// مولّدة آلياً بواسطة scripts/split-history.mjs — لا تُعدَّل يدوياً.
export default [{"id":1,"era":"before","t":"ولادة النبي محمد بن عبدالله صلى الله عليه وسلم .","s":"اختلفَ أهلُ السِّيَر والتَّاريخِ في تحديدِ يومِ وشهرِ وِلادتِه صلى الله عليه وسلم واتَّفقوا على أنَّ مِيلادَه صلى الله عليه وسلم كان يومَ الاثنينِ من عامِ الفيلِ.قال ابنُ القيِّم: \"لا خِلافَ أنَّه وُلِدَ صَلَّى اللَّهُ عَليهِ وسلَّم بجَوفِ مكَّة، وأنَّ مَولِدَه كان عامَ الفيلِ\". عنِ ابنِ عبَّاس رضِي الله عنهُما أنَّه قال: (وُلِدَ رسولُ الله صلى الله عليه وسلم عامَ الفيلِ)، وهو الَّذي لا يَشكُّ فيه"},{"id":2,"era":"before","t":"حادِثةُ شَقِّ صدرِ النَّبيِّ صلَّى الله عَليهِ وسلَّم الأُولى .","s":"عن أنسِ بنِ مالكٍ: أنَّ رسولَ الله صلَّى الله عَليهِ وسلَّم أتاهُ جبريلُ صلَّى الله عَليهِ وسلَّم وهو يلعبُ مع الغِلمانِ، فأخذهُ فصرعهُ، فشَقَّ عن قَلبِه، فاستخرجَ القلبَ، فاستخرجَ منه عَلَقَةً، فقال: هذا حَظُّ الشَّيطانِ منكَ، ثمَّ غسلهُ في طِسْتٍ من ذهبٍ بماءِ زمزمَ، ثمَّ لَأَمَهُ، ثمَّ أعادهُ في مكانِه، وجاء الغِلمانُ يَسعَون إلى أمِّه -يعني ظِئْرَهُ-فقالوا: إنَّ محمَّدًا قد قُتل، فاستقبلوه وهو"},{"id":3,"era":"before","t":"وفاة أم النبي آمنة بنت وهب وحضانة أم أيمن له صلى الله عليه وسلم .","s":"لمَّا بَلَغَ رسولُ الله صلَّى اللهُ عليه وسلَّم سِتَّ سنينَ، خرجَتْ به أُمُّه السيِّدةُ آمنةُ بنتُ وهبٍ إلى أخوالِه بني عَديِّ بن النَّجَّار تَزورُهم به، ومعه حاضِنَتُه أمُّ أيمنَ رَضي اللهُ عنها، وهم على بَعيرَين، فنَزَلَت به أُمُّه في دارِ النابغةِ عند قبرِ أبيه عبدِ الله بن عبدِ المُطَّلِب، فأقامَت به عند أخوالِه شهرًا، ثم رَجَعَت به أُمُّه إلى مكةَ، فلمَّا كانوا بالأبواءِ توُفِّيَت أُمُّه آمِن"},{"id":4,"era":"before","t":"كفالة عبد المطلب رسول الله صلَّى اللهُ عليه وسلَّم ومعرفته بشأنه .","s":"لمَّا تُوفِّيتِ آمنةُ والدةُ الرسول عليه الصلاة والسلام وعُمُرُه ستُّ سنواتٍ، صارت كَفالَتُه إلى جدِّه عبدِ المطلب بن هاشِمٍ، وكان عبدُ المطلب ذا شَرفٍ في قومِه وفَضلٍ، وكانت قُريشٌ تُسمِّيه الفضلَ؛ لسَماحتِه وفضلِه، وتولَّى أمْرَ الرِّفادةِ والسِّقايةِ بعد موتِ أبيه هاشمِ بن عبد مَنافٍ. وكان عبدُ المطلب يُحِبُّ حفيدَه مُحمَّدًا حبًّا عظيمًا، ويُقدِّمُه على سائِرِ بنيه، ويَرِقُّ عليه أكثَرَ مِن رِ"},{"id":5,"era":"before","t":"وفاة عبد المطلب ووصيته لأبي طالب برسول الله صلَّى اللهُ عليه وسلَّم .","s":"لمَّا بَلَغَ رسولُ الله صلَّى اللهُ عليه وسلَّم ثَمانيَ سنواتٍ توُفِّي جدُّه عبد المطلب. وكان عبدُ المُطَّلِب لمَّا حَضَرته الوفاةُ أوصى ابنَه أبا طالبٍ بحِفظِ رسول اللَّه صلَّى اللهُ عليه وسلَّم، وحياطَتِه، والقيامِ عَليهِ، وأوصَى به إلى أبي طالِبٍ؛ لأنَّ عبدَ الله -والِدَ النبيِّ صلَّى اللهُ عليه وسلَّم- وأبا طالبٍ كانا لأُمٍّ واحدةٍ، فلمَّا مات عبدُ المطلب كان أبو طالِبٍ هو الذي يَلي أمْرَ رسول"},{"id":6,"era":"before","t":"سفر النبي صلَّى اللهُ عليه وسلَّم مع عمه أبي طالب إلى الشام .","s":"لمَّا تمَّ للنبيِّ صلَّى اللهُ عليه وسلَّم من العُمُرِ اثنَتا عَشْرةَ سنةً، سافر عمُّه أبو طالِبٍ إلى الشَّامِ في رَكبٍ للتِّجارةِ، فأخَذهُ معه. ولمَّا نزلَ الرَّكبُ (بُصرَى) مرّوا على راهِبٍ هناك يُقال له (بَحيرَا)، وكان عليمًا بالإنجيلِ، خبيرًا بالنَّصرانيَّةِ، وهناك أبصرَ بَحيرَا النبيَّ صلَّى اللهُ عليه وسلَّم، فجَعَلَ يتأمَّلُه ويُكلِّمُه، ثم الْتَفَتَ إلى أبي طالبٍ فقال له: ما هذا الغُلامُ م"},{"id":7,"era":"before","t":"حرب الفِجَار، وشهود النبي صلَّى اللهُ عليه وسلَّم لها .","s":"لمَّا بلغَ رسولُ الله صلَّى اللهُ عليه وسلَّم أربعَ عشرةَ سنةً أو خمسَ عشرةَ سنةً هاجت حربُ الفِجارِ بين قُريشٍ ومَن معها مِن كِنانةَ وبين قَيسِ عَيلانَ، وهو من أعظمِ أيَّامِ العربِ، وكان الذي أهاجَها: أنَّ عُروةَ الرَّحَّالَ بنَ عتبة بن ربيعةَ أجارَ لَطيمةً للنُّعمانِ بن المنذرِ، فقال له البَرَّاضُ بنُ قيسٍ -أحدُ بني ضَمْرةَ بنِ بكرِ بنِ عبدِ مناةَ بنِ كنانةَ-: أتُجيرُها على كِنانةَ؟! قال: نعم، و"},{"id":8,"era":"before","t":"حِلْفُ الفُضولِ بين قبائل قريش .","s":"وقع حِلفُ الفُضولِ في الشَّهرِ الحرامِ, تَداعتْ إليهِ قبائلُ من قُريشٍ, بَنو هاشمٍ، وبَنو المطَّلبِ، وأسدُ بنُ عبدِ العُزَّى، وزُهْرَةُ بنُ كِلابٍ، وتَيْمُ بنُ مُرَّةَ، فاجتمعوا في دارِ عبدِ الله بنِ جُدْعانَ التَّيميِّ؛ لِسِنِّه وشَرفِه، فتعاقدوا وتعاهدوا على ألَّا يجدوا بمكَّة مظلومًا من أهلِها وغيرِهم من سائرِ النَّاس إلَّا قاموا معه، وكانوا على مَن ظلمهُ حتَّى تُرَدَّ عَليهِ مَظلمتُه، وشهِد هذ"},{"id":9,"era":"before","t":"زَواجُ النَّبيِّ صلَّى الله عَليهِ وسلَّم من خَديجةَ بنتِ خُويلدٍ رضِي الله عنها .","s":"اختلفتْ الأقوالُ في عُمُرِ النَّبيِّ صلى الله عليه وسلم وعُمُرِ خَديجةَ حين زَواجهِما، فقِيل: كان خمسًا وعِشرين. وقِيل: سبعًا وعِشرين. وقِيل: ثلاثين. وقِيل: غيرَ ذلك، وأمَّا عُمُرُ خَديجةَ فكذلك تضاربتِ الأقوالُ بين خمسٍ وثلاثين وأربعين وغيرِ ذلك، لمَّا سمِعتْ خَديجةُ رضي الله عنها بالنَّبيِّ صلى الله عليه وسلم وبأمانتِه و أخلاقِه الكريمةِ، فقد جاء في رِوايةٍ: أنَّ أُختَ خَديجةَ قد اسْتَكْرَتْ رسو"},{"id":10,"era":"before","t":"سفر النبي صلَّى اللهُ عليه وسلَّم للمرة الثانية إلى الشام .","s":"لمَّا بلغَ رسولُ الله صلَّى اللهُ عليه وسلَّم خَمسًا وعِشرين سنةً وليس له بمكَّةَ اسمٌ إلا \"الأمينُ\"؛ لِمَا تكامَلَ فيه من خِصال الخير، قال له عمُّه أبو طالِبٍ: \"يا ابنَ أخي، أنا رجلٌ لا مالَ لي، وقد اشتَدَّ الزَّمانُ علينا، وألَحَّت علينا سِنونَ مُنكَرةٌ، وليس لنا مادَّةٌ ولا تجارةٌ، وهذه عيرُ قومِك قد حَضَرَ خروجُها إلى الشامِ، وخديجةُ بِنتُ خوَيلدٍ تبعَثُ رِجالًا من قومِك في عيرانِها، فيتَّجِرو"},{"id":11,"era":"before","t":"النَّبيُّ صلَّى الله عَليهِ وسلَّم يضعُ الحَجَرَ الأَسودَ في مكانِه في الكعبةِ .","s":"عن مُجاهدٍ، عن مَولاهُ أنَّه حدَّثه: أنَّه كان فيمن يَبني الكعبةَ في الجاهليَّةِ... قال: فَبَنَيْنا حتَّى بلغنا موضعَ الحَجَرِ وما يَرى الحَجَرَ أحدٌ، فإذا هو وَسْطَ حِجارتِنا مِثلَ رأسِ الرَّجلِ، يَكادُ يَتراءى منه وجهُ الرَّجلِ، فقال بطنٌ من قُريشٍ: نحن نَضعهُ. وقال آخرون: نحن نَضعهُ. فقالوا: اجعلوا بينكم حَكَمًا. قالوا: أوَّلُ رجلٍ يَطلُعُ مِنَ الفَجِّ. فجاء النَّبيُّ صلى الله عليه وسلم، فقالوا"},{"id":12,"era":"before","t":"أوَّلُ نُزولِ الوَحيِ ونُبوءةُ النَّبيِّ صلَّى الله عَليهِ وسلَّم .","s":"كان أوَّلَ ما بُدِئ بهِ الوحيُ هو الرُّؤيا الصَّادقةُ في النَّومِ، وكان لا يَرى رُؤيا إلا جاءتْ مِثلَ فَلَقِ الصُّبحِ، ثمَّ إنَّه صلى الله عليه وسلم حُبِّبَ إليهِ الخَلاءُ، فكان يَخلو في غارِ حِراءٍ ويَتَحَنَّثُ فيهِ مُتعبِّدًا، حتَّى جاءهُ جبريلُ عَليهِ السَّلامُ وهو في الغارِ بقولِه تعالى: {اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ (1) خَلَقَ الْإِنْسَانَ مِنْ عَلَقٍ (2) اقْرَأْ وَرَبُّكَ الْأَكْرَ"},{"id":13,"era":"before","t":"فُتورُ الوحيِ عن رسولِ الله صلَّى الله عَليهِ وسلَّم .","s":"فَتَرَ الوحيُ عن رسولِ الله صلى الله عليه وسلم فَترةً مِنَ الزَّمنِ, حتَّى شَقَّ ذلك عَليهِ فأحزنهُ، فجاءهُ جبريلُ بسورةِ الضُّحى يُقسِمُ له رَبُّهُ -وهو الذي أكرمهُ بما أكرمهُ بهِ- ما وَدَعَهُ, فقد روى البخاري في صحيحه من حديث جندب بن عبدالله رضي الله عنه قال: احْتَبَسَ جِبْرِيلُ صَلَّى اللهُ عليه وسلَّمَ علَى النبيِّ صَلَّى اللهُ عليه وسلَّمَ، فَقالتِ امْرَأَةٌ مِن قُرَيْشٍ -وهي أمُّ جميلٍ أَرْو"},{"id":14,"era":"before","t":"أوَّلُ النَّاسِ إيمانًا بالله ورسولِه .","s":"كان أوَّلَ مَنْ آمنَ بالله ورسولِه خَديجةُ بنتُ خويلدٍ زوجتُه صلى الله عليه وسلم، وأبو بكرٍ الصِّدِّيقُ، وعليُّ بنُ أبي طالبٍ، ثمَّ أَسلمَ زيدُ بنُ حارثةَ مولى رسولِ الله صلى الله عليه وسلم. وقد أَسلمَ بدُعاءِ أبي بكرٍ الصِّدِّيقِ عُثمانُ بنُ عفَّانَ، والزُّبيرُ بنُ العوَّامِ، وسعدُ بنُ أبي وقَّاصٍ، وطَلحةُ بنُ عُبيدِ الله، وعبدُ الرَّحمنِ بنُ عوفٍ, ثمَّ أَسلمَ أبو عُبيدةَ بنُ الجرَّاحِ، وأبو سَلم"},{"id":15,"era":"before","t":"ما لقِي الصَّحابةُ من إيذاءِ قُريشٍ .","s":"كان أوَّلَ مَن أظهرَ إسلامَه سبعةٌ: رسولُ الله صلى الله عليه وسلم، وأبو بكرٍ، وعمَّارٌ، وأمُّهُ سُميَّةُ، وصُهيبٌ، وبلالٌ، والمقدادُ، فأمَّا رسولُ الله صلى الله عليه وسلم فمنعهُ الله بعمِّه أبي طالبٍ، وأمَّا أبو بكرٍ فمنعهُ بقومِه، وأما سائرهُم فأخذهُم المشركون فألبسوهُم أَدراعَ الحديدِ وصَهروهُم في الشَّمسِ، فما منهُم إلَّا مَن واتاهُم فيما أرادوا وأَوْهَمهُم بذلك إلَّا بلالًا، فإنَّه هانتْ عَليه"},{"id":16,"era":"before","t":"طلب قريش من أبي طالب أن يكف عنهم رسول الله صلى الله عليه وسلم .","s":"كان رسولُ الله صلَّى اللهُ عليه وسلَّم يدْعو إلى الله تعالى في كُلِّ أحوالِهِ؛ ليلًا ونهارًا، وسِرًّا وجهرًا، لا يَصرِفُه عن ذلك صارِفٌ ولا يَرُدُّه عن ذلك رادٌّ، ولا يَصُدُّه عن ذلك صادٌّ، يَتبَعُ الناسَ في أنديَتِهم، ومَجامِعِهم ومَحافِلِهم وفي المَواسمِ، ومَواقفِ الحَجِّ؛ يدعو مَن لَقيَه مِن حرٍّ وعبدٍ، وضعيفٍ وقويٍّ، وغنيٍّ وفقيرٍ.وتسلَّط عليه وعلى مَنِ اتَّبَعه كفارُ قَومِه من مُشرِكي قُريشٍ،"},{"id":17,"era":"before","t":"الهِجرةُ الأُولى إلى الحَبشةِ .","s":"قالتْ أمُّ سَلمةَ رضي الله عنها: لمَّا ضاقتْ علينا مكَّة، وأوذِيَ أصحابُ رسولِ الله صلى الله عليه وسلم وفُتنوا، ورَأَوْا ما يُصيبهُم مِنَ البلاءِ والفِتنةِ في دينهِم، وأنَّ رسولَ الله صلى الله عليه وسلم لا يستطيعُ دفعَ ذلك عنهُم، وكان رسولُ الله صلى الله عليه وسلم في مَنَعَةٍ من قومهِ وعمِّه، لا يَصِلُ إليه شيءٌ ممَّا يَكرهُ ممَّا ينالُ أصحابَه، فقال لهم رسولُ الله صلى الله عليه وسلم: إنَّ بأرضِ ا"},{"id":18,"era":"before","t":"إسلام حمزة بن عبد المطلب رَضي اللهُ عنه .","s":"في أواخِرِ السنةِ السَّادسةِ من النُّبوَّةِ أسلم حَمزةُ بنُ عبد المطلب رَضي اللهُ عنه. وسببُ إسلامِه: أنَّ أبا جَهلٍ مرَّ برسولِ الله صلَّى اللهُ عليه وسلَّم يومًا عند الصَّفا، فآذاه ونال منه، ورسولُ الله صلَّى اللهُ عليه وسلَّم ساكِتٌ لا يُكلِّمُه، ثم ضَرَبه أبو جَهلٍ بحَجَرٍ في رأسِه فشَجَّه حتى نَزَف منه الدَّمُ، ثم انصَرَف عنه إلى نادي قُرَيشٍ عند الكعبةِ فجَلَس معهم، وكانت مولاةٌ لعَبدِ الله "},{"id":19,"era":"before","t":"الهِجرةُ الثَّانيةُ إلى الحَبشةِ .","s":"بلغ المهاجرين في الحَبشةِ أنَّ قُريشًا قد أسلمتْ، فرجعوا إلى مكَّة في شوَّالٍ من نفسِ السَّنةِ التي هاجروا فيها، فلمَّا كانوا دون مكَّة ساعةً من نهارٍ وعرفوا جلية الأمرِ رجع منهم مَنْ رجع إلى الحَبشةِ، ولم يدخلْ في مكَّة مِن سائرهِم أحدٌ إلَّا مُستخفِيًا، أو في جِوارِ رجلٍ من قُريشٍ‏.‏ ثم اشتدَّ عليهِم وعلى المسلمين البلاءُ والعذابُ من قُريشٍ، وسَطَتْ بهِم عشائرُهُم، فقد كان صعبًا على قُريشٍ ما بل"},{"id":20,"era":"before","t":"إِسلامُ عُمَرَ رضِي الله عنهُ .","s":"أخرج الترمذي في سننه عن عبدالله بن عمر رضي الله عنهما أنَّ رسول الله صلى الله عليه وسلم قال: ((اللهم أَعِزَّ الإسلامَ بأَحَبِّ هذين الرجُلَيْنِ إليك بأبي جهلٍ أو بعمرَ بنِ الخطابِ قال وكان أَحَبَّهُما إليه عمرُ)) وروى أهل السِّير أنَّ عمر خرج يومًا مُتوشِّحًا سَيفَهُ يُريدُ القضاءَ على النَّبيِّ صلى الله عليه وسلم، فلقِيهُ رجلٌ فقال: أين تعمدُ يا عُمَرُ؟ قال: أريدُ أنْ أقتُلَ محمَّدًا. قال: كيف تأ"},{"id":21,"era":"before","t":"إسلام الطّفيل بن عمرو الدوسي رَضي اللهُ عنه .","s":"كانت قُريشٌ تُحذِّر منَ الاستِماعِ للنبيِّ صلَّى اللهُ عليه وسلَّم، فلمَّا قَدِم الطُّفَيلُ بن عمرٍو مكةَ مَشَى إليه رجالٍ من قُرَيشٍ، وكان الطُّفَيلُ رجلًا شَريفًا شاعِرًا لَبيبًا، فقالوا له: \"يا طُفَيلُ، إنَّك قَدِمتَ بلادَنا، وهذا الرجلُ الذي بين أظهُرِنا قد أعضَلَ -اشتَدَّ أمرُه- بنا، وقد فرَّق جماعَتَنا، وشتَّت أمْرَنا، وإنَّما قَولُه كالسِّحرِ يُفرِّق بين الرَّجلِ وبين أبيه، وبين الرَّجُلِ و"},{"id":22,"era":"before","t":"حصار قريش للمسلمين في شعب أبي طالب .","s":"لمَّا عَزمتْ قُريشٌ أنْ تَقتُلَ رسولَ الله صلى الله عليه وسلم أجمع بَنو عبدِ المُطَّلِبِ أمرَهم على أنْ يُدخِلوا رسولَ الله صلى الله عليه وسلم شِعبَهم ويَحموهُ فيه، فعن أبي هُريرةَ رضي الله عنه، قال: قال النَّبيُّ صلى الله عليه وسلم مِنَ الغَدِ يومَ النَّحْرِ، وهو بمِنًى: «نحن نازِلون غدًا بِخَيْفِ بني كِنانةَ؛ حيث تقاسموا على الكُفرِ» يعني ذلك المُحَصَّبَ، وذلك أنَّ قُريشًا وكِنانةَ، تحالفتْ على "},{"id":23,"era":"before","t":"نَقْضُ قريش لمِيثاقِ الصَّحيفةِ .","s":"بعدَ مُرورِ عامينِ أو ثلاثةِ أَعوامٍ مِنَ الحِصارِ الظَّالمِ في شِعْبِ أبي طالبٍ نُقِضتْ الصَّحيفةُ وفُكَّ الحِصارُ؛ وذلك أنَّ قُريشًا كانوا بين راضٍ بهذا الميثاقِ وكارهٍ له، فسعى في نَقْضِ الصَّحيفةِ مَنْ كان كارهًا لها, وكان القائمُ بذلك هشامُ بنُ عَمرٍو مِن بني عامرِ بنِ لُؤَيٍّ, وكان يَصِلُ بني هاشمٍ في الشِّعْبِ مُستَخفِيًا باللَّيلِ بالطَّعامِ, فإنَّه ذهب إلى زُهيرِ بنِ أبي أُمَيَّةَ المخزوم"},{"id":24,"era":"before","t":"وَفاةُ أمِّ المؤمنين خَديجةَ بنتِ خويلدٍ رضِي الله عنها .","s":"هي خَديجةُ بنتُ خويلدِ بنِ أسدِ بنِ عبدِ العُزَّى بنِ قُصَيِّ بنِ كِلابٍ، مِن خيرِ نِساءِ الدُّنيا، أتى جبريلُ النَّبيَّ صلى الله عليه وسلم فقال: يا رسولَ الله، هذه خديجةُ قد أتتْكَ بإناءٍ فيه إدامٌ -أو طعامٌ أو شرابٌ- فإذا أتتْكَ فَاقرأْ عليها السَّلامَ مِن رَبِّها ومِنِّي، وبَشِّرها بِبيتٍ في الجنَّةِ من قَصبٍ لا صَخَبَ فيهِ ولا نَصَبَ. كانتْ خَديجةُ أوَّلَ مَنْ أَسلمَ بالنَّبيِّ صلى الله عليه و"},{"id":25,"era":"before","t":"خُروجُ رسولِ الله صلَّى الله عَليهِ وسلَّم إلى الطَّائفِ .","s":"خرج النَّبيُّ صلى الله عليه وسلم إلى الطَّائفِ، وهي تَبعُد عن مكَّة نحوَ سِتِّينَ مِيلًا، سارها ماشِيًا على قَدميهِ جِيئةً وذِهابًا، ومعه مولاهُ زيدُ بنُ حارثةَ، وكان كُلَّما مَرَّ على قَبيلةٍ في الطَّريقِ دعاهُم إلى الإسلامِ، فلمْ تُجبْ إليهِ واحدةٌ منها, فلمَّا انتهى إلى الطَّائفِ عَمَدَ إلى رُؤسائِها فدعاهُم فلمْ يَستجيبوا له, فأقام بين أهلِ الطَّائفِ عشرةَ أيَّامٍ، لا يَدَعُ أحدًا مِنْ أشرافهِ"},{"id":26,"era":"before","t":"إِسلامُ الجِنِّ وتَوافُدهُم على النَّبيِّ صلَّى الله عَليهِ وسلَّم  .","s":"لمَّا انصرف النَّبيُّ صلى الله عليه وسلم مِنَ الطَّائفِ راجعًا إلى مكَّة، حتَّى إذا كان بِنَخْلَةَ، قام من جوفِ اللَّيلِ يُصلِّي، فمَرَّ بهِ النَّفرُ مِنَ الجِنِّ الذين ذكَرهُم الله تعالى، وكانوا سَبعةَ نَفَرٍ من جِنِّ أهلِ نَصِيبِينَ، فاستمعوا لِتِلاوةِ الرَّسولِ صلى الله عليه وسلم، فلمَّا فرغ من صلاتهِ، وَلَّوْا إلى قَومهِم مُنذِرين، قد آمنوا وأجابوا إلى ما سمِعوا، وفيهِم نزل قولُه تعالى: (وَإِذ"},{"id":27,"era":"before","t":"وَفاةُ أبي طالبٍ عَمِّ النَّبيِّ صلَّى الله عَليهِ وسلَّم .","s":"بعدَ أنِ اشْتدَّ المرضُ على أبي طالبٍ عَمِّ النَّبيِّ صلى الله عليه وسلم وهو الذي كفله صغيرًا، وآزرَهُ كبيرًا، وناصرَهُ على دَعوتهِ، وحَماهُ من عَوادي المشركين، دخل عَليهِ النَّبيُّ صلى الله عليه وسلم وعندهُ أبو جَهْلٍ، فقال: ( أي عَمِّ، قُلْ: لا إلَه إلَّا الله، كلمةً أُحاجُّ لك بها عندَ الله). فقال أبو جَهْلٍ وعبدُ الله بنُ أبي أُمَيَّةَ: يا أبا طالبٍ، تَرغبُ عن مِلَّةِ عبدِ المُطَّلبِ؟ فلم يَزا"},{"id":28,"era":"before","t":"زَواجُ النَّبيِّ صلَّى الله عَليهِ وسلَّم من سَوْدَةَ بنتِ زَمْعَةَ رضِي الله عنها .","s":"بعدَ وفاةِ أمِّ المؤمنين خَديجةَ بنتِ خويلدٍ رضي الله عنها والتي كانت مِن نِعَمِ الله الجَليلةِ على رسولِ الله صلى الله عليه وسلم، تَزوَّج رسولُ الله صلى الله عليه وسلم سَودةَ بنتَ زَمْعَةَ بنِ قَيسِ بنِ عبدِ شمسِ بنِ عبدِ وُدِّ بنِ نصرِ بنِ مالكِ بن حِسْلِ بنِ عامرِ بن لُؤَيٍّ، القُرشيَّةَ، تَزوَّجها بمكَّة قبلَ الهِجرةِ، وكانت ممَّن أسلمَ قديمًا, وهاجرتْ الهِجرةَ الثَّانيةَ إلى الحَبشةِ، وكان زو"},{"id":29,"era":"before","t":"بداية دخول الأنصار في الإسلام .","s":"لمَّا أراد الله عزَّ وجلَّ إظهارَ دينهِ، وإعزازَ نَبيِّهِ صلى الله عليه وسلم، وإنجازَ مَوعِدِه له خرج رسولُ الله صلى الله عليه وسلم في مَوسمِ الحجِّ يَعرِضُ نَفْسَهُ على قبائلِ العربِ، كما كان صنع في كُلِّ مَوسمٍ. فبينما هو عند العَقبةِ لَقِيَ رهطًا مِنَ الخَزرجِ أراد الله بهم خيرًا فقال لهم مَن أنتم؟ قالوا: نَفرٌ مِنَ الخَزرجِ، قال أمِن موالي يَهودَ؟ قالوا: نعم. قال أفلا تَجلِسون أُكلِّمكُم؟ قالو"},{"id":30,"era":"before","t":"زَواجُ النَّبيِّ مِن عائشةَ بنتِ أبي بكرٍ الصِّدِّيقِ رضِي الله عنهُما .","s":"تَزوَّج رسولُ الله صلى الله عليه وسلم عائشةَ الصِّدِّيقةَ رضي الله عنها وهي بنتُ سِتِّ سِنينَ, وبَنى بها بالمدينةِ في شَوَّال في السَّنةِ الثانية مِن الهِجرةِ وهي بنتُ تِسعِ سِنينَ, وكانت أَحظى أزواجِه عنده وأحبَّهُم إليه, ولمْ يتزوَّجْ بِكرًا غيرَها."},{"id":31,"era":"before","t":"بَيْعةُ العَقبةِ الأولى  .","s":"عن عُبادةَ بنِ الصَّامتِ رضي الله عنه أحدُ النُّقَباءِ ليلةَ العَقبةِ: أنَّ رسولَ الله صلَّى الله عليه وعلى آله وصَحبِه وسلَّم قال وحولَه عِصابةٌ مِن أصحابهِ: (بايِعوني على أنْ لا تُشرِكوا بالله شيئًا، ولا تَسرِقوا، ولا تَزنوا، ولا تَقتُلوا أولادَكُم، ولا تَأتوا ببُهْتانٍ تَفتَرونهُ بين أيديكُم وأرجُلِكُم، ولا تَعْصوا في مَعروفٍ، فمَن وَفَّى منكم فأجرُهُ على الله، ومَن أصاب مِن ذلك شيئًا فعُوقِبَ "},{"id":32,"era":"before","t":"الإسراءُ والمِعراجُ وفرضُ الصَّلواتِ الخمسِ .","s":"في هذه الحادثةِ العظيمةِ رأى النَّبيُّ صلى الله عليه وسلم الأنبياءَ، ورأى سِدرةَ المُنتهى وغيرَ ذلك مِنَ الآياتِ العظيمةِ، وفيها فُرِضتْ الصَّلواتُ الخمسُ، وهو أمرٌ تتَّفِقُ عليه رِواياتُ الصَّحيحينِ، وقد كذَّبتْ قُريشٌ وقوعَ حادثةِ الإسراءِ والمِعراجِ، وهذا أمرٌ اتَّفقتْ عليه رِواياتُ الصَّحيحينِ أيضًا، قال رسولُ الله صلى الله عليه وسلم:\"لقد رأيتُني في الحِجْرِ وقُريشٌ تسألُني عن مَسْرايَ، فسألَت"},{"id":33,"era":"before","t":"هِجرةُ أبي سَلمةَ وأمِّ سَلمةَ رضي الله عنهما .","s":"كان أبو سَلمةَ عبدُ الله بنُ عبدِ الأسدِ أوَّلَ مَن هاجر إلى المدينةِ مِن أصحابِ رسولِ الله صلى الله عليه وسلم مِنَ المُهاجرين مِن قُريشٍ مِن بني مَخزومٍ، وكانتْ هِجرتُه إليها بعدَ بَيعةِ العَقبةِ الأولى، وقبلَ بَيعةِ العَقبةِ الثَّانيةِ، حين آذتْهُ قُريشٌ بعدَ مَرجعِهِ مِنَ الحَبشةِ، فعزم على الرُّجوعِ إليها، ثمَّ بَلغهُ أنَّ بالمدينةِ لهم إخوانًا، فعزم في الهِجرةِ إليها.قالتْ أمُّ سَلمةَ: لمَّا "},{"id":34,"era":"before","t":"انتِشارُ الإسلامِ في يَثْرِبَ بعدَ العَقبةِ الأولى .","s":"كتب الأنصارُ إلى رسولِ الله صلى الله عليه وسلم بعدَ بَيعةِ العَقبةِ الأولى أن يبعثَ لهم مَن يُصلِّي بهم ويُقريهِم القُرآنَ، فبعث رسولُ الله صلى الله عليه وسلم لهم مُصعبَ بنَ عُميرٍ, فكان في ضِيافةِ أَسعدَ بنِ زُرارةَ, وأخذ يدعو إلى الإسلامِ، وانتشر الإسلامُ في أهلِ يَثْرِبَ حتَّى لمْ يَبْقَ بيتٌ في يَثْرِبَ إلَّا وفيه مُسلمٌ أو مُسلمةٌ، وكان ممَّن أَسلمَ على يدِهِ سَيِّدا الأَوسِ سعدُ بنُ مُعاذٍ، "},{"id":35,"era":"before","t":"بَيعةُ العَقبةِ الثَّانيةِ .","s":"عن جابرٍ قال: (مكث رسولُ الله صلى الله عليه وسلم بمكَّةَ عشرَ سِنينَ يَتْبَعُ النَّاسَ في منازلِهم بعُكاظٍ ومَجَنَّةَ، وفي المَواسمِ بمِنًى، يقول: مَن يُؤْوِيني؟ مَن يَنصُرني حتَّى أُبَلِّغَ رسالةَ رَبِّي وله الجَنَّةُ. حتَّى إنَّ الرَّجلَ لَيخرُجُ مِنَ اليمنِ أو مِن مُضَرَ، فيأتيه قومُه فيقولون: احْذرْ غُلامَ قُريشٍ لا يَفْتِنُكَ. ويمشي بين رجالِهم وهُم يُشيرون إليه بالأصابعِ حتَّى بعثنا الله إلي"},{"id":36,"era":"before","t":"مُعجِزةُ انشِقاقِ القَمرِ .","s":"عن عبدِ الله بنِ مَسعودٍ رضي الله عنه، قال: انشقَّ القَمرُ على عهدِ رسولِ الله صلى الله عليه وسلم شِقَّتينِ، فقال النَّبيُّ صلى الله عليه وسلم: «اشْهَدوا». وعن أنسِ بنِ مالكٍ رضي الله عنه، «أنَّ أهلَ مكَّة سألوا رسولَ الله صلى الله عليه وسلم أنْ يُرِيَهُم آيةً، فأراهُم القَمرَ شِقَّتينِ، حتَّى رَأَوْا حِراءً بينهُما» وفي صحيحِ مُسلمٍ عن عبدِ الله بنِ مَسعودٍ قال: انشقَّ القَمرُ على عهدِ رسولِ الله"},{"id":37,"era":"c1","t":"إسلام عبد الله بن سلَام رَضي اللهُ عنه .","s":"كان عبدُ الله بن سلامٍ رَضي اللهُ عنه حَبْرًا من أحبارِ يَهودَ، عالِمًا، قال: لمَّا سَمِعتُ برسولِ الله صلَّى اللهُ عليه وسلَّم عَرَفتُ صِفَتَه واسمَه وزَمانَه الذي كنا نتوقَّعُ له، فكنتُ مُسِرًّا لذلك، صامِتًا عليه، حتى قَدِمَ رسولُ الله صلَّى اللهُ عليه وسلَّم المدينةَ، فلمَّا نزل بقُباءٍ، في بني عَمرِو بنِ عَوفٍ، أقبل رجلٌ حتى أخبَرَ بقُدومِه، وأنا في رأسِ نَخلةٍ لي أعمَلُ فيها، وعمَّتي خالِدةُ"},{"id":38,"era":"c1","t":"معاهدة النبي صلَّى اللهُ عليه وسلَّم مع يهود .","s":"قال ابن إسحاق: «كتب رسول الله- صلى الله عليه وسلم- كتابًا بين المهاجرين والأنصار وادع فيه يهود وعاهدهم وأقرّهم على دينهم وأموالهم واشترط عليهم وشرط لهم» . أي لمّا امتنعوا من إتباعه، وذلك قبل الإذن بالقتال وأخذ الجزية ممن أبى الإسلام، وقد أبى عامَّتُهم إلا الكفر. وكانوا ثلاث قبائل: بنو قينقاع، وبنو النضير، وبنو قريظة، وحاربه الثلاثة، فمنَّ على بني قينقاع، وأجلى بني النضير، وقتل بني قريظة، وسبى ذريت"},{"id":39,"era":"c1","t":"مَشروعِيَّةُ الأَذانِ .","s":"عنِ ابنِ عُمَرَ قال: كان المسلمون حين قَدِموا المدينةَ يجتَمِعون فيتَحيَّنون الصَّلواتِ، وليس يُنادي بها أحدٌ، فتَكلَّموا يومًا في ذلك فقال بعضُهم: اتَّخِذوا ناقوسًا مِثلَ ناقوسِ النَّصارى، وقال بعضُهم: قَرْنًا مِثْلَ قَرْنِ اليَهودِ. وقال عبدُ الله بنُ زيدٍ: (لمَّا أَمَر رسولُ الله صلى الله عليه وسلم بالنَّاقوسِ يُعملُ لِيُضرَبَ به للنَّاسِ لِجَمْعِ الصَّلاةِ طاف بي وأنا نائمٌ رجلٌ يَحمِلُ ناقوسً"},{"id":40,"era":"c1","t":"هِجرةُ الصَّحابةِ إلى المدينةِ .","s":"لمَّا تَمَّتْ بَيعةُ العَقبةِ أمرَ رسولُ الله صلى الله عليه وسلم مَن كان معه بالهِجرةِ إلى المدينةِ، فخرجوا أَرسالًا، كان مِنَ السَّابقين للهِجرةِ بعدَ العَقبةِ الثَّانيةِ مُصعبُ بنُ عُميرٍ, ثمَّ عامرُ بنُ رَبيعةَ حَليفُ بن بني عَدِيِّ بنِ كعبٍ، معه امرأتُه ليلى بنتُ أبي حَثْمَةَ بنِ غانمٍ، ثمَّ عبدُ الله بنُ جَحْشٍ بأهلِهِ وأخيهِ عبدِ بنِ جَحْشٍ أبي أحمدَ، وكان ضَريرًا، وكان منزلُهما ومنزلُ أبي س"},{"id":41,"era":"c1","t":"اجتماعُ المُشركين في دارِ النَّدوَةِ واتِّفاقُهم على قَتلِ النَّبيِّ صلَّى الله عليه وسلَّم .","s":"لمَّا رَأى المُشركون أنَّ أصحابَ رسولِ الله صلى الله عليه وسلم قد تَجهَّزوا وخرجوا، وحملوا وساقوا الذَّراريَّ والأطفالَ والأموالَ إلى الأوسِ والخزرجِ في يَثْرِبَ، أصابتهُم الكآبةُ والحزنُ، وساوَرهُم القلقُ والهَمُّ، فاجتمع طواغيتُ مكَّةَ في دارِ النَّدوَةِ لِيتَّخِذوا قرارًا حاسمًا في هذا الأمرِ. وكان اجتماعُهُم بعدَ شَهرينِ ونصفِ تقريبًا مِن بَيعةِ العَقبةِ، وتوافد إلى هذا الاجتماعِ جميعُ نُوَّاب"},{"id":42,"era":"c1","t":"هِجرةُ الرَّسولِ صلَّى الله عليه وسلَّم وأبي بكرٍ رضِي الله عنه إلى المدينةِ .","s":"عن عائشةَ رضي الله عنها قالت: قال النَّبيُّ صلى الله عليه وسلم للمُسلمين: «إنِّي أُريتُ دارَ هِجرتِكُم ذاتَ نَخلٍ بين لابَتَيْنِ». وهُما الحَرَّتانِ، فهاجر مَن هاجر قِبَلَ المدينةِ، ورجع عامَّةُ مَن كان هاجر بأرضِ الحَبشةِ إلى المدينةِ، وتَجهَّز أبو بكرٍ قِبَلَ المدينةِ، فقال له رسولُ الله صلى الله عليه وسلم: «على رِسْلِكَ، فإنِّي أرجو أن يُؤذنَ لي». فقال أبو بكرٍ: وهل ترجو ذلك بأبي أنت؟ قال: «نعم"},{"id":43,"era":"c1","t":"بِناءُ مَسجدِ قُباءٍ .","s":"لَبِثَ رسولُ الله صلى الله عليه وسلم في بني عَمرِو بنِ عَوفٍ بِقُباءٍ بِضعَ عشرةَ ليلةً، وأسَّسَ فيها المسجدَ الذي أُسِّسَ على التَّقوىَ، وصلَّى فيه رسولُ الله صلى الله عليه وسلم."},{"id":44,"era":"c1","t":"بِناءُ المسجدِ النَّبوِيِّ .","s":"ركِب رسولُ الله صلى الله عليه وسلم راحِلتَه مِن قُباءٍ فسار يمشي معه النَّاسُ حتَّى برَكتْ عند مسجدِ الرَّسولِ صلى الله عليه وسلم بالمدينةِ، وهو يُصلِّي فيه يَومئذٍ رجالٌ مِنَ المسلمين، وكان مِرْبَدًا للتَّمرِ، لِسُهيلٍ وسَهلٍ غُلامَينِ يَتيمَينِ في حَجْرِ أَسعدَ بنِ زُرارةَ، فقال رسولُ الله صلى الله عليه وسلم حين بَركتْ به راحِلتُه: «هذا إن شاء الله المنزِلُ». ثمَّ دَعا رسولُ الله صلى الله عليه و"},{"id":45,"era":"c1","t":"المُؤاخاةُ بين المُهاجِرين والأنصارِ .","s":"كان مِن آثارِ هِجرتِه صلى الله عليه وسلم وأصحابِه إلى المدينةِ تلك المُؤاخاةُ التي حَدثت بين المُهاجرين والأنصارِ رضي الله عنهم، حتَّى كان يَرِثُ بعضُهم بعضًا في أوَّلِ الأمرِ. فعنِ ابنِ عبَّاسٍ رضِي الله عنهما: {وَلِكُلٍّ جَعَلْنَا مَوَالِيَ} قال: «وَرَثَةً»: {وَالَّذِينَ عَاقَدَتْ أَيْمَانُكُمْ} قال: \" كان المُهاجِرون لمَّا  قَدِموا المدينةَ يَرِثُ المُهاجِرُ الأنصاريَّ دون ذَوِي رَحِمِهِ؛ لِلأُ"},{"id":46,"era":"c1","t":"سرية عبيدة بن الحارث بن المطلب إلى بطن رابغ .","s":"بَعَث النبيُّ صلَّى اللهُ عليه وسلَّم عُبيدةَ بنَ الحارِثِ بن عبد المطلب في سريَّةٍ إلي بطنِ رابِغٍ -هيَ ميقاتُ أهلِ الشامِ ومِصرَ وتركيا ومَن سَلَك طَريقَهم- في شعبان على رأسِ ثمانيةِ أشهُرٍ من الهجرةِ، وعَقَد له لواءً أبيضَ، وحَمَله مِسْطَحُ بن أُثاثةَ بن المطلبِ بن عبد مَنافٍ، وكانوا في ستِّين من المُهاجِرين ليس فيهم أنصاريٌّ، فلَقيَ أبا سُفيانَ بنَ حربٍ، وهو في مائتينِ على بطنِ رابِغٍ، على عشر"},{"id":47,"era":"c1","t":"سرية حمزة إلى سيف البحر .","s":"أرسل النبيُّ صلَّى اللهُ عليه وسلَّم سَريَّةً إلى سِيفِ -ساحِلِ- البحرِ، أمَّر عليها حمزةَ بنَ عبد المطلب، وبعثه في ثلاثين راكبًا مِن المُهاجِرين، وكان لِواءُ حَمزةَ أولَ لواءٍ عَقَده رسولُ الله صلَّى اللهُ عليه وسلَّم، وكان أبيضَ، وكان حامِلُه أبا مِرثَدٍ كَنَّازَ بنَ حُصينٍ الغَنويَّ رَضي اللهُ عنه، وكان هدفُ هذه السَّريَّةِ اعتِراضَ عِيرٍ لقُريشٍ جاءتْ من الشامِ، وفيها أبو جهلِ بنُ هشامٍ في ثلا"},{"id":48,"era":"c1","t":"سرية سعد بن أبي وقاص رضي الله عنه إلى الخَرّار .","s":"بَعثَ رسولُ الله صلَّى اللهُ عليه وسلَّم على رأسِ تِسعةِ أشهُرٍ من الهِجرةِ سعدَ بنَ أبي وقَّاصٍ رَضي اللهُ عنه في عِشرين من المُهاجِرين. وقيل: ثَمانيةٍ إلى الخَرَّارِ. وعَقَد له لواءً أبيضَ حَمَلَه المِقدادُ بنُ عَمرٍو رَضي اللهُ عنه. والخَرَّارُ: وادٍ يُتَوَصَّلُ منه إلى الجُحفةِ، وقد عَهِدَ صلَّى اللهُ عليه وسلَّم إليه ألَّا يُجاوِزَه؛ ليَعتَرِضَ عيرًا لقُريشٍ تَمرُّ بِهِم، فخَرَجوا يَمشون على "},{"id":49,"era":"c1","t":"غَزوةُ الأَبْواءِ (وَدَّانَ) ومُوادَعةُ بني ضَمْرَةَ .","s":"أوَّلُ ما غَزا النَّبيُّ صلَّى الله عليه وسلَّم الأَبْواءَ ثمَّ بُواطَ ثمَّ العُشَيْرَةَ. وهي قريةٌ مِن عَمَلِ الفُرْعِ، بينها وبين الجُحْفَةِ مِن جِهَةِ المدينةِ ثلاثةٌ وعِشرون مِيلًا. قِيلَ سُمِّيتْ بذلك لِما كان فيها مِنَ الوَباءِ، وهي غَزوةُ وَدَّانَ بِتَشديدِ الدَّالِ، قال إسحاقُ: خرج النَّبيُّ صلَّى الله عليه وسلَّم غازِيًا بِنَفْسِهِ حتَّى انتَهى إلى وَدَّانَ، وهي الأَبْواءُ. خرج مِنَ المدي"},{"id":50,"era":"c1","t":"غزوة بدر الأولى (وادي سفوان) .","s":"غزا رسولُ الله صلَّى اللهُ عليه وسلَّم غزوةَ بدرٍ الأولَى حتى بَلَغ واديَ سَفَوانَ؛ حيث خَرَج رسولُ الله صلَّى اللهُ عليه وسلَّم على رأسِ ثلاثةَ عَشَرَ شهرًا من مُهاجَرِه يَطلُب كُرزَ بنَ جابِرٍ الفِهريَّ، وحَمَل لِواءَه عليُّ بنُ أبي طالِبٍ رَضي اللهُ عنه، وكان أبيضَ، واستَخلَفَ على المدينةِ زيدَ بنَ حارِثةَ، وكان كُرزٌ قد أغار على سَرحِ المدينةِ -الإبِلِ والمَواشي التي تَسرَحُ للرَّعيِ بالغَداةِ"},{"id":51,"era":"c1","t":"غَزوةُ بُواطٍ بِقُربِ يَنْبُعَ .","s":"عن جابرٍ رضي الله عنه قال: سِرْنا مع رسولِ الله صلى الله عليه وسلم في غَزوةِ بَطْنِ بُواطٍ، وهو يَطلُبُ المَجْدِيَّ بنَ عَمرٍو الجُهَنيَّ، وكان النَّاضِحُ يَعْتَقِبُهُ مِنَّا الخمسةُ والسِّتَّةُ والسَّبعةُ، فَدارتْ عُقْبَةُ رجلٍ مِنَ الأنصارِ على ناضِحٍ له، فأناخَهُ فركِبَهُ، ثمَّ بَعثَهُ فتَلَدَّنَ عليه بَعضَ التَّلَدُّنِ، فقال له: شَأْ، لَعنَك الله. فقال رسولُ الله صلى الله عليه وسلم: «مَن هذا ا"},{"id":52,"era":"c1","t":"غَزوةُ العُشَيْرَةِ (الْعُسَيْرَةِ) .","s":"قِيلَ لِزيدِ بنِ أَرقمَ: \" كم غَزا النَّبيُّ صلى الله عليه وسلم مِن غَزوةٍ؟ قال: تِسعَ عشرةَ. قِيلَ: كم غَزوتَ أنت معه؟ قال: سبعَ عشرةَ. قِيلَ: فأَيُّهم كانت أوَّلَ؟ قال: الْعُسَيْرَةُ، أَوِ الْعُشَيْرُ. وقعت غَزوةُ العُشَيْرَةِ قبلَ وَقعةِ بدرٍ، سَلَكَ النَّبيُّ صلَّى الله عليه وسلَّم على نَقْبِ بني دِينارٍ، ثمَّ على فَيْفاءِ الخَبارِ فنزل تحت شجرةٍ ببَطْحاءَ ابنِ أَزهرَ يُقالُ لها: ذاتُ السَّاقِ"},{"id":53,"era":"c1","t":"سرية سعد بن أبي وقاص رضي الله عنه إلى رابغ .","s":"أخرَجَ ابنُ عَساكِرَ عن الزُّهريِّ قال: \"بَعَثَ رَسولُ الله صلَّى اللهُ عليه وسلَّم سَريَّةً فيها سعدُ بنُ أبي وقَّاصٍ رَضي اللهُ عنه إلى جانِبٍ مِن الحِجازِ يُدعَى (رابِغ)، فانكَفَأ المُشرِكون على المسلمين، فجاءَهم سعدُ بن أبي وقَّاصٍ رَضي اللهُ عنه يومَئذٍ بسِهامِهِ، وكان أوَّلَ مَن رَمَى في سبيلِ الله، وكان هذا أوَّلَ قِتالٍ في الإسلامِ\"."},{"id":54,"era":"c1","t":"سرية عبد الله بن جحش الأسدي إلى نخلة .","s":"بَعثَ رسولُ الله صلَّى اللهُ عليه وسلَّم رسولَه عبدَ الله بنَ جَحشٍ الأسَديَّ إلى نَخلةَ في رَجبٍ على رأسِ سَبعةَ عَشَرَ شَهرًا من الهِجرةِ في اثنَيْ عَشَرَ رَجلًا من المُهاجِرين، كلُّ اثنَينِ يَعتَقِبان على بَعيرٍ، فوَصَلوا إلى بَطنِ نَخلةَ يَرصُدون عيرًا لقُريشٍ، وفي هذه السَّريَّةِ سُمِّيَ عبدُ الله بنُ جَحشٍ أميرَ المؤمنين، وكان رسولُ الله كَتَب له كِتابًا، وأمرَه ألَّا يَنظُرَ فيه حتى يَسيرَ "},{"id":55,"era":"c1","t":"تَحويلُ القِبلَةِ إلى الكعبة .","s":"عنِ البَراءِ بنِ عازبٍ رضِي الله عنهما قال: \"لمَّا قَدِمَ رسولُ الله صلى الله عليه وسلم المدينةَ صلَّى نحوَ بيتِ المَقدسِ سِتَّةَ عشرَ أو سَبعةَ عشرَ شهرًا، وكان يُحِبُّ أن يُوَجَّهَ إلى الكعبةِ، فأنزل الله تعالى: {قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَاهَا} [البقرة: 144]، فَوُجِّهَ نحوَ الكعبةِ، وصلَّى معه رجلٌ العصرَ، ثمَّ خرج فمَرَّ على قومٍ مِنَ الأنصار"},{"id":56,"era":"c1","t":"نزول فَرْضِيَّة صِيامِ شَهرِ رَمضانَ .","s":"في هذه السَّنَةِ فُرِضَ صِيامُ شهرِ رمضانَ، وقِيلَ: إنَّ فَريضةَ صِيامِ شهرِ رمضانَ كانت قبلَ غَزوةِ بدرٍ."},{"id":57,"era":"c1","t":"نزول فَرْضية زكاةِ الفِطرِ .","s":"شرع الله سُبحانه وتعالى زكاةَ الفِطرِ, وهي واجبةٌ على كُلِّ مُسلمٍ حُرٍّ أو عبدٍ، ذَكَرٍ أو أُنثى، صغيرٍ أو كبيرٍ مِنَ المسلمين قادرٍ عليها. والحِكمةُ منها تَطهيرُ الصَّائمِ ممَّا عسى أن يكونَ قد وقع فيه أثناءَ الصِّيامِ مِن لَغْوٍ أو رَفَثٍ، وإعانةٌ للفقراءِ على إدخالِ السُّرورِ عليهم في يومِ العيدِ."},{"id":58,"era":"c1","t":"سرية عمير بن عدي رضي الله عنه لقتل عصماء بنت مروان .","s":"كانت عَصماءُ بِنتُ مَرْوانَ مِن بني أُمَيَّةَ بنِ زَيدٍ، زَوجةُ يَزيدَ بنِ زَيدِ بنِ حِصنٍ الخَطْميِّ، تَعيبُ الإسلامَ وتُؤذي رسولَ اللَّه صلَّى اللهُ عليه وسلَّم، وتُحرِّضُ عليه.وكانت تَطرَحُ المَحايِضَ في مسجِدِ بني خَطْمةَ؛ فأهدَرَ رسولُ اللَّه صلَّى اللهُ عليه وسلَّم دَمَها، فنَذَر عُمَيرُ بنُ عَديٍّ لئن رَجَعَ رسولُ اللَّه صلَّى اللهُ عليه وسلَّم من بَدرٍ إلى المدينة ليَقتُلَنَّها، وقد فعل رض"},{"id":59,"era":"c1","t":"غَزوةُ بدرٍ (الكُبرى) وانْتصارُ المُسلمين .","s":"ندَب رسولُ الله صلى الله عليه وسلم نَفرًا مِنَ المسلمين لاعتراضِ قافلةِ قُريشٍ القادمةِ مِنَ الشَّامِ التي كان يرأَسُها أبو سُفيانَ الذي عَلِمَ بعدَ ذلك بِخُروجِ المُسلمين، فأَرسل إلى قُريشٍ يَسْتَنْفِرُها لاسْتِنقاذِ تِجارتِهم كما غَيَّرَ طريقَهُ لإنقاذِ التِّجارةِ، ثمَّ الْتَقى المسلمون والمشركون عند ماءِ بدرٍ، وهي مكانٌ بين مكَّةَ والمدينةِ وهو أَقربُ إليها مِن مكَّةَ، وكان عددُ المشركين يُقارِ"},{"id":60,"era":"c1","t":"وفاةُ رُقَيَّةَ رضِي الله عنها .","s":"هي رُقَيَّةُ بنتُ سَيِّدِ البَشرِ صلَّى الله عليه وسلَّم، وهي زوجُ عُثمانَ بنِ عفَّانَ رضِي الله عنهما، وكانت رُقَيَّةُ أوَّلًا عند عُتْبَةَ بنِ أبي لَهبٍ، فلمَّا بُعِثَ النَّبيُّ صلَّى الله عليه وسلَّم أَمَرَ أبو لَهبٍ ابنَهُ بِطلاقِها، فتَزوَّجها عُثمانُ وهاجر بها إلى الحَبشةِ. ولمَّا نَدَبَ رسولُ الله النَّاسَ للخُروجِ لاعتراضِ قافلةِ أبي سُفيانَ أَمَرَ عُثمانَ أن يَبقى عند رُقَيَّةَ يُمَرِّضُه"},{"id":61,"era":"c1","t":"سرية سالم بن عمير رضي الله تعالى عنه إلى أبي عفك اليهودي .","s":"كانت سريَّةُ سالِمِ بنِ عُمَيرٍ رَضي اللهُ عنه إلى أبي عَفَكٍ اليَهوديِّ في شوَّالٍ على رأسِ عشرين شهرًا من مُهاجَرِ رسولِ الله صلَّى اللهُ عليه وسلَّم، وكان أبو عَفَكٍ من بني عمرِو بن عوفٍ شَيخاً كبيرًا قد بلغ عشرين ومئةَ سنةٍ، وكان يَهوديًّا، عَظيمَ الكُفرِ، شديدَ الطَّعنِ على المسلمين، قد امتَلَأ قلبُه بالحقدِ والحسدِ للمسلمين، وهو يرى الْتِفافَ الأوسِ والخزرجِ على نُصرةِ رسولِ الله صلَّى اللهُ"},{"id":62,"era":"c1","t":"غَزوةُ بني قَينُقاعٍ .","s":"ذكَر مُعظمُ أهلِ المَغازي والسِّيَرِ أنَّها وقعت بعدَ بدرٍ، ورجَّحهُ ابنُ حَجَرٍ، وقد كانت يومَ السَّبتِ للنِّصفِ مِن شَوَّالٍ. وخَبرُ إجلاءِ بني قَينُقاعٍ ثابتٌ في الصَّحيحينِ، فعنِ ابنِ عُمَرَ رضِي الله عنهما قال: \"حاربَتِ النَّضيرُ وقُرَيْظةُ، فأَجْلى بني النَّضيرِ، وأَقَرَّ قُرَيْظَةَ ومَن عليهم، حتَّى حاربتْ قُرَيْظَةُ، فقَتَلَ رِجالَهم، وقَسَمَ نِساءَهُم وأَولادَهُم وأَموالَهُم بين المسلمين،"},{"id":63,"era":"c1","t":"غزوة السويق أو غزوة بني سليم (قرقرة الكدر) .","s":"بعد هَزيمةِ المُشرِكين في بدْرٍ، نَذَر أبو سُفيانَ ألَّا يَمَسَّ رَأسَه ماءٌ من جَنابةٍ حتى يَغزوَ مُحمَّدًا صلَّى اللهُ عليه وسلَّم وأصحابَه ويَنتقِمَ من المسلمين؛ فخَرَج في مِائتَي راكِبٍ من قُريشٍ، ليَبَرَّ بيَمينِه، ووَصَل إلى أطرافِ المَدينةِ لَيلًا، ولَجَأ إلى بني النَّضيرِ، فأتَى حُيَيَّ بنَ أخطَبَ، فضَرَب عليه بابِه، فأبَى أن يَفتَحَ له بابَه وخافَهُ؛ فانصَرَف عنه إلى سَلَّامِ بنِ مِشكَمٍ "},{"id":64,"era":"c1","t":"غَزوةُ السَّوِيقِ (قَرْقَرَةِ الكُدْرِ) .","s":"كان أبو سُفيانَ حين رجع إلى مكَّةَ مِن بدرٍ قد نذَر أن لا يَمَسَّ رأسَهُ ماءٌ مِن جَنابَةٍ، حتَّى يغزو محمَّدًا، فخرج في مِائتي راكبٍ مِن قُريشٍ لِتَبرَّ يَمينَه فسلك النَّجْدِيَّةَ حتَّى نزل بصَدرِ قناةٍ إلى جبلٍ يُقالُ له: نَيْبٌ مِنَ المدينةِ على بَريدٍ أو نحوهِ، ثمَّ خرج من اللَّيلِ حتَّى أتى بني النَّضيرِ تحت اللَّيلِ فأتى حُيَيَّ بنَ أَخْطَبَ فضرَب عليه بابَهُ، فأبى أن يفتحَ له وخافَهُ، فانص"},{"id":65,"era":"c1","t":"مَقتَلُ كعبِ بنِ الأَشرفِ .","s":"كعبُ بنُ الأَشرفِ رجلٌ مِن طَيِّءٍ وأمُّهُ مِن يَهودِ بني النَّضيرِ. كان شاعرًا يَهجو النَّبيَّ صلى الله عليه وسلم وأصحابَه ويُحرِّضُ عليهم ويُؤذيهِم، فلمَّا كانت وقعةُ بدرٍ كُبِتَ وذُلَّ وقال: بطنُ الأرضِ خيرٌ مِن ظَهرِها اليومَ. فخرج حتَّى قَدِمَ مكَّةَ فبَكى قَتلى قُريشٍ وحَرَّضهُم بالشِّعرِ، قال جابرُ بنُ عبدِ الله: قال: رسولُ الله صلى الله عليه وسلم: «مَن لِكعبِ بنِ الأَشرفِ؟ فإنَّه قد آذى ال"},{"id":66,"era":"c1","t":"غزوة غطفان إلى نجد (غزوة ذي أمرّ) .","s":"وهي غزوةُ ذي أمَرَّ بناحيةِ نَجدٍ. وسَبَبُها: أنَّ رسولَ الله صلَّى اللهُ عليه وسلَّم بَلَغه أنَّ جَمعًا من بني ثَعلَبَة بنِ سَعيدِ بن ذُبْيانَ بن بَغيضٍ بنِ رَيثِ بن غَطَفانَ، وبني مُحارِبِ بن خَصَفةَ بن قَيسٍ بذي أمَرَّ قد تَجَمَّعوا يُريدون أن يُصيبوا مِن أطرافِ رسولِ الله صلَّى اللهُ عليه وسلَّم، وجَمَعهم رجلٌ منهم يُقال له: دُعْثورُ بن الحارِثِ بن مُحارِبٍ، فنَدَب رسولُ الله صلَّى اللهُ عليه "},{"id":67,"era":"c1","t":"غزوة بحران بين الفُرْعِ والمدينة .","s":"غزا رسولُ الله صلَّى اللهُ عليه وسلَّم يُريدُ قُريشًا، واستَعمَلَ على المدينةِ عبدَ الله بنَ أُمِّ مَكتومٍ رَضي اللهُ عنه، حتى بَلَغ بُحرانَ مِن ناحيةِ الفُرْعِ. وسَبَبُها: أنَّه بَلَغَ النبيَّ صلَّى اللهُ عليه وسلَّم أنَّ بها جَمعًا كثيرًا من بني سُلَيمِ بنِ مَنصورٍ؛ فخَرَج في ثَلاثِمئةِ رجلٍ من أصحابِه، ولم يُظهِر وَجهًا للسَّيرِ؛ حتى إذا كان دونَ بُحرانَ بليلةٍ لَقيَ رجلًا من بني سُلَيمٍ فأخبَر"},{"id":68,"era":"c1","t":"سَرِيَّةُ زيدِ بنِ حارِثةَ .","s":"أَصبحَ مُشرِكو مكَّةَ بعدَ هَزيمَتِهم في غَزوةِ بدرٍ، يَبحَثون عن طريقٍ أُخرى لِتِجارتِهم للشَّامِ، فأشارَ بعضُهم إلى طريقِ نَجْدِ العِراقِ، وقد سَلكوها بالفعلِ، وخرج منهم تُجَّارٌ، فيهم أبو سُفيانَ بنُ حَربٍ، وصَفوانُ بنُ أُميَّةَ، وحُوَيْطِبُ بنُ عبدِ العُزَّى، ومعهم فِضَّةٌ وبضائعُ كثيرةٌ، بما قيمتُه مائةُ ألفِ دِرهمٍ؛ فبلغ ذلك رسولُ الله صلى الله عليه وسلم بواسطةِ سَليطِ بنِ النُّعمانِ رضي الل"},{"id":69,"era":"c1","t":"غَزوةُ أُحُدٍ وسبب هزيمة المسلمين .","s":"كان سببُها أنَّ المشركين حين قُتِلَ مَن قُتِلَ مِن أَشرافِهِم يوْمَ بَدْرٍ، وسَلمَت العِيرُ بما فيها مِنَ التِّجارةِ التي كانت مع أبي سُفيانَ، فلمَّا رجع فَلُّهُم إلى مكَّةَ قال أبناءُ مَن قُتِلَ، ورُؤساءُ مَن بَقِيَ لأبي سُفيانَ: ارْصُدْ هذه الأموالَ لِقتالِ محمَّدٍ، فأَنفَقوها في ذلك، وجمعوا الجُموعَ والأَحابيشَ وأَقبلوا في قَريبٍ مِن ثلاثةِ آلافٍ، حتَّى نزلوا قريبًا مِن أُحُدٍ تِلْقاءَ المدينةِ"},{"id":70,"era":"c1","t":"اسْتِشهادُ حَمزةَ رضِي الله عنه في غَزوةِ أُحُدٍ .","s":"عن عُبيدِ اللهِ بنِ عَدِيِّ بنِ الخِيارِ أنَّه سألَ وَحْشِيًّا قاتلَ حَمزةَ، ألا تُخبِرُنا بِقتلِ حَمزةَ؟ قال: نعم، إنَّ حَمزةَ قَتَلَ طُعَيْمَةَ بنَ عَدِيِّ بنِ الخِيارِ ببَدرٍ، فقال لي مولايَ جُبيرُ بنُ مُطْعِمٍ: إن قَتلتَ حَمزةَ بِعَمِّي فأنت حُرٌّ، قال: فلمَّا أن خرج النَّاسُ عامَ عَيْنَيْنِ، وعَيْنَيْنُ جبلٌ بِحِيالِ أُحُدٍ، بينه وبينه وادٍ، خرجتُ مع النَّاسِ إلى القِتالِ، فلمَّا أن اصْطَفُّو"},{"id":71,"era":"c1","t":"غَزوةُ حَمراءِ الأَسدِ .","s":"قال ابنُ كَثيرٍ في تَفسيرِ قولِه تعالى: {الَّذِينَ اسْتَجَابُوا لِلَّهِ وَالرَّسُولِ مِنْ بَعْدِ مَا أَصَابَهُمُ الْقَرْحُ} هذا كان يومَ حَمراءِ الأسدِ، وذلك أنَّ المشركين لمَّا أصابوا ما أصابوا مِن المسلمين -أي يومَ أُحُدٍ-كَرُّوا راجِعين إلى بلادِهم، فلمَّا استَمرُّوا في سَيْرهِم تَنَدَّمُوا لِمَ لا تَمَّموا على أهلِ المدينةِ وجعلوها الفَيْصلةَ. فلمَّا بلغ ذلك رسولَ الله صلى الله عليه وسلم نَدَب"},{"id":72,"era":"c1","t":"سرية عبد الله بن عبد الأسد رضي الله عنه إلى قطن .","s":"كانت سَريَّةُ أبي سَلَمةَ عبدِ الله بنِ عبدِ الأسَدِ، وهو ابنُ عمَّتِه صلَّى اللهُ عليه وسلَّم بَرَّةَ بنتِ عبد المطلب، وأخوه من الرَّضاعةِ، أرضَعَتهما ثُوَيبةُ. وقَطَنٌ: هو جبلٌ، وقيل: ماءٌ مِن مياهِ بني أسَدٍ. وسَبَبُها: أن رجلًا مِن طيِّئٍ اسمُه الوليدُ بن زُهَيرِ بن طَريفٍ قَدِم المدينةَ زائرًا ابنةَ أخيه زَينَبَ، وكانت تَحتَ طُلَيبِ بنِ عُمَيرِ بن وَهبٍ، فأُخبِرَ أنَّ طُليحةَ وسَلَمةَ ابنَي خ"},{"id":73,"era":"c1","t":"سرية عبد الله بن أنيس الجهني إلى سفيان بن خالد ببطن عُرْنة .","s":"خَرَج عبدُ اللَّه بنُ أُنيسٍ رَضي اللهُ عنه من المدينةِ يومَ الإثنَينِ لخمسٍ خَلَونَ من المُحرَّمِ على رأس خمسةٍ وثلاثين شهرًا من مُهاجَرِ رسولِ اللَّه صلَّى اللهُ عليه وسلَّم، وبَلَغَ رسولَ اللَّه صلَّى اللهُ عليه وسلَّم أنَّ سُفيانَ بنَ خالِدِ بن نُبَيحٍ الهُذليَّ ثم اللِّحيانيَّ -وكان يَنزِل عُرْنةَ وما والاها في أُناسٍ من قومِه وغيرِهم- يُريد أن يَجمَعَ الجُموعَ إلى رسولِ اللَّه صلَّى اللهُ عل"},{"id":74,"era":"c1","t":"سرية يَوم الرَّجيعِ .","s":"عن أبي هُريرةَ رضي الله عنه قال: «بعَث رسولُ الله صلى الله عليه وسلم عشرةَ رَهْطٍ سَرِيَّةً عينًا، وأَمَّرَ عليهم عاصمَ بنَ ثابتٍ الأَنصاريَّ، جَدَّ عاصمِ بنِ عُمَرَ بنِ الخطاَّبِ، فانطلقوا حتَّى إذا كانوا بالهَدَأَةِ، وهو بين عُسْفانَ ومكَّةَ، ذُكِروا لِحَيٍّ مِن هُذيلٍ يُقالُ لهم: بنو لَحْيانَ، فنَفَروا لهم قريبًا مِن مائتي رجلٍ كُلُّهم رامٍ، فاقْتَصُّوا آثارَهُم حتَّى وجدوا مَأكلَهُم تمرًا تَزو"},{"id":75,"era":"c1","t":"سرية بِئر مَعونةَ .","s":"عن أنسِ بنِ مالكٍ رضي الله عنه قال:  أنَّ رِعْلًا، وذَكْوانَ، وعُصَيَّةَ، وبني لَحْيانَ، اسْتمَدُّوا رسولَ الله صلى الله عليه وسلم على عَدُوٍّ، فأَمدَّهُم بسبعين مِنَ الأنصارِ، كُنَّا نُسمِّيهم القُرَّاءَ في زمانِهم، كانوا يَحْتَطِبون بالنَّهارِ، ويُصلُّون باللَّيلِ، حتَّى كانوا ببِئرِ مَعونةَ قَتلوهُم وغَدَروا بهم، فبلَغ النَّبيَّ صلى الله عليه وسلم فقَنَتَ شهرًا يَدعو في الصُّبحِ على أَحياءٍ مِن"},{"id":76,"era":"c1","t":"غَزوةُ بني النَّضيرِ .","s":"كان سببُها أنَّه لمَّا قُتِلَ أصحابُ بِئرِ مَعونةَ مِن أصحابِ رسولِ الله صلى الله عليه وسلم، وكانوا سبعين، وأَفْلَتَ منهم عَمرُو بنُ أُميَّةَ الضَّمريُّ، فلمَّا كان في أَثناءِ الطَّريقِ راجعًا إلى المدينةِ قَتَلَ رجُلينِ مِن بني عامرٍ، وكان معهما عهدٌ مِن رسولِ الله صلى الله عليه وسلم وأَمانٌ لم يَعلَمْ به عَمرٌو، فلمَّا رجَع أَخبرَ رسولَ الله صلى الله عليه وسلم... فخرج رسولُ الله صلى الله عليه وس"},{"id":77,"era":"c1","t":"غزوة بدر الموعد (بدر الثانية) .","s":"تُسمَّى هذه الغزوةُ ببدرٍ الآخِرةِ، وبَدرٍ الصُّغرى، وبدرٍ الثانيةِ، وبدرٍ المَوعِدِ؛ للمواعَدةِ عليها مع أبي سُفيانَ بنِ حربٍ يومَ أُحدٍ؛ وذلك أن أبا سفيان لمَّا انصَرَف منِ أُحدٍ نادى: \"إنَّ مَوعِدَكم بَدرٌ، العامَ المُقبِلَ\". فلمَّا كانتِ السَّنةُ الرابِعةُ من الهِجرةِ، خَرَج الرسولُ صلَّى اللهُ عليه وسلَّم بألفٍ وخَمسِمئةٍ من أصحابِه إلى بدرٍ ومعه عَشَرةُ أفراسٍ، وحَمَل لِواءَه عليُّ بن أبي طا"},{"id":78,"era":"c1","t":"حادِثةُ الإفْكِ .","s":"لمَّا خرَج النَّبيُّ صلى الله عليه وسلم إلى بني المُصطلِقِ لِغَزوِهِم أَقرعَ بين نِسائِه مَن يَخرُج معه، فكانت القُرعَةُ على عائشةَ الطَّاهرةِ رضي الله عنها وأَرضاها، وفي طريقِ العَودةِ كانت تُحمَلُ على هَودجٍ، فقدَّرَ الله في ذلك اليومِ أن تكونَ خارجَ هَودَجِها لِتبحثَ عن عِقْدٍ سقَط منها، فلمَّا أرادوا الرَّحيلَ لم يَشعُروا بعدمِ وُجودِها ورَحلوا؛ فقد كانت صَغيرةً خَفيفةَ الوَزنِ، فلمَّا رجعت لم"},{"id":79,"era":"c1","t":"غزوة دومة الجندل .","s":"كانت غزوةُ دُومةِ الجَندلِ -موضِعٍ على طَرَفِ الشَّامِ بينها وبين دمشقَ خمسَ لَيالٍ، وبينها وبين المدينةِ خمسَ عشرةَ أو سِتَّ عشرةَ لَيلةً- في ربيعٍ الأوَّلِ من السَّنةِ الخامسةِ للهِجرةِ.وسَبَبُها: أنَّ رسولَ الله صلَّى اللهُ عليه وسلَّم بَلَغه أنَّ بدُومةِ الجَندَلِ جَمعًا كثيرًا من القبائِلِ، وأنَّهم يَظلِمون مَن مرَّ بِهِم، ويَنهَبون ما معهم، وأنَّهم يُريدون أن يَدْنوا من المدينةِ لمُهاجَمَتِه"},{"id":80,"era":"c1","t":"غزوة بني المصطلق (المريسيع) .","s":"بَلَغ رسولَ الله صلَّى اللهُ عليه وسلَّم أن بني المُصطَلِقِ -وهم بَطنٌ من قَبيلةِ خُزاعةَ الأزديَّةِ اليَمانيَّةِ- يَجمَعون لقِتالِه، وقائِدُهمُ الحارِثُ بن أبي ضِرارٍ؛ فلمَّا سَمِع رسولُ الله صلَّى اللهُ عليه وسلَّم بهم خَرَج إليهم حتَّى لَقيَهم على ماءٍ لهم يُقال له: (المُرَيسيعُ)، ولذلك تُسَمَّى هذه الغَزوةُ أيضًا: بغَزوةِ المُرَيسيعِ. فتَزاحَفَ النَّاسُ واقتَتَلوا، فهَزَمَ اللهُ بني المُصطَلِق"},{"id":81,"era":"c1","t":"غَزوةُ الخَندَقِ (الأَحزابِ) .","s":"كان سببُ هذه الغَزوةِ هو إجلاءُ يَهودِ بني النَّضيرِ مِنَ المدينةِ؛ حيثُ إنَّ الحسدَ والحِقدَ قد تَمكَّنا مِن قُلوبهِم، ممَّا جعَلهم يُضمِرون العَداءَ ويَتَحَيَّنون الفُرصَ للتَّشفِّي ممَّن طَردَهم مِنَ المدينةِ وما حولها. ولمَّا لم يَستطِعْ يَهودُ خَيبرَ وخاصَّةً بني النَّضيرِ مَجابهةَ المسلمين لَجأوا إلى أُسلوبِ المكرِ والتَّحريشِ. وقد ذكَر ابنُ إسحاقَ بِسَندِهِ عن جماعةٍ: أنَّ الذين حَزَّبوا ال"},{"id":82,"era":"c1","t":"نُزولُ آيةِ الحِجابِ .","s":"وكان سببُ نُزولِها أنَّ عُمَرَ رضي الله عنه كان يَقولُ لِرسولِ الله صلى الله عليه وسلم: لو أَمرتَ نِساءَك أن يَحْتَجِبْنَ، فإنَّه يُكلِّمُهُنَّ البَرُّ والفاجرُ، فنزَل قولُه تعالى: {يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَدْخُلُوا بُيُوتَ النَّبِيِّ إِلَّا أَن يُؤْذَنَ لَكُمْ... إلى قوله تعالى:..وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِن وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُل"},{"id":83,"era":"c1","t":"غَزوةُ يَهودِ بني قُرَيْظَةَ .","s":"وقعَت هذه الغَزوةُ بعدَ غَزوةِ الأحزابِ مُباشرةً، وكان سببُها نقضَ بني قُريظةَ العهدَ الذي بينهم وبين النَّبيِّ صلى الله عليه وسلم بتَحريضٍ مِن حُيَيِّ بنِ أَخطبَ النَّضْريِّ. وكان النَّبيُّ صلَّى الله عليه وسلَّم قد أَرسلَ الزُّبيرَ لِمعرفةِ نِيَّتِهم، ثمَّ أَتبَعهُ بالسَّعدَيْنِ –سَعدِ بنِ عُبادةَ وسَعدِ بنِ مُعاذٍ- وابنِ رَواحةَ، وخَوَّاتِ بنِ جُبيرٍ لِذاتِ الهدفِ ليَتأكَّدَ مِن غَدرِهم. وقد أم"},{"id":84,"era":"c1","t":"مَقتلُ سَلَّامِ بنِ أبي الحُقَيْقِ اليَهوديِّ .","s":"هو أبو رافعٍ سَلَّامُ بنُ أبي الحُقَيْقِ شاعرٌ وفارسٌ يَهوديٌّ، أحدُ الذين حَزَّبوا الأحزابَ ضِدَ المسلمين في غزوةِ الأحزابِ، وأَعانَهُم بالمُؤَنِ والأَموالِ الكَثيرةِ، ولمَّا قتَل الله كعبَ بنَ الأشرفِ على يدِ رجالٍ مِنَ الأَوسِ بعدَ وقعةَ بدرٍ كان أبو رافعٍ سَلَّامُ بنُ أبي الحُقيقِ ممَّن أَلَّبَ الأحزابَ على رسولِ الله صلى الله عليه وسلم ولم يُقتلْ مع بني قُريظةَ كما قُتِلَ صاحبُه حُيَيُّ بنُ أ"},{"id":85,"era":"c1","t":"غَزوةُ ذي قَرَدٍ .","s":"أَغار عُيَيْنَةُ بنُ حِصْنٍ -في بني عبدِ الله بنِ غَطَفانَ- على لِقاحِ النَّبيِّ صلى الله عليه وسلم التي بالغابةِ، فاسْتاقَها وقتَل راعيَها، وهو رجلٌ مِن غِفارٍ، وأخذوا امْرأتَهُ، فكان أوَّلَ مَن نذَر بهم سَلمةُ بنُ عَمرِو بنِ الأَكْوَعِ الأَسلميُّ رضي الله عنه، يقول سَلمةُ: خَرجتُ قبلَ أن يُؤذَّنَ بالأولى، وكانت لِقاحُ رسولِ الله صلى الله عليه وسلم تَرعى بِذي قَرَدٍ، قال: فلَقِيَني غُلامٌ لِعبدِ "},{"id":86,"era":"c1","t":"سرية محمد بن مسلمة رضي الله عنه إلى القرطاء .","s":"بَعَثَ رسولُ الله صلَّى اللهُ عليه وسلَّم مُحمَّدَ بن مَسلَمةَ رَضي اللهُ عنه في ثلاثين راكِبًا إلى القُرْطاءِ -بينها وبين المدينةِ سَبعُ ليالٍ-، وهم بَطنٌ من بني بَكرٍ، واسمُه: عُبَيدُ بنُ كِلابٍ.فخَرَج محمدُ بنُ مَسلَمةَ رَضي اللهُ عنه وأصحابُه فسار اللَّيلَ واستَتَر النَّهارَ، فلمَّا أغار عليهم هَرَب سائِرُهم بعد أن قَتَل نَفَرًا منهم، واستاقَ المسلمون نَعَمًا وشاءً، وقَدِموا المدينةَ لِلَيلةٍ "},{"id":87,"era":"c1","t":"سرية عُكَّاشة بن مِحصَن رضي الله عنه إلى الغَمر (ماء بني أسد) .","s":"بَعَث رسولُ الله صلَّى اللهُ عليه وسلَّم عُكَّاشةَ بنَ مِحصَنٍ رَضي اللهُ عنه إلى الغَمْرِ -ماءٍ لبني أسَدٍ- في أربعين رَجلًا، فيهم: ثابِتُ بنُ أقرَمَ، وشُجاعُ بنُ وَهبٍ؛ فخَرَج سَريعًا ونَذِرَ به القَومُ فهَرَبوا فنَزَلوا عَلياءَ بلادِهِم، ووَجَد ديارَهم خُلوفًا -أي: أهلُها غائِبون-، فبَعَث شُجاعَ بنَ وَهبٍ طَليعةً؛ فرَأى أثَرَ النَّعَمِ، فتَحمَّلوا فأصابوا مَن دَلَّهم على بَعضِ ماشيَتِهِم، فأمَّ"},{"id":88,"era":"c1","t":"سرية محمد بن مسلمة رضي الله عنه إلى بني ثعلبة وبني عوال بذي القَصَّةِ .","s":"بَعَث رسولُ الله صلَّى اللهُ عليه وسلَّم مُحمَّدَ بنَ مَسلَمةَ رَضي اللهُ عنه، ومعه عَشَرةُ نَفَرٍ إلى بني ثَعلَبةَ من غَطَفانَ وبني عَوالٍ من ثَعلَبةَ، وهم بذي القَصَّةِ، فوَرَدوا عليهم ليلًا، فأحدَق به القومُ، وهم مئةُ رجلٍ، فتَرامَوا ساعةً من اللَّيلِ، ثم حَمَلتِ الأعرابُ عليهم بالرِّماحِ فقَتَلوهم جميعًا، ووَقَع محمدُ بنُ مَسلَمةَ جَريحًا، فضَرَبوا كعبَه فلم يتحرَّك فظَنُّوا مَوتَه، فجَرَّدوه "},{"id":89,"era":"c1","t":"سرية أبي عبيدة بن الجراح إلى ذي القصة .","s":"أرسل رسولُ الله صلَّى اللهُ عليه وسلَّم أبا عُبَيدةَ بنَ الجَرَّاحِ رَضي اللهُ عنه إلى ذي القَصَّةِ -موضِعٍ قريبٍ من المدينةِ- على إثرِ مَقتَلِ أصحابِ مُحمَّدِ بنِ مَسلمةَ رَضي اللهُ عنه في أربعين رجلًا من المسلمين حين صَلَّوُا المَغرِبَ، فسار إليهم مُشاةً حتى وافَوا ذي القَصَّةِ مع عَمايةِ الصُّبحِ -بقيَّةِ ظُلمةِ اللَّيلِ- فأغاروا عليهم، فأعجَزوهم هَرَبًا في الجبالِ، وأصابوا رجلًا فأسلم فتَرَكوه"},{"id":90,"era":"c1","t":"سرية زيد بن حارثة رضي الله عنه إلى الجموم (ماءٌ على طَريقِ مكةَ) .","s":"بَعَث رسولُ الله صلَّى اللهُ عليه وسلَّم زيدَ بنَ حارِثةَ رَضي اللهُ عنه إلى بني سُلَيمٍ؛ فسار حتى وَرَد الجَمومَ -وهو ماءٌ على طَريقِ مكةَ- ناحيةَ بَطنِ نَخلٍ عن يَسارِها، فأصابوا عليه امرَأةً من مُزَينةَ يقال لها: حَليمةُ، فدَلَّتهم على مَحَلَّةٍ من مَحالِّ بني سُلَيمٍ؛ فأصابوا في تلك المَحَلَّةِ نَعَمًا وشاءً وأسرى، فكان فيهم زوجُ حَليمةَ المُزنيَّةِ، فلمَّا قَفَل زيدُ بنُ حارِثةَ رَضي اللهُ عن"},{"id":91,"era":"c1","t":"غزوة بني لحيان (الذين غدروا يوم الرجيع) .","s":"بنو لِحيانَ: هم الذين غدروا بخُبَيبِ بنِ عَديٍّ رَضي اللهُ عنه وأصحابِه يومَ الرَّجيعِ، ولمَّا كانت ديارُهم مُتوغِّلةً في بلاد الحِجازِ إلى حدودِ مكةَ، ولوُجودِ ثاراتٍ بين المسلمين من جهةٍ، وقُريشٍ والأعرابِ من جهة أُخرَى، رأى رسولُ الله صلَّى اللهُ عليه وسلَّم ألَّا يَتوغَّلَ في البلادِ القريبةِ من العَدوِّ الأكبَرِ والرَّئيسيِّ قُريشٍ، فلمَّا تَخاذَلَتِ الأحزابُ، وانكَسَرَت عزائِمُهم، رأى أنَّ ا"},{"id":92,"era":"c1","t":"سرية زيد بن حارثة رضي الله عنه إلى العيص .","s":"بَعَث رسول الله صلَّى اللهُ عليه وسلَّم زيدَ بنَ حارِثةَ رَضي اللهُ عنه في سَريَّةٍ في سبعين ومئةِ راكِبٍ إلى العيصِ -اسمِ مَوضِعٍ قُربَ المدينةِ على ساحِلِ البحرِ- بهَدفِ اعتِراضِ عيرٍ لقُريشٍ أقبلَت مِن الشامِ بقيادةِ أبي العاصِ بنِ الرَّبيعِ، فأدرَكوها، فأخَذوها وما فيها، وأخَذوا يومئذٍ فِضَّةً كَثيرةً لصَفوانَ بنِ أُميَّةَ، وأسَروا ناسًا ممَّن كان في العيرِ، منهم: أبو العاصِ بنُ الرَّبيعِ، وقَ"},{"id":93,"era":"c1","t":"سرية زيد بن حارثة إلى بني ثعلبة بالطَّرف (ماء قرب المدينة) .","s":"بَعَث رسولُ الله صلَّى اللهُ عليه وسلَّم زيدَ بنَ حارِثةَ رَضي اللهُ عنه إلى الطَّرَفِ -هو ماءٌ على ستَّةٍ وثلاثين ميلًا من المدينةِ-، فخَرَج إلى بني ثَعلبةَ في خَمسةَ عَشَرَ رَجُلًا، فهَرَبتِ الأعرابُ وخافوا أن يكونَ رسولُ الله صلَّى اللهُ عليه وسلَّم سار إليهم، وأنَّ هؤلاءِ مُقدِّمةٌ؛ فأصابَ مِن نَعَمِهم عِشرين بَعيرًا، ورَجَع إلى المدينةِ، ولم يَلْقَ كيدًا، وغابَ أربَعَ لَيالٍ. وكان شِعارُهم: \""},{"id":94,"era":"c1","t":"سرية عبد الرحمن بن عوف رضي الله عنه إلى دومة الجندل .","s":"دعا رسولُ الله صلَّى اللهُ عليه وسلَّم عبدَ الرَّحمنِ بنَ عوفٍ رَضي اللهُ عنه، فقال له: \"تَجهَّزْ؛ فإنِّي باعِثُك في سَريَّةٍ مِن يَومِك هذا، أو مِن الغَدِ إن شاءَ اللهُ تعالى\"، فأصبَحَ عبدُ الرَّحمنِ فغَدا إلى رسولِ الله صلَّى اللهُ عليه وسلَّم، فأقعَدَه بين يَدَيه وعمَّمَه بيَدِهِ، ثمَّ عَقَد له رسولُ الله صلَّى اللهُ عليه وسلَّم اللواءَ بيَدِه، أو أمرَ بلالًا يَدفَعُه إليه، ثم قال له: \"خُذه باس"},{"id":95,"era":"c1","t":"سرية أبي بكر الصديق رضي الله عنه  إلى بني فزارة بوادي القرى .","s":"كان بَطنُ فَزارةَ يُريدُ اغتيالَ النبيِّ صلَّى اللهُ عليه وسلَّم؛ فبَعَث رسولُ الله صلَّى اللهُ عليه وسلَّم سَريَّةً على رَأسِها: أبو بَكرٍ الصِّدِّيقُ رَضي اللهُ عنه فأغار عليهم، وقَتَل وأسَر وسَبَى، وكان مِن شَياطينِهم أُمُّ قِرْفةَ التي جهَّزَت ثلاثين فارِسًا من أهلِ بَيتِها لاغتيالِ رسولِ الله صلَّى اللهُ عليه وسلَّم، فقُتِلوا وسُبيَتِ ابنَتُها، ففَدَى بها رسولُ الله صلَّى اللهُ عليه وسلَّم بع"},{"id":96,"era":"c1","t":"سرية كُرز بن جابر الفهري إلى العرنيين .","s":"في هذا العام كانت سَريَّةُ كُرْزِ بنِ جابِرٍ الفِهريِّ إلى العُرَنيِّين، الذين قَتَلوا راعيَ رسولِ الله صلَّى اللهُ عليه وسلَّم، واستاقوا النَّعَمَ؛ فبَعَث رسولُ الله صلَّى اللهُ عليه وسلَّم في آثارِهِم كُرْزَ بنَ جابِرٍ رَضي اللهُ عنه في عِشرين فارِسًا.عن أنس رَضي اللهُ عنه: أنَّ رهطًا من عُكلٍ وعُرَينةَ أتَوا رسولَ الله صلَّى اللهُ عليه وسلَّم فقالوا: إنَّا أُناسٌ من أهل ضَرعٍ، ولم نَكُن أهلَ ري"},{"id":97,"era":"c1","t":"بَيعةُ الرِّضْوانِ .","s":"كان رسولُ الله صلَّى الله عليه وسلَّم قبلَ عَقْدِ صُلحِ الحُديبيةِ بعَث خِراشَ بنَ أُميَّةَ الخُزاعيَّ إلى مكَّةَ، وحمَلهُ على جَملٍ له يُقالُ له: الثَّعلبُ. فلمَّا دخَل مكَّةَ عَقَرَتْ به قُريشٌ وأرادوا قَتْلَ خِراشٍ فمنَعهُم الأَحابيشُ (هم: بنو الحارث بن عبد مناة بن كنانة ، والهون بن خزيمة بن مدركة، وبنو المصطلق من خزاعة) حتَّى أتى رسولَ الله صلى الله عليه وسلم فدَعا عُمَرَ لِيَبعثَهُ إلى مكَّةَ"},{"id":98,"era":"c1","t":"صُلْحُ الحُدَيبيةِ .","s":"خرَج رسولُ الله صلى الله عليه وسلم ومعه قُرابةُ ألفٍ وأربعمائةٍ مِن أصحابِه يُريدون العُمرةَ فلمَّا وصلوا إلى الحُديبيةِ - وهي تَبعُد عن مكَّةَ قُرابةَ 22 كم - وَصلَهُ الخبرُ أنَّ هناك مَن يُريدُ أن يُقاتِلَهُ، فقال: إنَّه لم يَجِئْ لقِتالٍ؛ بل جاء مُعتمِرًا. وأَرسل رسولُ الله صلى الله عليه وسلم عُثمانَ بنَ عفَّانَ إلى مكَّةَ لِيُخبِرَهم بذلك، ثمَّ شاع الخبرُ أنَّ عُثمانَ قُتِلَ، فأمَر رسولُ الله "},{"id":99,"era":"c1","t":"غَزوةُ خَيبرَ .","s":"اختلَف أهلُ السِّيَرِ في وقتِها على قولين، فقِيلَ: في السَّنةِ السَّابعةِ. وهو قولُ ابنِ إسحاقَ وغيرِه، وقِيلَ: في السَّنةِ السَّادسةِ. وهو قولُ مالكٍ وغيرِه. قال ابنُ القَيِّمِ: والجُمهورُ على أنَّها في السَّابعةِ. وقال ابنُ حَجَرٍ: وهذه الأقوالُ مُتقاربةٌ، والرَّاجحُ منها ما ذكَرهُ ابنُ إسحاقَ، ويُمكنُ الجمعُ بينهما بأنَّ مَن أطلق سَنَةَ سِتٍّ بِناءً على أنَّ ابتداءَ السَّنةِ مِن شهرِ الهِجرةِ ا"},{"id":100,"era":"c1","t":"تَحريمُ لُحومِ الحُمُرِ الأَهْلِيَّةِ ومُتعةِ النِّساءِ يوم خيبر .","s":"في أثناءِ غَزوةِ خَيبرَ حَرَّمَ رسولُ الله صلى الله عليه وسلم لُحومَ الحُمُرِ الأَهلِيَّةِ، وأَخبرَ أنَّها رِجْسٌ، وأمَر بالقُدورِ فأُلقِيتْ وهي تَفورُ بِلُحومِها، وأمَر بغَسلِ القُدورِ بعدُ، وأَحَلَّ حِينئذٍ لُحومَ الخَيْلِ وأَطعَمهُم إيَّاها, كما نَهى صلى الله عليه وسلم عن مُتعةِ النِّساءِ."},{"id":101,"era":"c1","t":"هجرة أبي موسى الأشعري وأصحابه رضي الله عنهم إلى المدينة مروراً بالحَبشةِ .","s":"عن أبي موسى رضي الله عنه قال: بلغَنا مَخرجُ النَّبيِّ صلى الله عليه وسلم ونحن باليَمنِ، فخرَجْنا مُهاجرين إليه، أنا وأَخَوانِ لي أنا أَصغرُهم، أَحدُهما أبو بُردةَ، والآخرُ أبو رُهْمٍ -إمَّا قال: في بِضْعٍ، وإمَّا قال: في ثلاثةٍ وخمسين، أو اثنين وخمسين رجلًا مِن قومي- فرَكِبْنا سَفينةً، فأَلقَتْنا سَفينتُنا إلى النَّجاشيِّ بالحَبشةِ، ووافَقْنا جَعفرَ بنَ أبي طالبٍ وأصحابَه عنده، فقال جَعفرٌ: إنَّ ر"},{"id":102,"era":"c1","t":"مُحاوَلةُ اليَهودِ تَسميمِ رسولِ الله صلَّى الله عليه وسلَّم .","s":"لمَّا اطْمأنَّ رسولُ الله صلى الله عليه وسلم بخَيبرَ بعدَ فَتحِها أَهدَتْ له زَينبُ بنتُ الحارثِ -امرأةُ سَلاَّمِ بنِ مِشْكَمٍ- شاةً مَصْلِيَّةً، وقد سَألتْ أيَّ عُضْوٍ أَحَبُّ إلى رسولِ الله صلى الله عليه وسلم؟ فقِيلَ لها: الذِّراعُ، فأَكثرتْ فيها مِنَ السُّمِّ، ثمَّ سَمَّتْ سائرَ الشَّاةِ، ثمَّ جاءت بها، فلمَّا وَضعتْها بين يَدي رسولِ الله صلى الله عليه وسلم تناوَلَ الذِّراعَ، فَلاكَ منها مُضغةً"},{"id":103,"era":"c1","t":"مراسلة النبي صلى الله عليه وسلم إلى المُلوكِ يَدعوهُم إلى الإسلامِ .","s":"بعدَ رُجوعِ رسولِ الله صلى الله عليه وسلم مِنَ الحُديبيةِ كتَب إلى المُلوكِ يَدعوهُم إلى الإسلامِ, ولمَّا أراد أن يُكاتِبَهُم قِيلَ له: إنَّهم لا يَقرءون كِتابًا إلَّا وعليه خاتمٌ، فاتَّخذَ النَّبيُّ صلى الله عليه وسلم خاتمًا مِن فِضَّةٍ، نَقْشُهُ: محمَّدٌ رسولُ الله، وكان هذا النَّقْشُ ثلاثةَ أَسطُرٍ: محمَّدٌ سطرٌ، ورسولُ سطرٌ، والله سطرٌ. وعن أنسِ بنِ مالكٍ رضي الله عنه قال: « فَكأنِّي بِوَبِيصِ"},{"id":104,"era":"c1","t":"غَزوةُ ذاتِ الرِّقاعِ .","s":"قال جابرُ بنُ عبدِ الله رضي الله عنه: خرج النَّبيُّ صلى الله عليه وسلم إلى ذاتِ الرِّقاعِ مِن نخلٍ، فلَقِيَ جمعًا مِن غَطَفانَ، فلم يكن قِتالٌ، وأخاف النَّاسُ بعضُهم بعضًا، فصَلَّى النَّبيُّ صلى الله عليه وسلم ركعتي الخوفِ، وعن أبي موسى رضي الله عنه قال: خرجنا مع النَّبيِّ صلى الله عليه وسلم في غَزوةٍ ونحن سِتَّةُ نفرٍ، بيننا بَعيرٌ نَعْتَقِبُه، فنَقِبَتْ أَقدامُنا، ونَقِبَتْ قَدمايَ، وسقَطت أَظفا"},{"id":105,"era":"c1","t":"سَرِيَّةُ غالبِ بنِ عبدِ الله اللَّيثيِّ إلى بني المُلَوَّحِ بُقدَيْدٍ .","s":"بعَث رسولُ الله صلى الله عليه وسلم سَرِيَّةَ غالبِ بنِ عبدِ الله اللَّيثيِّ إلى بني المُلَوَّحِ بِقُدَيْدٍ، وكان بنو المُلَوَّحِ قد قَتلوا أصحابَ بشيرِ بن سُوَيْدٍ، فبُعِثت هذه السَّرِيَّةُ لأَخذِ الثَّأرِ، فشَنُّوا الغارةَ في اللَّيلِ فقَتلوا مَن قَتلوا، وساقوا النَّعَمِ، وطاردَهُم جيشٌ كَبيرٌ مِنَ العَدُوِّ، حتَّى إذا قرب مِنَ المسلمين نزل مَطَرٌ، فجاء سَيلٌ عَظيمٌ حال بين الفَريقين. ونجَح المسل"},{"id":106,"era":"c1","t":"سرية زيد بن حارثة إلى أرض حِسْمى .","s":"أرسل الرَّسولُ صلى الله عليه وسلم بكِتابٍ إلى قَيصرِ الرُّومِ وكان حاملَ الكِتابِ هو دِحيةُ بنُ خَليفةَ الكَلبيُّ، فلمَّا كان مِن قَيصرَ ما كان أجاز دِحيةَ بنَ خَليفةَ الكَلبيَّ بمالٍ وكِسوَةٍ، ولمَّا كان دِحيةُ بحِسْمَى في الطَّريقِ لَقِيَهُ ناسٌ مِن جُذَامَ، فقَطعوها عليه، فلم يتركوا معه شيئًا، فجاء دِحيةُ إلى رسولِ الله صلى الله عليه وسلم قبلَ أن يَدخُلَ بيتَه فأخبرَهُ، فبعَث رسولُ الله صلى الل"},{"id":107,"era":"c1","t":"سَرِيَّةُ عُمَرَ بنِ الخطَّابِ رضِي الله عنه إلى (تُرَبَةَ) طائفةٍ مِن هَوازِنَ .","s":"بعَث رسولُ الله صلى الله عليه وسلم عُمَرَ بنَ الخطَّابِ رضِي الله تعالى عنه في ثلاثين رجلًا إلى عَجُزِ هَوازِنَ -مَحِلٌّ بينه وبين مكَّةَ أربعُ ليالٍ بطَريقِ صَنعاءَ يُقالُ له: تُرَبَةُ-. وأَرسلَ صلى الله عليه وسلم دليلًا مِن بني هِلالٍ فكان يَسيرُ اللَّيلَ ويَكْمُنُ النَّهارَ، فأتى الخبرُ لِهَوازنَ فهَربوا، فجاء عُمَرُ بنُ الخطَّابِ رضِي الله تعالى عنه مَحالَّهُم فلم يَجِدْ منهم أحدًا فانصرَف راج"},{"id":108,"era":"c1","t":"سَرِيَّةُ بَشيرِ بنِ سعدٍ الأَنصاريِّ إلى بني مُرَّةَ بِناحِيةِ فَدَكٍ .","s":"بعَث رسولُ الله صلى الله عليه وسلم سَرِيَّةَ بَشيرِ بنِ سعدٍ الأَنصاريِّ إلى بني مُرَّةَ بِناحِيةِ فَدَكٍ، في ثلاثين رجلًا. وخرَج إليهم واسْتاقَ الشَّاءَ والنَّعَمَ، ثمَّ رجَع فأَدْركَهُ الطَّلَبُ عند اللَّيلِ، فرَمَوْهُم بالنَّبْلِ حتَّى فَنِيَ نَبْلُ بَشيرٍ وأصحابِه، فقُتِلوا جميعًا إلَّا بَشيرًا، فإنَّه حُمِلَ وبه رَمَقٌ إلى فَدَكٍ، فأقام عند يَهودَ حتَّى بَرَأَتْ جِراحُهُ، فرجَع إلى المدينةِ."},{"id":109,"era":"c1","t":"سَرِيَّةُ غالبِ بنِ عبدِ الله اللَّيثيِّ إلى بني عُوَالٍ .","s":"بعَث رسولُ الله صلى الله عليه وسلم سَرِيَّةَ غالبِ بنِ عبدِ الله اللَّيثيِّ، إلى بني عُوَالٍ وبني عبدِ بنِ ثَعلبةَ بالمَيْفَعَةِ، وقِيلَ إلى الحُرَقَاتِ مِن جُهَيْنَةَ في مائةٍ وثلاثين رجلًا؛ فهجَموا عليهم جميعًا، وقتَلوا مَن أَشرفَ لهم، واسْتاقوا نَعَمًا وشَاءً، وفي هذه السَّرِيَّةِ قَتَلَ أُسامةُ بنُ زيدٍ نَهِيكَ بن مِرْدَاسٍ بعدَ أن قال: لا إلَه إلَّا الله. فلمَّا قَدِموا وأُخْبِرَ النَّبيُّ صل"},{"id":110,"era":"c1","t":"سَرِيَّةُ عبدِ الله بنِ رَواحةَ إلى خَيبرَ لِقَتلِ يَسيرِ بنِ رِزامٍ اليَهوديِّ .","s":"بلَغ رسولَ الله صلى الله عليه وسلم أنَّ يَسيرَ بنَ رِزامٍ اليَهوديَّ يَجمعُ غَطَفانَ لِيَغزو بهم المدينةَ، فبعَث رسولُ الله صلى الله عليه وسلم عبدَ الله بنَ رَواحةَ في ثلاثين راكبًا إلى يَسيرِ بنِ رِزامٍ حتَّى أَتَوْهُ بِخَيبرَ، فقالوا: أَرسلَنا إليك رسولُ الله صلى الله عليه وسلم لِيَستعمِلَك على خَيبرَ, فلم يزالوا به حتَّى تَبِعَهُم في ثلاثين رجلًا مع كُلِّ رجلٍ منهم رَديفٌ مِنَ المسلمين، فلمَّا "},{"id":111,"era":"c1","t":"سَرِيَّةُ أبي حَدْرَدٍ الأَسلميٍّ إلى الغابةِ .","s":"بعَث رسولُ الله صلى الله عليه وسلم سَرِيَّةَ أبي حَدْرَدٍ الأسلميِّ إلى الغابةِ، وسببُ ذلك أنَّ رجلًا مِن جُشَمِ بنِ مُعاويةَ أَقبلَ في عددٍ كبيرٍ إلى الغابةِ، يُريدُ أن يَجمعَ قَيسًا على مُحارَبةِ المسلمين، فبعَث رسولُ الله صلى الله عليه وسلم أبا حَدْرَدٍ مع رَجلينِ ليأتوا منه بِخَبرٍ وعِلْمٍ، فوصلوا إلى القومِ مع غُروبِ الشَّمسِ، فكَمَنَ أبو حَدْرَدٍ في ناحيةٍ، وصاحِباهُ في ناحيةٍ أُخرى، وأَبطأَ"},{"id":112,"era":"c1","t":"عُمرَةُ الحُديبيةِ وتُسَمَّى (عُمرَةَ القَضاءِ) .","s":"قال ابنُ عبَّاسٍ رضِي الله عنهما: قَدِمَ رسولُ الله صلى الله عليه وسلم وأصحابُه مكَّةَ، وقد وَهَنَتْهُم حُمَّى يَثْرِبَ، قال المشركون: إنَّه يَقدُمُ عليكم غَدًا قومٌ قد وَهَنَتْهُم الحُمَّى، ولَقوا منها شِدَّةً، فجلسوا ممَّا يَلِي الحِجْرَ، وأَمرَهُم النَّبيُّ صلى الله عليه وسلم أن يَرمُلوا ثلاثةَ أَشواطٍ، ويَمشوا ما بين الرُّكنَينِ، لِيَرى المشركون جَلَدَهُم، فقال المشركون: هؤلاء الذين زَعمْتُم أ"},{"id":113,"era":"c1","t":"سَرِيَّةُ ابنِ أبي العَوجاءِ إلى بني سُلَيْمٍ .","s":"بعَث رسولُ الله صلى الله عليه وسلم إلى بني سُلَيْمٍ سَرِيَّةِ ابنِ أبي العَوجاءِ، في خمسين رجلاً، وذلك لِيَدعُوَهُم إلى الإسلامِ؛ فقالوا: لا حاجةَ لنا إلى ما دَعوتَنا، ثمَّ قاتَلوا قِتالًا شَديدًا. جُرِحَ فيه أبو العَوجاءِ، وأُسِرَ رَجُلان مِنَ العَدُوِّ."},{"id":114,"era":"c1","t":"وَفاةُ زَينبَ رضِي الله عنها بنتِ رسولِ الله صلَّى الله عليه وسلَّم .","s":"هي زينبُ بنتُ رسولِ الله صلى الله عليه وسلم، وأَكبرُ أَخواتِها، تَزوَّجَها في حياةِ أمِّها ابنُ خالتِها أبو العاصِ بنُ الرَّبيعِ، فوَلدتْ له أُمامَةَ التي تَزوَّجَ بها عليُّ بنُ أبي طالبٍ بعدَ فاطمةَ، ووَلدتْ له عليَّ بنَ أبي العاصِ، أَسلمتْ زَينبُ وهاجرتْ قبلَ إسلامِ زَوجِها بسِتِّ سنين، قالت أمُّ عَطيَّةَ: لمَّا ماتتْ زَينبُ بنتُ رسولِ الله صلى الله عليه وسلم قال لنا رسولُ الله صلَّى الله عليه و"},{"id":115,"era":"c1","t":"سريَّة أَوْطاسٍ (وادٍ بين مكة والطائف) .","s":"لمَّا فرَغ النَّبيُّ صلى الله عليه وسلم مِن حُنينٍ بعَث أبا عامرٍ على جيشٍ إلى أَوْطاسٍ، فلَقِيَ دُرَيْدَ بنَ الصِّمَّةِ، فقُتِلَ دُريدٌ وهزَم الله أصحابَهُ، قال أبو موسى الأَشعريُّ: وبعَثني مع أبي عامرٍ عُبيدٍ الأَشعريِّ، فرُمِيَ أبو عامرٍ في رُكْبَتِهِ، رَماهُ جُشَمِيٌّ بِسَهمٍ فأَثْبَتَهُ في رُكبتِهِ، فانتَهيتُ إليه فقلتُ: يا عمِّ مَن رَماك؟ فأَشار إليه فقال: ذاك قاتِلي الذي رَماني. فقصدتُ له ف"},{"id":116,"era":"c1","t":"إِسلامُ عَمرِو بنِ العاصِ وخالدِ بنِ الوليدِ وعُثمانَ بنِ طلحةَ رضِي الله عنهم .","s":"قال خالدُ بنُ الوليدِ: لمَّا أراد الله عزَّ وجلَّ ما أَراد مِنَ الخيرِ قذَف في قلبي الإسلامَ وحضَرني رُشدي, وقلتُ قد شَهِدتُ هذه المواطِنَ كُلَّها على محمَّدٍ صلَّى الله عليه وسلَّم فليس مَوطنٌ أَشهدُه إلَّا أَنصرِفُ وأنا أَرى في نَفْسي أنِّي في غيرِ شيءٍ وأنَّ محمَّدًا سيَظهرُ، فلمَّا خرَج رسولُ الله صلَّى الله عليه وسلَّم إلى الحُديبيةِ خَرجتُ في خيلِ المشركين فقمتُ بإزائِه في عُسْفانَ وتَعرَّضت"},{"id":117,"era":"c1","t":"سَرِيَّةُ غالبِ بنِ عبدِ الله اللَّيثيِّ إلى أَصحابِ بَشيرِ بنِ سعدٍ بفَدَكٍ .","s":"بعَث رسولُ الله صلى الله عليه وسلم إلى مُصابِ أَصحابِ بَشيرِ بنِ سعدٍ بفَدَكٍ سَرِيَّةَ غالبِ بنِ عبدِ الله، في مِائتي رجلٍ؛ فأصابوا مِن بني مُرَّةَ نَعَمًا، وقتلوا منهم قَتْلى."},{"id":118,"era":"c1","t":"سَرِيَّةَ كعبِ بنِ عُميرٍ الأنصاريِّ إلى بني قُضَاعَةَ .","s":"بعَث رسولُ الله صلى الله عليه وسلم سَرِيَّةَ ذاتِ أطلح بقِيادةِ كعبِ بنِ عُميرٍ الأنصاريِّ في خمسةَ عشرَ رجلًا إلى بني قُضَاعَةَ؛ حيث كانت قد حَشدتْ جُموعًا كَبيرةً للإغارَةِ على المسلمين، فلَقوا العَدُوَّ، فدَعَوْهُم إلى الإسلامِ، فلم يَستَجيبوا لهم، وأَرشَقوهُم بالنَّبْلِ حتَّى قُتِلوا كُلُّهم إلَّا رجلًا واحدًا، فقد ارْتُثَّ مِن بين القَتْلى."},{"id":119,"era":"c1","t":"سَرِيَّةُ شُجاعِ بنِ وَهْبٍ رضِي الله عنه إلى بني هَوازِنَ .","s":"كانت بنو هَوازِنَ قد مَدَّتْ يدَ المَعونَةِ لأعداءِ المسلمين مِرارًا, فأَرسلَ إليهم رسولُ الله صلى الله عليه وسلم شُجاعَ بنَ وَهْبٍ الأَسديَّ في خمسةٍ وعشرين رجلًا، وهم بالسِّيِّ, ناحيةَ رُكْبَةَ, مِن وراءِ المَعدِن, وهي مِنَ المدينةِ على خمسِ ليالٍ، وأَمرهُ أن يُغِيرَ عليهم, فكان يَسيرُ اللَّيلَ ويكَمُنُ النَّهارَ, حتَّى صَبَّحَهُم وهُم غارون، وقد أَوعزَ إلى أصحابِه ألَّا يُمْعِنوا في الطَّلَبِ، "},{"id":120,"era":"c1","t":"غَزوةُ مُؤْتَةَ .","s":"بعَث رسولُ الله صلى الله عليه وسلم سَرِيَّةً في ثلاثةِ آلافِ مُقاتلٍ على الجيشِ زيدُ بنُ حارثةَ، فإن أُصيبَ فجَعفرُ بنُ أبي طالبٍ، فإنْ أُصيبَ فعبدُ اللهِ بنُ رَواحةَ، وشَيَّعهُم رسولُ الله صلى الله عليه وسلم ووَدَّعهُم، ثمَّ انْصرَف ونهَضوا، فلمَّا بلغوا مَعانَ مِن أرضِ الشَّامِ، أَتاهُم الخبرُ: أنَّ هِرقلَ مَلِكَ الرُّومِ قد نزل أرضَ بني مآبٍ، -أرضَ البَلقاءِ- في مائةِ ألفٍ مِنَ الرُّومِ، ومائةِ"},{"id":121,"era":"c1","t":"غَزوةُ ذاتِ السَّلاسِلِ .","s":"كانت بعدَ غزوة مُؤْتَةَ، وسُمِّيتْ ذاتَ السَّلاسِلِ لأنَّها وقعت بالقُرْبِ مِن ماءٍ يُقالُ له: السَّلْسَلُ. بلَغ النَّبيَّ صلى الله عليه وسلم أنَّ جمعًا مِن قُضاعةَ تَجَمَّعوا وأَرادوا أن يَدنوا مِن أَطرافِ المدينةِ فَدعا النَّبيُّ صلى الله عليه وسلم عَمرَو بنَ العاصِ فعقَد له لِواءً أَبيضًا وبَعثَهُ في ثلاثمائةٍ مِن سَراةِ المُهاجرين والأنصارِ، فكان أَميرُها عَمرَو بنَ العاصِ رضي الله عنه. قال عَ"},{"id":122,"era":"c1","t":"سَرِيَّةُ أبي عُبيدةَ بنِ الجَرَّاحِ رضِي الله عنه إلى سِيفِ البَحرِ .","s":"بعَث رسولُ اللّه صلَّى اللّه عليه وسلَّم أبا عُبيدةَ بنَ الجَرَّاحِ على رأسِ ثلاثمائةِ رجلٍ إلى سِيفِ البَحرِ, وكان الغَرَضُ مِن هذه السَّرِيَّةِ رَصْدَ عِيرٍ لقُريشٍ، ومُحارَبةَ حَيٍّ مِن جُهينةَ, وزَوَّدَهُم جِرابًا مِن تمرٍ, فجعل أبو عُبيدةَ يَقُوتُهُم إيَّاهُ, حتَّى صار إلى أن يَعُدَّهُ لهم عددًا, حتَّى كان يُعطي كُلَّ رجلٍ منهم كُلَّ يومٍ تمرةً, فقَسَمَها يومًا فنَقصَتْ تمرةٌ عن رجلٍ, فوَجَد "},{"id":123,"era":"c1","t":"سَرِيَّةُ أبي قَتادةَ الأَنصاريِّ إلى خَضِرَة .","s":"بعَث رسولُ الله صلى الله عليه وسلم أبا قَتادةَ بنَ رِبْعِيٍّ رضي الله عنه في سَرِيَّةٍ إلى خَضِرَة؛ وذلك لأنَّ بني غَطَفَانَ كانوا يَحْتَشِدون في خَضِرَة -وهي أرضُ مُحَارِبٍ بِنَجْدٍ- فبعَثهُ صلى الله عليه وسلم في خمسةَ عشرَ رجلًا، فقَتَلَ منهم، وسَبَى وغَنِمَ، وكانت غَيبتُه خمسَ عشرةَ ليلةً."},{"id":124,"era":"c1","t":"سَرِيَّةُ أبي قَتادةَ رضِي الله عنه إلى بَطْنِ إِضَمٍ .","s":"لمَّا نَقضَتْ قُريشٌ ومَن معها العهدَ الذين الذي بينهم وبين المسلمين في الحُديبيةِ عزَم رسولُ الله صلى الله عليه وسلم على المَسيرِ إليهم، أمَر النَّاسَ بالجِهازِ وأَعلمَهُم أنَّه سائِرٌ لمكَّةَ، وقال: (اللَّهمَّ خُذِ العُيونَ والأَخبارَ عن قُريشٍ حتَّى نَبْغَتَها في بِلادِها). وزِيادةٌ في الإخفاءِ والتَّعمِيَةِ بعَث رسولُ الله صلى الله عليه وسلم سَرِيَّةً قَوامُها ثَمانيةُ رِجالٍ، تحت قِيادةِ أبي "},{"id":125,"era":"c1","t":"غَزوةُ فَتحِ مكَّةَ .","s":"كان سببُها أنَّ المشركين نقَضوا العهدَ الذي بينهم وبين رسولِ الله صلى الله عليه وسلم، فأَغاروا على إحدى القَبائلِ المُحالفةِ للرَّسولِ عليه الصَّلاةُ والسَّلامُ، وهي قَبيلةُ خُزاعةَ، ولمَّا عَلِمَ النَّبيُّ صلى الله عليه وسلم بالأَمرِ أَمَرَ النَّاسَ بالتَّجَهُّزِ دون أن يُخبِرَهُم بوِجْهَتِه، ثمَّ مضى حتَّى نزَل بمَرِّ الظَّهرانِ وهو وادٍ قَريبٌ مِن مكَّةَ. فعنِ ابنِ عبَّاسٍ رضِي الله عنهما: أنَّ"},{"id":126,"era":"c1","t":"سَرِيَّةُ خالدِ بنِ الوليدِ رضِي الله عنه إلى العُزَّى بنَخْلَةَ .","s":"لمَّا اطْمأَنَّ رسولُ الله صلى الله عليه وسلم بعدَ الفتحِ بعَث خالدَ بنَ الوليدِ إلى العُزَّى لخمسِ ليالٍ بَقِينَ مِن هذا الشَّهرِ الكريمِ لِيَهدِمَها، وكانت بِنَخْلَةَ، وكانت لقُريشٍ وجميعِ بني كِنانةَ, وهي أَعظمُ أَصنامِهم. وكان سَدَنَتُها بني شَيبانَ؛ فخرَج إليها خالدٌ في ثلاثين فارسًا حتَّى انتهى إليها فهَدمَها. ولمَّا رجَع إليها سألهُ رسولُ الله صلى الله عليه وسلم (هل رأيتَ شيئًا؟). قال: لا. "},{"id":127,"era":"c1","t":"سَرِيَّةُ عَمرِو بنِ العاصِ رضِي الله عنه إلى سُواعٍ، صَنَمِ هُذيلٍ .","s":"بعَث رسولُ الله صلى الله عليه وسلم عَمرَو بنَ العاصِ إلى سُواعٍ لِيَهدِمَهُ، وسُواعٌ صَنَمٌ لقومِ نوحٍ عليه السَّلامُ، ثمَّ صار بعدَ ذلك لقَبيلةِ هُذيلٍ المُضَريَّةِ, وظَلَّ هذا الوَثَنُ مَنصوبًا تَعبُدهُ هُذيلٌ وتُعَظِّمُهُ, حتَّى إنَّهم كانوا يَحُجُّون إليه حتَّى فُتِحَتْ مكَّةُ ودخلَت هُذيلٌ فيمَن دخَل في دينِ الله أفواجًا، وكان مَوضعُه بِرُهاطٍ على قُرابةِ 150 كيلو مترًا شمالَ شرقيِّ مكَّةَ، ف"},{"id":128,"era":"c1","t":"سَرِيَّةُ خالدِ بنِ الوليدِ رضِي الله عنه إلى بني جَذِيمَةَ .","s":"لمَّا رجَع خالدُ بنُ الوليدِ مِن هَدْمِ العُزَّى بعَثهُ رسولُ الله صلى الله عليه وسلم إلى بني جَذيمَةَ داعِيًا إلى الإسلامِ لا مُقاتِلًا, فخرَج في ثلاثمائةٍ وخمسين رجلًا مِنَ المُهاجرين والأنصارِ وبني سُليمٍ، فانتهى إليهم فدَعاهُم إلى الإسلامِ فلم يُحسِنوا أن يَقولوا: أَسلَمْنا، فجعلوا يَقولون: صَبَأْنا، صَبَأْنا. -فحملها خالد على أنها سُخرية بالإسلام لأن قريشًا كانت تقول لمن أسلم صبأ تعييرا له- ف"},{"id":129,"era":"c1","t":"غزوة الطَّائفِ بعد أن حاصرها المسلمون أربعين ليلة .","s":"بعدَ أن تَعقَّبَ المسلمون فُلولَ الهارِبين مِن هَوازِنَ في أَوْطاسٍ ونَخْلةَ، تَوجَّهوا للقَضاءِ على ثَقيفٍ التي فَرَّتْ مِن حُنينٍ وأَوْطاسٍ، وتَحصَّنتْ بحُصونِها المَنيعَةِ في الطَّائفِ، وفي صَحيحِ مُسلمٍ: أنَّ الرَّسولَ صلى الله عليه وسلم ومَن معه مِنَ المسلمين حاصروا المشركين في الطَّائفِ أربعين ليلةً.عن أبي نَجيحٍ السُّلميِّ قال: حاصَرْنا مع نَبيِّ الله صلَّى الله عليه وسلَّم حِصْنَ الطَّائفِ"},{"id":130,"era":"c1","t":"غَزوةُ حُنينٍ (هَوازِنَ) .","s":"حُنينُ: وادٍ إلى جَنبِ ذي المَجازِ، قريبٌ مِنَ الطَّائفِ، وبينه وبين مكَّةَ بضعةَ عشرَ مِيلًا مِن جِهَةِ الشرائع والسيل الكبير، وقِيلَ سُمِّيَ بِحُنَيْنٍ؛ نِسبَةً إلى رَجلٍ يُدعَى: حُنينَ بنَ قابِثَةَ بنِ مَهْلائِيلَ. وكان النَّبيُّ صلى الله عليه وسلم قد أقامَ بمكَّةَ 19 يومًا، حتَّى جاءَتْ هَوازِنُ وثَقيفٌ فنزلوا بحُنينٍ يُريدون قِتالَ النَّبيِّ صلى الله عليه وسلم، وكانوا قد جمَعوا قبلَ ذلك حين س"},{"id":131,"era":"c1","t":"عُمرَةُ الجِعْرانَةِ .","s":"ثبَت أنَّ النَّبيَّ صلى الله عليه وسلم اعْتمَرَ مِنَ الجِعْرانةِ عامَ حُنينٍ، وهذه العُمرَةُ هي الثَّالثةُ بعدَ عُمرَةِ الحُديبيَةِ وعُمرَةِ القَضاءِ. قال ابنُ حَجَرٍ: فإنَّه صلى الله عليه وسلم أَحرَمَ مِنَ الجِعْرانةِ ودخَل مكَّةَ ليلًا فقَضى أمْرَ العُمرَةِ ثمَّ رجَع ليلًا فأَصبحَ بالجِعْرانةِ كَبائِتٍ. قال إبراهيمُ النَّخَعيُّ: كانوا يَستَحِبُّون أن يَدخلوا مكَّةَ نهارًا ويَخرُجوا منها ليلًا. و"},{"id":132,"era":"c1","t":"وَفاةُ أمِّ كُلثومٍ بنتِ رسولِ الله صلَّى الله عليه وسلَّم .","s":"هي أمُّ كُلثومٍ بنتُ رسولِ الله صلى الله عليه وسلم- البَضْعَةُ الرَّابعةُ النَّبَوِيَّةُ، أمُّها خَديجةُ بنتُ خُويلدٍ رضي الله عنها، يُقالُ تَزوَّجها عُتَيْبةُ بنُ أبي لَهبٍ ثمَّ فارَقَها، وأَسلَمتْ وهاجَرتْ بعدَ النَّبيِّ صلى الله عليه وسلم، فلمَّا تُوفِّيتْ أُختُها رُقيَّةُ تزَوَّجَ بها عُثمانُ في رَبيعٍ الأوَّلِ سَنةَ ثلاثٍ فلم تَلِدْ له."},{"id":133,"era":"c1","t":"عامُ الوُفودِ .","s":"كان مِن أَبرَزِ نَتائجِ فَتحِ مكَّةَ أن أَخذتْ قَبائلُ العربِ وأَفرادُها يُبادِرون بإسلامِهم؛ لأنَّهم كانوا يَنتظِرون نَتيجةَ الصِّراعِ بين المسلمين وقُريشٍ، فعن عَمرِو بنِ سَلمةَ قال: كُنَّا بماءٍ مَمَرَّ النَّاسِ، وكان يَمُرُّ بِنا الرُّكبانُ فنسألُهم: ما للنَّاسِ، ما للنَّاسِ؟ ما هذا الرَّجلُ؟ فيقولون: يَزعُم أنَّ الله أَرسلَهُ، أَوْحى إليه -أو: أَوْحى الله بكذا- فكنتُ أَحفظُ ذلك الكلامَ، وكأنّ"},{"id":134,"era":"c1","t":"نزول فريضة الحج .","s":"كان الحَجُّ مَعروفًا قبلَ البعثة، فإبراهيمُ أَذَّنَ في النَّاسِ بالحَجِّ، وحَجَّ موسى وغيرُه مِنَ الأنبياءِ، وبَقِيَ الحَجُّ مَعروفًا ولكن بَدَّلَ فيه المُشركون ما بَدَّلوا، وأَوَّلُ مَن بَدَّلَ عَمرُو بنُ لُحَيٍّ، ثمَّ فرَض الله تعالى الحَجَّ على المسلمين لِمَن اسْتَطاع إليه سَبيلًا، {وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا} [آل عمران: 97]، وبَيَّن الرَّسولُ صلى"},{"id":135,"era":"c1","t":"وَفاةُ النَّجاشِيِّ صاحِبِ الحَبشةِ رضِي الله عنه .","s":"هو أَصْحَمَةُ بنُ أَبْجَرَ مَلِكُ الحَبشةِ، والنَّجاشيُّ لَقبٌ له ولمُلوكِ الحَبشةِ، ومَعْنى: أَصْحَمَةَ: عَطِيَّةُ، وقِيلَ: عَطِيَّةُ الله، وقِيلَ: عَطاءٌ.تَوَلَّى الحُكمَ بعدَ مَوتِ عَمِّهِ، وبعدَ سَنواتٍ مِن حُكمِهِ وانتشر وانْتِشارِ عَدْلِه أَسلمَ في عَهدِ النَّبيِّ صلى الله عليه وسلم، وأَحسنَ إلى المسلمين الذين هاجَروا إلى أَرضِه، قال رسولُ الله صلَّى الله عليه وسلَّم لأَصحابِه عن النَّجاشيِّ"},{"id":136,"era":"c1","t":"غَزوةُ تَبوكَ وجَيشُ العُسْرَةِ .","s":"تَبوكُ مَوضِعٌ بين وادي القُرى والشَّامِ، قال أبو موسى الأَشعريُّ رضي الله عنه: (أَرسلَني أَصحابي إلى رسولِ الله صلى الله عليه وسلم أَسأَلُه الحُمْلانَ لهم إذ هُم معه في جَيشِ العُسْرَةِ، وهي غَزوةُ تَبوكَ..). وحديث أبي موسى رضي الله عنه فيه دِلالةٌ على ما كان عليه الصَّحابةُ مِنَ العُسْرِ الشَّديدِ في المالِ والزَّادِ والرَّكائِبِ، كما رَوى مُسلمٌ أيضًا عن أبي هُريرةَ رضي الله عنه ما وقع للمسلمين"},{"id":137,"era":"c1","t":"وَفاةُ رَأْسِ المُنافقين عبدِ الله بنِ أُبَيٍّ بن ابنِ سَلولَ .","s":"هو عبدُ الله بنُ أُبَيٍّ بن ابنُ سَلولَ، رَأْسُ المُنافقين، مَرِضَ في ليالٍ بَقِينَ مِن شَوَّالٍ بعدَ أن رجَع رسولُ الله صلى الله عليه وسلم مِن غَزوةِ تَبوكَ, ولمَّا مات اسْتَغفَرَ له رسولُ اللّه صلى الله عليه وسلم، وصلَّى عليه بعدَ أن حاوَلَ عُمَرُ مَنْعَهُ عن الصَّلاةِ عليه، وقد نزَل القُرآنُ بعدَ ذلك بِمُوافَقَةِ عُمَرَ رضي الله عنه، وإنَّما صلَّى عليه رسولُ الله صلى الله عليه وسلم إجراءً له عل"},{"id":138,"era":"c1","t":"حَجَّةُ أبي بكرٍ الصِّدِّيقِ ونُزولُ سُورةِ بَراءَة .","s":"بعَث النَّبيُّ صلى الله عليه وسلم أبا بكرٍ أَميرًا على الحَجِّ بعدَ انْسِلاخِ ذي القَعدةِ لِيُقيمَ للمسلمين حَجَّهُم -والنَّاسُ مِن أهلِ الشِّركِ على مَنازِلهم مِن حَجِّهِم- فخرَج أبو بكرٍ رضِي الله عنه ومَن معه مِنَ المسلمين، وقد بعَث عليه الصَّلاةُ والسَّلامُ عَلِيًّا رضي الله عنه بعدَ أبي بكرٍ الصِّدِّيقِ رضي الله عنه لِيكونَ معه، ويَتوَلَّى علِيٌّ بِنَفْسِه إبلاغَ البَراءةِ إلى المشركين نِيابَ"},{"id":139,"era":"c1","t":"تَتابُعُ الوُفودِ إلى النَّبيِّ صلَّى الله عليه وسلَّم .","s":"بَقِيَتِ الوُفودُ تَتابَعُ إلى رسولِ الله صلَّى الله عليه وسلَّم، وكان بينها وَفْدُ نَصارى نَجْرانَ، ومصالحتهم وصالَحَهُم على الجِزْيَةِ، وجعَل لهم ذِمَّةً."},{"id":140,"era":"c1","t":"وَفاةُ إبراهيمَ ابنِ النَّبيِّ صلَّى الله عليه وسلَّم .","s":"إبراهيمُ ابنُ النَّبيِّ صلى الله عليه وسلم، وأمُّهُ مارِيَةُ القِبْطِيَّةُ، وقد كان جَميعُ أَولادِ النَّبيِّ صلى الله عليه وسلم مِن خَديجةَ رضي الله عنها، ما عَدا إبراهيمَ فمِن مارِيَةَ القِبطيَّةِ المِصريَّةِ رضي الله عنها، قال أنسُ بنُ مالكٍ رضي الله عنه: «ما رَأيتُ أحدًا كان أَرحمَ بالعِيالِ مِن رسولِ الله صلى الله عليه وسلم. قال: كان إبراهيمُ مُسْتَرْضِعًا له في عَوالي المَدينةِ، فكان يَنطلِقُ"},{"id":141,"era":"c1","t":"حَجَّةُ الوَداعِ وتسمى حَجَّةُ الإسلامِ أو حَجَّةُ البَلاغِ .","s":"سُمِّيَتْ حَجَّةَ الوَداعِ؛ لأنَّه عليه الصَّلاةُ والسَّلامُ وَدَّعَ النَّاسَ فيها، ولم يَحُجَّ بعدَها، وسُمِّيَتْ حَجَّةَ الإسلامِ؛ لأنَّه عليه السَّلامُ لم يَحُجَّ مِنَ المدينةِ غيرَها، وسُمِّيَتْ حَجَّةَ البَلاغِ؛ لأنَّه عليه السَّلامُ بلَّغَ النَّاسَ شَرْعَ الله في الحَجِّ قَولًا وفِعلًا، ولم يكنْ بَقِيَ مِن دَعائِمِ الإسلامِ وقَواعِدِهِ شيءٌ إلَّا وقد بيَّنَهُ عليه السَّلامُ، فلمَّا بيَّنَ له"},{"id":142,"era":"c1","t":"خروج الأسود العنسي في اليمن وقتله على يد فيروز الديلمي .","s":"خرج الأسوَدُ العَنْسيُّ -واسمُه عَبهلةُ بنُ كَعبِ بنِ غَوثٍ- في آخِرِ حياةِ رَسولِ اللهِ صلَّى اللهُ عليه وسلَّم في سَبْعِمائةِ مقاتلٍ، فكَتَب إلى عمَّالِ النَّبيِّ صلَّى اللهُ عليه وسلَّم: أيُّها المتمَرِّدون علينا، أمسِكوا علينا ما أخَذْتُم مِن أرضِنا، ووفِّروا ما جمعتُم؛ فنحن أَولى به، وأنتم على ما أنتم عليه، ثمَّ توجَّه مع مقاتِلِيه إلى نجرانَ فأخَذَها، ثمَّ قَصَد صنعاءَ، فخرج إليه شَهرُ بنُ ب"},{"id":143,"era":"c1","t":"أبو بكر الصديق يتصدي لقتال أهل الردة ومانعي الزكاة .","s":"لَمَّا قُبِضَ رَسولُ اللهِ صلَّى اللهُ عليه وسلَّم ارتدَّت العَرَبُ، واشرأَبَّ النِّفاقُ، وعَظُمَ الخَطْبُ واشتدَّت الحالُ، وأنفذ الصِّديقُ جَيشَ أُسامةَ، فقَلَّ الجندُ عند الصِّدِّيقِ، فطمَعِتَ كثيرٌ من الأعرابِ في المدينةِ، وراموا أن يَهجُموا عليها، فجَعَل الصِّدِّيقُ على أنقابِ المدينةِ حُرَّاسًا يبَيتون بالجُيوشِ حولَها، وجعَلَت وفودُ العَرَبِ تَقدَمُ المدينةَ يُقِرُّونَ بالصَّلاةِ ويمتنعون من"},{"id":144,"era":"c1","t":"إرسالُ خالدِ بن الوَليد لِدَعْم عَمليَّات فَتْح العِراق  .","s":"لمَّا انتهى خالدُ بن الوَليد رضِي الله عنه مِن اليَمامَة جاء الأَمْر بالتَّوَجُّهِ للعِراق لِدَعْم المُثَنَّى بن حارِثةَ، فسار خالدٌ إلى الحِيرَةِ والْتَقى بجيشِ المُثَنَّى وجيشِ عِياضِ بن غَنْمٍ بهُرْمُزَ في الأُبُلَّةِ، وقد حَدَثت عِدَّةُ مَعارك في تلك المناطق التي تُعرَف بالمنطقة الشَّرقيَّة التي كانت تحت سَيطرة الفُرْس، وفُتِحَت عِدَّةُ مناطق كالحِيرَةِ والأَنْبارِ ودُومَةِ الجَنْدَلِ والفِراض"},{"id":145,"era":"c1","t":"خروج أبي بكر إلى ذي القصة (موضع قريب من المدينة المنورة) حين عقد ألوية الأمراء الأحد عشر .","s":"بعد ما جَمَّ جيشُ أسامةَ واستراحوا، ركِبَ الصِّدِّيقُ في المسلمين شاهِرًا سيفَه مسلولًا، من المدينةِ إلى ذي القصَّةِ، وعلي بن أبي طالبٍ يقودُ براحلةِ الصِّدِّيقِ رَضِيَ اللهُ عنهما، فسأله الصَّحابةُ، وألحُّوا عليه أن يرجِعَ إلى المدينةِ، وأن يَبعَثَ لقِتالِ الأعرابِ غيرَه ممَّن يؤمِّرُه من الشُّجعانِ الأبطالِ، فأجابهم إلى ذلك، وعَقَد لهم الألْوِيَةَ لأحَدَ عَشَرَ أميرًا، وذلك لقتال طليحة بن خويلد،"},{"id":146,"era":"c1","t":"قتال خالد بن الوليد طليحة الأسدي ومن التف حوله .","s":"لَمَّا توجَّه خالِدُ مِن ذي القصَّةِ وفارقه الصِّدِّيقُ، واعَدَه أنَّه سيلقاه من ناحيةِ خيبَرَ بمَن معه من الأمراءِ، وأظهروا ذلك ليُرعِبوا الأعرابَ، وأمَرَه أن يذهَبَ أوَّلًا إلى طليحةَ الأسديِّ، ثمَّ يذهَبَ بعده إلى بني تميمٍ، وكان طليحةُ بنُ خُوَيلدٍ في قَومِه بني أسَدٍ، وفي غَطفانَ، وانضَمَّ إليهم بنو عبسٍ وذبيان، وبَعَث إلى بني جديلةَ والغوثِ وطَيِّئ يستدعيهم إليه، وجَعَل خالدُ بن الوليدِ يتأت"},{"id":147,"era":"c1","t":"قصة سجاح وبني تميم وزواجها من مسيلمة الكذاب .","s":"كانت بنو تميمٍ قد اختَلَفت آراؤُهم أيَّامَ الرِّدَّةِ؛ فمنهم من ارتدَّ ومَنَع الزَّكاةَ، ومنهم من بَعَث بأموالِ الصَّدَقاتِ إلى الصِّدِّيقِ، ومنهم من توقَّف لينظُرَ في أمرِه، فبينما هم كذلك إذ أقبَلَت سَجاحُ بنتُ الحارِثِ بنِ سُوَيدِ بنِ عقفانَ التَّغلِبيَّةُ من الجزيرةِ، وهي من نصارى العَرَبِ، وقد ادَّعَت النبُوَّة، ومعها جنودٌ مِن قَومِها ومن التَفَّ بهم، وقد عزموا على غَزوِ أبي بكرٍ الصِّدِّيقِ"},{"id":148,"era":"c1","t":"قتال خالد بن الوليد رضي الله عنه مالك بن نويرة اليربوعي التميمي .","s":"كان مالِكُ بنُ نُوَيرةَ قد صانَعَ سَجاحَ حينَ قَدِمَت من أرضِ الجزيرةِ، فلمَّا اتَّصَلت بمُسَيلِمةَ الكَذَّابِ، ثمَّ ترحَّلَت إلى بلادِها، نَدِمَ مالِكٌ على ما كان من أمرِه، وتلَوَّم في شأنِه، وهو نازِلٌ بمكانٍ يقالُ له: البِطاحُ في نجد، فقَصَدَها خالدٌ بجُنودِه وتأخَّرت عنه الأنصارُ، وقالوا: إنَّا قد قَضَينا ما أمَرَنا به الصِّدِّيقُ، فقال لهم خالِدٌ: إنَّ هذا أمرٌ لا بدَّ مِن فِعْلِه، وإنَّه لم "},{"id":149,"era":"c1","t":"قتال العلاء بن الحضرمي رضي الله عنه أهل البحرين (الساحل الشرقي من الجزيرة العربية) .","s":"كان مِن خَبَرِ أهلِ البَحرين أنَّ رَسولَ اللهِ صلَّى اللهُ عليه وسلَّم كان قد بَعَث العلاءَ بنَ الحَضْرميِّ إلى مَلِكِها؛ المنذِرِ بن ساوى العَبْديِّ، وأسلَمَ على يَدَيه وأقام فيهم الإسلامَ والعَدْلَ، فلمَّا توفِّيَ رسولُ الله صلَّى اللهُ عليه وسلَّم، توفِّي المنذِرُ بعده بقليلٍ، فلما مات المنذِرُ ارتدَّ أهلُ البحرينِ، وملَّكوا عليهم الغَرورَ، وهو المنذِرُ بنُ النُّعمانِ بنِ المنذِرِ. وقال قائِلُه"},{"id":150,"era":"c1","t":"قتال خالد بن الوليد رضي الله عنه مسيلمة الكذاب ووقعة حديقة الموت .","s":"بعث الصِّدِّيقُ خالدَ بنِ الوليدِ إلى قِتالِ مُسَيلِمةَ الكَذَّابِ وقَومِه من بني حَنيفةَ باليمامةِ، وأوعب معه المسلمون، وعلى الأنصارِ ثابتُ بنُ قيسِ بنِ شماسٍ، فسار لا يمُرُّ بأحدٍ مِن المرتدِّين إلَّا نكَّل بهم، وقد اجتاز بخُيولٍ لأصحابِ سَجاحٍ فشَرَّدهم وأمَرَ بإخراجِهم مِن جزيرةِ العَرَبِ، وأردف الصِّدِّيقُ خالِدًا بسَرِّيةٍ لتكونَ رِدءًا له من ورائِه، فلمَّا سَمِع مُسَيلِمةُ بقدومِ خالدٍ عَسك"},{"id":151,"era":"c1","t":"ردة أهل عمان والمهرة في عهد أبي بكر الصديق رضي الله عنه .","s":"نبَغَ في أهلِ عُمانَ رجُلٌ يقالُ له: ذو التَّاجِ؛ لقيطُ بنُ مالكٍ الأزديُّ، وكان يسَمَّى في الجاهليَّةِ الجلنديَّ، فادَّعى النبُوَّةَ، وتابعه الجَهَلةُ مِن أهلِ عُمانَ، فتغَلَّب عليها وقَهَر جيفرًا وعبادًا وألجأَهما إلى أطرافِها من نواحي الجبالِ والبَحرِ، فبعث جيفرٌ إلى الصِّدِّيقِ فأخبَرَه الخَبَر واستجاشَه، فبعث إليه الصِّدِّيقُ بأميرينِ، وهما حُذَيفةُ بنُ محصنٍ الحِمْيَريَّ، وعَرْفجةُ البارقيُّ"},{"id":152,"era":"c1","t":"مُصيبَةُ المسلمين الكُبرى بِوَفاةِ رسولِ الله صلَّى الله عليه وسلَّم .","s":"اشْتَكى رسولُ الله صلى الله عليه وسلم بعدَ عَودتِه مِن حَجَّةِ الوَداعِ، حتَّى اشْتَدَّ وَجَعُهُ وهو في بيت مَيمونَةَ رضي الله عنها، فدَعا نِساءَهُ فاسْتأذَنَهُنَّ في أن يُمَرَّضَ في بيتِ عائشةَ رضي الله عنها، قالت عائشةُ رضي الله عنها: كان النَّبيُّ صلى الله عليه وسلم يقولُ في مَرضِهِ الذي مات فيه: «يا عائشةُ ما أَزالُ أَجِدُ أَلَمَ الطَّعامِ الذي أَكلتُ بِخَيبرَ، فهذا أَوانُ وَجَدْتُ انْقِطاعَ أ"},{"id":153,"era":"c1","t":"أبو بكرٍ الصِّدِّيق رضِي الله عنه يَتولَّى الخِلافةَ (بَيْعة السَّقيفَة) .","s":"توفِّي رسولُ الله صلَّى الله عليه وسلَّم ولم يَنُصَّ على الخليفةِ مِن بعدِه صَراحةً - وإنَّ كانت هناك إشاراتٌ ودِلالاتٌ مِن النَّبيّ صلَّى الله عليه وسلَّم على تَوْلِيَةِ أبي بكرٍ -والله أعلم- ثمَّ اجتمع الأنصارُ في سَقيفَة بني ساعِدة ليُبايعوا رجلًا منهم، وهو سعدُ بن عُبادَة، فحضر المُهاجرون إليهم، وأخبرهم أبو بكرٍ أنَّ هذا الأمْرَ يجب أن يكونَ في قُريش، فهُمْ أوسطُ العرب نَسَبًا ودارًا، ثمَّ رشّ"},{"id":154,"era":"c1","t":"بَعْثُ أُسامةَ بن زيدٍ رضِي الله عنه إلى الشَّام .","s":"كان زيدُ بن حارِثةَ قد اسْتُشْهِدَ في مُؤْتةَ، فلمَّا أراد رسولُ الله صلَّى الله عليه وسلَّم غزوَ تلك الجِهات جَهَّز جيشًا وأَمَّر عليهم أُسامةَ بن زيدِ بن حارِثةَ، وأَمَرهُ أن يَصِلَ إلى البَلْقاء، فتَجَهَّزَ الجيشُ وتَعَبَّأَ، ولكنَّ هذا الجيشَ لم يَنفذْ بسبب وَفاة النَّبيّ صلَّى الله عليه وسلَّم، فلمَّا تَولَّى أبو بكرٍ الخِلافةَ كان أوَّل شيء فعله هو إنفاذ جيشِ أُسامةَ وإرساله كما أراد النَّبي"},{"id":155,"era":"c1","t":"خروج أبي بكر الصديق بالمسلمين لقتال المرتدين الذين غاروا على المدينة وانتصاره عليهم .","s":"لم يَلبَثِ المسلمون بعد تحذيرِ أبي بكرٍ الصِّدِّيقِ لهم من الأعرابِ المرتدِّينَ إلَّا ثلاثًا، حتى طَرَقوا المدينةَ غارةً، وخَلَّفوا نِصفَهم بذي حسى ليكونوا رِدءًا لهم، فأرسَلَ الحَرَسُ إلى أبي بكرٍ يخبرونَه بالغارةِ، فبعث إليهم: أنِ الزَموا مكانَكم، ثمَّ ركِبَ الصِّدِّيقُ في أهلِ المدينةِ وأمراءِ الأنقابِ، إلى مَن حَولَ المدينةِ مِن الأعرابِ الذين أغاروا عليها، فما طَلَع الفَجرُ إلَّا وهم والعَدُو"},{"id":156,"era":"c1","t":"غزو أبي بكر بني عبس وذبيان في الربذة بالأبرق .","s":"لَمَّا قَدِمَ أسامةُ بنُ زيدٍ مِن بَعْثِه للرُّومِ استخلفه أبو بكرٍ على المدينةِ، وأمره ومن معه أن يُريحوا ظَهْرَهم، ثم ركب أبو بكر في الذين كانوا معه من المسلمين، فقالوا له: لو رجعتَ إلى المدينةِ وأرسلْتَ رجلًا، فقال: واللهِ لا أفعَلُ، ولأواسِيَنَّكم بنفسي، فخرج في تعبئتِه النُّعمانُ وعبدُ اللهِ وسُوَيدُ بنو مُقرنٍ على ما كانوا عليه في الوقعةِ السابقةِ، حتى نزل على أهلِ الربذةِ بالأبرَقِ، وهناك ج"},{"id":157,"era":"c1","t":"وَفاةُ فاطِمةَ رضِي الله عنها بنتِ رسولِ الله صلَّى الله عليه وسلَّم .","s":"سَيِّدةُ نِساءِ العالمين في زمانِها، بنتُ سَيِّدِ الخَلْقِ رسولِ الله صلَّى الله عليه وسلَّم أبي القاسم محمَّد بن عبدِ الله بن عبدِ المُطَّلِب بن هاشم بن عبدِ مَناف القُرشيَّة الهاشِميَّة وأمّ الحَسَنَيْنِ. أمّها خديجةُ بنتُ خويلدٍ، وُلِدَتْ قبلَ البعثة بقليلٍ، وتَزوَّجها علِيُّ بن أبي طالبٍ بعدَ بدرٍ، وقِيلَ: بعدَ أُحُدٍ, فوَلدَت له الحسنَ والحُسينَ ومُحسنًا وأمَّ كُلثومٍ وزَينبَ. وهي أصغرُ بناتِ"},{"id":158,"era":"c1","t":"مَعركةُ ذاتِ السَّلاسِل وهَزيمةُ الفُرْس بقِيادةِ خالدِ بن الوَليد .","s":"قَدِمَ خالدٌ العِراقَ لِمُساندَةِ المُثَنَّى بأَمْرٍ مِن أبي بكرٍ ومعه عشرةُ آلافِ مُقاتِل، ومع المُثَنَّى وأصحابِه ثَمانيةُ آلافٍ، وجعل على مُقَدِّمَتِه المُثَنَّى وبَعدَهُ عَدِيَّ بن حاتم، وجاء خالدٌ بَعدهُما، وواعدهما الحَفِيرَ ليُصادِموا عَدُوَّهُم، وكان ذلك الفَرْجُ أعظمَ فُروجِ فارِسَ وأشدَّها شَوْكةً، وكان صاحبُهُ هُرْمَزَ، وهو سيِّئُ المُجاورةِ للعربِ، فكلُّهم عليه حنق، وكانوا يَضرِبونه مث"},{"id":159,"era":"c1","t":"أبو بكرٍ الصِّدِّيق رضِي الله عنه يأمُر بجَمْعِ القُرآنِ .","s":"عَهِدَ أبو بكرٍ الصِّدِّيق رضِي الله عنه إلى زيدِ بن ثابتٍ بجَمْعِ نُصوصِ القُرآن وخاصّة بعدَ مَوت عددٍ كبيرٍ من حفظة القرآن في اليَمامةِ، وكان هذا الأمرُ غيرَ مقبول لدى الصَّحابة رضِي الله عنهم في البداية، ولكنَّ الله شرَح صُدورَهم له كما شرَح صدر أبي بكرٍ له، فكَلَّفَ أبو بكرٍ زيدَ بن ثابتٍ بمُهِمَّةِ الكِتابة، فقال لزيدٍ: إنَّك رجلٌ شابٌّ عاقل لا نَتَّهِمك, قد كُنتَ تكتبُ الوَحيَ لرسولِ الله صل"},{"id":160,"era":"c1","t":"فَتْحُ بَلدةِ أَمْغِيشِيا بقِيادَةِ خالدِ بن الوَليد  .","s":"فتَح المسلمون بقِيادةِ خالدِ بن الوَليد بلدَةَ أَمْغِيشِيا، وكانت مِصْرًا كالحِيرَةِ، وقِيلَ: اسمها منيشيا، وهي تقعُ على نهرِ الفُراتِ، ولم يقع بأَمْغِيشِيا قِتالٌ، وإنَّما هجرها أهلُها بعدَ هزيمةِ الفُرْس في أُلَّيْس، فدخَلها المسلمون فاتحين، وأصابوا فيها ما لم يُصيبوا مِثلَه لأنَّ أهلَها أَعجَلَهُم المسلمون أن يَنقُلوا أموالَهم وأثاثَهم وكِراعَهم وغيرَ ذلك، بلَغ سهمُ الفارسِ ألفا وخمسمائة، سِوى "},{"id":161,"era":"c1","t":"وَقعةُ الوَلَجَةِ وهَزيمةُ الفُرْسِ بقِيادةِ خالدِ بن الوَليد\n  .","s":"قامت وَقعةُ الوَلَجَةِ بين الفُرْس والمسلمين بقيادةِ خالدِ بن الوَليد رضِي الله عنه، والوَلَجَةُ مكان في العِراق، وسُمِّيت المعركة باسمه لوُقوع الأحداثِ فيه, لمَّا وقع الخبرُ بأَرْدَشِير بمُصابِ قارَنَ وأهلِ المَذارِ، جَنَّدَ المَلِكُ جيشًا عظيمًا مِن قبيلةِ بكرِ بن وائلٍ والقبائل الأُخرى المُواليةِ له, تحت قِيادةِ قائدٍ مشهور منهم يُدْعى الأندرزغر, وكان فارِسيًّا مِن مولدي السَّوادِ. وأرسل بهمن ج"},{"id":162,"era":"c1","t":"مَعركةُ المَذارِ وهَزيمةُ الفُرْسِ بقِيادةِ خالدِ بن الوَليد\n  .","s":"كتَب هُرمُز إلى أَرْدَشِير وشِيرَى بخبرِ مَسِيرِ خالدٍ إليه مِن اليَمامةِ، فأَمَدَّهُ بقارَن بن قِرْيانِس، فخرَج قارَنُ مِن المدائن حتَّى إذا انتهى إلى المَذارِ بَلَغَتْهُ الهَزيمةُ، فعَسْكَرَ قارَنُ وفُلولُ الفُرْس بالمَذارِ بالقُربِ مِن نهرِ دِجْلة، واستعمَل على مُجَنِّبَتِهِ قُباذَ وأَنُوشَجان، ولمَّا انتهى الخبرُ إلى خالدٍ عن قارَن قسَمَ الفَيءَ على مَن أفاءَهُ الله عليه، ونَفَّلَ مِن الخُمُسِ"},{"id":163,"era":"c1","t":"فَتْحُ الحِيرَةِ بقِيادةِ خالدِ بن الوَليد  .","s":"كان الآزاذِبَةُ مَرْزُبان الحِيرَةِ أي حكام الحيرة, فلمَّا أَخرَب خالدٌ أَمْغِيشِيا عَلِم الآزاذبةُ أنَّه غيرُ مَتروكٍ، فأخذ في أَمْرهِ وتَهيَّأ لحربِ خالدٍ، لمَّا تَوجَّه خالدٌ إلى الحِيرَةِ وحمَل الرِّحالَ والأثقالَ في السُّفُنِ أَرسلَ الآزاذبةُ ابنَهُ لِيقطَعَ الماءَ عن السُّفُنِ, فتعَجَّلَ خالدٌ في خَيلٍ نحو ابنِ الأزاذبةِ فلَقِيَهُ على فُراتِ بادِقْلَى، فقتَلهُ وقتَل أصحابَهُ، وسار نحو الحِير"},{"id":164,"era":"c1","t":"معركة ألِّيس وهزيمة نصارى العرب والفرس بقيادة خالد بن الوليد .","s":"لمَّا أصاب خالدٌ يومَ الوَلَجَةِ ما أصاب مِن نَصارى بكرِ بن وائلٍ الذين أعانوا الفُرْسَ غَضِبَ لهم نَصارى قَوْمِهم، فكاتَبوا الفُرْسَ، واجتمعوا على أَلَّيْس وعليهم عبدُ الأسودِ العِجْليُّ وكتَبَ أَرْدَشِير إلى بهمن جاذُوَيْهِ يأمُرهُ بالقُدومِ على نَصارى العربِ بأُلَّيْس، فقَدِمَ بهمن جاذُوَيْهِ جابانَ إليهم، فاجتمع على جابان نَصارى العربِ مِن أهلِ الحِيرَةِ. وكان خالدٌ لمَّا بَلغَهُ تَجَمُّعُ نَص"},{"id":165,"era":"c1","t":"فَتْحُ الأَنْبارِ في مَعركةِ ذاتِ العُيونِ  بقِيادةِ خالدِ بن الوَليد .","s":"رَكِبَ خالدٌ في جُيوشِه بعد فتحِ الحِيرَةِ حتَّى انتهى إلى الأنبارِ وعليها قائدٌ يُقال له: شِيرَزاذ، فأحاط بها خالدٌ، وعليها خندقٌ وحوله أَعرابٌ مِن قَومِهم على دينهم، واجتمع معهم أهلُ أرضِهم، ولمَّا تَواجَه الفَريقانِ أَمَر خالدٌ أصحابَه فَرَشقوهم بالنِّبال حتَّى فَقَأوا منهم ألفَ عَيْنٍ، وسُمِّيَت هذه الغزوة ذات العُيونِ، فراسل شِيرَزاذ خالدًا في الصُّلْحِ، فاشْتَرط خالدٌ أُمورًا فامْتَنع شِيرَز"},{"id":166,"era":"c1","t":"وَقعةُ عَيْنِ التَّمْرِ وهَزيمةُ العَربِ المُوالين للفُرْسِ بقِيادةِ خالدِ بن الوَليد .","s":"لمَّا فَرَغَ خالدُ بن الوَليد مِن الأنبارِ واسْتَحكَمت له اسْتخلَف على الأنبارِ الزِّبْرِقانَ بن بدرٍ، وقصَد عَيْنَ التَّمْرِ، وبها يَومئذٍ مِهرانُ بن بَهْرامَ جُوبِينَ في جَمْعٍ عظيمٍ مِن العَجَمِ، وعَقَّةُ بن أبي عَقَّةَ في جَمْعٍ عظيمٍ مِن العَرَبِ مِن النَّمِرِ وتَغْلِبَ وإيادٍ ومَن لاقاهُم فلمَّا سمِعوا بخالدٍ قال عَقَّةُ لمِهرانَ: إنَّ العربَ أعلمُ بقِتالِ العربِ، فدَعْنا وخالدً.، قال: صدقتَ"},{"id":167,"era":"c1","t":"انتصارُ المسلمين في مَعركةِ الحُصَيْدِ  والخَنافِسِ المُصَيَّخِ .","s":"بعد أن انصرفَ خالدٌ مِن عَيْنِ التَّمْرِ أقام بدُومَة الجَندلِ فظَنَّ الفُرْسُ أنَّه قد غادَر العِراقَ مُتوجِّهًا إلى الجَزيرةِ العربيَّة مع القسم الأكبر مِن قُوَّاتِه، فأرادوا طَرْد قُوَّاتِه مِن العِراق، واستعادَة الأراضي التي فتَحها المسلمون؛ فطَمِع الأعاجمُ، وكاتَبَهم عربُ الجَزيرةِ غضبًا لِعَقَّةَ، فخرَج زرمهر وروزبه يُريدان الأنبارَ، واتَّعدا حُصيدًا والخَنافِسَ، فسمِع  القعقاعُ بن عَمرٍو وه"},{"id":168,"era":"c1","t":"مَعركةُ الفِراضِ وهَزيمةُ الرُّوم بقِيادةِ خالدِ بن الوَليد .","s":"سار خالدُ بن الوَليد رضِي الله عنه بجُيوشِه المُجتمعَة إلى الفِراض على تُخوم الشَّام والعِراق والجَزيرة، وتَعاوَن الفُرْسُ والرُّومُ ضِدَّ المسلمين, فأقام هنالك شهرَ رمضانَ مُفْطِرًا لِشُغلِه بالأعداءِ، ولمَّا بلَغ الرُّومَ أمرُ خالدٍ ومَصيرُهُ إلى قُرْبِ بِلادِهم حَمُوا وغَضِبوا وجَمَعوا جُموعًا كثيرةً، ثمَّ ناهَدوا خالدًا فحالت الفُراتُ بينهم، فقالت الرُّومُ لخالدٍ: اعْبُرْ إلينا. وقال خالدٌ للر"},{"id":169,"era":"c1","t":"حَجَّةُ خالدِ بن الوَليد رضِي الله عنه أثناءَ عَودةِ جَيشِه مِن الفِراضِ إلى الحِيرَةِ .","s":"أقام خالدُ بن الوَليد بالفِراضِ عشرةَ أيَّامٍ، ثمَّ أَذِنَ بالقُفولِ إلى الحِيرَةِ، لِخَمْسٍ بَقِينَ مِن ذي القَعدةِ، وأَمَر عاصمَ بن عَمرٍو أن يَسيرَ في المُقدِّمة، وأَمَر شَجَرةَ بن الأعَزِّ أن يَسيرَ في السَّاقَةِ، وأظهرَ خالدٌ أنَّه يَسيرُ في السَّاقَةِ, ثمَّ انطلق في كَوْكَبَةٍ مِن أصحابِه، وقصَد شَطْرَ المسجدِ الحرامِ، وسار إلى مكَّةَ في طريقٍ لم يُسْلك قبلَهُ قَطُّ، وتَأتَّى له في ذلك أَمرٌ"},{"id":170,"era":"c1","t":"وَقعةُ النَّمارِق وهَزيمةُ الفُرْسِ بقِيادةِ أبي عُبيدِ بن مَسعودٍ الثَّقفيِّ .","s":"بعَث رُسْتُم جيشًا لِقِتالِ أبي عُبيدِ بن مَسعودٍ الثَّقفيِّ فالْتَقَى الطَّرفانِ في النَّمارِقِ بين الحِيرَةِ والقَادِسِيَّةِ، وكان على خَيلِ المسلمين المُثَنَّى بن حارِثةَ، فهزَم الفُرْسَ وهَربوا وساروا إلى كَسْكَر فلَحِقَهم  أبو عُبيدٍ  ثمَّ هزَمهم ثانيةً وفَرَّ الفُرْسُ إلى المدائنِ. وجمَع المسلمون الغَنائمَ مِن كَسْكَر، فرَأَوْا مِن الأَطعِمَة شيئًا عظيمًا، فاقْتَسموهُ وجعلوا يُطعِمونه الفلَّ"},{"id":171,"era":"c1","t":"خالدُ بن الوَليد يُشارك في فَتحِ بُلدانِ الشَّام .","s":"كان أبو بكرٍ قد أَمَر خالدَ بن الوَليد بعدَ أن انتهى مِن الفِراض بالانتقالِ إلى الشَّامِ؛ لِمُساندةِ جُيوشِ الفَتحِ هناك، فسار خالدٌ مِن الفِراض حتَّى وصل اليَرْموكَ وجاء كِتابُ عُمَر بعدَ اليَرْموك: أن ابْدَؤوا بِدِمشقَ فإنَّها حِصْنُ الشَّام. ولمَّا وصلت جُيوشُ المسلمين دِمشقَ شَدَّدوا الحِصارَ عليها سبعين يومًا، طَوَّقوها مِن جِهاتِها كُلِّها، ومَنعوا المَدَدَ إليها، فانْكَسرت حَمِيَّتُهم وفُتِ"},{"id":172,"era":"c1","t":"إجْلاءُ اليَهودِ والنَّصارى مِن جَزيرةِ العَربِ .","s":"كان الرَّسولُ صلَّى الله عليه وسلَّم قد أَجْلى اليَهودَ مِن المدينة تِباعًا؛ وذلك لِنَقْضِهم العُهود، واسْتِثارتِهم الفِتَن والحُروب، وقد كان النَّبيُّ صلَّى الله عليه وسلَّم قال: (لا يَجتَمِع دِينانِ في أرضِ العَربِ). وكانت اليَهودُ قد اسْتقرَّت في خَيبرَ وما حولها بعدَ جَلائِهم مِن المدينةِ، وبقوا على ذلك حتَّى قام عُمَر بإجلائِهم مِن خَيبرَ إلى الشَّامِ عملًا بحَديثِ النَّبيِّ صلَّى الله عليه و"},{"id":173,"era":"c1","t":"أبو بكر الصِّدِّيق رضِي الله عنه يَعْقِدُ أَلْوِيَةَ فَتْح الشَّام بعدَ فَراغِه مِن حُروبِ الرِّدَّةِ .","s":"قام الصِّدِّيقُ أبو بكرٍ رضِي الله عنه بعَقْدِ أربعةِ أَلوِيةٍ لفَتْح بِلادِ الشَّام بعدَ أن فَرَغَ مِن حُروبِ الرِّدَّةِ، وجعَل قِيادَتَها لأبي عُبيدةَ بن الجَرَّاحِ، ووِجْهَتُه حِمْصُ، وعَمرِو بن العاصِ ووِجْهَتُه فِلسطينُ، وشُرَحْبِيلِ بن حَسَنَةَ ووِجْهَتُه الأُرْدُنُّ، ويَزيدَ بن أبي سُفيانَ ووِجْهَتُه دِمشقُ. وقد أَدَّتْ هذه الجُيوشُ دورَها الفعَّالَ في مُقاتلةِ الرُّومِ وانتصروا في مَواقعَ "},{"id":174,"era":"c1","t":"مَسيرُ خالدِ بن الوَليد مِن العِراقِ لِدَعْمِ أَجنادِ الشَّامِ وفَتْحُ مَدينةِ بُصْرى .","s":"لمَّا رأى المسلمون مُطاوَلةَ الرُّومِ لهم بالشَّام اسْتمَدُّوا أبا بكرٍ، فكتَب إلى خالدِ بن الوَليد يأمُرهُ بالمَسيرِ إليهم وبالحَثِّ، وأن يَأخُذَ نِصفَ النَّاس ويَسْتخلِفَ على النِّصفِ الآخرِ المُثَنَّى بن حارِثةَ الشَّيبانيَّ، ولا يَأْخُذَنَّ مَن فيه نَجْدَةٌ إلَّا وَيَتْرك عند المُثَنَّى مِثْلَهُ، وإذا فتَح الله عليهم رجَع خالدٌ وأصحابُه إلى العِراقِ. اتَّجَه خالدٌ مِن العِراقِ إلى الشَّام وفتَ"},{"id":175,"era":"c1","t":"مَعركةُ \"مَرْجِ الصُّفَّرِ\" بين الرُّوم والمسلمين بقِيادةِ خالدِ بن سعيدٍ .","s":"وقعت مَعركةُ \"مَرْجِ الصُّفَّرِ\" بين الرُّوم بقِيادةِ ماهان، والمسلمين بقِيادةِ خالدِ بن سعيدٍ، وذلك في بِدايات فتحِ المسلمين لبِلاد الشَّام، حيث أخذ خالدٌ طريقَهُ لِمَرْجِ الصُّفَّرِ للهُجومِ على الرُّومِ ممَّا أَدَّى بقائِدهِم ماهان إلى أن يَنحَدِرَ بجَيشِهِ حتَّى يَستدرِجَ جُيوشَ المسلمين التي اتَّجهَت إلى الجَنوبِ ووصلت إلى مَرْجِ الصُّفَّرِ شرق بُحيرَةِ طَبَرِيَّةَ، واغتنم الرُّومُ على المسلم"},{"id":176,"era":"c1","t":"وَفاةُ أبي بكرٍ الصِّدِّيق رضِي الله عنه .","s":"هو أبو بكرٍ الصِّدِّيق عبدُ الله بن عُثمانَ بن عامرِ بن كعبِ بن سعدِ بن تَيْمِ بن مُرَّةَ بن كعبِ بن لُؤَيٍّ. وهو أحدُ العشرةِ المُبشَّرين بالجنَّةِ، وأوَّلُ الخُلفاءِ الرَّاشِدين، مِن أَوائلِ المُصَدِّقين للنَّبيِّ صلَّى الله عليه وسلَّم والمؤمنين به، بَقِيَ معه في مكَّة حتَّى هاجَر معه فكان صاحِبَه في ذلك، قَدَّمَهُ النَّبيُّ صلَّى الله عليه وسلَّم للصَّلاةِ بالنَّاس في مَرَضِ مَوتِه، أَنفقَ في "},{"id":177,"era":"c1","t":"عُمرُ بن الخطَّاب رضي الله عنه يَتولَّى الخِلافةَ بعد وفاة أبي بكر رضي الله عنه .","s":"لمَّا مَرِض أبو بكرٍ الصِّدِّيق رضِي الله عنه وأَحَسَّ بِدُنُوِّ أَجَلِه جمَع عددًا مِن الصَّحابة الذين كان النَّبيُّ صلَّى الله عليه وسلَّم يُشاوِرهُم وعرَض عليهم أن يُؤمِّروا رجلًا يَرضَوْنهُ في حَياتِه؛ ولكنَّهم لم يَستقِرُّوا على أَمْرٍ، ثمَّ بدَأ يسألُ النَّاس عن عُمَرَ بن الخطَّاب، ثمَّ استَقرَّ رَأيُه على اسْتِخلاف عُمَرَ، فكتَب بذلك كِتابًا نَصُّهُ: بسم الله الرَّحمن الرَّحيم، هذا ما عَهِد"},{"id":178,"era":"c1","t":"مَوقِعةُ الجِسْرِ وهَزيمةُ المسلمين .","s":"بعدَ أن هُزِمَ الفُرْسُ في النَّمارِق وما بعدَها اجتمعوا إلى رُسْتُم فأرسل جيشًا كثيفًا ومعهم رايةُ كِسرى ورايةُ أفريدون  فالتقوا مع المسلمين وبينهم جِسْرٌ فعَبَر أبو عُبيدِ بن مَسعودٍ الثَّقفيُّ الجِسْرَ إليهم وجَرَت المعركةُ، وكانت فِيَلَةُ الفُرْسِ تُؤذي المسلمين وتُؤذي خُيولَهم، فقُتِل عددٌ مِن قادَةِ المسلمين منهم أبو عُبيدٍ القائدُ، واسْتَحَرَّ القَتلُ في المسلمين فمَضَوْا نحوَ الجِسْر فقَطَ"},{"id":179,"era":"c1","t":"مَوقِعةُ البُوَيْب وانتِصارُ المسلمين بقِيادةِ المُثَنَّى بن حارِثةَ الشَّيبانيِّ .","s":"بعدَ أن تَوَلَّى المُثَنَّى بن حارِثةَ قِيادةَ المسلمين وكان عُمَر رضِي الله عنه يُمِدُّهُ بالمُقاتلين، الْتَقَى المُثَنَّى مع الفُرْسِ في البُوَيْب قُرْب الكوفةِ، وطلَبَت الفُرْسُ أن يَعبُرَ المسلمون إليهم، أو أن يَعبُروا هُم إليهم، فاختار المُثَنَّى  أن يَعبُر الفُرْسُ فعَبَروا, وجرَت مَعركةٌ عَنيفةٌ هُزِم فيها الفُرْسُ هزيمةً مُنكَرةً، وقُتِلَ منهم الكثيرُ قتلًا أو غَرَقًا في النَّهرِ، وقُتِلَ "},{"id":180,"era":"c1","t":"بِناءُ مَدينةِ البَصْرَةِ .","s":"لمَّا نزَل عُتبةُ بن غَزْوان الخُرَيْبَةَ -مَسالِح الفُرْسِ قَريبة مِن الأُبُلَّةِ- كتب إِلى عُمَر بن الخطَّاب يُعلِمه نُزولَه إيَّاها، وأنَّه لابُدَّ للمسلمين مِن مَنزلٍ يَشْتُون به إذا شَتَوْا، ويَكْنِسون فيه إذا انصرفوا مِن غَزوِهم، فكتب إليه: اجْمَع أصحابَك في مَوضِع واحد وليَكُنْ قريبًا مِن الماء والرَّعْي، واكْتُبْ إِلىَّ بصِفَتِه. فكتب: إليه إنِّي وجدتُ أرضًا كثيرةَ القَصَبَةِ -أي كثيرةَ ال"},{"id":181,"era":"c1","t":"مَعركةُ اليَرموك وانتِصارُ المسلمين على الرُّوم بقِيادةِ خالدِ بن الوَليد .","s":"كان أبو بكرٍ قد كتَب إلى خالدٍ أن يَلحقَ بالشَّام  لِمُساندةِ أَجنادِ المسلمين، وأَمَدَّ هِرقلُ الرُّومَ بباهان، فطلَع عليهم وقد قَدَّمَ الشَّمامِسَةَ والرُّهْبانَ والقِسِّيسينَ يَحُضُّونهم على القِتالِ، ولمَّا قَدِمَ خالدٌ الشَّامَ أشار على الأُمراءِ أن يَجتمِعوا تحت قِيادةٍ واحدةٍ، فقال لهم: إنَّ تَأْمِيرَ بعضِكم لا يُنْقِصُكم عند الله ولا عند خَليفةِ رسولِ الله صلَّى الله عليه وسلَّم فهَلُمُّوا"},{"id":182,"era":"c1","t":"مَعركةُ القادِسِيَّةِ وانتِصارُ المسلمين على الفُرْسِ بقِيادةِ سعدِ بن أبي وقَّاصٍ .","s":"اجتمَع المسلمون في القادِسيَّة ثلاثون ألفًا بقِيادةِ سعدِ بن أبي وقَّاص بعدَ أن أَمَّرَهُ عُمَر بن الخطَّاب بَدَلَ خالدِ بن الوَليد، مكَث سعدٌ في القادِسيَّة شهرًا يَبُثُّ السَّرايا في كلِّ الجِهاتِ، ويأتي بالغَنائِم، فأَمَّر يزدجردُ رُسْتُمَ على جيشٍ كثيفٍ مِن مائةٍ وعشرين ألفًا، ومِثلِها مِن المَدَدَ، فبعَث سعدٌ إليه مَن يَدعوه للإسلامِ وحاوَل الفُرْسُ أن يغروا المسلمين، فطلبوا إرسالَ أكثرِ مِن "},{"id":183,"era":"c1","t":"قَتْلُ قائدِ الفُرْسِ رُسْتُم .","s":"هو رُسْتُم فرخزاد قائدُ الجيشِ الفارسيِّ في عَهدِ آخر مُلوكِ الدَّولةِ السَّاسانيَّةِ يزدجرد الثَّالث أصلُه مِن أَرْمِينيَة، وكان يَخدُم مَلِكَ الفُرْسِ بإخلاصٍ، أرسل يزدجرد الثَّالث القائدَ رُستمَ مُجبِرًا إيَّاه قِيادةَ الجيش الفارسيِّ لِيواجِهَ جُيوشَ المسلمين التي كانت تَخْترِق العِراقَ تَمهيدًا لفتحِ بِلاد فارس، واجَه رُستم المسلمين في القادِسيَّة وفي رابعِ أيَّام القادسيَّة هَبَّتْ رِيحٌ شدي"},{"id":184,"era":"c1","t":"مَعركةُ أَجْنادِينَ وهَزيمةُ الرُّومِ بقِيادةِ عَمرِو بن العاصِ .","s":"سار عَمرُو بن العاصِ إلى أَجْنادِينَ وهي تقعُ قريبًا مِن الفالوجَةِ ومكانِ عُبورِ فِلَسْطين مِن الجَنوبِ، إذ رابَط فيها الأَرْطَبُون، وكانت قُوَّةٌ للرُّوم في الرَّمْلَة وأخرى في بيتِ المَقدِس، وطال تَأَخُّرُ فَتحِها، وكانت مُراسلات بين الطَّرفينِ حتَّى ذهَب عَمرٌو بنفسه إلى الأرطبون، وكادوا يَقتُلونه ولكنَّه فَطَنَ لهم وخادَعهُم ورجَع سالمًا، ثمَّ حدَث قِتالٌ عظيمٌ يُشْبِهُ يومَ اليَرموكِ حتَّى د"},{"id":185,"era":"c1","t":"فَتحُ قِنَّسْرِينَ بقِيادةِ خالدِ بن الوَليد .","s":"أرسل أبو عُبيدةَ عامرُ بن الجَرَّاح خالدَ بنَ الوَليد إلى قِنَّسْرِينَ، فلمَّا نزَل الحاضرَ زحَف إليهم الرُّومُ وعليهم مِيناسُ، وكان مِن أعظمِ الرُّومِ بعدَ هِرقل، فاقتتلوا فقُتِلَ مِيناسُ ومَن معه مَقتلةً عظيمةً لم يُقتلوا مِثْلَها، فماتوا على دمٍ واحدٍ، وسار خالدٌ حتَّى نزَل على قِنَّسْرين فتَحصَّنوا منه، فقالوا: لو كنتم في السَّحابِ لحَمَلَنا الله إليكم، أو لأَنْزَلَكُم إلينا، فنَظروا في أَمرِه"},{"id":186,"era":"c1","t":"فَتحُ مَدينةِ حِمْصَ بقِيادةِ أبي عُبيدةَ عامرِ بن الجَرَّاحِ .","s":"فتَح المسلمون بقِيادةِ أبي عُبيدةَ عامرِ بن الجَرَّاحِ مدينةَ حِمْصَ، بعدَ أن حاصروها حِصارًا شديدًا واضْطَرَّتْ المدينةُ إلى طلبِ الصُّلْحِ، فكتَب المسلمون لأهلِها كِتابًا بالأمانِ على أَنفُسِهم وأموالِهم."},{"id":187,"era":"c1","t":"فَتْحُ بيتِ المَقدِس .","s":"لمَّا فتَح أبو عُبيدةَ الجابِيَةَ مِن أعمالِ دِمشقَ وقِنَّسرينَ وحاصَر أهلَ مَسجدِ إيليا -أي بيت المَقدِس- فأَبَوْا أن يَفتَحوا له، وسَألوه أن يُرْسِلَ إلى صاحِبِه عُمَرَ لِيَقْدُمَ فيكون هو الذي يَتوَلَّى مُصالحَتَهُم، فكتَب بذلك إلى عُمَرَ فاسْتخلفَ علِيَّ بن أبي طالبٍ على المدينةِ, ثمَّ قَدِمَ للشَّامِ, وكتَب إلى أُمراءِ الأجنادِ أن يُوافُوه بالجابِيَةِ ليومٍ سَمَّاهُ لهم في المُجَرَّدَةِ، ويَس"},{"id":188,"era":"c1","t":"دُخولُ عُمَرَ بن الخطَّاب رضِي الله عنه بيت المَقدِس ماشِيًا على قَدَمَيْهِ  .","s":"بعدَ أن كتَب الله النَّصرَ للمسلمين وفتحوا إيليا بيتَ المَقدِس طلَب أهلُه أنَّ يُصالَحوا على صُلحِ أهلِ مُدُنِ الشَّام، وأن يكونَ المُتولِّي للعَقدِ عُمَر بن الخطَّاب، أَبَى بَطْرِيقُها أن يُسَلِّمَ مَفاتيحَ القُدسِ إلَّا للخليفةِ عُمَر بن الخطَّاب، فحضَر عُمَر رضِي الله عنه والقِصَّةُ في دُخولِه مَشهورةً، حيث كان يَتَناوَب على بَعيرٍ مع خادِمِه، فكانت نَوْبَةُ عُمَر المَشْيَ حين وُصولِهم إلى القُ"},{"id":189,"era":"c1","t":"بَدْأُ غارات المسلمين على الأَناضُول (تُرْكِيا) بقِيادةِ سُراقةَ بن عَمرٍو وعبدِ الرَّحمن بن رَبيعةَ .","s":"نَدَبَ عُمَرُ بن الخطَّاب سُراقةَ بن عَمرٍو، وعبدَ الرَّحمن بن رَبيعةَ للمَسيرِ إلى بِلادِ البابِ، وهي بِلادُ التُّرْكِ خلفَ بابِ الأبوابِ المعروف بالدَّرْبَنْد، وأَمَدَّهُ عُمَرُ بن الخطَّاب بحَبيبِ بن مَسلمةَ، ولكنَّ شَهْرَيراز مَلِكَ تلك البِلادِ طلَب مِن عبدِ الرَّحمن أن يُمْهِلَهُ ففعَل، كما عَبَّرَ له عن كُرْهِهِ للأَرْمَن والقَبْج الذين يُقيمون حول بِلادِه، وأَعرَب عن نَواياهُ الطَّيِّبَة ل"},{"id":190,"era":"c1","t":"وَفاةُ مارِيا القِبطيَّة رضِي الله عنها  .","s":"هي مارِيا القِبطيَّة، أهداها المُقَوْقِسُ القِبطيُّ للنَّبيِّ صلَّى الله عليه وسلَّم، تَسَرَّى بها النَّبيُّ صلَّى الله عليه وسلَّم، ووَلدَت له إبراهيمَ، فقال: (أَعْتَقَها وَلَدُها)، فلا تُعَدُّ مِن زَوجاتِه صلَّى الله عليه وسلَّم، وبالتَّالي لَيست مِن أُمَّهات المؤمنين، أَنفَق عليها أبو بكرٍ وعُمَر إلى أن تُوفِّيَت في خِلافَتِه وصلَّى عليها بِنفسِه."},{"id":191,"era":"c1","t":"فَتحُ بَهُرَسِيرَ \"المَدائِن الغَربيَّة\" بقِيادةِ سعدِ بن أبي وَقَّاصٍ .","s":"كان انتِصارُ المسلمين في القادِسيَّة دافعًا لهم للاستمرار في زَحْفِهم نحو المدائنِ عاصِمَةِ الفُرْسِ، وسار سعدٌ بجُنودِه حتَّى وصَل إلى بَهُرَسِيرَ \"المدائن الغَربيَّة\" وكانت إحدى حواضِر فارِسَ، فنزَل سعدٌ قريبًا منها، وأرسَل مجموعةً مِن جُنودِه لاستِطلاعِ المَوقِف، وعاد الجُنودُ وهُم يَسوقون أَمامَهم آلافَ الفَلَّاحين، مِن أهلِ تلك المدينةِ. وحينما عَلِمَ شيرزارُ دَهْقانُ -أمير- ساباط بالأَمْرِ أ"},{"id":192,"era":"c1","t":"فَتحُ مَدائنِ القُصورِ عاصِمةِ الفُرْسِ بقِيادةِ سعدِ بن أبي وَقَّاص .","s":"عزَم سعدُ بن أبي وَقَّاص أن يَعْبُرَ جَيشُه دِجلَة بالخيلِ، فجمَع النَّاس فحمِد الله وأثنى عليه ثمَّ قال: إنَّ عَدُوَّكُم قد اعْتصَم منكم بهذا البحرِ، فلا تَخْلُصون إليه معه ويَخْلُصون إليكم إذا شاءوا في سُفُنِهم فَيُناوِشُونَكُم، وليس وَراءَكُم شيءٌ تخافون أن تُؤْتَوْا منه، قد كَفاكُم أهلُ الأيَّام وعَطَّلُوا ثُغورَهُم، وقد رأيتُ مِن الرَّأي أن تُجاهِدوا العَدُوَّ قبلَ أن تَحْصُدَكُم الدّنيا، ألا"},{"id":193,"era":"c1","t":"بِناءُ أوَّلِ مَسجدٍ في المدائنِ عاصِمَة إمْبراطورِيَّة فارِسَ  .","s":"لمَّا دخَل المسلمون المدائنَ وفتحوها واتَّخذَ سعدُ بن أبي وَقَّاص قَصرَها مَسكنًا جعَل إيوانَها المشهورَ مَسجدًا ومُصَلَّى وتَلَا قولَه تعالى: {كَمْ تَرَكُوا مِنْ جَنَّاتٍ وَعُيُونٍ (25) وَزُرُوعٍ وَمَقَامٍ كَرِيمٍ (26) وَنَعْمَةٍ كَانُوا فِيهَا فَاكِهِينَ (27) كَذَلِكَ وَأَوْرَثْنَاهَا قَوْمًا آخَرِينَ (28) فَمَا بَكَتْ عَلَيْهِمُ السَّمَاءُ وَالْأَرْضُ وَمَا كَانُوا مُنْظَرِينَ} [الدخان: 25 - 29"},{"id":194,"era":"c1","t":"بِدايَةُ التَّاريخِ الهِجْرِيِّ .","s":"كتَب أبو موسى الأَشعريُّ إلى عُمَر: إنَّه يأتينا منك كُتُبٌ ليس لها تاريخٌ، فجمَع عُمَرُ النَّاسَ للمَشُورَةِ، فقال بعضُهم: أَرِّخْ لِمَبْعَثِ النَّبيِّ صلَّى الله عليه وسلَّم. وقال بعضُهم: لمُهاجرَةِ رسولِ الله صلَّى الله عليه وسلَّم. فقال عُمَرُ: بل نُؤَرِّخُ لمُهاجرَةِ رسولِ الله صلَّى الله عليه وسلَّم، فإنَّ مُهاجَرتَه فَرْقٌ بين الحَقِّ والباطلِ. قاله الشَّعْبِيُّ، وقال مَيمونُ بن مِهْرانَ: و"},{"id":195,"era":"c1","t":"فَتحُ تَكْريت والمَوْصِل بقِيادةِ عبدِ الله بن المُعْتَمِّ .","s":"لمَّا افْتَتَح سعدُ بن أبي وَقَّاص المدائنَ بَلغَه أنَّ أهلَ المَوْصِل قد اجْتَمعوا بِتَكْريت على رَجُلٍ يُقال له: الأنطاق, فكتَب إلى عُمَر بن الخطَّاب بأَمْرِ جَلُولاء، واجْتِماع الفُرْسِ بها, وبأَمْرِ أهلِ المَوْصِل, فكتَب عُمَر في قَضِيَّةِ أهلِ المَوْصِل أن يُعَيِّنَ جيشًا لِحَرْبِهم, ويُؤَمِّرَ عليه عبدَ الله بن المُعْتَمِّ, ففَصَلَ عبدُ الله بن المُعْتَمِّ في خمسةِ آلافٍ مِن المدائنِ, فسار ف"},{"id":196,"era":"c1","t":"مَوقِعةُ جَلُولاء وهَزيمةُ الفُرْسِ بقِيادةِ هاشمِ بن عُتبةَ بن أبي وَقَّاص .","s":"بعدَ أن فَرَّ يزدجردُ مِن المدائنِ وسار بِاتِّجاهِ حُلوان، والْتَفَّ مَن الْتَفَّ حولَه خِلالَ مَسيرِه فأَمَّرَ عليهم مِهرانَ وأقاموا بجَلُولاء، وتَحَصَّنوا فيها، وحَفروا الخَنادِقَ حولَها، فبعَث سعدٌ إلى عُمَر يُخبِره بذلك، فأَمَرَهُ أن يُقيمَ بالمدائنِ، ويُرْسِل إليهم هاشمَ بن عُتبةَ بن أبي وَقَّاص، فسار إليهم هاشمٌ وحاصَرهُم، واشْتَدَّ القِتالُ، وكانت النَّجدات تَصِلُ إلى الطَّرفين حتَّى فتَح ا"},{"id":197,"era":"c1","t":"بناء مدينة الكوفة في خلافة عمر بن الخطاب رضي الله عنه .","s":"لمَّا نزَل المسلمون المدائنَ اجْتَوَوْها فشَكُوا ذلك, فكتَب حُذيفةُ إلى عُمَر: إنَّ العَربَ قد رَقَّتْ بُطونُها، وجَفَّتْ أَعضادُها، وتَغَيَّرَتْ أَلوانُها. وكان مع سعدٍ, فكتَب عُمَرُ إلى سعدٍ: أَخبِرني ما الذي غَيَّرَ أَلوانَ العَربِ ولُحومَهُم؟ فكتَب إليه سعدٌ: إنَّ الذي غَيَّرَهُم وُخومَةُ البِلادِ، وإنَّ العَربَ لا يُوافِقُها إلَّا ما وافَق إِبِلَها مِن البُلدانِ. فكتَب إليه عُمَر: أن ابْعَثْ "},{"id":198,"era":"c1","t":"فَتحُ المسلمين لبلاد الأَهْوازِ بعد أن استولى عليها الهُرمُزان .","s":"بعدَ أن تَغَلَّبَ الهُرمُزانُ على مَنطِقَةِ الأَهْوازِ أصبحَ يُغِيرُ على المناطِقِ التي دانت للمسلمين، فسار إليه جَيْشان مِن المسلمين مِن الكوفةِ ومِن البَصْرَةِ فأَجبَروه على الصُّلْحِ، ثمَّ نَقَضَ الهُرْمُزان الصُّلْحَ فبَرَزَ له المسلمون ثانِيَةً ففَرَّ إلى تُسْتَر فحاصَروهُ فيها فطلَب الصُّلْحَ ثانِيَةً، وكانت الأهوازُ قد فُتِحَتْ ثمَّ نَقَضَ الهُرمُزان الصُّلْحَ ثانيةً، فسَيَّرَ إليه عُمَرُ ب"},{"id":199,"era":"c1","t":"غَزْوُ العَلاءِ بن الحَضْرَميِّ بِلادَ فارِسَ مِن البَحْرَين وفَتحُ إصْطَخْر  .","s":"كان العلاءُ بن الحَضْرَميِّ رضِي الله عنه واليَ البَحْرين، وكان يُسابِق سعدَ بن أبي وَقَّاص في الفَتحِ، فلمَّا كتَب الله النَّصرَ في القادِسيَّة، وكان له الصَّدى الواسعُ أَحَبَّ العَلاءُ أن يكونَ له النَّصرُ على فارِسَ مِن جِهَتِهِ، فنَدَبَ النَّاسَ إلى الجِهادِ، فاجتمَع الجيشُ وعَبَروا البحرَ إلى فارِسَ، ولكن كلّ ذلك دون إذْنِ عُمَر بن الخطَّاب، واتَّجه العَلاءُ إلى إصْطَخْر -مدينة جنوب إيران- وق"},{"id":200,"era":"c1","t":"عُمَر بن الخطَّاب رضي الله عنه يَزيدُ في مساحة المسجدِ النَّبوِيِّ .","s":"لم يَزِدْ أبو بكرٍ الصِّدِّيقُ رضِي الله عنه في عَهدِه بالمسجدِ النَّبوِيِّ الشَّريف لانشغالِه بحُروبِ الرِّدَّةِ، ولكن في عَهدِ عُمَر بن الخطَّاب رضِي الله عنه ضاق المسجدُ بالمُصلِّين لِكثرَةِ النَّاسِ، فقام عُمَر بِشِراءِ الدُّورِ التي حولَ المسجدِ النَّبوِيِّ الشَّريف وأَدخَلها ضِمْنَ المسجدِ، وكانت تَوْسِعَتُه مِن الجِهَةِ الشَّماليَّة والجَنوبيَّة والغَربيَّة. فقد زاد مِن ناحِيَةِ الغَربِ عشر"},{"id":201,"era":"c1","t":"فَتحُ الجَزيرةِ وأَرْمِينِيَة .","s":"أرسَل سعدُ بن أبي وَقَّاص العَساكِرَ إلى الجَزيرةِ، فخرَج عِياضُ بن غَنْمٍ إليها وفي صُحبَتِه أبو موسى الأشعريُّ, وعُمَرُ بن سعدِ بن أبي وَقَّاص -وهو غُلامٌ صغيرُ السِّنِّ ليس إليه مِن الأمر شيءٌ- وعُثمانُ بن أبي العاصِ، فنزَل الرُّها, فصالَحهُ أهلُها على الجِزيَة, وصالَحَت حَرَّانُ على ذلك, ثمَّ بعَث أبا موسى الأشعريَّ إلى نَصِيبِين, وعُمَرَ بن سعدٍ إلى رَأْسِ العَيْنِ, وسار بنفسه إلى دارا, فافْت"},{"id":202,"era":"c1","t":"طاعونُ عِمْواس في الشَّام ووَفاةُ عددٍ مِن المسلمين مُتأَثِّرين به. .","s":"أصاب الشَّامَ في ذلك العام طاعونٌ عامٌّ شديدٌ حَصَد الكثيرَ مِن النَّاسِ، وسُمِّيَ ذلك العامُ بعام عَمْواس مِن شِدَّةِ ما حصَل مِن الموتِ, وقد مات فيه خمسةٌ وعشرون ألفًا, وكان ممَّن تُوفِّيَ فيه أبو عُبيدةَ بن الجَرَّاح، ومعاذ بن جبل، ويَزيدُ بن أبي سُفيانَ، وشُرَحْبِيلُ بن حَسَنَةَ، وغيرُهم كثيرٌ، وعَمْواس هو اسمُ المكان الذي انْتَشَر فيه الطَّاعونُ، وهو مكانٌ قَريبٌ مِن الرَّمْلَةِ في فِلَسطين."},{"id":203,"era":"c1","t":"وَفاةُ أبي عُبيدةَ بن الجَرَّاح رضِي الله عنه .","s":"هو أمينُ الأُمَّةِ عامرُ بن عبدِ الله بن الجَرَّاح رضِي الله عنه، اشْتَهَر بكُنْيَتِه, أبي عُبيدةَ، أحدُ العشرةِ المُبَشَّرين بالجنَّةِ، شَهِدَ بدرًا وأُحُدًا والمَشاهِدَ كُلَّها مع رسولِ الله صلَّى الله عليه وسلَّم، وهو مِن السَّابقين إلى الإسلامِ، وهاجَر إلى الحَبَشةِ وإلى المدينةِ أيضًا، وكان يُدْعى: القويَّ الأمينَ، آخَى النَّبيُّ صلَّى الله عليه وسلَّم بينه وبين أبي طَلحةَ الأنصاريِّ، كان مِن"},{"id":204,"era":"c1","t":"فَتحُ الرَّيِّ بقِيادةِ نُعَيْمِ بن مُقَرِّن المُزَنيِّ .","s":"خرَج نُعيمُ بن مُقرِّن مِن واج رُوذ في النَّاس إلى دَسْتَبى، فلَقِيَهُ الزَّيْنَبِيُّ أحدُ قادةِ الفُرْسِ بمكان يُقال له: قِها مُسالِمًا ومُخالِفًا لمَلِكِ الرَّيِّ، وقد رأى مِن المسلمين ما رأى، فأقبل مع نُعيمٍ والمَلِكُ يَومئذٍ بالرَّيِّ وهو سِيَاوَخْشُ بن مِهران، فاسْتَمَدَّ أهلَ دَنْباوَنْد وطَبَرِستان وقُومِس وجُرْجان وقال المَلِكُ: قد عَلِمْتُم أنَّ هؤلاء قد حَلُّوا بالرَّيِّ، وإنَّه لا مُقام"},{"id":205,"era":"c1","t":"فَتحُ جُرْجان\nبقِيادةِ سُويدِ بن مُقَرِّنٍ .","s":"سار سُويدُ بن مُقرِّن إلى جُرجان فعَسْكَر بها ببِسْطام، وكتَب إلى مَلِكِ جُرجان، وهو زُرْنان صُول، وكاتَبهُ زُرنان صُول وصالحَه على جُرجان على الجِزيَةِ، وكِفايَة حَربِ جُرجان، وأن يُعينَه سُويدٌ إن غَلَبَ، فأجابَهُ سُويدٌ إلى ذلك، وتَلَقَّاهُ زُرنان صُول قبلَ دُخولِه جُرجان فدخَل معه وعَسْكَر بها حتَّى جَبَى الخَراجَ وسَمَّى فُروجَها، فسدها بترك دِهِسْتان، ورفَع الجِزيَةَ عمَّن قام بِمَنْعِها، وأ"},{"id":206,"era":"c1","t":"عُمَر بن الخطَّاب يُوَلِّي مُعاويةَ بن أبي سُفيانَ على الشَّام خَلَفًا لأبي عُبيدةَ رضي الله عنهم .","s":"بعدَ أن تُوفِّيَ أبو عُبيدةَ بن الجَرَّاح بطاعون عَمْواس، وكان أبو عُبيدةَ القائِدَ العامَّ على جُيوشِ الشَّامِ بعدَ عَزْلِ خالدٍ، فلمَّا تُوفِّيَ عَيَّنَ عُمَرُ بن الخطَّاب بَدَلًا عنه مُعاويةَ بن أبي سُفيانَ الذي أصبحَ أميرًا على بِلادِ الشَّامِ بَقِيَّةَ خِلافَةِ عُمَر، ومُدَّةَ خِلافةِ عُثمانَ."},{"id":207,"era":"c1","t":"مَوقِعةُ عَيْنِ شَمْسٍ بِمِصْرَ وهَزيمةُ الرُّومِ الصَّلِيبيِّين بقِيادةِ عَمرِو بن العاصِ .","s":"حاصَر المسلمون عَيْنَ شَمْسٍ وارْتَقى الزُّبيرُ بن العَوَّام السُّورَ، فلمَّا أَحَسَّ أهلُها بذلك انْطَلَقوا بِاتِّجاهِ البابِ الآخَرِ الذي عليه عَمرُو بن العاصِ؛ ولكنَّ الزُّبيرَ كان قد اخْترقَ البابَ عَنْوَةً ووصَل إلى البابِ الذي عليه عَمرٌو؛ ولكنَّ أهلَ عَيْنِ شَمْسٍ كانوا قد سَبَقوه وصالحوا عَمرًا, وكتَب لهم عَمرٌو كِتابَ أَمانٍ: بسم الله الرحمن الرحيم، هذا ما أعطى عَمرُو بن العاصِ أهلَ مِصْر"},{"id":208,"era":"c1","t":"تَوَغُّلُ جُيوشِ المسلمين في بِلادِ فارِسَ .","s":"بعدَ أن فُتِحَت نَهاوَنْد أَمَرَ عُمَرُ بن الخطَّاب بالانْسِياح في فارِسَ كُلِّها، وأُعْطِيَت الأوامرُ لِسبعَةِ أُمَراء بالتَّوَغُّلِ في أَعماقِ فارِسَ، فسار النُّعمانُ بن مُقَرِّن إلى هَمْدان ففَتَحها، ثمَّ إلى الرَّيِّ \"طِهْران اليوم\" ففَتَحها ثمَّ قُوس فأخَذَها سِلْمًا أخوهُ سُويدٌ، ثمَّ جاءَ هو إلى جُرجان وطَبَرِستان وصالَحوه، ثمَّ بعضِ بِلادِ أَذْرَبِيجان، وأمَّا سُراقةُ بن عَمرٍو فذهَب إلى ب"},{"id":209,"era":"c1","t":"أوَّلُ مَن دخَل من المسلمين إلى أرضَ الرُّومِ .","s":"أوَّلُ مَن دخَل أرضَ الرُّومِ أبو بَحْرِيَّةَ عبدُ الله بن قيسٍ، وقِيلَ: أوَّلُ مَن دخَلَها مَيْسرَةُ بن مَسروقٍ العَبْسِيُّ، فسَبَى وغَنِمَ."},{"id":210,"era":"c1","t":"وَفاةُ أُمِّ المؤمنين زَينبَ بنتِ جَحْشٍ رضِي الله عنها .","s":"هي أُمُّ المؤمنين زينبُ بنتُ جَحْشِ بن رِيابِ بن يَعْمُر، أُمُّها أُمَيْمةُ بنتُ عبدِ المُطَّلِب عَمَّةُ النَّبيِّ صلَّى الله عليه وسلَّم، مِن المُهاجِرات، كانت تحت زيدِ بن حارِثَةَ، ثمَّ طَلَّقَها فزَوَّجَها اللهُ تعالى نَبِيَّهُ، وفيها نزَلَت الآياتُ: {وَإِذْ تَقُولُ لِلَّذِي أَنْعَمَ اللَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَاتَّقِ اللَّهَ وَتُخْفِي فِي نَفْسِكَ مَا ال"},{"id":211,"era":"c1","t":"هَلاكُ هِرَقْلَ قَيْصَر الرُّومِ .","s":"هو فلافيوس أغسطس هِرقل إمبراطور الإمبراطوريَّة البِيزَنْطيَّة، مِن أُصولٍ أَرْمِينيَّةٍ, بدأَ صُعودَه إلى السُّلطةِ عام 608م، قاد ثَورةً ناجِحَةً ضِدَّ الإمبراطور فورس الذي تَسَلَّم السُّلطةَ بعدَ خَلْعِ الإمبراطور موريس، ودون شَعبِيَّةٍ تُذْكَر في ظِلِّ القَلاقِل التي عانت منها الإمبراطوريَّة. كان والدُ هِرقل -وهو هِرقل الأكبرُ- قائدًا عَسكرِيًّا ناجحًا، شارَك في حُروبِ الإمبراطور موريس، ويُعتبَر"},{"id":212,"era":"c1","t":"القَحْطُ وعامُ الرَّمادَةِ في الحِجازِ .","s":"كما أصاب الشَّامَ طاعونُ عَمْواس فقد أُصِيبَتْ الحِجازُ بقَحْطٍ شديدٍ جِدًّا وجَفافٍ عامٍّ، وسُمِّيَ ذلك اليومُ بعامِ الرَّمادَةِ، حتَّى طلَب عُمَرُ الغَوْثَ مِن مِصْرَ ومِن الشَّامِ، فأرسل له عامِلَاهُ عليها المَؤونَةَ التي خَفَّفَتْ عن النَّاسِ."},{"id":213,"era":"c1","t":"سُقوطُ حِصْنِ بابِ لِيُون على يَدِ عَمرِو بن العاصِ رضِي الله عنه .","s":"بعدَ انْتِصار المسلمين في مَوقعةِ عَيْنِ شَمْسٍ مَكَّنَ هذا النَّصرُ مُعسكراتِ المسلمين مِن أن تَشْرُفَ على حِصْن بابِ لِيُون مُباشرةً مِن جِهَتِه الشَّماليَّة والشَّرقيَّة، وكانت أَسوارُ هذا الحِصْن تَضُمُّ مِساحةً تَزيدُ عن السِّتِّين فَدَّانًا, ضرَب المسلمون حِصارًا قَوِيًّا على الحِصْن المَنيعِ، غيرَ عابِئِينَ بِمَجانيق الرُّومِ، تَدفَعُهم حَماسَتُهُم، وحُبُّ الجِهادِ ونَيْلُ الشَّهادةِ في مُه"},{"id":214,"era":"c1","t":"فَتحُ الإسكندريَّة عاصمةِ مِصْرَ بقِيادةِ عَمرِو بن العاصِ .","s":"لمَّا افتَتَح المسلمون بابَ لِيُون ثمَّ افتَتَحوا قُرى الرِّيفِ فيما بينها وبين الإسكندريَّة قريةً فقريةً، حتَّى انتهوا إلى بَلْهِيب -قرية يُقال لها: الرّيش- أرسل صاحبُ الإسكندريَّة الى عَمرِو بن العاصِ: إنَّني كنتُ أُخرِج الجِزيةَ إلى مَن هو أبغضُ إليَّ منكم: فارِسَ والرُّومِ، فإن أحببتَ الجِزيةَ على أن تَرُدَّ ما سَبَيْتُم مِن أرضي فعلتُ. فكتب عَمرٌو إلى عُمَرَ يَستأذِنهُ في ذلك، ورفعوا الحربَ إ"},{"id":215,"era":"c1","t":"وَقعةُ نَهاوَنْد وانتِصارُ المسلمين بقِيادةِ النُّعمانِ بن مُقرِّن المُزَنِيِّ .","s":"تَجمَّعَ الفُرْسُ في نَهاوَنْد بقِيادةِ ذي الحاجِبِ بعدَ أن ذهبَت أكثرُ مُدُنِهِم، وبَقَوْا فترةً على ذلك لعدمِ سَماحِ عُمَرَ رضِي الله عنه بالانسِياحِ في فارِسَ، ولكن لمَّا كَثُرَ نَقضُ العُهودِ بسببِ تَقَوِّيهِم بمَن بَقِيَ في نَهاوَنْد، شاوَر عُمَرُ المسلمين في أَمْرِ الفُرْسِ المجتمعين في نَهاوَنْد، وكان يُهِمُّ أن يَسيرَ بنفسه لمُلاقاتِهِم، فأشار عليه علِيٌّ: أنِ ابْعَثْ إلى أهلِ الكوفةِ فَلْ"},{"id":216,"era":"c1","t":"وَفاةُ خالدِ بن الوَليد رضِي الله عنه سَيْفِ الله المَسْلولِ .","s":"هو خالدُ بن الوَليد بن المُغيرةِ بن عبدِ الله بن عَمرِو بن مَحْزومٍ القُرشيُّ المَخْزوميُّ، سَيْفُ الله، أبو سُليمانَ، كان أحدَ أَشرافِ قُريشٍ في الجاهِليَّة، وكان إليه أَعِنَّةُ الخَيلِ في الجاهِليَّة، وشَهِدَ مع كُفَّارِ قُريشٍ الحُروبَ إلى عُمرَةِ الحُديبيةِ، كما ثبَت في الصَّحيحِ: أنَّه كان على خَيلِ قُريشٍ طَلِيعَةً، ثمَّ أَسلَم في سَنةِ سبعٍ بعدَ خَيبرَ، وقِيلَ قَبلَها، أَرسَلهُ أبو بكرٍ إلى"},{"id":217,"era":"c1","t":"فَتْحُ هَمَذان والرَّيِّ وقُومِس وجُرْجان وأَذْرَبِيجان بقِيادةِ نُعيمِ بن مُقَرِّن .","s":"بعدَ أن فُتِحَت نَهاوَنْد اطْمَأنَّ عُمَرُ بن الخطَّاب رضِي الله عنه للانْسِياحِ داخِلَ فارِسَ كُلِّها، فأَمَرَ بذلك، وكان ممَّن أُمِرَ بذلك نُعيمُ بن مُقرِّن أخو النُّعمانَ، فسار إلى هَمَذان ففتَحها واسْتخلَف عليها يَزيدَ بن قيسٍ، ثمَّ سار هو باتِّجاهِ الرَّيِّ -موقع طِهْران اليوم-  ففتَحها كذلك، ثمَّ بعَث بأخيه سُويدِ بن مُقرِّن إلى قُومِس فأخذها سِلْمًا، وصالَح أهلَها، وجاء إليه أهلُ جُرْجان وط"},{"id":218,"era":"c1","t":"فَتحُ شَمالِ أفريقيا (بَرْقَة بليبيا وطَرابُلُس الغرب) بقِيادةِ عَمرِو بن العاصِ .","s":"سار عَمرُو بن العاصِ رضِي الله عنه إلى بَرْقَة وصالَح أَهلَها، وأَرسَل عُقبةَ بن نافعٍ إلى زَوِيلَة، واتَّجَه إلى بِلادِ النُّوبَةِ، ثمَّ انْطَلق عَمرٌو إلى طَرابُلُس ففتَحها بعدَ حِصارِ شَهْرٍ، ثمَّ فتَح صبراته وشروس، ثمَّ مَنَعهُ عُمَرُ بن الخطَّاب رضِي الله عنه مِن التَّقَدُّمِ غربًا أكثرَ مِن ذلك."},{"id":219,"era":"c1","t":"وَفاةُ أُمِّ المؤمنين سَوْدَةَ بنتِ زَمْعَةَ رضِي الله عنها .","s":"هي أُمُّ المؤمنين سَوْدَةُ بنتُ زَمْعَةَ بن قيسِ بن عبدِ شَمسِ بن عبدِ وُدٍّ، وأُمُّها الشَّموسُ بنتُ قيسِ بن عَمرِو بن زيدِ بن لَبيدٍ، تَزوَّجها السَّكرانُ بن عَمرِو بن عبدِ شَمسِ بن عبدِ وُدٍّ، وأَسلمَت بمكَّةَ قديمًا وبايَعَت، وأَسلَم زَوجُها السَّكرانُ بن عَمرٍو، وخرَجا جميعًا مُهاجِرين إلى أرضِ الحَبشةِ في الهِجرَةِ الثَّانيةِ، قَدِمَ السَّكرانُ بن عَمرٍو مكَّةَ مِن أرضِ الحَبشةِ ومعه امْرأتُ"},{"id":220,"era":"c1","t":"اسْتِشهادُ عُمَرَ بن الخطَّاب رضِي الله عنه .","s":"أثار فَتحُ بلادِ فارِسَ وتطهيُرها من عبادةِ غيرِ اللهِ عزَّ وجلَّ حِقْدًا مجوسيًّا؛ فحَرَّكوا أصابَعهم، واستطاعوا بقَدَرٍ مِن اللهِ عزَّ وجلَّ أن يَصِلوا إلى خليفةِ المسلمينَ عُمَرَ بنِ الخطَّابِ رضي الله عنه وقتله، بتحريكِ ذلك العِلْجِ المجوسيِّ؛ ليَقضِيَ اللهُ أمرًا كان مفعولًا، فكان قاتله أشقى الخَلقِ بما أقدَمَ عليه، وكان قَتْلُه لعُمَرَ مؤامرةً منه مع غيرِه من المجوسِ الذين جيءَ بهم أَسرى إلى"},{"id":221,"era":"c1","t":"خِلافةُ عُثمانَ بن عفَّانَ رضِي الله عنه  .","s":"لمَّا طُعِنَ عُمَرُ بن الخطَّاب رضِي الله عنه بسِكِّينٍ مَسمومةٍ وأَيْقَن أنَّه مَيِّتٌ طَلبوا منه أن يَسْتَخْلِفَ كما اسْتخلَفهُ أبو بكرٍ رضِي الله عنه؛ لكنَّه أَبَى ذلك، ولكن جعَل سِتَّةً مِن الصَّحابةِ وكُلُّهُم مِن المُبشَّرين بالجنَّة: عُثمانَ بن عفَّانَ، وعَلِيَّ بن أبي طالبٍ، وعبدَ الرَّحمن بن عَوفٍ، والزُّبيرَ بن العَوَّامِ، وسعدَ بن أبي وَقَّاصٍ، وطَلحةَ بن عُبيدِ الله رضِي الله عنهم، وأَ"},{"id":222,"era":"c1","t":"المسلمون يَغزون أَذْرَبِيجان وأَرْمِينِيَة بقِيادةِ الوَليدِ بن عُقبةَ .","s":"كان الوَليدَ بن عُقبةَ هو أَميرُ الكوفةِ، فقام بِغَزْوِ أَذْرَبِيجان وأَرْمِينِية بجَيشٍ على مُقدِّمتِه سُليمانُ بن رَبيعةَ، وذلك أنَّ أهلَهُما قد مَنَعوا ما صالَحوا عليه حُذيفةَ بن اليَمانِ أيَّامَ عُمَر بن الخطَّاب، فاضْطَرَّهُم الوَليدُ إلى المُصالَحةِ مَرَّةً أُخرى."},{"id":223,"era":"c1","t":"عَزْلُ عَمرِو بن العاصِ رضِي الله عنه عن وِلايَةِ مِصْرَ .","s":"بعدَ أن تَوَلَّى عُثمانُ بن عفَّانَ الخِلافةَ، وكان عَمرَو بن العاصِ هو أَميرُ مِصْرَ مِن قِبَلِ عُمَر بن الخطَّاب، فَعُيِّنَ بدلًا عنه عبدُ الله بن سعدِ بن أبي السَّرْحِ، عَيَّنَهُ على مِصْرَ وخَراجَها، وأَمَرَهُ كذلك بالانْسِياحِ في أفريقيا والتَّوَغُّلِ فيها واسْتِكمالِ الفُتوحِ."},{"id":224,"era":"c1","t":"المسلمون يُكْمِلون فَتْحَ الشَّام بقِيادةِ حَبيبِ بن مَسلَمةَ .","s":"اسْتُكْمِلت الفُتوحات التي كانت قد بدأت أيَّام عُمَر بن الخطَّاب، أَكمَلها عُثمانُ بن عفَّانَ، فقد غَزا حَبيبُ بن مَسلَمةَ بعضَ أراضي سُوريا التي كانت لا تَزالُ بيَدِ الرُّومِ، فدارَت مَعاركُ على الشَّواطئِ وغيرِها مِن المَناطِق."},{"id":225,"era":"c1","t":"الرُّومُ يُعاوِدون احْتِلالَ الإسكندريَّة والمسلمون يَسْتَرِدُّونَها منهم .","s":"نقَض الرُّومُ العَهْدَ الذي كان بينهم وبين المسلمين بعدَ أن تَوَلَّى عبدُ الله بن أبي السَّرْحِ وِلايةَ مِصْرَ، فكتَب أهلُ الإسكندريَّة إلى قُسطنطين بن هِرقل وهَوَّنُوا عليه فَتْحَ الإسكندريَّة لِقِلَّةِ الحامِيَةِ مِن المسلمين، فأَنْفَذَ قائِدَهُ مانوبل الأرمنيَّ على رأسِ جيشٍ كَثيفٍ فاسْتَولى عليها، فكتَب عُثمانُ إلى عَمرٍو ووَلَّاهُ الإسكندريَّةَ، فسار عَمرٌو إليهم فبَدأَ القِتالُ في نَقْيُوس، "},{"id":226,"era":"c1","t":"عُثمانُ بن عفَّانَ رضي الله عنه يأمر بتَوْسيعُ المَسجدِ الحرامِ .","s":"أَمَرَ عُثمانُ بن عفَّانَ رضِي الله عنه بِتَجديدِ أَنْصابِ الحَرمِ، وفيها زاد في المَسجدِ الحَرامِ ووَسَّعَهُ، وابْتاع مِن قَومٍ،  وَأَبَى آخَرون فهَدَم عليهم، ووضَع الأثْمانَ في بيتِ المالِ، فصاحوا بعُثمانَ، فأَمَر بهم فحُبِسُوا، وقال: أتدرون ما جَرَّأَكُم عَلَيَّ؟ ما جَرَّأَكُم عَلَيَّ إلَّا حِلْمِي، قد فعَل هذا بكم عُمَرُ فلم تَصيحوا به. فكَلَّمَهُ فيهم أَميرُ مكَّةَ عبدُ الله بن خالدِ بن أَسِي"},{"id":227,"era":"c1","t":"وَفاةُ كعبِ بن زُهيرِ بن أبي سُلْمَى رضِي الله عنه .","s":"هو كعبُ بن زُهيرِ بن أبي سُلْمَى المُزَنِيُّ، أبو المُضَرَّبِ, الشَّاعرُ ابنُ الشَّاعرِ، وأَبُوهُ أَشْعَرُ منه، كان كعبٌ في الجاهِليَّة شاعرًا مَعروفًا ولمَّا ظهَر الإسلامُ هَجا النَّبيَّ صلَّى الله عليه وسلَّم وشَبَّبَ بنِساءِ المسلمين، فأَهْدَر النَّبيُّ صلَّى الله عليه وسلَّم دَمَهُ، فجاء مُسْتَأْمِنًا إلى النَّبيِّ صلَّى الله عليه وسلَّم، فأَمَّنَهُ وقَبِلَ منه، فأَنشَدهُ لامِيَّتَهُ المشهورة "},{"id":228,"era":"c1","t":"عَزْلُ سعدٍ رضِي الله عنه عن الكوفةِ وتَوْلِيَةُ الوَليدِ بن عُقبةَ  .","s":"كان سعدُ بن أبي وقَّاص أميرًا على الكوفةِ بعدَ أن عُزِلَ عنها المُغيرةُ بن شُعبةَ، ثمَّ عَزَلَ عُثمانُ سعدًا عن الكوفةِ، ووَلَّاها الوَليدَ بن عُقبةَ، وكان سببُ عَزْلِ سعدٍ أنَّه اقْتَرَض مِن ابنِ مَسعودٍ مالًا مِن بيتِ المالِ، فلمَّا تَقاضاهُ به ابنُ مَسعودٍ ولم يَتَيَسَّرْ قَضاؤهُ تَقاوَلا، وجَرَتْ بينهما خُصومةٌ شديدةٌ، فغَضِبَ عليهما عُثمانُ فعَزَلَ سعدًا واسْتعمَل الوَليدَ بن عُقبةَ، وكان عام"},{"id":229,"era":"c1","t":"سُقوط طَرابُلُس الغرب في أيدي المسلمين بقِيادةِ عبدِ الله بن أبي السَّرْحِ .","s":"أَمَرَ عُثمانُ عبدَ الله بن سعدِ بن أبي السَّرْحِ أن يَغْزُوَ بِلادَ أفريقيا فإذا افتَتَحها الله عليه فله خُمُسُ الخُمُسِ مِن الغَنيمةِ نَفْلًا، فسار إليها في عشرةِ آلافٍ فافتَتَحها سَهْلَها وجَبَلَها، وقتَل جُرْجِيرَ مَلِكَ الرُّومِ وخَلْقًا كثيرًا مِن أهلِها، ثمَّ اجتمَع أهلُ أفريقيا على الإسلامِ، وحَسُنَتْ طاعتُهم. أخَذ عبدُ الله بن سعدِ خُمُسَ الخُمُسِ مِن الغَنيمةِ، ثمَّ بعَث بخُمُسٍ إلى عُثم"},{"id":230,"era":"c1","t":"غَزْوُ الأَنْدَلُس في عَهْدِ عُثمانَ بن عفَّانَ بقِيادةِ عبدِ الله بن نافع .","s":"لمَّا افْتُتِحَتْ أفريقيا أَمَرَ عُثمانُ عبدَ الله بن نافعٍ وعبدَ الله بن عبدِ القيسِ أن يَسِيرا إلى الأَندلُس، فغَزاها مِن قِبَلِ البَحرِ، وكتَب عُثمانُ إلى مَن انْتَدَبَ معهما: أمَّا بعدُ فإنَّ القُسطنطينيَّة إنَّما تُفْتَحُ مِن قِبَلِ الأَندلُس. فخَرجوا ومعهم البَرْبَرُ، ففتَح الله على المسلمين وزادَ في سُلطانِ المسلمين مِثل أفريقيا."},{"id":231,"era":"c1","t":"المسلمون يركبون البحر ويفتحون قبرص بقِيادةِ عبدِ الله بن قيسٍ .","s":"كان مُعاويةُ بن أبي سُفيانَ قد أَلَحَّ على عُمَرَ بن الخطَّاب أنَّ يَغْزُوَ البحرَ ولكنَّه أَبَى ذلك، ثمَّ في زمنِ عُثمانَ طلَب ذلك فوافَق عُثمانُ بِشرطِ ألَّا يُجبِرَ أحدًا على ركُوبِ البحرِ؛ بل يُخَيِّرُهُم، مَن أراد الغَزْوَ معه فعَل وإلَّا فَلَا، ففعَل ذلك، واسْتَعْمَل على البحرِ عبدَ الله بن قيسٍ الجاسيَّ، ثمَّ غَزَا قبرصَ وصالَح أهلَها على سبعةِ آلافِ دِينارٍ كلَّ سَنةٍ، وقد ساعَد في ذلك الغ"},{"id":232,"era":"c1","t":"تَوْسيعُ المسجدِ النَّبويِّ .","s":"كان بِناءُ المسجدِ النَّبويِّ بالمدينةِ باللَّبِنِ والجَريدِ وأَعمِدَةِ الخشبِ، فزاد فيه عُثمانُ زِيادةً كبيرةً فجَعَله بطُولِ مائةٍ وسِتِّين ذِراعًا، وعَرْضِ مائةٍ  وخمسين ذِراعًا، وجعَل بِناءَهُ مِن الحِجارةِ المَنْقوشَةِ التي كُسِرَتْ بِطريقةٍ مُناسِبةٍ للبِناءِ، وجعَل الأَعمِدةَ مِن حِجارةٍ مع الرَّصاصِ لزِيادةِ القُوَّةِ والتَّحَمُّلِ، وسَقْفَهُ بالسَّاجِ، وجعَل له سِتَّةَ أبوابٍ كما فعَل عُم"},{"id":233,"era":"c1","t":"افْتِتاحُ طَبَرِستان بقِيادةِ سعيدِ بن العاصِ .","s":"اسْتَعاد سعيدُ بن العاصِ فَتْحَ طَبَرِستان شمال إيران؛ وذلك أنَّهم كانوا صالَحوا سُويدَ بن مُقرِّن بعدَ أن غَزاهُم قَبلَ ذلك في عَهدِ عُمَر بن الخطَّاب على أن لا يَغْزوها على مالٍ بَذَلَهُ له إصْبَهْبَذُها؛ لكنَّهم نَقَضوا الصَّلْحَ، فَرَكِبَ سعيدُ بن العاصِ في جيشٍ فيه الحسنُ والحسينُ، والعَبادِلَةُ الأربعةُ، وحُذيفةُ بن اليَمانِ، في خلقٍ مِن الصَّحابةِ فسار بهم، فمَرَّ على بُلدانٍ شَتَّى يُصالِح"},{"id":234,"era":"c1","t":"نَقْضُ أهلِ جُرْجان العَهد  .","s":"غَزا سعيدُ بن العاصِ جُرجان بعدَ أن نَقَضَ أهلُها عَهْدَهُم مع المسلمين الذي عُقِدَ في عَهدِ عُمَر بن الخطَّاب فافْتَتَحها."},{"id":235,"era":"c1","t":"عَقْدُ الصُّلْحِ بين المسلمين ومَلِكِ النُّوبَةِ .","s":"بعدَ أن انتهى عبدُ الله بن أبي السَّرْحِ مِن قِتالِ الرُّومِ في المغربِ مع ابنِ الزُّبيرِ عاد إلى النُّوبةِ التي كانت هَدَّدَتْ مِصْرَ مِن الجَنوبِ فغَزاهُم مِن جديدٍ، بعدَ أن كان غَزاهُم قَبلَه عَمرُو بن العاصِ، فقاتَل أهلَها قِتالًا شديدًا؛ ولكنَّه لم يَتَمَكَّنَ مِن الفَتْحِ فَهَادَنَ أهلَها وعقَد معهم الصُّلْحَ، وكان فيها بعضُ المُبادلاتِ الاقتِصادِيَّة."},{"id":236,"era":"c1","t":"مَقْتلُ (يَزْدَجِرْد) مَلِكِ السَّاسانِيِّين بالفُرْس وهو بِمَخْبَئِه بمدينةِ (مَرْو) .","s":"هو يَزْدَجِرْد بن شَهْرَيار بن برويز المَجوسيُّ الفارِسيُّ آخِرُ الأكاسِرَةِ مُطلقًا، انهزَم مِن جيشِ عُمَر, فاسْتَولى المسلمون على العِراقِ، وانهزَم هو إلى مَرْو، ووَلَّتْ أيَّامُه، ثمَّ ثار عليه أُمراءُ دَولتِه وقتَلوه، وقِيلَ: هرَب بأُبَّهَتِهِ في جماعةٍ يَسيرةٍ إلى مَرْو، فسأل مِن بعضِ أهلِها مالًا فمَنعوهُ وخافوهُ على أَنفُسِهم، فبعثوا إلى التُّرْكِ يَسْتَفِزُّونَهم عليه، فأَتَوْهُ فقَتلوا أص"},{"id":237,"era":"c1","t":"تَمَرُّدُ أهلِ خُراسان ثمَّ إخْضاعُهم  على يَدِ عبدِ الله بن عامرٍ .","s":"انْتَقَض أهلُ خُراسان (وهي مُوزعة الآنَ بين إيران وأفغانستان وروسيا) على عُثمانَ بن عفَّانَ رضِي الله عنه، فأرسَل إليهم عبدَ الله بن عامرٍ عامِلَه على البَصرَةِ، فاشْتَبَك مع أهالي تلك البِلادِ في مَرْو ونَيْسابور وغيرِها ففتَحها مِن جديدٍ، ثمَّ تَوَجَّه الأحنفُ بن قيسٍ -وهو الذي كان على مُقدِّمةِ جيشِ عبدِ الله بن عامرِ تَوَجَّه- إلى طَخارِستان فحاصرَهُم حتَّى صالَحوه، ولكن انْضَمَّ لهم أهلُ مَرْ"},{"id":238,"era":"c1","t":"انْتِصارُ المسلمين في مَعركةِ ذاتِ الصَّواري بقِيادةِ عبدِ الله بن أبي السَّرْحِ .","s":"لمَّا أصاب المسلمون مِن أهلِ أفريقيا وقتَلوهُم وسَبوهُم، خرَج قُسطنطين بن هِرقل في جمعٍ لم تَجمَعْ الرُّومُ مِثلَه مُذْ كان الإسلامُ، خرَجوا في خمسمائةِ مَركَبٍ عليهم قُسطنطين بن هِرقل، ورَكِبَ المسلمون البحرَ على غيرِ مِيعادٍ مع الرُّومِ وعليهم عبدُ الله بن سعدِ بن أبي السَّرْحِ أميرُ مِصْرَ حتَّى بلغوا ذاتَ الصَّواري، فلَقوا جُموعَ الرُّومِ في جمعٍ لم يَروا جمعًا مِثلَه قَطُّ, فقال عبدُ الله بن "},{"id":239,"era":"c1","t":"غَزْوُ مُعاويةَ رضِي الله عنه بِلادَ الرُّومِ .","s":"لمَّا جمَع الله لمُعاويةَ بن أبي سُفيانَ الشَّامَ كلَّها فصار أميرَ الشَّامِ كان يَغزو الرُّومَ كلَّ عامٍ في الصَّيْفِ -وتُسَمَّى الصَّائِفَةَ- فيَفتَح الله على يَديهِ البِلادَ ويَغنَم الكثيرَ حتَّى وصَل عَمُّورِيَة -وهي اليوم في أنقرة- وكان معه مِن الصَّحابةِ عُبادةُ بن الصَّامِتِ، وأبو أيُّوبَ الأنصاريُّ، وأبو ذَرٍّ الغِفاريُّ، وشَدَّادُ بن أَوْسٍ، وغيرُهم وقد فتَح الله لهم مِن البِلادِ الكثيرَ,"},{"id":240,"era":"c1","t":"فَتْحُ أَفْغانِسْتان بقِيادةِ أَوْسِ بن ثَعلبةَ والأحنفِ بن قيسٍ .","s":"فتَح أَوْسُ بن ثَعلبةَ أَفغانستان، وتابَع الأحنفُ بن قيسٍ فَتْحَها مِن ناحيةِ بَلَخ بالشَّمالِ،  ثمَّ أغار على كابُل عبدُ الرَّحمن بن محمَّدٍ، وتَمَّ فَتْحُ البِلادِ كلِّها، ثمَّ دخَل سُكَّانُ قُنْدُهار وكابُل في الإسلامِ."},{"id":241,"era":"c1","t":"وَفاةُ عبدِ الله بن مَسعودٍ رضِي الله عنه .","s":"هو عبدُ الله بن مَسعودِ بن غافِلِ بن حَبيبٍ، أحدُ المُكثِرين في الرِّوايةِ عن النَّبيِّ صلَّى الله عليه وسلَّم، قَديمُ الإسلامِ، أوَّلُ مَن جَهَر بالقُرآنِ في مكَّةَ بعدَ النَّبيِّ صلَّى الله عليه وسلَّم،كان في خِدمَةِ النَّبيِّ صلَّى الله عليه وسلَّم حتَّى كان يُعرَفُ في الصَّحابةِ بصاحِبِ السَّوادِ والسِّواكِ، وهاجَر الهِجرَتين جميعًا إلى الحَبشةِ وإلى المدينةِ، وصلَّى إلى القِبْلَتين، كان مِن ك"},{"id":242,"era":"c1","t":"وَفاةُ عبدِ الرَّحمن بن عَوفٍ رضِي الله عنه  .","s":"هو عبدُ الرَّحمنِ بنُ عَوفِ بن عبدِ عَوفِ بن عبدِ بن الحارِثِ بن زُهْرةَ بن كِلابِ بن مُرَّةَ بن كعبِ بن لُؤَيٍّ، أبو محمَّدٍ. القُرشيُّ الزُهريُّ، أحدُ العشرةِ المُبَشَّرين بالجنَّةِ، أَسلَم قبلَ أن يَدخُلَ الرَّسولُ صلَّى الله عليه وسلَّم دارَ الأرقمِ، وكان أحدَ الثَّمانيةِ الذين سَبَقوا إلى الإسلامِ، وأحدَ الخَمسةِ الذين أسلموا على يَدِ أبي بكرٍ، وأحدَ السَّابقين البَدْرِيِّين، وأحدَ السِّتَّةِ"},{"id":243,"era":"c1","t":"وَفاةُ العبَّاسِ بن عبدِ المُطَّلِب عَمِّ النَّبيِّ صلَّى الله عليه وسلَّم .","s":"هو العبَّاسُ بن عبدِ المُطَّلِب بن هاشمِ بن عبدِ مَنافٍ، أبو الفَضلِ، عَمُّ النَّبيِّ صلَّى الله عليه وسلَّم، ومِن أكابرِ قُريشٍ في الجاهِليَّةِ والإسلامِ، وجَدُّ الخُلفاءِ العبَّاسيِّين رضِي الله عنه. كان مُحسِنًا لِقومِه، سَديدَ الرَّأيِ، واسعَ العَقلِ، مُولَعًا بإعْتاقِ العَبيدِ، كارِهًا للرِّقِّ، اشْتَرى 70 عبدًا وأَعتَقَهم، وكانت له سِقايةُ الحاجِّ، وعِمارةُ المسجدِ الحرامِ -وهي أن لا يَدَعَ "},{"id":244,"era":"c1","t":"وَفاةُ أبي ذَرٍّ رضِي الله عنه .","s":"هو جُنْدُب بن جُنادة أبو ذَرٍّ الغِفاريُّ كان طُوالًا آدمَ، وكان يَتعبَّدُ قبلَ مَبعثِ رسولِ الله. صلَّى الله عليه وسلَّم، وأَسلمَ بمكَّةَ قديمًا، وقال: كنتُ في الإسلامِ رابعًا. ورجَع إلى بلادِ قومِه فأقام بها حتَّى مَضَتْ بدرٌ وأُحُدٌ والخندقُ، ثمَّ قدِم المدينةَ، كان أبو ذَرٍّ شُجاعًا يَنفَرِد وحدَه فيقطعُ الطَّريقَ ويُغِيرُ على الصِّرْمِ كأنَّه السَّبُعُ، ثمَّ إنَّ الله قذَف في قَلبِه الإسلامَ "},{"id":245,"era":"c1","t":"اسْتِعادةُ فَتْحِ قُبرص بقِيادةِ جُنادةَ بن أبي أُميَّةَ .","s":"بعدَ أن فُتِحَت قُبرص نقَضَت مُعاهدةَ الصُّلحِ ممَّا اضْطَرَّ المسلمين لِغَزْوِهِم ثانيةً بِحَمْلَةٍ بَحْرِيَّةٍ يَقودُها هذه المَرَّةِ جُنادةُ بن أبي أُميَّةَ الأَزديُّ، الذي قام بِتأدِيبِهم وإدخالِهم في التَّبَعيَّةِ مَرَّةً أُخرى."},{"id":246,"era":"c1","t":"جَمْعُ القُرآنِ الكريمِ في مُصحَفٍ واحدٍ في عهد عُثمانَ بن عفَّانَ رضي الله عنه .","s":"لمَّا كَثُرَت الفُتوحُ وبالتَّالي كَثُرَ الدَّاخِلون الجُدُدُ في الإسلامِ والمُتعَلِّمون لِكتابِ الله مِن غيرِ العَربِ ظَهرَت بعضُ الاختِلافاتِ في القِراءاتِ، ممَّا خَوَّفَ بعضَ الصَّحابةِ على مُستقبَلِ مِثلِ هذه الخِلافاتِ، فما كان مِن حُذيفةَ بن اليَمانِ رضِي الله عنه إلَّا أن تَوجَّهَ إلى عُثمانَ بن عفَّانَ وطلَب منه أن يُدرِكَ النَّاسَ قبلَ أن يَختلِفوا الاختِلافَ الذي تكونُ فيه فِتْنَتُهم واق"},{"id":247,"era":"c1","t":"بداية فِتنَةِ مَقتَلِ عُثمانَ بن عفَّانَ رضِي الله عنه .","s":"أوَّلُ بَدْءِ نُشوءِ جُذورِ الفِتنَةِ هو بخُروجِ عبدِ الله بن سَبَإٍ يَهوديٍّ مِن صَنْعاءَ، أَظهَرَ الإسلامَ ثمَّ رحَل إلى الكوفةِ والبَصرَةِ والشَّامِ يُحاوِلُ أن يُؤثِّرَ في النَّاسِ؛ لكن لم يَلْقَ تَجاوُبًا حتَّى رحَل إلى مِصْرَ وبدَأ يُشَكِّكُ في عَقيدةِ النَّاسِ، ويَزْعُم عَودةَ النَّبيِّ صلَّى الله عليه وسلَّم، وأنَّه أَحَقُّ بالعَودةِ مِن عيسى صلَّى الله عليه وسلَّم، ثمَّ بدَأ بالدَّعوَةِ ل"},{"id":248,"era":"c1","t":"اغْتِيالُ عُثمانَ بن عفَّانَ رضِي الله عنه  .","s":"بعدَ أن جاءَ وَفدٌ مِن مِصْرَ مُظْهِرين العُمرَةَ، وجاؤوا المدينةَ وناقَشوا عُثمانَ في بعضِ الأَمْرِ وأظْهَروا الشَّكْوى والتَّأَفُّفِ منه حتَّى أَقنَعهُم بما يَراهُ حتَّى خرجوا مِن عندِه راجِعين لمِصْرَ، ثمَّ جاءَ وَفدٌ مِن مِصْرَ وتَواعَدوا مع وَفدِ الكوفةِ ووَفدِ البَصرَةِ في المدينةِ؛ ولكنَّ عددًا مِن الصَّحابةِ على رأسهم عَلِيُّ بن أبي طالبٍ قام بمُواجَهَتِهم قبلَ دُخولِ المدينةِ ممَّا أخافَه"},{"id":249,"era":"c1","t":"خِلافةُ عَلِيِّ بن أبي طالبٍ رضِي الله عنه .","s":"لمَّا قُتِلَ عُثمانُ بن عفَّانَ مَظلومًا في دارهِ بَقِيَ الأمرُ في المدينةِ دون خَليفةٍ، وكان يُديرُها الغافِقِيُّ المِصْريُّ وهو مِن رُؤوسِ الفِتنَةِ هو وأصحابُه، وحاوَلوا تَولِيةَ سعدٍ وابنِ عُمَرَ ولكن لم يَتِمْ لهم الأمرُ، فعرَض الصَّحابةُ الأمرَ على عَلِيِّ بن أبي طالبٍ فرفَض في اليومِ الأوَّلِ، ثمَّ جاءَهُ طَلحةُ والزُّبيرُ وبايَعوهُ في اليومِ الثَّاني، ثمَّ بايَعهُ النَّاسُ إلَّا القَليلَ م"},{"id":250,"era":"c1","t":"مَوقعةُ الزَّابوقةِ قُبَيْلَ وَقعةِ الجَملِ .","s":"لمَّا جاء أصحابُ الجَملِ إلى البَصرَةِ لِتَأليفِ الكَلِمَةِ والتَّوَصُّلِ بذلك إلى إقامةِ الحَدِّ على قَتَلَةِ عُثمانَ وينظروا في جمعِ طَوائفِ المسلمين، وضَمِّ تَشَرُّدِهِم حتَّى لا يَضْطَرِبوا فيَقتَتِلوا، حَرَّضَ مَن كان بها مِن المُتَأَلِّبِين على عُثمانَ النَّاسَ، وقالوا: اخْرُجوا إليهم حتَّى تَروا ما جاءوا إليه. فبعَث عُثمانُ بنُ حَنيفٍ -والي البَصرَةِ مِن قِبَلِ عَلِيِّ بن أبي طالبٍ- حَكيمَ "},{"id":251,"era":"c1","t":"مَوقعةُ الجَملِ .","s":"بعدَ وَقعةِ الزَّابوقةِ بين الزُّبيرِ وطَلحةَ مع مَن أَرسَلهم عُثمانُ بن حَنيفٍ مِن أهلِ البَصرَةِ بقِيادةِ حَكيمِ بن جَبلةَ سار عَلِيٌّ مِن المدينةِ، وبعَث ابنَه الحسنَ، وعمَّارَ بن ياسرٍ إلى الكوفةِ بين يَديهِ يَسْتَنْفِران النَّاسَ، فخرَج مِن الكوفةِ سِتَّة آلافٍ، قَدِموا على عَلِيٍّ بذي قار، فسار في نحوِ عشرةِ آلافٍ، ثمَّ إنَّه وصَل إلى البَصرَةِ، فالتَقى هو وجيشُ طَلحةَ والزُّبيرِ، فاصْطَفَّ "},{"id":252,"era":"c1","t":"وَفاةُ طَلحةَ بن عُبيدِ الله رضِي الله عنه .","s":"أبو محمَّدٍ طَلحةُ بن عُبيدِ الله بن عُثمانَ بن عَمرِو بن كعبِ بن سعدِ بن تَيْمِ بن مُرَّةَ بن كعبِ بن لُؤَيٍّ، أُمُّهُ: الصَّعْبَةُ بنتُ الحَضرميِّ، أُختُ العَلاءِ، أَسلمَت وأَسلَم طَلحةُ قديمًا، هو أحدُ العشرةِ المُبَشَّرين بالجنَّةِ، مِن السَّابقين الأوَّلين إلى الإسلامِ، دَعاهُ أبو بكرٍ الصِّدِّيقُ إلى الإسلامِ، آخَى رسولُ الله صلَّى الله عليه وسلَّم بين طَلحةَ وبين أبي أيُّوبَ الأنصاريِّ، أَب"},{"id":253,"era":"c1","t":"وَفاةُ الزُّبيرِ بن العَوَّام رضِي الله عنه  .","s":"هو أبو عبدِ الله الزُّبيرُ بن العَوَّام بن خويلدِ بن أَسَدِ بن عبدِ العُزَّى بن قُصَيِّ بن كِلابٍ، أحدُ العشرةِ المُبَشَّرين بالجنَّةِ، أُمُّهُ صَفيَّةُ بنتُ عبدِ المُطَّلِب عَمَّةُ رسولِ الله صلَّى الله عليه وسلَّم، كان مِن أوائلِ الذين أسلموا، هاجَر الهِجرتين إلى الحَبشةِ وإلى المدينةِ، آخَى النَّبيُّ صلَّى الله عليه وسلَّم بينه وبين سَلمةَ بن سَلامةَ بن وَقْشٍ، قال فيه النَّبيُّ صلَّى الله عليه"},{"id":254,"era":"c1","t":"مَوقعةُ صِفِّينَ بين عَلِيٍّ ومُعاويةَ رضِي الله عنهما  .","s":"لمَّا تَسلَّم عَلِيُّ بن أبي طالبٍ الخِلافةَ بدَأ بِعَزْلِ بعضِ العُمَّالِ وأبدَلَهم بآخَرين، وكان ممَّن عزَلَهم مُعاويةُ بن أبي سُفيانَ الذي كان على الشَّامِ, كان رأيُ عَلِيٍّ في قَتلةِ عُثمانَ عدمَ الاسْتِعجالِ في القِصاصِ قبلَ أن يَسْتَتِبَّ الأمرُ ويَقْوَى سُلطانُ الخِلافةِ, وكان مُعاويةُ على رأي أهلِ الجَملِ الاسْتِعجال في الاقْتِصاصِ مِن قَتَلَةِ عُثمانَ، قَرَّرَ عَلِيٌّ عَزْلَ مُعاويةَ عن و"},{"id":255,"era":"c1","t":"مَعركةُ النَّهْرَوان وخُروجُ الخَوارجِ ونَشأَةُ فِكْرِهِم .","s":"بعد أن اتَّفَقَ فَريقُ عَلِيِّ بن أبي طالبٍ وفَريقُ مُعاويةَ على التَّحْكيمِ بعدَ القِتالِ الذي دارَ في صِفِّينَ وعاد كلُّ فَريقٍ إلى مَكانِه الأوَّلِ، فسار علِيُّ بن أبي طالبٍ عائِدًا إلى الكوفَةِ، وفي الطَّريقِ انْحازَت جَماعةٌ ممَّن لم يكونوا راضِينَ عن التَّحكيمِ وكانوا يَرَوْن أنَّ التَّحْكيمَ فقط لِكتابِ الله لا للرِّجالِ، فانصرفوا إلى حَرُوراءَ وبدأوا يَبُثُّون هذه الفِكرةَ، خارِجِينَ عن عَ"},{"id":256,"era":"c1","t":"مُعاويةُ رضِي الله عنه يَسْتَوْلِي على مِصْرَ .","s":"ازداد مُعاويةُ بنُ أبي سفيانَ رَضِيَ اللهُ عنهما بعد التحكيمِ قُوَّةً، واختلف الناسُ بالعِراقِ على عليٍّ رَضِيَ اللهُ عنه، ولم يَعُدْ له همٌّ إلَّا مِصرُ التي كان يخشاها وأهلَها؛ لقُربِهم منه، فأراد أن يَضُمَّها إليه ، فأرسل إلى مَنْ لم يبايعْ عليًّا ولم يأتَمِرْ بأمرِ نُوَّابِه يخبِرُهم بقُدومِ الجيشِ عليهم سريعًا، وكان واليها من قِبَلِ عليٍّ حينَئذٍ محمَّدَ بنَ أبي بكرٍ، وكان يواجِهُ اضطراباتٍ د"},{"id":257,"era":"c1","t":"وَفاةُ عبدِ الله بن سَبَإٍ رَأْسِ الطَّائفةِ السَّبَئِيَّةِ .","s":"هو عبدُ الله بن وَهْبٍ  الهَمْدانيُّ السَّبَئِيُّ، وقِيلَ: الحِمْيَريُّ. أصلُه مِن يَهودِ صَنْعاءَ, وقِيلَ: مِن يَهودِ الحِيرَةِ، مَعروفٌ بابنِ السَّوداءِ لأنَّ أُمَّهُ حَبَشيَّةٌ، أَظهرَ الإسلامَ في زَمَنِ عُثمانَ بن عفَّانَ, وقِيلَ: إنَّه رُوميٌّ أَظهرَ الإسلامَ هو وجماعتُه السَّبئيَّةُ بغَرَضِ تَقويضِ الدَّولةِ الإسلاميَّة لصالحِ الدَّولةِ البِيزنْطيَّة. وهو يَختلِفُ عن عبدِ الله بن وَهْبٍ الرّ"},{"id":258,"era":"c1","t":"تَوْجيهُ مُعاويةَ رضي الله عنه بُسْرَ بن أَرْطاةَ إلى الحِجازِ واليَمنِ .","s":"بعَث مُعاويةُ رضي الله عنه إلى الحِجازِ واليَمنِ بُسْرَ بن أبي أَرْطاةَ القُرشيَّ العامريَّ في جُنودٍ ووصَل عامِلُهُ هذا إلى اليَمنِ فتَنَحَّى عنها عامِلُ عَلِيٍّ عُبيدُ الله بن عبَّاسٍ، وبلَغ عَلِيًّا ذلك فجَهَّزَ إلى اليَمنِ جاريةَ بن قُدامةَ السَّعديَّ فهرب بُسْرُ من اليمن، ثمَّ رجَع عُبيدُ الله إلى اليَمنِ."},{"id":259,"era":"c1","t":"اغْتِيالُ الخَليفةِ عَلِيِّ بن أبي طالبٍ رضي الله عنه .","s":"انْتدَب ثلاثةٌ مِن الخَوارجِ، وهُم: عبدُ الرَّحمنِ بن مُلْجِمٍ المُراديُّ، والبَرْكُ بن عبدِ الله التَّميميُّ، وعَمرُو بن بكرٍ التَّميميُّ، فاجتمعوا بمكَّةَ، فتَعاهَدوا وتَعاقَدوا لَيَقْتُلَنَّ هؤلاء الثَّلاثةُ: عَلِيَّ بن أبي طالبٍ رضِي الله عنه، مُعاويةَ بن أبي سُفيانَ، وعَمرَو بن العاصِ، ويُريحوا العِبادَ منهم، فقال ابنُ مُلْجِمٍ: أنا لِعَلِيٍّ. وقال البَرْكُ: أنا لِمُعاويةَ، وقال الآخرُ: أنا أ"},{"id":260,"era":"c1","t":"خِلافةُ الحسنِ بن عَلِيٍّ رضِي الله عنهما .","s":"بعدَ أن قُتِلَ الخليفةُ الرَّاشدُ عَلِيُّ بن أبي طالبٍ رضِي الله عنه وأَرضاهُ اتَّجهَ أهلُ الكوفةِ إلى الحسنِ بنِ عَلِيٍّ فبايَعوهُ بالخِلافةِ، وكان أوَّلَ مَن بايَعهُ قيسُ بن سعدٍ، وبَقِيَ في الخِلافةِ سِتَّةَ أَشهُرٍ، رأى خِلالَها تَخاذُلَ أصحابِه، فرأى ضَرورةَ اتِّفاقِ الأُمَّةِ فآثَر الصُّلْحَ وتَنازَل لِمُعاويةَ بالخِلافةِ، وسُمِّيَ ذلك العامُ بعامِ الجَماعةِ، وكان كما قال عنه النَّبيُّ صلَّى"},{"id":261,"era":"c1","t":"تَنازُل الحسنِ بن عَلِيٍّ بن أبي طالِب رضي الله عنه عن الخِلافَة .","s":"لمَّا قتل عَلِيُّ بن أبي طالِب رضي الله عنه بايَع أهلُ الكوفَة الحسنَ بن عَلِيٍّ، وأطاعوه وأحبُّوه, فاشْتَرط عليهم: إنَّكم سامِعون مُطيعون، مُسالِمون مَن سالَمْتُ، مُحارِبون مَن حارَبْتُ. فارتاب به أهلُ العِراق وقالوا: ما هذا لكم بصاحب. فما كان عن قَريب حتَّى طعنوه، فازداد لهم بُغْضًا، وازداد منهم ذُعْرًا، فعند ذلك عرَف تَفرُّقَهُم واخْتِلافَهُم عليه, وكان أهلُ العِراق أشاروا على الحسن أن يَسير إل"},{"id":262,"era":"c1","t":"بِدايةُ حُكم الأُمويِّين في دِمشقَ .","s":"بعدَ أن تَنازَل الحسنُ بن عَلِيٍّ رضي الله عنه لمُعاوِيَة بالخِلافَة أصبح مُعاوِيَةُ هو الخَليفَةَ الشَّرعيَّ للمسلمين، فكان بذلك أوَّل بِدايَة الدَّولة الأُمويَّة التي كانت عاصمتُها دِمشقَ، ومِن المعلوم أنَّ هذه الدَّولة اسْتَمرَّت إحدى وتِسعين سنة."},{"id":263,"era":"c1","t":"بداية خروج الخَوارِج على مُعاوِيَة رضي الله عنه .","s":"كان أوَّلَ الخارِجين فَروةُ بن نَوفلٍ الأشجعيُّ، وكان ممَّن اعتزَل قِتالَ عَلِيٍّ والحسنِ وانحاز معه خمسُمائة فارسٍ مِن الخَوارِج إلى شَهْرَزُور، قائلًا: والله ما أدري على أيِّ شيءٍ نُقاتِلُ عَلِيًّا! أرى أن أَنصَرِفَ حتَّى تَتَّضِحَ لي بَصيرَتي في قِتالِه أو أُتابِعُه. فلمَّا سَلَّمَ الحسنُ الأمرَ إلى مُعاوِيَة قالوا: قد جاء الآن ما لا شَكَّ فيه، فسيروا إلى مُعاوِيَة فجاهِدوهُ. فأقبلوا وعليهم فَر"},{"id":264,"era":"c1","t":"تَوَغُّلُ عُقبةَ بن نافعٍ في أفريقيا .","s":"تَوَغَّلَ عُقبةُ بن نافعٍ في أفريقيا حتَّى فتَح غَدامِسَ ووَدَّانَ وبِلادَ البَرْبَر."},{"id":265,"era":"c1","t":"أوَّلُ مُحاولاتِ فَتْحِ القُسطنطينيَّة .","s":"كان أوَّلَ مَن بدَأ ذلك بُسْرُ بن أَرْطاةَ الذي أَرسلَهُ مُعاوِيَةُ في الشَّاتِيَةِ فوصَل إلى القُسطنطينيَّة ولكن لم تُفْتَحْ."},{"id":266,"era":"c1","t":"الخوارج يختارون المُسْتَوْرِد بن عُلَّفَةَ التَّيميِّ قائداً لهم .","s":"بَقِيَتْ بَقِيَّةٌ مِن الخَوارِج الذين خرَجوا على عَلِيِّ بن أبي طالِب يومَ النَّهْروان، وهؤلاء بقوا يَبُثُّون أَفكارَهُم في الكوفَة والبَصْرَة وغيرِها، وكان بَدْءُ تَحَرُّكِهِم للخُروجِ سنة 42هـ، عندما بَدأوا يَتَشاوَرون في ذلك، فقد كانت الخَوارِج يَلْقى بعضُهم بعضًا فيُذاكِرون مَصارِعَ إخوتِهم بالنَّهْرِ، فيَتَرَحَّمون عليهم، ويَحُضُّ بعضُهم بعضًا على الخُروجِ للانتِقام مِن حُكَّامِهِم الجائرين،"},{"id":267,"era":"c1","t":"وَفاةُ عَمرِو بن العاصِ رضِي الله عنه حاكِمِ مِصْرَ .","s":"هو عَمرُو بن العاصِ بن وائلِ بن هاشِم بن سُعَيْدِ –بالتصغير- بن سهمِ بن عَمرِو بن هُصَيْص بن كعبِ بن لُؤَيٍّ القُرشيُّ السَّهميُّ، أميرُ مِصْرَ، يُكَنَّى أبا عبدِ الله، وأبا محمَّد، أَسلَم قبلَ الفتحِ في صَفَر سنة ثمانٍ، وقِيلَ: بين الحُديبيَة وخيبر، ولمَّا أَسلَم كان النَّبِيُّ صلَّى الله عليه وسلَّم يُقَرِّبُه ويُدْنِيهِ لِمَعرفتِه وشَجاعتِه. ووَلَّاهُ غَزوةَ ذاتِ السَّلاسِل، وأَمَدَّهُ بأبي بكر"},{"id":268,"era":"c1","t":"أوَّلُ فُتوحِ المسلمين للهِنْدِ .","s":"تَمَّ الفتحُ على يَدِ المُهَلَّب بن أبي صُفْرَةَ حيث بدَأ بِغَزْوِ مُكْران حتَّى وصَل إلى قَنْدابيل، وكسَر العَدُوَّ وسَلِمَ وغَنِمَ. وبه تَعَرَّف أهلُ البِلادِ على الإسلامِ وشَرائِعِه فدخَل منهم عددٌ كبيرٌ في الإسلامِ."},{"id":269,"era":"c1","t":"وَفاةُ أُمِّ المؤمنين أُمِّ حَبيبةَ بنتِ أبي سُفيان رضي الله عنها .","s":"هي رَمْلَةُ بنتُ أبي سُفيان، أُخْتُ مُعاوِيَة، أُمُّها صَفيَّةُ بنتُ أبي العاصِ بن أُمَيَّة، كانت تحت عُبيدِ الله بن جَحشٍ، خرجت معه مُهاجِرة إلى الحَبشةِ ومات زَوجُها هناك، فخطَبها وهي هناك النَّبِيُّ صلَّى الله عليه وسلَّم، وزَوَّجَهُ إيَّاها النَّجاشيُّ وأَصدَقَ عنه، ثمَّ حُمِلَتْ إليه إلى المدينةِ، تُوفِّيَت في المدينةِ في خِلافَة أخيها مُعاوِيَة."},{"id":270,"era":"c1","t":"فَتحُ سُوسَة وتَدمِيرُ قَلعةِ جَلُولاء البِيزَنطِيَّة شمالَ أفريقيا .","s":"كان مُعاوِيَةُ بن خَديجٍ أميرَ أفريقيا، فوُجِّه عبدُ الله بن الزُّبير ففتَح سُوسَة، وأمَّا عبدُ الملك بن مَرْوان فقد اسْتَولى على جَلُولاء ودَمَّرَ قَلعَتها البِيزَنطيَّة."},{"id":271,"era":"c1","t":"وَفاةُ أُمِّ المؤمنين حَفصةَ بنتِ عُمَر رضِي الله عنها .","s":"هي حَفصَةُ بنتُ عُمَر بن الخطَّاب، أُمُّها زينبُ بنتُ مَظعونِ بن حَبيبِ بن وَهْبٍ، كانت تحت خُنَيْس بن حُذافَة بن قيسِ بن عَدِيٍّ، هاجَرا سَوِيًّا للمدينةِ، ثمَّ تُوفِّي عنها بعدَ بدرٍ فتَزَوَّجَها النَّبِيُّ صلَّى الله عليه وسلَّم، ثمَّ طَلَّقَها تَطليقَة ثمَّ ارْتَجَعَها، أَمَرَهُ جِبريلُ بذلك وقال: (إنَّ الله يَأمُرك أن تُرْجِعَها إنَّها صَوَّامَة قَوَّامَة، وإنَّها زَوجتُك في الجنَّة). توفِّيت"},{"id":272,"era":"c1","t":"الخَطيمُ الباهليُّ وسَهْمُ الهُجَيميُّ يتأثرون بفكر الخوارج .","s":"خرَج الخَطيمُ، وهو يَزيدُ بن مالكٍ الباهليُّ، وسَهْمُ بن غالبٍ الهُجَيميُّ فحَكَما؛ فأمَّا سهمٌ فإنَّه خرَج إلى الأهوازِ فحَكَم بها، ثمَّ رجَع فاخْتَفى وطلَب الأمانَ فلم يُؤَمِّنْهُ زيادٌ وطلَبَهُ حتَّى أخذَهُ وقتَلَهُ وصَلَبَهُ على بابهِ، وأمَّا الخَطيمُ فإنَّ زِيادًا سَيَّرَهُ إلى البَحرَيْن ثمَّ أَقْدَمَهُ، وقال لمُسلمِ بن عَمرٍو الباهليِّ -والدِ قُتيبةَ بن مُسلمٍ-: اضْمَنْهُ. فأَبَى، وقال: إن "},{"id":273,"era":"c1","t":"عُقبةُ بن نافعٍ يَفتَح شمالَ أفريقيا  .","s":"عَزَل مُعاوِيَةُ بن أبي سُفيان مُعاوِيَةَ بن خَديجٍ عن أفريقيا، واسْتَعمل عليها عُقبةَ بن نافعٍ الفِهْريَّ، وكان مُقِيمًا بِبَرْقَةَ وزَوِيلَةَ مُذْ فتَحها أيَّام عَمرِو بن العاصِ، وله في تلك البِلادِ جِهادٌ وفُتوحٌ. فلمَّا اسْتَعمله مُعاوِيَةُ سَيَّرَ إليه عشرةَ آلاف فارسٍ، فدخَل أفريقيا وانْضافَ إليه مَن أَسلَم مِن البَرْبَر، فكَثُرَ جَمْعُهُ، ووضَع السَّيفَ في أهلِ البِلادِ لأنَّهم كانوا إذا دخ"},{"id":274,"era":"c1","t":"الحِصارُ الأوَّلُ للقُسطنطينيَّة عاصِمَة البِيزَنطيَّنين بقِيادَة سُفيان بن عَوفٍ .","s":"جَهَّزَ مُعاوِيَةُ بن أبي سُفيان جيشًا عظيمًا بَرًّا وبَحْرًا لِغَزْوِ القُسطنطينيَّة، وكان قائدَ الجيشِ سُفيانُ بن عَوفٍ الأزديُّ، وقاد الأُسْطولَ بُسْرُ بن أَرْطاة, وكان في الجيشِ ابنُ عبَّاسٍ، وابنُ عُمَر، وأبو أَيُّوبَ، وابنُ الزُّبيرِ، والحُسينُ بن عَلِيٍّ رضي الله عنهم، انْضَمُّوا إلى هذه الحَملَةِ مُتَمَثِّلينَ أَمامَ أَعيُنِهم قولَ الرَّسولِ: (لَتُفْتَحَنَّ القُسطنطينيَّةُ فَلَنِعْمَ الأمي"},{"id":275,"era":"c1","t":"وَفاةُ الحسن بن عَلِيِّ بن أبي طالِب رضِي الله عنهما  .","s":"هو أبو محمَّد الحسنُ بن عَلِيِّ بن أبي طالِب الهاشِميُّ القُرشيُّ، المَدنيُّ الشَّهيدُ، سِبْطُ رسولِ الله صلَّى الله عليه وسلَّم ورَيْحانَتُه مِن الدُّنيا, وكان أَكثَرَهُم شَبَهًا بِوَجْهِ رسولِ الله صلَّى الله عليه وسلَّم, وهو سَيِّدُ شَبابِ أهلِ الجنَّة، ابنُ فاطِمةَ بنتِ رسولِ الله صلَّى الله عليه وسلَّم، وأبوهُ أميرُ المؤمنين عَلِيٌّ رضي الله عنه. وُلِدَ الحسنُ رضي الله عنه في نِصف رَمضان سنة "},{"id":276,"era":"c1","t":"بِناءُ عُقبةَ بن نافعٍ مَحَطَّةً للجِهادِ اسمُها (القَيْروان) .","s":"بعدَ أن انْتَصر عُقبةُ بن نافعٍ في عِدَّةِ مَواقِع في فُتوحِه في أفريقيا على البَرْبَر رأى أن يَتَّخِذَ مدينةً يكونُ بها عَسكرُ المسلمين وأهلُهم وأموالُهم لِيَأمَنوا مِن ثَورَةٍ تكونُ مِن أهلِ البِلادِ، فقصَد مَوضِعَ القَيْروان، وكان أَجَمَةً مُشتبِكة بها مِن أنواعِ الحيوانِ، فأمَر ببِناءِ المدينةِ، فبُنِيَت، وبَنَى المسجدَ الجامعَ، وبَنَى النَّاسُ مَساجِدَهم ومَساكِنَهم، وكان دُورُها ثلاثة آلاف ب"},{"id":277,"era":"c1","t":"وَفاةُ أُمِّ المؤمنين صَفِيَّة بنتِ حُيَيٍّ رضي الله عنها .","s":"هي صَفِيَّةُ بنتُ حُيَيِّ بن أَخْطَبَ، مِن وَلَدِ هارونَ النَّبِيِّ صلَّى الله عليه وسلَّم، وأُمُّها بَرَّةُ بنتُ سَمَوْأَل أُخْتُ رِفاعةَ، كانت تحت سَلَّامِ بنِ مِشْكَمٍ القُرَظيِّ، ثمَّ خلَف عليها كِنانةُ بن الرَّبيعِ بن أبي الحُقَيْقِ، سَباها النَّبِيُّ صلَّى الله عليه وسلَّم مِن خَيبر وكانت عَروسًا، وأَعْتَقَها وتَزوَّجَها بعدَ مَرجِعِه مِن خَيبر، توفِّيت في المدينةِ ودُفِنت في البَقيعِ رضي ال"},{"id":278,"era":"c1","t":"وَفاةُ سعيدِ بن زيدٍ رضِي الله أَحَدِ العشرةِ المُبَشَّرين بالجنَّة .","s":"هو سعيدُ بن زيدِ بن عَمرِو بن نُفيلٍ، أَحَدُ العشرةِ المُبَشَّرين بالجنَّة، أَسلَم قديمًا قبلَ عُمَرَ، هو وامرأتُه فاطمةُ بنتُ الخطَّاب، وهي كانت سببَ إسلامِ عُمَر، وكان مِن المُهاجرين الأوَّلين، وآخَى رسولُ الله صلَّى الله عليه وسلَّم بينه وبين أُبَيِّ بن كعبٍ، صلَّى عليه عبدُ الله بن عُمَر، ونزَل في قَبرِه هو وسعدُ بن أبي وقَّاصٍ."},{"id":279,"era":"c1","t":"وَفاةُ أُمِّ المؤمنين مَيمونَة بنتِ الحارِث رضِي الله عنها .","s":"هي مَيمونَةُ بنتُ الحارِثِ بن حَزْنِ بن بُجيرِ بن الهُزَمِ، وأُمُّها هِندُ بنتُ عَوفِ بن زُهيرٍ، كانت تحت مَسعودِ بن عَمرِو بن عبدِ نائلٍ الثَّقفيِّ في الجاهليَّة وفارَقَها، ثمَّ خلَف عليها أبو رُهْمِ بن عبدِ العُزَّى بن أبي قيسِ بن عبدِ وُدٍّ فتُوفِّي عنها فتَزوَّجها النَّبِيُّ صلَّى الله عليه وسلَّم في عُمرَةِ القَضاءِ، وهي آخِرُ نِسائِه تَزْوِيجًا، توفِّيت في سَرِفَ قُربَ مكَّة في المكان الذي ب"},{"id":280,"era":"c1","t":"زِيادِ بن خِراشٍ العِجْليِّ يلتحق بفكر الخوارج .","s":"خرَج زيادُ بن خِراشٍ العِجليُّ -ثائِرٌ مِن الحَروريَّة على مُعاوِيَة بن أبي سُفيان- في ثلاثمائةِ فارسٍ، فأتى أرضَ مَسْكِن مِن السَّوادِ، فسَيَّرَ إليه زيادُ بن أَبيهِ خَيلًا عليها سعدُ بن حُذيفةَ أو غيرُه، فقَتَلوهم وقد صاروا إلى ماه، ونَشَبَت مَعاركُ انتهَت بقَتلِ زيادٍ العِجليِّ. ثمَّ خرَج على زيادِ بن أَبيهِ أيضًا رجلٌ مِن طَيِّء يُقالُ له: مُعاذ، فأتى نَهْرَ عبدِ الرَّحمن ابنِ أُمِّ الحَكَمِ ف"},{"id":281,"era":"c1","t":"فَتحُ المسلمين جزيرة رُودِس (من جزر اليونان) .","s":"افتَتَح المسلمون وعليهم جُنادةُ بن أبي أُمَيَّة \"جَزيرةَ رُودِس\" فأقام بها طائفةٌ مِن المسلمين، كانت أشدَّ شيءٍ على الكُفَّار، يَعتَرِضون لهم في البَحرِ ويَقطَعون سَبيلَهم، وكان مُعاوِيَة يَدِرُّ عليهم الأرزاقَ والأُعْطِيات الجَزيلةَ، وكانوا على حَذَرٍ شَديدٍ مِن الفِرنْج، يَبِيتون في حِصْنٍ عَظيمٍ فيه حَوائِجُهم ودَوابُّهُم وحَواصِلُهم، ولهم نَواطِير على البَحرِ يُنذِرونَهُم إن قَدِمَ عَدُوٌّ أو "},{"id":282,"era":"c1","t":"الحِصارُ الثَّاني للقُسطنطينيَّة .","s":"كان هذا الحِصارُ في هذه المَرَّةِ بقِيادَة فَضالَةَ بن عُبيدٍ الأنصاريِّ، وعلى الأُسْطولِ البَحريِّ عبدُ الله بن قيسٍ الحارثيُّ، وجُنادةُ بن أبي أُمَيَّة، وأمَّا أسطولُ الشَّام فكان بإمْرَةِ يَزيدَ بن شَجَرَة الرُّهاويِّ، ودام هذا الحِصارُ إلى عام 57 هـ، احْتَلُّوا فيها عِدَّةَ جُزُرٍ قريبة كأَرْواد وكزيكوس، واتُّخِذَت قَواعِد عَسكريَّة, ولم تَسْتطِعْ هذه الحَمْلةُ الثَّانية اقْتِحامَ القُسطنطينيّ"},{"id":283,"era":"c1","t":"فتحُ المسلمين جزيرة كَرِيت \"أَقْرِيطِش\" (أكبرُ الجُزُرِ اليُونانيَّة) .","s":"هي أكبرُ الجُزُرِ اليُونانيَّة، وخامسُ أكبرِ جَزيرة في البحرِ الأبيضِ المتوسِّط، وصَل المسلمون إلى كَرِيت في وقتٍ مُبَكِّر، إذ ضرَبوا الحِصارَ عليها ولم يَنتصِف القَرنُ الأوَّلُ الهجريُّ بعدُ؛ ولكنَّهم لم يَتمكَّنوا مِن فَتحِها، إذ أن قُوَّتَهم البَحريَّة لم تكُن قد تكامَلَت بعدُ. رَوَى البَلاذُرِيُّ: غَزا جُنادةُ بن أبي أُمَيَّة أَقْرِيطِش، فلمَّا كان زمن الوَليدِ بن عبدِ الملك فتَح بعضَها ثمَّ أ"},{"id":284,"era":"c1","t":"غارةُ الأُمَويِّين على بِلاد البَلْقان وفَتحُها جُزئيًّا\n  .","s":"البَلْقان هي شِبه جَزيرة تقَع في الجنوبِ الشَّرقيِّ مِن قارَّة أوروبا، وتَضُمُّ عَديدًامِن بُلدان شرق أوروبا مثل: المجر، رومانيا، يوغسلافيا سابقًا، وبلغاريا. اتَّجهت أَنظارُ المسلمين نحوَ الشَّمال والغربِ حيث الدَّولة الرُّومانيَّة الشَّرقيَّة التي كانت تُغيرُ على المناطقِ الخاضِعة لِسُلطان المسلمين, فرَتَّبَ مُعاوِيَةُ الغَزْوَ إليها بَرًّا وبَحرًا، وجَهَّزَ أُسطولًا بلَغ عددُه 1700 سَفينة، وفتَح"},{"id":285,"era":"c1","t":"وَفاةُ سعدِ بن أبي وقَّاص رضي الله عنه أَحَدِ العشرةِ المُبَشَّرين بالجنَّة  .","s":"هو سعدُ بن أبي وقَّاص مالكِ بن أُهَيْب، الزُّهريُّ القُرشيُّ، صَحابيٌّ مِن أوائلِ مَن دَخلوا في الإسلامِ، وكان في السَّابعة عشر مِن عُمُرهِ، ولم يَسبِقْهُ في الإسلامِ إلَّا أبو بكرٍ، وعَلِيٌّ، وزَيدٌ، وهو أحدُ العَشرةِ المُبَشَّرين بالجنَّة، فكان مِن المُتَقَدِّمين في الإسلامِ، شَهِد المَشاهِدَ كُلَّها، أوَّلُ مَن رَمى بِسَهمٍ في سَبيلِ الله، وله قال النَّبِيُّ صلَّى الله عليه وسلَّم: (ارْمِ سعدُ "},{"id":286,"era":"c1","t":"فَتحُ بلاد ما وراءَ النَّهْرِ وإغارةُ سعيدِ بن عُثمان على بُخارى وفَتحُها .","s":"وَلَّى مُعاوِيَةُ بن أبي سُفيان عُبيدَ الله بن زيادٍ على خُراسان فبلَغ بِيكَنْد وأَرْغَم خاتون أَميرَةَ بُخارى على الصُّلْحِ؛ ولكنَّها اسْتَنجدَت بالتُّرْكِ فأرسلوا جيشًا أَلْحَقَ به المسلمون الهَزيمةَ، فأُرْغِمت على طَلَبِ الصُّلْحِ، وكان مُعاوِيَةُ قد وَلَّى سعيدَ بن عُثمان بن عفَّان إمارةَ خُراسان بَدَل عُبيدِ الله فدخَل الجيشُ بُخارى بقِيادَتِه."},{"id":287,"era":"c1","t":"وَفاةُ أُمِّ المؤمنين جُوَيْرِيَة بنتِ الحارِث رضِي الله عنها .","s":"هي ابنةُ سَيِّدِ بَنِي المُصْطَلِق مِن خُزاعَة، وقَعَت في السَّبْي بعدَ غَزوةِ المُصطَلِق فوقَعَت في سَهْمِ ثابتِ بن قيسٍ، فكاتَبَتْ نَفْسَها ثمَّ أَتَت النَّبِيَّ صلَّى الله عليه وسلَّم تَستَعينُه فعَرَضَ عليها أن يُؤَدِّيَ عنها ويَتَزوَّجها فقَبِلَت، وكانت قبلَ ذلك -يعني قبلَ السَّبْي- تحت صَفوان بن مالكٍ وقد قُتِلَ فيمَن قُتِلَ في الغَزوةِ، ثمَّ لمَّا تَزوَّجها النَّبِيُّ صلَّى الله عليه وسلَّم"},{"id":288,"era":"c1","t":"عَزْلُ مَرْوانَ بن الحَكَمِ عن المدينةِ وتَوْلِيةُ الوَليدِ بن عُتبةَ .","s":"عَزَلَ مُعاوِيَةُ رضي الله عنه مَرْوانَ بن الحَكَمِ عن المدينةِ ووَلَّى عليها الوَليدَ بن عُتبةَ بن أبي سُفيان، وهو الذي حَجَّ بالنَّاسِ في هذه السَّنةِ، لأنَّه صارت إليه إمْرَةُ المدينةِ، ولم يَزَلْ عليها والِيًا حتَّى مات مُعاوِيَةُ رضي الله عنه."},{"id":289,"era":"c1","t":"وَفاةُ أُمِّ المؤمنين عائِشةَ رضِي الله عنها .","s":"هي عائشةُ الصِّدِّيقةُ بنتُ الصِّدِّيق رضي الله عنها، تَزوَّجها رسولُ الله صلَّى الله عليه وسلَّم بعدَ خَديجةَ في مكَّة؛ ولكن لم يَدْخُلْ بها إلَّا في المدينةِ بعدَ الهِجرَةِ، لها مِن الفضائلِ الكثيرُ، نزلت بَراءتُها مِن السَّماءِ بآياتٍ تُتْلَى إلى يومِ القِيامَة، توفِّيت في المدينةِ النَّبَوِيَّةِ وأَوْصَتْ أن تُدْفَنَ ليلًا، وصلَّى عليها أبو هُريرةَ، ونزَل في قَبرِها خمسةٌ ودُفِنَت في البَقيعِ،"},{"id":290,"era":"c1","t":"وَفاةُ أبي هُريرةَ رضي الله عنه .","s":"أَسلَم أبو هُريرةَ سنةَ خَيبرَ، ولَزِمَ النَّبِيَّ صلَّى الله عليه وسلَّم حتَّى وَفاتِه، فكان ذلك ذُخْرًا له، فلا ضَيْرَ أن يكونَ أكثرَ الصَّحابةِ رِوايةً عن رسولِ الله صلَّى الله عليه وسلَّم فهو مِن حُفَّاظِهم، ودَعا له النَّبِيُّ صلَّى الله عليه وسلَّم بالحِفْظِ فقارَبَت الأحاديثُ التي مِن رِوايَتِه إلى خمسةِ آلاف حديثٍ، وقد اخْتُلِف في اسمِه، وكان يدعو الله ألَّا تُدْرِكَه سَنَةُ سِتِّين فتُوفّ"},{"id":291,"era":"c1","t":"وَفاةُ أُمِّ المؤمنين أُمِّ سَلَمةَ رضِي الله عنها .","s":"هي هِندُ بنتُ أبي أُمَيَّة سُهيلِ بن المُغيرَةِ بن عبدِ الله، وأُمُّها عاتِكَةُ بنتُ عامرِ بن رَبيعَة، كانت تحت أبي سَلمةَ عبدِ الله بن عبدِ الأَسَدِ بن هِلالٍ، كانت أوَّلَ مَن هاجَر إلى الحَبشةِ هي وزَوجُها، ويُقالُ أيضًا: إنَّ أُمَّ سَلَمةَ أوَّلُ ظَعينَة هاجَرَت إلى المدينةِ، تَزوَّجها النَّبِيُّ صلَّى الله عليه وسلَّم بعدَ بدرٍ، وقِيلَ: بعدَ أُحُدٍ. وقِصَّتُها يومَ الحُديبيَة حيث أشارَت على ال"},{"id":292,"era":"c1","t":"وَفاةُ مُعاوِيَة بن أبي سُفيان رضي الله عنه .","s":"هو أبو عبدِ الرَّحمن مُعاوِيَةُ بن أبي سُفيان الأُمَويُّ القُرشيُّ، مِن أصحابِ الرَّسول صلى الله عليه وسلم، وأحدُ كُتَّابِ الوَحْي، سادِسُ الخُلفاءِ في الإسلامِ، وأوَّلُ مُلوكِ المسلمين، ومُؤَسِّسُ الدَّولةِ الأُمويَّة في الشَّام، وُلِدَ بمكَّة وتَعَلَّم الكِتابَةَ والحِسابَ، أَسلَم مُعاوِيَةُ رضي الله عنه يومَ الفَتحِ، وقِيلَ: في عُمرَةِ القَضاءِ وكان يَكتُم إسلامَهُ خَوفًا مِن أَبيهِ، وقد اسْتَع"},{"id":293,"era":"c1","t":"يَزيدُ بن مُعاوِيَة يَتَوَلَّى الخِلافَة الأُمويَّة بعدَ وَفاةِ والِدهِ .","s":"كان مُعاوِيَةُ في عام 50 هـ قد عَهِدَ إليه بالخِلافَة مِن بعدِه، وأخَذ ذلك على النَّاسِ؛ ولكنَّ البعضَ لم يَرْضَ مِثلَ ابنِ عُمَر، وابنِ الزُّبيرِ، وعبدِ الرَّحمن بن أبي بكرٍ، والحُسينِ بن عَلِيٍّ، ثمَّ لمَّا حضَرَت مُعاوِيَةَ الوَفاةُ كان يَزيدُ غائبًا فأَوْصى إليه، ثمَّ لمَّا تُوفِّي بايَعَت الأمصارُ لِيَزيدَ إلَّا مَن ذُكِرَ آنِفًا، وبذلك تَمَّتْ له الخِلافَة، ثمَّ بايَع له ابنُ عُمَرَ، وابنُ ع"},{"id":294,"era":"c1","t":"مُراسَلةُ الكوفيِّين الحُسينَ بن عَلِيٍّ رضِي الله عنه ومَسيرُه إليهم .","s":"بِمُجَرَّد وَفاةِ مُعاوِيَة بن أبي سُفيان سارَع زُعماءُ الكوفَة بالكِتابةِ إلى الحُسين بن عَلِيٍّ رضي الله عنه، وطلبوا منه المَسيرَ إليهم على وَجْهِ السُّرعةِ, فلمَّا تَواتَرت الكُتُبُ إليه مِن جِهَةِ أهل العِراق, وتَكرَّرت الرُّسُلُ بينهم وبينه, وجاءَهُ كِتابُ مُسلِم بن عَقِيلَ بالقُدومِ عليه بأَهْلِه, ثمَّ وقَع في غُبونِ ذلك ما وقَع مِن قَتْلِ مُسلمِ بن عَقِيلَ والحُسينُ لا يَعلَم بشيء مِن ذلك, "},{"id":295,"era":"c1","t":"فَتحُ عُقبةَ بن نافعٍ باغايَة وطَنْجَة وأَرَبَة. \n  .","s":"سار عُقبةُ بن نافعٍ بعدَ أن وَلَّاهُ يَزيدُ أفريقيا في عَسكرٍ عَظيمٍ حتَّى دخَل مَدينةَ باغايَة وقد اجْتَمع بها خَلْقٌ كثيرٌ مِن الرُّومِ، فقاتَلوهُ قِتالًا شَديدًا وانْهزَموا عنه، وقَتَلَ فيهم قَتلًا ذَريعًا، وغَنِمَ منهم غَنائمَ كثيرةً، ودخَل المُنْهزِمون المدينةَ وحاصَرهُم عُقبةُ. ثمَّ كَرِهَ المُقامَ عليهم فسار إلى بلاد الزَّابِ، وهي بِلادٌ واسعةٌ فيها عِدَّةُ مُدُنٍ وقُرىً كثيرةٍ، فقصَد مَدين"},{"id":296,"era":"c1","t":"مَقْتَلُ الحُسينِ بن عَلِيٍّ رضِي الله عنهما في كَرْبَلاء  .","s":"لم يُبايِعْ الحُسينُ بن عَلِيٍّ رضي الله عنه لِيَزيدَ، وبَقِيَ في مكَّة هو وابنُ الزُّبيرِ؛ ولكنَّ أهلَ الكوفَة راسَلوا الحُسينَ لِيَقْدُمَ عليهم لِيُبايِعوهُ ويَنصُروهُ فتكونُ له الخِلافَة، وكان على الكوفَة عُبيدُ الله بن زيادٍ، فبعَث الحُسينُ ابنَ عَمِّهِ مُسلِم بن عَقِيلَ لِيَعلَمَ له صِدْقَ أهلِ الكوفَة، فقَبَضَ عليه ابنُ زيادٍ وقَتَلَهُ، وتَوالَت الكُتُبُ مِن أهلِ الكوفَةِ للحُسينِ لِيَحضُرَ "},{"id":297,"era":"c1","t":"سُقوطُ مَدينةِ القَيْروان في يَدِ البَرْبَر واسْتِشْهادُ عُقبةَ بن نافع .","s":"لمَّا أُهِينَ كُسيلَةُ البَرْبَريُّ مِن قِبَلِ أبي المُهاجِر قائدِ عُقبةَ بن نافعٍ أَضْمَرَ كُسيلَةُ الغَدْرَ، فلمَّا رأى الرُّومُ قِلَّةَ مَن مع عُقبةَ أرسلوا إلى كُسيلةَ وأَعْلَموه حالَهُ، وكان في عَسكرِ عُقبةَ مُضمِرًا للغَدْرِ، وقد أَعلَم الرُّومَ ذلك وأَطْمَعَهُم، فلمَّا راسَلوهُ أَظهَر ما كان يُضْمِرُهُ وجمَع أهلَهُ وبَنِي عَمِّهِ وقصَد عُقبةَ وانْفَصل عنه ولَحِقَ بالرُّومِ وهاجَم عُقبةَ وجم"},{"id":298,"era":"c1","t":"غَزْوُ عُقبةَ بن نافعٍ شمال أفريقيا  .","s":"قام أَميرُ أفريقيا عُقبةُ بن نافعٍ باجْتِياح المغربِ كُلِّه مِن أدناهُ إلى أقصاهُ حتَّى بلَغ ساحِلَ المُحيطِ الأطلسي."},{"id":299,"era":"c1","t":"فِتنَةُ عبدِ الله بن الزُّبير رضي الله عنه ضِدَّ الدَّولةِ الأُمويَّة .","s":"كان ابنُ الزُّبيرِ رضي الله عنه رافِضًا بَيْعَة يَزيدَ بن مُعاوِيَة منذ أن حاوَل مُعاوِيَةُ رضي الله عنه أَخْذَ البَيْعَة لابنِه يَزيدَ مِن ابنِ عُمَر والحُسينِ وابنِ الزُّبيرِ، وبعدَ وَفاةِ مُعاوِيَة رضي الله عنه انتقَل ابنُ الزُّبيرِ والحُسينُ بن عَلِيٍّ مِن المدينةِ إلى مكَّة, وبعدَ قَتْلِ الحُسينِ بن عَلِيٍّ رضي الله عنه خلَع عبدُ الله بن الزُّبير عامِلَ يَزيدَ في مكَّة، وقَدَّمَ بدلًا عنه مُص"},{"id":300,"era":"c1","t":"الأُمَوِيُّون يَقْتَحِمون المدينةَ النَّبوِيَّةَ (مَعركَةُ الحَرَّةِ) .","s":"لمَّا بايَع أهلُ المدينةِ لعبدِ الله بن الزُّبيرِ وخَلعوا بَيْعَة يَزيدَ وخَلعوا والِيَهُ في المدينةِ وحاصروا بني أُمَيَّة في دارِ مَرْوان أرسَل إليهم يَزيدُ جيشًا بقِيادَةِ مُسلِم بن عُقبةَ المُرِّيِّ، وكان كبيرًا مريضًا، فلمَّا وصَل المدينةَ حاصَرها مِن طَرْف الحَرَّةِ الشَّرقيَّة مِن طريقِ الكوفَة وقتَها، وأَمْهَلَهُم ثلاثةَ أيَّام لِيَخْلعوا بَيْعَة ابنِ الزُّبيرِ ويَعودوا لِبَيْعَة يَزيدَ، فأ"},{"id":301,"era":"c1","t":"وَفاةُ الخَليفةِ الأُمَويِّ يَزيدَ بن مُعاوِيَة .","s":"هو يَزيدُ بن مُعاوِيَة بن أبي سُفيان الأُمَويُّ القُرشيُّ الدِّمشقيُّ، وُلِدَ في 23 رمضان 26 هـ في خِلافَة عُثمان بن عفَّان رضي الله عنه في قَريةِ الماطِرُون، وأُمُّهُ مَيْسونُ بنتُ بَحْدَل الكَلْبِيَّةُ، طَلَّقَها مُعاوِيَةُ فيما بعدُ. عاش فَترةً مِن حياتِه في البادِيَةِ بين أخوالِه، تَوَلَّى الخِلافَة بعدَ وَفاةِ والدِه في سنة 60 للهِجرَةِ، ولم يُبْقِ مِن مُعارِضي تَوْلِيَتِهِ الخِلافَة غيرَ الح"},{"id":302,"era":"c1","t":"احْتِراقُ الكَعبَةِ أثناءَ حِصارِ الأُمَويِّين لابنِ الزُّبيرِ .","s":"لمَّا رفَض ابنُ الزُّبيرِ البَيْعَة لِيَزيدَ بن مُعاوِيَة وكان بمكَّة المُكرَّمَة سَيَّرَ إليه يَزيدُ بن مُعاوِيَة جيشًا بقِيادَةِ مُسلمٍ؛ ولكنَّ مُسلِمًا تُوفِّي في الطَّريقِ إلى مكَّة فاسْتَلَم بعدَه الحُصينُ بن نُميرٍ فحاصَر مكَّة المُكرَّمَة، وكان ابنُ الزُّبيرِ اتَّخَذَ المسجدَ حِصْنًا له ووضَع فيه الخِيامَ لِتَحميهِ وجُنْدَهَ مِن ضَرباتِ المَنْجنيق، واسْتَمرَّ الحِصارُ إلى أن احْتَرقَت الكَع"},{"id":303,"era":"c1","t":"مُعاوِيَةُ بن يَزيدَ يَتَوَلَّى الخِلافَة ثمَّ يَترُكها شُورى للمسلمين  .","s":"بعدَ أن تُوفِّي يَزيدُ وكان قد عَهِدَ بالخِلافَة لابنِه مُعاوِيَة، وكان شَابًّا مَريضًا، وكان ناسِكًا صالِحًا مُتَعبِّدًا لم تَدُمْ خِلافتُه بالنَّاس سِوى اليَسيرِ، ولم يُرِدْ الخِلافَةَ وقد عَلِمَ أنَّه ليس لها بأهلٍ، واعْتَزَل النَّاسَ وقال: إنَّه لم يَجِدْ للنَّاس مَن يَخلُفُه كما خَلَّفَ أبو بكرٍ للنَّاس عُمَرَ بن الخطَّاب، ولا وجَد في النَّاسِ سِتَّةً مِن أهلِ الشُّورى يكون الأمرُ بينهم كما و"},{"id":304,"era":"c1","t":"تَوَلِّي ابنِ الزُّبيرِ الخِلافَة بعدَ مُعاوِيَة بن يَزيدَ  .","s":"لمَّا مات يَزيدُ بن مُعاوِيَة أَقْلَع جَيشُه عن مكَّة، وهم الذين كانوا يُحاصِرون ابنَ الزُّبيرِ وهو عائِذٌ بالبيتِ، فلمَّا رجَع حُصينُ بن نُميرٍ السَّكونيُّ بالجيشِ إلى الشَّام بعدَ أن عرَض الحُصينُ على ابنِ الزُّبيرِ أن يُبايِعَه بالخِلافَة شَرْطَ أن يَأتِيَ معهم للشَّامِ؛ لكنَّ ابنَ الزُّبيرِ رفَض الذِّهابَ إلى الشَّام, كان يَزيدُ قد أَوْصى بالخِلافَة لابنِه مُعاوِيَة؛ لكنَّه لم يكُن راغِبًا فيه"},{"id":305,"era":"c1","t":"إِعادَةُ بِناءِ الكَعبَةِ على قَواعِد إبراهيمَ على يَدِ عبدِ الله بن الزُّبيرِ رضي الله عنه .","s":"لمَّا احْتَرَقت الكَعبةُ حين غَزا أهلُ الشَّامِ عبدَ الله بن الزُّبير أيَّام يَزيدَ تَرَكها ابنُ الزُّبير يُشَنِّع بذلك على أهلِ الشَّام، فلمَّا مات يَزيدُ واسْتَقَرَّ الأمرُ لابنِ الزُّبير شرَع في بِنائِها، فأَمَر بِهَدْمِها حتَّى أُلْحِقَت بالأرضِ، وكانت قد مالت حيطانُها مِن حِجارَةِ المَنْجنيقِ، وجَعَل الحَجَرَ الأسودَ عنده، وكان النَّاسُ يَطوفون مِن وراءِ الأساسِ، وضرَب عليها السُّورَ وأدخل في"},{"id":306,"era":"c1","t":"مَرْوانُ بن الحكمِ يَتَوَلَّى أُمورَ الخِلافَة الأُمويَّة .","s":"لمَّا بُويِعَ لابنِ الزُّبير بالخِلافَة، وقَدِمَ الحُصينُ بن نُميرٍ ومَن معه إلى الشَّام أَخْبَرَ مَرْوانَ بما كان بينه وبين ابنِ الزُّبير، وقال له ولِبَنِي أُمَيَّة: نَراكُم في اخْتِلاطٍ فأقيموا أَميرَكُم قبلَ أن يَدخُلَ عليكم شامَكُم، فتكون فِتنَة عَمْياء صَمَّاء. وكان مِن رَأْيِ مَرْوان أن يَسيرَ إلى ابنِ الزُّبير فيُبايِعهُ بالخِلافَة، فقَدِمَ ابنُ زيادٍ مِن العِراق وبَلغَهُ ما يَريدُ مَرْوانُ"},{"id":307,"era":"c1","t":"وَقعةُ مَرْج راهِط بين مروان بن الحكم والضحاك بن قيس .","s":"لمَّا بايَع النَّاسُ مَرْوانَ سار مِن الجابِيَة إلى مَرْج راهِط قريبا من دمشق وبها الضَّحَّاك بن قيسٍ ومعه ألفُ فارسٍ، وكان قد اسْتَمَدَّ الضَّحَّاكُ النُّعمانَ بن بَشيرٍ وهو على حِمْص فأَمَدَّهُ حَبيبَ بن ذي الكِلاعِ، واسْتَمَدَّ أيضًا زُفَرَ بن الحارثِ وهو على قِنَّسْرين فأَمَدَّهُ بأهلِ قِنَّسْرين، وأَمَدَّهُ ناتِل بأهلِ فِلَسْطين، فاجتمعوا عنده، واجتمع على مَرْوان كَلْبٌ وغَسَّانُ, والسَّكاسِك"},{"id":308,"era":"c1","t":"ضَمُّ مَرْوان بن الحكمِ أرضَ مِصْرَ إلى خلافته .","s":"لمَّا اسْتَقَرَّ الشَّامُ لمَرْوان بن الحكمِ سار إلى مِصْرَ, فقَدِمَها وعليها عبدُ الرَّحمن بن جَحْدَم القُرشيُّ يَدعو إلى ابنِ الزُّبير، فخرَج إلى مَرْوان فيمَن معه، وبعَث مَرْوانُ عَمرَو بن سعيدٍ مِن وَرائِه حتَّى دخَل مِصْرَ، فقِيلَ لابنِ جَحْدَم ذلك، فرجَع وبايَع النَّاسُ مَرْوانَ ورجَع إلى دِمشقَ."},{"id":309,"era":"c1","t":"مَقْتَلُ نافعِ بن الأزرقِ (زَعيمُ طائفة الأزارِقَة) .","s":"هو نافعُ بن الأزرقِ مِن بَنِي حَنيفةَ زَعيمُ الأزارِقَة، المشهور بمُساءَلة ابنِ عبَّاس, وممَّا يُذكَر عن ابتداءِ ظُهورهِ أنَّه اجْتَمع بالخَوارِج الذين يَرون رَأيَه وطلَب إليهم أن يَنضمُّوا إلى ابنِ الزُّبيرِ لمُقاتَلةِ جُيوشِ أهلِ الشَّام الذين حاصروا مكَّة، قائلًا لهم مِن خُطبةٍ له: وقد جَرَّدَ فيكم السُّيوفَ أهلُ الظُّلْمِ، وأوَّلوا العَداءَ والغَشْمَ، وهذا مَن ثار بمكَّة، فاخْرُجوا بِنَا نَأْت"},{"id":310,"era":"c1","t":"عبدُ المَلِك بن مَرْوان يَتَوَلَّى الخِلافَة الأُمويَّة .","s":"لمَّا غلَب مَرْوانُ بن الحكمِ على الشَّام وما حَولَها عَهِدَ بالخِلافَة لابْنَيْهِ عبدِ المَلِك ثمَّ مِن بعدِه عبدِ العزيزِ، فاسْتلَم عبدُ الملك زِمامَ الأُمورِ التي كانت بِيَدِ والدِه ولكن لم تَتِمَّ له الأمورُ كُلُّها؛ لأنَّ بعضَ المناطقِ ما زالت تَدينُ بالخِلافَة لابنِ الزُّبير."},{"id":311,"era":"c1","t":"وَفاةُ عبدِ الله بن عَمرِو بن العاصِ رضِي الله عنه .","s":"هو أحدُ المُكْثِرين في الرِّاويةِ عن النَّبِيِّ صلَّى الله عليه وسلَّم، أَسلَم قبلَ أبيهِ، وكان فاضِلًا عالِمًا، قَرَأَ القُرآنَ والكُتُبَ المُتَقدِّمة، واسْتأذَنَ النَّبِيَّ صلَّى الله عليه وسلَّم في أن يَكتُبَ عنه، فأَذِنَ له، شَهِدَ صِفِّينَ مع مُعاوِيَة طاعةً لوالِدِه، إذ كان النَّبِيُّ صلَّى الله عليه وسلَّم قال له: (أَطِعْ أباكَ). اخْتُلِف كثيرًا في زمنِ وَفاتِه ومَكانِ وَفاتِه، وذلك للاختلا"},{"id":312,"era":"c1","t":"حرَكةُ المُختارِ الثَّقَفيِّ .","s":"هو المُختارُ بن أبي عُبيدٍ الثَّقفيُّ، وكان في الكوفَة، وكان يَدعو إلى إمامةِ المَهْدِيِّ محمَّدِ بن عَلِيٍّ المعروف بابنِ الحَنَفِيَّةِ، فسارت وَراءَهُ جَماعةٌ منها جَماعةٌ كانت مع سُليمان بن صُرَدٍ رضي الله عنه، الذين لَقَّبُوا أَنفُسَهم بالتَّوَّابِينَ، لِيُكَفِّرُوا عن خُذْلانِهم للحُسينِ بن عَلِيٍّ رضي الله عنه في كَرْبَلاء, ولكنَّ ابنَ الحَنفيَّة لم يكُن يَعلَم بأَمرِهِم فضلًا عن أن يَرْضى ب"},{"id":313,"era":"c1","t":"عبدُ الملك بن مَرْوان يبدأ ببِناءِ قُبَّةِ الصَّخرَةِ في بيتِ المَقْدِس .","s":"بدَأ عبدُ الملك بن مَرْوان في بِناءِ مَسجِد قُبَّةِ الصَّخرَةِ في بيتِ المَقْدِس. وقِيلَ: إنَّ عبدَ الملك بن مَرْوان حين قَرَّرَ بِناءَ قُبَّةٍ عالِيَةٍ تُغَطِّي الصَّخرَةَ رصَد لِبِنائِها خَراجَ مِصْرَ لِسَبْعِ سِنين، وحين أُنْفِقَت هذه الأموالُ على البِناءِ بَقِيَ منها مائةُ ألفِ دِينارٍ، فأَمَر عبدُ الملك بن مَرْوان أن يُصْنَعَ بها صَفائِح ذَهَبيَّة تُكْسَى بها القُبَّةُ مِن الخارجِ."},{"id":314,"era":"c1","t":"مَقْتَلُ المُختارِ الثَّقفيِّ .","s":"بدَأ المُختارُ بن أبي عُبيدٍ الثَّقفيُّ بالدَّعوَةِ لابنِ الحَنَفيَّة ظاهرًا؛ ولكنَّه تَبَيَّنَ أنَّه يدعو لِنَفسِه، فقد كَوَّنَ حوله جيشًا قاتَل فيه عُبيدَ الله بن زيادٍ، وكان المُختارُ يُصانِع ابنَ الزُّبير حينًا لِيَتَقَوَّى به على جُيوشِ عبدِ الملك بن مَرْوان، وحصلت مَعركةٌ بين جَيشِه وجَيشِ الشَّام عند نَهْرِ الحازر، قُتِلَ فيها ابنُ زيادٍ، والحُصينُ بن نُميرٍ، وشُرَحْبيل بن زيادٍ، ثمَّ حصل ا"},{"id":315,"era":"c1","t":"وَفاةُ عبدِ الله بن عبَّاس رضِي الله عنهما .","s":"هو حَبْرُ الأُمَّةِ، وهو أحدُ المُكْثِرين مِن الرِّوايَةِ عن النَّبِيِّ صلَّى الله عليه وسلَّم، شَهِدَ مع عَلِيٍّ الجَملَ وصِفِّينَ، وكان والِيًا له على الكوفَة، كُفَّ بَصَرُهُ في آخِرِ عُمُرهِ، وكان في مكَّة ثمَّ انْتَقل إلى الطَّائِف، وتُوفِّي فيها وهو ابنُ واحدٍ وسبعين سنة، ودُفِنَ فيها."},{"id":316,"era":"c1","t":"عِصْيانُ الجَراجِمَة بالشَّام .","s":"لمَّا امْتَنع عَمرُو بن سعيدِ بن العاصِ على عبدِ الملك خرَج أيضًا قائدٌ مِن قُوَّادِ الضَّواحي في جبلِ اللُّكَّامِ وتَبِعَهُ خَلْقٌ كثيرٌ مِن الجَراجِمَة (نسبة لقبيلة جرجم)، والأَنباطِ (مجموعة من العرب ينتمون إلى نبط بن ‘سماعيل)، وآباقِ عَبيدِ المسلمين، وغَيرِهم، ثمَّ سار إلى لُبنان، فلمَّا فرَغ عبدُ الملك مِن عَمرِو بن سعيدِ أَرسَل إلى هذا الخارِج فبَذَل له كُلَّ جُمُعةٍ ألفَ دِينارٍ، فرَكَن إلى "},{"id":317,"era":"c1","t":"وَقعةُ ممش قريبًا مِن القَيْروان وانْتِصارُ المسلمين .","s":"عَيَّنَ عبدُ الملك بن مَرْوان زُهيرَ بن قيسٍ أَميرًا على أفريقيا، وأَمَدَّهُ بالمالِ والرِّجالِ لِيَتَوَجَّهَ بجيشٍ إلى القَيْروان لاسْتِردادِها، حيث كانت مع الرُّومِ فاسْتَولوا عليها مع كُسَيلةَ البَرْبَريِّ، والْتَقى الطَّرَفان في مَوقِع ممش قُرْبَ القَيْروان، وحصل القِتالُ وانْتَصر زُهيرٌ وقَتَلَ كُسيلَةَ ثمَّ عاد إلى بَرْقَة، فكانت الرُّومُ قد أغارَت عليه بِحَمْلَةٍ بَحْريَّةٍ فقاتَلهُم وكان ف"},{"id":318,"era":"c1","t":"انْقِلابُ عَمرِو بن سعيدٍ على عبدِ الملك بن مَرْوان\n  .","s":"أقام عبدُ الملك بن مَرْوان بدِمشقَ بعدَ رُجوعِه مِن قِنَّسْرين ما شاء الله أن يُقيمَ، ثمَّ سار يُريدُ قَرْقِيسِيا وبها زُفَرُ بن الحارثِ الكِلابيُّ، وكان عَمرُو بن سعيدٍ مع عبدِ الملك، فلمَّا بلَغ بُطْنانَ حَبيبٍ رجَع عَمرٌو ليلًا ومعه حُميدُ بن حُرَيثٍ الكَلبيُّ، وزُهيرُ بن الأَبْرَدِ الكَلبيُّ، فأَتى دِمشقَ وعليها عبدُ الرَّحمن بن أُمِّ الحكمِ الثَّقفيُّ قد اسْتَخلَفَهُ عبدُ الملكِ، فلمَّا بَلغه"},{"id":319,"era":"c1","t":"مَقتَلُ مُصعَبِ بن الزُّبير .","s":"لمَّا تَمَكَّنَ عبدُ الملك مِن الشَّام أراد أن يَضُمَّ لها العِراقَ، وقد قِيلَ: إن أَهلَها كاتَبوا عبدَ الملك لِيَسيرَ إليهم، وكانت العِراقُ مع ابنِ الزُّبير وواليها مُصعَبُ أَخوهُ، فسار إليه بِنَفسِه فلمَّا عَلِمَ مُصعبٌ بذلك سار إليه ومعه إبراهيمُ بن الأَشْتَرِ، وكان على المَوصِل والجزيرةِ، فلمَّا حضَر عنده جَعلَه على مُقدِّمَتِه وسار حتَّى نزل باجُمَيرَى، وهي قريبٌ مِن أَوانا، وهي مِن مَسْكِن، "},{"id":320,"era":"c1","t":"وَقعَةٌ عَظيمةٌ بين المُهَلَّب بن أبي صفرة والخَوارِج .","s":"كان المُهَلَّب يُحارِب الأزارِقَة، فجَعلَهُ عبدُ المَلِك بن مَرْوان على خَراجِ الأهوازِ ومَعونَتِها، وسَيَّرَ أخاهُ عبدَ العزيز بن عبدِ الله إلى قَتْلِ الخَوارِج، وسَيَّرَ معه مُقاتِلَ بن مِسْمَع، فخَرَجا يَطلُبان الأزارِقَة، فأتت الخَوارِج مِن ناحِيَة كِرْمان إلى دارِ أبجرد، فأَرسَل قَطَرِيُّ بن الفُجاءَةِ المازنيُّ مع صالحِ بن مُخارِق تسعَمائة فارِسٍ، فأقبلَ يَسيرُ بهم حتَّى اسْتَقْبَل عبدَ العز"},{"id":321,"era":"c1","t":"عبدُ الملك بن مَرْوان يُسَيطِر على العِراق .","s":"تَمَّ ذلك لِعبدِ الملك بن مَرْوان بعدَ أن قَتَلَ مُصعَبَ بن الزُّبير ومَن معه، فانْتَهى بذلك حُكمُ عبدِ الله بن الزُّبير على العِراق، وانْضَمَّت لِعبدِ الملك ووَلَّاها خالدَ بن عبدِ الله القَسْرِيَّ."},{"id":322,"era":"c1","t":"مَقْتَلُ ابنِ الزُّبير رضي الله عنه بعد أن حاصره الحجاج بن يوسف .","s":"سَيَّرَ عبدُ الملك بن مَرْوان الحَجَّاج بن يوسُف الثَّقفيَّ إلى عبدِ الله بن الزُّبير رضي الله عنه، وبعَث معه له أمانًا إنْ هو أطاعَ، فبَقِيَ الحَجَّاج مُدَّةً في الطَّائفِ يَبعَثُ البُعوثَ تُقاتِل ابنَ الزُّبير وتَظْفَرُ عليه. فكتَب الحَجَّاجُ إلى عبدِ الملك يُخبِرُه: بأنَّ ابنَ الزُّبير قد كَلَّ وتَفَرَّق عنه أَصحابُه, ويَسْتَأذِنُه بمُحاصَرةِ الحَرَمِ ثمَّ دُخولِ مكَّة، فأَمَدَّهُ عبدُ الملك بط"},{"id":323,"era":"c1","t":"الانْتِهاءُ مِن بِناءِ مَسجِد قُبَّةِ الصَّخرَةِ .","s":"في هذه السَّنةِ انْتُهِيَ مِن بِناءِ مَسجِد قُبَّةِ الصَّخرَةِ في بيتِ المَقْدِس والذي كان عبدُ الملك قد أمر به في سَنةِ 66 هـ."},{"id":324,"era":"c1","t":"وَفاةُ أسماءَ بنتِ أبي بكرٍ الصِّدِّيق رضِي الله عنهما .","s":"هي ذاتُ النِّطاقَيْنِ، وهي زَوجةُ الزُّبير، ووالدةُ عبدِ الله بن الزُّبير، وكانت قد شَهِدَت اليَرْموك مع زَوجِها وابْنِها، بَقِيَت في مكَّة بعدَ أن طَلَّقَها الزُّبيرُ في عَهْدِ عُثمان بن عفَّان، وكانت قد عَمِيَت رضي الله عنها وبَلَغت المائةَ سَنةٍ مِن عُمُرِها، وخَبرُها مع الحَجَّاج مشهور بشأنِ ابْنِها عبدِ الله، وقد تُوفِّيت بعدَ مَقْتَلِ ابْنِها بِشَهرين، وكانت مِن آخرِ المُهاجِرات موتًا، فرضِي"},{"id":325,"era":"c1","t":"ثَورةُ الخَوارِج في البَحْرَين .","s":"في عَهدِ عبدِ الملك بن مَرْوان ثار الخَوارِجُ في البَحرينِ بزَعامَةِ عبدِ الله بن قيسٍ المعروف بأبي فُدَيْكِ, وأَخرَجَهم منها المُغيرةُ بن المُهَلَّب بن أبي صُفْرَة بعدَ مَعركةٍ قُتِلَ فيها أبو فُدَيكٍ."},{"id":326,"era":"c1","t":"وَفاةُ عبدِ الله بن الزُّبير .","s":"هو أميرُ المؤمنين عبدُ اللهِ بنُ الزُّبَير بنِ العوَّام بن خُوَيلد بن أسد بن عبد العُزَّى بن قُصَي بن كلِاب بن مُرَّة: أبو بكر، وأبو خُبَيب القرشيُّ الأَسديُّ المكيُّ، ثم المدنيُّ, أحد الأعلام، كان عبدُ الله أول مولودٍ للمهاجرين بالمدينةِ, وُلِدَ سنة اثنتين، وقيل: السنة الأولى من  الهجرة, ولَمَّا بلغ سبع سنين جاء ليبايِعَ النبيَّ صلَّى الله عليه وسلَّم، فتبسَّم النبيُّ صلى الله عليه وسلم حين رآه م"},{"id":327,"era":"c1","t":"الحَجَّاجُ بن يوسُف يُعيدُ بِناءَ الكَعبةِ إلى ما كانت عليه في عَهدِ قُريش .","s":"كان عبدُ الله بن الزُّبير أعاد بِناءَ الكَعبةِ بعدَ أن تَخَرَّبَت في الحِصارِ الأوَّل الذي قادهُ الحُصينُ بن نُميرٍ مِن قِبَلِ يَزيدَ بن مُعاوِيَة على قَواعِدها القديمة، وجعَل لها بَابَيْنِ كما وصَف النَّبِيُّ صلَّى الله عليه وسلَّم، ثمَّ عادَت وتَضَرَّرت الكَعبةُ في الحِصارِ الثَّاني الذي قادهُ الحَجَّاجُ بن يوسُف الذي اسْتَعمل كذلك المَنْجنيقَ، ممَّا أَدَّى إلى هَدْمِ أَجزاءٍ مِن الكَعبةِ، وبعدَ"},{"id":328,"era":"c1","t":"وَفاةُ عبدِ الله بن عُمَر رضِي الله عنهما .","s":"هو أبو عبدِ الرَّحمن عبدُ الله بن عُمَر بن الخَطَّاب العَدَويُّ القُرشيُّ المَكِّيُّ ثمَّ المَدنيُّ، صَحابيٌّ جَليلٌ، وابنُ ثاني خُلفاءِ المُسلمين عُمَر بن الخَطَّاب، وعالِمٌ مِن عُلماءِ الصَّحابةِ، لُقِّبَ بِشَيخِ الصَّحابةِ رضي الله عنه، أَسْلَمَ قَديمًا مع أَبيهِ ولم يَبلُغ الحُلُمَ، وهاجَرا وعُمُرُهُ عشرُ سِنين، وقد اسْتُصْغِر يومَ أُحُدٍ، فلمَّا كان يومُ الخَندقِ أَجازَهُ وهو ابنُ خمسَ عشرةَ "},{"id":329,"era":"c1","t":"وَفاةُ جابرِ بن عبدِ الله رضِي الله عنه .","s":"هو جابرُ بن عبدِ الله بن حَرامٍ الأنصاريُّ، أَحدُ المُكْثِرين في الرِّوايةِ عن النَّبِيِّ صلَّى الله عليه وسلَّم، شَهِدَ العَقَبَة الثَّانيَة مع أَبيهِ، فكان آخرَ مَن تُوفِّي في المدينةِ مِن أَصحابِ العَقَبَة، عَمِيَ في آخرِ عُمُرهِ، لم يَسْتَطِع أن يَشْهَدَ بدرًا ولا أُحُدًا، فلمَّا اسْتُشْهِد أبوهُ في أُحُدٍ لم يَتَخلَّفْ بعدها عن مَشهَدٍ بعدَ ذلك، تُوفِّي في المدينةِ سَنَة أربعٍ وسبعين، وقِيلَ:"},{"id":330,"era":"c1","t":"فَتْحُ حَسَّان بن النُّعمان الغَسَّانيِّ قَرْطاجَنَّة .","s":"لمَّا قُتِلَ ابنُ الزُّبير واجتَمَع المسلمون على عبدِ الملك بن مَرْوان جَهَّزَ جيشًا كبيرًا واستَعْمل عليهم وعلى أفريقيا حسَّانَ بن النُّعمان الغَسَّانيَّ وسَيَّرَهُم إليها، فلم يَدخُلْ أفريقيا قَطُّ جَيشٌ مِثلُه، فلمَّا وَرَدَ القَيْروان تَجَهَّزَ منها وسار إلى قَرْطاجَنَّة، وكان صاحبُها أعظمَ مُلوكِ أفريقيا، ولم يكُن المسلمون قَطُّ حارَبوها، فلمَّا وصَل إليها رأى بها مِن الرُّومِ والبَرْبَر مالا"},{"id":331,"era":"c1","t":"الحَجَّاجُ بن يوسُف يَحكُم العِراقَ  .","s":"حَكَم الحَجَّاجُ بن يوسُف بعدَ أن قَضى على ابنِ الزُّبيرِ، حَكَم الحِجازَ كُلَّها ثمَّ وَلَّاهُ عبدُ الملك أَمْرَ العِراق بدلًا مِن خالدِ بن عبدِ الله القَسْريِّ، فصارت العِراق للحَجَّاج، وخُطْبَتُهُ فيها مشهورة، فأَمْسَك زِمامَ الأُمورِ فيها بِشِدَّةٍ فدانَتْ له وخَضَعت."},{"id":332,"era":"c1","t":"إجْلاء الخَوارِج عن رامَهُرْمُز وقَتْل عبدِ الرَّحمن بن مخنف\n  .","s":"بعَث الحَجَّاجُ كِتابًا إلى المُهَلَّب وعبدِ الرَّحمن بن مِخْنَف يأمرُهما بِمُناهَضة الخَوارِج، فزَحَفوا إليهم وقاتلوهم شيئًا مِن قِتالٍ، فانْهَزمت الخَوارِج كأنَّهم على حامِيَة، ولم يكُن منهم قِتالٌ، وساروا حتَّى نَزلوا كازَرُون، وسار المُهَلَّبُ وابنُ مِخْنَف حتَّى نزلوا بهم، وخَنْدَقَ المُهَلَّبُ على نَفسِه، وقال لابن مِخْنَف: إن رأيتَ أن تُخَنْدِقَ عليك فافْعَل. فقال أصحابُه: نحن خَنْدَقْنا سُ"},{"id":333,"era":"c1","t":"ضَرْبُ العُمْلَة الإسلامِيَّة .","s":"وكان سَبَب ضَرْبها أنَّ عبدَ الملك بن مَرْوان كتَب في صُدورِ الكُتُبِ إلى الرُّوم: \"قل هو الله أحد\" وذَكَر النَّبِيَّ صلَّى الله عليه وسلَّم، مع التَّاريخ، فكَتَب إليه مَلِكُ الرُّوم: إنَّكم قد أَحْدَثْتُم كذا وكذا، فاتركوه وإلَّا أتاكُم في دَنانيرنا مِن ذِكْرِنا نَبِيَّكم ما تَكرهُون. فعَظُم ذلك عليه. فأحضر خالدَ بن يَزيدَ بن مُعاوِيَة فاسْتَشارهُ فيه، فقال: حَرِّمْ دَنانيرَهُم واضْرِب للنَّاس سِ"},{"id":334,"era":"c1","t":"اسْتِعادَة البَرْبَر قَرْطاجَنَّة مِن المسلمين .","s":"كانت هناك في جِبال أُوراس كاهِنَة مُطاعَة مِن قِبَل البَرْبَر فانْطَلق إليها حسَّانُ بن النُّعمان لِقِتالِها، وحَصَل قِتالٌ شديدٌ هُزِمَ فيه المسلمون، ووَصَل الخبرُ لعبدِ الملك فأَمَر بالانتظار حتَّى يأتيهم الأمرُ؛ ولكنَّ الرُّوم لمَّا عَلِموا بالأمرِ ساروا بأُسْطُولِهم إلى قَرْطاجَنَّة بإمْرَةِ البَطْريق يُوحَنَّا فتَمكَّن مِن دُخولِها وقسا على المسلمين ممَّا اضْطَرَّهم للهُروب للقُرى المُجاورة."},{"id":335,"era":"c1","t":"ثَورة الخَوارِج في طَبَرِستان بقِيادَة قَطَريِّ بن الفُجاءَة .","s":"ثار الخَوارِجُ في طَبَرِستان بِزَعامَة قَطَريِّ بن الفُجاءَة فأَرسَل الحَجَّاجُ جَيْشًا بقِيادَة سُفيان بن الأبردِ فقاتَلهُ, فانْفَضَّ عنه أصحابُه وسَقَطَ في شِعْبٍ مِن الشِّعابِ فاغْتالهُ عِلْجٌ مِن أهلِ طَبَرِستان وأَرسَل رأسَه إلى الحَجَّاج."},{"id":336,"era":"c1","t":"الأُمَوِيُّون يُخْمِدون فِتنَة شَبيب بن يَزيد الخارجي بالعِراق .","s":"كَثُرَت فِتَنُ الخَوارِج والحُروب معهم وازداد أمرُهم قُوَّةً، فقد بايعوا لِشَبيب بن يَزيد بعدَ صالِح بن مُسَرِّحٍ، وكان شَبيب قد هَزَمَ جيشَ الحَجَّاج ثمَّ هَرَب شَبيب إلى المدائن وقَوِيَ أمرُه حتَّى سار إليه الحَجَّاجُ بِنَفسِه كما سَيَّرَ عبدُ الملك جيشًا مِن الشَّام إليه والتَقى الطَّرفان في مَقتلةٍ عظيمة قُتِلَ فيها الكثيرُ مِن أصحابِ شَبيب، ممَّا اضْطَرَّهُ للهُروب إلى ناحِيَة جِسْرٍ على نهرِ"},{"id":337,"era":"c1","t":"فَتْح المسلمين إرْقِيلِيَّة في بلاد الروم .","s":"كانت هذه الغَزوة مِن أَعظَم الغَنائم للمسلمين ببِلاد الرُّوم حيث افْتَتحوا إرْقِيليَّة، وكان الجيش أثناء رُجوعِهم أصابَهم مَطَرٌ عظيمٌ وثَلْجٌ وبَرْدٌ، فأُصِيبَ بِسَببِه ناسٌ كثيرٌ."},{"id":338,"era":"c1","t":"اسْتِعادَة البِيزنطيِّين قَرْطاجَنَّة (جنوب شرق أسبانيا) .","s":"كان لِسُقوط قَرْطاجَنَّة بِيَدِ المسلمين أثرٌ بالغٌ على البِيزنطيِّين، ووجدوا في خُروج حسَّان مِن أفريقيا بعدَ هَزيمتِه على يَدِ الكاهنة مَلِكَة البَرْبَر والفَوضى التي عَمَّت البلادَ بِسَبب سِياسَة الكاهنة التَّخريبيَّة مَجالًا لِإعادَة نُفوذِهم في الشَّمال الإفريقي، فجَهَّز الإمبراطور لِيونتوس الذي خَلَفَ جستنيان الثاني حَملةً كبيرةً بِقيادة البَطْريق يُوحَنَّا إلى أفريقيا وأَعَدَّ أُسطولًا كبير"},{"id":339,"era":"c1","t":"الحَجَّاج يرسل جيشا إلى مَلِك التُّرْك لِتَمَرُّدِه بِعَدم دَفْع الجِزْية .","s":"أَرْسَل الحَجَّاجُ إلى رتبيل مَلِك التُّرْك جيشًا بِقِيادة والي سجستان عُبيد الله بن أبي بَكْرة، وأَمَره أن يَتوغَّل في بلاد رتبيل وأن يَدُكَّ حُصونَهم وقِلاعَهم، تأديبًا لترتبيل لتَمَرُّدِه بِعَدم دَفْع الجِزْية أحيانًا، أو اسْتِغلال اضْطِرابات المسلمين، فتَمَكَّن عُبيد الله مِن هَزيمة رتبيل واجْتِياح بِلادِه وغَنِمَ غنائمَ كثيرة؛ ولكنَّ رتبيل أَخَذ في التَّقَهْقُر فأَطْمَع المسلمين في اللِّحاق ب"},{"id":340,"era":"c1","t":"نِهايَة الوُجود البِيزنطي في شَمال أفريقيا .","s":"بعدَ أن هُزِمَ المسلمون أمامَ البَرْبَر وتَسَلَّط البِيزنطيُّون على قَرْطاجَنَّة بَقِيَ حَسَّان بن النُّعمان في قُصور حَسَّان حتَّى أتاهُ المَدَدُ مِن عبدِ الملك وأَمَرَهُ بالتَّحَرُّك، فتَحَرَّك حَسَّان إلى الكاهِنَة ومَن معها فتَقابَلوا في قابِس وتَغَلَّب عليها حَسَّان وتَمَّ سَيْرُه إلى باقي أنحاءِ أفريقيا."},{"id":341,"era":"c1","t":"بِناء مَدينَة تُونُس الإسلامِيَّة في شَمالِ أفريقيا .","s":"قام الأميرُ حَسَّان بن النُّعمان بِبِناء مَدينَة تُونُس وبَنَى بها الجامِعَ المعروف بجامِع الزَّيْتُونة، كما أنشأ دارًا لِصِناعَة الأساطيل، فكانت أوَّل قاعِدَة حَربِيَّة في المَغرِب، كما قام بِتَدوِين الدَّواوِين، وضَرب الدَّنانِير والدَّراهِم العَربِيَّة."},{"id":342,"era":"c1","t":"وَفاة مُحمَّد بن الحَنَفِيَّة .","s":"هو محمَّد بن عَلِيٍّ بن أبي طالِب، أُمُّهُ خَوْلَةُ بِنتُ جَعفَر مِن بني حَنِيفَة مِن سَبْيِ اليَمامَة، نُسِبَ إليها تَمييزًا له عن أَخَوَيْهِ الحسن والحُسين وَلَدَي فاطِمَة رضي الله عنهم أجمعين، كانت الشِّيعَة في زَمانِه تَتَغالى فيه، وتَدَّعِي إمامَتَه، وأوَّل مَن دَعا إلى ذلك المُخْتار الثَّقَفِيُّ، ولَقَّبُوه بالمَهْدِيِّ، ويَزعُمون أنَّه لم يَمُت، كان أحدَ الأبطال الشُّجْعان، وكان كثيرَ العِل"},{"id":343,"era":"c1","t":"بِدايَة فِتنَة عبدِ الرَّحمن بن الأشعث  .","s":"لمَّا بُعِثَ عبدُ الرَّحمن بن محمَّد بن الأشعث على الجيشِ إلى بِلادِ رتبيل فدَخَلها وأَخَذ منها الغَنائِمَ والحُصونَ كَتَب إلى الحَجَّاج يُعَرِّفُه ذلك، وأنَّ رَأْيَه أن يَتْرُكوا التَّوَغُّلَ في بِلادِ رتبيل حتَّى يَعرِفوا طَريقَها ويَجْبُوا خَراجَها، فكَتَب إليه الحَجَّاجُ أن يَتَوَغَّلَ ويَسْتَمِرَّ في الحَربِ؛ ولكنَّ ذلك لم يَرُق لِعبدِ الرَّحمن، فحَرَّضَ النَّاسَ وبَيَّنَ لهم خُطورَة التَّوَغ"},{"id":344,"era":"c1","t":"وَقْعَة الزَّاوِيَة بين أهلِ الشَّامِ وابنِ الأشعث .","s":"لمَّا سَمِعَ الحَجَّاجُ بِتَمَرُّدِ ابنِ الأشعث جَهَّزَ جُيوشًا وطَلَب مِن عبدِ الملك إمْدادَه فكان ذلك، ثمَّ الْتَقى الطَّرَفان في تُسْتَر واقْتَتَلوا قِتالًا شَديدًا فهَزَمَهُم ابنُ الأشعث ودَخَل البَصْرَةَ فبايَعَهُ أهلُها، وكان ذلك في ذي الحجَّة، ثمَّ في أواخر مُحَرَّم حصَل قِتالٌ شديدٌ آخر انْهزَم فيه أيضًا أصحابُ الحَجَّاج، فحمَل سُفيانُ بن الأبرد الكَلْبِيُّ على المَيْمَنَةِ التي لِعبدِ الر"},{"id":345,"era":"c1","t":"وَفاة المُهَلَّب بن أبي صُفْرَة .","s":"هو المُهَلَّب بن أبي صُفْرَة ظالم، أبو سَعيد الأَزْدِيُّ، الأميرُ البَطَل، قائدُ الكَتائِب أحدُ أَشْرافِ أهلِ البَصْرَةِ، ووُجَهائِهِم ودُهاتِهِم وأَجْوادِهِم وكُرَمائِهِم، وُلِدَ عامَ الفَتْح، نَزَل المُهَلَّبُ البَصْرَة وغَزا في أيَّام مُعاوِيَة أرضَ الهِنْد سنةَ أربع وأربعين، ووَلِيَ الجزيرةَ لابنِ الزُّبير سنةَ ثمانٍ وسِتِّين، ثمَّ وَلِيَ حَربَ الخَوارِج أوَّلَ دَولةِ الحَجَّاج، وقَتَل منهم في"},{"id":346,"era":"c1","t":"وَقعَة دَيْر الجَماجِم ونِهايَة فِتنَة ابنِ الأشعث .","s":"اسْتُهِلَّ هذا العام والنَّاسُ مُتَواقِفون لِقتال الحَجَّاج وأصحابه بِدَيْرِ قُرَّة، وابنُ الأشعث وأَصحابُه بِدَيْرِ الجَماجِم، والمُبارَزة في كُلِّ يَومٍ بينهم واقِعَة، وفي غالبِ الأيَّامِ تكون النُّصْرَة لأهلِ العِراق على أهلِ الشَّام، إذا حصَل له ظَفَرٌ في يوم مِن الأيَّام يَتقدَّم بجَيشِه إلى نَحْرِ عَدُوِّهِ، وكان له خِبرَةٌ بالحربِ، وما زال ذلك دَأْبُه ودَأْبُهم حتَّى أَمَر بالحَمْلَةِ على ك"},{"id":347,"era":"c1","t":"الحَجَّاجُ بن يوسُف يبدأ ببِناء مَدينة واسِط في العراق .","s":"قام الحَجَّاجُ بن يوسُف الثَّقفيُّ بعدَ أن اسْتَتَبَّ له العِراق ببِناء مَدينة واسِط، وسُمِّيَت بذلك لتَوَسُّطِها بين البَصْرَة والكوفَة، وجَعَلَها مَعْقَلَهُ وقاعِدَةَ حُكْمِه، وأَسْكَنَها الجُنْدَ الشَّامِيَّ العَربيَّ وأَتْراكَ ما بين النَّهْرَيْنِ الذين قَدِموا أَسْرَى حَرْبٍ أو مَنْفِيِّين أو مِن تِلْقاءِ أَنْفُسِهم فأَضْحَت قاعِدَة للعِراق."},{"id":348,"era":"c1","t":"اسْتِيلاء الأُمَويِّين على جُزُرِ دَهْلَك وتَطْهِيرها مِن القَراصِنَة (جزر إرتريا) .","s":"جُزُر أرخبيل دَهْلَك: مُدُن حَبَشِيَّة ساحِلِيَّة في البَحرِ الأحمر، وبها أكثر مِن مائتي جَزيرَة، وهي عبارة عن جُزُر صَحراوِيَّة بتُرْبَتِها الصَّلْبَة وقِلَّةِ مِياهِها العَذْبَة, لَعِبَت هذه الجُزُر دَوْرًا هامًّا كنُقْطَةِ تَجَمُّعٍ وانْطِلاقٍ للهِجْرات العَربِيَّة القَديمَة المُتَّجِهَة صَوْبَ ساحِل أفريقيا, وعن طَريقِها كان يَتِمُّ نَقْل التِّجارَة واسْتِقبالها, ثمَّ أصبحت جُزُر دَهْلَك مَرْك"},{"id":349,"era":"c1","t":"فَتْحُ يَزيد بن المُهَلَّب قَلْعَة نَيْزَك بِباذَغِيس .","s":"فَتَحَ يَزيدُ بن المُهَلَّب قَلْعَةَ نَيْزَك، وكان يَزيد قد وَضَع على نَيْزَك العُيونَ، فلمَّا بَلَغَهُ خُروجُ نَيْزَك عنها سار إليها فحاصَرَها فمَلَكَها وما فيها مِن الأموال والذَّخائِر، وكانت مِن أَحْصَن القِلاعِ في زَمانِها، وكان نَيْزَك إذا رآها سَجَدَ لها تَعْظِيمًا لها، كَتَبَ يَزيدُ بن المُهَلَّب إلى الحَجَّاجِ بالفَتْحِ: أَنَّا لَقِينَا العَدُوَّ فمَنَحَنا اللهُ أَكْتافَهُم، فقَتَلْنَا طائ"},{"id":350,"era":"c1","t":"فَتْحُ عبدِ الله بن عبدِ الملك المَصِّيصَة في بلاد الروم .","s":"غَزا عبدُ الله بن عبدِ الملك الرُّومَ ففَتَح المَصِّيصَة وبَنَى حِصْنَها، ووَضَع بها ثلاثمائة مُقاتِل مِن ذَوِي البَأْسِ، ولم يكُن المسلمون سَكَنوها قبلَ ذلك، وبَنَى مَسجِدَها."},{"id":351,"era":"c1","t":"غَزْوُ محمَّدِ بن مَرْوان أرمينية .","s":"قام محمَّدُ بن مَرْوان وهو أَميرُ الجَزيرَة بِغَزْوِ أرمينية وحَرْقِ كَنَائِسِهِم، وتُسَمَّى هذه السَّنَة بِسَنَةِ الحَرْق."},{"id":352,"era":"c1","t":"وَفاةُ عِمْران بن حِطَّان الخارجيِّ .","s":"هو عِمْرانُ بن حِطَّان بن ظَبْيان، السَّدُوسيُّ البَصريُّ، نَشَأ في البَصْرَة، حَدَّثَ عن عائِشَة، وأبي موسى الأشعريِّ، وابن عَبَّاس، ورَوَى عنه ابنُ سِيرين، وقَتادَة، ويحيى بن أبي كَثير. كان مِن أَهلِ السُّنَّةِ والجَماعَة، فتَزَوَّج امْرأَةً مِن الخَوارِج حَسَنَةً جَميلةً جِدًّا فأَحَبَّها، وكان هو دَمِيمُ الشَّكْل، فأَرادَ أن يَرُدَّها إلى السُّنَّةِ فأَبَتْ، فَارْتَدَّ معها إلى مَذْهَبِها. وقد"},{"id":353,"era":"c1","t":"إِنْشاء حَسَّان بن النُّعْمان جامِع الزَّيْتونَة بالقَيْرَوان .","s":"بعدَ فَتْحِ تُونُس اقْتَضَتْ الحاجَةُ لِبِناءِ مَسجِد للصَّلاة ونَشْر الدِّين الإسلاميِّ بين أهالي تُونُس، بَنَي أوَّلَ مَسجِد فيها الشَّيْخُ الأمينُ حَسَّان بن النُّعْمان الغَسَّانيُّ فاتِحُ تُونُس وقَرْطاجَنَّة، وسُمِّيَ بـ (جامِع الزَّيْتونَة) لأنَّ مَوْقِعَه كانت به شَجَرَة زَيْتون عندَ صَوْمَعَة كان يَتَعَبَّد فيها راهِبٌ نَصْرانيٌّ، وقِيلَ: إنَّ السَّبَب في تَسْمِيَتِه بهذا الاسم هو لِكَثْرَ"},{"id":354,"era":"c1","t":"وَفاةُ عبدِ الرَّحمن بن الأشعث .","s":"هو عبدُ الرَّحمن بن محمَّد بن الأشعث بن قَيْس الكِنْدِيُّ، أَميرُ سِجِسْتان كان قائدًا أُمَوِيًّا مِن أهلِ الكوفَة وأَشرافِها، بَدَأ عبدُ الرَّحمن كَأَيِّ قائِدٍ لِبَنِي أُمَيَّةَ، وضَمَّ عددًا كبيرًا مِن البُلدان لِصالِح الدَّولَةِ الأُمويَّة، ولم تكُن أسباب خُروجِه دِينيَّة على الإطلاق. وُلِدَ عبدُ الرَّحمن في الكوفَة في بَيتٍ مِن أَشرافِها، فأَبُوه محمَّدُ بن الأشعث، أَحَدُ وُجوهِ كِنْدَة. كانت"},{"id":355,"era":"c1","t":"فَتْحُ المُفَضَّل بن المُهَلَّب باذغيس .","s":"ثمَّ لمَّا وَلِيَ المُفَضَّل بن المُهَلَّب خُراسان غَزَا باذغيس ففَتَحَها وأصاب مَغنمًا فقَسَّمَه، فأصاب كُلُّ رَجُلٍ ثماني مائة. ثمَّ غَزَا آخرون وشومان فغَنِمَ وقَسَّمَ ما أصاب، ولم يكُن للمُفَضَّل بيتُ مَالٍ، كان يُعطِي النَّاس كُلمَّا جاء شيءٌ، وإن غَنِمَ شَيئًا قَسَّمَه بينهم."},{"id":356,"era":"c1","t":"بَيْعَة عبدِ المَلِك بن مروان لِوَلَدَيْهِ الوَليد ثمَّ سُليمان .","s":"أراد عبدُ الملك بن مَرْوان أن يَخْلَع أخاه عبدَ العزيز مِن وِلايَة العَهْد ويُبايِع لابنِه الوَليد بن عبدِ الملك، فنَهاهُ عن ذلك قَبِيصَةُ بن ذُؤَيْب وقال: لا تَفعَل؛ فإنَّك تَبْعَث على نَفْسِك صَوتَ عَارٍ، ولَعَلَّ الموتَ يأتيه فتَسْتَريح منه. فَكَفَّ عنه ونَفْسُه تُنازِعُه إلى خَلْعِه. فدَخَل عليه رَوْحُ بن زِنْباع، وكان أَجَلَّ النَّاس عند عبدِ الملك، فقال: يا أميرَ المؤمنين، لو خَلعتَه ما انْت"},{"id":357,"era":"c1","t":"غَزْوُ قُتيبَة بن مُسلِم أَرض التُّرْك .","s":"قَدِمَ قُتيبةُ خُراسان أميرًا عليها للحَجَّاج، فقَدِمَها والمُفَضَّل يَعرِض الجُنْدَ للغَزَاةِ، فخَطَب قُتيبةُ النَّاسَ وحَثَّهُم على الجِهاد، ثمَّ عَرَضَهم وسَارَ، وجَعَل بِمرو على حَرْبِها إياس بن عبدِ الله بن عَمرٍو، وعلى الخَراجِ عُثمان السعيدي. فلمَّا كان بالطَّالقان أتاهُ دَهاقِين بَلْخ وساروا معه، فقَطَع النَّهْر، فتَلَقَّاه مَلِكُ الصَّغَانِيَان بِهَدايا ومَفاتِيح مِن ذَهَبٍ، ودَعاهُ إلى ب"},{"id":358,"era":"c1","t":"غَزْوُ مَسْلَمة بن عبدِ الملك بِلاد الرُّوم وهَلَاك ملكها .","s":"غَزَا مَسلَمةُ بن عبدِ الملك الرُّومَ فقَتَل منهم عددًا كبيرًا بسوسنة مِن ناحِيَة المَصِّيصة وفَتَح حُصونًا. وقِيلَ: إنَّ الذي غَزَا في هذه السَّنَة هِشامُ بن عبدِ الملك ففَتَح حِصْنَ بولق، وحِصْن الأخرم، وحِصْن بولس وقمقم، وقَتَل مِن المُتَعَرِّبَة نحوًا مِن ألفِ مُقاتِل وسَبَى ذُرِّيَّتَهم ونِساءَهم."},{"id":359,"era":"c1","t":"وَفاةُ الخَليفَة عبدِ الملك بن مَرْوان .","s":"هو عبدُ الملك بن مَرْوان بن الحَكَم بن أبي العاصِ بن أُمَيَّة، أبو الوَليد الأُمَويُّ أَميرُ المؤمنين، وُلِدَ سنة سِتٍّ وعشرين بالمدينة, شَهِدَ الدَّارَ –يعني يومَ مَقْتَل عُثمان-مع أبيه، وله عَشْرُ سِنين، وهو أوَّلُ مَن سَارَ بالنَّاس في بِلاد الرُّوم سنة ثنتين وأربعين، وكان أَميرًا على أهلِ المدينة وله سِتَّ عَشرةَ سنة، وَلَّاهُ إيَّاها مُعاوِيَةُ، وكان يُجالِس الفُقَهاء والعُلَماء والعُبَّاد وا"},{"id":360,"era":"c1","t":"الوَليد بن عبدِ الملك يَتَوَلَّى الخِلافَة .","s":"لمَّا دُفِنَ عبدُ الملك بن مَرْوان انْصَرَف الوَليدُ عن قَبرِه فدَخَل المَسجِد وصَعَد المِنْبَر واجْتَمع إليه النَّاسُ فخَطَبَهم وقال: إنَّا لله وإنَّا إليه راجِعون، والله المُستعان على مُصِيبتِنا لِمَوتِ أَميرِ المؤمنين، والحمدُ لله على ما أَنْعَمَ علينا مِن الخِلافَة، قوموا فبايِعُوا، فكان أوَّلَ مَن عَزَّى نَفْسَه وهَنَّأَهَا؛ وكان أوَّلَ مَن قام لِبَيْعَتِه عبدُ الله بن هَمَّام السَّلُولِيُّ."},{"id":361,"era":"c1","t":"وَضْعُ أُسُسِ بِناءِ المَسجِد الأُمَويِّ الجامِع بِدِمَشْق .","s":"شَرَعَ الخَليفةُ الوَليدُ بن عبدِ الملك بن مَرْوان في بِناءِ جامِع دِمَشق الأُمَويِّ؛ وكان نِصْفُه كَنيسةَ النَّصارَى، وعلى ذلك صَالَحَهم أبو عُبيدةَ بن الجَرَّاح؛ فقال لهم الوَليدُ: إنَّا قد أَخَذنا كَنيسةَ مَريمَ عَنْوَةً فأَنَا أَهْدِمُها، فَرَضوا بِهَدْمِ هذه الكَنيسَة وإبْقاء كَنيسَة مَريم؛ والمِحْراب الكبير هو مكان بابِ الكَنيسَة."},{"id":362,"era":"c1","t":"تَوَلِّي عُمَرَ بن عبدِ العزيز إِمارَة المدينة .","s":"عَيَّنَ الوَليدُ بن عبدِ الملك عُمَرَ بنَ عبدِ العزيز على إِمارَةِ المَدينَة بعدَ أن عَزَلَ هِشامَ بن إسماعيلَ عن وِلَايَتِها، ثمَّ ضَمَّ إليه وِلايَةَ الطَّائِف سنة 91هـ، وبذلك صار وَالِيًا على الحِجازِ كُلِّها, وكانت إمارتُه عليها أربعَ سِنين غير شَهرٍ أو نَحوِه، فقَدِمَها وَالِيًا وثَقَلُه على ثلاثين بَعِيرًا، فنَزَل دارَ مَرْوان، وجَعَل يَدخُل عليه النَّاسُ فيُسَلِّمون، فلمَّا صلَّى الظُّهْرَ "},{"id":363,"era":"c1","t":"غَزْوُ قُتيبةَ بن مُسلِم لِبِيكَنْد (أَدْنَى مَدائِن بُخارَى) .","s":"غَزَا قُتيبةُ بِيكَنْد وهي أَدْنَى مَدائِن بُخارَى إلى النَّهْر، فلمَّا نَزَل بهم اسْتَنْصَروا الصُّغْدَ واسْتَمَدُّوا مَن حَولهم، فأَتوهم في جَمْعٍ كَثيرٍ وأَخَذوا الطُّرُقَ على قُتيبَة، فلم يَنْفَذ لِقُتيبَة رَسولٌ ولم يَصِل إليه خَبَرٌ شَهْرَيْنِ، وأَبطأَ خَبرُه على الحَجَّاج فأَشفَق على الجُنْدِ فأَمَر النَّاس بالدُّعاء لهم في المَساجِد وهُم يَقْتَتِلُون كُلَّ يومٍ. وكان لِقُتيبةَ عَيْنٌ مِن ا"},{"id":364,"era":"c1","t":"الوليد بن عبد الملك يُدْخِل حُجْرَةَ عائِشَة رَضِيَ الله عنها في المَسجِد النبوي .","s":"كَتَبَ الوَليدُ إلى عُمَرَ بن عبدِ العزيز في رَبيعٍ الأوَّل يَأمُره بِإدْخال حُجَرِ أَزواجِ النَّبِيِّ صلَّى الله عليه وسلَّم في مَسجِد رَسولِ الله صلَّى الله عليه وسلَّم، وأن يَشتَرِي ما في نَواحِيه حتَّى يكون مِائَتَي ذِراع في مِائَتَي ذِراع، ويَقول له: قَدِّم القِبْلَةَ إن قَدَرْتَ، وأنت تَقْدِر لِمَكان أَخوالِك، وإنَّهم لا يُخالِفُونك، فمَن أَبَى منهم فقَوِّمُوا مُلْكَهُ قِيمَةَ عَدْلٍ واهْدِم"},{"id":365,"era":"c1","t":"مَعرَكة حِصْن الطُّوانَة وهَزيمَة الرُّوم بِشَمال الشَّام بِقِيادَة مَسلمَة بن عبدِ الملك .","s":"غَزَا مَسلمةُ بن عبدِ الملك والعَبَّاس بن الوَليد بن عبدِ الملك بِلادَ الرُّومِ، وكان الوَليدُ قد كَتَبَ إلى صاحِب أرمينية يَأمُره أن يَكتُب إلى مَلِك الرُّوم يعرفه أن الخَزَر وغيرهم مِن مُلوك جِبال أرمينية قد اجتمعوا على قَصْدِ بِلادِه، ففَعَل ذلك، وقَطَعَ الوَليدُ البَعْثَ على أهلِ الشَّام إلى أرمينية وأَكْثَرَ وأَعْظَمَ جِهازَهُ، وساروا نحو الجَزيرَة ثمَّ عَطَفوا منها إلى بَلَدِ الرُّوم فاقْتَت"},{"id":366,"era":"c1","t":"الأمويون يتوغلون في بلاد الروم ويفتتحون عَمُّورِية وهِرْقَلَة وقَمُونِيَة .","s":"غَزَا مَسلمةُ والعَبَّاس بن الوَليد بن عبدِ الملك الرُّومَ، فافْتَتَح مَسلمةُ حِصْنَ سُورِيَة، وافْتَتَح العَبَّاسُ مَدينَة أذرولية، ثمَّ إنَّ مَسلمةَ قَصَد عَمُّورِيَة فلَقِيَ بها جَمْعًا مِن الرُّوم كثيرًا فهَزَمَهم وافْتَتَح هِرْقَلَة وقَمُونِيَة، وغَزَا العَبَّاس الصَّائِفَة مِن ناحِيَة البَذَنْدُون."},{"id":367,"era":"c1","t":"غَزْوُ محمَّد بن القاسِم بِلاد السِّنْد .","s":"سَارَ محمَّدُ بن القاسِم بن محمَّد بن الحَكَم بِأَمْرٍ مِن الحَجَّاج بِجَيْشٍ مُجَهَّزٍ بالكامِل إلى مُكْران فأَقام بها أيَّاما ثمَّ أَتَى قَنَّزْبُور ففَتَحَها، ثمَّ سَارَ إلى أَرمائِيل ففَتَحَها، ثمَّ سَارَ إلى الدَّيْبُل فقَدِمَها يومَ جُمُعَة، ووافَتْهُ سُفُنٌ كان حَمَلَ فيها الرِّجالَ والسِّلاحَ والأَداةَ فخَنْدَقَ حين نَزَل الدَّيْبُل, وكان بالدَّيْبُل بُدٌّ عَظيمٌ عليه دَقَلٌ عَظيمٌ وعلى ال"},{"id":368,"era":"c1","t":"تَوْلِيَة موسى بن نُصَير غَزْو بِلادِ المَغرِب  .","s":"كان موسى بن نُصَير ذا رَأْيٍ وتَدْبيرٍ وحَزْمٍ و خِبْرَةٍ بالحَرْبِ، فوَلَّاهُ عبدُ العزيز بن مَرْوان والي مِصْر على أفريقيا خَلَفًا لِحَسَّان بن النُّعْمان في خِلافَة الوَليدِ بن عبدِ الملك بن مَرْوان، فعَمِل موسى بن نُصَير على تَثْبيت دَعائِم الإسلام في إقليم أفريقيا، الذي ارْتَدَّ أَهلُه عن الإسلام أَكثرَ مِن مَرَّة؛ فاسْتَطاع موسى أن يُخْمِد ثَوْرات البَرْبَر المُتَعاقِبَة، ويُعيد فَتْحَ المَن"},{"id":369,"era":"c1","t":"إخماد موسى بن نصير ثورات البَرْبَر نهائيا  .","s":"لمَّا وَصَل موسى إلى أفريقيا وبها صالِحٌ الذي اسْتَخْلَفَه حَسَّانُ على أفريقيا، وكان البَرْبَر قد طَمِعوا في البِلاد بعدَ مَسير حَسَّان عنها، فلمَّا وَصَل موسى عَزَل صالِحًا، وبَلَغَه أنَّ بأَطْرافِ البِلادِ قومًا خارجِين عن الطَّاعَة، فوَجَّه إليه ابنَه عبدَ الله فقاتَلَهم فظَفَر بهم، وسَبَى منهم ألفَ رَأسٍ، وسَيَّرَه في البَحرِ إلى جَزيرَة مَيُورْقَة، فنَهَبَها وغَنِمَ منها ما لا يُحْصَى وعاد س"},{"id":370,"era":"c1","t":"فَتْحُ عبدِ الله بن موسى جَزائِر البِلْيار وطَنْجَة .","s":"وَجَّه موسى ابنَه عبدَ الله لِغَزْو جُزُر البِلْيار، فافْتَتَح مَيورْقَة ومَنورْقَة وإيبيزا وأَدْخَلَها تحتَ حُكْم الدَّولة الأُمَويَّة، كما أَرسَل حَمَلات لِغَزْو سِرْدانِيَة وصِقِلِّيَّة، عادَت مُحَمَّلَة بالغَنائِم. كما اسْتَطاع فَتْحَ طَنْجَة، ولم يُبْقِ بذلك في المَغرِب الأقصى سِوَى سَبْتَة التي كانت تحت حُكْم يُولْيان القُوطي, واسْتَعمَل مَولاهُ طارِقَ بن زِياد على طَنْجَة."},{"id":371,"era":"c1","t":"غَزْو قُتيبَة بن مُسلِم بِلاد الصُّغْد ومُحاوَلَة فَتْح مَدينَة بُخارَى .","s":"غَزَا قُتيبَةُ بن مُسلِم بِلادَ الصُّغْد ونَسَف وكِشّ وقد لَقِيَه هنالك خَلْقٌ مِن الأَتراك فظَفَر بهم فقَتَلَهم، وسارَ إلى بُخارَى فلَقِيَه دونها خَلْقٌ كَثيرٌ مِن التُّرْك فقاتَلَهم يَوْمَين ولَيْلَتين عندَ مَكانٍ يُقالُ له خَرْقان وظَفَر بهم, ثمَّ قَصَد قُتيبةُ وَرْدانَ خُذاه مَلِك بُخارَى فقاتَلَه وَرْدان قِتالًا شَديدًا فلم يَظْفَر به قُتيبةُ، فرَجَع عنه إلى مَرْو فجاءَهُ البَريدُ بكِتابِ الح"},{"id":372,"era":"c1","t":"فَتْحُ قُتيبَة بن مُسلِم بُخارَى .","s":"سارَ قُتيبةُ بن مُسلِم إلى بُخارَى مَرَّةً أُخرى, فأَرسَل مَلِكُها يَسْتَنْصِر مَن حَولَه، ولكنَّ قُتيبةَ اسْتَطاع فَتْحَها هذه المَرَّة، ولمَّا فَتَحَها اسْتَأْذَنه نَيْزَك طَرْخان في الرُّجوع إلى بِلادِه -وكان نَيْزَك قد أَسلَم وسُمِّيَ بعبدِ الله- فأَذِنَ له، فرَجَع إلى طُخارِستان، فعَصى وكاتَبَ مَن حَولَه، وجَمَع الجُموعَ، فزَحَف إليه قُتيبةُ، وانْتَصَر عليهم بعدَ قِتالٍ شَديدٍ وحَرْبٍ يَشيبُ "},{"id":373,"era":"c1","t":"غَزْو موسى بن نُصَير جَزيرَتي مَيُورْقَة ومَنُورْقَة .","s":"افتتح موسى بن نصير جزيرتي مَيُورْقَة ومَنُورْقَة، وهما جَزيرَتان في البَحر بين جَزيرَة صِقِلِّيَّة وجَزيرَة الأَندَلُس؛ وتُسَمَّى هذه الغزوة غَزوَة الأَشْراف لِكَثرَة الأَشْراف الذين كانوا بها مِن أَشْراف العَرَب."},{"id":374,"era":"c1","t":"طَريف بن مالِك يُمَهِّد لِفَتح الأَندَلُس .","s":"كانت بِدايَة فَتْح الأَندَلُس بأن يُولْيان حاكِم الجَزيرَة الخَضْراء غَضِبَ مِن لُذْريق (رُودْريغُو) مَلِك الأَندَلُس فاتَّفَق مع موسى بن نُصَير على أن يَدُلَّه على عَوْراتِهم ويُدْخِلَه الأَندَلُس, فكَتَب موسى إلى الوَليد يَسْتَأْذِنُه في غَزْو الأَندَلُس, فكَتَب إليه الوَليدُ: خُضْها بِالسَّرايا، ولا تُغَرِّر بالمسلمين في بِحْرٍ شَديدِ الأَهوال. فكَتَب إليه موسى: إنَّه ليس بِبَحْرٍ مُتَّسِع، وإن"},{"id":375,"era":"c1","t":"غَزْوُ قُتيبةَ بن مُسلِم سِجِسْتان .","s":"غَزَا قُتيبةُ بن مُسلِم سِجِسْتان، وأَراد قَصْدَ رتبيل الأعظَم، فلمَّا نَزَل قُتيبةُ سِجِسْتان أَرسَل رتبيل إليه رُسُلًا بالصُّلْح، فقَبِلَ ذلك وانْصَرف واسْتَعمَل عليهم عبدَ رَبِّه بن عبدِ الله اللَّيْثِيَّ."},{"id":376,"era":"c1","t":"غَزْوُ موسى بن نُصَير جَزيرَة سَرْدانِيَة .","s":"جَزيرَة في بَحرِ الرُّوم، وهي مِن أَكبَر الجَزائِر ما عَدا جَزيرَة صِقِلِّيَّة وأَقْرِيطِش، وهي كَثيرَة الفَواكِه، ولمَّا فَتَح موسى بِلادَ الأَندَلُس سَيَّرَ طائِفَةً مِن عَسكَرِه في البَحرِ إلى هذه الجَزيرَة فدَخَلوها، وعَمَدَ النَّصارى إلى ما لهم مِن آنِيَة ذَهَب وفِضَّة فأَلْقوا الجَميعَ في المِيناء الذي لهم، وجعلوا أَموالَهم في سَقْفٍ بَنوه للبَيْعَة العُظمى التي لهم تحت السَّقْف الأوَّل، وغَ"},{"id":377,"era":"c1","t":"انْتِصار المسلمين على الأَسْبان في مَوقِعَة وادِي لَكَّة (شَذُونَة) .","s":"بعدَ نَجاح غَزوَة طَريف بن مالِك بَعَث موسى بن نُصَير مَولاهُ على طَنْجَة طارِقَ بن زِياد في سَبعةِ آلاف مُقاتِل فسار فنَزَل في جَبَل مُنِيف يُعرَف إلى اليومِ بِجَبَلِ طارِق، ثمَّ دَخَل الجَزيرَة الخَضْراء ثمَّ تابَع مَسيرِه ومعه يُولْيان يَدُلُّه على طُرُق الأَندَلُس, ولمَّا بَلَغ لُذْرِيق (رودريغو) غَزْو طارِق بِلاده عَظُمَ ذلك عليه، وكان غائِبًا في غَزاتِه، فرَجَع منها وطارِق قد دَخَل بلاده، فج"},{"id":378,"era":"c1","t":"فتح قتيبة بن مسلم سمرقند .","s":"أَمَر قُتيبَة بن مُسلِم أخاه عبدَ الرحمن بالسَّيْرِ إلى الصُّغْد (سَمَرْقَنْد) وكانوا قد نَكَثوا العَهْد, ثمَّ لَحِقَ قُتيبةُ بِأَخيهِ فبَلَغَها بعدَه بثلاثٍ أو أَربَع، وقَدِمَ معه أَهلُ خَوارِزْم وبُخارَى فقاتَلَه أَهلُ الصُّغْد شَهْرًا مِن وَجْهٍ واحِد وهُم مَحْصورون، وخاف أَهلُ الصُّغْد طُولَ الحِصار فكَتَبوا إلى مَلِك الشَّاش وخاقان وأَخْشاد فَرْغانَة لِيُعينوهم، فلمَّا عَلِمَ بذلك قُتيبةُ أَر"},{"id":379,"era":"c1","t":"موسى بن نُصَير يَأْمُر بالتَّوَقُّف عن التَّوَغُّل في بِلادِ الأندَلُس .","s":"بعدَ أن تَوَغَّل طارِقُ بن زِياد في الأَندَلُس وفَتَحَ الله على يَديهِ ما شاء الله كَتَبَ بذلك إلى موسى بن نُصَير فأَمَرَهُ أن يَبْقى مَكانَه حتَّى يَأتِيَه."},{"id":380,"era":"c1","t":"موسى بن نُصَير يستأنف فُتوحات بَقِيَّة مُدُن الأَندَلُس .","s":"كان موسى بن نُصَير قد غَضِبَ على مَولاهُ طارِق بِسَبَب تَوَغُّلِه في أَرضِ العَدُوِّ, فاسْتَخْلَف على أفريقيا ابنَه عبدَ الله بن موسى، ثمَّ دَخَل الأَندَلُس وبَقِيَ فيها سَنتَيْنِ يَفتَح البُلْدان ويَغْنَم حتَّى صارت الأَندَلُس تحت سَيْطَرَتِه, عَبَرَ موسى إلى الأَندَلُس في جَمْعٍ كَثيرٍ قِوامُه ثَمانِيَة عشر ألفًا، فتَلَقَّاهُ طارِق وتَرَضَّاهُ، فرَضِيَ عنه وقَبِلَ عُذْرَه وسَيَّرَهُ إلى طُلَيْطُ"},{"id":381,"era":"c1","t":"وَفاةُ أَنَس بن مالِك رَضِيَ الله عنه .","s":"هو أَحَدُ المُكْثِرين مِن الرِّواية عن النَّبِيِّ صلَّى الله عليه وسلَّم، وليس بِغَريبٍ فهو خادِمُ النَّبِيِّ صلَّى الله عليه وسلَّم، دَعَا له النَّبِيُّ صلَّى الله عليه وسلَّم بِطُولِ العُمُر والبَرَكَة في المالِ والوَلَدِ، فكان له الكَثيرُ مِن الأوَّلادِ زادوا على المائة، وقِيلَ: كان له بُستانٌ يُثْمِرُ مَرَّتَيْنِ في السَّنَة. وكان سَكَنَ البَصْرَةَ وبَقِيَ فيها إلى أن تُوفِّي فيها، وهو آخِرُ ا"},{"id":382,"era":"c1","t":"الوَليد بن عبد الملك يعزل عُمَر بن عبدِ العزيز عن وِلايَة المَدينَة .","s":"كان سَبَب ذلك أنَّ عُمَر بن عبدِ العزيز كَتَبَ إلى الوَليد يُخْبِرُه عن أَهلِ العِراق أنَّهم في ضَيْمِ وضِيقٍ مع الحَجَّاجِ مِن ظُلْمِه وغَشْمِه، فسَمِع بذلك الحَجَّاجُ فكَتَبَ إلى الوَليد: إنَّ عُمَر ضَعيف عن إِمْرَةِ المَدينَة، وإنَّ جماعَة مِن أَهلِ الشِّقاق مِن أهلِ العِراق قد لَجَأوا إلى المَدينَة ومَكَّة، وهذا وَهْنٌ وضَعْفٌ في الوِلايَة، فاجْعَل على الحَرَمَيْنِ مَن يَضْبُط أَمْرَهُما. فكَت"},{"id":383,"era":"c1","t":"وَفاةُ أبي بَكْرِ بن عبدِ الرَّحمن أَحَد الفُقَهاء السَّبعَة في المَدينَة .","s":"هو أبو بَكْرِ بن عبدِ الرَّحمن بن الحارِث بن هِشام أَحَد الفُقَهاء السَّبعَة بالمَدينَة، كان ثِقَةً، فَقِيهًا، عالِمًا سَخِيًّا، كَثيرَ الحَديثِ، حَدَّث عن عَدَدٍ مِن الصَّحابَة كأَبيهِ، وعائِشَةَ، وأبي هُريرَةَ، وعَمَّارِ بن ياسِر، وغَيرِهم، جَمَعَ العِلْمَ والعَمَل والشَّرَف، وكان ممَّن خَلَفَ أَباهُ في الجَلالَة، كان يُقالُ له: رَاهِب قُريشٍ. لِكَثْرَةِ صَلاتِه، وكان مَكْفوفًا كَثيرَ الصَّوْم، "},{"id":384,"era":"c1","t":"فَتْحُ قُتيبةَ بن مُسلِم كابُل .","s":"بعدَ أن غَزَا قُتيبةُ بن مُسلِم الشَّاش وفَرْغانَة، وفَرَغَ مِن الصُّغْد، وفَتَحَ سَمَرْقَنْد، خاض بِلادَ التُّرْك يَفتَح فيها حتَّى وَصَل إلى كابُل فحاصَرَها وافْتَتَحَها، وقد لَقِيَه المُشرِكون في جُموعٍ هائِلَة مِن التُّرْك فقاتَلَهم قُتيبةُ عندِ خُجَنْدَة فكَسَرَهم مِرارًا وظَفَر بهم، وأَخَذ البِلادَ منهم، وقَتَل منهم خَلْقًا وأَسَر آخَرِين وغَنِمَ أَموالًا كَثيرةً جِدًّا."},{"id":385,"era":"c1","t":"وَفاةُ زَيْنِ العابِدِين عَلِيِّ بن الحُسين .","s":"هو عَلِيّ زَيْنُ العابِدِين بن الحُسين بن عَلِيِّ بن أبي طالِب، أُمُّهُ بِنتُ يَزْدَجِرْد آخِر مُلوك فارِس، مِن الفُقَهاء الحُفَّاظ كان مَضْرَب المَثَلِ في الحِلْمِ والوَرَعِ والجُودِ والتَّواضُع، مَدَحَهُ الفَرزدَقُ بالقَصيدَة المَشهورَة التي مَطلعُها: هذا الذي تَعرِف البَطحاءُ وَطأتَهُ والبَيتُ يَعرِفُه والحِلُّ والحَرَمُ، تُوفِّي في أوَّلِ هذه السَّنَة يعني سَنَة 94هـ، وصُلِّيَ عليه بالبَقيعِ و"},{"id":386,"era":"c1","t":"وَفاةُ عُرْوَة بن الزُّبير أَحَد الفُقَهاء السَّبعَة في المَدينَة .","s":"هو عُروَة بن الزُّبير بن العَوَّام، أَحَد الفُقَهاء السَّبعَة في المَدينَة، كان عالِمًا كَريمًا، رَوَى الحَديثَ عن كَثيرٍ مِن الصَّحابَة، تَفَقَّه على خالَتِه عائِشَة رَضِيَ الله عنها، انْتَقَل إلى البَصْرَة ثمَّ إلى مِصْرَ ثمَّ عاد إلى المَدينَة وتُوفِّي فيها، وهو الذي أُصِيبَت رِجْلُهُ بِمَرَضِ الآكال (الغرغرينا) فنُشِرَت وقُطِعَت وهو يَقرأُ القُرآن، وتُوفِّي له بِنَفْسِ اليَومِ أَحَبُ أوَّلادِه"},{"id":387,"era":"c1","t":"وَفاةُ سَعيد بن المُسَيِّب أَحَد الفُقَهاء السَّبعَة في المَدينَة .","s":"هو أَحَدُ الفُقَهاء السَّبْعة في المَدينَة (ومنهم مَن يَعُدُّ بَدَلَهُ سالِمَ بن عبدِ الله بن عُمَرَ)، سَيِّد التَّابِعين، جَمَع بين الحَديثِ والفِقْهِ والوَرَعِ والزُّهْدِ، رَوَى مَراسِيل عن النَّبِيِّ صلَّى الله عليه وسلَّم كَثيرةً، كان الحَسَنُ البَصريُّ إذا أُشْكِلَ عليه شَيءٌ كَتَبَ إليه يَسألُه، كان يَحفَظ أَحكامَ عُمَرَ بن الخَطَّاب وأَقْضِيَتَهُ، كان مَهِيبًا عند الخُلَفاء، تَعَرَّض للأَذَ"},{"id":388,"era":"c1","t":"مَقْتَل سَعيد بن جُبَير .","s":"هو سَعيدُ بن جُبَير بن هِشام الأَسَدِيُّ الوالِبِيُّ مَوْلاهُم الكوفيُّ، أبو محمَّد، كان وِعاءًا مِن أَوْعِيَة العِلْم, قال خُصَيف: كان أَعْلَمَهم بالقُرآن مُجاهِد، وأَعْلَمَهم بالحَجِّ عَطاء، وأَعْلَمَهم بالحَلال والحَرام طاووس، وأَعْلَمَهم بالطَّلاق سَعيد بن المُسَيِّب، وأَجْمَعَهم لِهذه العُلوم سَعيد بن جُبير. لقد مات سَعيد بن جُبَير وما على ظَهْر الأرضِ رَجُل إلَّا يَحتاجُ إلى عِلْمِ سَعيد, وك"},{"id":389,"era":"c1","t":"المسلمون يَفْتَحون بِلادَ السِّنْد .","s":"لمَّا مات الحَجَّاجُ بن يُوسُف كان محمَّد بن القاسِم بالمُلْتان، فأتاهُ خَبَرُ وَفاتِه، فرَجَع إلى الرُّور والبَغْرور، وكان قد فَتَحَهُما، فأَعْطَى النَّاسَ، ووَجَّهَ إلى البَيْلَمان جَيْشًا فلم يُقاتِلوا وأَعطوا الطَّاعَةَ، وسَألَه أَهلُ سُرَشْت، وهي مَغْزَى أَهلِ البَصْرَة، وأَهلُها يَقطَعون في البَحرِ، ثمَّ أَتَى محمَّدٌ الكَيْرَجَ فخَرَج إليه دَوْهَر فقاتَلَه فانْهَزَم دَوْهَر وهَرَب، وقِيلَ: "},{"id":390,"era":"c1","t":"وَفاةُ الحَجَّاجِ بن يُوسُف الثَّقَفي .","s":"هو أبو محمَّد الحَجَّاجُ بن يُوسُف الثَّقَفي، قائِدٌ أُمَوِيٌّ، داهِيَة، سَفَّاك، خَطِيب، وُلِدَ وَنَشأَ في الطَّائِف، وانْتَقَل إلى الشَّام فلَحِقَ بِرَوْحِ بن زِنْباع نائِب عبدِ الملك بن مَرْوان فكان في عِدادِ شُرْطَتِه، ثمَّ ما زال يَظهَر حتَّى قَلَّدَهُ عبدُ الملك أَمْرَ عَسْكَرِهِ, ثمَّ أَصبَح والِيًا على العِراق مِن قِبَل عبدِ الملك بن مَرْوان، أَصلَح البِلادَ في العِراق واعْتَنَى بها، وازْد"},{"id":391,"era":"c1","t":"غَزْوُ قُتيبةَ بن مُسلِم بِلاد الصِّين وفرض الجِزْيَة على مَلِكِها .","s":"غَزَا قُتيبةُ بن مُسلِم كاشْغَر, وهي أَدْنَى مَدائِن الصِّين، وحَمَل مع النَّاسِ عِيالَهُم لِيَضَعَهُم في سَمَرْقَنْد فلمَّا بَلَغ النَّهْرَ اسْتَعمَل رَجُلًا مِن مَوالِيه يُقالُ له الخَوارِزْمي على مَقْطَع النَّهْر، وقال: لا يَجُوزَنَّ أَحَدٌ إلَّا بِجَوازٍ منه، ومَضَى إلى فَرْغانَة، وأَرسَل مَن يُسَهِّل له الطَّريقَ إلى كاشْغَر، وبَعَث جَيْشًا مع كَبيرِ بن فُلان إلى كاشْغَر، فغَنِمَ وسَبَى سَبْي"},{"id":392,"era":"c1","t":"وَفاةُ إِبراهيمَ النَّخَعِيِّ .","s":"هو إِبراهيمُ بن يَزيدَ بن قَيسٍ النَّخَعِيُّ، فَقِيهُ العِراق وأَحَدُ الأئِمَّة المَشهورين، تابِعِيٌّ أَدرَك عَددًا مِن الصَّحابَة لكن لا يُعرَف له سَماعٌ عنهم، وأَخَذ عن كِبارِ التَّابِعين، تَزَعَّمَ مَدرَسةَ ابنِ مَسعودٍ في الكوفَة، حيث أَخَذ عن خالِه الأَسوَدِ بن يَزيدَ تِلميذ ابنِ مَسعود، وعن عَلْقَمَة، ومَسروق، وعبدِ الرَّحمن بن عبدِ الله بن مَسعود، وعليه تَتَلْمَذ حَمَّادُ بن سُليمان شَيخُ أ"},{"id":393,"era":"c1","t":"وفاةُ الوليد بن عبد الملك وتولِّي أخيه سليمان الخِلافَة .","s":"توفي الوليد بن عبدالملك في هذا العام وتولَّى أخوه سليمان من بعده الخلافة وبُويع له في اليوم الذي توفِّي فيه الوليد، وكان قويًا كريمًا محبوبًا."},{"id":394,"era":"c1","t":"تَمَرُّد قُتيبةَ بن مُسلِم الباهِلِي  .","s":"لمَّا أَرادَ الوَليدُ بن عبدِ المَلِك أن يَنْزِع أَخاهُ سُليمان مِن وِلايَة العَهْد ويَجعَل بَدَلَه ابنَه عبدَ العَزيز، أَجابَه إلى ذلك الحَجَّاجُ وقُتيبةُ على ما تَقَدَّم، فلمَّا مات الوَليدُ ووَلِيَ سُليمانُ خافَهُ قُتيبةُ، وخاف أن يُوَلِّي سُليمانُ يَزيدَ بن المُهَلَّب خُراسان، فكَتَب قُتيبةُ إلى سُليمانَ كِتابًا يُهَنِّئُه بالخِلافَة، ويَذكُر بَلاءَهُ وطاعَتَه لِعبدِ الملك والوَليدِ، وأنَّه له"},{"id":395,"era":"c1","t":"تَكامُل بِناء الجامِع الأُمَوِيِّ .","s":"كان الوَليدُ بن عبدِ الملك قد بَدَأَ بِتَأْسِيس البِناء للمَسجِد الأُمَوي في 87هـ إلى أن اكْتَمَل بِناؤُه في هذه السَّنَة, وكان أَصْلُ مَوضِع هذا الجامِع قَديمًا مَعْبَدًا بَنَتْهُ اليُونان الكُلْدَانِيُّون الذين كانوا يُعَمِّرون دِمَشْق، وهُم الذين وَضَعوها وعَمَّروها أوَّلًا، فَهُم أوَّلُ مَن بَناها، وقد كانوا يَعبدون الكَواكِب السَّبعَة المُتَمَيِّزَة، ثمَّ إنَّ النَّصارَى حَوَّلوا بِناءَ هذا ا"},{"id":396,"era":"c1","t":"وَفاةُ قُتيبةَ بن مُسلِم الباهِلِي .","s":"هو الأَميرُ أبو حَفْص قُتيبةُ بن مُسلِم بن عَمرِو بن حُصَين بن رَبيعَة الباهلي، أَحَدُ الأَبطال والشُّجْعان، ومِن ذَوِي الحَزْمِ والدَّهاءِ والرَّأْيِ والغَنَاءِ، كان مِن سادات الأُمَراء وخِيارِهم، وكان مِن القادَة النُّجَباء الكُبَراء، والشُّجْعان وذَوِي الحُروبِ والفُتوحات السَّعيدَة والآراء الحَميدَة، وهو الذي فَتَح خَوارِزْمَ وبُخارَى، وسَمَرْقَنْد، وكانوا قد نَقَضوا وارْتَدُّوا، ثمَّ إنَّه اف"},{"id":397,"era":"c1","t":"الأمويون يبدأون بتَجْهيز الجُيوش لِغَزْو القُسطنطينيَّة .","s":"جَهَّزَ سُليمانُ بن عبدِ الملك أَميرُ المؤمنين أَخاهُ مَسلمَة بن عبدِ الملك لِغَزْوِ القُسطنطينيَّة وَراء الجَيْش الذين هُم بها، فسار إليها ومعه جَيْشٌ عَظيمٌ."},{"id":398,"era":"c1","t":"وَفاةُ موسى بن نُصَير .","s":"هو أبو عبدِ الرَّحمن موسى بن عبدِ الرَّحمن بن زَيْدٍ اللَّخْمِيُّ، صاحِبُ فُتوحات الغَربِ، يُقالُ: إنَّه كان أَعْرَجًا. قِيلَ: أَصلُه مِن عَيْنِ التَّمْرِ، وقِيلَ: هو مَوْلًى لِبَنِي أُمَيَّة، وقِيلَ: لامْرَأَةٍ مِن لَخْمٍ وُلِدَ بِقَريَةِ كفرتُوثا مِن قُرَى الجَزيرَة, كان شُجاعًا مِقْدامًا جَوادًا، أَحَد قادَة الدَّولَة الأُمَويَّة، وَلَّاهُ مُعاوِيَةُ بن أبي سُفيان غَزْوَ البَحرِ، فغَزَا قُبْرُص"},{"id":399,"era":"c1","t":"حِصارُ مَسلمَة بن عبدِ الملك للقُسطنطينيَّة \n  .","s":"أَمَرَ سُليمانُ بن عبدِ الملك أَخاهُ مَسلمَة بالسَّيْرِ إلى القُسطنطينيَّة وألَّا يَعود حتَّى يَفتَحها، فَجَهَّزَهُ بمائةٍ وعشرين ألفًا في البَرِّ، ومائةٍ وعشرين ألفًا مِن المُقاتِلَة في البَحْرِ، وأَخرَج لهم الأُعْطِيات، وأَنفَق فيهم الأَموالَ الكَثيرَة، وأَعلَمَهم بِغَزْوِ القُسطنطينيَّة والإقامَة عليها إلى أن يَفتَحوها، ولمَّا اجْتَمَع العَساكِر عند سُليمان أَمَّرَ عليهم أَخاه مَسلمَة، وكان معه"},{"id":400,"era":"c1","t":"فَتْحُ يَزيدَ بن المُهَلَّب طَبَرِسْتان  .","s":"لمَّا فَتَح يَزيدُ بن المُهَلَّب قُهِسْتان وجُرْجان طَمِعَ في طَبَرِسْتان أن يَفْتَحها، فَعَزَم على أن يَسيرَ إليها، فاسْتَعمَل عبدَ الله بن المُعَمَّر اليَشْكُرِيَّ على السَّاسان وقُهِسْتان، وخَلَّفَ معه أَربعةَ آلاف، ثمَّ أَقبَل إلى أَدانِي جُرجان مما يَلِي طَبَرِسْتان، فاسْتَعمَل على أَيْذُوسا راشِدَ بن عَمرٍو، وجَعَلَه في أَربعةِ آلاف، ودَخَل بِلادَ طَبَرِسْتان، فأَرسَل إليه الإِصْبَهْبَذ صاحِ"},{"id":401,"era":"c1","t":"فَتْحُ يَزيد بن المُهَلَّب جُرجان الفَتْح الأوَّل .","s":"كان سُليمان بن عبدِ الملك كُلَّما فَتَح قُتيبةُ بن مُسلِم فَتْحًا في عَهدِ الوَليد يقول لِيَزيد بن المُهَلَّب: ألا تَرَى إلى ما يَفتَح الله على قُتيبَة؟ فيقول يَزيدُ: ما فَعَلَت جُرجان التي قَطَعَت الطَّريقَ، وأَفْسَدت قُومِس ونَيْسابور. ويقول أَيضًا: هذه الفُتوح لَيسَت بِشَيءٍ، الشَّأنُ هي جُرجان. فلمَّا وَلَّاهُ سُليمانُ خُراسانَ لم يكن لِيَزيد هِمَّة غَير جُرجان، فسار إليها في مائةِ ألف مِن أَه"},{"id":402,"era":"c1","t":"فَتْحُ يَزيد بن المُهَلَّب جُرجان الفَتْح الثَّاني .","s":"كان يَزيدُ فَتَح جُرجان وقُهِسْتان ثمَّ غَدَر أَهلُ جُرجان، فلمَّا صالَح يَزيدُ إصْبَهْبَذ صاحِبَ طَبَرِسْتان سار إلى جُرجان، وعاهَد الله تعالى لَئِن ظَفَر بهم لا يَرفَع السَّيفَ حتَّى يَطحَن بِدِمائِهم، ويَأكُل مِن ذلك الطَّحِين. فأَتاها فحَصَرهم يَزيدُ فيها سَبعةَ أَشهُر، وهُم يَخرُجون إليه في الأيَّام فيُقاتِلونَه ويَرجِعون, فبَيْنَا هُم على ذلك إذ خَرَج رَجَلٌ مِن عَجَم خُراسان يَتَصَيَّد، وقِ"},{"id":403,"era":"c1","t":"وَفاةُ عُبيدِ الله بن عبدِ الله بن مَسعودٍ أَحَد الفُقَهاء السَّبعَة في المَدينَة .","s":"هو عُبيدُ الله بن عبدِ الله بن عُتْبَة بن مَسعودٍ أَحَدُ الفُقَهاء السَّبعَة بالمَدينَة، مُفْتِي المَدينَة وعالِمُها، حَدَّثَ عن ابنِ عَبَّاس ولازَمَهُ طَويلًا، وعن عائِشَةَ، وأبي هُريرةَ، وغَيرِهم، وهو مُعَلِّم عُمَر بن عبدِ العزيز، كان يُطيلُ الصَّلاةَ ولا يُعَجِّلُها لِأَحَدٍ."},{"id":404,"era":"c1","t":"وَفاةُ خارِجَة بن زَيدٍ أَحَد الفُقَهاء السَّبعَة في المَدينَة .","s":"هو خارِجَة بن زَيدِ بن ثابِت، أَحَد الفُقَهاء السَّبعَة بالمَدينَة، رَوَى عن أَبيهِ وعن غيره مِن الصَّحابَة، قال مُصعَبُ بن الزُّبير: كان خارِجَة بن زَيدٍ، وطَلحَة بن عبدِ الله بن عَوْف في زَمانِهِما يُسْتَفْتَيان، ويَنتَهِي النَّاسُ إلى قَولِهِما، ويَقْسِمان المَواريثَ بين أَهلِها مِن الدُّورِ والنَّخيل والأَموال، ويَكْتُبان الوَثائِقَ للنَّاسِ."},{"id":405,"era":"c1","t":"وَفاةُ الخَليفَة سُليمان بن عبدِ الملك .","s":"هو سُليمان بن عبدِ الملك بن مَرْوان بن الحَكَم بن أبي العاص بن أُمَيَّة بن عبدِ شَمس القُرشيُّ الأُمَويُّ، أبو أَيُّوب. كان مَولِده بالمدينة في بني جَذيلَة، وهو الخَليفَة الأُمَوي السَّابِع، ويُعَدُّ مِن خُلفاء بني أُمَيَّة الأقوِياء, وُلِدَ بدِمشق عام 54هـ ووَلِيَ الخِلافَة بعدَ أَخيه الوَليد  عام 96هـ. ومُدَّة خِلافَتِه لا تَتَجاوز السَّنَتيْنِ وسَبعَة شُهور. كان النَّاس في دِمشق يُسَمُّونه مُفت"},{"id":406,"era":"c1","t":"عُمَر بن عبدِ العزيز يَتَوَلَّى الخِلافَة الأُمَويَّة .","s":"لمَّا قَرُبَت وَفاةُ سُليمان كان يُريد أن يَعْهَد لِوَلَدِهِ داود؛ لكنَّ رَجاء بن حَيْوَة صَرَفَهُ عن ذلك، فسَأَلَهُ عن عُمَر بن عبدِ العزيز فأَثْنَى رَجاءُ عليه، فجَعَل سُليمانُ الأَمْرَ لِعُمَر بن عبدِ العزيز، ثمَّ لِيَزيد بن عبدِ الملك بَعدَهُ، فكان لِرَجاء الفَضْل في إحْكام ذلك بعدَ مَوتِ سُليمان، فقرأ عليهم كِتابَ سُليمان بعدَ أن أَخَذَ البَيْعَةَ على الكِتابِ منهم، ثمَّ أَجْلَس عُمَرَ بن عبد"},{"id":407,"era":"c1","t":"بداية نشأة الدَّعْوَة العَبَّاسِيَّة .","s":"وَجَّهَ محمَّدُ بن عَلِيِّ بن عبدِ الله بن عَبَّاس الدُّعاة في الآفاق، وكان سَبَب ذلك أنَّ أبا هاشِم عبدَ الله بن محمَّد بن الحَنَفِيَّة سار للشَّام إلى سُليمان بن عبدِ الملك، فلمَّا أَكرَمَه وقَضَى حَوائِجَه، ورَأَى مِن عِلْمِه وفَصاحَتِه ما حَسَدهُ عليه وخافه، فلمَّا أَحَسَّ أبو هاشِم بالشَّرِّ قَصَدَ الحُمَيْمَة مِن أَرضِ الشَّراةِ بالأردن، وبها محمَّدُ بن عَلِيِّ بن عبدِ الله بن عَبَّاس، فنَزَ"},{"id":408,"era":"c1","t":"خُروجُ بِسْطام اليَشْكُرِيِّ على عُمَر بن عبدِ العزيز  .","s":"خَرجَت خارِجَة مِن الحَرورِيَّة بالعِراق، يَتَزَعَّمُهم شَوْذَب واسْمُه بِسْطام مِن بَنِي يَشْكُر في ثمانين فارِسًا أَكثرُهم مِن رَبيعَة، فبَعَث أَميرُ المؤمنين عُمَرُ بن عبدِ العزيز إلى عبدِ الحَميدِ نائِب الكوفَة يَأمُرهُ بأن يَدعوهم إلى الحَقِّ، ويَتَلَطَّف بِهم، ولا يُقاتِلهم حتَّى يُفسِدوا في الأَرضِ، فلمَّا فَعَلوا ذلك بَعَث إليهم جَيْشًا فكَسَرهُم الحَرورِيَّةُ، فبَعَث عُمَرُ إليه يَلومُه ع"},{"id":409,"era":"c1","t":"تَوَلِّي السَّمْح بن مالِك الخَوْلاني الأَنْدَلُس  .","s":"لمَّا وَلِيَ عُمَرُ بن عبدِ العزيز الخِلافَةَ اسْتَعمَل على الأَندَلُس السَّمْحَ بن مالِك الخَوْلاني خَلَفًا للحُرِّ بن عبدِ الرَّحمن الثَّقَفي لِمَا رَأَى مِن أَمانَتِه ودِيانَتِه, وأَمَره أن يُمَيِّز أَرضَها، ويُخرِج منها ما كان عَنْوَةً ويَأخُذ منها الخُمُسَ، ويَكتُب إليه بِصِفَة الأَندَلُس. فقَدِمَها السَّمْحُ، وفَعَل ما أَمَره عُمَرُ، وعَهِدَ إليه بإجْلاءِ المسلمين مِن الأَندَلُس خَشيَةً مِنه"},{"id":410,"era":"c2","t":"ثَوْرَة يَزيد بن المُهَلَّب في العِراق ومَقْتَلُه .","s":"كان يَزيدُ بن المُهَلَّب قد سُجِنَ أيَّام عُمَر بن عبدِ العزيز لِتَأْدِيَة المَظالِم التي عليه، فلمَّا عَلِمَ بِمَرَضِ عُمَر بن عبدِ العزيز هَرَب مِن السِّجْن خَوفًا مِن يَزيد بن عبدِ الملك، فلمَّا تَوَلَّى يَزيدُ بن عبدِ الملك سَجَنَ آلَ المُهَلَّب؛ لكنَّ يَزيد بن المُهَلَّب اسْتَطاع أن يَفُكَّهم وتَغَلَّبَ على البَصْرَة ثمَّ سَجَنَ أَميرَها وبَعَث عُمَّالَه إلى الأَهوازِ وفارِس، وأَرسَل أخاه إلى"},{"id":411,"era":"c2","t":"وَفاةُ الخَليفَة الصَّالِح عُمَر بن عبدِ العزيز .","s":"هو عُمَر بن عبدِ العزيز بن مَرْوان بن الحَكَم بن العاص بن أُمَيَّة بن عبدِ شَمس القُرشِي الأُمَوي، أَميرُ المؤمنين، أُمُّهُ أُمُّ عاصِم لَيْلَى بِنتُ عاصِم بن عُمَر بن الخَطَّاب، ويُقال له: أَشَجُّ بَنِي مَرْوان. وكان يُقال: الأَشَجُّ والنَّاقِصُ أَعْدَلا بَنِي مَرْوان. فهذا هو الأَشَجُّ، بُويِعَ له بالخِلافَة بعدَ ابنِ عَمِّه سُليمان بن عبدِ الملك عن عَهْدٍ منه له بذلك. ويُقال: كان مَولِدُه في سَ"},{"id":412,"era":"c2","t":"يَزيدُ بن عبدِ الملك يَتَوَلَّى الخِلافَة بعدَ وَفاةِ عُمَر بن عبدِ العزيز .","s":"دامَت خِلافَةُ عُمَر بن عبدِ العزيز سَنَتينِ وخَمسة أَشهُر، فلمَّا تُوفِّي صارت الخِلافَةُ إلى يَزيد بن عبدِ الملك بِناءً على الكِتاب الذي كَتبَه سُليمانُ أن يَلِيَ الأمْرَ بعدَ عُمَر يَزيدُ فصار بذلك الخَليفَة."},{"id":413,"era":"c2","t":"غَزْوُ السَّمْح بن مالِك الخَوْلاني فَرنسا واسْتِشهادُه في مَعركَة طولوز .","s":"غَزا السَّمْحُ بن مالِك الخَوْلاني فَرنسا فاخْتَرق جِبالَ البرانس وزَحَف على مُقاطَعَتي سبتمانيا وبروفانس، ثمَّ أَغارَ على اكيتانيا، وحاصَر طلوشة (طولوز) فخَرَج له دُوق اكيتانيا بجَيشٍ كَبيرٍ ونَشبَت مَعركَة عَظيمَة بين الطَّرَفين، اسْتُشْهِدَ فيها السَّمْح، وتَوَلَّى إمْرَةَ الجُنْدِ عبدُ الرَّحمن الغافِقي فانْسَحَب بِفُلول الجَيْشِ إلى أربونه."},{"id":414,"era":"c2","t":"غَزْوُ بِلادِ الصُّغْدِ  .","s":"عَبَر سَعيدُ خُذَيْنَة والي خُراسان النَّهْرَ وغَزا الصُّغْدَ، وكانوا قد نَقَضوا العَهْدَ وأعانوا التُّرْكَ على المسلمين، فقال النَّاسُ لسَعيدٍ: إنَّك قد ترَكتَ الغَزْوَ، وقد أغار التُّرْكُ، وكَفَرَ أَهلُ الصُّغْد. فقَطَع النَّهْرَ وقَصَد الصُّغْدَ، فلَقِيَه التُّرْكُ وطائِفَة مِن الصُّغْدِ فهَزَمهم المسلمون، فقال سَعيدٌ: لا تَتَّبِعوهم فإنَّ الصُّغْدَ بُستان أَميرِ المؤمنين وقد هَزَمتُموهم، أَفَت"},{"id":415,"era":"c2","t":"عَزْلُ عبدِ الرَّحمن بن الضَّحَّاك عن المَدينَة ومَكَّة .","s":"عَزَل يَزيدُ بن عبدِ الملك عبدَ الرَّحمن بن الضَّحَّاك عن المَدينَة ومَكَّة، وكان عامِلَهُ عليهما ثلاثَ سِنين، ووَلَّى عبدَ الواحِد النَّضْري، وكان السَّبَب في عَزْلِه أنَّه خَطَب فاطِمَة بِنتَ الحُسين بن عَلِيٍّ فقالت: ما أُريدُ النِّكاحَ، ولقد قَعَدتُ على بَنِيِّ هؤلاء. فأَلَحَّ عليها وقال: لئن لم تَفعَلي لأَجْلِدَنَّ أَكبرَ بَنِيك في الخَمْرِ. فبَعَثَتْ كِتابًا إلى الخَليفَة تُخبِرُه بِخَبرِه. "},{"id":416,"era":"c2","t":"غَزْوُ مُسلِم بن سَعيد بِلادَ التُّرْك .","s":"غَزَا مُسلِمُ بن سَعيد التُّرْكَ فعَبَر النَّهرَ وعاثَ في بِلادِهم ولم يَفتَح شَيئًا وقَفَلَ، فأَتْبَعَه التُّرْكُ ولَحِقُوهُ على النَّهرِ فعَبَر بالنَّاسِ ولم يَنالوا منه، ثمَّ غَزا بَقِيَّةَ السَّنَة وحاصَر افشين حتَّى صالَحُوه على سِتَّة آلافِ رَأسٍ، ثمَّ دَفَعوا إليه القَلعَة، ثمَّ غَزَا سَنَة سِتٍّ ومائة وتَباطَأ عنه النَّاسُ, ولمَّا قَطَع مُسلمٌ النَّهرَ وصار ببُخارَى أَتاهُ كِتابٌ مِن خالدِ"},{"id":417,"era":"c2","t":"غَزْوُ عَنْبَسَة بن سُحَيْم الكَلْبِي فَرنسا (بِلادَ غالَة) .","s":"غَزَا عَنْبَسَةُ بن سُحَيْمٍ الكَلْبِي أَميرُ الأَندَلُس بَلدَ الفِرِنْج في جَمعٍ كَثيرٍ، ونازَل مَدينَة قَرْقَسُونة وحَصَر أَهلَها، فصالَحوه على نِصْف أَعمالِها، وعلى جَميعِ ما في المَدينَة من أَسرَى المسلمين وأَسلابِهم، وأن يُعطوا الجِزْيَة، ويَلتَزِموا بأَحكام الذِّمَّة مِن مُحارَبة مَن حارَبَه المسلمون، ومَسالَمة مَن سالَموه، فعاد عنهم عَنْبَسَة، ثمَّ تَوَغَّلَ داخِلَ فَرنسا وغَزَا إقليمَ الرو"},{"id":418,"era":"c2","t":"وَفاةُ يَزيدَ بن عبدِ الملك .","s":"هو يَزيدُ بن عبدِ الملك بن مَرْوان بن الحَكَم بن أبي العاص بن أُمَيَّة بن عبدِ شَمسِ بن عبدِ مَناف أبو خالدٍ القُرَشِي الأُمَوي، أَميرُ المؤمنين، وأُمُّهُ عاتِكَة بِنتُ يَزيدَ بن مُعاوِيَة. بُويِعَ له بالخِلافَة بعدَ عُمَر بن عبدِ العزيز في رَجب مِن سَنة إحدى ومائة، بِعَهْدٍ مِن أَخيهِ سُليمان أن يكون الخَليفَة بعدَ عُمَر بن عبدِ العَزيز رَحِمَه الله، تُوفِّي يومَ الجُمُعَة لِخَمسٍ بَقِينِ من رَجب"},{"id":419,"era":"c2","t":"تَوَلِّي هِشامِ بن عبدِ الملك الخِلافَة .","s":"تَوَلَّى هِشامٌ الخِلافَةَ بعدَ وَفاةِ أَخيهِ يَزيد بن عبدِ الملك وبِعَهْدٍ منه إليه بذلك."},{"id":420,"era":"c2","t":"ظُهورُ فِئَةٍ مِن الخَوارِج باليَمَن .","s":"خَرَج باليَمَنِ رَجُلٌ يُقالُ له: عَبَّاد الرُّعَيْنِي، فدَعا إلى مَذهَب الخَوارِج، واتَّبَعَه فِرْقَةٌ مِن النَّاس وحَكَموا، فقاتَلَهم يُوسُف بن عُمَر الثَّقَفِي فقَتَلَه وقَتَل أَصحابَه، وكانوا ثلاثمائة."},{"id":421,"era":"c2","t":"وَفاةُ سُليمان بن يَسار أَحَد الفُقَهاء السَّبْعَة  .","s":"هو أبو أَيُّوب سُليمانُ بن يَسارٍ، وُلِدَ في خِلافَة عُثمان سَنة أربع وثلاثين, مَوْلَى أُمِّ المؤمنين مَيْمونَة بِنتِ الحارِث، أَحَدُ الفُقَهاء السَّبْعَة بالمَدينَة، كان عالِمًا ثِقَةً عابِدًا وَرِعًا حُجَّةً، كَثيرَ الصِّيام، فَقيهًا كَبيرًا، أَبوهُ فارِسِيٌّ، رَوَى عن مَولاتِه مَيْمونَة، وعن عائِشَة، وأبي هُريرةَ، وغَيرِهم مِن الصَّحابَة، كان مِن أَوْعِيَة العِلْم بحيث إنَّ بَعضَهم قد فَضَّلَه "},{"id":422,"era":"c2","t":"غَزْوُ أَسَد القَسْرِي للغَوْرِ غرب أفغانستان .","s":"غَزَا أَسَدُ القَسْرِي جِبالَ نمروذ مَلِك القَرْقِيسِيان، مما يَلِي جِبالَ الطَّالقان، فصالَحَه نمروذ وأَسلَم على يَديهِ. وفيها غَزَا أَسَدٌ القَسْرِي الغَوْرَ -وهي جِبالُ هَراةَ- عَمَدَ أَهلُها إلى حَواصِلِهم وأَموالِهم وأَثقالِهم فجَعَلوا ذلك كُلَّه في كَهفٍ مَنيعٍ، لا سَبيلَ لِأَحَدٍ عليه، وهو مُسْتَعْلٍ جِدًّا، فأَمَر أَسَدُ بالرِّجالِ فحُمِلُوا في تَوابيت ودَلَّاهُم إليه، وأَمَر بِوَضْعِ ما ه"},{"id":423,"era":"c2","t":"وَفاةُ القاسِم بن محمَّد بن أبي بَكرٍ أَحَد الفُقَهاء السَّبْعَة في المَدينَة .","s":"هو القاسِمُ بن محمَّد بن أبي بَكْرٍ الصِّدِّيق، أَحَدُ الفُقَهاء السَّبعَة بالمَدينَة، مِن سادات التَّابِعين, كان ثِقَةً عالِمًا، مات أَبوهُ وعُمُرُه سَبعُ سَنوات, تَرَبَّى في حِجْرِ عَمَّتِه عائِشَة رَضِيَ الله عنها فتَفَقَّهَ عليها، فكان فَقيهًا إمامًا وَرِعًا كَثيرَ الحَديثِ، قال أبو الزِّناد: ما رَأيتُ أَحَدًا أَعلمَ بالسُّنَّةِ مِن القاسِم بن محمَّد، وما كان الرَّجُل يُعَدُّ رَجُلًا حتَّى يَع"},{"id":424,"era":"c2","t":"وَفاةُ عَنْبَسَة بن سُحَيْمٍ الكَلْبِي  .","s":"هو عَنْبَسَة بن سُحَيْمٍ الكَلْبِي -نِسْبَةً إلى قَبيلَة كَلْب اليَمانِيَّة، المَعروفَة بِتَأْيِيدِها للأُمَويِّين- والي الأَندَلُس، ومِن قادَةِ الدَّولَة الأُمَويَّة الأَفْذاذ، له فُتوحات واسِعَة في أوروبا، وقد أُصِيبَ بجِراحاتٍ في بَعضِ الوَقائِع مع الفِرِنْج، فكانت سَبَبَ وَفاتِه، رَحِمَه الله, وكانت وِلايَتُه على الأَندَلُس أربعَ سِنين وأربعة أَشهُر."},{"id":425,"era":"c2","t":"فَتْحُ المسلمين حِصْن طِيبَة بِأَرضِ الرُّوم .","s":"غَزَا مُعاوِيَةُ بن هِشام أَرضَ الرُّوم ففَتَح حِصْنًا يُقالُ له طِيبَة، فأُصِيبَ معه قَومٌ مِن أَهلِ أَنطاكِيَّة."},{"id":426,"era":"c2","t":"دُخولُ أَهلِ الذِّمَّة بسَمَرْقَنْد الإسلام بَعدَ وَضْعِ الجِزْيَة عنهم .","s":"دَعَا أَشْرَسُ بن عبدِ الله السُّلَمِي نائِبُ خُراسان أَهلَ الذِّمَّة بِسَمَرْقَنْد ومَن وَراء النَّهْر إلى الدُّخولِ في الإسلامِ، ويَضَع عنهم الجِزْيَة فأَجابوه إلى ذلك، وأَسلَم غالبُهم، ثمَّ طالَبَهم بالجِزْيَة فنَصَبوا له الحَرْب وقاتَلوه، ثمَّ كانت بينه وبين التُّرْك حُروبٌ كَثيرَة."},{"id":427,"era":"c2","t":"وَفاةُ الشَّاعِرَيْن الفَرَزدَق وجَرير  .","s":"الفَرَزدَق هو هَمَّام بن غالِب التَّميمِي أبو فِراس، له مَواقِف وأَشعار في الذَّبِّ عن آلِ البَيتِ، كان غالِبَ شِعْرِه الفَخْرُ، تُوفِّي وعُمُرُه يُقارِب المِائة. وجَدُّهُ صَعْصَعَة بن ناجِيَة صَحابِيٌّ، وَفَدَ إلى رَسولِ الله صلَّى الله عليه وسلَّم، وكان يُحْيِي المَوْءُودَة في الجاهِلِيَّة. قال: الفَرَزدَق وَفَدْتُ مع أبي على عَلِيٍّ، فقال: مَن هذا؟ قال: ابني وهو شاعِرٌ. قال: عَلِّمْهُ القُرآنَ "},{"id":428,"era":"c2","t":"انتصار مَسلَمَة بن عبدِ الملك على التُّرْك في غَزَاةِ الطِّين .","s":"قاتَل مَسلَمةُ بن عبدِ الملك مَلِكَ التُّرْكِ الأَعظَم خاقان، فزَحَف إلى مَسلَمة في جُموعٍ عَظيمَة فتَواقَفوا نَحوًا مِن شَهرٍ، ثمَّ هَزَم الله خاقان زَمَن الشِّتاءِ، ورَجَع مَسلَمَةُ سالِمًا غانِمًا، فسَلَك على مَسْلَك ذي القَرْنَيْنِ في رُجوعِه إلى الشَّام، وتُسَمَّى هذه الغَزَاة غَزَاة الطِّين، وذلك أنَّهم سَلَكوا على مَغارِق ومَواضِع غَرِقَ فيها دَوابٌّ كَثيرَة، وتَوَحَّل فيها خَلْقٌ كَثيرٌ، ف"},{"id":429,"era":"c2","t":"وَفاةُ الحَسَن البَصْرِي .","s":"هو أبو سَعيدٍ الحَسَنُ بن يَسار البَصْرِي، وُلِدَ قَبلَ سَنَتين مِن نِهايَة خِلافَة عُمَر بن الخَطَّاب في المَدينَة عام 21هـ. كانت أُمُّهُ تَخدُم أُمَّ سَلَمَة، ورُبَّما أَرْسَلَتْها في الحاجَةِ فتَشْتَغِلُ عن وَلَدِها الحَسَن وهو رَضيعٌ فتُشاغِلُه أُمُّ سَلَمَة بِثَدْيَيْها فيُدِرَّان عليه فيَرْتَضِعُ منهما، فكانوا يَرَون أنَّ تلك الحِكْمَةَ والعُلومَ التي أُوتِيها الحَسَن مِن بَرَكَةِ تلك الرَّض"},{"id":430,"era":"c2","t":"وَفاةُ محمَّد بن سِيرينَ .","s":"هو محمَّدُ بن سِيرينَ أبو بَكر بن أبي عَمرٍو الأَنصارِي، مَوْلَى أَنَسِ بن مالِكٍ النَّضْرِي، كان أبوه مِن سَبْيِ عَيْنِ التَّمْر، أَسَرَهُ في جُملَةِ السَّبْيِ خالدُ بن الوَليدِ، فاشْتَراهُ أَنسُ بن مالِك ثمَّ كاتَبَهُ. وُلِدَ ابنُ سِيرينَ لِسَنَتينِ بَقِيَتا في خِلافَة عُثمان، كان مِن جُلَّةِ التَّابِعين، قال هِشامُ بن حَسَّان: هو أَصْدَقُ مَن أَدركْتُ مِن البَشَرِ. ولمَّا مات أَنسُ بن مالِك أَو"},{"id":431,"era":"c2","t":"غَزْوُ أَبناء هِشامِ بن عبدِ الملك قَيْسارِيَّة .","s":"غَزَا مُعاوِيَةُ بن هِشامٍ الصَّائِفَة اليُسْرَى، وغَزَا سَعيدُ بن هِشامٍ الصَّائِفَة اليُمْنَى حتَّى أَتَى قَيْسارِيَّة."},{"id":432,"era":"c2","t":"فَتْحُ الأمويين مَدينَة البَيْضاء بِبِلادِ الخَزَر .","s":"اسْتَعمَل هِشامُ بن عبدِ الملك الحَجَّاحَ بن عبدِ الله الحَكَمِيَّ على أرمينية، وعَزَل أَخاه مَسلَمَة بن عبدِ الملك، فدَخَل بِلادَ الخَزَر مِن ناحِيَة تفليس وفَتَح مَدينَتَهم البَيْضاءَ وانْصَرَف سالِمًا، فجَمَعَت الخَزَرُ وحَشَدَت وسارَت إلى بِلادِ الإسلامِ."},{"id":433,"era":"c2","t":"غَزْوُ الجُنَيْدِ المُرِّيِّ التُّرْك (غَزْوَة الشِّعْب) .","s":"خَرَج الجُنَيْدُ المُرِّيُّ غازِيًا يُريدُ طَخارِسْتان، فوَجَّه عُمارَةَ بن حُرَيْم إلى طَخارِسْتان في ثمانِيَة عَشر ألفًا، ووَجَّهَ إبراهيمَ بن بَسَّام اللَّيْثِيَّ في عَشرةِ آلافٍ إلى وَجْهٍ آخَر، وجاشَت التُّرْكُ فأتوا سَمَرْقَنْد وعليها سَوْرَةُ بن الحُرِّ، فكَتَب سورةُ إلى الجُنَيْدِ: إنَّ خاقان جاشَ التُّرْكَ فخَرَجتُ إليهم فلم أَطِقْ أن أَمنَع حائِطَ سَمَرْقَنْد، فالغَوْثَ الغَوْثَ. وعَبَرَ"},{"id":434,"era":"c2","t":"غَزْوُ الجَرَّاح الحَكَمِي بِلاد اللَّان \n  .","s":"غَزَا الجَرَّاح بن عبدِ الله الحَكَمي بِلادَ الخَزَر شمال القوقاز، وهم إيرانيون، فاجْتَمَع الخَزَرُ والتُّرْك مِن ناحِيَة اللَّان، فلَقِيَهم الجَرَّاح فيمَن معه مِن أَهلِ الشَّام وأذربيجان، فاقْتَتَلوا أَشَدَّ قِتالٍ رَآهُ النَّاسُ، فصَبَر الفَريقان، وتَكاثَرَت الخَزَرُ والتُّرْكُ على المسلمين فاسْتُشْهِد هو ومَن معه مِن الجُنْدِ بأردبيل، ولمَّا قُتِلَ الجَرَّاح طَمِعَ الخَزَرُ وأَوْغَلوا في البِل"},{"id":435,"era":"c2","t":"وفاة الجراح الحكمي\n  .","s":"هو أبو عُقْبَة الجَرَّاح بن عبدِ الله الحَكَمي مُقَدِّم الجُيوش، فارِس الكَتائِب. وَلِيَ البَصْرَة من جِهَة الحَجَّاج، ثمَّ وَلِيَ خُراسان وسِجِسْتان لعُمَر بن عبدِ العزيز. وكان بَطلًا، شُجاعًا, عابِدًا، قارِئًا, كَبيرَ القَدْرِ, مَهيبًا طُوالًا، كان إذا مَرَّ في جامِع دِمَشق يَميلُ رَأسَه عن القَنادِيل مِن طُولِه. قال الجَرَّاح: تَرَكتُ الذُّنوبَ حَياءً أربعين سَنة، ثمَّ أَدْرَكَنِي الوَرَعُ. كان"},{"id":436,"era":"c2","t":"مُعاوِيَةُ بن هِشام يَغزو الرُّومَ  .","s":"غَزَا مُعاوِيَةُ بن هِشام أَرضَ الرُّومَ مِن ناحِيَة مَرْعَش."},{"id":437,"era":"c2","t":"مَسْلمَة بن عبدِ الملك يَتَوغَّل في بِلادِ التُّرْك .","s":"تَوَغَّلَ مَسلمَةُ بن عبدِ الملك في بِلاد التُّرْكِ فقَتَل منهم خَلْقًا كَثيرًا، ودانَت له تلك المَمالِك مِن ناحِيَة بَلَنْجَر وأَعْمالِها."},{"id":438,"era":"c2","t":"عبدُ الرَّحمن الغافِقِيُّ يَتَوَلَّى إِمارةَ الأَندَلُس ويَغزو بِلادَ الفِرِنْجَة .","s":"تَوَلَّى عبدُ الرَّحمن الغافِقِيُّ أُمورَ القِيادَةِ على الشَّاطِئ الشَّرقيِّ مِن الأَندَلُس مِن قِبَل عُبيدَة بن عبدِ الرَّحمن القَيْسِي صاحِب أفريقيا في عَهْدِ هِشامِ بن عبدِ الملك مُدَّةَ سَنتينِ ونِصف، وطِيلَة تلك المُدَد كان يَقوم بالغَزْوِ والفَتْح، وكانت انْتِصاراتُه على البَرْبَر مَشهودَةً، وساعَد على ذلك حُسْنُ مُعامَلتِه للبَرْبَر ممَّا كان له الأَثَر الكَبير في دُخولِ كَثيرٍ منهم إلى ال"},{"id":439,"era":"c2","t":"هَزيمَة المسلمين في مَعركَة بَلاط الشُّهَداء .","s":"وَلَّى هِشامُ بن عبدِ الملك عبدَ الرَّحمن الغافِقِي إمارَةَ الأَندَلُس فتَأَهَّبَ لِفَتحِ بِلادِ الغال (فرنسا) فدَعا العَرَبَ مِن اليَمَن والشَّام إلى مُناصَرَتِه فأَقْبَلوا إليه، فاجْتاز جِبالَ البِرانس بجَيْشٍ مِن العَرَب والبَرْبَر، وأَوْغَل في مُقاطَعَتي اكيتانيا ووبرغونية وبوردو، ثمَّ تَقدَّم يُريدُ الإيغال داخِلَ البِلادِ، فجَمَع له شارل مارتل جُموعَه وأَلَّفَ جَيشًا كَبيرًا مِن الغاليين وال"},{"id":440,"era":"c2","t":"وُقوعُ طاعونٍ بالشَّام وقَحْطٍ بخُراسان .","s":"في هذه السَّنَة وَقَع الطَّاعون بالشَّام، وفيها وَقَع بخُراسان قَحْطٌ شَديدٌ، فكَتَب الجُنيدُ المُرِّيُّ إلى الكور بِحَمْلِ الطَّعام إلى مَرْو، أَعْطَى الجُنيدُ رَجُلًا دِرْهَمًا فاشْتَرَى به رَغيفًا، فقال لهم أَتَشْكون الجُوعَ ورَغيفٌ بِدِرْهَم؟ لقد رَأَيْتُني بالهِنْدِ وإنَّ الحَبَّة مِن الحُبوب لَتُباع عددًا بِدِرْهَم."},{"id":441,"era":"c2","t":"تَوَلِّي مَرْوان بن محمَّد أرمينية والجَزيرَة وأذربيجان .","s":"اسْتَعمَل هِشامُ بن عبدِ الملك مَرْوانَ بن محمَّد بن مَرْوان -وهو ابنُ عَمِّه- على الجَزيرَة الفراتية وأذربيجان وأرمينية، وكان سَبَبُ ذلك أن مَرْوان بن محمَّد قال لهِشام: قد كان مِن دُخولِ الخَزَر إلى بِلادِ الإسلام وقَتْل الجَرَّاح وغَيرِه مِن المسلمين ما دَخَل به الوَهَنُ على المسلمين, أنَّ مَسلمَة بن عبد الملك، ما وَطِئ مِن بِلادِهم إلَّا أَدْناها، وكان قُصاراه السَّلامَة، وقد أَردتُ أن تَأذَن "},{"id":442,"era":"c2","t":"ثَورةُ بِلادِ ما وَراء النَّهرِ على الأُمَويِّين .","s":"غَضِبَ هِشامُ بن عبدِ الملك على أَميرِ خُراسان الجُنيدِ المُرِّيِّ فوَلَّى بَدَلًا عنه عاصِمَ بن عبدِ الله الهِلالِيَّ، وأَمَره أن يَسيرَ إليه وأن يَقتُلَه إن وَجَده حَيًّا، وكان الجُنيدُ مَريضًا ومات قَبلَ وُصولِ عاصِمٍ، فلمَّا وَصَل عاصِمٌ أَخَذ بالإساءَةِ إلى قادَةِ الجُنيدِ وأَظهَر القَسوَة، ممَّا أَثار عليه النَّاس، فخَرَج عليه الحارِثُ بن سُريجٍ وسار إلى الفارياب، وسَيَّرَ إليه عاصِمٌ جَيشًا"},{"id":443,"era":"c2","t":"غَزوُ مَرْوان بن محمَّد بن مَرْوان وارقيس  .","s":"غزا مَرْوانُ بن محمَّد بن مَرْوان مِن أرمينية ودخَل أرضَ وارقيس فهرَب وارقيس إلى الحرور ونزَل حِصنَه، فحَصَره مَرْوانُ ونصَب عليه المَجانيقَ، فقَتَل وارقيسَ بعضُ مَن اجتاز به وأَرسلَ رَأسَه إلى مَرْوان، فنَصبَه لأهلِ حِصنِه، فنزلوا على حُكمِه، فقَتَل المُقاتِلَة وسَبَى الذُّرِّيَّة."},{"id":444,"era":"c2","t":"وَفاةُ عبدِ الله بن عامِر أَحَد القُرَّاءِ السَّبْعَة .","s":"هو عبدُ الله بن عامِر بن يَزيدَ بن تَميمٍ اليَحْصُبِيُّ، أَحَدُ القُرَّاء السَّبعَة، إمامُ أَهلِ الشَّامِ في القِراءَةِ، والذي انْتَهت إليه مَشيَخَةُ الإقْراءِ بها، أَخَذ القِراءَةَ عَرَضًا عن أبي الدَّرْداء وعن المُغيرَة بن أبي شِهابٍ صاحِب عُثمان، وقِيلَ: عُرِضَ على عُثمان بن عَفَّان. ولا زال أَهلُ الشَّامِ قاطِبَةً على قِراءَةِ ابن عامِر تِلاوَةً وصَلاةً وتَلْقينًا إلى قَريبِ الخمسمائة، كان مِن"},{"id":445,"era":"c2","t":"وَفاةُ عبدِ الله بن كَثيرٍ أَحدُ القُرَّاء السَّبعَة .","s":"هو عبدُ الله بن كَثيرِ بن عَمرِو بن عبدِ الله بن زاذان بن فيروزان، أَحَدُ القُرَّاء السَّبعَة، إمامُ أَهلِ مَكَّة في القِراءَةِ، ولَقِيَ فيها عددًا مِن الصَّحابَة، وكان فَصيحًا بَليغًا مُفَوَّهًا، أَبيضَ اللِّحْيَة، طَويلًا، جَسيمًا، أَسْمَر، أَشْهَلَ العَينينِ، يَخضِب بالحِنَّاء، عليه السَّكينَة والوَقار، تُوفِّي في مَكَّة."},{"id":446,"era":"c2","t":"هِشامُ بن عبدِ الملك يعَزل خالد القَسري عن أَعمالِه .","s":"قام هِشامُ بن عبدِ الملك بِعَزلِ خالِدِ بن عبدِ الله القَسري البَجَلي ووَلَّى بَدلًا منه يُوسُف بن عُمَر الثَّقَفي، وقد اختَلفَت الرِّوايات بِشأنِ سَببِ عَزلِه."},{"id":447,"era":"c2","t":"التُّرك يُهاجِمون المسلمين بالقُربِ مِن نَهرِ بَلْخ  .","s":"سار أَسدُ بن عبدِ الله القَسري أَميرُ خُراسان بجُيوشِه إلى مَدينَة خُتَّل فافْتَتَحها، وتَفرَّقت في أَرضِها جُنودُه يَقتُلون ويَأسِرون ويَغنَمون، فجاءَت العُيونُ إلى مَلِك التُّركِ خاقان أنَّ جَيشَ أَسَد قد تَفرَّق في بِلادِ خُتَّل، فاغْتَنَم خاقان هذه الفُرصَة فرَكِب مِن فَوْرِه في جُنودِه قاصِدًا إلى أَسَد، وتَزَوَّد خاقان وأَصحابُه سِلاحًا كَثيرًا، وقَديدًا ومِلحًا، وساروا في خَلْقٍ عَظيمٍ، وجا"},{"id":448,"era":"c2","t":"انْتِفاضةُ زَيدِ بن عَلِيٍّ بالعِراق وظُهورُ طائِفَة الزَّيدِيَّة .","s":"لمَّا أَخَذ زَيدُ بن عَلِيٍّ زين العابدين بن الحُسينِ البَيْعَةَ ممَّن بايَعهُ مِن أَهلِ الكوفَة، أَمرَهم في أوَّلِ هذه السَّنَة بالخُروجِ والتَّأَهُّبِ له، فشَرَعوا في أَخذِ الأُهْبَةِ لذلك. فانطَلَق رَجلٌ يُقالُ له: سُليمان بن سُراقَة. إلى يُوسُف بن عُمَر الثَّقَفي نائِب العِراق فأَخبَره - وهو بالحِيرَةِ يَومَئذٍ - خَبَرَ زَيدِ بن عَلِيٍّ هذا ومَن معه مِن أَهلِ الكوفَة، فبَعَث يُوسُف بن عُمَر يَ"},{"id":449,"era":"c2","t":"ثورة البَرْبَر على العَرَب في المَغرِب الأَقصى .","s":"ثارت البَرْبَرُ بالمَغرِب فخَرَج مَيسَرة المدغري وقام على عُمَرَ بن عبدِ الله المُرادي بِطَنجَة فقَتَله وثارت البَرابِرُ مع أَميرِهم مَيسَرة الحَقير، ثمَّ خَلَّف مَيسَرةُ على طَنجَة عبدَ الأعلى بن حُدَيج، وزَحَف إلى إسماعيل بن عُبيدِ الله بن الحَبْحاب إلى السُّوس فقَتلَه، ثمَّ كانت وَقائعُ كَثيرةٌ بين أَهلِ المَغرِب الأقصى وأَهلِ أفريقيا، وكان المَغرِبُ حِينئذٍ قَومًا ظَهرَت فيهم دَعوةُ الخَوارِج،"},{"id":450,"era":"c2","t":"مَوقِعَة أكرونيون وهَزيمَة المسلمين .","s":"خَرَج إليون مِن القُسطنطينيَّة ومعه مائةُ أَلفِ فارِس، فأُخبِرَ بذلك البَطَّال وهو عبدُ الله الأنطاكي فأَخبَر البَطَّالُ أَميرَ عَساكِر المسلمين بذلك، وكان الأَميرُ مالِك بن شَبيب، وقال له: المَصلَحةُ تَقتَضِي أن نَتحَصَّن في مَدينَة حَرَّان فنَكُون بها حتَّى يَقدُم علينا سُليمانُ بن هِشام بالمَدَد، فأَبَى عليه ذلك ودَهمَهم الجَيشُ، فاقْتَتَلوا قِتالًا شَديدًا والأَبطالُ تَحومُ بين يدي البَطَّال و"},{"id":451,"era":"c2","t":"البَرْبَر يَنتصِرون في مَوقِعة الأَشراف بالمَغرِب .","s":"بعدَ أن تَفَشَّت الخَوارِج في المَغرِب وهُم الصُّفْرِيَّة وَلَّوْا عليهم مَيسرَة المدغري المعروف بِمَيسرَة الحَقير، فأَعلَن الثَّورَةَ على عُبيدِالله بن الحَبْحاب فاستولى على طَنجَة وقَتَل عامِلَها عُمَرَ بن عبدِ الله المُرادي ووَلَّى عبدَ الأعلى الرُّومي، فتَوَجَّه الأَخيرُ إلى السُّوس لِقِتال إسماعيل بن عُبيدِ الله بن الحَبْحاب، وكان أَبُوه وَلَّاه على السُّوس، وقُتِلَ في المعركة عبدُ الأعلى فسَ"},{"id":452,"era":"c2","t":"نَصرِ بن سِيار يغزو التُّرك، ويأَسْر مَلكهم كور صول .","s":"غَزا نَصرُ بن سِيار أَميرُ خُراسان غَزَوات مُتعدِّدَة في التُّرك، وأَسَرَ مَلِكَهم كور صول في بَعضِ تلك الحُروب وهو لا يَعرِفُه، فلمَّا تَيَقَّنه وتَحَقَّقه، سأَل منه كور صول أن يُطلِقَه على أن يُرسِلَ له أَلفَ بَعير مِن إِبِل التُّرك -وهي البَخاتي- وأَلفَ بِرْذَون، وهو مع ذلك شَيخٌ كَبيرٌ جِدًّا، فشاوَرَ نَصرُ مَن بِحَضرَتِه مِن الأُمراء في ذلك، فمنهم مَن أشار بإطلاقه، ومنهم مَن أشار بِقَتلِه. ثم"},{"id":453,"era":"c2","t":"ظُهورُ الدَّعوَة العَبَّاسِيَّة وتَكامُل أُسُسِها .","s":"كان بَدءُ الدَّعوَة مِن قِبَل محمَّد بن عَلِيِّ بن عبدِ الله بن عَبَّاس، ووَصَلت الدَّعوة إلى خُراسان، ثمَّ لمَّا تُوفِّي محمَّد بن عَلِيٍّ في عام 124 هـ سار بالأَمرِ مِن بَعدِه ابنُه إبراهيمُ وساعَد في قُوَّةِ الأَمرِ ظُهورُ أبي مُسلِم الخُراساني الذي كان يَخدِمُ في سِجْنِ يُوسُف بن عُمَر أَحدَ المَسجونين بِتُهمَةِ الدَّعوَة العَبَّاسِيَّة وكان بُكيرُ بن ماهان أَحَدَ الدُّعاة الكِبار للدَّعوَةِ ا"},{"id":454,"era":"c2","t":"وَفاةُ ابنِ شِهاب الزُّهري .","s":"هو محمَّدُ بن مُسلِم بن عُبيدِ الله بن شِهاب الزُّهري، أوَّلُ مَن دَوَّنَ الحَديثَ، أَحدُ كِبارِ الحُفَّاظ والفُقَهاء، حَدَّث عن عَددٍ مِن الصَّحابة كَأَنَسٍ وابنِ عُمَر، وأَرسَل عن النَّبِيِّ صلَّى الله عليه وسلَّم أَحاديثَ كَثيرَة، كان مِن مَشاهير القُرَّاء، له مُؤَلَّفات في المَغازي والتَّاريخ والقُرآن، اسْتَقَرَّ في الشَّام وبَقِيَ إلى أن قِيلَ ليس في الدُّنيا له نَظير، تُوفِّي في قَريَةِ شَغْ"},{"id":455,"era":"c2","t":"قَتلُ الجَعْدِ بن دِرهَم رَأسِ طائفة المُعَطِّلَة .","s":"هو الجَعْدُ بن دِرهَم، رَأسُ المُعَطِّلَة، أَصلُه مِن خُراسان، أَسلَم أَبوهُ وصار مِن مَوالي بَنِي مَرْوان، وقد وُلِدَ في خُراسان وهاجَر بعدَ ذلك إلى دِمَشق حيث أقام هناك، وهو أوَّلُ مَن ابْتَدَع: أن الله ما اتَّخَذَ إبراهيمَ خَليلًا، ولا كَلَّمَ موسى، وأن ذلك لا يَجوزُ على الله. كان الجَعْدُ زِنْديقًا، شَهِدَ عليه مَيمونُ بن مِهران، فطَلَبَه هِشام، فظَفَر به، وسَيَّرَهُ إلى خالدِ بن عبدِ الله الق"},{"id":456,"era":"c2","t":"وَفاةُ الخَليفَة الأُموي هِشامِ بن عبدِ الملك .","s":"هو هِشامُ بن عبدِ الملك بن مَرْوان بن الحَكَم بن أبي العاص بن أُمَيَّة بن عبدِ شَمسٍ، أبو الوَليد القُرَشي الأُمَوي الدِّمَشقي، أَميرُ المؤمنين، بُويِعَ له بالخِلافَة بعدَ أَخيهِ يَزيد بن عبدِ الملك بِعَهْدٍ منه إليه، وذلك يوم الجُمُعة لِأَربعٍ بَقِينَ مِن شَعبان سَنةَ خمَسٍ ومائة، وكان له مِن العُمُر يَومئذٍ أربعٌ وثَلاثون سَنَة، وكان جَميلًا أَبيضَ أَحْوَل، يَخضِبُ بالسَّواد، وهو الرَّابعُ مِن و"},{"id":457,"era":"c2","t":"الوَليدُ بن يَزيد يَتَوَلَّى الخِلافَة الأُمويَّة .","s":"كان يَزيدُ بن عبدِ الملك قد عَهِدَ الأمرَ مِن بَعدِه لأَخيهِ هِشام ثمَّ لابنِه الوَليد مِن بَعدِه، وكان الوَليدُ بن يَزيد ماجِنًا غارِقًا في شُربِ الخَمرِ، حاوَل عَمَّه هِشامٌ أَكثرَ مِن مَرَّة عَزْلَة مِن الخِلافَة لكنَّه لم يَفعل, فلمَّا تُوفِّي هِشام بُويِعَ بالخِلافَة للوَليدِ بن يزيد وعُمُره خمسٌ وثَلاثون سَنَة. أَكثَر الوَليدُ بن يَزيد العَطاءَ للنَّاس, وسار في النَّاس سِيرَةً حَسنَة في بِدا"},{"id":458,"era":"c2","t":"تولي أبو الخَطَّار وِلايةُ الأَندَلُس .","s":"كان أبو الخَطَّار لمَّا بايَعَ وُلاةَ الأندَلُس مِن قَيسٍ قد قال شِعرًا وعَرَّض فيه بِيَومِ مَرْج راهِط، وما كان مِن بَلاءِ كَلْبٍ فيها مع مَرْوان بن الحَكَم، وقِيام القَيْسِيِّين مع الضَّحَّاك بن قَيسٍ الفِهري على مَرْوان, فلمَّا بَلَغ شِعرُه هِشامَ بن عبدِ الملك عَلِم أنَّه رَجلٌ مِن كَلْبٍ، وكان هِشام قد استَعمَل على أفريقيا حَنضَلة بن صَفوان الكَلْبي سَنَة أربع وعشرين ومائة، فكَتَب إليه هِشامٌ"},{"id":459,"era":"c2","t":"اغْتِيالُ الخَليفَة الأُمَوي الوَليد بن يَزيد .","s":"لمَّا تَوَلَّى الوليدُ بن يَزيد بن عبدِ الملك الخِلافَة سار في أوَّلِ أَمرِه سِيرَةً حَسنَة مع أنَّه كان قد اشْتُهِرَ عنه أنَّه صاحِبُ شَرابٍ، ولكن الذي وَلَّد النِّقمَة عليه أنَّه عَقَد لِوَلدَيْهِ بالخِلافَة مِن بَعدِه الحَكَم وعُثمان، وهُما لم يَبلُغا سِنَّ الرُّشْد بعدُ، كما أَسرَف في شَرابِه وانْتِهاك المُحَرَّمات فثَقُلَ ذلك على النَّاس ونَقِموا عليه ممَّا حَداهم إلى أن بايَعوا سِرًّا لابنِ "},{"id":460,"era":"c2","t":"يزيد بن الوليد بن عبد الملك (الناقص) يَتَوَلَّى الخِلافَة .","s":"بُويِعَ لِيَزيد بن الوَليدِ الذي يُقالُ له: النَّاقِص، وإنَّما سُمِّيَ النَّاقِصَ لأنَّه نَقَصَ الزِّيادَة التي كان الوَليدُ زادَها في عَطِيَّاتِ النَّاس، وهي عشرة عشرة، ورَدَّ العَطاءَ إلى ما كان أيَّام هِشام، لمَّا قُتِلَ الوليد بن يَزيد خَطَب يَزيدُ بن وَليد النَّاسَ فذَمَّ الوَليدَ بن يَزيد وأنَّه قَتلَه لِفِعلِه الخَبيث. قال: (... ظَهَر الجَبَّارُ العَنيد، المُستَحِلُّ الحُرْمَة، والرَّاكِب ا"},{"id":461,"era":"c2","t":"بداية الانقسام والاختلاف بين بني أمية .","s":"لمَّا استَلَم يَزيدُ بن الوَليدِ الخِلافَة بعدَ أن قُتلَ ابنُ عَمِّه الوَليد بن يَزيد اضْطَربَت الأُمور عليه واختَلفَت كَلمةُ بَنِي مَرْوان، وخرج سُليمانُ بن هِشام مِن السِّجْن واسْتَولى على الأَموالِ، وكان في سِجْن الوَليد بن يَزيد في عَمَّان ثمَّ حَضَر دِمَشق، وثار أَهلُ حِمص يُطالِبون بِدَمِ الوَليد بن يَزيد وخَلعَوا أَميرَهم، وثار أَهلُ فِلَسطين وبايَعوا يَزيدَ بن سُليمان، وأَهلُ الأردن كذلك ث"},{"id":462,"era":"c2","t":"تَوَلِّي مَرْوان بن محمَّد الخِلافَة بعدَ قَتلِ إبراهيم بن الوَليد .","s":"لمَّا تُوفِّي يَزيدُ بن الوليد وكان قد عَهِدَ لأَخيهِ إبراهيم، فلمَّا سَمِع مَرْوانُ بن محمَّد بن عبدِ الملك بذلك، واسْتِلام إبراهيم بن الوَليد، قَفَل مِن خُرسان بالجزيرة وسار إلى دِمَشق وأَخَذ البَيْعَة لِنَفسِه، فمالَ إليه مِن قِنِّسرين ومِن حِمص الكثيرُ، ثمَّ جَرَت مَعركةٌ بينه وبين جُنْدِ إبراهيم انْتَصَر فيها مَرْوان، ثمَّ لمَّا وَصَل لِدِمَشق هَرَب إبراهيم وقَتَله عبدُ العزيز بن الحَجَّاج، ف"},{"id":463,"era":"c2","t":"تتابع الثَوَرات على مَرْوان بن محمَّد وبَنِي أُميَّة .","s":"في هذه السَّنَة ثارَ بعضُ اليَمانِيَّة على مَرْوان بن محمَّد في حِمص وتَدمُر وكذلك في فِلَسطين، فقام بإرسالِ مَن يَقمَعُهم مُستَعينًا بالقَيْسِيَّة، كما خَرَج في الكوفَة عبدُ الله بن مُعاوِيَة الطَّالِبي على بَنِي أُميَّة وبايَعَه بعضُ أَصحابِه ثمَّ هَرَب معهم إلى حلوان وغَلَب على الرَّيِّ وأَصبَهان وهَمدان، وفي الأندَلُس ثارَ بعضُ القَيْسِيَّة بقِيادَة ثَوابَة بن سَلامَة الذي تَولَّى بعدُ إِمارةَ"},{"id":464,"era":"c2","t":"وَفاةُ عاصِم بن أبي النُّجودِ أَحَدُ القُرَّاء السَّبعَة  .","s":"هو عاصِمُ بن بَهْدَلَة أبي النُّجودِ، أَحَدُ القُرَّاء السَّبعَة، وهو مِن صِغارِ التَّابعين، لَقِيَ عاصِمٌ بعضَ صَحابَة رَسولِ الله صلَّى الله عليه وسلَّم وأَخَذ عنهم، كالحارِث بن حَسَّان البَكري الذُّهلي رضي الله عنه، ورِفاعَة بن يَثْرِبي التَّميمي رضي الله عنه، انتَهَت إليه رِئاسَةُ الإقْراء بالكوفَة بعدَ أبي عبدِ الرَّحمن السُّلَمي في مَوضِعه، جَمَع بين الفَصاحَة والإتقانَ والتَّحريرَ والتَّجوي"},{"id":465,"era":"c2","t":"خَلْعُ أبي الخَطَّار أَميرِ الأندَلُس .","s":"كان سَببُ ذلك أنَّه لمَّا قَدِمَ الأندَلُس أَميرًا أَظهَر العَصبِيَّة لليَمانِيَّة على المُضَرِيَّة، فاتَّفَق في بعضِ الأيَّام أنَّه اختَصَم رَجلٌ مِن كِنانَة ورَجلٌ مِن غَسَّان، فاسْتَعان الكِنانيُّ بالصُّمَيلِ بن حاتِم بن ذي الجَوْشَن الضَّبابي، فكلَّم فيه أبا الخطَّار، فاسْتَغلَظ له أبو الخطَّار، فأجابه الصُّمَيل، فأُمِرَ به فأُقِيمَ وضُرِب قَفاهُ، فمالَت عِمامتُه، فلمَّا خرَج قِيلَ له: نَرَى ع"},{"id":466,"era":"c2","t":"وَفاةُ الجَهْم بن صَفوان رَأس الجَهْمِيَّة .","s":"هو أبو مُحْرِز الجَهْم بن صَفوان التِّرمذي مِن مَوالي بَنِي راسِب, نَشأَ الجَهمُ في سَمرقَند وقَضى فَترةً مِن حَياتِه في تِرمِذ، كان بارِعًا في عِلْم الكلام, ثمَّ انتَقَل إلى الكوفَة وبها الْتَقى بالجَعْدِ بن دِرهَم ومنه أخَذ مَقالَة التَّعطيل، والجَبْر، وفَناء الجَنَّة والنَّار، ونَفْي الصِّفات، وأنَّ الإيمان هو مُجرَّد المَعرِفة ثمَّ القول بخَلْق القُرآن، واشْتهَر الجَهمِيَّة بِنَفْي الصِّفات عن"},{"id":467,"era":"c2","t":"بَداية الدَّعوَة العَبَّاسِيَّة في خُراسان .","s":"في هذه السَّنَة وَجَّه إِبراهيمُ بن محمَّدِ بن عَلِيِّ بن عبدِ الله بن عَبَّاس الإمامُ أبا مُسلِم الخُراساني، واسمُه عبدُ الرَّحمن بن مُسلِم، إلى خُراسان، وعُمُره تِسع عَشرة سَنَة، وكتَبَ إلى أَصحابِه: إنِّي قد أَمَّرتُه بأَمري فاسمعوا له وأَطيعوا، فإنِّي قد أَمَّرتُه على خُراسان وما غَلَب عليه بعدَ ذلك. فأتاهم، فلم يَقبَلوا قوله وخَرَجوا مِن قابِل فالْتَقوا بمكَّة عند إبراهيم، فأَعلَمَه أبو مُسلِ"},{"id":468,"era":"c2","t":"أبو مُسلِم الخُراساني يُجاهِر بالدَّعوة العَبَّاسِيَّة .","s":"طلَب إبراهيمُ بن محمَّد بن عَلِيِّ بن عبدِ الله بن عَبَّاس مِن أبي مُسلِم أن يَحضُر إليه إلى مَكَّة لِيَعلَم منه أَخبارَ الدَّعوة، فجاءَه كِتابٌ منه أن يَرجِع إلى خُراسان ويُعلِن بالدَّعوة بعد أن كانت سِرِّيَّة، فأَظهَر أبو مُسلِم الدَّعوة وطلَب مِن سُليمان بن كَثير أن يُصلِّي بالنَّاس العيد، فأَرسَل إليهم نَصرُ بن سِيار قُوَّةً؛ ولكنَّ جُندَ أبي مُسلِم كانوا قد اسْتولَوا على هَراة، وكُشِفَ أمرُ إ"},{"id":469,"era":"c2","t":"اسْتِيلاءُ الخَوارِج على صَنعاء ومَكَّة والمَدينَة .","s":"خَرَج بِحَضرمَوت طالبُ الحَقِّ عبدُ الله بن يحيى الكِندي إمامُ الإباضِيَّة؛ تَغلَّب عليها واجْتَمع عليه الإباضِيَّةُ. ثمَّ سار إلى صَنعاء وبها القاسِمُ بن عُمَر الثَّقفي فوقَع بينهم قِتالٌ كَثيرٌ، انْتَصر فيه طالبُ الحَقِّ وهَرَب القاسِمُ وقُتِلَ أخوه الصَّلْتُ، واسْتَولى طالبُ الحَقِّ على صَنعاء وأَعمالَها، ثمَّ جَهَّز إلى مَكَّة عشرةَ آلاف وبها عبدُ الواحد بن سُليمان بن عبدِ الملك بن مَرْوان فغَ"},{"id":470,"era":"c2","t":"وَفاةُ نَصرِ بن سِيار وتَمَكُّن أبي مُسلِم الخُرساني مِن بِلادِ خُراسان .","s":"هو الأمير أبو الليث نصر بن سيار المروزي, نائب مَرْوان بن محمَّد صاحب خراسان, خرج عليه أبو مسلم الخرساني صاحب الدعوة العباسية، وحاربه, فعجز عنه نصر, واستصرخ بمَرْوان غير مرة لكن مَرْوان عجز نجدته لاشتغاله باختلال أمر أذربيجان والجزيرة, فتقهقر نصر, وجاءه الموت على حاجة, فتُوفِّي بساوة, وقد ولي إمرة خراسان عشر سنين. وكان من رجال الدهر سؤددا وكفاءة."},{"id":471,"era":"c2","t":"وَفاةُ واصِل بن عَطاء رَأس المُعْتَزِلَة .","s":"هو أبو حُذيفَة واصِلُ بن عَطاء المَخزومي، كان تِلميذًا للحَسَن البَصري، سُمِّيَ هو وأَصحابُه بالمُعتَزِلَة لاعْتِزالِهم مَجلِس الحَسَن البَصري، وذلك بِسَببِ مَسألَة مُرتَكِب الكَبيرة، فالحَسنُ يقول بأنَّه لا يَزالُ مُؤمِنًا ولكنَّه فاسِق. فخالَفَه واصِل ومعه عَمرُو بن عُبيد فقال: فاسِق لكنَّه غيرُ مُؤمِن فهو في مَنزِلَة بين المَنزِلَتين وهو مع ذلك مُخَلَّد في النَّار إن مات على كَبيرَتِه، ثمَّ تَط"},{"id":472,"era":"c2","t":"العَبَّاسِيُّون يُسَيطِرون على العِراق .","s":"كان إبراهيمُ بن محمَّدِ بن عَلِيٍّ زَعيمُ الدَّعوة العَبَّاسِيَّة قد سَجنَه مَرْوانُ ثمَّ قَتلَه، واخْتُلِف في كَيفيَّة ذلك، ثمَّ استَلَم بعدَه أَخوهُ المُلَقَّب بالسَّفَّاح عبدُ الله أبو العَبَّاس الذي تَوجَّه إلى الكوفَة فبُويِعَ له بالخِلافَة، وكانت خُراسان قد أُخْضِعَت أصلًا سابِقًا للعبَّاسِيِّين."},{"id":473,"era":"c2","t":"خُروجُ أبي محمَّد السُّفياني على العَبَّاسِيِّين .","s":"تَراسَل أَهلُ قِنِّسرين مع أَهلِ حِمص وتَزمَّروا واجْتَمَعوا على أبي محمَّد السُّفياني، وهو أبو محمَّد زِيادُ بن عبدِ الله بن يَزيد بن مُعاوِيَة بن أبي سُفيان، فبايَعوه بالخِلافَة، وقام معه نحو مِن أربعين ألفًا فقَصَدهم عبدُ الله بن عَلِيٍّ فالْتقَوا بمَرْج الأخرم، فاقْتَتَلوا مع مُقدِّمَة السُّفياني وعليها أبو الوَرْدِ فاقْتَتَلوا قِتالًا شَديدًا وهَزَموا عبدَ الصَّمد وقُتِلَ مِن الفَريقين أُلوف،"},{"id":474,"era":"c2","t":"بداية حكم أبي العباس السفاح أول خلفاء الدولة العباسية .","s":"بعد أن هُزِمَ مَروان بن محمد ومن معه في معركةِ الزاب وهرب، وكان إبراهيم بن محمد قد قُتِلَ، فكان بعده أخوه عبد الله أبو العبَّاس السفَّاح، فبايعه الناسُ في الكوفة، فكان أوَّلَ خُلَفاءِ بني العباس، وبه افتُتِح عصرُ الدولةِ العباسيَّة."},{"id":475,"era":"c2","t":"مَعركَة نَهرِ الزَّاب الأعلى وهَزيمَة الأُمَويِّين أمامَ العَبَّاسِيِّين .","s":"كان أَمرُ الدَّعوة العَبَّاسِيَّة قد اسْتَفحَل خِلالَ السَّنوات الماضِيَة وقَوِيَ أَمرُها جِدًّا في خُراسان وما حولها، حتَّى بَدأَت البُعوثُ تَسيرُ إلى العِراق فخَرَج مَرْوان بن محمَّد بِجَيشٍ إليهم مِن حَرَّان حتَّى بلَغ الزَّاب وحَفَر خَندقًا وكان في عِشرين ومائة ألف، وسار أبو عَوْن وهو القادِمُ إلى العِراق للدَّعوة العَبَّاسِيَّة إلى الزَّاب، فوَجَّه أبو سَلمَة إلى أبي عَوْن عُيينَة بن موسى، وا"},{"id":476,"era":"c2","t":"مَصرَعُ مَرْوان بن محمَّد آخِر خُلَفاء بَنِي أُمَيَّة وانْدِثارُ الدَّولة الأُمويَّة .","s":"لمَّا انْهزَم مَرْوانُ وجَيشُه في الزَّاب هَرَب إلى حَرَّان فمَكَث فيها قَليلًا ثمَّ هَرَب إلى مِصرَ عن طَريقِ حِمص ثمَّ دِمَشق ثمَّ فِلَسطين فتَبِعَه العَبَّاسِيُّون حتَّى قَتلَوه في كَنيسَة أبي صير، فكان آخِرَ خُلَفاء بَنِي أُميَّة وبِمَقْتَلِه انْتَهَت الدَّولةُ الأُمويَّة ويَبدأُ عَهْدُ الدَّولة العَبَّاسِيَّة."},{"id":477,"era":"c2","t":"وَفاةُ مَرْوان بن محمَّد آخِر خُلَفاء بَنِي أُميَّة .","s":"هو مَرْوانُ بن محمَّد بن مَرْوان بن الحَكَم بن أبي العاص بن أُميَّة، القُرَشي الأُمَوي (مَرْوان الحِمار) أبو عبدِ الملك، أَميرُ المؤمنين، آخِرُ خُلَفاء بَنِي أُميَّة، بُويِعَ له بالخِلافَة بعدَ قَتلِ الوَليدِ بن يَزيد، وبعدَ مَوتِ يَزيد بن الوَليد ثمَّ قَدِمَ دِمَشق، وخَلَع إبراهيمَ بن الوَليد، واسْتَتَبَّ له الأَمرُ في صَفَر سَنَة سَبعٍ وعِشرين ومائة, وكان يُقالُ له: مَرْوان الجَعْدي، نِسبَةً إلى"},{"id":478,"era":"c2","t":"العباسيون يبنون مدينة العسكر عاصمة لمصر .","s":"لَمَّا قَدِمَ صالح بن علي العباسيُّ وأبو عون بجموعِهما إلى مصر في طلَبِ مروان بن محمد نزَلَت عساكرُهما الصَّحراءَ جنبَ جبل يشكُر، الذي هو الآنَ جامِعُ أحمدَ بنِ طولون، وكان فَضاءً. فلمَّا رأى أبو عون ذلك أمَرَ أصحابَه بالبناءِ فيه، فبَنَوا وبنى هو به أيضًا دارَ الإمارة، ومسجِدًا عُرِفَ بجامع العَسكر. وعَمِلَت الشرطةُ أيضًا في العسكر، وقيل لها: الشرطةُ العليا، فأصبَحَت كالعاصمةِ لمصرَ؛ لأنَّه قد صا"},{"id":479,"era":"c2","t":"دخول قسطنطين مَلِكُ الروم إلى ملطية .","s":"أقبل قُسطنطين- مَلِكُ الروم- إلى ملطية وكمخ، فنازل كمخ، فأرسَلَ أهلُها إلى أهل ملطية يستنجدونَهم، فسار إليهم منها ثمانمئة مقاتل، فقاتلهم الرومُ، فانهزم المسلمون، ونازل الرومُ ملطيةَ وحصَروها، والجزيرةُ يومئذ مفتونةٌ بالحروب الداخلية، وعامِلُها موسى بن كعب بحران. فأرسل قسطنطين إلى أهل ملطية: إنِّي لم أحصُرْكم إلَّا على عِلمٍ مِن المسلمين واختلافِهم، فلكم الأمانُ وتعودون إلى بلاد المسلمينَ حتى أحتَر"},{"id":480,"era":"c2","t":"غزو أبي داود خالد بن إبراهيم كش .","s":"غزا أبو داود خالدُ بن إبراهيم أهلَ كش، فقتل الأخريدَ ملكَها، وهو سامِعٌ مطيع، وقتل أصحابَه وأخذ منهم من الأواني الصينيَّة المنقوشة المذَهَّبة ما لم يُرَ مثلُها، ومن السُّروجِ ومتاع الصين كلِّه من الديباج والطرفِ شَيئًا كثيرًا فحمَلَه إلى أبي مسلم وهو بسمرقند، وقتَل عدَّةً مِن دهاقينِهم، واستحيا طاران أخا الأخريدِ ومَلكه على كش, ثم رجع أبو داود إلى بلخ."},{"id":481,"era":"c2","t":"أمر أبي مسلم الخرساني بناء سور سمرقند .","s":"أمرَ أبو مسلم الخرساني ببناء سور سمرقند، بعد انصرافه من سمرقند وفتكه بأهل الصغد وبخارى؛ واستخلف زيادَ بن صالح على سمرقند وبخارى"},{"id":482,"era":"c2","t":"عبد الله بن حبيب يغزو جزيرة صقلية .","s":"غزا عبد الله بن حبيبٍ جزيرةَ صقليَّة وغنم بها وسبى وظفَرَ بها ما لم يظفَرْه أحد قبله بعد أن غزا تلمسان."},{"id":483,"era":"c2","t":"تحصين الروم لصقلية وعدوانهم منها على المسلمين  .","s":"لما اشتغل ولاةُ إفريقية بالفتنةِ مع البربر، أمَّن الروم في صقليَّة فعمَرَوها من جميع الجهاتِ وعَمَروا فيها الحصونَ والمعاقِلَ، وصاروا يُخرجون كلَّ عامٍ مراكِبَ تطوف بالجزيرةِ وتذُبُّ عنها، وربما طارقوا تجَّارًا من المسلمين فيأخذونَهم."},{"id":484,"era":"c2","t":"وفاة ربيعة الرأي .","s":"هو الإمام، الفقيه الحافِظٌ، عالم الوقت، أبو عثمان ويقال: أبو عبد الرحمن ربيعةُ بنُ أبي عبد الرحمن فروخ القرشي، التيمي مولاهم، المشهور بربيعة الرأي، من موالي آل المنكدر. أحد أئمة الاجتهاد ومن أوعية العلم. أدرك جماعة من الصحابة رضي الله عنهم, وروى عن أنسِ بن مالكٍ، وعن كثير من التابعين، كان بصيرًا بالرأي، حتى لُقِّبَ بهذا اللقب، عليه تفقَّه الإمام مالك، كان صاحِبَ الفتوى في المدينة، وكان صاحِبَ اجته"},{"id":485,"era":"c2","t":"وفاة الخليفة العباسي أبي عبد الله السفاح .","s":"هو الخليفة أبو العباس عبدُ الله السَّفَّاح بن محمد الإمام بن علي السجاد بن عبد الله الحبر بن العباس، القرشيُّ الهاشمي أمير المؤمنين، وهو أول خلفاء العباسيين. ولِد السَّفاح سنة 105 بالحميمة ونشأ به وهي من أرض الشراة من أرض البلقاء بالشام. كان السَّفاح شابا، مليحا، مهيبا، أبيض، طويلا، وقورا. هرب أبو العباس مع أهله من جيش مروان الحمار، وأتوا الكوفة لما استفحل لهم الأمر بخراسان. حتى طُلِب أخوه إبراهيم"},{"id":486,"era":"c2","t":"أبو جعفر المنصور يَتَوَلَّى الخلافة العباسية .","s":"عقد السَّفَّاح عبدُ الله بن محمد بن علي بن عبد الله بن عباس لأخيه أبي جعفرٍ عبدِ الله بن محمَّد بالخلافة مِن بعدِه، وجعله وليَّ عهد المسلمين، ومِن بعد أبي جعفرٍ ولد أخيه عيسى بن موسى بن محمد بن علي، وجعل العهدَ في ثوبٍ وخَتَمه بخاتمه وخواتيمِ أهل بيته، ودفعه إلى عيسى بن موسى. فلما توفي السفَّاح كان أبو جعفر بمكَّة، فأخذ البيعةَ لأبي جعفرٍ عيسى بن موسى، وكتب إليه يُعلِمُه وفاة َالسفَّاح والبيعةَ له"},{"id":487,"era":"c2","t":"ثورة عبد الله بن علي على ابن أخيه المنصور .","s":"كان عبد الله بن علي في الصائفة في الجنود حين مات السفَّاح، وكان المنصور يخشى أن يثورَ عليه، ولَمَّا وصل الكتاب إلى عبد الله بموت السفَّاح وهو في الصائفة دعا لنفسه، وذلك أنَّه قال: إنَّ السفاحَ لَمَّا أراد قتلَ مروان انتدب الناسَ من يقتُلُه من أهل بيته- يعني بيت العباسيين- فإنَّه يكونُ وليَّ عَهدِه، فانتدب لذلك عبد الله، فهو الأحق بالأمر من المنصورِ، فبايعه بعضُ قوَّاده، فسار إلى الكوفة وحاصرها أرب"},{"id":488,"era":"c2","t":"قتل المنصور الأمير أبا مسلم الخراساني .","s":"هو الأمير أبو مسلم عبد الرحمن بن مسلم بن عثمان بن يسار، بن شذوس بن جودرن من ولد بزرجمهر بن البختكان الخراساني الفارسي صاحب الدعوة، وهازم جيوش الدولة الأموية، والقائم بإنشاء الدولة العباسية. وقيل كان اسمه إبراهيم بن عثمان بن يسار غيره بطلب من الإمام إبراهيم بن محمد لمزيد من التخفي. قال الذهبي: \"كان أبو مسلم من أكبر الملوك في الإسلام، كان ذا شأن عجيب، ونبأ غريب، من رجل يذهب على حمار بإكاف من الشام ح"},{"id":489,"era":"c2","t":"دخول ملك الروم ملطية عنوة .","s":"خرجَ قُسطنطين ملكُ الروم إلى بلد الإسلامِ، فدخل ملطية عَنوةً وقهرًا، وغلَب أهلَها، وهدَمَ سُورَها، وعفا عمَّن فيها من المُقاتِلة والذرِّيَّة."},{"id":490,"era":"c2","t":"مبايعة عبد الله بن علي للخلافة .","s":"بعد أن انهزم عبد الله بن علي (عمُّ المنصور) على يدِ أبي مسلم، وبقي في البصرة، قام بالدعوة لنفسِه، وبويع، ولكن لم يتمَّ له شيءٌ، فاستجار بأخيه سليمان الذي كان أميرًا للبصرة، ثم إنه بقي كذلك حتى أظهر الطاعةَ للمنصور، ثم عزل المنصور عمَّه سليمان عن إمرة البصرة، فاختفى عبد الله بن عليٍّ وأصحابُه خوفًا على أنفسهم، فبعث المنصورُ إلى نائبه على البصرة، وهو سفيان بن معاوية، يستحِثُّه في إحضار عبد الله بن ع"},{"id":491,"era":"c2","t":"ذكر الفتنة في الأندلس .","s":"خرج في الأندلس الحُباب بن رواحة بن عبد الله الزهري ودعا إلى نفسِه، واجتمع إليه جمعٌ من اليمانية، فسار إلى الصميل، وهو أمير قرطبة، فحصره بها وضيَّق عليه، فاستمد الصميلُ يوسفَ الفهريَّ أمير الأندلس، فلم يفعَلْ لتوالي الغلاءِ والجوع على الأندلس، ولأنَّ يوسُفَ قد كره الصميل واختار هلاكَه ليستريحَ منه. وثار بها أيضًا عامر العبدري وجمع جمعًا واجتمعَ مع الحباب على الصميل، وقاما بدعوة بني العباس. فلما اشت"},{"id":492,"era":"c2","t":"عبد الرحمن الداخل يؤسس الدولة الأموية بالأندلس .","s":"كان عبد الرحمن بن معاوية قد انتقل إلى بلاد المغرب؛ فرارًا من عبد الله بن عليِّ بن عبد الله بن عباس، فاجتاز بمن معه من أصحابِه الذين فرُّوا معه بقومٍ يقتتلون على عصبيَّة اليمانية والمُضَرية، فبعث مولاه بدرًا إليهم فاستمالهم إليه، فبايعوه ودخل بهم ففتح بلادَ الأندلس واستحوذ عليها، وانتزعها من يوسف بن عبد الرحمن الفهري آخر ولاة بني أمية في الأندلس، والذي جمع جيشًا فيما بعد، وأعلن العصيانَ وأراد غزو ق"},{"id":493,"era":"c2","t":"استعادة العباسيين مقاطعة ملطية من البيزنطيين .","s":"غزا العبَّاسُ بن محمد بن علي بن عبد الله بن عباس الصائفةَ مع صالحِ بنِ علي وعيسى بن علي، وبنوا ما أخربه الرومُ مِن ملطية، ثم غزَوا الصائفةَ من درب الحدثِ، فتوغلوا في أرض الروم، وغزا مع صالحٍ أختاه أم عيسى ولبابة بنتا علي، وكانتا نذَرَتا إن زال مُلكُ بني أميَّة أن تجاهِدا في سبيل الله، وغزا من درب ملطية جعفرُ بن حنظلة المرهاني، وفي هذه السَّنة كان الفداءُ بين المنصور وملك الروم، فاستفدى المنصورُ أس"},{"id":494,"era":"c2","t":"أبو جعفر المنصور يبدأ بتوسيع المسجد الحرام .","s":"كانت هذه السنةُ خِصبةً جِدًّا، حتى سُمِّيَت سنةَ الخِصبِ، وكان فيها توسيعُ المسجدِ الحرامِ مِن قِبَلِ المنصورِ، فزاد في شِقِّه الشامي الذي فيه دارُ النخلة ودارُ الندوة في أسفله، ولم يزِدْ عليه في أعلاه ولا في شِقِّه الذي على الوادي، فاشترى من النَّاسِ دُورَهم الملاصِقةَ بالمسجدِ مِن أسفَلِه، فزاده فيه."},{"id":495,"era":"c2","t":"بداية تأسيس الدولة الرستمية (الإباضية) .","s":"كان قد هرب الكثيرُ من أهلِ القيروان لِمَا لاقوا مِن ظُلم عبد الملك بن أبي الجعد الورفجومي وأتباعه، فلجأ الهاربون إلى أبي الخطَّاب عبد الأعلى بن السَّمح، فبايعوه وكثُرَ أتباعُهم، فاستولى على طرابلس، ثم سار إلى قابس فأخذها، واتجه إلى القيروان فالتقى بعبد الملك فهزمه وقتَلَه، واستولى على القيروان وولَّى عليها عبد الرحمن بن رستم الإباضي."},{"id":496,"era":"c2","t":"الخوارج الصفارية يبنون مدينة سلجماسة بالمغرب الأقصى .","s":"استطاع عاصِمُ بن جميل أن يهزِمَ حبيبَ بن عبد الرحمن الفهري، فدخل القيروان وولَّى عليها عبد الملك بن أبي الجعد، وسار هو خلفَ حبيب حتى قتلَه فأصبح للصفرية نفوذُهم الكبير في المغرب، ثم لما انهزموا أمام الإباضيَّة اتجهوا نحو المغرب الأقصى والأوسط، واستطاع أبو قرةَ تأسيسَ دولةٍ في ناحية تلمسان، كما استطاع أبو القاسِمِ سِمكو بن واسول إرساءَ قواعِدِ دولةِ بني مدرارٍ في سجلماسة."},{"id":497,"era":"c2","t":"يوم الروانديَّة (الروانديَّة) .","s":"الروانديَّةُ أو الروانديَّة أصلُهم من خراسان، وهم على رأي أبي مسلمٍ الخراساني، كانوا يقولونَ بالتناسُخِ، ويزعمونَ أنَّ روح آدم انتقَلَت إلى عثمان بن نهيك، وأنَّ رَبَّهم الذي يُطعِمُهم ويسقيهم أبو جعفرٍ المنصور. وأنَّ الهيثم بن معاوية جبريل- قبَّحَهم الله- فأتَوا يومًا قصر المنصور فجعلوا يطوفونَ به، ويقولون: هذا قصر ربنا، فأرسل المنصورُ إلى رؤسائهم، فحبس منهم مئتين، فغَضِبوا من ذلك ودخَلوا السجن قه"},{"id":498,"era":"c2","t":"بناء المنصور المصيصة .","s":"لما رجع أبو جعفر المنصور من الحج مر بالمدينة، ثم توجه إلى بيت المقدس، فصلى في مسجدها، ثم سلك إلى الشام منصرفا حتى انتهى إلى الرقة فنزلها، وكتب إلى صالح بن علي يأمره ببناء المصيصة، ثم خرج منها إلى ناحية الكوفة، فنزل المدينة الهاشمية بالكوفة، وقد فرغ بناءُ المصيصة على يدَي جبريلَ بنِ يحيى الخراساني."},{"id":499,"era":"c2","t":"فتح طبرستان .","s":"كتب المنصورُ إلى ابنه المهدي أن يغزوَ طبرستان، وأن يوجِّهَ أبا الخصيب وخازم بن خزيمة والجنودَ إلى الأصبهبذ، وكان الأصبهبذ يومئذٍ محاربًا للمصمغان، ملك دنباوند، فتحالفا ضدَّ المُسلمين، فانصرف الأصبهبذ إلى بلادِه فحارب المسلمين، فطالت تلك الحروبُ، فوجه المنصورُ عمرَ بن العلاء إلى طبرستان وكان عالِمًا ببلاد طبرستان، فأخذ الجنودَ وقصد الرويان وفتَحَها، وأخذ قلعةَ الطاق وما فيها، وطالت الحربُ، فألحَّ خ"},{"id":500,"era":"c2","t":"وفاة عمرو بن عبيد شيخ المعتزلة .","s":"هو عمرو بنُ عُبيد بن باب التميميُّ ولاءً، من أهل ِالبصرةِ، شيخ المعتزلة في زمانه، اشتُهِر بزهده، أخذ عن واصل بن عطاءٍ، واعتزل معه مجلسَ الحسَن البصريِّ، قال يحيى بن معين: \"كان من الدَّهرية الذين يقولونَ إنما الناسُ مِثلُ الزرع\"، وقال ابن المبارك: \"دعا إلى القدَرِ فتركوه\"، قال ابن عُلية: \"أوَّلُ من تكلَّم في الاعتزالِ واصِلُ الغزَّال، فدخل معه عمرو بنُ عُبيد، فأُعجِبَ به وزوَّجَه أختَه\"، وله كتابُ "},{"id":501,"era":"c2","t":"غزو الديلم .","s":"بلغ أبا جعفر المنصور ما فعله الدَّيلمُ بالمسلمين وقتْلُهم منهم مقتلةً عظيمةً، فوجَّه إلى البصرة حبيبَ بن عبد الله بن رغبان، وعليها يومئذ إسماعيلُ بن عليٍّ، وأمره بإحصاءِ كلِّ مَن له فيها عشرةُ آلاف درهم فصاعدًا، وأن يأخُذَ كلَّ من كان ذلك له بالشُّخوصِ بنَفسِه لجهاد الدَّيلم، ووجَّه آخر لمثل ذلك إلى الكوفة. ثم سيَّرَ أبو جعفر النَّاسَ من الكوفة والبصرة والجزيرة والموصل إلى غزو الديلم، واستعمل عليه"},{"id":502,"era":"c2","t":"بداية تأسيس الدولة الرستمية (الإباضية) .","s":"كان عبد الرحمن بن رستم من مُسلِمة الفتح الإسلامي، وهو من ولَدِ رستم أمير الفرس بالقادسية، قَدِم إلى إفريقية مع طوالعِ الفتح فكان بها. وأخذَ بدِين الخارجيَّة والإباضية منهم، تحزَّبَ الإباضية بناحية طرابلس واجتمعوا إلى ابنِ الخطاب عبد الأعلى بن السمح المغافري إمامِ الإباضية، فملكوا طرابلس، ثم ملَكوا القيروان، وقتَلوا واليَها من ورفجومة عبد الملك بن أبي الجعد، وأثخَنوا في ورفجومة وسائر مغراوة, ثم رجع"},{"id":503,"era":"c2","t":"المنصور يعتقل عبدالله بن حسن والد محمد النفس الزكية .","s":"لَمَّا قَدِمَ المنصورُ لموسم الحجِّ واجتمع بعبدِ الله بن حسن، ولم يكن ولداه قد قَدِما معه إليه، فغَضِبَ المنصور من عبد الله لَمَّا لم يُعلِمْه بمكانِ ولديه فأخذه معه إلى الكوفة هو وبعض أقاربه مُقَيَّدينَ، وحبَسَهم هناك في حبسٍ سيئ، هلك فيه بعضُهم، وقُتِل البعضُ. وأمَّا عبد الله بن حسن فإنه توفِّي في السجن بعد مقتل ولده محمد بالمدينة, وقيل إنَّه قُتِلَ في السجنِ عمدًا؛ حيث كان محبوسًا في سرداب، فقي"},{"id":504,"era":"c2","t":"ثورة السودان العبيد بالمدينة .","s":"كان على المدينةِ عبد الله بن الربيع مِن قِبَل المنصور، وكان جندُه قد استفحل أمرُهم مع التجَّار بالظُّلم، فكانوا يأخذون ما شاءوا بدون ثمنٍ أحيانًا، وكل ذلك وابن الربيع لا يغيِّرُ شيئًا ولا يكلِّمُ جندَه، فاستفحل أمرُهم حتى كان يومُ جمعة قتَلَ أحدُ الجزَّارين جنديًّا، ثم تنادى الجندُ وتنادى السودان (العبيد) ونفخوا في بوقٍ لهم، فلم يبقَ في المدينة أسودُ إلَّا جاء، وتأمر عليهم وثيق الزنجي، فثاروا على "},{"id":505,"era":"c2","t":"حركة محمد النفس الزكية .","s":"كان المنصورُ قد حَبَس عبدَ الله بن الحسن والدَ محمد النفس الزكية، وكان همُّ المنصورِ هو الظفَرَ بمحمَّدٍ - الذي كان متخفيًا في المدينة- وأخيه إبراهيمَ، وذلك أنَّهما تخلَّفا عن الحضور إليه في موسم الحج, وعِلْمه بسعيهما للوصول لأمر ِالخلافة منذ أيَّام بني أمية؛ بقصد إزالة المخالفاتِ الشَّرعية والظُّلم الذي وقع من الولاة والأمراء, فخاف مِن أمرِهما، ثمَّ إنَّ محمدًا دعا للبيعةِ لنفسه واستولى على مقالي"},{"id":506,"era":"c2","t":"خروج إبراهيم بن عبدالله (أخو محمد النفس الزكية) بالبصرة  .","s":"لَمَّا قام محمد بالمدينة ودعا لنفسه خرج أخوه إبراهيم في البصرة ودعا للبيعة، وقوِيَ أمره ثم غلبَ عليها وبايعه أهلُ الأهواز كذلك واستحوذَ على البلاد، وبعث إبراهيم إلى بلاد فارس فأخَذَها، وكذلك واسِط والمدائن والسَّواد، واستفحل أمرُه جدًّا، ولكنْ لَمَّا جاءه نعيُ أخيه محمد انكسر جدًّا، ثم إنَّ المنصورَ استدعى عيسى بن موسى وجيشَه وسيَّرَه لقتال إبراهيم حتى هزمه في موقعة باخمرا، وقُتِلَ إبراهيمُ كذلك و"},{"id":507,"era":"c2","t":"هزيمة حملة العلاء بن مغيث ضد الأمويين بالأندلس .","s":"سار العلاء بن مغيث اليحصبي من إفريقيَّة إلى مدينة باجة من الأندلس، ولَبِسَ السَّواد, وخطبَ للمنصور، واجتمع إليه خلقٌ كثيرٌ، فخرج إليه الأميرُ عبد الرحمن الداخل، فالتقيا بنواحي إشبيلية، ثم تحارَبا أيامًا، فانهزم العلاء وأصحابُه، وقُتِل منهم في المعركة سبعةُ آلاف، وقُتِل العلاء، وأُمِرَ بعضُ التجار بحمل رأسه ورؤوسِ جماعةٍ مِن مشاهير أصحابه إلى القيروان، وإلقائِها بالسوق سرًّا، ففعل ذلك، ثم حُمِلَ من"},{"id":508,"era":"c2","t":"بناء بغداد واتخاذها عاصمة للدولة العباسية .","s":"في هذا العام تكاملَ بناءُ بغداد، وكان السببُ الباعث للمنصور على بنائها أنَّ الراونديَّة لَمَّا وثبوا عليه بالكوفةِ ووقاه اللهُ شَرَّهم، بَقِيَت منهم بقيَّةٌ فخشيَ على جندِه منهم، فخرج من الكوفةِ يرتادُ لهم موضعًا لبناء مدينة، فسار في الأرض حتى بلغ الجزيرةَ، فلم يرَ موضعًا أحسنَ لوضعِ المدينة من موضعِ بغدادَ الذي هي فيه الآن؛ وذلك بأنه موضِعٌ يُغدى إليه ويُراحُ بخيراتِ ما حوله في البَرِّ والبحر، وه"},{"id":509,"era":"c2","t":"غارات أسترخان الخوارزمي في جمع من الترك على المسلمين .","s":"فيها أغار أسترخان الخوارزمي في جمعٍ من التُّرك على المسلمين بناحية أرمينية، وسبى من المسلمين وأهلِ الذمَّة خلقًا، ودخلوا تفليس، وكان حربُ بن عبد الله مقيمًا بالموصِل في ألفينِ مِن الجند لمكان الخوارجِ الذين بالجزيرة، وسيَّرَ المنصور إلى محارَبة التُّرك جبرائيلَ بن يحيى وحَربَ بنَ عبد الله، فقاتلوهم، فهُزم جبرائيلُ وقُتِلَ حَربٌ، وقُتِل من أصحاب جبرائيلَ خلقٌ كثيرٌ."},{"id":510,"era":"c2","t":"خروج حسان بن مجالد الهمداني على المنصور في الموصل .","s":"خرج حسان بن مجالد بن يحيى بن مالك بن الأجدع الهمداني، وكان خروجُه بنواحي الموصِل بقريةٍ تُسمَّى بَافَخَّارى، قريب من الموصل على دجلة، فخرج إليه عسكرُ الموصِل، وعليها الصقر بن نجدة، فالتقَوا واقتَتلوا وانهزم عسكرُ الموصِل على الجِسر، وأحرق الخوارجُ أصحابُ حسَّان السوقَ هناك ونهبوه. ثم إنَّ حسانَ سار إلى الرقَّةِ ومنها إلى البحر ودخل إلى بلد السِّند، وكانت الخوارجُ مِن أهل عمان يُدخِلونَهم ويَدَعونه"},{"id":511,"era":"c2","t":"استعادة العباسيين فتح طبرستان .","s":"نكث أصبهبذ طبرستان العهدَ الذي كان بينه وبين المسلمين، وقتلَ طائفةً ممَّن كان بطبرستان، فجهَّز إليه المنصورُ جيشًا بقيادة خازم بن خزيمة، وروحِ بن حاتم، ومعهم مرزوقٌ أبو الخصيب، مولى المنصور، فحاصَروه مدةً طويلة، فلما أعياهم فتحُ الحِصنِ احتالوا عليه، وذلك أنَّ أبا الخصيبِ قال: اضربوني واحلِقوا رأسي ولِحيتي، ففعلوا ذلك، فذهب إليه كأنَّه مُغاضِبٌ للمُسلِمينَ قد ضربوه وحلَقوا لحيتَه، فدخل الحِصنَ، وق"},{"id":512,"era":"c2","t":"ولاية الأغلب بن سالم على إفريقية .","s":"لَمَّا بلغ المنصورَ خروجُ محمد بن الأشعث من إفريقيَّة بعث إلى الأغلب بن سالم بن عقال بن خفاجة التميمي عهدًا بولايةِ إفريقية، وكان هذا الأغلبُ ممَّن قام مع أبي مسلم الخُراساني وقَدِم إفريقيَّةَ مع محمد بن الأشعث، فلما أتاه العهد قَدِم القيروانَ وأخرج جماعةً من قوَّاد المُضَريَّة، وسكن النَّاس. ثم خرج عليه أبو قرَّة في جمع كثير من البربر، فسار إليه الأغلبُ، فهرَبَ أبو قرَّة من غير قتال، ثم خرج عليه "},{"id":513,"era":"c2","t":"وفاة الإمام جعفر الصادق .","s":"هو الإمام، الصَّادق، شيخ بني هاشم، أبو عبدالله جعفرُ بن محمد الباقر بن علي زين العابدين بن الحسين بن علي بن أبي طالب، القرشي، الهاشمي، العلوي، النبوي، المدني، أحد الأعلام من التابعين, وكان يلقَّبُ بالصابر، والفاضِلِ، والطاهر، وأشهرُ ألقابه الصادِقُ، ولد سنة 80, وأمه أم فروة بنت القاسم بن محمد بن أبي بكر الصديق, وأمها: هي أسماء بنت عبد الرحمن بن أبي بكر، ولهذا كان يقول: ولدني أبو بكر الصديق مرتين. "},{"id":514,"era":"c2","t":"خروج الأستاذ سيس (الفارسي) على المنصور في خرسان .","s":"فيها خرج أهل خراسان على المنصور مع الأستاذ سيس حتى اجتمع له فيما قيل ثلاثمئة ألف مقاتل من بين فارس وراجل، سائرُهم من أهل هراة وباذغيس وسجستان، واستولى على أكثر خراسان، وعَظُم الخطبُ فنهض لحربه الأخثم المروروذي. فقتل الأخثم واستُبيح عسكُره، فوجه المنصورُ- وهو بالراذان- خازمَ بن خزيمة إلى المهديِّ، فولَّاه المهدي محاربةَ أستاذ سيس وضمَّ إليه القُوَّاد. فسار حازم بن خزيمة في جيشٍ عظيم فالتقى الجمعان "},{"id":515,"era":"c2","t":"وفاة الإمام أبي حنيفة النعمان .","s":"هو الإمام، فقيه الملة، أبو حنيفة النُّعمانُ بنُ ثابت بن زوطى التيميُّ ولاءً، فقيهُ العراقِ إمامُ الحنفيَّة، أحد الأئمة الأربعة المشهورين أصحاب المذاهب المعروفة، يقال: إنه من أبناء الفرس ولد سنة 80, وكان حسن الوجه حسن المجلس، شديد الكرم حسن المواساة لإخوانه، وكان ربعة من الرجال، وقيل كان طوالا تعلوه سمرة،. أدرك أبو حنيفة أربعة من الصحابة، رضوان الله عليهم وهم: أنس بن مالك وعبد الله بن أبي أوفى بالك"},{"id":516,"era":"c2","t":"أبو جعفر المنصور يبدأ ببناء مدينة الرصافة .","s":"شرع المنصورُ في بناء الرصافة لابنه المهدي بعد مَقدَمِه من خراسان، وكان سبب بنائِها أنَّ بعضَ الجند شغَّبوا على المنصور وحاربوه على باب الذَّهبِ، فدخل عليه قُثَمُ بنُ العبَّاس، وهو شيخُهم، وله الحرمةُ والتقدُّم عندهم، فاستشاره المنصور، فقال له أن يتركَ الأمرَ له، فقام قُثَم بحيلةٍ فافترق الجند، فصارت مُضَرُ فِرقةً، وربيعةُ فرقة، والخراسانية فرقة. فقال قُثَم للمنصور: قد فرَّقتُ بين جُندِك وجعلتُهم أ"},{"id":517,"era":"c2","t":"تجديد البيعة للمنصور ثم ولده المهدي .","s":"جدَّد المنصورُ البيعةَ لنفسه ثمَّ لولده المهدي من بعده، ولعيسى بن موسى مِن بعدهما، وجاء الأمراءُ والخَواصُّ، فبايعوا وجعلوا يقبِّلونَ يد المنصور ويدَ ابنه ويلمسونَ يد عيسى بن موسى ولا يقبِّلونَها."},{"id":518,"era":"c2","t":"خروج شقنا بن عبد الواحد في الأندلس .","s":"ثار في الشرق من الأندلس رجلٌ من بربر مكناسة، كان يعلِّمُ الصبيان، وكان اسمُه شقنا بن عبد الواحد، وكانت أمُّه تُسمى فاطمة، وادَّعى أنَّه من ولد فاطمةَ رَضِيَ الله عنها، ثم مِن ولَد الحُسين بن علي رضي الله عنهما، وتَسمَّى بعبد الله بن محمَّد، وسكن شنت برية، واجتمع عليه خلقٌ كثير من البربر، وعظُمَ أمرُه، وسار إلى عبد الرحمن الداخِل الأموي فلم يقِف له وراغ في الجبالِ، فكان إذا أمِنَ انبسط، وإذا خاف صَ"},{"id":519,"era":"c2","t":"وفاة محمد بن إسحاق صاحب السيرة النبوية .","s":"هو العلامة، الحافظ، الأخباري أبو بكر، وقيل: أبو عبد الله محمد بن إسحاق بن يسار بن خيار, القرشي, المدني, المطَّلِبي ولاءً، العلَّامة, الحافظ, الأخباري, صاحب \"السيرة النبوية\" وُلِدَ ابنُ إسحاق: سنةَ ثمانين. وقيل إنه رأى أنس بن مالك بالمدينة, انتقل من المدينة إلى بغداد وسكنَها، كان من أقدم المؤرخينَ، ومن أشهر مؤلَّفاته السيرةُ النبويَّة، وبها اشتُهِر، قيل: إنه ألَّفها بأمرٍ من المنصورِ، وقال الشافعي:"},{"id":520,"era":"c2","t":"خروج الخوارج الصفرية ببلاد أفريقية .","s":"خرجَت الخوارجُ من الصفريَّة وغيرهم ببلاد إفريقية. فاجتمعَ منهم ثلاثمائة ألف وخمسون ألفًا، ما بين فارس وراجل، وعليهم أبو حاتم الأنماطي، وأبو عبَّاد وانضم إليهم أبو قرة الصفري في أربعين ألفًا، فقاتلوا نائبَ إفريقية فهَزَموا جيشَه وقتلوه، وهو عمَرُ بن حفص بن عثمان بن أبي صفرة الذي كان نائبَ السِّند، قتله هؤلاء الخوارجُ, وأكثرت الخوارجُ الفسادَ في البلاد، وقتلوا الحريمَ والأولاد، ثمَّ إن أبا جعفر المن"},{"id":521,"era":"c2","t":"أبو جعفر المنصورُ يبدأ بزيارة إلى الشامِ وبيتِ المقدس .","s":"سار أبو جعفر المنصورُ الخليفةُ العباسي إلى الشامِ وبيتِ المقدس، وأراد المنصور بناء الرافقة، فمنعه أهلُ الرقَّة، فهَمَّ لمحاربتِهم."},{"id":522,"era":"c2","t":"وفاة أبي عمرو بن العلاء البصري أحد القراء السبعة .","s":"هو شيخ القراء والعربية أبو عمرو العريان وقيل: زَبَّان بن العلاء بن عمار بن العُريان التميمي ثم المازني البصري، أحد القرَّاء السبعة، وُلد بمكة عام 68، وقيل 70, وأمه: من بني حنيفة. ونشأ بالبصرة، أحدُ التابعين، سمع من أنسِ بن مالك. قرأ القرآن على: سعيد بن جبير، ومجاهد، ويحيى بن يعمر، وعكرمة، وابن كثير، وطائفة, وكان من أئمَّة اللغة والأدب، ومن أعلَمِ الناسِ بالقرآن والعربية وأيَّامِ الناس، برز في الحر"},{"id":523,"era":"c2","t":"أمر المنصور ببناء الرافقة وببناء سور وخندق حول الكوفة .","s":"الرافقة مدينة كانت متَّصلة البناء بالرقة، وهما على ضفَّة الفرات، وبينهما مقدار ثلاثمائة ذراع، ثم إن الرقَّة خربت وغلب اسمُها على الرافقة وصار اسمُ المدينة الرقة (وهي الموجودة حاليًّا في سوريا) ففي هذه السَّنة أمرَ الخليفةُ العباسي المنصور ببناء الرافقة، على منوالِ بناء بغداد، فلما أراد أهلُ الرقَّة منْعَه من بنائها همَّ في محاربتِهم. كما أمرَ ببناء سورٍ وعَمَلِ خندقٍ حول الكوفة، وأخذَ ما غَرِمَ عل"},{"id":524,"era":"c2","t":"خروج الخوارج الصفرية على أميرِهم بمدينة سجلماسة .","s":"أنكرت الخوارجُ الصفرية المجتَمِعةُ بمدينة سجلماسة على أميرِهم عيسى بن جرير أشياءَ، فشَدُّوه وِثاقًا، وجعلوه على رأس الجبلِ، فلم يزَلْ كذلك حتى مات، وقَدَّموا على أنفُسِهم أبا القاسم سمكو بن واسول المكناسي جدَّ مدرار."},{"id":525,"era":"c2","t":"ثورة الأرمن الصنارية .","s":"ثار الأرمن الصنارية بزَعامة موشيغ ماميكونيان، وسمباط بن آشوط، وامتنعوا عن دفع الخَراج، فأمدَّ المنصورُ الحسَن بن قحطبة أمير أرمينية بجيشٍ يضُمُّ كبارَ القادة، فالتقى الطرفانِ وجرت معركةٌ قرب جبل أرارات، وعُرِفَت المعركة في التاريخ الأرمني باسم بيغرافند، وفيها تمَّ قمعُ هذه الثورة وقتْلُ موشيغ، ودخلَ جيشُ المسلمين مدينة تفليس."},{"id":526,"era":"c2","t":"فتنة الخوارج في أفريقيا .","s":"هرب عبد الرحمن بن حبيب- الذي كان أبوه أميرَ إفريقية- مع الخوارج، واتَّصل بكتامة، فسيَّرَ يزيد بن حاتم أمير إفريقية العسكرَ في أثَره، وقاتلوا كتامة. فلمَّا كانت هذه السَّنةُ سيَّرَ يزيدُ عسكرًا آخرَ مددًا للذين يقاتلون عبد الرحمن، فاشتد الحصارُ على عبد الرحمن، فمضى هاربًا، وفارقَ مكانَه، فعادت العساكرُ عنه، ثم ثار في هذه السنة على يزيد بن حاتم أبو يحيى بن فانوس الهواري بناحية طرابلس، فاجتمع عليه كث"},{"id":527,"era":"c2","t":"عصيان أهل إشبيلية على عبد الرحمن الداخل .","s":"سار عبد الرحمن الداخل إلى حرب شقنا، وقصدَ حصنَ شيطران، فحصَرَه وضيَّقَ عليه، فهرب إلى المفازة كعادته، وكان قد استخلف على قرطبة ابنَه سُليمان، فأتاه كتابُه يخبِرُه بخروج أهل إشبيلية مع عبد الغفار وحيوة بن ملابس عن طاعتِه، وعصيانِهم عليه، واتَّفَق مَن بها من اليمانية معهما، فرجع عبد الرحمن ولم يدخُل قرطبة، وهاله ما سَمِعَ من اجتماعِهم وكثرتِهم، فقدَّمَ ابنَ عمه عبد الملك بن عمر (كان شهاب آل مروان)، "},{"id":528,"era":"c2","t":"وفاة حمزة الزيات أحد القراء السبعة .","s":"هو الإمام العلم أبو عمارة حمزةُ بن حبيبِ بنِ عمارة التيميُّ المعروف بالزيَّات، ولد سنة 80. قيل له \" الزيات \" لأنه كان يجلب الزيت من الكوفة إلى حلوان, ويجلب إلى الكوفة الجبن والجوز. أصله من سبي فارس، وقيل: ولاؤه لبني عجل، وقيل: ولاؤه لتيم الله بن ثعلبة. أدرك عددًا من الصحابة, أحدُ القراء السبعة، من أهل الكوفةِ، تلا عليه طائفةٌ، منهم الأعمش، وحدَّثَ عنه كثيرٌ، منهم الثوريُّ، كان إمامًا قَيِّمًا لكتا"},{"id":529,"era":"c2","t":"بناء قصر الخلد في بغداد .","s":"بنى المنصور قصرَه المسمَّى بالخُلد في بغداد على شاطئ دجلة، تفاؤلًا بالتَّخليد في الدنيا، فعند كمالِه مات وخرِبَ القَصرُ من بعده، وكان المستحِثُّ في عمارته أبان بن صدقة، والربيع مولى المنصور وهو حاجبُه."},{"id":530,"era":"c2","t":"وفاة الإمام الأوزاعي .","s":"هو إمام أهل الشام أبو عمرو عبد الرحمن بن عمرو بن محمد الأوزاعي، من كبار تابعي التابعين. ولقب بالأوزاعي نسبة إلى الأوزاع وهي فرع من همدان, وقيل الأوزاع قرية بدمشق على طريق باب الفراديس، ولم يكن أبو عمرو منهم، وإنما نزل فيهم فنسب إليهم وهو من سبي اليمن. وُلِدَ في بعلبك سنة 88 ونشأ في البقاع يتيم الأب, ثم انتقلت به أمه إلى بيروت، كان فوق الربعة خفيف اللحية به سمرة، وكان يخضب بالحناء. طلب الحديثَ فصار"},{"id":531,"era":"c2","t":"وفاة الفقيه الحنفي زفر بن الهذيل .","s":"هو العلَّامة الفقيهُ المجتهدُ الربَّاني الحنفي، أبو الهذيل زُفَر بن الهذيل بن قيس بن سلم وُلد سنة 110 في العراق. وكانت أسرة زُفر على جانبٍ مِن سَعة الرزق وبُحبوحة العيش، وهو ما ساعَده على الانصراف إلى طلب العلمِ دون أن يشغَلَ نفسَه بأعباءِ الحياة، فحَفِظَ القرآنَ صغيرًا واستقام به لسانُه، وتفتَّحَت مواهِبُه واستعَدَّت لطلب العلم، ومالت نفسُه ورَغِبَت في تلقِّي الحديثِ النبوي، فتردَّدَ على حلقاتِه "},{"id":532,"era":"c2","t":"وفاة الخليفة العباسي أبي جعفر المنصور .","s":"هو الخليفة العباسي أبو جعفر المنصور عبد الله بن محمد بن علي الهاشمي العباسي, وأمه: سلامة البربريَّة. وُلِدَ سنة 95, وكان أسمرَ, طويلًا, نحيفًا, مَهيبًا, خفيفَ العارِضَينِ, مُعرق الوجه, رحْبَ الجبهة, كأنَّ عينيه لسانان ناطقان, تخالِطُه أبَّهة المُلك بِزِيِّ النسَّاك, تَقبَلُه القلوبُ، وتَتبَعُه العيون, وكان فحْلَ بني العباس؛ هيبةً وشجاعةً، ورأيًا وحزمًا، ودهاءً وجبروتًا، وكان جمَّاعًا للمال, حريصًا"},{"id":533,"era":"c2","t":"محمد بن عبد الله المهدي يتولى الخلافة العباسية .","s":"كان المنصورُ عَهِدَ بالخلافة لولَدِه المهدي محمد بن عبد الله من بعدِه بعد أن اضطرَّ عيسى بن موسى إلى خلعِ نَفسِه من ولاية العهدِ، فلما توفِّي المنصورُ في الحج كُتِمَ أمرُ وفاتِه، حتى أُخِذَت البيعةُ لابنه المهدي، وبُويِعَ له بين الرُّكنِ والمقام، عُرِفَ المهديُّ بسماحتِه وكرَمِه ورَدِّه للمظالمِ."},{"id":534,"era":"c2","t":"غزو العباسيين بلاد الروم الغربية والشرقية .","s":"بعد أن تولَّى المهدي الخلافةَ بعث العباسَ بن محمد على رأسِ جيشٍ إلى بلاد الروم كما أرسل جيشًا آخر إلى بلاد الهند، وكان متَّجهًا بصورة عامة إلى بلاد الروم، حيث ما تنفكُّ الصوائفُ من الثغور فتُغيرُ على أرض الروم، وإن كانت لم تُحدِثْ فتوحات واسعة أو تضمَّ بلادًا جديدة بشكل دائمٍ إلَّا أنَّ الانتصاراتِ كانت كبيرةً، والغنائمُ كثيرةً، والأسرى كذلك."},{"id":535,"era":"c2","t":"خروج يوسف البرم الحروري بخراسان .","s":"خرجَ يوسف بن إبراهيم، المعروفُ بالبرم، بخراسان، منكِرًا هو ومن معه على المهديِّ سيرتَه التي يسيرُ بها، واجتمع معه بشَرٌ كثير، فتوجَّه إليه يزيد بن مزيد الشيباني، وهو ابنُ أخي معن بن زائدة، فلَقِيَه فاقتتلا، حتى صارا إلى المعانقة، فأسره يزيدُ بن مزيد وبعثَ به إلى المهدي، وبعثَ معه وجوهَ أصحابه، فلمَّا بلغوا النهروان حُمِلَ يوسفُ على بعيرٍ، قد حُوِّلَ وجهُه إلى ذَنَبه، وأصحابُه مثلُه، فأدخلوهم الرصا"},{"id":536,"era":"c2","t":"فتح مدينة باربد .","s":"كان المهدي قد سيَّرَ جيشًا في البحر، وعليهم عبد الملك بن شهاب المسمعي إلى بلاد الهندِ في جمعٍ كثيرٍ مِن الجند والمتطوِّعة، وفيهم الربيع بن صبيح، فساروا حتى نزلوا على باربد، فلمَّا نزلوها حصَروها من نواحيها، وحرَّضَ الناسُ بعضُهم بعضًا على الجهادِ، وضايقوا أهلَها، ففتَحَها اللهُ عليهم عَنوةً واحتمى أهلُها بالبلد الذي لهم، فأحرقه المسلمونَ عليهم، فاحتَرَق بعضُهم، وقُتِل الباقون، واستُشهِدَ من المسلم"},{"id":537,"era":"c2","t":"المهدي يلغي نسب آل زياد بمعاوية بن أبي سفيان .","s":"كان سببُ إلغاء نسَبِ آل زياد الذي كان معاويةُ قد استلحَقَه، وكان يقالُ له: زيادُ بن أبيه، هو أنَّ رجلًا من آل زياد قَدِمَ عليه يقال له الصغدي بن سلم بن حرب بن زياد، فقال له المهدي: من أنت؟ فقال: ابنُ عَمِّك. فقال: أيُّ بني عمي أنت؟ فذكر نسَبَه، فقال المهدي: يا ابنَ سُميَّة الزانية! متى كنتَ ابنَ عمِّي؟ وغَضِبَ وأمَرَ به، فوُجِئَ في عنقِه وأُخرِجَ، وسأل عن استلحاقِ زياد، ثمَّ كتب إلى العامل بالبصرة"},{"id":538,"era":"c2","t":"قيام الدولة الإباضية الرستمية في الجزائر .","s":"قام جماعةٌ مِن الخوارج الإباضيَّة بقيادة عبد الرحمن بن رستم، ببناء مدينة تاهرت، وكانت مقرَّهم، وهادنَ إمامُهم عبد الرحمن ولاةَ القيروانِ مثل حكَّام الدولة الصفرية في سجلماسة."},{"id":539,"era":"c2","t":"الخليفة العباسي المهدي يوسع لمسجد الحرام .","s":"حجَّ المهديُّ بعد توليه الخلافةَ بعامٍ, ولَمَّا رأى ضِيقَ مساحة مسجدِ الحرم, ومعاناة الحُجَّاج من الزِّحام؛ أمَرَ بتوسعته، فاشترى الأراضيَ والدُّورَ المحيطة بالمسجد وأزالها، وقد شَمِلَت التوسعة الجهتين الشماليَّة والجنوبية, وأمر بنقل أساطينِ الرُّخامِ من الشام ومصر إلى ميناء جُدَّة، ثم نُقِلَت على عربات إلى مكَّة, أما الأروقة فقد عَمِلَها على أساطينِ الرُّخام، وسُقِفَت بخشب الساج, وقد انتهت أعمال "},{"id":540,"era":"c2","t":"الخليفة العباسي المهدي يوسع المسجد النبوي .","s":"أمر أبو عبد الله محمد المهدي، أثناء زيارتِه للمدينة المنورة، بالزيادةِ فيه، فزاد فيه 30 مترًا من الناحية الشماليَّة فقط, واستمَرَّ العمل في البناء 4 سنوات من سنة 161 وانتهى منه سنة 165."},{"id":541,"era":"c2","t":"الخليفة العباسي المهدي يأمر ببناء المصانع والقصور في طريق مكة .","s":"أمر المهديُّ ببناء القصورِ في طريق مكَّة، وأمر بتوسيعِ القُصور التي كان بناها السفَّاح، كما قام بتجديد الأميال والبِرَك ومصانع المياه، وحفر الرَّكايا؛ كلُّ ذلك تسهيلًا للمسافرينَ في طُرُقِهم، كما أمرَ أن تُقصَّرَ كُلُّ المنابرِ إلى قَدْرِ ارتفاعِ مِنبرِ الرَّسولِ صلَّى الله عليه وسلَّم، ولا يُزادَ على ذلك."},{"id":542,"era":"c2","t":"بناء مدينة تيهرت (تاهرت) كعاصمة لدولة الرستميين .","s":"مدينة تيهرت، أسسَّها عبد الرحمن بن رستم بن بهرام، وكان مولًى لعثمانَ بن عفان، وكان خليفةً لأبي الخطاب أيامَ تغلُّبِه على إفريقية، ولما دخل ابن الأشعث القيروان فرَّ عبد الرحمن إلى الغرب بما خلفَ مِن أهله وماله، فاجتمعت إليه الإباضية، وعزموا على بنيان مدينةٍ تجمَعُهم، فنزلوا بموضعِ تيهرت، وهي غَيضة يكثر فيها الشجر بين ثلاثة أنهارٍ، فبنوا مسجدًا من أربع بلاطات، واختَطَّ الناسُ مساكِنَهم، وكانت في الز"},{"id":543,"era":"c2","t":"عبد الرحمن الفهري يقاتل أهل الأندلس ليدخُلوا في طاعة العباسيَّين .","s":"عبَرَ عبد الرحمن بن حبيب الفهري، المعروف بالصقلبي- وإنَّما سمي به لطولِه وزُرقتِه وشُقرتِه- من إفريقية إلى الأندلس مُحاربًا لهم، ليدخُلوا في طاعة العباسيَّين، وكان عبورُه في ساحل تدمير، وكاتبَ سليمانَ بن يقظان بالدخول في أمرِه، ومحاربةِ عبد الرحمن الداخل، والدُّعاءِ إلى طاعة المهدي. وكان سليمان ببرشلونة، فلم يجِبْه، فاغتاظَ عليه، وقصَدَ بلدَه فيمن معه من البربرِ، فهزمه سليمان، فعاد الصقلبيُّ إلى ت"},{"id":544,"era":"c2","t":"بدء حملات شارلمان على الأندلس .","s":"قام شارلِمان ملكُ الفرنجة بالإغارةِ على الأندلس شمالًا، وذلك بالاتِّفاق مع حليفِه سليمان بن يقظان ابن الأعرابي أمير سرقسطة، واستولى على بنبلونه، ثمَّ اتَّجه نحو سرقسطة، فخرج سليمان لاستقبالِه وتسليمه المدينةَ، لكنَّ المدينة أُغلِقَت بوجهِ الجيوشِ، وتسلَّمَ السلطة الحسين بن يحيى الأنصاري، وهو الذي أعان سليمان في الخروجِ على عبد الرحمنِ الداخِلِ، لكنه أحَبَّ الانفرادَ بإمارة سرقسطة، فاضطرَّ شارلمان "},{"id":545,"era":"c2","t":"وفاة سفيان الثوري .","s":"هو شيخ الإسلام، إمام الحفاظ، أميرُ المؤمنين في الحديث، أبو عبد الله سفيانُ بنُ سعيد بن مسروق الثوريُّ التميميُّ، وُلِدَ سنة 97 بالكوفة, وهو سيِّدُ أهل زمانه في العِلم والدين، من كبارِ تابعي التابعينَ, وأحدُ الأئمة المجتهدينَ الذين كان لهم أتباعٌ، مصنف كتاب (الجامع) ولد: سنة 98 اتفاقا، وطلب العلم وهو حدث باعتناء والده المحدث الصادق سعيد بن مسروق الثوري، وكان والده من أصحاب الشعبي، وخيثمة بن عبد الر"},{"id":546,"era":"c2","t":"وفاة إبراهيم بن أدهم .","s":"هو الإمام العارف، سيد الزهاد، أبو إسحاقَ إبراهيمُ بن أدهم بن منصور التميمي البلْخي ويقال له العجلي. أحد مشاهير العباد وأكابر الزهاد. كانت له همة عالية في ذلك. أصله من بلْخ، ولد سنة 99،كان من الأشراف وكان أبوه كثيرَ المال والخَدَم, ثم ترَكَ ابنُ أدهم الدُّنيا وأقبل على آخِرتِه، سكن الشام وروى الحديثَ، قال النسائي: \"إبراهيم بن أدهم ثقة مأمون أحد الزهاد\". اشتهر بالزُّهد والورع، فلا يُذكَرُ الزُّهدُ إ"},{"id":547,"era":"c2","t":"خروج عبد السلام اليشكري في الجزيرة .","s":"خرج عبد السلامِ بن هاشم اليشكري، وهو من الخوارج الصفرية في الجزيرة، وقَوِيَ أمرُه، وأحرز النصرَ على عددٍ مِن قُوَّاد المهدي وجيوشِه، ثم سار إليه شبيب بن واج المروذي، فانهزم أولًا، ثم طلب الدعمَ مِن المهدي فأمَدَّه وأعطى كلَّ جندي ألفَ درهمٍ معونةً له، فنفر إليه وقاتَلَه مرة أخرى، فهزمه وفر عبد السلام إلى قِنَّسرين فتبعه إليها وتمكَّنَ منه وقتلَه."},{"id":548,"era":"c2","t":"القضاء على فتنة المقَنَّع رأس الزنادقة ببلاد فارس .","s":"ظهر المقَنَّع بخراسان سنة 161 وقيل سنة 159 وكان رجلًا أعورَ قصيرًا، من أهل مرو، ويسمَّى حكيمًا، وكان اتخذَ وجهًا من ذهَبٍ فجعله على وجهِه لئلا يُرى، فسُمِّيَ المقَنَّع، وادعَّى الألوهيَّة، ولم يُظهِرْ ذلك إلى جميع أصحابه، وكان يقولُ: إن الله خلق آدم، فتحول في صورته، ثمَّ في صورة نوح، وهكذا هلُمَّ جرًّا إلى أن تحوَّلَ في صورة أبي مسلم الخراساني، ثم تحوَّل إلى هاشم، وهاشم- في دعواه- هو المقَنَّع، وي"},{"id":549,"era":"c2","t":"وفاة أبي بكر بن عبد الله بن محمد بن أبي سبرة .","s":"هو الفقيه الكبير، قاضي العراق، أبو بكر بن عبد الله بن محمد بن أبي سبرة بن أبي رهم - وهو بدري من السابقين المهاجرين- بن عبد العزى القرشي، ثم العامري. كان أبو بكر من علماء قريش، ولاه المنصور القضاء، وكان خرج مع محمد بن عبد الله بن حسن صاحب النفس الزكية، وكان على صدقات أسد وطيء، فقدم على محمد بأربعة وعشرين ألف دينار، فلما قتل محمد، أُسر ابن أبي سبرة وسجن، ثم استعمل المنصور جعفر بن سليمان على المدينة،"},{"id":550,"era":"c2","t":"المهدي يغزو الروم بقيادة ابنه هارون الرشيد .","s":"تجهَّزَ المهدي لغزو الروم، فخرج وعسكرَ بالبردان، وجمع الأجناد من خراسان وغيرها، وسار عنها، وكان قد توفِّي عيسى بن علي بن عبد الله بن عباس في جمادى الآخرة، وسار المهدي من الغد، واستخلفَ على بغداد ابنَه موسى الهادي، واستصحَبَ معه ابنه هارون الرشيد، وسار على الموصِل والجزيرة، وعزل عنها عبد الصمد بن علي في مسيرِه ذلك، ولما حاذى قصرَ مسلمة بن عبد الملك، قال العباس بن محمد بن علي للمهدي: إنَّ لِمَسلمةَ "},{"id":551,"era":"c2","t":"قتال المسلمين للأرمن  .","s":"غزا عبدُ الكبيرِ بنُ عبد الحميدِ بنِ عبدِ الرحمنِ بنِ زيدِ بنِ الخطَّابِ الصائفةَ مِن درب الحدث، بلاد الروم، فأتاه ميخائيلُ البِطريق، وطاردا طازاذ الأرمني البطريق في تسعينً ألفًا، فخافه عبد الكبير، ومنع الناسَ من القتال، ورجع بهم، فأراد المهديُّ قتْلَه، فشُفعَ فيه فحبَسَه."},{"id":552,"era":"c2","t":"عبدالرحمن الداخل يستعيد سرقسطة  .","s":"سار عبدُ الرحمن الداخل إلى سرقسطة، بعد أن كان قد سيَّرَ إليها ثعلبةَ بنَ عُبيد في عسكرٍ كثيف، وكان سليمانُ بن يقظان، والحسينُ بن يحيى قد اجتمعا على خلعِ طاعةِ عبد الرحمن، وهما بها، فقاتَلَهما ثعلبةُ قِتالًا شديدًا، وفي بعض الأيامِ عاد إلى مخَيَّمِه، فاغتنم سليمانُ غِرَّتَه، فخرج إليه، وقبَضَ عليه وأخَذَه، وتفَرَّق عسكَرُه، واستدعى سليمان بن يقظان قارله ملك الإفرنج، ووعَدَه بتسليمِ البلد وثعلبةَ إل"},{"id":553,"era":"c2","t":"غزو عبدالرحمن الداخل الفرنجة في الأندلس .","s":"غزا عبدالرحمن الداخل بلادَ الفرنج، فدَوَّخَها، وبلغ قلهرة، وفتح مدينةَ فكيرة، وهدمَ قلاعَ تلك الناحية، وسار إلى بلاد البشكنس، ونزل على حِصنِ مثمين الأقرع، فافتتحه، ثمَّ تقدم إلى ملدوثون بن أطلال، وحصر قلعتَه، وقصد الناسُ جَبَلَها، وقاتلهم فيها، فمَلَكَها عَنوةً وخرَّبَها ثم رجع إلى قُرطبة."},{"id":554,"era":"c2","t":"فتنة الثورات بين البربر في الأندلس .","s":"ثارت فتنةٌ بين بربر بلنسية وبربر شنت برية من الأندلس، وجرت بينهم حروبٌ كثيرةٌ قُتِلَ فيها خَلقٌ كثيرٌ مِن الطائفتَينِ، وكانت وقائِعُهم مشهورةً."},{"id":555,"era":"c2","t":"ثورة دحية بن مصعب الأموية في مصر ضد العباسيين .","s":"خرج دحيةُ بن المصعب بن الأصبغ بن عبد العزيز بن مروان الأموي بالصعيدِ ودعا لنَفسِه بالخلافة، فتراخى عنه إبراهيمُ بنُ صالح أميرُ مصرَ، ولم يحفِلْ بأمره حتى استفحلَ أمرُ دحية، وملكَ غالِبَ بلاد الصعيد وكاد أمرُه أن يتِمَّ ويُفسِدَ بلادَ مِصرَ وأمرَها؛ فسَخِطَ المهديُّ عليه؛ بسبب ذلك، وعزله عزلًا قبيحًا، ثمَّ عيَّن موسى بن مصعب بن الربيع الذي اشتغلَ بأمر دحية الأموي، وجهَّزَ إليه جيوشًا لقتاله، ثمَّ خ"},{"id":556,"era":"c2","t":"غدر الحسين بن يحيى بعبدالرحمن الداخل بالأندلس .","s":"غدر الحُسَين بن يحيى بسرقسطة، فنكَثَ مع عبد الرحمن، فسيَّرَ إليه عبد الرحمن غالبَ بنَ ثُمامة بن علقمة في جندٍ كثيف، فاقتتلوا، فأسرَ جماعةً من أصحاب الحسين فيهم ابنُه يحيى، فسيَّرَهم إلى الأمير عبد الرحمن، فقتَلَهم، وأقام غالبُ بن ثمامة على الحسين يحصُرُه، ثمَّ إنَّ الأمير عبد الرحمن سار سنةَ سِتٍّ وستين ومائة إلى سرقسطة بنفسِه، فحاصرها، وضايقَها، ونصب عليها المجانيقَ ستة وثلاثين منجنيقًا، فمَلَكَه"},{"id":557,"era":"c2","t":"هارون الرشيد ينتصر على البيزنطيين .","s":"أرسل المهديُّ ابنَه الرشيدَ لغَزوِ الرومِ صائفة، في خمسةٍ وتسعين ألفًا وتسعمائة وثلاثة وتسعين رجلًا، ومعه الربيع، فوغل هارونُ في بلاد الروم، ولقيه عسكرُ لقيظا قومس القوامسة، فبارزه يزيدُ بن مزيد الشيباني فأثخنه يزيدُ وانهزمت الرومُ، وغلب يزيدُ على عسكَرِهم. وساروا إلى الدمستق، وهو صاحِبُ المسالح، فحمل لهم مائة ألفِ دينار وثلاثة وتسعين ألفًا وأربعمائة وخمسين دينارًا، ومن الوَرِق أحدًا وعشرين ألف أل"},{"id":558,"era":"c2","t":"أخذ المهدي البيعة لولده هارون من بعد موسى الهادي .","s":"في هذه السنة أخذ المهديُّ البيعةَ لابنه هارون ولُقِّبَ بالرشيدِ مِن بعد موسى الهادي"},{"id":559,"era":"c2","t":"تتبعُ المهدي الزنادقة وإنشاء ديوان لمطاردتهم .","s":"جدَّ المهديُّ في تتبُّعِ الزنادقةِ، فأنشأ ديوانًا لمطاردتِهم, وكان المتولي أمرَ هذا الديوانِ عمر الكلواذي الذي صار يتتبَّعُ الزنادقةَ في سائرِ الآفاق فيستحضِرُهم ويقتلُ صبرًا بين يدي المهدي، فقتل عددًا كبيرًا، منهم الشَّاعرُ بشَّار بن بُرد، وأخذ يزيد بن الفيض كاتبَ المنصور، فأقَرَّ ولم يرجِعْ عمَّا يعتَقِدُه فحبسه، ثم هرب من الحَبسِ، فلم يَقدِر عليه."},{"id":560,"era":"c2","t":"نقض الروم الصلح الذي عقده هارون الرشيد عن أمر أبيه  .","s":"نقضَ الرومُ الهُدنةَ التي عقَدَها الرشيدُ سنة 165هـ فوجه إليهم عليُّ بن سليمان أميرُ الجزيرةِ جيشًا بقيادةِ يزيدَ بنِ بدر البطَّال، فظَفِرَ بهم وغَنِم."},{"id":561,"era":"c2","t":"اتخاذ الخليفة المهدي دواوين الأزِمة وتسمى (المالية) .","s":"كان ديوانُ الأزِمَّة- واحِدُها الزِّمام- من أهمِّ دواوينِ الدَّولة- ويُشبِهُ ديوانَ المحاسبةِ اليومَ- وكانت مهمَّةُ صاحب هذا الديوانِ جمعَ ضرائبِ بلاد العراقِ؛ أغنى أقاليمِ الدولة العباسية، وتقديمَ حسابِ الضرائب في الأقاليم الأخرى. ومن اختصاصاتِه أيضًا جمعُ الضرائب النوعيَّة المسمَّاة بالمعادن، وكانت تُجمَعُ لرجُلٍ يَضبِطُها بزمامٍ يكون له على كلِّ ديوانٍ- وقد جمَعَها عمر بن بزيع- فيتَّخِذُ دواوين"},{"id":562,"era":"c2","t":"ثورة أبي الأسود الفهري في الأندلس .","s":"ثار أبو الأسود محمد بن يوسف بن عبد الرحمن الفِهري بالأندلس، وكان من حديثه: أنَّه كان في سِجنِ عبد الرحمن بقُرطبةَ مِن حينِ هرب أبوه، وقُتِل أخوه عبد الرحمن، وحُبِس أبو الأسود، وتعامى في الحبسِ ثمَّ هرب منه واجتمعَ حَولَه خَلقٌ كثيرٌ، فرجع بهم إلى قتال عبد الرحمن الداخل، فالتقيا على الوادي الأحمر بقسطلونة، واشتدَّ القتال، ثم انهزم أبو الأسودِ، وقُتِلَ من أصحابِه أربعةُ آلاف سوى من تردَّى في النهر، "},{"id":563,"era":"c2","t":"توالي ثورات الخوارج في الجزيرة والموصل  .","s":"خرج بأرضِ المَوصِل خارجيٌّ اسمُه ياسين من بني تميم، فخرج إليه عسكرُ الموصِل، فهزمهم، وغلَب على أكثَرِ ديار ربيعةَ والجزيرة، وكان يميلُ إلى مقالةِ صالحِ بن مسرح الخارجيِّ، فوجَّه إليه المهديُّ أبا هريرة محمد بن فرُّوخ القائد، وهرثمة بن أعيَن مولى بني ضبة، فحارباه فصَبَرَ لهما، حتى قُتِلَ وعِدَّةٌ من أصحابِه، وانهزم الباقون."},{"id":564,"era":"c2","t":"وفاة نافع بن عبدالرحمن أحدُ القُرَّاء السبعة .","s":"هو الإمامُ حَبرُ القرآنِ: نافع بن عبدالرحمن بن أبي نعيم، أحدُ القُرَّاء السبعة، أصلُه من أصبهان، ولد بالمدينة سنة 70 وقيل 71هـ في خلافة عبدالملك بن مروان, وكان أسودَ اللونِ حالكًا صبيحَ الوجهِ حسَنَ الخُلُق، فيه دُعابة، أخذ القراءةَ عَرضًا عن جماعةٍ مِن تابعي أهلِ المدينة، أقرأَ النَّاسَ دهرًا طويلًا؛ نيفًا عن سبعين سنة، وانتهت إليه رياسةُ القراءة بالمدينة، قيل: إنه كان يُشَمُّ منه رائحةُ المِسكِ "},{"id":565,"era":"c2","t":"وفاة الخليفة العباسي المهدي .","s":"هو محمَّدُ بن عبد الله بن محمد بن علي بن عبد الله بن عباس، أبو عبدِ الله المهدي، أميرُ المؤمنين، لُقِّبَ بالمهدي رجاءَ أن يكون الموعودَ به في الأحاديثِ، فلم يكُنْ به. وُلِدَ بالحميمة من أرض البلقاء سنة 126هـ، وقيل 127هـ، ووليَ الخلافةَ بعد أبيه سنة 158هـ في ذي الحجة سنة ثمان وخمسين ومائة، وعمُره إذ ذاك 33 سنة، وكان أسمرَ طويلًا جَعْدَ الشَّعرِ. وكان من مآثِره تتبُّعُه للزنادقة في عهدِه، حتى قُتِلَ"},{"id":566,"era":"c2","t":"موسى الهادي يتولى الخلافة العباسية .","s":"وبويِعَ لموسى الهادي في اليومِ الذي مات فيه المهديُّ، وهو مقيمٌ بجرجان، يحارِبُ أهل طبرستان."},{"id":567,"era":"c2","t":"ثورة الحسين بن علي بن الحسن في المدينة ومكة .","s":"ظهر الحُسَين بن عليِّ بن الحسن بن الحسن بن علي بن أبي طالب بالمدينةِ، وذلك أنَّه أصبح يومًا وقد لَبِسَ البياضَ وجلس في المسجدِ النبويِّ، وجاء الناسُ إلى الصلاةِ، فلما رأوه ولَّوا راجعين، والتفَّ عليه جماعةٌ فبايعوه على الكتابِ والسنَّة والرضا من أهل البيت, وكان سببُ خروجِه أنَّ متولي المدينة خرج منها إلى بغداد ليهنِّئ الخليفةَ الهادي بالولايةِ ويعَزِّيه في أبيه. ثم جرت أمورٌ اقتَضَت خروجَه، والتفّ"},{"id":568,"era":"c2","t":"وفاة الخليل بن أحمد الفراهيدي .","s":"هو الخليلُ بن أحمد بن عمرو بن تميم الفراهيديُّ الأزدي اليحمدي، أبو عبد الرحمن: من أئمَّة اللغة والأدب، وواضِعُ علم العروضِ، إمامُ اللغة المعروف، ولد سنة 100هـ ونشأ بالبصرة، وأخذ النحوَ والقراءةَ والحديث عن أئمَّة العربية وكِبار الرواة، رحل إلى الباديةِ فسَمِعَ الفصيحَ وجمَع الغريبَ، حتى نبغَ في اللغة فأصبح عَلَمَها المشهورَ، وعنه أخذ سيبويهِ، انكَبَّ على العلم يستنبِطُ ويُعَلِّم ويؤلِّف، مع تقشُّف"},{"id":569,"era":"c2","t":"ثورة الإباضية في أفريقية .","s":"لَمَّا توفِّيَ يزيد بن حاتم المهلبي، والي إفريقيَّة، وكان قد استخلفَ عليها ابنَه داود، فانتقَضَت جبال باجة، وخرج فيها الإباضيَّة، فسيَّرَ إليهم داود جيشًا فظَفِرَ بهم الإباضيَّة، وهزموهم، فجهز إليهم جيشًا آخرَ، فهُزِمت الإباضيَّة، فتَبِعَهم الجيش، فقَتلوا منهم فأكثروا، وبَقيَ داود أميرًا إلى أن استعمل الرَّشيدُ عمَّه روح بن حاتم المهلبي أميرًا على إفريقيَّة."},{"id":570,"era":"c2","t":"بدء بناء جامع قرطبة .","s":"كان أوَّل الأمرِ في قرطبة عندما فتَحَها المسلمونَ أن بنَوَا المسجِدَ فيها بجانب الكنيسةِ العظيمة فيها، ثمَّ لَمَّا ازداد عددُ المسلمين وضاق عليهم المسجدُ، نظر عبدالرحمن الداخل في أن يوسِّعَه فاشترى من النصارى كنيسَتَهم بعد أن دفَعَ لهم ما أرادوه من المالِ، وأوسع في ذلك، فأمر بتحويلِه إلى مسجدٍ وضَمَّه للقديم، وكان ذلك في عامٍ كاملٍ."},{"id":571,"era":"c2","t":"وفاة الخليفة العباسي الهادي  .","s":"هو موسى الهادي بن محمد المهدي بن عبد الله المنصور بن محمد بن علي بن عبد الله بن عباس أبو محمد وَلِيَ الخلافةَ في محرم سنة تسع وستين ومائة. مات وله من العمُرِ ثلاث وعشرون سنة، ويقال: إنَّه لم يلِ الخلافةَ أحدٌ قبلَه في سِنِّه، وكان حسنًا جميلًا طويلًا، أبيض، وكان قويًّا شَهمًا خبيرًا بالمُلك كريمًا، ومن كلامه: \"ما أُصلِحَ الملكُ بمثل تعجيلِ العقوبةِ للجاني، والعفوِ عن الزلَّات، ليقِلَّ الطَّمعُ عن "},{"id":572,"era":"c2","t":"تولي هارون الرشيد الخلافة .","s":"أراد الهادي أن يعهَدَ لابنه جعفرٍ بدلًا من أخيه هارون الرشيد الذي عيَّنه والده المهديُّ واليًا ثانيًا للعهد. وألحَّ الهادي على ذلك وشجَّعَه جماعةٌ من ولاته, لكِنَّ خالد بن يحيى البرمكي نبَّهَه أنَّ جعفر ما زال صغيرًا لم يبلُغ الحنثَ، ثمَّ إنَّ هذا سيجعل الناسَ تستخِفُّ بأيمانِها، فرجع الهادي عن رأيه في عَزْلِ الرشيد, والعجيبُ أنَّ الرشيدَ كان مُسالِمًا لأخيه الهادي في هذا الأمرِ دون أن يبديَ أيَّ "},{"id":573,"era":"c2","t":"الأدارسة يقيمون دولتهم ويبنون فاس عاصمة لها بالمغرب الأقصى .","s":"هرب إدريسُ بن عبدالله بن حسن بن الحسن بن علي بن أبي طالب- أخو محمد النَّفس الزكيَّة- من الحجاز بعد أن نجا من معركةِ فخ بمكَّة عام 169هـ فاتَّجه لمصرَ ثمَّ للمغرب، واستطاع أن يؤسِّسَ بمساعدة السكَّان البربر دولةَ الأدارسة العلويَّة المنفصلة عن المشرقِ في خلافة هارون الرشيد, وبنى مدينة فاس في مكانٍ يسمَّى جراوة، وصارت عاصمةً له وبَقِيَ حاكمًا عليهم إلى أن توفِّيَ عام 175هـ وقيل في 177هـ"},{"id":574,"era":"c2","t":"وفاة عبدالرحمن الداخل صاحب الأندلس .","s":"هو عبد الرحمن بن معاوية بن هشام بن عبد الملك بن مروان، صاحِبُ الأندلس، سمِّيَ بالداخل؛ لأنَّه استطاع أن يهربَ مِن العباسيين رغمَ كُلِّ المحاولاتِ للإمساك به، واستطاع أن يدخُلَ الأندلسَ، وأن يكَوِّنَ فيها دولةً قَوِيَت يومًا بعد يوم، وقيل: كان عمره حينئذ عشرين سَنةً، وأما موتُه فكان بقرطبة، وصلَّى عليه ابنُه عبد الله، وكان عَهِدَ إلى ابنه هشام، وكان هشامٌ بمدينة ماردة واليًا عليها، وكان ابنُه سليما"},{"id":575,"era":"c2","t":"هارون الرشيد يكتب كتابا يوصي فيه لابنه الأمين بالبيعة .","s":"أخذ الرَّشيدُ بولاية العهدِ مِن بعده لولَدِه محمَّد بن زبيدة وسمَّاه الأمين، وعمُرُه إذ ذاك خمسُ سنين، وقد كان الرشيد يتوسَّمُ النجابةَ والرَّجاحة في عبد الله المأمون، ويقول: والله، إنَّ فيه حزمَ المنصور، ونُسُك المهديِّ، وعِزَّة نفسِ الهادي، ولو شئتُ أن أقولَ الرابعةَ مني لقُلتُ، وإني لأقَدِّمُ محمَّد بن زبيدة، وإنِّي لأعلَمُ أنَّه مُتَّبِعٌ هواه، ولكن لا أستطيعُ غيرَ ذلك، ثمَّ لَمَّا حج علَّقَ ه"},{"id":576,"era":"c2","t":"تغلب هشام بن عبدالرحمن على أخويه .","s":"لَمَّا استلم هشامٌ الخلافةَ بعَهدِ أبيه إليه، طَمِعَ أخواه فيها بعد مدَّةٍ، فحاول سليمانُ-وهو الأخ الأكبَرُ لهشام- ذلك، ودعا لنفسِه وبويع في بعضِ المناطق، ثم فعل أخوه الآخَرُ عبدالله كذلك، فانتدب لهما هشامٌ وغَلَبَهما وأجْلاهما عن الأندلُس."},{"id":577,"era":"c2","t":"القضاء على تمرد مطروح بن سليمان في سرقسطة .","s":"لَمَّا فرغ هشامُ بن عبدالرحمن من أخوَيه سليمانَ وعبد الله, انتدب لمطروحِ بن سليمان بن يقظان، فسيَّرَ إليه جيشًا كثيفًا، وجعل عليه أبا عثمان عبيد الله بن عثمان، فسار إلى مطروح، وهو بسرقسطة، فحصَرَه بها فلم يظفَرْ به، فرجع أبو عثمانَ عنه، ونزل بحِصنِ طرسونة، بالقربِ من سرقسطة، وبثَّ سراياه على أهل سرقسطة يُغِيرونَ ويَمنَعون عنهم المِيرةَ، ثمَّ غدر بمطروحٍ بعضُ أصحابِه وقَتَلوه ودانُوا لهِشامٍ، فقَبِ"},{"id":578,"era":"c2","t":"غزو عبيد الله بن مطروحِ بلاد الفرنجة .","s":"لَمَّا فرغ أبو عثمان عبيد الله بن عثمان من مطروحِ بنِ سليمان، سار إلى بلاد الفرنج، فلَقِيَه العدوُّ، فظَفِرَ بهم، وقتلَ منهم خلقًا كثيرًا، وفتح الله عليه."},{"id":579,"era":"c2","t":"غزو هشام بن عبدالرحمن مدينة جليقية (غرب إسبانيا) .","s":"سيَّرَ هشام بن عبدالرحمن يوسُفَ بن بخت في جيشٍ إلى جليقية، فلقِيَ مَلِكَهم وهو برمند الكبير، فاقتتلوا قتالًا شديدًا وانهزمت الجلالِقةُ، وقُتِل منهم عالَمٌ كثير."},{"id":580,"era":"c2","t":"وفاة الليث بن سعد .","s":"هو الإمامُ الحافِظُ شيخ الإسلامِ، وعالمُ الدِّيار المصرية، أبو الحارثِ الليثُ بنُ سعدِ بن عبد الرحمن الفهمي، ولِدَ سنة أربع وتسعين بقرقشندة- قرية من أسفل أعمال مصر- إمامُ أهل مصر في عصرِه؛ حديثًا وفِقهًا ولغةً، حتى قال الشافعي: الليث أفقَهُ من مالك، أصلُه من أصبهان، ولد في مصر ونشأ فيها، أراده المنصورُ على القضاء فأبى، كان متولِّي مصرَ وقاضيها وناظِرُها من تحتِ أوامِره، ويَرجِعونَ إلى رأيِه ومَشُو"},{"id":581,"era":"c2","t":"ثورة يحيى بن عبدالله في بلاد الديلم (من ذرية الحسن بن علي) .","s":"هو يحيى بن عبدالله بن الحسن بن الحسن بن علي بن أبي طالب، وكان يحيى ممَّن نجا يوم فخٍّ بمكَّة عام 169هـ فهرب إلى اليمن، ثم لمصر، ثم بغداد، ثم نزل ببلاد الديلم، واتَّبَعه خلقٌ كثيرٌ وجَمٌّ غفير، وقَوِيَت شوكتُه، وارتحل إليه الناسُ من الكور والأمصار، فانزعج لذلك الرشيدُ وقَلِقَ من أمره، فنَدَب إليه الفضلَ بن يحيى بن خالد بن برمك، فسار الفضلُ إليه وكاتَبَه بأنَّه سيسعى له بالأمانِ إن هو خرجَ مُطيعًا و"},{"id":582,"era":"c2","t":"فتنة عظيمة بالشام بين النزارية (القيسية) واليمانية .","s":"هاجت الفتنةُ بدِمشقَ بين المُضَريَّة واليمانية، وكان رأس المضرِيَّة أبو الهيذام، واسمُه عامر بن عمارة بن خريم أحَد الفُرسان المشهورين، وكان سببُ الفتنة أنَّ عامِلًا للرشيد بسجستان قَتَل أخًا لأبي الهيذام، فخرج أبو الهيذامِ بالشام، وجمعَ جمعًا عظيمًا فرثى أخاه بأبياتٍ، ثمَّ إنَّ الرشيد احتال عليه بأخٍ له كتَبَ إليه فأرغَبَه، ثم شَدَّ عليه فكَتَّفه، وأتى به الرشيدَ، فمَنَّ عليه وأطلقه. وقيل: كان أوّ"},{"id":583,"era":"c2","t":"ظهور الإباضية في عُمان .","s":"استطاع أحدُ زُعَماء الإباضية وهو عبد الله بن يحيى، المشهورُ بطالب الحقِّ، الاستيلاءَ على حضرموت سنة 129هـ، في السنواتِ الأخيرة لحُكم بني أمية، بمساعدة الإباضيَّة في البصرة، ثم استولى على صَنعاء، وامتَدَّ نُفوذُهم إلى بعضِ مَناطِقِ الحجاز بعد انتصاراتٍ على الجيوش الأمويَّة، تَبِعَها هزائم وانكسارات. وقد ظَلَّ للإباضيَّة نفوذ وانتشار في حضرموت حتى استيلاء الصليحي عليها سنة 455هـ. وأدَّت بعضُ العوامل"},{"id":584,"era":"c2","t":"غزو هشام بن عبدالرحمن الداخل جنوب فرنسا .","s":"أرسل هشامُ بن عبدالرحمن الداخل بالصائفة جيشًا كثيفًا واستعمَلَ عليهم وزيرَه عبدالملك بن عبدالواحد بن مُغيث، فبلغ ألبةَ والقلاعَ، وأثخن في نواحيها، ثم بعَثَه في العساكِرِ، فوصلوا إلى أربونة وجرندة، وكان البدءُ بجرندة، وكان بها حامية الفرنج، فقَتَل رجالَها وهَدَّم أسوارَها بالمجانيقِ، وأبراجَها، وأشرَفَ على فَتحِها، فرحل عنها إلى أربونة، ففعل بها مثلَ ذلك، وأوغلَ في بلادهم ووطئَ أرض برطانية فاستباح "},{"id":585,"era":"c2","t":"فتنة العطاف في الموصل .","s":"خالف العطافُ بنُ سفيانَ الأزديُّ الرشيدَ وتغلَّب على الموصِل، وكان من فرسانِ أهلِ الموصل، واجتمع عليه أربعةُ آلافِ رَجُلٍ، وجبى الخراجَ، وكان عامِلُ الرشيدِ على الموصل محمَّدَ بن العباس الهاشمي، وقيل: عبد الملك بن صالح، والعطاف غالِبٌ على الأمر كلِّه، وهو يَجبي الخراج، وأقام على هذا سنتين، حتى خرجَ الرشيدُ إلى الموصل فهدَمَ سُورَها بسَبَبِه, فأقسَمَ ليقتُلَنَّ من لَقِيَ مِن أهلِها، وكان العطاف قد "},{"id":586,"era":"c2","t":"اغتيال إدريس بن عبدالله مؤسس دولة الأدارسة بالمغرب .","s":"لَمَّا قَدِمَ إدريسُ بن عبدالله المغربَ سنة 172هـ نزل على إسحاقَ بن عبد الحميد، فقَدَّمه قبائلُ البربر وأطاعوه، وبلغ خبرُه هارونَ الرشيد، فدَسَّ إليه مَن سَمَّه. وكان المدسوسُ إليه رجلًا يقالُ له الشماخ، فسَمَّه وهرب إلى المشرق، فقام بأمرِ البربرِ مولاه راشِد. وترك إدريسُ جاريةً بربريَّةً اسمها كنزة؛ فوَلَدت له غلامًا سُمِّيَ باسم أبيه، فوَلِيَ إدريسُ بنُ إدريس سنة 187هـ وهو ابنُ أحد عشرة سنة، وقي"},{"id":587,"era":"c2","t":"ثورة أهل تونس ونهاية دولة المهالبة .","s":"استعمل الرشيدُ على إفريقيَّة الفضلَ بنَ روح بن حاتم المهلبي بعد موت والِدِه, فاستعمل الفضلُ على مدينة تونس ابنَ أخيه المغيرةَ بن بشر بن روح، فاستخَفَّ بالجُندِ. وكان الفضلُ أيضًا قد أوحَشَهم، وأساء السيرةَ معهم؛ بسبَبِ ميلهم إلى نصرِ بن حبيب الوالي قبلَه، فاجتمع مَن بتُونس، وكتبوا إلى الفضلِ يَستعفُونه من ابن أخيه، فلم يُجِبْهم عن كتابِهم، فاجتمعوا على تَركِ طاعتِه، فبايعوا عبدالله بن الجارود، وأخ"},{"id":588,"era":"c2","t":"فتنة تاكرنا بالأندلس .","s":"هاجت فتنةُ تاكرنا بالأندلس، وخلع بربَرُها الطاعة، وأظهروا الفسادَ، وأغاروا على البلادِ، وقطعوا الطريقَ، فسَيَّرَ هشام بن عبدالرحمن إليهم جُندًا كثيفًا عليهم عبدُ القادر بن أبان بن عبد الله، مولى معاويةَ بن أبي سفيان، فقَصَدوها وتابَعوا قتالَ من فيها إلى أن أبادوهم قتلًا وسَبيًا، وفَرَّ من بقِيَ منهم، فدخل في سائرِ القبائل، وبَقِيَت كورة تاكرنا وجبالُها خاليةً مِن الناس سبعَ سنين."},{"id":589,"era":"c2","t":"ثورة مسلمي مصر على الضرائب العباسية .","s":"لَمَّا وَلِيَ إسحاق بن سليمان بن علي بن عبد الله بن العباس إمارةَ مِصرَ لم يرضَ بما كان يأخُذُه قبله الأمراءُ، وزاد على المُزارعين زيادةً أفحَشَت بهم فسَئِمَته الناسُ وكَرِهَته وخرج عليه جماعةٌ مِن أهل الحوفِ مِن قيس وقضاعة، فحاربَهم إسحاقُ، وقُتل من حواشيه وأصحابِه جماعةٌ كبيرة، فكتب إسحاقُ يُعلِمُ الرَّشيدَ بذلك، فعَظُمَ على الرشيدِ ما ناله من أمرِ مِصرَ، وصَرَفه عن إمرَتِها وعقَدَ الرَّشيدُ لهر"},{"id":590,"era":"c2","t":"القضاء على ثورة الوليد بن طريف الخارجي في الجزيرة .","s":"خرج الوليدُ بن طريف التغلبي بالجزيرة، ففَتَك بإبراهيم بن خازم بن خزيمة بنصيبين، ثم قَوِيَت شوكةُ الوليد، فدخل إلى أرمينيَّة، وحصر خلاط عشرينَ يومًا، فافتدوا منه أنفُسَهم بثلاثين ألفًا. ثم سار إلى أذربيجان، ثمَّ إلى حلوان وأرض السواد، ثم عبَرَ إلى غرب دجلة، وقصد مدينة بلد، فافتدوا منه بمائةِ ألف، وعاث في أرضِ الجزيرة، فسَيَّرَ إليه الرشيد يزيدَ بن مزيد بن زائدة الشيباني, فجعل يزيدُ يختالُه ويُماكِر"},{"id":591,"era":"c2","t":"غزو هشام بن عبدالرحمن الفرنج بالأندلس .","s":"سيَّرَ هشام بن عبدالرحمن صاحِبُ الأندلس جيشًا كثيفًا عليهم عبدُ الملك بن عبد الواحد بن مغيث، إلى جليقية، فساروا حتى انتهوا إلى استرقة، وكان أذفونش، ملك الجلالقة قد جمع وحشَد، وأمَدَّه ملك البشكنس، وهم جيرانُه، ومن يليهم من المجوس، وأهل تلك النواحي، فصار في جمعٍ عظيم، فأقدمَ عليه عبدُ الملك، فرجع أذفونش هيبةً له، وتَبِعَهم عبد الملك يقفو أثَرَهم، ويُهلِكُ كلَّ من تخلَّفَ منهم، فدَوَّخ بلادَهم، وأوغ"},{"id":592,"era":"c2","t":"وفاة الإمام مالك بن أنس .","s":"هو إمامُ دار الهجرة، أبو عبدِ الله مالكُ بنُ أنس بن مالك بن أبي عامر بن عمرو بن الحارث بن غيمان بن خثيل بن عمرو بن الحارث الأصبحي، ثم المدني، جَدُّه الصحابيُّ أبو عامرٍ الأصبحيُّ، كان طويلًا عظيمَ الهامةِ أصلعَ أبيضَ الرأسِ واللِّحية. أبيضَ شديدَ البياضِ إلى الشُّقرة. وُلِدَ بالمدينة سنة ثلاث وتسعين، عام موتِ أنسِ بنِ مالكٍ خادمِ رَسولِ الله صلى الله عليه وسلم، ونشأ في أسرةٍ ذاتِ صَونٍ ورفاهيةٍ وت"},{"id":593,"era":"c2","t":"خروج حمزة بن أترك في خراسان .","s":"خرج حمزةُ بن أترك السجستاني الخارجيُّ في خراسان، فجاء إلى بوشنج، فخرج إليه عَمرَوَيه بن يزيد الأزدي، وكان على هراة، في ستةِ آلاف، فقاتَلَه فهزمه حمزة، وقتَلَ مِن أصحابه جماعةً، ومات عَمرَويه في الزحام، فوجَّه عليُّ بن عيسى- وهو أميرُ خراسان- ابنَه الحُسَينَ في عشرة آلاف، فلم يحارِبْ حمزة، فعَزَله وسَيَّرَ عِوَضَه ابنَه عيسى بن علي، فقاتل حمزة، فهَزَمه حمزةُ، فرَدَّه أبوه إليه أيضًا فقاتله بباخرز، "},{"id":594,"era":"c2","t":"نزول هارون الرشيد الرقة .","s":"بعد أن هدمَ الرَّشيدُ سُورَ الموصِل بسبَبِ العطاف بن سفيان الأزدي، مضى إلى الرقَّةِ فاتَّخَذها وَطنًا، واستنابَ على بغدادَ ابنَه الأمينَ محمَّدًا، وولاه العِراقَينِ."},{"id":595,"era":"c2","t":"وفاة سيبويه أستاذ النحاة .","s":"هو أبو بِشرٍ عَمرُو بنُ عُثمانَ بنِ قُنَبْرَ مَولى بني الحارثِ بنِ كعبٍ، قيل: مولى الرَّبيع بن زياد الحارثي البصري، ولُقِّبَ سيبويهِ لجَمالِه وحُمرةِ وَجنَتَيه، حتى كانتا كالتفَّاحتَين، وسيبويهِ في لغة فارس (رائحةُ التفاحِ)، وهو الإمامُ العلَّامة العَلَم، شيخُ النُّحاة من لدنْ زمانِه إلى زمانِنا هذا، والناسُ عِيالٌ على كتابِه المشهورِ في هذا الفنِّ المعروفِ باسمِ \"كتابُ سِيبَويه\"، وقد شُرِحَ شروحً"},{"id":596,"era":"c2","t":"غزو الحكم بن هشام بلاد الفرنج (صاحِب الأندلس) .","s":"سيَّرَ الحكم بن هشام صاحِبُ الأندلس جيشًا مع عبد الكريم بنِ مغيث إلى بلاد الفرنج، فدخل البلادَ، وبثَّ السَّرايا فجازوا خليجًا من البحر كان الماءُ قد جَزَر عنه، وكان الفرنجُ قد جعلوا أموالَهم وأهليهم وراء الخليجِ؛ ظنًّا منهم أنَّ أحدًا لا يقدِرُ أن يعبُرَ إليهم، فجاءهم ما لم يكُنْ في حِسابهم، فغَنِمَ المسلمون جميعَ مالهم، وأسَروا الرجالَ وقَتَلوا منهم فأكثروا، وسَبَوا الحريمَ، وعادوا سالِمينَ إلى ع"},{"id":597,"era":"c2","t":"وفاة هشام بن عبدالرحمن حاكم الأندلس .","s":"هو هِشامُ بنُ عبد الرحمن بن معاوية بن هشامِ بن عبد الملك بن مروان، صاحِبُ الأندلس، توفي في صفر، وكانت إمارتُه سبع سنين وسبعة أشهر وثمانية أيام، وقيل: تسعة أشهر، وقيل: سبعة أشهر، وكان عمرُه تسعًا وثلاثين سنة وأربعة أشهر، كان ذا رأيٍ وشجاعةٍ وعدلٍ، محبًّا لأهل الخير والصَّلاح، شديدًا على الأعداءِ، راغبًا في الجهادِ، وهو الذي تمَّمَ بناء جامِعِ قرطبة، وكان أبوه قد مات قبل فراغِه منه، وبنى عدَّة مساجد"},{"id":598,"era":"c2","t":"القضاء على طائفة المحمرة الزنادقة في جرجان ببلاد فارس .","s":"ظهرت طائفةٌ بجرجان، يقال لها المحَمِّرة، لَبِسُوا الحُمرةَ واتَّبَعوا رجلًا يقال له عمرُو بن محمد العمركي، وكان يُنسَبُ إلى الزندقة، فبعث الرشيدُ يأمُرُ بقَتلِه، فقُتِلَ، وأطفأ اللهُ نارَهم في ذلك الوقتِ."},{"id":599,"era":"c2","t":"وفاة عبدالله بن المبارك .","s":"هو عبدالله بن المبارك بن واضح، أبو عبد الرحمن الحنظليُّ، مولاهم التركيُّ، ثمَّ المروزي، الحافِظُ الغازي، أحدُ الأعلامِ، كان أبوه تركيًّا وأمُّه تركيَّةً، مِن خوارزمَ، وُلِدَ سنة ثماني عشرة ومائة. وطلبَ العِلمَ وهو ابنُ عشرين سنة، أفنى عمُرَه بالأسفارِ، صَنَّفَ الكتُبَ، وجاهَدَ في سبيلِ اللهِ، وجمَعَ الحديثَ والفقهَ والعربيَّةَ وأيَّامَ النَّاسِ، أوَّلُ مَن صنَّفَ في الجهادِ، اشتهَرَ بالزُّهدِ والو"},{"id":600,"era":"c2","t":"هارون الرشيد يجعل البيعة لولاية العهد لابنه المأمون بعد أخيه الأمين .","s":"أخذ الرَّشيدُ لوَلَدِه عبدِ الله المأمونِ وِلايةَ العَهدِ، من بعد أخيه محمَّد الأمين بن زُبيدة، وذلك بالرقَّةِ بعد مَرجِعِه من الحَجِّ- للمَرَّة الثانية؛ حيث كانت الأولى عام 175هـ-  وضَمَّ ابنَه المأمونَ إلى جعفر بن يحيى البرمكي، وبعثه إلى بغدادَ ومعه جماعةٌ من أهل الرشيدِ خِدمةً له، وولَّاه خراسان وما يتَّصِلُ بها، وسمَّاه المأمون."},{"id":601,"era":"c2","t":"قتال سليمان بن عبدالرحمن لابن أخيه صاحب الأندلس .","s":"جاز سُليمان بن عبد الرحمن بن معاوية إلى بلاد الأندلُسِ من الشرق، وتعَرَّض لحرب ابنِ أخيه الحَكَمِ بن هشام بن عبد الرحمن، صاحِبِ الأندلُس، فسار إليه الحكَمُ في جيوشٍ كثيرة، وقد اجتمع إلى سليمانَ كثيرٌ من أهل الشِّقاقِ ومن يريد الفتنةَ، فالتقيا واقتَتلا واشتدَّت الحربُ، فانهزم سليمانُ واتبَعَه عسكَرُ الحَكَم، وعادت الحربُ بينهما ثانيةً في ذي الحجة، فانهزم فيها سُلَيمان، واعتصَمَ بالوَعْرِ والجبال، ف"},{"id":602,"era":"c2","t":"وفاة القاضي أبي يوسف صاحب أبي حنيفة .","s":"هو أبو يوسُفَ يعقوبُ بن إبراهيم بن حبيب بن حبيش بن سعد بن بجير بن معاوية الأنصاري، الكوفيُّ، وُلِدَ سنة ثلاث عشرة ومائة، لَزِمَ أبا حنيفةَ سبع عشرة سنةً وتتلمَذَ عليه، وكان يعَدُّ من أنبَلِ تلامذتِه وأنجَبِهم، وكان أبو حنيفةَ يتعاهَدُه ويُنفِقُ عليه، كان أميَلَ للمُحَدِّثينَ مِن أبي حنيفة ومِن مُحمَّد بن الحسَن، كان قاضيَ الآفاقِ، ووزيرَ الرَّشيدِ، وزميلَه في حَجِّه، وكان الرشيدُ يُجِلُّه كثيرًا، "},{"id":603,"era":"c2","t":"الخوارج في بلاد الخزر وقتالهم المسلمين .","s":"خرج الخزر بسبب ابنة خاقان من بابِ الأبواب، وقيل: إنَّ سببَ خُروجِهم أنَّ سعيد بن سلم قتَلَ المنجم السلميَّ فدخل ابنُه بلاد الخزر، واستجاشهم على سعيد، فخرجوا ودخَلوا أرمينيَّة من الثُّلمة، فانهزم سعيدٌ، وأقاموا نحو سبعينَ يومًا، وسَبَوا أكثَرَ من مائة ألف رأس، وأوقعوا بالمسلمينَ وأهل الذمَّة أمرًا عظيمًا لم يُسمَعْ بمِثلِه في الأرضِ، فولَّى الرشيدُ أرمينيَّةَ يزيدَ بن مزيد مضافًا إلى أذربيجان، ووجّ"},{"id":604,"era":"c2","t":"وفاة موسى الكاظم بن جعفر الصادق .","s":"هو السَّيِّدُ أبو الحسن العلوي موسى الكاظم بن جعفر الصادق بن محمد الباقر بن علي زين العابدين بن الحسين بن علي بن أبي طالب، والِدُ الإمام علي بن موسى الرضا, المدنِيُّ، ولد سنة ثمان وعشرين ومائة بالمدينةِ ثم نزلَ بغداد,َ لقب بالكاظِمِ لكَظمِه عمَّن أساء إليه، كان مجتهدًا في العبادةِ كريمًا، قيل: إنَّ سبَبَ سَخَطِ الرشيدِ عليه هو أنَّ الرشيدَ لَمَّا زار قبرَ النبيِّ صلَّى اللهُ عليه وسلَّم، قال: السّ"},{"id":605,"era":"c2","t":"هارون الرشيد يعقد لابنه القاسم بولاية العهد بعد أخيه المأمون .","s":"حجَّ الرَّشيدُ ومعه ابناه: الأمينُ محمَّد، والمأمونُ عبد الله، وفَرَّقَ بالحرمينِ الأموالَ، وفيها بايعَ الرَّشيدُ بولايةِ العَهدِ لولده قاسِمٍ بعد الأخوينِ: الأمين والمأمون، ولقَّبَه المُؤتَمَن، وولَّاه الجزيرةَ والثُّغورَ، وهو صبيٌّ."},{"id":606,"era":"c2","t":"هارون الرشيد يولي  إبراهيم بن الأغلب على أفريقية .","s":"تمرَّدَ متولي المغربِ محمَّد بن مقاتل العكي، وظلَم وعسَفَ واقتطَعَ مِن أرزاق الأجنادِ وآذى العامَّةَ، فخرج عليه تمامُ بنُ تميم التميمي نائبُه على تونس، فزحَفَ إليه فبَرَز لملاقاته العكي، فهَزَمه ابنُ تميمٌ، فتحَصَّنَ العكيُّ بالقيروان في القصرِ، وغلَبَ تمَّام على البلد، ثم نزل العكيُّ بأمانٍ وانسحب إلى طرابلس، فنهض لنُصرتِه إبراهيمُ بنُ الأغلب، فتقهقر تمَّام إلى تونُسَ ودخل ابنُ الأغلب القيروانَ، "},{"id":607,"era":"c2","t":"مؤسس دولة الأغالبة في أفريقيا يبني مدينة ويسميها (العباسية) .","s":"بعد أن قام إبراهيمُ بنُ الأغلب بقَمعِ تمَرُّدِ تمَّام بن تميم في أفريقيا، ولَّاه الرشيد، فانقمع الشَّرُّ، وضُبطَ الأمر، وسَيَّرَ تمامًا وكُلَّ مَن يتوثَّبُ الوُلاة إلى الرَّشيد، فسَكَنت البلاد، وابتنى مدينةً سمَّاها العباسيَّة بقُرب القيروان، وانتقَلَ إليها بأهلِه وعَبيدِه."},{"id":608,"era":"c2","t":"سقوط مدينة برشلونة الإسلامية في يد الأسبان .","s":"سقَطَت مدينةُ برشلونة بالأندلُسِ بِيَدِ ملك الفرنج بقيادةِ أذفونش بعد تحالُفِه مع البشكنس- لعَنَهم الله- وأخَذُوها من المسلمينَ، ونقلوا حُماةَ ثغورِهم إليها، وتأخَّرَ المسلمونَ إلى ورائهم. وكان سبَبُ مُلكِهم إيَّاها اشتغال الحَكَم بن هِشامٍ صاحِبِ الأندلس بمحاربةِ عَمَّيه عبد الله وسُليمان."},{"id":609,"era":"c2","t":"هارون الرشيد يجدد وثيقة ولاية العهد لأولاده في جوف الكعبة .","s":"لَمَّا وصل الرشيدُ إلى مكَّة، ومعه أولادُه والفُقَهاء والقُضاة والقُوَّاد، فكتب كتابًا أشهَدَ فيه على محمَّد الأمين، وأشهدَ فيه من حضرَ بالوفاء للمأمونِ، وكتَبَ كتابًا للمأمونِ أشهَدَهم عليه فيه بالوفاءِ للأمين، وعلَّقَ الكتابينِ في الكعبةِ، وجَدَّد العهودَ عليهما في الكعبة. ولَمَّا فعل الرشيد ذلك قال الناس: قد ألقى بينهم شَرًّا وحَربًا. وخافوا عاقبةَ ذلك، فكان ما خافوه."},{"id":610,"era":"c2","t":"هارون الرشيد يجبر إمبراطور البيزنطيين على دفع الجزية .","s":"اضطُرَّت دولةُ الرُّومِ أمام ضَرَباتِ الرشيدِ المتلاحقةِ إلى طلبِ الهُدنة والمصالحة، فعقدت \"إيريني\" مَلِكةُ الرُّومِ صلحًا مع الرشيد، مقابِلَ دفعِ الجزية السَّنوية له في سنة 181هـ، وظلَّت المعاهدة ساريةً حتى نقَضَها إمبراطورُ الروم، الذي خلَفَ إيريني، وكتب إلى هارون: \"مِن نقفور ملكِ الرُّومِ إلى ملِك العَرَب، أمَّا بعدُ؛ فإنَّ المَلِكة إيريني التي كانت قبلي أقامَتْك مقامَ الرُّخِّ، فحَمَلَت إليك م"},{"id":611,"era":"c2","t":"استيلاء الفرنجة على تطيلة في الأندلس واسترجاع المسلمين لها .","s":"استولى الفِرنجُ على مدينة تطيلة بالأندلس، وسبب ذلك أنَّ الحَكَمَ بن هِشامٍ صاحِبَ الأندلُسِ استعمَلَ على ثغورِ الأندلُسِ قائدًا كبيرًا من أجنادِه، اسمُه عمروس بن يوسف، فاستعمل ابنَه يوسُفَ على تطيلة. وكان قد انقلب على الحَكَم بنِ هشام بيتٌ من بيوت الأندلُسِ أولُو قوَّةٍ وبأس؛ لأنَّهم خرجوا عن طاعته، فالتحَقوا بالمُشرِكين، فقَوِيَ أمرُهم، واشتَدَّت شوكتُهم، وتقَدَّموا إلى مدينة تطيلة فحَصَروها ومَل"},{"id":612,"era":"c2","t":"وفاة الفضيل بن عياض .","s":"هو الفُضيلُ بنُ عِياضِ بن مسعود بن بشر التميمي اليربوعي الخراساني، المجاوِرُ بحرم الله، وُلِدَ بسمرقند، ونشأ بأبيورد، وارتحلَ في طلَبِ العلم؛ قال الفضل بن موسى: كان الفضيلُ بنُ عياض شاطِرًا يقطَعُ الطَّريقَ بين أبيورد وسرخس، وكان سبَبُ توبته أنَّه عَشِقَ جارية، فبينا هو يرتقي الجُدران إليها، إذ سَمِعَ تاليًا يتلو {أَلَمْ يَأْنِ لِلَّذِينَ آمَنُوا أَنْ تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ اللَّهِ وَمَا نَ"},{"id":613,"era":"c2","t":"تصفية نفوذ البرامكة في دولة هارون الرشيد .","s":"كان لآلِ بَرْمَك نفوذٌ كبيرٌ في دولة الرشيد؛ إذ كان يحيى بن خالدٍ مُربِّيًا للرشيدِ، وكان أولادُه جعفر والفضل وموسى ومحمَّد أترابَ الرَّشيد، ثمَّ تغيَّرَت أحوالُ البرامكة وتبدَّلَ لهم الرشيدُ فجأةً، فقتل جعفرَ بنَ يحيى وسجَنَ يحيى وابنَه الفضلَ، وصادرَ أملاكَهم، وقد قيل في سبب ذلك أشياءُ؛ منها: أنهم- يعني البرامِكةَ- زاد نفوذُهم كثيرًا، وزادت مصروفاتُهم كثيرًا، حتى فاقوا الخليفةَ بذلك؛ ممَّا جعل أ"},{"id":614,"era":"c2","t":"نَكْثُ نقفور للعهد وغزو الروم .","s":"بعد أن غزا الرشيدُ نقفور وطلبَ الصُّلحَ وقَبِلَ منه، قام نقفور بنكثِ العَهدِ في نفسِ السَّنة، لكن الأمرَ لم يصِلْ إلى الرشيدِ إلَّا بعد سنةٍ؛ للبَردِ الشَّديد الذي منع وصولَ البريدِ، فغزا إبراهيمُ بن جبرئيل الصائفة، فدخل أرضَ الروم من درب الصفصاف، فخرج إليه نقفور ملكُ الروم، فأتاه مِن ورائه أمرٌ صَرَفه عنه، ولَقِيَ جمعًا من المسلمين، فجرح ثلاث جِراحات، وقُتِلَ مِن الروم- فيما قيل- أربعون ألفًا وسب"},{"id":615,"era":"c2","t":"وفاة علي بن حمزة الكسائي .","s":"هو أبو الحسنُ عليُّ بن حمزة بن عبد الله بن بهمن بن فيروز الأسدي مولاهم الكوفيُّ الملقَّبُ بالكسائيِّ؛ لكساءٍ أحرَمَ فيه، وُلِدَ بالكوفةِ نحو 120هـ, اختار قراءةً اشتَهَرت عنه، وصارت إحدى القراءاتِ السَّبع، وجالس في النحو الخليلَ، وسافر في بادية الحجازِ مُدَّةً للعربيَّة، قال الشافعي: \"من أراد أن يتبحَّرَ في النحو فهو عيالٌ على الكسائيِّ\". وقال ابن الأنباري: \"اجتمع في الكسائيِّ أمور: كان أعلمَ النَّ"},{"id":616,"era":"c2","t":"وفاة محمد بن الحسن الشيباني صاحب أبي حنيفة .","s":"هو العلَّامة، فقيهُ العراق أبو عبد الله محمد بن الحسن بن فرقد الشَّيباني ولاءً، أصلُه من الغوطة، صاحِبُ أبي حنيفة، ولد سنة 131هـ بواسط, نشأ في الكوفة فسَمِعَ من أبي حنيفة، وأخذ عنه طريقتَه، لم يجالِسْه طويلًا لوفاة أبي حنيفة، فأتمَّ الطريقةَ على أبي يوسف، رحل إلى المدينةِ وأخذ عن الإمامِ مالكٍ، واتَّصل بالشافعيِّ، وكان بينهما مناظراتٌ معروفةٌ، تولى القضاءَ للرَّشيدِ ثمَّ اعتزل القضاءَ وتفَرَّغ لتع"},{"id":617,"era":"c2","t":"فدية أسارى المسلمين من بلاد الروم .","s":"رابَطَ في هذه السنة القاسِمُ بن الرشيد في مرج دابق، وفادى الرشيدُ الأُسارى من المسلمين الذين كانوا في بلاد الرومِ، حتى لم يبقَ أسيرٌ واحِدٌ."},{"id":618,"era":"c2","t":"شَغبُ أهل المغرب على وُلاتِهم من دولة الأغالبة .","s":"كثُرَ شَغبُ أهل طرابلس الغرب على وُلاتِهم، وكان إبراهيمُ بن الأغلب أميرُ إفريقيَّةَ قد استعمَلَ عليهم عِدَّةَ وُلاةٍ، فكانوا يَشكُون من وُلاتِهم، فيَعزِلُهم، ويولِّي غَيرَهم، فاستعمل عليهم هذه السَّنةَ سُفيانَ بنَ المضاء، وهي ولايتُه الرابعة، فاتَّفق أهلُ البلد على إخراجه عنهم، وإعادتِه إلى القيروان، فزَحَفوا إليه، فأخذ سلاحَه، وقاتَلَهم هو وجماعةٌ ممَّن معه، فأخرجوه من داره، فدخل المسجِدَ الجامع،"},{"id":619,"era":"c2","t":"المسلمون يعاودون غزو قبرص  .","s":"نقَضَ أهلُ قُبرص العهدَ، فقام معيوف بن يحيى أميرُ سواح الشامِ ومصر بالسَّيرِ إليهم بأسطولٍ كبيرٍ، فغزاهم وأسَرَ أسقُفَهم وسبى من أهلِها الكثيرَ، وقتل الكثيرَ، ثم سار إلى جزيرة كريت ورودوس."},{"id":620,"era":"c2","t":"فتنة رافع بن الليث بن سيَّار في سمرقند .","s":"كان رافِعُ بن نصرِ بنِ الليث بن سيَّار من عظماء الجندِ فيما وراء النهر، وكان يحيى بن الأشعَثِ الطائي قد تزوَّجَ ابنةَ عَمٍّ له، وكانت ذاتَ يَسارٍ ولِسانٍ وجَمالٍ, ثم ترَكَها بسمرقند فترةً وأقام ببغداد، واتَّخذَ السَّراريَّ، فلما طال ذلك عليها، أرادت أن تخلصَ مِن زواجها له, فعَلِمَ رافِعٌ بأمرِها فتزوَّجَها بعد أن قال لها أن تُظهِرَ الشِّركَ ثم تتوبَ فيَنفَسِخَ نِكاحُها, فشكاه زوجُها يحيى بن الأشعث"},{"id":621,"era":"c2","t":"خروج رافع بن الليث بن نصر في خراسان .","s":"خلع رافِعُ بنُ الليث بن نصر بن سيَّار نائبُ سمرقند الطاعةَ، ودعا إلى نفسِه، وتابعه أهلُ بلَدِه وطائفةٌ كثيرةٌ من تلك الناحية، واستفحل أمرُه، فسار إليه نائِبُ خراسان علي بن عيسى، فهزمه رافِعٌ وتفاقم الأمر به. فجمَعَ له عليُّ بن عيسى جيشًا لقِتالِه، فلما قَتَل رافِعُ بن الليثِ عيسى بن علي خرج عليُّ بن عيسى مِن بَلْخ حتى أتى مرْوًا مخافةَ أن يسيرَ إليها رافع بن الليث، فيستولي عليها، فلما علم الرشيد ب"},{"id":622,"era":"c2","t":"فتح هرقلة  .","s":"فتح الرَّشيدُ هرقلةَ، وكان سببُ مَسيرِه إليها ما حصل سنةَ سبعٍ وثمانين ومائة، من غَدرِ نقفور، فحاصرَ الرَّشيدُ هرقلة ثلاثين يومًا وسَبى أهلَها، وكان قد دخل البلادَ في مائة ألف وخمسة وثلاثين ألفًا من المرتَزِقة، سوى الأتباعِ والمتطَوِّعة، ومَن لا ديوان له، وأناخ عبدُ الله بن مالك على ذي الكلاع، ووجَّه داود بن عيسى بن موسى سائرًا في أرضِ الرُّوم في سبعين ألفًا، ففتَحَ الله عليه، وفتح شراحيل بن معن ب"},{"id":623,"era":"c2","t":"هارون الرشيد يأمر بتمييز لباس أهل الذمة في بغداد .","s":"أمرَ الرَّشيدُ بهَدمِ الكنائسِ والدُّورِ بالثُّغور، وألزم أهلَ الذمَّة بتمييزِ لباسِهم وهيئاتِهم ورَكوبِهم عن المُسلمين في بغداد وغَيرِها من البلاد."},{"id":624,"era":"c2","t":"وقعة الحفرة في أهل طليطلة .","s":"أوقع الأميرُ الحكَمُ بنُ هشام- صاحب الأندلس- بأهل طليطِلة، فقتلَ منهم ما يزيدُ على خمسةِ آلاف رجلٍ مِن أعيان أهلِها، وسببُ ذلك أنَّ أهلَ طُليطِلة كانوا قد طَمِعوا في الأمراءِ، وخَلَعوهم مرَّةً بعد أخرى، وقَوِيَت نفوسُهم بحصانةِ بلَدِهم وكثرةِ أموالِهم، فلم يكونوا يطيعونَ أمراءَهم طاعةً مُرضيةً، فلما أعيا الحكَمَ شأنُهم أعمل الحيلةَ في الظفَرِ بهم، فاستعان في ذلك بعَمروس بن يوسف المعروف بالمولد، حي"},{"id":625,"era":"c2","t":"هزيمة لزريق بالأندلس .","s":"تجهَّزَ لذريق ملك الفرنج بالأندلس، وجمعَ جموعَه ليسيرَ إلى مدينة طرطوشة ليحصرَها، فبلغ ذلك الحكَمَ بنَ هشامٍ صاحِبَ الأندلس، فجمع العساكِرَ وسيَّرَها مع ولده عبد الرحمن، فاجتمعوا في جيشٍ عظيمٍ، وتَبِعَهم كثيرٌ من المتطَوِّعة، فساروا فلَقُوا الفرنج في أطرافِ بلادهم قبل أن ينالوا من بلادِ المسلمينَ شيئًا، فاقتتلوا وبذلَ كُلٌّ من الطائفتين جُهدَه، واستنفَدَ وُسعَه، فأنزل الله تعالى نَصرَه على المسلمي"},{"id":626,"era":"c2","t":"خروج ثروان الحروري بسواد العراق .","s":"خرج رجلٌ بسَوادِ العِراقِ يُقالُ له ثروانُ بن سيف الحروري، وجعل يتنقَّلُ فيها من بلدٍ إلى بلد، فوَجَّه إليه الرشيدُ طَوقَ بن مالك فهَزَمَه، وجُرِحَ ثروان وقُتِلَ عامَّةُ أصحابه، وكتبَ بالفتح إلى الرَّشيد، لكِنَّ ثروان هرب فنجا من القتل."},{"id":627,"era":"c2","t":"تأسيسُ مدينة فاس في المغرب .","s":"تم تأسيسُ مدينة فاس على يدِ إدريس الأوَّل مؤسِّس دولة الأدارِسة في المغرب، وليس إدريس الثاني كما هو شائِعٌ."},{"id":628,"era":"c2","t":"وفاة الخليفة العباسي هارون الرشيد .","s":"هو هارونُ الرَّشيدُ أميرُ المؤمنينَ ابنُ المهديِّ محمد بن أبي جعفر المنصور، أبو محمد، ويقال أبو جعفر. وأمُّه الخَيزُران أمُّ ولَدٍ. كان مولِدُه في شوَّال سنة 147هـ وقيل غيرُ ذلك, وبويِعَ له بالخلافةِ بعد موت أخيه الهادي في ربيع الأوَّل سنة 170هـ، بعهدٍ مِن أبيه المهدي. وكان الرشيدُ أبيضَ طويلًا سمينًا جَميلًا، وقد غزا الصائفةَ في حياة أبيه مرارًا، وعقد الهدنةَ بين المسلمين والرومِ بعد محاصرتِه الق"},{"id":629,"era":"c2","t":"الأمين يتولى خلافة الدولة العباسية  .","s":"كان الرَّشيدُ قد عقد الخلافةَ لابنه الأمينِ ثمَّ للمأمونِ لِمَكانةِ زبيدة والدةِ الأمينِ، وإلَّا فالمأمونُ أكبَرُ منه، فبويع الأمينُ بالخلافة في عسكرِ الرشيد، صبيحةَ الليلة التي توفِّيَ فيها، وكان المأمونُ حينئذ بمرو، فكتب حمويه مولى المهديِّ، صاحبُ البريدِ، إلى نائبِه ببغداد- وهو سلام بن مسلم- يُعلِمُه بوفاةِ الرشيد، فدخل أبو مسلمٍ على الأمينِ فعَزَّاه وهنَّأه بالخلافة، فانتقل مِن قصرِه بالخُلد إ"},{"id":630,"era":"c2","t":"الأمين يعلن خلع أخويه المأمون والمؤتمن من ولاية العهد .","s":"كان الرَّشيدُ في أثناء مسيرِه إلى خراسانَ، وكان المأمونُ في مرو بخُراسان، وكان الأمينُ في بغداد، فأخذ الرشيدُ البيعةَ مِن جُندِه الذين معه أن يطيعوا للمأمونِ ويَبقَوا معه، ولكِنَّ الفَضلَ بنَ الربيعِ عاد بالجُندِ إلى بغداد، ثم أوحى للأمينِ أن يَعقِدَ البيعةَ لابنِه موسى ثمَّ للمأمونِ، فلمَّا علم بذلك المأمونُ قَطَعَ البريدَ عن الأمينِ وأسقطَ اسمَه من الطرز، وأمَّنَ رافِعَ بنَ اللَّيثِ وأكرَمَه، كم"},{"id":631,"era":"c2","t":"عصيان أهل ماردة على الحكَم بن هشام أميرِ الأندلُس .","s":"في هذه السَّنةِ عاود أهلُ ماردة الخلافَ على الحكَم بن هشام أميرِ الأندلُس، وعصُوا عليه، فسار بنَفسِه إليهم وقاتَلَهم، ولم تَزَل سراياه وجيوشُه تتردَّدُ وتقاتِلُهم على مدى ثلاثِ سَنَوات."},{"id":632,"era":"c2","t":"خلاف أهل تونس على ابن الأغلب .","s":"تمرَّدَ عِمرانُ بن مجالد الربيعيُّ، وقُريشُ بن التونسي بتونُسَ على إبراهيمَ بنِ الأغلب أميرِ إفريقيَّةَ، واجتمع فيها خلقٌ كثير، وحُصِرَ إبراهيمُ بن الأغلب بالقصرِ وجمعٌ ممَّن أطاعه، وخالفَ عليه أيضًا أهلُ القيروان، فكانت بينهم وقعةٌ وحَربٌ قُتِلَ فيها جماعةٌ مِن رجالِ ابن الأغلب. وقَدِمَ عِمرانُ بنُ مجالد فيمن معه، فدخل القيروانَ عاشر رجب، وقَدِمَ قُريش من تونس عليه، فكانت بينهم وبين ابن الأغلبِ و"},{"id":633,"era":"c2","t":"موقعة الري وهزيمة جيوش الأمين أمام جيش المأمون .","s":"عقَد الأمينُ لعليِّ بنِ عيسى بن ماهان بالإمرةِ على الجبل وهمذان وأصبهان وقُم، وأمره بحربِ المأمونِ، وجَهَّزَه بجيشٍ كبير، فلمَّا وصل الجيشُ إلى الريِّ تلقَّاه طاهِرُ بن الحسين قائِدُ المأمون، فاقتتَلَ الطرفانِ، فقُتِلَ عليُّ بنُ عيسى بن ماهان، وانهزم جيشُه، ولَمَّا وصل الخبرُ إلى الأمين جهَّز جيشًا آخر بإمرةِ عبدالرحمن بن جَبَلة الأنباريِّ، ولكنَّه هُزِمَ هو أيضًا، فهرب بجيشِه إلى همذان، وطلب الأم"},{"id":634,"era":"c2","t":"ظهور السفياني في الشام .","s":"ظهَرَ السُّفيانيُّ بدمشقَ وبويع بالخلافةِ، واسمُه عليُّ بن عبد الله بن خالد بن يزيد بن معاوية بن أبي سفيان، وطرَدَ عامِلَ الأمينِ عن دمشق- وهو سليمانُ بن أبي جعفر- بعد أن حصَرَه السفيانيُّ بدمشق مدَّةً، ثمَّ أفلت منه، وخالد بن يزيد جدُّ السفياني هذا، هو الذي وضع حديثَ السُّفياني في الأصل؛ فإنَّه ليس بحديثٍ، غيرَ أن خالدًا لَمَّا سَمِعَ حديثَ (المهديُّ من أولادِ عليٍّ في آخِرِ الزَّمانِ) أحَبَّ أن "},{"id":635,"era":"c2","t":"الحكم بن هشام ينتصر لأهل الثغور .","s":"لَمَّا انشغل الحكَمُ بن هشام بإخماد عِصيانِ أهل مارد. طمِعَ الفرنج في ثغورِ المسلمين، وقَصَدوها بالغارة والقتل، والنَّهبِ والسَّبي، فأتاه الخبَرُ بشِدَّة الأمر على أهل الثغر، وما بلغ العدوُّ منهم، وسَمِعَ أنَّ امرأةً مُسلمةً أُخِذَت سبيةً، فنادت: واغَوْثاه، يا حَكَمُ! فعَظُمَ الأمر عليه، وكان قد فرَغ من أهل ماردِ، فجمَعَ عَسكَرَه واستعَدَّ وحَشَد وسار إلى بلد الفرنج, وأثخَنَ في بلادهم، وافتتح عِدّ"},{"id":636,"era":"c2","t":"وفاة أبي نواس الشاعر .","s":"هو الحسَنُ بن هانئ بن صباح بن عبد الله، اشتهر بالشِّعرِ، ولكنَّه أدخل فيه ما يُستقذَرُ، حتى اتُّهِم، ذكروا له أمورًا كثيرة، ومُجونًا وأشعارًا مُنكَرة، وله في الخَمريَّات والقاذورات والتشبُّب بالمُردان والنِّسوان أشياءُ بِشَعةٌ شَنيعةٌ؛ فمِن النَّاسِ من يفَسِّقُه ويرميه بالفاحشةِ، ومنهم من يرميه بالزَّندقة،  كان أبو نواس شاعِرَ الأمينِ بن الرشيد وأحدَ نُدَمائه، وقد قال في الأمين مدائِحَ حِسانًا، وق"},{"id":637,"era":"c2","t":"انقلاب داخلي في بغداد على الخليفة العباسي الأمين .","s":"كان الأمينُ قد أرسل عبدالملك بن صالح بن عليٍّ إلى الشام ليجمَعَ له الجُندَ، لكنَّه توفي في الرقَّة، فتولى أمرَ الجُندِ الحُسينُ بن علي بن ماهان، فعاد بهم إلى بغداد، ورفض القدومَ على الأمين الذي أرسلَ إليه من يُحضِرُه، فاقتتل الطرفانِ وانهزم الجمعُ الذين أرسَلَهم الأمين، فخلَعَ الحُسَينُ الأمينَ يومَ الأحدِ لإحدى عشرة ليلةً خلَت من رجب، وأخذ البيعةَ للمأمونِ مِن الغدِ يوم الاثنين، فلما أصبح الناسُ "},{"id":638,"era":"c2","t":"توقيع اتفاق حسن الجوار بين الدولة الرستمية ودولة الأغالبة .","s":"ثار أبو عصامٍ ومَن وافقه على إبراهيمَ بن الأغلب، أميرِ إفريقيَّة، فحاربهم إبراهيمُ، فظَفِرَ بهم. واستعمل ابنُ الأغلب ابنَه عبدالله على طرابلس الغرب، فلما قدِمَ إليها ثار عليه الجُندُ، فحصروه في داره، ثم اصطَلَحوا على أن يخرُجَ عنهم، فخرج عنهم، فلم يُبعِد عن البلد حتى اجتمع إليه كثيرٌ من الناس، ووضَعَ العطاء، فأتاه البربرُ من كل ناحية، فاجتمع له عددٌ كثير، فزحف بهم إلى طرابلس، فخرج إليه الجُند، فاق"},{"id":639,"era":"c2","t":"تخريب مدينة بغداد واستسلام الخليفة العباسي الأمين .","s":"بعد أن عادت الأمور في بغداد للأمين، كان جيشُ المأمون بقيادة طاهر بن الحسين وهَرثمةَ بنِ أعيَنَ قادمًا إلى بغداد، فلمَّا اقتَرَبوا منه عادت الفوضى وخَلَعَت بعضُ الأقاليم الأمين وبايَعَت للمأمون، حتى إنَّ موسم الحج دُعِيَ فيه للمأمون، ثم حاصر الجيشُ بغداد فضَعُفَ أمر الأمين وخاصَّةً أنَّ طاهِرَ بنَ الحسين قد استولى على الضِّياعِ والإنتاجِ، وأجابه كثير من قوَّاد الأمين إلى بيعةِ المأمون، ثم دخل جيشُ "},{"id":640,"era":"c2","t":"وفاة جابر بن حيان عالم الكيمياء  .","s":"هو جابِرُ بنُ حيان بن عبد الله الأزدي أبو الكيمياء، فيلسوفٌ كيميائيٌّ، ولد عام 101هـ كان يُعرَف بالصوفي. من أهل الكوفة، وأصلُه من خراسان، له تصانيف كثيرة، قيل: عددها 232 كتابًا، وقيل: بلغت خمسَمائة. ضاع أكثَرُها، وتُرجِمَ بعضُ ما بقي منها إلى اللاتينية، منها أسرار الكيمياء، وعلم الهيئة، وأصول الكيمياء، وقد اشتملت كتبُه على بيان مركَّبات كيماويَّة كانت مجهولةً قبله. وهو أوَّلُ من وصف أعمالَ التقطير"},{"id":641,"era":"c2","t":"وقعة الميدان بين اليمانية والنِّزارية في الموصل .","s":"كانت بين اليمانية والنِّزارية وكان سببُها أنَّ عُثمانَ بنَ نُعيم البرجمي صار إلى ديارِ مُضَر، فشكا الأزدَ واليمن، وقال: إنَّهم يغلبونَنا على حُقوقنا واستنصَرَهم، فسار معه إلى الموصِل ما يقارب عشرين ألفًا, فأرسل إليهم عليُّ بن الحسن الهمداني، وهو حينئذٍ متغَلِّبٌ على الموصِل، فسألهم عن حالهم، فأخبَروه، فأجابهم إلى ما يريدون، فلم يقبَلْ عثمان ذلك، فخرج إليهم عليُّ بن الحسَن مِن الموصِل في نحو أربعةِ"},{"id":642,"era":"c2","t":"غزو الحكم بن هشام لسمورة .","s":"همَّت الرُّوم بما لم ينالوا من طلَبِ الثغور، فنكَثوا العهدَ، فتجهَّزَ الحكَمُ بن هشامٍ إليهم حتى جاز جبلَ السارة شماليَّ طليطلة، ففرَّت الرومُ أمامه حتى تجمَّعوا بسمورة، فلما التقى الجمعانِ، نزل النصرُ وانهزم الكفرُ، وتحصَّنوا بمدينة سمورة، وهي كبيرة جدًّا، فحصرها المسلمون بالمجانيق، حتى افتَتَحوها عَنوةً، وملكوا أكثَرَ شوارعِها، واشتغل الجندُ بالغنائم، وانضمَّت الرومُ إلى جهة من البلد، وخرجوا على"},{"id":643,"era":"c2","t":"اغتيال الأمين بن هارون الرشيد في السجن .","s":"لَمَّا كان الأمرُ من دخولِ جيشِ المأمون واستيلائِه على بغداد، وأخْذِ الأمينِ الأمانَ مِن هرثمة بن أعيَن، وكان قد سيَّرَه في السفينة، فعَلِمَ بذلك طاهر بن الحسين، فغضب لذلك كثيرًا؛ لأنَّ الأمينَ لم يطلُبْ منه الأمانَ، بل طلبه من هرثمةَ بنِ أعيَن، فقام بإغراقِ السَّفينةِ، ولكنَّ الأمينَ سبح ونجا، وكان بعضُ الجندِ قد أسَروه ووضعوه في أحدِ البُيوتِ، فدسَّ طاهِرٌ إليه بعضَ العجَمِ فقتلوه في البيتِ الذي"},{"id":644,"era":"c2","t":"وفاة الأمين بن هارون الرشيد .","s":"هو محمَّد الأمين بن هارون الرشيد بن محمد المهدي بن المنصور، أبو عبد الله، ويقال: أبو موسى الهاشمي العباسي، وأمه أمُّ جعفر زبيدة بنت جعفر بن أبي جعفر المنصور، كان مولده بالرصافة سنة سبعين ومائة, وأتته الخلافةُ بعد وفاة والده الرشيدِ بوصيةٍ منه له بولايةِ العهد، ثمَّ نازعه أخوه المأمونُ على الخلافة. كان طويلًا سمينًا أبيضَ أقنى الأنفِ صغيرَ العينين، عظيمَ الكراديس، بعيدًا ما بين المنكِبَين. وقد رماه"},{"id":645,"era":"c2","t":"تولي المأمون للخلافة العباسية  .","s":"بعد أن تمَّ قتلُ الأمينِ في حَبسِه والاستيلاءِ على بغداد، أُخِذَت البيعةُ بالكاملِ للمأمونِ الذي بقي في مَرْو، وولَّى الحسَنَ بنَ سَهلٍ البصرةَ والكوفة والحجازَ واليمن والأهواز، وولَّى غيرَه المناطق الأخرى."},{"id":646,"era":"c2","t":"وفاة سفيان بن عيينة .","s":"هو محَدِّثُ الحرَمِ المكِّي، الحافِظُ المشهورُ: سُفيان بن عُيَينة بن أبي عمران يكنَّى أبا محمد. وهو مولى لبني عبد الله بن رويبة، وُلِد سنةَ سبعٍ ومائة بالكوفةِ، انتقل إلى مكَّةَ وبقي فيها، قال الشافعي: لولا مالِكٌ وسفيان لذهب عِلمُ الحجاز، كان واسِعَ العِلم، كبيرَ القَدرِ، مع زهدٍ وورَعٍ، له المُسند الجامِعُ، وتفسير القرآن، توفِّي في مكَّة- رحمه الله وجزاه عن الإسلامِ والمسلمين خيرًا."},{"id":647,"era":"c2","t":"العلويون يثورون على العباسيين في الكوفة .","s":"ظهر أبو عبدِ الله محمد بن إبراهيم بن إسماعيل بن إبراهيم بن الحسن بن الحسن بن علي بن أبي طالب، بالكوفةِ، يدعو إلى الرِّضا من آل محمَّد صلَّى الله عليه وسلَّم والعمَل بالكتابِ والسُّنَّة، وهو الذي يُعرَف بابنِ طباطبا، وكان القيِّم بأمرِه في الحرب أبو السَّرايا السَّري بن منصور، وكان سببُ خروجه أنَّه شاع أنَّ الفضلَ بنَ سَهلٍ قد غلب على المأمونِ، وأنَّه يستبِدُّ بالأمر دونه، فغَضِبَ لذلك بنو هاشم ووج"},{"id":648,"era":"c2","t":"ظهور إبراهيم بن موسى (الجزار) بمكة .","s":"ظهر إبراهيمُ بن موسى بن جعفر بن محمد، وكان بمكَّةَ، فلما بلغَه خبَرُ أبي السرايا وما كان منه سار إلى اليمن، وبها إسحاقُ بن موسى بن عيسى بن موسى بن محمد بن علي بن عبد الله بن عباس عاملًا للمأمون، فلمَّا بلغه قُربُ إبراهيمَ من صنعاء، سار منها نحوَ مكة فأتى المشاش، فعسكَرَ بها واجتمع بها إليه جماعةٌ من أهل مكة هَرَبوا من العلويِّينَ، واستولى إبراهيمُ على اليمن، وكان يسمَّى الجزَّار؛ لكثرة من قتَل بال"},{"id":649,"era":"c2","t":"خروج البربر بناحية مورور في الأندلس .","s":"خرج خارجيٌّ من البربر بناحية مورور، من الأندلس، ومعه جماعةٌ، فوصل كتابُ العامل إلى الحكَمِ بنِ هشام بخبَرِه، فأخفى الحكَمُ خبَرَه، واستدعى من ساعته قائدًا من قوَّاده، فأخبَرَه بذلك سرًّا، وقال له: سِرْ مِن ساعتِك إلى هذا الخارجيِّ فأْتِني برأسه، وإلَّا فرأسُك عِوَضَه، وأنا قاعِدٌ مكاني هذا إلى أن تعود. فسار القائِدُ إلى الخارجيِّ، فلما قاربه سأل عنه، فأُخبِرَ عنه باحتياطٍ كثيرٍ، واحترازٍ شديدٍ، ثم"},{"id":650,"era":"c2","t":"عبث زيد النار بالبصرة .","s":"كان بالبصرة من الطالبيين زيدُ بنُ موسى بن جعفر بن محمد بن علي بن حسين بن علي بن أبي طالب، ومعه جماعةٌ من أهل بيته، وهو الذي يقال له زيد النار وإنما سمِّيَ زيدَ النارِ؛ لكثرة ما حرَقَ مِن الدُّور بالبصرة من دور بني العبَّاسِ وأتباعهم، وكان إذا أتِيَ برجلٍ مِن المسودة كانت عقوبتُه عنده أن يحرِقَه بالنَّارِ، وانتهب أموالَ تجَّار البصرة، فأخذه عليُّ بن أبي سعيد أسيرًا، وقيل: إنه طلَبَ الأمانَ فأمَّنه."},{"id":651,"era":"c2","t":"مبايعة محمد بن جعفر (الديباج) بمكة .","s":"لَمَّا وصل الحُسَين بن حسن الأفطس لِمَكَّة من قِبَل أبي السرايا وفعل في مكَّة ما فعل من تغييرِ كسوةِ الكعبةِ وتخريبٍ ونَهبٍ، وصلَه خبرُ هزيمة أبي السرايا، ذهب إلى محمد بن جعفر بن محمد بن علي بن الحسين وبايعه فأقامه، وبايَعه بالخلافةِ، وجمع له النَّاسَ، فبايعوه طوعًا وكَرهًا وسَمَّوه أمير المؤمنين، فبقي شهورًا وليس له من الأمرِ شَيءٌ، ثمَّ لَمَّا وصل عامِلُ اليمن وجيشُ هرثمة بن أعين من الكوفةِ، هرب"},{"id":652,"era":"c2","t":"ثورة الطالبيين ببغداد بعد مقتل هرثمة بن أعين .","s":"لَمَّا هزَمَ هَرثمةُ بنُ أعين أبا السرايا ومن كان معه من وُلاة الخلافة، وهو محمد بن محمد، وشَى بعضُ الناس إلى المأمون أنَّ هرثمة راسلَ أبا السرايا وهو الذي أمره بالظُّهور، فاستدعاه المأمونُ إلى مروٍ فأمر به فضُرِبَ بين يديه ووُطِئَ بطنُه، ثمَّ رفع إلى الحبس ثم قُتِلَ بعد ذلك بأيام، وانطوى خبَرُه بالكلية. ولَمَّا وصل بغدادَ خبَرُ قتلِه عَبَثَت العامَّة والحربيَّة بالحسن بن سهل نائب العراق، وقالوا: "},{"id":653,"era":"c2","t":"وصول المسلمين إلى وسط بلاد الفرنج بالأندلس .","s":"جهَّز الحَكَمُ بنُ هِشامٍ أميرُ الأندلس جيشًا مع عبد الكريم بن مُغيث إلى بلاد الفرنج بالأندلس، فسار بالعساكرِ حتى دخل بأرضِهم، وتوسَّط بلادَهم، فخَرَّبَها ونهبَها وهدمَ عِدَّةً مِن حصونها، كلما أهلك موضعًا وصل إلى غيرِه، فاستنفد خزائِنَ مُلوكِهم. فلما رأى مَلِكُهم فِعْلَ المسلمين ببلادِهم، كاتَبَ ملوكَ جميع تلك النواحي مستنصِرًا بهم، فاجتمعت إليه النصرانيَّة مِن كُلِّ صَوبٍ، فأقبل في جموعٍ عظيمة ب"},{"id":654,"era":"c3","t":"فتح المسلمين جبال طبرستان والديلم .","s":"افتتح عبدُ الله بن خرداذبة والي طبرستان البلاذرَ، والشيزرَ، من بلاد الديلم، وافتتح جبالَ طبرستان، فأنزل شهريار بن شروين عنها، وأشخَصَ مازيار بن قارن إلى المأمون، وأسَرَ أبا ليلى ملكَ الديلم."},{"id":655,"era":"c3","t":"فتنة العباسيين ضد الخليفة المأمون .","s":"كان سبَبُ ذلك أن المأمونَ جعل عليَّ بنَ موسى الرضا بن جعفر بن محمد بن علي بن الحسين بن علي بن أبي طالب، وليَّ عهدِ المسلمين والخليفةَ من بعده، ولقَبَّه الرضا من آل محمد، وأمَرَ جُندَه بطرح السَّواد ولُبس الثياب الخُضر، وكتب بذلك إلى الآفاقِ، وكتب الحسَنُ بن سهل إلى عيسى بن محمد بن أبي خالد بعد عودِه إلى بغداد يُعلِمُه أنَّ المأمون قد جعل عليَّ بن موسى وليَّ عَهدِه من بعده. وذلك أنه نظرَ في بني الع"},{"id":656,"era":"c3","t":"فتنة مبايعة أهل بغداد لإبراهيم بن المهدي .","s":"لَمَّا جاء الخبَرُ أن المأمونَ بايع لعليِّ الرضا بن موسى الكاظم بن جعفر الصادق بن محمد بن الحسين بالولايةِ مِن بعده؛ وذلك أن المأمون رأى أنَّ عليًّا الرضا خيرُ أهل البيت، وليس في بني العباس مثلُه في عِلمِه ودينِه، فجعله وليَّ عهده من بعده- اختلفوا فيما بينهم، فمِن مجيبٍ مبايعٍ، ومِن آبٍ ممانعٍ، وجمهورُ العباسيِّين على الامتناعِ من ذلك، وقام في ذلك ابنا المهديِّ إبراهيم ومنصور، فلما كان يوم الثلاثا"},{"id":657,"era":"c3","t":"وفاة أبي العباس عبد الله بن إبراهيم بن الأغلب .","s":"أبو العبَّاسِ عبد الله الأول بن إبراهيم أحدُ حكَّام الأغالبة، تولَّى بعد وفاة والده إبراهيمَ بنِ الأغلب سنة 196هـ. وكان أبو العباس يلي طرابلُس لأبيه، فأخذ أخوه زيادةُ الله البيعةَ له من رؤساء الجند، ثم دخل القيروان سنة 197هـ, وأقَرَّه الخليفةُ المأمون على ما بيده من إفريقيَّة. عامَلَ أبو العباس سكَّانَ البلاد معاملةً تنطوي على الكثيرِ مِن العنَتِ والجَور، ولم يُصغِ إلى نصائحِ أهل الرأي فيها. وعدَّ"},{"id":658,"era":"c3","t":"ولاية زيادة الله بن إبراهيم بن الأغلب إفريقية .","s":"لَمَّا توفِّيَ أبو العباس عبد الله بن إبراهيم بن الأغلب، أميرُ إفريقيَّة، ولِيَ بعده أخوه محمَّد زيادةُ الله بن إبراهيم، وبقي أميرًا رخِيَّ البالِ وادعًا والدنيا عنده آمِنة. ثم جهَّزَ جيشًا في أسطولِ البحرِ إلى مدينة سردانية، وهي للروم، فعطب بعضُها بعد أن غَنِموا من الروم، وقتلوا كثيرًا، فلمَّا عاد مَن سلِمَ منهم أحسَنَ إليهم زيادةُ الله ووصَلَهم."},{"id":659,"era":"c3","t":"مبايعة أهل بغداد لإبراهيم بن المهدي .","s":"بايع أهلُ بغداد إبراهيمَ بن المهدي بالخلافة، ولقَّبوه المبارك، وخلعوا المأمون، وبايعه سائِرُ بني هاشم، فكان المتولِّي لأخذ البيعةِ المطَّلِب بن عبدالله بن مالك، فكان الذي سعى في هذا الأمر السِّندي، وصالحًا صاحِبَ المصلَّى، ونَصيرًا الوصيفَ، وغيرَهم؛ غضبًا على المأمونِ حين أراد إخراجَ الخلافة من ولَدِ العباس، ولِتَركِه لباسَ آبائِه من السَّواد. فلما فرغَ مِن البيعةِ وعد الجُندِ رِزقُ سِتَّة أشهر، و"},{"id":660,"era":"c3","t":"فتنة خلع الحكم بن هشام في الأندلس .","s":"عزَّ على علماء الأندلس انتهاكُ الحكَمِ بنِ هشام للحُرُمات، وأْتَمَروا ليخلعوه، ثم جيَّشوا لقتاله، وجَرَت بالأندلس فتنةٌ عظيمة على الإسلام وأهلِه- فلا قوة إلا بالله- فلمَّا هَمَّ العُلَماءُ بخلعِ الحَكَمِ، قالوا: إنَّه غيرُ عدلٍ، ونكَثُوه في نفوس العوامِّ، وزعموا أنَّه لا يحِلُّ المُكثُ ولا الصبرُ على هذه السيرةِ الذَّميمةِ، وكان ممن تقدَّمَ العلماءَ في الدعوةِ لخلعِ الحكَمِ بن هشام يحيى بن يحيى ال"},{"id":661,"era":"c3","t":"مسير المأمون للعراق وقتل ذي الرياستين الفضل بن سهل .","s":"أقبل المأمونُ من خراسان قاصدًا العراق، وذلك أنَّ علي بن موسى الرضا أخبر المأمونَ بما النَّاسُ فيه من الفِتَن والاختلافِ بأرض العراق، وبأنَّ الهاشميِّينَ قد أنهَوا إلى الناس بأنَّ المأمونَ مَسحورٌ ومَسجونٌ، وأنَّهم قد نَقَموا عليك ببيعتِك لعليِّ بن موسى، وأنَّ الحرب قائمة بين الحسَنِ بنِ سَهلٍ وبين إبراهيم بن المهدي. فاستدعى المأمونُ جماعةً مِن أمرائه وأقربائه فسألهم عن ذلك فصدَّقوا عليًّا فيما قال"},{"id":662,"era":"c3","t":"موقعة أهل الربض بقرطبة .","s":"من أشهَرِ الثَّوراتِ التي قمَعها الحكَمُ بن هشام ثورة ُالربض، وهم قومٌ كانوا يعيشونَ في إحدى ضواحي قُرطُبة، وقد ثار أهلُها ثورةً كبيرة جدًّا عليه؛ بسبب ما عُرِفَ عنه من معاقرةِ الخَمرِ، وتشاغُلِه باللهوِ والصَّيد، وقد زاد من نقمةِ الشَّعبِ عليه قتلَه لجماعةٍ مِن أعيان قُرطبة، فكرهه الناسُ, وصاروا يتعرَّضون لجُندِه بالأذى والسَّبِّ، فشرعَ في تحصينِ قُرطبةَ وعِمارةِ أسوارِها وحَفْرِ خَنادِقِها، وارت"},{"id":663,"era":"c3","t":"استقلال دولة بني زياد وامتلاكها اليمن وحضرموت .","s":"دولةُ بَني زيادٍ هي أوَّلُ الدُّولِ اليَمنيةِ استقلالًا في القرنِ الثالثِ الهِجريِّ، ففي زمَنِ المأمونِ الخَليفةِ العباسيِّ بدأ النُّفوذُ الشِّيعيُّ يزدادُ بشدةٍ؛ ما جعَله يُولِّي محمدَ بنَ إبراهيمَ الزِّياديَّ اليَمنَ سنةَ 203هـ، وبعد عامٍ مِن هذا التاريخ بدأ الزِّياديُّ في بناءِ مَدينةٍ جَديدةٍ لها، وهي مَدينةُ زُبَيدٍ، وقد نجَح في بَسطِ نُفوذِه على جميعِ أرجاءِ اليَمنِ حتى استَقلَّ بمُلكها، فمَ"},{"id":664,"era":"c3","t":"وفاة علي بن موسى الرضي (ولي عهد المأمون) .","s":"تُوفِّيَ علي بن موسى الرضا- الذي كان المأمونُ قد جعله وليًّا للعهدِ- وكان سببُ موته أنَّه أكل عنبًا فأكثَرَ منه، فمات فجأةً، وكان موتُه بمدينة طوس، فصلى المأمونُ عليه، ودفنه عند قبرِ أبيه الرشيد, وقيل: إنَّ المأمون سمَّه في عنب، وكان عليٌّ يحِبُّ العنب. فلما توفِّيَ كتب المأمونُ إلى الحسن بن سهل يُعلِمُه موتَ عليٍّ، وما دخل عليه من المُصيبة بموته، وكتب إلى أهلِ بغداد، وبني العبَّاس والموالي يُعلِم"},{"id":665,"era":"c3","t":"خلع أهل بغداد لإبراهيم بن المهدي .","s":"كان سبَبُ ذلك أنَّ إبراهيمَ قَبَضَ على عيسى بن محمد بن أبي خالد وحبسَه، وأخذ عِدَّةً من قوَّاده وأهلَه، فحبَسَهم ونجا بعضُهم، وفيمن نجا أخو عيسى العباس بن محمد، ومشى بعضُ أهله إلى بعض، وحرَّضوا الناسَ على إبراهيم، وكان أشَدَّهم العباسُ بن محمد، وكان هو رأسَهم، فاجتمعوا وطردوا عاملَ إبراهيمَ على الجسر، والكرخ وغيره، وظهر الفُسَّاق والشُّطَّار، وكتب العباسُ إلى حميد بن عبد الحميد يسألُه أن يَقدَمَ ع"},{"id":666,"era":"c3","t":"اليمن يستقل عن الخلافة العباسية بقيام الدولة الزيادية  .","s":"كان شَخصٌ مِن بني زيادِ بن أبيه، اسمُه محمد بن إبراهيم بن عبيد الله بن زياد، مع جماعةٍ من بني أمية، قد سَلَّمهم المأمونُ إِلى الفضل بن سهل ذي الرياستين، وقيل إِلى أخيه الحسَن، وبلغ المأمونُ اختلالَ أمر اليمن، فأثنى ابنُ سهلٍ على محمَّد بن زياد الأموي، وأشار بإِرساله أميرًا على اليمن، فأرسل المأمونُ محمَّدَ بن زياد، ومعه جماعةٌ، فحَجَّ ابنُ زياد في سنة ثلاث ومائتين، وسار إِلى اليمَنِ، وفتح تِهامةَ "},{"id":667,"era":"c3","t":"قدوم الخليفة المأمون من جرجان إلى بغداد .","s":"لَمَّا خُلِعَ إبراهيمُ بن المهدي واختفى وانقطعت الفِتَن، قَدِمَ المأمونُ بغداد، وكان قد أقام بجرجان شَهرًا وجعل يقيمُ بالمنزل اليومَ واليومينِ والثلاثةَ، وأقام بالنهروان ثمانيةَ أيام، فخرج إليه أهلُ بيته والقوَّاد، ووجوهُ الناس، وسَلَّموا عليه. وكان قد كتب إلى طاهرِ بنِ الحُسين، وهو بالرقَّة، ليوافيَه بالنهروان، فأتاه بها ودخل بغدادَ مُنتصَفَ صفر، ولباسُه ولباسُ أصحابِه الخُضرة، فلمَّا قَدِمَ بغدا"},{"id":668,"era":"c3","t":"وفاة الإمام الشافعي .","s":"هو أبو عبدالله محمَّد بن إدريس بن العبَّاس بن عثمان بن شافع بن السائب بن عبيد بن عبد يزيد بن هشام بن المطلب بن عبد مناف بن قصي بن كلاب بن مرة بن كعب بن لؤي بن غالب، الإمامُ عالِمُ العَصرِ ناصِرُ الحديثِ، فقيه المِلَّة، ثم المطَّلبيُّ الشافعيُّ، المكِّي، الغزي القرَشِيُّ، أحَدُ الأئمَّة الأربعة المشهورينَ في الفقه، ولِدَ في غزَّة عام 150هـ فعادت به أمُّه إلى مكة، وهو ابن سنتين، فنشأ بها، وأقبل على "},{"id":669,"era":"c3","t":"وفاة الحكم بن هشام صاحب الأندلس .","s":"هو الحكَمُ بنُ هشامٍ ابنُ الداخل عبد الرحمن بن معاوية بن هشام بن عبد الملك بن مروان ابن الحَكَم الأُموي، المرواني، أبو العاصِ، أميرُ الأندلس، وابنُ أميرِها، وحفيدُ أميرها. ويلقَّب: بالمرتضَى، ويعرف: بالربضي؛ لِما فعلَ بأهلِ الربض. بويعَ بالمُلك عند موت أبيه- في صفر سنة ثمانين ومائة- وكان من جبابرةِ الملوك وفُسَّاقهم ومتَمَرِّديهم، وكان فارسًا شجاعًا فاتِكًا، ذا دهاءٍ وحَزمٍ، وعُتُوٍّ وظُلمٍ، تملَّ"},{"id":670,"era":"c3","t":"عبدالرحمن الأوسط يحكم الأندلس .","s":"لَمَّا مات الحكَمُ بنُ هشام بن عبدالرحمن، قام بالمُلْك بعده ابنُه عبد الرحمن ويكنَّى أبا المطرف، واسمُ أمِّه حلاوة، ولد بطليطِلة، أيَّامَ كان أبوه الحكَمُ يتولَّاها لأبيه هشام، فلمَّا وَلِيَ عبدالرحمن خرج عليه عمُّ أبيه عبد الله البلنسي؛ طمعًا في الحُكمِ بعد موتِ الحَكَمِ."},{"id":671,"era":"c3","t":"خروج عبدالله البلنسي على عبدالرحمن الثاني في الأندلس .","s":"قبل أن يتسَلَّمَ عبدُالرحمن بن الحكَم مقاليدَ الحُكمِ، فوجئ بخروجِ عَمِّ أبيه عبد الله بن عبدالرحمن البلنسي عليه؛ لينتزع المُلكَ منه، خرج من بلنسية يريد قُرطبة، فتجهَّزَ له عبد الرحمن واستعَدَّ لمواجهتِه، وعندما بلغ ذلك عبد الله خاف وضَعُفَت عزيمتُه، وانسحب إلى بلنسية، ثم ما لبث أن مات في أثناء ذلك سريعًا، ووقى الله ذلك الطَّرفَ شَرًّا. فلما مات نقلَ عبدُ الرحمن أولادَه وأهلَه إليه بقُرطبة، فخَلَص"},{"id":672,"era":"c3","t":"خروج عبدالرحمن بن أحمد بن عبدالله باليمن .","s":"خرج عبدُ الرحمن بن أحمد بن عبد الله بن محمد بن عمر بن علي بن أبي طالب ببلادِ عَكٍّ من اليمن، يدعو إلى الرضا من آل محمد, وكان خروجُه من سوءِ سيرةِ عاملِ اليمَنِ، فبايعه خلقٌ، فوجه إليه المأمونُ لحَربِه دينارَ بن عبد الله، وكتب معه بأمانِه، فحَجَّ دينار ثم سار إلى اليمَنِ حتى قرُبَ من عبد الرحمن، وبعث إليه بأمانِه فقَبِلَه وعاد مع دينارٍ إلى المأمون."},{"id":673,"era":"c3","t":"طاهر بن الحسين يعلن قيام الدولة الطاهرية بخراسان .","s":"تُنسبُ الدَّولةُ الطاهريَّةُ إلى طاهر بن الحُسين بن مصعب بن رُزَيق، وكان أبوه أحدَ وُجَهاءِ خراسان ومِن سادتِها في عصر الخليفة العباسيِّ هارون الرشيد، وقد ولَّاه الرشيد بوشنج- إحدى مدن خراسان- والتي تقعُ بين هراة وسرخس. وبعد وفاة هارونَ الرشيد سنة 194هـ حدث نزاعٌ حول الخلافة بين ابنيه: الأمينِ والمأمون، وتصاعد الخِلافُ إلى حدِّ الحرب والاقتتال، وفي ظلِّ تلك الأجواء المشحونةِ بالقتال والصِّراع، وجد"},{"id":674,"era":"c3","t":"بداية فتنة المضرية واليمانية بالأندلس .","s":"ثارت بمدينةِ تدميرٍ فتنةٌ بين المُضَرية واليمانية، فاقتتلوا بلورقة، وكان بينهم وقعةٌ تعرَفُ بيوم المُضارة، قُتِل منهم ثلاثةُ آلاف رجل، ودامت الحربُ بينهم سبعَ سنين، فوكَلَ عبدُالرحمن بن الحكم بكَفِّهم، ومَنْعِهم، يحيى بنَ عبدِ الله بن خالد، وسيَّرَه في جميع الجيش، فكانوا إذا أحسُّوا بقرب يحيى تفَرَّقوا وتركوا القتال، وإذا عاد عنهم رجعوا إلى الفتنةِ والقتالِ، حتى عَيِيَ أمرُهم."},{"id":675,"era":"c3","t":"وقعة بالس في الأندلس .","s":"وقعَ عبدُ الرحمن بن الحَكَم، صاحِبُ الأندلس، بجُندِ إلبيرة وأهلِها، وهي الوقعةُ المعروفة بوقعة بالس، كان سببُها أنَّ الحكَمَ كان قد بلغه عن عاملٍ اسمُه ربيع أنَّه ظلم أبناءَ أهلِ الذمَّة، فقبض عليه وصَلَبه قبْلَ وفاته، فلمَّا توفِّيَ الحكَمُ ووَلِيَ ابنُه عبدُ الرحمن سَمِعَ النَّاسُ بصَلبِ الربيع، فأقبلوا إلى قرطبةَ مِن النواحي يطلُبونَ الأموال التي كان ظلَمَهم بها ربيعٌ؛ ظنًّا منهم أنَّها تُرَدُّ"},{"id":676,"era":"c3","t":"خلاف قادة الجند مع زيادة الله الأغلب .","s":"وقعَت بين زيادةِ الله وبين الجُند الحُروبُ وهاجت الفِتَن. واستولى كلُّ رئيس بناحية فملكوها عليه كُلَّها، وزحفوا إلى القيروان فحَصَروه، وكان فاتحةَ الخلافِ أنَّ زيادَ بنَ سَهلِ بن الصقليَّة حاصر مدينةَ باجة فسَرَّحَ إليه زيادةُ الله العساكِرَ فهزموه وقتلوا أصحابَه. ثمَّ انتقض منصورُ الترمذي بطبنة، وسار إلى تونُس فملَكَها, فسرَّحَ زيادةُ الله العساكِرَ من القيروان مع غلبون ابنِ عَمِّه، ووزيره اسمُه "},{"id":677,"era":"c3","t":"وفاة طاهر بن الحسين أمير خراسان .","s":"هو طاهِرُ بنُ الحسينِ بنِ مُصعَبِ بن رُزَيق الأمير، مُقَدَّمُ الجُيوشِ، ذو اليمينَينِ، أبو طلحة الخزاعي، ولد طاهِرٌ في بوشنج سنة 159هـ القائم بنصرِ خلافة المأمون؛ فإنه ندبه لحربِ أخيه الأمين فسار في جيشٍ لَجِب، وحاصر الأمينَ فظَفِرَ به وقتله صبرًا، فمُقِت لتسَرُّعِه في قتله. وكان شهمًا مَهِيبًا داهيةً، جوادًا مُمَدَّحًا. كان مع فَرطِ شجاعته عالِمًا خطيبًا مفَوَّهًا بليغًا شاعرًا، بلغ أعلى الرُّتَب"},{"id":678,"era":"c3","t":"وفاة الفضل بن الربيع .","s":"هو الفضلُ بنُ الربيعِ بنِ يونُسَ، الحاجِبُ الأميرُ أبو الفضل، مولِدُه سنة أربعين ومائة، وكان حاجبًا للرشيد ووزيرًا له، ولَمَّا مات الرشيدُ استولى على الخزائِنِ وقَدِمَ بها إلى الأمينِ محمَّد ببغداد ومعه البُردة والقَضيبُ والخاتَم، فأكرمه الأمينُ وفَوَّض إليه أمورَه، فصار إليه الأمرُ والنهي، ولَمَّا خلعَ الأمينُ أخاه المأمونَ مِن ولاية عهدِ الخلافة، استخفى ثم ظهرَ في أيامِ المأمونِ، فأعاده المأمونُ"},{"id":679,"era":"c3","t":"هزيمة نصارى الأندلس على يد عبد الكريم بن مغيث .","s":"وكان عبدُ الرحمن شديدَ الاهتمامِ بتأمين حدودِ البلاد الشماليَّة، بعد أن تزايدَ عُدوانُ الفِرنجةِ عليها، فأرسل حملةً عسكريةً كبيرةً بقيادةِ عبد الكريم بن عبد الواحد بن مغيث, وقد نجَحَت تلك الحملةُ في إلحاقِ الهزيمةِ بالنَّصارى المتربِّصين، وألحقَت بهم خسائِرَ كبيرةً بعد أن أحرَقَت حُصونَهم، وقتَلت منهم عددًا كبيرًا، وعادت الحملةُ إلى قرطبة محمَّلةً بالغنائم، وهي تسوقُ الأسرى والأسلابَ، وكان لهذه ال"},{"id":680,"era":"c3","t":"القضاء على فتنة نصر بن شبث .","s":"أظهرَ نَصرُ بنُ سيَّار بن شبث العقيلي الخِلافَ على المأمون سنة 198ه، وكان يسكن كيسوم، ناحية شماليَّ حَلَب، وكان في عنُقِه بيعةٌ للأمين، وله فيه هوًى، فلمَّا قُتِلَ الأمينُ أظهر نصرٌ الغضَبَ لذلك، وتغلَّبَ على ما جاوره من البلاد، وملك سميساط، واجتمع عليه خلقٌ كثيرٌ مِن الأعراب، وأهلِ الطمع، وقَوِيَت نفسُه، وعبَرَ الفُرات إلى الجانب الشرقي، وحدَّثَته نفسُه بالتغلُّب عليه، فلما رأى الناسُ ذلك منه كثُ"},{"id":681,"era":"c3","t":"استعادة عبدالله بن طاهر الإسكندرية للعباسيين .","s":"أخرج عبدُ الله من كان تغلَّبَ على الإسكندريةِ مِن أهل الربض الأندلسيِّينَ بأمانٍ، وكانوا قد جاؤوا في مراكِبَ مِن الأندلس في فتنةِ ابنِ السري وغيره، فأرسَوا بالإسكندرية، ورئيسُهم يدعى أبا حفص، فلم يزالوا بها حتى قَدِمَ ابنُ طاهر، فأرسل يؤذِنُهم بالحَربِ إن هم لم يدخُلوا في الطاعة، فأجابوه، وسألوه الأمانَ على أن يرتَحِلوا عنها إلى بعضِ أطراف الروم التي ليسَت من بلاد الإسلامِ، فأعطاهم الأمانَ على ذلك"},{"id":682,"era":"c3","t":"خلع أهل قم للخليفة العباسي المأمون .","s":"خلعَ أهلُ قُم المأمونَ، ومنعوا الخراجَ، وكان سببُه أنَّ المأمونَ لَمَّا سار من خراسانَ إلى العراق أقام بالريِّ عِدَّةَ أيَّامٍ، وأسقط عنهم شيئًا من خراجِهم، فطَمِعَ أهلُ قُم أن يصنع بهم كذلك، فكتَبوا إليه يسألونُه الحطيطةَ، وكان خراجُهم ألفي ألف درهم، فلم يُجِبْهم المأمونُ إلى ما سألوا، فامتنعوا من أدائِه، فوجَّه المأمونُ إليهم عليَّ بن هشام، وعجيف بن عنبسة، فحارباهم فظَفِرا بهم، وقتَلَ يحيى بن عم"},{"id":683,"era":"c3","t":"هزيمة الفرنج بالأندلس أمام جيوش عبدالرحمن بن الحكم .","s":"سيَّرَ عبدالرحمن بن الحكَم سريَّةً كبيرةً إلى بلاد الفرنج، واستعمل عليها عبيدَ الله المعروف بابن البلنسي، فسار ودخل بلادَ العدُوِّ، وتردَّدَ فيها بالغارات والسبيِ، والقتل والأسْر، ولقِيَ عبيد الله الأعداءَ، فاقتتلوا فانهزم المشركونَ، وكثُرَ القتلُ فيهم، وكان فتحًا عظيمًا."},{"id":684,"era":"c3","t":"المأمون يعفو عن عمه إبراهيم بن المهدي .","s":"كان إبراهيمُ المهديُّ قد خرج على المأمونِ وبايعه أهلُ بغداد إلَّا أنَّ الأمرَ لم يدُمْ في يدِه طويلًا، حتى انفَضَّ عنه الناسُ وتركوه، فاختفى مدةَ سِتِّ سنين وشهور، ثم ظَفِرَ به المأمون, فاستعطفه إبراهيمُ فعفا عنه وترَكَه."},{"id":685,"era":"c3","t":"هزيمة الفرنج بالأندلس أمام عبد الرحمن بن الحكم .","s":"افتتح عسكرٌ سَيَّرَه عبدُ الرحمن حِصنَ القَلعةِ مِن أرضِ العَدُوِّ، وتردَّدَ فيها بالغارات."},{"id":686,"era":"c3","t":"وفاة عبدالرزاق الصنعاني صاحب المصنف .","s":"هو أبو بكر عبدُالرَّزاق بن همام بن نافع الحِمْيري ولاءً الصَّنعاني، الحافِظُ المحَدِّث الثِّقة، عالمُ اليمَنِ الكبيرُ، ولد بصنعاء سنة 126هـ, روى عنه خلقٌ كثيرٌ، منهم الإمام أحمدُ وابنُ عُيَينة، قال الذهبي: هو خزانةُ العِلمِ، له كتابٌ في التفسير، وأشهرُ كتُبِه هو (المصنَّف) المعروفُ، جمعَ فيه الكثيرَ من الأحاديثِ والآثارِ الموقوفةِ عن الصحابة وعن التابعين. كان فيه تشيُّعٌ لعليٍّ، قال أحمد العجلي: ع"},{"id":687,"era":"c3","t":"فتنة عبيدالله بن السري بمصر .","s":"لَمَّا توفِّيَ السري أميرُ مصرَ للمأمونِ، وليَ بعدَه ابنُه عُبيدالله، ولَّاه الجُندُ وبايعوه، ثم حدَّثَته نفسُه الخروجَ عن طاعة المأمونِ وجَمَع وحَشَد، فبلغ المأمونَ ذلك وطلب عبدَ الله بنَ طاهرٍ لقتالِه وقتالِ الخوارج بمصرَ، فسار إليه ابنُ طاهر فتهَّيأ عُبيد الله بن السري لحَربِه وعبَّأ جيوشَه وحفَرَ خندقًا عليه، ثم تقدَّم بعساكِرِه إلى خارج مصرَ والتقى مع عبد اللهِ بنِ طاهر وتقاتلا قتالًا شديدًا،"},{"id":688,"era":"c3","t":"المأمون يدعو بأفضلية علي بن أبي طالب رضي الله عنه .","s":"في هذه السَّنةِ أظهر المأمونُ أوَّلَ بِدَعِه الشنيعةِ، فأمر مناديًا ينادي: بَرِئَت الذمَّةُ ممَّن ذكر معاويةَ بنَ أبي سفيان بخيرٍ أو فضَّلَه على أحدٍ مِن الصَّحابة، وينادي: إنَّ أفضَلَ الخَلقِ بعد رَسولِ الله صلَّى الله عليه وسلَّم عليُّ بنُ أبي طالب. وقيل: كان المأمون يبالِغُ في التشيُّعِ، لكنَّه لم يتكلَّمْ في الشَّيخينِ بسُوءٍ، بل كان يترضَّى عنهما ويعتقِدَ إمامتَهما."},{"id":689,"era":"c3","t":"وفاة أبي العتاهية الشاعر .","s":"هو أبو إسحاقَ، إسماعيلُ بنُ القاسم بن سويد العنزيُّ ولاءً، المشهورُ بأبي العتاهية، لقَّبَه بذلك الخليفةُ المهديُّ، ولِدَ في عين التمر سنة 130هـ، نشأ بالكوفة، قال الشِّعرَ سَجِيَّةً مِن نفسه، قَدِمَ بغداد على المهديِّ وقَرَّبه الرشيدُ، كان شاعرًا مُكثِرًا، وكان أوَّلَ أمرِه في الغَزلِ، ثم أخذ في شِعرِ الزُّهد والتقشُّف والوَرَع، توفِّي عن عمر يناهز الثمانين."},{"id":690,"era":"c3","t":"المأمون يوجه محمد الطوسي لمحاربة بابك الخُرَّمي .","s":"بدأت فِتنةُ بابك الخرمي صاحِبُ البذ عام مائتان وواحد، وهم أصحابُ جاويدان بن سهل، وادَّعى بابك أنَّ روحَ جاويدان دخَلَت فيه، فأخذ في العَيثِ والفساد، فكان يُخشى من أمْرِه؛ لأنَّه في أطرافِ الرُّومِ، ويُمكِنُ أن يتحالَفَ معهم ضِدَّ المسلمين، وكان قبل ذلك حصَلَت عِدَّةُ محاولاتٍ لإخماد فتنتِه؛ لكِنَّها لم تنجَحْ، فوَجَّه المأمونُ محمَّدَ بن حميد الطوسي إلى بابك الخرمي لمحاربتِه، وأمَرَه أن يجعَلَ طري"},{"id":691,"era":"c3","t":"المأمون يعتنق مذهب المعتزلة ويعلنه مذهبا رسميا للدولة .","s":"أظهرَ المأمونُ بِدعتَه الثانيةَ الشَّنيعةَ، ولم يأت هذا الإظهارُ دون سوابِقَ، بل إنَّ المأمونَ عُرِفَ عنه تقريبُه لأئمَّة المعتَزِلة وتودُّده إليهم وإكرامُه لهم، فتأثر بهم وبمذهبِهم، حتى قال بقَولِهم، ولم يقف الأمرُ عند هذا الحَدِّ، بل ألبوه على عُلَماءِ السنَّة الذين يخالفونَهم في الرأي، وكان من أشدِّ الأمور التي ظهر الخلافُ فيها هي مسألةُ خلقِ القرآنِ، فأهلُ السنَّة والجماعة يقولون: إنَّه كلامُ "},{"id":692,"era":"c3","t":"فتح المسلمين جزيرة كريت وتأسيس قاعدة بحرية فيها .","s":"استولى أهلُ الربض الهاربين من الأندلُسِ على الإسكندرية، فقام عبدُالله بن طاهر أميرُ مِصرَ بمحاصَرتِهم فأعطاهم الأمانَ بشَرطِ الرحيلِ إلى جزيرة كريت، فذهبوا واستولَوا على جزيرةِ كريت التي كانت في أيدي البيزنطيِّينَ وجعلوا عليهم واليًا هو أبو حفصٍ عمَرُ البلوطي، وأسَّسوا قاعدةً لهم بالجزيرةِ وأحاطوها بخندقٍ كبيرٍ، فأصبحت تُعرَفُ باسم الخندق، والتي تُعرَفُ كذلك بهراقليون، وبقيت هذه الجزيرةُ بأيدي الم"},{"id":693,"era":"c3","t":"المسلمون يحتلون جزيرة صقلية .","s":"استولى على جزيرةِ صقليَّة فيمي الروميُّ الذي غلَبَ عامِلَ قُسطنطينَ عليها، وكان فيمي طلبَ مِن زيادةِ الله النَّجدةَ، فجهز زيادةُ الله جيشًا كبيرًا بإمرة أسَدِ بنِ الفُرات قاضي القيروان، الذي سار إليهم فانتصرَ المسلمون بالبداية، ثم جاءت نجداتُ الروم إلى نصارى صقلية وانقلبَ فيمي اللعينُ على المسلمينَ، ومات أسدُ بنُ الفرات، فلم يتوغَّلوا داخِلَ الجزيرةِ، لكِنَّ النجدة جاءت من القيروان كما وصلَت سفُنٌ"},{"id":694,"era":"c3","t":"وفاة إدريس الثاني حاكم دولة الأدارسة .","s":"كان إدريسُ الثاني قد بُويِعَ وهو رضيعٌ، ولَمَّا بلغ الحاديةَ عشرة من عمره بويع مرةً أخرى، وكان جوادًا أحبَّه الرعيَّةُ، واستمال أهلَ تونُسَ وطرابلس الغرب التي كان يحكُمُها الأغالبة، وانتظم له البربر وبنى مدينةَ فاس، وأخضع الخوارِجَ الصفرية في تلمسان، فلما مات عن عمر 36 عامًا خَلَفَه ابنُه محمَّدٌ، فاختلف الأدارسة؛ إذ نازعه أخوه عيسى بن إدريسَ الذي كان واليًا على أزمور، فأراد محمد أن يستعينَ عليه ب"},{"id":695,"era":"c3","t":"ثورة أهل ماردة في الأندلس .","s":"قتلَ أهلُ ماردةَ مِن الأندلس عامِلَهم، فثارت الفتنةُ عندهم، فسيَّرَ إليهم عبدُ الرحمن جيشًا فحصرهم، وأفسَدَ زَرعَهم وأشجارَهم، فعاودوا الطاعةَ، وأُخِذَت رهائنُهم، وعاد الجيشُ بعد أن خَرَّبوا سور المدينة. ثم أرسل عبد الرحمن إليهم بنقلِ حِجارةِ السُّورِ إلى النهرِ؛ لئلَّا يطمَعَ أهلُها في عمارتِه، فلمَّا رأوا ذلك عادوا إلى العِصيانِ، وأسَرُوا العامِلَ عليهم، وجدَّدوا بناء السور وأتقَنوه، ثم تتابعَ ا"},{"id":696,"era":"c3","t":"مقتل محمد الطوسي على يد بابك الخُرَّمي .","s":"لَمَّا فرغ محمَّدُ بن حميد الطوسي مِن أمْرِ المتغَلِّبينَ على طريقِه إلى بابك الخُرمي سار نحوه وقد جمع العساكر، والآلاتِ والميرة، فاجتمع معه عالمٌ كثير من المتطوِّعةِ مِن سائر الأمصار، فسلك المضايقَ إلى بابك، وكان كلَّما جاوز مضيقًا أو عقبةً ترك عليه من يحفَظُه من أصحابِه إلى أن نزل بهشتادسر (جبل في إيران)، وحفَر خندقًا وشاور في دخولِ بلد بابك، فأشاروا عليه بدخولِه مِن وجهٍ ذكروه له، فقَبِلَ رأيهم"},{"id":697,"era":"c3","t":"خروج هاشم الضراب بطليطلة .","s":"خرج هاشم الضرَّابُ بمدينة طليطلة، من الأندلس، على صاحِبِها عبد الرحمن، وكان هاشِمٌ قد خرج من طليطِلة لَمَّا أوقع الحكَمُ بأهلِها، فسار إلى قُرطُبةَ، ثم سار إلى طليطِلة، فاجتمع إليه أهلُ الشرِّ وغَيرُهم، فسار بهم إلى وادي نحوييه وأغار على البربر وغيرهم، فطار اسمُه واشتَدَّت شَوكتُه، واجتمع له جمعٌ عظيم، وأوقع بأهلِ شنت برية. وكان بينه وبين البربرِ وقعاتٌ كثيرة، فسيَّرَ إليه عبد الرحمن جيشًا فقاتلوه"},{"id":698,"era":"c3","t":"ثورة القيسية واليمانية على العباسيين في الديار المصرية .","s":"كان على مصرَ عُمَير بن الوليد الباذغيسي التميمي أميرُ مصر، ولِيَ مِصرَ باستخلافِ أبي إسحاق محمد المعتَصِم له؛ لأن الخليفةَ المأمون كان ولَّى مصرَ لأخيه المعتصم بعد عزلِ عبد الله بن طاهر، وولى المعتَصِمُ عُميرَ بن الوليد على الصَّلاة، وسكَن العَسكرِ، وجعل على شُرطتِه ابنَه محمدًا؛ وعندما تمَّ أمرُه خرج عليه القيسيَّة واليمانية الذين كانوا خَرَجوا قبل تاريخه وعليهم عبد السَّلامِ وابن الجليس، فتهيأ ع"},{"id":699,"era":"c3","t":"العباسيون ينهون فتنة القيسيَّة واليمانية في مصر .","s":"وليَ عيسى بن يزيد الجلودي مصرَ مِن قِبَل أبي إسحاقَ محمَّد المعتَصِم بعد قتل القيسيَّة واليمانية عميرَ بنَ الوليد الباذغيسي التميمي عامِلَ المعتَصِم على الصلاة، ولَمَّا قَدِمَ عيسى بن يزيد مصر، قصَدَه قيسٌ ويمن على العادةِ، وقد كثُرَ جَمعُهم من أهل الحوف وقطَّاع الطريق، فوقع لعيسى معهم حروبٌ وفِتَن، وجمع عساكِرَه وخرج إليهم حتى التقاهم بمنية مطَر (بقرب مدينة عينِ شَمس) وقاتلهم، فكانت بينهم حروبٌ ه"},{"id":700,"era":"c3","t":"الخليفة المأمون يطور بيت الحكمة ببغداد .","s":"أُنشِئَت هذه المكتبةُ في القرن الثاني الهجري ( الثامن الميلادي) على يدِ هارونَ الرشيد، وذلك بعد أن ضاقت مكتبةُ القَصرِ بما فيها من كتُبٍ, وعَجَزت عن احتواءِ القُرَّاء المتردِّدين عليها؛ ممَّا جعله يفكِّرُ في إخراجِها من القصر, وإفرادِها بمبنًى خاصٍّ بها, يَصلُحُ لاستيعابِ أكبَرِ عدَدٍ مِن الكتُبِ, ويكون مفتوحًا أمام كلِّ الدارسينَ وطُلَّابِ العِلمِ. فاختار لها مكانًا مُناسِبًا, وأقام عليه مبنًى مك"},{"id":701,"era":"c3","t":"خروج المأمون بنفسه لغزو الروم .","s":"سار المأمونُ بنفسه لِغَزوِ الرُّومِ؛ لأنه ربما شعر أنَّ النَّاسَ قد ركنت للرفاهيةِ وضَعُفَت عندهم رُوحُ الجهادِ، كما أنَّ الفُرقةَ بدأت تعصِفُ بينهم بريحِها المُنتِنة؛ مما شجَّعَ كثيرًا من المتمرِّدينَ على الخروج، فسار مِن بغداد على طريقِ المَوصِل، حتى صار إلى منبج، ثم إلى دابق، ثم إلى أنطاكية، ثم إلى المصيصة وطرسوس، ودخل منها إلى بلاد الرُّوم، ودخل ابنُه العبَّاسُ مِن ملطية، فأقام المأمونُ على حِ"},{"id":702,"era":"c3","t":"عودة المأمون إلى غزو الروم .","s":"عاد المأمونُ إلى بلاد الروم في هذه السَّنة بعد أن كان سار إليهم أوَّلَ السَّنة الماضية، وسببُ ذلك أنَّه بلغه أنَّ مَلِكَ الرومِ قتلَ ألفًا وستَّمائة مِن أهل طرسوس والمصيصة، فسار حتى دخل أرضَ الروم، وقيل كان سببُ دُخولِه إليها أنَّ مَلِكَ الرومِ كتب إليه وبدأ بنَفسِه، فسار إليه، ولم يقرأ كتابَه، فلمَّا دخل أرضَ الرومِ أناخ على أنطيغو، فخرجوا على صُلْحٍ، ثم سار إلى هرقلة، فخرج أهلُها على صلحٍ، ووجَّ"},{"id":703,"era":"c3","t":"خروج عبدوس الفهري على العباسيين بمصر .","s":"انتفض الوجهُ البحري بمصرَ بزعامة عبدوس الفهري وانضم الأقباطُ إليهم، وحَشَدوا وجمعوا فكثُرَ عددُهم وساروا نحو الديارِ المصرية، فتجهَّزَ عيسى بن منصور وجمعَ العساكِرَ والجندَ لقتالهم، فضَعُف عن لقائِهم وتقهقر بمن معه، فدخلت الأقباطُ وأهل الغربيَّة مصرَ، وأخرجوا منها عيسى هذا على أقبَحِ وجهٍ؛ لسُوءِ سِيرتِه، وخرج معه أيضًا مُتولِّي خَراجِ مِصرَ وخلعوا الطاعةَ، فقدم الأفشين حيدر بن كاوس من بُرقةَ وتهي"},{"id":704,"era":"c3","t":"ابتداع المأمون التكبير عقب الصلوات الخمس .","s":"كتب المأمونُ إلى نائِبِه ببغداد إسحاقَ بنِ إبراهيم أن يأخُذَ الجندُ بالتكبيرِ إذا صَلَّوا الجمعةَ، وبعد الصَّلواتِ الخَمسِ إذا قَضَوا الصلاةَ أن يَصيحوا قيامًا ويكَبِّروا ثلاثَ تكبيراتٍ، ففعل ذلك، فقال الناسُ: هذه بدعةٌ ثالثة."},{"id":705,"era":"c3","t":"المأمون يحاصر حصن لؤلؤة في بلاد الروم .","s":"ركِبَ المأمون إلى بلاد الروم فحاصر حِصنَ لؤلؤةَ مائة يومٍ، ثم ارتحلَ عنها واستخلف على حصارِها عجيف بن عنبسة، فخدعته الرومُ فأسَروه فأقام في أيديهم ثمانيةَ أيام، ثم انفَلَت منهم واستمَرَّ محاصِرًا لهم، فجاء توفيل ملِكُ الروم بنفسِه، فأحاط بجيشِه من ورائه، فبلغ المأمونَ فسار إليه، فلمَّا أحس توفيل بقدومِه هرب وبعث وزيرَه صنغل، فسأله الأمانَ والمصالحةَ، لكنَّه بدأ بنَفسِه قبل المأمون فرَدَّ عليه المأ"},{"id":706,"era":"c3","t":"تمرد علي بن هشام في أذربيجان .","s":"كان المأمونُ استعمل عليَّ بنَ هِشامٍ على أذربيجان وغيرها، فبلغه ظُلمُه، وأخذُه الأموالَ، وقتلُه الرجالَ، فوجَّهَ إليه عجيف بن عنبسة، فثار به عليُّ بن هشام، وأراد قَتْلَه واللَّحاقَ ببابك، فظَفِرَ به عجيف، وقَدِمَ به على المأمونِ، فقتَلَه وقتل أخاه حبيبًا، وطِيفَ برأسِ عليٍّ في العراقِ وخراسان، والشام ومِصرَ، ثم ألقيَ في البحرِ."},{"id":707,"era":"c3","t":"المأمون يمتحن العلماء والفقهاء في مسألة خلق القرآن .","s":"لم يكتَفِ المأمونُ باعتناقِ مسألةِ القَولِ بخلقِ القرآن، بل كتب إلى عمَّالِه في الأمصارِ بامتحانِ العُلَماءِ في هذه المسألة من أجاب وإلَّا كان العقابُ، وربَّما بطانتُه من العلماء كانوا وراء هذا الامتحان، فكتب المأمونُ إلى نائبه ببغداد إسحاقَ بن إبراهيم بن مُصعَب يأمُرُه أن يمتَحِنَ القُضاةَ والمحَدِّثين بالقَولِ بخَلقِ القرآن، وأن يرسل إليه جماعةً منهم، وكتب إليه يستحِثُّه في كتابٍ مُطَوَّل، وكتب "},{"id":708,"era":"c3","t":"اعتقال الإمام أحمد بن حنبل ومحمد بن نوح في بغداد .","s":"بعد أن أحضر إسحاقُ بنُ إبراهيمَ العُلَماءَ والمحدِّثينَ لامتحانِهم، كان مِن بينهم الإمامُ أحمَدُ، ومحمدُ بنُ نوح، وغيرُهم كثيرٌ، ولَمَّا انتهت النوبةُ إلى امتحانِ الإمامِ أحمَدَ بنِ حنبَل، قال له: أتقولُ إنَّ القرآنَ مَخلوقٌ؟ فقال: القرآنُ كلامُ اللهِ، لا أزيدُ على هذا، فقال له: ما تقولُ في هذه الرُّقعةِ؟ بالرقعةِ التي وافَقَ عليها قاضي القُضاةِ بِشرُ بن الوليد الكِندي، فقال: أقولُ: {لَيْسَ كَمِثْ"},{"id":709,"era":"c3","t":"خروج فضل بن أبي العنبر على دولة الأغالبة في المغرب .","s":"وجَّه زيادةُ اللهِ بنُ الأغلب، صاحِبُ إفريقية، جيشًا لمحاربةِ فضل بن أبي العنبر بجزيرة شريك، وكان مخالفًا لزيادةِ الله، فاستمَدَّ فَضلٌ بعبد السلامِ بن المفرج الربعي، وكان أيضًا مخالفًا مِن عَهدِ فِتنةِ منصور الترمذي، فسار إليه، فالتَقَوا مع عسكر زيادة الله، وجرى بين الطائفتينِ قِتالٌ شديدٌ عند مدينة اليهود بالجزيرة، فقُتِلَ عبد السلام، وحُمِلَ رأسُه إلى زيادة الله، وسار فضلُ بن أبي العنبر إلى مدي"},{"id":710,"era":"c3","t":"وفاة بشر المريسي من رؤوس المعتزلة .","s":"هو بِشرُ بنُ غياث بن أبي كريمة المِرِّيسي، شيخُ المعتزلة، وأحدُ من أضَلَّ المأمونَ، وقد كان هذا الرجلُ ينظُرُ أوَّلًا في شيءٍ مِن الفِقهِ، وأخذ عن أبي يوسُفَ القاضي، وروى الحديثَ عنه وعن حمَّاد بن سَلَمة، وسُفيانَ بنِ عُيَينة وغيرِهم، ثم غلب عليه عِلمُ الكلامِ, وقد نهاه الشافعيُّ عن تعلُّمِه وتعاطيه، فلم يقبل منه، وقال الشافعي: \"لَئِنْ يلقى اللهَ العبدُ بكُلِّ ذنبٍ- ما عدا الشِّركَ- أحَبُّ إليَّ م"},{"id":711,"era":"c3","t":"وفاة عبدالملك بن هشام راوي السيرة المشهور .","s":"هو أبو محمد عبدالملك بن هشام بن أيوبَ المعافري، العلَّامةُ النَّحويُّ الأَخباريُّ، أبو محمد الذهلي السَّدوسي، وقيل: الِحمْيري المعافري البصري، نزيلُ مصر، هذَّبَ السيرةَ النبويَّةَ لابنِ إسحاقَ مُصَنِّفِها. سمعها مِن زياد البكائي صاحِبِ ابنِ إسحاق, وإنما نُسِبَت إليه، فيقال سيرةُ ابن هشام؛ لأنه هذَّبَها وزاد فيها ونقَصَ منها، وحَرَّر أماكِنَ، واستدرك أشياءَ، وكان إمامًا في اللغة والنحو، وقد كان مقي"},{"id":712,"era":"c3","t":"قيام المأمون بتوجيه ابنه العباس إلى أرض الروم .","s":"وجَّه المأمونُ ابنَه العبَّاسَ إلى أرضِ الرومِ وأمَرَه بنزول الطوانةِ وبنائِها، وكان قد وجَّه الفَعَلةَ والفُروضَ، فابتدأ البناءَ وبناها ميلًا في ميلٍ، وجعل سورَها على ثلاثةِ فراسِخَ، وجعل لها أربعةَ أبواب، وبنى على كلِّ بابٍ حِصنًا."},{"id":713,"era":"c3","t":"وفاة الخليفة العباسي المأمون .","s":"هو أبو العبَّاسِ عبدُ الله بن هارون الرَّشيد بن محمد المهدي بن أبي جعفر المنصور المأمون العباسي. وُلِدَ سنة سبعين ومائة, واسمُ أمِّه: مراجل ماتت في نفاسِها به. قرأ العلمَ والأدبَ والأخبارَ، والعقليَّات وعلومَ الأوائل، وأمرَ بتعريبِ كُتُبِهم، وبالغ في تعريبها، وعَمِلَ الرصدَ فوق جبل دمشق، ودعا إلى القولِ بخَلْقِ القرآنِ وامتحنَ العُلَماءِ به. كان ذا حَزمٍ وعزمٍ، ورأيٍ وعقلٍ، وهيبةٍ وحِلمٍ، ومحاسِنُ"},{"id":714,"era":"c3","t":"المعتصم بالله يتولى الخلافة العباسية .","s":"هو أبو إسحاقَ محمَّدُ بن هارون الرشيد، بويعَ له بالخلافةِ بعد موتِ المأمونِ، ولَمَّا بويِعَ له شَغَّبَ الجندُ، ونادوا باسمِ العبَّاسِ بنِ المأمون، فأرسل إليه المعتَصِمُ، فأحضره فبايَعَه، ثم خرج العبَّاسُ إلى الجندِ، فقال: ما هذا الحبُّ البارِدُ؟ قد بايعتُ عَمِّي، فسكَتوا، وأمَرَ المعتَصِمُ بخرابِ ما كان المأمونُ أمَرَ ببنائِه من طوانة، وحَمْل ما أطاق من السِّلاحِ والآلة التي بها وأحرقَ الباقيَ، وأ"},{"id":715,"era":"c3","t":"الخليفة المعتصم يأمر بمواجهة طائفة الخرميَّة في همذان .","s":"دخل كثيرٌ من أهل الجبال، وهمذان، وأصبهان، وماسبذان، وغيرِها في دين الخرميَّة، وتجمَّعوا فعَسكَروا في عمَلِ همذان، فوجَّه إليهم المعتَصِمُ العساكِرَ، وكان فيهم إسحاقُ بن إبراهيمَ بنِ مُصعَب، وعقَدَ له على الجبال، فسار إليهم، فأوقع بهم في أعمالِ همذان، فقتَلَ منهم ستين ألفًا وهرب الباقونَ إلى بلد الرومِ، وقرئ كتابُه بالفتح يوم الترويةِ."},{"id":716,"era":"c3","t":"ظهور محمد بن القاسم ودعوته لنفسه في خراسان .","s":"ظهر محمَّدُ بن القاسم بن عمر بن علي بن الحسين بن علي بن أبي طالب، بالطالقان من خراسان، يدعو إلى الرضا من آل محمَّد، وكان ابتداءُ أمرِه أنَّه كان ملازمًا مسجدَ النبيِّ صلَّى الله عليه وسلَّم، حسَنَ السِّيرةِ، فأتاه إنسانٌ من خراسان كان مجاورًا، فلما رآه أعجَبَه طريقُه، فقال له: أنت أحَقُّ بالإمامةِ مِن كُلِّ أحَدٍ، وحَسَّنَ له ذلك وبايعه، وصار الخُراساني يأتيه بالنَّفَرِ بعد النفر مِن حُجَّاجِ خُرا"},{"id":717,"era":"c3","t":"استمرار محنة الإمام أحمد بن حنبل على يد المعتصم  .","s":"بعد أن كان الإمامُ أحمدُ قد قُيِّدَ وسِيرَ به إلى المأمونِ ثم عاد لبغداد لَمَّا وصلهم نبأُ وفاة المأمون، وتولى بعده المعتَصِمُ استمَرَّ على نفس الامتحان، فأحَضَره المعتَصِم وامتحنَه بالقولِ بخلقِ القُرآنِ فلم يُجِبْه الإمامُ أحمدُ، وكُلُّ ذلك وهو ثابِتٌ على قولِه: القرآنُ كَلامُ اللهِ غيرُ مخلوقٍ، فجُلِدَ جلدًا عظيمًا حتى غاب عقلُه، وتقَطَّعَ جِلدُه، وحُبِس مقيَّدًا- رحمه الله."},{"id":718,"era":"c3","t":"عبدُ الرحمن بن الحكم يحاصر مدينةِ طُليطِلة .","s":"سيَّرَ عبدُ الرحمن بن الحكم، صاحِبُ الأندلُسِ، جيشًا مع أميَّةَ بنِ الحكَمِ إلى مدينةِ طُليطِلة، فحصَرَها، وكانوا قد خالفوا الحَكَم، وخرجوا عن الطاعة، واشتَدَّ في حصرهم، وقطَعَ أشجارَهم، وأهلك زروعَهم، فلم يُذعِنوا إلى الطاعة، فرحل عنهم، وأنزل بقَلعةِ رباح جيشًا عليهم ميسرةُ، المعروف بفتى أبي أيوب، فلما أبعدوا منه خرجَ جمعٌ كثيرٌ مِن أهل طليطلة؛ لعلَّهم يجدون فرصةً وغَفلةً مِن مَيسرةَ فينالوا منه "},{"id":719,"era":"c3","t":"المعتَصِم بالله يأمر بحرب الزطِّ (قطاع الطرق) .","s":"وجَّه المعتَصِمُ بالله عجيفَ بن عنبسة لحرب الزطِّ الذين كانوا غلَبوا على طريق البصرةِ، وعاثوا وأخذوا الغَلَّات من البيادر بكسكر وما يليها من البصرة، وأخافوا السبيلَ، ورتَّبَ عجيفٌ الخيلَ في كلِّ سكَّةٍ مِن سِكَكِ البريدِ، تركُضُ بالأخبارِ إلى المعتَصِم، فسار عجيف حتى نزل تحت واسط، وأقام على نهرٍ يقال له بردودا حتى سدَّه وأنهارًا أخَرَ كانوا يخرجون منها ويدخلون، وأخذ عليهم الطرُقَ، ثم حارَبَهم فأسَ"},{"id":720,"era":"c3","t":"المعتصم يبعث القائد الأفشين لقتال بابك الخُرَّمي .","s":"عقد المعتصِمُ للأفشين حيدر بن كاوس على الجبال، ووجَّهه لحرب بابك الخرمي، فسار إليه، وكان ابتداءُ خروجِ بابك سنةَ إحدى ومائتين، ثمَّ إنَّ الأفشين سار إلى بلادِ بابك، فنزل برزند، وعسكَرَ بها وضبَطَ الطرق والحصونَ فيما بينه وبين أردبيل، وأنزل محمَّدَ بن يوسف بموضعٍ يقال له خش، فحفرَ خندقًا وأنزل الهيثمَ الغنوي برستاق أرشق، فأصلح حِصنَه، وحفَرَ خَندقَه، وأنزل علويه الأعور، من قوَّاد الأبناء، في حصنِ ا"},{"id":721,"era":"c3","t":"اقتتال القائد العباسي الأفشين وبابك الخرمي .","s":"وجَّه المعتصِمُ القائد العسكري التركي بغا الكبيرَ إلى الأفشين، ومعه مالٌ للجندِ والنفقات، فوصل أردبيل، فبلغ بابك الخبر، فتهيَّأ هو وأصحابُه ليقطعوا عليه قبل وُصولِه إلى الأفشين، فجاء جاسوسٌ إلى الأفشين، فأخبَرَه بذلك، فلما صَحَّ الخبَرُ عند الأفشين كتب بغا أن يُظهِرَ أنَّه يريد الرحيلَ، ويحمِل المالَ على الإبل، ويسير نحوه، حتى يبلغ حصنَ النَّهر، فيَحبِس الذي معه، حتى يجوزَ مَن صَحِبَه من القافلة، "},{"id":722,"era":"c3","t":"غضب المعتصم على الفضل بن مروان وعزله عن الوزارة .","s":"غَضِبَ المعتَصِمُ على الفضل بن مروان بعد المكانةِ العظيمةِ التي كانت له، وعَزَله عن الوَزارةِ وحبَسَه وأخذ أموالَه، وجعل مكانَه محمَّدَ بن عبدالملك بن الزيات، فكان المعتَصِمُ يقول: عصى اللهَ وأطاعني، فسلَّطني اللهُ عليه."},{"id":723,"era":"c3","t":"الخليفة المعتصم يأمر بتأسيس مدينة سامراء .","s":"خرج المعتَصِمُ إلى سامِرَّا لبنائِها، وكان سببُ ذلك أنَّه قال إني أتخوَّفُ هؤلاء الحربيَّةَ أن يَصيحوا صيحةً فيَقتُلوا غِلماني، فأريدُ أن أكونَ فوقهم، فإن رابني منهم شيءٌ أتيتُهم في البَرِّ والماء، حتى آتيَ عليهم، فخرج إليها فأعجَبَه مكانَها، وقيل: كان سببُ ذلك أنَّ المعتصِمَ كان قد أكثَرَ مِن الغِلمان الأتراك، فكانوا لا يزالونَ يَرَون الواحِدَ بعد الواحدِ قتيلًا، وذلك أنَّهم كانوا جفاةً، يركبون ا"},{"id":724,"era":"c3","t":"القضاء على حكم بابك الخرمي في أذربيجان .","s":"تقدَّمَ الأفشين حتى شارف الموضِعَ الذي كانت به الوقعةُ في العام الماضي، فاختار ثلاثةَ جبالٍ كان عليها حصونٌ فخُرِّبَت، فسَدَّ الطريقَ إلى تلك الجبال، حتى صارت كالحُصون، وأمر بحفرِ خَندقٍ على كلِّ طريقٍ وراء تلك الحجارةِ، وكان جماعةٌ مِن الخرمية يأتونَ إلى قرب خندق الأفشين فيَصيحون، فلم يترُك الأفشين أحدًا يخرجُ إليهم، فَعَلوا ذلك ثلاثةَ أيام، ثمَّ إنَّ الأفشين كَمَن لهم كمينًا، فإذا جاؤوا ثاروا عل"},{"id":725,"era":"c3","t":"إخضاع أهل طليطلة لعبدالرحمن بن الحكم .","s":"وقع عِصيانُ أهل طليطِلة على عبدِ الرحمنِ بنِ الحكم بن هشام، صاحِبِ الأندلس، وتم َّإنفاذُ الجيوش لمحاصرتها مرَّةً بعد مرة، فلمَّا كانت هذه السَّنةُ خرج جماعةٌ مِن أهلها إلى قلعةِ رباح، وبها عسكرٌ لعبد الرحمن، فاجتمعوا كلُّهم على حصر طليطلة، وضَيَّقوا عليها وعلى أهلِها وقطعوا عنهم باقيَ مرافِقِهم واشتَدُّوا في محاصرتِهم، فبَقُوا كذلك إلى أن سَيَّرَ عبد الرحمن أخاه الوليدَ بنَ الحكم إليها أيضًا، فرأى"},{"id":726,"era":"c3","t":"هجوم ملك الروم على المسلمين بزبطرة .","s":"خرج توفيل بن ميخائيل ملِكُ الروم إلى بلادِ الإسلام، وأوقع بأهلِ زبطرة وغيرها، وكان سبَبُ ذلك أنَّ بابك لَمَّا ضَيَّقَ الأفشينُ عليه، وأشرف على الهلاك، كتب إلى مَلِك الروم توفيل يُعلِمُه أنَّ المعتَصِمَ قد وجَّهَ عساكِرَه ومقاتليه إليه، ولم يَبقَ على بابِه أحدٌ، فإن أردت الخروجَ إليه فليس في وجهِك أحدٌ يَمنَعُك؛ ظنًّا أن ذلك يخَفِّفُ عنه، فخرج توفيل في مائة ألفٍ، وقيل أكثر، منهم من الجندِ نَيِّفٌ و"},{"id":727,"era":"c3","t":"محاولة العباس بن المأمون قتل عمه المعتصم .","s":"كان العباسُ بنُ المأمون مع عَمِّه المعتَصِم في غزوةِ عَمُّورية، وكان عجيفُ بن عنبسة قد نَدَّمَه إذ لم يأخُذ الخلافةَ بعد أبيه المأمونِ، ولامَه على مبايعتِه عَمَّه المعتصِمَ ولم يزل به حتى أجابه إلى الفتك بعمِّه وأخذِ البيعةِ من الأمراء له، وجهَّزَ رجلًا يقال له الحارِثُ السَّمَرقندي وكان نديمًا للعبَّاسِ، فأخذ له البيعةَ مِن جماعةٍ مِن الأمراء في الباطنِ، واستوثَقَ منهم وتقَدَّم إليهم أنَّه يلي ال"},{"id":728,"era":"c3","t":"القائد الأفشين يقود بابك الخرمي أسيراً إلى المعتَصِم .","s":"بعد أن أنهى الله فتنةَ بابك الخرمي، وقضى عليه وعلى جيشِه الأفشينُ ومن معه، وقبض على بابك وحَبَسه وراسَلَ المعتَصِمَ فأمره بتسييرهم إليه, فدخل الأفشينُ وبِصُحبتِه بابك على المعتَصِم سامرَّا، ومعه أيضًا أخو بابك في تجمُّلٍ عظيم، وقد أمر المعتَصِمُ ابنَه هارونَ الواثِقَ أن يتلقَّى الأفشين، وأمَرَ بابك أن يركَبَ على فيلٍ ليُشهَرَ أمرُه ويعرفوه، وعليه قباءُ ديباج وقَلَنْسُوة سمور مدورة، وقد هيؤوا الفيل"},{"id":729,"era":"c3","t":"مقتل زعيم فرقة الخُرَّميَّة بابك الخرمي .","s":"هو بابَك الخُرَّمي (بابک خرمدین) زعيمٌ ديني فارسيٌّ، وقائدُ فرقة الخُرَّميَّة ظهر سنة 201هـ الموافق 816 م، في خلافةِ المأمون العباسي, وكثُرَ أتباعهُ، وقاد ثورةً على العباسيِّينَ بعد مصرعِ أبي مسلم الخراساني، استمَرَّت حوالى عشرينَ سنة، وكان أحد الشُّجعانِ، أخاف الإسلامَ وأهلَه، وهزم الجيوشَ العباسيَّة عشرين سنة، وغلبَ على أذربيجانَ وغَيرِها، وأراد أن يقيم المِلَّةَ المجوسيَّة، وعَظُم البلاء. فأنفق"},{"id":730,"era":"c3","t":"وفاة أمير إفريقية زيادة الله بن الأغلب .","s":"هو أبو محمَّد زيادةُ الله بن إبراهيم بن الأغلب أو زيادةُ الله الأوَّل، أميرُ إفريقيَّة، وكان أفصَحَ أهلِ بَيتِه لسانًا وأكثَرَهم أدبًا، وكان يقولُ الشعر، ويرعى الشعراءَ، كانت ولايته من قِبَل المأمون سنة 201هـ، فطالت أيَّامُه واستقام الأمر, وبنى زيادةُ الله في أيَّامِه سُورَ القيروان ودار سوسة وقنطرة باب الربيع، وحِصنَ الرباط بسوسة، وجامعَ القيروان بعد هَدمِه، وأنفق عليه سِتَّة وثمانين ألف دينار، و"},{"id":731,"era":"c3","t":"الخليفة العباسي المعتصم بالله يفتح مدينة عمورية .","s":"لَمَّا فعل الرُّومُ ما فعلوا بأهلِ زبطرة وغيرِها، وكانت فِتنةُ بابك قد انتهت، سار المعتَصِمُ بجَيشِه قاصدًا فتحَ عَمُّوريَّة؛ إذ كانت تعَدُّ من أقوى مُدُنِ الروم، بل ربما كانت بمكانةِ القُسطنطينيَّة، فكان أوَّلَ الأمرِ أن التقى الأفشينُ مع الروم وهَزَمَهم شَرَّ هزيمةٍ، ثم سار المعتَصِمُ والأفشين وأشنان، كلٌّ على رأس جيشٍ، متوجِّهينَ إلى عمُّورية وكانت حصينةً ذاتَ سورٍ منيعٍ وأبراجٍ تحَصَّنَ أهلُها"},{"id":732,"era":"c3","t":"خروج مازيار بن قارن على نائب خراسان .","s":"خرج رجلٌ بآمل طبرستان يقال له مازيار بن قارن بن يزداهرمز، وكان لا يرضى أن يدفَعَ الخراجَ إلى نائب خراسان عبد الله بن طاهر بن الحُسَين، بل يبعثه إلى الخليفةِ ليقبِضَه منه، فيبعث الخليفةُ من يتلقى الحملَ إلى بعض البلاد ليقبِضَه منه ثم يدفَعُه إلى ابن طاهر، ثم آل أمرُه إلى أن وثب على تلك البلادِ وأظهر المخالفةَ للمُعتَصِم، وقد كان المازيار هذا ممَّن يكاتب بابك الخرميَّ ويَعِدُه بالنصر، ويقال: إنَّ ال"},{"id":733,"era":"c3","t":"خروج منكجور على المعتصم في أذربيجان .","s":"لَمَّا فرَغَ الأفشينُ مِن بابك وعاد إلى سامِرَّا استَعمَلَ على أذربيجان منكجورَ- وهو من أقارِبِه- فوجد في بعض قرى بابك مالًا عظيمًا ولم يُعلِمْ به المعتَصِم، ولا الأفشين، فكتب صاحِبُ البريد إلى المعتَصِم، وكتب منكجور يُكَذِّبه، فتناظرا، فهم منكجور ليقتُلَه، فمنعه أهلُ أردبيل، فقاتَلَهم منكجور، وبلغ ذلك المعتَصِم، فأمر الأفشينَ بعزل منكجور، فوجَّه قائدًا في عسكرٍ ضَخمٍ، فلما بلغ منكجورَ الخبَرُ خلع"},{"id":734,"era":"c3","t":"هزيمة نصارى الأندلس على يد عبد الرحمن بن الحَكَم .","s":"سيَّرَ عبدُ الرحمن بن الحَكَم عبدَ اللهِ المعروفَ بابنِ البَلنسيِّ إلى بلادِ العَدُوِّ، فوصلوا إلى \"ألبة\" والقلاعِ، فخرج المشركونَ إليه في جَمعِهم، وكان بينهم حربٌ شديدة وقتالٌ عظيم، فانهزم المشركونَ، وقُتلَ منهم ما لا يُحصى، وجُمِعَت الرؤوس أكداسًا، وفي هذه السنة أيضًا خرج لذريق في عسكَرِه، وأراد الغارةَ على مدينةِ سالم من الأندلس، فسار إليه عبدُ الرحمن بن الحَكَم فوتون بن موسى في عسكَرٍ جرار، فل"},{"id":735,"era":"c3","t":"وفاة أبي عبيد القاسم بن سلام .","s":"هو القاسِمُ بنُ سلَّام الهروي الأزدِيُّ ولاءً، ولد بمدينة هراة سنة 157هـ, أحد أئمَّة اللُّغة والفقه والحديثِ، والقرآن والأخبار وأيَّام الناس، كان أبوه عبدًا روميًّا, فطلب أبو عبيدٍ العِلمَ وسَمِعَ الحديثَ ودرسَ الأدبَ والفقه، ثم ارتحل إلى العراقِ نحوَ سنة 176هـ، له المصنَّفات المشهورة المنَتِشرة بين الناس، حتى يقال: إنَّ الإمامَ أحمدَ كتب كتابَه الغريبَ بِيَدِه- وهو أشهر كتُبِه- قال هلالُ بن العلا"},{"id":736,"era":"c3","t":"قيام الدولة اليعفرية بصنعاء .","s":"هي ثاني دولة مستقِلَّة تقوم في اليمَنِ ويُنسَبُ اليعفريون إلى الملوك الحِمْيَريين، ويعتبر يعفرُ بن عبد الرحيم المؤسِّسَ الفعليَّ لهذه الدولة، وكان الخليفةُ المعتَمِد قد عيَّنه عاملًا على صنعاءَ قبل أن يستقِلَّ بالسلطة ويؤسِّسَ الدولة، ولكِنَّ الخلافاتِ نَشَبت بين أفراد الأسرة اليعفريَّة، فضَعُف مركزُها لتنتهي لاحقًا وتدخُلَ في طاعة دولة الأئمَّة. في آخِرِ عهدِ المتوكِّلِ ابتدأت الدولةُ اليعفرية بص"},{"id":737,"era":"c3","t":"وفاة الأغلب بن إبراهيم صاحب إفريقية .","s":"هو أبو عِقالٍ الأغلَبُ بن إبراهيم بن أغلب، أخو زيادة الله، كانت ولايتُه من قِبَل المعتَصِم بالله، وهو رابِعُ أمراء إفريقية مِن بني الأغلَبِ، ولم تطُلْ مُدَّةُ أيامِه، كانت ولايتُه سنتين وسبعةَ أشهر وسبعة أيَّام, لَمَّا تولَّى أبو عقالٍ أحسَنَ إلى الجند، وأزال مظالمَ كثيرةً، وزاد العُمَّالَ في أرزاقهم، وكَفَّ أيديَهم عن الرعية، وقطَعَ النَّبيذَ والخَمرَ عن القيروان. وكانت أيَّامُه أيَّامَ دَعةٍ وسك"},{"id":738,"era":"c3","t":"قتل أفشين أكبر قائد عسكري عباسي .","s":"هو حَيدرُ بنُ كاوس الملقَّب بالأفشين، أصلُه من التُّرك مِن أشروسنة تركستان، كان مجوسيًّا مِن سُلالةِ حُكَّام أشروسنة، اعتنق الإسلامَ زمنَ المأمونِ وأقام ببغدادَ عند المعتصِم، وعَظُم محلُّه عنده, وهو من كِبارِ قادةِ المأمونِ والمعتَصِم، تولى إخمادَ الكثيرِ مِن الفِتَن والثَّوراتِ، وأهمُّها ثورةُ بابك الخرمي، ولكن كان يطمَحُ لتولِّي خُراسان بدل عبدالله بن طاهرٍ، فقيل: إنَّه هو الذي حرَّضَ المازيار ل"},{"id":739,"era":"c3","t":"خروج المبرقع أبو حرب اليماني في فلسطين .","s":"خرج بفلسطينَ المُبرقَعُ أبو حربٍ اليمانيُّ الذي زعَمَ أنَّه السُّفياني، فدعا بالأمرِ بالمعروفِ والنَّهيِ عن المنكرِ أولًا، إلى أن قَوِيَت شَوكتُه، فادعى النبوَّةَ. وكان سببُ خُروجِه أن جنديًّا أراد النزولَ في داره، فمنَعَتْه زوجتُه، فضَرَبها الجنديُّ بسوطٍ فأثَّرَ في ذراعها، فلما جاء المُبرقَعُ شكَت إليه، فذهب إلى الجنديِّ فقَتَله وهَرَب، ولَبِسَ بُرقعًا لئلَّا يُعرَف، ونزل جبالَ الغَور مُبرقَعًا،"},{"id":740,"era":"c3","t":"فتنة القيسية بدمشق .","s":"لَمَّا مات المعتَصِم ثارت القيسيَّة بدمشقَ وعاثوا وأفسَدوا وحَصَروا أميرَهم، فبعث الواثِقُ إليهم رجاءَ بنَ أيوب الحضاري، وكانوا مُعسكِرينَ بمَرج راهط، فنزل رجاءٌ بدير مران، ودعاهم إلى الطاعةِ، فلم يَرجِعوا فواعَدَهم الحربَ بدَومة يومَ الاثنين. فلما كان يومُ الأحد، وقد تفَرَّقت، سار رجاءٌ إليهم، فوافاهم وقد سار بعضُهم إلى دومة، وبعضُهم في حوائجه، فقاتَلَهم وقتل منهم نحوَ ألف وخمسمائة، وقُتِلَ مِن أ"},{"id":741,"era":"c3","t":"وفاة الخليفة العباسي المعتصم  .","s":"هو أبو إسحاقَ محمَّد المعتَصِم بالله بن هارون الرَّشيد بن محمد المهدي بن عبد الله المنصور بن محمد بن علي بن عبد الله بن العباس، ثامِنُ الخُلَفاءِ العباسيِّينَ، وُلِدَ سنة 179ه يوم الخميسِ لثماني عشرة مَضَت من ربيع الأول، بُويع بالخلافةِ يوم الخميس لاثنتي عشرة ليلةً بَقِيَت من رجب سنة ثماني عشرة ومائتين، وبعد ذلك بأيَّامٍ اجتمع جماعةٌ من الجند وشغَّبوا وتحدَّثوا في بيعةِ العبَّاسِ بنِ المأمونِ وأظه"},{"id":742,"era":"c3","t":"تولِّي الواثق بالله الخلافة .","s":"بويِعَ الواثِقُ باللهِ هارونُ بنُ المعتَصِم في اليومِ الذي توفِّيَ فيه أبوه، وكان يكنَّى أبا جعفرٍ، وأمُّه أمُّ ولَدٍ روميَّة، تسمَّى قراطيس."},{"id":743,"era":"c3","t":"وفاة بشر الحافي .","s":"هو بِشرُ بنُ الحارثِ بنِ علي المعروفُ بالحافي، مِن أهلِ مَروٍ، ولِدَ سنة 152هـ سكن بغدادَ، كان من أكابرِ الزُّهَّاد، وأخبارُه في الزُّهدِ والوَرَع مشهورةٌ جِدًّا ومعروفة، أثنى عليه غيرُ واحدٍ مِن الأئمَّةِ في عبادتِه وزهادتِه وورَعِه ونُسكِه وتقَشُّفِه. قال الإمامُ أحمد يوم بلَغَه مَوتُه: \"لم يكُنْ له نظيرٌ إلَّا عامِرُ بنُ عبد قيس، ولو تزوَّجَ لتَمَّ أمْرُه\"، وذكر غيرُ واحدٍ أن بِشرًا كان شاطِرًا"},{"id":744,"era":"c3","t":"خروج عامل مدينة تطيلة موسى بن موسى على أمير الأندلس .","s":"سبَبُ ذلك أنَّ موسى بن موسى كان من أعيانِ قُوَّادِ عبد الرحمن، وهو العامِل على مدينةِ تَطيلة، فجرى بينه وبين القُوَّادِ تحاسُدٌ سنةَ سَبعٍ وعشرين، فعصِيَ موسى بن موسى على عبد الرحمنِ بنِ الحَكَم، فسَيَّرَ إليه جيشًا واستعمل عليهم الحارِثَ بنَ يزيغ والقُوَّاد، فاقتتلوا عند برجة، فقُتل كثيرٌ من أصحاب موسى، وقُتِلَ ابنُ عَمٍّ له، وعاد الحارِثُ إلى سرقسطة، فسيَّرَ موسى ابنَه ألب بن موسى إلى برجة، فعاد"},{"id":745,"era":"c3","t":"عبد الرحمن بن الحكم يقضي على مجوس الأندلس .","s":"خرج المجوسُ كما سمَّاهم الأندلسيُّون، وهم النرماند أو الفايكونغ، في نحو ثمانين مركبًا، فحَلُّوا بأشبونة، ثمَّ أقبلوا إلى قادس، وشذونة، ثم قَدِموا على إشبيلية فدخَلوها قَسرًا، واستأصلوا أهلَها قَتلًا وأسْرًا. فبَقُوا بها سبعة أيام، يسقونَ أهلَها كأسَ الحِمامِ. واتَّصلَ الخبَرُ بالأميرِ عبدِ الرحمن بن الحَكَم، فقَدِمَ على الخيلِ عيسى بن شهيد الحاجِب، وتوجَّه بالخيلِ عبدُ الله ابن كليب وابنُ رستم وغي"},{"id":746,"era":"c3","t":"إخضاع بني سليم وبني هلال من قبائل أعراب المدينة .","s":"كان سببُ ذلك أنَّ بني سُليم كانت تُفسِدُ حولَ المدينة بالشَّرِّ، ويأخذون ما أرادوا من الأسواقِ بالحجازِ بأيِّ سِعرٍ أرادوا، وزاد الأمرُ بهم إلى أن وقَعُوا بناسٍ مِن بني كِنانة وباهلة، فأصابُوهم، وقتلوا بعضَهم، فوَجَّهَ محمَّدُ بن صالح- عامِلُ المدينةِ- إليهم حمَّادَ بنَ جريرٍ الطبري، وكان مَسلَحةً لأهل المدينة، في مائتي فارسٍ، وأضاف إليهم جندًا غيرَهم، وتَبِعَهم متطوِّعة، فسار إليهم حمَّاد، فلَقِي"},{"id":747,"era":"c3","t":"الخليفة الواثق بالله يأمر بامتحان العلماء في مسألة خلق القرآن .","s":"لم تَزَل هذه الفتنةُ ساريةً مِن أيام المأمونِ إلى أيَّامِ المُعتَصِم ثمَّ إلى أيام الواثق، فبَقِيَ على نفسِ مِنوالِ صاحِبَيه السابقَينِ، يمتَحِنُ العلماء بمسألة خَلْقِ القرآنِ ومسألةِ رؤية الله تعالى يومَ القيامة، وسُجِنَ مَن سُجِن وقُتِل من قُتل بسبب هذا، حتى ورد كتابُ الخليفةِ هارون الواثقُ إلى الأعمالِ بامتحانِ العُلَماءِ بخلقِ القُرآنِ، وكان قد منع أبوه المعتَصِمُ ذلك، فامتحَنَ الناسَ ثانيًا ب"},{"id":748,"era":"c3","t":"محمد بن عبد الرحمن أمير الأندلس يحاصر مدينة ليون .","s":"غزا بالصائفة جليقية محمَّد بن الأمير عبد الرحمن بن الحَكَم، فحَصَرها، وحصَرَ مدينة ليون، ورماها بالمجانيقِ. فلمَّا أيقنَ أهلُها بالهلاك خرجوا ليلًا، ولجؤوا إلى الجبالِ والغِياض، فأحرقَ محمَّدٌ ما فيها، وأراد هدمَ سُورِها، فوجد سعتَه ثمانيَ عشرة ذراعًا فتركه، وأمعن في بلادِ الشِّركِ قتلًا وسبيًا."},{"id":749,"era":"c3","t":"الخليفة الواثق يمتحن أسارى المسلمين في الروم بمسألة خلق القرآن .","s":"وقَعَت مُفاداةُ الأُسارى بين المسلمينَ والرُّوم، واجتمع المسلِمونَ على نهرِ اللَّامس، على مسيرةِ يومٍ مِن طرسوس، واشترى الواثِقُ من بغداد وغيرِها من الروم، وعقَدَ الواثِقُ لأحمد بن سعيد بن سلم بن قُتيبة الباهلي على الثغور والعواصِم، وأمره بحضورِ الفِداءِ هو وخاقان الخادِم، وأمَرَهما أن يمتحنا أَسرى المُسلِمينَ، فمن قال: القرآنُ مَخلوقٌ، وإنَّ اللهَ لا يُرى في الآخرةِ، فوُدِيَ به، وأعطِيَ دِينارًا،"},{"id":750,"era":"c3","t":"مقتل أحمد بن نصر الخزاعي بسبب عدم قوله بخلق القرآن .","s":"هو أبو عبدِ اللهِ أحمَدُ بنُ نصرِ بن مالك بن الهيثم الخُزاعي المروزي، ثم البغدادي، الإمامُ الكبيرُ الشَّهيدُ، ثِقةٌ فاضِلٌ، مِن كبارِ العُلَماء الآمِرينَ بالمعروفِ والنَّاهينَ عن المُنكَر. كان أحمَدُ بنُ نصرٍ يُخالِفُ مَن يقولُ: القُرآنُ مخلوقٌ، ويُطلِقُ لِسانَه فيه، مع غِلظةِ بالواثق، وكان يقولُ- إذا ذكَرَ الواثِقَ: فعَلَ هذا الخِنزيرُ، وقال هذا الكافِرُ، وفشا ذلك، فكان يغشاه رجلٌ يُعرَفُ بأبي ها"},{"id":751,"era":"c3","t":"استقلال إمارة بني يعفر عن العباسيين وظهور أوَّل إمام زَيديٍّ في صنعاء .","s":"في حوالَيْ عامِ 232هـ ومع ضَعفِ الحُكام العباسيِّينَ بدأت تظهرُ أطماعُ بعضِ الوُلاةِ المحلِّيينَ في كَوْكبانَ وعلى رأسِهم يَعفُرُ بنُ عبدِ الرحمنِ الحَوَاليُّ. ومع أواخِرِ القرنِ التاسعِ الميلاديِّ، أصبحت اليَمنُ قاعدةَ عملياتٍ لحركةِ الشِّيعةِ الفاطميِّينَ. وقد عهِدَ يَعفُرُ بالسُّلطةِ لابنِه محمدٍ الذي فضَّلَ أن تكونَ مِن صَنعاءَ، ثم عهِدَ محمدُ بنُ يَعفُرَ بالسُّلطةِ بعدَ ذلك لابنِه إبراهيمَ، ا"},{"id":752,"era":"c3","t":"وفاة الخليفة العباسي الواثق .","s":"هو الواثِقُ هارون بن محمد المعتصِم بالله بن هارون الرشيد، تاسِعُ الخُلَفاء العباسيين، ولد ببغداد سنة 200هـ، ومُدَّة خلافتِه خمسُ سنين وتسعة أشهر وخمسة أيام، وقيل سبعة، وفي نفسِ اليوم بويع لأخيه المتوكِّل بالخِلافةِ."},{"id":753,"era":"c3","t":"تولي المتوكل الخلافة العباسية .","s":"وكانت الأتراكُ قد عَزَموا على توليةِ محمَّدِ بنِ الواثق، فاستصغروه فتَرَكوه وعَدَلوا إلى أخيه جعفر، وكان عُمُره إذ ذاك ستًّا وعشرين سنة، وكان الذي ألبَسَه خِلعةَ الخلافة أحمدَ بن أبي دؤاد القاضي، وكان هو أوَّلَ مَن سلَّم عليه بالخلافةِ، وبايعه الخاصَّةُ والعامَّةُ، وكانوا قد اتَّفَقوا على تسميته بالمنتَصِر بالله، إلى صبيحةِ يوم الجمعة، فقال ابنُ أبي دؤاد: رأيت أن يلقَّبَ بالمتوكِّل على الله، فاتَّ"},{"id":754,"era":"c3","t":"ثورة سالم بن غلبون بإفريقيا .","s":"عزل محمَّدُ بن الأغلبِ- أميرُ إفريقيَّةَ- عامِلَه على الزاب، واسمُه سالم بن غلبون، فأقبلَ يريدُ القيروانَ، فلما صار بقلعةِ يلبسير أضمَرَ الخلافَ وسار إلى الأربس، فمَنَعه أهلُها من الدخول إليها، فسار إلى باجة، فدخلها واحتمى بها فسيَّرَ إليه ابنُ الأغلب جيشًا عليهم خفاجةُ بن سفيان، فنزل عليه وقاتَلَه، فهرب سالمٌ ليلًا، فاتبعه خفاجة، فلَحِقَه وقتَلَه، وحمَلَ رأسَه إلى ابنِ الأغلب، وكان أزهرُ بن سالم "},{"id":755,"era":"c3","t":"وفاة يحيى بن معين .","s":"هو الإمامُ الحافِظُ الجَهبَذُ، شيخُ المحَدِّثين، أبو زكريَّا يحيى بن مَعِينِ بنِ عون بن زياد بن بسطام. الغطفانيُّ, ثم المُرِّي مولاهم البغدادي. ولد سنة ثمان وخمسينَ ومائة. أحدُ أعلامِ أئمَّة الحديثِ، سيِّدُ الحفَّاظِ، إمامُ عَصرِه بالجَرح ِوالتَّعديلِ، وإليه المنتهى والمرجِعُ بذلك، وقال الإمام أحمد: \"كلُّ حديثٍ لا يَعرِفُه يحيى، فليس بحديثٍ\"، له كتابٌ في العِلَلِ، وكتابٌ في الجَرحِ والتعديل، توفِّ"},{"id":756,"era":"c3","t":"خروج محمد بن البعيث بأذربيجان على الخليفة المتوكل .","s":"خرج محمَّدُ بنُ البعيث بن حلبس عن الطاعةِ في بلاده أذربيجان، وأظهر أن المتوكِّلَ قد مات، والتفَّ عليه جماعةٌ مِن أهلِ تلك الرساتيق، ولجأ إلى مدينةِ مرند فحصَّنَها، وجاءته البعوثُ مِن كلِّ جانبٍ، وأرسل إليه المتوكِّلُ جيوشًا يَتبَعُ بَعضُها بعضًا، فنصبوا على بلده المجانيقَ مِن كلِّ جانب، وحاصروه محاصرةً عظيمةً جِدًّا، وقاتلهم مُقاتلةً هائلة، وصبَرَ هو وأصحابُه صبرًا بليغًا، وقَدِمَ بغا الشرابي لمحا"},{"id":757,"era":"c3","t":"الخليفة العباسي المتوكل يلغي القول بخلق القرآن .","s":"بعد أن تمكَّنَ المتوكِّلُ من الخلافةِ ولم يكُنْ على مذهَبِ أخيه ومَن قَبلَه في مسألةِ خَلْقِ القرآنِ، وخاصَّةً أنَّه لم يُقَرِّبْ أحمدَ بنَ أبي دؤاد المعتزليَّ، كما كان مقرَّبًا للواثِقِ، فأمر وكتَبَ بالكَفِّ عن امتحانِ النَّاسِ بمسألةِ خَلقِ القُرآنِ، حتى هدَّدَ بالقتلِ مَن امتحَنَ فيها وأعاد القولَ فيها، ونشَرَ السُّنَّةَ, واستقدم الإمامَ أحمَدَ إليه واعتذَرَ إليه، وشاوره بمن يُرشَّحُ للقضاءِ، ف"},{"id":758,"era":"c3","t":"خروج عمرو بن سليم على دولة الأغالبة في أفريقيا .","s":"خرج عَمرُو بنُ سُليم التجيبي- المعروفُ بالقويع- على محمَّدِ بنِ الأغلب أميرِ إفريقيَّة، فسيَّرَ إليه جيشًا، فحصره بمدينةِ تونس، فلم يبلُغوا منه غرضًا فعادوا عنه. فلما دخَلَت سنة خمس وثلاثين سيَّرَ إليه ابن الأغلب جيشًا، فالتَقَوا بالقرب من تونس، ففارق جيشَ ابنِ الأغلب جمعٌ كثيرٌ، وقصدوا القويعَ فصاروا معه، فانهزم جيشُ ابن الأغلب وقَوِيَ القُويع؛ فلما دخلت سنةُ ستٍّ وثلاثين سيَّرَ محمد بن الأغلب إل"},{"id":759,"era":"c3","t":"وفاة علي بن المديني .","s":"هو عليُّ بنُ عبدالله بن جعفر المعروفُ بابنِ المديني، إمامُ عَصرِه في الجرحِ والتَّعديلِ والعِلَل، وُلِدَ سنةَ إحدى وستين ومائةٍ، أحدُ الأعلامِ، وصاحبُ التصانيفِ، روى عنه الأئمَّةُ: البُخاري، وأحمد، والنَّسائي، وغيرُهم، قال ابن عُيَينة: \"لولا ابنُ المدينيِّ ما جَلَستُ\"، وقال النَّسائيُّ: \"كأنَّ اللهَ خلَقَ عليَّ بن المديني لهذا الشأنِ\"، وقيل للبخاريِّ ما تشتهي؟ قال: \"أقدَمُ العِراقَ وعَلِيُّ بنُ عب"},{"id":760,"era":"c3","t":"الخليفة المتوكل يأمر بتمييز أهل الذمة عن المسلمين .","s":"أمر المتوكِّلُ أهلَ الذِّمَّة بلُبسِ الطَّيالِسة العسليَّة، وشَدِّ الزنانيرِ، ورُكوبِ السُّروجِ بالركب الخشَب، وعَمَل كُرَتَين في مؤخَّرِ السروج، وعمَل رُقعَتَين على لباسِ مَماليكِهم مُخالِفَتينِ لِلَونِ الثوب، كلُّ واحدةٍ منهما قَدْرُ أربعة أصابِعَ، ولونُ كلِّ واحدةٍ منهما غيرُ لون الأخرى، ومن خرجَ مِن نسائهم تلبس إزارًا عسليًّا، ومنعهم من لباسِ المناطِقِ، وأمَرَ بهَدمِ بِيَعِهم المُحدَثة، وبأخْذ"},{"id":761,"era":"c3","t":"ظهور محمود بن الفرج في سامرا يزعم أنه نبي .","s":"خرج رجلٌ يقال له محمودُ بن الفَرَج النيسابوري، وهو ممَّن كان يتردَّدُ إلى خشَبةِ بابك وهو مصلوبٌ فيقعُدُ قريبًا منه، وذلك بقُربِ دار الخلافةِ بسُرَّ من رأى، فادَّعى أنَّه نبيٌّ، وأنَّه ذو القرنينِ، وقد اتَّبَعه على هذه الضَّلالة ووافَقَه على هذه الجَهالةِ جماعةٌ قليلونَ، وهم تسعة وعشرون رجلًا، وقد نظَمَ لهم كلامًا في مصحَفٍ له- قبَّحه الله- زعم أنَّ جبريلَ جاءه به من الله، فأتيَ به وبأصحابِه المتو"},{"id":762,"era":"c3","t":"أخذ الخليفة العباسي المتوكل العهد لأولاده .","s":"عقد المتوكل البيعة لبنيه الثلاثة بولاية العهد وهم محمد، ولقبه المنتصر بالله، وأبو عبد الله محمد؛ وقيل طلحة، وقيل الزبير، ولقبه المعتز بالله، وإبراهيم، ولقبه المؤيد بالله، وعقد لكل واحد منهم لواءين أحدهما أسود وهو لواء العهد، والآخر أبيض وهو لواء العمل، وأعطى كل واحد منهم عدة ولايات."},{"id":763,"era":"c3","t":"وفاة أبي بكر بن أبي شيبة صاحب المصنف .","s":"هو الإمامُ العَلَمُ, سَيِّدُ الحفَّاظ, أبو بكر عبدُالله بن محمد بن القاضي أبي شيبة إبراهيم بن عثمان بن خُوَاستَى العبسي مولاهم, الكوفي. ولد بالكوفةِ عام 159هـ. أحدُ أعلام الحديثِ، صاحِبُ المصَنَّف المعروف. أخو الحافظ عثمانَ بنِ أبي شيبة، والقاسمِ بن أبي شيبة الضَّعيف. فالحافظ إبراهيمُ بن أبي بكر هو ولَدُه, والحافِظُ أبو جعفر محمد بن عثمان هو ابنُ أخيه, فهُم من بيتِ علم, وأبو بكر: أجَلُّهم. قال أبو"},{"id":764,"era":"c3","t":"الخليفة المتوكل يتخلص من الأتراك بعد تدخُّلُهم في شؤونِ الدَّولةِ .","s":"كان إيتاخُ التركي قائدَ جيشِ المتوكِّلِ وإليه المغاربة، والأتراك، والأموال، والبريد، والحِجابة، ودارُ الخلافة, وكان الأتراكُ بعد أن رشَّحوا المتوكِّلَ للخلافةِ بعد أبيه، بدأ تدخُّلُهم في شؤونِ الدَّولةِ، فلمَّا تمكَّنَ المتوكِّلُ من الخلافةِ، وقد أدرك خطرَ الأتراكِ على الدولةِ، عَمِلَ على تَصفيتِهم، وبدأ بمربِّيه إيتاخَ التركيِّ، فلما عاد إيتاخ مِن مكَّةَ، وكان حاجًّا تلك السنةَ كتب المتوكِّلُ إلى"},{"id":765,"era":"c3","t":"الخليفة العباسي المتوكل يأمر بهدم قبر الحسين بن علي .","s":"أمَرَ المتوكِّلُ بهَدمِ قَبرِ الحُسَين بنِ عليِّ بنِ أبي طالب وما حولَه من المنازلِ والدُّورِ، ونودي في الناسِ: مَن وُجِدَ هنا بعد ثلاثةِ أيَّامِ ذَهَبتُ به إلى المطبق (سجن من سجون بغداد)، فلم يبقَ هناك بَشَرٌ، واتُّخِذَ ذلك الموضِعُ مَزرعةً تُحرَثُ وتُستغَلُّ."},{"id":766,"era":"c3","t":"ثورة حبيب البرنسي في الأندلس .","s":"ثار رجُلٌ من البربر، يقالُ له حبيبٌ البرنسي، بجبال الجزيرة؛ فتجَمَّع إليه جماعةٌ من أهل الشَّرِّ والفساد في الأرضِ، فشَنَّ بهم الغارةَ على قُرى رية وغيرها، فأشاع الأذى، ونهبَ وقتَل وسَبى،، فأخرج إليه عبدُ الرحمن الأجنادَ، فلما وصلوا إليه ألْفَوُا البربرَ قد قَصَدوا حبييًا ومن تجمَّعَ إليه، فتغَلَّبوا على المعقل الذي كان انضوى إليه، وأخرجوه عنه، وقتلوا عدةً كثيرةً من أصحابه. وافتَرَق بقيَّتُهم عنه،"},{"id":767,"era":"c3","t":"ظهور رجل من المعلِّمينَ بشَرقِ الأندلس يدعي النبوءة .","s":"قام رجلٌ من المعلِّمينَ بشَرقِ الأندلس، فادَّعى النبوءةَ، وتأوَّلَ القرآن على غيرِ تأويلِه، فاتَّبَعه جماعةٌ مِن الغوغاء، وقام معه خَلقٌ كثيرٌ، وكان من بعض شرائِعِه النهيُ عن قَصِّ الشعرِ وتقليم الأظفار، ويقول: [لا تغييرَ لخلق الله] فبعث إليه يحيى بنُ خالد، فأتى به. فلما دخل عليه كان أوَّل ما خاطبه به أنْ دعاه إلى اتِّباعِه والأخذِ بما شرَع، فشاور فيه أهلَ العِلمِ، فأشاروا بأن يُستَتابَ، فإن تاب و"},{"id":768,"era":"c3","t":"بداية ظهور يعقوب بن الليث الصفار في سجستان .","s":"كان صالحُ بنُ النضر الكناني من أهلِ بُست، قد ظهر بتلك الناحية يقاتِلُ الخوارج، وسمَّى أصحابَه المتطوِّعةَ، حتى قيل له: صالح المطوِّعي وصَحِبَه جماعةٌ؛ منهم: درهم بن الحسن، ويعقوب بن الليث, وغَلَبوا على سجستان، ثم أخرَجَهم عنها طاهرُ بن عبد الله أميرُ خراسان. وهلك صالح إثر ذلك، وقام بأمر المتطوِّعةِ دِرهمُ بن الحسن، فكَثُرَ أتباعه. وكان يعقوبُ بن الليث شهمًا، وكان دِرهَم مُضعفًا، واحتال صاحِبُ خراس"},{"id":769,"era":"c3","t":"وفاة الخوارزمي واضع علم الجبر .","s":"هو أبو عبدالله- وقيل: أبو جعفر- محمَّد بن موسى الخوارزمي، رياضيٌّ فلَكيٌّ جغرافيٌّ مؤرِّخٌ، من أهل خوارزم, وقيل ولد عام 164هـ بخوارزم, وكان يُنعَت بالأستاذِ، أقامه المأمونُ قَيِّمًا على خزانة كتُبِ بيتِ الحكمة، وعَهِدَ إليه بجَمعِ الكتب اليونانية وترجَمتِها، ترجم كتابَ بطليموس المجسطي، فصار أساسَ عِلمِ الفلك، ووضع جدولًا فلكِيًّا للمواقع الجغرافيَّة بحسب الابتعادِ التدريجيِّ عن خطِّ الزوال، يعتبَر"},{"id":770,"era":"c3","t":"الخليفة المتوكل يعزل ابن أبي دؤاد المعتزلي وينصر السنة .","s":"غَضِبَ المتوكِّلُ على ابنِ أبي دؤاد القاضي المعتزليِّ، وكان على المظالمِ، فعَزَله عنها واستدعى يحيى بنَ أكثَمَ، فولاه قضاءَ القُضاةِ والمظالمِ أيضًا. وفي ربيع الأوَّل أمر الخليفةُ بالاحتياطِ على ضِياعِ ابنِ أبي دؤاد، وأخَذَ ابنَه أبا الوليد محمَّدًا فحَبَسه في يوم السبتِ لثلاثٍ خَلَونَ من ربيع الآخر، وأمَرَ بمصادرتِه، فحَمَل مائةَ ألفِ وعشرين ألف دينار، ومن الجواهِرِ. كان ابنُ أبي دؤاد قد أصابه ال"},{"id":771,"era":"c3","t":"الخليفة المتوكل ينتقم من البطارقة لقتلهم عامل أرمينية .","s":"وكان سببُ ذلك أنَّ يوسُفَ بنَ محمَّد- عامِلَ أرمينيَّةَ- لَمَّا سار إلى أرمينية خرج إليه بِطْريقٌ يقال له بقراط بن أشوط، ويقال له بِطريقُ البطارقة، يطلبُ الأمان، فأخذه يوسُفُ وابنُه نعمة، فسيَّرَهما إلى باب الخليفة، فاجتمع بطارقة أرمينية مع ابن أخي بقراط بن أشوط، وتحالفوا على قتلِ يوسُفَ، ووافقهم على ذلك موسى بن زرارة، وهو صِهرُ بقراط على ابنتِه، فأتى الخبَرُ يوسف، ونهاه أصحابُه عن المُقام بمكانه،"},{"id":772,"era":"c3","t":"الروم يحتلون دمياط ثم ينسحبون .","s":"جاء ثلاثُمائة مركَبٍ للرُّومِ مع ثلاثةِ رُؤساء، فأناخ أحدُهم في مائةِ مركَبٍ بدمياط، وكان على معونةِ مِصرَ عَنبسةُ بن إسحاق الضبِّي، فلما حضَرَ العيدُ أمَرَ الجندَ الذين بدمياط أن يَحضُروا مصر، فساروا منها، فاتَّفَق وصولُ الرومِ وهي فارغةٌ من الجندِ، فنَهَبوا وأحرقوا وسَبَوا، وأحرقوا جامِعَها، وأخذوا ما بها من سلاحٍ ومَتاعٍ، وقَنْدٍ، وغير ذلك، وسَبَوا من النساء المُسلِمات والذِّمِّيات نحو ستمائة ا"},{"id":773,"era":"c3","t":"وفاة أمير الأندلس عبدالرحمن الأوسط .","s":"هو أبو المطَرِّف عبدالرحمنِ بنُ الحكَم بن هشام بن عبدالرحمن الداخل، رابِعُ أمراء الأندلس، ويلقَّبُ بالأوسط، أو عبدالرحمن الثاني، ولد عام 176هـ, كان مكثرًا للغَزو، فتصدى للثوراتِ الداخليَّة وعدوان النَّصارى في شمال الأندلُسِ، وغارات النورماند البحريَّة, وكان يحِبُّ العِمرانَ، فبنى المساجِدَ والقصور، وفي عَهدِه كَثُرت وفودُ المشارقة العلماء. توفِّي في قرطبة بعد حُكمٍ دام 32 سنةً، مخلِّفًا من الأولاد"},{"id":774,"era":"c3","t":"القائد بغا الكبير يحاصر مدينة تفليس ويستولى عليها .","s":"حاصَرَ بغا مدينة تفليس، وعلى مقَدِّمته زيرك التركي، فخرج إليه صاحبُ تفليس إسحاقُ بنُ إسماعيل فقاتله، فأُسِرَ إسحاق، فأمر بغا بضَربِ عُنُقِه وصَلبِه، وأمَرَ بإلقاء النارِ في النفطِ إلى نحو المدينة، وكان أكثَرُ بنائها من خشَبِ الصَّنَوبر، فأَحرَقَ أكثَرَها، وأحرقَ من أهلِها نحوًا من خمسين ألف إنسان، وخَمِدَت النار بعد يومينِ; لأنَّ نارَ الصنوبر لا بقاء لها، ودخل الجندُ فأسَروا من بقي من أهلِها، واست"},{"id":775,"era":"c3","t":"وفاة إسحاق بن راهويه .","s":"هو الإمامُ الكبيرُ، شَيخُ المَشرِق، سيِّدُ الحُفَّاظ، أبو يعقوب: إسحاق بن إبراهيم بن مَخلَد الحنظلي التيميُّ المروزي، المعروف بابنِ راهَوَيه، ولد بمرو عام 161هـ كان مِن أهل مرو، وسكن نيسابور، أحدُ الأئمَّة الحُفَّاظ، شيخ البخاريِّ وأحمد ومسلم وغيرهم، فكُلُّهم روى عنه، قال الحسن بن عبد الصمد: سمعتُ إسحاقَ بن إبراهيم يقول: أحفَظُ سبعينَ ألف حديثٍ كأنَّها نُصبَ عيني. اجتمع فيه الحديثُ والفِقهُ، والحِ"},{"id":776,"era":"c3","t":"الخليفة العباسي المتوكل يزيد في التغليظ على أهل الذمة .","s":"أمرَ المتوكِّلُ بأخذِ أهلِ الذِّمَّة بلُبسِ ذِراعَينِ عَسليتيَّن على الأقبيةِ والدراريع، وبالاقتصارِ في مراكِبِهم على ركوبِ البِغالِ والحَميرِ دون الخَيلِ والبَراذينِ، وأمر المتوكِّلُ بهدمِ البِيَعِ المُحدَثةِ في الإسلامِ."},{"id":777,"era":"c3","t":"إصلاح قلعة رباح بالأندلس بعد أن هدم أهلُ طليطِلة سورها .","s":"سيَّرَ محمَّدُ بن عبد الرحمن جيشًا مع أخيه الحكَمِ إلى قلعةِ رباح، وكان أهلُ طليطِلة قد خَرَّبوا سُورَها وقتَلوا كثيرًا من أهلِها، وأصلح الحكَمُ سُورَها وأعاد مَن فارَقَها من أهلها إليها، وأصلح حالَها، وتقدَّمَ إلى طليطِلة فأفسد في نواحيها وشَعثِها وسيّرَ محمد أيضًا جيشًا آخَرَ إلى طليطلة، فلما قاربوها خرجت عليهم الجنودُ مِن المكامن، فانهزم العسكَرُ، وأصيب أكثرُ من فيه."},{"id":778,"era":"c3","t":"وفاة الحافظ الكبير عثمان بن أبي شيبة  .","s":"هو الإمامُ الحافِظُ الكبيرُ المفَسِّر: أبو الحسن عثمانُ بن محمد بن القاضي بن أبي شيبة إبراهيم خواستى العبسي مولاهم الكوفي، صاحب التصانيفِ، وأخو الحافظ أبي بكرِ بن أبي شيبة، صاحب كتاب \"المصنَّف\" والقاسِم بن أبي شيبة الضعيف.  فهم من بيت علم, وأبو بكر: أجلُّهم. وهو شيخُ البخاري ومسلم، وقد أكثَرَ عنه البخاري في (صحيحه)."},{"id":779,"era":"c3","t":"معركة وادي سليط وانتصار المسلمين على أهل طليطلة وحلفائهم .","s":"خرج الأميرُ محمد بنفسِه إلى طليطلة. فلمَّا عَلِمَ أهلُها بذلك، أرسلوا إلى أردن بن إذفونش صاحِبِ جليقية، يعلمونَه بحَركتِه ويستَمِدُّون به. فبعث إليهم أخاه غثون في جمعٍ عظيمٍ مِن النصارى. فلمَّا عَلِمَ بذلك الأميرُ محمد، وقد كان قاربَ طليطلة، أعملَ الحيلةَ والكيد، وأخذ بالحَزمِ، فعبَّأَ الجيوشُ، وكمَنَ الكمائِنَ بناحية وادي سليط، ثم نصب الردودَ، وطلع في أوائلِ العسكر في قِلَّةٍ من العدد. فلما رأى ذ"},{"id":780,"era":"c3","t":"ثورة أهل حمص على عاملهم أبي المُغيث موسى الرافعي .","s":"وثب أهلُ حِمصٍ بعامِلِهم أبي المُغيث موسى بن إبراهيم الرافعي، وكان قتَلَ رجلًا من رؤسائِهم، فقتلوا جماعةً مِن أصحابه، وأخرجوه، وأخرجوا عامِلَ الخراج، فبعث المتوكِّلُ إليهم عتَّاب بن عتاب، ومحمد بن عبدويه الأنباري، وقال لعتَّاب: قلْ لهم: إنَّ أميرَ المؤمنينَ، قد بَدَّلَكم بعامِلِكم، فإن أطاعوا فوَلِّ عليهم محمد بن عبدويه، فإن أبَوْا فأقمْ وأعلِمْني، حتى أُمِدَّك برجالٍ وفُرسانٍ، فساروا إليهم، فرَضُ"},{"id":781,"era":"c3","t":"وفاة أفلح بن عبدالوهاب الإباضي إمامُ الرستميَّة بالمغرب الأوسط .","s":"هو أفلحُ بن عبدالوهاب بن عبدالرحمن بن رستم، إمامُ الرستميَّة الإباضيَّة الثالث في تاهرت، بويع له للإمامة بعد أبيه عام 190هـ، كان حازِمًا للأمورِ، وقد خرجت عليه كثيرٌ من الحروبِ والفِتَن، كان مؤيِّدًا للأُمَويِّين في الأندلس، وهو الذي أحرق مدينةَ العباسيَّة التي بناها الأغالبةُ عام 239هـ وكافأه على ذلك عبدُالرحمن الأوسط أميرُ الأندلس بمائة ألف دِرهَم، ودامت إمامتُه للرستمية خمسين سنة، واستخلف بعدَه"},{"id":782,"era":"c3","t":"وفاة ابن أبي دؤاد المعتزلي .","s":"هو أبو عبدِ الله أحمدُ بنُ أبي دؤاد فرج بن جرير بن مالك بن عبد الله بن عباد بن سلام، ولد سنةَ ستين ومائة بقِنَّسرينَ، ونشأ بدمشق, وكان أبوه تاجرًا يَفِدُ إلى الشام، ثم وفد إلى العراق وأخذ ولَدَه هذا معه إلى العراق، فارتحل للبصرةِ، واتصل ابن أبي دؤاد بأصحاب واصلِ بنِ عطاء، وعنهم أخذ مذهَبَ الاعتزالِ، ثم اتَّصلَ بالمأمونِ فكان قاضيَ القُضاةِ، وكان موصوفًا بالجود والسَّخاءِ وحُسنِ الخُلقِ ووُفورِ الأ"},{"id":783,"era":"c3","t":"الخليفة المتوكل يفتدي أسرى المسلمين من ملكة الروم .","s":"كان الفِداءُ بين المُسلِمينَ والروم، بعد أن قَتَلَت تدورة- ملكةُ الرُّومِ- من أسرى المسلمينَ اثني عشر ألفًا، فإنَّها عَرَضت النصرانيَّة على الأسرى، فمن تنَصَّرَ جعَلَتْه أسوةَ مَن قَبلَه من المتنصِّرة، ومن أبى قتَلَتْه، وأرسلت تطلُبُ المفاداةَ لِمَن بقي منهم، فأرسل المتوكِّلُ شنيفًا الخادم، فأذِنَ له فحضره واستخلف على القضاءِ ابنَ أبي الشوارب، وهو شابٌّ، ووقع الفداءُ على نهر اللامس، فكان أسرى المُ"},{"id":784,"era":"c3","t":"تمرد طائفة البُجاة من سودان بلاد النُّوبة على الخليفة المتوكل .","s":"البُجاة هم طائفةٌ مِن سودان بلاد المغرب، وكذا النُّوبة وشنون وزغرير ويكسوم، وأممٌ كثيرةٌ لا يعلَمُهم إلا الله، وفي بلادِ هؤلاء معادنُ الذهب والجوهر، وكان عليهم حملٌ في كُلِّ سَنةٍ إلى ديار مصر من هذه المعادنِ، فلما كانت دولةُ المتوكِّل امتنعوا من أداءِ ما عليهم سنينَ مُتَعدِّدة، فكتب نائِبُ مِصرَ إليه يُعلِمُه بذلك، فلما شاور المتوكِّلُ في أمرِهم أعلموه أنَّهم في أرضٍ بعيدةٍ، ومن أراد قتالَهم عليه"},{"id":785,"era":"c3","t":"ثورة أهل حمص على عاملهم محمد بن عبدويه الأنباري .","s":"بعد أن وثب أهلُ حِمصٍ العامَ الماضي على أبي المُغيثِ موسى بن إبراهيم الرافعي، ثم أبدلهم المتوكل بمحمد بن عبدويه الأنباري ورضوا به، لم يَسِرْ بهم العامِلُ الجديدُ سِيرةً حَسنةً، بل فعل فيهم الأعاجيبَ، فوثب أهلُ حمص بعامِلِهم الجديد محمد بن عبدويه، وأعانَهم عليه قومٌ مِن نصارى حمص، فكتب إلى المتوكِّلِ، فكتب إليه يأمُرُه بمناهَضتِهم، وأمَدَّه بجندٍ مِن دمشق والرملة، فظفر بهم، فضرب منهم رجُلَينِ مِن ر"},{"id":786,"era":"c3","t":"وفاة الإمام أحمد بن حنبل .","s":"هو أبو عبدِ الله أحمدُ بنُ مُحمَّد بن حنبل بن هلال بن أسَدٍ الشَّيباني المروزي، نزيل بغداد، أحدُ الأئمَّة الأربعة المشهورينَ في الفقهِ، ثِقةٌ حافِظٌ، فقيهٌ حُجَّةٌ، وهو رأسُ الطَّبقة العاشرة، خرجت أمُّه من مرو وهي حامِلٌ به، فولدته في بغداد، في شهرِ ربيع الأول سنة أربع وستين ومائة، وقيل: إنَّه وُلِدَ بمَروٍ وحُمِلَ إلى بغداد وهو رضيعٌ. نشأ وتعلَّمَ ببغداد. كان مخضوبًا، طُوالًا، أسمرَ شديدَ السُّمر"},{"id":787,"era":"c3","t":"وفاة محمد بن الأغلب أمير أفريقيا .","s":"هو أبو العبَّاسِ محمَّدُ بن الأغلب أمير إفريقيَّة، تولى الإمارةَ بعد موت أبيه عام 226هـ، ودانت له إفريقيَّةُ، وشَيَّدَ مدينةً بقرب تاهرت، وسمَّاها العباسية، وذلك سنة 227هـ, حاول أخوه أبو جعفرٍ أن يأخُذَ الإمارةَ منه عام 231هـ، لكنَّه تغلب عليه ونفاه، ثم ثار عليه سالمُ بنُ غلبون وعمرو بن سليم. توفِّيَ وعمره ستٌّ وثلاثون سنةً، دامت إمارتُه خمس عشرة سنة وثمانية أشهر، وولِيَ بعدَه ابنُه أحمد إمارةَ إف"},{"id":788,"era":"c3","t":"الجيوش الأندلسية تدخل برشلونة .","s":"كتب الأميرُ محمَّدُ بنُ عبدالرحمن إلى موسى بن موسى بحَشدِ الثُّغورِ والدُّخولِ إلى برشلونة، فغزاها وافتتح في هذه الغَزاةِ حِصنَ طراجة، وهي مِن آخر أحواز برشلونة، ومِن خُمُسِ ذلك الحِصنِ زِيدَت الزَّوائِدُ في المسجد الجامِعِ بسَرقسطة، وكان الذي أسَّسَه ونصب محرابَه حنش الصنعاني، وهو من التابعينَ."},{"id":789,"era":"c3","t":"الأميرُ محمَّد بن عبد الرحمن يقضي على فتنة أهل طليطلة في الأندلس .","s":"وقَعَت في هذه السَّنةِ وَقعةٌ عَظيمةٌ في أهل طليطِلة، وذلك أنَّهم خرجوا إلى طلبيرة، فخرج إليهم قائِدُها مسعود بن عبد الله العريف، بعد أن كمَنَ لهم الكمائِنَ، فقتلهم قتلًا ذريعًا، وبعث إلى قُرطبةَ بسَبعمائة رأسٍ مِن رؤوس أكابِرِهم، ثم في سنة 244هـ خرج الأميرُ محمَّد بنَفسِه إلى طليطلة، وعدَدُهم قد قَلَّ، بتواتر الوقائِعِ عليهم، ونزولِ المصائبِ بهم، فلم تكن لهم حربٌ إلا بالقنطرة. ثم أمر الأميرُ بقَط"},{"id":790,"era":"c3","t":"دخول الخليفة العباسي المتوكل دمشق وعزمه على اتخاذها مقرًا له .","s":"خرج المتوكِّلُ من العراقِ قاصدًا دِمشقَ فأدركه الأضحى في الطريق ولم يَصِل دمشق إلَّا في أوَّلِ هذه السنة، فدخل الخليفةُ المتوكِّلُ إلى مدينة دمشق في أُبَّهة الخلافةِ، وكان يومًا مشهودًا، وكان عازمًا على الإقامة بها، وأمَرَ بنقل دواوينِ المُلْك إليها، وأمَرَ ببناء القصور بها، فبُنِيَت بطريق داريا، فأقام بها مدَّةً، ثم إنَّه استوخَمَها ورأى أنَّ هواءَها بارِدٌ نَدِيٌّ وماءَها ثقيلٌ بالنسبة إلى هواءِ"},{"id":791,"era":"c3","t":"فتح المُسلِمين مَدينةَ قصريانة في بلاد الروم .","s":"فتح المُسلِمونَ مَدينةَ قصريانة، وهي المدينةُ التي بها دارُ المُلْك بصقلية، وكان المَلِكُ قبلها يسكُنُ سرقوسة، فلما مَلَك المسلمونَ بعضَ الجزيرة نقل دارَ المُلك إلى قصريانة لحصانَتِها. وسبَبُ فَتحِها أنَّ العبَّاسَ بنَ الفَضلِ- أميرَ صقلية- سار في جيوشِ المسلمين إلى مدينة قصريانة، وسرقوسة، وسيَّرَ جيشًا في البحر، فلَقِيَهم أربعون شلندي للرُّوم، فاقتتلوا أشَدَّ قتال، فانهزم الرومُ، وأخذ منهم المسلم"},{"id":792,"era":"c3","t":"ملك الروم يطلب من الخليفة المتوكل المفاداة بين الأسرى .","s":"بعث مَلِكُ الرُّوم بأسرى من المسلمينَ، ويسألُ المُفاداة بمن عنده وكان الذي قَدِمَ من قِبَل صاحب الروم رسولًا إلى المتوكِّلِ شَيخًا يُدعى أطرو بيليس، معه سبعةٌ وسبعون رجلًا من أسرى المسلمين أهداهم ميخائيل بن توفيل ملك الروم إلى المتوكِّلِ، فأنزل على شنيف الخادم، ثم وجَّه المتوكِّلُ نصر بن الأزهر مع رسولِ صاحِبِ الروم، فشخص في هذه السنة ولم يقَع الفداءُ إلَّا في سنة ستٍّ وأربعين."},{"id":793,"era":"c3","t":"خروج النورماند (المجوس) في الأندلس .","s":"خرج المجوسُ (النورماند) إلى ساحِلِ البحر بالغرب، في اثني وستين مركبًا، فوجدوا البحر محروسًا، ومراكِبَ المُسلِمينَ مُعَدَّة، تجري من حائطِ إفرنجة إلى حائطِ جليقية في الغرب الأقصى، فتقدم مركبانِ مِن مراكبِ المجوسِ، فتلاقت بهم المراكِبُ المُعَدَّة، فوافَوا هذين المركبينِ في بعضِ كُسورِ باجة؛ فأخذوهما بما كان فيهما من الذهَبِ والفِضَّة والسَّبيِ والعُدَّة. ومَرَّت سائر مراكِبِ المجوس في الريفِ حتى انت"},{"id":794,"era":"c3","t":"الحرب بين البربر وابن الأغلب في أفريقيا .","s":"وقَعَت بين البربرِ وعسكَرِ أبي إبراهيم أحمدَ بنِ محمد بن الأغلب وقعةٌ عظيمةٌ، وسبَبُها أنَّ بربرَ لهان امتنعوا على عاملِ طرابلس من أداءِ عُشورِهم وصَدقاتِهم، وحاربوه فهَزَموه، فقصد لبدة فحَصَّنَها وسار إلى طرابلس، فسَيَّرَ إليه أحمد بن محمد الأمير جيشًا مع أخيه زيادةِ الله، فانهزم البربَرُ، وقُتل منهم خلقٌ كثيرٌ، وسيَّرَ زيادةُ الله الخيلَ في آثارهم، فقَتَلَ من أدرك منهم، وأسَرَ جماعةً، فضُرِبَت أ"},{"id":795,"era":"c3","t":"بناء مسجد القرويين الجامع بالمغرب .","s":"يعتبر مَسجِدُ القُرَويِّينَ بفاس من أعرَقِ المساجد المغربيَّة وأقدَمِها. وتكادُ تُجمِعُ الدراسات التاريخية على أنَّ هذا المسجِدَ بَنَتْه فاطمةُ الفِهريَّة (أم البنين) في عهدِ دولة الأدارِسة، أمَّا بداية بناء مسجد القُرويين فشُرِعَ في حفر أساسِ مَسجِدِ القرويين والأخذِ في أمرِ بنائِه هذه السَّنة بمطالعةِ الإدريسي يحيى الأوَّل، وأمُّ البنين فاطمةُ الفِهريَّة هي التي تطَوَّعَت ببنائه وظَلَّت صائمةً م"},{"id":796,"era":"c3","t":"فتح المسلمين حِصنَ أنطاكية وتبادل الأسرى مع الروم .","s":"غزا عمرُو بنُ عبد الله الأقطَع الصائفةَ، فأخرج سبعةَ عشرَ ألف رأس، وغزا قريباس، وأخرج خمسةَ آلافِ رأس، وغزا الفضلُ بن قارن بحرًا في عشرينَ مركبًا، فافتتح حِصنَ أنطاكية، وغزا بلكاجور، فغَنِمَ وسَبَى، وغزا عليُّ بن يحيى الأرمني، فأخرج خمسةَ آلافِ رأس، ومن الدوابِّ والرمك والحمير، ونحوًا من عشرةِ آلاف رأس، وفيها كان الفداءُ على يدِ عليِّ بنِ يحيى الأرمني، ففُودِيَ بألفين وثلاثمائة وسبعة وستين نفسًا."},{"id":797,"era":"c3","t":"بداية قيام دولة الزيديين في صعدة وصنعاء باليمن .","s":"تزعَّمَ بنو الرسي بصَعدة وصنعاء، وقام الحسَنُ بن قاسم الرسي بتأسيسِ دولَتِهم، وهم من الأئمَّة الزيديِّين، والقاسم الرسي هو القاسِمُ بن إبراهيم المعروف بطباطبا بن إسماعيلَ بنِ الحسن بن الحسن بن علي بن أبي طالب، وكان بُويِعَ بالإمامةِ بعد موت أخيه محمَّد، وبقي متخَفِّيًا مدةً هاربًا من بلد لآخرَ، حتى استقَرَّ بأرمينية في الرسِّ، وفيها مات فعُرِفَ بالرسِّي."},{"id":798,"era":"c3","t":"غزو العباس بن الفضل بلاد الروم .","s":"نكث العهدَ كثيرٌ مِن قِلاعِ صَقَلية وهي: وسطر، وابلا وابلاطنوا وقلعة عبد المؤمن، وقلعة البلوط، وقلعة أبي ثور، وغيرها من القلاع، فخرج العباسُ بنُ الفضل إليهم، فلَقِيَهم عساكِرُ الروم، فاقتتلوا فانهزم الرومُ، وقُتل منهم كثير. وسار إلى قلعةِ عبد المؤمن وقلعة ابلاطنوا فحصرها، فأتاه الخبر بأنَّ كثيرًا من عساكر الرُّومِ قد وصلت، فرحل إليهم، فالتقوا بجفلودى، وجرى بينهم قتالٌ شديد، فانهزمت الروم، وعادوا إ"},{"id":799,"era":"c3","t":"أميرُ الأندلس محمَّد بن عبد الرحمن يغزو أرض بنبلونة .","s":"أغزى الأميرُ محمَّد بن عبد الرحمن إلى أرضِ بنبلونة أحدَ قوَّاده، فخرج في هذه الغزوة خروجًا لم يُخرَجْ قَبلَه مِثله جَمعًا وكثرةً، وكمالَ عِدَّة، وظهورَ هيبةٍ. وكان ابنُ غرسية صاحِبُ بنبلونة إذ ذاك متظافِرًا مع أزدون صاحب جليقية، فأقام هذا القائِدُ يدوِّخُ أرضَ بنبلوبة، متردِّدًا فيها اثنين وثلاثين يومًا، يخرِّبُ المنازل، وينسِفُ الثمار، ويفتح القُرى والحصون. وافتتح في الجملة حِصنَ قشتيل، وأخذَ فيه"},{"id":800,"era":"c3","t":"اغتيال الخليفة العباسي المتوكل وتولي ابنه المنتصر الخلافة .","s":"كان مَقتلُ الخليفةِ المتوكِّلِ على الله على يَدِ وَلَدِه المنتَصِر، وكان سببُ ذلك أن المتوكِّلَ أمَرَ ابنَه عبدَ الله المعتَزَّ أن يخطُبَ بالناسِ في يومِ جمعة، فأدَّاها أداءً عظيمًا بليغًا، فبلغ ذلك من المنتَصِر كلَّ مبلغٍ، وحَنقَ على أبيه وأخيه، وزاد ذلك أنَّ المتوكِّلَ أراد من المنتَصِر أن يتنازلَ عن ولايةِ العهد لأخيه المعتَزِّ فرفض، وزاد ذلك أيضًا أنَّه أحضَرَه أبوه وأهانَه وأمَرَ بضَربِه في ر"},{"id":801,"era":"c3","t":"وفاة الخليفة العباسي المتوكل على الله .","s":"هو أميرُ المؤمنينَ أبو الفضلِ بنِ المعتَصِم بالله محمَّد بن هارون الرَّشيد القُرَشي العبَّاسي البغدادي. ولِدَ سنةَ خَمسٍ ومائتين، وبويعَ في ذي الحِجَّة سنةَ اثنتينِ وثلاثين بعد الواثقِ, وتلقَّبَ بالمتوكِّل على الله. وكان أسمَرَ مليحَ العينينِ، نحيفَ الجِسمِ خفيفَ العارِضَينِ، إلى القِصَرِ أقرَب. وأمُّه أمُّ ولد اسمُها: شجاع. قال خليفة: \"استُخلِفَ المتوكِّلُ، فأظهرَ السُّنَّةَ وعَمِلَ بها في مجلِسِ"},{"id":802,"era":"c3","t":"خلع المعتَز والمؤيَّد أبناء المتوكِّل من ولاية العهد .","s":"خُلِعَ المعتَزُّ والمؤيَّدُ ابنا المتوكِّل من ولاية العهد؛ وكان سببُ خَلعِهما أنَّ المنتصرَ لَمَّا استقامت له الأمور، قال أحمد بن الخصيب لوصيف بغا: إنَّا لا نأمَنُ الحَدَثانَ وأن يموتَ أميرُ المؤمنين، فيلي المعتزُّ الخلافةَ، فيُبيدُ خَضراءَنا ولا يُبقي منا باقيةً؛ والآنَ الرأيُ أن نعمل في خلعِ المعتَزِّ والمؤيَّد، فجدَّ الأتراك في ذلك، وألحُّوا على المنتصر، وقالوا نخلَعُهما من الخلافة، ونبايِعُ لا"},{"id":803,"era":"c3","t":"وفاة  الخليفة العباسي المنتصر بالله .","s":"هو أبو جعفر \"المنتصر بالله\" محمد بن جعفر المتوكِّل، وأمُّه أمُّ ولدٍ روميَّةٌ اسمُها حبشية. وكان أعينَ أسمَرَ أقنى, مليحَ الوجهِ, رَبْعةً, كبيرَ البطن, مَهيبًا، لَمَّا قُتِل أبوه دخل عليه التُّركُ ومعهم قاضي القضاة جعفر بن عبد الواحد الهاشمي، فقال له: بايِعْ. قال: وأين أمير المؤمنين؟ -يعني: المتوكِّل- قال: قتله الفتحُ بن خاقان. قال: وأين الفتح? قال: قتله بغا, فبايعه القاضي ثم الوزير وكبار قادة الت"},{"id":804,"era":"c3","t":"تولي المستعين بالله بن المعتصم الخلافة العباسية .","s":"بُويعَ أحمد بن محمد بن المعتَصِم بالخلافة؛ وكان سببَ ذلك أنَّ المنتصِرَ لَمَّا توفِّي اجتمع الموالي على الهارونيَّة من الغد، وفيها بغا الكبيرُ، وبغا الصغير، وأتامش، وغيرهم، فاستحلفوا قوَّاد الأتراك، والمغاربة، والشروسنية على أنْ يرضَوا بمن رضِيَ به بغا الكبير، وبغا الصغير، وأتامش، وذلك بتدبيرِ أحمد بن الخصيب، فحَلَفوا وتشاوروا وكَرِهوا أن يتولَّى الخلافةَ أحد من ولد المتوكِّل؛ لئلَّا يغتالَهم، واج"},{"id":805,"era":"c3","t":"تولي خفاجة بن سفيان إمارة صقلية  .","s":"بعد وفاة أمير صقليَّة العباسِ بن الفضل، ولَّى الناسُ عليهم ابنَه عبد الله بن العباس، وكتبوا إلى أميرٍ بإفريقيَّة بذلك، وأخرج عبد الله السرايا ففتحَ قِلاعًا متعَدِّدة منها: جبل أبي مالك، وقلعة الأرمنين، وقلعة المشارعة، فبقي كذلك خمسة أشهر، ووصل من إفريقية خفاجة بن سفيان أميرًا على صقليَّة، فأوَّلُ سريَّةٍ أخرجها سريَّةٌ فيها ولدُه محمود، فقصَدَ سرقوسة فغَنِم،  فخرج إليه أهلُها فقاتلهم حتى ظَفِرَ به"},{"id":806,"era":"c3","t":"وفاة بغا الكبير أبو موسى التركي .","s":"هو بغا الكبير أبو موسى التركي، مُقَدَّمُ قُوَّادِ المتوكِّل وأكبَرُهم، كان شجاعًا مِقدامًا وله همَّةٌ عالية وهيبة، ووقْعٌ في النُّفوسِ، وكان مملوكًا للحسن بن سهل الوزير، وكان يُحمَّق ويجهَّل في رأيه، أسهم في اغتيالِ الخليفة المتوكِّل، ثم سيطر على الخليفة المستعين الذي لم يكُنْ له من الأمر شيءٌ غير الاسم، فغَلَب على المستعين هو ووصيفُ الأمير، حتى قيل: خليفةٌ في قفصٍ بين وصيف وبغا ** يقول ما قالا له"},{"id":807,"era":"c3","t":"وفاة أمير خراسان طاهر بن عبدالله .","s":"توفِّيَ طاهِرُ بن عبدالله بن طاهر بن الحُسين الخزاعي، أميرُ خراسان وابنُ أميرها, وكان قد ولِيَ إمرة خراسان بعد أبيه ثماني عشرة سنة, فلما ورد على المستعين وفاةُ طاهر بن عبدالله، عقدَ لابنه محمَّد بن طاهر على خراسان، ولمحمد بن عبدالله بن طاهرٍ على العراق، وجعل إليه الحَرَمين، والشُّرطة"},{"id":808,"era":"c3","t":"غزو عبد الملك بن العباس نصارى شمال الأندلس .","s":"خرج عبد الرحمن بن الأمير محمَّد إلى حصون ألبة والقلاع؛ وكان القائِدُ عبد الملك بن العباس؛ فافتتَحها، وقتَل الرجال، وهدَمَ البُنيان؛ وانتقل في بسائطِها من موضع إلى موضع يحطِمُ الزروع، ويقطَعُ الثمار. وأخرج أردون بن إذفونش أخاه إلى مضيق الفجِّ ليقطع بالمُسلمين، ويتعرَّضَهم فيه؛ فتقَدَّم عبد الملك فقاتَلَهم على المَضِيقِ، حتى هزمهم وقتَلَهم وبدَّدَهم؛ ثم وافَتْهم بقيَّة العساكر، وأظلَّتهم الخيلُ من ك"},{"id":809,"era":"c3","t":"شغب العامة ببغداد وسامرا بسبب تسلط الأتراك .","s":"كان سبَب ذلك أنَّه لَمَّا وصل خبَرُ مقتل عمر بن عبيد الله، وعلي بن يحيى، أثناءَ غَزوِهما للروم للشاكريَّة والجند ببغداد وسامرَّا وما قرب منهما، وكانا من شجعان الإسلام، شَقَّ ذلك عليهم، وما لَحِقَهم من استعظامِهم قتلَ الأتراك للمتوكِّل، واستيلائِهم على أمور المسلمين، يقتلون من يريدون من الخُلَفاء، ويستخلفون من أحبُّوا من غير ديانةٍ، ولا نظَرٍ للمُسلمين، فاجتمعت العامَّة ببغداد وأخذوا في الصُّراخ، و"},{"id":810,"era":"c3","t":"عمر بن عبيد الله الأقطع يغزو بلاد الروم .","s":"غزا جعفر بن دينار الصائفةَ، فافتتح حصنا ومطأمير، واستأذنه عمر بن عبيد الله الأقطع في المسيرِ إلى بلاد الروم، فأذن له، فسار في خلقٍ كثير من أهل ملطيَّة، فلقيه الملِكُ في جمع عظيم من الروم بمرج الأسقف، فحاربَه محاربةً شديدةً قُتِلَ فيها من الفريقينِ خَلقٌ كثير، ثم أحاطت به الروم، وهم خمسون ألفًا، وقتل عمر وممَّن معه ألفان من المسلمين، فلما قُتِلَ عمر بن عبيد الله خرج الرومُ إلى الثغور الجزرية، وكلبو"},{"id":811,"era":"c3","t":"ظهور يحيى بن عمر الطالبي بالعراق .","s":"كان ظهور أبي الحسين يحيى بن عمر بن يحيى بن حسين بن زيد بن علي بن الحسين بن علي بن أبي طالب، أنَّه أصابته فاقةٌ شديدةٌ فدخل سامرَّا فسأل وصيفًا أن يجري عليه رزقًا فأغلظ له القولَ، فرجع إلى أرض الكوفة فاجتمع عليه خلقٌ من الأعراب، وخرج إليه خلقٌ من أهل الكوفة، فنزل على الفلوجة، وقد كثُرَ الجمع معه، فكتب محمد بن عبد الله بن طاهر نائبُ العراق إلى عامِلِه يأمُرُه بقتالِه، وظهر أمرُه بالكوفة واستحكم بها،"},{"id":812,"era":"c3","t":"وفاة زيادة الله الثاني بن محمد بن الأغلب أمير أفريقية .","s":"هو أبو محمد زيادةُ الله بن محمد بن الأغلب بن إبراهيم بن الأغلب ولِيَ أفريقيَّة يوم وفاة أخيه أحمد أبو إبراهيم، في ذي القعدة، سنة 249هـ, وكان زيادة الله عاقلًا حليمًا حسَن السيرةِ جميلَ الأفعال، ذا رأيٍ ونجدة وجُودٍ وشجاعةٍ. وهو الثاني ممن اسمه زيادة الله في بني الأغلب، وهو ثامن أمراء الأغالبة بأفريقية، واستمَرَّت إمارته سنة وأيامًا، ثم تولى من بعده ابن أخيه محمد الثاني المعروف بأبي الغرانيق."},{"id":813,"era":"c3","t":"ثورة أهل حمص على عاملهم الفضل بن قارن .","s":"وثب أهلُ حمص وقومٌ من كلب، بعامِلِهم، وهو الفضل بن قارن أخو مازيار بن قارن، فقَتَلوه، فوجَّه المستعين إلى حمص موسى بن بغا الكبير، فلَقِيَه أهلُها فيما بين حمص والرستن، وحاربوه، فهَزَمهم، وافتتح حمص، وقتلَ من أهلها مقتلةً عظيمة، وأحرَقَها وأسر جماعةً من أعيان أهلِها."},{"id":814,"era":"c3","t":"ظهور الحسن بن زيد العلوي بطبرستان .","s":"خرج الحسَنُ بن زيد بن محمد بن إسماعيل بن الحسَن بن زيد بن الحسن بن علي بن أبي طالب بناحية طبرستان، وكان سبب خُروجِه أنَّه لَمَّا قُتِلَ يحيى بن عمر أقطع المستعينُ لمحمد بن عبد الله بن طاهر طائفةً مِن أرض تلك الناحية، فبعث كاتبًا له يقال له جابر بن هارون، وكان نصرانيًّا، ليتسَلَّم تلك الأراضي، فلما انتهى إليهم كرهوا ذلك جدًّا، وأرسلوا إلى الحسن بن زيد هذا، فجاء إليهم فبايعوه والتَفَّ عليه جملةُ الد"},{"id":815,"era":"c3","t":"فتنة إسماعيل بن يوسف الطالبي (السفاك) بمكة .","s":"ظهر إسماعيل بن يوسف بن إبراهيم بن موسى بن عبد الله بن الحسن بن الحسن بن علي بن أبي طالب بمكَّة، فهرب منه نائبُها جعفر بن الفضل بن عيسى بن موسى، فانتَهَبَ مَنزِلَه ومنازلَ أصحابه وقَتَلَ جماعةً من الجند وغيرهم من أهل مكة، وأخَذَ ما في الكعبة من الذَّهَب والفِضَّة والطِّيب وكسوة الكعبة، وأخَذَ من الناس نحوًا من مائتي ألف دينار، ثم خرج إلى المدينةِ النبويَّة فهرب منها نائبُها أيضًا علي بن الحسين بن ع"},{"id":816,"era":"c3","t":"غزوة عبد الرحمن بن محمد ألبة والقلاع وهزيمة المركويز .","s":"خرج إلى هذه الغزاةِ عبد الرحمن بن محمَّد، وتقدَّمَ حتى حلَّ على نهرِ دوبر وتوالت عليه العساكرُ من كل ناحية، فرتَّبَها ثم تقَدَّم، فاحتل بفج برذنش، وكانت عليه أربعة حصون، فتغلب العسكرُ عليها، وغنم المسلمون جميعَ ما فيها وخربوها، ثم انتقل من موضعٍ إلى موضع، لا يمُرُّ بمسكنٍ إلَّا خرَّبه، ولا موضِعٍ إلا حَرَقه، حتى اتصلَ ذلك في جميع بلادهم، ولم يبقَ لرذريق صاحب القلاع، ولا أردمير صاحب توفة، ولا لعندش"},{"id":817,"era":"c3","t":"خروج الحسين بن أحمد الكوكبي الطالبي .","s":"خرج الحسين بن أحمد بن محمد بن إسماعيل بن محمد بن الأرقط عبدالله بن زين العابدين علي بن الحسين الكوكبي الطالبي بقزوين، فالتقى موسى بن بغا الكبير هو والحسين بن أحمد الكوكبي على فرسخٍ من قزوين، فاقتتلا قتالًا شديدًا، ولَمَّا التَقَوا صَفَّ أصحاب الكوكبي صفوفًا وأقاموا ترسَتَهم في وجوهِهم يتَّقون بذلك سهامَ أصحاب موسى، فلما رأى موسى أن سهامَ أصحابِه لا تصِلُ إليهم مع ما قد فعلوا، أمَرَ بما معه من النّ"},{"id":818,"era":"c3","t":"تسلط الأتراك على الدولة العباسية .","s":"أوَّلُ من بدأ بجلب الأتراك كان المعتصِم؛ وذلك لأنهم لم يَفسُدوا بعدُ بالترَفُّه، ويمكن تدريبهم عسكريًّا فيصبحوا من الجندِ، وكَثُروا حتى أصبح وجودُهم مُزعِجًا فبُنِيَت من أجلهم سامرَّا، ثم أصبح منهم القادة البارزون كالأفشين وبغا الكبير ووصيف، وأصبح نفوذُهم وتنفُّذُهم كبيرًا بسبب كثرتِهم وبسبب قوَّة إدارتهم، وبسبب تركِ كثيرٍ من الأمور إليهم أصلًا، فتآمروا مع المنتصر لقَتلِ أبيه المتوكِّل، ثم كان لهم"},{"id":819,"era":"c3","t":"خلع الخليفة العباسي المستعين بالله ومبايعة المعتز بن المتوكل .","s":"كانت البدايةُ في أنَّ بعض قواد الأتراك من المشغِّبين قد جاؤوا إلى المستعين وسألوه العفوَ والصَّفحَ عنهم ففعل، فطلبوا منه أن يرجِعَ معهم إلى سامرَّا التي خرج منها إلى بغداد؛ بسبب تنكُّرِ بعض هؤلاء القادة الأتراك له، فلم يقبَلْ وبقي في بغداد، وكان محمد بن عبدالله بن طاهر قد أهان أحدَ القادة الأتراك، فزاد غضَبُهم، فلما رجعوا إلى سامرَّا أظهروا الشغب وفتحوا السُّجونَ وأخرجوا من فيها، ومنهم المعتزُّ بن"},{"id":820,"era":"c3","t":"وفاة إسماعيل بن يوسف الطالبي (السفاك) .","s":"هو إسماعيل بن يوسف بن إبراهيم بن موسى بن عبد الله بن حسن بن حسن بن علي بن أبي طالب الحسني من بيتٍ خرج منهم جماعةٌ على الخلفاء بالحجاز والعراق والمغرب، عرف بالسَّفَّاك، خرج إسماعيل سنة إحدى وخمسين ومائتين في زمن المستعين بالله بالحجاز وهو شاب له عشرون سنة، وتبعه خلقٌ كثير من المتشيِّعة والديلم, فعاث في الحرمين وقتل من الحُجَّاج بعرفة وسلَبَ ونهب، ولقِيَ النَّاسُ منه عنَتًا إلى أن هلك هو وأصحابُه با"},{"id":821,"era":"c3","t":"فتنة بين الأتراك والمغاربة .","s":"كان سببُها أنَّ الأتراكَ وثَبوا بالوزيرِ عيسى بن فرخان شاه، فضربوه، وأخذوا دابَّته، واجتمَعَت المغاربةُ مع محمد بن راشد، ونصر بن سعد، وغلبوا الأتراكَ على الجوسق، وأخرجوهم منه، وقالوا لهم: كلَّ يومٍ تقتلونَ خليفةً، وتخلعونَ آخر, وتقتلونَ وزيرًا وتُثبِتونَ آخرَ، وصار الجوسق وبيتُ المال في أيدي المغاربة، وأخذوا الدوابَّ التي كان تَرَكها الأتراكُ، فاجتمع الأتراكُ وأرسلوا إلى من بالكرخ والدُّور منهم، ف"},{"id":822,"era":"c3","t":"خلعُ المعتز أخاه المؤيد عن ولاية العهد .","s":"أرسل العلاءُ بن أحمد- عاملُ أرمينية- إلى المؤيَّد بخمسة آلاف دينار ليُصلِحَ بها أمرَه، فبعث عيسى بن فرخانشاه إليها فأخذها, فأغرى المؤيَّد الأتراك بعيسى وخالَفَهم المغاربة، فبعث المعتزُّ إلى المؤيَّد وأبي أحمد، فأخذَهما وحبَسَهما وقيَّدَ المؤيَّد، وأدرَّ العطاء للأتراك والمغاربة. وقيل: إنَّه ضرَبَه أربعينَ مقرعةً، وخلعه بسامرَّاءَ وأخذ خَطَّه بخلعِ نَفسِه."},{"id":823,"era":"c3","t":"وفاة إبراهيم بن المتوكل المعروف بالمؤيد .","s":"هو المؤيَّدُ إبراهيمُ بن جعفر المتوكِّل على الله، أحدُ وُلاةِ العهد الثلاثة بعد الخليفةِ المتوكِّل: وهم المنتصر بالله، والمعتَزُّ بالله، والمؤيَّد، تمَّ خَلْعُه من ولاية العهد مرتين؛ الأولى: في عهد أخيه المنتصِر؛ حيث قام بخلعِه مع المعتز بضَغطٍ من قادة الأتراك, والثانية: على يد أخيه المعتزِّ بالله؛ حيث تمَّ إجبارُه على خَلعِ نَفسِه من ولاية العهدِ، ومن ثمَّ تمَّ قتلُه في ظروف غامضة, وكانت امرأةٌ م"},{"id":824,"era":"c3","t":"وفاة الخليفة المستعين بالله .","s":"هو المستعين بالله أبو العباس أحمد بن المعتصم بالله محمد بن الرشيد العباسي، ولد سنةَ إحدى وعشرين ومئتين, وأمُّه أمُّ ولد، اسمها مخارق, وكان رَبعةً، خفيف العارضينِ، وكان مليحًا أبيض، بوجهِه أثَرُ جُدريٍّ، وكان يلثغُ في السين نحو الثاء، بايعَ له الأتراكُ بالخلافة بعد المنتصر، فتسلَّطوا عليه وقهروه، فلم يكن له من الأمرِ شَيءٌ، فانتقل من سامرَّا إلى بغداد مُغضَبًا, جرت عدَّةُ وقائع بينه وبين أخيه المعت"},{"id":825,"era":"c3","t":"الفتنة بين جند بغداد ومحمد بن عبدالله بن طاهر .","s":"اجتمع الشَّاكرية وأصحابُ الفروض إلى دار محمَّد بن عبدالله بن طاهر أميرِ العراق يطلبونَ أرزاقَهم، فكتب إلى أمير المؤمنين بذلك، فكتب الخليفة في الجواب: إن كنتَ تريد الجندَ لنفسِك فأعطِهم أرزاقَهم، وإن كنتَ تريدُهم لنا فلا حاجة لنا فيهم؛ فشَغَّبوا عليه، وأخرجَ لهم ألفي دينارٍ، ففُرِّقَت فيهم فسكتوا، ثم اجتمعوا مرَّةً أخرى بالسِّلاح والأعلام والطبول، وجمع محمَّد أصحابَه في داره, واجتمع إلى أولئك (المش"},{"id":826,"era":"c3","t":"مقتل الخليفة المخلوع المستعين بالله .","s":"قرر المعتزُّ قتلَ المستعين، فكتب إلى محمد بن عبد الله بن طاهر أن يسلِّمَه إلى سيما الخادمِ، وكتب محمَّد في ذلك إلى الموكَّلين به بواسط فقَتلوه، ثم جاؤوا برأسه والمعتَزُّ يلعب الشطرنجَ، فقيل: هذا رأسُ المخلوعِ، فقال: ضعوه هنالك، ثم فَرَغ من لَعِبِه ودعا به فنظر إليه، ثم أمر بدَفنِه."},{"id":827,"era":"c3","t":"ابتداء دولة يعقوب الصفار وملكه هراة وبوشنج  .","s":"كان يعقوبُ بن الليث وأخوه عمرو يعملانِ الصُّفر بسجستان، ويُظهِران الزهد والتقشُّف، وكان في أيامهما رجلٌ من أهل سجستان يُظهِرُ التطوُّع بقتال الخوارج، يقال له صالح المطوعي، فصَحِبه يعقوب، وقاتلَ معه، فحَظِيَ عنده، فجعله صالحٌ مقامَ الخليفة عنه، ثم هلك صالحٌ، وقام مقامَه إنسانٌ آخر اسمه درهم، فصار يعقوبُ مع درهم كما كان مع صالحٍ قبله. ثم إنَّ صاحبَ خُراسان احتال لدرهم لَمَّا عَظُم شأنُه وكثُر أتباعُ"},{"id":828,"era":"c3","t":"قتال عبدالعزيز بن أبي دلف في همذان .","s":"عقد المعتزُّ لموسى بن بغا الكبير على جيشٍ قريب من أربعةِ آلاف ليذهَبوا إلى قتال عبد العزيز بن أبي دلف بناحيةِ همذان؛ لأنَّه خرج عن الطاعة، وهو في نحوٍ من عشرين ألفًا بناحية همذان، فهَزَموا عبد العزيز في أواخر هذه السَّنة هزيمةً عظيمةً، ثمَّ كانت بينهما وقعةٌ أخرى في رمضانَ عند الكرج، فهُزِم عبد العزيز أيضًا وقُتِلَ من أصحابه بشرٌ كثير، وأَسَروا ذراريَّ كثيرةً حتى أسروا أمَّ عبد العزيز، وبَعَثوا إل"},{"id":829,"era":"c3","t":"خروج أهل ماردة في الأندلس وقمعهم .","s":"خرج الأميرُ محمد بن عبدالرحمن بن الحكم إلى ماردة بعد أن أظهَروا التمرُّد, وكانوا قد اجتمع أمرُهم في الخروج على أبيه من قبلُ، فأظهرَ أنَّ استعدادَه لطُلَيطِلة، فلما فصَلَ من قرطبةَ، وتقدَّمَ بالمحلاتِ إلى طريق طُليطِلة، نكبَ إلى ماردة، وهم في أمنٍ وغفلة، فتحَصَّنوا في المدينة أيامًا. ثم ناهض القنطرةَ، فوقع القتال، واشتدَّت الحرب حتى غُلِبوا عليها، فأمر الأميرُ بتخريب رِجلٍ من القنطرة، فكان ذلك سببً"},{"id":830,"era":"c3","t":"قيام الدولة الطولونية بمصر .","s":"كانت ديارُ مصر قد أُقطِعَت لبابكيال، وهو مِن أكابر قوَّاد الأتراك، وكان مُقيمًا بالحَضرة، والتمسَ بابكيال من يستخلِفُه بمصر، فأشيرَ عليه بأحمد بن طولون؛ لِمَا ظهَرَ عنه من حُسنِ السيرة، وكان طولون والدُ أحمد بن طولون أيضًا من الأتراك، وقد نشأ هو بعد والدِه على طريقةٍ مُستقيمة، وسيرةٍ حَسنةٍ، فولَّاه بابكيال وسيَّرَه إليها، وكان بها ابنُ المدبر على الخَراج، وقد تحكَّمَ في البلد، فلمَّا قَدِمَها أحم"},{"id":831,"era":"c3","t":"أمير صقلية خفاجة بن سفيان يرسل سراياه إلى سرقوسة ومدينة غيطة .","s":"سيَّرَ خفاجة ابنَه محمدًا على الحراقات، وسيَّرَ سريَّةً إلى سرقوسة، فغَنِموا وأتاهم الخبَرُ أنَّ بِطريقًا قد سار من القسطنطينية في جمعٍ كثيرٍ، وغَنِم المسلمونَ منهم غنائمَ كثيرة، فرحل خفاجة إلى سرقوسة فأفسَدَ زَرعَها وغَنِم منها وعاد إلى بلرم، وسيَّرَ ابنه محمدًا في البحر، مُستهَلَّ رجَب، إلى مدينة غيطة، فحَصَرها وبثَّ العساكِرَ في نواحيها، فغَنِم وشحَن مراكِبَه بالغنائم، وانصرف إلى بلرم في شوَّال"},{"id":832,"era":"c3","t":"وفاة الجاحظ المتكلم المعتزلي .","s":"هو أبو عثمان عمرُو بنُ بحر بن محبوب الكناني الليثي البصري المتكلِّم المعتزلي، اشتهرَ بالجاحِظِ لجُحوظٍ كان في عينيه، أديبٌ كبيرٌ وُلِدَ في البصرة ونشأ وتعلَّم فيها. قال عنه الذهبي: \"كان واسِعَ النقلِ كثيرَ الاطِّلاع، مِن أذكياءِ بني آدم وأفرادِهم وشياطينِهم\", ليس بثقةٍ ولا مأمونٍ، أخذَ عن الأصمعي وغيرِه, وأخذ عِلمَ الكلام عن أبي إسحاق إبراهيمَ بن سيَّار البلخي المعروف بالنَّظَّام المعتزلي المتكَلّ"},{"id":833,"era":"c3","t":"ظهور ثورة الزنج في البصرة .","s":"ظهر رجلٌ بظاهر البصرة زعمَ أنَّه عليُّ بن محمد بن أحمد بن عيسى بن زيد بن علي بن الحسين بن علي بن أبي طالب، ولم يكنْ صادِقًا، وإنما كان أجيرًا من عبد القيس، واسمُه علي بن محمد بن عبد الرحيم، وأمُّه قرَّة بنت علي بن رحيب بن محمد بن حكيم من بني أسد بن خزيمة، وأصلُه من قرية من قرى الريِّ، والتَفَّ عليه خلقٌ من الزنج الذين يكسحونَ السِّباخ، فعبَرَ بهم دجلةَ فنزل الديناري، وكان يزعُمُ لبعضِ من معه أنَّه"},{"id":834,"era":"c3","t":"فتح جزيرة مالطة .","s":"فتَحَها المسلمونَ في ولاية أبي عبد الله محمد بن أحمد بن محمد بن الأغلب أبو الغرانيق، غزاها خَلفٌ الخادم مولى زيادة الله بن إبراهيم، وخَلفٌ هو المعروفُ ببناء المساجدِ والقناطر، فحاصرها ومات وهو محاصِرٌ لها، فكَتَبوا إلى أبي عبد الله بوفاته، فكتب أبو عبد الله إلى عامِلِه بجزيرة صقليَّة، وهو محمَّد بن خفاجة، أن يبعَثَ إليهم واليًا، فبعث إليهم سوادةَ بن محمد، ففتحوا حصنَ مالطة، وظَفِروا بمَلِكها عمروس"},{"id":835,"era":"c3","t":"استيلاء يعقوب بن الليث الصفار على بلاد فارس .","s":"لَمَّا بلغ عليُّ بن الحسين بن شبل بفارس ما فعَلَه يعقوب بطوقٍ في كرمان أيقَنَ بمجيئِه إليه، وكان عليٌّ بشيراز، فجمع جيشَه وسار إلى مضيقٍ خارج شيراز، من أحدِ جانبيه جبَلٌ لا يُسلَك، ومن الجانب الآخر نهرٌ لا يُخاضُ، فأقام على رأسِ المضيق، وهو ضَيِّقٌ، ممَرُّه لا يسلُكُه إلا واحِدٌ بعد واحد، وهو على طرفِ البَرِّ، وقال: إنَّ يعقوبَ لا يقدِرُ على الجوازِ إلينا، فخاض يعقوبُ وأصحابه النهر وخرجوا من وراء "},{"id":836,"era":"c3","t":"استيلاء يعقوب بن الليث الصفار على ولاية كرمان .","s":"كتب المعتزُّ لعلي بن الحسين بن شبل بولاية كرمان، وكتبَ إلى يعقوبَ بن الليث بولايتها أيضًا يلتمِسُ إغراءَ كُلِّ واحدٍ منهما بصاحبه؛ ليُسقِطَ مؤونةَ الهالكِ عنه، وينفرِدَ بالآخر، وكان كلُّ واحد منهما يُظهِرُ طاعةً لا حقيقةَ لها، والمعتز يعلم ذلك منهما. أرسل عليُّ بن الحسين طوقَ بن المغلس إلى كرمان، وسار يعقوبُ إليها فسَبَقه طوقٌ واستولى عليها وأقبل يعقوبُ حتى بقيَ بينه وبين كرمان مرحلةٌ، فأقام بها ش"},{"id":837,"era":"c3","t":"وفاة محمد بن كرام السجستاني شَيخُ الطائفة الكَرَّاميَّة .","s":"هو المُبتدِع الضّالُّ شَيخُ الكَرَّاميَّة: محمد بن كرَّام بن عراف النيسابوري، الذي إليه تُنسَب الفِرقةُ الكرَّامية, وُلِدَ بقرية من قرى زرنج بسجستان، ثمَّ دخل خراسان, وأكثَرَ الاختلاف إلى أحمد بن حرب الزاهد، كان زاهدًا عابدًا بعيدَ الصِّيتِ, كثيرَ الأصحابِ، ولكِنَّه يروي الواهياتِ, خُذِلَ حتى التقَطَ من المذاهِبِ أرداها، ومن الأحاديثِ أوهاها, ثم جالسَ الجويباري، وابن تميم, ولعلهما قد وضعا مائة ألف"},{"id":838,"era":"c3","t":"خلع الأتراك للخليفة العباسي المعتز ثم قتله  .","s":"كان سببَ ذلك أنَّ الأتراك ساروا إلى المعتزِّ يطلبون أرزاقهم، وقالوا: أعطِنا أرزاقَنا حتى نقبَلَ صالح بن وصيف، فلم يكُن عنده ما يعطيهم، فنزلوا معه إلى خمسين ألفَ دينار، فأرسلَ المعتَزُّ إلى أمِّه يسألُها أن تعطيَه مالًا ليعطيَهم، فأرسلت إليه: ما عندي شيءٌ, فلما رأى الأتراكُ أنَّهم لا يحصل لهم من المعتزِّ شَيءٌ، ولا مِن أمِّه، وليس في بيتِ المال شيء، اتَّفَقَت كلمتهم وكلمةُ المغاربة والفراغنة، على خ"},{"id":839,"era":"c3","t":"المهتدي بالله يتولى الخلافة العباسية .","s":"هو أبو محمد عبد الله محمد بن الواثق بن المعتصم بن هارون، كانت بيعتُه بعد خلع المعتزِّ نفسَه بين يديه وإشهادِه عليه، فأوَّلُ من بايعه المعتَزُّ ثمَّ بايعه الخاصَّةُ، ثم كانت بيعةُ العامَّة على المنبر."},{"id":840,"era":"c3","t":"مقتل خفاجة بن سفيان أمير صقلية وتولي ابنه من بعده .","s":"هو خفاجة بن سفيان أمير صقلية، وكان من الشُّجَعان الغُزاة المدَبِّرين، تولَّى إمرة صقلية عام 248هـ وكانت عاصمته بلرم،  اغتاله رجلٌ من عَسكَرِه وهو عائِدٌ مِن غَزوِ سرقوسه قاصدًا بلرم، فطعنه طعنةً فقتله، ثم هرب القاتِلُ إلى سرقوسة، وحُمِل خفاجة إلى بلرم، فدُفِنَ بها وولَّى الناسُ عليهم بعدَه ابنه محمدًا، وكتبوا بذلك إلى الأميرِ محمد بن أحمد، أمير إفريقية، فأقَرَّه على الولاية، وسيَّرَ له العهدَ والخ"},{"id":841,"era":"c3","t":"شغب العامة ببغداد على ولاية المهتدي .","s":"بعث المهتدي بكتابٍ إلى سليمان بن عبد الله بن طاهر نائبِ الخليفة في بغداد يأمُرُه بأخذ البيعة له، وكان أبو أحمد بن المتوكل ببغداد، وكان المعتزُّ قد سَيَّرَه إليها، فأرسل سليمانَ إليه، فأخذه إلى داره،  فاجتمع العامَّةُ إلى باب دار سليمان، فقاتَلَهم أصحابه، وقيل لهم: ما يَرِدُ علينا من سامرَّاء خبر، فانصَرَفوا ورَجَعوا الغدَ، وهو يوم الجمعة على ذلك، وخطب للمعتز ببغداد، فانصرفوا وبكَّروا يوم السبت، فه"},{"id":842,"era":"c3","t":"وفاة الخليفة العباسي المعتز  .","s":"هو أبو عبد الله، الزبيرُ بن المتوكل جعفر بن المعتصم محمد بن الرشيد هارون بن المهدي العباسي. ولد سنة 233ه, وأمُّه أم ولد روميَّة تسمَّى قبيحة, وما رُئِيَ في زمانِه أصبحَ وجهًا منه ولا من أمِّه قبيحة، تولَّى الخلافة بعد أن عزَلَ الأتراكُ المستعين بالله وأخذوا البيعة له، ثمَّ دبَّرَ من يقتل المستعينَ بعد عزله من الخلافة، وكان المعتزُ أمرَدَ حين ولِيَ الخلافة, وهو ابنُ عشرين سنة أو دونَها, وجلس جلوسًا"},{"id":843,"era":"c3","t":"ثورة الشاكرية والعامة في بغداد على محمد بن أوس  .","s":"وقعت فتنةٌ ببغداد بين محمَّد بن أوس البلخي ومن تَبِعَه وبين الشاكريَّة والجند وغيرهم من العامَّة والرَّعاع، فوثبت الشاكريَّة ببغداد بمحمد بن أوس، والسببُ في ذلك أنَّ محمَّد بن أوس قَدِمَ بغداد مع سليمانَ بنِ عبد الله بن طاهر، وهو على الجيش القادم من خراسان، ومع سليمان الصعاليكُ الذين تألَّفَهم سليمانُ بالرَّيِّ، ولم تكن أسماؤهم في ديوانِ السُّلطان بالعراق، والجُند والشَّاكرية يصيحون في طلبِ مال ال"},{"id":844,"era":"c3","t":"استفحال أمر صاحب الزنج في مدن العراق  .","s":"كان أول ظهورٍ لثورة صاحب الزنج  الدعيِّ علي بن محمد عام 255هـ وبدأ يستفحل أمرُه وتوالت الحروب بينه وبين جيوش الخلافة مرَّةً تلو الأخرى، وكل ذلك لم يظفروا به، فدخل البصرةَ والسبخة والأبلة وعبادان والأهواز، حتى خافه كثيرٌ من أهل البصرة وفرُّوا خارج البصرة، فكان هذا بدايةً لدولتهم الجديدة المؤسَّسة أصلًا على الزنج من العبيد الفارِّين والمتمرِّدين على أسيادهم، ومَن أُسِرَ من العبيد في حروبِه."},{"id":845,"era":"c3","t":"ظهور أحمد بن إبراهيم بن طباطبا العلوي في مصر .","s":"ظهر بمصرَ إنسانٌ عَلويٌّ ذُكِرَ أنَّه أحمد بن محمد بن عبد الله بن إبراهيم بن طباطبا، وكان ظهورُه بين الرقة والإسكندرية، وسار إلى الصعيد، وكثُر أتباعه، وادَّعى الخلافة، فسَيَّرَ إليه أحمد بن طولون جيشًا فقاتلوه، وانهزم أصحابُه عنه، وثبت هو فقُتِل، وحُمِلَ رأسُه إلى مصر."},{"id":846,"era":"c3","t":"بناء أحمد بن طولون مدينة القطائع عاصمة الدولة الطولونية .","s":"لَمَّا وليَ أحمد بن طولون مصرَ سكن مدينةَ العسكرِ على عادة أمراء مصرَ من قَبلِه، ثم أحَبَّ أن يبني له قصرًا، فبنى القطائع. والقطائِعُ قد زالت آثارها الآن مِن مصر، ولم يبق لها رَسمٌ يُعرف، وكان موضِعها من قبَّة الهواء، التي صار مكانها الآن قلعةُ الجبل، إلى جامع ابن طولون، وهو طول القطائع، وأمَّا عرضها فإنه كان من أول الرميلة من تحت القلعة إلى الموضع الذي يعرف الآن بالأرضِ الصفراء, وكانت مساحةُ القط"},{"id":847,"era":"c3","t":"ظهور ابن الصوفي العلوي بمصر .","s":"ظهر بصعيد مصر إنسانٌ ذكَرَ أنه إبراهيم بن محمد بن يحيى بن عبد الله بن محمد بن أبي طالب العَلَوي، ويُعرَف بابن الصوفي، وملك مدينة أسنا ونهبها وعَمَّ شَرُّه البلاد. فسير إليه أحمد بن طولون جيشًا فهزَمه العَلويُّ، وأسرَ المقَدَّم على الجيش، فقطع يديه ورجليه وصَلَبه؛ فسيَّرَ إليه ابنُ طولون جيشًا آخر فالتقوا بنواحي إخميم، فاقتتلوا قتالًا شديدًا فانهزم العَلَوي، وقُتِل كثيرٌ من رجاله، وسار هو حتى دخل ا"},{"id":848,"era":"c3","t":"شغب الترك على المهتدي بسبب صالح بن وصيف .","s":"كان صالح بن وصيف قائدًا من الأتراك صاحِبَ تسلُّطٍ شديد, وهو أحدُ المتآمرين على قتل المتوكِّل، ثم اختفى فطلَبه الأتراك بسببِ أموالٍ بينهم فأتوا المهتدي ليكشِفَ لهم أمرَ صالح. فقدم موسى بن بغا الكبير إلى سامرَّا بطلبٍ من الخليفة, فدخلها في جيشٍ هائل، فأتوا دار الخلافةِ التي فيها المهتدي جالسًا لكشف المظالم فاستأذنوا عليه فأبطأ الإذنَ ساعةً، وتأخَّرَ عنهم فظنُّوا في أنفسهم أنَّ الخليفةَ إنما طلبهم خد"},{"id":849,"era":"c3","t":"تولي المعتمد على الله الخلافة العباسية .","s":"بويع المعتمِدُ على الله- وهو أحمد بن المتوكِّل على الله- بالخلافةِ في دار الأمير يارجوخ، وذلك قبل خلعِ المهتدي بأيامٍ، ثم كانت بيعةُ العامَّة. وفي صفر من السنة التالية عَقدَ المعتمِدُ لأخيه أبي أحمد على الكوفةِ وطريق مكة والحرمين واليمن، وأضاف إليه في رمضان نيابةَ بغداد والسواد وواسط وكور دجلة والبصرة والأهواز وفارس، وأذِنَ له أن يتصَرَّف في ذلك كلِّه."},{"id":850,"era":"c3","t":"وفاة الخليفة العباسي المهتدي بالله .","s":"هو الخليفة الصالحُ أميرُ المؤمنين أبو إسحاق، وقيل أبو عبدالله محمَّد بن هارون الثاني الواثق بالله بن محمد المعتصم بالله بن هارون الرشيد, وأمُّه أم ولدٍ اسمُها قرب, ولدَ في خلافة جدِّه الواثق سنة 219ه, وبويع بالخلافةِ في رجب سنة 255ه، وما قَبِلَ بيعةَ أحد حتى بايعه المعتز بالله، بعد أن أقرَّ بتنازله عن الخلافة له، وأشهَدَ على نفسِه بعجزه عن تولِّي مهامِّها. كان المهتدي أسمرَ رقيقًا، مليح الوجه، حسَ"},{"id":851,"era":"c3","t":"وفاة الإمام البخاري صاحب الجامع الصحيح .","s":"هو محمَّد بن إسماعيل بن إبراهيم بن المغيرة، إمامُ أهلِ الحديثِ بلا مُنازِعٍ، صاحِبُ الصَّحيحِ، الذي أجمعت الأمَّةُ على تلِّقيه بالقَبول، وُلِدَ في بخارى، رحل إلى مكَّةَ وبقي فيها فترةً يتلقى العلمَ، طاف البلادَ للحديث يجمَعُ ويحفَظُ، حتى صار إمامَ الحديث وحافِظَه في عصرِه، إمامًا في الجرحِ والتعديلِ، إمامًا في العِلَل. قال ابنُ خُزيمة: \"ما رأيتُ تحت أديمِ السَّماءِ أعلمَ بحديثِ رَسولِ اللهِ صلَّى "},{"id":852,"era":"c3","t":"تغلبُ الحسن بن زيد الطالبي على بلاد الري .","s":"تغلبَ الحسَنُ بن زيد الطالبيِّ على بلاد الريِّ، فتوجه إليه موسى بن بغا في شوال، وخرج الخليفة لتوديعه, فكانت وقعة بين موسى بن بغا وأصحاب الحسن بن زيد، فهزَمَ موسى أصحابَ الحسَنِ وتغَلَّب عليهم."},{"id":853,"era":"c3","t":"خوارج الزنج يحرقون جامع البصرة وقتل الكثير من أهلها .","s":"دخل جيش الخبيثِ الزنجيِّ إلى البصرة قهرًا، فقتل من أهلِها خَلقًا، وهرب نائبُها بغراج ومن معه، وأحرَقَت الزنج جامعَ البصرة ودورًا كثيرة، وانتهبوها، ثم نادى فيهم إبراهيم بن المهلبي أحدُ أصحاب الزنجي الخارجي: من أراد الأمانَ فلْيَحضُر، فاجتمع عنده خلقٌ كثير من أهل البصرة، فرأى أنه قد أصاب فرصةً، فغدر بهم وأمَرَ بقَتلِهم، فلم يُفلِتْ منهم إلَّا الشاذ، كانت الزنجُ تحيط بجماعةٍ من أهل البصرة، ثم يقول بع"},{"id":854,"era":"c3","t":"الاقتتال بين الخوارج بسبب مسألة قبول توبةِ العصاة .","s":"اختلف مساور الخارجي مع رجلٍ من الخوارج- يقال له عُبيدة، من بني زهير العمروي- على توبةِ المخطئ، فقال مساور: نقبلُ توبته؛ وقال عبيدة: لا نقبل، فجمع عبيدةُ جمعًا كثيرًا وسار إلى مساور، وتقدَّمَ إليه مساور من الحديثة، فالتَقَوا بنواحي جهينة، بالقرب من المَوصِل، واقتتلوا أشدَّ قتال، فترجَّل مساور ومن عنده، ومعه جماعةٌ من أصحابه، وعرقبوا دوابَّهم، فقُتِل عبيدة وانهزم جمعه، فقُتِل أكثَرُهم، واستولى مساور"},{"id":855,"era":"c3","t":"مقتل أمير صقلية محمد بن خفاجة  .","s":"لَمَّا قُتِلَ خفاجة بن سفيان استعمل الناسُ ابنه محمدًا، وأقره محمد بن أحمد بن الأغلب أبو الغرانيق- صاحِبُ القيروان- على ولايته, كان ذلك في عام خمس وخمسين ومائتين، وفي رجب من عام سبع وخمسين ومائتين قُتِلَ الأميرُ محمد، قتله خَدَمُه الخصيان نهارًا وكتموا قَتْلَه، فلم يعرَفْ إلَّا مِن الغد، وكان الخدَمُ الذين قتلوه قد هربوا فطُلِبوا فأُخِذوا وقُتِلَ بعضُهم، ولَمَّا قُتِلَ استعمل محمَّدُ بن أحمد بن ال"},{"id":856,"era":"c3","t":"معارك سعيد الحاجب مع خوارج الزنج في البصرة .","s":"أوقع سعيد الحاجب أمير البصرة بجماعةٍ مِن الزنج، فهزمهم واستنقذَ مَن معهم من النساء والذريَّة، واسترجع منهم أموالًا جزيلةً، وأهان الزنجَ غايةَ الإهانة، فكانت المرأةُ من نساء تلك الناحية تأخذ الزنجيَّ فتأتي به عسكرَ سعيدٍ فلا يمتنِعُ عليها، ثم عبَرَ سعيد إلى غرب دجلة فأوقع بصاحِبِ الزنج عدةَ وَقعاتٍ، ثم عاد إلى معسكرِه بهطمة فأقام من ثاني رجب إلى آخر شعبان. ثم أوقع صاحِبُ الزنج بسعيد، وذلك أنَّه سيّ"},{"id":857,"era":"c3","t":"الخليفة المعتمد يأمر بحربِ خوارج الزنج في البصرة .","s":"أمر المعتمد أحمد المولد بالمسير إلى البصرة لحربِ الزنج، فسار حتى نزل الأبلة، ثم نزل البصرة، واجتمع إليه من أهلِها خلقٌ كثير، فسيَّرَ علي بن أبان المهلبي إلى حرب المولد يحيى بن محمد البحراني، فسار إليه فقاتله عشرةَ أيام، ثم وطَّن المولدُ نفسَه على المقام، فكتب العلَويُّ إلى يحيى يأمره بتبييتِ المولد، ووجه إليه الشذا مع أبي الليث الأصفهاني، فبَيَّته، ونهض المولد فقاتلَه تلك الليلة، ومن الغدِ إلى الع"},{"id":858,"era":"c3","t":"الخليفة المعتمد يأمر أخيه الموفَّق بقتال خوارج الزنج .","s":"عقد الخليفةُ المعتمِدُ لأخيه الموفَّق أبي أحمد ومفلح لقتال الزنج، فلما سارا إلى البصرة واجههم علي بن أبان المهلبي فجرى القتالُ بينهما، وكان نتيجته مقتل مفلح وكثيرٍ من أصحابه، ثمَّ إنَّ يحيى بن محمد البحراني- وهو من طرف الزنج- سار نحو نهر العباس فلَقِيَه عسكرُ أصعجور، عامل الأهواز بعد منصور، وقاتلهم، وكان أكثَرَ منهم عددًا، فنال ذلك العسكر من الزنج بالنشاب، وجرحوهم، فعبَرَ يحيى النهرَ إليهم، فانحاز"},{"id":859,"era":"c3","t":"غزو الأمير محمد بن عبدالرحمن ثغور الأندلس .","s":"خرج الأمير محمد بن عبدالرحمن بنفسه إلى الثغر، وحلَّ في وجهته بطليطِلة، وأخذ رهائِنَهم، وعقدَ أمانَهم، وقاطَعَهم على قطيعٍ من العُشور يؤدُّونه في كل عام، وهو الأمانُ الثاني. واختلفت أهواؤهم في عُمَّالهم، فطلب قوم منهم توليةَ مطَرِّف بن عبد الرحمن، وطلب آخرونَ تولية طربيشة بن ماسوية، فولَّى كلَّ واحد منهما جانبًا، واقتسما المدينةَ وأقاليمها على حدود مفهومة معلومة؛ ثم تنازعا، وأراد كلُّ واحد منهما ال"},{"id":860,"era":"c3","t":"عودة ظهور ابن الصوفي العلوي بمصر .","s":"كان إبراهيم بن محمَّد بن يحيى بن عبد الله بن محمد بن أبي طالب المعروف \"بابن الصوفي العَلَوي\" قد ظهر بمصر سنة ست وخمسين، فدعا لنفسه ثم هرب إلى الواحات، ثم عاد هذا العام، فدعا الناسَ إلى نفسه، فتَبِعَه خلق كثير، وسار بهم إلى الأشمونين، فوُجِّه إليه جيش عليهم قائد يعرف بابن أبي الغيث، فوجده قد أصعد إلى لقاء أبي عبد الرحمن العمري، فلما وصل العَلَوي إلى العُمري التقيا، فكان بينهما قتالٌ شديد، أجْلَت ال"},{"id":861,"era":"c3","t":"دخول خوارج الزنج إلى بلاد الأهواز .","s":"أنفذ قائدُ الزنجِ عليَّ بن أبان المهلبي، وضمَّ إليه الجيشَ الذي كان مع يحيى بن محمد البحراني، وسليمان بن موسى الشعراني، وسيَّرَه إلى الأهواز, وكان المتولي لها بعد منصور بن جعفر رجلًا يقالُ له أصعجور، فبلغه خبَرُ الزنج، فخرج إليهم، والتقى العسكرانِ بدشت ميسان، فانهزم أصعجور، وقُتِل معه كثيرٌ، وجُرِح خلقٌ كثيرٌ من أصحابه، وغرق أصعجور، وأُسِرَ خَلقٌ كثيرٌ، فيهم الحسن بن هرثمة، والحسن بن جعفر، وحُمِلَ"},{"id":862,"era":"c3","t":"انتهاء الدولة الطاهرية بخراسان على يد الصفارية .","s":"دخل يعقوبُ بن الليث نيسابور، وكان سببَ مَسيرِه إليها أنَّ عبد الله السجزي كان ينازع يعقوب بسجستان، فلما قويَ عليه يعقوبُ هرب منه إلى محمد بن طاهر، فأرسل يعقوبُ يطلب من ابن طاهرٍ أن يسَلِّمَه إليه فلم يفعَلْ، وقيل: كان سببَ مِلك يعقوب نيسابورَ ما بلَغَه من ضَعفِ محمد بن طاهر أميرِ خراسان، فلما تحقَّقَ يعقوبُ ذلك، وأنَّه لا يقدِرُ على الدَّفعِ، وكان بعضُ خاصة محمد بن طاهر، وبعضُ أهلِه لَمَّا رأوا إد"},{"id":863,"era":"c3","t":"الخليفة المعتمد يأمر موسى بن بغا لحرب خوارج الزنج .","s":"أمر المعتمِدُ موسى بن بغا الكبيرَ بالمسير إلى حرب صاحبِ الزنج، فسيَّرَ إلى الأهواز عبد الرحمن بن مفلح، وإلى البصرة إسحاقَ بن كنداجيق، وإلى باذاورد إبراهيمَ بن سيما، وأمرهم بمحاربة صاحب الزنج، فلما وَليَ عبد الرحمن الأهوازَ سار إلى محاربة عليِّ بن أبان المهلبي، فتواقعا فانهزم عبدُالرحمن؛ ثم استعَدَّ وعاد إلى عليٍّ، فأوقع به وقعةً عظيمةً قَتَل فيها من الزنج قتلًا ذريعًا وأسَرَ خلقًا كثيرًا، وانهزم ع"},{"id":864,"era":"c3","t":"الحرب بين يعقوب الصفار والحسن بن زيد العلوي .","s":"كان عبد الله السجزي ينازِعُ يعقوبَ بن الليث الصفَّار الرئاسةَ بسجستان، فقهره يعقوبُ، فهرب منه عبد الله إلى نيسابور، فلما سار يعقوبُ إلى نيسابور، هرب عبد الله إلى الحسن بن زيد العَلَوي بطبرستان، فسار يعقوبُ في أثَرِه، فلقيه الحسنُ بن زيد بقرية سارية، وكان يعقوبُ قد أرسل إلى الحسن يسألُه أن يبعثَ إليه عبد الله ويرجِعَ عنه، فإنَّه إنما جاء لذلك لا لحَربِه، فلم يُسلِّمْه الحسن، فحاربه يعقوبُ، فانهزم ا"},{"id":865,"era":"c3","t":"فتنة الموصل وفساد عاملها ابن أساتكين .","s":"كان المعتمِد قد ولَّى على الموصِل أساتكين من قوَّاد الأتراك، فبعث عليها ابنَه اذكوتكين وسار إليها سنة تسع وخمسين، فأساء السيرةَ وأظهر المُنكَر وعسَفَ بالنَّاسِ في طلب الخَراجِ، وتعرَّضَ أحد الأيام رجلٌ من حاشيته إلى امرأةٍ في الطريقِ، وتخلَّصها من يده بعضُ الصالحين، فأحضره أذكوتكين وضربه ضربًا شديدًا، فاجتمع وجوهُ البلد وتآمروا في رَفعِ أمرهم إلى المعتمِد، فركب إليهم ليوقِعَ بهم فقاتلوه وأخرجوه وا"},{"id":866,"era":"c3","t":"الحرب بين أهل طليطلة وهوارة في الأندلس .","s":"ظهر موسى بن ذي النون الهواري بشنت برية، وأغار على أهل طليطِلة، ودخل حِصنَ وليد من شنت برية، فخرج أهل طليطِلة إليه في نحوِ عشرين ألفًا، فلمَّا التَقَوا بموسى واقتتلوا انهزم محمد بن طريشة في أصحابه، وهو من أهلِ طُليطِلة، فتَبعَه أهلُ طُليطِلة في الهزيمة، وانهزم معهم مُطَرِّف بن عبد الرحمن، فقُتِلَ من أهل طليطِلة خلقٌ كثيرٌ، وقَوِيَ موسى بن ذي النون، وهابه من حاذَرَه."},{"id":867,"era":"c3","t":"ثورة أبى روح على الدولة الطولونية بمصر .","s":"ظهر بمصر إنسانٌ يكنى أبا روحٍ، واسمه سكن، وكان من أصحاب ابن الصوفي، واجتمع له جماعةٌ، فقطع الطريق، وأخاف السبيلَ، فوَجَّه إليه ابن طولون جيشًا, فوقف أبو روحٍ في أرض كثيرةِ الشقوق، وقد كان بها قمحٌ فحُصِد، وبقي مِن تبنه على الأرضِ ما يستُرُ الشقوق، وقد ألِفُوا المشي على مثل هذه الأرضِ، فلما جاءهم الجيش لقوهم، ثم انهزم أصحابُ أبي روح، فتبعهم عسكرُ ابن طولون، فوقعت حوافِرُ خيولهم في تلك الشُّقوق، فسق"},{"id":868,"era":"c3","t":"وفاة الحسن العسكري .","s":"هو أبو محمد الحسن العسكري بن علي الهادي بن محمد الجواد بن علي الرضا بن موسى الكاظم بن جعفر الصادق بن محمد الباقر بن علي زين العابدين بن الحسين بن علي بن أبي طالب، هو الإمامُ الحادي عشر عند الشيعة الذين يدَّعون عِصمَتَهم, كان مولدُه بسامرَّا بلد العسكرِ، ومنها أخذ لقبه، وأمُّه أمُّ ولدٍ. توفِّيَ في سامرا وله تسع وعشرون سنة. ودُفِنَ إلى جانب والده. والحسَنُ العسكري هو والد محمَّد المهدي الذي تزعمُ ا"},{"id":869,"era":"c3","t":"حرب أبي الساج للزنج في الأهواز .","s":"ولَّى المعتمِدُ أبا الساج الأهواز بعد مسيرِ عبد الرحمن بن مفلح عنها إلى فارس، وأمَرَه بمحاربة الزنج، فسيَّرَ صهره عبد الرحمن لمحاربة الزنج، فلَقِيه علي بن أبان المهلبي بناحية دولاب، فقُتِلَ عبد الرحمن، وانحاز أبو الساج إلى ناحية عسكر مكرم، ودخل الزِّنج الأهواز، فقتلوا أهلَها وسَبَوا وأحرَقوا، ثم انصرف أبو الساج عمَّا كان إليه من الأهواز، وحربِ الزنج، فوَلِيَها إبراهيم بن سيما فلم يزَلْ بها حتى انص"},{"id":870,"era":"c3","t":"تجهيز مسرور البلخي لقتال خوارج الزنج .","s":"أمر الخليفةُ المعتَمِدُ الموفِّقَ أن يسيرَ إلى حرب الزنج؛ فولَّى الموفِّقُ الأهوازَ والبصرةَ وكور دجلة مسرورًا البلخيَّ، وسيَّرَه في مقدمته، وعزم على المسيرِ بعده، فحدَث من أمرِ يعقوبَ الصَّفَّار ما منعه عن المسيرِ."},{"id":871,"era":"c3","t":"إبراهيم بن أحمد الأغلب يتولى إمرة أفريقية .","s":"لَمَّا مات محمد بن أحمد بن الأغلب أبو الغرانيق، سار أهل القيروان إلى إبراهيم- الذي عينه أخوه أبو الغرانيق وصيًّا على ولده عِقالٍ حتى يكبَرَ- وسألوه أن يتولى أمرَهم؛ لحُسنِ سِيرتِه وعَدْلِه، فلم يفعَلْ، ثم أجاب، وانتقل إلى قصرِ الإمارة، وباشر الأمورَ، وقام بها قيامًا مَرضيًا، وكان عادلًا حازمًا في أموره، أمَّنَ البلاد، وقتل أهلَ البغي والفساد"},{"id":872,"era":"c3","t":"ابتداء أمر السامانيين بحكم بلاد ما وراء النهر .","s":"كان جدُّ السامانيين أسدُ بن سامان من أهل خراسان، وينتسبونَ إلى الفُرس تارة وإلى سامة بن لؤيِّ بن غالب أحيانًا, وكان لأسدِ بن سامان أربعةُ بنين: نوح وأحمد ويحيى وإلياس، وكان في خراسان حين استولى عليها المأمونُ، فأكرمهم المأمونُ أربعَتَهم وقَدَّمَهم واستعملهم، فتولى أحمدُ بن أسد فرغانةَ في سنة أربع ومائتين، ويحيى بن أسد الشاشَ مع أسروشنه، وإلياس بن أسد هراةَ، ونوح بن أسد سمرقندَ، ولَمَّا تولى طاهرُ "},{"id":873,"era":"c3","t":"عصيان أهل برقة على ابن طولون .","s":"عصيَ أهلُ بُرقةَ على أحمد بن طولون، وأخرجوا أميرَهم محمد بن الفرج الفرغاني، فبعث ابنُ طولون جيشًا عليه غلامُه لؤلؤ، وأمَرَه بالرِّفقِ بهم، واستعمالِ اللين، فإن انقادوا وإلَّا فالسَّيفُ، فسار العسكرُ حتى نزلوا على بُرقة، وحصروا أهلَها وفعلوا ما أمَرَهم من اللين، فطَمِعَ أهلُ برقة، وخرجوا يومًا على بعضِ العسكرِ، وهم نازلون على باب البلدِ، فأوقعوا بهم وقَتَلوا منهم. فأرسل لؤلؤ إلى صاحِبِه أحمد يعَرِّ"},{"id":874,"era":"c3","t":"وفاة محمد بن أحمد الأغلب صاحب إفريقيا  .","s":"هو أبو عبدالله محمد بن أحمد بن الأغلب، صاحبُ إفريقيَّة، المعروفُ بأبي الغرانيق؛ بسبب اهتمامه بصيد طيور الغرانيق، وُلد عام 237هـ، وكانت ولايته عشرَ سنين وخمسة أشهر وستة عشر يومًا من 250ه إلى 261هـ، كان عهدُه هادئًا زاهرًا, تمَّ في عهده تشييدُ سلسلةٍ من الحصون والمحارس الساحلية، غيرَ أنَّ الأغالبة مُنُوا بهزائمَ في عهده بجزيرة صقلية, وكانت إفريقيةُ في عهد أبي الغرانيق مزدهرةً تعيش نهضةً كاملة، وكانت"},{"id":875,"era":"c3","t":"وفاة الإمام مسلم بن الحجاج صاحب الصحيح .","s":"هو مُسلِمُ أبو الحسَنِ القُشيري النيسابوري، أحدُ الأئمَّة من حُفَّاظ الحديثِ، صاحبُ الصحيح الذي يلي صحيحَ البخاري، انتقل إلى العراقِ والحجاز والشَّام ومصر، وسمع من جماعةٍ كثيرين، وقد أثنى عليه جماعةٌ من العلماء من أهل الحديث وغيرهم. قال أحمد بن سلمة: \"رأيت أبا زُرعة وأبا حاتم يُقَدِّمان مسلمَ بن الحجاج في معرفةِ الصَّحيحِ على مشايخ عصرهما\"، وقيل: كان سببُ مَوتِه- رحمه الله- أنَّه عُقِدَ مَجلِسٌ لل"},{"id":876,"era":"c3","t":"عودة يعقوب الصفار إلى بلاد فارس  .","s":"حصَلَت وقعةٌ بين محمد بن واصل بن إبراهيم التميمي- الذي تغلَّبَ على فارس- وعبدالرحمن بن مفلح، فكسره ابنُ واصل وأسَرَه وقتَلَ مُعظَمَ جَيشِه فلم يُفلِتْ منهم إلَّا اليسيرُ، فلما وصل خبَرُهما إلى يعقوب الصفَّار وهو بسجستان، تجدَّدَ طَمَعُه في ملك بلاد فارس، وأخذ الأموالَ والخزائن والسِّلاح التي غَنِمَها من ابن مفلح، فسار مجدًّا, وبلغ ابنُ واصل خبَرَ قُربه منه وأنه نزل البيضاءَ من أرض فارس، وهو بالأهو"},{"id":877,"era":"c3","t":"هزيمة أصحاب الزنجي على يد جند الخليفة  .","s":"كانت وقعة للزنوج مع أحمد بن ليثويه، وكان سببَها أنَّ مسرورًا البلخيَّ وجه أحمد بن ليثويه إلى كور الأهواز، فنزل السوس، وكان يعقوبُ الصفَّار قد قلَّدَ محمد بن عبيد الله بن هزارمرد الكردي كورَ الأهواز، فكاتَبَ محمد قائدَ الزنجِ يُطمِعُه في الميلِ إليه، وأوهَمَه أنَّه يتولى له كور الأهواز. وكان محمَّد يكاتِبُه قديمًا، وعزم على مداراة الصفَّار، وقائد الزِّنج، حتى يستقيمَ له الأمرُ فيها، فكاتبه صاحِبُ ا"},{"id":878,"era":"c3","t":"الأندلسيون يؤسسون مدينة تنس بساحل أفريقية .","s":"(تنس) مدينةٌ تقع بالقُربِ من مليانة بينهما بحرُ ميلان، أسَّسَها وبناها البحريونَ من أهل الأندلس، وهي مُسَوَّرة حصينة، وبعضُها على جبلٍ وقد أحاط به السُّور، وبعضُها في سهلِ الأرض، وهي قديمةٌ، ويشرب أهلُها من عينٍ عذبة تُعرَفُ بعين عبدالسلام، وبها فواكِهُ وخِصبٌ وإقلاعٌ وانحطاط، ولها أقاليمُ وأعمالٌ ومزارِعُ. أصبحت تنس جمهورية مستقلَّةً مع قدوم قبيلة السَّواد العربية."},{"id":879,"era":"c3","t":"دخول يعقوب الصفار لمدينة واسط وقتاله مع العباسيين .","s":"قدم يعقوبُ بن الليث في جحافِلَ فدخل واسط قهرًا، فخرج الخليفة المعتَمِدُ بنفسه من سامرَّا لقتاله، فتوسط بين بغداد وواسط، فانتدب له أبو أحمد الموفَّق بالله- أخو الخليفة- في جيشٍ عظيم على ميمنتِه موسى بن بغا، وعلى ميسرته مسرورٌ البلخي، فتقاتلوا قتالًا شديدًا، وقد ظهر من أصحابِ يعقوب كراهةٌ للقتال معه؛ إذ رأوا الخليفةَ يُقاتِلُه، فحملوا على يعقوبَ ومَن قد ثبت معه للقتالِ، فانهزم أصحابُ يعقوب، وثبت يعق"},{"id":880,"era":"c3","t":"الخليفة العباسي المعتمد يعهد بالخلافة لابنه جعفر .","s":"ولَّى المعتمِدُ على الله وَلَدَه جعفرًا العهدَ من بعدِه، وسماه المفوِّضَ إلى الله، وولاه المغرِبَ، وضمَّ إليه موسى بن بغا ولايةَ إفريقية ومصر والشام والجزيرة والموصل وأرمينية وطريق خراسان وغير ذلك، وجعل الأمرَ مِن بعد ولَدِه لأبي أحمد المتوكِّل، ولَقَّبَه الموفَّق بالله، وولاه المشرِقَ وضم إليه مسرورًا البلخي وولَّاه بغداد والسواد والكوفة وطريق مكة والمدينة واليمن وكسكر وكور دجلة والأهواز وفارس وأ"},{"id":881,"era":"c3","t":"تسليم أهل أنطاكية حصن لؤلؤة إلى الروم .","s":"كان سببَ ذلك أنَّ أحمد بن طولون قد أدمن الغزوَ بطرسوس قبل أن يليَ مصر، فلمَّا ولِيَ مِصرَ كان يؤثِرُ أن يلي طرسوس ليغزوَ منها أميرًا، فكتب إلى أبي أحمدَ الموفَّق يطلُبُ ولايتَها، فلم يجبه إلى ذلك، واستعمل عليها محمد بن هارون التغلبي، فركب في سفينةٍ في دجلة فألقتها الريحُ إلى الشاطئ، فأخذه أصحابُ مساور الشاري فقتلوه، واستعمَلَ عِوَضَه محمد بن علي الأرمني، وأضيفَ إليه أنطاكية، فوثب به أهلُ طرسوس فقت"},{"id":882,"era":"c3","t":"بناء جامع أحمد بن طولون بمصر .","s":"أقام أحمد بن طولون مسجدًا ضخمًا أنفق في بنائه 120 ألف دينار، وقد اهتمَّ بالأمور الهندسية في بنائه، ويُعَدُّ مسجد ابن طولون المسجِدَ الوحيدَ بمصرَ الذي غلَبَ عليه طرازُ سامِرَّاء؛ حيث المئذنةُ الملوية المُدرَّجة. وقام السلطان لاجين بإدخالِ بعض الإصلاحات فيه، وعيَّنَ لذلك مجموعةً من الصناع، كما أمر بصناعةِ ساعة فيه، فجُعِلَت قبةً فيها طيقانٌ صغيرة على عددِ ساعاتِ الليل والنهار وفتحة، فإذا مَرَّت ساع"},{"id":883,"era":"c3","t":"ذكر الفتنة ببلاد الصين .","s":"ظهرَ ببلادِ الصين إنسانٌ لا يُعرَفُ، فجمع جمعًا كثيرًا من أهل الفَسادِ والعامَّة، فأهمل المَلِكُ أمْرَه؛ استصغارًا لشأنه، فقَوِيَ وظهر حالُه وكَثُف جَمعُه؛ وقَصَده أهلُ الشَّرِّ من كل ناحية، فأغار على البلادِ وأخرَبَها ونزل على مدينةِ خانقوا وحَصَرها، وهي حصينةٌ، ولها نهرٌ عظيم، وبها عالِمٌ كثير من المسلمين، والنصارى، واليهود، والمجوس، وغيرهم من أهل الصينِ، فلما حصَرَ البلدَ اجتمعت عساكرُ المَلِك "},{"id":884,"era":"c3","t":"استيلاء ابن طولون على الشام .","s":"توفِّيَ أماجور والي دمشق، فتولى ابنُه مكانَه، فتجهَّزَ ابنُ طولون ليسيرَ إلى الشام فيَملِكَه، فكتب إلى ابن أماجور له أنَّ الخليفة قد أقطعه الشَّامَ والثغور، فأجابه بالسَّمعِ والطاعة، وسار أحمد، واستخلف بمصرَ ابنَه العباس، فلقيه ابن أماجور بالرملة، فأقره عليها وسار إلى دمشق فمَلَكَها وأقرَّ أماجور على أقطاعِهم، وسار إلى حمص فملَكَها وكذلك حماة، وحلب. وراسلَ سيما الطويل بأنطاكية يدعوه إلى طاعتِه ليُ"},{"id":885,"era":"c3","t":"أميرَ صقليَّة جعفر بن محمد يغزو مدينة سرقوسة .","s":"في هذه السنةِ ملَكَ المُسلِمونَ سَرقوسة- وهي من أعظمِ مُدُنِ صَقَليَّة- وكان سببَ مِلكِها أنَّ جعفرَ بنَ محمد أميرَ صقليَّة غزاها فأفسَدَ زَرعَها وزَرْعَ قطانية، وطبرمين، ورمطة، وغيرِها من بلاد صقليَّة التي بيَدِ الروم، ونازل سرقوسة، وحصَرَها برًّا وبحرًا وملَكَ بعضَ أرباضها، ووصَلَت مراكِبُ الرومِ نَجدةً لها، فسيَّرَ إليها أسطولًا فأصابوها وتمكَّنوا حينئذٍ مِن حَصرِها فأقام العسكرُ مُحاصَرًا لها "},{"id":886,"era":"c3","t":"وفاة المزني صاحب الشافعي .","s":"هو أبو إبراهيمَ إسماعيلُ بن يحيى بن إسماعيل بن عمرو بن مسلمٍ المُزِني المصري، وُلِدَ بالفُسطاط في مصر في سنة 175ه. صاحِبُ الشافعيِّ، تفَقَّه عليه بمصرَ، ويعَدُّ من أئمَّة الحديث والفقه، كان من المقَدَّمين من أصحاب الشافعي وأعرَفِهم بمذهبه، حتى قال الشافعي: \"المُزنيُّ ناصِرُ مذهبي\"، ألَّفَ كتُبًا تُعتبَرُ مدارَ المذهب الشافعي، منها الجامع الصغير، ومختصر المختصر، والمنثور، والمسائل المعتبَرة، والترغ"},{"id":887,"era":"c3","t":"وفاة أبي زرعة الرازي\n \n  .","s":"هو أبو زرعة عُبَيد الله بن عبد الكريم الرازي، أحدُ الحُفَّاظ المشهورين. كان مولِدُه في الريِّ بإيران سنة مائتين، وقيل سنة تسعين ومائة, من كبار الحُفَّاظ وسادات أهلِ التقوى. قيل: إنَّه كان يحفَظُ سِتَّمائة ألفِ حديثٍ، وكان فقيهًا وَرِعًا زاهِدًا عابدًا متواضِعًا خاشعًا، أثنى عليه أهلُ زمانه بالحفظِ والدِّيانة، وشَهِدوا له بالتقَدُّم على أقرانه، قال أحمد بن حنبل: \"ما عبَرَ جِسرَ بغداد أحفَظُ من أبي "},{"id":888,"era":"c3","t":"إنهاء ابن طولون تمرد ابنه العباس عليه .","s":"كان ابنُ طولون قد استخلفَ على مصرَ ابنَه العبَّاسَ، وهو متَّجِهٌ إلى الشَّامِ، فخالف العباسُ أباه،  فلما بلغه قدومُ أبيه عليه من الشامِ أخذ ما كان في بيتِ المال من الحواصِلِ ووازره جماعةٌ على ذلك، ثم ساروا إلى بُرقة خارجًا عن طاعة أبيه، فبعث إليه من أخذه ذليلًا حقيرًا، وردُّوه إلى مصر، فحَبَسه وقتَلَ جماعةً مِن أصحابه."},{"id":889,"era":"c3","t":"زعم الشيعة الإمامية اختفاء الإمام الثاني عشر .","s":"هو محمَّد المهدي بن الحسن العسكري بن علي الهادي بن محمد الجواد بن علي الرضا بن موسى الكاظم بن جعفر الصادق بن محمد الباقر بن علي زين العابدين بن الحسين بن علي بن أبي طالب، ولد بسامرَّا، وهو المهديُّ المنتظَرُ عند الرافضة، يقولون إنَّه دخل في سردابٍ في بيت والده ولم يخرُج منه، وزعموا أنَّه سيخرج في آخر الزمان بنفس العمُرِ الذي دخل فيه السرداب، وهم ينتظرونَه إلى اليومِ عند السرداب المزعوم. قيل: إنه د"},{"id":890,"era":"c3","t":"استكمال أحمد بن طولون سيطرته على الشام .","s":"حاصرَ أحمدُ بن طولون نائِبُ الدِّيارِ المصريةِ مدينةَ أنطاكيةَ وفيها سيما الطويلُ، فأخذها منه وجاءته هدايا مَلِكُ الروم، وفي جُملتِها أُسارى من أُسارى المسلمين، ومع كلِّ أسيرٍ مُصحَفٌ، منهم عبد الله بن رشيد بن كاوس، الذي كان عامِلَ الثغورِ، فاجتمع لأحمد بن طولون مُلكُ الشَّامِ بكمالِه مع الدِّيارِ المصريةِ؛ لأنَّه لَمَّا مات نائِبُ دمشق أماخور ركِبَ ابنُ طولون من مصرَ فتلقَّاه ابن أماخور إلى الرمل"},{"id":891,"era":"c3","t":"غزو بطارقة الروم مدينة أذنة بالشام .","s":"خرج خمسةٌ من بطارقة الروم في ثلاثين ألفًا من الروم إلى أذنة- وهي مدينة بالشامِ بناها الرشيدُ، وأتمها الأمينُ، بين طرسوس والمصيصة- وأهلُ أذنة أخلاطٌ من موالي الخلفاء وغيرِهم، وهي مدينةٌ جليلة عامرة ذاتُ أسواقٍ وصناعاتٍ وصادرٍ ووارد، وهي ثغرُ سيحان، فصاروا إلى المصلَّى وأسَروا أرخوز، كان واليَ الثُّغورِ، ثم عُزِلَ فرابَطَ هناك- فأُسِرَ وأسِرَ معه نحوٌ من أربعمائة رجلٍ، وقَتَلوا ممَّن نفر إليهم نحوًا"},{"id":892,"era":"c3","t":"وفاة يعقوب بن الليث مؤسس الدولة الصفارية .","s":"هو الملك أبو يوسف يعقوب بن الليث الصفَّار الخارجي- خرج على سلطانِ الخلافةِ- التُّركمانيُّ، من سجستان، أصلُه فارسي ينحدِرُ من جبال شرق فارس، أسَّسَ السُّلالةَ الصفَّاريَّة التي حكَمَت فارس وبلاد ما وراء النهر. وقد أكثَرَ أهلُ التاريخ مِن ذِكرِ هذا الرجل وذِكرِ أخيه عمرو وما ملكا من البلادِ وقتلا من العبادِ، وما جرى للخلفاءِ معهما من الوقائع، كان رجلًا عاقلًا حازمًا, وكان أوَّلَ أمْرِه أنه وأخاه عَم"},{"id":893,"era":"c3","t":"وثوب الأعراب على الحُجَّاج ونهبهم كسوة الكعبة .","s":"وثب جماعةٌ من الأعرابِ- من بني أسد- على عليِّ بن مسرور البلخي قبل وصولِه إلى المغيثة بطريقِ مكَّة، وكان الموفَّق ولَّاه الطريقَ، ووثب الأعرابُ على كسوةِ الكعبةِ فانتهبوها، وصار بعضُها إلى صاحب الزنج، وأصاب الحُجَّاجَ فيها شِدَّةٌ عظيمة."},{"id":894,"era":"c3","t":"أكراد دارنان يهزمون خوارج الزنج .","s":"كانت وَقعةً للزنج انهزموا فيها، وكان سببَها أنَّ محمد بن عبيد الله كتب إلى عليِّ بن أبان بعدَ الصُّلحِ يَسألُه المعونةَ على الأكرادِ الدارنان، على أن يجعلَ له ولأصحابه غنائِمَهم، فكتب عليٌّ إلى صاحبه يستأذِنُه، فكتب إليه أن وجِّهْ إليه جيشًا وأقِمْ أنت، ولا تُنفِذ أحدًا حتى تستوثِقَ منه بالرهائنِ، ولا يأمن غزوه والطلب بثأره. فكتب عليٌّ إلى محمد يطلبُ منه اليمين والرهائن، فبذَلَ له اليمينَ، ومَطَله"},{"id":895,"era":"c3","t":"خروج عمر بن حفصون بالأندلس .","s":"ابتدأ شَرُّ عمر بن حفصون، الذي أعيا الخلفاءَ أمرُه، وطالت في الدنيا فتنتُه، وعَظُم شَرُّه، فقام في هذه السنة على الأميرِ محمد بناحية رية. فتقدَّم إليه عامر بن عامر، فانهزم عامرٌ وأسلَمَ قُبَّته؛ فأخذها ابن حفصون، وهو أوَّل رُواقٍ ضَرَبه؛ فاستكنَّ إليه أهلُ الشر. وعزل الأميرُ محمد عامرًا عن كورة رية، وولَّاها عبد العزيز بن عباس، فهادنه ابن حفصون، وسكَنَت الحالُ بينهما. ثم عُزِل عبد العزيز، وتحرَّك "},{"id":896,"era":"c3","t":"محاولة العباس بن أحمد بن طولون غزو المغرب .","s":"عندما وصل العباسُ بن أحمد بن طولون الغربَ هربًا من والده، راسل إبراهيمَ الثاني الأغلبي، وادَّعى أنَّ الخليفةَ قد قلَّده أمر المغرب، فسار العباسُ حتى وصل إلى مدينةِ لبدة فاستقبله أهلُها فاستباحها، وغَرَّته نفسُه فتابع السيرَ نحو الغَربِ، فقاتله إبراهيمُ الثاني وهزمه واضطَرَّه إلى العودة إلى برقة، ثمَّ إن ابن طولون أرسل جيشًا خلف ابنه ليُعيدَه فأخذوه ومَن معه وأعادوهم إلى مصرَ، فسُجِنَ العبَّاسُ حتى"},{"id":897,"era":"c3","t":"بناء مدينة الموفقية .","s":"ابتنى أبو أحمد الموفَّق بن المتوكِّل مدينةً تجاه مدينة صاحب الزنج  المختارة, وسمَّاها الموفَّقيَّة، وعظُمَ شأنُها، بناها أبو أحمد ليستعينَ بها على قتال صاحب الزنج، فأرسل إلى من يأتيه بآلاتِ الماء, ويبني فيها السفنَ والشذاءات, ويجلِبُ متاع البحر. وكان قد انقطع جلَبُ البحر منذ أكثَرَ من عشر سنين لإخافةِ الخبيث السُّبُلَ، وكتب بإثبات كلِّ من يصلُحُ للجنديَّةِ إلى عمَّاله في الأمصار، ورغَّب في ذلك، وا"},{"id":898,"era":"c3","t":"الموفَّق بالله يأمر ولَدَه أبا العباس لقتال خوارج الزنج .","s":"وجَّه أبو أحمد الموفَّق ولَدَه أبا العباسِ في نحوٍ مِن عشرة آلافِ فارس وراجلٍ، في أحسَنِ هيئةٍ وأكملِ تجَمُّل لقتال الزنج، فساروا نحوَهم فكان بينه وبينهم من القتالِ والنِّزال في أوقاتٍ متعدِّدة ووقعاتٍ مشهورةٍ، استحوذ أبو العباس بن الموفِّق فيها على ما كان استولى عليه الزنجُ ببلاد واسط وأراضي دجلة، هذا وهو شابٌّ حَدَثٌ لا خبرةَ له بالحرب، ولكِنْ سَلَّمَه الله وأعلى كلمَتَه وسَدَّد رَميَتَه وأجاب د"},{"id":899,"era":"c3","t":"غزو محمد بن الفضل الروم في جزيرة صقلية .","s":"سارت سريَّةٌ من المسلمين في صقليَّة مُقَدَّمُها رجلٌ يُعرَفُ بأبي الثور، فلقيهم جيشٌ من الروم، فأصيب المسلمون كلُّهم غيرَ سبعة نفر، وعُزِل الحسَنُ بن العباس عن صقلية، ووَلِيَها محمد بن الفضل، فبثَّ السرايا في كل ناحية من صقليَّة، وخرج هو في حشدٍ وجمعٍ عظيم، فسار إلى مدينة قطانية، فأهلك زرعَها، ثم رحل إلى أصحابِ الشلندية فقاتَلَهم، فأصاب فيهم فأكثَرَ القتلَ، ثم رحل إلى طبرمين فأفسَدَ زَرعَها، ثم رح"},{"id":900,"era":"c3","t":"حملة المنذر بن محمد لتأديب المخالفين في الأندلس .","s":"في هذه السنة سيَّرَ محمد بن عبد الرحمن- صاحِبُ الأندلس- جيشًا مع ابنه المنذِر إلى المخالفينَ عليه، فقصَدَ مدينة سرقسطة، فأهلك زَرعَها وخَرَّب بلَدَها وافتتح حِصنَ روطة، فأسَرَ منه عبد الواحد الروطي، وهو من أشجَعِ أهل زمانه، وتقَدَّم إلى دير تروجة، وبلد محمَّد بن مركب بن موسى، فهتكَهما بالغارة، وقصد مدينةَ لاردة وقرطاجنة، فكان فيها إسماعيل بن موسى فحاربه، فأذعن إسماعيلُ بالطاعة، وترك الخلافَ وأعطى "},{"id":901,"era":"c3","t":"أمين أسرار صاحب الزنج يطلب الأمان من الموفق بالله .","s":"طلب جعفرُ بن إبراهيم السَّجَّان الأمانَ من الموفَّق، وكان أمينَ أسرار الخبيثِ صاحب الزنجِ، وأحدَ خواصِّه، فخلع عليه الموفَّقُ وأعطاه مالًا كثيرًا، وأمر بحَملِه إلى قريبِ مدينة الخبيث. فلمَّا حاذى قصر الخبيث صاح: وَيحَكُم إلى متى تصبِرونَ على هذا الخبيثِ الكذَّابِ؟ وحدَّثهم بما اطَّلع عليه مِن كَذِبه وفُجوره، فاستأمَنَ في ذلك اليومِ خلقٌ كثيرٌ منهم. وتتابع النَّاسُ في الخروجِ مِن عند الخبيثِ."},{"id":902,"era":"c3","t":"الموفق بالله يشدد الحصار على مدينة صاحب الزنج .","s":"عبَرَ أبو أحمد الموفَّق إلى مدينة الفاجر بعد أن أوهى قُوَّتَه في مُقامِه بمدينة الموفَّقيَّة بحصاره والتضييقِ عليه، فلما أراد العبورَ إليها أمَرَ ابنه أبا العبَّاس بالقصد للموضِعِ الذي كان قصَدَه مِن رُكنِ مدينة الخبيث الذي يحوطُه بابنه وجِلَّةِ أصحابه وقوَّاده، وقصد أبو أحمد موضِعًا من السور- فيما بين النَّهرِ المعروف بمنكى، والنهر المعروف بابن سمعان- وأمر صاعدا وزيرَه بالقصد لفُوَّهة النهر المعر"},{"id":903,"era":"c3","t":"وفاة ابن المواز المالكي .","s":"هو أبو عبد الله محمد بن إبراهيم بن زياد الإسكندراني المالكي صاحبُ التصانيف المشهورة، المعروف بابن الموَّاز، فقيهٌ مالكي، تفقَّه على أصبغ بن الفرج المصري، وعلى ابن الماجِشون، انتهت إليه رياسةُ المذهب المالكي في عصره، فكان المنتهى في تفريعِ المسائل، وكتابه المشهورُ بالموازية يعتبَرُ من الكتب المعتَمَدة في الفقه المالكي، بل قيل: هو أصحُّ كتاب في الفقه المالكي، وعليه العُمدةُ، قَدِمَ دمشقَ في صحبة أحم"},{"id":904,"era":"c3","t":"محاولة الخليفة العباسي المعتمد التآمر مع ابن طولون على أخيه الموفق .","s":"لَمَّا رأى الخليفةُ المعتَمِد أن أخاه أبا أحمد قد استحوذ على أمورِ الخلافة، وصار هو الحاكِمَ الآمِرَ الناهي، وإليه تُجلَبُ التقادم وتُحمَل الأموال والخَراج، وهو الذي يُوَلِّي ويعزل، كتب إلى أحمد بن طولون يشكو إليه ذلك، فكتب إليه ابن طولون أن يتحَوَّل إليه في مصرَ، ووعده النصرَ والقيامَ معه، فاستغلَّ غَيبةَ أخيه الموفَّق، وركب في جمادى الأولى ومعه جماعةٌ من القواد، وقد أرصد له ابن طولون جيشًا بالرق"},{"id":905,"era":"c3","t":"كاتب صاحب الزنج يطلب الأمان من الموفق .","s":"طلب محمدُ بن سمعان- كاتِبُ الخبيث، وأوثَقُ أصحابِه في نفسِه- الأمانَ من الموفَّقِ، وكان سببَ استئمانِه أنَّ الخبيث أطلَعَه على أنه عازمٌ على الخلاصِ وَحدَه بغير أهلٍ ولا مالٍ، فلمَّا رأى ذلك من عزْمِه، أرسل يطلبُ الأمان، فأمَّنَه الموفَّقُ وأحسن إليه، وقيل: كان سبَبَ خُروجِه أنه كان كارهًا لصُحبة الخبيث، مُطَّلعًا على كُفرِه وسوءِ باطِنِه، ولم يمكِنْه التخلصُ منه ففارقه."},{"id":906,"era":"c3","t":"الحرب بين عسكر ابن طولون وعسكر الموفق بمكة .","s":"سبَبُها أنَّ أحمد بن طولون سيَّرَ جيشًا مع قائدينِ إلى مكَّةَ، فوصلا إليها وجمَعا الحنَّاطين، والجزارين، وفَرَّقا فيهم مالًا؛ وكان عامِلُ مكة هارون بن محمد إذ ذاك ببستانِ ابن عامر قد فارقها خوفًا منهما، فقَدِمَ مكة جعفر الباغمردي في عسكرٍ، وتلقاه هارون بن محمد في جماعةٍ، فقَوِيَ بهم جعفر، والتَقَوا هم وأصحاب ابن طولون فاقتتلوا وأعان أهلُ خراسان جعفرًا، فقتل من أصحابِ ابن طولون مائتي رجلٍ، وانهزم ا"},{"id":907,"era":"c3","t":"خروج محمد بن الفضل أمير صقلية إلى ناحية رمطة .","s":"خرج محمد بن الفضل أميرُ صقليَّة في عسكرٍ إلى ناحية رمطة، وبلغ العَسكرُ إلى قطانية، فقتل كثيرًا من الرومِ، وسبى وغَنِم، ثم انصرف إلى بلرم."},{"id":908,"era":"c3","t":"وفاة محمد بن نُصَير رأس النصيرية .","s":"هو أبو شُعَيب- وقيل: أبو جعفر- محمد بن نُصَير بن بكر النميري البصري، أحد نوَّاب الإمام المنتظَر عند الرافضة في فترة الغَيبة الصغرى. إليه تُنسَبُ الفرقةُ النصيرية، وهي من الفِرَق الباطنيةِ من غُلاة الشيعة، زعم ابنُ نصير هذا أنَّه الباب إلى الإمامِ الحسن العسكري، أي: أنَّه الإمام والمَرجِعُ من بعده، ثم ادَّعى ألوهيَّةَ علي بن أبي طالب، وأنه هو الذي أرسلَه للنَّاسِ رسولًا، قال بالتناسُخِ وأنَّ المؤمِ"},{"id":909,"era":"c3","t":"هزيمة الروم على يد نائب طرسوس بازمان .","s":"خرجت الرومُ في مائة ألف، فنزلوا على قلمية، وهي على ستَّة أميال من طرسوس، فخرج إليهم الخادمُ نائب طرسوس بازمان ليلًا فبَيَّتَهم في ربيع الأول، فقتَلَ منهم- فيما يقال- سبعين ألفًا، وقتل مُقَدَّمَهم، وهو بطريق البطارقة، وقتل أيضًا بِطريقَ الفنَّادين، وبِطريقَ الباطليق، وأفلت بطريقِ قرة وبه عدَّة جراحات، وأخذ لهم سبعةَ صُلبان من ذهب وفضة؛ وصَليبُهم الأعظمُ من ذهب مكَلَّل بالجوهر، وأخذ خمسة عشر ألف داب"},{"id":910,"era":"c3","t":"وفاة الحسن بن زيد مؤسس الدولة العلوية .","s":"هو الحسَنُ بن زيد بن محمد بن إسماعيل بن الحسن بن زيد بن الحسن بن علي بن أبي طالب، صاحبُ طبرستان ومؤسِّس الدولةِ العَلَوية فيها، كان في الريِّ، فلما حَدَثت الفتنةُ بين بني طاهر أصحابِ خراسان وبين أهل طبرستان سنة 250هـ كتبوا إليه يستدعونَه، فبايعوه والتفَّ عليه الديلم وأمراءُ النواحي، فمَلَك طبرستان وجرجان والريَّ، فدامت دولتُه عشرين سنة، وخَلَفه بعده أخوه محمد، والحسنُ كان أحد العُلَماء الزيدية، له"},{"id":911,"era":"c3","t":"وفاة داود الظاهري .","s":"هو الحافِظُ العلَّامة داود بن علي بن خلَف، أبو سليمان الظاهريُّ الأصبهاني، صاحِبُ مذهب الظاهريَّة، المعروف بداود الظاهريِّ، وهو أصبهانيُّ الأصل، من أهل قاشان (بلدة قريبة من أصبهان) وُلِدَ سنة 200ه في الكوفة. سكن بغداد، وهو أوَّلُ من نفى القياسَ في الأحكامِ الشرعيَّة، تُنسَب إليه طائفةُ الظاهريَّة، وسُمِّيَت بذلك لتمسُّكِها بظواهرِ النصوصِ وإعراضِها عن التأويلِ والرأيِ والقياسِ. وكان داودُ أوَّلَ م"},{"id":912,"era":"c3","t":"قتل صاحب الزنج المدعي أنه علي بن محمد وإنهاء فتنته .","s":"لَمَّا قُتِلَ الذين كانوا يمُدُّون الزنجَ بالميرة، وقُطِعَت تلك الإمدادات واشتَدَّ الحصار على الزنج، ولَمَّا فرغ الموفَّقُ من شأن مدينة صاحبِ الزنج، وهي المختارة، واحتاز ما كان بها من الأموالِ وقَتَل من كان بها من الرجال، وسَبى من وجد فيها من النِّساء والأطفال، وهرب صاحِبُ الزنج عن حومةِ الحرب والجِلاد، وسار إلى بعضِ البلاد طريدًا شريدًا بشَرِّ حال؛ عاد الموفَّق إلى مدينتِه المُوفَّقيَّة مُؤيَّدًا"},{"id":913,"era":"c3","t":"مسير إسحاق بن كنداجيق إلى الشام .","s":"لَمَّا توفِّيَ أحمدُ بن طولون كان إسحاقُ بن كنداجيق على الموصل والجزيرة، فطَمِعَ هو وابن أبي الساج- وهما من كبار قادة الترك عند المعتَمِد- في الشام، واستصغرا أولادَ أحمد، وكاتَبا الموفَّقَ بالله في ذلك، واستمَدَّاه، فأمرهما بقصدِ البلاد، ووعدهما إنفاذَ الجيوش، فجمَعَا وقصدَا ما يجاوِرُهما من البلاد، فاستولَيَا عليه وأعانهما النائبُ بدمشق لأحمد بن طولون، ووعدَهما الانحيازَ إليهما فتراجع مَن بالشامِ"},{"id":914,"era":"c3","t":"وفاة الربيع بن سليمان صاحب الشافعي .","s":"هو الربيعُ بن سليمان بن عبد الجبار بن كامل أبو محمد المراثي الفقيهُ، صاحِبُ الشافعيِّ، نقل عنه مُعظَمَ أقاويلِه، وكان فقيهًا فاضلًا ثقةً دَيِّنًا، وهو أوَّلُ من أملى الحديثَ بجامع ابن طولون، مات بمصر عن عمر 96 عامًا، وصلى عليه صاحِبُ مصر خِمارَوَيه بن أحمد بن طولون."},{"id":915,"era":"c3","t":"وفاة أحمد بن طولون مؤسس الدولة الطولونية بمصر .","s":"هو أحمد بن طولون أبو العبَّاسِ، تركي الأصل، ولِدَ بسامرَّاء، عام 220ه كانت أمُّه جاريةً اسمُها هاشم, أميرُ الديار المصرية، وباني الجامع المنسوب إليه، نشأ ابنُ طولون في صيانةٍ وعفافٍ ورياسةٍ وطلَبٍ للعلمِ ودِراسةٍ للقرآن العظيم، مع حُسنِ الصَّوتِ به. تنقَّلَت به الأحوال؛ تأمَّرَ فولِيَ ثُغورَ الشامِ، ثمَّ إمرةَ دمشق، ثم ولِيَ الديار المصريةَ في سنة أربع وخمسين، وله إذ ذاك أربعونَ سنة, وكانت له أطما"},{"id":916,"era":"c3","t":"وقعة الطواحين بين المعتضِدِ بالله وبين خِمارَوَيه بن طولون .","s":"كانت بين أبي العباس المعتضِدِ بن الموفَّق وبين خِمارَوَيه بن أحمد بن طولون، وذلك أن المعتَضِد سار من دمشق- بعد أن ملَكَها- نحوَ الرملة إلى عساكرِ خمارويه، فأتاه الخبَرُ بوصول خمارويه إلى عساكرِه، وكثرةِ مَن معه من الجموع، فهَمَّ بالعود، فلم يُمكِنْه من معه من أصحاب خمارويه الذين صاروا معه؛ وكان المعتضد قد أوحش ابن كنداجيق، وابن أبي الساج، ونسبهما إلى الجبن، حيث انتظراه ليصل إليهما ففسدت نياتهما مع"},{"id":917,"era":"c3","t":"دخول محمد وعلي ابنا الحسين بن جعفر المدينة النبوية .","s":"دخل محمدٌ وعليٌّ ابنا الحُسَين بن جعفر بن موسى بن جعفر بن محمد بن علي بن الحسين بن علي بن أبي طالب المدينة، وقتلا جماعةً مِن أهلها وأخذا من القومِ مالًا، ولم يُصَلِّ أهلُ المدينة في مسجدِ رسولِ اللهِ- صلَّى اللهُ عليه وسلم- لا جمعةً ولا جماعةً، شَهرًا."},{"id":918,"era":"c3","t":"وقوع حرب بين عسكر الخليفة وعمرو الصفار .","s":"وقَعَت الحربُ بين عساكر الخليفة وفيها أحمد بن عبدالعزيز بن أبي دلف، وبين عمرو بن الليث الصَّفَّار، ودامت الحربُ من أوَّلِ النهار إلى الظهر، فانهزم عمرٌو وعساكِرُه، وكانوا خمسةَ عشَرَ ألفًا بين فارسٍ وراجلٍ، وجُرِحَ الدرهميُّ مُقَدَّمُ جيشِ عَمرِو بن الليث، وقُتِلَ مائة رجل من حُماتِهم، وأُسِرَ ثلاثةُ آلاف، واستأمنَ منهم ألفَ رجل، وغَنِموا من معسكرِ عَمرٍو من الدوابِّ والبقَرِ والحميرِ ثلاثينَ ألفَ"},{"id":919,"era":"c3","t":"تحرك بقية خوارج الزنج في أرض البصرة .","s":"تحرَّكَت بقيَّةُ الزنج في أرض البصرة ونادَوا: يا انكلاي يا منصور، وانكلاي هو ابنُ صاحب الزنج، وسليمانُ بن جامع وأبان بن علي المهلبي، وجماعةٌ من وجوههم كانوا في جيش الموفَّق, فبعث إليهم الموفَّق فقُتِلوا وحُمِلَت رؤوسُهم إليه، وصُلِبَت أبدانُهم ببغداد، وسَكَنَت شرورُهم."},{"id":920,"era":"c3","t":"نشوب حرب بين اذكوتكين ومحمد بن زيد العلوي .","s":"وقَعَت حربٌ شديدة بين أذكوتكين بن أساتكين أحدِ قوَّاد التُّرك وبين محمَّد بن زيد العلوي، صاحِبِ طبرستان، ثم سار أذكوتكين من قزوين إلى الريِّ ومعه أربعةُ آلاف فارس، وكان مع محمد بن زيد من الديلم والطبريَّة والخراسانية عالَمٌ كبير، فاقتتلوا فانهزم عسكرُ محمد بن زيد وتفَرَّقوا، وقُتِل منهم ستةُ آلافٍ وأُسِرَ ألفانِ، وغَنِمَ أذكوتكين وعسكَرُه من أثقالِهم وأموالِهم ودوابِّهم شيئًا لم يَرَوا مِثلَه، ودخ"},{"id":921,"era":"c3","t":"خمارويه يعيد توحيد مصر والشام .","s":"في هذه السَّنَة فسَدَ الحالُ بين محمد بن أبي الساج وإسحاق بن كنداج- من كبار قادةِ الأتراك في عهد المُعتَمِد- وكانا متَّفِقَين في الجزيرة، وسببُ ذلك أنَّ ابن أبي الساج نافَرَ إسحاق في الأعمالِ، وأراد التقدُّمَ، وامتنع عليه إسحاقُ، فأرسل ابن أبي الساج إلى خِمارَوَيه بن أحمد بن طولون، صاحِبِ مصر، وأطاعه وصار معه وخطَبَ له بأعمالِه، وهي قِنَّسرين، وسيَّرَ ولده ديوداد إلى خِمارَوَيه رهينةً، فأرسل إليه "},{"id":922,"era":"c3","t":"ثورة العبيد السودان في مصر .","s":"ثار السودانُ بمصر وحصروا صاحِبَ الشُّرطة، فسَمِعَ خِمارَوَيه بن أحمد بن طولون الخبَرَ، فركب، وفي يده سيفٌ مسلولٌ، وقصد دارَ صاحِبِ الشرطة، وقتل كلَّ مَن لَقِيَه من السودان، فانهزموا منه، وأكثَرَ القتلَ فيهم، وسكنت مصرُ وأمِنَ النَّاسُ"},{"id":923,"era":"c3","t":"وفاة محمد بن عبدالرحمن صاحب الأندلس .","s":"هو محمَّد بن عبد الرحمن بن الحَكَم بن هشام الأموي، صاحِبُ الأندلُس، كانت ولايتُه أربعًا وثلاثين سنةً وأحد عشر شهرًا، كان أيمَنَ أمراءِ الأندلُس مُلكًا، وأكرَمُهم تثبُّتًا وأناةً، يجمَعُ إلى هذه الخِلالِ البلاغةَ والأدبَ، وكان ذكيًّا فَطِنًا بالأمور المُشتَبِهة، خلف نيفًا وخمسين ولدًا، منهم ثلاثةٌ وثلاثون ذكرًا، ولَمَّا مات كان عمرُه نحوًا مِن خمس وستين سنةً. وَلِيَ بعده ابنُه المنذر بن محمد، بويِع"},{"id":924,"era":"c3","t":"وفاة ابن ماجه صاحب السنن .","s":"هو أبو عبد الله محمَّد بن يزيد بن ماجه، صاحِبُ كتابِ السُّنَن المشهورِ، وهي دالَّةٌ على عَمَلِه وعِلمِه وتبحُّرِه واطلاعِه واتِّباعِه للسُّنَّة في الأصول والفروع، حُكِيَ عن أبي زُرعةَ الرازي أنه انتقَدَ منها بضعة عشر حديثًا، كان عالِمًا بهذا الشأن، صاحِبَ تصانيف، منها (التاريخ والسُّنَن)، ارتحل إلى العراقَينِ- الكوفة والبصرة- ومصر والشام، مات وعمره أربعٌ وستون سنة، وصلَّى عليه أخوه أبو بكر، تولى د"},{"id":925,"era":"c3","t":"حروب أهلية في الأندلس .","s":"بعد وفاة الأمير المنذر بويعَ بالإمارة بعده لأخيه عبد الله بن محمَّد بن عبد الرحمن بن الحكم، وأفضَتِ الإمارةُ إليه، وقد مَزَّقَها الشِّقاقُ، ونَقْض العهود, وحلَّ عُراها النِّفاق؛ والفِتنةُ مُستولِية، والقلوبُ مُختَلِفة، والباطِلُ قد أُعلِن، والشَّرُّ قد اشتَهَر؛ وقد تمالأ على أهلِ الإيمان حِزبُ الشيطان؛ وتألَّبَ على أهلِ الإسلامِ أهلُ الشِّركِ ومن ضاهاهم من أهلِ الفتنةِ، الذين جرَّدوا سيوفَهم على أ"},{"id":926,"era":"c3","t":"قتال بين خمارويه وابن أبي الساج .","s":"كان بين ابن أبي الساج- أحد كبارِ قادةِ الأتراك في عهد المعتَمِد- وخِمارَوَيه بن طولون اتِّفاقٌ، وكان ابنُ أبي الساج يطيع خِمارَوَيه ويسمَعُ له، إلَّا أنَّ ابنَ أبي الساج خالف على خمارَوَيه، فلما سمع خمارويه الخبَرَ، سار عن مصر في عساكِرِه نحو الشام، فقَدِمَ إليه آخِرَ سنة أربع وسبعين، فسار ابنُ أبي الساج إليه، فالتَقَوا عند ثنية العقاب بقُرب دمشق، وكان القتالُ بينهما فانهزمت ميمنةُ خمارَوَيه وأحاط"},{"id":927,"era":"c3","t":"وفاة أمير الأندلس المنذر بن محمد بن عبدالرحمن .","s":"هو المُنذِر بن محمد بن عبد الرحمن بن الحكم أبو الحكم المرواني. تملَّك بعد والِدِه. لَقِيَ مصرَعَه وهو أمام قلعةِ بربشتر محاصِرًا لعمر بن حفصون رأس الخارجينَ على سُلطانِ الدولة الأمويَّة بالأندلس، كانت ولايتُه سنةً واحدة وأحدَ عشَرَ شهرًا وعشرة أيَّام."},{"id":928,"era":"c3","t":"وفاة أبي داود صاحب السنن .","s":"هو سُليمان بن الأشعث بن إسحاق بن بشير بن شداد السِّجستاني، إمامٌ في الحديث، وُلِدَ بسجستان عام 202ه، رحل إلى بغداد وتفَقَّه فيها على الإمامِ أحمد وغيرِه، ورحل إلى الحجاز والشام ومصر، قال أبو بكر الخَلَّال: \"أبو داود سليمانُ بن الأشعث السجستاني الإمامُ المقدَّم في زمانِه، رجلٌ لم يَسبِقْه إلى معرفةِ تخريجِ العلومِ وبَصرِه بمواضِعِها أحَدٌ مِن أهلِ زمانه، رجلٌ وَرِعٌ مُقَدَّم\"، وقال إبراهيم الحربي: "},{"id":929,"era":"c3","t":"وفاة بقي بن مخلد الأندلسي صاحب المسند .","s":"هو أبو عبدالرحمن بقِيُّ بن مَخلَد بن يزيد أبو عبد الرحمن الأندلسي الحافِظُ الكبير، له المُسنَد المبَوَّب على الفِقهِ، روى فيه عن ألفٍ وستمائة صحابي، وقد فضَّلَه ابنُ حزم على مسند الإمامِ أحمد بن حنبل، وقد رحل بقيٌّ إلى العراقِ، فسَمِعَ من الإمام أحمد وغيرِه من أئمَّة الحديث بالعراق وغيرها، يزيدون على المائتين بأربعة وثلاثين شيخًا، وله تصانيفُ أخرى، وكان رجلًا صالحًا عابدًا زاهدًا مُجابَ الدَّعوة، "},{"id":930,"era":"c3","t":"وفاة ابن قتيبة الدينوري .","s":"هو أبو محمَّد عبدالله بن مسلم بن قُتَيبة الدِّينَوَري وقيل المروزي، ولد سنة 213ه, خطيبُ أهل السنة، عالمٌ في التفسيرِ واللُّغة، والنحو والأدب، والتاريخ والحديث، تولَّى القضاءَ في دِينَوَر فنُسِبَ إليها، كان شديدًا على المعتَزِلة، عاد إلى بغداد ودرَّسَ فيها، ومن مؤلَّفاتِه غريبُ الحديث، ومُشكِل القرآنِ، وأدب الكاتبِ، وجامِعُ النَّحوِ، وغيرُها، توفي عن 63 سنة."},{"id":931,"era":"c3","t":"ظهور حركة القرامطة في العراق .","s":"بعد أن تمَّ القضاءُ على ثورةِ الزنج، بدأ بالظهورِ دَعوةٌ جديدة كان رائِدَها حمدانُ بن الأشعث المعروف بقَرمَط، جاء من خوزستان إلى الكوفةِ واستقَرَّ بمكانٍ يُسمَّى (النهرين)، وكان يُظهِرُ الزهدَ والتقشُّفَ ويسفُ الخُوصَ ويأكُلُ مِن كَسْبِ يَدِه، ويُكثِرُ الصلاة، فأقام على ذلك مدَّةً، فكان إذا قعد إليه رجلٌ ذاكَرَه في أمر الدينِ وزَهَّدَه في الدنيا وأعلَمَه أنَّ الصلاة المفروضةَ على الناسِ خمسونَ صلا"},{"id":932,"era":"c3","t":"جفاف ماء النيل وشدة في غلاء الأسعار .","s":"في هذه السَّنةِ غار نَهرُ النِّيلِ، حتى قيل: لم يبق فيه ماءٌ، وهذا ما لم يحصُلْ من قبلُ أبدًا، فكانت شِدَّةٌ وغلاءٌ بالأسعارِ عظيمٌ، ومجاعةٌ وقَحطٌ."},{"id":933,"era":"c3","t":"القرامطة يؤسسون دولتهم في القطيف والأحساء  .","s":"في هذا العام- وقيل عام 281هـ- جاء إلى القطيفِ رجلٌ كذَّابٌ اسمُه يحيى، يدَّعي أنَّه رسولٌ من الإمام المهدي، ويستغِلُّ رغبة المؤمنين بظهور المهديِّ؛ لتحقيقِ مطامِعِه، وأعانه على ذلك رجلٌ ثري اسمه أبو سعيد الجنابي. لكنهما كُشِفا عام 283هـ، وقُبِضَ على يحيى، أمَّا الجنابي فقد هرب، وبعد إطلاق سَراحِه ذهب يحيى للبادية، فاستمال إليه البدوَ وأعانه الجنابيُّ بأموالِه، فكوَّنوا جيشًا قويًّا من عدَّةِ قبائل"},{"id":934,"era":"c3","t":"ذكر قتال ابن حفصون بالأندلس .","s":"خرج الأميرُ عبد الله إلى بلاي مِن عَمَل قبرة، وبها عدوُّ اللهِ ابنُ حفصون مع جماعةٍ كبيرةٍ مِن أصحابِه أهلِ الفسادِ والارتداد. وكانوا قد أضَرُّوا بأقاليمِ قرطبة، وضَيَّقوا عليهم حتى أغاروا على أغنامِ قُرطبة. فخرج إليهم الأميرُ، فناهضه وصادقه القتال، فانهزم ابنُ حَفصون ومن معه، ولجأ إلى حِصنِه مع ملأٍ من أصحابِه، وعُوجِلَ خواصُّه عن الدخول معه، فلم يخلُصْ منهم أحدٌ. فبات الأميرُ قريرَ عَينٍ، والمسل"},{"id":935,"era":"c3","t":"وفاة الموفق أخو الخليفة المعتمد على الله  .","s":"هو الموفَّقُ بالله أبو أحمد محمد بن جعفر المتوكِّل على الله بن محمد المعتصم بن هارون الرشيد, وقيل: إن اسمه طلحة، الأميرُ العباسي وقائِدُ جيش الخليفة المعتَمِد على الله. ولِدَ في بغداد عام 227ه من أمِّ ولَدٍ للخليفة المتوكِّل على الله، وتربَّى تربيةً عِلميَّةً، وكان عالِمًا بالأدب والنَّسَب، والفِقه والقضاءِ، غزيرَ العَقلِ، حسَنَ التدبيرِ، كريمًا حازمًا، ذا مَقدِرةٍ في سياسةِ المُلْك، اعتبَرَه البع"},{"id":936,"era":"c3","t":"وفاة بازمان نائب مدينة طرسوس .","s":"دخل أحمدُ العجيفي طرسوسَ، وغزا مع بازمان الصائفةَ، فبلغوا شكند، فأصابت بازمان شظيةٌ من حجرِ مَنجَنيقٍ في أضلاعه، فارتحَلَ عن شكند بعد أن أشرَفَ على أخذها, فتوفِّيَ في الطريق، وحُمِلَ إلى طرسوس فدُفِنَ بها. وكان بازمان قد أطاع خِمارَوَيه بن أحمد بن طولون، فلما توفِّيَ خَلَفَه ابنُ عجيف، وكتب إلى خمارَوَيه يُخبِرُه بمَوتِه، فأقَرَّه على ولاية طرسوس، وأمَدَّه بالخيل والسِّلاحِ والذخائر وغيرِها، ثم عز"},{"id":937,"era":"c3","t":"ثورة أهل طرطوس على خمارَوَيه .","s":"سببُ ذلك أنَّ الموفَّقَ لَمَّا توفِّيَ كان له خادمٌ من خواصِّه يقال له: راغب، فاختار الجِهادَ، فسار إلى طرسوس على عَزمِ المُقام بها، فلما وصل إلى الشام سيَّرَ ما معه من دوابَّ وآلاتٍ وخيامٍ وغير ذلك إلى طرسوس، وسار هو إلى خمارَوَيه ليزورَه، ويُعَرِّفَه عزمَه، فلما لَقِيَه بدمشق أكرَمَه خمارَوَيه وأحَبَّه وأَنِسَ به، واستحيا راغِبٌ أن يطلُبَ منه المسيرَ إلى طرسوس، فطال مُقامُه عنده، فظنَّ أصحابُه أ"},{"id":938,"era":"c3","t":"الخليفة العباسي المعتمد على الله يخلع ابنه من ولاية العهد .","s":"خرج المعتَمِدُ على الله، وجلس للقُوَّادِ والقُضاةِ ووجوهِ النَّاس، وأعلَمَهم أنَّه خلع ابنَه المفَوِّضَ إلى الله جعفرًا من ولايةِ العهد، وجعل ولايةَ العَهدِ للمُعتَضِد بالله أبي العباسِ أحمدَ بنِ الموفَّق، وشَهِدوا على المفَوِّض أنه قد تبرَّأ من العهد، وأسقط اسمَه من السِّكَّة، والخِطبة، والطراز، وغير ذلك، وخُطِبَ للمُعتَضِد، وكان يومًا مشهودًا."},{"id":939,"era":"c3","t":"وفاة الخليفة المعتمد على الله وتولي المعتضد بالله الخلافة .","s":"هو أبو العبَّاس- وقيل أبو جعفر- أحمد المعتَمِدُ على الله بن جعفر المتوكل بن محمد المعتصم بن هارون الرشيد. ولِدَ سنة تسع وعشرين ومائتين بسُرَّ من رأى، وأمُّه روميَّة اسمها فتيان. كان أسمرَ رقيق اللون، خفيفًا، لطيف اللِّحية، أعْيَنَ جميلًا, كان مربوعًا نحيفًا, فلما استُخلِفَ سَمِنَ وأسرع إليه الشَّيبُ، استُخلِفَ بعد قتل المهتدي بالله في سادس عشر رجب سنة 256ه. مكث في الخلافة ثلاثًا وعشرين سنة وستة أي"},{"id":940,"era":"c3","t":"وفاة الترمذي صاحب السنن .","s":"هو الحافِظُ محمَّدُ بنُ عيسى بن سورة بنِ موسى بن الضحَّاك السلمي التِّرمذي، الضريرُ، قيل: ولِدَ أعمى، والصحيحُ أنه كُفَّ بَصرُه في كِبَرِه، بعد رحلتِه وكتابتِه العِلمَ. وهو أحدُ أئمَّة الحديث في زمانه، وله المصَنَّفات المشهورة؛ منها: الجامِعُ المعروف بالسُّنَن، والشَّمائل، وأسماءُ الصحابة، وغير ذلك، تتلمذَ على البخاريِّ، رحل إلى خُراسان والعراق والحجاز، ورُويَ عنه أنَّه قال: \"صنَّفتُ هذا المُسندَ "},{"id":941,"era":"c3","t":"بناء دار الخلافة في بغداد .","s":"أوَّلُ مَن بناها المعتضدُ بالله في هذه السَّنة، وهو أوَّلُ مَن سكَنَها من الخلفاءِ إلى آخرِ دولتِهم، وكانت أولًّا دارًا للحسَنِ بنِ سَهلٍ تُعرَفُ بالقصرِ الحَسَني، ثم صارت بعد ذلك لابنتِه بُوران زوجةِ المأمون، ثم أَصلحَت ما وَهَى منها ورَمَّمَت ما كان قد تشعَّثَ فيها، وفرَشَتْها بأنواعِ الفُرشِ في كُلِّ مَوضعٍ منها ما يليقُ به من المفارشِ، وأسكَنَتْه ما يليقُ به من الجواري والخَدَمِ، وأعدَّت بها ا"},{"id":942,"era":"c3","t":"المعتضد بالله يقضي على فتنة بني شيبان في الموصل .","s":"كان بنو شَيبانَ قد أفسدوا في الأرضِ وأخذوا يُغِيرونَ على المَوصِل وينهبون ويَسلبونَ، فتصدَّى لهم الخوارجُ وأهلُ الموصِلِ إلَّا أنهم هزموهم, فسار إليهم المعتَضِد، وقصدَ الموضِعَ الذي يجتمعونَ به من أرضِ الجزيرة، فلمَّا بلَغَهم قَصدُه جمعوا إليهم أموالَهم، فأغار عليهم وأوقعَ بهم، فقتَلَ منهم مقتلةً عظيمةً وغَرِقَ منهم خلقٌ كثيرٌ في الزابين – فروع أنهارٍ حَولَ الفُرات- وأخذ النِّساءَ والذراريَّ وغَنِ"},{"id":943,"era":"c3","t":"نشوء الدولة الزيدية في مدينة صعدة باليمن .","s":"كان يَحيى بنُ الحُسَين بن القاسم بن إبراهيم بن إسماعيلَ بنِ إبراهيم بن الحسن بن الحسَن بن علي بن أبي طالب، يقيمُ بالمدينة المنوَّرة، فجاءه وفٌد مِن اليمَنِ يدعوه للمُقامِ في بلادهم وأن يقومَ لهم بأمرِهم، فسافر إليهم في هذا العامِ، غيرَ أنَّه لم يجد ما كان يتوقَّعُه، فعاد للمدينةِ، فجاءه وفدٌ آخَرُ فاعتذر إليه ممَّا كان ووعدوه بالنَّصرِ فرجع إليهم، وأقام في صعدة، ثمَّ بدأت الدولةُ تتأسَّسُ وتَقوى، "},{"id":944,"era":"c3","t":"ظهور القرامطة في البحرين .","s":"كان ابتداءُ القرامِطةِ بناحية البحرين أنَّ رجُلًا يُعرفُ بيحيى بن المهدي قصدَ القَطيفَ فنزل على رجلٍ يُعرَفُ بعليِّ بن المعلي بن حمدان، مولى الزياديِّين، وكان مُغاليًا في التشيُّع، فأظهَرَ له يحيى أنَّه رسولُ المهدي، وكان ذلك سنة 281، وذكَرَ أنه خرج إلى شيعتِه في البلاد يدعوهم إلى أمرِه، وأنَّ ظهورَه قد قَرُب، فوجه عليُّ بن المعلي إلى الشيعةِ مِن أهل القطيف فجمَعَهم، وأقرأهم الكتابَ الذي مع يحيى ب"},{"id":945,"era":"c3","t":"خِمارَوَيه أميرُ مِصرَ يغزوِ بلاد الرومِ .","s":"أرسل خِمارَوَيه أميرُ مِصرَ طغج بن جف إلى غزوِ الرومِ، فتوجَّهَ مِن طرسوس حتى بلغ طرابزون، وفتح ملورية في جُمادى الآخرة، ودامت الحربُ بين المسلمين والروم اثني عشر يومًا، فظَفِرَ المسلمونَ وغَنِموا غنائمَ كثيرةً ثمَّ عادوا."},{"id":946,"era":"c3","t":"هدم دار الندوة بمكة وبناء مسجد مكانها .","s":"كانت دارُ النَّدوةِ عامرةً بالحَرَمِ تجاهَ الكعبةِ في مكَّةَ المُكرَّمة مِن الجِهةِ الشَّماليَّة الغربيَّة، وكان ينزِلُ بها الخُلَفاءُ والأُمَراءُ في حجِّهم في صدرِ الإسلام، ولكنَّها أُهمِلَ أمرُها في مُنتصَفِ القَرنِ الثالثِ الهجريِّ فأخذ يتهَدَّمُ بناؤُها. فكتب في ذلك إلى الخليفةِ المُعتَضِد العباسيِّ، فأمر بها فهُدِمَت في هذا العامِ وجُعِلَت مسجِدًا وفيها قبلةٌ إلى الكعبةِ، ثم بُني له قُبَّةٌ ع"},{"id":947,"era":"c3","t":"مسير المعتضِد بالله إلى المَوصِل لقتال الخوارج .","s":"خرج المعتضِدُ إلى المَوصِل، قاصدًا حَمدانَ بنَ حمدون التغلبيَّ؛ لأنَّه بلغه أنَّ حَمدانَ التَّغلِبيَّ مال إلى هارون الشاري الخارجي، ودعا له، فلمَّا بلغ الأعرابَ والأكرادَ مَسيرُ المعتَضِد تحالَفوا أنَّهم يُقاتِلونَ على دمٍ واحد، واجتمعوا وعَبَّوا عسكرَهم، وسار المعتضِدُ إليهم في خَيلِه، فأوقع بهم، وقتل منهم، وغرِقَ منهم في الزابِ خَلقٌ كثير. ثم تابع المعتَضِدُ سَيرَه إلى الموصل يريد قلعةَ ماردين، "},{"id":948,"era":"c3","t":"اغتيال خمارويه حاكم الدولة الطولونية .","s":"كان خِمارَوَيه في دمشقَ في قاسيون، وكان قد بلغه أنَّ جاريةً له قد اتَّخَذت خَصِيًّا له كالزَّوجِ لها، فلمَّا عَلِمَ بذلك وأراد أن يقتُلَه تمالأ الخدَمُ على قتلِه فقَتَلوه وهو في فراشِه ذبحًا، ثم أُخِذَ الخدَمُ وقُتِلوا وكانوا أكثَرَ مِن عشرين، وقيل غيرُ ذلك في سبب قتلِه، ثم حُمِلَ في تابوتٍ إلى مصرَ ودُفِنَ فيها، وتوَّلى الحكم بعده ابنَه جيشَ بنَ خِمارَوَيه"},{"id":949,"era":"c3","t":"المعتضِد بالله يقضي على فتنة الخارجي هارون الشاري .","s":"خلَّفَ المعتَضِدُ بالموصِلِ نصرًا القشوريَّ يَجبي الأموالَ ويُعينُ العُمَّال على جبايتها، فخرج عامل معلثايا - معلثايا قريةٌ غَربَ مدينة دهوك- إليها ومعه جماعةٌ مِن أصحاب نصرٍ، فوقع عليهم طائفةٌ مِن الخوارجِ، فاقتتلوا إلى أن أدرَكَهم الليلُ وفَرَّقَ بينهم، وقُتِلَ من الخوارج إنسان اسمُه جعفر، وهو من أعيان أصحابِ هارون، فعَظُم عليه قتلُه، وأمر أصحابَه بالإفسادِ في البلادِ، فكتب نصرٌ القشوري إلى هارو"},{"id":950,"era":"c3","t":"ملك الروم يستعين بأسارى المسلمين في قتال نصارى الصقالبة .","s":"في هذه السَّنة سارت الصَّقالِبة (البلغار) إلى الرُّوم، فحصروا القُسطنطينية، وقتلوا من أهلِها خَلقًا كثيرًا وخَرَّبوا البلادَ، فلما لم يَجِدْ ملِكُ الرومِ منهم خلاصًا، جمع مَن عنده مِن أُسارى المُسلمين، وأعطاهم السِّلاحَ، وسألهم مَعونتَه على الصَّقالبة، ففعلوا وكَشَفوا الصَّقالبة وأزاحوهم عن القُسطنطينية، ولَمَّا رأى ملِكُ الروم ذلك خاف المسلمينَ على نفسِه، فردَّهم وأخذ السلاحَ منهم، وفرَّقَهم في ا"},{"id":951,"era":"c3","t":"عصيان رافع بن هرثمة على الخليفة المُعتَضِد .","s":"كان الخليفةُ المُعتَضِد قد عزل رافِعَ بنَ هرثمةَ مِن ولاية خُراسان وأعطاها لعمرِو بنِ الليث، وذلك عام 279هـ، فأعلن رافِعٌ العصيانَ، وانضم إلى محمَّدِ بنِ زيد العلوي بطبرستان، فجهَّز جيشًا وتوجَّه إلى خراسان لاستردادِها، فخرج إليه عمرُو بنُ الليث بجيشٍ واقتتل الطرفان في معركةٍ قرب طوس، فهرب رافِعٌ إلى خوارزم فتعَقَّبَه عمرو إلى أن قبضَ عليه وقتَلَه، وأرسل رأسَه إلى المعتَضِد."},{"id":952,"era":"c3","t":"وفاة الشاعر ابن الرومي .","s":"هو أبو الحسَنُ عليُّ بنُ العبَّاسِ بن جريج، مولى آل المنصورِ, أصلُه روميٌّ يُوناني، شاعِرُ زمانِه مع البحتريِّ، وُلد سنة 221. كان من كُتَّاب الدواوين، غلب عليه الشِّعرُ فلم يُعرَفْ إلَّا به، كان مُرَّ الهِجاءِ، قيل توفِّيَ مسمومًا بأمر القاسم بن عبيدالله وزيرِ المعتَضِد؛ لأنه أكثَرَ مِن هجائِه وأفحشَ، توفِّي في بغداد عن 62 عامًا. وقيل: مات سنة 284."},{"id":953,"era":"c3","t":"اغتيال أبي العساكر بن خمارويه حاكم الدولة الطولونية .","s":"خرج جماعةٌ مِن قُوَّاد حاكِمِ مِصرَ جيشِ بنِ خِمارَوَيه، وجاهروا بالمُخالفة، وقالوا: لا نرضى بك أميرًا فاعتَزِلْنا حتى نولِّي عَمَّك الإمارةَ. وكان سببُ ذلك أنَّه لَمَّا وَلِيَ وكان صبيًّا قَرَّبَ الأحداثَ والسفلَ، وأخلد إلى استماعِ أقوالهم، فغَيَّروا نيَّته على قوَّادِه وأصحابه، وصار يقعُ فيهم ويذُمُّهم، ويُظهِرُ العزمَ على الاستبدالِ بهم، وأخذَ نَعَمَهم وأموالَهم، فاتَّفَقوا عليه ليقتلوه ويقيموا"},{"id":954,"era":"c3","t":"وفاة البحتري الشاعر المشهور .","s":"هو أبو عُبادةَ الوليدُ بنُ عبيدِ بنِ يحيى الطائي البُحتري المنبجي القحطاني، صاحِبُ الديوان المعروف، شاعرٌ كبيرٌ يقال لِشعِرِه سلاسِلُ الذَّهَبِ، كان أحدَ أشعَرِ أهلِ عَصرِه، وُلِدَ بمَنبج إحدى قرى حلب عام 206ه وهو أحدُ الثلاثة الذين كانوا أشعَرَ أبناءِ عَصرِهم: هو، والمتنَبِّي، وأبو تمَّام، قيل إنَّ أبا تمام لَمَّا سمع شِعرَه قال: نُعِيَت إليَّ نَفسي، رحلَ البُحتري إلى العراق متكسِّبًا بشِعرِه، فك"},{"id":955,"era":"c3","t":"فتنة في مدينة طرسوس بين أتباع الدولة العباسية والطولونية .","s":"كان سبَبُ الفِتنةِ أنَّ راغِبًا مولى المُوَفَّق ترك الدُّعاءَ لهارون بن خِمارَوَيه بن أحمد بن طولون، ودعا لبدر مولى المعتَضِد، واختلف هو وأحمدُ بن طوغان، فلمَّا انصرف أحمدُ بنُ طوغان من الفداء سنة 283 ركب البحرَ ومضى، ولم يدخُلْ طرسوس، وخلَّفَ دِميانةَ غلامَ بازمان بها للقيامِ بأمرها، وأمَدَّه ابن طوغان، فقَوِيَ بذلك، وأنكر ما كان يفعَلُه راغب، فوقعت الفتنةُ، فظَفِرَ بهم راغب، فحمل دميانةَ إلى بغد"},{"id":956,"era":"c3","t":"بداية لعن معاوية بن أبي سفيان على المنابر  .","s":"عزَمَ المُعتَضِد على لعْنِ مُعاويةَ بنِ أبي سفيانَ- رضيَ اللهُ عنه- على المنابرِ، فحَذَّره وزيرُه عبدُ الله بن وهب، وقال له: إنَّ العامَّةَ تُنكِرُ قُلوبُهم ذلك، وهم يترحَّمونَ عليه ويترَضَّونَ عنه في أسواقِهم وجوامِعِهم، فلم يلتَفِتْ إليه، بل أمر بذلك وأمضاه، وكتب به نُسخًا إلى الخُطَباءِ بلَعنِ مُعاويةَ، وذكَرَ فيها ذمَّه وذَمَّ ابنِه يزيدَ بنِ معاوية وجماعةٍ مِن بني أمية، وأورد فيها أحاديثَ باط"},{"id":957,"era":"c3","t":"اضطرابات في مصر على هارون بن خمارويه .","s":"ظهر اختلالُ حالِ هارونَ بنِ خِمارَوَيه بنِ أحمد بن طولون بمصر، واختلَفَت القوَّاد، وطَمِعوا فانحَلَّ النظام، وتفَرَّقَت الكلمة، فأقاموا له أحدَ أمراءِ أبيه يديرُ الأمورَ ويُصلِحُ الأحوال، وهو أبو جعفرِ بن أبان، وكان عند والدِه وجَدِّه مُقَدَّمًا كبيرَ القَدرِ، فأصلحَ مِن الأحوالِ ما استطاع، وكان مَن بدمشق من الجُندِ قد خالفوا على أخيه جيشِ بنِ خِمارَوَيه، فلما تولى أبو جعفرٍ الأمورَ سَيَّرَ جيشًا "},{"id":958,"era":"c3","t":"راغِبٌ الخادِمُ مَولى المُوفَّقُ يغزو بلادَ الرومِ .","s":"غزا راغِبٌ الخادِمُ مَولى المُوفَّقُ بلادَ الرومِ ففتح حصونًا كثيرةً، وأسَرَ ذراريَّ كثيرةً جِدًّا، وقتَلَ مِن أُسارى الرجالِ الذين معه ثلاثةَ آلاف أسير، ثم عاد سالِمًا مُؤَيَّدًا منصورًا."},{"id":959,"era":"c3","t":"ابنُ الإخشيد نائب مدينة طرسوس يغزو بلادَ الرومِ .","s":"غزا ابنُ الإخشيد بأهلِ طرسوس بلادَ الرومِ، ففتح اللهُ على يديه حصونًا كثيرةً، ولله الحمدُ."},{"id":960,"era":"c3","t":"وفاة أبي العباس محمد بن يزيد المعروف بالمبرد .","s":"هو إمامُ النحو أبو العبَّاس محمَّدُ بنُ يزيدَ بنِ عبد الأكبر الأزديُّ الثمالي المعروف بالمُبَرِّد، النحويُّ البصري. ولِدَ بالبصرة عام 210 إمامٌ في اللغة العربية، أخذ ذلك عن المازنيِّ وأبي حاتم السِّجستاني، وكان إمامًا علَّامةً، جميلًا وسيمًا، فَصيحًا مُفَوَّهًا، ثقةً ثَبتًا فيما ينقُلُه, كان المبَرِّدُ مناوِئًا وزميلًا لأبي العبَّاسِ أحمد بن يحيى المشهور بثَعلب. والمبرد يحِبُّ مناظرتَه والاستكثارَ"},{"id":961,"era":"c3","t":"المعتضد بالله يحاصر مدينة آمد ويأخذها بالأمان .","s":"لَمَّا توفِّيَ أحمدُ بنُ عيسى بن الشيخ الشَّيباني صاحِبُ ديار بكر، قام بعده ابنُه محمد بآمد وما يليها على سبيل التغَلُّب، فسار المعتَضِدُ إلى آمد بالعساكر، ومعه ابنُه أبو محمد علي المُكتَفي، وجعل طريقَه على الموصِل، فوصل آمدَ، وحصرها إلى ربيع الآخر من سنة 286، ونصب عليها المجانيقَ، فأرسل محمَّد بن أحمد بن عيسى يطلبُ الأمانَ لنفسه، ولِمَن معه، ولأهل البلد، فأمَّنَهم المعتضد، فخرج إليه وسلَّم البلد،"},{"id":962,"era":"c3","t":"قتال بين إسماعيلَ الساماني وعمرو بن الليث الصَّفار .","s":"قامت الحربُ بين إسماعيلَ بنِ أحمدَ الساماني وعمرو بن الليث بنِ يعقوبَ الصَّفار؛ وذلك أنَّ عمرَو بنَ الليث لَمَّا قَتلَ رافِعَ بن هرثمة وبعث برأسِه إلى الخليفةِ، سأل منه أن يُعطِيَه ما وراء النهرِ مضافًا إلى ما بيده من ولاية خُراسان، فأجابه إلى ذلك فانزعج لذلك إسماعيلُ بنُ أحمد الساماني نائبُ ما وراء النهر، وكتب إليه: إنَّك قد وُلِّيتَ دنيا عريضةً فاقتَنِعْ بها عمَّا في يديَّ مِن هذه البلاد، فلم يق"},{"id":963,"era":"c3","t":"ظهور أبي سعيد الجنابي القرمطي في البحرين .","s":"ظهر أمرُ رجلٍ مِن القرامطة يُعرَفُ بأبي سعيد الجنابي بالبحرين، كان أوَّلَ أمرِه يبيعُ للنَّاسِ الطعامَ ويحسِبُ لهم بيعَهم، ثم أصبح أبو سعيدٍ مِن أبرز أتباعِ يحيى بن المهديِّ رسولِ المهديِّ المُنتظَر- على زعمِهم- فاجتمع إليه جماعةٌ مِن الأعراب والقرامطة، وقَوِيَ أمرُه، فقتَلَ مَن حولَه من أهلِ القُرى، ثمَّ سار إلى القطيف فقتَلَ ممَّن بها وأظهر أنَّه يريد البصرةَ، فكتب أحمدُ بنُ محمد بن يحيى الواثقي"},{"id":964,"era":"c3","t":"إظهار عمر بن حفصون النصرانية بالأندلس .","s":"أظهر عُمَرُ بنُ حفصون النصرانيَّة، وكان قد خرج في الأندلسِ على أميرها وحصَلَت بينهم عدَّةُ وقائِعَ، وكان قبل ذلك يُسِرُّها، وانعقد مع أهلِ الشِّركِ وباطَنَهم، ونفر عن أهلِ الإسلام ونابَذَهم، فتبرأ منه خلقٌ كثير، ونابذه عوسجة بن الخليع، وبنى حصِنَ قنبط، وصار فيه مواليًا للأمير عبد الله، محاربًا لابنِ حفصون, فرأى جميعُ المسلمينَ أنَّ حَربَه جهادٌ، فتتابعت عليه الغزواتُ بالصوائفِ والشَّواتي من ذلك ال"},{"id":965,"era":"c3","t":"قتل محمد بن زيد العلوي صاحب طبرستان .","s":"كان سببُ قَتلِ محمَّدِ بنِ زيد العَلويِّ أنَّه لَمَّا عَلِمَ بأسر عمرِو بن الليث الصَّفَّار، خرج من طبرستان نحو خراسان ظنًّا منه أنَّ إسماعيل الساماني لا يتجاوزُ عَمَلَه، ولا يقصِدُ خُراسان، وأنه لا دافِعَ له عنها، فلما سار إلى جُرجان أرسل إليه إسماعيل، وقد استولى على خُراسان، يقول له: الزَمْ عمَلَك، ولا تقصِدْ خُراسان؛ وتَرك جُرجان له، فأبى ذلك محمد، فندب إليه إسماعيلُ بنُ أحمد، محمَّدَ بنَ هارون"},{"id":966,"era":"c3","t":"الروم يغيرون على طرسوس ويأسرون أميرها .","s":"اجتمَعَت الروم وتحشَّدَت، ووافت بابَ قلميَّة من طرسوس، فنفر أبو ثابتٍ أميرُ طرسوس بعد كوت بن الإخشيد، وكان استخلَفَه عند موته، فبلغ أبو ثابتٍ في نفيرِه إلى نهر الرجان في طلَبِهم، فأُسِرَ أبو ثابت، وأصيبَ النَّاسُ معه، وكان ابن كلوب غازيًا في دربِ السَّلامة – موقِعٌ كان يسمَّى بدرب الحدث، لكنَّ بني أمية سمَّوه بدرب السلامة- فلمَّا عاد ابنُ كلوب جمعَ مشايخَ الثغرِ لِيَتراضَوا بأميرٍ، فأجمعوا رأيَهم "},{"id":967,"era":"c3","t":"واقعة ركب الحاج العراقي بأرض المعادن .","s":"هاجمت طيِّئٌ ركْبَ الحاجِّ العراقي بأرض المعدن. وكانت الأعرابُ في ثلاثة آلافٍ ما بين فارس وراجل، وكان أميرَ الحاجِّ أبو الأغَرِّ، فأقاموا يقاتِلونَهم يومًا وليلة. واشتد القتالُ، ثمَّ إنَّ الله أيَّدَ الرَّكبَ وهزموهم، وقُتِلَ صالحُ بنُ مدرك الذي نهب الحاجَّ فيما مضى، وقُتِلَ معه أعيانُ طيئٍ، ودخل الركبُ بغدادَ بالرؤوس على الرِّماحِ وبالأسرى."},{"id":968,"era":"c3","t":"ولاية أبي العباس بن الأغلب جزيرة صقلية .","s":"كان إبراهيمُ بنُ الأمير أحمدَ أمير إفريقيَّة قد استَعمَلَ على صقليَّةَ أبا مالكٍ أحمدَ بنَ عمر بن عبدالله، فاستضعفه، فولَّى بعده ابنَه أبا العباسِ بنَ إبراهيمَ بنِ أحمد بن الأغلب، فوصل إليها في مائةٍ وعشرين مركبًا وأربعينَ حربيًّا."},{"id":969,"era":"c3","t":"المعتضد بالله يأمر بقتال القرامطة .","s":"عظُمَ أمرُ القرامطةِ بالبحرين، وأغاروا على نواحي هجَر، وقَرُب بعضُهم من نواحي البصرةِ، فكتب أحمدُ الواثقيُّ يسألُ المدَدَ، فأمر المعتَضِدُ باختيار رجلٍ يُنفِذُه إلى البصرة، وعزَلَ العبَّاسَ بنَ عمرو عن بلاد فارس، وأقطعه اليمامةَ والبحرين، وأمَرَه بمحاربة القرامطة وضَمَّ إليه زُهاءَ ألفَي رجل، فسار إلى البصرةِ، واجتمع إليه جمعٌ كثيرٌ من المتطوِّعة والجُند والخَدَم، ثم سار إلى أبي سعيدٍ الجَنابي، فل"},{"id":970,"era":"c3","t":"دخول الروم إلى بلادَ الرقَّة .","s":"قصد الرومُ في هذه السنة بلادَ الرقَّة في جحافِلَ عظيمةٍ وعساكِرَ من البحر والبر، فقتلوا خلقًا وأسَروا نحوًا من خمسةَ عشر ألفًا من الذريَّة."},{"id":971,"era":"c3","t":"وفاة أبي الحسن ثابت بن قرة الصابئي .","s":"هو الحاسِبُ الحكيمُ أبو الحسن ثابت بن قُرَّة بن مروان بن ثابت الحَرَّاني الصابئي, وُلد في مدينة حرَّان الشامية سنة 221. كانت أسرتُه تدرِّسُ قديمًا الديانةَ الصابئيَّةَ، ثم أسلمت. كان صيرفيًّا بحرَّان، ثم انتقل إلى بغداد واشتغل بعلوم الأوائل فمهر فيها وبرعَ في الطبِّ، وكان الغالبُ عليه الفلسفةَ، وكان ثابتٌ يجيدُ عِدَّةَ لغات، منها: السريانية والعربية واليونانية، وترجم عدَّةَ مؤلَّفات من اليونانية ل"},{"id":972,"era":"c3","t":"تأسيس أشهر دول الزيدية باليمن .","s":"مؤسِّسُها يحيى بن الحسَن الطالبيُّ الذي كان يعيشُ بالمدينة المنورة، ولكِنَّه وبطلَبٍ مِن أهل اليمَنِ سافر إليهم فالتَفُّوا حوله واستقَرَّ في صعدةَ عام 284 فأراد التوسُّعَ، فاصطدم بمقاومةِ حُكَّامِ اليمَنِ، وكان أشدَّهم عليه بنو يعفرَ في صنعاء، فاصطدم معهم عام 285 غيرَ أنَّه عجزَ عن دخولها، لكنَّه دخلها عام 288ه بمساعدة الأئمَّة الزُّيود الذين استولَوا على الحُكمِ فيما بعدُ، وهم بنو الرسِّ في صعدة،"},{"id":973,"era":"c3","t":"السامانيون في بلاد ما وراء النهر يقوضون على دولة الصفارية .","s":"كان يعقوبُ بنُ اللَّيثِ الصَّفَّار قد قضى على الدَّولةِ الطاهريَّة، وأقام دولتَه على أنقاضِها، فأمر الخليفةُ أن يجهِّزَ جيشًا بقيادةِ أخيه الموفَّقِ؛ لِمُواجهة يعقوب، وذلك في عام 262هـ / 876م، ويشاءُ اللهُ أن تدور الدائرةُ على يعقوبَ فيُهزَم، ولكِنَّ المُعتَمِد يرى الاحتفاظَ بولائه للخلافةِ، فمِثلُه يمكِنُ الاعتماد عليه في مواجهةِ الثَّوراتِ والانتفاضات، فبعث إليه يستميلُه ويتَرضَّاه، ويقَلِّدُه أ"},{"id":974,"era":"c3","t":"بدء الدولة العبيدية (الفاطمية) في أفريقيا .","s":"لم تنقَطِعْ حركاتُ التشَيُّع ولم تتوقَّف، فقد كانوا متعصِّبين لآرائهم، مؤمنينَ بفِكرتِهم، يزعمونَ أنَّ أحَقَّ النَّاسِ بالخلافةِ أبناءُ عليِّ بنِ أبي طالبٍ مِن نسلِ السَّيِّدةِ فاطمةَ الزَّهراءِ، فإن نالَها غيرُهم فما ذاك إلَّا أمرٌ باطِلٌ يجب أن يُمحى، ونَشِطَ دُعاةُ الشيعةِ في الدعوةِ إلى مذهبهم، وبخاصةٍ في الجهاتِ البعيدةِ عن مركز الخلافةِ، مثل أطراف فارِسَ واليمَنِ وبلاد المغرب. وكان من هؤلاء "},{"id":975,"era":"c3","t":"خروج طاهر بن الليث الصفار إلى فارس .","s":"دخل طاهِرُ بنُ محمَّد بنِ عمرِو بنِ الليث بلادَ فارس في عسكَرِه وأخرجوا عنها عامِلَ الخليفة، فكتب الأميرُ إسماعيلُ بنُ أحمد الساماني إلى طاهر يذكُرُ له أنَّ الخليفةَ المعتضِدَ قد ولَّاه سجستان، وأنَّه سائر إليها فعاد طاهِرٌ لذلك، فولَّى المعتضِدُ مولاه بدرًا فارِسَ، وأمره بالشُّخوصِ إليها لَمَّا بلغه أنَّ طاهرًا تغلب عليها، فسار إليها في جيشٍ عظيمٍ في جمادى الآخرة، فلما قَرُب من فارس تنحَّى عنها م"},{"id":976,"era":"c3","t":"أخبار القرامطة في العراق .","s":"انتشر القرامطةُ بسَوادِ الكوفة، فوجَّه المعتَضِدُ شِبلًا غلامَ أحمد بن محمد الطائي، وظفِرَ بهم، وأخذ رئيسًا لهم يُعرَف بأبي الفوارس، فسيَّرَه إلى المعتضد، فأحضره بين يديه، وقال له: أخبرني، هل تزعمون أنَّ رُوحَ الله تعالى ورُوحَ أنبيائه تحُلُّ في أجسادِكم فتعصِمُكم من الزلل وتوفِّقُكم لصالح العمل؟ فقال له: يا هذا، إن حَلَّت رُوحُ الله فينا فما يضُرُّك؟ وإن حلَّت روحُ إبليسَ فما ينفَعُك؟ فلا تسألْ ع"},{"id":977,"era":"c3","t":"أخبار القرامطة في الشام .","s":"ظهر بالشامِ رجلٌ مِن القرامطة، وجمع جموعًا من الأعرابِ، وأتى دمشق، وأميرها طغج بن جف من قِبَل هارون بن خِمارَوَيه بن أحمد بن طولون، وكانت بينهما وقَعاتٌ، وكان ابتداءُ حال هذا القرمطيِّ أنَّ زكرَوَيه بن مهرَوَيه الداعية القرمطي الذي بدأ أمرُه في العراق هذا لَمَّا رأى أنَّ الجيوشَ مِن المعتَضِد متتابِعةٌ إلى مَن بسواد الكوفةِ مِن القرامطة، فإنَّ القتلَ قد أبادهم، سعى باستغواءِ مَن قَرُب من الكوفة من"},{"id":978,"era":"c3","t":"وفاة الخليفة العباسي المعتضد بالله وتولي ابنه المكتفي بالله الخلافة .","s":"هو أميرُ المؤمنينَ أبو العَبَّاس أحمدُ بنُ طلحة الموفَّق بالله بن المتوكل على الله جَعْفَر بن المُعْتَصم بن الرشيد الهاشمي العباسي. ولد في ذي القَعدة سنة 242 في دولةِ جَدِّه، استخلف بعد عَمِّه المعتَمِد في رجبٍ سنة تسع وسبعين. وكان ملكًا شجاعًا مهيبًا، أسمرَ نحيفًا، معتدِلَ الخَلقِ، ظاهِرَ الجبروت، وافِرَ العقل، شديدَ الوطأة، من أفراد خلفاءِ بني العَبَّاس. وكان ذا سياسةٍ عظيمة. وكان المُعْتَضِدُ ي"},{"id":979,"era":"c3","t":"استيلاء محمد بن هارون على بلاد الري .","s":"كاتب أهلُ الريِّ محمَّدَ بنَ هارون الذي حارب محمَّدَ بن زيد العلوي، وتولى طبرستان لإسماعيلَ بنِ أحمد الساماني، فلما خلع محمَّدُ بن هارون طاعةَ إسماعيل، سأله أهلُ الرَّيِّ المسيرَ إليهم ليُسَلِّموها إليه، وكان سببُ ذلك أنَّ الواليَ عليهم كان قد أساء السيرةَ فيهم، فسار محمَّدُ بن هارون إليهم فحاربه واليها وهو الدتمش التركي، فقتله محمَّد وقتَلَ ابنينِ له وأخا كيغلغ، وهو من قوَّاد الخليفة، ودخل محمَّد"},{"id":980,"era":"c3","t":"الحروب مع القرامطة في الشام .","s":"أقبل يحيى بن زكرَوَيه بن مهرويه أبو قاسم القرمطي المعروفُ بالشيخ في جحافلِه، فعاث بناحية الرقَّة فسادًا، فجهز إليه الخليفةُ جيشًا نحو عشرة آلاف فارس، وكان قد سار يحيى بن زكرويه إلى دمشق وحاصرها، فقُتِلَ على باب دمشق، زرَقَه رجلٌ من المغاربةِ بِمزراقِ نارٍ- المزراقُ رُمحٌ قصير أو خفيفٌ يُقْذَف باليد- فقَتَله، ففَرِحَ الناس بقتله، وكان هذا المغربيُّ من جملة جيش المصريين، فقام بأمرِ القرامطةِ مِن بعد"},{"id":981,"era":"c3","t":"مقتل عبدالله بن الأغلب وتولي ابنه زيادة الله الإمارة من بعده .","s":"هو أبو العبَّاس عبدالله بنُ إبراهيمَ بنِ أحمد بن الأغلب، الأميرُ الأغلبيُّ أميرُ تونُسَ والقيروان الحادي عشر من أمراء الدولةِ الأغلبيَّة، كان عاقلًا حكيمًا شجاعًا، قَرَّب إليه العلماءَ واستعان بهم على تطبيق العدلِ بين الناس، وسار بهم سيرةً حَسنةً، ولكِنَّ أمرَ الحُكمِ بدأ يضطرِبُ ويضعُفُ في أيَّامِه، وكان قد سجَنَ ابنًا له هو زيادة الله، سجنَه بسبب انحرافِه في الشهواتِ، وقيل: بل لأنَّه كان يتآمَرُ"},{"id":982,"era":"c3","t":"الأندلسيون يؤسسون مدينة وهران بالساحل الجزائري .","s":"تقع على الساحلِ الغربيِّ على البحر الأبيض المتوسط، عاصمةُ غرب البلاد وثاني أكبَر مدينةٍ بعد الجزائر العاصمة. تعدُّ المدينةُ مركزًا اقتصاديًّا وميناءً بحريًّا مهمًّا. قام البحَّارة الأندلسيُّون بإنشاءِ هذه المدينة في هذا العام. حتى أصبَحَت مدينةُ وهران محطَّ نزاعٍ بين الأمويِّين في الأندلس والفاطميِّين. دُمِّرَت مدينة وهران عدةَ مرَّات أثناء تلك الحِقبة. وأصبحت المدينةُ تحت الحكم الأموي عام 407، ثم"},{"id":983,"era":"c3","t":"وفاة عبدالله بن الإمام أحمد بن حنبل .","s":"هو أبو عبدِ الرَّحمنِ عبدُ الله بنُ أحمدَ بنِ محمد بن حنبل الشيباني البغدادي، الحافظ، مِن أهل بغداد، والده هو الإمامُ أحمد بن حنبل، ولد سنة 213 وأمُّه اسمها ريحانة، تزوجَّها الإمام أحمد بعد وفاةِ زوجته الأولى عبَّاسة أم ابنِه صالحٍ، وأنجبت له ريحانةُ ابنَه عبد الله. تعلَّمَ على يدِ أبيه فسَمِعَ منه المُسنَد، فكان مُكثِرًا في الروايةِ عن أبيه وعن غيره, وكان إمامًا ثِقةً حافِظًا ثَبتًا، قال ابن المن"},{"id":984,"era":"c3","t":"المكتفي بالله يقضي على فتنة القرامطة ويأسر زعيمهم .","s":"أمرَ محمَّدُ بنُ سليمان- الذي ولَّاه المكتفي قتالَ القرامطةِ- بمناهضةِ صاحِبِ الشامة القرمطيِّ الحسين بن زكرويه - المُدَّعي أنَّه أحمد بن عبد الله- فسار إليه في عساكِرِ الخليفة، حتى لَقُوه وأصحابَه بمكان بينهم وبين حماة اثنا عشرَ ميلًا، فقَدَّمَ القرمطيُّ أصحابَه إليهم، وبقِيَ في جماعةٍ مِن أصحابه، معه مالٌ كان جمعه، وسوادُ عَسكرِه، والتحمت الحربُ بين أصحاب الخليفةِ والقرامطة، واشتَدَّت وانهزمت ال"},{"id":985,"era":"c3","t":"انتصار المسلمين على الترك في بلاد ما وراء النهر .","s":"خرجت التُّركُ في خلقٍ كثيرٍ لا يُحصَون إلى ما وراءَ النَّهر، وكان في عسكرِهم سبعُمائة قُبَّة تركية، ولا يكونُ إلَّا للرؤساء منهم، فوجَّه إليهم إسماعيلُ بنُ أحمد الساماني جيشًا كثيرًا، وتَبِعَهم من المتطَوِّعة خلقٌ كثيرٌ، فساروا نحو التُّركِ، فوصلوا إليهم وهم غارُّونَ، فكَبَسَهم المسلمون مع الصبحِ، فقَتَلوا منهم خلقًا عظيمًا لا يُحصَون، وانهزم الباقون، واستُبيحَ عَسكرُهم، وعاد المسلمونَ سالِميَن غا"},{"id":986,"era":"c3","t":"فتح المسلمين مدينة أنطاكية .","s":"في هذه السنة سار المعروفُ بغلام زرافة من طرسوس نحو بلادِ الروم، ففتح مدينةَ أنطاكية، وهي تعادِلُ القُسطنطينية، فتَحَها بالسَّيفِ عَنوةً، فقتل خمسةَ آلاف رجلٍ، وأسَرَ مِثلَهم، واستنقذَ مِن الأُسارى خمسةَ آلاف، وأخذ لهم ستينَ مَركبًا فحمَلَ فيها ما غَنِمَ من الأموال والمتاع والرَّقيق، وقُدِّرَ نصيبُ كلِّ رجلٍ ألف دينار، وهذه المدينة على ساحل البحر، فاستبشر المسلمونَ بذلك."},{"id":987,"era":"c3","t":"الروم يقتحمون ثغور المسلمين بجيش عظيم .","s":"خرج من الروم عشرةُ صُلبان مع كلِّ صليبٍ عَشرةُ آلافٍ إلى الثغور، فغاروا على أطرافِ بلاد المسلمينَ، فأحرقوا, وقَتَلوا خلقًا وسَبَوا نساءً وذرِّيةً."},{"id":988,"era":"c3","t":"القضاء على دولة بن طولون في مصر .","s":"سار محمَّدُ بن سليمان إلى حدودِ مِصرَ لحرب هارونَ بنِ خمارَوَيه بن أحمد بن طولون، وسببُ ذلك أنَّ محمَّدَ بنَ سُلَيمان لَمَّا تخلَّفَ عن المكتفي، وعاد عن محاربةِ القرامطة، واستقصى محمَّد في طلَبِهم، فلما بلغ ما أراد عزمَ على العودِ إلى العراق، أتاه كتابُ بدرٍ الحمامي غلامِ ابن طولون، وكتابُ فائق، وهما بدمشق، يدعوانِه إلى قصد البلاد بالعساكِرَ يُساعدانه على أخذها، فلما عاد إلى بغداد أنهى ذلك إلى الم"},{"id":989,"era":"c3","t":"ذكر أخبار القرامطة بالشام والعراق .","s":"أنفذ زكرَوَيه بن مهرويه، بعد قَتلِ صاحب الشامة الحُسَينِ بنِ زكرويه، رجلًا كان يعَلِّمُ الصبيانَ بالرافوفة من الفلوجة يسمَّى عبد الله بن سعيد، ويكنَّى أبا غانم، فسُمِّي نصرًا, وقيل كان المنفذ ابن زكرويه، فدار على أحياءِ العرَبِ مِن كَلبٍ وغيرهم يدعوهم إلى رأيِه، فلم يقبَلْه منهم أحد، إلَّا رجلًا من بني زياد يسمَّى مقدام بن الكيال، واستقوى بطوائِفَ من الأصبغيين المنتمينَ إلى الفواطم، وغيرِهم من الع"},{"id":990,"era":"c3","t":"ظهور الخلنجي في مصر ومحاولة القضاء عليه .","s":"ظهر بمصر رجلٌ يُعرَفُ بالخلنجي، من القادةِ, وهو أبو عبدِ اللهِ محمَّدُ بن علي الخلنجي المصري الطولوني، كان قد تخلَّفَ عن محمد بن سليمان، فاستمال جماعةً، وخالف على السُّلطانِ، فتمَلَّك الديارَ المصريَّةَ بالسَّيفِ، واستولى عليها عَنوةً مِن عيسى بن محمد النوشري. فلما مَلَك الخلنجي الديارَ المصرية ومَهَّدَ البلادَ ووطَّنَ الناسَ ووضعَ العطاءَ وفَرَض الفروضَ. كتب النوشري إلى المُكتفي بالخبر، فجَهَّز ا"},{"id":991,"era":"c3","t":"أخبار القرامطة في اليمن .","s":"وفي اليمَنِ نبغ رجلٌ يدعو إلى القرامطة يُدعى بالداعية الذي سار إلى مدينةِ صنعاء، فحاربه أهلُها فظَفِرَ بهم وقتَلَهم، فلم يُفلِتْ إلَّا اليسير، وتغلَّب على سائرِ مُدُنِ اليمن، ثم اجتمَعَ أهل صنعاء وغيرُها فحاربوا الداعيةَ فهزموه، فانحاز إلى موضعٍ من نواحي اليمن، وبلغ الخبَرُ الخليفة، فخلع على المظفَّر بن حاج في شوال، وسيَّرَه إلى عمله باليمَنِ، وأقام بها إلى أن مات."},{"id":992,"era":"c3","t":"القضاء على الخلنجي في مصر  .","s":"عَظُمَ على الخليفةِ المكتفي ما أصاب جيشَه بقيادة أبي الأغَرِّ في مصر على يدِ الخلنجي، فجهَّزَ إليه العساكِرَ ثانيًا بصحبة فاتك مولى المعتَضِد في البَرِّ، وجهَّزَ دميانة غلامَ بازمان في البحر، فقَدِمَ فاتك بجيوشِه حتى نزل بالنويرة, وقد عَظُم أمر الخلنجي وأخرج عيسى النوشري عن مصرَ وأعمالِها, ولَمَّا بلغ الخلنجيَّ مجيءُ عسكر العراق بصُحبة فاتك، جمعَ عَسكرَه وخرج إلى بابِ المدينة وعسكَرَ به، وقام بالل"},{"id":993,"era":"c3","t":"دخول الروم إلى قورس .","s":"أغارت الرومُ على قورس، من أعمالِ حلَبٍ، فقاتلهم أهلُها قتالًا شديدًا، ثم انهزموا وقُتِلَ أكثَرُهم، وقَتَلوا رؤساء بني تميم، ودخل الرومُ قورس فأحرقوا جامِعَها وساقُوا مَن بَقِيَ مِن أهلِها."},{"id":994,"era":"c3","t":"انتصارات أبي عبدالله الشيعي بأفريقيا ونهاية دولة الأغالبة .","s":"عمِلَ أبو عبد الله الشيعيُّ على تنظيم جماعتِه، حتى التزموا طاعتَه، ثم بدأ في سنة (289هـ - 901م) في مهاجمةِ دولة الأغالبة، التي دَبَّ فيها الضَّعفُ؛ بسبب سوء وضعِ آخِرِ حكامِها زيادةِ الله الثالثِ الذي قَتَل والِدَه وقرابته، مع انهماكه في اللَّهوِ، ودخل معها في عِدَّة معارِكَ وتوالت انتصاراتُ أبي عبدالله الشيعيُّ على دولة الأغالبة خاصةً بعد هرب زيادةِ الله إلى مصر، فسَقَطَت في يد أبي عبدالله الشيعي"},{"id":995,"era":"c3","t":"تعرض القرامطة للحجيج وقتلهم وسلبهم .","s":"ارتحل زكرَوَيه من نهر المثنية يريد الحاجَّ، فبلغ السَّلمان، وأقام ينتَظِرُهم، فبلغت القافلةُ الأولى واقصةَ سابِعَ المحرَّم، فأنذرهم أهلُها وأخبَروهم بقرب القرامطة، فارتحلوا لساعتِهم، وسار القرامطةُ إلى واقصة، فسألوا أهلَها عن الحاجِّ، فأخبَروهم أنَّهم ساروا فاتَّهَمهم زكرويه، فقتل العلافةَ، وأحرق العلَف، وتحصَّن أهل واقصة في حِصنِهم، فحصرهم أيامًا ثم ارتحل عنهم نحو زبالة، ولقيَ زكرَوَيه القرمطيُّ "},{"id":996,"era":"c3","t":"ذكر بعض الحوادث مع الروم .","s":"غزا ابنُ كيغلغ الرومَ مِن طرسوس، فأصاب من الرومِ أربعةَ آلافِ رأسٍ سبيًا ودوابَّ ومتاعًا، ودخل بِطْرِيقٌ من بطارقةِ الروم في الأمانِ وأسلم، كما غزا ابنُ كيغلغ شكند، وافتتح اللهُ عليه، وسار إلى الليس، فغنموا نحوًا من خمسينَ ألفَ رأسٍ، وقتلوا مقتلةً عظيمة من الروم، وانصرفوا سالِمينَ، وكاتَبَ أندرونقس البطريقُ المكتفيَ بالله يطلُبُ منه الأمان، وكان على حربِ أهلِ الثغور من قِبَل ملك الروم، فأعطاه المك"},{"id":997,"era":"c3","t":"وفاة محمَّد بنُ نَصرِ المَروزي .","s":"هو الإمامُ أبو عبد الله محمَّد بنُ نَصرِ المَروزي، إمامُ أهل الحديثِ في عصره، وأحدُ الأعلامِ في العلومِ والأعمالِ. ولِدَ سنة 202 ببغداد، ونشأ بنيسابورَ، سكن سمرقندَ وغيرَها. وكان أبوه مروزيًّا. قال الحاكمُ فيه: \"إمامُ الحديثِ في عصرِه بلا مُدافعةٍ\". كان من أعلمِ النَّاسِ باختلافِ الصَّحابةِ والتابعينَ ومَن بعدهم، كان مولِدُه ببغداد ثم رحل إلى نيسابورَ ونشأ بها، ثم رحل إلى مصر، وكان من أحسَنِ النَّ"},{"id":998,"era":"c3","t":"مقتل زكرويه بن مهرويه القرمطي .","s":"لَمَّا فعل زكرَوَيه بالحجاج ما فعل، عَظُمَ ذلك على الخليفة خاصَّةً، وعلى جميع المسلمين عامَّةً، فجهَّزَ المكتفي الجيوشَ، فلما كان أوَّل ربيع الأول سيَّرَ وصيف بن صوارتكين مع جماعةٍ من القوَّاد والعساكر إلى القرامطة، فساروا على طريقِ حفان فلَقِيَهم زكرَوَيه، ومن معه من القرامطةِ، فاقتتلوا يومهم، ثم حجزَ الليل، وباتوا يتحارَسون، ثمَّ بكَّروا إلى القتال، فاقتتلوا قتالًا شديدًا فقُتِلَ من القرامطة مقت"},{"id":999,"era":"c3","t":"وفاة أمير خراسان إسماعيل بن أحمد الساماني .","s":"هو أبو إبراهيمَ إسماعيلُ بنُ أحمدَ الساماني أميرُ خراسان وما وراء النَّهرِ، شَهِدَ عَهدُه ظهورَ السَّامانيين كقوَّةٍ في المنطقة. وهو ابنُ أحمدَ بنِ أسد، ويرجع نسَبُه إلى سامان خدا الذي أسَّس سلالةَ السَّامانيين والذي ترك المجوسيَّة واعتنقَ الإسلامَ، ويُعتبَرُ إسماعيل أبًا روحيًّا للقوميَّة الطاجيكية، كان عاقلًا عادلًا، حسَنَ السِّيرةِ في رعيَّتِه، حليمًا كريمًا، يلقب بعد موته بالماضي، وهو الذي كان"},{"id":1000,"era":"c3","t":"مفاداة الأسرى بين الروم والمسلمين .","s":"تمَّ الفِداءُ بين المسلمين والروم، وكان عِدَّةُ من فودِيَ به من الرجال والنساء ثلاثةَ آلافِ نفسٍ."},{"id":1001,"era":"c3","t":"وفاة الخليفة العباسي المكتفي بالله وتولي أخيه المقتدر بالله الخلافة .","s":"هو أميرُ المؤمنينَ أبو محمَّد علي المكتفي باللهِ بنُ الخليفة المعتَضِد بن الأمير أبي أحمد الموفَّق بن المتوكل على الله جعفر بن المعتصم بن الرشيد العباسي، وليس من الخلفاءِ مَن اسمُه عليٌّ سواه بعد عليِّ بنِ أبي طالبٍ، وليس من الخُلَفاء مَن يُكنَّى بأبي محمَّد سوى الحسَنِ بن علي بن أبي طالب وهو، ولِدَ سنة 264، وكان يُضرَبُ المثَلُ بحُسنِه في زمانه. كان معتَدِلَ القامةِ، أسودَ الشَّعرِ، حسَنَ اللِّحي"},{"id":1002,"era":"c3","t":"خلع الخليفة العباسي المقتدر وإعلان الخلافة لعبدالله بن المعتز .","s":"اجتمع جماعةٌ مِن القوَّادِ والجُند والأُمَراء على خَلعِ المُقتَدِر وتوليةِ عبدِ الله بن المعتَزِّ الخلافةَ، فأجابهم ابنُ المعتَزِّ على ألَّا يُسفَكَ بسَبَبِه دَمٌ، وكان المقتَدِرُ قد خرج يلعَبُ بالصولجان، فقصد إليه الحُسَينُ بن حمدان يريد أن يفتِكَ به، فلما سمع المقتَدِرُ الصَّيحةَ بادر إلى دارِ الخلافةِ فأغلقها دونَ الجيشِ، واجتمع الأمراءُ والأعيانُ والقُضاة في دارِ المخرمي فبايعوا عبدَ الله بن ا"},{"id":1003,"era":"c3","t":"الغزو الإسماعيلي العبيدي الفاطمي لأفريقيا .","s":"لَمَّا كان مِن أمْرِ انتهاءِ دَولةِ الأغالِبةِ واستحواذِ أبي عبدالله الشيعيِّ على البلادِ، واستقَرَّت له القيروانُ ورقادة، سار إلى سجلماسة، وكان المهديُّ وابنه أبو القاسم محبوسينِ عند اليسَع بن المدرار أميرِ سجلماسة، فلاطفه أبو عبدِالله ليُخَلِّصَ المهديَّ منه دون أذًى، وكان المهدي قد حاول الحضورَ إلى المغربِ بعد أن راسله أبو عبدالله بما فتح من البلادِ وغلبَ، وأن الأمرَ قد استتَبَّ له فلْيَحضُرْ، "},{"id":1004,"era":"c3","t":"زوال دولة الأغالبة بالمغرب .","s":"كان آخِرَ مَن تولَّى من أمراء الأغالبةِ زيادةُ الله الثالثُ الذي قتل أباه وتولى بعده عام 290، لكنَّه كان منصرفًا إلى اللَّهوِ والمُجون، فقويَ أمرُ أبي عبدالله الشيعي الحُسَين بن أحمد بن زكريَّا الصنعاني الذي رحل إلى المغربِ بعد أن مهَّدَ له الطريقَ والدَّعوةَ فيها رجلانِ قبله، وكان بينه وبين بني الأغلَبِ حروبٌ، وكان الأحولُ بنُ إبراهيم الثاني الأغلبي- عمُّ زيادةِ الله- لأبي عبدالله الشيعي بالمرصاد"},{"id":1005,"era":"c3","t":"زوال دولة الخوارج الصفرية في تاهرت .","s":"بعد أن دخل أبو عبدالله الشيعيِّ رقادةَ واستولى عليها وقضى على الأغالبةِ، اتَّجَه إلى سجلماسة قاعدةِ الخوارِجِ الصفريَّة، لكنَّه مَرَّ بطريقه على تاهرت، وكانت الدولةُ الصَّفريةُ في مرحلةِ ضَعفٍ وتنازُعٍ على السلطة، فقَتَلَ يقظان بن أبي اليقظان وبَنيه، وسار إلى العاصمة الرستمية وقتل فيها، وهرَبَ مَن هربَ، واستباح المدينةَ وحَرَقها، فقضى على الدَّولةِ الرُّستمية الصفريَّة الخارجية، لكِنَّ المذهبَ الإ"},{"id":1006,"era":"c3","t":"وفاة أبي بكر الأثرم .","s":"هو الإمامُ الحافِظُ العلَّامة: أبو بكرٍ أحمدُ بنُ محمد بن هاني الإسكافي الأثرَم الطَّائي، وقيل: الكلبيُّ. أحدُ الأعلامِ، ومُصَنِّفُ (السُّنَن)، تلميذُ الإمام أحمد. ولد في دولة الرشيد. روى عنه كثيرًا مِن المسائِلِ، سَمِعَ مِن عفان، وأبي الوليد، والقعنبي، وأبي نُعيم، وابنِ أبي شيبة, وخلقٍ كثيرٍ، وحَدَّث عنه: النَّسائي في (سُنَنه)، وموسى بن هارون، ويحيى بن صاعد، وعليُّ بن أبي طاهر القزويني، وغيرهم. و"},{"id":1007,"era":"c3","t":"عدوان ابن حفصون .","s":"اجتمع عُمَرُ بنُ حفصون، وسعيدُ بن مستنة، وسعيدُ بن هذيل، وضَمَّهم عسكرٌ واحدٌ، فضَرَبوا بناحيةِ جيان جنوب إسبانيا وأغاروا، فأصابوا وغَنِموا، وانصَرَفوا إلى حِصنِ جُريشة؛ فاتَّبَعَهم القائدُ أحمدُ بن محمد بن أبي عبدة فلَحِقَهم وهَزَمهم، وقتل جماعةً منهم، فيهم تسريل العجمي من قُوَّاد ابنِ حفصون."},{"id":1008,"era":"c3","t":"غزو المتمردين في الأندلس .","s":"افتتح القائدُ أحمدُ بنُ محمد بن أبي عبدة حصنَ الزبيب، وابتنى حصنَ ترضيض؛ تضييقًا على ابن هُذَيل، وحَصَّن قلعة الأشعث، ووضَعَ فيه ندبًا من الرجال. وشتَّى هذه السنة بجبل أرنيش من كورة قبرة. وكانت له في هذه الشتوة حركات بالغت في نكايةِ أهلِ النفاق."},{"id":1009,"era":"c3","t":"هزيمة نصارى الأندلس على يد محمَّد بن عبد الملك الطويل .","s":"خرج محمَّدُ بنُ عبد الملك الطويل إلى بار بليارش؛ فافتتح حصنَ أوربوالة، وأصاب من المُشرِكينَ ثلاثمائة سبية، وقتل كثيرًا منهم، وهدَمَ الحِصنَ وحَرَّقه. وتقَدَّمَ إلى حصني علتير والغبران فهَدَمهما. وكان مبلغُ الفَيءِ في هذه الغزاة ثلاثةَ عشرَ ألفًا."},{"id":1010,"era":"c3","t":"تأسيس دولة العبيديين الفاطميين في أفريقيا .","s":"لَمَّا ظهر المهدِيُّ مِن سِجنِه أقام بسِجِلماسة أربعين يومًا، ثم سار إلى أفريقيَّة، وأحضر الأموالَ من إنكجان، فجعَلَها أحمالًا وأخذها معه، وقد عمِلَ أبو عبدالله الشيعي على زوالِ مُلك بني الأغلب، ومُلك بني مدرار الذين منهم اليسَع، وكان لهم ثلاثون ومائة سنةً منفردين بسجلماسة، وزوالِ مُلكِ بني رستم من تاهرَت، ولهم ستون ومائة سنةٍ تفرَّدوا بتاهَرت، ومَلَك المهديُّ جميع ذلك، فلمَّا قَرُب من رقادة تلقَّ"},{"id":1011,"era":"c3","t":"إعلان قيام الدولة الفاطمية برقادة .","s":"نجح أبو عبد الله الشيعيُّ داعيةُ الإسماعيليَّةُ في إعلانِ قيامِ الدَّولةِ الفاطميَّةِ في \"رقادة\" عاصمةِ دولةِ الأغالبةِ، ومُبايعةِ عُبيدِ الله المَهديِّ بالخلافة، وجاء هذا النَّجاحُ بعد محاولاتٍ فاشلةٍ قام بها الشِّيعةُ منذ قيامِ الدولة الأمويَّة للظَّفَرِ بالخلافةِ."},{"id":1012,"era":"c3","t":"شن حرب على ابن حفصون .","s":"كان غزوُ العاصِ بنِ الإمام عبدِ الله الغَزاةَ المعروفةَ بغَزوةِ رية وفريرة. قاد الخيلَ أحمدُ بنُ محمد بن أبي عبدة. وفصَلَ يوم الخميس لتسعٍ بَقِينَ مِن شعبان؛ فتقدَّمَ إلى بلدة فحاربَها. ثم احتلَّ على نهر طلجيرة، فدارت بينه وبين أصحاب ابن حفصون حربٌ، عُقِرَت فيها خيلُ السُّلطان، وقُتِلَ عددٌ مِن أصحابِ ابنِ حفصون. ثمَّ تقدَّمَ إلى حصون إلبيرة؛ فنزل على حصنِ شبيلش، فكانت هنالك حربٌ شديدةٌ، ونالت بعض"},{"id":1013,"era":"c3","t":"وفاة محمد بن داود الظاهري .","s":"هو أبو بكرٍ محمَّدُ بنُ داود بن عليِّ بن خلف الأصبهانيُّ المعروفُ بالظاهريِّ. ابنُ الإمامِ داودَ بنِ عليٍّ الظاهري, كان عالِمًا بارعًا, إمامًا في الحديث, أديبًا شاعِرًا ظريفًا، فقيهًا ماهرًا، اشتغل على أبيه وتَبِعَه في مذهبه ومَسلَكِه وما اختاره من الطرائِقِ وارتضاه، وكان أبوه يحبُّه ويقَرِّبُه ويُدنيه. كان أحدَ من يُضرَبُ المثَلُ بذكائه. تصَدَّرَ للفُتيا بعد والده، لَمَّا جلس للفتوى بعد والِدِه ا"},{"id":1014,"era":"c3","t":"اغتيال أبي عبدالله الشيعي من قبل عبيد الله المهدي .","s":"سببُ ذلك أنَّ المهديَّ لَمّا استقامت له البلادُ، ودان له العباد، وباشر الأمورَ بنَفسِه، وكفَّ يدَ أبي عبد الله، ويدَ أخيه أبي العبَّاس - وهما أكبَرُ دعاته- داخَلَ أبا العبَّاسِ الحسَدُ، وعظُمَ عليه الفطامُ عن الأمر والنهي، والأخذِ والعطاء، فأقبل يُزري على المهديِّ في مجلسِ أخيه، ويتكلَّمُ فيه، وأخوه ينهاه، ولا يرضى فِعلَه، فلا يزيدُه ذلك إلَّا لجاجًا، ولم يزَلْ حتى أثَّر في قلب أخيه، فقال أبو عبدِ"},{"id":1015,"era":"c3","t":"وفاة أبي عبدالله الشيعي داعية عبيد الله المهدي العبيدي\n  .","s":"هو الحُسينُ بنُ أحمد بن محمد بن زكريا أبو عبد الله الشيعي المعروف بالقائم؛ فهو الذي قام بالدعوة لعُبيد الله المهدي جَدِّ ملوك مصر, ويُعرَفُ كذلك بالمعلِّم؛ لأنه يعلِّمُ الناسَ عقائِدَ الباطنية, وأصلُه من اليمن من صنعاء، وقيل: كان من أهل الكوفة، سار من سلمية من عند عُبيد الله المهدي داعيًا له في البلاد، وتنقَّلت به الأحوال إلى أن دخل المغرِبَ, وكان من دُهاة العالم، وأفرادِ بني آدم دَهاءً ومَكرًا ور"},{"id":1016,"era":"c3","t":"وفاة الراوندي الفيلسوف الملحد .","s":"هو أحمدُ بنُ يحيى بن إسحاق الراوندي نسبةً إلى راوند بلدةٍ مِن أصبهان، ولد عام 210, فيلسوف مجاهرٌ بالإلحاد، له مناظراتٌ ومجالسُ مع علماء الكلام، انفرد بمذاهِبَ نُقِلَت عنه في كتبه، كالقول بالحُلوليَّة، وتناسُخ رُوح الإله في الأئمَّة، وكان يلازِمُ الرافضةَ والملاحِدةَ، فإذا عوتِبَ قال: \"أنا أريدُ أن أعرِفَ مذاهبَهم\"، ثم كاشَفَ وناظَرَ، وصنَّف في الزندقة- لعنه اللهُ- قيل: إنَّ أباه كان يهوديًّا فأظهَ"},{"id":1017,"era":"c3","t":"قيام الدولة السامانية وزوال الدولة الصفارية .","s":"استولى أبو نصر أحمدُ بن إسماعيل السامانيُّ على سِجِستان، وسببُ ذلك أنَّه لَمَّا استقرَّ أمرُه، وثبت ملكُه في بلادِ ما وراءَ النهر، خرج في سنة 297 إلى الرَّيِّ، وكان يسكُنُ بُخارى، ثمَّ سار إلى هراة، فسيَّرَ منها جيشًا في المحرَّم سنة ثمان وتسعين إلى سِجِستان، وسيَّرَ جماعةً من أعيان قوَّاده وأمرائه، منهم أحمد بن سهل، ومحمَّد بن المظفَّر، وسيمجور الدواتي، وهو والدُ آل سيمجور ولاة خُراسان للسامانيَّ"},{"id":1018,"era":"c3","t":"وفاة الجنيد بن محمد الصوفي .","s":"هو أبو القاسِمُ الجُنَيدُ بنُ محمَّد البغدادي النهاوندي الخزَّاز- لأنه كان يعمَلُ في الخَزِّ- أصلُه من نهاوند، ولد ببغداد قيل بعد 220، ونشأ فيها، كان شيخَ العارفينَ وقُدوةَ السَّائرينَ وعَلَمَ الأولياءِ في زمانه، تفَقَّه على أبي ثورٍ, وسمِعَ من الحسن بن عرفة وغيرِه, واختصَّ بصحبةِ السَّرِيِّ السَّقَطيِّ. أتقن العِلمَ، ثم أقبَلَ على شبابه، واشتغل بما خُلِقَ له، سمع الكثيرَ، وشاهَدَ الصالحينَ وأهلَ "},{"id":1019,"era":"c3","t":"المقتدر بالله يقبض على وزيره ابن الفرات .","s":"قبَضَ المقتَدِرُ على الوزير أبي الحَسَنِ بنِ الفُرات، ووكَّلَ بدارِه، وهتَكَ حَرَمه، ونهب مالَه، ونُهِبَت دور أصحابِه ومَن يتعلَّقُ به، وافتتنت بغدادُ لِقَبضِه، ولقِيَ الناسُ شِدَّةً لِمُدة ثلاثة أيَّامٍ، ثمّ سكنوا. وكانت مدُّةُ وزارتِه- وهي الوزارة الأولى- ثلاثَ سنين وثمانية أشهر وثلاثة عشر يومًا؛ لكونه أخَّرَ أرزاقَ الجُندِ، واعتَلَّ بضيقِ الأموال، فقال المقتَدِر: أين ما ضَمِنْتَ مِن القيامِ بأم"},{"id":1020,"era":"c3","t":"وزارة الخاقاني وانحلال أمور الدولة العباسية .","s":"لَمَّا عزَلَ المُقتَدِرُ ابنَ الفرات قلَّدَ أبا علي محمد بن يحيى بن عبيد الله بن يحيى بن خاقان، وكان قليلَ الخبرةِ في تدبير أمور الوزارة, فانحَلَّت أمور الدولة؛ لأنَّه كان ضجورًا، ضَيِّقَ الصَّدرِ، مُهمِلًا لقِراءةِ كتُبِ العُمَّال، وجِبايةِ الأموال، وكان يتقَرَّبُ إلى الخاصة والعامة، فمنَعَ خَدَمَ السُّلطانِ وخَواصَّه أن يخاطِبوه بالعبدِ، وكان إذا سأله أحدٌ حاجةً دقَّ صَدرَه، وقال: نعمْ وكرامةً، "},{"id":1021,"era":"c3","t":"فتنة أهل صقلّية بين طاعة المقتدر بالله وطاعة المهديّ العلويّ .","s":"في سنة 297 استعمل عُبيدُ الله المهديُّ عليَّ بنَ عُمَرَ على صقلِّية، فلمَّا وَلِيَها كان شيخًا ليِّنًا، فلم يرضَ أهلُ صقلِّيَّة بسيرته، فعزلوه عنهم، وولَّوا على أنفسهم أحمدَ بنَ قرهب، ودعا أحمدُ بن قرهب النَّاسَ إلى طاعة المقتَدِر، فأجابوه إلى ذلك، فخَطب له بصقلِّيَّة، وقَطع خُطبةَ المهديِّ، وأخرج ابنُ قرهب جيشًا في البحرِ إلى ساحل أفريقيَّة، فلَقُوا هناك أسطولَ المهديِّ ومُقَدَّمه الحَسَن بن أبي "},{"id":1022,"era":"c3","t":"ولاية عبدالرحمن بن محمد إمارة الأندلس .","s":"كان والِدُ عبدِ الرحمنِ النَّاصر- محمَّدُ بنُ عبدِ الله- قد قتله أخوه المُطَرِّفُ فِي صدر دولةِ أبيهما. وخلَّفَ محمَّدٌ ابنَه عبدَ الرحمنِ، وهو ابنُ عشرين يومًا. ولَمَّا توفِّيَ الأميرُ عبدُ اللَّهِ جَدُّ عبدِ الرحمنِ سنة ثلاثمئة، وليَ عبدُ الرحمنِ الأمرَ بعده. وكان ذلك مِن غرائبِ الأمورِ؛ لأنَّه كَانَ شابًّا مع وجودِ أكابِرَ مِن أعمامِه وأعمامِ أبيه، وتقدَّم هُوَ- وهو ابن اثنتين وعشرين سنة- فوَلِ"},{"id":1023,"era":"c3","t":"خلاف سجستان وعودها إلى طاعة أحمد بن إسماعيل الساماني .","s":"سببُ ذلك أنَّ محمَد بن هُرمُز، المعروفُ بالمولى الصندليِّ، كان خارجيَّ المذهب، وكان قد أقام ببُخارى وهو من أهلِ سِجِستان جنوب غرب أفغانستان، وكان شيخًا كبيرًا، فجاء يومًا إلى الحُسين بن عليِّ بنِ محمَّد العارض يَطلُبُ رِزقَه، فقال له: إنَّ الأصلحَ لِمِثلِك من الشيوخِ أن يلزمَ رباطًا يَعبُدُ الله فيه، حتّى يوافيَه أجلُه، فغاظه ذلك، فانصرف إلى سِجِستان والوالي عليها منصورُ بنُ إسحاق، فاستمال جماعةً "},{"id":1024,"era":"c3","t":"اعتقال سبكري غلام عمرو بن الليث الصفاري .","s":"لَمَّا استولى السامانيُّونَ على سجستان، بلغهم خبَرُ مسيرِ سُبكرى في المفازة من فارسَ إلى سجستانَ، فسيَّروا إليه جيشًا، فلَقُوه وهو وعسكره قد أهلكَهم التَّعبُ، فأخذوه أسيرًا، واستولَوا على عسكرِه، وكتب الأميرُ أحمدُ إلى المقتَدِر بذلك، وبالفتح، فكتب إليه يشكُرُه على ذلك، ويأمُرُه بحمل سُبكرى، ومحمَّد بن عليِّ بن الليث إلى بغداد، فسيَّرَهما، وأُدخِلا بغداد مشهورَينِ على فيلَينِ، وأعاد المقتدر رسلَ أ"},{"id":1025,"era":"c3","t":"وفاة عبدالله بن محمد صاحب الأندلس .","s":"هو عبدُ اللهِ بنُ محمَّدِ بنِ عبد الرحمن بن الحاكم بن هشام بن عبد الرحمن بن معاوية الداخِل، صاحِبُ الأندلس، وليَ الأمرَ بعد أخيه المُنذِر بن محمد في صفر سنة 275، وطالت أيامُه، وبقي في المُلكِ خمسًا وعشرين سنةً وأحد عشر شهرًا، وكان من الأمراءِ العادلين الذين يَعِزُّ وجودُ مثلهم. كان صالحًا تقيًّا، كثيرَ العبادةِ والتلاوة، رافعًا لِعَلمِ الجِهادِ، مُلتَزِمًا للصَّلواتِ في الجامعِ، وله غَزواتٌ مَشهور"},{"id":1026,"era":"c4","t":"الخليفة المُقتَدِر يبعث برسالة إلى الجنابي رأس القرامطة .","s":"استأذن الوزيرُ عليُّ بنُ عيسى الخليفةَ المُقتَدِر في مكاتبةِ رأسِ القرامطة أبي سعيدٍ الحسَنِ بن بهرام الجنابي فأذِنَ له، فكتب كتابًا طويلًا يدعوه فيه إلى السَّمع والطاعة، ويوبِّخُه على ما يتعاطاه مِن تَركِ الصَّلاة والزكاةِ وارتكاب المُنكَرات، وإنكارِهم على من يذكُرُ اللهَ ويُسَبِّحُه ويحمده، واستهزائِهم بالدين واسترقاقِهم الحرائرَ، ثمَّ توعَّده الحربَ وتهَدَّده بالقتل، فلما سار بالكتابِ نحوه قُتِ"},{"id":1027,"era":"c4","t":"ظهور الحسن بن عليّ الأطروش في طَبَرستان .","s":"استولى الحسَنُ بنُ عليِّ بنِ الحسن بن عمر بن عليِّ بن الحسين بن عليِّ بن أبي طالب على طَبَرستان، وكان يلقَّبُ بالناصر، وكان الحسَنُ بن عليٍّ الأطروش قد دخل الديلم بعد قتل محمَّدِ بنِ زيد، وأقام بينهم نحو ثلاثَ عشرةَ سنة يدعوهم إلى الإسلامِ، ويقتَصِرُ منهم على العُشر، فأسلم منهم خلقٌ كثيرٌ، واجتمعوا عليه، وبنى في بلادِهم مساجِدَ، وكان للمُسلمين بإزائِهم ثغورٌ مثل: قزوين، وسالوس، وغيرهما، وكان بمدين"},{"id":1028,"era":"c4","t":"مقتل أبي سعيد الجَنّابي القرمطي .","s":"هو أبو سعيدٍ الحسَنُ بنُ بهرام الجنابي القرمطي- قَبَّحه اللهُ- أخذ القرمطةَ عن حمدانَ بنِ قرمط, وهو رأسُ القرامطة، ظهر سنة 286 بالبحرين، فدعا الناسَ إلى مذهبِه القرمطي، واجتذب إليه اللُّصوصَ وقُطَّاعَ الطُّرُقِ، واشتَدَّ خَطَرُه، فاستولى على اليمامة وعمان وهَجَر والقَطيف، قاتَلَه جيشُ المعتَضِد فهَزَم الجيشَ وقَتَلَهم سوى قائِدِهم، ترَكَه ليُخبِرَ الخليفة بما رآه منه، كان موتُ أبي سعيد في الحمَّام"},{"id":1029,"era":"c4","t":"أول هجوم عبيدي فاطمي على مصر .","s":"جهَّز عُبيدُ الله المهديُّ العساكِرَ مِن إفريقية، وسيَّرَها مع ولده أبي القاسمِ إلى الديار المصريَّةِ، فساروا إلى بُرقة، واستولوا عليها، وساروا إلى مصرَ، فمَلَك الإسكندريَّةَ والفيُّومَ، وصار في يدِه أكثَرُ البلاد، وضيَّقَ على أهلها، فسيَّرَ إليها المقتدر باللهِ مُؤنِسًا الخادمَ في جيش كثيف، فحاربهم وأجلاهم عن مصرَ، فعادوا إلى المغربِ مَهزومينَ."},{"id":1030,"era":"c4","t":"اغتيال أحمد بن إسماعيل زعيم الدولة السامانية .","s":"هو الأميرُ أحمدُ بنُ إسماعيلَ بنِ أحمد بن أسد السامانيُّ مولى بني العباس، أبو نصرٍ صاحِبُ خراسان وما وراء النهر، مِن ولَدِ أسَدِ بنِ سامان، وهم بيت لهم إمرةٌ وحِشمةٌ، وكان أبو نصرٍ حسَنَ السِّيرةِ عظيمَ الحُرمة, وكان مولعًا بالصيدِ، فخرج إلى فربر متصيِّدًا، فلمَّا انصرف أمرَ بإحراقِ ما اشتمل عليه عسكَرُه، وانصرف فورد عليه كتابُ نائبه بطبرستان، وهو أبو العبَّاس صعلوك، وكان يليها بعد وفاةِ ابنِ نوحٍ"},{"id":1031,"era":"c4","t":"مخالفة عروبة الكتاميّ على المهدوية بالقيروان .","s":"خالف عروبةُ بنُ يوسف الكتاميُّ على المهديِّ بالقَيروان، واجتمع إليه خلقٌ كثيرٌ مِن كتامة والبرابر، فأخرج المهديُّ إليهم مولاه غالبًا، فاقتتلوا قتالًا شديدًا في مَحضِر القَيروانِ، فقُتِلَ عروبةُ وبنو عمِّه، وقُتل معهم عالَمٌ لا يُحصَونَ، وجُمِعَت رؤوس مُقَدَّميهم في قُفَّةٍ وحُملت إلى المهديِّ، فقال: ما أعجَبَ أمورَ الدُّنيا، قد جمعت هذه القُفَّةُ رؤوسَ هؤلاء، وقد كان يَضيقُ بعساكِرِهم فضاءُ المغرِ"},{"id":1032,"era":"c4","t":"خبر مصر مع المهدوية العبيديين الفاطميين .","s":"أنفذ أبو محمَّدٍ عبيدُ الله الملقَّبُ بالمهديِّ جيشًا من إفريقية مع قائدٍ مِن قوَّادِه يقال له حُباسةُ، إلى الإسكندريَّةِ، فغلب عليها وكان مسيرُه في البحر، ثمَّ سار منها إلى مصر، فنزل بين مصر والإسكندريَّة، فبلغ ذلك المُقتَدِر، فأرسل مؤنِسًا الخادِمَ في عسكرٍ إلى مصر لمحاربةِ حُباسة، وأمدَّه بالسلاح والمال، فسار إليها، فالتقى العسكرانِ، فاقتتلوا قتالًا شديدًا فقُتِلَ مِن الفريقَيْن جمعٌ كثير، وجُر"},{"id":1033,"era":"c4","t":"الأعراب يقطعون الطريق على الحجّاج إلى مكة .","s":"خرجت الأعرابُ من الحاجر -وهو قاعٌ عظيمٌ بنَجدٍ تَصُبُّ فيه مجموعةُ أودية- على الحُجَّاجِ، فقطعوا عليهم الطَّريقَ، وأخذوا من العَينِ وما معهم من الأمتعةِ والجِمالِ ما أرادوا، وأخذوا مائتين وثمانين امرأةً مِن الحرائر سوى من أخذوا من المماليكِ والإماءِ."},{"id":1034,"era":"c4","t":"خروج الحسين بن حمدان بالجزيرة الفراتية .","s":"طالب الوزيرُ عليُّ بنُ عيسى الحُسَينَ بنَ حمدانٍ بمالٍ كان عليه من ديارِ ربيعة، وهو يتولَّاها، فدافَعَه، فأمره بتسليمِ البلاد إلى عُمَّالِ السلطان، فامتنع، وكان مُؤنِسٌ الخادِمُ غائبًا بمصرَ لمحاربة عسكر المهديِّ، صاحب إفريقية، فجهَّز الوزيرُ رائقًا الكبير في جيشٍ وسيَّرَه إلى الحسين بن حمدان، وكتب إلى مؤنسٍ يأمرُه بالمسير إلى ديار الجزيرة لقتال الحسينِ، بعد فراغه من أصحاب المهديِّ، فسار رائِقٌ إل"},{"id":1035,"era":"c4","t":"نزول الوباء والقحط في الأندلس .","s":"كانت مجاعةٌ بالأندلس؛ حيث بلغت الحاجةُ بالناسِ مبلغًا لا عهدَ لهم بمثله؛ وبِيعَ قَفيزُ قَمحٍ بكيلِ سوقِ قرطبة بثلاثةِ دنانير. ووقع الوباءُ في الناس، وكَثُرَ الموت في أهل الفاقةِ والحاجة، حتى كاد أن يُعجَزَ عن دفنهم. وكَثُرت صدقات أميرِ المؤمنين عبد الرحمن الناصر على المساكينِ في هذا العام، وصَدَقات أهلِ الحِسبة من رجاله، فكان الحاجب بدرُ بنُ أحمد أكثَرَهم صدقة، وأعظَمَهم بمالِه مواساةً. ولم يمكن ف"},{"id":1036,"era":"c4","t":"العبيديون الفاطميون يسيطرون على دولة الأدارسة بالمغرب .","s":"قام قائدُ العُبَيديِّينَ مصالة بن حبوس بغزو دولةِ الأدارسةِ بالمغرب الأقصى، فالتقى به الأميرُ يحيى قُربَ مكناس، فانهزمت الأدارسةُ وحاصر العُبيديون فاس، واضطُرَّ يحيى إلى الصُّلحِ على أن يدفع مبلغًا مِن المالِ، وأن يبايعَ للمهديِّ عبيدالله، وأصبح مصالة بن حبوس أميرَ فاس."},{"id":1037,"era":"c4","t":"وفاة أبي علي الجبائي شيخ المعتزلة .","s":"هو محمَّدُ بنُ عبد الوهاب بن سلام أبو عليٍّ الجُبَّائي، شيخُ طائفة الاعتزال في زمانِه، ورئيسُ عِلمِ الكلامِ، وإليه تُنسَبُ الطائفة الجُبَّائية، وعليه اشتغل أبو الحسَنِ الأشعري ثم رجع عنه، وللجُبَّائي تفسيرٌ حافِلٌ مُطَوَّل، له فيه اختياراتٌ غريبة في التفسيرِ، وقد ردَّ عليه الأشعريُّ فيه، وله كتبٌ رَدَّ فيها على الراونديِّ والنَّظَّام، وكان الجُبَّائي يقول: \"الحديثُ لأحمد بن حنبل، والفِقهُ لأصحابِ "},{"id":1038,"era":"c4","t":"وفاة النسائي صاحب السنن .","s":"هو أحمدُ بنُ عليِّ بنِ شُعَيبِ بن علي بن سنان بن بحر بن دينار، أبو عبد الرحمن النَّسائيُّ، صاحِبُ السُّنَن، كان إمامًا في الحديثِ ثِقةً ثبتًا حافِظًا. ولد سنة 215 كان مليحَ الوجهِ، مع كِبَرِ السِّنِّ. وكان يؤثِرُ لباسَ البرود النوبيَّة الخُضر، وكان له أربعُ زوجاتٍ يَقسِمُ لهن، ولا يخلو مع ذلك مِن سُرِّيَّة. وكان يُكثِرُ أكلَ الدُّيوكِ الكِبارِ تُشترى له وتُسمَّن. كان الإمامَ في عصرِه والمُقَدَّمَ "},{"id":1039,"era":"c4","t":"بناء مدينة المهدية عاصمة للعبيديين الفاطميين بأفريقيا .","s":"خرج المهديُّ بنفسِه إلى تونُسَ وقرطاجَنَّة وغيرِهما يرتادُ موضعًا على ساحِلِ البحر يتَّخِذُ فيه مدينةً، وكان يجِدُ في الكتُبِ خروجَ أبي يزيدَ على دولته، ومن أجلِه بنى المهديَّةَ، فلم يجِدْ مَوضِعًا أحسَنَ ولا أحصَنَ مِن موضع المهديَّة، وهي جزيرةٌ متَّصِلةٌ بالبَرِّ كهيئة كفٍّ متَّصِلةٍ بزِندٍ، فبناها وجعلها دار مُلكِه، وجعل لها سورًا مُحكَمًا وأبوابًا عظيمةً، وزْنُ كُلِّ مِصراعٍ مائةُ قنطارٍ، وكان"},{"id":1040,"era":"c4","t":"غزو مؤنس المظفَّر بلاد الروم وغزو ابن بِسطام طَرَسُوس .","s":"سار مُؤنِسٌ المظفَّرُ إلى بلاد الرومِ لغزاةِ الصائفة، فلمَّا صار بالموصل قلَّدَ سبكَ المفلحيَّ بازبدى وقردى، وقلَّدَ عُثمانَ العنزي مدينة بلد، وباعيناثا، وسنجار، وقلَّد وصيفًا البكتمري باقيَ بلاد ربيعة، وسار مؤنِسٌ إلى ملطية وغزا فيها، وكتب إلى أبي القاسمِ عليِّ بنِ أحمد ابن بِسطام أن يغزوَ من طَرَسُوس في أهلها، ففعل، وفتح مؤنِسٌ حصونًا كثيرةً مِن الروم، وأثر آثارًا جميلةً، وعتب عليه أهل الثغور وق"},{"id":1041,"era":"c4","t":"وفاة زيادة الله الثالث آخر أمراء الأغالبة في أفريقية .","s":"هو أبو مُضَر زيادةُ اللهِ الثَّالث بنُ عبد الله بن إبراهيم بن أحمد بن محمد بن الأغلب بن إبراهيم بن سالم بن عقال بن خفاجة، هو زيادةُ اللهِ الأصغَرُ، وهو الأميرُ الحاديَ عشَرَ والأخير من أمراء الأغالبة بإفريقية، تولَّى الإمارةَ بعد أن قَتَلَ والِدَه وقَرابَتَه؛ ليخلو له الحُكمُ. كان غارِقًا في اللَّهوِ والمجونِ في وقتٍ كانت إمارتُهم تتعَرَّضُ لاجتياحِ الدَّعوةِ العُبَيديَّة على يدِ داعيتهم أبي عبد ا"},{"id":1042,"era":"c4","t":"تغلّب كثير بن أحمد على سجستان ومحاربته .","s":"كان كثيرُ بنُ أحمد بن شهفور قد تغلَّب على أعمال سجستان، فكتب الخليفةُ إلى بدر بن عبدالله الحماميِّ، وهو متقلِّدٌ أعمال فارس، يأمره أن يرسِلَ جيشًا يحاربون كثيرًا، ويؤمِّرَ عليهم دردا، ويستعمل على الخراج زيدَ بنَ إبراهيم، فجهَّزَ بدرٌ جيشًا كثيفًا وسيَّرَهم، فلمَّا وصلوا قاتلهم كثيرٌ، فلم يكُنْ له بهم قوَّةٌ، وضَعُفَ أمره وكادوا يَملِكونَ البلد، فبلغ أهلَ البلدِ أنَّ زيدًا معه قيود وأغلال لأعيانِهم"},{"id":1043,"era":"c4","t":"وفاة الحسن الأطروش العلوي .","s":"هو الحسَنُ بنُ عليِّ بنِ الحسين بن عمر الأشرف بن علي زين العابدين العلوي الهاشمي، حاز بلادَ الديلم ثمَّ طبرستان وآمل، لُقِّبَ بالناصر، كان شاعرًا فقيهًا لُغويًّا عادلًا، نشر المذهبَ الزيديَّ في طبرستان، له مؤلَّفات كثيرة، توفِّيَ في طبرستان عن 79 عامًا، وبه انتهت سيادةُ العلويين على طبرستان."},{"id":1044,"era":"c4","t":"بداية الصراع بين المسلمين والفرنجة في الأندلس .","s":"حشَدَ أرذون بن إذفنش، وشائجة بن غرسية صاحب النصرانيَّة، بجليقية وبنبلونة، وخرجها في جموعِهم واحتفالٍ مِن كَفَرتِهم إلى مدينةِ ناجرة بالثَّغر الأقصى؛ فنزلا عليها في عَقِب ذي الحِجَّة، وأقاما عليها ثلاثةَ أيام. وعاثت النصرانيَّة في ذلك الثغر. وأفسدت الزُّروعَ، ثم تنقَّلَت إلى تطيلة. وبلغ العدوُّ إلى نهر مالس، وجزائر مسقبرة، ووادي طرسونة. وخلف شانجة نهر إبرة، وقاتل حصن بلتبرة، وقهره على أهلِ الربض، و"},{"id":1045,"era":"c4","t":"وفاة عمر بن حفصون في الأندلس .","s":"هو عُمَرُ بنُ حَفصون بن عمر بن جعفر بن دميان بن فرغلوش بن أذفونش القس, وينتمي عمر بن حفصون لأسرة من المولَّدين قوطيَّة الأصل, فجَدُّه الأعلى وقت الفتح هو القِسُّ ألفونسو، وأوَّلُ من أسلَمَ مِن أسرته هو جدُّه الرابع جعفر, وابنُ حفصون هو رأس الخوارجِ بجزيرة الأندلس, وأحدُ أشهَرِ معارضي سُلطة الدولة الأمويَّة في الأندلس، وكاد أن يغلِبَ على الأندلس، وأتعبَ السَّلاطينَ، وطال أمرُه، وعظُم البلاءُ به، وك"},{"id":1046,"era":"c4","t":"قدوم رسول الروم إلى المقتَدِر بالله للهدنة وفداء الأسرى .","s":"وصل رسولانِ مِن مَلِك الروم إلى المقتَدِر يطلبانِ المُهادنة والفِداء، فأُكرِما إكرامًا كثيرًا، وأُدخِلا على الوزيرِ، وهو في أكمل أُبَّهةٍ، وقد صفَّ الأجنادَ بالسِّلاحِ والزينة التامَّة، وأدَّيا الرسالةَ إليه، ثمَّ إنَّهما دخلا على المقتَدِر، وقد جلس لهما، واصطفَّ الأجنادُ بالسلاح والزينة التامَّة، وأدَّيا الرسالة، فأجابهما المقتَدِر إلى ما طَلَب مَلِكُ الروم من الفداء، وسيَّرَ مُؤنِسًا الخادِمَ؛ ل"},{"id":1047,"era":"c4","t":"وفاة النحوي الكوفي المعروف بالحامض .","s":"هو سُليمانُ بنُ مُحمَّد بن أحمد أبو موسى النحوي الكوفيُّ المعروفُ بالحامضِ، وقد صَحِبَ ثعلبًا أربعين سنةً وخَلَفَه في حلقتِه, وكان أوحَدَ النَّاسِ في البيانِ واللُّغةِ والشِّعرِ، وكان قد أخذ عن البصريِّينَ وكان حسَنَ الوراقةِ في الضَّبطِ وكان يتعصَّبُ على البصريِّينَ فيما أخذَ عنهم، وإنما قيل له الحامِضُ؛ لشَراسةِ أخلاقِه، وأوصى بكتُبه لأبي فاتك المقتدري بخلًا بها أن تصيرَ إلى أحدٍ مِن أهل العلمِ،"},{"id":1048,"era":"c4","t":"إرسال عساكر المهدي العبيدي إلى مصر .","s":"جهَّز المهديُّ العُبيدي صاحِبُ إفريقية جيشًا كثيفًا مع ابنِه أبي القاسم (الملقَّب بالقائم بأمر الله)، وسيَّرَهم إلى مصر، وهي المرَّة الثانية، فوصل إلى الإسكندريَّة في ربيع الآخر سنة 306، فخرج عامِلُ المقتَدِر عنها، ودخَلَها القائم، ورحل إلى مصر، فدخل الجيزةَ، وملك الأشمونينَ وكثيرًا من الصعيدِ، وكتب إلى أهلِ مكَّةَ يدعوهم إلى الدُّخولِ في طاعتِه فلم يقبلوا منه، ووردت بذلك الأخبارُ إلى بغداد، فبعث "},{"id":1049,"era":"c4","t":"وقوع فتنة بين العامة والحنابلة في بغداد .","s":"وقعت فتنةٌ ببغداد بين العامَّةِ والحنابلة، فأخذ الخليفةُ جماعةً منهم وسيَّرَهم إلى البصرةِ فحُبِسوا."},{"id":1050,"era":"c4","t":"غزوة مطونية في الأندلس .","s":"كانت غزاة الحاجِبِ بدرِ بنِ أحمد إلى دار الحرب، وهي غزاة مطونية -مدينة بالأندلس-. وكان أميرُ المؤمنين الناصر لَمَّا اتَّصل به تطاوُلُ المشركينَ على من كان بإزائِهم من أهل الثغور بامتناعِ الصَّوائِفِ عن غزوهم، والإيغالِ في بلادهم بالحرب؛ أحفَظَه ذلك، وأذكى عَزْمَه، وأكَّدَ بصيرته في مجاهدةِ أعداء الله وأعداءِ دينه في هذا العام، فأمر بالاحتفال في الحَشدِ وجَمعِ الرجالِ والتكثيرِ مِن الأجناد والفرسان"},{"id":1051,"era":"c4","t":"غزو بلاد الروم .","s":"غزا بشر الأفشينيُّ بلاد الروم، فافتتح عدَّة حُصونٍ، وغَنِم وسَلِمَ؛ وغزا ثملٌ الخادِمُ في بحر الروم، فغنم وسبى وعادَ، وكان على المَوصِل أبو أحمد بن حماد الموصليُّ، وفيها دخلَ جنِّي الصفوانيُّ بلادَ الروم، فنهب وخرَّب، وأحرق وفتَحَ وعاد، فقُرِئَت الكتب على منابرِ بغداد بذلك."},{"id":1052,"era":"c4","t":"وفاة محمّد بن خلف المعروف بوكيع .","s":"هو القاضي محمَّد بن خلَف بن حيَّان بن صدقة بن زياد البغدادي أبو بكرٍ الضَّبِّيُّ، المعروفُ بوَكيعٍ، وكان عالِمًا بأخبار النَّاسِ وغيرها، وله تصانيفُ حَسَنةٌ. قال الدارقطني: \"كان نبيلًا فصيحًا فاضِلًا، من أهل القرآنِ والفِقهِ والنحو، له تصانيفُ كثيرة\" مات وكان يتقلَّدُ قضاءَ كور الأهوازِ كُلِّها."},{"id":1053,"era":"c4","t":"وفاة الفقيه الشافعي أحمد بن عمر بن سُريج  .","s":"هو الفقيهُ الشافعي الكبير أحمد بن عمر بن سُريج كان من عُظَماءِ الشَّافعيَّة، وأئمة المسلمين، وكان يقال له: \"البازُ الأشهب\"، ولي القضاءَ بشيراز، وكان يَفضُل على جميعِ أصحاب الإمام الشافعي، حتى على المُزَني، وإنَّ فِهرست كتُبِه تشتمل على أربعمائة مصنَّف، وقام بنُصرة مذهب الشافعي والرد على المخالفين، وفرَّع على كتُبِ محمد بن الحسن الحنفي. وقد عُدَّ من الفُقَهاءِ الذين أسهموا في نشرِ المذهب الشافعي في"},{"id":1054,"era":"c4","t":"الفتنة ببغداد بسبب غلاء الأسعار .","s":"غلت الأسعارُ ببغداد فاضطربت العامَّةُ وقصدوا دار حامِدِ بنِ العباس, الذي جلسَ في منصب الوَزارة أيامًا، فظهر منه سوءُ تدبيرٍ وقِلَّةُ خِبرةٍ بأعباء الوَزارةِ, والذي ضَمِنَ لأهل بغداد خراجَ أصبهان والسَّواد،  ومع ذلك غَلَت الأسعار، وعَدا العامةُ في ذلك اليوم- وكان يوم الجمعة- على الخطيبِ، فمنعوه الخُطبةَ، وكسروا المنابِرَ وقتلوا الشُّرطة وحَرَّقوا جسورًا كثيرة، فأمر الخليفةُ بقتال العامَّةِ ثم نقَض "},{"id":1055,"era":"c4","t":"أمير الأندلس عبدالرحمن الناصر يهاجم الأسبان .","s":"كان الأميرُ الناصر غزا إلى دار الحرب، وهي غزاة مويش، والحشودُ والعساكر تتلاحَقُ به من سائر أقطار الأندلس، وجميع جهاتها، ونزل على مدينةِ طُلَيطلة، وخرج إليه لبُّ بن الطربيشة صاحِبُها، مبادرًا إليه، وغازيًا معه، وكان يظهر طاعةً تحتها معصيةٌ، حتى نزل بمدينة الفرج، فنظر لأهلها، وخرج للجهاد أكثَرُهم، حتى احتَلَّ بثغر مدينة سالم، وأظهَرَ التوجه إلى الثغر الأقصى. وقَدِمَت المُقَدِّمة نحوه. ثم عرجَ بالجيو"},{"id":1056,"era":"c4","t":"غلاء الأسعار وشدة البرد في بغداد .","s":"وزاد من بلاء أهل بغداد في هذا العامِ مع غلاءِ الأسعار ما وقع عليهم في شتاءِ هذه السنة من البَردِ الشديد جدًّا، حتى نزل الناس عن الأسطُحِ وتدَثَّروا باللُّحُف والأكسِيَة، وأضرَّ ذلك البردُ ببعضِ النَّخيلِ."},{"id":1057,"era":"c4","t":"مقتل الحسين بن منصور الحلاج أشهر غلاة الصوفية .","s":"هو الحُسين بن منصور بن محمى الحلَّاج أبو مغيث، ويقالُ أبو عبد الله، كان جَدُّه مَجوسيًّا اسمُه محمى من أهل فارس، ونشأ بواسط، ويقال بتُستر، ودخل بغداد وتردَّدَ إلى مكة وجاور بها في وسطِ المسجدِ في البَردِ والحَرِّ، مكث على ذلك سنواتٍ متفرقةً، وكان يصابِرُ نَفسَه ويُجاهدُها، وقد صَحِبَ جماعةً من سادات المشايخ الصوفيَّة، كالجُنَيد بن محمد، وعمرِو بن عثمان المكي، وأبي الحسين النوري، قال الخطيبُ البغدا"},{"id":1058,"era":"c4","t":"انتشار الصوفية بعد ظهور الحسين بن منصور الحلاج  .","s":"جيءَ بالحُسين بن منصور الحلَّاج إلى بغداد وهو مشهورٌ على جملٍ، وغلامٌ له راكبٌ جملًا آخَرَ، ينادي عليه: أحدُ دُعاةِ القرامطة فاعرفوه، ثم حُبِسَ ثمَّ جيء به إلى مجلسِ الوزير فناظره، فإذا هو لا يقرأ القرآنَ ولا يعرف في الحديثِ ولا الفِقهِ شَيئًا، ولا في اللغةِ ولا في الأخبارِ ولا في الشِّعرِ شَيئًا، وكان الذي نَقَم عليه: أنَّه وُجِدَت له رِقاعٌ يدعو فيها الناسَ إلى الضلالة والجَهالة بأنواع ٍمنِ الرم"},{"id":1059,"era":"c4","t":"غزو قَالِيقَلا ودخول أهل طرطوس ملطية .","s":"سار محمَّدُ بن نصر الحاجِبُ مِن المَوصِل إلى الغزاة على قَالِيقَلا وهي مطينة من ممدينة من مدن أرمينيةة، فغزا الرومَ مِن تلك الناحيةِ، ودخلَ أهل طرسوس ملطيَّة، فظَفِروا، وبلغوا من بلادِ الرُّومِ والظَّفَر بهم ما لم يظنُّوه وعادوا."},{"id":1060,"era":"c4","t":"وفاة إمام المفسِّرين ابن جرير الطبري .","s":"هو أبو جعفرٍ محمَّدُ بنُ يزيدَ بنِ كثير بن غالب الطَّبَري، صاحبُ التَّفسيرِ الكبيرِ, والتاريخِ الشَّهيرِ، كان إمامًا في فنون كثيرةٍ، منها: التفسير والحديث، والفقه والتاريخ، وغير ذلك، وله مُصنَّفات مَليحة في فنونٍ عديدة تدلُّ على سَعةِ عِلمِه وغزارةِ فَضلِه، وكان من الأئمَّة المجتَهِدين، لم يقَلِّدْ أحدًا مِن المجتَهِدين. مولِدُه سنة 224 بآمل طبرستان. أكثَرَ مِن التَّرحالِ، ولقي نُبلاءَ الرِّجالِ، "},{"id":1061,"era":"c4","t":"وفاة المحدث أبي بشر الدولابي .","s":"هو الإمامُ الحافِظُ البارِعُ أبو بشر محمَّد بن أحمد بن حمَّاد بن سعيد بن مسلمٍ الأنصاريُّ الدولابي الرازي، مولى الأنصارِ، ويعرف بالورَّاق، ولد سنة 224 من قرى الرَّيِّ. أحد الأئمَّة، ومن حُفَّاظ الحديثِ، وله تصانيفُ حَسَنةٌ في التاريخِ وغيرِ ذلك، وروى عن جماعةٍ كثيرة، وتوفِّيَ وهو قاصِدٌ الحَجَّ بين مكَّة والمدينة بالعرج."},{"id":1062,"era":"c4","t":"دخول أمير القرامطة سليمان الجَنابي إلى البصرة .","s":"دخل أبو طاهرٍ سُلَيمانُ بنُ أبي سعيد الجَنابي أميرُ القرامطة في ألفٍ وسبعمائة فارسٍ إلى البصرةِ ليلًا، فنصب السَّلالمَ الشَّعرَ في سورها فدخَلَها قهرًا، وفتحوا أبوابَها وقتلوا مَن لَقُوه من أهلِها، وهرب أكثَرُ النَّاسِ فألقَوا أنفُسَهم في الماء فغَرِقَ كثيرٌ منهم، ومكَثَ بها سبعةَ عشَرَ يومًا يَقتُل ويأسِرُ مِن نسائها وذراريِّها، ويأخذ ما يختارُ مِن أموالها، ثم عاد إلى بلَدِه هجَرَ، وكلَّما بعث إل"},{"id":1063,"era":"c4","t":"وفاة أبي بكر الرازي الطبيب .","s":"هو الأستاذُ الفيلسوف محمد بن زكريا الرازي، من أهلِ الرَّيِّ، فيها تعلَّمَ ونشأ، ثم سافر إلى بغداد, أشهرُ أطبَّاءِ الإسلامِ وأكثَرُهم ابتكارًا، صاحب التصانيف، من أذكياءِ أهلِ زمانِه، كان كثيرَ الأسفارِ، واسِعَ المعرفةِ، مليحَ التأليف، وكان في بصَرِه رطوبةٌ؛ لكثرةِ أكلِه الباقلَّى، عمِيَ آخِرَ عُمُره. قال عنه الذهبي: \"أخذَ عن البلخي الفيلسوفِ، فبلغ الغايةَ في علوم الأوائل. نسأل اللهَ العافية\". كان ف"},{"id":1064,"era":"c4","t":"وفاة أبي بكر الخلال، صاحب الكتاب الجامع لعلوم الإمام أحمد .","s":"هو الإمامُ العلَّامةُ الحافِظُ الفقيهُ، شيخ الحنابلةِ وعالِمُهم، أبو بكر أحمدُ بنُ محمَّد بن هارون بن يزيد البغدادي المعروفُ بالخَلَّال. ولِدَ سنة 234، أو في التي تليها، ويجوز أن يكون رأى الإمامَ أحمد، ولكنَّه أخذ الفقهَ عن خلقٍ كثيرٍ مِن أصحابه، رحل إلى فارس وإلى الشَّام والجزيرةِ يتطلَّبُ فِقهَ الإمامِ أحمدَ وفتاويَه وأجوبتَه، وكتب عن الكِبارِ والصِّغارِ، حتى كتب عن تلامذتِه، ثمَّ إنَّه صَنَّف ك"},{"id":1065,"era":"c4","t":"وفاة الزجاج صاحب معاني القرآن .","s":"هو الإمامُ الفاضل، نحويُّ زمانِه، أبو إسحاقَ إبراهيمُ بنُ مُحمَّد بنُ السري بن سهل الزَّجَّاج، مصنِّفُ كتاب \"معاني القرآن\" و\"الاشتقاق\" و\"القوافي\" و\"العَروض\" و\"فعلتُ وأفعلتُ\" ومختصرًا في النحو وغير ذلك، وقد كان أوَّل أمرِه يَخرِطُ الزُّجَاج فأحَبَّ عِلمَ النَّحوِ، فذهب إلى المبَرِّد، وكان يعطي المُبَرِّدَ كلَّ يومٍ دِرهمًا، ثم استغنى الزَّجَّاجُ وكثُرَ مالُه ولم يقطَعْ عن المبَرِّدْ ذلك الدِّرهَم ح"},{"id":1066,"era":"c4","t":"وفاة ابن خزيمة صاحب الصحيح .","s":"هو الإمامُ الحافظُ الحُجَّة الفقيهُ، شيخُ الإسلام، محمدُ بنُ إسحاقَ بنِ خُزيمة بن المغيرة بن صالح بن بكر السلمي النَّيسابوري، الشافعي، الملقَّب بإمامِ الأئمَّة أبو بكر بنُ خُزيمة، صاحِبُ التصانيفِ. ولد: سنة 223. مولى مُحسِن بن مزاحم، عُنِيَ في حداثته بالحديثِ والفِقهِ، حتى صار يُضرَبُ به المثَلُ في سعة العلم والإتقان. كان بحرًا من بحور العِلمِ، طاف البلادَ ورحل إلى الآفاقِ في الحديثِ وطلب العلم، ف"},{"id":1067,"era":"c4","t":"استيلاء ابن أبي الساج على مدينة الري .","s":"سار يوسُفُ بنُ أبي الساج من أذربيجان إلى الرَّيِّ، فحاربه أحمدُ بن عليٍّ أخو صعلوك، فانهزم أصحابُ أحمد وقُتِلَ هو في المعركة، وأنفذ رأسَه إلى بغداد؛ وكان أحمدُ بن عليّ قد فارق أخاه صعلوكًا، وسار إلى المقتَدِر فأُقطِعَ الريِّ، ثمّ عصى، وهادن ماكان بنَ كالي وأولاد الحسن بن علي الأطروش، وهم بطبرستان، وجُرجان، وفارق طاعةَ المقتَدِر وعصى عليه، ووصل رأسُه إلى بغداد، وكان ابنُ الفرات يقعُ في نصر الحاجب، "},{"id":1068,"era":"c4","t":"القرامطة يقطعون طريق العائدين من الحج .","s":"سار أبو طاهر سليمان القرمطيُّ إلى الهَبِير في عسكرٍ عظيم ليلقى الحاجَّ في رجوعِهم من مكَّة، فأوقع بقافلةٍ تقدَّمت معظمَ الحاجِّ، وكان فيها خلقٌ كثيرٌ مِن أهل بغدادَ وغيرهم، فنهَبَهم، واتَّصل الخبر بباقي الحاجِّ وهم بفَيد، فأقاموا بها حتَّى فني زادُهم، فارتحلوا مسرعينَ، وكان أبو الهيجاء بن حَمدان قد أشار عليهم بالعَودِ إلى وادي القُرى، وأنَّهم لا يقيمون بفَيد، فاستطالوا الطريقَ، ولم يَقبَلوا منه، ف"},{"id":1069,"era":"c4","t":"دخول القرامطة الكوفة .","s":"دخل أبو طاهر القرمطيُّ الكوفةَ، وكان سببُ ذلك أنَّ أبا طاهر أطلقَ مَن كان عنده من الأسرى الذين كان أسَرَهم من الحُجَّاج، وفيهم ابنُ حمدان وغيره، وأرسل إلى المقتَدِر يطلُبُ البصرة والأهواز، فلم يجِبْه إلى ذلك، فسار من هَجَر يريد الحاجَّ، وكان جعفرُ بن ورقاء الشيبانيُّ متقلِّدًا أعمالَ الكوفة وطريق مكَّة، فلمَّا سار الحُجَّاج من بغداد سار جعفر بين أيديهم خوفًا من أبي طاهر، ومعه ألف رجلٍ من بني شيبان"},{"id":1070,"era":"c4","t":"القبض على الوزير ابن الفرات وأهله ومصادرة أموالهم\n  .","s":"لَمَّا رأى المحسِنُ ابن الوزير ابن الفرات انحلالَ أمورهم، أخذَ كلَّ مَن كان محبوسًا عنده من المصادَرينَ، فقتَلَهم؛ لأنَّه كان قد أخذ منهم أموالًا جليلةً، ولم يوصِلْها إلى المقتَدِر، فخاف أن يقرُّوا عليه. فكَثُر الإرجافُ على ابن الفرات، فكتب ابنُ الفراتِ إلى المقتَدِر يُعَرِّفُه ذلك، وأنَّ النَّاسَ إنَّما عادَوه لنُصحِه وشفَقتِه، وأخذ حقوقه منهم، فأنفذ المقتَدِرُ إليه يُسَكِّنُه ويطَيِّبُ قَلبَه, ث"},{"id":1071,"era":"c4","t":"بعض غزوات الناصر بالأندلس .","s":"غزاةُ أمير الأندلس الناصر إلى دار الحرب، وهي الغزوةُ المعروفة ببنبلونة، حيثُ بلغ مدينة بنبلونة، فوجدها خاليةً مُقفِرةً، فدخلها وجال بنَفسِه عليها، وأمَرَ بهدمِ جميعِ بنيانها، وتخريبِ كنيسة الكفَرة بها، التي كانت بيعتُهم موضِعَ نُسُكِهم، حتى لقد جُعِلَت قاعًا صفصفًا، ثم ارتحل منها إلى محلَّةٍ بقرية منيير؛ ثم تنقَّل إلى محلَّة بدى شره المجاورة لشنت اشتبين؛ وكان موضع \"استراح\" العِلْج شانجة، ثم تنقَّل"},{"id":1072,"era":"c4","t":"ظهور زعيم الإسماعيلية في الكوفة .","s":"ظهر في الكوفةِ رجلٌ ادَّعى أنه محمَّد بن إسماعيل بن جعفر بن محمَّد بن عليِّ بن الحسين بن عليِّ بن أبي طالب، وهو رئيسُ الإسماعيليَّة، وجمع جمعًا عظيمًا من الأعرابِ وأهل السواد، واستفحل أمرُه، فسُيِّرَ إليه جيشٌ من بغداد، فقاتلوه، فظَفِروا به وانهزم، وقُتِلَ كثيرٌ مِن أصحابِه."},{"id":1073,"era":"c4","t":"فتوحات جيوش المسلمين في صقلية .","s":"سار جيشُ صقلَّيةَ مع أميرهم سالمِ بنِ راشد وأرسل إليهم المهديُّ جيشًا من إفريقيَّة، فسار إلى أرضِ انكبردة، ففتحوا غيرانَ وأبرجة، وغَنِموا غنائِمَ كثيرةً، وعاد جيشُ صقلِّية، وساروا إلى أرض قلوريةَ، وقصدوا مدينةَ طارنت، فحصروها وفتحوها بالسَّيفِ في شهر رمضان ووصَلوا إلى مدينة أدرنت، فحصروها، وخرَّبوا منازِلَها، فأصاب المسلمينَ مرَضٌ شديدٌ كبيرٌ، فعادُوا ولم يزَلْ أهل صقلِّية يُغيرونَ على ما بأيدي ال"},{"id":1074,"era":"c4","t":"غزو المسلمين مدينة إلبيرة في الأندلس .","s":"كانت غزاةُ أمير الأندلسِ النَّاصِرِ إلى كورة إلبيرة، ومنازلتُه حصنَ اشتين، واستصلاحُه الأحوالَ بكورة جيان وما والاها؛ فبرزَ لهذه الغزاة يومَ الخميس لإحدى عشرة ليلة خلت من المحرَّم، وبقي في هذه الغزاة خمسينَ يومًا."},{"id":1075,"era":"c4","t":"اجتماع الرافضة في مسجد براثي للنَّيْلِ من الصحابة .","s":"بلغ الخليفةُ المُقتَدِر أنَّ جماعةً مِن الرَّافضة يجتَمِعونَ في مسجدِ براثي فينالونَ مِن الصحابةِ ولا يُصَلُّونَ الجمُعةَ، ويكاتبونَ القرامِطةَ ويَدْعونَ إلى محمد بن إسماعيل الذي ظهرَ بين الكوفة وبغداد، ويدَّعونَ أنَّه المهدي، ويتبَرَّؤون من المقتَدِر وممَّن تَبِعَه، فأمر بالاحتياطِ عليهم واستفتى العلماءَ بالمسجد فأفتَوا بأنَّه مَسجِدُ ضِرارٍ، فضُرِبَ مَن قُدِرَ عليه منهم الضَّربَ المُبَرِّحَ، ونو"},{"id":1076,"era":"c4","t":"دخول الروم ثغور المسلمين .","s":"كتب مَلِكُ الروم الدُّمُستق إلى أهلِ الثُّغورِ يأمُرُهم بحَملِ الخَراجِ إليه، فإن فعلوا، وإلَّا قصَدَهم فقتل الرِّجالَ، وسبى الذريَّة، وقال: إنَّني صحَّ عندي ضَعفُ وُلاتِكم، فلم يفعلوا ذلك، ثمَّ في ربيع الآخر، خرجت الرومُ إلى ملطيَّة وما يليها مع الدُّمُستُق، ومعه مليح الأرمنيُّ صاحِبُ الدُّروب، فنزلوا على ملطيَّة، وحصروها، فصبر أهلُها، ففتح الروم أبوابًا من الربضِ، فدخلوا، فقاتَلَهم أهلُه، وأخرجو"},{"id":1077,"era":"c4","t":"امتناع الكثير من أداء الحج خوفاً من القرامطة .","s":"اقتربت القرامطةُ من مكَّةَ المُكَرَّمة، فهرب كثيرٌ من أهلِها إلى الطائف، وامتنع في هذا العامِ مِن الحَجِّ أهلُ بغداد والموصِل، ورجع حُجَّاج خراسان خوفًا من القرامطة، حيث وصلهم نبأُ اقترابهم من مكة."},{"id":1078,"era":"c4","t":"استيلاء السامانيّة على بلاد الرَّيّ .","s":"لَمَّا استدعى المقتَدِرُ يوسفَ بنَ أبي الساج إلى واسط كتبَ إلى السعيدِ نصرِ بنِ أحمد السامانيِّ بولاية الرَّيِّ، وأمَرَه بقَصدِها، وأخذها من فاتك، غلامِ يوسُف، فسار نصر بن أحمد إليها، أوائِلَ هذا العام، فوصل إلى جبلِ قارن، فمنعه أبو نصرٍ الطبريُّ من العبورِ، فأقام هناك، فراسله وبذل له ثلاثين ألف دينارٍ حتَّى مكَّنَه من العبور، فسار حتَّى قارب الرَّيَّ، فخرج فاتك عنها، واستولى نصر بن أحمد عليها في "},{"id":1079,"era":"c4","t":"الحرب بين ابن حمدان أمير الموصل والأكراد والعرب .","s":"أفسد الأكرادُ والعرَبُ بأرض المَوصِل وطريقِ خُراسان، وكان عبدُ الله بن حَمدان يتولَّى الجميعَ وهو ببغداد، وابنُه ناصر الدولة بالموصِل، فكتب إليه أبوه يأمُرُه بجمع الرجال، والانحدارِ إلى تكريت، ففعل وسارَ إليها، فوصل إليها في رمضانَ، واجتمعَ بأبيه، وأحضر العَرَب، وطالبهم بما أحدثوا في عمَلِه بعد أن قتَلَ منهم، ونكَّلَ ببعضهم، فردُّوا على الناس شيئًا كثيرًا، ورحل بهم إلى شَهرزور، فوطئَ الأكراد الجلا"},{"id":1080,"era":"c4","t":"قتل سليمان بن عمر بن حفصون بالأندلس .","s":"بعد مَقتَل عُمَرَ بنِ حَفصون استلم ابنُه سليمان قيادةَ الثَّورةِ، وبقي على سيرةِ أبيه، ثم قُتِلَ في هذه السنة, كان سليمانُ قد ركب وخرج عن مدينة ببشتر مركزِ الثَّورةِ ومَقَرِّها. معارِضًا لبعض الحشَمِ المجاورينَ له من العسكر، فتبادرت إليه الخيلُ مِن الجهة التي كان فيها عبدُ الحميد الوزير، فصُرِعَ سليمانُ عن فرسِه، فاحتزَّ رأسَه سعيدُ بن بعلي العريف المعروف بالشفة، وقطعت يداه ورجلاه، وبعث الوزيرُ عب"},{"id":1081,"era":"c4","t":"دخول الروم سيمساط ثغور المسلمين بالشام .","s":"هاجمت الرومُ المسلمينَ، فقصدوا الثُّغورَ، ودخلوا سُمَيساط- وهي مِن ثغور الجزيرةِ بالشام- وغَنِموا جميعَ ما فيها من مالٍ وسلاحٍ وغيرِ ذلك، وضربوا في الجامِعِ بالناقوسِ أوقاتَ الصَّلواتِ، ثمَّ إنَّ المسلمينَ خرجوا في أثَرِ الرُّوم وقاتلوهم وغَنِموا منهم غنيمةً عظيمةً، فأمر المقتَدِرُ بالله بتجهيزِ العساكِرِ مع مؤنسٍ المظفَّر، وخلع المقتَدِر عليه في ربيع الآخر؛ ليسيرَ إليهم."},{"id":1082,"era":"c4","t":"القتال بين أهل طرسوس والروم .","s":"خرجت سَريَّةٌ من طرسوسَ إلى بلادِ الرومِ، فوقع عليها العدوُّ، فاقتتلوا فاستظهَرَ الرُّومُ وأسَروا من المُسلمين أربعمائة رجل، فقُتِلوا صبرًا، وفيها سار الدُّمُسْتُق في جيشٍ عظيمٍ من الروم إلى مدينة دَبيل، وفيها نصر السُّبكيُّ في عسكرٍ يحميها، وكان مع الدُّمُستُق دَبَّابات ومجانيقُ معه مِزراقٌ يزرقُ بالنَّارِ عدَّةَ اثنى عشر رجلًا، فلا يَقِرُّ بين يديه أحدٌ من شدَّةِ نارِه واتِّصاله، فكان من أشدِّ ش"},{"id":1083,"era":"c4","t":"ظهور الديلم في الري والجبل .","s":"ظهر الديلمُ على الريِّ والجبالِ، وأوَّلُ من غلب منهم لنكى بن النعمان، فقَتَل من أهلِ الجبال مقتلةً عظيمةً وذبح الأطفالَ في المهدِ، ثم غلب على قزوين أسفار بن شيرويه وألزم أهلَها مالًا، وكان له قائدٌ يُسمَّى مرداويج بن زيار، فوثب على أسفار المذكور وقتَلَه وملك البلاد مكانَه، وأساء السيرةَ بأصبهان، وجلس على سريرٍ مِن ذهَبٍ، وقال: أنا سليمانُ بن داودَ، وهؤلاء الشياطينُ أعواني، وكان مع هذا سيئَ السيرةِ"},{"id":1084,"era":"c4","t":"مسير جيش المهدي إلى المغرب .","s":"سيَّرَ المهديُّ العُبَيديُّ- صاحب إفريقيَّة- ابنَه أبا القاسم من المهديَّة إلى المغرب في جيشٍ كثير، في صفر؛ لسبب محمَّد بن خرز الزناتيِّ، وذلك أنَّه ظفِرَ بعسكر من كتامة، فقتل منهم خلقًا كثيرًا، فعَظُم ذلك على المهديِّ، فسيَّرَ ولده، فلمَّا خرج تفرَّقَ الأعداءُ، وسار حتَّى وصل إلى ما وراء تاهَرت، فلمَّا عاد من سفرتِه هذه خطَّ برُمحِه في الأرض صفةَ مدينةٍ، وسمَّاها المحمَّدية، وهي المسيلة، وكانت خط"},{"id":1085,"era":"c4","t":"موقعة بين أبي الساج وأبي طاهر القرمطي بالكوفة .","s":"كانت بين يوسُفَ بنِ أبي الساج وبين أبي طاهرٍ القرمطيِّ عند الكوفة موقعةٌ، فسبقه إليها أبو طاهر فحال بينه وبينها، فكتب إليه يوسُفُ بنُ أبي الساج: اسمَعْ وأطِعْ، وإلا فاستعِدَّ للقتالِ يوم السبت تاسِعَ شوال منها، فكتب: هلُمَّ، فسار إليه، فلما تراءى الجمعانِ استقَلَّ يوسف جيشَ القرمطي، وكان مع يوسُفَ بن أبي الساج عشرونَ ألفًا، ومع القرمطي ألفُ فارس وخمسمائة رجل. فقال يوسف: وما قيمةُ هؤلاء الكلابِ؟ وأ"},{"id":1086,"era":"c4","t":"محاصرة حفص بن عمر بن حفصون وفتح مدينة ببشتر .","s":"كان حفصٌ قد استلم مكانَ أخيه سليمان بعد أن قُتِلَ، فقام في هذه السنةِ النَّاصِرُ أميرُ الأندلس بغزوِه في ببشتر جنوب إسبانيا، وهو متحصِّنٌ فيها، ولَمَّا اشتدت المحاصَرةُ على حفص بن عمر بن حفصون بمدينةِ ببشتر، وأحيطَ به بالبنيانِ عليه مِن كُلِّ جانبٍ، ورأى من الجِدِّ والعَزمِ في أمرِه ما عَلِمَ أنْ لَا بقاءَ له معه في الجبل الذي تعلَّقَ فيه، كتب إلى أمير المؤمنين الناصرِ، يسأله تأمينَه والصفحَ عنه، "},{"id":1087,"era":"c4","t":"غزو الروم .","s":"عاد ثمل الخادِمُ إلى طرسوس من الغَزاةِ الصائفةِ سالِمًا هو ومَن معه فلَقُوا جمعًا كثيرًا من الرومِ، فاقتتلوا فانتصر المُسلِمونَ عليهم وقتَلوا من الرومِ كثيرًا، وغَنِموا ما لا يُحصى، وكان من جملةِ ما غَنِموا أنَّهم ذبحوا من الغَنَمِ في بلاد الروم ثلاثمائة ألف رأس، سوى ما سلِمَ معهم، ولقيهم رجلٌ يُعرَفُ بابن الضحَّاك، وهو من رؤساءِ الأكراد، وكان له حصنٌ يُعرَفُ بالجعفري، فارتدَّ عن الإسلام وصار إلى "},{"id":1088,"era":"c4","t":"القرامطة يدعون للفاطميين ويعيثون الفساد في الأرض .","s":"عاث أبو طاهرٍ سُلَيمانُ بنُ أبي سعيد الجَنابي القرمطي في الأرضِ فسادًا، وحاصَرَ الرحبةَ فدخلها قهرًا وقتل مِن أهلِها خَلقًا، وطلب منه أهلُ قرقيسيا الأمانَ فأمَّنَهم، وبعث سراياه إلى ما حولَها من الأعرابِ، فقتل منهم خلقًا، حتى صار الناسُ إذا سمعوا بذِكرِه يَهربونَ مِن سماع اسمه، وقدَّرَ على الأعرابِ إمارة يحملونَها إلى هجَرَ في كل سنة، عن كل رأسٍ ديناران، وعاث في نواحي الموصِل فسادًا، وفي سنجار ونو"},{"id":1089,"era":"c4","t":"ابتداء حال بني البريدي في الأهواز .","s":"لَمَّا وزَر أبو عليِّ بنُ مقلة بسعايةِ نصر الحاجب أبي عبدالله بن البريدي وبذل له عشرينَ ألف دينار على ذلك، فقلَّدَ أبا عبد اللهِ بنَ البريديِّ الأهوازَ جميعَها، سوى السُّوسِ وجُنْدَيسابور، وقلَّدَ أخاه أبا الحُسَين الفراتيَّة، وقلَّدَ أخاهما أبا يوسف الخاصَّةَ والأسافل، على أن يكون المالُ في ذمَّةِ أبي أيُّوب السمسار إلى أن يتصرَّفوا في الأعمال، وكتب أبو عليِّ بنُ مقلة إلى أبي عبد الله في القبضِ ع"},{"id":1090,"era":"c4","t":"عبدالرحمن الناصر يلقب نفسه (أمير المؤمنين) بالأندلس .","s":"رأى النَّاصِرُ أميرُ الأندلس أن تكونَ الدَّعوةُ له في مخاطباته والمُخاطَباتِ له في جميعِ ما يَجري ذِكرُه فيه، بأميرِ المؤمنين، فعَهِدَ إلى أحمد بن بقيٍّ القاضي صاحِبِ الصلاة بقُرطبةَ بأن تكون الخُطبةُ يوم الجمعة مُستهَلَّ ذي الحجة بذلك. ونَفَذت الكتبُ إلى العمَّال فيه، ونُسخة الرسالة النافذة في ذلك: بسم اللهِ الرَّحمنِ الرحيم. أمَّا بعدُ؛ فإنَّا أحقُّ من استوفى حَقَّه، وأجدرُ من استكمَلَ حَظَّه، و"},{"id":1091,"era":"c4","t":"عودة المقتدر بالله إلى الخلافة بعد أن تنازل لأخيه محمد القاهر .","s":"اشتَدَّت الوحشةُ بين مُؤنِسٍ الخادمِ والمُقتَدِر بالله، وتفاقَمَ الحالُ وآل إلى أن اجتَمَعوا على خَلعِ المُقتَدِر وتولية القاهِرِ محمَّد بن المعتضد، فبايعوه بالخلافةِ وسَلَّموا عليه بها، ولقَّبوه القاهر بالله، وذلك ليلة السبت النصف من المحرم، وقَلَّدَ عليَّ بنَ مقلة وزارته، وولى نازوك الحُجُوبة مضافًا إلى ما بيده من الشُّرطة، وألزم المقتَدِر بأن كتب على نفسِه كتابًا بالخَلعِ مِن الخلافة، وأشهد على"},{"id":1092,"era":"c4","t":"الناصر أمير الأندلس يغزو مدينة بطليوس .","s":"غزا الناصِرُ أميرُ الأندلس مدينةَ بَطليوس؛ لمحاربة أهلِها وأميرِهم ابن مروان الجليقي؛ فلمَّا أخَذَهم الحِصارُ، وطاوَلَتهم الحربُ، وفَنِيَ رجالُهم، واستُبيحَت نَعَمُهم، وقُطِعَت ثَمراتُهم، ورأوا عزمًا لا فترةَ فيه، وجِدًّا لا بقاءَ لهم عليه- استأمنوا الناصِرَ، وعاذُوا بصَفحِه، فأوسعهم ما أوسَعَ أمثالَهم قبلهم. واستنزل ابنَ مروان الجليقي وأهلَه، وذوي الشوكة مِن صَحْبِه، وأسكَنَهم قرطبة، وألحقهم في ا"},{"id":1093,"era":"c4","t":"القرامطة يسرقون الحجر الأسود ويعيثون الفساد في مكة .","s":"لم يَشعُر الحُجَّاجُ في هذا العامِ إلَّا وأبو طاهرٍ سُلَيمانُ الجنابي القرمطي- لعنه الله-  قد خرج عليهم في جماعتِه يومَ الترويةِ، فانتهب أموالَهم واستباح قتالَهم، فقتَلَ في رحابِ مَكَّة وشعابِها وفي المسجِدِ الحرامِ وفي جوفِ الكعبةِ مِن الحُجَّاجِ خَلقًا كثيرًا، وجلس أميرُهم أبو طاهرٍ- لعنه الله- على باب الكعبة، والرجالُ تُصرَعُ حوله، والسيوفُ تَعمَلُ في الناس في المسجدِ الحرام في الشَّهرِ الحرام "},{"id":1094,"era":"c4","t":"نفي الرجالة من بغداد .","s":"طرد الخليفةُ الرَّجَّالةَ وهم المُشاة من الجيش الذين كانوا بدارِ الخلافةِ عن بغداد، وذلك أنَّه لَمَّا رَدَّ المُقتَدِر إلى الخلافة شَرَعوا ينفسونَ بكلامٍ كثيرٍ عليه، ويقولون: من أعان ظالِمًا سَلَّطَه اللهُ عليه، ومن أصعد الحِمارَ على السَّطحِ يقدِرُ أن يُطيحَه، فأمر بإخراجِهم ونفيِهم عن بغداد، ومن أقام منهم عُوقِبَ، فأُحرِقَت دورٌ كثيرةٌ مِن قراباتِهم، واحتَرَق بعضُ نسائهم وأولادهم، فخرجوا منها في"},{"id":1095,"era":"c4","t":"بداية قيام دولة بني حمدان بالموصل .","s":"يعودُ أصلُ الحمدانيِّينَ على بني تغلبَ، وكان من القادة البارزينَ منهم الحُسَينُ بنُ حمدان الذي قاد حروبًا ضِدَّ القرامطة، وكان المقتَدِرُ ولَّاه قمَّ وقاشان، وأما أبو الهيجاءِ عبدالله بن حمدان فكان مع المقتَدِر إلى أن قُتِلَ يوم أن عُزِلَ المقتدر من الخلافة، وكان الحسَنُ بن عبدالله بن حمدان على الموصِل، ثم عُزِلَ ووليها عمَّاه سعيد ونصر ابنا حمدان، ووليَ ناصِرُ الدولة ديارَ ربيعة، ونَصِيبين، وسِنج"},{"id":1096,"era":"c4","t":"الناصر أمير الأندلس يغزو مدينة طُلَيطلة .","s":"بعد أن افتتَحَ أميرُ المُؤمِنينَ النَّاصِرُ بطليوس في هذا العامِ عزَمَ على غزو طُلَيطلة في جيشٍ كثيرٍ وعَدَدٍ جمٍّ، فأخرج معهم أهلَ الثِّقةِ مِن خِدمتِه والأمانةِ مِن فُقَهاءِ مِصْرِه إلى أهل طُلَيطلة، مُعذِرًا إليهم، داعيًا لهم إلى الطاعة والدخولِ فيما صارت إليه الجماعةُ، إذ كانوا لا يؤدُّون جبايةً، ولا يلتَزِمون طاعةً، ولا يتناهون عن مُنكَرٍ ولا معصيةٍ، وأمَرَهم بمحاصرتها واحتلالِها، حتى يلحَقَ "},{"id":1097,"era":"c4","t":"جيش العباسيين يصحب الحجيج إلى مكة خوفًا من القرامطة .","s":"في المحرم دخل الحَجيجُ بغداد، وقد خرج مؤنِسٌ الخادِمُ إلى الحجِّ فيها في جيشٍ كثيفٍ؛ خوفًا من القرامِطةِ، ففرح المسلمون بذلك وزُيِّنَت بغداد يومئذٍ وضُرِبَت الخيام والقِباب لمؤنسٍ الخادم، وقد بلغ مؤنسًا في أثناء الطريق أنَّ القرامطةَ أمامه، فعدل بالنَّاسِ عن الجادة، وأخذ بهم في شعابٍ وأوديةٍ أيَّامًا."},{"id":1098,"era":"c4","t":"احتلال ملك الديلم مرداويج أصبهان وغيرها .","s":"استولى مرداويج مَلِكُ الدَّيلم على بلدِ الجبَلِ والرَّيِّ وغيرِهما، وأقبلت الدَّيلمُ إليه من كلِّ ناحية لبَذلِه وإحسانِه إلى جُندِه، فعَظُمَت جيوشُه، وكَثُرَت عساكِرُه، وكثُرَ الخراجُ عليه، فلم يَكفِه ما في يده، ففرَّق نوَّابَه في النواحي المجاورةِ له، فكان ممَّن سيَّرَه إلى همَذان ابنُ أختٍ له في جيشٍ كثير، وكان بها أبو عبدِ الله محمَّدُ بن خلف في عسكرِ الخليفة، فتحاربوا حروبًا كثيرة، وأعان أهلُ "},{"id":1099,"era":"c4","t":"عبدالرحمن الناصر يهدد الدولة العبيدية (الفاطمية) بأفريقيا .","s":"كاتَبَ موسى بن أبي العافية- صاحبُ المغرب- الأميرَ الناصر، ورَغِبَ في موالاته، والدخولِ في طاعته، وأن يستميلَ له أهواءَ أهل المغرب المجاورينَ له، فتقبله أحسَنَ قَبولٍ، وأمَدَّه بالخِلَعِ والأموال، وقوَّى يده على ما كان يحاوِلُه من حربِ ابنِ أبي العيش وغيره. فظهر أمرُ موسى من ذلك الوقت في المغرب، وتجمَّعَ له كثيرٌ من قبائل البربر، وتغلَّب على مدينة جراوة، وأخرج عنها الحسَنَ بنَ أبي العيش بن إدريس ال"},{"id":1100,"era":"c4","t":"القتال مع الروم .","s":"أوقع ثمل متولي طرسوس بالرُّومِ وَقعةً عظيمةً، قتل منهم خلقًا كثيرًا وأسرَ نحوًا مِن ثلاثةِ آلاف، وغَنِمَ من الذهَبِ والفِضَّة والديباج شيئًا كثيرًا جِدًّا، ثم أوقع بهم مَرَّةً ثانيةً كذلك، وكتب ابنُ الديراني الأرمني إلى الرومِ يحُثُّهم على الدُّخولِ إلى بلادِ الإسلامِ ووعَدَهم النَّصرَ منه والإعانةَ، فدخلوا في جحافِلَ عظيمةٍ كثيرةٍ جِدًّا، وانضاف إليهم الأرمنيُّ فركب إليهم مُفلِحٌ غلامُ يوسُفَ بنِ"},{"id":1101,"era":"c4","t":"الناصر أمير الأندلس يغزو مدينة طُلَيطلة للمرة الثانية .","s":"غزا الناصِرُ مدينة طُلَيطلة غَزاتَه الثانيةَ التي فُتِحَ فيها عليه، وكان أهل طليطلة لَمَّا أخذهم الحصار، واشتَدَّ عليهم التَّضييق، ولازمهم القُوَّادُ، استنجدوا بالمشركين، ورَجَوا نصرهم لهم، فلم يغنوا عنهم فتيلًا، ولا كشَفوا عنهم عذابًا، ولا جَلَبوا إليهم إلَّا خِزيًا وهوانا. وخرج القُوَّادُ المُحاصِرون لهم إلى الكَفَرة، فهزموهم وفَرَّقوا جموعهم، وانصرفوا مُوَلِّينَ على أعقابهم، خاذلينَ لِمن انتصر "},{"id":1102,"era":"c4","t":"اغتيال الخليفة العباسي المقتدر بالله وتولي أخيه محمد القاهر الخلافة .","s":"لَمَّا تزايَدَت الوحشةُ بين مؤنسٍ صاحِبِ الجيشِ، والخليفةِ المُقتَدر وزاد ذلك انفرادُ الوزيرِ الحسين بن القاسم بأشياءَ أغاظت مؤنِسًا، الذي عزم على المسيرِ إلى الموصِلِ، فسار إليها وحارب فيها بني حمدانَ وهزمهم، فاستمال نحوه كثيرًا مِن الجند والأعراب وغيرهم، وجمع العساكِرَ وسار إلى المُقتَدِر على أن يُجرِيَ عليهم الأرزاقَ وإلَّا قاتلوه، وقد بعث بين يديه الطلائِعَ، حتى جاء فنزل بباب الشماسية ببغداد، "},{"id":1103,"era":"c4","t":"وفاة الخليفة العباسي المقتدر بالله .","s":"هو أبو الفضلِ جَعفرُ بنُ أحمدَ المعتَضِد بالله أحمد بن أبي أحمد الموفَّق بن جعفر المتوكل على الله بن محمد المعتصم بن هارون الرشيد، أمير المؤمنين العبَّاسي، ولد في رمضان سنة 282، وأمُّه أمُّ ولَد اسمها شغب، بويعَ له بالخلافةِ بعد أخيه المُكتفي في ذي القَعدة، سنة 295، وهو يومئذٍ ابنُ ثلاث عشرة سنة وشهر وأيام. وما وليَ أحدٌ قبله أصغَرُ منه، فانخرم نظامُ الإمامة في أيَّامِه، وصَغُرَ منصِبُ الخلافة؛ ول"},{"id":1104,"era":"c4","t":"القاهر بالله يأمر بمَنعِ بَيعِ الخَمرِ وتحريمِ القِيانِ وبيعِ المُغَنِّيات .","s":"أمر القاهِرُ بالله بمَنعِ بَيعِ الخَمرِ وسائِرِ الأنبذة، وتحريمِ القِيانِ وبيعِ المُغَنِّيات من الجواري إلَّا على أنهنَّ ساذجاتٍ- يعني حتى لا يُبَعْنَ بثمنٍ غالٍ للغناء- وقَبَضَ على المُغَنِّينَ وكسَرَ آلاتِ اللَّهوِ ونفى المخانيثَ، ومع هذا كلِّه كان هو مُغرمًا بسماعِ الغناءِ وتَعاطي الشُّربِ. قال ابن الأثير: \" ثم وضع القاهِرُ من يشتري له كُلَّ حاذقةٍ في صنعةِ الغِناءِ، فاشترى منهنَّ ما أراد بأرخَ"},{"id":1105,"era":"c4","t":"ظهور الدولة البويهية .","s":"كان الإخوةُ الثلاثة (عماد الدولة) أبو الحسَن علي، و(رُكْن الدولة) أبو علي الحسَن، و(مُعِزُّ الدولة) أبو الحسين أحمد- أولادُ أبي شجاع بُوَيه بن قباخسرو فرس- من أحفاد الملك يزدجرد, وإنَّما قيل لهم الديالمة؛ لأنهم جاوروا الدَّيلم، وكانوا بين أظهُرِهم مُدَّةً، وقد كان أبوهم أبو شجاع بويه فقيرًا مُدقِعًا، يصطاد السَّمَك ويحتَطِبُ بنوه الحطَبَ على رؤوسهم، وهؤلاء الإخوة الثلاثة كانوا عند ملِكٍ يقال له ما"},{"id":1106,"era":"c4","t":"بداية أمر بني محتاج في خراسان .","s":"استعمل السعيدُ نصر الساماني أبا بكرٍ محمَّدَ بن المظفَّر بن محتاج على جيوشِ خراسان، وردَّ إليه تدبيرَ الأمور بنواحي خُراسان جميعها، وعاد إلى بخارى مقرِّ عِزِّه، وكرسيِّ مُلكِه، وكان سبب تقدُّم محمّد بن المظفَّر أنَّه كان يومًا عند السعيد، وهو يحادِثُه في بعض مهمَّاتِه خاليًا، فلَسَعَته عقربٌ في إحدى رجليه عدَّةَ لسعات، فلم يتحرَّكْ، ولم يَظهَرْ عليه أثَرُ ذلك، فلمَّا فرغ من حديثه، وعاد محمَّدٌ إلى"},{"id":1107,"era":"c4","t":"وفاة الشاعر المشهور ابن دريد .","s":"هو أبو بكر محمَّدُ بن الحسن بن دريد بن عتاهية الأزديُّ البصريُّ، عالِمٌ وشاعِرٌ وأديبٌ عربيٌّ، كان رأسًا في العربيَّةِ وأشعار العرَبِ, وله شعرٌ كثيرٌ وتصانيفُ مشهورة. ولِدَ سنة 223.كان يقالُ: \"ابن دريد أشعَرُ العُلَماء وأعلَمُ الشُّعَراء\", وكان أبوه وجيهًا من وجهاءِ البصرة، وقرأ ابنُ دريد على علمائِها وعلى عمه الحُسَين بن دريد، قال أحمد بن يوسف الأزرق: \"ما رأيتُ أحفَظَ مِن ابنِ دُرَيد. وما رأيتُه "},{"id":1108,"era":"c4","t":"وفاة محمّد بن يوسف بن مطر الفربري .","s":"تُوفِّيَ المحَدِّث الثِّقةُ العالم أبو عبدالله محمَّد بن يوسف بن مطر بن صالح بن بِشرٍ الفَرَبْريُّ، نِسبتُه إلى فَرَبْر: بفتح الفاء والراء وسكون الباء الموحدة وفي آخرها راء ثانية، وهي بلدةٌ على طرف جيحون ممَّا يلي بخارى. وُلِدَ سنة 231 راوي \"الجامِع الصحيح\" عن أبي عبد الله البخاري, سَمِعَه منه بِفَرَبْرَ مرتين؛ مرة سنة 248، ومرة سنة 253، وكان قد سمع \"الجامع الصحيح\" من البُخاري عشراتُ الألوفِ، فلم "},{"id":1109,"era":"c4","t":"وفاة أبي جعفر الطحاوي .","s":"هو أحمدُ بنُ محمَّدِ بنِ سلامة بن سلمة بن عبد الملك أبو جعفرٍ الأزدِيُّ الحجري المصريُّ الطحاوي، الفقيهُ الحنفيُّ، المحَدِّثُ الحافِظُ، أحدُ الأعلام، ولد سنة 239 بِطَحَا: قريةٍ مِن قُرى مِصرَ مِن ضواحي القاهرةِ بالوجه البحري، رحل إلى البلادِ، قال أبو إسحاق الشيرازي: انتهت إلى أبي جعفر رياسةُ أصحابِ أبي حنيفة بمصرَ، أخذ العلمَ عن أبي جعفرٍ أحمَدَ بن أبي عمران، وأبي حازم، وغيرهما، وكان إمامَ عَصرِه "},{"id":1110,"era":"c4","t":"طمع هارون بن غريب بالخلافة .","s":"لَمَّا خُلِعَ القاهِرُ ووَلِيَ الرَّاضي، طَمِعَ هارونُ بنُ غريبٍ في الخلافة؛ لكَونِه ابنَ خالِ المُقتَدِر، وكان نائبًا على ماه والكوفة والدينور وماسبذان، فدعا إلى نفسِه واتَّبَعه خلقٌ كثيرٌ مِن الجند والأمراء، وجبى الأموالَ واستفحل أمرُه، وقَوِيَت شوكتُه، وقصد بغداد فخرج إليه محمَّدُ بنُ ياقوت رأسُ الحَجَبةِ بجميع جندِ بغداد، فاقتَتَلوا فخرج في بعض الأيامِ هارونُ بنُ غريب يتقصَّدُ؛ لعَلَّه يعمَلُ "},{"id":1111,"era":"c4","t":"وفاة عبيدالله المهدي أول حاكم عبيدي (فاطمي) .","s":"هو سعيدُ بنُ حُسين بن أحمد بن محمَّد بن عبد الله بن عَمْرِو بن ميمون القدَّاح بن دَيصان الأهوازي. قال القاضي عبد الجَبَّار بن أحمد بن عبد الجبار البصري: \"اسمُ جَدِّ الخلفاء المصريِّين سعيدٌ، ويلقَّبُ بالمهديِّ\". المعروف بالمهديِّ أبو محمَّد عبيدالله، مؤسِّسُ الدولة الفاطمية العُبيدية الباطنيَّة في إفريقيا، كان أبوه يهوديًّا حدَّادًا بسَلَمية. زعم سعيدٌ هذا أنَّه ابنُ الحُسين بن محمد بن أحمد بن عبد"},{"id":1112,"era":"c4","t":"خلع الخليفة العباسي القاهر بالله وتولي الراضي بالله الخلافة .","s":"كان سببُ ذلك أنَّ الوزيرَ عليَّ بنَ مقلةَ كان قد هرب حين قُبِضَ على مؤنسٍ ومَن معه لإرادتِهم قتلَ القاهرِ بالله، وكان قد قَبَضَ عليهم وقتَلَهم إلَّا ابن مقلة فإنه هرب، فاختفى في داره، وكان يراسِلُ الجُندَ ويكاتبهم ويغريهم بالقاهرِ، ويخوِّفُهم سطوتَه وإقدامَه، وسرعةَ بطشِه، ويخبِرُهم بأنَّ القاهِرَ بالله قد أعدَّ لأكابرِ الأمراءِ أماكِنَ في دار الخلافة يسجنُهم فيها، ومهالك يُلقيهم فيها، كما فعل بفل"},{"id":1113,"era":"c4","t":"اغتيال مرداويج بن زياد أمير بلاد فارس .","s":"كان- قَبَّحَه الله- سيئَ السِّيرةِ والسَّريرة، يزعُمُ أنَّ روحَ سُلَيمانَ بنِ داود حلَّت فيه، وله سريرٌ من ذهب يجلِسُ عليه والأتراكُ بين يديه، ويزعُمُ أنَّهم الجِنُّ الذين سُخِّروا لسليمان بن داود، وكان يسيئ المعاملةَ لجُندِه ويحتَقِرُهم غايةَ الاحتقار، فما زال ذلك دأبَه حتى أمكنهم اللهُ منه فقتلوه شَرَّ قِتلةٍ في حمَّام، وكان الذي مالأَ على قتله غلامَه بجكم التركي، وكان رُكنُ الدَّولةِ بنُ بُوَيه"},{"id":1114,"era":"c4","t":"قيام الدولة الإخشيدية في مصر .","s":"وَلِيَ مِصرَ ثانيًا مِن قِبَل الخليفة الراضي بالله مُحمَّد بن طغج بن جف الفرغاني على الصَّلاةِ والخراج بعد عزلِ الأمير أحمد بن كيغلغ عنها، بعد أمور وقعت. دخل محمَّدُ بنُ طغج مصر أميرًا عليها بعد أن سلَّمَ الأميرُ أحمد بن كيغلغ في يوم الخميس لسِتٍّ بقِينَ مِن شهرِ رمضان وأقَرَّ على شرطته سعيدَ بنَ عثمانَ ثمَّ ورد عليه بالدِّيار المصرية أبو الفتح الفضلُ بنُ جعفر بن محمد بالخِلَع من الخليفةِ الراضي ب"},{"id":1115,"era":"c4","t":"وفاة نفطويه النحوي .","s":"هو إبراهيمُ بنُ مُحمَّد بن عرفة الأزدي، إمامُ النَّحوِ، كان فقيهًا حافظًا، جالس الملوكَ والوزراء، أتقن حفظَ السِّيَر، سُمِّيَ نِفطَوَيه؛ لأنَّه كان دميمَ الِخلقةِ شديدَ السُّمرةِ، ولأنَّه كان يؤيِّدُ مَذهَبَ سِيبويهِ فلَقَّبوه نفطويه، له مصنَّفاتٌ؛ منها: غريب القرآن، وأمثال القرآن، والرد على من قال بخَلْقِ القرآن، وغيرها، توفِّيَ عن 79 عامًا في بغداد، وصلى عليه البربهاري إمامُ الحنابلةِ في وَقتِه."},{"id":1116,"era":"c4","t":"فتنة الحنابلة في بغداد .","s":"عَظُمَ أمرُ الحَنابلةِ ببغداد، وقَوِيَت شوكَتُهم، وصاروا يكبِسونَ دُورَ القوَّادِ والعامَّة، وإن وَجَدوا نبيذًا أراقوه، وإن وجدوا مغنِّيةً ضربوها وكسروا آلةَ الغناء، واعترضوا في البيعِ والشِّراءِ، وفي مشيِ الرِّجالِ مع الصِّبيان, كان البربهاري شيخُ الحنابلةِ في عَصرِه مُقيمًا في بغداد, وله فضلٌ كبيرٌ في الدعوةِ إلى الرجوع إلى منهجِ السَّلَفِ في العقيدة وإنكارِ البِدَع والخُرافات، وله مواقِفُ شديدة"},{"id":1117,"era":"c4","t":"ضعف الخلافة ببغداد واستحواذ ابن رائق بالأمور\nواستقلال النواب بالأطراف .","s":"ضَعُفَ أمرُ الخلافة جِدًّا، وبعث الراضي باللهِ إلى محمَّد بن رائق- وكان بواسط- يدعوه إليه ليولِّيَه إمرةَ الأمراءِ ببغداد، وأمْرَ الخراجِ والمغلِّ في جميع البلاد والدواوين، وأمر أن يَخطُبَ له على جميعِ المنابِرِ، وأنفذ إليه بالخِلَع، فقَدِمَ ابنُ رائق بغداد على ذلك كُلِّه، ومعه الأميرُ بجكم التركي غلامُ مرداويج، وهو الذي ساعد على قتل مرداويج، واستحوذ ابنُ رائق على أموالِ العراقِ بكَمالِه، ونقل أمو"},{"id":1118,"era":"c4","t":"وفاة أبي الحسن الأشعري .","s":"هو عليُّ بنُ إسماعيلَ بنِ إسحاق بنِ سالم بن إسماعيلَ بنِ عبد الله بن موسى ابنِ أمير البصرةِ بلال بن أبي بُردة ابن صاحبِ رَسولِ اللهِ- صلَّى الله عليه وسلَّم- أبي موسى عبد الله بن قيس بن حضار الأشعري، اليماني، البصري. أبو الحسَن الأشعريُّ المتكلِّم المشهور، وُلِدَ بالبصرة سنة 260، وقيل: ولد سنة سبعين. كان عجبًا في الذَّكاء وقُوَّةِ الفَهمِ. يقولُ الذهبي: \"لأبي الحسن ذكاءٌ مُفرِطٌ، وتبحُّرٌ في العِل"},{"id":1119,"era":"c4","t":"استيلاء ماكان بن كالي على مدينة جُرجان .","s":"في هذه السَّنةِ استولى ماكان بن كالي على جُرجان، وسبب ذلك أوَّلًا لَمَّا عاد ماكان من جرجان أقام بنَيسابور، وأقام بانجين بجُرجانَ، فلمَّا كان بعد ذلك خرج بانجين يلعَبُ بالكرة، فسقط عن دابَّتِه فوقع ميِّتًا، وبلغ خبَرُه ماكان بن كالي، وهو بنَيسابور، وكان قد استوحَشَ من عارض جيش خراسان، فاحتجَّ على محمَّد بن المظفَّر صاحب الجيش بخراسان بأنَّ بعض أصحابه قد هرب منه، وأنَّه قد يخرج في طَلَبِه، فأذِنَ ل"},{"id":1120,"era":"c4","t":"قتال بين الخليفة الراضي بالله وأبي عبد الله البريدي نائب الأهواز .","s":"خرج الخليفةُ الراضي وأميرُ الأمراءِ محمَّدِ بن رائق من بغداد قاصدينِ واسِطَ؛ لقتال أبي عبد الله البريدي نائبِ الأهواز، الذي قد تجبَّرَ بها ومنع الخَراج، فلما سار ابنُ رائق إلى واسِط خرجَ الحجريَّةُ فقاتلوه فسَلَّطَ عليهم بجكم فطحَنَهم، ورجع فَلُّهم إلى بغدادَ فتلقَّاهم لؤلؤ أميرُ الشرطة فاحتاط على أكثَرِهم ونُهِبَت دورهم، ولم يبقَ لهم رأسٌ يَرتَفِع، وقُطِعَت أرزاقهم من بيت المال بالكليَّة، وبعث ال"},{"id":1121,"era":"c4","t":"بناء مدينة الزهراء بالأندلس .","s":"أمر الناصِرُ ببناء مدينة الزَّهراء في قرطبة، وكان يصرف فيها من الصَّخرِ المنجور ستةَ آلاف صخرة في اليوم، سوى التَّبليطِ في الأساس وجَلَب إليها الرُّخام من قرطاجَنَّة إفريقية ومن تونس، وكان الأمناء الذين جلبوه عبد الله بن يونس، وحسن القرطبي، وعليُّ بنُ جعفر الإسكندراني، وكان الناصر يَصِلُهم على كلِّ رخامة بثلاثة دنانير، وعلى كلِّ سارية بثمانية دنانير. وكان فيها من السَّواري 4313 سارية، المجلوبة منه"},{"id":1122,"era":"c4","t":"اختلال أمور القرامطة وقتَل بعضهم بعضًا .","s":"في هذه السَّنة اختَلَّت أمورُ القرامِطة حتى قتَلَ بعضُهم بعضًا، وسببُ ذلك أنَّه كان رجلٌ منهم يقال له ابن سنبر، وهو مِن خواصِّ أبي سعيدٍ القرمطي والمطَّلِعينَ على سِرِّه، وكان له عدوٌّ مِن القرامطة اسمُه أبو حفص الشريك، فعَمَد ابنُ سنبر إلى رجلٍ من أصبهان وقال له: إذا ملكَّتكُ أمر القرامطة أريدُ منك أن تقتُلَ عدوي أبا حفص فأجابه إلى ذلك وعاهده عليه، فأطلَعَه على أسرارِ أبي سعيد، وعلاماتٍ كان يذكُر"},{"id":1123,"era":"c4","t":"الخليفة الراضي بالله يقبل الهدنة وفداء الأسرى من الروم .","s":"ورد كتابٌ مِن مَلِكِ الرُّومِ إلى الراضي مكتوبٌ بالروميَّة والتَّفسير بالعربية، فالروميُّ بالذَّهبِ والعربيُّ بالفِضَّة، وحاصِلُه طلب الهُدنة بينه وبينه، ووجَّهَ مع الكتاب بهدايا وألطافٍ كثيرة فاخرة، فأجابه الخليفةُ إلى ذلك، وفودي من المسلمينَ سِتَّة آلافِ أسيرٍ، ما بين ذكَرٍ وأنثى على نهرِ البدندون."},{"id":1124,"era":"c4","t":"فشل محمد بن رائق في استعادة منصبه أمير الأمراء للدولة العباسية .","s":"خرج الراضي أميرُ المؤمنينَ إلى المَوصِل لمحاربةِ ناصرِ الدولة الحسَنِ بنِ عبد الله بن حمدان نائبِها، وبين يديه بجكم أميرُ الأمراء، وقاضي القضاة أبو الحُسَين عمر بن محمد بن يوسف، وقد استخلف على بغداد ولَده القاضيَ أبا نصر يوسف بن عمر، في منصبِ القضاء، عن أمرِ الخليفةِ بذلك، ولما انتهى بجكم إلى الموصل ومعه الخليفةُ. واقَعَ الحسَن بن عبد الله بن حمدان فهزم بجكم ابنَ حمدان، وقرَّرَ الخليفة الموصِلَ وا"},{"id":1125,"era":"c4","t":"تمرد أمية بن إسحاق بمدينة شنترين واستعانته بالنصارى .","s":"كان لأُميَّةَ بنِ إسحاقَ أخٌ اسمُه أحمد، وكان وزيرًا لعبدِ الرحمن الناصر، فقتله عبدُ الرحمن، وكان أميَّةُ بشنترين، فلما بلغه ذلك عصى فيها، والتجأ إلى ردمير ملكِ الجلالقة، ودَلَّه على عَوْرات المسلمين، ثم خرج أميَّةُ في بعض الأيام يتصَيَّدُ، فمنعه أصحابُه من دخول البلد، فسار إلى ردمير فاستوزَرَه، وغزا عبدُ الرحمن بلاد الجلالقة، فالتقى هو وردمير هذه السَّنَة، فانهزمت الجلالقةُ، وقُتِلَ منهم خلقٌ كثي"},{"id":1126,"era":"c4","t":"وفاة عبدالرحمن بن أبي حاتم الرازي .","s":"هو العلَّامةُ الحافِظُ أبو محمَّد عبدالرحمن بن أبي حاتم محمَّد بن إدريس بن المنذر بن داود بن مهران التّميمي الحَنْظَلي الرازي. والرازيُّ نسبةٌ إلى الرَّيِّ، والزايُ للنِّسبةِ، كما في المروزي نسبةً إلى مَرْو الشاهجان ولد سنة 240 وقيل 241. أحدُ العلماء الثقات المشهورين بالتبحُّرِ في علوم الحديث والتفسير، وتفسيرُه من أحسَنِ التفاسيرِ لاشتمالِه على الأسانيدِ، وهو صاحِبُ كتاب الجرح والتعديل، كان أبوه أ"},{"id":1127,"era":"c4","t":"وفاة الخرائطي صاحب التصانيف المشهورة .","s":"هو الإمامُ الحافِظُ الصَّدوقُ المصَنِّف أبو بكر، محمدُ بنُ جعفر بن محمد بن سهل بن شاكر، السامري الخرائطيُّ صاحب كتاب \"مكارم الأخلاق\"، وكتاب \"مساوئُ الأخلاق\"، وكتاب \"اعتلال القلوب\" حدَّث بدمشقَ وبعسقلان, وصنَّفَ الكثير، وكان من الأعيانِ الثِّقاتِ, حسَنَ الأخبارِ، مليحَ التصانيف. مات بِيَافا."},{"id":1128,"era":"c4","t":"ولاية أبي علي بن محتاج خراسان .","s":"كان أبو بكرٍ محمَّدُ بنُ المظَفَّر بن محتاج عاملًا على خراسان مِن قِبَل الأمير السعيد نصر بن أحمد, إلَّا أنَّه مرِضَ مرضًا شديدًا طال به، فأحضر السعيدُ ابنه أبا عليٍّ من الصغانيان، واستعمله مكانَ أبيه، وسيَّرَه إلى نيسابور، وكتب إلى أبيه يستدعيه إليه، فسار عن نيسابورَ، فلَقِيَه ولَدُه على ثلاث مراحِلَ من نيسابور، فعَرَّفَه ما يحتاجُ إلى معرفتِه، وسار أبو بكرٍ إلى بخارى مريضًا، ودخل ولدُه أبو علي ن"},{"id":1129,"era":"c4","t":"استيلاء ابن رائق على الشام .","s":"استولى مُحمَّدُ بنُ رائق على بلاد الشامِ فدخل حمصَ أوَّلًا فأخذها، ثم جاء إلى دمشقَ وعليها بدر بن عبد الله الإخشيد المعروف ببدر الإخشيد وهو محمَّد بن طغج، فأخرجه ابنُ رائق من دمشق قهرًا واستولى عليها، ثم ركبَ ابن رائق في جيشٍ إلى الرملة فأخذها، ثمَّ إلى عريش مصر فأراد دخولَها فلقيه محمد بن طغج الإخشيدي فاقتتلا هناك فهَزَمه ابنُ رائق واشتغل أصحابُه بالنهبِ ونزلوا بخيام المصريين، فكَرَّ عليهم المصري"},{"id":1130,"era":"c4","t":"وفاة ابن عبد ربه صاحب العقد الفريد .","s":"هو العلَّامةُ الأديبُ الأخباريُّ، شهابُ الدين أبو عُمَر أحمدُ بنُ عبد ربه ابن حبيب بن حدير بن سالم المرواني القرطبي، مولى هشامِ بنِ عبد الرحمن بن معاوية بن هشام المعروف بابن عبد ربه الأندلسي. صاحِبُ كتاب (العِقد الفريد). ولد في رمضان سنة 246 كان موثَّقًا نبيلًا بليغًا شاعرًا, وكان من الفضلاء المُكثرين، والعُلَماء بأخبار الأوَّلين والمتأخرين، وكتابه العِقدُ يدُلُّ على فضائل جمة، وعلوم كثيرة مهمة، ق"},{"id":1131,"era":"c4","t":"قحط شديد ببغداد .","s":"وقع بالعِراقِ غَلاءٌ شديدٌ، فاستسقى النَّاسُ في ربيع الأول، فسُقُوا مطرًا قليلًا لم يجْرِ منه ميزابٌ، ثمَّ اشتد الغلاءُ والوَباءُ، وكثُرَ الموتُ حتى كان يُدفَنُ الجماعة في القبرِ الواحدِ ولا يُغسَّلونَ، ولا يُصَلَّى عليهم، ورخَصَ العَقارُ ببغداد والأثاث حتى بيعَ ما ثمنُه دينارٌ بدِرهم. وانقضى ربيع أول، ربيع ثاني، ولم يجئ غيرُ المطرة التي عند الاستسقاءِ، ثم جاء المطرُ في شعبان."},{"id":1132,"era":"c4","t":"وفاة الإمام البربهاري .","s":"هو الفقيهُ العابِدُ أبو محمَّدِ الحسَنُ بن علي بن خلف البربهاري، شيخُ الحنابلة في عصره، كان كبيرَ القَدرِ مُعَظَّمًا مُهابًا، له صِيتٌ عند السلطان وجلالةٌ، شديدًا على المبتدعة, عارفًا بالمذهب أصولًا وفروعًا. كان له فضلٌ كبير بالدعوة إلى الرجوعِ إلى منهج السلف في العقيدةِ، وإنكار البِدَع والخرافات، وله مواقِفُ شديدة على أهل البِدَع والفِرَق وخاصَّةً الشِّيعة، قال أبو الحُسَين بن الفراء: \"كان للبربه"},{"id":1133,"era":"c4","t":"وفاة الخليفة العباسي الراضي وتولي أخيه المتقي لله الخلافة .","s":"هو أبو إسحاقَ محمَّد - وقيل: أحمد – الراضي بالله بن المقتَدِر بالله جعفر بن المعتضد بالله أحمد بن الموفق بن المتوكل الهاشمي، العباسي. ولد: سنة 297. وأمُّه رومية. كان أسمَرَ قصيرًا نحيفًا، في وَجهِه طول. استخلف بعد عَمِّه القاهر عندما سمَلوا عينيه سنة 322. له فضائِلُ؛ منها: أنه آخر خليفة خطب يومَ الجمعة، وآخِرُ خليفةٍ جالسَ النُّدَماء، وآخِرُ خليفة له شِعرٌ مُدَوَّن، وآخر خليفة انفرد بتدبيرِ الجيوش"},{"id":1134,"era":"c4","t":"مقتل بجكم .","s":"أنفذ أبو عبدالله البريدي جيشًا من البصرةِ إلى مذار، فأنفذ بجكم جيشًا إليهم، وعليهم توزون، فاقتتلوا قتالًا شديدًا، فكتب توزون إلى بجكم يطلُبُ أن يلحَقَ به، فسار بجكم إليهم من واسط، منتصَفَ رجبٍ، فلَقِيَه كتاب توزون بأنَّه ظفِرَ بهم وهزمهم، فأراد بجكم الرجوعَ إلى واسط، فأشار عليه بعضُ أصحابه بأن يتصَيَّد، فقَبِلَ منه، وتصيَّدَ حتى بلغ نهر جور، فسَمِعَ أنَّ هناك أكرادًا لهم مالٌ وثروةٌ، فشَرِهَت نفسُ"},{"id":1135,"era":"c4","t":"قيام دولة بني سلار في أذربيجان .","s":"كانت أذربيجان بيَدِ ديسمَ بنِ إبراهيمَ الكُرديِّ، وكان مُعظَمُ جيوشِه الأكراد، إلَّا نفرًا يسيرًا من الديلم، من عسكرِ وشمكير، أقاموا عنده حين صَحِبوه إلى أذربيجان، ثمَّ إنَّ الأكراد تقَوَّوا، وتحكَّموا عليه، وتغلَّبوا على بعضِ قلاعِه وأطرافِ بلاده، فرأى أن يستظهِرَ عليهم بالدَّيلم، فاستكثر ذلك منهم، وكان وزيرُه أبا القاسم علي بن جعفر، وهو مِن أهل أذربيجان، فسعى به أعداؤه، فأخافه ديسم، فهرب إلى محم"},{"id":1136,"era":"c4","t":"بعض أخبار الروم .","s":"وصلت الرومُ إلى قريب حلبٍ فقَتَلوا خلقًا وأسَروا نحوًا مِن خمسة عشر ألفًا، وفيها دخل نائبُ طرسوس إلى بلادِ الرومِ فقَتَل وسبى وغَنِم، وسَلِمَ وأسَرَ مِن بطارقتهم المشهورينَ منهم وغيرهم خلقًا كثيرًا، ولله الحمدُ."},{"id":1137,"era":"c4","t":"الحمدانيون يسيطرون على بغداد .","s":"كان الخليفةُ أرسل وهو ببغداد إلى أبي محمَّد الحسن بن حمدان نائبِ الموصِلِ يستَمِدُّه ويستحِثُّه على البريدي، فأرسل أبو محمَّد الحسن أخاه عليًّا في جيش كثيف، فلما كان بتكريت إذا الخليفةُ وابنُ رائق قد هربا فرجَعَ معهما عليُّ بنُ حمدان إلى أخيه، وخدَمَ عليٌّ الخليفةَ خِدمةً كثيرة، ولَمَّا وصلوا إلى الموصِل خرج عنها أبو محمَّد الحسن بن حمدان فنزل شَرقَها، وأرسل التُّحَف والضِّيافات، ولم يجئْ إلى الخل"},{"id":1138,"era":"c4","t":"الروم يُطلِقونَ أسرى المسلمين بمقابل منديل مِن كنيسة الرها .","s":"وصلت الرومُ أرزن وميافارقين ونصيبين، ثم طلبوا منديلًا مِن كنيسة الرها يزعمونَ أنَّ المسيحَ مسَحَ به وجهَه، فارتسمت صورتُه فيه، على أنهم يُطلِقونَ جميع من سَبَوا من المسلمين، فاستفتى الخليفةُ الفقهاءَ، فمِن قائلٍ: نحن أحقُّ بعيسى منهم، وفي بَعثِه إليهم غضاضةٌ على المسلمين ووهنٌ في الدينِ، فقال علي بن عيسى الوزير: يا أميرَ المؤمنينَ، إنقاذ أسارى المسلمين من أيدي الكُفَّارِ خَيرٌ وأنفَعُ للناس من بقا"},{"id":1139,"era":"c4","t":"كثر الرفض ببغداد .","s":"كثُرَ الرَّفضُ ببغداد، فنودي بها: من ذكر أحدًا مِن الصحابة بسوءٍ، فقد بَرِئَت منه الذِّمَّةُ."},{"id":1140,"era":"c4","t":"وفاة السعيد صاحب خراسان .","s":"هو السَّعيدُ نصرُ بنُ أحمد بن إسماعيل الساماني, صاحِبُ خراسان وما وراء النهر، مولِدُه ووفاته في بخارى. وليَ الإمارة بعد مقتَلِ أبيه سنة 301 واستصغره أهلُ ولايته، وكفَلَه أصحاب أبيه. وكاد ينفَرِطُ عِقدُ إمارته، إلَّا أنَّه ما لَبِثَ أنْ شَبَّ ذَكيًّا مِقدامًا، حليمًا وقورًا. جمع الجموعَ وقاتلَ الخُصومَ، فامتَدَّ سلطانُه واتَّسَعَت دائرةُ مُلكِه، فكانت له خراسانُ وجرجان والريُّ ونيسابور وتلك الأطراف"},{"id":1141,"era":"c4","t":"الروس يهاجمون أذربيجان ويذبحون أهلها .","s":"خرجت طائفةٌ من الروسيَّة في البحر إلى نواحي أذربيجان، وركبوا في البحرِ في نهر للكر، وهو نهرٌ كبير، فانتهوا إلى بَردعةَ، فخرج إليهم نائبُ المرزبان بردعة في جمع الديلم والمطوعة يزيدون على خمسةِ آلافِ رجلٍ، فلَقُوا الروس، فلم يكُنْ إلَّا ساعة حتى انهزم المسلمونَ منهم، وقُتِلَ الديلم عن آخرهم، وتَبِعَهم الروس إلى البلد، فهرب من كان له مركوبٌ وترك البلد، فنزله الروسُ ونادوا فيه بالأمان فأحسنوا السيرةَ،"},{"id":1142,"era":"c4","t":"دخول الروم رأس العين .","s":"جاء الدُّمُسْتُق مَلِكُ الروم إلى رأس العين- من أرض الجزيرةِ- في ثمانين ألفًا، فدخلها ونهب ما فيها وقتَلَ وسبى منهم نحوًا من خمسة عشر ألفًا، وأقام بها ثلاثةَ أيام، فقصدته الأعرابُ مِن كلِّ وَجهٍ، فقاتلوه قتالًا عظيمًا حتى انجلى عنها."},{"id":1143,"era":"c4","t":"وفاة رئيس القرامطة سليمان الجنابي .","s":"هو أبو طاهرٍ سُلَيمانُ بنُ أبي سعيد الحسن الجَنّابي الهَجري القرمطيُّ، رئيس القرامطة- قبَّحه الله- كان أبوه يحِبُّه ويرجِّحُه للأمرِ مِن بعده، وأوصى: إن حَدَث به موتٌ، فالأمرُ إلى ابنِه سعيدٍ إلى أن يكبَرَ أبو طاهر، فيُعيد سعيدٌ إليه الأمر. فلما كان في سنةِ خمس وثلاثمائة سلَّمَ سعيدٌ الأمرَ إلى أخيه أبي طاهر، فاستجاب لأبي طاهرٍ خَلقٌ وافتتنوا به؛ بسبب أنَّه دلَّهم على كنوزٍ كان والده أطلَعَه عليها"},{"id":1144,"era":"c4","t":"وصول معز الدولة ابن بُوَيه إلى مدينة واسط وديالي .","s":"بلغ مُعِزَّ الدولةِ أبا الحُسَينِ بن بُوَيه إصعادُ توزون إلى الموصِل، فسار هو إلى واسِط؛ لِميعادٍ مِن البريديين، وكانوا قد وعدوه أن يُمدُّوه بعسكرٍ في الماء، فأخَلفوه، وعاد توزون من الموصِل إلى بغداد، وانحدر منها إلى لقاءِ مُعِزِّ الدولة، والتَقَوا سابع عشر ذي القعدة بقباب حميد، وطالت الحربُ بينهما بضعةَ عشر يومًا، إلَّا أن أصحاب توزون يتأخَّرون، والديلم يتقَدَّمون، إلى أن عبرَ توزون نهرَ ديالي، و"},{"id":1145,"era":"c4","t":"عزل الخليفة العباسي المتقي لله وخلافة ابن عمه المستكفي .","s":"كان الخليفةُ المتقي لله مقيمًا بالموصل فأرسَلَ إلى الإخشيد محمَّدِ بن طغج صاحب الديار المصريَّة والبلاد الشامية، فأقبل إليه وقَدِمَ عليه في المنتَصَف من المحرم، وخضع للخليفة غايةَ الخُضوع، وكان يقومُ بين يديه كما يقومُ الغلمان، ويمشي والخليفةُ راكِبٌ، ثم عرض عليه أن يسيرَ معه إلى الدِّيار المصرية، أو يقيمَ ببلاد الشام فأبى عليه ذلك، فأشار عليه بالمُقامِ بمكانِه الذي هو فيه، ولا يذهَب إلى توزون ببغ"},{"id":1146,"era":"c4","t":"سيف الدولة يتولى إمارة حلب ويقيم فيها الدولة الحمدانية .","s":"كان سَيفُ الدَّولة عليُّ بنُ أبي الهيجاء عبدالله بن حمدان مع المتَّقي لله بالرقَّة، فلما عاد المتَّقي إلى بغداد، وانصرف الإخشيدُ إلى الشام، بقِيَ يأنس المؤنسي بحلبٍ، فقَصَدها سيفُ الدولة، فلما نازلها فارقها يأنسُ وسار إلى الإخشيد، فمَلَكها سيفُ الدولة، ثم سار منها إلى حمصٍ، فلَقِيَه بها عسكرُ الإخشيد محمَّد بن طغج، صاحب الشام ومصر، مع مولاه كافور، واقتتلوا، فانهزم عسكَرُ الإخشيد وكافور، وملَكَ سَي"},{"id":1147,"era":"c4","t":"قتال أبي يزيد الخارجي العبيديين الفاطميين في إفريقية .","s":"ظهر أبو يزيدَ مخلدُ بنُ كيداد عام 316هـ في جبالِ أوراس، وقَوِيَ أمره عام 325هـ بانضمام الإباضيَّة إليه، ثم انضَمَّ إليه بعضُ السُّنَّة؛ لمحاربته الفاطميِّينَ، كان بداية الأمر أن أرسل القائِمُ الفاطميُّ عامِلَه على قسطيلة لقتالِ أبي يزيد، فاعتقله أبو يزيدَ فأرسل القائِمُ جَيشًا كبيرًا أحرز فيه أبو يزيد انتصاراتٍ على جيش الفاطميِّينَ، واستولى على كثيرٍ مِن المدن، فدخل رقادة والقيروان، واتَّجَه نحو ا"},{"id":1148,"era":"c4","t":"وفاة أبي منصور الماتريدي .","s":"هو أبو منصورٍ محمَّد بن محمد بن محمود أبو منصور الماتُريديُّ، نِسبتُه إلى ما تُريد محلَّة بسَمَرقند. من أئمَّة علم الكلامِ، حَنفيُّ المذهَبِ, وهو إمامُ المدرسةِ المَاتُريديَّة التي يتبَعُها غالبيَّةُ أتباع المذهَبِ الحنَفي في العقيدةِ. أقام نظرياتٍ عَقَديَّةً خاصةً بإثباتِ أدلَّةِ الشَّرعِ بالأدلة العقليَّة والمنطقيَّة والبراهين التي لا شَكَّ فيها أبدًا، مع جَعلِ العَقلِ سُلطانًا على كلِّ ذلك، له "},{"id":1149,"era":"c4","t":"قحط ووباء شديد ببغداد .","s":"في هذه السَّنةِ وقَعَ غَلاءٌ شَديدٌ ببغداد، حتى أكلوا الميتةَ والسنانيرَ والكِلابَ، وكان من النَّاسِ مَن يسرِقُ الأولادَ فيَشويهم ويأكُلُهم، وكثُرَ الوباء في الناس حتى كان لا يَدفِنُ أحدٌ أحدًا، بل يُترَكونَ، على الطُّرُقاتِ، فيأكل كثيرًا منهم الكلابُ، وبيعت الدورُ والعقارُ بالخُبزِ، وانحدرَ كثيرٌ من أهل بغداد إلى البصرةِ، فكان منهم من مات في الطريقِ ومنهم من وصل إليها بعد مُدَّة مديدةٍ."},{"id":1150,"era":"c4","t":"وفاة محمد الإخشيدي مؤسس الدولة الإخشيدية وتولي ابنه مكانه .","s":"هو الإخشيدُ أبو بكر مُحمَّد بن طغج، صاحِبُ ديارِ مِصرَ، وكان مولِدُه سنة 268 ببغداد، وكان موتُه بدمشق، وقيل مات سنة 335، ووليَ الأمرَ بعدَه ابنُه أبو القاسم أنوجور، فاستولى على الأمرِ كافور الخادِمُ الأسود، وهو من خَدَمِ الإخشيد، ولَمَّا ثبت أمرُ أنوجور وكان صغيرًا، صار الخادم كافور الإخشيدي مدبِّرَ مَملكتِه، فكان كافور يُطلِقُ في كل سنة لأنوجور أربعَمائة ألف دينار ويتصَرَّفُ كافور فيما يبقى."},{"id":1151,"era":"c4","t":"قيام دولة البويهيين في طبرستان وفارس وكرمان  .","s":"استطاع البويهيُّون أن يتحَكَّموا في الخليفة، ويُسيطِروا على الدولة، ويُديروها بأنفُسِهم، ففي أيام مُعِزِّ الدولة جرَّدوا الخليفةَ مِن اختصاصاته، فلم يبقَ له وزيرٌ، وإن كان له كاتِبٌ يديرُ أملاكَه فحَسبُ، وصارت الوزارةُ لمُعز الدولة يستوزِرُ لنَفسِه من يريد، وكان من أهمِّ أسبابِ ضَعفِ الخلافة وغروب شمسِها أن البويهيين (الديلم) كانوا من المُغالينَ في التشيُّع، وهم يعتَقِدونَ أنَّ العباسيِّينَ قد أخذ"},{"id":1152,"era":"c4","t":"وفاة الخِرَقي الحنبلي صاحب المختصر .","s":"هو العَلَّامة شيخُ الحنابلةِ: أبو القاسم عُمَرُ بنُ أبي علي الحسين بن عبد الله بن أحمد البغدادي الخِرَقيُّ الحنبليُّ, والخِرَقي: بكسر الخاء وفتح الراء؛ نِسبةً إلى بَيعِ الخِرَق والثِّيابِ. فقيهٌ حنبليٌّ، صنَّف التصانيفَ. صاحِبُ المُختَصَر المشهورِ في الفِقهِ على مذهب الإمام أحمد، والذي شَرَحه القاضي أبو يعلَى بن الفراء، والشيخ مُوفَّق الدين بن قُدامة المقدسي، كان من كبارِ العُلَماء، تفَقَّه على وا"},{"id":1153,"era":"c4","t":"بنو بويه الديلم الشيعية يتطلعون للسيطرة على العراق .","s":"تطَلَّعَ بنو بُوَيه الديلم الشِّيعيَّة إلى السيطرةِ على العراقِ مَقَرِّ الخلافة، وقيل: إنَّ أصلَهم يرجِعُ إلى ملوك ساسان الفارسيِّين الذين شُرِّدوا، فاتَّخَذوا من إقليمِ الديلم الواقع في المنطقة الجبليَّة جنوبيَّ بَحرِ قزوين ملجأً لهم ومقرًّا, وسُمُّوا بالدَّيلمة؛ لطُولِ مُجاورتِهم الدَّيلم. تزعَّم أبو شجاع بُوَيه قبائلَ البُويهيِّينَ سنة 322 - 329 والذى ينتهي نسَبُه إلى الملك الفارسي يزد جرد، وقد"},{"id":1154,"era":"c4","t":"البويهيون يعزلون الخليفة المستكفي بالله ويولون المطيع لله الخلافة .","s":"حضر مُعِزُّ الدولة إلى الحضرةِ، فجلس على سريرٍ بين يدي الخليفة، وجاء رجلان من الدَّيلم فمَدَّا أيديَهم إلى الخليفة فأنزلاه عن كُرسِيِّه، وسحباه، ونهض معِزُّ الدولةِ واضطربَت دارُ الخلافة حتى خُلِصَ إلى الحريمِ، وتفاقَمَ الحالُ، وسيق الخليفةُ ماشيًا إلى دار معز الدولة فاعتُقِل بها، وأُحضِرَ أبو القاسم الفضلُ بن المُقتَدِر، فبويع بالخلافة، وسُمِلَت عينا المستكفي وأودعَ السِّجنَ، فلم يزَلْ به مسجونا "},{"id":1155,"era":"c4","t":"وفاة القائم العبيدي (الفاطمي) وولده المنصور يتسمَّى بالخلافة .","s":"هو القائِمُ بأمرِ الله الفاطميُّ العُبَيدي أبو القاسم محمد نزارا بن عبيد الله المهدي صاحب إفريقيَّة، بايع له والِدُه عُبيد الله بولاية العهد بإفريقيَّة وجَهَّزه أبوه لضَمِّ مِصرَ مرتين، لكنَّه لم يُفلِحْ في ضَمِّها. وبعد وفاةِ القائمِ قام بالأمرِ بعده ابنُه إسماعيلُ، وتلقَّب بالمنصور بالله، وكتم موتَه؛ خوفًا أن يعلمَ بذلك أبو يزيد، وهو بالقربِ منه على سوسة، وأبقى الأمورَ على حالها، ولم يتسَمَّ بال"},{"id":1156,"era":"c4","t":"استيلاء ركن الدولة البويهي على مدينة الري وغيرها .","s":"سار أبو عليِّ بن محتاج في عساكرِ خُراسان إلى الريِّ لاستنقاذِها من يدِ ركنِ الدَّولة بنِ بُوَيه، فسار في جمعٍ كثير فخرج إليه ركنُ الدولة محاربًا، فالتَقَوا على ثلاثة فراسخ من الريِّ، وكان مع أبي علي جماعةٌ كثيرة من الأكراد، فغدروا به، واستأمنوا إلى ركنِ الدولة، فانهزم أبو عليٍّ، وعاد نحو نيسابور وغَنِموا بعضَ أثقاله، ورجع ركنُ الدولة إلى الريِّ واستولى عليها وعلى سائرِ أعمالِ الجبَلِ، وأزال عنها ا"},{"id":1157,"era":"c4","t":"فداء الأسرى بين الروم وسيفِ الدولة بن حمدان .","s":"كان الفِداءُ بالثغورِ بين المسلمينَ والرومِ على يدِ نَصرِ الثملي أميرِ الثغور لسيفِ الدولة بن حمدان، وكان عدة الأسرى 2480 أسيرًا مِن ذكَرٍ وأنثى، وفضَلَ للرُّومِ على المُسلِمينَ مائتان وثلاثون أسيرًا لكثرةِ مَن معهم من الأسرى، فوفاهم ذلك سيفُ الدولة."},{"id":1158,"era":"c4","t":"معز الدولة البويهي يستعيد البصرة من أبي القاسم البريدي .","s":"سار مُعِزُّ الدولة ومعه المطيعُ لله إلى البصرةِ; لاستنقاذها مِن يَدِ أبي القاسم عبدِ الله بن أبي عبد الله البريدي، وسَلَكوا البريَّةَ إليها، فأرسل القرامِطةُ مِن هجَرَ إلى مُعِزِّ الدولة ينكرون عليه مسيرَه إلى البريةِ بغير أمْرِهم، وهي لهم، فلم يجِبْهم عن كتابهم، وقال للرَّسولِ: قل لهم مَن أنتم حتى تستأمِروا، وليس قصدي مِن أخذِ البَصرةِ غَيرَكم، وستَعلَمونَ ما تلقونَ مني. ولَمَّا وصل معزُّ الدولة "},{"id":1159,"era":"c4","t":"ركنُ الدولة بن بويه يسيطر على طبرستان وجرجان .","s":"اجتمع ركنُ الدولة بن بويه، والحسَنُ بن الفيرزان، وقصدا بلادَ وشمكير، فالتقاهما وشمكيرُ وانهزم منهما، وملك ركنُ الدولة طبرستان، وسار منها إلى جرجانَ فمَلَكها، واستأمَنَ مِن قوَّاد وشمكير مائة وثلاثة عشر قائدًا، فأقام الحسن بن الفيرزان بجرجان، ومضى وشمكير إلى خراسان مستجيرًا ومُستنجدًا لإعادةِ بلادِه."},{"id":1160,"era":"c4","t":"خلاف بين ناصر الدولة الحمداني ومعز الدولة البويهي .","s":"سار مُعِزُّ الدولة من بغداد إلى الموصِل قاصدًا ناصِرَ الدولة الحمدانيَّ، فلما سمع ناصِرُ الدولة بذلك سار عن المَوصِل إلى نصيبين، ووصل معزُّ الدولة فمَلَك الموصِلَ في شهر رمضان، وظلم أهلَها وعسَفَهم، وأخذ أموالَ الرَّعايا، فكَثُرَ الدُّعاءُ عليه، وأراد معِزُّ الدولةِ أن يملِكَ جميعَ بلاد ناصرِ الدولة، فأتاه الخبَرُ من أخيه ركنِ الدولة أنَّ عساكِرَ خراسان قد قَصَدَت جرجان والريَّ، ويستمِدُّه ويطلب م"},{"id":1161,"era":"c4","t":"حروب سيف الدولة الحمداني ضد الروم .","s":"دخل سيفُ الدَّولةِ الحَمدانيُّ بجيشٍ كثيفٍ بلادَ الرُّومِ غيرَ أنه هُزِمَ وأخذ الرومُ كُلَّ ما في أيدي هذا الجيش، فأخذ الرومُ مرعش كما نال أهلَ طرطوس من الرومِ الأذى الكثيرُ، ولم يتمكَّنْ سيف الدولة من حمايتِهم ورَدِّ ما بهم."},{"id":1162,"era":"c4","t":"وفاة عماد الدولة بن بويه .","s":"هو أبو الحسَنِ عليُّ بنُ بُوَيه، وهو أكبر أولاد بُوَيه، وأوَّلُ مَن تمَلَّك منهم، وكان عاقلًا حاذقًا حميد السيرة رئيسًا في نفسه. كان أولُ ظهورِه في سنة 322, فلما كان في هذا العام 338 قَوِيَت عليه الأسقامُ وتواترت عليه الآلامُ، فأحسَّ من نفسه بالهلاك، ولم يُفادِه ولا دفَعَ عنه أمرَ اللهِ ما هو فيه من الأموالِ والمُلك وكثرةِ الرِّجال والأموالِ، ولا رَدَّ عنه جيشُه من الديلم والأتراك والأعجام، مع كثر"},{"id":1163,"era":"c4","t":"وفاة الخليفة المستكفي بالله في بغداد .","s":"هو الخليفة أبو القاسمِ عبد الله المستكفي بالله بن المكتفي علي بن المعتضد العباسي. كان رَبْعَ القامةِ مليحًا، معتدِلَ البَدَن، أبيضَ بحُمرةٍ، خفيفَ العارضين. وأمُّه أمُّ ولد. بويع وقتَ خَلعِ المتقي لله عام 333. وله يومئذٍ إحدى وأربعون سنة، ولقب بالمستكفي بالله. قام ببيعته أميرُ الأمراء توزون، ولَمَّا أقبل أبو الحسن أحمدُ بنُ بويه على العراق استولى على الأهوازِ والبصرة وواسط، ثم بغداد, وفَرَّ منها أ"},{"id":1164,"era":"c4","t":"وفاة اللغوي أبي جعفر النَحّاس .","s":"هو أحمدُ بنُ مُحمَّد بن إسماعيلَ بنِ يونُسَ أبو جعفر المراديُّ المصريُّ النحويُّ، المعروف بالنَّحَّاس، والنَّحَّاس: نسبة إلى من يعمَلُ النَّحاسَ. لُغويٌّ مُفَسِّرٌ أديبٌ، له مُصَنَّفاتٌ كثيرةٌ في التفسيرِ وغيره، وقد سَمِعَ الحديثَ ولقي أصحابَ المُبَرِّد، أخذ النحوَ عن عليِّ بن سليمانَ الأحوص، وأبي بكر الأنباري، وأبي إسحاق الزَّجَّاج، ونِفطَوَيه، وغيرهم، وله مصنفاتٌ كثيرة مفيدة، منها (تفسير القرآن)"},{"id":1165,"era":"c4","t":"وفاة الخليفة العباسي القاهر بالله .","s":"هو أبو منصورٍ محمَّدُ بنُ المعتضد بن طلحة بن المتوكل. أمُّه أمُّ ولدٍ اسمُها فتنة، لَمَّا قُتِلَ المقتَدِرُ أُحضِرَ هو ومحمَّد بن المكتفي، فسألوا ابنَ المكتفي أن يتولَّى، فقال: لا حاجة لي في ذلك، وعمِّي هذا أحَقُّ به، فكلم القاهِر فأجاب، فبويعَ ولُقِّبَ القاهِرَ بالله، فأوَّلُ ما فعَلَ أنْ صادَرَ آلَ المُقتَدِر وعَذَّبهم، وضربَ أمَّ المُقتَدِر حتى ماتت في العذابِ، على الرغمِ أنَّها كانت تُحسِنُ إل"},{"id":1166,"era":"c4","t":"وفاة الفارابي .","s":"هو شيخُ الفَلسفةِ الحَكيمُ أبو نصر محمَّدُ بنُ محمد بن طرخان بن أوزلغ التركي الفارابي المنطقيُّ، من كبار الفلاسفة، قال الذهبي: \"أحدُ الأذكياء. له تصانيفُ مشهورة, من ابتغى الهُدى منها ضَلَّ وحار, منها تخرَّجَ ابنُ سينا, نسأل الله التوفيق\". تعلَّم اليونانية, ولقِيَ متَّى بن يونس فأخذ عنه, وسار إلى حرَّان فلزم بها يوحنَّا بن جيلان النصراني فتعلَّمَ عليه المنطِقَ, وقد أحكم أبو نصرٍ العربيَّةَ بالعراقِ"},{"id":1167,"era":"c4","t":"سيف الدولة بن حمدان يغزو بلاد الروم .","s":"دخل سيفُ الدَّولةِ بنُ حمدان بجيشٍ عظيمٍ نحو مِن ثلاثين ألفًا إلى بلادِ الرُّومِ فتوغَّلَ فيها وفتح حصونًا وقتل خلقًا وأسرَ أممًا، وغَنِمَ شيئًا كثيرًا ثمَّ رجع، فأخذت عليه الرومُ الدَّربَ الذي يخرجُ منه فقتلوا عامَّةَ مَن معه وأسَرُوا بقيَّتَهم واستردُّوا ما كان أخَذَه، ونجا سيفُ الدولة في نفرٍ يسيرٍ مِن أصحابه. ثمَّ في سنة 342 جمع سيفُ الدولة بن حمدان جيوشَ المَوصِل، والجزيرة، والشام، والأعراب، "},{"id":1168,"era":"c4","t":"وفاة أبي القاسم الزجاجي النحوي .","s":"هو أبو القاسمِ عبدُ الرَّحمنِ بنُ إسحاقَ الزَّجَّاجي النَّحْوي البغدادي دارًا ونشأةً، والنَّهاونديُّ أصلًا ومولدًا. كان إمامًا في علمِ النَّحو، وصنَّفَ فيه كتابَ \"الجُمل الكبرى\" وهو كتابٌ نافعٌ لولا طولُه بكثرة الأمثلة. أخذ النحوَ عن محمَّد بن العبَّاس اليزيدي، وأبي بكر بن دُريد، وأبي بكر بن الأنباريِّ. وصَحِبَ أبا إسحاق إبراهيمَ بنَ السَّريِّ الزجَّاج فنُسِبَ إليه، وعُرِفَ به، وسكن دمشقَ وانتفع ب"},{"id":1169,"era":"c4","t":"إعادة القرامطة الحجر الأسود للكعبة  .","s":"في هذه السَّنةِ ردَّ القرامِطةُ الحجَرَ الأسودَ المكِّيَّ إلى مكانه في البيت، وقد كان القرامطةُ أخذوه في سنة 317، وكان مَلِكُهم إذ ذاك أبا طاهر سُليمانَ بن أبي سعيد الجَنَّابي- لعنه الله- ولَمَّا وقع هذا أعظمَ المُسلِمونَ ذلك، وقد بذل لهم الأميرُ بجكم التركي قبل هذا العامِ خمسينَ ألف دينارٍ على أن يردوه إلى موضِعِه فلم يفعلوا، وقالوا: نحن أخذناه بأمرٍ فلا نرُدُّه إلَّا بأمرِ مَن أخذناه بأمرِه، وكَ"},{"id":1170,"era":"c4","t":"ظهور بعض القائلين بالتناسخ ببغداد .","s":"رُفِعَ إلى وزيرِ مُعِزِّ الدولة الحسَنِ المهلَّبي أنَّ رجلًا يُعرَفُ بالبصريِّ مات ببغداد، وهم مُقَدَّم القراقرية، يدَّعي أنَّ رُوحَ أبي جعفرٍ محمَّد بن علي بن أبي القراقر قد حَلَّت فيه، وأنَّه خَلَّف مالًا كثيرًا كان يَجبيه من هذه الطائفةِ، وأنَّ له أصحابًا يعتَقِدونَ ربوبيَّته، وأنَّ أرواحَ الأنبياءِ والصِّديقينَ حَلَّت فيهم، فأمر بالختمِ على التَّرِكة، والقبضِ على أصحابه، والذي قام بأمرِهم بعده"},{"id":1171,"era":"c4","t":"نشوب حرب مع الروم في صقلية .","s":"كان المنصورُ الفاطميُّ- صاحِبُ إفريقيَّةَ- قد استعمَلَ على صقليَّة سنة 336 الحسَنَ بنَ علي بن أبي الحسين الكلبي، فدخلها واستقَرَّ بها، وغزا الرومَ الذين بها عدَّةَ غَزَوات، فاستمَدُّوا مَلِكَ قسطنطينيَّة فسيَّرَ إليهم جيشًا كثيرًا، فنزلوا أذرنت، فأرسل الحسَنَ بنَ علي إلى المنصور يعَرِّفه الحال، فسيَّرَ إليه جيشًا كثيفًا مع خادِمِه فرح، فجمع الحسَنُ جُندَه مع الواصلين وسار إلى ريو، وبثَّ السَّرايا "},{"id":1172,"era":"c4","t":"تتابع فتوحات المسلمين في الأندلس .","s":"كانت للمُسلمين غزواتٌ على نصارى الأندلُس، نصَرَهم اللهُ فيها. منها فتحٌ على يدِ قائدِ بطليوس بجيليقة، هزَمَهم أقبحَ هزيمةٍ، قَتَل جملةً مِن حُماتهم ومقاتِلتِهم، وسبى من نسائِهم وذراريِّهم نيِّفًا وثلاثمائة رأس، ووصل ذلك السبيُ إلى قرطبة، وفتحٌ آخَرُ على يدي أحمدَ بنِ يعلى قائدِ الناصرِ، وفتحٌ آخَرُ على يدي رشيقٍ قائد الناصر على طلبيرة، وفتحٌ آخَرُ على يدي يحيى بن هاشم النجيبي."},{"id":1173,"era":"c4","t":"حَجَبة الكعبة يصلحون الحجر الأسود ويجعلون له طوقا من فضة .","s":"قلَعَ حَجَبةُ الكعبةِ الحجَرَ الأسودَ لا لأخْذِه، بل لعدمِ رِضاهم عن وَضعِ سنبر بن الحسن صاحِبِ القرمطيِّ الذي وضَعَه لَمَّا ردُّوه في العام الماضي، فجعلوه في الكعبةِ، فأحبُّوا أن يجعلوا له طوقًا مِن فِضَّة فيُشَدُّ به كما كان قديمًا، كما عَمِلَه عبد الله بن الزبير، وأخذ في إصلاحِه صانعانِ حاذقانِ فأحكماه. قال أبو الحسن محمَّد بن نافع الخزاعي: \" دخلتُ الكعبةَ فيمن دخَلَها فتأمَّلتُ الحجَرَ، فإذا ا"},{"id":1174,"era":"c4","t":"وفاة منصور بن قراتكين أمير ما وراء النهر .","s":"هو منصورُ بنُ قراتكين، صاحِبُ الجيوش الخراسانيَّة، من أكابرِ أصحابِ نوحٍ وخَواصِّه؛ أميرِ ما وراء النهرِ وخُراسان. توفِّيَ بعد عَودتِه مِن أصبهان إلى الريِّ، ذكر العراقيونَ أنَّه أدمن الشُّربَ عِدَّةَ أيام بلياليها، فمات فجأةً، وقال الخراسانيُّونَ إنَّه مَرِضَ ومات، فالله أعلم. ولَمَّا مات رجعت العساكِرُ الخراسانيَّة إلى نيسابور، وحُمِلَ تابوتُ منصور، ودُفِنَ إلى جانب والده باسبيجاب."},{"id":1175,"era":"c4","t":"وفاة أبي المظفر بن محتاج صاحب جيوش خراسان .","s":"هو أبو المظَفَّر بنُ أبي علي بنِ محتاج صاحب جيوش خراسان، توفي ببُخارى كان قد رَكِبَ دابَّةً أنفَذَها إليه أبوه، فألقَتْه وسَقَطت عليه فهَشَمتْه، فمات من يومِه، وعَظُمَ مَوتُه على الناس كافَّةً، وشَقَّ موته على الأميرِ نوح الساماني أميرِ بلادِ ما وراء النهر، وحُمِلَ إلى الصغانيان إلى والدِه أبي علي."},{"id":1176,"era":"c4","t":"وفاة الإمام أبي إسحق المروزي .","s":"هو إبراهيمُ بنُ أحمدَ بنِ إسحاقَ المعروفُ بأبي إسحق المروزيِّ، يُنسَبُ إلى مَرْو الشاهجان، وهي إحدى حواضِرِ خراسان. كان إمامَ عَصرِه في الفتوى والتدريس، وانتهت إليه رئاسةُ الفِقهِ في العراق بعد ابنِ سُرَيج، أخذ الفِقهَ عن عبدان المروزي وابنِ سُريج والإصطخري. أقام ببغدادَ زمنًا طويلًا يدرِّس ويُفتي، وتخرَّج على يديه خلقٌ كثيرٌ. ثم انتقل إلى مصرَ في آخرِ حياته، وجلس بها مجلِسَ الشافعيِّ يدرِّس ويُفت"},{"id":1177,"era":"c4","t":"وفاة أبي الحسن الكرخي .","s":"هو عُبيدُ الله بنُ الحسَنِ بنِ دلَّال بن دلهم، المعروفُ بأبي الحسَن الكَرخيِّ، أحدُ مشايخ الحنفيَّة المشهورين، ولد سنة 260 وسكن بغدادَ ودرَّسَ فِقهَ أبي حنيفة وانتَهَت إليه رئاسةُ أصحابه في البلاد، وكان متعبِّدًا صبورًا على الفقرِ عزوفًا عمَّا في أيدي الناس، ولكنه كان رأسًا في الاعتزالِ، وقد سمع الحديثَ مِن إسماعيلَ بنِ إسحاق القاضي، وروى عنه حَيوةُ وابنُ شاهين، وأصابه الفالج في آخر عمره، فاجتمع ع"},{"id":1178,"era":"c4","t":"قصد صاحب عمان البصرة بمساعدة من القرامطة .","s":"سار يوسُفُ بنُ وجيه، صاحِبُ عمان، في البحرِ والبَرِّ إلى البصرة فحَصَرها، وكان سببُ ذلك أنَّ معِزَّ الدولة لَمَّا سلك البريَّةَ إلى البصرة، وأرسل القرامِطةُ يُنكِرونَ عليه ذلك، فعَلِمَ يوسف بن وجيه استيحاشَهم مِن مُعِزِّ الدولة، فكتب إليهم يطَمِّعُهم في البصرة، وطلب منهم أن يُمِدُّوه من ناحية البَرِّ، فأمدُّوه بجمعٍ كثير منهم، وسار يوسفُ في البحر، فبلغ الخبَرُ إلى الوزير الحسَن المهلَّبي وقد فرغ م"},{"id":1179,"era":"c4","t":"وفاة المنصور العبيدي (الفاطمي) وتوليّ المعز الحكم  .","s":"هو المنصورُ بالله أبو الطاهرِ إسماعيلُ بنُ القائم أبي القاسم محمَّد بن عُبَيد الله المهدي، بويع يومَ وفاةِ أبيه القائم، وكان بليغًا فصيحًا يرتجِلُ الخُطَب. كانت خلافتُه سبعَ سنينَ وستَّة عشر يومًا، وكان سببُ مَوتِه أنَّه مَرِضَ من البردِ الشديدِ، فلازَمَه السهرُ حتى لا يستطيعَ النَّومَ أبدًا، فداواه أحد الأطباء بدواءٍ منوِّمٍ فمات منه، ولَمَّا مات وَلِيَ الأمرَ بعده ابنُه معد، وهو المعِزُّ لدين ال"},{"id":1180,"era":"c4","t":"قتال بين حجاج العراق وحجاج مصر .","s":"كان أميرُ الحُجَّاج العراقيين الشَّريفان أبو الحسن محمد بن عبد الله، وأبو عبد الله أحمد بن عمر بن يحيى العلويان، فجرى بينهما وبين عساكِرِ المِصريِّين من أصحابِ ابنِ طغج حربٌ شديدة، وكان الظَّفَرُ لهما، فخطَبَ لمُعِزِّ الدولة بمكَّة، فلما خرجا من مكَّة لَحِقَهما عسكرُ مِصرَ، فقاتَلَهما، فظفرا به أيضًا."},{"id":1181,"era":"c4","t":"قتال سيف الدولة الحمداني مع الروم .","s":"غزا سيفُ الدولة بن حمدان بلادَ الروم، فقَتَل وأسَرَ، وسبى وغَنِمَ، وكان فيمن قُتِلَ قُسطنطين بن الدُّمُسْتُق, فعَظُم الأمرُ على الروم، وعظُمَ الأمر على الدُّمُسْتُق، فجمع عساكِرَه من الروم والروس والبلغار وغيرهم وقصَدَ الثُّغورَ، فسار إليه سيفُ الدولة بن حمدان، فالتقوا عند الحدث في شعبان، فاشتد القتالُ بينهم وصبر الفريقان، ثم انهزم الرومُ، وقُتِلَ منهم وممَّن معهم خَلقٌ عظيم، وأُسِرَ صِهرُ الدُّمُ"},{"id":1182,"era":"c4","t":"وقوع داء ووباء ببغداد وأصبهان والأهواز .","s":"شَمِلَ النَّاسَ ببغداد وواسط وأصبهان والأهواز داءٌ مُرَكَّبٌ مِن دمٍ وصفراء ووباء، مات بسبب ذلك خلقٌ كثير، بحيث كان يموتُ في كلِّ يومٍ قَريبٌ مِن ألف نفسٍ، وجاء فيها جرادٌ عظيمٌ أكل الخَضروات والأشجار والثِّمار، ووقع بالريِّ وباءٌ كثيرٌ مات فيه من الخَلقِ ما لا يُحصى، وكان فيمن مات أبو عليِّ بنُ محتاج صاحِبُ جيوش خراسان، ومات معه ولَدُه."},{"id":1183,"era":"c4","t":"خروج مدعي النبوة بأذربيجان .","s":"خرج بأذربيجان رجلٌ ادَّعى حُرمةَ اللُّحومِ وما يخرُجُ مِن الحيوان، وأنَّه يعلَمُ الغَيبَ، فأضافه رجلٌ وأطعَمَه كشكيَّةً بشَحمٍ، فلمَّا أكَلَها قال له: ألستَ تُحَرِّمُ اللحم، وما يخرجُ مِن الحيوان، وأنَّك تعلمُ الغيبَ؟ قال: بلى! قال: فهذه الكشكيَّة بشَحمٍ، ولو عِلمْتَ الغيبَ لَمَا خَفِيَ عليك ذلك، فأعرض النَّاسُ عنه."},{"id":1184,"era":"c4","t":"قتال بين عبد الرحمن الناصر صاحب الأندلس والمعز الفاطمي .","s":"أنشأ عبدُ الرَّحمنِ النَّاصِرُ صاحِبُ الأندلس مركبًا كبيرًا لم يُعمَلْ مِثلُه، وسيَّرَ فيه أمتعةً إلى بلادِ الشرق، فلقِيَ في البَحرِ مَركبًا فيه رسولٌ مِن صقليَّةَ إلى المُعِزِّ، فقطع عليه أهلُ المركب الأندلسيُّ، وأخذوا ما فيه، وأخذوا الكتُبَ التي إلى المعِزِّ، فبلغ ذلك المعِزَّ، فعمَّرَ أسطولًا واستعمل عليه الحسَنَ بنَ علي صاحِبَ صقليَّة، وسيَّرَه إلى الأندلس، فوصلوا إلى المرية، فدخلوا المرسى، وأ"},{"id":1185,"era":"c4","t":"لعن ملوك الشيعة على منابر الأندلس .","s":"أمَرَ النَّاصِرُ بالأندلسِ بإطلاقِ اللَّعنِ على ملوكِ الشِّيعةِ بجميعِ منابرِ الأندلسِ، وإنفاذِ كُتُبِه بذلك إلى العُمَّالِ بسائر الأقطار."},{"id":1186,"era":"c4","t":"خروج روزبهان الديلمي على معز الدولة البويهي .","s":"عَصِيَ روزبهان الديلميُّ على معِزِّ الدولة وانحاز إلى الأهوازِ ولَحِقَ به عامَّةُ من كان مع المهلبي وزيرِ مُعِزِّ الدولة الذي كان يحارِبُه، فلمَّا بلغ ذلك مُعِزَّ الدولةِ لم يصَدِّقْه؛ لأنَّه كان قد أحسن إليه ورفع مِن قَدْرِه بعد الضَّعةِ والخمول، ثم تبيَّنَ له أنَّ ذلك حَقٌّ، فخرج لقتالِه وتَبِعَه الخليفةُ المطيع لله خوفًا مِن ناصرِ الدَّولةِ بنِ حمدان؛ فإنَّه قد بلغه أنَّه جهَّزَ جَيشًا مع ولدِه"},{"id":1187,"era":"c4","t":"غزو الروم من قبل سيف الدولة الحمداني .","s":"سار سَيفُ الدولة بن حمدان في جيوشٍ إلى بلاد الروم وغزاها، حتى بلغ خرشنة، وصارخة، وفتح عِدَّةَ حُصونٍ وسَبى وأسر، وأحرقَ وخرَّب، وأكثَرَ القتلَ فيهم، ورجع إلى أذنة فأقام بها حتى جاءه رئيسُ طرسوس، فخلع عليه وأعطاه شيئًا كثيرًا، وعاد إلى حَلَب، فلمَّا سَمِعَ الروم بما فعل جمعوا وساروا إلى ميافارقين، وأحرقوا سوادَها ونهبوه، وخربوا وسَبَوا أهلَها، ونهبوا أموالهم وعادوا، وفي جمادى الآخرة سار الرومُ في ا"},{"id":1188,"era":"c4","t":"وفاة السلار المرزبان حاكم بلاد أذربيجان .","s":"هو المرزبان بن محمَّد بن مسافر بن السلار، وهو صاحِبُ أذربيجان، كان قد تآمرَ مع أخيه وهسوذان على والديهما، واستولَيا على بعضِ قلاعه، وكان السببُ سوءَ معامَلتِه معهما ومع غيرِهما، ثم إنَّهما قبضا على أبيهما محمَّدِ بنِ مسافر، وأخذا أموالَه وذخائِرَه، وبَقِيَ في حصنٍ آخَرَ وحيدًا فريدًا بغيرِ مالٍ ولا عُدَّة. وقع المرزبان في الأسرِ عند ركن الدولةِ البويهي, فحبَسَه في قلعة سميرم، فاحتال حتى فكَّ قَيدَ"},{"id":1189,"era":"c4","t":"الخلاف بين ناصر الدولة الحمداني ومعز الدولة البويهي .","s":"رَكِبَ مُعِزُّ الدولة إلى المَوصِل فأخذها من يد ناصِرِ الدَّولةِ؛ وذلك أن الأخيرَ امتنَعَ مِن أداء الخَراجِ الذي تعهَّدَ به لقاءَ إمارتِه المَوصِلَ، ثم هرب ناصِرُ الدولة إلى نصيبينَ، ثم إلى ميافارقين، فلَحِقَه مُعِزُّ الدولة فصار إلى حَلَب عند أخيه سيفِ الدولة، ثم أرسل سيفُ الدولة إلى معِزِّ الدولة في المصالحةِ بينه وبين أخيه، فوقع الصُّلحُ على أن يحمِلَ ناصر الدولةِ في كلِّ سنةٍ ألفي ألف وتسعمائة"},{"id":1190,"era":"c4","t":"وفاة ابن دُرُسْتُويه النحوي المشهور .","s":"هو أبو مُحمَّد عبد الله بن جعفر بن دُرُسْتوَيه بن المرزبان أبو محمَّد الفارسي الفسوي النحوي. ولد سنة 258، بفَسا ثم انتقلَ في صباه إلى بغداد, واستوطنها, وبرع في العربية، وصنَّف التصانيفَ, ورُزِقَ الإسنادَ العاليَ, وكان ثِقةً. كان أبوه من كبارِ المحَدِّثين وأعيانِهم. ودُرُسْتُويه: بضم الدال والراء وسكون السين، وضم التاء، وقيل: بفتح الدال والراء والواو، كان عالِمًا فاضلًا أخذ فَنَّ الأدب عن عبَّاسِ ا"},{"id":1191,"era":"c4","t":"مسير جيوش المعز العبيدي (الفاطمي) إلى أقاصي المغرب .","s":"عظُمَ أمرُ أبي الحسَنِ جوهَرِ الصِقليِّ عند المعِزِّ بإفريقيَّة، وعلا محَلُّه، وصار في رُتبة الوزارة، فسَيَّرَه المعِزُّ في صفر في جيشٍ كثيفٍ، فيهم زيري بن مناد الصنهاجي وغيره، وأمره بالمسير إلى أقاصي المغربِ، فسار إلى تاهرت، ومدينة أفكان، دخَلَها بالسيف، ونهبها، ونهب قصور يعلى، وأخذ ولده، وكان صبيًّا، وأمر بهدم أفكان وإحراقِها بالنار، ثم سار منها إلى فاس، وبها صاحِبُها أحمد بن بكر، فأغلق أبوابَها"},{"id":1192,"era":"c4","t":"هجوم الروم على المسلمين في الشام .","s":"خرج مُحمَّدُ بنُ ناصر الدولة بن حمدان في سَريَّةٍ نحوَ بلاد الروم، وكانت الرومُ قد وصلوا إلى الرَّها وحرَّان فأسروا أبا الهيثمِ ابنَ القاضي أبي الحُصَين وسَبَوا وقتلوا، وفي هذه السنة مات مَلِكُ الروم وطاغيتُهم الأكبر بالقُسطنطينية، وأقعَدَ ابنَه مكانَه، ثم قُتِلَ ونُصِبَ في الملك غيرُه، وفي هذه السَّنَة وصلت الرومُ إلى طرسوس فقتلوا جماعةً وفَتَحوا حِصنَ الهارونية وخَرَّبوا الحِصنَ المذكورَ وقَتَلو"},{"id":1193,"era":"c4","t":"وفاة أمير دولة الإخشيد بمصر وتولي أخيه مكانه .","s":"هو أنوجور بنُ الإخشيدِ مُحمَّد، تولَّى إمرةَ مِصرَ صَغيرًا، فكان الذي يتحَكَّمُ بالأمور كُلِّها كافور، ولَمَّا كَبِرَ أنوجور حصَلَت بينه وبين كافور وَحشةٌ؛ بسبب استبدادِ كافور بالحُكم والاسمُ لأنوجور، ولكِنْ لم يلبث أن توفِّيَ أنوجور في آخِرِ هذه السنة وحُمِلَ إلى القدس ودُفِنَ بجوار والده، بعد أن كانت مُدَّة ولايته أربع عشرة سنة، فخَلَّفَه أخوه عليٌّ الإخشيدي وأقَرَّه الخليفةُ على ذلك، ولكِنْ بقي"},{"id":1194,"era":"c4","t":"البيزنطيون يعاودون احتلال جزيرة كريت .","s":"أخذ مَلِكُ الرومِ رومانوس بن قُسطَنطين من المسلمين جزيرةَ أقريطش (كريت) من بلادِ المغرب، وكان الذي افتتح أقريطشَ عُمَرَ بنَ شُعَيبٍ، غزاها وافتتحها في حدودِ سنةِ ثلاثين ومائتين، وصارت في يدِ أولادِه إلى هذا الوقتِ."},{"id":1195,"era":"c4","t":"معز الدولة البويهي يبني دارا عظيمة ببغداد بعد أن أصابه المرض .","s":"مَرِضَ مُعزُّ الدولة بن بُوَيه بانحصارِ البَولِ، فقَلِقَ من ذلك وجمَعَ بين صاحبه سبكتكين ووزيره الحسَن المهلبي، وأصلح بينهما ووصَّاهما بوَلَدِه بختيار خيرًا، ثم عوفيَ مِن ذلك فعزم على الرَّحيلِ إلى الأهواز لاعتقادِه أنَّ ما أصابه مِن هذه العِلَّة بسبَبِ هواءِ بغداد ومائِها، فأشاروا عليه بالمُقام بها، وأن يبني بها دارًا في أعلاها حيث الهواءُ أرَقُّ والماءُ أصفى، فبَنى له دارًا غرِمَ عليه ثلاثة عشر "},{"id":1196,"era":"c4","t":"وفاة عبد الرحمن الناصر الأموي أمير الأندلس وتولي ابنه المستنصر الحكم .","s":"هو أميرُ المؤمنين، الناصِرُ لدينِ الله، أبو المطرِّف عبد الرحمن بن محمد بن عبد الله بن محمد بن عبد الرحمن بن الحكم بن هشام بن الداخل عبد الرحمن، كان أبوه محمَّدٌ وَلِي عَهْد والده عبد الله بن محمد، فقَتَله أخوه أبو القاسِمِ المطرِّف، فقَتَله أبوهما به. ولَمَّا قُتِلَ محمد، كان لابنِه عبد الرحمن عشرونَ يومًا. ووليَ الخلافةَ بعد جَدِّه عبد الله. قال ابن حزم: \"كانت خلافتُه من المُستطرَف؛ لأنَّه كان ش"},{"id":1197,"era":"c4","t":"وفاة الأمير عبد الملك بن نوح الساماني .","s":"هو عبدُ المَلِك بنُ نوحٍ الساماني صاحِبُ خُراسان وغزنة وما وراءَ النَّهرِ. تولَّى حُكْمَ الدَّولةَ السامانيَّةَ بعد والده, وكان في العاشرةِ مِن عُمُرِه، وكان ضعيفَ الهيبةِ ولم يَقُم بشَيءٍ للمُحافظة على وَحدةِ دَولتِهم، وكان سبَبُ مَوتِه أنَّه سقط عن فَرَسِه فوقع ميتًا وافتُتِنَت خراسان بعده، فقام بالأمرِ مِن بعده أخوه منصورُ بنُ نوح الساماني. وفي عهدِ منصور بدأت الدَّولةُ في الضَّعفِ بسبَبِ خروجِ"},{"id":1198,"era":"c4","t":"البيزنطيون يهاجمون حلب ويدمرونها ويذبحون أهلها .","s":"كان دخولُ الرُّومِ إلى حَلَب بصحبة الدُّمُسْتُق مَلِك الروم، في مائتي ألفِ مقاتل، وكان سببُ ذلك أنَّه ورَدَ إليها بغتةً فنهَضَ إليه سيفُ الدولة بن حمدان بمن حضَرَ عنده من المقاتِلة، ولم يتمَكَّنوا من مقاوَمتِه لكثرةِ جُنودِه، وقَتَلَ مِن أصحاب سيف الدولة خلقًا كثيرًا، وكان سيفُ الدولة قليلَ الصبرِ ففَرَّ منهزمًا في نفرٍ يسيرٍ مِن أصحابه، فأوَّل ما استفتح به الدُّمُسْتُق- قبَّحه الله- أن استحوذ على"},{"id":1199,"era":"c4","t":"استيلاء ركن الدولة بن بويه على طبرستان وجرجان .","s":"سار ركنُ الدَّولةِ إلى طبرستان، وبها وشمكير بنُ زيار الديلمي، فنزل على مدينةِ سارية فحصرها ومَلَكها، ففارق حينئذٍ وشمكيرُ طبرستان وقصَدَ جرجان، فأقام ركنُ الدولة بطبرستان إلى أنْ مَلَكَها كُلَّها، وأصلح أمورَها، وسار في طلَبِ وشمكير إلى جرجان، فأزاح وشمكيرَ عنها، واستولَّى عليها، واستأمَنَ إليه مِن عَسكرِ وشمكير ثلاثةُ آلاف رجل، فازداد قوَّةً، وازداد وشمكيرُ ضعفًا ووهَنًا فدخل بلادَ الجيل."},{"id":1200,"era":"c4","t":"احتلال الروم لمدينة عين زربة في آسيا الصغرى .","s":"دخلَت الرُّومُ عينَ زربة- مدينةٌ قديمةٌ في آسيا الصغرى بناها الرومُ وجَدَّدَ بناءَها الرشيدُ سنة 180- بصُحبة الدُّمُسْتُق، فاستأمنه أهلُها فأمَّنَهم، وأمر بأن يدخُلوا كلُّهم المسجِدَ ومَن بَقِيَ في منزله قُتِلَ، فصاروا إلى المسجِدِ كُلُّهم، ثم قال: لا يبقينَّ أحَدٌ مِن أهلها اليوم إلَّا ذهب حيث شاء، ومن تأخَّرَ قُتِل، فازدحموا في خروجِهم من المسجدِ فمات كثيرٌ منهم، وخرجوا على وجوهِهم لا يدرونَ أين"},{"id":1201,"era":"c4","t":"ذكر ما كتب على مساجد بغداد من قبل الرافضة .","s":"كتَبَ عامَّةُ الشيعة ببغداد، بأمرِ مُعِزِّ الدولة، على المساجِدِ ما هذه صورتُه: لعن الله معاوية بن أبي سفيان، ولعن من غصب فاطمة، رضي الله عنها، فدكًا، (يعنون أبا بكر الصديق رضي الله عنه) ومن منع من أن يُدفَن الحسن عند قبر جَدِّه، عليه السلام (يعنون مروان بن الحكم)، ومن نفى أبا ذرٍّ الغفاريَّ (يعنون عثمان بن عفان رضي الله عنه)، ومَن أخرج العبَّاس من الشورى (يعنون عمر بن الخطاب رضي الله عنه)، فأمَّا"},{"id":1202,"era":"c4","t":"فتح المسلمين قلعة طبرمين في صقلية .","s":"سارت جيوشُ المُسلِمينَ بصقليَّة، وأميرُهم حينئذ أحمدُ بن الحسن بن علي بن أبي الحسين الكلبي، إلى قلعةِ طبرمين من صقليَّة أيضًا، وهي بيدِ الرومِ، فحصروها، وهي مِن أمنع الحصون وأشَدِّها على المسلمين، فامتنع أهلُها، ودام الحصارُ عليهم، فلما رأى المسلمونَ ذلك عَمَدوا إلى الماءِ الذي يدخُلُها فقطعوه عنها، وأجروه إلى مكانٍ آخَرَ، فعَظُمَ الأمر عليهم، وطَلَبوا الأمان، فلم يُجابوا إليه، فعادوا وطَلَبوا أن "},{"id":1203,"era":"c4","t":"أمر المعز البويهي ببدعة عاشوراء وببدعة الغدير .","s":"في هذه السَّنةِ عاشِرَ المحَرَّم أمرَ مُعِزُّ الدولة الناسَ أن يُغلِقوا دكاكينَهم، ويُبطِلوا الأسواقَ والبيعَ والشِّراءَ، وأن يُظهِروا النياحةَ، ويلبسوا قبابًا عَمِلوها بالمُسوح، وأن يَخرُجَ النساء مُنشِراتٍ الشُّعورَ، مُسَوِّداتٍ الوُجوهَ، قد شَقَقنَ ثيابَهنَّ، يَدُرنَ في البلد بالنوائحِ، ويَلطمْنَ وجوهَهنَّ على الحسين بن عليِّ، رضي الله عنهما، ففعل النَّاسُ ذلك، ولم يكن للسُّنَّة قُدرةٌ على المن"},{"id":1204,"era":"c4","t":"أهلُ طرسوس يغزون بلادَ الروم ويصلون إلى مدينة قونية .","s":"دخل أهلُ طرسوس بلادَ الروم غازين، ودخلها أيضًا نجا غلامُ سيفِ الدولة بن حمدان من دربٍ آخر، ولم يكن سَيفُ الدولة معهم لِمَرضِه؛ فإنَّه كان قد لَحِقَه قبل ذلك بسنتين فالجٌ، فأقام على رأس دربٍ من تلك الدروب، فأوغل أهلُ طرسوس في غزوتِهم حتى وصلوا إلى قونية وعادوا."},{"id":1205,"era":"c4","t":"تمرد هبة الله بن ناصر الدولة الحمداني وعصيان أهل حران .","s":"لَمَّا رجَعَ سَيفُ الدولة إلى حَلَب من غزو الروم، كان لحِقَه في الطريق غشيةٌ أرجَفَ عليه الناسُ بالموت، فوثب هبةُ الله ابنُ أخيه ناصر الدولة بن حمدان بابنِ دنجا النصراني فقتَلَه، وكان خصيصًا بسيفِ الدولة، وإنما قتَلَه لأنَّه كان يتعَرَّضُ لغلام له، فغار لذلك، ثمَّ أفاق سيفُ الدولة، فلَمَّا عَلِمَ هِبةُ الله أن عمه لم يمُتْ هَرَب إلى حرَّان، فلما دخلها أظهر لأهلِها أنَّ عَمَّه مات، وطلب منهم اليمين"},{"id":1206,"era":"c4","t":"الروم يحاصرون مدينة المصيصة ووصول جيش المسلمين من خراسان .","s":"حصر الرُّومُ مع الدُّمُسْتُق بن الشمشقيق المصيصةَ، وقاتلوا أهلَها، ونَقَبوا سورَها، واشتد قتالُ أهلِها على النَّقبِ حتى دفعوهم عنه بعد قتالٍ عظيمٍ، وأحرق الرومُ بيوتها ومزارعها ومزارع أذنة وطرسوس لِمُساعدتهم أهلَها، فقُتِلَ من المسلمين خمسةَ عشرَ ألفَ رجل، وأقام الروم في بلادِ الإسلام خمسة عشر يومًا لم يَقصِدْهم من يقاتِلُهم، فعادوا لغلاءِ الأسعارِ وقِلَّة الأقوات، ثمَّ قَدِمَ إلى الشام من خُراسان"},{"id":1207,"era":"c4","t":"الروم يحاصرون مدينة طرسوس .","s":"نزل مَلِكُ الرومِ على طرسوس وحَصَروها، وجرى بينهم وبين أهلِها حروبٌ كثيرةٌ سقط في بعضها الدُّمُسْتُق بن الشمشقيق إلى الأرضِ، وكاد يُؤسَرُ، فقاتل عليه الرومُ وخَلَّصوه، وأسَرَ أهلُ طرسوس بِطريقًا كبيرًا من بَطارقةِ الرُّومِ، ورحل الرُّومُ عنهم، وتركوا عسكرًا على المصيصةِ مع الدُّمُسْتُق، فحصرها ثلاثةَ أشهر لم يمنَعْهم منها أحد، فاشتَدَّ الغلاءُ على الرومِ، وكان شديدًا قبل نزولِهم، فلهذا طَمِعوا في "},{"id":1208,"era":"c4","t":"العبيديون الفاطميون يهزمون الروم في وقعة المختار .","s":"أقبل من الرُّومِ خَلقٌ كثير، ومن الفرنجِ ما يقارِبُ مائةَ ألفٍ، فبعث أهلُ صقليَّةَ إلى المُعِزِّ الفاطمي يستنجِدونَه، فبعث إليهم جيوشًا كثيرة في الأسطول، وكانت بين المسلمينَ والروم وقعةٌ عظيمة صبر فيها الفريقانِ مِن أوَّلِ النهار إلى العصر، ثم قُتِلَ أميرُ الروم منويل، وفَرَّت الروم وانهزموا هزيمةً قبيحةً، فقتل المسلمون منهم خلقًا كثيرًا وسقط الفرنجُ في وادٍ مِن الماء عميقٍ، فغرق أكثَرُهم وركب الب"},{"id":1209,"era":"c4","t":"محاولة القرامطة الهجوم على طبرية ودعم سيف الدولة الحمداني لهم  .","s":"قَصَدت القرامِطةُ مدينةَ طَبَريَّة ليأخذوها من يدِ الإخشيدِ صاحِبِ مصرَ والشَّامِ، وطلبوا من سيفِ الدولة أن يُمِدَّهم بحديدٍ يتَّخِذونَ منه سلاحًا، فقلع لهم أبوابَ الرقَّة- وكانت من حديدٍ صامتٍ- وأخذ لهم من حديدِ النَّاسِ، حتى أخذ أواقيَ الباعةِ والأسواق، وأرسل بذلك كُلِّه إليهم، فأرسلوا إليه يقولون اكتَفَينا."},{"id":1210,"era":"c4","t":"اقتتال الرافضة والسنة بسبب عمل عزاء الحسين في بغداد .","s":"كان مُعِزُّ الدولة البويهيُّ قد أمر بعمَلِ عزاءِ يوم عاشوراء، فكان هذه السَّنةَ أن قام الرافِضةُ بعمل العزاءِ في العاشر من محرَّمٍ؛ مما أثار السُّنَّةَ عليهم فحصل اقتتالٌ شديدٌ بينهم وحصل نهبٌ للأموال كذلك."},{"id":1211,"era":"c4","t":"معز الدولة البويهي يسيطر على مدينة الموصل .","s":"كان قد استَقَرَّ الصُّلحُ بين ناصرِ الدولة الحمداني وبين مُعِزِّ الدولة البويهي على ألف ألف درهم يحمِلُها ناصِرُ الدولة كل سنة، فلمَّا حصلت الإجابةُ مِن مُعِزِّ الدولة بذل زيادةً ليكونَ اليمينُ أيضًا لوَلَدِه أبي تغلب فضل الله الغضنفر معه، وأن يحلِفَ مُعِزُّ الدولة لهما، فلم يُجِبْ إلى ذلك، وتجهَّزَ مُعِزُّ الدولة وسار إلى المَوصِل في جمادى الآخرة، فلما قاربها سار ناصِرُ الدولة إلى نصيبين، ووصل مع"},{"id":1212,"era":"c4","t":"جولة معز الدولة البويهي في بغداد .","s":"طلب مُعِزُّ الدولة من الخليفةِ أن يأذَنَ له في دخولِ دارِ الخلافة ليتفرَّجَ فيها فأذِنَ له فدخَلَها، فبعث الخليفةُ خادِمَه وصاحِبَه معه فطافوا بها وهو مُسرِعٌ خائِفٌ، ثم خرج منها وقد خاف مِن غائلة ذلك وخشي أن يُقتَلَ في دهاليزِها، فتصَدَّقَ بعَشرةِ آلاف لَمَّا خرج؛ شكرًا لله على سلامتِه، وازداد حبًّا في الخليفةِ المطيعِ مِن يومئذٍ."},{"id":1213,"era":"c4","t":"ثورة رجل من القرامطة على سيف الدولة .","s":"ثار رجلٌ من القرامطةِ اسمُه مَروانُ، كان يحفُظُ الطُّرُقاتِ لِسَيفِ الدولة، ثار بحِمص فمَلَكها وما حولها، فقَصَده جيشٌ من حلب مع الأميرِ بدرٍ فاقتتلوا معه فرماه بدرٌ بسَهمٍ مسمومٍ فأصابَه، واتَّفَق أنْ أسَرَ أصحابُ مَروانَ بدرًا فقَتَله مروانُ بين يديه صبرًا، ومات مروان بعد أيَّامٍ وتفَرَّقَ عنه أصحابُه."},{"id":1214,"era":"c4","t":"وفاة المتنبي الشاعر .","s":"هو شاعِرُ الزَّمانِ المَشهورُ، أبو الطَّيِّب أحمَدُ بنُ حُسَين بن حسن الجعفي الكوفي, الأديبُ الشهيرُ بالمتنبي. ولد سنة 303 بالكوفة في مَحلَّةٍ تسمى كندة فنُسِبَ إليها، وليس هو من كِندَةَ القبيلة، بل هو جعفيٌّ. قَدِمَ الشامَ في صباه, ثم أقام بالبادية يقتَبِسُ اللغة والأخبار, واشتغل بفنونِ الأدب ومَهَر فيها، وكان من المُكثِرينَ مِن نقلِ اللغة والمطَّلِعينَ على غَريبِها وحواشيها، ولا يُسألُ عن شَيءٍ "},{"id":1215,"era":"c4","t":"طاعة أهل عمان لمعز الدولة البويهي .","s":"سيَّرَ مُعِزُّ الدولةِ عَسكرًا إلى عمانَ، فلَقُوا أميرَها، وهو نافِعٌ مولى يوسُفَ بنِ وجيه، وكان يوسُفُ قد هلك، وملَكَ نافِعٌ البلدَ بَعدَه، فدخل نافِعٌ في طاعةِ مُعِزِّ الدولة، وخطب له، وضرب له اسمَه على الدينارِ والدِّرهمِ، فلمَّا عاد العسكرُ عنه وثبَ به أهلُ عمانَ فأخرجوه عنهم، وأدخلوا القرامِطةَ الهَجَريِّينَ إليهم وتسَلَّموا البلد، فكانوا يقيمونَ فيه نهارًا ويخرجونَ ليلًا إلى مُعسكَرِهم، وكتب"},{"id":1216,"era":"c4","t":"الفتنة ببغداد بسبب العزاء يوم عاشوراء .","s":"بتشجيعٍ مِن البُويهيِّينَ عَمِلَت الشيعةُ في العاشر من محرَّم مآتِمَهم وبِدعَتَهم، وغُلِّقَت الأسواقُ وعُلِّقَت المُسوحُ، وخَرَجت النساءُ سافراتٍ ناشراتٍ شُعورَهنَّ، يَنُحْنَ ويلطمْنَ وجوهَهنَّ في الأسواقِ والأزِقَّة على الحسين، وهذا تكُلُّفٌ لا حاجة إليه في الإسلامِ، ولو كان هذا أمرًا محمودًا لفعله خيرُ القرون وصَدرُ هذه الأمة وخِيرتُها، وهم أولى به، وأهلُ السنة يَقتَدونَ ولا يَبتَدِعونَ، ثمَّ تس"},{"id":1217,"era":"c4","t":"دخول الروم المصيصة وطرسوس .","s":"قَدِمَ مَلِكُ الروم بجيشٍ كثيفٍ إلى المصيصة فأخذها قسرًا وقتَلَ مِن أهلها خلقًا، واستاق بقِيَّتَهم معه أسارى، وكانوا قريبًا من مائتي ألف، ثم جاء إلى طرسوس فسأل أهلُها منه الأمانَ فأمَّنَهم وأمَرَهم بالجلاءِ عنها والانتقال منها، واتخذَ مَسجِدَها الأعظمَ إسطبلًا لخيولِه وحَرَقَ المنبرَ ونقل قناديلَه إلى كنائِسِ بلَدِه، وتنصَّرَ أهلُها معه، وكان أهلُ طرسوس والمصيصة قد أصابهم قبلَ ذلك بلاءٌ وغلاءٌ عَظ"},{"id":1218,"era":"c4","t":"وفاة ابن حبان صاحب الصحيح .","s":"هو الإمامُ العلَّامةُ الحافِظُ المجَوِّدُ, شيخُ خُراسان, أبو حاتمٍ, محمَّدُ بنُ حِبَّان بن أحمد بن حبان بن معاذ بن معبد بن سهيد بن هدية بن مُرة التميمي الدارمي البُستي، ولِدَ سنة بِضعٍ وسَبعينَ ومائِتين. صاحِبُ الكُتُب المشهورة. ومنها كتابُ الأنواع والتقاسيم، المعروف باسم (صحيح ابن حبان)، كان مِن أوعيةِ العِلمِ، برع في الحديثِ والفِقهِ واللُّغةِ والوَعظِ، تنقَّلَ في الأقطارِ لطَلَبِ العِلمِ، له تص"},{"id":1219,"era":"c4","t":"تولي كافور حكم الدولة الإخشيدية بمصر .","s":"بعد أن تولى عليُّ بنُ الإخشيد حُكمَ مِصرَ بعد موت أخيه أنوجور، فسَدَ ما بينه وبين مدبِّر مملكته كافور الإخشيدي، فمنع كافور النَّاسَ مِن الاجتماعِ بعَليِّ بنِ الإخشيد حتى اعتَلَّ بعِلَّةِ أخيه أنوجور ومات لإحدى عشرة خَلَت من المحَرَّم وحُمِلَ إلى المقدس ودفن عند أبيه الإخشيد وأخيه أنوجور، وبَقِيَت مصر من بعده أيامًا بغير أميرٍ، وكافور يدبِّرُ أمرَها على عادته في أيَّامِ أولاد الإخشيد ومعه أبو الفضل"},{"id":1220,"era":"c4","t":"فداء أسرى المسلمين من الروم .","s":"وقعَ الفِداءُ بين سيفِ الدَّولةِ وبين الرومِ، فاستنقذ منهم أُسارى كثيرةً، منهم ابنُ عَمِّه أبو فِراس بن سعيد بن حمدان، وأبو الهيثم بن حصن القاضي، وذلك في رجب منها، ولَمَّا لم يبقَ مع سيف الدَّولةِ مِن أسرى الرومِ أحَدٌ اشترى الباقينَ مِن أسارى المسلمينَ كُلَّ نَفسٍ باثنينِ وسبعينَ دينارًا، حتى نفِدَ ما معه من المال, فاشترى الباقينَ ورهن عليهم بدَنَتَه الجوهرَ المعدومةَ المِثْل، فقد أنفق في سنةٍ وث"},{"id":1221,"era":"c4","t":"خروج الروم إلى بلاد الإسلام .","s":"خرجَت الرُّومُ قاصِدةً مدينة آمد، فنَزَلوا عليها وحصروها وقاتلوا أهلَها، فقُتِلَ منهم ثلاثُمائة رجلٍ، وأُسِرَ نحوُ أربعمائة أسيرٍ، ولم يمكِنْهم فتحُها، فانصرفوا إلى دارا، وقرُبوا من نصيبين، ولَقِيَهم قافلةٌ واردة من ميافارقين، فأخذوها، وهربَ النَّاسُ من نصيبين خوفًا منهم، حتى بلَغَت أجرة الدابَّة مائة درهم، وراسل سيفُ الدولة الأعرابَ ليهرَبَ معهم، وكان في نصيبين، فاتَّفَق أنَّ الرُّومَ عادوا قبل ه"},{"id":1222,"era":"c4","t":"وفاة معز الدولة بن بويه .","s":"هو السُّلطانُ مُعِزُّ الدولة أبو الحسين, أحمدُ بنُ بُوَيه بن فنا خسرو بن تمام بن كوهي الديلمي الفارسي الشيعي, كان أبوه سمَّاكًا, وهو ربَّما احتطب. تملَّك العراق نيفًا وعشرين سنة بلا كُلفةٍ، ودانت له الأُمَم, ولَمَّا تغَلَّب على بغداد سنة 334 لقَّبَه الخليفةُ المستكفي بمعزِّ الدولة، وتولى منصِبَ أميرِ الأمراء، وبدا بتسَلُّطه على الخليفة فأصرَّ أن يُذكَرَ اسمُه مع اسمِ الخليفةِ في خُطبة الجمعة، وأن "},{"id":1223,"era":"c4","t":"وفاة أبي الفرج الأصبهاني صاحب كتاب الأغاني .","s":"هو العلَّامة، الأخباريُّ أبو الفَرَج عليُّ بنُ الحسين بن محمَّد بن أحمد بن الهيثم بن عبد الرحمن بن مروان بن محمد بن مروان بن الحكم الأموي، وجَدُّه مروان بن محمَّد آخِرُ خُلَفاء بني أمية، وهو أصبهانيُّ الأصل بغداديُّ المنشأ، كان من أعيانِ أُدَبائِها، وأفراد مُصَنِّفيها, صاحِبُ كتاب الأغاني، وكتاب أيَّام العرب، ذكَرَ فيه ألفًا وسَبعمائة يومٍ مِن أيامهم، وكان شاعرًا أديبًا كاتبًا، عالِمًا بأخبار النا"},{"id":1224,"era":"c4","t":"ظهور رجل ببغداد ادعى أنه المهدي .","s":"شاع الخبَرُ ببغداد وغيرِها من البلاد أنَّ رَجُلًا ظهَرَ يقالُ له مُحمَّدُ بنُ عبد الله وتلقَّب بالمهديِّ وزعم أنَّه الموعود به، وأنه يدعو إلى الخيرِ وينهى عن الشر، ودعا إليه ناسٌ من الشيعة، وقالوا: هذا عَلَويٌّ مِن شِيعتِنا، وكان هذا الرجلُ إذ ذاك مقيمًا بمصر عند كافور الإخشيدي قبل أن يموتَ، وكان يُكرِمُه، وكان من جملةِ المُستحسِنينَ له سبكتكين حاجِبُ مُعزِّ الدولة البويهي، وكان شيعيًّا فظَنَّه عَ"},{"id":1225,"era":"c4","t":"وفاة أبي فراس الحمداني الأمير والشاعر .","s":"هو أبو فِراسٍ الحارِثُ بنُ سعيد بن حمدان بن حمدون الحمداني ابنُ عَمِّ ناصر الدولة وسيف الدولة ابني حمدان، كان رأسًا في الفروسية والجُود, وبراعةِ الأدب وكان شاعِرًا وأميرًا, قال الصاحِبُ بن عبَّاد: \" بُدئَ الشِّعرُ بمَلِك وهو امرؤُ القَيسِ, وخُتِمَ بمَلِك وهو أبو فراسٍ\". فكان عامِلَ منبج لسيفِ الدَّولة الحمداني، وله وقائِعُ كثيرة. أُسِرَ مِن قِبَلِ الرومِ، وبقي أربع سنين في أسْرِهم، تناوَلَ في شِعر"},{"id":1226,"era":"c4","t":"وفاة كافور الإخشيدي بمصر .","s":"هو أبو المسك كافورُ بنُ عبد الله الإخشيديُّ، كان يلقَّبُ بالأستاذ، كان عبدًا نوبيًّا اشتراه السُّلطانُ أبو بكر محمد بن طغج الإخشيد بثمانيةَ عشرَ دينارًا سنة 312 بمصرَ مِن محمود بن وهب بن عبَّاس، وأعتقه ورَقى به حتى صار أتابِكَ- أي مربي- وَلَدَيه، فكان من كبارِ قُوَّادِه، وكان قد تمَلَّكَ أمرَ مِصرَ في ولايةِ أبي القاسِمِ الإخشيدي، فكانت زمامُ الأمور بيَدِه هو لا بيَدِ أميرِ مِصرَ الإخشيدي، ثمَّ لَ"},{"id":1227,"era":"c4","t":"نهاية الدولة الإخشيدية بمصر .","s":"كانت نهايةُ الدَّولةِ الإخشيديَّة بعد أن توفِّيَ كافورُ الإخشيدي، حيثُ مَلَك بعده أحمدُ بنُ علي الإخشيدي عِدَّة أشهُرٍ، وأمورُ مِصرَ كانت سيِّئةً جدًّا، فالغلاء من جهةٍ والقَحطُ من جهة أخرى، وكثرة المغاربة من طرَفِ الفاطميِّينَ مِن جهةٍ أيضًا، فصارت أمورُ الدولة لا زمام لها؛ ممَّا أغرى المعِزَّ الفاطميَّ بالهجومِ عليها، فأرسل القائِدَ جَوهَرَ الصِّقليَّ فدخلها فكانت هذه نهايةَ الدَّولةِ الإخشيديَّ"},{"id":1228,"era":"c4","t":"العُبيديون (الفاطميون) يسيطرون على الشام .","s":"لَمَّا استقَرَّ جوهر بمصر، وثبت قدَمُه، سيَّرَ جَعفرُ بنُ فلاح الكتامي إلى الشامِ في جمع كبيرٍ، فبلغ الرملة، وبها أبو محمَّد الحسن بن عبد الله بن طغج، فقاتله وجَرَت بينهما حروبٌ كان الظَّفَرُ فيها لجعفرِ بنِ فلاح، وأسَرَ ابنَ طغج وغيرَه من القوَّادِ فسَيَّرَهم إلى جوهر، وسيَّرَهم جوهر إلى المُعِزِّ بإفريقيَّة، ودخل ابنُ فلاح البلد عَنوةً، فقتَلَ كثيرًا من أهلِه، ثمَّ أمَّنَ مَن بَقِيَ، وجبى الخراج"},{"id":1229,"era":"c4","t":"أفعال الروم بالشام والجزيرة .","s":"دخل مَلِكُ الرُّومِ الشَّامَ، ولم يمنَعْه أحدٌ ولا قاتَلَه، فسار في البلادِ إلى طرابلس وأحرق بلدها، وحصَرَ قلعةَ عرقة، فمَلَكها ونَهَبها وسَبى من فيها، وكان صاحِبُ طرابلس قد أخرجه أهلُها لشِدَّةِ ظُلمِه، فقصد عرقة، فأخذه الرومُ وجميعَ مالِه، وكان كثيرًا، وقصَدَ مَلِكُ الروم حمصَ، وكان أهلُها قد انتقلوا عنها وأخلَوْها، فأحرقها ورجعَ إلى بلدانِ السَّاحِلِ فأتى عليها نهبًا وتخريبًا، ومَلَك ثمانية عشر"},{"id":1230,"era":"c4","t":"العُبيديون (الفاطميون) يدخلون مصر بقيادة جوهر الصقلي .","s":"سيَّرَ المعِزُّ الفاطميُّ القائِدَ أبا الحسَنِ جوهَرَ الصقليَّ، غلامَ والِدِه المنصور، وهو روميٌّ، في جيشٍ كثيفٍ إلى الديار المصرية، فاستولى عليها، وكان سببُ ذلك أنَّه لَمَّا مات كافور الإخشيدي، صاحِبُ مصر، اختلفت القلوبُ فيها، ووقع بها غلاءٌ شديد، فلما بلغ الخبَرُ بهذه الأحوال إلى المُعِزِّ، وهو بإفريقية، سيَّرَ جوهرًا إليها بجيشٍ عظيمٍ أنفق عليه ما جناه من البربَرِ مِن الضرائبِ، فكانت خمسمائة أل"},{"id":1231,"era":"c4","t":"بناء مدينة القاهرة عاصمة الدولة العبيدية (الفاطمية) .","s":"اختَطَّ جوهرُ الصِّقليُّ القائِدُ الفاطميُّ القصرَ وحفَرَ أساسَه في أوَّلِ ليلةِ نُزولِه القاهرة، وأدخل فيه ديرَ العظام، وبنى مكانها مَسجِدًا من داخل السور، وأدخل أيضًا قصرَ الشَّوك في القصر المذكور، وجعل للقَصرِ أبوابًا، وقيل دخل جوهر مِصرَ بعَسكرٍ عظيمٍ ومعه ألفُ حمل مال، ومن السِّلاح والعُدَد والخيل ما لا يُوصَف. فلما انتظم حالُه ومَلَك مِصرَ ضاقت بالجُندِ والرعيَّة، واختَطَّ سورَ القاهرة وبنى "},{"id":1232,"era":"c4","t":"البيزنطيون يحتلون أنطاكية .","s":"مَلَك الرُّومُ مدينةَ أنطاكيةَ، وسببُ ذلك أنَّهم حَصَروا حِصنًا بالقُربِ مِن أنطاكية يقالُ له حصنُ لوقا، وأنَّهم وافقوا أهلَه، وهم نصارى، على أن يرَتَحِلوا منه إلى أنطاكية، ويُظهِروا أنَّهم إنَّما انتَقَلوا منه خوفًا من الرومِ، فإذا صاروا بأنطاكية أعانوهم على فَتحِها، وانصرف الرومُ عنهم بعد موافقتِهم على ذلك، وانتقل أهلُ الحصن ونزلوا بأنطاكية بالقُربِ مِن الجبَلِ الذي بها، فلمَّا كان بعد انتقالِهم"},{"id":1233,"era":"c4","t":"وفاة الإمام الآجُرِّي .","s":"توفِّيَ الإمامُ المحَدِّثُ القُدوةُ، شيخُ الحَرَمِ الشَّريفِ، أبو بكرٍ محمَّدُ بنُ الحُسَين بنِ عبد الله البغدادي الآجُرِّيُّ، الفقيهُ الشَّافعيُّ المحَدِّث صاحِبُ كتاب الأربعين حديثًا، وهي مشهورة به، صاحب التواليف، منها: كتاب \" الشريعة في السُّنة \"، وكتاب \" الرؤية \"، وكتاب \" الغرباء \"، وكتاب \" الأربعين \"، وكتاب \" الثمانين \"، وكتاب \" آداب العلماء \"، وكتاب \" مسألة الطائفين \"، وكتاب \" التهجُّد \"، وغ"},{"id":1234,"era":"c4","t":"مصرع زيري زعيم قبيلة صنهاجة القوية بالمغرب .","s":"كان بين جَعفرِ بنِ عليٍّ، صاحِبِ مدينةِ مَسيلة وأعمالِ الزَّاب، وزِيري الصِّنهاجيِّ مُحاسَدةٌ، فلمَّا كثُرَ تقَدُّمُ زِيري عند المعِزِّ ساء ذلك جعفرًا، ففارق بلادَه ولَحِقَ بزناتة فقَبِلوه قَبولًا عظيمًا، ومَلَّكوه عليهم عداوةً لزِيري، وعصيَ جعفرٌ على المعِزِّ الفاطميِّ، فسار زيري إليه في جمعٍ كثيرٍ مِن صنهاجة وغيرِهم، فالتقوا في شهر رمضان، واشتد القتالُ بينهم، فكبا بزيري فرسُه، فوقعَ فقُتِل."},{"id":1235,"era":"c4","t":"القرامطة يسيطرون على مدينة دمشق بمدد من عز الدولة .","s":"أخَذَت القرامطةُ دِمشقَ وقَتَلوا نائِبَها جعفرَ بنَ فلاح الفاطميَّ، وكان رئيسُ القرامطة وأميرُهم الحُسَين بن أحمد بن بهرام وقد أمَدَّه عِزُّ الدولة البُويهي من بغداد بسِلاحٍ وعُدَدٍ كثيرةٍ، ثمَّ ساروا إلى الرَّملةِ فأخذوها وتحصَّنَ بها مَن كان بها من المغاربةِ نوابا، ثمَّ إن القرامطةَ تركوا عليهم من يحاصِرُها ثم ساروا نحو القاهرةِ في جمعٍ كثيرٍ مِن الأعراب والإخشيديَّة والكافوريَّة، فوصلوا عينَ شم"},{"id":1236,"era":"c4","t":"وفاة الطبراني صاحب المعاجم .","s":"هو الإمامُ الحافِظُ الثِّقةُ الرَّحَّالُ الجَوَّال, مُحَدِّثُ الإسلام, عَلَمُ المعَمَّرينِ, أبو القاسم سُليمان بن أحمد بن أيوب بن مطير اللخمي الشامي الطَّبَراني، نسبةً إلى طبَرِيَّة، مولدُه بمدينة عكَّا في شهر صفر سنة 260, وكانت أمُّه عكَّاوية. أحد الحُفَّاظ المكثرينَ الذين رحَلوا في البلاد كثيرًا شَرقًا وغَربًا وشَمالًا وجنوبًا، كان عالِمًا بالحديثِ والعِلَل والرِّجال، وأوَّل سماعٍ له في الحديث ك"},{"id":1237,"era":"c4","t":"إغارة الروم على الجزيرة .","s":"أغار مَلِكُ الرومِ على الرَّها ونواحيها، وسار في ديارِ الجزيرة الفراتية حتى بلغوا نصيبين، فغَنِموا، وسَبَوا، وأحرقوا وخرَّبوا البلاد، وفعلوا مثلَ ذلك بديارِ بكر، ولم يكُنْ من أبي تَغلِبَ بنِ حمدان في ذلك حركةٌ، ولا سعيَ في دَفعِه، لكنَّه حمل إليه مالًا كَفَّه به عن نفسِه، فسار جماعةٌ مِن أهل تلك البلادِ إلى بغداد مستنفرينَ، وقاموا في الجوامِعِ والمشاهِدِ، واستنفروا المسلمينَ، وذكروا ما فعَلَه الرو"},{"id":1238,"era":"c4","t":"الفتنة ببغداد بسبب إبطال غزو الروم .","s":"لَمَّا كان مِن أمرِ دُخولِ الرُّومِ وبُلوغِ الخبر إلى بغداد، وتجهَّزت العامَّةُ للغَزاةِ، وقعت بينهم فتنةٌ شديدة بين الروافض وأهل السُّنة، وأحرق أهلُ السُّنَّة دُورَ الرَّوافِضِ في الكرخ، وقالوا: الشَّرُّ كُلُّه منكم، وثار العيَّارون ببغداد يأخذون أموالَ النَّاسِ، وتناقَضَ النَّقيبُ أبو أحمد الموسوي والوزيرُ أبو الفضل الشيرازي، وأرسل بختيار عزُّ الدولة بن معز الدولة إلى الخليفةِ المُطيع لله يطلُبُ"},{"id":1239,"era":"c4","t":"بناء الجامع الأزهر بالقاهرة من قبل الفاطميين .","s":"جامِعُ الأزهرِ هو من أهَمِّ المساجِدِ في مصرَ وأشهرِها في العالمِ الإسلاميِّ. وهو أوَّلُ جامعٍ أُسِّسَ بالقاهرة، أنشأه القائِدُ جوهر الكاتب الصِّقليُّ مولى المعِزِّ لدينِ الله، لَمَّا اختَطَّ القاهرة، وابتدأ بناءَه في يوم السبت لستٍّ بقين من جمادى الأولى سنة 359، وكَمُل بناؤه لسبعٍ خَلَونَ مِن رمضان سنة 361."},{"id":1240,"era":"c4","t":"مسير المعز العبيدي (الفاطمي) إلى مصر .","s":"سار المعِزُّ الفاطميُّ من إفريقيَّة يريدُ الدِّيارَ المصريَّة، وكان أوَّل مسيرِه أواخِرَ شوَّال سنة 361 وكان أوَّل رحيله من المنصوريَّة، فأقام بسردانيَّة، وهي قريةٌ قريبةٌ مِن القيروان، ولحقه بها رجالُه وعُمَّالُه، وأهلُ بيته وجميعُ ما كان له في قَصرِه مِن أموال وأمتعةٍ وغير ذلك، وسار عنها واستعملَ على بلاد إفريقيَّةَ يوسُفَ بلكين بن زيري، وجعل على صقليَّةَ حسَن بنَ علي بن أبي الحُسَين، وجعل على ط"},{"id":1241,"era":"c4","t":"القتال بين الروم وهبةِ اللهِ بنِ ناصر الدولة بن حمدان .","s":"كانت وقعةٌ بينَ هبةِ اللهِ بنِ ناصر الدولة بن حمدانَ وبينَ الدُّمُسْتُق بناحية ميافارقين، وكان سبَبُها غزوَ الدُّمُسْتُق بلادَ الإسلام، ونهْبَه ديارَ ربيعة وديارَ بكرٍ، فلمَّا رأى الدُّمُسْتُق أنَّه لا مانِعَ له عن مرادِه قَوِيَ طَمَعُه على أخذِ آمد، فسار إليها وبها هزارمرد غلامُ أبي الهيجاء بن حمدان، فكتب إلى أبي تَغلِبَ يستصرِخُه ويستنجِدُه، ويُعلِمُه الحال، فسيَّرَ إليه أخاه أبا القاسِمَ هبةَ ا"},{"id":1242,"era":"c4","t":"تأسيس الدولة الزيرية (بني زيري) مكان العبيدية (الفاطمية) في إفريقية .","s":"لَمَّا سار المعِزُّ الفاطميُّ إلى مصرَ خَلَّفَ على إفريقيَّة يوسُفَ بلكين بن زيري، ولَمَّا عاد يوسف بلكين من وداعِ المعِزِّ أقام بالمنصوريَّة يعقِدُ الوِلاياتِ للعُمَّال على البلاد، ثم سار في البلاد، وباشرَ الأعمال، وطيَّبَ قُلوبَ الناس، وكان المعِزُّ يريد أن يستخلِفَ يوسُفَ بلكين على الغَربِ لقُوَّتِه، وكثرةِ أتباعه، ولكِنَّه كان يخاف أن يتغَلَّبَ على البلاد بعد مسيرِه عنها إلى مصر، فلما استحكَمَ"},{"id":1243,"era":"c4","t":"دخول المعز العبيدي الفاطمي مصر .","s":"بعد أن انتظم الأمرُ في مِصرَ للفاطميِّينَ تهيَّأَ المعِزُّ الفاطميُّ العُبَيديُّ للانتقالِ إليها، فسار بخزائِنِه وتوابيتِ آبائه. وكان دخولُه إلى الإسكندريَّة في شعبان سنة 362 وتلقَّاه قاضي مصر الذهلي وأعيانُها، فأكرمهم وطال حديثُه معهم وأظهر لهم أنَّ قَصْدَه الحَقُّ والجِهادُ، وأن يختِمَ عُمُرَه بالأعمالِ الصالحة، وزعم أنَّه يُقيمُ أوامِرَ جَدِّه رسولِ الله صلَّى الله عليه وسلم، ووعَظَ وذَكَّرَ حت"},{"id":1244,"era":"c4","t":"فتنة بالبصرة بين الديلم والأتراك  .","s":"كان سَببُها أنَّ عِزَّ الدولة بختيارَ بنَ مُعِزِّ الدولة قلَّت عنه الأموالُ، فتوَجَّه مع جندِه إلى الأهواز، ليتعَرَّضوا لبختكين آزادرويه، وكان متولِّيَها، ويعملوا له حُجَّةً يأخذونُ منه مالًا ومِن غيره، فسار بختيار وعسكَرُه، وتخلَّفَ عنه سبكتكين التركي، فلمَّا وصلوا إلى الأهواز خدم بختكين بختيار وحَمَلَ له أموالًا جليلةَ المقدارِ، وبذل له من نَفسِه الطاعةَ، وبختيار يفكِّرُ في طريقٍ يأخُذُه به. فات"},{"id":1245,"era":"c4","t":"الحرب بين العبيديين (الفاطميين) والقرامطة .","s":"لَمَّا استقَرَّ المعِزُّ الفاطميُّ بالدِّيارِ المصرية وابتنى فيها القاهرةَ والقصرينِ وتأكَّدَ مُلكُه، سار إليه الحُسَين بن أحمد القرمطي من الأحساءِ في جمعٍ كثيفٍ مِن أصحابه، والتَفَّ معه أميرُ العرب ببلادِ الشَّامِ وهو حَسَّان بنُ الجراح الطائي، في عربِ الشَّامِ بكَمالِهم، فلمَّا سَمِعَ بهم المعِزُّ أُسقِطَ في يده لكَثرتِهم، وكتب إلى القرمطيِّ يَستَميلُه ويقولُ: إنَّما دعوةُ آبائك كانت إلى آبائي ق"},{"id":1246,"era":"c4","t":"العبيديون (الفاطميون) ينتزعون دمشق من القرامطة .","s":"لَمَّا انهزَمَ القَرمطيُّ بعث المعِزُّ سَريَّةً وأمَّرَ عليهم ظالمَ بن موهوب العقيلي، فجاؤوا إلى دمشقَ فتسَلَّمَها من القرامطةِ بعد حصارٍ شديدٍ، واعتقل متولِّيَها أبا الهيجاءِ القَرمطيَّ وابنَه، ولَمَّا تفرغ أبو محمود القائِدُ مِن قتال القرامطة أقبل نحو دمشقَ فخرج إليه ظالمُ بنُ موهوب فتلَقَّاه إلى ظاهر البلَدِ وأكرَمَه وأنزله ظاهِرَ دمشق، فأفسد أصحابُ أبي محمودٍ في الغوطة ونهَبوا الفلَّاحين وقطعو"},{"id":1247,"era":"c4","t":"وفاة شيخ الحنابلة، أبي بكر بن يزداد البغدادي غلام الخلال .","s":"هو شيخُ الحنابلةِ أبو بكر عبدُ العزيز بن جعفر بن أحمد بن يزداد البغدادي الفقيهُ، تلميذُ أبي بكرٍ الخَلَّال. ولِدَ سنة 285. وسمِعَ في صِباه من مُحمَّد بن عثمان بن أبي شيبةَ، وموسى بن هارون، والفضلِ بنِ الحُباب وجماعة, وقيل: إنَّه سَمِعَ مِن عبد الله بن أحمد بن حنبل، ولم يصِحَّ ذلك؛ قال الذهبي: \" كان كبيرَ الشَّأنِ، من بحورِ العِلمِ، له الباعُ الطويل في الفِقهِ, ومَن نظَرَ في كتابه \" الشافي \" عَرَف "},{"id":1248,"era":"c4","t":"عزل الخليفة العباسي المطيعِ للهِ وتولي ابنِه الطائع لله مكانه .","s":"خُلِعَ المُطيعُ لله، وكان به مرَضُ الفالجِ، وقد ثَقُل لِسانُه، وتعَذَّرَت الحركةُ عليه، وهو يستُرُ ذلك، فانكشف حالُه لسبكتكين حاجِبِ عِزِّ الدولة، فدعاه إلى أن يخلَعَ نَفسَه مِن الخلافةِ ويسَلِّمَها إلى ولده الطائعِ لله، واسمُه أبو الفضلِ عبدُ الكريم، ففعل ذلك وأشهَدَ على نفسِه بالخَلْعِ ثالثَ عشَرَ من ذي القعدة. وكانت مُدَّةُ خلافتِه تسعًا وعشرين سنةً وخمسةَ أشهر غيرَ أيَّامٍ، وبويع للطائعِ لله ب"},{"id":1249,"era":"c4","t":"أفتكين التركي ينتزع دمشق من يد العبيديين (الفاطميين) .","s":"نزَلَ أفتكين التركي غلامُ مُعِزِّ الدولة- الذي كان قد خرج عن طاعتِه بسبَبِ الفِتنةِ التي جَرَت بين التُّرك والديلم وما بعدها، والتَفَّ عليه عساكِرُ وجُيوشٌ من الديلم والتركِ والأعرابِ- نزل في هذه السَّنةِ على دِمشقَ، وكان عليها مِن جِهةِ الفاطميِّينَ الطواشيُّ ريان الخادِمُ مِن جِهةِ المُعِزِّ الفاطميِّ، فلما نزل بظاهِرِها خرج إليه كُبَراءُ أهلِها وشيوخُها، فذكروا له ما هم فيه من الظُّلمِ والغشم و"},{"id":1250,"era":"c4","t":"بناء مدينة أشير عاصمة للدولة الزيرية بالمغرب الأوسط .","s":"اجتمعت صَنهاجةُ ومَن والاها بالمغربِ على طاعةِ يوسُفَ بلكين بن زيري بن مناد الصنهاجي الحِمْيَري قبل أن يُقَدِّمَه المنصور، وكان أبوه مناد الصِّنهاجيُّ كبيرًا في قومِه، كثيرَ المالِ والولَدِ، حسَنَ الضِّيافةِ لِمَن يمُرُّ به، وتقدَّمَ ابنُه زيري في أيَّامِه، وقاد كثيرًا من صنهاجةَ، وأغار بهم وسبى، فحَسَدته زناتة وجَمَعَت له لتسيرَ إليه وتحارِبَه. فسار إليهم مجِدًّا فكَبَسَهم ليلًا- وهم غارُّون - بأ"},{"id":1251,"era":"c4","t":"ظهور رجل يُعرَفُ بالعبَّاس يدعي النبوة بأفريقيا .","s":"خرج في جبل غمارة بإفريقيَّة رجلٌ يُعرَفُ بالعبَّاس ادَّعى النبوَّةَ واتَّبَعَ نعيقَه الأرذَلونَ مِن سفهاءِ تلك القبائلِ وأعمارِهم، وزحف إلى بادس من أمصارِهم ودخَلَها عَنوةً, فلمَّا سمع يوسُفُ بلكين بن زيري الصنهاجي به وباتِّباعِ أهل غمارة له، سار إليهم وغزاهم وظَفِرَ بهم، وأخَذَ العبَّاسَ- الذي كان يدَّعي النبُوَّةَ- أسيرًا، وأحضَرَ الفُقَهاءَ فقَتَله لأربعينَ يومًا من ظهورِ دَعوتِه."},{"id":1252,"era":"c4","t":"وفاة الخليفة العباسي المطيع لله .","s":"أبو القاسمِ الفَضلُ ابنُ المُقتَدر جعفر بن المعتضد أحمد بن الموفق الخليفة العباسي. ولدَ سنة 301 وبويع بالخلافةِ بعد خَلعِ المُستكفي نفسَه سنة 334، وأمُّه اسمُها مشغلة أمُّ ولد. كان مقهورًا مع نائب العراقِ ابنِ بُوَيه مُعِزِّ الدولة الذي قرَّرَ له في اليومِ مائة دينار فقط. ولَمَّا اشتَدَّ الغَلاءُ المُفرطُ ببغداد، اشتري المطيعُ لله لمعِزِّ الدولةِ كر دقيقٍ بعشرين ألف درهم, وفي سنة 360 فُلِجَ المُطي"},{"id":1253,"era":"c4","t":"استرداد الفاطميين دمشق من أفتكين التركي .","s":"لَمَّا استقَرَّ الأمرُ لأفتكين التركي في الشام ولم يستجِبْ لطَلَبِ المعِزِّ الفاطميِّ ليكونَ نائبًا له فيها. عزم المعِزُّ على المسير إليه ليأخُذَها منه، فبينما كانت العساكرُ تُجمَعُ للمُعِزِّ إذ توفِّيَ، وقام بعدَه ولدُه العزيز، فاطمأنَّ عند ذلك أفتكين بالشام، واستفحل أمرُه وقَوِيَت شوكتُه، ثمَّ اتَّفقَ أمرُ المِصريِّينَ على أن يبعثوا جوهرًا الصقليَّ لقتالِه وأخْذِ الشَّامِ مِن يده، فعند ذلك حلَفَ"},{"id":1254,"era":"c4","t":"وفاة الشاشي القفال الكبير الشافعي .","s":"هو الإمامُ العلَّامةُ الفقيهُ الأصوليُّ اللُّغويُّ, عالمُ خُراسان, أبو بكر مُحمَّدُ بنُ عليِّ بنِ إسماعيل الشافعيُّ، صاحِبُ التصانيفِ، المعروفُ بالقَفَّال الكبيرِ، الشَّاشيُّ نِسبةً إلى مدينة شاشَ وراءَ النَّهرِ، ولد بها سنة 271, وكان من أكابر عُلَماءِ عَصرِه بالفِقهِ والحديث واللغة، رحل إلى العراقِ والشام وخراسان، قال الحاكم عنه: \"عالمُ أهلِ ما وراءَ النَّهرِ في الأصولِ \". وعنه انتشر المذهبُ الشّ"},{"id":1255,"era":"c4","t":"وفاة المعز لدين الله (الفاطمي) وتولي ابنه العزيز بالله من بعده .","s":"هو المُعِزُّ لدين الله أبو تميمٍ مُعدُّ بن المنصور بالله إسماعيل بن القائم بأمر الله أبي القاسم محمد بن المهدي أبي محمد عبيد الله، العُبَيديُّ المهدويُّ صاحِبُ المغرب. بُنِيَت له القاهرة, وكان وليَّ عَهدِ أبيه. ولي سنة 341، وسار في نواحي إفريقيَّةَ يمَهِّدُ مُلكَه، فذَلَّل الخارجين عليه، واستعمل مماليكَه على المدُنِ، واستخدم الجُندَ، وأنفق الأموالَ، وجهَّز مملوكَه جوهرًا القائِدَ في الجيوشِ. فسار "},{"id":1256,"era":"c4","t":"المسلمون يحاصرون كسنتة .","s":"سار أبو القاسمِ بنُ الحسَنِ بنِ علي بن أبي الحسين أميرُ صقليَّةَ، في عساكرِ المسلمينَ، ومعه جماعةٌ مِن الصَّالحين والعلماء، فنازل مدينةَ مسيني في رمضانَ، فهرب العدوُّ عنها، وعدا المُسلمونَ إلى كسنتة فحصروها أيَّامًا، فسأل أهلُها الأمانَ، فأجابهم إليه، وأخذ منهم مالًا، ورحل عنها إلى قلعةِ جلوا، ففعل كذلك بها وبِغَيرِها، وأمَرَ أخاه القاسِمَ أن يُذهِبَ الأسطولَ إلى ناحية بربولة ويَبُثَّ السَّرايا في"},{"id":1257,"era":"c4","t":"وفاة أبي الحسن ثابت بن سنان بن قرة الفيلسوف الطبيب .","s":"هو ثابتُ بنُ سِنانِ بنِ ثابتِ بن قُرَّة بن مروان، أبو الحسن الحرَّانيُّ الأصلِ الصَّابئُ، ثم البغدادي الطبيبُ المؤرِّخُ. كان يلحَقُ بأبيه في صناعةِ الطِّبِّ، وجَدُّه هو ثابت بن قرة الصابئ فيلسوفُ عَصرِه, وكان صيرفيًّا، يتوقَّدُ ذَكاءً، فبرع في علمِ الأوائل وصار منجِّمَ المعتَضِد, وكان أخوه إبراهيمُ بنُ سنان من الأذكياءِ البارعين في صناعة الطب. صنف أبو الحسَنِ ثابت بن سنان تاريخًا كبيرًا على الحواد"},{"id":1258,"era":"c4","t":"وفاة المستنصر بالله حاكم الأندلس وتولي ابنه هشام المؤيد بالله بعده .","s":"هو أميرُ المؤمنينَ، أبو العاصِ الحَكَمُ بنُ عبد الرحمن بن محمد بن عبد الله بن محمد بن عبد الرحمن المستنصر بالله الأموي، صاحبُ الأندلس، وُلِدَ سنة 302, وبويع بعد أبيه، في رمضان، سنة 350. وكان حسَنَ السيرة، جامعًا للعلم، مُكرِمًا للأفاضل، كبيرَ القَدرِ، ذا نَهمةٍ مُفرِطةٍ في العلم والفضائل، عاكفًا على المطالعة. جمع من الكتُبِ ما لم يجمَعْه أحدٌ من الملوك، لا قَبله ولا بعدَه، وتطَلَّبَها وبذَلَ في أث"},{"id":1259,"era":"c4","t":"ابتداء ملك آل سبكتكين في مدينة غزنة .","s":"مَلَكَ سبكتكين مدينةَ غزنة وأعمالَها، وكان ابتداءُ أمرِه أنَّه كان مِن غِلمانِ أبي إسحاقَ بنِ البتكين، صاحِبِ جيش غزنة للسامانية، وكان مقَدَّمًا عنده، وعليه مدارُ أمرِه، وقدِمَ إلى بُخارى، أيَّامَ الأمير منصور بن نوح، مع أبي إسحاق، فعَرَفَه أربابُ تلك الدولة بالعقلِ والعفَّة، وجودةِ الرأي والصَّرامة، وعاد معه إلى غزنة، فلم يلبثْ أبو إسحاق أن توفِّيَ، ولم يخَلِّفْ من أهلِه وأقاربه من يصلُحُ للتقَدّ"},{"id":1260,"era":"c4","t":"ابن أبي عامر يحجب المؤيد بالله ويتولى تدبير البلاد في الأندلس .","s":"لَمَّا توفِّيَ الحَكَمُ بنُ عبد الرحمن بويعَ بخلافةِ الأندلُسِ ابنُه هشامٌ المؤيَّدُ بالله، وله يومئذٍ عشرُ سنينَ أو نحوها، بإشارة الوزراء والقُوَّاد, واختلفت البلادُ في أيامه، فأخذه حاجِبُه ابنُ أبي عامرٍ وحَبَسه، وحَجَبه عن النَّاسِ، فلم يكن أحدٌ يراه ولا يصل إليه، وقام المنصورُ أبو عامر بأمر الدولة القيامَ المَرضِيَّ، وعدل في الرعيَّة، وأقبلت الدُّنيا إليه، واشتغل بالغَزوِ، وفتحَ مِن بلاد الأعد"},{"id":1261,"era":"c4","t":"سبكتكين الغزنوي مؤسس دولة الغزنويين يوالي انتصاراته في الهند .","s":"جمعَ العساكِرَ وسار نحوَ الهِندِ مجُاهدًا، وجرى بينه وبين الهنودِ حُروبٌ يَشيبُ لها الوليدُ، وكشَفَ بلادَهم، وشَنَّ الغاراتِ عليها، وطَمِعَ فيها، وخافه الهنودُ، ففتح من بلادهم حصونًا ومعاقِلَ، وقتل منهم ما لا يدخُلُ تحت الإحصاءِ، ولَمَّا رأى جيبال ملِكُ الهند ما دهاه، وأنَّ بلاده تُملَكُ من أطرافها، أخذه ما قَدُم وحَدَث، فحشد وجمعَ واستكثَرَ مِن الفِيَلة، وسار حتى اتَّصَل بولايةِ سبكتكين، فسار سبك"},{"id":1262,"era":"c4","t":"وفاة ركن الدولة بن بويه الديلمي الشيعي .","s":"هو السلطان رُكنُ الدولة, أبو عليٍّ, الحسنُ بنُ بُوَيه بن فناخسرو الديلمي الشيعي, صاحب أصبهان والري وهمذان وجميع عراقِ العَجَم، ووالِدُ السلطانِ عَضُدِ الدولةِ فناخسرو، ومؤيِّدِ الدَّولة أبي منصور بُوَيه، وفَخرِ الدولةِ أبي الحسَنِ عليٍّ، وكان ملكًا جليلَ القدر عاليَ الهمة، وهو أحدُ الإخوة الثلاثة الذين مَلَكوا البلادَ بعد الفَقرِ, وكان هو أوسَطَ الإخوة الثلاثة، وهم عِمادُ الدولة أبو الحسَنِ عليٌّ،"},{"id":1263,"era":"c4","t":"محاولة العزيز بالله الفاطمي القضاء على فتنة القرامطة في الشام .","s":"لم يزلْ أفتكين الشَّرابيُّ مولى مُعِزِّ الدولة بن بُوَيه طُولَ مُقامِه بدمشق يكاتِبُ القَرامِطةَ ويكاتِبونَه بأنَّهم سائرون إلى الشام، إلى أن وافَوا دمشق بعد موتِ المعِزِّ الفاطمي في هذه السنة، وكان الذي وافى منهم: إسحاقُ، وكِسرى، وجعفر، فنزلوا على ظاهرِ دمشق، ومعهم كثيرٌ مِن العجم أصحابِ أفتكين الذين تشَتَّتوا في البلاد وقتَ وَقعتِه مع الديلم، فلَقُوهم بالكوفة في الموقعات، فأركبوهم الإبِلَ، وسارو"},{"id":1264,"era":"c4","t":"عضد الدولة البويهي يدخل بغداد ويقتل ابن عمه بختيار .","s":"سار عَضُد الدَّولة إلى بغداد، وأرسل إلى بختيار يدعوه إلى طاعتِه، وأن يسيرَ عن العراقِ إلى أيِّ جهةٍ أراد، وضَمِنَ مساعدتَه بما يحتاجُ إليه من مال وسلاح وغير ذلك، فاختلف أصحابُ بختيار عليه في الإجابةِ إلى ذلك، إلَّا أنَّه أجاب إليه لضَعفِ نَفسِه، وأرسل إليه عضُدُ الدَّولةِ يطلُبُ منه ابنَ بقية، فسَمَلَ عينيه وأنفَذَه إليه، وتجهَّزَ بختيار بما أنفَذَه إليه عضُد الدولة، وخرج عن بغداد عازمًا على قَصدِ"},{"id":1265,"era":"c4","t":"المنصور أبو عامر يبني مدينة الزاهرة بالأندلس .","s":"أمر أبو عامِر محمَّدُ بنُ أبي عامر حاجِبُ هِشامٍ المؤَيَّد ببناء قصره المعروفِ بالزاهرة، وذلك عندما استفحل أمرُه، واتَّقَد جَمْرُه، وظهر استبدادُه، وكثُرَ حُسَّادُه، وخاف على نفسِه في الدخولِ إلى قصر السلطان، فتوثَّقَ لنَفسِه، وكُشِفَ له ما سُتِرَ عنه في أمسِه، من الاعتزاز عليه، ورفع الاستنادِ إليه، وسما إلى ما سَمَت إليه الملوكُ مِن اختراع قَصرٍ يَنزِلُ فيه، ويُحله بأهلِه وذويه، ويضُمُّ إليه رياس"},{"id":1266,"era":"c4","t":"نهاية حكم أفتكين التركي على يد عسكر الفاطميين .","s":"اتَّفَقَ أنَّ عَضُدَ الدولة أبا شجاع فناخسرو بن ركن الدولة بن بُويه أخذ بغدادَ مِن ابنِ عَمِّه بختيار بن أحمدَ بنِ بُوَيه، فسار بختيار إلى المَوصِل، واتَّفَق مع أبي تغلِبَ الغضنفر بن ناصر الدولة بن حِمدانَ على قتالِ فناخسرو، فسار إليهم فناخسرو وأوقَعَ بهم، فانهزموا، وأَسَر بختيار وقَتَلَه، وفَرَّ حينئذٍ مِن أولاد بختيار إعزازُ الدولة المرزبان، وأبو كاليجار وعَمَّاه: عُمدةُ الدولة أبو إسحاق، وأبو ط"},{"id":1267,"era":"c4","t":"قسَّام الجُبَيلي التَّرَّاب يسيطر على دمشق .","s":"لَمَّا ذهب أفتكين إلى ديارِ مِصرَ نهَضَ رجلٌ مِن أهل دمشق يقال له قسَّام الجُبَيلي التَّرَّاب وهو من بني الحارثِ بنِ كعبٍ مِن اليَمَن. كان ابتداءُ أمْرِه أنَّه انتمى إلى رجلٍ مِن أحداثِ أهلِ دِمشقَ يقال له أحمد بن المسطان، فكان مِن حِزبِه، وكان أفتكين يقَرِّبُه ويُدنيه، ويأمَنُه على أسراره، فاستحوذ على دمشقَ وطاوعَه أهلُها، وغلب على الوُلاةِ والأمراءِ، وقصَدَته عساكِرُ العزيز من مصرَ فحاصروه فلم ي"},{"id":1268,"era":"c4","t":"عضد الدولة يستحوذ على كثير من البلاد .","s":"ركِبَ عَضُدُ الدولةِ في جنودٍ كثيفة إلى بلادِ أخيه فخرِ الدَّولة، وذلك لَمَّا بلَغَه من ممالأتِه لعِزِّ الدولة واتفاقِهما عليه، فتسَلَّمَ بلاد أخيه فخرِ الدولة وهمدان والري وما بينهما من البلاد، وسلَّمَ ذلك إلى مؤيِّدِ الدَّولة- وهو أخوه الآخر- ليكون نائبه عليها، ثم سار إلى بلادِ حسنويه الكردي فتسَلَّمَها وأخذ حواصِلَه وذخائِرَه، وكانت كثيرةً جِدًّا، وحبس بعضَ أولادِه وأسَرَ بَعضَهم، وأرسلَ إلى ال"},{"id":1269,"era":"c4","t":"عضُدُ الدَّولةِ يشرع في عمارةِ بغداد بعد خرابها بسبب الفتن .","s":"شرع عضُدُ الدَّولةِ في عمارةِ بغداد، وكانت قد خَرِبَت بتوالي الفِتَن فيها، وعَمَرَ مساجِدَها وأسواقها، وأدَرَّ الأموال على الأئمَّة والمؤذِّنين، والعلماء والقُرَّاء، والغُرَباء والضعفاء الذين يأوون إلى المساجد، وألزم أصحابَ الأملاكِ الخرابِ بعِمارتِها، وجَدَّدَ ما دثَرَ مِن الأنهار، وأعاد حَفْرَها وتسويتها، وأطلق مُكوسَ الحجَّاج، وأصلح الطريقَ مِن العراق إلى مكَّة، شَرَّفَها الله تعالى، وأطلق الصّ"},{"id":1270,"era":"c4","t":"ورد بن منير الرومي، يطَمِع في مُلكِ الرُّوم .","s":"كان ورد بن منير من أكابرِ أصحابِ الجُيوشِ وعُظَماءِ البطارقة، فطَمِعَ في مُلكِ الرُّوم، وكاتب أبا تغلِبَ بنَ حمدان وصاهره، واستجاش بالمُسلمينَ مِن الثغور، فاجتمعوا عليه، فقصد الرومَ، فأخرج إليه المَلِكان الروميَّان ولدا الدُّمُسْتُق جيشًا بعد جيشٍ وهو يهزِمُهم، فقَوِيَ جَنانُه وعَظُم شأنه، وقصد القسطنطينيَّة، فخافه المَلِكان، فأطلقا ورديس بن لاون، وقَدَّماه على الجيوش، وسيَّرَاه لقتال ورد، فاقتتلو"},{"id":1271,"era":"c4","t":"العزيز بالله (الفاطمي) يقضي على فتنة ابن جَرَّاح وقسَّام الجبيليِّ .","s":"سُيِّرَت العساكِرُ مِن مِصرَ لقتالِ المفرج بن جراح، وسبَبُ ذلك أنَّ ابنَ جَرَّاح عظُمَ شَأنُه بأرض فلسطينَ، وكثُرَ جَمعُه، وقَوِيَت شوكتُه، وبالغ هو في العيثِ والفساد، وتخريبِ البلاد، فجهز العزيزُ الفاطمي العساكرَ وسَيَّرَها، وجعل عليها القائِدَ يلتكين التركي، فسار إلى الرملة، واجتمع إليه من العربِ، من قيسٍ وغيرها، جمعٌ كثيرٌ، وكان مع ابنِ جَرَّاح جمعٌ يرمون بالنُّشَّاب، ويقاتلون قتالَ الترك، فالت"},{"id":1272,"era":"c4","t":"وفاة أبي بكر الرازي الجصاص من أئمة علماء الحنفية .","s":"هو الإمامُ العلَّامةُ المُفتي المجتَهِد, عَلَمُ العراق أبو بكر أحمدُ بنُ عليٍّ الرازي الجَصَّاصُ، الفقيهُ الحنفي، إمامُ أصحاب الرأي في وقته، صاحب التصانيف، وتلميذُ أبي الحسن الكرخي. ولد سنة 305 في مدينة الريِّ التي يُنسَبُ لها بالرازي, وقد مكث بها حتى سِنِّ العشرينَ، حيث رحل إلى بغداد واستوطَنَها. وقد حاز الإمامُ مكانةً عِلميَّةً سامِقةً بين علماءِ الأمة عمومًا, وعُلَماءِ الحنفيَّة خُصوصًا. كان مع"},{"id":1273,"era":"c4","t":"أبو عامر المنصور ينتصر على الأسبان في موقعة سيمانكس .","s":"بعد أن توفِّيَ غالِبُ النَّاصِريُّ أميرُ مدينةِ سالم والثُّغورِ الشَّماليَّة بالأندلُسِ، وكان هو المنافِسَ لمحمد بن أبي عامر المنصور، وكان غالِبٌ قد انضَمَّ للنصارى لقتالِ المنصورِ، فبعد هذا توجَّه المنصورُ إلى ليون لحربِ مَلِكِها راميرو الذي استنصَرَ بمَلِكَي قشتالة ونافار، فحصلت بينهم حروبٌ قُربَ سيمانكس أو شنت منكش، فكانت نتيجةُ هذه المعارك انتصارَ ابنِ أبي عامر الذي تلقَّبَ بعدَ هذه المعارك با"},{"id":1274,"era":"c4","t":"وفاة عضد الدولة البويهي الديلمي الشيعي وكتم وفاته .","s":"هو السُّلطانُ عَضُد الدولة, أبو شُجاع, فناخسرو بن السلطان رُكنِ الدولة حسن بن بويه الدَّيلمي الشيعي, صاحِبُ العراق وفارس. تملَّك فارس بعد عَمِّه عماد الدولة, ثم كثُرَت بلادُه, واتسعت ممالِكُه, ودانت له البلادُ والعباد. وهو أوَّلُ مَن خُوطِبَ بالمَلِك شاه شاه في الإسلامِ، وأوَّلُ مَن خُطِب له على المنابر ببغداد بعد أميرِ المؤمنين وكان بطلًا شُجاعًا مَهيبًا, جبَّارًا عَسوفًا, شديد الوطأةِ, وكان فاضل"},{"id":1275,"era":"c4","t":"مقتل أبي القاسم أمير صقلية وهزيمة الفرنج .","s":"سار الأميرُ أبو القاسم، أميرُ صقليَّة، من المدينةِ يريدُ الجِهادَ، وسببُ ذلك أنَّ مَلِكًا مِن مُلوكِ الفِرنجِ، يقال له بردويل، خرجَ في جموعٍ كثيرةٍ مِن الفرنجِ إلى صقليَّةَ، فحصَرَ قَلعةَ مَلطةَ ومَلَكَها، وأصاب سريتَينِ للمُسلمينِ، فسار الأميرُ أبو القاسم بعساكِرِه ليُرحِّلَه عن القلعة، فلمَّا قاربَها خاف وجَبُن، فجمع وجوهَ أصحابِه، وقال لهم: إنِّي راجِعٌ مِن مكاني هذا، فلا تكسروا عليَّ رأيي. فرج"},{"id":1276,"era":"c4","t":"سبب انتقال بعض صنهاجة من إفريقية إلى الأندلس .","s":"انتقل أولادُ زيري بن مناد- وهم زاوي وجلالة وماكسن، إخوة بلكين- إلى الأندلس، وسببُ ذلك أنَّهم وقعَ بينهم وبين أخيهم حمَّاد حروبٌ وقِتالٌ على بلادٍ بينهم، فغلبهم حمَّادٌ، فتوجَّهوا إلى طنجة ومنها إلى قُرطُبةَ، فأنزلهم محمَّدُ بنُ أبي عامر وسُرَّ بهم، وأجرى عليهم الوظائِفَ وأكرَمَهم، وسألهم عن سبَبِ انتقالهم، فأخبروه، وقالوا له: إنَّما اخترناك على غيرك، وأحبَبْنا أن نكون معك نجاهدُ في سبيل الله. فاست"},{"id":1277,"era":"c4","t":"غزو ابن أبي عامر الفرنجة بالأندلس .","s":"لَمَّا رأى أهلُ الأندلس فِعْلَ صِنهاجةَ غَبَطوهم، ورَغِبوا في الجهاد، وقالوا للمنصورِ بنِ أبي عامر: لقد نَشَّطَنا هؤلاء للغزو، فجمع الجيوش الكثيرةَ مِن سائر الأقطار، وخرج إلى الجهاد، إلى إليون ونازلها، واستمَدَّ أهلُها الفِرنجَ، فأمدُّوهم بجيوش كثيرة، واقتتلوا ليلًا ونهارًا، فكَثُر القتل فيهم، وصبَرَت صنهاجة صبرًا عظيمًا، ثم خرج قومص كبيرٌ مِن الفرنج لم يكُنْ لهم مثله، فجال بين الصفوفِ وطلب البراز"},{"id":1278,"era":"c4","t":"ظهور رسائل إخوان الصفا .","s":"قال أبو حيَّان التوحيديُّ: \" سألني وزيرُ صمصام الدَّولة بن عضُدِ الدولة عن زيد بن رفاعة في حدود سنة 373 قال: لا أزالُ أسمَعُ مِن زيد بن رفاعة قولًا يَريبُني، ومذهبًا لا عهد لي به، وقد بلغني أنَّك تغشاه وتجلِسُ إليه وتُكثِرُ عنده. ومن طالت عشرتُه لإنسانٍ أمكَنَ اطِّلاعُه على مستكنِّ رأيه. فقلت: أيُّها الوزيرُ، عنده ذكاءٌ غالِبٌ، وذهن وقَّاد. قال: فعلى هذا ما مذهَبُه؟ قلت: لا يُنسَبُ إلى شيءٍ، لكنه "},{"id":1279,"era":"c4","t":"وفاة مؤيد الدولة بن ركن الدولة البويهي الديلمي الشيعي .","s":"هو أبو منصور بُوَيه مؤيَّدُ الدولة بنُ رُكن الدولة الحسَن بن بُوَيه بن فناخسرو الديلمي الشيعي. كان وزيرُه هو الصَّاحِبَ إسماعيلَ بنَ عَبَّاد، الذي صحبه منذ صباه حتى صار وزيرًا له، فضبَطَ مملكتَه وأحسَنَ تدبيرَها. قال الصاحِبُ بنُ عَبَّاد لمؤيَّد الدولة في مرضِه: لو عهدْتَ إلى أحدٍ؟ فقال: أنا في شُغُلٍ عن هذا، ولم يَعهَدْ بالملك إلى أحدٍ، توفِّيَ مؤيَّد الدولة بجرجان، من خوانيقَ أصابته، وله ثلاثٌ و"},{"id":1280,"era":"c4","t":"عودة الديلم إلى الموصل .","s":"لَمَّا استولى باذ الكردي على الموصِل، اهتم صمصام الدولة ووزيرُه ابن سعدان بأمرِه، فوقع الاختيارُ على إنفاذِ زيار بن شهراكويه، وهو أكبَرُ قُوَّادهم، فأمره بالمسيرِ إلى قتاله، وجَهَّزه، وبالغ في أمرِه، وأكثَرَ معه الرجالَ والعُدَد والأموال، وسار إلى باذ، فخرج إليهم، ولَقِيَهم في صفر، فأجْلَت الوقعةُ عن هزيمةِ باذ وأصحابِه، وأُسِرَ كثيرٌ مِن عَسكرِه وأهْلِه، وحمُلِوا إلى بغداد فشُهِروا بها، ومَلَك ال"},{"id":1281,"era":"c4","t":"محاولة القرامطة دخول البصرة .","s":"دخلت القرامِطةُ البصرةَ لَمَّا عَلِموا بموتِ عَضُد الدولة، ولم يكُن لهم قُوَّة على حصارِها، فجُمِعَ لهم مالٌ فأخذوه وانصَرَفوا."},{"id":1282,"era":"c4","t":"الفتنة بين الديلم ببغداد .","s":"جَرَت فتنةٌ ببغداد بين الديلم، وكان سببُها أنَّ أسفار بن كردويه، وهو من أكابِرِ القُوَّاد، استنفر من صمصام الدولة، واستمالَ كثيرًا من العسكَرِ إلى طاعة شَرَف الدولة، واتَّفَق رأيُهم على أن يولُّوا الأميرَ بهاءَ الدولة أبا نصر بنَ عضد الدولة العراقَ نيابةً عن أخيه شَرَف الدولة، وكان صمصام الدولة مريضًا، فتمكَّنَ أسفار من الذي عزم عليه، وأظهَرَ ذلك، وتأخَّرَ عن الدار، وراسله صمصامُ الدولة يستميلُه و"},{"id":1283,"era":"c4","t":"أخبار القرامطة في الكوفة .","s":"ورد إسحاقُ وجعفرٌ البحريان، وهما من الستَّة القرامطة الذين يلقَّبون بالسادة، فمَلَكا الكوفةَ، وخَطَبا لشَرَف الدولة، فانزعج النَّاسُ لذلك؛ لِمَا في النفوس من هيبتِهم وبأسِهم، وكان نائبُهم ببغداد يُعرَفُ بأبي بكر بن شاهويه، يتحَكَّمُ تحكُّمَ الوُزَراء، فقَبَضَ عليه صمصام الدولة، فلما ورد القرامطةُ الكوفة كتب إليهما صمصامُ الدولة يتلَطَّفُهما، ويسألهما عن سبَبِ حَرَكتهما، فذكرا أنَّ قَبضَ نائِبِهم ه"},{"id":1284,"era":"c4","t":"الإفراج عن ورد بن منير الرومي .","s":"أفرج صَمصامُ الدَّولة عن ورد الروميِّ، وكان قد حبَسَه، وشَرَط عليه إطلاقَ عَدَدٍ كثيرٍ مِن أسرى المسلمين، وأن يسَلِّمَ إليه سبعةَ حُصونٍ مِن بلد الروم برساتيقِها، وألا يقصِدَ بلادَ الإسلامِ هو ولا أحدٌ مِن أصحابه ما عاش، وجهَّزَه بما يحتاجُ إليه مِن مالٍ وغَيرِه."},{"id":1285,"era":"c4","t":"دخول الروس في النصرانية .","s":"سار ورد الروميُّ بعد إطلاق صمصام الدَّولةِ سَراحَه إلى بلاد الروم، واستمال في طريقِه خلقًا كثيرًا من البوادي وغيرِهم، وأطمَعَهم في العطاء والغنيمة، وسار حتى نزل بملطيَّة، فتسَلَّمَها، وقَوِيَ بها وبما فيها من مالٍ وغيرِه، وقصَدَ ورديس بن لاون، فتراسَلَا، واستقَرَّ الأمرُ بينهما على أن تكونَ القُسطنطينية وما جاورها من شماليَّ الخليجِ لورديس، وهذا الجانِبُ من الخليج لورد، وتحالفا واجتَمَعا، فقَبَضَ "},{"id":1286,"era":"c4","t":"قتال المنصور ابن أبي عامر الأندلسي لأهل زناتة بالمغرب .","s":"قام في المغرب على ابنِ أبي عامرٍ زيري بنُ عطيَّة المغراوي، ونكَثَ طاعتَه بعد الحُبِّ الشديدِ والوَلاءِ الأكيد، وطعن على ابنِ أبي عامرٍ تغَلُّبَه على هشام وسَلْبَه مُلكَه. فأنفذ له ابنُ أبي عامر واضِحًا الفتى في جيشٍ كثيف، فقاومه بالغَربِ، ودارت بينهم حروبٌ عظيمة. ثم أردَفَه ابنُ أبي عامر بوَلَدِه عبد الملك، وهبَطَ ابنُ أبي عامر إلى الجزيرةِ الخَضراءِ، يُمِدُّهم بالقُوَّاد والأجناد، وسار عبدُ الملك"},{"id":1287,"era":"c4","t":"الفتنة بين الديلم والترك ببغداد .","s":"جَرَت فتنةٌ بين الديلم والأتراكِ الذين مع شَرَفِ الدولة ببغداد، وسبَبُها أنَّ الدَّيلمَ اجتمعوا مع شَرَفِ الدولة في خَلق كثيرٍ بَلَغَت عِدَّتُهم خمسةَ عشر ألف رجل، وكان الأتراكُ في ثلاثةِ آلاف، فاستطال عليهم الدَّيلمُ، فجرت منازعةٌ بين بعضهم في دار وإصطبل، ثمَّ صارت إلى المُحاربة، فاستظهر الديلمُ لكَثرتِهم، وأرادوا إخراجَ صمصامِ الدَّولة وإعادته إلى مُلكِه، وبلغ شرفَ الدَّولةِ الخبَرُ، فوكَلَ بصمص"},{"id":1288,"era":"c4","t":"انتزاع شرف الدولة بغداد من أخيه صمصام الدولة  .","s":"سار شَرَفُ الدولة أبو الفوارِسِ بنُ عَضُد الدولة من الأهواز إلى واسط فمَلَكها، فأرسل إليه صمصامُ الدَّولةِ أخاه أبا نصرٍ يستعطِفُه بإطلاقه، وكان محبوسًا عنده، فلم يتعطَّفْ له، واتسَّعَ الخَرقُ على صمصام الدولة، وشَغَّبَ عليه جُندُه، فسار صمصام الدولةِ إلى أخيه شَرَف الدولة في خواصِّه، فلَقِيَه وطَيَّبَ قَلبَه، فلما خرجَ مِن عنده قبَضَ عليه، وأرسل إلى بغدادَ مَن يحتاطُ على دار المَملكةِ، وسار شرفُ "},{"id":1289,"era":"c4","t":"العزيز بالله الفاطمي يمنع النصارى من إظهار ما كانوا يفعلونه في الغطاس .","s":"قام العزيزُ بالله الفاطميُّ بمَنعِ النَّصارى من إظهارِ ما كانوا يَفعَلونَه في الغطاسِ وهو عيد الظهور الإلهي عند النصارى؛ من الاجتماعِ، ونُزولِ الماء، وإظهارِ الملاهي، وحَذَّرَ من ذلك."},{"id":1290,"era":"c4","t":"مسير المنصور الزيري صاحب إفريقية لقتال أهل كتامة أتباع الفاطميين .","s":"أرسل العزيزُ بالله الفاطمي بمصرَ داعيًا له إلى كتامةَ، يقال له أبو الفهمِ، واسمُه حسَنُ بنُ نصر، يدعوهم إلى طاعتِه، وغَرَضُه أن تميلَ كتامة إليه وترسِلَ إليه جندًا يقاتِلونَ المنصور صاحِبَ إفريقيةَ، ويأخذون إفريقيةَ منه، لَمَّا رأى مِن قُوَّتِه، فدعاهم أبو الفهم، فكثر أتباعُه، وقاد الجيوشَ، وعَظُمَ شأنُه، وعزم المنصورُ على قَصدِه، فأرسل إلى العزيزِ بمصرَ يُعَرِّفُه الحال، فأرسل العزيزُ رَسولينِ إل"},{"id":1291,"era":"c4","t":"عقد اتفاق للتصالح بين العبيديين (الفاطميين) والبيزنطيين .","s":"تهيأ العزيزُ الفاطميُّ صاحِبُ مِصرَ لِغَزوِ الرُّوم، فاحتَرَقت مراكبُه، فاتَّهَم بها أناسًا. ثمَّ بعد ذلك وصَلَت رسلُ الروم في البحر إلى ساحِلِ القدس، ودخلوا مصرَ يَطلُبونَ الصُّلح، فأجابهم العزيزُ واشترط شروطًا شديدةً التَزَموا بها كلها، منها: أنَّهم يَحلِفونَ أنَّه لا يبقى في مملكتِهم أسيرٌ إلَّا أطلقوه، وأن يُخطَبَ للعَزيزِ في جامع قُسطنطينية كلَّ جمعة، وأن يُحمَلَ إليه من أمتعةِ الرُّومِ كُلَّ"},{"id":1292,"era":"c4","t":"تجديد البيعة بين الطائع وبين شرف الدولة .","s":"عُقِدَ مجلسٌ بحَضرةِ الخَليفةِ فيه القضاةُ وأعيان الدولة، وجُدِّدَت البيعة بين الطائعِ وبين شَرَف الدولة بن عَضُد الدولة، وكان يومًا مشهودًا، ثمَّ في ربيعها الأوَّل ركب شرف الدولة من داره إلى دارِ الخليفة وزُيِّنَت البلد وضُرِبَت البوقات والطُّبول والدبادب، فخَلَعَ عليه الخليفةُ وسَوَّره وأعطاه لواءَينِ معه، وعقَدَ له على ما وراء دارِه، واستخلفه على ذلك، ولَمَّا قُضِيَت البيعة دخل شرَفُ الدولة على"},{"id":1293,"era":"c4","t":"وفاة أبي علي الفارسي أحد علماء العربية .","s":"هو أبو عليِّ الحسَنُ بنُ أحمد بن عبد الغَفَّار بن سليمان (أبو عليٍّ الفارِسيُّ) أحدُ عُلَماء العربيَّة المعدودينَ، وُلِدَ ببلده فسا, وقَدِمَ بغداد فاستوطَنَها، وكان فيه اعتزالٌ. عَلَت منزلتُه في النحوِ، حتى قال قومٌ مِن تلامذته هو فَوقَ المُبَرِّد، وأعلَمُ منه، وصنَّفَ كُتبًا عجيبةً حسَنة، لم يُسبَقْ إلى مثلِها، منها كتاب \"الإيضاح\"  وكتاب \"التكملة\" في النحو. واشتهر ذِكرُه في الآفاق، وبَرَع له غِلم"},{"id":1294,"era":"c4","t":"حدوث فتنة شديدة بين الديلم والعامة بمدينة الموصل .","s":"حَدَثَت فتنةٌ شَديدةٌ بين الديلم والعامَّة بمدينة المَوصِل، قُتِلَ فيها مقتلةٌ عظيمةٌ، ثم أُصلِحَ الحالُ بين الطَّائفَتينِ."},{"id":1295,"era":"c4","t":"هزيمة القرامطة على يد الأصفَرِ مِن بني المنتفق .","s":"جمعَ إنسانٌ يُعرَفُ بالأصفَرِ مِن بني المنتفق جَمعًا كثيرًا، وكان بينه وبين جمعٍ مِن القرامطة وقعةٌ شديدةٌ قُتِلَ فيها مُقَدَّمُ القرامطة، وانهزم أصحابُه وقُتِل منهم وأُسِرَ الكثيرُ، وسار الأصفَرُ إلى الأحساءِ، فتحَصَّنَ منه القرامِطةُ، فعدل إلى القطيفِ فأخذ ما كان فيها مِن عبيدِهم وأموالِهم ومواشيهم، وسار بها إلى البصرةِ."},{"id":1296,"era":"c4","t":"ذكر بعض الجوائح بالعراق .","s":"في محرَّم كثُرَ الغَلاءُ والفَناءُ ببغداد إلى شعبان، وفي شَعبانَ كَثُرَت الرِّياحُ العواصفُ وتتابعت الأمطارُ، وكَثُرَت البروق والرعود، والبردُ الكبار، وسالت منه الأوديةُ، وامتلأت الأنهارُ والآبار ببلاد الجبل، وخَرِبَت المساكن، وامتلأت الأفناءُ طينًا وحجارةً، وانقَطَعَت الطرق، وجاءت وقتَ العَصرِ خامِسَ شعبانَ ريحٌ عظيمةٌ بفم الصلحِ، فهَدَمَت قطعةً مِن الجامع، وأهلكت جماعةً مِن الناس، وغَرَّقَت كثير"},{"id":1297,"era":"c4","t":"شرف الدولة البويهي يبني ببغداد مرصدا لرصد الكواكب السبعة .","s":"في المحَرَّم أمَرَ شَرَفُ الدولة بأن تُرصَدَ الكَواكِبُ السَّبعةِ في مسيرها وتنقلُها في بروجِها على مثالِ ما كان المأمونَ يَفعَلُ، وتولَّى ذلك ابنُ رستم الكوهي، وكان له عِلمٌ بالهيئة والهندسة، وبنى بيتًا في دارِ المملكة بسببِ ذلك في آخرِ البُستان، وأقام الرَّصَد لليلتين بقيتا من صفَر."},{"id":1298,"era":"c4","t":"الفتنة بين الأتراك والديلم ببغداد .","s":"وقعت الفِتنةُ ببغداد بين الأتراكِ والديلم، واشتَدَّ الأمرُ ودام القتال بينهم خمسة أيامٍ، وبهاءُ الدولةِ في داره يراسِلُهم في الصلح، فلم يسمَعوا قَولَه، وقُتِلَ بَعضُ رُسُلِه، ثمَّ إنَّه خرج إلى الأتراك، وحضَرَ القِتالَ معهم، فاشتَدَّ حينئذ الأمرُ، وعَظُمَ الشَّرُّ، ثم إنَّه شرع في الصلح، ورفَقَ بالأتراك، وراسل الديلم، فاستقَرَّ الحال بينهم، وحلَفَ بعضُهم لبعض، وكانت مُدَّة الحرب اثني عشر يومًا، ثم"},{"id":1299,"era":"c4","t":"مسير فخر الدولة إلى بغداد للاستيلاء عليها .","s":"سار فخرُ الدَّولةِ بنُ ركن الدولةِ مِن الريِّ إلى همذان، عازمًا على قَصدِ العِراقِ والاستيلاء عليها، فلمَّا توفِّيَ شَرَفُ الدولة عَلِمَ أنَّ الفُرصةَ قد أمكَنَت، وكان الصاحِبُ بنُ عَبَّاد قد وضع على فَخرِ الدَّولةِ مَن يُعَظِّمُ عنده مُلكَ العِراقِ، ولم يباشِرْ على ذلك خوفًا من خطر العاقبةِ، إلى أن قال له فخرُ الدولة: ما عندك في هذا الأمرِ؟ فأحال على أنَّ سعادتَه تُسَهِّلُ كُلَّ صَعبٍ، وعَظَّمَ ا"},{"id":1300,"era":"c4","t":"نشوب فتنة في بغداد أثارها أبو الحسن بن المعلم رئيس الشيعة .","s":"نشَبَت فِتنةٌ أثارها أبو الحسَنِ بنُ المعَلِّم الملَقَّب بالشيخ المفيد، فقام الشُّطَّارُ والعيَّارون بالسلب والنهب، فقام الخليفةُ بالقبض على الشَّيخِ المفيد وسجَنَه، ولكِنَّ بهاء الدولة قام بفَكِّه وإخلاء سبيله، فحَنِقَ الشِّيخُ المفيد على الخليفةِ، وأخذ يخطِّطُ ويكيدُ للخليفة."},{"id":1301,"era":"c4","t":"وفاة شرف الدولة البويهي والعهد إلى أخيه أبي نصر بهاء الدولة .","s":"هو صاحِبُ العِراقِ السُّلطانُ أبو الفوارسِ شَرَفُ الدولةِ, شيرويه بن عَضُد الدولة بن بُوَيه الديلمي الشيعي. تمَلَّكَ وظَفِرَ بأخيه صمصام الدولة فسَجَنَه، وكان فيه خيرٌ, وأزال المُصادرات وتمَلَّك بعده أخوه بهاءُ الدولة، وكان أخوهما الصمصام هو الذي تمَلَّك العراقَ بعد أبيهم عَضُد الدولة ثلاثةَ أعوام, ثم أقبل شرفُ الدولة لحَربِه, فذَلَّ وسَلَّمَ نَفسَه إلى أخيه, فغدر به وحبسه بشيراز إلى أن مات. تعَلّ"},{"id":1302,"era":"c4","t":"وفاة أبي بكر الزبيدي أحد علماء النحو واللغة .","s":"هو أبو بكرٍ مُحمَّدُ بنُ الحَسَن بن عبد الله بن مَذْحِج بنِ محمد بن عبد الله بن بشر الزبيدي الإشبيليُّ نَزيلُ قرطبة؛ كان واحِدَ عَصرِه في علم النحو وحِفظِ اللغة، وكان أخبَرَ أهلَ زمانِه بالإعراب والمعاني والنوادر، إلى علمِ السِّيَر والأخبار، ولم يكُنْ بالأندلس في فنه مثلُه في زمانه، وله كتُبٌ تدُلُّ على وفورِ عِلمِه؛ منها \"مختصر كتاب العين\" وكتاب \"طبقات النحويين واللغويين بالمشرق والأندلس\" و \"لحن "},{"id":1303,"era":"c4","t":"ابتداء دولة بني مروان بديار بكر .","s":"لَمَّا قُتِلَ باذ الكردي سار ابنُ أخته أبو عليِّ بنُ مروان الكردي في طائفةٍ مِن الجيش إلى حصن كيفا، وهو على دجلة، وهو من أحصَنِ المعاقل، وكان به امرأةُ باذ وأهلُه، فلمَّا بلغ الحِصنَ قال لزوجة خالِه: قد أنفذني خالي إليك في مُهِمَّة، فظنَّتْه حقًّا، فلمَّا صَعِدَ إليها أعلَمَها بهلاكِه، وأطمَعَها في التزوُّجِ بها، فوافقَتْه على مُلكِ الحِصنِ وغَيرِه، ونزل وقصَدَ حصنًا حصنًا، حتى مَلَك ما كان لخالِه"},{"id":1304,"era":"c4","t":"تفاقم خطر العيَّارين في بغداد وقيام فتنة بينهم وبين أهلها .","s":"تفاقَمَ الأمرُ بالعيَّارينَ (وهم طائفة من أهل الدعارة والنهب واللصوصية) ببَغداد وصار الناسُ أحزابًا، في كلِّ مَحلَّةٍ أميرٌ مُقَدَّمٌ، واقتتل النَّاسُ وأُخِذَت الأموالُ، وأُحرِقَت دُورٌ كِبارٌ، ووقع حريقٌ بالنَّهارِ في نهر الدجاج، فاحتَرَق بسببه شيءٌ كثيرٌ للناسِ."},{"id":1305,"era":"c4","t":"مسير جيش العزيز العبيدي (الفاطمي) إلى حلب للاستيلاء عليها .","s":"لَمَّا مات سعدُ الدَّولةِ الحَمدانيُّ صاحِبُ حَلَب، سار الوزيرُ أبو الحسن المغربي من مَشهدِ عليٍّ إلى العزيز بمصرَ، وأطمَعَه في حلب، فسيَّرَ جيشًا وعليهم منجوتكين أحدُ أمرائه إلى حلب، فسار إليها في جيش ٍكثيفٍ فحَصَرها، وبها أبو الفضائلِ ولؤلؤٌ، فكتبا إلى بسيل مَلِكِ الرومِ يستَنجِدانِه، وهو يقاتِلُ البلغار، فأرسل بسيل إلى نائِبِه بأنطاكيةَ يأمُرُه بإنجاد أبي الفضائل، فسار في خمسينَ ألفًا، حتى نزل "},{"id":1306,"era":"c4","t":"خلع الخليفة العباسي الطائع لله واستخلاف ابن عمه القادر بالله .","s":"قيل في سَبَبِ خَلعِ الطائعِ وهو عبد الكريم أبو بكر عِدَّةُ أشياءَ؛ منها: أنَّه عجز عن دفع مصاريفِ الجُندِ، ومنها أنَّه بسَجنِه للشَّيخِ المفيدِ سَبَّبَ ذلك جفوةً بينه وبين بهاءِ الدَّولة، وقيل غيرُ ذلك، فكان خَلعُه حين جاء بهاءُ الدولة إلى دارِ الخلافة، وقد جلس الطائِعُ متقلِّدًا سيفًا، فلما قَرُب بهاءُ الدولة قبَّل الأرضَ، وتقَدَّمَ أصحابُه فجذبوا الطائِعَ بحَمائلِ سيفِه، وتكاثروا عليه ولَفُّوه ف"},{"id":1307,"era":"c4","t":"وفاة جوهر الصقلي القائد الأول في الدولة العبيدية (الفاطمية)  .","s":"هو الأميرُ الكبيرُ, قائِدُ الجُيوشِ, أبو الحسَنِ جَوهرُ بنُ عبد الله الروميُّ الصقلِّيُّ، قائد المعِزِّ الفاطميِّ, مِن نُجَباء الموالي. كان عاليَ الهِمَّة, نافِذَ الأمر. فتح مِصرَ للفاطميِّينَ فأنهى الحُكمَ الإخشيديَّ عليها لَمَّا تهيَّأَ له أخذُ البلاد بمُكاتبةٍ مِن أمراء مصر, عندما قَلَّت عليهم الأموالُ, اختَطَّ القاهِرةَ في اللَّيلةِ التي دخل فيها مِصرَ, والجامِعَ الأزهَرَ، كُلُّ ذلك قبلَ مجيءِ"},{"id":1308,"era":"c4","t":"القبض على أبي الحسن بن المعلم الكوكبي الوزير .","s":"كان أبو الحَسَنِ بنُ المعَلِّم وزيرُ بَهاءِ الدولة البُويهيِّ, قد استولى على الأمورِ كُلِّها، وخَدَمَه النَّاسُ كُلُّهم، حتى الوزراء، فمنع أهلَ الكرْخِ وبابَ الطاقِ مِن النَّوْحِ يومَ عاشوراء، ومِن تعليق المُسُوحِ، الذي كان يُعمَلُ به من نحوِ ثلاثينَ سَنَة، وكان المقرِّبُ مَن قرَّبه، والمُبْعَدُ مَن بعَّده، فثَقُلَ على الأُمَراء أمرُه، ولم يُراعِهم هو، فأجابهم السُّلطانُ، فشَغَّبَ الجندُ في هذا ال"},{"id":1309,"era":"c4","t":"حصار ملك الروم لملاذكرد  .","s":"نزل مَلِكُ الرومِ بأرمينيَّة، وحصَرَ مدن تركية (خلاط، وملاذكرد، وأرجيش)، فضَعُفَت نفوسُ الناس عنه، ثم هادَنَه أبو عليٍّ الحسَنُ بنُ مروان مدة عشر سنين، وعاد مَلِكُ الرُّومِ."},{"id":1310,"era":"c4","t":"غزو الترك بخارى وهزيمتهم أمام السامانيين .","s":"سار شِهابُ الدَّولةِ هارونُ بنُ سُلَيمان إيلك- المعروفُ ببغراخان التركي- مَلِكُ الترك، بعساكِرِه إلى بخارى، فسيَّرَ الأميرُ نوح بن منصور جيشًا كثيرًا، ولَقِيَهم إيلك وهزَمَهم، فعادوا إلى بخارى، وهو في أثَرِهم، فخرج نوحٌ بنَفسِه وسائِرُ عَسكرِه، ولقيه فاقتتلوا قتالًا شديدًا وأجْلَت المعركةُ عن هزيمة إيلك فعاد منهزمًا إلى بلاساغون، وهي كرسيُّ مملكتِه."},{"id":1311,"era":"c4","t":"بناء أول دار للعلم ووقفه على الفقهاء في بغداد  .","s":"ابتاع أبو نصرٍ سابورُ بن أردشير وزيرُ بهاءِ الدَّولةِ بنِ بُوَيه دارًا بالكرخ غرب بغداد وجَدَّد عِمارَتَها، ونقل إليها كتبًا كثيرة، ووقَفَها على الفُقَهاء، وسَمَّاها دارَ العلم، فكانت أوَّلَ مَدرسةٍ وُقِفَت على الفُقَهاءِ، وكانت قبل النظاميَّة بمدَّةٍ طويلةٍ."},{"id":1312,"era":"c4","t":"ملك الترك بغراخان ينتزع بخارى من السامانيين ثم يستردونها منه .","s":"ملك مدينة بخارى شهابُ الدولة هارون بن سليمان إيلك المعروفُ ببغراخان التركي، وكان له كاشغر وبلاساغون إلى حدِّ الصين، وكان سبَبُ ذلك أنَّ أبا الحسن بنَ سيمجور لَمَّا مات ووليَ ابنُه أبو عليٍّ خُراسانَ بعده، فسار نحو بخارى، وقصَدَ بلادَ السامانيَّة، فاستولى عليها شيئًا بعد شيءٍ، فسيَّرَ إليه نوح جيشًا كبيرًا، واستعمل عليهم قائدًا كبيرًا من قوَّادِه اسمه انج، فلَقِيَهم بغراخان، فهَزَمهم وأسرَ انج وجما"},{"id":1313,"era":"c4","t":"فتنة العيارين ببغداد .","s":"عَظُمَ خَطبُ العيَّارينَ (وهم طائفة من أهل الدعارة والنهب واللصوصية)، وعاثُوا ببغداد فسادًا، وأخذوا الأموالَ والعُملاتِ الثِّقالَ ليلًا ونهارًا، وحَرَقوا مواضِعَ كثيرةً، وأخذوا من الأسواقِ الجباياتِ، وتطَلَّبَهم الشُّرَطُ، فلم يُفِدْ ذلك شيئًا ولا فَكَّروا في الدولة، بل استمَرُّوا على ما هم عليه من أخذِ الأموالِ، وقَتْلِ الرِّجالِ، وإرعابِ النِّساءِ والأطفال، في سائِرِ المحالِّ، فلمَّا تفاقم الحال"},{"id":1314,"era":"c4","t":"فتنة الأصيفرَ الأعرابيَّ ومنعه لأهل العراق والشام واليمن من الحج .","s":"رجع رَكْبُ العراقِ أثناءَ طَريقِهم للحَجِّ بعدما فاتَهم الحَجُّ، وذلك أنَّ الأصيفرَ الأعرابيَّ الذي كان قد تكفَّلَ بحِراستِهم اعتَرَض لهم في الطريقِ وذكَرَ لهم أنَّ الدنانيرَ التي أُقطِعَت له من دارِ الخلافةِ كانت دراهِمَ مَطليَّةً، وأنَّه يريدُ مِن الحَجيجِ بدَلَها، وإلَّا لا يدَعُهم يتجاوزونَ هذا المكان، فمانعوه وراجَعوه، فحبَسَهم عن السَّيرِ حتى ضاق الوقتُ ولم يبقَ فيه ما يُدركون فيه الحَجَّ، ف"},{"id":1315,"era":"c4","t":"وفاة الصاحب بن عباد الوزير .","s":"هو أبو القاسِمِ إسماعيلُ بنُ عَبَّاد بن عباس بن عباد بن أحمد بن إدريس الطالقاني الوزيرُ المشهورُ بكافي الكُفاة، وزَرَ لمؤَيَّد الدولة بن رُكنِ الدولة بن بُوَيه. هو أوَّلُ مَن سُمِّيَ بالصَّاحِبِ؛ لأنَّه صَحِبَ مُؤَيَّد الدولة من الصِّبا، وسَمَّاه الصاحِبَ، فغَلَب عليه، ثمَّ سُمِّيَ به كلُّ مَن وَلِيَ الوَزارةَ بعده، وقيل: لأنَّه كان يصحَبُ أبا الفضل بن العَميدِ، فقيل له صاحِبُ ابن العميد، ثم خُفِّ"},{"id":1316,"era":"c4","t":"غزو المنصور بن أبي عامر الفرنجة في الأندلس .","s":"سير المنصورُ مُحمَّد بن أبي عامر عَسكرًا إلى بلادِ الفرنج للغزو، فنالوا منهم وغَنِموا، وأوغلوا في ديارِهم، وأسروا غرسيَّة، وهو مَلِكٌ للفِرنجِ بنُ مَلِكٍ مِن مُلوكِهم يقال له شانجة، وكان من أعظَمِ مُلوكِهم وأمنَعِهم."},{"id":1317,"era":"c4","t":"وفاة الحافظ الدَارَقُطني .","s":"هو الإمامُ الحافِظُ المَجَوِّد, شيخُ الإسلام, عَلَمُ الجهابِذةِ, أبو الحسَنِ عليُّ بنُ عُمَرَ بنِ أحمد بن مهدي بن مسعود بن دينار بن عبد الله الدَارَقُطنيُّ، الحافِظُ الكبير، المقرئُ المحَدِّث, كان عالِمًا حافِظًا فقيهًا على مذهَبِ الإمام الشافعي. أخذ الفِقهَ عن أبي سعيدٍ الاصطخريِّ الفقيهِ الشافعي. كانت ولادتُه في ذي القعدة سنة 306. والدَّارَقُطنيُّ بفتحِ الدالِ المُهملة وبعدَ الألف راءٌ مفتوحة ثم"},{"id":1318,"era":"c4","t":"المنصور الأندلسي يضم إليه قبائل صنهاجة ويحتل مدينة فاس .","s":"قام زيري بنُ عطيَّةَ بالخُروجِ على المنصورِ بنِ أبي عامر الأندلسي، فجهَّزَ المنصورُ ابنُ أبي عامر جيشًا كبيرًا بقيادة غُلامِه واضح، وضَمَّ له قبائِلَ صِنهاجةَ المُعادية لزيري، فاقتتل في وادٍ بقُربِ طنجة وانتهى القتالُ باحتلال مدينة فاس وهزيمةِ زيري الذي هرب ولجأَ إلى بلاد صنهاجة بالمغرب الأقصى حتى توفِّيَ فيها."},{"id":1319,"era":"c4","t":"بداية الدولة العقيلية في الموصل .","s":"مَلَكَ المقَلَّدُ بنُ المسيب مدينةَ الموصل، وكان سبَبُ ذلك أنَّ أخاه أبا الذواد توفِّيَ هذه السنة، فطَمِعَ المقلدُ في الإمارة، فلم تساعِدْه عقيل على ذلك، وقلَّدوا أخاه عليًّا؛ لأنه أكبَرُ منه، فأسرع المقلد واستمال الديلمَ الذين كانوا مع أبي جعفرٍ الحَجَّاج بالموصِل، فمال إليه بعضُهم، وكتب إلى بهاءِ الدَّولةِ أنْ قد ولَّاه المَوصِل، وسأله مساعدتَه على أبي جعفرٍ؛ لأنَّه قد منعه عنها، فساروا ونزلوا ع"},{"id":1320,"era":"c4","t":"وفاة أمير إفريقيَّة المنصور بن يوسف وولاية ابنه باديس .","s":"هو المنصورُ بنُ يوسُفَ بلكين أميرُ إفريقيَّة، كان مَلِكًا شجاعًا، عادِلًا حازِمًا. توفِّيَ خارج صبرة، ودُفِنَ بقَصرِه. وَلِيَ بَعدَه ابنُه باديس، ويكَنَّى بأبي مناد، فلما استقَرَّ في الأمر سار إلى سردانية، وأتاه النَّاسُ مِن كُلِّ ناحية للتَّعزيةِ والتهنئة، وأراد بنو زيري أعمامُ أبيه أن يخالِفوا عليه، فمنَعَهم أصحابُ أبيه وأصحابُه, وأتته الخِلَعُ والعَهدُ بالولايةِ مِن العزيزِ حاكِمِ مِصرَ العُبَي"},{"id":1321,"era":"c4","t":"وفاة العزيز العبيدي (الفاطمي) وتولي ابنه الحاكم بأمر الله .","s":"هو العزيزُ صاحِبُ مِصرَ أبو منصور نزار بن المعِزِّ معد بن إسماعيل العبيدي المهدي المغربي. ولِدَ سنة 344. قام بعد أبيه في ربيع الأول، سنة 365. وكان كريمًا شُجاعًا صفوحًا، أسمَرَ أصهَبَ الشَّعرِ أعيَنَ أشهَلَ، بعيدَ ما بين المَنكِبَينِ، حسنَ الأخلاقِ قَريبًا من الرَّعيَّة، مُغرَمًا بالصيدِ، ويُكثِرُ مِن صيد السِّباعِ، ولا يُؤثِرُ سَفكَ الدماء. فُتحِتَ له حلب وحماة وحِمص. وخطب أبو الذواد محمَّد بن ال"},{"id":1322,"era":"c4","t":"وفاة الإمام ابن بطة .","s":"هو الإمامُ القُدوةُ العابدُ المحَدِّثُ, شيخُ العراق, أبو عبدِ الله عُبيد الله بنُ محمد بن حمدان، العكبريُّ المعروف بابن بطَّة، أحدُ عُلماءِ الحنابلة، وُلِدَ سنة 304 في عُكبَرا – تقع عُكبَرا على نهرِ دجلة بين سامرَّاء وبغداد- قال ابن بطة: \"كان لأبي ببغداد شُرَكاءُ, فقال له أحدُهم: ابعَثْ بابنك إلى بغدادَ؛ لِيَسمَعَ الحديث, قال: هو صغيرٌ. قال: أنا أحمِلُه معي, فحمَلَني معه, فجئتُ فإذا ابنُ منيعٍ يُق"},{"id":1323,"era":"c4","t":"المنصور ابن أبي عامر الأندلسي يغزو مدينة شنت ياقوب الأسبانية .","s":"عندما تناهى المنصورُ بن أبي عامر في هذا الوقتِ على الاقتدار، والنَّصر على ملوك النصارى، سما إلى مدينة شنت ياقوب قاصية غلبسية، وأعظَمِ مَشاهِدِ النَّصارى الكائنةِ ببلاد الأندلُس وما يتَّصِلُ بها من الأرضِ الكبيرة. وكانت كَنيستُها عندهم بمنزلةِ الكَعبةِ عند المُسلِمينَ، فبِها يحلِفونَ وإليها يَحُجُّونَ مِن أقصى بلاد رومة وما وراءها، ويَزعُمونَ أنَّ القبر المزوَّرَ فيها قبر ياقوب أحد الحواريِّين الاث"},{"id":1324,"era":"c4","t":"عصيان أهل مدينة صور على الحاكم بأمر الله الفاطميِّ العُبيديِّ .","s":"قام أهلُ صور بالثَّورةِ على الحاكِمِ الفاطميِّ لَمَّا لَحِقَهم مِن جُندِه المغاربة البَربرِ الظُّلمُ والجَورُ، وأخذ الحريم من الحَمَّامات والطُّرُق, فقام أهلُ صور عليهم, بعد أن استنجَدوا بالإمبراطورِ البيزنطيِّ باسيل الثاني، فأمَدَّهم بأسطول. فقتلوا المغاربةَ البَربرَ، فأرسل جيشُ ابنِ الصمصامة جيشًا مِن مصر بقيادةِ أبي عبد الله الحسن بن ناصر ومعه ياقوت الخادِمُ, كما أرسل الحاكِمُ أسطولًا إلى طرابل"},{"id":1325,"era":"c4","t":"وفاة محمد الخوارزمي صاحب كتاب مفاتيح العلوم .","s":"هو مُحمَّدُ بنُ أحمد بن يوسُفَ البَلخيِّ الخوارزمي، صاحِبُ كتابِ مفاتيح العُلوم، وهو كالمُعجَم للمُصطَلَحات المُستعمَلَة في جميعِ فُروعِ العِلمِ، وكان سببُ التأليفِ هو اتِّصالَه بأبي الحَسَنِ العتبي وزيرِ الأميرِ نوح السَّاماني."},{"id":1326,"era":"c4","t":"وفاة نوح بن منصور الساماني وبدأ انهيار الدولة السامانية .","s":"هو سُلطان بُخارى وسَمَرقند وابنُ سلاطينِها, أبو القاسِمِ نوحُ بنُ منصور بنِ نوحِ بنِ عبد الملك بن نصر بن أحمد بن إسماعيل بن أحمد بن أسد بن سامان. تمَلَّك نوحٌ خُراسانَ وغزنةَ وما وراء النهر, ولَمَّا توفِّيَ الأميرُ نوحُ بنُ منصور الساماني اختَلَّ بموته مُلكُ آل سامان، وضَعُف أمرُهم ضعفًا ظاهِرًا، وطَمِعَ فيهم أصحابُ الأطراف، فزال مُلكُهم بعد مدَّةٍ يسيرة. ولَمَّا توفِّيَ نوحٌ بعد أنْ حَكَم اثنتين "},{"id":1327,"era":"c4","t":"وفاة فخر الدولة بن بُوَيه وإقامة ولده رستم مكانه .","s":"هو فَخرُ الدولة أبو الحَسَنِ عليُّ بن ركن الدولة الحسَن بن بُوَيه أميرُ الرَّيِّ وهمذان. وُلِدَ سنة 341, ولَمَّا توفِّيَ أخوه مؤيد الدولة في شعبان سنة 373ه بجرجان، استولى على مملكتِه، فأقَرَّ الصاحِبَ ابنَ عبَّاد على وزارته، وكان مُبَجَّلًا عند فخر الدولة, ومُعَظَّمًا نافِذَ الأمر، كان فخرُ الدولة شهمًا شُجاعًا، لَقَّبَه الخليفةُ الطائِعُ مَلِكَ الأمة, توفِّيَ بقلعة طبرق, عن سِتٍّ وأربعين سنة، وكا"},{"id":1328,"era":"c4","t":"وفاة الإمام الخطابي .","s":"هو حَمدُ بنُ محمد بن إبراهيم البُستي الخطَّابي، المحدِّثُ الفقيهُ الأديب اللُّغويُّ، ولد سنة بضع عشرة وثلاثمائة. تحوَّل إلى طلب العِلمِ ورحَلَ إلى العراق والحجاز وغيرها، تفَقَّه على القَفَّال الكبير. له تصانيفُ كثيرةٌ، أشهرُها: معالم السُّنَن، وهو شَرحٌ لسُنَن أبي داود، وشرح للبخاريِّ، وكتاب غريب القرآن، وإصلاح غلط المحدِّثين، وإعجاز القرآن، وغيرها، توفي ببست, وقيل: إنه توفي في سنة 386هـ."},{"id":1329,"era":"c4","t":"مقتل صمصام الدولة ابن عضد الدولة .","s":"هو صمصامُ الدَّولةِ بنُ عَضُدِ الدولة، وهو صاحِبُ بلاد فارس، وكان سبَبُ قَتلِه أنَّ جماعةً كثيرة من الديلم استوحشوا مِن صمصام الدولة؛ لأنَّه أمرَ بعَرضِهم، وإسقاطِ من ليس بصحيحِ النَّسَب، فأسقط منهم مقدارَ ألفِ رجُل، واتَّفَق أنَّ أبا القاسم وأبا نصر ابني عزِّ الدولة بختيار كانا مقبوضَينِ، فخدعا الموكَّلينِ بهما في القلعة، فأفرجوا عنهما، فجَمَعا لفيفًا من الأكراد، واتَّصَل خبرُهما بالذين أُسقِطوا "},{"id":1330,"era":"c4","t":"قيام الدولة الغزنوية وزوال السامانية .","s":"انقَرَضت دولةُ آلِ سامان على يدِ محمودِ بنِ سبكتكين، وإيلك الخان التركي، واسمُه أبو نصر أحمد بن علي، ولَقَبُه شمس الدولة، فأمَّا محمود فإنَّه مَلَك خُراسان، وبَقِيَ بيَدِ عبد الملك بنِ نوح ما وراء النَّهر، فلما انهزم من محمود قَصَدَ بُخارى واجتمع بها هو وفائِقُ وبكتوزون وغيرُهما من الأمراء والأكابر، فقَوِيَت نفوسُهم، وشَرَعوا في جمعِ العساكِر، وعَزَموا على العَودِ إلى خراسان، فاتَّفَق أن مات فائق،"},{"id":1331,"era":"c4","t":"الشيعة في بغداد يحتفلون بيوم الغدير وحصول فتنة مع أهل السنة .","s":"أراد الشِّيعةُ أن يصنَعوا ما كانوا يصنعونَه من الزينة يومَ غديرِ خُمٍّ، وهو اليوم الثامن عشر من ذي الحِجَّة فيما يزعمونَه، فقاتلهم جهَلَةٌ آخرون في المنتَسِبينَ إلى السُّنَّة بعد أن ادَّعَوا أنَّ في مثل هذا اليوم حُصِرَ النبيُّ صلَّى الله عليه وسلم وأبو بكرٍ في الغار فامتنعوا من ذلك، وهذا أيضًا جَهلٌ من هؤلاء، ولَمَّا كان الشِّيعةُ يصنعون في يوم عاشوراء مأتمًا يُظهِرونَ فيه الحُزنَ على الحُسَين بن"},{"id":1332,"era":"c4","t":"قتل برجوان وزير الحاكم العبيدي (الفاطمي) .","s":"كان قَتلُ برجوان وزيرُ الحاكمِ الفاطميِّ في بستانٍ يُعرَفُ بدويرة التين والعنب، كان الحاكم فيه مع زيدان فجاء برجوان ووقفَ مع زيدان، فسار الحاكِمُ حتى خرج من باب الدويرة، فعاجل زيدان وضَرَبَ برجوان بسِكِّينٍ كانت في خُفِّه، وابتدره قومٌ، وقد أعدُّوا له السكاكينَ والخناجِرَ، فقُتِلَ مكانَه، وحُزَّت رأسُه وطرح عليه حائِطٌ، وسبب ذلك أن برجوان لَمَّا بلغ النهاية قصَّرَ في الخدمة، واستقَلَّ بلَذَّاتِه و"},{"id":1333,"era":"c4","t":"مقتل الأمير بختيار واستيلاء بهاء الدولة على بلادِ كرمان .","s":"قُتِلَ الأميرُ أبو نصر بن بختيار، الذي كان قد استولى على بلادِ فارس. وسبَبُ قَتلِه أنَّه لَمَّا انهزم مِن عَسكَرِ بهاء الدولة بشيراز، سار إلى بلاد الديلم، وكاتب الديلمَ بفارس وكرمان من هناك يستميلُهم، وكاتَبوه واستدعَوه، فسار أبو نصرٍ إلى بلادِ فارس، واجتمع عليه جمعٌ كثيرٌ مِن الزطِّ، والديلم، والأتراك، وتردَّد في تلك النواحي, ثمَّ سار إلى كرمان، فلم يَقبَلْه الديلم الذين بها، وكان المُقَدَّمَ علي"},{"id":1334,"era":"c4","t":"انتصار المسلمين في موقعة جربيرة بالأندلس بقيادة ابنِ أبي عامرٍ .","s":"تحالفَت كُلُّ قوى النصرانيَّة مِن أجْلِ الصُّمودِ في وَجهِ قُوَّةِ المُسلِمينَ بقِيادةِ المنصورِ بنِ أبي عامرٍ في وقعة جربيرة، التقى فيها الفريقان عند مكانٍ شَديدِ الوُعورةِ يُسمَّى بصَخرةِ جربيرة، وكاد المنصور أن يُهزَمَ لأوَّلِ مَرَّة في معاركِه، ولكِنَّ بَسالةَ المُسلِمينَ وشِدَّةَ بأسِهم في القِتالِ أنهَت المعركةَ بهزيمةٍ مُرَوِّعة للتَّحالُفِ النَّصرانيِّ، وقُتِلَ مُعظَمُ قادة الصَّليبيِّينَ "},{"id":1335,"era":"c4","t":"قبائل القرة خانيون يحتلون بخارى ويقضون على الدول السامانية .","s":"احتلَّت قبائِلُ القرَّة خانيون بزعامةِ أرسلان إيليغ خان مدينةَ بخارى، وأنهَت الحُكمَ الإيرانيَّ في تركستان، وقَضَت على الدُّوَل السَّامانية، كما أنها استولَت على سمرقند وبلادِ ما وراء النهر حتى حُدودِ خُراسان. والقُرَّة خانيون قبائِلُ تُركيَّةٌ اعتَنَقَت الإسلامَ وساهمت بدَورٍ في حمايةِ الإسلامِ."},{"id":1336,"era":"c4","t":"فتنة بين الأتراك ومعهم أهل السنة وبين أهل الكرخ الشيعة .","s":"ثار الأتراكُ ببغداد بنائِبِ السُّلطانِ، وهو أبو نصرٍ سابورُ بنُ أردشير وزيرُ بهاءِ الدَّولة البُويهيِّ، فهَرَب منهم، ووقَعَت الفتنةُ بين الأتراك والعامَّة مِن أهل الكَرخِ وهم رافِضةٌ، وقُتِلَ بينهم قتلى كثيرونَ، ثمَّ إنَّ السُّنَّةَ مِن أهل بغداد ساعدوا الأتراكَ على أهلِ الكَرخِ، فضَعفوا عن الجميع، فسعى الأشرافُ في إصلاحِ الحالِ فسَكَنَت الفِتنةُ."},{"id":1337,"era":"c4","t":"مبايعة الخليفة العباسي القادر بالله لولده أبي الفضل بالعهد .","s":"أمَرَ الخليفةُ القادِرُ بالله بالبيعةِ لِوَلَدِه أبي الفَضلِ بولايةِ العَهدِ، وأحضَرَ حُجَّاجَ خُراسان وأعلَمَهم ذلك، وكان سبَبُ هذه البيعةِ أنَّ رَجُلًا يقال له عبدُ الله بن عثمان الواثقيُّ من ولَدِ الواثِقِ بالله أحدِ الخُلَفاء السَّابقين، كان مِن أهلِ نصيبينَ، ذهَبَ إلى بعضِ الأطرافِ من بلادِ التُّركِ، وادَّعى أنَّ القادِرَ بالله جعَلَه وليَّ العَهدِ مِن بَعدِه، فخَطَبوا له هنالك، فلمَّا بلغ ال"},{"id":1338,"era":"c4","t":"محمود بن سبكتكين يغزو الهند .","s":"أوقَعُ يمينُ الدَّولةِ محمودُ بنُ سبكتكين بجيبال ملِكِ الهند وقعةً عَظيمةً، وسببُ ذلك أنَّه لَمَّا اشتغَلَ بأمر خراسان ومَلِكِها، وفرغ منها ومِن قتال خلَفِ بنِ أحمد، وخلا وجهُه مِن ذلك؛ أحَبَّ أن يغزوَ الِهندَ غزوةً تكونُ كَفَّارةً لِما كان منه من قتالِ المُسلِمينَ، فثنى عنانَه نحو تلك البلادِ، فنزل على مدينة برشور، فأتاه عدوُّ الله جيبال مَلِكُ الهند في عساكِرَ كثيرةٍ، فالتَقَوا في المحرَّمِ مِن "},{"id":1339,"era":"c4","t":"ثورة العوام على النصارى ببغداد  .","s":"ثارت العوامُّ على النَّصارى ببغداد، فنَهَبوا كنيسَتَهم التي بقطيعةِ الدَّقيقِ وأحرقوها، فسَقَطَت على خَلقٍ فماتوا، وفيهم جماعةٌ مِن المُسلِمينَ: رجالٌ ونِساءٌ وصِبيانٌ."},{"id":1340,"era":"c4","t":"وفاة النحوي اللغوي الشهير أبي الفتح عثمان بن جني .","s":"هو أبو الفَتحِ عُثمانُ بنُ جِنِّيٍّ، المَوصِليُّ النَّحويُّ اللُّغَويُّ المشهور، كان إمامًا في عِلمِ العربيَّة، صاحِبَ التصانيف الفائقة المُتداولة في النَّحو واللغة. قرأ الأدبَ على الشيخِ أبي عليٍّ الفارسيِّ، فارقه وقعَدَ للإقراء بالمَوصِل، وكان أبوه جِنِّيٌّ مملوكًا روميًّا لسُلَيمانَ بنِ فَهدِ بنِ أحمد الأزدي المَوصِليِّ، وابنُ جِنيٍّ واحِدٌ من أنفَعِ العُلَماءِ في علومِ العَرَبيَّة على مرِّ الت"},{"id":1341,"era":"c4","t":"توقف الحج من بلاد المشرق بسبب فتنة الأعراب .","s":"قَدِمَ الحُجَّاجُ مِن خُراسان إلى بغداد؛ لِيَسيروا إلى الحجازِ، فبلَغَهم عَيثُ الأعرابِ في الأرضِ بالفَسادِ، وأنَّه لا ناصِرَ لهم ولا ناظِرَ يَنظُرُ في أمرِهم، فرجعوا إلى بلادِهم ولم يحُجَّ من بلادِ المَشرِقِ أحدٌ في هذه السَّنةِ."},{"id":1342,"era":"c4","t":"وفاة المنصور ابن أبي عامر الأندلسي .","s":"هو المَلِكُ المنصور، حاجِبُ الممالك الأندلسيَّة، أبو عامر، محمَّدُ بن عبد الله بن أبي عامر مُحمَّد بن وليد المعافري القَحطاني القُرطُبي، قَدِمَ قُرطبةَ شابًّا لطلَبِ العِلمِ والأدَبِ، وكان عنده هِمَّةٌ عاليةٌ، وكَّلَتْه زوجةُ الحاكِمِ المُستنصِر صبحَ البكشنجية أمورَها وإدارةَ ضياعِها وبَقِيَ يترقَّى حتى تولَّى الشُّرطةَ والإشرافَ على الأموالِ، ثمَّ صار وكيلًا لوليِّ العَهدِ هشامٍ، فلمَّا تسَلَّمَ "},{"id":1343,"era":"c4","t":"نهاية الدولة الصفارية في سجستان .","s":"مَلَك يَمينُ الدَّولةِ محمودُ بنُ سبكتكين سجستانَ، وانتزَعَها مِن يدِ خلَفِ بنِ أحمدَ الصَّفَّار، وكان سبَبُ أخْذِها أنَّ يمينَ الدَّولةِ لَمَّا رحَلَ عن خلَفٍ بعد أن صالَحَه، سنة تسعينَ وثلاثمِئَة، عَهِدَ خَلَفٌ إلى ولَدِه طاهرٍ، فلمَّا استقَرَّ طاهِرٌ في المُلكِ عقَّ أباه وأهمَلَ أمْرَه، فلاطَفَه أبوه ورفَقَ به، حتى قبضَ على أبيه وسَجَنه، وبقِيَ في السِّجنِ إلى أن مات فيه، وأظهَرَ عنه أنَّه قتَل"},{"id":1344,"era":"c4","t":"محاصرة مدينة قابس بالمغرب .","s":"سار يحيى بنُ عليٍّ الأندلُسيُّ وفلفل بن سعيدٍ مِن طرابلسَ إلى مدينة قابس في عسكرٍ كثيرٍ، فحَصَروها، ثمَّ رَجَعوا إلى طرابلس، ولَمَّا رأى يحيى بنُ عليٍّ مِن قِلَّةِ المالِ، واختلالِ حالِه وسُوءِ مُجاوَرةِ فلفل وأصحابِه له، رجعَ إلى مصرَ إلى الحاكِمِ العُبَيديِّ، بعد أن أخذَ فلفل وأصحابُه خُيولَهم، وما اختاروه مِن عُدَدِهم بين الشِّراءِ والغَصبِ، فأراد الحاكِمُ قَتْلَه، ثمَّ عفا عنه."},{"id":1345,"era":"c4","t":"الأصيفر الشيعي يعترض حجاج أهل العراق .","s":"حَجَّ بالنَّاسِ مِن العراقِ أبو الحارِثِ محمَّدُ العَلَويُّ، فاعتَرَض الرَّكبَ الأُصيفِرُ الشِّيعيُّ الأعرابيُّ، وعَوَّل على نهبِهم، فقالوا: مَن يكَلِّمُه ويقَرِّرُ له ما يأخُذُه مِن الحاجِّ؟ فقَدَّموا أبا الحُسَينِ بنَ الرفاء وأبا عبد الله بن الدجاجيَّ، وكانا من أحسَنِ النَّاسِ قراءةً، فدخلا عليه وقرآ بينَ يديه، فقال لهما: كيف عَيشُكما ببغداد؟ قالا: نِعمَ العَيشِ، تَصِلُنا الخِلَعُ والصِّلاتُ. فق"},{"id":1346,"era":"c4","t":"هدم جامع عمرو بن العاص في مصر .","s":"أمَرَ الحاكِمُ الفاطميُّ بهَدمِ جامِعِ عَمرِو بنِ العاصِ بالإسكندريَّةِ."},{"id":1347,"era":"c4","t":"نهاية الدولة الحمدانية بحلب .","s":"كان لؤلؤ الجراحيُّ مولى الحَمدانِيِّينَ وَصِيًّا على سعيدِ الدَّولةِ بعدَ وفاةِ أبيه سَعدِ الدَّولةِ عامَ 381هـ، ثمَّ في عام 392هـ تُوفِّيَ سعيدُ الدَّولةِ، وخَلَّفَ ولدَيه أبا الحَسَنِ عليًّا وأبا المعالي شريفًا أميرَينِ على حَلَب، وكان لؤلؤٌ هو مَن يقومُ بتَدبيرِ جَميعِ الأمور، ثمَّ قام بإرسالِهما مع باقي أهلِ البَيتِ الحَمدانيِّ إلى مِصرَ إلى الحاكِمِ الفاطميِّ، واستبَدَّ هو بحُكمِ حَلَب، فكانت"},{"id":1348,"era":"c4","t":"يمينُ الدَّولةِ مَحمودُ بنُ سبكتكين يغزو مدينة بهاطيةَ .","s":"غزا يمينُ الدَّولةِ مَحمودُ بنُ سبكتكين بهاطيةَ مِن أعمالِ الهِندِ، وهي وراءَ الملتان، وصاحِبُها يُعرَفُ ببحيرا، وهي مدينةٌ حَصينةٌ، عاليةُ السُّورِ، يُحيطُ بها خَندقٌ عَميقٌ، فامتنَعَ صاحِبُها بها، ثمَّ خرج هو وجُندُه إلى ظاهرِ المدينةِ، فقاتلوا المُسلِمينَ ثلاثةَ أيَّامٍ، ثمَّ انهزموا في الرَّابِعِ، وطَلَبوا المدينةَ ليَدخُلوها، فسَبَقَهم المُسلِمونَ إلى بابِ المدينةِ فمَلَكوه عليهم، وأخذَتْهم ا"},{"id":1349,"era":"c4","t":"وباء وغَلاءٌ شَديدٌ بإفْريقيَّة .","s":"كان بإفريقيَّةَ غَلاءٌ شَديدٌ بحيث تعطَّلَت المخابِزُ والحَمَّامات، وهلك النَّاسُ، وذهَبَت الأموالُ مِن الأغنياءِ، وكَثُر الوَباءُ، فكان يموتُ كُلَّ يومٍ ما بين خمسِمِئَة إلى سَبعِمِئَة."},{"id":1350,"era":"c4","t":"أمر الحاكم العبيدي بسب السلف ولعنهم .","s":"أمَرَ الحاكِمُ بأمْرِه العُبَيديُّ الفاطميُّ بأن يُكتَبَ على سائِرِ المساجِدِ، وعلى الجامِعِ العَتيقِ مِن ظاهِرِه وباطِنِه وفي جميعِ جوانِبِه، وعلى أبوابِ الحَوانيتِ والحَجَر والمقابِر والصَّحراءِ بسَبِّ السَّلَفِ ولَعْنِهم، ونُقِشَ ذلك ولُوِّنَ بالأصباغِ والذَّهَب، وعُمِلَ كذلك على أبوابِ القياسرِ وأبوابِ الدُّورِ، وأكْرَهَ على عمَلِ ذلك، ولَمَّا دخل الحاجُّ نالَهم من العامَّةِ سَبٌّ وبَطشٌ؛ فإنّ"},{"id":1351,"era":"c4","t":"الخطبة في الحج للحاكم العبيدي .","s":"أصابَ الحَجيجُ في الطَّريقِ عَطَشٌ شَديدٌ بحيثُ هَلَك كثيرٌ منهم، وكانت الخُطبةُ في الحَجِّ للحاكِمِ العُبَيديِّ الفاطميِّ حاكِمِ مِصرَ."},{"id":1352,"era":"c4","t":"بعض أوامر الحاكم بأمره العبيدي الفاطمي بمصر .","s":"في السَّابِعِ من المحَرَّم قُرِئَ سجِلٌّ في جوامِعِ مِصرَ يأمُرُ الحاكِمُ العُبَيديُّ اليهودَ والنَّصارى بشَدِّ الزُّنَّار ولُبس الغيار، وشعارُهم السَّوادُ شِعارُ العباسيِّينَ، وقرئ سجِلٌّ في الأطعِمةِ بالمَنعِ مِن أكلِ المُلوخيَّةِ المُحبَّبة لِمُعاويةَ بنِ أبي سُفيان، والبَقلة المسمَّاة بالجرجيرِ المَنسوبة إلى عائشةَ رَضِيَ الله عنها، وفيه المنعُ مِن عَجنِ الخُبزِ بالرِّجلِ، والمنعُ مِن ذَبحِ ال"},{"id":1353,"era":"c4","t":"وفاة ابن فارس صاحب \"المجمل\" و\"المقاييس في اللغة\" .","s":"هو الإمامُ العلَّامةُ اللُّغَويُّ المُحَدِّثُ، أبو الحُسَين: أحمَدُ بنُ فارسِ بنِ زكريَّا بنِ محمَّد بن حبيب القزوينيُّ، المعروفُ بالرَّازيِّ، المالكي، اللُّغَوي الأديب، نزيلُ همذان، وصاحِبُ كِتابِ \"المُجمَل\". مولِدُه بقزوين, ومرباه بهمذان، وأكثَرُ الإقامةِ بالرَّيِّ. وكان رأسًا في الأدَبِ، بصيرًا بفِقهِ مالكٍ، مناظِرًا متكَلِّمًا على طريقةِ أهل الحق، ومذهَبُه في النَّحوِ على طريقةِ الكوفيِّينَ، ج"},{"id":1354,"era":"c4","t":"العبيديون (الفاطميون) ينشئون دار الحكمة بمصر .","s":"أنشأ العُبَيديُّونَ في عَهدِ الحاكِمِ \"دارَ الحِكمةِ\" بالقاهرةِ؛ لِنَشرِ مَذهَبِهم الباطنيِّ, فجَلَس الفُقَهاءُ فيها، وحُمِلَت الكتُبُ إليها، ودخَلَها النَّاسُ للنَّسخِ مِن كُتُبِها وللقِراءةِ، وانتصَبَ فيها الفُقَهاء والقُرَّاء والنُّحاة وغيرُهم من أربابِ العُلومِ، وفُرِشَت وأُقيمَ فيها خُدَّامٌ لخِدمتِها، وأُجرِيَت الأرزاقُ على مَن بها مِن فَقيهٍ وغَيرِه، وجُعِلَ فيها ما يُحتاجُ إليه مِن الحِبرِ"},{"id":1355,"era":"c4","t":"محمود بن سبكتكين يغزو الملتان وكواكير بالهند .","s":"غزا يَمينُ الدَّولةِ مَحمودُ بنُ سبكتكين المولتان، وكان سبَبُ ذلك أنَّ واليَها أبا الفتوحِ نُقِلَ عنه خُبثُ اعتقادِه، ونُسِبَ إلى الإلحاد، وأنَّه قد دعا أهلَ ولايتِه إلى ما هو عليه، فأجابوه. فرأى يمينُ الدَّولة أن يُجاهِدَه ويَستنزِلَه عمَّا هو عليه، فسار نحوه، فابتدأ ببلدِ أندبال قبلَ المولتان، وقال: نجمعُ بين غزوتينِ، فدخَلَ بلادَه، وجاسَها، وأكثَرَ القَتلَ فيها، والنَّهبَ لأموالِ أهلِها، والإحر"},{"id":1356,"era":"c4","t":"بهاءُ الدَّولة بنُ بُوَيه يقمع الفساد ويمنع البدع ببغداد .","s":"اشتَدَّت الفِتنةُ ببغداد، وانتشَرَ العَيَّارون والمُفسِدون، فبَعَث بهاءُ الدَّولة بنُ بُوَيه الدَّيلمي, عميدَ الجُيوشِ أبا عليِّ بنَ أستاذ هرمز إلى العراقِ ليُدَبِّرَ أمْرَه، فوصل إلى بغداد، والفِتَنُ ثائرةٌ بها، فضبط العِراقَ بأتَمِّ سياسةٍ، وأباد الحَراميَّة، وقتل عِدَّةً منهم، فقَمَع الفَسادَ وأهلَه، ومنَعَ الرَّافضةَ مِن إحياءِ مآتِمِ يومِ عاشوراءَ بالنَّوحِ وتَعليقِ المُسوح ببغداد وغيرها، ومن"},{"id":1357,"era":"c4","t":"وفاة أبي عبد الله بن منده الحافظ .","s":"هو الإمامُ الحافِظُ الجَوَّال، مُحَدِّثُ الإسلامِ، أبو عبد اللهِ مُحمَّد بنُ إسحاق بن محمَّد بن يحيى بن مَنْدَه الأصبهاني (الأصفهاني)، صاحِبُ التصانيف. وجَدُّه منده أسلَمَ حين افتتَحَ أصحابُ رَسولِ اللهِ صلَّى اللهُ عليه وسلَّم أصبهانَ، وولاؤه لعبدِ القَيسِ، وكان مجوسيًّا فأسلم، وناب عن بعضِ أعمال أصبهان (أصفهان), وُلِدَ ابنُ مَنْدَه سنة 310، وقيل إحدى عشرة. كان ثَبتَ الحَديثِ والحِفظِ، ورحَلَ إلى"},{"id":1358,"era":"c4","t":"خروج أبي ركوة على الحاكم العبيدي صاحب مصر .","s":"كان أبو ركوة من سُلالةِ هِشامِ بنِ عبدِ الملك بنِ مروان الأموي، واسمُه الوليد، هرب مِن الأندلُسِ وقصَدَ مِصرَ، بعد أن استبَدَّ المنصورُ ابنُ أبي عامرٍ بالحُكمِ في الأندلُس, وإنَّما لُقِّبَ بأبي رَكْوة؛ لرَكْوةٍ (سقاءٍ صغيرٍ) كان يصحَبُها في أسفارِه على طريقةِ الصُّوفيَّةِ، وقد سَمِعَ أبو رَكوةَ الحديثَ بالدِّيارِ المِصريَّة، ثمَّ أقام بمكَّةَ ثُمَّ رحَل إلى اليمَنِ ثمَّ دخل الشَّامَ، وهو في غُضونِ"},{"id":1359,"era":"c4","t":"محمود الغزنوي يهزم ملك الترك الأعظم إيلك الخان  .","s":"لَمَّا أخرج يمينُ الدَّولةِ مَحمودُ بنُ سبكتكين عساكِرَ إيلك الخان مِن خُراسان، راسَلَ إيلك الخان قدرخان بن بغراخان مَلِكَ الختل؛ لقرابةٍ بينهما، وذكَرَ له حالَه، واستعانَ به واستنصَرَه، واستنفَرَ التُّركَ مِن أقاصي بلادها، وسار نحو خُراسان، واجتمع هو وإيلك الخان، فعَبَرا النَّهرَ، وبلغ الخبَرُ يمينَ الدَّولة، وهو بطخارستان، فسار وسبَقَهما إلى بلخ، واستعَدَّ للحَربِ، وجمع التُّركَ الغُزية، والخلج،"},{"id":1360,"era":"c4","t":"محمود بن سبكتكين يغزو الهند .","s":"غزا يمينُ الدَّولةِ مَحمودُ بنُ سبكتكين الهندَ، ولَمَّا وصَله خبَرُ دُخولِ إيلك التركي إلى بلادِه واستيلائِه عليها، رجَعَ مِن فورِه إلى بلادِه واستخلصَها مِن يَدِه، فلمَّا فرَغَ سار نحو الهندِ للغزاة، وسبَبُ ذلك أنَّ بعضَ أولادِ مُلوكِ الهند، يُعرَفُ بنواسه شاه، كان قد أسلَمَ على يَدِه، واستخلَفَه على بَعضِ ما افتتَحَه من بلادِهم، فلمَّا بلَغَه أنَّه ارتَدَّ عن الإسلامِ، ومالأَ أهلَ الكُفرِ والطُّ"},{"id":1361,"era":"c4","t":"رِيحٌ سَوداءُ تمنع أهل العراق من الحج .","s":"هبَّ على الحُجَّاجِ رِيحٌ سَوداءُ بالثَّعلبيَّة أظلَمَت لها الأرضُ، ولم يَرَ النَّاسُ بَعضَهم بعضًا، وأصابَهم عَطَشٌ شَديدٌ، ومنعهم ابنُ الجَرَّاح الطائيُّ مِن المسيرِ؛ ليأخُذَ منهم مالًا، فضاق الوَقتُ عليهم، فعادوا ولم يحُجُّوا."},{"id":1362,"era":"c4","t":"غلاء ومجاعة وريح سوداء في العراق وشغب بين الجند وفتن .","s":"اشتَدَّ الغَلاءُ بالعراقِ، فضَجَّ العامَّةُ، وشَغَّبَ الجُندُ وكانت فِتنةٌ."},{"id":1363,"era":"c4","t":"نزول الثلج ببغداد .","s":"وقَعَ ثَلجٌ كَثيرٌ ببغداد وواسِط والكوفة، والبطائِح إلى عبادان، وكان ببغدادَ نحو ذراع، وبَقِيَ في الطُّرُقِ نحوَ عِشرينَ يَومًا."},{"id":1364,"era":"c4","t":"الحاكم العبيدي يهدم الكنائس ثم يعود يأمر ببنائها مرة أخرى .","s":"أمَرَ الحاكِمُ بأمْرِ اللهِ العُبَيديُّ، صاحبُ مِصرَ، بهَدمِ كَنيسةِ قمامة، وهي بالبيتِ المقَدَّس، وتُسَمِّيها العامَّةُ كنيسةَ القيامة، وإليها يحُجُّونَ مِن أقطارِ الأرض، وأمَرَ بهَدمِ البِيَعِ في جميعِ مَملكَتِه، فهُدِّمَت في هذه السَّنَة عِدَّةُ كنائِسَ ببلادِ مِصرَ، ونودِيَ في النَّصارى: من أحَبَّ الدُّخولَ في دينِ الإسلامِ دخَلَ، ومَن لا يَدخُل فلْيَرجِعْ إلى بلاد الرُّومِ آمِنًا، ومن أقام من"},{"id":1365,"era":"c4","t":"محمود بن سبكتكين يغزو قلعة بهيم نغر .","s":"سار يَمينُ الدَّولة محمودُ بنُ سبكتكين الغزنوي، إلى شاطئِ نَهرِ هندمند، فلاقاه هناك إبرهمن بال بن إندبال في جيوشِ الهند، فاقتَتَلوا مليًّا، وكادت الهندُ تَظفَرُ بالمُسلمين، ثمَّ إنَّ الله تعالى نصَرَ عليهم، فظَفِرَ بهم المُسلمون، فانهزموا على أعقابِهم، وأخَذَهم المُسلِمونَ بالسَّيفِ، وتَبِعَ يمينُ الدَّولة أثَرَ إبرهمن بال، حتى بلغ قلعةَ بهيم نغر، وهي على جَبَلٍ عالٍ كان الهندُ قد جعلوها خِزانةً ل"},{"id":1366,"era":"c4","t":"وفاة بديع الزمان الهمذاني .","s":"هو العلَّامةُ البليغُ، أبو الفَضلِ الحافِظُ أحمدُ بنُ الحُسَينِ بن يحيى الهَمَذانيُّ، الملقَّبُ ببديعِ الزَّمان، صاحِبُ الرَّسائِلِ الرَّائقة، والمقامات الفائِقة، اختَرَع نمطًا من الإنشاءِ عُرِفَ باسمِه، وعلى مِنوالِه نَسَجَ الحَريريُّ مَقاماتِه واحتَذى حَذوَه واقتفى أثَرَه، واعتَرَف في خُطبتِه بفَضلِه، وأنَّه الذي أرشَدَه إلى سُلوكِ ذلك المَنهَجِ، وهو أحَدُ الفُضَلاءِ الفُصَحاء. وُلِدَ في همذان و"},{"id":1367,"era":"c4","t":"فِتنةٌ بين السُّنَّة والرافضة في بغداد .","s":"جَرَت فِتنةٌ بين السُّنَّة والرافضة، سَبَبُها أنَّ بعضَ الهاشميِّينَ قصد أبا عبدِ اللهِ مُحَمَّدَ بنَ النُّعمانِ المعروفَ بابنِ المُعَلِّم، كان فقيهَ الشِّيعةِ في مسجِدِه بدرب رباح، فعَرَض له بالسَّبِّ، فثار أصحابُه له، واستنفَرَ أصحاب الكَرخِ، وصاروا إلى دار القاضي أبي محمَّدٍ الأكفاني والشيخ أبي حامدٍ الإسفرايينيِّ، وجَرَت فِتنةٌ عظيمة طويلة، وأحضَرَت الشِّيعةُ مُصحَفًا ذكَروا أنَّه مُصحَفُ عبدِ"},{"id":1368,"era":"c4","t":"بعض أوامر الحاكم العبيدي الفاطمي بمصر وبعض أعماله .","s":"كان الحاكِمُ بأمرِ اللهِ العُبَيديُّ حالُه مُضطربةٌ في الجَورِ والعَدلِ، والإخافةِ والأمنِ، والنُّسُك والبِدعة, ومذهَبُه في الرَّفضِ مَعروفٌ. ولقد كان مضطرِبًا فيه، فكان يَأذَنُ في صلاةِ التَّراويحِ ثمَّ ينهي عنها، وكان يرى بعِلمِ النُّجومِ ويُؤثِرُه، ويُنقَلُ عنه أنَّه منع النِّساءَ مِن التصرُّفِ في الأسواقِ، ومنَعَ مِن أكلِ الملوخيَّا. ورُفِعَ إليه أنَّ جماعةً مِن الرَّوافِضِ تعرَّضوا لأهلِ السن"},{"id":1369,"era":"c4","t":"تدمير مدينة الزهراء بالأندلس وخلع هشام المؤيد .","s":"وثبَ مُحمَّدُ بنُ هِشامِ بنِ عبد الجبَّار بنِ عبدِ الرَّحمنِ النَّاصر على الأميرِ هِشامِ المُؤَيَّد، ثمَّ خَلَعه وتسمَّى بالمهديِّ، وكان سبَبُ الخَلعِ هو ما قام به المؤَيَّد مِن تولِّيه العهدَ لعبدِ الرَّحمنِ بنِ أبي عامر، فأمر المهديُّ بهَدمِ مدينةِ الزَّهراء مَعقِلِ بني عامر وسَلَّطَ العامَّةَ عليه فنهبوا ما فيه مِن الأموالِ والأمتعةِ، كما نَهَبوا دُورَ زُعَماء البربر بالرصافة، كما قام المهديُّ "},{"id":1370,"era":"c4","t":"سقوط الدَّولة العامرية بالأندلس .","s":"تحكَّمَ عبدُ المَلِك ابنُ أبي عامرٍ المُلَقَّبُ بالمُظَفَّر بأمرِ الأندلُسِ بعد أخيه المنصورِ، ثمَّ توفِّيَ المُظَفَّر وتولى أخوه عبدُ الرَّحمنِ المُلَقَّب بشنشول، الذي قام بإخراجِ هِشام المؤيَّد أميرِ الأندلس مِن مُعتَقَلِه, وأعاده إلى قَصرِه الزَّهراءِ، فتقَرَّبَ له حتى ولاه المؤيَّدُ ولايةَ العَهدِ بَعدَه، ولَقَّبه بالنَّاصِرِ المأمون، ثم سار عبدُ الرحمن للغزو. وخلالَ ذلك خُلِعَ هِشامٌ المُؤَيّ"},{"id":1371,"era":"c4","t":"يمين الدَّولة الغزنوي يغزو الهند في وقعة نارين .","s":"تجهَّزَ يمينُ الدَّولةِ إلى الهندِ عازمًا على غَزوِها، فسار إليها واختَرَقها واستباحَها ونكَّسَ أصنامَها. فلمَّا رأى مَلِكُ الهِندِ أنَّه لا قُوَّةَ له به، راسَلَه في الصُّلحِ والهُدنةِ على مالٍ يؤدِّيه، وخمسينَ فيلًا، وأن يكونَ له في خِدمتِه ألفَا فارسٍ لا يزالون، فقَبَضَ منه ما بذَلَه، وعاد عنه إلى غزنةَ زهب مدينة من مدن قيرغيزستان ومركز مُقاطعة نارين أوبلاستي ."},{"id":1372,"era":"c4","t":"ذكر ما أخذه الحاكم العبيدي من بيت جعفر الصادق .","s":"أنفَذَ الحاكِمُ العُبيديُّ الفاطميُّ إلى دارِ جَعفرِ بنِ مُحمَّدٍ الصادِقِ بالمدينةِ، فأخذ منها مُصحفًا وآلاتٍ كانت بها، وكان مع المُصحَفِ خَشَبٌ مُطَوَّقٌ بحديد وخيزران، وحَربةٌ وسريرٌ، حَمَلَ ذلك كُلَّه جماعةٌ مِن العَلَويِّينَ إلى الدِّيار المصرية، فأطلق لهم الحاكِمُ أنعامًا كثيرةً ونَفَقاتٍ زائدةً، وردَّ السَّريرَ وأخذ الباقيَ، وقال: أنا أحَقُّ به."},{"id":1373,"era":"c4","t":"استخفاف الحاكم العبيدي الفاطمي بالمسلمين ودمائهم في مصر .","s":"لَمَّا شاع صنيعُ الحاكِمِ في الأمورِ التي خرَقَ العاداتِ فيها، ودُعِيَ عليه في أعقابِ الصَّلواتِ وظُوهِرَ بذلك، أشفَقَ وخاف، وأمَرَ بعمارةِ دارِ العِلمِ وفَرَشَها، ونقل إليها الكُتُبَ العظيمةَ، وأسكَنَها مِن شُيوخِ السُّنَّة شَيخينِ، يُعرَفُ أحدُهما بأبي بكرٍ الأنطاكيِّ، وخلَعَ عليهما وقَرَّبَهما ورَسَم لهما بحضورِ مَجلِسِه ومُلازمتِه، وجمع الفُقَهاءَ والمُحَدِّثينَ إليها، وأمَرَ أن يُقرأَ بها فضا"},{"id":1374,"era":"c4","t":"عودة هشام المؤيد إلى حكم الأندلس وقتاله مع سليمان بن الحكم .","s":"استمَرَّ محمَّدُ بنُ هشامِ بنِ عبدِ الجبَّار بن عبد الرحمن النَّاصر المهدي في خِلافةِ الأندلُسِ، إلى أن خرجَ عليه سُلَيمانُ بنُ الحَكَم بنِ سليمان بن عبد الرحمن النَّاصر، فهرب المهديُّ مُحمَّدُ بنُ هشام، واستولى سُلَيمانُ على الخلافة في أوائِلِ شوَّال سنة 400هـ، ثم جمع المهديُّ مُحمَّدُ بنُ هشامٍ جمعًا وقصَدَ سُلَيمانَ بقُرطُبةَ، فهَرَب سُلَيمانُ وعاد المهديُّ إلى الخلافةِ في منتصف شوال، ثم اجتمَع"},{"id":1375,"era":"c5","t":"غزوة يمين الدَّولة الغزنوي بلاد الغور .","s":"كانت بلادُ الغورِ تُجاوِرُ غزنةَ، وكان الغور يقطعونَ الطَّريقَ، ويُخيفونَ السَّبيلَ، وبلادُهم جِبالٌ وَعرةٌ، ومضايقُ غَلقةٌ، وكانوا يحتَمون بها، ويعتَصِمون بصعوبةِ مَسلَكِها، فلمَّا كَثُرَ ذلك منهم أنِفَ يمينُ الدَّولة محمودُ بنُ سبكتكين أن يكونَ مثل أولئك المُفسدينَ جِيرانَه، وهم على هذه الحالِ مِن الفَسادِ والكُفرِ، فجمَعَ العساكِرَ وسار إليهم، وعلى مُقَدِّمتِه التونتاش الحاجِبُ، صاحِبُ هراة، وأ"},{"id":1376,"era":"c5","t":"وباءٌ عظيم وشدة غلاء في خراسان .","s":"اشتَدَّ الغَلاءُ بخراسانَ جَميعِها، وعَدَمُ القُوتِ، حتى أكلَ النَّاسُ بعضُهم بعضًا، فكان الإنسانُ يصيحُ: الخبزَ الخبزَ! ويموت، ثم تَبِعَه وباءٌ عظيم حتى عَجَزَ النَّاسُ عن دَفنِ الموتى."},{"id":1377,"era":"c5","t":"وفاة أبي عبيد الهروي .","s":"هو العلَّامةُ أبو عُبَيدٍ أحمَدُ بنُ محمَّد بن أبي عُبَيد العَبديُّ الهَرويُّ الشافعيُّ اللُّغويُّ المؤدِّبُ، صاحِبُ \"الغَريبَينِ\" اللُّغويُّ البارِعُ، كان مِن أعلَمِ النَّاسِ في الأدَبِ واللُّغة. وكتابه \"الغريبينِ في مَعرفةِ القُرآنِ والحديث\" يدلُّ على اطِّلاعِه وتبحَرُّه في هذا الشأنِ، وكان من تلامذةِ أبي منصورٍ الأزهريِّ. قال ابن خَلِّكانَ: \" سار كتابُه في الآفاقِ، وهو من الكتُبِ النافعةِ, وقيل"},{"id":1378,"era":"c5","t":"الخليفة العباسي القادر بالله يطعن في نسب العبيديين الفاطميين .","s":"كُتِبَ ببغدادَ مَحضَرٌ يتضَمَّنُ الطَّعنَ والقَدحَ في نَسَبِ الفاطميِّينَ، وهم ملوكُ مِصرَ فليسُوا كذلك، وإنَّما نسَبُهم إلى عُبيدِ بنِ سَعدٍ الجَرميِّ، وكَتَب في ذلك جماعةٌ من العُلَماءِ والقُضاة والأشراف والعُدول، والصالحين والفُقهاء، والمحَدِّثين، وشَهِدوا جميعًا أنَّ الحاكِمَ بمِصرَ: منصورُ بنُ نِزارِ الملَقَّب بالحاكم- حَكَمَ اللهُ عليه بالبَوارِ والخِزيِ والدَّمارِ- بن مَعد بنِ إسماعيلَ بنِ "},{"id":1379,"era":"c5","t":"وزيرُ بهاء الدَّولة البُويهيّ يأذن للرافضة بإظهار بدعهم في عاشوراء .","s":"في هذه السَّنةِ أَذِنَ فَخرُ الملك وزيرُ بهاء الدَّولة البُويهيِّ للرَّوافِضِ أن يَعمَلوا بِدعَتَهم الشَّنعاءَ، والفضيحةَ الصَّلعاءَ، من الانتحابِ والنَّوحِ والبُكاءِ، وتعليقِ المُسوح، وأن تُغلَقَ الأسواقُ مِن الصَّباحِ إلى المَساء، وأن تدورَ النِّساءُ حاسراتٍ عن وُجوهِهنَّ ورُؤوسِهنَّ، يَلطِمنَ خُدودَهنَّ، كفِعلِ الجاهليَّةِ الجهلاءِ، على الحُسَينِ بنِ عليٍّ رَضِيَ الله عنه."},{"id":1380,"era":"c5","t":"غزو يمين الدَّولة الغزنوي قصدار في بلاد السند .","s":"كان مَلِكُ قصدار قد صالحَ يَمينَ الدَّولةِ محمودَ سبكتكين على مالٍ يُؤدِّيه إليه، ثمَّ قطَعَه اغتِرارًا بحَصانةِ بَلَدِه، وكَثرةِ المضايِقِ في الطريقِ، واحتمى بايلك الخان، وكان يمينُ الدَّولة يريدُ قَصْدَها، فيتَّقي ناحيةَ إيلك الخان، فلمَّا فَسَدَ ذاتُ بينهما صَمَّمَ العزمَ وقَصَدَها وتجَهَّزَ، وأظهَرَ أنَّه يريدُ هَراةَ، فسار مِن غزنةَ في جمادى الأولى، فلمَّا استَقَلَّ على الطريقِ، سار نحو قصدار"},{"id":1381,"era":"c5","t":"سقوط دولة بني زياد وقيام إمارة بني نجاح في اليمن .","s":"تأسَّست إمارةُ بَني نجاح على أنقاضِ دولةِ بَني زيادٍ، أسَّسَها الأميرُ نجاحٌ، مَولى مُرجانَ الحَبشيِّ، حاجِبِ أميرِ بَني زيادٍ بعدَ انتهاءِ دولةِ بَني زيادٍ، فقَضى على مَولاه مُرجانَ وعلى مُنافِسِه نَفيسٍ، اللَّذيْنِ قتَلَا الأميرَ عبدَ اللهِ بنَ أبي الجيشِ آلَ زيادٍ. فأعلنَ نَفْسَه سُلطانًا على تِهامةَ، وضَبطَ الأميرُ نجاحٌ تِهامةَ ضَبطًا تامًّا، أمَّا الجبالُ التي كانت خاضِعةً لِأسلافِه فإنَّها "},{"id":1382,"era":"c5","t":"وفاة إيلك خان ملك الترك .","s":"هو إيلك الخان عليُّ بنُ نصر أحدُ مُلوكِ الكرخانيين _ إيلك الخان: لَقَبُ ملوك الكرخانيِّين التركي- وكان أيلك خان خيِّرًا عادلًا محبًّا للدِّينِ وأهله. دخَلَت قبائِلُ الكرخانيِّينَ في الإسلامِ في نهاية القَرنِ الرَّابعِ، وقد تمكَّنَ إيلك الخان أن يأخُذَ بُخارى وسمرقند من السَّامانيِّين، ثمَّ حاول أن يتوسَّعَ في خُراسان، لكِنَّ السُّلطانَ محمودَ الغزنوي هَزَمَه في أكثَرَ مِن موقعة. توفِّيَ إيلك الخان"},{"id":1383,"era":"c5","t":"الخلاف بين أبناء البيت الأمويين بالأندلس  .","s":"اجتمع البربَرُ فقَدَّموا على أنفُسِهم سُلَيمانَ بنَ الحَكَمِ بنِ سُلَيمانَ بنِ عبد الرحمن الناصرِ، فنهض بالبربَرِ إلى الثَّغرِ واستجاش بالنَّصارى وأتى بهم إلى بابِ قُرطبةَ فبرَزَ إليه جماعةُ أهلِ قُرطبةَ، فلم تكُنْ إلَّا ساعةٌ حتى قُتِلَ مِن أهلِ قُرطبةَ نَيِّفٌ وعشرونَ ألفَ رجُلٍ في جبَلٍ هنالك يُعرَفُ بجبلِ قنطش، وهي الوقعةُ المشهورة، ذهب فيها من الخِيارِ والفُقَهاءِ وأئمَّةِ المساجِدِ والمؤذِّن"},{"id":1384,"era":"c5","t":"قيام الدَّولة الأسدية غرب بغداد .","s":"خلع سُلطانُ الدَّولةِ على أبي الحَسَنِ عليِّ بن مزيد الأسديِّ، وهو أوَّلُ مَن تقَدَّم من أهلِ بَيتِه؛ حيث أسنَدَ له إمارةَ الحلَّة، فكانت هذه بدايةَ دولتِهم التي استمَرَّت إلى عام 545هـ"},{"id":1385,"era":"c5","t":"وفاة أبي القاسم الزهراوي الطبيب  .","s":"هو خَلَفُ بنُ عَبَّاس الزهراوي الأندلُسيُّ، طبيبٌ وعالمٌ وخبيرٌ بالأدويةِ المُفرَدة والمُرَكَّبة، وكان طبيبَ البَلاطِ في عهدِ الحُكمِ الثَّاني الأُمويِّ، كان مِن أهلِ الفَضلِ والدِّينِ والعِلمِ، وعِلمُه الذي سبَقَ عِلمَ الطِّبِّ, وله تصانيفُ مَشهورةٌ في صناعة الطب، أفضَلُها كتابُه الكبيرُ المعروف \"بالزهراوي\" وله كتابٌ كبيرٌ مَشهورٌ كبيرُ الفائدة، سمَّاه كتاب \"التَّصريف لِمَن عجَزَ عن التَّأليف\" في"},{"id":1386,"era":"c5","t":"وفاة بهاء الدَّولة بن بويه الشيعي وقيام ولده سلطان الدَّولة بعده .","s":"هو بهاءُ الدَّولةِ أبو نَصرِ بنُ عَضدِ الدَّولة بنِ بُوَيه الديلميُّ الشيعيُّ، وهو المتحَكِّمُ حينئذٍ بالعراقِ، خلع بهاءُ الدَّولةِ الخليفةَ الطائِعَ للهِ، ونصَبَ القادرَ باللهِ مَكانَه. بينما كان هو خاضِعًا للسُّلطانِ محمودِ بنِ سبكتكين، مُداريًا له، مُؤثِرًا لمُصافاتِه بحُكمِ الجِوارِ. كان مرَضُه الذي مات فيه تتابع الصَّرَع مثل مرَضِ أبيه، وكان موتُه بأرجان، وحُمِلَ إلى مشهد أميرِ المؤمنين عليٍّ"},{"id":1387,"era":"c5","t":"الفتنة بين المسلمين والنصارى ببغداد .","s":"تُوفِّيَت زوجةُ بَعضِ رُؤَساءِ النصارى، فخَرَجَت النوائِحُ والصُّلبانُ معها جِهارًا، فأنكَرَ ذلك بعضُ الهاشميِّينَ، فضَرَبه بعضُ غِلمانِ ذلك الرَّئيسِ النصرانيِّ بدبوسٍ في رأسِه فشَجَّه، فثار المسلمونَ بهم فانهزموا حتى لجؤوا إلى كنيسةٍ لهم هناك، فدخَلَت العامَّةُ إليها فنَهَبوا ما فيها، وما قَرُب منها مِن دورِ النَّصارى، وتتَبَّعوا النصارى في البَلَدِ، وقصَدوا النَّاصِحَ وابن أبي إسرائيلَ فقاتَلَه"},{"id":1388,"era":"c5","t":"يَمينُ الدَّولةِ الغزنوي يغزو الهند ويفتح نادرين .","s":"سار يَمينُ الدَّولةِ الغزنوي عندما خرج الشِّتاءُ غازيًا إلى الهندِ في جمعٍ عَظيمٍ وحَشدٍ كثيرٍ، وقصَدَ واسِطةَ البلادِ مِن الهند، فسار شَهرينِ، حتى قارَبَ مَقصِدَه، ورتَّب أصحابَه وعساكِرَه، فسَمِعَ عَظيمُ الهند به، فجَمَع مَن عِندَه مِن قُوَّادِه وأصحابِه، وبرز إلى جَبَلٍ هناك، صَعبِ المرتقى، ضَيِّقِ المسلَكِ، فاحتمى به، وكتَبَ إلى الهنودِ يستدعيهم مِن كُلِّ ناحية، فاجتمع عليه منهم كلُّ مَن يحمِل"},{"id":1389,"era":"c5","t":"الحاكم العبيدي الفاطمي يأمر بحظر التجول على النساء .","s":"منَعَ الحاكِمُ صاحِبُ مِصرَ النِّساءَ مِن الخروجِ مِن منازلهم، أو أن يَطَّلِعنَ مِن الأسطِحةِ أو الطَّاقاتِ، ومنَعَ الخَفَّافينَ مِن عَمَلِ الخِفافِ لهن، ومنَعَهنَّ مِن الخروجِ إلى الحَمَّامات، وقتَلَ خَلقًا مِن النساءِ على مخالفتِه في ذلك، وهدَمَ بَعضَ الحَمَّامات عليهنَّ، وجَهَّزَ نساءً عَجائِزَ كثيرةً يَستَعلِمنَ أحوالَ النِّساءِ لِمَن يَعشَقْنَ أو يَعشَقُهنَّ، بأسمائِهنَّ وأسماءِ مَن يتعَرَّضُ"},{"id":1390,"era":"c5","t":"غزو تانشير بالهند .","s":"ذُكِرَ ليَمينِ الدَّولة الغزنويِّ أنَّ بناحيةِ تانشير فِيَلةً مِن جنسِ فِيَلةِ الصيلمان الموصوفةِ في الحربِ، وأنَّ صاحِبَها غالٍ في الكُفرِ والطُّغيان، والعِنادِ للمُسلِمينَ، فعَزَم على غَزوِه في عُقرِ دارِه، فسار في الجنودِ والعساكِرِ والمتطَوِّعة، فلَقِيَ في طريقِه أوديةً بعيدةَ القَعرِ، وَعْرةَ المسالِك، وقِفارًا فسيحةَ الأقطارِ والأطراف، بعيدةَ الأكنافِ، والماءُ بها قليلٌ، فلَقُوا شِدَّةً، وقا"},{"id":1391,"era":"c5","t":"قيام دولة بني حماد بالمغرب الأوسط .","s":"في سنة 387ه عقَدَ باديسُ بنُ منصورِ بنِ بلكينَ صاحِبُ إفريقيَّةَ الوِلايةَ لِعَمِّه حمَّادِ بنِ بلكين على أشيرَ، فاتَّسَعَت ولايةُ حمَّاد وعَظُم وجمَعَ العساكرَ والأموال. وفي سنة 405ه أظهر حمَّادٌ الخلافَ على ابنِ أخيه باديس وخلَعَه واقتتلا في أوَّلِ جمُادى سنة 406ه، فانهزم حَمَّادٌ هزيمةً شَنيعةً بعد قتالٍ شديدٍ بين الفريقين والتجأ إلى قلعة مغلية، ثمَّ نَهَب دكمة ونقَلَ منها الزَّادَ إلى مغيلة وت"},{"id":1392,"era":"c5","t":"الحاكم العبيدي الفاطمي يغير أربعة وزراء في عام واحد ويقتل ثلاثة منهم .","s":"رَكِبَ الحاكِمُ ومعه وزيرُه الحُسَينُ بنُ طاهر الوزَّان، على رَسمِه، فلمَّا انتهى إلى حارةِ كتامة خارِجَ بابِ القاهرة، أمَرَ بقَتلِه فضُرِبَت رقَبَتُه ودُفِنَ مكانَه. فكانت مُدَّةُ نظره في الوزارة سنتين وشهرين وعشرين يومًا، ثمَّ استوزَرَ مكانَه عبدَ الرَّحمنِ بنَ أبي السيد الذي لم يلبَثْ إلَّا قليلًا حتى قتَلَه الحاكِمُ فاستوزر مكانَه أبا العبَّاسِ الفَضلَ بنَ جَعفرِ بنِ الفراتِ، ثمَّ قَتَلَه الحا"},{"id":1393,"era":"c5","t":"قيام حرب بين علي بن مزيد الأسدي وبين بني دبيس .","s":"كان بنو دبيس قد قَتَلوا أبا الغنائِمِ بنَ مزيدٍ أخا أبي الحَسَنِ في حربٍ بينهم وحالت الأيَّامُ بينه وبين الأخذِ بثَأرِه، ثم تجهَّزَ لِقَصدِهم بعد ذلك، وجمَعَ العَرَبَ، والشَّاذنجان، والجوانيَّة، وغيرَهما من الأكرادِ، وسار إليهم، فلمَّا قَرُبَ منهم خرَجَت زوجتُه ابنةُ دبيس وقَصدت أخاها مُضَرَ بنَ دبيس ليلًا، وقالت له: قد أتاكم ابنُ مزيد فيما لا قِبَلَ لكم به، وهو يَقنَعُ منكم بإبعادِ نبهان قاتِلِ أ"},{"id":1394,"era":"c5","t":"وفاة الحاكم النيسابوري صاحب المستدرك .","s":"هو الإمامُ الحافِظُ، الناقِدُ العَلَّامة، شيخُ المُحَدِّثين، أبو عبدِ اللهِ مُحمَّدُ بنُ عبدِ الله بن محمَّد بن حمدويه بنِ نعيم بن الحكم، بن البيع الحاكم الضَّبِّي الطهماني النيسابوري، ويُعرَفُ بابن البيع، مِن أهل نيسابور. ولِدَ في يوم الاثنين, ثالثَ شهر ربيع الأول، سنة 321ه بنيسابور. قال الذهبي: \"طلب الحديثَ في صِغَرِه بعنايةِ والِدِه وخالِه، وأوَّلُ سَماِعِه كان في سنةِ ثلاثين، في التاسعة مِن عُ"},{"id":1395,"era":"c5","t":"محمود بن سبكتكين يغزو الهند .","s":"غزا محمودُ بنُ سبكتكين الهندَ على عادتِه، فَضَلَّ أدلَّاؤُه الطريقَ، ووقع هو وعسكَرُه في مياهٍ فاضَت من البَحرِ، فغَرِقَ كثيرٌ ممَّن معه، وخاض الماءَ بنَفسِه أيامًا حتى تخلَّصَ وعاد إلى خُراسان."},{"id":1396,"era":"c5","t":"وباء وكوارث بالعراق ومصر  .","s":"أصاب البصرةَ بالعِراقِ وَباءٌ عَظيمٌ وطاعونٌ أعجَزَ الحفَّارينَ عن الدَّفنِ، وفيها زاد ماءُ النيلِ بمِصرَ وأغرق الضِّياعَ، وغَلَت الأسعارُ، وهَلَكت البساتينُ، وامتلأ كُلُّ مكانٍ مِن المدينة، وغَرِقَ المقياسُ وانتهت الزِّيادةُ إلى ثلاثِ أصابعَ من إحدى وعشرين ذراعًا، وبلغ الماءُ إلى نصفِ النَّخلِ مِمَّا يلي بركةَ الحَبش."},{"id":1397,"era":"c5","t":"فتنةٌ ببغدادَ بينَ أهل الكَرخِ وبين أهلِ بابِ الشَّعير .","s":"وقَعَت فتنةٌ ببغدادَ بينَ أهل الكَرخِ وبين أهلِ بابِ الشَّعير، فأنكَرَ فَخرُ الملك على أهلِ الكرخ، ومنَعَهم من النَّوحِ يوم عاشوراء، ومِن تعليقِ المُسوحِ؛ مخافةَ زيادةِ الِفتنةِ."},{"id":1398,"era":"c5","t":"وفاة الشريف الرضي .","s":"هو نقيبُ العَلَويِّينَ، أبو الحسَنِ محمَّدُ بنُ الحُسَينِ بنِ موسى بنِ مُحمَّد بنِ إبراهيم بن موسى الكاظمِ الحُسيني المُوسَوي البغدادي الشِّيعي، الشاعِرُ المُفلِق، الذي يقالُ: إنَّه أشعَرُ قُرَيشٍ، قال ابنُ خَلِّكانَ: \"هو أشعَرُ الطالبيِّينَ مَن مضى منهم ومَن غَبَر، على كثرةِ شُعَرائِهم المُفلِقينَ، ولو قُلتُ: إنَّه أشعَرُ قُرَيشٍ لم أُبعِدْ عن الصِّدقِ\". وُلِدَ ببغداد سنة 359ه، وتعلَّمَ فيها وبرَ"},{"id":1399,"era":"c5","t":"وفاة باديس الصنهاجي وولاية ابنه المعز .","s":"هو أبو مناد باديسُ بنُ مَنصورِ بنِ يُوسُفَ بلكين بن زيري بنِ مناد الحِمْيريُّ الصنهاجيُّ أمير إفريقيَّة نيابةً عن الحاكِمِ العُبيديِّ المُدَّعي الخلافةَ بمِصرَ، ولَقَّبَه الحاكِمُ نصيرَ الدَّولةِ، وُلِدَ بآشير سنة 374, وكانت ولايتُه بعد أبيه المنصور، سنة386، وكان باديس مَلِكًا كبيرًا، حازمَ الرأي، شديدَ البأس، إذا هَزَّ رُمحًا كَسَرَه. ‏ ووَلِيَ بعده إمرةَ إفريقيَّةَ ابنُه المعِزُّ بنُ باديس وعُمُ"},{"id":1400,"era":"c5","t":"تفرق المسلمين في الأندلس وظهور دول ملوك الطوائف .","s":"اقتَسَم أصحابُ الأطرافِ والرُّؤَساءُ حُكمَ بلادِ الأندلُسِ، وصاروا طوائِفَ مُتناحِرةً، فقُرطبةُ استولى عليها أبو الحَسَنِ بنُ جهور، وكان مِن وزراء الدَّولة العامريَّة، وبقِيَ كذلك إلى أن مات سنةَ خمسٍ وثلاثين وأربعِمِئَة، وقام بأمِرِ قُرطبةَ بَعدَه ابنُه أبو الوليد مُحمَّدُ بنُ جهور، وأمَّا إشبيليَّةُ فاستولى عليها قاضيها أبو القاسمِ مُحمَّدُ بنُ إسماعيلَ بنِ عَبَّاد اللخمي. لَمَّا انقَسَمَت مملكة"},{"id":1401,"era":"c5","t":"قتل الشيعة أتباع العبيديين بإفْريقيَّة أيام المعز بن باديس .","s":"كان المعِزُّ بنُ باديس الصِّنهاجيُّ ناصِرًا للسُّنَّةِ وقامِعًا لبدعةِ الرَّفضِ الإسماعيليَّة العُبَيديَّة بإفْريقيَّةَ، وفي هذه السَّنَةِ قَتَل الرَّافِضةَ الإسماعيليَّةَ أتباعَ العُبَيديِّينَ في بلاد إفْريقيَّةَ، وبدايتُه أنَّ المُعِزَّ بنَ باديس رَكِبَ في عاشوراء ومشى في القيروانِ والنَّاسُ يُسَلِّمونَ عليه ويَدعُونَ له، فاجتاز بجَماعةٍ، فسأل عنهم، فقيل: هؤلاء رافِضةٌ يسُبُّونَ أبا بكرٍ وعُمَرَ"},{"id":1402,"era":"c5","t":"احتراق جامع سامرا واجتماع عدة أمور مثلها في هذا العام .","s":"احتَرَق مسجِدُ سامِرَّا المشهورُ بمِئذنتِه المُلتَوية، كما احتَرَق مَشهَدُ الحُسَينِ بنِ علي بكَربَلاءَ وأروقتُه، وكان سبَبُ ذلك أنَّ القومةَ أشعلوا شمعتينِ كَبيرتينِ، فمالتا في اللَّيلِ على التأزيرِ- الخشَبِ المُحيطِ بالشَّمعَتَينِ- ونَفِذَت النَّارُ منه إلى غيرِه حتى كان ما كان، ثمَّ بعد ذلك احتَرَقَت دارُ القطن ببغدادَ وأماكِنُ كثيرةٌ بباب البصرة، وفيها ورَدَ الخبَرُ بتشعيثِ الُّركنِ اليَمانيِّ"},{"id":1403,"era":"c5","t":"فتح يمين الدَّولة الغزنوي كشمير ودخول أهلها في الإسلام  .","s":"غزا يَمينُ الدَّولةِ بلادَ الهندِ، بعد فراغِه مِن خوارزم، فسار منها إلى غزنةَ، ومنها إلى الهندِ عازمًا على غَزوِ قَشمير (كشمير)؛ إذ كان قد استولى على بلادِ الهِندِ ما بينَه وبين قشمير، فلما بلغ دَربَ قَشميرَ أتاه صاحِبُها وأسلَمَ على يَدِه، وسار بينَ يديه إلى مَقصِدِه، فبلغ ماءَ جون في العشرينَ مِن رَجَب، وفتَحَ ما حولَها مِن الوِلاياتِ الفَسيحةِ والحُصونِ المَنيعةِ، حتى بلغ حِصنَ هودب، وهو آخِرُ "},{"id":1404,"era":"c5","t":"محمود بن سبكتكين يسيطر على خوارزم .","s":"قام أُمراءُ خوارزمَ بقَتلِ حاكِمِهم أبي العَبَّاسِ خوارزمشاه لَمَّا رأَوْا مِن مُوافَقَتِه ليَمينِ الدَّولةِ ودُعائِه له على المنابِرِ، فقَتَلوه غِيلةً وأجلَسوا مكانَه أحدَ أولادِه، وتعاهَدوا على مُقاتَلةِ يَمينِ الدَّولة ومُقارَعتِه، واتَّصَل الخبَرُ بيمينِ الدَّولة، فجمَعَ العساكِرَ وسار نحوَهم، فلمَّا قارَبَهم جَمَعَهم صاحِبُ جَيشِهم، ويُعرَفُ بالبتكين البخاري، وأمَرَهم بالخُروجِ إلى لِقاءِ مُق"},{"id":1405,"era":"c5","t":"فِتنةٌ كَبيرةٌ بينَ السُّنَّةِ والشِّيعةِ بمدينة واسِط .","s":"كانت فِتنةٌ كَبيرةٌ بينَ السُّنَّةِ والشِّيعةِ بواسِط، فانتصَرَ السُّنَّةُ وهَرَبَ وُجوهُ الشِّيعةِ والعَلَويِّينَ إلى عليِّ بنِ مزيد أميرِ جَزيرةِ الأسديَّةِ مِن قِبَلِ فخر الدَّولةِ البُويهيِّ، فاستَنصَروه."},{"id":1406,"era":"c5","t":"ابتداء الدَّولة الحمودية (العلويين) بالأندلس .","s":"وَلِيَ الأندلُسَ عليُّ بنُ حَمُّود بنِ أبي العَيشِ بنِ ميمون بنِ أحمَدَ بنِ عليِّ بنِ عبد اللهِ بنِ عُمَرَ بنِ إدريس بن إدريسَ بن عبد الله بن الحسن بن الحسن بن علي بن أبي طالب، وقيل في نَسَبِه غيرُ ذلك، مع اتِّفاقٍ على صِحَّةِ نَسَبِه إلى أميرِ المؤمنينَ عليِّ بنِ أبي طالبٍ رَضِيَ الله عنه، وكان سَبَبُ تَوَلِّيه أنَّ الفتى خيرانَ العامريَّ لم يكُنْ راضيًا بولايةِ سُلَيمانَ بنِ الحاكِمِ الأُمويِّ؛ "},{"id":1407,"era":"c5","t":"وفاة الوزير فخر الملك .","s":"هو الوَزيرُ الكَبيرُ، أبو غالبٍ مُحمَّدُ بنُ عليِّ بنِ خَلَفِ بنِ الصيرفيِّ الشِّيعيِّ، المُلَقَّبُ فَخر الملك، وزيرُ بهاءِ الدَّولة أبي نصرِ بنِ عضُدِ الدَّولة بن بُوَيه، وبعد وفاتِه وَزَرَ لِوَلَدِه سُلطانِ الدَّولةِ أبي شُجاعٍ فناخِسرو. أصلُه مِن واسِط، وكان أبوه صيرفيًّا، وباسمِه صَنَّفَ كتاب \"الفخري\" في الجبرِ والمُقابلة. كان صدرًا مُعظَّمًا، جوادًا مُمَدَّحًا، مِن رجالِ الدَّهرِ، وكان مِن صِ"},{"id":1408,"era":"c5","t":"ذكر خروج الترك من الصين وموت طغان خان .","s":"خرَجَ التُّركُ- وهم وثنيُّونَ- مِن الصِّينِ، وكان سبَبُ خُروجِهم أنَّ طغان خان مَلِكَ تُركستان التُّركي كان مُسلِمًا فاضِلًا يُحِبُّ أهلَ العِلمِ والدِّينِ. لَمَّا مَرِضَ مرضًا شديدًا، وطال به المَرَضُ، طَمِعوا في البلادِ لذلك، فساروا إليها ومَلَكوا بعضَها وغَنِموا وسَبَوا، وبَقِيَ بينهم وبين بلاساغون ثمانيةُ أيام، فلمَّا بلَغَه الخبَرُ كان بها مريضًا، فسألَ اللهَ تعالى أن يُعافِيَه لِينتَقِمَ مِن"},{"id":1409,"era":"c5","t":"الخليفة العباسي القادر بالله يستتيب فقهاء المعتزلة .","s":"استتابَ القادِرُ باللهِ الخَليفةُ فُقَهاءَ المُعتَزِلةِ، فأظهروا الرُّجوعَ وتبَرَّؤوا من الاعتزالِ والرَّفضِ والمقالاتِ المُخالِفةِ للإسلام، وأُخِذَت خطوطُهم بذلك، وأنَّهم متى خالفوا أحلَّ فيهم مِن النَّكالِ والعُقوبةِ ما يَتَّعِظُ به أمثالُهم. قال ابن كثير: \"وامتَثَل محمودُ بنُ سبكتكين أمْرَ أميرِ المؤمنينَ في ذلك، واستَنَّ بسُنَّتِه في أعمالِه التي استخلَفَه عليها مِن بلادِ خُراسان وغيرها، في قَ"},{"id":1410,"era":"c5","t":"ظهور المذهب الدرزي ودعوى ألوهية الحاكم .","s":"قَدِمَ إلى مصرَ داعٍ عَجميٌّ اسمُه مُحَمَّدُ بنُ إسماعيلَ الدرزيُّ المعروفُ بأبي عبدِ اللهِ أنوشتكين النجري الدرزيِّ، وهو أوَّلُ رَجُلٍ تكَلَّمَ بدَعوى ألوهيَّةِ الحاكِمِ، وأمَرَ برَفعِ ما جاء به الشَّرعُ، وسيَّرَ مذهبَه إلى بلادِ الشَّامِ والسَّاحلِ، ولهم مذهَبٌ في كتمانِ السِّرِّ لا يُطلِعونَ عليه مَن ليس منهم, وكان الدرزيُّ يُبيحُ البَناتِ والأمَّهاتِ والأخواتِ, واتَّصَل بالحاكِمِ فأنعَمَ عليه،"},{"id":1411,"era":"c5","t":"قيام دولة عمران بن شاهين بالبطيحة في العراق ثم سقوطها .","s":"كان أوَّلَ مَن مَلَك البطيحةَ أو البطائح- تقَعُ بين واسِطَ والبصرةِ- عِمرانُ بنُ شاهينَ، أصلُه من الجامدة (من أعمالِ واسط) مجهولُ النَّسَبِ، سواديُّ المنشأِ، ينتَسِبُ إلى بني سُلَيم, كان عليه دِماءٌ فهَرَب إلى البطيحة, واحتمى بالآجامِ, يتصَيَّدُ السَّمَك والطَّيرَ, فرافقه صيَّادون, ثمَّ التَفَّ عليه لصوصٌ, ثمَّ استفحَلَ أمرُه, وكَثُرَ جَمعُه, فأنشأ معاقِلَ وتمَكَّنَ مِن البطيحة, فحارَبَه مُعِزُّ ا"},{"id":1412,"era":"c5","t":"الخليفة العباسي القادر بالله يقرر كفر من قال بخلق القرآن .","s":"أصدَرَ الخَليفةُ العباسيُّ القادِرُ باللهِ كِتابًا في مذهَبِ أهلِ السُّنَّةِ والجماعةِ في القُرآنِ الكريمِ، قُرِئَ بدارِ الخِلافةِ في الموكِبِ, وفيه: أنَّ مَن قال: القُرآنُ مَخلوقٌ، فهو كافِرٌ حلالُ الدَّمِ."},{"id":1413,"era":"c5","t":"غزو محمود بن سبكتكين بلاد الهند .","s":"سار يمينُ الدَّولةِ إلى الهندِ غازيًا، واحتَشَد وجَمَع، واستَعَدَّ وأعَدَّ، وسبَبُ هذا أنَّ بيدا أكبَرَ مُلوكِ الهند قَوِيَ أمْرُه واستمال إليه كُلَّ مَن كان يمينُ الدَّولةِ قد هَزَمَهم ووعَدَهم بإعادةِ مُلكِهم لهم، فتجَهَّزَ يمينُ الدَّولة للغَزوِ، وقصَدَ بيدا، وابتدأ في طريقِه بالأفغانيَّةِ، وهم كُفَّارٌ، فغَنِمَ المُسلِمونَ مِن أموالِهم الكثيرُ، ثمَّ واصَلَ المَسيرَ، وبلَغَ إلى مكانٍ لم يَبلُغْ"},{"id":1414,"era":"c5","t":"مجاعة وغَلاء شديد بمِصرَ .","s":"اشتَدَّ الغَلاءُ بديارِ مِصرَ حتى بِيعَ الدَّقيقُ رِطلًا بدِرهمٍ، واللَّحمُ أربعَ أواقٍ بدِرهَمٍ، ومات كثيرٌ مِن النَّاسِ بالجوعِ، وبلَغَت عِدَّةُ مَن مات في مُدَّةِ رَمَضانَ وشَوَّال وذي القَعدة، مِئَتي ألفٍ وسبعين ألفًا سوى الغُرَباءِ، وهم أكثَرُ مِن ذلك."},{"id":1415,"era":"c5","t":"وفاة ابن مردويه الكبير .","s":"هو الحافِظُ المُجَوِّدُ العلَّامة، مُحَدِّثُ أصبهان، أبو بكرٍ أحمَدُ بنُ موسى بن مَردَوَيهِ بنِ فَوْرَك بن موسى بن جعفر، الأصبهاني، المؤرِّخُ المُفَسِّرُ، مِن أهل أصبهان. مولِدُه سنة323. ويقالُ له ابنُ مَردَوَيهِ الكبير؛ لِيُمَيَّزَ عن حَفيدِه المحدِّثِ العالِمِ أبو بكرٍ أحمَدُ بنُ مُحمَّد بن أحمد بن مردويه. له عِدَّةُ تصانيفَ، منها: \"التفسير الكبير\"، و\"التاريخ\"، و\"الأمالي\" \"الثلاثمئة مجلس\"، و\"الم"},{"id":1416,"era":"c5","t":"ذكر الفتنة بين الأتراك والأكراد بهمذان .","s":"زاد شَغبُ الأتراكِ بهَمذانَ على صاحِبِهم شَمسِ الدَّولةِ بنِ فَخرِ الدَّولة، وكان قد تقَدَّمَ ذلك منهم غيرَ مَرَّة، وهو يحلُمُ عنهم بل يَعجِزُ، فقَوِيَ طمَعُهم، فزادوا في التوثُّبِ والشغبِ، وأرادوا إخراجَ القُوَّادِ القوهيَّة الأكرادِ مِن عنده، فلم يُجِبْهم إلى ذلك، فعَزَموا على الإيقاعِ بهم بغيرِ أمْرِه، فاعتَزَل الأكرادُ مع وزيرِه تاجِ الملك أبي نصر بنِ بهرامَ إلى قلعةِ برجين، فسار الأتراكُ إليه"},{"id":1417,"era":"c5","t":"الحاكم العبيدي يأمر بحرق القاهرة, ثم ادعائه الألوهية  .","s":"كان الحاكِمُ العُبَيديُّ صاحِبُ مِصرَ يواصِلُ الرُّكوبَ وتتصَدَّى له العامَّةُ، فيَقِفُ عليهم ويسمَعُ منهم. وكان النَّاسُ في ضنكٍ مِن العَيشِ معه. فكانوا يدسُّونَ إليه الرِّقاعَ المختومةَ بالدُّعاءِ عليه والسَّبِّ له ولأسلافِه، حتى إنَّهم عَمِلوا تمثالَ امرأةٍ مِن كاغد بخُفٍّ وإزارٍ ثمَّ نَصَبوها له، وفي يَدِها قصَّةً. فأمَرَ بأخْذِها مِن يَدِها، ففتَحَها فرأى فيها العظائمَ، فقال: انظُروا مَن هذه."},{"id":1418,"era":"c5","t":"وفاة الحاكم العبيدي الفاطمي وتولي ابنه الظاهر لإعزاز دين الله .","s":"هو صاحِبُ مِصرَ الحاكِمُ بأمر الله، أبو عليٍّ منصورُ بنُ العزيز نزار بن المعِزِّ معد بن المنصور إسماعيل بن القائم محمد بن المهدي، العُبَيديُّ الإسماعيليُّ الزِّنديقُ المُدَّعي الرُّبوبيَّة. مولِدُه سنةَ 375. أقاموه في المُلكِ بعد أبيه، وله إحدى عشرةَ سنةً. حكى هو عن نَفسِه قال: \"ضَمَّني أبي وقَبَّلَني وهو عُريان، وقال: امْضِ فالعَبْ، فأنا في عافيةٍ. قال: ثمَّ توفِّيَ، فأتاني برجوان، وأنا على جميزة"},{"id":1419,"era":"c5","t":"ذكر حماية محمود الغزنوي حجاج العراق .","s":"لَمَّا توقَّفَ الحجُّ مِن العِراقِ عِدَّةَ سَنَواتٍ مُتَتالياتٍ خَوفًا مِن الأعرابِ قُطَّاعِ الطُّرُقِ، قَصَد النَّاسُ يَمينَ الدَّولةِ محمودَ بنَ سبكتكين وقالوا له: أنت سُلطانُ الإسلامِ وأعظَمُ مُلوكِ الأرض، وفي كلِّ سَنةٍ تَفتَحُ مِن بلادِ الكُفرِ ما تُحِبُّه، والثَّوابُ في فَتحِ طَريقِ الحَجِّ أعظَمُ، وقد كان الأميرُ بَدرُ بنُ حسنويه، وما في أمرائِك إلَّا مَن هو أكبَرُ منه شأنًا، يُسَيِّرُ الحا"},{"id":1420,"era":"c5","t":"نهاية الدَّولة الزيادية في اليمن وقيام دولة بني نجاح .","s":"لَمَّا توفِّيَ أبو الحَبشِ إسحاقُ بنُ إبراهيمَ حاكِمُ دَولةِ بني زيادٍ في اليَمَنِ سَنَةَ 371، وقد طالت مُدَّةُ حُكمِه وأسَنَّ؛ خَلَفَه طِفلٌ قيلَ اسمُه زيادُ بنُ أبي الحبش، وتولت أختُه هندُ بنت أبي الحبش، وتولى معها في تصريفِ شُؤونِ الدَّولةِ رشد، وهو عبدٌ لأبي الحبَشِ، وبقي رشدٌ على ولايتِه حتى مات، فتَولَّى عبدٌ لرشدٍ اسمُه حُسَينُ بن سلامة إدارةَ الدَّولةِ، وسلامة هي أمُّ حسين، ونشأ حسينٌ حازِ"},{"id":1421,"era":"c5","t":"أهل العراق يعودون للحج بعد أن توقف سنوات خوفاً من الأعراب .","s":"حجَّ النَّاسُ مِن العراقِ بعد أن توقَّفَ الحَجُّ مِن جِهةِ العِراقِ والشَّامِ وما وراءَ النَّهرِ؛ خوفًا من الأعرابِ الذين كانوا يَقطَعونَ الحَجَّ ويَنهَبونَ ويَقتُلونَ الحُجَّاجَ؛ حيث بقِيَ الأمرُ على ذلك عِدَّةَ سَنَواتٍ تُقارِبُ العَشرَ، لا يخرُجُ وَفدُ حَجٍّ مِن هذه المناطِقِ إلَّا من مصرَ والمغربِ واليمَنِ أحيانًا."},{"id":1422,"era":"c5","t":"رجل من أتباع الباطنية يطعن الحجر الأسود ثلاث ضربات .","s":"اتَّفَق أحَدُ المِصريِّينَ مِن أصحابِ الحاكِمِ مع جماعةٍ مِن الحُجَّاجِ المصريِّينَ على أمرٍ سُوءٍ، وذلك أنَّه لَمَّا كان يومُ النَّفرِ الأوَّلِ، طاف هذا الرجُلُ بالبَيتِ، فلما انتهى إلى الحَجَرِ الأسودِ جاء ليُقَبِّلَه فضَرَبه بدبوسٍ كان معه ثلاثَ ضَرَباتٍ مُتَوالياتٍ، وقال: إلى متى نعبُدُ هذا الحجَرَ؟ ولا مُحمَّدٌ ولا عليٌّ يَمنَعُني ممَّا أفعله، فإنِّي أهدم اليومَ هذا البيتَ، وجعل يرتَعِدُ، فات"},{"id":1423,"era":"c5","t":"وفاة الشيخ المفيد ابن المعلم شيخ الإمامية الرافضة .","s":"عالمُ الرَّافِضةِ، صاحِبُ التَّصانيفِ: أبو عبدِ اللهِ مُحمَّدُ بنُ محمد بن القاضي النعمان البغدادي الكَرْخي بن محمد المغربي، المعروفُ بابنِ المعَلِّم أو الشَّيخ المُفيد شيخ الإماميَّة الرَّوافض، والمُصَنِّف لهم، والمُحامي عن حوزتِهم، صاحِب فُنونٍ وبحوثٍ وكلام، واعتزالٍ وأدبٍ. قال الذهبي: \"ذكَرَه ابن أبي طي في \"تاريخ الإماميَّة\"، فأطنب وأسهب، وقال: كان أوحَدَ في جميعِ فُنونِ العلم: الأصلينِ، والفِق"},{"id":1424,"era":"c5","t":"وفاة ابن البواب الكاتب المشهور .","s":"الكاتِبُ المَشهورُ صاحِبُ الخَطِّ المنسوبِ أبو الحَسَنِ عليُّ بنُ هلالٍ البَغداديُّ، المعروف بابنِ البَوَّاب؛ ويقال له \"ابن الستري\" أيضًا؛ لأنَّ أباه كان بوَّابًا، والبَوَّاب ملازِمٌ سِترَ البابِ، فلهذا نُسِبَ إليهما. كان شَيخُه في الكتابةِ ابنَ أسَدٍ الكاتِبَ المَشهورَ، وهو أبو عبدِ اللهِ مُحمَّدُ بنُ أسدِ بنِ عليِّ بنِ سَعيدٍ القارئ الكاتب البزَّاز البغدادي. قال ابن كثيرٍ: \"وقد أثنى على ابنِ الب"},{"id":1425,"era":"c5","t":"نهاية حكم بني حمود الطالبيين في الأندلس .","s":"كان القاسِمُ بنُ حَمُّود بقُرطبةَ تَولَّى الحُكمَ بعد أخيه عليِّ بنِ حَمُّود, ثمَّ قام عليه ابنُ أخيه يحيى بنُ علي بن حمود بمالقةَ، فهرب القاسِمُ مِن قُرطبةَ بلا قتالٍ، وصار بأشبيليَّةَ، ثم عاد إليها مرَّةً أخرى، فبقي القاسِمُ بقُرطبةَ شُهورًا واضطَرَب أمرُه، وغَلَب ابنُ أخيه يحيى على المدينةِ المعروفةِ بالجزيرةِ الخضراءِ، وهي كانت مَعقِلَ القاسِمِ، وبها كانت امرأتُه وذخائِرُه، وغلب ابنُ أخيه الثا"},{"id":1426,"era":"c5","t":"وفاة الفيلسوف الصوفي أبو حيان التوحيدي .","s":"هو أبو حيَّانَ عليُّ بن محمَّد بن العبَّاس البغدادي، الصوفي، صاحِبُ التَّصانيفِ، له مصنَّفاتٌ عديدةٌ في الأدبِ والفصاحةِ والفلسفةِ، له مصنَّفٌ كبيرٌ في تصوُّفِ الحكماءِ، وزهَّاد الفلاسفة، وكتابٌ سمَّاه البصائرَ والذخائرَ, وكان سيئَ الاعتقادِ، نفاه الوزيرُ أبو محمد المهلبي. ذكر ابن بابي في كتاب الخريدة والفريدة: \"كان أبو حيان كذَّابًا، قليلَ الدين والوَرَع عن القَذفِ والمجاهَرة بالبُهتان، تعرَّضَ ل"},{"id":1427,"era":"c5","t":"مسير السلطان مشرّف الدَّولة إلى بغداد\n  .","s":"سار السُّلطانُ مُشرفُ الدَّولة مُصعِدًا إلى بغداد من ناحيِة واسط، ورُوسِلَ القادِرُ باللهِ في البروزِ لتَلَقِّيه، فتلقَّاه من الزلاقة، ولم يكن تلقَّى أحدًا من الملوكِ قَبلَه. فرَكِبَ في الطيار، وعن جانبه الأيمَنِ الأميرُ أبو جعفر، وعن يسارِه الأميرُ أبو القاسمِ، وبين يديه أبو الحسَنِ عليُّ بنُ عبد العزيز، وحوالي القُبَّة الشريف أبو القاسم المرتضي، وأبو الحَسَن الزينبي، وقاضي القُضاة ابنُ أبي الشوا"},{"id":1428,"era":"c5","t":"محمود بن سبكتكين يفتح قلعة بالهند .","s":"أوغلَ يَمينُ الدَّولة محمودُ بنُ سبكتكين في بلاد الهندِ، فغَنِمَ وقَتَل، حتى وصل إلى قلعةٍ على رأس جبَلٍ منيعٍ، ليس له مَصعدٌ إلَّا من موضعٍ واحدٍ، وهي كبيرةٌ تَسَعُ خلقًا، وبها خمسُمِئَة فيل، وفي رأسِ الجَبَلِ من الغَلَّات والمياه، وجميعِ ما يحتاجُ الناسُ إليه، فحصرهم يمينُ الدَّولة، وأدام الحِصارَ، وضَيَّق عليهم، واستمَرَّ القتال، فقُتِل منهم كثيرٌ، فلما رأَوا ما حلَّ بهم أذعنوا له، وطلبوا الأما"},{"id":1429,"era":"c5","t":"عودة الحكم إلى بني أمية في الأندلس ثم صراعهم عليه .","s":"لَمَّا انهَزَم البربر عن قُرطُبةَ مع أبي القاسِمِ، اتَّفَق رأيُ أهل قُرطُبة على رَدِّ الأمرِ إلى بني أميَّة، فاختاروا منهم ثلاثةً، وهم: عبدُ الرَّحمنِ بنُ هِشامِ بنِ عبد الجبَّار بن عبد الرَّحمن الناصر أخو المهديِّ، وسُليمانُ بنُ المرتضى، ومحمَّدُ بنُ عبد الرحمن بن هشام بن سليمان القائمُ على المهدي بن الناصر، ثم استقَرَّ الأمر لعبدِ الرَّحمنِ بن هشامِ بنِ عبد الجبَّار، فبويع بالخلافةِ لثلاثَ عَشرة"},{"id":1430,"era":"c5","t":"تجديد البيعة لمشرف الدَّولة البويهي .","s":"ألزم الوزيرُ أبو القاسِمِ المَغربيُّ الأتراكَ والمولَّدينَ لِيَحلِفوا لمُشَرف الدَّولةِ البويهي، وكَلَّف مُشرف الدَّولة المُرتضى ونِظام الحضرتَينِ أبا الحَسَن الزينبي، وقاضي القضاة، وأبا الحَسَن بن أبي الشوارب، وجماعةً مِن الشهود بالحضور، فظَنَّ الخليفةُ القادِرُ بالله أنَّ التحالُفَ لِنيَّةٍ مَدخولةٍ في حَقِّه، فبعث من دارِ الخليفةِ مَن منع الباقينَ بأن يحلِفوا، وأنكر على المُرتَضى والزينبي وقاضي"},{"id":1431,"era":"c5","t":"فتنة بالكوفة بين العلويين والعباسيين .","s":"وقَعَت بين المُختارِ أبي عليِّ بنِ عبيد الله العَلَويِّ وبين الزكيِّ أبي علي النهرسابسي، وأبي الحَسَن عليِّ بنِ أبي طالب بن عمر مُباينةٌ، فاعتضَدَ المُختارُ بالعباسيِّينَ، فساروا إلى بغدادَ، وشَكَوا ما يَفعَلُ بهم النهرسابسي، فتقَدَّمَ الخليفةُ القادِرُ باللهِ بالإصلاح بينهم مراعاةً لأبي القاسمِ الوَزيرِ المغربيِّ؛ لأنَّ النهرسابسي كان صديقَه، وابنُ أبي طالبٍ كان صِهرَه، فعادوا، واستعان كلُّ فريق "},{"id":1432,"era":"c5","t":"المُعِزُّ بنُ باديس الصنهاجيُّ يقضي على فتنة زناتة بإفريقيَّةَ .","s":"خرجَ بإفريقيَّةَ جَمعٌ كثيرٌ مِن زناتة -قبيلة أمازيغية-، فقَطَعوا الطَّريقَ، وأفسَدوا بقسطيلية ونفزاوة، وأغاروا وغَنِموا، واشتَدَّت شَوكتُهم، وكَثُرَ جَمعُهم، فسَيَّرَ إليهم المُعِزُّ بنُ باديس الصنهاجيُّ- صاحِبُ إفريقيَّة- جيشًا، وأمَرَهم أن يَجِدُّوا السَّيرَ ويَسبِقوا أخبارَهم، ففَعَلوا ذلك، وكَتَموا خبرهم، وطَوَوا المراحِلَ حتى أدرَكوهم وهم آمِنونَ مِن الطَّلَبِ، فوضعوا فيهم السَّيفَ، فقُتِلَ "},{"id":1433,"era":"c5","t":"قيام الدَّولة المرداسية في حلب .","s":"مؤسِّسُ الدَّولةِ المرداسيَّة في حلَبٍ هو صالِحُ بنُ مرداس الذي لُقِّبَ أسدَ الدَّولة. وهو من بني كلابٍ، القبيلةِ العربيَّةِ التي كانت تَنزِلُ ضِفافَ الفُراتِ والجزيرة, وكان بالرَّحبةِ رَجلٌ مِن أهلها يُعرَفُ بابنِ محكان، فمَلَك البلدَ، واحتاجَ إلى من يجعَلُه ظَهرَه، ويستعينُ به على مَن يَطمَعُ فيه، فكاتَبَ صالِحَ بنَ مِرداس الكلابيَّ، فقَدِمَ عليه وأقام عنده مُدَّةً، ثمَّ إنَّ صالحًا عدا على ابنِ"},{"id":1434,"era":"c5","t":"وفاة ابن النقيب مِن أئمَّةِ أهل السُّنَّة .","s":"هو عُبَيدُ اللهِ بنُ عَبدِ اللهِ بنِ الحُسَين أبو القاسِمِ الخَفَّاف، المعروف بابنِ النَّقيبِ. كان مِن أئمَّةِ السُّنَّة، قال الخطيبُ: \"سألتُه عن مولِدِه فقال في سنة 305، وأذكُرُ مِن الخُلَفاءِ: المُقتَدِر، والقاهِرَ، والرضيَّ، والمُتَّقيَ لله، والمُستكفيَ، والمُطيع، والطَّائِعَ، والقادِرَ، والغالِبَ بالله، الذي خطَبَ له بولايةِ العَهدِ\". وقيل إنَّه مَكَث دَهرًا طَويلًا يُصَلِّي الفجرَ بوُضوءِ الع"},{"id":1435,"era":"c5","t":"وفاة سلطان الدَّولة أبي شجاع بن بهاء الدَّولة البويهي .","s":"هو مَلِكُ العِراقِ وفارس، سُلطانُ الدَّولة، أبو شُجاع، فناخِسرو بنُ بهاءِ الدَّولةِ خُرَّة فيروز بن عَضُد الدَّولة أبي شُجاع بن رُكنِ الدَّولة حسن بن بُوَيه الديلميُّ الشِّيعيُّ. وَلِيَ إمرةَ واسط لأبيه وبرَعَ في الأدبِ والأخبار والعربيَّة، وأكَبَّ على اللَّهوِ والخَلاعةِ. تملَّك بعد أبيه سنة 403، وهو صبيٌّ، فقُرئَ عَهدُ أبي شجاع من القادِرِ بالله، ولَقَّبه سُلطانَ الدَّولة, ثم أُحضِرَت الخِلَعُ و"},{"id":1436,"era":"c5","t":"وفاة القاضي المعتزلي عبد الجبار .","s":"القاضي أبو الحَسَنِ عبدُ الجَبَّار بنُ أحمدَ بنِ عبدِ الجَبَّار الهمذانيُّ شَيخُ المُعتَزِلة في عَصرِه، وَلِيَ القَضاءَ في الريِّ، وعُرِفَ بقاضي القُضاة، صاحِبُ التصانيفِ، مِن كبارِ فُقَهاءِ الشَّافعيَّة. كان مُنافِحًا عن المُعتَزِلة، وألَّفَ الكثيرَ في نُصرةِ مَذهَبِهم، مثل: كتاب التوحيد، والعدل، وله دلائلُ النبوة، والأمالي، وتنزيه القرآن، توفِّيَ في الرَّيِّ وقد ناهز التسعينَ عامًا."},{"id":1437,"era":"c5","t":"الظاهر الفاطمي ينفي علماء المالكية وينشر مذهب الرافضة .","s":"أمَرَ الظَّاهِرُ بنُ الحاكِمِ العُبَيديُّ حاكِمُ مِصرَ بنَفيِ مَن وُجِدَ مِن الفُقَهاءِ المالكيَّة وغيرِهم. وأمَرَ الدُّعاةَ أن يُحفِّظوا النَّاسَ كِتابَ دعائِمِ الإسلامِ لابنِ بابويهِ القُمِّي الرَّافضي، وكتاب الوزير يعقوبَ بنِ كلس في الفقهِ على مذهَبِ آلِ البَيتِ، وفرَضَ الظَّاهِرُ لِمَن يحفَظُ ذلك مالًا، وجلسَ الدُّعاةُ بالجامِعِ للمُناظرة."},{"id":1438,"era":"c5","t":"بداية هجوم الروم على جزيرة صقلية لأخذها من المسلمين .","s":"خرج الرُّومُ إلى جَزيرةِ صقليَّةَ في جمعٍ كثير، ومَلَكوا ما كان للمُسلمين في جزيرة قلورية، وهي مجاوِرةٌ لجزيرةِ صقليَّة، وشرعوا في بناءِ المساكِنِ يَنتَظِرونَ وُصولَ مراكِبِهم وجُموعِهم مع ابنِ أخت الملك، فبلغ ذلك المُعِزَّ بنَ باديس، فجهَّزَ أسطولًا كبيرًا أربعمِئَة قطعةٍ، وحَشَد فيها، وجمع خلقًا كثيرًا، وتطَوَّعَ جَمعٌ كثير بالجهاد؛ رغبةً في الأجرِ، فسار الأسطولُ حتى قَرُبَ مِن جزيرة قوصرة، وهي "},{"id":1439,"era":"c5","t":"وفاة مشرف الدَّولة بن بويه ونهب بغداد .","s":"هو المَلِك مُشرف الدَّولة أبو عليٍّ بنُ بهاءِ الدَّولة بنِ عَضُدِ الدَّولةِ بنِ بُوَيهِ الديلميُّ الشِّيعيُّ. كان فيه عَدلٌ في الجُملةِ. وكان له العِراقُ في وقتٍ وشيراز وكرمان، ولأخيه سُلطانِ الدَّولةِ صاحِبِ فارِسَ بُخارى ثمَّ اصطلحا. وتمَلَّكَ بعد مُشرف الدَّولة أخوه جلالُ الدَّولة ببغداد. توفِّيَ مُشرف الدَّولة بمرضٍ حادٍّ، وله أربعٌ وعشرون سنة، وكان مُلكُه خَمسَ سِنينَ وخمسة وعشرين يومًا، واست"},{"id":1440,"era":"c5","t":"كسر صنم الهنود الأعظم سومنات في الهند .","s":"كان لأهلِ الهندِ صَنمٌ مَعروفٌ بسومنات يُعَظِّمونَه أشَدَّ التَّعظيمِ، ويقَدِّمونَ له مِن القَرابينِ ما لا يُقَدَّمُ لصَنَمٍ غَيرِه، وكان يمينُ الدَّولة كلَّما فتَحَ مِن الهندِ فتحًا، وكسَرَ صنمًا يقولُ الهنود: إنَّ هذه الأصنامَ قد سَخِطَ عليها سومنات، ولو أنَّه راضٍ عنها لأهلَكَ مَن تقَصَّدَها بسُوءٍ، وقد كانوا يَفِدونَ إليه مِن كُلِّ فَجٍّ عَميقٍ، كما يفِدُ النَّاسُ إلى الكعبةِ بالبيتِ الحَرامِ،"},{"id":1441,"era":"c5","t":"تسلط الأتراك والعيارين ببغداد .","s":"كَثُرَ تسَلُّطُ الأتراك الجُندِ ببغداد، فأكثَروا مُصادراتِ النَّاسِ، وأخذوا الأموالَ، حتى إنَّهم فَرَضوا على الكَرخِ خاصَّةً مِئَة ألف دينار، وعَظُم الخَطبُ، وزاد الشَّرُّ، وأُحرِقَت المنازِلُ والدُّروبُ والأسواقُ، ودخل في الطَّمَعِ العامَّةُ والعيَّارون- والعَيَّارون: لصوصٌ يَمتَهِنونَ النَّهبَ والدعارةَ -، فكانوا يدخُلونَ على الرَّجُلِ فيُطالِبونَه بذخائِرِه، كما يفعَلُ السُّلطانُ بمن يُصادِرُه،"},{"id":1442,"era":"c5","t":"الصلح بإفريقية بين كتامة وزناتة وبين المعز بن باديس الصنهاجي .","s":"ورَدَت رُسُلُ زناتة وكتامة إلى المعِزِّ بنِ باديس الصِّنهاجيِّ، صاحِبِ إفريقيَّةَ، يَطلُبونَ منه الصُّلحَ، وأن يَقبَلَ منهم الطَّاعةَ والدُّخولَ تحت حُكمِه، وشَرَطوا أنَّهم يَحفَظونَ الطَّريقَ، وأعطَوا على ذلك عُهودَهم ومواثيقَهم، فأجابهم إلى ما سألوا، وجاءت مَشيخةُ زناتة وكتامة إليه، فقَبِلَهم وأنزلهم ووصَلَهم، وبذَلَ لهم أموالًا جليلةً."},{"id":1443,"era":"c5","t":"الهدنة بين الظاهر العبيدي الفاطمي حاكم مصر والروم .","s":"وقَعَت الهُدنةُ بينَ مَلِك الروم قسطنطين الثَّامِن، والظَّاهِرِ العُبَيديِّ الفاطميِّ حاكِمِ مصرَ عن ديارِ مِصرَ والشام، وكُتِبَ بينهما كِتابٌ، وتفَرَّدَت الخُطبةُ للظاهِرِ ببلاد الرومِ، وفُتِحَ الجامِعُ الذي بقُسطنطينيَّة، وعُمِلَ له الحُصُر والقناديلُ، وأقيم به مؤذِّنٌ، وعند ذلك أذِنَ الظَّاهِرُ في فتحِ كَنيسةِ القمامة التي بالقُدسِ، وسَمَحَ لهم بإعادةِ بنائها، فحَمَلَ إليها ملوكُ النصارى الأموا"},{"id":1444,"era":"c5","t":"وفاة أبي إسحاق الإسفراييني .","s":"هو الإمامُ العَلَّامةُ الأستاذُ، رُكنُ الدِّينِ، الفَقيهُ الشافعيُّ، الشيخُ أبو إسحاقَ، إبراهيمُ بنُ مُحَمَّد بنِ إبراهيم بنِ مَهران الإسفرايينيِّ, مِن أئمَّةِ الشَّافعيَّة, متكَلِّمٌ أصوليٌّ بارِعٌ، وأحَدُ الأئمَّةِ المُجتَهِدينَ في عَصرِه. صاحِبُ التَّصانيفِ الباهرةِ، والتَّعليقاتِ النَّافِعةِ في أصولِ الفِقهِ، لُقِّبَ برُكنِ الدِّينِ، وهو أوَّلُ مَن تلَقَّبَ مِن الفُقَهاءِ على طريقةِ ألقابِ الح"},{"id":1445,"era":"c5","t":"تنصيب هشام الثالث آخر الأمراء الأمويين في الأندلس .","s":"لَمَّا انقَطَعَت دعوةُ يحيى بنِ عليٍّ الفاطميِّ عن قُرطُبةَ، أجمَعَ رأيُ أهلِ قُرطبةَ على ردِّ الأمرِ إلى بني أمَيَّة، وكان عَميدُهم في ذلك والذي تولَّى مُعظَمَه وسعى في تمامِه الوَزير أبا الحَزمِ جهور بنَ مُحمَّد بن جهور بن عبيد الله بن محمَّد بن الغمر بن يحيى بن عبد الغافر بن أبي عبدة، وقد كان ذهَبَ كُلُّ مَن يُنافِسُ في الرِّياسةِ في الفِتنةِ بقُرطُبةَ، فراسَلَ جهور من كان معه على رأيِه مِن أهل"},{"id":1446,"era":"c5","t":"وفاة الإمام اللالكائي .","s":"هو الإمامُ الحافِظُ المُجَوِّد، المُفتي: أبو القاسِمِ هِبةُ اللهِ بنُ الحَسَنِ بنِ مَنصورٍ، الطَّبريُّ الرازيُّ، الشَّافعيُّ اللَّالَكائي، مفيدُ بغدادَ في وقته. وهو طبَريُّ الأصل، أحدُ تلامذةِ الشيخِ أبي حامدٍ الإسْفِرايينيِّ، كان يَفهَمُ ويَحفَظُ، وعُنِيَ بالحديثِ فصَنَّفَ فيه أشياءَ كثيرةً، ولكِنْ عاجَلَتْه المنيَّةُ قبل أن تشتَهِرَ كُتُبُه، وله كتابٌ في العقيدةِ على مَنهَجِ السَّلَفِ، وهو كتابُ"},{"id":1447,"era":"c5","t":"شغب الجند الأتراك ببغداد على جلال الدَّولة .","s":"ثار الجُندُ الأتراكُ ببغداد على جَلالِ الدَّولة البُويهيِّ الشِّيعيِّ، وشَغَّبوا، وطالبوا الوزيرَ أبا علي بنَ ماكولا بما لهم من العلوفةِ والأدرار، ونَهَبوا دارَه ودُورَ كُتَّاب المَلِك وحواشيه، حتى المُغَنِّينَ والمُخَنَّثين، ونَهَبوا صياغاتٍ أخرَجَها جلالُ الدَّولة لتُضرَبَ دنانيرَ ودراهِمَ، وتُفَرَّق فيهم، وحَصَروا جلالَ الدَّولة في داره، ومَنَعوه الطَّعامَ والماءَ، حتى شَرِبَ أهلُه ماءَ البئر، "},{"id":1448,"era":"c5","t":"الاختلاف بين الديلم والأتراك بالبصرة .","s":"وَلِيَ النَّفيسُ أبو الفتحِ مُحمَّدُ بنُ أردشير البَصرةَ، استعمَلَه عليها جلالُ الدَّولة البُويهيُّ، فلمَّا وَصَل إلى المشان مُنحَدِرًا إليها، وقع بينه وبين الديلمِ الذين بالمشان وقعةٌ، فاستظهر عليهم وقَتَل منهم، وكانت الفِتَنُ بالبصرةِ بين الأتراك والديلم، وبها المَلِكُ العزيزُ أبو منصور بن جلال الدَّولة، فقَوِيَ الأتراكُ بها، فأخرجوا الدَّيلمَ، فمَضَوا إلى الأبلَّة، وصاروا مع بختيار بنِ عليٍّ، ف"},{"id":1449,"era":"c5","t":"وفاة قوام الدَّولة أبو الفوارس البويهي الشيعي صاحب كرمان .","s":"هو قوام الدَّولة أبو الفوارِسِ بنُ بَهاءِ الدَّولة البُويهيُّ الدَّيلميُّ الشِّيعيُّ، صاحِبُ كرمان. في سنة410 قُرِئَ عَهدُ أبي الفوارس ولُقِّبَ قوام الدَّولة، وخُلِعَ عليه خِلَعًا حُمِلَت إليه بوِلايةِ كرمان. كان أبو الفوارِسِ قد تجَهَّزَ لِقَصدِ بلاد فارس، وجَمَع عسكرًا كثيرًا، فأدرَكَه أجَلُه، فلمَّا توفِّيَ نادى أصحابُه بشعارِ ابنِ أخيه المَلِك أبي كاليجار، وأرسلوا إليه يَطلُبونَه إليهم، فسار م"},{"id":1450,"era":"c5","t":"كتاب محمود بن سبكتكين بما فعله بالباطنية وغلاة الرافضة .","s":"وردَ إلى الخليفةِ القادِرِ بالله كِتابٌ مِن الأميرِ يَمينِ الدَّولة محمود بنِ سبكتكين الغزنوي أنَّه أحَلَّ بطائفةٍ مِن أهلِ الرَّيِّ مِن الباطنيَّة وغُلاة الرَّوافِضِ قَتلًا ذريعًا، وصَلبًا شَنيعًا، وأنَّه انتَهَب أموالَ رَئيسِهم رستُم بن علي الديلمي، فحصَلَ منها ما يُقارِبُ ألف ألف دينار، وقد كان في حيازتِه نحوٌ مِن خمسين امرأةً حُرَّة، وقد وَلَدْنَ له ثلاثًا وثلاثين ولدًا بين ذكَرٍ وأنثى، وكانوا"},{"id":1451,"era":"c5","t":"وقعة الأقحوانة بين الظاهر (الفاطمي) وبين حسان بن الجراح .","s":"كان حَسَّانُ بنُ الجَرَّاح قد خرج على الحاكِمِ، وأمَدَّه الرُّومُ، ثمَّ إنَّ الظاهِرَ لَمَّا عقَدَ المُعاهَدةَ مع الرُّومِ كان منها عدَمُ إمدادِ حَسَّان، فلمَّا كانت هذه السَّنَةُ أرسل الظَّاهِرُ الفاطميُّ جَيشًا بقيادةِ أنوشتكين التركي لَمَّا بلَغَه أنَّ حَسَّان وسِنان بن عليان أميرَ بني كلابٍ وصالِحَ بنَ مرداس أميرَ حَلَب اتَّفَقوا على إخراجِ الفاطميِّينَ مِن الشَّامِ واقتسامِها بينهم، فكانت الح"},{"id":1452,"era":"c5","t":"الخليفة العباسي القادر يقرر مذهب اعتقاد أهل السنة والجماعة .","s":"في الثَّامِنَ عَشَر مِن رَجَب جُمِعَ القُضاةُ والعُلَماءُ في دارِ الخلافة، وقُرِئَ عليهم كتابٌ كان القادِرُ بالله قد جمع فيه مواعِظَ وتفاصيلَ مذاهِبِ أهلِ البَصرةِ، وفيه الرَّدُّ على أهلِ البِدَع، وتَفسيقُ مَن قال بخَلقِ القُرآنِ، وصِفةُ ما وقع بين بِشرٍ المِريسيِّ وعبد العزيز بن يحيى الكِناني من المناظرة، ثمَّ خُتِمَ القَولُ بالمواعِظِ والقَولِ بالمعروفِ، والنَّهيِ عن المُنكَرِ، وأخَذَ خُطوطَ الح"},{"id":1453,"era":"c5","t":"سير قسطنطين ملك الروم إلى الشام وهلاك معظم جيشه بالعطش .","s":"خرج مَلِكُ الرُّومِ مِن القُسطنطينيَّةِ في ثلاثمِئَة ألفِ مقاتلٍ إلى الشام، فلم يَزَلْ بعساكِرِه حتى بلغوا قريبَ حَلَب، وصاحِبُها شبل الدَّولةِ نَصرُ بنُ صالحِ بنِ مرداس، فنزلوا على يومٍ منها، فلَحِقَهم عطَشٌ شَديدٌ، وكان الزَّمانُ صَيفًا، وكان أصحابُه مختَلِفينَ عليه، فمِنهم من يحسُدُه، ومنهم من يَكرَهُه، وممَّن كان معه ابنُ الدوقس، ومِن أكابِرِهم، وكان يريدُ هلاكَ المَلِك لِيَملِكَ بعده، فقال ال"},{"id":1454,"era":"c5","t":"وفاة يمين الدَّولة محمود بن سبكتكين الغزنوي وعهده إلى ابنه محمد  .","s":"هو يَمينُ الدَّولةِ، فاتِحُ الهِندِ: أبو القاسِمِ، المَلِكُ السُّلطانُ مَحمودُ بنُ سَيِّد الأمراءِ ناصِر الدَّولةِ سبكتكين، التُّركيُّ، صاحِبُ خُراسان والهِند. وُلِدَ في غزنة سنةَ 361. كان- رحمه الله- صادِقَ النِّيَّة في إعلاءِ الدِّينِ، مُظَفَّرًا كثيرَ الغَزوِ، وكان ذكيًّا بعيدَ الغَورِ، صائِبَ الرَّأيِ، وكان مَجلِسُه مَورِدَ العُلَماءِ. كان والِدُه أبو منصورٍ سبكتكين قد تولَّى إمرةَ غزنة بعد وف"},{"id":1455,"era":"c5","t":"البيعة لأبي جعفر عبد الله بن القادر بالله بولاية العهد  .","s":"مَرِضَ الخليفةُ القادِرُ باللهِ، وأُرجِفَ بمَوتِه، فجلَسَ جُلوسًا عامًّا وأذِنَ للخاصَّةِ والعامَّةِ فوَصَلوا إليه، فلما اجتَمَعوا قام الصاحِبُ أبو الغنائِمِ مُحَمَّدُ بنُ أحمد فقال: خَدَمُ مولانا أميرِ المؤمنينَ داعُونَ له بإطالةِ البَقاءِ، وشاكِرونَ لِما بلَغَهم مِن نَظَرِه لهم وللمُسلِمينَ، باختيارِ الأميرِ أبي جَعفرٍ عَبدِ اللهِ بنِ القادِرِ لولايةِ العَهدِ، فقال الخليفةُ للنَّاسِ: قد أذِنَّا "},{"id":1456,"era":"c5","t":"تغلب مسعود بن محمود بن سبكتكين على أخيه محمد .","s":"لَمَّا توفِّيَ يَمينُ الدَّولة وكان قد عَهِدَ لابنه محمَّدٍ دون مسعودٍ، وكان ابنُه مَسعودٌ بأصبهان، فلمَّا بلَغَه الخبَرُ سار إلى خراسان، واستخلف بأصبهانَ بَعضَ أصحابِه في طائفةٍ مِن العسكر، فحين فارَقَها ثار أهلُها بالوالي عليهم فقَتَلوه، وقَتَلوا مَن معه من الجُندِ، وأتى مسعودًا الخبَرُ، فعاد إليها وحَصَرها، وفتَحَها عَنوةً، وقَتَل فيها فأكثَرَ، ونهبَ الأموالَ، واستخلف فيها رجُلًا كافيًا، وكَتَب"},{"id":1457,"era":"c5","t":"استيلاء الروم على الرها (مدينة في الجزيرة الفراتية) .","s":"كانت الرَّها بيدِ نَصرِ الدَّولة بن مروان، فلمَّا قُتِلَ عَطير الذي كان صاحِبَها، شَفَعَ صالحُ بنُ مرداس، صاحِبُ حَلَب، إلى نَصرِ الدَّولة ليُعيدَ الرَّها إلى ابنِ عطير، وإلى ابنِ شبلٍ، بينهما نِصفَينِ، فقَبِلَ شَفاعَتَه، وسَلَّمَها إليهما، وكان في الرَّها برجانِ حَصينانِ أحَدُهما أكبَرُ من الآخر، فتَسَلَّمَ ابنُ عطير الكبير، وابنُ شبل الصَّغيرَ، وبَقِيَت المدينةُ معهما إلى هذه السَّنة، فراسل ابنُ"},{"id":1458,"era":"c5","t":"الروم يسيطرون على قلعة أفامية بالشام .","s":"سيَّرَ الظَّاهِرُ حاكِمُ مِصرَ العُبَيديُّ إلى الشَّامِ الدزبريَّ وزيرَه، فملَّكه، وقَصَد حسَّانَ بنَ المفرج الطائي، فألحَّ في طلَبِه، فهَرَب منه، ودخل بلدَ الرُّومِ ولَبِسَ خِلعةَ مَلِكِهم، وخرج مِن عِندِه وعلى رأسِه عَلَمٌ فيه صليبٌ، ومعه عسكَرٌ كثيرٌ، فسار إلى أفامية فكَبَسَها، وغَنِمَ ما فيها، وسبى أهلَها، وأسَرَهم، وسيَّرَ الدزبري إلى البلادِ يستنفِرُ النَّاسَ للغزو وخرج فخافه نصرُ بن صالح وق"},{"id":1459,"era":"c5","t":"نهاية الدَّولة الأموية بالأندلس وقيام الدَّولة الجهورية في قُرطُبة .","s":"كان المُعتَدُّ بالله أبو بكر هِشامُ بنُ مُحمَّدِ بنِ عبدِ المَلِك بن عبد الرحمن النَّاصر الأمويُّ أميرَ قُرطُبةَ، لكنَّه لم يَقُمْ بها إلا يسيرًا حتى قامت عليه طائفةٌ مِن الجُندِ فخُلِعَ، وجَرَت أمورٌ مِن جُملتِها إخراجُ المُعتَدِّ بالله مِن قَصرِه هو وحشَمُه والنِّساءُ حاسراتٍ عن أوجُهِهنَّ حافيةً أقدامُهنَّ إلى أن أُدخِلوا الجامِعَ الأعظَمَ على هيئةِ السَّبايا، فأقاموا هنالك أيامًا يُتعَطَّفُ عل"},{"id":1460,"era":"c5","t":"تجدد الفتنة بين السنة والشيعة ببغداد .","s":"تجَدَّدَت الفِتنةُ ببغدادَ بينَ السُّنَّة والشِّيعة، وكان سبَبُ ذلك أنَّ الوزيرَ أبا القاسم عليَّ بنَ أحمد الملَقَّب بالمذكور أظهَرَ العَزمَ على الغَزاة، واستأذن الخليفةَ في ذلك، فأَذِنَ له، وكُتِبَ له منشورٌ من دار الخلافة، وأعطى عَلَمًا، فاجتمَعَ له لفيفٌ كثيرٌ، فسار واجتاز ببابِ الشعير، وطاق الحراني، وبين يديه الرِّجالُ بالسِّلاحِ، فصاحوا بذِكرِ أبي بكرٍ وعُمَرَ، رَضِيَ الله عنهما، وقالوا: هذا "},{"id":1461,"era":"c5","t":"وفاة الخليفة العباسي القادر بالله وتولي ابنه القائم بأمر الله الخلافة .","s":"هو الخليفةُ أبو العَبَّاسِ أحمَدُ بنُ الأميرِ إسحاقَ بنِ المُقتَدِرِ جَعفرِ بنِ المُعتَضِدِ العباسيِّ البغداديِّ. ولِدَ سنة 336. وأمُّه اسمُها: تمني, ماتت في دولتِه، وكان أبيضَ كَثَّ اللِّحيةِ يَخضِبُ, دَيِّنًا عالِمًا متعَبِّدًا وقورًا، مِن جِلَّةِ الخُلفاءِ وأمثَلِهم. عَدَّه ابنُ الصَّلاحِ في الشَّافعيَّة؛ فقد تفَقَّه على أبي بشرٍ أحمَدُ بنُ محمَّدٍ الهَرَويِّ. قال الخطيبُ البغدادي: \"كان القادِر"},{"id":1462,"era":"c5","t":"طاعون جارف امتد من الهند إلى بلاد العجم والعراق .","s":"كان الطَّاعونُ ببِلادِ الهِندِ والعَجَمِ، وعَظُمَ إلى الغاية، وكان أكثَرُه بغُزنة وخراسان وجرجان والريِّ وأصبهان ونواحي الجَبَل إلى حلوان، وامتَدَّ إلى المَوصِل والجزيرة وبغداد، ثمَّ امتَدَّ إلى شيراز، وتَبِعَه غلاءٌ شديد، واستسقى النَّاسُ فلم يُسْقَوا، وكان عامًّا في جميعِ البلادِ، وكَثُرَ المَوتُ، فدُفِنَ في أصبهانَ في عِدَّةِ أيَّامٍ أربعونَ ألفَ مَيِّتٍ، وكَثُرَ الجُدريُّ في النَّاسِ فأُحصي با"},{"id":1463,"era":"c5","t":"هزيمة الأرمن على يد نائب نصر الدَّولة بن مروان .","s":"جمَعَ نائِبُ نَصرِ الدَّولة بنِ مَروان بالجزيرة جمعًا يُنَيِّفُ على عشرةِ آلافِ رَجُلٍ، وغزا مَن يُقارِبُه مِن الأرمن، وأوقع بهم وأثخَنَ فيهم، وغَنِمَ وسَبى كثيرًا، وعاد ظافرًا مَنصورًا"},{"id":1464,"era":"c5","t":"وقوع فتنة بين أهل تونس من إفريقية .","s":"كان بين أهلِ تونُسَ مِن إفريقيَّةَ خِلافٌ، فسار المُعِزُّ بنُ باديس صاحِبُ إفْريقيَّةَ إليهم بنَفسِه، فأصلحَ بينهم، وسَكَنَت الفتنةُ وعاد."},{"id":1465,"era":"c5","t":"ثورة الشيعة في إفْريقيَّة وقمعهم .","s":"اجتمع ناسٌ كثيرٌ مِن الشِّيعةِ بإفريقيَّةَ، وساروا إلى أعمالِ نفطة، فاستولوا على بلدٍ منها وسكنوه، فجَرَّد إليهم المعِزُّ بنُ باديس صاحِبُ إفْريقيَّة عسكرًا، فدخلوا البلادَ وحاربوا الشيعةَ وقتلوهم أجمعين."},{"id":1466,"era":"c5","t":"عدم تمكن أهل العراق من الحج بسبب قطاع الطرق .","s":"خرَجَت العرَبُ على حُجَّاجِ البَصرةِ ونَهَبوهم، وحَجَّ النَّاسُ مِن سائِرِ البلادِ إلَّا من العراقِ."},{"id":1467,"era":"c5","t":"تجدد الفتنة بين جلال الدَّولة البويهي وبين الأتراك ببغداد .","s":"تجدَّدت الفِتنةُ بين جلالِ الدَّولةِ البُويهي وبين الأتراك، فأغلَقَ بابه، فجاءت الأتراكُ ونهبوا دارَه، وسلبوا الكُتَّابَ وأربابَ الديوانِ ثيابَهم، وطلبوا الوزيرَ أبا إسحاقَ السهلي، فهرب إلى حلةِ كمال الدَّولةِ غريب بن محمد، وخرج جلالُ الدَّولة إلى عكبرا في شهرِ ربيعٍ الآخر، وخطب الأتراكُ ببغداد للمَلِك أبي كاليجار، وأرسلوا إليه يطلبونَه وهو بالأهواز، فمَنَعه العادلُ بن مافنة عن الإصعادِ إلى أن يحض"},{"id":1468,"era":"c5","t":"ثورة الأتراك على الملك جلال الدَّولة البويهي .","s":"ثارت الأتراك بالمَلِك جلالِ الدَّولة البويهي ليأخُذوا أرزاقَهم، وأخرجوه من دارِه، ورسَموا عليه في المسجِدِ، وأُخرِجَت حريمُه، فذهب في اللَّيلِ إلى دار الشَّريفِ المرتضى فنزلها، ثمَّ اصطلحت الأتراكُ عليه وحَلَفوا له بالسَّمعِ والطاعة، وردُّوه إلى دارِه."},{"id":1469,"era":"c5","t":"ثورة العيارين ببغداد .","s":"ثار العَيَّارون ببغداد -والعَيَّارون لصوصٌ يَمتَهِنونَ النَّهبَ والدعارةَ - وأخذوا أموالَ النَّاسِ ظاهرًا، وعَظُم الأمرُ على أهلِ البَلَدِ، وطَمِعَ المُفسِدونَ إلى حَدِّ أنَّ بعضَ القُوَّادِ الكِبارِ أخَذَ أربعةً مِن العيَّارينَ، فجاء عقيدُهم وأخذَ مِن أصحابِ القائِدِ أربعةً، وحضر بابَ دارِه ودقَّ عليه الباب، فكَلَّمَه من داخل، فقال العقيدُ: قد أخذتُ مِن أصحابِك أربعةً، فإنْ أطلقْتَ مَن عندَك أطلق"},{"id":1470,"era":"c5","t":"مسعود بن سبكتكين يتولى تدبير شؤون الدولة الغزنوية .","s":"لَمَّا استقَرَّ المُلكُ لمسعود بن سبكتكين بعد أبيه أقرَّ بما كان قد فتَحَه أبوه من الهندِ نائبًا يُسمَّى أحمد ينالتكين، وقد كان أبوه محمَّد استنابه بها ثقةً بجَلَدِه ونَهضَتِه، فرَسَخت قَدَمُه فيها، وظَهَرت كِفايته. ثمَّ إنَّ مسعودًا بعد فراغِه مِن تقرير قواعِدِ المُلك، والقَبضِ على عَمِّه يوسف والمخالفين له، سار إلى خراسان عازمًا على قَصدِ العراق، فلمَّا أبعد عصى ذلك النائِبُ بالهند، فاضطُرَّ مسع"},{"id":1471,"era":"c5","t":"مسعود بن محمود الغزنوي يفتح قلعة سرستي في الهند .","s":"فتح السُّلطانُ مسعود بن محمود بن سبكتكين قلعةَ سرستي وما جاورها من بلاد الهندِ، وكان سبَبُ ذلك عصيانَ نائِبِه بالهند أحمد ينالتكين عليه ومَسيره إليه، فلمَّا عاد أحمد إلى طاعتِه أقام بتلك البلادِ طويلًا حتى أَمِنَت واستقَرَّت، وقصد قلعةَ سرستي، وهي مِن أمنَعِ حُصون الهند وأحصَنِها، فحَصَرها، وقد كان أبوه حَصَرها غيرَ مَرَّة، فلم يتهيَّأْ له فتحُها، فلمَّا حَصَرها مسعود راسلَه صاحِبُها، وبذل له مالً"},{"id":1472,"era":"c5","t":"استيلاء الروم على قلعةُ بركوي المتاخِمةُ للأرمن .","s":"كانت قلعةُ بركوي المتاخِمةُ للأرمن في يَدِ أبي الهيجاء بن ربيب الدَّولة، ابنِ أخت وهسوذان بن مملان، فتنافَرَ هو وخاله، فأرسل خالُه إلى الرومِ فأطمعهم فيها، فسَيَّرَ مَلِكُ الروم إليها جمعًا كثيرًا فمَلَكوها، فبلغ الخبَرُ إلى الخليفة العباسي القائمِ بأمرِ الله، فأرسل إلى أبي الهيجاءِ وخالِه مَن يُصلِحُ بينهما ليتَّفِقا على استعادةِ القلعةِ، فاصطلحا، ولم يتمَكَّنا من استعادتِها، واجتمع إليهما خلقٌ ك"},{"id":1473,"era":"c5","t":"استعانة ابنُ وثَّاب النميري بالروم ضد المسلمين .","s":"جمع ابنُ وثَّاب النميري جمعًا كثيرًا من العَرَبِ وغيرِهم، واستعان بمَن بالرَّها مِن الرُّومِ على المُسلِمينَ، فسار معه منهم جيشٌ كثيفٌ، وقصَدَ بلَدَ نصرِ الدَّولة أحمدَ بنِ مروان الكردي صاحِبِ ديارِ بكر، ونهب وأخرب. فجمَع ابنُ مروان جموعَه وعساكِرَه واستمَدَّ قرواشًا أميرَ بني عقيلٍ وغَيرَه، وأتته الجنودُ مِن كلِّ ناحية، فلما رأى ابنُ وثاب ذلك وأنَّه لا يتِمُّ له غَرَضٌ عاد عن بلادِه، وأرسل ابنُ م"},{"id":1474,"era":"c5","t":"وهن أمر الخلافة ببغداد .","s":"وَهَن أمرُ الخلافةِ والسَّلطَنةِ ببغداد، حتى إنَّ بَعضَ الجُندِ خَرَجوا إلى قريةِ يحيى، فلَقِيَهم أكراد، فأخَذوا دوابَّهم، فعادوا إلى حَقلِ الخليفةِ القائِمِ بأمر الله، فنَهَبوا شيئًا من ثَمَرتِه، وقالوا للعاملينَ فيه: أنتم عَرَفتم حالَ الأكرادِ ولم تُعلِمونا، فسَمِعَ الخليفةُ الحالَ، فعَظُمَ عليه، ولم يَقدِرْ جلال الدَّولة البويهيُّ على أخذِ أولئك الأكراد لعَجزِه ووَهَنِه، واجتهدَ في تسليمِ الجُن"},{"id":1475,"era":"c5","t":"مَسعودُ الغزنوي يسيطر على مدينة جرجان وطبرستان .","s":"كان مَسعودُ الغزنوي قد أقرَّ دارا بن منوجهر بن قابوس على جرجانَ وطبرستان، وتزوَّج أيضًا بابنةِ أبي كاليجار القوهي، مقدَّم جيشِ دارا، فلمَّا سار إلى الهند منعوا ما كان استقَرَّ عليهم من المال، وراسلوا علاءَ الدَّولة بن كاكويه وفرهاذ بالاجتماعِ على العصيان والمخالفة، وقَوِيَ عزمُهم على ذلك ما بلَغَهم من خروج الغز بخراسان، فلما عاد مسعودٌ من الهند وأجلى الغزَّ وهَزَمهم سار إلى جرجان فاستولى عليها ومل"},{"id":1476,"era":"c5","t":"ثورة الجند على الوزير جلال الدَّولة البويهي الشيعي .","s":"ثار الجُندُ الأتراكُ ببغدادَ على جلالِ الدَّولةِ البُويهيِّ الشيعيِّ، وأرادوا إخراجَه منها، فاستنظَرَهم ثلاثة أيام، فلم يُنظِروه، ورَمَوه بالآجُرِّ، فأصابه بعضُهم، واجتمع الغِلمانُ فرَدُّوهم عنه، فخرَجَ من بابٍ لطيفٍ في سميرية- نوعٍ مِن السفُنِ- مُتنكِّرًا، وصَعِدَ راجلًا منها إلى دارِ المرتضى بالكرخ، وخرج من دار المرتضى، وسار إلى رافعِ بنِ الحُسَين بن مقن بتكريت، وكسَر الأتراكُ أبوابَ داره ودخلوه"},{"id":1477,"era":"c5","t":"وقعة الجفنة بين جماعة زناتة والمعز بن باديس صاحب إفْريقيَّة .","s":"اجتَمَعت زناتة بإفريقيَّة، وزحَفَت في خيلِها ورَجِلِها يريدونَ مدينة المنصورة، فلَقِيَتهم جيوشُ المعز بن باديس، صاحِبِ إفْريقيَّة، بموضعٍ يقال له الجفنة قريبٍ من القيروان، فاقتتلوا قتالًا شديدًا، وانهزمت عساكرُ المعِزِّ، ففارقت المعركةَ، وهم على حامية، ثم عاودوا القتالَ، وحَرَّض بعضُهم بعضًا فصَبَرت صنهاجة، وانهزمت زناتة هزيمةً قبيحة، وقُتِلَ منهم عددٌ كثير، وأُسِرَ خَلقٌ عظيمٌ، وتُعرَف هذه الوقعة"},{"id":1478,"era":"c5","t":"قيام دولة ذي النون بطليطلة .","s":"لَمَّا نَشَبت فتنةٌ في طُلَيطلة قام أهلُها بإنهاء حُكمِ ابنِ يعيش، واستدعوا عبد الرَّحمن بن ذي النون أميرَ شنتمرية لتولِّي رئاسة مدينتهم، فأرسل ابنَه إسماعيل فكان أوَّلَ مَن حكم طُلَيطلة من بني ذي النُّونِ، فأحسن إدارتَها إلى أن مات، فتولَّى بعده ابنُه المأمون. هذه بدايةُ قيام دولةِ ذي النون في طُلَيطلة."},{"id":1479,"era":"c5","t":"المسلمون يفتحون السويداء وربض الرها .","s":"اجتمع ابنُ وثَّاب النميري صاحِبُ حران وقريبُه ابن عطير النميري، وأمدَّهما نصر الدَّولة بنُ مروان بعسكرٍ كثيف، فساروا جميعُهم إلى السُّويداء جنوب دمشق، وكان الرومُ قد أحدثوا عمارتَها في ذلك الوقت، واجتمع إليها أهلُ القرى المجاورةِ لها، فحصرها المسلمون وفتحوها عَنوةً، وقتلوا فيها ثلاثةَ آلاف وخمسَمِئَة من الرومِ، وغَنِموا ما فيها، وسَبَوا خلقًا كثيرًا، وقَصَدوا الرَّها فحصروها، وقطعوا الميرةَ عنها، "},{"id":1480,"era":"c5","t":"وفاة الظاهر لإعزاز دين الله الفاطمي وتولي ابنه المستنصر الحكم .","s":"هو الظاهِرُ لإعزازِ دينِ الله أبو الحَسَن عليُّ بن أبي علي المنصور الحاكم الفاطمي العُبيدي الإسماعيليُّ الباطنيُّ, أمُّه أم ولد تدعى رقية، وُلِدَ بالقاهرة سنة 395، وبويع بالحُكمِ بعد أبيه في يوم عيد الأضحى سنة 411، وله من العمرِ 16 سنة و3 أشهر، وكان له مِصرُ، والشام، والخطبة له بإفريقيَّة، وكان جميلَ السِّيرةِ، حَسَن السياسةِ، مُنصِفًا للرعية، إلَّا أنَّه مُشتَغِلٌ بلذَّاته محِبٌّ للدَّعَة والراحة"},{"id":1481,"era":"c5","t":"الخليفة العباسي يأذن لحاكِمُ مصر العُبَيديّ بإصلاح نهر الكوفة .","s":"بعث حاكِمُ مصر العُبَيديُّ بمال لإصلاحٍ نهر بالكوفة إن أذِنَ الخليفةُ العباسيُّ في ذلك، فجمع الخليفةُ الفُقَهاءَ وسألهم عن هذا المالِ فأفتَوا بأنَّ هذا المالَ فَيءٌ للمسلمين، يُصرَفُ في مصالِحِهم، فأذِنَ في صَرفِه في مصالحِ المُسلِمينَ"},{"id":1482,"era":"c5","t":"وفاة أبي الحسين القدوري الحنفي .","s":"هو العلَّامة أبو الحُسَين أحمدُ بنُ محمد بن أحمد بن جعفر بن حمدان الحنفيُّ الفقيهُ البغدادي المشهورُ بالقُدوري. ولِدَ ببغداد سنة 362. قال أبو بكر الخطيب: \"لم يحدِّثْ إلَّا شيئًا يسيرًا، وكان صَدوقًا، انتهت إليه بالعراقِ رياسةُ أصحابِ أبي حنيفة، وعَظُم عندهم قَدرُه وارتفع جاهُه، وكان حسَنَ العبارةِ في النَّظَرِ، جريءَ اللسان، مُديمًا للتلاوة\"، وهو مُصَنِّف مُختَصَر القُدوري في فقه الحنفيَّة، ويُعتَ"},{"id":1483,"era":"c5","t":"وفاة ابن سينا الطبيب الفيلسوف .","s":"هو الفيلسوف الشَّهيرُ، الرَّئيسُ أبو علي الحُسَين بنُ عبدِ الله بن الحَسَن بن علي بن سينا البلخي ثم البخاري، صاحِبُ التصانيف في الطبِّ والفلسفة والمنطق. الحكيمُ المشهور، كان بارعًا في الطبِّ في زمانه، وكان أبوه من أهلِ بلخ، وانتقل إلى بخارى، وهو من العُمَّال فيها، ومن دعاة الإسماعيليَّة، تولَّى العملَ بقرية من ضياعِ بخارى يقال لها خرميثنا، وُلِدَ ابنُ سينا بها سنة 370، واسم أمِّه ستارة. تعلَّم بها"},{"id":1484,"era":"c5","t":"مَلِكُ الأبخاز (القوقاز) يحاصر مدينة تفليس .","s":"حصَرَ مَلِكُ الأبخاز- القوقاز- مدينة تفليس – عاصِمةَ جورجيا الآن، وتسمى تبليسي- وامتنع أهلُها عليه، فأقام عليهم محاصِرًا ومُضَيِّقًا، فنَفِدَت الأقوات، وانقطعت الميرةُ، فأنفذ أهلُها إلى أذربيجان يَستنفرون المسلمينَ، ويسألونهم إعانَتَهم، فلمَّا وصل الغز إلى أذربيجان، وسَمِعَ الأبخاز بقربهم، وبما فعلوا بالأرمن، رحلوا عن تفليس مُجفِلين خائفين. ولَمَّا رأى وهسوذان صاحِبُ أذربيجان قُوَّةَ الغز، وأنَّه "},{"id":1485,"era":"c5","t":"ابتداء ظهور السلاجقة الغز قبل إسلامهم .","s":"دخلَ رُكنُ الدين أبو طالبٍ طغرلبك محمد بن ميكائيل بن سلجوق مدينةَ نيسابور -شمال غرب أفغانستان- مالِكًا لها، وكان سببُ ذلك أنَّ الغزَّ السلجقيَّة لَمَّا ظهروا بخراسان أفسدوا، ونهبوا، وخرَّبوا البلاد، وسَبَوا، وسَمِعَ الملك مسعودُ بنُ محمود بن سبكتكين بخَبَرِهم، فسَيَّرَ إليهم حاجِبَه سباشي في ثلاثين ألف مقاتلٍ، فسار إليهم من غزنة، فلما بلغ خراسانَ أقام مدَّة سنة على المدافعة والمُطاولة، كان سباشي ي"},{"id":1486,"era":"c5","t":"جلال الدَّولة البويهي يتسمى بـملك الملوك والعلماء ينكرون عليه .","s":"سأل جلالُ الدَّولةِ البويهيُّ الشيعيُّ الخليفةَ القائمَ بأمرِ الله ليخاطَبَ بشاهِنشاه أي: ملك الملوك، فامتنع، ثمَّ أجاب إليه؛ إذ أفتى الفقهاءُ بجَوازِه، فكتب فتوى إلى الفُقَهاءِ في ذلك، فأفتى القاضي أبو الطيِّب الطبري، والقاضي أبو عبد الله الصيمري، والقاضي ابن البيضاوي، وأبو القاسم الكرخي بجوازِه، وامتنع منه قاضي القضاة أبو الحَسَن الماوردي، وجرى بينه وبين من أفتى بجوازه مراجعاتٌ، وخُطِبَ لجلالِ ا"},{"id":1487,"era":"c5","t":"الفاطميون يهزمون شبل الدَّولةِ بن مرداس ويسيطرون على حلب .","s":"عَهِدَ المُستنصر الفاطميُّ إلى القائد أنوشتكين الدزبري أميرِ دمشقَ بالاستيلاء على حَلَب وأخذها مِن شبل الدَّولةِ نصرِ بنِ صالح بن مرداس، فاستأذنَ الرومَ لحربهِ؛ لأنَّ شبلَ الدَّولة كان حليفًا للروم على دَفْعِ أتاوة سنويةٍ لهم، فتعهَّد أنوشتكين بدَفعِ نَفسِ الأتاوة للرُّومِ، إن هم أذنوا له بحَربِه، فأذنوا له فقام بالسَّيرِ إلى شبل الدَّولةِ وهَزَمه واستولى على حلَب، وقَتَل شبلَ الدَّولة."},{"id":1488,"era":"c5","t":"قيام دولة الصليحيين باليمن .","s":"قامَت الدعوةُ الصُّلَيحيَّة باليمنِ والتي أصلها إسماعيليٌّ عن طريق علي بن محمد الصليحي. كانت الدعوةُ الإسماعيليَّةُ قد انقطعت في اليمَنِ بعد اختلافِ عليِّ بن الفضل وابن حوشب؛ إذ سيطَرَ الأوَّلَ على المنطقةِ وأعلن كُفرَه الصَّريحِ حتى مات مسمومًا عام 303هـ على حين اعتزل ابن حوشب في مغارب اليمن. حتى قامت الدعوةُ مُجدَّدًا على يدِ عليٍّ الصليحيِّ الذي كان أبوه محمَّدٌ مِن قضاة اليمن سُنِّي المذهب, وك"},{"id":1489,"era":"c5","t":"الخطبة العباسية بحران والرقة .","s":"خطبَ شبيب بن وثاب النميريُّ، صاحِبُ حران والرَّقَّة، للخليفةِ القائم بأمر الله، وقطَعَ خُطبةَ المستنصر بالله العُبَيديُّ، وكان سببُها أنَّ نَصرَ الدَّولة بنُ مروان كان قد بلغه عن الدزبري نائبُ العلويين بالشام أنَّه يتهَدَّده، ويريد قصدَ بلاده، فراسل ابنُ مروان قرواشًا، صاحِبَ الموصل، وطلب منه عسكرًا، وراسل أيضًا شبيبًا النميري يدعوه إلى المُوافقة، ويُحَذِّرُه من المغاربةِ العُبَيديِّين، فأجابه إلى"},{"id":1490,"era":"c5","t":"وفاة الحافظ أبي نعيم الأصبهاني .","s":"هو الإمامُ الثِّقةُ العلَّامة، شيخُ الإسلامِ: أبو نُعَيم، أحمدُ بنُ عبدِ اللهِ بنِ أحمد بن إسحاقَ بنِ موسى بن مهران، الأصبهاني الحافظ المشهور، الصوفيُّ، الأحول، سبطُ الزاهد محمد بن يوسف البنَّاء، وصاحب \"الحِلْية\". وُلِدَ سنة ست وثلاثين وثلاثمِئَة. كان أبوه من عُلَماءِ الحديثِ والرحَّالين، من أعلامِ المحدِّثين وأكابِرِ الثقاتِ الحُفَّاظ، رحلَ إلى العراقِ والحجاز وأصفهان، قال أحمدُ بنُ محمد بن مردوي"},{"id":1491,"era":"c5","t":"دخول السلاجقة في الإسلام .","s":"كان جَدُّ السلاجقةِ بغاق من مشايخِ التُّركِ القُدَماء، الذين لهم رأيٌ ومَكيدة ومكانةٌ عند مَلِكهم الأعظَم، ونشأ ولدُه سلجوق نجيبًا شَهمًا، فقَدَّمه المَلِك ولقَّبه شباسي، فأطاعَتْه الجيوشُ وانقاد له النَّاسُ بحيث تخوَّفَ منه المَلِك وأراد قَتْلَه، فهرب منه إلى بلادِ المسلمين، فلمَّا خالط المسلمينَ أسلم فازداد عِزًّا وعلُوًّا، ثم توفِّيَ عن مِئَة وسبع سنين، وخلَّف من الأبناء أرسلان وميكائيل وموسى، "},{"id":1492,"era":"c5","t":"الملك مسعود الغزنوي يَهزم الملك طغرلبك السلجوقي .","s":"في صَفَر مِن هذه السنة وصَلَ المَلِك مسعود إلى بلْخ من غزنة، فجمع أصحابَه، ولقِيَ إسماعيلَ شاه مَلِكَ خوارزم، وقاتله، ودامت الحربُ بينهما مُدَّةَ شَهر، وانهزم إسماعيلُ، والتجأ إلى طغرلبك وأخيه داود السلجقيَّة، ثم سار مسعودُ بن سبكتكين من بلخ بنفسِه، وقصد سرخس، فتجَنَّب الغزُّ لقاءه، وعدلوا إلى المُراوغة والمُخاتلة، وأظهر الغُزُّ العزمَ على دخول المفازة التي بين مروٍ وخوارزمَ، فبينما عساكِرُ مسعودٍ"},{"id":1493,"era":"c5","t":"ما جرى بعُمان بعد موت أبي القاسم بن مكرم .","s":"لَمَّا توفِّيَ أبو القاسمِ بنُ مكرم صاحِبُ عُمان خلَّف أربعةَ بنينَ، وهم أبو الجيش، والمهذَّب، وأبو محمد، وآخرُ صغيرٌ، فوَلِيَ بعده ابنُه أبو الجيش، وأقَرَّ عليَّ بن هطال المنوجاني، صاحِبَ جيش أبيه، وكان المهذَّب، يَطعنُ على ابنِ هطال، وبلغه ذلك، فأضمَرَ له سوءًا، فجهَّزَ له مكيدةً وجعله يكتُبُ بخَطِّه ما أظهَرَه ابنُ هطال عند أبي الجيش، وقال له: إنَّ أخاك كان قد أفسد كثيرًا من أصحابِك عليك، وتحَد"},{"id":1494,"era":"c5","t":"شغب الأتراك على جلال الدَّولة البويهي .","s":"شَغبَ الأتراكُ على الملك جلال الدَّولة البويهي ببغداد، وأخرجوا خيامَهم إلى ظاهِرِ البلد، ثمَّ أوقعوا النَّهبَ في عِدَّةِ مواضِعَ، فخافهم جلالُ الدَّولة، فغَيَّرَ خيامَه إلى الجانبِ الغربيِّ، وتردَّدَت الرسُلُ بينهم في الصُّلحِ، وأراد الرَّحيلَ عن بغداد، فمنَعَه أصحابُه، فراسل دبيس بن مزيد، وقرواشًا صاحِبَ الموصل، وغيرهما، وجمع عنده العساكِرَ، فاستقَرَّت القواعِدُ بينهم وعاد إلى داره، وطَمِعَ الأتر"},{"id":1495,"era":"c5","t":"وفاة محمد بن حسن بن الهيثم  .","s":"هو الفيلسوفُ أبو عليٍّ محمَّدُ بنُ الحَسَن بن الهيثم البصري أصلُه بصري، سكن الديارَ المصريَّةَ إلى أن مات. كان من أذكياءِ بني آدم، عديمَ النظيرِ في عَصرِه في العلمِ الرياضي. وكان متزهِّدًا زُهدَ الفلاسفة. لخَّص كثيرًا من كتُبِ جالينوس، وكثيرًا مِن كتب أرسطوطاليس. وكان رأسًا في أصول الطبِّ وكليَّاتِه. وكان قد وَزَر في أوَّل أمرِه، ثمَّ تزهَّد وأظهر الجنونَ، وكان مليحَ الخطِّ يَنسَخُ في بعضِ السَّنة"},{"id":1496,"era":"c5","t":"انتصار السلاجقة على جيش الدَّولة الغزنوية في معركة دندانكان .","s":"انتصرَ السُّلطانُ السلجوقيُّ طغرلبك على جيشِ الدَّولة الغزنويَّة في معركةِ دندانكان، واستولى على خراسان، وأجبَرَ الغزنويِّينَ على الاعترافِ بالدَّولة السلجوقيَّةِ كأكبَرِ وأقوى دولةٍ في المنطقةِ."},{"id":1497,"era":"c5","t":"ابتداء ملك السلاجقة .","s":"عَظُمَ شأنُ السلجوقيَّة، وارتفع شأنُ مَلِكِهم طغرلبك، وأخيه داود، وهما ابنا ميكائيلَ بنِ سلجوق بن بغاق، بعد أن أسلموا ووالاهم من أسلَمَ مِن التُّركِ فأخذوا بلاد خراسانَ بكمالها بعد موتِ محمودِ بنِ سبكتكين، وقد كان يتخَوَّف منهم محمود بعضَ التخَوُّف، فلمَّا مات وقام ولَدُه مسعودٌ بعده قاتَلَهم وقاتلوه مرارًا، فكانوا يَهزِمونَه في أكثَرِ المواقف، واستكمل لهم مُلكُ خراسان بأسرِها، وكَمَل لهم جميعُ ما"},{"id":1498,"era":"c5","t":"مقتل الملك مسعود الغزنوي وتولي أخيه محمد من بعده .","s":"سار مسعودٌ يريدُ بلادَ الهندِ لِيشْتُوا بها، فلمَّا سار أخَذَ معه أخاه محمَّدًا مسمولَ العينينِ، واستصحَبَ الخزائِنَ، وكان عازمًا على الاستنجادِ بالهندِ على قتال السلجوقيَّة ثِقةً بعهودهم. فلمَّا عَبَرَ سيحون- وهو نهرٌ كبيرٌ نحو دِجلة- وعبَرَ بعض الخزائِنِ، اجتمع أنوشتكين البلخي وجمعٌ من الغلمانِ الداريَّةِ ونهبوا ما تخلَّفَ من الخزانةِ، وأقاموا أخاه محمَّدًا 13 ربيع الآخر، وسَلَّموا عليه بالإمارة"},{"id":1499,"era":"c5","t":"قتال الروم مع عساكر مصر .","s":"كان مَلِكُ الرومِ قد هادنَه المُستَنصِرُ بالله الفاطميُّ صاحِبُ مصر، ثمَّ أخذ يراسِلُ ابنَ صالحِ بن مرداس ويستميلُه، وراسله قبله صالحٌ ليتقَوَّى به على الدزبري صاحب دمشق للفاطميين؛ خوفًا أن يأخُذَ منه الرقَّةَ، فبلغ ذلك الدزبري فتهَدَّد ابنَ صالح فاعتذر وجَحَد، ثمَّ إنَّ جمعًا من بني جعفرِ بنِ كلاب دخلوا ولايةَ أفامية، فعاثوا فيها، ونهَبوا عدَّةَ قُرًى، فخرج عليهم جمعٌ مِن الروم فقاتَلوهم وأوقعوا "},{"id":1500,"era":"c5","t":"طغرلبك السلجوقي يسيطر على مدينة جرجان وطبرستان .","s":"ملَكَ طغرلبك السلجوقي جرجان وطبرستان، وسبَبُ ذلك أنَّ أنوشروان ابنَ منوجهر بن قابوس بن وشمكير صاحبها، قبض على أبي كاليجار بن ويهان القوهي، صاحِبِ جيشِه، وزَوجِ أمِّه بمساعدةِ أمِّه عليه، فعَلِمَ حينئذ طغرلبك أنَّ البلادَ لا مانع له عنها، فسار إليها، وقصَدَ جرجان ومعه مرداويج بن بسو، فلمَّا نازلها فتح له المقيمُ بها، فدخلها وقرَّرَ على أهلِها مِئَة ألف دينار صُلحًا، وسَلَّمَها إلى مرداويج بن بسو، و"},{"id":1501,"era":"c5","t":"معز الدَّولة الكلابي ينتزع الشام من يد العبيديين (الفاطميين) .","s":"فسَدَ أمرُ أنوشتكين الدزبري، نائبِ المستنصِرِ بالله الفاطميِّ، صاحِبِ مصر، بالشَّام، وكان الوزيرُ أبو القاسم الجرجرائي يقصِدُه ويَحسدُه، إلَّا أنَّه لا يجِدُ طريقًا إلى الوقيعةِ فيه، وأحسَّ الدزبري بما يجري، فأظهر ما في نفسِه، وأحضر نائبَ الجرجرائي عنده، وأمر بإهانتِه وضَرْبِه، ثمَّ إنه أطلق لطائفةٍ مِن العسكَرِ يَلزَمونَ خِدمَتَه أرزاقَهم، ومنع الباقينَ، فحَرَّك ما في نُفوسِهم، وقوِيَ طَمَعُهم في"},{"id":1502,"era":"c5","t":"وفاة حمزة الزوزني كبير مؤسسي الدعوة الدرزية .","s":"هو حَمزةُ بنُ عليِّ بنِ أحمد الفارسي الزوزني، مِن كبارِ الباطنيَّة، ويُعتبَرُ مُؤَسِّسَ المذهَبِ الدرزي وواضِعَ أُسُسِه وعقائِدِه، اتَّصَل بمصرَ برجالِ الدعوة السِّرِّية من شيعة الحاكِمِ بأمر الله الفاطمي العُبَيدي، نادى بالتقَمُّص والحلول مع محمد بن إسماعيلَ الدرزي، أظهر الدعوةَ بألوهيَّةِ الحاكم وأنَّ الإلهَ قد حلَّ فيه، جعله الحاكِمُ داعيَ الدُّعاة، ولَمَّا قُتِلَ الحاكِمُ غادر حمزةُ مصر إلى ال"},{"id":1503,"era":"c5","t":"استيلاء طغرلبك على البلدان الشرقية خوارزم وما جاورها .","s":"سار طغرلبك إلى خوارزم فحصرها وملكها واستولى عليها، وانهزم شاه ملك بين يديه، واستصحَبَ أموالَه وذخائِرَه، ومضى في المفازةِ إلى دهستان، ثم انتَقَل عنها إلى طبس، ثمَّ إلى أطراف كرمان، ثمَّ إلى عمال التيز ومكران، فلمَّا وصَلَ إلى هناك عَلِمَ خلاصَه ببُعدِه، وأمِنَ في نفسه، ثمَّ خرجَ طغرلبك من خراسانَ إلى الريِّ بعد فراغِه مِن خوارزم، وجرجان، وطبرستان، فلمَّا سَمِعَ أخوه إبراهيمُ ينال بقدومِه سار إليه "},{"id":1504,"era":"c5","t":"خلاف بين الخليفة القائم بأمرِ الله وجلال الدَّولة البويهي .","s":"افتُتِحَت الجوالي –أموال الجزية- في المحَرَّم ببغداد، فأنفذ الملِكُ جلال الدَّولة البويهي فأخذ ما تحصَّلَ منها، وكانت العادةُ أن يُحمَلَ منها إلى الخُلفاءِ لا تُعارِضُهم فيها الملوك، فلمَّا فَعَل جلالُ الدَّولة ذلك، عَظُمَ الأمرُ فيه على القائِمِ بأمرِ الله واشتَدَّ عليه، وأرسَلَ مع أقضى القُضاة أبي الحسن الماوَردي في ذلك، وتكَرَّرت الرَّسائلُ، فلم يُصْغِ جلالُ الدَّولة لذلك، وأخذ الجواليَ، فجمع ا"},{"id":1505,"era":"c5","t":"خروج رجل بمصر ادعى أنه الحاكم بأمر الله .","s":"خرج بمِصرَ إنسانٌ اسمُه سكين وقيل سُليمان، كان يُشبِهُ الحاكِمَ صاحِبَ مِصرَ، فادَّعى أنَّه الحاكِمُ، وقد رجعَ بعد موتِه، فاتَّبَعه جمعٌ مِمَّن يعتَقِدُ رَجعةَ الحاكِمِ، فاغتنموا خُلوَّ دار الخليفةِ بمصرَ مِن الجند وقصَدوها معه نِصفَ النَّهار، فدخلوا الدهليز، فوثَبَ من هناك من الجندِ، فقال لهم أصحابُه: إنَّه الحاكِمُ، فارتاعوا لذلك، ثمَّ ارتابوا به، فقَبَضوا عليه، واقتَتلوا، فتراجع الجندُ إلى القص"},{"id":1506,"era":"c5","t":"قتال بين مودود الغزنوي وعسكر ألب أرسلان السلجوقي .","s":"سيَّرَ المَلِكُ أبو الفتح مودود بنُ مسعود بن سبكتكين عَسكَرًا مع حاجِبٍ له إلى نواحي خراسان، فأرسل إليهم داود أخو طغرلبك- وهو صاحِبُ خراسان- ولَدَه ألب أرسلان في عسكرٍ، فالتَقَوا واقتتلوا فكان الظَّفَرُ للمَلِك ألب أرسلان، وعاد عسكَرُ غزنة مُنهَزمًا، وفي صَفَر سار جمعٌ مِن الغز إلى نواحي بست، وفعلوا ما عُرِفَ منهم من النَّهبِ والشَّرِّ، فسَيَّرَ إليهم أبو الفتح مودود عسكرًا، فالتَقَوا بولاية بست، "},{"id":1507,"era":"c5","t":"مودود الغزنوي يهزم الهنود ويتملك عدة حصون .","s":"اجتمع ثلاثةُ مُلوكٍ مِن ملوك الهند، وقَصَدوا لاهور وحَصَروها، فجمع مُقَدَّم العساكر الإسلامية بتلك الديار مَن عندَه منهم، وأرسل إلى صاحِبِه مودود يستنجِدُه، فسَيَّرَ إليه العساكِرَ فاتَّفَقَ أنَّ بعض أولئك الملوك فارَقَهم وعاد إلى طاعةِ مودود، فرحل الملكانِ الآخران إلى بلادِهما، فسارت العساكرُ الإسلاميَّة إلى أحدهما، ويُعرَفُ بدوبال هرباته، فانهزم منهم، وصَعِدَ إلى قلعةٍ له منيعةٍ هو وعساكِرُه، فا"},{"id":1508,"era":"c5","t":"إخراج المسلمين والنصارى من القسطنطينية .","s":"وقع خبَرٌ بالقُسْطَنطينيَّة أنَّ قُسْطَنطين قتَلَ ابنَتَي الملك اللَّتين قد صار المُلكُ فيهما, فاجتمَعَ أهل البلد وأثاروا الفتنةَ، وطَمِعوا في النَّهبِ، فأشرف عليهم قُسْطَنطين، وسألهم عن السَّبَبِ في ذلك، فقالوا: قتلْتَ الملِكَتَين، وأفسَدْتَ المُلْكَ، فقال: ما قتَلْتُهما، وأخرَجَهما حتى رآهما النَّاسُ، فسكنوا، ثمَّ إنَّه سأل عن سبب ذلك، فقيل له: إنَّه فِعلُ الغُرَباءِ، وأشاروا بإبعادِهم، وأَمَرَ "},{"id":1509,"era":"c5","t":"المعز بن باديس يظهر الولاء للعباسيين واستقلاله عن الفاطميين .","s":"أظهَرَ المُعِزُّ بنُ باديس صاحِبُ إفريقيَّةَ الدُّعاءَ للدَّولةِ العباسيَّة، وخطب للإمامِ القائِمِ بأمرِ الله، أميرِ المؤمنين، وورَدَت عليه الخِلَعُ والتقليدُ ببلادِ إفريقيَّةَ وجميعِ ما يفتَحُه، وأُرسِلَ إليه سيفٌ وفَرَسٌ وأعلامٌ على طريقِ القُسطَنْطينيَّة، فوصل ذلك يومَ الجمعة، فدُخِلَ به إلى الجامِعِ، والخطيبُ ابنُ الفاكاة على المنبر يخطُبُ الخُطبةَ الثانيةَ، فدخلت الأعلامُ، فقال: هذا لواءُ الح"},{"id":1510,"era":"c5","t":"إسلام الترك بما وراء النهر .","s":"أسلَمَ مِن كُفَّارِ التُّركِ الذين كانوا يَطرُقونَ بلاد الإسلامِ بنواحي بلاساغون وكاشغر، ويُغيرون ويَعيثونَ، عشرةُ آلافِ خركاة، وضَحَّوا يومَ عيد الأضحى بعشرين ألفَ رأس غنم، وكفى اللهُ المسلمينَ شَرَّهم، وكانوا يصيِّفونَ بنواحي بلغار، ويَشتُون بنواحي بلاساغون، فلما أسلموا تفَرَّقوا في البلادِ، فكان في كُلِّ ناحيةٍ ألفُ خركاة، وأقَلُّ وأكثَرُ لأمنِهم؛ فإنَّهم إنما كانوا يجتَمِعونَ ليحميَ بَعضُهم بع"},{"id":1511,"era":"c5","t":"الحرب بين الروم والروس .","s":"ورد إلى القُسطَنطينية عددٌ كثيرٌ مِن الرُّوسِ في البحر، وراسَلوا قسطنطين مَلِكَ الروم بما لم تجْرِ به عادتُهم، فاجتمعت الرومُ على حَربِهم، وكان بعضُهم قد فارق المراكِبَ إلى البَرِّ، وبعضُهم فيها، فألقى الرومُ في مراكِبِهم النَّار، فلم يهتدوا إلى إطفائها، فهلك كثيرٌ منهم بالحَرْق والغَرَق، وأمَّا الذين على البَرِّ فقاتلوا، وصَبَروا، ثم انهزموا، فلم يكن لهم ملجأٌ، فمن استسلم أولًا استُرِقَّ وسَلِمَ،"},{"id":1512,"era":"c5","t":"وفاة جلال الدَّولة البويهي الشيعي وتولي أبي كاليجار بعده .","s":"هو صاحِبُ العِراقِ، المَلِك جلالُ الدَّولة، أبو طاهر بن بهاء الدَّولة بن عضد الدَّولة بن ركن الدَّولة بن بُوَيه، الديلمي. تمَلَّك سبع عشرة سنة، وكانت دولتُه ليِّنةً، وتمَلَّك بعده ابنُه المَلِك العزيزُ أبو منصور، فكانت أمورُه واهيةً كأبيه. وكان جلالُ الدَّولة شيعيًّا كأهلِ بَيتِه وفيه جُبنٌ، وعَسكَرُه مع قِلَّتِهم طامعون فيه. عاش نيفًا وخمسين سنة، وذاق نكدًا كثيرًا, وإنما كان سلطانَ العَصرِ ابنُ س"},{"id":1513,"era":"c5","t":"وفاة الإمام أبي ذر الهروي .","s":"هو الحافِظُ الإمامُ المُجَوِّد العَلَّامة شيخُ الحرم: أبو ذر عبدُ اللهِ بنُ أحمدَ بنِ مُحمَّد بن عبد الله بن غفير بن محمد، الأنصاريُّ الخُراساني الهَرَوي المالكي، صاحِبُ التصانيفِ، وراوي الصَّحيحِ عن الثلاثة: المستملي، والحَمَوي، والكشميهني. وُلِد سنة 355. سمع الكثيرَ ورحل إلى الأقاليم، وسكن مكَّة، ثمَّ تزوَّجَ في العرب، وكان يحُجُّ كلَّ سنة ويقيمُ بمكَّةَ أيَّام الموسم ويسمعُ النَّاس، ومنه أخذَ ا"},{"id":1514,"era":"c5","t":"القضاء على الإسماعيلية في بلاد ما وراء النهر .","s":"قصَدَ نَفَرٌ مِن الإسماعيليَّةِ ما وراء النَّهرِ، ودعوا إلى طاعةِ المستنصِرِ بالله الفاطميِّ صاحبِ مِصرَ، فتَبِعَهم جمعٌ كثير وأظهروا مذاهِبَ أنكرها أهلُ تلك البلاد، وسَمِعَ ملكها بغراخان خبَرَهم، وأراد الإيقاعَ بهم، فخاف أن يسلَمَ منه بعضُ من أجابَهم من أهل تلك البلاد، فأظهر لبَعضِهم أنَّه يميلُ إليهم، ويريدُ الدخولَ في مذاهِبِهم، وأعلَمَهم ذلك، وأحضَرَهم مجالِسَه، ولم يزَلْ حتى عَلِمَ جميعَ مَن "},{"id":1515,"era":"c5","t":"وفاة أبي القاسم الجرجرائي .","s":"هو الوزيرُ الكامِلُ نجيب الدَّولة، أبو القاسِمُ علي بن أحمد الجرجرائي، وزيرُ الديار المصريَّة للظاهِرِ العُبَيدي، وكان مِن دُهاة الملوك، خدم الحاكِمَ، فغَضِبَ عليه، فقطع يديه مِن مِرفَقَيه في سنة 404؛ لكونه خان في مباشرةِ الديوان، ثمَّ رَضِيَ عنه في سنة 409، فولَّاه ديوان النَّفَقات، ثم عَظُمَ أمرُه إلى أن وزَرَ في سنة 418 للظاهِرِ بنِ الحاكم. وهو مقطوعُ اليدينِ مِن المرفقين، فاستمَرَّ في الوزارة "},{"id":1516,"era":"c5","t":"الخطبة للملك أبي كاليجار البويهي وإصعاده إلى بغداد .","s":"لَمَّا توفِّي المَلِكُ جلال الدَّولة، راسل الجندُ، الملكَ أبا كاليجار مرزبان بنَ سلطان الدَّولة البويهي وخَطَبوا له. فلمَّا استَقَرَّت القواعِدُ بينه وبينهم أرسل أموالًا فُرِّقَت على الجُندِ ببغداد، وعلى أولادهم، وأرسل عشرةَ آلاف دينار للخليفةِ ومعها هدايا كثيرة، فخطبَ به ببغداد في صفر، وخَطَب له أيضًا أبو الشوك في بلادِه، ودبيس بن مزيد ببلادِه، ونصر الدَّولة بن مروان بديار بكرٍ، ولَقَّبَه الخليفة"},{"id":1517,"era":"c5","t":"وفاة الشريف المرتضى .","s":"هو أبو القاسِمِ عليُّ بنُ الحُسَين بن موسى بن محمد بن موسى الكاظم بن جعفر الصادق بن محمد الباقر بن علي زين العابدين بن الحسين بن علي بن أبي طالب، الشَّريفُ الموسويُّ، المُلَقَّب بالمرتضى، ذي المجدين، كان نقيبَ الطالبيِّينَ وكان إمامًا في عِلمِ الكلامِ والأدبِ وجيد الشعر. وُلِدَ سنة 355, وكان أكبَرَ مِن أخيه ذي الحَسَبين الشريف الرضي، كان على مذهَبِ الإماميَّةِ والاعتزال، يُناظِرُ على ذلك، وكان يُن"},{"id":1518,"era":"c5","t":"وفاة أبي الحسين محمد بن علي الطيب البصري شيخ المعتزلة .","s":"هو أبو الحُسَين محمَّد بن علي بن الطيب البصري المتكلِّم، صاحِبُ التَّصانيفِ الكلاميَّة، شيخُ المعتزلة والمُنتَصِر لهم، والمحامي عن ذمِّهم بالتصانيفِ الكثيرة، كان فصيحًا بليغًا، عَذْبَ العبارة، يتوقَّدُ ذَكاءً, وله اطِّلاعٌ كبير. توفِّيَ ببغداد بعد أن شاخ عُمُرُه, وصلَّى عليه القاضي أبو عبد الله الصيمري، ودُفِنَ في الشونيزي، ولم يَرْوِ من الحديثِ سوى حديثٍ واحدٍ، هو \"إنَّ ممَّا أدرك النَّاس مِن كلا"},{"id":1519,"era":"c5","t":"تملك السلاجقة لبلاد الجبل والدينور .","s":"أمر السُّلطانُ طغرلبك السلجوقيُّ أخاه إبراهيم ينال بالخروجِ إلى بلد الجَبَل وملكها، فسار إليها من كرمان، وقصد همذان، وبها كرشاسف بن علاء الدَّولة، ففارقها خوفًا، ودخلها ينال فمَلَكها، والتحَقَ كرشاسف بالأكراد الجوزقان، وكان أبو الشوك حينئذ بالدينورِ، فسار عنها إلى قرميسين خَوفًا وإشفاقًا مِنْ ينال، فقَوِيَ طَمَعُ ينال حينئذ في البلادِ، وسار الدينور فمَلَكَها ورتَّبَ أمورَها، وسار منها يطلُبُ قرميس"},{"id":1520,"era":"c5","t":"أبو كاليجار سلطان الدَّولة البويهي يتجهز لقتال السلاجقة السنة .","s":"لما رأى أبو كاليجار البويهيُّ الشيعيُّ- وكان بخوزستان- ما تمَلَّكه السَّلاجقةُ مِن الجَبَل والدينور، وأصبح شأنُهم في علوٍّ وقوَّةٍ، تَجهَّزَ لقتال السلاجقةِ الذين تعَدَّوا على أتباعِه، فلم يمكِنْه ذلك لقِلَّةِ الظهر، وذلك أنَّ الآفةَ اعتَرَت في هذه السَّنةِ الخيلَ، فمات له فيها نحوٌ مِن اثني عشر ألفَ فَرَس، بحيث جافَت بغدادُ مِن جِيَف الخَيلِ."},{"id":1521,"era":"c5","t":"مهلهل بن عناز يسيطر على مدينتي قرميسين والدينور بإيران .","s":"مَلَكَ مُهلهَل بن محمد بن عناز مدينة قرميسين والدينور، وسبَبُ ذلك أنَّ إبراهيمَ ينال السلجوقي كان قد استعمل عند عودِه من حلوان على قرميسين بدرَ بنَ طاهر بن هلال، فلما ملَكَ مُهلهَل بعد موت أخيه أبي الشوك الذي كان يحكُمُ الدينور، سار إلى مايدشت، ونزل بها ثم توجَّهَ نحو قرميسين، فانصرَفَ عنها بدر فملكها مهلهل، وسيَّرَ ابنه محمدًا إلى الدينور، وبها عساكِرُ ينال، فاقتتلوا، فقُتِلَ بين الفريقينِ جماعة،"},{"id":1522,"era":"c5","t":"طغرلبك السلجوقي يحاصر مدينة أصبهان .","s":"حصر طغرلبك مدينة أصبهان، وبها صاحِبُها أبو منصور فرامرز بن علاء الدَّولة، فضَيَّق عليه، ولم يظفَرْ من البلد بطائل، ثمَّ اصطلحوا على مالٍ يحملُه فرامرز بن علاء الدَّولة لطغرلبك، وخطب له بأصبهان وأعمالِها."},{"id":1523,"era":"c5","t":"أبناء أمير سرقسطة بالأندلس يتنازعون السلطة بعد وفاة والدهم .","s":"توفِّيَ سُلَيمانُ بنُ هود المستعين أميرُ سرقسطة ولاردة والثغر الأعلى، وكان قبل موته قد قسمَ سرقسطة بين أولادِه فخَصَّ أحمد بولاية سرقسطة العاصمة، وخَصَّ يوسُفَ بلاردة، وخَصَّ لب بوشقة، وخص المنذر بتطيلة، وخص محمدًا بقلعة أيوب، ثمَّ بعد وفاته تنازع الإخوةُ فيما بينهم، فقام أحمد الذي لَقَّبَ نفسَه بالمقتَدِر وانتزع مِن لب والمنذر ومحمَّد ما بأيديهم واستولى على مدُنِهم بعد أن سجَنَهم وسمَلَ أعينَهم، "},{"id":1524,"era":"c5","t":"وفاة الشيخ أبي محمد (الجويني) .","s":"هو الشَّيخُ أبو محمَّد الجُوَينيُّ إمامُ الشافعيَّة عبد الله بن يوسف بن محمد بن حيويه الجويني الطَّائي السنبسي، كان فقيهًا مُدَقِّقًا مُحَقِّقًا، نحويًّا مفسِّرًا، وهو والد إمامِ الحَرَمين، وأصلُه من قبيلة يقال لها سنبس، وجُوَين من نواحي نيسابور، سمِعَ الحديث من بلادٍ شَتَّى على جماعة، وقرأ الأدبَ على أبيه، وتفَقَّه بأبي الطيِّبِ سهلِ بنِ محمد الصعلوكي، ثمَّ خرج إلى مروٍ إلى أبي بكر عبدِ الله بن أ"},{"id":1525,"era":"c5","t":"وفاة عبد الله بن قحطان آخر حكام بني يعفر وقيام الدولة الصليحية .","s":"مع وفاةِ عبدِ اللهِ بنِ قَحطانَ آخِرِ حُكَّامِ بَني يَعفُرَ، انتَهى حُكمُهم، وظلَّت البِلادُ في حالةِ فَوضى سياسيةٍ، إلى أنْ جاء إلى الحُكمِ بنو الصُّلَيحيِّ عامَ 1047م/439هـ. ومِن أبرَزِ حُكَّامِ هذه الأُسرةِ الملكةُ الحُرَّةُ أرْوى بِنتُ الصُّلَيحِ. وظلت البِلادُ مُنقَسمةً على بَعضِها، وفي هذا العَصرِ جاءَ سَلاطِنةُ هَمَدانَ لتوَلِّي السُّلطةِ في صَنعاءَ عامَ 1088م/481هـ، واستَمرَّت السُّلطةُ تن"},{"id":1526,"era":"c5","t":"مسير إبراهيم ينال السلجوقي إلى قلعة كنكور .","s":"سار إبراهيم ينال إلى قلعة كنكور، وبها عكبر بن فارس- صاحِبُ كرشاسف بن علاء الدَّولة- يحفَظُها له، فامتنع عكبر بها إلى أن فَنِيَت ذخائره، وكانت قليلةً، فلمَّا نَفِدَت الذخائِرُ عَمِلَ حيلة وطلب الأمانَ على تسليمِ القلعةِ، ثمَّ لَمَّا تسلَّمَها إبراهيمُ، صَعِدَ إلى القلعة فانكشفت الحيلة، فسار عكبر بمن معه إلى قلعة سرماج، وصَعِدَ إليها، ولَمَّا ملك ينال كنكور عاد إلى همذان، فسَيَّرَ جيشًا لأخذ قلاعِ س"},{"id":1527,"era":"c5","t":"الأصفر التغلبي يغزو بلاد الروم .","s":"ظهر الأصفَرُ التغلبيُّ برأس عين -مدينة سورية تقع على الحدود التركية السورية-، وادَّعى أنَّه من المذكورينَ في الكتب، واستغوى قومًا بمَخاريقَ، وجمع جمعًا وغزا نواحيَ الروم، فظَفِرَ وغَنِمَ وعاد، وظهَرَ حَديثُه، وقوِيَ ناموسُه، وعاودوا الغزوَ في عدد أكثَرَ مِن العدد الأول، ودخل نواحيَ الروم وأوغل، وغَنِمَ أضعافَ ما غَنِمَه أولًا، وتسامع النَّاسُ به فقصدوه، وكثُرَ جَمعُه، واشتَدَّت شوكتُه، وثقُلَت على"},{"id":1528,"era":"c5","t":"الوباء والغلاء بالعراق .","s":"كان ببغداد والمَوصِل، وسائِرِ البلاد العراقيَّة والجزيرة، غلاءٌ عظيم، حتى أكَلَ النَّاسُ المَيتةَ، وتَبِعَه وَباءٌ شَديدٌ مات فيه كثيرٌ مِن الناس، حتى خَلَت الأسواق، وزادت أثمانُ ما يَحتاجُ إليه المرضى، كما حدث وباءٌ شديد بالعراق والجزيرة، بسبب جِيَفِ الدوابِّ التي ماتت، فمات فيها خلقٌ كثيرٌ، حتى خَلَت الأسواقُ وقَلَّت الأشياءُ التي يحتاجُ إليها المرضى."},{"id":1529,"era":"c5","t":"الصلح بين طغرلبك السلجوقي وأبي كاليجار سلطان الدَّولة البويهي .","s":"أرسل الملك أبو كاليجار البويهيُّ إلى السُّلطانِ رُكنِ الدين طغرلبك في الصُّلح، فأجابه إليه، واصطلحا، وكتَبَ طغرلبك إلى أخيه ينال يأمُرُه بالكَفِّ عَمَّا وراء ما بيده، واستقَرَّ الحالُ بينهما أن يتزوَّجَ طغرلبك بابنةِ أبي كاليجار، ويتزوَّج الأميرُ أبو منصور بن أبي كاليجار بابنةِ الملك داود أخي طغرلبك، وتمَّ العَقدُ."},{"id":1530,"era":"c5","t":"غزو إبراهيم ينال الروم .","s":"غزا الرُّومَ إبراهيم ينال أخو طغرل بك لأمه وأحد قادة السلاجقة، فظَفِرَ بهم وغَنِمَ، وكان سببُ ذلك أنَّ خلقًا كثيرًا من الغزِّ بما وراء النهر قَدِموا عليه، فقال لهم: بلادي تضيقُ عن مُقامِكم والقيامِ بما تحتاجون إليه، والرأيُ أن تَمضُوا إلى غَزوِ الروم، وتُجاهِدوا في سبيل الله، وتغنَموا، وأنا سائِرٌ على أثَرِكم، ومساعِدٌ لكم على أمْرِكم. ففعلوا، وساروا بين يديه، وتَبِعَهم، فوصلوا إلى ملازكرد، وأرزن "},{"id":1531,"era":"c5","t":"دولة بني مزين في الأندلس .","s":"لم يبقَ مِن إماراتِ الغَربِ بعد سُقوطِ لبلةَ وشلطيش وشنتمريَّة في يدِ المُعتَضِد بن عبَّاد سوى إمارةِ شلب، وكانت هذه الإمارةُ مِن أهَمِّ إماراتِ الغرب بعد إشبيليَّةَ وكانت تشمَلُ كورة شلب وكورة باجة، وكان الحاجِبُ عيسى بن محمد قد تغَلَّب في أعقابِ الفِتنةِ على هذه المنطقةِ النائيةِ وأقام بها دولةً، واستمَرَّ مُسيطرًا عليها حتى توفِّيَ سنة 432 هـ فخَلَفه في حُكمِها ولَدُه مُحمَّدُ بنُ عيسي الملقَّب"},{"id":1532,"era":"c5","t":"وفاة الملك أبي كاليجار البويهي الشيعي وولي بعده ابنه أبو نصر .","s":"هو السُّلطانُ صاحِبُ العراق، المَلِك أبو كاليجار المرزبان بنُ سلطان الدَّولة بن بهاء الدَّولة بن عضد الدَّولة بن بُوَيه الديلمي الشيعي. تمَلَّك بعد ابنِ عَمِّه جلال الدَّولة، وجرَت له خطوبٌ وحُروب، وعاش نيِّفًا وأربعين سنة، وقهر ابنَ عَمِّه الملك العزيز، توفِّيَ رابع جمادى الأولى، بمدينة جناب من كرمان، ولما توفِّيَ نَهَب الأتراكُ مِن العسكر الخزائِنَ والسلاحَ والدوابَّ، وكانت ولايتُه على العراق أر"},{"id":1533,"era":"c5","t":"محاصرة العساكر المصرية العبيدية مدينة حلب .","s":"وصلت عساكِرُ مِصرَ العُبَيديَّة إلى حَلَب في جمعٍ كثيرٍ فحَصَروها، وبها مُعِزُّ الدَّولة أبو علوان ثمال بن صالح الكلابي، فجمع جمعًا كثيرًا بلغوا خمسةَ آلاف فارس وراجل، فلمَّا نزلوا على حلب خرج إليهم ثمال وقاتلهم قِتالًا شديدًا صبَرَ فيه لهم إلى الليل، ثم دخل البلدَ، فلمَّا كان الغد اقتتلوا إلى آخِرِ النهار، وصبر أيضًا ثمال، وكذلك أيضًا اليوم الثالث، فلما رأى المصريُّونَ صَبْرَ ثمال، وكانوا يظنُّون"},{"id":1534,"era":"c5","t":"وفاة الفيلسوف المؤرخ الموسوعي البيروني .","s":"هو الفيلسوفُ المُنَجِّم مُحمَّد بنُ أحمد أبو الريحان البيروني الخوارزمي مُؤرخٌ مُحَقِّقٌ وجغرافيٌّ مُدقِّق، وفلَكيٌّ نابِهٌ، ورياضيٌّ أصيلٌ، وفيزيائيٌّ راسخٌ، ومترجِمٌ متمَكِّنٌ، مِن بلادِ السندِ، ومن أعيان الفلاسفة. عاصر الرَّئيسَ ابن سينا وجَرَت بينهما حوارات وأسئلةٌ وجوابات، وكان عالِمًا في الهيئة والنجوم، خبيرًا بالطبِّ. وُلد في بيرون إحدى ضواحي خوارزم، وهو مجهولُ النَسَب؛ فقد قال عن نفسِه في "},{"id":1535,"era":"c5","t":"الفتنة بين السنة والشيعة في الكرخ ببغداد .","s":"مُنِعَ أهلُ الكرخ في بغداد من النَّوحِ وفِعلِ ما جَرَت عادتُهم بفعله يومَ عاشوراء، فلم يَقبَلوا وفعلوا ذلك، فجرى بينهم وبين السُّنَّة فِتنةٌ عظيمة قُتِلَ فيها وجُرِحَ كثيرٌ من الناس، ولم ينفَصِل الشَّرُّ بينهم حتى عبَرَ الأتراك وضربوا خيامَهم عندهم، فكَفُّوا حينئذ، ثم شرع أهلُ الكرخ في بناء سورٍ على الكرخ، فلمَّا رآهم السنَّةُ من القلَّائين – صَنعَتُهم القَليُ- ومَن يجري مجراهم، شرعوا في بناءِ سُو"},{"id":1536,"era":"c5","t":"فتنة بين الملك طغرلبك وبين أخيه إبراهيم ينال .","s":"سببُ ذلك أنَّ طغرلبك طلَبَ مِن إبراهيم ينال أن يُسَلِّمَ إليه مدينة همذان والقلاعَ التي بيده من بلدِ الجبل، فامتنَعَ مِن ذلك، واتَّهَم وزيرَه أبا عليٍّ بالسعيِ بينهما في الفَسادِ، فقَبَض عليه، وأمَرَ به فضُرِبَ بين يديه، وسَمَل إحدى عينيه، وقطَعَ شَفَتَيه، فسار إلى طغرلبك، وجمع جمعًا مِن عَسكَرِه، والتقيا، وكان بين العسكرين قتالٌ شديدٌ انهزم ينال وعاد مُنهَزِمًا، فسار طغرلبك في أثَرِه، فملك قلاعَه"},{"id":1537,"era":"c5","t":"وفاة الحافظ أبي عبد الله محمد بن علي الصوري .","s":"هو الحافِظُ أبو عبد الله مُحمَّدُ بنُ عليِّ بنِ عبد الله بن محمد الصوري، أحَدُ علماء الحديثِ؛ طلب الحديثَ بنَفسِه على الكِبَرِ، ورحَلَ في طلبه إلى الآفاق. كان من أعظَمِ أهل الحديث هِمَّةً في الطلب وهو شابٌّ، ثم كان من أقوى النَّاسِ على العمَلِ الصالحِ عزيمةً في حالِ كِبَرِه. كان صوَّامًا يَسرِدُ الصومَ إلَّا يومَيِ العيدينِ وأيام التشريق، وكان مع ذلك حَسَن الخُلُق جميلَ المعاشرة، محبًّا للشِّعرِ، "},{"id":1538,"era":"c5","t":"وفاة مودود الغزنويّ وقيام عمه عبد الرشيد بالأمر بعده .","s":"هو أبو الفَتحِ مَودود بن مسعود بن محمود بن سبكتكين الغزنويُّ، صاحِبُ غزنة، لَمَّا ملَكَ مودودٌ قَبَض على عمِّه عبدِ الرَّشيدِ بنِ محمود وسَجَنَه في قلعة ميدين، بطريقِ بست، وكاتَبَ أصحابَ الأطرافِ ودعاهم إلى نُصْرَتِه، وبذل لهم الأموالَ والإمرةَ على بلادِ خُراسان فأجابوه، منهم: أبو كاليجار صاحِبُ أصبهان، فإنَّه سار بجيوشِه في المفازة فهلك كثيرٌ مِن عسكره، ومَرِضَ هو ورجع، ومنهم خاقان التُّرك فإنَّه"},{"id":1539,"era":"c5","t":"الخوارج يستولون على عمان .","s":"استولى الخوارجُ المُقيمونَ بجبال عُمان على مدينةِ الولاية، وسبَبُ ذلك أنَّ صاحِبَها الأمير أبا المُظَفَّر ابن الملك أبي كاليجار كان مُقيمًا بها، ومعه خادِمٌ له قد استولى على الأمورِ، وحَكَم على البلاد، وأساء السيرةَ في أهلها، فأخذ أموالَهم، فنفروا منه وأبغَضوه، وعَرَفَ إنسانٌ من الخوارجِ- يقالُ له ابنُ راشدٍ- الحالَ، فجمع مَن عنده منهم فقَصَد المدينةَ، فخرج إليه الأميرُ أبو المُظَفَّر في عساكِرِه،"},{"id":1540,"era":"c5","t":"محاولة المستنصر العبيدي الفاطمي استعادة نفوذه في إفْريقيَّة .","s":"لَمَّا قطَعَ المُعِزُّ بنُ باديس الخطبةَ للفاطميِّينَ وخطَبَ للعباسيِّينَ، وأعلن بذلك انشقاقَه عن الفاطميِّينَ وولاءَه للعباسيِّينَ، كاد له المستنصِرُ الفاطميُّ حاكِمُ مِصرَ لَمَّا عجز عنه بنَفسِه وجَيشِه عن قَهرِه، أرسل إليه جموعًا مِن العرب الهلاليَّة مِن بني زغبة ورياح، وهم بطونُ بني عدي الأثبج، وكانوا يسكُنونَ على الضَّفَّة الشرقيَّة من صعيد مصر بعد قُدومِهم من نجد، وكان المستنصِرُ قد عقد لرؤس"},{"id":1541,"era":"c5","t":"فَتحُ طُغرلبك بِلادَ أصبهان .","s":"كان أبو منصورِ بن عَلاءِ الدَّولةِ، صاحبُ أصبهان، غيرَ ثابتٍ على طَريقةٍ واحدةٍ مع السُّلطانِ طغرلبك، كان يُكثِر التَّلَوُّنَ معه، تارةً يُطيعُه ويَنحازُ إليه، وتارةً يَنحرِف عنه ويُطيعُ المَلِكَ الرَّحيمَ البويهي، فأضمر له طُغرلبك سُوءًا، فلما عاد من خُراسان لِأَخذِ البلادِ الجَبليَّةِ من أَخيهِ إبراهيمَ ينال، واستولى عليها عَدَلَ إلى أصبهان عازِمًا على أَخذِها من أبي منصورٍ، الذي سَمِع بالخبرِ، "},{"id":1542,"era":"c5","t":"استيلاءُ الغُزِّ السلاجقة على مَدينةِ فَسا .","s":"سار المَلِكُ أَلب أَرسلان بن داودَ ابن أخي طُغرلبك من مدينةِ مَرو بخُراسان، وقَصَد بِلادَ فارس في المَفازَة، فلم يَعلَم به أحدٌ، ولا أَعلَم عَمَّهُ طُغرلبك، فوَصَل إلى مَدينةِ فَسا، فانصرف النَّائِبُ بها من بين يديه، ودَخلَها أَلبُ أَرسلان فقَتَل من الدَّيلم بها ألفَ رَجُل، وعددًا كثيرًا من العامَّةِ، ونَهبوا ما قَدرُه ألف ألف دينار، وأسروا ثلاثةَ آلافِ إنسانٍ، وكان الأمرُ عظيمًا. فلمَّا فَرغوا من"},{"id":1543,"era":"c5","t":"فِتنةٌ عَظيمةٌ بين السُّنَّةِ والشِّيعَةِ ببغداد .","s":"تَجدَّدت الفِتنةُ ببغداد بين السُّنَّةِ والشِّيعَة، وعَظُمَت أضعافَ ما كانت عليه قديمًا، وكان سببُ هذه الفِتنَة أنَّ أهلَ الكَرخ عَمِلوا أَبراجًا كَتَبوا عليها بالذَّهَبِ: محمدٌ وعَلِيٌّ خَيرُ البَشَرِ. وأَنكرَ السُّنَّةُ ذلك، وادَّعوا أنَّ المكتوبَ: محمدٌ وعَلِيٌّ خَيرُ البَشَرِ، فمَن رَضِيَ فقد شَكَر، ومَن أَبَى فقد كَفَر. وأَنكَر أهلُ الكَرخ الزِّيادةَ وقالوا: ما تَجاوَزنا ما جَرَتْ به عادتُنا "},{"id":1544,"era":"c5","t":"ابن أبى كاليجار البويهي يسيطر على بلاد إصطخر وشيراز .","s":"سَيَّرَ المَلِكُ الرَّحيمُ ابن أبى كاليجار البويهي الشِّيعي أخاهُ الأميرَ أبا سعد في جَيشٍ إلى بلادِ فارس، وكان سببُ ذلك أنَّ المُقيمَ في قَلعةِ إصطخر، وهو أبو نصر بن خسرو، وكان له أَخَوان قَبَضَ عليهما هزارسبُ بن بنكير بِأَمْرِ الأَميرِ أبي منصور بن المَلِكِ أبي كاليجار، فكتَبَ إلى المَلِكِ الرَّحيم البويهي الشِّيعي يَبذُل له الطَّاعة والمُساعَدة، ويَطلُب أن يُسَيِّر إليه أخاهُ لِيُمَلِّكَهُ بلاد"},{"id":1545,"era":"c5","t":"وفاة صاحبِ المَوصِل أَميرِ بني عُقيلٍ، وقيام إمارة قُريشِ بن بَدران .","s":"زَعيمُ الدَّولة، أبو كامل، بَرَكَة بن المُقَلِّد، أميرُ بني عُقيلٍ، وصاحبُ المَوصِل بن المُسيبِ بن رافِع بن المُقلِّد بن جعفرِ بن عَمروِ بن المُهَنَّا بن عبدِ الرَّحمن بن بُرَيد -مُصغَّرًا- يَنتهِي إلى هوازن العُقَيلي، هو من بَيتٍ كَبيرٍ في الإمرَةِ. كان بَركةُ بن المُقلِّد قد غَلَب على المَوصِل وغَيرِها، وقَهَر أخاهُ قرواشا، وعاثَ وأَفسَد وعَسَف، وفي هذه السَّنَةِ انحدَر إلى تكريت في حُلَلِهِ قاص"},{"id":1546,"era":"c5","t":"أهل بغداد يقَدْحُون في نَسَبِ العُبيديِّين (الفاطميِّين) .","s":"عُمِلَ مَحضَرٌ ببغداد يتضمن القَدْحَ في نَسَبِ العَلويِّين أصحاب مصر، وأنهم كاذبون في ادعائهِم النَّسَبَ إلى عَلِيِّ بن أبي طالبٍ، وعَزُوهُم فيه إلى الدَّيْصانِيَّة مِن المَجوس، والقَدَّاحِيَّة مِن اليهود، وكَتَبَ فيه العَلويُّون، والعبَّاسِيُّون، والفُقهاء، والقُضاة، والشُّهود، وعُمِلَ به عِدُّة نُسَخٍ، وسُيِّرَ في البِلادِ، وشِيعَ بين الحاضرِ والبادي."},{"id":1547,"era":"c5","t":"وَفاةُ عبدِ الرَّشيد بن محمود بن سُبُكْتِكِين صاحب غَزْنَة .","s":"هو عبدُ الرَّشيد بن محمود بن سُبُكْتِكِين، مِن مُلوكِ الدَّولة الغَزْنويَّة، كان ابنُ أخيهِ مَوْدودُ بن مسعود قد حَبسَهُ في قَلعةِ ميدين، ولما تُوفِّي مَودود سنة 441هـ خَلَفَهُ وَلدٌ له، فبَقِيَ خَمسةَ أيَّامٍ ثم قَصدَ بعضُ النَّاسِ القَلعةَ وأَخرَجوا عبدَ الرَّشييد وبايعوه ودَخلوا معه غَزنَة، ولَقَّبوهُ شَمسَ دِين الله، وكان ضَعيفًا قَليلَ الحِيلَة، فلم يَطُل عَهدُه, فقد قَتلَهُ حاجبٌ لِمَودود اس"},{"id":1548,"era":"c5","t":"وُصولِ الغُزِّ السَّلاجِقَة إلى فارس وانهزامُهم عنها .","s":"وَصلَ أَصحابُ السُّلطان طُغرُلبك إلى فارس، وبلغوا إلى شيراز، ونزلوا بالبَيضاءَ، واجتمع معهم العادلُ أبو منصور الذي كان وزيرَ المَلِكِ أبي كاليجار، ودَبَّرَ أَمرَهم، فقَبَضوا عليه وأخذوا منه ثلاثَ قِلاعٍ، وهي: قَلعةُ كَبْزَة، وقَلعةُ جُوَيْم، وقَلعةُ بَهَنْدَر، فأقاموا بها، وسار مِن الغُزِّ نحو مائتي رَجُلٍ إلى الأَميرِ أبي سعدٍ، أخي المَلِكِ الرَّحيم، وصاروا معه، وراسَل أبو سعدٍ الذي بالقِلاعِ الم"},{"id":1549,"era":"c5","t":"ذِكرُ دُخولِ العَربِ إلى إفريقية بتَحريضٍ مِن حاكم مصر العُبيدِي\n  .","s":"في هذه السَّنَةِ دَخلتْ العَربُ إلى إفريقية, وسببُ ذلك أنَّ المُعِزَّ بن باديس كان خَطَبَ للقائم بأَمرِ الله الخليفة العبَّاسي، وقَطَع خُطبةَ المُستَنصِر العُبيدي الفاطمي صاحب مصر، فلمَّا فعل ذلك كَتَب إليه المُستَنصِر العَلويُّ يَتَهدَّدهُ، فأَغلظَ المُعِزُّ في الجوابِ، ثم شَرعَ المُستَنصِرُ ووَزيرهُ الحسنُ بن عَليٍّ اليازوري في إرسالِ العَربِ إلى أفريقية، وأصلحوا بني زُغْبَة ورِياحٍ، وكان بينهم "},{"id":1550,"era":"c5","t":"وَفاةُ أبي عَمرٍو الدَّاني .","s":"الإمامُ، الحافظُ، المُجَوِّدُ، المُقرِئُ، الحاذِقُ، عَالِمُ الأندلُس، أبو عَمرٍو عُثمانُ بن سَعيدِ بن عُثمان الدَّاني، المعروف بابنِ الصَّيْرَفِيِّ، وبأبي عَمرٍو الدَّاني، مالِكي المَذهَب، وُلِدَ سنة 371هـ بدأ بِطَلَبِ العِلمِ في قُرطبة سَنةَ 386هـ, ثم رَحلَ إلى المَشرِق وسَمِعَ الحَديثَ في القَيروان ومصر، وهو أَحدُ الأَئِمَّة في عِلمِ القُرآن رِواياتِه، وقِراءاتِه، وتَفسيرِه، ومَعانِيه، وطُرُقِه،"},{"id":1551,"era":"c5","t":"عَودةُ الفِتنَة بين السُّنَّةِ والشِّيعَة في الكَرخِ .","s":"زادت الفِتنةُ بين شِيعَةٍ مِن أَهلِ الكَرخِ وغَيرهِم مِن أَهلِ السُّنَّةِ، وكان ابتِداؤُها أواخرَ سَنَةِ أربعٍ وأربعين في ذي القعدة، فلمَّا كان الآن عَظُمَ الشَّرُّ، واطَّرَحَت المُراقبَة للسُّلطان، واختَلطَ بالفَريقينِ طوائفُ مِن الأتراكِ، فلمَّا اشتَدَّ الأمرُ اجتمع القُوَّادُ واتَّفَقوا على الرُّكوبِ إلى المَحالِّ، وإقامةِ السِّياسةِ بأهلِ الشَّرِّ والفَسادِ، وأَخَذوا مِن الكَرخِ إِنسانًا عَلوي"},{"id":1552,"era":"c5","t":"استِيلاءُ المَلِكِ الرَّحيم البُويهي الشِّيعي على أرجان .","s":"استولى المَلِكُ الرَّحيم البويهي  الدَّيلمي الشِّيعي على مَدينةِ أرجان، وأَطاعهُ مَن كان بها مِن الجُندِ، وكان المُقَدَّمُ عليهم فولاذ بن خُسرو الدَّيلمي، وكان قد تَغلَّب على جِوارِها مِن البِلادِ إِنسانٌ مُتَغَلِّبٌ يُسمَّى خشنام، فأَنفذَ إليه فولاذ جَيشًا فأَوقَعوا به وأَجْلَوْهُ عن تلك النَّواحي، واستَضافوا إلى طَاعةِ المَلِكِ الرَّحيم، وخاف هزارسب بن بنكير من ذلك لأنَّه كان مُبايِنًا للمَلِكِ "},{"id":1553,"era":"c5","t":"إِيقاعُ البساسيري بِقُطَّاعِ الطَّريقِ مِن الأَكرادِ والأَعرابِ .","s":"وَصلَ الخَبرُ إلى بغداد بأنَّ جَمْعًا من الأَكرادِ والأَعرابِ قد أَفسَدوا في البلادِ، وقَطَعوا الطَّريقَ، ونَهَبوا القُرى، طَمعًا في السَّلْطَنَةِ بسَببِ الغُزِّ، فسار إليهم البساسيري -وكان مملوكاً تركياً من مماليك بهاء الدولة بن عضد الدولة- وتَبِعَهُم إلى البَوازيج -بلد قُربَ تكريت-، فأَوقعَ بِطَوائفَ كَثيرةٍ منهم، وقَتَّلَ فيهم، وغَنِمَ أَموالَهم، وانهَزمَ بعضُهم فعَبَروا الزَّابَ عند البَوازيج "},{"id":1554,"era":"c5","t":"الأَميرُ أبو مَنصور البويهي  الشِّيعي يَستَولي على شيراز .","s":"عاد الأميرُ أبو منصور فولاستون ابن المَلِكِ أبي كاليجار البويهي  الدَّيلمي الشِّيعي إلى شيراز مُستَولِيًا عليها، وفارَقَها أخوهُ الأميرُ أبو سعدٍ، وكان سببُ ذلك أنَّ الأميرَ أبا سعدٍ كان قد تَقدَّم معه في دَولتِه إنسانٌ يُعرفُ بعَميدِ الدِّين أبي نصرِ بن الظَّهير، فتَحَكَّم معه، واطَّرحَ الأجنادَ واستَخَفَّ بهم، وأَوحشَ أبا نصرِ بن خسرو، صاحب قَلعةِ إصطخر، الذي كان قد استَدعَى الأميرَ أبا سعدٍ ومَ"},{"id":1555,"era":"c5","t":"غَزوُ السُّلطانِ طُغرلبك أذربيجان ثم الرُّومِ .","s":"سار طُغرلبك إلى أذربيجان، فقَصدَ تبريزَ، وصاحبُها الأميرُ أبو منصور وهسوذان بن محمد الرَّوادي، فأَطاعَه وخَطَب له وحَمَلَ إليه ما أَرضاهُ به، وأَعطاهُ وَلَدَهُ رَهينةً، فسار طُغرلبك عنه إلى الأميرِ أبي الأسوارِ، صاحبِ جنزة - بَلدَة من بلادِ أذربيجان- فأَطاعَهُ أيضًا وخَطَب له، وكذلك سائرُ تلك النَّواحي أَرسَلوا إليه يَبذُلون الطَّاعةَ والخُطبةَ، وانقادَت العَساكرُ إليه، فأَبقَى بِلادَهم عليهم، وأَ"},{"id":1556,"era":"c5","t":"مُعاهدةٌ بين العُبيديِّينَ الفاطِميِّينَ والرُّومِ .","s":"أُصيبَت مِصرُ بِقَحْطٍ شَديدٍ وغَلاءٍ شَديدٍ كاد يُهلِكُهم، فعَقدَ المُستنصِرُ الفاطِميُّ مع الإمبراطورِ البيزنطي قُسطنطين التاسِع مُعاهدةً مُوجِبُها أن يَمُدَّ الرُّومُ مِصرَ بالغِلالِ والأَقواتِ لِتَجاوُزِ المَجاعةِ التي حَلَّت بهم، لكنَّ إمبراطورَ الرُّومِ يَموتُ قبلَ الوَفاءِ بالمُعاهدةِ، ويَتولَّى أَمرَ الرُّومِ الإمبراطورة تيودورا فاشتَرطَت أن يَتَعهَّدَ الفاطِميونَ الدِّفاعَ عن الرُّومِ في "},{"id":1557,"era":"c5","t":"فِتنةُ الجُندِ الأَتراكِ ببغداد .","s":"كانت فِتنةُ الجُندِ الأَتراكِ ببغداد، وكان سَببُها أنهم تَخَلَّفَ لهم على الوزيرِ الذي للمَلِكِ الرَّحيم مَبلَغٌ كَثيرٌ مِن رُسومِهم، فطالبوهُ، وأَلَحُّوا عليه، فاختَفَى في دارِ الخِلافةِ، فحَضَر الأتراكُ بالدِّيوانِ وطالبوهُ، وشَكَوْا ما يَلقَوْنَه منه من المَطْلِ بمالِهم، فلم يُجابوا إلى إظهارهِ، فعَدَلوا عن الشَّكوَى منه إلى الشَّكوَى من الدِّيوان، وقالوا: إنَّ أربابَ المُعاملات قد سَكَنوا بالح"},{"id":1558,"era":"c5","t":"ابْتِداءُ الوَحشَةِ بين البساسيري التُّركي وبين الخَليفَةِ العبَّاسي .","s":"ابتَدأَت الوَحشةُ بين الخَليفةِ وأَرسِلان التُّركي المعروف بالبساسيري الذي قد عَظُمَ أَمرُه واستَفحَل، واستَولَى على البلادِ وطار اسمُه، وخافَتهُ أُمراءُ العَربِ والعَجَمِ، ودُعِيَ له على كَثيرٍ من المَنابِر العِراقيَّة والأهوازِ ونَواحِيها، ولم يكُن للخَليفَةِ قَطْعٌ ولا وَصْلٌ دُونَه، ثم صَحَّ عند الخَليفةِ سُوءُ عَقيدَتِه، وشَهِدَ عنده جَماعةٌ مِن الأَتراكِ أنَّه عازمٌ على نَهْبِ دارِ الخِلافَة"},{"id":1559,"era":"c5","t":"ابتِداءُ الوَحشَةِ بين الرُّومِ والعُبيدِيِّين (الفاطِميِّين) .","s":"كان القاضي أبو عبدِ الله القضاعي قد تَوَجَّه من عند المُستَنصِر حاكم مصر العُبيدي برِسالةٍ إلى مُتَمَلِّكِ الرُّومِ، فقَدِمَ وهو بالقُسطنطينيَّة رَسولُ السُّلطانِ طُغرلبك بن سلجوق يَلتَمِس من المَلِكَة تيودورا أن تُمَكِّنَ رَسولَه مِن الصَّلاةِ في جامعِ قُسطنطينيَّة، فأَذِنَت له في ذلك؛ فدَخلَ إليه وصَلَّى به، وخَطَبَ للخَليفةِ القائمِ بأَمرِ الله العبَّاسي. فبَعَثَ القَضاعيُّ بذلك إلى المُستنصِر،"},{"id":1560,"era":"c5","t":"استِيلاءُ المَلِكِ الرَّحيم البويهي  الشِّيعي على شيراز .","s":"سار قائدٌ كبيرٌ من الدَّيلمِ، يُسمَّى فولاذ، وهو صاحبُ قَلعةِ إصطخر، إلى شيراز، فدَخلَها وأَخرجَ عنها الأَميرَ أبا منصور فولاستون، ابنَ المَلِكِ أبي كاليجار، فقَصدَ فيروزآباذ وأَقامَ بها، وقَطعَ فولاذ خُطبةَ السُّلطانِ طُغرلبك في شيراز، وخَطبَ للمَلِكِ الرَّحيمِ، ولأَخيهِ أبي سعدٍ، وكاتَبَهُما يُظهِر لهُما الطَّاعةَ، فعَلِمَا أنَّه يَخدَعهُما بذلك، فسار إليه أبو سعدٍ، وكان بأرجان، ومعه عَساكرُ كثي"},{"id":1561,"era":"c5","t":"السلاجقة يدخلون العراقِ وانتهاءُ حُكمِ البُويهيِّين .","s":"كان سببُ ذلك أن أبا المُظفَّر أبا الحارث أرسلان التُّركي المعروف بالبساسيري كان قد عَظُمَ شَأنُه بالعراقِ، واستَفحَل أَمرُه، وبَعُدَ صِيتُه، وعَظُمَت هَيبتُه في النُّفوسِ، وخُطِبَ له على المنابرِ، وصار هو الكُلَّ، ولم يَبْقَ للمَلِكِ الرَّحيمِ ابن بُويه معه إلا مُجرَّد الاسمِ. ثم إنَّه بَلَغَ أَميرَ المؤمنين القائم أنَّ البساسيري قد عَزَمَ على نَهْبِ دارِ الخِلافَة والقَبضِ على الخَليفةِ، فكاتَبَ "},{"id":1562,"era":"c5","t":"الخَليفةُ العبَّاسي يَأمُر بِتلاوَةِ الخُطبةِ في بغداد للسُّلطانِ السلجوقي .","s":"أَمَرَ الخَليفةُ العبَّاسيُّ بِتلاوَةِ خُطبةِ الجُمعةِ في بغداد باسمِ السُّلطانِ السَّلجوقي طُغرل بك، وكان ذلك اعتِرافًا صَريحًا من العبَّاسيِّين بنُفوذِ السَّلاجِقَة في الخِلافَةِ العبَّاسيَّة."},{"id":1563,"era":"c5","t":"قِيامُ دَولَةِ المُرابِطينَ في المَغرِب وشَمالِ أفريقيا .","s":"كان ابتِداءُ أَمرِ المُلَثَّمِينَ، وهُم عِدَّةُ قَبائلَ يُنسَبون إلى حِمْيَر، أَشهرُها: لَمْتُونَة، ومنها أَميرُ المُسلمين يُوسف بن تاشفين، وجدالة ولمطة، وكان أوَّلُ مَسيرِهم مِن اليَمنِ، أيَّامَ أبي بكرٍ الصِّدِّيق رضي الله عنه، فسَيَّرَهُم إلى الشَّامِ وانتَقَلوا إلى مصر، ودَخَلوا المغربَ مع موسى بن نُصير، وتَوجَّهوا مع طارقِ إلى طَنجة، فأَحَبُّوا الانفِرادَ، فدَخلوا الصَّحراءَ واستَوطَنوها، فلم"},{"id":1564,"era":"c5","t":"مُوالاةُ السَّلاجِقَة لأَهلِ السُّنَّةِ وصَدُّهُم للرَّافِضَة .","s":"أُلْزِمَ الرَّوافِضُ بِتَركِ الأذانِ بحَيّ على خَيرِ العَملِ، وأُمِروا أن يُنادِي مُؤذِّنُهم في أذانِ الصُّبحِ، وبعدَ حَيَّ على الفَلاحِ: الصَّلاةُ خَيرٌ مِن النَّوْم. مَرَّتينِ، وأُزِيلَ ما كان على أَبوابِ المساجدِ ومَساجِدِهم مِن كتابة: محمدٌ وعَلِيٌّ خَيرُ البَشرِ. ودَخلَ المُنشِدونَ من بابِ البَصرَةِ إلى بابِ الكَرخِ، يُنشِدونَ بالقَصائدِ التي فيها مَدحُ الصَّحابَةِ، وذلك أنَّ نَجْمَ الرَّافِض"},{"id":1565,"era":"c5","t":"احتِلالُ البساسيري للمَوصِل .","s":"جاء البساسيري إلى المَوصِل ومعه نورُ الدَّولةِ دُبيس في جَيشٍ كَثيفٍ، فاقتَتَل مع صاحبِها قُريشِ بن بَدران ونَصرَهُ قُتلمشُ ابنُ عَمِّ طُغرلبك، وهو جَدُّ مُلوكِ الرُّومِ، فهَزمَهما البساسيري، وأَخذَ البَلدَ قَهْرًا، فخُطِبَ بها للعُبيديين  بمصر، وكذلك خُطِبَ للمِصريِّين فيها بالكوفَةِ وواسِط وغَيرِها من البِلادِ، وعَزَمَ طُغرلبك على المَسيرِ إلى المَوصِل لِمُناجَزَةِ البساسيري فنَهاهُ الخَليفةُ عن"},{"id":1566,"era":"c5","t":"وَباءٌ وقَحْطٌ عامٌّ ينتشر في البلدان .","s":"عَمَّ الوَباءُ والقَحْطُ بغدادَ والشامَ ومِصرَ ومَكَّةَ والحِجازَ ودِيارَ بَكْرٍ والمَوْصِلَ وبِلادَ الرُّومِ وخُراسان والجِبالَ؛ وكان النَّاسُ يأكلون المَيْتَةَ، وانقَطعَ ماءُ النِّيلِ بمصر، وكان يموتُ بها في كلِّ يَومٍ عَشرةُ آلافِ إنسانٍ، ووقع بمصر أنَّ ثَلاثةَ لُصوصٍ نَقَبُوا نَقْبًا فوُجِدُوا عند الصَّباحِ مَوْتَى: أَحدُهم على بابِ النَّقْبِ، والثَّاني على رَأسِ الدَّرَجَةِ، والثَّالثُ على ال"},{"id":1567,"era":"c5","t":"قِيامُ وَقعةٍ بين البساسيري وقُريشٍ بن بدران .","s":"نَشبَت مَعركةٌ بين البساسيري ومعه نورُ الدَّولةِ دُبيس بن مَزْيَد، وبين قُريشِ بن بَدران، صاحبِ المَوصِل، ومعه قُتلمش، وهو ابنُ عَمِّ السُّلطانِ طُغرلبك، وهو جَدُّ هؤلاء المُلوكِ أَولادِ قِلج أرسلان، ومعه أيضًا سَهمُ الدَّولةِ أبو الفَتحِ بن عَمرٍو، وكانت الحَربُ عند سنجار، فاقتَتَلوا، فاشتَدَّ القِتالُ بينهم، فانهَزَم قُريشٌ وقُتلمش، وقُتِلَ مِن أَصحابِهما الكَثيرُ, ولَقِيَ قُتلمش مِن أَهلِ سنجار"},{"id":1568,"era":"c5","t":"طاعونٌ عَظيمٌ في بلاد بُخارَى .","s":"وقعَ غَلاءٌ وفَناءٌ عَظيمان ببغداد وغَيرِها مِن البلادِ، بحيث خَلَتْ أَكثرُ الدُّورِ وَسُدَّتْ على أَهلِها أَبوابُها بما فيها، وأَهلُها مَوتى فيها، ثم صار المارُ في الطَّريقِ لا يَلقى الواحدَ بعدَ الواحدِ، وأكلَ النَّاسُ الجِيَفَ والنَّتَنَ مِن قِلَّةِ الطَّعامِ، ووُجِدَ مع امرأةٍ فَخِذُ كَلْبٍ قد اخْضَرَّ, وشَوَى رَجلٌ صَبِيَّةً في الأَتُونِ وأَكَلَها، وسَقطَ طائرٌ مَيِّتٌ مِن حائطٍ فاحْتَوَشَتْه"},{"id":1569,"era":"c5","t":"وَفاةُ أبي العَلاءِ المَعَرِّي الشاعر .","s":"هو شَيخُ الآدابِ، أبو العلاء أَحمدُ بن عبدِ الله بن سُليمانَ المَعَرِّي التَّنوخي الشاعر، اللُّغويُّ، صاحبُ الدَّواوين والمُصَنَّفات في الشِّعرِ واللُّغةِ، المشهور بالزَّندقَةِ، وُلِدَ سنة 363هـ, وأصابهُ جُدَري وله أربعُ سِنين أو سَبع، فذَهبَ بَصرهُ، وقال الشِّعْرَ وله إحدى أو ثنتا عشرة سَنة، ودخلَ بغداد سنةَ تِسعٍ وتسعين وثلاثمائة، فأقام بها سنةً وسبعةَ أَشهُر، ثم خَرجَ منها طَريدًا مُنهزِمًا، لم"},{"id":1570,"era":"c5","t":"استِيلاءُ البساسيري على المَوصِل ثم خُروجُه منها .","s":"فارَقَ إبراهيمُ ينال المَوصِل نحوَ بلادِ الجَبلِ، فنَسَبَ السُّلطانُ طُغرلبك رَحيلَه إلى العِصيانِ، فأَرسَل إليه رَسولًا يَستَدعِيه، وكَتبَ الخَليفةُ إليه أيضًا كِتابًا في المعنى، فرَجعَ إبراهيمُ إلى السُّلطانِ، وهو ببغداد، ولمَّا فارَق إبراهيمُ المَوصِل قَصدَها البساسيري، وقُريشُ بن بَدران، وحاصَراها، فمَلَكا البلدَ, وبَقِيَت القَلعةُ، وبها الخازِنُ، وأردمُ، وجماعةٌ مِن العَسكرِ، فحاصَراها أَربعة"},{"id":1571,"era":"c5","t":"وَفاةُ القاضي الماوَردِي .","s":"هو الإمامُ العَلَّامةُ، أَقضى القُضاةِ، أبو الحسنِ عَلِيُّ بن محمدِ بن حَبيبٍ، المَاوَردِي البَصري، شَيخُ الشَّافعيَّة، كان من وُجوهِ الفُقهاءِ الشَّافعيَّة ومن كِبارِهم، أَخذَ الفِقهَ عن أبي القاسم الصيمري بالبَصرةِ، ثم عن الشيخ أبي حامِد الإسفرايني ببغداد، صاحبِ التَّصانيفِ الكَثيرةِ في الأُصولِ والفُروعِ والتَّفسيرِ والأَحكامِ السُّلطانيَّة، وأَدَبِ الدُّنيا والدِّين، قال الماوردي: \"بَسَطتُ الف"},{"id":1572,"era":"c5","t":"وُقوعُ زَلزلةٍ عَظيمةٍ بالعِراقِ، والمَوصِل .","s":"وَقعَت زَلزلةٌ عَظيمةٌ بالعراقِ والمَوصِل ووَصلَت إلى همذان، ولَبِثَت ساعةً، فخَرَّبَت كثيرًا مِن الدُّورِ، وهَلَكَ فيها جَمٌّ غَفيرٌ."},{"id":1573,"era":"c5","t":"دُخولُ البساسيري إلى بغداد والخُطبةُ فيها للعُبيديِّين (الفاطِميِّين) .","s":"لمَّا خَرجَ طُغرلبك من بغداد خَلْفَ أَخيهِ إبراهيمَ ينال استَغلَّ الفُرصةَ البساسيري، فلمَّا كان يومُ الأحدِ الثامن من ذي القعدة جاء إلى بغداد ومعه الرَّاياتُ البِيضُ المِصريَّةُ العُبيدِيَّةُ، وعلى رَأسِه أَعلامٌ مَكتوبٌ عليها اسمُ المُستَنصِر بالله أبو تَميمٍ مَعَدُّ، أَميرُ المؤمنين، فتَلقَّاهُ أَهلُ الكَرخِ الرَّافِضَةُ وسَألوهُ أن يَجتازَ من عندهم، فدَخلَ الكَرخَ وخَرجَ إلى مشرعةِ الزَّاويا، "},{"id":1574,"era":"c5","t":"المُرابِطون يَبنُونَ مَدينةَ مَراكِش .","s":"قَصدَ يُوسفُ بن تاشفِين الملتوني اللَّمْتُوني أَميرُ المُرابِطين مَوضِعَ مَدينةِ مَراكِش، وهو قاعٌ صَفْصَفٌ، لا عِمارةَ فيه، وهو مَوضِعٌ مُتوسِّطٌ في بِلادِ المَغربِ كالقَيروانِ في إفريقية، فاخْتَطَّ هناك مَدينةَ مَراكِش لِيَقوَى على قَمعِ أَهلِ تلك الجِبالِ إن هَمُّوا بفِتنةٍ، فجعلها يُوسفُ مَقَرًّا له ولِعَسكرِهِ وللتمترّس للتَّتَرُّسِ بقَبائلِ المَصامِدَة المصيفة بمَواطنِهم بها في جَبلِ درن، فل"},{"id":1575,"era":"c5","t":"حَريقٌ هائلٌ ببغداد .","s":"احتَرقَت بغداد، الكَرخُ وغَيرهُ، وبين السُّورَينِ، واحتَرقَت فيه خَزانَةُ الكُتُبِ التي وَقَفَها أردشيرُ الوزيرُ، ونُهِبَت بَعضُ كُتُبِها، وجاء عَميدُ المُلْكِ الكندريُّ، فاختارَ من الكُتُبِ خَيرَها، وكان بها عَشرةُ آلاف وأربعمائة مُجلَّد من أَصنافِ العُلومِ، منها مائةُ مُصحَفٍ بخُطوطِ ابنِ مُقْلَة، وكان العامَّةُ قد نَهَبوا بَعضَها لمَّا وَقعَ الحَريقُ، فأَزالَهم عَميدُ المُلْكِ، وقَعدَ يَختارُها"},{"id":1576,"era":"c5","t":"وَفاةُ فَرَّخ زاد الغَزنَوي صاحبِ غَزنَة ومِلْكُ أَخيهِ إبراهيمَ بعده .","s":"هو المَلِكُ فَرَّخ زاد بن مسعودِ بن محمودِ بن سُبكتكين، صاحبُ غَزنَة، كان مَلِكًا شُجاعًا مَهيبًا، واسعَ البِلادِ. وكان قد ثار به مَماليكُه سَنةَ خمسين وأربعمائة واتَّفَقوا على قَتلِه، فقَصَدوهُ وهو في الحَمَّامِ، وكان معه سَيفٌ، فأَخذَهُ وقاتَلَهم، ومنعهم عن نَفسِه حتى أَدرَكهُ أَصحابُه وخَلَّصوهُ، وقَتَلوا أولئك الغِلمانَ. وصار بعد أن نَجا من هذه الحادِثَةِ يُكثِر ذِكْرَ الموتِ ويَحتَقِر الدُّني"},{"id":1577,"era":"c5","t":"مَقتَل إبراهيمَ ينال على يَدِ أَخيهِ السُّلطانِ طُغرلبك لِكَثرَةِ تَمَرُّدِهِ .","s":"كان السُّلطانُ طُغرلبك في قِلَّةٍ مِن العَسكرِ، بينما إبراهيمُ ينال كان قد اجتَمعَ معه كَثيرٌ من الأَتراكِ، وحَلفَ لهم أنَّه لا يُصالِح أَخاهُ طُغرلبك، ولا يُكَلِّفُهم المَسيرَ إلى العراقِ، وكانوا يَكرهونَه لِطُولِ مَقامِهم وكَثرةِ إخراجاتِهم، فلم يَقوَ به طُغرلبك، وأتى إلى إبراهيمَ محمدٌ وأَحمدُ ابنا أَخيهِ أرتاش في خَلْقٍ كَثيرٍ، فازداد بهم قُوَّةً، وازداد طُغرلبك ضَعْفًا، فانزاحَ من بين يَديهِ "},{"id":1578,"era":"c5","t":"تَوَلِّي ألب أرسلان مُلْكَ حَرَّان بعدَ أَبيهِ .","s":"تُوفِّي جغري بك داود بن ميكائيل بن سلجوق، أخو السُّلطانِ طُغرلبك، وقِيلَ: كان مَوتُه في صفر سنة 452هـ، وعُمُرُه نحوَ سبعين سَنةٍ، وكان صاحبَ خُراسان، وهو مُقابلَ آل سُبكتكين ومُقاتِلُهم، ومانِعُهم عن خُراسان، فلمَّا تُوفِّي مَلَكَ بَعدهُ خُراسانَ ابنُه السُّلطانُ ألب أرسلان."},{"id":1579,"era":"c5","t":"السَّلاجِقَة يَقضُونَ على فِتنَةِ البساسيري في بغداد .","s":"لمَّا فَرغَ السُّلطانُ طُغرلبك مِن أَمرِ أَخيهِ إبراهيمَ ينال عاد يَطلُب العِراقَ، فأَرسلَ إلى البساسيري وقُريشٍ في إعادةِ الخَليفةِ إلى دارهِ على أن لا يَدخُل طُغرلبك العِراقَ، ويَقنَع بالخُطبةِ والسِّكَّةِ، فلم يُجِب البساسيري إلى ذلك، فرَحلَ طُغرلبك إلى العِراقِ، فانحَدرَ حَرَمُ البساسيري وأَولادُه، ورَحلَ أَهلُ الكَرخِ بنِسائِهم وأَولادِهم في دِجلةَ وعلى الظَّهرِ، وكان دُخولُ البساسيري وأَولاد"},{"id":1580,"era":"c5","t":"مَقتلُ البساسيري  .","s":"هو أبو الحارثِ أرسلانُ بن عبدِ الله البساسيري مَملوكٌ تُركيٌّ، مُقَدَّمُ التُّركِ ببغداد، وهو الذي خَرجَ على الخَليفةِ القائمِ بأَمرِ الله ببغداد، وكان قد قَدَّمَهُ على جَميعِ التُّركِ، وقَلَّدَهُ الأمور بأَسرِها، وخُطِبَ له على مَنابرِ العِراقِ وخوزستان، فعَظُمَ أَمرُه وهابَتهُ المُلوكُ، ثم خَرجَ على الخَليفةِ القائمِ، في فِتنةٍ عَظيمةٍ شارَكهُ فيها قُريشُ بنُ بَدران العُقيليُّ، وخَطبَ البساسيري "},{"id":1581,"era":"c5","t":"القَضاءِ على فِتنةِ البساسيري والخَليفةِ القائمِ بأَمرِ الله يدخل بغداد .","s":"بعدَ أن فَرغَ طُغرلبك من أَخيهِ إبراهيمَ وغيرِ ذلك من المَشاغلِ أَسرعَ بالعَوْدِ إلى بغداد وليس له هم إلَّا إِعادةُ الخَليفةِ لدارهِ، وكان قد راسلَ البساسيري على أن يُعيدوا الخَليفةَ ويَقنَع هو بعَدمِ العَودةِ إلى بغداد فلم يَرضَ البساسيري، فتَمكَّنَت عَساكرُ طُغرلبك مِن قَتلِه في ذي الحجَّةِ سَنةَ451هـ. أَرسلَ طُغرلبك مِن الطَّريقِ الإمامَ أبا بكرٍ أحمدَ بن محمدِ بن أيوبَ المعروف بابنِ فورك، إلى "},{"id":1582,"era":"c5","t":"استيلاءُ المِرداسِيِّين على حَلَبَ ومَوقعةُ الفُنَيْدِق .","s":"حَصَرَ عِزُّ الدَّولةِ محمودُ بن شِبْلِ الدَّولةِ نَصرِ بن صالحِ بن مِرداس الكِلابي مدينةَ حَلَب، وضَيَّقَ عليها، واجتَمعَ مع جَمعٍ كَثيرٍ من العَربِ، فأَقامَ عليها، فلم يَتمكَّن مِن فَتحِها، فرَحلَ عنها، ثم عاوَدَها فحَصرَها، فمَلَكَ المدينةَ عَنوةً، بعدَ أن حَصرَها، وامتَنعَت القَلعةُ عليه. -كانت حَلبُ أوَّلًا بِيَدِ ثمالِ بن صالحِ بن مِرداس؛ لكنَّ أَهلَ حَلبَ لمَّا خَرجَ ثمالٌ إلى مِصرَ سَلَّمو"},{"id":1583,"era":"c5","t":"يُوسفُ بن تاشفين يَتولَّى شُؤونَ دَولةِ المُرابطين .","s":"قام أبو بكرِ بن عُمرَ اللَّمتُوني زَعيمُ المُرابطين بالمَغرِب بِتَولِيَةِ ابنِ عَمِّهِ يُوسفَ بن تاشفين شُؤونَ المُرابطين، وتَوجَّه أبو بكرٍ إلى الجنوبِ على رَأسِ جَيشٍ مُختَرِقًا بِلادَ سجلماسة، ثم قَصدَ بِلادَ السُّودانَ السِّنغالَ مُتوغِّلًا فيها ناشِرًا للإسلام."},{"id":1584,"era":"c5","t":"وَفاةُ نَصرِ الدَّولةِ الكُردي صاحبِ دِيارِ بَكرٍ .","s":"هو نَصرُ الدَّولةِ أحمدُ بن مَروان الكُردي، صاحبُ دِيارِ بِكرٍ، ولَقَبُه القادرُ بالله نَصرُ الدولةِ، واستَولى على الأُمورِ ببِلادهِ استِيلاءً تامًّا، وعَمَّرَ الثُّغورَ وضَبطَها، وتَنَعَّم تَنَعُّمًا لم يُسمَع بمِثلِه عن أَحدٍ مِن أَهلِ زَمانِه، ومَلَكَ خمسمائة سُرِّيَّةٍ سوى تَوابعهنَّ، وخمسمائة خادم، وكان في مَجلسِه من الآلاتِ ما تَزيدُ قَيمتُه على مائتي ألف دينارٍ، وتَزوَّج من بناتِ المُلوكِ ج"},{"id":1585,"era":"c5","t":"دخول قبائل المَغربِ الأقصى في طاعة يُوسف بن تاشفين .","s":"بعد أن قامَ يُوسفُ بن تاشفين بِفَتحِ مدينةِ فاس، أَخضعَ مُعظمَ نواحي المَغربِ الجَنوبيَّة والوُسطى، ودَخلَ في طاعتِه قبائلُ مغراتة وزناتة وبني يفرن."},{"id":1586,"era":"c5","t":"بِدايةُ الخِلافِ بين العَسكرِ الأَتراكِ والعُبيديين (الفاطميين) .","s":"خَرجَ المُستَنصِرُ الفاطمي على عادَتهِ في كلِّ سَنَةٍ يَركبُ على النُّجُبِ ومعه النِّساءُ والحَشَمُ إلى جب عميرة، وهو موضع نُزهَةٍ، ويُغيِّر هَيئتَه، كأنَّه خارجٌ يُريدُ الحَجَّ على سَبيلِ الهَزْرِ والمَجانَةِ، ومعه الخَمْرُ مَحمولٌ في الرَّوايا عِوَضًا عن الماءِ، ويَدورُ به سُقاتِه عليه وعلى مَن معه كأنَّه بِطريقِ الحِجاز أو كأنه ماءُ زمزم؛ واتَّفقَ أن بعضَ الأَتراكِ جَرَّدَ سَيْفًا في سَكْرَةٍ م"},{"id":1587,"era":"c5","t":"وَفاةُ المُعِزِّ بن باديس ووِلايةُ ابنهِ تَميم .","s":"هو المُعِزُّ بن باديس بن المنصور بن بلكين بن زيري بن مناد الحِميريُّ الصَّنهاجيُّ، صاحبُ إفريقية وما والاها مِن بلادِ المَغرب، وكانت وِلادتُه بالمَنصوريَّة، ويُقال لها صبرة، من أَعمالِ إفريقية، يومَ الخميسِ لِخَمسٍ مَضَيْنَ من جمادى الأُولى سنةَ 398هـ، ومَلَكَ بعدَ أَبيهِ باديس سنةَ 406هـ, وكان الحاكمُ العُبيدي صاحبُ مصر قد لَقَّبَهُ شَرَفَ الدَّولةِ، وسَيَّرَ له تَشريفًا وسِجِلًّا يَتضمَّن اللَّق"},{"id":1588,"era":"c5","t":"زَواجُ السُّلطانِ طُغرلبك من ابنةِ الخليفةِ العبَّاسي .","s":"خَطَبَ السُّلطانُ طُغرلبك ابنةَ الخليفةِ، فانزَعجَ الخليفةُ من ذلك، وقال: هذا شيءٌ لم تَجْرِ العادةُ بمِثلهِ، ثم طَلَبَ شيئًا كَثيرًا كهَيئةِ الفِرارِ، من ذلك أنه طَلبَ ما كان لِزَوجتِه التي تُوفِّيت من الإقطاعات بأرضِ واسط، و300 ألف دينارٍ، وأن يُقيمَ السُّلطانُ طُغرلبك ببغداد لا يَرحل عنها ولا يومًا واحدًا، فوقعَ الاتِّفاقُ على بعضِ ذلك، وأَرسلَ إليها بمائةِ ألف دينارٍ مع أرسلان خاتون ابنةِ أَخي"},{"id":1589,"era":"c5","t":"وَفاةُ القاضي المُؤَرِّخ أبي عبدِالله محمدِ بن سَلامةَ المعروف بالقَضاعي .","s":"هو الفَقيهُ، العلَّامةُ، القاضي المُؤرِّخ أبو عبدِالله محمدُ بن سَلامةَ بن جَعفرٍ المعروفُ بالقَضاعي، المِصري، الشافعي، كان من الثِّقاتِ الأثباتِ, إمامًا في الفِقهِ والحديثِ، وكان يَنوبُ في القَضاءِ بمصر أيامَ المُستَنصِر الفاطمي, وكان المُستَنصِر قد أَرسلَهُ في سِفارةٍ للتَّفاوُضِ مع إمبراطورِ الرُّومِ في القسطنطينية بشأنِ العِلاقة بين الدَّولتينِ. وهو صاحبُ كتابِ (الشِّهاب) مُجرَّدًا ومُسنَدًا، "},{"id":1590,"era":"c5","t":"العُبيدِيُّون (الفاطِميُّون) يُعاوِدونَ بَسْطَ نُفوذِهم على الحِجازِ .","s":"قَدِمَ الصليحي اليمني مكَّةَ بعدَ ما مَلَكَ اليمنَ كُلَّهُ سَهْلَهُ وجَبَلَهُ، وبَرَّهُ وبَحْرَهُ، وأقامَ بها وبمَكَّةَ دَعوةً المُستَنصِر، وكَسَا الكعبةَ حَريرًا أبيضَ، ورَدَّ حِليةَ البَيتِ إليه؛ وكان بنو حسنٍ قد أَخذوها ومَضوا بها إلى اليمنِ، فاشتَراها منهم، وأَعادَها في هذه السَّنةِ. واستَخلفَ على مكَّةَ محمدَ بن أبي هاشم، وعاد إلى اليمنِ."},{"id":1591,"era":"c5","t":"وُقوعُ زَلزلةٍ عَظيمةٍ بالشَّامِ .","s":"وَقعَت بالشَّامِ زَلزلةٌ عَظيمةٌ خَرِبَ منها كَثيرٌ من البلادِ، وانهَدمَ سُورُ طرابلس."},{"id":1592,"era":"c5","t":"وَفاةُ السُّلطانِ طُغرلبك وتَوَلِّي ابنِ أَخيهِ ليمان بن داودَ بعدَه .","s":"هو السُّلطانُ الكبيرُ، رُكْنُ الدِّين، أبو طالبٍ، طُغرلبك محمدُ بن ميكائيل بن سَلجوق بن دقاق أوَّلُ مُلوكِ السَّلاجِقة, وأَصلُ السَّلاجِقة مِن بَرِّ بُخارى؛ لهم عددٌ وقُوَّةٌ وإِقدامٌ، وشَجاعةٌ وشَهامةٌ وزَعارةٌ، فلا يَدخُلون تحتَ طاعةٍ، وإذا قَصدَهُم مَلِكٌ دَخَلوا البَرِّيَّة, ثم إن طُغرلبك عَظُمَ سُلطانُه، وطَوَى المَمالِكَ، واستولى على العِراقِ في سنة 447هـ، وتَحبَّبَ إلى الرَّعيَّةِ بِعَدْلٍ "},{"id":1593,"era":"c5","t":"ألب أرسلان يَخْلُف عَمَّهُ طُغرلبك السلجوقي .","s":"لمَّا خُطِبَ لسُليمانَ بن داودَ بالسَّلْطَنَةِ اختَلفَ الأُمراءُ، فمَضَى باغي سيان وأردم إلى قَزوين، وخَطَبا لأَخيهِ عَضُدِ الدَّولةِ ألب أرسلان محمدِ بن داودَ جغري بك بن ميكائيل بن سلجوق، ابن أخي طُغرلبك وهو حينئذٍ صاحبُ خُراسان، ومعه نِظامُ المُلْكِ وَزيرُه، والناسُ مائِلونَ إليهِ، وكذلك الجَيشُ كانوا يَميلونَ إليهِ، وقد خَطَبَ له أَهلُ الجَبَلِ ومعه نِظامُ المُلْكِ أبو عليٍّ الحَسنُ بن عَلِيِّ "},{"id":1594,"era":"c5","t":"ألب أرسلان يسيطر على مدينة ختلان وهراة وصغانيان .","s":"لمَّا مَلَكَ ألب أرسلان عَصَى عليه أَميرُ ختلان بِقَلعَتِه، ومَنعَ الخَراجَ، فقَصدَهُ السُّلطانُ، فرأى الحِصْنَ مَنيعًا على شاهقٍ، فأَقامَ عليه وقاتَلَهُ، فلم يَصِل منه إلى مُرادِه، ففي بَعضِ الأيَّامِ باشَرَ ألب أرسلان القِتالَ بِنَفسِه، وتَرَجَّلَ، وصَعَدَ في الجَبلِ، فتَبِعَهُ الخَلْقُ، وتَقدَّموا عليه في المَوقِف، وأَلَحُّوا في الزَّحْفِ والقِتالِ، وكان صاحبُ القَلعَةِ على شُرْفَةٍ من سُورِها "},{"id":1595,"era":"c5","t":"فَتْحُ ألب أرسلان مدينةَ آني وغَيرَها مِن بِلادِ النَّصرانِيَّة .","s":"سار السُّلطانُ ألب أرسلان من الرَّيِّ إلى أذربيجان، فوَصلَ إلى مرند عازِمًا على قِتالِ الرُّومِ وغَزْوِهِم، فلمَّا فَرَغَ مِن جَمعِ العساكرِ والسُّفُنِ سار إلى بلادِ الكرج، وجَعلَ مَكانَه في عَسكرِه وَلَدَهُ ملكشاه، ونِظامَ المُلْكِ وَزيرَه، فسار ملكشاه ونِظامُ المُلْكِ إلى قَلعةٍ فيها جَمعٌ كَثيرٌ مِن الرُّومِ، فنَزلَ أَهلُها منها، وتَخَطَّفُوا من العَسكرِ، وقَتَلوا منهم فِئَةً كَثيرةً، فنَزلَ نِ"},{"id":1596,"era":"c5","t":"النورمانديون يَذبَحون المسلمينَ في مَدينةِ ببشتر الأَندلُسِيَّة  .","s":"قام جيوم دي مونري النورماندي بقِيادَةِ حَملَةٍ بَحرِيَّةٍ نَزلَت بِساحلِ قطلونية ثم سارت إلى الشَّرْقِ حتى وَصلَت إلى مَدينةِ ببشتر جنوب إسبانيا وكانت من أَعمالِ يُوسفَ بن سُليمانَ بن هود فحاصَروها حتى استَسلَمت فدَخَلها وأَمْعَنَ جُنْدُهُ في أَهلِها قَتْلًا ونَهْبًا وسَبْيًا، ولم يُبادِر أَحدٌ من أُمراءِ الطَّوائفِ بِنَجْدَتِه، ثم غادَرَ النورمانديون المدينةَ بعدَ أن تَركوا فيها حامِيةً من خَمسةِ"},{"id":1597,"era":"c5","t":"الحربُ بين ألب أرسلان وقُتلمش .","s":"سَمِعَ ألب أرسلان أن شهابَ الدَّولةِ قُتلمش السلجوقي، قد عَصَى عليه، وجَمعَ جُموعًا كَثيرةً، وقَصدَ الرَّيَّ ليَستَولي عليها، فجَهَّزَ ألب أرسلان جَيشًا عَظيمًا وسَيَّرَهُم على المَفازَةِ إلى الرَّيِّ، فسَبَقوا قُتلمش إليها، وسار ألب أرسلان من نيسابور أَوَّلَ المُحرَّم من هذه السَّنَةِ، فلمَّا وَصلَ إلى دامغان أَرسَل إلى قُتلمش يُنكِر عليه فِعلَه، ويَنهاهُ عن ارتكابِ هذا الحالِ، ويَأمرُه بِتَركِها"},{"id":1598,"era":"c5","t":"وَفاةُ الإمامِ ابنِ حَزْمٍ الظاهري الأَندلُسي القُرطُبي .","s":"هو الإمامُ الأَوحدُ، البَحرُ، ذو الفُنونِ والمَعارِف، العَلَّامَةُ أبو مُحمدٍ عليُّ بن أحمدَ بن سَعيدِ بن حَزْمِ بن غالبِ بن صالحِ بن خَلَفِ بن معد بن سُفيانَ بن يَزيدَ (مَولى يَزيدَ بن أبي سُفيانَ) الأُمَويُّ الفَقيهُ الحافظُ، المُتَكَلِّمُ، الأَديبُ، الوَزيرُ، الظَّاهريُّ، صاحبُ التَّصانيفِ. أَصلُ جَدِّهِ يَزيدَ من فارس، وهو أَوَّلُ مَن أَسلَم من أَجدادِه، وجَدُّهُ خَلَفٌ أَوَّلُ مَن دَخَلَ بِلا"},{"id":1599,"era":"c5","t":"وَفاةُ الوَزيرِ عَميدِ المُلْكِ الكندريِّ .","s":"الوَزيرُ عَميدُ المُلْكِ، أبو نَصرٍ محمدُ بن منصورِ بن محمدٍ الكندريُّ، وَزيرُ السُّلطانِ طُغرلبك. كان أَحَدَ رِجالِ الدَّهرِ شَهامةً وكتابةً وكَرَمًا. وُلِدَ سنة 415هـ بقَريةِ كندر في نيسابور. تَفَقَّهَ لأبي حنيفةَ، وتَأَدَّبَ، ثم صَحِبَ رَئيسًا بنيسابور، فاستَخدَمهُ في ضِياعِه، ثم استَنابَهُ عنه في خِدمَةِ السُّلطانِ طُغرلبك، فطَلَبَه منه، فوَصَل في خِدمَتِه، وصار صاحِبَ خِبْرَةٍ. ثم وَلَّاهُ خو"},{"id":1600,"era":"c5","t":"الحَربُ بين بني حَمَّادٍ والعَربِ في أفريقية .","s":"كانت حَرْبٌ بين الناصرِ بن علناس بن حمَّادٍ ومَن معه مِن رِجالِ المَغارِبَةِ مِن صنهاجة ومِن زناتة ومِن العَربِ: عَدِيّ والأَثبَج، وبين رِياحٍ، وزُغْبَة، وسُلَيم، ومع هؤلاء المُعِزُّ بن زيري الزناتي، على مَدينةِ سَبتَة، ولمَّا رَحلَ المُعِزُّ من القيروان وصبرة إلى المَهدِيَّة تَمكَّنَت العَربُ، ونَهبَت النَّاسَ، وخَرَّبَت البِلادَ، فانتَقلَ كَثيرٌ مِن أَهلِها إلى بِلادِ بني حمَّاد لِكَونِها جِبالً"},{"id":1601,"era":"c5","t":"الإعلانُ عن سَبِّ الصَّحابَةِ وإظهارُ البِدَعِ في الكرخِ .","s":"في يومِ عاشُوراءَ أَغلَقَ الشِّيعةُ مِن أَهلِ الكَرخِ دَكاكِينَهم، وأَحضَرُوا نِساءً يَنُحْنَ على الحُسينِ، كما جَرَت به بِدعَتُهم، فحين وَقعَ ذلك أَنكرَتهُ العامَّةُ، وطَلبَ الخَليفةُ أبا الغَنائمِ ابن المحلبان وأَنكرَ عليه ذلك، فاعتَذرَ إليه بأنَّه لم يَعلَم به، وأنَّه حين عَلِمَ أَزالَهُ، وتَردَّدَ أَهلُ الكرخِ إلى الديوانِ يَعتَذِرون من ذلك، وخَرجَ التَّوقيعُ بِكُفْرِ مَن سَبَّ الصَّحابةَ وأَظ"},{"id":1602,"era":"c5","t":"حُدوثُ زِلزالٍ عَظيمٍ بخُراسان .","s":"حَدثَ بخُراسان زَلزلةٌ مَكثَت أيَّامًا، تَصدَّعَت منها الجِبالُ، وهَلكَ جَماعةٌ، وخُسِفَ بعِدَّةِ قُرى، وخَرجَ الناسُ إلى الصحراءِ وأقاموا هنالك، ووَقعَ حَريقٌ بنهر معلى فاحتَرقَ مائةُ دُكَّانٍ وثلاثةُ دُورٍ، وذهبَ للناس شيءٌ كَثيرٌ، ونَهبَ بَعضُهم بَعضًا."},{"id":1603,"era":"c5","t":"ألب أرسلان يأخذ ولاية العَهْدَ لابنِه ملكشاه من بعده .","s":"سار ألب أرسلان من مرو إلى رايكان، فنَزلَ بظاهِرِها، ومعهُ جَماعةُ أُمراءِ دَولتِه، فأَخَذَ عليهم العُهودَ والمَواثِيقَ لِوَلَدِهِ ملكشاه بأنَّه السُّلطانُ بعدَه، وأَركبَه، ومشى بين يَديهِ يَحمِلُ الغاشيةَ، وخَلعَ السُّلطانُ على جَميعِ الأُمراءِ، وأَمرَهُم بالخُطبةِ له في جميعِ البلادِ التي يَحكُم عليها، ففعل ذلك، وأَقطَع البِلادَ، فأَقطَع مازندران للأَميرِ إينانج بيغو، وبلخ لأخيه سُليمان بن داود ج"},{"id":1604,"era":"c5","t":"استِيلاءُ تَميمٍ صاحبِ إفريقية على القَيروان وقابس .","s":"سَيَّرَ تَميمٌ، صاحبُ إفريقية، عَسكرًا كَثيفًا إلى مَدينةِ قابس، وبها أحمدُ بن خُراسان قد أَظهرَ عليه الخِلافُ، وسَببُ ذلك أنَّ المُعِزَّ بن باديس، أبا تَميمٍ، لمَّا فارَقَ القَيروانَ والمَنصوريَّةَ ورَحلَ إلى المَهديَّة، استَخلفَ على القَيروان وعلى قابس قائدَ بنَ مَيمونٍ الصنهاجيَّ، وأَقامَ بها ثلاثَ سنين، ثم غَلبَتهُ هوارةُ عليها، فسَلَّمَها إليهم وخَرجَ إلى المَهدِيَّة، فلمَّا وَلِيَ المُلْكَ ت"},{"id":1605,"era":"c5","t":"وَفاةُ العالم اللُّغوِيِّ ابنِ سِيدَه .","s":"هو إمامُ اللُّغةِ، أبو الحُسينِ عَلِيُّ بن إسماعيلَ المرسي نِسبةً إلى مَدينةِ مرسية في شَرقِ الأَندَلُس المُعروفُ بابنِ سِيدَه، وأَحَدُ مَن يُضرَب بِذَكائِه المَثَلُ. كان إمامًا حافِظًا في اللُّغةِ، وكان ضَريرَ البَصَرِ، أَخذَ عِلمَ العَربيَّةِ واللُّغةِ عن أَبيهِ، وكان أَبوهُ ضَريرًا أَيضًا، واشتَغلَ على أبي العَلاءِ صاعدٍ البغداديِّ، وله ((المُحكَم في لِسانِ العَربِ)) في مُجلَّداتٍ عَديدةٍ، وله "},{"id":1606,"era":"c5","t":"وَفاةُ البَيهقيِّ صاحبِ السُّنَنِ .","s":"هو العَلَّامةُ، الثَّبْتُ، الفَقيهُ، شَيخُ الإسلامِ، أبو بكرٍ أَحمدُ بنُ الحُسينِ بن عَلِيِّ بن عبدِ اللهِ بن موسى البَيهقيُّ، الخسرو جردي الشافعيُّ الخُرسانيُّ الحافظُ الكَبيرُ المَشهورُ، المُحَدِّثُ الأُصوليُّ. وُلِدَ سَنةَ 384هـ. أَخَذَ الفِقهَ عن أبي الفَتحِ المروزيِّ، ثم غَلَبَ عليه الحَديثُ، واشتَهرَ به، وهو أوَّلُ مَن جَمعَ نُصوصَ الإمامِ الشافعيِّ في عَشرِ مُجلَّداتٍ. قال إمامُ الحَرمينِ ف"},{"id":1607,"era":"c5","t":"وَفاةُ القاضي أبي يَعلى الفَرَّاء شَيخِ الحَنابِلَة .","s":"هو الإمامُ، العلامةُ، شَيخُ الحنابلةِ، القاضي، أبو يَعلى محمدُ بن الحُسينِ بن محمدِ بن خَلَفِ بن أحمدَ البغداديُّ، الحَنبليُّ، ابنُ الفَرَّاءِ، وُلِدَ في مُحرَّم سنةَ 380هـ، صاحبُ التَّعليقَةِ الكُبرى، والتَّصانيفِ المُفيدةِ في المَذهَبِ, ومُمَهِّدُ مَذْهَبِهم في الفُروعِ، أَفْتَى ودَرسَ، وتَخَرَّجَ به الأصحابُ، وانتهت إليه الإمامةُ في الفِقْهِ، وكان عالِمَ العراقِ في زَمانهِ، مع مَعرفةٍ بعُلومِ ا"},{"id":1608,"era":"c5","t":"استِعادةُ ألب أرسلان سُلطَتِهِ على كرمان واصطخر .","s":"عَصَى مَلِكُ كرمان، وهو \"قرا أرسلان\"، على السُّلطانِ ألب أرسلان، وسببُ ذلك أنَّه كان له وَزيرٌ جاهلٌ سَوَّلَت له نَفسُه الاستِبدادَ بالبِلادِ عن السُّلطانِ، وأن صاحِبَه إذا عَصَى احتاجَ إلى التَّمَسُّكِ به، فحَسُنَ لصاحِبِه الخِلافُ على السُّلطانِ، فأجابَ إلى ذلك، وخَلعَ الطَّاعةَ، وقَطعَ الخُطبةَ، فسَمِعَ ألبُ أرسلان، فسارَ إلى كرمان، فلمَّا قارَبَها وَقعَت طَليعَتُه على طَليعَةِ قرا أرسلان، فانه"},{"id":1609,"era":"c5","t":"الانتهاءُ من بِناءِ المَدرسَةِ النِّظامِيَّة ببغداد وبَدءُ التَّدريسِ فيها .","s":"كان الشُّروعُ ببِناءِ المَدرسَةِ النِّظامِيَّة نِسبةً إلى الوَزيرِ نِظامِ المُلْكِ، وَزيرِ ملكشاه في مَدينةِ بغداد، في ذي الحجَّةِ من عام 457هـ ونُقِضَ لأَجلِها دُورٌ كَثيرةٌ مِن مَشرعَةِ الزَّوايا وبابِ البَصرةِ، ثم في ذي القَعدةِ من سَنةِ 459هـ، فَرغَت عِمارةُ المَدرسَةِ النِّظامِيَّة، وتَقرَّر التَّدريسُ بها للشيخِ أبي إسحاقَ الشِّيرازيِّ الشافعيِّ، فجَمعَ العَميدُ أبو سعدٍ القاضي الناسَ على طَ"},{"id":1610,"era":"c5","t":"وَفاةُ أبي جَعفرٍ الطُّوسيِّ فَقِيهِ الشِّيعَةِ .","s":"هو شَيخُ الشِّيعةِ، وصاحِبُ التَّصانيفِ، أبو جَعفرٍ محمدُ بن الحسنِ بن عليٍّ الطُّوسيُّ، فَقيهُ الإِمامِيَّة وعالِمُهُم، انتَقلَ مِن خُراسان إلى بغداد وأقامَ فيها أربعين سَنةً، تَفَقَّهَ فيها أوَّلًا للشافعيِّ, ثم أَخذَ الكلامَ وأُصولَ الشِّيعةِ عن الشيخِ المُفيدِ رَأسِ الإماميَّةِ ولَزِمَهُ حتى تَحوَّل رافِضِيًّا، وعَمِلَ التَّفسيرَ، وأَملَى أحاديثَ ونَوادِرَ في مُجلَّدينِ، عامَّتُها عن شَيخِه ال"},{"id":1611,"era":"c5","t":"حُدوثُ زِلازلٍ بالمَدينةِ والرَّملةِ  .","s":"كانت زَلزلةٌ بأَرضِ فِلسطينَ، أَهلكَت بَلدَ الرَّملةِ، ورَمَت شَراريفَ -الشراريف ما يُوضَع في أَعلى البناء يحلَّى به- من مَسجدِ رَسولِ الله صلَّى الله عليه وسلَّم، ولَحِقَت وادي الصَّفْرَ وخَيبرَ، وانشَقَّت الأرضُ عن كُنوزٍ كَثيرةٍ مِن المالِ، وبَلغَ حِسُّها إلى الرَّحبةِ والكوفةِ، وجاء كِتابُ بَعضِ التُّجَّارِ فيه ذِكْرُ هذه الزَّلزلةِ، وذَكرَ فيه أنَّها خَسفَت الرَّملةَ جَميعًا حتى لم يَسلَم منه"},{"id":1612,"era":"c5","t":"قِراءةُ الاعتِقادِ القادريِّ الذي فيه إِظهارُ السُّنَّةِ وإِنكار على أَهلِ البِدَعِ .","s":"يومَ النِّصفِ من جُمادى الآخرة قُرِئَ الاعتقادُ القادريُّ الذي فيه مَذهبُ أَهلِ السُّنَّةِ والجَماعةِ، والإنكارُ على أَهلِ البِدَعِ، وقَرأَ أبو مُسلمٍ الكجيُّ البخاريُّ المُحَدِّثُ كِتابَ ((التَّوحيدِ)) لابنِ خُزيمةَ على الجَماعةِ الحاضرين، وذُكِرَ بمَحضرٍ مِن الوَزيرِ ابنِ جَهيرٍ وجَماعةِ الفُقهاءِ وأَهلِ الكَلامِ، واعتَرَفوا بالمُوافَقةِ، ثم قُرِئَ الاعتِقادُ القادريُّ على الشَّريفِ أبي جَعفرِ ب"},{"id":1613,"era":"c5","t":"وَفاةُ عبدِ المَلِكِ بن محمدٍ المُلَقَّبِ بالشَّيخِ الأَجَلِّ .","s":"هو الصَّدرُ الأَنبلُ الرَّئيسُ القُدوةُ أبو منصورٍ عبدُ المَلِكِ بن محمدِ بن يُوسُفَ البغداديُّ، سِبْطُ الإمامِ أبي الحسينِ أحمدَ بن عبدِ الله السوسنجردي, وُلِدَ سنةَ 395هـ وكان يُلقَّب بالشَّيخِ الأَجَلِّ، كان أَوْحَدَ زَمانِه في الأمرِ بالمَعروفِ والنهيِ عن المُنكرِ، والمُبادَرةِ إلى فِعلِ الخَيراتِ، واصطِناعِ الأَيادي عند أَهلِها، مِن أَهلِ السُّنَّةِ، مع شِدَّةِ القِيامِ على أَهلِ البِدَعِ ولَ"},{"id":1614,"era":"c5","t":"بَدْءُ ضَعفِ الحُكمِ العُبيديِّ الفاطِميِّ بمِصرَ .","s":"بَدأَت الدَّولةُ الفاطِمِيَّةُ بمصر يُصيبُها الضَّعفُ بسَببِ عِدَّةِ أُمورٍ كان مِن أَهمِّها حُصولُ الشِّقاقِ بين التُّركِ والعَبيدِ، وحُصولُ الاقتِتالِ بينهم، وفي هذه السَّنَةِ خَرجَ ناصرُ الدولةِ بن حمدان من عند الوزيرِ أبي عبدِ الله الماشلي وَزيرِ المُستَنصِر بمصر فوَثبَ عليه رَجلٌ صَيْرَفِيٌّ وضَربَه بسِكِّينٍ؛ فأُمسِكَ الصَّيرفيُّ وشُنِقَ في الحالِ، وحُمِلَ ناصرُ الدولةِ بن حمدان إلى دارِه جَ"},{"id":1615,"era":"c5","t":"وَفاةُ المُعتَضِد بالله عَبَّادِ بن القاضي محمد مَلِكِ إشبيلية .","s":"هو المُعتَضِدُ بالله أبو عَمرٍو عَبَّادُ بن الظَّافرِ المُؤَيَّدِ بالله أبي القاسمِ محمد قاضي إشبيلية بن أبي الوَليدِ إسماعيلَ بن قُريشِ بن عَبَّادِ بن عَمرِو بن أَسلمَ بن عَمرِو بن عَطَّافِ بن نُعيمٍ، اللخميُّ، مِن وَلَدِ النُّعمانِ بن المُنذِر اللخميِّ، آخر مُلوكِ الحِيرَةِ, لمَّا تُوفِّي محمدٌ القاضي سَنةَ 433هـ قامَ مَقامَه وَلَدُه عَبَّادٌ، قال أبو الحسنِ عليُّ بن بَسَّامٍ في حَقِّهِ: \" ثم أَ"},{"id":1616,"era":"c5","t":"احتِراقُ الجامعِ الأُمَويِّ بدِمَشق .","s":"في لَيلةِ النِّصفِ من شعبان كان حَريقُ جامعِ دِمشق، وكان سَببُه أنَّ غِلمانَ الفاطِميِّين والعَبَّاسِيِّين اختَصَموا فأُلقِيَت نارٌ بِدارِ المُلْكِ، وهي الخَضراءُ المُتاخِمَةِ للجامعِ مِن جِهَةِ القِبلَةِ، فاحتَرقَت، وسَرَى الحَريقُ إلى الجامعِ فسَقطَت سُقُوفُه وتَناثَرت فُصوصُه المُذَهَّبَةُ، وتَغيَّرَت مَعالِمُه، وتَقَلَّعَت الفُسَيْفِساءُ التي كانت في أَرضِه، وعلى جُدرانِه، وتَبدَّلَت بِضِدِّها"},{"id":1617,"era":"c5","t":"تَوَجُّهُ مَلِكِ الرُّومِ مِن القُسطنطينيَّة إلى الشام ونُزولُه مدينة منبج .","s":"أَقبلَ مَلِكُ الرُّومِ مِن القُسطنطينِيَّة في عَسكرٍ كَثيفٍ إلى الشامِ، ونَزلَ على مَدينةِ منبج بسوريا ونَهبَها وقَتلَ أَهلَها، وهَزمَ محمودَ بن صالحِ بن مرداس، وبني كِلابٍ، وابنَ حسَّان الطائيَّ، ومَن معهما مِن جُموعِ العَربِ، ثم إنَّ مَلِكَ الرُّومِ ارتَحلَ وعادَ إلى بِلادِه، ولم يُمكِنهُ المَقامُ لِشِدَّةِ الجُوعِ."},{"id":1618,"era":"c5","t":"وَفاةُ أبي بكرٍ اللَّمْتوني مُؤَسِّس دَولةِ المُرابطين .","s":"أبو بكرِ بن عُمرَ بن تكلاكين اللَّمتوني، أَميرُ المُلَثَّمِين، وهو ابنُ عَمِّ يُوسفَ بنِ تاشفين أَميرِ المُرابطين، كان في أَرضِ فرغانة، خَلَفَ أَخاهُ يحيى بن عُمرَ في زَعامةِ صنهاجة وتَقَلَّدَ أُمورَ الحَربِ، اتَّفقَ له مِن النَّاموسِ ما لم يَتَّفِق لِغيرهِ مِن المُلوكِ، كان يَركَبُ معه إذا سار لِقِتالِ عَدُوٍّ خمسُمائةِ ألفِ مُقاتلٍ، كان يعتقد طاعته، لمَّا قَدِمَ عبدُالله بن ياسين للصحراء لصحراء "},{"id":1619,"era":"c5","t":"غَلاءٌ شَديدٌ، ومَجاعةٌ عَظيمةٌ في مصر .","s":"كان بمصر غَلاءٌ شَديدٌ، ومَجاعةٌ عَظيمةٌ حتى أَكلَ الناسُ بَعضُهم بَعضًا، وفارَقوا الدِّيارَ المِصريَّة، فوَرَدَ بغدادَ منهم خَلْقٌ كَثيرٌ هَرَبًا مِن الجوعِ، ووَرَدَ التُّجَّارُ، ومعهم ثِيابُ صاحبِ مصر وآلاتُه، نُهِبَت مِن الجوعِ، وكان فيها أشياءُ كَثيرةٌ كانت قد نُهِبَت من دارِ الخِلافةِ وقتَ القَبضِ على الطائعِ لله سنة 381هـ، وممَّا نُهِبَ أيضًا في فِتنةِ البساسيري وخَرَجَ من خَزائنِهم ثمانون أ"},{"id":1620,"era":"c5","t":"قَطْعُ الخُطبةِ للعبيديين في مكة والمدينة وإِقامةُ الخُطبةِ للعبَّاسيِّين .","s":"وَرَدَ رسولُ صاحبِ مكَّةَ محمدِ بن أبي هاشمٍ، ومعه وَلَدُه، إلى السُّلطانِ ألب أرسلان، يُخبِرُه بإقامةِ الخُطبةِ للخَليفةِ القائمِ بأَمرِ الله وللسُّلطانِ بمكَّةَ، وإِسقاطِ خُطبَةِ الفاطميِّ صاحبِ مصر، وتَرْكِ الأَذانِ بِحَيَّ على خَيرِ العَملِ، فأَعطاهُ السُّلطانُ ثلاثينَ ألف دِينارٍ، وخِلَعًا نَفيسَةً، وأَجرَى له كلَّ سَنَةٍ عَشرةَ آلاف دِينارٍ، وقال: إذا فَعلَ أَميرُ المَدينَةِ مهنأ كذلك، أَعطَ"},{"id":1621,"era":"c5","t":"نِهايةُ الدَّولةِ الجَهْوَرِيَّةِ بِقُرطُبة .","s":"قام يحيى المأمون بن إسماعيل بن ذي النون أَميرُ طُليطلة بالمَسيرِ إلى قُرطُبة للاستِيلاءِ عليها، فاستَنجدَ أَميرُها عبدُالملك بن جَهور بالمُعتَمِد بن عبَّادٍ الذي أَرسلَ إليه جَيشًا للنَّجدَةِ فاحتَلَّ قُرطُبة واعتَقلَ عبدَالملك بن جَهور ووَالِدَهُ وأَخاهُ ونَفاهُم إلى جَزيرةِ شلطيش، ووَلَّى ابنَه سِراجَ الدَّولةِ حاكِمًا على قُرطُبة فأنهى بذلك دَولةَ الجَهوريِّينَ على قُرطُبة التي دامت قَريبًا من "},{"id":1622,"era":"c5","t":"وَفاةُ ابنِ عبدِ البَرِّ القُرطُبيِّ .","s":"هو الإمامُ، العَلَّامةُ، حافظُ المَغرِب، شيخُ الإسلامِ، أبو عُمرَ يُوسُف بنُ عبدِ الله بن محمدِ بن عبدِ البَرِّ بن عاصمٍ النمريُّ، الأَندَلُسيُّ، القُرطُبيُّ, فَقِيهٌ مالكيٌّ مَشهورٌ، صاحبُ التَّصانيفِ المَلِيحَةِ الهائِلَة، منها ((التمهيد))، و((الاستذكار)) و((الاستيعاب))، وغير ذلك، مِن كِبارِ حُفَّاظِ الحَديثِ، يُقالُ عنه: حافِظُ المَغرِب، وُلِدَ سَنةَ 368هـ. طَلَبَ العِلمَ بعدَ 390هـ وأَدرَكَ ال"},{"id":1623,"era":"c5","t":"انتِزاعُ الأَميرِ أتسز الخوارزميِّ الرَّمْلَةَ وبَيتَ المَقْدِس من اتباعِ العُبيديِّين .","s":"قَصَدَ أتسز بن أوق الخوارزميُّ -وهو من أُمراءِ السُّلطانِ ملكشاه السلجوقي- بِلادَ الشامِ، فجَمعَ الأَتراكَ وسار إلى فِلسطين، ففَتحَ مَدينةَ الرَّمْلَةَ، وسار منها إلى بَيتِ المَقدِس وحَصرَه، وفيه عَساكرُ المِصريِّين التابِعينَ للدولةِ الفاطِميَّة، ففَتَحَهُ، ومَلَكَ ما يُجاوِرُهُما من البِلادِ، ما عدا عَسقلان، وقَصَدَ دِمشقَ فحَصرَها، وتابَعَ النَّهْبَ لِأَعمالِها حتى خَرَّبَها، وقَطعَ الميرةَ عنه"},{"id":1624,"era":"c5","t":"استِيلاءُ السُّلطانِ ألب أرسلان على حَلَب .","s":"بَعثَ ناصرُ الدولةِ حُسينُ بن حمدان الفقيه أبا جَعفرٍ محمدَ بن أحمدَ بن البُخاريِّ رَسولًا منه إلى السُّلطانِ ألب أرسلان، مَلِكِ العِراقِ، يَسألهُ أن يُسَيِّرَ إليه العَساكرَ لِيُقيمَ الدَّعوةَ العبَّاسيَّةَ بدِيارِ مصر، وتكون مصر له. فتَجَهَّزَ ألب أرسلان مِن خُراسان في عِساكرَ عَظيمةٍ، وبَعثَ إلى محمودِ بن ثمال بن صالحِ بن مرداس، صاحبِ حَلَب، أن يَقطعَ دَعوةَ المُستَنصِر ويُقيمَ الدَّعوةَ العبَّ"},{"id":1625,"era":"c5","t":"وَفاةُ الشاعِرِ ابنِ زَيدونَ الأندَلُسي  .","s":"هو الصاحبُ، الوَزيرُ، العَلَّامَةُ، أبو الوَليدِ أحمدُ بن عبدِ الله بن أحمدَ بن غالبِ بن زَيدونَ المَخزُومِيُّ، القُرشيُّ، الأندَلُسيُّ، القُرطُبيُّ، الشاعرُ الماهرُ، حاملُ لِواءِ الشِّعْرِ في عَصرِه. اتَّصلَ بالأَميرِ المُعتَمِدِ بن عبَّادٍ، صاحبِ إشبيلية، فحَظِيَ عنده وصار مُشاوِرًا في مَنزِلَةِ الوَزيرِ، كان بارِعًا أَديبًا شاعرًا مُجيدًا، كان يُشعِر لِنَفسِه لا للتَّكَسُّبِ، أُفْعِمَ بِحُبِّ و"},{"id":1626,"era":"c5","t":"مَوقِعةُ ملازكرد بقِيادَةِ السُّلطانِ ألب أرسلان .","s":"في هذه السَّنَةِ خَرجَ أرمانوس مَلِكُ الرُّومِ في مائتي ألفٍ من الرُّومِ، والفِرنجِ، والغَربِ، والرُّوسِ، والبجناك، والكرج، وغَيرِهم، من طوائفِ تلك البِلادِ، فجاءوا في تَجَمُّلٍ كَثيرٍ، وزِيٍّ عَظيمٍ، وقَصدَ بِلادَ الإسلامِ، فوَصلَ إلى ملازكرد من أَعمالِ خلاط. فبَلغَ السُّلطانَ ألب أرسلان الخَبرُ. وهو بمَدينةِ خوي من أذربيجان، قد عاد من حَلَب. وسَمِعَ بكَثرَةِ الجُموعِ التي  مع مَلِكِ الرُّومِ، فل"},{"id":1627,"era":"c5","t":"وَفاةُ الخَطيبِ البَغداديِّ صاحبِ تاريخِ بغداد .","s":"هو الحافِظُ أبو بكرٍ أَحمدُ بن عليِّ بن ثابتِ بن أَحمدَ بن مَهدِيٍّ، الخَطيبُ البغداديُّ، أَحدُ الحُفَّاظِ الأَعلامِ المَشهورِينَ، صاحبُ ((تاريخ بغداد)) وغَيرِه من المُصنَّفاتِ العَديدةِ المُفيدةِ، وُلِدَ سَنةَ 392هـ، وكان أبوه أبو الحَسنِ الخَطيبُ قد قَرأَ على أبي حَفصٍ الكِتَّانيِّ، وصار خَطيبَ قَريةِ درزيجان، إحدى قُرى العِراقِ، فحَضَّ وَلدَه أبا بكرٍ على السَّماعِ في صِغَرِه، فسَمِعَ وله إحدى "},{"id":1628,"era":"c5","t":"إِنكارُ الشيخِ الشِّيرازيِّ مع عَددٍ من الحَنابِلَةِ على المُفسِدِينَ .","s":"قام الشيخُ أبو إسحاقَ الشِّيرازيُّ مع الحَنابِلَةِ في الإنكارِ على المُفسِدِينَ، والذين يَبيعُونَ الخُمورَ، وفي إِبطالِ المُؤاجِراتِ وَهُنَّ البَغايا، وكَتَبوا إلى السُّلطانِ في ذلك، فجاءَت كُتُبُه في الإنكارِ."},{"id":1629,"era":"c5","t":"حُدوثُ زَلزَلةٍ عَظيمةٍ ببغداد .","s":"حدوث حَدَثَت زَلزلةٌ عَظيمةٌ ببغداد ارتَجَّت لها الأَرضُ سِتَّ مَرَّاتٍ، وفيها كان مَوتٌ ذَرِيعٌ في الحيواناتِ، بحيث أنَّ بعضَ الرُّعاةِ بخُراسان قام وقتَ الصباحِ لِيَسرَحَ بِغَنَمِه فإذا هُنَّ قد مِتْنَ كُلُّهُنَّ، وجاء سَيْلٌ عَظيمٌ وبَرَدٌ كِبارٌ أَتلَفَ شَيئًا كَثيرًا من الزُّروعِ والثِّمارِ بخُراسان."},{"id":1630,"era":"c5","t":"السُّلطانِ ألب أرسلان يسيطر على قَلعةَ فضلون الكُرديِّ بفارِس .","s":"سَيَّرَ السُّلطانُ ألب أرسلان وَزيرَهُ نِظامَ المُلْكِ في عَسكرٍ إلى بِلادِ فارِس، وكان بها حِصْنٌ من أَمنَعِ الحُصونِ والمَعاقِلِ، وفيه صاحبُه فضلون الكُرديُّ، وهو لا يُعطِي الطَّاعةَ، فنازَلَهُ وحَصرَهُ، ودَعاهُ إلى طَاعةِ السُّلطانِ فامتَنَع، فقاتَلَهُ فلم يَبلُغ بقِتالِه غَرَضًا لِعُلُوِّ الحِصنِ وارتِفاعِه، فلم يَطُل مَقامُهم عليه حتى نادَى أَهلُ القَلعةِ بَطَلَبِ الأَمانِ لِيُسَلِّموا الحِصن"},{"id":1631,"era":"c5","t":"مُحاوَلةُ ناصرِ الدَّولةِ ابنِ حمدان التَّغلبيِّ القَضاءَ على دَولةِ المُستَنصِر بالله الفاطِميِّ  .","s":"وَقعَ نِزاعٌ بين فِرقَتينِ، فِرقةِ العَبيدِ وعَرَبِ الصَّعيدِ، وفِرقةِ الجُنْدِ مِن التُّركِ والمَغارِبَةِ، ورَأسُهم ناصرُ الدَّولةِ ابنُ حمدان التَّغلبيُّ، فالتَقوا بكومِ الريش، فهَزمَهم ابنُ حمدان، وقَتَلَ وغَرَّقَ نحوًا من أربعين ألفًا. ونَفَدَت خَزائنُ المُستَنصِر على التُّركِ، ثم اختَلَفوا، ودامت الحَربُ أيامًا، وطَمِعَ التُّركُ في المُستَنصِر، وطالبوه حتى بِيعَت فُرُشُ القَصرِ، وأَمتِعَتُه ب"},{"id":1632,"era":"c5","t":"وَفاةُ ناصِرِ الدَّولةِ ابنِ حمدان التُّركيِّ .","s":"هو الأَميرُ الكَبيرُ، ناصِرُ الدَّولةِ، حُسينُ بنُ الأَميرِ ناصِرِ الدَّولةِ وسَيفِها حَسنِ بنِ الحُسينِ ابنِ صاحِبِ المَوصِل ناصِرِ الدَّولةِ، أبي مُحمدٍ الحَسنِ بنِ عبدِ الله بن حمدان، التَّغلبيُّ. كان أَبوهُ حَسنٌ قد عَمِلَ نِيابةَ دِمشقَ لصاحِبِ مصر المُستَنصِر، ونَشأَ ناصرُ الدَّولةِ، فكان أَحَدَ الأَبطالِ، شَهْمًا شُجاعًا، مِقدامًا مَهِيبًا، وافِرَ الحِشمَةِ، تَمَكَّنَ بمِصرَ، وتَقدَّم على أ"},{"id":1633,"era":"c5","t":"الحَربُ بين السُّلطانِ ملكشاه وعَمِّهِ قاورت بك .","s":"لمَّا بَلغَ قاورت بك، وهو بكرمان، وَفاةُ أَخيهِ ألب أرسلان سارَ طالِبًا للرَّيِّ يُريدُ الاستِيلاءَ على المَمالِكِ، فسَبَقَهُ إليها السُّلطانُ ملكشاه ونِظامُ المُلْكِ، وسارا منها إليه، فالتَقوا بالقُربِ من همذان في شَعبانَ، وكان العَسكرُ يَمِيلون إلى قاورت بك، فحَمَلَت مَيسرةُ قاورت بك على مَيمَنَةِ ملكشاه، فهَزَموها، وحَمَلَ شَرفُ الدَّولةِ مُسلمُ بن قُريشٍ، وبَهاءُ الدَّولةِ مَنصورُ بن دبيس بن م"},{"id":1634,"era":"c5","t":"وَفاةُ القُشيريِّ مصنف الرِّسالَةِ القُشيريَّة .","s":"الفَقيهُ الشافعيُّ أبو القاسمِ عبدُ الكَريمِ بنُ هوازن القُشيريُّ، النَّيسابوريُّ، مُصَنِّفُ ((الرِّسالة القُشيريَّة)) المشهورة وغيرَها، كان عَلَّامةً في الفِقْهِ والتَّفسيرِ والحَديثِ والأُصولِ والكِتابَةِ والأَدبِ والشِّعْرِ وعِلْمِ التَّصَوُّفِ، جَمعَ بين الشَّريعَةِ والحَقيقَةِ، أَصلُه من ناحِيَةِ أستوا من العَربِ الذين قَدِموا خُراسان، وُلِدَ في شَهرِ رَبيعٍ الأَوَّلِ سَنةَ 376هـ. تُوفِّي أَب"},{"id":1635,"era":"c5","t":"تَوبةُ أبي الوَفاءِ بن عَقيلٍ مِن الاعتِزالِ\n  .","s":"قال ابنُ كَثيرٍ: \"في يومِ الخَميسِ حادي عشر المُحرَّمِ حَضرَ إلى الدِّيوانِ أبو الوَفا عليُّ بنُ محمدِ بنِ عَقيلٍ العَقيليُّ الحَنبليُّ، وقد كَتبَ على نَفسِه كِتابًا يَتضمَّن تَوبتَه من الاعتِزالِ، وأنَّه رَجعَ عن اعتِقادِ كَوْنِ الحَلَّاجِ من أَهلِ الحَقِّ والخَيرِ، وأنه قد رَجعَ عن الجُزءِ الذي عَمِلَه في ذلك، وأنَّ الحَلَّاجَ قد قُتِلَ بإجماعِ عُلماءِ أَهلِ عَصرِه على زَندَقتِه، وأنَّهم كانوا م"},{"id":1636,"era":"c5","t":"وَفاةُ ألب أرسلان سُلطانِ السَّلاجِقَة .","s":"هو سُلطانُ العالَم عَضُدُ الدَّولةِ أبو شُجاعٍ، المُلَقَّبُ بالعادِل محمد، ألب أرسلان بن جغريبك داود بن ميكائيل بن سلجوق بن دقاق بن سلجوق التُّركيُّ, واسمُه بالعربي محمدُ بنُ داودَ وألب أرسلان اسمٌ تُركيٌّ مَعناهُ شُجاع أَسَد، فألب: شُجاع، وأرسلان: أَسَد. وهو ابنُ أخي السُّلطانِ طغرلبك، أَصلُه من قَريةٍ يُقال لها: النور. وُلِدَ سَنةَ 424هـ, وَجَدُّهُ دقاق، هو أَوَّلُ مَن دَخلَ في الإسلامِ, وألب أر"},{"id":1637,"era":"c5","t":"مِلْكُ ملكشاه بن ألب أرسلان بعدَ مَوتِ أَبيهِ .","s":"لمَّا جُرِحَ السُّلطانُ ألب أرسلان أَوصَى لابنِه ملكشاه، وكان معه، وأَمرَ أن يَحلِف له العَسكرُ، فحَلَفوا جَميعُهم، وكان المُتَوَلِّي للأَمرِ في ذلك نِظامُ المُلْكِ، وأَرسلَ ملكشاه إلى بغداد يَطلُب الخُطبةَ له، فخُطِبَ له على مَنابِرِها، وأَوصَى ألب أرسلان ابنَه ملكشاه أيضًا أن يُعطِي أَخاهُ قاروت بك بن داود أَعمالَ فارس وكرمان، وشَيئًا عَيَّنَهُ من المالِ، وأن يُزَوَّجَ بِزَوجَتِه، وكان قاروت بك "},{"id":1638,"era":"c5","t":"استِيلاءُ مَلِكِ التكين صاحِبِ سَمرقَند على مَدينةِ تِرمِذ .","s":"مَلَكَ التكينُ صاحبُ سَمرقَند مَدينةَ تِرمِذ، وسَببُ ذلك أنَّه لمَّا بَلغَهُ وَفاةُ ألب أرسلان، وعَوْدُ ابنِه ملكشاه عن خُراسان، طَمِعَ في البِلادِ المُجاوِرَةِ له، فقَصدَ تِرمِذَ أوَّلَ رَبيعٍ الآخر، وفَتحَها، ونَقلَ ما فيها من ذَخائِر وغَيرِها إلى سَمرقَند."},{"id":1639,"era":"c5","t":"دُخولُ عَسكرِ غَزْنَةَ إلى سكلكند .","s":"وَردَت طائِفةٌ كَثيرةٌ من عَسكرِ غَزنةَ إلى سكلكند، وبها عُثمانُ عَمُّ السُّلطانِ ملكشاه، ويُلقَّب بأَميرِ الأُمراءِ، فأَخَذوهُ أَسيرًا، وعادوا به إلى غَزنةَ مع خَزائِنه وحَشَمِه، فسَمِعَ الأَميرُ كمشتين بلكابك، وهو من أَكابرِ الأُمراءِ، فتَبِعَ آثارَهُم، وكان معه أنوشتكين جَدُّ مُلوكِ خوارزم، فنَهَبوا مَدينةَ سكلكند."},{"id":1640,"era":"c5","t":"ارتفاع ماء دجلة وغَرَقُ بغدادَ .","s":"غَرِقَ الجانبُ الشرقيُّ وبعضُ الغربيِّ من بغداد، وسَببُه أن دِجلَة زادت زِيادةً عَظيمةً، وانفَتَح القَوْرَجِ عند المُسَنَّاةِ المُعِزِّيَّةِ، وجاء في الليلِ سَيْلٌ عَظيمٌ، وطَفحَ الماءُ من البَرِّيَّةِ مع رِيحٍ شَديدةٍ، وجاء الماءُ إلى المنازِلِ من فَوق، ونَبعَ من البَلاليعِ والآبارِ بالجانبِ الشرقيِّ، وهَلَكَ خَلْقٌ كَثيرٌ تحت الهَدْمِ، وشُدَّت الزَّواريقُ تحتَ التَّاجِ خَوْفَ الغَرَقِ، وقام الخَ"},{"id":1641,"era":"c5","t":"مِلْكُ السُّلطانِ ملكشاه تِرمِذ والهُدْنَةُ بينه وبين صاحبِ سَمرقَند .","s":"إنَّ خاقان التكين صاحبَ سَمرقَند مَلَكَ تِرمِذَ بعدَ قَتْلِ السُّلطانِ ألب أرسلان، فلمَّا استَقامَت الأُمورُ للسُّلطانِ ملكشاه سار إلى تِرمِذ وحَصرَها، وطَمَّ العَسكرُ خَندَقها، ورَماها بالمجانيقِ، فخافَ مَن بها، فطَلَبوا الأَمانَ فأَمَّنَهم، وخَرَجوا منها وسَلَّموها، وكان بها أَخٌ لِخَاقان التكين، فأَكرَمَه السُّلطانُ، وخَلَعَ عليه وأَحسنَ إليه وأَطلَقَه، وسَلَّمَ قَلعةَ تِرمِذ إلى الأَميرِ ساوتك"},{"id":1642,"era":"c5","t":"استِعانَةُ ملكشاه بالمُنَجِّمِين .","s":"جَمَعَ نِظامُ المُلْكِ، والسُّلطانُ ملكشاه، جَماعةً من أَعيانِ المُنَجِّمِين، وجَعَلوا النَّيْروزَ أَوَّلَ نُقطَةٍ من الحَمَل، وكان النَّيروزُ قبلَ ذلك عند حُلولِ الشمسِ نِصفَ الحُوتِ. وصار ما فَعلَه السُّلطانُ مَبدأَ التَّقاويمِ، وفيها أيضًا عُمِلَ الرَّصْدُ للسُّلطانِ ملكشاه، واجتَمعَ من أَعيانِ المُنَجِّمِينَ في عَمَلِه وخَرَجَ عليه من الأَموالِ شَيءٌ عَظيمٌ، وبَقِيَ الرَّصدُ دائِرًا إلى أن مات"},{"id":1643,"era":"c5","t":"وُقوعُ حَربٍ بين بَنِي رِياحٍ وزُغبةَ ببِلادِ إفريقية .","s":"وَقَعَت حَربٌ شَديدةٌ بين بَنِي رِياحٍ وزُغبةَ ببِلادِ إفريقية، فقَوِيَت بَنُو رِياحٍ على زُغبةَ فهَزَموهُم وأَخرَجوهُم عن البِلادِ, وهذه القَبائلُ هي التي شَجَّعَها المُستَنصِرُ بالله صاحبُ مصر العُبيديُّ سَنةَ 444هـ للانتِقالِ إلى أفريقية وأَطلَق يَدَها فيما تَحْتَلَّهُ من دِيارِها. نِكايةً بالمُعِزِّ بن باديس الصنهاجي الذي قَطعَ الخُطبةَ للمُستَنصِر العُبيديِّ وخَطبَ للخَليفةِ العبَّاسيِّ في أف"},{"id":1644,"era":"c5","t":"وَفاةُ الخَليفةِ العبَّاسيِّ القائمِ بأَمرِ الله وتَوَلِّي حَفيدِه المُقتَدِي الخِلافَةَ .","s":"هو الخَليفةُ، أبو جَعفرٍ القائمُ بأَمرِ الله أَميرُ المؤمنين، عبدُ الله أبو جَعفرِ بن القادرِ بالله أبي العبَّاسِ أَحمدَ ابنِ الأَميرِ إسحاقَ بن المُقتَدِر بالله أبي الفَضلِ جَعفرِ بن المُعتَضِد بالله أبي العبَّاسِ أَحمدَ. وُلِدَ سَنةَ إحدى وتِسعينَ وثلاثِ مائة في نِصفِ ذي القعدةِ، وأُمُّهُ بَدرُ الدُّجَى الأرمنية. وقِيلَ: قَطْرُ النَّدَى، بَقِيَت إلى أَثناءِ خِلافَتِه. وكان مَليحًا وَسيمًا أَبيضَ"},{"id":1645,"era":"c5","t":"أَمْرُ المُقتدِي بأَمرِ الله بإزالَةِ المُنكَراتِ في بغداد .","s":"كان مِن أَوَّلِ أَعمالِ المُقتدِي بأَمرِ الله أنَّه أَمَرَ بإخراجِ المُفْسِداتِ مِن الخَواطِئ من بغداد، وأَمَرَهُنَّ أن يُنادِينَ على أَنفُسِهِنَّ بالعارِ والفَضيحَةِ، وخَرَّبَ الخَمَّاراتِ ودُورَ الزَّوانِي والمَغانِي، وأَسكنَهُنَّ الجانِبَ الغَربيَّ مع الذُّلِّ والصَّغارِ، وخَرَّبَ أبرجةَ الحمامِ، ومَنعَ اللَّعِبَ بها، وأَمرَ الناسَ باحتِرازِ عَوراتِهِم في الحَمَّاماتِ ومَنعَ أَصحابَ الحَمَّامات"},{"id":1646,"era":"c5","t":"حُدوثُ نِيرانٍ عَظيمةٍ في سوق بغداد .","s":"في شوَّال وَقعَت نارٌ ببغداد في دُكَّانِ خَبَّازٍ بِنَهْرِ المُعَلَّى، فاحتَرقَت من السُّوقِ مائةٌ وثمانون دُكَّانًا سِوى الدُّورِ، ثم وَقعَت نارٌ في المَأمونِيَّة، ثم في الظَّفَرِيَّة، ثم في دَربِ المَطبَخِ، ثم في دارِ الخَليفَةِ، ثم في حَمَّامِ السمرقندي، ثم في بابِ الأزج ودَربِ خُراسان، ثم في الجانبِ الغربيِّ في نَهرِ طابق، ونَهرِ القلائين، والقطيعة، وبابِ البَصرَةِ، واحتَرقَ ما لا يُحصَى"},{"id":1647,"era":"c5","t":"إِعادةُ الخُطبَةِ بمَكَّةَ للمُستَنصِر بالله العُبيديِّ (الفاطِميِّ) .","s":"أَرسلَ المُستَنصِرُ بالله الفاطِميُّ صاحبُ مصر، إلى صاحبِ مَكَّةَ ابنِ أبي هاشمٍ رِسالةً وهَدِيَّةً جَليلةً، وطَلبَ منه أن يُعيدَ له الخُطبةَ بمَكَّةَ، وقال: إن أَيْمانَك وعُهودَك كانت للقائمِ، وللسُّلطانِ ألب أرسلان، وقد ماتَا، فخَطَبَ به بمَكَّةَ وقَطعَ خُطبةَ المُقتَدِي، وكانت مُدَّةُ الخُطبَةِ العبَّاسيَّة بمَكَّةَ أربعَ سنين وخَمسةَ أَشهُر."},{"id":1648,"era":"c5","t":"النِّزاعُ بين مُلوكِ الطَّوائفِ على حُكمِ مُدُنِ الأندَلُسِ .","s":"قام أبو بكرٍ محمدُ بن عبدِالعزيزِ المَنصورُ نائبُ يحيى المَأمونِ بن ذي النُّونِ في بلنسية بإعلانِ استِقلالِه فيها بعدَ أن بَلَغَه وَفاةُ يحيى المَأمونِ، وقام بمُحالَفَةِ ألفونسو السادس مَلِكِ قشتالة وليون وجيليقية مُقابِلَ دَفْعِ جِزْيَةٍ له، كما قام المُعتَمِدُ بن عبَّادٍ بانتِهازِ وَفاةِ يحيى المَأمونِ لِيُغِيرَ على قُرطُبة ويَستَولِي عليها ويَقتُل حاكِمَها ابنَ عُكاشةَ، وكان المأمونُ قد وَلَّاه"},{"id":1649,"era":"c5","t":"وَباءٌ وجَرادٌ وغَلاءٌ بِدِمَشقَ .","s":"جاء جَرادٌ في شَعبانَ بعَددِ الرَّملِ والحَصَا، فأَكلَ الغَلَّاتِ وآذَى الناسَ، وجاعوا فطُحِنَ الخَرُّوبُ بِدَقيقِ الدُّخْنِ فأَكلوهُ، ووَقعَ الوَباءُ، ثم مَنعَ اللهُ الجَرادَ من الفَسادِ، وكان يَمُرُّ ولا يَضُرُّ، فرَخُصَت الأَسعارُ، ووَقعَ غَلاءٌ شَديدٌ بدِمشق واستَمرَّ ثلاثَ سِنين."},{"id":1650,"era":"c5","t":"السَّلاجِقَةُ يُسيطِرونَ على الشامِ ودِمشقَ .","s":"في سَنةِ 463هـ مَلَكَ أتسز الرَّمْلَةَ، والبيتَ المُقدَّسَ، وحَصرَ مَدينةَ دِمشقَ، فلمَّا عادَ عنها جَعلَ يَقصِد أَعمالَها كلَّ سَنةٍ عند إدراكِ الغَلَّاتِ فيَأخُذها، فيَقوَى هو وعَسكرُه، ويَضعُف أَهلُ دِمشقَ وجُندُها، فلمَّا كان رَمضانُ سَنةَ 467هـ سار إلى دِمشقَ فحَصرَها، وأَميرُها المُعَلَّى بن حَيدرَة مِن قِبَلِ المُستَنصِر العُبيدي صاحبِ مصر، فلم يَقدِر عليها، فانصَرفَ عنها في شوَّال، فهَربَ "},{"id":1651,"era":"c5","t":"طَرْدُ الرُّومِ مِن مَدينةِ منبج .","s":"مَلَكَ نَصرُ بن محمودِ بن صالحِ بن مرداس مَدينةَ منبج، وأَجلَى عنها الرُّومَ."},{"id":1652,"era":"c5","t":"ابتِداءُ عِمارَةِ قَلعةِ دِمشقَ .","s":"لما انتَزعَ المَلِكُ المُعَظَّمُ أتسز بن أوف الخوارزمي دِمشقَ من أَيدِي العُبيديِّين سَنةَ 468هـ، شَرعَ في بِناءِ هذا الحِصْنِ المَنيعِ بدِمشقَ وكان في مكانِ القَلعةِ -أَحَدِ أَبوابِ البَلدِ- بابٌ يُعرفُ ببابِ الحَديدِ، وهو البابُ المُقابلُ لدارِ رضوان، وقد ارتَفعَ بعضُ أَبرجتِها فلم يتَكامل حتى انتَزعَ مُلْكَ البَلدِ منه المَلِكُ المُظفَّرُ تاجُ المُلوكِ تتش بن ألب أرسلان السلجوقي، فأَكمَلَها وأَ"},{"id":1653,"era":"c5","t":"مُحاولةُ أتسز الخوارزميِّ انتِزاعَ مصر مِن العُبيديِّينَ  .","s":"سار أتسز –ويُقال: أقسيس- الخوارزميُّ التُّركيُّ من دِمشقَ إلى مصر وحَصرَها، وضَيَّقَ على أَهلِها، ولم يَبقَ غير أن يَملِكَها، فاجتَمعَ أَهلُها مع ابنِ الجوهريِّ الواعظِ في الجامعِ، وبَكَوا وتَضرَّعوا ودَعَوا، فانهَزمَ أتسز من غيرِ قِتالٍ، فوَصلَ إلى دِمشقَ وقد تَفرَّق أَصحابُه، فرَأَى أَهلَها قد صانوا مُخَلَّفِيهِ وأَموالَه، فشَكرَهُم، ورَفعَ عنهم الخَراجَ تلك السَّنَةَ، وأَتَى البَيتَ المُقدَّسَ،"},{"id":1654,"era":"c5","t":"وُقوعُ فِتنَةٍ بين الحَنابِلَةِ وفُقَهاءِ النِّظامِيَّةِ  الأَشاعِرَةِ في بغداد .","s":"قَدِم ابنُ القُشيريُّ بغدادَ فجَلسَ يَتكلَّم في النِّظاميَّةِ وأَخذَ يَذُمُّ الحَنابلةَ ويَنسُبُهم إلى التَّجسِيمِ، وساعَدهُ أبو سعدٍ الصُّوفيُّ، ومالَ معه الشيخُ أبو إسحاقَ الشِّيرازيُّ، وكَتبَ إلى نِظامِ المُلْكِ يَشكُو إليه الحَنابلةَ ويَسأَلُه المَعونةَ عليهم، وذَهبَ جَماعةٌ إلى الشَّريفِ أبي جَعفرِ بن أبي موسى شَيخِ الحَنابلةِ، وهو في مَسجدِه فدافَعَ عنه آخرون، واقتَتَل الناسُ بسَببِ ذلك، وقُ"},{"id":1655,"era":"c5","t":"ابتِداءُ دَولةِ بَيتِ خوارزم شاه\n  .","s":"كان أَوَّلَهم محمدُ خوارزم شاه بن أنوشتكين، وكان أنوش تكين مَملوكًا لِرَجلٍ من غرشتان ولذلك قِيلَ له: أنوش تكين غرشه، فاشتَراهُ منه أَميرٌ من السَّلجوقيَّة اسمُه بلكابل، وكان أنوشتكين حَسَنَ الطَّريقةِ فكَبُرَ وعَلَا مَحِلُّهُ، وصار أنوشتكين مُقَدَّمًا مَرجُوعًا إليه، ووُلِدَ له محمد خوارزم شاه المذكور، فرَبَّاهُ والِدُه أنوشتكين وأَحسَنَ تَأدِيبَه، فانتَشَأ محمدٌ عارِفًا أَدِيبًا، وتَقدَّم بالعِن"},{"id":1656,"era":"c5","t":"نِهايةُ دَولةِ القَرامِطَةِ وقيام الدَّولةُ العيونيَّةُ مكانها .","s":"انتَصرَ عليهم عبدُ الله العيوني بمُساعدَةِ العبَّاسيِّين والسَّلاجِقَةِ فأَخرَجَهُم من أوال ثم من البَحرَيْنِ، وأخيرًا حَدثَت في الأَحساءِ مَعركةُ الخَندَقِ فقَضَت على دَولةِ القَرامِطَةِ نِهائِيًّا، وحَلَّت مَحِلَّها الدَّولةُ العيونيَّةُ.  والعيوني، مِن بَنِي عبدِ القَيْسِ: رَأسُ العيونيين في الأَحساءِ، نَشأَ بها، في مشارف \"العيون\" ونِسْبَتُه إليها. وأَدرَك ضَعْفَ القِرامِطَةِ فيها، فاتَّصلَ ببغ"},{"id":1657,"era":"c5","t":"وَفاةُ الشَّريفِ أبي جَعفرِ بن أبي موسى الهاشميِّ الفَقيهِ الحَنبليِّ .","s":"هو الفَقيهُ العالِمُ، إِمامُ الحَنابِلَةِ، الشَّريفُ أبو جَعفرٍ عبدُ الخالقِ بن عيسى بن أحمدَ بن محمدِ بن عيسى بن أحمدَ بن موسى بن محمدِ بن إبراهيمَ بن عبدِ الله بن معبدِ بن العبَّاسِ بن عبدِ المُطَّلِبِ, الهاشميُّ الفَقيهُ. إِمامُ الطائفةِ الحَنبليَّةِ في زَمانِه بلا مُدافَعَةٍ. وُلِدَ سَنةَ 411هـ, وهو أَجَلُّ أَصحابِ القاضي أبي يَعلَى. كان حَسَنَ الكَلامِ في المُناظَرَةِ، وَرِعًا زاهِدًا، مُتقِن"},{"id":1658,"era":"c5","t":"وَفاةُ الإمام ابنِ مَنْدَه .","s":"هو الشيخُ، الإمامُ، المُحَدِّثُ، المُفِيدُ، الكَبيرُ، المُصَنِّفُ، أبو القاسمِ عبدُ الرحمن بن الحافظِ الكَبيرِ أبي عبدِ الله  محمدِ بن إسحاقَ بن محمدِ بن يحيى بن إبراهيمَ بن أبي عبدِ الله بن مَنده  العَبدِيُّ الأصبهانيُّ. وُلِدَ سَنةَ 381هـ. سَمِعَ أَباهُ وابنَ مَرْدَوَيْهِ وخَلْقًا في أقاليمَ شَتَّى، سافَر إليها وجَمعَ شَيئًا كَثيرًا، وكان ذا وَقارٍ وسَمْتٍ حَسَنٍ، واتِّباعٍ للسُّنَّةِ وفَهْمٍ جَ"},{"id":1659,"era":"c5","t":"السُّلطانِ تُتُش أرسلان يمتلك دِمشقَ ومَقتلُ مَلِكِها أتسز الخوارزميِّ .","s":"أَقطعَ السُّلطانُ ملكشاه أَخاهُ تاجَ الدولةِ تتش الشامَ، وما يَفتَحُه في تلك النَّواحي، سَنةَ 470هـ، فأَتَى حَلَب وحَصرَها، ولَحِقَ أَهلَها مَجاعةٌ شَديدةٌ، وكان معه جَمعٌ كَثيرٌ من التُّركمان، فأَنفذَ إليه أتسز صاحِبُ دِمشقَ، يَستَنجِدُه، ويُعرِّفُه أن عَساكِرَ مصر قد حَصرَتهُ بدِمشقَ، وكان أَميرُ الجُيوشِ بَدرٌ قد سَيَّرَ عَسكرًا من مصر، ومُقَدِّمُهم قائدٌ يُعرَف بنَصرِ الدولةِ، فحَصَرَ دِمشقَ، "},{"id":1660,"era":"c5","t":"النِّزاعُ بين مُلوكِ الطَّوائفِ على حُكمِ مُدُنِ الأندَلُس .","s":"جَهَّزَ المُعتَمِدُ بن عَبَّادٍ جَيشًا بقِيادَةِ وَزيرِه أبي بكرِ بن عَمَّارٍ ووَجَّهَهُ للاستِيلاءِ على مَدينةِ مرسية، فاستَعانَ ابنُ عَمَّار بالكونت برنجيه أَميرِ برشلونه لِقاءَ المال، كما استَعانَ بعبدِالرحمن بن رشيق حاكمِ حِصْنِ بلج، فتَمَّ له ما أَرادَ من احتِلالِ مرسية وبَقِيَ ابنُ عَمَّارٍ على أَعمالِها، ثم قام بعدَ فَترَةٍ بالخُروجِ على المُعتَمِدِ وطَعَنَ فيه وفي زَوجتِه فقامَ ابنُ رشيق ع"},{"id":1661,"era":"c5","t":"مقَتْلُ ضامِنِ البَصرَةِ ابنِ عَلَّان اليَهودِيِّ .","s":"كان خمارتكين وكوهرائين يَسعَيانِ في قَتْلِ ابنِ عَلَّان اليَهوديِّ، ضامِنِ البَصرَةِ، وكان مُلتَجِئًا إلى نِظامِ المُلْكِ، وكان بين نِظامِ المُلْكِ وبين خمارتكين الشرابي وكوهرائين عَداوَةٌ، فسَعَيا باليهوديِّ لذلك، فأَمَرَ السُّلطانُ ملكشاه بتَغرِيقِه فغُرِّقَ، وانقَطعَ نِظامُ المُلْكِ الوَزيرُ عن الرُّكوبِ ثلاثةَ أيامٍ، وأَغلقَ بابَه، ثم أُشِيرَ عليه بالرُّكوبِ فرَكِبَ، وعَمِلَ للسُّلطانِ دَعوةً "},{"id":1662,"era":"c5","t":"ذِكْرُ فُتُوحِ إبراهيمَ بن مَسعودٍ الغَزنويِّ صاحِبِ غَزْنَةَ في بِلادِ الهِنْدِ .","s":"غَزا المَلِكُ إبراهيمُ بن مَسعودِ بن محمودِ بن سبكتكين بِلادَ الهندِ، فحَصرَ قَلعةَ أجود، وهي قَلعةٌ حَصينةٌ، في غايَةِ الحَصانَةِ، كَبيرةٌ، تَحوِي عشرةَ آلافِ رجلٍ من المُقاتِلَةِ، فقاتَلوهُ، وصَبَروا تحت الحِصارِ، وزَحفَ إليهم غيرَ مَرَّةٍ، فرأوا من شِدَّةِ حَربِه ما مَلأَ قُلوبَهم خَوفًا ورُعبًا، فسَلَّموا القَلعةَ إليه في الحادي والعشرين من صَفَر هذه السَّنَةِ. وكان في نَواحي الهندِ قَلعةٌ يُق"},{"id":1663,"era":"c5","t":"وَفاةُ نَصرِ بنِ مَرْوانَ، صاحِبِ دِيارِ بَكرٍ، ومِلْكُ ابنِه مَنصورٍ بَعدِه .","s":"هو نَصرُ بن أحمدَ بن مَروانَ بن دوستك الكُرديُّ، صاحِبُ دِيارِ بَكرٍ، كان مَلِكًا عادِلًا، خَفيفَ الوَطْأَةِ، حَسَنَ السِّيرَةِ، كَثيرَ الإحسانِ إلى الناسِ. وعَمُرَت ميافارقين في أيَّامِه أَحسنَ عِمارَةٍ، ولَقِيَ الناسُ منه الخيرَ والبَركةَ في وِلايَتِه. وكان يَتفقَّد أَحوالَ الناسِ ويَسألُ عن أَحوالِهم ومَن غابَ منهم، وما شُوهِدَت ميافارقين أَعمَرَ ممَّا كانت في أيامِ نِظامِ الدِّينِ، ولا أَغنَى "},{"id":1664,"era":"c5","t":"نِهايةُ الدَّولةِ المرداسية بِحَلَب  .","s":"مَلَكَ شَرفُ الدولةِ مُسلمُ بن قُريشٍ العقيليُّ، صاحبُ المَوصِل، مَدينةَ حَلَب؛ وسَببُ ذلك أنَّ تاجَ الدولةِ تتش بن ألب أرسلان حَصرَها مَرَّةً بعدَ أُخرى، فاشتَدَّ الحِصارُ بأَهلِها، وكان شَرفُ الدولةِ يُواصِلُهم بالغَلَّاتِ وغَيرِها. ثم إنَّ تتش حَصرَها هذه السَّنَةَ، وأَقامَ عليها أيامًا ورَحلَ عنها ومَلَكَ بزاعة والبيرة، وأَحرقَ ربض عزاز، وعادَ إلى دِمشقَ. فلمَّا رَحلَ عنها تاجُ الدولةِ استَدعَ"},{"id":1665,"era":"c5","t":"خُروجُ تكش على السُّلطانِ ملكشاه .","s":"سار السُّلطانُ ملكشاه إلى الرَّيِّ، وعَرضَ العَسكرَ، فأَسقطَ منهم سبعةَ آلافِ رجُلٍ لم يَرضَ حالَهم، فمَضوا إلى تكش -قِيلَ: إنه مملوك لملكشاه. وقِيلَ: إنه لَصيق له وإن أبوه النُّعمان-، وهو ببوشنج، فقَوِيَ بهم، وأَظهرَ العِصيانَ على أَخيهِ ملكشاه، واستَولَى على مرو الروذ، ومرو الشاهجان، وترمذ، وغيرَها، وسار إلى نيسابور طامِعًا في مُلْكِ خُراسان، وقِيلَ: إن نِظامَ المُلْكِ قال للسُّلطانِ لمَّا أَمرَ"},{"id":1666,"era":"c5","t":"اغتِيالُ عليٍّ الصُّليحيِّ زَعيمِ اليَمنِ الشِّيعيِّ القُرمطيِّ .","s":"هو أبو الحَسنِ عليُّ بن محمدِ بن عليٍّ المُلقَّب بالصليحيِّ، كان أَبوهُ قاضِيًا باليَمنِ سُنِّيًّا، أمَّا الصليحيُّ فتَعلَّم العِلمَ وبَرعَ في أَشياءَ كَثيرةٍ من العُلومِ، وكان شِيعِيًّا على مَذهبِ القَرامِطَةِ، ثم كان يَدُلُّ بالحَجِيجِ مُدَّةَ خمس عشرة سَنَةً، استَحوذَ على بلادِ اليمنِ بكمالها بكاملها في أَقصرِ مُدَّةٍ، واستَوثقَ له المُلْكُ بها سَنةَ خمسٍ وخمسين وأربعمائة، وخَطبَ للمُستَنصِر ال"},{"id":1667,"era":"c5","t":"فَتْحُ أنطرطوس على يَدِ تتش بنِ ألب أرسلان .","s":"سار تتش بنُ ألب أرسلان صاحِبُ دِمشقَ، بعدَ عَوْدِ شَرفِ الدولةِ عن دِمشقَ، وقَصدَ الساحِلَ الشاميَّ، فافتَتحَ أنطرطوس، وبَعضًا مِن الحُصونِ، وعادَ إلى دِمشقَ."},{"id":1668,"era":"c5","t":"حِصارُ الأَميرِ تَميمِ بنِ المُعِزِّ بن باديس مَدينةَ قابس .","s":"حَصَرَ الأَميرُ تَميمُ بنُ المُعِزِّ بن باديس، صاحبُ إفريقية، مَدينةَ قابس حِصارًا شَديدًا، وضَيَّقَ على أَهلِها، وعاثَ عَساكِرُه في بَساتِينِها المَعروفَةِ بالغابَةِ فأَفسَدوها."},{"id":1669,"era":"c5","t":"النِّزاعُ بين مُلوكِ الطَّوائفِ على حُكمِ مُدُنٍ بالأندَلُس\n  .","s":"بعدَ أن أَصبحَ أحمدُ بن سُليمانَ بن هود أَميرًا لسرقسطة بعَهدِ أَبيهِ تُوفِّي في هذا العامِ وكان يُلقَّب بالمُقتَدِر باللهِ، وكان قبلَ وَفاتِه قد قَسَّمَ مَملكَتَه بين وَلدَيهِ فأَعطَى المُؤتَمن سرقسطة وأَعمالَها، وأَعطَى المُنذِرَ بلادَ الثَّغرِ الأعلى دانية ولاردة، ولكنَّ المُؤتَمن أَعلَن الحَربَ على أَخيهِ للاستِيلاءِ على حِصَّتِه مُستعينًا بكمبيادرو النَّصرانيِّ حَليفَ أَبيهِ فقامَ المُنذِرُ ب"},{"id":1670,"era":"c5","t":"وَفاةُ داودَ بنِ السُّلطانِ ملكشاه .","s":"هو داودُ بنُ السُّلطانِ ملك شاه، جَزَعَ عليه والدُه جَزَعًا شَديدًا، وحَزِنَ حُزنًا عَظيمًا، ومَنعَ مِن أَخْذِهِ وغَسْلِه، حتى تَغيَّرت رائحتُه، وأَرادَ قَتْلَ نَفسِه مَرَّاتٍ، فمَنَعهُ خَواصُّه، وأَمرَ بالنِّياحَةِ عليه في البلدِ، ففُعِلَ ذلك عِدَّةَ أيامٍ، وجَلسَ له وَزيرُ الخَليفةِ في العَزاءِ ببغداد."},{"id":1671,"era":"c5","t":"وَفاةُ أبي الوَليدِ الباجي المالكيِّ .","s":"هو الإمامُ، العَلَّامةُ، الحافظُ، ذو الفُنونِ، القاضي أبو الوَليدِ سُليمانُ بنُ خَلَفِ بنِ سعدِ بن أيُّوبَ التَّجيبيُّ الأندَلُسيُّ، القُرطُبيُّ، الباجيُّ، الفَقِيهُ المالكيُّ، صاحبُ التَّصانيفِ. وَلِدَ سَنةَ 403هـ أَصلُه من مَدينةِ بطليوس، فتَحوَّل جَدُّهُ إلى باجةَ -بُليدَة بقُربِ إشبيلية- فنُسِبَ إليها، وليست باجة المدينةَ التي بإفريقية، التي يُنسَب إليها الحافظُ أبو محمدٍ عبدُ الله بنُ محمدِ ب"},{"id":1672,"era":"c5","t":"الفِتنَةُ ببغداد بين الشافِعيَّةِ والحَنابِلَةِ .","s":"وَرَدَ إلى بغداد الشَّريفُ أبو القاسمِ البكريُّ، المغربيُّ، الواعظُ، وكان أَشعريَّ المَذهبِ، وكان قد قَصَدَ نِظامَ المُلْكِ، فأَحَبَّهُ ومالَ إليه، وسَيَّرَهُ إلى بغداد، وأَجرَى عليه الجِرايةَ الوافِرةَ، فوَعظَ بالمدرسةِ النِّظاميَّةِ، وكان يَذكُر الحَنابِلَةِ ويَعِيبُهم، ويقول: \"وما كَفَرَ سُليمانُ ولكنَّ الشياطين كَفَروا، والله ما كَفَرَ أَحمدُ ولكنَّ أَصحابَه كَفَروا، ثم إنَّه قَصَدَ يومًا دارَ"},{"id":1673,"era":"c5","t":"استِيلاءُ المُرابطين على مُعظَمِ بِلادِ المَغرِب. .","s":"كان يوسفُ بن تاشفين قد استَفحلَ أَمرُه بالمَغربِ واستَولَى على أَكثرِ البلادِ, فلمَّا سَمِعَ الأَميرُ أبو بكرِ بن عُمرَ بما آلَ إليه أَمرُ يوسفَ بن تاشفين وما مَنحَه الله من النصرِ أَقبلَ من الصحراءِ لِيَختَبِرَ أَحوالَه، ويُقالُ: إنه كان مُضمِرًا لِعَزلِه وتَولِيَةِ غَيرِه فأَحَسَّ يوسفُ بذلك فشاوَرَ زَوجتَه زينبَ بنت إسحاقَ -كان قد تَزوَّجَها بعدَ أبي بكر بن عُمرَ- فقالت له: إنَّ ابنَ عَمِّك مُت"},{"id":1674,"era":"c5","t":"مَسيرُ أبي إسحاقَ الشِّيرازيِّ بِرِسالةٍ من الخَليفَةِ إلى ملكشاه .","s":"نَفَذَ الشيخُ أبو إسحاقَ الشِّيرازيُّ رَسولًا إلى السُّلطانِ ملكشاه والوَزيرِ نِظامِ المُلْكِ بِرسالةٍ مَضمونُها تتضمن الشَّكوَى من العَميدِ أبي الفَتحِ بن أبي اللَّيثِ، عَميدِ العِراقِ، وأَمرَهُ أن يُنهِي ما يجري على البلادِ من النُّظَّارِ، وقد جَرَى بينه وبين إمامِ الحَرَمينِ أبي المَعالي الجُوينيِّ مُناظرَةٌ بِحَضرَةِ نِظامِ المُلْكِ، وأُجِيبَ إلى جَميعِ ما التَمسَهُ، ولمَّا عاد أُهِينَ العَميد"},{"id":1675,"era":"c5","t":"استِيلاءُ مالِكِ بن عَلَويٍّ على القَيروانِ ثم استعادتها منه .","s":"جَمعَ مَالكُ بن عَلويٍّ الصَّخريُّ العَربَ فأَكثرَ، وسارَ إلى المَهدِيَّةِ فحَصرَها، فقامَ الأَميرُ تَميمُ بن المُعِزِّ قِيامًا تامًّا، ورَحَّلَهُ عنها، ولم يَظفَر منها بشيءٍ، فسار مالِكُ منها إلى القَيروانِ فحَصرَها ومَلِكَها، فجَرَّدَ إليه تَميمٌ العَساكرَ العَظيمةَ، فحَصَروهُ بها، فلمَّا رأى مالِكٌ أنَّه لا طاقةَ له بتَميمٍ خَرجَ عنها وتَركَها، فاستَولَى عليها عَسكرُ تَميمٍ وعادَت إلى مُلكِه كم"},{"id":1676,"era":"c5","t":"حِصارُ شَرفِ الدَّولةِ صاحِبِ حَلَب لِدِمشقَ .","s":"جَمعَ تاجُ الدولةِ تتش جَمْعًا كَثيرًا، وسار عن بغداد، وقَصدَ بِلادَ الرُّومِ أنطاكية وما جاوَرَها، فسَمِعَ صاحِبُ حَلَب، شَرفُ الدولةِ أبو المَكارِم مُسلمُ بن قُريشٍ أَميرُ بَنِي عُقيلٍ الخَبرَ، فخافَهُ، فجَمعَ العَربَ من عُقيلٍ، والأَكرادَ، وغَيرَهم، فاجتَمعَ معه جَمْعٌ كَثيرٌ، فراسَلَ صاحِبَ مصر الفاطميَّ يَطلُب منه إِرسالَ نَجدَةٍ إليه لِيَحصُرَ دِمشقَ، فوَعَدهُ ذلك فسار إليها. فلمَّا سَمِعَ ت"},{"id":1677,"era":"c5","t":"وَفاةُ الشيخِ أبي إسحاقَ الشِّيرازيِّ .","s":"هو الشيخُ، الإمامُ، القُدوَةُ، المُجتَهِد، شيخُ الإسلامِ، أبو إسحاقَ إبراهيمُ بن عليِّ بن يوسفَ الفيروزاباذي الشِّيرازيُّ، الشافعيُّ، الأشعريُّ, نَزيل بغدادَ، قِيلَ: لَقَبُه جَمالُ الدِّينِ، وُلِدَ سَنةَ 393هـ  في قَريةِ فيروزباذ من قُرَى فارس، وقِيلَ: هي مَدينَة خوارزم، وهو شيخُ الشافعيةِ في عَصرِه, ومُدَرِّسُ النِّظاميَّةِ ببغداد، تَفَقَّه بفارس على أبي عبدِ الله البَيضاوي، ثم قدم بغداد سَنةَ خَ"},{"id":1678,"era":"c5","t":"عِصيانُ تكش على السُّلطانِ ملكشاه .","s":"عاوَدَ تكش العِصيانَ -قِيلَ: إن تكش مَملوكٌ لملكشاه. وقِيلَ: إنه لَصيقٌ له وإن أَباهُ النُّعمانُ- وكان أَصحابُ تكش يُؤثِرون الاختلاطَ، فحَسَّنوا له مُفارقةَ طاعَةِ ملكشاه، فأَجابَهم، وسارَ معهم، فمَلَكَ مرو الروذ وغيرَها إلى قَلعةٍ تُقارِب سرخس وهي لمسعودِ ابنِ الأَميرِ ياخز، وقد حَصَّنَها جُهْدَهُ، فحَصَروهُ بها، ولم يَبقَ غيرُ أَخْذِها منه، فاتَّفقَ أبو الفُتوحِ الطُّوسيُّ، صاحبُ نِظامِ المُلْكِ"},{"id":1679,"era":"c5","t":"فَتحُ سُليمانَ بنِ قتلمش أنطاكيةَ .","s":"سار سُليمانُ بن قتلمش، صاحِبُ قونية وأقصرا وأَعمالِها من بلادِ الرُّومِ، إلى الشم الشام، فمَلَكَ مَدينةَ أنطاكية من أرضِ الشامِ، وكانت بَيَدِ الرُّومِ من سَنةِ 358هـ، وسَببُ مُلْكِ سُليمانَ المدينةَ أن صاحِبَها الفردوس الرُّوميَّ كان قد سار عنها إلى بِلادِ الرُّومِ، ورَتَّبَ بها شِحْنَةً – مَسؤول عن ضَبْطِ المدينة-، وكان الفردوس مُسيئًا إلى أَهلِها، وإلى جُنْدِه أيضًا، فاتَّفقَ ابنُه والشِّحْنَةِ "},{"id":1680,"era":"c5","t":"وَفاةُ أبي المَعالِي الجُوينيِّ إِمامِ الحَرَمَين .","s":"هو أبو المَعالِي عبدُ المَلِكِ ابنِ الشيخِ أبي محمدٍ عبدِ الله بن يوسفَ بن محمدِ بن حيويهِ، الجُوينيُّ، الفَقيهُ الشافعيُّ، المُلَقَّب ضِياءَ الدِّين، المعروف بإمامِ الحَرمَينِ؛ أَعلمُ المُتأخِّرين مِن أَصحابِ الإمامِ الشافعيِّ على الإطلاقِ، المُجْمَع على إِمامَتِه، المُتَّفَق على غَزارَةِ مادَّتِه، وتَفَنُّنِه في العُلومِ من الأُصولِ والفُروعِ والأَدَبِ وغَيرِ ذلك، وُلِدَ في مُحرَّم سَنةَ 419هـ, "},{"id":1681,"era":"c5","t":"سُقوطُ طُليطِلَة المُسلِمَة في أَيدِي القشتاليين .","s":"في هذه السَّنَةِ استَولَى الفِرنجُ على مَدينةِ طُليطِلة من بِلادِ الأندلس، وأَخذُوها من المسلمين، وهي من أَكبرِ البلادِ وأَحصَنِها. وسببُ ذلك أن الأذفونش، (ألفونسو السادس) مَلِكَ قشتالة، كان قد قَوِيَ شَأنُه، وعَظُمَ مُلكُه، وكَثُرت عَساكِرُه، مُذ تَفرَّقَت بِلادُ الأندلس، وصار كلُّ بَلدٍ بِيَدِ مَلِكٍ، كما دَبَّ النِّزاعُ بينهم واستَعانوا بالفِرنجَةِ على بَعضٍ، فحينئذٍ طَمِعَ الفِرنجُ فيهم، وأَخَ"},{"id":1682,"era":"c5","t":"استِنجادُ مُلوكِ الطَّوائفِ بيُوسفَ بنِ تاشفين .","s":"بعدَ أن قامَ ألفونسو السادسُ –أدفونش- بالاستِيلاءِ على طُليطلة بدأَ بتَهديدِ إشبيلية، فأَرسلَ كِتابًا لصاحِبِها المُعتَمِد بن عبَّاد قال فيه: \"مِن الإمبراطورِ ذي الملتين المَلِكِ أدفونش بن شانجة، إلى المُعتَمِد بالله، سَدَّدَ الله آراءَه، وبَصَّرَهُ مَقاصِدَ الرَّشادِ. قد أَبصرتَ تَزَلزُلَ أَقطارِ طُليطلة، وحِصارَها في سالفِ هذه السِّنين، فأَسلَمتُم إخوانَكم، وعَطَّلتُم بالدَّعَةِ زَمانَكم، والحَذ"},{"id":1683,"era":"c5","t":"مُلوكُ الفِرنجَةِ يَجمَعون جُنودَهم لِلِقاءِ ابنِ تاشفين زَعيمِ المُرابِطين .","s":"بعدَ أن رَدَّ ألفونسو على رِسالَةِ يوسف بن تاشفين واختارَ الحَربَ بَدأَ بالتَّجهيزِ فحاصَرَ مَدينةَ سَرقُسطة بعدَما استَولَى على طُليطلة، كما قامَ سانشو راميرو بمُحاصَرةِ مَدينةِ طرطوشة ثم لم يَلبَث أن فَكَّا الحِصارَ وتَداعَى مُلوكُ الفِرنجِ وجَمَعوا جُنودَهم وفيهم المُرتَزَقَة للِقاءِ يوسفَ بنِ تاشفين."},{"id":1684,"era":"c5","t":"نِهايَةُ الدَّولةِ العامِريَّةِ في الأندلس على يَدِ دَولةِ ابن ذي النُّونِ .","s":"تُوفِّي أبو بكرٍ محمدُ بن عبدِالعزيز بنِ المنصورِ بن أبي عامرٍ أَميرُ بلنسية، واستُخلِفَ بعدَه ابنُه عُثمانُ أبو عَمرٍو، ولكنَّ القادِرَ بن ذي النونِ الذي انتَهَت دَولتُه في طُليطلة على يَدِ ألفونسو يَمُدُّهُ ألفونسو نَفسُه ويُساعِدُه على الاستِيلاءِ على بلنسية فيُسَيِّرُ له سَرِيَّةً قَويَّةً فيقومُ باستِخلاصِ بلنسية من عُثمانَ ويُقيمُ فيها دَولةَ بني ذي النون."},{"id":1685,"era":"c5","t":"انتِهاءُ دَولةِ بَنِي مَرْوان في الأندَلُسِ على يَدِ ابن جَهيرٍ .","s":"قام ابنُ جَهيرٍ بإنهاءِ دَولةِ بَنِي مَروان في كلٍّ مِن آمد التي سَلَّمَها أَهلُها إليه بعدَ حِصارِها وكانوا قد سَئِموا مِن المُعامَلَةِ السَّيِّئَةِ من وُلاتِها وكان بينهم كَثيرٌ من النَّصارَى المتحكمين، كما تَمَلَّكَ ميافارقين وأَنهَى فيها حُكمَ بَنِي مَروان، وهي أيضًا سَلَّمَها أَهلُها، ثم مَلَكَ جَزيرةَ ابنِ عُمرَ وهي أيضا لبَنِي مَروان فحاصَروها ودَخَلوا حِصنَها عُنوةً ومَلَكوها، فكان هذا إنه"},{"id":1686,"era":"c5","t":"مَقتَلُ شَرَفِ الدَّولةِ صاحِبِ حَلَب وتَوَلِّي أَخيهِ بعدَه  .","s":"هو السُّلطانُ الأَميرُ شَرفِ الدَّولةِ أبو المَكارِمِ مُسلِمُ بن مَلِكِ العَربِ أبي المعالي قُريشِ بن بدران بن مُقَلَّدٍ حُسام الدَّولةِ أبي حَسَّان بن المُسَيِّب بنِ رافعٍ العقيليُّ, كان يَتَرَفَّض كأَبيهِ, ونَهَبَ أَبوهُ دارَ الخِلافَةِ في فِتنَةِ البساسيري، وأَجارَ القائمَ بالله, وماتَ سَنةَ 453هـ كَهْلًا، فقامَ شَرفُ الدولةِ بعدَه، واستَولَى على دِيارِ رَبيعةَ، ومُضَر، وتَمَلَّكَ حَلَب، وأَخذَ"},{"id":1687,"era":"c5","t":"حِصارُ دِمشقَ مِن قِبَلِ العُبَيدِيِّينَ الفاطِمِيِّين .","s":"سارَ أَميرُ الجُيوشِ في عَساكرِ مصر إلى الشامِ، فحَصَرَ دِمشقَ، وبها صاحِبُها تاجُ الدولةِ تتش، فضَيَّقَ عليه، وقاتَلَهُ، فلم يَظفَر منها بشيءٍ، فرَحلَ عنها عائِدًا إلى مصر."},{"id":1688,"era":"c5","t":"وَفاةُ أبي عبدِالله الدَّامغاني .","s":"هو العَلَّامةُ، البارِعُ، مُفتِي العِراقِ، قاضي القُضاةِ، أبو عبدِ الله محمدُ بن عليِّ بن محمدِ بن حَسنِ بن عبدِ الوهاب بن حسويهِ الدَّامغاني الحَنفيُّ. وُلِدَ بدامغان، سَنةَ 398هـ, وتَفَقَّهَ بخُراسان، وقَدِمَ بغدادَ شابًّا، فأَخَذَ عن القدوريِّ، وحَصَّل المَذهبَ على فَقْرٍ شَديدٍ. فكان يَحرُس في دَربِ الرِّياحِ، تَفَقَّهَ بدامغان على أبي صالحٍ الفَقيهِ، ثم قَصدَ نيسابور، فأقم فأَقامَ أَربعةَ أَش"},{"id":1689,"era":"c5","t":"الوَقعَةُ بين تتش وبين سُليمانَ بنِ قتلمش صاحِبِ حَلَب .","s":"كانت الوَقعةُ بين تتش بن ألب أرسلان صاحِبِ دِمشقَ وبين سُليمانَ بن قتلمش صاحِبِ حَلَب وأنطاكية وتلك الناحيَةِ، فانهَزمَ أَصحابُ سُليمانَ وقَتَلَ هو نَفسَه بخِنجَر كان معه، وقِيلَ: بل جاءَهُ سَهمٌ على وَجهِه فسَقطَ مَيِّتًا مِن فَوْرِه، ويُذكَر أنَّه دُفِنَ بجانبِ مُسلمِ بنِ قُريشٍ صاحبِ حَلَب قَبلَه وهو مَن قَتلَه في أَحداثِ السَّنَةِ سابقة السَّابقةِ."},{"id":1690,"era":"c5","t":"ضَمُّ ملكشاه حَلَب والرها وحران لِمُلْكِه .","s":"سارَ السُّلطانُ ملكشاه من أصبهان إلى حَلَب فمَلَكَها، ومَلَكَ ما بين ذلك من البلادِ التي مَرَّ بها، مثل حران والرها وقَلعَة جعبر، وكان جعبر شَيخًا كبيرًا قد عَمِيَ، وله وَلَدان، وكان قُطّاعُ الطَّريقِ يَلجَأون إليها فيَتَحصَّنون بها، فرَاسَلَ السُّلطانُ سابقَ بن جعبر في تَسليمِها فامتَنَع عليه، فنَصَبَ عليها المناجيق المجانيق والعرادات ففَتَحَها وأَمَرَ بِقَتْلِ سابق."},{"id":1691,"era":"c5","t":"مَوقِعَةُ الزَّلَّاقَة وهَزيمَةُ النَّصارَى أَمامَ المُرابِطين .","s":"وكان المُعتَمِدُ على الله أبو عبدِ الله محمدُ بن عَبَّاد أَعظمَ مُلوكِ الأندلسِ من المسلمين، وكان يَملِك أكثرَ البلادِ مثل قُرطُبة وإشبيلية، وكان يُؤدِّي إلى الفونسو السادس -الأذفونش- ضَريبةً كلَّ سَنَةٍ. فلمَّا مَلَكَ الفونسو طليطلة أَرسلَ إليه المُعتَمِدُ الضَّريبةَ على عادَتِه، فرَدَّها عليه ولم يَقبَلها منه، فأَرسلَ إليه يَتهدَّدهُ ويَتوعَّدهُ أنَّه يَسيرُ إلى مَدينةِ قُرطُبة ويَتملَّكها إلَّا"},{"id":1692,"era":"c5","t":"دُخولُ ملكشاه بَغدادَ لأَوَّلِ مَرَّةٍ .","s":"دَخَلَ السُّلطانُ ملكشاه بغدادَ في ذي الحجَّةِ، بعدَ أن فَتَحَ حَلَبَ وغَيرَها من بلادِ الشَّامِ والجَزيرةِ، وهي أَوَّلُ مَرَّةٍ يَدخُل فيها بغدادَ، ونَزلَ بدارِ المَملكةِ، وأَرسلَ إلى الخَليفةِ هَدايا كَثيرةً، فقَبِلَها الخَليفةُ، ومِن الغَدِ أَرسلَ نِظامُ المُلْكِ إلى الخَليفَةِ خَدمةً كَثيرةً، فقَبِلَها، وزارَ السُّلطانُ ونِظامُ المُلْكِ مَشهدَ موسى بن جَعفرٍ، وقَبْرَ مَعروفٍ، وأحمدَ بن حَنبلٍ "},{"id":1693,"era":"c5","t":"الخَليفةُ العبَّاسي المُقتَدِي يَتَزوَّج ابنةَ السُّلطان السلجوقي ملكشاه .","s":"تَزوَّج الخَليفةُ المُقتَدِي بابنةِ السُّلطانِ ملكشاه فاشتَرطَت عليه أن لا يُبقِي تَحتَه لا زَوجةً ولا سُرِّيَّةً إلا هي وَحدَها، فأُجِيبَت رَغبتُها. فنُقِلَ جِهازُها إلى دارِ الخِلافَةِ على مائةٍ وثلاثين جَمَلًا مُجَلَّلَةً بالدِّيباجِ الرُّوميِّ، وكان أَكثرَ الأحمالِ الذهبُ والفِضَّةُ وعلى أربعٍ وسبعين بَغْلًا مُجَلَّلَةً بأَنواعِ الدِّيباجِ المَلَكِيِّ، وأَجراسُها وقَلائدُها من الذهبِ والفِضَّة"},{"id":1694,"era":"c5","t":"فَتحُ الرُّومِ مَدينةَ زويلة من إفريقية .","s":"كان الأَميرُ تَميمُ بن المُعِزِّ بن باديس صاحِب المَهدِيَّةِ قد أَكثرَ غَزْوَ بِلادِ الرُّومِ في البَحرِ، فخَرَّبَها، وشَتَّتَ أَهلَها، فاجتَمَعوا من كلِّ جِهَةٍ، واتَّفَقوا على إنشاءِ الشواني -سُفُن حَربيَّة ضَخمَة - لِغَزوِ المَهدِيَّة، ودَخلَ معهم البيشانيون، والجنوبيون، وهما من الفِرنج، فأَقاموا يُعمِّرون الأُسطولَ أَربعَ سِنين، واجتَمَعوا بجَزيرَةِ قوصرة في أَربعِ مائةِ قطعةٍ، فأَرادَ تَميمٌ "},{"id":1695,"era":"c5","t":"الفِتنَةُ ببغداد .","s":"شَرَعَ أَهلُ بابِ البَصرَةِ في بِناءِ القَنطرَةِ الجَديدةِ، واتُّفِقَ أن كوهرائين سار في سميرية -نوع من السُّفُن-، وأَصحابُه يَسيرونَ على شاطئِ دِجلَة بسميريه، فوَقفَ أَهلُ بابِ الأزج على امرأةٍ كانت تَسقِي الناسَ من مُزَمَّلَةٍ لها على دِجلَة، فحَمَلوا عليها، على عادةٍ لهم، وجَعَلوا يَكسِرونَ الجِرارَ، ويَقولون: الماءُ للسَّبيلِ! فلما رَأت سعدَ الدولةِ كوهرائين استَغاثَت به، فأَمَرَ بإبعادِهم عنه"},{"id":1696,"era":"c5","t":"فَتْحُ ملكشاه مَدينةَ سمرقند .","s":"كان قد مَلَكَ سمرقند أحمدُ خان بن خضر خان، وهو ابنُ أخي تركان خاتون، زَوجةِ السُّلطانِ ملكشاه، وكان صَبِيًّا ظالِمًا، قَبيحَ السِّيرَةِ، يُكثِر مُصادَرةَ الرَّعيَّةِ، فنَفَروا منه، وكَتَبوا إلى السُّلطانِ سِرًّا يَستَغيثون به، ويَسأَلونَه القُدومَ عليهم لِيَملِك بِلادَهم، فتَحرَّكَت دَواعي السُّلطانِ إلى مُلْكِها، فسار من أصبهان، وجَمعَ العَساكرَ من البلادِ جَميعِها، فعَبَرَ النهرَ فلمَّا قَطعَ ال"},{"id":1697,"era":"c5","t":"غَزْوُ السُّلطانِ ملكشاه كاشغرَ .","s":"وسار السُّلطانُ قاصِدًا كاشغر، فبَلَغَ إلى يوزكند، وأَرسلَ منها رُسُلًا إلى مَلِكِ كاشغر يَأمُرهُ بإقامَةِ الخُطبَةِ، وضَرْبِ السِّكَّةِ باسمِه ويَتوَعَّدهُ إن خالَفَ بالمَسيرِ إليه. ففَعلَ ذلك وأَطاعَ، وحَضرَ عند السُّلطانِ، فأَكرَمَه وعَظَّمَه، وتابَعَ الإنعامَ عليه، وأَعادَهُ إلى بَلدِه."},{"id":1698,"era":"c5","t":"غَلاءٌ وقَحْطٌ بإفريقية .","s":"كان بإفريقية هذه السَّنَةَ غَلاءٌ شَديدٌ، وبَقِيَ كذلك إلى سَنةِ أربعٍ وثمانين، وصَلُحَت أَحوالُ أَهلِها، وأَخصَبَت البلادُ، ورَخُصَت الأسعارُ، وأَكثرَ أَهلُها الزَّرعَ."},{"id":1699,"era":"c5","t":"فَتْحُ عَساكِر صاحِبِ مصر العُبيدِيِّ عَكَّا وغَيرَها من الشامِ .","s":"خَرجَت عَساكرُ صاحبِ مصر العُبيديِّ بقِيادَةِ بَدرٍ أَميرِ الجُيوشِ إلى الشامِ في جَماعةٍ من المُقدِّمين، فحَصَروا مَدينةَ صُور، وكان قد تَغلَّبَ عليها القاضي عَيْنُ الدولةِ بن أبي عَقيلٍ، وامتَنعَ عليهم، ثم تُوفِّي، ووَلِيَها أَولادُه، فحَصرَهُم العَسكرُ المصريُّ فلم يكُن لهم من القُوَّةِ ما يَمتَنِعون بها، فسَلَّموها إليهم، ثم سار بدرُ بالعَسكرِ عنها إلى مَدينةِ صَيْدا، ففَعلوا بها كذلك، ثم سارو"},{"id":1700,"era":"c5","t":"عِصيانُ أَهلِ سمرقند على نائبِ السُّلطانِ ملكشاه .","s":"لمَّا رَجعَ السُّلطانُ ملكشاه من كاشغر إلى خُراسان، وأَبعدَ عن سمرقند لم يَتَّفِق أَهلُها وعَسكرُها المعروفون بالجَكلِيَّة مع العَميدِ أبي طاهرٍ، نائبِ السُّلطانِ عندهم، حتى كادوا يَثِبونَ عليه، فاحتالَ حتى خَرجَ مِن عندهم، ومَضَى إلى خوارزم. كان مُقدِّم الجَكلِيَّة واسمُه عَيْنُ الدولةِ، قد خافَ السُّلطانَ لهذا الحادثِ، فكاتَبَ يعقوبَ تكين أخا مَلِكِ كاشغر، ومَملَكَتُه تُعرَف بآب نباشي، وبِيَدِه "},{"id":1701,"era":"c5","t":"طَلَبُ السُّلطانِ ملكشاه يعَقوبَ أخي مَلِكِ كاشغر  .","s":"سارَ السُّلطانُ ملكشاه في إثْرِ يعقوبَ لِقَتلِه مُقدِّمَ الجَكليَّة, والذي دَخلَ إلى أَخيهِ بكاشغر مُستجِيرًا به، فسَمِعَ السُّلطانُ بذلك، فأَرسلَ إلى مَلِكِ كاشغر يَتوعَّدُه، إن لم يُرسِلهُ إليه، أن يَقصِد بِلادَه، ويَصيرُ هو العَدُوَّ، فخافَ أن يَمنَع السُّلطانَ، فأَدَّاهُ اجتِهادُه إلى أن قَبَضَ على أَخيهِ يعقوبَ، وأَظهرَ أنه كان في طَلَبِه، فظَفَرَ به، وسَيَّرَهُ مع وَلَدِه، وجَماعةٍ من أَصحاب"},{"id":1702,"era":"c5","t":"عُدوانُ ابنِ عَلَوِيٍّ  مَلِكِ العَربِ على مَدينةِ سوسة بإفريقية  .","s":"نَقَضَ ابنُ عَلَوِيٍّ ما بينه وبين تَميمِ بن المُعِزِّ بن باديس أَميرِ إفريقية من العَهْدِ، وسار في جَمْعٍ مِن عَشيرَتِه العَربِ، فوَصلَ إلى مَدينةِ سوسة من بلادِ إفريقية، وأَهلُها غارُّونَ لم يَعلَموا به، فدَخلَها عُنوةً، وجَرَى بينه وبين مَن بها من العَسكرِ والعامَّةِ قِتالٌ، فقُتِلَ من الطَّائِفَتينِ جَماعةٌ وكَثُرَ القَتلُ في أَصحابِه والأَسْرُ، وعَلِمَ أنه لا يَتِمُّ له مع تَميمٍ حَالٌ، ففارَ"},{"id":1703,"era":"c5","t":"وَفاةُ أبي بكرٍ السَّرخسي الحنفيِّ .","s":"هو شَمسُ الأئمَّةِ أبو بكرٍ محمدُ بن أحمدَ بن سَهلِ السَّرخسي، صاحِبُ ((المبسوط)) بَرَعَ في الفِقهِ وعِلْمِ الكلامِ والأُصولِ والمُناظَرَةِ، أَحدُ الفُحولِ الأئمَّةِ الكِبارِ أَصحابِ الفُنونِ، لَزِمَ الإمامُ شَمسُ الأئمَّةِ أبا محمدٍ عبدَ العزيز الحلوانيَّ حتى تَخرَّجَ به وصارَ أَنظَرَ أَهلِ زَمانِه وأَخذَ في التَّصنيفِ وناظَرَ الأَقرانَ فظَهرَ اسمُه وشاعَ خَبرُه. سُجِنَ بسَببِ فَتوى له وبَقِيَ في"},{"id":1704,"era":"c5","t":"الفِتنَةُ بين السُّنَّةِ والشِّيعَةِ ببغداد .","s":"كَبَسَ أَهلُ بابِ البَصرَةِ السُّنَّةُ الكَرخَ، فقَتَلوا رَجلًا وجَرَحوا آخرَ، فأَغلقَ الشِّيعةُ من أَهلِ الكَرخِ الأَسواقَ، ورَفَعوا المَصاحِفَ، وحَمَلوا ثِيابَ الرَّجُلينِ وهي بالدَّمِ، ومَضوا إلى دارِ العَميدِ كَمالِ المُلْكِ أبي الفَتحِ الدهستاني مُستَغيثينَ، فأَرسلَ إلى النَّقيبِ طِرادِ بن محمدٍ يَطلُب منه إِحضارَ القاتِلين، فقَصَدَ طِرادٌ دارَ الأميرِ بوزان بقَصرِ ابنِ المأمونِ، فطالَبَه بُو"},{"id":1705,"era":"c5","t":"الفِتنَةُ الثانيةُ بين السُّنَّةِ والشِّيعَةِ ببغداد .","s":"كَثُرَت الفِتَنُ ببغداد بين الشِّيعةِ من أَهلِ الكَرخِ وغَيرِها من المَحالِّ مِن أَهلِ السُّنَّةِ، وقُتِلَ بينهم عَددٌ كَثيرٌ، واستَولَى أَهلُ المَحالِّ على قِطعَةٍ كَبيرةٍ من نَهرِ الدَّجاجِ، فنَهَبوها، وأَحرَقوها، فنَزل شِحْنَةُ بغداد -المسؤول عن ضبط بغداد- وهو خمارتكين النائبُ عن كوهرائين، على دِجلَة في خَيْلِه ورَجِلِه، لِيَكُفَّ الناسَ عن الفِتنةِ، فلم يَنتَهوا، وكان أهلُ الكَرخِ يَجرُون عليه"},{"id":1706,"era":"c5","t":"عَودَةُ يُوسفَ بنِ تاشفين للأندَلُسِ ونِهايَةُ مُلوكِ الطَّوائِف .","s":"جازَ يوسفُ بن تاشفين ثانِيةً وتَثاقَلَ أُمراءُ الطَّوائفِ عن لِقائِه لِمَا أَحَسُّوا مِن نَكيرِه عليهم أَخذَهُم المُكوسَ، فوَجَدَ عليهم، وعَهِدَ بِرَفعِ المُكوسِ وتَحرِّى العَدل، فلمَّا أَجازَ انقَبَضوا عنه إلا ابنَ عبَّادٍ فإنه بادَرَ إلى لِقائِه, وتَوافَقَ مُلوكُ الطَّوائفِ على قَطْعِ المَدَدِ عن عَساكرِه ومحلاتِه فساءَ نَظرُه، قال ابنُ خَلدون: \"وأَفتاهُ الفُقهاءُ وأَهلُ الشُّورَى من المَغرِب وا"},{"id":1707,"era":"c5","t":"الخَليفةُ العبَّاسيُّ المُقتَدِي يُلزِم أَهلَ الذِّمَّةِ بلِباسٍ يُمَيِّزهُم عن المسلمين .","s":"كَتَبَ الوَزيرُ أبو شُجاعٍ محمدُ بن حُسينٍ الروذراوريُّ إلى الخَليفةِ يُعرِّفهُ باستِطالَةِ أَهلِ الذِّمَّةِ على المسلمين، وأن الواجِبَ تَمييزُهم عنهم؛ فأَمرَهُ الخَليفةُ أن يَفعلَ ما يَراهُ. فأَلزَمَهم الوَزيرُ لُبْسَ الغيارِ والزَّنانيرِ وتَعليقَ الدَّراهِم الرصاص في أَعناقِهم، مَكتوبٌ على الدَّراهِم \"ذِمِّي\" وتُجعَل هذه الدَّراهِم أيضًا في أَعناقِ نِسائِهم في الحَمَّاماتِ ليُعرَفنَ بها، وأن يَل"},{"id":1708,"era":"c5","t":"نَهْبُ العَربِ البَصرَةَ .","s":"نَهَبَ العَربُ البَصرةَ نَهْبًا قَبيحًا، وسَببُ ذلك أنَّه وَرَدَ إلى بغداد، في بَعضِ السِّنين، رَجلٌ أَشقرُ مِن سَوادِ النِّيلِ يَدَّعِي الأَدبَ، والنَّظَرَ في النُّجومِ، ويَستَجرِي الناسَ، فلَقَّبَهُ أَهلُ بغداد تليا –أي التابع-، وكان نازلًا في بَعضِ الخاناتِ، فسَرَقَ ثِيابًا من الدِّيباجِ وغَيرِه، وأَخفَاها في خلفا، وسار بهم، فرَآها الذين يَحفَظون الطَّريقَ، فمَنَعوهُ من السَّفَر اتِّهامًا له، و"},{"id":1709,"era":"c5","t":"دُخولُ المُرابِطين مَدينةَ غرناطة .","s":"دَخلَ المُرابِطون بقِيادَةِ القائدِ يوسف بن تاشفين مَدينةَ غرناطة وذلك بعدَ أن عَزَلَ سُلطانَها عبدَالله بن بلقين، وأَصبَحت المَدينةُ تابِعَةً لدَولةِ المُرابِطين التي امتَدَّ نُفوذُها من المَغرِب إلى بلادِ الأندلسِ."},{"id":1710,"era":"c5","t":"ظُهورُ دَولةِ الحَشَّاشِين الإسماعيلية النزارية .","s":"قدم الحَسنُ بن الصَّبَّاحِ، رَئيسُ الطائفةِ الباطِنيَّةِ من الإسماعيليةِ، إلى مصر في زِيِّ تاجرٍ، واتَّصلَ بالمُستَنصِر واختَصَّ به، والتَزَمَ أن يُقيمَ له الدَّعوةَ في بلادِ خراسان وغيرِها من بلادِ المَشرِق. وكان الحسنُ هذا كاتِبًا للرَّئيسِ عبدِ الرَّزَّاق بن بهرام بالرَّيِّ، فكاتَبَ المُستَنصِر، ثم قَدِمَ عليه، ثم إن المُستَنصِر بَلغَه عنه كلامٌ، فاعتَقَلَه، ثم أَطلَقَه. وسَألهُ ابنُ الصَّبَّاح"},{"id":1711,"era":"c5","t":"الفَقيهُ الشافعيُّ مَسعودُ الخجنديُّ يقضي على دعاة الباطنية .","s":"في أيامِ السُّلطانِ ملكشاه، فإنه اجتَمعَ منهم ثمانية عشر رجلًا، فصَلُّوا صلاةَ العِيدِ في ساوة، ففَطَنَ بهم الشِّحْنَةُ –المسؤول عن ضبط أمن ساوة-، فأَخَذَهم وحَبَسَهم، ثم سُئِلَ فيهم فأَطلَقَهم، فهذا أَوَّلُ اجتِماعٍ كان لهم، ثم إنهم دَعوا مُؤذِّنًا من أَهلِ ساوة كان مُقيمًا بأصبهان، فلم يُجِبهُم إلى دَعوَتِهم، فخافوه أن يَنِمَّ عليهم، فقَتَلوه، فهو أَوَّلُ قَتيلٍ لهم، وأَوَّلُ دَمٍ أَراقوهُ، فبَل"},{"id":1712,"era":"c5","t":"حُدوثُ زَلازِل كَثيرةٍ بالشامِ وغَيرِها .","s":"وَقعَت بالشامِ وكَثيرٍ من البلادِ زَلازلُ كَثيرةٌ، وكان أَكثرُها بالشامِ، ففارَقَ الناسُ مَساكِنَهم، وانهَدَم بأنطاكية كَثيرٌ من المَساكِن، وهَلَكَ تحتها عالَمٌ كَثيرٌ، وخَرِبَ من سُورِها تسعون بُرْجًا، فأَمَرَ السُّلطانُ ملكشاه بعِمارَتِها."},{"id":1713,"era":"c5","t":"وَقعَةُ جَيَّان بين المُسلِمين والفِرنِج بجَيَّان .","s":"جَمعَ ألفونسو عَساكِرَه، وجُموعَه، وغَزَا بِلادَ جَيَّان من الأندلسِ، فلَقِيَهُ المُرابِطون وقاتَلوهُ، واشتَدَّت الحَربُ، فكانت الهَزيمةُ أوَّلًا على المسلمين، ثم إن الله تعالى رَدَّ لهم الكَرَّةَ على الفِرنجِ، فهَزَموهم، وأَكثَروا القَتْلَ فيهم، ولم يَنجُ إلا ألفونسو في نَفَرٍ يَسيرٍ، وكانت هذه الوَقعةُ من أَشهُر الوَقائعِ، بعدَ الزَّلَّاقَة، وأَكثرُ الشُّعراءِ ذَكرَها في أَشعارِهم."},{"id":1714,"era":"c5","t":"استِيلاءُ تتش على حِمصَ وغَيرِها مِن ساحِلِ الشَّامِ .","s":"لمَّا كان السُّلطانُ ببغداد قَدِمَ إليه أَخوهُ تاجُ الدولةِ تتش من دِمشقَ، وقَسِيمُ الدولةِ أتسز من حَلَب، وبوزان من الرها، فلمَّا أَذِنَ لهم السُّلطانُ في العَوْدِ إلى بِلادِهم أَمَرَ قَسِيمُ الدولةِ وبوزان أن يَسِيرا مع عَساكِرهِما في خِدمَةِ أَخيهِ تاجِ الدولةِ، حتى يَستولِيَ على ما للمُستَنصِر الفاطميِّ حاكمِ مصر بساحِلِ الشامِ، من البلادِ، ويَسيرُ، وهُم معه، إلى مصر لِيَملِكَها، فساروا أجمعون"},{"id":1715,"era":"c5","t":"قتال الأَعرابُ لحُجَّاجِ أهل بغداد ونهبهم بالكُوفَةِ .","s":"سار الحُجَّاجُ من بغداد، فقَدِموا الكُوفةَ، ورَحَلوا منها، فخَرَجت عليهم خَفاجَةٌ، وقد طَمِعوا بمَوتِ السُّلطانِ وبُعْدِ العَسكرِ، فأَوقَعوا بهم، وقَتَلوا أَكثرَ الجُندِ الذين معهم، وانهَزمَ باقيهم، ونَهَبوا الحُجَّاجَ، وقَصَدوا الكوفةَ فدَخَلوها، وأغاروا عليها، وقَتَلوا في أَهلِها، فرَماهُم الناسُ بالنُّشَّابِ، فخَرَجوا بعدَ أن نَهَبوا، وأَخَذوا ثِيابَ مَن لَقوهُ من الرِّجالِ والنِّساءِ، وَصَلَ ا"},{"id":1716,"era":"c5","t":"اغتِيالُ الوَزيرِ السَّلجوقيِّ نِظامِ المُلْكِ على يد الباطنية .","s":"هو الوَزيرُ الكَبيرُ، نِظامُ المُلْكِ، قِوامُ الدِّينِ، أبو عليٍّ الحَسنُ بن عليِّ بن إسحاقَ الطُّوسيُّ، وَزيرُ السُّلطانِ ملكشاه السلجوقي، عاقِلٌ، سائِسٌ، خَبيرٌ، سَعيدٌ، مُتَدَيِّنٌ، مُحتَشِمٌ، عامِرُ المَجلِس بالقُرَّاءِ والفُقَهاءِ. أَنشأَ المَدرسةَ النِّظامِيَّة الكُبرى ببغداد، ثم أَنشأَ مَدارسَ أُخرى في عَددٍ من البُلدانِ, ورَغَّبَ في العِلمِ، وأَدَرَّ على الطَّلَبَةِ الصِّلاتِ، وأَملَى الحَ"},{"id":1717,"era":"c5","t":"وَفاةُ السُّلطانِ السلجوقي ملكشاه وتَفَكُّكُ الدَّولةِ السلجوقية .","s":"هو أبو الفَتحِ ملكشاه بن ألب أرسلان محمد بن داود بن ميكائيل بن سلجوق بن دقاق، المُلَقَّب بجَلالِ الدولة. لمَّا تُوفِّي أَبوهُ كان ملكشاه وَلِيَّ الأَمرِ مِن بَعدِه بِوَصِيَّةِ والِدِه وتَحليفِ الأُمراءِ والأَجنادِ على طاعَتِه، ووَصَّى وَزيرَه نِظامَ المُلْكِ أبا عليٍّ الحَسنَ على تَفرِقَةِ البِلادِ بين أَولادِه، ويكون مَرجِعُهم إلى ملكشاه، ففَعَلَ ذلك، وعَبَرَ بهم نَهرَ جيحون راجِعًا إلى البلادِ, "},{"id":1718,"era":"c5","t":"القِتالُ على السُّلطَةِ بعدَ ملكشاه  .","s":"بعدَ وَفاةِ ملكشاه أَخذَت زَوجتُه تركان خاتون الجلالية البَيْعَةَ لِوَلَدِها محمود وله أربع سنوات وعِدَّةُ أَشهُر, ثم  أَرسلَت إلى أصبهان في القَبضِ على بركيارق ابنِ السُّلطانِ، وهو أَكبرُ أَولادِه، خافَتْهُ أن يُنازِعَ وَلدَها في السَّلطَنَةِ، فقُبِضَ عليه، فلمَّا ظَهرَ مَوتُ ملكشاه وَثَبَ المَماليكُ النِّظامِيَّةُ على سِلاحٍ كان لنِظامِ المُلْكِ بأصبهان، فأَخَذوهُ وثاروا في البلدِ، وأَخرَجوا برك"},{"id":1719,"era":"c5","t":"قِتالُ تتش بن ألب أرسلان مِن أَجلِ السَّلطَنَةِ .","s":"كان تتش بن ألب أرسلان صاحِبُ دِمشقَ وما جاوَرَها من بلادِ الشامِ، سار من دِمشقَ إلى أَخيهِ السُّلطانِ ملكشاه ببغداد، فلمَّا كان بهيت بَلَغَهُ مَوتُه، فأَخَذَ هيت، واستَولَى عليها، وعاد إلى دِمشقَ يَتجهَّزَ لِطَلَبِ السَّلطَنَة، فجَمعَ العَساكِرَ، وأَخرجَ الأَموالَ وسار نحوَ حَلَب، وبها قَسيمُ الدولةِ أتسز فرأى قَسيمُ الدولةِ اختِلافَ أَولادِ صاحِبِه ملكشاه، وصِغَرَهُم، فعَلِمَ أنه لا يَطيقُ دَفْعَ"},{"id":1720,"era":"c5","t":"نِهايَةُ مُلوكِ الطَّوائفِ وقِيامُ دَولةِ المُرابِطين  بالأندَلُسِ .","s":"انتَظَمَت جَميعُ بلادِ المُسلِمين في الأندلسِ تحت مُلْكِ يوسفَ بنِ تاشفين، وانقَرضَ عَهدُ مُلوكِ الطَّوائفِ منها أَجمَع كأنْ لم يكُن، واستَولَى على العَدوَتَينِ، وتَسَمَّى بأَميرِ المسلمين، وخاطَبَ المُستَنصِر العبَّاسيَّ الخَليفةَ لِعَهْدِه ببغداد، وبَعثَ إليه عبدَ الله بنَ محمدِ بنِ العَربِ على يَدِ المعافري الإشبيلي ووَلَدَه القاضي أبا بكرٍ، فتَلَطَّفا في القَولِ وأَحسَنا في الإبلاغِ، وطَلَبا م"},{"id":1721,"era":"c5","t":"وَقعَةُ المُضَيَّعِ بين إبراهيمُ بن بدران وتتش بن ألب أرسلان .","s":"كان إبراهيمُ بن قُريشِ بن بدران، أَميرُ بني عُقيلٍ، قد استَدعاهُ السُّلطانُ ملكشاه سَنةَ اثنتين وثمانين وأربعمائة لِيُحاسِبَه، فلمَّا حَضَرَ عنده اعتَقَلهُ، وأَنفَذَ فَخرَ الدولةِ بنَ جَهيرٍ إلى البِلادِ، فمَلَكَ المَوصِلَ وغَيرَها، وبَقِيَ إبراهيمُ مع ملكشاه، وسارَ معه إلى سمرقند، وعاد إلى بغداد، فلمَّا ماتَ ملكشاه أَطلقَتهُ تركان خاتون من الاعتِقالِ، فسارَ إلى المَوصِل, وكان ملكشاه قد أَقطعَ عَم"},{"id":1722,"era":"c5","t":"الجَيشِ العُبيديِّ الفاطِميِّ يحاصر مدينة صور .","s":"مَلَكَ عَسكرُ المُستَنصِر بالله العُبيديِّ، صاحِبِ مصر، مَدينةَ صور، وسَببُ ذلك ما كان سَنةَ 482هـ أن أَميرَ الجُيوشِ بَدرًا، وَزيرَ المُستَنصِر، سَيَّرَ العَساكِرَ إلى مَدينةِ صور، وغَيرِها، من ساحِلِ الشامِ، وكان مَن بها قد امتَنعَ مِن طاعَتِهم، فمَلَكَها، وقَرَّرَ أُمورَها، وجَعَلَ فيها الأُمراءَ، وكان قد وَلَّى مَدينةَ صور الأَميرَ الذي يُعرَف بمُنيرِ الدولةِ الجُيوشيِّ، فعَصَى على المُستَنصِر"},{"id":1723,"era":"c5","t":"الخَليفَةُ العبَّاسيُّ يُقَلِّد يوسفَ بن تاشفين البِلادَ التي فَتَحَها .","s":"طَلَبَ يوسفُ بن تاشفين من الخَليفَةِ العبَّاسيِّ المُستَظهِر بالله أن يُقَلِّدَهُ البِلادَ التي فَتحَها وبَعثَ إليه بهذا الطَّلَبَ مع عبدِالله بن العربي الإشبيلي ووَلَدِه القاضي أبي بكرِ بن العربي الإمامِ المَشهورِ، فعَهِدَ الخَليفةُ لابنِ تاشفين بما طَلَبَ."},{"id":1724,"era":"c5","t":"بركيارق يَتوَّلى حُكمَ الدَّولةِ السَّلجوقِيَّة بفارس .","s":"يومَ الجُمعةِ رابع عشر المُحرَّم، خُطِبَ ببغداد للسُّلطانِ بركيارق بن ملكشاه، وكان قَدِمَها أَواخِرَ سَنَةِ سِتٍّ وثَمانين وأربعمائة، وأَرسلَ إلى الخَليفةِ المُقتدِي بأَمرِ الله يَطلُب الخُطبةَ، فأُجِيبَ إلى ذلك، وخَطَبَ له، ولُقِّبَ رُكنَ الدِّين، وحَملَ الوَزيرُ عَميدُ الدَّولةِ بن جَهيرٍ الخِلَعَ إلى بركيارق، فلَبِسَها، وعُرِضَ التَّقليدُ على الخَليفةِ لِيُعَلِّمَ عليه، فعَلَّمَ فيه، وتُوفِّي ف"},{"id":1725,"era":"c5","t":"وَفاةُ الخَليفَةِ العبَّاسيِّ المُقتَدِي بالله وحُكْمُ ابنِه المُستَظهِر بالله .","s":"هو أَميرُ المؤمنين المُقتَدِي بالله أبو القاسمِ عبدُ الله بنُ الأَميرِ ذَخيرةِ الدِّين أبي العبَّاس محمدِ بن القائمِ بأمرِ الله عبدِ الله بنِ القادرِ بالله أحمدَ بن إسحاقَ بن جَعفرٍ المُقتَدِر بن المُعتَضِد الهاشميُّ العبَّاسيُّ، تُوفِّي أَبوهُ الذَّخيرَةُ والمُقتدِي حَمْلٌ وأُمُّهُ أُمُّ وَلَدٍ اسمُها: أرجوان، أرمنية عاشَت إلى خِلافَةِ ابنِ ابنِها المُستَرشِد بالله. بُويِعَ المُقتدِي بالخِلافة في"},{"id":1726,"era":"c5","t":"مَقتَلُ قَسيمِ الدَّولةِ أتسز السَّلجوقيِّ .","s":"قُتِلَ قَسيمُ الدَّولةِ أتسز، وسَببُ قَتلِه أن تاجَ الدَّولةِ تتش لمَّا عاد من أذربيجان مُنهزِمًا لم يَزل يَجمَع العَساكرَ، فكَثُرت جُموعُه، وعَظُمَ حَشدُه، فسار في هذا التاريخِ عن دِمشقَ نحوَ حَلَب لِيَطلُب السَّلطنةَ، فاجتَمعَ قَسيمُ الدولةِ أتسز وبوزان، وأَمَدَّهُما رُكنُ الدِّينِ بركيارق بالأَميرِ كربوقا الذي صار بعدَ صاحِبِ المَوصِل، فلمَّا اجتَمَعوا ساروا إلى طَريقِه، فلَقوهُ عند نَهرِ سبعين"},{"id":1727,"era":"c5","t":"انهِزامُ بركيارق بنِ ملكشاه على يد عَمِّهِ تتش .","s":"انهَزمَ بركيارق مِن عَسكرِ عَمِّهِ تتش. وكان بركيارق بنصيبين، فلمَّا سَمِعَ بمَسيرِ عَمِّهِ إلى أذربيجان، سار هو من نصيبين، وعَبَرَ دِجلةَ مِن بَلدٍ فوقَ المَوصِل، وسار إلى إربل، ومنها إلى بلدِ سرخاب بن بدرٍ إلى أن بَقِيَ بينه وبين عَمِّهِ تِسعةُ فَراسِخ، ولم يكُن معه غيُر ألف رَجُلٍ، وكان عَمُّه في خمسين ألف رَجُلٍ، فسارَ الأَميرُ يعقوبُ بن آبق مِن عَسكرِ عَمِّه، فكَبَسَهُ وهَزَمهُ، ونَهبَ سَوادَ"},{"id":1728,"era":"c5","t":"وَفاةُ حاكِمِ مصر العُبيديِّ المُستَنصِر بالله وتَوَلِّي ابنِه المُستَعلِي بَعدَه .","s":"هو المُستَنصِر بالله أبو تَميمٍ مَعَدُّ بنُ أبي الحَسنِ عليٍّ الظاهر بن الحاكم الفاطِميُّ العُبيديُّ صاحِبُ مصر والشام، وُلِدَ سَنةَ 420هـ, ووَلِيَ الأَمرَ بعدَ أَبيهِ الظاهرِ وله سَبعُ سنين، في شعبان سنة 427هـ، وفي وَسطِ دَولتِه خُطِبَ له بإَمْرَةِ المؤمنين على مَنابرِ العِراقِ. قال ابنُ خلكان: \"جَرَى في أَيامِه ما لم يَجرِ على أَيامِ أَحَدٍ مِن أَهلِ بَيتِه ممَّن تَقدَّمهُ ولا تَأخَّرهُ: منها قَ"},{"id":1729,"era":"c5","t":"استِفحالُ أَمْرِ بركيارق بنِ ملكشاه .","s":"لمَّا مَلَكَ بركيارق بعدَ أَبيهِ وكان ما كان مِن قِتالِه مع عَمِّهِ تتش، ومُحاولَةِ بَعضِ العَسكرِ بالتَّحريضِ أن يَكحَلوهُ ويَسمُلوا عَينَيهِ فنَجَّاهُ الله من ذلك، ثم إنه مَرَضَ بالجُدَرِي وعاد عَمُّهُ لقِتالِه ثم شُفِيَ وقَتَلَ عَمَّهُ فأَصبحَ يَعلُو كَعبُه ويَقوَى شَأنُه ويَستَفحِل أَمرُه."},{"id":1730,"era":"c5","t":"وَفاةُ المُحَدِّثِ الحُمَيدِيِّ .","s":"الإمامُ، القُدوَةُ، الأَثَرِيُّ المُتقِنُ، الحافِظُ، شَيخُ المُحَدِّثينَ، أبو عبدِ الله محمدُ بنُ أبي نَصرٍ فتوح بن عبدِ الله بن فتوحِ بن حُميدِ بن يصل الأزديُّ، الحُمَيدِيُّ، الأندلسيُّ؛ الميورقيُّ، الفَقِيهُ، الظاهِريُّ، مُؤَرِّخٌ ومُحَدِّثٌ أَندلسيٌّ من أَهلِ الجَزيرَةِ، صاحِبُ ابنِ حَزمٍ وتِلميذُه. وُلِدَ قبلَ سَنةِ 420هـ، بَدأَ بِطَلَبِ العِلمِ صَغيرًا قال عن نَفسِه: \"كُنتُ أُحمَلُ للسَّماعِ "},{"id":1731,"era":"c5","t":"دُخولُ الأَتراكِ أفريقية عُنوَةً ثم خُروجُهم منها .","s":"غَدَرَ شاهملك التُّركيُّ بِيَحيى بنِ تَميمِ بنِ المُعِزِّ بنِ باديس، وقَبَضَ عليه، وكان شاهملك هذا من أَولادِ بَعضِ الأُمراءِ الأَتراكِ ببلادِ الشَّرقِ، فنالَهُ في بَلدِه أَمْرٌ اقتَضى خُروجَه منه، فسار إلى مصر في مائةِ فارسٍ، فأَكرَمَهُ الأَفضلُ أَميرُ الجُيوشِ، وأَعطاهُ إِقطاعًا ومَالًا، ثم بَلَغَهُ عنه أَسبابٌ أَوجبَت إِخراجَه من مصر، فخَرجَ هو وأَصحابُه هارِبينَ، فاحتالوا حتى أَخَذوا سِلاحًا و"},{"id":1732,"era":"c5","t":"البابا (أوربان الثاني) يُعلِن الحَربَ الصَّليبيَّة الأُولى على الأَتراكِ .","s":"تَلَقَّى البابا أوربان الثاني نِداءً من الإمبراطورِ البِيزنطي إلكسيس كومنين يَطلُب منه العَوْنَ ضِدَّ السَّلاجِقَةِ الأَتراكِ، فيَعقِد البابا مَجْمَعًا كَنَسِيًّا في مَدينةِ كليرمون فران في فرنسا ويُعلِن الحَربَ الصَّليبيَّة الأُولى على الأَتراكِ، ويَدعُو إلى وَقْفِ الحَربِ بين المُلوكِ والأُمراءِ المَسيحِيِّينَ في أوربا، وتَوَجُّهِهِم بأَسلِحَتِهم لِحَربِ الكَفَرَةِ على حَدِّ تَعبيرِهِم، ويُعلِن "},{"id":1733,"era":"c5","t":"وَفاةُ تتش بن ألب أرسلان صاحِبِ دِمشقَ .","s":"هو المَلِكُ أبو سَعيدٍ تاجُ الدَّولةِ تتش بنُ محمد ألب أرسلان بن داود بن ميكال بن سلجوق بن دقاق السلجوقي، وَلَدُ سُلطانٍ وأَخو سُلطانٍ. صاحِبُ البِلادِ الشرقيَّةِ. وُلِدَ في رمضان سَنةَ 458هـ. تُركِيٌّ مُحتَشِمٌ، شُجاعٌ، مَهِيبٌ جَبَّارٌ، ذا سَطْوَةٍ، مِن بَيتِ مُلْكٍ، وله فُتوحاتٌ ومصافاتٌ، وتَمَلَّكَ عِدَّةَ مَدائنَ، وخُطِبَ له ببغداد، وصار مِن كِبارِ مُلوكِ الزَّمانِ وتقدم. مَرَّ كَثيرٌ مِن سِي"},{"id":1734,"era":"c5","t":"وَفاةُ أبي شُجاعٍ الوَزيرِ الروذراوريِّ .","s":"هو أبو شُجاعٍ الوَزيرُ محمدُ بن الوَزيرِ حُسينِ بن عبدِ الله بن إبراهيمَ، الروذراوريُّ، أَهوازيُّ الأَصلِ من همذان. كان أبو شُجاعٍ قد قَرأَ الفِقهَ والعَربيَّةَ، وسَمِعَ الحَديثَ من جَماعةٍ منهم: أبو إسحاقَ الشِّيرازيُّ، وصَنَّفَ كُتُبًا منها كِتابُه الذي ذَيَّلَهُ على ((تجارب الأمم)) ووَزَرَ للمُقتدِي بالله سَليمًا مِن طَمَعٍ، وكان يَملِك حِينئذٍ عَيْنًا ستمائة ألف دِينارٍ، فأَنفَقَها في الخَيرات"},{"id":1735,"era":"c5","t":"وَفاةُ المُعتَمِد بنِ عَبَّادٍ مَلِك الأَندلسِ .","s":"هو مَلِكُ الأَندلسِ المُعتَمِدُ على الله أبو القاسمِ محمدُ بنُ المُعتَضِد بالله أبي عَمروٍ عَبَّادِ بنِ الظافرِ المُؤيَّدِ بالله أبي القاسمِ محمدِ قاضي إشبيلية بن أبي الوليدِ إِسماعيلَ بن قُريشِ بن عَبَّاد بنِ عَمرِو بن أَسلمَ بنِ عَمرِو بنِ عَطَّاف بنِ نعيمٍ، اللخميُّ، مِن وَلَدِ النُّعمانِ بن المُنذِر اللخميِّ، آخرِ مُلوكِ الحِيرَةِ؛ كان المُعتَمِدُ صاحِبَ قُرطبةَ وإشبيلية وما والاهُما مِن جَزير"},{"id":1736,"era":"c5","t":"وَفاةُ أَميرِ الجُيوشِ بَدرِ بنِ عبدِ الله الجمالي .","s":"هو أَميرُ الجُيوشِ، الوَزيرُ الأَرمَنيُّ، بَدرُ بنُ عبدِ الله الجمالي، اشتَراهُ جَمالُ المُلْكِ بنُ عمَّارٍ الطَّرابلسيُّ، ورَبَّاهُ، فتَرَقَّت به الأَحوالُ إلى المُلْكِ. وَلِيَ نِيابَةَ دِمشقَ للمُستَنصِر الفاطميِّ سَنَةَ 455هـ، إلى أن هاجَ أَحداثُ دِمشقَ وشُطَّارُها سَنةَ 460هـ, فتَحَوَّل إلى مصر, وقِيلَ: لمَّا ضَعُفَ حالُ المُستَنصِر في مصر واختَلَّت دَولتُه وُصِفَ له بَدرٌ الجمالي، فاستَدعاهُ "},{"id":1737,"era":"c5","t":"عُدوانُ قبيلة خَفاجَة العربية على سَيفِ الدَّولَةِ بنِ مزيد .","s":"أَغارَت خَفاجَةُ على بَلدِ سَيفِ الدولةِ صَدَقَة بنِ مزيد، فأَرسلَ في إِثْرِهِم عَسكَرًا، مُقَدِّمُه ابنُ عَمِّهِ قُريشُ بن بدران بن دبيس بن مزيد، فأَسَرَتهُ خَفاجةُ، وأَطلَقوهُ، وقَصَدوا مَشهدَ الحُسينِ بنِ عليٍّ، فتَظاهَروا فيه بالفَسادِ والمُنكَرِ، فوَجَّهَ إليهم صَدقةُ جَيشًا، فكَبَسوهُم، وقَتَلوا منهم خَلْقًا كَثيرًا في المَشهدِ، حتى عند الضَّريحِ، وأَلقَى رَجلٌ منهم نَفسَه وهو على فَرَسِه من"},{"id":1738,"era":"c5","t":"الدَّعوةُ لِقِيامِ الحَملَةِ الصَّلِيبيَّةِ الأُولى .","s":"دَعا البابا أوربان الثاني إلى حَربٍ صَليبيَّةٍ ضِدَّ المسلمين واستَجابَ أُمراءُ أوربا لهذا النِّداءِ فأَوقَفوا الحُروبَ بينهم وأَعَدُّوا حَملَةً صَليبيَّةً مُنَظَّمَةً اشتَركَ فيها الدوق جودفري بويون أَميرُ مُقاطَعَةِ اللورين السُّفلَى، وأَخوهُ بودوان، وريمون أَميرُ تولوز، وبروفانس وبوهمند النورماندي أَميرُ تارانت، وابنُ أُختِه تانكرد، وروبير أَميرُ نورماندي وهو ابنُ وليم الفاتح، وصِهرُه اتيان أَم"},{"id":1739,"era":"c5","t":"مِلْكُ تَميمِ بنِ المُعِزِّ مَدينةَ قابس .","s":"في هذه السَّنَةِ مَلَكَ تَميمُ بنُ المُعِزِّ مَدينةَ قابس، وأَخرَجَ منها أَخاهُ عَمْرًا, وسَببُ ذلك أنه كان بها إنسانٌ يُقال له قاضي بن إبراهيمَ بن بلمونه فماتَ، فوَلَّى أَهلُها عليهم عَمرَو بنَ المُعِزِّ، فأَساءَ السِّيرَةَ، وكان قاضي بن إبراهيمَ عاصِيًا على تَميمٍ، وتَميمٌ يُعرِض عنه، فعَصَى عَمرٌو على أَخيهِ كقاضي بن إبراهيم، فأَخرجَ تَميمٌ العَساكِرَ إلى أَخيهِ عَمرٍو لِيَأخُذَ المَدينةَ منه، "},{"id":1740,"era":"c5","t":"وَفاةُ مَنصورِ بنِ نِظامِ الدِّينِ بنِ نَصرِ الدَّولَةِ بنِ مَروانَ .","s":"هو أبو المُظَفَّرِ مَنصورُ بن نِظامِ الدِّينِ نَصرِ بنِ نَصيرِ الدَّولةِ مَروانَ بنِ دوستك الكُرديُّ، صاحِبُ دِيارِ بَكرٍ، تَوَلَّى الحُكمَ بعدَ وَالدِه نِظامِ الدِّين في ذي الحجَّةِ سَنةَ 472هـ، ودَبَّرَ دَولتَهُ ابنُ الأَنبارِيِّ، ولم يَزَل في مُلكِه إلى أن انقَرَضَ أَمرُ بَنِي مَروانَ على يَدِ فَخرِ الدَّولةِ بنِ جَهيرٍ حين حارَبَهُ، وكان جكرمش قد قَبَضَ عليه بالجَزيرَةِ، وتَرَكَهُ عند رَجلٍ يَ"},{"id":1741,"era":"c5","t":"وَفاةُ مَنصورِ بنِ مُحمدٍ السَّمعانيِّ .","s":"هو أبو المُظَفَّرِ مَنصورُ بنُ محمدِ بنِ عبدِ الجَبَّارِ بنِ أَحمدَ بنِ محمدٍ، السَّمعانيُّ، التَّميميُّ المَروَزِيُّ، الفَقِيهُ الحَنفيُّ ثم الشافعيُّ. الحافِظُ، مِن أَهلِ مَرْو، وُلِدَ في ذي الحجَّةِ 426هـ, وتَفَقَّهَ أَوَّلًا على أَبيهِ في مَذهَبِ أبي حَنيفَةَ، حتى بَرَعَ فيه وبَرَزَ على أَقرانِه, ثم انتَقَل إلى مَذهَبِ الشافعيِّ فأَخَذَ عن أبي إسحاقَ الشِّيرازيِّ وابنِ الصَّبَّاغِ. ذَكرَهُ أبو"},{"id":1742,"era":"c5","t":"نِهايَةُ الدَّولَةِ العُقَيلِيَّةِ بالمَوصِل .","s":"مَلَكَ قِوامُ الدَّولةِ أبو سَعيدٍ كربوقا التُّركيُّ مَدينةَ المَوصِل، فأَسَرَهُ تاجُ الدولةِ تتش لمَّا قَتَلَ أتسز وبوزان، فلمَّا أَسَرَهُ أَبقَى عليه، ولم يكُن له بلدٌ يَملِكُه إذا قَتلَه، كما فَعلَ الأُميرُ بوزان، فإنه قَتَلَهُ واستَولَى على بِلادِه الرها وحران. ولم يَزَل قِوامُ الدولةِ مَحبوسًا بحَلَب إلى أن قُتِلَ تتش، ومَلَكَ ابنُه المَلِكُ رضوان حَلَب فأَرسلَ السُّلطانُ بركيارق رَسولًا يَأم"},{"id":1743,"era":"c5","t":"الفِتنَةُ بنيسابور بين طائفة الكَرامِيَّة والطَّوائفِ الأخرى .","s":"جَمَعَ أَميرٌ كَبيرٌ مِن أُمراءِ خراسان جَمْعًا كَثيرًا، وسار بهم إلى نيسابور، فحَصَرَها، فاجتَمَع أَهلُها وقاتَلوهُ أَشَدَّ قِتالٍ، ولازَمَ حِصارَهم نحوَ أربعين يومًا، فلمَّا لم يَجِد له مَطْمَعًا فيها سار عنها في المُحرَّمِ سَنةَ 489هـ، فلمَّا فارَقَها وَقَعَت الفِتنَةُ بها بين الكَرامِيَّة وسائرِ الطَّوائفِ من أَهلِها، فقُتِلَ بينهم قَتلَى كَثيرةٌ، وكان مُقَدَّمُ الشافعيَّةِ أبا القاسمِ بن إمام"},{"id":1744,"era":"c5","t":"هزيمة قلج بن أرسلان صاحب قونية على يد الصليبيين .","s":"لَمَّا زحف الإفرنجُ إلى سواحل الشام جعلوا طريقَهم على القسطنطينية، فمنعهم من ذلك ملك الروم حتى شرَطَ عليهم أن يعطوه أنطاكية إذا ملكوها، فأجابوا لذلك، وعبروا خليجَ القسطنطينية، ومروا ببلاد قلج أرسلان بن سليمان بن قطلمش السلجوقي فلَقِيَهم في جموعه قريبًا من قونية، فهزموه."},{"id":1745,"era":"c5","t":"عصيان يارقطاش وقدون على السلطان بركيارق .","s":"كان الأميرُ قودن صار في جملة الأمير قماج، فلما توفي قماج، والسلطان بمرو، فاستوحش قودن، وأظهر المرض، وتأخَّرَ بمروٍ بعد مسير السلطان بركيارق إلى العراق، وكان من جملة أمراء السلطان أمير اسمه اكنجي، وقد ولاه السلطان خوارزم، ولقَّبه خوارزمشاه، فجمع عساكِرَه وسار في عشرة آلاف فارس ليلحقَ السلطان، فسبق العسكر إلى مرو في ثلاثمائة فارس، وتشاغل بالشُّرب، فاتفق قودن وأمير آخر اسمه يارقطاش على قتله، فجمعا خم"},{"id":1746,"era":"c5","t":"مقتل أرسلان أرغون السلجوقي ملك خراسان .","s":"هو صاحبُ خراسانَ أرسلان أرغون بن ألب أرسلان السلجوقي: أخو السلطان ملكشاه. لما مات أخوه السلطان ملكشاه بادر أرسلان أرغون واستولى على خراسان، وتمكَّن من تملُّك بلخ ومرو وترمذ، وخرَّبَ سورَ نيسابور وغيرَها من المدائن، ووزَر له عمادُ الملك بن نظام الملك، ثم قَبَض عليه وأخذ منه ثلاثمائة ألف دينار وذبحه. وكان ظالِمًا شرس الأخلاق, قتل أرسلان أرغون بمرو، وكان سبب قتله أنه كان شديدًا على غلمانه، كثيرَ الإه"},{"id":1747,"era":"c5","t":"حملة الصليبيين العامة (الشعبية)\n  .","s":"على إثر دعوة البابا قامت حركة شعبية ضخمة ارتبطت باسم بطرس الناسك الذي أخذ يتجول غرب أوربا، بثيابه الرثَّة وقدميه العاريتين وحمارِه الأعرج، يدعو العامةَ والدهماءَ، وقد استجاب له في سرعة غريبة الفلاحون والمعدِمون بسبب الظروف القاسية التي كانوا يعيشون فيها، وقد وصف وِل ديورَانت هذه الحملةَ والمنضمِّين لها في قصة الحضارة بقوله: \"وانضوت جماعاتٌ لا عدد لها تحت لواء هذه الحرب مدفوعة إلى هذا بمغريات جمَّة"},{"id":1748,"era":"c5","t":"استيلاء عسكر مصر على مدينة صور .","s":"وصل عسكرٌ كثيرٌ من مصر إلى ثغر صور بساحل الشام، فحصرها وملَكَها، وسبب ذلك أنَّ الواليَ بها -ويعرف بكتيلة- أظهر العصيانَ على المستعلي الفاطمي العبيدي صاحب مصر، والخروجَ عن طاعته؛ فسيَّرَ إليه جيشًا، فحصروه بها وضيقوا عليه وعلى من معه من جنديٍّ وعامي، ثم افتتحها عَنوةً بالسيف، وقُتِل بها خلقٌ كثير، ونُهِب منها المال الجزيل، وأُخذ الوالي أسيرًا بغير أمان، وحُمِل إلى مصر فقُتِل بها."},{"id":1749,"era":"c5","t":"سقوط مدينة نيقية عاصمة دولة السلاجقة في أيدي الصليبيين .","s":"كانت أوَّل حركة الفرنج لأخذ سواحل المسلمين وخروجهم إليها في هذه السنة، ساروا إليها، وأوَّل ما أخذوا نيقية، وهو أوَّلُ بلد فتحوه وأخذوه من المسلمين. ثمَّ فتحوا حصونَ الدروب شيئًا بعد شيء، ووصلوا إلى البارة، وجبل السَّمَّاق، وفامية، وكفر طاب، ونواحيها. واستباح الفرنج تلك النواحي، فكان هذا أولَ مظهر للفرنج بالشام، قَدِموا في بحر القسطنطينية في جمعٍ عظيم، وانزعجت الملوك والرعية، وعَظُم الخَطبُ، وقيل: "},{"id":1750,"era":"c5","t":"احتلال الإفرنج مدينة أنطاكية .","s":"سار الفرنجةُ إلى أنطاكية ولم ينازلوها، وجاؤوا إلى المعرَّة فنصبوا عليها السَّلالم فنزلوا إليها فقَتَلوا من أهلها مائة ألف إنسان، وسَبَوا مثلها. ثمَّ دخلوا كفر طاب وفعلوا مثل ذلك، وعادوا إلى أنطاكية، وكان بها الأميرُ باغي سيان، وكان على الفرنج صنجيل، فحاصرها مدَّة، فنافق رجلٌ من أنطاكية يقال له فيروز,, وفتح لهم في الليل شبَّاكًا فدخلوا منه, قال أبو يعلى بن القلانسي: \"في جمادى الأولى ورد الخبر بأنَّ"},{"id":1751,"era":"c5","t":"العبيديون الفاطميون يستولون على القدس من السلاجقة .","s":"خرج أمير الجيوش الأفضل بن بدر الجمالي في عساكِرَ جمة، ورحل من القاهرة في شعبان، وسار يريدُ أخذ بيت المقدِسِ من الأمير سكمان وإيلغازي بني أرتق، وكانا به في كثير من أصحابهما، فبعث إليهما يلتمِسُ منهما أن يسَلِّما البلدَ ولا يحوِجاه إلى الحرب، فأبيا عليه، فنزل على البلدِ ونصَب عليها من المجانيقَ نيِّفًا وأربعين منجنيقًا، وأقام عليها يحاصِرُها نيِّفًا وأربعين يومًا، حتى هدم جانبًا من السورِ، ولم يبقَ "},{"id":1752,"era":"c5","t":"الصليبيون يستولون على معرة النعمان  .","s":"كان أخذُ المعرَّة بعد أخذ أنطاكية. ولَمَّا وقع ذلك اجتمع ملوكُ الإسلام بالشام، وهم رضوان صاحِبُ حلب، وأخوه دقماق، وطغتكين صاحب دمشق، وصاحب الموصل، وسكمان بن أرتق صاحب ماردين، وأرسلان شاه صاحب سنجار, ولم ينهَضْ أمير الجيوش الأفضل بن بدر بإخراج عساكِرِ مِصرَ مع قدرته على المال والرجال, فاجتمع الجميعُ ونازلوا أنطاكية وضيَّقوا على الفرنجَ حتَّى أكلوا ورق الشجر. وكان صنجيل مقدَّم الفرنج عنده دهاءٌ ومكر"},{"id":1753,"era":"c5","t":"وفاة السلطان إبراهيم الغزنوي صاحب غزنة .","s":"هو السلطانُ إبراهيم بن مسعود بن محمود بن سبكتكين صاحب غزنة وغيرها من بلاد الهند. وكان ملِكًا عادلًا مُنصِفًا منقادًا إلى الخيرِ، كثير الصدقات، كريمًا مجاهدًا، عاقلًا شُجاعًا حازِمًا، حسنَ السيرة، ذا رأيٍ ودهاء متين. كان يقول: \"لو كنتُ بعد وفاة جدي محمود لما ضعف مُلكُنا، ولكني الآن عاجِزٌ أن أستردَّ ما أُخِذَ منا من البلاد؛ لكثرة جيوشهم\". كان لا يبني لنفسه مكانًا حتى يبنيَ لله مسجدًا أو مدرسة. قال "},{"id":1754,"era":"c5","t":"تفاقم أمر الباطنيين وقتلهم الأمراء والسلاطين والعوام .","s":"تفاقم أمرُ الباطنيين كثيرًا حتى أصبحت لهم يدٌ طولى في اغتيال الأمراء والسلاطين، كما ساعد على ذلك كثرةُ الحروب بين السلاطين أنفُسِهم، فأصبح كثيرٌ منهم لا يفارقه درعُه وسلاحُه، وقد قتل الباطنيون نظامَ الملك، وأرسلان أرغون بن ألب أرسلان، والأمير برسق، وقتلوا الأميرَ بلكابك سرمز رئيس شحنة أصبهان، ضربه باطنيٌّ بسكين في خاصرته بأصبهان في دار السلطان محمد، وكان بلكابك كثير الاحتياط من الباطنية لا يفارقه "},{"id":1755,"era":"c5","t":"الصليبيون يستولون على بيت المقدس ويذبحون سبعين ألف مسلم .","s":"كان بيتُ المقدِسِ تحت حُكمِ الفاطميين، ولهم فيه رجلٌ نائِبٌ يُعرَفُ بافتخار الدولة، وبقِيَ فيه إلى الآن، فقصده الفرنجُ بعد أن حصروا عكَّا، فلم يقدِروا عليها، فلما وصلوا إليه حصروه نيفًا وأربعين يومًا، ونصبوا عليه برجين أحدهما من ناحية صهيون، وأحرقه المسلمون، وقتلوا كلَّ من به، فلمَّا فرغوا من إحراقه أتاهم المستغيثُ بأن المدينة قد مُلِكت من الجانب الآخر، وملكوها من جهة الشمال منه ضحوةَ نهار يوم الج"},{"id":1756,"era":"c5","t":"حرب العبيديين الفاطميين للصليبيين في عسقلان  .","s":"كانت وقعةٌ بين العساكر المصرية والفرنج، قيل في سببِها: إن المصريين لما بلغهم ما تمَّ على أهل القدس جمع الأفضل أميرُ الجيوش بن بدر الجمالي العساكِرَ وحَشَد، وسار إلى عسقلان، وأرسل إلى الفرنج ينكِرُ عليهم ما فعلوا، ويتهدَّدهم، فأعادوا الرسولَ بالجواب ورحلوا على إثرِه، وطلعوا على المصريين عَقيبَ وصول الرسول، ولم يكُنْ عند المصريين خبَرٌ من وصولهم، ولا من حركتِهم، ولم يكونوا على أُهْبةِ القتال، فنادَو"},{"id":1757,"era":"c5","t":"ابتداء أمر السلطان محمد بن ملكشاه واقتتاله مع أخيه بركيارق .","s":"كان ابتداءُ أمر السلطان محمد بن ملكشاه، وهو أخو السلطان سنجر لأبيه وأمه، واستفحل إلى أن خُطِب له ببغداد في ذي الحجة من هذه السنة، ثمَّ في صفر من السنة التالية دخل السلطان بركيارق بن ملكشاه أخو السلطان محمد إلى بغداد، ونزل بدار الملك، وأعيدت له الخُطبة، وقُطِعت خُطبة أخيه محمد، ثم سار فالتقى هو وأخوه محمد بمكانٍ قريب من همدان، فهزمه أخوه محمد ونجا هو بنفسِه في خمسين فارسًا، ولَمَّا جرى ما جرى في هذ"},{"id":1758,"era":"c5","t":"المرابطون بالأندلس يستردون مدينة بلنسية .","s":"كانت بلنسية قد سقطت بيد النصراني إلكمبيادور بعد حصرها عام 487، وطلب أهلُها في حينها النزولَ بالأمان، فنقض الفرنجُ الأمانَ فورَ دُخولِهم وقتلوا وحرقوا، وبَقِيَت بيَدِهم إلى هذا العام؛ حيث قام المرابطون بحصارها بقيادة محمد بن تاشفين ومعه القائد المزدلي اللمتوني، ثم في فترة الحصار هلك إلكمبيادور وتولَّت زوجته شيمانه الدفاعَ عن المدينة، ولكِنَّ الحصار الذي دام سبعة أشهر اضطرها لتسليم المدينة؛ حيث انتش"},{"id":1759,"era":"c5","t":"انتصار كمشكين السلجوقي على الصليبيين قرب ملطية .","s":"لقي كمشتكين بن الدانشمند طايلو السلجوقي بن صاحب ملطية وسيواس - وإنما قيل له ابن الدانشمند -معنى الدانشمند المعلم- لأن أباه كان معلمًا للتركمان وتقلبت به الأحوال، حتى مَلضك، وهو صاحِبُ ملطية وسيواس وغيرهما- بيمند الفرنجي، وهو من مقدَّمي الفرنج، قريبَ ملطية، وكان صاحبُها قد كاتبه، واستقدمه إليه، فورد عليه في خمسةِ آلاف، فلقيهم ابن الدانشمند، فانهزم بيمند وأُسِر. ثم وصل من البحر سبعةُ قمامصة -كبار ال"},{"id":1760,"era":"c5","t":"القتال بين السلطانين بركيارق ومحمد وإعادة الخطبة لمحمد ببغداد .","s":"سار بركيارق من بغداد على شهرزور، فأقام بها ثلاثةَ أيام، والتحق به عالَمٌ كثير من التركمان وغيرهم، فسار نحو أخيه السلطان محمد ليحاربَه، فكاتبه رئيس همذان ليسير إليها ويأخُذَ أقطاع الأمراء الذين مع أخيه، فلم يفعل، وسار نحو أخيه، فوقعت الحرب بينهما رابع رجب، وهو المصافُّ الأول بين بركيارق وأخيه السلطان محمد بإسبيذروذ -النهر الأبيض- وهو على عدَّةِ فراسِخَ من همذان. وكان مع محمد نحو عشرين ألف مقاتل، وك"},{"id":1761,"era":"c5","t":"استفحال أمر الباطنية الحشاشين .","s":"كثُرَت الباطنية بالعراق والجبل، وزعيمُهم الحسن بن صباح، فملكوا القلاعَ، وقطعوا السبيل، وأهمَّ النَّاسَ شأنُهم، واستفحل أمرُهم لاشتغال أولاد ملكشاه بالنزاع على السلطة والاقتتال من أجلها."},{"id":1762,"era":"c5","t":"الصليبيون يستولون على حيفا ويافا ويحاصرون مدينة عكا .","s":"سار كندفري ملك الفرنج بالشام -وهو صاحب بيت المقدس- إلى مدينة عكا بساحل الشام، فحصرها فأصابه سهم فقتله، وكان قد عمَرَ مدينة يافا وسلَّمَها إلى قمص -كبير القساوسة- من الفرنج اسمه طنكري، فلما قُتِل كندفري سار أخوه بغدوين إلى بيت المقدس في خمسمائة فارس وراجل، فبلغ الملك دقاق- صاحب دمشق- خبره، فنهض إليه في عسكره، ومعه الأمير جناح الدولة في جموعه، فقاتله، فنُصِر على الفرنج، ومَلَك الفرنجُ مدينةَ سروج من"},{"id":1763,"era":"c5","t":"العالم الإدريسي يزور ملك صقلية ويرسم الأرض على كرة من فضة .","s":"اختار الإدريسيُّ الانتقالَ إلى صقلية بعد سقوط الحكومة الإسلامية؛ لأنَّ الملك النورماني في ذلك الوقت روجر الثاني كان محبًّا للمعرفة، شرح الإدريسي لروجر موقعَ الأرض في الفضاء مستخدِمًا في ذلك البيضةَ لتمثيل الأرض، شبَّهَ الإدريسي الأرضَ بصفار البيضة المحاط ببياضها تمامًا كما تهيم الأرضُ في السماء محاطة بالمجرَّات. أمر الملك الصقلي روجر الثاني له بالمال لينقُشَ خارطة العالم والمعروف باسم لوح الترسيم "},{"id":1764,"era":"c5","t":"السلطان بركيارق يشن حملة على الباطنية الإسماعيلية ويبيح قتلهم .","s":"في هذه السَّنة قَتَل السلطان بركيارق خلقًا من الباطنية ممن تحقَّق مذهبَه، ومن اتُّهِم به، فبلغت عدتُهم ثمانمائة ونيِّفًا، ووقع التتبُّعُ لأموال من قُتِل منهم، فوُجِد لأحدهم سبعون بيتًا من الزوالي المحفور، وكُتب بذلك كتابٌ إلى الخليفة، فتقدَّم بالقبض على قومٍ يُظَنُّ فيهم ذلك المذهَبُ، ولم يتجاسر أحدٌ أن يشفع في أحدٍ لئلَّا يُظَنَّ مَيلُه إلى ذلك المذهب، وزاد تتبُّعُ العوام لكل من أرادوا، وصار كلُّ"},{"id":1765,"era":"c5","t":"محاولة وزير الفاطميين الأفضل بن أمير الجيوش استرداد القدس .","s":"جهَّز الأفضلُ بن أمير الجيوش عسكرًا كثيفًا لغزو الفرنج، فساروا إلى عسقلان ووصلوا إليها في أول رمضان، فأقاموا بها إلى ذي الحِجَّة؛ فنهض إليهم من الفرنج ألفُ فارس وعشرة آلاف راجل، فخرج إليهم المسلمون وحاربوهم. فكانت بين الفريقين عدةُ وقائع آلت إلى كسر الميمنة والميسرة وثبات سعد الدولة الطواشي -مقدَّم العسكر- في القلب، وقاتل قتالًا شديدًا، فتراجع المسلمون عند ثبات المذكور وقاتلوا الفرنج حتى هزموهم إل"},{"id":1766,"era":"c5","t":"الصليبيون يحاصرون طرابلس .","s":"كان صنجيل الفرنجي قد لقي قلج أرسلان بن سليمان بن قتلمش، صاحب قونية، وكان صنجيل في مائة ألف مقاتل، وكان قلج أرسلان في عدد قليل، فاقتتلوا، فانهزم الفرنجُ وقُتِلَ منهم وأُسِرَ الكثير، وعاد قلج أرسلان بالغنائم والظَّفَر الذي لم يحسَبْه. ومضى صنجيل مهزومًا في ثلاثمائة، فوصل إلى الشام، فأرسل فخر الملك بن عمار، صاحب طرابلس، إلى الأمير ياخز، خليفة جناح الدولة على حمص، يقول: من الصواب أن يُعاجل صنجيل إذ هو"},{"id":1767,"era":"c5","t":"قيام الدولة الأرتقية .","s":"تنتسب هذه الدولة إلى زعيم عشيرة من التركمان يُدعى أرتق بن أكسب جد الملوك الأرتقية.كان أميرًا شُجاعًا مُطاعًا، تغلَّب على حلوان والجبل، وكثُرَ أتباعه، فسار إلى الشام. وملك ولدُه سقمان بيتَ المقدس. وذريتُه هم ملوك ماردين من مائتي سنة, وكان أرتق قد التحق عام 449 بخدمة السلطان السلجوقي تتش بن ألب أرسلان صاحب بلاد الشام فأقطعه القدسَ وما حولها. ولما توفِّيَ أرتق سنة 484خلفه ولداه معين الدين سقمان, ونجم"},{"id":1768,"era":"c5","t":"وفاة حاكم مصر العبيدي المستعلي بالله وولاية ابنه المنصور .","s":"هو المستعلي بالله أبو القاسم أحمد بن معد المستنصر بالله الفاطمي العبيدي، حاكم مصر، حكمها مدة سبع سنين وقريبًا من الشهرين، وكان المدبِّر لدولته أمير الجيوش الأفضل بن بدر الجمالي، ولما توفِّيَ وَلِيَ بعده ابنُه أبو علي المنصور، وبويع له في اليوم الذي مات فيه أبوه، وله خمس سنين وشهر وأربعة أيام، ولُقِّب الآمر بأحكام الله، ولم يقدر يركبُ وحده على الفرس لصِغَرِ سنه، وقام بتدبير دولته الأفضل أحسن قيام، "},{"id":1769,"era":"c5","t":"فتنة بين شحنة بغداد إيلغازي والعامة .","s":"كانت فتنةٌ كبيرة بين شحنة بغداد -شحنة: أي القَيِّم لضبط البلد- إيلغازي بن أرتق، وبين العامة. أتى جنديٌّ من أصحابه ملاحًا ليعبر به وبجماعة، فتأخَّر فرماه بنشَّابه فقتله، فأخذت العامة القاتِلَ، فجَرُّوه إلى باب النوبي، فلقيهم ابن إيلغازي فخلَّصه، فرجمتهم العامةُ. فتألم إيلغازي وعبر بأصحابه إلى محلة الملاحين فنهبوها، وانتشرت الشطَّار، فعاثوا هناك وبدعوا، وغرق جماعة، وقُتِل آخرون. وجمع إيلغازي التركما"},{"id":1770,"era":"c5","t":"المصريون بقيادة شرف المعالي يهزمون الصليبيين قرب الرملة .","s":"كان الأفضلُ أمير الجيوش بمصر قد أنفذ مملوكًا لأبيه -لَقَبه سعد الدولة، ويعرف بالطواشي- إلى الشام لحرب الفرنج، فلقِيَهم بين الرملة ويافا، ومقَدَّم الفرنج يعرف ببغدوين، تصافوا واقتتلوا، فحملت الفرنج حملةً صادقة، فانهزم المسلمون، فلما كانت هذه الوقعة انهزم سعد الدولة، فتردى به فرسه فسقط ميتًا، وملك الفرنجُ خيمتَه وجميعَ ما للمسلمين. فأرسل الأفضلُ بعده ابنَه شرف المعالي في جمعٍ كثير، فالتقوا هم والفرن"},{"id":1771,"era":"c5","t":"يوسف بن تاشفين يعود إلى قرطبة للمرة الرابعة .","s":"عاد يوسف بن تاشفين إلى قرطبة للمرة الرابعة، وقاتل ألفونسو وانتهت المعركة بانهزام ألفونسو، ثم قام يوسف بن تاشفين بأخذ البيعة لابنه علي فجعله ملِكًا على قرطبة، وعاد هو إلى مراكش."},{"id":1772,"era":"c5","t":"عودة الاقتتال بين الأخوين السلطان محمد بن ملكشاه وبركيارق .","s":"كان الخليفة العباسي قد ولَّى السلطان محمدًا المُلكَ، واستنابه في جميع ما يتعلَّقُ بأمر الخلافة دون ما أغلق عليه الخليفةُ بابَه، ثم خرج السلطانُ محمد ومعه أخوه سنجر قاصدًا قتال أخيه بركيارق، وفي هذه السنة ثامن جمادى الآخرة كان المصاف الخامس بين السلطان بركيارق والسلطان محمد, فأقبل بركيارق في خمسة عشر ألفًا فحاصره في أصبهان وعددُ أصحاب محمد قليل، فضاقت الميرةُ على محمد، فقسط على أهل البلد على وجه ال"},{"id":1773,"era":"c5","t":"احتلال الفرنج جبيل وعكا من الشام .","s":"وصلت مراكب من بلاد الفرنج إلى مدينة اللاذقية فيها التجار والأجناد والحُجَّاج، وغير ذلك، واستعان بهم صنجيل الفرنجي على حصار طرابلس، فحصروها معه برًّا وبحرًا، وضايقوها وقاتلوها أيامًا، فلم يروا فيها مطمعًا، فرحلوا عنها إلى مدينة جبيل، فحصروها، وقاتلوا عليها قتالًا شديدًا. فلما رأى أهلُها عجزهم عن الفرنج أخذوا أمانًا وسلموا البلد إليهم، فلم يفِ الفرنج لهم بالأمان، وأخذوا أموالهم، واستنقذوها بالعقوبات"},{"id":1774,"era":"c5","t":"وفاة أبي سعد العلاء بن الموصلايا .","s":"هو أمين الدولة أبو سعد العلاء بن حسن بن وهب الموصلايا البغدادي، الكاتب المنشئ بدار الخلافة. ذو الترسُّل الفائق، المنشئ، البليغ. كان نصرانيًّا وأسلم على يد الخليفة المقتدي بأمر الله، وحَسُن إسلامه، أسلم عندما خرج توقيعُ الخليفة سنة 484 بإلزامِ الذَّمَّةِ بلُبسِ الغيار -لبس خاص كوضع الزُّنَّار، وغيره - فأسلم بعضُهم وهرب طائفة. وفي ثاني يوم أسلم الرئيسان أبو سعد بن الموصلايا صاحب ديوان الإنشاء، وابن "},{"id":1775,"era":"c5","t":"انتصار المسلمين على الصليبيين في معركة حران  .","s":"كانت حران لمملوك من مماليك ملكشاه اسمه قراجه، فاستخلف عليها إنسانًا يقال له محمد الأصبهاني، وخرج في العام الماضي، فعصى الأصبهاني على قراجه، ثم قُتل محمد الأصبهاني، قتَلَه غلامٌ لقراجه، فعند ذلك سار الفرنج إلى حران وحصروها، فلما سمع مُعين الدولة سقمان وشمس الدولة جكرمش ذلك، وكان بينهما حرب، أرسل كلٌّ منهما إلى صاحبه يدعوه إلى الاجتماع معه لتلافي أمر حران، ويُعلِمه أنه قد بذل نفسه لله تعالى وثوابه، "},{"id":1776,"era":"c5","t":"انتزاع بلك بن بهرام مدينة عانة من بني يعيش .","s":"استولى بلك بن بهرام بن أرتق على مدينة عانة، والحديثة، وكانت له مدينة سروج، فأخذها الفرنجُ منه، فسار عنها إلى عانة وأخذها من بني يعيش بن عيسى بن خلاط، فقصد بنو يعيش سيف الدولة صدقة بن مزيد، ومعهم مشايخهم، فسألوه الإصعادَ إليها، وأن يتسلَّمَها منهم، ففعل وأصعد معهم, فرحل التركمان وبهرام عنها، وأخذ صدقة رهائنَهم، وعاد إلى حلته، فرجع بلك إليها ومعه ألفا رجل من التركمان، فمانعه أصحابه قليلًا، واستدلَّ "},{"id":1777,"era":"c5","t":"غارة الفرنج على الرقة وقلعة جعبر .","s":"أغار الفرنج من الرها على مرج الرقة وقلعة جعبر، وكانوا لما خرجوا من الرها افترقوا فرقتين، وتواعدوا يومًا واحدًا تكون الغارة على البلدين فيه، ففعلوا ما استقرَّ بينهم، وأغاروا، واستاقوا المواشيَ، وأسَروا من وقع بأيديهم من المسلمين، فكانت قلعة جعبر والرقة لسالم بن مالك بن بدران بن المقلد بن المسيب، سلَّمها إليه السلطان ملكشاه سنة تسع وسبعين وأربعمائة."},{"id":1778,"era":"c5","t":"الصلح بين السلطان بركيارق وأخيه محمد .","s":"في هذه السنة وقع الصلح بين الأخوين السلطانين بركيارق ومحمد ابني ملكشاه. وكان سببه أن الحروب تطاولت بينهما، وعمَّ الفساد، فصارت الأموال منهوبة، والدماء مسفوكة، والبلاد مخربة، والقرى محرقة، والسلطنة مطموعًا فيها، محكومًا عليها، فلما رأى السلطانُ بركيارق المالَ عنده معدومًا، والطمع من العسكر زائدًا، أرسل القاضي أبا المظفر الجرجاني الحنفي، وأبا الفرج الهمذاني، المعروف بصاحب قراتكين، إلى أخيه محمد في ت"},{"id":1779,"era":"c5","t":"أخبار الباطنيين في خراسان .","s":"في خراسان سار جمعٌ كثير من الإسماعيلية الباطنية من طريثيت، عن بعض أعمال بيهق، وشاعت الغارة في تلك النواحي، وأكثروا القتلَ في أهلها، والنهبَ لأموالهم، والسبيَ لنسائهم، واشتدَّ أمرهم، وقَوِيَت شوكتهم، ولم يكفُّوا أيديَهم عمن يريدون قتْلَه؛ لاشتغال سلاطين السلاجقة بالاقتتال فيما بينهم عن خطر الباطنية. فمن جملة فعلهم لما تجمع حُجَّاج هذه السنة، مما وراء النهر، وخراسان، والهند، وغيرها من البلاد، فوصلوا"},{"id":1780,"era":"c5","t":"وفاة السلطان بركيارق بن ملكشاه .","s":"هو السلطان ركن الدولة بركيارق بن السلطان ملكشاه بن السلطان ألب أرسلان بن داود بن سلجوق بن دقماق السلجوقي أبو المظفر، كانت سلطنته اثنتي عشرة سنة وأربعة أشهر، جرت له خطوبٌ طويلة وحروب هائلة، خُطِب له ببغداد ست مرات, فقاسى من الحروب واختلاف الأمور عليه ما لم يقاسِه أحد، واختلفت به الأحوال بين رخاء وشدة، ومُلكٍ وزواله، وأشرفَ في عدة نُوَب بعد إسلام النعمة على ذَهاب المُهجة, ولم يُهزَم في حروبه غيرَ مر"},{"id":1781,"era":"c5","t":"احتلال الفرنج حصن أرتاح بالشام .","s":"كانت وقعة بين طنكري الفرنجي، صاحب أنطاكية، وبين الملك رضوان، صاحب حلب، انهزم فيها رضوان وسببها أن طنكري حصر حصن أرتاح، وبه نائب الملك رضوان، فضيق الفرنجُ على المسلمين، فأرسل النائِبُ بالحصن إلى رضوان يعرِّفه ما هو فيه من الحصر الذي أضعف نفسَه، ويطلب النجدة، فسار رضوان في عسكر كثير من الخيَّالة، وسبعة آلاف من الرجَّالة، منهم ثلاثة آلاف من المتطوِّعة، فساروا حتى وصلوا إلى قِنَّسرين، وبينهم وبين الفر"},{"id":1782,"era":"c5","t":"حرب الفرنج والمصريين .","s":"كانت وقعةٌ بين الفرنج والمسلمين كانوا فيها على السواء، وسببها أن أمير الجيوش الأفضل، وزير صاحب مصر، كان قد سيَّرَ ولده شرف المعالي في السنة الماضية إلى الفرنج فقهرهم وأخذ الرملة منهم، ثم اختلف المصريون والعرب وادَّعى كل واحد منهما أن الفتح له، فأتتهم سرية الفرنج فتقاعد كل فريق منهما بالآخر، حتى كاد الفرنج يظهرون عليهم، فرحل عند ذلك شرف المعالي إلى أبيه بمصر، فنفذ ولده الآخر، وهو سناء الملك حسين، ف"},{"id":1783,"era":"c5","t":"احتلال الفرنج حصن أفامية .","s":"احتلَّ الفرنج حصن أفامية من بلد الشام، وسبب ذلك أن المتولي لأفامية من جهة الملك رضوان صاحب حلب أرسل إلى صاحب مصر العُبيدي الإسماعيلي، وكان يميل إلى مذهبهم، يستدعي منهم من يسلِّم إليه الحصن، وهو من أمنع الحصون، فطلب خلف بن ملاعب الكلابي -كان متغلبًا على حمص- من صاحب مصر العبيدي أن يكون هو المقيم به، وقال: إنني أرغب في قتال الفرنج وأوثرُ الجهاد. فسلموه إليه وأخذوا رهائنه، فلما ملكه خلع طاعتَهم ولم ي"},{"id":1784,"era":"c5","t":"حال طرابلس الشام مع الفرنج .","s":"كان صنجيل الفرنجي قد ملك مدينة جبلة، وأقام على طرابلس يحصرها، فحيث لم يقدر أن يملكها بنى بالقرب منها حصنًا وبنى تحته ربضًا، وأقام مراصد لها، منتظرًا وجود فرصة فيها، فخرج فخر الملك أبو علي بن عمار، صاحب طرابلس، فأحرق ربضه، ووقف صنجيل على بعض سقوفه المتحرقة، ومعه جماعة من القمامصة -كبار القساوسة- والفرسان، فانخسف بهم، فمرض صنجيل من ذلك عشرة أيام ومات، وحُمل إلى القدس فدُفن فيه، ثم إن ملك الروم أمر أ"},{"id":1785,"era":"c5","t":"الحرب بين طغتكين والفرنج .","s":"حدثت وقعة بين طغتكين أتابك دمشق -أتابك يعني الأمير الوالد- وبين قمص -كبير القساوسة- كبير من قمامصة الفرنج، وسبب ذلك أنه تكررت الحروب بين عسكر دمشق وبغدوين، فتارة لهؤلاء وتارة لهؤلاء، ففي آخر الأمر بنى بغدوين حصنًا بينه وبين دمشق نحو يومين، فخاف طغتكين من عاقبة ذلك، وما يحدث به من الضرر؛ فجمع عسكره وخرج إلى مقاتلتهم، فسار بغدوين ملك القدس وعكا وغيرهما، إلى هذا القمص ليعاضده ويساعده على المسلمين، فع"},{"id":1786,"era":"c5","t":"نهب العرب للبصرة .","s":"لَمَّا استولى الأمير صدقة بن مزيد صاحب الحلة على البصرة، واستناب بها مملوكًا اسمه التونتاش، وجعل معه مائة وعشرين فارسًا، اجتمعت ربيعة والمنتفق ومن انضم إليهم من العرب وقصدوا البصرة في جمع كثير، فقاتلهم التونتاش فأسروه وانهزم أصحابه، ولم يقدر من بها على حفظها، فدخلوها بالسيف أواخِرَ ذي القعدة، وأحرقوا الأسواق والدور الحسان، ونهبوا ما قدروا عليه، وأقاموا ينهبون ويحرقون اثنين وثلاثين يومًا، وتشرد أهل"},{"id":1787,"era":"c5","t":"الحرب بين ملك القسطنطينية والفرنج .","s":"كانت وحشةٌ مُستحكِمة بين ملك الروم، صاحب القسطنطينية، وبين بيمند الفرنجي؛ فسار بيمند إلى بلد ملك الروم ونهبه، وعزم على قصده، فأرسل ملك الروم إلى الملك قلج أرسلان بن سليمان صاحب قونية وأقصرا وغيرهما من تلك البلاد يستنجده، فأمده بجمع من عسكره، فقوي بهم وتوجه إلى بيمند، فالتقوا وتصافوا واقتتلوا، وصبر الفرنج بشجاعتهم، وصبر الروم ومن معهم لكثرتهم، ودامت الحرب، ثم أجلت الوقعة عن هزيمة الفرنج، وأتى القتل"},{"id":1788,"era":"c5","t":"تدمير السلطان محمد بن ملكشاه لقلاع الباطنية .","s":"قام السلطان محمد بن ملكشاه بمحاصرة قلاع كثيرة من حصون الباطنية، فافتتح منها أماكن كثيرة، وقتل خلقًا منهم، منها قلعة شاه دز بأصبهان حصينة كان أبوه السلطان جلال الدولة ملكشاه قد بناها بالقرب من أصبهان في رأس جبل منيع هناك، وكان سبب بنائه لها أنه كان مرة في بعض صيوده فهرب منه كلب فاتَّبعه إلى رأس الجبل فوجده، وكان معه رجل نصراني من رسل الروم، فقال الرومي: لو كان هذا الجبل ببلادنا لاتخذنا عليه قلعة، ف"},{"id":1789,"era":"c5","t":"وفاة يوسف بن تاشفين مؤسس دولة المرابطين .","s":"هو سلطان المغرب أبو يعقوب يوسف بن تاشفين بن إبراهيم بن ترقنت الصنهاجي اللمتوني المغربي البربري، الملقَّب بأمير المسلمين، وبأمير المرابطين، وبأمير الملثمين. ولد سنة 430. كان أحدَ من ملك البلاد ودانت بطاعته العباد، واتسعت ممالكه، وطال عمره. وقلَّ أن عُمِّرَ أحد من ملوك الإسلام ما عمر. تولى إمارة البربر واستولى على المغرب ثم الأندلس والسودان، وكان يخطب لبني العباس، وهو أول من تسمى بأمير المسلمين من ا"},{"id":1790,"era":"c5","t":"استحواذ سيف الدولة صدقة بن منصور على مدينة تكريت .","s":"تسلَّم الأمير سيف الدولة صدقة بن منصور بن مزيد قلعةَ تكريت، وكانت لبني مقن العقيليين، ولما استقر السلطان محمد بعد موت أخيه بركيارق أقطعها للأمير أتسز البرسقي، فسار إليها وحصرها مدة تزيد على سبعة أشهر حتى تسلمها."},{"id":1791,"era":"c5","t":"مقتل ابن عطاش الباطني .","s":"هو الرئيس أحمد بن عبد الملك بن عطاش العجمي طاغية الإسماعيلية. كان أبوه من كبار دعاة الباطنية ومن أذكياء الأدباء، له بلاغة وسرعة جواب، استغوى جماعة ثم هلك، وخلفه في الرياسة ابنه أحمد، فكان جاهلًا شجاعًا مطاعًا، تجمع له أتباع وتحيلوا حتى ملكوا قلعة شاه دز بأصبهان، وكان الباطنية بأصبهان قد ألبسوا ابن عطاش تاجًا وجمعوا له أموالًا، وصار له عدد كثير وبأس شديد، واستفحل أمره بالقلعة، فكان يرسل أصحابَه لقط"},{"id":1792,"era":"c6","t":"الصليبيون يحاصرون مدن الساحل صور وصيدا .","s":"جمع بغدوين ملك الفرنج عسكرَه وقصد مدينةَ صور وحصرها، وأمر ببناء حصن عندها على تل المعشوقة، وأقام شهرًا محاصرًا لها فصانعه واليها على سبعة آلاف دينار، فأخذها ورحل عن المدينة، وقصد مدينة صيدا، فحصرها برًّا وبحرًا ونصب عليها البرُجَ الخشب، فوصل الأسطول من مصر للدفع عنها، والحماية لمن فيها، وقاتلوا الفرنج، فظهر المسلمون عليهم، فبلغهم أن عسكر دمشق خارج في نجدة صيدا، فرحل الأسطول عائدًا إلى مصر بغير فائ"},{"id":1793,"era":"c6","t":"قيام دولة الموحدين في المغرب على يد ابن تومرت .","s":"كان محمد بن عبد الله بن تومرت البربري المصمودي الهرغي، الخارج بالمغرب، المدَّعي أنَّه عَلَوي حَسَني، وأنه الإمام المعصوم- من أهل جبل السوس من بلاد المغرب. رحل ابن تومرت إلى بلاد المشرق في طلب العلم، وأتقن علم الأصولين والعربية، والفقه والحديث، واجتمع بالغزالي والكيا الهراسي في العراق، واجتمع بأبي بكر الطرطوشي بالإسكندرية، وقيل إنه لم يجتمع بالغزالي. ثم حج ابن تومرت وعاد إلى المغرب، وكان شجاعًا فصي"},{"id":1794,"era":"c6","t":"وفاة تميم بن المعز صاحب إفريقية .","s":"هو السلطان أبو يحيى تميم بن المعز بن باديس بن المنصور بن بلكين بن زيري بن مناد الحميري الصنهاجي، ملَكَ إفريقيةَ بعد أبيه. كان ملكًا جليلًا شهمًا، شجاعًا ذكيًّا، مَهيبًا فاضلًا، شاعرًا جوادًا فصيحًا, حليمًا كثير العفو عن الجرائم العظيمة، وله معرفة حسنة، وله شِعر حسن, كان حسَنَ السيرة، محبًّا للعلماء، قصده الشعراء من النواحي. ولد سنة 422، ولم يزل بالمهدية منذ ولاه أبوه إياها من صفر سنة خمس وأربعين إ"},{"id":1795,"era":"c6","t":"السلاجقة يقتلون سيف الدولة صدقة بن منصور وإنهاء فتنته .","s":"هو الأمير سيف الدولة صدقة بن بهاء الدولة منصور بن ملك العرب دبيس بن علي بن مزيد الأسدي، الناشري العراقي صاحب الحلة السيفية. كان يتشيع هو وأهل بيته، ويقال له ملك العرب. وكان ذا بأس وسطوة، كريمًا ذا ذمام، عفيفًا من الزنا والفواحش، كأن عليه رقيبًا من الصيانة، ولم يتزوج على زوجته قطُّ ولا تسرَّى، وقيل: إنه لم يشرب مُسكِرًا ولا سَمِعَ غناءً ولا قصد التسوُّقَ في طعام، ولا صادر أحدًا من أصحابه، وكان تاري"},{"id":1796,"era":"c6","t":"احتلال الفرنج حصن عرقة بطرابلس .","s":"كان حِصنُ عرقة، وهو من أعمال طرابلس، بيد غلام للقاضي فخر الملك أبي علي بن علي بن عمار، صاحب طرابلس، وهو من الحصون المنيعة، فعجز غلام ابن عمار عن حمايته، فضاق به القوت وانقطعت عنه الميرة؛ لِطولِ مُكث الفرنج في نواحيه، فأرسل إلى أتابك طغتكين، صاحب دمشق، وقال له: أرسل من يتسلمُ هذا الحصن مني؛ قد عجزت عن حفظه، ولأن يأخذَه المسلمون خيرٌ لي دنيا وآخرة من أن يأخُذَه الفرنج. فبعث إليه طغتكين صاحبًا له اسم"},{"id":1797,"era":"c6","t":"الحرب بين طغتكين أتابك دمشق والفرنج .","s":"حدثت حربٌ شديدة بين طغتكين أتابك دمشق -أتابك يعني الأمير الوالد- والفرنج، وسببها أن طغتكين سار إلى طبرية، وقد وصل إليها ابن أخت بغدوين الفرنجي، ملك القدس، فتحاربا واقتتلا، وكان طغتكين في ألفي فارس وكثيرٍ من الرجَّالة، وكان ابن أخت ملك الفرنج في أربعمائة فارس وألفي راجل، فلما اشتد القتال انهزم المسلمون، فترجل طغتكين ونادى بالمسلمين وشجَّعهم، فعاودوا الحرب وكسروا الفرنج، وأسروا ابنَ أخت الملك، وحُمِ"},{"id":1798,"era":"c6","t":"المرابطون يهزمون الأسبان في موقعة أقليش .","s":"تطلَّع علي بن يوسف بن تاشفين إلى القضاء على مقاومة النصارى وخاصة ألفونسو السادس صاحب طليطلة الذي أصبح يُغيرُ على أطراف بلاد المسلمين في الأندلس بعد وفاة يوسف بن تاشفين، فولى أخاه تميمًا على غرناطة وجعله قائد جيش المرابطين في الأندلس، ثم قام تميم بمحاربة ألفونسو في معركة أقليش التي تعتبر من أكبر المعارك بعد الزلاقة، واستطاع تميم أن ينتصر على ألفونسو الذي قُتِل ابنه في هذه المعركة، كما قُتِل قائدُ ج"},{"id":1799,"era":"c6","t":"الصليبيون يؤسسون مدن صليبية بدعم من نصارى الشام والعبيديين .","s":"كان الصليبيون هاجموا دمشق من جهة الشمال عام 497 ولكنهم هُزموا، وأُسِر أمير الرها الصليبي، غير أنهم استطاعوا في العام نفسه أن يدخلوا حصن أفاميا. بدعم من العُبيديين في أول الأمر لَمَّا وجدوا في الصليبيين حلفاء طبيعيين ضد السلاجقة خصومِهم، واتفقوا معهم على أن يحكموا شماليَّ بلاد الشام ويتركوا لهم حكم جنوبها، ولما دخل الصليبيون بيت المقدس أحسوا بشيء من النصر فتابعوا تقدُّمَهم واصطدموا بالعُبيديين، وبد"},{"id":1800,"era":"c6","t":"استيلاء مودود بن طغتكين على الموصل .","s":"لما استولى جاولي سقاوو على الموصل وعلى الأموال الكثيرة منها، لم يحمل إلى السلطان منها شيئًا، فلما وصل السلطان إلى بغداد لقصد بلاد سيف الدولة صدقة، أرسل إلى جاولي يستدعيه إليه بالعساكر، وكرر الرسُلَ إليه، فلم يَحضُر، وغالط في الانحدار إليه، وأظهر أنه يخاف أن يجتمِعَ به، ولم يقنع بذلك حتى كاتب صدقة، وأظهر له أنه معه، فلما فرغ السلطان من أمر صدقة وقتله، أرسل مجموعة من أمرائه الكبار على رأسهم مودود بن"},{"id":1801,"era":"c6","t":"ذكر الحرب بين جاولي التركماني والفرنج .","s":"كان المصافُّ بين جاولي سقاوو التركماني وبين طنكري الفرنجي، صاحب أنطاكية، وسببُ ذلك أن الملك رضوانًا كتب إلى طنكري صاحب أنطاكية يُعَرِّفه ما عليه جاولي من الغدر والمكر والخداع، ويحذِّره منه ويُعلِمُه أنه قصد حلب وأنَّه إن ملكها لا يبقى للفرنج معه بالشام مقام، وطلب منه النصرة والاتفاق على منعه. فأجابه طنكري إلى منعه، وبرز من أنطاكية، فأرسل إليه رضوان ستمائة فارس، فلما سمع جاولي الخبر أرسل إلى القمص "},{"id":1802,"era":"c6","t":"محاولة الباطنية استيلاءهم على حصن شيزر واغتيالهم للقضاة .","s":"حاول الباطنية الإسماعيلية الاستيلاءَ على حصن شيزر مستغلين خروج أصحابه بني منقذ منه، ولكنَّ بني منقذ أدركوهم وقاتلوهم حتى أخرجوهم من الحصن وقُتل من الطرفين الكثير، كما قام الباطنية الإسماعيلية باغتيال عدد من القضاة، منهم: قاضي أصبهان عبيد الله بن علي الخطيبي، وقتلوا قاضي نيسابور صاعد بن محمد أبو العلاء البخاري، وقتلوا أيضًا قاضي آمد عبد الواحد بن إسماعيل الروياني الشافعي، وقام في السنة التالية بعض "},{"id":1803,"era":"c6","t":"وفاة الخطيب التبريزي .","s":"هو إمام اللغة أبو زكريا يحيى بن علي بن محمد، المعروف بالخطيب التبريزي، أحد أعلام اللغة والأدب في القرن الخامس الهجري، وصاحب الشروح المعروفة لعدد من المجموعات الشعرية، مثل: المعلَّقات، والمُفَضَّليات، والحماسة. وكان أصله من تبريز، ونشأ ببغداد ورحل إلى بلاد الشام، فقرأ \"تهذيب اللغة\" للأزهري، على أبي العلاء المعري، قيل: أتاه يحمل نسخة \"التهذيب\" في مِخْلاة على ظهره، وقد بلَّلَها عرقُه حتى ليظُنُّ من ي"},{"id":1804,"era":"c6","t":"الصلح بين السنة والشيعة ببغداد .","s":"اصطلح عامةُ بغداد السُّنَّة والشيعة، وكان الشرُّ منهم على طول الزمان، وقد اجتهد الخلفاء والسلاطين والشُحن -المسؤولون عن ضبط الأمن- في إصلاح الحال، فتعذر عليهم ذلك إلى أن أذن الله تعالى فيه، وكان بغير واسطة، وكان السبب في ذلك أن السلطان محمدًا لما قَتَل ملك العرب صدقة خاف الشيعة ببغداد أهل الكرخ وغيرهم؛ لأن صدقة كان يتشيَّع هو وأهل بيته، فشنَّع أهل السُّنَّة عليهم بأنهم نالهم غمٌّ وهَمٌّ لقتله، فخا"},{"id":1805,"era":"c6","t":"القتال بين يحيى بن تميم صاحب إفريقيا والروم .","s":"جهَّز يحيى بن تميم، صاحب إفريقية، خمسة عشر شينيًا -سفن حربية كبيرة- وسيَّرها إلى بلاد الروم، فلقيها أسطول الروم، وهو كبير، فقاتلوهم وأخذوا ست قطع من شواني المسلمين، ولم ينهزم بعد ذلك ليحيى جيشٌ في البحر والبر."},{"id":1806,"era":"c6","t":"الفرنج يسيطرون على مدينة جبيل وبانياس .","s":"لما فرغ الفرنج من طرابلس سار طنكري، صاحب أنطاكية، إلى بانياس وحَصَرها وافتتحها، وأمَّن أهلها، ونزل مدينة جبيل، وفيها فخر الملك بن عمار الذي كان صاحب طرابلس، وكان القوت فيها قليلًا، فقاتلها إلى أن ملكها في الثاني والعشرين من ذي الحجة من السنة بالأمان، وخرج فخر الملك بن عمار سالِمًا، ووصل عَقيبَ ملك طرابلس الأسطولُ المصري بالرجال والمال والغلال وغيرها ما يكفيهم سنة، فوصل إلى صور بعد أخذ طرابلس بثمان"},{"id":1807,"era":"c6","t":"إخضاع يحيى بن تميم صاحب إفريقيا أهالي مدينة سفاقس .","s":"سيَّرَ يحي بن تميم ابنه أبي الفتوح إلى مدينة سفاقس واليًا عليها، فثار به أهلُها، فنهبوا قصرَه، وهمُّوا بقتله، فلم يزل يحيى يعمِلُ الحيلة عليهم، حتى فرَّق كلمتَهم، وبدَّد شملَهم، وملَك رقابَهم فسجنَهم، وعفا عن دمائِهم وذنوبِهم."},{"id":1808,"era":"c6","t":"سقوط طرابلس في يد الصليبيين .","s":"احتلَّ الفرنج طرابلس، وسبب ذلك أن طرابلس كانت قد صارت في حكم العُبيديين في مصر ونائبهم فيها، والمدد يأتي إليها منه، فلما كانت هذه السنة أول شعبان وصل أسطولٌ كبير من بلد الفرنج في البحر، ومُقدَّمهم قمص كبير القساوسة- اسمه ريمند بن صنجيل، ومراكبه مشحونة بالرجال والسلاح والميرة، فنزل على طرابلس، وكان نازلًا عليها قبله السرداني ابن أخت صنجيل، فجرى بينهما فتنة أدت إلى الاقتتال بينهما، فوصل طنكري صاحب أ"},{"id":1809,"era":"c6","t":"خروج جماعة من الفقهاء لقتال الفرنجة في الشام .","s":"في أوائل هذه السنة تجهَّز جماعة من البغدادية من الفقهاء وغيرهم، ومنهم ابن الزاغوني، للخروج إلى الشام لأجل الجهاد، وقتال الفرنج، وذلك حين بلغهم أنهم فتحوا مدائن عديدة، من ذلك مدينة صيدا وغيرها من المدائن، ثم رجع كثيرٌ منهم حين بلغهم كثرة الفرنج."},{"id":1810,"era":"c6","t":"سقوط قلعة الأثارب وعدد من الحصون بالشام في يد الفرنج .","s":"جمع صاحِبُ أنطاكية عساكِرَه من الفرنج، وحشد الفارِسَ والراجِلَ، وسار نحو حصن الأثارب، وهو بالقرب من مدينة حلب بينهما ثلاثة فراسخ، وحصره ومنع عنه الميرة، فضاق الأمر على من به من المسلمين، فنقبوا من القلعة نقبًا قصدوا أن يخرجوا منه إلى خيمة صاحب أنطاكية فيقتُلوه، فلما فعلوا ذلك وقربوا من خيمتِه استأمن إليه صبيٌّ أرمنيٌّ، فعرَّفه الحال فاحتاط واحترز منهم، وجَدَّ في قتالهم حتى ملك الحصن قهرًا وعنوة، و"},{"id":1811,"era":"c6","t":"عقد أمراء الشام الهدنة مع الفرنج .","s":"لما فتح الفرنج معظم بلاد الشام عَظُمَ خوفُ المسلمين منهم وبلغت القلوبُ الحناجِرَ، وأيقنوا باستيلاء الفرنج على سائر الشام لعدم الحامي له والمانع عنه، فشرع أمراء بلاد الشام في الهدنة معهم، فامتنع الفرنج من الإجابة إلا على قطيعة يأخذونها إلى مدة يسيرة، فصالحهم الملك رضوان، صاحب حلب، على اثنين وثلاثين ألف دينار وغيرها من الخيول والثياب، وصالحهم صاحب صور على سبعة آلاف دينار، وصالحهم ابن منقذ، صاحب شيزر"},{"id":1812,"era":"c6","t":"القضاء على تمرد والي عسقلان  .","s":"كانت عسقلان للفاطميين المصريين، ثم إنَّ حاكِمَ مصر الفاطمي الآمر بأحكام الله استعمل عليها إنسانًا يُعرَف بشمس الخلافة، فراسل بغدوين ملك الفرنج بالشام وهادنه، وأدَّى إليه مالًا وعروضًا، فامتنع به من أحكام المصريين عليه إلا فيما يريد من غير مجاهدة بذلك، فوصلت الأخبارُ بذلك إلى الآمر صاحب مصر، وإلى وزيره الأفضل، أمير الجيوش، فعَظُم الأمر عليهما، وجهَّزا عسكرًا وسيَّراه إلى عسقلان مع قائد كبير من قوَّ"},{"id":1813,"era":"c6","t":"محاولات التجار والفقهاء والعامة نصرة إخوانهم المسلمين في الشام .","s":"أقلعت مراكِبُ من ديار مصر فيها التجار ومعهم الأمتعة الكثيرة؛ لنصرة إخوانهم في الشام، فوقع عليها مراكب الفرنج، فأخذوها وغنموا ما مع التجار وأسروهم، فسار جماعة من أهل حلب إلى بغداد مُستنفِرين على الفرنج. فلما وردوا بغداد اجتمع معهم خلق كثير من الفقهاء وغيرهم فقصدوا جامع السلطان واستغاثوا، ومنعوا من الصلاة وكسروا المنبر، فوعدهم السلطان بإنفاذ العساكر للجهاد، وسيَّر من دار الخلافة منبرًا إلى جامع السل"},{"id":1814,"era":"c6","t":"وفاة الكياالهراسي الشافعي .","s":"هو أحد الفقهاء الكبار، من رؤس الشافعية: علي بن محمد بن علي الفقيه الشافعي المشهور بالكيا الهراسي، لقبه عماد الدين، كان من أهل طبرستان, ولد سنة 450. كان مليح الوجه، جَهْوريَّ الصوت، فصيحًا زكي الأخلاق, وحَظِيَ بالحشمة والجاه والتجمُّل. روى شيئًا يسيرًا عن أبي المعالي وغيره. خرج إلى نيسابور، وتفقَّه على أبي المعالي الجويني، وكان من رؤوس معيديه، وقدم بغداد ودرس بالنظامية ووعظ وذكر مذهب الأشعري، واتُّ"},{"id":1815,"era":"c6","t":"سقوط مدينة صيدا في يد الفرنج .","s":"احتلَّ الفرنج مدينة صيدا من ساحل الشام. وسبب ذلك أنه وصل في البحر إلى الشام ستون مركبًا للفرنج مشحونة بالرجال والذخائر مع بعض ملوكهم؛ ليحُجَّ بيت المقدس، وليغزو –بزعمه- المسلمين؛ فاجتمع بهم بغدوين ملك القدس، وتقررت القاعدة بينهم أن يقصِدوا بلاد الإسلام، فرحلوا من القدس ونزلوا مدينة صيدا ثالث ربيع الآخر من هذه السنة، وضايقوها برًّا وبحرًا، وكان الأسطول المصري مقيمًا على صور، فلم يقدِرْ على إنجاد صي"},{"id":1816,"era":"c6","t":"قتال الأمير مودود بن زنكي للفرنجة وانتزاع حصون كثيرة منهم .","s":"اجتمعت العساكرُ التي أمرها السلطان بالمسير إلى قتال الفرنج، وهم الأمير مودود بن زنكي صاحب الموصل، والأمير سكمان القطبي صاحب تبريز، وبعض ديار بكر، والأمير إيلبكي وزنكي ابنا برسق، ولهما همذان وما جاورها، والأمير أحمديل، وله مراغة، وكوتب الأمير أبو الهيجاء، صاحب إربل، والأمير إيلغازي، صاحب ماردين، والأمراء البكجية، باللحاق بالملك مسعود ومودود، فاجتمعوا ما عدا الأمير إيلغازي؛ فإنه سير ولده إيازًا وأقا"},{"id":1817,"era":"c6","t":"الأسبان يهاجمون قرطبة ويُصدُّون عنها .","s":"خرج ألفونسو الفرنجي، صاحب طليطلة بالأندلس، إلى بلاد الإسلام، يطلب مُلكَها والاستيلاءَ عليها، وجمع وحشد فأكثر، وكان قد قَوِيَ طمعه فيها بسبب موت أمير المسلمين يوسف بن تاشفين، فسمع أمير المسلمين علي بن يوسف بن تاشفين الخبرَ، فسار إليه في عساكره وجموعه، فلقيه، فاقتتلوا واشتد القتال، وكان الظفر للمسلمين، وانهزم الفرنج وقُتِلوا قتلًا ذريعًا، وأُسِرَ منهم بشر كثير، وسبى منهم وغَنِمَ من أموالهم ما لا يُح"},{"id":1818,"era":"c6","t":"الإمبراطور البيزنطي يستنجد بالسلطان السلجوقي ضد الصليبيين  .","s":"ورد رسولُ ملك الروم إلى السلطان يستنفِرُه على الفرنج، ويحثُّه على قتالهم ودفعِهم عن البلاد، وكان وصولُه قبل وصول أهل حلب، وكان أهل حلب يقولون للسلطان: أما تتقي الله تعالى أن يكون مَلِكُ الروم أكثرَ حميةً منك للإسلام حتى أرسل إليك في جهادِهم؟!"},{"id":1819,"era":"c6","t":"محاصرة الفرنجة مدينة صور ورحيلهم عنها .","s":"اجتمعت الفرنج على قصد مدينة صور وحَصْرِها، فساروا إليها مع الملك بغدوين، صاحب القدس، وحشدوا وجمعوا ونازلوها وحصروها في الخامس والعشرين من جمادى الأولى، وعملوا عليها ثلاثة أبراج خشب، عُلوُّ البرج سبعون ذراعًا، وفي كل برج ألف رجل، ونصبوا عليها المجانيق، وألصقوا أحدها إلى سور البلد، وأخلَوه من الرجال، وكانت صور للآمر بأحكام الله الفاطمي ونائبه بها عز الملك الأعز، فأحضر أهل البلد واستشارهم في حيلةٍ يد"},{"id":1820,"era":"c6","t":"وفاة أبي حامد الغزالي .","s":"هو الشيخ البحر حُجَّة الإسلام، أُعجوبة الزمان: زين الدين أبو حامد محمد بن محمد بن محمد بن أحمد الغزالي الألوسي الطوسي الشافعي؛ إمام عصره صاحب التصانيف والذكاء المفرط. وُلِدَ بطوس سنة 450, وتفقَّه ببلده أولًا، ثم تحول إلى نيسابور في مرافقة جماعة من الطلبة، فلازم إمام الحرمين، فبرع في عدة علوم في مدة قريبة، ومهر في الكلام والجدل، حتى صار عينَ المناظرين، وشرع في التصنيف. يقول الذهبي: \"سار أبو حامد إل"},{"id":1821,"era":"c6","t":"مقتل الأمير مودود بن التونتكين في جامع دمشق .","s":"هو الأمير المجاهد شرف الدولة مودود بن التونتكين بن الأتابك زنكي -أتابك يعني الأمير الوالد- بن قسيم الدولة آقسنقر التركماني، صاحب الموصل، أمير من أمراء السلاجقة العظام، كان رجلًا فاضلًا عالمًا مجاهدًا, خيِّرا عادلًا كثير الخير, وهو والد عماد الدين زنكي، وهو من جملة الأمراء والنواب الذين قدموا لقتال الفرنج بالشام، ولما دخلوا دمشق دخل الأمير مودود يوم الجمعة إلى جامعها ليصلِّيَ فيه، فجاءه باطني في زي"},{"id":1822,"era":"c6","t":"انتصار المسلمين على الفرنجة في أرض طبرية .","s":"في المحرم اجتمع المسلمون وفيهم الأمير مودود بن التونتكين، صاحب الموصل، وتميرك، صاحب سنجار، والأمير إياز بن إيلغازي، وطغتكين، صاحب دمشق، وكان سبب اجتماع المسلمين أن ملك الفرنج بغدوين تابع الغارات على بلد دمشق ونهبه وخرَّبه أواخر سنة ست وخمسمائة، وانقطعت الموادُّ عن دمشق، فغلت الأسعار فيها وقَلَّت الأقوات، واتفق رأيُهم على قصد بغدوين، ملك القدس، فساروا إلى الأردن، فنزل المسلمون عند الأقحوانة، ونزل ا"},{"id":1823,"era":"c6","t":"إخراج الإسماعيلية من حلب وتحولهم إلى دمشق .","s":"توفِّيَ الملك رضوان بن تاج الدولة تتش بن ألب أرسلان، صاحب حلب، وقام بعده بحلب ابنه ألب أرسلان الأخرس، وعمره ست عشرة سنة، وكان القيِّمُ عليه لؤلؤًا الخادم، وكانت أمور رضوان غير محمودة؛ قَتَل أخويه أبا طالب وبهرام، وكان يستعين بالباطنية في كثير من أموره لقِلَّة دينه، وكان الباطنية قد كثُروا بحلب في أيامه، حتى خافهم ابن بديع رئيس حلب، وأعيان أهلها، فلما توفي الملك رضوان قال ابن بديع لألب أرسلان بن رض"},{"id":1824,"era":"c6","t":"قتل الأخرس بن رضوان بن تتش صاحب حلب .","s":"هو صاحب تاج الدولة الأخرس ألب أرسلان بن رضوان بن تتش صاحب حلب، لما ملك الأخرس بعد أبيه استولى على الأمور لؤلؤ الخادم، ولم يكن للأخرس معه إلا اسم السلطنة، ولم يكن ألب أرسلان أخرس، وإنما في لسانه حُبسة وتمتمة، وقد قضى على الإسماعيلية في حلب بعد أن نصحه بذلك ابن بديع وأعيان حلب, قتله غلمانه، وقام من بعده أخوه سلطان شاه بن رضوان."},{"id":1825,"era":"c6","t":"مسير آقسنقر البرسقي إلى الشام لحرب الفرنج .","s":"سيَّرَ السلطان محمد بن ألب أرسلان الأمير أتسز البرسقي إلى الموصل وأعمالها، واليًا عليها، لما بلغه قتل شرف الدولة مودود بن التونتكين بن زنكي، وسيَّرَ معه ولده الملك مسعودًا في جيش كثيف، وأمره بقتال الفرنج، وكتب إلى سائر الأمراء بطاعته، فوصل إلى الموصل، واتصلت به عساكرها، وفيهم عماد الدين زنكي بن آقسنقر, واتصل به أيضًا تميرك صاحب سنجار وغيرهما، فسار البرسقي إلى جزيرة ابن عمر، فسلَّمها إليه نائب مودو"},{"id":1826,"era":"c6","t":"أمير دمشق طغتكين وإيلغازي أمير ماردين يحالفان الصليبيين .","s":"كان طغتكين أمير دمشق قد استوحش من السلطان محمد بن ألب أرسلان؛ لأنه نسب إليه قتل مودود، فاتفق هو وإيلغازي أمير ماردين على الامتناع والالتجاء إلى الفرنج، والاحتماء بهم، وإيلغازي كان ناقمًا على أتسز البرسقي لأسرِ ابنه إياز، فراسلا صاحب أنطاكية وحالفاه، فحضر عندهما على بحيرة قدس عند حمص، وجدَّدوا العهود، وعاد إلى أنطاكية، وعاد طغتكين إلى دمشق، وسار إيلغازي إلى الرستن قاصدًا ديار بكر، فتَمَّ أسرُه على "},{"id":1827,"era":"c6","t":"بدء الصراع في الدولة الغزنوية بين الإخوة أحفاد محمود الغزنوي .","s":"توفِّي الملك علاء الدولة أبو سعد مسعود بن أبي المظفر إبراهيم بن أبي سعد مسعود بن محمود بن سبكتكين، صاحب غزنة، في شوال، وملك بعده ابنه أرسلانشاه، فقبض على إخوته وسجنهم، وهرب أخ له اسمه بهرام إلى خراسان، فوصل إلى السلطان سنجر بن ملكشاه، فأرسل إلى أرسلانشاه في معناه، فلم يسمع منه، ولا أصغى إلى قوله، فتجهز سنجر للمسير إلى غزنة، وإقامة بهرامشاه في الملك، فأرسل أرسلانشاه إلى السلطان محمد يشكو من أخيه سن"},{"id":1828,"era":"c6","t":"حملة سلجوقية لإخضاع طغتكين والبرسقي لتحالفهما مع الفرنج .","s":"جهَّز السلطان غياث الدين محمد بن ملكشاه جيشًا كثيفًا مع الأمير برشق بن إيلغازي صاحب ماردين إلى صاحب دمشق طغتكين، وإلى أتسز البرسقي ليقاتلهما؛ لأجل عصيانهما عليه، وقطْع خطبته، وإذا فرغ منهما عمد لقتال الفرنج، فلما اقترب الجيش من بلاد الشام هربا منه وتحيَّزا إلى الفرنج، وجاء الأمير برشق إلى كفر طاب ففتحها عَنوة، وأخذ ما كان فيها من النساء والذرية، وجاء صاحب أنطاكية روجيل في خمسمائة فارس وألفي راجل، "},{"id":1829,"era":"c6","t":"انتصار الصليبيين على المسلمين في معركة تل دانيث .","s":"نزلت العساكِرُ السلطانية أرض شيزر، وجعل أتابك طغتكين دمشق يُرَيِّث الفرنج عن اللقاءِ خوفًا من الفرنج أن يَكسِروا العساكر السلطانية فيأخذوا الشام جميعه، أو ينكسروا فتستولي العساكر السلطانية على ما في يده. وخاف الفرنج وضاقت صدورُ أمراء عسكر السلطان من المصابرة، فرحلوا ونزلوا حصن الأكراد وأشرف على الأخذ، فاتفق أتابك والفرنج على عودِ كلِّ قوم إلى بلادهم، ففعلوا ذلك. وتوجه أتابك إلى دمشق، وعاد عسكر حلب"},{"id":1830,"era":"c6","t":"احتلال الفرنج رفنية ثم استعادها المسلمون منهم .","s":"احتلَّ الفرنج رفنية من أرض الشام، وهي لطغتكين، صاحب دمشق، وقوَّوها بالرجال والذخائر، وبالَغوا في تحصينها، فاهتَمَّ طغتكين لذلك، وقَوِيَ عزمه على قَصدِ بلاد الفرنج بالنَّهبِ لها والتخريبِ، فأتاه الخبَرُ عن رفنية بخُلوِّها من عسكر يمنَعُ عنها، وليس هناك إلا الفرنجُ الذين رتَّبوا لحفظها، فسار إليها جريدة، فلم يشعرْ من بها إلا وقد هجم عليهم البلد فدخله عَنوةً وقهرًا، وأخذ كل من فيه من الفرنج أسيرًا، ف"},{"id":1831,"era":"c6","t":"وقوع الفتنة بين العامة ببغداد .","s":"وقعت الفتنةُ بين العامة في بغداد، وسببها أن الناسَ لما عادوا من زيارة قبر مصعب بن الزبير اختصموا على من يدخل أولًا، فاقتتلوا، وقُتِل بينهم جماعة، وعادت الفِتَن بين أهل المحالِّ كما كانت، ثم سكَنَت."},{"id":1832,"era":"c6","t":"وفاة يحيى بن تميم الصنهاجي صاحب أفريقيا وولاية ابنه علي .","s":"هو أبو طاهر يحيى بن تميم بن المعز بن باديس الحميري الصنهاجي صاحب إفريقية وما والاها, كان من خيار الملوك، عارفًا حسن السيرة، كان عادلًا في دولته ضابطًا لأمور رعيته، عارفًا بخرجه ودخله، مدبرًا في جميع ذلك على ما يوجبه النظر العقلي ويقتضيه الرأي الحكمي، وكان كثيرَ المطالعة لكتب الأخبار والسِّيَر، عارفًا بها، رحيمًا للضعفاء شفيقًا على الفقراء، يُطعِمُهم في الشدائد فيرفُق بهم، ويقرب أهل العلم والفضل من"},{"id":1833,"era":"c6","t":"فتح جبل وسلات وتونس .","s":"حاصر عسكر علي بن يحيى، صاحب إفريقية، مدينة تونس، وبها أحمد بن خراسان، وضَيَّق على من بها، فصالحه على ما أراد وفتح أيضًا جبل وسلات بإفريقية، واستولى عليه، وهو جبل منيع، ولم يزل أهله طول الدهر يفتكون بالناس، ويقطعون الطريق، فلما استمَرَّ ذلك منهم سيَّرَ إليهم جيشًا، فكان أهل الجبل ينزلون إلى الجيش، ويقاتلون أشد قتال، فعمل قائد الجيش الحيلةَ في الصعود إلى الجبل من شعب لم يكن أحد يظن أنه يُصعد منه، فل"},{"id":1834,"era":"c6","t":"إصلاح جاولي سقاوو لبلاد فارس بتكليف من محمد بن ملكشاه .","s":"كان السلطانُ محمد بن ملكشاه ببغداد عازمًا على المقام بفارس، فاضطرَّ إلى المسير إلى أصبهان ليكونَ قريبًا من فارس؛ لئلَّا تختلف عليه، ولما قصده جاولي سقاوو ورضي عنه أقطعَه بلاد فارس، بعد أن أخذ منه الموصل, فسار جاولي إليها ومعه ولد السلطان جغري، وهو طفل له من العمر سنتان، وأمره بإصلاحها، وقَمْعِ المفسدين بها، فسار إليها، فأوَّل ما اعتمده فيها أنه لم يتوسط بلاد الأمير بلدجي، وهو من كبار مماليك السلطا"},{"id":1835,"era":"c6","t":"استعادة المرابطين جزائر (البليار) بالأندلس من النصارى .","s":"كانت الجزائر الشرقية البليار تحت سيطرة بني هود إلى أن أخذها منهم النصارى، ثم قام المرابطون باستردادها بعد سنة من احتلالها من قبل برشلونة."},{"id":1836,"era":"c6","t":"مقتل الأمير أحمديل الروادي صاحب مراغة .","s":"هو أحمديل بن إبراهيم بن وهسوذان الروادي، الكردي، صاحب مراغة وغيرها من أذربيجان. في أول المحرم حضر أتابك طغتكين، صاحب دمشق، دارَ السلطان محمد ببغداد، وحضر جماعة من الأمراء ومعهم أحمديل وهو جالس إلى جانب طغتكين، فأتاه رجل متظلِّم، وبيده رقعة، وهو يبكي، ويسأله أن يوصِلَها إلى السلطان، فأخذها من يده، فضربه الرجلُ بسكين فجذبه أحمديل فبرك فوقَه، فوثب رفيق للباطني وضرب أحمديل سكينًا أخرى، فأخذَتْهما السي"},{"id":1837,"era":"c6","t":"الفتنة بطوس في يوم عاشوراء .","s":"في عاشوراء كانت فتنة عظيمة بطوس في مشهد علي بن موسى الرضا، وسببها أن علويًّا خاصم في المشهد يوم عاشوراء بعض فقهاء طوس، فأدى ذلك إلى خصومة وعراك بالأيدي، وانقطعت الفتنة، ثم استعان كل منهما بحزبه، فثارت فتنة عظيمة حضرها جميع أهل طوس، وأحاطوا بالمشهد وخربوه، وقتلوا من وجدوا، فقُتِل بينهم جماعة ونُهِبت أموال جمةٌ، وافترقوا، وتَرَك أهل المشهد الخطبةَ أيام الجمعات فيه، فبنى عليه عضد الدين فرامرز بن علي "},{"id":1838,"era":"c6","t":"حصار مدينة قابس والمهدية .","s":"جهَّز علي بن يحيى، صاحب إفريقية، أسطولًا في البحر إلى مدينة قابس وحصرها، وسببُ ذلك أن صاحبها رافع بن مكن الدهماني أنشأ مركبًا بساحلها ليحمل التجار في البحر، فلما خاف رافع أن يمنعه علي التجأ إلى رجار ملك الفرنج بصقلية، واعتضد به، فوعده رجار أن ينصُرَه ويُعينَه على إجراء مركبه في البحر، وتمادى رافع في المخالفة لعلي، وجمع قبائل العرب وسار بهم حتى نزل على المهدية محاصرًا لها، وخادع عليًّا، وقال: إنني "},{"id":1839,"era":"c6","t":"قتل لؤلؤ الخادم صاحب حلب واستيلاء إيلغازي عليها .","s":"هو لؤلؤ الخادم مملوك رضوان، كان لؤلؤ يتولى قلعة حلب حسده مماليك سيده رضوان فقتلوه, وكان قد استولى على قلعة حلب وأعمالها بعد وفاة الملك رضوان، ووَلِيَ أعمالَ ولَدِه الأخرسِ ألب أرسلان، فلما مات الأخرس أقام لؤلؤ بعده في الملك سلطانشاه بن رضوان، وحكم في دولته أكثر من حكمه في دولة أخيه، فلما كانت هذه السنة سار لؤلؤ من حلب إلى قلعة جعبر ليجتمع بالأمير سالم بن مالك صاحبها، فلما كان عند قلعة نادر نزل يري"},{"id":1840,"era":"c6","t":"حدوث زلزلة يوم عرفة بالعراق والجزيرة وكثير من البلاد .","s":"في يوم عرفة من هذا العام كانت زلزلة بالعراق والجزيرة وكثير من البلاد، وخُرِّبت ببغداد دورٌ كثيرة بالجانب الغربي."},{"id":1841,"era":"c6","t":"وفاة السلطان السلجوقي محمد بن ملكشاه وملك ابنه محمود بعده .","s":"هو غياثُ الدين أبو شجاع السلطان محمد بن ملكشاه بن ألب أرسلان بن داود بن ميكائيل بن سلجوق، سلطان بلاد العراق وخراسان وغير ذلك من البلاد الشاسعة, والأقاليم الواسعة. كان من خيار الملوك وأحسنهم سيرة، عادلًا رحيمًا، سهل الأخلاق، محمود العشرة، لما توفي والده ملكشاه اقتسم مملكته أولادُه الثلاثة وهم: بركيارق، وسنجر، ومحمد، ولم يكن لمحمد وسنجر، وهما من أم واحدة، وجود في اهتمام بركيارق؛ لأنه كان السلطان الم"},{"id":1842,"era":"c6","t":"قيام ثلاث إمارات صليبية ومملكة بيت المقدس .","s":"خلال الحملة الصليبية الأولى قام أحد الجيوش الفرنج بقيادة بغدوين -ويقال: بردويل- بالانعطاف شرقًا أثناء حصار أنطاكية إلى الرها التي سرعان ما سقطت في يده، مؤسِّسًا أول إمارة صليبية في الشرق الأوسط في ربيع الأول سنة 491، وفي تلك الأثناء استولى بوهمند أحد القادة الصليبين على أنطاكية، وأسس فيها الإمارة الثانية، ثم استولى ريموند على طرابلس وأسس فيها الإمارة الثالثة، وكانت ثلاث الإمارات تابعة بشكل صوري لم"},{"id":1843,"era":"c6","t":"ظهور فرقتي الداوية والاسبتارية في بيت المقدس .","s":"أنشأ الصليبيون بعد احتلالهم بيت المقدس فرقه دينية عُرِفت بالداوية أو بفرسان المعبد، وأقامت في موضع قرب المسجد الأقصى، وقد انتسب إليها النبلاء والأشراف، وقيل: إن مهمة هذه المنظمة هي الحفاظ على مقدسات الكنيسة، وحماية كل ما هو مرتبط من المقدسات سواء كانت أرواحًا أو آثارًا أو أي شيء له ارتباط بقداسة المسيحية عندهم، ثم أنشأ الصليبيون فرقة أخرى عُرِفَ أصحابها بالاسبتارية؛ لنفس الغرض، وإن كانت أقل قوة ون"},{"id":1844,"era":"c6","t":"طغتكين أتابك دمشق يغزو الفرنج .","s":"كان أتابك طغتكين قد سار عن دمشق لقتال الفرنج، فنزل بين دير أيوب وكفر بصل باليرموك، فخفيت عنه وفاة بغدوين، حتى سمع الخبر بعد ثمانية عشر يومًا، وبينهم نحو يومين، فأتته رسل ملك الفرنج يطلب المهادنة، فاقترح عليه طغتكين ترك المناصفة التي بينهم من جبل عوف، والحنانة، والصلت، والغور، فلم يُجِبْ إلى ذلك، وأظهر القوة؛ فسار طغتكين إلى طبرية فنهبها وما حولها، وسار منها نحو عسقلان."},{"id":1845,"era":"c6","t":"الصليبيون يحاولون غزو مصر ثم هلاك ملك الفرنج بغدوين  .","s":"سار بغدوين ملك القدس إلى ديار مصر في جمع الفرنج، قاصدًا ملكها والتغلب عليها، وقوي طمعه في الديار المصرية، وبلغ مقابل تنيس وسبح في النيل، فانتقض جرح ٌكان به، فلما أحس بالموت وصَّى ببلاده للقمص -كبير القساوسة- صاحب الرها، وهو الذي كان أسره جكرمش، وأطلقه جاولي سقاوو، واتفق أن هذا القمص كان قد سار إلى القدس يزور بيعة قمامة، فلما وصى إليه بالملك قبله، واجتمع له القدس والرها. وكان بغدوين قد وصل إلى الفر"},{"id":1846,"era":"c6","t":"وفاة الخليفة العباسي المستظهر وتولي ابنه المسترشد بالله الخلافة .","s":"هو أميرُ المؤمنين الخليفة العباسي المستظهر بالله أبو العباس أحمد بن المقتدي بأمر الله أبي القاسم عبد الله بن الذخيرة محمد بن القائم بأمر الله عبد الله بن القادر الهاشمي، العباسي، البغدادي. ولد في شوال سنة 470، وأمه أمُّ ولدٍ، واستُخلِف عند وفاة أبيه في تاسع عشر المحرم وله ست عشرة سنة وثلاثة أشهر، وذلك في سنة 487. كان خيِّرًا فاضلًا ذكيًّا بارعًا كريم الأخلاق، ليِّن الجانب، سخيَّ النفس، مؤثرًا للإح"},{"id":1847,"era":"c6","t":"هزيمة الصليبيين في معركة سهل بلاط (سهل الحلقة) .","s":"سار الفرنج من بلادهم إلى نواحي حلب، فملكوا بزاعة وغيرها، وخربوا بلد حلب ونازلوها، ولم يكن بحلب من الذخائر ما يكفيها شهرًا واحدًا، وخافهم أهلها خوفًا شديدًا، ولو مُكِّنوا من القتال لم يبقَ بها أحد، لكنهم مُنعوا من ذلك، وصانع الفرنج أهل حلب على أن يقاسموهم على أملاكهم التي بباب حلب. فأرسل أهل البلد إلى بغداد يستغيثون ويطلبون النجدة، فلم يُغاثوا، وكان الأمير إيلغازي، صاحب حلب، ببلد ماردين يجمع العساك"},{"id":1848,"era":"c6","t":"حلب بين الغلاء والفرنج\n  .","s":"اشتدَّ الغلاء بأنطاكية وحلب؛ لأن الزرع عرق ولحقه هواء عند إدراكه فأتلفه، وهرب الفلاحون للخوف، واستدعى أهل حلب ابن قراجا من حمص، فرتب الأمور بها، وحصنها، وسار إلى حلب، ونزل في القصر خوفًا من إيلغازي لِما كان بينهما. وخرج أتابك طغتكين من دمشق إلى حمص، ونهب أعمالها وشعثها، وأقام عليها مدة، وعاد إلى دمشق لحركة الفرنج. وخرجت قافلة من حلب إلى دمشق فيها تجار وغيرهم، وحملوا ذخائرهم وأموالهم لما قد أشرف عل"},{"id":1849,"era":"c6","t":"الأسبان يهزمون المرابطين ويستولون على مدينة سرقسطة .","s":"كانت سرقسطة بيد بني هود، وكان أميرها عبد الملك بن أحمد الثاني، وفي هذه السنة قام ألفونسو الأول ملك قشتالة الملقب بالمحارب، قام بالاستيلاء على سرقسطة وأخذها من أيدي بني هود، واتخذها عاصمة لمملكته وحوَّل مسجدها إلى كنيسة، فكان هذا السقوط وسقوط طليطلة من قبلها سببًا في انهيار أكبر معاقل المسلمين في الأندلس، وكان من أكبر أسباب ضعف قوة المرابطين فيها وخاصة بعد أن انضاف لهذا سقوط قلعة أيوب بيد النصارى."},{"id":1850,"era":"c6","t":"معركة بين الصليبيين وبعض قبائل والعرب\n  .","s":"سار جوسلين، صاحب تل باشر، في جمع من الفرنج، نحو مائتي فارس، من طبرية، فكبس طائفة من طي يُعرفون ببني خالد فأخذهم، وأخذ غنائمهم وسألهم عن بقية قومهم من بني ربيعة، فأخبروه أنهم من وراء الحزن، بوادي السلالة، بين دمشق وطبرية، فقدم جوسلين مائة وخمسين فارسًا من أصحابه، وسار هو في خمسين فارسًا على طريق آخر، وواعدهم الصبح ليكبسوا بني ربيعة، فوصلهم الخبر بذلك، فأرادوا الرحيل، فمنعهم أميرهم من بني ربيعة، وكا"},{"id":1851,"era":"c6","t":"وفاة ابن عقيل أبو الوفا الحنبلي .","s":"الإمام العلامة البحر شيخ الحنابلة: أبو الوفاء علي بن عقيل بن محمد بن عقيل بن عبد الله البغدادي، الظفري، الحنبلي، المتكلم، صاحب التصانيف، شيخ الحنابلة في زمانه. ولد سنة 431 هـ, وكان يسكن الظفرية -محلة كبيرة بشرقي بغداد- ومسجده بها مشهور. كان إمامًا مُبرزًا في كثير من العلوم، خارق الذكاء قوي الحجة واللسان، اشتغل أول أمره بمذهب المعتزلة واتُّهِم بالانحراف عن مذهب السنة حتى أراد الحنابلة قَتْلَه، ثم أ"},{"id":1852,"era":"c6","t":"هزيمة السلطان السلجوقي محمود أمام جيوش عمه سنجر .","s":"كانت حربٌ شديدة بين سنجر وابن أخيه السلطان محمود بن محمد، وكان سنجر عزم على قصد بلد الجبال والعراق وما بيد محمود ابن أخيه، ثمَّ إن السلطان محمودًا أرسل إلى عمه سنجر شرف الدين أنوشروان بن خالد وفخر الدين طغايرك بن اليزن، ومعهما الهدايا والتحف، وبذل له النزول عن مازندران، وحمل مائتي ألف دينار كل سنة، فوصلا إليه وأبلغاه الرسالة، فتجهَّز ليسير إلى الري، فأشار عليه شرف الدين أنوشروان بترك القتال والحرب"},{"id":1853,"era":"c6","t":"فتنة دبيس بن صدقة صاحب الحلة ببغداد .","s":"كان دبيس بن صدقة صاحب الحلة بالعراق، فلما بلغه خبر انهزام الملك مسعود أمام أخيه محمود، ركب دبيس بنفسه إلى بغداد، ونصب خيمته بإزاء دار الخلافة، وأظهر ما في نفسه من الضغائن، وذكر كيف طِيفَ برأس أبيه في البلاد أيام السلطان محمد بعد قتله في المعركة سنة 501، فنهب البلاد وخربها، وفعل فيها الأفاعيل القبيحة, وتهدد المسترشد بالله، فأرسل إليه الخليفة يسكِّن جأشه ويَعِدُه أنه سيصلح بينه وبين السلطان محمود، إ"},{"id":1854,"era":"c6","t":"خروج الكرج (الجورجيون، سكان جورجيا) إلى بلاد الإسلام وملك تفليس .","s":"خرج الكرج، وهم الخزر، إلى بلاد الإسلام، وكانوا قديمًا يُغيرون، فامتنعوا أيام السلطان ملكشاه إلى آخر أيام السلطان محمد، فلما كانت هذه السنة خرجوا ومعهم قفجاق وغيرهم من الأمم المجاورة لهم، فتكاتب الأمراء المجاورون لبلادهم، واجتمعوا، منهم: الأمير إيلغازي صاحب ماردين، ودبيس بن صدقة صاحب الحلة، وكان عنده، والملك طغرل بن محمد، وأتابكه كنتغدي، وكان لطغرل بلد أران، ونقجوان إلى أرس، فاجتمعوا وساروا إلى الك"},{"id":1855,"era":"c6","t":"إيلغازي صاحب ماردين يغزو الفرنج .","s":"سار إيلغازي صاحب ماردين إلى الفرنج، وكان قد جمع لهم جمعًا، فالتقوا بموضع اسمه ذات البقل من أعمال حلب، فاقتتلوا، واشتدَّ القتال، وكان الظفر له، ثم اجتمع إيلغازي وأتابك طغتكين، صاحب دمشق، وحصروا الفرنجَ في معرة قنسرين يومًا وليلة، ثم أشار أتابك طغتكين بالإفراج عنهم؛ كيلا يحمِلَهم الخوف على أن يستقتلوا ويخرجوا إلى المسلمين، فربما ظفروا، وكان أكثر خوف طغتكين من دبر خيل التركمان، وجودة خيل الفرنج، فأفر"},{"id":1856,"era":"c6","t":"ظهور دولة الموحدين بعد انتصار ابن تومرت على جيش المرابطين .","s":"سار ابنُ تومرت بعد أن أخرجه أمير المسلمين علي بن يوسف بن تاشفين من مراكش، إلى أغمات, ثم لحق بالجبل، فسار فيه، حتى التحق بالسوس وتسامع به أهل تلك النواحي، فوفدوا عليه، وحضر أعيانُهم بين يديه، وجعل يَعِظُهم، ويذكِّرُهم بأيام الله، ويذكر لهم شرائع الإسلام، وما غيِّر منها، وما حدث من الظلم والفساد، وأنه لا يجب طاعة دولة من هذه الدول؛ لاتباعهم الباطل، بل الواجب قتالهم، ومَنْعُهم عما هم فيه، وسمَّى أتبا"},{"id":1857,"era":"c6","t":"حصر ابن ردمير الإفرنجي مدينة كتندة بالأندلس .","s":"خرج ملك من ملوك الفرنج بالأندلس، يقال له ابن ردمير، فسار حتى انتهى إلى كتندة، وهي بالقرب من مرسية، في شرق الأندلس، فحصرها، وضيَّق على أهلها، وكان أمير المسلمين علي بن يوسف حينئذ بقرطبة، ومعه جيشٌ كثير من المسلمين والأجناد المتطوعة، فسيَّرهم إلى ابن ردمير، فالتقَوا واقتتلوا أشد القتال، وهزمهم ابن ردمير هزيمة منكرة، وكثر القتل في المسلمين، واستطاع الفرنج أن يستولوا على قلعة أيوب، وهي من أشد القلاع ح"},{"id":1858,"era":"c6","t":"القتال بين السلطان محمود بن ملكشاه وأخيه مسعود .","s":"في النصف من ربيع الأول كانت وقعة عظيمة بين الأخوين السلطان محمود ومسعود ابني محمد بن ملكشاه عند عقبة اسداباذ، وحصلت بينهما حروب وقتال كانت نهايتها انهزام عسكر مسعود وأسْر وزيره الأستاذ أبي إسماعيل وجماعة من أمرائه، فأمر السلطان محمود بقتل الوزير أبي إسماعيل، فقُتِل، ثم إن مسعودًا رحل إلى الموصل وحاول الذهابَ إلى العراق مع دبيس، لكن أخاه محمودًا أرسل إليه الأمان واستقدمه عليه، فلما التقيا بكيا واصط"},{"id":1859,"era":"c6","t":"احتراق دار السُّلطان محمود السُّلجوقي وجامع أصبهان .","s":"احتَرَقت دارُ السُّلطانِ مَحمودِ بنِ مُحمَّد السُّلجوقي، كان قد بناها مُجاهِدُ الدِّينِ بهروز للسُّلطانِ مُحمَّد، ففُرِغَت قبل وفاتِه بيَسيرِ، وسَبَبُ الحَريقِ أنَّ جاريةً كانت تخضَّبَت ليلًا، فأسندت شمعةً إلى الخيش فاحتَرَق، وعَلِقَت النار منه في الدار، واحتَرَق فيها مِن مالِ زَوجةِ السُّلطان محمود بنت السُّلطان سنجر ما لا حَدَّ له من الجواهِرِ والحُلي والفَرشِ والثِّيابِ، وأقيم الغَسَّالون يُخَل"},{"id":1860,"era":"c6","t":"حصر بلك بن بهرام الرها وأسر صاحبها جوسلين الإفرنجي .","s":"سار بلك بن بهرام، ولد أخي إيلغازي، إلى مدينة الرها، فحصرها وبها الفرنج، وبقي على حصرها مدة، فلم يظفر بها، فرحل عنها، فجاءه إنسان تركماني وأعلمه أن جوسلين، صاحب الرها وسروج، قد جمع مَن عنده من الفرنج، وهو عازم على كبسه، وكان قد تفرَّق عن بلك أصحابه، وبقي في أربعمائة فارس، فوقف مستعدًّا لقتالهم، وأقبل الفرنج، فمِن لطف الله تعالى بالمسلمين أن الفرنج وصلوا إلى أرض قد نضب عنها الماء، فصارت وحلًا غاصت خ"},{"id":1861,"era":"c6","t":"الفتنة بين المرابطين وأهل قرطبة\n  .","s":"في هذه السنة، وقيل سنة 514، كانت فتنة بين عسكر أمير المسلمين علي بن يوسف، وبين أهل قرطبة. وسببها: أن أمير المسلمين استعمل عليها أبا بكر يحيى بن رواد، فلما كان يوم الأضحى خرج الناس متفرجين، فمدَّ عبد من عبيد أبي بكر يدَه إلى امرأة فأمسكها، فاستغاثت بالمسلمين، فأغاثوها، فوقع بين العبيد وأهل البلد فتنة عظيمة، ودامت جميع النهار، والحرب بينهم قائمة على ساق، فأدركهم الليل، فتفرَّقوا، فوصل الخبر إلى الأم"},{"id":1862,"era":"c6","t":"اغتيال الأفضل بن بدر الجمالي وزير الفاطميين .","s":"هو أمير الجيوش أبو القاسم شاهنشاه الملك الأفضل بن أمير الجيوش بدر الجمالي. كان والده بدر أرمنيًّا، اشتراه جمال الدولة بن عمار، وتربى عنده وتقدم بسببه، كان بدر نائبًا بعكا، فسار في البحر في ترميم دولة المستنصر العبيدي، فاستولى على الإقليم، وأباد عدة أمراء، ودانت له الممالك إلى أن مات، فقام بعده ابنه الأفضل، وعَظُم شأنه، وأهلك نزارًا ولد المستنصر صاحب دعوة الباطنية الإسماعيلية أصحاب ابن الصباح وقلعة"},{"id":1863,"era":"c6","t":"سقوط ثلج كبير بالعراق من البصرة إلى تكريت .","s":"سقط بالعراق جميعه من البصرة إلى تكريت ثلج كبير، وبقي على الأرض خمسة عشر يومًا، وسُمكُه ذراع، وهلكت أشجارُ النارنج، والأُترج، والليمون."},{"id":1864,"era":"c6","t":"مقتل الأمير جيوش بيك صاحب الموصل .","s":"هو الأميرُ جيوش بك صاحب الموصل كان تركيًا من مماليك السلطان محمد، عادلًا، حسن السيرة، ولما وليَ الموصل والجزيرة كان الأكراد بتلك الأعمال قد انتشروا، وكثُر فسادهم، وكثرت قلاعهم، والناس معهم في ضيق، فقصدهم وحصَرَ قلاعَهم، وفتح كثيرًا منها ببلد الهكارية، وبلد الزوزان، وبلد البشنوية، وخافه الأكراد، وتولى قصدهم بنفسه، فهربوا منه في الجبال والشعاب والمضايق، وأمِنَت الطرق، وانتشر الناسُ واطمأنوا، وبقي ال"},{"id":1865,"era":"c6","t":"وفاة الحريري صاحب المقامات .","s":"هو العلامة البارع ذو البلاغتين: أبو محمد القاسم بن علي بن محمد بن عثمان، الأديب اللغوي النحوي البصري الحريري، صاحب المقامات المشهورة، كان يسكن بني حرام أحد محال البصرة مما يلي الشط، مولِدُه ومَرْباه بقرية المشان، من أعمال البصرة، وكان أحد أئمة عصره في الأدب والبلاغة والفصاحة، وله مصنفات كثيرة، من أبرزها المقامات، التي لا نظير لها في معناها، وقد سلك فيها منوالَ بديع الزمان صاحب المقامات، وقد اشتملت"},{"id":1866,"era":"c6","t":"رجوع السلطان طغرل بك إلى طاعة أخيه محمود .","s":"أطاع الملك طغرل أخاه السلطان محمودًا، وكان قد خرج عن طاعته، وقصد أذربيجان في السنة الماضية ليتغلَّبَ عليها، وكان أتابكه كنتغدي يحسِّن له ذلك، ويقويه عليه، فاتفق أنه مَرِض، وتوفي في شوال سنة 515، وكان الأمير آقسنقر الأحمديلي، صاحب مراغة، عند السلطان محمود ببغداد، فاستأذنه في المضي إلى إقطاعه، فأذن له، فلما سار عن السلطان ظن أنه يقوم مقام كنتغدي من الملك طغرل، فسار إليه، واجتمع به، وأشار عليه بالمكا"},{"id":1867,"era":"c6","t":"مقتل أبي طالب السميرمي وزير السلطان محمود الغزنوي .","s":"هو الوزير الكبير، أبو طالب علي بن أحمد بن علي السميرمي، وزير السلطان محمود الغزنوي السلجوقي، صدرٌ معظَّم، كبير الشأن، شديد الوطأة، ذو عسف وظلم، وسوء سيرة، وقف مدرسة بأصبهان، وعمل بها خزانة كتب نفيسة، وكان مجاهرًا بالظلم والفسق، وأحدث على الناس مكوسًا وجدَّدها بعدما كانت قد أزيلت من مدة متطاولة. وكان يقول: \"استحييتُ من كثرة ظلمِ من لا ناصِرَ له، وكثرةِ ما أحدثتُ من السُّنَن السيئة!\". لما عزم على ال"},{"id":1868,"era":"c6","t":"وفاة نجم الدولة إيلغازي واقتسام دولته بعد العدوان الصليبي .","s":"هو الملك إيلغازي نجم الدين بن الأمير أرتق بن أكسب التركماني، صاحب ماردين، وحلب، وميافارقين، كان هو وأخوه الأمير سقمان من أمراء تاج الدولة تتش صاحب الشام، فأقطعهما القدس، وجرت لهما سِيَر، ثم استولى إيلغازي على ماردين. وكان ذا شجاعة ورأي وهيبة وصيتٍ، وجوادًا محترِمًا للمسلمين. حارب الفرنج غير مرة، وأخذ حلب بعد أولاد رضوان بن تتش، واستولى على ميافارقين وغيرها قبل موته بسنة, وهو أول من تملك ماردين، وا"},{"id":1869,"era":"c6","t":"وفاة البغوي صاحب التفسير .","s":"هو الشيخ الإمام العلَّامة القدوة الحافظ، شيخ الإسلام، محيي السنة: أبو محمد الحسين بن مسعود بن محمد بن الفراء البغوي، الشافعي، نسبة إلى بغا من قرى خراسان، صاحب التفسير المعروف بمعالم التنزيل، وشرح السنة، والتهذيب في الفقه الشافعي، والجمع بين الصحيحين، والمصابيح في الصحاح والحسان، والأربعين حديثًا، وغير ذلك. اشتغل على القاضي حسين بن محمد المروروذي صاحب التعليقة قبل سنة 460. وبرع في هذه العلوم، وكان "},{"id":1870,"era":"c6","t":"الخليفة العباسي المسترشد بالله يحارب دبيس بن صدقة .","s":"كان دبيس بن صدقة صاحب الحلة المزيدية قد أطلق عفيفًا خادِمَ الخليفة المسترشد بالله، وكان مأسورًا عنده، وحمَّله رسالة فيها تهديد للخليفة بإرسال قسيم الدولة البرسقي صاحب الموصل إلى قتاله، وتقويته بالمال، وأن السلطان كَحَل أخاه، وبالغ في الوعيد، ولبس السواد، وجزَّ شعره، وحلف لينهبَنَّ بغداد، ويخرِّبها، فاغتاظ الخليفة لهذه الرسالة وغضب، وتقدم إلى البرسقي بالتبريز إلى حرب دبيس؛ فبرز في رمضان سنة 516، وت"},{"id":1871,"era":"c6","t":"ظفر السلطان محمود السلجوقي بالكرج .","s":"اشتدَّت نكاية الكرج (وهم الجورجيون، سكان جورجيا) في بلد الإسلام، وعظم الأمر على الناس، لا سيما أهل دربند شروان، فسار منهم جماعة كثيرة من أعيانهم إلى السلطان محمود بن محمد السلجوقي، وشكَوا إليه ما يَلقَون منهم، وأعلَموه بما هم عليه من الضعف والعجز عن حفظ بلادهم، فسار إليهم والكرج قد وصلوا إلى شماخي، فنزل السلطان في بستان هناك، وتقدَّم الكرج إليه، فخافهم العسكر خوفًا شديدًا، وأشار الوزير شمس الملك ع"},{"id":1872,"era":"c6","t":"انتصار المسلمين على الفرنج بإفريقية .","s":"كان الأميرُ علي بن يحيى صاحب إفريقية لما استوحش من رجار صاحب صقلية، جدَّد الأسطول الذي له، فكثَّر عَدده وعُدده، وكاتب أمير المسلمين علي بن يوسف بن تاشفين بمراكش بالاجتماع معه على قصد جزيرة صقلية، فلما علم رجار ذلك كفَّ عن بعض ما كان يفعله، فاتفق أن عليًّا مات سنة 515، وولي ابنه الحسن، فلما دخلت سنة 516 سيَّرَ أمير المسلمين أسطولًا، ففتح نقوطرة بساحل بلاد قلورية، فلم يشكَّ رجار أن عليًّا كان سبب ذل"},{"id":1873,"era":"c6","t":"طغتكين يستولي على حماة بعد وفاة صاحبها محمود بن قراجا .","s":"هو الأميرُ محمود بن قراجا، صاحِبُ حماة، كان ظالِمًا جائرًا. سار إلى حصن أفامية فهجم على الربض بغتةً، فأصابه سهم من القلعة في يده، فاشتدَّ ألمه، فعاد إلى حماة، وقلع الزُج -الحديدة في أسفل الرمح- من يده، ثم عملت عليه، فمات منه، واستراح أهلُ عمله من ظُلمِه وجَورِه، فلما سمع طغتكين، صاحب دمشق، الخبر سيَّرَ إلى حماة عسكرًا، فمَلَكها وصارت في جملة بلاده، ورتب فيها واليًا وعسكرًا لحمايتها."},{"id":1874,"era":"c6","t":"استيلاء الفرنج على خرتبرت من بلاد ديار بكر .","s":"استولى الفرنج على خرتبرت من بلاد ديار بكر، وسبب ذلك: أن بلك بن بهرام بن أرتق كان صاحب خرتبرت، فحضر قلعة كركر، وهي تقارب خرتبرت، فسمع الفرنج بالشام الخبرَ، فسار بغدوين ملك الفرنج في جموعه إليه ليرحلَه عنها؛ خوفًا أن يَقوى بملكها، فلما سمع بلك بقُربه منه رحل إليه، والتقيا في صفر واقتتلا؛ فانهزم الفرنج وأُسِرَ مَلِكُهم ومعه جماعة من أعيان فرسانهم، وسُجنوا بقلعة خرتبرت، وكان بالقلعة أيضًا جوسلين، صاحب"},{"id":1875,"era":"c6","t":"وفاة الحسن بن الصباح كبير دعاة الإسماعيلية .","s":"صاحبُ ألموت الكيا الحسن بن الصباح بن علي بن محمد الحميري الإسماعيلي. رأس الإسماعيلية، كان داهية وأصله من مرو، وُلِد بطوس وتتلمذ على أحمد بن عطاش من أعيان الباطنية، وكان كاتبًا لبعض الرؤساء، ثم صار إلى مصر وتلقى من دعاتهم، وعاد داعية لقومه، فكان الحسنُ مُقدَّمَ الباطنية في أصبهان دعا إلى إمامة المستنصر الفاطمي فطاف البلاد للدعوة الإسماعيلية، وقوي أمرُه حتى استولى على قلعة ألموت في قزوين، ثم ضمَّ إل"},{"id":1876,"era":"c6","t":"البرسقي صاحب الموصل يسيطر على حلب لحمايتها من الفرنج .","s":"لَمَّا ملك الفرنجُ مدينة صور طمعوا وقَوِيَت نفوسهم، وتيقَّنوا الاستيلاءَ على بلاد الشام، واستكثروا من الجموع، ثم وصل إليهم دبيس بن صدقة، صاحب الحلة، فأطمعهم طمعًا ثانيًا، لا سيما في حلب، وقال لهم: إن أهلها شيعة، وهم يميلون إليَّ لأجل المذهب، فمتى رأوني سلموا البلد إلي، وبذل لهم على مساعدته بذولًا كثيرة، وقال: إنني أكون هاهنا نائبًا عنكم ومطيعًا لكم، فساروا معه إليها وحصروها، وقاتلوا قتالًا شديدًا،"},{"id":1877,"era":"c6","t":"سقوط مدينة صور بيد الصليبيين .","s":"كانت مدينةُ صور تحت حكم الفاطميين العُبيديين بمصر، ولم تَزَل كذلك إلى سنة 506، وكان الفرنجُ قد حصروها، وضَيَّقوا عليها، ونهبوا بلدَها غير مرة، فتجهَّز ملكُ الفرنج، وجمع عساكِرَه ليسيرَ إلى صور، فخافهم أهلُ صور، فأرسلوا إلى أتابك طغتكين، صاحب دمشق، يطلُبون منه أن يُرسِلَ إليهم أميرًا من عنده يتولاهم ويحميهم، ويكونُ البلد له، وقالوا له: إن أرسلتَ إلينا واليًا وعسكرًا، وإلا سلَّمْنا البلد إلى الفرنج؛"},{"id":1878,"era":"c6","t":"الخليفة العباسي المسترشد يخمد فتنة دبيس بن صدقة .","s":"قصد دبيس والسلطانُ طغرل بغدادَ ليأخذاها من يد الخليفة، فلما اقتربا منها برز إليهما الخليفةُ في جحفلٍ عظيم، والناسُ مُشاةٌ بين يديه إلى أول منزلة، ثم ركب الناسُ بعد ذلك، فلما أمست الليلةُ التي يقتتلون في صبيحتها، ومِن عزمهم أن ينهبوا بغداد، أرسل الله مطرًا عظيمًا، ومرض السلطان طغرل في تلك الليلة، فتفَرَّقت تلك الجموع ورجعوا على أعقابهم خائبين خائفين، والتجأ دبيس وطغرل إلى الملك سنجر وسألاه الأمان م"},{"id":1879,"era":"c6","t":"فتح البرسقي كفر طاب وانهزامه من الفرنج .","s":"جمع قسيمُ الدولة البرسقي صاحب الموصل عساكِرَه وسار إلى الشام، وقصد كفر طاب وحصَرَها، فمَلَكها من الفرنج، وسار إلى قلعة عزاز، وهي من أعمال حلب من جهة الشمال، وصاحبها جوسلين الفرنجي، فحصرها، فاجتمعت الفرنج؛ فارِسُها وراجِلُها، وقصدوه ليُرحلوه عنها، فلقيهم وضرب معهم مصافًّا، واقتتلوا قتالًا شديدًا صبروا كلهم فيه، فانهزم المسلمون وقُتِل منهم وأُسِر كثير، وكان عدد القتلى أكثر من ألف قتيل من المسلمين، و"},{"id":1880,"era":"c6","t":"حرب الفرنج والمسلمين بالأندلس .","s":"عَظُم شأن ابن ردمير الفرنجي بالأندلس، واستطال على المسلمين، فخرج في عساكر كثيرة من الفرنج، وجاس في بلاد الإسلام، وخاضها، حتى وصل قرب قرطبة، وأكثر النهبَ والسبيَ والقتل، فاجتمع المسلِمونَ في جيش عظيم زائد الحد في الكثرة، وقصدوه، فلم يكن له بهم طاقة، فتحصَّن منهم في حصن منيع له اسمه أرنيسول، فحصروه، وكبسهم ليلًا، فانهزم المسلمون، وكثُرَ القتل فيهم، وعاد إلى بلاده."},{"id":1881,"era":"c6","t":"استفحال الباطنية بحلب والشام .","s":"في هذه السنة عَظُم أمر الإسماعيلية بالشام، وقَوِيت شوكتهم، وملكوا بانياس في ذي القعدة منها، وسببُ ذلك أن بهرام بن أخت الأسداباذي، داعيَ الباطنية بحلب والشام، لَمَّا قُتِل خالُه ببغداد هرب إلى الشام، وصار داعيَ الإسماعيلية فيه، وكان يتردد في البلاد، ويدعو أوباش الناس وطغامَهم إلى مذهبه، فاستجاب له منهم من لا عقلَ له، فكثُر جمعه، إلا أنه يُخفي شخصَه فلا يُعرَف، وأقام بحلب مدة، ونفر إلى إيلغازي صاحبه"},{"id":1882,"era":"c6","t":"قيام دولة بني آل زريع الإسماعيلية في عدن وزوالهم على يد الأيوبيين  .","s":"لما توفِّي أبو حمير سبأ بن أحمد بن المظفر بن علي الصليحي سنة 495، وهو آخر الملوك الصليحيين الباطنية، أرسل المأمون البطائحي الرافضي وزير الفاطميين بمصر علي بن إبراهيم بن نجيب الدولة، فوصل إلى جبال اليمن سنة 513، وقام بأمر الدعوة والمملكة التي كانت بيد سبأ، وبقيَ ابن نجيب الدولة حتى أرسل الآمر الفاطمي وقبض عليه بعد سنة 520، فانتقل الملك والدعوة باليمن إلى آل الزريع بن العباس بن المكرم. وآل الزريع هم"},{"id":1883,"era":"c6","t":"أبو نصر وزير السلطان سنجر يغزو الباطنية الإسماعيلية في خراسان .","s":"أمر الوزير المختص أبو نصر أحمد بن الفضل، وزير السلطان سنجر، بغزوِ الباطنية، وقَتْلهم أين كانوا، وحيثما ظُفِر بهم، ونَهْب أموالهم، وسَبْي حريمهم، وجهَّز جيشًا إلى طريثيت، وهي لهم، وجيشًا إلى بيهق من أعمال نيسابور، وكان في هذه الأعمال قرية مخصوصة بهم اسمها طرز، ومقَدَّمُهم بها إنسان اسمه الحسن بن سمين، وسيَّرَ إلى كل طرف من أعمالهم جمعًا من الجند، ووصَّاهم أن يقتلوا من لقوه منهم، فقصد كل طائفة إلى ا"},{"id":1884,"era":"c6","t":"دخول السلطان محمود بن محمد بن ملِكْشَاه بغداد بجيش كثيف .","s":"تراسل السلطان محمود والخليفة بشأن السلطان سنجر، وأن يكونا عليه، فلما علم بذلك سنجر كتب إلى ابن أخيه محمود ينهاه ويستميلُه إليه، ويحذِّره من الخليفة، وأنه لا تُؤمَنُ غائلتُه، وأنه متى فرغ مني دار إليك فأخَذَك، فأصغى إلى قول عمِّه ورجع عن عزمه، وأقبل ليدخل بغداد عامَه ذلك، فكتب إليه الخليفةُ ينهاه عن ذلك لقلةِ الأقوات بها، فلم يَقبَل منه، وأقبل إليه، فلما أزِفَ قدومُه خرج الخليفة من داره وتجهَّز إلى"},{"id":1885,"era":"c6","t":"السلاجقة يقتحمون بغداد وينهبون قصر الخلافة العباسي .","s":"لما وصل السلطان إلى بغداد في العشرين من ذي الحجة، ونزل بباب الشماسية، ودخل بعضُ عسكره إلى بغداد، ونزلوا في دُورِ الناس، شكا الناسُ ذلك إلى السلطان، فأمر بإخراجِهم، وبَقِيَ فيها مَن له دار، وبقي السلطانُ يراسل الخليفة بالعود، ويطلب الصلحَ، وهو يمتنِعُ، وكان يجري بين العسكرين مناوشة، والعامة من الجانب الغربي يسبون السلطانَ أفحش سَبٍّ. ثم إن جماعة من عسكر السلطان دخلوا دار الخلافة، ونهبوا التاج، وحُج"},{"id":1886,"era":"c6","t":"مصاف بين طغتكين أتابك دمشق والفرنج بالشام .","s":"اجتمعت الفرنجُ وملوكُها وقمامصتها وجنودها وساروا إلى نواحي دمشق فنزلوا بمرج الصفر عند قرية يقال لها سقحبا بالقرب من دمشق، فعظم الأمرُ على المسلمين واشتدَّ خوفُهم، وكاتَبَ طغتكين أتابك دمشق أمراءَ التركمان من ديار بكر وغيرها وجمعهم، وكان هو قد سار عن دمشق إلى جهة الفرنج، واستخلف بها ابنَه تاج الملوك بوري فكان بها، كلما جاءت طائفة أحسن ضيافتَهم وسَيَّرهم إلى أبيه، فلما اجتمعوا سار بهم طغتكين إلى الف"},{"id":1887,"era":"c6","t":"وفاة آقسنقر البرسقي صاحب الموصل .","s":"هو أبو سعيد آقسنقر البرسقي الغازي، الملقَّب قسيم الدولة سيف الدين، وكان مملوكًا تركيًّا صاحب الموصل والرحبة وتلك النواحي، ملَكَها بعد مودود بن التونتكين، وكان مودود بالموصل وببلاد الشام من جهة السلطان محمد بن ملكشاه السلجوقي، فقُتِل مودود سنة 507، وآقسنقر يومئذ شحنة بغداد، كان ولَّاه إياها السلطان محمد في سنة 498، فلما قتل مودود أرسل السلطان محمد البرسقي واليًا على الموصل وأمره بالاستعداد لقتال ال"},{"id":1888,"era":"c6","t":"وفاة عز الدين البرسقي السلجوقي .","s":"عزُّ الدين مسعود بن آقسنقر البرسقي السلجوقي توفي في هذه السنة, واتَّفق أن موته كان بالرحبة، وسببُ مسيره إليها أنه لما استقامت أمورُه في ولايته، وراسل عز الدين السلطان محمودًا، وطلب منه ولايةَ ما كان أبوه يتولاه من الموصل وغيرها، أجابه السلطان إلى ما طلب، فرتَّب الأمور وقررها، فكثُرَ جنده، وكان شجاعًا شهمًا، عالي الهمة محًّبا للجهاد, فطمع في التغلب على بلاد الشام، فجمع عساكره، وسار إلى الشام يريد ق"},{"id":1889,"era":"c6","t":"عماد الدين زنكي يصبح أتابك الموصل بعد وفاة صاحبها البرسقي .","s":"لما توفِّيَ عزُّ الدين مسعود بن آقسنقر البرسقي صاحِبُ الموصل، أشار الوزير أنوشروان على السلطان محمود أن يولِّيَ الأتابك عماد الدين زنكي الموصِلَ وما حولَها؛ لحاجة الناس إلى من يقوم بإزاء الفرنج, وخاصةً أن الفرنج قد استولوا على أكثر الشام، فاستحسن ذلك السلطان ومال إلى توليته؛ لما يعلمه من كفايته لما يليه، فأحضره وولَّاه البلاد كلها، وكتب منشورةً بها، وسار عماد الدين فبدأ بالبوازيج ليملكها ويتقوى به"},{"id":1890,"era":"c6","t":"قيام الدولة الزنكية في الشام ومصر  .","s":"بظهورِ عماد الدين زنكي بن أقسنقر بدأ عهد الدولة الزنكية في الموصل وحلب؛ فقد تولى عماد الدين زنكي أمرَ ولاية الموصِل وأعمالها سنة 521 بعد أن ظهرت كفاءتُه في حكم البصرة وواسط، وتولَّى شحنكية العراق، وفي محرم سنة 522 تمت له السيطرة على حلب, وأخذ عماد الدين يخوض المعارك تلو المعارك ويحقق الانتصارات على الصليبيين، وقد علَّق ابن الأثير بعد أن تحدَّث عن انتصار عماد الدين على الفرنج في معركة كبيرة، وملكه "},{"id":1891,"era":"c6","t":"الصلح بين الخليفة العباسي المسترشد بالله ومحمود بن ملكشاه .","s":"كان السلطانُ محمود بن محمد بن ملكشاه قد أرسل إلى عماد الدين بواسط يأمره أن يَحضُر هو بنفسِه ومعه المقاتِلة في السفن، وعلى الدوابِّ في البر، فجمع كلَّ سفينة في البصرة إلى بغداد، وشحَنَها بالرجال المقاتِلة، وأكثَرَ من السلاح، وأصعد، فلما قارب بغداد أمرَ كُلَّ من معه في السفن وفي البر بلُبس السلاح، وإظهار ما عندهم من الجَلدِ والنهضة، فسارت السفنُ في الماء، والعسكرُ في البر على شاطئ دجلة قد انتشروا وم"},{"id":1892,"era":"c6","t":"وفاة ابن السيد البطليوسي .","s":"هو أبو محمد عبد الله بن محمد بن السيد البطليوسي البلنسي النحوي، أحد أئمة اللغة والأدب في القرنين الخامس والسادس الهجريين. ولد ببطليوس سنة 444, ونشأ بها، ثم سكن مدينة بلنسية، وكان الناس يجتمعون إليه ويقرؤون عليه ويقتبسون منه، واشتهر بالتبحر في الأدب واللغة، وكان مقدَّمًا في معرفتهما وإتقانهما، وانتصب لإقراء علوم النحو، واجتمع إليه الناس، وله يدٌ في العلوم القديمة، وكان حسَنَ التعليم، جيِّدَ التفهيم"},{"id":1893,"era":"c6","t":"مقتل الوزير العبيدي الفاطمي المأمون البطائحي .","s":"هو وزيرُ الديار المصرية العبيدي، الملك أبو عبد الله المأمون بن البطائحي الرافضي، ويقال: إنَّ أباه كان من جواسيس الأفضل بالعراق، وإنه مات ولم يخلِّفْ شيئًا، فتزوَّجت أمه وتركته فقيرًا، ثم صار من أجناد المشارقة, وهو ممَّن خدم المستنصر، وإنه الذي لقبه بالمأمون. وترقى به الحال إلى المُلك، وهو الذي أعان الآمر بالله على الفتك بالوزير أمير الجيوش الأفضل السُّني، وولي منصبه، وكان المأمون شهمًا مِقدامًا، ج"},{"id":1894,"era":"c6","t":"وفاة أتابك طغتكين صاحب دمشق التركي .","s":"صاحب دمشق الملك أبو منصور أتابك طغتكين -أتابك يعني الأمير الوالد- وهو من مماليك السلطان تتش بن ألب أرسلان، زوَّجه بأم ولده دقاق، فلما قُتل السلطان تملَّك بعده ابنه دقاق، وصار طغتكين مقدَّم عسكره، ثم تملَّك بعد دقاق. كان عاقلًا خيِّرًا شهمًا شجاعًا، مَهيبًا مجاهدًا، مؤثِرًا للعدل، يلقَّب ظهير الدين, كثيرَ الغزوات والجهاد للفرنج، حسنَ السيرة في رعيته، ولَمَّا توفي مَلَك بعده ابنُه تاج الملوك بوري، و"},{"id":1895,"era":"c6","t":"استمرار عماد الدين زنكي في توحيد الجبهة الإسلامية في الشام .","s":"كان السلطان قد أمر بتولية عماد الدين زنكي الموصل وما حولها، فلما عبر زنكي الفرات إلى الشام، وأظهر أنه يريد جهاد الفرنج، وأرسل إلى تاج الملوك بوري بن طغتكين، صاحب دمشق، يستنجِدُه ويطلب منه المعونةَ على جهادهم، فأجابه إلى مراده، وأرسل من أخذ له العهودَ والمواثيق، فلما وصلت التوثقةُ جَرَّد عسكرًا من دمشق مع جماعة من الأمراء، وأرسل إلى ابنه سونج، وهو بمدينة حماة، يأمره بالنزول إلى العسكر والمسير معهم "},{"id":1896,"era":"c6","t":"تمرد دبيس بن صدقة صاحب الحلة .","s":"دخل السلطان محمود إلى بغداد، واجتهد في إرضاء الخليفة عن دبيس بن صدقة، وأن يسلِّمَ إليه بلاد الموصل، فامتنع الخليفةُ من ذلك وأبى أشدَّ الإباء، وقد تأخَّر دبيس عن الدخول إلى بغداد، ثم دخلها وركِبَ بين الناس فلعنوه وشتموه في وجهه، وقَدِم عماد الدين زنكي فبذل للسلطان في كل سنة مائة ألف دينار، وهدايا وتحفًا، والتزم للخليفة بمثلِها على ألَّا يولي دبيسًا شيئًا، وعلى أن يستمر زنكي على عمله بالموصل، فأقرَّ"},{"id":1897,"era":"c6","t":"استئصال الإسماعيلية بدمشق .","s":"قُتِلَ إبراهيم الأسداباذي الباطني ببغداد، وهرب ابن أخته بهرام داعية الباطنية إلى الشام، وملكَ قلعة بانياس، وسار إليها، والتحق بدمشق فدعمه المزدقاني وزير تاج الملوك صاحب دمشق، ولما فارق بهرام دمشق أقام له بها خليفةً يدعو الناس إلى مذهبه، فكثُروا وانتشروا، وملك هو عدةَ حصون من الجبال منها القدموس وغيره، وكان بوادي التيم، من أعمال بعلبك، أصحاب مذاهب مختلفة من النصيرية، والدرزية، والمجوس، وغيرهم، وأمي"},{"id":1898,"era":"c6","t":"محاصرة الفرنجة دمشق وانتصار أهلها عليهم .","s":"لما بلغ الفرنجَ قتلُ أبي علي طاهر بن سعيد المزدقاني وزير دمشق الذي كان قد راسلهم على تسليمِهم دمشق؛ عَظُم عليهم ذلك، وتأسَّفوا على دمشق؛ حيث لم يتمَّ لهم ملكها، وعمَّتهم المصيبة، فاجتمعوا كلُّهم: صاحب القدس، وصاحب أنطاكية، وصاحب طرابلس، وغيرُهم من الفرنج وقمامصتهم، ومن وصل إليهم في البحر للتجارة والزيارة، فاجتمعوا في خلق عظيم نحو ألفي فارس، وأما الراجل فلا يُحصى، وساروا إلى دمشق ليحصُروها، ولما سَ"},{"id":1899,"era":"c6","t":"فتح عماد الدين الزنكي حصن الأثارب وقلعة حارم وهزيمة الفرنج .","s":"لما فرغ عماد الدين زنكي من أمرِ البلاد الشامية، حلب وأعمالها، وما ملكه، وقرَّر قواعده؛ عاد إلى الموصل، وديار الجزيرة؛ ليستريح عسكره، ثم أمرهم بالتجهُّز للغَزاة، فتجهزوا وأعدُّوا واستعدوا، وعاد إلى الشام وقَصَد حلب، فقَوِيَ عَزمُه على قصد حصن الأثارب ومحاصرته؛ لشدة ضرره على المسلمين، وهذا الحصن بين حلب وبين أنطاكية، وكان مَن به من الفرنج يقاسمون حلب على جميع أعمالها الغربية، وكان أهل البلد معهم في "},{"id":1900,"era":"c6","t":"وفاة المهدي ابن تومرت مؤسس دولة الموحدين بالمغرب الأقصى .","s":"أبو عبد الله محمد بن عبدالله بن تومرت المصمودي، الهرغي، الخارج بالمغرب. لقَّبه أتباعه بالمهدي، وهو زعيم الموحِّدين ومؤسس دولتهم، قال الذهبي عنه: \"المدعي أنه علوي حَسَني، وأنه الإمام المعصوم المهدي، محمد بن عبد الله بن عبد الرحمن بن هود بن خالد بن تمام بن عدنان بن صفوان بن جابر بن يحيى بن رباح بن يسار بن العباس بن محمد بن الحسن بن الإمام علي بن أبي طالب. رحل من السوس الأقصى شابًّا إلى المشرق، فحجَّ"},{"id":1901,"era":"c6","t":"مصرع ملك إمارة أنطاكيا الصليبي في معركة عين زربة .","s":"طمع كل من بوهمند الثاني أمير أنطاكية وإيلغازي بن دانشمند في الاستيلاء على الإمارة الأرمنية في كليكيا بعد وفاة الأمير الأرمني طوروس الأول، ثم وفاة ابنه قسطنطين مسمومًا بعده، فنشب القتال بينهما في سهل عين زربة، وقُتِل فيه بوهمند الثاني، فورثت ابنته كونستانس وكانت قاصرة، فقام جدُّها بودوان الثاني بالوصاية عليها حتى تكبر، ولم يكن له هو ولد، فبعث إلى لويس السادس ملك فرنسا وطلب منه اختيار أمير معروف بال"},{"id":1902,"era":"c6","t":"حدوث زلزلة عظيمة بالعراق والجزيرة .","s":"وقعت زلزلة عظيمة في ربيع الأول بالعراق، وبلد الجبل، والموصل، والجزيرة؛ فخرَّبت كثيرًا."},{"id":1903,"era":"c6","t":"انتصار المرابطين على الموحدين أتباع ابن تومرت في موقعة البحيرة .","s":"في هذه السنة جهَّز ابن تومرت جيشًا عليهم الونشريسي وعبد المؤمن إلى مراكش، فحصروا أمير المسلمين بمراكش عشرين يومًا، ثم سار متولي سجلماسة بالعساكر للكشف عن مراكش، وطلع أهل مراكش وأمير المسلمين واقتتلوا، فقُتِل الونشريبسي، وصار عبد المؤمن مقدَّم العسكر، واشتدَّ بينهم القتال إلى الليل، واستحَرَّ القتل بالموحِّدين, فانهزم عبد المؤمن بالعسكر إلى الجبل، ولما بلغ المهدي بن تومرت خبر هزيمة عسكره، وكان مريض"},{"id":1904,"era":"c6","t":"اغتيال الحاكم العبيدي الفاطمي الآمر بأحكام الله .","s":"هو حاكم مصر الفاطمي: أبو علي منصور بن المستعلي أحمد بن المستنصر معد بن الظاهر بن الحاكم، العُبيدي المصري الرافضي الظلوم. كان متظاهرًا بالمكر واللهو والجبروت. وَلِيَ وهو صغير له خمسة أعوام, فلما كبر قتَلَ الأفضل أمير الجيوش، واصطفى أموالَه وكانت تفوت الإحصاءَ، ويُضرَب بها المثل، فاستوزر بعده المأمون محمد بن مختار البطائحي، فعسف الرعية وتمرد، فاستأصله الآمر بعد أربع سنين، ثم صلبه، وقتل معه خمسة من إ"},{"id":1905,"era":"c6","t":"تنصيب الحافظ لدين الله حاكمًا للعبيديين الفاطميين بمصر .","s":"لَمَّا قُتِل الآمر بحكم الله الفاطمي ولم يكن له ولد ذكَرٌ بعده، وقد كان عَهِد بالولاية لحملٍ كان ما يزال في بطنِ أمِّه منه، فوَلِيَ بعده ابن عمه الحافظ لدين الله أبو الميمون عبد المجيد ابن الأمير أبي القاسم بن المستنصر بالله، ولم يبايَع بالحكم، وإنما بُويعَ له لينظُرَ في أمر الحمل أيكون ذكرًا أم أنثى، ويكون هو نائبًا عنه، ولما وليَ استوزر أبا علي أحمد بن الأفضل بن بدر الجمالي، واستبدَّ الوزير بالأ"},{"id":1906,"era":"c6","t":"محاولة الباطنية لاغتيال أمير تاج الملوك بوري بن طغتكين .","s":"لما علم ابن صباح صاحب قلعة ألموت بما جرى على أشياعه الإسماعيلية بدمشق، تنمَّر وندب طائفة لقتل تاج الملوك بوري بن طغتكين، صاحب دمشق، فعيَّن اثنين في زي الجند، ثم قدما فاجتمعا بناس منهم أجناد، وتحيلا على أن صارا من السلحدانة وضمنوهما، ثم وثبا عليه في خامس جمادى الآخرة، فضربه أحدهما بالسيف قَصَد رأسه، فجرحه في رقبته جرحًا سليمًا، وضربه الآخر بسكين في خاصرته، فمرت بين الجلد واللحم, فتعلَّل من ذلك بجرح"},{"id":1907,"era":"c6","t":"تولية القضاة من عدة مذاهب في مصر .","s":"رتَّب الوزير أبو علي بن الأفضل وزير الحاكم الفاطمي الحافظ لدين الله، في الحُكم أربعة قضاة، فصار كل قاض يحكم بمذهبِه ويُوَرِّث بمذهبه، \"فكان قاضي الشافعية سلطان بن إبراهيم بن المسلم بن رشا، وقاضي المالكية أبو عبد الله محمد بن أبي محمد عبد المولى بن أبي عبد الله محمد بن عبد الله اللبني المغربي، وقاضي الإسماعيلية أبو الفضائل هبة الله بن عبد الله بن حسن بن محمد القاضي فخر الأمناء الأنصاري المعروف بابن"},{"id":1908,"era":"c6","t":"أسر دبيس بن صدقة وتسليمه إلى عماد الدين زنكي .","s":"أَسَر تاج الملوك بوري بن طغتكين، صاحب دمشق، الأميرَ دبيس بن صدقة، صاحب الحلة، وسلَّمه إلى أتابك زنكي بن آقسنقر، وسببُ ذلك أن دبيس لما فارق البصرة جاءه قاصد من الشام من صرخد يستدعيه إليها؛ لأن صاحبها كان خصيًّا، فتوفي هذه السنة، وخَلَّف جارية سُرِّية له، فاستولت على القلعة وما فيها، وعَلِمَت أنَّها لا يتم لها ذلك إلا بأن تتصل برجل له قوة ونجدة، فوُصِف لها دبيس بن صدقة وكثرة عشيرته، وذُكِرَ لها حاله"},{"id":1909,"era":"c6","t":"وفاة السلطان محمود السلجوقي وملك ابنه داود .","s":"هو صاحب العراق، مغيث الدين أبو القاسم السلطان محمود بن محمد بن ملكشاه بن ألب أرسلان السلجوقي. تملَّك بعد أبيه وهو حَدَثٌ أمردُ، في أول سنة 512، وخُطِب له على منابر بغداد، وكان ذكيًّا فَطِنًا له معرفة بالنحو، ومَيلٌ إلى العلم، ونظرٌ في التاريخ، وضَعُفَت دولة بني سلجوق في أواخر أيامه، وكان عمه السلطان سنجر أعلى رتبة منه. توفي السلطان محمود بهمذان، وكان قبل مرضه قد خاف وزيره أبو القاسم الأنساباذي من "},{"id":1910,"era":"c6","t":"مقتل أبي علي بن الأفضل وزير الحافظ لدين الله الفاطمي .","s":"هو الأفضل أبو علي بن الأفضل بن بدر الجمالي وزير الحافظ لدين الله العلوي، صاحب مصر. ولد بعسقلان. كان داهيةً، تغلَّب على المُلك وحَجَر على الحافظ وردَّ على المصادِرين أموالهم، فحَمِد له المصريون ذلك. وكتَبَ اسمه على السكة، ودعا على المنابر للقائم في آخر الزمان، واستمر إلى أن قتله أحد مماليك الحافظ، بظاهر القاهرة. وسبب قتله: أنه كان قد حجر على الحافظ، ومنعه أن يحكُمَ في شيء من الأمور؛ قليل أو جليل، و"},{"id":1911,"era":"c6","t":"وفاة تاج الملوك صاحب دمشق بوري بن طغتكين  .","s":"هو صاحب دمشق، تاج الملوك، بوري بن صاحب دمشق الأتابك طغتكين، مولى السلطان تتش السلجوقي. وُلِد سنة 478, ثم تملَّك بعد أبيه في صفر سنة 522. كان ذا حلم وكرم، وكثير الجهاد، شجاعًا، مِقدامًا، سدَّ مسد أبيه، وفاق عليه، وكان ممدَّحًا، أكثر الشعراء من مدحه، لا سيما ابن الخياط. قال الذهبي: \"قيل: كان عجبًا في الجهاد، لا يفتُرُ من غزو الفرنج، ولو كان له عسكر كثير لاستأصل الفرنج\" له أثر كبير في قتل وزيره المزد"},{"id":1912,"era":"c6","t":"الحرب بين السلطان مسعود وعمه السلطان سنجر .","s":"لما توفي السلطان محمود سار السلطان سنجر إلى بلاد الجبال، ومعه الملك طغرل بن السلطان محمد، وكان عنده قد لازمه، فوصل إلى الريِّ، ثم سار منها إلى همذان، فوصل الخبر إلى الخليفة المسترشد بالله والسلطان مسعود بوصوله إلى همذان، فاستقرَّت القاعدة بينهما على قتال سنجر، وأن يكون الخليفةُ معهم، وتجهَّز الخليفة، وقُطِعت خطبة سنجر من العراق جميعِه، ووصلت الأخبار بوصول عماد الدين زنكي ودبيس بن صدقة إلى قريب بغد"},{"id":1913,"era":"c6","t":"محاولة عماد الدين زنكي ودبيس بن صدقة الاستيلاء على بغداد .","s":"كان المسترشد بالله خرج من بغداد لنصرة السلطان مسعود في قتاله مع عمه سنجر, فلما بلغه أن عماد الدين ودبيس بن صدقة يسيران إلى بغداد، وبلغه انهزام السلطان مسعود، عزم على العود إلى بغداد، فأتاه الخبر بوصول عماد الدين زنكي إلى بغداد، ومعه دبيس بن صدقة، وكان السلطان سنجر قد كاتبهما وأمرهما بقصد العراق، والاستيلاء عليه، فلما علم الخليفة بذلك أسرع العود إليها، وعبر إلى الجانب الغربي، وسار فنزل بالعباسية، و"},{"id":1914,"era":"c6","t":"الحرب بين الملك طغرل وبين أخيه الملك داود بن محمود .","s":"كانت الحرب بين الملك طغرل وبين أخيه الملك داود بن محمود، وكان سببُها أن السلطان سنجر أجلس الملك طغرل في السلطنة، وعاد إلى خراسان لأنه بلغه أن صاحب ما وراء النهر أحمد خان قد عصى عليه، فبادر إلى العود لتلافي ذلك الخرق، فلما عاد إلى خراسان عصى الملك داود على عمِّه طغرل وخالفه، وجمع العساكر بأذربيجان وبلاد كنجة، وسار إلى همذان، فنزل مستهل رمضان عند قرية يقال لها وهان بقرب همذان، وخرج إليه طغرل، وانهزم"},{"id":1915,"era":"c6","t":"هزيمة صاحب طرابلس الفرنجي .","s":"عبر إلى الشام جمع كثير من التركمان من بلاد الجزيرة، وأغاروا على بلاد طرابلس وغنموا وقتلوا كثيرًا، فخرج القمص -كبير القساوسة- صاحب طرابلس في جموعه فانزاح التركمان من بين يديه، فتبعهم فعادوا إليه وقاتلوه فهزموه وأكثروا القتل في عسكره، ومضى هو ومن سلم معه إلى قلعة بعرين، فتحصنوا فيها وامتنعوا على التركمان، فحصرهم التركمان فيها. فلما طال الحصار عليهم نزل صاحب طرابلس ومعه عشرون فارسًا من أعيان أصحابه س"},{"id":1916,"era":"c6","t":"وفاة الإمام ابن الزاغوني شيخ الحنابلة ببغداد .","s":"هو الإمام العلامة شيخ الحنابلة ذو الفنون، أبو الحسن علي بن عبد الله بن نصر بن عبيد الله بن سهل، ابن الزاغوني، شيخ الحنابلة ببغداد، صاحب التصانيف. وُلِد سنة 455، كان من بحور العلم، كثير التصانيف، يرجع إلى دين وتقوى، وزهد وعبادة، فقيهًا متبحرًا في الأصول والفروع، واعظًا وشاعرًا، وله المصنفات الكثيرة، وله يد في الوعظ؛ قال ابن الجوزي: \"صحبتُه زمانًا، وسمعت منه، وعلَّقت عنه الفقه والوعظ\". ومات في سابع "},{"id":1917,"era":"c6","t":"استعادة شمس الملوك صاحب دمشق بانياس من الفرنج .","s":"استعاد شمس الملوك، صاحب دمشق، حصن بانياس من الفرنج؛ وذلك أن الفرنج استضعفوه وطمعوا فيه، وعزموا على نقض الهدنة التي بينهم؛ فتعرضوا إلى أموال جماعة من تجار دمشق بمدينة بيروت وأخذوها، فشكا التجار إلى شمس الملوك، فراسل في إعادة ما أخذوه، وكرَّر القول فيه، فلم يردوا شيئًا، فحملته الأنفة من هذه الحالة والغيظ على أن جمع عسكره وتأهب، ولا يعلم أحد أين يريد، ثم سار وسبق خبره أواخر المحرم، ونزل على بانياس أو"},{"id":1918,"era":"c6","t":"انتصار المسلمين بقيادة أسوار نائب حلب على الفرنج .","s":"سار ملك الفرنج، صاحب البيت المقدس، في خيَّالته ورجَّالته إلى أطراف أعمال حلب، فتوجه إليه الأمير أسوار، النائب بحلب، فيمن عنده من العسكر، وانضاف إليه كثير من التركمان، فاقتتلوا عند قنسرين، فقُتل من الطائفتين جماعة كثيرة، وانهزم المسلمون إلى حلب، وتردَّد ملك الفرنج في أعمال حلب، فعاد أسوار وخرج إليه فيمن معه من العسكر، فوقع على طائفة منهم، فأوقع بهم، وأكثر القتل فيهم والأسر، فعاد من سلم منهزمًا إلى "},{"id":1919,"era":"c6","t":"الخليفة العباسي المسترشد بالله يحاصر مدينة الموصل .","s":"حصر المسترشد بالله مدينة الموصل في العشرين من شهر رمضان، وسبب ذلك ما تقدم من قصد الشهيد زنكي بغداد، ثم قصد جماعة من الأمراء السلجوقية باب المسترشد بالله، وصاروا معه فقَوِي بهم، واشتغل السلاطين السلجوقية بالخُلف الواقع بينهم، فأرسل الخليفة الشيخ بهاء الدين أبا الفتوح الأسفراييني الواعظ إلى عماد الدين زنكي برسالة فيها خشونة، فقبض عليه عماد الدين زنكي وأهانه ولقيه بما يكره، فأرسل المسترشد بالله إلى ا"},{"id":1920,"era":"c6","t":"عماد الدين زنكي يضم قلاع الأكراد الحميدية إلى حكمه .","s":"استولى عماد الدين زنكي على جميع قلاع الأكراد الحميدية، منها قلاع العقر، وقلعة شوش، وغيرهما، وكان لما ملك الموصل أقرَّ صاحبها الأمير عيسى الحميدي على ولايتها وأعمالها، ولم يعترِضْه على شيء مما هو بيده، فلما حصر المسترشد بالله الموصل حضر عيسى هذا عنده، وجمع الأكراد عنده فأكثر، فلما رحل المسترشد بالله عن الموصل أمر زنكي أن تُحصَر قلاعهم، فحُصرت مدة طويلة وقُوتلت قتالًا شديدًا إلى أن مُلِكت هذه السنة،"},{"id":1921,"era":"c6","t":"قتال الدانشمند صاحب ملطية للفرنج .","s":"أوقع الدانشمند صاحب ملطية بالفرنج الذين بالشام، فقتل كثيرًا منهم وأسرَ كثيرًا."},{"id":1922,"era":"c6","t":"حصار الإسماعلية بقلعة كردكوه بخراسان .","s":"اجتمع جمع من العساكر السنجرية مع الأمير أرغش، وحصروا قلعة كردكوه بخراسان، وهي للإسماعيلية، وضيَّقوا على أهلها وطال حصرها، وعدمت عندهم الأقوات؛ فأصاب أهلها تشنج وكزاز، وعجز كثير منهم عن القيام فضلًا عن القتال، فلما ظهرت أمارات الفتح رحل الأمير أرغش، فقيل: إنهم حملوا إليه مالًا كثيرًا وأعلاقًا نفيسة، فرحل عنهم."},{"id":1923,"era":"c6","t":"الاقتتال بين ولدي حاكم مصر وبداية تدهور الدولة الفاطمية .","s":"عَهِدَ الحافظ إلى ولده سليمان، وكان أسَنَّ أولاده وأحبَّهم إليه، وأقامه ليسُدَّ مكان الوزير، فمات بعد ولاية العهد بشهرين، ثم جعل ابنه حيدرة أبا تراب وليَّ عهده ونصبه للنظر في المظالم، فشَقَّ ذلك على أخيه أبي علي حسن؛ لأنه كان يروم ذلك؛ لكثرة أمواله وأولاده وحواشيه وموكبه، بحيث كان له ديوان مفرد. وما زالت عقارب العداوة تدب بينهما حتى وقعت الفتنة بين الطائفية الجيوشية أصحاب حسن، وكان مائلًا لنصرة أه"},{"id":1924,"era":"c6","t":"شمس الملوك ينتزع شقيف تيرون من ابن جندل وينهب بلد الفرنج .","s":"سار شمس الملوك إسماعيل من دمشق إلى شقيف تيرون، وهو في الجبل المطلِّ على بيروت وصيدا، وكان بيد الضحاك بن جندل رئيس وادي التيم، قد تغلَّب عليه وامتنع به، فتحاماه المسلمون والفرنج، يحتمي على كل طائفة بالأخرى، فسار شمس الملوك إليه وأخذه منه في المحرم، وعَظُم أخذُه على الفرنج؛ لأن الضحاك كان لا يتعرض لشيء من بلادهم المجاورة له، فخافوا شمس الملوك، فشرعوا في جمع عساكرهم، فلما اجتمعت ساروا إلى بلد حوران، "},{"id":1925,"era":"c6","t":"استيلاء الفرنج على جزيرة جربة .","s":"كانت جزيرة جربة مقابل تونس من بلاد إفريقية قد استولت في كثرة عمارتها وخيراتها، غيرَ أن أهلَها طغَوا فلا يدخُلون تحت طاعة السلطان، ويُعرَفون بالفساد وقَطْع الطريق، فخرج إليها جمعٌ من الفرنج، من أهل صقلية، في أسطولٍ كثير وجَمٍّ غفير، فيه من مشهوري فرسان الفرنج جماعة، فنزلوا بساحتها وأداروا المراكب بجهاتها، واجتمع أهلها وقاتلوا قتالًا شديدًا، فوقع بين الفريقين حرب شديدة، فثبت أهل جربة، فقُتِل منهم بش"},{"id":1926,"era":"c6","t":"ملك الفرنج حصن روطة من بلاد الأندلس .","s":"اصطلح المستنصر بالله بن هود والسليطين الفرنجي صاحب طليطلة من بلاد الأندلس مدة عشر سنين. وكان السليطين قد أدمن غزو بلاد المستنصر وقتاله، حتى ضَعُف المستنصر عن مقاومته؛ لقلة جنوده، وكثرة الفرنج، فرأى أن يصالحَه مدة يستريح فيها هو وجنوده، ويعتدُّون للمعاودة، فترددت الرسلُ بينهم، فاستقَرَّ الصلح على أن يسلِّمَ المستنصر إلى السليطين حصنَ روطة من الأندلس، وهو من أمنع الحصون وأعظمها، فاستقرت القاعدة واصط"},{"id":1927,"era":"c6","t":"حصر ابن ردمير الفرنجي مدينة أفراغة بالأندلس وهزيمته ثم موته .","s":"حصر ابن ردمير الفرنجي مدينةَ أفراغة من شرق الأندلس، وكان الأمير يوسف بن تاشفين بن علي بن يوسف بمدينة قرطبة، فجهَّز الزبير بن عمرو اللمتوني والي قرطبة ومعه ألفا فارس، وسير معه ميرة كثيرة إلى أفراغة، وكان يحيى بن غانية، الأمير المشهور، أمير مرسية وبلنسية من شرق الأندلس، ووالي أمرها لأمير المسلمين علي بن يوسف، فتجهَّز في خمسمائة فارس، وكان عبد الله بن عياض صاحب مدينة لاردة، فتجهز في مائتي فارس، فاجتم"},{"id":1928,"era":"c6","t":"قتل شمس الملوك إسماعيل بن بوري وملك أخيه شهاب الدين محمود .","s":"هو صاحب دمشق شمس الملوك إسماعيل بن تاج الملوك بوري بن طغتكين التركي. تملَّك بعد أبيه في رجب سنة 526، وكان بطلًا شجاعًا شهمًا مِقدامًا كآبائه، فخافته الفرنج واستنقذ بانياس منهم في يومين، وكانت الإسماعيلية باعوها لهم من سبع سنين، وسعر بلادهم وأوطأهم ذلًّا، ففرح الناس بشهامته وفَرْط شجاعته، واحتملوا ظلمه. قُتِل في ربيع الآخر، وكان سبب قتله أنه ركب طريقًا شنيعًا من الظلم ومصادرات العمال وغيرهم من أعما"},{"id":1929,"era":"c6","t":"حصر أتابك عماد الدين زنكي دمشق .","s":"حصر أتابك عماد الدين زنكي دمشقَ، وكان نزوله عليها أول جمادى الأولى، وسببُه إرسال شمس الملوك صاحبها إليه واستدعاؤه ليسلمها إليه، فقُتل شمس الملوك قبل وصول زنكي، وسار إلى دمشق فنازلها، وأجفل أهلُ السواد إلى دمشق، واجتمعوا فيها على محاربته ونزل أولًا شماليَّها، ثم انتقل إلى ميدان الحصار، وزحف وقاتل، فرأى قوةً ظاهرة وشجاعة عظيمة واتفاقًا تامًّا على محاربته، فبينما هو يحاصِرُها وصل رسول الخليفة المسترش"},{"id":1930,"era":"c6","t":"مقتل الوزير حسن بن الحافظ العبيدي الفاطمي .","s":"هو الحسنُ بن الحافظ لدين الله عبد المجيد بن محمد بن المستنصر العبيدي المصري, استوزره أبوه وجعله وليَّ عهده سنة 526، فظلم وعسف وسفك الدماء، وقَتَل أعوان أبي علي الوزير الذي قبله، حتى قيل إنَّه قتل في ليلة أربعين أميرًا، فخافه أبوه، وجهَّز لحربه جماعة، فحاربهم واختلطت الأمور، ثم دس أبوه من سقاه السمَّ، فهلك هذه السنة, وكان الحسن يميل إلى أهل السُّنة, وقيل في سبب قتله: إنه لما حصل اقتتال بين ابني الح"},{"id":1931,"era":"c6","t":"السلطان مسعود السلجوقي يعتقل الخليفة العباسي المسترشد بالله .","s":"كان السلطان مسعود بن محمد بن ملكشاه وصل إلى بغداد هاربًا من أخيه طغرل فأكرمه الخليفة وخلع عليه وطوَّقه وسوَّره ونفذ معه جماعة من عسكره لدفع أخيه. فحين وصلوا إلى النهروان جاء الخبرُ من همذان بموت الملك طغرل، فجدَّ مسعود في السير إلى همذان ودخلها واستولى على المُلك، واستوزر شرف الدين نوشروان بن خالد، وخاف المسترشد أن يتمكَّن مسعود في المملكة فيقصد الحضرة ويستولي عليها,كان بعض الأمراء قد عزموا على قب"},{"id":1932,"era":"c6","t":"الباطنية يغتالون الخليفة العباسي المسترشد بالله وتولي ابنه الراشد .","s":"هو أمير المؤمنين أبو منصور الفضل بن المستظهر بالله أحمد ابن المقتدي بأمر الله عبد الله بن محمد بن القائم عبد الله بن القادر القرشي الهاشمي العباسي البغدادي. مولده في شعبان سنة 486 في أيام جده المقتدي، وخُطب له بولاية العهد وهو يرضع، وضُرِبت السكة باسمه, وكان له خطٌّ بديع، ونثر صنيع، ونظم جيد، مع دين ورأي، وشهامة وشجاعة، وكان خليقًا للخلافة، قليل النظير. قال ابن النجار: إن المسترشد كان يتنسك في أول"},{"id":1933,"era":"c6","t":"قتل دبيس بن صدقة صاحب الحلة .","s":"هو أبو الأغر -وقيل: الأعز- دبيس بن سيف الدولة أبي الحسن صدقة بن منصور بن دبيس بن علي بن مزيد الأسدي الناشري الشيعي، الملقب نور الدولة ملك العرب صاحب الحلة المزيدية -حلة بني مزيد، وهي مدينة كبيرة بين الكوفة وبغداد كانت تسمى الجامعين- كان دبيس جوادًا كريمًا عنده معرفة بالأدب والشعر، وتمكَّن في خلافة الإمام المسترشد، واستولى على كثير من بلاد العراق، وهو من بيت كبير. كان دبيس في خدمة السلطان مسعود بن "},{"id":1934,"era":"c6","t":"الحرب بين الخليفة الراشد وبين السلطان مسعود .","s":"وصل يرنقش الزكوي من عند السلطان مسعود يطالب الخليفة بما كان قد استقَرَّ على المسترشد من المال، وهو أربعمائة ألف دينار، فذكر أنه لا شيءَ عنده، وأنَّ المال جميعَه كان مع المسترشد بالله، فنُهب في الهزيمة المذكورة. ثم بلغ الراشد بالله أن يرنقش يريد الهجومَ على دار الخلافة وتفتيشها لأخذ المال، فجمع العساكِرَ لمنع داره، وأمَّر عليهم كج أبه، وأعاد عمارة السور. فلما علم يرنقش بذلك اتفق هو وبك أبه شحنة بغد"},{"id":1935,"era":"c6","t":"الفتنة بدمشق بين صاحبها شهاب الدين محمود والجند .","s":"وقَعَت الفِتنةُ بدمشقَ بين صاحِبِها شِهابِ الدِّينِ محمود بن تاج الملوك بوري والجند. وسبَبُ ذلك أنَّ الحاجِبَ يوسف بن فيروز كان أكبَرَ حاجِبٍ عند أبي شِهابِ الدين وجَدِّه، ثمَّ إنَّه خاف أخاه شمسَ الملوك، وهرب ابنُ فيروز منه إلى تدمُر، فلمَّا كانت هذه السَّنةُ سأل أن يَحضُرَ إلى دمشق، وكان يخاف جماعةَ المماليك؛ لأنَّه كان أساء إليهم وعامَلَهم أقبَحَ مُعاملةٍ، فلما طلبَ الآن الحضورَ إلى دمشق أُجيبَ"},{"id":1936,"era":"c6","t":"الحرب بين عسكر الخليفة الراشد وعسكر السُّلطان مسعود .","s":"اجتمَعَ كثيرٌ مِن الأُمَراءِ وأصحابِ الأطرافِ على الخُروجِ عن طاعةِ السُّلطانِ مَسعود، فسار المَلِكُ داود بن السُّلطان محمود في عسكَرِ أذربيجان إلى بغداد، فوصَلَها رابِعَ صَفَر، ونزل بدارِ السُّلطان، ووصل أتابك عماد الدين زنكي بَعدَه مِن المَوصِل، ووصل يرنقش بازدار صاحِبُ قزوين وغيرها، والبقش الكبيرُ صاحب أصفهان، وصَدقةُ بنُ دبيس صاحِبُ الحلة، ومعه عنترُ بنُ أبي العسكر الجاواني يدَبِّرُه، ويُتَمِّ"},{"id":1937,"era":"c6","t":"موافقة عجيبة في خلع سادس خليفة .","s":"حكى ابنُ الجَوزيِّ عن أبي بكرٍ الصوليِّ أنَّه قال: \"النَّاسُ يقولونَ: كُلُّ سادسٍ يقومُ بأمرِ النَّاسِ مِن أوَّلِ الإسلامِ لا بُدَّ أن يُخلَعَ، قال ابنُ الجوزيِّ: فتأمَّلتُ ذلك فرأيتُه عَجَبًا: قيامُ رَسولِ اللهِ صلَّى اللهُ عليه وسلَّم ثمَّ أبِي بكر ثمَّ عُمَرَ ثُمَّ عُثمانَ ثمَّ عليٍّ ثمَّ الحَسَن فتنازلَ بالخلافةِ لِمُعاوية! ثمَّ يزيدُ ومُعاويةُ بنُ يزيد ومروانُ وعبدُ المَلِك ثمَّ عبدُ الله بنُ"},{"id":1938,"era":"c6","t":"ملك شهاب الدين محمود صاحب دمشق مدينة حمص وقلعتها .","s":"كان أصحابُ حمص أولادُ الأمير خيرخان بن قراجا، والوالي بها مِن قبلِهم، قد ضَجِروا من كثرةِ تعَرُّضِ عَسكَرِ عماد الدين زنكي إليها وإلى أعمالِها، وتَضييقِهم على مَن بها مِن جُنديٍّ وعامِّيٍّ، فراسلوا شهابَ الدين محمود بن تاج الملوك بوري صاحب دمشقَ في أن يُسَلِّموها إليه، ويُعطيهم عِوضًا عنها تَدمُر، فأجابهم إلى ذلك، وسار إليها وتسَلَّمَها منهم، وسَلَّمَ إليهم تَدمُر، وأقطع حِمصَ مَملوكَ جَدِّه معين "},{"id":1939,"era":"c6","t":"غزاة العسكر الأتابكي لبلاد الفرنج .","s":"اجتَمَعت عَسكَرُ أتابك زنكي، صاحِبِ حَلَب وحَماة، مع الأميرِ أسوار نائِبِه بحَلَب، وقَصَدوا بلدَ الفِرنجِ على حين غفلةٍ منهم، وقَصَدوا أعمالَ اللاذقيَّة بَغتةً، ولم يتمَكَّنْ أهلُها مِن الانتقالِ عنها والاحترازِ، فنَهَبوا منها ما يزيدُ عن الوَصفِ، وقتلوا وأسَروا وفعلوا في بلدِ الفِرنجِ ما لم يَفعَلْه غَيرُهم، وكان الأسرى سبعةَ آلافِ أسيرٍ ما بين رجُلٍ وامرأةٍ وصَبيٍّ، ومِئة ألفِ رأسٍ مِن الدوابِّ "},{"id":1940,"era":"c6","t":"وصول السُّلطان مسعود إلى العراق وخلع الخليفة الراشد .","s":"حَصَل اجتماعُ الأمراءِ والملوكِ، ببغداد، على خلافِ السُّلطانِ مسعود، والخُطبةِ للمَلِك داود بن أخيه السُّلطان محمود، فجمع السُّلطانُ مسعود العساكِرَ وسار إلى بغداد، ولَمَّا وصل السُّلطانُ نزل على بغداد وحَصَرها وجميعَ العساكِرِ فيها، وثار العيَّارون ببغداد وسائِرِ محالِّها، وأفسدوا ونَهَبوا، وقَتَلوا، وحصرهم السُّلطانُ نَيِّفًا وخمسين يومًا فلم يَظفَرْ بهم، فعاد إلى النهروان عازمًا على العَودِ إلى"},{"id":1941,"era":"c6","t":"تولي المقتفي لأمر الله الخلافة بدل ابن أخيه الراشد .","s":"لَمَّا قُطِعَت خُطبةُ الراشِدِ بالله وخُلِعَ، استشار السُّلطانُ جَماعةً مِن أعيان بغدادَ، منهم الوزيرُ علي بن طراد، وصاحِبُ المخزن، وغيرهما، فيمن يَصلُحُ أن يليَ الخلافة. فقال الوزير: أحدُ عُمومةِ الراشِدِ، وهو رجلٌ صالحٌ. قال: من هو؟ قال: لا أقدِرُ أن أُفصِحَ باسمِه لِئَلَّا يُقتَلَ، فتقَدَّم إليهم بعَمَلِ مَحضَرٍ في خَلعِ الرَّاشِدِ، فعَمِلوا محضرًا ذَكَروا فيه ما ارتكَبَه من أخذِ الأموالِ وأشيا"},{"id":1942,"era":"c6","t":"عزل الوزير بهرام الأرمني وزير حاكم مصر الفاطمي .","s":"هرب تاجُ الدَّولةِ بهرام وزيرُ الحافظ لدينِ الله الفاطمي صاحِبِ مِصرَ، وكان قد استوزَرَه بعد قَتلِ ابنِه حَسَن، وكان نصرانيًّا أرمنيًّا، فتمَكَّنَ في البلاد واستعمَلَ الأرمن وعزل المُسلِمين، وأساء السيرةَ فيهم وأهانَهم هو والأرمنُ الذين ولَّاهم وطَمِعوا فيهم، فلم يكُنْ في أهلِ مِصرَ مَن أنِفَ ذلك إلَّا رضوان بنُ الريحيني؛ فإنَّه لَمَّا ساءه ذلك وأقلَقَه جَمَعَ جَمعًا كثيرًا وقَصَد القاهرة، فسمِعَ "},{"id":1943,"era":"c6","t":"فتح المسلمين حصن وادي ابن الأحمر من الفرنج .","s":"سار عسكَرُ دِمشقَ مع مُقَدَّمِهم الأميرِ بزاوش إلى طرابلس الشَّام، فاجتمع معه من الغُزاةِ المُتطَوِّعة والتركمان أيضًا خَلقٌ كثير، فلَمَّا سَمِعَ القُمص- كبيرُ القَساوِسة- صاحِبُها بقُربِهم مِن ولايتِه، سار إليهم في جُموعِه وحُشودِه، فقاتَلَهم وانهزم الفرنجُ وعادوا إلى طرابلسَ على صورةٍ سَيِّئةٍ، وقد قُتِلَ كثيرٌ مِن فُرسانِهم وشُجَعانِهم، فنهب المسلمونَ مِن أعمالهم الكثيرَ، وحَصَروا حِصنَ وادي اب"},{"id":1944,"era":"c6","t":"ملك أتابك زنكي قلعة بعرين وهزيمة الفرنج .","s":"سار أتابك عمادُ الدين زِنكي من المَوصِلِ إلى الشَّامِ وحصَرَ قلعةَ بعرين، وهي تُقارِبُ مدينةَ حَماةٍ، وهي مِن أمنَعِ معاقِلِ الفِرنجِ وأحصَنِها، فلمَّا نزل عليها قاتَلَها، وزحف إليها، فجمَعَ الفِرنجُ فارِسَهم وراجِلَهم، وساروا في قَضِّهم وقَضيضِهم، ومُلوكِهم وقَمامِصتِهم- كبارِ القَساوسة – وأمرائهم إلى أتابك زنكي؛ لِيُرحِّلوه عن بعرين، فلم يَرحَلْ وصبَرَ لهم إلى أن وصَلوا إليه، فلَقِيَهم وقاتَلَهم"},{"id":1945,"era":"c6","t":"قصد ملك الروم الشام وأخذه بلادًا كثيرة من الفرنج .","s":"أرسل الفِرنجُ إلى مَلِك القُسطنطينيَّة يَستَصرِخونَ به ويَعرِفونَه ما فعَلَه زنكي فيهم، ويَحثُّونَه على لحاقِ البِلادِ قبل أن تُملَك، ولا يَنفَعُه حينئذٍ المجيءُ، فتجَهَّزَ وسار مُجِدًّا فابتدأ ورَكِبَ البَحرَ وسار إلى مدينةِ أنطاكيا، وهي له على ساحِلِ البحر، فأرسى فيها، وأقام ينتَظِرُ وُصولَ المراكِبِ التي فيها أثقالُه وسِلاحُه، فلمَّا وَصَلت سار عنها إلى مدينةِ نيقية وحصَرَها، فصالحه أهلُها على "},{"id":1946,"era":"c6","t":"عماد الدين زنكي ينجد أهل حلب من عدوان ملك الروم .","s":"لَمَّا استنجَدَ أهلُ حَلَب بعماد الدين زنكي فارق حمصَ وسار إلى سِلميَّة فنازلها، وعبَرَ الفُراتَ إلى الرقَّة، وأقام جريدة- الجريدة خَيْلٌ لا رَجَّالةَ فيها- لَيتبَعَ الرُّومَ ويَقطَعَ عنهم الميرةَ، وأمَّا الرومُ فإنَّهم قَصَدوا قلعةَ شيزر؛ فإنَّها من أمنَعِ الحُصونِ، وإنَّما قَصَدوها لأنَّها لم تكُنْ لزنكي، فلا يكونُ له في حِفظِها الاهتمامُ العظيمُ، وإنَّما كانت للأميرِ أبي العساكِرِ سُلطانِ بنِ ع"},{"id":1947,"era":"c6","t":"انهيار دولة السلاجقة على أيدي الأتابك .","s":"الأتابِكةُ جَمعُ أتابك، وهي كَلِمةٌ مُرَكَّبةٌ مِن لفظينِ تُركيِّينِ «أتا» أي: الأبُ، أو المُرَبِّي، و«بِك» أي: الأمير، فيكون معنى الكلمة «مربي الأمير» ثم صارت مع الأيام تُستعمَلُ لدَلالاتٍ أخرى، بينها: المَلِك، والوزير الكبير، والأُمَراء البارزون الذين يَمُتُّون بصلةِ القَرابةِ إلى السلاجقةِ والأُمراء الأقوياء. كذلك أُطلِقَت في عهد المماليك على من تُعهَدُ إليه إمارةُ العَسكَرِ، ومنه شاع لَقَبُ «أ"},{"id":1948,"era":"c6","t":"عماد الدين زنكي يضم حمص وغيرها لحكمه .","s":"وصل زنكي حَماة وسار منها إلى بقاعِ بعلبك، فمَلَك حِصنَ المجدل، وكان لصاحِبِ دمشق، وراسله مُستحفِظُ بانياس وأطاعه، وسارَ إلى حمص وحصَرَها. ثمَّ رحَلَ عنها إلى سلميَّة؛ بسبَبِ نُزولِ الرومِ على حلَب، ثمَّ عاد إلى مُنازلةِ حمص فسُلِّمَت إليه المدينةُ والقَلعةُ."},{"id":1949,"era":"c6","t":"حدوث زلزلة عظيمة بالشام والجزيرة وديار بكر وغيرها  .","s":"وقَعَت زلزلةٌ عَظيمةٌ بالشَّامِ والجزيرةِ وديارِ بَكرٍ والمَوصِل والعراقِ وغيرها مِن البلادِ، فخَرَّبَت كثيرًا منها، وهَلَك تحت الهَدمِ عالمٌ كثيرٌ."},{"id":1950,"era":"c6","t":"الحرب بين السُّلطان مسعود والملك داود ومن معه من الأمراء .","s":"فارق الرَّاشِدُ باللهِ الخليفةَ المخلوعَ أتابك زنكي من الموصِل وسارَ نحو أذربيجان، فوصَلَ مراغةَ، وكان الأميرُ منكبرس صاحِبُ فارس، ونائبُه بخوزستان الأميرُ بوزابة، والأميرُ عبدُ الرَّحمنِ طغايرك صاحِبُ خلخال، والمَلِكُ داود بن السُّلطان محمود؛ مُستشعرينَ مِن السُّلطانِ مَسعود، خائفينَ منه، فتجَمَّعوا ووافَقوا الرَّاشِدَ على الاجتِماعِ معهم؛ لتَكونَ أيديهم واحدةً، ويَرُدُّوه إلى الخِلافةِ، فأجابهم "},{"id":1951,"era":"c6","t":"تصدي أهل حلب لعدوان ملك الروم على حلب وهزيمته  .","s":"لَمَّا انتهى مَلِكُ الرُّومِ مِن احتِلالِ بزاعةَ وغَدْره بأهلِها، ارتحل إلى حلَب ونَزَل على قويق (نهر بحلب) فزحف المَلِكُ بجَيشِه ومعه الفرنجُ الذين بساحل الشام، على حَلَب من الغد في خَيلِهم ورَجِلِهم، فخرج إليهم أحداثُ حَلَب، فقاتلوهم قتالًا شَديدًا، فقُتِلَ مِن الرُّومِ وجُرِحَ خَلقٌ كَثيرٌ، وقُتِلَ بِطْريقٌ جَليلُ القَدرِ عندهم، وعادوا خاسرينَ، وأقاموا ثلاثةَ أيَّامٍ فلم يَرَوا فيها طَمَعًا، فر"},{"id":1952,"era":"c6","t":"وصول ملك الروم إلى الشام .","s":"وصل مَلِكُ الرُّومِ إلى الشَّامِ وخافه النَّاسُ خَوفًا عظيمًا، وقصَدَ بزاعةَ فحَصَرها، وهي مدينةٌ قَريبةٌ مِن حَلَب، فمضى جماعةٌ مِن أعيانِ حَلَب إلى أتابك زنكي وهو يحاصِرُ حمص، فاستغاثوا به واستنصَروه، فسَيَّرَ معهم كثيرًا من العساكِرِ، فدخلوا إلى حَلَب ليَمنَعوها من الرُّومِ إن حَصَروها، ثمَّ إنَّ مَلِكَ الرومِ قاتل بزاعة، ونَصَب عليها منجنيقاتٍ، وضَيَّق على مَن بها فمَلَكَها بالأمانِ في الخامسِ"},{"id":1953,"era":"c6","t":"مقتل الخليفة العباسي الراشد بالله .","s":"هو أميرُ المُؤمِنينَ: أبو جعفر الرَّاشِدُ باللهِ مَنصورُ بنُ المسترشدِ باللهِ الفَضلِ بنِ أحمدَ العباسي، وُلِدَ سنة 502 في رمضان. وقيل: وُلِدَ بلا مَخرجٍ، ففُتِقَ له مخرجٌ بآلةٍ مِن ذهَبٍ، وأمُّه أم ولد. خُطِبَ له بولايةِ العَهدِ سنة 513، واستخلف في ذي القعدة، سنة 529, وكان أبيضَ مليحًا، تامَّ الشَّكلِ، شديدَ الأيدِ. وكان حَسَنَ السِّيرةِ، مُؤثِرًا للعَدلِ، فصيحًا، عَذْبَ العبارةِ، أديبًا شاعرًا ج"},{"id":1954,"era":"c6","t":"حال ابن بكران العيار بالعراق .","s":"عَظُمَ أمرُ ابنِ بَكرانَ العَيَّار بالعراقِ، وكَثُرَ أتباعُه، وصار يَركَبُ ظاهِرًا في جمعٍ من المُفسِدينَ، وخافه الشَّريفُ أبو الكرم الوالي ببغدادَ، فأمر أبا القاسِمِ ابنَ أخيه حاميَ بابِ الأزجِ أن يشتَدَّ عليه ليأمَنَ شَرَّه، وكان ابنُ بكران يُكثِرُ المُقامَ بالسَّوادِ، ومعه رفيقٌ له يُعرَفُ بابن البزاز، فانتهى أمرُهما إلى أنَّهما أرادا أن يضرِبَا باسمِهما سكَّةً في الأنبارِ، فأرسل الشحنةُ والوزي"},{"id":1955,"era":"c6","t":"انتصار الموحدين على المرابطين في المغرب .","s":"توجَّه عبدُ المؤمن لِمُلاقاةِ المرابطين، إلى جَبَل كرناطة، فنَزَل في أرضٍ صُلبة، بين شَجَر، ونزل تاشفين بنُ علي قُبالتَه، في الوطأةِ في أرضٍ لا نباتَ فيها، وكان الفَصلُ شاتيًا، فتوالت الأمطارُ أيامًا كثيرةً لا تُقلِعُ، فصارت الأرضُ التي فيها تاشفين وأصحابُه كثيرةَ الوحل، تسوخُ فيها قوائمُ الخيلِ إلى صُدورِها، ويَعجِزُ الرَّجُلُ عن المشيِ فيها، وتقَطَّعَت الطرقُ عنهم، فأوقدوا رماحَهم، وقرابيسَ سُرو"},{"id":1956,"era":"c6","t":"استيلاء قراسنقر صاحِبُ أذربيجان على بلاد فارس .","s":"جمَعَ أتابك قراسنقر صاحِبُ أذربيجان عساكِرَ كثيرةً وحَشَد، وسار طالبًا بثأرِ أبيه الذي قتَلَه بوزابة, فلمَّا قارب السُّلطانَ مَسعودًا أرسل إليه يطلُبُ منه قَتْلَ وزيرِه الكمال، فقَتَله، فلمَّا قُتِلَ سار قراسنقر إلى بلاد فارس، فلما قارَبَها تحصَّنَ بوزابة منه في القلعةِ البيضاء، ووطئ قراسنقر البلادَ، وتصَرَّفَ فيها، وليس له فيها دافِعٌ ولا مانِعٌ إلَّا أنَّه لم يُمكِنْه المُقامُ، ومَلَك المُدنَ ال"},{"id":1957,"era":"c6","t":"وقعة عظيمة بين السُّلطان سنجر وخوارزم شاه وانتصار سنجر عليه .","s":"سار السُّلطانُ سنجرُ بنُ ملكشاه إلى خوارِزمَ مُحاربًا لخوارزم شاه أتسز بن محمد. وسبَبُ ذلك أنَّ سنجر بلَغَه أنَّ أتسز يحَدِّثُ نَفسَه بالامتِناعِ عليه وتَرْكِ الخِدمةِ له، وأنَّ هذا الأمر قد ظهرَ على كثيرٍ مِن أصحابِه وأُمَرائِه، فأوجَبَ ذلك قَصْدَه وأخْذَ خوارزمَ منه، فجمَعَ سنجر عساكرَه وتوجَّه نَحوَه، فلمَّا قَرُبَ مِن خوارزم خرج خوارِزم شاه إليه في عساكِرِه، فلقيه مُقابِلًا وعَبَّأَ كلُّ واحدٍ"},{"id":1958,"era":"c6","t":"مقتل شهاب الدين محمود بن تاج الملوك صاحب دمشق .","s":"هو المَلِكُ شِهابُ الدِّينِ، أبو القاسِمِ محمودُ بنُ تاج الملوك بوري بن الأتابك طغتكين صاحِب دمشقَ. تمَلَّك بعد مَقتَلِ أخيه شمسِ الملوك، بإعانةِ أمِّه زمرد، وكان مُقَدَّمَ عَسكَرِه مُعينُ الدين أنر. قال ابنُ عساكر: \"كانت الأمورُ تجري في أيَّامه على استقامةٍ، إلى أن وثَبَ عليه جماعةٌ مِن خَدَمِه، فقتلوه في شوَّال، هذه السنة\"، قُتِلَ على فِراشِه غِيلةً، قتله ثلاثةٌ مِن غِلمانِه هم خواصُّه وأقربُ ال"},{"id":1959,"era":"c6","t":"أتابك زنكي يضم بعلبك لحكمه .","s":"سار عمادُ الدين أتابك زنكي بن آقسنقر إلى بعلبك، فحَصَرَها ثمَّ مَلَكَها؛ وسبَبُ ذلك أنَّ مَحمودًا صاحِبَ دِمشقَ لَمَّا قُتِلَ كانت والدتُه زمرد خاتون عند أتابك زنكي بحَلَب، قد تزوَّجَها، فوَجَدت لقَتلِ وَلَدِها وَجْدًا شديدًا، وحَزِنَت عليه، وأرسلت إلى زنكي وهو بديارِ الجزيرة تُعَرِّفُه الحادثةَ، وتَطلُبُ منه أن يَقصِدَ دمشقَ ويطلُبَ بثأر ولدها. فلمَّا وقف على هذه الرِّسالةِ بادر في الحالِ مِن غير"},{"id":1960,"era":"c6","t":"فتنة رضوان وزير الحافظ العبيدي الفاطمي صاحب مصر .","s":"وزَرَ رضوانُ بنُ ولخشي مكانَ بهرام النصراني، وتلقَّبَ بالأفضلِ، ولكِنَّه أساء السيرةَ، وصار بينه وبين الحافِظِ حاكِمِ مِصرَ العُبَيديِّ مُشاحناتٌ حتى حاول الوزيرُ خَلْعَه، فقام الحافِظُ بتدبير الأمرِ والعَمَلِ على إخراجِ الوزيرِ مِن مِصرَ بإثارةِ النَّاسِ عليه، فطلب رضوانُ الشَّامَ، فدخل عسقلانَ ومَلَكَها وجعلَها مَعقِلَه، ثم خرج رضوانُ مِن عسقلان ولحِقَ بصلخد، فنزل على أمينِ الدولة كمشتكين صاحِبِ"},{"id":1961,"era":"c6","t":"حصار أتابك زنكي دمشق .","s":"حصَرَ أتابك زنكي دمشقَ مَرَّتين؛ فأمَّا المرَّة الأولى فإنَّه سار إليها في ربيعٍ الأوَّل مِن بعلبَكَّ بعد الفراغِ مِن أمرِها، وتقريرِ قواعِدِها وإصلاحِ ما تَشَعَّثَ منها، ليَحصُرَها، فنزل في البقاعِ، وأرسل إلى جمالِ الدِّينِ صاحِبِها يبذُلُ له بلدًا يقتَرِحُه ليُسَلِّمَ إليه دمشق، فلم يجِبْه إلى ذلك، فرحل وقصَدَ دمشق، فنزل على داريا ثالثَ عَشَرَ ربيع الأول فالتفَّت الطلائِعُ واقتَتَلوا، وكان الظَّ"},{"id":1962,"era":"c6","t":"إعادة بردة النبي صلَّى اللهُ عليه وسلَّم إلى الخليفة المقتفي .","s":"وصولُ رَسولٍ مِن السُّلطانِ سنجر ومعه بُردةُ النبيِّ صلَّى اللهُ عليه وسلَّم، والقضيبُ، وكانا قد أُخِذَا مِن المُستَرشِد، فأعادهما إلى الخليفةِ المقتفي لأمرِ اللهِ"},{"id":1963,"era":"c6","t":"وفاة أتابك قراسنقر صاحب أذربيجان .","s":"هو الأتابك قراسنقر صاحِبُ أذربيجان وأرانية بمدينةِ أردبيل، مِن مماليكِ المَلِك طغرل بن السُّلطان مُحمَّد بن ملكشاه. كان شُجاعًا مَهيبًا، ظَلُومًا غَشومًا، عظيمَ المَحْلِ. وقد علا شأنُه على سُلطانِه السُّلطانِ مَسعود، فكان يخافُه ويداريه، وقتَلَ الوزيرَ كَمالَ الدين الرازي مِن أجلِه، وقد مات له ابنانِ تحت الزلزلة بجنزة، ومَرِضَ بالسُّلِّ، وطال به وماتَ بأردبيل."},{"id":1964,"era":"c6","t":"ابن الدانشمند صاحِبُ مَلطيَّةَ يقتل جمعًا من الروم في الشام .","s":"ظَفِرَ كمشتكين بن الدانشمند- صاحِبُ مَلطيَّةَ وغَيرِها من تلك النواحي- بجَمعٍ مِن الرُّومِ فقَتَلَهم وغَنِمَ ما معهم."},{"id":1965,"era":"c6","t":"بناء المدرسة الكمالية ببغداد .","s":"بنى كَمالُ الدين أبو الفُتوحِ بنُ طلحة- صاحِبُ المخزن- المدرسةَ الكماليَّةَ ببغداد، ولَمَّا فُرِغَت درس فيها الشَّيخُ أبو الحسن بن الخل، وحَضَره أربابُ المناصِبِ وسائِرُ الفُقَهاءِ."},{"id":1966,"era":"c6","t":"استيلاء الإسماعيلية على حصن مصياف بالشام .","s":"مَلَك الإسماعيليَّةُ حِصنَ مِصياف بالشَّامِ، وكان واليه مملوكًا لبني منقذ أصحاب شيزر، فاحتال عليه الإسماعيليَّةُ، ومكروا به حتى صَعِدوا إليه وقتَلَوه، ومَلَكوا الحِصنَ."},{"id":1967,"era":"c6","t":"نشوب حرب بين أتابك زنكي وبين داود سقمان بن أرتق .","s":"نَشَبت حَربٌ شَديدةٌ بين أتابك زنكي صاحِبِ المَوصِل, وبين داودَ سقمان بن أرتق، صاحِبِ حِصنِ كيفا (على الفرات)، وانهزم داود بن سقمان، ومَلَك زنكي من بلادِه قلعةَ بهمرد، وأدركه الشِّتاءُ فعاد إلى المَوصِل."},{"id":1968,"era":"c6","t":"هزيمة الفرنج على يد عسكر عسقلان .","s":"سارت طائفةٌ مِن الفِرنجِ بالشَّامِ إلى عسقلان لِيُغيروا على أعمالِها، وهي لصاحِبِ مِصرَ العُبَيديِّ، فخرج إليهم العَسكَرُ الذي بعَسقلانَ فقاتَلَهم، فظَفِرَ المُسلِمونَ وقتلوا من الفرنجِ كثيرًا، فعادوا مُنهَزِمينَ."},{"id":1969,"era":"c6","t":"وفاة أبي القاسم إسماعيل التيمي قوام السنة .","s":"هو الإمامُ العلَّامةُ الحافِظُ شَيخُ الإسلامِ: أبو القاسِمِ إسماعيلُ بنُ مُحمَّدِ بنِ الفَضلِ بنِ عليِّ بنِ أحمد بن طاهر القرشي، التيمي، ثم الطلحي، الأصبهاني، المُلَقَّب: بقَوَّام السنة، وُلِدَ سنة 457 ووالدته كانت من ذريَّةِ طَلحةَ بنِ عُبَيد الله التيمي- رضي الله عنه- أحَدِ العَشرةِ المُبشَّرينَ بالجنَّةِ. طَلَب العِلمَ وهو حدَثٌ. قال إسماعيل: \"سَمِعتُ مِن عائشةَ- بنتِ الحَسَن الوركانيَّة- وأنا "},{"id":1970,"era":"c6","t":"قتال سنجر للأتراك المجوس وهزيمته في موقعة قطوان .","s":"سار سِنجر إلى لقاء التُّرك، فعبَرَ إلى ما وراء النَّهرِ، فشكا إليه محمودُ بنُ محمد خان من الأتراك القارغلية، فقَصَدهم سنجر، فالتجؤوا إلى كوخان الصيني ومَن معه من الكُفَّار، وأقام سنجر بسمرقند، فكتب إليه كوخان كتابًا يتضَمَّنُ الشَّفاعةَ في الأتراكِ القارغلية، ويَطلُبُ منه أن يعفوَ عنهم، فلم يُشَفِّعْه فيهم، وكتَبَ إليه يدعوه إلى الإسلامِ ويتهَدَّدُه إن لم يُجِبْ عليه، ويتوعَّدُه بكَثرةِ عساكرِه، و"},{"id":1971,"era":"c6","t":"هلاك إبراهيم البهلوي مقدم الباطنية وحرق تابوته .","s":"هلاكُ إبراهيمَ البهلويِّ (وقيل: السهاوي) مُقَدَّمُ ورَئيسُ الباطنيَّةِ الإسماعيليَّةِ، فأحرق شحنة الري البهلوي في تابوتِه."},{"id":1972,"era":"c6","t":"أتابك زنكي بن آقسنقر يضم مدينة الحديثة لحكمه .","s":"مَلَك أتابك زنكي بن آقسنقر مدينةَ الحديثة من مدن الأنبار غرب العراق، ونَقَل مَن كان بها مِن آل مهراش إلى المَوصِل، ورتَّبَ أصحابَه فيها."},{"id":1973,"era":"c6","t":"جعلت الخطبة لزنكي بمدينة آمد .","s":"خُطِبَ لزنكي بمدينةِ آمد الواقعة جنوب شرق الأناضول بتركيا، وصار صاحِبُها في طاعتِه، وكان قبل ذلك مُوافِقًا للمَلِك داود على قِتالِ زنكي، فلمَّا رأى قوةَ زنكي صار معه."},{"id":1974,"era":"c6","t":"عزل بهروز عن شحنكية بغداد وإعادته إليها .","s":"عُزِلَ مجاهِدُ الدينِ بهروز عن شحنكية بغداد– شحنكية: أي: ضابطُ أمن البلَدِ-، ووَلِيَها قزل وهو مِن مماليك السُّلطان محمود، كانت له شحنكية برجرد والبصرة، فأضيف إليه شحنكية بغدادَ، ثمَّ وصَلَ السُّلطان مسعودٌ إلى بغداد، فرأى مِن تبَسُّطِ العيَّارينَ وفسادِهم ما ساءه، فأعاد بهروز إلى الشحنكية ببغداد, فتاب كثيرٌ منهم، ولم ينتَفِعِ النَّاسُ بذلك؛ لأنَّ وَلَدَ الوَزيرِ وأخا امرأةِ السُّلطان كانا يقاسِما"},{"id":1975,"era":"c6","t":"تولي عبدالرحمن طغايرك حجبة السُّلطان .","s":"تولَّى عبدُ الرحمن طغايرك حَجَبةَ السُّلطان، واستولى على المملكةِ وعَزَلَ الأميرَ تتر الطغرلي عنها، وآلَ أمرُه إلى أن يمشي في ركابِ عبدِ الرَّحمنِ."},{"id":1976,"era":"c6","t":"فساد بنو خفاجة في العراق  .","s":"وأفسدَ بنو خفاجةَ بالعراقِ، فسَيَّرَ السُّلطانُ مَسعودٌ سَرِيَّةً إليهم مِنَ العَسكَرِ، فنَهَبوا حلتهم، وقتلوا مَن ظَفِروا به منهم وعادوا سالِمينَ."},{"id":1977,"era":"c6","t":"غارة عسكر أتابك زنكي على بلاد الفرنج .","s":"أغار عسكَرُ أتابك زنكي مِن حَلَب على بلادِ الفِرنجِ في الشَّامِ، فنَهَبوا وأحرَقوا وظَفِروا بسَرِيَّةٍ من الفرنج، فقَتَلوا فيهم وأكثَروا، فكان عِدَّةُ القتلى سبعَمئة رجلٍ."},{"id":1978,"era":"c6","t":"توجه صاحب صقلية إلى إفريقيَّة .","s":"سَيَّرَ رِجالُ الفرنجي صاحِبِ صَقليَّةَ أُسطولًا إلى أطرافِ إفريقيَّةَ، فأخذوا مراكِبَ سُيِّرَت من مصر إلى الحَسَن صاحِبِ إفريقيَّة، وغُدِرَ بالحَسَن، ثُمَّ راسله الحسن، وجَدَّد الهُدنةَ لأجلِ حَملِ الغَلَّاتِ مِن صقليَّةَ إلى إفريقيَّة؛ لأنَّ الغلاء كان فيها شديدًا والموتُ كثيرًا"},{"id":1979,"era":"c6","t":"قيام الدولة الخوارزمية المستقلة .","s":"سار خوارزم شاه إلى خراسانَ بعد أن هزم سنجر، فقصد سرخس، فلمَّا وصَلَ إليها لَقِيَه الإمامُ أبو محمد الزيادي، وكان قد جمَعَ بين الزُّهدِ والعلم، فأكرَمَه خوارزم شاه إكرامًا عظيمًا، ورحل مِن هناك إلى مَرْو الشاهجان، فقصده الإمامُ أحمد الباخرزي، وشَفِعَ في أهلِ مَروٍ، وسأل ألَّا يتعَرَّضَ لهم أحَدٌ من العسكَرِ، فأجابه إلى ذلك، ونزل بظاهرِ البلد، واستدعى أبا الفَضلِ الكرمانيَّ الفقيهَ وأعيان أهلَها، فث"},{"id":1980,"era":"c6","t":"احتراق منارة الجامع العتيق بمصر .","s":"في ليلةِ الثُّلاثاءِ الثانيَ عَشَرَ مِن ربيعٍ الأول سَقَطَت صاعقةٌ أحرَقَت رُكنَ مَنارةِ الجامِعِ العتيقِ بمِصرَ القاهرةِ"},{"id":1981,"era":"c6","t":"وفاة الحافظ المازري المالكي .","s":"هو الشَّيخُ الإمامُ العلَّامةُ، البَحرُ المتفنِّنُ: أبو عبد الله محمَّدُ بنُ عليِّ بنِ عُمَرَ بن محمد التميمي المازري (نسبةً إلى مازرة بصقليَّةَ) المالكي، الحافِظُ المحَدِّث المشهور. وُلِدَ بالمهدية بإفريقيَّة. كان إمامًا حافِظًا مُتقِنًا أحدَ الأذكياءِ الموصوفين، والأئمَّة المتبحِّرينَ، عارفًا بعلوم الحديثِ، سَمِعَ وسافَرَ كثيرًا وكتب الكثير. قيل: \"إنَّه مَرِضَ مَرضةً، فلم يجِدْ مَن يعالجُه إلَّا"},{"id":1982,"era":"c6","t":"عماد الدين زنكي يمتلك عددا من قلاع الأكراد الهكارية .","s":"لَمَّا ضَمَّ الأتابك زنكي قلعةَ الحديثةِ التي على الفُراتِ، ونَقَل مَن كان بها مِن آل مهارِشَ إلى الموصِلِ، رتَّبَ فيها نوَّابَه، وأرسل زنكي جيشًا إلى قلعة أشب، وكانت أعظَمَ حُصونِ الأكرادِ الهكارية وأمنَعَها، وبها أموالُهم وأهلُهم، فحَصَروها وضَيَّقوا على مَن بها فمَلَكوها، فأمَرَ بإخرابِها وبناءِ القَلعةِ المعروفةِ بالعماديَّة عِوَضًا عنها، وكانت قلعةَ أشب حصنًا عظيمًا من حُصونِ الأكرادِ، فخَرَّ"},{"id":1983,"era":"c6","t":"اغتيال السُّلطان داود بن محمود السلجوقي .","s":"هو السُّلطانُ داودُ بنُ محمود بن محمَّدِ بنِ ملكشاه بن ألب أرسلان بن داود بن ميكائيل بن سلجوق بن دقماق السلجوقي، صاحِبُ أذربيجان وغيرِها، وهو الذي اختَلَفَ مع السُّلطان مسعود وجَرَت بينهما وقائِعُ وحُروبٌ حتى استولى داودُ على أذربيجان وما حولَها، وكان سبَبُ مَوتِه أنَّه رَكِبَ يومًا في سوقِ تبريز، فوَثَبَ عليه قومٌ مِن الباطنيَّةِ فقَتَلوه غِيلةً، وقتلوا معه جماعةً مِن خواصِّه، ودُفِنَ بتبريز، وكا"},{"id":1984,"era":"c6","t":"حصار الروم للفرنج بأنطاكية .","s":"خرجَ مِن الرومِ عَسكَرٌ كثير إلى الشَّامِ، فحصروا الفرنجَ بأنطاكيةَ، فخرج صاحِبُها واجتمع بمَلِك الرومِ وأصلَحَ حالَه معه، وعاد إلى مدينةِ أنطاكيةَ ومات في رمضانَ، ثمَّ إنَّ مَلِكَ الرُّومِ بعد أن صالحَ صاحِبَ أنطاكيةَ سار إلى طرابلس فحَصَرَها ثمَّ سار عنها."},{"id":1985,"era":"c6","t":"هلاك ملك الخطا كوخان طاغية الترك .","s":"هو طاغيةُ التُّركِ والخطا، كوخان من أبطالِ مُلوك الترك المجوسِ، و\"كو\"، بلسان الصين: لقَبٌ لأعظَمِ ملوكهم. أقبل كوخان في ثلاثمئة ألف فارس وكسر السُّلطانَ سنجر السلجوقي في موقعة قطوان، واستولى كوخان على بخارى وسمرقند سنة 536، فما أمهله الله، فهلك في رجَبٍ مِن هذه السَّنَةِ. كان كوخان جميلًا، حسَنَ الصورةِ، لا يلبَسُ إلَّا الحريرَ الصيني، له هَيبةٌ عظيمةٌ على أصحابِه، وكان سائِسًا، محِبًّا للعدلِ، دا"},{"id":1986,"era":"c6","t":"حصر الفرنج طرابلس الغرب .","s":"سارت مراكِبُ الفِرنجِ مِن صقليَّةَ إلى طرابلس الغَربِ فحَصَروها، وسبَبُ ذلك أنَّ أهلَها في أيَّامِ الأمير الحَسَن صاحِبِ إفريقيَّة، لم يَدخُلوا في طاعته، ولم يَزالُوا مخالِفينَ مُشاقِّينَ له، فقَدَّموا عليهم من بني مطروح مشايخَ يُدَبِّرونَ أمْرَهم، فلمَّا رآهم مَلِكُ صَقليَّةَ كذلك جهَّزَ إليهم جيشًا في البحر، فوصلوا إليهم تاسِعَ ذي الحجة، فنازلوا البلدَ وقاتلوه، وعَلَّقوا الكلاليبَ في سُورِه ونَق"},{"id":1987,"era":"c6","t":"تجهيز السُّلطان مسعود ليأخذ الشام والمَوصِل من زنكي ثم اصطلحا .","s":"وصَلَ السُّلطانُ مسعودٌ إلى بغداد على عادتِه في كلِّ سَنَةٍ، وجمَعَ العساكِرَ، وتجهَّزَ لِقَصدِ أتابك زنكي، وكان حَقَد عليه حِقدًا شديدًا؛ بسبَبِ أنَّ أصحابَ الأطراف الخارجينَ على السُّلطانِ مَسعودٍ، كانوا يَخرُجونَ عليه بتَحريضٍ من أتابك زنكي، ويقولُ إنَّه هو الذي سعى فيه وأشار به لعِلْمِه أنَّهم كُلَّهم كانوا يَصدُرونَ عن رأيِه، فلمَّا تفَرَّغَ السُّلطانُ هذه السَّنَةَ، جَمَعَ العساكِرَ لِيَسيرَ"},{"id":1988,"era":"c6","t":"ملك أتابك زنكي بعض ديار بكر .","s":"سار أتابك زنكي إلى ديارِ بَكرٍ ففَتَحَ منها عِدَّةَ حُصونٍ، فمِن ذلك: مدينةُ طنزة، ومدينةُ أسعرد، ومدينةُ حيزان، وحِصْنُ الروق، وحِصْنُ قطليس، وحِصنُ ناتاسا، وحِصنُ ذي القرنين، وغيرُ ذلك مِمَّا لم يبلُغْ شُهرةَ هذه الأماكِنِ، وأخَذَ أيضًا مِن بلَدِ ماردين ممَّا هو بِيَدِ الفِرنجِ حملين، والموزر، وتل موزن وغيرَها مِن حُصونِ جوسلين، ورتَّبَ أمورَ الجميعِ وجَعَلَ فيها مِن الأجنادِ مَن يَحفَظُها، وقَص"},{"id":1989,"era":"c6","t":"القضاء على العيارين ببغداد .","s":"زاد أمرُ العيَّارينَ (وهم طائفة من أهل الدعارة والنهب واللصوصية) وكَثُروا لأمْنِهم مِنَ الطَّلَبِ بسَبَبِ ابنِ الوزيرِ وابنِ قاروت أخي زوجةِ السُّلطان؛ لأنَّهما كان لهما نَصيبٌ في الذي يأخذُه العيَّارون، وكان النَّائِبُ في شحنكية بغدادَ يومَئذٍ مَملوكًا اسمُه إيلدكز، وكان صارِمًا مِقدامًا، ظالِمًا، فحَمَلَه الإقدامُ إلى أن حضَرَ عند السُّلطانِ، فقال له السُّلطانُ: إنَّ السِّياسةَ قاصِرةٌ، والنَّاس"},{"id":1990,"era":"c6","t":"وفاة الزمخشري صاحب تفسير الكشاف .","s":"هو العلَّامةُ كَبيرُ المُعتَزِلةِ: أبو القاسِمِ محمودُ بنُ عُمَرَ بنِ مُحمَّدِ بنِ عُمَرَ الزَّمخشريُّ الخوارزميُّ النَّحويُّ اللُّغَويُّ الحَنَفيُّ المتكَلِّمُ المُفَسِّر, وزمخشَرُ: قَريةٌ مِن قُرى خوارِزمَ، ومَولِدُه بها في رجَبٍ سنة 457، صاحِبُ الكَشَّاف في التفسير، والمُفصَّل في النَّحوِ، وله الفائِقُ في غريبِ الحديثِ، وأساسُ البلاغةِ في اللُّغةِ، وشَرحُ لاميَّةِ العَرَب للشَّنفَرَى، وشَرحُ أب"},{"id":1991,"era":"c6","t":"خروج أبي الحسين بن المستنصر .","s":"خرج أبو الحُسَينِ ابنُ المستنصر إلى الأميرِ خمارتاش الحافظي، صاحِبِ البابِ بمصرَ على الحافِظِ صاحبِ مِصرَ الفاطميِّ العُبَيديِّ، وقال له: اجعلني خليفةً وأنا أولِّيك الوَزارةَ، فطالع الأميرُ خمارتاش الحافِظَ صاحِبَ مِصرَ بذلك، فأمَرَ بالقَبضِ عليه، فقُبِضَ عليه واعتُقِلَ."},{"id":1992,"era":"c6","t":"مقتل نصير الدين جقر نائب المَوصِل .","s":"هو أبو سَعيدٍ جقر بنُ يعقوبَ الهَمَذانيُّ الملَقَّبُ نصير الدين، كان نائِبَ عمادِ الدين زنكي صاحِبِ الجزيرةِ الفُراتيَّة والمَوصِل والشَّام، استنابه عنه بالمَوصِل، وكان جَبَّارًا عَسُوفًا سَفَّاكًا للدَّماءِ مُستَحِلًّا للأموالِ، كان المَلِكُ فروخشاه بن السُّلطانِ مَحمود السلجوقي المعروف بالخفاجي يطمَعُ في السَّلطَنةِ بعد السُّلطانِ مَسعود, وكان فروخشاه بالموصِل هذه السَّنةَ ونَصيرُ الدين جقر يَنز"},{"id":1993,"era":"c6","t":"تحرير قلعة البيرة من الفرنج  .","s":"لَمَّا فَرَغ أتابك زنكي مِن أخْذِ الرَّهَا وإصلاحِ حالِها والاستيلاءِ على ما وراءَها مِن البِلادِ والوِلاياتِ، سار إلى قلعةِ البيرة وهي حِصنٌ حَصينٌ مُطِلٌّ على الفُرات وهو لجوسلين الثاني أيضًا، فحَصَرَه وضايقَه، فأتاه الخبَرُ بقَتلِ نائِبِه بالمَوصِلِ والبلادِ الشَّرقيَّة نصيِر الدِّينِ جقر بن يعقوب، فرحَلَ عنها خوفًا مِن أن يَحدُثَ بعده في البلادِ فَتقٌ يَحتاجُ إلى المَسيرِ إليها, فلمَّا رحَلَ ع"},{"id":1994,"era":"c6","t":"عماد الدين زنكي يحرر إمارة الرها من الصليبيين .","s":"في سادس جمادى الآخرة، فتح أتابك عمادُ الدين زنكي بن آقسنقر مدينةَ الرَّها من الفرنج، وفتَحَ غَيرَها مِن حُصونِهم بالجزيرةِ أيضًا، وكان ضَرَرُهم قد عَمَّ بلادَ الجزيرة وشَرَّهم قد استطار فيها، ووصَلَت غاراتُهم إلى أدانيها وأقاصيها، وبلَغَت آمِدَ ونصيبين ورأسَ عَين والرقَّة، وكانت مملكَتُهم بهذه الديارِ مِن قَريبِ ماردين إلى الفُرات مثل الرَّها، وسروج، والبيرة، وسن ابن عطير، وحملين، والموزر، والقراد"},{"id":1995,"era":"c6","t":"وفاة تاشفين بن علي آخر ملوك المرابطين بالمغرب الأقصى .","s":"هو أميرُ المُسلِمينَ تاشفينُ بنُ علي بن يوسف بن تاشفين صاحِبُ المَغرِب، وكانت وِلايتُه تزيد على أربعِ سِنينَ، تولَّى تاشفين غَزْوَ الأسبان أيامَ أبيه فافتتَحَ عِدَّةَ حُصونٍ، ولَمَّا توفِّيَ أبوه بويعَ له بالعَهدِ، وكان عبدُ المؤمن أميرُ الموحِّدينَ قد توغَّلَ بالمغرب فقاتَلَه تاشفين فكانت أيَّامُه حروبًا كُلُّها هزائِمُ وكان مَوتُه في إحدى المعارك، حيث كان فارًّا بفَرَسِه الذي كبا به فخَرَّ على و"},{"id":1996,"era":"c6","t":"عبد المؤمن قائد الموحدين يستولي على بلدان المرابطين في المغرب  .","s":"لَمَّا قُتِلَ تاشفين أرسَلَ عُمَرُ الهنتاتي- مُقَدَّمُ عَسكَرِ عبدِ المؤمِنِ- إليه بالخبَرِ، فجاء عبدُ المؤمِنِ مِن تاجِرة في يومِه بجميعِ عَسكَرِه، وتفَرَّقَ عَسكَرُ تاشفين، واحتمى بعضُهم بمدينةِ وهران، فلمَّا وصَلَ عبدُ المؤمِنِ دخَلَها بالسَّيفِ، وقَتَل فيها ما لا يُحصى، ثمَّ سار إلى تِلمِسان، وهما مدينَتانِ بينهما شَوطُ فَرَس، إحداهما تاهرت، وبها عسكَرُ المُسلِمينَ، والأخرى أقادير، وهي بناءٌ ق"},{"id":1997,"era":"c6","t":"وقوع فتنة بين أمير مكة هاشم العلوي الحسيني والأمير قطز .","s":"وقوعُ فِتنةٍ عَظيمةٍ بينَ الأميرِ هاشمِ بنِ فليتة بن القاسِمِ العَلويِّ الحُسَيني، أميرِ مكَّةَ، والأميرِ قُطُز الخادم أميرِ الحاجِّ، فنهَبَ أصحابُ هاشِمٍ الحُجَّاجَ وهم في المَسجِدِ يَطوفونَ ويُصَلُّونَ، ولم يَرقُبوا فيهم إلًّا ولا ذِمَّةً."},{"id":1998,"era":"c6","t":"اتفاق بوزابة وعباس على منازعة السُّلطان مسعود .","s":"سار بوزابة، صاحِبُ فارِسَ وخوزستان، وعساكِرُه إلى قاشان، ومعه المَلِكُ محمد بن السُّلطان محمود، ووصل إليهما المَلِكُ سُليمان بن السُّلطان محمَّد، واجتمع بوزابة والأميرُ عَبَّاس صاحِبُ الري، واتَّفَقا على الخروجِ عن طاعة السُّلطان مسعودٍ ومَلَكا كثيرًا مِن بلادِه، ووصل الخبَرُ إليه وهو ببغداد ومعه الأميرُ عبد الرحمن طغايرك، وهو أميرٌ حاجِبٌ، حاكِمٌ في الدولة، وكان ميلُه إليهما، فسار السُّلطانُ في ر"},{"id":1999,"era":"c6","t":"استيلاء علي بن دبيس على الحلة .","s":"لَمَّا أراد السُّلطانُ مسعود الرَّحيلَ مِن بغداد، أشار عليه الأميرُ المهلهل أن يَحبِسَ عليَّ بن دبيس بقلعةِ تكريت، فعَلِمَ ذلك، فهَرَب في جماعةٍ يَسيرةٍ نحو خمسة عشر، فمضى إلى الأزيز، وجمَعَ بني أسدٍ وغَيرَهم، وسار إلى الحلَّةِ وبها أخوه مُحمَّد بن دبيس، فقاتَلَه، فانهزَمَ مُحمَّد، ومَلَك عليٌّ الحلَّةَ، واستهان السُّلطانُ أمْرَه أوَّلًا، فاستفحل وضَمَّ إليه جَمعًا مِن غِلمانِه وغِلمانِ أبيه وأهلِ"},{"id":2000,"era":"c6","t":"وقوع عدد من مدن الأندلس بأيدي الفرنج .","s":"مَلَكَ الفِرنجُ مدينة شنترين، وباجة، وماردة، وأشبونة، وسائِرَ المعاقِلِ المجاوِرةِ لها من بلادِ الأندلُسِ، وكانت للمُسلِمينَ، فاختلفوا، فطَمِعَ العَدُوُّ فيهم، وأخَذَ هذه المُدُنَ وقَوِيَ بها قُوَّةً تمكَّنَ معها وتيَقَّنَ مِلْكَ سائِرِ البلادِ الإسلاميَّةِ بالأندلُس، فخَيَّبَ اللهُ ظَنَّه."},{"id":2001,"era":"c6","t":"سقوط جزيرة قرنة بأيدي الفرنج .","s":"سار أسطول الفِرنجِ مِن صقليَّةَ، فاحتَلُّوا جزيرةَ قرنةَ مِن إفريقيَّة، فقتَلُوا رجالَها، وسَبَوا حَريمَهم، فأرسل الحسَنُ صاحِبُ إفريقيَّةَ إلى رجار مَلِك صقليَّة يُذَكِّرُه العُهودَ التي بينهم، فاعتذَرَ بأنَّهم غيرُ مُطيعينَ له."},{"id":2002,"era":"c6","t":"استيلاء الموحدين على فاس ومكناسة .","s":"سار عبدُ المؤمِن إلى مدينةِ فاس فنَزَل على جَبَلٍ مُطِلٍّ عليها، وحصَرَها تسعةَ أشهُرٍ، وفيها يحيى بنُ الصَّحراويَّة وعَسكَرُه الذين فَرُّوا مِن تلمسان، فلمَّا طال مُقامُ عبد المؤمِنِ عَمَد إلى نهرٍ يدخُلُ البَلَدَ فسَكَّرَه بالأخشابِ والترابِ وغيرِ ذلك، فمَنَعَه من دُخولِ البَلَدِ، وصار بحيرةً تَسيرُ فيها السُّفُنُ، ثمَّ أزال الحاجِزَ، فجاء الماءُ دَفعةً واحدةً فخَرَّبَ سُورَ البلد وكُلَّ ما يُجا"},{"id":2003,"era":"c6","t":"دعوة البابا للقيام بحملة صليبية جديدة ثانية .","s":"بعد أن تمكَّنَ الأتابك عِمادُ الدين زنكي مِن انتزاعِ الرَّها مِن يَدِ الصَّليبيِّينَ قام مَلِكُ القُدسِ بتَوجيهِ رِسالةِ استغاثةٍ إلى البابا أوجين الثَّالث، فكان لها الأثَرُ القَويُّ في الأوساطِ البابويَّة، فقَرَّرَ البابا تأليفَ حَملةٍ صليبيَّةٍ ثانيةٍ، وكَلَّفَ القِدِّيس برنارد كليرفو بالدَّعوةِ لهذه الحملةِ، فقام بعَقدِ عِدَّةِ مُؤتمرات في مُدُنِ فَرنسا وألمانيا يدعو فيها لحَملةٍ صَليبيَّةٍ جَد"},{"id":2004,"era":"c6","t":"وفاة الإمام اللُّغويّ أبي منصور الجواليقي .","s":"هو أبو منصورٍ موهوبُ بنُ أحمدَ بنِ محمَّدِ بنِ الحَسَن بن الخضر الجواليقي البغداديُّ النحويُّ اللُّغويُّ. إمامُ الخليفةِ المقتفي, وكان إمامًا في فُنونِ الأدب. وُلِدَ في ذي الحجة سنة 465, ونشأ بباب المراتِبِ، قرأ على أبي زكريَّا سبع عشرة سنة, فانتهى إليه عِلمُ اللغة فأقرأها، ودرَّسَ العربيَّةَ في النظاميَّةِ بعد أبي زكريَّا مُدَّةً، فلما وَلِيَ المُقتفي اختَصَّ بإمامتِه في الصَّلاةِ, وكان المقتفي ي"},{"id":2005,"era":"c6","t":"استيلاء الموحدين على مراكش عاصمة المرابطين ونهاية دولتهم .","s":"لَمَّا فَرَغ عبدُ المؤمِنِ مِن فاس، سار إلى مراكشَ، وهي كرسيُّ مَملكةِ المُرابِطينَ، وهي مِن أكبَرِ المُدُنِ وأعظَمِها، وكان صاحِبُها حينئذ إسحاقَ بنَ عليِّ بنِ يوسف بن تاشفين، وهو صَبيٌّ، فنازلها، فضَرَب خيامَه في غَربيِّها على جَبَل صغيرٍ، وبنى عليه مدينةً له ولِعَسكَرِه، وبنى بها جامِعًا وبنى له بناءً عاليًا يُشرِفُ منه على المدينةِ، ويرى أحوالَ أهلِها وأحوالَ المُقاتِلينَ مِن أصحابِه، وقاتَلَه"},{"id":2006,"era":"c6","t":"استيلاء عبد المؤمن صاحب المغرب على الأندلس .","s":"سَيَّرَ عبدُ المؤمن جيشًا إلى جزيرة الأندلس، فمَلَكوا ما فيها مِن بلاد الإسلامِ. وسَبَبُ ذلك أنَّ عبدَ المؤمِنِ لَمَّا كان يحاصِرُ مراكش جاء إليه جماعة من أعيان الأندلُسِ، منهم أبو جعفر أحمد بن محمد بن حمدين، ومعهم مكتوبٌ يتضَمَّنُ بيعة أهلِ البلاد التي هم فيها لعبدِ المؤمِنِ ودُخولهم في زُمرةِ أصحابِه المُوحِّدينَ، وإقامتهم لأمره، فقَبِلَ عبدُ المؤمِنِ ذلك منهم، وشَكَرَهم عليه، وطَيَّبَ قُلوبَهم،"},{"id":2007,"era":"c6","t":"احتلال الفرنج طرابلس الغرب .","s":"احتَلَّ الفِرنجُ طرابلسَ الغَربِ، وسَبَبُ ذلك أنَّ رجار مَلِك صقليَّةَ جَهَّزَ أسطولًا كبيرًا وسَيَّرَه إلى طرابلُس الغَربِ، فأحاطوا بها برًّا وبحرًا، ثالِثَ المُحَرَّم، فخرج إليهم أهلُها وأنشَبوا القِتالَ، فدامَت الحَربُ بينهم ثلاثةَ أيَّامٍ، فلمَّا كان اليومُ الثَّالثُ سَمِعَ الفِرنجُ بالمدينةِ ضَجَّةً عَظيمةً، وخَلَت الأسوارُ مِن المُقاتِلة، وسَبَبُ ذلك أنَّ أهلَ طرابلُس كانوا قبل وصولِ الفرنجِ"},{"id":2008,"era":"c6","t":"اغتيال عماد الدين زنكي .","s":"هو المَلِكُ المنصورُ، أبو الجودِ الأتابك عِمادُ الدين زنكي بنُ الحاجِبِ قسيم الدولة آقسنقر بن عبد الله التركي، صاحِبُ المَوصِل. وُلِدَ سنة 477. قتل والِدُه, قسيمُ الدَّولةِ مملوكُ السُّلطانِ ألب أرسلان, وله يومئذٍ عَشرُ سنينَ، ولم يُخَلِّفْ والِدُه ولدًا غَيرَه، فالتَفَّ عليه غِلمانُ أبيه، ورَبَّاه كربوقا، وأحسَنَ إليه, فكان زنكي بطلًا شُجاعًا مِقدامًا كأبيه، عظيمَ الهَيبةِ مَليحَ الصُّورةِ، أسمرَ"},{"id":2009,"era":"c6","t":"تولي سيف الدين غازي إمارة المَوصِل .","s":"لَمَّا قُتِلَ عِمادُ الدين زنكي أخذَ نورُ الدين محمود ولَدُه خاتَمَه مِن يَدِه، وكان حاضِرًا معه، وسار إلى حَلَب فمَلَكَها، وكان حينئذٍ يتوَلَّى ديوانَ زنكي، ويحكُمُ في دولتِه مِن أصحابِ العمائِمِ جَمالُ الدين محمَّدُ بنُ علي وهو المنفَرِدُ بالحكم، ومعه أمير حاجِب صلاح الدين محمد الياغيسياني، فاتَّفَقا على حِفظِ الدولة، وكان مع الشَّهيدِ أتابك المَلِكُ ألب أرسلان بن السُّلطان محمود، فرَكِبَ ذلك ال"},{"id":2010,"era":"c6","t":"أخبار مسير الحملة الصليبية الثانية .","s":"تألَّفَت الحَملةُ الصَّليبيَّةُ الثانيةُ مِن ثلاثِ فِرَقٍ؛ الفِرقةُ الإنكليزيَّةُ التي اتَّجَهت من إنكلترا التي رَسَت سُفُنُها على سواحِلِ البرتغال بسَبَبِ العواصِفِ، فساهَموا في مساعدةِ أمير البرتغال ألفونسو الأوَّل في قتال المُسلِمينَ في لشبونةَ والاستيلاءِ عليها، ولم يُواصِلِ السَّيرَ إلى الأراضي المُقَدَّسة منهم إلَّا القليلُ، والفِرقَتانِ الألمانيَّة والفرنسيَّة ساراتا بَرًّا، فعَبَروا القُسط"},{"id":2011,"era":"c6","t":"مقتل بوزابة صاحب فارس وخوزستان .","s":"لَمَّا عَلِمَ الأميرُ بوزابة بقَتلِ عَبَّاس صاحِبِ الرَّيِّ، جمَعَ عساكِرَه مِن فارس وخوزستان وسارَ إلى أصفهان فحَصَرَها، وسَيَّرَ عَسكرًا آخَرَ إلى همذان، وعَسكَرًا ثالثًا إلى قَلعةِ الماهكي من بلَدِ اللحفِ، فأمَّا عَسكَرُه الذي بالماهكي فإنَّه سار إليهم الأميرُ البقش كون خر فدَفعَهم عن أعمالِه وكانت أقطاعه، ثمَّ إنَّ بوزابة سار عن أصفهانَ يَطلُبُ السُّلطانَ مَسعودًا، فراسَلَه السُّلطانُ في الصُّ"},{"id":2012,"era":"c6","t":"الموحدون يخيرون أهل الذمة بين الإسلام أو اللحاق بدار الحرب .","s":"لَمَّا استولى عبدُ المؤمن بنُ علي قائدُ المُوحِّدينَ على مراكش، أحضَرَ اليهودَ والنَّصارى، وقال: إنَّ الإمامَ المَهديَّ أمَرَني ألَّا أُقِرَّ النَّاسَ إلَّا على مِلَّةٍ واحدةٍ وهي الإسلامُ، وأنتم تَزعُمونَ أنَّ بعد الخَمسِمئة عام يظهَرُ مَن يُعضِّدُ شريعتَكم، وقد انقَضَت المُدَّةُ، وأنا مُخَيِّرُكم بين ثلاثٍ: إمَّا أن تُسلِموا، وإمَّا أن تَلحَقوا بدارِ الحَربِ، وإمَّا أن أضرِبَ رِقابَكم، فأسلم منه"},{"id":2013,"era":"c6","t":"سقوط بعض المدن الأندلسية في يد الأسبان .","s":"في جمادى الأولى حَصَرَ الفِرنجُ مَدينةَ المرية مِن الأندلس، وضَيَّقوا عليها بَرًّا وبَحرًا، فملكوها عَنوةً، وأكثَروا القَتلَ بها والنَّهبَ، وملكوا أيضًا مدينةَ بياسة وولايةَ جيان."},{"id":2014,"era":"c6","t":"ظفر عبد المؤمن قائد الموحدين بالملثمين في دكالة .","s":"سار بَعضُ المُرابِطينَ مِن المُلَثَّمينَ إلى دكالة، فاجتمَعَ إليه قبائِلِها، وصاروا يُغيرُونَ على أعمالِ مَراكشَ، وعبدُ المؤمِنِ لا يلتَفِتُ إليهم، فلمَّا كَثُرَ ذلك منهم سار إليهم سنةَ أربعٍ وأربعين وخمسمئة، فلمَّا سَمِعَت دكالة بذلك انحشَروا كُلُّهم إلى ساحِلِ البَحرِ في مئتي ألف راجلٍ وعشرين ألفَ فارسٍ، وكانوا مَوصوفين بالشَّجاعةِ، وكان مع عبدِ المؤمِنِ من الجيوشِ ما يخرج عن الحَصرِ، وكان الموض"},{"id":2015,"era":"c6","t":"فشل حصر الفرنج لدمشق في الحملة الصليبية الثانية .","s":"سار مَلِكُ الألمانِ مِن بلادِه في خَلقٍ كَثيرٍ وجَمْعٍ عَظيمٍ مِن الفرنج، عازمًا على قَصدِ بلادِ الإسلامِ، وهو لا يَشُكُّ في مِلكِها بأيسَرِ قِتالٍ؛ لكَثرةِ جُموعِه، وتوفُّرِ أموالِه وعُدَدِه، فلمَّا وَصَل إلى الشَّامِ قَصَده مَن به من الفرنجِ وخَدَموه، وامتَثَلوا أمْرَه ونَهْيَه، فأمَرَهم بالمسيرِ معهم إلى دمشقَ لِيَحصُرَها، فساروا معه ونازلوها وحَصَروها، وكان صاحِبُها مجير الدين أبق بن نوري بن ط"},{"id":2016,"era":"c6","t":"محاولة فرنج صقلية فتح قلعة إقليبية .","s":"لَمَّا استَقَرَّت أحوالُ الفرنجِ في المهديَّة وصفاقِسَ سار قائِدُهم جرجي في أسطولٍ إلى قلعةِ إقليبيَّةَ، وهي قلعةٌ حَصينةٌ، فلَمَّا وصَلَ إليها سَمِعَت به العرب، فاجتَمَعوا إليها، ونزل إليهم الفِرنجُ، فاقتتلوا فانهزم الفِرنجُ وقُتِلَ منهم خلقٌ كثيرٌ، فرجعوا خاسرين إلى المهديَّة، وصار للفِرنجِ مِن طرابلس الغَرب إلى قريبِ تُونُسَ ومِن المغرب إلى دونَ القَيروان."},{"id":2017,"era":"c6","t":"الخلاف بين السُّلطان مسعود وجماعة من الأمراء .","s":"فارق السُّلطانُ مَسعودًا جماعةٌ مِن أكابِرِ الأمراءِ، وهم من أذربيجان: إيلدكر المسعودي، صاحِبُ كنجة وأرانية، وقيصر، ومن الجبل: البقش كون خر، وتتر الحاجب، وهو من مماليك مسعود أيضًا، وطرنطاي المحمودي، شحنة واسط، والدكز، وقرقوب وابن طغايرك، وكان سَبَبُ ذلك مَيلَ السُّلطانِ إلى خاص بك واطِّراحَه لهم، فخافوا أن يَفعَلَ بهم مِثلَ فِعلِه بعبدِ الرَّحمنِ وعَبَّاس وبوزابة، ففارقوه وساروا نحو العراق، ووصل إ"},{"id":2018,"era":"c6","t":"انهزام الفرنج في أرض يغرى .","s":"هزَمَ نورُ الدِّينِ محمود بن زنكي الفرنجَ بمكانٍ اسمُه يغرى مِن أرضِ الشَّامِ، وكانوا قد تجَمَّعوا ليقصِدوا أعمالَ حَلَب ليُغيروا عليها، فعَلِمَ بهم، فسار إليهم في عَسكَرِه، فالتَقَوا بيغرى واقتتلوا قتالًا شديدًا وأجْلَت المعركةُ عن انهزام الفرنج، وقُتِلَ كَثيرٌ منهم، وأُسِرَ جَماعةٌ مِن مُقَدَّميهم، ولم ينجُ من ذلك الجمعِ إلَّا القَليلُ، وأرسل من الغنيمةِ والأسارى إلى أخيه سيفِ الدين وإلى الخليفة"},{"id":2019,"era":"c6","t":"سقوط مدينة طرطوشة بيد الفرنج بالأندلس .","s":"مَلَك الفِرنجُ بالأندلُسِ مَدينةَ طَرطوشة، ومَلَكوا معها جميعَ قِلاعِها وحُصونَ لاردة وأفراغة، ولم يبقَ للمُسلِمينَ في تلك الجِهاتِ شَيءٌ إلَّا واستولى الفِرنجُ عليه جميعِه؛ لاختلافِ المُسلِمينَ بينهم."},{"id":2020,"era":"c6","t":"النورمانديون يحتلون مدينة المهدية بأفريقيا ونهاية دولة بني زيري .","s":"اشتَدَّ الغلاءُ بإفريقيَّةَ مِن سنة 537 إلى سنة اثنتين وأربعين حتى أكَلَ النَّاسُ بعضُهم بعضًا، وخَلَت القرى، ولحِقَ كثيرٌ مِن النَّاسِ بجزيرة صقلية، فاغتنمَ رجار مُتمَلِّكُها الفُرصةَ وبعث جرج، مُقَدَّم أسطولِه، فنزل على المهديَّة ثامِنَ صفر سنة 542، وبها الحَسَنُ بن علي بن يحيى بن تميم بن المعز بن باديس، ففَرَّ بأخَفِّ حِملِه وتَبِعَه الناس، فدخل جرج المهديَّةَ بغيرِ مانعٍ، واستولى على قَصرِ الأ"},{"id":2021,"era":"c6","t":"النورمان يستولون على سوسة وصفاقس .","s":"لَمَّا استقَرَّ جرجي صاحب صقليَّة بالمَهديَّة، سَيَّرَ أسطولًا بعد أسبوع إلى مدينة صفاقس، وسَيَّرَ أسطولًا آخَرَ إلى مدينة سوسة، فأمَّا سوسة فإنَّ أهلَها لَمَّا سَمِعوا خبَرَ المهديَّة، وكان واليها عليَّ بنَ الحَسَن الأمير، فخرج إلى أبيه، وخرج النَّاسُ لخروجه، فدخلها الفِرنجُ بلا قتالٍ ثانيَ عَشَرَ صَفر، وأمَّا صفاقس فإنَّ أهلَها أتاهم كثيرٌ مِن العَرَبِ، فامتنعوا بهم، فقاتَلَهم الفرنج، فخرج إليهم"},{"id":2022,"era":"c6","t":"إفشال محاولة الانقلاب على الحافظ العبيدي الفاطمي .","s":"توجَّه عَسكَرُ الحافِظِ الفاطميِّ صاحِبِ مِصرَ، في ثالِثَ صَفَر، لقتالِ لواتة وقد تجَمَّعوا وعَقَدوا الأمرَ لرَجُلٍ قَدِمَ مِن المغرب وادَّعى أنَّه وَلَدُ نزار بن المستنصِر الفاطمي، فسار إليهم العَسكَرُ وواقَعَهم على الحمَّامات وانهزم منهم العَسكرُ، فجَهَّزَ الحافِظُ عَسكَرًا آخَرَ، ودَسَّ إلى مُقَدَّمي لواتة مالًا جزيلًا، ووعدهم بالإقطاعاتِ، فغدروا بابن نزار وقَتَلوه، وبَعَثوا برأسِه إلى الحافِظِ"},{"id":2023,"era":"c6","t":"وفاة الفقيه المالكي ابن العربي الأندلسي .","s":"هو الإمامُ العلَّامةُ الحافِظُ القاضي: أبو بكر مُحمَّدُ بنُ عبد اللهِ بنِ مُحمَّد المعافري ابنُ العربيِّ الإشبيليُّ الأندلسيُّ المالكيُّ، صاحِبُ التَّصانيفِ, الحافِظُ المشهورُ مِن عُلَماءِ الأندلس، وُلِدَ ونشأ وتعلَّمَ بإشبيليَّة, كانت ولادتُه سنة 468, ثمَّ لَمَّا استولى المرابطونَ عليها رحل مع أبيه إلى المَشرِق, ثمَّ رجع إلى الأندلُسِ بعد أن دَفَنَ أباه في رِحلتِه إلى المشرق, ثم عاد مِن قُرطبةَ إ"},{"id":2024,"era":"c6","t":"استيلاء نور الدين محمود زنكي على سنجار .","s":"لَمَّا مَلَك قُطبُ الدين مودود المَوصِلَ بعد أخيه سيف الدين غازي، كان أخوه الأكبَرُ نورُ الدين محمود بالشَّامِ، وله حَلَب وحَماة، فكاتبه جماعةٌ مِن الأمراء وطَلَبوه، وفيمن كاتَبَه المُقَدَّم عبدُ الملك والد شمس الدين محمد، وكان حينئذٍ مُستَحفظًا بسنجار، فأرسَلَ إليه يستدعيه ليتسَلَّمَ سنجار، فسار نور الدين جريدة- الجريدة خَيْلٌ لا رَجَّالةَ فيها- في سبعينَ فارِسًا مِن أُمَراءِ دَولتِه، فوصَلَ إلى "},{"id":2025,"era":"c6","t":"انتصارات نور الدين محمود زنكي على الصليبيين .","s":"غزا نورُ الدين محمودُ بن زنكي بلادَ الفِرنجِ مِن ناحيةِ أنطاكيةَ، وقَصَد حِصنَ حارم، وهو للفِرنجِ، فحَصَره وخَرَّب رَبضَه، ونهَبَ سَوادَه، ثمَّ رحل إلى حِصنِ أنب فحَصَرَه أيضًا، فاجتمع الفرنجُ مع البرنس صاحبِ أنطاكية وحارم وتلك الأعمال، وساروا إلى نورِ الدين لِيُرحِلوه عن إنب، فلَقِيَهم واقتتلوا قتالًا عظيمًا، وباشَرَ نور الدين القِتالَ ذلك اليوم، فانهزم الفرنجُ أقبَحَ هَزيمةٍ، وقُتِلَ منهم جمعٌ ك"},{"id":2026,"era":"c6","t":"وفاة القاضي عياض الأندلسي .","s":"هو الإمامُ العَلَّامة الحافِظُ الأوحَدُ، شَيخُ الإسلامِ القاضي أبو الفَضلِ عِياضُ بنُ موسى بنِ عِياضِ بنِ عَمرِو بنِ موسى بن عياض بن محمد بن موسى بن عِياض اليحصبي الأندلسي، ثمَّ السبتي، المالكيُّ، قاضي سبتة. أحدُ مشايخ العُلَماءِ المالكيَّة، أصلُه من الأندلُسِ انتَقَلَ جَدُّه عَمرٌو مِن الأندلُسِ إلى مدينة فاس، ثمَّ مِن فاس إلى سبتة, ووُلِدَ القاضي عياض بسبتة في النِّصفِ مِن شعبان سنة 476, لم يَحم"},{"id":2027,"era":"c6","t":"وفاة سيف الدين بن أتابك زنكي وملك أخيه قطب الدين بعده .","s":"هو المَلِكُ سَيفُ الدين غازي بن أتابك زنكي صاحِبُ المَوصِل تَمَلَّكَ المَوصِلَ بعدَ أبيه، واعتَقَلَ ألب أرسلان السلجوقي, وكان عاقِلًا حازِمًا شُجاعًا جَوادًا، محبًّا أهلَ الخَيرِ، لم تَطُلْ مُدَّتُه، وعاش أربعين سنة. وكان أحسَنَ الملوك شكلًا، وله مَدرسةٌ كبيرة بالمَوصِل، وهي من أحسَنِ المدارس، وقَفَها على الفُقَهاءِ الحَنَفيَّة والشَّافعيَّة، توفِّيَ في المَوصِل بمَرَضٍ حادٍّ، ولَمَّا اشتَدَّ مَرَ"},{"id":2028,"era":"c6","t":"وفاة الحاكم الفاطمي الحافظ لدين الله وتولي ابنه الظافر بأمر الله .","s":"هو الحافِظُ لدينِ الله عبدُ المجيد بنُ الأمير أبي القاسم بن المستنصر بالله الفاطمي العُبَيدي حاكِمُ مصر، كان في جميعِ مُدَّةِ حُكمِه محكومًا عليه، يَحكُمُ عليه وزراؤُه، حتى إنَّه جَعَلَ ابنَه حسنًا وزيرًا ووَلِيَّ عَهدِه فحَكَمَ عليه واستبَدَّ بالأمرِ دونَ أبيه وقَتَلَ كثيرًا مِن أُمَراءِ دَولةِ أبيه وصادَرَ كثيرًا، فلما رأى الحافِظُ ذلك سقى الحسَنَ سُمًّا فمات. توفِّيَ الحافِظُ بعد أن أصابه مَرَض"},{"id":2029,"era":"c6","t":"فتح نور الدين محمود زنكي حصن فاميا وأعزاز .","s":"فتَحَ نور الدين محمود بنُ الشهيد زنكي حِصنَ فاميا من الفرنجِ، وهو مُجاوِرٌ شيزر وحماة على تَلٍّ عالٍ، مِن أحصَنِ القِلاعِ وأمنَعِها، فسار إليه نورُ الدين وحَصَرَه وبه الفِرنجُ، وقاتَلَهم وضَيَّقَ على مَن به منهم، فاجتمع فِرنجُ الشَّامِ وساروا نحوَه لِيُرحِلُوه عنه فلم يَصِلوا إلَّا وقد مَلَكَه وملأَه ذخائِرَ وسِلاحًا ورِجالًا وجميعَ ما يُحتاجُ إليه، فلَمَّا بلغه مَسيرُ الفرنج إليه، رحَلَ عنه وقد ف"},{"id":2030,"era":"c6","t":"أبو جعفر بن أبي أحمد الأندلسي أول وزراء الموحدين في الأندلس .","s":"استوزَرَ عبدُ المُؤمِنِ صاحبُ بلادِ المغرب أبا جَعفر بنَ أبي أحمد الأندلسي، وكان مأسورًا عنده، فوُصِفَ له بالعَقلِ وجَودةِ الكتابة، فأخرَجَه من الحَبسِ واستوزَرَه، وهو أوَّلُ وزيرٍ كان للمُوَحِّدينَ."},{"id":2031,"era":"c6","t":"حصر الفرنج قرطبة ورحيلهم عنها .","s":"سار السليطين- وهو الأذفونش مَلِكُ طليطلة وأعمالِها، وهو مِن مُلوك الجلالقة، نوعٌ من الفرنج- في أربعينَ ألفَ فارسٍ إلى مدينةِ قُرطُبةَ، فحَصَرَها، وهي في ضَعفٍ وغَلاءٍ، فبَلَغَ الخبَرُ إلى عبدِ المؤمن وهو في مراكش، فجَهَّزَ عَسكرًا كثيرًا، وجعَلَ مُقَدَّمَهم أبا زكرياء يحيى بن يرموز، ونفَذَهم إلى قُرطُبةَ، فلَمَّا قَرُبوا منها لم يَقدِروا أن يلقَوا عسكَرَ السليطين في الوطاءِ، وأرادوا الاجتماعَ بأهل"},{"id":2032,"era":"c6","t":"اعتداء العرب على أهل الحج بين مكة والمدينة .","s":"في الرابعَ عَشَرَ مِن مُحَرَّم خَرَجَ العَرَبُ، زعب ومَن انضَمَّ إليها، على الحُجَّاج بالغرابي، بين مَكَّة والمدينة، فأخذوهم ولم يَسلَمْ منهم إلَّا القليلُ، وكان سَبَبُ ذلك أنَّه سار على الحاجِّ قايماز الأرجواني، وكان حَدَثًا غِرًّا، سار بهم إلى مكَّةَ، فلمَّا رأى أميرُ مكَّةَ قايماز استصَغَرَه وطَمِعَ في الحاجِّ، وتلَطَّفَ قايماز الحالَ معه إلى أن عادوا، فلمَّا سار عن مكَّةَ سَمِعَ باجتماعِ العَر"},{"id":2033,"era":"c6","t":"نور الدين زنكي يعتقل جوسلين الفرنجي ويفتح عددا من القلاع .","s":"جمعَ نُورُ الدِّينِ مَحمود بن زنكي عَسكَرَه وسار إلى بلادِ جوسلين الفرنجي، وهي شَماليَّ حَلَب منها تل باشر، وعين تاب، وإعزاز وغيرها، وعَزَمَ على مُحاصَرتِها وأخْذِها، وكان جوسلين فارِسَ الفِرنجِ غَيرَ مُدافَعٍ، قد جمع الشَّجاعةِ والرَّأيَ، فلَمَّا عَلِمَ بذلك جَمَعَ الفِرنجَ فأكثَرَ، وسار نحوَ نور الدين فالتَقَوا واقتتلوا، فانهزم المُسلِمونَ وقُتِلَ منهم وأُسِرَ جمعٌ كثيرٌ، وكان في جُملةِ مَن أُسِ"},{"id":2034,"era":"c6","t":"حصار الموحدين غرناطة والمرية من بلاد الأندلس .","s":"سَيَّرَ عبدُ المؤمن قائِدُ الموحِّدينَ جَيشًا كثيفًا، نحو عشرينَ ألفَ فارسٍ، إلى الأندلُسِ مع أبي حَفصٍ عُمَرَ بن أبي يحيى الهنياتي، وسَيَّرَ معهم نساءَهم، فكُنَّ يَسِرْنَ مُفرَداتٍ عليهن البَرانِسُ السُّودُ، ليس معهنَّ غَيرُ الخَدَمِ، ومتى قَرُبَ منهن رجلٌ ضُرِبَ بالسياط، فلما قَطَعوا الخليجَ ساروا إلى غرناطةَ وبها جمعُ المرابطين، فحَصَرَها عُمَرُ وعَسكَرُه، وضَيَّقوا عليها، فجاء إليه أحمَدُ بنُ "},{"id":2035,"era":"c6","t":"قتال الإسماعيلية في طريثيث .","s":"سار الأميرُ قجق في طائفةٍ مِن عَسكَرِ السُّلطان سنجر إلى طريثيث بخُراسان، وأغار على بلادِ الإسماعيليَّةِ فنَهَب وسَبى، وخَرَّب وأحرَقَ المساكِنَ، وفعل بهم أفاعيلَ عَظيمةً، وعاد سالِمًا، وكان في السَّنةِ الماضيةِ أمَرَ علاءُ الدين محمود بن مسعود- الغالبُ على أمر طريثيث التي بِيَدِ الإسماعيليَّةِ- بإقامةِ الخُطبةِ للخَليفةِ، ولُبْسِ السَّوادِ، ففَعَلَ الخَطيبُ ذلك، فثار به عَمُّه وأقاربُه ومَن وافَق"},{"id":2036,"era":"c6","t":"غزو جيش المصريين الفرنج بالشام والانتصار عليهم .","s":"جهَّزَ أبو منصورٍ عليُّ بنُ إسحاق، المعروفُ بالعادِلِ ابن السلار، وهو وزيرُ الظَّافِرِ الفاطميِّ، المَراكِبَ الحَربيَّةَ بالرِّجالِ والعُدَد، وسَيَّرَها إلى يافا، فأسَرَت عِدَّةً مِن مراكِبِ الفِرنجِ، وأحرقوا ما عَجَزوا عن أخْذِه، وقَتَلوا خلقًا كثيرًا مِن الفِرنجِ بها، ثمَّ تَوجَّهوا إلى ثَغرِ عكَّا، فأنكَوا فيهم، وساروا منه إلى صيدا وبيروت وطرابلس، فأبلوا بلاءً حسنًا، وظَفِروا بجماعةٍ مِن حُجَّا"},{"id":2037,"era":"c6","t":"ظفر عبد المؤمن قائد الموحدين بصنهاجة .","s":"لَمَّا مَلَكَ عَبدُ المؤمِنِ بجايةَ تَجَمَّعَت صنهاجةُ في أُمَمٍ لا يُحصِيها إلَّا الله تعالى، وتقَدَّمَ عليهم رجلٌ اسمُه أبو قصبة، واجتمع معهم مِن كتامة ولواتة وغيرِهما خلقٌ كَثيرٌ، وقَصَدوا حَرْبَ عبد المؤمن، فأرسل إليهم جيشًا كبيرًا، ومُقَدَّمُهم أبو سعيد يخلف، فالتَقَوا في عرض الجَبَلِ شرقي بجاية، فانهزم أبو قصبة وقُتِلَ أكثَرُ مَن معه، ونُهِبَت أموالُهم، وسُبِيَت نساؤهم وذراريُّهم، ولَمَّا فَ"},{"id":2038,"era":"c6","t":"نهاية دولة بني حماد بالمغرب  .","s":"سارَ عبدُ المُؤمِنِ بنُ علي إلى بجاية ومَلَكَها، ومَلَك جميعَ مَمالِكِ بني حَمَّاد. وكان لَمَّا أراد قَصْدَها سار من مراكِشَ إلى سبتة سنة 546، فأقام مُدَّةً يَعمُر الأسطولَ، ويَجمَعُ العساكِرَ القَريبةَ منه، فكتَبَ لِمَن في طريقِه إلى بجاية ليتجَهَّزوا ويكونوا على الحَرَكةِ أيَّ وَقتٍ طَلَبَهم، والنَّاسُ يَظُنونَ أنَّه يريدُ العبور إلى الأندلُسِ، فأرسل في قَطعِ السَّابلةِ عَن بلادِ شَرقِ المَغرِبِ"},{"id":2039,"era":"c6","t":"الحرب بين نور الدين محمود زنكي وبين الفرنج .","s":"تَجَمَّعَت الفِرنجُ، وحَشَدَت الفارِسَ والرَّاشِدَ، وساروا نحوَ نُورِ الدين محمود، وهو ببلاد جوسلين، ليَمنَعوه عن مِلْكِها، فوَصَلوا إليه وهو بدلوك، فلمَّا قَرُبوا منه رجَعَ إليهم ولَقِيَهم، وجرى المصافُّ بينهم عند دلوك، واقتَتَلوا أشَدَّ قِتالٍ رآه النَّاسُ، وصَبَرَ الفريقان، ثم انهزمَ الفِرنجُ، وقُتِلَ منهم وأُسِرَ كَثيرٌ، وعاد نور الدين محمود إلى دلوك، فمَلَكَها واستولى عليها."},{"id":2040,"era":"c6","t":"انقضاء دولة بني سبكتكين عن بلاد غزنة .","s":"اقتتل السُّلطانُ سنجر ومَلِك الغور علاءُ الدين الحسين بن الحسين أوَّلُ مُلوكِهم، فكَسَرَه سنجر وأسَرَه، ثم عَفا عنه وأطلَقَه إلى بلاده، ثمَّ إن علاء الدين قَصَدَ غزنةَ, ومَلِكُها حينئذ بهرام شاه بن إبراهيمَ بنِ مَسعودِ بنِ محمود بن سبكتكين فلم يَثبُتْ بها بين يدي علاءِ الدينِ الغوريِّ، بل فارَقَها إلى كرمان، وهي مدينةٌ بينَ غزنةَ والهندِ، وسُكَّانُها قَومٌ يُقالُ لهم أبغان، فلمَّا فارق بهرام شاه غ"},{"id":2041,"era":"c6","t":"وفاة السُّلطان السلجوقي مسعود وتولي ابن أخيه ملكشاه بعده .","s":"هو السُّلطانُ الكَبيرُ، غِياثُ الدِّينِ، أبو الفَتحِ مَسعودُ بنُ مُحَمَّد بن ملكشاه أحَدُ مُلوكِ السُّلجوقيَّة المشاهير، نشأ بالمَوصِل مع أتابك مودود، ورَبَّاه، ثم مع آقسنقر البرسقي، ثمَّ مع خوش بك صاحِبِ المَوصِل، فلمَّا مات والِدُه، حَسَّنَ له خوش بك الخروجَ على أخيه محمود، فالتَقَيا، فانكسر مسعودٌ، ثم تنقلت به الأحوالُ، واستقل بالسَّلطَنةِ سنة 528، وقَدِمَ بغداد. كان عادِلًا لَيِّنًا، كبيرَ الن"},{"id":2042,"era":"c6","t":"النزاع على السلطنة بعد وفاة السُّلطان مسعود السلجوقي .","s":"لَمَّا مات السُّلطان مسعود، قال خاص بك لملكشاه: \"سأقبِضُ عليك صُورةً، وأطلُبُ أخاك محمَّدًا لأُمَلِّكَه، فإذا جاء أمسَكْناه، وتستَقِلَّ أنت. قال: فافعَلْ. فما نَفَقَ خُبثُه على محمَّدٍ، وجاء إلى همذان، فبادر العَسكَرُ إليه، فقال: كلامُكم مع خاص بك فهو الوالِدُ، فوصل هذا القَولُ إلى خاص بك، فاطمَأَنَّ، وتلَقَّاه، وقَدَّمَ له تُحَفًا، ثمَّ قُتِلَ خاص بك، وخَلَّفَ أموالًا جزيلةً مِن بعضِها سبعون ألفَ"},{"id":2043,"era":"c6","t":"الصليبيون يستولون على عسقلان من العبيديين الفاطميين بمصر .","s":"مَلَكَ الفِرنجُ بالشَّامِ مَدينةَ عَسقلان، وكانت مِن جُملةِ مَملكةِ الظَّافِرِ بالله الفاطميِّ المصريِّ، وكان الفِرنجُ كُلَّ سَنةٍ يَقصِدونَها ويَحصُرونَها، فلا يَجِدونَ إلى مِلْكِها سَبيلًا، وكان الوُزراء بمِصرَ لهم الحُكمُ في البلاد، والحُكَّامُ معهم اسمٌ لا معنى تحته، وكان الوزراءُ كُلَّ سَنَةٍ يُرسِلونَ إليها الذَّخائِرَ والأسلِحةَ والأموال والرِّجالَ مَن يَقومُ بحِفظِها، فلمَّا كان في هذه الس"},{"id":2044,"era":"c6","t":"اجتياح الغز الأتراك على بلاد خرسان وإبادة أهلها .","s":"لَمَّا مَلَك الخطا بلادَ ما وراءَ النَّهرِ، خَرَجَ منها الغُزُّ الأتراكُ وهم طائفةٌ مِن مُسلِمي التُّركِ، كانوا بما وراء النَّهرِ، فقَصَدوا خراسان وكانوا خَلقًا كثيرًا، فأقاموا بنواحي بَلخٍ يَرْعَون في مراعيها، فأراد الأميرُ قماج وهو صاحِبُ بلخ، إبعادَهم، فصانعوه بشَيءٍ مِن المال بَذَلوه له، فعاد عنهم، فأقاموا على حالةٍ حَسَنةٍ لا يؤذونَ أحدًا، يُقيمونَ الصَّلاةَ, ويُؤتُونَ الزَّكاةَ, ثمَّ إنَّ قم"},{"id":2045,"era":"c6","t":"وفاة الملك العادل ابن السلار\n  .","s":"هو المَلِكُ العادِلُ سَيفُ الدين أبو منصور عليُّ بنُ إسحاق المعروف بابن السلار، وزيرُ الظَّافِرِ العُبَيدي صاحِبِ مِصرَ، كان من أمراء الأكراد، وكان تربيةَ القَصرِ بالقاهرة، وتقَلَّبَت فيه الأحوالُ في الولايات بالصَّعيدِ وغَيرِه إلى أن تولى الوزارةَ للظَّافِرِ في رَجَب سنة 543. بعد أن تغَلَّبَ على ابنِ مصال وانتزَعَ منه الوزارةَ واستَمَرَّ العادِلُ في الوزارة إلى أن قُتِلَ، وكان ابنُ السلار مِن الأ"},{"id":2046,"era":"c6","t":"انتصار عساكر عبد المؤمن قائد الموحدين على العرب في المغرب .","s":"كانت الحَربُ بين عَسكَرِ عبدِ المُؤمِنِ والعَرَبِ عند مدينة سطيف، وسَبَبُ ذلك أنَّ العَرَبَ- وهم بنو هلالٍ، والأبتح، وعدي، ورياح، وزغب، وغيرهم من العرب- لَمَّا مَلَك عبدُ المؤمِنِ بلادَ بني حَمَّاد اجتَمَعوا من أرض طرابلس إلى أقصى المغرب، وقالوا: إنْ جاوَرَنا عبدُ المؤمِنِ أجلانا من المَغرِبِ، وليس الرأيُ إلَّا إلقاءَ الجِدِّ معه، وإخراجَه من البلاد قبل أن يتمَكَّنَ، وتحالَفوا على التعاوُنِ والتَّ"},{"id":2047,"era":"c6","t":"احتلال الفرنج مدينة بونة بإفريقيَّة .","s":"سار أُسطولُ رجار مَلِكِ الفرنج بصقليَّةَ إلى مدينة بونة- وهي أوَّلُ حَدٍّ مِن بلادِ إفريقيَّةَ- وكان المُقَدَّمُ عليهم فتاه فيلب المهدوي، فحَصَرَها واستعان بالعَرَبِ عليها، فأخَذَها في رجب، وسَبى أهلَها، ومَلَكَ ما فيها، غيرَ أنَّه أغضى عن جماعةٍ مِن العُلَماءِ والصَّالحينَ، حتى خَرَجوا بأهليهم وأموالِهم إلى القُرى، فأقام بها عَشرةَ أيَّامٍ، وعاد إلى المهديَّةِ وبَعضِ الأسرى معه، وعاد إلى صقليَّةَ"},{"id":2048,"era":"c6","t":"نُورِ الدِّينِ محمود زِنكي يسيطر على قَلعةَ تَلِّ باشِرَ .","s":"في هذه السَّنَةِ وقِيلَ التي بعدَها، مَلَكَ نورُ الدينِ محمودُ بن زِنكي قَلعةَ تَلِّ باشِرَ، وهي شَماليَّ حَلَب مِن أَمنَعِ القِلاعِ، وسَببُ مِلْكِها أن الفِرنجَ لمَّا رأوا أن نورَ الدينِ مَلَكَ دِمشقَ خافوهُ، وعَلِموا أنه يَقوَى عليهم، ولا يَقدِرون على الانتِصافِ منه، لِمَا كانوا يَرَوْنَ منه قبلَ مِلْكِها، فراسَلَهُ مَن بهذه القَلعةِ مِن الفِرنجِ، وبَذَلوا له تَسليمَها، فسَيَّرَ إليهم الأَميرَ ح"},{"id":2049,"era":"c6","t":"حَصْرُ عَسكَرِ الخَليفَةِ المُقتَفِي لأَمرِ الله تَكريتَ وعَوْدُهُم عنها .","s":"سَيَّرَ الخَليفةُ العبَّاسيُّ المُقتَفِي لأَمرِ الله عَسكرًا إلى تَكريتَ لِيَحصُروها، وأَرسلَ معهم مُقدَّمًا عليهم أبا البَدرِ بن الوَزيرِ عَوْنِ الدِّينِ بن هُبيرَة وتُرشُكَ، وهو مِن خَواصِّ الخَليفةِ، وغَيرَهما، فجَرَى بين أبي البَدرِ وتُرشُكَ مُنافرَةً فكَتَبَ ابنُ الوَزيرِ للخَليفةِ يشكو من تُرشكَ، فأَمرَ الخَليفةُ بالقَبضِ على تُرشكَ، فعَرَفَ ذلك، فأَرسلَ إلى مَسعودِ بِلال، صاحِبِ تَكريت، وصا"},{"id":2050,"era":"c6","t":"بُطلانُ خَبَرِ نَقْلِ رَأسِ الحُسينِ رضي الله عنه مِن عَسقلانَ إلى القاهرةِ .","s":"سُئِلَ شَيخُ الإسلامِ ابنِ تَيميَّةَ عن المَشهَدِ المَنسوبِ إلى الحُسينِ رضي الله عنه بمَدينةِ القاهرةِ:هل هو صَحيحٌ أم لا؟ وهل حُمِلَ رَأسُ الحُسينِ إلى دِمشقَ، ثم إلى مصر، أم حُمِلَ إلى المَدينَةِ من جِهَةِ العِراقِ؟ وهل لِمَا يَذكُرهُ بعضُ الناسِ مِن جِهَةِ المَشهَدِ الذي كان بعَسقلان صِحَّةٌ أم لا؟ ومَن ذَكَرَ أَمرَ رَأسِ الحُسينِ، ونَقْلِه إلى المَدينةِ النَّبويَّةِ دون الشامِ ومصر؟ ومَن جَزَ"},{"id":2051,"era":"c6","t":"اغتِيالُ الحاكِمِ العُبيديِّ (الفاطِميِّ) الظافِرِ وتَولِيَةُ ابنِه الفائزِ بنَصرِ الله .","s":"هو حاكِمُ مصر الظافِرُ أبو مَنصورٍ إسماعيلُ بن الحافظِ لدِينِ الله عبدِ المجيدِ بن محمدِ بن المُستَنصِر مَعَدِّ بن الظاهرِ عليِّ بن الحاكمِ الفاطميُّ العُبيديُّ، المصريُّ، الإسماعيليُّ. وَلِيَ الأَمرَ بعدَ أَبيهِ خَمسةَ أَعوامٍ. وكان شابًّا جَميلًا وَسيمًا لَعَّابًا عاكِفًا على الأَغاني والسَّراري، استَوْزَرَ الأَفضلَ سليمَ بن مصالٍ فَسَاسَ الإِقليمَ. وانقَطعَت في أَيامِه الدَّعوةُ له ولآبائِهِ ال"},{"id":2052,"era":"c6","t":"نُورُ الدِّين زِنكي يَستَولِي على مَدينةِ دِمشق وانتِهاءُ الدَّولَةِ البوريَّةِ .","s":"تَمَلَّك نُورُ الدِّين محمودُ بن زِنكي مَدينةَ دِمشق، وأَخذَها مِن صاحِبِها مُجيرِ الدِّين أبق بن محمد بن بوري بن طغتكين، وكان سَببُ جِدِّهِ في مِلْكِها أن الفِرنجَ لمَّا مَلَكوا في العام الماضي مَدينةَ عَسقلان لم يكُن لنورِ الدين طَريقٌ لإزعاجِهِم عنها لاعتِراضِ دِمشق بينه وبين عَسقلان، كما أن الفِرنجَ لمَّا مَلَكوا عَسقلان طَمِعوا في دِمشق، حتى أنهم استَعرَضوا كلَّ مَن بدِمشق مَملوكًا أو جارِيةً"},{"id":2053,"era":"c6","t":"قَصْدُ الإسماعيليَّةِ خُراسانَ والظَّفَرُ بهم .","s":"اجتَمعَ جَمْعٌ كَثيرٌ من الإسماعيليةِ من قهستان، بلغت عُدَّتُهم سَبعةَ آلافِ رَجلٍ ما بين فارسٍ وراجلٍ، وساروا يُريدون خُراسانَ لاشتِغالِ عَساكرِها بالأَتراكِ الغُزِّ، وقَصَدوا أَعمالَ خواف وما يُجاوِرُها، فلَقِيَهم الأَميرُ فرخشاه بن محمود الكاسانيُّ في جَماعةٍ من حَشَمِه وأَصحابِه، فعَلِمَ أنه لا طاقةَ له بهم، فتَرَكهُم وسار عنهم، وأَرسلَ إلى الأَميرِ محمدِ بن أنر، وهو مِن أَكابرِ أُمراءِ خُراسا"},{"id":2054,"era":"c6","t":"فَتْحُ نورِ الدِّينِ الزِّنكي بعلبكَ وتَقرِيبُه لآلِ أيوب واحتِفاؤهُ بهم .","s":"كان نَجمُ الدينِ أيوبُ نائِبَ بعلبك، وعلى قَلعَتِها رَجلٌ يُقالُ له الضَّحَّاكُ البِقاعيُّ، فكاتَبَ نَجمُ الدينِ نورَ الدينِ محمودًا، ولم يَزَل نورُ الدينِ يَتلَطَّف البِقاعيَّ حتى أَخَذَ منه القَلعةَ ثم استَدعَى نَجمَ الدينِ أيوبَ إليه بدمشق فأَقطَعَهُ إِقطاعًا حَسَنًا، وأَكرَمهُ. مِن أَجلِ أَخيهِ أَسَدِ الدينِ، فإنه كانت له اليَدُ الطُّولَى في فَتحِ دِمشقَ، وجَعلَ الأَميرَ شَمسَ الدولةِ بوران شا"},{"id":2055,"era":"c6","t":"الغُزُّ الأَتراكُ التُّركُمان يَنْتَزِعُون خوزستان ونيسابور مِن السَّلاجِقَة .","s":"استَولَى شملةُ التُّركمانيُّ على خوزستان، وكان قد جَمَعَ جَمْعًا كَثيرًا من التُّركمانِ وسار يريد خوزستان، وصاحِبُه حينئذٍ ملكشاه بنُ محمودٍ السَّلجوقيُّ، فسَيَّرَ الخَليفةُ إليه عَسكرًا، فلَقِيَهم شملةُ في رجب، وقاتَلَهم، فانهَزَم عَسكرُ الخَليفةِ، وأَسَرَ وُجُوهَهُم، ثم أَحسَنَ إليهم وأَطلَقَهم، وأَرسلَ يَعتَذِر، فقَبِلَ عُذرَهُ، وسار إلى خوزستان فمَلَكَها وأَزاحَ عنها ملكشاه بنَ مَحمودٍ، ثم سار"},{"id":2056,"era":"c6","t":"عِصيانُ أَهالي إفريقية على مَلِكِ الفِرنجِ بصِقِلِّيَة .","s":"مات في سَنةِ 548هـ رجار مَلِكُ صِقِلِّية ومَلَكَ وَلدُه غليالم، وكان فاسِدَ التَّدبيرِ، فخَرجَ من حُكمِه عِدَّةٌ من حُصونِ صِقِلِّية، فلمَّا كان هذه السَّنَةُ قَوِيَ طَمعُ الناسِ فيه، فخَرجَ عن طاعَتِه جَزيرةُ جربة وجَزيرةُ قرقنة، وأَظهَروا الخِلافَ عليه، وخالَفَ عليه أَهلُ إفريقية، فأَوَّلُ مَن أَظهرَ الخِلافَ عليه، من أَهلِ إفريقية، عُمَرُ بنُ أبي الحُسينِ الفِرياني بمَدينةِ صَفاقس، وكان رجار قد"},{"id":2057,"era":"c6","t":"دُخولُ فِرنجِ صِقِلِّيَةَ زَوِيلةَ ونَهْبُها وقَتْلُ نِسائِها وأَطفالِها .","s":"لمَّا حَصرَ أهالي أفريقية المَهدِيَّة سَيَّرَ إليها صاحِبُ صِقِلِّية عِشرينَ شِينِيًّا –سُفن كبيرة- فيها الرِّجالُ والطَّعامُ والسِّلاحُ، فدَخَلوا البلدَ، وأَرسَلوا إلى العَربِ وبَذَلوا لهم مالًا لِيَنهَزِموا، وخَرَجوا من الغَدِ، فاقتَتَلوا هُم وأَهلُ زَوِيلةَ، فانهَزَمَت العَربُ، وبَقِيَ أَهلُ زَوِيلةَ وأَهلُ صفاقس يُقاتِلون الفِرنجَ بِظَاهِرِ البلدِ، وأَحاطَ بهم الفِرنجُ، فانهَزَم أَهلُ صفاقس ور"},{"id":2058,"era":"c6","t":"حِصارُ السُّلطانِ محمدِ بنِ مَحمودٍ السَّلجوقيِّ بغدادَ .","s":"أَرسلَ السُّلطانُ محمدُ بنُ مَحمودِ بنِ ملكشاه إلى الخَليفةِ المُقتَفِي يَطلُب منه أن يُخطَب له في بغداد، فلم يُجِبهُ إلى ذلك، فسار من همذان إلى بغداد لِيُحاصِرَها، فانجَفَلَ الناسُ وحَصَّنَ الخَليفةُ البلدَ، وجاء السُّلطانُ محمدُ فحَصَرَ بغدادَ، ووَقَفَ تِجاهَ التَّاجِ مِن دارِ الخِلافَةِ في جَحْفَلٍ عَظيمٍ، ورَموا نَحوَهُ النُّشَّابَ، وقاتَلَت العامَّةُ مع الخَليفةِ قِتالًا شَديدًا بالنِّفْطِ وغ"},{"id":2059,"era":"c6","t":"حَصْرُ نُورِ الدِّينِ مَحمودٍ زِنْكِي قَلعةَ حارِم .","s":"جَمَعَ نورُ الدينِ بنُ محمودٍ صاحِبُ الشامِ، العَساكِرَ بحَلَب، وسار إلى قَلعةِ حارِم، وهي للفِرنجِ غَربيَّ حَلَب،  فحَصَرَها وَجَدَّ في قِتالِها، فامتَنَعَت عليه بحَصَانَتِها، وكَثرَةِ مَن بها من فِرسانِ الفِرنجِ ورَجَّالَتِهم، فلمَّا عَلِمَ الفِرنجُ ذلك جَمَعوا فارِسَهم وراجِلَهم من سائرِ البلادِ، وحَشَدوا، واستَعَدُّوا، وساروا نَحوَها لِيُرَحِّلُوه عنها، فلمَّا قارَبوهُ طَلَبَ منهم المُصَافَّ، "},{"id":2060,"era":"c6","t":"فَتْحُ نُورِ الدِّينِ  محمودٍ زنكي حِصْنَ شيزر  .","s":"حِصنُ شيزر قَريبٌ مِن حماة، بينهما نِصفُ نَهارٍ، وهو على جَبلٍ عالٍ مَنيعٍ لا يُسلَك إليه إلا مِن طَريقٍ واحدةٍ. وكان لآلِ مُنقِذ الكِنانِيِّين يَتَوارثونَهُ من أَيامِ صالِحِ بنِ مرداس، ثم تُوفِّي سُلطانُها وبَقِيَ بعدَه أَولادُه، فبَلَغَ نورَ الدينِ عنهم مُراسلةُ الفِرنجِ، فاشتَدَّ حِنقُه عليهم، وانتَظرَ فُرصةً تُمَكِّنُهُ، فلمَّا خَرِبَت القَلعةُ من الزَّلزلَةِ لم يَنجُ من بني مُنقِذٍ الذين بها "},{"id":2061,"era":"c6","t":"انقِراضُ دَولةِ المُلَثَّمِين (المُرابِطِين) في الأَندلُس .","s":"انقَرَضَت دَولةُ المُلَثَّمِين(المُرابِطِين) بالأندلس، وسَببُ ذلك أن عبدَ المؤمن لمَّا استَعمَل ابنَه أبا سَعيدٍ عَلِيًّا على الجَزيرَةِ الخَضراءِ ومالقة، عَبَرَ أبو سعيدٍ البحرَ إلى مالقة، واتَّخَذَها دارًا، وكاتَبَهُ أَميرُ المُرابِطين بالأندلس ميمونُ بنُ بَدرٍ اللَّمتُوني، صاحِبُ غرناطة، أن يُوَحِّد ويُسَلِّم إليه غرناطة، فقَبِلَ أبو سعيدٍ ذلك منه وتَسَلَّم غرناطة، فسار ميمون إلى مالقة بأَهلِه "},{"id":2062,"era":"c6","t":"عبدِ المُؤمِن قائدِ المُوَحِّدِين يسيطر على مدينة المِرْيَةَ في الأَندَلُسِ .","s":"لمَّا مَلَكَ أبو سَعيدٍ عليُّ بنُ عبدِ المُؤمنِ غرناطة جَمعَ الجُيوشَ وسار إلى مَدينةِ المِريَةِ، وهي بأَيدِي الفِرنجِ، أَخَذوها من المسلمين سَنةَ 542هـ، فلمَّا نازَلَها وَافاهُ الأُسطولُ مِن سَبتَة وفيه خَلْقٌ كَثيرٌ من المسلمين، فحَصَروا المِريَةَ بَرًّا وبَحرًا، وجاء الفِرنجُ إلى حِصنِها، فحَصَرَهُم فيها ونَزَلَ عَسكرُه على الجَبلِ المُشرِف عليها، وبَنَى أبو سَعيدٍ سُورًا على الجَبلِ إلى البَحر"},{"id":2063,"era":"c6","t":"غَزْوُ صاحِبِ طبرستان الإسماعِيلِيَّةَ .","s":"جَمعَ شاه مازندران رستم بنُ عليِّ بنِ شهريار عَسكرَهُ، وسارَ ولم يَعلَم أَحَدٌ جِهَةَ مَقصِدِهِ، وسَلكَ المَضايِقَ، وجَدَّ السَّيْرَ إلى بلدِ ألموت، وهي للإسماعيليَّةِ على الرغمِ من أنه شِيعِيٌّ شَديدُ التَّشَيُّعِ، فأَغارَ عليها وأَحرقَ القُرَى والسَّوادَ، وقَتَلَ فأَكثرَ، وغَنِمَ أَموالَهم، وسَبَى نِساءَهُم، واستَرَقَّ أَبناءَهُم فباعَهُم في السُّوقِ وعادَ سالِمًا غانِمًا، وانخَذلَ الإسماعيليةُ،"},{"id":2064,"era":"c6","t":"قِتالُ عَسكَرِ العُبيدِيِّينَ (الفاطِمِيِّينَ) مع الفِرنجِ .","s":"انفَسَخَت الهُدنَةُ بين الفِرنجِ وبين المِصرِيِّين، فشَرَعَ الوَزيرُ الصالحُ أبو الغارات الأَرمَنيُّ الرَّافِضيُّ في النَّفَقَةِ على العَساكِرِ وعِربانِ البِلادِ للغارَةِ على بلادِ الفِرنجِ. فأَخرجَ سَرِيَّةً في سابع عشر جُمادَى الأُولى وأَتبَعَها بأُخرَى في رابع عشر جُمادَى الآخِرَة؛ فوَصَلَت الأُولى إلى غَزَّة ونَهَبَت أَطرافَها، ثم سارت إلى عَسقلانَ فأَسَرَت وغَنِمَت وعادَت مُنتَصِرةً. ثم نَدَب"},{"id":2065,"era":"c6","t":"تَحالَفَ إمبراطور بِيزَنطَة ومَلِكِ القُدسِ الصَّليبي ضِدَّ نُورِ الدِّينِ زِنكي .","s":"تَحالَفَ بودان الثالثُ مَلِكُ بَيتِ المَقدِس مع الإمبراطورِ البِيزنطيِّ مانويل كومنين ضِدَّ نورِ الدينِ مَحمودٍ مُقابِلَ إطلاقِ يَدِ الإمبراطورِ البِيزنطي في أنطاكية, وزَواجِ بودان الثالثِ من تيودورا ابنَةِ أخي الإمبراطور."},{"id":2066,"era":"c6","t":"وَفاةُ سنجر مَلِكِ السَّلاجِقَةِ فارِسِ وعَمِيدِ الأُسرَةِ السَّلجوقِيَّة .","s":"هو السُّلطانُ مُعِزُّ الدِّينِ أبو الحارِثِ سنجر بن ملكشاه بن ألب أرسلان بن جغريبك بن ميكائيل بن سلجوق بن دقاق؛ الغُزِّيُّ، التُّركيُّ، السَّلجوقيُّ سُلطانُ خراسان وغُزنَة وما وَراءَ النَّهرِ. كانت وِلادَتُه يومَ الجُمعةِ لِخَمسٍ بَقِينَ من رجب سَنةَ 479هـ بظاهِرِ مَدينةِ سنجار، ولذلك سُمِّيَ بسنجر. نَشأَ ببلادِ الخَزَر، ثم سَكنَ خراسان. كان مِن أَعظمِ المُلوكِ هِمَّةً، وأَكثرِهم عَطاءً، ذُكِرَ عن"},{"id":2067,"era":"c6","t":"جَمعٌ من الجُندِ ينَهْبُون ويقَتْلُون حجيج خُراسان .","s":"سار حُجَّاجُ خُراسان، فلمَّا رَحَلوا عن بسطام أغار عليهم جَمعٌ من الجُندِ الخُراسانيَّة قد قَصَدوا طبرستان، فأَخَذوا من أَمتِعَتَهم، وقَتَلوا نَفرًا منهم، وسَلِمَ الباقون وساروا من مَوضِعهم، فبينما هم سائِرون إذ طَلُعَ عليهم الإسماعيليَّةُ، فقاتَلَهم الحُجَّاجُ قِتالًا عَظيمًا، وصَبَروا صَبرًا عَظيمًا، فقُتِلَ أَميرُهم، فانخَذَلوا، وأَلقَوا بأيديهم، واستَسلَموا وطَلَبوا الأَمانَ، وأَلقَوا أَسلِحَت"},{"id":2068,"era":"c6","t":"حِمايةُ نُورِ الدِّينِ مَحمودٍ للشامِ من الفِرنجِ بعدَ زَلازلَ قَوِيَّةٍ تُدمِّرُها .","s":"كان بالشامِ زَلازلُ كَثيرةٌ قَوِيَّةٌ خَرَّبَت كَثيرًا من البلادِ، وهَلَكَ فيها ما لا يُحصَى كَثْرَةً، فخَرِبَ منها بالمرة: حماة، وشيزر، وكفر طاب، والمعرة، وأفاميا، وحِمصُ، وحِصنُ الأَكرادِ، وعرقة، واللَّاذِقِيَّة، وطَرابلُس، وأَنطاكية، وأما ما لم يَكثُر فيه الخَرابُ ولكن خَرِبَ أَكثرُه فجَميعُ الشامِ، وتَهَدَّمَت أَسوارُ البلادِ والقِلاعِ، فقام نورُ الدينِ محمودٌ في ذلك المقام المرضي، وخاف على بل"},{"id":2069,"era":"c6","t":"الحَربُ بين الغُزِّ الأَتراكِ التُّركمانِ والإسماعيليَّةِ بخُراسان .","s":"نَزلَ جَمْعٌ من الإسماعيليَّةِ من قِلاعِهم وهُم ألفٌ وسبعمائة رَجلٍ. على طائفةٍ من الغُزِّ الأَتراكِ التُّركمانِ كانوا بنَواحِي قهستان، فأَوقَعوا بهم، فلم يَجِدوا الرِّجالَ، وكانوا قد فارَقوا بُيوتَهم، فنَهَبوا الأَموالَ، وأَخَذوا النِّساءَ والأَطفالَ، وأَحرَقوا ما لم يَقدِروا على حَملِه، وعادَ التُّركمانُ ورَأوا ما فُعِلَ بهم، فتَبِعوا أَثرَ الإسماعيليَّةِ، فأَدرَكوهُم وهُم يَقتَسِمون الغَنيمةَ، "},{"id":2070,"era":"c6","t":"فِتنَةُ الغُزِّ الأَتراكِ التُّركمانِ بالجَبلِ وقِتالُهم .","s":"كَثُرَ فَسادُ الغُزِّ الأَتراكِ التُّركمانِ أَصحابِ بُرجُم الإيوائي بالجَبلِ، فسَيَّرَ إليهم الخَليفةُ العبَّاسيُّ المُقتَفِي مِن بغداد عَسكرًا مُقَدَّمَهُم منكبرسُ المسترشدي، فلمَّا قارَبَهُم اجتَمَعَ التُّركمانُ، فالتَقوا واقتَتَلوا هُم ومنكبرس، فانهَزَم التُّركمانُ أَقبحَ هَزيمَةٍ، فقُتِلَ بَعضُهم، وأُسِرَ البَعضُ الآخَر، وحُمِلَت الرُّؤوسُ والأَسارَى إلى بغداد."},{"id":2071,"era":"c6","t":"القِتالُ بين عَسكرِ العُبيدِيِّينَ (الفاطِمِيِّينَ) والفِرنج  .","s":"جَهَّزَ المَلِكُ الصالحُ أبو الغارات الأَرمنيُّ الرَّافِضيُّ وَزيرُ العاضِدِ حاكِم مصر العُبيديُّ أَربعةَ آلافٍ وأَمَّرَ عليهم شَمسَ الخِلافَةِ أبا الأَشبالِ ضِرغامًا للغارَةِ على بِلادِ الفِرنجِ، فساروا إلى تَلِّ العُجولِ وحارَبوا الفِرنجَ، فانهَزَموا من المسلمين هَزيمةً قَبيحةً عليهم. وسَيَّرَ عَسكرًا فوَاقَعوا الفِرنجَ على العَريشِ وعادوا ظافِرينَ بعِدَّةِ غَنائمَ ما بين خُيولٍ وأَموالٍ، وسار ا"},{"id":2072,"era":"c6","t":"مُعاوَدَةُ الغُزِّ الأَتراكِ (التُّركمانِ) الفِتنةَ بخُراسان وقِتالُهم .","s":"كان الغُزُّ الأَتراكُ (التُّركمانُ) قد أَقاموا بمَدينةِ بَلخ واستَوطَنُوها، وتَرَكوا النَّهْبَ والقَتْلَ ببلادِ خُراسان، واتَّفَقَت الكَلمةُ بها على طاعَةِ السُّلطانِ خاقان محمود بن أرسلان، وكان المُتَوَلِّي لِأُمورِ دَولتِه المُؤيَّدُ أي أبه -أحد مماليك سنجر- وعن رَأيِه يَصدُر محمودٌ، فلمَّا كان هذه السَّنةَ في شعبان، سار الغُزُّ من بَلخ إلى مَرو، وكان السُّلطانُ محمود بسرخس في العَساكرِ، فسار ال"},{"id":2073,"era":"c6","t":"ضَمُّ المُوَحِّدِين عَدَدًا من مَناطِقَ إفريقية .","s":"وفي مُدَّةِ حِصارِ عبدِ المُؤمنِ للمَهديَّةِ أَطاعَتهُ صفاقسُ، وكذلك مَدينةُ طرابلس، وجِبالُ نَفُوسَة، وقُصورُ إفريقية وما وَالَاهَا، وفَتَحَ مَدينةَ قابس بالسَّيفِ، وسَيَّرَ ابنَه أبا محمدٍ عبدَ الله في جَيشٍ ففَتَحَ بِلادًا، ثم إن أَهلَ مَدينةِ قفصة لمَّا رَأوا تَمَكُّنَ عبدِ المؤمنِ أَجمَعوا على المُبادَرَةِ إلى طاعَتِه، وتَسليمِ المَدينةِ إليه."},{"id":2074,"era":"c6","t":"الفِتنَةُ بين الشَّافعيَّةِ والشِّيعَةِ في استراباذ .","s":"وَقعَ في استراباذ -جرجان حاليا، شمال إيران- فِتنةٌ عَظيمةٌ بين العَلَوِيِّين ومَن يَتبَعُهم مِن الشِّيعَةِ وبين الشافعيَّةِ ومَن معهم، وكان سَببُها أن الإمامَ محمدًا الهَرويَّ وَصلَ إلى استراباذ، فعَقَدَ مَجلِسَ الوَعظِ، وكان قاضِيَها أبو نصرٍ سعدُ بن محمدِ بن إسماعيلَ النعيميُّ شافعيُّ المَذهَبِ أيضًا فثار العَلَوِيِّون ومَن يَتبَعُهم مِن الشِّيعَةِ بالشافعيَّةِ ومَن يَتبَعُهم باستراباذ، ووَقَعَت"},{"id":2075,"era":"c6","t":"نِهايَةُ الدَّولةِ النَّجاحِيَّة وقِيامُ دَولةِ بَنِي مَهديٍّ باليَمنِ .","s":"كان بَنُو نَجاحٍ يَحكُمون تِهامَة وكان أَميرُهم فاتك بن منصور الذي تُوفِّي سَنةَ 540هـ وكان ظَهَرَ في أَيامِه المَهدِيُّون، فهاجَمُوا بإِمْرَةِ عليِّ بن مَهديٍّ بِلادَ بَنِي نَجاحٍ سَنةَ 538هـ غيرَ أنَّهم هُزِمُوا وانسَحَب عليُّ بن مَهديٍّ إلى الجِبالِ، وبعدَ مَوتِ فاتك خَلَفَهُ فاتك بن محمد بن فاتك، وبَقِيَ إلى أَواخرِ هذا العامِ فكان آخِرَ مُلوكِ بَنِي نَجاحٍ ونِهايةَ دَولَتِهم به، ثم أَغارَ علي"},{"id":2076,"era":"c6","t":"عبد المُؤمِن قائدِ المُوَحِّدِين ينتزع مدينة المَهديَّةَ من الفرنج .","s":"لمَّا مَلَكَ الفِرنجُ مَدينةَ المَهديَّة وفَعَلوا ما فَعَلوا في زويلة المَدينةِ المُجاوِرَةِ للمَهديَّةِ من القَتلِ والنَّهبِ، هَرَبَ منهم جَماعةٌ وقَصَدوا عبدَ المُؤمنِ صاحبِ المَغربِ، وهو بمراكش، يَستَجيرُونَه، فلمَّا وَصَلوا إليه ودَخَلوا عليه أَكرَمَهم، وأَخبَروهُ بما جَرَى على المسلمين، وأنه ليس من مُلوكِ الإسلامِ مَن يُقصَد سِواهُ، فبدَأَ بالاستِعدادِ للمَسيرِ, فلمَّا كان في صفر سَنةَ554هـ س"},{"id":2077,"era":"c6","t":"ارتفاع نهر دِجلَة وغرق بغداد .","s":"في ثامنِ رَبيعٍ الآخر، كَثُرَت الزِّيادةُ في دِجلَة، وخَرَقَ القُورجُ  فوقَ بغداد -القُورج  نهر بين القاطول وبغداد، منه يكون غرق بغداد غالبًا- فامتَلأَت الصَّحارِي وخَندَق البلد، وأَفسدَ الماءُ السُّورَ وأَحدثَ فيه فَتحةً يومَ السبتِ تاسعَ عشرَ الشهرِ، فوَقعَ بعضُ السُّورِ عليها فَسَدَّهَا، ثم فَتحَ الماءُ فَتحةً أُخرَى، وأَهمَلوها ظَنًّا أنها تُنَفِّسُ عن السُّورِ لِئَلَّا يَقَع، فغَلَبَ الماءُ، "},{"id":2078,"era":"c6","t":"دُخولُ المُوَحِّدِينَ تونس .","s":"في صَفر سار عبدُ المؤمنِ بنُ عليٍّ عن مراكش، يَطلُب إفريقية، فلم يَزَل يَسيرُ إلى أن وَصلَ إلى مَدينةِ تونس في الرابع والعشرين من جُمادَى الآخرة، وبها صاحِبُها أحمدُ بن خُراسان، فلمَّا نازَلَها أَرسلَ إلى أَهلِها يَدعوهُم إلى طاعَتِه، فامتَنَعوا، فقاتَلَهم من الغَدِ أَشَدَّ قِتالٍ، فلم يَبقَ إلا أَخْذُها، ودُخولُ الأُسطولِ إليها، فجاءَت رِيحٌ عاصِفٌ مَنَعَت المُوَحِّدِين من دُخولِ البلدِ، فرَجَعوا"},{"id":2079,"era":"c6","t":"وَفاةُ السُّلطانِ محمدِ بنِ محمودِ بنِ ملكشاه .","s":"هو السُّلطانُ محمدُ بن محمودِ بن محمدٍ، كان مَولِدُه سَنةَ 522هـ، وكان كَريمًا عاقِلًا، وهو الذي حاصَرَ بغدادَ طالِبًا السَّلْطَنَةَ وعادَ عنها، فأَصابَهُ سُلٌّ، وطالَ به فماتَ ببابِ همذان، فلمَّا حَضَرَهُ الموتُ أَمَرَ العَساكرَ فرَكِبَت وأَحضرَ أَموالَه وجَواهِرَه وحَظَاياهُ ومَمَاليكَهُ، فنَظَرَ إلى الجَميعِ مِن طَيَّارَةٍ تشرف على ما تحتها، فلمَّا رَآهُ بَكَى، وقال: هذه العَساكرُ والأَموالُ وا"},{"id":2080,"era":"c6","t":"وفاة ملكشاه بن السلطان محمود بن محمد بن ملكشاه .","s":"هو السلطان ملكشاه بن السلطان محمود بن محمد بن ملكشاه بن ألب أرسلان، تولى السلطنة بعد وفاة عَمِّه السلطان مسعود بن محمد بعهدٍ منه. فقعد في السلطنة وخُطِبَ له، وكان المتغلِّبُ على المملكة أميرًا يقال له خاص بك، وأصله صبي تركماني اتصل بخدمة السلطان مسعود، فتقدَّم على سائر أمرائه، ثم إنَّ خاص بك قبض على السلطان ملكشاه بن محمود وسجَنه، وأرسل إلى أخيه محمد بن محمود، وهو بخورستان، فأحضَرَه وتولى السلطنة،"},{"id":2081,"era":"c6","t":"وَفاةُ حاكم مصر الفائِزِ بنَصرِ الله العُبيدِيِّ وتَوَلِّي العاضِدِ بن الحافِظِ .","s":"هو حاكِمُ مصر الفائزُ بنَصرِ الله أبو القاسمِ عيسى بن الظَّافِرِ إسماعيلَ بن الحافِظِ عبدِ المَجيدِ بن محمدِ بن المُستَنصِر بالله العُبيديُّ، المصريُّ الفاطِميُّ. كانت مُدَّةُ حُكمِه سِتَّ سِنين ونحوَ شَهرينِ؛ وكان عُمرُه لمَّا وَلِيَ خمسَ سِنين، قال الذَّهبيُّ: \"لمَّا اغتَالَ عبَّاسٌ الوَزيرُ الظَّافِرَ، أَظَهَرَ القَلقَ، ولم يكُن عَلِمَ أَهلُ القَصرِ بمَقتَلِه, فطَلَبوه في دُورِ الحَرَمِ فما وَج"},{"id":2082,"era":"c6","t":"وَفاةُ الخَليفَةِ العبَّاسيِّ المُقتَفِي بأَمرِ الله وخِلافَةُ ابنِهِ المُستَنجِد بالله .","s":"هو الخَليفةُ، أَميرُ المُؤمِنين، المُقتَفِي لأَمرِ الله، أبو عبدِ الله، محمدُ بن المُستَظهِر بالله أبي العبَّاسِ أحمدَ بن المُقتَدِي بالله، بن الذَّخيرَةِ محمدِ بن القائمِ بأَمرِ الله عبدِ الله بن القادرِ بالله عبدِ الله أحمدَ بن الأَميرِ إسحاقَ بن المُقتَدِر، الهاشميُّ، العبَّاسيُّ، البغداديُّ، الحَبَشيُّ الأُمِّ. وُلِدَ في رَبيعٍ الأوَّلِ سَنةَ 489هـ. وبُويِعَ بالإمامَةِ في سادس عشر ذي القعدةِ، "},{"id":2083,"era":"c6","t":"الفتنة بنيسابور وتخريبها .","s":"كان أهلُ العبث والفساد بنيسابور قد طمعوا في نهب الأموال وتخريب البيوت، وفِعلِ ما أرادوا، فإذا نُهوا لم ينتهوا، فلما كان الآن تقدمَ المؤيد أي أبه بقبض أعيان نيسابور، منهم نقيب العلويين أبو القاسم زيد بن الحسن الحسيني وغيره، وحبسهم في ربيع الآخر، وقال: أنتم الذين أطمعتم المفسدين حتى فعلوا هذه الفِعال، ولو أردتم منعهم لامتنعوا، وقتل من أهل الفساد جماعةً، فخربت نيسابور بالكلية، ومن جملة ما خُرِّبَ مسج"},{"id":2084,"era":"c6","t":"فتنة بين أصحاب الوزير ابن هبيرة والفقهاء ببغداد .","s":"خرج الوزير ابن هبيرة من داره إلى الديوان، والغلمان يطرقون له، وأرادوا أن يَرِدوا باب المدرسة الكمالية بدار الخليفة، فمنعهم الفقهاءُ وضربوهم بالآجُرِّ، فشَهَر أصحابُ الوزير السيوف وأرادوا ضربَهم، فمنعهم الوزير، ومضى إلى الديوان، فكتب الفقهاء مطالعةً يشكون أصحاب الوزير، فأمر الخليفة بضربِ الفقهاء وتأديبهم ونفيهم من الدار، فمضى أستاذ الدار وعاقبَهم هناك، واختفى مدرِّسُهم الشيخ أبو طالب، ثم إنَّ الوزي"},{"id":2085,"era":"c6","t":"مبايعة السلطان أرسلان شاه بن طغرل بن محمد بن ملكشاه .","s":"لما تخلص الخادم كردبازو من السلطان سليمان شاه بسَجنه ثم قتله، أرسل إلى إيلدكز، صاحب آران وأكثر بلاد أذربيجان، يستدعيه إليه ليخطُبَ للملك أرسلان شاه الذي معه، وبلغ الخبر إلى إينانج صاحب بلاد الري، فسار ينهب البلادَ إلى أن وصل إلى همذان، فتحصن كردبازو، فطلب منه إينانج أن يعطيه مصافًا، فقال: أنا لا أحاربك حتى يصل الأتابك الأعظم إيلدكز. وسار إيلدكز في عساكره جميعًا يزيد على عشرين ألف فارس، ومعه أرسلان"},{"id":2086,"era":"c6","t":"مقتل السلطان سليمان شاه بن محمد ملكشاه .","s":"قُتِلَ السلطانُ سليمان شاه بن السلطان محمد بن ملكشاه، وسببُ ذلك أنه كان فيه تهوُّرٌ وخرقٌ، وبلغ به شربُ الخمر حتى إنه شربها في رمضان نهارًا، وكان يجمع المساخِرَ ولا يلتفت إلى الأمراء، فأهمل العسكرُ أمره، وصاروا لا يحضُرون بابه، وكان قد ردَّ جميع الأمور إلى شرف الدين كردبازو الخادم، وهو من مشايخ الخدم السلجوقية، كان فيه دينٌ وعقل وحسن تدبير، فكان الأمراء يشكُون إليه السلطان وهو يُسَكِّنُهم، فكتب سل"},{"id":2087,"era":"c6","t":"وفاة ملك الغور علاء الدين وتولي ابنه محمد الملك بعده .","s":"هو الملك علاء الدين الحسين بن الحسين الغوري ملك الغور، وكان عادلًا من أحسن الملوك سيرة في رعيته، توفي بعد انصرافه عن غزنة، ولما مات ملَك بعده ابنُه سيف الدين محمد، وأطاعه الناس وأحبوه، وكان قد صار في بلادهم جماعةٌ من دعاة الإسماعيلية، وكثر أتباعهم فأُخرِجوا من تلك الديار جميعها، ولم يبقَ فيها منهم أحدٌ، وراسل الملوك وهاداهم، واستمال المؤيد، أي أبه صاحب نيسابور وطلب موافقتَه‏.‏"},{"id":2088,"era":"c6","t":"الحرب بين العرب وعسكر بغداد .","s":"اجتمعت خفاجة إلى الحلة والكوفة، وطالبوا برسومِهم من الطعام والتمر وغير ذلك، فمنعهم أميرُ الحاج أرغش، وهو مقطع الكوفة، ووافقَه على قطعه الأمير قيصر شحنة الحلة، وهما من مماليك الخليفة، فأفسدت خفاجة، ونهَبوا سواد الكوفة والحلة، فأسرى إليهم الأميرُ قيصر، شحنةَ الحلة، في مائتين وخمسين فارسًا، وخرج إليه أرغش في عسكر وسلاح، فانتزحت خفاجة من بين أيديهم، وتبعهم العسكرُ إلى رحبة الشام، فأرسل خفاجة يعتذرون و"},{"id":2089,"era":"c6","t":"تمرد أهل غرناطة على الموحدين بتحريض من ابن مردنيش  .","s":"كانت غرناطة لعبد المؤمن، فأرسل أهلُها إلى الأمير إبراهيم بن همشك صهر ابن مردنيش فاستدعوه إليهم؛ ليسلموا إليه البلد؛ وكان قد وحَّدَ- صار من أتباع الموحدين- ومن أصحاب عبد المؤمن، وفي طاعته، وممن يحرِّضُه على قتل ابن مردنيش. ثم فارق طاعة عبد المؤمن وعاد إلى موافقة ابن مردنيش. فامتنعوا بحصنها، فبلغ الخبر أبا سعيد عثمان بن عبد المؤمن وهو بمدينة مالقة، فجمع الجيش الذي كان عنده وتوجَّه إلى غرناطة لنصرة م"},{"id":2090,"era":"c6","t":"فتنة جماعة من عبيد مكَّةَ في الحجِّ بمنى .","s":"وصل الحُجَّاج إلى منى، ولم يتمَّ الحجُّ لأكثر الناس؛ لصَدِّهم عن دخول مكة والطواف والسعي، فمن دخل يومَ النحر مكَّةَ وطاف وسعى كَمُل حجه، ومن تأخر عن ذلك مُنِعَ دخولَ مكَّةَ؛ لفتنةٍ جرت بين أمير الحاجِّ وأمير مكة، كان سببُها أن جماعة من عبيد مكَّةَ أفسدوا في الحاجِّ بمنى، فنفَرَ عليهم بعضُ أصحاب أمير الحاج، فقتلوا منهم جماعة، ورجعَ مَن سلم إلى مكة، وجمعوا جمعًا وأغاروا على جمالِ الحاجِّ، وأخذوا منه"},{"id":2091,"era":"c6","t":"ملك الخليفة العباسي المستنجد قلعة الماهكي .","s":"مَلَكَ الخليفةُ المستنجد بالله قلعة الماهكي، وسببُ ذلك أنَّ سنقر الهمذاني، صاحبها، سلَّمَها إلى أحد مماليكه ومضى إلى همذان، فضَعُف هذا المملوك عن مقاومة ما حولها من الغزِّ الأتراك التركمان والأكراد، فأشيرَ عليه ببيعها على الخليفةِ، فراسل في ذلك، فاستنزله المستنجِدُ عنها بخمسة عشر ألف دينار وسلاحٍ وغير ذلك من الأمتعة، وعِدَّة من القرى، فسلَمَّها واستلم ما استقَرَّ له، وأقام ببغداد، وهذه القلعة لم ت"},{"id":2092,"era":"c6","t":"الحرب بين المسلمين والكرج وهم الجورجيون، سكان جورجيا .","s":"اجتمعت الكرج في خلقٍ كثير يبلغون ثلاثين ألف مقاتل، ودخلوا بلاد الإسلام، وقصدوا مدينةَ دوين من أذربيجان، فملكوها ونَهَبوها، وقتلوا من أهلِها وسوادها نحوَ عشرة آلاف قتيل، وأخذوا النساءَ سبايا، وأسَرُوا كثيرًا، وأعرَوُا النساءَ وقادوهم حُفاةً عُراةً، وأحرقوا الجوامِعَ والمساجِدَ، فلما وصلوا إلى بلادهم أنكر نساءُ الكرج ما فعلوا بنساءِ المسلمين، وقُلْنَ لهم قد أحوجتُم المسلمين أن يفعلوا بنا مثلَ ما فعل"},{"id":2093,"era":"c6","t":"خلع السلطان محمود ملك خراسان .","s":"قَصَد السلطانُ محمود بن محمد الخان، وهو ابن أخت السلطان سنجر، مَلِك خراسان بعده. سار محمود لحصار المؤيَّد أي أبه صاحب نيسابور بشاذياخ، وكان الغز الأتراك (التركمان) مع السلطان محمود، فدامت الحربُ إلى سنة 556, ثم إن محمودًا أظهر أنَّه يريدُ دُخولَ الحمَّام، فدخل إلى شهرستان، آخر شعبان، كالهارب من الغز، وأقاموا على نيسابورَ إلى آخرِ شوال، ثم عادوا راجعين، فعاثُوا في القرى ونَهَبوها، ونهبوا طوس نهبًا "},{"id":2094,"era":"c6","t":"إجلاء بني أسد أهل الحلة المزيدية الشيعة من العراق .","s":"أمر الخليفة المستنجد بالله بإهلاك بني أسد أهل الحلة المزيدية الشيعة؛ لِما ظهَرَ مِن فسادهم، ولما كان في نفس الخليفة منهم من مساعدتهم السلطان محمدًا لَمَّا حصر بغداد، فأمر يزدن بن قماج بقتالهم وإجلائهم عن البلاد، وكانوا منبسطين في البطائح، فلا يُقدر عليهم، فتوجه يزدن إليهم، وجمع عساكر كثيرة من راجل وفارس، وأرسل إلى ابن معروف مُقدم المنتفق، وهو بأرض البصرة، فجاء في خلق كثير فحصرهم وسَدَّ عليهم الماء"},{"id":2095,"era":"c6","t":"انهزام نور الدين محمود زنكي من الفرنج .","s":"انهزم نور الدين محمود بن زنكي من الفرنج، تحت حصن الأكراد، وهي الوقعة المعروفة بالبقيعة، وسببُها أن نور الدين جمع عساكِرَه ودخل بلاد الفرنج، ونزل في البقيعة تحت حصن الأكراد، محاصرًا له عازمًا على قصد طرابلس ومحاصرتها، فبينما الناس يومًا في خيامِهم وسط النهار، لم يَرُعْهم إلا ظهور صلبان الفرنج من وراء الجبل الذي عليه حِصن الأكراد، وذلك أن الفرنجَ اجتمعوا واتَّفَق رأيهم على كبسة المسلمين نهارًا، فإنّ"},{"id":2096,"era":"c6","t":"وفاة عبد المؤمن بن علي ملك الموحدين بالمغرب والأندلس .","s":"هو سلطان المغرب الملقب بأمير المؤمنين، عبد المؤمن بن علي بن علوي الكومي، القيسي، المغربي التلمساني. وُلِدَ بأعمال تلمسان، سنة 487, وكان أبوه يصنع الفخار. كان أبيضَ جميلًا، تعلوه حُمرة، أسود الشعر، معتدل القامة، جَهْوري الصوت، فصيحًا جَزلَ المَنطِق، لا يراه أحدٌ إلَّا أحَبَّه بديهةً، وكان في كِبَره شَيخًا وقورًا، أبيض الشعر، كثَّ اللحية، واضِحَ بياض الأسنان، وكان عظيمَ الهامة، طويل القعدة، غليظَ ال"},{"id":2097,"era":"c6","t":"إجلاء القارغلية من من بلاد ما وراء النهر .","s":"كان خان خانان الصيني ملك الخطا قد فوَّض ولاية سمرقند وبخارى إلى الخان جغري خان بن حين تكين، واستعمله عليها، وهو مِن بيت الملك، قديم الأبوة، فبقي فيها مدبِّرًا لأمورها، فلما كان الآن أرسل إليه ملك الخطا بإجلاء الأتراك القارغلية من أعمال بخارى وسمرقند إلى كاشغر، وأن يتركوا حمل السلاح ويشتغلوا بالزراعة وغيرها من الأعمال، فتقدم جغري خان إليهم بذلك، فامتنعوا، فألزمهم وألحَّ عليهم بالانتقال، فاجتمعوا وص"},{"id":2098,"era":"c6","t":"غارة الأمير محمد بن أنز الإسماعيلية بخراسان .","s":"أغار الأمير محمد بن أنز صاحب قهستان على بلد الإسماعيلية بخراسان وأهلها غافلون، فقَتَل منهم وغَنِم وسبى وأكثَرَ، وملأ أصحابه أيديهم من ذلك."},{"id":2099,"era":"c6","t":"خروج ملك الروم من القسطنطينية وهزيمته أمام المسلمين التركمان .","s":"خرج مَلِكُ الروم من القسطنطينية في عساكِرَ لا تحصى، وقَصَدَ بلاد الإسلام التي بِيَدِ قلج أرسلان وابن دانشمند، فاجتمع الغز الأتراك التركمان في تلك البلاد في جمعٍ كبير، فكانوا يُغيرون على أطرافِ عَسكَرِه ليلًا، فإذا أصبَحَ لا يرى أحدًا، وكثُرَ القتل في الروم حتى بلغت عِدَّةُ القتلى عشراتِ ألوف، فعاد إلى القُسطنطينية، ولما عاد مَلَك المسلمونَ منه عِدَّة حصون."},{"id":2100,"era":"c6","t":"حملة نور الدين محمود زنكي على مصر .","s":"سيَّرَ نور الدين محمود بن زنكي عسكرًا كثيرًا إلى مصر، وجعل عليهم الأميرَ أسد الدين شيركوه بن شاذي، وهو مُقَدَّم عسكره، وأكبَرُ أمراء دولته، وأشجعُهم، وكان سبب إرسال هذا الجيش أنَّ شاور السعديَّ- وزيرَ العاضد لدين الله العُبَيدي، صاحِبِ مِصرَ- نازعه في الوزارة ضرغام، وغَلَبَ عليها، فهرب شاور منه إلى الشام، ملتجئًا إلى نور الدينِ ومُستجيرًا به، فأكرَمَ مثواه، وأحسَنَ إليه، وأنعم عليه، وكان وصولُه في"},{"id":2101,"era":"c6","t":"نور الدين زنكي يهزم الصليبيين في موقعة أرتاح ويفتح قلعة تل حارم .","s":"فتح نور الدين محمود بن زنكي قلعة حارم من الفرنج؛ وسببُ ذلك أن نور الدين لَمَّا عاد منهزمًا من البقيعة، تحت حصن الأكراد، مِن قبلُ، واتَّفَق مسير بعض الفرنج مع مَلِكِهم في مصر، فأراد أن يقصِدَ بلادهم ليعودوا عن مصرَ، فأرسل إلى أخيه قطب الدين مودود، صاحِبِ الموصل وديار الجزيرة، وإلى فخر الدينِ قرا أرسلان، صاحبِ حصن كيفا، وإلى نجمِ الدين ألبي، صاحبِ ماردين، وغيرِهم من أصحاب الأطراف يستنجِدُهم؛ فأما قط"},{"id":2102,"era":"c6","t":"ملك نور الدين محمود بن زنكي قلعة بانياس من الفرنج .","s":"فتَحَ نور الدين محمود قلعة بانياس، وهي بالقُرب من دمشق، وكانت بيد الفرنج من سنة 543، وكان نور الدين لما فتح حارم أذن لعسكر الموصل وديار بكر بالعود إلى بلادهم، وأظهر أنه يريدُ طبرية، فجعل من بقي من الفرنج همَّتَهم حفظَها وتقويتَها، فسار محمود إلى بانياس لعِلْمِه بقلة من فيها من الحُماة الممانعين عنها، ونازلها، وضَيَّقَ عليها وقاتَلَها، وجَدَّ في حصارها، فسمع الفرنج، فجَمَعوا، فلم تتكاملْ عِدَّتُهم،"},{"id":2103,"era":"c6","t":"وفاة شاه مازندران رستم واستيلاء ابنه على الملك من بعده .","s":"هو رستم بن علي بن شهريار بن قارن. ملك مازندران. كان ملكًا شجاعًا مخوفًا، استولى على بسطام وقومس، واتَّسعت ممالكه، وكان شيعيًّا شديد التشيع, غزا بلاد ألموت فأوطأ الإسماعيلية ذلًّا، وخَرَّب بلادهم، وسبى النساء والأولاد، وغنم، وخُذلت الإسماعيلية في أيامه، وخُرِّبَت عامة قراهم. توفي في ثامن ربيع الأول، ولَمَّا توفي كتم ابنه الحسن بن علاء الدين موتَه أيامًا، حتى استولى على سائر الحصون والبلاد، ثم أظهره"},{"id":2104,"era":"c6","t":"الحروب بين أمراء السلاجقة .","s":"نشبَت الحرب بين قليج أرسلان بن مسعود صاحِبِ قونية، وبين ياغي بسان بن دانشمند صاحِبِ ملاطية، وكان سبب هذه الحرب أنَّ قليج أرسلان تزوج ابنة سلدق بن علي بن أبي القاسم صاحب أرزروم، فسيرت العروس إلى قليج مع جهاز كبير، فأغار ياغي على مسيرة العروس واختطفها وما معها، وأمَرَها بالردَّةِ عن الإسلام لينفَسِخَ زواجُها من قليج أرسلان، ففعلت ثم عادت للإسلامِ؛ ليزوجها ياغي من ابن أخيه، فلما علم قليج بذلك جمع عسا"},{"id":2105,"era":"c6","t":"حصار الإسماعلية لقزوين .","s":"بنى الإسماعيلية قلعةً بالقرب من قزوين، فقيل لشمس الدين إيلدكز عنها، فلم يكنْ له إنكار لهذه الحالِ؛ خوفًا مِن شَرِّهم وغائلتهم، فتقَدَّموا بعد ذلك إلى قزوين فحصروها، وقاتلهم أهلُها أشدَّ قتال رآه الناس."},{"id":2106,"era":"c6","t":"وقوع قتال بسبب التعصب المذهبي في أصفهان .","s":"وقعَت بأصفهان فتنةٌ عظيمة بين صدر الدين عبد اللطيف بن الخجندي رئيس الشَّافعية بأصفهان وبين أصحاب المذاهبِ الأخرى، بسبب التعصب للمذاهب، فدام القتالُ بين الطائفتين ثمانيةَ أيام مُتَتابعةً قُتل فيها خلق كثير، واحترق وهُدم كثيرٌ من الدور والأسواق، ثم افترقوا على أقبحِ صورةٍ."},{"id":2107,"era":"c6","t":"فتح نور الدين محمود زنكي حصن المنيطرة من الشام .","s":"فتَحَ نورُ الدين محمود بن زنكي حِصنَ المنيطرة من الشام، وكان بيد الفرنج، ولم يحشِدْ له، ولا جمَعَ عساكِرَه، وإنما سار إليه جريدة- الجريدة خَيْلٌ لا رَجَّالة فيها- على غِرَّة منهم، وعَلِمَ أنه إن جمع العساكِرَ حَذِروا وجمعوا، وانتهز الفرصةَ وسار إلى المنيطرة وحصره، وجَدَّ في قتاله، فأخذه عَنوةً وقهرًا، وقتل من بها وسبى، وغَنِمَ غنيمة كثيرة، فإنَّ الذين به كانوا آمنين، فأخذتهم خيل الله بغتةً وهم لا "},{"id":2108,"era":"c6","t":"وفاة الشريف الإدريسي الجغرافي الأندلسي الكبير .","s":"هو الشَّريفُ أبو عبد الله محمد بن محمد بن عبد الله بن إدريس بن يحيى بن علي الحمودي الحَسني الطالبي الإدريسي. ولد بمدينة سبتة وتعلَّم بقُرطبة، خرج إلى المشرق وطاف البلاد، أقام في بلاد الإسلام وعاد إلى المغربِ. كان أديبًا ظريفًا شاعرًا مُغرمًا بعلم الجغرافيا. أقام بصقليَّةَ في بلاط الملك النورماندي روجيه الثاني الذي كان من هواة الفلك، فألَّفَ له الإدريسي كتابَ نزهة المشتاق في اختراق الآفاق، وهو في و"},{"id":2109,"era":"c6","t":"وفاة عبدالقادر الجيلاني .","s":"هو الزاهِدُ، صاحِبُ الكرامات والمقامات، شيخُ الحنابلة أبو محمد عبد القادر بن أبي صالح موسى بن عبد الله بن يحيى الزاهد الهاشمي القرشي العلوي الجيلي الحنبلي. ولد بجيلان سنة 470 وقيل 471. دخل بغداد سنة ثمان وثمانين، وله ثماني عشرة سنة، فقرأ الفقهَ على: أبي الوفاء بن عقيل، وأبي الخطاب، وأبي سعد المخرمي، وأبي الحسين بن الفراء، حتى أحكم الأصولَ، والفروع، والخلاف, وسمع الحديث، ومدرسته ورباطه مشهوران ببغد"},{"id":2110,"era":"c6","t":"نور الدين محمود زنكي ينتزع عددا من الحصون من الصليبيين .","s":"جمع نور الدين محمود العساكر، فسار إليه أخوه قطب الدين من الموصل وغيره، فاجتمعوا على حمص، فدخل نور الدين بالعساكر بلاد الفرنج، فاجتازوا حصنَ الأكراد، وقصدوا عرقةَ فنازلوها وحصروها، وقصدوا حلبة وأخذوها، وفتحوا العريمةَ وصافيثا، وعادوا إلى حمص فصاموا بها رمضان، ثم ساروا إلى بانياس، وقصَدوا حِصنَ هونين، وهو للفرنجِ أيضًا، من أمنَعِ حصونهم ومعاقِلِهم، فانهزم الفرنجُ عنه وأحرقوه، فوصل نور الدين من الغدِ"},{"id":2111,"era":"c6","t":"مقاتلة أسد الدين شيركوه للفرنجة بمصر وفتح الإسكندرية .","s":"أقبَلَت الفرنج في جحافِلَ كثيرة إلى الديار المصرية، وساعدهم المصريون فتصَرَّفوا في بعض البلاد، فبلغ ذلك أسدَ الدين شيركوه، فاستأذن الملك نور الدين محمود في العود إليها، وكان كثيرَ الحنق على الوزير شاوِر السعدي، فتجهَّزَ وسار في ربيع الآخر في جيشٍ قويٍّ، وسَيَّرَ معه نور الدين جماعة من الأمراء، فلما اجتمع معه عسكرُه سار إلى مصر على البَرِّ، وترك بلاد الفرنج على يمينه، فوصل الديار المصرية، فقصد أطفي"},{"id":2112,"era":"c6","t":"الحرب بين البهلوان وصاحب مراغة .","s":"أرسل آقسنقر الأحمديلي، صاحب مراغة، إلى بغداد يسأل أن يخطب للملك الذي هو عنده، وهو ولد السلطان محمد شاه، ويبذل أنه لا يطأ أرض العراق، ولا يطلب شيئًا غير ذلك، وبذل مالًا يحمله إذا أجيب إلى ما التمسه، فأجيب بتطييب قلبه، وبلغ الخبر إيلدكز صاحِبَ البلاد، فساءه ذلك، وجهَّزَ عسكرًا كثيفًا، وجعل المقدَّمَ عليهم ابنَه البهلوان، وسيَّرَهم إلى آقسنقر، فوقعت بينهم حربٌ أجْلَت عن هزيمةِ آقسنقر وتحصُّنه بمراغة،"},{"id":2113,"era":"c6","t":"قتال بين خفاجة وجيش بغداد .","s":"وفيها أفسدت خفاجة في البلاد ونهَبوا القرى، فخرجَ إليهم جيش من بغداد فهربوا في البراري فانحسر الجيشُ عنهم خوفًا من العطش، فكَرُّوا على الجيش فقتلوا منهم خلقًا، وأسروا آخرين، وكان قد أسر الجيش منهم خلقًا، فصُلِبوا على الأسوار."},{"id":2114,"era":"c6","t":"نهاية دولة بني زيري في الجزائر وتونس  .","s":"لحق الحسنُ بن يحيى آخِرُ ملوك بني زيري بعد استيلاءِ النصارى على المهدية، بالعَرَبِ مِن رياح، وكبيرُهم محرز بن زياد الفادعي صاحِبُ القلعة، فلم يجِدْ لديهم مصرخًا، وأراد الرحيل إلى مصر للحافظ عبد المجيد الفاطمي, لكنَّه ارتحل إلى المغرب، وأجاز إلى بونة وبها الحارث بن منصور وأخوه العزيز. ثم توجه إلى قسنطينة وبها سبع بن العزيز أخو يحيى صاحب بجاية، فبعث إليه من أجازه إلى الجزائر. ونزل على ابن العزيز فأح"},{"id":2115,"era":"c6","t":"حماية نور الدين محمود زنكي لشاور من أسد الدين شيركوه .","s":"بعث شاور إلى نور الدين محمود رسالةً مع شهاب الدين محمود، خال صلاح الدين الأيوبي، تتضمن أنه يحمل إليه مالًا في كل سنة من مصر مصانعةً؛ ليصرف عنه أسد الدين شيركوه، فأجاب نور الدين إلى ذلك، وأعطى شيركوه مدينة حمص وأعمالها زيادةً على ما كان بيده، وأمره بترك ذكر مصر، فأرسل شاور إليه كتابًا يشكر صنيعَه."},{"id":2116,"era":"c6","t":"ملك نور الدين محمود زنكي قلعة جعبر .","s":"ملَكَ نورُ الدين محمود بن زنكي قلعةَ جعبر، أخذها من صاحبها شهاب الدين ملك بن علي بن مالك العقيلي، وكانت بيده ويد آبائه مِن قَبلِه من أيام السلطان ملك شاه، وهي من أمنَعِ القلاع وأحصَنِها، مطلة على الفرات من الجانب الشرقي. وأمَّا سبب ملكها فإن صاحِبَها نزل منها يتصيد، فأخذه بنو كلاب وحملوه إلى نور الدين في رجب سنة 563، فاعتقله وأحسنَ إليه، ورغَّبَه في المال والإقطاع ليُسَلِّمَ إليه القلعة، فلم يفعل،"},{"id":2117,"era":"c6","t":"فتح مصر على يد أسد الدين شيركوه  .","s":"في ربيع الأول، سار أسد الدين شيركوه بن شاذي إلى ديار مصر، فمَلَكَها ومعه العساكر النورية، وسَبَبُ ذلك تمكُّن الفرنج من البلاد المصرية، وأنهم جعلوا لهم في القاهرة شحنةً وتسَلَّموا أبوابها، وجعلوا لهم فيها جماعةً من شجعانهم وأعيان فرسانهم، وحكَموا المسلمين حكمًا جائرًا، ورَكِبوهم بالأذى العظيم، فعَمِلوا أيضًا على تجهيز الجيوش لتمَلُّك مصر كلها، وشرعوا يتجهَّزون ويُظهِرون أنَّهم يريدون قصد مدينة حمص،"},{"id":2118,"era":"c6","t":"اغتيال شاور بن مجير السعدي وزير العاضد العبيدي (الفاطمي) .","s":"هو مَلِك الديار المصرية ووزيرُها أبو شجاع شاور بن مجير بن نزار بن عشائر السعدي، الهوازني. يرجع نسبه إلى أبي ذؤيب عبد الله والد حليمة السعدية مرضعة رسول الله صلى الله عليه وسلم. كان الملك الصالحُ طلائع بن رزيك الرافضي وزيرُ العاضد قد ولَّاه إمرة الصعيد، ثم نَدِمَ على توليته حيث لا ينفع الندم. ثم إن شاوِر تمكن في الصعيد، وكان شجاعًا فارسًا شهمًا، وكان الصالح لما احتُضِرَ قد وصى ولده رزيك ألَّا يتعرض"},{"id":2119,"era":"c6","t":"صلاح الدين الأيوبي يسيطر على مصر .","s":"لما توفي أسد الدين شيركوه كان معه صلاح الدين بن أخيه أيوب بن شاذي قد سار معه على كُرهٍ منه للمسير، وأما كيفيَّة ولايته، فإنَّ جماعة من الأمراء النورية الذين كانوا بمصر طلبوا التقدُّمَ على العساكر، وولاية الوزارة العاضدية بعده، منهم عينُ الدولة الياروقي، وقطب الدين، وسيف الدين المشطوب الهكاري، وشهاب الدين محمود الحارمي، وهو خالُ صلاح الدين، وكُلُّ واحد من هؤلاء يخطُبها، وقد جمع أصحابه ليغالَ عليها،"},{"id":2120,"era":"c6","t":"وفاة أسد الدين شيركوه مؤسس الوجود الأيوبي بمصر .","s":"هو الملك المنصور أبو الحارث أسد الدين شيركوه بن شاذي بن مروان عم صلاح الدين, وأصلُه من الأكراد الروادية، وهذا النَّسلُ هم أشرف الأكراد. كان شاوِر وزيرَ العاضد العُبيدي, فقدم إلى الشام يستنجِدُ بنور الدين سنة 559 على خَصِمه ضرغام. فسير معه جماعة من عسكره، وجعل مُقَدَّمَهم أسدَ الدين شيركوه، وقَدِموا مصر، وغدر بهم شاوِر ولم يفِ بما وعدهم به، فعادوا إلى دمشق، ثم عاد شيركوه إلى مصر في شهر ربيع الأول س"},{"id":2121,"era":"c6","t":"وقعة السودان بمصر .","s":"في أوائل ذي القعدة قُتِلَ مؤتمن الخلافة، وهو خصِيٌّ كان بقصرِ العاضد، إليه الحُكم فيه، والتقدُّم على جميع من يحويه، فاتَّفَق هو وجماعة من المصريين على مكاتبة الفرنج واستدعائهم إلى البلاد، والتقَوِّي بهم على صلاح الدين ومَن معه، وسَيَّروا الكتب مع إنسانٍ يثقون به، وأقاموا ينتَظِرون جوابه، وسار ذلك القاصدُ إلى البئر البيضاء، فلَقِيه إنسان تركماني، فرأى معه نعلين جديدين، فأخذهما منه وقال في نفسه: لو "},{"id":2122,"era":"c6","t":"غزوةٌ لسريةٍ نورانيَّةٌ مباركة .","s":"كان شهابُ الدين إلياس بن إيلغازي بن أرتك، صاحب قلعة البيرة، قد سار في عسكره، وهو في مائتي فارس، إلى نور الدين وهو بعشترا، فلما وصل إلى قرية اللبوة، وهي من عمل بعلبك، رَكِبَ متصَيِّدًا، فصادف ثلاثمائة فارس من الفرنج قد ساروا للإغارة على بلاد الإسلام سابع عشر شوال، فوقع بعضُهم على بعض، واقتتلوا واشتَدَّ القتال، وصبَرَ الفريقان لا سيما المسلمون، فإنَّ ألف فارس لا يصبرون لحملة ثلاثمائة فارس إفرنجية، و"},{"id":2123,"era":"c6","t":"الحرب بين يوسف بن عبد المؤمن وابن مردنيش بالأندلس .","s":"كان محمد بن سعيد بن مردنيش، ملك شرق الأندلس، قد اتفق هو والفرنج، وامتنع على عبد المؤمن وابنه يوسف من بعده، فاستفحل أمرُ ابن مردنيش، لا سيَّما بعد وفاة عبد المؤمن، فلمَّا كان هذه السَّنةَ جَهَّزَ إليه يوسفُ بن عبد المؤمن العساكِرَ الكثيرةَ مع أخيه عُمَرَ بنِ عبد المؤمن، فجاسوا بلادَه وخَرَّبوها، وأخذوا مدينتينِ مِن بلاده، وأخافوا عساكِرَ جنودِه، وأقاموا ببلادِه مُدَّةً يتنقَّلون فيها ويَجبُون الأمو"},{"id":2124,"era":"c6","t":"محاصرة الفرنجة لدمياط ورجوعهم عنها .","s":"تحرَّكَ الفرنج لغزو ديار مصرَ؛ خوفًا من صلاح الدين ونور الدين محمود زنكي عندما بلغهم تمكُّنُه من ديار مصر وقطعُ آثار جند المصريين. فكاتبوا فرنجَ صقلية وغيرهم واستنجدوا بهم، فأمدوهم بالمالِ والسلاح والرجال، وساروا بالدبابات والمنجنيقات إلى دمياط، فنزلوا عليها في مستهَلِّ صفر بألف ومائة مركب، ما بين شين ومسطح وشلندي وطريدة، وأحاطوا بها برًّا وبحرًا، فأسرع صلاح الدين إلى دمياط وتحصَّنَ فيها، كما قام "},{"id":2125,"era":"c6","t":"حصار نور الدين محمود لكرك .","s":"أرسل صلاح الدين إلى نور الدين يطلُبُ أن يرسِلَ إليه والِدَه نجم الدين أيوب، فجَهَّزه نور الدين وسَيَّرَه، وسيَّرَ معه عسكرًا، واجتمع معه من التجار خلق كثير، وانضاف إليهم من كان له مع صلاح الدين أُنس وصحبة، فخاف نور الدين عليهم من الفرنجِ، فسار في عساكره إلى الكرك، فحصَرَه وضيَّقَ عليه ونصب عليه المجانيق، فأتاه الخبَرُ أن الفرنج قد جمعوا له، وساروا إليه، وقد جعلوا في مقدمتهم إليه ابن هنفري وقريب بن"},{"id":2126,"era":"c6","t":"وفاة قطب الدين مودود بن عماد الدين زنكي .","s":"هو قطبُ الدين مودود بن زنكي بن آقسنقر، المعروفُ بالأعرج صاحِبُ الموصل، وقد كان من أحسن الملوك سيرةً، وأعفِّهم عن أموال رعيَّته، مُحسِنًا إليهم، كثيرَ الإنعام عليهم، محبوبًا إلى كبيرهم وصغيرهم، عطوفًا على شريفهم ووضيعهم، كريمَ الأخلاق، حسَنَ الصحبة معهم, سريعَ الانفعال للخير، بطيئًا عن الشَّرِّ، جمَّ المناقب، قليلَ المعايب.  تولى قطب الدين السلطنةَ بالموصل بعد موت أخيه سيف الدين غازي بن زنكي, وكان "},{"id":2127,"era":"c6","t":"ملك نور الدين محمود زنكي الرقة ونصيبين والخابور وسنجار .","s":"لَمَّا بلغ نور الدين محمودًا وفاةُ أخيه قطب الدين مودود، صاحِبِ الموصل، ومُلك ولده سيف الدين غازي الموصِلَ والبلاد التي كانت لأبيه، بعد وفاته، وقيام فخر الدين عبد المسيح بالأمرِ معه، وتحكُّمه عليه؛ أنِفَ لذلك وكَبِرَ لديه وعَظُمَ عليه، وكان يُبغِضُ فخر الدين؛ لما يبلغه عنه من خشونةِ سياسته، فقال: أنا أولى بتدبير أولاد أخي ومُلكِهم، وسار عند انقضاء العزاء جريدة في قلة من العسكر، وعبر الفرات، عند قل"},{"id":2128,"era":"c6","t":"وفاة الخليفة العباسي المستنجد بالله وخلافة ابنه المستضيء بأمر الله .","s":"هو الخليفةُ، المستنجد بالله، أبو المظفر يوسف بن المقتفي لأمر الله محمد بن المستظهر بن المقتدي العباسي. أمُّه كرجية اسمُها طاووس. عقد له أبوه بولاية العهد في سنة سبع وأربعين، وعمره يومئذ تسع وعشرون سنة. فلما احتُضِر المقتفي، رام طائفة عزل المستنجد، وبعثت حَظِيَّة المقتفي أم علي إلى الأمراء تعدهم وتمنيهم؛ ليبايعوا ابنَها علي بن المقتفي. قالوا: كيف هذا مع وجود ولي العهدِ يوسف؟ فقالت أنا أكفيكموه، فدب"},{"id":2129,"era":"c6","t":"غزو صلاح الدين الأيوبي بلاد الفرنج وفتح إيلة .","s":"سار صلاحُ الدين عن مصر إلى بلاد الفرنج، فأغار على أعمال عسقلان والرملة، وهجمَ على ربض غزة فنهَبه، وأتاه ملك الفرنج في قِلَّةٍ مِن العسكر مسرعين لرَدِّه عن البلاد، فقاتلهم وهزمهم، وأفلت ملكُ الفرنج بعد أن أشرف أن يؤخَذَ أسيرًا. عاد صلاحُ الدين إلى مصر، وعَمِلَ مراكب مفصلة، وحملها قطعًا على الجبال في البر، وقصَدَ إيلة، فجمع قطع المراكب وألقاها في البحر، وحصر إيلة برًّا وبحرًا، وفتحها في العشر الأُوَ"},{"id":2130,"era":"c6","t":"صلاح الدين الأيوبي يبدأ بإصلاح مصر وإزالة التشيع منها .","s":"كان بمصر دار للشحنة تُسمَّى دار المعونة يُحبَسُ فيها من يريد حبسه، فهدمها صلاح الدين، وبناها مدرسة للشافعية، وأزال ما كان بها من الظُّلم، وبنى دار العدل مدرسة للشافعية أيضًا، وبنى مدرسة أخرى للمالكية، وعزل القضاة المصريين، وكانوا شيعةً، وأقام قاضيًا شافعيًا في مصر، وولَّى قضاء القضاة بها لصدر الدين عبد الملك بن درباس المارداني الشافعي، فاستناب في سائر المعاملات قُضاة شافعية، ومن حينئذ اشتهر مذهبُ "},{"id":2131,"era":"c6","t":"غضب نور الدين زنكي من صلاح الدين الأيوبي والصلح بينهما .","s":"كان سببُه أن صلاح الدين يوسف بن أيوب سار عن مصر في صفر إلى بلاد الفرنج غازيًا، ونازل حصن الشوبك، وبينه وبين الكرك يوم، وحصره، وضيَّقَ على مَن به من الفرنج، وأدام القتال، وطلبوا الأمانَ واستمهلوه عشرة أيام، فأجابهم إلى ذلك، فلما سمع نور الدين بما فعله صلاح الدين سار عن دمشق قاصدًا بلاد الفرنج؛ ليدخل إليها من جهة أخرى، فقيل لصلاح الدين: إن دخل نور الدين بلاد الفرنج وهم على هذه الحال: أنت من جانب ونو"},{"id":2132,"era":"c6","t":"قطع صلاح الدين الأيوبي الخُطبة للفاطميين والدُّعاء للعباسيين .","s":"قام صلاح الدين الأيوبي بقَطعِ الخُطبة للحاكم الفاطمي بمصر، والدُّعاء للخليفة العباسي \"المستضيء\" على منابر مصر، معلنًا بذلك نهاية الدولة الفاطمية، ومُعَبِّرًا عن طاعته وولائه للخليفة العباسي."},{"id":2133,"era":"c6","t":"صلاح الدين الأيوبي يؤسس دولة الأيوبيين ويقضي على العبيديين .","s":"لما مات العاضد غَسَّله ابنه داود وصلى عليه، وجلس على الشدَّة، واستدعى صلاح الدين ليبايعَه، فامتنع، وبعث إليه: أنا نائبٌ عن أبيك في الحُكم ولم يوصِ بأنَّك وليُّ عهده، وقبَضَ عليه وعلى بقيَّةِ أولاد العاضد وأقاربه، ونقله هو وجميع أقاربه وأهله إلى دار المظفر من حارة برجوان، ووكل عليهم وعلى جميع ذخائر القصر، وفَرَّق بين الرجال والنساء حتى لا يحصُلَ منهم نسل. وأُغلِقَت القصور وتُمُلِّكَت الأملاك التي ك"},{"id":2134,"era":"c6","t":"وفاة العاضد بالله آخر حكام العبيديين الفاطميين بمصر .","s":"هو صاحِبُ مصرَ العاضد لدين الله خاتم الدولة العُبيدية: أبو محمد عبد الله بن الأمير يوسف بن الحافظ لدين الله عبد المجيد بن محمد بن المستنصر، العبيدي الحاكمي المصري الإسماعيلي المُدَّعي هو وأجدادُه أنهم فاطميون. ولد سنة 546. وليَ الحُكمَ بعد وفاة ابن عمه الفائز، وكان أبوه يوسف أحد الأخوين اللذين قتلهما عباس بعد الظافر، واستقر الأمر للعاضد اسمًا، والصالحُ بن رزيك الرافضي كان المتحكِّمَ في الحكم. كان "},{"id":2135,"era":"c6","t":"وفاة السلطان علاء الدين خوارزم شاه تكش .","s":"هو السلطانُ علاءُ الدين خوارزم شاه تكش بن الملك أرسلان شاه بن أطسز، وقيل: هو من ولد طاهر بن الحسين, كان ملكًا مشهورًا، عنده آدابٌ وفضائلُ، ومعرفةٌ بمذهبِ أبي حنيفة، وبنى مدرسةً بخوارزم للحنفيَّةِ، وكان شُجاعًا جوادًا، ملَكَ الدنيا من السِّندِ والهندِ وما وراء النهرِ إلى خراسانَ إلى بغدادَ؛ فإنَّه كان نوَّابُه في حلوان. وكان في ديوانه مائةُ ألف مقاتل، وهو الذي كسر مملوكُه عسكرَ الخليفةِ وأزال دولةَ"},{"id":2136,"era":"c6","t":"وصول الترك إلى إفريقية وملكهم طرابلس وغيرها .","s":"سارت طائفةٌ مِن الترك من ديارِ مِصرَ مع قراقوش مملوكِ تقي الدين عمر بن أخي صلاح الدين يوسف بن أيوب، إلى جبال نفوسة، واجتمع بمسعود بن زمام المعروف بمسعود البلاط، وهو من أعيان العرب هناك، وكان خارجًا عن طاعة عبدِ المؤمن وأولاده، فاتفقا، وكثُرَ جمعهما، ونزلا على طرابلس الغرب فحاصراها وضَيَّقا على أهلها، ثم فُتِحَت فاستولى قراقوش، وأسكن أهلَه قصرها، وملك كثيرًا من بلاد إفريقية ما خلا المهدية وصفاقس وق"},{"id":2137,"era":"c6","t":"غزو ابن عبد المؤمن الفرنج بالأندلس .","s":"جمع أبو يعقوب يوسف بن عبد المؤمن عساكِرَه، وسار من إشبيلية إلى الغزو، فقصد بلاد الفرنج، ونزل على مدينة رندة، وهي بالقرب من طليطلة شرقًا منها، وحصرها، واجتمعت الفرنجُ على بن الأذفونش ملك طليطلة في جمع كثير، فلم يَقدِروا على لقاء المسلمين، فاتَّفَق أن الغلاء اشتدَّ على المسلمين، وعَدِمت الأقوات عندهم، وهم في جمع كثير، فاضطُروا إلى مفارقة بلاد الفرنج، فعادوا إلى إشبيلية، وأقام أبو يعقوب بها سنة 571، "},{"id":2138,"era":"c6","t":"غاره الفرنج على بلد حوران وغارة المسلمين على بلد الفرنج .","s":"اجتمع الفرنج وساروا إلى بلد حوران من أعمال دمشق للغارة عليه، وبلغ الخبر إلى نور الدين محمود، وكان قد برز ونزل هو وعسكره بالكسوة، فسار إليهم مجدًّا، وقَدِمَ بجموعه عليهم، فلما عَلِموا بقُربه منهم دخلوا إلى السواد، وهو من أعمال دمشق أيضًا، ولحِقَهم المسلمون وتخَطَّفوا مَن في ساقتهم ونالوا منهم، وسار نور الدين فنزل في عشترا، وسيَّرَ منها سرية إلى أعمال طبرية، فشنُّوا الغارات عليها، فنَهَبوا وسَبَوا، "},{"id":2139,"era":"c6","t":"رحيل صلاح الدين الأيوبي عن مصر إلى الكرك وعوده عنها .","s":"رحَلَ صلاح الدين يوسف بن أيوب من مصر بعساكِرِه جميعِها إلى بلاد الفرنج يريدُ حَصرَ الكرك، والاجتماع مع نور الدين محمود والاتِّفاق على قصد بلاد الفرنج من جِهَتينِ، كل واحد منهما في جهة بعسكرِه، وسبب ذلك أنَّ نور الدين لَمَّا أنكر على صلاح الدين عَودَه من بلاد الفرنج في العام الماضي، وأراد نور الدين قَصْدَ مصر وأخْذَها منه، أرسل يعتذر، ويَعِدُ من نفسه بالحركةِ على ما يقَرِّرُه نور الدين، فاستقَرَّت "},{"id":2140,"era":"c6","t":"موقف صلاح الدين من نزاع آل زنكي بعد وفاة نور الدين محمود .","s":"لَمَّا سار سيفُ الدين غازي، صاحِبُ الموصل، ومَلَك البلادَ الجزريَّةَ، أرسل صلاح الدين أيضًا إلى المَلِك الصالح يعتبُه حيث لم يُعلِمْه قصد سيف الدين بلادَه وأخْذَها، ليحضُرَ في خدمته ويكُفَّ سيف الدين، وكتب إلى كمالِ الدين والأمراء يقول: \"لو أنَّ نور الدين يعلَمُ أنَّ فيكم من يقومُ مقامي، أو يثِقُ به مِثلَ ثِقتِه بي، لسلم إليه مصر التي هي أعظَمُ ممالكه وولاياته، ولو لم يُعجِّلْ عليه الموت لم يعهَدْ"},{"id":2141,"era":"c6","t":"الفتنة ببغداد بين قطب الدين قايماز والخليفة .","s":"كانت الفتنةُ ببغدادَ بين أمير العسكَرِ قطب الدين قايماز المظفري والخليفةِ المستضيء بأمرِ الله، وسَبَبُها أنَّ الخليفة أمرَ بإعادة عَضدِ الدين ابن رئيس الرؤساءِ إلى الوزارة، فمنع منه قُطب الدين، وأغلق بابَ النوبي وباب العامة، وبقيت دار الخليفة كالمحاصَرة، فأجاب الخليفةُ إلى تَركِ وَزارته، فقال قطب الدين: \"لا أقنَعُ إلا بإخراج عضد الدينِ مِن بغداد؛ فأمر بالخروجِ منها\" فالتجأ عضدُ الدين إلى صدر الدين"},{"id":2142,"era":"c6","t":"النفوذ الأيوبي يصل إلى اليمن ونهاية دولة بني مهدي وبني زريع .","s":"لما عاد صلاحُ الدين إلى مصرَ بلَغَه أنَّ باليمن إنسانًا يسمَّى عبدَ النبي بن مهدي صاحِبَ زبيد يزعُمُ أنه ينتشر ملكُه حتى يملِكَ الأرضَ كُلَّها، وكان قد ملك كثيرًا من بلادِ اليمَنِ, واستولى على حصونِها وخطب لنَفسِه، وقطع الخطبةَ للخليفةِ العباسي, وكان السُّلطانُ قد ثبتت قواعِدُه وقَوِيَ عسكرُه، فاستأذن السلطان نور الدين محمود في أن يسيرَ إلى اليمن لقصدِ عبد النبي، فأذِنَ له في ذلك، فجهَّز أخاه شمس "},{"id":2143,"era":"c6","t":"إحباط ثورة الشيعة الفاطميين على صلاح الدين الأيوبي بمصر .","s":"أراد جماعةٌ مِن شيعة العُبَيديين ومحبِّيهم إقامةَ الدعوة، ورَدَّها إلى العاضد، فكان منهم عمارةُ بنُ أبي الحسن اليمني، وعبدُ الصمد الكاتب، والقاضي العويرس، والقاضي هبة الله بن كامل، وداعي الدُّعاة ابن عبد القوي، وغيرُهم من جند المصريِّين ورجالتهم السُّودان، وحاشيةُ القصر، ووافَقَهم جماعةٌ من أمراءِ صلاح الدين، وعَيَّنوا الخليفةَ والوزير، وتقاسَموا الدُّورَ، واتَّفَق رأيُهم على استدعاء الفرنجِ مِن ص"},{"id":2144,"era":"c6","t":"وفاة نور الدين زنكي صاحب الشام وتولي ابنه الصالح إسماعيل .","s":"هو المَلِكُ العادِلُ، ناصِر أمير المؤمنين، تقيُّ الملوك، ليثُ الإسلام، أبو القاسِم نور الدين محمود بن الأتابك قسيم الدولة أبي سعيد زنكي بن الأمير الكبير آقسنقر التركي، السلطاني، الملكشاهي. ولِيَ جدُّه آقسنقر نيابةَ حَلَب للسلطان ملكشاه بن ألب آرسلان السلجوقي. وُلِدَ نور الدين يوم الأحد سابع عشر شوال سنة 511؛ وكان أسمَرَ اللَّونِ طويلَ القامةِ حَسَنَ الصورة، ليس بوجهِه شَعرٌ سوى ذقنه. كان ملكًا عاد"},{"id":2145,"era":"c6","t":"حصر الفرنج بانياس وعودهم عنها .","s":"لما مات نورُ الدين محمود زنكي، صاحِبُ الشام، اجتمعت الفرنجُ وساروا إلى قلعة بانياس من أعمال دمشق فحصروها، فجمع شمسُ الدين محمد بن المقدم الوصيُّ على الملك الصالح بن نور الدين محمود العسكرَ عنده بدمشق، فخرج عنها، فراسَلَهم، ولاطَفَهم، ثم أغلظ لهم بالقول، وقال لهم: إن أنتم صالحتُمونا وعدتُم عن بانياس، فنحن على ما كنَّا عليه، وإلا فنُرسِلُ إلى سيف الدين، صاحِبِ الموصل، ونصالِحُه، ونستنجده، ونرسِلُ إل"},{"id":2146,"era":"c6","t":"نزاع آل زنكي وأمرائهم على ملك بلدان الشام بعد وفاة نور الدين .","s":"كان نور الدين قبل أن يمرَضَ قد أرسل إلى البلاد الشرقيَّة- الموصل وديار الجزيرة وغيرها- يستدعي العساكِرَ منها للغَزاة، والمراد غيرها، وقد تقدَّمَ ذِكرُه، فسار سيفُ الدين غازي بن قطب الدين مودود بن زنكي، صاحب الموصل، في عساكره، وعلى مُقَدِّمتِه الخادم سعد الدين كمشتكين الذي كان قد جعله نورُ الدين بقلعة الموصل مع سيف الدين، فلما كانوا ببعضِ الطريق وصلت الأخبار بوفاة نور الدين، فأمَّا سعد الدين فإنَّه"},{"id":2147,"era":"c6","t":"وصول أسطول صقلية إلى الإسكندرية وانهزامه عنها .","s":"ظَفِرَ أهلُ الإسكندرية وعسكَرُ مصرَ بأسطولِ الفِرنجِ مِن صقليَّةَ، وكان سبَبُ ذلك إرسالَ أهل مصر إلى ملك الفرنج بساحلِ الشَّامِ، وإلى صاحبِ صقليَّةَ، ليَقصِدوا ديارَ مِصرَ ليثُوروا على صلاحِ الدين ويُخرجوه من مصر، فجَهَّزَ صاحبُ صقلية أسطولًا كبيرًا، وسَيَّرَه إلى الإسكندرية من ديار مصر، فوصلوا إليها في التاسع والعشرين من ذي الحجة سنة 569، على حينِ غَفلةٍ مِن أهلها وطمأنينةٍ، فخرج أهل الإسكندرية ب"},{"id":2148,"era":"c6","t":"محاولة فاشلة لإعادة الدولة العبيدية الفاطمية في مصر .","s":"جمع كَنزُ الدولة والي أسوان العَرَبَ والسودانَ، وقَصَد القاهرةَ يريدُ إعادةَ الدولة الفاطمية، وأنفق في جموعه أموالًا جزيلة، وانضم إليه جماعةٌ ممَّن يهوى هواهم، فقَتَلَ عدَّةً من أمراء صلاح الدين، وخرج في قريةِ طود رجلٌ يُعرَفُ بعباس بن شادي، وأخذ بلادَ قوص، وانتهب أموالَها، فجهز السلطانُ صلاح الدين أخاه المَلِكَ العادل في جيشٍ كثيف، ومعه الخطيرُ مهذب بن مماتي، فسار وأوقع بشادي وبدَّدَ جموعَه وقتَل"},{"id":2149,"era":"c6","t":"صلاح الدين الأيوبي يستولي على دمشق .","s":"ملكَ صلاحُ الدِّينِ يوسف بن أيوب مدينةَ دمشق، وسبَبُ ذلك أنَّ نور الدين لَمَّا مات ومَلَك ابنُه المَلِكُ الصالح إسماعيلُ بعده كان بدمشق، ولَمَّا استولى سيفُ الدين غازي بن قطب الدين مودود صاحِب الموصل وعَمِّ الملك الصالح إسماعيل على البلاد الجزرية، خاف شمس الدين علي بن الداية-وهو أكبر الأمراء النورية- أن يُغيرَ إلى حلب فيَملِكَها، فأرسل الخادمَ سعد الدين كمشتكين إلى دمشق لِيُحضِرَ الملك الصالح ومعه"},{"id":2150,"era":"c6","t":"ملك صلاح الدين الأيوبي حمص  .","s":"لَمَّا استقَرَّ مُلك صلاح الدين لدمشق، وقرَّر أمْرَها، استخلَفَ بها أخاه سيفَ الإسلام طغتكين بن أيوب، وسار إلى مدينة حمص مستهَلَّ جمادى الأولى، وكانت حمص وحماة وقلعة بعين وسلمية وتل خالد والرها من بلد الجزيرة في أقطاعِ الأمير فخر الدين مسعود الزعفراني، فلمَّا مات نور الدين لم يُمكِن فخر الدين المقامُ بها لسوء سيرتِه في أهلها، ولم يكُنْ له في قلاعِ هذه البلاد حُكمٌ، إنما فيها ولاة لنور الدين. وكان "},{"id":2151,"era":"c6","t":"ملك صلاح الدين الأيوبي حماة .","s":"سار صلاحُ الدين إلى مدينةِ حماة، وهو في جميعِ أحوالِه لا يُظهِرُ إلَّا طاعةَ الملكِ الصالحِ بنِ نور الدين محمود، فلما وصَلَ إلى حماة، مَلَك المدينةَ مُستهَلَّ جمادى الآخرة، وكان بقلعتِها الأميرُ عزُّ الدين جورديك، وهو من المماليك النوريَّة، فامتنع من التسليمِ إلى صلاحِ الدين، فأرسل إليه صلاحُ الدينِ ما يُعَرِّفه ما هو عليه من طاعةِ المَلِك الصالح، وإنما يريدُ حِفظَ بلادِه عليه، فاستحلَفَه جورديك ع"},{"id":2152,"era":"c6","t":"محاولة صلاح الدين الأيوبي في السيطرة على حلب .","s":"لَمَّا مَلَك صلاحُ الدين حماة سارَ إلى حَلَب فحَصَرها ثالثَ جُمادى الآخرة، فقاتَلَه أهلُها، ورَكِبَ الملك الصالحُ، وهو صبيٌّ عُمُرُه اثنتا عشرة سنة، وجمع أهلَ حَلَب واتفقوا على القتالِ دُونَه، والمنع عن بلده، وجَدُّوا في القتال، وأرسل سعدُ الدين كمشتكين إلى سنان مقدَّم الإسماعيليَّة، وبذَلَ له أموالًا كثيرةً؛ ليقتلوا صلاح الدين، فأرسلوا جماعةً منهم إلى عسكَرِه، فحمل أحدُهم على صلاح الدين ليقتُلَه،"},{"id":2153,"era":"c6","t":"ملك صلاح الدين الأيوبي قلعة حمص وبعلبك .","s":"أثناءَ حِصار صلاحِ الدين الأيوبي لحَلَب بلَغَه مسيرُ الفرنجِ إلى حمص وتجهُّزُهم لِقَصدِها، فرحل عن حَلَب إلى حماة، فوصله ثامِنَ رَجَب، بعد نزول الفرنجِ على حمص بيومٍ، ثم رحل إلى الرستن، فلمَّا سَمِعَ الفرنجُ بقُربِه رَحَلوا عن حمص، ووصل صلاحُ الدين إليها، فحصر القلعةَ إلى أن ملكها في الحادي والعشرين من شعبان، فصار أكثَرُ الشام بيده، ولَمَّا ملك حمص سار منها إلى بعلبك، وبها خادِمٌ اسمه يمن، وهو وال"},{"id":2154,"era":"c6","t":"ملك صلاح الدين الأيوبي قلعة بعرين من الشام .","s":"في العَشرِ الأُوَل من شوال مَلَك صلاحُ الدين قلعةَ بعرين من الشَّامِ، وكان صاحِبُها فخر الدين مسعود بن الزعفراني، وهو مِن أكابر الأمراءِ النوريَّة، فلما رأى قوَّةَ صلاح الدين نزل منها، واتَّصل بصلاح الدين، ظنَّ أنَّه يُكرِمُه ويُشارِكُه في ملكه، ولا ينفَرِدُ عنه بأمرٍ مِثل ما كان مع نور الدين، فلم يَرَ مِن ذلك شيئًا، ففارَقَه، ولم يكن بَقِيَ من أقطاعه الذي كان له في الأيامِ النورية غيرُ بعرين ونائ"},{"id":2155,"era":"c6","t":"وفاة ابن عساكر صاحب تاريخ دمشق .","s":"هو الإمامُ العلَّامةُ، الحافِظُ الكبيرُ المجَوِّد، مُحَدِّثُ الشام، ثِقةُ الدين، أبو القاسم علي بن الحسن بن هبة الله بن عبد الله بن الحسين المعروف بابن عساكر، الدمشقي الشافعي صاحب (تاريخ دمشق). من أعيانِ الفُقَهاء الشافعيَّة، ومُحَدِّث الشام في وقته. غَلَب عليه الحديثُ فاشتَهَر به وبالَغَ في طلبه إلى أن جمعَ منه ما لم يتَّفِق لغَيرِه، حتى صار أحدَ أكابر حُفَّاظ الحديث ومن عُنِيَ به سَماعًا وجمعًا "},{"id":2156,"era":"c6","t":"انتصار صلاح الدين الأيوبي على سيف الدين غازي بن نور الدين .","s":"تجهَّز الحلبيُّون لقتال صلاح الدين، فاستدعى صلاحُ الدين عساكر مصر، فلما وافته بدمشقَ في شعبان سار في أوَّل رمضان، فلَقِيَهم في عاشر شوال، وكانت بينهما وقعةٌ تأخَّرَ فيها السلطان سيف الدين غازي بن نور الدين محمود صاحِبُ الموصل، فظَنَّ الناس أنَّها هزيمة، فولَّت عساكرهم، وتَبِعَهم صلاح الدين، فهلك منهم جماعةٌ كثيرة، وملك خيمةَ غازي، وأسر عالَمًا عظيمًا، واحتوى على أموالٍ وذخائر وفُرُش وأطعمة وتُحَف "},{"id":2157,"era":"c6","t":"ملك صلاح الدين الأيوبي مدينة منبج .","s":"سار صلاحُ الدين إلى بزاعة فحصرها، وقاتَلَه مَن بالقلعة، ثم تسلَّمَها وجعل بها من يحفَظُها، وسار إلى مدينة منبج فحصَرها آخِرَ شوال، وبها صاحِبُ قطب الدين ينال بن حسان المنبجي، وكان شديدَ العداوة لصلاح الدين والتَّحريضِ عليه، والإطماع فيه، والطَّعن فيه، فحَنِقَ عليه صلاح الدين وهَدَّده، ثم مَلَك منبج، ولم تمتنِعْ عليه إلا قلعَتُها وبها صاحِبُها اسمه ينال، قد جمع إليها الرجال والذخائر والسلاح، فحصره "},{"id":2158,"era":"c6","t":"وقوع فتنة ببغداد بين العامة وبعض الأتراك .","s":"وقَعَت يومَ عيد الأضحى فتنةٌ ببغداد، بين العامَّةِ وبعضِ الأتراك؛ بسَبَبِ أخْذِ جِمالِ النحر، فقُتِلَ بينهم جماعةٌ، ونُهِبَ شَيءٌ كثير من الأموال، ففَرَّق الخليفةُ أموالًا جليلةً فيمن نُهِب مالُه."},{"id":2159,"era":"c6","t":"صلاح الدين الأيوبي يسيطر على قلعة إعزاز ونجاته من محاولة اغتيال .","s":"ولَمَّا فَرَغ صلاح الدين من منبج سار إلى قلعة إعزاز، فنازلها ثالثَ ذي القعدة، وهي من أحصَنِ القلاع وأمنَعِها، فنازلها وحَصَرها، وأحاط بها وضَيَّقَ على من فيها ونَصَب عليها المجانيقَ، حتى فتحها وقُتِل عليها كثيرٌ من العسكر. فبينما صلاح الدين يومًا في خيمةٍ لأحد أمرائه يقال له جاولي، وهو مُقَدَّم الطائفة الأسدية، إذ وثب عليه باطنيٌّ إسماعيليٌّ فضَرَبه بسكينٍ في رأسِه فجَرَحه، فلولا فضلُ الله ثمَّ إن"},{"id":2160,"era":"c6","t":"حصر صلاح الدين الأيوبي مدينة حلب .","s":"لَمَّا ملك صلاح الدين إعزازَ رحل إلى حلب فنازلها منتصَفَ ذي الحجة وحَصَرَها، وبها الملك الصالح إسماعيل بن نور الدين محمود ومَن معه من العساكِرِ، وقد قام العامَّةُ في حفظِ البَلَدِ القيامَ المَرضِيَّ، بحيث إنَّهم منعوا صلاح الدين من القُربِ مِن البلد، لأنَّه كان إذا تقدم للقتال خَسِرَ هو وأصحابُه، كَثُرَ الجراح فيهم والقَتلُ، كانوا يخرجُون ويقاتلونه خارج البلد، فترك القتالَ وأخلدَ للمطاولة، وانقَضَ"},{"id":2161,"era":"c6","t":"الفتنة بمكة وعزل أميرها وإقامة غيره .","s":"كان بمكَّةَ حَربٌ شديدةٌ بين أمير الحاجِّ طاشتكين وبين الأمير مُكثِر أمير مكة، وكان الخليفةُ قد أمر أميرَ الحاج بعَزلِ مُكثر وإقامة أخيه داود مقامَه، وسبَبُ ذلك أنه كان قد بنى قلعةً على جبل أبي قُبَيس، فلما سار الحاجُّ من عرفة لم يبيِّتوا بالمُزدَلفة، وإنما اجتازوا بها، فلم يَرمُوا الجمار، إنَّما بَعضُهم رمى بعضَها وهو سائِرٌ، ونزلوا الأبطُحَ فخرج إليهم ناسٌ مِن أهل مكة فحاربوهم، وقُتِلَ من الفريق"},{"id":2162,"era":"c6","t":"صلاح الدين الأيوبي يبني سورا ضخما لحماية القاهرة .","s":"أمَرَ السُّلطانُ الناصِرُ صلاح الدين الأيوبي ببناء السُّورِ على القاهرةِ والقَلعةِ، طولُه تسعة وعشرون ألف ذراع وثلاثمائة وذراعان بالذراع الهاشمي، فتولى ذلك الأميرُ بهاء الدين قراقوش الأسدي، وشرعَ في بناء القلعة، وحَفَرَ حول السور خندقًا عميقًا، وحفر واديَه وضَيَّقَ طريقه، وكان في مكانِ القلعة عِدَّةُ مساجد، منها مسجد سعد الدولة، فدخلت في جملةِ القلعة، وحَفَر فيها بئرًا ينزل إليها بدَرَجٍ منحوتة في"},{"id":2163,"era":"c6","t":"بناء مدرسة صلاح الدين الأيوبي للشافعية .","s":"أمرَ النَّاصِرُ ببناء مدرسةِ صلاح الدين للشافعيَّة عند قبرِ الشافعيِّ، وجعل الشيخَ نجم الدين الخبوشاني مُدَرِّسَها وناظِرَها."},{"id":2164,"era":"c6","t":"ظفر المسلمين بالفرنج والفرنج بالمسلمين .","s":"كان شَمسُ الدين محمَّدُ بنُ عبد الملك بن المقَدَّم صاحب بعلبك، قد أتاه خبَرُ أنَّ جمعًا من الفرنجِ قد قَصَدوا البِقاعَ من أعمال بعلبك، وأغاروا عليها، فسار إليهم، وكَمَن لهم في الشعاري والغياض، وأوقع بهم، وقَتَل فيهم وأكثَرَ، وأسَرَ نحو مائتي رجل منهم وسَيَّرَهم إلى صلاح الدين، وكان شمسُ الدولة توران شاه، أخو صلاح الدين، وهو الذي مَلَك اليمن، قد وصل إلى دمشق، وهو فيها، فسَمِعَ أن طائفة من الفرنج قد"},{"id":2165,"era":"c6","t":"مسير صلاح الدين الأيوبي إلى بلد الإسماعيلية وحصارهم .","s":"لَمَّا رحَلَ صَلاحُ الدين من حلب، قصدَ بلادَ الإسماعيليَّة في مصياف؛ ليقاتِلَهم بما فعلوه من الوثوبِ عليه وإرادة قتلِه، وحصر قلعةَ مصياف، وهي أعظمُ حصونِهم، وأحصَنُ قلاعِهم، فنصَبَ عليها المجانيقَ، وضيَّقَ على مَن بها، فنَهَب بلَدَهم وخَرَّبه وأحرَقَه، فقَتَل وسبى وحرَّق، وأخذ أبقارَهم، ولم يزَلْ كذلك، فأرسل سنان مُقَدَّم الإسماعيلية إلى شهابِ الدين الحارمي، صاحِبِ حماة، وهو ابنُ خال صلاح الدين، ي"},{"id":2166,"era":"c6","t":"وفاة القاضي كمال الدين محمد الشهرزوري الموصلي .","s":"هو الإمامُ، قاضي القضاة أبو الفضل كمال الدين محمد بن عبد الله بن القاسم الشهرزوري، الفقيه الموصلي الشافعي، بقيَّةُ الأعلام. وُلِدَ سنة 491, وكان والدُه أحد علماء زمانه يُلقَّب: بالمرتضى. لَمَّا قُتِلَ عماد الدين زنكي عند قلعةِ جعبر كان كمال الدين حاضرًا في العسكر هو وأخوه تاج الدين أبو طاهر يحيى، فلما رجع العسكَرُ إلى الموصل كانا في صُحبتِه, ولَمَّا تولى سيفُ الدين غازي بن عماد الدين زنكي فوَّضَ ا"},{"id":2167,"era":"c6","t":"الفتنة ببغداد مع اليهود .","s":"حضر قَومٌ مِن مُسلِمي المدائِنِ إلى بغداد، فشَكَوا من يهودِها، وقالوا: لنا مسجِدٌ نؤذِّنُ فيه ونصَلِّي، وهو مجاورُ الكنيسة، فقال لنا اليهودُ: قد آذيتُمونا بكثرةِ الأذان، فقال المؤذِّنُ: ما نبالي بذلك، فاختَصَموا، وكانت فتنةٌ استظهر فيها اليهودُ، فجاء المسلمون يشكونَ منهم، فأمَرَ ابنُ العطار، وهو صاحِبُ المخزن، بحَبسِهم، ثم أُخرِجوا، فقصدوا جامِعَ القصر، واستغاثوا قبلَ صلاةِ الجُمعةِ، فخَفَّف الخطي"},{"id":2168,"era":"c6","t":"حصر الفرنج مدينة حماة .","s":"حصَرَ الفرنجُ مدينةَ حماة، وسَبَبُ ذلك أنَّه وصل من البحرِ إلى الساحل الشامي كند- يعني قائد-  كبيرٌ من الفرنج من أكبر طواغيتِهم، فلما رأى أنَّ صلاح الدين قد عاد منهزمًا لمصرَ، اغتنم خلو البلاد؛ لأنَّ توران شاه بن أيوب كان بدمشق ينوبُ عن أخيه صلاح الدين ليس عنده كثيرٌ من العسكَرِ، وكان أيضًا كثيرَ الانهماك في اللذَّاتِ مائلًا إلى الرَّاحات، فجمع ذلك الكند الفرنجيُّ مَن بالشام من الفرنج، وفَرَّقَ في"},{"id":2169,"era":"c6","t":"انهزام صلاح الدين الأيوبي في الرملة .","s":"في أواخِرِ جمادى الأولى، سار صلاح الدين يوسف بن أيوب من مصرَ إلى ساحل الشامِ؛ لقصد بلاد الفرنج، وجمع معه عساكِرَ وجنودًا كثيرة، فلم يزالوا يجِدُّون السيرَ حتى وصلوا عسقلان في الرابع والعشرين منه، فنَهَبوا وأسروا، وقتلوا وأحرقوا وتفَرَّقوا في تلك الأعمال مُغِيرينَ، فلما رأَوا أنَّ الفِرنجَ لم يَظهَرْ لهم عسكَرٌ ولا اجتمع لهم من يحمي البلادَ مِن المسلمين، طَمِعوا، وانبسطوا، وساروا في الأرض آمنين مطم"},{"id":2170,"era":"c6","t":"مقتل سعد الدين كمشتكين .","s":"قَبَض الملكُ الصالِحُ إسماعيلُ بنُ نور الدين على سعدِ الدين كمشتكين، وكان المتولِّيَ لأمر دولته والحاكِمَ فيها؛ وسَبَبُ قَبضِه أنَّه اتُّهِم بالسعيِ لقتل أبي صالح بن العجمي، الذي كان بمنزلةِ الوزير الكبير المتمكِّن، وكان قد وثب به الباطنيَّةُ فقتلوه وتمكَّنَ بعده سعد الدين وقَوِيَ حاله، فلما قُتِلَ ابن العجمي أحال الجماعةُ قتله على سعد الدين، وقالوا: هو وضَعَ الباطنية عليه حتى قتلوه، وذكروا ذلك لل"},{"id":2171,"era":"c6","t":"حصر الفرنج قلعة حارم .","s":"لما رأى الفرنج الخلافَ الذي في  قلعةِ حارم وقَتْل الملك الصالحِ صاحِبَها سعد الدين كمشتكين، ساروا إلى حارم من حماة في جمادى الأولى، ظنًّا منهم أنَّهم لا ناصِرَ لهم، وأنَّ الملك الصالح صبيٌّ قليل العسكر، وصلاحُ الدين بمصر، فاغتنموا هذه الفرصةَ ونازلوها وأطالوا المقامَ عليها مدة أربعة أشهر، ونَصَبوا عليها المجانيقَ والسلالم، فلم يزالوا كذلك إلى أن بذل لهم المَلِكُ الصالح مالًا، وقال لهم: إنَّ صلاح ا"},{"id":2172,"era":"c6","t":"صلاح الدين الأيوبي يسقط المكوس والضرائب عن الحجيج .","s":"أسقط صلاحُ الدين المكوسَ والضرائب عن الحُجَّاج بمكة، وقد كان يُؤخَذُ مِن حجاج الغربِ شَيءٌ كثيرٌ، ومن عجز عن أدائه حُبِسَ، فربما فاته الوقوفُ بعرفة، وعَوَّضَ أميرَ مكَّةَ بمالٍ أقطَعَه إياه بمصر، وأن يحمِلَ إليه في كلِّ سَنةٍ ثمانية آلاف أردب إلى مكة، ليكون عونًا له ولأتباعه، ورِفقًا بالمجاورين، وقُرِّرَت للمجاورين أيضًا غلَّات تُحمَلُ إليهم"},{"id":2173,"era":"c6","t":"بناء قلعة الجبل الضخمة بالقاهرة .","s":"أمر المَلِكُ الناصر صلاحُ الدين ببناء قلعة الجبلِ، وإحاطة السور على القاهرة ومصر، فعَمرَ قلعة للملك لم يكُنْ في الديار المصرية مثلُها ولا على شكلها، ووليَ عمارة ذلك الأميرُ بهاء الدين قراقوش مملوكُ تقي الدين عمر بن شاهنشاه بن أيوب."},{"id":2174,"era":"c6","t":"حدوث زلزلة شديدة ببغداد .","s":"هبَّت ببغداد ريحٌ عظيمة، ثم زَلَزلت الأرض، واشتَدَّ الأمرُ على الناس حتى ظَنُّوا أنَّ القيامةَ قد قامت، فبَقِيَ ذلك ساعة ثم انجَلَت، وقد وقع كثيرٌ من الدور، ومات فيها جماعةٌ كثيرة."},{"id":2175,"era":"c6","t":"وفاة الوزير أبو الفرج بن المظفر  .","s":"هو محمَّدُ بن عبد الله بن هبة الله بن المظفَّر، الوزير أبو الفرج ابنُ رئيس الرؤساء، ولَقَبُه عضد الدولة. وكان أبوه أستاذ دار المقتفي وأقرَّه المستنجد. فلمَّا ولي المستضيء استوزره، فشرع ظهيرُ الدين بن العطَّار أبو بكر صاحب المخزن في عداوة أبي الفرج، حتَّى غيَّر قلب الخليفة عليه، فطلب الحجَّ فأذِنَ له، فتجهَّزَ جهازًا عظيمًا واشترى ستَّمائة جمل لحَملِ المنقطعينَ وزادِهم، وحمل معه جماعةً من العلماء و"},{"id":2176,"era":"c6","t":"عصيان ابن المقدم على صلاح الدين الأيوبي وحصر بعلبك .","s":"عصى شمسُ الدين محمد بن عبد الملك المقَدَّم على صلاح الدين ببعلبك، وكانت له قد سَلَّمَها إليه صلاحُ الدين لَمَّا فَتَحَها جزاءً له حيث سَلَّمَ إليه ابن المقدم دمشق، فلم تَزَلْ بيده إلى الآن، فطلب شمسُ الدولة بن أيوب أخو صلاح الدين منه بعلبك، وألحَّ عليه في طلبها، فلم يتمكَّنْ صلاح الدين من مخالفته، فأمر شمس الدين بتسليمِها إلى أخيه ليعَوِّضَه عنها، فلم يُجِبْ إلى ذلك، وذَكَّرَه العهود التي له، وما "},{"id":2177,"era":"c6","t":"الغلاء والوباء العام .","s":"انقطعت الأمطارُ بالكليَّةِ في سائِرِ البلاد الشاميَّة والجزيرة والبلاد العراقية، والديار البكريَّة، والموصل وبلاد الجَبَل وخلاط، وغير ذلك، واشتدَّ الغلاء، وكان عامًا في سائرِ البلاد، واستسقى الناسُ في أقطار الأرض، فلم يُسقَوا، وتعَذَّرَت الأقوات، وأكَلَت الناس الميتةَ وما ناسَبَها، ودام كذلك إلى آخِرِ سنة خمس وسبعين؛ ثم تَبِعَه بعد ذلك وباءٌ شديد عامٌّ أيضًا، كَثُرَ فيه الموت، وكان مَرَضُ الناس شي"},{"id":2178,"era":"c6","t":"عودة الفرنج إلى مدينة حماة .","s":"سار جمعٌ كثيرٌ مِن الفرنج بالشَّامِ إلى مدينة حماة، وكَثُرَ جَمعُهم من الفرسان والرجَّالة؛ طمعًا في النهب والغارة، فشَنُّوا الغارة، ونَهَبوا وخَرَّبوا القرى، وأحرَقوا وأسروا وقَتَلوا، فلما سمع العسكرُ المقيم بحماة ساروا إليهم، وهم قليل، متوكلينَ على الله تعالى، فالتقوا واقتتلوا، وصدق المسلمونَ القتال، فنصرهم الله تعالى، وانهزم الفرنج، وكَثُرَ القتل والأسرُ فيهم، واستردُّوا منهم ما غَنِموه من السوا"},{"id":2179,"era":"c6","t":"وفاة الشاعر الحيص بيص شهاب الدين أبو الفوارس .","s":"هو الأميرُ شِهابُ الدين، أبو الفوارِسِ سَعدُ بن محمد بن سعد بن صيفي التميمي الأديب الفقيه الشافعي، المعروف بالحيص بيص, ومعنى الحيص بيص: الشِّدَّةُ والاختلاطُ, قيل: إنَّه رأى الناسَ في شدَّة وحركةٍ، فقال: ما للنَّاسِ في حيصَ بَيصَ؟ فلزِمَه ذلك. وكان من فضلاءِ العالَم. كان قد سمع الحديثَ، ومدح الخلفاءَ والسلاطين والأكابر، وشِعرُه مشهورٌ، وله (ديوان) وترَسُّل. كان فصيحًا حسَن الشعر, بليغًا وافِرَ الأ"},{"id":2180,"era":"c6","t":"غارات الفرنج على بلاد المسلمين في الشام .","s":"اجتمع الفِرنجُ وساروا إلى بلدِ دِمشقَ مع ملكهم، فأغاروا على أعمالِها فنهبوها وأسَروا وقَتَلوا وسَبَوا، فأرسل صلاحُ الدين فرخشاه، ولد أخيه، في جمعٍ من العسكر إليهم، وأمره إذا قاربهم يرسِلُ إليه يخبره على جناحِ طائر ليسير إليه، وتقدَّمَ إليه أن يأمُرَ أهل البلاد بالانتزاحِ مِن بين يدي الفرنج، فسار فرخشاه في عسكره يطلُبُهم، فلم يشعُرْ إلا والفرنجُ قد خالطوه، فاضطرَّ إلى القتال، فاقتتلوا أشدَّ قتال رآ"},{"id":2181,"era":"c6","t":"وفاة علم بنت عبد الله أم المبارك  .","s":"توفِّيَت الزاهدةُ العابدةُ علم بنت عبد الله بن هبة الله أم المبارك. امرأة صالحة واعظة، زوجةُ محمد بن يحيى الزبيدي الواعِظ، تزوجها بدمشق ثم قَدِمَت معه بغداد, وكانت تضاهي رابعة العدويَّة في زمانها، وقد عمرت طويلًا، توفيت ببغداد، وعمرها مائة سنة وستُّ سنين، ولم يتغيَّرْ لها شيء من حواسِّها."},{"id":2182,"era":"c6","t":"وقعة مرج عيون بين الفرنجة والسلطان صلاح الدين .","s":"سار السُّلطانُ صلاح الدِّين من عكَّا إلى دمشق، فأقام بها ثم خرج إلى شقيف- وهي في موضع حصين- فخَيَّم في مرجِ عُيون بالقُربِ منه، وأقام أيامًا يباشِرُ القتال- والعساكر تتواصل إليه- فلمَّا تحقَّقَ أرناط صاحِبُ شقيف أنَّه لا طاقة له به، نزل إليه بنفسه، فلم يشعُرْ به إلَّا وهو قائمٌ على باب خيمته، فأذِنَ له في دخوله إليه، وأكرمه واحتَرَمه، وكان من أكابِرِ الفرنج وعُقَلائِهم، وكان يَعرِف بالعربيَّة وعند"},{"id":2183,"era":"c6","t":"تخريب المسلمين حصن الأحزان .","s":"كان الفرنجُ قد بَنَوا حِصنًا منيعًا يقارِبُ بانياس، عند بيت يعقوب، بمكان يُعرَف بمخاضة الأحزان؛ وقد حفروا فيه بئرًا وجعلوه لهم عينًا، وسلموه إلى الداوية، فلمَّا سمع صلاح الدين بذلك كتب إلى الفرنج يأمرهم بتخريبِ هذا الحصن الذي بنوه للداوية فامتنعوا إلا أن يبذُلَ لهم ما غرموه عليه، فبذل لهم ستين ألفَ دينار فلم يقبلوا، ثم أوصلهم إلى مائة ألف دينار، فقال له ابنُ أخيه تقي الدين عمر: ابذُلْ هذا إلى أجنا"},{"id":2184,"era":"c6","t":"وفاة الخليفة العباسي المستضيء بأمر الله وخلافة ولده الناصر .","s":"هو الخليفةُ، أبو محمد الحَسَن بن المستنجد بالله يوسف بن المقتفي محمد بن المستظهر أحمد بن المقتدي الهاشمي، العباسي المستضيء بأمر الله. ولِدَ سنة 536, وأمه أرمنية، اسمها غضة. بويع بالخلافة يوم موت أبيه، في ربيع الآخر، سنة 566، وقام بأمر البيعة عضد الدين أبو الفرج بن رئيس الرؤساء، فاستوزره يومئذ, وكان المستضيءُ ذا حِلمٍ وأناة ورأفةٍ وبِرٍّ وصدقات. قال ابن الجوزي: \"لَمَّا بويع نُودي برفع المكوس، وردِّ"},{"id":2185,"era":"c6","t":"قصد صلاح الدين الأيوبي بلاد الأرمن .","s":"قصد صلاحُ الدين بلَدَ ابنِ ليون الأرمني، وسَبَبُ ذلك أنَّ ابن ليون الأرمني قد استمال قومًا من التركمان وبذل لهم الأمانَ، فأمرهم أن يَرعَوا مواشِيَهم في بلاده، وهي بلاد حصينةٌ كلُّها حصون منيعة، والدخول إليها صعب؛ لأنها مضائق وجبال وَعِرة، ثم غدر بهم وسبى حريمَهم، وأخذ أموالهم، وأسرَ رجالهم بعد أن قَتَل منهم، فسار صلاح الدين على النَّهر الأسود، وبثَّ الغارات على بلاده، فخاف ابنُ ليون على حِصنٍ له ع"},{"id":2186,"era":"c6","t":"وفاة الحافظ أبي طاهر السِّلَفي .","s":"هو الإمامُ العلَّامة المحدِّث، الحافظ الكبيرُ المفتي شيخ الإسلام، شرف المعمرين، أبو طاهرٍ أحمد بن محمد بن أحمد بن محمد بن إبراهيم الأصبهاني، الجرواني السِّلَفي بكسر السين وفتح اللام. يلقب جَدُّه أحمد سِلفة- أي أشرم الشفة- وأصله بالفارسية سِّلبة، وكثيرًا ما يمزجون الباء بالفاء فسَمَّته الأعاجم لذلك السِّلَفي، والسَّلَفي -بفتحتين- وهو من كان على مذهَبِ السلف، وكان يلقب بصدر الدين، وكان شافعيَّ المذه"},{"id":2187,"era":"c6","t":"ملك يوسف بن عبد المؤمن مدينة قفصة بالمغرب .","s":"سار يوسُفُ بن عبد المؤمن إلى إفريقيَّةَ، وملك قفصة، وكان سبب ذلك أنَّ صاحِبَها علي بن عبد المعز بن المعتز لَمَّا رأى دخولَ الترك إلى إفريقيَّة واستيلاءهم على بعضها، وانقياد العرب إليهم؛ طَمِعَ أيضًا في الاستبدادِ والانفراد عن يوسف وكان في طاعته، فأظهر ما في نفسه وخالفه وأظهر العِصيان، ووافقه أهلُ قفصة، فقتلوا كلَّ من كان عندهم مِن الموحِّدين أصحابه، وكان ذلك في شوال سنة 572، فأرسل والي بجاية إلى ي"},{"id":2188,"era":"c6","t":"وفاة فخر الدين شمس الدولة توران شاه بن أيّوب .","s":"هو المَلِكُ المُعظَّم فخر الدين شمس الدولة توران شاه بن أيُّوب أخو السلطان صلاح الدين. كان أكبَرَ من صلاح الدين في السنِّ. وكان يرى في نفسه أنَّه أحقُّ بالمُلك من صلاح الدين يوسف، وكان يبدو منه كلامٌ يقدح في صلاح الدين وتبلغه عنه، ومع ذلك كان صلاح الدين يُحسِنُ إليه. شهد معه مواقِفَ مشهودة محمودة، وهو الذي افتتح بلادَ اليمن عن أمر صلاح الدين، فمكث فيها حينًا واقتنى منها أموالًا جزيلة، ثم عاد من ال"},{"id":2189,"era":"c6","t":"وفاة سيف الدين غازي صاحب الموصل وولاية أخيه عز الدين بعده .","s":"هو سيفُ الدينِ غازي بن الملك قطب الدين مودود بن أتابك زنكي بن آق سنقر التركي. صاحِبُ الموصِل ووالد سنجر شاه صاحِب جزيرة ابن عمر. لَمَّا مات أبوه قطب الدين، وهو على تلِّ باشر، وفي سنة ست وستين مَلَك الرقة، ونصيبين وسنجار، ثم أتى الموصِلَ، فأرسل إلى صاحبها وعَرَّفَه صحة قصده، فصالحه. ونزل الموصِلَ ودخلَها، وأقرَّ صاحبها فيها، وزوَّجَه بابنته، وعاد إلى الشام، فلما تملَّك صلاح الدين وسار إلى حلب وحاصر"},{"id":2190,"era":"c6","t":"غزو  الفرنج في الكرك من الشام .","s":"سار عز الدين فرخشاه نائب صلاح الدين بدمشق إلى أعمال الكرك ونَهَبها، وسببُ ذلك أن البرنس صاحب الكرك، كان من شياطين الفرنج ومَرَدتهم، وأشدِّهم عداوة للمسلمين، فتجهز وجمع عسكره ومن أمكنه الجمع، وعزم على المسيرِ في البر إلى تيماء، ومنها إلى مدينة النبيِّ صلى الله عليه وسلم، للاستيلاء على تلك النواحي الشريفة، فسَمِعَ فرخشاه ذلك، فجمع العساكِرَ الدمشقية وسار إلى بلده ونهبه وخربه، وعاد إلى طرف بلادِهم، و"},{"id":2191,"era":"c6","t":"إرسال صلاح الدين الأيوبي العساكر إلى اليمن .","s":"سَيَّرَ صلاحُ الدين جماعةً من أمرائه منهم صارم الدين قتلغ أبه- والي مصر- إلى اليمن؛ للاختلاف الواقع بها بين نواب أخيه شمس الدولة توران شاه، وهم عزُّ الدين عثمان بن الزنجيلي، والي عدن، وحطان بن منقذ، والي زبيد، وغيرهما؛ فإنهم لما بلغهم وفاةُ صاحبهم توران شاه اختلفوا وجَرَت بين عز الدين عثمان وبين حطان حربٌ، وكل واحد منهما يروم أن يغلِبَ الآخر على ما بيده، واشتد الأمرُ، فخاف صلاح الدين أن يطمَعَ أهل"},{"id":2192,"era":"c6","t":"حصر صاحب ماردين قلعة البيرة ومصير صاحبها مع صلاح الدين .","s":"كانت قلعةُ البيرة، وهي مُطِلَّة على الفرات من أرض الجزيرة، لشهاب الدين الأرتقي، وهو ابنُ عم قطب الدين إيلغازي بن ألبي بن تورتاش بن إيلغازي بن أرتق صاحب ماردين، وكان في طاعةِ نور الدين محمود بن زنكي، صاحِبِ الشام، فمات شهابُ الدين وملك القلعةَ بعده ولدُه وصار في طاعة عز الدين مسعود صاحب الموصل، فلما كان هذه السنة أرسل صاحِبُ ماردين إلى عز الدين مسعود يطلبُ منه أن يأذن له في حَصْرِ البيرة وأخْذِها، "},{"id":2193,"era":"c6","t":"وفاة الملك الصالح إسماعيل بن نور الدين صاحب حلب .","s":"هو أبو الفتوح الملك الصَّالح إسماعيلُ- صاحب حلب- بن نور الدين محمود بن الأتابك زنكي, وصى له والده محمود بمملكته وهو ابن إحدى عشرة سنة، فملَّكوه بدمشق، وحلفوا له بحلب، فأقبل صلاح الدين من مصر، وأخذ منه دمشق، فترحل إسماعيل إلى حلب، وكان شابًا ديِّنًا خَيِّرًا، عاقلًا بديع الجمال، محبَّبًا إلى الرعية وإلى الأمراء، ثم سار السلطان صلاح الدين، وحاصر حلب مُدَّةً، ثم ترحل عنها، ثم حاصرها، فصالحوه، وبذلوا "},{"id":2194,"era":"c6","t":"وفاة ابن الأنباري النحوي .","s":"هو أبو البركات كمال الدين عبد الرحمن بن محمد بن عبيد الله مصغر بن أبي سعيد بن سليمان الأنباري النحوي صاحب التصانيف المفيدة، من الأئمَّة المشار إليهم في علمِ النحو، وُلِدَ في شهر ربيع الآخر سنة 513, وسكن بغداد من صباه إلى أن مات، وتفقَّه على مذهب الشافعي، بالمدرسة النظامية وتصدَّر لإقراءِ النحو بها، وصار شيخَ العراق في الأدب غيرَ مُدافَع له. تولى التدريس في بغداد, وقَصَده طلابُ العلم من سائر الأقطا"},{"id":2195,"era":"c6","t":"إرسال سيف الإسلام الأيوبي إلى اليمن وتغلبه عليه .","s":"سَيَّرَ صلاح الدين أخاه سيف الإسلام طغتكين إلى بلاد اليمن، وأمَرَه بتمَلُّكِها وقطْع الفتن بها، وفَوَّض إليه أمرها، وكان بها حطان بن منقذ، وكتَبَ عز الدين عثمان الزنجيلي متولي عدن إلى صلاح الدين يُعَرِّفُه باحتلال البلاد، ويشير بإرسالِ بعض أهله إليها؛ لأن حطان كان قَوِيَ عليه، فجَهَّز صلاح الدين أخاه سيف الإسلام وسَيَّرَه إلى أهل اليمن، فوصلَ إلى زبيد، فخافه حطان بن منقذ واستشعر منه، وتحصَّن في بع"},{"id":2196,"era":"c6","t":"نهاية دولة آل سبكتكين الغزنوية في بلاد فارس وما وراء النهر .","s":"كان أوَّل الغورية هو محمد بن الحسين قد صاهر بهرام شاه بن مسعود صاحِبَ عزنة من آل سبكتكين، ثم قتله بهرام شاه خشيةً من غدره، وقد جاءه يظهِرُ الطاعة ويُبطِنُ الغدر، فولى بعده ملكَ الغورية أخوه سورى وسار إلى غزنة في طلب ثأرِ أخيه وقاتَلَ بهرام شاه فظفر به وقتله أيضًا. ثم ملك أخوهما علاء الدين الحسين بن الحسين، وسار إلى غزنة، فانهزم عنها بهرام شاه، فاستوى عليها علاء الدين الحسين وأقام بغزنة أخاه سيف ال"},{"id":2197,"era":"c6","t":"صلاح الدين الأيوبي يسيطر على ديار الجزيرة ويحصار الموصل .","s":"كان عِزُّ الدين مسعود بن مودود بن زنكي صاحِبُ الموصل قد أقطَعَ مظفر الدين كوكبري بن زين الدين كجك مدينةَ حران وقلعَتَها، ولما سار صلاح الدين لحصار البيرة جنحَ اليه مظفر الدين ووعَدَه النصر واستحَثَّه للقدوم على الجزيرةِ، فجَدَّ صلاح الدين السيرَ مُظهِرًا أنه يريد حَصْرَ حلب سترًا للحالِ، فلما قارب الفراتَ سار إليه مظفر الدين فعبَرَ الفرات واجتمع به وعاد معه فقصدَ البيرة، وهي قلعةٌ منيعة على الفرات"},{"id":2198,"era":"c6","t":"وفاة المنصور عز الدين فروخ شاه بن شاهنشاه صاحب بعلبك .","s":"هو الملك المنصورُ عِزُّ الدين فروخ شاه بن شاهنشاه بن أيوب صاحِبُ بعلبك ونائِبُ دمشق لعَمِّه الناصر صلاح الدين الأيوبي، وهو والِدُ الأمجد بهرام شاه صاحِبِ بعلبك بعد أبيه، وإليه تُنسَبُ المدرسة الفروخ شاهية بالشرقِ الشمالي بدمشق، وإلى جانبِها التربة الأمجديَّة لولده، وهما وقفٌ على الحنفية والشافعية، وقد كان فروخ شاه شجاعًا شَهمًا عاقلًا، ذكيًّا كريًما مُمدَّحًا، امتدحه الشعراءُ لفضله وجُودِه، وكان م"},{"id":2199,"era":"c6","t":"انتصار المسلمين على الفرنج في بحر عيذاب .","s":"عَمِلَ البرنسُ صاحب الكرك أسطولًا، وفَرَغ منه بالكرك، ولم يبقَ إلَّا جمعٌ قطَعَه بعضُها إلى بعض، وحملها إلى بحر أيلة، وجمعها في أسرع وقت، وفرغَ منها وشحَنَها بالمقاتِلة وسَيَّرَها، فساروا في البحر، وافترقوا فرقتين: فرقةٌ أقامت على حِصنِ أيلة وهو للمسلمينَ يَحصُرونه، ويمنَعُ أهلَه من ورود الماء، فنال أهله شدةٌ شديدة وضِيقٌ عظيم؛ وأما الفرقةُ الثانية فإنَّهم ساروا نحو عيذاب، وأفسدوا في السواحل، ونهب"},{"id":2200,"era":"c6","t":"صلاح الدين الأيوبي يملك مدينة سنجار .","s":"لَمَّا سار صلاح الدين عن الموصل إلى سنجار، سيَّرَ مجاهد الدين قايماز إليها عسكرًا قوةً لها ونجدةً، فسمِعَ بهم صلاح الدين، فمَنَعَهم من الوصول إليها، وأوقع بهم، وأخذ سلاحَهم ودوابَّهم وسار إليها ونازلها، وكان بها شرفُ الدين أمير أميران هندوا أخو عز الدين بن مسعود، صاحِبِ الموصل، في عسكر معه، فحَصَر البلد وضايقه، وألحَّ في قتاله، فكاتبه أحدُ أمراء الأكراد الذين به من الزرزارية، وخامر معه، وأشار بقَص"},{"id":2201,"era":"c6","t":"حصر صلاح الدين الأيوبي الموصل محاولا فتحها .","s":"لَمَّا ملك صلاح الدين نصيبين، سار إلى الموصل، وكان عزُّ الدين بن مسعود بن مودود صاحِبُها ومجاهد الدين قايماز قد جمعا العساكرَ الكثيرةَ ما بين فارسٍ وراجل، وأظهرا من السلاحِ وآلات الحصار ما حارت له الأبصارُ، وبذلا الأموالَ الكثيرة، وسار صلاحُ الدين حتى قارب الموصل، فرأى ما هاله وملأ صدرَه وصدور أصحابِه، فإنه رأى بلدًا عظيمًا كبيرًا، ولَمَّا رأى السور والفصيلَ، عَلِمَ أنَّه لا يقدر على أخْذِه، وأنَّ"},{"id":2202,"era":"c6","t":"انتصار المسلمين على الفرنج واستعادة الشقيف منهم .","s":"فتح المسلمون بالشام شقيفًا من الفرنج، وهو من أعمال طبرية، مُطِل على السواد، وسببُ فَتحِه أنَّ الفرنج لما سمعوا بمسير صلاح الدين من مصر إلى الشام جمعوا له، وحشدوا الفارس والراجل، واجتمعوا بالكرك بالقرب من الطريق؛ لعَلَّهم ينتهزون فرصة، أو يظفرون بنُصرة، وربما عاقوا المسلمينَ عن المسير بأن يَقِفوا على بعض المضايق، فلمَّا فعلوا ذلك خَلَت بلادهم من ناحية الشام، فسَمِعَ عز الدين فرخشاه بن أخي صلاح الدي"},{"id":2203,"era":"c6","t":"انتصار المسلمين على الفرنجة نواحي طبرية وبيسان .","s":"لَمَّا وصَلَ صَلاحُ الدين إلى دمشقَ مِن مصر أقام بها أيامًا يريحُ ويَستريح هو وجندُه، ثم سار إلى بلاد الفرنج في ربيع الأول، فقصد طبريَّةَ، فنزل بالقرب منها، وخيَّمَ في الأقحوانة من الأردن، وجاءت الفرنجُ بجموعِها فنزلت في طبريَّة، فسيَّرَ صلاح الدين فرخشاه إلى بيسان، فدخَلَها قهرًا، وغَنِمَ ما فيها، وقتل وسبى، وجحف الغورَ غارةً شعواءَ، فعَمَّ أهلَه قتلًا وأسرًا، وجاءت العرب فأغارت على جنين واللجون "},{"id":2204,"era":"c6","t":"وفاة أحمد الرفاعي صاحب الطريقة الصوفية .","s":"هو أبو العبَّاس أحمد بن أبي الحسن علي بن أبي العباس أحمد المعروف بالرفاعي، شيخُ الطائفةِ الأحمديَّة الرفاعية البطائحية الصوفيَّة المشهورة، كان أصلُه من العرب فسكن في البطائِحِ بقرية يقال لها: أم عبيدة، وانضم إليه خلقٌ عظيم من الفقراء، وأحسنوا الاعتقادَ فيه وتَبِعوه, حتى عُرِفوا بالطائفة الرفاعيَّة والبطائحية ويقال: إنَّه حَفِظَ التنبيه في الفقه على مذهب الشافعيِّ، قال الذهبي في العِبَر: وقد كَثُرَ"},{"id":2205,"era":"c6","t":"ظفر صلاح الدين بسفينة كبيرة للفرنج في دمياط .","s":"أثناء حصارِ صلاح الدين الأيوبي الفرنجَ في بيروت أتاه الخبَرُ وهو عليها، أن البحر بمصرَ قد ألقى بطسة- السفينة الكبيرة- للفرنجِ فيها جمعٌ عظيم منهم إلى دمياط، وكانوا قد خرجوا لزيارة بيت المقدس، فأَسَر المسلمون من بها وغَرِقَ منهم الكثير, وكان عِدَّةُ الأسرى ألفًا وستمائة وستة وسبعين أسيرًا، فضُرِبَت بذلك البشائرُ."},{"id":2206,"era":"c6","t":"حصر صلاح الدين الأيوبي  الفرنج في بيروت .","s":"سار صلاحُ الدين عن دمشق إلى بيروت، فنَهَب بلدها، وكان قد أمَرَ الأسطول المصري بالمجيءِ في البحر إليها، فساروا ونازَلوها، وأغاروا عليها وعلى بلدها، وسار صلاحُ الدين فوافاهم ونَهَب ما لم يصِل الأسطولُ إليه، وحصرها عدَّةَ أيام. وكان عازمًا على ملازمتِها إلى أن يفتَحَها."},{"id":2207,"era":"c6","t":"انتصار المسلمين على الفرنج في الشام .","s":"سارت عصابةٌ كبيرة من الفرنج من نواحي الدارم إلى نواحي مصر ليُغيروا وينهبوا، فسَمِعَ بهم المسلمون، فخرجوا إليهم على طريقِ صدر وأيلة، فانتزح الفرنجُ من بين أيديهم فنزلوا بماءٍ يقال له العسيلة، وسبقوا المُسلمين إليه، فأتاهم المسلمون وهم عِطاشٌ قد أشرَفوا على الهلاك، فرأوا الفرنجَ قد ملكوا الماء، فأنشأ اللهُ سبحانه وتعالى بلُطفِه سحابةً عظيمةً فمُطِروا منها حتى رَوُوا، وكان الزَّمانُ قَيظًا، والحَرُّ "},{"id":2208,"era":"c6","t":"ضم صلاح الدين الأيوبي قلعة حارم وإقرار أوضاع بقية قلاع حلب .","s":"لَمَّا ملك صلاحُ الدين حلَب كان بقلعةِ حارم- وهي من أعمالِ حلب- أحَدُ المماليك النوريَّة، واسمه سرحك، وولَّاه عليها الملك الصالح عماد الدين إسماعيل، فامتنع مِن تسليمها إلى صلاح الدين، فراسله صلاحُ الدين في التسليم، وقال له: اطلُبْ مِن الإقطاع ما أردت، ووعده الإحسانَ، فاشتَطَّ في الطلب، وتردَّدَت الرسلُ بينهما، فراسل الفرنجَ ليحتميَ بهم، فسَمِعَ مَن معه من الأجناد أنَّه يراسِلُ الفرنج، فخافوا أن يس"},{"id":2209,"era":"c6","t":"ملك صلاح الدين الأيوبي آمد وتسليمها إلى صاحب الحصن .","s":"نزل صلاحُ الدين بحرزم، تحت ماردين، فلم يَرَ لأخذها وجهًا، فسار عنها إلى آمد، على طريق البارعيَّة، وكان نور الدين محمد بن قرا أرسلان يطالبُه في كل وقتٍ بقَصدِها وأخْذِها وتَسلِيمها إليه، على ما استقَرَّت القاعدةُ بينهما، فوصل إلى آمد سابع عشر ذي الحجة سنة ثمان وسبعين ونازلها، وأقام يحاصِرُها، وقاتلهم صلاح الدين، ونصب المجانيقَ، وزحف إليها، وهي الغايةُ في الحصانة والمَنَعة، بها وبسورِها يُضرَبُ المث"},{"id":2210,"era":"c6","t":"ملك صلاح الدين الأيوبي تل خالد وعين تاب من أعمال الشام .","s":"لما فرغ صلاح الدين من أمر آمد سار إلى الشام، وقصَدَ تلَّ خالد، وهي من أعمالِ حلب، فحصرها ورماها بالمنجنيقِ، فنزل أهلُها وطلبوا الأمانَ فأمَّنَهم، ثم سار منها إلى عين تاب فحصرها وبها ناصر الدين محمد، وهو أخو الشيخ إسماعيل الذي كان خازنَ نور الدين محمود بن زنكي وصاحبَه، وكان قد سلَّمَها إليه نور الدين، فبَقِيَت معه إلى الآن. فلما نازله صلاح الدين أرسل إليه يطلُبُ أن يُقِرَّ الحِصنَ بيده ويَنزِلَ إلى"},{"id":2211,"era":"c6","t":"انتصار المسلمين على الفرنج في البحر  .","s":"في العاشِرِ من المحرم، سار أسطولُ المسلمين مِن مِصرَ في البحر، فلقوا بُطسة- سفينة كبيرة- فيها نحو ثلاثمائة من الفرنج بالسلاح التام، ومعهم الأموالُ والسلاح متَّجهة إلى فرنج الساحل، فقاتلوهم، وصبَرَ الفريقان، وكان الظَّفَرُ للمسلمين، وأخذوا الفرنجَ أسرى، فقَتَلوا بعضهم وأبقَوا بعضَهم أسرى، وغَنِموا ما معهم وعادوا إلى مصرَ سالمين."},{"id":2212,"era":"c6","t":"صلاح الدين الأيوبي يملك حلب .","s":"سار صَلاحُ الدين من عين تاب إلى حلب، فنزل عليها، في الميدان الأخضر، وأقام به عدَّة أيام، ثم انتقل إلى جبل جوشن فنزل بأعلاه، وأظهَرَ أنه يريد أن يبنيَ مساكِنَ له ولأصحابه وعساكِرِه، وأقام عليها أيامًا والقتالُ بين العسكرين كل َّيوم، وكان صاحِبُ حلب عماد الدين زنكي بن مودود بن زنكي، ومعه العسكرُ النوري، وهم مجِدُّون في القتال، فلما رأى كثرةَ الخرجِ، كأنَّه شَحَّ بالمال، فحضر يومًا عنده بعضُ أجناده، "},{"id":2213,"era":"c6","t":"صلاح الدين الأيوبي يغزو مدينة بيسان .","s":"لما فرغ صلاحُ الدين من أمرِ حَلَب جعل فيها ولده المَلِكَ الظاهِرَ غازي، وهو صبيٌّ، وجعَلَ معه الأميرَ سيف الدين يازكج، وكان أكبَرَ الأمراء الأسدية، وسار إلى دمشقَ، وتجهَّز للغزو، ومعه عساكِرُ الشام والجزيرة، وديار بكر، وسار إلى بلدِ الفرنج، فعبَرَ نهر الأردن تاسِعَ جمادى الآخرة، فرأى أهلَ تلك النواحي قد فارقوها خوفًا، فقصد بيسان فأحرقها وخَرَّبَها، وأغار على ما هناك، فاجتمَعَ الفرنج، وجاؤوا إلى قب"},{"id":2214,"era":"c6","t":"صلاح الدين الأيوبي يغزو مدينة الكرك .","s":"لَمَّا عاد صلاحُ الدينِ والمُسلِمونَ مِن غزوةِ بيسان تجَهَّزوا لغزو الكركِ، فسار إليه في العساكرِ، وكتبَ إلى أخيه العادِلِ أبي بكر بن أيوب، وهو نائبُه بمصر، يأمُرُه بالخروج بجميعِ العساكر إلى الكرك. فوصل صلاحُ الدين إلى الكرك، ووافاه أخوه العادِلُ في العَسكَرِ المصري، وكثُرَ جَمعُه، وتمكَّنَ مِن حصره، وصَعِد المسلمون إلى رَبضِه وملكه، وحصر الحِصنَ من الربض، وتحكَّم عليه في القتال، ونصب عليه سبعةَ "},{"id":2215,"era":"c6","t":"العادل بن أيوب يمتلك مدينة حلب .","s":"كان العادِلُ بن أيوب قد أرسل إلى أخيه صلاحِ الدين يطلُبُ منه مدينةَ حَلَب وقلعَتَها بعد أن مَلَكَها، فأجابه إلى ذلك، وأمَرَه أن يخرج معه بأهلِه وماله فالتقى به في الكرك، ثم سيَّر صلاح الدين ابن أخيه تقي الدين إلى مصرَ نائبًا عنه؛ ليتولى ما كان أخوه العادِلُ يتولاه، وبعد أن رحل صلاحُ الدين عن الكرك استصحب معه أخاه العادل إلى دمشق، وأعطاه مدينةَ حلب وقلعتها وأعمالها، ومدينة منبج وما يتعلَّقُ بها، وس"},{"id":2216,"era":"c6","t":"جيش الموحدين يفك الحصار عن مدينة \"شفترين\" الأندلسية .","s":"فكَّ جَيشُ الموحِّدينَ بقيادة \"أبي يعقوبَ يوسف\" الحصارَ عن مدينة \"شفترين\" الأندلسيَّة التي وقَعَت في قبضةِ النصارى، وذلك بعد أن فَشِل الموحِّدون في اقتحام أسوارِ المدينة."},{"id":2217,"era":"c6","t":"غزو صلاح الدين الأيوبي الكرك .","s":"سار صلاح الدين من دمشق يريدُ الغزوَ، وجمَعَ عساكِرَه، فأتَته من كل ناحية، وأتاه نورُ الدين محمد بن قرا أرسلان، صاحِبُ الحصن. وكتب إلى مصرَ لِيُحضِرَ عَسكَرَها عنده على الكرك، فنازل الكركَ وحصره، وضَيَّقَ على من به، وأمَرَ بنصب المجانيق على ربضه، واشتَدَّ القتال، فملك المسلمون الربَضَ، وبقي الحصن، وهو الربضُ على سطحِ جَبَلٍ واحد، إلَّا أنَّ بينهما خندقًا عظيمًا فطَمُّوه بصعوبةٍ بالغة، وأرسَلَ مَن ف"},{"id":2218,"era":"c6","t":"وفاة قطب الدين الأرتقي صاحب ماردين وملك أولاده بعده .","s":"هو قطبُ الدين إيلغازي بن نجم الدين بن ألبي بن تمرتاش بن إيلغازي بن أرتق صاحِبُ ماردين، ومَلَك بعده ابنُه حسام الدين بولق أرسلان، وهو طفل، وقام بتربيته وتدبيرِ مملكته نظامُ الدين البقش مملوك أبيه، وكان شاه أرمن صاحِبُ خلاط خالَ قطب الدين فحَكَم في دولته، وهو رتَّبَ البقشَ مع ولده، وكان البقشُ ديِّنًا خيرًا عادلًا حَسَن السيرة حليمًا، فأحسن تربيتَه وتزوَّجَ أمَّه. فلما كَبِرَ الولد لم يمكِنْه النظام"},{"id":2219,"era":"c6","t":"مصرع يوسف بن عبد المؤمن حاكم الموحدين بالأندلس .","s":"هو السُّلطانُ الكبير، أبو يعقوبَ يوسفُ بن عبد المؤمن بن علي القيسي الكومي صاحب المغرب, تمَلَّك بعد أخيه المخلوع محمد بن علي؛ لطَيشِه، وشُربِه الخمر، فخُلِعَ بعد شهر ونصف، وبُويع أبو يعقوب، وكان شابًّا مليحًا، أبيض بحُمرة، مستديرَ الوجه، أفوَهَ، أعيَنَ، تامَّ القامة، حُلوَ الكلام، فصيحًا، حُلوَ المفاكهةِ، عارفا باللغة والأخبار والفِقه، متفنِّنًا، عاليَ الهمة، سخيًّا، جوادًا، مَهيبًا شجاعًا، خليقًا "},{"id":2220,"era":"c6","t":"ملك الملثمين بجاية وعودها إلى أولاد عبد المؤمن .","s":"خرج عليُّ بنُ إسحاق المعروفُ بابن غانية، وهو من أعيان الملثَّمين- المرابطين- الذين كانوا ملوك المغرب، وهو حينئذٍ صاحبُ جزيرة ميورقة، إلى بجاية فمَلَكَها، وسبب ذلك أنه لَمَّا سمع بوفاة يوسف بن عبد المؤمن عَمرَ أسطولَه، فكان عشرين قطعةً وسار في جموعه فأرسى في ساحل بجاية، وخرجت خيلُه ورجالُه من الشواني فكانوا نحو مائتي فارس من الملثَّمين وأربعة آلاف راجل، فدخل مدينةَ بجاية بغير قتالٍ؛ لأنه اتفق أنَّ "},{"id":2221,"era":"c6","t":"الفتنة بين التركمان والأكراد بديار الجزيرة والموصل .","s":"ابتدأت الفتنةُ بين التركمان والأكراد بديار الجزيرة والموصِل وديار بكر وخلاط والشام وشهرزور وأذربيجان، وقُتِلَ فيها من الخلقِ ما لا يحصى، ودامت عدةَ سِنينَ، وتقَطَّعَت الطرق، ونُهِبَت الأموال، وأُريقَت الدماء، وكان سَبَبُها أنَّ امرأة من التركمان تزوَّجَت بإنسانٍ تركماني، واجتازوا في طريقِهم بقلعة من الزوزان للأكراد، فجاء أهلُها وطلبوا من التركمان وليمةَ العرس، فامتنعوا من ذلك، وجرى بينهم كلامٌ صار"},{"id":2222,"era":"c6","t":"انتزاع الملثمين والعرب إفريقية من الموحدين والخطبة للخليفة العباسي .","s":"بعد أن فَشِلَ عليُّ بنُ إسحاق الملثَّم السنة الماضية في مُلك بجاية، سار علي إلى إفريقيَّة، فلما وصل إليها اجتمع سليمٌ ورباح ومن هناك من العرب، وانضاف إليهم التركُ الذين كانوا قد دخلوا من مصر مع بهاء الدين قراقوش، ودخل أيضًا من أتراكِ مِصرَ مملوك لتقي الدين بن أخي صلاح الدين، اسمُه بوزابة، فكَثُرَ جَمعُهم، وقَوِيَت شوكتُهم، فلما اجتمعوا بلغت عِدَّتُهم مبلغًا كثيرًا، وكُلُّهم كاره لدولة الموحِّدين، "},{"id":2223,"era":"c6","t":"وفاة الإمام عبد الحق الإشبيلي .","s":"هو الإمامُ الحافِظُ، البارعُ المجَوِّد العلَّامة، الفقيهُ المحَدِّث: أبو محمد عبد الحق بن عبد الرحمن بن عبد الله الأزدي الأندلسي الإشبيلي، المعروف بابن الخراط. ولد سنة 514 سكن بمدينة بجاية، ونشر بها عِلمَه، وصَنَّف التصانيف وقت الفتنة التي زالت فيها دولةُ المرابطين على يد الموحِّدين، وهو من علماء الأندلس. اشتهرَ بالتأليف في العلم وخاصَّةً في الحديثِ، له كتاب الجَمعُ بين الصحيحين، والجامعُ الكبير و"},{"id":2224,"era":"c6","t":"ملك صلاح الدين الأيوبي ميافارقين .","s":"سار صلاحُ الدين إلى خلاط وجعَلَ طريقَه على ميافارقين مَطمَع ملكها، حيث كان صاحِبُه قطب الدين، صاحِبُ ماردين، قد توفِّي ومَلَك بعده ابنُه، وهو طفل، وكان حُكمُها إلى شاه أرمن، وعسكَره فيها، فلمَّا توفِّيَ طَمِعَ في أخْذِها، فلمَّا نازلها رآها مشحونةً بالرجال، وبها زوجةُ قطب الدين المتوفى، ومعها بناتٌ لها منه، وهي أختُ نور الدين محمد، صاحِبِ الحصن، فأقام صلاحُ الدين عليها يحصُرُها من أول جمادى الأولى"},{"id":2225,"era":"c6","t":"وفاة الحافظ أبي موسى المديني الأصبهاني .","s":"هو الإمام العلَّامة، الحافظُ الكبيرُ الثِّقة، شيخُ المحَدِّثين، أبو موسى محمد بن المقرئ أبي بكر عمر بن أحمد بن عمر بن محمد بن أحمد بن أبي عيسى المديني، الأصبهاني، الشافعي، صاحِبُ التصانيف، أحد حفَّاظ الدنيا الرَّحَّالين الجوَّالين، له مصنفات عديدة، وشرح أحاديث كثيرة، كان من علماء الحديث المشهورين، ولد في ذي القعدة سنة 501, ومولد أبيه المقرئ أبي بكر سنة 465. حرص عليه أبوه، وسَمَّعه حضورًا، ثم سماعً"},{"id":2226,"era":"c6","t":"ملك صلاح الدين الأيوبي الموصل .","s":"لَمَّا فَرَغ صلاح الدين من أمر ميافارقين، وأحكم قواعِدَها، وقرَّرَ أقطاعها وولاياتها، أجمعَ على العود إلى الموصل، فسار نحوها، وجعل طريقَه على نصيبين، فوصل إلى كفر زمار، والزمانُ شتاء، فنزلها في عسكره، وعزم على المقامِ بها وإقطاع جميع بلادِ الموصل، وأخذ غِلالَها ودَخْلَها، وإضعاف الموصل بذلك؛ إذ عَلِمَ أنه لا يمكنه التغلبُ عليها، وأقام بها شعبان ورمضان، وتردد الرسُلُ بينه وبين عز الدين مسعود، صاحِب"},{"id":2227,"era":"c6","t":"وهن أمر الفرنج بسبب اختلافهم على الملك بالشام .","s":"كان القُمُّص- كبير القساوسة- صاحِبُ طرابلس، واسمُه ريمند بن ريمند الصنجيلي، قد تزوج بالقومصة، صاحِبةِ طبريَّة، وانتقل إليها، وأقام عندها بطبريَّة، ومات ملك الفرنج بالشام، وكان مجذومًا، وأوصى بالمُلك إلى ابن أختٍ له، وكان صغيرًا، فكفَلَه القُمُّص، وقام بسياسة الملك وتدبيره؛ لأنه لم يكن للفرنج ذلك الوقتَ أكبَرُ منه شأنًا، ولا أشجَعُ ولا أجود رأيًا منه، فطَمِعَ في الملك بسبب هذا الصغير، فاتفق أن الصغ"},{"id":2228,"era":"c6","t":"غدر البرنس أرناط صاحب الكرك، .","s":"كان البرنس أرناط، صاحب الكرك، من أعظَمِ الفِرنجِ وأخبَثِهم، وأشدِّهم عداوةً للمُسلِمينَ، وأعظَمِهم ضررًا عليهم، فلمَّا رأى صلاح الدين ذلك منه قَصَدَه بالحَصرِ مَرَّةً بعد مرة، وبالغارة على بلاده كَرَّةً بعد أخرى، فذَلَّ وخضع، وطلب الصُّلحَ من صلاحِ الدين، فأجابه إلى ذلك، وهادنه وتحالفا، وترددت القوافل من الشامِ إلى مصر، ومِن مِصرَ إلى الشام، فلما كان هذه السَّنة اجتاز به قافلةٌ عظيمة غزيرة الأموال"},{"id":2229,"era":"c6","t":"وفاة البهلوان صاحب أذربيجان وعراق العجم وملك أخيه قزل .","s":"هو المَلِك شمس الدين البهلوان محمَّد بن الأتابك إيلدكز صاحِب أذربيجان وعراق العجم بلد الجبل والري وأصفهان وأذربيجان وأرانية وغيرها من البلاد،، وهو من كبارِ الملوك كوالِدِه. تمَلَّك البهلوان بعد موت أبيه سنة 570، وأقام في السلطنةِ معه طغريل بن رسلان شاه خاتمة بقايا السلجوقية، وكان السلطانُ طغريل بن أرسلان بن طغرل بن محمد بن ملكشاه مع البهلوان، والخطبةُ له في البلاد بالسلطنة، وليس له من الأمرِ شَيءٌ"},{"id":2230,"era":"c6","t":"وفاة العلامة اللغوي ابن بري .","s":"هو الإمامُ العلَّامة اللُّغوي الكبيرُ، الحُجَّة الثقة أبو محمد عبد الله بن بري بن عبد الجبار، المقدسي الأصل، المصري، ابن أبي الوحش، المعروف بابن بري، من علماءِ العربية النابهين، وُلد بمصر سنة 499 وتعلم بها, وبرز في علوم اللغة، ودرس في جامع عمرِو بن العاص. اشتغل عليه جماعةٌ كثيرة وانتفعوا به، ومن جُملتهم أبو موسى الجزولي، صاحب المقدِّمة الجزولية في النحو، ووليَ رياسة الديوان المصري, وكان كثيرَ الاط"},{"id":2231,"era":"c6","t":"وفاة مجد الدين هبة الله بن علي الرافضي أستاذ دار المستضيء بأمر الله  .","s":"هبةُ اللهِ بن علي بن هبة الله بن محمد بن الحسن مجد الدين أبو الفضل بن الصاحب أستاذ دار المستضيء بأمر الله، انتهت إليه الرئاسةُ في زمانِه، ووليَ حجابةَ الباب في أيام المستنجدِ، وبلغ رتبةَ الوزراءِ، وولَّى وعَزَل وماج الرفض في أيامِه، وشمخت المبتدعةُ، ولَمَّا بويع الناصِرُ قَرَّبَه وحكَّمَه في الأمور، ثم إنَّ بعض النَّاسِ سعى به فاستدعيَ إلى دار الخلافة وقُتِلَ بها ثمَّ عُلِّقَ رأسُه على بابِ دارِه،"},{"id":2232,"era":"c6","t":"صلاح الدين الأيوبي يهزم الصليبيين في معركة صفورية .","s":"أرسلَ صلاحُ الدين إلى وَلَدِه الأفضل يأمُرُه أن يرسل قطعةً صالحةً مِن الجيش إلى بلدِ عكا ينهبونَه ويخَرِّبونهَ، فسيَّرَ مُظفَّر الدين كوكبري بن زين، وهو صاحِبُ خوارزم شاه ران والرها، وأضاف إليه قايماز النجمي ودلدرم اليارقي، وهما من أكابِرِ الأمراء، وغيرهما، فساروا ليلًا، وصَبَّحوا صفوريَّة أواخِرَ صَفَر، فخرج إليهم الفِرنجُ في جمعٍ مِن الدواية والإسبتارية وغيرهما، فالتَقَوا هناك، وجَرَت بينهم حربٌ"},{"id":2233,"era":"c6","t":"صلاح الدين الأيوبي يهزم الصليبيين في معركة (حطين) .","s":"لَمَّا أتت صلاحُ الدين البِشارةَ بهزيمة الإسبتارية والدواية، وقَتْل مَن قُتِل منهم، وأسْر مَن أُسِرَ في صفوريَّة، عاد عن الكرك إلى العسكَرِ الذي مع وَلَدِه الملك الأفضل، فنزل بالأقحوانةِ بقرب طبرية، وتقَدَّم صلاح الدين حتى قارب الفرنجَ، فلم يَرَ الفرنج من يمنَعُهم من القتال، ونزل جريدةً إلى طبرية وقاتلَهم، ونقَّبَ بعض أبراجها، وأخذَ المدينة عَنوةً في ليلة، ولجأ من بها إلى القلعةِ التي لها، فامتنعو"},{"id":2234,"era":"c6","t":"صلاح الدين الأيوبي يعود إلى مدينة طبرية ويمتلك قلعتها .","s":"لَمَّا فَرَغ صلاحُ الدين من هزيمة الفرنجِ في حطِّين أقام بموضِعِه باقيَ يَومِه، وأصبحَ يومُ الأحد، فعاد إلى طبرية ونازلها، فأرسلت صاحبتُها تطلُبُ الأمانَ لها ولأولادها وأصحابِها ومالها، فأجابها إلى ذلك، فخرجت بالجميعِ، فوَفى لها، فسارت آمنةً، ثم أمر بالمَلِك وجماعةٍ مِن أعيان الأسرى فأُرسلوا إلى دمشق، وأمَرَ بمن أُسِرَ مِن الداوية والإسبتارية أن يُجمَعوا ليقتُلَهم، ثمَّ عَلِمَ أن مَن عنده أسيرٌ لا"},{"id":2235,"era":"c6","t":"صلاح الدين الأيوبي يفتح مدينة عكا .","s":"لَمَّا فَرَغ صلاحُ الدين من طبريَّة سار عنها يوم الثلاثاء ووصَلَ إلى عكا يومَ الأربعاء، وقد صَعِدَ أهلُها على سورها يُظهِرونَ الامتناعَ والحِفظَ، وركب يوم الخميس، وقد صَمَّمَ على الزحف إلى البلَدِ وقِتالِه، فبينما هو ينظُرُ مِن أين يزحَفُ ويقاتِلُ إذ خرج كثيرٌ مِن أهلها يَضرَعونَ، ويطلبون الأمانَ، فأجابهم إلى ذلك، وأمَّنَهم على أنفُسِهم وأموالهم، وخيَّرَهم بين الإقامة والظَّعنِ، فاختاروا الرحيلَ؛ "},{"id":2236,"era":"c6","t":"فتح يافا وتبنين وصيدا وجبيل وبيروت .","s":"لَمَّا خرج العادِلُ من مصر، وفتح مجدليابة، سار إلى مدينة يافا، وهي على الساحِلِ، فحصَرَها وملَكَها عَنوةً، ونَهَبها، وأسرَ الرِّجالَ، وسبى الحريمَ، وجرى على أهلها ما لم يجرِ على أحدٍ مِن أهل تلك البلاد، فأما تبنين، فقد قام صلاح الدين بإنفاذ تقي الدين ابن أخيه إلى تبنين، فلمَّا وصلها نازلها، وأقام عليها، فرأى حَصْرَها لا يتِمُّ إلا بوصول عَمِّه صلاح الدين إليه، فأرسل إليه يُعلِمُه الحالَ ويَحُثُّه "},{"id":2237,"era":"c6","t":"صلاح الدين الأيوبي يفتح مدينة عسقلان .","s":"لَمَّا ملك صلاح الدين بيروت وجبيل وغيرهما، سار نحو عسقلان، واجتمع بأخيه العادل ومن معه مِن عساكرِ مِصرَ، ونازلوها يوم الأحد سادس عشر جمادى الآخرة، وكان صلاحُ الدين قد أحضر مَلِكَ الفرنج ومُقَدَّم الداوية إليه مِن دمشق، وقال لهما: إن سَلَّمتُما البلادَ إليَّ فلكما الأمانُ، فأرسلا إلى من بعسقلان من الفرنجِ يأمرانِهم بتسليم البلد، فلم يَسمَعوا أمرَهما وردُّوا عليهما أقبَحَ رَدٍّ وأجابوهما بما يسوءُهم"},{"id":2238,"era":"c6","t":"صلاحُ الدِّينِ الأيوبيُّ يستعيد بيتَ المقدِسِ مِن أيدي الصليبيين .","s":"لَمَّا فَرَغ صلاحُ الدين مِن أمر عَسقلان وما جاورها من البلاد، أرسل إلى مِصرَ؛ لطَلَبِ الأسطول الذي بها في جمَع ٍمن المُقاتِلة، ومُقَدَّمُهم حسامُ الدين لؤلؤ الحاجب، فأقاموا في البَحرِ يقطعون الطريقَ على الفرنجِ، كُلَّما رأوا لهم مركبًا غَنِموه، وشانيًا أخَذوه، فحين وصلَ الأسطول وخلا سِرُّه من تلك الناحية سار عن عسقلان إلى بيت المقدس، وكان به البُطرُك المعظَّم عندهم، وهو أعظَمُ شأنًا من مَلِكِهم، "},{"id":2239,"era":"c6","t":"فتح الغوريين شرستي من الهند وغيرها وانهزام المسلمين بعدها .","s":"سار شِهابُ الدين الغوري، مَلِك غزنة، إلى بلاد الهند، وقَصَد بلاد أجمير، وتعَرَّف بولاية السوالك، واسمُ ملكهم كولة، وكان شجاعًا شهمًا، فلما دخل المُسلِمونَ بلاده ملكوا مدينةَ تبرندة، وهي حِصنٌ منيع عامِرٌ، وملكوا شرستي، وملكوا كورام، فلما سَمِعَ مَلِكُهم كولة جمَعَ العساكِرَ فأكثَرَ، وسار إلى المسلمين، فالتقوا، وقامت الحربُ على ساق، وكان مع الهند أربعة عشر فيلًا، فلما اشتَدَّت الحربُ انهزَمَت ميمنة"},{"id":2240,"era":"c6","t":"الفتنة بعرفات وقتل ابن المقدم .","s":"قُتِلَ شَمسُ الدين محمَّد بن عبد الملك المعروف بابنِ المُقَدَّم يومَ عَرَفة بعَرَفاتٍ، وهو أكبَرُ الأمراء الصلاحية، وسبَبُ قتله أنَّه لما فتَحَ المُسلِمونَ بيت المقدس طَلَب إذنًا من صلاحِ الدين ليحُجَّ ويُحرِمَ مِن القدس، ويجمَعَ في سنةٍ بين الجِهادِ والحَجِّ وزيارة الخليل- عليه السلام- وما بالشام من مشاهِدِ الأنبياء، وبين زيارةِ رَسولِ الله صلى الله عليه وسلم أجمعين، فأَذِنَ له, وكان قد اجتمَعَ ت"},{"id":2241,"era":"c6","t":"انهزام عسكر الخليفة من السلطان طغرل .","s":"جهَّزَ الخليفةُ الناصِرُ لدين الله عسكرًا كثيرًا، وجعلَ المقَدَّمَ عليهم وزيرَه جلال الدين عبيد الله بن يونس، وسيَّرَهم إلى مساعدة قزل أرسلان بن الأتابك إيلدكز، ليكُفَّ السلطان طغرل عن البلاد، فسار العسكَرُ ثالث صفر إلى أن قارب همذان، فلم يصِلْ قزل إليهم، وأقبَلَ طغرل إليهم في عساكرِه، فالتقوا ثامِنَ ربيع الأول بـ (داي مرج) عند همذان، واقتتلوا، فلم يثبُتْ عسكر بغداد، بل انهزموا وتفَرَّقوا، وثبت ال"},{"id":2242,"era":"c6","t":"غزو صلاح الدين الأيوبي بلاد الفرنج بالشام .","s":"سار صلاحُ الدين عن دمشق منتصَفَ ربيعٍ الأول إلى حمص، فنزل على بحيرةِ قدس غربيَّ حمص، وجاءته العساكِرُ، فأوَّل من أتاه من أصحابِ الأطرافِ عماد الدين زنكي بن مودود بن آقسنقر. صاحِبُ سنجار، ونصيبين، والخابور، وتلاحقت العساكِرُ مِن الموصل وديار الجزيرة وغيرها. فاجتَمَعَت عليه، وكَثُرَت عنده. فسار حتى نزل تحت حِصنِ الأكراد من الجانبِ الشرقيِّ، فأقام يومينِ، وسار جريدة- الجريدة خَيْلٌ لا رَجَّالةَ فيها-"},{"id":2243,"era":"c6","t":"فتح جبلة على يد صلاح الدين الأيوبي .","s":"لَمَّا أقام صلاح الدين تحت حِصنِ الأكراد، أتاه قاضي جبلة، وهو منصورُ بن نبيل، يستدعيه إليها ليسَلِّمَها إليه، حمَلَتْه الغيرةُ للدينِ على قَصدِ السُّلطان، وتكَفَّل له بفتح جبلة واللاذقية والبلاد الشماليَّة، فسار صلاح الدين معه رابِعَ جمادى الأولى، فنزل بأنطرطوس سادسه، فرأى الفرنجَ قد أخلَوا المدينة، واحتموا في برجَينِ حَصينينِ، كلُّ واحد منهما قلعةٌ حصينةٌ ومَعقِلٌ منيع، فخرَّب المسلمونَ دُورَهم و"},{"id":2244,"era":"c6","t":"فتح اللاذقية على يد صلاح الدين الأيوبي .","s":"لما فرغ صلاح الدين من أمر جبلة، سار عنها إلى اللاذقية، فوصل إليها في الرابعِ والعشرين من جمادى الأولى، فترك الفرنجُ المدينة لعَجزِهم عن حِفظِها، وصَعِدوا إلى حصنينِ لها على الجبل فامتنَعوا بهما، فدخل المسلمونَ المدينة وحصروا القلعتينِ اللتين فيهما الفرنجُ، وزحفوا إليهما، ونَقَّبوا السور ستين ذراعًا، وعَلِقوه- حازوه-  وعَظُمَ القتال، واشتد الأمرُ عند الوصول إلى السور، فلما أيقن الفرنجُ بالعَطَبِ، و"},{"id":2245,"era":"c6","t":"فتح قلعة صهيون وعدة من الحصون على يد صلاح الدين الأيوبي .","s":"لَمَّا فَرَغ صلاحُ الدين مِن أمْرِ اللاذقيَّة في السابع والعشرين من جمادى الأولى، قصد قلعة صهيون، وهي قلعة منيعةٌ شاهقة في الهواء، صعبةُ المرتقى، على قرنة جبل، يُطيفُ بها وادٍ عَميقٌ، فيه ضِيقٌ في بعضِ المواضع، فنزل صلاحُ الدين على هذا الجبَلِ الملتصق بها، ونَصَب عليه المجانيقَ ورماها، وتقَدَّم إلى ولَدِه الظاهر، صاحِبِ حلب، فنزل على المكانِ الضَّيقِّ من الوادي، ونصَبَ عليه المجانيق أيضًا، فرمى ال"},{"id":2246,"era":"c6","t":"فتح صفد وحصن كوكب على يد صلاح الدين الأيوبي .","s":"في المحَرَّم حاصَرَ صلاح الدين الحِصنَ، لكنه رآه منيعًا فكان رحيلُه عنها في ربيع الأول إلى دمشق، فأقام بدمشق إلى منتصف رمضان، وسار عن دمشقَ إلى قلعة صفد فحصَرَها وقاتلها، ونصب عليها المجانيقَ، وأدام الرميَ إليها ليلًا ونهارًا بالحِجارةِ والسهام، وكان أهلُها قد قاربت ذخائرُهم وأزوادُهم أن تفنى في المدَّةِ التي كانوا فيها محاصَرينَ، فإنَّ عَسكَرَ صلاح الدين كان يحاصِرُهم مِن أول السنة، فلما رأى أهلُ"},{"id":2247,"era":"c6","t":"فتح حصن بكاس والشغر على يد صلاح الدين .","s":"لَمَّا فرغ  صلاحُ الدينِ مِن أمرِ قلعةِ صهيون، سار في ثالث جمادى الآخرة، فوصلَ إلى قلعة بكاس فرأى الفرنجَ قد أخلَوها، وتحصَّنوا بقلعة الشغر، فمَلَك قلعةَ بكاس بغيرِ قتالٍ، وتقَدَّمَ إلى قلعة الشغر وحصَرَها، وهي وبكاس على الطريقِ السَّهلِ المسلوكِ إلى اللاذقيَّة وجبلة، والبلاد التي افتتحها صلاحُ الدين من بلاد الشام الإسلاميَّة، فلما نازلها رآها منيعةً حصينة لا تُرام، ولا يُوصَلُ إليها بطريقٍ من الط"},{"id":2248,"era":"c6","t":"فتح قلعة برزية على يد صلاح الدين الأيوبي .","s":"لَمَّا رحل صلاحُ الدين مِن قلعةِ الشغر سار إلى قلعة برزية، وكانت قد وُصِفَت له، وهي تقابِلُ حِصنَ أفامية، وتناصِفُها في أعمالها، وبينهما بحيرةٌ تجتَمِعُ مِن ماءِ النهر العاصي وعيونٌ تتفَجَّرُ من جبل برزية وغيره، وكان أهلُها أضَرَّ شَيءٍ على المسلمين؛ يقطعونَ الطَّريقَ، ويبالِغونَ في الأذى، فلمَّا وصل إليها نزل شرقيَّها في الرابع والعشرين من جمادى الآخرة، ثم رَكِبَ من الغدِ وطاف عليها لينظُرَ مَوضِ"},{"id":2249,"era":"c6","t":"فتح سرمينية على يد الظاهر غازي بن صلاح الدين .","s":"لما كان صلاحُ الدين مشغولًا بفَتحِ القِلاعِ والحُصونِ التي بيَدِ الفِرنجِ، سَيَّرَ وَلَدَه الظاهر غازي، صاحِبَ حلب، فحصر سرمينية، وضيَّق على أهلها، واستنزلهم على قطيعةٍ قَرَّرَها عليهم، فلمَّا أنزَلَهم وأخذ منهم المقاطعة، هدم الحِصنَ وعفى أثَرَه وعاليَ بنيانه، وكان فيه وفي هذه الحصونِ مِن أسارى المسلمين الجَمُّ الغفيرُ، فأُطلِقوا وأُعطوا كِسوةً ونَفقةً، وكان فَتحُه في يوم الجمعة الثالث والعشرين من"},{"id":2250,"era":"c6","t":"صلاح الدين الأيوبي يفتح قلعة درب ساك .","s":"بعد أن فتح صلاحُ الدين حِصنَ برزية رحل عنه من الغَدِ، فأتى جسرَ الحديد، وهو على النهرِ العاصي، بالقُربِ مِن أنطاكيةَ، فأقام عليه حتى وافاه من تخَلَّفَ عنه من عسكره، ثم سار عنه إلى قلعة درب ساك، فنزل عليها ثامِنَ رجب، وهي مِن معاقِلِ الداوية الحصينةِ وقلاعِهم التي يدَّخِرونَها لحماياتهم عند نزول الشدائد، فلما نزل عليها نصَبَ المجانيقَ، وتابع الرميَ بالحجارة، فهَدَمَت من سورِها شيئًا يسيرًا، فلم يبا"},{"id":2251,"era":"c6","t":"صلاح الدين الأيوبي يفتح قلعة بغراس .","s":"لَمَّا فرغ صلاحُ الدينِ مِن أمْرِ قلعةِ دَربِ ساك سار إلى قلعة بغراس، فحصرها، وجعل أكثَرَ عَسكَرِه يزكًا- اليزك كلمة فارسية تعني مقدِّمة الجيش- مقابل أنطاكية، يُغيرونَ على أعمالها، وكانوا حَذِرينَ مِن الخوف من أهلِها إن غفلوا؛ لقربهم منها، وصلاحُ الدين في بعض أصحابِه على القلعة يقاتِلُها، ونصَبَ المجانيقَ، فلم يؤثِّرْ فيها شيئًا لعُلُوِّها وارتفاعها، فغلب على الظُّنونِ تعذُّرُ فَتحِها وتأخُّر مِلك"},{"id":2252,"era":"c6","t":"الهدنة بين المسلمين وصاحب أنطاكية  .","s":"لما فتح صلاح الدين بغراس عزم على التوجُّهِ إلى أنطاكيَّةَ وحَصرِها، فخاف البيمند صاحِبُها من ذلك، وأشفق منه، فأرسل إلى صلاحِ الدين يطلُبُ الهدنة، وبذَلَ إطلاقَ كُلِّ أسيرٍ عنده من المسلمين، فاستشار مَن عنده من أصحابِ الأطراف وغيرهم، فأشار أكثَرُهم بإجابته إلى ذلك؛ ليعود النَّاسُ ويستريحوا ويجَدِّدوا ما يحتاجون إليه، فأجاب إلى ذلك، واصطلحوا ثمانيةَ أشهُرٍ، وسَيَّرَ رسولَه إلى صاحِبِ أنطاكية يستحلِف"},{"id":2253,"era":"c6","t":"وفاة مؤيد الدولة أسامة بن منقذ الشيزري  .","s":"هو الأميرُ الكبيرُ، العلَّامة فارِسُ الشام، مجدُ الدِّينِ، سلالةُ الملوك والسلاطين مؤيَّدُ الدولة، أبو المظفَّر أسامة بن الأمير مرشد بن علي بن مقلد بن نصر بن منقذ الكناني الشيزري. وُلِدَ بشيزر سنة 488. أحد الشعراء المشهورين. قيل: كان يحفظ من شعر الجاهليَّة عشرةَ آلاف بيت. قال الذهبي: \"سافر إلى مصر, وكان من أمرائِها الشيعة، ثم فارقها وجرت له أمورٌ، وحضر حروبًا ألَّفَها في مجلَّدٍ فيه عبر\". قال يحيى"},{"id":2254,"era":"c6","t":"وفاة الشاعر \"سبط ابن التعاويذي\" .","s":"هو الشاعِرُ الكبير رئيسُ الشعراء، أبو الفتحِ مُحمَّدُ بنُ عبيد الله نشتكين بن عبد الله. الكاتِبُ المعروف بسبط ابن التعاويذي، الشاعِرُ المشهور، كان والده عبيدُ الله من غلمان بني المظفر، وكان اسمُه نشتكين فسَمَّاه ابنه أبو الفتح عبيد الله, وهو سبط أبي محمد المبارك بن علي بن نصر السراج الجوهري الزاهد المعروف بابن التعاويذي- نسبة إلى كتابته التعاويذ وهي الحروز- وإنما نُسِبَ إلى جَدِّه؛ لأنه كفله صغيرً"},{"id":2255,"era":"c6","t":"استعداد نصارى أوربا في حملة صليبية لاسترداد بيت المقدس .","s":"كان وصولُ نبأ سقوط مملكةِ بيت المقدس إلى أوروبا كنتيجةٍ لمعركة حطين صاعِقًا لنصارى أوربا. فإنَّ البابا أوربان الثامن ما إن علم بما حدث حتى توفي من وقْعِ الصدمة. ودعا خليفَتَه البابا غريغوريوس الثامن بمنشور باباوي إلى حملةٍ صليبية جديدة، وأمَرَهم بالصيام كلَّ أسبوع في يوم الجمعة على امتدادِ خمس سنوات، كما أمَرَهم بالامتناع كليًّا في هذه الحقبة من الزَّمَنِ عن أكل اللحم مرَّتينِ في الأسبوع، والدعوة "},{"id":2256,"era":"c6","t":"محاولات صلاح الدين الأيوبي لتحرير المناطق الساحلية من الصليبين .","s":"خرج السلطانُ صلاح الدين الأيوبي من دمشق في ثالث ربيع الأول, ونازل لشقيف أرنون, وكان منزعجًا لقرب انقضاء الهدنة مع بيمند صاحِبِ أنطاكيةَ، ولاجتماع الفرنجِ بصور، واتِّصال الأمداد بهم، فكانت للمُسلمين مع الفرنجِ في بلادهم الساحليَّة عِدَّةُ وقائع، قُتِلَ فيها من الفريقين عِدَّةٌ، وكثُرَ القتل في المسلمين، واشتدت نكايةُ الفرنج فيهم، فرحل السلطانُ إلى عكا، وقد سبقه الفرنجُ ونزلوا عليها. ونزل السلطان بم"},{"id":2257,"era":"c6","t":"حصار صلاح الدين حصن شقيف أرنون .","s":"سار صلاحُ الدين إلى شقيف أرنون، وهو من أمنَعِ الحصون، ليحصُرَه، فنزل بمرج عيون، فنزل صاحِبُ الشقيف، وهو أرناط صاحب صيدا، وكان أرناط هذا من أعظَمِ النَّاسِ دهاءً ومكرًا، فدخل إليه واجتمع به، وأظهر له الطاعةَ والمودة، وقال إنَّه سيُسَلِّمُ له الحِصنَ، فظن صلاحُ الدين صِدقَه، فأجابه إلى ما سأل، فاستقر الأمرُ بينهما أن يسلِّمَ الشقيفَ في جمادى الآخرة، وأقام صلاح الدين بمرج عيون ينتظر الميعاد، وكان أرن"},{"id":2258,"era":"c6","t":"وقعة مقدمة جيش صلاح الدين الأيوبي مع الفرنج .","s":"لما كان صلاح الدين بمرج عيون، وعلى الشَّقيف، جاءته كُتُبٌ مِن أصحابه الذين جعَلَهم يزكًا- مُقَدِّمة جيشه- في مقابل الفرنجِ على صور، يُخبِرونَه فيها أنَّ الفرنج قد أجمعوا على عبورِ الجِسرِ الذي لصور، وعزموا على حصارِ صيدا، فسار صلاح الدين جريدةً في شجعان أصحابه، سوى من جعَلَه على الشقيف، فوصل إليهم وقد فات الأمرُ، وذلك أن الفرنج قد فارقوا صور وساروا عنها لمقصِدِهم، فلَقِيَهم اليزك على مضيق هناك، وق"},{"id":2259,"era":"c6","t":"حصار الفرنج لعكا ومشاركة قوات الألمان في الحصار .","s":"لَمَّا كَثُرَ جَمعُ الفرنج بصور؛ بسَبَبِ أن صلاح الدين كان كُلَّما فتح مدينةً أو قلعةً أعطى أهلَها الأمان، وسيَّرَهم إليها بأموالهم ونسائهم وأولادهم، فاجتمع بها منهم عالَمٌ كثير، ثم إنَّ الرهبان والقسوس وخلقًا كثيرًا من مشهوريهم وفرسانهم لَبِسوا السواد، وأظهروا الحُزنَ على خروج بيت المقدس من أيديهم، وأخَذَهم البطرك الذي كان بالقُدس، ودخل بهم بلادَ الفرنج يطوفها بهم جميعًا، ويستنجدون أهلَها، ويستجي"},{"id":2260,"era":"c6","t":"وصول الحملة الصليبية الثالثة إلى مدينة عكا .","s":"قامت الحملةُ الصَّليبيَّةُ الثالثة من سنة 586 إلى سنة 588، واشترك فيها بوجهِ الخصوص الإقطاعيُّون الكبار والفُرسان من بلدان أوروبا الغربية، قاد الجيوشَ الصليبية كُلٌّ مِن ملكِ فرنسا: فيليب أوغست الثاني، ملك إنجلترا: ريتشارد الذي لُقِّبَ لاحقًا بقلب الأسد، وملك الجرمان (ألمانيا): فريدريك الأول بربروسا، وصلت  القوات الألمانية قبل غيرها سنة 585, لكن بربروسا غَرِقَ في نهر اللامس؛ مِمَّا أحدث ربكةً في ص"},{"id":2261,"era":"c6","t":"ملك البرتغال مدينة شلب بالأندلس وعودها إلى المسلمين .","s":"مَلَك ابن الرنك، وهو من ملوك الفرنج البرتغال، غَربَ بلاد الأندلس، مدينة شلب، وهي من كبار مدن المسلمين بالأندلس، واستولى عليها، فوصَلَ الخبر بذلك إلى الأمير أبي يوسف يعقوب بن يوسف بن عبد المؤمن، صاحِبِ المغرب والأندلس، فتجهَّزَ في العساكِرِ الكثيرة وسار إلى الأندلس، وعبَرَ المجاز، وسيَّرَ طائفة كثيرةً مِن عسكره في البحر، ونازلها وحصَرَها، وقاتَلَ مَن بها قتالًا شديدًا، حتى ذَلُّوا وسألوا الأمانَ، ف"},{"id":2262,"era":"c6","t":"الحرب بين غياث الدين وسلطان شاه بخراسان .","s":"كان سُلطان شاه أخو خوارزم شاه قد تعَرَّض إلى بلاد غياث الدين ومعز الدين مَلِكَي الغورية، من خراسان، فتجهَّزَ غياث الدين وخرج من فيروزكوه إلى خراسان سنة خمس وثمانين وخمسمائة، فبَقِيَ يتردد بين بلاد الطالقان، وبنجدة، ومرو، وغيرها يريد حربَ سلطان شاه، فلم يزَلْ كذلك إلى أن دخلت سنة ست وثمانين، فجمع سلطان شاه عساكِرَه وقصد غياث الدين، فتصافَّا واقتتلا، فانهزم سلطان شاه، وأخذ غياث الدين بعضَ بلاده وعاد"},{"id":2263,"era":"c6","t":"وقعة الفرنج ويزك- مقدمة الجيش- المسلمين عند أسوار عكا .","s":"بعد رحيلِ صلاح الدين عن عكَّا إلى الخروبة لِمَرَضِه، سمع الفرنج أنَّ صلاح الدين قد سار للصيد، ورأوا أنَّ عسكر اليزك- اليزك كلمة فارسية تعني مقدِّمة الجيش- عندهم قليلًا، وأنَّ الوحل الذي في مرج عكا كثيرٌ يمنع من سلوكه من أراد أن ينجدَ اليزك، فاغتنموا ذلك، وخرجوا من خندَقِهم على اليزك وقت العصر، فقاتلهم المسلمونَ، وقُتِلَ من الفريقين جماعة كثيرة، وعاد الفرنجُ إلى خندقهم، ولما عاد صلاح الدين إلى المع"},{"id":2264,"era":"c6","t":"وقعة للمسلمين مع الفرنج حول  عكا\n  .","s":"خرجت الفرنج فارسُها وراجِلُها من وراء خنادقهم في عكا، وتقَدَّموا إلى المسلمين، وهم كثيرٌ لا يُحصى عددهم، وقصدوا نحوَ عسكر مصر، ومُقَدَّمهم الملك العادل أبو بكر بن أيوب، وكان المصريونَ قد ركبوا واصطَفُّوا للقاء الفرنج، فالتقوا واقتتلوا قتالًا شديدًا، فانحاز المصريون عنهم، ودخل الفرنجُ خيامَهم، ونَهَبوا أموالهم، فعطف المصريُّون عليهم، فقاتلوهم مِن وَسطِ خيامهم فأخرجوهم عنها، وتوجَّهت طائفة من المصري"},{"id":2265,"era":"c6","t":"قتال المسلين للصليبين في شواطئ الشام .","s":"دخلت سنة سبع وثمانين والسلطان بالخروبة على حصارِ الفرنج، وقَدِمَت عساكر المسلمين من الشرق ومِن بقية البلاد، فرَحَل من الخروبة لاثنتي عشرة بقيت من ربيع الأول إلى تل كيسان وتتابع مجيءُ العساكر. وكملت أبراجُ الفرنج الثلاثة، التي بَنَوها تجاه عكا في مدة سبعة أشهر، وكانت غايةً في القوة والمتانة والارتفاع حتى علت على أسوار البلد، وامتلأت بالعَدَد والعُدَّة، وطَمُّوا كثيرا من الخندق، وضايقوا البلد. واشتَ"},{"id":2266,"era":"c6","t":"الفرنج يسيطرون على مدينة عكا ويقتلون معظم المسلمين .","s":"في يومِ الجُمُعة سابِعَ عشر جمادى الآخرة، استولى الفرنجُ على مدينة عكا، وكان أوَّل وَهَن دخل على مَن بالبلد أنَّ الأمير سيف الدين علي بن أحمد الهكاري، المعروف بالمشطوب، كان فيها ومعه عدة من الأمراء كان هو أمثَلَهم وأكبَرَهم، خرج إلى ملك إفرنسيس وبذل له تسليمَ البلدِ بما فيه على أن يُطلِقَ المسلمين الذين فيه، ويُمَكِّنَهم من اللَّحاق بسلطانهم، فلم يجِبْه إلى ذلك، فعاد عليُّ بن أحمد إلى البلد، فوَهَ"},{"id":2267,"era":"c6","t":"وفاة الفقيه الحنفي أبي بكر بن مسعود الكاساني .","s":"هو الفقيهُ الحنفي علاءُ الدين أبو بكر بن مسعود بن أحمد الكاساني أو الكاشاني، وكاسان، ويقال قاشان: بلدة وراء الشاس بها قلعة حصينة، وقد لقب بملك العلماء؛ لبراعته في الفقه. ألَّفَ كتابه \"بدائع الصنائع وترتيب الشرائع\". تفَقَّه صاحب \"البدائع\" على محمد بن أحمد بن أبي أحمد السمرقندي المنعوت علاء الدين، وقرأ عليه معظم تصانيفه، مثل \"التحفة في الفقه\" وغيرها من كتب الأصول، وزوَّجه شيخُه ابنته الفقيهة العالِم"},{"id":2268,"era":"c6","t":"وفاة الفيلسوف شهاب الدين السهروردي .","s":"هو الفيلسوف أبو الفتوح شهاب الدين يحيى بن حبش بن أميرك السَّهروردي الحلبيُّ المقتولُ. وُلِدَ السهروردي سنة 549 في بلدةِ سهرورد الواقعةِ في شمال إيران بين قزوين وسلسلة جبالِ البرز ونشأ في مدينةِ مراغة، كان شابًّا فاضِلًا، متكَلِّمًا مناظِرًا، يتوقَّدُ ذكاءً. كان أوحَدَ في العلوم الحكميَّة، جامعًا لفنون الفلسفة، بارعًا في أصول الفقه، مُفرِطَ الذكاءِ، فصيح العبارة، لم يناظر أحدًا إلا أربى عليه، وكان "},{"id":2269,"era":"c6","t":"رحيل الفرنج إلى ناحية عسقلان .","s":"لما فرغ الفرنجُ من إصلاح أمْرِ عكا، ساروا مستهلَّ شعبان نحو حيفا مع شاطئ البحر لا يفارِقونَه، فلما سمع صلاح الدين برحيلِهم نادى في عسكره بالرحيلِ، فضايقوا الفرنج في مسيرِهم، وأرسلوا عليهم مِن السهام ما كاد يحجُبُ الشمس، ووقعوا على ساقةِ الفرنج، فقتلوا منها جماعةً، وأسَروا جماعةً، وأرسل الأفضَلُ بن صلاح الدين إلى والِدِه يستَمِدُّه ويُعَرِّفُه الحال، فأمر صلاح الدين العساكِرَ بالمسير إليه، فاعتذروا"},{"id":2270,"era":"c6","t":"مقتل قزل أرسلان بن إيلدكز صاحب أذربيجان .","s":"هو المَلِك قزل أرسلان، واسمُه عثمان بن الأتابك إيلدكز، صاحب أران، وأذربيجان، وهمذان، وأصفهان، والري، وما بينها، وقد مَلَك البلاد بعد وفاة أخيه البهلوان، وأطاعه صاحبُ فارس وخوزستان، واستولى على السلطان طغرل بن أرسلان بن طغرل، فاعتقله في بعض القلاع، ودانت له البلادُ، وفي آخِرِ أمره سار إلى أصفهان، والفِتَن بها متَّصِلة من وفاة البهلوان إلى هذا الوقت، فتعَصَّب على الشافعية، وأخذ جماعةً مِن أعيانهم فص"},{"id":2271,"era":"c6","t":"عزم الفرنج على قصد بيت المقدس .","s":"لما رأى صلاح الدين أنَّ الفِرنجَ قد لزموا يافا ولم يفارِقوها، وشَرَعوا في عمارتها. رحَلَ مِن مَنزله إلى النطرون ثالث عشر رمضان، وخيَّمَ به، فراسله ملكُ الإنكليز يطلُبُ المهادنة، فكانت الرسُلُ تتردَّدُ إلى المَلِك العادل أبي بكر بن أيوب، أخي صلاح الدين، فاستقَرَّت القاعدة أنَّ مَلِكَ الإنكليز يزوجُ أختَه من العادل، ويكون القُدسُ وما بأيدي المسلمين من بلاد الساحِلِ للعادل، وتكون عكَّا وما بيد الفرنج"},{"id":2272,"era":"c6","t":"وفاة الملك المظفر تقي الدين عمر بن شاهنشاه بن أيوب  .","s":"هو الملك المظَفَّر: تقي الدين عمر بن الأمير نور الدولة شاهنشاه بن أيوب بن شاذي صاحِب حماة، كان بطلًا شجاعًا فاتِكًا مِقدامًا جوادًا مُمَدَّحًا، له مواقِفُ مشهودة مع عَمِّه السلطان صلاح الدين، وكان عزيزًا على عمه صلاح الدين، استنابه بمصر وغيرها من البلاد، ثم أقطعه حماة ومدنًا كثيرة حولها في بلاد الجزيرة، وكان مع عَمِّه صلاح الدين على عكا، ثم استأذنه أن يذهب ليُشرِفَ على بلاده المجاورة للجزيرة والفر"},{"id":2273,"era":"c6","t":"توجه الفرنجة لبيت المقدس لاحتلالها  .","s":"سار صلاحُ الدين إلى بيت المقدس فيمن بَقِيَ معه من العساكر، فنزلوا جميعًا داخِلَ البلد، فاستراحوا مما كانوا فيه، ونَزَل هو بدار الأقسا مجاوِر بيعة قمامة، وقَدِمَ إليه عسكر من مصر مُقَدَّمُهم الأمير أبو الهيجاء السمين، فقَوِيَت نفوس المسلمين بالقُدس، وسار الفرنجُ من الرملة إلى النطرون ثالث ذي الحجة، على عزمِ قَصدِ القدس، فكانت بينهم وبين يزك- مقدِّمة جيش- المسلمينَ وقَعات، أَسَرَ المسلمون في وقعةٍ م"},{"id":2274,"era":"c6","t":"عود الفرنج إلى الرملة .","s":"في العشرين من ذي الحجة عاد الفرنج إلى الرملة، وكان سبَبُ عودهم أنَّهم كانوا ينقلون ما يريدونَه مِن الساحل، فلما أبعدوا عنه كان المسلمون يخرجونَ على مَن يجلِبُ لهم الميرةَ فيَقطَعونَ الطريق ويَغنَمونَ ما معهم، ثم إنَّ ملك الإنكليز  قال لمن معه من الفرنج الشاميين: صَوِّروا لي مدينةَ القدس؛ فإني ما رأيتُها، فصوروها له، فرأى الواديَ يُحيطُ بها ما عدا موضِعًا يسيرًا من جهة الشمال، فسأل عن الوادي وعن عُ"},{"id":2275,"era":"c6","t":"ملك شهاب الدين الغوري أجمير وغيرها من الهند  .","s":"في سنة ثلاث وثمانين غزا شهاب الدين الغوري بلد الهند، وانهزم أمامَ أحد ملوكها وبَقِيَ إلى الآن في نفسه غَضَبٌ عظيمٌ على الجند الغورية الذين انهزموا، فألزَمَهم من الهوان، حتى هذه السَّنة فخرج من غزنة وقد جمع عساكِرَه وسار منهم يطلُبُ عَدُوَّه الهندي الذي هزمه تلك النوبةَ، قال ابن الأثير: \" لما وصل الغوري إلى برشاوور تقَدَّمَ إليه شيخ من الغورية كان يدُلُّ عليه، فقال له: قد قَرُبنا من العدو، وما يعلَ"},{"id":2276,"era":"c6","t":"نهب بني عامر البصرة .","s":"اجتمع بنو عامر في خلقٍ كثير، وأميرُهم اسمُه عميرة، وقَصَدوا البصرةَ، وكان الأميرُ بها محمد بن إسماعيل، ينوبُ عن مُقطِعِها الأمير طغرل، مملوك الخليفة الناصر لدين الله، فوصلوا إليها يومَ السبت سادس صفر، فخرج إليهم الأميرُ محمد فيمن معه من الجند، فوقعت الحربُ بينهم بدرب الميدان، بجانب الخريبة، ودام القتالُ إلى آخر النهار، فلما جاء الليلُ ثَلَم العربُ في السور عدَّةَ ثُلَم، ودخلوا البلد من الغد، فقاتل"},{"id":2277,"era":"c6","t":"مقتل المركيس  صاحب صور وملك الكند هري بعده صور .","s":"في ثالث عشر ربيع الآخر قُتِلَ المركيس الفرنجي، صاحِبُ صور، وهو أكبَرُ شياطينِ الفرنج، وقيل في سبب قتله: إن صلاح الدين راسل مُقَدِّمَ الإسماعيلية، وهو سنان، وبذَلَ له أن يُرسِلَ مَن يقتُلُ مَلِك الإنكليز، وإن قَتَل المركيسَ فله عشرةُ آلاف دينار، فلم يمكِنْهم قتلُ ملك الإنكليز، ولم يَرَه سنان مصلحةً لهم؛ لئلَّا يخلو وجه صلاح الدين من الفرنجِ ويتفَرَّغ لهم، وطَمِعَ في أخذ المال، فعَدَل إلى قتل المركي"},{"id":2278,"era":"c6","t":"استيلاء الفرنج على حصن الداروم ومسيرهم إلى بيت المقدس .","s":"في تاسع جمادى الأولى من هذه السنة استولى الفرنجُ على حصن الداروم، فخَرَّبوه، ثمَّ ساروا إلى بيت المقدس وصلاحُ الدين فيه، فبَلَغوا بيت نوبة، وكان سَبَبُ طمعهم أن صلاح الدين فَرَّقَ عساكره الشرقية وغيرَها؛ لأجل الشتاء ليستريحوا، ولِيَحضُرَ البَدَل عِوَضَهم، وبَقِيَ من قواته الخاصة بعض العساكر المصريَّة، فظنوا أنهم ينالون غَرَضًا، فلما سمع صلاح الدين بقُربِهم منه فَرَّقَ أبراجَ البلد على الأمراء، وسا"},{"id":2279,"era":"c6","t":"استيلاء الفرنج على عسكر المسلمين المصريين .","s":"في تاسع جمادى الآخرة بلغ الفرنجَ الخبَرُ بوصول عسكر من مصر، ومعهم قفل- حِمل كبير- فأسرى الفرنجُ إليهم، فواقعوهم بنواحي الخليل، فانهزم الجندُ، ولم يُقتَلْ منهم رجل من المشهورينَ، إنما قُتِلَ مِن الغلمان والأصحاب، وغَنِمَ الفرنج خيامَهم وآلاتِهم، وأما القفل فإنه أُخِذَ بَعضُه، وصَعِدَ من نجا جبل الخليل، فلم يُقدِم الفرنج على اتِّباعهم، وتمَزَّقَ من نجا من القفل، وتقَطَّعوا، ولَقُوا شدة إلى أن اجتَمَ"},{"id":2280,"era":"c6","t":"غزو صلاح الدين الأيوبي يافا .","s":"لما رحل الفرنج نحو عكا كان قد اجتمع عند صلاح الدين عسكر حلب وغيره، فسار إلى مدينة يافا، وكانت بيد الفرنج، فنازلها وقاتَلَ مَن بها منهم، وملَكَها في العشرين من رجب بالسَّيفِ عَنوةً، ونَهَبها المسلمون، وغَنِموا ما فيها، وقتلوا الفرنجَ وأسَروا كثيرًا، وكان بها أكثَرُ ما أخذوه من عسكرِ مِصرَ والقفل -حِمل كبير- الذي كان معهم، وكان جماعةٌ من المماليك الصلاحيَّة قد وقفوا على أبوابِ مدينة يافا، وكلُّ مَن "},{"id":2281,"era":"c6","t":"وفاة قلج أرسلان صاحب قونية من جهة الروم .","s":"هو السلطان عز الدين قلج أرسلان بن مسعود بن قلج أرسلان بن سليمان بن قتلمش بن سلجوق السلجوقي التركماني، ملك الروم. فيه عَدلٌ في الجملة، وسداد وسياسة، وهو والدُ زوجة الخليفة الناصر لدين الله الست سلجوقي خاتون المعروفة بالخلاطية. كان له من البلاد قونية وأعمالها، وأقصرا، وسيواس، وملطية، وغير ذلك من البلاد، وقد امتَدَّت أيام ملكه نحو تسع وعشرين سنة، وقيل: بضعًا وثلاثين سنة, وغزواته كثيرة في بلاد الروم، "},{"id":2282,"era":"c6","t":"صلح الرملة بين صلاح الدين الأيوبي وريتشارد قلب الأسد .","s":"في العشرين من شعبان عُقِدَت بين المسلمين والفرنج هدنةٌ لِمُدَّة ثلاث سنين وثمانية أشهر، ويوافِقُ أوَّلَ أيلول 1192م، وكان سبب الصلح أن ملك الإنكليز  المعروف بريتشارد قلب الأسد لَمَّا رأى اجتماع العساكر، وأنَّه لا يُمكِنُه مفارقةُ ساحِلِ البحر، وليس بالساحِلِ للمسلمين بلدٌ يَطمَعُ فيه، وقد طالت غيبتُه عن بلاده، راسل صلاح الدين في الصُّلحِ، وأظهر من ذلك ضِدَّ ما كان يطلبُ منه المصاف والحرب، فأعاد ال"},{"id":2283,"era":"c6","t":"وفاة السلطان صلاح الدين الأيوبي .","s":"هو السُّلطانُ الكبيرُ، المَلِكُ النَّاصِرُ: صلاح الدين، أبو المظفر يوسف بن الأمير نجم الدين أيوب بن شاذي بن مروان بن يعقوب الكردي الدُوِيني، ثم التِكريتي المولد. صاحِبُ الدِّيارِ المصريَّة والبلادِ الشاميَّة والفُراتيَّة واليمنيَّة، واسطة عقدِ آل أيوب، وشُهرتُه أكبَرُ مِن أن تحتاج إلى التنبيهِ عليه. اتَّفَق أهل التاريخ على أن أباه وأهلَه من دُوِين؛ بلدةٍ في آخِرِ عمل أذربيجان من جهة أران وبلاد الك"},{"id":2284,"era":"c6","t":"مقتل بكتمر صاحب بخلاط .","s":"هو المَلِك سيف الدين بكتمر, صاحِبُ خلاط، مملوك الملك ظهير الدين شاه أرمن. استولى على أرمينية، وكان محاربًا للسلطان صلاح الدين، فلما بلغه مَوتُه، أسرف في إظهارِ الشَّماتة بموته, فأمر بضَربِ البشائر، وفَرِحَ فرحًا كثيرًا، وعمل تختًا جَلَس عليه، ولَقَّبَ نفسه بالسلطان المعظم صلاح الدين، وكان لقَبُه سيف الدين، فغَيَّرَه، وسمى نفسه عبد العزيز، فلم يُمهِلْه الله تعالى، وظهر منه اختلالٌ وتخليط، وتجهز ليق"},{"id":2285,"era":"c6","t":"وفاة أتابك عز الدين مسعود صاحب الموصل .","s":"هو أتابك أبو المظفر عز الدين مسعود بن قطب الدين مودود بن زنكي بن آقسنقر التركي، صاحِبُ الموصل، وكان عزُّ الدين مُقَدَّم الجيوش في أيام أخيه سيف الدين غازي, وكان يزور الصالحينَ، وفيه حِلمٌ وحياءٌ ودينٌ وقيامُ ليل، وفيه عَدلٌ. ولما توفي أخوه سيف الدين استقَلَّ عز الدين بالمُلك من بعده، وعمل المصافَّ مع صلاح الدين على قرونِ حماة، فانكسر مسعودٌ سنة سبعين، ثم ورث حلب، أوصى له بها ابن عمه الصالح إسماعيل"},{"id":2286,"era":"c6","t":"ملك السلطان خوارزم شاه بلاد الري .","s":"خرج السلطانُ طغرل بن ألب أرسلان بن طغرل بن محمد بن ملكشاه بن ألب أرسلان السلجوقي في سنة ثمان وثمانين من الحبس، وملك همذان وغيرها، وكان قد جرى بينه وبين قتلغ إينانج بن البهلوان، صاحِبِ البلاد، حربٌ انهزم فيها قتلغ إينانج، وتحصَّنَ بالري، وسار طغرل إلى همذان فمَلَكَها، فأرسل قتلغ إينانج إلى خوارزم شاه علاء الدين تكش يستنجِدُه، فسار إليه في سنة ثمان وثمانين، فلما تقاربا نَدِمَ قتلغ إينانج على استدعاء"},{"id":2287,"era":"c6","t":"حصر العزيز عثمان بن صلاح الدين مدينة دمشق .","s":"وصل المَلِكُ العزيزُ عُثمانُ بن صلاح الدين، وهو صاحِبُ مصر، إلى مدينةِ دِمشقَ، فحَصَرَها وبها أخوه الأكبَرُ الملك الأفضل عليُّ بن صلاح الدين، فنزل بنواحي ميدان الحصى، فأرسل الأفضَلُ إلى عمه الملك العادل أبي بكر بن أيوب، وهو صاحِبُ الديار الجزرية، يستنجِدُه، فسار الملك العادِلُ إلى دمشق هو والمَلِك الظاهر غازي بن صلاح الدين، صاحِبُ حلب، وناصِرُ الدين محمد بن تقي الدين، صاحِبُ حماة، وأسدُ الدين شيرك"},{"id":2288,"era":"c6","t":"وقعة عظيمة بين شهاب الدين الغوري ملك غزنة وبين الملك بنارس .","s":"كان شهابُ الدين الغوري، ملك غزنة، قد جهَّز مملوكَه قطب الدين أيبك، وسيَّرَه إلى بلد الهند للغزو، فدخلها فقَتَل فيها وسبى وغَنِم وعاد، فلما سَمِعَ به ملك بنارس، وهو أكبَرُ ملك في الهند، ولايتُه من حد الصين إلى بلاد ملاوا طولًا، ومن البحر إلى مسيرة عشرة أيام من لهاوور عرضًا، وهو مَلِكٌ عظيم، فعندها جمع جيوشَه وحشرها، وسار يطلُبُ بلاد الإسلام، ودخلت سنة تسعين فسار شهاب الدين الغوري من غزنة بعساكِرِه "},{"id":2289,"era":"c6","t":"وفاة السلطان طغرل بن ألب أرسلان  ونهاية الدولة السلجوقية الكبرى .","s":"هو السُّلطانُ طغرل بن ألب أرسلان بن طغرل بن محمد بن ملكشاه بن ألب أرسلان السلجوقي، آخر الملوك السلجوقية. وكان طغرل من أحسَنِ الناس صورةً، فيه إقدامٌ وشجاعةٌ زائدة, وقد انهارت دولةُ بني سلجوق بوفاته, وكانت عوامِلُ ضَعفِ سلطان السلاجِقةِ قد بدأت بوفاة آخِرِ سلاطينِهم الأقوياء السُّلطان سنجر سنة 552, والذي جلس على سريرِ الملك قريبًا من ستين سنة. وقد كان من أعظمِ الملوك همَّةً، ولم يزَلْ في ازدياد إلى"},{"id":2290,"era":"c6","t":"وفاة الإمام الشاطبي صاحب الشاطبية .","s":"هو الشَّيخُ الإمامُ العالمُ العامِلُ، القُدوةُ سيد القراء: أبو محمد القاسم بن فيرة بن أبي القاسم خلف بن أحمد الرعيني الشاطبي الضرير، من طبقات الشافعية, ولد سنة 538 ببلدة شاطبة- وهي مدينة كبيرة بشرق الأندلس، خرج منها جماعة من العلماء- كان الشاطبي يتوقد ذكاءا، مع الورع والتقوى والتأله والوقار. وهو مصنِّف الشاطبية في القراءات السبع، فلم يُسبَق إليها ولا يُلحَق فيها، وفيها من الرموز كنوز لا يهتدي إليه"},{"id":2291,"era":"c6","t":"مسير وزير الخليفة ابن القصاب إلى خوزستان وملكها .","s":"خلع الخليفةُ الناصر لدين الله على النائبِ في الوزارة: مؤيدِ الدينِ أبي عبدِ اللهِ محمَّدِ بنِ علي- المعروف بابن القصَّاب- خِلَعَ الوَزارةِ، وحَكَم في الولايةِ، وبرز في رمضانَ، وسار إلى بلاد خوزستان، وولي الأعمالَ بها، وصار له فيها أصحابٌ وأصدقاء ومعارف، وعَرَف البلادَ ومِن أيِّ وَجهٍ يُمكِنُ الدخول إليها والاستيلاءُ عليها، فلمَّا وَلِيَ ببغدادَ نيابةَ الوزارة أشار على الخليفةِ بأن يُرسِلَه في عسكر"},{"id":2292,"era":"c6","t":"غارة  الملثم الميورقي على إفريقية .","s":"لَمَّا عَبَرَ أبو يوسف يعقوب، صاحِبُ المغرب، إلى الأندلُسِ، وأقام مجاهدًا ثلاثَ سنين، انقطعت أخبارُه عن إفريقية، فقَوِيَ طَمَعُ علي بن إسحق الملثم الميورقي، وكان بالبريَّة مع العرب، فعاود قَصْدَ إفريقية، فبَثَّ جنوده في البلاد فخَرَّبوها، وأكثروا الفسادَ فيها، فمُحِيَت آثارُ تلك البلاد وتغَيَّرَت، وصارت خاليةً من الأنيس، خاويةً على عروشها، وأراد المسيرَ إلى بجاية ومحاصَرتَها لاشتغالِ يعقوب بالجهاد"},{"id":2293,"era":"c6","t":"حصر العزيز عثمان بن صلاح الدين مدينة دمشق ثانية .","s":"خرجَ المَلِكُ العزيزُ عُثمانُ بنُ صلاح الدين من مِصرَ في عساكره إلى دمشقَ يريدُ حَصْرَها مرَّةً أخرى، فعاد عنها مُنهَزِمًا، وسبب ذلك أنَّ مَن عنده من مماليكِ أبيه، وهم المعروفون بالصلاحيَّة، كانوا لا يزالون يخوِّفونَ العزيزَ مِن أخيه، وبيَّنوا له أنَّ المصلحةَ أخْذُ دمشق، فخرج من العام الماضي وعاد، فتجَهَّزَ هذه السنة ليخرُجَ، فبلغ الخبَرُ إلى الأفضل، فسار من دمشقَ إلى عمه الملك العادل، فاجتمع به "},{"id":2294,"era":"c6","t":"ملك عسكر الخليفة الناصر لدين الله أصفهان .","s":"جهَّز الخليفةُ النَّاصِرُ لدين الله جيشًا وسَيَّرَه إلى أصفهان، ومُقَدَّمُهم سيف الدين طغرل، مُقطع بلد اللحف من العراق، وكان بأصفهان عسكَرٌ لخوارزم شاه مع ولده، وكان أهلُ أصفهان يكرهونَهم، فكاتب صَدرُ الدين الخجندي رئيسُ الشافعية بأصفهان الديوانَ ببغداد يبذُلُ من نفسِه تسليمَ البلد إلى من يَصِلُ الديوان من العساكر، وكان هو الحاكِمَ بأصفهان على جميعِ أهلها، فسُيِّرَت العساكر، فوصلوا إلى أصفهان، ونز"},{"id":2295,"era":"c6","t":"انتصار الموحدين على نصارى الأسبان بمرج الحديد في الأندلس .","s":"غزا أبو يوسُفَ يعقوبُ بنُ عبد المؤمن، صاحِبُ بلاد المغرب والأندلس، بلادَ الفِرنجِ بالأندلُسِ، وسبَبُ ذلك أنَّ ألفونسو مَلِك الفرنج بها، ومَقَرُّ مُلكِه مدينة طليطلة، كتب إلى يعقوبَ كتابًا فحواه أنَّه يريد الإغارةَ على البلادِ والقَتلَ، وأنَّه لا مانع له من ذلك ويستهزئُ بقوة المسلمين ويتَّهِمُهم بالضَّعفِ مع أنَّهم- أي المسلمين- مأمورون بالجهاد، حتى لو كان العدوُّ ضِعفَ العَدَد، واستهزأ بالمَلِك أب"},{"id":2296,"era":"c6","t":"انتصار أبي يوسف يعقوب على الفرنج وفتح عدد من حصونهم .","s":"لَمَّا انتصر أبو يوسفَ يعقوب الموحِّدي على نصارى الأسبان السَّنةَ الماضية, حَلَقَ ألفونسو رأسه، ونكَّس صليبه، وركب حمارًا، وأقسم أنْ لا يركب فرسًا ولا بغلًا حتى تُنصر النصرانيَّة, فجمع جموعًا عظيمة، وبلغ الخبَرُ بذلك إلى يعقوب، فأرسل إلى بلاد المغربِ مراكش وغيرها يستنفِرُ النَّاسَ مِن غير إكراه، فأتاه من المتطوِّعة والمرتزقين جمعٌ عظيم، فالتَقَوا في ربيع الأول من هذه السنة، فانهزم الفرنجُ هزيمة قب"},{"id":2297,"era":"c6","t":"ملك شهاب الدين الغوري قلعة بهنكر وغيرها من بلاد الهند .","s":"سار شِهابُ الدين الغوري، صاحِبُ غُزنةَ، إلى بلد الهند، وحصَرَ قلعة بهنكر، وهي قلعةٌ عظيمةٌ منيعةٌ، فطلب أهلُها منه الأمان على أن يُسَلِّموها إليه، فأمَّنَهم وتسَلَّمها، وأقام عندها عشرة أيام حتى رتَّب جندَها وأحوالها، وسار عنها إلى قلعة كوالير، وبينهما مسيرةُ خمسة أيام، وفي الطريق نهرٌ كبيرٌ، فجازه، ووصل إلى كوالير، وهي قلعةٌ منيعة حصينة على جبلٍ عالٍ لا يَصِلُ إليها حَجَرُ منجنيق ولا نشاب، وهي كب"},{"id":2298,"era":"c6","t":"بناء مسجد الكتيبة الجامع بمدينة مراكش بالمغرب الأقصى .","s":"تبدأُ قِصَّةُ بناء مسجد الكتيبة منذ الأيامِ الأولى لانتصارِ الموحِّدين على المرابطين؛ فقد أبى كثيرٌ من الموحِّدين دخولَ البلدة أو الاستقرار فيها؛ لأنهم كانوا يسمعون مُؤَسِّسَ دولتهم المهدي (ابن تومرت) يقول لهم دائمًا: لا تدخلوا مراكش حتى تُطَهِّروها، ولما التمسوا معنى تطهيرِها لدى فقهائِهم أجابوهم أنَّ مساجد مراكش فيها انحرافٌ قليلٌ في القبلة عن الجهةِ الصَّحيحةِ، فعليكم أن تبنوا مسجِدًا دقيق الات"},{"id":2299,"era":"c6","t":"ملك العادل مدينة دمشق من الأفضل .","s":"مَلَك المَلِكُ العادِلُ أبو بكر بنُ أيوب مدينة دمشقَ مِن ابن أخيه الأفضَلِ عليِّ بن صلاح الدين، وكان أبلَغُ الأسباب في ذلك وثوقَ الأفضل بالعادل، فلما أقام العادِلُ عند العزيز بمصر استمالَه، وقَرَّرَ معه أنَّه يخرج معه إلى دمشقَ ويأخُذُها من أخيه ويُسَلِّمُها إليه، فسار معه من مصرَ إلى دمشق، وحَصَروها، واستمالوا أميرًا من أمراءِ الأفضَلِ يقال له العزيزُ بن أبي غالب الحمصي، فسَلَّمَ إليه بابًا من أب"},{"id":2300,"era":"c6","t":"محاولة العزيز عثمان بن صلاح الدين ملك مصر هدم الأهرامات .","s":"عزم العزيزُ عُثمانُ بنُ صلاح الدين الأيوبي على نَقضِ الأهرام، ونَقْل حجارتها إلى سورِ دمياط لبنائه، فقيل له: إن المؤنةَ تَعظُمُ في هَدمِها، والفائدةَ تَقِلُّ مِن حَجَرِها، فانتقل رأيُه من الهَرَمين الكبيرين إلى الهرم الصغيرِ، وهو مبنيٌّ بالحجارة الصوان، فشرع في هدمه، وأراد كذلك إخراجَ الكنوز من تحته فبَقِيَ العمال شهورًا، ثم تركوه بعد أن عَجَزوا عن هَدمِه أيضًا."},{"id":2301,"era":"c6","t":"تطوير الموحدين بناء مدينة الرباط بالمغرب الأقصى .","s":"يرجِعُ تاريخُ مدينةِ الرِّباط إلى فتراتٍ تاريخية مختلفة، إلَّا أنَّ التأسيس الأوَّلي للمدينة يعودُ إلى عهد المرابطين الذين أنشؤوا رباطًا مُحَصَّنًا؛ ذلك أنَّ هاجِسَ الأمن كان أقوى العوامِلِ التي كانت وراء هذا الاختيار؛ ليكون نقطةً لتجَمُّع المجاهدين، ورَدِّ الهَجَمات خلالَ عهد الموحدين، عرفَت المدينة إشعاعًا تاريخيًّا وحضاريًّا؛ حيث تمَّ تحويلُ الرباط (الحصن) على عهدِ عبد المؤمن الموحِّدي إلى قصبة"},{"id":2302,"era":"c6","t":"فتح ملك العادل يافا عنوة .","s":"مَلَك العادِلُ أبو بكرِ بنُ أيوبَ مدينةَ يافا من الساحِلِ الشاميِّ وهي بيد الفرنج، وسَبَبُ ذلك أنَّ الفرنجَ كان قد مَلَكَهم الكند هري، وكان الصُّلحُ قد استقَرَّ بين المسلمين والفرنج أيَّامَ صلاح الدين الأيوبي، فلما توفِّيَ ومَلَك أولادُه بعده، جَدَّد المَلِكُ العزيزُ عثمان بن صلاح الدين الهُدنةَ مع الكند هري وزاد في مُدَّة الهدنة، وبَقِيَ ذلك إلى هذه السَّنة، وكان بمدينةِ بيروت أميرٌ يُعرَفُ بأسام"},{"id":2303,"era":"c6","t":"وفاة سيف الإسلام صاحب اليمن أخو السلطان صلاح الدين .","s":"هو المَلِكُ سَيفُ الإسلام أبو الفوارِسِ طغتكين بن أيوب بن شاذي بن مروان المنعوتُ بالملك العزيز ظهير الدين، صاحِب اليمن بزبيد، أخو صلاح الدين الأيوبي، لَمَّا ملك صلاحُ الدين الدِّيارَ المصريَّةَ سَيَّرَ أخاه شمسَ الدولة توران شاه إلى بلادِ اليمن، فمَلَكَها واستولى على كثيرٍ مِن بلادها، ورجع عنها، ثمَّ سَيَّرَ السلطان إليها بعد ذلك أخاه سيفَ الإسلام، وذلك في سنة 577, وكان رجلًا شجاعًا شديدَ السيرة، "},{"id":2304,"era":"c6","t":"احتلال الفرنج بيروت .","s":"بعد فراغ الملك العادل من فتح يافا عاد المسلمون إلى عين جالوت، فوصَلَهم الخبَرُ بأن الفرنج على عَزمِ قصد بيروت، فرحل العادِلُ والعسكر في ذي القعدة إلى مرج العيون، وعزم على تخريبِ بيروت، فسار إليها جمعٌ مِن العسكر، وهَدَموا سور المدينة سابِعَ ذي الحجة، وشَرَعوا في تخريب دورها وتخريبِ القلعة، فمَنَعَهم أسامة من ذلك، وتكَفَّل بحِفظِها، ورحل الفرنجُ مِن عكَّا إلى صيدا، وعاد عسكَرُ المسلمين من بيروت، فا"},{"id":2305,"era":"c6","t":"انهزام الخطا الترك من الغورية .","s":"عبَرَ كُفَّارُ الخطا الترك نهرَ جيحون إلى ناحية خراسان، فعاثُوا في البلاد وأفسَدوا، فلَقِيَهم عسكر غياث الدين الغوري وقاتلَهم فانهزم الخطا، وكان سَبَبُ ذلك أنَّ خوارزم شاه تكش كان قد سار إلى بلد الري، وهمذان وأصفهان وما بينهما من البلادِ، ومَلَكَها وتعرض إلى عساكر الخليفة، وأظهر طَلَبَ السلطنة والخطبة ببغداد، فأرسل الخليفةُ إلى غياث الدين ملك الغور وغُزنة يأمُرُه بقَصدِ بلاد خوارزم شاه ليعودَ عن ق"},{"id":2306,"era":"c6","t":"فتح خوارزم شاه بخارى .","s":"لَمَّا ورد رسولُ ملك الخطا التُّرك الكُفَّار على خوارزم شاه، أعاد الجوابَ: إنَّ عَسكَرَك إنَّما قَصَد انتزاعَ بلخ، ولم يأتُوا إلى نصرتي، ولا اجتَمَعْتُ بهم، ولا أمرتُهم بالعبور، إن كنتُ فعلْتُ ذلك، فأنا مقيمٌ بالمال المطلوب مني، ولكِنْ حيث عجزتم أنتم عن الغوريَّة عُدتُم عليَّ بهذا القول وهذا المطلب، وأمَّا أنا فقد صلحت مع الغورية، ودخلت في طاعتِهم، ولا طاعةَ لكم عندي، فعاد الرسولُ بالجواب، فجَهَّز"},{"id":2307,"era":"c6","t":"وفاة السلطان عماد الدين زنكي بن قطب الدين مودود .","s":"هو أبو الفَتحِ وأبو الجود عِمادُ الدين زنكي بنُ قُطب الدين مودود بن عماد الدين زنكي بن اقسنقر، صاحِبُ سنجار ونصيبين، والخابور والرقة، كان قد مَلَك حلب سنة 577 بعد ابنِ عَمِّه الملك الصالح إسماعيل بن نور الدين محمود بن عماد الدين زنكي، ومَلَك بعدَه ابنُه قطب الدين محمد، وتولَّى تدبير دولته مجاهِدُ الدين يرنقش مملوكُ أبيه، كان يحِبُّ أهل العلم والدين، ويحتَرِمهم ويجلس معهم ويرجع إلى أقوالهم، وكان شد"},{"id":2308,"era":"c6","t":"حصار الفرنج حصن تبنين .","s":"في مُنتَصَف المحَرَّم، بلغ المَلِكَ العادِلَ أنَّ الفرنج قد نازلوا حِصنَ تبنين، فسَيَّرَ إليه عسكرًا يحمونَه ويَمنَعون عنه، ورحلَ الفرنج من صور، ونازلوا تبنين أوَّلَ صفر وقاتلوا من به، وجدُّوا في القتال، ونَقَبوه من جهاتهم، فلمَّا عَلِمَ العادل بذلك أرسل إلى العزيز عثمان بن صلاح الدين  بمصرَ يطلُبُ منه أن يَحضُرَ هو بنفسه، فسار العزيزُ مُجِدًّا فيمن بَقِيَ معه من العساكر، وأمَّا مَن بحصنِ تبنين فإ"},{"id":2309,"era":"c6","t":"حصار الملك العادل قلعة ماردين .","s":"حاصر المَلِكُ العادل أبو بكر بن أيوب قلعةَ ماردين في شهر رمضان، وقاتَلَ مَن بها، وكان صاحِبُها حسام الدين يولق أرسلان, وكان صبيًّا والحاكِمُ في بلده ودولته مملوكَ أبيه النظام يرنقش، وليس لصاحِبِه معه حُكمٌ البتَّةَ في شيء من الأمور، ولَمَّا حصر العادل ماردين ودام عليها سَلَّمَ إليه بعضُ أهلها الربض بمخامرةٍ بينهم، فنهب العسكَرُ أهلَه نهبًا قبيحًا، وفَعَلوا بهم أفعالًا عظيمة لم يُسمَعْ بمِثلِها، فل"},{"id":2310,"era":"c6","t":"قتال خوارزم شاه الإسماعيلية .","s":"لما استقَرَّت أمورُ خوارزم شاه في الريِّ اشتغَلَ بقتالِ الملاحدة، فافتتح قلعةً على باب قزوين تسمَّى أرسلان كشاه، وانتقل إلى حصارِ قلعة ألموت، فقُتِلَ عليها صدرُ الدين محمد بن الوزان رئيس الشافعية بالري، وكان قد تقَدَّم عنده تقدمًا عظيمًا، قَتَله الملاحدة، وعاد خوارزم شاه إلى خوارزم، فوثَب الملاحِدةُ على وزيره نظام الملك مسعود بن علي فقَتَلوه في جمادى الآخرة سنة ست وتسعين، فأمر تكش ولَدَه قطب الدين"},{"id":2311,"era":"c6","t":"عصيان أهل المهدية على يعقوب وطاعتها لولده محمد .","s":"كان أبو علي يونُس بنُ عمر وَلِيَ المهديَّةَ، وجَعَل قائِدَ الجيش بالمهدية محمَّد بن عبد الكريم، وهو شجاعٌ مشهور، فعَظُمَت نكايته في العرب، فلم يَبقَ منهم إلَّا من يخافه، فاتَّفَق أنه أتاه الخبَرُ بأن طائفة من عوف نازلون بمكان، فخرج إليهم، وعَدَل عنهم حتى جازهم، ثم أقبَلَ عائدًا يطلُبُهم، وأتاهم الخبَرُ بخروجه إليهم، فهربوا من بين يديه، فلَقُوه أمامهم، فهربوا وتركوا المالَ والعيال من غيرِ قتال، فأخ"},{"id":2312,"era":"c6","t":"فتنةٌ عَظيمةٌ بين غياث الدين، مَلِك الغور وغزنة بمدينة فيروزكوه .","s":"كانت فتنةٌ عَظيمةٌ بعَسكَرِ غياث الدين، مَلِك الغور وغزنة، وهو بفيروزكوه، عَمَّت الرعية والملوك والأمراء، وسَبَبُها أن الفخر محمد بن عمر بن الحسين الرازي، الإمامُ المشهور، الفقيهُ الشافعيُّ، فارق بهاءَ الدين صاحِبَ باميان وقَصَد غياثَ الدين الغوري خال بهاء الدين، فالتقاه وبجَّلَه وأنزله، وبنى له مدرسةً، وقَصَده الفُقَهاءُ من النواحي، فعظم ذلك على الكرَّامية، وهم خلقٌ بهراة، وكان أشد الناس عليه ابن"},{"id":2313,"era":"c6","t":"وفاة الملك العزيز عثمان  بن صلاح الدين الأيوبي .","s":"هو السُّلطانُ الملك العزيز أبو الفتح عماد الدين عثمان  بن صلاح الدين يوسف بن أيوب، صاحب ديار مصر، وُلِدَ سنة 567، جمادى الأولى. وحدَّث عن أبي طاهر السِّلَفي، وابنِ عوف. قال الذهبي: \"وتمَلَّك بعد أبيه، وكان لا بأسَ بسيرتِه، قَدمَ دمشق وحاصَرَ أخاه الأفضل. نَقَلْتُ من خط الضياء الحافظ، قال: خرجَ إلى الصيد، فجاءته كُتُبٌ مِن دمشق في أذيَّة أصحابِنا الحنابلةِ في فِتنةِ الحافظ عبد الغني المقدسي, فقال: "},{"id":2314,"era":"c6","t":"وفاة ابن رشد الحفيد الفيلسوف الأندلسي .","s":"هو العلَّامةُ فيلسوف الوقت، أبو الوليد محمد بن أبي القاسم أحمد بن شيخ المالكيَّة أبي الوليد محمد بن أحمد بن أحمد بن رشد القرطبي. حفيدُ العلَّامة ابن رشد الفقيه المتوفى سنة 520، وُلِدَ سنة عشرين قبل وفاة جده العلامة بشهر واحد. درس الفقه والأصول حتى برَعَ فيه وأقبل على عِلمِ الكلام والفلسفة وعلوم الأوائل، حتى صار يُضرَبُ به المثَلُ فيها. واشتغل بالطبِّ والرياضيات. كان ذكيًّا رَثَّ البَزَّة، قَوِيَّ "},{"id":2315,"era":"c6","t":"مسير خوارزم شاه إلى مدينة الري .","s":"سار خوارزم شاه علاء الدين تكش إلى الريِّ وغيرها من بلاد الجَبَل، لَمَّا بلَغَه أنَّ نائِبَه بها مياجق قد تغيَّرَ عن طاعته، فسار إليه فخافه مياجق، فجعل يفِرُّ مِن بين يديه، وخوارزم شاه في طَلَبِه يدعوه إلى الحضورِ عنده، وهو يمتَنِعُ، فاستأمن أكثَرُ أصحابه إلى خوارزم شاه، وهرب هو، فدخل قلعةً من أعمال مازندران فامتنع بها، فسارت العساكِرُ في طلبه فأُخذَ منها وأُحضِرَ بين يدي خوارزم شاه فأمَرَ بحَبسِه "},{"id":2316,"era":"c6","t":"وفاة يعقوب المنصور حاكم الموحدين بالمغرب وولاية ابنه بعده .","s":"هو المنصور أبو يوسف يعقوب بن أبي يعقوب يوسف بن عبد المؤمن بن علي، القيسي الكومي، صاحِبُ المغرب والأندلس. ولِدَ في ربيع الأول سنة 554كان صافي السمرةِ جدًّا، ليس بالطَّويلِ، جميل الوجه، أفْوَهَ أعيْنَ، شديدَ الكَحَل، ضخم الأعضاءِ جَهْوريَّ الصوتِ، جَزْلَ الألفاظ، مِن أصدَقِ الناس لهجةً وأحسَنِهم حديثًا وأكثَرِهم إصابةً بالظن، مجرِّبًا للأمور، ولِيَ وَزارة أبيه، فبحث عن الأحوالِ بحثًا شافيًا وطالع مق"},{"id":2317,"era":"c6","t":"حصر الأفضل مدينة دمشق .","s":"لَمَّا مَلَك الأفضَلُ مِصرَ، واستَقَرَّ بها، واجتمعت الكلمةُ على الأفضَلِ بها، وصَلَ إليه رسولُ أخيه الملك الظاهر غازي، صاحِبِ حلب، ورُسُلُ ابنِ عَمِّه أسد الدين شيركوه بن محمد بن شيركوه، صاحِبِ حمص، يحثَّانِه على الخروج إلى دمشق، واغتنام الفرصةِ بغَيبةِ العادل عنها، وبَذَلا له المساعدةَ بالمال والنَّفسِ والرجال، فبَرَز من مصر، فوصل إلى دمشقَ ثالث عشر شعبان، وكان العادِلُ قد أرسل إليه نوَّابُه بدم"},{"id":2318,"era":"c6","t":"انتزاع ملك العادل الديار المصرية من الأفضل بن صلاح الدين .","s":"في سَنةِ خَمسٍ وتسعين حَصَر الأفضَلُ والظاهِرُ وَلَدا صلاح الدين دمشقَ؛ لأخذها مِن عَمِّهما الملك العادل ورحلا عنها، على عَزمِ المقام بحوران إلى أن يخرُجَ الشتاء، فلمَّا أقاموا برأس الماء وجد العسكَرُ بردًا شديدًا، لأنَّ البَردَ في ذلك المكان في الصَّيفِ موجود، فكيف في الشِّتاءِ، فتغَيَّرَ العزم عن المقام، واتَّفَقوا على أن يعود كلُّ إنسانٍ منهم إلى بلده، ويعودوا إلى الاجتماعِ، فتفَرَّقوا تاسع ربي"},{"id":2319,"era":"c6","t":"مقتل نظام الملك مسعود بن علي على يد الملاحدة الإسماعيلية .","s":"هو نظام الملك مسعود بن علي، وزير خوارزم شاه تكش، وكان صالحًا كثيرَ الخير، حَسَن السِّيرة، شافعيَّ المذهب، بنى للشافعية بمرو جامعًا مُشرفًا على جامع الحنفيَّة، وبنى أيضًا مدرسة عظيمة بخوارزم وجامعًا، وجعل فيها خزانة كتب، وله آثارٌ حسنة بخراسان باقية، وثب الملاحدة الإسماعيليَّة عليه فقتلوه، ولَمَّا مات خلَّف ولدًا صغيرًا، فاستوزره خوارزم شاه رعايةً لحق أبيه، فأشيرَ على الصبيِّ أن يَستعفيَ، فأرسل يقو"},{"id":2320,"era":"c6","t":"وفاة السلطان علاء الدين خوارزم شاه .","s":"هو خوارزم شاه تكش بن ألب أرسلان، صاحِبُ خوارزم وبعض خراسان والري وغيرها من البلاد الجبالية، بشهرستانة بين نيسابور وخوارزم، وكان قد سار من خوارزم إلى خراسان، وكان به خوانيق، فأشار عليه الأطباءُ بترك الحركة، فامتنع، وسار، فلما قارب شهرستانة اشتَدَّ مَرَضُه فأرسل إلى ابنِه قطب الدين محمد يستدعيه، ويعَرِّفُه شدة مرضه، فوصل بعد موتِ أبيه، فولِيَ الملك بعده، ثم تلقَّبَ بعلاء الدين، لَقَب أبيه، وكان لقَب"},{"id":2321,"era":"c6","t":"محاولة انقلاب على ابن سيف الإسلام الأيوبي في اليمن .","s":"جمع عبد الله بن حمزة العلوي المتغَلِّب على جبال اليمن جموعًا كثيرةً فيها اثنا عشر ألف فارس، ومن الرجَّالة ما لا يحصى كثرةً، وكان قد انضاف إليه من جندِ المعز بن إسماعيل بن سيف الإسلام طغتكين بن أيوب، صاحِب اليمن، خوفًا منه، وأيقَنوا بمُلك البلاد، واقتَسَموها، وخافَهم ابنُ سيف الإسلام خوفًا عظيمًا، فاجتمع قوَّاد عسكر ابنِ حمزة ليلًا ليتَّفِقوا على رأيٍ يكون العمَلُ بمقتضاه، وكانوا اثني عشر قائدًا فن"},{"id":2322,"era":"c6","t":"قحط ووباء بمصر وغيرها .","s":"تعَذَّرت الأقواتُ بديار مصر، وتزايدت الأسعارُ، وعَظُم الغلاءُ، حتى أكل النَّاسُ الميتاتِ، وأكَلَ بَعضُهم بعضًا، وتَبِعَ ذلك فناءٌ عظيم، وابتدأ الغلاءُ من أول العام، وتمادى الحالُ ثلاث سنين متواليةً، لا يَمُدُّ النيلُ فيها إلا مدًّا يسيرًا، حتى عَدِمَت الأقوات، وخرج من مصرَ عالمٌ كثيرٌ بأهليهم وأولادهم إلى الشام، فماتوا في الطُّرُقاتِ جُوعًا، وشَنع الموتُ في الأغنياء والفقراء، وأُكِلَت الكلابُ بأسر"},{"id":2323,"era":"c6","t":"وفاة الإمام العلامة أبو الفرج بن الجوزي .","s":"هو الإمامُ العلَّامةُ المفَسِّر، شيخُ الإسلام، مَفخَر العراق، الحافِظُ الواعِظُ جمالُ الدين أبو الفرج عبد الرحمن بن علي بن محمد بن علي الجوزي- نسبة إلى فرضة نهر البصرة- المشهور بابن الجوزي، القُرَشي التيمي البكري البغدادي الفقيهُ الحنبلي. ينتهي نسبُه إلى أبي بكر الصديقِ رَضِيَ الله عنه. كان علَّامة عصره وإمامَ وَقتِه في الحديث وصناعة الوعظ. ولد سنة تسع- أو عشر- وخمسمائة، كان والده واعظًا ويعمَلُ ف"},{"id":2324,"era":"c6","t":"وفاة الأمير سقمان صاحب آمد ومُلك أخيه محمود بعده .","s":"هو الأميرُ قُطبُ الدين سقمان بن محمد بن قرا أرسلان بن داود بن سقمان، صاحب آمد وحصن كيفا، ملك بعد والده، وتلقَّبَ بقطب الدين، وكان صغيرًا فقام بتدبيره القوَّام بن سماقا الأسعدي, ثم بادر سقمان إلى خدمة السلطان صلاح الدين وهو يحاصِرُ ميافارقين، فأقرَّه على ملك بلاده، وأنْ يَصدُرَ عن أمْرِه ونهيه, وكان سقمان شديدَ الكراهةِ لأخيه محمود، والنفور عنه، قد أبعده وأنزله حِصنَ منصور في آخِرِ بلادهم، واتخذَ م"},{"id":2325,"era":"c6","t":"حصار دمشق ومحاولة أخذها من العادل .","s":"بعد مِلكِ الملك العادل ديارَ مِصرَ، وقَطعِه خطبة الملك المنصور ولد الملك العزيز عثمان بن صلاح الدين الأيوبي، فلمَّا فعل ذلك لم يَرْضَه الأمراء المصريون، وخَبُثَت نيَّاتُهم في طاعته، فراسلوا أخوَيِ العزيزِ: الظاهر بحلب، والأفضل بصرخد، يدعونَها إلى قصد دمشقَ وحَصرِها ليخرُجَ المَلِكُ العادل إليهم، فإذا خرج إليهم من مِصرَ أسلموه، وصاروا معهما، فيَملِكانِ البلاد، وكَثُرَ ذلك حتى فشا الخبَرُ واتصل بالم"},{"id":2326,"era":"c6","t":"ملك خوارزم شاه ما كان أخذه الغورية من بلاده .","s":"في سنةِ سبع وتسعين مَلَك غياث الدين وأخوه شهابُ الدين ما كان لخوارزم شاه محمَّد بنِ تكش بخراسان ومرو ونيسابور وغيرها، وعادا عنها بعد أن أقطعا البلادَ، فلمَّا بلغ خوارزم شاه خبَرُ عودة العساكر الغوريَّة عن خراسان، ودخول شهاب الدين الهندَ، أرسل إلى غياثِ الدين يعاتِبُه ويُهَدِّدُه، فغالَطَه غِياثُ الدين في الجواب لتمديدِ الأيامِ بالمُراسلاتِ، ويخرج أخوه شهاب الدين من الهند بالعساكِرِ؛ فإن غياث الدين"},{"id":2327,"era":"c6","t":"الحملة الصليبية الرابعة واحتلال الصليبيين القسطنطينية .","s":"قام البابا أنوسنت الثالث بالدعوة لحرب صليبية رابعة فاستجاب لدعوتِه عدَدٌ مِن أمراء أوربا أغلَبُهم من فرنسا، وكانت هذه الحملة حملةَ أمراء كاثوليك، وقد قرروا أن تكون وجهةُ هذه الحملة إلى مصرَ، ومنها إلى بيت المقدس، لكن الحملة تحوَّلَت إلى القسطنطينية، فلما وصلوها احتلُّوها احتلالَ المنتقم لما بين الأرثوذكس والكاثوليك من العداء، فقتلوا النساءَ والأطفال والرجال وأكثَروا النَّهبَ والسَّلبَ حتى الكنائس "},{"id":2328,"era":"c6","t":"وفاة أبي القاسم سيد الأهل هبة الله البوصيري\n  .","s":"هو الشَّيخُ العالمُ المعَمَّر، مُسنِدُ الديار المصرية، أمين الدين: أبو القاسم سيد الأهل هبة الله بن علي بن سعود بن ثابت بن هاشم بن غالب الأنصاري، الخزرجي، المنستيري الأصل، المصري المولِد والدار، المعروف بالبوصيري، الكاتب الأديب. كانت ولادته سنة 506 بمصر، وقيل: بل ولد يوم الخميس خامس ذي القعدة سنة 500, وله سماعاتٌ عاليةٌ وروايات تفَرَّد بها وألحَقَ الأصاغِرَ بالأكابرِ في علُوِّ الإسناد، ولم يكنْ في"},{"id":2329,"era":"c6","t":"مقتل المعز بن سيف الإسلام صاحب اليمن على يد مماليك أبيه .","s":"هو المعزُّ إسماعيلُ بنُ سيف الإسلام ظهير الدين طغتكين بن نجم الدين أيوب. وسَبَبُ قتله قِلَّةُ عَقلِه، وما كان ادَّعاه من الدعاوى الكاذبة بعد تملُّكِه اليمن بعد أبيه. جَرَت له بها حروبٌ، منها: أنه خرج عليه الشريفُ عبد الله بن عبد الله الحسنى، وضرب معه مصافًّا، فانكسر الشريف, ثم خرج عليه مِن مماليك أبيه نحو ثمانمائة مملوك، وحاربوه، واعتصموا بصنعاء، فكَسَرهم، وأخذها منهم, ثم ادَّعى بعد ذلك الخلافة، و"},{"id":2330,"era":"c6","t":"استيلاء الكرج (الجورجيون، سكان جورجيا) الكفار على دوين .","s":"استولى الكرجُ على مدينة دوين، من أذربيجان، ونَهَبوها، واستباحوها، وأكثَروا القتلَ في أهلها، وكانت هي وجميعُ بلاد أذربيجان للأمير أبي بكر بن البهلوان، وكان على عادته مشغولًا بالشُّربِ، ولا ينظُرُ في أمرِ مملَكتِه ورعِيَّتِه وجُندِه، قد ألقى الجميعَ عن قلبه، وكان أهلُ تلك البلاد قد أكثَرَت الاستغاثة به، وإعلامَه بقصد الكرج بلادَهم بالغارةِ مَرَّةً بعد أخرى، فلما حصر الكرجُ هذه السنة مدينةَ دوين، سار"},{"id":2331,"era":"c6","t":"حصر عسكر الملك العادل ماردين وصلحه مع صاحبها .","s":"سيَّرَ الملكُ العادل أبو بكر بن أيوب، صاحِبُ دمشق ومصر، عسكرًا مع وَلَدِه الملك الأشرف موسى إلى ماردين، فحصروها، وشَحَنوا على أعمالها، وانضاف إليه عسكَرُ المَوصِل وسنجار وغيرهما، ونزلوا بخرزم تحت ماردين، ونزل عسكَرٌ من قلعة البارعية، وهي لصاحب ماردين، يقطعون الميرةَ عن عسكر العادل، فسار إليهم طائفةٌ من عسكر العادل، فاقتتلوا، فانهزم عسكَرُ البارعية، وثار التركمانُ وقطعوا الطريقَ في تلك الناحية، وأك"},{"id":2332,"era":"c6","t":"وفاة السلطان غياث الدين ملك الغور .","s":"هو السلطان غياث الدين أبو الفتح محمد بن سام بن الحسين بن الحسن الغوري، صاحِبُ غزنة وبعض خراسان وفيروزكوه ولهاوور ودهلي من الهند. كان ملِكًا عادِلًا، وللمال باذِلًا، محسِنًا إلى رعيته، رؤوفًا بهم في حُكمِه وسياسته. قَرَّبَ العلماء، وأحَبَّ الفضلاء، كان غياثُ الدين مظفرًا منصورًا في حروبِه، لم تنهَزِمْ له رايةٌ قط، وكان قليلَ المباشرة للحروب، وإنما كان له دَهاءٌ ومَكرٌ، وكان جَوادًا، كثيرَ الصَّدَقا"},{"id":2333,"era":"c6","t":"الظاهر بن صلاح الدين الأيوبي يأخذ قلعة نجم من أخيه الأفضل .","s":"أخذَ الظاهِرُ غازي قلعةَ نجمٍ مِن أخيه الأفضل، وكانت في جملةِ ما أخذ من العادِلِ لَمَّا صالَحَه سنة سبع وتسعين، فلما كان هذه السَّنة أخذ العادِلُ من الأفضل سروج وحملين ورأس عين، وبَقِيَ بيده سميساط، وقلعة نجم، فأرسل الظاهِرُ إليه يطلُبُ منه قلعةَ نجم، وضَمِنَ له أنه يشفَعَ إلى عَمِّه العادل في إعادةِ ما أخذ منه، فلم يعُطِه، فتهَدَّدَه بأن يكون إلبًا عليه، ولم تَزَلِ الرسُلُ تترَدَّدُ حتى سَلَّمَها"},{"id":2334,"era":"c6","t":"مقتل طائفة من الإسماعيلية بخراسان .","s":"وصل رسولٌ إلى شهاب الدين الغوري من عند مُقَدَّم الإسماعيليَّة بخراسان برسالةٍ أنكَرَها، فأمر علاء الدين محمد بن أبي علي متولي بلاد الغور بالمسيرِ في عساكر إليهم ومحاصرةِ بلادهم، فسار في عساكر كثيرةٍ إلى قهستان، وسَمِعَ به صاحب زوزن، فقصده وصار معه وفارق خدمةَ خوارزم شاه، ونزل علاء الدين على مدينة قاين، وهي للإسماعيليَّة، وحَصَرها، وضَيَّق على أهلها، ووصل خَبَرُ قتل شهاب الدين، فصالح أهلَها على ستي"},{"id":2335,"era":"c6","t":"خروج الفرنج للشام لاحتلال بلاد الإسلام والصلح معهم .","s":"خرج كثيرٌ من الفرنج في البحر إلى الشام، وسَهَّلَ الأمرَ عليهم بذلك مُلْكُهم للقُسطنطينيَّة، فأرسوا بعكَّا، وعزموا على قَصدِ بيت المقدس، واستنقاذه من المسلمين، فلما استراحوا بعكَّا ساروا فنهبوا كثيرًا من بلادِ الإسلام بنواحي الأردن، وسَبَوا، وفتكوا في المسلمين، وكان الملك العادل بدمشقَ، فأرسل في جمع العساكِرِ مِن بلاد الشام ومصر، وسار فنزل عند الطور بالقربِ مِن عَكَّا؛ لمنع الفرنج من قصد بلاد الإسل"},{"id":2336,"era":"c6","t":"تملُّك محمود الحميري مرباط وظفار وغيرها من حضرموت  .","s":"تمَلَّك إنسانٌ اسمُه محمود بن محمد الحميري على مدينة مرباط وظفار وغيرهما من حضرموت, وكان ابتداء أمره أنَّ له مَركبًا يَكريه في البحر للتجار، ثم وزر لصاحبِ مرباط، وفيه كرمٌ وشجاعة وحُسن سيرة، فلما توفِّيَ صاحب مرباط مَلَك المدينة بعده، وأطاعه الناسُ محبَّةً له لكَرَمِه وسيرته، ودامت أيامُه بها، فلما كان سنة تسع عشرة وستمائة خرب مرباط وظفار، وبنى مدينة جديدةً على ساحل البحر بالقرب من مرباط، وعندها ع"},{"id":2337,"era":"c6","t":"قتل ملاحدة الباطنية بمدينة واسط .","s":"ورد إلى واسط رجلٌ يعرف بالزكم محمد بن طالب بن عصية، وأصلُه من القارب، مِن قُرى واسط، وكان باطنيًّا ملحدًا، ونزل مجاورًا لدور بني الهروي، وغَشِيَه الناس، وكَثُر أتباعه، وكان ممَّن يغشاه رجلٌ يُعرَف بحسن الصابوني، فاتَّفَق أنه اجتاز بالسويقة، فكَلَّمه رجل نجَّار في مذهبهم، فرَدَّ عليه الصابوني ردًّا غليظًا، فقام إليه النجَّار وقتَلَه، وتسامع الناسُ بذلك، فوثبوا وقتلوا مَن وَجَدوا ممَّن يَنتَسِبُ إلى"},{"id":2338,"era":"c6","t":"تيموجين (جنكيز خان) بن بسوكاي يؤسس إمبراطورية المغول .","s":"في هذه السنة كان ابتداءُ ملك تيموجين (جنكيز خان) ملك التتار، وهو صاحِبُ الياسق وَضَعَه ليتحاكَمَ إليه التتارُ ومن معهم من أمراء الترك, وهو والِدُ تولي، وجَدُّ هولاكو بن تولي. وُلِدَ تيموجين في غُرَّة محرم سنة 550 في منغوليا على الضفة اليمنى لنهر الأونون في مقاطعة دولون بولداق، وهذه المقاطعةُ توجَدُ اليوم في الأراضي الروسيَّة، وكان أبوه بسوكاي رئيسًا لقبيلة قيات المغولية الذي كان وقت ولادة ابنه غائ"},{"id":2339,"era":"c6","t":"وفاة الإمام العلامة الحافظ عبدالغني المقدسي .","s":"هو الإمامُ العلَّامة الحافِظُ الكَبيرُ، الصادِقُ القدوة، العابد الأثَري المتَّبع، عالِم الحفاظ: تقي الدين أبو محمد عبد الغني بن عبد الواحد بن علي بن سرور المقدسي الجماعيلي الدمشقي الصالحي الحنبلي، صاحب التصانيف المشهورة، ولد سنة 541 بجماعيل, وهي قرية من أعمال نابلس وكان أكبَرَ مِن الشيخ موفق الدين أحمد بن قدامة المقدسي بأربعة أشهر، وهما ابنا خالة، كان إمامًا حافظًا متقنًا مصنفًا ثقة، سمع الكثير ور"},{"id":2340,"era":"c6","t":"تحول الملك من الروم إلى الفرنجة بالقسطنطينية  .","s":"مَلَك الفرنجُ مدينة القسطنطينيَّةِ مِن الروم، وأزالوا مُلكَ الروم عنها، وكان سَبَبُ ذلك أنَّ مَلِكَ الروم حينها ثار عليه ابن أخيه وقيل ابنه، ففشل في ذلك فالتجأ للفرنج، ووعدهم إن ساعدوه أن يعينَهم على إخضاعِ الكنيسة للبابوية ويُعينَهم على حملتِهم الصليبيَّة، فاتَّفَق ذلك وقد اجتمع كثيرٌ من الفرنج ليخرجوا إلى بلاد الشامِ لاستنقاذ بيت المقدس من المسلمين، فأخذوا ولدَ الملك معهم، وجعلوا طريقَهم على الق"},{"id":2341,"era":"c6","t":"وفاة الملك ركن الدين بن قلج أرسلان وملك ابنه بعده .","s":"هو المَلِكُ رُكن الدين سليمان بن قلج أرسلان بن مسعود بن قلج أرسلان بن سليمان بن قتلمش بن سلجوق، صاحب ديار الروم، ما بين ملطية وقونية، وكان موته بمرض القولنج في سبعة أيام، وكان قبل مرضه بخمسة أيام قد غدر بأخيه صاحب أنكورية (أنقرة) وهي مدينة منيعة، وكان مُشاقًّا لركن الدين، فحصَرَه عِدَّة سنين حتى ضَعُفَ وقَلَّت الأقوات عنده، فأذعن بالتسليمِ على عِوَضٍ يأخذه، فعَوَّضَه قلعة في أطراف بلده وحَلَفَ له "},{"id":2342,"era":"c7","t":"غارة الكرج (الجورجيون، سكان جورجيا) على بلاد الإسلام من ناحية أذربيجان .","s":"أغارت الكرج على بلاد الإسلامِ من ناحية أذربيجان، فأكثَروا العَيثَ والفَسادَ والنَّهبَ والسَّبيَ، ثمَّ أغاروا على ناحيةِ خلاط من أرمينية، فأوغلوا في البلاد حتى بَلَغوا ملازكرد، ولم يخرُجْ إليهم أحَدٌ من المسلمين يمنَعُهم، فجاسوا خلالَ البلادِ يَنهَبون ويأسِرونَ ويَسْبُون، وكلَّما تقَدَّموا تأخَّرَت عساكِرُ المسلمين عنهم، ثم رجَعوا عنهم، وأغارت الكرجُ على بلاد خلاط، فأتوا إلى أرجيش ونواحيها، فنَهَبو"},{"id":2343,"era":"c7","t":"الحرب بين أمير مكة وأمير المدينة .","s":"وقَعَت الحربُ بين الأميرِ قتادةَ الحسني، أميرِ مكة، وبين الأمير سالم بن قاسم الحُسيني، أميرِ المدينة، ومع كل واحدٍ منهما جمعٌ كثير، فاقتتلوا قتالًا شديدًا، وكانت الحربُ بذي الحُلَيفة بالقُرب من المدينة، وكان قتادة قد قصد المدينةَ لِيَحصُرَها ويأخُذَها، فلَقِيَه سالم، فسار فلَقِيَه، فانهزم قتادةُ، وتَبِعَه سالم إلى مكة فحَصَرَه بها، فأرسل قتادةُ إلى من مع سالم من الأمراء، فأفسَدَهم عليه، فمالوا إلي"},{"id":2344,"era":"c7","t":"كيخسرو بن قلج أرسلان يمتلك بلاد الروم من ابن أخيه .","s":"مَلَك غياثُ الدين كيخسرو بن قلج أرسلان بلادَ الرومِ التي كانت بيد أخيه رُكن الدين سليمان وانتَقَلَت بعد موته إلى ابنه قلج أرسلان بن ركن الدين، وكان سبَبُ مِلك غياث الدين لها أنَّ ركنَ الدين كان قد أخذ ما كان لأخيه غياث الدين، وهي مدينةُ قونية، فهَرَب غياث الدين منه، وقَصَد الشامَ إلى المَلِك الظاهر غازي بن صلاح الدين، صاحب حلب، فلم يجد عنده قبولًا، وقصر به، فسار مِن عنده، وتقَلَّب في البلاد إلى أن"},{"id":2345,"era":"c7","t":"وقوع فتن بين أهل بغداد .","s":"في تاسع رمضان وقعت فتنةٌ بين أهل سوق السلطان والجعفرية، منشؤها أنَّ رَجُلَينِ مِن المحلَّتَينِ اختصما وتوعَّدَ كُلُّ واحدٍ منهما صاحِبَه، فاجتمع أهلُ المحلَّتَينِ، واقتتلوا في مقبرةِ الجعفرية، فسَيَّرَ إليهم مِن الديوان من تلافى الأمرَ وسَكَّنَه، وفي سابع عشر رمضان جرت فتنةٌ ببغداد بين أهل باب الأزج وأهل المأمونيَّة، وسبَبُها أنَّ أهل باب الأزج قتلوا سَبُعًا وأرادوا أن يطوفوا به، فمنَعَهم أهل المأ"},{"id":2346,"era":"c7","t":"استيلاء الأمير عماد الدين الغوري صاحب بلخ على مدينة ترمذ .","s":"سار الأميرُ عِمادُ الدين عُمَر بن الحسين الغوري، صاحبُ بلخ، إلى مدينةِ ترمذ، وهي للأتراكِ الخطا الكُفَّار، فافتتحها عَنوةً، وجعل بها ولَدَه الأكبر، وقَتَل مَن بها من الخطا، ونقل العَلَويينَ منها إلى بلخ، وصارت ترمذ دارَ إسلام، وهي من أمنَعِ الحُصونِ وأقواها."},{"id":2347,"era":"c7","t":"استيلاء خوارزم شاه على بلاد الغورية .","s":"بعد مُكاتَبةِ الحُسَينِ بنِ خرميل، والي هراة، خوارزمَ شاه، ومراسَلَتِه في الانتماءِ إليه والطاعة له، تَرَكَ طاعةَ الغورية، وخِداعه لغياث الدين، ومغالطته له بالخُطبة له والطاعة؛ انتظارًا لوصولِ عسكر خوارزم شاه، ووصل عسكَرُ خوارزم شاه، فلَقِيَهم ابن خرميل، وأنزلهم على بابِ البلد، فقالوا له: قد أَمَرنا خوارزم شاه ألَّا نُخالِفَ لك أمرًا، فشَكَرَهم على ذلك، وكان يخرج إليهم كلَّ يَومٍ، وأقام لهم الوظائ"},{"id":2348,"era":"c7","t":"خوارزم شاه يمتلك مدينة ترمذ وتسليمها إلى الخطا الكفار .","s":"لما أخذ خوارزم شاه مدينة بلخ سار عنها إلى مدينة ترمذ مجِدًّا، وبها ولدُ عماد الدين صاحب بلخ، فأرسل إليه محمَّد بن علي بن بشير يقولُ له: إن أباك قد صار من أخصِّ أصحابي وأكابِرِ أمراء دولتي، وقد سَلَّمَ إليَّ بلخ، وإنما ظهَرَ لي منه ما أنكَرْتُه، فسَيَّرْتُه إلى خوارزم مُكرَمًا محترمًا، وأمَّا أنت فتكون عندي أخًا ووعَدَه، وأقطعه الكثيرَ، فخدعه محمد بن علي، فرأى صاحِبُها أنَّ خوارزم شاه قد حصره مِن ج"},{"id":2349,"era":"c7","t":"الغارة من ابن ليون على أعمال حلب .","s":"توالت الغارةُ من ابن ليون الأرمني، صاحِبِ الدروب، على ولايةِ حَلَب، فنَهَب وحرق، وأسر وسبى، فجمع المَلِكُ الظاهر غازي بن صلاح اِلدين الأيوبي، صاحِبُ حلب، عساكِرَه واستنجد غيرَه من الملوك، فجمع كثيرًا من الفارِسِ والراجِل، وسار عن حَلَب نحو ابن ليون، وكان ابنُ ليون قد نزل في طرف بلادِه مما يلي بلد حلب، فليس إليه طريقٌ؛ لأن جميع بلاده لا طريقَ إليها إلَّا مِن جبال وعرة، ومضايق صعبة، فلا يقدِرُ غيره "},{"id":2350,"era":"c7","t":"ثورة ابن غانية على دولة الموحدين بشمال أفريقيا .","s":"بعد أن استطاع الموحِّدون إخراجَ عليِّ بنِ أحمد من بني خراسان من إفريقيا وطرَدوا النورماند من المهديَّة ووصلوا إلى بُرقةَ، واستَخلَفَ عليها عبدُ المؤمن أبا محمد عبد السلام الكورميَّ، وجعل العاصمة تونس، ثم جاء الأميرُ يعقوب المنصور الذي خرج عليه يحيى بن إسحاق المنورقي المعروف بابن غانية، فقام بالثورة عليه حتى كاد يُنهي دولةَ الموحِّدينَ إلَّا قليلا خلال الفترة من 580 إلى 604 حتى اضطُرَّ السلطان المو"},{"id":2351,"era":"c7","t":"وفاة الأمير طاشتكين مجير الدين أمير الحاج بتستر .","s":"هو الأميرُ مجيرُ الدين طاشتكين بن عبد الله المقتفوي المستنجدي, أميرُ الحاج وزعيم بلاد خوزستان، كان شيخًا غاليًا في التشَيُّع، وكانت الحلة الشيعيَّة إقطاعَه، وكان شجاعًا قليلَ الكلام، يمضي عليه الأسبوعُ لا يتكلم فيه بكلمةٍ، وذُكِرَ أنَّه حج بالناس ستًّا وعشرين سنة، كان يكونُ في الحجاز كأنَّه مَلِكٌ، وقد رماه الوزيرُ ابن يونس بأنه يكاتب صلاحَ الدين فحبَسَه الخليفة، ثم تبيَّنَ له بطلان ما ذكر عنه فأط"},{"id":2352,"era":"c7","t":"عدوان الكرج (الجورجيون، سكان جورجيا) على ولاية خلاط من أرمينية .","s":"قَصَدت الكرجُ في جموعها ولايةَ خلاط من أرمينيَّة، ونهبوا وقتلوا، وأسَروا وسَبَوا أهلَها كثيرًا، وجاسُوا خلالَ الديار آمنين، ولم يخرُجْ إليهم من خلاط من يمنَعُهم فبَقُوا متصرفين في النهب والسبي، والبلادُ شاغرة لا مانع لها، لأنَّ صاحِبَها صبيٌّ، والمدبِّر لدولتِه ليست له تلك الطاعة على الجُندِ، فلما اشتَدَّ البلاء على الناس تذامَروا، وحَرَّض بعضُهم بعضًا، واجتمعت العساكِرُ الإسلاميَّة التي بتلك الول"},{"id":2353,"era":"c7","t":"مقتل السلطان شهاب الدين الغوري ملك غزنة .","s":"هو السُّلطانُ شِهابُ الدين أبو المظفَّر محمَّد بن سام الغوري، مَلِكُ غزنة وبعض خراسان. كان ملكًا شجاعًا غازيًا، عادلًا حَسَنَ السيرة، يحكُمُ بما يوجِبُه الشرع، يُنصِفُ الضعيفَ والمظلوم، وكان يَحضُرُ عنده العُلَماءُ. لما مات أخوه السلطان غياث الدين، قَبَضَ شهاب الدين على جماعةٍ مِن خواصِّ أخيه وأتباعه وصادرهم. قُتِلَ شهاب الدين بعد عودته من لهاوور، بمنزلٍ يقال له دميل، وقتَ صلاة العشاء، وكان سبَبُ "},{"id":2354,"era":"c7","t":"ملك خوارزم شاه الطالقان .","s":"لَمَّا سَلَّم خوارزم شاه ترمذَ إلى الخطا سار عنها إلى ميهنة وأندخوي، وكتب إلى سونج أمير أشكار، نائب غياث الدين محمود بالطالقان يستميلُه، فعاد الرسول خائبًا لم يجِبْه سونج إلى ما أراد منه، وجمع عسكَرَه وخرج يحارِبُ خوارزم شاه، فالتَقَوا بالقرب من الطالقان، فلما تقابل العسكرانِ حمل سونج وحده مجِدًّا حتى قارب عسكرَ خوارزم شاه، فألقى سونج نفسَه إلى الأرض، ورمى سلاحه عنه، وقَبَّلَ الأرضَ، وسأل العَفْوَ"},{"id":2355,"era":"c7","t":"وفاة حسام الدين أردشير صاحب مازندران والخلاف بين أولاده .","s":"توفِّيَ حُسامُ الدين أردشير، صاحِبُ مازندران، وخَلَّفَ ثلاثة أولاد، فمَلَك بعده ابنُه الأكبَرُ، وأخرج أخاه أسامةَ وهو الأوسَطُ مِن البلاد، فقَصَد جرجان، وبها المَلِك علي شاه بن خوارزم شاه تكش، أخو خوارزم شاه محمد، وهو ينوبُ عن أخيه فيها، فشكا إليه ما صنَعَ به أخوه من إخراجِه مِن البلاد، وطَلَب منه أن يُنجِدَه عليه، ويأخُذَ له البلاد؛ ليكون في طاعته، فكتَبَ علي شاه إلى أخيه خوارزم شاه في ذلك، فأمر "},{"id":2356,"era":"c7","t":"امتلاك الكرج (الجورجيون، سكان جورجيا) لمدينة قرس وموت ملك الكرج .","s":"ملك الكرج حصن قرس من أعمال خلاط، وكانوا قد حصروه مدةً طويلة، وضيَّقوا على من فيه، وأخذوا دخلَ الولاية عدة سنين، وكل من يتولى خلاط لا ينجِدُهم، ولا يسعى في راحة تصل إليهم، وكان الوالي بها يواصل رسله في طلب النجدة، وإزاحة من عليه من الكرج، فلا يجاب له دعاء، فلما طال الأمرُ عليه ورأى أنْ لا ناصر له، صالح الكرجَ على تسليم القلعة على مالٍ كثير وإقطاع يأخذُه منهم، وصارت دار شرك بعد أن كانت دار توحيد! ثم"},{"id":2357,"era":"c7","t":"غياث الدين كيخسرو يمتلك مدينة أنطاكية .","s":"في الثالث من شعبان ملك غياث الدين كيخسرو، صاحِبُ قونية وبلد الروم، مدينةَ أنطاكية بالأمان، وهي للرومِ على ساحِلِ البحر، وسَبَبُ ذلك أنَّه كان حَصَرَها قبل هذا التاريخ، وأطال المقامَ عليها، وهَدَّمَ عِدَّةَ أبراج من سورها، ولم يبقَ إلَّا فَتْحُها عَنوةً، فأرسل مَن بها من الروم إلى الفرنجِ الذين بجزيرة قبرص، وهي قريبةٌ منها، فاستنجدوهم، فوصل إليها جماعةٌ منهم، فعند ذلك يَئِسَ غياث الدين منها، ورَحَل"},{"id":2358,"era":"c7","t":"الحرب بين عسكر الخليفة الناصر لدين الله وصاحب لرستان .","s":"سار عسكر الخليفة الناصر لدين الله من خوزستان مع مملوكه سنجر، إلى جبال لرستان، وصاحبها يعرف بأبي طاهر، وهي جبال منيعة بين فارس وأصبهان وخوزستان، فقاتلوا أهلها وعادوا منهزمين، وسبب ذلك أن مملوكًا للخليفة اسمه قشتمر من أكابر مماليكه كان قد فارق الخدمة لتقصير رآه من الوزير نصير الدين العلوي الرازي، واجتاز بخوزستان، وأخذ منها ما أمكنه ولحق بأبي طاهر صاحب لرستان، فأكرمه وعظَّمه وزوجه ابنته، ثم توفِّي أب"},{"id":2359,"era":"c7","t":"محمد خوارزم شاه يمتلك بلاد ما وراء النهر بعد حروب طويلة .","s":"عبر علاء الدين محمد خوارزم شاه نهر جيحون لقتال الخطا، وسبب ذلك أن الخطا كانوا قد طالت أيامهم ببلاد تركستان، وما وراء النهر، وثقُلت وطأتُهم على أهلها، ولهم في كل مدينة نائب يجبي إليهم الأموال، فاتفق أن سلطان سمرقند وبخارى، أنف وضجر من تحكُّم الكفار على المسلمين، فراسل خوارزم شاه يقول له: إن اللهَّ عزَّ وجلَّ قد أوجب عليك بما أعطاك مِن سَعة الملك وكثرة الجنود أن تستنقِذَ المسلمين وبلادهم من أيدي الك"},{"id":2360,"era":"c7","t":"ملك نجم الدين بن الملك العادل خلاط .","s":"ملك الملك الأوحد نجم الدين أيوب بن الملك العادل أبي بكر ابن أيوب مدينةَ خلاط، وسبب ذلك أنَّه كان بمدينة ميافارقين مع أبيه، فلما كان من مُلك سيف الدين بلبان خلاط قصَدَ نجم الدين مدينة موش، وحصرها وأخذها، وأخذ معها ما يجاورها، وطَمِعَ في خلاط، فسار إليها فهزمه بلبان، فعاد إلى بلده وجمع وحشد، وسيَّرَ إليه أبوه جيشًا، فقصد خلاط، فسار إليه بلبان، فتصافَّا واقتتلا، فانهزم بلبان، وتمكن نجم الدين من البلا"},{"id":2361,"era":"c7","t":"غارات الفرنج بالشام .","s":"كثر الفرنج الذين بطرابلس وحصن الأكراد، وأكثروا الإغارة على بلد حمص وولاياتها، ونازلوا مدينة حمص، وكان جمعهم كثيرًا لم يكن لصاحبها أسدِ الدين شيركوه بن محمد بن شيركوه بهم قوَّةٌ ولا يقدر على دفعِهم ومنعِهم، فاستنجد الظاهِرَ غازي، صاحِبَ حلب، وغيره من ملوك الشام، فلم ينجده إلا الظاهر؛ فإنه سيَّرَ له عسكرًا أقاموا عنده، ومنعوا الفرنجَ عن ولايته، ثمَّ إن الملك العادل خرج من مصر بالعساكر الكثيرة، وقصد "},{"id":2362,"era":"c7","t":"حدوث زلزلة بالموصل .","s":"حدثت زلزلة بالموصل في وقت السَّحَر، ولم تكن بها شديدة، وجاءت الأخبارُ من كثير من البلاد بأنها زلزلت ولم تكن بالقويَّة."},{"id":2363,"era":"c7","t":"مقتل السلطان غياث الدين محمود صاحب الغور .","s":"هو السلطان غياث الدين محمود بن السلطان الكبير غياث الدين محمد بن سام الغوري, صاحب غزنة والغور وفيروزكوه, وهو مِن كبار ملوك الإسلام، اتَّفق أن خوارزم شاه علاء الدين هزم الخطا مرات، ثم وقع في أسرِهم مع بعض أمرائه، فبقي خوارزم شاه يخدُم ذلك الأمير كأنَّه مملوكه، ثم قال الأميرُ للذي أسرهما: نفِّذْ غلمانك إلى أهلي ليفتَكُّوني بمال. فقال: فابعث معهم غلامَك هذا ليدُلَّهم، فبعثه ونجا علاء الدين بهذه الحيل"},{"id":2364,"era":"c7","t":"مقتل سنجر شاه صاحب جزيرة ابن عمر وملك ابنه محمود .","s":"هو سنجر شاه بن غازي بن مودود بن زنكي بن آقسنقر، صاحب جزيرة ابن عمر، وهو ابن عم نور الدين، صاحب الموصل، قتله ابنه غازي، وسبب ذلك أن سنجر كان سيئَ السيرة غشومًا ظلومًا لرعيته وجندِه وحَرَمِه وولَدِه، كثيرَ القهر لهم والانتقام منهم، فاقِدَ الشفقة على بنيه حتى غرَّب ابنيه محمودًا ومودودًا إلى قلعة فرح من بلاد الزوزان لتوهُّمٍ توهَّمه فيهما, ثم أخرج ابنه غازي إلى دار بالمدينة, ووكل به فساءت حاله، وكانت"},{"id":2365,"era":"c7","t":"ملك العادل الخابور ونصيبين ومحاولة أخذ سنجار .","s":"ملك العادل أبو بكر بن أيوب بلد الخابور ونصيبين، وحصر مدينة سنجار، والجميع من أعمال الجزيرة، وهو بيد قطب الدين محمد بن زنكي بن مودود، وسببُ ذلك أن قطب الدين كان بينه وبين ابنِ عَمِّه نور الدين أرسلان شاه بن مسعود بن مودود، صاحب الموصل، عداوةٌ مستحكمة، وكان لنور الدين وزراء يحبون أن يشتغل عنهم، فحسَّنوا له مراسلة العادل والاتفاق معه على أن يقتسما بالبلاد التي لقطب الدين، وبالولاية التي لولد سنجر شاه"},{"id":2366,"era":"c7","t":"وفاة الفخر الرازي .","s":"هو العلَّامة فخر الدين, إمام الدنيا في عصره، أبو المعالي وأبو عبد الله محمد بن عمر بن الحسين بن الحسن بن علي القرشي التيمي البكري، الطبرستاني الأصل, الرازي المعروف بالفخرِ الرازي، ويقال له خطيبُ الريِّ، الفقيهُ الشافعي، المفسِّر المتكَلِّم, صاحب التصانيف المشهورة في الفقه والأصولين وغيرهما، أحد فقهاء الشافعية المشاهير بالتصانيف الكبار والصغار، له نحو من مائتي مصنَّف. ولد سنة 543, وقيل سنة أربعة وأ"},{"id":2367,"era":"c7","t":"وفاة ابن الأثير الجزري صاحب جامع الأصول .","s":"هو مجد الدين أبو السعادات المبارك بن أبي الكرم محمد بن محمد بن عبد الكريم بن عبد الواحد الشيباني، المعروف بابن الأثير الجزري كانت ولادته بجزيرة ابن عمر سنة 544 ونشأ بها، ثم انتقل إلى الموصل سنة خمس وستين, ثم عاد إلى الجزيرة، ثم الموصل، وتنقل في الولايات بها واتصل بخدمة الأمير مجاهد الدين قايماز بن عبد الله الخادم الزيني، فكتب له, ثمَّ اتصل بخدمة عز الدين مسعود بن مودود صاحب الموصل، وتولى ديوان رسا"},{"id":2368,"era":"c7","t":"وفاة السلطان أرسلان شاه بن مسعود وقيام ولده بعده .","s":"هو السلطانُ الملك العادل نور الدين أبو الحارث، أرسلان شاه بن مسعود بن مودود بن أتابك عماد الدين زنكي بن آقسنقر، صاحب الموصل, وابنُ صاحبها، كان ملكًا شَهمًا، عارفًا بالأمور، جبارًا سافكًا للدماء بخيلًا. انتقل إلى مذهب الشافعي، ولم يكن في بيته شافعيٌّ سواه. وبنى المدرسة المعروفة به بالموصل للشافعية، قل أن توجد مدرسة في حسنها. كان سريع الحركة في طَلَبِ الملك، إلَّا أنه لم يكن له صبرٌ؛ فلهذا لم يتَّسِ"},{"id":2369,"era":"c7","t":"اعتداءات الفرنج على البلاد المسلمين في الشام ومصر .","s":"توجَّهت مراكب من عكا فيها ملك قبرص المسمَّى إليان إلى ثغر دمياط، فدخله ليلًا وأغار على بعض البلاد، فقتل وسبى وكر راجعًا، فركب مراكبه ولم يدركه الطلبُ، وقد تقدمت له غارة مثلُها قبل هذه، وهذا شيءٌ لم يتَّفِق لغيره، وفيها عاثت الفرنجُ بنواحي القدس، فبرز إليهم الملك المعظم شرف الدين بن الملك العادل، وعمل أبو المظفر سبط ابن الجوزي ميعادًا بنابلس وحثَّ على الجهاد، وكان يومًا مشهودًا، ثم سار هو ومن معه و"},{"id":2370,"era":"c7","t":"هزيمة الفرنج بطليطلة ببلاد الأندلس .","s":"جاءت الأخبار من بلاد الأندلس بأنَّ الموحِّدينَ قد كسروا الفرنجَ بطُليطِلة كسرةً عظيمة، وربما فتحوا طليطلةَ عَنوةً وقَتل منهم خلقًا كثيرًا."},{"id":2371,"era":"c7","t":"إظهار الإسماعيلية توبتهم من اعتقادات الباطنية .","s":"أظهر الإسماعيليَّةُ- ومقَدَّمُهم جلالُ الدين الإسماعيليُّ، تولى بعد أبيه, وقيل: إنه كان غير راضٍ عن ممارساتِ أبيه أعلى محمد وسياستِه العدوانيَّة- الانتِقالَ عن فعل المحرَّمات واستحلالِها، وأمَرَ بإقامة الصلواتِ وشرائِعِ الإسلامِ ببلادهم من خراسان والشام، وأرسل مقدُّمُهم رسلًا إلى الخليفة، وغيره من ملوك الإسلام، يخبِرُهم بذلك، وأرسل والدتَه إلى الحجِّ، فأُكرِمَت ببغدادَ إكرامًا عظيمًا، وكذلك بطريقِ"},{"id":2372,"era":"c7","t":"وفاة العلامة محمد بن يونس بن منعة الفقيه الشافعي .","s":"هو العلَّامةُ عماد الدين أبو حامد محمد بن يونس بن محمد بن منعة بن مالك الإربلي الأصل الموصلي، الفقيه الشافعي، وُلِدَ سنة 535 بمدينة الموصل وتفَقَّه بها على والده، ثم سار إلى بغداد، وتفقَّه بها بالنظامية على السديد محمَّد السلماسي، وأبي المحاسن يوسف بن بندار الدمشقي، وسمِعَ الحديثَ من أبي حامد محمد بن أبي الربيع الغرناطي، وعبد الرحمن بن محمد الكشميهني. وعاد إلى الموصل، ودرَّس بها في عدة مدارس، وعلا"},{"id":2373,"era":"c7","t":"استيلاء منكلي على بلاد الجبل وأصفهان .","s":"قدم إيدغمش، صاحب همذان وأصفهان والري وما بينهما من البلاد إلى بغداد، هاربًا من منكلي، وسببُ ذلك أن إيدغمش كان قد تمكَّنَ في البلاد، وعظم شأنُه، وانتشر صيتُه، وكثُرَ عَسكَرُه، حتى إنَّه حصر صاحبه أبا بكر البهلوان، صاحب هذه البلاد: أذربيجان وأران، فلما كان هذا العام خرج عليه مملوكٌ اسمه منكلي، ونازعه في البلادِ، وكثر أتباعه، وأطاعه المماليكُ البهلوانية، فاستولى عليها، وهرب منه شمس الدين إيدغمش إلى ب"},{"id":2374,"era":"c7","t":"نهب أمير مكة حجاج العراق بمنى .","s":"وثب أحدُ الباطنية على بعض أهلِ الأمير قتادة، صاحِبِ مكة، فقتله بمنًى ظنًّا منه أنه قتادة، فلما سمع قتادةُ ذلك جمع الأشراف والعربَ والعبيد وأهلَ مكَّة، وقصدوا الحاجَّ، ونزلوا عليهم من الجبَلِ، ورموهم بالحجارة والنبل وغير ذلك، وكان أميرُ حجاَّج العراق ولد الأمير ياقوت وهو صبي لا يَعرِفُ كيف يفعَلُ، فخاف وتحيَّرَ، وتمكن أمير مكة من نهب الحاجِّ، فنَهَبوا منهم من كان في الأطراف، وأقاموا على حالهم إلى ا"},{"id":2375,"era":"c7","t":"وفاة الملك الأوحد صاحب خلاط .","s":"توفي الملك الأوحد نجم الدين والدنيا أيوب بن السلطان الملك العادل أبي بكر، صاحب خلاط بتركيا في أيام أبيه الملك العادل، مَلَكَ خلاط ونواحيها، فظلم وعسَف وسفك الدماء بها, وقيل إنه قتل ثمانية عشر ألف نَسَمة بخلاط عندما أخذها، فابتُلي بأمراضٍ مزمنة، فتمنى الموتَ، فمات قبل الكهولة, وكان قد استزار أخاه الملك الأشرف موسى من حران، فأقام عنده أيامًا، واشتد مرضُه فطلب الأشرف الرجوع إلى حران، فقال له الأوحدُ:"},{"id":2376,"era":"c7","t":"محاولة الأمير أسامة الجبلي الاستيلاء على دمشق .","s":"اجتمع العادل وأولاده الكامل والمعظم والفائز بدمياط من بلاد مصر في مقاتلة الفرنج، فاغتنم غيبتَهم أسامة الجبلي أحدُ أكابر الأمراء، وكانت بيدِه قلعة عجلون وكوكب فسار مسرعًا إلى دمشق ليتسلم البلدين، فأرسل العادلُ في إثره ولَدَه المعَظَّم فسبقه إلى القدسِ وحملَ عليه في كنيسة صهيون، وكان الجبلي شيخًا كبيرًا قد أصابه النقرس، فشرع المعظَّمُ يرده إلى الطاعة بالملاطفةِ فلم ينفَعْ فيه، فاستولى على حواصله وأم"},{"id":2377,"era":"c7","t":"قدوم ابن منكلي بغداد .","s":"قدم محمد بن منكلي المستولي على بلاد الجبل إلى بغداد، وسببُ ذلك أنَّ أباه منكلي لَمَّا استولى على بلاد الجبل وهرب إيدغمش صاحبها منها إلى بغداد خاف أن يساعِدَه الخليفة، ويرسِل معه العساكر، فيَعظُم الأمر عليه؛ لأنَّه لم يكن قد تمكَّن في البلاد، فأرسل ولده محمدًا ومعه جماعةٌ من العسكر، فخرج النَّاسُ ببغداد على طبقاتِهم يلتقونَه، وأُنزِلَ وأُكرِمَ، وبَقِيَ ببغداد إلى أن قُتِلَ منكلي إيدغمش بهمذان سنة ع"},{"id":2378,"era":"c7","t":"هزيمة الموحدين في موقعة العقاب بالأندلس .","s":"انهزم الموحِّدون في وقعةِ العقاب أمام جيوشِ الأسبان من قشتالة وليون ونافار المتحالفة بقيادة ألفونسو الثامن ملك قشتالة، وهذه المعركة وقَعَت قُربَ حِصنِ العقاب في الخامسَ عشَر مِن صفر. لَمَّا انتهت الهدنة مع الفرنج، عبَرَ السلطان الناصر بجيوشه إلى إشبيلية, ثم تحرَّك في سنة 608 لجهادهم، فنازل حصنًا لهم فأخذه، فسار ألفونسو في أقاصي الممالك يستنفر عبَّاد الصليب، فاجتمَعَت له جيوش ما سُمِعَ بمِثلِها، ون"},{"id":2379,"era":"c7","t":"قتل إيدغمش صاحب همذان .","s":"هو شمسُ الدين إيدغمش صاحب همذان وأصبهان والري. كان قد تمكن وعَظُم أمرُه، وبَعُد صيتُه، وكثُرَ جَيشُه إلى أن حصر ابن أستاذه أبا بكر بن البهلوان صاحب أذربيجان، فلما كان في سنة ثمان وستمائة خرج عليه أحدُ مماليكه اسمه منكلي ونازعه في البلاد، وأطاعته المماليكُ البهلوانية. فهرب أيدغمش سنة ثمانٍ إلى بغداد وأقام بها، فأنعم عليه الخليفةُ، وشَرَّفه بالخِلَع، ثمَّ سَيَّرَه إلى همذان، فسار إيدغمش في جمادى الآ"},{"id":2380,"era":"c7","t":"وفاة الناصر حاكم الموحدين بالمغرب والأندلس .","s":"هو السلطانُ أبو عبد الله الملك الناصر محمد بن يعقوب المنصور بالله يوسف بن عبد المؤمن بن علي القيسي, أميرُ الموحدين، وأمُّه رومية اسمها زهر. بويعَ له بعد أبيه سنة 595 بعهدٍ من أبيه، وكان أشقَرَ أشهَلَ أسيل الخَدِّ مليح الشكل، كثير الصمتِ والإطراق، شجاعًا مَهيبًا بعيدَ الغور، حليمًا عفيفًا عن الدماء، وفي لسانه لثغةٌ، وكان بخيلًا، وله عِدَّة أولاد. استوزر أبا زيد بن يوجان، ثم عزله، واستوزر الأمير إبر"},{"id":2381,"era":"c7","t":"خوارزم شاه يمتلك مدينة كرمان ومكران والسند .","s":"كان من جملة أمراء خوارزم شاه تكش والد خوارزم شاه محمد, أميرٌ اسمُه أبو بكر، ولقَبُه تاج الدين، وكان في ابتداءِ أمرِه جمَّالًا يكري الجمالَ في الأسفار، ثم جاءته السعادة، فاتصل بخوارزم شاه، وصار سيروانَ جمالِه، فرأى منه جلدًا وأمانةً، فقَدَّمَه إلى أن صار من أعيانِ أمراءِ عَسكَرِه، فولَّاه مدينة زوزن، وكان عاقلًا ذا رأي وحزمٍ وشجاعة، فتقَدَّم عند خوارزم شاه تقدمًا كثيرًا، فوَثِقَ به أكثَرَ مِن جميع "},{"id":2382,"era":"c7","t":"تبليط داخل الجامع الأموي .","s":"شُرِعَ في تبليطٍ داخل الجامع الأموي وبدؤوا من ناحيةِ السبع الكبير، وكانت أرضُ الجامع قبل ذلك حُفرًا وجورًا، فاستراح النَّاسُ بتبليطِه."},{"id":2383,"era":"c7","t":"أخذ المعظم قلعة صرخد من ابن قراجا .","s":"أخذ المُعظَّم قلعة صرخد من ابن قراجا وعَوَّضَه عنها وسَلَّمَها إلى مملوكه عز الدين أيبك المعظمي، فثبَتَت في يده إلى أن انتزعها منه نجمُ الدين أيوب سنة 644."},{"id":2384,"era":"c7","t":"طرد الملك العادل أمير مكة منها .","s":"حجَّ الملك المعَظَّم بنُ العادلِ فرَكِبَ مِن الكرك على الإبل في حادي عشر ذي القعدة، ومعه ابن موسك ومملوك أبيه وعز الدين أستاذ داره وخَلْقٌ، فلما قدم المدينةَ النبويَّةَ تلقَّاه صاحبُها سالم وسَلَّمَ إليه مفاتيحَها وخَدَمه خدمةً تامَّةً، وأمَّا صاحب مكة قتادةُ فلم يرفَعْ به رأسًا؛ ولهذا لما قضى نسُكَه، وكان قارنًا، وأنفق في المجاورين ما حمَلَه إليهم من الصَّدَقاتِ، وكَرَّ راجعًا؛ استصحب معه سالِمًا"},{"id":2385,"era":"c7","t":"تملك أضسيس اليمن بعد وفاة أيوب بن طغتكين  .","s":"لما مات صاحب اليمن أيوب بن طغتكين تولى بعده سليمان بن شاهنشاه بن تقي الدين عمر بن شاهنشاه بن أيوب باتِّفاق الأمراء عليه، فأرسل العادِلُ إلى ولده الكامِلِ أن يرسِلَ إليها ولده أضسيس (ومعناه ما له اسم) وتسمَّى بالمسعودِ صلاح الدين يوسف، فخرج في جيش كثيفٍ من مصر، وسار إلى بلاد اليمن، فاستولى على معاقلِها، وظَفِرَ بصاحبها الملك سليمان شاهنشاه, فسَيَّرَه تحت الحوطة إلى مصر، فتمَلَّك أضسيس اليمن فظَلَم "},{"id":2386,"era":"c7","t":"عدوان فرنج قبرص وعكا وطرابلس وأنطاكية على المسلمين .","s":"تجمع فرنج قبرص وعكا وطرابلس وأنطاكية، وانضم إليهم عسكرُ ابن ملك الأرمن؛ لقصد بلاد المسلمين، فخافهم المسلمون، وكان أول ما بدؤوا به بلاد الإسماعيلية، فنازلوا قلعةَ الخوابي وجدُّوا في حصارها، وكانوا حانقين على الإسماعيلية؛ بسبب قتلهم ابن البرنس صاحب أنطاكية؛ شابٍّ في الثامنة عشرة من العمر، وثبوا عليه العام الماضي فقتلوه، فخرج الملك الظاهر بعسكَرِه ليدافِعَ عن القلعة، فترحَّلت الفرنجُ ثم ساروا عنها إل"},{"id":2387,"era":"c7","t":"القتال بين أمير المدينة النبوية وبين أمير مكة .","s":"حاصر الأمير قتادة أميرُ مكَّةَ المدينةَ ومن بها وقطع نخلًا كثيرًا، فقاتَلَه أهلُها فكَرَّ خائبًا خاسرًا حسيرًا، وكان صاحب المدينة بالشام فطلب مِن العادل نجدةً على أمير مكة، فأرسل معه جيشًا فأسرع في الأوبة، فمات أمير المدينة في أثناء الطريق، فاجتمع الجيشُ على ابن أخيه جماز فقصَدَ مكة فالتقاه أميرُها بالصفراء فاقتتلوا قتالًا شديدًا، فهرب المكيُّون وغَنِمَ منهم جماز شيئًا كثيرًا، وهربَ قتادةُ إلى ينب"},{"id":2388,"era":"c7","t":"مناوشات بين الفرنج والمسلمين .","s":"أغارت الفرنج على بلاد الإسماعيلية فقتلوا ونهبوا ثم اصطلحوا، وأخذ مَلِكُ بلاد الروم عزُّ الدين كيكاوس بن كيخسرو مدينة إنطاكية من أيدي الفرنجِ، ثم أخَذَها منه ابنُ لاون ملك الأرمن، ثم منه إبريس طرابلس، وسار عزُّ الدين إلى بلاد الأرمن، وحاصرَ قلعة جابان، وهزم عندها جيوش الأرمن، ورجع إلى قيصريَّة قبل أن يستوليَ على قلعة جابان، ثم طلب الأرمنُ الصلحَ، وأجابهم إليه عزُّ الدين، فأخذ في مقابلِ الصلح من بلا"},{"id":2389,"era":"c7","t":"وفاة ولي العهد الملك المعظم أبي الحسن علي بن الخليفة الناصر .","s":"هو أبو الحسَنِ عليُّ بن الخليفة الناصر لدين الله أحمد بن المستضيء بأمر الله، وهو الأصغر، وكان يلقَّب الملك المعظم، وكان أحبَّ ولدي الخليفة إليه، وقد رشَّحه لولاية العهد بعده، وعزَلَ ولده الأكبر عن ولاية العهدِ؛ لأجل أبي الحسن علي, وكان كريمًا كثير الصدقة والمعروف، حَسَن السيرة، محبوبًا إلى الخاص والعام، وكان سببُ موتِه أنَّه أصابه إسهالٌ فتوفِّيَ، وحَزِنَ عليه الخليفةُ حُزنًا لم يُسمَعْ بمثله، حتى"},{"id":2390,"era":"c7","t":"مقتل منكلي وولاية أغملش .","s":"انهزم منكلي صاحب همذان وأصفهان والري وما بينهما من البلاد، ومضى هاربًا، فقُتِلَ، وسَبَبُ ذلك أنَّه كان قد ملكَ البلاد، وقتل إيدغمش فأُرسلَ إليه من الديوان الخليفي رسولٌ ينكِرُ ذلك عليه، وكان قد أوحش الأمير أوزبك بن البهلوان، صاحب أذربيجان، فأرسل الخليفةُ إليه يحَرِّضُه على منكلي ويَعِدُه النصرةَ، وأرسل أيضًا إلى جلال الدين الإسماعيلي، صاحِبِ قلاع الإسماعيلية ببلاد العجم، ألموت وغيرها، يأمرُه بمساع"},{"id":2391,"era":"c7","t":"خوارزم شاه  يمتلك مدينة غزنة وأعمالها .","s":"ملك خوارزم شاه محمد بن تكش مدينة غزنة وأعمالها، وسببُ ذلك أنَّ خوارزم شاه لَمَّا استولى على عامَّة خراسان وملك باميان وغيرها، أرسلَ إلى تاج الدين، صاحبِ غزنة، يطلُبُ منه أن يخطُبَ له، ويضرِبَ السِّكَّة باسمه، ويرسِلَ إليه فيلًا واحدًا ليصالِحَه ويقِرَّ بيده غزنة، ولا يعارِضه فيها، فأحضر الأمراءَ وأعيانَ دولته واستشارهم، فخطب لخوارزم شاه، وضَرَب السكة باسمِه، وأرسل إليه فيلًا، وأعاد رسولَه إليه، وم"},{"id":2392,"era":"c7","t":"وقوع بَرَد شديد بالبصرة وهبوب ريح سوداء شديدة ببغداد .","s":"وقع بالبصرة بَرَد كثير، وهو مع كثرتِه عظيمُ القَدرِ، قيل: كان أصغرُه مثل النارنجة- نوع من الليمون- الكبيرة، وقيل في أكبرِه ما يستحي الإنسانُ أن يذكُرَه، فكسر كثيرًا من رؤوسِ النخيل. وفي صفَر من نفس العام هبَّت ببغداد ريحٌ سوداءُ شديدة، كثيرةُ الغبار والقتام، وألقت رملًا كثيرًا، وقلعت كثيرًا من الشَّجَر، فخاف الناسُ وتضَرَّعوا، ودامت من العشاءِ الآخرة إلى ثلث الليل ثم انكشَفَت."},{"id":2393,"era":"c7","t":"وفاة الملك الظاهر غازي بن صلاح الدين صاحب حلب .","s":"هو المَلِكُ الظاهر غازي بن صلاح الدين يوسف بن أيوب، وهو صاحِبُ مدينة حلب ومنبج وغيرهما من بلاد الشام، وكان مرضُه إسهالًا، وكان شديد السيرة، ضابطًا لأموره كلِّها، ولَمَّا اشتدت علتُه عهد بالملك بعده لولد له صغيرٍ اسمه محمد، ولقَّبَه الملك العزيز غياث الدين، عُمُره ثلاثُ سنين، وعدَلَ عن ولد كبير لأنَّ الصغيرَ كانت أمه ابنة عمه الملك العادل أبي بكر بن أيوب، صاحب مصر ودمشق وغيرهما من البلاد، فعَهِدَ ب"},{"id":2394,"era":"c7","t":"خوارزم شاه يمتلك بلد الجبل .","s":"سار خوارزم شاه علاء الدين محمد بن تكش إلى بلاد الجَبَل فمَلَكَها، وكان سببُ حركتِه في هذا الوقت عِدَّة أمور؛ أحدها: أنه كان قد استولى على ما وراء النهر، وظَفِرَ بالخطا، وعَظُم أمره، وعلا شأنه، وأطاعه القريبُ والبعيد، ومنها: أنه كان يهوى أن يُخطَبَ له ببغداد، ويُلَقَّب بالسلطان، ومنها: أن أغلمش لَمَّا ملك بلاد الجبل خطب له فيها جميعِها، فلما قتَلَه الباطنية غَضِبَ له، وخرج لئلا تخرُجَ البلاد عن طاع"},{"id":2395,"era":"c7","t":"قدوم خوازم شاه إلى بغداد طالبا السلطنة .","s":"قَدِمَ السلطانُ علاء الدين خوارزم شاه محمد بن تكش من همدان قاصدًا بغداد في أربعمائة ألف مقاتل، وقيل في ستمائة ألف، فاستعَدَّ له الخليفة واستخدم الجيوَش وأرسل إلى الخليفةِ يطلُبُ منه أن يكون بين يديه على قاعدةِ مَن تقَدَّمه من الملوك السلاجقة، وأن يَخطُبَ له ببغداد، فلم يجِبْه الخليفة إلى ذلك، وأرسل إليه الشيخ شهاب الدين السهروردي، فلما وصل شاهدَ عند خوارزم شاه من العظمةِ وكثرة الملوك بين يديه وأخذ"},{"id":2396,"era":"c7","t":"انقضاء الهدنة مع الفرنج وغزوهم بلاد الشام .","s":"وصلت أمداد الفرنج في البحر من روميَّة الكبرى وغيرها من بلاد الفرنج في الغرب والشمال، إلَّا أن المتولي لها كان صاحب رومية؛ لأنَّه يتنزل عند الفرنج بمنزلة عظيمةٍ، لا يرون مخالفةَ أمره ولا العُدولَ عن حُكِمهِ فيما سَرَّهم وساءهم، فجهَّز العساكرَ مِن عنده مع جماعةٍ مِن مقَدَّمي الفرنج، وأمَرَ غيرَه من ملوكِ الفرنج إمَّا أن يسير بنفسِه، أو يرسِلَ جيشًا، ففعلوا ما أمَرَهم، فاجتمعوا بعكَّا من ساحل الشام،"},{"id":2397,"era":"c7","t":"حصر الفرنج قلعة الطور وتخريبها .","s":"لما نزل الفرنج بمرج عكَّا تجَّهزوا، وأخذوا معهم آلةَ الحصار من مجانيقَ وغيرها، وقصدوا قلعةَ الطور، وهي قلعةٌ منيعة على رأس جبلٍ بالقرب من عكا العادل قد بناها عن قريبٍ، فتقدموا إليها وحصروها وزحفوا إليها، وصَعِدوا في جبلها حتى وصلوا إلى سورها، وكادوا يملِكونه، فاتَّفق أن بعض المسلمين ممَّن فيها قتَل بعضَ ملوكهم، فعادوا عن القلعة فتركوها، وقصدوا عكَّا، وكانت مدة مُقامهم على الطور سبعة عشر يومًا، ولَ"},{"id":2398,"era":"c7","t":"قيام فتنة ببغداد بين أهل المأمونية وبين أهل باب الأزج .","s":"وقعت ببغداد فتنة بين أهل المأمونية وبين أهل باب الأزج بسبب قتل سبع؛ وزاد الشرُّ بينهم، واقتتلوا، فجُرح بينهم كثير، فحضر نائبُ الباب وكفَّهم عن ذلك، فلم يقبلوا ذلك، وأسمعوه ما يكرَهُ، فأُرسِل من الديوان أميرٌ من مماليك الخليفة، فرَدَّ أهل كل محلَّة إلى محلَّتِهم، وسكنت الفتنةُ."},{"id":2399,"era":"c7","t":"قصد كيكاوس ولاية حلب .","s":"سار عز الدين كيكاوس بن كيخسرو ملك بلاد الروم إلى ولاية حلب؛ قصدًا للتغلُّب عليها، ومعه الأفضلُ بن صلاح الدين يوسف، حيث كان أشار عليه ذوو الرأيِ من أصحابه، وقالوا له: لا يتِمُّ لك هذا إلا بأن يكون معك أحدٌ من بيت أيوب لِيسهلَ على أهل البلاد وجُندِها الانقياد إليه؛ وهذا الأفضَلُ بن صلاح الدين هو في طاعتك، فأحضر الأفضل من سميساط إليه، واستقَرَّت القواعد بينهما أن يكون ما يفتحه من حلب وأعمالها للأفضل،"},{"id":2400,"era":"c7","t":"حصر الفرنج دمياط  .","s":"لما عاد الفرنجُ من حصار الطور أقاموا بعكَّا إلى أن دخلت هذه السَّنةُ، فساروا في البحرِ إلى دمياط، فوصَلوا في صفر، فأرسوا على بر الجيزة، بينهم وبين دمياط النيل، فإنَّ بعض النيل يصب في البحر المالح عند دمياط، وقد بني في النيل برجٌ كبير منيع، وجعلوا فيه سلاسِلَ من حديد غلاظ، ومدُّوها في النيل إلى سورِ دمياط لتَمنَعَ المراكِبَ الواصلة في البحرِ المالح أن تصعَدَ في النيل إلى ديار مصر، ولولا هذا البرجُ "},{"id":2401,"era":"c7","t":"وفاة الملك القاهر صاحب الموصل وتملك ولده بعده .","s":"هو المَلِكُ القاهر عزُّ الدين مسعود بن أرسلان شاه بن مسعود بن مودود بن زنكي بن آقسنقر، صاحِبُ الموصل، توفِّيَ ليلة الاثنين لثلاثٍ بقِينَ من شهر ربيع الأول، وكانت ولايتُه سبع سنين وتسعة أشهر، وكان سبب موته أنَّه أخذته حمى، ثم فارقته الغد، وبقي يومينِ موعوكًا، ثم عاودته الحُمَّى مع قيءٍ كثير، وكربٍ شديد، وقلق متتابعٍ، ثم برد بدَنُه، وعَرقَ، وبَقِيَ كذلك إلى وسط الليل، ثم توفِّيَ، وقيل مات مسمومًا، و"},{"id":2402,"era":"c7","t":"وفاة أم المؤيد زينب بنت الشعري\n  .","s":"هي أم المؤيد زينبُ بنت أبي القاسم عبد الرحمن بن الحسن بن أحمد بن سهل بن أحمد بن عبدوس الجرجاني الأصل النيسابوري الدار، الصوفي المعروف بالشعري- وتدعى حرة- وُلِدَت سنة 524 بنيسابور، وكانت عالمة، وأدركت جماعة من أعيان العلماء، وأخذت عنهم رواية وإجازة. سمعت من أبي محمد إسماعيل بن أبي القاسم ابن أبي بكر النيسابوري القارئ، وأبي القاسم زاهر وأبي بكر وجيه ابني طاهر الشحاميين، وأبي المظفر عبد المنعم بن عبد"},{"id":2403,"era":"c7","t":"وفاة الملك العادل سيف الدين أبو بكر الأيوبي .","s":"هو الملك العادل سيف الدين أبو بكر محمد بن أبي الشكر أيوب بن شاذي بن يعقوب بن مروان الدويني، ثم التكريتي، ثم الدمشقي. وُلِدَ ببعلبك في سنة 534، وهو أصغَرُ من أخيه السلطان صلاح الدين بسنتين. وقيل: وُلِدَ بدمشق سنة ثمان وثلاثين. وقيل: ولد سنة أربعين. وهو أحد ملوك الدولة الأيوبية. لما ملك صلاح الدين الديار المصرية كان العادل ينوب عنه في حال غيبته في الشام، ويستدعي منه الأموال للإنفاق على الجند وغيرهم."},{"id":2404,"era":"c7","t":"القتال بين جنكيزخان وخوارزم شاه في بلاد ما وراء النهر .","s":"كان سبب غزو جنكيز خان لِما وراءَ النَّهرِ هو أن خوارزم شاه محمد قد بدأ يأخذ أموال التجار الذين من طرف جنكيز خان ثم زاد الأمرُ أن قتل سفير جنكيز نفسه الذي جاء من أجل إعادة تلك الأموال، فأثار ذلك غضب جنكيز الذي جهز العساكِرَ من فوره، وانطلق إلى خوارزم شاه فوقع بينهما ما وقع."},{"id":2405,"era":"c7","t":"هزيمة عماد الدين زنكي بن مودود من العسكر البدري .","s":"كان عسكر البدري يحاصر العماديَّة وبها عمادُ الدين زنكي بن مودود، فلمَّا عاد العسكرُ عنها قَوِيَت نفسُه وفارقها، وعاد إلى قلعة العقر التي له ليتسَلَّط على أعمال المَوصِل بالصحراء، فإنَّه كان قد فرغ من بلدِ الجبل، وأمدَّه مظفر الدين بطائفةٍ كثيرة من العسكَر. ولَمَّا اتَّصل الخبَرُ ببدر الدين لؤلؤ أتابك صاحِبِ الموصل سيَّرَ طائفةً من عسكره إلى أطراف الموصِل يحمونَها، فأقاموا على أربعة فراسخ من الموصل"},{"id":2406,"era":"c7","t":"ظهور المغول التتر وقتالهم مع المسلمين .","s":"ظهر التترُ إلى بلاد الإسلام، وهم نوع كثير من الترك، ومساكنُهم جبالُ طمغاج من نحو الصين، وكان السبب في ظهورِهم أنَّ مَلِكَهم- ويسمى بجنكيزخان، المعروف بتموجين- كان قد فارق بلاده وسار إلى نواحي تركستان، وسيَّرَ جماعة من التجار والأتراك، ومعهم شيءٌ كثير من النقرة- قطع مذابةُ من الذَّهب أَو الفِضَّة- وغيرِها، إلى بلاد ما وراء النهر سمرقند وبخارى؛ ليشتروا له ثيابًا للكسوة، فوصلوا إلى مدينة من بلاد التر"},{"id":2407,"era":"c7","t":"وفاة الملك المنصور قطب الدين محمد بن زنكي وملك ابنه .","s":"هو الملك المنصور قطب الدين محمد بن زنكي بن مودود بن عماد الدين زنكي، صاحب سنجار، وكان كريمًا، حسنَ السيرة في رعيته، حسَنَ المعاملة مع التجَّار، كثيرَ الإحسان إليهم، وأمَّا أصحابه فكانوا معه في أرغد عيش؛ يعُمُّهم بإحسانه، ولا يخافون أذاه، وكان عاجزًا عن حفظ بلده، مسلِّمًا الأمورَ إلى نوابه, ولما توفِّيَ قطب الدين مَلَك بعده ابنُه عماد الدين شاهنشاه، وركب الناسُ معه، وبقي مالكًا لسنجار عدةَ شهور، وس"},{"id":2408,"era":"c7","t":"وفاة الحافظ أبو الحسن بن عساكر .","s":"هو أبو الحسن علي بن أبي محمد القاسم بن علي بن الحسن بن عبد الله الدمشقي، الحافِظُ بن الحافظ بن الحافظ، المعروف بابن عساكر، وكان قد قصد خراسانَ وسَمِعَ بها الحديثَ فأكثر، وعاد إلى بغداد، وكان قد وقع على القفل- الحمل- الذي هو فيه، في الطريق حرامية، وجرحوا ابن عساكر، ووصل على تلك الحال إلى بغداد، وبقي بها حتى توفي في هذه السنة في جمادى الأولى."},{"id":2409,"era":"c7","t":"الصليبيون يحتلون دمياط (الحملة الصليبية الخامسة) .","s":"تعتبر هذه الهجمة هي الحملة الصليبية الخامسة على المسلمين؛ حيث اجتمع رأي الفرنج على الرحيل من عكا إلى مصر، والاجتهاد في تملُّكِها، فأقلعوا في البحر، وأرسَوا على دمياط، في يوم الثلاثاء رابع شهر ربيع الأول سنة 515 على بر جيزة دمياط، وصار الفرنجُ في غربي النيل، فأحاطوا على معسكَرِهم خندقًا، وبنوا بدائره سورًا، وأخذوا في محاربة أهل دمياط، وعملوا آلات ومرمات، وأبراجًا متحركة يزحفون بها في المراكب إلى بر"},{"id":2410,"era":"c7","t":"وفاة السلطان كيكاوس صاحب بلاد الروم وملك كيقباذ أخيه .","s":"هو صاحب بلاد الروم السلطان الملك الغالب عز الدين كيكاوس بن السلطان كيخسرو بن قلج رسلان السلجوقي التركماني القتلمشي، صاحب قونية وأقصرا وملطية. وهو أخو السلطان كيقباذ. كان جبارًا، سفاكًا للدماء، كسره المَلِك الأشرف لَمَّا قدم ليأخذ حلب وقت الملك الظاهر غازي، فاتهم أمراءه أنهم ما نصحوا في القتال. وسلقَ جماعةً في القدورِ، وحرقَ آخرين، فأخذه الله فُجاءةً وهو مخمورٌ، وقيل: ابتلي وتقطَّعَ بَدَنُه. وكان أ"},{"id":2411,"era":"c7","t":"وفاة الأميرة ست الشام بنت أيوب أخت الناصر صلاح الدين الأيوبي .","s":"هي الست الجليلة المصونُ خاتون ست الشام بنت أيوب بن شادي، واقفةُ المدرستين البرَّانية والجُوَّانية, وهي أختُ الملوك وعمَّةُ أولادهم، وأمُّ الملوك، كان لها من الملوك المحارم خمسة وثلاثون ملكًا، منهم أشقاؤها: الملك الناصر صلاح الدين، والملك العادل، والمعظم توران شاه بن أيوب صاحب اليمن، وكانت قد تزوجت ابن عمِّها ناصرَ الدين محمد بن أسد الدين شيركوه بن شادي صاحب حمص بعد عمر بن لاجين والد ابنها حسام، وك"},{"id":2412,"era":"c7","t":"إجلاء بني معروف عن البطائح وقتلهم .","s":"أمر الخليفة الناصر لدين الله الشريف معدًّا، متولي بلاد واسط، أن يسير إلى قتال بني معروف، فتجهز وجمع معه من الرجَّالة من تكريت، وهيت، والحديثة، والأنبار، والحلة، والكوفة، وواسط، والبصرة، وغيرها، خلقًا كثيرًا، وسار إليهم، ومُقَدَّمهم حينئذ معلى بن معروف، وهم قوم من ربيعة, وكانت بيوتهم غربي الفرات، تحت سوراء، وما يتَّصل بذلك من البطائح، وكثُرَ فسادهم وأذاهم لما يقاربهم من القرى، وقطعوا الطريقَ، وأفسد"},{"id":2413,"era":"c7","t":"المغول يغيرون على بخارى ويذبحون أهلها .","s":"لما نشب القتالُ مع المغول أمر خوارزم شاه بتحصين بخارى وسمرقند, ثم قفل ليجمع العساكِرَ من الأنحاء لقتال المغول، فلما فرغ من ذلك رحل عائدًا إلى خراسان، فعبر جيحون، ونزل بالقرب من بلخ فعسكر هناك، وأمَّا الكُفَّار فإنهم رحلوا بعد أن استعدوا يطلبون ما وراء النهر، فوصلوا إلى بخارى بعد خمسة أشهر من وصول خوارزم شاه، وحصروها، وقاتلوها ثلاثة أيام قتالًا شديدًا متتابعًا، فلم يكن للعسكر الخوارزمي بهم قوة، ففا"},{"id":2414,"era":"c7","t":"ذكر خروج التتار إلى بلاد الإسلام وإهلاكهم الحرث والنسل ووصف ابن الأثير لأفعالهم .","s":"في هذه السنة عمَّ البلاء وعظُمَ العزاء بجنكيزخان المسمى بتموجين وقيل (تمرجين) لعنه الله تعالى، ومن معه من التتر قبَّحهم الله أجمعين، واستفحل أمرُهم واشتد إفسادُهم من أقصى بلاد الصين إلى أن وصلوا بلاد العراق وما حولها حتى انتهوا إلى إربل وأعمالها، فمَلَكوا في سنة واحدة وهي هذه السنة سائر الممالك المشرق، وقهروا جميع الطوائفِ التي بتلك النواحي الخوارزمية والقفجاق والكرج واللان والخزر وغيرهم، وقتلوا ف"},{"id":2415,"era":"c7","t":"المغول يغيرون على سمرقند ويذبحون أهلها .","s":"بعد استيلاء المغول على بخارى وما كان فيها منهم رحلوا نحو سمرقند وقد تحقَّقوا عجز خوارزم شاه عنهم، وهم بمكانه بين ترمذ وبلخ، واستصحبوا معهم من سَلِمَ من أهل بخارى أسارى، فساروا بهم مشاةً على أقبح صورة، فكلُّ من أعيا وعجز عن المشي قتلوه، فلما قاربوا سمرقند قدَّموا الخيَّالة، وتركوا الرجَّالة والأسارى والأثقال وراءهم، حتى تقدموا شيئًا فشيئًا، ليكون أرعبَ لقلوب المسلمين؛ فلما رأى أهل البلد سوادهم استع"},{"id":2416,"era":"c7","t":"محاولة الفرنج التوسع في احتلال أراضي مصر بعد احتلالهم دمياط .","s":"لَمَّا ثبت الفرنج في دمياط بثُّوا سراياهم في القرى يقتلون ويأسرون، فعظُم الخطب واشتدَّ البلاء، وندب السلطانُ الملك الكامل الناسَ وفَرَّقهم في الأرض، فخرجوا إلى الآفاق يستصرخون النَّاسَ لاستنقاذ أرض مصر من أيدي الفرنج، وشرع الكاملُ في بناء الحور –خيام من جلد أبيض- والفنادق والحمامات والأسواق بمنزلة المنصورةِ، وجهَّزَ الفرنج من حصل في أيديهم من أسارى المسلمين في البحرِ إلى عكا وبرزوا من مدينةِ دمياط"},{"id":2417,"era":"c7","t":"وفاة السلطان علاء الدين محمد خوارزم شاه .","s":"هو السُّلطانُ علاء الدين خوارزم شاه محمد بن تكش بن إيل أرسلان بن آتسز بن محمد بن نوشتكين. نسبه ينتهي إلى إيلتكين أحد مماليك السلطان ألب أرسلان بن جغر بيك السلجوقي. أباد ملوك العالم، ودانت له الممالك واستولى على الأقاليم. كان صبورًا على التعب وإدمان السير، غير متنَعِّم ولا مقبل على اللذات، إنما نهمتُه في المُلك وتدبيره وحِفظِه وحِفظِ رعيَّتِه. كان فاضِلًا، عالِمًا بالفقه والأصول، وغيرهما. وكان مكرم"},{"id":2418,"era":"c7","t":"استيلاء التتار على كثير من البلدان وما صنعوا فيها من الفظائع .","s":"بعد ما فعل المغول في سمرقند ما فعلوه أخذ جنكيزخان يرسِلُ السَّرايا إلى البلدانِ فأرسل سريةً إلى بلاد خراسان وتسميها التتار المغربة، وأرسل أخرى وراء خوارزم شاه، ثم ساروا إلى مازندران وقلاعها من أمنَعِ القلاع، بحيث إن المسلمين لم يفتحوها إلَّا في سنة تسعين من أيام سليمان بن عبد الملك، ففتحها هؤلاء في أيسَرِ مُدَّة ونهبوا ما فيها وقتَلوا أهاليها كلَّهم وسَبَوا وأحرقوا، ثمَّ ترحلوا عنها نحو الريِّ فدخ"},{"id":2419,"era":"c7","t":"وفاة قتادة أمير مكة وملك ابنه الحسن .","s":"هو أميرُ مكة، قتادة بن إدريس العلوي، الحسني. كان في أول ملكه، لَمَّا ملك مكة، حرسها الله، حسنَ السيرة أزال عنها العبيد المفسِدين، وحمى البلاد، وأحسن إلى الحُجَّاج، وأكرمهم، وبقي كذلك مدة، ثم إنه بعد ذلك أساء السيرة، وجدد المكوسَ بمكة، وفعل أفعالًا شنيعة، ونهب الحاجَّ في بعض السنين، وقيل في موت قتادة إن ابنه حسنًا خنقه فمات، وسبب ذلك أن قتادة جمع جموعًا كثيرة وسار عن مكة يريد المدينة، فنزل بوادي ال"},{"id":2420,"era":"c7","t":"اقتتال أمير مكة الحسن وأخيه وقتل أمير الحجاج .","s":"لما مات أمير مكة قتادة، وملك بعده ابنه الحسن، وكان له ابن آخر اسمه راجح، مقيم في العرب بظاهر مكة، يُفسِد وينازع أخاه في ملك مكة، فلما سار حاج العراق كان الأمير عليهم مملوكًا من مماليك الخليفة الناصر لدين الله اسمه أقباش، وكان حسن السيرة مع الحاج في الطريق، كثير الحماية، فقصده راجح بن قتادة، وبذل له وللخليفة مالًا ليساعده على ملك مكة، فأجابه إلى ذلك، ووصلوا مكة، ونزلوا بالزاهر، وتقدم أقباش إلى مكة "},{"id":2421,"era":"c7","t":"انهزام الحملة الصليبية الخامسة واستعادة المسلمين دمياط .","s":"اشتَدَّ القتال بين الفرنج والمسلمين برًّا وبحرًا، وقد اجتمع من الفرنج والمسلمين ما لا يعلم عددهم إلا الله، هذا والرسُل تتردد من عند الفرنج في طلب الصلحِ بشروط: منها أخذ القدس وعسقلان وطبرية، وجبلة واللاذقية، وسائر ما فتحه السلطان صلاحُ الدين من بلاد الساحل، فأجابهم الملوك إلى ذلك، ما خلا الكرك والشوبك، فأبى الفرنجُ، وقالوا: لا نسَلِّم دمياط حتى تسلِّموا ذلك كله فرضي الكامل، فامتنع الفرنج، وقالوا: "},{"id":2422,"era":"c7","t":"نهب الكرج (الجورجيون، سكان جورجيا) بيلقان .","s":"سار الكرج من بلادهم إلى بلاد أران وقصدوا مدينة بيلقان، وكان التتار قد خربوها، ونهبوها فلما سار التتر إلى بلاد قفجاق عاد من سلم من أهلها إليها، وعَمَروا ما أمكنهم عمارته من سورها، فبينما هم كذلك إذ أتاهم الكرج ودخلوا البلد وملكوه، وكان المسلمون في تلك البلاد ألِفُوا من الكرج أنهم إذا ظفروا ببلد صانعوه بشيء من المال فيعودون عنهم، فكانوا أحسن الأعداء مقدرةً، فلما كانت هذه الدفعة ظن المسلمون أنهم يفعل"},{"id":2423,"era":"c7","t":"حج مسعود بن أقسيس صاحب اليمن وما فعله في مكة .","s":"حج الملك مسعود بن أقسيس بن الكامل صاحب اليمن، فبدت منه أفعال ناقصة بالحرمِ مِن سُكرٍ ورَشقِ حمامِ المسجِدِ بالبندق من أعلى قبَّة زمزم، وكان إذا نام في دار الإمارة يُضرَبُ الطائفون بالمسعى بأطرافِ السيوف لئلَّا يشوشوا عليه، وهو نوم سكر، وكان مع هذا كله مهيبًا محترمًا والبلاد به آمنة، وقد كاد يرفع سنجق أبيه يوم عرفة على سنجق الخليفة، فيجري بسبب ذلك فتنة عظيمة."},{"id":2424,"era":"c7","t":"الملك المسعود صاحب اليمن يستولي على مكة وينهب أهلها .","s":"سار صاحب اليمن الملك المسعود أقسيس بن الملك الكامل محمد، صاحب مصر، إلى مكة وصاحبها حينئذ حسن بن قتادة بن إدريس، العلوي الحسيني، قد ملكها بعد أبيه، وكان حسن قد أساء إلى الأشراف والمماليك الذين كانوا لأبيه، وقد تفرقوا عنه، ولم يبق عنده غيرُ أخواله من غيره، فوصل صاحب اليمن إلى مكة، ونهبها عسكرُه إلى العصر، حتى أخذوا الثيابَ عن الناس، وأفقَروهم، وأمر صاحب اليمنِ أن ينبش قبر قتادة الأمير السابق ويُحرَق"},{"id":2425,"era":"c7","t":"وفاة الإمام فخر الدين ابن عساكر الشافعي .","s":"هو الشيخ الإمام العالم القدوة المفتي شيخ الشافعية: فخر الدين، أبو منصور عبد الرحمن بن محمد بن الحسن بن هبة الله بن عبد الله الدمشقي، الشافعي. ولد سنة 550, وسمع من عميه؛ الصائن والحافظ، وتفقه على قطب الدين مسعود النيسابوري، وتزوج بابنته، وجاءه ولد منها، سماه مسعودًا. درَّس بالجاروخية، ثم بالصلاحية بالقدس، وبالتقوية بدمشق، فكان يقيم بالقدس أشهرًا، وبدمشق أشهرًا، وكان عنده بالتقوية فضلاء البلد، حتى ك"},{"id":2426,"era":"c7","t":"حرب بين المسلمين والكرج (الجورجيون، سكان جورجيا) بأرمينية .","s":"سار شهاب الدين غازي بن الملك العادل أبي بكر بن أيوب صاحب قلعة سرماري، وهي من أعمال أرمينية إلى خلاط، لأنه كان في طاعة صاحب خلاط، فحضر عنده، واستخلف ببلده أميرًا من أمرائه، فجمع هذا الأمير جمعًا وسار إلى بلاد الكرج، فنهب منها عدة قرى وعاد، فسمعت الكرج بذلك، فجمع صاحب دوين، واسمه شلوة، وهو من أكابر أمراء الكرج، عسكره وسار إلى سرماري فحصرها أيامًا، ونهب بلدها وسوادها ورجع، فسمع صاحب سرماري شهاب الدين"},{"id":2427,"era":"c7","t":"وفاة الإمام العلامة موفق الدين ابن قدامة المقدسي الحنبلي .","s":"هو الإمامُ العلَّامة البارع الفقيه أبو محمد موفق الدين عبد الله بن أحمد بن محمد بن قدامة بن مقدام بن نصر المقدسي، الجماعيلي، الدمشقي، الصالحي، الحنبلي، صاحب (المُغني). ولد بجماعيل، من عمل نابلس، في شعبان سنة 541. صاحب كتاب المغني المشهور في المذهب الحنبلي، قدم مع أهله إلى دمشق في سنة إحدى وخمسين، وهو ابن عشر سنوات ومعه ابن خاله الحافظ عبد الغني, وقرأ القرآن وسمع الحديث الكثير، ورحل مرتين إلى العرا"},{"id":2428,"era":"c7","t":"وفاة المنتصر بالله أبي يعقوب يوسف المؤمني صاحب المغرب .","s":"هو المنتصر بالله- وقيل المستنصر بالله أبو يعقوب يوسف بن محمد الناصر بن يعقوب المنصور بن يوسف بن عبد المؤمن بن علي. ولد سنة 594، وأمه أم ولد، اسمها قمر الرومية، وكان يشبه بجَدِّه. تولى الملك بعد وفاة أبيه يقول الذهبي: \"فملكوه وله ست عشرة سنة، فضيعوا أمرَ الأمة، وكان بديع الحسن، بليغ المنطق، غارقًا في وادي اللهو والبطالة\" فغلب عليه وزراؤه واشتغل المنتصرُ بما يستهويه, وفي عهده استولى الأسبان في الأند"},{"id":2429,"era":"c7","t":"غياث الدين بن خوارزم يمتلك بلاد فارس .","s":"كان غياث الدين بن خوارزم شاه محمد بالري، وله معها أصفهان وهمذان وما بينهما من البلاد، وله أيضًا بلادُ كرمان، فلما هلك أبوه، وصل التترُ إلى بلاده، وامتنع بأصفهان، وحصره التترُ فيها فلم يقدروا عليها، فلما فارق التتر بلادَه، وساروا إلى بلاد قفجاق، عاد ملك البلاد وعَمَر ما أمكَنَه منها، وأقام بها إلى أواخر سنة 620، فسار إلى بلاد فارس فلم يشعُرْ صاحبُها، وهو أتابك سعد بن دكلا، إلا وقد وصل غياث الدين إل"},{"id":2430,"era":"c7","t":"عود طائفة من التتار إلى الري وهمذان وغيرهما .","s":"أول هذه السنة وصلت سرية للريِّ من التتر من عند مَلكِهم جنكيزخان، وهؤلاء غيرُ الطائفة الغربية، وكان من سَلِمَ من أهلها قد عادوا إليها وعَمَروها، فلم يشعروا بالتتر إلا وقد وصلوا إليها، فلم يمتَنِعوا عنهم، فوضعوا في أهلها السيفَ وقتلوهم كيف شاؤوا، ونهبوا البلد وخَرَّبوه، وساروا إلى ساوة ففعلوا بها كذلك، ثمَّ إلى قم وقاشان، وكانتا قد سَلِمَتا من التتر أولًا، فإنَّهم لم يقربوهما، ولا أصاب أهلَهما أذًى،"},{"id":2431,"era":"c7","t":"حصر الكرج (الجورجيون، سكان جورجيا) مدينة كنجة .","s":"سارت الكرج (وهم قوم كفار) في جموعِها إلى مدينة كنجة من بلاد أران قصدًا لحصرها، وأعتَدُوا لها بما أمكنهم من القوة؛ لأن أهل كنجة كثيرٌ عددهم، قويةٌ شوكتُهم، وعندهم شجاعةٌ كثيرة من طول ممارستهم للحرب مع الكرج، فلما وصلوا إليها ونازلوها قاتلوا أهلها عدة أيام من وراء السور، لم يظهر من أهلها أحد، ثم في بعض الأيام خرج أهل كنجة ومن عندهم من العسكر من البلد، وقاتلوا الكرج بظاهر البلد أشدَّ قتال وأعظَمَه، ف"},{"id":2432,"era":"c7","t":"خلع ابن شروان شاه لأبيه وظفر الأبن بالكرج (جورجيا) .","s":"ثار على شروان شاه ولده فنزع منه الملك، وأخرجه من البلاد، ومَلَك بعده، وسبب ذلك أن شروان شاه كان سيئ السيرة، كثيرَ الفساد والظلم، يتعرض لأموال الرعايا وأملاكهم، وقيل أيضًا: إنه كان يتعرض للنِّساء والولدان، فاشتدت وطأتُه على الناس، فاتفق بعضُ العسكر مع ولده، وأخرجوا أباه من البلاد، وملك الابن وأحسن السيرة، فأحبه العساكر والرعيَّة، وأرسل الولد إلى أبيه يقول له: إني أردتُ أن أتركك في بعض القلاعِ وأجري"},{"id":2433,"era":"c7","t":"محاصرة الكرج (الجورجيون، سكان جورجيا) لأذربيجان .","s":"سار جمع من الكرج الكفار من تفليس يقصدون أذربيجان والبلاد التي بيد أوزبك بن البهلوان، فنزلوا وراء مضيقٍ في الجبال لا يسلك إلا للفارس بعد الفارس، فنزلوا آمنين من المسلمين استضعافًا لهم، واغترارًا بحصانة موضعِهم، وأنه لا طريقَ إليهم، وركب طائفةٌ من العساكر الإسلامية وقصدوا الكرج، فوصلوا إلى ذلك المضيق، فجاوزوه مخاطرينَ، فلم يشعر الكرج إلا وقد غَشِيَهم المسلمون ووضعوا فيهم السيفَ فقتلوهم كيف شاؤوا، وو"},{"id":2434,"era":"c7","t":"تخلي الموحدين عن إسبانيا وقيام عدة دويلات .","s":"كانت دولة الموحِّدين قد قَوِيَت أولًا في إسبانيا، ولكنها لم تستطع أن تقف لوحدها في وجه التوسع الصليبي بصورة دائمة، كما لم يدُمْ صمودهم طويلًا إثر ذلك النصر الذي أحرزوه في معركة الأرك سنة 591 فقد جاءت هزيمتهم الماحقة في معركة العقاب سنة 609 على أيدي تحالف ملوك الصليبيين في إيبيريا، والذي نجم عنه انسحاب الموحدين نهائيًّا من إسبانيا وانكماش آخر سلاطينهم إلى المغرب، وضَعْف شوكتهم عمومًا حتى في المغرب."},{"id":2435,"era":"c7","t":"عودة جنكيزخان إلى منغوليا بعد أن قضى على دولة خوارزم .","s":"بعد أن قضى جنكيزخان على دول خوارزم شاه وفعل ما فعله من القبائح والرذائل، عاد إلى بلاده وخاصة أنه سمع أنَّه قد ثار عليه فيها البعضُ يريدون إزالتَه من ملكه، فبقي في مسيره ذلك سنتين ووصل إلى بلاده، فاشتغل بإنهاء تلك الثورة، ثم أخلد للراحةِ وممارسة هواية الصيدِ."},{"id":2436,"era":"c7","t":"وفاة الملك الأفضل علي بن صلاح الدين الأيوبي .","s":"هو السُّلطانُ الملك الأفضل علي بن يوسف بن أيوب بن شاذي. ابن السلطان الملك الناصر صلاح الدين، ولد يوم عيد الفطر سنة 565 بالقاهرة، وقيل: سنة ست وستين. وسمع من عبد الله بن بري النحوي، وأبي الطاهر إسماعيل بن عوف الزهري، وأجاز له جماعة. وله شِعر حسن، وترسُّل، وخط مليح. وكان أسنَّ إخوانه، وإليه كانت ولاية عهد أبيه. ولما مات أبوه، كان معه بدمشق، فاستقل بسلطنتها، واستقل أخوه الملك العزيز بمصر، وأخوهما الظ"},{"id":2437,"era":"c7","t":"استحواذ جلال الدين بن خوارزم شاه على بلاد أذربيجان .","s":"استحوذ جلالُ الدين بن خوارزم شاه على بلاد أذربيجان وكثيرٍ من بلاد الكرج، وكسر الكرجَ وهم في سبعين ألف مقاتل، فقتل منهم عشرين ألفًا من المقاتلة، واستفحل أمره جدًّا وعظم شأنه، وفتح تفليس فقتل منها ثلاثين ألفًا، وقتل من الكرج سبعين ألفًا في المعركة، وقتل من تفليس تمامَ المائة ألف، وقد اشتغل بهذه الغزوة عن قصد بغداد، وذلك أنه لما حاصر دقوقا سبَّه أهلها ففتحها قسرًا وقتل من أهلها خلقًا كثيرًا، وخرب سور"},{"id":2438,"era":"c7","t":"وفاة الخليفة العباسي الناصر لدين الله وتولي ابنه الظاهر بأمر الله .","s":"هو الخليفة الناصر لدين الله أبو العباس أحمد بن المستضيء بأمر الله أبي محمد الحسن بن المستنجد بالله يوسف بن المقتفي محمد بن المستظهر بالله أحمد بن المقتدي الهاشمي، العباسي، البغدادي. ولد في عاشر رجب، سنة 553.كان أبيض معتدل القامة، تركيَّ الوجه، مليح العينين، أنور الجبهة، أقنى الأنف، خفيف العارضين، أشقر، رقيق المحاسن، نَقشُ خاتمه: رجائي من الله عَفوُه. وبويع في أول ذي القعدة سنة 575، وكانت خلافته ست"},{"id":2439,"era":"c7","t":"إيقاع جلال الدين خوارزم شاه بالتركمان الإيوانية .","s":"كان التركمان الإيوانية قد تغلَّبوا على مدينة أسنة وأرمية، من نواحي أذربيجان، وأخذوا الخراجَ من أهلِها ليكفُّوا عنهم، واغتروا باشتغال جلال الدين بالكرج، وبُعدِهم بخلاط، وازداد طمعُهم، وانبسطوا بأذربيجان ينهبون، ويقطعون الطريقَ، والأخبار تأتي إلى جلال الدين بن خوارزم شاه، وهو يتغافل عنهم لاشتغاله بما هو المهمُّ عنده، فلما اشتد ذلك على الناس وعظُمَ الشَّرُّ أرسلت زوجة جلال الدين ابنة السلطان طغرل ونو"},{"id":2440,"era":"c7","t":"الصلح بين الأخوين المعظم والأشرف الأيوبيين .","s":"كان بين المعظم والأشرف خلافٌ سَبَبُه أنَّه لَمَّا توفِّيَ الملك العادل أبو بكر بن أيوب، اتفق أولاده الملوك بعده اتفاقًا حسنًا، وهم: الملك الكامل محمد، صاحب مصر، والملك المعظم عيسى، صاحب دمشق، والملك الأشرف موسى، صاحب ديار الجزيرة وخلاط، واجتمعت كلمتُهم على دفع الفرنج عن الديار المصريَّة، ولما رحل الكامل عن دمياط لما كان الفرنج يحصُرونَها، صادفه أخوه المعظَّم من الغد، وقَوِيَت نفسه، وثَبَتت قدمه، و"},{"id":2441,"era":"c7","t":"الفتنة بين الفرنج والأرمن .","s":"جمع البرنس الفرنجي، صاحب أنطاكية، جموعًا كثيرة وقصد الأرمن الذين في الدروب بلاد ابن ليون، فكان بينهم حربٌ شديدةٌ، وسَبَبُ ذلك أنَّ ابن ليون الأرمني، صاحِبَ الدروب، توفِّيَ قبلُ ولم يخلف ولدًا ذكرًا، إنما خلف بنتًا، فملَّكَها الأرمنُ عليهم، ثمَّ عَلِموا أنَّ المُلكَ لا يقومُ بامرأة، فزوجوها من ولد البرنس، فتزوجَّها، وانتقل إلى بلَدِهم، واستقَرَّ في الملك نحو سنة، ثم نَدِموا على ذلك، وخافوا أن يستول"},{"id":2442,"era":"c7","t":"جلال الدين خوارزم شاه يمتلك مدينة تفليس .","s":"فتح جلال الدين بن خوارزم شاه مدينة تفليس من الكرج في ثامن ربيع الأول، وقد كانت الحرب بينه وبينهم من السنة الماضية، وقد انهزموا منه، ثم عاد إلى تبريز بسبب الخلاف الواقع فيها، فلما استقرَّ الأمر في أذربيجان عاد إلى بلد الكرج هذه السنة، فقصد بلادَهم، وقد عادوا فحشدوا وجمعوا من الأمم المجاورة لهم اللان واللكز وقفجاق وغيرهم، فاجتمعوا في جمعٍ كثير لا يحصى، فطمعوا بذلك، فلَقِيَهم وجعل لهم الكمينَ في عدة "},{"id":2443,"era":"c7","t":"عصيان بمدينة كرمان على جلال الدين خوارزم شاه .","s":"وصل الخبَرُ إلى جلال الدين أن نائبه بكرمان، وهو أميرٌ كبير اسمه بلاق حاجب، قد عصى عليه، وطَمِعَ في أن يتملَّك البلاد ويستبِدَّ بها لبُعدِ جلال الدين عنها، واشتغاله بالكرج وغيرهم، وأنه أرسل إلى التتر يعَرِّفُهم قوة جلال الدين ومُلكَه كثيرًا من البلاد، وإن أخذ الباقي عَظُمَت مملكته، وكثُرَت عساكره، وأخذَ ما بأيديكم من البلاد. فلما سمع جلال الدين ذلك كان قد سار يريد خلاط، فتركها وسار إلى كرمان يطوي ا"},{"id":2444,"era":"c7","t":"مسير مظفر الدين صاحب إربل إلى الموصل وعوده عنها .","s":"استقرَّت القاعدة بين مظفر الدين بن زين الدين، صاحب إربل وبين جلال الدين بن خوارزم شاه وبين الملك المعظَّم، صاحب دمشق، وبين صاحِبِ آمد، وبين ناصر الدين، صاحب ماردين، ليقصِدوا البلادَ التي بيد الأشرف، ويتغلَّبوا عليها، ويكون لكُلٍّ منهم نصيبٌ، فبادر مظفر الدين إلى الموصِل, وأمَّا جلال الدين فإنَّه قد شُغِلَ بعصيان نائبه ببلاد كرمان، فانفسخ جميعُ ما كانوا عزموا عليه إلَّا أن مظفر الدين سار من إربل ون"},{"id":2445,"era":"c7","t":"وفاة الخليفة العباسي الظاهر بأمر الله ومبايعة ابنه المستنصر بالله .","s":"هو الخليفة الإمام الظاهر بأمر الله أبو نصر محمد بن الناصر لدين الله أبي العباس أحمد بن المستضيء بأمر الله أبي محمد الحسن ابن المستنجد بالله يوسف بن المقتفي محمد بن المستظهر بالله أحمد بن المقتدي الهاشمي، العباسي، البغدادي. ولد سنة 571. بايع له أبوه بولاية العهد في سنة 585، وخطب له على المنابر، ونثر عند ذكره الدنانير وعليها اسمُه. ولم يزل الأمر على ذلك حتى قطع ذلك أبوه في سنة 601, وخلعه وأكرهه، وزو"},{"id":2446,"era":"c7","t":"الحرب بين كيقباذ وصاحب آمد .","s":"سار علاء الدين كيقباذ بن كيخسرو بن قلج أرسلان، مَلِكُ بلاد الروم، إلى بلاد الملك المسعود بن مودود، صاحِبِ آمد، ومَلَكَ عِدَّةً مِن حصونه، وسببُ ذلك اتفاق صاحب آمد مع جلال الدين بن خوارزم شاه والملك المعظم، صاحب دمشق، وغيرهما على خلاف الأشرف؛ فلما رأى الأشرف ذلك أرسل إلى كيقباذ، ملك الروم، وكانا متفقَينِ، يطلب منه أن يقصِدَ بلد صاحب آمد ويحاربَه، وكان الأشرفُ حينئذ على ماردين، فسار ملك الرومِ إلى م"},{"id":2447,"era":"c7","t":"حصر جلال الدين بن خوارزم شاه مدينتي آني وقرس وخلاط .","s":"عاد جلال الدين بن خوارزم شاه من كرمان، إلى تفليس، وسار منها إلى مدينة آني، وهي للكرج، وبها إيواني مقدَّم عساكر الكرج فيمن بقي معه من أعيان الكرج، فحصره وسيَّرَ طائفةً مِن العسكر إلى مدينة قرس، وهي للكرج أيضًا، وكلاهما من أحصَنِ البلاد وأمنَعِها، فنازلهما وحصَرَهما، وقاتل من بهما، ونصَبَ عليهما المجانيقَ، وجدَّ في القتال على مدينتي آني وقرس، وبالغ الكرج في حفظِهما والاحتياطِ لهما لخوفِهم منه أن يفع"},{"id":2448,"era":"c7","t":"نهب جلال الدين بن خوارزم شاه بلاد الإسماعيلية .","s":"قتل الإسماعيلية أميرًا كبيرًا من أمراء جلال الدين، وكان قد أقطعه جلالُ الدين مدينةَ كنجة وأعمالها، فلما قُتِلَ ذلك الأميرُ عَظُم قَتلُه على جلال الدين، واشتد عليه، فسار في عساكرِه إلى بلاد الإسماعيلية، مِن حدود ألموت إلى كردكوه بخراسان، فخرب الجميعَ، وقتل أهلَها، ونهب الأموالَ، وسبى الحريمَ، واسترقَّ الأولادَ، وقتل الرجالَ، وعَمِلَ بهم الأعمالَ العظيمةَ وانتقم منهم، وكانوا قد عَظُمَ شَرُّهم وازداد"},{"id":2449,"era":"c7","t":"الحرب بين جلال الدين بن خوارزم شاه والتتر .","s":"لما فرغ جلال الدين من الإسماعيلية بلغه الخبَرُ أن طائفةً مِن التتر عظيمةً قد بلغوا إلى دامغان، بالقُربِ من الري، عازمينَ على قصدِ بلاد الإسلام، فسار إليهم وحاربَهم، واشتَدَّ القتال بينهم، فانهزموا منه، فأوسعَهم قتلًا، وتَبِعَ المنهزمين عدَّة أيام يقتُلُ ويأسِرُ، فبينما هو كذلك قد أقام بنواحي الري خوفًا من جمع آخرَ للتتر، إذ أتاه الخبَرُ بأن كثيرًا منهم واصلون إليه، فأقام ينتَظِرُهم. حتى لقيهم سنة "},{"id":2450,"era":"c7","t":"خلاف بين أبناء العادل الأيوبي وأثره في مواجهة الحملة الصليبية .","s":"تأكدت الوحشةُ بين الكامل وبين أخويه المعظَّم والأشرف، وخاف الكامِلُ من انتماء أخيه المعظم إلى السلطان جلال الدين بن خوارزم شاه، فبعث الكامِلُ الأمير فخر الدين يوسف بن شيخ الشيوخ صدر الدين بن حمويه إلى ملك الفرنج، يريدُ منه أن يَقدَم إلى عكا، ووعده أن يعطيه بعض ما بيد المسلمين من بلاد الساحل، ليشغلَ سِرَّ أخيه المعظم، فتجهَّز إمبراطور الألمان فردريك الثاني لقصد الساحل، وبلغ ذلك المعظَّم، فكتب إلى ا"},{"id":2451,"era":"c7","t":"دخول الكرج (وهم الجورجيون، سكان جورجيا) مدينة تفليس وإحراقها .","s":"وصل الكرج مدينةَ تفليس، ولم يكُنْ بها من العسكَرِ الإسلاميِّ من يقومُ بحمايتها، وسبَبُ ذلك أنَّ جلال الدين لَمَّا عاد من خلاط، وأوقع بالإيوانية، فرق عساكره إلى المواضع الحارة الكثيرة المرعى، ليشتُوا بها، وكان عسكره قد أساؤوا السيرةَ في رعية تفليس، وهم مسلمون، وعَسَفوهم، فكاتبوا الكرج يستدعونَهم إليهم، ليملِّكوهم البلد، فاغتنم الكرج ذلك؛ لميل أهل البلدِ إليهم، وخَلَّوه من العسكر، فاجتمعوا، وكانوا ب"},{"id":2452,"era":"c7","t":"نشأة الدولة الحفصية على يد أبي زكريا الحفصي .","s":"بعد أنْ تولَّى أمرَ دولة الموحدينَ أبو محمد العادل بن أبي يوسف يعقوب المنصور سنة 621هـ (1224م) عهد بولاية إفريقيَّةَ إلى أبي محمَّد عبد الله بن عبد الواحد بن أبي حفص، وكان في صحبته أخوه أبو زكريا يحيى، وقام الوالي الجديدُ بإعادة الهدوء والاستقرارِ بعد أن عكَّرت صفوَها الفتنُ والثَّورات، وقام بحَمَلات على الخارجينَ على سلطان الدولة، وما كادت الأمورُ تستقرُّ حتى قفز على منصبِ حُكم الموحِّدين أبو الع"},{"id":2453,"era":"c7","t":"دخول عساكر الملك الأشرف الأيوبي إلى أذربيجان .","s":"سار الحاجب علي حسام الدين، وهو النائب عن الملك الأشرف بخلاط، والمقدَّم على عساكرِها، إلى بلاد أذربيجان فيمن عندَه من العساكر، وسببُ ذلك أنَّ سيرة جلال الدين كانت جائرةً، وعساكرُه طامعةً في الرعايا، وكانت زوجتُه ابنةَ السلطان طغرل السلجوقي، وهي التي كانت زوجةَ أوزبك بن البهلوان، صاحب أذربيجان، فتزوجَّها جلال الدين، وكانت مع أوزبك تحكُم في البلاد جميعها، ليس له ولا لغيره معها حكمٌ، فلما تزوجها جلال "},{"id":2454,"era":"c7","t":"مقتل العادل الموحدي وانقسام دولة الموحدين .","s":"قُتل العادِلُ الموحدي عبد الله بن يعقوب المنصور بن يوسف بن عبدالمؤمن بن علي, فقد كان أميرًا على شرقيِّ الأندلس وجاءته بيعةُ أهل مراكش بعد خلع عمه عبد الواحد، ففوض الأمرَ إلى أخيه أبي العلاء وقصد مراكش ثمَّ اضطربت عليه الأمورُ وقامت فِتَنٌ، فدعا أخوه أبو العلاء لنفسه في إشبيلية وأخذ البيعةَ وتلقب بالمأمون، وأرسل إلى مراكش يدعوهم إلى بيعته، وأعلمهم أن أهلَ الأندلسِ معه، فخلع أهلُ مراكش العادل بعد أن"},{"id":2455,"era":"c7","t":"وفاة الملك المعظم صاحب دمشق وملك ولده داود .","s":"هو المَلِكُ المعَظَّم شرفُ الدين عيسى بن الملك العادل كان عاليَ الهمة حازمًا شجاعًا مهيبًا فاضلًا جامعًا شَملَ أرباب الفضائل محبًّا لهم، كانت مملكتُه متسعة من حدود بلد حمص إلى العريش يدخل في ذلك بلاد الساحل الإسلامية منها، وبلاد الغور وفلسطين والقدس والكرك والشوبك وصرخد وغير ذلك. توفي يوم الجمعة آخر ذي القعدة، وكان مرضُه دوسنطاريا، وكان ملكُه لمدينة دمشق، من حين وفاة والده الملك العادل، عشر سنين و"},{"id":2456,"era":"c7","t":"قيام دولة بني حفص (الحفصيون) في تونس .","s":"استقَلَّ بنو حفص عن دولة الموحِّدين بعد أن انقسمت دولتُهم: قِسمٌ في الأندلس، وقِسمٌ في مراكش، فأطمعهم ذلك بالافتراق عنهم فأقاموا دولةً لهم بزعامةِ أبي زكريا يحيى الأوَّل بن أبي حفص الهتاني، واستمرَّت دولتُهم هذه إلى عام 981."},{"id":2457,"era":"c7","t":"هلاك جنكيزخان وانقسام الإمبراطورية المغولية بين أبنائه الأربعة .","s":"هو جنكيزخان السلطان الأعظم عند التتار والدُ ملوكهم، واسمه تموجين وقيل (تمرجين أو تمرجي) ولد في غرة محرم سنة 550 في منغوليا على الضفة اليمنى لنهر الأونون في مقاطعة دولون بولداق وهذه المقاطعة توجد اليوم في الأراضي الروسية. وكان أبوه بسوكاي رئيسًا لقبيلة قيات المغولية فسمَّاه باسم قائد صرعه؛ لأنَّه كان معجبًا به لفرط شجاعته, وقيل: \"إنَّ أمَّه كانت تزعمُ أنها حملته من شعاع الشمس؛ فلهذا لا يُعرَفُ له أ"},{"id":2458,"era":"c7","t":"ضم قبرص إلى المملكة الألمانية .","s":"توفي ملك قبرص هوك دولوزنيان وقد خلف ولدًا قاصرًا هو هنري الأول، فتولى الوصاية عليه فيليب إيبلان برضا أمه الملكة، فلما توفي فيليب انتقلت الوصاية إلى أخيه جان، لكن بغير رضا الملكة، وكان الملك فردريك الثاني قد مر على قبرص في طريقه إلى بلاد الشام، فاستعانت به الملكة ضد الوصي جان فاستولى فردريك على قبرص وضمها إلى مملكته الألمانية."},{"id":2459,"era":"c7","t":"ثورة ابن هود على الموحدين .","s":"استولى محمد بن يوسف بن هود من سلالة بني هود على مرسية، وطرد منها الموحدين، وأعلن طاعته للخليفة العباسي المستنصر بالله، وتلقب بالمتوكل على الله، ودخل في طاعته جيان وقرطبة وماردة وبطليوس وغيرها من المدن الإسبانية."},{"id":2460,"era":"c7","t":"نشأة محاكم التفتيش في إسبانيا .","s":"بدأ في هذا العام إنشاء محاكم التفتيش الصليبية على يد رجال الكنيسة الكاثوليكية لمحارة الخارجين على سيادة الكنيسة وسلطة البابا؛ حيث وصمت الكنيسة هؤلاء الخارجين على سيادتها من اليهود والنصارى بالكفر والانحراف والبدعة والهرطقة، وأصدرت قوانين التعذيب والقتل بأبشع صورة, وفي القرن الخامس عشر والسادس عشر سلطت هذه المحاكم زبانيتها على المسلمين الذين بقوا في الأندلس بعد سقوط حكم المسلمين فيها لردهم عن دينهم"},{"id":2461,"era":"c7","t":"الحرب بين جلال الدين والتتار وما وقع فيها من عجائب غريبة .","s":"عاود التتر الخروج إلى الري، وجرى بينهم وبين جلال الدين حروب كثيرة، كان أكثرها عليه، وفي الأخير كان الظفر له وكانت أول حرب بينهم فيها عجائب غريبة، وكان هؤلاء التتر قد سخط ملكُهم جنكيزخان على مُقدَّمهم، وأبعده عنه، وأخرجه من بلاده، فقصد خراسان، فرآها خرابًا، فقصد الريَّ ليتغلب على تلك النواحي والبلاد، فلقيه بها جلال الدين، فاقتتلوا أشدَّ قتال، ثم انهزم جلال الدين وعاد ثم انهزم، وقصد أصفهان، وأقام بي"},{"id":2462,"era":"c7","t":"خروج الفرنج إلى الشام وعمارة صيدا .","s":"خرج كثيرٌ من الفرنج من بلادهم، التي هي في الغرب من صقلية وما وراءها من البلاد، إلى بلادهم التي بالشام: عكا وصور وغيرهما من ساحل الشام، فكثُرَ جمعهم، وكان قد خرج قبل هؤلاء جمع آخر أيضًا إلا أنهم لم تمكِنْهم الحركة والشروع في أمر الحرب؛ لأجل أنَّ مَلِكَهم الذي هو المقدَّم عليهم هو ملك الألمان، ولأنَّ الملك المعظم عيسى بن العادل صاحب دمشق كان حيًّا، وكان شهمًا شجاعًا مقدامًا، فلما توفي المعظم، وولي ب"},{"id":2463,"era":"c7","t":"علاء الدين كيقباذ السلجوقي يمتلك مدينة أرزنكان .","s":"ملك علاء الدين كيقباذ بن كيخسرو بن قلج أرسلان- وهو صاحب قونية وما حولها من بلاد الروم- أرزنكان، وسبب ملكه إياها أن صاحبها بهرام شاه كان قد طال مُلكُه لها، وجاوز ستين سنة، توفي ولم يزل في طاعة قلج أرسلان وأولاده بعده، فلما توفي ملك بعده ولده علاء الدين داود شاه، فأرسل إليه كيقباذ يطلب منه عسكرًا ليسير معه إلى مدينة أرزن الروم- وهي قريبة من مدينة أرزنكان- ليحصرها، ويكون هو مع العسكر، ففعل ذلك، وسار "},{"id":2464,"era":"c7","t":"نهب جلال الدين خوارزم شاه بلاد أرمينية .","s":"وصل جلال الدين خوارزم شاه إلى بلاد خلاط، وتعدى خلاط إلى صحراء موش، وجبل جور، ونهب الجميع، وسبى الحريم، واسترقَّ الأولاد، وقتل الرجال، وخرب القرى، وعاد إلى بلاده، ولما وصل الخبرُ إلى البلاد الجزرية: حران وسروج وغيرهما، أنَّه قد جاز خلاط إلى جور، وأنه قد قرب منهم، خاف أهل البلاد أن يجيء إليهم، لأنَّ الزمان كان شتاء، وظنُّوا أنه يقصد الجزيرة ليشتي بها، لأنَّ البرد بها ليس بالشديد، وعزموا على الانتقال"},{"id":2465,"era":"c7","t":"خروج الملك الكامل صاحب مصر إلى الشام .","s":"سار الملك الكامل محمد بن الملك العادل، صاحب مصر, فوصل إلى بيت المقدس, ثم سار عنه، وتولى بمدينة نابلس، وشحن على تلك البلاد جميعها، وكانت من أعمال دمشق، فلما سمع صاحبها، وهو ابن الملك المعظم، خاف أن يقصده ويأخذ دمشق منه، فأرسل إلى عمه الملك الأشرف يطلبه ليحضر عنده بدمشق، فسار إليه جريدة، فدخل دمشق، فلما سمع الكامل بذلك لم يتقدم لعِلمِه أن البلد منيع، وقد صار به من يمنعه ويحميه، وأرسل إليه الملك الأش"},{"id":2466,"era":"c7","t":"اتفاق يافا وتسليم الملك الكامل بيت المقدس للصليبيين .","s":"بعد أن ترددت الرسل بين الملك الكامل صاحب مصر وفردريك الثاني ملك ألمانيا انتهوا على صلح عشر سنوات يسلم الكامل بيت المقدس للصليبيين نكاية بإخوانه في الشام بسبب خلاف بينه وبينهم, وجاء في بنود الاتفاق الذي عرف باتفاق يافا: 1/ أن ملك الفرنج يأخذ القدس من المسلمين، ويبقيها على ما هي من الخراب، ولا يجدد سورها. 2/ أن يكون سائر قرى القدس للمسلمين، لا حكم فيها للفرنج. 3/ أن الحرم بما حواه من الصخرة والمسجد "},{"id":2467,"era":"c7","t":"الملك فردريك الثاني يتوج نفسه ملكا على القدس .","s":"بعد أن تسلم فردريك الثاني ملك ألمانيا القدس على الاتفاق توج نفسه ملكًا على القدس بوصفه زوجًا للملكة إيزابيلا الثانية ملكة القدس ثم غادر فلسطين."},{"id":2468,"era":"c7","t":"استيلاء السلطان التتمش على البنجاب السفلي والعلوي .","s":"انتهى حكم أيبك على هندستان في سنة 608 (1210م) وذلك على أثر سقوطه من على فرسه. أثناء لعبة الكرة أو البولو- جوكان- فتوفي على الأثر, وخلفه أحدُ مماليكه البارزين وزوج ابنته شمس الدين التتمش الذي سار سيرة حسنة في رعيته، واشتدَّ في رد المظالم وإنصاف المظلومين. فيؤثر عنه أنه أمر أن يلبس كلُّ مظلوم ثوبًا مصبوغًا. وأهل الهند جميعًا يلبسون البياض، فكان إذا قعد للنَّاسِ أو ركب، فرأى أحدًا عليه ثوب مصبوغ نظر "},{"id":2469,"era":"c7","t":"البابا يصدر حرمان من الكنسية ضد الملك فردريك ومنعه من بيت المقدس .","s":"كان البابا غريغوريوس التاسع قد أصدر سابقًا سنة 623 صكًّا فيه حرمان الملك فردريك ملك ألمانيا من الكنيسة؛ وذلك بسبب تأخره عن تجهيز الحملة الصليبية السادسة، واعتذر بسبب مرضه وهذا لم يشفع له، ثم في هذا العام أصدر البابا صكًّا آخر فيه حرمان ثان؛ وذلك ليمنعه من تسلم بيت المقدس كما وعده الكامل صاحب مصر، وقام البابا أيضًا بمراسلة الكامل، وبيَّنَ له أن فردريك قد طرد من الكنيسة ولا يستحق أن يتسلم بيت المقدس"},{"id":2470,"era":"c7","t":"هدنة الملك الكامل الأيوبي مع الفرنج وتسليم القدس للصليبيين .","s":"بدأت الحملة الصليبية السادسة سنة 625 (1227م)كمحاولة لإعادة السيطرة على بيت المقدس. بدأت بعد سبع سنوات فقط من فشل الحملة الصليبية الخامسة التي ترأسها الإمبراطور فريدريك الثاني هوهنشتاوفن الألماني الذي نذر النذر الصليبي للحملة السابقة ولم يف به حينها، وأراد الإمبراطور أن يحقق مقاصده دون أن يسحب سيفه من غمده، فتزوج في صيف سنة 622 (1224م) من ابنة ملك بيت المقدس يوحنا دي بريان (يولاندي والمعروفة أيضًا "},{"id":2471,"era":"c7","t":"الملك الأشرف الأيوبي يمتلك مدينة دمشق .","s":"في يوم الاثنين ثاني شعبان مَلَك المَلِك الأشرف بن الملك العادل مدينة دمشق من ابن أخيه الملك الناصر صلاح الدين داود بن المعظم، وسبب ذلك أن صاحب دمشق لما خاف من عمِّه الملك الكامل أرسل إلى عمه الأشرف يستنجده، ويستعين به على دفع الكاملِ عنه، وسار صاحب دمشق إلى بيسان وأقام بها، وعاد الملك الأشرف من عند أخيه، واجتمع هو وصاحب دمشق، ولم يكن الأشرف في كثرة من العسكر، ووصلت العساكر من الكامل إلى الأشرف، وس"},{"id":2472,"era":"c7","t":"انتصار الملك الأشرف الأيوبي على خوارزم شاه بمدينة خلاط .","s":"نزل جلال الدين خوارزم شاه على خلاط وحاصرها وضايقها أشَدَّ مضايقة، وأخذَها من نواب الملك الأشرف، وهو مقيمٌ بدمشق، ولم يمكِنْه في ذلك الوقت قَصْدَها للدفع عنها لأعذارٍ كانت له. ثم عقيبَ ذلك دخل الأشرفُ بلاد الروم باتفاق مع سلطانِها علاء الدين كيقباذ، وتعاقدا على قصد خوارزم شاه، وضرب المصاف معه، فإن صاحب الروم كان يخاف على بلاده منه؛ لكونِه مجاوِرَه، فتوجَّها نحوه في جيش عظيم من جهة الشام والشرق في خ"},{"id":2473,"era":"c7","t":"الملك الكامل الأيوبي يمتلك مدينة حماة .","s":"ملك الملك الكامل مدينة حماة، وسبب ذلك أنَّ الملك المنصور محمد بن تقي الدين عمر، وهو صاحب حماة، توفِّي، ولما حضرته الوفاة حلف الجندُ وأكابر البلد لولده الأكبر، ويلقب بالملك المظفَّر، وكان قد سيَّرَه أبوه إلى الملك الكامل، صاحب مصر، وكان لمحمَّد ولد آخر اسمه قلج أرسلان، ولقبه صلاح الدين، وهو بدمشق، فحضر إلى مدينة حماة فسُلِّمَت إليه، واستولى على المدينة وعلى قلعتها، فأرسل الملك الكامل يأمره أن يسلِّ"},{"id":2474,"era":"c7","t":"حصر جلال الدين خوارزم شاه خلاط وملكها .","s":"حصر جلال الدين خوارزم شاه مدينة خلاط، وهي للملك الأشرف، وبها عسكره، فامتنعوا بها، وأعانهم أهل البلد خوفًا من جلال الدين لسوء سيرته، وأسرفوا في الشتم والسفه، فأخذه اللجاج معهم، وأقام عليهم جميع الشتاء محاصرًا، وفرق كثيرًا من عساكره في القرى والبلاد القريبة من شدة البرد وكثرة الثلج؛ فإن خلاط من أشد البلاد بردًا وأكثرها ثلجًا، وأبان جلال الدين عن عزم قوي، وصبر تحارُ العقول منه، ونصب عليها عدةَ مجانيق"},{"id":2475,"era":"c7","t":"علاء الدين كيقباذ السلجوقي يسيطر على مدينة أرزن .","s":"كان صاحب أرزن الروم مع جلال الدين على خلاط، ولم يزل معه، وشهد معه المصاف بباسي حمار، فلمَّا انهزم جلال الدين أُخِذَ صاحب أرزن الروم أسيرًا، فأحضر عند علاء الدين كيقباذ بن عمه، فأخذه وقصد أرزن الروم، فسَلَّمَها صاحبها إليه وهي وما يتبعها من القلاع والخزائن وغيرها، فجاء إلى جلال الدين يطلُبُ الزيادة، فوعَدَه بشيءٍ مِن بلاد علاء الدين، فأخذ مالَه وما بيديه من البلادِ وبَقِيَ أسيرًا، فسُبحان من لا يزو"},{"id":2476,"era":"c7","t":"ملك شهاب الدين غازي مدينة أرزن الروم .","s":"كان حسام الدين صاحب مدينة أرزن الروم من ديار بكر لم يزل مصاحبًا للملك الأشرف، مشاهدًا جميع حروبه وحوادثه، وينفِقُ أمواله في طاعته، ويبذل نفسَه وعساكره في مساعدته، فهو يعادي أعداءه، ويوالي أولياءه، ومن جملة موافقته أنه كان في خلاط لَمَّا حصرها جلال الدين، فأسره جلالُ الدين، وأراد أن يأخذ منه مدينة أرزن، فقيل له: إن هذا من بيت قديمٍ عريق في الملك، وإنه ورث أرزن هذه من أسلافِه، وكان لهم سواها من البل"},{"id":2477,"era":"c7","t":"الأسبان يستولون على الجزر الشرقية .","s":"استولى الأسبان على الجزر الشرقيَّة الباليار واحتلُّوا مدينة ماردة."},{"id":2478,"era":"c7","t":"نهاية دولة الأيوبيين وقيام دولة بني رسول في اليمن .","s":"مات المَلِكُ المسعود يوسف بن الملك الكامل بمكة، وكانت مدة ملكه باليمن أربع عشرة سنة، وهو آخر ملوك بني أيوب ببلاد اليمن، وترك المسعود ابنًا يقال له صلاح الدين يوسف، ولُقِّب بالملك المسعود، لقبَ أبيه، وبقي يوسف هذا حتى مات في سلطنة عَمِّه الملك الصالح نجم الدين أيوب، صاحب مصر، ثم ولي ابنُه موسى بن يوسف بن يوسف بن الكامل مملكة مصر، ولُقِّبَ بالأشرف، وكان المسعود قد استخلف على اليمن نورَ الدين علي بن "},{"id":2479,"era":"c7","t":"انهزام جلال الدين  بن خوارزم شاه من كيقباذ والأشرف الأيوبي .","s":"انهزم جلال الدين بن خوارزم شاه من عبد الله بن كيقباذ بن كيخسرو بن قلج أرسلان، صاحب بلاد الروم، ومن الملك الأشرف، صاحب دمشق، وسببُ ذلك أن جلال الدين كان قد أطاعه صاحب أرزن الروم، وهو ابن عم علاء الدين، ملك الروم، وبينه وبين ملك الروم عداوة مستحكمة، وحضر صاحبُ أرزن الروم عند جلال الدين على خلاط، وأعانه على حصرِها، فخافهما علاء الدين، فأرسل إلى الملك الكامل، وهو حينئذ بحرَّان، يطلبُ منه أن يحضر أخاه "},{"id":2480,"era":"c7","t":"قدوم بني رسول مع الأيوبيين إلى اليمن، واستيلاؤهم على اليمن .","s":"قَدِمَ بَنو رَسولٍ اليَمنَ ضِمنَ الحَملةِ الأيُّوبيَّةِ إليها، فإنَّه لَمَّا استَوثَقَ المُلْكُ لبَني أيُّوبَ في مِصرَ لم يَزَلْ معهم عُصبةٌ مِن بَني رَسولٍ؛ لِعِلْمِهم بتَقدُّمِ مَنصِبِهم في المُلكِ وعُلوِّ هِمَمِهم وشدةِ بَسالَتِهم، فاجتَمع رأيُ بَني أيُّوبَ على تسييرِهم إلى اليَمنِ صُحبةَ المَلكِ المعظَّمِ تُورانْشاهْ بنِ أيُّوبَ، وكانَ دُخولُه اليَمنَ في سنةِ 569هـ، وتوالى مُلوكُ الأيُّوبيةِ ع"},{"id":2481,"era":"c7","t":"خروج التتر إلى أذربيجان .","s":"وصل التتر من بلاد ما وراء النهر إلى أذربيجان، وقد كان استقَرَّ مُلكُهم بما وراء النهر، وعادت بلادُ ما وراء النهر فانعمرت، وعمروا مدينة تقارب مدينة خوارزم، وبَقِيَت مدن خراسان خرابًا لا يجسر أحدٌ من المسلمين أن يسكُنَها، وأما التتر فكانت تَغيرُ كلَّ فترة طائفة منهم ينهبون ما يرونه بها، فالبلاد خاوية على عروشها، فلم يزالوا كذلك إلى أن ظهر منهم طائفةٌ سنة خمس وعشرين، فكان بينهم وبين جلال الدين ما كان"},{"id":2482,"era":"c7","t":"دخول التتر ديار بكر والجزيرة .","s":"لما انهزم جلال الدين من التتر على آمد نهب التتر سوادَ آمد وأرزن الروم وميافارقين، وقصدوا مدينةَ أسعرد، فقاتلهم أهلُها، فبذل لهم التترُ الأمان، فوَثِقوا منهم واستسلَموا، فلما تمكَّنَ التتر منهم وضَعُوا فيهم السيفَ وقتلوهم حتى كادوا يأتونَ عليهم، فلم يسلَمْ منهم إلَّا من اختفى، وقليل ما هم، ومدَّة الحصار كانت خمسة أيام، ثمَّ ساروا منها إلى مدينة طنزة، ففعلوا فيها كذلك، وساروا من طنزة إلى وادٍ بالقرب"},{"id":2483,"era":"c7","t":"التتر يسيطرون على مدينة مراغة من أذربيجان .","s":"حصر التترُ مراغة من أذربيجان، فامتنع أهلها، ثم أذعن أهلُها بالتسليم على أمانٍ طلبوه، فبذلوا لهم الأمان، وتسلَّموا البلدَ وقتلوا فيه إلَّا أنهم لم يُكثِروا القتل وجعلوا في البلد شحنةً، وعظُمَ حينئذ شأن التتر، واشتد خوفُ الناس منهم بأذربيجان، وليس في ملوك الإسلام من له رغبةٌ في الجهاد، ولا في نصرةِ الدين، بل كلٌّ منهم مُقبِلٌ على لهوه ولعبه وظُلمِ رَعيَّتِه، وقال الله تعالى: {وَاتَّقُوا فِتْنَةً لَا"},{"id":2484,"era":"c7","t":"وفاة سليمان شاه التركماني جد عثمان مؤسس الدولة العثمانية .","s":"هو سُليمان شاه بن قتلمش القايوي التركماني جَدُّ مُؤَسِّس الدَّولة العُثمانيَّة، السُّلطان عثمان الأوَّل بن أرطغرل. كان حاكِمًا في بلدة ماهان, لَمَّا وقعت فتنةُ جنكيز خان سنة 621 ترك تلك سليمان مع قومه البلادَ مع من تركها من الملوكِ، وقصد بلادَ الروم، وكان قد سمع بدولةِ السلجوقية بها وعِظَمِ شَوكتِهم، وتَبِعَه خلقٌ كثير، فلمَّا وصلوا إلى أرزنجان قاتلوا الكفَّار وغنموا منهم شيئًا كثيرًا ثمَّ قَصَدوا"},{"id":2485,"era":"c7","t":"استيلاء ابن هود على غرناطة .","s":"قام الأمير محمد بن يوسف بن هود بالاستيلاء على غرناطة وانتزعها من دولة الموحدين بعد أن استولى على مرسية وما جاورها من بلاد الشَّرقِ."},{"id":2486,"era":"c7","t":"نهاية الدولة الخوارزمية .","s":"بعد دخول التتر أذربيجان وغيرها من المدن، وتفَرُّق عساكر جلال الدين خوارزم شاه واختفائه، ولم يعرف له سبيل؛ كان ذلك نهاية للدولة الخوارزميَّة."},{"id":2487,"era":"c7","t":"وصول طائفة من التتر إلى إربل ودقوقا .","s":"وصل طائفةٌ من التتر من أذربيجان إلى أعمال إربل، فقتلوا من على طريقِهم من التركمان الإيوانية والأكراد الجوزقان وغيرهم إلى أن دخلوا بلدَ إربل، فنهبوا القرى، وقتَلوا من ظَفِروا به من أهلِ تلك الأعمال، وعَمِلوا الأعمالَ الشنيعة التي لم يُسمَع بمثلِها من غيرهم، وبرز مظفر الدين، صاحب إربل، في عسكره، واستمدَّ عساكِرَ الموصل فساروا إليه، فلمَّا بلَغَه عودَ التتر إلى أذربيجان أقام في بلاده ولم يتبعْهم، فوص"},{"id":2488,"era":"c7","t":"طاعة أهل أذربيجان للتتر .","s":"في أواخر هذه السنة أطاع أهل بلاد أذربيجان جميعها للتتر، وحملوا إليهم الأموالَ والثياب الخطائي، والخوبي، والعتابي، وغير ذلك، وسبب طاعتِهم أن جلال الدين لَمَّا انهزم على آمد من التتر، وتفَرَّقت عساكره، وتمزَّقوا كلَّ مُمزَّق، وتخطَّفَهم الناس، وفعل التترُ بديار بكر والجزيرة وإربل وخلاط ما فعلوا، ولم يمنَعْهم أحد، ولا وقف في وجوههم واقف، وملوكُ الإسلام منجحرون في الأثقاب، وانضاف إلى هذا انقطاعُ أخبار"},{"id":2489,"era":"c7","t":"امتداد الغزو المغولي وتصدي الخليفة لهم .","s":"تكامَلَ استيلاءُ التتر على إقليم أرمينية وخلاط وسائر ما كان بيد الخوارزمي، فوصلوا إلى شهزور فاهتَمَّ الخليفة المستنصر بالله غايةَ الاهتمام، وسيَّرَ عِدَّة رسل يستنجد الأشرفَ مِن مصر، ويستنجد العربان وغيرهم، وأخرج الخليفةُ الأموال، فوقع الاستخدام في جميع البلاد لحركة التتر، فندب الخليفةُ صاحب إربل مظفر الدين كوكبري بن زين الدين، وأضاف إليه عساكِرَ مِن عنده، فساروا نحوهم فهربت منهم التتار وأقاموا في"},{"id":2490,"era":"c7","t":"اجتماع الملوك لقتال التتار .","s":"خرج المَلِكُ الكامِلُ مِن القاهرة في جمادى الآخرة، واستخلفَ على مصر ابنَه المَلِك العادلَ أبا بكر، وقَدِمَ الأشرف والمعظم صاحِب الجزيرة بالعساكر، ومضى الكاملُ جريدة-الجريدة خَيْلٌ لا رَجَّالة فيها- إلى الشوبك والكرك، وسار إلى دمشقَ، ومعه الناصرُ داود بن الملك المعظَّم صاحب الكرك بعساكره، وأقام الكامِلُ بدمشق يسَرِّح العساكِرَ، وجعل في مقدِّمتِها ابنه الملك الصالح أيوب، وورد الخبر بدخول التتر بلاد "},{"id":2491,"era":"c7","t":"إقامة دولة بني الأحمر بغرناطة .","s":"أقام محمد بن يوسف بن نصر جد بني الأحمر دولةَ بني الأحمر في غرناطة بعد أن تغلَّبَ على محمد بن يوسف بن هود."},{"id":2492,"era":"c7","t":"محاولة صاحب اليمن الاستيلاء على مكة .","s":"بعث الملكُ المنصور عمر بن علي بن رسول، صاحبُ اليمن، عسكرًا إلى مكة، وفيها الشَّريفُ راجح بن قتادة، فمَلَكَها من الأمير شجاع الدين طغتكين، نائب الملك الكامل، وفرَّ شجاع الدين إلى نخلة ثم إلى ينبع، وكتب يُعلِمُ الملك الكامل بذلك، فبعث إليه الكامِلُ عسكرًا سار بهم إلى مكَّة، فقدموها في شهر رمضان، ومَلَكوها بعدما قتلوا جماعة، وكان مُقَدَّم العسكر الأمير فخر الدين يوسف بن الشيخ."},{"id":2493,"era":"c7","t":"تأسيس دولة بني الأحمر في غرناطة وبناء قصر الحمراء .","s":"بعد أن تخلى الموحِّدون عن الأندلس بدأت تتساقَطُ المدن الإسلامية فيها واحدة تلوَ الأخرى في أيدي القوى الصَّليبية غيرَ أنَّ مقاطعة غرناطة استطاع أن يسيطرَ عليها محمد الغالب بن يوسف بن أحمد بن نصر بن الأحمر الذي اعتصم بها، وأقام قلعةً عُرِفَت باسم قلعة الحمراء أو قصر الحمراء وجعلها مركزًا له ولأسرته من بعده، وملجأً لجموع المسلمين الهاربين من أنحاءِ الأندلس، ثمَّ أعلن نفسَه أميرًا على الأندلس بعد أن ا"},{"id":2494,"era":"c7","t":"اتساع دولة بني حفص في الجزائر .","s":"قام أبو زكريا الأول الحفصي أمير تونس مؤسس الدولة الحفصية بتوسيعِ رقعة دولته باستيلائِه على بجاية وقسنطينة."},{"id":2495,"era":"c7","t":"نهاية دولة بني أرتق في بلاد آمد .","s":"قام الملك الكامِلُ الأيوبي صاحِبُ مصر بفتح آمد، وأخرجَ منها صاحبها الملك المسعود بن مودود بعد حصار طويل، وتسلم منه جميعَ القلاع التي كانت بيده، وبَقِيَ حِصنُ كيفا عاصيًا، فبعث الكامل أخاه الأشرف وأخاه شهاب الدين غازي، ومعهما صاحب آمد تحت الحوطة، فسألهم صاحِبُ آمد في تسليمِ الحصن فلم يسَلِّموا البلد، فعذَّبَه الأشرفُ عذابًا عظيمًا، وكان يُبغِضُه، ولا زال الأشرف يحاصر حصن كيفا حتى تسَلَّمَها، ووجد ع"},{"id":2496,"era":"c7","t":"وفاة ابن الأثير الجزري صاحب التاريخ .","s":"هو الشيخ الإمام العلامة المحدِّث، الأديبُ النَّسَّابة: عز الدين أبو الحسن علي بن محمد بن عبد الكريم بن عبد الواحد الشيباني الجزري الموصلي المعروف بابن الأثير، مصنف كتاب (أُسْد الغابة في أسماء الصحابة)، وكتاب (الكامل في التاريخ)، وهو من أحسنها سردًا للحوادث ابتدأه من المبتدأ إلى سنة ثمان وعشرين وستمائة، ولد بجزيرة ابن عمر، في سنة 550، ونشأ بها، وأخواه العلامة مجد الدين والوزير ضياء الدين، ثم تحوَّل"},{"id":2497,"era":"c7","t":"وفاة الملك المظفر صاحب إربل .","s":"هو السلطانُ المَلِكُ المعَظَّم: مظفر الدين أبو سعيد كوكبري بن علي بن بكتكين بن محمد التركماني، صاحب إربل، وابنُ صاحبها, وقد مصرَها الملك زين الدين علي كوجك. ثمَّ وهبها لأولاد مظفر الدين صاحب الموصل، وكان يوصَفُ بقوةٍ مُفرِطة، وطال عمره، وله أوقافٌ وبر ومدرسة بالموصل. ولد مظفر الدين في المحرم، 549، بإربل. تولى مظفَّرُ الدين إربل بعد وفاةِ أبيه وأقام بها مدَّةً وانتقل إلى الموصِلِ، ثمَّ دخل الشام وا"},{"id":2498,"era":"c7","t":"الملك الكامل صاحب مصر يرسل جيشا لاسترداد مكة .","s":"جهَّز الملكُ الكامِلُ عسكرًا من الغزِّ والعربان إلى ينبع، من أرضِ الحجاز عليهم علاء الدين آق سنقر الزاهدي في شوَّال وعِدَّتُهم سبعمائة، وسبَبُ ذلك ورودُ الخبر بمسير الشريف راجح من اليمن بعسكر إلى مكةَ، وأنَّه قَدِمَها في صفر، وأخرج من بها من المصريين بغيرِ قتال، ثم إنَّ ابن رسول بعث إلى الشريف راجح بن قتادة بخزانة مالٍ، ليستخدم عسكرًا، فلم يتمكَّنْ من ذلك؛ لأنَّه بلغه أنَّ السلطان الملك الكامل بعث"},{"id":2499,"era":"c7","t":"استيلاء الخليفة على الموصل .","s":"سارت العساكر المستنصرية بصحبة الأمير سيف الدين أبي الفضائل إقبال الخاص المستنصري إلى مدينة إربل وأعمالها، وذلك لمرض مالكِها مظفر الدين كوكبري بن زين الدين، وأنَّه ليس له من بعده من يملك البلاد، فحين وصَلَها الجيشُ منَعَه أهلُ البلد فحاصروه حتى افتتحوه عنوةً في السابع عشر من شوال، وجاءت البشائرُ بذلك فضُرِبَت الطبول ببغداد بسَبَبِ ذلك، وفَرِحَ أهلُها، وكتب التقليدُ عليها لسيف الدين أبي الفضائل إقبا"},{"id":2500,"era":"c7","t":"إنشاء المدرسة الجوزية .","s":"أنشأها القاضي أستاذ دار الخليفة المستعصم الصاحب محيي الدين ابن الشيخ جمال الدين أبي الفرج عبد الرحمن ابن الجوزي أيَّامَ الملك الصالح عماد الدين، كان قد حصل على أموالٍ وكراماتٍ من بني أيوب بالشامِ- أثناء قيامه بالسِّفارة بين الخليفة وبني أيوب- ابتنى بها المدرسةَ الجوزيَّة بالنشابين بدمشق بسوق القمح بالقرب من الجامِعِ، وقد نسب إليها ابنُ قَيِّم الجوزيَّة رحمه الله، فهو إمامُها ووالدُه كان قَيِّمَها."},{"id":2501,"era":"c7","t":"وفاة العلامة المتكلم سيف الدين الآمدي .","s":"هو العلامة المتكلم أبو الحسن علي بن أبي علي ابن محمد بن سالم الثعلبي سيف الدين الآمدي، الحنبلي ثم الشافعي. الحموي الدمشقي، صاحبُ المصَنَّفات في الأصلين وغيرهما، ومن مصنفاته: \" أبكار الأفكار في الكلام \" و\" دقائق الحقائق في الحكمة \" و\" إحكام الأحكام في أصول الفقه \" ولد بعد 550 بيسيرٍ بآمد، وقرأ بها القراءات على الشيخ محمد الصفار، وعمار الآمدي. وحفظ \"الهداية\" في مذهب أحمد. كان حنبليَّ المذهب فصار شاف"},{"id":2502,"era":"c7","t":"اكتمال بناء المدرسة المستنصرية .","s":"كَمُل بناء المدرسة المستنصرية ببغداد ولم يُبنَ مدرسةٌ قبلَها مِثلُها، ووقفت على المذاهب الأربعة من كل طائفة اثنان وستون فقيهًا، وأربعة معيدين، ومدرس لكل مذهب، وشيخ حديث وقارئان وعشرة مستمعين، وشيخ طب، وعشرة من المسلمين يشتغلون بعلم الطب، ومكتب للأيتام، وقدر للجميع من الخبز واللحم والحلوى والنفقة، ما فيه كفاية وافرة لكل واحد، ولما كان يوم الخميس خامس رجب حضرت الدروس بها وحضر الخليفة المستنصر بالله "},{"id":2503,"era":"c7","t":"قصد كيقباذ صاحب بلاد الروم السلجوقي لقتال خلاط .","s":"قصد السلطان علاء الدين كيقباذ بن كيخسرو السلجوقي، صاحب بلاد الروم، مدينةَ خلاط، فخرج المَلِكُ الكامل من القاهرة بعسكره، ليلة السبت خامس شعبان، واستناب ابنَه الملك العادل، فوصل إلى دمشق، وكتب إلى ملوك بني أيوب يأمرُهم بالتجهز، للمسير بعساكرهم إلى بلاد الروم، وخرج الكامِلُ من دمشق، فنزل على سلمية في شهر رمضان، ورتَّب عساكِرَه، وسار إلى منبج، فقَدِمَ عليه عسكر حلب، وغيرُه من العساكر، فسار وقد صار معه"},{"id":2504,"era":"c7","t":"وباء عظيم في مصر مات فيه الألوف .","s":"كان في مصر الوباء العظيم؛ حيث مات في شهر نيف وثلاثون ألف إنسان، واستمَرَّ هذا الوباء مدة ثلاثة أشهر، فمات بالقاهرة خلقٌ كثُر، بلغت عدتُهم زيادة على اثني عشر ألفًا، سوى من مات بالريف."},{"id":2505,"era":"c7","t":"الملك الكامل صاحب مصر وخلافه مع الأمراء .","s":"عاد الملكُ الكامل إلى قلعة الجبل من بلاد الشرق، وقد توحَّشَ ما بينه وبين أخيه الأشرف صاحب دمشق وغيره من الملوك، فقبَضَ الكامل على المسعود صاحب آمد واعتقله في برجٍ هو وأهلَه، يوم الاثنين سادس عشر جمادى الأولى، لممالأتِه لهم، فملك صاحبُ الروم حرَّان بالسيف، وعاد إلى بلاده، بعدما استولى على ما كان بها من الأموال، فلما بلغ الكامل ذلك أمر العساكر أن تتجهز للمسير إلى الشرق، وأقطع ابنَ الأمير صلاح الدين "},{"id":2506,"era":"c7","t":"وفاة ابن الفارض الصوفي .","s":"هو أبو حفص عمر بن أبي الحسن علي بن المرشد بن علي، الحموي الأصل، المصري المولد والدار والوفاة، ولد في الرابع من ذي القعدة سنة 576 بالقاهرة. وكان أبوه يكتب فروض النساء والرجال، ناظم التائية, وهي قصيدة طويلةٌ أكثر من سبعمائة بيت في السلوك على طريقة المتصوفة المنسوبين إلى الاتحاد، وقد تكلَّمَ فيه غير واحد من المشايخ بسبب قصيدته المشارِ إليها، وقد ذكره الذهبي وحطَّ عليه فقال: \"إن لم يكن في تلك القصيدةِ"},{"id":2507,"era":"c7","t":"سقوط قرطبة في يد الأسبان .","s":"قام الأسبان بقيادة فرديناند الثالث ملك قشتالة بالاستيلاء على قرطبة وحوَّلوا جامعها إلى كنيسة."},{"id":2508,"era":"c7","t":"نهاية حكم الموحدين بالأندلس .","s":"كانت دولة الموحدين قد قويت أولًا في الأندلس، ولكنها لم تستطع أن تقفَ لوحدها في وجه التوسُّعِ الصليبي بصورةٍ دائمةٍ، كما لم يدُمْ صُمودُهم طويلًا إثر ذلك النصر الذي أحرزوه في معركة الأرك سنة 591 فقد جاءت هزيمتهم الماحقة في معركة العقاب سنة 609 على أيدي تحالف ملوك الصليبيين في الأندلس، والذي نجم عنه انسحاب الموحدين من الأندلس شيئًا فشيئًا، وخاصة أن الصليبيين بقوا في حروبهم التي سموها حروبَ الاسترداد"},{"id":2509,"era":"c7","t":"القوات البرتغالية تحتل مدينة طلبيرة .","s":"قامت القوات البرتغالية بقيادة مَلِكِهم باحتلال طلبيرة وغيرها من البلاد التي سيطرت عمليًّا عليها وعلى جميع المناطقِ التي تشكِّلُ اليوم بلاد البرتغال."},{"id":2510,"era":"c7","t":"وفاة ابن دحية الكلبي .","s":"هو أبو الخطاب عمر بن الحسن بن علي بن محمد بن فرج بن خلف بن قومس بن أحمد بن دحية بن خليفة الكلبي الحافظ، شيخ الديار المصرية في الحديث، ولد سنة 546. كان يذكر أنه من ولد دحية الكلبي، وأنه سبطُ أبي البسام الحسيني الفاطمي. كان بصيرًا بالحديث معتنيًا بتقييده، مكبًّا على سماعه، حسنَ الحَطِّ معروفًا بالضبط، له حظٌّ وافر من اللغة، ومشاركة في العربية وغيرها. وهو أول من باشر مشيخة دار الحديث الكامليَّة بها، "},{"id":2511,"era":"c7","t":"مسير الملك الكامل الأيوبي نحو الشرق .","s":"سار الملك الكامل من القاهرة بعساكره يريد بلاد الشرق، فنازل الرَّها حتى أخذها يوم الأربعاء ثالث عشر جمادى الأولى، وأسَرَ منها زيادةً على ثمانمائة من الأمراء، وهدم قلعتَها، ونازل حران، وأخذها بعد حصارٍ وقتال في رابع عشر جمادى الآخر، وأسَرَ من كان بها من أجناد السلطان علاء الدين كيقباذ، وأمرائه ومقدميه الصوباشية، وكانوا سبعمائة وخمسة وعشرين رجلًا، فمات كثير منهم في الطرقات، ثم نزل الكامِلُ على دنيسر "},{"id":2512,"era":"c7","t":"استعادة الكامل الأيوبي الرها وحران من الروم .","s":"قطع الكامِلُ وأخوه الأشرف الفرات وأصلحا ما كان أفسَدَه جيش الروم من بلادهما، فاستعاد من الروم حران والرها وغيرهما، وأخرب قلعةَ الرها ونزل على دنيسر فأخربها ومعه أخوه الأشرف، وبينما هم في ذلك جاء كتاب بدر الدين لؤلؤ إلى الأشرف يقول: قد قطع التتارُ دجلة في مائة طلب كل طلب خمسمائة فارس، ووصلوا إلى سنجار، فخرج إليهم معين الدين بن كمال الدين بن مهاجر فقتلوه على باب سنجار، ثم رجع التتارُ، ثمَّ عادت، فأم"},{"id":2513,"era":"c7","t":"أبو عبد الله الحفصي يعلن استقلاله عن دولة الموحدين في تونس .","s":"عاد أبو زكريا الحفصي إلى تونس بعد حملته المظفرة، وأعلن على رؤوس الملأ استقلالَه بالملك، وانقطاع تبعيَّته للموحِّدين رسميًّا، وبايع لنَفسِه بيعةً عامَّةً في هذه السَّنة وضرب السكَّة باسمِه، وأمر أن يُخطَبَ له باسمِه على كل منابِرِ بلاده، ثم بايع لابنه أبي يحيى وليًّا للعهدِ سنة 638(1246م)."},{"id":2514,"era":"c7","t":"دخول التتار لإربل .","s":"حاصرت التتار إربل بالمجانيق ونقبوا الأسوارَ حتى فتحوها عَنوةً فقَتَلوا أهلها وسَبَوا ذراريهم، وامتنعت عليهم القلعةُ مُدَّةً، وفيها النائبُ من جهة الخليفة، فدخل فصلُ الشتاء فأقلعوا عنها وانشَمَروا إلى بلادهم، وقيل إنَّ الخليفة جهَّزَ لهم جيشًا فانهزم التتار."},{"id":2515,"era":"c7","t":"وفاة الملك العزيز صاحب حلب وتولي ابنه بعده .","s":"هو الملك العزيز الظاهر صاحِبُ حلب محمد بن السلطان الملك الظاهر غياث الدين غازي بن الملك الناصر صلاح الدين الأيوبي، وهو وأبوه وابنه الناصر أصحاب حلب من أيام الناصر، توفي وله من العمر أربع وعشرون سنة، وكان مدبِّرُ دولته الطواشي شهاب الدين، وقام في الملك بعده ولده الناصر صلاح الدين يوسف وعمره نحو السبع سنين، وقام بتدبير أمره الأميران لؤلؤ الأميني، وعز الدين عمر بن محلي، وبينهما وزيرُ الدولة جمال الدي"},{"id":2516,"era":"c7","t":"محاولة الملك الكامل الأيوبي أخذ حلب .","s":"لَمَّا شرَعَ الملك الكامل بالتجهز لأخذ حلب، خافه المجاهِدُ أسد الدين شيركوه الصغيرُ صاحب حمص، وبعث ابنَه المنصورَ إبراهيم فتقَرَّر الأمرُ على أن يحمِلَ المجاهِدُ كُلَّ سنة للملك الكامل ألفي ألف درهم، فعفا عنه، وكان منذ دخلَ الكامِلُ إلى قلعة دمشق قد مَرِضَ وتوفِّي فيها."},{"id":2517,"era":"c7","t":"اضطرابات بين الأيوبيين بعد وفاة الكامل صاحب مصر .","s":"قوي المجاهِدُ أسد الدين شيركوه الأصغر صاحب حمص بعد موت الكامل، وأغار على حماة وحصرها واستعدَّ أهل حلب، واستنجدوا عسكرًا من الخوارزمية، وعسكرًا من التركمان، كان قد صار إليهم عِدَّة من أصحاب الملك الكامل، فأكرموهم، وبَعَثوا إلى السلطان غياث الدين كيخسرو بن كيقباذ، ملك الروم، يسألونه إرسالَ نجدة، فأمدَّهم بخيار عسكره، وخرجوا فمَلَكوا المعرَّة، ونازلوا حماة، وقاتلوا المظفَّر صاحبَها، فثبت لهم وامتنع ع"},{"id":2518,"era":"c7","t":"انهيار دولة بني هود في الأندلس وقيام دولة بني الأحمر في غرناطة .","s":"بعد اغتيال محمد بن يوسف بن هود انهارت دولتُه وانتهت، فقامت في غرناطة دولةُ بني نصر من بني الأحمر بعد أن تحرَّرَت من سيطرة بني هود, بزعامة أبي عبد الله بن يوسف بن نصر, ودولة بني الأحمر هي آخرُ دول الطوائفِ في الأندلس."},{"id":2519,"era":"c7","t":"قصد التتار بغداد .","s":"ورد الخَبَرُ باستيلاء الصالح نجم الدين أيوب بن الكامل على سنجار ونصيبين والخابور، وقدم رسول الخليفة بمالٍ إلى الملك الكامل، ليستخدِمَ به عسكرًا للخليفة، فإنَّه بلغه توجه التتر إلى بغداد، فقام الملك الكامل لَمَّا سلم إليه كتاب الخليفة، ووضعه على رأسه، وكان جملةُ ما حضر من المال مائة ألف دينار مصرية، فأمرَ الملك الكامل أن يخرج من بيت المال مائتا ألف دينار، ليستخدم بها العساكر، وأن يجرَّد من عساكر مص"},{"id":2520,"era":"c7","t":"استيلاء الأسبان على مدن المسلمين الأندلسية .","s":"من حين تخلى الموحِّدون عن الأندلس إثرَ هزيمتهم المُرَّة أمام التحالف الصليبي الأسباني في معركة العقابِ وبعدها بدأت المدنُ الأندلسيَّة الإسلامية تتساقَطُ وتقع في أيدي الأسبانِ الصليبيين، وسَمَّوا حركتَهم تلك بحروب الاسترداد فسَقَطت قرطبة وبطليوس هذه السنة، وسقطت ماردةُ قبلها بسنوات، وكذلك جزر البليار، ثم سقطت بلنسية ومرسية سنة 641 ثم إشبيلية سنة 646 ثم شلب سنة 648 ثم قادس سنة 660."},{"id":2521,"era":"c7","t":"وفاة الملك الأشرف صاحب دمشق وملك أخيه بعده .","s":"هو أبو الفتح موسى بن الملك العادل سيف الدين أبي بكر بن أيوب، الملقب بالملك الأشرف مظفر الدين. ولد سنة 576، بالديار المصرية بالقاهرة، وقيل بقلعة الكرك, ونشأ بالقُدس الشريف بكفالة الأمير فخر الدين عثمان الزنجاري، وكان أبوه يحبه، وكذلك أخوه المعظَّم, مليحَ الهيئة، حلو الشمائل، وكان فيه دينٌ وخوف من الله وفضيلة، على لَعِبِه, وعكوف على الملاهي- عفا الله عنه - وكان جوادًا سمحًا فارسًا شجاعًا. وكان يبالغ"},{"id":2522,"era":"c7","t":"استيلاء الملك الكامل على دمشق .","s":"بعد موت الأشرف موسى بن العادل أبي بكر بن أيوب صاحب دمشق قام من بعده بدمشق أخوه الملك الصالح عماد الدين إسماعيل، صاحِبُ بصرى، بعهدٍ من أخيه له، فاستوفى الملك الصالح عماد الدين على دمشقَ وبعلبك، وبعث ابنه الملك المنصور محمودًا إلى الشرق، ليتسَلَّم سنجار ونصيبين والخابور من نوَّاب الشرق، وبعث إلى المجاهد صاحب حمص، وإلى المظفر صاحب حماة، وإلى الحلبيين أيضًا، ليحلفوا له ويتفقوا معه على القاعدة التي تقَ"},{"id":2523,"era":"c7","t":"وفاة الملك الكامل صاحب مصر .","s":"هو أبو المعالي محمد بن الملك العادل، الملقب بالملك الكامل ناصر الدين، ولد سنة 576، وكان أكبر أولاد العادل بعد مودود، وإليه أوصى العادل لعلمه بشأنه وكمال عقله، وتوفُّر معرفته، ملك مصر ثلاثينَ سنة، وكانت الطرقاتُ في زمانه آمنة، والرعايا متناصفة، لا يتجاسَرُ أحد أن يظلم أحدًا، وكانت له اليد البيضاء في رد ثغرِ دمياط إلى المسلمين بعد أن استحوذ عليه الفرنج، فرابطهم أربعَ سنين حتى استنقذه منهم، وكان يومُ"},{"id":2524,"era":"c7","t":"السلطان العادل الثاني بن الكامل الأيوبي يمتلك مصر بعد وفاة أبيه .","s":"استقر الأمر للملك العادل الثاني بن الملك الكامل بمصر ودمشق يوم الخميس في الثاني عشر من رجب، وهو السلطان السابع من بني أبوب بديار مصر، فقدمت عليه القصاد من دمشق بوفاة أبيه واستقراره من بعده، فشرع الأميرُ سيف الدين قلج في تحليف الأمراء للملك العادل في داره، وحطَّ الملك العادل المكوس، ووسَّع في العطاء وفي الأرزاق على كلِّ أحدٍ، وفي رابع شعبان خطب له بمصر، وأعلن بموت الملك الكامل، وفي رابع عشر شعبان ض"},{"id":2525,"era":"c7","t":"نهاية الدولة العيونية في البحرين .","s":"استمَرَّت سيطرة عبد القيس على إقليم البحرين وبينونة الدنيا ومزيرعة إلى وقت نهاية الدولة العيونيَّةِ العبقسية، وقد استمَرَّ حكم الدولة العيونية من سنة 470 (1077م) إلى سنة 636 (1238م) ثم أخذ الضَّعفُ ينخر في أركان هذه الدولة فتوالى سقوط مناطقِها واحدةً تلو الأخرى على يد العصفوريين، وقُتِلَ آخِرُ أمرائهم محمد بن محمد بن ماجد العيوني، بعد أن حكموا بلاد البحرين قرابة 167سنة."},{"id":2526,"era":"c7","t":"قيام إمبراطورية مالي الإسلامية في أفريقيا الغربية .","s":"عندما قوي أمر الصوصو الذين قضوا على إمبراطورية غانا ضَمُّوا إليهم أكثَرَ الممالك التي كانت تتبع لغانا، ومنها مملكة كانغابا (مالي) وقُتِلَ ملك الصوصو سومانغارو ملكهم وأولاده الأحد عشر باستثناء الصغير منهم، وهو سندياتا إذ عرف فيما بعد بماري جاطه الذي تمكن بعد أن كبر من إحراز النصر على الصوصو، وقتل فيها إمبراطور الصوصو عام 633, فانتهى أمر الصوصو وسار ماري جاطه إلى عاصمة إمبراطورية غانا ودمر ما كان بق"},{"id":2527,"era":"c7","t":"سقوط مدينة بلنسية الأندلسية في يد نصارى الأسبان .","s":"بلنسية مدينة شهيرة بالأندلس، تقع شرقيَّ مدينتي تدمير، وقرطبة، وتتَّصِلُ بزمام إقليم مدينة تدمير. وفي بلنسية تأسَّست مملكة إسلامية عام 401 (1010م) على يدِ اثنين من موالي المنصور بن عامر ووقعت بلنسية في القرون التالية تحت سيطرة حكام ملوك الطوائف. ثمَّ المرابطين، ثم الموحدين، إلى أن سقطت في أيدي الفرنجة سنة 636 (1238م) بعد سقوط قرطبة. وفي يوم الجمعة 27 صفر سنة 636 (9 أكتوبر 1238م) دخل خايمي ملك أراجو"},{"id":2528,"era":"c7","t":"استيلاء الصالح نجم الدين أيوب على دمشق ومحاولته الاستيلاء على مصر .","s":"جهز الملك العادِلُ بن الملك الكامل جماعة من الأمراء، وعدة من العساكر بديار مصر لتأخذ دمشق، وقدَّم الملك العادل إلى الملك الجواد نائبِه على دمشق رسولًا بكتابٍ فيه أنَّه يعطيه قلعةَ الشوبك وبلادها، وثغرَ الإسكندرية، وأعمال البحيرة وقليوب، وعشر قرى من بلاد الجيزة بديار مصر، لينزِلَ عن نيابة السلطة بدمشق، ويحضُرَ إلى قلعة الجبل، ليعمَلَ برأيه في أمور الدولة، فلما وفى ذلك أوهمه نائبُه عماد الدين قلج من"},{"id":2529,"era":"c7","t":"استيلاء الفرنج على مدينة قرطبة .","s":"استولى أعداءُ الله من الفرنج على مدينة قرطبة قاعدة بلاد الأندلسِ ودارِ مملكتها، وذلك يوم الأحد الثالث والعشرين من شوال."},{"id":2530,"era":"c7","t":"وفاة السلطان المجاهد أسد الدين شيركوه الصغير صاحب حمص .","s":"هو السلطان الملك المجاهد أسد الدين شيركوه الصغير، أبو الحارث بن ناصر الدين محمد بن أسد الدين شيركوه بن شادي، صاحبُ حمص، ولَّاه إياها الملك الناصر صلاح الدين بعد موت أبيه سنة إحدى وثمانين وخمسمائة، فمكث فيها سبعًا وخمسين سنة، ولد بمصر سنة 569 وكان من أحسن الملوك سيرةً، طَهَّر بلاده من الخمور والمكوس والمنكرات، وهي في غايةِ الأمن والعدل، لا يتجاسر أحدٌ من الفرنج ولا العرب يدخلُ بلاده إلا أهانه غايةَ"},{"id":2531,"era":"c7","t":"حملة صليبية فرنسية فاشلة على بلاد الشام .","s":"دعا البابا غريغوار التاسع لحملة صليبية جديدة، فاستجاب لها عددٌ من الأمراء الفرنسيين، منهم أمير شامباني، وملك نافار، وأمير برغوني، وغيرهم، فتجَهَّزَ هؤلاء الأمراءُ الفرنسيون بحملةٍ فاتَّجهوا إلى بلادِ الشَّامِ بحرًا ونزلوا في عكا، ثم اعتَرَضت في غزة قافلةٌ تجارية متجهة إلى دمشق فنَهَبوا ما فيها، فسَيَّرَ الملك العادل صاحِبُ مصر جيشًا لقتالهم، فأفنوا كثيرًا من رجالها واضطرَّ من بقي منهم إلى الانسحاب"},{"id":2532,"era":"c7","t":"المغول يغزون أوروبا .","s":"وجَّهَ أوجتاي بن جنكيزخان ثلاثةَ جيوش أحدها إلى كوريا، والثاني إلى إمبراطورية سونغ في جنوب الصين الذين ساعدوه بالأمس ضد إمبراطورية كين في شمال الصين، والجيش الثالث إلى شرقي أوروبا وقائد هذا الجيش الأخير هو باتو بن أخيه جوجي، فدخل باتو بلاد البلغار، وهي قازان، ثم دخل موسكو واتجهوا إلى كييف أكبر مدنِ روسيا آنذاك، فأبادوها وقتلوا أهلَها وقطعوا آذانَهم وجمعوها في أكياسٍ، ثم انقسم جيشُ باتو إلى قسمين: "},{"id":2533,"era":"c7","t":"البابا يدعو إلى حرب صليبية ضد المغول .","s":"بعد أن رأى الصليبيون أعمال المغول التتار في البلاد التي يسيرون إليها ويحتلُّونها وشناعَتَهم ووحشيَّتَهم وما فعلوه في روسيا وبولندا من غزوهم أوروبا. قام البابا غريغور التاسع بالدعوة إلى حرب صليبية، ولكن هذه المرة ضد المغول، وليس ضد المسلمين، علمًا بأنَّه قد قيل إن الصليبيين هم من حرَّضوا المغول على التحرك إلى بلاد المسلمين خوارزم وأذربيجان وغيرها؛ وذلك حتى يجعلوا المسلمين بين فكَّي كماشة: من الشرق "},{"id":2534,"era":"c7","t":"استيلاء الصالح إسماعيل والمجاهد أسد الدين على دمشق .","s":"استهلت هذه السَّنةُ وسلطانُ دمشق نجم الدين الصالح أيوب بن الكامل مخيِّم عند نابلس، يستدعي عمَّه الصالح إسماعيل؛ ليسيرَ إلى الديارِ المصريةِ؛ لأخْذِها من صاحبها العادل بن الكامل، فلما كان يومُ الثلاثاء السابع والعشرين من صفر هجم الملك الصالح إسماعيل وفي صحبته المجاهِدُ أسد الدين شيركوه صاحب حمص على دمشقَ، فدخلاها بغتةً من باب الفراديس، فنزل الصالح إسماعيل بدارِه من درب الشعارين، ونزل صاحِبُ حمص بدا"},{"id":2535,"era":"c7","t":"وقعة بين الفرنج والعسكر المصري .","s":"في يوم الأحد رابع عشر ربيع الأول وقع بين الفرنج وبين العسكر المصري المقيم بالساحلِ حَربٌ، انحسَرَ فيها الفرنج، وأُخِذَ من الفرنج ملوكُهم وأكنادُهم، وثمانون فارسًا، ومائتان وخمسون راجلًا وصَلوا إلى القاهرة، وقُتِلَ منهم ألف وثمانمائة، ولم يُقتَل من المسلمين غيرُ عشرة رجال."},{"id":2536,"era":"c7","t":"انتهاء مدة صلح يافا مع الصليبيين .","s":"انتهت مدةُ الصلح المعقود بين الملك الكامل بن الملك العادل وبين فردريك الثاني ملك الألمان على ما ذكرناه سنة 624، وكانت المدة عشر سنوات، وكان بموجبه قد تسلم الصليبيون القدس، وبه نَصَّب فردريك نفسه ملكًا على القُدسِ."},{"id":2537,"era":"c7","t":"تولي الشيخ عز الدين بن عبدالسلام الخطابة بجامع دمشق .","s":"في يوم الأربعاءِ ثالث ربيع الآخر وليَ الشيخ عز الدين عبد العزيز بن عبد السلام بن أبي القاسم السلمي خَطابةَ جامِعِ دمشقِ."},{"id":2538,"era":"c7","t":"استرداد القدس من الصليبيين .","s":"في أثناءِ الاختلاف بين الملوك التركمان استغل الفرنجُ الوضع فعَمَروا في القُدسِ قلعةً، وجعلوا برجَ داود أحدَ أبراجها، وكان قد تُرِكَ لَمَّا خرب الملك المعظم أسوارَ القُدس، فلما بلغ الناصرَ داود بن الملك المعظَّم صاحب الكرك والأردن عمارةُ هذه القلعة، سار إلى القدسِ ورمى عليها بالمجانيقِ حتى أخَذَها، بعد واحد وعشرين يومًا في يوم تاسع جمادى الأولى عَنوةً بمن معه من عسكر مصر، وتأخَّر أخْذُ برج داود إلى"},{"id":2539,"era":"c7","t":"خلع الملك العادل صاحب مصر وتعيين الملك الصالح نجم الدين .","s":"بعد استيلاء الصالح إسماعيل والمجاهد أسد الدين شيركوه على دمشقَ ولَمَّا وصل الخبر إلى الصالح نجم الدين وهو مقيمٌ في نابلس يتجهَّزُ للمسير إلى مصر، افتَرَق عنه عسكرُه وبقي وحيدًا، فاستغل الفرصةَ الملك الناصر داودُ بن الملك المعظَّم صاحب الكرك والأردن فأرسل إليه من أخَذَه من نابلس مهانًا على بغلةٍ بلا مهماز ولا مُقَدمة، فاعتقله عنده سبعةَ أشهر، فأرسل العادِلُ من مصر إلى الناصر ِيطلب منه أخاه الصالحَ "},{"id":2540,"era":"c7","t":"ولاية الملك الصالح نجم الدين أيوب على مصر .","s":"بعد وفاة الملك الكامل محمد سنة 635 (1238م) تعرضت الدولة الأيوبية في مصر والشام لخطر الانقسام والفوضى، فاستولى الصالح نجم الدين أيوب على دمشق سنة 636 (1239م)، وكان هذا إيذانًا بدخوله في صراعٍ مع أخيه الملك العادل الصغير بن الكامل الذي خلَف أباه على حكم مصر والشام، واستعان كلٌّ منهما بأنصارٍ مِن البيت الأيوبي للوقوفِ في وجه الآخر، وفي غمرة الصراع قفَزَ عمُّهما الصالح إسماعيل على دمشق واستولى عليها، "},{"id":2541,"era":"c7","t":"ثورة المسلمين على الملك الصالح إسماعيل في دمشق .","s":"بعد أن بدأ الخلاف في البيت الأيوبي وخاف كل أميرٍ من الآخر، لم يجدوا سبيلًا إلا الاستنجاد بالكُفَّار على إخوانهم، وتعهدوا لهم بعهودٍ ومواثيق وتسليمِ للبلاد, فسَلَّم الملك الصالح إسماعيل صاحب دمشق حصن شقيف أرنون لصاحب صيدا الفرنجي وسلَّمه غيرها من المدن، فاشتد الإنكارُ عليه من الناس عامَّةً؛ بسبب ذلك، حتى إن الشيخ عز الدين بن عبد السلام خطيب البلد، والشيخ أبا عمرو بن الحاجب شيخ المالكية ندَّدا به وق"},{"id":2542,"era":"c7","t":"انتقال الشيخ عز الدين بن عبدالسلام إلى مصر  .","s":"لَمَّا أطلق الملك الصالح إسماعيل صاحب دمشق سراح الشيخ عز الدين بن عبد السلام من سجنه بسبب إنكاره عليه تسليمَه أراضي المسلمين للصليبيين، ترك الشام وانتقل إلى الديار المصريَّة، فتلقاه صاحبها الملك الصالح نجم الدين أيوب بالاحترامِ والإكرامِ، وولَّاه خطابة القاهرة وقضاءَ مصر، واشتغل عليها أهلُها، فكان ممن أخذ عنه الشيخ تقي الدين بن دقيق العيد- رحمهما الله تعالى."},{"id":2543,"era":"c7","t":"النزاع بين الملوك الأيوبيين واستنجادهم بالصليبيين .","s":"استولى الصالح نجم الدين أيوب على مصر، ثم استولى عمه الصالح إسماعيل على دمشق، ثم إن الناصر داود بن الملك المعظَّم الذي كان أطلق الصالح نجم الدين أيوب مِن أسرِه إلى مصر فمَلَكها على أن يعطيه بعضَ البلاد فخلفه، فانحاز إلى الصالح إسماعيل ومعهم كذلك صاحب حمص، كل هذه الأمور من النزاعات بين أمراء البيت الأيوبي أدت إلى تولد شرارة الحرب بينهم، فخاف الصالح عماد الدين صاحب دمشق من الملك الصالح نجم الدين صاحب"},{"id":2544,"era":"c7","t":"وصول رسالة من ملك المغول إلى المسلمين .","s":"وصل رسول التتار من ملكهم خاقان إلى الملك المظفَّر شهاب الدين غازي بن العادل، صاحب ميافارقين، ومعه كتاب إليه وإلى ملوك الإسلام، عنوانه: من نائب رب السماء، سامح وجه الأرض، ملك الشرق والغرب، قاقان، فقال الرسول لشهاب الدين صاحب مياقارفين: قد جعلك قاقان سلاحَ داره، وأمرك أن تخربَ أسوار بلدِك، فقال له شهاب الدين: أنا من جملةِ الملوك، وبلادي حقيرةٌ بالنسبة إلى الروم والشام ومصر، فتوجَّهْ إليهم، وما فعلوه"},{"id":2545,"era":"c7","t":"الحملة الصليبية الإنجليزية .","s":"هذه الحملة الصليبية كانت مكونة من المتطوعة الإنكليز بقيادة ريتشارد كورنفيل أخو هنري الثالث ملك إنكلترا، وقد وصلت هذه الحملة إلى عكا، وقامت بتحصين عسقلان، فاعترف لها الملك الصالح نجم الدين أيوب بحق الصليبيين في ملكيَّة إقليم الجليل فضلًا عن بيت المقدس وعسقلان ولكن ريتشارد اكتفى بما استولى عليه، ثم إنه أبحر عائدًا إلى بلاده."},{"id":2546,"era":"c7","t":"ظهور متنبئ في بلاد الروم .","s":"ظهر في بلاد سلاجقة الروم متنبئ يدعى بابا إسحاق تركماني الأصل ادعى أنه نبي، فكان يقول للناس: قولوا لا إله إلا الله بابا ولي الله، ثم إنه انخدع به أناس كثيرون فصار له أتباع وقوي أمره فأرسل إليه السلطان غياث الدين كيخسرو سلطان سلاجقة الروم جيشًا فاقتتلوا، فكان فيها قتل المتنبئ وقتل أربعة آلاف رجل."},{"id":2547,"era":"c7","t":"وفاة السلطانة رضية الدين إحدى سلاطين دولة المماليك بالهند .","s":"هي رضية الدين بنت السلطان شمس الدين ألتمش المؤسس الحقيقي لدولة المماليك بالهند، وقد اشتهر ألتمش بالعدل وتحقيق الأمن في دولته. وكان ألتمش يحب ابنته ويقدمها على إخوانها الذكور لما يتوسم فيها من النجابة والهمة العالية, كما أنها كانت غاية في الحسن والجمال وعذوبة المنطق؛ لذا كان يسند إليها بعض المهام، حتى إنه فكَّر في أن يجعلها وليَّة للعهد دون إخوانها الذكور الذين انشغلوا باللهو والملذات، فلما مات ألت"},{"id":2548,"era":"c7","t":"وفاة الصوفي الملحد محي الدين ابن عربي .","s":"هو محمد بن علي بن محمد بن عربي أبو عبد الله الطائي الأندلسي، ولد في مرسية بالأندلس سنة 560 ثم انتقل إلى إشبيلية، ودرس القرآن والفقه والحديث، ومال إلى المذهب الظاهري، ثم رحل إلى الحجاز وأقام بمكة مدة سنتين، ثم رحل مع الحجاج الأتراك إلى قونية، ثم قصد بغداد، ثم استقر في دمشق، وله مصنفاتٌ كثيرة جدًّا، أشهرها كتابه المسمى بـ \"الفتوحات المكية وفصوص الحكم\" وفيها أشياء كثيرة ظاهرها كفر صريح، وله كتاب \"الع"},{"id":2549,"era":"c7","t":"إغارة الخوارزمية على حلب .","s":"أغار الخوارزمية على بلاد قلعة جعبر وبالس ونهبوها، وقتلوا كثيرًا من الناس، ففرَّ من بقي إلى حلب ومنبج، واستولى بدر الدين لؤلؤ صاحب الموصل على سنجار، وأخرج منها الملك الجواد يونس بن مودود بن العادل بن نجم الدين أيوب، فسار الجواد إلى الشام، حتى صار في يد الناصر داود بن الملك المعظم، فقبض عليه بغزة يوم الأحد ثامن عشر ذي الحجة، وبعث به إلى الكرك، وانضمَّت الخوارزمية على صاحب الموصل، فصاروا نحو الاثني ع"},{"id":2550,"era":"c7","t":"إغارة الخوارزمية على الموصل .","s":"سار الخوارزمية إلى الموصل، فسالمهم صاحبها بدر الدين لؤلؤ، ووافقهم المظفَّر شهاب الدين غازي بن العادل، صاحب ميافارقين، ثم ساروا إلى آمد فخرج إليهم عسكرُ حلب عليه المعظَّم فخر الدين توران شاه بن صلاح الدين، فدفعوهم عنها، ونهَبوا بلاد ميافارقين، وجرت بينهم وبين الخوارزميَّة وقائع، ثم عاد العسكرُ إلى حلب، فغار الخوارزمية على رساتيق الموصل, ثم اصطلح شهابُ الدين غازي صاحب ميافارقين معهم وآواهم إلى بلده "},{"id":2551,"era":"c7","t":"أبو زكريا الحفصي يوسع حكمه في إفريقية على حساب الموحدين .","s":"قام أبو زكريا الحفصي على رأس حملةٍ ضَخمةٍ قَدَّرَها بعض المؤرخين بستين ألف مقاتل، فدخل تلمسان، وأجبر واليها يغمراسن على الدخول في طاعتِه، والخُطبةِ باسمه، كما أدخل في طاعتِه القبائِلَ العربية والبربريَّة في المناطق المحيطة. وكان من أثر ازدياد قُوَّته واتساع نفوذه أن هادنه بنو مرين في المغرب الأقصى، وأقيمت الخطبةُ باسمه في عددٍ كبيرٍ مِن بلاد الأندلس التي لم تقع في براثن الأسبانِ، واحتفظت بحرِّيَّت"},{"id":2552,"era":"c7","t":"القتال بين الموحدين وبني مرين في المغرب .","s":"سيَّرَ أبو محمد عبد الواحد الرشيد بن أبي العلاء المأمون الموحدي جيشًا لقتال بني مرين، فهزمهم واستولى على عسكرهم، فتدالت الحروب بينهم إلى أن انتهت إلى استيلاءِ بني مرين على مكناس وفاس التي كانت حاضرةَ الموحدين، كما استولوا بعد ذلك على سجلماسة ودرعة."},{"id":2553,"era":"c7","t":"اقتتال عسكر مصر مع عسكر الشام .","s":"بلغ السُّلطانُ صاحِبُ مصر أنَّ الناصِرَ داود بن الملك المعظَّم صاحب الكرك قد وافق الصالحَ إسماعيل صاحب دمشق، والمنصور إبراهيم صاحب حمص، وأهل حلب، على محاربته، فسير السلطان كمال الدين بن شيخ الشيوخ على عسكر إلى الشام، فخرج إليه الناصرُ وقاتله ببلاد القدس، وأسَرَه في عدة من أصحابه، ثم أطلقهم وعادوا إلى القاهرة، وكان من خبر ذلك أنَّه في يوم الأربعاء ثاني عشر صفر، وقع عسكر الناصر داود على الأمير عز ال"},{"id":2554,"era":"c7","t":"وقعة بين الحلبيين وبين الخوارزمية .","s":"كانت وقعة عظيمة بين الحلبيين وبين الخوارزمية، ومع الخوارزمية شهاب الدين غازي صاحب ميافارقين، فكسرهم الحلبيون كسرةً عظيمةً مُنكرةً، وغَنِموا من أموالهم شيئًا كثيرًا جدًّا."},{"id":2555,"era":"c7","t":"نهب الخوارزمية نصيبين .","s":"نهب الخوارزمية نصيبين مرة أخرى، وهذه سابع عشر مرة تنهب نصيبين في هذه السنين، وعاد شهاب الدين غازي إلى ميافارقين، وتفَرَّقت الخوارزمية يفسدون في الأرض بصحبة مُقَدَّمهم بركات خان، وقَدِمَ على شهاب الدين غازي منشور بمدينة خلاط فتسَلَّمَها وما فيها من الحواصل."},{"id":2556,"era":"c7","t":"استيلاء الحفصيين على مدن جزائرية .","s":"قام الحفصيون بهزيمة يغمراسن بن زيان زعيم دولةِ آل زيان من بني عبد الواحدِ، واستولوا على حاضرته تلمسان، ثم قاموا بالاستيلاء على مدن جزائريَّة أخرى."},{"id":2557,"era":"c7","t":"وفاة الخليفة العباسي المستنصر بالله .","s":"هو أميرُ المؤمنين الخليفة العباسي المستنصر بالله أبو جعفر منصور بن الخليفة الظاهر بأمر الله محمد بن الخليفة الناصر لدين الله أبي العباس أحمد. واقف المستنصريَّة التي لا نظيرَ لها. ولد سنة 588, وأمه تركية، وكان جده الناصر يحبُّه ويسميه القاضي؛ لحبه للحقِّ، وعقلِه, وبويعَ عند موت والده يوم الجمعة، ثالث عشر رجب، سنة 623 البيعة الخاصة من إخوته وبني عمه وأسرته، وبايعه من الغد الكبراء والعلماء والأمراء. "},{"id":2558,"era":"c7","t":"خلافة المستعصم بالله آخر خلفاء بني العباس  .","s":"تولى الخلافةَ المستعصمُ بالله وهو آخر خلفاء بني العباس ببغداد، وهو الخليفة الذي قتله التتار بأمر هلاكو بن تولي ملك التتار بن جنكيزخان، سنة 656، وآباؤه ثمانية نسقًا وَلُوا الخلافة لم يتخلَّلهم أحد، وهو التاسِعُ، ولما توفي أبوه بكرةَ الجمعة عاشر جمادى الآخرة استدعي هو من التاج يومئذ بعد الصلاة، فبويع بالخلافة، ولقب بالمستعصم بالله، وله من العمر يومئذ ثلاثون سنة وشهور، وقد أتقن في شبيبته تلاوة القرآن"},{"id":2559,"era":"c7","t":"اجتياح المغول دولة سلاجقة الروم .","s":"قدم التتار بلاد الروم، وأوقعوا بالسلطانِ غياث الدين كيخسرو بن كيقباذ بن يخسرو بن قلج أرسلان، وهزموه وملكوا بلادَ الروم وخلاط وآمد، فدخل غياثُ الدين في طاعتِهم، على مالٍ يحملُه إليهم، وملكوا أيضًا سيواس وقيسارية بالسيف وقرَّروا على صاحبهما في كل سنة أربعمائة ألف دينار ففَرَّ غياث الدين منهم إلى القسطنطينية، وقام من بعده ركنُ الدين ابنه وهو صغيرٌ إلى أن قُتِل."},{"id":2560,"era":"c7","t":"فشل محاولة الصلح بين الصالح صاحب دمشق والصالح صاحب مصر .","s":"تكرَّرَت المراسلةُ بين الصالح نجم الدين أيوب صاحب مصر، وبين عَمِّه الصالح إسماعيلَ صاحبِ دمشق، وبين المنصورِ صاحِبِ حمص، على أن تكون دمشقُ وأعمالها للصالح إسماعيل، ومصر للصالح أيوب، وكلٌّ من صاحب حمص وحماة وحلب على ما هو عليه، وأن تكون الخطَّة والسكَّة في جميع هذه البلاد للملك الصالح نجم الدين أيوب، وأن يُطلِق الصالح إسماعيل الملك المغيث فتح الدين عمر بن الملك الصالح نجم الدين من الاعتقالِ، وأن يخ"},{"id":2561,"era":"c7","t":"البابا يدعو المغول لاعتناق النصرانية .","s":"لَمَّا رأى الصليبيون قوةَ التَّتار وأنَّهم لا قِبَل لهم بهم وخافوا عليهم من أن يُسلِموا بحكم احتكاكهم بالمسلمين، أرادوا أن يَجُرُّوهم إلى النصرانيَّة، فقام البابا إينوسان الرابع بإرسال بعثة إلى خاقان ملك المغول إلى عاصمتِهم قره كروم يدعوه فيها إلى اعتناق النصرانيَّة، فاشترط الخاقان لاعتناقها دخول البابويَّة وجميع ملوك وأمراء الغرب تحت سيادتِه."},{"id":2562,"era":"c7","t":"حصار غرناطة .","s":"قام ألفونسو بن فريناند ملك قشتالة بالاستيلاء على حصن أراغونة وعدة حصون أخرى وحاصر غرناطة، فقام ابن الأحمر أبو عبد الله محمد بن نصر بمهادنته بعد أن أيقَنَ أنَّه لا قِبَلَ له به وبمنازلتِه، ففَكَّ الحصار عن غرناطة بصلحٍ بينهما يقضي فيه أن يبقى ابن الأحمر حاكمًا على غرناطة، لكن باسم ملك قشتالة وتحت ظله، ويؤدي جزيةً سنوية ويُعينه على أعدائه وقت يريدُ، وأن يشهَدَ معه اجتماعَ مجلس قشتالة الكورتيس باعتبا"},{"id":2563,"era":"c7","t":"الخوارزمية يستردون بيت المقدس .","s":"نشب النزاعُ بين الصالحَينِ إسماعيلَ ونجمِ الدين أيوب مرة أخرى، ووقف الناصرُ داود بن الملك المعظَّم هذه المرة مع الصالح إسماعيل، واتفقا على الاستعانة بالصليبيين ضِدَّ إخوانهم المسلمين، ولم يجدِ الصالح أيوب قُوَّةً تَقِفُ إلى جواره غيرَ الخوارزمية الذين تَفَرَّقت بهم السبل بعد انهيار دولتِهم ومقتل سلطانهم جلال الدين خوارزم شاه، فاستجابوا لدعوته، وقَدِموا بأعدادٍ كبيرة إلى الشام، فقطعوا الفراتَ، ومُق"},{"id":2564,"era":"c7","t":"انتصار الخوارزمية ونجم الدين أيوب على عساكر الشام والفرنج .","s":"جهَّزَ الملك الصالح نجمُ الدين أيوب عسكرًا من القاهرة عليه الأمير ركنُ الدين بيبرس، أحد مماليكِه الأخصَّاء الذين كانوا معه وهو محبوسٌ بالكرك، فسار إلى غزَّة، وانضم إلى الخوارزمية جماعةٌ من القميرية، كانوا قد قَدِموا معهم من الشرق، ثم خرج الأميرُ حسام الدين أبو علي بن محمد بن أبي علي الهذباني بعسكر، ليقيم على نابلس، وجهَّزَ الصالح إسماعيل عسكرًا من دمشق، عليه الملك المنصور صاحِبُ حمص، فسار المنصور "},{"id":2565,"era":"c7","t":"محاصرة الخوارزمية لدمشق .","s":"أخذ الملكُ الصالحُ نجمُ الدين أيوب صاحِبُ مصر دمشقَ بعد أن حاصرها بمساعدةِ الخوارزميَّة، وكان الخوارزميَّة يظنون أنَّ السلطانَ إذا انتصر على عَمِّه الملك الصالح إسماعيل يقاسِمُهم البلادَ حتى دمشق، فلما منعوا من دمشقَ، وصاروا في الساحِلِ وغيره من بَرِّ الشام، تغيَّرت نياتُهم، واتفقوا على الخروجِ عن طاعة الملكِ الصالح نجم الدين، وساروا إلى داريا وانتهبوها، وكاتَبوا الأميرَ ركنَ الدين بيبرس وهو على غ"},{"id":2566,"era":"c7","t":"وفاة الإمام تقي الدين أبي عمرو بن الصلاح .","s":"هو الإمامُ مفتي الإسلام تقي الدين أبو عمرو عثمان بن الإمام البارع أبي القاسم صلاح الدين عبد الرحمن بن عثمان بن موسى بن أبي نصر النصري الكردي، الشهرزوري، الشافعي. المعروف بابن الصلاح، مفتي الشام ومحدِّثُها، سمع الحديثَ ببلادِ الشَّرقِ وتفَقَّه بالموصِلِ وحلب وغيرها، وُلِدَ سنة 577 بشرخان – وهي قريةٌ من أعمال إربل قريبةٌ مِن شهرزور- تفقَّه على والِدِه صلاح الدين بشهرزور، وكان والدُه شيخَ تلك الناحية"},{"id":2567,"era":"c7","t":"الملك الصالح نجم الدين يحاصر عمه الصالح إسماعيل بدمشق .","s":"كَثُرَت محاربة الصاحب معين الدين بن شيخ الشيوخ ومعه الخوارزمية الذين كان مجيئُهم بناءً على طلب الملك الصالحِ نجم ِالدين  أيوب صاحبِ مصر، فحاصروا دمشقَ وقطعوا عنها الميرةَ فتضايقت البلدُ، ثم أحرقوا قصرَ الحجَّاج في ثاني محرم، ورمي بالمجانيق وألحَّ بالقتال، فأحرق الصالحُ إسماعيل صاحب دمشق في ثالثه عدَّة مواضع، ونُهِبَت أموال الناس، وجرت شدائدُ إلى أن أهل شهر ربيع الأول، ففيه خرج المنصورُ صاحب حمص من"},{"id":2568,"era":"c7","t":"وفاة الشيخ علم الدين أبي الحسن السخاوي .","s":"هو الإمام العلَّامة، شيخ القرَّاء والأدباء، عَلَمُ الدين أبو الحسن علي بن محمد بن عبد الصمد بن عبد الأحد بن عبد الغالب الهمذاني المصري السخاوي، ثم الدمشقي المقرئُ النحوي شيخُ القراء بدمشق، ولد سنة 558 وقيل سنة تسع وخمسين. كان قد اشتغل بالقاهرةِ على الشيخِ أبي محمد القاسم الشاطبي المقرئ، وأتقن عليه علم القراءات والنَّحو واللُّغة، وشرح قصيدتَه الشاطبيَّة، كان إمامًا في العربية، بصيرًا باللغةِ، فقيهً"},{"id":2569,"era":"c7","t":"وفاة الحافظ ضياء الدين المقدسي .","s":"هو الشَّيخُ الإمامُ الحافِظُ القدوة المحقِّق، المجَوِّد الحُجَّة، بقية السلف، أبو عبد الله ضياء الدين، محمد بن عبد الواحد بن أحمد بن عبد الرحمن بن إسماعيل، السعدي المقدسي، الجماعيلي، ثم الدمشقي، الصالحي، الحنبلي، صاحبُ التصانيف والرحلة الواسعة. ولد سنة 569 بدمشق في الدير المبارك، بقاسيون، سمع الحديث الكثير وكتب كثيرًا, وطوَّفَ بالبلاد وبَقِيَ في الرحلة المشرقيَّة مدَّة سنين، وحصَّل فيها الأصولَ ال"},{"id":2570,"era":"c7","t":"وفاة الحافظ ابن النجار .","s":"هو الإمامُ الحافظُ الكبيرُ، محَدِّث العراق، ومؤرِّخُ العصر، محبُّ الدين، أبو عبد الله محمَّد بن محمود بن حسن بن هبة الله بن محاسن بن النجار البغدادي, مولِدُه سنة 578. كان والدُه مقدمَ النجَّارين بدار الخلافة، وكان من العوام. أولُ سماع لابن النجار سنة ثمان وثمانين، وأول دخولِه في الطلب وهو حَدَثٌ سنة ثلاث وتسعين، سمع الكثيرَ ورحل شرقًا وغربًا، وهو صاحب كتاب ذيل التاريخ المعروف جعَلَه ذيلًا لتاريخ ب"},{"id":2571,"era":"c7","t":"البابا يبيح دم ملك القدس .","s":"قَدِمَت الرسلُ من عند البابا تخبِرُ بأنه قد أباح دمَ الأبدور ملكِ الفِرنجِ في القُدسِ لتهاونِه في قتال المسلمين، وأرسل البابا طائفةً مِن عنده ليقتُلوه، فلما انتهوا إلى المَلِك كان قد استعَدَّ لهم وأجلس مملوكًا له على السَّريرِ فاعتقدوه المَلِكَ فقتلوه، فعند ذلك أخَذَهم الأبدور فصَلَبَهم على باب قَصرِه بعد ما ذبحَهم وسلخَهم وحشى جلودَهم تبنًا، فلما بلغ ذلك البابا أرسَلَ إليه جيشًا كثيفًا لقتاله فأو"},{"id":2572,"era":"c7","t":"قتال الخوارزمية جيش الصالح أيوب صاحب مصر ودمشق .","s":"بعد رحيل الخوارزميَّة عن دمشق بعدما حاصروها حين أرسلَ الملك الصالحُ نجمُ الدين أيوب مِن مصرَ جيشًا لقتالهم وبعد تحالُفِ بيبرس معهم، وكذلك صاحب حمص، وكذلك الصالح إسماعيلُ كُلُّهم ضد صاحِبِ مصر، حيث أرسل الملِكُ الصالح أيوب القاضي نجمَ الدين محمد بن سالم النابلسي، المعروف بابن قاضي نابلس- وكان متقدمًا عنده- إلى مملوكِه الأمير ركن الدين بييرس، فما زال يخدعُه ويُمَنِّيه، حتى فارق الخوارزميَّة، وقَدِمَ"},{"id":2573,"era":"c7","t":"وفاة الملك المنصور صاحب حمص .","s":"هو الملك المنصور، ناصر الدين إبراهيم بن الملك المجاهد أسد الدين شيركوه الصغير بن محمد بن أسد الدين شيركوه الكبير. كان الملك المنصور بطلًا شجاعًا مُتواضعًا، عاليَ الهمة، وافر الهيبةِ. كان في بدايةِ أمرِه موافقًا للمَلِك الصالح إسماعيلَ ومُصاهِرًا له، سار بعَسكرِه وعسكر حلب، وعمل المصاف مع الخوارزمية والمظفر صاحب ميافارقين، فالتَقَوا في صفَر سنة أربعين، فهزمهم المنصورُ أقبَحَ هزيمةٍ، وتعثَّرت الخوار"},{"id":2574,"era":"c7","t":"اعتلاء \"كيوك خان\" عرش المغول خلفًا لأبيه \"أوكتاي خان\" .","s":"بعد وفاة \"جنكيز خان\" سنة 624 (1226م)، ظل مكانُه خاليًا مدَّة عامين، كان يقومُ خلالها الابنُ الأصغرُ \"تولوي\" بحكمِ الإمبراطوريَّة المغوليَّة بصفتِه وصيًّا على العرش، إلى أن اجتمَعَ كبار أمراء البيت الحاكم، وأجمعوا على اختيار \"أوكتاي\" خاقانًا للمغول خلفًا لأبيه جنكيز خان. واستمر أوكتاي يحكمُ المغول ثلاثَ عشرة سنة إلى أن تُوفي سنة 639 (1241م) بعد أن أتمَّ المغول في عهده فتحَ الصين الشمالية وجنوب روسي"},{"id":2575,"era":"c7","t":"إرسال ثاني سفارة نصرانية من البابا \"أنوسنت الرابع\" إلى المغول. .","s":"أرسل البابا سفارةً ثانية، غادرت ليون ووصَلَت منغوليا وحضرت حفلَ تتويج \"كيوك خان\" على عرشِ المغولِ في مدينة \"قرا قورم\" عاصمة المغول في 9 من ربيع الآخر 644  (24 من أغسطس 1246م)، وقد أكرم كيوك خان وفادةَ سفارة البابا، وردَّ على المطالب البابويَّة بالرَّفضِ، وطلب من البابا أن يخضَعَ هو وسائِرُ ملوك أوروبا المسيحيين للسيادة المغوليَّة."},{"id":2576,"era":"c7","t":"القتال بين الملك الصالح أيوب صاحب مصر والصالح إسماعيل  .","s":"سار الأميرُ حسام الدين بنُ أبي علي الهذباني من دمشق، واستولى على بعلبكَّ بغير حربٍ في رجب، وحَمَل منها الملك المنصورُ نورَ الدين محمود بن الملك الصالح إسماعيل، وأخَذَه الملك السعيدُ عبد الملك إلى الديار المصريةِ تحت الاحتياط، ثمَّ صَلَحت الحالُ بين السلطانِ الصالح نجمِ الدين أيوب وبين المنصور صاحِبِ حمصَ والناصِر صاحب حلب، واتفَقَت الكلمة وبَعَث الصالح نجم الدين أيوب إلى حلب يطلب تسليمَ الصالح إسم"},{"id":2577,"era":"c7","t":"دخول السلطان نجم الدين أيوب صاحب مصر إلى دمشق والقدس .","s":"خرج السُّلطانُ الملك الصالح نجمُ الدين أيوب بالعساكِرِ في شوال يريدُ دمشق واستناب بديارِ مِصرَ الأميرَ حُسام الدين بن أبي علي، فدخل إلى دمشقَ في سابع عشر ذي القعدة، وكان دخولُه يومًا مشهودًا، فأحسن إلى النَّاسِ، وخلع على الأعيانِ، وتصَدَّقَ على أهل المدارِسِ والرُّبُط وأرباب البيوت وسار بعد خمسة عشر يومًا إلى بعلبكَّ، فرَتَّبَ أحوالها، وسار إلى بُصرى، وقد تسَلَّمها نوابُ السلطان أيوب من الأمير شها"},{"id":2578,"era":"c7","t":"الدعوة لحرب صليبية سابعة .","s":"بعد أن استخلص المسلمونَ بيتَ المقدس من يد الفرنجِ وبلغ الخبَرُ إلى أوربا لاستنفارِ أُمَرائِها وملوكِها، انعقد مجلسٌ كَنَسي في ليون تقَرَّر فيه إرسالُ حملة صليبيَّة سابعة بزعامة ملك فرنسا لويس التاسع المشهور بوَرَعِه حتى لُقِّبَ بالقديس، فأعَدَّ هذا الملك العُدَّة وجهَّز جيشًا أبحر أواخِرَ هذه السنة متجهًا إلى الشرقِ، وقد تم وصولُ خبر هذه الحملة إلى الملك الصالحِ نجمِ الدين أيوب صاحبِ مصرَ عن طريق "},{"id":2579,"era":"c7","t":"إرسال سفارة نصرانية ثالثة من البابا \"أنوسنت الرابع\" إلى المغول .","s":"في الوقتِ الذي خَرَجت فيه السفارة الثانية للمغول في 9 من ربيع الآخر 644 (24 من أغسطس 1246م) كانت هناك سفارة ثالثة خرجت في إثرِها، ضَمَّت رهبانًا من جماعة \"الدومنيكان\" وأوكلَت إليها مهمَّة مختلفة عن مهمَّة السفارتينِ السَّابقتَينِ، فقد أمَرَ البابا هذه السفارةَ أن تَصِلَ إلى أوَّلِ جيشٍ مغوليٍّ تُقابِلُه في فارس، وأن يحضَّ قائدَه على الامتناعِ عن نَهبِ النَّاِس، وبخاصَّةٍ النَّصارى منهم، وأن يعتَنِ"},{"id":2580,"era":"c7","t":"الصالح أيوب يحرر طبرية وعسقلان من الصليبيين .","s":"سار الأميرُ فخر الدين بن شيخ الشيوخ أمير عسكر المَلِك الصالحِ نجم الدين أيوب صاحِب مصرَ بعسكرٍ إلى طبرية، ونزلت الجيوشُ لحصار الفرنج ففَتَحَت طبريَّةَ عَنوةً في عاشر صفر، وفَتَحَت عسقلان بعدَ حصارٍ شديد وأُخِذَت من يد الفرنجِ في أواخِرِ جُمادى الآخرةِ."},{"id":2581,"era":"c7","t":"محاولة استيلاء نجم الدين أيوب صاحب مصر على حمص .","s":"قايض الملكُ الأشرف موسى صاحِبُ حمص تل باشر بحمص مع الملك الناصِر يوسُفَ بنِ العزيز بن الظاهر بن صلاح الدين، صاحِبِ حلب؛ ولذلك خرج الملكُ الصالح نجم الدين أيوب صاحِبُ مصر من مصرَ بالعساكِرِ إلى دمشقَ وجَهَّزَ الجيوشَ والمجانيقَ إلى حمص، ولَمَّا عَلِمَ الحلبيونَ بخروج الدماشِقة برزوا أيضًا في جَحفلٍ عظيمٍ ليَمنَعوا حمصَ منهم، واتَّفَق وصول الشيخِ نجم الدين البادرائي مدرس النظاميَّة ببغداد في رسالةٍ "},{"id":2582,"era":"c7","t":"عزل أمير مكة من قبل صاحب اليمن .","s":"عزل الملكُ المنصورُ نورُ الدين عمر بن علي بن رسول صاحِبُ اليمن الأميرَ فخرَ الدين بن الشلاحِ عن مكَّةَ وأعمالِها، وولَّى محمد بن أحمد بن المسيب على مالٍ يقومُ به وقود عدده مائة فرسٍ كلَّ سنة، فقَدِمَ ابنُ المسيب مكة، وخرج الأميرُ فخر الدين، فسار بنفسِه إلى ابن المسيب وأعاد الجباياتِ والمكوس بمكَّة، وأخذ الصَّدَقةَ الواردة من اليمن، عن مالِ السلطان وبنى حصنًا بنخلةَ يسمى العطشان وحَلَّف هُذيلًا لنَ"},{"id":2583,"era":"c7","t":"سقوط أشبيلية في يد الفرنجة  .","s":"حاصر الأسبانُ إشبيليَّةَ مُدَّة ثمانية عشر شهرًا حتى سقَطَت في أيديهم فقاموا بتحويلِ جامِعِها إلى كنيسة وأزالوا كل معالمِ الإسلامِ فيها، ويُذكَرُ أن بعض المسلمين قد شاركوا في هذا الحصارِ بناءً على اتفاقهم مع النصارى، مثل محمد بن يوسف بن نصر أمير غرناطة من بني الأحمر، وقد تم هذا الاتفاقُ سنة 642، كما قام رامون ملك أراغون بإعلانِ حَربٍ صليبيَّةٍ على المسلمين بمباركة البابا واستولى بحملتِه تلك على لا"},{"id":2584,"era":"c7","t":"اتصال ملك الأرمن بالمغول .","s":"قام هيثوم الأول ملك أرمينية الصغرى بإرسال أخيه سمباط إلى منكو خاقان المغولِ الأكبر في عاصمتِه قره كروم، ثم تَبِعَه بنَفسِه مُقَدِّمًا للخاقان فروضَ الطاعةِ والولاء ووضَعَ الكنيسة ورعاياها تحتَ حمايته ورعايته."},{"id":2585,"era":"c7","t":"وفاة ضياء الدين بن البيطار .","s":"هو العلامةُ ضياءُ الدين أبو محمَّد عبد الله بن أحمد المالقي النباتي المعروفُ بابن البيطار، الطبيبُ، ولد في مالقةَ بالأندلس، كان عالمًا بالنبات وصفاتِه ومنافِعِه وأماكِنِه، سافر في البلادِ إلى اليونان والمغرب ومصر وبلاد الشام، وكان كلَّ ذلك يدرس علمَ النبات ويجمع العيِّنات، كان ثقةً فيما ينقُلُه حُجَّةً, وإليه انتهت معرفة النباتِ وتحقيقه وصفاته وأسمائه وأماكنه. كان لا يجارَى في ذلك. سافر إلى بلاد ا"},{"id":2586,"era":"c7","t":"الاتصال بين لويس التاسع والمغول .","s":"في أثناء مسير الحملة الصليبية السابعة المتَّجِهة إلى الشرق بقيادة الملك لويس التاسع ملك فرنسا توقَّفَ في قبرص فأجرى اتصالاتِه مع المغول ليساعِدُوه على تطويق المسلمينَ في الشرق الأدنى ولِعَقدِ تحالف عسكري مع المغول ضد الأيوبيِّينَ في الشام وضدَّ الخلافة العباسيَّة في بغداد."},{"id":2587,"era":"c7","t":"وفاة الإمام العلامة جمال الدين بن الحاجب المالكي .","s":"هو الشَّيخُ، الإمام، العلَّامة، المقرئ، الأصولي، الفقيه، النحوي، جمال الأئمَّة والمِلَّة والدين أبو عمرو بن الحاجب عثمانُ بن عُمَر بن أبي بكر بن يونس الدويني الكردي الأصل، الإسنائي المولد، ثمَّ المصري, المالكي. كان مولده في آخر سنة 570 بأسْنا وهي بلدة صغيرة بصعيد مصر، كان والده حاجبًا للأمير عز الدين موسك الصلاحي. اشتغل أبو عمرو بالقاهرة في صغره بالقرآنِ الكريم، ثم بالفقهِ على مذهب الإمام مالك، رض"},{"id":2588,"era":"c7","t":"استعداد التتار لغزو الصين وبلاد المسلمين .","s":"اعتلى \"كيوك\" عرش دولةِ المغولِ, ولم يكنْ مِثلَ أبيه \"أوكتاي\" ملكًا كريمًا، نبيلَ الخُلق، طيبَ المعاملةِ مع المسلمين؛ وإنما كان رجلًا مغامرًا محاربًا، يميلُ إلى الغزو والفتحِ مِثلَ جَدِّه جنكيز خان، وما إن استقَرَّ في الحكم حتى دعا الأمراء إلى ضرورة مراعاة أحكام القانون المغولي (الياسا)، وحذَّرَ من الخروج عليه، ثم قام بتجهيزِ الجيوشِ لمواصلةِ فتحِ الصين الجنوبيَّة، وأوكل هذه المهمَّةَ إلى القائِدِ "},{"id":2589,"era":"c7","t":"فيضان الماء ببغداد .","s":"طغى الماء ببغداد حتى أتلف شيئًا كثيرًا من المحالِّ والدُّور الشهيرة، وتعَذَّرت الجُمَعُ في أكثر الجوامع بسبب ذلك سوى ثلاثِة جوامِعَ، ونُقِلَت توابيت جماعة من الخلفاء إلى الترب من الرصافة خوفًا عليهم من أن تغرق محالُّهم، منهم المقتصد بن الأمير أبي أحمد المتوكل، وذلك بعد دفنه بأكثَرَ من 350 سنة، وكذا نُقِلَ ولَدُه المكتفي وكذا المقتفي بن المقتدر بالله."},{"id":2590,"era":"c7","t":"الحملة الصليبية السابعة تصل إلى دمياط وتحتلها .","s":"قَدِمَ السلطان الملك الصالحُ نجم الدين أيوب من دمشق، وهو مريضٌ، لَمَّا بلغَه من حركةِ الفرنج، فنزل بأشموم طناح في المحرم، وجمع في دمياط من الأقواتِ والأسلحة شيئًا كثيرًا، وبعث إلى الأميرِ حسام الدين بن أبي علي نائبِه بالقاهرة، أن يجهِّزَ الشواني من صناعةِ مصر، فشرع في تجهيزِها، وسَيَّرَها شيئًا بعد شيء، وأمر الملك الصالح نجم الدين أيوب الأمير فخر الدين بن شيخ الشيوخ أن ينزل على جيزةِ دمياط بالعساك"},{"id":2591,"era":"c7","t":"وفاة الملك يحيى مؤسس الدولة الحفصية بتونس وتولي ابنه بعده .","s":"هو الملِكُ صاحِبُ تونس أبو زكريا يحيى بن الأميرِ عبد الواحد بن الشيخ أبي حفص عمَرَ الهنتاني، الموحِّدي كان أبوه متوليًا لمدائن إفريقيَّة لآلِ عبد المؤمن، فمات ووَلِيَ بعده ابنُه الأمير أبو محمد عبد الله الحفصي، فوَلِيَ مُدَّة، ثم وثب عليه أخوه أبو زكريا يحيى بدعم من الموحِّدين، واستولى على إفريقيَّةَ، واستبد أبو زكريا بأمر إفريقية ودعا لنفسه، وامتدت دولته بضعًا وعشرين سنة، واشتغل عنه بنو عبد المؤم"},{"id":2592,"era":"c7","t":"ضم الملك الصالح أيوب  صاحب مصر الكرك لحكمه .","s":"إن الناصر داودَ صاحب الكرك لما ضاقت به الأمورُ استخلف ابنَه الملكَ المعظم شرفَ الدين عيسى، وأخذ معه جواهِرَه، وسار في البر إلى حَلَب مستجيرًا بالملك الناصرِ يوسف بن الملك العزيز فأنزله وأكرَمَه وسيَّرَ النَّاصِرَ بجواهره إلى الخليفةِ المستعصم بالله؛ لتكون عنده وديعة، فقبض الخليفةُ ذلك، وسير إليه الخطَّ بقبضه وأراد الناصرُ بذلك أن يكون الجوهَرُ في مأمن، فإذا احتاج إليه طلَبَه، وكانت قيمتُه ما ينيِّ"},{"id":2593,"era":"c7","t":"وفاة السلطان الملك الصالح نجم الدين أيوب وتولي ابنه توران شاه .","s":"هو السُّلطانُ الملك الصالحُ نجمُ الدين أيوب بن السلطان الملك الكامِل ناصِرِ الدين محمد بن السلطان الملك العادل أبي بكر محمد بن الأمير نجم الدين أيوب بن شاذي. وُلِدَ سنة 603 بالقاهرة، فلمَّا قَدِمَ أبوه دمشقَ في آخر سنة خمس وعشرين استنابه على ديار مصر، فلمَّا رجع انتقَدَ عليه أبوه أحوالًا، ومال عنه إلى ولَدِه الملك العادل الثاني. ولما استولى الكامِلُ على حران، وعلى حِصنِ كيفا وآمد وسنجار سلطَنَه عل"},{"id":2594,"era":"c7","t":"قدوم توران شاه بن الملك الصالح أيوب لحكم مصر بعد وفاة أبيه .","s":"بعد وفاةِ الملك الصالحِ نجمِ الدين أيوب قَدِمَ ابنُه المعظَّم توران شاه, وكان في حصنِ كيفا، فسار من حصنِ كيفا إلى دمشق، لإحدى عشرةَ ليلةً مضت من شهر رمضان، فنزل عانةً في خمسين فارسًا من أصحابه، يوم الخميس النِّصفَ من شهر رمضان وخرج منها يوم الأحدِ يريد دمشق على طريقِ السماوة في البرية فنَزَل القصيرَ في دهليز ضربه له الأميرُ جمال الدين موسى بن يغمور نائب دمشق يوم الجمعة لليلتين بَقِيَتا من شهر رمضا"},{"id":2595,"era":"c7","t":"وفاة الأمير الفخر يوسف بن شيخ الشيوخ .","s":"هو الصاحِبُ الكبير، ملك الأمراءِ، فَخرُ الدين يوسف بن شيخ الشيوخ بن حمويه. مولده: بدمشق، سنة582. كان فاضلًا صدرًا مُعظمًّا عاقِلًا شُجاعًا جَوادًا دَيِّنًا مَهيبًا وقورًا خَليقًا للإمارةِ والملك، كانت الأمراءُ تعَظِّمُه جدًّا، ولو دعاهم إلى مبايعتِه بعد الصالحِ لما اختُلِفَ عليه اثنان، ولكنه كان لا يرى ذلك حمايةً لجانب بني أيوب، غَضِبَ عليه السلطان نجم الدين سنة أربعين وسجنَه ثلاث سنين، وقاسى شدائ"},{"id":2596,"era":"c7","t":"الحملة الصليبية السابعة بقيادة ملك فرنسا وهزيمتهم في المنصورة .","s":"كان لسقوط بيت المقدس في أيدي المسلمين سنة642 هـ (1244م) صدى كبير في أوروبا فأخذت أوروبا تجَهِّزُ لحملة صليبيةٍ جديدةٍ كبيرةٍ هي الحملةُ الصليبية السابعة للاستيلاءِ على مصر, حيثُ إنهم أدركوا بعد هزيمةِ حَملتِهم الصليبية الخامسةِ على مصر، ثم هزيمتهم في معركة الحربيَّة عند غزة، وضياع بيت المقدس منهم، أنَّ مِصرَ هي التي تمثل مركزَ قُوَّة المسلمين وقلعة التصدِّي لطموحاتِهم في الاستيلاءِ على بيتِ المقدس"},{"id":2597,"era":"c7","t":"اغتيال المماليك الملك المعظم توران شاه ونهاية الدولة الأيوبية .","s":"هو السُّلطانُ الملك المعظم، غياث الدين توران شاه بن السلطان الملك الصالح أيوب بنِ الكامل بن العادل. وُلِدَ بمصر، وعَمِل نيابة أبيه، ثم تملك بحِصن كيفا وآمد، وكان أبوه لا يُعجِبُه هَوَجُه ولا طَيشُه، وكان السلطانُ يقول: توران شاه ما يَصلُحُ للمُلك, ولما مات أبوه سار لإحضارِه لمصر الأميرُ فارس أقطاي، فاتفَقَت كسرة الفرنج عند وصولِه مصر، فتيمَّنَ الناس به، فبدا منه حركاتٌ مُنَفِّرة، ووجدوه خفيفَ العَ"},{"id":2598,"era":"c7","t":"تنصيب شجرة الدر ملكة على مصر  .","s":"هي المَلِكةُ عِصمةُ الدين أمُّ خليل شَجَرةُ الدر كانت تركيةَ الجنس، وقيل بل أرمنيَّة، اشتراها الملِكُ الصالح نجم الدين أيوب، وحَظِيَت عنده بحيث كان لا يفارِقُها سفرًا ولا حضرًا، هي أوَّلُ مَن ملك مصر من ملوكِ الترك المماليكِ، وذلك أنَّه لما قُتِلَ الملك المعظم غياث الدين توران شاه بن الملك الصالح نجم الدين أيوب، اجتمع الأمراءُ المماليك البحرية، وأعيانُ الدولة وأهل المشورة، بالدهليز السلطاني، واتفق"},{"id":2599,"era":"c7","t":"المصريون يطلقون سراح ملك فرنسا لويس التاسع مقابل فدية كبيرة .","s":"لما حلف الأمراء والأجناد واستقرت القاعدة على تملُّك شجرة الدر، نَدَب الأميرُ حسام الدين محمد بن أبي علي للكلامِ مع الملك لويس التاسع في تسليمِ دمياط، فجرى بينه وبين الملك مفاوضاتٌ ومحاورات ومراجعات، آلت إلى أن وقع الاتفاقُ على تسليمها من الفرنجِ، وأن يخلى عنه ليذهَبَ إلى بلاده، بعدما يؤدِّي نصفَ ما عليه من المالِ المقَرَّر، فبعث الملك الفرنسي إلى من بها من الفرنجِ يأمُرُهم بتسليمِها، فأبوا وعاوَدَ"},{"id":2600,"era":"c7","t":"استيلاء الملك الناصر صاحب حلب على دمشق .","s":"كتب الأمراءُ القيمريَّة مِن دمشق إلى المَلِك النَّاصِر صلاح الدين يوسُف بن العزيز محمَّد بن الظاهر غازي بن السُّلطان صلاح الدين يوسُف بن أيوب صاحِب حلب، يحذرونَه بامتناعِهم من الحَلِف لشَجرةِ الدُّرِّ، ويحثُّونَه على المسيرِ إليهم حتى يملِكَ دمشق، فخرج من حَلَب في عساكِرِه مُستهَلَّ شَهرَ ربيع الآخر، ووصل إلى دمشقَ يوم السبت ثامِنَه، ونازلها إلى أن كان يومُ الاثنين عاشِرَه زحف عليها، ففتح الأمراءُ"},{"id":2601,"era":"c7","t":"عز الدين أيبك يملك مصر بعد بني أيوب ويتزوج شجرة الدر .","s":"عِزُّ الدين أيبك الجاشنكير التركماني الصالحي تركي الأصلِ والجنس، انتقل إلى مِلكِ السلطان المَلِك الصالحِ نجم ِالدين أيوب من بعض أولاد التركماني، فعُرِفَ بين المماليك البحريَّة بأيبك التركماني، وترقى عنده في الخَدَم، حتى صار أحدَ الأمراء الصالحية، وعَمَلُه جاشنكيرا - متذوّق الطعام السُّلطان- وهو من أخَصِّ موظفي القصر السلطاني إلى أن مات الملك الصالح، وبعد قَتْلِ ابنه توران شاه توَلَّت شجرة الدر الس"},{"id":2602,"era":"c7","t":"مسير الناصر للاستيلاء على مصر بعدما ملك دمشق .","s":"أخذ الملك الناصر صاحِبُ الشام في الحَرَكةِ لأخذ مصر، بتحريضِ الأمير شمس الدين لؤلؤ الأرمني له على ذلك، فخرج الناصرُ من دمشق بعساكِرِه، يوم الأحد النصفَ من شهر رمضان، ومعه الملك الصالح عماد الدين إسماعيل بن العادل أبي بكر بن أيوب ثم برز الأميرُ حسام الدين أبو علي من القاهرة، وكان الوقتُ شِتاءً، وفي تاسع شوال برز الأميرُ فارس الدين أقطاي الجمدار - مقَدَّم البحرية - في جمهورِ العسكر من الترك، وسارت ا"},{"id":2603,"era":"c7","t":"وفاة الملك الصالح إسماعيل بن الملك العادل صاحب دمشق .","s":"هو السُّلطانُ الملك الصالح عماد الدين، أبو الخيش إسماعيل بن الملك العادل محمد بن نجم الدين أيوب بن شاذي صاحب دمشق. تمَلَّك بصرى وبعلَبَّك، وتنقَّلَت به الأحوال، واستولى على دمشقَ أعوامًا، فحارَبَه ابنُ أخيه الملك الصالح نجم الدين أيوب صاحب مصر، وجرت له أمورٌ طويلة، ما بين ارتفاعٍ وانخفاضٍ، وكان بطلًا شُجاعًا، مَهيبًا شديدَ البطشِ، مليحَ الشَّكلِ، كان في خدمةِ أخيه الأشرفِ، فلما مات الأشرفُ، توثَّب"},{"id":2604,"era":"c7","t":"معارضة الأمراء الأيوبيين قيام دولة المماليك .","s":"اقتتل العسكرُ الأيوبي مع عسكرِ مِصرَ وانهزم عسكرُ الأيوبيِّينَ، ودمشق بيدِ الناصر صلاحِ الدين فعاد المَلِكُ الناصرُ إلى دمشق وقَدِمَت عساكر المصريين فحَكَموا بلاد السواحل حيث استولى الأميرُ فارس الدين أقطاي على الساحِلِ ونابلس إلى نهر الشريعة، فجهَّز لهم الملك الناصِرُ جَيشًا طردهم حتى رَدَّهم إلى الدِّيارِ المصرية، وقَصَرَهم إلى حَدِّ نهر الشريعة، وسَيَّرَ الملكُ الناصرُ عَسكرًا من دمشقَ إلى غزة "},{"id":2605,"era":"c7","t":"المغول يقررون غزو بلاد الإسلام ويختارون هولاكو لهذه المهمة .","s":"قام أمراء المغول ورؤساؤهم بالاجتماعِ برئاسةِ الخاقان الأكبر منكو في جمعيةٍ عامَّةٍ تُدعى قوريلتاري فقرروا فيها القيامَ ببَعثةٍ حربية بقيادة هولاكو مهمتها غزو الدولِ الإسلاميَّة مبتدئين قبل ذلك ببلاد الإسماعيليَّة من ألموت وغيرها."},{"id":2606,"era":"c7","t":"تحرك المغول باتجاه الولايات الإسلامية .","s":"وصل التتارُ إلى الجزيرة وسروج ورأس العينِ وما والى هذه البلادَ، فقتلوا وسَبَوا ونهبوا وخَرَّبوا ووَقَعوا بسنجار يسيرونَ بين حران ورأس العين، وكان عِدَّة من قتلوا من أهل الجزيرة نحًوا من عشرة آلاف قتيل، وأسروا من الولدان والنساء ما يقارب ذلك، وسيَّرَ منكوخان ملك التتر أخاه هولاكو لأخذ العراق فسار وأباد أهلَ بلاد الإسماعيلية قتلًا ونهبًا، وأسرًا وسبيًا، ووصَلَت غاراته إلى ديار بكرٍ وميافارقين، وصادف"},{"id":2607,"era":"c7","t":"الحرب بين المماليك وأمراء الدول الأيوبية .","s":"تمكَّن السلطان المملوكي عز الدين أيبك من احتلالِ غَزَّة، ودخلت هذ السَّنةُ وهم على نفسِ الأمر من التنافر والاقتتال، وقد التقى الفريقانِ في العباسيَّة على الطريق إلى القاهرة، ثمَّ إن طائفة من العسكر الشامي انحازوا إلى العسكر المصري، فكانت هزيمةً على العسكرِ الشامي أُسِرَ فيها عددٌ مِن الأمراء الذين حُمِلوا إلى مصر وسُجِنوا في القلعةِ."},{"id":2608,"era":"c7","t":"وفاة اللغوي الإمام، العلامة أبو الفضل الصاغاني .","s":"هو الشيخُ الإمامُ العلَّامة المحَدِّث، إمامُ اللغة رضي الدين أبو الفضائل الحسن بن محمد بن الحسن بن حيدر علي المعروف بالصاغاني، القرشي، العدوي، العمري، الصاغاني الأصل، الهندي اللهوري المولد، البغدادي الوفاة، المكي المدفن، الفقيه الحنفي، صاحب التصانيف. أحد أئمَّة اللغة في القرن السابع الهجري, وكان إليه المنتهى في معرفة اللِّسانِ العربي. وُلِدَ في لاهور بالهند في صفر سنة 577, ونشأ بغزنة من بلاد السند"},{"id":2609,"era":"c7","t":"الملك الناصر الثاني يستنجد بالملك فردريك الثاني لتسليمه القدس .","s":"قام الملك الناصرُ صلاح الدين صاحِبُ دمشق بطَلَب العونِ مِن ملك الفرنجِ فريدريك الثاني وهو في عكَّا على أن يُسَلِّمَه القُدسَ مقابِلَ هذه المساعدة ضِدَّ العسكر المصري، ولكِنَّ فريدريك رفض طلبَه ذاك لوجودِ معاهدة بينه وبين المماليكِ تمنعُ مناصرةَ خُصومِهم في الحرب، وقد قال ابن كثير في تاريخه \"إن الجيشَ المصريَّ قد تمالأ أيضًا مع الفرنج على تسليمِهم القدس إن هم نصروهم على الشاميِّين, فالله أعلمُ بحقي"},{"id":2610,"era":"c7","t":"ثورة الأعراب على حكم المماليك في الصعيد الشرقية .","s":"ثار العُربان ببلاد الصعيدِ وأرضِ بحري، وقطعوا الطريق برًّا وبحرًا، فامتنع التجَّار وغيرُهم من السفر، وقام الشريفُ حِصنُ الدين ثعلب بن الأمير الكبير نجمِ الدين علي بن الأمير الشريف فخر الدين إسماعيل بن حصن الدولة مجد العرب ثعلب بن يعقوب بن مسلم بن جعفر بن موسى، وقال نحن أصحابُ البلاد، ومنع الأجنادَ مِن الخراج، وصَرَّح هو وأصحابُه بأنَّا أحَقُّ بالمُلكِ مِن المماليك، وقد كفى أنَّا خَدَمْنا بني أيوب،"},{"id":2611,"era":"c7","t":"الخليفة العباسي يتوسط في الصلح بين المماليك والأيوبيين .","s":"قام الخليفةُ العباسيُّ المستعصم بالتوسُّط بين الأيوبيين أصحابِ الشَّامِ وبين المماليك أصحابِ مِصرَ لما كان بينهم من الحروب، فأرسل الشيخَ نجم الدين البادرائي للتوسُّط بينهم، الذي حمل رسالةً إلى الطرفين فتقرر الصلحُ بين الملك المعز أيبك وبين الملك الناصر صاحب دمشق، بسفارةِ نجم الدين البادرائي، وقد قَدِم نجمُ الدين إلى القاهرة، وصَحِبَه عز الدين أزدمر، وكاتبُ الإنشاء بحَلَب نظام الدين أبو عبد الله مح"},{"id":2612,"era":"c7","t":"خروج نار من عدن ظنها الناس النار التي تحشر الناس للقيامة .","s":"وردت أخبارٌ في مكَّةَ شَرَّفَها الله تعالى بأنَّ نارًا ظَهَرَت في أرضِ عَدَن في بعض جبالِها بحيث إنَّه يطير شَرَرُها إلى البحر في الليل، ويصعدُ منها دخانٌ عظيم في أثناء النهار، فما شَكُّوا أنها النارُ التي ذكر النبيُّ صلى الله عليه وسلم أنها تظهرُ في آخِرِ الزمان، فتاب الناسُ وأقلعوا عمَّا كانوا عليه من المظالمِ والفسادِ، وشرعوا في أفعالِ الخير والصَّدَقاتِ."},{"id":2613,"era":"c7","t":"الصلح بين الملك الناصر صاحب دمشق وبين الفرنج .","s":"وقع الصُّلحُ بين الملك الناصر صاحِبِ دمشق وبين الفرنجِ أصحابِ عكَّا، لمدة عشر سنين وستة أشهر وأربعين يومًا أولُها مُستهَلَّ المحرم، على أن يكونَ للفرنجِ مِن نهر الشريعة مغربًا، وحلف الفريقانِ على ذلك."},{"id":2614,"era":"c7","t":"التنازع على مكة بين الشَّريف راجح بن قتادة والشريف جماز .","s":"أخذ الشَّريفُ راجح بن قتادة مكَّةَ من الشريف جماز بن حسن، بغيرِ قتال، ثم أخذها ابنُه غانم بن راجح في ربيعٍ الأول بغير قتالٍ، فقام عليه الشَّريفُ أبو نمي بن أبي سعيد بن علي بن قتادة في شوال ومعه الشريفُ إدريس، وحارباه ومَلَكَا مكة، فقدم في خامس عشر ذي القعدة مبارز الدين الحسين بن علي بن برطاس من اليمن، وقاتَلَهما وغَلَبَهما، وحجَّ بالنَّاسِ."},{"id":2615,"era":"c7","t":"اغتيال الأمير فارس الدين أقطاي الجمدار .","s":"هو الأميرُ الكبير فارس الدين التركي، أقطاي بن عبد الله الجمدار- حامل ملابس السلطان- الصالحي، النَّجمي، من كبار مماليك المَلِك الصالح نجم الدين أيوب. كان شجاعًا جَوادًا كريمًا مهابًا، وهابًا. ذكر شمس الدين الجزري في \" تاريخه \": \"أنه كان مملوكًا للزكي إبراهيم الجزري المعروف بالجبيلي، اشتراه بدمشق ورباه، ثم باعه بألف دينار، فلما صار أميرًا وأقطعوه الإسكندرية طَلَبَ من الملك الناصر إطلاقَ أستاذه المذك"},{"id":2616,"era":"c7","t":"وفاة بدرة بنت الإمام فخر الدين محمد بن تيمية جدة شيخ الإسلام .","s":"هي بدرةُ بنتُ الإمامِ فخرِ الدين محمد بن أبي القاسم بن تيميَّة، أم البدر، زوجةُ العلَّامة المفتي مجدِ الدين أبي البركات عبد السلام بن عبد الله ابن أبي القاسم ابن تيميَّة، جَدَّةُ شيخ الإسلامِ أبي العباس بن تيميَّة. توفيت قبل زوجها بليلة، وقد روت بالإجازةِ عن بعضِ أصحاب أبي علي الحدَّاد. سمع منها: الدمياطي بإجازتها من أبي المكارم اللبَّان"},{"id":2617,"era":"c7","t":"وفاة مجد الدين بن تيمية جد شيخ الإسلام بن تيمية .","s":"هو الشَّيخُ الإمامُ العلَّامة، فقيهُ العصر، شيخُ الحنابلة، مجدُ الدين أبو البركات عبد السلام بن عبد الله بن أبي القاسم الخضر بن محمد بن علي بن تيمية الحراني الحنبلي، جد الشيخ تقي الدين بن تيميَّة المشهور بشيخِ الإسلام، ولِدَ في حدود سنة 590 وتفَقَّه في صغره على عَمِّه الخطيب فخر الدين، ففقه وبرع، واشتغل وصنف التصانيف، وانتهت إليه الإمامةُ في الفقه، وكان يجيدُ القراءاتِ، وصنَّف فيها أرجوزةً, وقد حَ"},{"id":2618,"era":"c7","t":"تآمر المماليك العزيزية على الملك المعز .","s":"كانت المماليكُ العزيزيَّةُ قد عزمت بالقبضِ على الملك المعزِّ عِزِّ الدين أيبك وكاتبوا المَلِكَ الناصر واستشعر المَلِكُ المعز منهم بذلك وعَلِمَ الخبر، وعَلِموا هم أيضًا فهربوا على حمية، وكبيرُهم آقوش البرنلي، وقبض أيضًا على الأمير الأتابكي ونهِبَت خيامُ العزيزية وكانوا بالعباسيَّة."},{"id":2619,"era":"c7","t":"خروج الأمير عز الدين على الملك المعز أيبك صاحب مصر .","s":"سار الأميرُ عز الدين أيبك الأفرم الصالحي إلى بلاد الصعيدِ، وأظهر الخروجَ عن طاعة الملِك المعزِّ عِزِّ الدين أيبك، وجمع العُربان، فسيَّرَ إليه الملك المعز الوزيرَ الصاحِبَ الأسعد شرف الدين الفائزي، ومعه طائفةٌ من العسكر، حتى سكَّنَ الأمور."},{"id":2620,"era":"c7","t":"انضمام الأمراء الهاربين من مصر إلى الناصر بدمشق لمواجهة المعز آيبك .","s":"أخرج الملِكُ الناصِرُ عسكرًا إلى جهةِ ديار مصر، ومعهم البحريَّة الذين كانوا قد هَرَبوا من مصرَ مِن المعز بعد أن قُتِلَ صاحِبُهم فارسُ الدين أقطاي الجمداري، وهم الأميرُ سيف الدين بلبان الرشيد، وعز الدين أزدمر، وشمس الدين سنقر الرومي، وشمس الدين سنقر الأشقر، وبدر الدين بيسري، وسيف الدين قلاوون، وسيف الدين بلبان المسعودي، وركن الدين بيبرس البندقداري، وعدة من مماليك الفارس أقطاي."},{"id":2621,"era":"c7","t":"قيام حروب داخلية بين الصليبيين .","s":"جرت بين الصليبيِّينَ حُروبٌ داخلية أضعَفَت قواهم بحَمدِ الله، فقامت حروبٌ بين البندقية وجنوة امتدت إلى عام 660 انضَمَّت فيها جميعُ الأحزاب المتنافرة إلى أحَدِ الجانبين وأنهكَتْهم ممَّا كان له الأثَرُ في استعادة الظاهر بيبرس في حينها أنطاكية منهم."},{"id":2622,"era":"c7","t":"هولاكو يجتاح بلاد فارس ويقتل جماعة الحشاشين الإسماعيلية .","s":"بعد الاتِّفاقِ المغولي على الزَّحفِ إلى بلاد الإسماعيلية وغيرها, حدث في هذه السَّنة أن استولى هولاكو على حصنينِ مِن حُصونِ الإسماعيليَّة بولاية قهستان وأمَرَ بإعدام كلِّ مَن يزيد عمره على عشرِ سنوات، ثم استولى على قلعتي ألموت وميمون دز وقبضَ على زعيمِ الإسماعيليَّة ركن الدين خورشاه وأرسَلَه إلى قره كروم عاصمة المغول، فأمر منكو زعيمُهم بقتله وقتْل أتباعِه الذين كانوا معه."},{"id":2623,"era":"c7","t":"فيضانات أغرقت بغداد .","s":"أصاب بغدادَ غَرَقٌ عظيمٌ حتى طفح الماء من أعلى أسوارِ بغداد إليها، وغرق كثيرٌ منها، ودخل الماءُ دار الخلافة وسَطَ البلد، وانهدمت دارُ الوزير وثلاثمائة وثمانون دارًا، وانهدم مخزنُ الخليفة، وهلك مِن خزانة السلاحِ شيء كثير، وأشرف الناسُ على الهلاك وعادت السفُنُ تدخل إلى وسط البلدة، وتخترق أزقَّة بغدادَ."},{"id":2624,"era":"c7","t":"احتراق المسجد النبوي الشريف .","s":"في ليلةِ الجُمُعةِ مُستهَلَّ رَمَضانَ احترق المسجدُ النبوي بالمدينةِ- على ساكِنِه أفضَلُ الصلاة والسلام، ابتدأ حريقُه من زاويتِه الغربيَّة من الشمال، وكان دخل أحدُ القومةِ إلى خزانةٍ ومعه نار فعَلِقَت في الأبوابِ ثم اتصلت بالسَّقفِ بسُرعةٍ، ثم دبَّت في السقوف، وأخذت قبلةً فأعجلت النَّاسَ عن قطعها، فما كان إلا ساعةٌ حتى احترقت سقوفُ المسجِدِ أجمع، ووقعت بعض أساطينِه وذاب رصاصُها، وكلُّ ذلك قبل أن ي"},{"id":2625,"era":"c7","t":"فتنة بين السنة والشيعة في بغداد .","s":"وقوع فتنة عظيمة ببغداد بين الرافضة وأهل السنة، قال ابن كثير: \"فنُهِبَ الكرخ ودُورُ الرافضة حتى دورُ قرابات الوزير ابنِ العلقمي، وأنَّ ذلك من أقوى الأسبابِ في ممالأتِه للتتار\"."},{"id":2626,"era":"c7","t":"إسلام ملك بلاد القبجاق بركة خان المغولي .","s":"اعتنق الإسلامَ بَرَكةُ خان بن جوجي بن جنكيز خان المغولي متمَلك بلاد القبجاق, وزعيمُ القبيلة الذهبيَّة المغولية, وهو ابنُ عم هولاكو، وكذلك أسلَمَت زوجتُه ججك. أسلم بركةُ خان على يد الشَّيخِ أبو المعالي سعيد بن المطهر الباخرزي, وكان عنده ستون زوجة، فأمره باتخاذِ أربعٍ فقط وفراق الباقيات، ففعل، ورجع إلى بلاده، وأظهر شعائر الملة الإسلامية، وأسلم معه جماعةٌ من أمرائه وأهل بيته، وأخذوا في تعلُّمِ الفرائ"},{"id":2627,"era":"c7","t":"بداية قصد المغول بغداد .","s":"جرت فتنةٌ مهولة ببغدادَ بين الناس وبين الرَّافضة، وقُتِلَ عدة من الفريقين، وعَظُم البلاء، ونهب الكرخ، فحنق ابن العلقمي الوزير الرافضي، وكاتَبَ هولاكو، وطَمَّعَه في العراق، فجاءت رسُلُ هولاكو إلى بغدادَ، وفي الباطِنِ معهم فرماناتٌ لغير واحد، وَصَلت جواسيس هولاكو إلى وزير الخليفة العباسي المستعصم بالله مؤيد الدين محمد بن العلقمي الرافضي ببغداد، وتحَدَّثوا معه ووعدوا جماعةً مِن أمراء بغداد مواعيدَ، و"},{"id":2628,"era":"c7","t":"وفاة الملك المعز عز الدين أيبك صاحب مصر وأول سلطان مملوكي .","s":"هو السُّلطانُ الملك المعز عِزُّ الدنيا والدين، أيبك التركماني، الصالحي الجاشنكير- جاشنكير متذوِّق طعام السلطان-  صاحب مصر. لما قتل المماليكُ المعظَّم توران شاه، خَطَبوا لشجرةِ الدر أمِّ خليل أيامًا، وكانت تعلِّمُ على المناشير، وتأمُرُ وتنهى، ويُخطَبُ لها بالسلطنة. ولما وصل الخبَرُ بذلك إلى بغداد فبعث الخليفة المستعصم بالله من بغداد كتابا إلى مصر وهو ينكِرُ على الأمراء ويقولُ لهم: \"إن كانت الرجالُ "},{"id":2629,"era":"c7","t":"مقتل شجرة الدر بسبب قتلها زوجها الملك المعز عز الدين أيبك .","s":"هي شجرةُ الدر الصالحيَّة بنت عبد الله أم خليل التركيَّة، ذاتُ حُسنٍ وظرف ودهاء وعقل، ونالت من العِزِّ والجاه ما لم تنَلْه امرأة في عصرها، كانت جاريةً اشتراها الملك الصالح نجم الدين أيوب، وحَظِيَت عنده بمكانةٍ كبيرة، وكانت أمَّ ولدٍ عنده؛ فقد ولدت منه خليلًا، من أحسن الصور، فمات صغيرًا، وكانت تكونُ في خدمة الملك الصالحِ لا تفارقه حضرًا ولا سفرًا من شدة محبته لها, فأعتَقَها وتزوَّجَها. وكانت تقومُ ب"},{"id":2630,"era":"c7","t":"القتال بين المماليك البحرية الذين هربوا من مصر وبين عسكر مصر .","s":"وقَعَت الوحشةُ بين الملك الناصر وبين من عنده من المماليك البحريَّة، ففارقوه في شوال، وقصدوا الملك المغيثَ صاحب الكرك، فأخرج الأميرُ سيف الدين قطز العسكَرَ الصالحية، فواقعوهم في يوم السبت خامِسَ عشر ذي القعدة، وأسَرُوا الأمير سيف الدين قلاوون، والأميرَ سيف الدين بلبان الرشيدي، وقتل الأمير سيف الدين بلغان الأشرفي، وانهزم عَسكَرُ الكرك وفيهم بيبرس البندقداري، وعاد العسكرُ إلى القاهرة، فضمن الأميرُ شر"},{"id":2631,"era":"c7","t":"استيلاء المغول على بلاد الجزيرة وغيرها .","s":"نزل هولاكو بجيشِه المغولي بعدَ مذبحةِ بغداد حرَّان واستولى عليها ومَلَك بلادَ الجزيرة، ثم سيَّرَ ولده أشموط إلى الشامِ وأمره بقطعِ الفرات وأخْذ البلاد الشامية، وسيَّرَه في جمعٍ كثيف من التتار فوصَلَ أشموط إلى نهرِ الجوز وتل باشر، ووصل الخبَرَ إلى حلب من البيرة بذلك، وكان نائبُ السلطان صلاح الدين يوسف بحلب ابنه الملك المعظم توران شاه، فجفَل النَّاسُ بين يدي التتارِ إلى جهة دمشق وعظم الخطب، واجتمع ا"},{"id":2632,"era":"c7","t":"وفاة أبي الحسن الشاذلي مؤسس الطريقة الصوفية الشاذلية .","s":"هو شَيخُ الطائفة الشاذليَّة الزاهد أبو الحَسَن علي بن عبد الله بن عبد الجبَّار بن تميم المغربي الشاذلي المالكي، نزيلُ الإسكندرية، مؤسِّس الطريقة الصوفيَّة المشهورة بالشاذليَّة، ولد في غمارة قرب سبتة بالمغرب، وفيها نشأ وتعلم، رافق أبا القاسم الجُنَيد البغداديَّ الصوفيَّ، فأخذ عنه التصوفَ، ثم اتخذ في تونس رباطًا له في جبل وبدأ ينشُرُ أفكاره في بلدة شاذلة القريبةِ مِن رباطه فكَثُرَ أتباعه، ثم نُفِيَ "},{"id":2633,"era":"c7","t":"سقوط بغداد على يد هولاكو قائد المغول .","s":"كان الوزيرُ ابن العلقمي يجتَهِدُ في صرف الجيوش وإسقاطِ اسمِهم من الديوان، فكانت العساكِرُ في آخر أيام المستنصر قريبًا من مائة ألف مقاتل، منهم من الأمراء ومن هو كالملوك الأكابر الأكاسر، فلم يزل يجتهد في تقليلِهم إلى أن لم يبقَ سوى عشرة آلاف، ثم كاتب التتارَ وأطمعهم في أخذِ البلاد، وسَهَّل عليهم ذلك، وحكى لهم حقيقةَ الحال، وكشَفَ لهم ضعف الرجال، وذلك كلُّه طمعًا منه أن يزيل السُّنَّة بالكُلِّيَّة، و"},{"id":2634,"era":"c7","t":"وفاة القاضي محيي الدين يوسف بن الجوزي واقف المدرسة الجوزية .","s":"هو أستاذ دار الخلافة الصاحِبُ القاضي محيي الدين يوسف ابن الشيخ جمال الدين أبي الفرج بن الجوزي عبد الرحمن بن علي بن محمد بن علي بن عبد الله بن حماد بن أحمد بن يعقوب بن جعفر بن عبد الله بن القاسم بن النصر بن محمد بن أبي بكر الصديق، المعروفُ بابنِ الجوزيِّ القرشيِّ التيمي البكري البغدادي الحنبلي، ولد في ذي القعدة سنة 580 ونشأ شابًّا حسنًا وحين توفِّيَ والِدُه وعَظَ في موضعه فأجاد وأحسن وأفاد، ثم تقَد"},{"id":2635,"era":"c7","t":"مقتل المستعصم بالله آخر الخلفاء العباسيين على يد التتار .","s":"هو الخليفةُ الشهيد أمير المؤمنين المستعصِم بالله أبو أحمد عبد الله بن المستنصر بالله منصور بن الظاهر محمد بن الناصر أحمد بن المستضيء الهاشمي، العباسي، البغدادي. ولد: سنة 609, واستُخلِفَ سنة أربعينَ يومَ مَوتِ أبيه في عاشر جمادى الآخرة، وكان فاضلًا تاليًا لكتاب الله، كان مليحَ الخَطِّ، قرأ القرآن على الشيخ علي بن النيار الشافعي، ويوم خَتَمَه خلع على الشَّيخِ، وأعطي ستة آلاف دينار. ويوم خلافته بلغت "},{"id":2636,"era":"c7","t":"وفاة الوزير الرافضي ابن العلقمي الذي كان سبباً في سقوط بغداد .","s":"هو الوزيرُ, المُدْبر، المُبير, وزيرُ العراق، أبو طالب مؤيد الدين محمد بن أحمد بن علي بن أبي طالب بن محمد العلقمي البغدادي،  وزير المستعصم بالله. كان عنده فضيلةٌ في الإنشاء والأدب، لكنه كان رافضيًّا شيعيًّا جَلْدًا خَبيثًا داهيةً- لَعَنه اللهُ- استوزره الخليفةُ المستعصِمُ بالله سنة 642 وكان مشؤومًا على نفسِه، وعلى أهل بغداد، ورديء الطويَّة على الإسلام وأهله،  ولم يُعصَم المستعصم في وزارته، فإنه لم "},{"id":2637,"era":"c7","t":"وفاة الحافظ المنذري .","s":"هو الإمام العلامة الحافظ المحقِّق شيخ الإسلام: أبو محمد زكي الدين عبد العظيم بن عبد القوي بن عبد الله بن سلامة بن سعد بن سعيد المنذري، الشامي الأصل، المصري، الشافعي. أصلُه من الشام وولد بمصر، وكان شيخَ الحديث بها مدةً طويلة، إليه الوِفادةُ والرحلة من سنين متطاولة، وقيل: إنه وُلِدَ بالشام في غرة شعبان، سنة 581. كان متينَ الديانة، ذا نسُك وورع وسَمت وجلالة, وسمِعَ الكثير ورحل وطلَب وعُني بهذا الشأن،"},{"id":2638,"era":"c7","t":"المغول ينذرون صاحب دمشق ويطلبون منه تسليمها .","s":"أرسل الملك الغاشم هولاكو خان إلى المَلِك الناصر صاحِبِ دمشق يستدعيه إليه، فأرسل إليه ولَدَه العزيز وهو صغيرٌ ومعه هدايا كثيرةٌ وتُحَف، فلم يحتَفِلْ به هولاكو خان بل غضب على أبيه إذ لم يُقبِلْ إليه، وأخذ ابنُه، وقال: أنا أسير إلى بلاده بنفسي، فانزعج الناصِرُ لذلك، وبعث بحريمِه وأهله إلى الكرك ليحَصِّنَهم بها وخاف أهلُ دمشق خوفًا شديدًا، ولا سيما لما بلغهم أن التتار قد قطعوا الفرات، فسافر كثيرٌ منهم"},{"id":2639,"era":"c7","t":"هولاكو يهدد السلطان المظفر سيف الدين قطز .","s":"بعد أن سقطت بغدادُ بيد هولاكو زحف إلى الشَّامِ واستولى عليها وأنذر سيفَ الدين قطز حاكِمَ مِصرَ يريد بذلك إخافتَه، وذلك أنه يريد أن يُكمِلَ زَحفَه على مصر وإنهاءَ حكم المماليك بعد أن أنهى الدَّولةَ العباسيَّة، ولكن المظفَّرَ قطز كان يجهِّزُ جيشًا لملاقاتِه، ثم قدَّر الله أن يعودَ هولاكو بسبب عصيانِ الأمراءِ في بلادِه عليه فذهب وترك بعضَ عساكره في الشامِ والذين قاتَلَهم المظفر سيف الدين قطز في عينِ "},{"id":2640,"era":"c7","t":"سيف الدين قطز يقبض على الملك المنصور صاحب مصر .","s":"بعد أن جاءت الأخبارُ بتحَرُّك المغول إلى الشام وبَعْثهم الرسائِلَ التهديديَّة للأمراء عقَدَ الأمير سيف الدين قطز في مصر اجتماعًا حضره الفُقَهاءُ وعلى رأسِهم العِزُّ بن عبد السلام بأخذ أموالٍ مِن العامَّة لتجهيز الجيوشِ, ثم قبض قطز على الملك نور الدين عليِّ بن المعز أيبك الملقَّب بالمنصور صاحب مصر، وذلك في غيبةِ أكثر الأمراءِ مِن مماليك أبيه وغيرِهم في الصيد، فلمَّا قبض على المنصور بَعَث به وبأخيه "},{"id":2641,"era":"c7","t":"اتفاق أحوال عجيبة في ولاية الأمر بالشام  .","s":"اتَّفَق في هذا العام أمورٌ عجيبة، وهي أن أوَّلَ هذه السنة كانت الشامُ للسلطان الناصر بن العزيز، ثمَّ في النصف من صفر صارت لهولاكو مَلِك التتار، ثمَّ في آخر رمضان صارت للمظَفَّر قطز، ثمَّ في أواخر ذي القَعدة صارت للظاهِرِ بيبرس، وقد شاركه في دمشقَ الملك المجاهد سنجر، وكذلك كان القضاءُ في أولها بالشام لابن سنى الدولة صدر الدين، ثم صار للكمال عمر التفليسي من جهة هولاكو، ثم لابن الزكي ثم لنجم الدين بن"},{"id":2642,"era":"c7","t":"محاولة انقلاب فاشلة على المظفر سيف الدين قطز سلطان مصر .","s":"ثار جماعةٌ مِن السودان والركبدارية والغِلمان على حاكِمِ مِصرَ السُّلطان سيفُ الدين قطز، وفتحوا دكاكينَ السيوفيِّين بين القصرين وأخذوا ما فيها من السِّلاحِ، واقتحموا اصطبلات الأجناد وأخذوا منها الخيولَ، وكان الحامِلُ لهم على هذا رجلٌ يعرف بالكوراني، أظهَرَ الزُّهدَ بيَدِه سبحةٌ وسكن قبة بالجبل، وتردَّد إليه الغلمان فحَدَّثَهم في القيام على أهل الدولة، وأقطعهم الإقطاعاتِ وكتب لهم بها رقاعًا، فلما ثا"},{"id":2643,"era":"c7","t":"سقوط حلب بيد المغول واستباحتها .","s":"كان التتارُ قد نزلوا على حَلَب في ذي القعدة سنة 556 ولم يدخُلوها, ثم عادوا إليها في ثاني صفر مِن هذه السَّنة, وحاصروها حتى استولَوا عليها في تاسِع صَفَر بالأمان، فلمَّا مَلَكوها غَدَروا بأهل حلب وقتَلوا ونَهَبوا وسَبَوا وفعلوا تلك الأفعالَ القبيحة على عادةِ فِعلِهم."},{"id":2644,"era":"c7","t":"كيف استهلت أول سنة للمسلمين بعد سقوط الخلافة العباسية .","s":"استهلَّت هذه السَّنةُ بيوم الخميسِ، وليس للناس خليفةٌ، ومُلك العراقين وخراسان وغيرها من بلاد المشرق للطاغية هولاكو خان ملك التَّتار، وسُلطان ديار مصرَ للمظفَّر سيف الدين قطز، مملوكِ المعزِّ أيبك التركماني، وسلطانُ دمشقَ وحَلَب للملك الناصر بن العزيز بن الظاهر، وبلادُ الكرك والشوبك للمَلِك المغيث بن العادل بن الكامل محمد بن العادل أبي بكر بن أيوب، وهو حربٌ مع الناصِرِ صاحِبِ دمشق على المصريِّين، وم"},{"id":2645,"era":"c7","t":"سقوط دمشق في أيدي المغول وتمكين النصارى فيها .","s":"أرسل هولاكو وهو نازلٌ على حلب جيشًا مع أميرٍ مِن كبار دولته يقال له كتبغانوين، فوردوا دمشقَ في آخر صفر فأخذوها سريعًا من غير ممانعة ولا مدافع، بل تلقَّاهم كبارها بالرَّحبِ والسعة، وقد كتب هولاكو أمانًا لأهل البلد، فقُرئ بالميدانِ الأخضر ونودي به في البلد، فأمِنَ الناس على وجَلٍ مِن الغدر، كما فعل بأهلِ حلب، هذا والقلعةُ ممتنعةٌ مستورة، وفي أعاليها المجانيقُ منصوبة والحالُ شديدة، فأحضر التتارُ منجن"},{"id":2646,"era":"c7","t":"المماليك يهزمون المغول في موقعة عين جالوت بقيادة المظفر قطز .","s":"لمَّا بلغ الملك المظفَّر سيف الدين قُطز صاحِبَ مِصرَ أنَّ التتارَ قد فعلوا بالشَّامِ ما فعلوه، وقد نهَبوا البلاد كلَّها حتى وصلوا إلى غزَّة، وقد عزم كتبغانوين نائب هولاكو في الشام على الدخولِ إلى مصر، وكان إذ ذاك في البقاع فاستشار الأشرفَ صاحِبَ حمص والمجير بن الزكي، فأشاروا عليه بأنَّه لا قِبَل له بالمظفَّر حتى يستَمِدَّ هولاكو فأبى إلا أن يناجزه سريعًا، فبادرهم  المظفَّر قطز قبل أن يبادِروه ويبر"},{"id":2647,"era":"c7","t":"هلاك قائد المغولي كتبغانوين نائب هولاكو بالشام .","s":"هو كتبغانوين نائب هولاكو على بلاد الشَّامِ- لعنه الله، ومعنى نوين يعني أمير عشرة آلاف، وكان هذا الخبيث قد فتح لأستاذه هولاكو من أقصى بلاد العَجَمِ إلى الشام، وقد أدرك جنكيزخان جد هولاكو، وكان كتبغا هذا يعتمد في حروبه للمسلمين أشياءَ لم يسبِقْه أحد إليها، فكان إذا فتح بلدًا ساق مقاتِلةَ هذا البلد إلى البلد الآخر الذي يليه، ويطلب من أهل ذلك البلد أن يُؤوا هؤلاء إليهم، فإن فعلوا حصل مقصودُه في تضييقِ"},{"id":2648,"era":"c7","t":"اغتيال سيف الدين قطز سلطان دولة المماليك بمصر والشام .","s":"هو السُّلطانُ الشهيدُ الملك المظفر، سيفُ الدين قطز محمود بن عبد الله التركي المعزي. كان أنبَلَ وأخَصَّ مماليك الملك المعز عز الدين أيبك التركماني، ثم صار نائِبَ السلطنة لوَلَدِه المنصور, ثالثِ سلاطين دولة المماليك في مصرَ والشام. كان شابًّا أشقرَ وافِرَ اللحية, فارسًا شجاعًا بطلًا، سائِسًا، دَيِّنًا، حازمًا، حسَنَ التدبيرِ، محَبَّبًا إلى الرعيَّة. كثير الخير ناصحًا للإسلام وأهله، وكان الناسُ يحبُّ"},{"id":2649,"era":"c7","t":"الركن بيبَرس البندقداري  يحكم مصر  .","s":"بعد اغتيالِ سيف الدين قطز حار الأمراءُ فيما بينهم فيمن يوَلُّون المُلك، وصار كل واحد منهم يخشى غائلة ذلك، وأن يصيبه ما أصاب غيرَه سريعًا، فاتفقت كلمتُهم على أن بايعوا بيبرس البندقداري، ولم يكن هو مِن أكابِرِ المقَدَّمين، ولكن أرادوا أن يجرِّبوا فيه، ولقَّبَوه الملك الظاهِرَ، فجلس على سريرِ المملكة وحكمه، ودقت البشائِرُ وضُرِبَت الطبول والبوقات, وزعقت الشاووشية بين يديه، وكان يومًا مشهودًا ثم دخل م"},{"id":2650,"era":"c7","t":"المغول يغيرون على حلب بعد هزيمتهم شمالي حمص .","s":"أغار التتارُ على حلَب فلَقِيَهم صاحِبُها حسامُ الدين العزيزي، والمنصورُ صاحِبُ حماة، والأشرَفُ صاحِبُ حمص، وكانت الوَقعةُ شماليَّ حِمصَ قَريبًا من قَبرِ خالد بن الوليدِ، والتتار في ستة آلاف، والمسلمون في ألف وأربعمائة، فهزمهم الله عز وجل، وقتل المسلمونَ أكثَرَهم، فرجع التتار إلى حلب فحصروها أربعةَ أشهُر وضيَّقوا عليها الأقوات، وقَتَلوا من الغرباء خلقًا صبرًا، والجيوش الذين كسروهم على حمص مُقيمونَ "},{"id":2651,"era":"c7","t":"كثرة الملوك والأمراء في البلدان الإسلامية بعد سقوط الخلافة العباسية .","s":"استهَلَّت بيوم الاثنين لأيامٍ خَلَونَ مِن ديسمبر، وليس للمسلمينَ خليفة، وصاحب مكة أبو نمي بن أبي سعيد بن علي بن قتادة الحسني، وعمه إدريس بن علي شريكُه، وصاحِبُ المدينة الأميرُ عِزُّ الدين جماز بن شيحة الحسيني، وصاحِبُ مصر والشام السلطان الملك الظاهر بيبرس البندقداري، وشريكُه في دمشق وبعلبك والصبيبة وبانياس الأميرُ علم الدين سنجر الملقب بالملك المجاهد، وشريكُه في حلب الأمير حسام الدين لاشين الجوكند"},{"id":2652,"era":"c7","t":"البيعة بالخلافة للمستنصر بالله في مصر  وتجهيزه لاستعادة بغداد .","s":"كان المستنصِرُ بالله أبو القاسِمِ أحمَدُ بن أمير المؤمنين الظاهِر مُعتقَلًا ببغداد فأُطلِقَ، وكان مع جماعةِ الأعراب بأرض العراق، ثم قصَدَ الظاهر بيبرس حين بلغه تسلطُنَه بمصر، فقدم إليه بصحبته جماعةٌ مِن أمراء الأعراب عشرةٌ منهم الأمير ناصر الدين مهنا في ثامن رجب من هذه السنة، فخرج السلطانُ الظاهر ومعه الوزير والشهود والمؤذنون فتلَقَّوه وكان يومًا مشهودًا، وخرج أهلُ التوراة بتوراتهم، والنصارى بإنجي"},{"id":2653,"era":"c7","t":"بداية الخلاف بين هولاكو وابن عمه بركة خان .","s":"كان سَبَبُ عداوة بركة خان وهولاكو أنَّ وقعةً كانت بينهما، قُتِلَ فيها ولد هولاكو وكُسِرَ عَسكَرُه وتمزَّقوا في البلاد، وصار هولاكو إلى قلعةٍ بوسط بحيرة أذربيجان محصورًا بها، وأرسَلَ إليه بركةُ يطلُبُ منه نصيبًا مما فتحه من البلاد وأخَذَه من الأموال والأسرار، على ما جرت به عادةُ ملوكهم، فقتَلَ رُسُلَه فاشتَدَّ غَضَبُ بركة، ومما زاد الخلافَ بينهما هو إسلامُ بركة خان وغَضَبُه على هولاكو مما فَعَله بب"},{"id":2654,"era":"c7","t":"قتل المغول الخليفة العباسي الجديد المستنصر بالله في بغداد .","s":"هو أميرُ المؤمنينَ الخليفةُ المستنصِرُ بالله أبو القاسِمِ أحمد بن الظاهر بأمر الله محمد بن الناصر لدين الله أحمد بن المستضيء بالله الهاشمي العباسي، البغدادي، الأسود. ولي الخلافةَ بعد قتل ابن أخيه المستعصِم بالله بن المستنصر بالله منصور بثلاثِ سنينَ، في وقتٍ خلا فيه من خليفة للمسلمين. وكان شديدَ السُّمرة، جَسيمًا، عاليَ الهمة، شجاعًا، قال الإمام أبو شامة: في رجب قُرئ بالعادلية كتابُ السلطان الظاهِر"},{"id":2655,"era":"c7","t":"وفاة الأمير الوزير كمال الدين بن العديم .","s":"هو الأميرُ الوزير والرئيس الكبير، كمال الدين أبو القاسم عمر بن أحمد بن هبة الله بن محمد بن هبة الله بن أحمد بن يحيى بن زهير بن هارون بن موسى بن عيسى بن العديم العقيلي الحنفي الحلبي، ولد سنة 586، سمع الحديث وحَدَّث وتفَقَّه وأفتى ودرَّس وصنف، وكان إمامًا في فنونٍ كثيرة، وقد ترسل إلى الخلفاء والملوك مرارًا عديدة، وكان يكتُبُ حَسنًا طريقة مشهورة، وصنف لحلب تاريخًا مفيدًا قريبًا في أربعين مجلدًا، وكان"},{"id":2656,"era":"c7","t":"وفاة العلامة سلطان العلماء العز بن عبد السلام   .","s":"هو العلَّامة أبو محمد عبد العزيز بن عبد السلام بن القاسم بن الحسن بن محمد المهذب، المشهورُ بالعز بن عبد السلام السلمي الدمشقي الشافعي شيخ المذهب ومُفيدُ أهله، وله مصنَّفاتٌ حِسانٌ، منها التفسير الكبير، واختصار النهاية، والقواعد الكبرى والصغرى قواعد الأحكام في مصالح الأنام، وكتاب الصلاة، والفتاوى الموصلية، وغير ذلك، ولد سنة 578 وقيل سنة سبع، وسَمِعَ كثيرًا، واشتغل على فخر الدين بن عساكر وغيره، وبرع"},{"id":2657,"era":"c7","t":"نهاية دولة الأتابكة بالموصل على يد قوات هولاكو .","s":"كان الصالحُ إسماعيل بن لؤلؤ صاحبُ الموصل من الذين ساروا مع المستنصِر الخليفة الجديد إلى بغداد، فلما حصلَ من الحرب ما حصَلَ هَرَب ورجع إلى بلادِه، فأرسل هولاكو طائفةً مِن جنده نحو عشرة آلاف وقائدهم صندغون وراءه فحاصروا الموصِلَ ونَصَبوا عليها خمسةً وعشرين منجنيقًا، وضاقت بها الأقواتُ، فأرسل الملك الصالحُ إسماعيل بن لؤلؤ إلى التركي يستنجِدُه فقَدِمَ عليه فهُزِمَت التتار ثم ثَبَتوا والتَقَوا معه، وإن"},{"id":2658,"era":"c7","t":"عساكر الظاهر بيبرس تهاجم الصليبيين في أنطاكية لإخراجهم منها .","s":"جهَّز الملكُ الظاهر عسكرًا إلى حَلَب، وكان مُقَدَّمُهم شمس الدين سنقر الرومي، فأَمِنَت بلاد حلب وعادت إلى الصَّلاح، ثم تقَدَّم الملك الظاهر بيبرس إلى سنقر الرومي إلى صاحِبِ حماة الملك المنصور، وإلى صاحِبِ حمص الملك الأشرف موسى أن يسيروا إلى أنطاكيةَ، للإغارة عليها، فساروا إليها ونَهَبوها وضايقُوا الفرنجَ فيها، ثم عادُوا، فتوجَّهَت العساكرُ المصريَّة بصُحبة سنقر الرومي إلى مصر، ووصلوا إليها في تاسع"},{"id":2659,"era":"c7","t":"وفاة الأمير سيف الدين بلبان الزردكاش .","s":"هو الأمير الكبيرُ سَيفُ الدين بلبان المعروف بالزردكاش. من أمراء دمشقَ الأعيان، وكان دَينًا مشكورًا، وقد استنابه بيبرس موضِعَه بدار العدل على دمشق لما سافر إلى حصار أنطاكية، وكان دَيِّنًا خيِّرًا يحب العدل والصلاح. مات في الثامن من ذي الحجة من هذه السنة."},{"id":2660,"era":"c7","t":"الحرب بين هولاكو وابن عمه بركة خان ملك القبيلة الذهبية المغولية .","s":"قَدِمَت رسلُ بركة خان إلى السلطانِ الظاهرِ بيبرس يقول له: قد عَلِمتَ محبَّتي للإسلام، وعَلِمتَ ما فعَلَ هولاكو بالمسلمين، فاركَبْ أنت من ناحيةٍ حتى آتيَه أنا من ناحيةٍ حتى نصطَلِمَه أو نخرِجَه من البلاد.  فالتقى بركة خان وهولاكو ومع كلِّ واحدٍ جيوشٌ كثيرة فاقتتلوا فهزم اللهُ هولاكو هزيمةً فظيعةً وقُتِلَ أكثر أصحابه وغَرِقَ أكثر من بقي، وهرب هو في شرذمةٍ يسيرةٍ، ولله الحمد، ولما نظَرَ بَركة خان كثر"},{"id":2661,"era":"c7","t":"تحالف الظاهر بيبرس مع بركة خان المغولي .","s":"أرسل بركة خان المغولي رسلًا إلى السُّلطان الظاهر بيبرس يطلُبُ منه أن يتحالَفَ معه ضِدَّ هولاكو، وخاصَّةً أنه قد أسلَمَ ووقَعَ بينه وبين هولاكو من الخلافِ، فأكرم الظاهِرُ بيبرس الرسُلَ، ثمَّ أرسل هو بدوره رسلًا إلى بركة خان يعرِّفُه بموافقته على هذا الأمر مِن تحالُفِهما ضد هولاكو، وكتب الظاهِرُ إلى ملك شيراز وأهل تلك الديار، وإلى عرب خفاجة، يستحثُّهم على قتالِ هولاكو مَلَكِ التتار، وأن الأخبارَ قد "},{"id":2662,"era":"c7","t":"بيعة الخليفة العباسي الحاكم بأمر الله .","s":"دخل الخليفة أبو العبَّاس الحاكِمُ بأمر الله أحمد بن الأمير أبي علي القبي بن الأمير علي بن الأمير أبي بكر بن الإمام المسترشد بالله بن المستظهر بالله أبي العباس أحمد, من بلاد الشرق وبصحبته جماعةٌ من رؤوس تلك البلاد، وقد شَهِدَ الوقعةَ بصحبة المستنصر الذي قُتِلَ فيها، وهرب هو في جماعةٍ مِن المعركة فسَلِمَ، فلما كان يومُ دخوله إلى مصر تلقَّاه السلطان الظاهر وأظهر السرورَ له والاحتفال به، وأنزله في الب"},{"id":2663,"era":"c7","t":"نهاية الأيوبيين بعد أخذ الظاهر بيبرس مدينة الكرك وإعدام صاحبها .","s":"ركب الظاهِرُ بيبرس من مصرَ في العساكر المنصورة قاصدًا ناحية بلاد الكرك، واستدعى صاحِبَها الملك المغيث عمر بن العادل أبي بكر بن الكامل، فلما قَدِمَ عليه بعد جهدٍ أرسله إلى مصر معتقَلًا، فكان آخر العهد به، وذلك أنَّه كاتب هولاكو وحَثَّه على القدوم إلى الشَّامِ مَرَّةً أخرى، وجاءته كتبُ التتار بالثَّباتِ ونيابة البلاد، وأنهم قادِمونَ عليه عشرون ألفًا لفتح الديارِ المصريَّة، وأخرج السلطانُ فتاوى الفقه"},{"id":2664,"era":"c7","t":"الظاهر بيبرس يأمر بعمارة المسجد النبوي بعد احتراقه .","s":"في رمضانَ جَهَّزَ الظاهِرُ صُنَّاعًا وأخشابًا وآلاتٍ كثيرة لعمارة مسجِدِ رَسولِ الله صلى الله عليه وسلم بعد حريقِه، فطيفَ بتلك الأخشاب والآلات بمصرَ فَرحةً وتعظيمًا لشأنها، ثم ساروا بها إلى المدينةِ النبوية."},{"id":2665,"era":"c7","t":"تحرير الظاهر بيبرس مدن ساحل الشام من الصليبيين .","s":"لمَا خلا بالُ السلطان الظاهر بيبرس من هَمِّ المَلِك المغيث صاحب الكرك، توجَّهَ بكليته إلى الفرنجِ؛ فإنَّهم كانوا قد شرعوا في التعَلُّل وطلبوا زرعين- وهي قرية في سهل زرعين بصفد-  فأجابَهم السلطان بأنكم تعوَّضتُم عنها في الأيام الناصرية ضِياعًا من مرج عيون، وهم لا يزدادونَ إلا شكوى، وآخِرَ الحال طلب الفرنجُ من والي غزة كتابًا بتمكينِ رُسُلِهم إذا حضروا، فكتب لهم الكتابَ، وتواصلت بعد ذلك كتُبُهم، وور"},{"id":2666,"era":"c7","t":"نصير الدين الطوسي مبعوث هولاكو للنظر في أوقاف بغداد .","s":"قدم نصيرُ الدين الطوسي إلى بغداد من جهة هولاكو، فنظر في الأوقافِ وأحوالِ البلد، وأخذ كتبًا كثيرةً مِن سائِرِ المدارس وحَوَّلها إلى رَصدِه الذي بناه بمراغة، ثم انحَدَر إلى واسط والبصرة."},{"id":2667,"era":"c7","t":"محاولة عز الدين السلجوقي قتل الأشكري صاحب القسطنطينية .","s":"في هذه السنةِ قبض الأشكري صاحِبُ قسطنطينية على عزِّ الدين كيكاوس بن كيخسرو بن كيقباذ صاحِبِ بلاد الروم، وسَبَبُه أن الأشكري كان قد وقع بين كيكاوس وبين أخيه، فاستظهر أخوه عليه، فهرب كيكاوس وبقِيَ أخوه ركن الدين قليج أرسلان في سلطنة بلاد الرومِ، ثم سار كيكاوس إلى قسطنطينيَّة، فأحسن إليه الأشكري صاحبُ قسطنطينية. وإلى من معه من الأمراء، واستمَرُّوا كذلك مدة، فعزمت الأمراءُ والجماعة الذين كانوا مع عزِّ"},{"id":2668,"era":"c7","t":"عدوان الأرمن على الشام .","s":"ورد الخبر أن هيتوم ملك الأرمن جمَعَ قوَّاتِه وسار إلى هرقلة، ونزل على قلعةِ صَرخد، فخرج البريدُ مِن قلعة الجبَلِ إلى حماة وحِمص بالمسير إلى حلب، فخرجوا وأغاروا على عَسكَرِ الأرمن، وقتَلوا منهم وأسَروا، فانهزم الأرمنُ واستنجدوا بالتَّتارِ، فقَدِمَ منهم من كان في بلادِ الروم وهم سبعُمائة فارس، فلما وصلوا إلى حارم رجعوا من كثرة الثلج، وقد هلك منهم كثيرٌ، ومع ذلك اهتم ملك الأرمن بالمسير إلى بلاد الشام"},{"id":2669,"era":"c7","t":"الأسبان يهاجمون غرناطة وابن الأحمر يهزمهم ويسترجع بعض المدن .","s":"كان مَلِكُ قشتالة ألفونسو ملك النصارى قد طلب من محمَّدِ بنِ يوسف بن الأحمر حاكِمِ غرناطةَ الساحِلَ من مالقةَ إلى المرية فاستعان ابنُ الأحمر بالمتطَوِّعة والمجاهدين الذين وفدوا إليه من المغربِ فهزم الأسبان واسترد منهم مدينةَ شريش وقادس، وأخذ ألفونسو أسيرًا. ثم اجتمع العدوُّ المخذول في جمع كبير، ونازلوا غرناطة فانتصر عليهم المسلمون، وقتلوا منهم مقتلةً عظيمة، وجُمِع من رؤوسِهم نحو خمسة وأربعين ألف رأ"},{"id":2670,"era":"c7","t":"وفاة الأمير حسام الدين الجوكندار من كبار أمراء دمشق .","s":"هو الأميرُ حسام الدين لاجين العزيزي الجوكندار- حامل الجوكان مع السلطان في لعب الكرة- وهو مِن غِلمانِ العزيز بن الظاهر بن السلطان صلاح الدين ومن كبار أمراء دمشق, وهو من أكابِرِ الأمراء وأعظَمِهم قدرًا، جوادًا ديِّنًا فارسًا شجاعًا حازمًا، له في الحروبِ آثارٌ جميلةٌ، وكان محبًّا للفقراء وأخلاقهم، كثيرَ البِرِّ بهم، يجمَعُهم على السَّمَاعات التي يُضرَبُ بها المثل، وكان له يدٌ طولى في كَسرِ التتار بوق"},{"id":2671,"era":"c7","t":"وفاة الملك الأشرف صاحب حمص .","s":"هو الملك الأشرف مظفر الدين موسى بن الملك المنصور أبو إبراهيم بن الملك المجاهد شيركوه بن الأمير ناصر الدين محمد بن أسد الدين شيركوه بن شادي بن مروان صاحب حمص، مَلَك حمصَ بعد وفاة أبيه، وطالت مدَّتُه بها، وكان فيه مداراةٌ للتَّتارِ واستمرَّ على ذلك إلى أن توفِّيَ بحمص يوم الجمعة حادي عشر من صفر عن غيرِ ولد ولا أخٍ ولا ولي، فبعث السلطانُ الظاهر بيبرس إلى الأمير عز الدين بيليك العلائي أحد الأمراء، فتس"},{"id":2672,"era":"c7","t":"وفاة الشيخ الصالح محمد بن منصور القباري الإسكندراني .","s":"الشيخ الصالحُ محمد بن منصور بن يحيى الشيخ أبي القاسم القباري الإسكندراني كان مقيمًا بغيط له يقتاتُ منه ويعمَلُ فيه ويبذره، ويتورَّعُ جدًّا ويُطعِمُ الناس من ثماره. توفي في سادس شعبان بالإسكندرية وله خمس وسبعون سنة، وكان يأمرُ بالمعروف وينهى عن المنكر ويردَعُ الولاة عن الظلمِ فيَسمَعون منه ويطيعونَه لزهده، وإذا جاء الناسُ إلى زيارته إنما يكَلِّمُهم من طاقة المنزل وهم راضونَ منه بذلك، ولما توفي ترك "},{"id":2673,"era":"c7","t":"سلطنة الملك السعيد ناصر الدين بركة .","s":"في يومِ الخميس ثالث عشر شوال من هذه السنة، أركَبَ السلطانُ الظاهر بيبرس ولَدَه الملك السعيد بشِعارِ السَّلطنةِ ومشى في ركابِه حاملًا له الغاشيةَ، وأخذها الأمراءُ الكبار واحدًا بعد واحدٍ، وعليهم الخِلَعُ الفاخرة، والحُلَل الزاهرة، وزينت المدينةُ زينةً تامة، واستبشر بذلك الخاصَّةُ والعامة، وتقَرَّر أن يكون أتابكه الأمير عز الدين أيدمر الحلي."},{"id":2674,"era":"c7","t":"الظاهر بيبرس يؤدب اليهود والنصارى بسبب افتعالهم الحرائق بمصر .","s":"كثُرَت الحرائقُ بالقاهرة ومِصرَ في مدَّة سفر السلطان الظاهر بيبرس، وأُشيعَ أنَّ ذلك من النصارى، ونزل بالناسِ مِن الحريق في كلِّ مكان شدَّةٌ عظيمة، ووُجِدَ في بعض المواضع التي احترقت نفطٌ وكبريت، فأمر السلطانُ بجمع النصارى واليهود، وأنكر عليهم هذه الأمورَ التي تفسَخُ عهدهم وأمَرَ بإحراقهم، فجُمِعَ منهم عالمٌ عظيم في القلعة، وأُحضِرَت الأحطاب والحلفاء، وأُمِرَ بإلقائهم في النار، فلاذُوا بعفوه وسألوا"},{"id":2675,"era":"c7","t":"هلاك هولاكو المغولي .","s":"هو هولاكو خان بن تولي خان بن جنكيز خان ملك التتار بن ملك التتار، وهو والِدُ مُلوكِهم، والعامَّةُ يقولون هولاوون مثل قلاوون، وقد كان هولاكو ملكًا جبارًا فاجرًا كفَّارًا- لعنه الله- قتل من المسلمين شرقًا وغربًا ما لا يَعلَمُ عَدَدَهم إلَّا الذي خلقهم، وسيجازيه على ذلك شَرَّ الجزاء، كان لا يتقيَّدُ بدين من الأديان، وإنما كانت زوجتُه تنصَّرَت وكان هو يترامى على محبَّة المعقولات، ولا يتصوَّر منها شيئًا"},{"id":2676,"era":"c7","t":"إجلاء السلطان الظاهر بيبرس التتار من مدينة البيرة .","s":"نزل التتارُ  على البيرة، فجهَّز السلطانُ بيبرس مِن فَورِه الأميرَ بدر الدين الخازندار- ممسك خزانة المال- على البريد؛ ليخرج أربعة آلاف فارس من بلاد الشام، وركبَ السلطان من موضِعِه وساق إلى القلعة، وعيَّنَ الأمير عز الدين إيغان المعروف باسم الموت لتقدمةِ العساكر، فخرجوا من القاهرة جرائدَ- خَيْلٌ لا رَجَّالة فيها- في رابع شهر ربيع الأول، ثم عين الأمير جمال الدين المحمدي، والأمير جمال الدين أيدغدي الح"},{"id":2677,"era":"c7","t":"الظاهر بيبرس يسترجع مدينة قيسارية وغيرها من الفرنج .","s":"رحل السلطانُ بيبرس إلى قريبِ عيونِ الأساور من وادي عارة وعرعرة، فلما كان بعد عشاءِ الآخرِ أمر العسكَرَ كُلَّه فلبسوا آلة الحرب، وركِبَ آخِرَ الليل وساق إلى قيسارية، فوافاها بكرةَ نهار الخميس تاسع جمادى الأولى على حين غفلةٍ مِن أهلها، وضرب عليها بعساكِرِه، وللوقت ألقى الناسُ أنفُسَهم في خندقها، وأخذوا سكك الحديدِ التي برسم الخيولِ مع المقاود والشبح، وتعلَّقوا فيها من كل جانبٍ حتى صعدوا، وقد نُصِبَت"},{"id":2678,"era":"c7","t":"الأسبان يستردون مرسية .","s":"كان المُسلِمونَ قد استردُّوا مدينة مرسية من يد الأسبان سنة 662هـ، ثم في هذا العام استطاع ألفونسو العاشر ملك قشتالة بمساعدة ليون وجيمس الأول ملك أرغونة من استعادتها من يد المسلمينَ، فلم يبقَ بيد المسلمينَ بعدها سوى مقاطعةِ غِرناطة."},{"id":2679,"era":"c7","t":"السلطان الظاهر بيبرس يحرر مدينة صفد .","s":"اهتم السلطانُ الظاهر بيبرس بأمر صفد، وأحضر العساكِرَ المجردة، ورحَّل الأمير بكتاش الفخري أميرَ سلاح بالدهليز السلطاني ونزل على صفد، وتبعه الأميرُ البندقدار والأميرُ عز الدين أوغان في جماعة، وحاصروها، هذا والسلطانُ مقيم على عكا حتى وافته العساكرُ، وعمل عدةَ مجانيقَ، ثم رحل والعساكِرُ لابسة، وساق إلى قربِ باب عكا، ووقفَ على تل الفضول، ثم سار إلى عين جالوت، ونزل على صفد يوم الاثنين ثامن شهر رمضان وحا"},{"id":2680,"era":"c7","t":"الملك المنصور صاحب حماة يأخذ بلاد سيس من الأرمن .","s":"سار الملك المنصور صاحب حماة ومن معه، إلى حصن دير بساك ودخلوا الدربند، وقد بنى التكفور هيتوم بن قسطنطين بن باساك ملك الأرمن على رؤوس الجبال أبراجًا وهو الذي تزهَّد فيما بعد، وترك المُلكَ لولده ليفون فاستعد ووقف في عسكره، فعندما التقى الفريقان أُسِرَ ليفون بن ملك سيس، وقُتِلَ أخوه وعمه، وانهزم عمه الآخر، وقتل ابنه الآخر، وتمزق الباقي من الملوك, وكانوا اثني عشر ملكًا وقُتِلَت أبطالهم وجنودهم، وركب ال"},{"id":2681,"era":"c7","t":"إيقاع السلطان الظاهر بيبرس بأهل قارا النصارى .","s":"عندما توجه الملك الظاهر من دمشق، لملتقى عساكره العائدة من غزوة بلاد سيس، ونزل على قارا بين دمشق وحمص، أمر بنهب أهلها وقتلِ كبارهم، فنُهِبوا وقُتِل منهم جماعة لأنهم كانوا نصارى، وكانوا يسرِقونَ المسلمين ويبيعونَهم بالخُفيةِ إلى الفرنج، وأُخِذَت صبيانهم مماليكَ، فترَبَّوا بين الترك في الديار المصرية، فصار منهم أجنادٌ وأمراء."},{"id":2682,"era":"c7","t":"إقامة الجمعة في الجامع الأزهر بعد أن انقطعت عنه زمنا طويلًا .","s":"أُقيمَت الجمعةُ بالجامع الأزهر من القاهرة، وكانت قد بطلت منه منذ ولي قضاء مصر صدرُ الدين عبد الملك بن درباس، عن السلطان صلاحِ الدين يوسف بن أيوب، وقد ظَلَّ كذلك إلى أن سكن الأميرُ عز الدين أيدمر الحلي بجواره، فانتزع كثيرًا من أوقاف الجامع كانت مغصوبة بيد جماعة، وتبرع له بمالٍ جزيل، واستطلق له مِن السلطان الظاهر بيبرس مالًا، وعَمَرَ الواهيَ من أركانه وجدرانه، وبيَّضَه وبلَّطَه ورمَّم سقوفه، وفَرَشه"},{"id":2683,"era":"c7","t":"وفاة بركة خان ابن عم هولاكو  .","s":"هو زعيمُ القبيلة الذهبية بركة خان بن جوجي بن جنكيز خان في بلاد القفجاق، وهو ابنُ عم هولاكو، وقد أسلم بركة خان وزوجته ججك  سنة 655، وكان يحِبُّ العلماء والصالحين ومن أكبَرِ حَسَناتِه كَسرُه لهولاكو وتفريقُ جنوده، وكان يناصِحُ الملكَ الظاهِرَ ويعَظِّمُه ويُكرِمُ رسُلَه إليه، ويُطلِقُ لهم شيئًا كثيرًا، وقد اتَّفَق معه على حربِ هولاكو، في سنة إحدى وستين وقد قام في الملكِ بعده بعضُ أهل بيته وهو منكوتمر"},{"id":2684,"era":"c7","t":"هدنة بين ابن الأحمر ملك غرناطة وملك قشتالة .","s":"تجدَّدَت الهدنةُ بين محمد بن الأحمر ملك غرناطة وبين مَلِك قشتالة ألفونسو العاشر على أن يَنزِلَ له عن عَدَدٍ من البلادِ والحُصونِ."},{"id":2685,"era":"c7","t":"وفاة كيقباد صاحب سلاجقة الروم .","s":"هو السلطانُ ركن الدين كيقباد بن السلطان غياث الدين كيخسرو بن السلطان علاء الدين كيقباد بن كيخسرو بن قليج أرسلان بن مسعود بن قليج أرسلان بن سليمان بن قطلمش بن أتسز بن إسرائيل بن سلجوق بن دقماق السلجوقي صاحب الروم، كان ملكًا جليلًا شجاعًا لكنَّه كان غيرَ سديد الرأي، كان جعَلَ أمْرَه بيَدِ البرواناه- الحاجب- فاستفحل أمر البرواناه، فأراد ركن الدين هذا قتْلَه فعاجله البرواناه وعمل على قَتْلِه حتى قُتِل"},{"id":2686,"era":"c7","t":"تحرير الظاهر بيبرس مدينة يافا من الفرنج .","s":"لما كان يوم العشرين من جمادى الآخر سار السلطانُ الظاهر من العوجاء إلى يافا، وحاصرها حتى ملكها من يومه، وأخذ قلعتها وأخرج من كان فيها من الفرنجِ، وهَدَمَها كُلَّها وجمع أخشابَها ورخامها وحمَلَه في البحر إلى القاهرة، وأمَرَ السلطان ببناء الجوامِعِ بتلك البلاد، وأزال منها المنكَراتِ، ورتَّبَ الخفراءَ على السواحلِ وألزَمَهم بدَركِها، ورسم أن المال المتحصَّل من هذه البلاد لا يُخلَطُ بغيره، وجعله لمأكله"},{"id":2687,"era":"c7","t":"تحرير الظاهر بيبرس حصن الشقيف من الفرنج  .","s":"جهَّزَ السلطان عسكرًا إلى الشقيف، ثم سار إليها بنفسه فنزل عليها في يوم الأربعاء تاسع عشر شهر رجب، وقدم الفقهاءُ للجهاد، ونصب السلطانُ عليها ستة وعشرين منجنيقًا، وألح عليها حتى أخذها يوم الأحد آخر رجب، وأخرج منها نساء الفرنجِ وأولادهم إلى صور، وقيَّدَ الرجال كلهم وسَلَّمَهم للعساكر، وهدم السلطان قلعةً استجدها الفرنجُ هناك، واستناب على القلعة الأخرى الأميرَ صارم الدين قايماز الكافري، ورتب بها الأجنا"},{"id":2688,"era":"c7","t":"غزو السلطان الظاهر بيبرس الفرنج بالشام .","s":"رحل السُّلطانَ من الشقيف إلى قرب بانياس، وبعث الأثقالَ إلى دمشق وجهز الأميرَ عز الدين أوغان بجماعة لجهة، وجهز الأمير بدر الدين الأيدمري في جماعةٍ إلى جهة أخرى، فحَفِظَت العساكر الطرقات، ثم سار السلطانُ إلى  طرابلس وخيَّمَ عليها في النصف من رجب، وناوش أهلَها القتال وأخذ برجًا كان هناك، وضرب أعناقَ مَن كان من الفرنج، وأغارت العساكِرُ على من في تلك الجبال، وغَنِموا شيئًا كثيرًا وأخذوا عدة مغاير بالسي"},{"id":2689,"era":"c7","t":"الظاهر بيبرس يحرر إمارة أنطاكية من الصليبيين .","s":"بعد أن انتهى السلطان الظاهر بيبرس من أمر طرابلس وعاد إلى حماة واجتمعت فيه أمراؤه، فأصبح أول شهر رمضان والسلطان مغير على أنطاكية، وأطافت العساكرُ بها من كل جانب، فتكمَّلوا بخيامهم في ثالثه، وبعث السلطان إلى الفرنج يدعوهم وينذرهم بالزحف عليهم، وفاوضهم في ذلك مدة ثلاثة أيام وهم لا يجيبونَ، فزحف عليهم وقاتلهم قتالًا شديدا، وتسَوَّر المسلمون الأسوار من جهة الجبل بالقرب من القلعة، ونزلوا المدينة ففر أهل"},{"id":2690,"era":"c7","t":"السلطان الظاهر بيبرس يحرر قلعة بغراس .","s":"حرر الملك الظاهر بغراس وسبب ذلك أنَّه لما فتح أنطاكية، هرب أهلُ بغراس منها وتركوا الحِصنَ خاليًا، فأرسل الظاهِرُ من استولى عليها، وشحنه بالرِّجالِ والعُدَد، وصار من الحصونِ الإسلاميَّة."},{"id":2691,"era":"c7","t":"دخول السلطان بيبرس إلى دمشق بعد تحرير أنطاكية .","s":"لما فرغ أمر السلطانِ الظاهِرِ من غزوه للشامِ وتحرير أنطاكية عاد منصورًا، فدخل دمشقَ في السابع والعشرين من رمضان في أبهة عظيمة وهيئة هائلة، وقد زُينت له البلد، ودُقت البشائر فرحًا به."},{"id":2692,"era":"c7","t":"السلطان الظاهر بيبرس يجدد البيعة لولده بركة من بعده .","s":"جدَّد السلطان الظاهِرُ البيعةَ لولده من بعده الملك السعيدِ محمد بركة خان، وأحضَرَ الأمراءَ كُلَّهم والقضاة والأعيان وأركَبَه ومشى بين يديه، وكتب له ابنُ لقمان تقليدًا هائلًا بالمُلكِ مِن بعد أبيه، وأن يحكُمَ عنه أيضًا في حالِ حياته."},{"id":2693,"era":"c7","t":"إبطال السلطان الظاهر بيبرس الخمور وبيوت الخنا .","s":"أمَرَ السلطان الملك الظاهر بإراقةِ الخمور وتبطيل المُفسِدات وبيوت الخنا بالبلاد كلها، فنُهِبَت الزواني وسُلِبنَ جميعَ ما كان معهن حتى يتزوَّجنَ، وكُتِبَ إلى جميع البلاد بذلك، وأسقَطَ المكوسَ التي كانت مرتَّبةً على ذلك، وعوَّضَ من كان محالًا على ذلك بغيرِها."},{"id":2694,"era":"c7","t":"الظاهر بيبرس يبسط نفوذه على الحجاز .","s":"وصَلَ السلطانُ بيبرس إلى المدينة النبويَّةِ في خامس عشر من ذي القعدة، فلم يقابِلْه جماز ولا مالك أميرا المدينة وفَرَّا منه، ورحل منها في سابع عشر، وأحرم فدخل مكَّةَ في خامس ذي الحجة، وأعطى خواصَّه جملةً من المال ليفَرِّقوها سرًّا، وفرق كساويَ على أهل الحرمينِ وصار كواحدٍ مِن الناس، لا يحجُبُه أحَدٌ ولا يحرُسُه إلا الله، وهو منفَرِدٌ يصلي ويطوف ويسعى، وغَسَلَ البيتَ، وصار في وسط الخلائق، وكلُّ من ر"},{"id":2695,"era":"c7","t":"رياح وأمطار شديدة في مصر يهلك بسببها الكثير .","s":"هبَّت ريحٌ شديدة بديار مصر غرقت مائتي مركبٍ في النيل، وهلك فيها خلقٌ كثير، ووقع هنالك مطرٌ شديدٌ جدًّا، وأصاب الشامَ من ذلك صقعةٌ أهلَكَت الثِّمارَ."},{"id":2696,"era":"c7","t":"تحصين الإسكندرية وعمل الجسور خوفًا من مداهمة الفرنجة .","s":"اهتم السلطان الظاهر لأمر الإسكندرية وأولاها اهتمامَه البالغ كل ذلك لأنها محطُّ نظر الفرنج، ومنها يدخلون مصرَ، فأمر بتحصينها للغايةِ، فعُمِلَت الجسور عليها التي تمنع دخول السفنِ وحُصِّنَت بالأسوار، وقُتِلَت الكلابُ التي فيها."},{"id":2697,"era":"c7","t":"حرب الموحدين مع بني مرين ونهاية دولة الموحدين في المغرب .","s":"قام ملك الموحدين الواثقُ بالله المعروف بأبي دبوس بالسير لقتال بني مرين فالتقى معهم في معركة جرت في وادي غفو بين مراكش وفاس، انهزم فيها الموحدون وقُتل فيها أبو العلاء إدريس بن عبد الله بن محمد بن يوسف الواثق واستولى المرينيون على معسكرهم، وكان الواثق آخر ملوك الموحدين في المغرب، وبالتالي تنتهي دولتهم في المغرب."},{"id":2698,"era":"c7","t":"تحالف الصليبيين مع المغول .","s":"بعد أن رجع السلطان الظاهر من الحج ودخل دمشق وعاد منها إلى مصر، بلغه حركة التتار، وأنهم واعدوا فرنج الساحل، فعاد إلى قلعة الجبل، فورد الخبر بغارة التتار على الساجور بالقرب من حلب، فجرد السلطانُ الأميرَ علاء الدين البندقدار في جماعة من العسكر، وأمره أن يقيمَ في أوائل البلاد الشاميَّة على أُهبة، وسار السلطانُ من قلعة الجبل في ليلة الاثنين الحادي عشر ربيع الأول ومعه نفرٌ يسير فوصَلَ إلى غزةَ، ثمَّ دخل"},{"id":2699,"era":"c7","t":"إغارة السلطان الظاهر بيبرس على عكا بسبب نكثهم العهد .","s":"خرج فرنج عكا وخيَّموا بظاهرها، وركبوا وأعجبَتْهم أنفسُهم بمن قدم إليهم من فرنج الغرب، وتوجَّهت طائفة منهم إلى عسكر جينين وعسكر صفد، فخرج السلطانُ من دمشق على أنه يتصَيَّد في مرج برغوث وبعث من أحضر إليه العُدَد ومن أخرج العساكرَ كُلَّها من الشام، فتكاملوا عنده بكرةَ يوم الثلاثاء الحادي عشر ربيع الأول بمرج برغوث، وساق بهم إلى جسرِ يعقوب فوصل آخرَ النهار، وسار بهم في الليل فأصبحَ في أول المرج، وكان ا"},{"id":2700,"era":"c7","t":"إغارة السلطان الظاهر بيبرس على حصن الأكراد  .","s":"ركب السلطان في ثالث جمادى الآخرة، بمائتي فارس من غير سلاح، وأغار على حصن الأكراد وصَعِدَ الجبل الذي عليه حصن الأكرادِ ومعه قدر أربعين فارسًا، فخرج عليه عدة من الفرنج ملبسين، فحمل عليهم وقتل منهم جماعةً، وكسر باقيَهم وتبعهم حتى وصل إلى خنادقهم، وقال يستخف بهم: خلوا الفرنجَ يخرجوا، فما نحن أكثَرُ من أربعين فارسًا، وعاد إلى مخيمه، ورعى الخيولُ مروجَها وزروعَها."},{"id":2701,"era":"c7","t":"أمراء الشام يقدمون على الظاهر بيبرس لتقديم فروض الطاعة .","s":"أثناء حصارِ السلطان بيبرس حصن الأكرادَ حضر إلى خدمة السلطان كثيرٌ من أصحاب البلاد المجاورة، فلم يبق أحدٌ إلا وقدم على السلطان مثل: صاحب حماة، وصاحب صهيون، إلا نجم الدين حسن بن الشعراني صاحب قلاع الإسماعيليَّة، فإنه لم يحضر بل بعث يطلبُ تنقيضَ القطعة التي حملوها لبيت المال، بدلًا مما كانوا يحملونه إلى الفرنج، وكان صارم الدين مبارك بن الرضي صاحب العليقة قد تغير السلطان عليه من مدة، فدخل صاحب صهيون ب"},{"id":2702,"era":"c7","t":"الحملة الصليبية الثامنة على شمال أفريقيا بقيادة لويس التاسع .","s":"قام ملك فرنسا لويس التاسع بتجهيز حملة صليبيةٍ هي في التعداد الثامنة، وقصد بها تونسَ ليجعَلَها طريقه إلى مصر، لكنَّ قواتِ أمير تونس أبي عبد الله محمد بن أبي زكريا الحفصي تصَدَّت لها وساعد أيضًا على فشلها انتشار الأوبئة بينهم مع حرارةِ الجو وكان ممَّن توفي في تونس من الصليبيين الملك نفسُه لويس التاسع، غير الكثير من أفراد جيشه."},{"id":2703,"era":"c7","t":"وفاة الملك تقي الدين عباس بن الملك العادل الأيوبي .","s":"هو الملك تقي الدين عباس بن الملك العادل أبي بكر بن أيوب بن شاذي، وهو آخِرُ من بقي من أولاد العادل، وقد سَمِعَ الحديثَ مِن الكندي وابن الحرستاني، وكان محترمًا عند الملوك لا سيما عند الملك الظاهِرِ لا يترفَّعُ عليه أحد في المجالِسِ والمواكب، وكان لين الأخلاق حَسَن العِشرة، لا تُمَلُّ مجالسته‏, توفِّيَ يوم الجمعة الثاني والعشرين من جمادى الآخرة بدرب الريحان، ودُفِنَ بتربة له بسفح قاسيون."},{"id":2704,"era":"c7","t":"السلطان الظاهر بيبرس يفتح حصن الأكراد .","s":"في يوم الخميس ثامن رجب دخل الظاهر دمشق وفي صحبته ولده الملك السعيد بركة وابن الحنا الوزير وجمهور الجيش ثم خرجوا متفرقين وتواعدوا أن يلتقوا بالساحل ليشنوا الغارة على جبلة واللاذقية ومرقب وعرقا وما حولها من البلاد، فلما اجتمعوا فتحوا صافينا والمجدل، ثم ساروا فنزلوا على حصنِ الأكراد يوم الثلاثاء التاسع عشر رجب، وله ثلاثةُ أسوار، فنصبوا المنجنيقاتِ ففتحها قسرًا يوم نصف شعبان، فدخل الجيش، وكان الذي يحا"},{"id":2705,"era":"c7","t":"تحرير السلطان الظاهر حصن عكا .","s":"بلغ السلطان الظاهر بيبرس وهو مخيِّم على حصن الأكراد أنَّ صاحب جزيرة قبرص قد ركِبَ بجيشه إلى عكا لينصُرَ أهلها خوفًا من السلطان، فأراد السلطان أن يغتَنِمَ هذه الفرصة فبعث جيشًا كثيفًا في اثني عشرة شيني - نوعا من المراكب- ليأخذوا جزيرة قبرص في غيبةِ صاحِبِها عنها، فسارت المراكِبُ مسرعة فلما قاربت المدينة جاءتها ريحٌ عاصف فصدم بعضها بعضًا فانكسر بعضُها, وغَرِقَ خلقٌ وأسَرَ الفرنج من الصناع والرجال قر"},{"id":2706,"era":"c7","t":"وفاة ابن سبعين الصوفي .","s":"هو أبو محمد عبد الحق بن إبراهيم بن محمد بن نصر بن محمد بن نصر بن محمد بن سبعين، القرشي، المخزومي، بن قطب الدين المقدسي  الصوفي الرقوطي، نسبة إلى رقوطة بلدة قريبة من مرسية بالأندلس. المشهور بابن سبعين، ولِدَ سنة أربع عشرة وستمائة، واشتغل بعلم الأوائل والفلسفة، فتولَّدَ له من ذلك نوع من الإلحاد، وصنَّفَ فيه، وكان يعرف السيميا، وكان يلَبِّسُ بذلك على الأغبياء من الأمراء والأغنياء، ويزعُمُ أنه حال من "},{"id":2707,"era":"c7","t":"السلطان الظاهر بيبرس يحرر القرين .","s":"خرج السلطان الظاهر بيبرس من دمشق وأتى إلى الساحل، ثم سار إلى القرين وهي  قلعة تقع شمال شرق عكا ونازله، وأخذ باشورته –حائط ظاهر الحصن يختفي وراءه الجند عند القتال- في ثاني ذي القعدة، فأخذ الحصن وأمر بهدم قلعته، ثم سار عنه ونزل اللجون، وتقدمت مراسيمه إلى النواب بالديار المصرية بتجهيز الشواني، ثم إن السلطان جاء إلى عكا وأشرف عليها وتأملها، ثم سار إلى الديار المصرية."},{"id":2708,"era":"c7","t":"السلطان الظاهر بيبرس يأمر بإراقة الخمور من سائر بلاده .","s":"وفي اليوم السابع عشر من ذي الحجة من هذه السنة أمر بإراقة الخمور من سائر بلادِه وتهَدَّد من يعصِرُها أو يعتَصِرُها بالقتل، وأسقَطَ ضمان ذلك، وكان ذلك بالقاهرة وحدها كلَّ يوم ضمانه ألف دينار، ثم سارت البُرُد بذلك إلى الآفاق."},{"id":2709,"era":"c7","t":"الروم يغيرون على بعض بلاد المسلمين .","s":"وصلت العساكرُ المصريَّةُ إلى حضرة السلطان الظاهر بيبرس إلى دمشق فسار بهم منها في سابع هذا الشهر، فاجتاز بحماة واستصحب ملكها المنصور، ثم سار إلى حَلَب فخيم بالميدان الأخضر بها، وكان سَبَبُ ذلك أن عساكِرَ الروم جمعوا نحوًا من عشرة آلاف فارس وبعثوا طائفةً منهم فأغاروا على عينِ تاب، ووصلوا إلى نسطون ووقعوا على طائفة من التركمان بين حارم وأنطاكية فاستأصلوهم، فلما سمع الروم بوصول السلطان ومعه العساكر ال"},{"id":2710,"era":"c7","t":"محاربة السلطان الظاهر طائفة من التتار وخوضه نهر الفرات .","s":"في خامس جمادى الآخرة وصل السلطان بعسكره إلى الفراتِ؛ لأنه بلغه أن طائفةً مِن التتار هنالك فخاض إليهم الفراتَ بنَفسِه وجنده، وقتل من أولئك مقتلةً كبيرةً وخلقًا كثيرًا، وكان أوَّلَ من اقتحم الفراتَ يومئذ الأميرُ سيف الدين قلاوون وبدر الدين بيسرى وتبعهما السلطانُ، وكان قد اقتحم الأمير قلاوون الألفي الصالحي الفرات، فخاض ومعه عِدَّةٌ وافرة، وصدم التتارَ صَدمةً فَرَّقهم بها ومزَّقهم، ثم فعل بالتتار ما ف"},{"id":2711,"era":"c7","t":"وفاة الإمام العلامة القرطبي صاحب التفسير .","s":"هو الإمامُ العلَّامة، المتفنن المتبحر في العلم، أبو عبد الله محمد بن أحمد بن أبي بكر بن فرخ الخزرجي الأنصاري القرطبي، من أهل قرطبة، كان عالِمًا بالتفسير والأحكام واللغة. قال الذهبي: \"له تصانيفُ مفيدة تدل على كثرة اطلاعه ووفور فضله، أشهرها تفسيره الجامع لأحكام القرآن، وقد سارت به لعظيمِ شأنه الركبانُ، وهو كامل في معناه. ومن تصانيفه كذلك: الأسنى في شرح أسماء الله الحسنى، والتذكار في أفضل الأذكار،  و"},{"id":2712,"era":"c7","t":"تسليم الإسماعيلية ما كان بقي بأيديهم من الحصون .","s":"في سادس عشر من صفر عام 670هـ قدم شمس الدين بن نجم الدين صاحب الدعوة الإسماعيلية، فقُبِضَ عليه وعلى أصحابه وسُيِّروا إلى مصر، واستمرت مضايقةُ حصونهم حتى تسَلَّم نواب السلطان حصنَ الخواني وحصن العليقة، وفي ذي القعدة من هذا العام سلمت الإسماعيليةُ ما كان بقي بأيديهم من الحصونِ، وهي الكهف، والقدموس، والمنطقة، وعُوِّضوا عن ذلك بإقطاعات، ولم يبق بالشامِ شَيءٌ لهم من القلاع، واستناب السلطانُ فيها."},{"id":2713,"era":"c7","t":"وفاة الملك المغيث عمر بن الملك العادل .","s":"هو الملك المغيث فتح الدين أبو الفتح عمر بن الملك العادل أبي بكر بن الملك الكامل محمد بن الملك العادل أبي بكر بن أيوب، صاحب الكرك، كان مولده بالقاهرة في صفر سنة 606. قتل المَلِك المغيث في هذه السنة, وسَبَب قتله كما قال الذهبي: \"أنه كان في قلب الملك الظاهِرِ بيبرس منه غيظٌ عظيم، لأمورٍ كانت بينهما، قيل إنَّ المغيث أكره امرأةَ الملك الظاهر بيبرس، لَمَّا قبضَ المغيث على البحرية. وأرسَلَهم إلى الناصر ي"},{"id":2714,"era":"c7","t":"مقتل رجل ادعى أنه عيسى بن مريم .","s":"فوض ملك التتار إلى علاء الدين صاحب الديوان ببغداد النظرَ في تستُرَ وأعمالِها، فسار إليها ليتصَفَّحَ أحوالها فوجد بها شابًّا من أولاد التجَّار يقال له \"لي\" قد قرأ القرآنَ وشَيئًا من الفقه والإشارات لابن سينا، ونظر في النجوم، ثمَّ ادعى أنه عيسى ابن مريم، وصَدَّقه على ذلك جماعةٌ من جهلة تلك الناحية، وقد أسقَطَ لهم من الفرائِضِ صلاةَ العصر وعِشاء الآخرة!! فاستحضره وسأله عن ذلك فرآه ذكيًّا، إنما يفعل ذ"},{"id":2715,"era":"c7","t":"وفاة جلال الدين الرومي أحد أعلام الشعر الصوفي .","s":"هو جلال الدين محمد بن محمد بن حسين بهاء الدين البلخي البكري, وعرف أيضًا باسم مولانا جلال الدين الرومي شاعر، عالمٌ بفقه الحنفيَّة. من فحولِ شعراء الصوفية في الإسلام. وُلد ببلخ في 6 من ربيع الأول 604هـ (30 من سبتمبر 1207م) لأسرةٍ قيل: إن نسَبَها ينتهي إلى أبي بكر الصديقِ رضي الله عنه، وتحظى بمصاهرة البيت الحاكم في خوارزم، وأمُّه كانت ابنة خوارزم شاه علاء الدين محمد, وما كاد يبلغُ الثالثة من عمره حتى"},{"id":2716,"era":"c7","t":"وفاة ابن مالك النحوي صاحب الألفية .","s":"هو العلَّامة الأوحَدُ، أبو عبدِ اللهِ جمالُ الدين محمد بن عبد الله بن مالك الطائي الجياني الأندلسي الشافعي النحوي، نزيلُ دمشق. ولد بجيَّان في الأندلس سنة 600 وأقام بحَلَب مدة، ثم بدمشق، أخذَ العربية عن غير واحد، وجالس بحلب ابن عمرون وغيره. وتصدر بحَلَب لإقراء العربية وصَرَف همَّتَه إلى إتقان لسان العرب حتى بلغ فيه الغايةَ، وحاز قَصَب السبق، وأربى على المتقدِّمين, وهو صاحب الألفية المشهورة (ألفية ب"},{"id":2717,"era":"c7","t":"وفاة نصير الدين الطوسي وزير هولاكو .","s":"هو الفيلسوف الرياضي الفلكي نصير الدين أبو جعفر محمد بن عبد الله الطوسي، كان يقال له المولى نصير الدين، ويقال الخواجا نصير الدين، اشتغل في شبيبتِه وحصَّل علم الأوائلِ جيدًا، وصَنَّف في ذلك في علم الكلامِ، وشرح الإشارات لابن سينا، حتى كان رأسًا في علم الأوائل، لا سيَّما معرفة الرياضة وصنعة الأرصاد، فإنه فاق بذلك على الكبار. اشتغل في بداية أمرِه على المعين سالم بن بدران المصري المعتزلي، المتشيِّع الر"},{"id":2718,"era":"c7","t":"استيلاء المرينيين على سجلماسة .","s":"قام المنصور بالله أبو يوسف يعقوب بن عبد الحق المريني الأمازيغي بالاستيلاءِ على سجلماسة واستخلصها من أيدي بني زيان بعد أن حاصرها عامًا كاملًا، ويُذكَرُ أنه استعمل في هدم أسوارِها قاذفات البارود."},{"id":2719,"era":"c7","t":"الظاهر بيبرس يغزو كليكيا والمصيصة الأرمينية .","s":"في سابع رمضان دخل السلطانُ بيبرس حماة، ثم صار منها بالعساكر والعربان، وجرَّد السُّلطان عيسى بن مهنا، والأمير حسام الدين العنتابي، بعسكرٍ إلى البيرة، وجهَّزَ الأمير قلاوون الألفي والأمير بيليك الخازندار – ممسك خزنة المال-  بعسكرٍ إلى بلاد سيس؛ وذلك بسبب أن الحاجِبَ معين الدين سليمان بن مهذب الدين علي الديلمي وزير قليج أرسلان الرابع ملك سلاجقة الروم دعاه إليها وحرضه على القدوم، وبسبب أيضا تحالف الأر"},{"id":2720,"era":"c7","t":"ملك غرناطة يستنجد بملك مرين .","s":"استنجد أبو عبد الله محمد الثاني بن محمد الأول ملك غرناطة الملقَّب بالفقيه السلطان أبي يوسف المنصور يعقوب بن عبد الحق ملك بني مرين فسَيَّرَ إليه الأخير جيشًا كثيفًا عبر البحر ونزل مدينةَ طريف وأخذ في غزو البلاد التي استولى عليها الأسبانُ فخرج إليه سانشو ملك قشتالة ووقع اللقاءُ على مقربة من مدينة استجه، وانتهت المعركة الضارية بانتصار المسلمين فطلب سانشو الصلحَ فاستجاب السلطان واشترط شروطًا منها مسال"},{"id":2721,"era":"c7","t":"التتار والروم ومن تواطأ معهم من المسلمين يغزون البيرة .","s":"نزل التتار على البيرة في ثلاثين ألف مُقاتلٍ، خمسة عشر ألفًا من المغول، وخمسة عشر ألفًا من الروم، والمقَدَّم على الجميع البرواناه- الحاجب- وهو حاجب السلطان السلجوقي بأمر أبغا بن هولاكو ملك التتار، ومعهم جيش الموصل وجيش ماردين والأكراد، ونَصَبوا عليها ثلاثة وعشرين منجنيقًا، فخرج أهلُ البيرة في الليل فكبسوا عسكَرَ التتار وأحرقوا المنجنيقاتِ ونهبوا شيئًا كثيرًا، ورجعوا إلى بيوتهم سالمين، فأقام عليها ا"},{"id":2722,"era":"c7","t":"عسكر السلطان الظاهر بيبرس يقاتلون أهل النوبة .","s":"حضر ابنُ أخت ملك النوبة واسمه مشكد متظلمًا من داود ملك النوبة، فجَرَّد السلطانُ الظاهر بيبرس معه الأميرَ آقسنقر الفارقاني، ومعه من العسكَرِ وأجناد الولاة والعربان، والزرَّاقون والرُّماة والحراريقُ والزردخاناه-خزانة السلاح- فخرج مشكد في مستهل شعبان حتى تجاوز أسوان، وقاتل خالَه الملك داود ومن معه من السودان، فقاتلوه على النجب، وهَزَمَهم وأسر منهم كثيرًا، وبعث الأميرُ آقسنقر الأميرَ عزَّ الدين الأفرم"},{"id":2723,"era":"c7","t":"ثورة العامة على اليهود بمدينة فاس .","s":"ثارت العامَّةُ في فاس على اليهود بسَبَبِ حدثٍ أحدثوه فقتلوا منهم أربعة عشر يهوديًّا، ولولا أنَّ السلطان يعقوب ركب بنَفسِه وردَّ العامة عنهم لقتلوهم جميعًا."},{"id":2724,"era":"c7","t":"وفاة أحمد البدوي الصوفي .","s":"هو أبو العباس أحمد بن علي بن إبراهيم بن محمد بن أبي بكر المقدسىُّ الأصل، الحسيني البدوي، يلقَّب بالسطوحي، والسيد صاحب الشهرة في الديار المصرية، الذي يَستغيثُ به كُفرًا وعُدوانًا كثيرٌ مِن المتصوفة اليوم، ويعتقدون فيه من النفع والضر ممَّا لا يملكه إلا الله، يُعرف بأبي اللثَّامين لملازمته اللثامَ صيفًا وشتاء، أصله من المغرب حيث وُلِدَ بفاس، سنة 596 طاف البلاد وأقام بمكة والمدينة، ودخل مصرَ في أيام ا"},{"id":2725,"era":"c7","t":"وقعة البلستين وفتح قيسارية .","s":"في ثالث عشر المحرم دخل السلطان الظاهر بيبرس إلى دمشق، وسبق العساكر إلى بلاد حلب، فلما توافدت إليه أرسل بين يديه الأميرَ بدر الدين الأتابكي بألف فارس إلى البلستين بتركيا، فصادف بها جماعةً مِن عسكر الروم فرَكِبوا إليه وحَمَلوا إليه الإقاماتِ، وطلب جماعةٌ منهم أن يدخلوا بلادَ الإسلام فأذِنَ لهم، فدخل طائفةٌ منهم بيجار وابن الخطير، فرسم لهم أن يدخلوا القاهرةَ فتلقَّاهم الملك السعيد بركة بن السلطان بيب"},{"id":2726,"era":"c7","t":"وفاة الأمير أبي عبد الله محمد بن الأمير أبي زكريا صاحب تونس. .","s":"هو الأميرُ أبو عبد الله محمد بن يحيى بن عبد الواحد بن عمر الأمير المستنصر بن الأمير أبي زكرياء الهنتاتي البربري، الموحدي، ولي أبوه يحيى مدة ومات سنة 647 وهما بربريان من أتباع دولة الموحدين صاحبا تونس وأجل ملوكِ الغرب في زمانهما، كان جدُّه الشيخ الهنتاتي من العشرة خواص ابن تومرت، وكان محمد ملكًا مدبِّرًا شجاعًا، عاليَ الهمة، سائسًا، متحيلًا على بلوغ مقاصده، مقتحمًا للأخطار، كريمًا جوادًا، ذا غرام ب"},{"id":2727,"era":"c7","t":"مقتل الشيخ خضر بن أبي بكر المهراني .","s":"هو الشيخ خضر بن أبي بكر المهراني العدوي وهو شيخ السلطان الظاهر بيبرس، كان حظيًّا عنده مُكرَّمًا لديه، له عنده المكانة الرفيعة، كان السلطان ينزل بنَفسِه إلى زاويته التي بناها له في الحُسَينية، في كل أسبوع مرة أو مرتين، وبنى له عندها جامعًا يخطب فيه للجمعة، وكان يعطيه مالًا كثيرًا، ويطلق له ما أراد، ووقف على زاويته شيئًا كثيرًا جِدًّا، وكان معظَّمًا عند الخاص والعام بسبب حبِّ السلطان وتعظيمه له، وكا"},{"id":2728,"era":"c7","t":"وفاة السلطان الظاهر بيبرس البندقداري  وتولي ابنه السعيد بركة .","s":"هو السلطان الأعظم الملك الظاهر ركن الدين بيبرس بن عبد الله، البندقداري  الصالحي؛ يُعد المؤسِّسَ الفعلي لدولة المماليك وأعظَمَ سلاطينها، اجتمعت فيه صفاتُ العدل والفروسية والإقدام. ولِدَ بيبرس- بيبرس كلمة تركية تعني أمير فهد- بأرض القبجاق سنة 625، تعرضت ديارهم في القبجاق لغارات فأُسِرَ جماعة منهم، وكان بيبرس فيمن أُسِرَ وحُمِلَ إلى القاهرة، فاشتراه الأميرُ علاء الدين البندقدار الصالحي فطلع بطلًا شجا"},{"id":2729,"era":"c7","t":"ما فعله الملك السعيد بأمراء المماليك بعد أن استلم الملك .","s":"في سادس ربيع الآخر مات الأمير بدر الدين بيليك النائب، واتهم أن المَلِكَ السعيد سَمَّه؛ وذلك أنه اختصَّ بجماعة من المماليك الأحداث، ومن بعده اضطربت أمورُ الملك السعيد، وأقام الملك السعيد بعده في نيابةِ السلطنة الأمير شمس الدين آقنسنقر الفارقاني، وكان حازمًا، فضم إليه جماعة منهم شمس الدين أقوش، وقطليجا الرومي، وسيف الدين قلج البغدادي، وسيف الدين بيجو البغدادي، وعز الدين ميغان أمير شكار، وسيف الدين ب"},{"id":2730,"era":"c7","t":"وفاة الإمام محيي الدين النووي .","s":"هو الإمام أبو زكريا محيي الدين يحيى بن شرف بن حسن بن حسين بن جمعة النووي، الشافعي نسبة إلى نوى قرية من قرى حوران بسوريا، وُلِدَ بنوى في العشر الأوسط من المحرم سنة 631. رحل أبو زكريا إلى دمشق ودرس فيها وسَمِعَ الحديث مع زهد وورع وأمر بالمعروف ونهي عن المنكر، قال الشيخ محيي الدين: \"لما كان لي تسع عشرة سنة قدم بي والدي إلى دمشق في سنة تسع وأربعين، فسكنت المدرسة الرواحية، وبقيت نحو سنتين لم أضع جنبي إ"},{"id":2731,"era":"c7","t":"ملك غرناطة يسترد مالقة .","s":"استولى ملك غرناطة الفقيه محمد الثاني بن الأحمر على مالقة وضمها إلى مملكته، وكان المنصورُ يعقوب ملك بني مرين يطمع فيها فساءت بذلك العلاقةُ بينه وبين ملك غرناطة، فعَزَم على قتلِه."},{"id":2732,"era":"c7","t":"خلاف يدب في سائر الطوائف .","s":"اتَّفَق في هذه السنة أمورٌ عجيبة، وذلك أنَّه وقع الخُلفُ بين الممالك كلِّها؛ اختلفت التتارُ فيما بينهم واقتتلوا فقُتِلَ منهم خلق كثير، واختلفت الفرنجُ في السواحِلِ وصال بعضهم على بعض وقتل بعضُهم بعضًا، وكذلك الفرنجُ الذين في داخل البحور وجزائرها، فاختلفوا واقتتلوا، وقَتَلت قبائلُ الأعراب بعضُها في بعض قتالًا شديدًا، وكذلك وقع الخلف بين العشير من الحوارنة وقامت الحرب بينهم على ساق، وكذلك وقع الخلفُ"},{"id":2733,"era":"c7","t":"بنو مرين يغزون غرناطة .","s":"لما ساءت العلاقة بين بني مرين وملك غرناطة بسبب استيلاء ابن الأحمر على مالقة، وجَّه المنصور أبو يوسف ملك بني مرين في هذه السنة جيشًا بقيادة ابنه الأمير أبي يعقوب لقتال بني الأحمر واستعان بملك قشتالة فاستولى على ماربللا وهي من أملاك غرناطة، ثم زحف إلى غرناطة، ولكن ابن الأحمر ردَّه عنها، ثم إن ابن الأحمر صالح المنصور سلطان بني مرين على أن يتنازلَ له عن مالقة لتكون قاعدةَ عبور لبني مرين إلى الأندلس."},{"id":2734,"era":"c7","t":"خلع الملك السعيد وتولية أخيه سلامش بن الظاهر بيبرس .","s":"كان قد حدث من الملك السعيد أشياء أوغرت صدورَ الأمراء عليه، وأصبَحَ خاصية الملك يحظَونَ بما يريدون ويُبعِدونَ من أرادوا حتى كان في السنة الماضيةِ أن أرسل بعض الأمراء إلى سيس للقتال فخرجوا وهم مكرهون، فأما الأمراء فإنهم غَزَوا سيس وقتلوا وسَبَوا، ثم عادوا إلى دمشق ونزلوا بالمرجِ، فخرج الأميرُ كوندك إلى لقائهم على العادة، وأخبرهم مما وقع من الخاصكية في حَقِّهم وحَقِّه من تخوُّفِ الملك منهم، فحَرَّك ق"},{"id":2735,"era":"c7","t":"عزل العادل سلامش وتنصيب السلطان قلاوون الألفي .","s":"بعد أن تمَّ تنصيبُ العادل سلامش في الملك لم يكنْ له من الأمر شيءٌ، بل كل شيء من حَلٍّ وعَقدٍ بيد قلاوون الألفي فشرع الأمير قلاوون في القبض على الأمراء الظاهريَّة، فقبض على أعيانِهم وبعث بهم إلى الثغور فسُجِنوا بها، وأمسك أيضًا كثيرًا من الظاهريَّة وملأ الحبوسَ بهم، وأعطى قلاوونُ ومنع وقطع، ووصل واستخدم وعزل، فكان صورتُه أتابك وتصَرُّفُه تصرُّفَ الملوك، وانفرد قلاوون بالمملكة وأجَدَّ في تدبر أحواله"},{"id":2736,"era":"c7","t":"وفاة الملك السعيد محمد بركة خان بن الملك الظاهر صاحب الكرك .","s":"هو السُّلطان الملك السعيد، ناصر الدين، أبو المعالي محمد بركة خان بن السلطان الملك الظاهر بيبرس وُلِدَ سنة 658 في صفر بالعش من ضواحي القاهرة، وسلطنه أبوه وهو ابن خمس سنين أو نحوها. وبويع بالملك بعد والده وهو ابن ثمان عشرة سنة. وكان شابًّا مليحًا كريمًا، فيه عَدلٌ ولين وإحسان إلى الرعيَّة، ليس في طبعه ظلمٌ ولا عسف، بل يحب الخير وفعله. وكان محببا إلى الرعية، لكنه شاب غِرٌّ لم يحمِلْ أعباء الملك، وعجز"},{"id":2737,"era":"c7","t":"غزو الفرنج لمعاونتهم التتار .","s":"خرج الأميرُ بدر الدين بكتاش النجمي إلى حمص مجردًا، وخرج الأمير علاء الدين أيدكين البندقداري  الصالحي لحفظ الساحل من الفرنج، وكتب السلطان قلاوون إلى الأمير سيف الدين بلبان الطباخي نائب حصن الأكراد بغزو الفرنج بالمرقب؛ لمساعدتهم التتارَ عند وصولهم حلب، فجمَعَ التركمان وغيرَهم، وحمل المجانيق والآلات، ونازل المرقَبَ، فانهزم المسلمون ونهَبَهم الفرنج، وعَدِمَ من المسلمين مقدارُ مائتي فارس وراجل، فكبُرَ "},{"id":2738,"era":"c7","t":"الأمير شمس الدين سنقر الأشقر يستولي على دمشق .","s":"لما كان يوم الجمعة الرابع والعشرين من ذي القعدة سنة 678هـ ركب الأمير شمس الدين سنقر الأشقر من دار السعادة بعد صلاة العصر وبين يديه جماعة من الأمراء والجند مشاة، وقصد باب القلعةِ الذي يلي مدينة دمشق، فهجم منه ودخل القلعة واستدعى الأمراء فبايعوه على السلطنة، ولُقِّبَ بالملك الكامل، وأقام بالقلعة ونادت المنادية بدمشق بذلك، فلما أصبح يومَ السبت استدعى بالقضاة والعلماء والأعيان ورؤساء البلد إلى مسجد أب"},{"id":2739,"era":"c7","t":"قتال عسكر مصر لسنقر الأشقر بعد استيلائه على دمشق .","s":"لما أعلن سنقر الأشقر نفسَه سلطانًا في دمشق كتب إلى الأمير عز الدين الأفرم وهو بالكرك يعتذر عن قيامِه بما كَلَّف به السلطان في الكرك، وأتبع الكتابَ بعسكر، فلما ورد كتابه جهزه الأفرم إلى السلطان قلاوون بمصر، فكتب السلطانُ عند وروده إلى الأشقر يقَبِّحُ فعله، وكتب أمراءُ مصر إليه بذلك، ويحثُّونه على الإذعان وترك الفتنة، وسار بالكتُبِ بلبان الكريمي، فوصل دمشقَ في ثامنه، وخرج سنقر الأشقر إلى لقائه وأكرم"},{"id":2740,"era":"c7","t":"وفاة الأمير سيف الدين أبي بكر بن أسبهسلار والي شرطة مصر .","s":"هو الأمير سيف الدين أبو بكر بن أسبهسلار وقد ولي شرطةَ مِصرَ عِدَّةَ سنين، وكان موصوفًا بالكرم المفرط، خيِّرًا في أموره، يشكُره الناس, وكان ممن زاد به السِّمَن– زيادة الوزن- حتى قاسى منه شِدَّة، وأشار عليه الطبيب بعدم النوم على جنبٍ، وبقي مدة لا يرمي جنبَه إلى الأرض خوفًا من أن يغرق في النومِ فيموت. مات في ربيع الآخر من هذه السنة، ودُفِنَ في القرافة."},{"id":2741,"era":"c7","t":"المغول يزحفون نحو إمارة حلب المملوكية .","s":"ورد الخبر بمسير التتار إلى البلاد الشامية وذلك لما بلغهم من حصول الاختلاف بين المسلمين، وافترق التتار ثلاث فرق: فرقة سارت من جهة بلاد الروم ومقدمهم صمغار وتنجي وطرنجي، وفرقة من جهة الشرق ومقدمهم بيدو بن طوغاي بن هولاكو وبصحبته صاحب ماردين، وفرقة فيها معظم العسكرِ وشِرارُ المغول ومقدَّمُهم منكوتمر بن هولاكو، فخرج من دمشقَ الأميرُ ركن الدين إياجي على عسكر، وانضم مع العسكر المحاصر لشيزر، وخرج من القا"},{"id":2742,"era":"c7","t":"وفاة أبغا بن هولاكو المغولي وقيام أخيه تكدرا بالملك وإسلامه .","s":"هو ملك التتار، وصاحِبُ العراق والجزيرة وخراسان وغير ذلك، أبغا بن هولاكو بن تولي بن جنكيزخان, ويقال: اسمه أباقا، كان مقدامًا شجاعًا، عالي الهمة، لم يكن في إخوتِه مِثلُه، وهو على دينِ التتار لم يدخل في الإسلام، وكان ذا رأيٍ وحزم وخبرةٍ بالحرب، ولما توجَّه أخوه منكوتمر بالعساكِرِ إلى الشام لم يكن ذلك بتحريضِه، بل أشير عليه فوافق. قال الذهبي: \"كان كافِرَ النفس، سفاكًا للدماء، قتل في الروم خلقًا كثيرًا"},{"id":2743,"era":"c7","t":"الهدنة بين الفرنج والسلطان قلاوون .","s":"سار السلطان قلاوون من ظاهر القاهرة فأتته رسلُ الفرنج وهو بمنزلة الروحا في تقريرِ الهدنة، فتقَرَّرَت بين مقدم بيت الإسبتار وسائر الإسبتارية بعكا، وبين السلطان وولده الملك الصالح لمدة عشر سنين وعشرة أشهر وعشرة أيام وعشر ساعات، أولُها يوم السبت الثاني والعشرين من المحرم، وتقررت الهدنة أيضًا مع متملك طرابلس الشام بيمند بن بيمند لمدة عشر سنين، أولها السابع والعشرين شهر ربيع الأول، وعادت الرسل، وتوجه ال"},{"id":2744,"era":"c7","t":"ثورة العشير من الحورانية ونهبهم لغزة .","s":"ثار العشير من الحورانية ونهبوا مدينة غزة، وقتلوا خلقًا كثيرًا وأفسدوا، فبعث السلطانُ قلاوون الأمير علاء الدين أيدكين الفخري على عسكرٍ مِن دمشق، وخرج من القاهرةِ الأمير شمس الدين سنقر البدوي على عسكر لتأديبِهم"},{"id":2745,"era":"c7","t":"هزيمة التتار على يد السلطان المنصور قلاوون في حمص .","s":"ورد الخبر بدخول منكوتمر أخي أبغا بن هولاكو بن طلوي بن جنكيزخان إلى بلاد الروم بعساكر المغول، وأنه نزل بين قيسارية والأبلستين، فبعث السلطان قلاوون الكشافة، فلقوا طائفةً من التتار أسروا منهم شخصًا وبعثوا به إلى السلطان، فقَدِمَ إلى دمشق في العشرينَ مِن جمادى الأولى، فأتاه السلطانُ ولم ينزل به حتى أعلَمَه أن التتار في نحو ثمانين ألفًا، وإنهم يريدونَ بلاد الشام في أول رجب، فشرع السلطانُ في عرض العساكر"},{"id":2746,"era":"c7","t":"ثورة ابن أبي عمارة في تونس .","s":"ثار على إبراهيم بن زكريا بن يحيى الثاني أمير الحفصيين في تونس رجل يدعى أحمد بن مرزوق يعرف بابن أبي عمارة الذي قوي أمره، حتى تنازل إبراهيم لابنه أبي فارس أمير مدينة بجاية من قبل أبيه فلقب نفسه بالمعتمد وسار إلى قتال ابن أبي عمارة غير أنه هزم وقُتِلَ، فما كان من أبيه إلا أن هرب باتجاه تلمسان فأدركه بعض أتباع ابن أبي عمارة فحُمِلَ إلى بجاية وقُتِلَ فيها عام 683هـ."},{"id":2747,"era":"c7","t":"بعض أخبار بني مرين والأندلس .","s":"قام سانشو بن ملك قشتالة بالخروج على أبيه لينتزع منه الملك، فاستنجد الملك ألفونسو بأبي يوسف يعقوب بن عبد الحق سلطان بني مرين بالمغرب فأنجده بمال يستعين به على حشد الجنود، كما اجتاز السلطان بنفسِه البحر إلى الأندلس فأغار على أراضي قشتالة وحاصر قرطبة وغزا طليطلة، أمَّا أمير غرناطة أبو عبد الله محمد بن نصر بن الأحمر فأراد أن يصانع سانشو فزحف على المنكب التي كانت تحتلها قوات بني مرين؛ مما اضطر السلطان "},{"id":2748,"era":"c7","t":"وفاة قاضي القضاة شمس الدين بن خلكان .","s":"قاضي القضاة شمس الدين أبو العباس أحمد بن محمد بن إبراهيم بن أبي بكر بن خَلِّكان البرمكي الأربلي الشافعي، ولد بإربل سنة 608, وكان فاضلًا بارعًا متفننًا كريمًا جوادًا ممدوحًا فيه ستر وحِلمٌ وعفو، وعارفًا بالمذهب حسن الفتاوى جيد القريحة بصيرًا بالعربية علَّامة في الأدب والشعر وأيام الناس، كثيرَ الاطلاع حلو المذاكرة وافِرَ الحرمة، فيه رياسة كبيرة، قدم الشام في شبيبته, ودخل مصرَ وسكنها مدَّةً وتأهل بها"},{"id":2749,"era":"c7","t":"أخذ قلعة قطيبا من التتار وقلعة كختا من النصارى .","s":"في خامس المحرم خرجت تجريدة -الجريدة خَيْلٌ لا رَجَّالة فيها - من قلعة كركر إلى حصار قلعة قطيبا إحدى قلاع آمد، فأخذوها من أيدي التتار، وأقيم فيها الرجالُ وعملت بها الأسلحة والغلال، فصارت من حصون الإسلام المنيعة، وأخذت أيضًا قلعة كختا من النصارى بسؤال أهلها، فتسَلَّمَها أمراء السلطان قلاوون، بمدينة حلب، وشحنت بالأسلحة وغيرها، وصارت مسلطة على الأرمن."},{"id":2750,"era":"c7","t":"قتال مع الأرمن عند باب إسكندرونة .","s":"غارت عساكر المسلمين على بلاد الأرمن، ووصلوا إلى مدينة أياس وقتلوا ونهبوا وحرقوا، واقتتلوا مع الأرمن عند باب إسكندرونة وهزموهم إلى تل حمدون، وعادوا سالمين ظافرين بالغنائم."},{"id":2751,"era":"c7","t":"قتال المسلمين مع فرنج قبرص ببيروت .","s":"حين قصد الفرنج قبرص بلاد الساحل، قاتلهم المسلمون فردوهم عن دخول الساحل، وأسروا منهم زيادة على ثمانين رجلًا، وأخذت منهم غنائم كثيرة."},{"id":2752,"era":"c7","t":"وصول رسل صاحب بلاد سيلان من الهند إلى السلطان قلاوون .","s":"وصولُ رسل صاحب بلاد سيلان من أرض الهند واسمه أبو أنكيه بكتابه، وهو صحيفة ذهب عرض ثلاثة أصابع في طول نصف ذراع بداخلها شيء أخضر يشبه الخوص، إلى السلطان قلاوون بمصر مكتوب فيه بقلم لم يوجد في القاهرة من يحسن قراءته، فسئل الرسل عنه فقالوا \" إنه يتضمن السلام والمحبة وإنه ترك صحبة صاحب اليمن وتعلق بمحبة السلطان، ويريد أن يتوجه إليه رسول، وذكر أن عنده أشياء عدها من الجواهر والفيلة والتحف ونحوها، وأنه عبأ "},{"id":2753,"era":"c7","t":"هدنة بين السلطان قلاوون وبين الفرنج .","s":"جرت الهدنة بين السلطان قلاوون وبين الفرنج بعكا مدة عشر سنين."},{"id":2754,"era":"c7","t":"خروج أرغون بن أبغا المغولي على عمه أحمد سلطان .","s":"خرج أرغون بن أبغا على عمه تكدار المسمى أحمد سلطان بخراسان، فسار إليه وهزمه ثم أسره، فقامت الخواتين مع أرغون، وسألن الملك تكدار أحمد في الإفراج عنه وتوليته خراسان، فلم يرضَ بذلك، وكانت المغول قد تغيرت على تكدار، لكونه دخل في دين الإسلام وإلزامه لهم بالإسلام، فثاروا وأخرجوا أرغون من الاعتقال، وطرقوا ألناق نائب تكدار ليقتُلوه ففَرَّ منهم فأدركوه وقتلوا تكدار أيضًا في العام التالي، وأقاموا أرغون بن أب"},{"id":2755,"era":"c7","t":"وفاة شهاب الدين عبد الحليم بن تيمية والد شيخ الإسلام .","s":"هو شهاب الدين عبد الحليم بن الشيخ الإمام العلامة مجد الدين عبد السلام أبي البركات بن عبد الله بن أبي القاسم بن تيمية الحراني، والد تقي الدين شيخ الإسلام ابن تيمية، مفتي الفرق، الفارق بين الفرق، كان له فضيلة حسنة، ولديه فضائل كثيرة، وكان له كرسي بجامع دمشق يتكلم عليه عن ظاهر قلبهِ، وولي مشيخةَ دار الحديث السكَّرية بالقصاعين، وبها كان سكَنُه، كان إمامًا في المذهب الحنبلي وَلِيَ القضاء على كُرهٍ، ثم "},{"id":2756,"era":"c7","t":"انقسام دولة بني حفص في تونس .","s":"بعد خروج ابن أبي عمارة على دولة الحفصيين بتونس خلع أميرَها إبراهيم بن زكريا الحفصي وبويع أبو حفص عمر الأول بن يحيى بن عبد الواحد الحفصي، أما أبو زكريا يحيى بن أبي إسحاق فقد استقَلَّ بمدينة بجاية وقسطينة وبونة، وأقام دولة لهم بالمغرب الأوسط واتخذَ مِن بجاية عاصمةً له."},{"id":2757,"era":"c7","t":"وفاة ابن مودود الموصلي الفقيه الحنفي .","s":"هو الإمام العالم المصَنِّف الفقيه الحنفي أبو الفضل عبد الله بن محمود بن مودود الموصلي، ولد بالموصل سنة 599هـ (1203م) له أصحاب وحلقة أشغال، ومن مصنفاته: \"المختار في الفتوى\" و\"الاختيار لتعليل المختار\" و\"الوقاية\" و\"شرح الجامع الكبير للشيباني\"، تولى قضاء الكوفة فترة، ثم استقَرَّ في بغداد يفتي ويدرس في مسجد الإمامِ أبي حنيفة. قال ابن الفوطي: \"كان عالمًا بالفقه والخلاف والأصول، سمع الكثيرَ في صباه وألحق"},{"id":2758,"era":"c7","t":"تحرك الفرنج لأخذ الشام .","s":"ورد الخبر بحركة الفرنج لأخذ الشام، فتجَهَّز السلطان قلاوون الألفي للسَّفَر وركب بعساكِرِه في يوم الأحد ثامن جمادى الأولى، وتوجه من قلعة الجبل إلى دمشق، وفي يوم السبت ثاني عشر جمادى الآخرة دخل السلطان إلى دمشق، فقدم القصاد من بلاد التتار بقتل أحمد تكدار بن هولاكو ملك التتار المسلم وولاية ابن أخيه أرغون بن أبغا."},{"id":2759,"era":"c7","t":"قتال الشريف أبو نمي بسبب أخذه الضرائب من حجاج اليمن .","s":"طردَ الشَّريفُ أبو نمي جند اليَمَن واستبدَّ بها، وكان من خبَرِه أن مكة كانت بينه وبين قتادة، وكان يؤخَذُ من حاج اليمنِ على كل جمل مبلغ ثلاثين درهمًا، ومن حاج مصر على الجمل مبلغ خمسين درهمًا مع كثرة النهب والعسف في جباية ما ذكر، فما زال الظاهر بيبرس حتى صار يؤخَذُ من حاج مصر مبلغ ثلاثين درهمًا على كل جمل، فجرَّد المظفر صاحب اليمن إلى مكة عسكرًا عليه أسد الدين جغريل، فمَلَكَها بعد حرب، فجمع قتادة وأ"},{"id":2760,"era":"c7","t":"وفاة الملك المنصور ناصر الدين محمد الأيوبي صاحب حماة .","s":"هو الملك المنصور ناصر الدين محمد بن الملك المظفر تقي الدين عمر بن شاهنشاه بن نجم الدين أيوب بن شاذي، صاحب حماة. ولد سنة 630، وتملك حماة سنة ثنتين وأربعين، وله عشر سنين، فمكث في الملك أزيد من أربعين سنة، وكان له بر وصدقات، وقد أعتَقَ في مرض موته خلقًا من الأرقاء. توفي يوم عاشر شوال بحماة وقام في الملك بعده ولده الملك المظفر بتقليد الملك المنصور له بذلك."},{"id":2761,"era":"c7","t":"أرغون المغولي يعتنق البوذية ويخطط لحرب المسلمين واستعانة بالبابا .","s":"اعتنق أرغون البوذية- هو الذي خرج على عمه تكودار أحمد وقتله- وأرسل إلى البابا أربع سفارات يطلب منه إرسال حملة صليبية إلى مصر على أنه سيقوم هو بغزو الشام؛ حتى يُحكِموا قبضَتَهم على المسلمين، ولكن البابا لم يجِبه بشيء."},{"id":2762,"era":"c7","t":"وفاة أبي البقاء الرندي .","s":"هو العلامة أثير الدين أبو البقاء صالح بن يزيد بن صالح بن علي بن موسى بن أبي القاسم بن شريف النفزي الرندي من قبيلة نفزة البربرية أبو الطيب، شاعر أندلسي من أهل رندة من جزيرة الأندلس، ولِدَ برندة سنة 601, وهو من القضاة، وله علمٌ بالحساب والفرائض، وهو أحد الأدباء المجيدين من أهل الأندلس. أقام بمالقة شهرًا، وأكثر الترددَ إلى غرناطة يسترفد ملوكَها، قال عنه أبو عبد الله محمد المراكشي في الذيل والتكملة: \""},{"id":2763,"era":"c7","t":"فتح المسلمين حصن المرقب وتحرير أسارى المسلمين .","s":"سافر السلطان المنصور قلاوون الألفي بالعساكر المصرية والشامية فنزل المرقب، وهي قلعة حصينة تشرف على البحر بالشام، كانت بيد الإسبتارية، ففتحه الله عليهم في يوم الجمعة ثامن عشر صفر، وجاءت البشارة بذلك إلى دمشق فدُقَّت البشائر وزُينت البلد وفرح المسلمون بذلك؛ لأن هذا الحصن كان مضرة على المسلمين، ولم يتَّفِق فتحه لأحد من ملوك الإسلام لا للملك صلاح الدين، ولا للملك الظاهر بيبرس، وفتح حوله بلنياس ومرقب وه"},{"id":2764,"era":"c7","t":"وفاة الأمير علاء الدين أيدكين البندقدار الصالحيّ. .","s":"هو الأمير الكبير أيدكين علاء الدين البندقدار الصالحي أستاذ الملك الظاهر بيبرس وإليه ينسب. كان من كبار الأمراء الصالحية وكان عاقلًا ساكنًا. كان مملوكًا للأمير جمال الدين موسى بن يغمور ثم انتقل إلى الصالح نجم الدين فجعله بندقداره,  ثم غضب الملك الصالح نجم الدين أيوب على أيدكين وصادره، وأخذ منه مماليكَه وكان منهم بيبرس البندقداري، وأضافه إليه لشهامتِه ونهضته، فتقدَّمَ بيبرس عنده على خشداشيته – زملائه"},{"id":2765,"era":"c7","t":"وفاة الشاعر حازم القرطاجني  .","s":"هو الشاعر والناقد أبو الحسن حازم بن محمد بن حازم الأنصاري القرطاجني. ولد سنة 608هـ )1211م) في قرطاجنة وإليها نسب، ونشأ في أسرة ذات علم ودين، فأبوه كان فقيهًا عالِمًا، تولى والده قضاء قرطاجنة أكثر من أربعين عامًا، وقد عني بولده حازم فوجهه إلى طلب العلم مبكرًا. وبعد أن سقطت قرطاجنة ومرسية في أيدي القشتاليين للمرة الأولى سنة 640هـ (1243م) غادر عدد كبير من العلماء والأدباء الأندلس، ووجهوا شطرهم إما إل"},{"id":2766,"era":"c7","t":"وفاة السلطان المنصور يعقوب المريني .","s":"هو السلطان المنصور أبو يوسف يعقوب بن عبد الحق بن محبو بن حمامة المريني مؤسس دولة بني مرين ببلاد المغرب بين فكيك وملوية. ولد بالمغرب سنة 609 وقد تولى قيادة بني مرين سنة 653 بعد وفاة أخيه أبي بكر بن عبد الحق, وتلقب يعقوب بالمنصور. وكان شجاعًا صوامًا قوامًا مجاهدًا مقرِّبًا لأهل الصلاح والخير والعلم. خرج على أبي دبوس آخر حكام الموحدين وقتله، واستولى على مملكة المغرب، فقضى على دولة آل عبد المؤمن الموح"},{"id":2767,"era":"c7","t":"وقعة بين بلبان الطباخي نائب حصن الأكراد وبين أهل المرقب .","s":"كانت وقعةٌ بين الأمير بلبان الطباخي أحد مماليك المَلِك المنصور، ونائِبِه بحصنِ الأكراد وبينَ أهلِ حصنِ المرقب، بسَبَبِ أخذِهم قافلةَ تجارةٍ قُتِلَ فيها عِدَّةٌ من مماليك بلبان، وجُرِحَ هو في كَتِفِه، فاستأذنَ بلبان السُّلطان في الإغارةِ على بلَدِ المرقب، لِما اعتمده أهلُه من الفساد عند وصول التتر إلى حلب، فأذِنَ له السلطان في ذلك، فجمع بلبان الطباخي عساكرَ الحصون، وسار إلى المرقَب، ولم يزَلْ عليه "},{"id":2768,"era":"c7","t":"وفاة القاضي البيضاوي .","s":"هو القاضي الإمامُ العلَّامة ناصرُ الدين عبدُ الله بنُ عمر الشيرازي البيضاوي، قاضيها وعالمُها وعالمُ أذربيجان وتلك النواحي، ولِدَ في البيضا من فارس، تولى قضاء شيراز ثم رحل إلى تبريز، اشتهر بعلمِه فقد كان بارعًا في الأصول والفقه والكلام والنحو، ومن مصنفاته: منهاج الوصول إلى علم الأصول، وهو مشهور، وقد شرحه غيرُ واحد، وشرْح التنبيه في أربع مجلدات، والغاية القصوى في دراية الفتوى، وشرح المنتخب، والكافية"},{"id":2769,"era":"c7","t":"أخذ السلطان قلاوون الكرك من الملك المسعود بن الظاهر بيبرس .","s":"سار الأميرُ حُسام الدين طرنطاي نائبُ السلطنة بعسكَرٍ كثيفٍ إلى الكرك، فتلَقَّاه عسكَرُ دِمشقَ صحبة الأمير بدر الدين الصوابي، فتوجَّهَ معه إليها، وضايقَها وقطَعَ الميرةَ عنها حتى بعث المَلِكُ المسعود بن الظاهر بيبرس أخاه خضر يطلبُ الأمان، فبعث إليه السلطانُ قلاوون الأميرَ ركن الدين بيبرس الدوادار من قلعة الجبل بالأمانِ، فنزل الملك المسعود وأخوه بدر الدين سلامش إلى الأميرِ طرنطاي في خامس صفر، واستقَ"},{"id":2770,"era":"c7","t":"مطر عظيم بالمدينة يخرب المسجد النبوي وجراد يهلك الزرع .","s":"أُمطِرَت المدينةُ النبويَّةُ في ليلة الرابع من المحرم مطرًا عظيمًا فوكَفَت سقوفُ المسجِدِ النبوي والحُجرة الشريفة، وخَربت عدَّةُ دُورٍ وتَلِفَ نخلٌ كثيرٌ من السيولِ، ثم عقب ذلك جرادٌ عظيمٌ صار له دويٌّ كالرعد، فأتلف التَّمرَ وجريد النخلِ وغيرَه من المزارع، وكانت الأعينُ قد أتلَفَها السيلُ، وخَرَّبَ عين الأزرق حتى عادت مِلحًا أُجاجًا، فكتب بذلك إلى السُّلطانِ قلاوون، وأنَّ الحُجرةَ الشَّريفةَ عادتُ"},{"id":2771,"era":"c7","t":"استرجاع حصن صهيون في اللاذقية .","s":"توجَّه الأميرُ حُسام الدين طرنطاي نائبُ السُّلطة على عسكرٍ كثيرٍ لقتالِ الأمير شمسِ الدين سنقر الأشقر بصهيون، وسَبَبُ ذلك أنَّ السُّلطانَ لَمَّا نازَل المرقب وهي بالقربِ من صهيون، لم يحضُرْ إليه سنقر الأشقر، وبعث إليه ابنَه ناصرَ الدين صمغار، فأسَرَّها السلطانُ في نفسِه، ولم يمكِّنْ صمغار من العودِ إلى أبيه وحَمَله معه إلى مصر، واستمَرَّ الحالُ على ذلك حتى هذه السنة، فسار طرنطاي ونازل صهيونَ حتى ب"},{"id":2772,"era":"c7","t":"غزو بلاد النوبة .","s":"في سادس ذي الحجة توجَّه الأميرُ عَلَم الدين سنجر المسروري المعروف بالخياط متولي القاهرة، والأميرُ عز الدين الكوراني، إلى غزوِ بلاد النوبة، وجرَّدَ السلطانُ قلاوون معهما طائفةً مِن أجناد الولايات بالوجهِ القبلي والقراغلامية، وكتب إلى الأمير عز الدين أيدمر السيفي السلاح دار متولِّي قوص أن يسيرَ معهما بعُدَّته ومن عنده من المماليك السلطانية المركزين بالأعمال القوصيَّة، وأجناد مركز قوص، وعُربان الإقلي"},{"id":2773,"era":"c7","t":"نقض الفرنج بطرابلس الهدنة .","s":"نقض الفرنجُ بطرابلس الهدنةَ، عندما أخذوا جماعةً مِن التجارِ وغَيرهم، وصار بأيديهم عدَّةُ أسرى، وكانوا لَمَّا مَلَك السلطانُ قَلعةَ المرقب قد بعثوا إليه هديةً، وصالحوه على ألَّا يتركوا عندهم أسيرًا، ولا يتعَرَّضوا لتاجرٍ ولا يقطعوا الطريقَ على مسافرٍ، فتجهَّزَ السلطان قلاوون لأخذ طرابلسَ."},{"id":2774,"era":"c7","t":"وفاة الإمام النحوي بدر الدين محمد بن مالك .","s":"هو الإمامُ البليغُ النَّحوي بدرُ الدين أبو عبدِ اللهِ محمَّدُ بنُ محمد بن الإمام العلامة الأوحد جمال الدين عبد الله بن مالك، الإمامُ البليغ النحوي بدر الدين ابن الإمام العلامة جمال الدين الطائي الجياني ثم الدمشقي شارح الألفية التي لأبيه، وهو من أحسَنِ الشروحِ وأكثَرِها فوائد، كان إمامًا ذكيًّا فَهِمًا حادَّ الخاطر، إمامًا في النحو والمعاني والبيان والبديع والعروض والمنطق، جَيِّدَ المشارَكةِ في الف"},{"id":2775,"era":"c7","t":"غزو دنقلة من بلاد النوبة .","s":"كتب السلطان قلاوون إلى الأكابر ببلاد السند والهند والصين واليمن والنوبة صورةَ أمان لمن اختار الحضورَ إلى ديار مصر وبلادِ الشام، من إنشاءِ فَتحِ الدين بن عبد الظاهر، وسيَّرَه مع التجار، وفي أول جمادى الأولى ورَدَت كتب الأمير علم الدين سنجر المسروري الخياط من دنقلة (من بلاد النوبة)، بفتحها والاستيلاءِ عليها وأسرِ مُلوكها، وأخْذِ تيجانهم ونسائِهم، وكان الكِتابُ على يد ركن الدين منكورس الفاقاني، فخلع "},{"id":2776,"era":"c7","t":"وفاة ولي العهد الملك الصالح علاء الدين بن الملك المنصور قلاوون  .","s":"هو المَلِكُ الصالح علاءُ الدين ابن الملك المنصور قلاوون وَليُّ العهدِ توفِّيَ في يوم الأحد خامس عشر من رجب خرج السلطان مبرزًا بظاهر القاهرة يريد الشامَ، فركب معه ابنه الملك الصالح ثمَّ عاد الصالح إلى قلعة الجبل آخِرَ النهار، فتحَرَّك عليه فؤاده في الليلِ وكَثُرَ إسهاله الدموي وأفرط، فعاد السلطانُ لعيادته في يوم الأربعاء الثامن عشر ولم يُفِدْ فيه العلاج، فعاد السلطانُ إلى الدهليز من يومِه، فأتاه ال"},{"id":2777,"era":"c7","t":"ولاية العهد الأشرف صلاح الدين خليل بن قلاوون بعد وفاة أخيه .","s":"فوَّضَ السلطانُ قلاوون ولايةَ العهدِ لابنه المَلِك الأشرف صلاحِ الدين خليل بعد وفاة أخيه ولي العهد المَلِك الصالح علاء الدين، فركِبَ بشعار السَّلطنة من قلعةِ الجبل إلى باب النصر، وعبَرَ إلى القاهرة وخرج من بابِ زويلة، وصَعِدَ إلى القلعة وسائِرُ الأمراء وغيرُهم في خدمته، ودُقَّت البشائر، وحَلَف القضاةُ له وجميع العسكر، وخلع على سائرِ أهل الدولة، وخُطِبَ له بولاية العهد، واستقَرَّ على قاعدة أخيه الص"},{"id":2778,"era":"c7","t":"وفاة الطبيب ابن النفيس .","s":"هو العلَّامةُ علاء الدين علي بن أبي الحزم القرشي الدمشقي شيخُ الأطباء في عصرِه المعروف بابن النفيس، الحكيمُ في فَنِّه، لم يكُنْ في عصره من يضاهيه في الطبِّ والعلاج والعِلم، اشتغل على المهذَّب حتى برع، وانتهت إليه رياسةُ فَنِّه في زمانه، وهو صاحِبُ التصانيفِ المفيدة، منها: الشامِلُ في الطب، والمهَذَّب في الكحل، والموجز، وشرح القانون لابن سينا، وكانت تصانيفُه يُملِيها من ذهنه ولا يحتاجُ فيها إلى مرا"},{"id":2779,"era":"c7","t":"فتح السلطان قلاوون قلاعًا كثيرة بناحية حلب .","s":"فُتِحَت قلاعٌ كثيرة بناحية حلب كركر وتلك النواحي، وكُسِرَت طائفة من التتر هناك، وقُتِلَ مَلِكُهم خربندا نائبُ التتار على ملطية."},{"id":2780,"era":"c7","t":"السلطان قلاوون يحرر إمارة طرابلس من الصليبيين .","s":"خرج السلطانُ قلاوون من دمشق إلى طرابلس فنازلها، وقد قَدِمَ لنجدة أهلِها أربعة شوان- سفن حربية كبيرة- من جهةِ متمَلِّك قبرص، فوالى السلطانُ الرميَ بالمجانيق عليها والزَّحفِ والنُّقوب في الأسوار، حتى افتَتَحها عَنوةً في الساعة السابعة من يوم الثلاثاء رابع ربيع الآخر، بعدما أقام عليها أربعة وثلاثين يومًا، ونصب عليها تسعةَ عشر منجنيقًا، وعَمِلَ فيها ألف وخمسمائة نفسٍ من الحجَّارين الزرَّاقين- رُماة ال"},{"id":2781,"era":"c7","t":"وفاة الملك المنصور شهاب الدين محمود .","s":"هو الملك المنصور شهاب الدين محمود بن الملك الصالح إسماعيل بن الملك العادل. وقد توفِّيَ يوم الأربعاء ثامن عشر شعبان، وصلي عليه بالجامع الأموي، ودفِنَ مِن يومِه."},{"id":2782,"era":"c7","t":"فتح مدينة دنقلة من بلاد النوبة .","s":"جرَّد السلطان قلاوون الأميرَ عِزُّ الدين أيبك الأفرم أمير جاندرا إلى بلاد النوبة، ومعه من الأمراء قبجاق المنصوري وبكتمر الجوكندار، وأيدمر والي قوص، وكثير من الأمراء، وسائرُ أجناد المراكز بالوجه القبلي، ونواب الولاة، ومن عُربان الوجهين القبلي والبحري عدة أربعين ألف راجل، ومعهم متمَلِّك النوبة وجريس، فساروا في ثامن شوال، وصَحِبَتهم خمسمائة مركب ما بين حراريق ومراكب كبار وصغار تحمِلُ الزاد والسلاح وا"},{"id":2783,"era":"c7","t":"نهاية حكم الغوريين في الهند .","s":"كانت أسرةُ بلبن الغورية تحكُمُ تلك المناطق في الهندِ دلهي وغيرَها، وكان آخِرُ ملوكهم هو معزُّ الدين كيقباد الذي مرِضَ مرضًا شديدًا عجز الأطباءُ عن إيجاد علاجِه، فيبس أحَدُ شِقَّيه، فخرج عليه نائبُه جلال الدين فيروز الخلجي وأعلن خلعَ الطاعةِ في ظاهر المدينةِ وانضَمَّ له الأمراءُ ودخل الخلجي دلهي وقتل كيقباد بعد أن بَقِيَ في حكمه ثلاث سنوات وبضعة أشهر، وبموتِه تنتهي حكومةُ أسرة بلبان وتبدأ دولة الخل"},{"id":2784,"era":"c7","t":"أهل عكا ينقضون العهد .","s":"ثار أهلُ عكَّا بتجَّار المسلمين وقتلوهم، فغَضِبَ السلطان قلاوون وكتب إلى البلاد الشاميَّة بعَمَلِ مجانيق وتجهيزِ زردخاناة- خزنة الأسلحة- لحصارِ عكا، وذلك أنَّ الظاهِرَ بيبرس كان قد هادَنَهم، فصاروا يحمِلونَ إليه هديَّتَهم في كلِّ سَنةٍ واستمَرُّوا في حَملِها إلى الملك المنصور قلاوون، إلَّا أنهم كثُرَ طَمَعُهم وفسادُهم وقَطعُهم الطريقَ على التجار، فأخرج لهم السلطانُ قلاوون الأميرَ شمس الدين سنقر ال"},{"id":2785,"era":"c7","t":"غزو بلاد الصعيد .","s":"سار الأميرُ طرنطاي النائبُ إلى بلاد الصعيد ومعه عسكرٌ كبيرٌ، فوصل إلى طوخ تجاهَ قوص، وقَتَل جماعةً من العربان، وحرق كثيرًا منهم بالنار، وأخذ خيولًا كثيرة وسلاحًا ورهائنَ مِن أكابرهم، وعاد بمائة ألف رأسٍ مِن الغنم، وألفٍ ومائتي فرس، وألف جمل، وسلاحٍ لا يقع عليه حصرٌ."},{"id":2786,"era":"c7","t":"غزو بلاد النوبة .","s":"وصل والي قوص ممَّن معه إلى اتجاه الجزيرة التي بها عامون ملك النوبة، فرأوا بها عدة من مراكب النوبة، فبعثوا إليه في الدخولِ في الطاعةِ وأمَّنوه فلم يقبَلْ، فأقام العسكرُ تجاهه ثلاثة أيام، فخاف عامون من مجيءِ الحراريق والمراكبِ إليه، فانهزم إلى جهةِ الأبواب، وهي خارجةٌ عن مملكتِه وبينها وبين الجزيرة التي كان فيها ثلاثةُ أيام، ففارقه السواكرة وهم الأمراء وفارقه الأسقُفُ والقُسوس، ومعهم الصليبُ الفِضَّ"},{"id":2787,"era":"c7","t":"قيام الدولة الخلجية في الهند على أنقاض الدولة الغورية .","s":"الخلجيُّونَ أصلُهم من الترك الأفغانيين، وكانوا أسرةً مُحارِبةً، ظهر أمرُها من أيام الغزنويِّينَ، ويرى بعضُ المؤرخين أنَّهم ينتَسِبونَ إلى \"قليج خان\" أحدِ أصهار \"جنكيز خان\" والذي نزل بجبال الغورِ بعد هزيمة \"خوارزم شاه\"، وحرَّف اسمه بعد ذلك إلى خلج، وعُرِفَ ورثته بالخلجيون، واندمجوا في الحياةِ في \"أفغانستان\"، واعتنقوا الإسلامَ في عهد سلاطين الدولةِ الغزنوية، وضم الجيشُ الغزنوي فرقًا منهم أسهمت في فت"},{"id":2788,"era":"c7","t":"وفاة السلطان قلاوون وتولي ابنه خليل بعده .","s":"هو السلطانُ المَلِكُ المنصورُ سَيفُ الدنيا والدين، أبو المعالي وأبو الفتوح قلاوون بن عبد الله التركي الصالحيُّ النجميُّ الألفي، اشتراه المَلِكُ الصالحُ نجم الدين أيوب بألفي دينار، ولهذا يقالُ له الألفي, وكان من أكابِرِ الأمراء عنده وبعدَه، كان ملكًا عظيمًا حَسَنَ الصورة مَهيبًا، عليه أبَّهةُ السلطنة ومهابة المُلك، تامَّ القامة حَسَنَ اللِّحيةِ عاليَ الهِمَّة شجاعًا وقورًا, وكان لا يحِبُّ سَفكَ الد"},{"id":2789,"era":"c7","t":"مناوشات بين أمير مكة وحجاج مصر .","s":"حَجَّ بالنَّاسِ في هذه السنة من الشامِ الأمير بدر الدين بكتوت الدوباسي، وحَجَّ قاضي القضاة شهاب الدين بن الخوي، وشمسُ الدين بن السلعوس ومقَدَّم الركب الأمير عتبة، فتوهَّم منه أبو نُمي، وكان بينهما عداوةٌ، فأغلق أبوابَ مكَّةَ ومنع الناسَ مِن دخولِها، فأحرق البابَ وقتَلَ جماعةً ونهَبَ بعض الأماكِنِ، وجرت خطوبٌ فظيعة، ثم أرسلوا القاضيَ ابن الخوي ليصلح بين الفريقين، ولَمَّا استقر عند أبي نمي رحل الركو"},{"id":2790,"era":"c7","t":"أحوال البلاد الإسلامية مع بداية هذه السنة .","s":"استهلَّت هذه السنةُ والخليفةُ بمصرَ الحاكمُ بأمر الله أبو العباس العباسي، وسلطانُ البلادِ المَلِكُ الأشرف صلاحُ الدين خليل بن المنصور قلاوون، ونائبُه بمصر وأعمالها بدر الدين بيدرا، ووزيرُه ابن السلعوس الصاحِبُ شمس الدين، ونائبه بالشام حسامُ الدين لاجين السلحداري المنصوري، وصاحِبُ اليمن الملِكُ المظفَّر شمس الدين يوسف بن المنصور نور الدين عمر بن علي بن رسول، وصاحِبُ مكة نجم الدين أبو نمي محمد بن إد"},{"id":2791,"era":"c7","t":"وفاة الملك العادل بدر الدين سلامش بن الظاهر بيبرس .","s":"هو المَلِكُ العادِلُ بدرُ الدين سلامش بن الظاهرِ بيبرس بن عبد الله، كان قد بويع بالمُلك بعد أخيه الملِك السَّعيد، وجَعَلَ الملكُ المنصورُ قلاوونَ أتابِكَه وخطَبَ له، وضربَ السكةَ باسمه ثلاثة أشهر، ثم استقَلَّ قلاوون بالمُلكِ لصِغَرِ سِنِّ سلامش وقتَها، فلما عُزِلَ من الحكم بقي خاملًا. كان سلامش من أحسن الناسِ شَكلًا وأبهاهم منظرًا، فقد كان شابًّا مليحًا، تام الشكل، رشيق القدِّ، طويلَ الشعر، ذا حيا"},{"id":2792,"era":"c7","t":"وفاة أرغون بن أبغا بن هولاكو ملك التتار .","s":"هو أرغونُ بن أبغا ملكُ التتار, وحاكِمُ بلاد العراق وخراسان وما حولها. كان شهمًا شجاعًا سفَّاكًا للدماء، كافرًا، على دينِ قَومِه المغول؛ لذلك قتَلَ عَمَّه المسلمَ السلطان أحمد (تكدار) بن هولاكو، فعَظُمَ في أعين المغول, فلمَّا كان في هذه السنة مات من شرابٍ شَرِبَه فيه سُمٌّ، فاتهمت المغولُ اليهودَ به, وكان وزيرُه سعد الدولة بن الصفي يهوديًّا, فقتلوا من اليهودِ خلقًا كثيرًا، ونهبوا منهم أموالًا عظيمة"},{"id":2793,"era":"c7","t":"تحرير إمارة عكا من الوجود الصليبي وهي آخر معاقلهم .","s":"شرع السلطانُ الأشرفُ صلاحُ الدين خليلُ بن قلاوون في الاهتمامِ بفَتحِ عَكَّا، وبعثَ الأميرَ عِزَّ الدين أيبك الأفرم أمير جاندار إلى الشامِ لتجهيزِ أعوادِ المجانيق، فقَدِمَ دِمشقَ وجُهِّزَت أعوادُ المجانيق، وبرزت في أول ربيع الأول وتكامَلَت في الثاني عشر، وسار بها الأميرُ عَلَم الدين سنجر الدواداري أحدُ أمراء الشام، ثم فُرِّقَت على الأمراء مقَدَّمي الألوف، فتوجَّهَ كل أمير ومضافيه بما أمر بنقله منها"},{"id":2794,"era":"c7","t":"استرداد مدن الساحل من الصليبيين .","s":"بعد أن منَّ الله على المسلمينَ بفتح عكا، فُتِحَت صور وحيفا وعثليث وبعض صيدا بغيرِ قِتالٍ، وفَرَّ أهلُها خوفًا على أنفُسِهم، فتسَلَّمَها الأميرُ علم الدين سنجر الشجاعي، فقَدِمَت البشائرُ بتسليم مدينة صور في التاسع عشر، وبتسليم صيدا في العشرينَ منه، وأنَّ طائفةً مِن الفرنج عصَوا في برجٍ منها، فأمر السلطانُ بهدم صور وصيدا وعثليث وحيفا، فتوجَّه الأمير شمس الدين نبا الجمقدار بن الجمقدار لهدم صور، واتفق"},{"id":2795,"era":"c7","t":"وفاة الملك المظفر صاحب ماردين وقيام ابنه بعده بالملك .","s":"هو المَلِكُ المظَفَّر قرا أرسلان بن السعيد غازي بن المنصور أرتق بن إيلغازي بن ألبي بن تمرتاش بن إيلغازي بن أرتق، صاحِبُ ماردين بعدما ملكَ ثلاثًا وثلاثين سنة، وقام بعده ولدُه شمس الدين داود ولقِّبَ بالملك السَّعيدِ."},{"id":2796,"era":"c7","t":"فتح الملك الأشرف قلعة الروم .","s":"خرج الملِكُ الأشرَفُ مِن دمشق من يوم الاثنين سادس عشر جمادى الأولى، فدخل حَلَب في الثامن عشر، وخرج منها في رابعَ جمادى الآخرة يريدُ قلعةَ الروم فنزل عليها يومَ الثلاثاء ثامِنَه، ونصب عشرينَ منجنيقًا ورمى عليها، وعُمِلَت النقوبُ وعَمِلَ الأمير سنجر الشجاعي نائب دمشق سلسلةً وشَبَكَها في شراريفِ القلعة وأوثق طرفَها بالأرض، فصعد الأجنادُ فيها وقاتلوا قتالًا شديدًا، ففتح اللهُ القلعةَ يوم السبت حادي عش"},{"id":2797,"era":"c7","t":"كيختو ملك التتار يهدد باجتياح بلاد الشام .","s":"قَدِم رسُلُ كيختو ملك التتار بكتابِه يتضَمَّنُ أنه يريدُ الإقامة بحلب؛ فإنَّها مما فتحه أبوه هولاكو، وإن لم يُسمَحْ له بذلك أخَذَ بلادَ الشامِ، فأجابه السلطانُ بأنَّه قد وافق القان ما كان في نفسي، فإني كنتُ على عزمٍ مِن أخذ بغداد، وقَتْلِ رجاله، فإني أرجو أن أردَّها دارَ إسلامٍ كما كانت، وسينظُرُ أيُّنا يَسبِقُ إلى بلادِ صاحِبِه، وكتب إلى بلاد الشامِ بتجهيز الإقاماتِ وعرْضِ العساكِرِ."},{"id":2798,"era":"c7","t":"الملك الأشرف يقتل عددا من أمرائه .","s":"في ليلةِ أوَّلِ المحَرَّم أخرَجَ مَن في الجُبِّ مِن الأمراء، وقد كان اعتقَلَهم قبل ذلك لأمورٍ رآها منهم، ومنهم من اعتُقِلَ قبل هذا وأُطلِقَ ثمَّ اعتُقِلَ ثانيًا، وهم سنقر الأشقر وجرمك والهاروني وبكتوت وبيبرس وطقصوا ولاجين، وأمر بخَنقِهم أمامَ السلطان، فخُنِقوا بأجمعِهم حتى ماتوا، وتولى خنقَ لاجين الأميرُ قرا سنقر، فلمَّا وضع الوتَرَ في عنقِه انقطع، فقال: \"يا خوند، مالي ذنب إلا حميي طقصوا وقد هلك، "},{"id":2799,"era":"c7","t":"عقد صلح بين الملك الأشرف وبلاد سيس .","s":"ركِبَ الملِكُ الأشرف خليلُ بن قلاوون على الهجنِ في أوَّلِ جمادى الأولى ومعه جماعةٌ مِن أمرائه وخواصِّه، وسار إلى الكرك من غيرِ الدَّربِ الذي يُسلَكُ منه إلى الشام، فرَتَّب أحوالَها، وتوجَّهَ إلى دمشقَ، فقَدِمَها في تاسِعِ جمادى الآخرةِ بعد وصولِ الأميرِ بيدرا والوزيرِ بثلاثة أيام، فأمَرَ بالتجهيزِ إلى بهسنا وأخَذَها من الأرمِن أهل سيس، فقَدِمَ رسل سيس يطلبونَ العفوَ، فاتفق الحالُ معهم على تسليم به"},{"id":2800,"era":"c7","t":"وفاة الكاتب المؤرخ ابن عبد الظاهر .","s":"هو الكاتبُ المؤرِّخُ الصاحبُ محيى الدين عبد الله بن رشيد الدين عبد الظاهر بن نشوان بن عبد الظاهر السّعدىُّ الموقَّعُ كاتب الإنشاء بالديار المصريَّة، وكان من أبرع المؤرِّخين الذين ظهروا في مطالِعِ دولة المماليك البحريَّة، وكان إلى جانب كونِه مؤرِّخًا، كاتبًا صاحِبَ قَلمٍ بليغٍ أهَّلَه لأن يحتلَّ مكانةً مرموقة في الصفِّ الأوَّل من كتَّاب العربيَّة. ولد بالقاهرة في 9 محرم 620هـ (12 من فبراير 1223م) ب"},{"id":2801,"era":"c7","t":"أمطار شديدة في الشام .","s":"وقع ببعلبكَّ أمطار وسيولٌ خارجةٌ عن الحد، ففسد من كرومِها ومزارعِها ومساكِنِها ما تزيد قيمتُه على مائةِ ألفِ دينار."},{"id":2802,"era":"c7","t":"واقعة النصراني الذي شتم الرسول صلى الله عليه وسلم واستجارته بعساف بن حجي .","s":"كان هذا النَّصرانيُّ من أهل السويداء قد شَهِدَ عليه جماعةٌ أنَّه سَبَّ النبيَّ صلى الله عليه وسلم، وقد استجار هذا النصرانيُّ بعساف بن أحمد بن حجي أمير آل مري، فاجتمع شيخُ الإسلام تقي الدين ابنِ تيميَّة، والشيخ زين الدين الفارقي شيخُ دار الحديث، فدخلا على الأميرِ عزِّ الدين أيبك الحموي نائبِ السَّلطنة فكَلَّماه في أمرِه فأجابهما إلى ذلك، وأرسل ليُحضِرَه فخرجَا من عنده ومعهما خلقٌ كثيرٌ من الناس، فر"},{"id":2803,"era":"c7","t":"اغتيال السلطان الأشرف خليل بن قلاوون .","s":"هو السُّلطانُ المَلِكُ الأشرف صلاحُ الدين خليل بن السلطان الملك المنصور قلاوون الصالحي، جلس على تخت المُلك في ذي القعدة سنة 689، بعد موت والده، واستفتح المُلكَ بالجهاد، وسار فنازل عكَّا وافتتحها، ونظَّفَ الشامَ كُلَّه من الفرنج، ثم سار في السنة الثانية فنازل قلعةَ الروم وحاصَرَها خمسة وعشرين يومًا وافتتحها، ثم في السنة الثالثة جاءته مفاتيحُ قلعة بهسنا من غير قتالٍ إلى دمشق، ولو طالت مدَّتُه مَلَكَ"},{"id":2804,"era":"c7","t":"بدر الدين بيدرا يتولى السلطنة بمصر بعد قتله السلطان الأشرف .","s":"لَمَّا قَتَل بدر الدين بيدرا السلطانَ الأشرفَ بن قلاوون عاد بمن معه من الأمراء، ونزل بالدهليزِ وجلس في دست السلطة، وقام الأمراءُ فقَبَّلوا الأرضَ بين يديه وحلفوا له، وتلقَّب بالملك الأوحد وقيل المعظَّم، وقيل المَلِك القاهر، ثمَّ قبض بيدرا على الأميرِ بيسري والأميرِ بكتمر السلاح دار أمير جاندار، وقصد قتْلَهما ثم تركهما تحت الاحتياطِ لشفاعةِ الأمراء فيهما، وركب إلى الطرانة فبات بها وقد سار الأمراءُ "},{"id":2805,"era":"c7","t":"مقتل الأمراء الذين شاركوا في قتل الملك الأشرف بن قلاوون .","s":"وقع الطَّلَبُ على الأمراء الذين كانوا مع بدر الدين بيدرا في قَتلِ السلطان الأشرف، فأوَّلُ من وُجِدَ منهم الأميرُ سيف الدين بهادر رأسُ نوبة، والأميرُ جمال الدين أقش الموصلي الحاجب، فضُرِبَت أعناقُهما وأُحرِقَت أبدانُهما في المجاير ثامِنَ يوم سلطنة الناصر، ثمَّ أخذ بعدهما سبعة أمراء: وهم حسام الدين طرنطاي الساقي، ونوغاي السلاح دار، وسيف الدين الناق الساقي السلاح دار، وسيف الدين أروس الحسامي السلاح د"},{"id":2806,"era":"c7","t":"تولية الملك الناصر محمد بن قلاوون ملك مصر .","s":"لَمَّا قُتِلَ المَلِكُ الأشرَفُ صلاحُ الدين خليلُ بن قلاوون بالقُربِ مِن تروجة، وعدى الأميرُ زين الدين كتبغا والأمراء، اجتمَعَ بهم الأميرُ علم الدين سنجر الشجاعي ومن كان بالقاهرةِ والقلعة من الأمراء الصالحيَّة والمنصورية، وقرَّروا سلطنةَ الناصر محمد بن قلاوون وأحضروه وعُمُرُه تسعُ سنين سوى أشهر في يومِ السبت سادس عشر المحرم وأجلَسوه على سريرِ السلطنة، ورتَّبوا الأمير زين الدين كتبغا نائب السلطنة ع"},{"id":2807,"era":"c7","t":"وفاة الملك الحافظ غياث الدين محمد بن الملك السعيد الأيوبي .","s":"هو المَلِكُ الحافِظُ غِياثُ الدين محمَّد بن الملك السعيد معين الدين بن الملك الأمجد بهرام شاه بن المعز عز الدين فروخ شاه بن شاهنشاه بن أيوب، وُلِدَ بدمشق أو ببعلبك سنة 616 وقد سَمِعَ الحديثَ وسَمِعَ البخاريَّ من الزبيدي وحدَّث به وأجاز مروياته للشيخِ شمس الدين، وكان أميرًا جليلًا متميزًا، نسَخَ الكثيرَ بخطه المنسوب وخَلَّف عدة أولاد، وكان يحبُّ العُلَماء والفقراء. وتوفِّيَ يوم الجمعة سادس شعبان‏, "},{"id":2808,"era":"c7","t":"وباء عام ومجاعة هائلة في مصر .","s":"وقع بديار مصرَ كُلِّها وباءٌ عظيم في القاهرة ومصر، وتزايد حتى كان يموتُ فيهما كل يومٍ ألوف، ويبقي الميِّتُ مطروحًا في الأزقة والشوارع ملقًى في الممرات والقوارع اليوم واليومينِ لا يوجد من يدفِنُه، لاشتغال الأصحَّاء بأمواتِهم، والسُّقَماء بأمراضهم، وقصُرَ مَدُّ النيل فتزايد الغلاءُ واشتَدَّ البلاء، وأجدَبَت بلاد بُرقة أيضًا، وعمَّ الغلاء والقحط ممالِكَ المشرق والمغرب والحجاز، وتزايد موتُ النَّاسِ حت"},{"id":2809,"era":"c7","t":"دخول أكثر التتار الإسلام بسبب إسلام ملكهم قازان بن أرغون .","s":"ورد الخبَرُ بأن كيختو بن أبغا بن هولاكو، الذي تسلطنَ بعد أخيه أرغون في سنة تسعين، قُتِل في سنة ثلاث وتسعين، وملَك بعده ابنُ عمه بيدو، وهو ابن طرغاي بن هولاكو، فخرج عليه قازان بن أرغون بن أبغا نائبُ خراسان، وكسَرَه وأخذ المُلكَ منه، ويقال: إن قازان أسلم على يدِ الشيخ صدر الدين بن حمُّويه الجويني، وقيل: على يد نائبه الأمير توزون، ودخلَت التتار أو أكثرُهم في الإسلام، ونثر قازان الذهبَ والفضَّةَ واللؤ"},{"id":2810,"era":"c7","t":"وفاة ملك اليمن المنصور وما جرى بعده من قتال .","s":"هو المَلِكُ المظَفَّر شمس الدين أبي المظفَّر يوسف بن الملك المنصور نور الدين عمر بن علي بن رسول التركماني صاحِبُ اليمن المظفَّر صاحب اليمن. قُتِلَ أبوه وعمره ستٌّ وأربعون سنة، فقام هو بالأمر من بعده. توفِّيَ المظفَّر في شهر رمضان وكانت مُدَّةُ حُكمِه نحوَ خمسٍ وأربعين سنةً، وكانت سيرتُه جيدة، وملك بعده ابنُه الملك الأشرف ممهد الدين عمر، فنازعه أخوه المَلِك المؤيد هزبر الدين داود وجمع لقتاله، وحاصر"},{"id":2811,"era":"c7","t":"فتنة المماليك الأشرفية بمصر .","s":"في ليلةِ الأربعاءِ حادي عشر المحرم اجتمع المماليكُ الأشرفيَّة وخرجوا إلى الاسطبلات التي تحت القلعةِ، وركبوا الخيولَ ونَهَبوا ما قَدَروا عليه، وداروا على خوشداشيتهم- زملاء المهنة- فأركبوهم ومَضَوا إلى باب سعادة من أبوابِ القاهرة فأحرَقوه، ودخلوا إلى دارِ الوزارة ليُخرِجوا مَن فيها من المماليك، فلم يوافِقوهم على ذلك فتَرَكوهم، وقَصَدوا سوق السلاح بالقاهرة، وفتَحوا الحوانيتَ وأخذوا السِّلاحَ، ومضوا إ"},{"id":2812,"era":"c7","t":"خلع الملك الناصر محمد بن المنصور وسلطنة الملك العادل زين الدين كتبغا .","s":"في يومِ الأربعاءِ حادي عشر المحرم خُلِعَ المَلِكُ النَّاصِرُ بن قلاوون، وكانت أيَّامُه سَنةً واحدةً تَنقُصُ ثلاثةَ أيام، لم يكن له فيها أمرٌ ولا نهيٌ، بل كل ذلك بيَدِ السلطان الملك العادل زين الدين كتبغا المنصوري الذي كان في مُدَّة سلطنة الملك الناصِرِ هو القائِمَ بجميع أمور الدولة، وليس للناصرِ معه تصرفٌ البتة، ثمَّ إنه أخذ في أسباب السُّلطةِ بعد قتل الشجاعيِّ المنافِسِ الأوَّل لكتبغا، ولَمَّا دخ"},{"id":2813,"era":"c7","t":"وفاة السلطان جلال الدين سلطان الدولة الخلجية بالهند .","s":"هو السُّلطانُ جلالُ الدينِ فيروز شاه، مؤسِّسُ الدولة الخلجية بالهند, وكان نائبًا للمماليك, وقد وسَّعت هذه الدولةُ حُكمَ المسلمين في الهند فشَمِلت الدكنَ والبنغال وجيتور والكجرات، وقد تولى حكم الدولة علاء الدين الخلجي بعد وفاة جلال الدين. وقد زحف علاء الدين بجيشه إلى دلهي، حين جمعت زوجة جلال الدين أنصارَ زوجها، ونادت بابنِها ركن الدين إبراهيم سلطانًا خلفًا لأبيه، لكنَّ علاء الدين هاجمَ دلهي، وأجبر "},{"id":2814,"era":"c7","t":"توسع حكم المسلمين في الدولة الخلجية الهند .","s":"لما استقرَّت الأمور لعلاء الدين في الدولة الخلجية بالهند بدأ يتَّجِهُ لشؤون الدولة الحربيَّة، ويعنى بالنواحي الاجتماعيَّة، وكان سلطانًا قويًّا طموحًا، نجح في دفع الخطر المغوليِّ عن بلاده، وقاد جنده في فتوحات متَّصلة، حتى أظلَّت راية الإسلام شبهَ القارة الهندية كلَّها لأول مرة في التاريخ. ولكي يدفَعَ هجمات المغول أقام سلسلةً من الحصون على حدوده الغربية، وزوَّدها بالجند والسلاح، ولكنَّ ذلك لم يحُلْ "},{"id":2815,"era":"c7","t":"المجاعة والقحط ينتشران في مصر والشام والحجاز .","s":"استمَرَّ الحالُ على الغلاء في الأسعار بشكلٍ فاحشٍ جِدًّا وهلك معظَمُ الدوابِّ لعَدَمِ العَلَفِ، حتى لم توجَدْ دابة للكِراءِ، وهلكت الكلاب والقِطَطُ من الجوع، وانكشف حالُ كثيرٍ مِن الناس، وشَحَّت الأنفسُ حتى صار أكابِرُ الأمراء يمنعونَ مَن يدخُلُ عليهم من الأعيانِ عند مَدِّ أسمِطَتِهم، وكثُرَ تعزير محتَسِب القاهرة ومِصر لبيَّاعي لحوم الكلاب والمَيتات، ثمَّ تفاقم الأمر فأكل الناسُ الميتةَ مِن الكلاب"},{"id":2816,"era":"c7","t":"وفاة الأمير عمر الحفصي صاحب تونس وتولي أبي عصيدة بعده .","s":"هو الأميرُ أبو حفص عمر بن يحيى بن عبد الواحد بن أبي حفص ملك تونس. لمَّا استقر لأبي حفص المُلك بتونس بعد قتله أحمد بن مرزوق بن أبي عمار الذي ادَّعى أنه الفضل بن أمير المؤمنين الواثقِ بالله يحي بن محمد بن أبي زكريا. تلقَّب أبو حفص بالمستنصِر بالله أمير المؤمنين، وهو المستنصِرُ الثاني، ولما استقَرَّ في المملكة سار ابنُ أخيه يحيى بن إبراهيم بن أبي زكريا الذي سَلِمَ من المعركة إلى بجاية، وملَكَها وتلقّ"},{"id":2817,"era":"c7","t":"وفاة الملك السعيد صاحب ماردين وتولي أخيه بعده .","s":"هو المَلِكُ السعيدُ شمس الدين إيلغازي بن الملك المظفر فخر الدين قرا أرسلان بن الملك السعيد صاحِبُ ماردين الأرتقي، ودُفِنَ بتربة جده أرتق، وتولى بعده سلطنةَ ماردين أخوه الملك المنصور نجم الدين غازي، وكانت مُدَّةُ مَملكةِ الملك السعيد هذا على ماردين دونَ الثلاث سنين."},{"id":2818,"era":"c7","t":"قدوم كثير من أسر المغول إلى مصر والشام .","s":"قدم البريدُ بوصول طائفةِ الأويراتية من التتار ومُقَدَّمُهم طرغاي زوجُ بنت هولاكو، وإنَّهم نحو الثمانية عشر ألف بيت، وقد فَرُّوا من غازان ملك التتار وعبَروا الفراتَ يريدون الشام، فكتب إلى نائب الشام أن يبعَثَ إليهم الأمير علم الدين سنجر الدواداري إلى الرَّحبةِ لِيلقاهم، فخرجَ من دمشق، ثم توجَّه بعده الأميرُ سنقر الأعسر شاد الدواوين بدمشق، ووصلت أعيانُ الأويراتيَّة صُحبة سنقر الأعسر في الثالث عشر من"},{"id":2819,"era":"c7","t":"وفاة زين الدين أبي البركات بن المنجى شيخ الحنابلة .","s":"هو الإمامُ العلَّامة، مفتي المسلمين، أبو البركات زين الدين المنجي بن عثمان بن أسعد بن المنجي بن بركات بن المؤمل، التنوخي، المعرِّي الأصل، الدمشقي، شيخُ الحنابلة. ولد سنة 631. سمع الحديث وتفقَّهَ فبرع في فنون من العلمِ كثيرةٍ مِن الأصول والفروع والعربيَّة والتفسير وغير ذلك، وانتهت إليه رياسة المذهب، وصنَّف في الأصول وشرَحَ المُقنِعَ، وله تعاليقُ في التفسير, فدرَّس وأفتى وصنَّف, وتفقَّه عليه: ابن ال"},{"id":2820,"era":"c7","t":"خلع الملك كتبغا وتولي حسام لاجين ملك مصر .","s":"رحل السلطانُ كتبغا من دمشقَ بعساكِرِه يريدُ القاهرةَ، وقد توغَّرَت صدور الأمراء وتواعَدوا على الفتك به، فسار إلى أن نزل بالعوجاء قريبًا من الرملة، وحضر الأمراءُ عنده بالدهليز، فأمر بإحضارِ الأمير بيسري فطلب طلبًا حثيثًا، فلما حضَرَ لم يقُم له السلطانُ على عادته، وأغلظَ له في الكلام ونسَبَه إلى أنه كاتب التتار، فكانت بينهما مفاوضة، ثم نهض السلطانُ، وانفضَّ الأمراء وقد حَرَّك منهم ما كان عندهم كامنً"},{"id":2821,"era":"c7","t":"السلطان المخلوع كتبغا يستبد بدمشق ثم تؤخذ منه .","s":"بعد أن هرب السلطانُ العادِلُ كتبغا من حسام الدين لاجين وأمرائِه الذين حاولوا قتْلَه، كان قد قَدِمَ قبله إلى دمشق أميرُ شكاره وهو مجروح، ليُعلِمَ الأمير أغرلو نائب دمشق بما وقع، فوصَلَ في يوم الأربعاء آخر المحرم، فكثُرَ بدمشق القالُ والقيل، وألبس أغرلو العسكرَ السلاح ووقفوا خارجَ باب النصر، فوصل كتبغا في أربعةِ أنفس قبل الغروبِ وصَعِدَ القلعة، وحضر إليه الأمراءُ والقُضاة وجُدِّدَت له الأيمان، ثم أو"},{"id":2822,"era":"c7","t":"وفاة محمد بن سعيد الصنهاجي البوصيري صاحب قصيدة البردة .","s":"شرفُ الدين أبو عبد الله محمَّدُ بن سعيد بن حماد الصنهاجي البوصيري المصري، وبوصيرُ هي بين الفيوم وبني سويف بمصرَ، وُلِدَ البوصيري ببني سويف في مصرَ سنة 608 من أسرةٍ ترجع أصولُها إلى قبيلةِ صِنهاجةَ التي كانت تسكُنُ شَمالَ أفريقية, فهو شاعِرٌ صنهاجي له شعرٌ غايةٌ في الحسن واللطافة عذب الألفاظ منسجم التركيب. تنقَّل بين القدس والمدينة ومكَّة، ثم عاد إلى مصر وعَمِلَ كاتبًا في الدولةِ ثم أصبح يعلِّمُ ال"},{"id":2823,"era":"c7","t":"وفاة الغازي أرطغرل بك والد الغازي عثمان مؤسس الدولة العثمانية .","s":"هو الغازي أرطغرل بك بن سليمان شاه القايوي التركماني كان مع والده سليمانَ شاه عندما انتقلَ من موطنهم الأصلي باتجاه الغربِ على أثر الاجتياحِ التتري إلى أن غَرِقَ والده سليمان في الفراتِ فرجع أخويه سنقور تكين وكون طوغدي إلى الشرق, ومكث أرطغرل في ذلك الموضِعِ يجاهِدُ الكُفَّار، ثم أرسل ابنَه صارو بالي إلى علاء الدين السلجوقي يستأذِنُه في الدخول إلى بلادِه، ويطلب منه موضعًا ينزِلُ فيه فأذِنَ له وعَيَّن"},{"id":2824,"era":"c7","t":"خروج عساكر السلطان لاجين لاسترداد سيس من التتار .","s":"استشار السلطان حسام الدين لاجين الأمراءَ في أخذ سيس، وكان ذلك الوقتُ وقتَ اختلاف المغول، ثم عرض الجيشَ وجَرَّد في مصر تجريدةً فيها مجموعةٌ من الأمراء وكَتَب كتابًا لنائِبِ الشام سيف الدين قبجق بأن يتجَرَّد ويجَرِّدَ معه مجموعةً من الأمراء، وكتب إلى نائب طرابلس أيضًا أن يتجَرَّد بعساكرها، وإلى نائبِ حماة كذلك، وإلى نائبِ صفد فارس الدين اليكي الظاهري كذلك. فاجتمع هؤلاء مع الأميرِ سَيفِ الدين بلبان ا"},{"id":2825,"era":"c7","t":"السلطان لاجين يقر بأنه مؤقت في الملك حتى يكبر الملك الناصر .","s":"استدعى السلطانُ حسام الدين لاجين قاضيَ القضاة زينَ الدين علي بن مخلوف المالكي، وصِيَّ المَلِك الناصرِ محمد بن قلاوون، وقال له: الملِكُ الناصر ابنُ أستاذي، وأنا قائِمٌ في السلطنة كالنائِبِ عنه إلى أن يُحسِنَ القيامَ بأمرها، والرأيُ أن يتوجَّهَ إلى الكرك وأمَرَه بتجهيزِه، ثم قال السلطانُ للملك الناصر محمد بن قلاوون: لو عَلِمتُ أنَّهم يخلونَك سلطانًا واللهِ ترَكْتُ المُلكَ لك، لكِنَّهم لا يخلونه لك و"},{"id":2826,"era":"c7","t":"وفاة أحمد بن عثمان بن قايماز والد الإمام الذهبي .","s":"هو شِهابُ الدين أحمد بن عثمان بن قايماز بن الشيخ عبد الله التركماني الفارقي الأصل ثم الدمشقي الذهبي. قال الذهبي: \"والدي أحسَنَ اللهُ جزاءه ولد سنة 641 تقريبًا، وبرع في دقِّ الذَّهَب، وحصل منه ما أعتق منه خمسَ رقاب، وسَمِعَ الصحيح في سنة 666 من المقداد القيسي، وحجَّ في أواخر عمره، كان يقومُ مِن الليل\". توفِّي في آخر جمادى الأولى ليلة الجمعة، وصلى عليه الخلقُ يؤُمُّهم قاضي القضاة ابنُ جماعة."},{"id":2827,"era":"c7","t":"غزو سيس لتحريرها من الأرمن .","s":"قَدِمَ البريدُ مِن حَلَب بوقوع الخلاف بين الملك طقطاي بن منكوتمر ملك التتار وطائفة الأمير نغيه حتى قُتل منهم كثيرٌ من المغول، وانكسر طقطاي، وأنَّ غازان قَتَل وزيره نيروز وعِدَّةً ممن يلوذ به، فاتَّفق الرأي على أخذ سيس ما دام الخلافُ قائمًا بين المغول، وأن يخرُجَ الأمير بدر الدين بكتاش أميرُ سلاح ومعه ثلاثةُ أمراء وعشرةُ آلاف فارس، وكتب لنائب الشامِ بتجريد الأمير بيبرس الجالق وغيرِه من أمراءِ دِمشق"},{"id":2828,"era":"c7","t":"فتح تل حمدون ومرعش .","s":"بعد غزو سيس رحل الأمير بكتاش بجميع العساكِرِ إلى تل حمدون، فوجدوه خاليًا وقد نزح من كان فيه من الأرمن إلى قلعةِ نجيمة فتسَلَّمَها في سابع رمضان وأقام بها من يحفَظُها، وسيَّرَ الأمير بلبان الطباخي نائِبُ حلَب عسكرًا، فملكوا قلعةَ مرعش في رمضانَ أيضًا."},{"id":2829,"era":"c7","t":"تحرير قلعة نجيمة  .","s":"جاء الخبرُ إلى الأمير بكتاش وهو على تل حمدون بأن واديًا تحت قلعة نجيمة وحميص قد امتلأ بالأرمن، وأنَّ أهل قلعة نجيمة تحميهم، فبعث طائفةً مِن العسكر إليهم فلم ينالوا غرَضًا، فسَيَّرَ طائفةً ثانيةً فعادت بغير طائل، فسار الأمراءُ في عِدَّة وافرة وقاتلوا أهلَ نجيمة حتى ردُّوهم إلى القلعة، وزحفوا على الوادي وقتَلوا وأسَروا مَن فيه، ونازلوا قلعةَ نجيمة ليلةً واحدة، وسار العسكَرُ إلى الوطأة، وبقي الأميرُ "},{"id":2830,"era":"c7","t":"بعض أمراء المماليك يلجؤون إلى المغول .","s":"لَمَّا رجعت طائفةٌ مِن الجيش من بلاد سيس بسَبَبِ المرض الذي أصاب بعضَهم، فجاء كتابُ السلطان بالعَتبِ الأكيدِ والوعيد الشديد لهم، وأن الجيش يخرج جميعًا صحبةَ نائِبِ السلطنة قبجق إلى هناك، ونصَبَ مَشانِقَ لِمن تأخر بعُذرٍ أو غيره، فخرج نائبُ السلطنة الأميرُ سيف الدين قبجق وصحبته الجيوش، وخرج أهل البلد للفرجة على الأطلابِ على ما جرت به العادة، فبرز نائبُ السَّلطنة في أبَّهة عظيمة، فدعت له العامة وكان"},{"id":2831,"era":"c7","t":"تأسيس الدولة العثمانية على يد الغازي عثمان بن أرطغرل بك .","s":"كان الأميرُ علاء الدين السلجوقي قد أقطع أرطغرل جزءًا كبيرًا من الأرضِ مقابِلَ الرومِ مكافأةً له مِن جهةٍ، ومن جهةٍ أخرى يكون ردءًا له من الروم، فاستقَرَّت هذه الأسَرُ التركمانية في تلك الناحية قريبًا من بحرِ مرمرة التابع للبحر الأسودِ قريبًا من مدينة بورصة، إلى أن توفي أرطغرل سنة 697 فخَلَفَه ابنُه عثمانُ أكبَرُ أولاده، الذي حَظِيَ أيضًا بقَبولِ الأمير علاء الدين السلجوقي، ويُعَدُّ عُثمانُ هذا هو "},{"id":2832,"era":"c7","t":"اغتيال المنصور لاجين سلطان المماليك وتنصيب محمد بن قلاوون .","s":"قُتِلَ السلطانُ المَلِكُ المنصورُ حسام الدين لاجين ونائبُه سيف الدين منكوتمر، ليلةَ الجمعة حادي عشر ربيع الآخر، على يدِ الأمير سيف الدين كرجي الأشرفي ومَن وافقه من الأمراء، وذلك بحضورِ القاضي حسامِ الدين الحنفي وهو جالسٌ في خدمته يتحَدَّثان، وقيل كانا يلعبانِ بالشطرنج، فلم يشعُرا إلَّا وقد دخلوا عليهم فبادروا إلى السلطانِ بسُرعةٍ جَهرةً ليلةَ الجمعة فقَتَلوه وقُتِلَ نائبُه منكوتمر صبرًا صبيحة يوم "},{"id":2833,"era":"c7","t":"وفاة الشيخ رسلان الصوفي .","s":"هو الشيخُ الزَّاهِدُ العابدُ، رسلان بن يعقوب بن عبد الله بن عبد الرحمن الجعبري، ثم الدمشقي، صوفي مشهورٌ تعتقد فيه العامَّةٌ كراماتٍ كما هو شأنُهم في المتصَوِّفة، فنَسَبوا له الطيرانَ في الهواء وأنه ما جلس تحت شجرةٍ يابسةٍ إلَّا اخضَرَّت، بل نسب جهلةُ العوامِّ إليه أنه هو السَّبَبُ في انحسار التتار عن دمشق وأنه هو حامي البَرِّ والشام، بل إن بعُضهم إلى اليوم يذكُرُ ذلك عنه!! توفي في دمشق ودُفِنَ فيه"},{"id":2834,"era":"c7","t":"المغول يهزمون المماليك في موقعة سلمية بالشام .","s":"دارت مَعركةٌ بين \"محمود غازان\" سلطانِ الدولةِ الإيلخانية المغوليَّة, والذي أعلن هو وكثيرٌ من التتار دخولَهم في الإسلام سنة 694, و\"النَّاصر قلاوون\" سلطانُ دولة المماليك، وكانت معركةً هائلةً أسفرت عن انتصار غازان وجنودِه؛ بسَبَبِ تفَوُّقِهم في العِدَّة والعتاد، وتعَرَّض السلطانُ الناصر محمد قلاوون لمؤامرةٍ لخَلعِه, فقد تحرَّك غازان متَّجِهًا إلى بلاد الشام فقَطَع الفرات، وكانت الأخبارُ قد وصلت إلى ا"},{"id":2835,"era":"c7","t":"دخول قازان وجيشه المغول إلى دمشق .","s":"بعد أن انهزم جيشُ المماليك من التتار في موقعةِ السلمية في ربيع الأول، وبعد ما حصل لأهل دمشق من الخوفِ الشديد، زاد الأمر أنَّه في ليلة الأحد ثاني ربيع الآخر كسر المحبوسون بحَبسِ أبي الصغير الحبسَ وخرجوا منه على حميةٍ، وتفرقوا في البلدِ، وكانوا قريبًا من مائتي رجل فنَهَبوا ما قدروا عليه وجاؤوا إلى باب الجابية فكسروا أقفالَ الباب البراني وخرَجوا منه إلى بر البلد، فتفَرَّقوا حيث شاؤوا لا يقدِرُ أحد عل"},{"id":2836,"era":"c7","t":"رحيل المغول من دمشق وتركهم قبجق نائبا لهم فيها .","s":"رحل المغولُ مِن دمشق على أنَّهم سيعودون زمن الخريف ليدخلوا مصر أيضًا، وعاد سيف الدين قبجق إلى دمشقَ يوم الخميس بعد الظهر خامس عشرين جمادى الأولى ومعه الألبكي وجماعة، وبين يديه السيوفُ مُسَلَّلة وعلى رأسه عصابةٌ، فنزل بالقصر ونودي بالبَلَدِ: نائبُكم قبجق قد جاء فافتَحوا دكاكينَكم واعملوا معاشَكم، ولا يغرر أحدٌ بنفسه هذا الزَّمان والأسعارُ في غاية الغلاءِ والقِلَّة، ولما كان في أواخر الشهر نادى قبجق"},{"id":2837,"era":"c7","t":"خروج التتار من دمشق وعودتها لحكم الناصر بمصر .","s":"في ثالث رجب نودي بجامِعِ دمشق بعد الصلاةِ مِن جهة نائب القلعةِ بأنَّ العساكِرَ المِصريَّة قادِمةٌ إلى الشام، وفي عشيَّة يوم السبت رحل بولاي وأصحابُه من التتر وانشمروا عن دمشق، وقد أراح الله منهم وساروا من على عقبة دمر، فعاثوا في تلك النواحي فسادًا، ولم يأت سابع الشهر وفي حواشي البلد منهم أحدٌ، وقد أزاح الله عز وجل شَرَّهم عن العباد والبلاد، ونادى قبجق في الناسِ: قد أَمِنَت الطرقاتُ ولم يبقَ بالشَّ"},{"id":2838,"era":"c7","t":"وفاة الإمام المفتي الزاهد جمال الدين الباجربقي  .","s":"هو الإمامُ المفتي الزاهِدُ جمال الدين أبو محمد عبد الرحيم بن عبد المنعم بن عمر بن عثمان الباجربقي الموصلي الشافعي شيخٌ فقيهٌ محَقِّقٌ نقَّال طويل مهيب ساكِنٌ، كثيرُ الصلاة يلازم الجامِعَ، له حلقة تحت النسر إلى جانب البرادة، منقبض عن الناس، اشتغل بالموصل وأفاد وخطَبَ بجامِعِ دمشق نيابةً، ودرس بالغزالية نيابةً، وولي تدريس الفتحية، وحدَّث بجامع الأصول لابن الأثير عن واحد عن المصنَّف، وله نظم ونثر ووع"},{"id":2839,"era":"c7","t":"مسير الجيش الشامي برفقة شيخ الإسلام ابن تيمية إلى جبال الجرد .","s":"في يومِ الجمعة العشرين من شوَّالٍ ركِبَ نائب السلطنة جمال الدين آقوش الأفرم في جيش دمشقَ إلى جبال الجرد وكسروان (وهي من مناطق الساحل اللبناني كان يسكنُها الدروز والروافض) وخرج الشيخُ تقي الدين ابن تيميَّة ومعه خلقٌ كثير من المتطَوِّعة والحوارنة لقتال أهل تلك الناحية؛ بسبب فساد نيَّتِهم وعقائدِهم وكُفرِهم وضَلالِهم، وما كانوا عامَلوا به العساكِرَ لَمَّا كسرهم التَّتَرُ، وهربوا حين اجتازوا ببلادهم، "},{"id":2840,"era":"c7","t":"اقتتال العربان فيما بينهم بمصر .","s":"اختلف عربانُ البحيرة واقتَتَل طائفتا جابر وبرديس حتى فني بينهما بشرٌ كثير، واستظهرت برديس، فخرج الأميرُ بيبرس الدوادار في عشرين أميرًا من الطبلخاناه إلى تروجة، فانهزم العربُ منهم، فتَبِعوهم إلى الليونةِ وأخذوا جمالَهم وأغنامَهم، واستدعوا أكابِرَهم ووفَقَّوا بينهم وعادوا، فخرج الوزيرُ شمس الدين سنقر الأعسر في عدة مائة من المماليك السلطانية إلى الوجهِ القبلي لحَسمِ العربانِ، وقد كان كَثُرَ عَيثُهم و"},{"id":2841,"era":"c7","t":"تثبيت شيخ الإسلام بن تيمية للأمراء والناس في مواجهة التتار .","s":"في مستهَلِّ صَفَر وردت أخبارٌ بقَصدِ التتر بلادَ الشام، وأنهم عازمونَ على دخول مصر، فانزعج الناسُ لذلك وازدادوا ضعفًا على ضعفهم، وشرعَ الناسُ في الهرب إلى بلادِ مِصرَ والكرك والشوبك والحصون المنيعة، وجلس الشيخُ تقي الدين ابن تيمية في ثاني صفر بمجلِسِه في الجامع وحَرَّضَ الناسَ على القتال، وساق لهم الآياتِ والأحاديثَ الواردة في ذلك، ونهى عن الإسراعِ في الفرار، ورغَّبَ في إنفاق الأموال في الذَّبِّ ع"},{"id":2842,"era":"c7","t":"وقعة أهل الذمة بمصر والشام في إلزامهم بالشروط العمرية .","s":"في هذا الشَّهرِ كانت وقعةُ أهلِ الذِّمَّة، وهي أنهم كانوا قد تزايد تَرَفُهم بالقاهرة ومصر، وتفَنَّنوا في ركوب الخَيلِ المُسَوَّمة والبَغلات الرائعة بالحُليِّ الفاخرة، ولَبِسوا الثيابَ السريَّة، ووُلوا الأعمالَ الجليلة، فاتفق قدومُ وزير ملك المغرب يريدُ الحَجَّ، واجتمع بالسلطانِ والأمراء، وبينما هو تحت القلعة إذا برجلٍ راكب فرسًا وحَولَه عِدَّةٌ من الناس مشاةٌ في ركابِه، يتضَرَّعونَ له ويسألونه ويق"},{"id":2843,"era":"c8","t":"مقتل فتح الدين البققي على الزندقة بمصر .","s":"قُتِلَ الفتح أحمدُ بن البققي بالدِّيار المصريَّة في يوم الاثنين الرابعَ والعشرين من ربيع الأول، حَكَم فيه القاضي زين الدين بن مخلوف المالكي بما ثَبَت عنده من تنقيصِه للشَّريعةِ واستهزائِه بالآيات المحكماتِ، ومعارضةِ المُشتَبِهاتِ بَعضِها ببعض، فيُذكَرُ عنه أنه كان يحِلُّ المحَرَّمات من اللواطِ والخمر وغير ذلك، لمن كان يجتَمِعُ به من الفَسَقةِ من الترك وغيرِهم من الجهلة، هذا وقد كان له اشتغالٌ وهيئ"},{"id":2844,"era":"c8","t":"وفاة الخليفة العباسي الحاكم بأمر الله وتولى الخلافة ابنه أبو الربيع .","s":"هو أميرُ المؤمنينَ الخليفةُ الحاكِمُ بأمر الله أبو العباس أحمد بن المسترشد بالله الهاشمي العباسي البغدادي المصري، بويِعَ بالخلافة بالدَّولةِ الظاهرية في أول سنة 661، فاستكمل أربعينَ سنةً في الخلافة، وتوفِّيَ ليلة الجمعةِ ثامن عشر جمادى الأولى، وصُلِّيَ عليه بجامع ابن طولون، ودُفِنَ بجوار المشهد النفيسي وقتَ صلاةِ العَصرِ بسوق الخيل، وحَضَر جنازته الأعيانُ والدولةُ كُلُّهم مُشاةً، وكان قد عَهِدَ با"},{"id":2845,"era":"c8","t":"فتنة الأعراب في صعيد مصر .","s":"كثُرَ فَسادُ العُربان بالوجه القبلي، وتعَدَّى شَرُّهم في قَطعِ الطَّريقِ إلى أن فَرَضوا على التجَّار وأرباب المعايش بأسيوط ومنفلوط فرائِضَ جَبَوها شبه الجماليَّة، واستخَفُّوا بالولاة ومنعوا الخراجَ، وتَسَمَّوا بأسماء الأمراء، وجعلوا لهم كبيرينِ أحدهما سَمَّوه بيبرس، والآخر سلار، ولبسوا الأسلحةَ وأخرجوا أهلَ السُّجونِ بأيديهم، فاستدعى الأمراءُ القُضاةَ والفُقَهاءَ، واستفتَوهم في قتالِهم، فأفتَوهم ب"},{"id":2846,"era":"c8","t":"اتهام شيخ الإسلام ابن تيمية بالتعدي على حدود السلطان .","s":"وفي هذا الشَّهرِ ثار جماعةٌ مِن الحَسَدةِ على الشيخِ تَقيِّ الدين بن تيمية وشَكَوا منه أنَّه يقيمُ الحُدودَ ويُعَزِّرُ ويَحلِقُ رؤوس الصبيان، وتكلَّمَ هو أيضًا فيمن يشكو منه ذلك، وبيَّنَ خَطأَهم، فسَكَنَت الأمورُ."},{"id":2847,"era":"c8","t":"اليهود بدمشق يزورون كتابا على رسول الله صلى الله عليه وسلم بوضع الجزية عنهم .","s":"عُقِدَ مجلِسٌ لليهود الخيابرة وأُلزِموا بأداءِ الجزية أسوةَ أمثالهم من اليهود، فأَحضروا كتابًا معهم يزعُمونَ أنَّه من رسولِ الله صلى الله عليه وسلم بوضعِ الجِزيةِ عنهم، فلما وقف عليه الفُقَهاءُ تَبَيَّنوا أنَّه مكذوب مُفتَعَلٌ لما فيه من الألفاظِ الركيكة، والتواريخِ المحبطة، واللَّحنِ الفاحش، وحاقَقَهم عليه شيخُ الإسلام ابن تيميَّةَ، وبيَّنَ لهم خطأَهم وكَذِبَهم، وأنَّه مُزَوَّرٌ مكذوب، فأنابوا إل"},{"id":2848,"era":"c8","t":"تمرد أهل سيس ومحاربتهم .","s":"ورد الخبَرُ من حلب بأن تكفور الأرمني متمَلِّكَ سيس منع الحَملَ وخرَجَ عن الطاعةِ وانتمى لغازان، فرسم بخروجِ العسكر لمحاربته، وخرج الأميرُ بدر الدين بكتاش الفخري أميرُ سلاح والأمير عز الدين أيبك الخازندار بمضافيهما من الأمراءِ والمفاردة في رمضانَ وساروا إلى حماة، فتوجَّهَ معهم العادل كتبغا في الخامِسَ عشر من شوال، وقَدِموا حلب في أوَّلِ ذي القَعدةِ ورحَلوا منها في ثالِثِه، ودخلوا دربند بغراس في ساب"},{"id":2849,"era":"c8","t":"وفاة العلامة شيخ الإسلام تقي الدين بن دقيق العيد .","s":"هو الإمامُ العلَّامةُ شَيخُ الإسلام تقيُّ الدين أبو الفتح محمد بن علي بن وهب بن مطيع القشيري المصري المنفلوطي، المالكيُّ الشافعي، أحَدُ الأعلام وقاضي القضاة, المعروفُ بابن دقيق العيد. وُلِدَ يوم السبت الخامس والعشرين من شعبان سنة 625 بساحل مدينة ينبع من أرض الحجاز، تفقَّهَ على والده بقوص, وكان والِدُه مالكيَّ المذهب، ثم تفقَّه على الشيخ عزِّ الدِّين بن عبد السلام الشافعي، فحقَّق المذهبَين، وأفتى ف"},{"id":2850,"era":"c8","t":"فتح الناصر قلاوون جزيرة أرواد وطرد الصليبيين منها .","s":"قَدِمَ البريد من طرابلس بأن الفرنجَ أنشؤوا جزيرةً تجاه طرابلس تُعرَفُ بجزيرة أرواد، وعَمَروها بالعدد والآلات وكثُرَ فيها جمعُهم، وصاروا يركَبونَ البحر ويأخذون المراكِبَ، فرسم للوزير بعمارةِ أربعة شواني حربية، فشرَعَ في ذلك، ثمَّ في صفر هذه السنة توجَّهَ كهرداش إلى جزيرة أرواد، وهى بقُرب طرطوس، وصبَّحَهم في غفلةٍ وأحاط بهم وقاتلَهم ساعةً، فنصره اللهُ عليهم وقَتَلَ منهم كثيرًا، وسألوا الأمانَ فأُخِذ"},{"id":2851,"era":"c8","t":"وقعة عرض بين التتار والمماليك .","s":"وقعة عَرض- وهي من أعمال حلب بين الرصافة وتدمر- وذلك أنَّه التقى جماعةٌ من أمراء الإسلام فيهم استدمر وبهادر أخي وكجكن وغرلو العادلي، وكلٌّ منهم سيفٌ من سيوف الدين في ألفٍ وخمسمائة فارس، وكان التتارُ في سبعةِ آلاف فاقتتلوا وصبر المسلمون صبرًا جيدًا، فنصرهم الله وخذلَ التَّتَر، فقتلوا منهم خلقًا وأسروا آخرينَ، ووَلَّوا عند ذلك مُدبِرينَ، وغَنِمَ المسلمون منهم غنائِمَ، وعادوا سالمين لم يُفقَدْ منهم إل"},{"id":2852,"era":"c8","t":"وقعة شقحب بين التتار والمسلمين ومعهم شيخ الإسلام ابن تيمية .","s":"في ثامِنَ عشر رجب قَدِمَت طائفة كبيرة من جيش المصريِّين فيهم الأمير ركن الدين بيبرس الجاشنكير، والأميرُ حسام الدين لاجين المعروف بالاستادار المنصوري، والأميرُ سيف الدين كراي المنصوري، ثم قدمت بعدهم طائفةٌ أخرى فيهم بدر الدين أمير سلاح وأيبك الخزندار فقَوِيَت القلوبُ واطمأنَّ كثير من الناس، وكان الناسُ في حفل عظيم من بلاد حلب وحماة وحمص وتلك النواحي، وتقهقر الجيشُ الحلبي والحموي إلى حمص، ثم خافوا أ"},{"id":2853,"era":"c8","t":"وفاة الأمير زين الدين كتبغا المنصوري .","s":"هو الأميرُ زين الدين كتبغا المنصوري، نائِبُ السَّلطنة بحماة، كان من مماليكِ السلطان المَلِك المنصور سيف الدينِ قلاوون الصالحي, وأصلُه من أسرى التَّتار اشتراه السلطانُ قلاوون ثمَّ ترقَّى حتى تسلطنَ، وتلقَّب بالمَلِك العادل، وملَك ديارَ مِصرَ والشام في سنة 694، ثم خلَعَه نائبُه لاجين، وأعطاه صرخد في سنة ستٍّ وتسعين، واستمَرَّ مُقيمًا بصرخد إلى أن اندفَعَ المسلمون من التَّتَر على حمص، فوصل كتبغا من ص"},{"id":2854,"era":"c8","t":"غزو سيس وتل حمدون .","s":"سارت العساكِرُ من القاهرة للغارة على الأرمن في بلاد سيس، وعليهم الأميرُ بدر الدين بكتاش أمير سلاح، ومعه الأميرُ علم الدين سنجر الصوابي والأميرُ شمس الدين سنقر شاه المنصوري ومضافيهم، وكتب إلى طرابلس وحماة وصفد وحلب بخروج العساكِرِ إليها، فوصل الأميرُ بدر الدين بكتاش إلى دمشقَ في ثاني عشر رمضان، وخرج منها بعسكرِ دمشق، فسار إلى حَلَب وأتته عساكِرُ البلاد، فافتَرَقوا فرقتينِ فِرقةً سارت صحبة قبجق إلى "},{"id":2855,"era":"c8","t":"وفاة قازان محمود بن أرغون بن أبغا ملك التتار وتولي أخيه خدابندا .","s":"هو المَلِكُ محمود غازان ويقال (قازان) بن القان أرغون بن أبغا بن هولاكو بن تولي بن جنكزخان المغولي ملك التتار العراقين وخراسان وفارس وأذربيجان والروم؛ ولد سنة 670. كان شابًّا عاقلًا شجاعًا مهيبًا مليحَ الشكلِ، وكان جلوسه على تخت الملك سنة 693. ذكر الذهبي إسلامَه فقال: \"دخل قازان الإسلامَ بوساطة نوروز التركي وزيرِه ونائِبِه ومدبِّر مملكته وزَوجِ عَمَّتِه. أسلم في شعبان سنة694 بخراسان على يد الشيخ ال"},{"id":2856,"era":"c8","t":"نزوح كثير من عائلات التتار المسلمة إلى مصر .","s":"حضر جماعةٌ من المغول وافدينَ إلى بلاد الإسلام بعد إسلامِهم، نحو مائتي فارس بنسائِهم وأولادهم، وفيهم عِدَّةٌ من أقارب غازان وبعض أولاد سنقر الأشقر، الذي كتب يحُثُّ على إكرامهم، فقَدِموا إلى القاهرة في جمادى الأولى وقَدِمَ معهم أخوا سلار، وهما فخر الدين داود، وسيف الدين جبا، وقَدِمَت أيضًا أم سلار، فرُتِّبَت لهم الرواتب، وأُعطوا الإقطاعات، وفُرِّق جماعةٌ منهم على الأمراء، وأنشأ سلار لأمِّه دارًا بإس"},{"id":2857,"era":"c8","t":"شيخ الإسلام ابن تيمية يهدم الصخرة المزعوم أن فيها أثر النبي صلى الله عليه وسلم .","s":"سار الشيخُ تقي الدين ابن تيمية إلى مسجدِ النارنج وأمر أصحابَه ومعهم حجَّارونَ بقَطعِ صَخرةٍ كانت هناك بنهر قلوط تزارُ ويُنذَرُ لها، ويقولون إن الأثَرَ الذي بها هو قَدَمُ النبيِّ صلَّى الله عليه وسلم، فبَيَّنَ أن ما يفعَلُه الناس من التبرك به وتقبيلِه لا يجوز، فقَطَع الصخرةَ في سادس عشر رجب، وقد أنكر عليه الناسُ ما فعله فأُجيبَ إن كان الأمرُ على ما زعم فقد فعل الخيرَ وأزال بدعة، وإن كان الأمرُ بخلا"},{"id":2858,"era":"c8","t":"مسير شيخ الإسلام ابن تيمية مرة ثانية إلى كسروان الدروز والروافض .","s":"في مستهَلِّ ذي الحجَّة ركبَ الشيخ تقي الدين ابن تيمية ومعه جماعةٌ من أصحابه إلى جبل الجرد والكسروانيين ومعه نقيبُ الأشراف زين الدين بن عدنان، فاستتابوا خلقًا من الرافضة والدروز وألزَموهم بشرائِعِ الإسلامِ، ورجع مُؤيَّدًا منصورًا."},{"id":2859,"era":"c8","t":"مدينة سبتة بين بني مرين وبين بني الأحمر .","s":"استولى السلطانُ محمد الثالث الملَقَّب بالمخلوع بن محمد الثاني الملقَّب بالفقيه على مدينة سبتة، ولكنَّ السلطانَ محمد بن الأحمر توجَّه بأسطول فاسترَدَّ سبتة من بني مرين."},{"id":2860,"era":"c8","t":"محاربة الأرمن أهل سيس .","s":"أخَّر متمَلِّكُ سيس الحملَ الجاريَ به العادة، فبعث إليه نائِبُ حلب أستاداره قشتمر الشمسي أحدَ مقدَّمي حلب على عسكرٍ نحو الألفين، وفيهم الأميرُ شمس الدين أقسنقر الفارسي والأميرُ فتح الدين صبرة المهمندار- الذي يتلقَّى الرسُلَ والمبعوثين- والأمير قشتمر النجيبي، وقشتمر المظفري، فشنوا الغاراتِ على بلاد سيس، ونهبوا وحَرَّقوا كثيرًا من الضياع، وسَبَوا النساءَ والأطفال في المحَرَّم، وكان قد وصل إلى سيس طا"},{"id":2861,"era":"c8","t":"محاربة أهل الكسروان والجرد .","s":"خرج نائِبُ السلطنة بمن بقي من الجيوشِ الشاميَّة، وقد كان تقَدَّمَ بين يديه طائفةٌ من الجيش مع ابن تيميَّة في ثاني المحرم، فساروا إلى بلاد الجرد والرَّفضِ والتيامنة والدروز فخرج نائبُ السلطنة الأفرم بنفسه بعد خروجِ الشيخ لغزوهم، فنصَرَهم الله عليهم وأبادوا خلقًا كثيرًا منهم ومِن فِرقَتِهم الضالَّة، ووَطِئوا أراضيَ كثيرةً مِن صُنعِ بلادهم، وعاد نائِبُ السلطنة إلى دمشقَ في صحبته الشَّيخُ ابن تيمية وا"},{"id":2862,"era":"c8","t":"مناظرة شيخ الإسلام ابن تيمية للصوفية .","s":"حضر جماعةٌ كثيرة من الفقراء الأحمدية في يوم السبت تاسع جمادى الأولى إلى نائب السَّلطنةِ بالقصر الأبلق وحضر الشيخُ تقي الدين ابن تيمية فسألوا من نائب السلطنةِ بحَضرةِ الأمراء أن يكُفَّ الشيخ تقي الدين إمارتَه عنهم، وأن يسَلِّمَ لهم حالهم، فقال لهم الشيخ: هذا ما يمكِنُ، ولا بُدَّ لكل أحد أن يدخُلَ تحت الكتاب والسنة، قولًا وفعلًا، ومن خرج عنهما وجب الإنكارُ عليه، فأرادوا أن يفعلوا شيئًا من أحوالِهم ا"},{"id":2863,"era":"c8","t":"محنة شيخ الإسلام ابن تيمية وحبسه في القاهرة بسبب الاعتقاد .","s":"حضر القضاةُ والعُلَماءُ وفيهم الشيخُ تقيُّ الدين ابن تيمية في يوم الاثنين ثامِنَ رجب عند نائب السلطنةِ بالقَصرِ، وقُرئت عقيدةُ الشيخ تقي الدين ابن تيمية الواسطيَّة، وحصل بحثٌ في أماكِنَ منها، وأُخِّرَت مواضِعُ إلى المجلس الثاني، فاجتمعوا يومَ الجمعة بعد الصلاة في الثاني عشر من هذا الشهر, وحضر الشيخُ صفي الدين الهندي، وتكلَّمَ مع الشيخِ تقيِّ الدين كلامًا كثيرًا، ولكِنَّ ساقِيَتَه لاطمت بحرًا، ثم ا"},{"id":2864,"era":"c8","t":"قدوم وفد من الصوفية من التتار إلى دمشق .","s":"وَفَدَ لدمشق رجلٌ من بلاد التتار يقال له الشيخُ براق الرومي- كان في الأصل مريدًا لبعض الشيوخِ في البلاد الروميَّة- في تاسع جمادى الأولى، ومعه جماعةٌ من الفقراء نحو المائة لهم هيئةٌ عجيبةٌ، وعلى رؤوسِهم كلاوت لباد مقصَّصة بعمائِمَ فوقها، وفيها قرونٌ من لباد شبه قرون الجاموس فيها أجراسٌ، ولِحاهم مُحَلَّقة دون شواربهم خلافًا للسنَّة، ولُبسُهم لبابيدُ بيضاء، وقد تَقَلَّدوا بحبالٍ منظومة بكعاب البقر، و"},{"id":2865,"era":"c8","t":"وفاة أبي يعقوب يوسف المريني ملك المغرب .","s":"هو السُّلطانُ أبو يعقوب يوسُفُ بن يعقوب بن عبد الحَقِّ بن محيو بن أبي بكر بن حمامة ملك المغرب. وثب عليه سعادةُ الخَصِيُّ أحدُ مواليه في بعضِ حُجَرِه، وقد خَضَّب رجلَيه بالحنَّاء وهو مُستلقٍ على قَفاه، فطعنه طعناتٍ قطَعَ بها أمعاءه، وخرج فأُدرِكَ وقُتِلَ، فمات السلطانُ آخِرَ يوم الأربعاء سابع ذي القعدة، وأقيم بعده حفيدُه أبو ثابت عامر ابن الأمير أبي عامر بن السلطان أبي يعقوب يوسف بن يعقوب بن عبد ال"},{"id":2866,"era":"c8","t":"قتل برلغوا المغولي المسلم ملك سيس هيتوم .","s":"قُتِلَ هيتوم متمَلِّكُ سيس على يد بعضِ أمراء المغول؛ وذلك أنَّ هيتوم كان يحمِلُ القطعيَّة إلى المغول كما يحمِلُها إلى مصر، ويحضُر إلى كلِّ سنة أميرٌ من أمرائهم حتى يتسَلَّم الحَملَ، فحضر إليه من أمراء المغول برلغوا، وقد أسلَم وحَسُن إسلامُه، فعزم على بناءِ جامعٍ بسيس يعلَنُ فيه بالأذان، كما تجهَرُ هناك النصارى بضرب النواقيس، فشَقَّ ذلك على هيتوم، وكتب إلى خدبندا بأنَّ برلغوا يريد اللَّحاقَ بأهلِ م"},{"id":2867,"era":"c8","t":"حرب بين التتار وبين أهل كيلان .","s":"وقعت حربٌ بين التتار وبين أهلِ كيلان غربي طبرستان؛ وذلك أنَّ مَلِكَ التتار خربندا طلب منهم أن يجعلوا في بلادهم طريقًا إلى عسكره فامتنعوا من ذلك، فأرسل خربندا جيشًا كثيفًا ستين ألفًا من المقاتِلة؛ أربعين ألفًا مع قطلوشاه وعشرين ألفًا مع جوبان، فأمهلهم أهلُ كيلان حتى توسَّطوا بلادهم، ثم أرسلوا عليهم خليجًا من البحرِ ورَموهم بالنِّفطِ فغَرِقَ كثيرٌ منهم واحترق آخرونَ، وقَتَلوا بأيديهم طائفةً كثيرة، ف"},{"id":2868,"era":"c8","t":"وقوع خلاف بين السلطان الناصر وبين الأميرين بيبرس وسلار .","s":"في أوائل المحَرَّم أظهر السلطانُ المَلِكُ الناصر الغَضَبَ على الأمير سيف الدين سلار المغولي وبيبرس الجاشنكير، وامتنع من العلامة- العلامة: هي ما يكتُبُه السلطانُ بخطِّه على صورة اصطلاحيَّة، وكان لكل سلطانٍ علامة وتوقيع- وأغلق القلعةَ وتحَصَّن فيها، ولزمَ الأميران بيوتهما، واجتمع عليهما جماعةٌ من الأمراء وحُوصِرَت القلعة، وغُلِّقَت الأسواق، ثم راسلوا السلطانَ فتأطَّدت الأمور وسكنت الشرور على دخَنٍ و"},{"id":2869,"era":"c8","t":"خروج الشيخ تقي الدين ابن تيمية من السجن .","s":"اجتمع القضاةُ بالشيخِ تقي الدين ابن تيميَّة في دار الأوحدي من قلعةِ الجبل بمصر، وطال بينهما الكلامُ ثمَّ تفَرَّقا قبل الصلاة، والشيخُ تقيُّ الدين مُصَمِّمٌ على عدم الخروجِ من السجن، فلما كان يومُ الجمعة الثالث والعشرين من ربيع الأوَّل جاء الأميرُ حسام الدين مهنا بن عيسى مَلِك العرب إلى السجنِ بنَفسِه وأقسم على الشيخِ تقي الدين ليخرجَنَّ إليه، فلما خرجَ أقسَمَ عليه ليأتيَنَّ معه إلى دار نائبِ السلط"},{"id":2870,"era":"c8","t":"حبس شيخ الإسلام ابن تيمية مرة أخرى بمصر .","s":"وفي شوال مِن هذه السنة شكا الصوفيَّةُ بالقاهرة على الشيخِ تقيِّ الدين ابن تيميَّةَ, وكلامه في ابنِ عربي وغيرِه إلى الدولة، فردُّوا الأمرَ في ذلك إلى القاضي الشافعيِّ ابن صصرى، فعُقِد له مجلسٌ وادعى عليه ابنُ عطاء بأشياءَ فلم يثبُتْ عليه منها شيءٌ، لكنَّه قال: لا يُستغاثُ إلَّا بالله، لا يُستغاثُ بالنبيِّ صلَّى الله عليه وسلَّم؛ فالاستغاثةُ بمعنى العبادة، فبعضُ الحاضرين قال: ليس عليه في هذا شَيءٌ, "},{"id":2871,"era":"c8","t":"فتنة العبيد بمكة مع الأمير سيف الدين نوغاي القبجاقي .","s":"قام الأميرُ سيف الدين نوغاي القبجاقي التتري أميرُ ركب الحاجِّ بمحاربة العبيدِ بمكَّةَ، وذلك أنهم كثُرَ تخطُّفُهم أموالَ التجَّار، وأخْذُهم من الناسِ بالغَصبِ ما أرادوا، فلما وقف بعضُهم على تاجرٍ ليأخُذَ قماشَه منَعَه، فضربه ضربًا مُبَرِّحًا، فثار الناسُ وتصايحوا، فبعث نوغاي مماليكَه إلى العبيد فأمسَكوا بعضَهم وفَرَّ باقيهم بعدما جُرِحوا، فرَكِبَ الشريفُ حميضة بن أبي نُمَي بالأشراف والعبيد للحَربِ،"},{"id":2872,"era":"c8","t":"ورود الخبر بتحرك الفرنج لغزو دمياط وبناء جسر هائل عليها .","s":"ورد الخبَرُ بأن متمَلِّكَ قُبرُص اتَّفق مع جماعة من ملوك الفرنج على عمارةِ ستين سفينة لغزو دمياط، فجمع السلطانُ الناصر بن قلاوون الأمراءَ وشاوَرَهم، فاتَّفَقوا على عمل جسرٍ مادٍّ مِن القاهرة إلى دمياط خوفًا من نزولِ الفرنج أيَّامَ النيل، وندب لذلك الأمير جمال الدين أقوش الرومي الحسامي، وأمر ألا يراعي أحدًا من الأمراءِ في تأخيرِ رجالِ بلاده، ورسَمَ للأمراء أن يُخرِجَ كُلٌّ منهم الرجالَ والأبقار، وك"},{"id":2873,"era":"c8","t":"خلع محمد الثالث ملك بني نصر وتولي أخيه نصر بن محمد الثاني .","s":"قام نصرُ بنُ محمد الثاني الملَقَّب بأبي الجيوش ابن السلطان الأحمر الأنصاري المغربي بالخروجِ على أخيه أبي عبد الله محمَّد الثالث وخَلَعه واستولى على الحُكمِ، ونفى أخاه المخلوعَ إلى حِصنِ المنكِبِ حتى توفِّيَ فيه عام 713."},{"id":2874,"era":"c8","t":"خلع السلطان محمد بن قلاوون نفسه وتنصيب بيبرس الجاشنكير .","s":"لمَّا استقَرَّ الملك ناصر بالكرك وعَزَم على الإقامة بها بعد أن خرج من مصرَ على أنَّه يريد الحَجَّ، كتب كتابًا إلى الديار المصرية يتضَمَّنُ عَزلَ نَفسِه عن المملكة، فأثبت ذلك على القُضاةِ بمصر، وكان قد اشتَدَّ حَنَقُه، وصار في غاية الحَصرِ مِن تحَكُّم بيبرس الجاشنكيري- متذوِّق طعام السلطان- وسيف الدين سلار المغولي عليه، وعَدَم تصَرُّفِه ومَنْعه من كلِّ ما يريد، حتى إنه ما يصِلُ إلى ما يشتهي أكلَه ل"},{"id":2875,"era":"c8","t":"إظهار خدبندا ملك التتار الرفض في بلاده .","s":"أظهر خدبندا ملك التتر الرَّفضَ في بلاده، وأمر الخطباءَ أوَّلًا ألَّا يذكُروا في خُطبتِهم إلَّا عليَّ بنَ أبي طالب رضي اللهُ عنه وأهلَ بيته، ولما وصل خطيبُ بلاد الأزج إلى هذا الموضِعِ مِن خُطبتِه بكى بكاءً شديدًا وبكى الناسُ معه، ونزل ولم يتمكَّنْ من إتمام الخطبة، فأقيم مَن أتَمَّها عنه وصلَّى بالناس وظَهَر على الناسِ بتلك البلاد من أهل السُّنَّة أهلُ البدعةِ!"},{"id":2876,"era":"c8","t":"إنشاء المدرسة الطيبرسية في الجامع الأزهر .","s":"أنشأها علاءُ الدين طيبرس الخازندار نقيبُ الجيوشِ بالدِّيارِ المصريةِ، وهي على يمينِ الداخِلِ من باب الجامِعِ الأزهرِ المعروفِ بباب المزينين، وتمَّ الانتهاءُ مِن بنائها في عهد السلطانِ الناصر محمد بن قلاوون، فكانت من المدارس الملحَقة بالأزهر، وعُرِفت بالمدرسة الطيبرسية نسبةً إلى علاء الدين مؤسِّسِها الذي قرَّر أن يُدرِّسَ فيها درسًا للفقهاء الشافعية. وأنشأ بجوارِها مِيضأةً وحوضَ ماء سبيل ترِدُه الد"},{"id":2877,"era":"c8","t":"استيلاء الأسبان على جبل طارق .","s":"فرديناند الرابع ملك قشتالة وخايمي ملك أرغون يستوليانِ على جبل طارق، لِمَنع اتِّصالِ مَملكةِ بني مرين بالمَغربِ بمَملكة بني الأحمر بغِرناطة."},{"id":2878,"era":"c8","t":"خلع الملك المظفر الجاشنكيري وعودة السلطان الناصر قلاوون .","s":"لم يكتَفِ بيبرسُ الجاشنكيري بمُلكِ مِصرَ، بل ذهب يطلُبُ مِن الملك الناصِرِ المخلوعِ ما بيَدِه في الكرك، وذلك بتحريضِ وتخويفِ الأمراء له من الناصِرِ، فأصبح يريدُ أن يجرِّدَ النَّاصِرَ مِن كُلِّ شَيءٍ، فكان هذا من أسبابِ عَودةِ النَّاصِرِ لطَلَبِ المُلك، حيث حَبَس الناصِرُ مغلطاي رسولَ المظَفَّر بيبرس الذي جاء لأخذِ باقي أموالِ ومماليك الناصِرِ من الكرك، فخاف المظَفَّر بيبرس من ذلك، واشتهر بالدِّيار"},{"id":2879,"era":"c8","t":"فتنة بين القيسية واليمانية بحوران .","s":"في سادَسَ عَشَر شوال وقع بين أهلِ حوران من قيس ويَمَن فقتل منهم مقتلةٌ عَظيمةٌ جِدًّا، قُتِلَ مِن الفريقينِ نحوٌ من ألف نفسٍ بالقُربِ من السويداء (جنوبي سوريا)، وكانت الكسرةُ على يمن، فهربوا من قيس حتى دخل كثيرٌ منهم إلى دمشقَ في أسوأ الحال وأضعفِه، وهَرَبت قيس خوفًا من الدولةِ، وبَقِيَت القُرى خاليةً والزُّروعُ سائبةً."},{"id":2880,"era":"c8","t":"مقتل الملك المظفر بيبرس الجاشنكيري المخلوع .","s":"هو المَلِكُ المظَفَّر رُكنُ الدين بيبرس البرجي الجاشنكير- متذوِّق طعام السلطان- المنصوري. كان يُعرَف بالعثماني كان أبيضَ أشقرَ مُستدير اللحية، فيه عقل ودِينٌ، وله أموالٌ لا تحصى، وله إقطاعٌ كبيرٌ فيه عدَّة إقطاعات لأمراءَ، كان أستاذ دار الملك الناصر محمد بن قلاوون وسلار نائبًا فحَكَما في البلاد وتصَرَّفا في العباد، وللسُّلطانِ الاسمُ لا غير، وكان نواب الشام خوشداشية- زملاء مهنته- الجاشنكير وحزبه م"},{"id":2881,"era":"c8","t":"السلطان الناصر محمد بن قلاوون يقبض على العديد من الأمراء .","s":"بعد أن رجع الناصِرُ محمَّد إلى السلطنة وقَتَل المظَفَّر بيبرس الجاشنكيري، بقِيَ هناك الكثيرُ مِن الأمراء الذين كان يتخَوَّفُ منهم فبدأ بالقَبضِ عليهم فاستدعى من دمشقَ سبعةً من الأمراء واعتقَلَهم وحبَسَهم عنده، وفي مِصرَ قَبَض على أربعةَ عَشرَ أميرًا وحَبَسَهم، ومنهم من قُتِلَ وأُخِذَت إقطاعاته، وقُبض أيضًا على مماليك المظَفَّر بيبرس، ولكِنَّه تَرَكهم رحمة لهم، ثم إنَّه كان يهتَمُّ أكثَرَ شَيء ٍلأم"},{"id":2882,"era":"c8","t":"وفاة نجم الدين ابن الرفعة الفقيه الشافعي .","s":"هو الشَّيخُ نجم الدين أبو العبَّاس أحمد بن محمد بن علي بن مرتفع بن حازم، الأنصاري المصري، المعروف بابن الرفعة. فقيه شافعيٌّ. تفقه على الظهير والشريف العباسي، وسَمِعَ الحديث من محيي الدين الدميري، وعُيِّنَ مدرسًا بالمدرسة المعزية. كان محتَسِبَ القاهرة وناب في الحكم, ومن كتبه: \"المطلب في شرح الوسيط\"، \"الكفاية في شرح التنبيه\" وغير ذلك."},{"id":2883,"era":"c8","t":"أسر الفرنج لرسل السلطان الناصر .","s":"قَدِمَ الخبَرُ من سيس بأنَّ فِرنجَ جزيرة المصطكى أسَروا رسُلَ السلطان الناصر إلى المَلِك طقطاي، ومن معهم من رسل طقطاي وعِدَّتُهم ستون رجلًا، فبعث الملك طقطاي في فدائِهم ستين ألفَ دينار ليتَّخِذَ بذلك يدًا عند السلطانِ، فلم يمكِّنوه منهم، فكتب إلى الإسكندريَّة ودمياط بالحوطة على تجَّار الفرنج واعتقالِهم كُلِّهم، فأُحيطَ بحواصِلِهم وحُبِسوا بأجمَعِهم، وحضر أحَدُ تجَّار الجنوية فضَمِنَ إحضار الرسُل و"},{"id":2884,"era":"c8","t":"وفاة ابن منظور صاحب لسان العرب .","s":"هو الإمامُ اللُّغويُّ الحُجَّةُ مُحمَّدُ بنُ مكرم بن علي بن منظور الخزرجي الأنصاري الرويفعي الإفريقي، من ولد رُويفِع بن ثابت الأنصاري, وهو صاحِبُ (لسان العرب) ولِدَ بمصر سنة 630 ونشأ فيها وتعَلَّم. كان أديبًا وشاعرًا، وعالِمًا باللغة والنحو والتاريخ، وخَدَم في ديوان الإنشاء بالقاهرة, ثم وَلِيَ القضاء في طرابلس, وعاد إلى مصر فتوفِّيَ فيها، وقد ترك بخَطِّه نحوَ خمسمائة مجَلَّد، وعَمِيَ في آخر عمره. "},{"id":2885,"era":"c8","t":"إقامة الخطبة للسلطان الناصر في طرابلس الغرب .","s":"أقيمَت الخُطبةُ للمَلِك الناصر بطرابلس الغرب، أقامها له الشيخُ أبو يحيى زكريا بن أحمد بن محمد بن يحيى بن عبد الواحد بن حفص عمر اللحياني، لما جهزه السلطان إليها بالصناجِقِ وبعِدَّةٍ من الأجناد، وكان ذلك في شَهرِ رَجَب، وكان الأجنادُ قد قَدِموا مع بيبرس، بعدما قَدَّمَها أبو يحيى من مِصرَ في جُمادى الأولى."},{"id":2886,"era":"c8","t":"هروب بعض الأمراء إلى التتار .","s":"قدم البريدُ مِن حَلَب بعبور قرا سنقر ومن معه من الأمراء إلى بلاد التتار، وأنهم بَعَثوا بأولادهم وحريمهم إلى مصر، فكان مِن خَبَرِهم أنهم لما وصلوا إلى الرحبة انقطع كثيرٌ ممن تَبِعَهم من المماليك والتركمان، فبعث قرا سنقر ولَدَه الأمير فرجًا، وبعث الأفرم ولده موسى مع بعض من يُوثَقُ به، وأُمِرَا بتقبيلِ الأرض بين يَدَيِ السلطان، وأنْ يُبَلِّغاه أنَّ الأمراء ما حملَهم على دخولِ بلاد العدو إلَّا الخوفُ،"},{"id":2887,"era":"c8","t":"وفاة الملك المنصور صاحب ماردين وتولي ابنه بعده .","s":"هو المَلِكُ المنصور صاحب ماردين أبو الفتح نجم الدين غازي بن المَلِك المظَفَّر قرارسلان بن الملك السعيد نجم الدين غازي بن الملك المنصور ناصر الدين أرتق بن غازي بن المني بن تمرتاش بن غازي بن أرتق أصحاب ماردين من عِدَّة سنين، كان شيخًا حسنًا مَهيبًا كامِلَ الخلقة بدينًا سمينًا، إذا ركب يكون خلْفَه محَفَّة، خوفًا من أن يمسَّه لُغوبٌ فيركب فيها، توفِّيَ في تاسع ربيع الآخر ودُفِنَ بمدرسته تحت القلعة، وق"},{"id":2888,"era":"c8","t":"محاصرة خدابندا التتري الرحبة ورجوعهم خاسرين .","s":"ورد الخبَرُ في أول رجب بحركة خدابندا (ويقال له خربندا) وسبب ذلك رحيلُ بعض الأمراء إليه هاربين من السلطان الناصر منهم قراسنقر وغيره وإقامتُهم عنده، وتقويةُ عَزمِه على أخذ الشام، وكان السلطانُ تحت الأهرام بالجيزة، فقَوِيَ عزمُه على تجريد العساكر، ولم يزل هناك إلى عاشِرِ شعبان، فعاد إلى القلعة، وكتب إلى نوَّاب الشام بتجهيز الإقامات، وعرض السلطانُ العسكر، وترحَّلوا شيئًا بعد شيء، من أوَّل رمضان إلى ال"},{"id":2889,"era":"c8","t":"إرسال جيش إلى مكة بسبب ظلم أميرها وتمرده .","s":"توجَّهت تجريدة- خَيْلٌ لا رَجَّالة فيها- إلى مكَّة صحبة الأمير سيف الدين طقطاي الناصري والي قوص، وسيف الدين بيدوا، وعلاء الدين أيدغدي الخوارزمي، وصاروجا الحسامي، وتوجه دمشق سيف الدين بلبان البدري مع الركب، وأضيف إليهم عِدَّةٌ من الأجناد، وذلك بسَبَبِ الشريف حميضة بن أبي نمي، فإنَّه كَثُرَ ظُلمُه، ثم قَدِمَ الخبر من مكة بقَتلِ أبي الغيث في حَربٍ مع أخيه حميضة، وأنَّ العسكرَ المجرَّد إلى مكة الذي وص"},{"id":2890,"era":"c8","t":"قيام دولة بني المظفر بفارس .","s":"مع ضَعفِ الدولة الإيلخانية المغوليَّة وانهيارها بعد وفاة السلطان أبي سعيد ولا وريث له، والفوضى قائمة، فكان نتيجة ذلك اقتسام البلاد، فكانت كرمان وجنوبي فارس وكردستان من نصيب شَرفِ الدين المظَفَّر الذي كان هو حاكِمَها، ثم صار ابنه مبارز الدين محمد حاكمًا لمدينة يزد سنة 718 الذي وسَّع المملكة بحروبه مع بني أينجو في فارس، فبدأت دولةُ بني المظفَّر فيها."},{"id":2891,"era":"c8","t":"الإغارة على بلاد ماردين وقتال التتار .","s":"توجَّهَ من حلب ستُّمائة فارس عليهم الأميرُ شهاب الدين قرطاي للغارة على بلاد ماردين ودنيسر لقلة مراعاة صاحب ماردين لِما يُرسَم به، فشَنَّ قرطاي الغارةَ على بلاد ماردين يومين، فصادف التتارَ قد قَدِموا إلى ماردين على عادتهم كلَّ سَنةٍ لجباية القطيعة، وهم في ألفي فارس، فحارَبَهم قرطاي وقتل منهم ستَّمائة رجل، وأسَرَ مائتين وستين، وقَدِمَ بالرؤوس والأسرى إلى حلب، ومعهم عِدَّةُ خُيولٍ."},{"id":2892,"era":"c8","t":"ثورة على نصر بن محمد الثاني في غرناطة .","s":"ثار أبو سعيدٍ فَرَجُ بن إسماعيل بن يوسف بن نصر الأحمري صاحِبُ مالقة على ابنِ عَمِّه نصر بن محمد الثاني واستولى على المرية وبلش، وهزم قوات نصر؛ مما اضطر نصرًا إلى التنازل له عن العَرشِ والخروج من غرناطة إلى وادي آش ومبايعة أبي الوليد إسماعيل بن فرج من أسرة بني نصر خلفًا له."},{"id":2893,"era":"c8","t":"وفاة ملك القفجاق طقطغاي خان .","s":"هو مَلِكُ القفجاق المسمَّى طقطغاي بن منكوتمر بن طغان بن باطو بن جوجي، بن جنكيزخان، وكان له في المُلكِ ثلاث وعشرون سنة، وكان عمرُه ثمانية وثلاثين سنة، وكان شهمًا شجاعًا على دين التتر في عبادة الأصنام والكواكب، يُعَظِّمُ المجسِّمة والحكماء والأطباء، ويُكرِمُ المسلمين أكثَرَ من جميع الطوائف، كان جيشُه هائلًا لا يَجسُرُ أحد على قتاله لكثرة جيشِه, وقوَّتِهم وعدَدِهم، ويقال إنه جرَّد مرةً تجريدةً من كل "},{"id":2894,"era":"c8","t":"إنكار البكري على السلطان الناصر بن قلاوون في شأن النصارى .","s":"في نصف المحرَّمِ اتَّفَق أنَّه كان للنصارى مجتَمَعٌ بالكنيسة المعَلَّقة بمصر، واستعاروا من قناديلِ الجامِعِ العتيق جملةً، فقام في إنكارِ ذلك الشيخ نور الدين علي بن عبد الوارث البكري (وهو من أعداء شيخِ الإسلامِ ابنِ تيميَّة الذين كانوا قد سَعَوا في أذاه، مع أنَّ شيخَ الإسلام شَفَع فيه أيضًا لما طُلب من جهته)، وجمَعَ مِن البكريَّة وغيرِهم خلائِقَ، وتوجَّه إلى المعلقة وهَجَم على النصارى وهم في مجتَمَ"},{"id":2895,"era":"c8","t":"وفاة ملك شمس الدين دوباج صاحب كيلان  .","s":"هو المَلِكُ شمس الدين دوباج بن ملكشاه بن رستم صاحب كيلان. خرج قاصدًا الحجَّ في هذا العام، فلمَّا كان بغباغب أدركَته منيَّتُه يوم السبت السادس والعشرين من رمضان, فحُمِلَ إلى دمشق وصُلِّي عليه ودفن بتربته المشهورة بسفح قاسيون في خامس شوال، اشتريت له وتممت وجاءت حسنةً وهي مشهورة عند المكارية شرقيَّ الجامع المظفري، وكان له في مملكة كيلان خمس وعشرون سنة، وعمر أربعًا وخمسين سنة، وأوصى أن يحُجَّ عنه جماع"},{"id":2896,"era":"c8","t":"وفاة الشيخة الواعظة فاطمة بنت عياش البغدادية  .","s":"هي الشيخةُ العاملةُ الفقيهة الزاهدة القانتة الواعظة سيدة نساء زمانها: أم زينب فاطمة بنت عياش بن أبي الفتح البغدادية، كانت تفقه الفقه جيدًا, وانتفع بها خلقٌ من نساء أهل دمشق لصِدقِها في وعظها، ثم تحولت إلى القاهرة فحصل بها النفع وارتفع قدرُها وبعُدَ صيتُها، وكانت قد تفقهت عند المقادسة، كالشيخ ابن أبي عمر وغيره. كانت وافرة العلم، فائقة قانعة باليسير، حريصة على النفع والتذكير، ذات إخلاص وخشية، انصلح "},{"id":2897,"era":"c8","t":"فتح مدينة ملطية .","s":"كانت ملطيَّة إقطاعًا للجوبان أطلقها له ملك التتر فاستناب بها رجلًا كرديًّا يقال له مندوه فتعدى وأساء وظلم، وكاتب أهلُها السلطانَ الناصر بن قلاوون وأحبُّوا أن يكونوا من رعيَّتِه، فلمَّا ساروا إليها وأخذوها وفعلوا ما فعلوا فيها جاءها بعد ذلك الجوبان فعمَرها وردَّ إليها خلقًا من الأرمن وغيرِهم، وكان سبَبُ غزو ملطيَّة أن السلطان بعث فداوية من أهل مصياف لقتلِ قرا سنقر، فكان مندوه الكرديُّ يدل على قصاد "},{"id":2898,"era":"c8","t":"السلطان الناصر بن قلاوون يغير ملك النوبة وما حصل من القتال .","s":"رأى السلطانُ الناصر بن قلاوون أن يُقَدم برشنبو النوبي، وهو ابنُ أخت داود ملك النوبة، فجَهَّز صحبته الأميرَ عِزَّ الدين أيبك على عسكر، فلما بلغ ذلك كرنبس ملك النوبة بعَث ابن أختِه كنز الدولة بن شجاع الدين نصر بن فخر الدين مالك بن الكنز يسألُ السلطانَ في أمره، فاعتقل كنز الدولة، ووصل العسكَرُ إلى دنقلة، وقد فَرَّ كرنبس وأخوه أبرام، فقُبِضَ عليهما وحُملا إلى القاهرة، فاعتُقِلا، ومَلَك عبد الله برشنبو"},{"id":2899,"era":"c8","t":"خبر جيش التتار المتوجه إلى مكة .","s":"كان صاحِبُ مكَّة الأمير حميضة بن أبي نمي الحسني، قد قصد مَلِكَ التتر خربندا لينصُرَه على أهل مكة فساعده الروافِضُ هناك وجَهَّزوا معه جيشًا كثيفًا من خراسان، فلما مات خربندا بطل ذلك بالكلية، وعاد خميصة خائبًا خاسئًا. وفي صحبته أميرٌ من كبار الروافض من التتر يقال له الدلقندي، وقد جمع لخميصة أموالًا كثيرة ليقيم بها الرَّفضَ في بلاد الحجاز، فوقع بهما الأميرُ محمد بن عيسى أخو مهنا، وقد كان في بلاد التت"},{"id":2900,"era":"c8","t":"وفاة السلطان خربندا بن أرغون الرافضي ملك التتار .","s":"هو مَلِكُ التتارِ خَرْبَندا- بفتح الخاء المعجمة وسكون الراء وفتح الباء الموحدة وسكون النون- بن أرغون بن أبغا بن هولاكو بن تولو بن جنكيزخان السلطان غياث الدين، ملك العراق وخراسان وعراق العجم والروم وأذربيجان والبلاد الأرمينية وديار بكر، ومن الناسِ من يسَمِّيه خُدابَندا بضم الخاء المعجمة والدال المهملة وخدابندا: معناه عبد الله بالفارسي، غير أنَّ أباه لم يسمه إلَّا خربندا، وهو اسمٌ مُهمَل معناه: عبد "},{"id":2901,"era":"c8","t":"الأعراب يقطعون الطريق على رسل السلطان من اليمن .","s":"أخذ عَرَبُ برية عيذاب رسُلَ صاحب اليمن وعِدَّة من التجار وجميع ما معهم، فبعث السلطانُ الناصر محمد بن قلاوون العسكَرَ وهم خمسمائة فارس، عليهم الأميرُ علاء الدين مغلطاي بن أمير مجلس، في العشرين من شوال، فساروا إلى قوص، ومَضَوا منها في أوائل المحرم سنة سبع عشرة إلى صحراء عيذاب، ومضوا إلى سواكِنَ حتى التَقَوا بطائفةٍ يقال لها حيُّ الهلبكسة، وهم نحو الألفي راكب على الهجن بحِرابٍ ومزاريقَ، في خلقٍ مِن ا"},{"id":2902,"era":"c8","t":"وفاة الشيخ ابن المرحل شيخ الشافعية .","s":"هو الشيخُ أبو عبد الله محمد بن الشيخ المفتي زين الدين عمر بن مكي بن عبد الصمد المعروف بابن المرحل وبابن الوكيل شيخِ الشافعية في زمانه، وأشهَرُهم في وقته بكثرة الاشتغالِ والمطالعة والتحصيل والافتنان بالعلوم العديدة، وقد أجاد معرفةَ المذهب والأصلين، ولم يكن بالنحوِ بذاك القويِّ، وكان يقع منه اللَّحنُ الكثير، مع أنه قرأ منه المفَصَّل للزمخشري، وكانت له محفوظاتٌ كثيرة، ولد في شوال سنة 665، وسمِعَ الحد"},{"id":2903,"era":"c8","t":"هروب أمير مكة رميثة أبو نمي من أخيه حميضة الموالي للتتار .","s":"رجع الشَّريفُ حميضة بن أبي نمي من العراق إلى مكة، ومعه نحو الخمسين من المغول، فمنعه أخوه رميثة من الدخولِ إلَّا بإذن السلطان الناصِرِ ابن قلاوون، فكتب بمَنْعِه من ذلك ما لم يَقدَم إلى مِصرَ، ثم قدم الشريفُ رميثة أمير مكة فارًّا من أخيه حميضة، وأنه ملك مكَّةَ وخطَبَ لأبي سعيد بن خربندا وأخذ أموالَ التجَّار، فرسم بتجريدِ الأمير صارم الدين أزبك الجرمكي، والأمير سيف الدين بهادر الإبراهيمي في ثلاثمائة "},{"id":2904,"era":"c8","t":"منع النصيرية في الشام من تلقين الغلمان عقائدهم الباطلة .","s":"بعد قَتلِ مُدَّعي النُّصَيرية المهديَّة بساحل الشامِ رسم أن يُبنى بقرى النصيريَّة في كل قريةٍ مَسجِدٌ، وتُعمَل له أرضٌ لعمل مصالحه، وأن يُمنَعَ النُّصيريَّة من الخطابِ وهو أن الصبيَّ إذا بلغ الحُلُمَ عندهم عُمِلَت له وليمةٌ، فإذا اجتمع الناسُ وأكلوا وشَرِبوا حلَّفوا الصبيَّ أربعين يمينًا على كتمانِ ما يُودَعُ مِن المذهب، ثم يُعلِمونَه مذهَبَهم وهو إلهيَّةُ علي بن أبي طالب، وأن الخمر حلالٌ، وأن تنا"},{"id":2905,"era":"c8","t":"ابن خربندا ملك التتار يطلب الصلح من الناصر بن قلاوون .","s":"قَدِمَ كتاب المجد إسماعيل بن محمد بن ياقوت السلامي بإذعان المَلِك أبي سعيد بن خربندا، ووزيره خواجا علي شاه، والأمير جوبان، والأمراء أكابر المغول للصُّلحِ مع السلطان الناصِرِ ابنِ قلاوون، ومعه هديَّةٌ من جهةِ خواجا رشيد الدين، فجُهِّزَت إلى أبي سعيدٍ هدية جليلة من جملتها فرس وسيف وقرفل."},{"id":2906,"era":"c8","t":"دخول أهالي النوبة بالسودان في الإسلام  .","s":"في حينَ كان التفاعُلُ بين الإسلام والنوبة يأخُذُ دَورَه في أسوان وجنوبها حيث انتشرت اللغةُ العربيَّةُ وكثُرَت المساجِدُ وكان ملوكُ النوبة يفرَحونَ للهَجَماتِ الصليبية على مصر، ثمَّ لما جاء عهد المماليك خضعت النوبة تحت حكمِهم، فكان أهلُها يؤدُّونَ الجِزيةَ السَّنَويَّةَ ولكِنَّهم كانوا يمتنعون أحيانًا، فحصلت بينهم حروبٌ، ثم لما كان كرنبس الذي حاول التمَرُّدَ على المماليك فأرسلوا جيشًا يرافقه أمير ن"},{"id":2907,"era":"c8","t":"ظهور رجل يدعي أنه محمد بن الحسن المهدي من فرقة النصيرية .","s":"ظهر في سابع عشر ذي القعدة رجلٌ من أهل قرية قرطياوس من أعمالِ جبلة بساحل الشامِ زَعَم أنه محمد بن الحسن المهديُّ، وأنَّه بينما هو قائِمٌ يَحرُث إذ جاءه طائرٌ أبيضُ فنَقَب جنْبَه وأخرج روحَه وأدخل في جَسَدِه روحَ محمد بن الحسن، فاجتمع عليه من النصيريَّة القائلين بإلهيَّةِ عليِّ بن أبي طالب نحو الخمسة آلاف، وأمرهم بالسجودِ له فسجدوا، وأباح لهم الخَمرَ وتَرْك الصلوات وصَرَّحَ بأن لا إله إلا عليّ ولا ح"},{"id":2908,"era":"c8","t":"جماعة من التتار تقتل تجارا قادمين إلى الشام مع أطفالهم .","s":"اتَّفَق أنَّه في هذا الشهر تجمَّع جماعة من التجار بماردين وانضاف إليهم خلقٌ من الجفال من الغلا قاصدين بلاد الشام، حتى إذا كانوا بمرحلتين من رأس العين لحِقَهم ستون فارسًا من التتار فمالوا عليهم بالنشاب وقتلوهم عن آخرهم، ولم يبقَ منهم سوى صبيانِهم نحو سبعين صبيًّا، فقالوا من يقتل هؤلاء؟ فقال واحد منهم: أنا بشَرطِ أن تنَفِّلوني بمالٍ من الغنيمة، فقتلهم كلَّهم عن آخرهم، وكان جملةُ من قُتِل من التجَّار"},{"id":2909,"era":"c8","t":"انقراض دولة بني قطلمش ملوك قونية .","s":"انقَرَضت دولةُ بني قطلمش ملوك قونية، وذلك أنَّ عِزَّ الدين اسيكاوس بن كيخسرو لما مات سنة 677 ترك ابنَه مسعودًا، فولَّاه أبغا بن هولاكو سيواس وغيرها، واستبَدَّ معين الدين سليمان برواناه على ركن الدين قلج أرسلان ابن كيخسرو بقيصرية ثم قتَلَه، ونصب ابنَه غياث الدين كيخسرو، فعزله أرغون بن أبغا، وولي ابن عمه مسعود بن كيكاوس، فأقام مسعودٌ حتى انحل أمره وافتقر، وبقي المُلكُ بالروم للتتر إلَّا ملك بني أرتن"},{"id":2910,"era":"c8","t":"قحط وفناء عظيم في بلاد الجزيرة والموصل .","s":"وصَلَت الأخبارُ في المحَرَّم من بلاد الجزيرة وبلاد الشرق سنجار والموصل وماردين وتلك النواحي بغلاء عظيمٍ وفناء شديدٍ وقِلَّة الأمطار، والخوف من التتار، وعدمِ الأقواتِ وغلاءِ الأسعار، وقِلَّة النفقات، وزوال النِّعَم، وحلولِ النِّقَم، بحيث إنهم أكلوا ما وجدوه من الجماداتِ والحيواناتِ والميتاتِ، وباعوا حتى أولادَهم وأهاليهم، فبِيعَ الولد بخمسينَ دِرهمًا وأقل من ذلك، حتى إنَّ كثيرًا كانوا لا يشترون من "},{"id":2911,"era":"c8","t":"وقعة مع الأعراب ببرقة بسبب الزكاة .","s":"جهز الأميرُ أيتمش المحمدي على عسكرٍ إلى برقة، ومعه فايد وسليمان أمراءُ العُربان لجباية زكاةِ الأغنام على العادة، فسار في ثلاثمائةِ فارسٍ من أجناد الحلقة ومعه من الأمراءِ عِدَّةٌ، وذلك في آخِرِ يومٍ من المحرَّم، ونزل بالإسكندرية، ثم سار أيتمش يريدُ بلاد جعفر بن عمر من برقة، ومسافتُها من الإسكندرية على الجادة نحو شهرين، فدَلَّه بعض العرب على طريقٍ مسافتُها ثلاثة عشَرَ يَومًا يُفضي به إلى القَومِ مِن"},{"id":2912,"era":"c8","t":"وقعة عظيمة بين ملك التتار أبي سعيد بن خربندا ونائبه جوبان .","s":"كانت وقعةٌ عظيمةٌ بين التتار بسَبَبِ أنَّ مَلِكَهم أبا سعيد بن خربندا كان قد ضاق ذرعًا بنائبه الأمير جوبان وعجَزَ عن مَسكِه، فانتدب له جماعةً من الأمراء عن أمرِه، منهم أبو يحيى خال أبيه، ودقماق وقرشي وغيرُهم من أكابر الدولة، وأرادوا كبسَ جوبان فهرب وجاء إلى السلطانِ الناصر محمد بن قلاوون, فأنهى إليه ما كان منهم، وفي صُحبتِه الوزير علي شاه، ولم يزل بالسلطانِ حتى رضي عن جوبان وأمَدَّه بجيشٍ كثيف، ور"},{"id":2913,"era":"c8","t":"وقعة ألبيرة في غرناطة .","s":"حشد الفِرنجُ وأقبلوا يريدونَ استئصالَ المسلمين من الأندلس في غرناطةَ في عدَدٍ لا يُحصى، فيه خمسة وعشرونَ ملكًا بزعامة ألفونسو الحادي عشر ملك قشتالة، فقَلِقَ المسلمون بغرناطة ومَلِكُها الغالب بالله أبو الوليد إسماعيل بن فرج بن نصر من بني الأحمر، واستنجدوا بالمريني مَلِك فاس فلم يُنجِدْهم، فلجؤوا إلى الله وحارَبوهم في الألبيرة وهم نحو ألف وخمسمائة فارس وأربعة آلاف راجل، فقتلوا الفرنجَ بأجمَعِهم، وأق"},{"id":2914,"era":"c8","t":"السلطان الناصر يرسل الفداوية لقتل قراسنقر الذي هرب إلى التتار .","s":"بعث السُّلطانُ الناصر محمد بن قلاوون ثلاثينَ فداويًّا من أهل قلعةِ مصياف للفَتكِ بالأمير قراسنقر، فعندما وصلوا إلى تبريز نمَّ بعضُهم لقراسنقر عليهم، فتَتَبَّعَهم وقبضَ على جماعة منهم، وقَتَلهم، وانفرد به بعضُهم وقد ركب من الأردو، فقفز عليه فلم يتَمَكَّنْ منه، وقُتِلَ، واشتَهَر في الأردو خبَرُ الفداوية، وأنهم حضروا لقَتلِ السلطان أبي سعيد وجوبان والوزير علي شاه وقراسنقر وأمراء المغول، فاحتَرَسوا عل"},{"id":2915,"era":"c8","t":"نهاية الدولة الخلجية في الهند وقيام دولة بني تغلق .","s":"قام ناصِرُ الدين خسروخان بقتل قُطبِ الدين الخلجي لَمَّا خاف منه، فقام هو بأمر الدولةِ، وكان يميل إلى الهنادك؛ لذا فإن المُسلِمينَ كَرِهوه وتمنَّوا الخلاص منه، ثم بايعه الأمراءُ إلَّا تغلق شاه في السند فإنه أعلن الخلافَ، وسار إليه وقَتَله أيضًا فلم يَدُمْ في ملكه سوى أربعة أشهر، فكان خسروخان هذا آخِرَ ملوك الخلجيين، وكان تغلق هذا استعان بكشلوخان أمير الملتان ضِدَّ الجيش الذي أرسله خسروخان ضده فانهز"},{"id":2916,"era":"c8","t":"أبو سعيد ملك التتار يمنع الخمور وبيوت الفواحش في العراق .","s":"قَدِمَ الخبَرُ بأنَّ أبا سعيد بن خربندا مَلِك التتار بالعراق أراق الخُمورَ في سائر مملكته، وأبطل منها بيوتَ الفواحش، وأبعد أربابَ الملاهي، وأغلق الخاناتِ، وأبطل المكوسَ التي تُجبى من التجارة الواردة إليهم من البلاد، وهَدَّم كنائسَ بالقرب من توريز، ورفع شهادةَ الإسلام، ونشر العَدَل، وعَمَر المساجِدَ والجوامع، وقَتَل من وَجَد عنده الخمرَ بعد إراقته، فكتب السلطانُ الناصر محمد بن قلاوون لسائِرِ نواب ا"},{"id":2917,"era":"c8","t":"الصلح بين السلطان الناصر وبين أبي سعيد ملك المغول في العراق .","s":"قَدِمَ المجدُ السلامي على البريدِ مِن عند الملك أبي سعيد بن خربندا في طلب الصُّلحِ، فخرج القاضي كريم الدين الكبير إلى لقائه، وصَعِدَ به إلى القلعة، فأخبر المجد السلامي برغبةِ جوبان وأعيان دولة أبي سعيد في الصلحِ، وأنَّ الهديَّةَ تَصِلُ مع الرسل، فكَتَب إلى نائبي حلب ودمشق بتلقِّي الرسُلِ وإكرامِهم، فقدم البريدُ بأن سليمان بن مهنا عارض الرُّسُل، وأخذ جميعَ ما معهم من الهَديَّة، وقد خرج عن الطاعةِ ل"},{"id":2918,"era":"c8","t":"وقعة عظيمة ببلاد المغرب بين المسلمين والفرنجة وانتصار المسلمين .","s":"كانت وقعةٌ عظيمة ببلاد المغرب بين المسلمين والفرنجِ، فنصر الله المسلمينَ على أعدائِهم، فقتلوا منهم خمسينَ ألفًا وأَسَروا خمسةَ آلاف، وكان في جملةِ القَتلى آلاف من ملوك الفرنج، وغنموا شيئًا كثيًرا من الأموال، يقالُ: كان من جملة ما غنموا سبعون قنطارًا من الذهب والفضة، وإنما كان جيشُ الإسلام يومئذ ألفين وخمسَمائة فارس غير الرماة، ولم يُقتَلْ منهم سوى أحد عشر قتيلًا، وهذا من غريبِ ما وقع وعجيبِ ما سُم"},{"id":2919,"era":"c8","t":"الإغارة على بلاد الأرمن وتل حمدان وسيس .","s":"اجتمعت جُيوشُ السلطان الناصر بأرض حلَب نحوًا من عشرين ألفًا، عليهم كلِّهم نائبُ حلب الطنبغا وفيهم نائب طرابلس شهاب الدين قرطبة، فدخلوا بلاد الأرمن من إسكندرونة ففتحوا الثَّغرَ ثمَّ تل حمدان ثم خاضوا نهر جاهان فغَرِقَ منهم جماعة، ثم سلَّم اللهُ من وصلوا إلى سيس فحاصروها وضَيَّقوا على أهلها وأحرَقوا دارَ المَلِك التي في البلد، وقَطَعوا أشجارَ البساتين وساقوا الأبقارَ والجواميسَ والأغنام وكذلك فَعَلو"},{"id":2920,"era":"c8","t":"حبس شيخ الإسلام تقي الدين ابن تيمية في القلعة .","s":"في يومِ الخميس الثاني والعشرين من رجب عُقِدَ مجلس بدار السعادة للشَّيخِ تقي الدين ابن تيمية بحضرة نائب السَّلطنةِ، وحضر فيه القضاةُ والمُفتُونَ من المذاهب، وحضر الشيخُ وعاتبوه على العَودِ إلى الإفتاء بمسألةِ الطلاقِ، ثمَّ حُبِسَ في القلعةِ فبَقِيَ فيها خمسة أشهر وثمانية عشر يومًا، ثمَّ ورد مرسوم من السلطانِ بإخراجه يوم الاثنين يوم عاشوراء من سنةِ إحدى وعشرين، وكان الشيخُ قد عُقِدَ له أكثَرُ من مجل"},{"id":2921,"era":"c8","t":"وفاة شمس الدين محمد الهمذاني السكاكيني متشيع .","s":"هو الشيخُ شمس الدين محمد بن أبي بكر بن أبي القاسم الهمذاني ثم الدمشقي السكاكيني المتشيِّع، ولِدَ سنة 635 بدمشق، وطلب الحديثَ وتأدَّبَ وسَمِعَ وهو شابٌّ من إسماعيل بن العراقي والرشيد بن مسلمة، ومكي بن علان في آخرين، وتلا بالسبع، ومن مسموعاته مُسنَدُ أنس للحنيني على إسماعيل عن السلفي، ومن فوائد أبي النرسي بالسند عنه روى عنه البرزالي والذهبي وآخرون، من آخرهم أبو بكر بن المحب، وبالإجازة برهانُ الدين ا"},{"id":2922,"era":"c8","t":"هدم العامة كنائس النصارى بمصر وحرق بعضها .","s":"ثارت العامَّةُ يدًا واحدةً في يوم الجمعة تاسِعَ ربيع الآخر، وهَدَموا كنيستينِ مُتقابلتَينِ بالزهري، وكنيسة بستان السكري، وتعرف بالكنيسة الحمراء، وبعض كنيستين بمصرَ، ففي هذا اليوم الجمعة تاسع ربيع الآخر بطل العَمَلُ وقتَ الصلاةِ لاشتغالِ الأمراء بالصلاةِ، اجتمع من الغلمانِ والعامَّة طائفةٌ كبيرة، وصرخوا صوتًا واحدًا: اللهُ أكبر، ووقعوا في أركانِ الكنيسة بالمساحي والفُؤوسِ حتى صارت كُومًا، ووقع مَن "},{"id":2923,"era":"c8","t":"حرائق هائلة بالقاهرة من قبل النصارى ردا على هدم كنائسهم .","s":"كان عَقيبَ هَدمِ الكنائِسِ وقوعُ الحريق بالقاهرة ومصر، فابتدأ يومَ السبت خامس عشر جمادى الأولى، وتواتَرَ إلى آخره، بدأ الحريقُ في رَبعٍ من أوقاف المارستان المنصوري، واشتد الأمرُ، والأمراءُ تُطفِئُه إلى عصر يوم الأحد، فوقع الصوتُ قبل المغرب بالحريقِ في حارة الديلم بزُقاق العريسة، قريب من دار كريم الدين الكبير، ودخل الليلُ واشتد هبوب الرياح، فسَرَت النار في عِدَّة أماكن، وبعث كريمُ الدين بولده علم ا"},{"id":2924,"era":"c8","t":"وفاة الملك المؤيد هزبر الدين التركماني ملك اليمن وتولي ابنه بعده .","s":"هو المَلِكُ المؤيَّد هزبر الدين داودُ بن الملك المظفَّر يوسف بن عمر بن رسول التركماني الأصل اليمني المولِد والمنشأ والوفاة صاحِبُ ممالك اليمن، تسلطنَ بعد أخيه في المحرَّم سنة 696 فملَك نيفًا وعشرينَ سنة، وكان قبل سلطنته تفَقَّه وحَفِظَ كفايةَ المتحَفِّظ، ومُقَدِّمة ابن بابشاذ، وبحث التنبيه وطالعَ وفضل وسمع الحديث، وجمعَ الكتب النفيسةَ في سَلطنَتِه، حتى قيل إن خزانةَ كُتُبِه اشتملت على مائة ألف مجل"},{"id":2925,"era":"c8","t":"فتح إياس من بلاد الأرمن .","s":"في ربيع الأول تكامل فتح إياس (من بلاد الأرمن على ساحل البحرِ) ومعامَلتها وانتزاعُها من أيدي الأرمن، وأُخِذَ البرج الأطلس- وهو أحدُ ثلاثة أبراج وهي الأطلس والشمعة والإياس- بينه وبينها في البحر رميةٌ ونصف، فأخذه المسلمونَ بتوفيق الله وخَرَّبوه، وكانت أبوابُه مَطليَّةً بالحديد والرصاص، وعَرضُ سُورِه ثلاثة عشر ذراعًا، وغنم المسلمونَ غنائِمَ كثيرةً جدًّا، وحاصروا كوارَه فقوي عليهم الحَرُّ والذباب، فرسم"},{"id":2926,"era":"c8","t":"الإغارة على بلاد سيس .","s":"في مُستَهَلِّ جمادى الأولى قَدِمَ البريد بأن العسكَرَ أغار على بلاد سيس، وأخرَبَ وغَنِمَ وقتل جماعة، وأنَّ أوشين متمَلِّكَ سيس هلك، وقام مِن بعدِه ابنُه ليفون، وله من العُمرِ نحو اثنتي عشرة سنة، وأن العساكِرَ نازلت إياسَ وأخذوها عَنوةً بعد حصار، وقتلوا أهلَها وخَرَّبوها، وعادوا على الأرمن فغَنِموا وأسَروا منهم كثيرًا، وتوجَّهوا عائدين، فقَدِمَ الأمير جمال الدين أقوش بالعسكرِ إلى القاهرة في السابع "},{"id":2927,"era":"c8","t":"وفاة قاضي القضاة نجم الدين ابن صصرى الشافعي .","s":"هو الإمامُ العلَّامة الحافِظُ قاضي القضاة نجمُ الدين أبو العباس أحمد بن محمد بن سالم بن أبي المواهب، الربعي الثعلبي الدمشقي الشافعي، الشهيرُ بابن صصرى قاضي القُضاة بالشام، وُلِدَ في ذي القعدة سنة 655، ووالدتُه هي شاه ست بنت أبي الغنائم المسلم بن محمد بن المسلم بن علان القيسية الدمشقية، ذكرها الذهبي في معجم الشيوخ الكبير. كان في ابتداء أمرِه كتب في الإنشاء، وكان له نظمٌ ونثرٌ ومُشاركة في فنونٍ كثير"},{"id":2928,"era":"c8","t":"الإغارة على بلاد النوبة .","s":"في أوَّلِ ذي الحِجَّة خرج الأمير علاء الدين علي بن قراسنقر، والأمير سيف الدين أيدمر الكبكي، والأمير طقصباي المرتبة فديته بقوص، وخمسمائة من أجناد الحلقة إلى بلاد النوبة، ومعهم كرنبس، فانتهوا إلى دنقلة، وكان قد تغَلَّب كنزُ الدولة عليها، ونَزَع كرنبس، ففَرَّ كَنزُ الدولة منهم، وجلس كرنبس على سريرِ مُلكِه وعادوا، فحارب كنزُ الدولة كرنبس بعد عود العسكر، ومَلَك منه البلادَ."},{"id":2929,"era":"c8","t":"فتنة وقتل وقحط بأصبهان وأمراض وموت بالشام ومصر والصعيد .","s":"وقعت فِتنةٌ بأصبهان قُتِلَ بسَببِها ألوفٌ من أهلها، واستمَرَّت الحربُ بين أهلها شهورًا، وقَحَطَت بلادُ الشرق، فقَدِمَت طوائف إلى بلاد الشام، وكان الجراد قد أتلف زُروعَها، فجهز الأمراءُ مِن مِصرَ الغِلالَ الكثيرةَ في البحر إلى بيروت وطرابلس، فكان ما حُمِلَ من جهة السلطان الناصر محمد بن قلاوون والأمراء نحو عشرين ألف أردب سوى ما حمله التجَّار، فانحَطَّ السِّعرُ وكُتِبَ بإبطال مُكسِ الغَلَّة بالشام، و"},{"id":2930,"era":"c8","t":"وفاة الشيخ البكري الشافعي .","s":"هو نور الدين أبو الحسن علي بن يعقوب بن جبريل البكري المصري الشافعيُّ، له تصانيفُ، وقرأ مسند الشافعي على وزيرة بنت المنجا، ثمَّ إنه أقام بمصر، وقد كان في جملةِ خُصومِ شَيخِ الإسلام ابن تيمية، أراد بعضُ رجال الدولة قَتْلَه فهرب واختفى عند ابن تيميَّة لَمَّا كان مقيمًا بمصر، وما مثالُه إلَّا مثالُ ساقيةٍ ضعيفةٍ كَدِرة لاطمت بحرًا عظيمًا صافيًا، أو رملةٍ أرادت زوال جبل، وقد أضحك العقلاءَ عليه، وقد أرا"},{"id":2931,"era":"c8","t":"وفاة الباجربقي المنحرف صاحب الملحمة الباجربقية .","s":"هو الزاهِدُ محمد بن عبد الرحيم بن عمر الجزري، ابن المفتي الكبير جمال الدين الباجربقي، نسبةً إلى باجربق قرية بين النهرين، هو رأسُ الفرقة الضالة المعروفة بالباجربقيَّة، كان والده فاضلًا عالِمًا، انتقل إلى دمشق وجلس للإفادةِ والإفتاء. نشأ ابنُه محمد هذا بدمشق، فاشتغل أولًا بالفقه، ثم عدل إلى السلوكِ فتزهَّدَ وحصل له حالٌ وكَشفٌ، وبدأ ينحَرِفُ حتى أنكر وجود الله تعالى، ثم انقطع فصَحِبَه جماعةٌ من الرذ"},{"id":2932,"era":"c8","t":"استيلاء أبي الوليد ملك غرناطة على مدينتي بياسة ومرتش الإسبانية .","s":"بعد أن انتصر ملِكُ غرناطة أبو الوليد إسماعيل في موقعة ألبيرة قَوِيَ شأنُه أكثَرَ، فتعاقَبَت غزواتُه في أراضي النصارى وممتلكاتِهم، فزحف على مدينةِ بياسة الحصينة فحاصَرَها حتى استسلَمَت، ثمَّ استولى عَنوةً على مدينة مرتش وغَنِمَ منها الكثيرَ."},{"id":2933,"era":"c8","t":"هدم الكنائس التي جددت في منية بني خصيب (محافظة المنيا بمصر) .","s":"توجَّهَ الأمير أرغون النائب إلى منية بني خصيب، فشكا أهلُها من مُباشريهم، فلم يسمَعْ لهم وأمر بضَربِهم، فرَجَموه بالحجارةِ وأنكَوا في مماليكِه وغِلمانِه، فرَكِبَ عليهم أرغون ليفتِكَ بهم، ففَرُّوا من عند الوطاق خارج البلد إلى داخِلِ البلد، فأخذ مماليكُه من عمائِمِ الهاربين ما يزيدُ على ثلاثمائة وستين عمامة زرقاء من عمائِمِ النصارى، فلما استكثَرَ ذلك قيل له إنَّ بها كثيرًا من النصارى، ولهم خَمسُ كنائ"},{"id":2934,"era":"c8","t":"اجتماع عدة رسل في مصر عند السلطان .","s":"اتفق في هذا العام أن اجتمع للسُّلطانِ الناصر محمد بن قلاوون بمصرَ مِن رُسُلِ الملوك ما لم يجتَمِعْ مثلُهم في دولة المماليك التركية، وهم: رسلُ صاحِبِ اليَمَنِ، ورسُلُ صاحبِ إسطنبول، ورسل الأشكري، ورسل متملِّك سيس، ورسُلُ أبي سعيد بن خربندا التتري، ورسُلُ ماردين، ورسُلُ ابن قرمان، ورُسُل ملك النوبة، وكُلُّهم يبذلونَ الطاعةَ للسُّلطانِ!"},{"id":2935,"era":"c8","t":"غرق بلاد مصر والعراق بسبب أمطار غزيرة .","s":"وقع بمصرَ مَطَرٌ لم يُسمَعْ بمِثلِه بحيث زاد النيلُ بسببه أربعَ أصابع، وتغيَّرَ أيامًا، وكذلك زادت دجلةُ ببغداد حتى غَرِقَت ما حول بغداد وانحصر الناسُ بها ستَّةَ أيام لم تُفتَحْ أبوابها، وبَقِيَت مثل السفينة في وسط البحر، وغَرِقَ خَلقٌ كثير من الفلَّاحين وغيرِهم، وتَلِفَ للنَّاسِ ما لا يعلَمُه إلا الله، وودَّعَ أهلُ البلد بعضُهم بعضًا، ولجؤوا إلى الله تعالى وحَمَلوا المصاحِفَ على رؤوسهم في شِدَّةِ"},{"id":2936,"era":"c8","t":"السلطان الناصر يرسل جيشا إلى اليمن لاسترداده .","s":"سأل المَلِكُ المجاهِدُ صاحِبُ اليمن إنجادَه بعسكَرٍ من مصر، وأكثَرَ من ترغيب السلطان الناصر محمد بن قلاوون في المالِ الذي باليمن، وكان قدومُ رُسُلِه في مستَهَلِّ صفر، فرسم السلطانُ بتجهيز العسكر صحبة الأمير ركن الدين بيبرس الحاجب، وهو مُقَدَّم العسكر، فسار إلى مكَّةَ، فوصل في السادس والعشرين من جمادى الأولى، ودخلها وأقامَ بها حتى قَدِمَت المراكِبُ بالغلال وغيرِها من مصر إلى جُدَّة، وتقَدَّم الخادِ"},{"id":2937,"era":"c8","t":"وفاة السلطان إسماعيل بن الأحمر ملك دولة بني نصر في الأندلس .","s":"هو إسماعيلُ بن فرج بن إسماعيل بن يوسف بن نصر بن الأحمر، أبو الوليد، السلطانُ الغالِبُ بالله أميرُ المؤمنينَ، خامِسُ ملوك دولة بني نصر بن الأحمر بغرناطة في الأندلس، كانت لأبيه ولايةُ مالقة وسبتة، فتولَّاهما من بعده. وكان الملك بغرناطة أبو الجيوش نصرُ بن محمد الفقيه، وهو موصوف بالضَّعفِ، فثار عليه إسماعيلُ وزحف من مالقة إلى غرناطة سنة 713 فبويع فيها، وخرج نصرٌ إلى وادي آش. وأراد بطرس الأوَّلُ بن ألف"},{"id":2938,"era":"c8","t":"رسل أزبك خان ملك التتار يطلبون من السلطان كتب حديث وفقه .","s":"في يَومِ السبت العشرينَ مِن رمضان قَدِمَ الأمير سيف الدين بكمش الجمدار الظاهريُّ والأمير بدر الدين بيليك السيفي السلاري المعروف بأبي غُدَّة من بلاد أزبك خان مَلِك التتار المُسلِم بهَدِيَّة، ومعهما كتابه، وهو يسأل أن يجهَّزُ له كتابُ (جامِع الأصول في أحاديث الرسول)، وكتاب (شرح السنة) و(البحر) للروياني في الفقه، وعِدَّةُ كُتُبٍ طَلَبها، فجُهِّزَت له."},{"id":2939,"era":"c8","t":"وفاة ابن المطهر الحلي الشيعي .","s":"جمالُ الدين أبو منصور حسن بن يوسف بن مُطَهَّر الحلي العراقي الشيعي المعتزلي، شيخُ الروافض بتلك النواحي وفقيهُهم، وله التصانيفُ الكثيرة، يقال تزيدُ على مائة وعشرين مجلدًا، وعِدَّتُها خمسةٌ وخمسون مصنَّفًا، في الفقه والنحو والأصول والفلسفة والرفض، وغير ذلك من كبارٍ وصغار، وله كتابُ منهاج الاستقامة في إثبات الإمامة، خبط فيه في المعقول والمنقول، ولم يدرِ كيف يتوجه، إذ خرج عن الاستقامةِ، وقد انتدب في ا"},{"id":2940,"era":"c8","t":"ملك الحبشة يتهدد السلطان الناصر إن لم يعد بناء الكنائس .","s":"في يومِ الاثنين سادس عشر المحَرَّم ورَدَت رسُلُ مَلِكِ الحبشة بكتابِه يتضَمَّنُ أمْرَه بإعادة ما خُرِّبَ من كنائِسِ النصارى بمصر, ومعامَلَتِهم بالإكرامِ والاحترامِ، ويهَدِّدُ بأنَّه يُخَرِّبُ ما عنده من مساجدِ المسلمين، ويَسُدُّ النيلَ حتى لا يَعبُرَ إلى مصر، فسَخِرَ السلطان الناصر محمد بن قلاوون منه، ورَدَّ رُسُلَه!!"},{"id":2941,"era":"c8","t":"إجراء عين باذان إلى مكة .","s":"في أوَّلِ رمضان وصَلَت الأخبار إلى دمشق أنه أُجرِيَت عينُ ماء إلى مكَّةَ شَرَّفَها اللهُ وانتفَعَ الناس بها انتفاعًا عظيما، وهذه العين تُعرِفُ قديمًا بعين باذان، أجراها الأميرُ سيف الدين جوبان المغولي نائب السلطان أبي سعيد بن خربندا مَلِك التتار من بلادٍ بعيدة حتى دخَلَت إلى نفس مكة، ووصلت إلى عند الصَّفا وباب إبراهيم، واستقى الناسُ منها فقيرُهم وغَنِيُّهم وضعيفُهم وشريفُهم، كلُّهم فيها سواء، وارت"},{"id":2942,"era":"c8","t":"اعتقال شيخ الإسلام ابن تيمية وتلميذه ابن قيم الجوزية .","s":"وفي يومِ الجُمُعةِ العاشِرَ من شعبان قُرِئَ بالجامع الكتابُ السلطانيُّ الوارِدُ باعتقال شيخ الإسلامِ ابن تيمية، وهذه الواقِعةُ سَببُها فُتيا وُجِدَت بخطِّه في السَّفَرِ وإعمالِ المطِيِّ إلى زيارةِ قُبورِ الأنبياء عليهم الصلاة والسلام، وقبورِ الصالحين، وفي يوم الأربعاء مُنتصَفَ شعبان أمر قاضي القضاة الشافعي في حبسِ جماعةٍ مِن أصحاب الشيخِ تقي الدين ابن تيمية في سِجنِ الحكم، وذلك بمرسومِ نائب السلطن"},{"id":2943,"era":"c8","t":"وفاة عثمان بن أرطغرل مؤسس الدولة العثمانية وتولي ابنه أورخان .","s":"هو أبو الملوكِ السلطانُ الغازي فخرُ الدين عثمانُ بك خان الأول بن أرطغرل بن سليمان شاه القايوي التُركماني، لما توفِّيَ أرطغرل سنة 687 هـ ( 1288م) تولى عُثمانُ زعامةَ القبائِلِ التُّركمانيَّة في المقاطعة التي منحهم إيَّاها السلطان علاء الدين السلجوقي والتي كانت قريبةً من بحر مرمرة التابع للبحرِ الأسود بالقُربِ من مدينة بورصة، كان عثمان قد تمكَّن في البلاد حتى إنَّه بدأ يدعو أمراءَ الروم في آسيا الصغ"},{"id":2944,"era":"c8","t":"وفاة الغالب بالله ملك غرناطة وتولي ابنه بعده .","s":"هو السلطانُ الغالب بالله أبو الوليد إسماعيل بن الفرج بن إسماعيل بن يوسف بن نصر صاحِبُ غرناطة والأندلس من بلاد المغرب، وكان مولده سنة 680، وكان من أجَلِّ ملوك المغرب، واستولى على الأندلُسِ ثلاث عشرة سنة، وملك البلادَ في حياة أبيه الفرج، وكان أبوه متوليًا إذ ذاك لمالقةَ، فلما أراد إسماعيلُ هذا الخروجَ لامَه أبوه، فقبض إسماعيلُ على أبيه، وعاش أبوه في سلطنتِه بعد ذلك عزيزًا مُبَجَّلًا إلى أن مات في رب"},{"id":2945,"era":"c8","t":"تنكز نائب السلطان بدمشق يشتري أسرى مسلمين من تجار الفرنج .","s":"قَدِمَ إلى ميناء بيروت من سواحِلِ الشام تجار الفرنج بمائة وأربعين من أسارى المسلمين، قد اشتَرَوهم من الجزائر، فاشتراهم الأميرُ تنكز، وأفاد التجَّارَ في كل أسيرٍ مائة وعشرين درهمًا على ما اشتراه به، وكسا تنكز الجميعَ وزَوَّدَهم، وحَمَلَهم إلى مصر، فسُرَّ المسلمون بقدومِهم، وجَدَّ تجارُ الفرنج في شراءِ الأسرى رغبةً في الفائدةِ."},{"id":2946,"era":"c8","t":"فتنة بالإسكندرية بين الفرنج والمسلمين .","s":"في يومِ الخميس خامِس رجب كانت الفتنةُ بالإسكندرية وملَخَّصُها أنَّ بعض تجار الفرنج فاوض رجلًا من المسلمينَ وضَرَبه بخُفٍّ على وجهه، فثار المسلمون بالإفرنجيِّ وثار الفرنجُ لتحميه، فوقع الشَّرُّ بين الفريقين، واقتتلوا بالسلاحِ، فركب ركن الدين الكركي متولِّي الثغر، فإذا النَّاسُ قد تعصبوا وأخرجوا السلاحَ، وشهدوا على الفرنجيِّ ممَّا يوجب قَتْلَه، وحملوه إلى القاضي وغُلِّقَت أسواق المدينة وأبوابها، فلم"},{"id":2947,"era":"c8","t":"وفاة ابن الزملكاني الشافعي .","s":"هو أبو المعالي محمَّدُ بن علي بن عبد الواحد بن عبد الكريم، الزملكاني الأنصاري السماكي الدمشقي الشافعي قاضي قضاة دمشق، انتهت إليه رياسةُ المذهب تدريسًا وإفتاء ومناظرة، ويقالُ في نسبه السماكي نسبة إلى أبي دجانة سماك بن خَرشة، وُلِدَ ليلة الاثنين ثامن شوال 666، وسمع الكثير واشتغل على الشيخ تاج الدين الفزاري، وفي الأصولِ على القاضي بهاء الدين بن الزكي، وفي النحوِ على بدر الدين بن ملك وغيرهم، وكان من خ"},{"id":2948,"era":"c8","t":"قدوم دمرداش بن جوبان إلى مصر ثم قتله فيها .","s":"قَدِمَ دمرداش بن جوبان بن تلك بن تداون المغولي مصرَ في سابع ربيع الأول، وسَبَبُ ذلك أن القان أبا سعيد بن خربندا المغولي لَمَّا مَلَك أقبلَ على اللهو، فتحَكَّم الأميرُ جوبان بن تلك على الأردو، وقام بأمر المملكة، واستناب ولدَه خواجا رمشتق بالأردو، وبعث ابنَه دمرداش إلى مملكة الروم، فانحصر أبو سعيد بن خربندا إلى أن تحَرَّك بعض أولاد كبك بجهة خراسان، وخرج عن الطاعةِ، فسار جوبان لحَربِه في عسكرٍ كبير، "},{"id":2949,"era":"c8","t":"تنكز نائب السلطان على دمشق يجري عينًا في القدس .","s":"كان قبل سنتين أمَرَ تنكز نائبُ السلطان على دمشقَ بإجراء عينٍ إلى القدس، حيث قلَّ الماءُ فيها كثيرًا وبلغه ما فعله جابان بإجراءِ عَينٍ في مكَّةَ، فأراد أن يكون له أيضًا شَرَفُ ذلك، وفي هذه السنة كَمُلت العينُ التي أجراها الأمير تنكز بالقدس، بعد ما أقام الصنَّاعُ فيها مُدَّةَ سنة، وبنى لها مصنعًا- خزانًا- سعته نحو مائتي ذراع مرخَّم بين الصخرة والمسجد، وركَّب في الجبل مجاريَ نَقَب لها في الحَجَرِ حتى"},{"id":2950,"era":"c8","t":"منع شيخ الإسلام ابن تيمية من الكتابة في السجن .","s":"في يومِ الاثنين تاسِعَ جمادى الآخرة أُخرِجَ ما كان عند الشيخِ تقي الدينِ ابن تيميَّةَ من الكتُبِ والأوراقِ والدواةِ والقلم، ومُنِعَ من الكُتُبِ والمطالعة، وحُمِلَت كتُبُه في مُستهَلِّ رَجَب إلى خزانةِ الكتُبِ بالعادليَّة الكبيرة، وكانت نحو ستين مجلَّدًا، وأربع عشرة ربطةَ كراريس، فنظر القضاةُ والفُقهاءُ فيها وتفَرَّقوها بينهم، وكان سبَبَ ذلك أنَّه أجاب لما كان ردَّ عليه التقيُّ ابنُ الأخنائي المالك"},{"id":2951,"era":"c8","t":"وفاة الأمير جوبان نائب السلطان أبو السعيد بن خربندا المغولي .","s":"هو الأميرُ الكبير الأمير سيفُ الدين جوبان بن تلك بن تداون المغولي نائبُ السلطانِ أبي سعيدِ بن خربندا المغولي مَلِك التَّتار، وجوبان هذا هو الذي ساق قناةَ الماء الواصِلةَ إلى المسجد الحرام، وقد غَرِمَ عليها أموالًا جزيلة كثيرة، وله تربةٌ بالمدينة النبوية، ومدرسةٌ مشهورة، وله آثارٌ حَسَنة، وكان جيِّدَ الإسلامِ، له همَّة عالية، وقد دبَّرَ الممالِكَ في أيام السلطان أبي سعيد مُدَّةً طويلة على السداد، ث"},{"id":2952,"era":"c8","t":"حدوث سيل عظيم في مدينة عجلون .","s":"جاء إلى مدينة عجلون سيلٌ عظيم من أوَّل النهار إلى وقتِ العصر، فهدَمَ مِن جامعِها وأسواقِها ورِباعِها ودُورِها شيئًا كثيرًا، وغَرِقَ سَبعة نَفَرٍ، وهلك للناس شيءٌ كثير من الأموال والغلات والأمتعة والمواشي ما يقارب قيمتُه ألف ألف درهم."},{"id":2953,"era":"c8","t":"وفاة شيخ الإسلام تقي الدين ابن تيمية .","s":"هو الشَّيخُ الإمامُ العالمُ العَلَمُ العلَّامةُ الفقيهُ الحافِظُ الزاهِدُ العابِدُ القدوةُ شيخُ الإسلامِ: تقيُّ الدين أبو العباس أحمد بن شهاب الدين أبي المحاسن عبد الحليم بن أبي البركات عبد السلام بن عبد الله بن أبي القاسم محمد بن الخضر بن محمد ابن الخضر بن علي بن عبد الله بن تيمية الحراني ثمَّ الدمشقي، وكان مولِدُه يومَ الاثنين عاشر ربيع الأول بحران سنة 661، وقَدِمَ مع والده وأهلِه إلى دمشقَ وهو "},{"id":2954,"era":"c8","t":"إطلاق سراح الإمام ابن قيم الجوزية .","s":"في يومِ الثلاثاء عشرينَ ذي الحجة أُفرِجَ عن الشيخ الإمامِ العالم العلَّامة أبي عبد الله شمس الدين بن قيم الجوزية، وكان معتقَلًا بالقلعة أيضًا مع الشيخ تقي الدين من شعبان سنة ست وعشرين إلى هذا الحينِ."},{"id":2955,"era":"c8","t":"بناء أول جيش عثماني نظامي .","s":"بعد أن انتقل أورخان بن عثمان إلى بورصة وجعَلَها عاصمَتَه وضَرَبَ العملةَ الفضيَّة والذهبيَّة ثمَّ بدأ بتأسيسِ جيشِ يني تشري- يعني الجيش الجديد الذي عرف فيما بعد بالإنكشارية- الذي كانت نَواتُه أبناءَ الأَسرى والصِّغار الذين يَقَعون في الأسرِ فيُرَبَّونَ في ثُكناتِ عَسكريَّة تربيةً إسلاميَّةً ويُدَرَّبونَ تَدريبًا عسكريًّا ويتخَرَّجونَ لا يَعرِفونَ إلَّا القتالَ والحياةَ العَسكريَّة والإسلامَ والجِه"},{"id":2956,"era":"c8","t":"مملوك يدعي أنه المهدي بمصر .","s":"في يومِ الجمعة سادس ذي القعدة بعد أذان الجُمُعةِ صَعِدَ إلى منبر جامِعِ الحكم بمصر شخصٌ من مماليك الجاولي يقالُ له أرصى، فادَّعى أنَّه المهدي وسَجَع سجعاتٍ يسيرةً على رأيِ الكُهَّان، فأُنزِلَ في شرخيبة، وذلك قبل حضورِ الخطيب بالجامِعِ المذكور."},{"id":2957,"era":"c8","t":"الفرنج يطلبون تسليم القدس وبلاد الساحل .","s":"في خامِس عشر ربيع الآخر قَدِمَت رسل ريدافرنس في طَلَبِ القُدسِ وبلادِ الساحل، وعِدَّتُهم مائة وعشرون رجلًا، فأنكَرَ السلطانُ الناصِرُ محمد بن قلاوون عليهم وعلى مُرسِلِهم وأهانَهم، ثمَّ رسم بِعَودِهم إلى بلادهم، وقال لهم: لولا أنَّ الرُّسُلَ لا تُقتَلُ لقَتَلْتُكم جميعًا."},{"id":2958,"era":"c8","t":"يوسف الكيمياوي النصراني يخدع السلطان الناصر بصناعة الذهب .","s":"قَدِمَ يوسفُ الكيمياوي إلى مِصرَ في يوم الخميس سابعَ عشر رمضان، وكان من خبَرِ هذا الرجل أنه كان نصرانيًّا من أهل الكرك فأسلم، ومضى إلى دمشقَ بعدما خَدَع بمدينة صفد الأميرَ بهادر التقوى حتى انخدع له وأتلَفَ عليه مالًا جزيلًا، فلما ظهَرَ له أمْرُه سَجَنه مُدَّةً، ثم أفرج عنه، فاتصَلَ يوسف بالأمير تنكز نائب الشام، وقَصَد خديعته فلم ينخَدِعْ له، وأمر والي دمشق بشَنقِه، فصاح وقال: أنا جيت للسُّلطانِ حت"},{"id":2959,"era":"c8","t":"فتنة العبيد بمكة وقتل الأمير الدمر جاندار .","s":"قُتِلَ الأميرُ الدمر جاندار بمكَّةَ في يوم الجمعة رابع عشر ذي الحجة، وكان مِن خَبَرِه أنَّ أميرَ الرَّكبِ العراقيِّ في هذه السنة كان من أهل توريز يُعرَفُ بمحمد الحجيج، وكان يتقَرَّب من أولاد جوبان، فترقَّى بهم إلى معرفةِ السلطان أبو سعيد بن خربندا ملك التتار بالعراق، فعَظُمَ أمرُه وجعَلَه من نُدَمائِه، وبَعَثَه رسولًا إلى مصرَ غَيرَ مَرَّة، فأُعجِبَ به السلطانُ الناصِرُ ولاق بخاطِرِه إلى أن بلغه ع"},{"id":2960,"era":"c8","t":"تغيير أمير مكة بسبب فتنة العبيد .","s":"بعد ما كان من الفِتنةِ بمكَّةَ العامَ السَّابِقَ وانزعاج السلطانِ الناصر محمد بن قلاوون كثيرًا لذلك، ففي المحَرَّم هذا العام قَدِمَ الحاجُّ، وأخبروا بكثرةِ الفِتَن بمكَّةَ بين الشريفين عُطيفة ورُميثة، وقُوَّة رُمَيثة على عُطَيفة ونهْبِه مكَّة وخروجه عن الطاعة، وأنه لم يلقَ رَكبَ الحُجَّاج، فكتب بحضورِه، فلما ورد المرسومُ بطلب الشريفينِ إلى مصر اتَّفَقا وخرجا عن الطاعة، فشقَّ ذلك على السلطان، وعَزَ"},{"id":2961,"era":"c8","t":"ملك أبي الحسن علي بن أبي سعيد المريني مدينة فاس بعد أبيه .","s":"ملَكَ أبو الحَسَنِ علي بن أبي سعيد عثمان بن يعقوب بن عبد الحَقِّ المريني المنصور بالله مدينةَ فاس من بلادِ المغرب، بعد مَوتِ أبيه بعَهدٍ منه، وعُرِفَ بالسلطانِ الأكحَلِ لسُمرةِ لَونِه، فقد كانت أمُّه حَبشيَّةً."},{"id":2962,"era":"c8","t":"وفاة الملك المؤيد عماد الدين الأيوبي صاحب حماة وتولي ابنه بعده .","s":"هو المَلِكُ المؤيَّد صاحب حماة عماد الدين إسماعيل بن الملك الأفضل نور الدين علي بن الملك المظفر تقي الدين محمود بن الملك المنصور ناصر الدين محمد بن الملك المظفر تقي الدين عمر بن شاهنشاه بن أيوب، كانت له فضائلُ كثيرةٌ في علوم متعَدِّدة منها الفِقهُ والهيئة والطب، وله مُصَنَّفات عديدة، منها تاريخٌ حافِلٌ في مجلَّدين كبيرين، وله نَظمُ الحاوي وغير ذلك، وكان يحِبُّ العلماءَ ويُشارِكُهم في فنون كثيرة، و"},{"id":2963,"era":"c8","t":"الفرنج يهمون باستئناف الحروب الصليبية .","s":"فيليب السَّادِسُ مَلِكُ فرنسا يُعلِنُ عَزمَه على القيامِ بحَملةٍ صَليبيَّةٍ جَديدةٍ، لكِنَّه ينثني عنها بدخولِه حِلفًا ضِدَّ الأتراك العُثمانيِّين واشتراك جيوشِه في الإغارة على أزمير سنة 735، ولكِنَّ نجاحَه في هذه المعركة أعاد له العزمَ على مشروع الحَربِ الصَّليبيَّة، ولكِنْ لم يلبث أن أغارت إنكلترا عليه فانصرَفَ نهائيًّا عن فِكرةِ الحرب الصليبيَّة؛ لدوام حربه مع إنكلترا بما يُعرَفُ اليوم بحرب الم"},{"id":2964,"era":"c8","t":"استعادة محمد الرابع بن إسماعيل ملك غرناطة ثغر جبل طارق .","s":"استنجد محمَّدُ الرابع بن إسماعيل مَلِكُ غرناطة بأبي الحَسَنِ علي بن عثمان مَلِك بني مرين لاستردادِ ثَغرِ جبل طارق من الأسبان الذين استولوا عليه سنة 709 فاستجاب أبو الحسَنِ لهذه الدعوة وأرسل جَيشًا بقيادةِ ابنه أبي مالك، فحصَلَت معركةٌ بَحَريَّةٌ أمام جبل طارق هُزِمَ فيها القشتاليون واستسلمت حاميةُ الجبل فاسترَدَّها المسلمون من الأسبان، ثم بعد فترة تم اغتيال محمد الرابع بن إسماعيل بتحريضٍ من مُنافِ"},{"id":2965,"era":"c8","t":"وفاة قاضي القضاة بدر الدين ابن جماعة .","s":"قاضي القُضاةِ العالِمُ شَيخُ الإسلام بدر الدين أبو عبد الله محمد بن الشيخِ الإمام الزاهد أبي إسحاق إبراهيم بن سعد الله بن جماعة بن حازم بن صخر الكناني الحموي الأصل، وُلِدَ ليلة السبت رابع ربيع الآخر سنة 639 بحماة، وسَمِعَ الحديثَ واشتغل بالعلم، وحصَّل علومًا متعَدِّدة، وتقَدَّم وساد أقرانَه، وباشر تدريسَ القيمرية، ثم وليَ الحُكمَ والخَطابة بالقُدسِ الشريف، ثم نُقِلَ منه إلى قضاء مصر في الأيام الأش"},{"id":2966,"era":"c8","t":"السلطان الناصر محمد بن قلاوون يمنع رمي البندق  .","s":"رسم السُّلطانُ النَّاصِرُ محمَّدُ بن قلاوون بالمنعِ مِن رَميِ البُندُق، وألَّا تُباعَ قِسِيُّها ولا تُعمَل، وذلك لإفسادِ رُماةِ البندق أولادَ الناس، وأنَّ الغالِبَ على من تعاطاه اللُّواطُ والفِسقُ وقِلَّةُ الدين، ونودِيَ بذلك في البلادِ المصريَّة والشاميَّة."},{"id":2967,"era":"c8","t":"السلطان الناصر محمد بن قلاوون يأمر بضرب المنجمين وحبسهم .","s":"رسم السُّلطانُ النَّاصِرُ محمد بن قلاوون بتسليم المنَجِّمينَ إلى والي القاهرة فضُرِبوا وحُبِسوا؛ لإفسادهم حالَ النِّساءِ، فمات منهم أربعةٌ تحت العقوبة، وثلاثةٌ من المسلمين ونصرانيٌّ."},{"id":2968,"era":"c8","t":"السلطان الناصر محمد بن قلاوون يعمل بابًا جديدا للكعبة .","s":"عَمِلَ السُّلطانُ النَّاصِرُ محمد بن قلاوون بابًا من خَشَبِ السنط الأحمر، وصَفَّحه بفِضَّة زِنتُها خمسة وثلاثون ألفَ درهم وثلاثمائة درهم، ومضى به الأميرُ سيف الدين برسبغا الساقي إلى مكَّة، فقُلِعَ باب الكعبة العتيق، ورُكِّبَ هذا الباب وأخذ بنو شيبةَ الباب العتيق، وكان من خَشَبِ الساسم المصَفَّح بالفِضَّة، فوجدوا عليه ستين رطلًا من فِضَّة تقاسَموها فباعوها كلُّ دِرهمٍ بدرهمين، لأجلِ التبَرُّك، (وهذ"},{"id":2969,"era":"c8","t":"سيل عظيم بالمدينة النبوية .","s":"جاء بالمدينةِ النبَويَّة سَيلٌ عَظيمٌ أخَذَ جِمالًا كثيرةً وعشرين فَرَسًا، وخُرِّبَت عِدَّةُ دُورٍ."},{"id":2970,"era":"c8","t":"إلزام اليهود والنصارى بلباس خاص ببغداد .","s":"ألزم صاحِبُ بغدادَ النصارى أن يلبَسوا العمائمَ الزُّرقَ، واليَهودَ أن يَلبَسوا العمائِمَ الصُّفرَ يُمَيِّزُهم عن المسلمينَ؛ اقتداءً بالسلطان المَلِك الناصِرِ بهذه السُّنَّة الحَسَنة."},{"id":2971,"era":"c8","t":"وفاة الحافظ العلامة ابن سيد الناس .","s":"هو الحافِظُ العلَّامة البارع، فتحُ الدين بن أبي الفتح محمد بن الإمام أبي عمرو محمد بن الحافظ أبي بكر محمد بن أحمد بن عبد الله بن محمد بن يحيى بن سيد الناس الربعي اليعمري الإشبيلي ثم المصري، وُلِدَ في العشر الأُوَل من ذي الحجة سنة 671، كان حافِظًا بارعًا أديبًا بليغًا مُتَرَسِّلًا، حَسَن المحاوَرةِ لَطيفَ العبارة، فصيحَ الألفاظ كامِلَ الأدوات لا تُمَلُّ مُحاضَرتُه، كريم الأخلاق زائِدَ الحياء، حسَن "},{"id":2972,"era":"c8","t":"مقتل ياسور أحد ملوك المغول في الحج .","s":"قُتِلَ ياسور أحَدُ ملوك المغول وقتَ رَميِ الجمرات، وكان من خَبَرِه أنَّ مَلِكَ الشرق أبا سعيد بن خربندا المغولي لما قُتِل جوبان أراد إقامةَ ياسور لأنه من عظماء القان التتر، فخُوِّفَ من شجاعته، وأنَّ جوبان كان يريد إقامتَه في الملك، فنَفَر منه أبو سعيد، ثم إنَّه استأذنه في الحَجِّ فأَذِنَ له، وقام له بما يليقُ به، ثم طلب أبو سعيد من المجدِ السلامي وكتب إلى السلطانِ يُعَرِّفُه بأمر ياسور، ويخوِّفُه "},{"id":2973,"era":"c8","t":"قتل وتخريب بطرطوس وإياس على أيدي جيش حلب .","s":"رجع جيشُ حلب إلى مدينة حلب بعد غَزوِهم بلادَ أذنة وطرسوس وإياس، وكان عَدَدُهم عشرةَ آلاف سوى من تَبِعَهم من التركمان، وقد خَرَّبوا وقَتَلوا خلقًا كثيرًا، ولم يعدم منهم سوى رجلٍ واحد غَرِقَ بنهر جاهان، ولكِنْ كان قَتْلُ الكُفَّار مَن كان عندهم من المسلمينَ في تلك البلاد نحوًا من ألف رجل، يوم عيد الفطرِ، فإنَّا لله وإنَّا إليه راجعونَ."},{"id":2974,"era":"c8","t":"وباء ومرض بالمدينة المنورة .","s":"وقع بالمدينةِ النبويَّةِ وَبَاءٌ، فكان يموتُ في كُلِّ يَومٍ خَمسةَ عشر بمَرَض الخوانيق- داء يعسُرُ معه التنفس- ولم يُعهَدْ مثلُ هذا بالمدينةِ الشَّريفةِ."},{"id":2975,"era":"c8","t":"وفاة الشيخ صفي الدين إسحاق الأردبيلي مؤسس الطريقة الصفوية .","s":"هو الشيخُ صفيُّ الدين إسحاقُ بن جبريل الأرْدَبيلي، ويقال: إنَّ نسبَه يرجعُ إلى موسى الكاظم, وهو مؤسِّسُ الطريقة الصفويَّة. ولِدَ صفيُّ الدين بأردبيل سنة 650. درس في مطلع ِحياتِه العلومَ الدينيَّةَ والعقليَّةَ في أردبيل. ثم صار واعظًا صوفيًّا في مدينة أردبيل، ثم أسَّس فرقةً صوفيةً تُسمَّى الإخوان، وقد كثُرَت هذه الفرقةُ في إقليم أذربيجان, ولَمَّا أدركته الجذبة- الجذبُ: مصطلحٌ صوفي يعني: حالًا من أح"},{"id":2976,"era":"c8","t":"تعاقب أحفاد الأردبيلي في رئاسة الطريقة الصفوية إلى قيام دولتهم .","s":"بعد وفاة صفي الدين الأرْدَبيلي مؤسِّس الطريقة الصفوية خلَفَه في مشيخة الطريقة ابنه صدر الدين موسى مدةً طويلة بلغت تسعًا وخمسين عامًا, وكانت السلاطين تعتقِدُ فيه وتزوره، وممن زاره والتمس بركته تيمورلنك، فسأله أن يطلبَ منه أي شيء، فقال له موسى: أطلب منك أن تطلِقَ كل من أخذته من بلاد الروم من التركِ، فأجابه إلى سؤاله فأطلقَ جميع أسرى الترك، فصار أهل الروم يعتقدون في الشيخ صدر الدين والمشايخ من ذريتِه"},{"id":2977,"era":"c8","t":"نائب طرابلس يطلب الإقالة بسبب حرامي بحري .","s":"قُبِضَ على الأمير جمال الدين آقوش الأشرفي المعروفِ بنائب الكرك في يوم الخميس نصف جمادى الآخرة، وهو يومئذٍ نائِبُ طرابلس وسُجِنَ بقلعة صرخد، ثم نقِلَ في مستهل شوال إلى الإسكندرية فسُجِنَ بها، ونزل النشو إلى بيتِه بالقاهرة، وأخذ موجودَه كُلَّه وموجودَ حَريمِه، وعاقَبَ أستادراه، واستقَرَّ عِوَضَه في نيابة طرابلس الأميرُ طينال على عادته، ونُقِلَ بكتمر العلائي إلى نيابة حمص، عوضًا عن بشاش المتوفى، وسبب"},{"id":2978,"era":"c8","t":"إسلام سديد الدولة اليهودي من نواب ملك المغول .","s":"مَرَّ سديدُ الدولة ديانُ اليهودي بقارئٍ يقرأ قَولَه تعالى: {يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَاءً وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا} [النساء: 1], فوَقَف سديدُ الدولة واستعاده قراءتَها، وبكى بكاءً شَديدًا، وقد اجتمَعَ "},{"id":2979,"era":"c8","t":"وفاة الملك أبي سعيد المغولي ملك التتار واضطراب أمر المغول بعده  .","s":"هو القانُ أبو سعيدٍ بهادِرُ بن القان محمد خربندا بن أرغون بن أبغا بن هولاكو المغولي ملك التتار، صاحِبُ العراق والجزيرة وأذربيحان وخراسان والروم. كان من خيارِ مُلوك التَّتار وأحسَنِهم طريقةً وأثبَتِهم على السنَّةِ وأقوَمِهم بها، وقد عَزَّ أهلُ السنة بزمانِه وذَلَّت الرافضة، بخلاف دولةِ أبيه، أبطَلَ عِدَّة مُكوس، وأراق الخمورَ ومَنَع مِن شُربِها، وهَدَم كنائِسَ بغداد ووَرَّث ذوي الأرحام، فإنَّه كان "},{"id":2980,"era":"c8","t":"أحوال مُلك التتار في الشرق بعد وفاة الملك أبي سعيد بن خربندا .","s":"بعد وفاةِ أبي سعيد بن خربندا مَلِك التتار قام بَعدَه أربا كاؤن بن صوصا بن سنجقان بن ملكتمر بن أريغبغا أخي هولاكو بمساعدة الوزير غياث الدين بن رشيد الدين, فلم يوافِقْه علي بادشاه حاكِمُ بغداد في الباطن، واستمال أولادَ سونتاي فلم يوافِقوه، فجمع علي بادشاه المغولَ عليه، وكتب إلى السلطانِ الناصر يَعِدُه بأنه يسَلِّمُ له بغداد ويكونُ نائبًا عنه بها، وسأله في إعانتِه بنجدة على أولاد سونتا تكون مقيمةً عل"},{"id":2981,"era":"c8","t":"اعتقال السلطان الناصر للخليفة العباسي المستكفي بالله .","s":"أمر السُّلطانُ النَّاصِرُ محمَّد بن قلاوون في ثالث عشر ذي القعدة بنَقلِ الخليفة المستكفي بالله أبو الربيع سليمان مِن سَكَنِه بمناظر الكبش إلى قلعةِ الجبل، وأُنزِلَ حيث كان أبوه الحاكِمُ نازلًا، فسكن برج السباع دائمًا بعيالِه، ورُسِمَ على الباب جاندار بالنوبة، وسَكَن ابنُ عَمِّه إبراهيم في برج بجوارِه ومعه عياله، ورُسِمَ عليه جاندار الباب، ومُنِعا من الاجتماعِ بالنَّاسِ."},{"id":2982,"era":"c8","t":"استيلاء بني مرين على تلمسان وانتهاء دولة بني زيان .","s":"توجَّه أبو الحَسَنِ علي بن عثمان المريني من فاس على رأسِ جَيشٍ واستولى على تلمسان التي كانت تحتَ حكم آل زيان، والقضاء على أبي تاشفين عبد الرحمن بن موسى خامس ملوك آل زيان من بني عبد الواد، وبذلك انتهى حكمُ بني زيان وامتَدَّ سلطان المرينيين إلى المغرِبِ الأوسَطِ."},{"id":2983,"era":"c8","t":"نهاية الدولة الإيلخانية وقيام الدولة الجلائرية الشيعية .","s":"بعد مَوتِ أبي سعيد تولى أربا كاؤن معز الدين لكنَّه لم يدُمْ سوى ثلاثة أشهر، حيث كان حَسَنُ بن حسين بن أقبغا بن هولاكو معتقَلًا في بلاد آسيا الصغرى، فأُطلِقَ سَراحُه بعد موت أبي سعيد فانطلق إلى بغداد فخلع أربا كاؤن هذا وجرت بينهم حروبٌ كثيرة كان نهايتها خلع أربا كاؤن وتنصيب محمد بن عنبرجي الإيلخاني، وتمكَّن حسن بن حسين من بغداد وتبريز وأسَّسَ الدولة الجلائرية، ثمَّ إنَّ حسن بن دمرداش سار من آسيا ال"},{"id":2984,"era":"c8","t":"إنشاء أول جامعة عثمانية (مدرسة) في أزمير التي فتحها أورخان  .","s":"كان سلاطينُ العُثمانيِّينَ حَريصينَ على أن يَبنُوا في كُلِّ بَلَدٍ يَفتَحونَه مَسجِدًا، ويُخَصِّصونَ له الأئمَّة والفقهاء، وينشرون الإسلامَ بين أهل هذا البلد، وكان أوَّلُ مسجد أمر ببنائه سنة 687 في عهد أرطغرل والد عثمان، وكان ذلك قبل إعلانِ الدولة رسميًّا. وفى عهد أورخان بن عثمان تم تشييدُ مسجد بورصة، وألحق به بناءًا كبيرًا ليكونَ مَدرسةً للعُلومِ الشَّرعية. وفي سنة 737 سَقَطت مدينةُ أزميت في يد ا"},{"id":2985,"era":"c8","t":"الإفراج عن الخليفة العباسي ثم نفيه إلى بلاد قوص .","s":"أُفرِجَ عن الخليفة من سِجنه بالقلعة يوم الأربعاء من ربيع الأول، فكانت مُدَّةُ اعتقاله خمسة أشهر وسبعة أيام، ثم أُمِرَ به فأخرج إلى قوص، ومعه أولادُه وابنُ عَمِّه، وكُتِبَ لوالي قوص أن يحتَفِظَ بهم، وكان سَبَبُ ذلك أن السلطان لما نزل عن المُلكِ في سنة 708، وحصل الاجتماعُ على المظَفَّر بيبرس وقَلَّدَه المستكفي بالسلطنة، نَقَمَها عليه السلطانُ النَّاصِرُ وأسَرَّها له، ثم لما قام السلطانُ لاسترجاع مُل"},{"id":2986,"era":"c8","t":"وفاة الشيخ العالم الزاهد ابن الحاج المالكي  .","s":"هو الشَّيخُ الزَّاهِدُ أبو عبد الله محمد بن محمد بن محمد بن الحاج الفاسي المغربي نزيلُ مِصرَ العَبدري الفقيه المالكي عُرِفَ بابنِ الحاجِّ، وأخذ عن جماعةٍ منهم الشيخ أبو عبد الله محمد بن سعيد بن أبي جمرة، قَدِمَ القاهرة وسَمِعَ بها الحديث وحَدَّث بها وهو أحدُ المشايخ المشهورين بالزُّهدِ والخير والصلاح، صَحِبَ جماعة من الصلحاء أربابِ القلوب وتخَلَّق بأخلاقهم وأخذ عنهم الطريقةَ, وصَنَّف كتابه المشهور"},{"id":2987,"era":"c8","t":"مطر عظيم بمكة يغمر الكعبة .","s":"في عاشر جمادى الأولى استهَلَّ الغيث بمكَّةَ مِن أول الليل، فلما انتصف الليلُ جاء سيلٌ عظيمٌ هائِلٌ لم يُرَ مِثلُه من دهر طويل، فخَرَّب دورا كثيرةً نَحوًا من ثلاثين أو أكثر، وغَرِقَ جماعة وكَسَرَ أبواب المسجد، ودخل الكعبةَ وارتفع فيها نحوًا من ذراعٍ أو أكثر."},{"id":2988,"era":"c8","t":"تسيير جيش إلى سيس .","s":"توجَّهت تجريدةٌ- جيش لا رجَّالةَ فيه- في خامس عشر شعبان إلى بلاد سيس، وسبَبُ ذلك وصول رسول القان موسى وعلي بادشاه بطلب النَّجدة على الشيخ حسن الكبير وطغاي بن سونتاي وأولاد دمرداش ليكون علي بادشاه نائب السلطنة ببغداد، فاستشار السلطانُ نائب الشام والأمراء، واستقَرَّ الرأي على تجريد العسكر نحو سيس؛ فإن تكفور نقض الهُدنةَ بقَبضِه على عِدَّة مماليك وإرسالِهم إلى مدينة إياس، فلم يُعلَمْ خَبَرُهم وقَطَع "},{"id":2989,"era":"c8","t":"فتح قلعة إياس من بلاد سيس .","s":"لما سار الجيش الذي قَدِمَ من القاهرة في ثاني عشر شعبان، وقَدِموا دمشق تلقَّاهم الأمير تنكز، ولم يعبأْ تنكز بالأمير أرقطاي مُقَدَّم العسكر لِما في نفسه منه، ومَضَوا إلى حلب، فقدموها في رابع عشر رمضان، وأقاموا بها يومين فقدم الأمير قطلوبغا الفخري بعساكرِ الشام، وقد وصل إلى جعبر ثمَّ ساروا جميعًا يومَ عيد الفطر، ومعهم الأميرُ علاء الدين ألطبغا نائب حلب، وهو مُقَدَّم على العسكر جميعًا، حتى نزلوا على ا"},{"id":2990,"era":"c8","t":"وفاة الحافظ المؤرخ علم الدين البرزالي  .","s":"هو الحافِظُ المؤَرِّخ عَلَم الدين القاسم بن محمد بن يوسف بن محمد البرزالي الأشبيلي الشافعي، وُلِدَ بدمشق سنة 665, من أُسرةٍ عِلميَّة جاءت من المغرب، وكانت أسرتُه قد نزلت إشبيليَّةَ، ثم رَحَلت إلى الشام وبرزالة: قبيلة قليلة جدًّا، كان البرزالي محدِّثًا حافظًا فاضلًا، سَمِعَ الكثير ورحل إلى البلاد وحصَّل ودأب وسَمِعَ خلائِقَ كثيرةً تزيد عِدَّتُهم على ألفي شيخ، وحَدَّث وخرَّج وأفاد وأفتى وصَنَّف تاري"},{"id":2991,"era":"c8","t":"حسن الجلائري يطلب من السلطان الناصر عسكرا لاستلام بغداد .","s":"قَدِمَ رَسولُ الشيخ حسن بن الأمير حسين بن آقبغا بن أيدكين سبط القان أرغون أبغا بن هولاكو بن طولي بن جنكيزخان متولي العراق، بكتابه يتَضَمَّنُ طَلَبَ عسكر يتسَلَّمُ بغداد والمَوصِل وعراق العجم ليقامَ بها الدعوةُ للسلطان الناصر محمد بن قلاوون، وسأل أن يَبعَثَ السلطان إلى طغاي بن سونتاي في الصلحِ بينه وبين الشيخ حسن، فأجيب إلى ذلك، ووُعِدَ بتجهيز العسكر، ورَكِبَ أمير أحمد قريب السلطان إلى طغاي ومعه هد"},{"id":2992,"era":"c8","t":"إنشاء المدرسة الأقبغاوية في الجامع الأزهر .","s":"أنشأها الأمير علاء الدين أقبغا عبد الواحد، مقدَّم المماليك في عهد السلطان الناصر محمد بن قلاوون. وكان موضِعُ هذه المدرسة دارًا للأمير الكبير عز الدين أيدمر الحلي. وعندما تمَّ بناءُ المدرسة قرَّر فيها الأميرُ أقبغا درسًا للشافعية، ودرسًا للحنفية، ورتَّب لها ما يلزمُها من المستخدَمين. وظلَّت هذه المدرسة عامرةً إلى سنة 845 هـ / 1442م, ويشغلُها الآن جزءٌ من مكتبةِ الجامع الأزهر."},{"id":2993,"era":"c8","t":"توالي غزوات الأسبان على غرناطة .","s":"والى ألفونسو الحادي عشر مَلِكُ قشتالة غزواتِه على مملكةِ غرناطة؛ مما اضطر أبا الحَجَّاج يوسف ملك غرناطة أن يستنجِدَ بملك بني مرين أبي الحَسَنِ علي بن عثمان، فأرسل إليه الأخيرُ جَيشًا بقيادة ابنه أبي مالك، فواجه هذا الجيشُ جيش ثلاث دول هي قشتالة وأراغون والبرتغال، فكانت نهايةُ المعركة موتَ أبي مالك وانهزام الجيش المُسلِم."},{"id":2994,"era":"c8","t":"وفاة النشو القبطي ناظر الخاص للسلطان بعد أن كثر ظلمه للرعية .","s":"هو شَرَفُ الدين عبد الوهاب بن التاج فضل الله المعروف بالنشو القبطي ناظِرُ الخاص للسلطان، كان أبوه يكتُبُ عند الأمير بكتمر الحاحب وهو ينوب عنه، ثم انتقل إلى مباشرةِ ديوان الأمير أركتمر الجمدار، وعندما جمَعَ السلطان الناصر كتَّاب الأمراء, فرآه وهو واقِفٌ وراء الجميعِ وهو شابٌّ طويل نصراني حلوُ الوجه فاستدعاه وقال: أيش اسمك؟ قال: النشو، فقال: أنا أجعلك نشوي، ثمَّ إنه رتَّبَه مستوفيًا في الجيزية، وأقب"},{"id":2995,"era":"c8","t":"وفاة الخليفة العباسي المستكفي بالله بمصر وخلفه الواثق بالله إبراهيم .","s":"هو الخليفةُ المستكفي بالله أبو الربيع سليمان ابن الخليفة الحاكِمُ بأمر الله أبو العباس أحمد بن الحسن بن أبي بكر بن أبي علي بن الحسن العباسي، توفِّيَ بمدينة قوص في منفاه، عن ست وخمسين سنة وستة أشهر وأحد عشر يومًا، في خامِس شعبان، وكانت خلافتُه تسعًا وثلاثين سنة وشهرين وثلاثة عشر يومًا، ثم خُطِبَ للخليفة الواثق بالله إبراهيم بن محمد المستمسك بن أحمد الحاكم بأمر الله، وذلك أنَّ الخبَرَ قَدِمَ في يوم "},{"id":2996,"era":"c8","t":"أخذ السلطان الناصر البيعة بالخلافة لإبراهيم الواثق بالله .","s":"كان الخليفةُ المستكفي بالله قد أوصى بالخلافةِ مِن بعده لابنه أحمد، لكِنَّ السلطانَ النَّاصِرَ لم يُمضِ للسلطان عهده, وكان قد بايع لإبراهيمَ بن محمد المستمسك بن أحمد الحاكم بأمر الله ولَقَّبَه بالواثق بالله, وفي يوم الاثنين خامس عشر شعبان طلب الناصِرُ إبراهيمَ الواثق بالله، وأجلسه بجانِبِه وحادَثَه، ثم قام إبراهيم وخرج معه الحُجَّاب بين يديه، ثم طلع إلى السلطانِ في يوم الاثنين ثالث عشر رمضان، وقد ا"},{"id":2997,"era":"c8","t":"جماعة من النصارى يحرقون المسجد الأموي وسوقًا كبيرًا بدمشق .","s":"اجتمَعَ جماعةٌ من رؤوس النصارى في كنيستِهم وجَمَعوا من بينهم مالًا جزيلًا فدَفَعوه إلى راهبينِ قَدِما عليهما من بلاد الروم، يُحسِنانِ صَنعةَ النِّفطِ، اسم أحدِهما ملاني، والآخر عازر، فعملا كحطًا من نفط، وتلطَّفا حتى عملاه لا يظهَرُ تأثيرُه إلا بعد أربع ساعات وأكثر من ذلك، فوُضِعا في شقوق دكاكين التجَّار بسوق الرجال في عدَّة دكاكين من آخِرِ النهار، بحيث لا يشعُرُ أحَدٌ بهما، وهما في زي المُسلِمينَ،"},{"id":2998,"era":"c8","t":"مقتل الأمير سيف الدين تنكز نائب السلطان الناصر على دمشق .","s":"هو الأميرُ الكبيرُ المَهيبُ سَيفُ الدين أبو سعيد تنكز نائِبُ السلطنة بالشام، جُلِبَ إلى مصر وهو حَدَثٌ، فنشأ بها، وكان أبيض يميل إلى السمرة، رشيق القَدِّ، مليح الشَّعر، خفيف اللحية قليل الشَّيب، حَسَن الشَّكلِ، جلبه الخواجا علاء الدين السيواسي، فاشتراه الأمير حسام الدين لاجين، فلما قُتِلَ لاجين في سلطنته صار من خاصكية السلطان الناصر، وشهد معه وقعة وادي الخزندار ثم وقعة شقحب، سمع صحيح البخاري غير م"},{"id":2999,"era":"c8","t":"هزيمة المسلمين في وقعة طريف بالأندلس  .","s":"قام المَلِكُ أبو الحَسَن علي بن عثمان مَلِكُ بني مرين باجتيازِ البحرِ على رأسٍ جيشٍ كثيفٍ لمحاربةِ المتحالفين من قشتالة والبرتغال وأراغون، فجَرَت بينهم معركةٌ قُربَ مدينة طريف انكسَرَ فيها جيشُ المسلمين المكَوَّن من جيش بني مرين وجيش غرناطة، وسَقَط معسكرُ الملك المريني بيد الأسبان فذبحوهم بأجمَعِهم واستطاع المَلِكُ المريني عبورَ البحر إلى المغرب مع بعضِ فلول جيشِه، وانهزم مَلِكُ غرناطة إلى غرناطة "},{"id":3000,"era":"c8","t":"مقتل عثمان الدكاكي على الزندقة بدمشق .","s":"هو الصوفيُّ الاتحادي عثمان الدكاكي الدمشقي, خالطَ الصوفية ودعاةَ وَحدةِ الوجودِ، فتأثَّرَ بهم حتى ادَّعى الألوهيَّةَ وانتَقَص من الأنبياء, فعُقِدَ له مجلسٌ في دار العدل بدار السعادة في يوم الثلاثاء آخر شَهرِ شوال واجتَمَع القضاة والأعيانُ على العادة وأُحضِرَ يومئذ عثمان الدكاكي، وادُّعِيَ عليه بعظائمَ من القول لم يؤثَرْ مِثلُها عن الحلَّاجِ ولا عن ابن أبي الغدافر السلقماني، وقامت عليه البيِّنةُ بد"},{"id":3001,"era":"c8","t":"تجهيز عساكر إلى توريز لتسلُّمِها من حكامها التتار .","s":"كتب السُّلطانُ النَّاصِرُ بتَجهيزِ عساكِرِ دمشق وحَلَب وغيرهما للتجريدةِ إلى توريز، صحبة الأمير طشتمر نائب حلب، ويكونُ معه عامَّةُ أمراء التركمان والعربان، فتجَهَّزَ الأمراء والأجناد بمماليك الشام، وبَرَز نائب حلب بمخيَّمِه إلى ظاهر المدينة وأقام ينتَظِرُ قدومَ عساكِرِ مصر، فأصبح السلطان في مستهَلِّ ذي الحجة وبه وَعكٌ من قرف حدث عنه إسهالٌ لزم منه الفِراشَ خمسةَ أيام، فتصَدَّقَ بمال جزيل، وأفرَجَ "},{"id":3002,"era":"c8","t":"وفاة السلطان الناصر محمد بن قلاوون وتولي ابنه المنصور بعده .","s":"هو السلطانُ الملك الناصر، ناصر الدين أبو الفتح محمد ابن السلطان الملك المنصور سيف الدنيا والدين قلاوون، وُلِدَ الملك الناصر سنة 684، وكان قد أقيمَ النَّاصِرُ في السلطنة بعد أخيه الملك الأشرف خليل سنة 693، وعُمُرُه تسع سنين ثمَّ خُلِعَ في سادس عشر المحرم سنة أربع وتسعين، وأُرسِلَ إلى الكرك, ثمَّ أعيد إلى المُلكِ ثانيًا وعمره خمس عشرة سنة، فأقام في المُلك إلى سنة 708، وخرج يريدُ الحَجَّ، فتوجه إلى ا"},{"id":3003,"era":"c8","t":"وفاة الملك أزبك خان ملك التتار المسلم في منطقة الروم وتولي ابنه بعده .","s":"هو المَلِكُ أزبك خان بن طغرلجا بن منكوتمر بن طغان بن باطو بن دوشي خان بن جنكز خان ملك التتار، وكان أسلَمَ وحَسُنَ إسلامُه وحَرَّض رعيَّتَه على الإسلام، فأسلم بعضهم، ولم يلبَسْ أزبك خان بعد أن أسَلَم السراقوجات- لباس الرأس عند التتار- وكان يلبس حياصةً من فولاذ ويقول: لبسُ الذَّهَبِ حرامٌ على الرجال، وكان يميلُ إلى دينٍ وخَيرٍ، ويتردَّدُ إلى الفقراء، وكان عنده عَدلٌ في رعيته، وتزوَّجَ الملك الناصِرُ"},{"id":3004,"era":"c8","t":"خلع الخليفة العباسي الواثق وتولية الحاكم بأمر الله أحمد المستكفي .","s":"كان السُّلطانُ مُحمَّدُ بن قلاوون قَبلَ وَفاتِه أوصى بأن يُعادَ أحمدُ بنُ سُليمان للخلافةِ على ما كان أبوه عَهِدَ إليه، وأشهد على ذلك أربعين عَدلًا وقاضيَ قوصٍ وغيرَه من الفقهاء والقُضاة، ففي أوَّلِ هذه السنة أحضر السلطانُ المنصورُ بن محمد بن قلاوون الخليفةَ الواثِقَ إبراهيمَ وخَلَعَه بناءً على وصيَّةِ المستكفي لابنِه أحمد، وبايع القُضاةُ والسلطانُ أحمدَ بنَ سليمان المستكفي ولقَبَّه الحاكِمَ بأمر "},{"id":3005,"era":"c8","t":"وفاة الحافظ أبي الحجاج المِزِّيِّ .","s":"هو الشيخُ الإمامُ العلَّامة الحافِظُ حُجَّة العصرِ، ومحَدِّثُ الشام ومصر وخاتمةُ الحُفَّاظ جمال الدين أبو الحجاج يوسف بن الزكي عبد الرحمن بن يوسف بن علي بن عبد الملك بن أبي الزهر القضاعي الكلبي المزِّي الحلبي المولد، وُلِدَ بظاهر حَلَب في عاشر ربيع الآخر سنة 654، وكان إمامَ عَصرِه وأحَدَ الحُفَّاظ المشهورين، نشأ بالمزَّة بالقُربِ مِن دمشق, فحَفِظَ القرآن الكريم وعُنِيَ باللغةِ وبَرَع فيها وأتقَنَ "},{"id":3006,"era":"c8","t":"خلع السلطان المنصور أبي بكر وتولية أخيه الأشرف كجك .","s":"لَمَّا تَسلطَنَ المَلِكُ المنصور أبو بكر، أصبح همُّه ملذَّات نفسِه، فأصبح هذا شيئًا شائعًا عنه يعرِفُه القاصي والداني، حتى أصبح معروفًا بالشرب وجَلْب المغنيات إلى قَصرِه، حتى قال الأميرُ قوصون الناصري: أهكذا يكون أمرُ سُلطان المسلمين؟! أهكذا كان أبوه يفعَلُ؟! وكانت هذه الكَلِمةُ منه سببًا في الوحشة التي حَصَلت بعد ذلك، ثمَّ لَمَّا استفحل هذا الأمرُ مِن السلطان، قرَّر الأمراءُ خَلْعَه وإخراجَه وإخو"},{"id":3007,"era":"c8","t":"وفاة الملك الأفضل صاحب حماة وتولي ابنه بعده .","s":"هو الملِكُ الأفضَلُ علاء الدين عليُّ ابنُ المَلِك المؤيَّد عماد الدين إسماعيل ابن الملك الأفضل علي ابن الملك المظفر محمود ابن الملك المنصور محمد ابن الملك المظفر تقي الدين عمر بن شاهنشاه ابن الأمير نجم الدين أيوب بن شادي الأيوبي صاحِب حماة وابن صاحبها، مات بدمشقَ، وهو من جملةِ أمرائها بعدما باشر سلطنةَ حماة عشرينَ سَنةً إلى أن نقَلَه قوصون إلى إمرة الشام؛ وولِيَ نيابةَ حماة بعده الأميرُ طقزدمر الح"},{"id":3008,"era":"c8","t":"خلع السلطان الأشرف كجك وتولية أخيه الناصر أحمد .","s":"في يومِ الخَميسِ أول شعبان خُلِعَ السُّلطانُ المَلِكُ الأشرف علاء الدين كجك من السُّلطة، وكانت مدته خمسة أشهر وعشرة أيام لم يكُنْ له فيها أمرٌ ولا نهي، وتدبيرُ أمورِ الدَّولةِ كُلِّها إلى قوصون، وكان إذا حضرت العلائِمُ أعطِيَ السُّلطانُ قَلمًا في يده وجاء فقيهُه المغربيُّ الذي يقرئ أولادَ السلطان ويكتبُ العلامةَ والقَلمُ في يد السلطانِ علاء الدين، فلما استولى الأميرُ أيدغمش على الدَّولةِ بعد قوصون"},{"id":3009,"era":"c8","t":"الحرب بين ملك قشتالة وملك بني مرين .","s":"بعد هزيمةِ جَيشِ مَلِك المرينيين أمام تحالُفِ الأسبان، تشَجَّع مَلِكُ قشتالةَ للعَودِ إلى غزو غرناطةَ فتابعَ حُروبَه عليها واستولى على قلعةِ بني سعيدٍ، فأثار هذا الحميَّةَ لدى مَلِك بني مرين أبي الحَسَن علي بن عثمان، فأراد الانتقامَ مِن هزيمتِه الماضية، فأرسل أسطولًا بحريًّا إلى بحرِ الزقاق من مضيقِ جَبل طارق، فالتقى بجيش قشتالة في معركةٍ بحرية كانت فيها هزيمةُ جيش مَلِك بني مرين مرة أخرى، وتمَزُّ"},{"id":3010,"era":"c8","t":"خلع السلطان الناصر أحمد وتولية أخيه الصالح إسماعيل .","s":"أهلَّت هذه السَّنةُ والنَّاسُ في أمرٍ مَريجٍ؛ لغيبة السلطانِ النَّاصِرِ أحمد بالكرك، وعند الأمراءِ تشوُّش كبير، ثمَّ قَدِمَ كِتابُ السلطان إلى الأمراءِ يُطَيِّبُ خواطِرَهم، ويُعَرِّفُهم أنَّ مِصرَ والشام والكرك له، وأنَّه حيث شاء أقام، ورسم أن تُجهَّزَ له الأغنامُ مِن بلاد الصعيد، وأكَّد في ذلك، وأوصى آقسنقر بأن يكون مُتَّفِقًا مع الأمراءِ على ما يكون من المصالحِ، فتنكَّرَت قلوبُ الأمراء ونفَرَت خ"},{"id":3011,"era":"c8","t":"محاصرة الجيوش المصرية والشامية حصن الكرك .","s":"لَمَّا خُلِعَ السلطانُ الناصِرُ تحصَّن بالكركِ، فرَسَم السلطانُ الصَّالِحُ إسماعيلُ بإحضار المجرَّدين إلى الكرك وعيَّنَ عِوَضَهم تجريدةً أخرى إلى الكرك، وهي التجريدةُ السابعة، فيها الأميرُ بيبرس الأحمدي، والأمير كوكاي، وعشرون أمير طبلخاناه، وستة عشر أمير عشرة، وكتب بخروج عسكرٍ أيضًا من دمشق ومعهم المنجنيق والزحَّافات، وأرسل أيضًا مع الأحمدي أربعةَ آلاف دينار لِمن عساه ينزِلُ إليه من قلعة الكركِ طا"},{"id":3012,"era":"c8","t":"فتنة الأعراب في الحج .","s":"في يومِ عَرَفةَ بعَرَفةَ وقعت فتنةٌ بين العَرَبِ والحُجَّاج من قَبلِ الظُّهرِ إلى غروبِ الشَّمسِ، قُتِلَ فيها جماعةٌ، وسَبَبُها أنَّ الشَّريفَ رُميثة بن أبي نُمي أميرَ مكَّةَ شكا من بني حَسَن إلى أميرِ الحاجِّ، فركِبَ أميرُ الحاجِّ في يوم عرفة بعرفة لحَربِهم، وقاتَلَهم وقَتَلَ مِن التُّركِ سِتَّة عشر فارسًا، وقَتَل من جماعةِ بني حسن عِدَّة، وانهزم بقيَّتُهم، فنفر النَّاسُ مِن عَرَفةَ على تخوُّف، و"},{"id":3013,"era":"c8","t":"خلع نائب السلطان الأمير أقسنقر السلاري وتولية الأمير الحاج .","s":"كان الأميرُ أقسنقر السلاري في نيابتِه لا يَرُدُّ قصَّةً تُرفَعُ إليه، فقصده الناسُ مِن الأقطار وسألوه الرِّزقَ والأراضيَ التي أنْهَوا أنها لم تكنْ بيَدِ أحَدٍ، وكذلك نيابات القلاع وولايات الأعمالِ والرواتب وإقطاعات الحلقة. فلم يرُدَّ أحدًا سأله شيئًا من ذلك سواءٌ كان ما أنهاه صحيحًا أم باطلًا. فإذا قيل له: هذا الذي أنهاه يحتاجُ إلى كَشفٍ، تغَيَّرَ وَجهُه وقال: ليش تقطع رزق الناسِ؟ فإذا كتَبَ بالإق"},{"id":3014,"era":"c8","t":"فتنة الناس بوجود قبر صحابي في القاهرة وبيان دجل هذه الإشاعة .","s":"اتَّفَق بظاهِرِ القاهرةِ أمرٌ اعتُنِي بضَبطِه، وهو أنَّه كان بناحية اللوق كوم يُعرفُ بكوم الزل يأوي إليه أهلُ الفسوق من أوباشِ العامَّة، فأخذ بعضُهم منه مَوضِعًا ليبنيَ له فيه بيتًا، فشَرَع في نقل الترابِ منه، فبينا هو يحفِرُ إذ ظهر له إناءُ فخَّار فيه مكاتيبُ دار كانت في هذا البُقعةِ، وتدُلُّ على أنه كان به أيضًا مَسجِدٌ، ورأى آثار البنيان، فأشاع أحدُ شياطينِ العامَّة- وكان يقال له شُعَيبٌ- أنَّه"},{"id":3015,"era":"c8","t":"والي القاهرة يخرب سجن الأسارى ويمنع الخمور في البلاد .","s":"أمر نائِبُ السُّلطانِ الأميرُ الحاج آل ملك والي القاهرة بأن يُنزَل إلى خزانة البنود بالقاهرة، ويُحتاطَ على ما بها من الخَمرِ والبغايا، ويخرج مَن فيها من النَّصارى الأسرى، ويريق ما هناك من الخُمور، ويخرِّبها حتى يجعَلَها دكًّا، وسبَبُ ذلك أنَّ خِزانةَ البنود كانت يومئذٍ حانةً، بعدما كانت سجنًا يُسجَنُ فيه الأمراءُ والجُندُ والمماليك، كما أنَّ خِزانةَ شمائِل سجنٌ لأرباب الجرائِمِ من اللصوصِ وقُطَّاع"},{"id":3016,"era":"c8","t":"إسلام ملك الهند وطلبه إرسال فقهاء ليعلموهم أمور دينهم .","s":"وصَلَت رسُلُ مَلِك الهند بهَديَّة فيها فصان ياقوت، ومعهم كتابٌ يتضَمَّنُ السلام والمودَّة، وأنَّهم لم يكونوا يَعرِفونَ الإسلامَ حتى أتاهم رجلٌ عَرَّفَهم ذلك، وذكرَ لهم أنَّ ولاية المَلِك لا بُدَّ أن تكون من الخليفةِ، وسأل مَلِكُ الهند أن يُكتَبَ له تقليدٌ مِن جهة الخليفة بولايةِ مَملكةِ الهند ليكونَ نائبًا عن السلطانِ بتلك البلاد، وأن يَبعَثَ السُّلطانُ إليهم رجلًا يعَلِّمُهم شرائِعَ الإسلام من ال"},{"id":3017,"era":"c8","t":"وفاة الشيخ الإمام ابن عبدالهادي الحنبلي .","s":"هو الشَّيخُ الإمامُ العلَّامة الناقِدُ في فنون العلوم: شمس الدين أبو عبد الله محمد بن الشيخ عماد الدين أحمد بن عبد الهادي بن عبد الحميد بن عبد الهادي بن يوسف بن محمد بن قدامة المقدسي الحنبلي، من تلاميذ شيخِ الإسلامِ ابنِ تيميَّةَ. كان مولِدُه في رجب سنة 705. توفي ولم يبلغِ الأربعين، وكان قد حَصَّل من العلومِ ما لا يَبلُغُه الشُّيوخُ الكبار، وتفَنَّنَ في الحديث والنحو والتصريف والفقه والتفسير والأص"},{"id":3018,"era":"c8","t":"مقتل حسن السكاكيني على الرفض الدال على الكفر المحض .","s":"هو حَسَنُ بن الشيخ محمد السكاكيني، كان والده الشيخ محمد السكاكيني يَعرِفُ مَذهَب الرافِضةِ الشِّيعةِ جَيِّدًا، وكانت له أسئلةٌ على مذهب أهلِ الجَبْرِ، ونَظَم في ذلك قصيدةً أجابه فيها شيخُ الإسلامِ ابنُ تيميَّةَ رحمه الله، وذكر غيرُ واحدٍ مِن أصحابِ الشَّيخِ أنَّ السكاكيني ما مات حتى رجع عن مذهَبِه، وصار إلى قَولِ أهلِ السنَّةِ، فالله أعلم، وقيل إنَّ وَلَدَه حَسَنًا هذا القبيحَ، كان قد أراد قَتْلَ "},{"id":3019,"era":"c8","t":"فتنة الأعراب بصعيد مصر والشام .","s":"قَدِمَ الخَبَرُ بنفاقِ عُربان الوجه القبلي، وقَطْعِهم الطُّرُقات على الناس، وامتدادِ الفِتَن بينهم نحو شهرينِ قُتِلَ فيها خلقٌ عظيم، وأنَّ عَربَ الفيومِ أغار بعضُهم على بعض، وذبحوا الأطفالَ على صدورِ أمَّهاتهم، فقُتِلَ بينهم قتلى كثيرٌ، وأخربوا ذاتَ الصفا، ومنعوا الخراجَ في الجبال، وقطعوا المياهَ حتى شَرِقَ أكثَرُ بلاد الفيوم، فلم يلتَفِت أمراءُ الدولة لذلك؛ لشُغلِهم بالصَّيدِ ونحوه، وفيه قَدِمَ ا"},{"id":3020,"era":"c8","t":"نساء السلطان وجواريه يبتدعن لباسا مترفا ثم يمنعن من لبسه .","s":"أبطل نائِبُ السُّلطانِ الأميرُ الحاج آل ملك ما أحدَثَه النِّساءُ مِن مَلابسِهنَّ، وذلك أنَّ الخواتينَ نساءَ السُّلطانِ وجواريَهنَّ أحدَثْنَ قُمصانًا طِوالًا تخبُّ أذيالها على الأرضِ، بأكمامٍ سَعةِ الكُمِّ منها ثلاثةُ أذرع، فإذا أرخَتْه الواحدةُ منهن غطَّى رِجْلَها، وعُرِفَ القَميصُ منها فيما بينهنَّ بالبهطلة، ومَبلَغُ مَصروفِه ألفُ درهم ممَّا فوقها! وتشَبَّه نِساءُ القاهرة بهن في ذلك، حتى لم يبقَ "},{"id":3021,"era":"c8","t":"وفاة الشيخ الإمام أثير الدين أبو حيان الغرناطي .","s":"هو الشَّيخُ العلَّامةُ الإمامُ الحافِظُ فَريدُ العَصرِ وشَيخُ الزَّمانِ، وإمامُ النُّحاةِ: أثيرُ الدين أبو حيَّان محمَّد بن يوسف بن علي بن يوسف بن حيان الغرناطي المغربي المالكيُّ ثمَّ الشافعيُّ شَيخُ البلاد المصريَّة، مَولِدُه بغرناطة في أُخريات شوال سنة 654. قرأ القرآنَ بالرِّوايات، واشتغَلَ وسَمِعَ الحديثَ بالأندلس وإفريقيَّة والإسكندريَّة والقاهرة والحجاز، وحصَّل الإجازاتِ من الشام والعراق، واج"},{"id":3022,"era":"c8","t":"مطر وثلج وهبوب ريح حارة شديدة بدمشق ومصر .","s":"كثُرَ سُقوطُ الثَّلجِ بدِمشقَ حتى خرج عن العادةِ، وأنفقوا على إزالته من الأسطحِ ما ينيفُ على ثمانين ألف درهم؛ فإنَّه أقام يسقط أسبوعين، وفي هذه السنة تواتَرَ سُقوطُ البرد بأرض مصرَ، مع ريحٍ سوداء، وشَعَث عظيمٍ، وبَرقٍ ورَعدٍ سهول، ثم أعقب ذلك عامٌ شديد الحر، بحيث تطاير منها شَرَرٌ أحرق رؤوسَ الأشجار، وزريعة الباذنجان وبعض الكتَّان، حتى اشتد خوف الناس، وضجُّوا إلى الله تعالى، وجاء مطرٌ غزير، ثم بَر"},{"id":3023,"era":"c8","t":"اعتنق أهل سومطرة بإندونيسيا الإسلام وتولى الملك عليهم مسلم  .","s":"ذكَرَ الرحَّالةُ ابنُ بطُّوطة عن مشاهدتِه لجزيرة سومطرة والإسلام فيها، ووصَفَ سُلطانَها قائِلًا: \"وهو السلطانُ المَلِكُ الظاهر من فُضَلاءِ الملوك، شافعيُّ المذهب محِبٌّ للفقهاء، يحضرون مجلِسَه للقراءة والمذاكرة، وهو كثيرُ الغزو والجهاد ومتواضِعٌ يأتي إلى صلاة الجمعة ماشيًا على قَدَميه وأهل بلاده شافعيَّةٌ محبُّون للجهاد يخرجون معه تطوعًا، وهم غالبون على من يليهم من الكُفَّار والكُفَّارُ يعطون الجز"},{"id":3024,"era":"c8","t":"وفاة السلطان الصالح إسماعيل بن الناصر وتولي أخيه الكامل شعبان .","s":"هو السُّلطانُ عِمادُ الدين المَلِكُ الصَّالحُ إسماعيل بن الناصر محمد بن المنصور قلاوون؛ في ربيع الأول اشتَدَّ مَرَضُ الملك الصالح إسماعيل فدخل عليه زَوجُ أمِّه ومُدَبِّرُ مَملكتِه الأمير أرغون العلائي في عِدَّة من الأمراء لِيَعهَدَ الملك الصالحُ إسماعيل بالمُلكِ لأحدٍ مِن إخوته, وكان أرغون العلائي غَرَضُه عند أخيه شعبان؛ لكونه أيضًا ربيبَه ابنَ زوجتِه, فعارضه في شعبانَ الأميرُ آل ملك نائِبُ السلطن"},{"id":3025,"era":"c8","t":"خراب سيس بسبب ظلمهم .","s":"قَصَد نائِبُ حَلَب سيس لطَلَب الحملِ، وقد كان تكفور صاحِبُها قد كتب في الصالحِ إسماعيل بأنَّ بلادَه خَرِبَت، فسُومِحَ بنِصفِ الخراج، فلمَّا وصل إليه قاصِدُ نائب حلب جَهَّز الحمل، وحضر كبيرُ دولته ليحَلِّفوه أنَّه ما بقى أسيرٌ مِن المسلمين في مملكتِه، كما جَرَت العادة في كل سنةٍ بتَحليفِه على ذلك، وكان في أيديهم عِدَّةٌ من المسلمين أسرى، فبَيَّتَ مع أصحابِه قَتْلَهم في الليلةِ التي تكونُ خلفه في صب"},{"id":3026,"era":"c8","t":"فتنة الأعراب بالصعيد .","s":"اشتَدَّ فسادُ العُربان بالصعيد والفيوم والإطفيحيَّة، فأخرج الأميرُ غرلو إلى إطفيح فأمَّنَ غرلو شيخَ العربان مغنى، وأخذ في التحيُّل على نُمَي حتى قَبَض عليه، وسَلَّمَه لمغنى، فعذبه عذابًا شديدًا، فثار أصحابُه، وكبسوا الحيَّ وتلك النواحيَ، وكَسَروا عرب المغنى، وقتلوا منهم ثلاثمائةِ رَجُل وستين امرأة، وذبحوا الأطفالَ، ونهبوا الأجرانَ وهدموا البيوت، ولَحِقوا بعربان الصعيد والفيوم فكانت عِدَّةُ مَن قُت"},{"id":3027,"era":"c8","t":"خروج يلبغا اليحياوي نائب دمشق عن طاعة السلطان شعبان .","s":"انشغل السُّلطانُ المَلِكُ الكامِلُ شَعبان بملذَّاته وملاهيه وأعرض عن تدبيرِ الأمور، فتمَرَّدَت المماليكُ، وأخذوا حرم النَّاسِ، وقطعوا الطريقَ، وفَسَدت عِدَّةٌ من الجواري، وكَثُرَت الفِتَنُ بسَبَبِ ذلك حتى بلغ السلطانَ، فلم يعبأ بهذا، وقال: \" خلُّوا كُلَّ أحد يعمَلُ ما يريدُ!!\"، وقد تظاهر الناسُ بكلِّ قَبيحٍ، فاشتَدَّ الأمرُ على الناس بديار مصر وبلاد الشام، وكَثُرَ دعاؤهم لما هم فيه من السُّخر والم"},{"id":3028,"era":"c8","t":"وفاة الأمير الحاج سيف الدين آل ملك الجوكندار الناصري .","s":"هو الأميرُ الكبيرُ سَيفُ الدين الحاج آل ملك الجوكندار الناصري، نائِبُ السَّلطنة بالديار المصرية، أصله من كسب الأبلستين في الأيام الظاهريَّة بيبرس في سنة 676، واشتراه قلاوون ومعه سلَّار النائب، فأنعم بسلار على ولَدِه علي، وأنعم بآل ملك هذا على ولَدِه الآخر, وقيل قدَّمَه لصِهْرِه الملك السعيد بركة خان ابن الملك الظاهر بيبرس، فأعطاه الملك السعيد لكوندك, وترقَّى آل ملك في الخَدَم إلى أن صار من جملةِ أ"},{"id":3029,"era":"c8","t":"خلع السلطان الكامل شعبان وقتله وتولية أخيه المظفر حاجي  .","s":"إنَّ الأمراءَ كُلَّهم تنكَّروا للسلطان الملك الكامل شعبان لِما ظهر منه من أمورٍ استوجَبَت بُغضَهم له، فألحَّ السلطان في طَلَبِ أخويه المسجونَينِ حسن وحاجي، ثم حصلت بذلك فِتنةٌ وآلت إلى الحرب بين الأمراء، وطَلَب السلطانُ الأميرَ أرغون العلائي واستشاره، فأشار عليه بأن يركَبَ بنَفسِه إليهم، فركِبَ ومعه الأمير أرغون العلائي وقطلوبغا الكركي وتمر الموساوي، وعِدَّة من المماليك، وأمر السلطانُ فدُقَّت الكو"},{"id":3030,"era":"c8","t":"المرينيون يحتلون تونس وينهون دولة الحفصيين فيها .","s":"بعد وفاةِ أبي يحيى المتوكِّل أبي بكر الحفصي ظهَرَت فِتَنٌ أثارها أمراءُ البيت الحفصي؛ ممَّا أتاح الفرصةَ أمام بني مرين بزعامة مَلِكِهم أبي الحسن علي بن عثمان للانقضاضِ على دولتِهم، فسار إلى تونس واستولى عليها، وفَرَّ أبو الحسن بن أبي حفص عمر الثاني ملك الحفصيينَ، ثمَّ قبض عليه بعد ذلك وقُتِل، فتمَّ للمرينيين مُلكُ المغرب كلِّه الأقصى والأوسط والأدنى."},{"id":3031,"era":"c8","t":"وقعة بين الأرمن والمسلمين في كوار .","s":"قَدِمَ البريدُ مِن حَلَب بأنَّ صاحِبَ سيس جهَّزَ مائتي أرمني إلى ناحية أياس، فلما قَرُبوا من كوار ليهجُموا على قلعتها، قاتَلَهم أربعون من المسلمين، فنصرهم الله على الأرمن، وقَتَلوا منهم خمسينَ، وأسروا ثلاثينَ، وهزموا باقيَهم، فقُتِلَ بكوار عِدَّةٌ مِمَّن أُسِر، وحُمِلَ بقيَّتُهم إلى حلب، فكُتِبَ بالإحسانِ إلى أهل كوار والإنعامِ عليهم."},{"id":3032,"era":"c8","t":"السلطان المظفر حاجي قتل نائبه بالشام يلبغا اليحياوي .","s":"لَمَّا كَثُرَ قَتلُ السلطانِ المظَفَّر حاجي للأمراءِ، أثار حفيظةَ نائِبِ السلطان بالشَّامِ مَلِكِ الأمراء يلبغا اليحياوي عليه، فعَمِلَ على مراسلةِ نائب صفد ونائبِ حماة على أن يتَّفِقوا على قتل السُّلطانِ المظَفَّر كما قَتَل الأمراء؛ حيث زاد شَرُّه وكَثُر الفسادُ، فوافقه نائِبُ حماة في الظاهر، وأوصل الخبَرَ إلى مصر، فسَيَّرَ السلطان جيشًا مع بعض الأمراءِ للقَبضِ على يلبغا وتوليةِ غَيرِه إمرةَ دِمشق"},{"id":3033,"era":"c8","t":"اغتيال السلطان المظفر حاجي وتولية أخيه حسن ناصر الدين .","s":"هو السُّلطانُ المَلِكُ المظَفَّر سيف الدين حاجي بن الناصر محمد بن قلاوون، تولَّى السلطنةَ بعد قَتْلِ أخيه السلطان الكامل شعبان، وعُمُرُه خمس عشرة سنة، وقد حلف للأمراءِ ألَّا يؤذيَهم وحَلَفوا له على الطاعةِ، لكِنْ لَمَّا كَثُرَ اشتِغالُه في اللَّعِبِ بالحَمامِ وتقريب الأوباش واللعَّابين وغيرِهم من أرباب الملاهي والفساد، أنكر عليه الأمراءُ أكثَرَ مِن مَرَّة، حتى حصل بينه وبينهم جفاءٌ, وعمل السلطان ع"},{"id":3034,"era":"c8","t":"وفاة الإمام العلامة الحافظ شمس الدين الذهبي .","s":"هو الشَّيخُ الإمامُ العلَّامة الحافِظُ شَمسُ الدين أبو عبد الله محمد بن أحمد بن عثمان بن قايماز الذهبي خاتمةُ الحُفَّاظ، كان من أسرة تُركمانيَّة الأصل، تنتهي بالولاءِ إلى بني تميم، سكنت مدينة ميافارقين من أشهَرِ مدن ديار بكر، ولِدَ في كفر بطنا قرب مدينة دمشق في شهرِ ربيع الآخر سنة 673, وهو حافِظٌ لا يُجارَى ولافِظٌ لا يُبارى، أتقَنَ عِلمَ الحديث ورجالَه، ونظَرَ عِلَلَه وأحوالَه، وعرف تراجم الناس و"},{"id":3035,"era":"c8","t":"أوضاع دولة الترك في مصر والشام مع مطلع هذا العام .","s":"استهل هذا العامُ وسُلطان البلاد المصرية والشاميَّة الملك الناصر ناصر الدين حسن بن الملك الناصر محمد بن قلاوون، ونائِبُه بالديار المصريَّة الأميرُ سَيفُ الدين يلبغا، ووزيرُه منجك، وقضاتُه عز الدين بن جماعة الشافعي، وتقي الدين الأخنائي المالكي، وعلاء الدين بن التركماني الحنفي، وموفَّق الدين المقدسي الحنبلي، وكاتِبُ سِرِّه القاضي علاء الدين بن محيي الدين بن فضل الله العمري، ونائب الشام المحروس بدمشق "},{"id":3036,"era":"c8","t":"وفاة الشيخ عبد الله بن رشيق المغربي كاتب شيخ الإسلام ابن تيمية .","s":"هو الشَّيخُ عبد الله بن رشيق المغربي، كاتِبُ مُصَنَّفات العلَّامة ابن تيمية، كان أبصَرَ بخَطِّ الشيخ منه، إذا عَزَب شيءٌ منه على الشيخِ استخرجه عبدُ الله هذا، وكان سريعَ الكتابةِ لا بأس به، دَيِّنًا عابدًا كثيرَ التلاوة حَسَن الصلاة، له عيالٌ وعليه ديونٌ."},{"id":3037,"era":"c8","t":"الفتنة بالكرك بين بني نمير وبني ربيعة .","s":"اشتَدَّت الفتنة في بلاد الكرك بين بني نمير وبني ربيعة، فإن المَلِكَ الناصر محمد بن قلاوون كان لَمَّا أعياه أمرُهم وتحصُّنُهم بجبالهم المنيعة، أخذ في الحيلة عليهم، وتقَدَّم إلى شطي أمير بني عقبة، وإلى نائب الشام ونائب غزة ونائب الكرك، بأن يدخُلوا إلى البرية كأنهم يصطادونَ ويوقعونَ بهم، فقبضوا على كثيرٍ منهم، وقَتَلوا في جبالهم خلقا كثيرًا منهم، وحَبَسوا باقيَهم حتى ماتوا، فسَكَن الشرُّ بتلك الجهات "},{"id":3038,"era":"c8","t":"وفاة الشيخ علاء الدين المارديني التركماني الحنفي .","s":"هو الإمامُ الشيخ علاءُ الدين علي ابنُ القاضي فخر الدين عثمان بن إبراهيم بن مصطفى المارديني الحنفي المعروف بالتركماني، ومولِدُه في سنة 683، كان إمامًا فقيهًا بارعًا نحويًّا أصوليًّا لغويًّا، أفتى ودرَّس واشتغل وألَّف وصَنَّف، وكان له معرفةٌ تامَّةٌ بالأدب وأنواعه، وله نظمٌ ونَثرٌ، كان إمامَ عَصرِه لا سيَّما في العلوم العقلية والفقه أيضًا والحديث، وتصدى للإقراءِ عِدَّة سنين، وتولى قضاء الحنفيَّة بال"},{"id":3039,"era":"c8","t":"قتال العشير والعربان بسبب كثرة فسادهم ببلاد القدس ونابلس .","s":"في عاشر جمادى الآخرة خرجت التجريدة- جيش بدون رجالة- من مصرَ إلى قتال العشير والعُربان، وسببه كثرةُ فسادهم ببلاد القُدس ونابلس، وكان قد قُبِضَ على أدى بن فضل أمير جرم، وسُجِن بقلعة الجبل، ثم أُفرِجَ عنه بعناية الوزير منجك، فجمع أدى وقاتل سنجر بن علي أمير ثعلبة، فمالت حارثة مع أدى، ومالت بنو كنانة مع سنجر، وجرت بينهم حروبٌ كثيرة، قُتِلَ فيها خلائق، وفسدت الطرقاتُ على المسافرين، فخرجت إليهم عساكِرُ د"},{"id":3040,"era":"c8","t":"معركة بين بني مرين وبني عبد الواد بنو زيان .","s":"بعد أن خرج أبو الحسن المريني من تونُسَ وعاد الحفصيُّون إلى تمَلُّكِها، رَكِبَ أبو الحسين الزيان البحر يريد الجزائرَ ومعه ستمائة سفينة، وفي الطريق غرقت أكثر السفن من الرياح والأمواج العالية، فوصل بعدد قليلٍ إلى الجزائر، وكانت بنو عبد الواد بنو زيان قد تجهزت لاسترداد ملكهم من بني مرين الذين استولوا على الجزائر من سنة 748 وحاول أبو الحسن هذا أن يصدَّهم عنها مستعينًا بقلة ممن نجا معه من الرجال فجرت بي"},{"id":3041,"era":"c8","t":"وفاة ابن قيم الجوزية .","s":"هو الشَّيخُ الإمامُ العلَّامةُ أبو عبد الله شمس الدين محمد بن أبي بكر بن أيوب الزرعي الدمشقي الحنبلي المعروفُ بابن قَيِّم الجوزيَّة، فهو إمامُ الجوزيَّة، وابنُ قَيِّمِها، ولِدَ بدمشق في سابع صفر سنة 691, وسَمِعَ الحديث واشتغل بالعلم، وبَرَع في العلوم المتعَدِّدة، لا سيما علم التفسير والحديث والأصلين، ولَمَّا عاد الشيخ تقي الدين بن تيمية من الديار المصرية في سنة 712 لازَمَه إلى أن مات الشيخُ، فأخذ "},{"id":3042,"era":"c8","t":"إبطال إحياء ليلة النصف من شعبان بالجامع الأموي بدمشق .","s":"قال ابنُ كثير: من العجائب والغرائب التي لم يتَّفِقْ مِثلُها ولم يقَعْ مِن نحو مائتي سنة وأكثر، أنَّه بطل الوقيدُ بجامع دمشق في ليلة النصف من شعبان، فلم يَزِدْ في وقيده قنديلٌ واحد على عادة لياليه في سائر السنة، ولله الحمد والمنة. وفرح أهلُ العلم بذلك، وأهلُ الديانة، وشكَرَ الله تعالى على تبطيل هذه البدعة الشنعاء، التي كان يتولَّدُ بسببها شرور كثيرة بالبلد، والاستئجار بالجامع الأموي، وكان ذلك بمرسو"},{"id":3043,"era":"c8","t":"عودة الحفصيين إلى تونس بعد خروج بني مرين منها .","s":"عاد أبو العبَّاس الفضل بن أبي بكر بن يحيى بن إبراهيم بن عبد الواحد بن أبي حفص في ذي القعدة ليملِكَ تونس مرة أخرى، وكان قد قَدِمَ إلى تونس السلطانُ أبو الحسن علي بن أبي سعيد عثمان بن يعقوب بن عبد الحق ملك بني مرين صاحب فاس، وملك تونس وإفريقيَّة ثم سار منها للنصف من شوال، واستخلف ابنَه أبا العباس الفضل."},{"id":3044,"era":"c8","t":"الفتنة بمنى بين المصريين واليمنيين .","s":"في العاشِرِ مِن ذي الحجة قُبِضَ على صاحب اليمن المَلِك المجاهد علي بن المؤيد داود بن المظفر أبو سعيد المنصوري عمر بن رسول, وسَبَبُ ذلك أن الشريف ثقبة بن رميثة لَمَّا بلَغَه استقرار أخيه الشريف عجلان في إمرة مكَّة، توجَّهَ إلى اليمن، وأغرى المَلِكَ المجاهد علي صاحب اليمن بأخذِ مَكَّة وكسوةِ الكَعبةِ، فتجَهَّز المجاهد، وسار يريد الحَجَّ في جحفل كبير بأولادِه وأمه حتى قَرُب من مكة، وقد سبق حاجُّ مصر،"},{"id":3045,"era":"c8","t":"خروج أحمد الساقي أمير صفد عن الطاعة .","s":"سَبَبُه أنَّه لَمَّا قُبِضَ على الوزير منجك، خرج الأميرُ قمارى الحموي، وبيده ملطفات لأمراء صفد بالقَبضِ على أحمد، فبلغه ذلك من هجان جَهَّزه إليه أخوه، فندب الأمير أحمد الساقي طائفةً من مماليكه لتلَقِّي قمارى، وطلب نائب قلعة صفد وديوانه، وأمره أن يقرأَ عليه كم له بالقلعة من غَلَّة، فأمر لمماليكه منها بشيءٍ فَرَّقه عليهم إعانةً لهم على ما حصَل من المحْلِ في البلاد، وبعثهم ليأخذوا ذلك، فعندما طلعوا ا"},{"id":3046,"era":"c8","t":"الإغارة على الموصل .","s":"قَدِمَ الخَبَرُ بأنَّ هند وهو أحَدُ الأكراد استولى على بلاد الموصل، وصار في جمعٍ كبير يقطَعُ الطريقَ، والتحق به نجمة التركماني، فاستنابه وتقوَّى به وركب من مندر إلى سنجار وتحصَّن بها، وأغار على الموصِلِ ونَهَب وقتل، ومضى إلى الرَّحبة وأفسَدَ بها، ومشى على بلاد ماردين ونهبها، فخرجت إليه عساكِرُ الشام، وحصروه بسنجار ومعهم عسكر ماردين، ونصبوا عليها المنجنيقَ مدَّة شهر حتى طلب هند الأمانَ، على أنه يقي"},{"id":3047,"era":"c8","t":"عزل السلطان الناصر بن قلاوون وتولية أخيه الصالح صلاح الدين .","s":"توعَّكَ السلطانُ المَلِكُ الناصر حسن بن محمد بن قلاوون ولَزِمَ الفراشُ أيامًا، فبلغ الأميرَ طاز ومغلطاي ومنكلي بغا أنَّه أراد بإظهار توعُّكِه القَبضَ عليهم إذا دخلوا إليه، وأنَّه قد اتَّفَقَ مع قشتمر وألطنبغا الزامر وملكتمر المارديني وتنكز بغا على ذلك، وأن ينعِمَ عليهم بإقطاعاتِهم وإمراتهم، فواعدوا أصحابَهم، واتَّفَقوا مع الأمير بيبغا ططر حارس الطير النائب، والأمير طيبغا المجدي والأمير رسلان بصل، "},{"id":3048,"era":"c8","t":"احتراق باب جيرون أحد الأبواب المشهورة لمدينة دمشق .","s":"في ليلة الاثنين سادس عشر صفر في هذه السنة وقَعَ حَريقٌ عظيم عند باب جيرون شرقيَّه فاحترق به دكان القفاعي الكبيرة المزخرفة وما حولها، واتَّسع اتساعًا عظيمًا، واتَّصَل الحريق بالباب الأصفر من النحاس، فبادر ديوان الجامع إليه فكَشَطوا ما عليه من النحاس ونقلوه من يومه إلى خزانة الحاصل، بمقصورة الحلبية، بمشهد علي، ثم عَدَوا عليه يكَسِّرون خشبه بالفؤوس الحداد، والسواعد الشداد، وإذا هو من خشب الصنوبر الذي"},{"id":3049,"era":"c8","t":"استيلاء بني مرين على تلمسان .","s":"استولى أبو عنان فارس المتوكِّل المريني على تلمسان حاضرة بني عبد الواد، وذلك بعد معركةٍ جَرَت بينه وبين السلطانِ أبي سعيد عثمان الثاني سلطان بني زيان، وكان من نتائِجِ هذه المعركة أسْرُ أبي سعيد ثم قتله بعد ذلك، ثم استولى أبو عنان على بجاية أيضًا."},{"id":3050,"era":"c8","t":"خروج بيبغا روس نائب حلب عن طاعة السلطان وتسلطنه بحلب .","s":"اتفَقَ الأمير بيبغا روس نائِبُ حلب مع الأمير أحمد الساقي نائب حماة، والأمير بكلمش نائب طرابلس على العصيان، فجُرِّدَ في يوم السبت سابع عشر رجب جماعةٌ من الأمراء وأجناد الحلقة إلى الصعيد، منهم عمر شاه الحاجب، وقماري الحاجب، ومحمد بن بكتمر الحاجب، وشعبان قريب يلبغا، وكتب لبيبغا روس نائب حلب بالحضور إلى مصر، على يَدِ سنقر وطيدمر من مماليك الحاج أرقطاي، وكتب معهما ملطفات لأمراء حلب تتضَمَّنُ أنَّه إن ا"},{"id":3051,"era":"c8","t":"وفاة الخليفة العباسي الحاكم بأمر الله وتولية أخيه أبي بكر المعتضد .","s":"الحاكِمُ بأمر الله أبو العباس أحمد بن المستكفي بالله أبي الربيع سليمان بن الحاكم بأمر الله أبي العباس أحمد الهاشمي العباسي، كان بويِعَ بالخلافة بعد وفاةِ والده بقوص في العشرين من شعبان سنة 741، فلم يُمضِ له السُّلطانُ المَلِكُ الناصر محمد بن قلاوون ما عَهِدَه أبوه؛ لِما كان في نفسِه من والده المستكفي بالله مِن مَيلِه للمَلِكِ المظَفَّر بيبرس الجاشنكير، وأراد أن يولِّيَ الخلافة لبعض أقارِبِه، بل أح"},{"id":3052,"era":"c8","t":"خروج قراجا بن دلغادر أمير ألبستان عن طاعة السلطان ثم قتاله .","s":"خرج عن الطاعةِ قراجا بن دلغادر أمير ألبستان وكان ممن ساعد الأمير بيبغا روس نائب حلب على الخروج أولًا ثمَّ سَلَّمه بنفسِه، وكان نائب حلب الجديد أرغوان الكاملي قد حلف له أنَّه لا يقاتِلُه إن سَلَّم له بيبغا، فلما طلب من أرغون المسيرَ إلى قراجا للقضاء عليه لعصيانِه امتنع واعتذر بأنَّه حلف له ألَّا يُقاتِلَه، ثم ألزم الأمير أرغون الكاملي نائِبَ حلب حتى سار لحرب ابن دلغادر وأتاه نوابُ القلاع حتى صار في"},{"id":3053,"era":"c8","t":"فتنة العربان بالصعيد بقيادة الأحدب بن واصل .","s":"كَثُرَ عَبَثُ العُربان ببلاد الصعيد بقيادة الأحدب محمد بن واصل شيخ عرك، فجمع جمعًا كبيرًا، وتسمَّى بالأمير، فقَدِمَ الخبر في شعبان بأنهم كَبَسوا ناحيةَ ملوي، وقتلوا بها نحو ثلاثمائة رجل، ونهبوا المَعاصِرَ، وأخذوا حواصِلَها وذَبحوا أبقارَها، وأنَّ عَرَب منفلوط والمراغة وغيرهم قد نافقوا، وقَطَعوا بعض الجسور بالأشمونين، فوقع الاتفاقُ على الركوب عليهم بعد تخضيرِ الأراضي بالزراعة، وكُتِبَ إلى الولاة بت"},{"id":3054,"era":"c8","t":"أسر الشريف ثقبة وإقرار الشريف عجلان على إمرة مكة .","s":"أَسرَّ السلطانُ والأمراء مدَبِّرو الدولة إلى أمير الحاجِّ ومَن بصحبته من الأمراء أن يقبضوا على الشَّريفِ ثُقبة، ويقَرِّروا الشريفَ عَجلان بمُفردِه على إمارة مكَّة، فلمَّا قَدِمَ الحاج بطن مر، ومضى عجلانُ إلى لقائهم، شكا إلى الأمراءِ من أخيه ثقبة، وذكر ما فعلَه معه، وبكى، فطَمَّنوا قَلْبَه، وساروا به معهم حتى لَقِيَهم ثقبة في قوَّاده وعبيده، فألبسوه خِلعةً على العادة، ومَضَوا حافِّينَ به نحو مكَّةَ"},{"id":3055,"era":"c8","t":"إقامة الحد على رافضي شتم الصحابة .","s":"قَدِمَ دمشقَ عليُّ بن الحسن بن أبي الفضل بن جعفر بن محمد بن كثير الحلبي الرافضيُّ، وأقام بها سنواتٍ، فاتفق أنَّه شَقَّ الصفوف والناسُ في صلاةِ جنازةٍ بالجامِعِ الأمويِّ وهو يلعَنُ ويسُبُّ من ظَلَم آلَ مُحمَّدٍ، فانتَهَره عمادُ الدين ابنُ كثيرٍ، وأغرى به العامَّةَ، وقال: إنَّ هذا يسُبُّ الصحابةَ، فحملوه إلى القاضي تقي الدين السبكي فاعترف بسَبِّ أبي بكر وعمر، فعَقَدوا له مجلسًا، فحكَم نائِبُ المالكي"},{"id":3056,"era":"c8","t":"محاولة قتل أمير المدينة الشريف فضل بن قاسم .","s":"قَدِمَ الخَبَرُ مِن المدينةِ النبويَّةِ أنَّ الشَّريفَ مانع بن علي بن مسعود بن جماز وأولاد طفيل جَمَعوا ونازلوا المدينةَ، يُريدونَ قَتْلَ الشَّريفِ فَضلِ بنِ قاسم بن قاسم بن جماز فامتنَعَ بها، وهم يحاصِرونَه اثني عشر يومًا مَرَّت بينهم فيها حروب، فانهَزموا ومضَوا من حيثُ أتوا."},{"id":3057,"era":"c8","t":"فتنة أهل الذمة بمصر وإلزامهم بالشروط العمرية .","s":"تعاظم أمرُ النَّصارى بمصر, فتباهَوا بالملابِسِ الفاخرة، وبَنَوا الأملاكَ الجليلة في مصرَ والقاهرة، واقتَنَوا الجواريَ الجميلةَ مِن الأتراك والمولَّدات، واستولَوا على دواوينِ السلطان والأمراء، وزادوا في الحُمقِ والرَّقاعة، وتعَدَّوا طَورَهم في الترفُّع والتعاظم، وأكثروا من أذى المسلمينَ وإهانتهم، وتحرَّكت الناسُ في أمر النصارى وماجوا، وانتَدَب عِدَّةٌ من أهل الخير لذلك، وصاروا إلى الأمير طاز الشريف"},{"id":3058,"era":"c8","t":"إبطال عيد الشهيد بمصر .","s":"بعد ما حدث بمصرَ مِن فتنة أهل الذمَّةِ وما جرى من إلزامِهم بالشروط العُمَريَّة وزيادةٍ، وما جرى من هدمٍ للكنائس المُحدَثة وغيرها، فلما كان في أُخرَيات رجب بلغ الأميرَ صرغتمش أنَّ بناحية شبرا الخيام كنيسةً فيها أصبع الشهيدِ التي ترمى كلَّ سنةٍ في النيل زعمًا منهم أنَّها تعمل على زيادةِ الخير والماء فيه، ويعملون في هذا اليوم عيدًا معروفًا بعيد الشهيد يحدُثُ فيه من المُنكرَات والفواحِش الكثير ممَّا ي"},{"id":3059,"era":"c8","t":"وفاة أمير غرناطة السلطان أبو الحجاج يوسف وتولي ابنه بعده .","s":"توفي السلطانُ أبو الحجَّاج يوسف بن إسماعيل بن فرج من بني نصر؛ صاحِبُ غرناطة وما والاها، طُعِنَ بخنجَرٍ في جبينِه في يوم عيد الفطر، فمات منه، وتسَلْطَن بعده ابنُه أبو عبد الله محمد بن يوسف، وتلقَّبَ بالغني بالله."},{"id":3060,"era":"c8","t":"خلع السلطان الصالح صلاح الدين وإعادة السلطان الناصر حسن .","s":"بعد أن اتَّفَق الأمراءُ بأن يكون الأمرُ كُلُّه للسلطان وأنَّه هو الذي يديرُ السَّلطنةَ بنَفسهِ مِن رأيه، استبَدَّ بالأمر وقَرَّبَ إليه الأمير طاز، وكان قد شُغِفَ بأخيه جنتمر كثيرًا، واستبعد الأميرَ شيخون كليًّا، بل زاد الأمرُ أنَّ السلطان قد اتفق مع إخوة طاز على أن يقبِضَ عليه وعلى صرغتمش يومَ العيد، وكان طاز قد توجَّه إلى البُحيرة في هذه الأيام للصيدِ، بعد ما قرر مع السلطان ما ذُكر، فركب السلطانُ"},{"id":3061,"era":"c8","t":"طلب البيزنطيين من العثمانيين المساعدة .","s":"طلَب إمبراطورُ بيزنطة يوحنا الخامِسُ من الغازي أورخان بن عُثمانَ مُساعَدتَه ضِدَّ إمبراطور الصرب: اصطفان دوشان، الملقب بالقوي، الذي تحالف مع البندقيَّة والإمارات الصربية للهُجومِ على القسطنطينية، ووعد بأن يزوِّجَه ابنة الوصي على العرش يوحنا كانتا كوزين التي تزوج هو أختها الأخرى، لِيُصبِحا عَديلينِ، وأرسل له أورخان الجندَ، غير أن اصطفان دوشان قد أدركه الموتُ وتوقَّف الاستعدادُ، وعاد الجنود العثماني"},{"id":3062,"era":"c8","t":"وفاة الطبيب الرئيس جمال الدين ابن المغربي طبيب السلطان الناصر .","s":"هو الطبيبُ الرئيسُ الحكيمُ جمال الدين أبو إسحاق إبراهيمُ بن شهاب الدين أحمد، المعروف بابن المغربي: رئيس الأطباء بالديار المصرية والممالك الشامية، ذو الرُّتبة المنيعة والمكانة العالية والوَجاهة في الدولة والحُرمة عند الناس، خصوصًا في أيام الملك الناصر محمد بن قلاوون؛ لِقُربه من السلطان وخِدمة أكابر الأمراء والوزراء في مواطِنَ كثيرة سرًّا وجهرًا، وكان ممن خرج صحبة الركاب الناصري سنة 708 وأقام معه با"},{"id":3063,"era":"c8","t":"وفاة تقي الدين السبكي الشافعي\n(الأب) .","s":"هو تقيُّ الدين أبو الحسن علي بن زين الدين عبد الكافي بن علي بن تمام بن يوسف بن موسى بن تمام بن حامد بن يحيى بن عمر بن عثمان بن علي بن سوار بن سليم الأنصاري السبكي الشافعي، توفِّيَ بشاطئ النيل في ليلة الاثنين رابع جمادى الآخرة؛ ومولِدُه في شهر صفر سنة 683 بسبك الثلاث، وهي قرية بالمنوفية من أعمال الديار المصريَّة بالوجه البحري، كان إمامًا عالِمًا بالفقه والأصلينِ، والحديث والتفسير، والنحو والأدب، ول"},{"id":3064,"era":"c8","t":"وفاة حسن الجلائري مؤسس الدولة الجلائرية المغولي بالعراق .","s":"هو تاجُ الدين الشيخُ حسن بزرك بن حسين بن أقبغا بن أيلكان التتري، سِبطُ أرغون بن أبغا بن هولاكو بن طولون بن جنكيزخان ملك التتار صاحب \" الياسق \" والأحكام التركية، وهو والِدُ أويس، وكان يقال له حسن الكبير؛ تمييزًا له عن حسن بن تمرتاش, وهو أوَّلُ حُكَّام آل جلائر, كان حَسَنٌ الكبير زوجَ خاتون بغداد بنت الجوبان، فلم يزل بوسعيد إلى أن طلقها وأخذها منه قهرًا وأبعده، فلما مات بوسعيد عاد فمَلَك بغداد وأقام"},{"id":3065,"era":"c8","t":"هجوم الفرنج على شواطئ صفد .","s":"في السابِعِ والعشرين من جمادى الأولى ورَدَ الخبَرُ إلى دمشق بأن الفرنجَ استحوذوا على مدينة صفد، قدموا إليها في سبعة مراكب وقتلوا طائفةً مِن أهلها ونهبوا شيئًا كثيرًا وأسَرُوا أيضًا، وهجموا على الناس وقت الفجرِ يوم الجمعة، وقد قَتَل منهم المسلمون خلقًا كثيرًا وكَسَروا مركبًا من مراكبهم، وجاء الفرنجُ في عشية السبت قبل العصر، وقَدِمَ الوالي وهو جريحٌ مُثقَلٌ، وأمر نائِبَ السلطنة عند ذلك بتجهيز الجيش "},{"id":3066,"era":"c8","t":"حريق هائل في بلاد كسروان وطرابلس .","s":"جرى في بلاد سواحِلِ الشام حريقٌ مِن بلاد طرابلس إلى آخِرِ معاملة بيروت إلى جميع كسروان، أحرق الجبالَ كُلَّها ومات الوحوش كلُّها، مثل النمور والدب والثعلب والخنزير من الحريق، ما بقي للوحوشِ مَوضِعٌ يهربون فيها، وبقي الحريقُ عليه أيامًا، وهرب الناس إلى جانب البحر خوفًا من النار، واحترق زيتون كثير، فلما نزل المطرُ أطفأه بإذن الله تعالى، ومن العجب أن ورقة من شجرةٍ وقعت في بيتٍ مِن مدخنته، فأحرقت جميع "},{"id":3067,"era":"c8","t":"العثمانيون يعبرون مضيق الدردنيل .","s":"لما طلب البيزنطيون المساعدةَ من العثمانيين ضِدَّ الصرب، أدرك بذلك العثمانيون ضَعفَ البيزنطيين، فرأى أورخان سلطانُ العثمانيين أن ينتَقِلَ إلى الضفة الغربية من مضيقِ الدردنيل ليتقَدَّمَ بعدها إلى أوروبا فيتمَكَّنَ من الإحاطة بالقسطنطينية والهجومِ عليها من الغرب؛ حيث عجز المسلمون عن فتحها من الشرقِ، فأرسل ابنه الكبير سليمان لدراسة هذه الخطة، وفي هذا العام اجتاز سليمانُ مضيق الدردنيل ليلًا مع أربعين ر"},{"id":3068,"era":"c8","t":"استيلاء بني مرين على تونس والجزائر .","s":"استولى أبو عنان فارس سلطان بني مرين على الجزائر، ثم استولى على قسنطينة وعنابة وتونس، واستسلم له السلطان الحفصي أبو العباس أحمد المتوكل، مريدًا بذلك توحيد إفريقيا الشمالية، ولكنَّ قبائل الأعراب ثارت على أبي عنان لِمَنعه عنهم بعض الأداءاتِ الموظَّفة لهم على عادة الأعراب، وعجَزَ الجيش المريني عن مطاردة الأعرابِ وإخماد عصيانهم، وعاد أبو عنان إلى فاس ومعه جيشُه."},{"id":3069,"era":"c8","t":"اغتيال سلطان بني مرين أبي عنان وتغلب أخيه على الملك .","s":"هو السُّلطانُ أبو عنان فارس بن أبي الحسن علي: حاكِمُ دولة بني مرين في أفريقية، اغتاله وزيرُه الحسن بن عمر الفودوي، ثم تولى بعدَه ابنُه أبو بكر محمد السعيد خلفًا لأبيه وله من العمر فقط خمس سنوات، وكان أبو سالم إبراهيم أخو أبي عنان منفيًّا في الأندلس عند بني الأحمر، فلما علم بما حصل لأخيه طلب من سلطانِ بني الأحمر مساندَتَه، فلم يجِبْه، فطلب من مَلِك قشتالة الأسباني فأنجده بأسطولٍ اجتاز به البحر إلى "},{"id":3070,"era":"c8","t":"اغتيال أمير المدينة مانع بن علي الحسيني .","s":"هو الشَّريفُ مانعُ بن علي بن مسعود بن جماز بن شيحة الحسيني: صاحِبُ المدينة النبويَّة، وقد ذُكِرَت عنه أمورٌ شنيعة بَشِعةٌ مِن غُلُوِّه في الرَّفضِ المُفرِط، ومن قَولِه: إنه لو تمكن أخرج الشيخين من الحُجرة! وغير ذلك من عبارات مؤدية لعدم إيمانِه إن صح عنه، والله أعلم، وفي السابع والعشرين من ذي الحجَّة عدا عليه فداويان عند لُبسِه خِلعةَ السلطان، وقت دخول المَحمَل إلى المدينة الشريفة، فقتلاه، فعَدَت ع"},{"id":3071,"era":"c8","t":"عزل الشريف عجلان عن إمرة مكة .","s":"كان الشَّريفُ عجلان قد قَدِمَ مِن مكَّةَ لمِصرَ، فعزله السلطان عن إمارتها، وولَّى عِوَضَه الشريفان محمد بن عطفة وسند بن رميثة، وقواهما بالأمير جركتمر الحاجب والأمير قطلوبغا المنصوري، وناصر الدين أحمد بن أصلم؛ ليقيموا بمكة حتى يأتيهم البَدَلُ مِن مِصرَ."},{"id":3072,"era":"c8","t":"إخماد الثورات ضد إمبراطورية المغول  .","s":"بعد أن توفِّيَ سلطان المغول بردي بك خان سنة 759 وقع الاختلالُ في دولة التتار ببلاد الشمال وكَثُرَ الهَرجُ والمرج، وكان ابنُه محمد بردي قد تسَلَّم السَّلطنةَ بعد أبيه الذي استطاع بجبروتِه وقوَّتِه أن يُخمِدَ هذه الثورات وأن يسيطِرَ أيضًا على حُكَّام الروس في موسكو وغيرها، كما قام توقتاميش أيضًا بمثل هذا الإخضاعِ."},{"id":3073,"era":"c8","t":"فتنة الأعراب بحوران .","s":"كانت قريةٌ بحوران- وهي خاص لنائب الشام وهم حلبية يمن، ويقال لهم بنو لبسة وبنو ناشي- وهي حصينة منيعة يضوي إليها كلُّ مُفسدٍ وقاطع ومارق، ولجأ إليهم أحَدُ شياطين رويمن العشير، وهو عمر المعروف بالدنيط، فأعدوا عددًا كثيرة ونهبوا ليغنَموا العشير، وفي هذا الحين بدَرَهم والي الولاة المعروف بشنكل منكل، فجاء إليهم ليرُدَّهم ويهديهم، وطلب الوالي منهم تسليمَ عمر الدنيط، فأبوا عليه وراموا مقاتلَتَه، وهم جمع ك"},{"id":3074,"era":"c8","t":"مطر عظيم بمصر بعد جفاف .","s":"وقعَ مَطَرٌ عظيمٌ في أوَّلِ هذا الشَّهرِ بمصر، وهو شهرُ فبراير، وثلجٌ عظيمٌ، فرَوِيَت البساتينُ التي كانت لها عن الماءِ عِدَّةُ شهور، ولا يحصلُ لأحدٍ مِن الناس سَقيٌ إلا بكلفة عظيمة ومشقَّة، ومبلغ كثير، حتى كاد الناسُ يقتتلون عليه بالأيدي والدبابيس وغير ذلك من البَذلِ الكثير، وذلك في شهورِ ديسمبر والثاني، وأول فبراير؛ وذلك لقِلَّةِ مياه الأنهار وضَعفِها، وكذلك بلادُ حوران أكثَرُهم يروون من أماكنَ "},{"id":3075,"era":"c8","t":"وفاة أورخان بن عثمان ثاني سلطان العثمانيين وتولي ابنه مراد الأول .","s":"هو الغازي بك شُجاعُ الدين والدنيا السلطانُ أورخان خان بن عثمان بن أرطغرل بن سليمان ثاني سلاطين بني عثمان، وُلِدَ في مدينة سُكود عاصمة إمارة والده سنة 687 هـ الموافق (1281م) ولِيَ سنة 726 بعد وفاةِ والده السلطان عثمان أوَّلِ ملوك بني عثمان، وكانت ولايةُ أورخان في أيام السلطان حسن بن محمد بن قلاوون صاحِبِ مصر، كان أورخان شديدًا على الكفَّارِ ففاق والِدَه في الجهاد، وفتح البلاد فافتتح قلاعًا كثيرة وح"},{"id":3076,"era":"c8","t":"فتح مراد الأول مدينة أنقرة .","s":"بعد وفاة أورخان وتولِّي ابنِه مراد الأول أراد أميرُ القرمان في أنقرة علاءُ الدين خليل بن محمود أن يستَغِلَّ هذه الفرصة ظنًّا منه أنَّه يقضي على العثمانيِّينَ فاستنهضَ هِمَمَ الأمراء المستقِلِّينَ في آسيا الصغرى للقتال، وعَمِلَ على تجميعهم، غيرَ أنَّه تفاجأ بجيش مراد الأول الحاكِمِ الجديدِ، وهي محيطةٌ بمدينة أنقرة، ودخلها فاتحًا، فاضطر علاءُ الدين لِعَقدِ الصلح معه وتنازل عن أنقرة، واعترف السلطانُ "},{"id":3077,"era":"c8","t":"وفاة الحافظ الفقيه صلاح الدين العلائي .","s":"هو الحافِظُ الفقيه أبو سعيد صلاح الدين العلائي خليل بن كيكلدي الدمشقي سِبطُ البرهان الذهبي الحافظ. مولِدُه سنة 694، حَفِظَ القرآن والسنة والنحو وغير ذلك، وسَمِعَ الكثير، وهو معدود في الأذكياء، ودَرَّس وأفتى وناظر، وكان مدَّة مقامه مدرسًا بالمدرسة الصلاحية بالقدس وشيخًا بدار الحديث السكرية ثلاثين سنة، وقد صَنَّف وألف وجمع وخَرَّج، وكانت له يدٌ طولى بمعرفة العالي والنازل، وتخريج الأجزاء والفوائد، ول"},{"id":3078,"era":"c8","t":"غزو بلاد سيس .","s":"في مُستَهَلِّ جمادى الآخرة رَكِبَ الأميرُ سَيفُ الدين بيدمر نائب حلب لقصد غزو بلاد سيس في جيش، وفي يوم الاثنين سابع عشر جاء الأمير تاج الدين جبريل مِن عند الأميرِ سيف الدين بيدمر نائب حلب، وقد فتحَ بلدين من بلاد سيس، وهما طرسوس وأذنة، وأرسل مفاتيحَهما صحبة الأمير تاج الدين جبريل إلى السلطان، ثم افتتح حصونًا أخرى كثيرةً في أسرع مدة، وأيسَرِ كُلفة، وخطب القاضي ناصرُ الدين كاتِبُ السر خطبةً بليغة حسن"},{"id":3079,"era":"c8","t":"عصيان خيار بن مهنا أمير العرب بين العراق وسوريا وقتاله .","s":"وصل تقليدُ الأمير سيف الدين بيدمر بنيابة دمشق، ورُسِمَ له أن يركَبَ في طائفةٍ مِن جيش حَلَب ويقصد الأميرَ خيار بن مهنا ليُحضِرَه إلى خدمة السلطان، وكذلك رُسِمَ لنائب حماة وحمص أن يكونا عونًا للأمير سيف الدين بيدمر في ذلك، فلمَّا كان يومُ الجمعة رابِعَ هذا الشهر التَقَوا مع خيار عند سلمية، فكانت بينهم مناوشات، فأحاط الأعرابُ بسيف الدين بيدمر ومَن معه من الترك من كل جانبٍ؛ وذلك لكثرة العرب وكانوا نح"},{"id":3080,"era":"c8","t":"وفاة ابن هشام الأنصاري النحوي .","s":"هو جمالُ الدين أبو محمَّدٍ عبدُ اللهِ بنُ يوسُفَ بنِ أحمد بن هشام الأنصاري الحنبلي النحويُّ. وُلِدَ وتوفِّيَ بمصر, كان بارعًا في عدة علوم، لا سيما العربية؛ فإنه كان فارِسَها ومالِكَ زِمامِها، وعُدَّ مِن كبار أئمَّةِ النحو، وله فيه الأبحاث العجيبة، والنكات الغريبة، والأنظار الدقيقة، حتى قيل عنه: أنحى مِن سيبويه, وهو صاحِبُ الشَّرحِ على ألفية ابن مالك في النحو، المسمى أوضح المسالك إلى ألفية ابن مالك"},{"id":3081,"era":"c8","t":"فتح مراد الأول مدينة أدرنة الأوروبية وجعلها عاصمة الدولة العثمانية .","s":"فتح العُثمانيون في هذه السنة مدينةَ أدرنة بعد أن حاصَروها، فسَلَّمَها القائِدُ الرومي بعد أن يَئِسَ من المقاومةِ، فنقل مراد الأوَّلُ عاصِمَتَه إليها لتكونَ على مقربة من أوروبا، وليكون الهجومُ على القُسطنطينية من جهة الغربِ، وكانت العاصمة قبل ذلك هي مدينة بورصة، وبَقِيَت هذه المدينة أدرنة عاصِمةً للعثمانيين حتى تمَّ فَتْح القسطنطينية عام 857هـ كما تمَّ الاستيلاءُ على مدُن أوروبية أخرى مثل فيلبه قاع"},{"id":3082,"era":"c8","t":"اغتيال السلطان الناصر حسن وتولية ابن أخيه المنصور حاجي .","s":"كان زوالُ مُلكِه في ليلة الأربعاء تاسع جمادى الأولى، وذلك أنَّه بلغه وهو بمنزِلِه بكوم برا أنَّ الأمير يلبغا الخاصكي يريدُ قَتْلَه، وأنه لا يدخُلُ إلى الخدمة إلَّا وهو لابِسٌ آلةَ الحَربِ مِن تحت ثيابِه فاستدعى به، وهو مع حريمه في خَلوةٍ، وأمر فنُزِعَت عنه ثيابُه كُلُّها، ثمَّ كُتِّفَت يداه، فشَفَعت فيه إحدى حظايا السلطان، حتى خَلَّى عنه وخلع عليه، واعتذر إليه بأنَّه بلغه عنه أنه لا يدخُلُ إلا بال"},{"id":3083,"era":"c8","t":"خروج الأمير بيدمر أمير دمشق عن الطاعة .","s":"خرج الأميرُ بَيدمر نائِبُ الشام عن الطاعة، وبموافقةِ جماعةٍ مِن الأمراء له على ذلك، منهم أسَنْدَمر أخو يَلبغا اليحياوي، والأمير مَنجَك وجماعة، وأنه قام لأخذ ثأر السُّلطانِ حسن، وأفتاه جماعةٌ من الفقهاء بجواز قتال قاتِلِه الذي تغَلَّب على المُلك- يعني الأمير يَلْبُغا- ومنع البريدَ أن يمُرَّ مِن الشام، وجَهَّزَ الأمير مَنجَك والأمير أَسَندَمُر الزيني في عسكَرٍ إلى غزة، فحاربوا نائِبَها ومَلَكوها، فن"},{"id":3084,"era":"c8","t":"محاولة انقلاب فاشلة على السلطان المنصور صلاح الدين حاجي .","s":"اتَّفَق الأميرُ حُسين بن محمد بن قلاوون مع الطواشي جوهر الزمردي نائِبِ مُقَدَّم المماليك على أن يُلبِسَ المماليكَ السُّلطانية آلةَ الحرب ويتسَلْطَن، وكان السفيرُ بينهما نصرَ السليماني أحَدَ طواشية الأمير حسين، فوشَى بذلك إلى الأمراء، وكان السلطانُ بالشام، فبادر الأميرُ أَيْدَمُر الشمسي نائب الغيبة والأمير موسى بن الأزْكَشي وقبضا على جوهر ونصر وسُجِنا بخزانة شمايل بالقاهرة، فلمَّا قَدِمَ السلطان وا"},{"id":3085,"era":"c8","t":"اغتيال السلطان المريني أبي سالم إبراهيم وتولية محمد الثاني .","s":"كان أبو سالم إبراهيمُ المريني منفيًّا في الأندلس، ثم عاد وتمَلَّك بعد أن خَلَع ابن أخيه محمد السعيد الذي جلس بعد اغتيالِ أبيه، ثمَّ في هذه السنة قام الوزيرُ عمر بن عبد الله الفودودي بخلع السلطانِ أبي سالم إبراهيم وقَتَله وولِيَ السلطنة تاشفين بن أبي الحسن علي أخي السلطان المخلوع، وكان تاشفين موسوسًا مختل العقل، ولم يرضَ بنو مرين عما فعله الوزيرُ فخلعوا تاشفين وأتوا بابنِ أخٍ له يدعى محمد الثاني بن"},{"id":3086,"era":"c8","t":"غارات على بلاد الروم .","s":"استقَرَّ الأميرُ أَسندمر الطازي في نيابة ملطيَّة فأكثر من الغارات على بلاد الروم، وأسَرَهم وقتَلَهم، فبعث إليه الأمير محمد بن أَرتَنَا صاحِبُ قيصرية الروم عسكرًا مع ابن دُلغَادر، فكبَسَه وهو يتصَيَّد فقاتله قتالًا شديدًا، ونجا بنَفسِه إلى ملطية، فكتب السلطانُ والأمير يلبُغا بخروج عساكِرِ دمشق وطرابلس وحماة وحلب بآلات الحرب والحصار، صحبة الأمير قطْلُوبغا نائب حلب، فخرج من دمشق خمسةُ آلاف فارس، ومن "},{"id":3087,"era":"c8","t":"وفاة الخليفة العباسي المعتضد بالله وتولية ابنه محمد المتوكل على الله .","s":"هو الخليفةُ المُعتَضِد بالله أبو الفتح، واسمُه أبو بكر بن المستكفي بالله أبي الربيع سليمان بن الحاكم بأمر الله أبي العباس أحمد بن الحسن بن أبي بكر بن أبي علي بن الحسن بن الخليفة الراشد بن المسترشد، توفِّيَ يوم الثلاثاء عاشر جمادى الأولى ومدة خلافتِه عشرة أعوام، وعهد إلى ابنه محمد قبل وفاته بقليل، فاستدعي أبو عبد الله محمد ابن الخليفة المعتضد بالله أبي بكر، في يوم الخميس ثاني عشر جمادى الأولى إلى ق"},{"id":3088,"era":"c8","t":"مقتل الملك إسماعيل ملك بني نصر وتولي محمد السادس الملك .","s":"قام أميرٌ مِن أمراء بني نصر يُدعى أبا سعيد محمد، وكان زوجَ أخت السلطان إسماعيل الثاني، فثار على صهره إسماعيلَ وقَتَله وأعلن نفسَه مَلِكًا باسم محمد السادس، ولكنه لم يلبَثْ أن ثار عليه أهلُ غرناطة فخلعوه فهَرَب من غرناطة إلى ملك قشتالة ولم يلبث أن قُتِلَ هناك، ثمَّ إن الوزير المريني عمر الفودودي جهَّزَ محمد الخامس الغني بالله بقوَّة فجاز بها إلى الأندلُسِ مع وزيره لسان الدين ابن الخطيب ودخل غرناطة "},{"id":3089,"era":"c8","t":"وفاة القاضي الإمام ابن مفلح الحنبلي .","s":"هو القاضي الإمامُ العالم شمسُ الدين محمد بن مفلح المقدسي الحنبلي الصالحي الراميني الأصل, وُلِدَ ونشأ في بيت المقدس. وكان بارعًا فاضلًا مُتفَنِّنًا في علوم كثيرة، ولاسيما علم الفروع، وكان نائبًا لمشيخة قاضي القضاة جمال الدين يوسف بن محمد المقدسي الحنبلي، وزَوجَ ابنته، وهو أعلَمُ أهل عصره بمذهب الإمام أحمد بن حنبل؛ لذا كان غايةً في نقل مذهب الإمام أحمد، وجمَعَ مصنفات كثيرة منها: كتاب المقنع، وعلق عل"},{"id":3090,"era":"c8","t":"خلع السلطان المنصور صلاح الدين حاجي وتولية ابن عمه شعبان .","s":"في يومِ الاثنينِ رابِعَ عشر شعبان اقتضى رأيُ الأمير يَلبغَا خَلْعَ السلطان، فوافقه الأمراء على ذلك، فخلعوه من الغدِ لاختلال عَقلِه، وسجنوه ببعضِ الدُّورِ السُّلطانية من القلعة، فكانت مُدَّةُ سلطنته سنتين وثلاثة أشهر وستة أيام، لم يكُنْ له سوى الاسم فقط، وتولى بعده السلطانُ الملك الأشرف زين الدين أبو المعالي شعبان بن الأمجد حسين بن الناصر محمد بن قلاوون السلطنة وعمره عشر سنين، ولم يَلِ أحَدٌ من بني"},{"id":3091,"era":"c8","t":"وفاة المؤرخ ابن شاكر الكتبي .","s":"هو المؤرِّخُ صلاح الدين محمد بن شاكر بن أحمد، المعروف بابن شاكر الكتبي، الداراني، الدمشقي. أحَدُ أعلام المؤرخين في القرن الثامن الهجري. كان باحثًا عارفًا بالأدب. ولِدَ في داريا (من قرى دمشق) ونشأ وتوفِّيَ بدمشق. كان فقيرًا جِدًّا، واشتغل بتجارة الكُتُب، فربح منها مالًا طائلًا. له مؤلَّفات مثل: كتاب \"عيون التواريخ\"، و \"فوات الوفيات\". قال ابن كثير: \"في يوم السبت حادي عشر رمضان صَلَّينا بعد الظهر على"},{"id":3092,"era":"c8","t":"وفاة الأديب المؤرخ خليل بن أيبك الصفدي .","s":"هو الأديبُ المؤرِّخُ صلاحُ الدين أبو الصفاء، خليل ابن الأمير عز الدين أيبك بن عبد الله الألبكي الصفدي, ولد سنة 696 في صفد بفلسطين، وإليها نُسِبَ، وكان والِدُه أحد أمراء المماليك، وكان إمامًا بارعًا كاتبًا ناظمًا ناثرًا شاعرًا، له مصنفات كثيرة في التاريخ والأدب والبديع وغير ذلك، وتاريخه المسمى: الوافي بالوفيات، وهو مشهورٌ مُعتَمَد، وله تاريخ آخر أصغر من هذا سماه أعوان النصر في أعيان العصر، وله شَرح"},{"id":3093,"era":"c8","t":"وفاة الملك الصالح شمس الدين صالح ملك ماردين .","s":"توفِّيَ السلطانُ المَلِكُ الصالح شمس الدين صالح ابن الملك المنصور نجم الدين غازي ابن الملك المظفَّر قرا أرسلان ابن الملك السعيد غازي بن أرتق بن أرسلان بن إيل بن غازي بن ألبي بن تمرداش بن إيل بن غازي بن أرتق الأرتقي صاحب ماردين بها، وقد ناهز السبعينَ سنةً مِن العمر، بعد أن دام في سلطنة ماردين أربعًا وخمسين سنة، وتولَّى ماردين بعده ابنُه الملك المنصور أحمد، وكان المَلِكُ الصالح من أجَلِّ ملوك بني أر"},{"id":3094,"era":"c8","t":"حرب صليبية ضد العثمانيين ووقعة ماريتزا .","s":"بعد فَتحِ العُثمانيين أدرنةَ وغيرَها من المدن الأوروبية، خاف الأمراءُ الأوربيون فكتبوا إلى ملوك أوروبا الغربيَّة وإلى البابا يستنجدون بهم ضِدَّهم، حتى إمبراطور القسطنطينية ذهب إلى بابا الفاتيكان في روما وركع أمامَه وقَبَّل يديه ورجليه ورجاه الدعمَ رَغْمَ الخلاف المذهبي بينهما، فلبَّى البابا النداء وكُتِبَ إلى ملوك أوروبا عامة يُطلَبُ منهم الاستعدادُ للقيام بحرب صليبية جديدة حفاظًا على النصرانيَّة "},{"id":3095,"era":"c8","t":"فتوحات العثمانيين في أوروبا .","s":"بعد انتِصارِ مُراد الأول في وقعة ماريتزا على التحالُفِ الصليبي العامَ الماضيَ، اضطرب ملوك النصارى المجاورون للدولةِ العَلِيَّة، وطلبوا من البابا أوربانوس الخامس أن يتوسط لدى ملوك أوروبا الغربيين لِيُساعدوهم على محاربة المسلمين وإخراجِهم من أوروبا خوفًا من امتداد الفتحِ العُثماني إلى ما وراء جبال البلقان؛ إذ لو اجتازوها بدونِ مُعارضة ومقاومة في مضايقِها، لم يقوَ أحد بعد ذلك على إيقاف تيار فتوحاتِهم"},{"id":3096,"era":"c8","t":"إسقاط المكوس عن سائر ما يحمل لمكة .","s":"رسم السلطانُ المَلِكُ الأشرف شعبان صاحِبُ مصر بإسقاط ما على الحَجِّ مِن المكوسِ بمكَّةَ في سائِرِ ما يُحمَلُ إليها من المتاجر، سوى الكارم- الأحجار الكريمة- وتجَّار الهند وتجار العراق، وأسقط المكسَ المتعَلِّق بالمأكولات، وكان المَكسُ يؤخذ من المأكولات بمكَّةَ مد حب جدي، على كل حمل من التمر اللبان الذي يصل إلى مكة، وثلاثة دنانير مسعوديَّة على كلِّ حِملِ تمر محشي يصِلُ إلى مكة، وستة مسعودية على كلِّ "},{"id":3097,"era":"c8","t":"احتلال الفرنج مدينة الإسكندرية بمصر بقيادة لابيردي لويزينانس .","s":"ورد الخبَرُ في يوم السبت رابع عشر محرم بمنازلة الفرنج الإسكندرية، وأنهم قدموا يوم الأربعاء حادي عشر، فسُرِّح الطائِرُ بذلك إلى الأمير يلبغا، فتوهَّمَ أن تكون هذه مكيدةً يُكادُ بها، فبادَرَ ودخل إلى داره خارِجَ القاهرة، وتَبِعَه السلطان، فصَعِدَ القلعة في يوم الأحد خامس عشر، فلما تحقَّق الأمير يلبغا الخبَرَ، عدى النيلَ مِن ساعته إلى البر الغربي، وتلاحق به أصحابُه، ونودِيَ بالقاهرة: من تأخَّرَ مِن ا"},{"id":3098,"era":"c8","t":"فتنة أولاد الكنز العلويين بمدينة أسوان وسواكن .","s":"كان الكنزُ أمير العرب بنواحي أسوان، وهو من الشيعة العَلَوية بمصر، فعصى الكنز الدولةَ واجتمَعَ إليه العرب والسودان، وطالت أيَّامُه واشتهر منذ أيام صلاح الدين، وفي هذا العام كثُرَ فسادُ أولاد الكنز وطائفة العكارمة بأسوان وسواكن، ومَنَعوا التجارَ وغَيرَهم من السفر؛ لِقَطعِهم الطريق، وأخْذِهم أموالَ الناس، وأنَّ أولاد الكنز قد غلبوا على ثغر أسوان، وصحراء عيذاب وبرية الواحات الداخلة، وصاهَروا ملوك النو"},{"id":3099,"era":"c8","t":"وفاة الملك المجاهد سيف الدين علي صاحب اليمن .","s":"هو السُّلطانُ المَلِكُ المجاهد سيف الدين أبو يحيى علي ابن السلطان الملك المؤيد هزبر الدين داود ابن السلطان الملك المظفر يوسف ابن السلطان الملك المنصور عمر بن نور الدين علي بن رسول، التركماني الأصل، اليمني المولد والمنشأ والوفاة، صاحب اليمن. كان مولِدُ المجاهد سنة 701 بتعز، ونشأ بها وحَفِظَ التنبيه في الفقه وبحَثَه وتخَرَّج على المشايخ، منهم: الشيخ الإمام العلامة الصاغاني، وتأدب على الشيخ تاج الدين"},{"id":3100,"era":"c8","t":"قدوم الفرنج إلى مصر يطلبون تجديد الصلح والنصرة على متملك قبرص .","s":"في أوَّلِ شَهرِ رَجَب قَدِمَ الخَبَرُ بوصول رسل الفرنج إلى ميناء الإسكندرية، وأنهم طلبوا رهائِنَ عندهم، حتى يَنزِلوا من مراكِبِهم ويَرُدُّوا رسالتَهم، فلم تؤمَنْ مَكيدتُهم، واقتضى الحالُ إجابَتَهم، فأُخرِجَ مِن سجن الوافي- المعروف بخزانة شمايل- جماعةٌ وَجَب قَتْلُهم، وغُسلوا بالحمَّام، وأُلبِسوا ثيابًا جميلةً، وسافروا إلى الإسكندرية، فأكرَمَهم النائب، وأشاع أنَّهم من رُؤساء الثغر، وبَعَث بهم إلى ا"},{"id":3101,"era":"c8","t":"غزو قشتالة وفتح آشر .","s":"كان الأميرُ محمد الخامس الغني بالله أميرُ غرناطة قد بدأ الغزوَ مِن السنة الماضية على قشتالة، وفي هذه السنة استمر على ما كان عليه، فزحف بقواتِه على ولاية إشبيلية وقشتالة، وفَتَح حِصنَ آشر وهو من معاقِلِ قشتالة المعروفة، كما استولى على كثيرٍ مِن الغنائم، وسبى الكثيرَ مِن أهلِها."},{"id":3102,"era":"c8","t":"فتنة يلبغا العمري ومحاولته خلع السلطان الأشرف شعبان .","s":"لَمَّا كان في مستهَلِّ شَهرِ ربيع الآخر نزل السلطانُ من قلعة الجبل وعَدَّى إلى بر الجيزة ليتوجه إلى الصيدِ بالبحيرة، بعد أن ألزم الأمراءَ أن يجعلوا- في الشواني التي نجز عملها برسم الغُزاة- العِدَد والسلاحَ والرجالَ على هيئة القِتالِ؛ لِيَنظُرَ السلطان والنَّاس، ثم سار السلطان والأتابك يلبغا بالعساكِرِ مِن بر الجيزة يريدون البحيرةَ حتى نزلوا في ليلة الأربعاء سادسَ شهر ربيع الآخر بالطرانة وباتوا بها"},{"id":3103,"era":"c8","t":"فتنة بين الأمراء في مصر .","s":"لَمَّا كان يومُ الأحد سابع شوال بلغ الأميرَ أسندَمُر الناصريَّ أميرَ كبير أتابك العساكر ومُدَبِّر المملكة ونائِبَ السلطنة- وهو الذي أصبح المقَدَّمَ بعد قَتلِ يلبغا- أنَّ جماعةً من الأمراء قد اتَّفَقوا على الفتكِ به وبالأجلاب، وهم أعضادُه وبهم يصولُ، فخرج ليلًا من داره إلى دار الأمير قجماس الطازي، وبذل له مالًا كبيرًا حتى استماله إليه، ثم فارَقَه، وفي ظَنِّه أنه قد صار معه، ولم يكن كذلك، وعاد إلى م"},{"id":3104,"era":"c8","t":"نائبا حماة وطرابلس يخرجان عن طاعة الملك الأشرف .","s":"اتَّفَق الأميرُ طيبغا الطويل نائِبُ حماة- وكان قد أصبح نائبها هذه السنة بعد فتنة يلبغا وقَتْلِه- والأمير أشقتمُر نائب طرابلس، على المخامرة والخروج عن طاعة السلطان، فتجَهَّز الأمير أسندمر الأتابك للسفر، وتقَدَّم بتهيؤ الأمراء، وبعث القُصَّاد للكشف عن ذلك على البريدِ، فعادوا باستمرار بقيَّة النواب على الطاعة، ما عدا المذكورين، فكتب بالقبضِ عليهما، فقُبِضَا وقبض معهما على إخوة طيبغا الطويل، وحُملوا إ"},{"id":3105,"era":"c8","t":"الغزو الغرناطي على الإسبان .","s":"استمر محمَّدٌ الخامس أمير غرناطة بالغزو, فحاصر مدينةَ جيَّان واقتحمها بعد معاركَ شَديدةٍ واستولى على ما فيها من أموالٍ وسلاح كما أسَرَ جُموعًا كثيرة، واقتحم أيضًا مدينة ياغة جنوب جيان ونهَبَها ودمَّرَ قَلعَتَها وتابع زَحفَه على مدينة أبده شمال شرق جيان واستولى عليها ودمر أسوارها، ثم عاد إلى غرناطة مكلَّلًا بالنصر، ثم توجه إلى الجزيرة الخضراء وحاصرها واستولى عليها بعد قتال مرير."},{"id":3106,"era":"c8","t":"فتنة الأمير أسندمر ومماليك يلبغا وقتالهم السلطان الأشرف .","s":"اتَّفَقَت مماليكُ يلبغا الأجلاب يوم الجمعة سادس صفر على الأميرِ أسندَمُر الناصري أمير كبير أتابك العساكر ومدَبِّر المملكة ونائب السلطنة، وركبوا معهم الأمراء وقت صلاة الجمعة، ودخلوا على أسندمر الناصري وسألوه أن يُمسِكَ جماعة من الأمراء، فمَسَك أزدمر العزي أمير سلاح وجركتمر المنجكي أمير مجلس، وبيرم العزي الدوادار الكبير، وبيبغا القوصوني، والأمير آخور كبك الصرغتمشي الجوكندا، واستمَرَّ المماليك لابسين"},{"id":3107,"era":"c8","t":"الفرنج يغزون طرابلس .","s":"وصلَ الفِرنجُ طرابلس في أول صفر في مائة وثلاثين مركبًا، ما بين شيني وقرقورة وغراب وطريدة، وشختور، عليها متمَلِّك قبرص، ومتمَلِّك رودس، والاسبتار، وكان نائِبُ طرابلس وأكثر عسكرها غائبين عنها، فاغتَنَمَت الفرنج الفرصةَ وخرجوا من مراكبهم إلى الساحل، فخرج لهم من طرابلس بقيَّةُ عَسكَرِها بجماعة من المسلمين، فترامَوا بالنبال ثم اقتتلوا أشدَّ قتال، وتقهقر المسلمون، ودخل المدينةَ طائفةٌ من الفرنج، فنَهَبو"},{"id":3108,"era":"c8","t":"وفاة ابن عقيل النحوي .","s":"هو الإمامُ القاضي بهاء الدين أبو محمد عبد الله بن عبد الرحمن بن عَقيل المصري الشافعيُّ، قاضي قضاة الديار المصرية، وفقيه الشافعية، ولِدَ في المحرم سنة 698، ونسبه يتَّصِلُ إلى عقيل بن أبي طالب، ونشأ بالقاهرةِ، وقرأ على عُلَماءِ عَصرِه، وبرع في علوم كثيرة، وصنف التصانيفَ المُفيدةَ في الفقه والعربية والتفسير، منها شرح الألفية لابن مالك، وشرح التسهيل أيضًا، والجامع النفيس في فقه الشافعية، وباشر قضاء ال"},{"id":3109,"era":"c8","t":"وفاة الملك إبراهيم الحفصي ملك تونس .","s":"هو المَلِكُ أبو إسحاق إبراهيم بن أبي بكر بن يحيى بن إبراهيم بن يحيى، بعدما مَلَك تسع عشرة سنة وشهرين، وهو الملك الرابع عشر من ملوك الحفصيين بتونس، فقام بعدَه ابنه أبو البقاء خالد، وكان حاجِبُه ابن المالقي هو الذي يتولى أمورَ السلطة ويستبِدُّ بها. مات في العشرين من رجب."},{"id":3110,"era":"c8","t":"فتنة العامة في مصر ضد ظلم الوالي .","s":"في يومِ الجمعة ثالثَ عَشرَ ذي القعدة تجمَّعَت الغوغاء من زعر العامة بأراضي اللوق خارج القاهرة للشلاق، فقُتِلَ بينهم واحد منهم، فركب والي القاهرة الشريفُ بَكتمُر، وأركب معه الأميرَ علاء الدين علي بن كَلَفت الحاجب، والأمير أقبغا اليوسفي الحاجب، وقصد المشالقينَ، ففروا منهم، وبَقِيَ من هناك من النظَّارة، فضرب عِدَّةً منهم بالمقارع، فتعَصَّبت العامة، ووقفوا تحت القلعةِ في يوم الثلاثاء، وأصبحوا يوم الأر"},{"id":3111,"era":"c8","t":"مقتل الأمير قشتمر المنصوري نائب حلب .","s":"في هذه السَّنةِ قُتِلَ الأميرُ قشتمر المنصوري نائب حلب، وخبَرُه أنَّه لَمَّا وَلَيَ نيابة حلب في جمادى الآخرة من هذه السنة وتوجَّه إلى حلب، فلم يُقِمْ بها إلا يسيرًا، ثم إن بني كلاب كَثُر فسادُهم وقَطْعُهم الطريقَ فيما بين حماة وحلب، وأخذوا بعضَ الحُجَّاج، فخرج إليهم الأمير قشتمر نائِبُ حلب بالعسكر، حتى أتوا تلَّ السلطان بظاهر حلب، فإذا عدَّةٌ من مضارب عرب آل فضل، فاستاق العسكَرُ جمالَهم ومواشيَهم"},{"id":3112,"era":"c8","t":"الفرنج يحاولون النزول على الإسكندرية .","s":"في يومِ الجمعة ثامِنَ ذي الحجة قَدِمَ الخبر بنزول أربع قطايعَ على الإسكندرية من الفرنج، وأنهم رمَوا على المدينة بمنجنيق، فخرج تلك الليلةَ ثلاثة وعشرون أميرًا، منهم ثلاثةٌ من الألوف وعشرة من الطبلخاناه وعشرة من أمراء العشرات، فقَدِمَ الخبر في عشية السبت أنَّ المغاربة والتركمان نزلوا في المراكب، وقاتلوا الفرنج، وقتلوا منهم نحوَ المائة، وغنِموا منهم مركبًا."},{"id":3113,"era":"c8","t":"ظهور دولة تيمورلنك وعاصمتها سمرقند .","s":"كان مِن وَلَدِ جنكيز خان, جغطاي الذي استقَرَّ في تركستان وبَقِيَت أسرته تحكُمُ هذه المنطقةَ وكان توغلق تيمور أحدَ ملوك المغول واستقَرَّ في أعمال تركستان الشرقية عام 748 وأعلن أنَّه حفيدُ داود خان، وضَمَّ إليه بلادَ ما وراء النهر ودخلت في أيَّامِه أعدادٌ كبيرة من المغول إلى الإسلام، ثم إنَّ والي سمرقند تحرَّك نحو مدينة هراة واحتَلَّها، ثمَّ إنه اغتِيلَ واختلف الأهالي وعَمَّتهم الفوضى، فوصل الخبر إل"},{"id":3114,"era":"c8","t":"الغزو الغرناطي على الإسبان .","s":"ما زال محمد الخامس الغني بالله يتابِعُ الغزو فزحف بقواتِه على مدينة قرمونه، واقتحم مدينةَ قشتالة، وكان محمَّد الخامس هذا قد استغَلَّ الأحداث الداخلية والفِتَن التي ثارت في قشتالة أيام ملكها بيدرو بعد وفاة أبيه الملك ألفونسو الحادي عشر، فكانت فترة قلاقل داخلية؛ حيث جرى بين بيدرو وأخيه هنري الذي استعان بالإنكليز وأما بيدرو فاستعان بالفرنسيين، فنشبت بينهما حروبٌ داخلية انتهت بقتل بيدرو وجلوس هنري على"},{"id":3115,"era":"c8","t":"وفاة تاج الدين السبكي (الابن) الشافعي .","s":"هو الإمامُ العالمُ الفقيه المحَدِّث النحوي الناظِمُ: تاج الدين أبو نصر عبد الوهاب ابن العلامة الفقيه قاضي القضاة تقي الدين علي بن عبد الكافي بن علي بن تمام بن يوسف بن موسى بن تمام الأنصاري السلمي السبكي الشافعي، قاضي قضاة دمشق بها، ولد بالقاهرة سنة 728. قال الصفدي: \"عُنِيَ تاج الدين بالرواية وسمع كثيرًا، وقرأ بنفسه على شيخنا شمس الدين الذهبي كثيرًا من مصنفاته وغيرها، وأفتى ودرَّس، ونظم الشعر وعمل "},{"id":3116,"era":"c8","t":"الفرنج يطلبون الصلح .","s":"في أوَّلِ صَفَر قَدِمَت رُسُل الفِرنجَ لطَلَبِ الصلح، فحلَفوا على ألَّا يَغدِروا ولا يحزنوا، وخُلِع عليهم، وسافروا ومعهم من يُحلِّفُ مَلِكَهم، وأُخِذَت منهم رهائن بالقلعة، ثم في جمادى الأولى عادت رسلُ الفرنج ومعهم عِدَّة مِمَّن أسروهم من المسلمين نحو المائة، ثمَّ في جمادى الآخرة بعث الفرنج من بقي من أسرى المسلمين ببلادهم، وتم الصلحُ، وفُتِحَت كنيسةُ القيامة بالقدس."},{"id":3117,"era":"c8","t":"خلع الملك الحفصي أبي البقاء خالد وتولي ابن عمه المستنصر بالله .","s":"خُلِعَ أبو البقاء خالد بن إبراهيم بن أبي بكر متمَلِّك تونس، بعد إقامته في المُلْك سنة وتسعة أشهر تنقُصُ يومين، وهو الخامس عشر من ملوك الحفصيين بتونس، وكان صبيًّا والأمر بيد الحاجِبِ ابن المالقي، وقام بعدَه ابنُ عَمِّه أبو العباس أحمد بن محمد بن أبي بكر بن يحيى بن إبراهيم، وقد كان هذا أميرَ قُسنطينة وبجاية، فلما استطاع الزحفَ على تونس قَتَل الحاجي ابن المالقي وفَرَّ خالد المخلوع، لكِنَّه قبض عليه و"},{"id":3118,"era":"c8","t":"وفاة جمال الدين الإسنوي صاحب طبقات الشافعية .","s":"هو الشَّيخُ جمال الدين أبو محمد عبد الرحيم بن الحسن بن علي بن عمر بن علي بن إبراهيم الأرموي الإسنوي نزيلُ القاهرة، ولِدَ في العشر الأواخر من ذي الحجة سنة 704. وقدِمَ القاهرة سنة 721 وحَفِظَ التنبيه وسَمِعَ الحديث من الدبوسي والصابوني وغيرهما، وحدث بالقليل، وأخذ العلمَ عن الجلال القزويني، والقونوي، وغيرهما، وأخذ العربية عن أبى حيَّان، ثم لازم بعد ذلك التَّدريسَ والتصنيفَ, فدرَّسَ بالملكية والأقبغاو"},{"id":3119,"era":"c8","t":"تآمر الأمير ساوجي ابن السلطان مراد الأول على أبيه .","s":"تآمَرَ ساوجي ابنُ السلطان مرادِ الأوَّلِ مع الأمير أندرونيقوس ابنِ الإمبراطور البيزنطي يوانيس، وسارا على رأسِ جيشٍ مِن البيزنطيين وبعضِ المخدوعين من الجنودِ العثمانيين؛ لمحاربةِ جيش السلطانِ مراد, فكانت نتيجةُ المعركة هزيمةَ المتآمرين ووقوعَ الأمير ساوجي في الأسْر، فأصرَّ والده السلطان مراد أن يَعرِضَ أمره على علماء الشريعة وقضاتها، فحكموا عليه بعقوبة الموتِ جزاءَ خروجه على طاعةِ ولي الأمر وموالات"},{"id":3120,"era":"c8","t":"وفاة المهدي علي بن محمد إمام الزيدية باليمن .","s":"هو المهديُّ لدينِ الله علي بن محمد بن علي بن منصور من سلالة الناصر بن الهادي إلى الحَقِّ من أئمة الزيدية في اليمن، ولِدَ في هجرة من قرى إلهان, وبويع بالإمامة بعد وفاة المؤيَّدِ بالله يحيى بن حمزة، افتَتَح صنعاء واستولى على صَعدة وذمار، وقاتل الباطنيَّةَ وخَرَّبَ قُراهم وأمَّن الطُّرُقات وأزال سَبعَ عَشرة إمارةً مستقِلَّةً، وكان فقيهًا مجتهدًا، وله تصانيفُ ومختصرات ورسائل. أُصيبَ بالفالج أو بعِلَّة"},{"id":3121,"era":"c8","t":"انتصار السلطان العثماني مراد الأول على الصرب في (جرمن) .","s":"أرسلَ سُلطانُ العُثمانيين مراد الأول جيشًا لاجتياح البلقان، فالتقى بالصرب في تشيرنوفو على نهر مارتيزا، فحدثت بينهم معركةٌ قوية، انهزم فيها أمراءُ الصِّرب، وكان من نتيجةِ هذه المعركة اعترافُ أمراء البلغار ومقدونيا والإمبراطورية البيزنطية بسيادةِ السَّلطنةِ العُثمانية في البُلقان."},{"id":3122,"era":"c8","t":"السلطان الأشرف يرسم للأشراف بعلامة خضراء ليعرفوا بها .","s":"رسم السلطانُ المَلِكُ الأشرَفُ أنَّ الأشرافَ بالديارِ المِصريَّة والبلاد الشامية كُلَّهم يَسِمونَ عمائِمَهم بعلامةٍ خَضراءَ بارزةٍ للخاصَّةِ والعامَّةِ؛ إجلالًا لحَقِّهم وتعظيمًا لقَدْرِهم؛ ليُقابَلوا بالقَبولِ والإقبالِ، ويَمتازوا عن غَيرِهم من المُسلِمينَ، فوقع ذلك ولَبِسَ الأشرافُ العمائِمَ الخُضرَ، فقال الأديبُ شَمسُ الدين محمد بن إبراهيم الشهير بالمزين، في هذا المعنى:أطرافُ تيجانٍ أتَت مِن سُ"},{"id":3123,"era":"c8","t":"وفاة الإمام الحافظ ابن كثير .","s":"هو المُحَدِّث الإمامُ الفقيهُ الحافِظُ الأوحَدُ البارعُ: عماد الدين أبو الفداء إسماعيلُ بن الخطيب شهاب الدين أبي حفص عمر بن كثير القرشي البصروي ثم الدمشقي الشافعي، صاحِبُ التفسيرِ والتاريخِ، صِهْرُ الشيخِ أبي الحجَّاج المِزِّي، مَولِدُه بقريةٍ شرقيَّ بُصرى من أعمال دمشق في سنة 701 كان أبوه خطيبًا بها، ثم انتقل إلى دمشق في سنة 706. تفقه ابن كثير بالشيخ برهان الدين الفزاري وغيره، وصاهر الحافِظَ المز"},{"id":3124,"era":"c8","t":"اختلاف السلطان الأشرف مع زوج أمه بسبب التركة .","s":"وقع بين المَلِك الأشرَفِ وبين زوج أمِّه ألجاي اليوسفي كلامٌ مِن أجل التَّرِكة المتعَلِّقة بخوند-السيدة- بركة والدة الأشرف, وكان ذلك يومَ الثلاثاء سادس المحرَّم مِن هذه السنة، وكَثُرَ الكلام بين السلطان وبين ألجاي اليوسفي، حتى غضب ألجاي، وخرج عن طاعةِ المَلِك الأشرف، ولبس هو ومماليكُه آلة الحرب، ولَبِسَت مماليلك السلطان أيضًا، وركِبَ السلطان بمن معه مِن أمرائه وخاصكيته، وباتوا الليلةَ لابسين السلاح"},{"id":3125,"era":"c8","t":"خلع صاحب فاس وبلاد المغرب السعيد محمد بن عبدالعزيز .","s":"خُلِعَ صاحبُ فاس وبلاد المغرب السعيد محمد بن عبد العزيز أبي الحسن، ومَلَك بعده السُّلطانُ أبو العباس أحمد بن أبي سالم إبراهيم ابن أبي الحسن."},{"id":3126,"era":"c8","t":"وفاة الوزير لسان الدين الخطيب القرطبي .","s":"هو الوزيرُ العلَّامة أبو عبد الله محمد بن عبد الله بن سعيد بن عبد الله بن سعيد بن علي بن أحمد السلماني, قرطبي الأصل, نزل سلفة طليطلة ثم لوشة ثم غرناطة، كان سلفة قديمًا يُعرَفون ببني وزير، ثم صاروا يُعرَفون ببني الخطيب نسبةً إلى سعيد جده الأعلى، وكان قد ولِيَ الخَطابة بها وتحَوَّل جَدُّه الأدنى سعيد إلى غرناطة. ولِدَ لسان الدين سنة 713 في لوشة ونشأ في غرناطة، كان عالِمًا بالتاريخ والفلسفة والرياضيا"},{"id":3127,"era":"c8","t":"وفاة أويس بهادر خان متملك توريز وبغداد .","s":"هو أُوَيس بهادر خان ابن الشيخ الحسن الكبير بن حسين بن أقبغا بن أيلكان المغولي ثم التبريزي، سلطان بغداد وتوريز، استقَرَّ في سلطنة بغداد بعد سنة 760. خطب بمكَّة للخان أويس بعد أن وصلت منه قناديلُ حَسَنة للكعبة، وهديةٌ طائلة لأمير مكة عجلان، واستمرت الخُطبة له بمكَّة فترة من الزمن، مات عن نيِّف وثلاثين سنة، منها في السَّلطنة تسع عشرة سنة، وكان قد اعتزل قبلَ مَوتِه، وأقام عِوَضَه في المملكة ابنَه الشي"},{"id":3128,"era":"c8","t":"وباء وغلاء عام في مصر وهلاك الكثير من الناس بسببه .","s":"ابتدأ الوباءُ في النَّاسِ في القاهرة ومِصرَ في نصف جمادى الآخر، وكَثُر مَوتُ الفقراء والمساكين بالجوع، وقد توقَّفَت أحوال الناس من قِلَّة المكاسب؛ لشِدَّة الغلاء وعَدَمِ وجودِ ما يُقتاتُ به، وشَحَّ الأغنياءُ وقَلَّت رَحمتُهم، فمن كان يكتَسِبُ في اليوم درهمًا يقومُ بحالِه ويَفضُلُ له منه شيء، صار الدِّرهَمُ لا يجدي شيئًا، فمات ومات أمثالُه من الأُجَراء والعُمَّال والصنَّاع والفلاحين والسُّؤَّال من "},{"id":3129,"era":"c8","t":"فتح سيس وإنهاء حكم الأرمن عليها .","s":"توجَّه الأميرُ بيدمر نائِبُ الشام في تاسع عشر من ذي القعدة بعساكِرِ حَلَب إلى سيس، وهي كرسي الأرمن فنازلها، وحصر التكفور متمَلِّكَها مدةَ شهرين حتى طلب الأمانَ؛ مِن فَناءِ أزوِدَتِهم، وعَجْزِهم عن العسكر، فتسَلَّمَ الأمير أشَقتمُر قلعَتَها، وأعلن في مدينةِ سيس بكلمة التوحيد، ورتَّبَ بها عسكرًا، وأخذ التكفورَ وأمراءَه، من أجناد وعاد إلى حلب، وجَهَّزَهم إلى القاهرة، فبعث السلطانُ الأميرَ يعقوب شاه ل"},{"id":3130,"era":"c8","t":"غلاء ووباء عظيم في الشام .","s":"وقعَ غلاء الأسعار بدمشق حتى أكلت النَّاسُ المَيتاتِ والكلابَ والقِطَط، ومات خلقٌ كثير من المساكين، وانكشف عِدَّةٌ من الأغنياء، وعَمَّ الغلاء ببلاد الشام كلِّها، حتى أُكِلَت القطط وبِيعَت الأولادُ بحَلَب وأعمالِها."},{"id":3131,"era":"c8","t":"وفاة أمير مكة الشريف عجلان بن رميثة .","s":"هو أميرُ مَكَّة الشريفُ عَجلان بن رُمَيثة بن أبي نُمَي محمد بن أبي سعد علي بن الحسن بن قتادة بن إدريس بن مطاعن بن عبد الكريم بن موسى بن عيسى بن سليمان بن عبد الله بن موسى الجور بن عبد الله الكامل بن الحسن المثنى بن الحسن ابن أمير المؤمنين علي بن أبي طالب، وكان قبل موته نَزَل لوَلَدِه الشريف أحمد بن عجلان عن نِصفِ إمرةِ مَكَّة التي كانت بيده؛ فإنه كان قبل ذلك نزَل له عن النصفِ الأوَّلِ قديمًا، وكان"},{"id":3132,"era":"c8","t":"وفاة الملك المظفر فخر الدين داود صاحب ماردين وتولى بعده ابنه .","s":"هو السلطانُ المَلِكُ المظَفَّر فخر الدين داود ابن الملك الصالح صالح ابن الملك المنصور غازي بن ألبي بن تمرتاش بن إيل غازي بن أرتق الأرتقي، صاحِبُ ماردين وابنُ صاحبها بماردين، وكان الملك المظفَّر هذا وَلِيَ مُلكَ ماردين بعد ابن أخيه الملك الصالح محمود الذي أقام في سلطنة ماردين أربعة أشهر عوضًا عن والده الملك المنصور أحمد ابن الملك الصالح صالح، وخُلِعَ الملك الصالح محمود، وتسلطن الملِكُ المظفر، فأظهر"},{"id":3133,"era":"c8","t":"وفاة الملك الأفضل عباس صاحب اليمن وتولي ابنه إسماعيل .","s":"هو السُّلطانُ المَلِك الأفضل عباسُ ابن الملك المجاهد علي ابن الملك المؤيد داود ابن الملك المظفر يوسف بن عمر بن علي بن رسول التركماني الأصل، اليمني صاحب اليمن وابنُ صاحِبِها، ولي الأفضَلُ السلطنة بعد موت أبيه المجاهد في شهر جمادى الأولى سنة 764، ولما ولي اليمَنَ خرج في أيامِه ابنُ ميكائيل فوقع له معه وقائِعُ، حتى أباده الأفضَلُ وزالت دولةُ ابن ميكائيل في أيامه، وكان الأفضَلُ شجاعًا مهابًا كريمًا، و"},{"id":3134,"era":"c8","t":"اغتيال السلطان الأشرف شعبان وتولية ابنه علي .","s":"هو السُّلطانُ الأشرف شعبان بن حسين الناصر بن المنصور قلاوون. بويِعَ للمَلِكِ الأشرف شعبان بعد عزل الملك المنصور، وله من العُمُرِ قَريبُ العشرين. كان الملِكُ الأشرف شعبان قد توعَّكَ، ومع ذلك أصر بالسَّفَرِ إلى الحج هذا العام وسافر وهو متوَعِّك، فلما كان يوم السبت ثالث ذي القعدة اتَّفق طشتمر اللفاف، وقرطاي الطازي، وأسندمر الصرغتمشي، وأينبك البحري، وجماعة من المماليك السلطانية، وجماعة من مماليك الأسي"},{"id":3135,"era":"c8","t":"نواب الشام وأمراء مصر يعصون على أيبك البدري لسوء أفعاله .","s":"بينما أيبك البدريُّ في أمْرِه ونَهْيِه بمصرَ، ورد عليه الخبَرُ بعصيان نوَّاب الشامِ، ففي الحال علَّق أيبك جاليش السفر في التاسع عشر من ربيع الأوَّل ورسم للعساكر بالتجهيز إلى سفر الشام وأسرع بالنفقةِ على العساكر وتجهَّزَ في أسرع وقت وخرج الجاليش من القاهرة إلى  الريدانية في السادس والعشرين من ربيع الأول، وهم خمسةٌ من أمراء الألوف ومائةُ مملوك من المماليك السلطانية، ومائةُ مملوك من مماليك الأتابك أي"},{"id":3136,"era":"c8","t":"أيبك البدري أمير العساكر يخلع الخليفة المتوكل .","s":"صار الأمرُ في المملكة لأيبك البدري وَحْدَه من غير منازع، وأخذ أيبك في المملكة وأعطى، وحكم بما اختاره وأراده، فمِن ذلك أنَّه في رابع شهر ربيع الأول رَسَم بنفي الخليفة المتوكِّل على الله إلى مدينة قوص، فخرج المتوكِّلُ على الله، ثم شُفِعَ فيه فعاد إلى بيته، ومن الغَدِ طَلَب أيبك نجم الدين زكريا بن إبراهيم ابن الخلفية الحاكمِ بأمر الله وخَلَع عليه واستقَرَّ به في الخلافة عِوَضًا عن المتوكل على الله من"},{"id":3137,"era":"c8","t":"وفاة الرحالة ابن بطوطة  .","s":"هو أبو عبدِ الله محمَّدُ بن محمد بن عبد الله بن إبراهيم الطنجي اللواتي المغربي من أسرة بطوطة، وُلِدَ بطنجة سنة 703 اشتُهِرَ برحلته التي دامت ثمانية وعشرين سنة على ثلاثة رحلات: الأولى بدأها من طنجة سنة 725 طاف فيها المغرب إلى مصر، ثم مكة ثم العراق وإيران والمشرق، ثم بلاد الأناضول، ثم إلى الحجاز ثم مكة ثم إلى اليمن وبلاد الخليج العربي، ثم مصر والشام، ثم القسطنطينية، ثم مكة ثم عاد إلى المغرب، كُلُّ ذ"},{"id":3138,"era":"c8","t":"عصيان الأمير إينال اليوسفي على الأمير برقوق وما جرى بينهما .","s":"لما كان يومُ الرابع والعشرين شعبان ركب الأتابكُ برقوق من الإسطبل السلطاني في حواشيه ومماليكه للتسير على عادته، وكان الأميرُ بركة الجوباني مسافرًا بالبحيرة للصيد، فلما بلغ إينال اليوسفي أمير سلاح ركوبُ برقوق من الإسطبل السلطاني، انتهز الفرصة لركوبِ برقوق وغَيبة بركة، وركب بمماليكِه وهجم الإسطبلَ السلطانيَّ ومَلَكَه، ومسَكَ الأميرَ جركس الخليلي، وكان مع إينال جماعةٌ من الأمراء ولما طلع إينال إلى باب"},{"id":3139,"era":"c8","t":"واقعة كنيسة ناحية بو النمرس من الجيزة .","s":"في يوم الأربعاء الثامِنَ مِن رمضان كانت واقعةُ كنيسة ناحية بو النمرس من الجيزة؛ وذلك أنَّ رجلًا من فُقَراء الزيلع بات بناحية بو النمرس، فسَمِعَ لنواقيس كنيسَتِها صوتًا عاليًا، وقيل له إنَّهم يضربون بنواقيسهم عند خُطبةِ الإمام للجمعة، بحيث لا تكادُ تُسمَعُ خُطبة الخطيب، فوقف للسُّلطان الملك الأشرف شعبان، فلم يَنَل غَرَضًا، فتوجه إلى الحجاز وعاد بعد مدة طويلة، وبيده أوراق تتضَمَّنُ أنه تشفع برسول ال"},{"id":3140,"era":"c8","t":"حدوث إصلاحات بمكة والحرم .","s":"أجرى الأميرُ باشاه- دوادار الأمير بركة- عينَ الأزرق المستمَدَّة من عين ثقبة، وعين ابنَ رَخَم من عرفة إلى البركتين خارج باب المعلَّاة بمكة المشَرَّفة, وجدد الميضأةَ عند باب بني شيبة، والرَّبع والحوانيت، وأصلح زمزمَ والحِجرَ والميزابَ، وسَطْح الكعبة."},{"id":3141,"era":"c8","t":"فتنة الحائط الذي يتكلم بمصر .","s":"في هذه السَّنةِ كانت بالدِّيارِ المصرية واقعةٌ غريبة من كلامِ الحائط، وخبَرُه أنَّ في أوائل شهر رجب من هذه السنة ظهر كلامُ شَخصٍ مِن حائط في بيت العدلِ شهاب الدين أحمد الفيشي الحنفي بالقُربِ مِن الجامع الأزهر، فصار كلُّ من يأتي إلى هذا الحائط ويسألُه عن شيء يرُدُّ عليه الجوابَ ويُكَلِّمُه بكلام فصيح، فجاءته الناسُ أفواجًا، وتردَّدَت إلى الحائِطِ أكابِرُ الدولةِ، وتكلموا معه!! وافتتن الناس بذلك الم"},{"id":3142,"era":"c8","t":"ظهور رجل يدعي النبوة بمصر .","s":"في يوم الثلاثاء خامس عشر شوال قُبِضَ على رجل ادَّعى النبوة، وأنه النبيُّ صلَّى الله عليه وسلم الأميُّ، وأنه مُصَدِّقٌ بنبُوَّة نبيِّنا، وزعم أنَّ حروف القرآن تَنطِقُ له مع أنه أمي، وأن الذي يأتيه بالوحيِ جبرائيل وميكائيل وإسرافيل وعزرائيل، ورضوان ومالك ودرديائيل، وزعم أنه عربيٌّ من مصر، وأنه أُرسِلَ بقَتلِ الكفرة، وأن الترك يحَكِّمونه ويملكونه عليهم، وأنَّه أُنزِلَ عليه القرآن فسُجِنَ عند المجانين"},{"id":3143,"era":"c8","t":"مقتل عدد ممن ارتدوا عن الإسلام وعادوا للنصرانية .","s":"حضر إلى القاهرة طائفةٌ ما بين رجال ونساء، ذكروا أنهم ارتَدُّوا عن الإسلامِ، وقد كانوا قبل ذلك على النصرانية، يريدونَ بارتدادِهم التقَرُّبَ إلى المسيح بسَفكِ دمائهم، فعُرِضَ عليهم الإسلام مرارًا فلم يقبلوا، وقالوا: \"إنما جئنا لنتطَهَّر ونتقَرَّب بنفوسنا إلى السيد المسيحِ\" فقُدِّمَ الرجال تحت شباك المدرسة الصالحية بين القصرين، وضُرِبَت أعناقهم، وعُرِضَ الإسلام على النساء، فأبَيْنَ أن يُسلِمْن، فأخذَ"},{"id":3144,"era":"c8","t":"الفتنة بين الأمير بركة والأمير برقوق .","s":"في ليلةِ الجمعة تاسِعَ عَشَر صفر لَبِسَ الأمير بركة السلاحَ هو ومماليكه، ولبس الأمراءُ أيضًا وباتوا في إسطبلاتهم على احتراز، فلما أصبح نهارُ يوم الجمعة، طلب الأميرُ الكبير برقوق القضاةَ ومشايخَ العلم وندبهم للدخول بينه وبين الأمير بركة في الصُّلحِ؛ مكيدةً منه ودَهاءً، فما زالوا يتردَّدونَ بينهما عِدَّة مرار، حتى وقع الصلحُ على دَخَن، وحلف كلٌّ منهم لصاحبه، ونزعوا عنهم السلاحَ، فبعث الأميرُ برقوق ب"},{"id":3145,"era":"c8","t":"كثر الوباء بالإسكندرية .","s":"كثر الوباء بالإسكندرية، فمات في كل يوم ما ينيف على مائة وخمسين إنسانًا، وتمادى إلى ذي الحِجَّة."},{"id":3146,"era":"c8","t":"غزو المغول الروس ودخول توقتاميش خان موسكو .","s":"بعد وفاةِ محمد بردي بك أمير أذربيجان سنة 762 وقد كان ولَدُه توقتاميش صغيرًا على الملك فعَمَّت الفوضى البلاد فاستقَلَّ الحاج جركس بمنطقة استراخان، واستقَلَّ ماماي بمنطقة القرم، وأما منطقة سراي فحَكَمَها خضر بك وهرب توقتاميش إلى سمرقند إلى تيمورلنك، فاستغَلَّ الروس هذا الاختلاف فانقَضُّوا على التتار والتَقَوا مع ماماي وانتصروا عليه، فقام توقتاميش بالرجوع إلى سراي وحكَمَها بمساعدة تيمورلنك، ثم في هذه"},{"id":3147,"era":"c8","t":"وقوع الوباء بالطاعون في الناس بالقاهرة ومصر .","s":"في المحرَّم من هذا العام بدأ انتشارُ وباء الطاعون في الناس بالقاهرة ومصر، وتزايد حتى بلغ عِدَّةُ من يموت في اليوم ثلاثمائة مَيِّت!"},{"id":3148,"era":"c8","t":"وفاة السلطان المنصور علي بن شعبان وتولي أخيه حاجي .","s":"هو السُّلطانُ المَلِكُ المنصور علي ابن الأشرف شعبان بن حسين الناصر بن المنصور قلاوون. مَرِضَ السلطان المنصور ولزم الفراش، حتى مات بين الظُّهرِ والعصر من يوم الأحد الثالث والعشرين صفر، ودفن من ليلته بعد عشاء الآخرة في تربةِ جَدَّتِه لأبيه خوند بركة بالقُبَّة التي بمدرستها بالتبانة، وكان الذي تولَّى تجهيزه وتغسيلَه ودَفْنَه الأميرَ قطلوبغا الكوكائي، وكانت مُدَّة سلطنته على ديار مصر خمس سنين وثلاثة أ"},{"id":3149,"era":"c8","t":"وفاة الإمام العالم شهاب الدين الأذرعي الشافعي .","s":"هو الشَّيخُ الإمامُ العالم شهابُ الدين أبو العباس أحمد بن حمدان بن أحمد بن عبد الواحد بن عبد الغني بن محمد بن أحمد بن سالم بن داود الأذرعي الشافعي، نزيلُ حَلَب، وُلِدَ سنة 707، وتفَقَّه بدمشق قليلًا، وناب في بعض النواحي في الحُكمِ بها، ثم تحوَّل إلى حلب فقَطَنَها، وناب في الحُكم بها، ثم ترك وأقبَلَ على الاشتغال والتصنيف والفتوى والتدريس، وجمع الكتبَ حتى اجتمع عنده منها ما لم يحصُلْ عند غيره، وظَفِ"},{"id":3150,"era":"c8","t":"عصيان الأمير علاء الدين ألطنبغا على السلطان برقوق .","s":"سار الأميرُ يلبغا الناصري نائِبُ حلب بعسكر حلب إلى إلبيرة، يريدُ تعدية الفرات، فجاءه الخبر بعصيانِ الأمير علاء الدين ألطنبغا السلطاني نائب الأبلستين، وأنه لم يحلِفْ للسلطان برقوق واستولى على قلعةِ درندة وطلع إليها، وأمسك بعض أمرائِها، وأطلع إليها ذخيرة وميرة، فركب العسكَرُ الذي بالمدينة عليه، وأمسكوا رجالَه، فطلب الأمان منهم، وفَرَّ مِن القلعة إلى الأبلستين، فكتب إليه الأميرُ يلبغا الناصري يهَدِّد"},{"id":3151,"era":"c8","t":"وفاة السلطان الملك حسين الجلائري المغولي ملك بغداد وتبريز .","s":"هو السُّلطانُ المَلِكُ المعِزُّ حسين بن أويس ابن الشيخ حسن بن حسين بن آقبغا بن أيلكان، المنعوت بالشيخ حسين، سلطان بغداد وتبريز وما والاهما، وكان سبط القان أرغون بن بوسعيد ملك التتار، ولِيَ سلطنة بغداد في حياة أبيه؛ لأنَّ والده أويسًا كان رأى منامًا يدُلُّ على موته في يومٍ مُعَيَّن، فاعتزل المُلْكَ وسَلْطَنَ ولَدَه هذا، ودام الشيخُ حسين هذا في الملك إلى أن قتَلَه أخوه السلطان أحمد بن أويس وملك بغدا"},{"id":3152,"era":"c8","t":"العثمانيون يفتحون صوفيا عاصمة البلغار .","s":"تأخَّرَ الصِّربُ والبلغار في دفع الجزية، ويبدو أنَّ ذلك عن اتفاق بينهم، فتوجَّهَت الجيوش العثمانية إلى بلادِهم، ففتحت بعضَ المدن الصربية التي تقع اليومَ جنوبي يوغسلافيا، كما حاصرت عاصمة البلغار صوفيا، وفتحتها بعد حصار دام ثلاث سنواتٍ، فكان في هذه السَّنةِ الفَرَجُ بفَتحِها، كما فُتِحَت مدينة سلانيك المدينة اليونانية المشهورة والواقعة على بحر إيجه."},{"id":3153,"era":"c8","t":"خلع السلطان الصالح حاجي وتولي برقوق أول مماليك الشراكسة .","s":"حاوَلَ بَعضُ الأمراء القضاءَ على برقوق وقَتْلَه، لكنَّه استطاع أن يقبِضَ عليهم ويسجِنَهم، ولكنه استمَرَّ بعد مَسْك هؤلاء في تخوف عظيم، واحترز على نفسه من مماليكِه وغيرِهم غايةَ الاحتراز، فأشار عليه بعد ذلك أعيانُ خشداشيته- زملاء مهنته- وأصحابه مثل أيتمش البجاسي، وألطنبغا الجوباني أمير مجلس، وقردم الحسني، وجركس الخليلي ويونس النوروزي الدوادار وغيرهم أن يتسلطَنَ ويحتَجِبَ عن الناس ويستريح ويُريحَ مِ"},{"id":3154,"era":"c8","t":"بعض النصارى يضربون مؤذنًا بسبب العرس .","s":"في شَهرِ جمادى الأولى اتَّفَق بناحية برما من الغربية أنَّ طائفة من مُسلِمةِ النصارى، صَنَعوا عُرسًا جمعوا فيه عِدَّةً من أرباب الملاهي، فلما صَعِدَ المؤذن ليسَبِّحَ الله تعالى في الليل على العادة، سَبُّوه وأهانوه، ثم صَعِدوا إليه وأنزلوه، بعدما ضربوه، فثار خطيب الجامِعِ بهم؛ ليُخَلِّصَه منهم، فأوسعوه سبًّا ولعنًا وهَمُّوا بقتله وقَتْلِ من معه، فقَدِمَ إلى القاهرة في طائفة، وشكَوا أمرهم إلى الأمير "},{"id":3155,"era":"c8","t":"السلطان برقوق يخلع الخليفة العباسي المتوكل ويولي محمد بن الواثق الخلافة .","s":"في أوَّلِ شَهرِ رَجَب من هذه السنة طلع الأميرُ صلاح الدين محمد بن محمد بن تنكز نائب الشام إلى السلطانِ ونقل له عن الخليفة المتوكل على الله أبي عبد الله محمد أنَّه اتفق مع الأمير قرط بن عمر التركماني المعزول عن الكشوفيَّة ومع إبراهيم بن قطلوقتمر العلائي أمير جاندار ومع جماعةٍ من الأكراد والتركمان، وهم نحو من ثمانمائة فارس، أنَّهم يَثِبون على السلطان إذا نزل من القَلعةِ إلى الميدان في يوم السَّبتِ ل"},{"id":3156,"era":"c8","t":"الفرنج يغزون بيروت .","s":"سار الأميرُ يلبغا الناصري نائب حلب من حلب بالعسكر للقاءِ الفرنج، وقد وردت شوانيهم في البَحرِ لِقَصدِ إياس، ونزوله بالعمق لقربه من البحر، فورد عليه كِتابُ نائب اللاذقية بوصول الفرنج إلى بيروت، وأنهم نزلوا إلى البر، وملكوا بعض أبراجِها، فأدركهم العسكرُ الشامي في طائفةٍ مِن رجَّالة الأكراد، وقاتلوهم، فأيَّدَ الله المسلمين، حتَى قتلوا من الفرنج نحو خمسمائة رجل، وانهزم باقيهم إلى مراكبهم، وساروا وعادت "},{"id":3157,"era":"c8","t":"محاربة التركمان المتمردين في سيس .","s":"كُتِبَ بتَجريدِ عَسكَرِ دمشق وطرابلس وحماة وحلب، ونواب الثغور وتركمان الطاعة وأكرادها، إلى جهة التركمان العصاة بالبلاد السيسية، كالصارم بن رمضان نائب أدنه وبني أوزر، وابن برناص من طائفة الأجقية؛ لمقاتلتهم على تعديهم طريقَهم، وقطْعِهم الطرقات، ونهْبِهم حُجَّاج الروم، ولاتفاقهم مع الأمير علاء الدين علي بك بن قرمان صاحب لارندة على اقتلاع بلاد سيس، فتأهَّبت العساكِرُ لذلك ووافت حلب، فتقَدَّمها الأميرُ"},{"id":3158,"era":"c8","t":"وفاة عماد الدين ابن بردس البعلبكي .","s":"هو الشَّيخُ الإمام العالم المقرئُ عماد الدين أبو الفداء إسماعيل بن محمد بن بردس بن نصر بن بردس بن رسلان البعلبكي الحنبلي. ولِدَ ببعلبك سنة720، ودرس على والده، وأبي الفتح اليونيني، وسَمِعَ جمعًا من مُسنِدِي عصره، وحَدَّث عنهم، واشتهر باختصارِه لجملة من الكتب ونَظْمها. له بُغية الأريب في اختصار التهذيب، أكمل مسودته في المحرم سنة 779 وهو اختصار ليس فيه إضافات تُذكَر، ولم يحذف من رجال التهذيب أحدًا، ل"},{"id":3159,"era":"c8","t":"تنظيم الخيالة العثمانيين سياه .","s":"نظَّمَ القائِدُ الوزير تيمور طاش باشا فِرَق الخيَّالة العثمانيين المسمَّاة سياهيه أو سياه- على نظام جديد، واختار أن تكون أعلامهم باللون الأحمر الذي لا يزال شعارَ الدَّولة التركية حتى الآن، وأقطع كلَّ نَفَرٍ منهم جزءًا من الأرض يزرعه أصحابه الأصليون مسيحيين كانوا أو مسلمين في مقابلة دَفعِ جُعْلْ مُعَيَّن لصاحب الإقطاع، وذلك بشرط أن يسكنَ الجنديُّ في أرضه وقت السلمِ ويستَعِدَّ للحرب عند الاقتضاءِ عل"},{"id":3160,"era":"c8","t":"خلع أبي العباس ملك بني مرين ومبايعة أبي فارس .","s":"خُلِعَ السُّلطانُ أبو العباس أحمد المستنصر بن إبراهيم بن أبي الحسن المريني مَلِكُ المغرب صاحب فاس ونُفي إلى غرناطة، وبُويع بدلًا منه أبو فارس موسى بن أبي عنان المتوكل على الله، وكان مقيمًا بالأندلس، وتولى الوزير مسعود بن ماساي الأمورَ."},{"id":3161,"era":"c8","t":"نزول مركبين من مراكب الفرنج على رشيد .","s":"نزل مركبانِ مِن مراكِبِ الفرنج على رشيدٍ، فخرج الأميرُ يونس الدوادار، والأمير ألطنبغا المعلم، فلم يُدركوهم."},{"id":3162,"era":"c8","t":"العثمانيون يقاتلون أمير القرمان  .","s":"قام أميرُ دولة القرمان علاءُ الدين وبعضُ الأمراء المستقلين بحَربِ الدَّولةِ العثمانية فأرسل لهم مرادٌ الأول جيشًا انتصر عليهم في سهل قونية، وأخذ الأميرَ علاء الدين أسيرًا، غير أنَّ ابنته زوجةَ السلطان قد توسطت له فأطلَقَ سَراحَه وأبقى له إمارتَه، ولكنه فرض عليه دفع مبلغٍ من المال سنويًّا."},{"id":3163,"era":"c8","t":"الظفر بمراكب للفرنج مقابل دمياط .","s":"في يوم الأربعاء سابعَ عشر جمادى الآخرة قَدِمَ الخبر بأن شواني الأمير ألطنبغا الجوباني سارت من ثغر دمياط في بحرِ الملح، فوجدوا مركبًا فيه الفرنج الجنوية، فأخذوه وأسَروا منهم خمسة وثلاثين رجلًا، وقتلوا منهم جماعةً، ثم قدمت الشواني إلى شاطئ النيل ببولاق خارج القاهرة بالأسرى والغنيمة، فعُرِضَت الأسرى من الغدِ على السلطان."},{"id":3164,"era":"c8","t":"تيمورلنك يستولي على خراسان وسراي وغيرها من البلاد .","s":"في المدَّة ما بين782 إلى 786, استولى تيمورلنك على خراسان وجرجان ومازندران وسجستان وأفغانستان، وفارس وأذربيجان وكردستان، ثمَّ في هذا العام دَبَّ الخلاف بين تيمورلنك وبين توقتاميش؛ إذ هاجم الأخيرُ ضواحيَ سمرقند ولم يكُنْ تيمورلنك فيها، فلما عاد تيمورلنك إلى قاعدة حكمه في سمرقند رجع توقتاميش إلى بلاده، ولم يمضِ طويلُ وقت حتى عاد توقتاميش للإغارةِ مَرَّةً أخرى على سمرقند؛ ممَّا شجع خوارزم على إعلان ال"},{"id":3165,"era":"c8","t":"هزيمة الشريف جماز بن هبة بالمدينة النبوية .","s":"حضر الشَّريفُ جماز بن هبة المدينةَ النبوية بحشده، فحاربه عليُّ بن عطية، وهزمه عنها."},{"id":3166,"era":"c8","t":"هجوم الصرب على أراضي العثمانيين .","s":"استغل الصِّربُ انشغال الجيوش العثمانية بحروبها مع الأمير علاء الدين أمير القرمان، فهاجموا القواتِ العُثمانية في جنوب الصرب من ألبانيا، وحصلوا على بعض النجاحِ سنة 788."},{"id":3167,"era":"c8","t":"وفاة السلطان موسى بن أبي عنان ملك المغرب وتولي الواثق محمد .","s":"هو السُّلطانُ موسى ابن السلطان أبي عنان فارس بن أبي الحسن المريني مَلِك المغرب صاحب مدينة فاس وما والاها، توفي في جمادى الآخرة، وأقيم بعده المستنصر محمد بن أبي العباس أحمد المخلوع، ابن أبي سالم فلم يَتِمَّ أمرُه وخُلِعَ بعد قليل، وأقيم الواثق محمد بن السلطان أبي الحسن، كل ذلك بتدبير الوزير ابن مسعود، وهو يوم ذاك صاحب أمر فاس."},{"id":3168,"era":"c8","t":"نشوب قتال بين عساكر الشام والتركمان .","s":"في أولِ جمادى الآخرة سار عساكر الشام لمحاربة التركمان، وكانت بينهم وقعةٌ عظيمة، قُتِلَ فيها سبعةَ عشر أميرًا، منهم سودن العلائي نائب حماة، وقتل من الأجناد خلق كثير، وانكسر بقية العسكر."},{"id":3169,"era":"c8","t":"وفاة الخليفة العباسي الواثق عمر وتولية أخيه المستعصم زكريا .","s":"هو الخليفةُ العباسي الواثِقُ عُمَرُ ابن الخليفة المستعصم بالله أبي إسحاق إبراهيم بن المستمسك بالله أبي عبد الله محمد بن الإمام الحاكم بأمر الله أبي العباس أحمد بن الحسن بن أبي بكر بن أبي علي إسحاق بن علي القبي. في يوم الاثنين الخامس والعشرين من شوال استدعى السلطانُ برقوق زكريَّا ابنَ الخليفة المعتصم بالله وأعلمه أنَّه يريد أن ينصِبَه في الخلافةِ بعد وفاة أخيه الواثق بالله عمر، ثم استدعى السلطانُ ا"},{"id":3170,"era":"c8","t":"اغتيال أمير مكة الشريف محمد بن عجلان وتولي أبي عنان مكانه .","s":"كان جركس الخليلي أميرًا على الحاج، وكان السلطانُ أوصاه بعَزلِ الصبي المنصوب الشريف محمد أحمد بن عجلان وأن يستبدلَ به الشَّريفَ أبي عنان بن مغامس، والقبض على عمِّ الصبي كبيش بن عجلان، ولما وصل الحاجُّ إلى مكة وخرج الصبيُّ لتلَقِّي المَحمَل الخلافي، وقد أرصد الرجال للبطش بكبيشٍ وأميره المنصوبِ، فقعد كبيش عن الحضور، وجاء الصبي وترجَّلَ عن فَرَسِه لتقبيلِ خُفِّ الجَمَل الذي عليه المحمل كالعادة، وثب به"},{"id":3171,"era":"c8","t":"السلطان الظاهر برقوق يستجلي أخبار تيمورلنك .","s":"أرسل السلطانُ الظاهر برقوق من يستجلي أخبارَ تيمورلنك، فجاءت الأخبار وورد البريد بأنَّ تيمورلنك كبس قرا محمد وكَسَره، ففَرَّ منه في نحو مائتي فارس، ونزل قريب ملطية، ونزل تيمورلنك على آمد، فاستدعى السلطانُ القضاة والفقهاء والأمراء وتحدث في أخذ الأوقافِ من الأراضي الخراجيَّة، فكَثُر النِّزاعُ، وآل الأمر إلى أنه يأخُذُ مُتحَصَّل الأوقاف لسنةٍ، ورسم السلطانُ بتجهيز أربعة من الأمراء الألوف، وهم الأميرُ "},{"id":3172,"era":"c8","t":"خلع الواثق محمد ملك بني مرين وتولية أبي العباس المخلوع سابقا .","s":"خُلع الواثِقُ محمد بن أبي الفضل بن أبي الحسن، وأعيد السلطانُ المخلوع أبو العباس أحمد بن أبي سالم إبراهيم بن أبي الحسن، وكان منفيًّا في غرناطة بعد أن خلع سنة 786، فملك فاس في خامس رمضان، وحُمِلَ الواثق إلى طنجة، فسُجِنَ بها ثم قتل، وكلُّ هذه الأمور حدثت بتدبير الوزير بن ماساي؛ مما دعا أبا العباس أحمد إلى قَتْلِه."},{"id":3173,"era":"c8","t":"عصيان نائب حلب يلبغا الناصري على السلطان برقوق .","s":"خرج الأميرُ يلبغا الناصري نائِبُ حلب عن طاعة السلطان برقوق؛ وذلك لأن السلطان أصلًا كان من مماليكِه، فأبى أن يكونَ مِن تابعيه، وخاصةً أنَّ السُّلطانَ كان يقبض على الكثير من الأمراء بأدنى ريبةٍ؛ مِمَّا أوغر صدورَهم تجاهه، وانضمَّ إلى يلبغا أمير ملطية الأمير تمربغا الأفضلي المعروف باسم منطاش، فأرسل السلطان العساكِرَ لإعادتهم إلى الطاعة، ثمَّ في حادي عشر من جمادى الأولى ورد صراي تَمُر- دوادار الأمير ي"},{"id":3174,"era":"c8","t":"وفاة الشاطبي المالكي الأندلسي صاحب الموافقات .","s":"هو الإمامُ العلَّامة أبو إسحاق إبراهيم بن موسى بن محمد اللخمي الغرناطي الشاطبي، نسبةً إلى شاطبة بالأندلس، ولد بغرناطة ونشأ بها, كان من علماء الأصول والحديث، بارعًا في العلوم وخاصة الأصول، كان من علماء المالكية، له تصانيف أشهرُها: كتاب الموافقات، وهو في أصول الفقه، وكتاب الاعتصام الذي عالج فيه موضوع البِدَع، وله الإفادات والإنشادات، ورسالة في الأدب والطرف، وشرح الألفية، وأصول النحو، وغيرها."},{"id":3175,"era":"c8","t":"وفاة الشيخ بهاء الدين النقشبندي مؤسس الطريقة النقشبندية .","s":"هو الشَّيخُ بهاءُ الدين محمد بن محمد البخاري النقشبندي، مؤسِّسُ الطريقةِ النقشبندية الصوفية المعروفة، يزعُمُ أنَّ مدارَها تصحيح العبودية ودوام العبادة لله ودوام الحضور مع الحَقِّ سُبحانَه، وأنَّ الطريقَ إلى هذا هو الذِّكرُ والمراقبة والرابطة بالشيخ والتخلي عن كلِّ شَيءٍ إلَّا عن محبته، وتتَّبِعُ هذه الطريقةُ التخلِّيَ أو الخلوة، وتوجيه الباطن إلى الله عن طريق الرابطة بالشيخ، وهي ما يسمُّونه الرابط"},{"id":3176,"era":"c8","t":"إعادة الخليفة العباسي المتوكل للخلافة بدلا من المستعصم زكريا .","s":"قام السُّلطانُ الظاهر برقوق بإعادةِ الخليفة المتوكِّل للخلافة بعدما كان قد خلعه عام 785, وسجنه بقلعة الجبل وقتَها، ولَمَّا أحَسَّ بالخطر الذي حَوْلَه من عصيان الناصري عليه والأمراء الذين معه؛ لعله أراد بذلك كسب الرضا أكثر، ففي يوم الجمعة عاشر جمادى الأولى من هذه السنة خُطِبَ للخليفة المتوكل على الله أبي عبد الله محمد، فإنَّه أعيد إلى الخلافة ثم قرئ تقليدُه في الثاني عشر بالمشهد النفيسي، وحضره القض"},{"id":3177,"era":"c8","t":"عصيان الأمراء على السلطان برقوق وخلعه وإعادة السلطان حاجي .","s":"عصى الأميرُ يلبغا الناصريُّ نائِبُ حَلَب على السلطان برقوق، وأمر السلطانُ بخروج العسكر إليه، ولكن الأمير قرابغا فرج الله والأمير بزلار العمري الناصري والأمير دمرداش اليوسفي والأمير كمشبغا الخاصكي الأشرفي وآقبغا قبجق، اجتمع معهم عدَّةٌ كثيرة من المماليك المنفيِّين بطرابلس، وثبوا على نائبها الأمير أسندمر المحمدي وقبضوا عليه، وقتلوا من أمراءِ طرابلس الأميرَ صلاح الدين خليل بن سنجر وابنه، وقبضوا على ج"},{"id":3178,"era":"c8","t":"انتصار العثمانيين في موقعة قوص أوه (إقليم كوسوفو)  .","s":"بعد محاربة الصربِ للعثمانيين سنة 788, وحصولِهم على بعض النجاحِ نتيجةَ انشغال العثمانيين بالحرب مع علاء الدين أمير القرمان، ثم إنَّ أمير البلغار سيسمان تأهَّب للقيام بدوره في محاربة القوات العثمانيةِ، غيرَ أنَّه تفاجأ بها وقد داهمَتْه واحتلَّت بعضَ أجزاء بلاده، ففَرَّ إلى الشمالِ واعتصم في مدينة نيكوبلي القريبة من الحدود الرومانية، وجمع فلولَه مَرَّة أخرى وحارب العثمانيِّينَ إلَّا أنه باء بالهزيمةِ"},{"id":3179,"era":"c8","t":"وفاة مراد الأول بن أورخان وتولي ابنه بايزيد .","s":"هو السُّلطانُ الغازي أبو الفتح غيَّاث الدنيا والدين: مراد الأول بن أورخان بن عثمان القايوي المعروف بغازي خداوندكار، التُركماني، ولِدَ سنة 726 (1326م). لَمَّا توفِّيَ والده الغازي أورخان سنة 761 جلس على سرير السلطنة, ووُلِدَ ابنُه السلطان يلدرم بايزيد خان عقيب جلوسِه على سرير السلطنة, ولما استَقَرَّ على سرير الملك كان الغزاةُ في روم إيلي منتظرينَ قُدومَه إليهم، فسار وجاوز البحر فاحتَلَّ مدينة أنقرة"},{"id":3180,"era":"c8","t":"الفتنة بين الأمير الكبير يلبغا الناصري والأمير تمربغا الأفضلي .","s":"استطاع الأميرُ يلبغا الناصري إزالةَ مُلكِ السلطان برقوق، وكان من أعوانه منطاش الأفضلي ولكن لم يكن ما بينهما صافيًا، فلما كان سادس عشر شعبان أشيعَ في القاهرة بتنكُّر منطاش على الناصري، وانقطع منطاش عن الخدمة، وأظهر أنَّه مريض، ففَطِنَ الناصري بأنه يريد أن يعمل مكيدةً، فلم ينزل لعيادتِه، وبعث إليه الأمير ألطنبغا الجوباني رأس نوبة كبيرًا في يوم الاثنين سادس عشر شعبان ليعودَه في مرضه، فدخل عليه وسَلَّ"},{"id":3181,"era":"c8","t":"خروج الظاهر برقوق من السجن بالكرك .","s":"خرج المَلِكُ الظاهر برقوق مِن سجن الكرك، واستولى على مدينتِها ووافقه نائِبُها الأمير حسام الدين حسن الكجكني، وقام بخِدمتِه، وقد حضر إلى الملك الظاهر برقوق ابنُ خاطر أمير بني عقبة من عرب الكَركِ، ودخل في طاعته، وقَدِمَ هذا الخبر من ابن بأكيش نائب غزة، فلمَّا سمعه منطاش- الذي تغلب على الناصري وأصبح هو نائِبَ السلطنة- أرسل من يقتُلُ الظاهر برقوق في سجنه، واضطربت الديارُ المصرية، وكَثُرَت القالة بين ا"},{"id":3182,"era":"c8","t":"منطاش الأفضلي يهرب من دمشق بعد أن استحوذ عليها  .","s":"بعد أن قام الظَّاهِرُ برقوق بالاستيلاء على مِصرَ وعودَتِه إليها، بقي منطاش في دمشق عاصيًا على السلطان برقوق، وأخَذَ منطاش بعلبكَّ بعد أن حاصرها محمد بن بيدمر أربعةَ أشهر، ثم إنَّ الظاهر برقوقًا جَهَّز العساكِرَ إلى دمشق لأخْذِها من منطاش، فلما بلغ منطاش قدومُ العساكر برز من دمشق، وأقام بقبَّة يلبغا، ثم رحل نصفَ ليلة الأحد ثالث عشر جمادى الآخرة بخواصِّه، وهم نحو الستمائة فارس، ومعه نحو السبعينَ حمل"},{"id":3183,"era":"c8","t":"الحرب بين الظاهر برقوق وعساكر السلطان حاجي المنصور .","s":"بعد أن خرج الظاهِرُ برقوق السلطانُ المخلوعُ مِن سجن الكرك واجتمَعَ له أهلُ الكرك ونصروه، وما زال أمرُه في ظهور حتى العُربان اجتمعت عليه، وأخلاطُ أهل مدينة الكرك، فخرج من الكرك يريد الشَّامَ فأقام بالثنية خارج الكرك يومين، ورحل في الثامِنِ والعشرين من شوال، وسار بهم يريد دمشقَ، وبها الأمير جَنتمُر أخو طاز، متولِّي نيابتها وقد وصل إليه الأمير ألطنبغا الحلبي الدوادار من مصر نائبًا على حلب بحُكم عصيان"},{"id":3184,"era":"c8","t":"هجوم الفرنجة على طرابلس الغرب .","s":"قَدِمَ البريدُ بنُزولِ عِدَّةِ مراكب للإفرنج على طرابلس، فعندما أشرفوا على الميناءِ بَعَث الله عليهم ريحًا أغرَقَت مركبًا، وفَرَّقَت البقية، وكانت نحو السبعين، فرُدُّوا خائبين، قَدِم الخبَرُ من الإسكندرية بأنَّ الفرنج الذين مَزَّقَت الريحُ مراكِبَهم على طرابلس ساروا إلى إفريقيَّة وحاصروا المهدية، وبها وَلَدُ أبي العباس صاحِبُ تونس، فكانت حروبًا شديدةً، انتصر فيها المسلمونَ على الفرنج، وقَتَلوا كثي"},{"id":3185,"era":"c8","t":"عدوان الفرنج على المهدية  .","s":"إن الفِرنجَ قَدِموا إلى المهدية وساعَدَهم هذه السَّنةَ أسطول فرنسيٌّ؛ عونًا لأسطول جنوة، فقام الأميرُ الحفصي أبو فارس عبد العزيز ابن السلطان أبي العباس أحمد المستنصر بصَدِّهم؛ مِمَّا اضطرهم إلى الانسحابِ؛ مما عَزَّزَ مكانة مركز أبي العباس أحمد، وأعيد إلى السلطنة الحفصية كما كانت سالِفَ عَهدِها."},{"id":3186,"era":"c8","t":"السلطان العثماني بايزيد الأول يضم عدة مدن في آسيا الصغرى .","s":"بعد أن تسَلَّمَ بايزيد بن مراد السلطةَ بعد مقتل أبيه، بَقِيَ على ما كان عليه من الجهادِ، فكان ينتَقِلُ من أوروبا إلى الأناضول ثم يعود مُسرعًا إلى أوروبا، يحقِّقُ فيها نصرًا جديدًا أو تنظيمًا حديثًا، حتى لُقِّبَ باسم يلدرم- يعني الصاعقة، وفي هذه السنة انتقل إلى الأناضول فضَمَّ إمارة منتشا، وإمارة آيدين، وإمارة صاروخان دون قتالٍ، وفَرَّ أبناء حكَّامها إلى أمير قسطموني مركز ولاية أسفنديار, كما تنازل "},{"id":3187,"era":"c8","t":"السلطان بايزيد الأول يطهر آسيا الصغرى من الوجود البيزنطي .","s":"فتح بايزيد الأوَّلُ مدينةَ الأشهر بقُربِ أزمير، وهي آخِرُ مدينة كانت قد بَقِيَت للروم في غرب بلادِ الأناضول وهي المعروفةُ بفلادلفيا، وهي آخِرُ مَعقِل بيزنطي بآسيا الصغرى، وبذا يكون قد أمِنَ خلفه؛ إذ كان حُكَّامُ هذه الإمارات يمكِنُ أن يتعاونوا مع أيِّ قُوَّة في سبيل المحافظةِ على إمارتِهم."},{"id":3188,"era":"c8","t":"وفاة السلطان محمد الخامس ملك بني الأحمر في غرناطة وتولي ابنه .","s":"هو السُّلطانُ أبو عبد الله محمد الخامس الغني بالله بن يوسف الأول إسماعيل بن فرج بن إسماعيل بن يوسف بن نصر ملك دولة بني نصر أو بني الأحمر في غرناطة، الذى ساعده ملك البرتغال وسلطان بنى مرين على استرداد مُلكِه، وقام بالأمرِ بعده ابنُه أبو الحجَّاج يوسف الثاني، الذي أبرم معاهدةَ سلم مع ملك قشتالة بعد الحروبِ التي كانت بين أبيه وبين قشتالة. وبعد وفاةِ محمد الخامس تعاقَبَ على حكم غرناطة عددٌ من السلاطين"},{"id":3189,"era":"c8","t":"اجتياح تيمورلنك تركستان وقتاله لتوقتاميش .","s":"زادت الوَحشةُ بين تيمورلنك وتوقتاميش حاكِمِ تُركستان، وكان تيمورلنك قد حاول أن يستثير غضَبَ توقتاميش؛ حيث اجتاح بعضَ أطراف بلاده مثل سيرام على أطراف تركستان، وحصلت مناوشات حربية بين جيوشِ الطرفين خلال ثلاث سنوات، واستولى تيمورلنك على خوارزم ثم انتزعها منه توقتاميش، ثمَّ إن تيمورلنك كان في قوشون من بلاد تركستان، فسمع بعصيان خراسان عليه، فأرسل من يوقِفُ عصيانَهم، ثم عاد في أواخر سنة 792 وتوجَّهَ من "},{"id":3190,"era":"c8","t":"عصيان يلبغا الناصري ومنطاش على السلطان برقوق .","s":"في أوَّلِ شَهرِ رَجَب قَدِمَ منطاش دمشق، وسار إليها من مرعش على العُمق، حتى قارب من حماة، فانهزم منه نائِبُها إلى جهة طرابلس من غيرِ لقاء، ودخلها منطاش، ولم يُحدِثْ حدثًا، وتوجَّه منها إلى حمص، ففَرَّ منه أيضًا نائِبُها إلى دمشق، ومعه نائِبُ بعلبك، فخرج الأميرُ يلبغا الناصري يريد لقاءه من طريق الزبداني، فثار أحمد شكر بجماعة البيدمرية، ودخل دمشقَ من باب كيسان، وأخذ ما في الإسطبلاتِ من الخيول، وخرج "},{"id":3191,"era":"c8","t":"حجاج يقعون في قبضة ملك صقلية في طريقهم إلى الحج .","s":"خرج جَماعةٌ مِن بلاد المغرب يريدون أرضَ مِصرَ لأداء فريضة الحجِّ، وساروا في بحر الملح، فألقَتْهم الريحُ إلى جزيرة صقلية، فأخذهم النصارى وما معهم، وأتَوا بهم إلى مَلِك صقلية، فأوقَفَهم بين يديه وسألهم عن حالِهم، فأخبروه أنَّهم خرجوا يريدون الحَجَّ، فألقَتْهم الريحُ إلى هنا، فقال: أنتم غنيمةٌ قد ساقكم الله إليَّ، وأمَرَ بهم أن يُقَيَّدوا حتى يُباعُوا ويُستَخدَموا في مِهَنِهم! وكان من جُملَتِهم رجلٌ "},{"id":3192,"era":"c8","t":"السلطان العثماني بايزيد يحاصر القسطنطينية ويفتح بلغاريا .","s":"قام السلطانُ بايزيد بن مراد الأوَّل بالاتجاه إلى الغَربِ ومحاصرة القُسطنطينية وضَيَّقَ عليها الحصار، لكنَّه لم يستمِرَّ هو في الحصار، بل تركها محاصَرةً مِن قِبَل بعض الجيش، وتوجه هو إلى الأفلاق، وهي الجزء الجنوبي من رومانيا اليوم، وأجبر حاكِمَها على توقيع معاهدة يعتَرِفُ فيها بسيادة العُثمانيين على بلاده، ويدفع كذلك جِزيةً سَنَوية على أن يُبقِيَه حاكِمًا على بلاده بقوانينِه وأنظِمَتِه الخاصة، ولكن"},{"id":3193,"era":"c8","t":"وفاة الإمام العلامة الزركشي .","s":"هو الإمامُ العلَّامة بدرُ الدين أبو عبد الله محمد بن بهادر بن عبد الله الزركشي المنهاجي، تركي الأصل، ولد بمصر سنة 745, وتعلَّمَ الفِقَه فيها، عُنِيَ بالاشتغال مِن صِغَرِه، فحَفِظَ كُتبًا وأخذ عن الشيخ جمال الدين الإسنوي والشيخ سراج الدين البلقيني ولازمه، حتى أصبح من كبار علماء الشافعيَّة في مصر، وبرع في الأصول، له تصانيفُ عديدة أشهرها: (البرهان في علوم القرآن)، (البحر المحيط في الأصول)، (إعلام الس"},{"id":3194,"era":"c8","t":"احتلال بني مرين تلمسان  .","s":"بعدَ وفاة أبو تاشفين الثاني عبد الرحمن بن أبي حمو موسى سلطان بني زيان، قام بالأمرِ بَعدَه ابنُه أبو ثابت يوسف، ولكِنَّ عَمًّا لأبي تاشفين يدعى أبا الحجَّاج يوسف قام فنزع السُّلطةَ من ابن أخيه، واحتل تلمسان عاصمةَ دولة بني زيان، فكان هذا الاختلافُ أكبَرَ فُرصة لبني مرين الذين لم يتركوا الفرصةَ تَمُرُّ عليهم، بل قاموا باحتلالِ تلمسان وإلحاق الدولة الزيانية بدولتِهم، وقاموا بتولية أبي محمد عبد الله ب"},{"id":3195,"era":"c8","t":"مقتل شاه منصور آل مظفر آخر حكام دولة آل المظفر ببلاد فارس .","s":"هو شاه منصور بن محمد بن مظفر: أخو شاه شجاع آخر حكام دولة آل المظفر، وثب على زين العابدين ابن أخيه فكحَلَه، واستقَلَّ بالحكم, فبلغ ذلك تيمورلنك فجعله سبيلًا إلى قصد بلاد فارس، فسار تيمورلنك ومعه ابنه شاه رخ إلى جهة فارس التي كان يحكمُها منصور شاه، فنازلَها ودافع شاه منصور عن بلاده، وظهرت منه شجاعةٌ عظيمة حتى هزمه تيمورلنك واحتلَّ بلاده وقتَلَه، وبمقتَلِه قضى تيمورلنك على دولةِ آل المظفر في أصفهان، "},{"id":3196,"era":"c8","t":"وفاة الحافظ ابن رجب الحنبلي .","s":"هو الحافظُ زيْنُ الدين أبو الفرج عبدالرحمن بن شِهاب الدِّين أحمد ابن رجَب الحنبلي، ولد ببغداد سنة 736هـ، وسافر إلى دمشق وهو صغير واستقر بها، كان محدثًا بارعًا على طريقة المتقدمين، وفقيهًا حنبليَّا، وواعظًا زاهدًا، له مصنفاتٌ عديدة أشهرُها: شرح الأربعين النَّوويَّة، وشرح سنن الترمذي، والقواعد الفقهية، وطبقات الحنابلة، وشَرَحَ صحيح البخاري وأسماه ((فتح الباري في شرح البخاري)) ولم يُكمِله، وغيرها من "},{"id":3197,"era":"c8","t":"مقتل الأمير منطاش الأشرفي .","s":"هو منطاش الأشرفي نسبةً إلى الأشرف شعبان بن حسين، كان اسمُه تمربغا، ويقال له أخو تمربيه، وكانت لتمربيه منزلةٌ من الأشرف، وتنقل منطاش إلى أنْ ولاه الظاهر برقوق نيابةَ السلطنة بملطية في سنة 788 فجمع كثيرًا من التركمان وأظهر العِصيانَ وانضوى إليه كثيرٌ مِن الأشرفيَّة الذين شَرَّدَهم برقوق لَمَّا تسَلْطَنَ في البلادِ، فلما بلغ الظاهِرَ ذلك جهَّزَ إليه عسكَرَ حلب مع أربعة أمراء من مقَدَّمي الألوف بالقاه"},{"id":3198,"era":"c8","t":"تيمورلنك يحتل بغداد ويستبيح دماء أهلها وأموالهم .","s":"في التاسع عشر من شوال قَدِمَ رسول الملك الظاهر مَجْد الدين عيسى صاحب ماردين بأن تَيْمورلنك أخذ تبريز، وبعث إليه يستدعيه إلى عنده بها، فاعتذر بمشاورة سلطان مصر، فلم يقبل منه، وقال: ليس لصاحب مصر عليك حكم، ولأسلافك دهر بهذا الإقليم، وأرسل إليه خِلعةً وصكة ينقُشُ بها الذهبَ والدنانير، ثم قدم رسول صاحب بسطام بأن تيمور قتل شاه منصور متملك أصفهان، وبعث برأسه إلى بغداد، وبعث بالخلعة والصكة إلى السلطان أح"},{"id":3199,"era":"c8","t":"مقتل أربعة رهبان بالقدس بسبب ذمهم الملة الإسلامية .","s":"خرج أربعةٌ من رهبان النصارى بمدينة القدس، ودَعَوا الفقهاء لِمناظرتهم، فلما اجتمع الناس لهم جهَروا بالسوء من القول، وصرَّحوا بذم الملة الإسلامية، والإزراء على القائم بها، وأنَّه كذابٌ وساحر، وما الحق إلا في دين عيسى! فقُبِض عليهم وقُتِلوا وحُرقوا بالنار، فكان من الأيام المشهورة بالقدس."},{"id":3200,"era":"c8","t":"تيمورلنك يتوعد السلطان برقوق والسلطان يجهز جيشًا للقائه .","s":"قام تيمورلنك بإرسال رسُلٍ مع هدايا إلى السلطان الظاهر برقوق صاحب الديار المصرية، ولكِنَّ السلطان قتَلَهم، فلما بلغ تيمورلنك ما فعله السلطان قام بكتابة رسالة كلها تهديد ووعيد، فأجابه السلطان بما يناسب رسالته من قوة وعدم خوف، وأمر السلطان برقوق بتجهيز العساكر حتى أخذ من خزانة أموال اليتامى؛ لتجهيز العسكر، وخرج من مصر في الرابع عشر من ربيع الآخر، ثم رحل عن غزة في الثاني عشر من جمادى الأولى، وقدم إلى "},{"id":3201,"era":"c8","t":"وفاة الملك أبو العباس أحمد صاحب فاس وتولي ابنه أبي فارس .","s":"صاحب مملكة فاس من بلاد الغرب السلطان أبو العباس أحمد بن أبي سالم بن إبراهيم بن أبي الحسن على بن عثمان بن يعقوب بن عبد الحق المريني ملك الغرب، تولى حكم بلاد المغرب بعد خلع السعيد محمد بن عبد العزيز أبي الحسن في ذي الحجة 774. توفي أبو العباس أحمد في المحرَّم، وأقيم بعده ابنه أبو فارس عبد العزيز، وهو غير متملِّك تونس المتوكل على الله أبو العباس أحمد الحفصي صاحب تونس مع أنَّ اسمهما يكاد يتطابق."},{"id":3202,"era":"c8","t":"وفاة السلطان أبي العباس أحمد سلطان الحفصيين وتولي ابنه .","s":"هو السلطانُ أبو العباس أحمد بن محمد بن أبي بكر بن يحيى بن إبراهيم بن يحيى عبد الواحد بن أبي  حفص عمر بن ونودين الهنتاتي المغربي أبو العباس، ويلقَّبُ أبا السباع سلطان الحفصيين. ولي تونسَ وما معها من بلاد المغرب في سنة 772، وكان شهمًا شجاعًا ولي كلَّ من ذُكِر في عمود نسبه المملكة إلا أباه وجدَّ أبيه, وكانت وفاتُه في شعبان، توفي في ليلة الخميس رابع شعبان بمحل ملكه مدينة تونس من بلاد المغرب بعد أن حكم"},{"id":3203,"era":"c8","t":"استعادة حكم بغداد بعد طرد نائب تيمورلنك منها  .","s":"لَمَّا تيقَّن السلطان برقوق من عودة تيمورلنك إلى بلاده وجَّه في يوم الاثنين أول شعبان القان غياث الدين أحمد بن أويس من دمشق إلى بغداد، بعد أن قدم له جميع ما يحتاج إليه، وعند وداعه خلع عليه أطلسين بشاش متمر، وسيف بسقط ذهب، وأعطى تقليدًا بنيابة السلطنة ببغداد، ولما وصل إلى ظاهر بغداد خرج إليه نائب تيمور بها، وقاتله فانكسر النائب، ودخل بغداد، وأطلق المياه على عسكر ابن أويس ليُغرقه، فأعانه الله وتخلَّ"},{"id":3204,"era":"c8","t":"وفاة أبي الحجاج يوسف الثاني ملك بني نصر  وقيام ابنه محمد السابع .","s":"هو أبو الحجَّاج يوسف الثاني بن محمد الخامس الغني بالله بن يوسف بن إسماعيل بن فرج بن إسماعيل بن يوسف ملك بني نصر ابن الأحمر المنحَدِر من قبيلة الخزرج القحطانية, فقام بالأمر بعده ابنُه محمد السابع متجاوزًا أخاه الأكبر يوسف؛ حيث قبَض عليه وسَجَنه."},{"id":3205,"era":"c8","t":"طقتمش المغولي يحارب قوات تيمورلنك في بلاد فارس .","s":"قام طقتمش زعيم القبيل الأبيض والأزرق المغولي الذي كان انتصر على الروس فاغتَرَّ بقوته فأراد أن يحارب تيمورلنك فأغار على فارس التي مع تيمورلنك حتى حاصر بخارى، وهذا الذي اضطر تيمورلنك لملاقاته في معركة جرت في جمادى الآخرة وانتهت بهزيمة طقتمش."},{"id":3206,"era":"c8","t":"مقتل الشريف علي بن عجلان أمير مكة في معركة مع بني حسن .","s":"هو الشريف أبو الحسن علي بن عجلان بن رميثة، واسمُ رُميثة منجد بن أبي نمي بن أبي سعد حسن بن علي بن قتادة بن إدريس بن مطاعن بن عبد الكريم بن عيسى بن عيسى بن حسين بن سليمان بن علي بن عبد الله بن محمد بن موسى بن عبد الله المحض بن موسى بن الحسن السبط بن الحسن بن علي بن أبي طالب المكي الحسني، أمير مكة المشرفة، وَلِيَها ثماني سنين ونحو ثلاثة أشهر مستقلًّا بالإمارة، غير سنتين أو نحوهما؛ فإنه كان فيهما شريك"},{"id":3207,"era":"c8","t":"تيمورلنك يهزم الأمير طولو بن علي شاه ويحتل بلاد القرم .","s":"قدم الأمير طولو بن علي شاه المتوجِّه إلى طَقتمش خان، وأنه بعد ما اتفق معه على محاربة تيمورلنك توجَّه تيمورلنك لمحاربته، فسار إليه وقاتله ثلاثةَ أيام، فانكسر من تيمور، ومَرَّ إلى بلاد الروس؛ فخرج طولو من سراي إلى القرم، ومضى إلى الكفا، فعوَّقه متمَلِّكُها ليتقرَّبَ به إلى تيمور، حتى أخذ منه خمسين ألف درهم، فملك تيمور القرم والكفا وخرَّبَها."},{"id":3208,"era":"c8","t":"وفاة السلطان أبي فارس عبدالعزيز المريني صاحب فاس وتولي أخيه .","s":"هو السلطانُ أبو فارس عبد العزيز بن السلطان أبي العباس أحمد بن أبي سالم بن إبراهيم بن أبي الحسن المريني ملك الغرب وصاحب فاس، أبو فارس، أقيم بعده على سلطنة فاس أخوه أبو عامر عبد الله. وهو يختلف عن السلطان أبي فارس عبد العزيز بن أبي العباس أحمد الحفصي ملك بلاد المغرب الذي توفي سنة 837."},{"id":3209,"era":"c8","t":"أخبار تيمورلنك وقتاله مع صاحب ماردين  .","s":"حضر الأمير علاء الدين ألطبغا نائب الملك الظاهر مجد الدين عيسى صاحب ماردين، فأنعم عليه وعلى من معه، وكان سببُ قدومه أنَّ الظاهِرَ عيسى لما قبض عليه تيمورلنك وأقام في أسْرِه، قام ألطبغا بأمر ماردين ومنع تيمورلنك منها، وكان الظاهر قد أقام في مملكة ماردين الملك الصاع شهاب الدين أحمد بن إسكندر بن الملك الصالح صالح، وهو ابنُ أخيه وزوجُ ابنته، فقاتل أصحاب تيمورلنك قتالًا شديدًا، وقتل منهم جماعة، فشقَّ هذ"},{"id":3210,"era":"c8","t":"دخول تيمورلنك أزرنكان .","s":"دخلت عساكر تيمورلنك إلى أزرنكان من بلاد الروم، وقُتِلَ كثير من التركمان، فتوجَّه الأمير تمربغا المنجكي على البريد؛ لتجهيز عساكر الشام إلى أرزنكان."},{"id":3211,"era":"c8","t":"اشتداد الغلاء بدمشق .","s":"اشتدَّ الغلاء بدمشق، فخرج الناسُ يستسقون، وثاروا برجلٍ يُعرَف بابن النشو، كان يحتكِرُ الغِلالَ، وقتلوه شرَّ قِتلةٍ، وأحرقوه بالنار."},{"id":3212,"era":"c8","t":"وفاة أبي عامر المريني ملك المغرب وتولي أخيه أبي سعيد .","s":"هو أبو عامر عبد الله بن السلطان أبي العباس أحمد بن أبي سالم إبراهيم بن أبي الحسن المريني ملك المغرب صاحب فاس، وأقيم بعده أخوه أبو سعيد عثمان بن أبي العباس، والشيخ أبو العباس أحمد بن علي القبايلي هو القائم بتدبير الدولة على عادته منذ موت السلطان أبي العباس أحمد في أيام أبي فارس عبد العزيز، وأبي عامر عبد الله."},{"id":3213,"era":"c8","t":"تيمورلنك يتجه إلى الهند ويستولي على دلهي وكشمير .","s":"بلغ تيمورلنك موتُ محمد بن فيروز شاه تغلق ملك الهند وقيام صراع عنيف بين أمراء الولايات الهندية في عهد ابنه إسكندر، وأنَّ الحُكمَ استقَرَّ أخيرًا لابنه الآخر محمود، فتوجَّه تيمورلنك إلى الهند بجيش كبير مزوَّد بآلات الحرب الهائلة، فحاول السلطان محمود أن يقاتلَه، ولكنَّه انهزم فاحتَلَّ تيمورلنك دلهي وهرب السلطان محمود إلى كجرات، وأمعن تيمورلنك في القتل والنهب والتخريب، واستولى كذلك على كشمير، ثم عاد إ"},{"id":3214,"era":"c8","t":"وقوع وباء بالوجه البحري وفشو الأمراض بالقاهرة ومصر .","s":"وقع وباءٌ بالوجه البحري، وفَشَت الأمراض بالقاهرة ومصر. وكان قد خرج جماعةٌ من الأمراء إلى الصعيد، فمَرِضَ أكثرهم، وعاد الأمير قَلْمطاي الدوادار يوم الثلاثاء رابع ربيع الآخر، وهو مريض لا يثبُتُ على الفَرسِ."},{"id":3215,"era":"c8","t":"العثمانيون ينتصرون على ملوك أوروبا في موقعة نيقوبوليس .","s":"لما أحرز العثمانيون الانتصاراتِ العديدةَ في المُدَد القصيرة، خاف ملوك أوروبا وخاصة ملك المجر الذي استغاث بالبابا والملوك، فأعلنها البابا حربًا صليبية دعا إليها الملوكَ؛ فاستجاب دوق بورغونيا شرق فرنسا، وأمراء النمسا وبافاريا قرب ألمانيا، وفرسان القديس يوحنا الذين كانوا يومها بمالطة، فسار الجميع يقودُهم ملك المجر \"سيجموند الأول\"، وبلغ قوامهم 120 ألف جندي مجتازين نهر الدانوب، وحاصروا مدينة نيكوبلي شم"},{"id":3216,"era":"c8","t":"محاولة اغتيال السلطان الظاهر برقوق .","s":"ركِبَ السلطان الظاهر برقوق بعد صلاة الظهر يريد المقياسَ من شهر ذي القعدة، وفتح الخليج على العادة، ومعه الأمراء إلا الأمير ألي باي الخازندار؛ فإنه كان قد انقطع في داره أيامًا لمرض نزل به فيما أظهره، وفي باطن أمره أنَّه قصد الفتك بالسلطان؛ فإنه علم أنَّه إذا نزل الخليج يدخل إليه ويعودُه على ما جرت به عادتُه مع الأمراء، فدبَّر اغتَيال السلطان، وأخلى إسطبله وداره من حريمه وأمواله، وأعدَّ قومًا اختارهم"},{"id":3217,"era":"c9","t":"اغتيال السلطان أبي سعيد ملك المرينيين وتولية ابنه الناصر .","s":"هو السلطان أبو سعيد بن عثمان بن أبي العباس أحمد بن أبي سالم إبراهيم بن أبي الحسن المريني ملك المرينيين، لما اغتِيلَ نُصب ولده الناصر عبد الحق خلفًا له وتولى الوصايةَ عليه أبو زكريا يحيى الوطاسي زعيم بني وطاس، والذي به قامت دولة بني وطاس التي خلفت دولة بني مرين فيما بعد."},{"id":3218,"era":"c9","t":"وفاة السلطان الظاهر برقوق وتولي ابنه الناصر فرج  .","s":"هو الملك الظاهر برقوق أبو سعيد أولُ من ملك مصر من الجراكسة، وَلِيَ سلطانها سنة 784 وبنى المدرسة البرقوقية بمصر بين القصرين. ثم خُلِع، ثم أعيد إلى أن مات سنة 801؛ ففي يوم الثلاثاء خامس شهر شوال ابتدأ مرض السلطان الظاهر برقوق، وذلك أنه ركب للعب الكرة بالميدان في القلعة على العادة، فلما فَرَغ منه قدم إليه عسل نحل ورد من كختا، فأكل منه ومن لحم بلشون، ودخل إلى قصوره، فعكف على شرب الخمر، فاستحال ذلك خلط"},{"id":3219,"era":"c9","t":"استيلاء مراد الأول بن أورخان على الأبلستين .","s":"أخذ السلطان مراد الأول بن أورخان بن عثمان الأبلستين، وعزم أن يمشيَ إلى البلاد الشامية، فطلب الأمراء والقضاة وأرباب الدولة إلى القصر السلطاني، وقُرِئَت عليهم كتبٌ تتضمَّنُ أنَّ ابن عثمان ملك الروم بعث أخاه عليًّا بالعساكر، وأنه أخذ ملطية والأبلستين -مدينة مشهورة ببلاد الروم- وفَرَّ منه صدقة بن سولي، فتسلَّمها في الثامن والعشرين من ذي القعدة، وأنَّه محاصر درندة، فوقع الاتفاقُ على المسير إلى قتاله، و"},{"id":3220,"era":"c9","t":"تيمورلنك يستولي على أذربيجان ويحتل شرق الأناضول .","s":"اتجه تيمورلنك ناحية الغرب في هذا العام فاستولى على أذربيجان، ففَرَّ منها صاحِبُها قره يوسف، ووصل تيمورلنك إلى القوقاز وأدَّب بلاد الكرج الذين ثاروا على عاملِه عليهم، ثم اتَّجه نحو السلطان العثماني بايزيد الأول عن طريق أرضروم ودخل سيواس، وقبض فيها على الأمير أرطغرل سليمان بن السلطان بايزيد، فقَتَله، وفَرَّ حاكِمُها، وكان قد وقف في وجهه أربعة آلاف أرضرومي فجمعهم في خندق واحد وردم التراب فوقهم، وسار "},{"id":3221,"era":"c9","t":"الفتنة بين الأمير أيتمش نائب السلطنة والأمير يشبك الشعباني .","s":"تزايد الاختلافُ بين أمراء المماليك والخاصكية، وكثُر نفور الخاصكية من الأمير أيتمش الذي كان يتولَّى نيابة السلطنة بوصية السلطان برقوق، وخاصة أن السلطان فرجًا ما زال قاصرًا، وظنوا به وبالأمراء أنَّهم قد مالوا إلى نائب الشام الأمير تنم الحسني الذي بدأ يعصي عن الطاعة، واتفقوا معه على إفناء المماليك بالقتل والنفي، فحَذِرَ الأمراء منهم، واشتدت الوحشةُ بين الطائفتين، وتعيَّن من الخاصكية سودون طاز، وسودون"},{"id":3222,"era":"c9","t":"حدوث فتنة في الكرك .","s":"لما قَدِمَ المهتار عبدالرحمن الكرك أظهر كتبًا إلى الأمير سودون الظريف نائب الكرك باستعدادِه لحرب الأمير أيتمش، فاختلف أهلُ الكرك وافترقوا فرقتين: قيسية، ويمانية؛ فرأسَ قيسًا قاضي الكرك شرف الدين موسى ابن قاضي القضاة عماد الدين أحمد الكركي. ورأَسَ اليمن الحاجبُ شعبان بن أبي العباس. ووقعت فتنةٌ نُهِب فيها رحل المهتار عبد الرحمن والخِلعة التي أحضرها إلى النائب، وامتدَّت إلى الغور فنُهب، ورحل أهله وفَ"},{"id":3223,"era":"c9","t":"سيل عظيم بمكة يدخل إلى الكعبة .","s":"في ليلة الخميس عاشر جمادى الأولى كان بمكة -شرَّفها الله- سيل عظيم بعد مطر غزير، امتلأ منه المسجد الحرام حتى دخل الكعبة، وعلا على بابها نحوَ ذراع، وهدم عمودين من عُمُد المسجد، وسقطت عدةُ دور، ومات تحت الهدم وفي السيل نحو الستين إنسانًا."},{"id":3224,"era":"c9","t":"خروج الأمير تنم الحسني نائب الشام عن الطاعة ثم قتله .","s":"كان الأمير تنم الحسني قد تغلَّب على دمشق أيام موت السلطان الظاهر برقوق، ثم إن السلطان الناصر فرج بن برقوق أقرَّه وأعطاه نيابة دمشق، وأجيز بإخراج من أراد من السجون، فأخرج عدة أمراء من السجون، وزاد أمره فأراد تملُّك أكثر من دمشق، كحلب وحمص وطرابلس وغيرها، ثم إن أيتمش لما هرب في الفتنة التي حصلت بينه وبين يشبك -في شهر صفر من هذه السنة- جاء إلى دمشق الأمير تنم هو ومن معه من الأمراء في خامس ربيع الآخر،"},{"id":3225,"era":"c9","t":"حريق هائل في المسجد الحرام يحرق ثلثه .","s":"في ليلة الثامن والعشرين شوال ظهرت نارٌ بالمسجد الحرام من رباط، ومشت بالجانب الغربي من المسجد، فعَمَّت النار، واحترقت جميع سُقُف هذا الجانب، وبعض الرواقين المقدَّمين من الجانب الشامي، وعمَّ الحريق فيه إلى محاذاة باب دار العجلة لخُلُوِّه بالهدم وقت السيل، وصار موضع الحريق أكوامًا عظيمة، وتكسَّر جميعُ ما كان في موضع الحريق من الأساطين وصارت قِطَعًا، وقُدِّر الذي احترق من المسجِدِ، فكان قَدْرَ الثُّلُ"},{"id":3226,"era":"c9","t":"أحمد بن أويس ملك بغداد يهرب منها ويقاتله أهلها ويلجأ للسلطان .","s":"في ثاني ذي القعدة ورد البريدُ من حلب ودمشق بأن ألقان أحمد بن أويس صاحب بغداد، لما توجه إلى بغداد واستولى عليها، كان لقرا يوسف في مساعدته أثر كبير؛ فعندما تمكَّن قَبَض على كثير من أمراء دولته وقتَلَهم، وأكثَرَ من مصادرات أهل بغداد وأخذ أموالهم، فثار عليه من بقي من الأمراء، وأخرجوه منها، وكاتبوا صاحب شيراز أن يحضرَ إليهم، فلحق ابن أويس بقرا يوسف بن قرا محمد التركماني صاحب الموصل، واستنجد به، فسار مع"},{"id":3227,"era":"c9","t":"تيمورلنك يذبح سكان مدينتي حلب عينتاب وبهنسا .","s":"بعد أن انتهى تيمورلنك من سيواس توجه إلى جهة حلب فوصل إلى عينتاب، ووصل إلى بهنسا وأخذها بعد أن حصرها، ثم نزل على بزاعة ظاهر حلب، فبرز نائب طرابلس بسبعمائة فارس إلى جيش تيمورلنك وهم نحو ثلاثة آلاف، وترامى الجمعان بالنشاب، ثم اقتتلوا، وأُخِذ من التتار أربعة، وعاد كل من الفريقين إلى موضعه فوسط الأربعة على أبواب مدينة حلب، وأما دمشق فإن أهلها بدؤوا يتجهزون والقضاة تحرِّضُ الناس على الجهاد ضدَّ تيمورلنك"},{"id":3228,"era":"c9","t":"وفاة الملك الأشرف إسماعيل صاحب اليمن وتولي ابنه الناصر .","s":"هو المَلِكُ الأشرَفُ إسماعيلُ بنُ الأفضلِ عباسِ بن المجاهد علي بن المؤيد داود بن المظفر يوسف بن منصور عمر بن علي بن رسول، وَلِيَ سَلطنة اليمن بعد أبيه في سنة 778، حتى مات، وكان حليمًا، كثير السَّخاء، مُقبلًا على العلم، محبًّا للغرباء، وصنَّف تاريخًا لليمن، توفِّيَ في ليلة السبت ثامن عشر ربيع الأول، بمدينة تَعْز من بلاد اليمن، عن سبع وثلاثين سنة، وقام بمملكة اليمن بعده ابنُه الملك الناصر أحمد."},{"id":3229,"era":"c9","t":"جيش تيمورلنك يدخل حماة ويقتل أهلها ويخربها .","s":"نزل مرزه شاه بن تيمورلنك على مدينة حماة بكرة يوم الثلاثاء رابع عشر ربيع الأول، وأحاط بسورها، ونهب المدينة، وسبى النساء والأطفال، وأسر الرجال، ووقع أصحابه على النساء يطؤونهن ويفتضُّون الأبكارَ جهارًا من غير استتار وخرَّبوا جميعَ ما خرج عن السور، وقد ركب أهل البلد السور، وامتنعوا بالمدينة، وباتوا على ذلك، فلما أصبحوا يوم الأربعاء فتحوا بابًا واحدًا من أبواب المدينة، ودخل ابنُ تيمورلنك في قليلٍ من أص"},{"id":3230,"era":"c9","t":"تيمورلنك يدمر مدينة دمشق ويذبح أهلها .","s":"لما قدم خبر أخْذ حلب وما ارتكبه المغول في أهلها نودِيَ بدمشق في الناس بالتحوُّل إلى المدينة والاستعداد للعدوِّ، فاختبط الناس وعظُم ضجيجهم وبكاؤهم، وأخذوا ينتقلون في يوم الأربعاء نصفه من حوالي المدينة إلى داخلها، واجتمع الأعيانُ للنظر في حفظ المدينة، فقدم في سابع عشر ربيع الأول المنهزمون من حماة، فعظُمَ الخوف، وهمَّ الناس بالجلاء، فمُنِعوا منه، ونودِيَ: من سافر نُهب، فورد في الثامن العشر منه الخبر "},{"id":3231,"era":"c9","t":"تيمورلنك يدخل بغداد ويقتل أهلها ويخربها .","s":"كان رحيل تيمورلنك عن دمشق في يوم السبت ثالث شعبان من هذه السنة واجتاز على حلب وفعل بها ما قدر عليه ثانيًا، ثم سار منها حتى نزل على ماردين يوم الاثنين عاشر شهر رمضان من السنة، ووقع له بها أمور، ثم رحل عنها، وأوهم أنه يريد سمرقند، يورِّي بذلك عن بغداد، وكان السلطان أحمد بن أويس قد استناب ببغداد أميرًا يقال له فرج، وتوجَّه هو وقرا يوسف نحو بلاد الروم، فندب تيمور على حين غفلة أمير زاده رستم ومعه عشرون"},{"id":3232,"era":"c9","t":"الصلح بين تيمورلنك والسلطان فرج بن برقوق .","s":"بعد أن تمَّ للمغول بقيادة تيمورلنك تدميرُ مدن الشام، أرسل تهديداتِه للسلطان فرج بن برقوق سلطان المماليك في مصر، وكان قد أسر أميرًا من المغول يدعى (أطلمس) فطالب تيمورلنك بإطلاق سراحه فورًا، وإلا فسيزحف المغول على مصر ويرفعون راياتهم على ربوعها. وقد أذعن السلطان فرج لهذه التهديدات، وأطلق سراح أطلمس وعقد صلحًا مع تيمورلنك يتعهد فيه السلطان فرج بطاعة تيمورلنك والدعوة باسمه في مساجد مصر، وقد أدى هذا ال"},{"id":3233,"era":"c9","t":"نائب الشام تغري بردي يعصي على السلطان وينضم له نائب حلب .","s":"كان قد رُسِم لتغري بردي بنيابة دمشق، ثم في محرم سنة 804 كتب الأمراء بمصر لأمراء دمشق بالقبض على الأمير تغري بردي، فكَتَب له بذلك بعضُ أعيان أمراء مصر، فسبق كتابُه كتابَ الأمراء، فركب من دار السعادة بدمشق في نفرٍ من مماليكه في ليلة الجمعة ثاني عشرين المحرم وخرج إلى حلب، فتعيَّن لنيابة دمشق عوضًا عنه الأمير آقبغا الجمالي الأطروش أتابك دمشق، وكتب بانتقال دقماق نائب صفد إلى نيابة حلب عوضًا عن دمرداش ا"},{"id":3234,"era":"c9","t":"مراكب للفرنج تهاجم شاطئ طرابلس .","s":"قَدِمَ إلى طرابلس يوم الاثنين العاشر من صفر مركب فيه عدةٌ من الفرنج، فخرج الناسُ لحربهم، وكان بالميناء مراكِبُ لتجَّار الفرنج، فاجتمعوا على مراكب المسلمين التي قد شُحِنَت بالبضائع لتسيرَ إلى أرض، وأخذوا منها مركبين فيهما مال كبير، وأسروا خمسة وثمانين مسلمًا بعدما قاتلوا قتالًا شديدًا وغرق جماعةٌ وفرَّ جماعة، وأصبحوا من الغدِ على الحرب، فوقع الاتفاقُ على فكاك من أسروه بمالٍ يُحمَلُ إليهم، فلما حُمِ"},{"id":3235,"era":"c9","t":"وفاة سراج الدين ابن الملقن .","s":"هو سراج الدين أبو حفص عمر بن علي بن أحمد الأنصاري المشهور بابن الملقِّن، ولد بالقاهرة سنة 723 عُرِفَ ابن الملقن؛ لأن الذي كفَلَه بعد وفاة أبيه مُلَقِّن القرآن في الجامع الطولوني بالقاهرة، فعُرِفَ به، فصار يقال: ابنُ المُلَقِّن، وكان هو زوجَ أمِّه، وهو الذي ربَّاه، فأصبح من كبار علماء الحديث والفقه الشافعي، فتولى قضاء الشافعية، ثم التدريس والإفتاء، له مصنفات عديدة؛ منها: إكمال تهذيب الكمال، وله الب"},{"id":3236,"era":"c9","t":"الفتنة بين الأمراء في مصر وقتالهم بين بعضهم .","s":"كثُرَ تنافرُ الأمراء واختلافهم، وانقطع نوروز، وجكم الجركسي الظاهري، وقنباي، عن الخدمة، ودخل شهر رمضان وانقضى، فلم يحضروا للهناء بالعيد، ولا صلَّوا صلاة العيد مع السلطان، فلما كان يوم الجمعة ثاني شوال ركبوا للحرب، فنزل السلطان من القصر إلى الإسطبل عند سودن طاز، وركب نوروز وجكم وقنباي، وقرقماس الرماح، ووقعت الحربُ من بكرة النهار إلى العصر، ورأس الأمراءَ نوروز وجكم، وخصمهم سودن طاز، فلما كان آخر النه"},{"id":3237,"era":"c9","t":"معركة أنقرة  وأسر تيمورلنك السلطان بايزيد الأول  .","s":"بعد أن رحل تيمورلنك من بغداد كتب إلى بايزيد الأول صاحب الروم أن يخرجَ السلطان أحمد بن أويس وقرا يوسف من ممالك الروم وإلا قصده وأنزل به ما نزل بغيره، فردَّ بايزيد جوابه بلفظ خَشِنٍ إلى الغاية، فسار تيمور إلى نحوه، فجمع بايزيد الأولُ عساكرَه من المسلمين والنصارى وطوائف التتر، فلما تكامل جيشُه سار لحربه، فأرسل تيمور قبل وصوله إلى التتار الذين مع بايزيد الأول يقول لهم: نحن جنسٌ واحد، وهؤلاء تركمان ندف"},{"id":3238,"era":"c9","t":"طاهر بن أحمد يثور على أبيه سلطان بغداد .","s":"ثار على السلطان أحمد بن أويس ولدُه طاهر وحارَبَه، ففرَّ من الحلة إلى بغداد فأَخَذَ وديعة له كانت بها، فهجم عليه طاهر وأخذ منه المال، ففرَّ أحمد من ابنه، وأتاه قرا يوسف بطلبه له وأعانه على ابنه، وحاربه معه، ففرَّ طاهر فاقتحم بفرسه دجلة فغرق بها، ولحِقَ بربِّه."},{"id":3239,"era":"c9","t":"وفاة السلطان العثماني بايزيد الأول .","s":"هو السلطان بايزيد الأول بن مراد الأول بن أورخان غازي بن الغازي عثمان بن أرطغرل الملقب بيلدرم -أي الصاعقة- نظرًا لحركته السريعة بجيوشه وتنقُّلِه بين عدة جهات بمنتهى السرعة. كانت ولادته سنة 761 (1360م) وكان هو الابن البكر لمراد الأول، فاتفق أركان الدولة على توليته بعد مقتل والده مراد الأول سنة 791 على يد أحد جرحى الصرب في أعقاب معركة قوصوة. قَتَل أخاه يعقوب الأصغر منه بقليل والمتصف بالشجاعة والإقدام"},{"id":3240,"era":"c9","t":"وفاة شيخ الإسلام العلامة سراج الدين البلقيني الشافعي .","s":"هو الإمام العلامة شيخ الإسلام مجتهد العصر نادرة الوقت فقيه الدنيا وخاتمة المجتهدين: سراج الدين أبو حفص عمر بن رسلان بن نصير بن صالح -وصالح أول من سكن بلقينة- بن شهاب بن عبد الخالق بن عبد الحق بن مسافر بن محمد الكناني البلقيني الشافعي، وُلِد في ليلة الجمعة ثاني عشر شعبان 724 ببلقينة، وهي قرية في المحلة الكبرى بطنطا. حفظ القرآن وهو في السابعة من عمره. حفظ المحرر في الفقه، والكافية لابن مالك في النحو"},{"id":3241,"era":"c9","t":"وفاة الشيخ عبد الجبّار بن عبد الله المعتزلي الحنفي إمام تيمورلنك .","s":"هو الشيخ عبد الجبَّار بن عبد الله المعتزلي الحنفي الخوارزمي عالم الدشت، صاحب تيمورلنك وإمامه وعالمه وترجمانه. ولد في حدود سنة 770، وكان إمامًا عالِمًا بارعًا، متقِنًا للفقه، والأصلين، والمعاني، والبيان، والعربية، واللغة، انتهت إليه الرئاسة في أصحاب تيمور، وكان هو عظيم دولته، ولما قدم تيمور البلاد الحلبية والشامية كان عبد الجبَّار هذا معه، وباحَثَ وناظر علماء البلدين، وكان فصيحًا باللغات الثلاث: ال"},{"id":3242,"era":"c9","t":"بداية الاختلاف بين أبناء السلطان العثماني بايزيد الأول .","s":"بعد أن توفي السلطان بايزيد الأول في الأَسْر, وكان أولاده الذين هربوا من المعركة كل منهم ولى إلى جهة، فلما سار تيمورلنك عن الأناضول عادت مجزَّأة كما كانت قبل أن يوحِّدها العثمانيون وأعلنت الإمارات الأوربية استقلالها لما رأت ما حلَّ بالعثمانيين من قِبَل تيمورلنك، فأعلن البلغار والصرب والأفلاق استقلالهم، واختلف أولاد السلطان بايزيد فزاد الضعف؛ فاستقل سليمان بن بايزيد في أدرنة والمناطق العثمانية في أو"},{"id":3243,"era":"c9","t":"الفرنج يغزون طرابلس .","s":"في هذا الشهر كانت واقعة الفرنج بطرابلس، وذلك أنهم نزلوا على طرابلس في ثلاثين شينيًا -سفينة كبيرة- وقراقر، وكان الأمير دمرداش غائبًا عن البلد، فقاتلهم الناس قتالًا شديدًا في يوم الثلاثاء ثاني عشره إلى الغد، فبلغ دمرداش وهو بنواحي بعلبك الخبر، فاستنجد الأمير شيخ المحمودي نائب الشام، وتوجه إلى طرابلس، فقَدِمَها يوم الخميس عشرينه، ونودي في دمشق بالنفير، فخرج الناس على الصعب والذلول، فمضى الفرنج إلى بي"},{"id":3244,"era":"c9","t":"وفاة الإمام العلامة الحافظ زين الدين العراقي الشافعي .","s":"هو الشيخ الإمام العلامة الأوحد شيخ العصر حافظ الوقت شيخ المحدِّثين علم الناقدين عمدة المخرجين: أبو الفضل زين الدين عبد الرحيم بن الحسين بن عبد الرحمن بن أبي بكر العراقي المصري الشافعي، شيخ الحديث بالديار المصرية، وُلِدَ بمصر سنة 725, وسمع الكثير ورحل في البلاد، حدَّث وأملى سنين كثيرة وأفاد وتكلم على العلل والإسناد ومعاني المتون وفقهها، فأجاد وصنف التصانيف التي اشتهرت، وخرج تخاريج رُوِيت وانتشرت. ك"},{"id":3245,"era":"c9","t":"الفتنة بين الأمراء بمصر والقتال بينهم .","s":"أهلَّ شهر جمادى الأولى والفتنة قائمة بين أمراء الدولة؛ وذلك أن الأمير يشبك هو زعيم الدولة، بيده جميع أمورها من الولاية والعزل، والنقض والإبرام، وصار له عصبة كبيرة، فأحبوا عزل الأمير إينال باي ابن الأمير قجماس ابن عم الملك الظاهر برقوق من وظيفة أمير أخور؛ وذلك أنه اختص بالسلطان لأمور؛ منها: قرابته، ثم مصاهرته إياه، فشَقَّ ذلك على عصبة يشبك، وأحبوا أن يكون جركس المصارع أمير أخور، وانقطعوا عن حضور ال"},{"id":3246,"era":"c9","t":"واقعة السعيدية وفتنة الأمير جكم ومحاولة استيلائه على البلاد .","s":"استولى الأمير جكم الجركسي الظاهري على حلب، وقد كان سابقًا خرج عن الطاعة وتمالأ مع التركمان والعربان وأحدث عدة فتن، وأنعم على الأمير علان نائب حماة بموجود دمرداش النائب السابق لحلب، وأحسن جكم السيرة في حلب، وولَّى في القلاع نوابًا من جهته، فاجتمعت له حلب وحماة وطرابلس، وأما الأمير شيخ المحمودي نائب الشام فإنه خرج لأخذ صفد وعمل ثلاثين مدفعًا، وعدة مكاحل للنفط ومنجنيقين، وجمع الحجَّارين والنقَّابين و"},{"id":3247,"era":"c9","t":"وفاة الطاغية تيمورلنك وزوال خطر المغول .","s":"هو الطاغية تيمورلنك كوركان بن أيتمش قنلغ بن زنكي بن سنيا بن طارم بن طغريل بن قليج بن سنقور بن كنجك بن طغر سبوقا بن التاخان، المغولي الأصل، من طائفة جغتاي، واسمه تمرلنك وقيل تيمور، كلاهما بمعنى واحد، والثاني أفصح، وهو باللغة التركية: الحديد. ومعنى لنك: الأعرج، ومعنى كوركان: صهر الملك، وهو ينتمي إلى قبيلة البرلاس التركية، وقد كان أحد أجداده وهو قراجا رنويان قد دعم جنكيز خان فأحبَّه وجعله وصيًّا على "},{"id":3248,"era":"c9","t":"فتنة بين أمراء الشراكسة وأمراء الروم واختفاء السلطان ابن برقوق .","s":"في يوم الثلاثاء سادس ربيع الأول تخبطت الأحوال بين السلطان وبين المماليك؛ فوقف طائفة من المماليك الجراكسة، وسألوا أن يقبض على الأمير تغري بردي، والأمير دمرداش، والأمير أرغون؛ من أجل أنهم من جنس الروم؛ وذلك أن السلطان اختص بهم، وتزوج ابنة تغري بردي، وأعرض عن الجراكسة، وقبض على إينال باي، فخاف الجراكسة من تقدُّم الروم عليهم، وأرادوا من السلطان إبعادهم، فأبى عليهم، فتحزبوا عليه واجتمعوا على الأمير الك"},{"id":3249,"era":"c9","t":"وقعة بين المسلمين والفرنج بالأندلس .","s":"لما انقضت مدة الصلح بين المسلمين بغرناطة وبين الطاغية صاحب قشتالة، أبى الطاغية الصلح، فبعث السلطان أبو سعيد عثمان صاحب ماس عشرين غرابًا أوسقها بالعدد والزاد، وجهز ثلاثة آلاف فارس، قدم عليهم القائد مارح، وجعل الشيخ عمر بن زيان الوساطي على ألف فارس أخرى، فنزلوا سبتة، وجهز أبو عبد الله محمد بن أبي الحجاج يوسف -صاحب غرناطة- أسطوله إلى جبل الفتح، فلقيهم أسطول الطاغية بالزقاق في يوم الجمعة السادس عشر، و"},{"id":3250,"era":"c9","t":"خلع السلطان الناصر فرج بن برقوق وتولية أخيه المنصور .","s":"لما فُقِدَ الملك الناصر وقتَ الظهر من يوم الأحد خامس عشرين ربيع الأول بادر الأمراء بالركوب إلى القلعة، وهم طائفتان: الطائفة التي خالفت الناصر وحاربته، ويرجع أمرُهم إلى الأمير يشبك الدوادار، والطائفة الأخرى هي التي وَفَت للناصر، وكبيرهم الأمير الكبير بيبرس ابن أخت الظاهر، وحاربت يشبك الدوادار ومن معه، فلما صار الفريقان إلى القلعة، منعهم الأمير سودون تلى المحمدي أمير أخور من صعود القلعة، وهم يضرعون "},{"id":3251,"era":"c9","t":"خلع السلطان المنصور عبدالعزيز بن برقوق وعودة أخيه الناصر فرج .","s":"في شهر جمادى الآخرة، أوله الثلاثاء، وفيه مرض السلطان الملك المنصور، وفي يوم الجمعة رابعه: عادت الخيول من الربيع، وظهر بين أهل الدولة حركة، فكَثُرت القالة، وبات المماليك تسعى بعضها إلى بعض، فظهر الملك الناصر في بيت الأمير سودن الحمزاوي، وتلاحق به كثير من الأمراء والمماليك، ولم يطلع الفجر حتى ركب السلطان بآلة الحرب، وإلى جانبه ابن غراب، وعليه آلة الحرب، وسار بمن اجتمع إليه يريد القلعة، فقاتله سودن ا"},{"id":3252,"era":"c9","t":"وفاة الخليفة العباسي المتوكل محمد وتولية ابنه المستعين بالله العباس .","s":"الخليفةُ أمير المؤمنين المتوكل على الله أبو عبد الله محمد بن المعتضد أبي بكر ابن المستكفي بالله أبي الربيع سليمان بن الحاكم بأمر الله أبي العباس أحمد، وكان عرض عليه الاستقلال بالأمر مرتين فأبى، وكان بويع بالخلافة بعهد من أبيه في سابع جمادى الآخرة سنة 763، وجعله الأمير أينبك البدري بن زكريا بن إبراهيم في ثالث عشرين صفر سنة تسع وسبعين، ثم أعيد في عشرين ربيع الأول، منها، وقبض عليه الظاهر برقوق في أول"},{"id":3253,"era":"c9","t":"وفاة ابن خلدون .","s":"هو القاضي ولي الدين أبو زيد عبد الرحمن بن محمد بن محمد بن خلدون التونسي الإشبيلي الحضرمي القاهري المالكي. وُلِدَ في تونس سنة 732. اشتغل في بلاده وسمع من الوادي آشي وابن عبد السلام وغيرهما، وأخذ القراءات عن محمد بن سعد بن براد، واعتنى بالأدب وأمور الكتابة والخط، حتى مهر في جميع ذلك. وولي كتابة العلامة عن صاحب تونس. ثم غادرها فارًّا من الطاعون متوجهًا إلى فاس في سنة ثلاث وخمسين، فعلا شأنه فيها حتى ك"},{"id":3254,"era":"c9","t":"مقاتلة الأمير جكم المتغلب على حلب مع التركمان والأعراب .","s":"في شهر ذي القعدة في ثالثه قَدِمَ الخبر بأن الأمير جكم الجركسي الظاهري لما أخذ حلب سار إلى الأمير فارس بن صاحب الباز التركماني المتغلب على إنطاكية، وقاتله وكسره أقبح كسرة وقتله وأخذ له أموالًا جزيلة، فقوي جكم بذلك، وكان قبل ذلك جاءه الخبر بمسير الأمير نعير بن حيار أمير الملا إليه، فلقيه عند قنسرين في النصف من شوال وقاتله، فوقع نعير في قبضته، وسَجَنه بقلعة حلب، وولي ابنه العجل بن نعير إمرة آل فضل عو"},{"id":3255,"era":"c9","t":"قتال الأمير جكم الجركسي مع نائب دمشق ومعه التركمان والأعراب .","s":"في خامس ذي الحجة اقتتل الأمير جكم الجركسي الظاهري، والأمير شيخ المحمودي نائب الشام، بأرض الرستن -فيما بين حماة وحمص-  قُتِل فيها الأمير طولو نائب صفد، والأمير علاق نائب حماة، وجماعة كثيرة من الفريقين، وانهزم الأمير شيخ ومعه الأمير دمرداش المحمدي إلى دمشق، ومضى منها إلى الرملة يريد القاهرة، فإن الأمير شيخ توجَّه من دمشق بعد عيد الأضحى، ومعه الأمير دمرداش، فنزل مرج عذراء في عسكره يريد حمص، وقد نزل ب"},{"id":3256,"era":"c9","t":"طاعون عظيم يعود إلى أرض مصر .","s":"ابتدأ الطاعون بالقاهرة ومصر، وتزايد حتى فشا في الناس وكثر الموت وبلغ عدد من يرد اسمه الديوان إلى مائتين وخمسين في كل يوم، وترجف العامة بأن عددهم أضعاف ذلك وشبهتهم أن الحوانيت المعدة لإطلاق الأموات أحد عشر حانوتًا، في كل حانوت نحو الخمسين تابوتًا، ما منها تابوت إلا ويتردد إلى الترب كل يوم ثلاث مرات وأكثر، مع كثرة ازدحام الناس عليها، وعز وجودها، فيكون على هذا عدة من يموت لا يقصر عن ألف وخمسمائة في ا"},{"id":3257,"era":"c9","t":"مقتل الأمير جكم الذي تسلطن وتلقب بالملك العادل .","s":"تسلطن الأمير جكم الجركسي الظاهري بحلب يوم حادي عشر رمضان، وتلقب بالسلطان الملك العادل أبي الفتوح عبد الله جكم، وخطب باسمه من حلب إلى الفرات إلى غزة، ما عدا صفد؛ وذلك أنه عَظُم أمره جدًّا، وخاصة أن السلطان فرج بن برقوق حاول أن يزيله عن عصيانه على حلب وغيرها، فكان أولًا قد هرب جكم منه، ثم لما رحل السلطان عن حلب رجع إليها واستطاع أن يتغلب على أكثر المناطق حتى وصل أمره إلى أن ولَّى هو مِن عنده على دمش"},{"id":3258,"era":"c9","t":"وفاة محمد السابع سلطان بني نصر وقيام أخيه أبي الحجاج مكانه .","s":"هو محمد السابع المستعين بن أبي الحجاج يوسف الثاني ملك بني نصر -بني الأحمر- في غرناطة بالأندلس، وقام بالأمر بعده أخوه أبو الحجاج يوسف الثالث الناصر، وكان معتقَلًا في سجن قلعة شلوبانية الحصينة القريبة من ثغر المنكب، والذي كان قد حبسه هو أخوه الملك محمد السابع هذا، وقام الملك الجديد أبو الحجاج بتجديد الهدنة مع ملك قشتالة لمدة تنتهي سنة 813."},{"id":3259,"era":"c9","t":"تغلب الأمير شيخ المحمودي على دمشق وعصيانه ثم قتله .","s":"في صفر حضر السلطان إلى دمشق وأمر باعتقال الأمير شيخ المحمودي نائبها ومعه الأمير يشبك الشعباني وحُبِسا بالقلعة، وأما الأمير جركس المصارع فهرب، ووكل بهما الأمير منطوق ولكنهما استطاعا أن يستميلاه، فهربوا جميعًا من القلعة، فأرسل وراءهم ولكن لم يُقتَل إلا منطوق، واستطاع يشبك وجركس وشيخ التغلُّبَ على حمص، ثم لما رحل السلطان عن دمشق وترك عليها الأمير بكتمر شلق، ثم لما كانت ليلة الأحد ثامن ربيع الآخر طرق "},{"id":3260,"era":"c9","t":"تولية أمير مكة إمرة الحجاز كلها وعصيان جماز بن نعير بالمدينة .","s":"أضاف السلطانُ إمرةَ المدينة النبوية، وإمرة ينبع، وخليص، والصفراء، وأعمالهم، إلى الشريف حسن بن عجلان أمير مكة، وكتب له بذلك توقيعًا، وهذا شيء لم ينَلْه أمير مكة قبله في هذا الزمان، أما المدينة فإن أميرها كان ثابت بن نعير، فمات فولى حسن بن عجلان مكانَه نيابة عنه أخاه، فثار بالمدينة جماز بن نعير، فكتب إليه ابن عجلان يقول: اخرُجْ بسلام، وإلَّا فأنا قاصدك، فأظهر جماز الطاعة، ثم إن جماز أرسل إلى الخُدَّ"},{"id":3261,"era":"c9","t":"حدوث زلزلة عظيمة في نواحي بلاد حلب وطرابلس .","s":"وقعت زلزلةٌ عظيمة في نواحي بلاد حلب وطرابلس، فخرب من اللاذقية وجبلة وبلاطنس أماكن عديدة، وسقطت قلعة بلاطنس. فمات تحت الردم بها خمسة عشر نفسًا، ومات بجبلة خمسة عشر نفسًا، وخربت شغر بكاس كلها والقلعتين بها، ومات جميع أهلها، إلا نحو خمسين نفسًا، وانشقَّت الأرض, وكما وقعت الزلزلة أيضًا بقبرص فخربت منها أماكن كثيرة."},{"id":3262,"era":"c9","t":"عصيان الأمير شيخ المحمودي نائب دمشق وقتاله مع السلطان .","s":"أفرج الأمير شيخ المحمودي نائب الشام عن الأمير سودن تلي الحمدي، والأمير طوخ، والأمير سودن اليوسفي، وهم الذين طلبهم السلطان، فامتنع من إرسالهم إليه حتى غضب، وسار من مصر إلى دمشق ليأخُذَ الأمير شيخ، ثم أظهر شيخ ما في نفسه، وصرح بالخروج عن طاعة السلطان، وأخذ في الاستعداد، وطلب الأمراء الذين أفرج عنهم إليه بالمرج، في ليلة الثامن والعشرين من المحرم واستدعى قضاة دمشق وفقهاءها، وتحدث معهم بحضرة الأمراء بج"},{"id":3263,"era":"c9","t":"القتال بين أولاد السلطان العثماني بايزيد الأول .","s":"اتجه محمد جلبي لقتال أخيه عيسى، وجرت بينهما عدة معارك خرج فيها محمد منتصرًا وقُتِل عيسى، فرجعت الأناضول تحت إمرته، ثم إن محمدًا الأول أرسل أخاه موسى على رأس جيش لقتال أخيهما سليمان الذي استطاع أن يهزم جيش موسى، فعاد خائبًا، ثم إنه كرر المحاولة مرة أخرى فتمكن في هذه السنة من القضاء على سليمان، وقَتَله على أبواب أدرنة، ثم بعد ذلك اتجه إلى الصرب الذين كانوا أعلنوا استقلالهم عن الدولة العثمانية في أثن"},{"id":3264,"era":"c9","t":"فرنج قشتالة يهزمون المسلمين ويستولون على مدينة أشقيرة بالأندلس .","s":"لما أوقع الطاغية صاحب قشتالة بالمسلمين في الزقاق، كثرت غاراته في بلاد المسلمين بالأندلس، وكثرت غاراتهم أيضًا على بلاد قشتالة، وكان ألفونسو قد قام بأمر أخيه دون، وكان عارفًا بالحروب والمكايد، شجاعًا، دَربًا، شديد البأس، فجمع لحرب المسلمين، ونزل على أشقيرة -تجاه مالقة - أول ذي الحجة، فلم يستنجد أبو الحجاج يوسف بن يوسف بن محمد بن إسماعيل بن نصر ابن الأحمر -صاحب غرناطة- عساكر فاس كما هي العادة، بل رأى"},{"id":3265,"era":"c9","t":"الأمير المحمودي والأمير نوروز يحاولان خلع السلطان فرج بن برقوق .","s":"في شهر ذي الحجة من سنة اثنتي عشرة وثمانمائة قاتل (الأمير شيخ المحمودي)  نوروزًا ودمرداش، سبعة أشهر وحاصرهما بحماة، ووقع بينهم في هذه المدة المذكورة حروب وخطوب يطول شرحها، وقُتِل بينهم خلائق لا تُحصى، واشتد الأمر على نوروز وأصحابه بحماة، وقلَّت عندهم الأزواد وقاسوا شدائد حتى وقع الصلح بينه وبين الأمير شيخ، وذلك عندما سمعوا بخروج الملك الناصر فرج إلى البلاد الشامية، وخاف نوروز إن ظفر به الملك الناصر"},{"id":3266,"era":"c9","t":"وفاة الملك أحمد بن أويس الجلائري وانقضاء دولة بني جلائر المغولية .","s":"هو أحمد بن أويس بن الشيخ حسن النوين بن حسين بن أقبغا بن أيلكان بن القال غياث الدين سلطان العراق. أوَّل ما ولي إمرة البصرة من أخيه حسين، فلما اختلف الأمراء على حسين خرج من بغداد إلى تبريز، فقدم أحمد بالجنود واغتال أخاه وقام بالسلطنة، وذلك في صفر سنة أربع وثمانين، وقبض على أعيان الأمراء فقتلهم وأقام أولادهم، فثار عليه من بقي ببغداد مع أخيه شيخ على شاه زاده؛ فآل الأمر إلى أن قتل واستبد أحمد فسار السي"},{"id":3267,"era":"c9","t":"الفرنج يحاولون إعادة عمارة بيت لحم .","s":"وصل إلى ميناء يافا أربع قطع، فيها نحو سبعمائة من الفرنج، فأسَروا جماعة من المسلمين، وأخذوا مركبًا فيه خام للسلطان قَدِمَ من مصر، وقدم أيضًا إلى يافا مركب فيه فرنج، معهم أخشاب وعَجَل وصُنَّاع، برسم عمارة بيت لحم بالقدس؛ حيث مولِدُ عيسى عليه السلام، وبيدهم مرسوم السلطان بتمكينهم من العمل، فدعوا الناس للعمل بالأجرة، فأتاهم عدة من القلعة والصنَّاع، وشرعوا في إزاحة ما بطريقهم من الأوعار، وكان سبب هذا أ"},{"id":3268,"era":"c9","t":"تأسيس الدولة الكثيرية الأولى .","s":"في أواخرِ القرنِ السادسِ الهِجريِّ كانت حَضرَموتُ مَيدانًا لِلمُناوراتِ السياسيةِ والفَوضى، حيث الصِّراعاتُ بينَ أطرافٍ مُتعدِّدةٍ، كبَني راشِدٍ وبَني يَمانٍ، وعَساكِرِ الغُزِّ الهاجمين مِنَ العَساكرِ المِصريةِ، وجُيوشِ ابنِ مَهديٍّ اليَمنيِّ، وغَيرِها مِنَ القَبائلِ والعَشائرِ الحَضرَميةِ، كبَني نَهدٍ وبَني حارِثةَ، فكانت حَضرَموتُ مُتفرقةً بينَ وُلاةٍ مُتعدِّدينَ، مُنتشرًا فيها النَّهبُ وسَفكُ ا"},{"id":3269,"era":"c9","t":"السلطان فرج بن برقوق يقتل المماليك الشراكسة مماليك أبيه وغيرهم .","s":"قبض السلطانُ الناصِرُ فرج على جماعةٍ من كبار المماليك الظاهرية -مماليك برقوق- وحبسهم بالبرج من القلعة، ثم قتَلَهم بعد شهر، وكانوا جمعًا كبيرًا، ثم في شهر رجب نزل السلطان من القلعة إلى الصيد، فبات ليلةً وعزم على مبيت ليلة أخرى بسرياقوس، فبلغه أن طائفة من الأمراء والمماليك اتفقوا على قتله، فعاد إلى القاهرة مسرعًا، وأخذ يتتبَّعُ ما قيل حتى ظفر بمملوكين عندهما الخبر، فعاقبهما في ثامن عشر شهر رجب، فأظه"},{"id":3270,"era":"c9","t":"عودة الأميرين شيخ ونوروز للخروج عن طاعة السلطان فرج بن برقوق .","s":"تواترت الأخبارُ بأنَّ الأميرين شيخًا ونوروزًا قد اتفقا على الخروج عن طاعة السلطان، وعزما على أخذ حماة، فوقع الشروع في عمارة قلعة دمشق، وكُتِبَ تقدير المصروف على ذلك مبلغ ثلاثين ألف دينار، وفيه وقع الاهتمام في بلاد الشام بتجهيز الإقامات للسلطان، وفي شهر رجب قدم الخبر بأن الأمير نوروزًا نائب طرابلس توجَّه منها إلى حصن الأكراد وحاصرها، وأن الأمير شيخًا كتب إليه أنه اتفق مع جماعة من قلعة حلب على أن يس"},{"id":3271,"era":"c9","t":"نزول الفرنج دمياط وهزيمتهم .","s":"نزل عددٌ من الفرنج على دمياط في أربعة أغربة وبيونيين -نوعين من المراكب-  فقاتلهم المسلمون على بر الطينة قتالًا كبيرًا، جُرح فيه جماعة من المسلمين، وقُتِلت خيولهم. فمضى الفرنج في آخر النهار إلى بر الطينة القديمة، ونهبوا ما كان هناك، وأتوا من الغد إلى حيث كانوا، فقاتلوا المسلمين مرة ثانية قتالًا كثيرًا، وعادوا إلى مراكبهم، فقدم في الحال غراب من أغربة المسلمين، فأحاط به الفرنج، فلم يثبت من كان في الغ"},{"id":3272,"era":"c9","t":"خروج السلطان الناصر فرج بن برقوق لقتال الأمراء المتمردين .","s":"خرج السلطان الملك الناصر فرج من دمشق بعساكره في يوم الاثنين سادس المحرم، ونزل برزة، ثم رحل منها يريد محاربة الأمراء الخارجين عليه: نوروز الحافظي، وشيخ المحمودي، ونزل حسيا بالقرب من حمص، فبلغه رحيل القوم من قارا إلى جهة بعلبك، فترك أثقاله بحسيا وساق على أثرهم إلى بعلبك، فوجدهم قد توجهوا إلى البقاع، فقصدهم، فمضوا نحو الصبيبة، فتبعهم حتى نزلوا باللجون، فساق السلطان خلفهم وهو سكران لا يعقِل، فما وصل إ"},{"id":3273,"era":"c9","t":"خلع السلطان الناصر فرج بن برقوق وتولية الخليفة العباسي المستعين .","s":"دار الأمرُ بين السلطان والأمراء العصاة عليه، وفي هذه الأثناء وفي يوم السبت خامس عشرين المحرم خلع الخليفة المستعين بالله الملكَ الناصر فرج من السلطنة، واتفق الأمراء على إقامة الخليفة المستعين بالله أبي الفضل العباس ابن الخليفة المتوكل على الله أبي عبد الله محمد ابن الخليفة المعتصم بالله أبي بكر ابن الخليفة المستكفي بالله أبي الربيع سليمان ابن الخليفة الحاكم بأمر الله أبي العباس أحمد بن الحسن بن أبي"},{"id":3274,"era":"c9","t":"اغتيال السلطان المخلوع فرج بن برقوق في حبسه في قلعة دمشق .","s":"هو الملِكُ الناصر فرج ابن السلطان برقوق، سلطان مملوكي، تولى عرش مصر بعد وفاة والده برقوق وعمره 13 سنة. حدث في عهده قحطٌ عام في البلاد وانتشرت أوباء مات فيها ثلث سكان البلاد, كما سادت الفتن والاضطرابات في عهده؛ فقد ثار عليه أمراء المماليك الظاهرية مماليك أبيه؛ لأنه قرَّب المماليك الجركسية وأبعدهم، وقتل عددًا كبيرًا من أمراء المماليك الظاهرية فقاتلوه حتى خلعوه من السلطنة، ثم تم القبض عليه وحَبسُه في"},{"id":3275,"era":"c9","t":"وفاة العلامة محب الدين أبو الوليد ابن الشحنة  .","s":"هو العلامة الفقيه المحدث القاضي الشاعر الأديب قاضي القضاة محبُّ الدّين أبو الوليد محمد بن محمد بن محمود بن غازي ابن أيوب بن الشِّحنة محمود، والشِّحنة جدُّه الأعلى محمود، الشهير بابن الشِّحنة التُّركي الأصل الحلبي الحنفي، وأسرة آل الشحنة المشهورين بحلب من قبيلة ثقيف، وظهر منهم علماء أجلاء. ولد أبو الوليد سنة 749، وحفظ القرآن العظيم وعدة متون، وتفقَّه وبرع في الفقه، والأصول، والنحو، والأدب، وأفتى ود"},{"id":3276,"era":"c9","t":"خلع الخليفة العباسي المستعين بالله وتولية الأمير شيخ المحمودي .","s":"بقي الخليفة العباسي المستعين بالله سلطانًا بعد خلع السلطان الناصر فرج أول السنة، ولكن الأمير شيخ المحمودي بيده كل شيء من أمر ونهي وعزل حتى تسمى بالأمير الكبير، ثم لما عَظُم أمره بعد موت بكتمر، وهو مقدم الألوف في الجيش، رأى شيخ المحمودي أن الجوَّ قد خلا له فلا مانع من سلطنته، فطلب الأمراء وكلَّمهم في ذلك، فأجاب الجميع بالسمع والطاعة طوعًا وكرهًا واتفقوا على سلطنته، فلما كان يوم الاثنين مستهل شعبان،"},{"id":3277,"era":"c9","t":"السلطان محمد جلبي بن بايزيد الأول يتولى حكم الدولة العثمانية .","s":"لما مات السلطان بايزيد الأول بن مراد الأول استولى أولاده على البلاد وجرت بينهم حروب، وكان أقواهم محمد الأول بن بايزيد الذي استطاع أن يأخُذَ البلاد التي تحت يد أخيه عيسى وسليمان، وأن ينفرد بالسلطة ويصبح هو السلطان العثماني الخامس المتفرد بحكم الدولة العثمانية، ولكن رغم ذلك لم تهدأ الفتن الداخلية والخارجية، وبقي على قتال مع جيرانه ممن كانوا يثورون عليه أحيانًا ويثور عليهم أحيانًا."},{"id":3278,"era":"c9","t":"عصيان الأمير نوروز نائب دمشق على السلطان ثم قتل نوروز .","s":"كانا الأميران نوروز وشيخ مشتركينِ في العصيان على السلطان الناصر فرج بن برقوق حتى تم لهما التغلب عليه، وقاما بسلطنة الخليفة المستعين بالله الذي  فوض إلى الأمير نوروز كفالة الشام جميعه: دمشق، وحلب، وطرابلس، وحماة، وصفد، وغزة، وجعل له أن يعيِّنَ الأمراء والإقطاعات لمن يريده ويختاره، وأن يولي نواب القلاع الشامية والسواحل وغيرها لمن أراد من غير مراجعة في ذلك، غير أنه يطالع الخليفة، ثم إن الأمير شيخًا ا"},{"id":3279,"era":"c9","t":"ظهور رجل في الشام يزعم أنه السفياني .","s":"قَدِمَ إلى أرض عجلون شخص يُسمَّى عثمان بن أحمد بن عثمان بن محمود بن محمد بن علي بن فضل بن ربيعة، يعرف بابن ثقالة، من فقهاء دمشق، وادعى أنه السفياني، وظهر بقرية الجيدور وحلَّف أهل البلاد وأقطع الإقطاعات، وأمَّر عدة من الناس، وقال: أنا السلطان الملك الأعظم السفياني، فاجتمع عليه خلق كثير؛ من عرب وترك وعشير، بألوية خضر إلى وادي إلياس من جبل عوف بمعاملة عجلون، وبثَّ كتُبَه، ووقَّع عليها تحت البسملة الس"},{"id":3280,"era":"c9","t":"خلع الخليفة العباسي المستعين بالله وتولية أخيه داود المعتضد بالله .","s":"قام السلطانُ المؤيد شيخ المحمودي في شهر ذي الحجة باستدعاء داود بن المتوكل على الله من داره، وهو أخو الخليفة العباسي العباس المستعين بالله، فحضر بين يديه بقلعة الجبل، وقد حضر قضاة القضاة الأربعة، فعندما رآه قام له، وقد ألبسه خِلعةً سوداء، وأجلسه بجانبه، بينه وبين قاضي القضاة شيخ الإسلام جلال الدين البلقيني، فدعا القضاة، وانصرفوا على أن داود بن المتوكل على الله استقَرَّ في الخلافة، ولم يقع خلع الخلي"},{"id":3281,"era":"c9","t":"هبوب ريح شديدة ورعد مرعب ومطر غزير وبَرَد كثير على مصر .","s":"هبَّت بمصر ريحٌ شديدة تلاها رعد مرعب، ومطر غزير، وسقط مع ذلك بمدينة مصر خاصة برد بقدر البندقة كثير جدًّا، بحيث ألقي على أسطحة الدور منه قناطير، وأخرب عدة دور، فخزن الناس منه شيئًا كثيرًا وبِيعَ في الأسواق بعد ذلك كل رطل بستة دراهم، ولم يسقط منه بالقاهرة شيء البتة."},{"id":3282,"era":"c9","t":"القتال بين السلطان العثماني محمد جلبي وأمير قرمان .","s":"وقعت معركةٌ بين محمد الأول سلطان العثمانيين وبين أمير قرمان محمد بن قرمان؛ وذلك أنه لما رأى اضطراب الأمور بين الإخوة العثمانيين، قَوِيَ عزمه على المسير إلى السلطان محمد جلبي ومحاربته فسار إلى بورصا وحاصرها، ثم حصل بين الطرفين قتال انتهى بانتصار السلطان محمد الأول على أمير قرمان وأخذه أسيرًا، ولكنه عفا عنه بعد أن حلف له بالطاعة وأنه لا يخرج عليه مرة أخرى، لكنه حنث وعاود الخروج لقتاله مرة أخرى، فانت"},{"id":3283,"era":"c9","t":"نزول ملك البرتقال على مدينة سبتة .","s":"نزل ملك البرتقال من الفرنج على مدينة سبتة في ثلاثمائة مركب، وأقام مدة بجزيرة فيما بينها وبين جبل الفتح يقال لها طرف القنديل، حتى ملَّ المسلمون الذين حُشِروا بسبتة من الجبال، ونفدت أزوادهم، وعادوا إلى ديارهم، فطرقها عند ذلك الفرنج، وقاتلوا المسلمين، وهزموهم، وركبوا أقفيَتَهم، وعبروا باب الميناء فتحَمَّل المسلمون بما قدروا عليه، ومرُّوا على وجوههم، فتملك البرتقال سبتة في سابع شعبان. وكان لذلك سبب هو"},{"id":3284,"era":"c9","t":"وفاة الفيروزآبادي صاحب كتاب القاموس المحيط .","s":"هو الشيخ العلَّامة أبو الطاهر مجد الدين محمد بن يعقوب بن محمد بن إبراهيم بن عمر الفيروزآبادي الشيرازي الشافعي اللغوي، وُلِدَ سنة 729 بمدينة كازرون وتفقه بها. قال جلال الدين السيوطي: \"كان يرفع نسبَه إلى الشيخ أبي إسحاق الشيرازي صاحب التنبيه، ويقول: إن جده فضل الله ولد الشيخ أبي إسحاق، ولا يبالي بما يشاع بين الناس أن الشيخ أبا إسحاق لم يتزوَّج فضلًا عن أن يُعقِبَ\" وقال المقري التلمساني: \"ثم ارتقى ال"},{"id":3285,"era":"c9","t":"حدوث فتنة بالمسجد الحرام .","s":"كان الأميرُ جقمق الأرغون شاوي الدوادار الثاني أمير الحاج فوقع بينه وبين أشراف مكة وقعة في خامس ذي الحجة، وخبر ذلك أن جقمق ضرب أحدَ عبيد مكةَ وحبسه؛ لكونه يحمل السلاح في الحرم الشريف، وكان قد مَنَع من ذلك، فثارت بسبب ذلك فتنة انتُهِكت فيها حرمة المسجد الحرام، ودخلت الخيلُ إليه عليها المقاتِلةُ من قوَّاد مكة لحرب الأمير جقمق، وأدخل جقمق أيضًا خيله إلى المسجِدِ الحرام، فباتت به تروث!! وأوقد مشاعِلَه "},{"id":3286,"era":"c9","t":"فكاك الأسرى المسلمين من قبرص .","s":"قَدِمَ كتاب أقبغا النظامي -أحد خواص السلطان الناصر فرج بن برقوق- من جزيرة قبرص، وقد توجَّه إليها لفك الأسرى، وأنه وجد بالجزيرة من أسارى المسلمين خمسمائة وخمسة وثلاثين أسيرًا، فِكاكُهم بثلاثة عشر ألف دينار وثلاثمائة دينار، وأنه قد أوصل إلى متملك قبرص العشرة آلاف دينار المجهَّزة معه، فانفك بها أربعمائة أسير، كل أسير بخمسة وعشرون دينارًا، وقد افتَكَّ متملك قبرص من مائة وخمسة وثلاثين أسيرًا، بثلاثة آل"},{"id":3287,"era":"c9","t":"وفاة الأمير سودون بن عبد الله المحمدي الظاهري الشهير بتلي .","s":"هو الأمير سيف الدين سودون بن عبد الله المحمدي الظاهري، الشهير بتلي، يعني مجنونًا، كان من مماليك الملك الظاهر برقوق، ومن أعيان خاصكيته، وترقى في الدولة الناصرية فرج بن برقوق إلى أن صار أمير مائة ومقدم ألف. ثم قُبِضَ عليه وحُبِسَ بثغر الإسكندرية، هو وبيبرس الصغير الدوادار، وجانم بن حسن شاه، في يوم الخميس سابع عشر ذي الحجة سنة 806، فاستمروا في السجن إلى أن أُفرج عنهم في شوال سنة 807. وقَدِموا القاهرة"},{"id":3288,"era":"c9","t":"إعادة طرسوس إلى سلطة المماليك بعدما كانت تابعة لتيمورلنك .","s":"قَدِمَ كتاب نائب حلب بأن الشهابي أحمد بن رمضان -وهو من الأمراء التركمان الأوحقية- أخذ مدينة طرسوس عَنوةً في ثالث عشر المحرم، بعد أن حاصرها سبعة أشهر، وأنه سلمها إلى ابنه إبراهيم، بعدما نهبها وسبى أهلها، وقد كانت طرسوس من نحو اثنتي عشرة سنة يخطب بها تارة لتيمورلنك، وتارة لمحمد باك بن قرمان، فيقال: السلطان الأعظم سلطان السلاطين، فأعاد ابن رمضان الخطبة فيها باسم السلطان الملك المؤيد شيخ المحمودي."},{"id":3289,"era":"c9","t":"عصيان نواب الشام بزعامة نائب دمشق الأمير قاني باي وقتله .","s":"قَدِمَ الخبر على السلطان المؤيد شيخ المحمودي بخروج قاني باي نائب الشام عن الطاعة، ثم ورد الخبر بخروج الأمير طرباي نائب غزة عن الطاعة وتوجُّهِه إلى الأمير قاني باي المحمدي نائب دمشق، فعند ذلك ندب السلطان الأمير يشبك المؤيدي المشد ومعه مائة مملوك من المماليك السلطانية، وبعثه نجدةً للأمير ألطنبغا العثماني، ثم ورد الخبر ثالثًا بعصيان الأمير تنبك البجاسي نائب حماة وموافقته لقاني باي، وكذلك الأمير إينال"},{"id":3290,"era":"c9","t":"انتشار الطاعون بمصر والشام وبلاد المشرق والمغرب .","s":"دخل فصل الربيع، وقد فشا في الناس الموت بالطاعون، وأُحصيَ من ورد اسمُه الديوان ممن مات بالقاهرة في مدة شهر أوله عاشر المحرم، فكان ثلاثة آلاف إنسان، ثم تجاوز عدد من يرد اسمه الديوان من الأموات مائة نفس في اليوم، وهذا سوى من يموت بالمارستان، وفي عدة مواضع خارج المدينة، ويكون ذلك نحو الخمسين نفسًا، وكانت عدة من صُلِّي عليه من الأموات بمصلى باب النصر خاصة من أول النهار إلى آذان الظهر اثنين وتسعين ميتًا"},{"id":3291,"era":"c9","t":"الفرنج ينزلون على يافا ويأسرون بعض المسلمين .","s":"قدم الفرنج في أربعة أغربة -نوع من المراكب- إلى مدينة يافا، وأسروا نحو الخمسين امرأة وطفلًا، وحاربهم المسلمون، وقتلوا منهم واحدًا، ثم افتكُّوا الأسرى خمسة عشر دينارًا لكل أسير."},{"id":3292,"era":"c9","t":"السلطان شيخ المحمودي يأمر الخطباء بالنزول درجة عند الدعاء له .","s":"في سابع جمادى الآخرة من هذه السنة أمر السلطان المؤيد شيخ المحمودي الخطباء إذا أرادوا الدعاء للسلطان على المنبر في يوم الجمعة أن ينزلوا درجةً ثم يدعوا للسلطان حتى لا يكون ذكر السلطان في الموضع الذي يذكر فيه اسمُ الله عزَّ وجلَّ واسم نبيه صلى الله عليه وسلم؛ تواضعًا لله تعالى، ففعل الخطباء ذلك، وحَسُن هذا ببال الناس إلى الغاية، واعتمد خطباء مصر والقاهرة ما أشار به السلطان، فنزلوا عندما أرادوا الدعاء"},{"id":3293,"era":"c9","t":"الفرنج ينزلون على الإسكندرية ويأسرون بعض المسلمين .","s":"في سادس عشر جمادى الآخرة قدم الأمير صلاح الدين محمد الحاجب بن الصاحب بدر الدين حسن بن نصر الله ناظر الخاص إلى الإسكندرية في تحصيل المال، فجلس بالخمس، وبين يديه أعيان أهلها، فجاءه الخبر بأن الفرنج الذين وصلوا ببضائع المتجر، وهم في ثمان عشاريات من مراكب بحر الملح، قد عزموا على أن يهجموا عليه، وأن يأخذوه هو ومن معه، فقام عَجِلًا من غير تأنٍّ يريد الفرار، وتسارع الناس أيضًا يفرون، فهجم الفرنج من باب ا"},{"id":3294,"era":"c9","t":"السلطان محمد الأول يغزو  قسطمونية .","s":"توجَّه السلطان محمد جلبي بن بايزيد بن مراد صاحب بورصا؛ لقتال اسفنديار ابن أبي يزيد متملك قسطمونية وحصره في جزيرة سينوب، فقامت معركة على بحر إيجه قرب مدينة غاليبولي كان نهايتها أن وقع بينهما الاتفاق على أن يخطب له ويضرب السكة باسمه، فأفرج عنه وعاد اسفنديار إلى قسطمونية، وخُطِب باسم السلطان محمد الأول فلم يوافِقْه وزيره خواند سلار على إقامة الخطبة بالجامع الذي أنشأه للسلطان محمد جلبي، وصار يخطب فيه "},{"id":3295,"era":"c9","t":"فتنة بمكة بين الأشراف والأمراء .","s":"لما عُزِل الشريف حسن بن عجلان بالشريف رميثة في صفر من السنة الحالية، ودخل رميثة إلى مكة لم يتعرض إليه الشريف حسن، حتى بعث ابنه بركات، وقائده شكر إلى السلطان، فقدما فكتب السلطان بإعادة الشريف حسن إلى الإمرة في ثامن عشر شهر رمضان، وجهز إليه تشريفه وتقليده، فقدما عليه وهو بجدة في ثاني شوال، فبعث إلى القواد العمرية -وكانوا باينوه من شعبان ولحقوا برميثة في مكة- يرغبهم في طاعته، فأبوا عليه وجمعوا لحربه،"},{"id":3296,"era":"c9","t":"السلطان المؤيد المحمودي يغير على التركمان في أبلستين .","s":"أمر السلطان المؤيد شيخ المحمودي ولده المقام الصارمي إبراهيم ليتوجه إلى أبلستين ومعه الأمير جقمق الأرغون شاوي الدوادار، وجماعة من الأمراء؛ لكبس الأمير ناصر الدين محمد بن دلغادرة فساروا مجِدِّين، فصبَّحوا أبلستين وقد فرَّ منها ابن دلغادر، وأجلى البلاد من سكانها، فجدوا في السير خلفه ليلًا ونهارًا حتى نزلوا بمكان يقال له كل دلي في يوم الخامس عشر من ربيع الآخر وأوقعوا بمن فيه من التركمان، وأخذوا بيوتهم"},{"id":3297,"era":"c9","t":"السلطان المؤيد شيخ المحمودي يتسلم طرسوس .","s":"أخذ الأميرُ صارم الدين إبراهيم بن رمضان طرسوس, وصيَّرها في طاعة السلطان المؤيد، ولكنه لم يسلِّمْها، بل جعل الخطبة للسلطان، وفي هذه السنة قدم الأمير إبراهيم بن رمضان، وابن عمه حمزة بن أحمد بن رمضان، وسائر أمراء التركمان الأوحقية، في جمع كبير، ومعهم أم إبراهيم بن رمضان، وأولاده الصغار في خمسمائة من أمرائه وأقاربه وأزلامه، فقام السلطان لهم، وخلع على إبراهيم وعلى أخيه، وحلف التركمان على الطاعة، وخلع ع"},{"id":3298,"era":"c9","t":"وفاة أبي الحجاج يوسف الثالث ملك بني نصر بغرناطة وتولي ابنه .","s":"توفِّيَ الملك أبي الحجاج يوسف الثالث بن إسماعيل بن فرج ملك بني نصر في الأندلس، طُعِنَ بخنجر في جبينه يوم عيد الفطر، فمات منه وتسلطن بعده ابنه أبو عبد الله محمد الثامن الملقَّب بالأيسر."},{"id":3299,"era":"c9","t":"فتنة في دمياط بسبب والي مصر .","s":"وقعت فتنة بدمياط قُتِلَ فيها الوالي، وهي أنَّ أعمال مصر منذ ابتداء أيام الظاهر برقوق، لا يولَّى بها وال إلا بمالٍ يقوم به، أو يلتَزِمُ به، وكان من أتباع المماليك رجل سوَّلت له نفسه ولاية في دمياط، يعرف بناصر الدين محمد السلاخوري، التزم بمالٍ ووَلِيَها، واستدان مالًا حتى عمل له ما يتجمَّلُ به وباشرها غير مرة في هذه الأيام المؤيدية، فلما وليها في هذه السنة جرى على عادته في ظلم الناس، وأخْذِ أموالهم "},{"id":3300,"era":"c9","t":"وفاة القلقشندي صاحب صبح الأعشى .","s":"هو شهاب الدين أبو العباس أحمد بن علي بن أحمد الفزاري القلقشندي, ولد سنة 765 بقلقشند إحدى قرى القليوبية قرب القاهرة، وبرع القلقشندي بالعربية والإنشاء، وكان عالِمًا بالأنساب، عَمِلَ بديوان الإنشاء في عهد السلطان المملوكي الظاهر برقوق الشركسي ويعتبر كتابه صبح الأعشى في صناعة الإنشاء من أهم كتبه، بل يعتبر من أهم الكتب التي جمعت عدة معارف يحتاج إليها الكاتب: من الخط، والقلم، والمِداد، والجغرافية، والتا"},{"id":3301,"era":"c9","t":"عدوان قرا يوسف التركماني صاحب بغداد وتبريز على بلاد الشام  .","s":"قَدِمَ الأمير بردبك الحمزاوي -أحد أمراء الألوف بحلب- ومعه نائب كختا -الأمير منكلي بغا- بكتاب يشبك نائب حلب، والأمير عثمان بن طر علي، المعروف بقرا يلك التركماني العثماني، بأن قرا يلك عدى الفرات من مكان يقال له زغموا، ونزل على نهر المرزبان؛ وذلك أنه بلغه أن قرا يوسف قصد كبْسَه، فما أحس قرا يلك إلا وقد هجمت فرقة من عسكر قرا يوسف التركماني عليه من شميصات دخل بهم خليل نائب كركر، فأدركوا قرا يلك عند رحي"},{"id":3302,"era":"c9","t":"الطاعون يفشو في مصر ويحصد الآلاف من الناس .","s":"فشا الموت بالطاعون في إقليمي الشرقية والغربية وجميع الوجه البحري، وكان ابتداؤه بالقاهرة ومصر منذ حلت الشمس في برج الحمل، في يوم الأحد الخامس عشر صفر، فبلغت عدة من يرد الديوان من الأموات ما بين العشرين والثلاثين في كل يوم، وبلغت عدة من ورد من الأموات بالقاهرة إلى الديوان نحو الخمسين، أكثرهم أطفال، وذلك سوى المارستان، وموتهم بأمراض حادة، وحبة الموت قَلَّ من يمرض منهم ثلاثة أيام، بل كثير منهم يموت سا"},{"id":3303,"era":"c9","t":"دخول قيسارية إلى السلطنة المملوكية .","s":"قَدِمَ الخبر برحيل ابن السلطان المؤيد شيخ من حلب، ودخل إلى مدينة قيسارية الروم في يوم الخميس تاسعه، فحضر إليه أكابرها من القضاة والمشايخ والصوفية، وتلقوه، فألبسهم الخِلَع، وطلع قلعتها في يوم الجمعة، وخُطِبَ في جوامعها للسلطان، وضُرِبت السكة باسمه، وأن شيخ جلبي نائب قيسارية انسحب قبل وصوله إليها، وأنه خلع على الأمير محمد بك قرمان، وأقره في نيابة السلطنة بقيسارية الروم، فدُقَّت البشائر بقلعة الجبل، "},{"id":3304,"era":"c9","t":"منع النصارى من العمل في ديوان السلطان وإلزامهم بملابس خاصة .","s":"في سابع جمادى الأولى استُدعِيَ بطرك النصارى، وقد اجتمع القضاة ومشايخ العلم عند السلطان، فأُوقِفَ على قدميه، ووُبِّخ وقُرِّع، وأنكر عليه ما بالمسلمين من الذلِّ في بلاد الحبشة، تحت حكم الحطي متملِّكِها، وهُدِّد بالقتل، فانتدب له محتسب القاهرة صدر الدين أحمد بن العجمي وأسمعه المكروه له من أجل تهاون النصارى فيما أُمروا به من التزام الذلة والصغار في ملبسهم وهيأتهم، وطال الخطابُ في معنى ذلك إلى أن استقر"},{"id":3305,"era":"c9","t":"وفاة السلطان عثمان المريني سلطان بني مرين ومبايعة ابنه الصبي .","s":"هو السلطان أبو سعيد عثمان بن السلطان أبي العباس أحمد ابن السلطان أبي سالم إبراهيم ابن السلطان أبي الحسن علي بن عثمان بن يعقوب بن عبد الحق المريني الفاسي ملك الغرب وصاحب فاس. توفي قتيلًا في ليلة الثالث عشر شوال، قتله وزيره عبد العزيز اللباني، وكانت مدته ثلاثًا وعشرين سنة وثلاثة أشهر، وأقيم ولده عبد الحق خلفًا له مع أنه ما يزال صبيًّا، وكان الوصيُّ عليه الوزير أبا زكريا يحيى الوطاسي، فكان هو الحاكم،"},{"id":3306,"era":"c9","t":"السلطان المؤيد شيخ المحمودي يعهد بالسلطنة لولده أحمد من بعده .","s":"طلب السلطان القضاة والأمراءَ فعهد إلى ولده الأمير أحمد بالسلطة من بعده، ومولده في ثاني جمادى الأولى من السنة الماضية، وله من العمر سبعة عشر شهرًا وخمسة أيام، وجعل الأمير الكبير ألطنبغا القرمشي القائِمَ بأمره، وأن يقومَ بتدبير الدولة, ثم أحضر القرمشي من حلب الأمراء الثلاثة، وهم: قجقار القردمي، وتنبك ميق، وططر، وحلفوا على ذلك، ثم حلف المماليك من الغد، ثم في ذي الحجة أثبت عهد الأمير أحمد ابن السلطان "},{"id":3307,"era":"c9","t":"وفاة الأمير قرا يوسف متملك العراق وتبريز وتملك ابنه شاه محمد .","s":"هو الأمير قرا يوسف ابن الأمير قرا محمد بن بيرم خجا التركماني متملك العراق وتبريز، وكان قرا يوسف شديد الظلم قاسي القلب لا يتمسَّك بدين، واشتهر عنه أنَّ في عصمته أربعين امرأة، وقد خربت في أيامه وأيام أولاده مملكة العراقين, فصدر بحقه فتوى تستبيحُ دمه, فقد ذكر موفق الدين ابن العجمي \"أن قرا يوسف عنده أربع زوجات، فإذا طلَّق واحدةً دفعها إلى قصر له وتزوَّج غيرها حتى بلغ عدد من في القصر أربعين امرأة يسمِّ"},{"id":3308,"era":"c9","t":"وفاة السلطان محمد جلبي سلطان العثمانيين وتولي ابنه مراد الثاني .","s":"هو السلطان محمد الأول بن بايزيد الأول بن مراد الأول بن أورخان غازي بن عثمان بن أرطغرل، هو السلطان الخامس للدولة العثمانية والملقب بالجلاد -ويعرف بمحمد جلبي- تولى السلطنة بعد وفاة أبيه، ونازعه إخوته الثلاثة على الحكم فقاتلهم حتى تمكن من قتلهم، ثم عمل على استرجاع الأراضي التي انتُزِعَت من الدولة بعد هزيمة والده وأسْرِه من قِبَل تيمورلنك في معركة أنقرة سنة 804, كما أنه عمل على بناء وتقوية الأسطول الب"},{"id":3309,"era":"c9","t":"وفاة السلطان الملك المؤيد شيخ المحمودي سلطان المماليك .","s":"هو السلطان الملك المؤيد أبو النصر سيف الدين شيخ بن عبد الله المحمودي الظاهري، وهو السلطان الثامن والعشرين من ملوك الترك المماليك بالديار المصرية، والرابع من الشراكسة وأولادهم، أصله من مماليك الملك الظاهر برقوق، اشتراه من أستاذه الخواجا محمود شاه البرزي في سنة 782، وبرقوق يوم ذاك أتابك العساكر بالديار المصرية قبل سلطنته، وكان عمر شيخ يوم اشتراه الملك الظاهر نحو اثنتي عشرة سنة تخمينًا، وجعله برقوق م"},{"id":3310,"era":"c9","t":"عصيان الأمير جقمق نائب دمشق وتسلطنه فيها ثم إنهاء فتنته وقتله .","s":"في سابع شهر صفر قدم الخبر بأن الأمير جقمق نائب الشام أخذ قلعة دمشق واستولى على ما فيها من الأموال وغيرها، وكان بها نحو المائة ألف دينار، فاضطرب أهلُ الدولة؛ وذلك لما بلغه من أن الأمير ططر قام بأمور السلطنة كلها وتفرد بها، وفي ثامن عشر ربيع الآخر قدم الخبر بأن عساكر دمشق برزت منها، وأنها نزلت باللجون، فركب الأمير ططر في يوم الثلاثاء التاسع عشر من قلعة الجبل ومعه السلطان الملك المظفر أحمد والأمراء، "},{"id":3311,"era":"c9","t":"الأمير الكبير ططر يتفرد بأمور السلطنة بحجة صغر السلطان المظفر .","s":"في عاشر شهر صفر جمع الأميرُ الكبير ططر عنده بالأشرفية من القلعة قضاةَ القضاة وأمراء الدولة ومباشريها، وكثيرًا من المماليك السلطانية، وأعلَمَهم بأن نواب الشام والأمير ألطنبغا القرمشي ومن معه من الأمراء المجردين لم يرضوا بما عمل بعد موت المؤيد، ولا بد للناس من حاكم يتولى تدبيرَ أمورهم، ولا بد أن يعيِّنوا رجلًا ترضَونه؛ ليقوم بأعباء المملكة ويستبد بالسلطنة، فقال الجميع: قد رضينا بك، وكان الخليفة حاضر"},{"id":3312,"era":"c9","t":"الحرب بين بني زيان والمرينيين .","s":"كانت حربٌ بمدينة فاس من بلاد المغرب بين أبي زيان محمد بن أبي طريق بن أبي عنان, وقد قام بأمر الحرب الشيخ يعقوب الحلفاوي الثائر على الوزير الحاجب عبد العزيز اللباني لقتله السلطان أبا سعيد عثمان بن أبي العباس أحمد وثلاثة عشر أميرًا من إخوته وأولاده وبني إخوته, وكان اللباني قد استنصر بالشاوية، وبعث إليهم بمال كبير، فأتوه، فلم يطق الحلفاوي مقاومتهم، فأُدخل اللباني مدينة فاس بجموعه، وألويته منشورة على ر"},{"id":3313,"era":"c9","t":"خلع السلطان المظفر أحمد وتسلطن الأمير الكبير ططر .","s":"لما انتهى الأمير ططر من أمر جقمق في دمشق وكان هو المتولي لكل أمور السلطنة، عزم على خلع المظفر من السلطنة، وخاصة أنه يراه صغيرًا جدًّا على هذا الأمر، فخلعه في التاسع والعشرين شعبان وهو في دمشق، فكانت مدة سلطنة السلطان المظفر أحمد بن المؤيد شيخ سبعة أشهر وعشرين يومًا، وتلقب السلطان الجديد بالظاهر سيف الدين أبو الفتح ططر بن عبد الله الظاهري، وخُطِب له من يومه على منابر دمشق، وكُتِب إلى مصر وحلب وحماة"},{"id":3314,"era":"c9","t":"عصيان مصطفى بن بايزيد على ابن أخيه السلطان مراد الثاني  .","s":"بعد أن تولى السلطان مراد الثاني سلطنة الدولة العثمانية، طلب منه إمبراطور القسطنطينية إيمانويل أن يتعهد له بعدم محاربته مطلقًا وأن يسلمه اثنين من إخوته تأمينًا على نفاذ هذا التعهد وتهدده بإطلاق سراح عمه مصطفى بن بايزيد ولَمَّا لم يجبه مراد الثاني لطلبه أخرج مصطفى من منفاه وأعطاه عشرة مراكب حربية تحت إمرة دمتريوس لاسكاريس, فحاصر بها مدينة غاليبولي فسُلِّمَت إلا القلعة فتركها مصطفى بعد أن أقام حولها "},{"id":3315,"era":"c9","t":"وفاة السلطان الملك الظاهر ططر وتولي ابنه الصالح محمد .","s":"هو الملِكُ الظاهر سيف الدين أبو الفتح ططر بن عبد الله الظاهري الشركسي, ربَّاه بعض التجار، وعلَّمه شيئًا من القرآن وفِقهَ الحنفية، وقَدِمَ به القاهرة في سنة 801، وهو صبيٌّ، فدل عليه الأمير قانبيه العلاي لقرابته به، فسأل السلطان الملك الظاهر برقوق فيه حتى أخذه من تاجره، ونزله في جملة مماليك الطباق، فنشأ بينهم، وكان الملك الظاهر برقوق أعتقه بسفارة الأمير جرباش الشيخي. بعد وفاة الملك المؤيد شيخ بويعَ "},{"id":3316,"era":"c9","t":"خروج الأمير تغري بردي المؤيدي نائب حلب عن الطاعة .","s":"لما كان يوم ثامن عشر ذي الحجة ورد الخبر بأن الأمير تغري بردي المؤيدي نائب حلب المعروف بأخي قصروه- خرج عن طاعة السلطان، وقبض على الأمراء الحلبيين، واستدعى التركمان والعربان، وأكثر من استخدام المماليك، وسببُ خروجه عن الطاعة أنه بلغه أن الملك الظاهر ططر عزَلَه، وأقرَّ عِوَضَه في نيابة حلب الأمير تنبك البجاسي نائب طرابلس، فلما تحقق ذلك خرج عن الطاعة وفعل ما فعل، فشاور الأمير برسباي الأمراءَ في أمره، ف"},{"id":3317,"era":"c9","t":"خلع السلطان الصالح محمد بن ططر وتسلطن الأشرف برسباي .","s":"ما زال برسباي قائمًا بتدبير أمر الدولة، ثم أحَبَّ أن يُطلَق عليه اسمُ السلطان لما خلا له الجو؛ فإنه كان ينافسه جنبك  الصوفي، وقد استطاع طرباي التخلص منه، ثم استطاع برسباي بمكيدة كذلك التخلص من طرباي وسجنه، ولما تم أمر الأمير برسباي فيما أراد من القبض على الأمير طرباي والاستبداد بالأمر، أخرج الأمير سودون الحموي منفيًّا إلى ثغر دمياط، ثم أخذ في إبرام أمره ليترقى إلى أعلى المراتب، فلم يلقَ في طريقه م"},{"id":3318,"era":"c9","t":"السلطان الأشرف برسباي يمنع من عادة تقبيل الأرض للملوك  .","s":"أول ما بدأ به الأشرف في سلطنته أنَّه منع الناس كافةً من تقبيل الأرض بين يديه، فامتنعوا من ذلك، وكانت عادةُ تقبيل الأرض جرت بالديار المصرية من أيام المعزِّ معد أول خلفاء بني عُبَيد بمصر، وبقيت إلى يوم تاريخه، وكان لا يُعفى أحد عن تقبيل الأرض، والكل يُقَبِّل الأرض: الوزير والأمير والمملوك وصاحب القلم ورسل ملوك الأقطار، إلا قضاة الشرع وأهل العلم وأشراف الحجاز! حتى لو ورد مرسوم السلطان على ملك من نواب"},{"id":3319,"era":"c9","t":"السلطان الأشرف يمنع اليهود والنصارى من استخدام ديوان السلطنة .","s":"في يومِ الخميس ثامن جمادى الأولى صدر مرسوم السلطان الملك الأشرف بألَّا يُستخدَم أحد من اليهود ولا من النصارى في ديوان من دواوين السلطان والأمراء، ونودِيَ بذلك في القاهرة، وصَمَّم الأشرف على ذلك، فلم يسلَمْ من اعتراض بعض عظماء الأقباط من مباشري الدولة، فلم يتِمَّ له ذلك."},{"id":3320,"era":"c9","t":"السلطان العثماني مراد الثاني يعقد صلح مع ملوك أوروبا .","s":"بعد أن تولى مراد الثاني السلطنة خلفًا لأبيه محمد جلبي رأى أنَّ عليه أن يعيد الإمارات في الأناضول إلى حظيرة الدولة العثمانية، فعَقَد هدنة مع ملك المجر مدتها خمس سنوات، وصالح أمير قرمان، وأمَّا إمبراطور القسطنطينية فطلب من  مراد الثاني التعهُّدَ بعدم قتاله، وطلب منه أن يسلِّمَه اثنين من إخوته كرهائن، وأنه إذا فكر بالحرب فسيطلق سراح عم السلطان مصطفى بن بايزيد المحجوز في سلانيك، وهو المنافس لمراد الثا"},{"id":3321,"era":"c9","t":"السلطان مراد الثاني يحاصر القسطنطينية .","s":"لما تخلص مراد الثاني من عمه مصطفى بن بايزيد الذي دعمه إمبراطور القسطنطينية سار في شهر رجب من بورصا إلى اسطنبول ( قسطنطينية) ونزل عليها أول شعبان، وقطع عامة أشجارها، ومنع عنها الميرة، حتى فرغ شهر رمضان من غير حرب، سوى مرة واحدة في يوم الجمعة ثالث رمضان، فإنه زحف على المدينة فكان بينه وبين أهلها حرب شديدة، فتخلى عنه عسكره، وبينما هو في ذلك إذ جاءه أخوه مصطفى، وكان في مملكة محمد باك بن قرمان، فتفرق ع"},{"id":3322,"era":"c9","t":"خروج الأمير إينال نائب صفد عن الطاعة وقتله .","s":"في شهر رجب ورد الخبر على السلطان بخروج الأمير إينال نائب صفد عن الطاعة، وكان سبب خروجه عن الطاعة أنه كان من جملة مماليك الملك الظاهر ططر، ربَّاه صغيرًا، ثم ولاه نيابة قلعة صفد بعد سلطنته، فلما قام الملك الأشرف برسباي بعد الملك الظاهر ططر بالأمر ولى إينال نيابة صفد، وبلغه خلع ابن أستاذه الملك الصالح محمد من السلطنة، فشَقَّ عليه ذلك، وأخذ في تدبيرِ أمره، واتَّفق مع جماعة على العصيان، وخرج عن الطاعة،"},{"id":3323,"era":"c9","t":"عبث الفرنج بسواحل الإسكندرية .","s":"كثُرَ عَبثُ الفرنج بالسواحل، وهجم في الليل غرابان -مركبان- فيهما طائفة من الفرنج، على ميناء الإسكندرية، فوجدوا فيها مركبًا للتجار فيه بضائع بنحو مائة ألف دينار، فاقتتلوا معهم عامة الليل، فخرج الناس من المدينة، فلم يقدروا على الوصول إليهم؛ لعدم المراكب الحربية عندهم، ولا وصلت سهامهم إلى الفرنج، بل كانت تسقط في البحر، فلما طال الحرب بين الفرنج والتجار المسلمين، واحترقت مركب التجار، نجَوا في القوارب "},{"id":3324,"era":"c9","t":"القتال بين عسكر السلطان الأشرف برسباي والأمير مقبل أمير ينبع .","s":"في السابع والعشرين ذي الحجة نزل الحاج بينبع، وقد استعدَّ من فيهم من المماليك السلطانية مع الأمير جانبك الخازندار أحد أمراء العشرات لحرب الشريف مقبل: متولي ينبع، وقد قدم الشريف عقيل بن وبير الحسني من القاهرة بصحبتهم بعدما خُلِع عليه بها في شوال من هذه السنة، واستقرَّ أمير ينبع شريكًا لعمه مقبل، بمالٍ التزم للدولة، فلما عَلِمَ مقبل بذلك نزح عن ينبع إلى واد بالقرب منها، وكان الحاج قد دخلوا ينبع في ذي"},{"id":3325,"era":"c9","t":"اعتداء ملك الحبشة على المسلمين بسبب إغلاق كنيسة القيامة .","s":"غَضِبَ متملِّك الحبشة، وهو أبرم -ويقال إسحاق- بن داود بن سيف أركد؛ بسبب إغلاق المسلمين كنيسةَ القيامة بالقدس، وقَتَل عامة من كان في بلاده من رجال المسلمين، واسترقَّ نساءهم وأولادهم، وعذَّبهم عذابًا شديدًا، وهدم ما في مملكته من المساجد، وركِبَ إلى بلاد جبرت، فقاتلهم حتى هزمهم، وقتل عامة من كان بها، وسبى نساءهم، وهدم مساجدهم، فكانت في المسلمين ملحمة عظيمة في هذه السنة لا يُحصى فيها من قُتِلَ من المس"},{"id":3326,"era":"c9","t":"مقتل الأمير ناصر الدين محمد باك متملك بلاد قرمان .","s":"قُتلَ الأمير ناصر الدين محمد باك بن علي بن قرمان باك متملك بلاد قرمان في صفر بحجر مدفع أصابه في حرب مع عساكر مراد بن كرشجي متملِّك بورصا."},{"id":3327,"era":"c9","t":"الوباء في الشام ينتشر ويحصد الآلاف من الناس .","s":"بدأت هذه السنة والوباءُ يتزايد في الشام والموتى بالمئات، وبدأ يتزايد شيئًا فشيئًا، ثم في شهر رجب تناقص الوباء ببلاد الشام، بعدما عم كورة دمشق وفلسطين والساحل، وبلغت عدة من مات بصالحية دمشق زيادة على خمسة عشر ألف إنسان، وأُحصي من ورد ديوان دمشق من الموتى فكانوا نحو الثمانين ألفًا، وكان يموت من غزة في كل يوم مائة إنسان وأزيد، وكان معظم من مات الصغار والخدم والنساء، فخلت الدور منهم إلا قليلًا، وفي رج"},{"id":3328,"era":"c9","t":"قدوم جراد عظيم إلى المدينة النبوية أتلف عامة زروعها وأشجارها .","s":"قدم إلى المدينة النبوية جرادٌ عظيم أتلف عامَّةَ زروعها وأشجارها، حتى أكل الأسابيطَ -العذوق- من فوق النخل، فأمحلت ونزح كثيرٌ من أهلها، فمات معظم الفقراء النازحين جوعًا وعَطشًا."},{"id":3329,"era":"c9","t":"خراب في مدينة الكرك وقراها .","s":"في شَهرِ ربيع الآخر من هذا العام تلاشى أمر مدينة الكرك وخربت قراها, وتشتَّت أهلها، وآلت إلى الدُّثور."},{"id":3330,"era":"c9","t":"وفاة الحافظ الإمام قاضي القضاة أبي زرعة العراقي .","s":"هو الحافِظُ الإمام قاضي قضاة الديار المصرية، الإمام الحافظ، وأستاذ المحدِّثين، ولي الدين أبو زُرعة أحمد ابن الحافظ الكبير الشيخ زين الدين عبد الرحيم بن الحسين بن عبد الرحمن بن إبراهيم بن أبي بكر بن إبراهيم المعروف بابن العراقي الشافعي، كردي الأصل قاهري الولادة والنشأة والوفاة، وُلِدَ في ذي القعدة سنة 762، اعتنى به والده مبكرًا في صِغَرِه، فرحل به إلى الشام سنة خمس وستين، فأدرك جماعة من مُسنِدِي دم"},{"id":3331,"era":"c9","t":"وباء بمكة  .","s":"ابتدأ وباء بمكة من نصف ذي الحجة واستمر إلى آخر شهر ربيع الآخر من هذه السنة، فمات بها نحو ثلاثة آلاف نفس، وأنه كان يموت في اليوم خمسون إنسانًا عدة أيام، وأن الوباء تناقص من أوائل جمادى الأولى."},{"id":3332,"era":"c9","t":"خروج الأمير تنبك البجاسي نائب دمشق عن الطاعة وقتله .","s":"في رابع عشر شهر صفر قدم الخبر بخروج تنبك البجاسي عن الطاعة ومحاربته أمراء دمشق، وسبب ذلك أنه لما ولي سودن بن عبد الرحمن نيابة الشام عوضا عن تنبك، تقدمت الملطفات السلطانية إلى أمراء دمشق، بالقبض على تنبك البجاسي، فأتوا دار السعادة في ليلة الجمعة رابِعَه، واستدعوه ليقرأ عليه كتاب السلطان، فارتاب من ذلك، وخرج من باب السِّرِّ، وقد لبس السلاحَ في جمع من مماليكه، فثار إليه الأمراءُ واقتتلوا معه حتى مضى "},{"id":3333,"era":"c9","t":"سيل بمكة يصل إلى الكعبة .","s":"في ثالث جمادى الأولى جاء سيل عظيم حتى صار المسجد الحرام بحرًا، ووصل الماء إلى قريب من الحجر الأسود، وصار في المسجد أوساخ وخِرَق كثيرة جاء بها السيل، وأنَّ الخطبة أعيدت بمكة لصاحب اليمن في سابع جمادى الأولى بعدما تُرِك اسمه والدعاء له من أيام الموسِم."},{"id":3334,"era":"c9","t":"استيلاء الحفصيين على تلمسان ونهاية دولة بني عبد الواد بها .","s":"جهَّز أبو فارس عبد العزيز بن أبي العباس أحمد صاحب تونس وبلاد إفريقية وملك الحفصيين ابنَه المعتمد أبا عبد الله محمدًا، من بجاية في عسكر إلى مدينة تلمسان، فحارب مَلِكَها أبا عبد الله عبد الواحد بن أبي محمد عبد الله بن أبي حمو موسى ملك بني زيان حروبًا كثيرة، حتى ملكها في جمادى الآخرة، وخطب لنفسه ولأبيه، فزالت دولة بني عبد الواد من تلمسان بعدما ملكت مائة وثمانين سنة، وولَّى على تلمسان الأمير الزياني م"},{"id":3335,"era":"c9","t":"وفاة العلامة البزازي .","s":"هو العلامة البحر الزاخر المولى حافظ الدين محمد بن محمد بن شهاب بن يوسف الكردي البريقيني الخوارزمي الحنفي الشهير بالبزازي، برع في الأصول حتى ذاع صيته في البلاد، اشتهر بفتاويه وخاصة فتواه بتكفير تيمورلنك، وتُعرَف بالفتاوى البزازية، وله مصنفات؛ منها: مناقب الإمام الأعظم  أبي حنيفة، ومناسك الحج، وآداب القضاة، وتعريفات الأحكام، وغيرها من الكتب. قال عصام الدين طاشْكُبْري زادَهْ: \"له كتاب في مناقب الإمام"},{"id":3336,"era":"c9","t":"أحوال الشام ومصر الاقتصادية  .","s":"كانت أسواق القاهرة ومصر ودمشق في كساد، وظلمُ ولاة الأمر من الكشاف والولاة فاشٍ. ونواب القضاة قد شنعت قالة العامة فيهم من تهافتهم، وأرض مصر أكثرها بغير زراعة؛ لقصور مد النيل في أوانه، وقلة العناية بعمل الجسور؛ فإن كشَّافها إنما دأبهم إذا خرجوا لعملها أن يجمعوا مال النواحي لأنفسهم وأعوانهم، والطرقات بمصر والشام مخوفة من كثرة عبث العربان والعشير، والناس على اختلاف طبقاتهم قد غلب عليهم الفقر، واستولى "},{"id":3337,"era":"c9","t":"الشروع في عمل مراكب حربية لغزو بلاد الفرنج .","s":"في شهر محرم من هذا العام وقع الشروعُ في عمل مراكب حربية؛ لغزو بلاد الفرنج."},{"id":3338,"era":"c9","t":"أحوال دولة الترك المماليك مع مطلع هذا العام .","s":"أهلَّت هذه السنة وخليفةُ الوقت المعتضد بالله أبو الفتح داود بن المتوكل على الله أبي عبد الله محمد، وليس له من الخلافة إلا مجرد الاسم بلا زيادة. وسلطانُ مصر والشام والحجاز الملِكُ الأشرف برسباي الدقماقي، والأمير الكبير الأتابك قجق، والدوادار الكبير صاحب الأمر والنهي في الدوادارية بل في سائر أمور الدولة, وأمير سلاح أينال النوروزي، وأمير مجلس أينال الجكمي، وأمير أخور جقمق، ورأس نوبة تغري بردي المحمود"},{"id":3339,"era":"c9","t":"تغيير أمير مكة ومشاركة الأمير قرقماس في إمارة مكة .","s":"في سنة 827 تأخر الأمير قرقماس الدوادار في ينبع، وطلب عسكرًا ليقاتِلَ به الشريف حسن بن عجلان، ويستقر عِوَضَه في إمارة مكة، فأُجيب إلى ذلك، ثم خَلَع على الشريف علي بن عنان بن مغامس، واستقر في إمارة مكة شريكًا للأمير قرقماس، ثم قَدِمَ الخبر بوصول الشريف علي بن عنان إلى ينبع بمن معه من المماليك المجردين، وتوجه الأمير قرقماس معه إلى مكة، فدخلوها يوم الخميس سادس جمادى الأولى بغير حرب، وأن الشريف حسن بن "},{"id":3340,"era":"c9","t":"قدوم طائفة من الفرنج إلى صور وهزيمتهم .","s":"قَدِمَت طائفة من الفرنج إلى صور من معاملة صفد، فحاربهم المسلمون، وقتلوا كثيرًا منهم، وقُتِل من المسلمين نحو الخمسين رجلًا."},{"id":3341,"era":"c9","t":"السلطان الأشرف برسباي يجهز جيشًا لغزو قبرص ويأسر ملكها .","s":"أخذ السلطان في تجهيز الغزاة وعيَّن جماعة كبيرة من المماليك السلطانية والأمراء، وقام السلطان في الجهاد أتمَّ قيام، ثم في العشرين من هذا الشهر سارت خيول الأمراء والأعيان من المجاهدين في البر إلى طرابلس، وعِدَّتُها نحو ثلاثمائة فرس؛ لتحمل من طرابلس صحبة غزاتها في البحر، ثم في يوم الخميس تاسع شوال ورد الخبر من طرابلس بنصرة المسلمين على الفرنج، وبينما الناس مستبشرون في غاية ما يكون من السرور والفرح بنص"},{"id":3342,"era":"c9","t":"قتال بين الفرنج القطرانيون وبين البنادقة في ميناء الإسكندرية .","s":"اقتتل الفرنج القطرانيون والبنادقة في ميناء الإسكندرية، فغلب القطرانيون وأخذوا مركب البنادقة بما فيه، بعدما قُتِل بينهم جماعة، ثم أسروا طائفة من المسلمين كانوا بالميناء، ومَضَوا في البحر."},{"id":3343,"era":"c9","t":"نزوح بعض أهل المدينة النبوية منها بسبب إهمالها .","s":"في شهر ربيع الآخر قَدِمَ الخبر بتشتت أهل المدينة النبوية، وانتزاحهم عنها؛ لشدة الخوف وضياع أحوال المسجد النبوي، وقلة الاهتمام بإقامة شعائر الله فيه، منذ كانت كائنة المدينة، فرُسِم الأمير بكتمر السعدي أحد أمراء العشرات إلى المدينة فأخذ في تجهيز حالِه."},{"id":3344,"era":"c9","t":"خلع الملك محمد التاسع الأيسر ملك بني نصر بالأندلس .","s":"كان صاحب غرناطة ومالقة والمرية ورندة ووادي آش وجبل الفتح من الأندلس، وهو أبو عبد الله محمد التاسع الملقَّب بالأيسر ابن السلطان أبي الحجاج يوسف الأنصاري الخزرجي الأرجوني الشهير بابن الأحمر- قد خرج من غرناطة دار ملكه يريد النزهةَ في فحص غرناطة في نحو مائتي فارس في مستهَلِّ ربيع الآخر، وكان ابن عمه أبو عبدالله محمد الثامن بن نصر بن محمد بن يوسف محبوسًا في الحمراء، وهي قلعة غرناطة، فخرج الجواري السُّو"},{"id":3345,"era":"c9","t":"وفاة الملك المنصور عبد الله ابن رسول ملك اليمن وتولي أخيه .","s":"هو الملك المنصور عبد الله بن الناصر أحمد بن الأشرف إسماعيل بن الأفضل عباس بن المجاهد علي بن المؤيد داود بن المظفر يحيى بن المنصور عمر بن علي بن رسول متملك اليمن, وهو تاسع حكَّام دولة بني رسول باليمن، وحكم سنة واحدة فقط من 829 إلى 830. توفِّي في جمادى الأولى، وأُقيم مِن بَعدِه أخوه الأشرف إسماعيل."},{"id":3346,"era":"c9","t":"سلطان العثمانيين مراد الثاني يحارب الروم النصارى .","s":"في شهر شوال قدم الخبر بأن السلطان العثماني مراد الثاني بن محمد بن بايزيد الأول، صاحب بورصا من بلاد الروم، جمع قواتِه بقيادة علي بك أحد أمرائه لمحاربة الأنكرس -من طوائف الروم المتنصرة- فهُزم فيها علي بك، واستُشهِدَ جمع وافر من عسكرِه."},{"id":3347,"era":"c9","t":"خلع أمير المدينة الشريف خشرم بن دوغان وتولية الشريف مانع .","s":"في الرابع والعشرين ذي الحجة قُبض بالمدينة النبوية على أميرها الشريف خشرم بن دوغان بن جعفر بن هبة الله بن جماز بن منصور بن جماز بن شيحة؛ لأنه لم يقم بالمبلغ الذي وعد به، وقُرِّر عِوَضًا عنه الشريف مانع بن علي بن عطية بن منصور بن جماز بن شيحة بن هاشم بن قاسم بن مهنا بن حسين بن مهنا بن داود بن قاسم بن عبد الله بن طاهر بن يحيى بن الحسين بن جعفر بن الحسين بن علي بن الحسين بن علي بن أبي طالب."},{"id":3348,"era":"c9","t":"السلطان الأشرف برسباي يصدر مرسومًا خاصًّا بالحرم المكي .","s":"قُرئ مرسوم السلطان الأشرف برسباي بمكة المشرفة في الملأ بمنْعِ الباعة من بَسطِ البضائع أيام الموسم في المسجد الحرام، ومِن ضَرْبِ الناسِ الخيامَ بالمسجد الحرام على مصاطبه وأمامها، ومن تحويل المنبر في يوم الجمعة والعيدين من مكانه إلى جانب الكعبة حتى يُسنَدَ إليها، فأُمِرَ أن يُتركَ مكانَه مُسامتًا لمقام إبراهيم الخليل عليه السلام، ويَخطُبَ الخطيب عليه هناك، وأمر أن تُسَدَّ أبواب المسجد بعد انقضاء الم"},{"id":3349,"era":"c9","t":"ارتفاع أسعار الغلال لقلة المطر وهبوب الرياح وأمراض بالشام .","s":"في آخر هذا الشهر ارتفعت أسعار الغلال، وسببه خِسَّة الزرع بالجيزية والوجه البحري؛ لعدم المطر، وتوالي هبوب الرياح المريسية زيادة على ثلاثين يومًا، فلم تَسِرْ فيها المراكب. وأهلَّ شهر ربيع الآخر والناس على تخوُّف من سوء حال الزرع، وانكشاف ساحل النيل من الغلال وقلة وجود القمح, وبعد أيام قَدِمَت الأخبار بكثرة أمراض أهل الشام، وكثرة موت الخيول بدمشق وحماة!"},{"id":3350,"era":"c9","t":"خلع الملك الأشرف إسماعيل ملك اليمن وتولي عمه الظاهر يحيى .","s":"في شهر جمادى الأولى كانت الفتنة الكبيرة بمدينة تعز من بلاد اليمن؛ وذلك أن الملك المنصور عبد الله بن أحمد لما توفي في جمادى الأولى السنة الفائتة، أقيم بعده أخوه الملك الأشرف إسماعيل بن أحمد الناصر بن الملك الأشرف إسماعيل بن عباس، فتغيَّرت عليه نيات الجند كافةً؛ من أجل وزيره شرف الدين إسماعيل بن عبد الله بن عبد الرحمن بن عمر العلوي، نسبةً إلى علي بن بولان العكي؛ فإنه أخَّر صرف جوامكهم -مخصَّصاتهم- و"},{"id":3351,"era":"c9","t":"مقتل الخواجا مبعوث ملك الحبشة إلى الفرنج للهجوم على الإسلام .","s":"عُثِر على أحد تجار العجم، وهو الخواجا نور الدين علي التبريزي العجمي المنتمي إلى الإسلام، وقد توجه من عند الحطي ملك الحبشة إلى الفرنج يحثهم على القيام معه لإزالة دين الإسلام وأهله، وإقامة الملة العيسوية؛ فإنه قد عزم على أن يسير من بلاد الحبشة في البر بعساكره، فتلاقوه بجموعهم في البحر إلى سواحل بلاد المسلمين، فسلك هذا التاجر الفاجر في مسيره من الحبشة البرية حتى صار من وراء الواحات إلى وراء المغرب، و"},{"id":3352,"era":"c9","t":"العسكر المصري والشامي يستولي على الرها ويخربها .","s":"سار عسكر المماليك من القاهرة لأخذ قلعة خرت برت، وقد مات متوليها، ونازلها عسكرُ قرا يلك صاحب آمد، فلما وصلوا إلى مدينة حلب ورد إليهم الخبر بأخذ قرا يلك قلعة خرت برت وتحصينها، وتسليمها لولده، فتوجه العسكر وقد انضم إليه الأمير سودن بن عبد الرحمن نائب الشام، وجميع نواب المماليك الشامية، ومضوا بأجمعهم إلى الرها، فأتاهم بالبيرة كتابُ أهل الرها بطلب الأمان، وقد رَغِبوا في الطاعة، فأمَّنوهم وكتبوا لهم به "},{"id":3353,"era":"c9","t":"الأمير محمد الزياني أمير تلمسان يخرج عن طاعة الحفصيين .","s":"كان أمير فاس أبو فارس عبد العزيز قد عيَّن الأمير محمد بن أبي تاشفين الزياني أميرًا على تلمسان بعد أن تملَّكها من المرينيين، ثم إنَّ محمدًا الزياني رأى أن يعلِنَ استقلاله فيها، فأعلن خروجه عن طاعة السلطان الحفصي أبي فارس، الذي سار من وقته فحاصر تلمسان، فهرب منها الأمير محمد الزياني، ولكن لم يلبث أن قُبِضَ عليه واعتُقِلَ، فحمله أبو فارس معه إلى فاس وسجنه هناك حتى توفي في سجنه من السنة التالية."},{"id":3354,"era":"c9","t":"شاه رخ بن تيمورلنك يخرب مدينة توريز وهروب ملكها إسكندر .","s":"عندما زحف إسكندر بن قرا يوسف قرا محمد بين بيرم خجا متملك توريز على مدينة السلطانية، وقتل متولِّيَها من جهة ملك المشرق شاه رخ بن تيمور كركان في عدة من أعيانها، ونهَب وأفسد، فسار إليه شاه رخ بن تيمور في جموع كبيرة، فخرج إسكندر بن قرا يوسف من توريز، وجمع لحربه، ولقيه وقد نزل خارج توريز، فانتدب لمحاربته الأمير قرا يلك صاحب آمد، وقد لحق بشاه رخ، وأمدَّه بعسكر كبير، وقاتله خارج توريز في يوم الجمعة سابع "},{"id":3355,"era":"c9","t":"وفاة الإمام الحافظ شمس الدين ابن الجزري .","s":"هو الإمامُ الحافظ شمس الدين محمد بن محمد بن محمد بن علي بن يوسف الشافعي شيخ القراء، ومُقرِئ الممالك الإسلامية، الشهير بابن الجزري نسبة إلى جزيرة عُمر. ولد بدمشق ليلة السبت الخامس والعشرين من شهر رمضان سنة 751، وتفقَّه بها، ولهج بطلب الحديث والقراءات، وبرَّز فيهما، وعَمر للقراءِ مدرسةً سمَّاها: دار القرآن، وأقرأ الناس، وقدم القاهرة مرارًا، وكان حسن الشَّكلِ، ثريًّا فصيحًا بليغًا، وكان باشر عند قطلب"},{"id":3356,"era":"c9","t":"انتصارات مراد الثاني في استعادة المناطق التي فقدتها الدولة العثمانية .","s":"أراد السلطان مراد الثاني بن محمد جلبي أن يعيد الإمارات في الأناضول إلى سيادة الدولة العثمانية بعد عدوان تيمورلنك على تلك المنطقة؛ ولذلك عقد هدنة مع ملك المجر لمدة خمس سنوات، كما صالح أمير القرامان، وبدأ يتجه لأوروبا مستأنفًا حركة الجهاد ومؤدبًا للأوربيين الذين أساؤوا للعثمانيين أيام المحنة التي حلَّت بهم أيام السلطان بايزيد. وفتح المجر وأخذ الجزية من أمير الصرب مع تقديم فرقة من جنود الصرب لمساعدة "},{"id":3357,"era":"c9","t":"خلع الملك محمد الثامن الصغير وعودة محمد التاسع الأيسر .","s":"قام الملك محمد الثامن الملقب بأبي عبد الله الصغير بطرد الوزير يوسف سراج الدين الذي لجأ إلى ملك قشتالة ودبَّر معه رد المُلْكِ إلى محمد التاسع الملقب بالأيسر الذي خُلِعَ سنة 831، فقام الوزير المذكور باستدعاء محمد التاسع الأيسر من تونس حيث كان لاجئًا عند ملك فاس فلبى الدعوة وعاد إلى الأندلس، فزوده ملك قشتالة بالفرسان والهدايا، فورد الخبر إلى الملك محمد الثامن أبي عبد الله الصغير الذي أرسل قواتِه لقتا"},{"id":3358,"era":"c9","t":"ملك الحفصيين يرسل جيشًا يغزو صقيلية .","s":"في ثامن عشر محرم بعث صاحب تونس وإفريقية وتلمسان أبو فارس عبد العزيز ملك الحفصيين أسطولًا فيه مائتا فرس، وخمسة عشر ألف مقاتل من العسكرية والمطوعة؛ لأخذ جزيرة صقلية، فنازلوا مدينة مارز حتى أخذوها عنوة، ومضوا إلى مدينة مالطة، وحصروها حتى لم يبق إلا أخذها، فانهزم من جملتِهم أحد الأمراء من العلوج، فانهزم المسلمون لهزيمته، فركب الفرنج أقفيتهم، فاستُشهِد منهم في الهزيمة خمسون رجلًا من الأعيان، ثم إنهم ثب"},{"id":3359,"era":"c9","t":"انتشار الطاعون في مصر والشام وبلاد الروم .","s":"فشا الطاعون في الوجه البحري، سيما في التحريرية ودمنهور، فمات خلق كثير جدًّا بحيث أحصي من مات من أهل المحلة زيادة على خمسة آلاف إنسان، ومن ناحية بورصا زيادة على ستمائة إنسان، وكان قد وقع بغزة والقدس وصفد ودمشق في شعبان في السنة الماضية طاعون، واستمر إلى هذا الشهر، وعُدَّ هذا من النوادر؛ فإن الوقت شتاء، وما عهد فيما أدركناه وقوع الطاعون إلا في فصل الربيع! ويعلل الأطباء ذلك بسيلان الأخلاط في الربيع، "},{"id":3360,"era":"c9","t":"جفاف وخراب بالعراق .","s":"وقع بعراقي العرب والعجم نهوب وغارات وقتال، بحيث إن شاه محمد بن قرا يوسف متملك بغداد مِن عَجزِه لا يتجاسر على أن يتجاوز سورَ بغداد، وخلا أحد جانبي بغداد من السكان، وزال عن بغداد اسم التمدُّن، ورحل عنها حتى الحيات، وجفَّ أكثر النخل من أعمالها!!"},{"id":3361,"era":"c9","t":"ملك قشتالة يهاجم بني نصر في غرناطة .","s":"جمَعَ مَلِكُ قشتالة الفونسو عساكِرَه من الفرنج، وركب البحرَ إلى قرطبة يريد أخذ غرناطة من المسلمين، فاشتدَّ البلاء عليهم؛ لقلة المال بغرناطة، وفناء عسكرها في الفتنة التي حصلت في استعادة الملك، وموت من هلك في الزلزلة أكثر من ستة آلاف إنسان، ونزل الفرنج عليهم، فلقُوهم في يوم الجمعة عاشر رمضان من هذه السنة، وقاتلوهم يومهم ومن الغد، قُتِلَ من المسلمين نحو الخمسة عشر ألفًا، وألجأهم العدو إلى دخول المدين"},{"id":3362,"era":"c9","t":"معاهدة ذل للمسلمين مع القشتاليين في الأندلس .","s":"بعد مؤامرة خلع أبي عبد الله محمد الملقب بالأيسر حاكم غرناطة -في فترة حكمه الثانية- والتي قام بها خصومه، وتولِّي أبي الحجاج يوسف بن المول الحكم، والذي كان مائلًا إلى ملك قشتالة ليساعده على انتزاع حكم غرناطة في مقابل تعهُّده بأن يحكم غرناطة باسم ملك قشتالة وتحت طاعته، تم بعد ذلك توقيعُ معاهدة بين يوسف بن المول وخوان الثاني ملك قشتالة؛ لتحقيق هذا الهدف في 7 محرم سنة 835 (16 سبتمبر 1431م) متضمنة بنودً"},{"id":3363,"era":"c9","t":"الفرنج يهاجمون جزيرة جربة ويأخذونها من الحفصيين .","s":"نزل الطاغية النشو بن دون فرنادو بن أندريك بن جوان بن فدريك بن أندريك ملك الفرنج الكيتلان، وصاحب برشلونة، على جزيرة صقلية في شهر رمضان، وسار ومعه صاحب صقلية في نحو مائتي قطعة بحرية حتى أرسى على جربة في سابع عشر ذي الحجة وملكها، وكان ملك المغرب أبو فارس عبد العزيز غائبًا عن تونس في جهات تلمسان، فلما بلغه تَرَك معظم عسكره وسار على الصحراء حتى دنا من جربة، وكانت بينه وبين الفرنج وقعةٌ كاد يُؤخَذُ فيها"},{"id":3364,"era":"c9","t":"الفرنج يتخطفون سفن المسلمين التجارية في الشام ومصر .","s":"طَرَقَ الفرنجُ ميناء طرابلس الشام في يوم السبت عاشِرَه، وأخذوا مركبًا فيه عدد كثير من المسلمين، وبضائع لها قيمة جليلة، وبينما هم في ذلك إذ قَدِمت مركب من دمياط فأخذوها أيضًا بما فيها وساروا، فلما ورد الخبر بذلك كتب بإيقاع الحوطة على أموال الفرنج الجنوية والكيتلان دون البنادقة، فأحيط بأموالهم التي بالشام والإسكندرية."},{"id":3365,"era":"c9","t":"السلطان الأشرف برسباي يجبر قرا يلك صاحب آمد على الصلح .","s":"كان السلطان الأشرف برسباي قد تجهز للسفر إلى جهة آمد من هذه السنة، وسبب ذلك أن قرا يلك مَلِك آمد أظهر أولًا أنه يريد الطاعة لَمَّا كان ابنه هابيل في قبضة السلطان من أيام تملُّك الرها، ثم لما مات هابيل بالطاعون لم يعُدْ قرا يلك يُلقي بالًا للسلطان، بل عدا على ملطية وغيرها من البلاد، وأحرق وأفسد، وكان السلطان في السنوات الماضية يُشيعُ أنه يريد السفر لقتاله؛ لعل قرا يلك يُرعَب منه فيطلب الصلح، ولكنه ل"},{"id":3366,"era":"c9","t":"أصبهان بن قرا متملك بغداد يخلي بغداد والموصل من السكان .","s":"لَمَّا أخذ أصبهان بن قرا يوسف بغدادَ من أخيه شاه محمد بن قرا يوسف أساء السيرةَ؛ بحيث إنه أخرج جميع من ببغداد من الناس بعيالهم، وأخذ كل مالهم من جليل وحقير، فتشتَّتوا بنسائهم وأولادهم في نواحي الدنيا، وصارت بغداد وليس بها سوى ألف رجل من جند أصبهان بن قرا يوسف، لا غير، وليس بها إلا ثلاثة أفران تخبز الخبز فقط، ولم يبقَ بها سكان ولا أسواق، وأنه أخرب الموصل حتى صارت يبابًا، فإنه سلب نعِمَ أهلها، وأمر ب"},{"id":3367,"era":"c9","t":"سيل عظيم بمكة يغرق أرض المسجد الحرام بالطين ويهدم الدور .","s":"في ليلة الجمعة السادس والعشرين جمادى الأولى وقع بمكة المشرفة مطر غزير، سالت منه الأودية، وحصل منه أمر مهول على مكة؛ بحيث صار الماء في المسجد الحرام مرتفعًا أربعة أذرع، فلما أصبح الناس يوم الجمعة ورأوا المسجد الحرام بحر ماء، أزالوا عتبة باب إبراهيم، حتى خرج الماء من المسفلة، وبقي بالمسجد طين في سائر أرضه قَدْر نصف ذراع في ارتفاعه، فانتدب عدة من التجار لإزالته، وتهدم في الليلة المذكورة دور كثيرة، يق"},{"id":3368,"era":"c9","t":"وفاة السلطان عبد العزيز ملك الحفصيين وتولي حفيده المنتصر محمد .","s":"هو السلطانُ أبو فارس عبد العزيز بن أبي العباس أحمد بن محمد بن أبي بكر بن يحيى بن إبراهيم بن يحيى بن عبد الواحد بن عمر بن ونودين الهنتاتي الحفصي ملك المغرب. وَلِيَ الأمر بعد والده أبي العباس سنة 796, فوزع الوظائِفَ من الإمارة والوزارة وولاية الأعمال على إخوته، فاعتضد بهم، وكان من جملتهم أخوه أبو بكر بن أبي العباس بقسنطينة، فنازعه بها ابن عمه الأمير أبو عبد الله محمد بن أبي زكريا الحفصي صاحب بونة، و"},{"id":3369,"era":"c9","t":"وفاة السلطان أبو المغازي ملك كلبرجة بالهند وتولى ابنه أحمد .","s":"هو السلطان شهاب الدين أبو المغازي أحمد شاه بن أحمد بن حسين شاه بن مهمن شاه ملك كلبرجة من بلاد الهند، وكان من خير ملوك تلك البلاد عدلًا وفضلًا وسياسة، له مآثر بمكة معروفة، أقام في الملك أربع عشر سنة، ثم قام بعده ابنه أحمد الملقَّب ظفر شاه."},{"id":3370,"era":"c9","t":"قتال بين الأعراب وبين الحفصيين .","s":"قَوِيَ عرب إفريقية وحصروا مدينة تونس؛ وذلك أن المنتصر أبا عبد الله محمد بن الأمير أبي عبد الله محمد بن السلطان أبي فارس عبد العزيز، لما قام في سلطنة أفريقية بعد موت جده أبي فارس عبد العزيز بن أبي العباس أحمد، عندما كان المنتصر في سفره بنواحي تلمسان، قدم إلى مدينة تونس دار ملكه في يوم عاشوراء، وأقام بها أيامًا، ثم خرج إلى عمرة، ونزل بالدار التي بناها جده أبو فارس، وضيق على العرب ومنعهم من الدخول إل"},{"id":3371,"era":"c9","t":"وقوع وباء عظيم ببلاد كرمان .","s":"وقع وباء عظيم ببلاد كرمان، وكان ابتداؤه في مدينة هراة من بلاد خراسان في شهر ربيع الأول، وشنع واشتد، فمات فيه عالمٌ عظيم، يقول المكثر: ثمانمائة ألف!"},{"id":3372,"era":"c9","t":"وفاة الأمير سيف الدين طراباي نائب طرابلس .","s":"هو الأمير سيف الدين طراباي نائب طرابلس, وهو أحد المماليك الظاهرية برقوق، وممن نبغ بعد موت برقوق واشتهر ذكره، ثم خرج عن طاعة الناصر فرج فيمن خرج وتنقَّل في أطوار من المحن إلى أن صار من أعظم الأمراء بديار مصر، ثم سُجِنَ عدة سنين بالإسكندرية في الأيام الأشرفية، ثم أُفرِجَ عنه وعمل في نيابة طرابلس، وكان عفيفًا عن القاذورات متدينًا. توفي بكرة نهار السبت رابع شهر رجب من غير وعكٍ ولا تقدُّم مرض، بل صلى ا"},{"id":3373,"era":"c9","t":"فتح عدة مدن من بلاد الحطي ملك الحبشة .","s":"بعث الملك شهاب الدين أحمد بدلاي بن سعد الدين سلطان المسلمين بالحبشة أَخاه خير الدين لقتال أهل أمحرة الكَفَرة بالحبشة، ففتح عدة بلاد من بلاد الحطي ملك الحبشة، وقتل أميرين من أمرائه، وغنم مالًا عظيمًا، وأكثر من القتل في أمحرة النصارى، وأخرب لهم ستَّ كنائس، وكان الوباء العظيم قد شنع بعامَّة بلاد الحبشة، ومات فيه من المسلمين والكفّار عالم لا يُحصى حتى كادت أن تخلو البلاد، بل خلا الكثير منها. وكان هلك "},{"id":3374,"era":"c9","t":"خروج عثمان قرا يلك على السلطان بمصر .","s":"ورد الخبر باتصال جانبك الصوفي بابن قرا يلك، وأنه بمدينة كماخ، وأنَّ قرا يلك سُرَّ به وجهَّز إليه بالخيل والمال، وأمدَّه بأشياء كثيرة، فزاد انزعاج السلطان وأهل الدولة بهذا الخبر, فأرسل السلطان إسكندر بن قرا يوسف لقتال عثمان قرا يلك, فجمع عثمان عسكره ولقي إسكندر فاقتتلا، فخرج كمين لإسكندر على عثمان، فانهزم وقصد أرزن الروم والخيل في طلبه. فلما خاف عثمان أن يُؤخَذ باليد رمى نفسه في خندق المدينة فغرق، "},{"id":3375,"era":"c9","t":"وفاة السلطان المنتصر محمد ملك الحفصيين وقيام أخيه عثمان .","s":"هو السلطانُ المنتصر أبو عبد الله محمد بن أبي عبد الله محمد بن أبي فارس ملك تونس وبلاد إفريقية من الغرب، تولى الملكَ بعد وفاة جَدِّه أبي فارس عبد العزيز بن أحمد سنة 837, وقام بمملكة تونس من بعده أخوه أبو عمرو عثمان، فقَتَل عدة من أقاربه وغيرهم، وكان من خبر المنتصر مع أخيه أبي عمر: أنه لما ثقل في مرضه حتى أقعد، وصار إذا سار يركب في عمَّاريَّة نوع من المحامل تُحمَل على بغل- وتردد كثيرًا إلى قصر بخارج"},{"id":3376,"era":"c9","t":"العسكر المصري يقاتل دلغار نائب أبلستين الخارج عن الطاعة  .","s":"توجَّه العسكر المجرَّد من مصر إلى حلب، وسار منها نائبها تغري برمش البهسني بعساكر حلب، وصحبته الأمير قاني باي الحمزاوي نائب حماة بعساكر حماة، ونزل على عينتاب؛ لقتال دلغادر نائب أبلستين, وقد نزل جانبك الصوفي مرغش، فتوجهوا إليه من الدربند, ونزلوا على بزرجق يعني سويقة باللغة العربية- ثم عدَّوا الجسر، وقصدوا ناصر الدين بك دلغادر نائب أبلستين من طريق دربند كينوك، فلم يقدروا على سلوكه؛ لكثرة الثلوج، فمضو"},{"id":3377,"era":"c9","t":"العسكر المصري يقاتل أولاد دلغار نائب أبلستين الخارج عن الطاعة .","s":"بلغ تغري برمش البهسني نائب حلب بعد قدومه من أبلستين إلى حلب أن ناصر الدين بن دلغادر نزل بالقرب من كينوك، فجهَّز إليه أخاه حسنًا حاجب حجَّاب حلب، وحسن هو الأسنُّ، ومعه مائة وخمسون فارسًا إلى عينتاب؛ تقويةً للأمير خجا سودون، وقد نزل بها بعد أن انفرد عن العسكر المصري من يوم خرج من الديار المصرية، فتوجَّه حسن بمن معه إلى خجا سودون وأقام عنده، فلما كان يوم الرابع والعشرين ذي الحجة من سنة تسع وثلاثين وص"},{"id":3378,"era":"c9","t":"الفرنج يحاولون سرقة مراكب المسلمين في الإسكندرية .","s":"في الحادى والعشرين محرم طرق ميناءَ بوقير خارجَ مدينة الإسكندرية ثلاثةُ أغربة -نوع من المراكب- من الفرنج الكيتلان، وأخذوا مركبين للمسلمين، فخرج إليهم أقباي اليشبكي الدوادار نائب الثغر، ورماهم حتى أخذ منهم أحد المركبين، وأحرق الفرنج المركبَ الآخر وساروا، وفي الثاني والعشرين منه بعد هذه الوقعة طرق ميناءَ الإسكندرية مركبٌ آخر للكيتلان، وكان بها مركب للجنوية، فتَحاربا، وأعان المسلمون الجنوية حتى انهزم "},{"id":3379,"era":"c9","t":"أبو الحسن عم ملك الحفصيين يحاصر قسنطينة ويحاربه الملك عثمان .","s":"في محرم خرج من مدينة بجاية بإفريقية أبو الحسن علي ابن السلطان أبى فارس عبد العزيز ملك الحفصيين، حتى نزل على قسنطينة، وحصرها، ثم في شهر صفر سار أبو عمرو عثمان بن أبي عبد الله محمد ابن السلطان أبى فارس عبد العزيز من مدينة تونس يريد قسنطينة؛ لقتال عمه أبي الحسن علي."},{"id":3380,"era":"c9","t":"وفاة إمام الزيدية المنصور نجاح الدين علي صاحب صنعاء .","s":"هو الإمامُ المنصور نجاح الدين أبو الحسن علي بن صلاح بن علي بن محمد بن علي بن أحمد بن منصور بن حجَّاج بن يوسف الحسني، الرسي المدعو بأمير المؤمنين، إمامُ الزيدية ورأسُهم. صاحبُ صنعاء باليمن، أقام في الإمامة بعد أبيه ستًّا وأربعين سنة وثلاثة أشهر، وأضاف إلى صنعاء وصعدة عدة من حصون الإسماعيلية، أخذها منهم بعد حروب وحصار. مات في سابع صفر،  فقام بعده ابنه الإمام الناصر صلاح الدين محمد بعهده إليه وبيعة ا"},{"id":3381,"era":"c9","t":"طاعون حاد في الشام .","s":"كثُرَ الوباء بالطاعون بحلب وأعمالها، حتى تجاوزت عدة الأموات بمدينة حلب في اليوم مائة، وفي شهر ربيع الآخر شنع الوباء بحماة، حتى تجاوزت عدة الأموات عندهم في كل يوم ثلاثمائة إنسان، ولم يعهدوا مثل ذلك في هذه الأزمنة، وفي شهر جمادى الأولى فشا الموت في الناس بمدينة حماة وأعمالها، حتى تجاوز عدة من يموت في كل يوم مائة وخمسين إنسانًا، وفي شهر جمادى الآخرة وقع الوباء بدمشق، وفشا الموت بالطاعون الوحى، ثم كثر"},{"id":3382,"era":"c9","t":"وقعة بين النصارى البرتغال وبين المسلمين في مدينة سبتة .","s":"قدم الخبرُ بأن ملك البرتغال صاحب مدينة شلب من الأندلس سار يريد مدينة طنجة، فنزل على سبتة في المحرم، ومضى منها وهى بيده في البر والبحر، ومعه فيما يقال ثمانية عشر ألف رامٍ، وستة آلاف فارس، حتى نزل على طنجة فحصرها مدة شهر إلى أن أتته جموع المسلمين من فاس ومكناسة وأصيلا في شهر ربيع الآخر، فكانت بينهم وبين البرتغال من النصارى حروب عظيمة، نصر الله فيها المسلمين، وقُتِل نحو الثلثين من النصارى، والتجأ باق"},{"id":3383,"era":"c9","t":"فتنة بين العبيد وبين مماليك السلطان في مصر .","s":"جرت في ليلة الاثنين ويوم الاثنين خامس رجب شنائع؛ وذلك أن مماليك السلطان سكان الطباق بالقلعة نشؤوا على مقت السلطان لرعيَّته، مع ما عندهم من بغض الناس، فنزل كثير منهم في أول الليل، وأخذوا في نهب الناس، وخَطْف النساء والصبيان للفساد، واجتمع عدد كثير من العبيد السود، وقاتلوا المماليك، فقُتِلَ من العبيد خمسة نفر، وجُرِح عدة من المماليك، وخُطِف من العمائم وأخذ من الأمتعة شيء كثير، فكان ذلك من أقبح ما سُ"},{"id":3384,"era":"c9","t":"طاعون حاد في مصر .","s":"في هذا الشهر وقع الوباء بالطاعون ببلاد الصعيد من أرض مصر، وفي شهر رمضان كانت عدة الأموات التي رُفِعت بها أوراق مُباشِري ديوان المواريث بالقاهرة ثمانية عشر إنسانًا، وتزايدت عدتُهم في كل يوم حتى فشا في الناس الموتُ بالطاعون في القاهرة ومصر، لا سيما في الأطفال والإماء والعبيد؛ فإنهم أكثر من يموت موتًا سريعًا، ثم شنعت الأخبار بكثرة من يموت، وسرعة موتهم، وشناعة الموتان أيضًا ببلاد الواحات من أرض مصر، و"},{"id":3385,"era":"c9","t":"هدم دير المغطس للنصارى في مصر .","s":"في هذا الشهر شعبان هُدِمَ للنصارى دير المغطس عند الملاحات، قريبًا من بحيرة البرلس، وكانت نصارى الإقليم قبليًّا وبحريًّا تحج إلى هذا الدير كما يحجون إلى كنيسة القيامة بالقدس، وذلك في عيده من شهر بشنس، ويسمونه عيد الظهور."},{"id":3386,"era":"c9","t":"وفاة السلطان الأشرف برسباي وقيام ابنه العزيز يوسف .","s":"هو السلطانُ الملك الأشرف سيف الدين أبي النصر برسباي الدقماقي الظاهري، سلطان الديار المصرية، جركسي الأصل، اشتراه الأمير دقماق المحمدي الظاهري نائب ملطية، وأقام عنده مدة، ثم قدَّمه إلى الملك الظاهر برقوق, وهو السلطان الثاني والثلاثون من ملوك دولة الترك المماليك، والثامن من الجراكسة بالديار المصرية، وقد تولى السلطنة بمصر سنة 825 وفتح مدينة قبرص وأنشأ بمصر مدرسة وجامعًا بسرياقوس, كان سلطانًا جليلًا سي"},{"id":3387,"era":"c9","t":"حصار آقشهر وأرزكان وعودهما إلى الطاعة .","s":"قَدِمَ الخبر بأن إسكندر بن قرا يوسف نزل قريبًا من مدينة تبريز، فبرز إليه أخوه جهان شاه، المقيم بها من قِبَل القان معين الدين شاه رخ بن تيمورلنك المغولي ملك المشرق، فكانت بينهما وقعة انهزم فيها إسكندر إلى قلعة يلنجا من عمل تبريز، فنازله جهان شاه وحصره بها، وأن الأمير حمزة بن قرا يلك متملك ماردين وأرزنكان أخرج أخاه ناصر الدين علي باك من مدينة آمد، وملكها منه، فقلق السلطان من ذلك، وعزم على أن يسافر ب"},{"id":3388,"era":"c9","t":"خلع السلطان العزيز يوسف وتسلطن الأمير جقمق .","s":"بعد أن أصبح السلطان العزيز يوسف بن برسباي سلطانًا أصبح الأمير الكبير جقمق هو نظام الملك؛ فله الأمر والنهي، وبيده كل شيء، وليس للسلطان سوى الاسم، وكان في هذه السنة حصلت فتن بين المماليك الأشرفية التابعين للسلطان، وبين الأمير جقمق ومن معه من الأمراء والمماليك الظاهرية والمؤيدية، فعزز الأمير جقمق مركزه وعلا شأنُه، حتى لما كان يوم الأربعاء التاسع عشر ربيع الأول قام الأمير الكبير جقمق بخلع السلطان العز"},{"id":3389,"era":"c9","t":"فتنة الأمير الكبير قرقماس ومحاولة خلع السلطان الظاهر جقمق .","s":"بعد أن تسلطن الظاهر جقمق أصبح الأمير قرقماس هو أتابك العساكر وهو الأمير الكبير، ثم في ربيع الآخر ثارت عدة من المماليك القرانصة الذين قاموا مع السلطان العزيز يوسف بن برسباي قبل ذلك على الأشرفية، وطلبوا الآن من السلطان الزيادة في مرتباتهم، فنزل إليهم الأمير قرقماس ووعدهم بأن يكلم السلطان بذلك، ولكنهم أبوا إلَّا أن يقاتلوا السلطان واستطاعوا أن يقنعوا الأمير قرقماس بأن يكون معهم ضِدَّ السلطان، فلبسوا "},{"id":3390,"era":"c9","t":"وفاة محدث الشام شمس الدين ابن ناصر الدين الدمشقي .","s":"هو الشيخ الإمام الحافظ محدث الشام شمس الدين أبو عبد الله محمد بن أبى بكر بن عبد الله بن محمد بن أحمد بن مجاهد بن يوسف بن محمد بن أحمد بن علي، المعروف بابن ناصر الدين القيسي الحموي الدمشقي الشافعي. ولد بدمشق سنة 777, طلب الحديث، فصار حافظ بلاد الشام من غير منازع، ووليَ مشيخة دار الحديث بالأشرفية, وصنَّف عدة مصنَّفات؛ منها: تحفة الإخباري بترجمة صحيح البخاري، وعقود الدرر في علوم الأثر، والرد الوافر ف"},{"id":3391,"era":"c9","t":"وفاة الظاهر عبد الله بن الأشرف ملك اليمن وتولي ابنه الأشرف .","s":"هو المَلِكُ الظاهر هزبر الدين عبد الله بن الأشرف إسماعيل بن علي بن داود بن يوسف بن عمر بن علي بن رسول ملك اليمن. ضعفت مملكة اليمن في أيامه؛ لقلة مجابي أموالها، واستيلاء العربان على أعمالها. مات يوم الخميس آخر شهر رجب، وله في الملك نحو اثنتي عشرة سنة، وأقيم بعده ابنه الأشرف إسماعيل، وله من العمر نحو العشرين سنة، فأكثر من سفك الدماء، وأخْذ الأموال، وغير ذلك من أنواع الفساد!"},{"id":3392,"era":"c9","t":"خروج الأمير تغري برمش والأمير إينال الجكمي عن الطاعة وقتلهما .","s":"أول من بدأ بالعصيان على السلطان هو تغري برمش الذي استطاع أن يستحوذ على حلب وأعلن عصيانه، فقام السلطان بإنابة غيره على حلب، وبعث بعض الأمراء لتولية الأمراء النواب الجدد، وكانت الأخبار تَرِدُ أن نائب دمشق الأمير إينال الجكمي أيضًا يريد الخروج عن الطاعة، لكن أمره لم يتحقق إلى أن كان يوم الاثنين تاسع رمضان، كان جميع أمراء دمشق وسائر المباشرين بين يدي الأمير إينال، وقد اطمأنَّ كل أحد بأن ملك الأمراء مس"},{"id":3393,"era":"c9","t":"القتال بين ملك الحفصيين أبي عمرو عثمان وبين عمه أبي الحسن .","s":"جرت حروب بأفريقية من بلاد المغرب، وذلك أنه لما مات أبو فارس عبد العزيز، وقام من بعده حفيده المنتصر أبو عبد الله محمد بن أبى عبد الله، ولى عمه أبا الحسن على بن أبي فارس بجاية وأعمالها، فلما مات المنتصر، وقام من بعده أخوه أبو عمرو عثمان بن أبي عبد الله، امتنع عمه أبو الحسن من مبايعته، ورأى أنه أحق منه، ووافقه فقيه بجاية منصور بن علي بن عثمان وله عصبة وقوة، فاستبد بأمر بجاية وأعمالها، فسار أبو عمرو م"},{"id":3394,"era":"c9","t":"وقوع الصلح بين ملك إشبيلية وبين ملك المسلمين بغرناطة .","s":"وقع الصلح بين الفنش ملك إشبيلية وقرطبة وغيرهما من ممالك الفرنج، وبين محمد بن الأحمر ملك المسلمين بغرناطة من بلاد الأندلس، بعدما امتدت الفتنة بين الفريقين عدة سنين."},{"id":3395,"era":"c9","t":"هدم قلعة الكهف الإسماعيلية في طرابلس .","s":"قدم عسكر من مدينة طرابلس فنازلوا قلعة الكهف ومدينتها وبها إسماعيل بن العجمي أمير الإسماعيلية مدة أيام، حتى أخذوها، وهدموا القلعة حتى سووا بها الأرض، وأنعم على إسماعيل بإمرة في طرابلس، فزالت قلعة الكهف، وكانت إحدى الحصون الإسماعلية المنيعة، وذلك بسعاية ناصر الدين محمد، وحجي، وفرج: أولاد عز الدين الداعي."},{"id":3396,"era":"c9","t":"غزو المسلمين رودس .","s":"في يوم الثلاثاء الحادي والعشرين جمادى الأولى قدم غزاة المسلمين في البحر، وكان من خبرهم أنهم انحدروا في النيل من ساحل بولاق إلى دمياط، ثم ركبوا بحر الملح من دمياط وساروا في جزيرة قبرص، فقام لهم متملكها بزوادتهم، ومروا إلى العلايا فأمدهم صاحبها بطائفة في غرابين -نوع من المراكب-  ومضوا إلى رودس، وقد استعد أهلها لقتالهم، فكانت بينهم محاربة طول يومهم، لم يكن فيها حسم، وقُتِلَ من المسلمين اثنا عشر من ال"},{"id":3397,"era":"c9","t":"استغاثة إمارة غرناطة بالسلطان المملوكي جقمق .","s":"أرسلت إمارة غرناطة آخر إمارات الإسلام في الأندلس بسفارة استغاثة ونجدة بعثتها إلى السلطان المملوكي الظاهر جقمق بالديار المصرية؛ وذلك طلبًا للعون والمساعدة، وكان المسلمون في غرناطة يعانون من ضراوة الهجوم الذي يشنه النصارى الأسبان على دولتهم، لكن هذه الاستغاثة لم تَجِدِ استجابةً كافية من السلطان المملوكي!!"},{"id":3398,"era":"c9","t":"اشتداد البرد بالقاهرة حتى جمدت المياه .","s":"اشتدَّ البرد بالقاهرة حتى جمدت المياه بعدة مواضع، وبِيعَ الجليد بالأسواق في يوم الخميس الحادي عشر من شعبان، وجمدت بركة من مستنقع ماء النيل في بعض الضواحي بحيث صارت قطعة واحدة، ومشى فوقها الأوزُّ، وأصبحت زروعٌ كثيرة من الفول وقد اسودَّت وجفَّت، فحُملت وأُوقدت في الأفران، واسودَّ ورقٌ كثير من شجر الجميز وغيره!"},{"id":3399,"era":"c9","t":"وفاة الخليفة العباسي المعتضد داود وتولية أخيه المستكفي سليمان .","s":"هو الخليفة العباسي المعتضد بالله داود بن المتوكل على الله أبي عبد الله محمد، في يوم الأحد رابع ربيع الأول كانت وفاته بعد مرض تمادى به أيامًا، وحضر السلطان الملك الظاهر جقمق الصلاة عليه بمصلاة المؤمني، ودُفن بالمشهد النفيسي، وكانت خلافته تسعة وعشرين سنة وأيامًا، ثم في يوم الخميس ثامن ربيع الأول كانت مبايعة الخليفة أمير المؤمنين سليمان ابن الخليفة المتوكل على الله أبي عبد الله محمد بالخلافة، بعد وفا"},{"id":3400,"era":"c9","t":"خلع أمير مكة بركات بن حسن وتولية أخيه علي بعده .","s":"في يوم الاثنين السادس عشر جمادى الأولى خَلَع السلطانُ الظاهر جقمق على الشريف علي بن حسن بن عجلان باستقراره في إمرة مكة، عِوَضًا عن أخيه الشريف بركات بن حسن بحكم عزله؛ لعدم حضوره إلى الديار المصرية، وعيَّن السلطان مع الشريف علي خمسين مملوكًا من المماليك السلطانية، وعليهم الأمير يشبك الصوفي المؤيدي أحد أمراء العشرات ورأس نوبة، لمساعدة الشريف علي على قتال أخيه الشريف بركات، وسافر الشريف علي من القاهر"},{"id":3401,"era":"c9","t":"وفاة المؤرخ المقريزي .","s":"هو الشيخ الإمام العالم المحدِّث المفنن، عمدة المؤرخين، ورأس المحدثين: تقي الدين أحمد بن علي بن عبد القادر بن محمد بن إبراهيم بن محمد بن تميم بن عبد الصمد البعلبكي الأصل, المصري المولد والوفاة، المقريزي الحنفي ثم الشافعي، ولد في القاهرة 764 نشأ بالقاهرة، وتفقه على مذهب الحنفية، وهو مذهب جده العلامة شمس الدين محمد بن الصائغ، ثم تحول شافعيًّا بعد مدة طويلة. تفقه وبرع، وصنف التصانيف المفيدة النافعة ال"},{"id":3402,"era":"c9","t":"الملك شاه رخ ابن الطاغية تيمورلنك يكسو الكعبة .","s":"لما ملك شاه رخ ابن الطاغية تيمورلنك، واستقلَّ بممالك العجَم وعراقة، وعظُمَ أمرُه وهابَتْه الملوك، وحُمِدَت سيرته، وشُكِرت أفعالُه، وقَدِمَت رسله إلى البلاد المصرية مرارًا عديدة, وراسلته ملوكُ مصر، إلى أن تسلطن الملك الأشرف برسباي، طلب شاه رخ أن يكسو البيت الشريف، فأبى الأشرفُ برسباي وخشَّن له الجواب. وترددت الرسلُ بينهما مرارًا، واحتجَّ شاه رخ أنَّه نذر أن يكسو البيت الشريف، فلم يلتفت الأشرف برسبا"},{"id":3403,"era":"c9","t":"القتال بين سلطان العثمانيين مراد الثاني وبين المجر .","s":"قام أميرُ الصرب جورج برنكوفتش بمهاجمة السلطان مراد الثاني العثماني، واستطاع أن يفتح جزءًا من بلاد الصرب، وحاصر مدينة بلغراد ستة أشهر، وغادرها أميرها نائب السلطان العثماني متوجهًا إلى بلاد المجر، ثم غادرها أيضًا, وأرسل جيشه للهجوم على ترانسلفانيا من أملاك المجر -تقع في الجزء الغربي من رومانيا- غير أن جيشه هُزم، وقُتل قائِدُه مع عشرين ألفًا من جند المسلمين، وانسحب العثمانيون إلى ما بعد نهر الدانوب، "},{"id":3404,"era":"c9","t":"خروج العسكر المصري لغزو رودس وعودته دون الوصول لرودس .","s":"كان السلطان الظاهر جقمق مهتمًّا بغزو رودس؛ فعَيَّن عدة كبيرة من المماليك السلطانية والأمراء، ومُقدَّم الجميع اثنان من مقدَّمي الألوف: الأمير إينال العلائي الناصري، المعزول عن نيابة صفد، والأمير تمرباي رأس نوبة النوب، وسافر الجميع من ساحل بولاق في محرم سنة ست وأربعين، ومعهم عدة كبيرة من المطوعة، بأبهج زي من العدد والسلاح، وكان لسفرهم بساحل بولاق يوم مشهود، إلا أنهم عادوا في أثناء السفر، ولم ينالوا "},{"id":3405,"era":"c9","t":"فتنة المماليك السلطانية الأجلاب على السلطان الظاهر جقمق .","s":"لما كان يوم الاثنين السادس عشر صفر وثب جماعة كبيرة من مماليك السلطان الأجلاب-هكذا يُعرَفون- من مشترواته الذين بالأطباق من القلعة، وطلعوا إلى أسطحة أطباقهم، ومنعوا الأمراء وغيرهم من الأعيان من طلوع الخدمة، وأفحشوا في ذلك إلى أن خرجوا عن الحد، ونزلوا إلى الرحبة عند باب النحاس، وكسروا باب الزردخاناه السلطانية، وضربوا جماعةً من أهل الزردخاناه -خزانة السلاح- وأخذوا منها سلاحًا كثيرًا، ووقع منهم أمور قب"},{"id":3406,"era":"c9","t":"وفاة الأمير سودون بن عبد الله النوروزي .","s":"الأمير سيف الدين سودون بن عبد الله النوروزي حاجب حُجَّاب دمشق, ويعرف بسودون العجمي أحد العشرات ورؤوس النوب، ممن تأمَّر في أيام الظاهر جقمق. من مماليك الأمير نوروز الحافظي، وتنقَّلت به الأحوال بعد موت أستاذه إلى أن صار في الدولة الأشرفية برسباي دوادار السلطان بحلب، وأمير مائة ومقدم ألف بها، ودام على ذلك مدة طويلة بحلب، إلى أن نقله الملك الظاهر جقمق إلى حجوبية الحجَّاب بدمشق، بعد الأمير برسباي من حم"},{"id":3407,"era":"c9","t":"البابا أوغانيوس يعلن قيام حرب صليبية جديدة ضد المسلمين .","s":"قام البابا أوغانيوس الرابع بالدعوة لحرب صليبية ضد العثمانيين، وخاصةً أن مراد الثاني هُزم أكثر من مرة وخاصةً أمام المجريين، ولاقت هذه الدعوة ترحيبًا كبيرًا في بولندا والمجر والنمسا وألمانيا وفرنسا، وتعاقدوا على جيش يقودُه ملك المجر جان هونياد."},{"id":3408,"era":"c9","t":"تنازل السلطان العثماني مراد بن محمد عن السلطة لولده محمد .","s":"لما مرَّ على مرادِ الثاني ما مرَّ من حروب وهُزِمَ أكثَرَ من مرة أمام المجر، وتوفِّيَ ولده الأكبر علاء الدين، شعَرَ السلطان بالتعب، فرأى أن يخلُدَ إلى الراحة، فتنازل عن الحكم لابنه الثاني محمد، الذي لم يكن يبلغ من العمر سوى أربعة عشر عامًا، وسافر هو إلى غربي الأناضول في ولاية آيدين، وهذا ممَّا قوى عزيمةَ الصليبيين للقيام بحملة صليبية على العثمانيين."},{"id":3409,"era":"c9","t":"العسكر المصري والشامي يغزو رودس ويعود دون فتحها .","s":"في يومِ السبت سادس عشر شهر ربيع الأول خرج الغُزاة من القاهرة، فنزلوا في المراكبِ من ساحل بولاق؛ وقصدوا الإسكندرية ودمياط؛ ليركبوا من هناك البحرَ المالح، والجميعُ قصْدُهم غزو رودس، وكانوا جمعًا موفورًا، ما بين أمراء وخاصكية ومماليك سلطانية ومطوعة، وكان مقَدَّمَ الجميع في هذه الغزوة الأميرُ إينال العلائي الدوادار الكبير، وكانت المماليك السلطانية في هذه الغزوة تزيد عدتهم على ألف مملوك، هذا خارجٌ عمَّ"},{"id":3410,"era":"c9","t":"الحرب بين العثمانيين وبين الصليبيين وموقعة فارنا .","s":"بعد أن أصبح سلطان العثمانيين محمدُ بن مراد الثاني وهو ما يزال صغيرًا غِرًّا على القتال، جمع الصليبيون جموعَهم وهاجموا بلاد البلغار، ساعدهم على ذلك صِغَرُ سن السلطان وبُعدِ السلطان مراد عن البلاد، ولكِنَّ السلطان مراد لما سمع بهذا الهجوم على البلغار غادر مكانه واتَّجه إلى أوربا فقاد الجيش وسار نحو الأعداءِ فوجدهم يحاصرون مدينة فارنا البلغارية الواقعة على ساحل البحر الأسود، فنازلهم وقتَلَ ملِكَ المج"},{"id":3411,"era":"c9","t":"عودة السلطان مراد الثاني للسلطة لجهاد الصليبيين .","s":"عاد السلطانُ مراد الثاني للسلطة بعد أن ترك اعتزالَه لقتال الصليبيين في فارنا وهزمهم ثم عاد مرةً أخرى إلى مكان إقامتِه تاركًا الأمر لابنه محمد، لكن إقامتَه لم تطل أكثر من ثلاثة أشهر فاضطر للعودةِ إلى أدرنة قاعدةِ الملك، حيث استصغر قادةُ الجيش العثماني من الانكشارية السلطانَ محمد بن مراد، فعَصَوا أمره ونهَبوا المدينة، فوصل السلطانُ مراد فأدَّب القادة وأشغَلَهم بالقتالِ في بلاد اليونان، وذلك أنَّ إمب"},{"id":3412,"era":"c9","t":"خلع محمد الأيسر ملك بني نصر في غرناطة وتولي محمد العاشر مكانه .","s":"كان محمد التاسع الملقب بالأيسر هذا منفيًّا في المغرب، ثم عاد بتقوية ملك قشتالة له فأزاح محمد الثامن الملقب بالصغير وحَلَّ محلَّه، لكِنَّ الفتنَ لم تنتهِ، وكان له عدةُ خصوم، فاستطاع الأميرُ محمد العاشر بن عثمان بن يوسف المعروف بالأحنف أن يتزعَّمَ خصوم محمد الأيسر ويستولي على قصر الحمراء والحصون المجاورة له، ويقبِضَ على الأيسر هذا وينُهيَ ملكَه ويزجَّه وآلَه في السجن، ويخلُفَه في ملك بني نصر."},{"id":3413,"era":"c9","t":"وفاة الشيخ الحافظ عبد الله العبدوسي المالكي مفتي فاس .","s":"هو شيخُ الإسلام الحافظ العلامة أبو محمد عبد الله بن محمد بن موسى بن معطي العبدوسي المالكي، مفتي فاس وعالِمُها ومحَدِّثُها. قال فيه السيوطي: \"كان عالِمًا بارعًا صالحًا مشهورًا\" وقال الشيخ أحمد زروق الفاسي: \"كان أبو محمد العبدوسي عالِمًا صالحًا مفتيًا، حُملتُ إليه وأنا رضيع ولم أزل أتردَّدُ إليه في ذلك السن؛ لكون جدتي تقرأُ عليه مع أختيه فاطمة وأم هانئ، وكانتا فقيهتين صالحتين، وكان قطبًا في السخاءِ،"},{"id":3414,"era":"c9","t":"خلع محمد العاشر الأحنف ملك بني نصر بغرناطة .","s":"لم تدُمْ أيام الأحنف محمد العاشر الملك بغرناطة كثيرًا؛ فقد ثار عليه الأمير سعد بن علي بن أبي الحجاج يوسف الثاني، فانتزع منه الملك وتلقب بالمستعين وعُرِفَ بابن الأحمر، لكنَّه لم يلبث كثيرًا حتى عاد محمد العاشر الأحنف بعد أن لجأ إلى ملك قشتالة فزوَّدَه بقوة استرد بها المُلكَ بالقوة وخلع المستعينَ."},{"id":3415,"era":"c9","t":"وفاة الأمير سودون بن عبد الله المحمدي نائب قلعة دمشق .","s":"هو الأمير سيف الدين سودون بن عبد الله المحمدي، نائب قلعة دمشق، هو مملوك سودون بن عبد الله المحمدي المتوفي سنة 818، وعتيقه، وإليه يُنسَب بالمحمدي. واستمرَّ بخدمته إلى أن قتله المؤيد شيخ، واستمرَّ من جملة المماليك السلطانية إلى أن صار في الدولة الأشرفية برسباي خاصكيًّا، ورأَسَ نوبةَ الجمدارية مدةً طويلة. ثم أراد الأشرفُ أن يؤمِّرَه فامتنع وترك وظيفته أيضًا، وصار من جملة المماليك السلطانية على إقطاعه"},{"id":3416,"era":"c9","t":"وفاة الأمير أزبك جُحا .","s":"هو الأمير سيف الدين أزبك بن عبد الله السيفي قاني باي، أحد أمراء العشرات ورأس نوبة، المعروف بجُحا، أصله من مماليك نوروز الحافظي، وبقى عنده كتابيًّا، فأخذه بعد موته الأمير قاني باي المحمدي نائب دمشق وأعتقه، ثم اتصل بعد موت قاني باي بخدمة السلطان الملك المؤيد شيخ، وصار في دولته خاصكيًّا، ثم صار رأس نوبة الجمدارية- حَمَلة ملابس السلطان- في دولة السلطان الأشرف برسباي، ثم أمَّرَه الأشرفُ عشرةً وجعله من "},{"id":3417,"era":"c9","t":"نشأة إمارة الدرعية في نجد .","s":"كان الأمير مانع المريدي الجدُّ الأعلى لأسرة آل سعود يقطُنُ ببلدة الدروع من أعمال القَطيف بشرق الجزيرة العربية، وكان يربطُه بابن درع رئيسِ حجر اليمامة صلةُ نسب، فدعا ابنُ درع مانعًا وأقطعه من أملاكه مرتَفعًا في وادي حنيفة يشتمل على قريتي المليبيد وغصيبة- تبعد 12 ميلًا عن الرياض- فاستقر مانع مع صحبِه وأهله في هذه المنطقة، وبنوا مساكنَهم وسَمَّوها الدرعية، على اسم بلدتهم الأولى في القطيف. كان ذلك في "},{"id":3418,"era":"c9","t":"وفاة شهاب الدين ابن المجدي .","s":"هو الشيخ الإمام العالم العلامة شهاب الدين المجدي أحمد بن رجب بن طيبغا، الشهير بابن المجدي الشافعي. مولدُه بالقاهرة في سنة 767، ونشأ بها، وتفقَّه على مذهب الشافعي، رضي الله عنه، ولازم علماء عصره، واجتهد في طلب العلم إلى أن برع في الفقه، والفرائض، والحساب، والعربية، وتصدر للإقراء والتدريس مدةً طويلة، وانتفع به الطلبة، وتفقَّه به جماعة من أعيان الطلبة، وكان له مشاركةٌ في علوم كثيرة لا سيما في الفرائض"},{"id":3419,"era":"c9","t":"العثمانيون يقاتلون إسكندر بك المتحكم في ألبانيا .","s":"كان إسكندر بك سببًا في فشل القوات العثمانية في الحرب مع اليونان؛ وذلك لهربه من الجيش العثماني وهروبه إلى ألبانيا واحتمى بها؛ ممَّا اضطر الجيشَ العثماني إلى المسير إليه بقوة كبيرة وحصل بينهم عدَّةُ حروب في هذه السنة كانت نهايتُها هزيمة إسكندر بك وأخْذِ بعض المواقع منه، لكِنَّ السلطان العثماني اضطُرَّ إلى تركه والتوجُّه إلى الجيش المجري الذي بدأ بالثوران للثأر من هزيمة وقعةِ فارنا."},{"id":3420,"era":"c9","t":"وفاة السلطان شاه رخ بن تيمورلنك سلطان هراة، وسمرقند .","s":"هو السلطان القان معين الدين شاه رخ ابن الطاغية تيمورلنك كوركان بن أيتمش قنلغ بن زنكي بن سنيا بن طارم بن طغريل بن قليج بن سنقور بن كنجك بن طغر سبوقا بن التاخان، المغولي الأصل، من طائفة جغتاي، سلطان هراة، وسمرقند، وشيراز، وما والاها من بلاد العجم وغيرها. مَلَك البلاد بعد ابن أخيه خليل بن أميران شاه بن تيمورلنك، فإنَّه لما مات والده الطاغية تيمورلنك بأهنكران شرقي سمرقند، وثب خليلٌ على الأمر وتسلطن، و"},{"id":3421,"era":"c9","t":"إعادة الشريف بركات بن حسن أميرًا على مكة .","s":"في يوم الخميس أول شعبان قدم الشريف بركات بن حسن بن عجلان مصرَ، ونزل الملك الظاهر جقمق إلى لقائِه خارج القاهرة، وبالغ السلطانُ في إكرام بركات، وقام إليه ومشى له خطوات، وأجلسه بجانبه، ثم خلع عليه، وقيَّد له فرسًا بسرج ذهبٍ وكنبوش زركش، وركب مع السلطان، وسار إلى قريبِ قلعة الجبل، فرسم له السلطانُ بالعود إلى محلٍّ أنزله به، وهو مكان أخلاه له المقرُّ الجمالي ناظر الخواص، ورتَّب له الرواتب الهائلة، وقام"},{"id":3422,"era":"c9","t":"وفاة الشيخ ابن قاضي شهبة الدمشقي الشافعي .","s":"هو العلامة الشيخ تقي الدين أبو بكر بن أحمد بن محمد بن عمر الدمشقي الشافعي، المعروف بابن قاضي شهبة نسبةً إلى جده عمر الذي كان قاضيًا بشهبة من قرى حوران. ولد أبو بكر سنة 779، انتهت إليه الرئاسة في فقه مذهبه وفروعه، وكان وليَ قضاء دمشق وخطب في واقعة الجكمي للملك العزيز يوسف، فحقَدَ عليه الملك الظاهر جقمق ذلك، وعزله، إلى أن مات، بعد أن تصدى للإفتاء والتدريس سنين كثيرة، وانتفع به غالبُ طلبة العلم بدمشق"},{"id":3423,"era":"c9","t":"العثمانيون ينتصرون على المجريين في موقعة (كوسوفا) .","s":"بعد انتصار العثمانيين على الصليبين في فارنا كانت رغبة الثأر تأكل قلبَ هونياد قائد الجيش الصليبي المجري، وكان يريد الانتقامَ ومحو آثار هزيمتِه وهروبه من ساحة القتالِ، لَمَّا رأى هونياد أنَّ السلطان العثماني مراد الثاني قد خلَدَ إلى الراحة تاركًا أعباء السلطنة لابنه محمد الذي كان ما يزال فتيًّا سولت لهم أنفسُهم نقضَ العهود التي كانوا قد أبرَموها مع السلطانِ مراد بزعم أنَّ هذه العهود لم تكن بإذن البا"},{"id":3424,"era":"c9","t":"وفاة الحافظ أحمد ابن حجر العسقلاني .","s":"هو أمير المؤمنين في الحديث قاضي القضاة، شيخُ الإسلام، حافظ العصر، رحلة الطالبين، مفتي الفِرَق، شهاب الدين أبو الفضل أحمد ابن الشيخ نور الدين علي بن محمد بن علي بن أحمد بن حجر، المصريُّ المولدِ والمنشأِ والدار والوفاة، العسقلانيُّ الأصلِ، الشافعيُّ، قاضي قضاة الديار المصرية وعالِمُها وحافظها وشاعرها، ولد في 23 شعبان بالقاهرة سنة 773. مات والده وهو حَدَث السن، فكفَلَه بعض أوصياء والده إلى أن كبرَ وح"},{"id":3425,"era":"c9","t":"وفاة الأمير ألوغ بك بن القان صاحب مدينة هراة .","s":"هو الأمير ألوغ بك بن القان معين الدين شاه رخ، ابن الطاغية تيمورلنك كوركان بن أيتمش قنلغ بن زنكي بن سنيا بن طارم بن طغريل بن قليج بن سنقور بن كنجك بن طغر سبوقا بن التاخان، المغولي الأصل، من طائفة جغتاي، وقيل: اسمه تيمور على اسم جدِّه، وقيل: محمد. صاحب سمرقند، فريد دهره ووحيد عصره في العلوم العقلية، والهيئة، والهندسة، طوسي زمانه، وهو حنفيُّ المذهب. ولد في حدود 790، ونشأ في أيام جدِّه، وتزوج في أيامه"},{"id":3426,"era":"c9","t":"انتشار طاعون في مصر .","s":"فشا أمر الطاعون بالقاهرة، وتزايد، ثم أهلَّ صفر من سنة ثلاث وخمسين يوم الأربعاء، وفيه عظم الطاعون، ومات في هذا الشهر جماعةٌ كبيرة من الأمراء، وأعيان الدولة، ثم في يوم الاثنين عشرين صفر، تناقص الطاعون، وفي أواخر شهر ربيع الأول قلَّ الطاعون بالقاهرة، بعد أن مات به خلائق كثيرة، فكان من جملة من مات للسلطان جقمق فقط أربعة أولاد من صلبه، حتى لم يبقَ له ولد ذكر غير المقام الفخري عثمان."},{"id":3427,"era":"c9","t":"إنهاء الطاهريين للدولة الرسولية، وقيام دولتهم على أنقاضها  .","s":"كانَ الطاهريُّون مشايخَ مَحلِّيينَ مِن منطقةِ رَداعَ حيث كانت لهمُ الرياسةُ فيها، وتابِعينَ لِبَني رَسولٍ، وقد توَطَّدتِ العَلاقةُ بينَ بَني طاهرٍ ودولةِ بَني رَسولٍ في أواخِرِ الدولةِ الرَّسوليةِ بمُصاهرةٍ تمت عامَ 836هـ بينَ المَلكِ الظاهرِ الرَّسوليِّ وابنةِ كَبيرِ آلِ طاهرٍ، الشَّيخِ طاهرِ بنِ معوضةَ، ثم صارَ آلُ طاهرٍ وُلاةً لآلِ رَسولٍ في جِهاتِهم، بل وامتَدَّ حُكمُهم إلى عَدَنٍ في فَتراتٍ ل"},{"id":3428,"era":"c9","t":"خبر قتل محمد الفاتح أخيه الرضيع .","s":"اتُّهِم السلطان محمد الفاتح بقتلِ أخيه الرضيع أحمد بعد تولِّيه السَّلْطَنة، وخبَرُ هذا القتل نُقِل بدون خطامٍ أو زمام، فلم تذكُره مراجع التاريخ العثماني، وإنما لفَّقه أعداء الدولة العثمانية وخصومُها خاصةً من النصارى أو من العرب المخدوعين بالفكر القومي, والثابتُ أنَّ أحمد هذا مات غريقًا في حوض الماء بعد أن غَفَلت عنه مربيته."},{"id":3429,"era":"c9","t":"وفاة الخليفة العباسي المستكفي بالله سليمان .","s":"هو الخليفة العباسي المستكفي بالله أبو الربيع سليمان ابن الخليفة المتوكِّل على الله أبي عبد الله محمد، توفي بالقاهرة يوم الجمعة الثاني محرم، ونزل السلطانُ الملك الظاهر جقمق للصلاة عليه بمصلاة المؤمني، ومشى في جنازته إلى أن شَهِد دفنَه، وربما أراد حملَ نعشِه في طريقه، ومات المستكفي وهو في عشر الستين، بعد أن أقام في الخلافة تسعَ سنين ونحو عشرة أشهر، وتولى الخلافةَ بعده أخوه أبو البقاء حمزة بغير عهدٍ "},{"id":3430,"era":"c9","t":"وفاة السلطان مراد الثاني بن محمد جلبي وتولي ابنه محمد (الفاتح) .","s":"هو السلطان الغازي مراد الثاني بن محمد جلبي بن بايزيد بن مراد الأول بن أورخان بن عثمان بن أرطغرل, وهو سادس سلاطين العثمانيين. ولد مراد الثاني سنة 806 (1403م) وتولى سنة 824 (1421م) بعد موت أبيه وعمره ثماني عشرة سنة. كانت أيام حكمه مليئة بالجهاد والحروب, وقد افتتح أعماله بإبرام الصلح مع أمير القرمان والاتفاق مع ملك المجر على هدنة خمسِ سنوات حتى يتفرَّغ لإرجاع ما شقَّ عصا الطاعة من ولايات آسيا لكنْ حد"},{"id":3431,"era":"c9","t":"وفاة العلامة بدر الدين العيني .","s":"هو العلامة قاضي القضاة بدر الدين أبو الثناء- وقيل أبو محمد- محمود ابن القاضي شهاب الدين أحمد بن موسى بن أحمد بن حسين بن يوسف بن محمود العينتابي الحنفي، قاضي قضاة الديار المصرية، وعالِمُها ومؤرِّخُها، وُلِدَ بعينتاب في رمضان سنة 762، ونشأ بها، وتفقه بوالده بعد حفظه القرآن الكريم، ثم رحل إلى حلب ثم القاهرة، إلى أن تولى فيها النظر في الأحباس- الأوقاف- ثم القضاء، كان مقربًا جدًّا من السلطان الأشرف برس"},{"id":3432,"era":"c9","t":"السلطان العثماني محمد الفاتح يستعد لحصار القسطنطينية .","s":"منذ أن تولى محمد الفاتح السلطنة مشى على ما كان عليه أبوه من الجهاد والغزو؛ فأول ما بدأ به أن أرجع زوجة أبيه الأميرة الصربية النصرانية مارا إلى أبيها، ثمَّ بنى قلعة على مضيق البوسفور على الشاطئ الأوربي مقابِلَ القلعة التي بناها السلطان بايزيد على الشاطئ الآسيوي، كل ذلك ليُحكِمَ قبضته على المضيق ويمنعَ من وصول الإمدادات إلى القسطنطينية من مملكة طرابزون الواقعة على ساحل البحر الأسود شمال شرق الأناضول"},{"id":3433,"era":"c9","t":"وفاة الملك الكامل خليل ابن الأشرف ملك حصن كيفا بديار بكر .","s":"توفي الملك الكامل خليل ابن الملك الأشرف أحمد ابن الملك العادل سليمان، صاحب حصن كيفا من ديار بكر، تولى ملك الحصن بعد قتل أبيه الملك الأشرف سنة 836 على يد أعوان قرايلك, وتوفِّي هو قتيلًا بيد ولده في شهر ربيع الأول. وتولى ولده الملك من بعده، ولقِّبَ بالملك الناصر، ودام في مملكة الحصن إلى شهر رمضان من نفس السنة, فوثب عليه ابن عمه الملك حسن وقتله، وسلطن أخاه أحمد، ولقَّبه بلقب أبيه المقتول، الملك الكام"},{"id":3434,"era":"c9","t":"وفاة السلطان الظاهر جقمق وتسلطن ابنه المنصور عثمان  .","s":"هو السلطان الملك الظاهر سيف الدين أبو سعيد جقمق العلائي الظاهري الشركسي، السلطان الرابع والثلاثون من ملوك الترك، والعاشر من الجراكسة، ويذكر في أصله أنه أخذ من بلاده صغيرًا فاشتراه خواجا كزلك وجلبه إلى الديار المصرية، فابتاعه منه الأتابك إينال اليوسفي، وقيل: ولده أمير علي بن إينال وهو الأصح، وربَّاه عنده، فطلبه الملك الظاهر منه في سرحة سرياقوس، وأخذه وأعطاه لأخيه جاركس، وقد اختلفت الأقوال في أمر عت"},{"id":3435,"era":"c9","t":"خلع السلطان المنصور عثمان بن جقمق وتسلطن الأشرف إينال .","s":"لما تسلطن المنصور عثمان بن جقمق أساء تدبيرَ أمور الدولة فأخذ يعزِلُ ويولي ويعطي ويمنع دون رشدٍ ولا تدبيرٍ ولا توقيرٍ لكبير أو قديم، حتى أوغر صدورَ الأشرفية والمؤيدية عليه، وانتظم الصلح بين الطائفتين سرًّا فتحالفوا واتَّفقوا على الركوب في يوم بعينه، كل ذلك والمنصور ومماليك أبيه وحواشيه في غفلةٍ عن ذلك، وأكبَرُ همهم في تفرقة الإقطاعات والوظائف، وفي ظنِّهم أن دولتهم تدوم، وأنَّ الملك قد صار بيَدِهم، "},{"id":3436,"era":"c9","t":"فتح القسنطينية على يد السلطان العثماني محمد (الفاتح) .","s":"عرَضَ السلطان محمد بن مراد الثاني على إمبراطور القسطنطينية أن يسلِّمَها كي لا تصابَ بأذًى ولا يحِلَّ بالأهالي النكبات، وتعهَّد السلطان بحمايةِ العقائد وإقامةِ الشعائر، فرفض الإمبراطورُ ذلك، فقام السلطانُ بمحاصرة المدينة من الجانب الغربي من البَرِّ بجنود يزيد عددهم على مائتين وخمسين ألف مقاتل، ومن جهة البحر بمائة وثمانين سفينة بحرية، وأقام المدافِعَ حول الموقع، وكان من أهمِّها وأشهرها المدفعُ العظي"},{"id":3437,"era":"c9","t":"فتح بلاد البلقان كلها عدا بلدتي بلغراد وغوسة .","s":"بعد أن أتم السلطانُ محمد الفاتح فتحَ القسطنطينية، أراد التوجُّهَ إلى بلاد المورة فأرسل مَلِكُها وفدًا يعرضُ على السلطانِ دفع جزيةٍ سنوية مقدارُها اثنا عشر ألف دوك ذهبي، كما صالح أمير الصربِ مقابل جزية سنوية قدرها ثمانون ألف دوك ذهبي، ثم دخل السلطان إلى بلاد الصرب وحاصر بلغراد، ودافع عنها المجريون، ولم يتمكن العثمانيون من فتحها."},{"id":3438,"era":"c9","t":"خلع محمد العاشر ملك بني نصر وعودة المستعين سعد .","s":"قام المستعين بالله سعد بن علي بن يوسف الثاني بخلع الأحنف محمد العاشر بن عثمان ملك بني نصر وتولي بدلًا عنه حُكمَ غرناطة، وقد تكرر الخلعُ بينهما أكثَرَ من مرة؛ فقد ثار الأمير سعد على الأحنف سنة 850 فخلعه، ثم لم يلبَث الأحنفُ أن عاد للحُكم وخلَعَ الأمير سعد بن علي بدعم من ملك قشتالة."},{"id":3439,"era":"c9","t":"زوال دولة بني رسول في زبيد وعدن .","s":"وفي هذه السنة زالت دولةُ بنى رسول ملوك اليمن في زبيد وعدن بعد ما حكموا ممالكَ اليمن نحوًا من مائتين وثلاثين سنة, وكان أولُ ملوكهم الملكَ المنصور أبا الفتح عمر بن على بن رسول إلى آخر من ملَكَ منهم، وهو الملِكُ المسعود أبو القاسم بن إسماعيل الثاني، وقد استولى على جميع ممالك اليمن بعد بني رسول أمراءُ بني طاهر بزعامة الملك الطاهر صلاح الدين عامر الأول بن طاهر، ويُذكَرُ أن دولة بني رسول تأسَّست سنة 626"},{"id":3440,"era":"c9","t":"ضعف شأن الوزارة في عهد المماليك  .","s":"في يوم الاثنين التاسع والعشرين صفر من هذه السنة استقرَّ شمس الدين نصر الله بن النجار ناظر الدولة وزيرًا عِوَضًا عن سعد الدين فرج بن النحال بحكم عزلِه، وكان قد طرأ على أمر الوزارة من الضعفِ ما جعل ابن تغري بردي يقول عنها: \"لم تَرَ عيني فيما رأيتُ ممن لبس خِلَعَ الوزارة أقبح زيًّا من ابن النجار، حتى إنَّه أذهب رونقَ الخِلعة مع حسن زيِّ خِلعةِ الوزارة وأبَّهة صفتها، ولو منَّ الله سبحانه وتعالى بأن يُ"},{"id":3441,"era":"c9","t":"فتنة المماليك الظاهرية ومحاولتهم خلع السلطان الأشرف إينال .","s":"في يوم الاثنين آخر جمادى الآخرة كانت وقعةُ المماليك الظاهرية الجقمقية مع الملك الأشرف إينال، وسببُ هذه الفتنة ثورةُ المماليك الأجلاب أولًا، وأفعالُهم القبيحة بالناس، ثم عقب ذلك أنَّ السلطان كان عيَّنَ تجريدة إلى البحيرة، نحوًا من خمسمائة مملوك، وعليهم من أمراء الألوف الأمير خشقدم المؤيدي أمير سلاح، والأمير قرقماس رأسُ نوبة النوب، وعِدَّةٌ من أمراء الطبلخانات والعشرات، ورسم لهم السلطانُ بالسفر، ولم"},{"id":3442,"era":"c9","t":"خلع الخليفة العباسي القائم بأمر الله حمزة وتولية أخيه المستنجد بالله .","s":"لما وقف الخليفةُ القائم بأمر الله في صفِّ المماليك الظاهرية في فتنتِهم ضِدَّ السلطان الأشرف إينال ظنًّا منه أنه يُخلَعُ فيزداد بذلك مرتبةً فوق التي هو فيها بوقوفِه مع هؤلاء المماليك، ولكن لما انكسر أمرُهم ومَسَك السلطانُ الأشرف إينال الخليفةَ ووبَّخه على وقفته هذه، أمر بحبسه بالبحرةِ من قلعة الجبل، وخلعه من الخلافة بأخيه يوسف في يوم الخميس ثالث شهر رجب، ثم أرسل الخليفةَ القائمَ بأمر الله في يوم ال"},{"id":3443,"era":"c9","t":"وفاة العلامة العز عبد السلام القيلوي البغدادي .","s":"هو العلَّامةُ العِزُّ مجد الدين عبد السلام بن أحمد بن عبد المنعم بن أحمد بن محمد بن كيدوم بن عمر بن أبي الخير سعيد الحسيني القيلوي البغدادي ثم القاهري الحنبلي ثم الحنفي. ولدَ تقريبًا بعد سنة 770 والقيلوي نسبة لقرية بالجانب الشرقي من بغداد يقال لها قيلويه نشأ بها العز. قرأ القرآنَ لعاصم وحَفِظَ كتبًا جمة في فنون كثيرة، وبحث في غالب العلوم على مشايخ بغداد والعجم والروم، حتى إنه بحث في مذهبي الشافعي "},{"id":3444,"era":"c9","t":"فتنة المماليك الأجلاب بمصر .","s":"في يوم الخميس الخامس عشر جمادى الآخرة من هذه السنة أمسك السلطان الأشرف إينال الأمير زين الدين الأستادار، واستقرَّ عِوَضَه في الأستادارية سعد الدين فرج بن النحال الوزير، فلمَّا سمعت المماليك الأجلاب بهذا العزل والولاية نزلوا من وقتهم غارةً إلى بيت الأستادار لينهبوه، فمنعهم مماليك زين الدين، وقاتلوهم وأغلقوا الدروبَ، فلما عجزوا عن نهب بيت زين الدين نهبوا بيوت الناسِ من عند بيت زين الدين فأخذوا ما لا"},{"id":3445,"era":"c9","t":"محمد الفاتح يضم بلاد الصرب ويحاصر مدينة بلغراد .","s":"التقى السلطان العثماني محمد الفاتح مع هونياد زعيم الصرب في معركة انتهت بقتل هونياد واستيلاء العثمانيين نهائيًّا على بلاد الصرب وجعْلها ولاية عثمانية، ولكن بقيت بلغراد التي حاصرها السلطانُ ومعه مائة وخمسون ألف مقاتل ومعه مائتا سفينة حربية، ولكنه فَشِلَ مع كثرة الغارات؛ وذلك بسبب الجرح الذي أصاب السلطان محمد الفاتح؛ مما اضطره للعودة عن الحصار، ولكنَّه فتح في عوده دوقية أثينا التي كانت بيد عائلة من ف"},{"id":3446,"era":"c9","t":"فتنة المماليك الأجلاب على السلطان بمصر .","s":"في يوم الخميس ثالث صفر ثارت المماليك الأجلاب على السلطان، وأفحشوا في أمرِه إلى الغاية، فبينما هو جالسٌ بقاعة قلعة الدهيشة، وكانت الخدمةُ بطالةً في هذا اليوم، وذلك قبل أن يصلِّيَ السلطان الصبح، وإذا بصياح المماليك، فأرسل السلطانُ يسأل عن الخبر، فقيل له إن المماليك أمسكوا نوكار الزردكاش وهددوه بالضرب، وطلبوا منه القرقلات-جمع قرقل وهو ثوب بغير كمين- التي وعدهم السلطان بها من الزردخاناه السلطانية، فحل"},{"id":3447,"era":"c9","t":"العسكر المصري والشامي يسير لقتال ابن قرمان .","s":"في يوم السبت أول شهر ربيع الآخر نودي في المماليك السلطانية المعينين إلى تجريدة البلاد الشامية لقتال ابن قرمان، ثمَّ في يوم الخميس خامس جمادى الأولى برز الأمراء والعساكر من القاهرة إلى الريدانية خارج القاهرة، وأقاموا بالريدانية إلى ليلة الاثنين تاسِعَه، فاستقلوا فيه بالمسير من الريدانية إلى جهة البلاد الشامية، ثم سافر الأمير نوكار الزردكاش، ومعه عدة من الرماة والنفطية وآلات الحصار وهو مريض، ورسم له"},{"id":3448,"era":"c9","t":"وفاة الكمال ابن الهمام الحنفي .","s":"هو الإمامُ العلامة كمال الدين محمد ابن الشيخ همام الدين عبد الواحد ابن القاضي حميد الدين عبد الحميد ابن القاضي سعد الدين مسعود الحنفي السيرامي الأصل المصري المولد والدار والوفاة، المشهور بابن الهمام، ولد سنة 790 بالإسكندرية ومات أبوه وكان قاضي الإسكندرية وهو ابن عشر أو نحوها، فنشأ في كفالة جدته لأمه، وكانت مغربية خيِّرة تحفظ كثيرًا من القرآن وقدم بصحبتها القاهرة فأكمل بها القرآن عند الشهاب الهيثمي"},{"id":3449,"era":"c9","t":"حرائق هائلة في ساحل بولاق وفي القاهرة .","s":"وقع حريق عظيم بساحل بولاق لم يُسمَعْ بمثله في سالف الأعصار إلا قليلًا، بحيث إنَّه أتى على غالب أملاك بولاق من ساحل النيل إلى خط البوصة التي هي محل دفن أموات أهل بولاق، وعجز الأمراء والحكام عن إخماده، وكان من أمر هذا الحريق أنه لما كان صبيحة يوم الجمعة سادس رجب هبت ريح عظيمة وعظمت حتى اقتلعت الأشجار وألقت بعض المباني، واستمرت في زيادة ونمو إلى وقت صلاة الجمعة، فلما كان وقت الزوال أو بعده بقليل احتر"},{"id":3450,"era":"c9","t":"الجيش العثماني يفتح المورة وبلغراد وغيرها .","s":"لم يستطع الجيش العثماني أن يفتح بلغراد سنة 861 بعد أن حاصرها ورجع الجيش بعد أن تعهد ملك الصرب بدفع جزية سنوية، ثم في هذه السنة استطاع الجيش العثماني بقيادة الصدر الأعظم محمود باشا بعد أن حاصر بلغراد وفتحها كما تمكَّن من فتح بلاد المورة من هذا العام، وفر مَلِكُها إلى إيطاليا، كما فتح الجزر التي في بحر إيجة قرب مضيق الدردنيل، كما عقد صلحًا مع إسكندر بك أمير ألبانيا، وكان قبل ذلك يرفض أن يعقد الصلح م"},{"id":3451,"era":"c9","t":"تزايد فتنة المماليك الأجلاب بمصر .","s":"تعرَّض جماعة من المماليك الأجلاب للأمير زين الدين الأستادار، فهرب منهم فضربوه، ولا يختلف اثنان في قوة شوكة الأجلاب في هذه الأيام، حتى تجاوزت الحدَّ، وبطل أمر حكام الديار المصرية قاطبةً، وصار من كان له حقٌّ أو شِبهُ حق لا يشتكي غريمَه إلا عند الأجلاب، ففي الحال يخلص حقه من غريمه، إما على وجه الحقِّ أو غيره، فخافهم كل أحد، لا سيما التجَّار والبَيَعة من كل صنف، وترك غالب الناس معايشَهم؛ خوفًا على رأس"},{"id":3452,"era":"c9","t":"وفاة جلال الدين المحلي صاحب التفسير .","s":"هو الإمام العلامة جلال الدين محمد بن أحمد بن إبراهيم بن أحمد بن هاشم بن الكمال الأنصاري المحلي الأصل نسبة للمحلة الكبرى من الغربية بالقاهرة، الشافعي المصري، ويعرف بالجلال المحلي. ولد في مستهل شوال سنة 791 ونشأ بها فقرأ القرآن وحفظ المتون واشتغل في فنون، فأخذ الفقه وأصوله والعربية وأفتى ودرَّس عدة سنين، وله عدة مصنفات، ولم يكمل بعضها، ورُشِّح لقضاء الديار المصرية غير مرة. قال شمس الدين السخاوي: \"مه"},{"id":3453,"era":"c9","t":"الأمير جاك يحضر إلى السلطان المملوكي ويطلب أن يوليه قبرص .","s":"حضر لمصر في هذه السنة جاك بن ملك قبرص بعد أن توفِّيَ والده ونصبوا على عرش قبرص أخته عوضًا عنه، قيل: لأنه ولَدُ زنا، وقيل غير ذلك، ثم بقي في مصرَ على أمل أن يوليه السلطان عرش قبرص, وحضر كذلك جماعة من قبرص نيابة عن أخته وهي تطلب كذلك أن تبقى هي الملكة, وفي يوم الثلاثاء سادس شعبان وقع في مصر أمرٌ شنيع بسبب هذا الأمر، وهو أن السلطان جمع أعيان الفرنج القبارصة في الملأ بالحوش السلطاني، وأراد بقاء الملكة"},{"id":3454,"era":"c9","t":"صراع على السلطة بين الأمير جاك وأخته ملكة قبرص .","s":"وصل القاهرة كتابُ جانبك الأبلق الظاهري من قبرص أنَّه هو ومن معه من المماليك السلطانية وغيرهم من الفرنج واقعوا أهلَ شرينة في عاشر شهر ربيع الآخر، وحصروا قلعتَها، وقتلوا من الفرنج بشرينة ثمانية نفر، وأسروا مثلَهم، ثم ذكر أنه واقع ثانيًا أهل شرينة، وقتل صاحب الشرطة بقلعتها، وآخر من عظمائها رمى بنفسِه إلى البحر فغرق، وأنَّه قبض على خمسة منهم، وأن الملكة صاحبة شرينة أخت جاك صاحب قبرص قد توجَّهت من شرين"},{"id":3455,"era":"c9","t":"وفاة السلطان الأشرف إينال وسلطنة ابنه الشهابي أحمد .","s":"هو السلطان الأشرف سيف الدين أبو النصر إينال بن عبد الله العلائي الظاهري ثم الناصري، أصله شركسي الجنس، أُخذَ من بلاده، فاشتراه خواجا علاء الدين علي، وقدم به إلى القاهرة، فاشتراه الملك الظاهر برقوق، ودام إينال كتابيًّا بطبقة الزمام، إلى أن مَلَكه الملك الناصر فرج بن برقوق وأعتقه. وهو السادس والثلاثون من ملوك الترك. تولى السلطنة بعد أن خلع المنصور عثمان بن السلطان جقمق سنة 857. تسلَّط في أيامه مماليك"},{"id":3456,"era":"c9","t":"خلع السلطان المؤيد أحمد بن إينال وتسلطن الظاهر خشقدم .","s":"كان الباعث لهذه الفتنة وخلع المؤيَّد أنه لما تسلطن لم يحرك ساكنًا ولم يتغير أحدٌ مما كان عليه، فشقَّ ذلك على الظاهريَّة، وقال كل منهم في نفسه: كأن الملك الأشرف إينال ما مات، فإن الغالبَ كلٌّ منهم كان أخذ ما بيده من الإقطاعات، وحبس ونفى في أوَّل سلطنة الأشرف إينال، كما هي عادة أوائل الدُّول، وبقى منهم جماعة كثيرة بلا رزق ولا إمرة ولم يجدوا عندهم قوةً ليخلعوا الملك المؤيد هذا ويسلطنوا غيره وحدهم، فك"},{"id":3457,"era":"c9","t":"خروج الأمير جانم نائب دمشق عن الطاعة .","s":"حاول الأمير جانم نائب دمشق قبل هذا أن يتسلطنَ، ولكنه كان يخاف، وكان قد أرسل ولده يحيى في السنة الماضية إلى مصر أيام السلطان المؤيد أحمد وكلم بعض الأمراء بذلك وبعضهم وعده أن يقِفَ معه، حتى إنَّ أمر سلطنة خشقدم السلطان الحالي كان على أساس أنه يكون مؤقتًا؛ لأن كثيرًا من الأمراء كاتبوا الأمير جانم على أنهم يسلطنونه وأرسلوا له أن يحضُرَ إلى مصر لذلك؛ لذا فإن جانم هذا وفي هذا شهر جمادى الأولى من هذا الع"},{"id":3458,"era":"c9","t":"نهاية الدولة الأيوبية الكردية على يد ابن قرايلك .","s":"أخذ حسن بك بن علي بك بن قرايلك مدينة حصن كيفا، ثم أخذ قلعتَها في ذي القعدة بعد ما حاصرها سبعةَ أشهر، وانقطع من الحصنِ ملك الأكراد الأيوبية، بعدما ملكوها أكثَرَ من مائتي سنة، وذلك بعد قتلِ صاحبها الملك خلف بيد بعض أقاربه، فاختلف الأكراد فيما بينهم، فوجد حسن بك بذلك فرصةً في أخذها، فحاصرها حتى أخذها، وقوِيَ أمر حسن بأخذِها، فإنه أخذ بعد ذلك عدةَ قلاع من أعمالِ ديار بكر من تعلُّقات الحصنِ وغيرِه."},{"id":3459,"era":"c9","t":"استيلاء الإسبان الفرنج على جبل طارق .","s":"استولى الإسبان الفرنج على جبل طارق الذي كان بيد بني الأحمر ملوك غرناطة، وكان هذا الاستيلاء سببًا لانقطاع غرناطة عن بقية العالم الإسلامي، وأصبحوا تحت تحكُّم الفرنج الذين قاموا بذلك لقطع إي إمدادات لبني الأحمر في حال الهجوم عليهم."},{"id":3460,"era":"c9","t":"ثورة عمرانية في القسطنطينية في عهد الفاتح بناء جامع الفاتح .","s":"أمر السلطان محمد الفاتح بإنشاء جامِعِه في موقع كنيسة بيزنطة القديمة التي دمَّرها الصليبيون أثناء الحملة الصليبية الرابعة، وسمي الجامعُ باسم جامع الفاتح نسبةً إليه، وأمر كذلك أن يُبنى بجانب مسجده ثماني مدارس، على كل جانب من جوانب المسجد أربعة مساجد يتوسَّطُها صَحنٌ فسيح، وفيها يقضي الطالبُ المرحلة الأخيرة من دراسته، وأُلحقت بهذه المدارس مساكِنُ للطلبة ينامون فيها ويأكلون فيها طعامَهم، ووضعت لهم منح"},{"id":3461,"era":"c9","t":"البوسنة تصبح ولاية عثمانية .","s":"امتنع أميرُ البوسنة من أداء الجزية المتعاهَد عليها للدولة العثمانية، فسار إليه السلطان محمد الفاتح بجيشه وانتصر عليه، فضمَّ بذلك بلاد البوسنة إلى الدولة العثمانية، وحاول ملك المجر مساعدةَ أهل البوسنة البوشناق ضد العثمانيين ولكنه انهزم هو الآخر، ويُذكر أن كثيرًا من البوشناق اعتنقوا الإسلام، وانتشر في تلك البلاد الدين الإسلامي على يد العثمانيين."},{"id":3462,"era":"c9","t":"خلع الملك سعد ملك بني نصر وتولي ابنه الغالب علي .","s":"قام أبو الحسن علي بن سعد بن علي بن أبي الحجاج يوسف الثاني بالخروجِ على أبيه وانتزاع الملك منه، وتلقَّب بالغالب بالله."},{"id":3463,"era":"c9","t":"السلطان الظاهر خشقدم يمنع استعمال أهل الذمة في السلطة .","s":"في يوم الأثنين الثاني عشر محرم نودي بشوارع القاهرة أن أحدًا من الأعيان لا يستخدم ذميًّا في ديوانه من الكَتَبة وغيرهم، فمنعت هذه المناداة أهل الذمة قاطبةً من التصرف والمباشرة بقلم الديوان بوجه من الوجوه في أعمال مصر، وكُتِب بذلك إلى سائر الأقطار، ثم عقد السلطان بالصالحية ببين القصرين مجلسَ بالقضاة الأربعة، وحضره الدوادار الكبير، وجماعة من الأعيان، وقُرئت العهود المكتوبة قديمًا على أهل الذمة، فوجدوا"},{"id":3464,"era":"c9","t":"العسكر المصري يأخذ قلعة الماغوصة ويسيء السيرة فيها .","s":"في يوم الجمعة الثالث والعشرين جمادى الآخرة وصل رسول صاحب قبرص جاك، وأخبر أنه أخذ مدينة الماغوصة وقلعتها من يد الفرنج، وأنَّه سلمها للأمير جانبك الأبلق المقيم بجزيرة قبرص بمن بقيَ معه من المماليك السلطانية، فأساء جانبك السيرةَ في أهل الماغوصة، ومدَّ يده لأخذ الصبيان الحِسان من آبائهم وهم أعيانُ أهل الماغوصة، فشق ذلك عليهم، وقالوا: نحن سلَّمناكم البلد بالأمان، وقد حلفتم لنا أنَّكم لا تفعلوا معنا بعد"},{"id":3465,"era":"c9","t":"العثمانيون يقاتلون البنادقة .","s":"اصطدم السلطان العثماني محمد الفاتح مع البنادقة الذين يملِكونَ بعض المواقع في بلاد المورة، وجزرًا كثيرة في بحر إيجة، وقد هاجم البنادقة بعض المراكز العثمانية ودخلوها فسار إليهم السلطان ففرُّوا من مواقعهم ودخلها العثمانيون، وبعد هدنةِ سنة عاد البنادقة لغيِّهم ونقضوا العهد فأرادوا استعادةَ ما فقدوه، وبدؤوا يُغيرون على الدولة العثمانية، ولكنهم باؤوا بالفشل وفقَدوا بعض مواقعهم المهمَّة."},{"id":3466,"era":"c9","t":"نهاية دولة بني مرين وتولية أبي عبد الله الحفيد على المغرب .","s":"اضطربت أحوال الدولة المرينية بفاس وتسلَّط بها اليهود, بعد تعيين السلطان عبد الحق هارون اليهودي رئيسًا لدولته كما عين عددًا منهم في حكومته، وكانوا قد أظهروا الإسلام, فاجتمع رؤساءُ فاس عند خطيب القرويين الفقيه أبي فارس عبد العزيز بن موسى الورياكلي وكانت له صلابة في الحقِّ وجَلادة عليه بحيث يلقي نفسَه في العظائم ولا يبالي، وقالوا له: ألا ترى إلى ما نحن فيه من الذلَّة والصغار وتحكُّم اليهود في المسلمي"},{"id":3467,"era":"c9","t":"العثمانيون يضمون ألبانيا إلى الدولة العثمانية .","s":"بدأ البابا بالدعوة إلى حرب صليبية فشجَّع إسكندر بك ملك ألبانيا على نقض العهدِ الذي أبرَمَه مع العثمانيين سابقًا، داعيًا ملوك أوربا وأمراءها لمساندته، غير أن البابا هلك فجأةً ولم تقم تلك الحرب المزعومة، ولكنَّ إسكندر بك نقض عهده وحارب العثمانيين، فكانت الحرب بينهم سِجالًا إلى أن توفي إسكندر بك بعد حُمَّى شديدة أصابته في مدينة السيو، واستطاع العثمانيون أن يضمُّوا ألبانيا إليهم."},{"id":3468,"era":"c9","t":"خروج الأمير شاه سوار نائب أبلستين عن الطاعة وقتاله .","s":"في يوم الخميس الثاني عشر محرم ورد الخبر من نائب حلب يشبك البجاسي أن شاه سوار نائب أبلستين خرج عن طاعةِ السلطان سيف الدين خشقدم، ويريد المشيَ على البلاد الحلبية، فرسم السلطانُ في الحال بخروج نائب طرابلس ونائب حماة إلى جهة البلاد الحلبية لمعاونة نائب حلب إن حصل أمر، ثم عيَّن السلطان تجريدة- خيل لا رَجَّالة فيها- من مصر إلى جهات البلاد الحلبية إن ألجأت الضرورة إلى سفرهم، ثم إنَّ الأمير بردبك نائب الش"},{"id":3469,"era":"c9","t":"الأعراب يهجمون على حجاج مصر العائدين .","s":"في يوم الخميس التاسع عشر محرم ورد الخبَرُ بأن إقامة الحاج التي جهزت من القاهرة أُخِذَت عن آخرها، أخذها مبارك شيخ بني عقبة بمن كان معه من العرب، وأنه قتل جماعة ممن كان مع الإقامة المذكورة، منهم جارقطلو السيفي دولات باي أحد أمراء آخورية السلطان، فعظم ذلك على السلطان، وزاد توعُّكُه، وعلى الناس قاطبة، وضَرَّ أخذُ إقامة الحاج غايةَ الضرر، وأشرف غالبهم على الموت، فلما كان يوم الجمعة العشرين من المحرم وص"},{"id":3470,"era":"c9","t":"وفاة السلطان الظاهر خشقدم وسلطنة الظاهر يلباي الإينالي .","s":"هو السلطان الملك الظاهر أبو سعيد سيف الدين خشقدم بن عبد الله الناصري المؤيدي، تسلطن في يوم الأحد التاسع عشر رمضان بعد أن أجمع أمراء المماليك على خلع السلطان المؤيد أحمد بن إينال واختاروا الأمير الكبير خشقدم؛ لأنه ليس من جنس المماليك؛ فهو رومي ورجل غريب ليس له شوكة، ومتى أردوا خلعه أمكنهم ذلك، فلما كان يومُ قرروا خلع المؤيد الجمعة السابع عشر رمضان وقت الزوال طُلِبَ الخليفة المستنجد بالله يوسف والقض"},{"id":3471,"era":"c9","t":"خلع السلطان الظاهر يلباي الإينالي وتسلطن الظاهر تمربغا .","s":"إنَّ الملك الظاهر يلباي الإينالي لما تسلطن وتم أمره غطَّاه المنصب، وصار كالمذهول، ولزم السكوتَ وعدم الكلام، وضَعُف عن بتِّ الأمور، وردْع الأجلاب، بل صارت الأجلاب في أيامه كما كانت أولًا وأعظم، فلم يَحسُن ذلك ببال أحد، وصار الأمير خيربك الدوادار الثاني هو صاحب الحل والعقد في مملكته، وإليه جميعُ أمور المملكة، وشاع ذلك في الناس والأقطار، فبهذا وأشباهه اضطربت أحوالُ الديار المصرية، ولما كان عصر يوم ال"},{"id":3472,"era":"c9","t":"خلع السلطان الظاهر تمربغا وتسلطن الأشرف قايتباي المحمودي .","s":"في الخامس من رجب حصل بين المماليك الأجلاب وبعض الأمراء مناوشات، وكان عند السلطان جماعة من خشداشيته الأمراء، والسلطان ومن عنده كالمأسورين في يد الأجلاب، ثم تفرق الأجلاب إلى الأطباق بقلعة الجبل، ولبسوا آلة الحرب وعادوا إلى القصر بقوة زائدة وأمر كبير، وتوجه بعضهم لإحضار الخليفة، وتوجه بعضهم لنهب الحريم السطاني بداخل الدور، ودخل على السلطان ثلاثة أنفار منهم وهم ملثَّمون، وأرادوا منه أن يقوم وينزل إلى "},{"id":3473,"era":"c9","t":"تحالف الدول الأوربية لقتال الدولة العثمانية .","s":"عقدت 25 دولة أوربية- من بينها البندقية وفرنسا وقبرص وبولونيا- معاهدة لقتال الدولة العثمانية التي وجهت فتوحاتها الإسلامية إلى أوربا، لكن هذه الجيوش لم تستطع مواجهة السلطانَ محمد الفاتح!"},{"id":3474,"era":"c9","t":"القتال بين العثمانيين وبين الأمير حسن الطويل التتري .","s":"استطاع الأمير حسن الطويل التتري الذي تزعَّم قبيلتي الخِراف البيض والخراف السود بعد توحُّدهما أن ينتزع خراسان من الأمير أبي سعيد بن محمد بن ميران شاه بن تيمورلنك بعد معركة انتهت بقتل أبي سعيد، ثم أبرم الأمير حسن هذا معاهدة مع دولة البنادقة ضد الدولة العثمانية، فأصبح قادرًا على تهديد الدولة العثمانية من ناحية المشرق، فهاجم الدولة العثمانية واحتلَّ مدينة توقات، فأرسل إليه السلطان العثماني محمد الفاتح"},{"id":3475,"era":"c9","t":"استيلاء البرتغال على مدينة أسفي بالمغرب\n  .","s":"استولى الفرنج البرتغال على مدينة أسَفِي- بلدة على شاطئ البحر المحيط بأقصى المغرب- وهدموها، وبقيت كذلك مدة تزيد على أربعين سنة، ثم شرعوا في تحصينها والبناء بها، ولم يزالوا مقيمين بها إلى حدود سنة 1154هـ."},{"id":3476,"era":"c9","t":"وفاة المؤرخ ابن تغري بردي .","s":"هو جمال الدين أبو المحاسن يوسف ابن الأمير سيف الدين تغري بردي بن عبد الله الظاهري الحنفي، ولد في القاهرة سنة 813، كان أبوه من مماليك الظاهر برقوق ومن أمراء جيوشه، بل صار نائب دمشق في آخر حياته وتوفي فيها، وتفقه ابنه جمال الدين وقرأ الحديث وبرع في التاريخ، وامتاز به واشتهر بتآليفه التاريخية التي منها: النجوم الزاهرة في ملوك مصر والقاهرة، ومنها حوادث الدهور في مدى الأيام والشهور، وله المنهل الصافي و"},{"id":3477,"era":"c9","t":"قيام دولة بني وطاس بالمغرب خلفًا لدولة بني مرين .","s":"كان بنو وطاس فرقة من بني مرين غير أنهم ليسوا من بني عبد الحق، ولما دخل بنو مرين المغرب واقتسموا أعماله كان لبني وطاس بلاد الريف، فكانت ضواحيها لنزولهم وأمصارها ورعاياها لجبايتهم، وكان بنو الوزير من بني وطاس يتطلعون إلى الرياسة ويسعون في الخروج على بني عبد الحق، وقد تكرر ذلك منهم، ثم أذعنوا إلى الطاعة وراضوا أنفسهم على الخدمة، فاستعملهم بنو عبد الحق في وجوه الولايات والأعمال واستظهروا بهم على أمور "},{"id":3478,"era":"c9","t":"العثمانيون يستولون على قلعة وجزيرة آغريبوز في بحر إيجة .","s":"كان البابا بيوس الثاني ترأس اجتماع التحالف الذي عُقد في مدينة ريجنس بورغ في نيسان سنة 858 (1454م) بعد فتح محمد الفاتح القسطنطينية، وعاهدته على حرب العثمانيين ثلاثون دولة في أوربا وآسيا، ففي آسيا تحالفت دولة كرجستان جورجيا، ودولة الخرفان البيض آق قويونلو التركمانية المخالِفة للعثمانيين، والمسيطرة على إيران بزعامة حسن الطويل التتري أوزون حسن، ولكن محمد الفاتح لم يهتز لذلك التحالف، بل صمم على المواجه"},{"id":3479,"era":"c9","t":"استيلاء البرتغال على مدينة آصيلا بالمغرب .","s":"استولى الفرنج البرتغال على آصيلا بالمغرب وظفروا فيها ببيت مال الوطاسي، وأسروا ولده محمدًا المدعو بالبرتغالي وابنته وزوجتيه وجماعة من الأعيان، وكان الخَطْبُ عظيمًا، وتمكن أبو عبد الله محمد الشيخ الوطاسي من عقد هدنة افتك فيها أهل بيته عدا ولده بقي عند البرتغال سبع سنين ثم افتكَّه والده بعدُ وكان يوم أُسر صبيًّا صغيرًا"},{"id":3480,"era":"c9","t":"وفاة الأمير يحيى بن يشبك المؤيدي .","s":"هو الأمير يحيى ابن الأمير الخير الفقيه يشبك المؤيدي سبط السلطان المؤيد شيخ، ولد في ربيع الأول سنة 842, وأمه الخوند آسية بنت السلطان شيخ كانت خيِّرة ديِّنة، عارفة بطرائق الخوندات، ولها شهرة وذكر. مات أبوها السلطان المؤيد وقد زادت على أربع سنين. فتزوجها أبوه الأمير الخير الفقيه يشبك وهو من موالى أبيها بعد موته، وكان لالتها - مربيها- نشأ يحي في عز, فقرأ القرآن واشتغل يسيرًا وجوَّد الكتابة عند البرهان"},{"id":3481,"era":"c9","t":"وفاة الصوفي برهان الدين إبراهيم المتبولي .","s":"هو الصوفي إبراهيم بن علي بن عمر برهان الدين الأنصاري المتبولي ثم القاهري الأحمدي، قدم من بلده متبول من الغربية إلى طنطا، فأقام بضريحها مدة ثم تحول إلى القاهرة ونزل بظاهر الحسينية، فكان يدير بها مزرعة ويباشر بنفسه العمل فيها من عزق وتحويل وغير ذلك من مصالحها، وكان يجتمع إذ ذاك بالشيخ إبراهيم الغنام ونزل بزاوية هناك بدرب التتر، تعرف بالشيخ رستم ثم قطن زاوية غيرها بالقرب من درب السباع، وصار الفقراء ي"},{"id":3482,"era":"c9","t":"معركة أوطلوق بلي بين العثمانيين وبين التحالف الآسيوي الأوربي .","s":"تعاهدت ثلاثون دولة أوربية وأسيوية ضد العثمانيين سنة 872 في الثاني من شباط/ فبراير (1468م)، وحاولت قوات التحالف ضم مملكة المماليك المصرية السورية إليهم، ولكن دولة المماليك رفضت ذلك؛ لاشتراكهم مع العثمانيين بالدين والمذهب، وعبأت دول التحالف قواها العسكرية، وخاضت ضد العثمانيين معارك فاشلة، ثم تعاهدت على خوض المعركة العمومية الكبرى بحرًا وبرًّا، وبدأت المعارك البحرية ضد العثمانيين في سواحل البحر الأبي"},{"id":3483,"era":"c9","t":"انقسام دولة بني نصر في غرناطة .","s":"قامت في مالقة ثورة ولم يُفلح ملك بني نصر الأمير أبو الحسن علي بن سعد من إخمادها، وانتهت هذه الثورة بتقسيم المملكة إلى شطرين؛ شطر يملكه أبو الحسن، وشطر يملكه أخوه الثائر عليه أبو عبد الله محمد بن سعد الملقب بالزغل، وكان ملك قشتالة يبارك هذه الحروب؛ مما أمكنه من الاستيلاء على بعض المواقع والحصون القريبة من غرناطة."},{"id":3484,"era":"c9","t":"محمد الفاتح يوالي انتصاراته فيطرد الجنويين من شبه جزيرة القرم .","s":"عرض السلطان محمد الفاتح سنة 878 على أمير البغدان استيفان الرابع الجزيةَ؛ حتى لا يحاربه، فلم يقبل الأمير فأرسل إليه جيشًا وانتصر عليه بعد حروب عنيفة، ولكن لم يستطع فتح الإقليم، فعزم السلطانُ على دخول القرم للإفادة من فرسانها في قتال البغدان، وتمكَّن من احتلال أملاك الجنويين الممتدة على شواطئ شبه جزيرة القرم ويطردهم منها، ولم يقاوم التتار سكان القرم العثمانيين، بل دفعوا لهم مبلغًا من المال سنويًّا، "},{"id":3485,"era":"c9","t":"توقيع حاكم شبه جزيرة القرم معاهدة مع السلطان محمد الفاتح .","s":"وقَّع حاكم شبه جزيرة القرم معاهدة مع السلطان العثماني محمد الفاتح تنصُّ على خضوع شبه جزيرة القرم للعثمانيين، شريطة أن يقوم العثمانيون بتعيين الحاكم من سلالة جنكيز خان، وأن يدعو لخان القرم في الصلاة بعد الدعاء للخليفة العباسي والسلطان العثماني."},{"id":3486,"era":"c9","t":"هزيمة العثمانيين في معركة فاسلوي  .","s":"أراد السلطان فتح بلاد البغدان، فأرسل إليها جيشًا بعد أن عرض دفع الجزية على أميرها المسمى استيفان الرابع ولم يقبل. فوقعت معركة عنيفة بين الطرفين عُرفت بمعركة فاسلوي، وصل عدد الجنود العثمانيين إلى 120 ألف جندي، بينما بلغ عدد الجنود البغدان 40 ألف جندي، بالإضافة إلى بعض القوات المتحالفة الأصغر حجمًا وبعض المرتزقة, وبعد قتال عنيف قُتِلَ فيه جنود كثر من الجيشين المتحاربين، انهزم الجيش العثماني وعاد دون"},{"id":3487,"era":"c9","t":"استقرار حكم بني نصر في غرناطة على يد الأمير علي بن سعد .","s":"كان الأمير أبو الحسن علي بن سعد بعد وفاة والده محجورًا عليه، والأمر كان للقوَّاد ولم يكن له من الملك إلا اسمه، فأراد أن يقوم بنفسه ويزيل عنه الحَجر، فانفرد بنفسه عن قواده كما انفرد معه بعضهم، ووقعت بينهم حروب وأحداث؛ وذلك أنه لما اعتزل عن قواده أخذوا أخاه محمد بن سعد الملقب بالزغل, وكان أصغر منه سنًّا فبايعوه، واشتعلت نار الفتنة بينهم, فأظهر أبو الحسن التوبة للناس ووعدهم إن قاموا معه أن يصلح شأنهم"},{"id":3488,"era":"c9","t":"تأسيس محاكم التفتيش في إسبانيا .","s":"ظهرت فكرة محاكم التفتيش في القرن الثالث عشر الميلادي مع تزايد غطرسة الكنيسة الكاثوليكية واجتهادها في مراقبة ضمائر الناس في الدول التي كانت تحت سيطرتها، فكان بابا روما يكلف بعض الأساقفة بتعقب من كانت أفكاره مخالفة لتعاليم الكنيسة وطبق هذا النظام في البداية في إيطاليا وفرنسا وألمانيا حيث كان يتجول مندوبو البابا في أنحاء البلاد لتقصي أخبار الناس واتهام كل مخالف بالكفر ثم القبض عليه ومعاقبته, وكانت تُ"},{"id":3489,"era":"c9","t":"حادثة سيل غرناطة العظيم \n  .","s":"كان من قضاء الله عز وجل وما قدَّره في آخر أيام مهرجان كبير عند أهل غرناطة حيث يجتمع فيه جُل أهل غرناطة من رجال ونساء وصبيان وشيوخ وكهول وكثير من أهل القرى حول غرناطة للنزهة، فاجتمعوا في السبيكة من الحمراء وما حولها وامتلأت تلك المواضع بالخلق الكثير، وأقبلت الفرسان وصاروا يتألفون في السبيكة وذلك وقت الضحى، فبينما الناس كذلك في المهرجان إذا بسحابة عظيمة قد أنشأها الله تعالى في السماء فأرعدت وأبرقت و"},{"id":3490,"era":"c9","t":"السلطان محمد الفاتح يجبر إمارة البندقية على توقيع معاهدة إستانبول .","s":"أجبر السلطان محمد الفاتح إمارة البندقية على توقيع معاهدة إستانبول، التي انسحبت- بناء على شروطها- من حرب العثمانيين، وفرضت عليها غرامات الحرب، وجزية سنوية. وكانت هذه المعاهدة أولَ خطوة خطَتْها الدولة العثمانية للتدخل في أوربا، وكانت البندقية أهمَّ دول أوربا من الناحية التجارية."},{"id":3491,"era":"c9","t":"استسلام مدينة أشكودرا للسلطان محمد الفاتح .","s":"استسلمت مدينة أشكودرا الواقعة في شمال ألبانيا والتي كانت خاضعة لحكم البنادقة إلى السلطان العثماني محمد الفاتح؛ حيث استخدم الفاتح في حصارها أنواعًا جديدة من الأسلحة النارية والمدافع الضخمة، وكانت حملة أشكودرا هي آخر حملات السلطان محمد الفاتح التي بلغت 25 حملة سلطانية كبرى."},{"id":3492,"era":"c9","t":"وفاة الخليفة العباسي المستنجد بالله يوسف وتولي ابن أخيه المتوكل .","s":"هو الخليفة العباسي المستنجد بالله أبو المحاسن يوسف بن المتوكل على الله محمد بن المعتضد توفي في الرابع عشر محرم بعد أن أصابه الفالج الذي بقي بسببه مريضًا مدة شهرين، فكانت مدة خلافته قرابة الخمس وعشرين سنة إلا خمسة أشهر، ثم تم تولية ابن أخيه عبد العزيز بن يعقوب بن محمد المتوكل الخلافة وتلقيبه بالمتوكل على الله."},{"id":3493,"era":"c9","t":"محمد الفاتح يستولي على الجزر بين اليونان وإيطاليا .","s":"صالَحَ السلطان محمد الفاتح البنادقة وانهزم أمام المجر عندما سار لفتح ترانسلفانيا، ولكنه في البحر فتح الجزر التي بين اليونان وإيطاليا كما فتح مدينة أوترانتو في جنوبي شبه جزيرة إيطاليا، وحاصر أيضًا جزيرة رودوس، لكن لم يتمكن من فتحها، وكل ذلك كان في هذا العام."},{"id":3494,"era":"c9","t":"وفاة العلامة برهان الدين البقاعي الشافعي .","s":"هو الشيخ الإمام القدوة العلامة المحدِّث المفسِّر المؤرِّخ برهان الدين أبو الحسن إبراهيم بن عمر بن حسن الرباط بن علي الشافعي، البقاعي الأصل، نسبة إلى سهل البقاع في سوريا، ولد سنة 809, وهو من أعيان جماعة شيخ الإسلام ابن حجر، سكن دمشق، قال البقاعي: \"في ليلة الأحد تاسع شعبان سنة 821 أوقع ناسٌ من قريتنا خربة روحًا من البقاع يقال لهم: بنو مزاحم بأقاربي بني حسن من القرية، فقتلوا تسعة أنفس، منهم والدي عمر"},{"id":3495,"era":"c9","t":"وفاة السلطان العثماني محمد الفاتح وتولي ابنه بايزيد الثاني .","s":"هو السلطان المجاهد الغازي أبو الفتوحات: محمد بن السلطان مراد الثاني ابن السلطان محمد ابن السلطان بايزيد ابن السلطان مراد الأول بن أورخان بن عثمان، تنازل له أبوه بالملك سنة 848 لكنه لم يستقر فيه إلا بعد وفاة أبيه سنة 855. اقتفى أثر أبيه في المثابرة على دفع الفرنج حتى فاق ملوك زمانه، مع وصفه بمزاحمة العلماء، ورغبته في لقائهم، وتعظيم من يَرِدُ عليه منهم، وله مآثر كثيرة من مدارس وزوايا وجوامع، كان مُل"},{"id":3496,"era":"c9","t":"الخلاف بين الأخوين بايزيد بن محمد الفاتح وأخيه جم .","s":"بعد أن توفِّي السلطان العثماني محمد الفاتح كان كلٌّ من ولديه بعيدًا عنه، فالأوَّلُ بايزيد وهو الأكبر كان حاكمًا لمقاطعة أماسيا، وكان الآخر جم حاكمًا لقرمان، وكانت رغبة الصدر الأعظم قرماني محمد باشا في تولية الأمير جم؛ لذا أرسل إليه من يخبره بوفاة أبيه كي يأتي بأسرع وقت لتسلم الأمر، غيرَ أن حاكم الأناضول سنان باشا علم بالأمر فقتل رسول الصدر الأعظم حيث كانت رغبة الانكشاريين مع بايزيد؛ ولذلك لما علمو"},{"id":3497,"era":"c9","t":"قيام الدولة الروسية القيصرية وطرد المغول من أراضيها .","s":"استطاع الدوق إيفان الثالث أن يرقى على عرش روسيا بعد أن ضم الأمراء الروس إليه وجمعهم حوله، ثم جهز حملة قوية قاتل بها المغول في معركة جرت حول نهر أوكا وتمكَّن فيها من تحطيم المغول وهم يتقدمون إلى موسكو مستغلًّا ما بين قبائلهم من خلاف، فتحرر الروس من المغول وتلقَّب إيفان بالقيصر."},{"id":3498,"era":"c9","t":"حدوث خسف في مدن وقرى ببلاد الروم .","s":"حصل خسف في بلاد الروم (بلاد ابن عثمان) في ثلاث مدن وقرى، وقيل في خمسة."},{"id":3499,"era":"c9","t":"احتراق غالب الحرم النبوي .","s":"نزلت صاعقة على هلال المئذنة تجاه الحجرة النبوية، ثم على سطح المسجد، فاحترق بنارِها المسجِدُ الشريف النبوي؛ سَقفُه، وحواصلُه، وخزائِنُ كتُبِه، وربعاته، ولم يبقَ من قناطره وأساطينه إلَّا اليسيرُ، وكانت آيةً من آيات الله تعالى.، وصعدت الرأس إلى الريس- وكان من أهل العلم - بالمئذنة فاحترق، واحترق في الحرم عالمٌ آخر خرج من بيته لطلب ولدِه، وصل الخبرُ من المدينة المشرَّفة بمحضر يكتتب بالكائنة التي اتفقت "},{"id":3500,"era":"c9","t":"استيلاء الفرنج على مدينة الحامة في غرناطة .","s":"بدأ ملك الأمير أبي الحسن علي بن سعد ملك غرناطة في التقهقر والانتكاس والانتقاض. من وقت السيل العظيم سنة 883 الذي أصاب غرناطة؛ وذلك أن الأمير اشتغل باللذات والانهماك في الشهوات واللهو بالنساء المطربات، وركن إلى الراحة والغفلات، وضيع الجند وأسقط كثيرًا من نجدة الفرسان وثقَّل المغارم وكثَّر الضرائب في البلدان ومكَّس الأسواق ونهب الأموال وشحَّ بالعطاء، إلى غير ذلك من الأمور التي لا يثبت معها المُلك, وك"},{"id":3501,"era":"c9","t":"تمرد ابني ملك غرناطة في أخطر مراحل وجود المسلمين في الأندلس  .","s":"كان الأمير أبو الحسن علي بن سعد ملك غرناطة متزوجًا بعائشة الحرة ابنة عمه الأمير محمد الأيسر وله منها ولدان محمد ويوسف, وكان من جملة انهماك الأمير أبي الحسن في الملذات أنه اصطفى على زوجته رومية اسمُها ثريا وهجر ابنة عمه وأولادها منه، فأدرك ابنة عمه من الغيرة ما يدرك النساء على أزواجهن، ووقع بينهما نزاع كثير وقام الأولاد محمد ويوسف مع أمهما وغلظت العداوة بينهم، وكان الأمير أبو الحسن شديد الغضب والسط"},{"id":3502,"era":"c9","t":"موقعة لوشة العظيمة وانتصار المسلمين فيها .","s":"لما رأى فرديناند الخامس ملك قشتالة أن المسلمين قد عجزوا عن أخذ الحامة ونصرة من فيها من الأسارى، وقع له الطمع في بلاد الأندلس، فأخذ في الاستعداد والخروج إليها. طلب فرديناند الخامس من أبي عبد الله محمد بن سعد الملقب بالزغل أمير مالقة إمضاء معاهدة يكون فيها أمير مالقة تابعًا لقشتالة، فرفض ذلك أمير مالقة، فقام ملك قشتالة بإعلان الحرب عليه, فلما كان جمادى الأولى من هذا العام خرج ملك قشتالة بحملة عظيمة،"},{"id":3503,"era":"c9","t":"تنازل الأمير أبو الحسن ملك غرناطة عن الملك لابنه أبي عبد الله .","s":"لما فقد الأمير أبي الحسن علي بن سعد بصَرَه، تنازل عن المُلك لابنه أبي عبد الله محمد الثاني عشر الملقب بأبي عبد الله الصغير، الذي كان قد ثار على أبيه السنة الماضية, وبعد أن تولى الحكم قام بانتهاز فرصة هزيمة الإسبان أمام أمير مالقة عمه أبي عبد الله الزغل, فخرج بقواته واتجه إلى قرطبة، مجتاحًا في طريقه عدة حصون وهزم الإسبان في عدة معارك محلية، وحين عودته وبيده الغنائم الكثيرة أدركه الإسبان وقاتلوه مرة"},{"id":3504,"era":"c9","t":"ثلوج بالأحساء تسبب معوقات في أثناء عودة الحجيج .","s":"حصل على الحجيج في وقت رجوعهم للأحساء مشقة عظيمة، لم يُعهَدْ مِثلُها؛ وذلك بسبب الثلج الذي نزل عليهم، وقُتِلَ به خلق كثير وجِمال، وذهب للناس أموال لا تعَدُّ ولا تحصى."},{"id":3505,"era":"c9","t":"الإفراج عن ملك غرناطة المأسور وعقد صلح بشروط مع القشتاليين .","s":"كان الإسبان قد أسروا الملك أبا عبد الله محمد الصغير، وفي هذه السنة تم فك أسره بسعاية أمِّه الأميرة عائشة الحرة، بعد مفاوضات انتهت بعقد معاهدة مع ملك قشتالة تقتضي دفع غرامة مالية باهظة، والإفراج عن الأسرى الإسبان، وأن يكون الملك أبو عبد الله الصغير تحت حكم قشتالة وحكم ملكها فرديناند إلى غير ذلك من شروط مهينة، تحقِّقُ سياسة الاستيلاء على غرناطة."},{"id":3506,"era":"c9","t":"وفاة الشيخ المحب أبو الفضل محمد ابن الشِّحْنَة الصَّغير\n  .","s":"هو الشيخ العلَّامة أبو الفضل المحبُّ محمد بن محمد أبو الوليد بن محمد بن محمود بن غازي بن أيوب بن محمود الثقفي، الحلبي، الحنفي ابن الشحنة الصغير، عالم الحنفية بحلب. ولد سنة 804, والشحنة هو جدُّه الأعلى محمود الأول كان شحنة حلب ووالده أبو الوليد المتوفى سنة 815 يعرف أيضًا بابن الشحنة. كان المحبُّ هذا عالِمًا فاضلا، عارفًا بالفنون له وجاهة ورياسة، وولي الوظائف الجليلة، ولِيَ قضاء العسكر بحلب ثم قاضي "},{"id":3507,"era":"c9","t":"استيلاء الإسبان على مدينة رندة .","s":"قام الفرنج الإسبان بالهجوم على مدينة رندة فحاصروها وقذفوها بالنفط وهدموا أسوارها، فاضطرت المدينة للاستسلام، وغادر أهلها منها فاستولى الإسبان على سائر الأماكن والحصون الواقعة في تلك المناطق، وعاثوا فيها نهبًا وقتلًا وسلبًا، وكان هذا الاستيلاء هو بمثابة تحطيم وسائل الدفاع في المنطقة الغربية من غرناطة."},{"id":3508,"era":"c9","t":"وفاة السلطان الغالب بالله علي بن سعد صاحب غرناطة .","s":"هو السلطان الغالب بالله أبو الحسن علي بن سعد بن محمد بن الأحمر الأرجواني، الأندلسي، الغرناطي، الأنصاري، المصري ملك الأندلس وصاحب غرناطة. ومولده قبيل سنة840. خرج على والده سعد واستولى على ملك غرناطة سنة 868 ونفا والده إلى المرية ومات من سنته، ومنذ البداية، دخل أبو الحسن في حروب مع أخويه، أبو الحجاج يوسف وأبو عبد الله محمد الزغل، اللذين نازعاه الملك، كل على حدة. ولما توفي أبو الحجاج بقي أبو عبد الله"},{"id":3509,"era":"c9","t":"مسلمو إسبانيا يستنجدون بالمماليك والعثمانيين .","s":"تطورت الأحداث في بلاد الأندلس، وأصبح اهتمام الإسبان هو توحيد أراضيهم، وانتزاع ما تبقى للمسلمين بها خصوصًا بعدما خضع الإسبان لسلطة واحدة بعد زواج إيزابيلا الكاثوليكية المتعصبة ملكة قشتالة من فرديناند ملك أراغوان، وبعد هلاك الدون جويان الثاني ملك أراغون، وتولَّى مكانه ابنه فرديناند الكاثوليكي، ضمَّ أراغون وبلنسية وصقلية وميورقة إلى قشتالة، وبينما كانت الممالك النصرانية تتَّحد في تلك الأقطار، كانت ال"},{"id":3510,"era":"c9","t":"أمراء بني نصر يتناوشون على عرش الملك .","s":"قام الأمير يوسف أبو الحجاج بن أبي الحسن علي بن سعد أمير المرية بمنازعة عمه أبي عبد الله الزغل ملك غرناطة، فقام القتال بينهما وقتل أمير المرية، ثم نازعه ابن أخيه الآخر عبدالله الصغير محمد الثاني عشر العائد من الأسر يريد استعادة ملكه الذي كان فيه قبل أن يؤسر، فأعلن نفسه ملكًا على غرناطة وقام بنصرته أهل ربض البيازين وهو حي غرناطة الشعبي، وأهله عرفوا بالاضطراب الدائم، كما أمده ملك قشتالة بقوة، فتمكن م"},{"id":3511,"era":"c9","t":"الفتنة بين أمراء بني نصر في الأندلس .","s":"بعد القتال الذي دار بين أمراء بني نصر على الملك، بقيت هذه الفتنة بينهم إلى أن تم الاتفاق على أن تنقسمَ المملكة إلى قسمين؛ القسم الأول: وهو غرناطة ومالقة، يكون تحت ملك أبي عبد الله محمد بن سعد المعروف بالزغل، والقسم الثاني: وهو القسم الشرقي يكون تحت ملك ابن أخيه محمد بن علي المعروف بأبي عبد الله الصغير، ولكن هذا الأخير لم يلبث أن نقض الاتفاق وظهر فجأة في ساحة البيازين بغرناطة، وأذاع عقده للصلح مع ا"},{"id":3512,"era":"c9","t":"أول هزيمة عثمانية أمام مماليك السلطان قايتباي  .","s":"حدثت معارك بين العثمانيين والمماليك على الحدود الشامية، إلا أنها لم تحتدم إلى حد التهديد بحدوث حرب شاملة بينهما، حيث استطاع قائد الجيوش المملوكية الأمير أزبك أن يأسر القائد العثماني أحمد بك بن هرسك، فأسهمت هذه الحرب في الشعور بعدم الثقة بينهما، الأمر الذي أدى إلى تعثر مفاوضات الصلح سنة 896. حتى إن السلطان المملوكي \" قايتباي\" قد ساورته مخاوف من احتمال قيام حرب واسعة بينه وبين العثمانيين؛ سواء لإدرا"},{"id":3513,"era":"c9","t":"استيلاء النصارى على مدينة لوشة  .","s":"بينما المسلمون في الأندلس بين حرب وصلح فيما بينهم إذ بصاحب قشتالة قد أقبل بحملته على مدينة لوشة, فنزل فيها الأمير محمد بن علي أبو عبد الله الصغير ومعه جماعة من أهل نجدة البيازين حين سمعوا بقدوم النصارى عليها، فتحصنوا بها مع أميرهم محمد ابن علي فحاصرها العدو حصارًا شديدًا ونصب عليها أنفاطه وعدته واقترب إليها بجيشِه وآلة حربه، حتى دخلوا ربضَها وهدموا بعض أسوارِها بالأنفاط، وقتل كثير من نجدة الرجال و"},{"id":3514,"era":"c9","t":"ملك قشتالة يحتل مدينة بلش  .","s":"لما كان النصف من شهر ربيع الثاني من هذا العام خرج ملك قشتالة إلى أرض المسلمين قاصدًا مدينة بلش مالقة، فلما سمع ملك غرناطة محمد الزغل بنزوله على مدينة بلش ندب أهل غرناطة ومن أطاعه من أهل تلك الجهات وترك طائفةً تقاتل أهل البيازين، وخرج يريد نصرة أهل بلش، وذلك يوم السبت الرابع والعشرين لربيع الثاني من عام التاريخ، فلما سار قريبًا منها وجد العدو قد سبقه بالنزول عليها، ودار بها من كل الجهات فقصد الأمير"},{"id":3515,"era":"c9","t":"استيلاء الإسبان على مالقة وقتلهم النساء والأطفال .","s":"لما استخلص ملك قشتالة الملك فرديناند مدينة بلش سار بحملته نحو مدينة مالقة فنزل عليها وقاتلها قتالًا شديدًا وحاصرها حصارًا عظيمًا لم يُرَ مثلُه، وأحاط بها من كل جانب ومكان برًّا وبحرًا، فتحصن أهل مالقة ببلدهم وأظهروا ما كان عندهم ومعهم من السلاح والعدة والأنفاط، وكان فيهم جملة من نجدة الفرسان فقاتلوا الروم قتالًا شديدًا، وقتلوا منهم خلقًا كثيًرا، حتى إنه قُتل من الروم في يوم واحد اثنا عشر ألفًا وسب"},{"id":3516,"era":"c9","t":"غلاء أسعار القمح والشعير بدمشق .","s":"غلا سعر القمح والشعير، وبرز مرسومُ الحوَّاط بالمناداة بدمشق، بأن لا يبيع حاضر لجلَّاب قمحًا ولا شعيرًا، فتخبَّطت دمشق، وزادت الأسعار وصَغُرت قطع الخبز، وطلبه الناس، وبيعت غرارة القمح بأربعمائة وعشرين درهم، والشعير بمائة وسبعين!!"},{"id":3517,"era":"c9","t":"زحف الإسبان على غرناطة وبدأ حصارها .","s":"طلب الإسبان من أبي عبد الله محمد الصغير أن يضعوا قواتٍ لهم في الحمراء فرفض أبو عبد الله الصغير هذا الطلب ومنعهم من دخول غرناطة، فقام ملك قشتالة فرديناند بالزحف بقواته على أطراف غرناطة الشرقية واستولى في طريقه على بعض المدن، ومنها المنكب والبيرة وبلش وغيرها من القواعد الشمالية، مكملًا مسيرته إلى غرناطة التي بدأ يحاصرها، واستمر الحصار إلى سنة 895."},{"id":3518,"era":"c9","t":"نهاية دولة الحفصيين بالمغرب .","s":"توفي الأمير أبو عمرو عثمان بن محمد الحفصي وقام خلفًا عنه حفيده أبو زكريا يحيى بن مسعود بن محمد، وكان عثمان هذا آخر الحفصيين الكبار والذي بوفاته تعتبر الدولة الحفصية قد انتهت؛ وذلك أن سكان جزيرة جربة رفضوا الاعترافَ بالأمير الجديد يحيى وبسيادة الحفصيين عليهم، فشكَّلوا جمهورية مستقلة فحذت مدينة طرابلس حذوَهم وقاموا هم أيضًا بالتخلص من الحفصيين."},{"id":3519,"era":"c9","t":"هزيمة العثمانيين الثانية أمام مماليك السلطان قايتباي .","s":"كانت الحرب الأولى للعثمانيين مع المماليك في سنة 891 حيث أُسِرَ فيها القائد العثماني أحمد بك بن هرسك، فأراد السلطان العثماني بايزيد الثاني الثأرَ فجهَّز جيوشًا برية وبحرية وانضم للماليك زعيم الآق قوينلو، ثم أراد السلطان المملوكي قايتباي أن يصلحَ الأمر فأطلق سراح الأسارى العثمانيين، ومنهم أحمد هرسك، ولكن هذا لم يُجدِ نفعًا, فنجح قائد الجيوش المملوكية الأمير أزبك في الوصول إلى أذنة ومن معه من القوات "},{"id":3520,"era":"c9","t":"الأمير أبو عبد الله الزغل يبايع ملك قشتالة ونكايته بالمسلمين .","s":"بعد سيطرة فرديناند على بسطة أهم مدن شرق غرناطة التي كانت تحت حكم الأمير أبي عبد الله محمد بن سعد الزغل خرج الأمير الزغل من مدينة وادي آش تابعًا لصاحب قشتالة، فلما لحقه بايعه ودخل في ذمتة وتحت طاعته على أن يعطيه مدينة وادي آش وكل مدينة وحصن وقرية كانت تحت طاعته وحكمه، فأجابه إلى مطلبه ورجع معه إلى وادي آش وهو فرح مسرور، فدخلها العدو وقبض قصَبَتها واستولى عليها في العشر الأُوَل من شهر صفر، ودخل في ذ"},{"id":3521,"era":"c9","t":"حصار الفرنج مدينة بسطة أهم مدن الزغل ثم استسلامها لهم .","s":"خرج فرديناند ملك قشتالة بحملته وعُدَّته، وقصد نحو حصن موجر فحاصره وقاتله قتالًا شديدًا، فاستولى عليه، ثم استولى على الحصون القريبة منه, ثم قصد مدينة بسطة أهم مدن الأمير أبي عبد الله الزغل في شرق غرناطة فنزل قريبًا منها فوجد بلدًا مقيمًا بالخيل والرجال والعدة والطعام، فكلما قرب من البلد وأراد قتال المسلمين رجع خاسرًا وقُتل منه خلق كثير ولم يقدر أن يمنع داخِلَها وخارجها كما فعل بغيرها من المدن، وكان"},{"id":3522,"era":"c9","t":"حمد الشيخ الوطاسي يضم مدينة فاس لحكمه .","s":"لما أحسَّ محمد الشيخ الوطاسي حاكم آصيلا من نفسه القدرة على الاستيلاء على كرسي فاس وتنحية الشريف أبي عبد الله الحفيد الإدريسي عنه- لا سيما مع ما كان الناس فيه من افتراق الكلمة- فجمع جندًا صالَحَها وزحف إلى فاس فبرز إليه الشريف والتقوا بأحواز مكناسة، فوقعت بينهما حرب عظيمة كانت الكرَّة فيها على الوطاسي، ثم جمع عسكرًا آخر وزحف به إلى فاس وحاصرها نحو سنتين والشريف فيها مع أرباب دولته، وفي أثناء الحصار"},{"id":3523,"era":"c9","t":"توقيع الصلح بين المماليك والعثمانيين .","s":"بعد أن بقيت العلاقات بين الطرفين متوترة واستطاع المماليك أن يُلحقوا الهزيمة بالعثمانيين ثلاث مرات آخرُها سنة 895 حيث أرسل قايتباي حملة بقيادة الأمير أزبك الذي وصل إلى كولك، وكان قد أمره قايتباي أن يحاول الصلح والسلم، فدخل أوزبك الأراضي العثمانية عن طريق حلب، فأرسل ماماي الخاصكي إلى المعسكر العثماني من أجل الصلح، ولكنه لما استبطأه دخل إلى العمق وبدأ بالنهب والحرق واستولى على قلعة كوارة وعاد إلى الق"},{"id":3524,"era":"c9","t":"وقوع ثلج كثير بدمشق وما حولها .","s":"وقع بدمشق وما حولها ثلج كثير، واستمرَّ إلى نصف النهار، فارتفع في الأسطح نحو ذراع، وتكسَّر بذلك كثير من الأشجار، سيما أشجار الزيتون، وكان الحطب قد غلا سعرُه وبلغ قنطار اليابس منه إلى نحو الثلاثين درهمًا، فرخُص سعرُه من يومئذٍ، واستمر الثلجُ في بعض الطرق وغيرها نحو عشرين يومًا، وكان آخره من مدينة زرع إلى مدينة حماة."},{"id":3525,"era":"c9","t":"نقض الملك فرديناند شروط تسليم غرناطة .","s":"كان الملك فرديناند قد أظهر للمسلمين في الأيام الأولى من تسليم غرناطة العناية والاحترام حتى كان النصارى يَغيرون منهم ويحسدونهم ويقولون لهم أنتم الآن عند ملكنا أعز وأكرم منا، ووضع عنهم المغارم وأظهر لهم العدل حيلة منه وكيدًا؛ ليغرَّهم بذلك وليثبطهم عن الجواز، فوقع الطمع لكثير من الناس، وظنوا أن ذلك يدوم لهم فاشتروا أموالًا رخيصة وأمتعة أنيقة وعزموا على الجلوس مع النصارى، ثم إن فرديناند أمر الأمير مح"},{"id":3526,"era":"c9","t":"قيام مملكة صنغاي الإسلامية غربي أفريقيا .","s":"تدفقت بعض القبائل المغربية وخاصة قبائل لمطة إلى الضفة اليسرى لنهر النيجر عند مدينة دندي، وسيطرت هذه القبائل على الزرَّاع من أهل صنغي الذين رحَّبوا بهم ليحموهم من الصيادين الذين كانوا يعتدون عليهم، ونجح هؤلاء الوافدون الجدد في تكوين أسرة حاكمة استفادت من علاقاتها التجارية مع غانة وشمال أفريقيا، وكان لهذه العلاقة أثر بعيد في تحويل ملوك صنغي إلى الإسلام وانتشاره في غربي قارة أفريقيا. كانت صنغاي في بد"},{"id":3527,"era":"c9","t":"سقوط غرناطة ونهاية حكم المسلمين في الأندلس .","s":"زحف الملك فرديناند ملك قشتالة على غرناطة سنة 895 وحاصرها وشدد الحصار عليها, وامتدَّ الحصار إلى هذه السنة وقعت خلاله ملاحم كثيرة، والمسلمون كانوا يلحُّون على حمايتها, فلم يزالوا يدافعون عنها ويقاتلون من قصَدَها حتى قصر عنها العدو؛ لكثرة ما قُتل له عليها من خيل ورجال، ولم تزل الحرب متصلة وقد أصيب فيها كثير من أنجاد فرسان المسلمين بالجراحات، واستشهد آخرون، ومن النصارى أضعاف ذلك, والمسلمون فوق ذلك صاب"},{"id":3528,"era":"c9","t":"رحلة فاسكو دي جاما إلى الهند بتكليف من ملك البرتغال .","s":"كلف ملك البرتغال مانويل الأول فاسكو دي جاما القيامَ برحلة للبحث عن طريق آخر يوصل بالهند دون المرور على بلاد المسلمين، فقام فاسكو بالسير جنوبًا بمحاذاة السواحل الغربية ووصل إلى رأس الزوابع في جنوب أفريقيا وسماها رأس الرجاء الصالح، ثم استدار شمالًا إلى السواحل الشرقية فوصل إلى موزمبيق وماليندي، وكانوا قد التقوا بسفن عربية أدهشتهم صناعتها، وكذلك أدوات الملاحة التي مع بحاريها من بوصلة وخرائط والمزاول،"},{"id":3529,"era":"c9","t":"وقوع ثلوج وغلاء في الأسعار بمصر .","s":"في هذه الأيام تضاعف وقوف حال الناس؛ بسبب كثرة وقوع الثلج والجليد من أول الأصم- رجب- إلى آخره، حتى وصل الثلج إلى مصر على ما قيل، وماتت دواب كثيرة، وغلا سعر اللحم حتى صار رطله بخمسة دراهم، وسعر القمح حتى صارت الغرارة بنحو الأربعمائة."},{"id":3530,"era":"c9","t":"نهب إبل بني مدلج من العرب في دمشق .","s":"دخل دمشق نهبُ إبل بني مدلج من العرب، قريب ألف ناقة وحمل وفصلان صغار، تجأر بصوتها الأمهات على أولادها، وأولادها على أمهاتها، حتى حزن الناس عليهم، ثم وضعوا في خان الجورة، وفارقوا بين الفصلان وأمهاتهم بالأكل والبيع، فزادوا في الجأر إلى الله، حتى سمعت من مكان بعيد، ولا حول ولا قوة إلا بالله، ودخل معهم عدة رؤوس مقطعة من عرب بني مدلج."},{"id":3531,"era":"c10","t":"طوفان عظيم من ناحية بحر الهند .","s":"حصل طوفان عظيم من ناحية بحر الهند غرق منه في بندر الديو عشرة مراكب، وفي الباحة أربعة مراكب، وتلف فيها من الأموال ما لا ينحصر، وتغيرت أربعة مراكب، وانكسرت أدقالهم، ورموا من حملهم أكثر من النصف."},{"id":3532,"era":"c10","t":"العثمانيون يسيطرون على البوسنة ودخول أمير البغدان في حمايتهم .","s":"بعد أن كانت العلاقات بين العثمانيين والبولنديين قد توطدت سنة 895 إلا أنها لم تلبث كثيرًا حتى بدأ الخلاف بينهما؛ بسبب الحماية على البغدان؛ فكل من الطرفين يدعي الحماية عليها، ولكن أمير البغدان اعترف بالحماية العثمانية، وحارب إلى جانب العثمانيين ضد البولنديين، واستطاعوا أن يصدوا البولنديين ويستولوا على البوسنة؛ مما أكسب الدولة العثمانية قوة إلى قوتها، فبدأ خصومها يتقربون إليها بعقد الحلف معها للإفادة"},{"id":3533,"era":"c10","t":"وفاة السلطان الأشرف قايتباي وسلطنة ابنه الناصر محمد .","s":"هو السلطان الأشرف قايتباي المحمودي، ويُذكر أن أصله شركسي الجنس، جُلب من بلاده إلى الديار المصرية في حدود سنة 839، فاشتراه الملك الأشرف برسباي، ولم يُجرِ عليه عتقًا، وجعله بطبقة الطازية من أطباق قلعة الجبل إلى أن مَلَكه الملك الظاهر جقمق، وأعتقه. كانت مدة حكم الأشرف قايتباي حافلة بالحروب، وسيرتُه من أطول السير، وقد تعرضت البلاد في أيامه لأخطار خارجية، أشدها محاولة العثمانيين احتلال حلب وما حولها، ف"},{"id":3534,"era":"c10","t":"خلع السلطان الناصر محمد وتسلطن الأشرف قانصوه .","s":"بعد أن استطاع قانصوه من إقناع قايتباي بتولية ابنه محمد السلطنة؛ ليكون هو الوصي والأتابك للعساكر، أخذ يخطط ليتسلطن هو، فتخلص من الأمراء المنافسين له، ثم دعا الخليفة العباسي والقضاة الأربعة وأقنعهم بضرورة تغيير السلطان لخلاعته والفوضى التي سارت في البلاد، فتم خلعه وتولية قانصوه السلطنة، وتلقب بالملك الأشرف."},{"id":3535,"era":"c10","t":"خلع السلطان الأشرف قانصوه وإعادة الناصر محمد .","s":"بعد أن استطاع قانصوه أن يخلع السلطان محمد بن قايتباي، وأراد أن يتسلطن ولم يبق له إلا الركوب بشعار السلطنة والصعود إلى القلعة للجلوس على العرش، إلا أنه اصطدم بمعارضة المماليك السلطانية الذين رفضوا الاعتراف بخطوته التي فعلها، فمنعوه من دخول القلعة بعد قتال أمام أسوارها استمر ثلاثة أيام، حتى انهزم قانصوه وجُرح وهرب مع أتباعه إلى فلسطين، فقام الخليفة والقضاة بتجديد البيعة للسلطان محمد بن قايتباي."},{"id":3536,"era":"c10","t":"وفاة الإمام العلامة شمس الدين السخاوي .","s":"هو الإمام العلامة شمس الدين أبو الخير محمد بن عبد الرحمن بن محمد السخاوي القاهري أصله من سخا من قرى مصر، ولد بالقاهرة في ربيع الأول سنة 831 بحارة مجاورة لمدرسة شيخ الإسلام البلقيني محل أبيه وجده، ثم تحول منه حين دخل في الرابعة مع أبويه لمِلْك اشتراه أبوه مجاور لسكن شيخه ابن حجر، وأدخله أبوه المكتب بالقرب من الميدان عند المؤدب الشرف عيسى بن أحمد المقسي الناسخ، فأقام عنده يسيرًا جدًّا، ثم نقله لزوج "},{"id":3537,"era":"c10","t":"السلطانِ عامر بن عبد الوهاب يعزر رئيسَ الإسماعيلية بمدينة تعز .","s":"أمر السلطانُ عامر بن عبد الوهاب بتقييد رئيس الإسماعيليةِ سليمان بن حسن بمدينة تعز، وأودعه دار الأدبِ، وكان يتحدث بما لا يعنيه من المغيبات المستقبلات، وكان عالمَ الإسماعيلية، فأمر السلطانُ عامر بإحضار كتبِه وإتلافها، فأُتلِفت، والحمد لله."},{"id":3538,"era":"c10","t":"وفاة الخليفة المتوكل وتولي ابنه يعقوب .","s":"هو الخليفة المتوكل على الله عبد العزيز بن يعقوب بن محمد المتوكل، وكان قد بقي في الخلافة تسع عشرة سنة وأيامًا، وتولى بعده ابنه يعقوب وتلقب بالمستمسك بالله أبو الصبر."},{"id":3539,"era":"c10","t":"إعلان التنصير القسري لأهل الأندلس المسلمين .","s":"كان تسليم غرناطة للملك فرديناند ملك أراغون والملكة إيزابيلا ملكة قشتالة بناء على معاهدة، لكن فرديناند وزوجته لم يَفيَا بهذه العهود، بل أصدرت إيزابيلا قانونًا يقضي بإجبار المسلمين على التنصر وتحريم إقامة شعائرهم الدينية، وتأمر كذلك بإحراق الكتب الإسلامية في غرناطة, وبعد أن نقض فرديناند شروط تسليم غرناطة شرطًا شرطًا بدا بدعوة المسلمين إلى التنصر وأكرههم عليه فدخلوا في دينه كرهًا وصارت الأندلس كلها ن"},{"id":3540,"era":"c10","t":"مقتل السلطان الناصر محمد وتسلطن الظاهر قانصوه الأشرفي .","s":"أساء السلطان الناصر محمد السيرة حتى أفحش في السوء، فقتل الجواري وارتكب الفواحش وأساء التدبير، حتى تمالأ الأمراء على خلعه وقتله، ثم في اليوم الخامس عشر ربيع الأول من هذه السنة خرج من قصره فهجم عليه جماعة من المماليك فقتلوه بسيوفهم وعُمُره يومَها سبعة عشر عامًا، وتولى السلطنة بعده قنصوه الأشرفي الذي اتفق الأمراء على توليته السلطنة بعد قتل الناصر محمد، فبويع بالسلطنة وتلقب بالملك الظاهر أبي سعيد قانص"},{"id":3541,"era":"c10","t":"بايزيد الثاني يضم مدينة ليبانتو اليونانية ويواجه تحالفًا صليبيًّا .","s":"استطاع بايزيد أن يحرز نصرًا بحريًّا على البنادقة في خليج ليبانتو ببلاد اليونان, واستولى على مدينة ليبانتو، وباستيلاء العثمانيين على مواقع البنادقة في اليونان، أقام البابا إسكندر السادس- بناء على طلب البنادقة- حلفًا ضد العثمانيين مكونًا من فرنسا وإسبانيا، وتعرض العثمانيون لهجوم الأساطيل الثلاثة: الفرنسي والإسباني والبابوي، واستطاعت الدولة العثمانية أن تعقد صلحًا مع البنادقة."},{"id":3542,"era":"c10","t":"خلع السلطان الظاهر قانصوه الأشرفي وتسلطن الأشرف جانبلاط .","s":"قام الأمراء الذين ولَّوا الأشرف قانصوه السلطنة بخلعِه في هذه السنة، وكان قد هرب منهم ولكنهم قبضوا عليه فأُرسل إلى سجن الإسكندرية، ثم قُتل فيه خنقًا، فكانت مدة سلطنته سنة وثمانية أشهر، فبايعوا بعده جانبلاط الذي كان أتابك العساكر، فتلقب بالسلطان الأشرف أبي النصر جانبلاط."},{"id":3543,"era":"c10","t":"وفاة المعلم أحمد بن ماجد النجدي  .","s":"هو المعلم أسد البحر شهاب الدين أحمد بن ماجد بن محمد السَّعْدي النجدي، من نجد عُمان، ويقال له السائح ماجد، وهو من علماءِ فنِّ الملاحة وتاريخه عند العربِ، ومِن كبارِ ربابنةِ العرب في البحر الأحمر والخليج العربي والمحيط الهندي وخليج البنغال وبحر الصين. ولِدَ ابنُ ماجد عام 821هـ بنجد عُمان في عائلة تهتمُّ بركوب البحر، فكان أبوه وجَدُّه ملاحَينِ مشهورين، ولابن ماجد الفضلُ في إرساء قواعد الملاحة للعالم،"},{"id":3544,"era":"c10","t":"خلع السلطان الأشرف جانبلاط وتسلطن طومان باي .","s":"قام الأمير قوصروه نائب دمشق بالانشقاق والخروج عن طاعة السلطان الأشرف جانبلاط وأعلن نفسه سلطانًا فيها، لكن السلطان جانبلاط قام بتجهيز جيش بقيادة طومان باي ومعه الأمير قانصوه الغوري فسارا إلى الشام، ولما وصل طومان باي اتفق مع الأمير قوصروه على الخروج عن طاعة الأشرف جانبلاط، واتفقا على الغدر بالسلطان جانبلاط واتَّفقا على أن يسيرا معًا إلى مصر لقتال السلطان جانبلاط، فزحفا معًا وأعلنا خلع السلطان جانبل"},{"id":3545,"era":"c10","t":"وقوع وباء ومرض عظيم بمدينة زبيد باليمن .","s":"حصل بمدينة زَبيد مرض عظيم ومات بسببه خلائق لا يُحصَون، وكثر الوباء واستمر الدعاء لذلك في الصلاة والخطب، ودام ذلك إلى شهر ذي القعدة، واشتد في آخر شعبان ورمضان فبلغ الموتى بزَبيد في كل يوم فوق ستين نفسًا، وكان غالبه في النساء والأطفال، وانتقل إلى بوادي زبيد وحيس وموزع وغيرها."},{"id":3546,"era":"c10","t":"مقتل السلطان طومان باي وتسلطن الأشرف قانصوه الغوري .","s":"هو السلطان العادل طومان باي بعد أن تسلطن العادل طومان باي قام بعزل أنصار الأشرف جانبلاط وولَّى أنصاره هو، وقتل بعض الأمراء وقبض على آخرين وسجنهم، فأثار هذا حفيظة بعض الأمراء عليه، حتى الذين كانوا نصروه بالأمس على جانبلاط، فاتَّفَق الأمراء بقيادة قانصوه الغوري وقاموا بخلعِه فهرب العادل طومان باي، ولكنه قُبِض عليه ثم قُتِلَ بعد أن كانت مدة سلطنته ثلاثة أشهر وعشرة أيام، وكان قانصوه الغوري أولًا قد ها"},{"id":3547,"era":"c10","t":"محاولة البرتغال الاستيلاء على ساحل البريجة  .","s":"بعث ملك البرتغال منويل من دار ملكه أشبونة قوةً بحرية للاستيلاء على بعض ثغور المغرب، فألجأهم هيجان البحر وموجه إلى ساحل البريجة فيما بين آزمور وتيط، وكانت البريجة بناء متخذًا هنالك للحراسة ونحوها، وكان يسمى برج الشيخ، فنزلت طائفةٌ منهم إلى البر فتطوفوا بالبريجة وما حولها، وأعجبهم المكان فعزموا على المقام به وشرعوا في إدارة السور على قطعة من الأرض، فنذر بهم أهل تلك البلاد من المسلمين وتسابقوا إليهم "},{"id":3548,"era":"c10","t":"قيام الدولة الصفوية في بلاد فارس .","s":"قامت الدولة الصفوية الشيعية في تبريز من بلاد فارس بزعامة إسماعيل الأول بن حيدر بن إبراهيم بن جنيد الصفوي، كان جده إبراهيم شيخ الطريقة الصفوية فنُسب إليها، ويذكر أن مؤسس الطريقة أصلًا هو الشيخ صفي الدين إسحاق، وكان حسن الطويل التتاري زعيم القبيل الأبيض جده لأمه, فلما توفي الطويل سنة 883, شاعت الفوضى في بلاد فارس حتى استطاع إسماعيل الصفوي الاستيلاء عليها بعد معركة مشهورة جرت سنة 907, فاستطاع أن يقضي"},{"id":3549,"era":"c10","t":"فرض إسماعيل الصفوي التشيع على المسلمين السنة في إيران .","s":"بعد أن أعلن إسماعيل الصفوي قيامَ الدولة الصفويَّة وعاصمتها تبريز، كان أول عملٍ قام به هو إعلانَ أنَّ مذهبَ دولته هو مذهب الإماميَّة الاثني عشرية، وأنه سيعمِّمُه في جميع بلاد إيران، وعندما نُصِحَ أنَّ مذهب أهل إيران هو مذهب الشافعي لم يستجبْ لنصحِهم وهدَّد من لم يستجب لأمره بالتشيعِ، فإنَّ مصيره القتل, فأمر الخطباء في المساجد بسبِّ الخلفاء الراشدين الثلاثة، مع المبالغةِ في تقديسِ الأئمة الاثني عشر,"},{"id":3550,"era":"c10","t":"ترحيل ثلاثمائة ألف مسلم من الأندلس إلى شمال أفريقيا والشام .","s":"أصدرت الملكة إيزابيلا مرسومًا يقضي بتخيير المسلمين في الأندلس بين أن يتنصَّروا أو يرحلوا عن الأندلس، فرحل ما يقارب الثلاثمائة ألف مسلم من الأندلس من غرناطة إلى المغرب العربي، ومنها انتشروا في أفريقيا وبعضهم إلى الشام، بعد أن أمرت الملكة إيزابيلا بتحويل مساجدهم إلى كنائس."},{"id":3551,"era":"c10","t":"فتنة الجازاني والاعتداء على سكان مكة  .","s":"قام في ينبع الأمير دراج- جد الأشراف ذوي هجار القاطنين بينبع النخل- بدور نبيل في حفظ مدينة رسول الله صلى الله عليه وسلم من عبث أميرِها حسن بن الزبير الذي تهجم على مخزون الحجرة الشريفة، ودخل المدينة في ربيع الأول سنة 901 وسيطر على الأوضاع بالمدينة، واطمأن الناس بوصوله إليها. إلا أن هذا الأمير دراج توفي سنة 902، وتنازع أبناؤه على إمرة ينبع، فبرز منافس قوي من الأشراف لأبناء دراج على الإمارة فتح بابًا "},{"id":3552,"era":"c10","t":"وقوع حريق عظيم بمدينة عدن باليمن .","s":"احترق من مدينة عدن جانبٌ عظيم، من نصف الليل إلى قرب الفجر، وتلفت فيه بيوت كثيرة من بيوت التجار، وجانبٌ من السوق الكبير، وجانب من حافة اليهود، وحافة الحبوش بأسرها وأحدقت النار بالمدرسة السفيانية، وتلفت فيها أموال جليلة. ويقال: إنه بلغ عدد البيوت المحترقة تسعمائة بيت, وذهب في هذا الحريق من الأموال والأنفس ما لا يعلمه إلَّا الله تعالى."},{"id":3553,"era":"c10","t":"وفاة العلامة ابن المبرد الحنبلي .","s":"هو الشيخ الإمام العلامة المحدِّث المسنِد جمال الدين يوسف بن حسن بن أحمد الصالحي المعروف بابن المبرد، ويعرف أيضًا بابن عبد الهادي الدمشقي الصالحي الحنبلي المتقِن المتفنِّن، من فقهاء الحنابلة ومن أهل دمشق، ولد سنة 840 بالصالحية في دمشق، له مشاركة في عدة علوم، وله تصانيف كثيرة نحو الأربعمائة أكثرها بخطه، منها: مغني ذوي الأفهام في فقه الحنابلة, والإغراب في أحكام الكلاب, والجوهر المنضد في طبقات متأخري "},{"id":3554,"era":"c10","t":"عقد الدولة العثمانية صلحًا مع بعض الدول الأوربية. .","s":"عقدت الدولة العثمانية صلحًا مع كلٍّ من المجر، وفرنسا، وإنجلترا، وإسبانيا، والبرتغال، وبولونيا، ونابولي، ورودس، وأوجد هذا الصلح هدوءًا على الجبهة العثمانية الأوربية، استمر 20 عامًا، وقد خاضت خلالها الدولة العثمانية حروبًا ضارية في الشرق الإسلامي."},{"id":3555,"era":"c10","t":"اجتياح الإسبان والبرتغال سواحل المسلمين في شمال أفريقيا والخليج .","s":"أخذ الإسبان والبرتغال يجتاحون أطراف العالم الإسلامي ويؤسِّسون مراكزَ عسكرية ومخافرَ أمامية في بلاد المغرب شمال إفريقيا والخليج العربي؛ للضغط على سلطنة المماليك سياسيًّا وإرباكها في حماية الثغور وخطوط التجارة التقليدية في البحر المتوسط. فنجحت إسبانيا من جانبها في احتلال ميناء المرسى الكبير في الجزائر سنة 910 (1505م) ثم وهران سنة 913 (1508م) ثم بجاية سنة 1510م. ونجحت البرتغال من جانبها في الاستيلاء "},{"id":3556,"era":"c10","t":"هلاك إيزابيلا ملكة قشتالة ودورها في سقوط مملكة غرناطة .","s":"هي الملكة إيزابيلا بنت خوان الثاني ملكة قشتالة، الكاثوليكية المتعصِّبة، قبلت الزواج بالشاب فرديناند ملك أراغوان الذي كان يصغرُها بسنة، وكان عمرها حين تزوجها تسع عشرة سنة؛ وذلك من أجل اتحاد المملكتين ضد المسلمين وطردهم من الأندلس، وقد اشتهرت في التاريخ بتعاونها مع زوجها فرديناند في القضاء على مملكة غرناطة سنة 897 آخر دولة للمسلمين في الأندلس, حيث تسلَّماها من أبي عبد الله الصغير محمد بن علي آخر حكا"},{"id":3557,"era":"c10","t":"اضطهاد الفرنج للمسلمين في الأندلس ومحاولة تنصيرهم .","s":"لما أُخمدت ثورات المسلمين في الأندلس بالقوة وألغي الإسلام رسميًّا في مملكة غرناطة، تعرض المسلمون لحملة شرسة لتنصيرهم بالقوة, وكان الأندلسيون على صلة وثيقة بإخوانهم في المغرب، الذين كانوا يقفون معهم في محنتهم يحاولون تثبيتهم على دينهم، ومن ذلك فتوى مفتي وهران: أحمد بن بوجمعة المغراوي، وهو أندلسي من بلدة المغرو بمقاطعة قلعة رباح، حيث أرسل لهم فتوى في غرة رجب سنة 910 (18/ 11 / 1504 م) هذا نصها: \" الح"},{"id":3558,"era":"c10","t":"هزيمة محمد البهال صاحب صعدة على يد السلطان عامر .","s":"حدثت وقعةٌ مشهورة بين السلطانِ عامر بن عبد الوهاب والأمير محمد بن الحسين البهَّال صاحب صعدة على باب صنعا، وانهزم فيها البهال وعساكره هزيمةً عظيمة ما سُمِع بمثلها قط، وأُسِرَ فيها إمام الزيدية محمد بن علي الوشلي إمام أهل البدعة ورئيسهم، وقُتل منهم جمعٌ لا يحصى، ونهبهم الناسُ، وكانوا يأتون بهم وبخيلِهم واحدًا واثنين وأخذ السلطان عامر مدينة صنعا."},{"id":3559,"era":"c10","t":"وفاة السلطان محمد الشيخ الوطاسي .","s":"هو السلطان أبو عبد الله محمد الشيخ بن أبي زكريا يحيى بن زيان الوطاسي، المعروف بمحمد الشيخ الوطاسي سلطان المغرب, وبنو وطاس فرقة من بني مرين غير أنهم ليسوا من بني عبد الحق، وكان بنو الوزير من بني وطاس يتطلَّعون إلى الرياسة ويسعَون في الخروج على بني عبد الحق، وقد تكرر ذلك منهم ثم أذعنوا إلى الطاعة، وراضوا أنفسهم على الخدمة فاستعملهم بنو عبد الحق في وجوه الولايات والأعمال واستظهروا بهم على أمور دولتهم"},{"id":3560,"era":"c10","t":"استيلاء الإسبان على بجاية .","s":"لما ظهر جنس الإصبنيول ملوك الجلالقة في طليلطلة في صدر المائة العاشرة بعد ما تم لهم ملك الأندلس وعظمت شوكتهم، طَمِحوا للتغلُّب على ثغور المغربين الأدنى والأوسط فاستولوا على بجاية."},{"id":3561,"era":"c10","t":"استيلاء البرتغال على ثغر آسفي .","s":"كان البرتغال قد تشوَّفوا للاستيلاء على أَسَفي (بلدة على شاطئ البحر المحيط بأقصى المغرب) وكان أهلها فيهم شجاعة أكثر من غيرهم من أهل الثغور، فزحف إليها البرتغال وجرى بينهم وبين أهلها قتال شديد هلك فيه عدد كبير من البرتغال، وعظُم عليهم أن تمتَنِعَ منهم بلدة صغيرة ليس لها حامية سوى أهلها، ثم طاولوها بالحصار حتى قل القوت عند أهل أسفي وأشرفوا على الهلاك، فحينئذ شارطوا البرتغال وأسلموها إليهم على الأمان "},{"id":3562,"era":"c10","t":"وفاة الإمام جلال الدين السيوطي .","s":"هو الشيخ الإمام الكبير العلَّامة جلال الدين أبو الفضل عبد الرحمن بن أبي بكر بن محمد السيوطي الخضيري القاهري الشافعي، صاحب التصانيف والمؤلفات الحافلة الجامعة التي تزيد على خمسمائة مصنف، وقد تداولها الناس واشتهرت, وعم النفعُ بها، وُلد في مستهل رجب سنة 849 في مصر بأسيوط وإليها نسبته، وأمُّه أَمَةٌ تركية، وكان أبوه قاضي أسيوط، ثم نشأ في القاهرة يتيمًا بعد وفاة والده، فاشتغل بالعلم فحفظ القرآن والعمدة "},{"id":3563,"era":"c10","t":"وفاة الفقيه أبي الحسن علي التجيبي الزقاق .","s":"هو الإمام العلامة الشيخ الفقيه أبو الحسن علي بن قاسم التجيبي المعروف بالزقاق من كبار فقهاء عصره بالمغرب، تتلمذ على يد أشهر علماء المغرب والأندلس، واستقَرَّ به المقام بفاس، فصار فقيه فاس وخطيبها وقاضيها ومدرسها، وصاحب المنظومة اللامية في علم القضاء وغيرها بعنوان المنهج المنتخب إلى قواعد المذهب، وهي من أنفس ما وُضعت نظمًا في قواعد الفقه المالكي, وقد حَظِيت هذه المنظومة باهتمام المالكية؛ حيث تولى عدد"},{"id":3564,"era":"c10","t":"سقوط ساحل عمان ومسقط وصحار في يد البرتغاليين .","s":"بعد أن استطاع البرتغاليون إغلاق البحر الأحمر بوجه التجارة العربية أرادوا السيطرة على الخليج العربي، وكان أول همهم جزيرة هرمز لمركزها الهام، فبدأت الحملة على الخليج العربي فهاجموا السفن العربية، فأحرقوا في رأس الحد قوارب الصيد، ثم توجهوا إلى قلهات، ومنها إلى قريات التي أبدت مقاومة بطولية، لكن البرتغاليون قتلوهم دون رحمة، فلم يتركوا طفلًا ولا امرأة ولا رجلًا إلا قتلوه، ثم هاجموا مسقط، ذات الموقع الم"},{"id":3565,"era":"c10","t":"احتلال البرتغال للمالديف المسلمة .","s":"وصل البرتغاليون إلى جزر المالديف في محاولتهم لتطويق العالم الإسلامي، وكانت أولًا قد وصلها التجار المسلمون منذ سنة 85 وبدأ واضحًا فيها الإسلام سنة 545، وقد تمكنت القوات البرتغالية هذا العام من احتلال جزر المالديف وفرض سيطرتها على السكان، وحاولت التأثير عليهم عقَديًّا بتنصيرهم، لكنها كانت تفشل فشلًا ذريعًا مع ارتكابها لأبشع الجرائم لإرهاب السكان، وبقي البرتغاليون فيها قرابة القرن من الزمن حتى مطلع ا"},{"id":3566,"era":"c10","t":"سقوط جزيرتي هرمز وقشم في يد البرتغاليين .","s":"كانت هرمز قد بسطت سيطرتها وسلطانها السياسي على أجزاء كبيرة من الخليج، وكانت ذات مركز تجاري هام؛ لذا قام البرتغاليون بغزوها، وكان ملك هرمز يومها صبيًّا صغيرًا هو سيف الدين ووصيه الشيخ عطار، فوصل البرتغاليون إلى الساحل هذا العام، وبدؤوا بالهجوم المدفعي، فطلب الملك المفاوضات التي كانت رهيبة إلى درجة أن بوكيرك قائد البرتغاليين طعن الشيخ عطار وقتله أثناء تلك المفاوضات، فأسفرت المفاوضات عن صلح بشروط قاس"},{"id":3567,"era":"c10","t":"إحراق آلاف الكتب والمخطوطات الإسلامية في غرناطة .","s":"صدرت بعض المراسيم الإسبانية النصرانية تقضي بتحويل المساجد إلى كنائس، وبإحراق جميع الكتب الإسلامية بغرناطة، ثم عُمم على بقية المناطق، وبمنع استعمال اللغة العربية، ومصادرة الأسلحة من المسلمين. وكان في سنة 908 (1502م) صدر مرسوم ملكي يقضي بأن يُمنح المسلمون شهرين فقط لا غير لاعتناق النصرانية أو الطرد النهائي، فشهدت ساحات غرناطة في حينها إحراق آلاف الكتب العربية والتنصير الإجباري للمسلمين من نزلاء حي ا"},{"id":3568,"era":"c10","t":"تنازل الخليفة العباسي المستمسك يعقوب عن الخلافة لابنه .","s":"بعد أن شعر الخليفة العباسي المستمسك بالله يعقوب بن المتوكل عبد العزيز بالتعب في هذا العام تنازل بالخلافةِ لابنه محمد الذي أصبح هو الخليفةَ بتنازل أبيه، وتلقب بالمتوكل على الله محمد بن يعقوب، وقد بقيَ والده المستمسك إلى أن دخل العثمانيون مصر فنُقِلَ ابنه الخليفةُ المتوكل إلى القسطنطينية، وأما المستمسك فلم يُنقَل لكبر سنه، وبقي بمصر حتى توفي في سنة 927."},{"id":3569,"era":"c10","t":"محاولة البرتغال الاستيلاء على ثغر آزمور .","s":"بعث طاغية البرتغال إلى ثغر آزمور شكوادره ألفين من العسكر وأربعمائة خيالة، فدافعهم زيار الوطاسي ابن عم السلطان محمد البرتغالي، ونشبت مراكب البرتغال في الساحل وتكسر جلُّها وعاث فيها المسلمون ورجع الباقي مفلولًا."},{"id":3570,"era":"c10","t":"حصار السلطان أبي عبد الله البرتغالي لآصيلا. .","s":"لما أفضى الأمر إلى السلطان محمد بن محمد الشيخ الوطاسي المعروف بالبرتغالي أراد أن يأخذ بثأره من البرتغال الذين أسروه لسبع سنين فزحف إلى آصيلا وحاصرها وطال قتاله عليها ثم اقتحمها المسلمون عليهم اقتحامًا واقتتلوا في وسط الأزقة والأسواق يومين، ثم جاء المدد إلى البرتغال من طنجة وجبل طارق فقَوِيت نفوسهم وخرج المسلمون عنهم، لكن ما خرجوا حتى هدموها وأحرقوها ولم يتركوا لهم بها إلا الخربات، ثم جدَّ البرتغال"},{"id":3571,"era":"c10","t":"إسبانيا تحتل مدينة وهران بالجزائر شمال أفريقيا وتذبح أهلها .","s":"كانت إسبانيا بقيادة الكاردينال شيسيروس بدأت بمحاولة احتلت مدينة وهران المرسى الكبير من سنة 910 (1504م) حيث شنَّت عدة هجمات على المدينة انتهت بسقوطها هذا العام, فأعمل الإسبان السيف في سكان المدينة، كما قاموا بتحويل جوامعها إلى كنائس. كانت مدينة وهران تمثِّل بالنسبة للإسبان نقطة ارتكاز للاستيلاء على باقي البلاد. إلا أن النتائج جاءت مخيِّبة. ولم يأت احتلال المدينة الذي دام طويلًا بأي نتائج للإسبان. ف"},{"id":3572,"era":"c10","t":"إنشاء البرتغال مدينة الجديدة بساحل البريجة .","s":"على الرغم من فشل محاولات البرتغال من بناء مدينة لهم في ثغور المغرب على ساحل البريجة سنة 907 بسبب مقاومة المسلمين لهم, إلا أنهم خططوا للعودة إلى هذا الموضع فانتهوا إليه هذا العام وتحيَّنوا غفلة أهل البلاد وشرعوا في بناء حصن مربع على كل ربعٍ منه برج وثيق، ودأبوا في العمل ليلًا ونهارًا، فلم تمض مدة يسيرة حتى فرغوا منه وامتنعوا على المسلمين به، ثم شرع البرتغال بعد الفراغ من هذا الحصن في إدارة سور المد"},{"id":3573,"era":"c10","t":"محاولة استعادة المسلمين مدينة أسفي من نصارى البرتغال .","s":"بعد أن فشلت محاولة المسلمين منع سقوط أسفي بيد البرتغاليين خرجوا منها سنة 910 بشرط الأمان ثم زحفوا إليها بعد ثلاث سنين من أخذها ووقع بينهم وبين البرتغال حرب شديدة كانت صفوف المسلمين تترادف فيها كأمواج البحر، وقتل قواد عسكر البرتغال وكبارهم ثم قَدِمت عليهم شكوادره من مادرة بالعسكر والزاد، فقويت نفوس البرتغال، وارتحل المسلمون عنها بعد أن أشرفوا على الفتح، وتبعهم البرتغال لينتهزوا فيهم الفرصة، فكرَّ ا"},{"id":3574,"era":"c10","t":"وقعة غوا بين المماليك وبين البرتغاليين .","s":"قام البرتغال بعدة حملات بحرية كان منها التي توجهت إلى جزيرة سقطرى على مدخل البحر الأحمر، وأنشؤوا فيها قلعة وفرضوا الحصار على البحر الأحمر, ومنها السفن الهندية التجارية التي يريدوا أن يصلوا بها إلى عدن ثم جدة ومنها إلى مكة والمدينة؛ بهدف تدميرها واعتراض السفن التجارية العربية، فما كان من الملك عامر الثاني ملك اليمن وكذلك الملك خليل مظفر شاه إلا الاستنجدا بالسلطان المملوكي قانصوه الغوري، وطلبا منه ا"},{"id":3575,"era":"c10","t":"وفاة الونشريسي .","s":"هو أبو العباس أحمد بن يحيى بن محمد الونشريسي، ولد بمدينة ونشريس التي تقع بناحية بجاية بين باجة وقسنطينة وإليها نُسب، ونشأ وتفقه بتلمسان على كبار فقهائها، ثم هرب إلى فاس بعد فتنة جرت له مع أمير تلمسان، برع في الفقه المالكي، وله كتب منها المعيار المعرب والجامع المغرب عن فتاوي علماء أفريقية والأندلس والمغرب، وهو أشهرها، وله المنهج الفائق والمنهل الرائق والمعنى اللائق بآداب الموثق وأحكام الوثائق، وله "},{"id":3576,"era":"c10","t":"جهاد قادة الدولة العثمانية لطرد الإسبان من مدينة ثغر الجزائر  .","s":"استولى الملك الأذفونش ملك الجلالقة بطليطلة على وهران، وفعل بأهلها الأفاعيل، ثم سما لتملُّك الجزائر وشَرِه لالتهامها وضايَقَ المسلمين في ثغورهم، وضعف بنو زيان عن مقاومته, فما كان من الشيخ الفقيه الصالح أبي العباس أحمد ابن القاضي الزواوي ممن له الشهرة والوجاهة الكبيرة في بسائط المغرب الأوسط وجباله إلا السعي للاستنجاد بالدولة العثمانية التي قد زخر عبابُهم وملكت أكثَرَ المسكونة خلال هذه الفترة، وظهر م"},{"id":3577,"era":"c10","t":"صراع العثمانيين مع الصفويين وسقوط بغداد بأيدي الصفويين  .","s":"بقيت العلاقة بين الدولتين العثمانية والصفوية متوترةً وغير صافية، بل بقيت بينهم الحروب والمناوشات والتحرُّشات، وكلٌّ يريد بسط سيطرته على ما يستطيعُ من المناطق وخاصةً أن الصفويين يريدون بسط النفوذ الشيعي على العراق وآسيا الصغرى، وهذا لم يرُقْ للدولة العثمانية التي كانت تمثِّلُ الدولة الحامية للسنة، ثم لَمَّا تمكن الشاه إسماعيل الصفوي من توحيد بلاد إيران قام بمهاجمة العراق, بدعوى أنَّ مقابر أئمة الشي"},{"id":3578,"era":"c10","t":"ظهور الدولة السعدية .","s":"كان سبب ظهور الدولة السعدية أن السلطان محمد البرتغالي بن محمد الشيخ الوطاسي قد انشغل بجهاد النصارى المعتدين وترديد الغزوِ إليهم والإجلاب عليهم، حتى شُغِل بذلك عن البلاد المراكشية وسواحلها؛ مما أدى إلى ظهور دولة السعديين عندما قام أبو عبد الله محمد الشيخ السعدي المعروف بالمهدي ببلاد السوس؛ حيث أقبل عليه الخلط وأظهروا الخدمة والنصيحة، وغلب محمد الشيخ المهدي هذا على فاس، وأخرج أبا حسون الوطاسي آخر حك"},{"id":3579,"era":"c10","t":"موقعة ديو البحرية بين المماليك والبرتغاليين .","s":"بعد أن تمكن أسطول المماليك من هزيمة البرتغاليين في وقعة غوا سنة 914 كان الأمير حسين الكردي قائد المماليك قد عاد إلى ديو منتظرًا موسم الأمطار حتى ينتهي ويعود إلى بلاده، ولكن البرتغال في هذه السنة قاموا بقيادة الحاكم البرتغالي لورانزو دالميدا حاكم الهند والذي قتل ابنه في وقعة غوا العام الماضي، فاجأ الأسطول المملوكي الراسي في ديو جنوب بومباي فجرت معركة انهزم فيها الأسطول المملوكي بعد أن تكبد الكثير م"},{"id":3580,"era":"c10","t":"استنجاد المماليك بالعثمانيين ضد البرتغاليين .","s":"لما تمكن البرتغاليون من طرد المماليك من مرفأ ديو الهندي وانسحبوا إلى جُدة، تبعهم البرتغاليون, فقام السلطان المملوكي قانصوه الغوري بالاستنجاد بالعثمانيين ضد البرتغاليين الذين قاموا بمحاصرة الأسطول المملوكي في جُدة، فقام العثمانيون بتزويد المماليك بسفن حربية مزودة بمدافع البارود بقيادة سليمان الريس، واستطاع هذا الأسطول العثماني أن يطرد الأسطول البرتغالي المحاصر للأسطول المملوكي بجدة، واستولى على بعض"},{"id":3581,"era":"c10","t":"البرتغاليون يسيطرون على الخليج العربي .","s":"لما تمكَّن البرتغاليون من إغلاق البحر الأحمر في وجه السفن التجارية العربية زحفوا على الساحل إلى الخليج العربي ودمَّروا مسقط وغيرها من الموانئ الهامة، حتى وصلوا إلى هرمز وبسطوا سيطرتهم عليها، وأقاموا الثكنات العسكرية، وفرضوا سيادتهم على الخليج العربي كاملًا حتى إن أي سفينة لا تستطيع الإبحار إلا بتصريح منهم، وبذلك استطاعوا حصر النشاط التجاري في الخليج العربي وقَبْلَه في الساحل الهندي، فأصبحت تجارة ا"},{"id":3582,"era":"c10","t":"غارة فرسان جزيرة رودوس البرتغاليين على السفن المملوكية .","s":"قام فرسان جزيرة رودوس بقيادة أمير البحر البرتغالي بالاستيلاء على ثماني عشرة سفينة من سفن المماليك، كانت تحمِلُ الأخشاب التي تنقلُها لبناء أسطول ثان كان يعتزم السلطان الغوري بناءه بعد أن فقد الأسطول الأول في معركة ديو، وقد سحبت إلى جزيرة رودوس بعد إحراق بعضها."},{"id":3583,"era":"c10","t":"بدء هجمات البرتغال على موزمبيق والصومال ومدغشقر .","s":"في نهاية القرن التاسع الهجري اكتُشف طريق رأس الرجاء الصالح، وتابع البحَّار فاسكو دي جاما الرحلات البرتغالية عبر المحيط الهندي، وشهد شرقي أفريقيا صراعًا دمويًّا شنَّه البرتغاليون ضِدَّ الإمارات والمدن الإسلامية على طول سواحل شرقي أفريقيا، ودمَّروا مدينة كلوة ومساجدها الثلاثمائة، ودمَّروا مدن لامو وباتي. واستمَرَّ الصراع بين المسلمين والبرتغاليين قرابة قرنين تدور رحاه في سواحل شرقي أفريقيا, واستطاع "},{"id":3584,"era":"c10","t":"احتلال الإسبان طرابلس الغرب وحكم فرسان القديس يوحنا .","s":"من أقوى الأسباب التي هيأت للإسبان احتلال طرابلس الغرب ضعفُ الحامية فيها، وانصراف الناس إلى تنمية المال، وإلى مُتَع الحياة عن الاهتمام بتقوية الجيش وتحصين القلاع، ومن المناسبات التي انتهزها الإسبان للتعجيل باحتلال طرابلس، أنه في هذه سنة وقع خلاف بين أحمد الحفصي وبين والده الناصر، فذهب إلى الإسبان يستنجد بهم على أبيه، فاستعد الإسبان لغزو طرابلس، فجهزوا 120 قطعة بحرية، وانضم إليها سفن أخرى من مالطة، "},{"id":3585,"era":"c10","t":"مقتل السلطان محمود شاه الأبادي صاحب كجرات .","s":"هو السلطان العادل المجاهد أبو الفتح محمود شاه بن محمد أحمد بن محمد بن مظفر ناصر الدين أبو الفتح بن غياث الدين الدلي الأصل، الأحمد أبادي. كان مولده سنة 848 بآباد. أسلم جَدُّ جَدِّه مظفر على يد محمد شاه صاحب دلي، وكان عاملًا له على فتن من كجرات- وفتن: بلدة من بلاد كجرات- من بلاد الهند، فلما وقعت الفتن في مملكة دلي وتقسمت البلاد، فكان الذي خصَّ مظفر حكمه كجرات، ثم وثب عليه ابنه محمد، ولكن لم يلبث أن "},{"id":3586,"era":"c10","t":"وقعة غوا الثانية بين المماليك والبرتغاليين .","s":"استنجد سلطان كجرات بالسلطان المملوكي قانصوه الغوري لطرد البرتغاليين الذين كثروا في بحر الهند، وأخذوا يصطادون السفن ويعتدون على المسافرين، ويقطعون الطريق عليهم وينهبون ويقتلون، فجهَّز السلطان الغوري أسطولًا وولى عليه الأمير حسين الكردي ومعه الأمير سليمان الريس العثماني، ثم التقى الأسطولان العثماني والمصري مع الأسطول البرتغالي بقيادة البوكيرك في معركة بحرية جرت أمام غوا على ساحل الملبار، ولم يحقق ال"},{"id":3587,"era":"c10","t":"وفاة الأمير أبي الحسن بن راشد .","s":"هو الأمير أبو الحسن علي بن موسى بن راشد بن علي بن سعيد بن عبد الوهاب مختطُّ مدينة شفشاون في العدوة الأخرى؛ حيث بنى قصبتها وشيَّدها وأوطنها بأهله وعشيرته، ونزل الناس بها فبَنَوا وصارت في عداد المدن، وكان من أهل الجهاد والمرابَطة خاصة على العدو ببلاد غمارة والهبط."},{"id":3588,"era":"c10","t":"الاستعمار البرتغالي للملايو .","s":"انطلق المستعمِرون الصليبيون البرتغاليون من قاعدتهم غوا على سواحل الهند الغربية، ووصلوا مالاقا في الملايو سنة 915 فقاموا بهجوم عليها، ولكنهم فشلوا ثم بعد عامين أعادوا الكَرَّة فسقطت ملاقا- الميناء التجاري الهام للمسلمين- بيد الاستعمار البرتغالي، وكان فرحًا كبيرًا للنصارى حتى أقاموا في روما قُدَّاس شكر حتى عدُّوا هذا النصر طريقًا لاحتلال القدس، وكان أول ما قاموا به بعد أن سقطت ملاقا بيدهم أن بنَوا ح"},{"id":3589,"era":"c10","t":"نزاع أبناء السلطان العثماني بايزيد الثاني مع أبيهم .","s":"كان السلطان بايزيد الثاني قد عين أولاده الثلاثة الذين بقُوا على قيد الحياة على الولايات، فكان كركود واليًا على شرقي الأناضول، وأحمد على أماسيا، وسليم على طرابزون، كما عيَّن حفيده سليمان بن سليم على مدينة كافا في شبه جزيرة القرم، وكان سليم محاربًا طموحًا فاراد أن يكون واليًا على بعض المقاطعات في أوربا ليمارس الجهادَ، ويؤيِّدُه في ذلك الانكشارية والعسكريون عامة، ولكن السلطان رفض من ابنه ذلك، كما رفض"},{"id":3590,"era":"c10","t":"دخول الإفرنج عدن .","s":"دخل الإفرنج عدن وقُتِلَ كبيرهم المسمى عين البقر على يد الأمير مرجان بن عبد الله الظَّافري, ومرجان هذا هو الذي عمر قبة العيدروس بعدن ودفن معه فيها."},{"id":3591,"era":"c10","t":"تحرير مدينة بجاية من يد الإسبان .","s":"اهتمت الدولة العثمانية بشمال أفريقيا خاصة بعد دخول الجزائر تحت نفوذها في عهد السلطان سليم الأول، وظهر في ساحة الجهاد في شمال أفريقيا قائدان تركيان عظيمان هما الأخوان عروج باشا، وخير الدين بربروسا باشا, ويظهر دور الأخوين المجاهدين بمحاولة تحرير بجاية من الحكم الإسباني سنة 918 (1512م)، وقد نَقلا لهذا الغرض قاعدة عملياتها ضد القوات الإسبانية في ميناء جيجل شرقي الجزائر بعد أن تمكَّنا من دخولها وقتل حم"},{"id":3592,"era":"c10","t":"وفاة السّلطان بايزيد الثاني  .","s":"هو السلطان بايزيد الثاني بن محمد الفاتح بن مراد الثاني, وهو ثامن سلاطين بني عثمان، ولد سنة 856 وهو أكبر أولاد أبيه، تولى السلطنة بعد أبيه محمد الفاتح في الثامن عشر ربيع الأول سنة 886 وعمره إذ ذاك ثلاثون سنة، بعد أن نازعه أخوه جم على السلطنة فانتصر عليه, ويعتبر بايزيد الثاني من عظماء السَّلاطين، افتتح الفتوحات، كقلعة ملوان، وقلعة كوكلك، وقلعة آق كرمان سنة 888 وقلعة متون، وغير ذلك من القلاع والحصون,"},{"id":3593,"era":"c10","t":"استيلاء إسماعيل شاه الصفوي على بلاد العجم والعراق .","s":"تزايد ظهورُ شأن إسماعيل شاه بن حيدر الصفوي، فاستولى على سائر ملوك العجم، وملك خراسان، وأذربيجان، وتبريز، وبغداد، وعراق العجم، وقهر ملوكَهم، وقتل عساكِرَهم، بحيث قتل مئاتِ الألوف، وأظهر مذهبَ الإلحاد والرَّفض، وغيَّر اعتقاد أهل العجم, وكان عسكرُه يسجدون له ويأتمرون بأمرِه، وكاد يدَّعي الرُّبوبية! وقتَل العلماء، وأحرق كتُبَهم ومصاحِفَهم، ونبش قبور المشايخ من أهل السُّنَّة وأخرج عظامَهم وأحرقَها، وكا"},{"id":3594,"era":"c10","t":"استيلاء البرتغال على ثغر آزمور .","s":"بعد فشل محاولة البرتغال احتلال ثغر آزمور سنة 914 بعث في هذا العام الطاغية منويل شكوادره فيها عشرين ألفًا من العسكر وألفين وسبعمائة خيالة، فانتهوا إلى آزمور وحاصروها بحرًا وزحفوا إليها من مدينة الجديدة برًّا، ووقعت حرب شديدة بينهم وبين أهل آزمور وأهل البادية، ثم انهزم المسلمون وخرجوا من باب تركه لهم البرتغال قصدًا ليفروا منها."},{"id":3595,"era":"c10","t":"خلع السلطان العثماني بايزيد الثاني نفسه وتولية ابنه سليم الأول .","s":"بعد أن وزَّعَ السلطان بايزيد الثاني الولايات على أولاده حاول سليم أن يعلِنَ نفسه سلطانًا فحاربه أبوه، ثم عفا عنه، ثم في 18 صفر من هذه السنة ترك السلطان بايزيد حكمَ الدولة لابنه سليم الأول، وذلك بدعم من الجيش الانكشاري الذي سار به إلى استانبول، وكان الانكشارية ينظرون إليه على أنه الأمل المرتجى في بعثِ النشاطِ الحربيِّ للدولة العثمانية بصورة أوسع، ودفْع حركة الفتوحات إلى الأمام؛ ولذلك بادر الجيش إلى"},{"id":3596,"era":"c10","t":"انتشار الوباء وكثرة الموتى بمدينة زبيد .","s":"كثر الموت بمدينة زَبيد وعمَّ الوباء وبلغ الموتى فيها كلَّ يوم إلى قريب من مائة نفس، ومات بسببه من الأعيان وغيرهم خلائق لا يحصَون."},{"id":3597,"era":"c10","t":"السلطان العثماني سليم الأول يتتبع إخوته ويقتلهم .","s":"بعد أن تسلطن سليم الأول وعلا عرشَ الدولة العثمانية توجَّه للتخلص من إخوته الذين ينازعونَه السلطة أو لا يرضونَ به سلطانًا؛ الأمير \"كوركود\"، و الأمير \"أحمد\"، فالأول قام بتجميع جيش وأعلن العصيان ضد الدولة، أما الثاني فلم يكتفِ بإعلان العصيان بل اتَّفق مع أعدى أعداء الدولة العثمانية، وهي الدولة الصَّفوية ضد أخيه, فتعقَّب أخاه أحمد إلى أنقرة وقبض عليه بعد جَهدٍ وقتَلَه، ثم سار إلى ولاية صاروخان وتتَبَّ"},{"id":3598,"era":"c10","t":"تعيين سليمان بن سليم حاكم لاستانبول .","s":"عيَّن السلطان سليم الأول ابنَه سليمان حاكمًا على إستانبول؛ ليتفرغ لأموره، فانتقل إلى أدرنة، فعقد معاهدات مع البندقية والمجر وموسكو ومماليك مصر."},{"id":3599,"era":"c10","t":"وفاة الشيخ أبي عبد الله محمد بن غازي المكناسي .","s":"هو الشيخ المحدث المقرئ الفقيه أبو عبد الله محمد بن محمد بن علي بن غازي، العثماني المكناسي ثم الفاسي المالكي، عالم المغرب وراويته الحيسوبي الفَرَضي صاحب الحواشي على الصحيح, والمعروف بابن غازي المكناسي. ولد سنة 841 بمكناس. برع في عدة فنون، لكنه اشتهر بالفقه، وكان بديع الخط متقِن الضبط. لم يكتفِ بالتعليم والتأليف، بل شارك في جهاد الإفرنج لحماية ثغور المغرب، حتى إنه توفي وهو في غزوة ضد النصارى بآصيلا؛"},{"id":3600,"era":"c10","t":"هزيمة الدولة الصفوية في معركة (جالديران) على يد العثمانيين .","s":"بعد أن نشأت الدولة الصفوية لم تكتفِ بفرض مذهبِها الشيعي على الناس بالقوةِ والقهر، بل بدأت تتحرَّش بالدولة العثمانية عن طريق إثارة الموالين لها من أصحابِ العمائم الحمر المعروفين بـ (قزلباش) ذوي التدين الشيعي، وأيضًا إثارتهم البرتغاليين وإرسال الرسائل لهم وحثهم على حرب العثمانيين، كما أنَّ احتضان الدولة لمراد بن أحمد الهارب من عمه السلطان سليم، كلُّ هذه الأمور اجتمعت لإثارة الحرب بين الدولتين العثما"},{"id":3601,"era":"c10","t":"انضمام الإمارة السلجوقية إلى الدولة العثمانية .","s":"بعد أن استطاع السلطان العثماني سليم الأول أن ينتصرَ على الصفويين في معركة جالديران، ترك جيشًا كان مهمتُه الاستيلاء على الرقَّة وأورفة وماردين والموصل، وقبل هذا قام السلطان بعد أن انتهى من استراحته حتى انتهى الشتاء بالرجوع إلى أذربيجان ففتح فيها بعض القلاع ودخل إمارة ذي القدر السلجوقية، وأميرُها علاء الدولة، التي كانت تعتبر تحت سيطرة المماليك، وهذه الإمارة تضم مدن أبلستين ومرعش وعينتاب، فأصبحت ضمن "},{"id":3602,"era":"c10","t":"التحالف بين الدولة الصفوية والبرتغاليين .","s":"ما إن هُزمَ إسماعيل شاه الصفوي في موقعة جالديران العام الماضي أمام السلطان العثماني سليم الأول حتى كان أكثرَ استعدادًا وتقبلًا من قبلُ للتحالف مع البرتغاليين، وبدأ في الاستعداد للارتباط بالبرتغال عقِبَ استيلاء البوكرك على هرمز، عندها وصل سفيرٌ من لدى إسماعيل شاه وتمَّ الدخول في اتفاقية محدودة بين البرتغاليين والصفويين نصَّت على ما يلي: أن يقدِّم البرتغال أسطولَه ليساعدَ الفُرسَ في غزو البحرين والق"},{"id":3603,"era":"c10","t":"استيلاء البرتغال على ثغر المعمورة بالمغرب .","s":"بلغ منويل البرتغالي أنَّ مينا المعمورة جيِّدة وبلادها نفاعة، فبعث إليها طائفةً من جنده فوصلوا إلى ساحلِها ونزلوا في البرِّ المقابل لها، وبنَوا هنالك برجًا لحصارها، ثم أردفهم مَلِكُهم منويل بعمارة تشتملُ على مائتي مركبٍ مشحونة بثمانية آلاف من المقاتلة، وكان خروج هذه العمارة من مدينة أشبونة، فوافت مينا المعمورة في الثالث والعشرين من يونيه من هذه السنة، وحاصروها وألحُّوا عليها بالقتال أيامًا، وبلغ ال"},{"id":3604,"era":"c10","t":"وفاة القائد البحري فاسكو دي جاما البرتغالي .","s":"هو القائد البحري فاسكو دي جاما البرتغالي، ولد سنة 1460م في عائلة نبيلة، ودرس الملاحة البحرية، أوكل إليه ملك البرتغال مانويل الأول حملةً بحرية يصل فيها لبلاد الشرق دون المرور ببلاد المسلمين, فانطلق برحلته سنة 1497م من لشبونة ووصل بلاد الهند عبر طريق رأس الرجاء الصالح، وذلك بعد اعتماده على معلومات وخبرات البحَّار المسلم أحمد بن ماجد النجدي العماني، وكان من أثر هذه الرحلة زيادةُ أطماع البرتغال الاستع"},{"id":3605,"era":"c10","t":"هزيمة السلطان المملوكي على السلطان العثماني سليم الأول .","s":"عندما استولى السلطان سليم الأول العثماني على إمارة ذي القادر التي كانت تابعة للدولة المملوكية وتوجَّه إلى الشام، أثار مخاوف السلطان المملوكي قانصوه الغوري الذي جهز جيشًا وتوجه به إلى الشام، وزاد هذا الأمر أنَّ المماليك وقفوا مع الصفويين ضد العثمانيين في ذي القادر ومرعش، بينما أمراء الشام شجَّعوا العثمانيين على القدوم إلى الشام؛ لخوفهم من الزحف البرتغالي، وربما أيضا زاد هذا أن علاء الدين الهارب من "},{"id":3606,"era":"c10","t":"وفاة السلطان المملوكي الأشرف الغوري وتسلطن طومان باي .","s":"هو السلطان الأشرف أبو النصر قانصوه بن بيبردى الغوري الجركسي الجنس, وهو من سلاطين المماليك البرجية. ولِدَ سنة 850 امتلكه الأشرف قايتباي وأعتقه وعيَّنه في عدة وظائف في خدمته. كان في أوائل الأمر أميًّا لا يعرف شيئًا؛ لأنه جُلب من بلاده وهو كبير قد شَرَع فيه الشيب، وصار السلطان قايتباي يرقِّيه لكونه أخًا لزوجته، وهي التي بذلت الأموال للجند ومكَّنَته من الخزائن حتى ملَّكوه بعد السلطان قايتباي، فاستمر س"},{"id":3607,"era":"c10","t":"استيلاء القائد عروج باشا على تلمسان والتغلب على أمر بني زيان .","s":"استولى القائد عروج باشا، وهو من قواد البحرية الترك، على تلمسان من أيدي بني زيان، إلَّا أن أهل تلمسان أنكروا سيرةَ الترك وسئِموا ملكَهم, ويقال: إن التركَ عسفوهم وصادروا أموالهم، فدارت الكَرَّة على عروج سنة 924 فقُتِل هنالك مع جماعة من وجوه عسكره، وتفرَّقت جموعه وعادت تلمسان مرةً أخرى لبني زيان."},{"id":3608,"era":"c10","t":"البابا ليو العاشر يستعد لحرب صليبية لمواجهة سليم الأول العثماني .","s":"لم يلبث السلطانُ سليم الأول أن يفرغَ من انتصاراته في بلاد العربِ والعجمِ حتى دبَّ الرعبُ والفزع في قلوب الصليبيين، وما استطاعت الدولة العثمانية أن تحرِزَه من ضَمٍّ للبلدان الأوربية إليها حتى تصبِحَ تحت سيطرتِها، فحدا هذا بالبابا ليو العاشر الذي كانت أيضًا بينه وبين غيره من النصارى منافسات، فقام في هذه السنة بالنداء لحرب صليبية ضد الدولة العثمانية مانحًا صكوك الغفران كالعادة لمن يستجيب, ومثيرًا في "},{"id":3609,"era":"c10","t":"وفاة السلطان القائم بأمر الله أبو عبد الله محمد السعدي .","s":"هو السلطانُ أبو عبد الله محمد بن محمد بن علي بن مخلوف بن زيدان، الملقَّب بالقائم بأمر الله، عميد الأسرة السعدية وسلطان المغرب. كان قد نشأ على عفافٍ وصلاحٍ وحجٍّ للبيت الحرام، وقيل: كان مجابَ الدعوةِ، من قرَّاءِ القرآن، ومن أهلِ العلمِ والدين، ولم يكن من بيت الرياسةِ، وكان له اطِّلاعٌ على تواريخ قُطره وعوائدِ جيله وأخلاقهم وطبائعهم، ورأى ما وصل إليه مُلكُ بني وطاس بالمغرب من الانحطاط والضعف، وتيقَّ"},{"id":3610,"era":"c10","t":"عودة فتنة الشيعة القزلباش في شرقي الأناضول .","s":"عاد جماعة من القزلباش- أي أصحاب العمائم الحمراء- إلى الانقضاض على الدولة العثمانية في منطقة ما بين النهرين بشرق الأناضول، وقد أمدتهم الدولة الصفوية الشيعية بقوة عسكرية، فأخذوا يُغيرون على الجماعات الآشورية والجماعات الكردية السُّنَّة، واستولوا على حاضرتهم آمد التي عرِفَت فيما بعد بديار بكر، وجرت بين الفريقين وقائع كانت الغلبة فيها لجماعات القزلباش، فاستنجد الأكرادُ بالسلطان سليم الأول فأمَدَّهم بق"},{"id":3611,"era":"c10","t":"قضاء المماليك على الطاهريين في اليمن في معركة الصافية .","s":"كان الخطر البرتغالي يهدد التجارة في البحر الأحمر والخليج العربي، وبالتالي يهدِّد التجارة المصرية التي يتولاها المماليك، ولما كان البرتغاليون وصلوا إلى مرحلة هددوا فيها كل شيء للعرب أو المسلمين في البحر، وليس فقط التجارة، فأرسل المماليك قوة إلى اليمن لتواجه القوة البرتغالية؛ فقد أرسل السلطان قانصوه الغوري أسطولًا بحريًّا بقيادة حسين الكردي سنة 922 إلى اليمن؛ حيث طلب حسين من الملك عامر الثاني الطاهر"},{"id":3612,"era":"c10","t":"وفاة ابن ماجد أحد كبار الملاحين العرب .","s":"هو البحار المشهور شهاب الدين أحمد بن ماجد بن عمر بن فضل بن دويك بن يوسف بن حسن بن حسين بن أبي معلق السعدي ابن أبي الركائب النجدي العماني، عُرِفَ بأسد البحر أحد كبار الملاحين العرب، ولد سنة 838 في مدينة جلفار- تقع في رأس الخيمة اليوم- ونشأ بها. ينحدر ابن ماجد من أسرة اشتهرت بالملاحة وارتياد البحار, اشتهر ابن ماجد بعلمه في شؤون البحار وما يتصلُ بذلك من علوم الملاحة والفلك والرياضيات والجغرافيا. رحل "},{"id":3613,"era":"c10","t":"وفاة الإمام العلامة شهاب الدين القسطلاني .","s":"هو الشيخُ الإمام العلامة الحافظُ الحجَّة الرُّحَلة الفقيه المقرئ المسنِد المؤرخ الخطيبُ: شهاب الدين أبو العباس أحمد بن محمد بن أبي بكر بن عبد الملك بن الزين أحمد بن الجمال محمد بن الصفي محمد بن المجد حسين بن التاج علي القسطلاني الأصل، القتيبي المصري الشافعي، ويعرف بالقسطلاني علَّامة الحديث, وأمُّه حليمة ابنة الشيخ أبي بكر بن أحمد بن حميدة النحاس. ولِدَ في الثاني والعشري ذي القعدة سنة 851 بمصر ونشأ"},{"id":3614,"era":"c10","t":"انتصار العثمانيين ونهاية دولة المماليك والخلافة العباسية .","s":"بعد أن انتصر السلطانُ العثماني سليم الأول على السلطان المملوكي قانصوه الغوري وقتَلَه في معركة مرج دابق سنة 922، سار إلى مصر، وأرسل السلطان سليم إلى السلطان الجديد طومان باي يعرِضُ عليه الصلح مقابِلَ الاعتراف بسيادة العثمانيين على مصر، غيرَ أن طومان باي رفض ذلك واستعدَّ للقتال، والتقى الطرفان أولًا على حدود بلاد الشام في معركة أولى انهزم فيها المماليك، ثم دخل العثمانيون غزةَ ثم أكملوا مسيرَهم إلى م"},{"id":3615,"era":"c10","t":"وفاة السلطان طومان باي آخر سلاطين الدولة المملوكية .","s":"هو السلطان الأشرف طومان باي آخر سلاطين الدولة المملوكية بمصر، ويُذكَر أن أصله من بلاد الغور، اشتراه قانصوه الغوري وقَدَّمه للملك الأشرف قايتباي، ثم وَرِثَه ابنُه الناصر محمد الذي أعتقه. تولى نيابة السلطنة المملوكية في عهد السلطان المملوكي الأشرف قونصوه الغوري، ثم بويع طومان باي بالسلطنة بعد معركة مرج دابق, لكِنَّ أيامه لم تطُلْ؛ فقد هُزم أمام العثمانيين في معركة الريدانية وسقط أسيرًا بأيديهم؛ حيث "},{"id":3616,"era":"c10","t":"السلطان العثماني سليم الأول يعلن الخلافة ويستلم مفاتيح الكعبة .","s":"لَمَّا دخل السلطانُ سليم الأول القاهرةَ وقتَلَ السلطان المملوكيَّ طومان باي آخِرَ سلاطين دولة المماليك وتنازلَ الخليفة العباسي له بالخلافةِ كُرهًا- على ما قيل- وجاءه أيضًا أشراف الحجاز مع أمير مكة الشريف محمد أبا نمي بن بركات ليَدينوا له بالطاعة وسَلَّموا له مفاتيح الكعبة، فولى السلطان الشريف محمد أبا نمي ولاية الحجاز، ثمَّ بعد أن أقام شهرًا في مصر بعد أن وطَّد فيها دعائم الحُكم ملحِقًا حكم مصر با"},{"id":3617,"era":"c10","t":"إعلان العثمانيين قيام الخلافة الإسلامية في دولتهم .","s":"بعد أن استطاع العثمانيون القضاء على الدولة المملوكية بمصر وسقوطها، وكانوا قبل ذلك قد استطاعوا أن يسيطروا على الشامِ، ثم بعد مصر على الحجاز، فأضحت الإماراتُ التي كانت تابعةً للماليك تابعةً لهم هم، وكانوا قد توسَّعوا في أوروبا أيضًا، فكان هذا التوسعُ في الشرق والغرب والشمال والجنوب- نصرًا لهم، وانتقلت الخلافة إليهم بعد أن كانت في العباسيين، فكان هذا إعلانًا لقيام الخلافة الإسلاميَّة في الدولةِ العُث"},{"id":3618,"era":"c10","t":"ترتيب السلطان سليم الأول أوضاع مصر  .","s":"لما أخذ السلطان سليم الأول مصر ورأى غالبَ حكامِها من المماليك الذين وَرِثوها عن ساداتهم؛ رأى أنَّ بُعدَ الولايةِ عن مركز الدولة ربما أوجب خروجَ حاكِمِها عن الطاعة وتطَلُّبَه الاستقلال، فجعل حكومة مصر منقسمةً إلى ثلاثة أقسام، وجعل في كل قسم رئيسًا، وجعلهم جميعًا منقادين لكلمة واحدة هي كلمة وزير الديوان الكبير، وجعله مركَّبًا من الباشا الوالي من قِبَله، ومن بيكوات السبع وجاقات، وجعل للباشا مزيةَ توص"},{"id":3619,"era":"c10","t":"تعيين أول وال عثماني على مصر. .","s":"عُيِّن الوزيرُ الأعظم رئيسُ الوزراء العثماني يونس باشا كأوَّل والٍ عثمانيٍّ على مصر."},{"id":3620,"era":"c10","t":"وفاة الملك الظافر عامر بن عبدالوهاب سلطان اليمن .","s":"هو الملك الظافر عامر بن عبد الوهاب بن داود بن طاهر: سلطان اليمن. ولِدَ سنة 866 بالمقرانة محل سلفه، ونشأ في كفالة أبيه فحفظ القرآن واشتغل قليلًا، ثم ملك اليمن بعد أبيه ولقِّب بالملك الظافر، فاختلف عليه بنو عامر فقهرهم وأذعنوا له، وملك اليمن الأسفل وتهامة ثم صنعاء وصعدة وغالبَ ما بينهما من الحصون. كان يحبُّ العلماء ويكرمُهم ويجمع الكتبَ, وكان على جانبٍ عظيم من الدين والتقوى والمشي في طاعة الله تعالى"},{"id":3621,"era":"c10","t":"بداية الامتيازات الأجنبية في البلاد الإسلامية  .","s":"قامت الدولة العثمانية في تاريخ العشرين من شهر شعبان من هذا العام بإبرام معاهدة تجارية مع البندقية مُنِح بموجبها قنصل البندقية في القسطنطينية الحقَّ في الفصل بأمور تركات رعيته وإرسال ترجمان لحضور المرافعات في القضايا التي يكون أفراد رعيته طرفًا فيها أمام القضاء العثماني، وامتدت هذه المعاهدة إلى مصر والشام بعد استيلاء العثمانيين عليهما، فكانت هذه المعاهدة أساس الامتيازات الأجنبية في البلاد الإسلامية"},{"id":3622,"era":"c10","t":"انتشار النفوذ العثماني في الجزائر .","s":"كانت الجزائر قد تعرَّضت لهجمات الإسبان الذين استطاعوا توطيد قدَمِهم في الجزائر، وبرز في تلك الفترة الأخوان عروج باشا وخير الدين بربروسا اللذين استطاعا أن يوقِفا المد الإسباني في البحر؛ حيث كانا بحَّارَين قويين، وكان السلطان العثماني قد منح عروج لقب أمير البحر العثماني، فأصبحت إنجازاته في ميزان الدولة العثمانية، واستطاع عروج أن يستعيد عدَّة مدن جزائرية، فدخلت بذلك الجزائر- أو بدأت تدخل- تحت النفوذِ"},{"id":3623,"era":"c10","t":"الغزو الإسباني للجزائر .","s":"كان الإسبان قد استولوا على تلمسان عام 915 فقام أمير البحر عروج بن يعقوب بمهاجمة تلمسان بقواته من البر والبحر، بمساعدة حاكمِها أبي حمو موسى الزياني الذي كان يتعاون مع الإسبان، فاستطاع الأمير عروج أن يستوليَ على تلمسان ويستخلصَها من أميرها المتعاوِن، وولى عليها أبو زيان أحمدَ الثاني، فاستنجد أبو حمو بالإسبان الذين كانوا يحتلون وهران، فقدموا بسرعة بقوة كبيرة توغَّلت داخل البلاد وشدَّدت الحصار على عرو"},{"id":3624,"era":"c10","t":"عودة السلطان العثماني سليم الأول إلى إستانبول .","s":"عاد السلطان العثماني سليم الأول إلى إستانبول بعد حملته العسكرية التي استمرت سنتين وشهرين انتصر فيها على الصفويين ودخل عاصمتهم تبريز, وفتح مصر والشام والحجاز، وتعد هذه الحملة هي أطول حملة في التاريخ العثماني."},{"id":3625,"era":"c10","t":"وفاة القائد التركي عروج باشا .","s":"هو القائد البحار التركي عروج باشا بن يعقوب بن يوسف، وهو أخو خير الدين بربروسا باشا, ويرجع أصلُ الأخوين المجاهدينِ إلى الأتراك المسلمين الذين استقرُّوا في جزيرة مدللي إحدى جزر الأرخبيل, وأمهم سيدة مسلمة أندلسية كان لها الأثر على أولادها في تحويل نشاطهم شطرَ بلاد الأندلس التي كانت تئن في ذلك الوقت من بطش الإسبان والبرتغال, وكان لعروج وخير الدين أخوان مجاهدان أيضًا هما إسحاق ومحمد إلياس. قُتل عروج با"},{"id":3626,"era":"c10","t":"البرتغال يحاصرون جدة .","s":"قام الأسطول البرتغالي بقيادة القائد سواريز بالرسو أمام جدَّة بعد أن اجتاز البحرَ الأحمر، وهذه محاولة منهم للوصولِ إلى مكة، وهم يريدون أن يهدِموا الكعبة ومِن ثمَّ يصِلون إلى المدينة، ويريدون أن ينبشوا القبر النبوي الشريف ليُساوموا به على القُدس، وهذا الأمر ليس بأوَّل مرة؛ فقد حاولوا قبل ذلك لكنَّهم فشلوا، وفي هذه الحملة تعرَّض الأسطول البرتغالي إلى عواصِفَ شديدة شتَّتت سفنه, ولما علم بهذا الحصار ال"},{"id":3627,"era":"c10","t":"إلحاق الجزائر بالدولة العثمانية .","s":"بعد أن ترأَّس خير الدين بربروسا الذي خلف أخاه عروج بن يعقوب في حكم الجزائر، دعا رجال الدين والأعيان واقترح عليهم الالتحاقَ بالدولة العثمانية، فوافق الجميعُ على هذه الفكرة وصادقوا على كتاب تقرَّرَ إرساله إلى السلطانِ سليم الأول العثماني؛ لبسط حمايته على الجزائر، فتلقى السلطان العثماني الكتابَ، وولى خير الدين النيابةَ على الجزائر، وأرسل فرمانًا يقضي بذلك وأن الجزائر تحوَّلت إلى ولاية عثمانية."},{"id":3628,"era":"c10","t":"طرد الوجود الإسباني من الجزائر .","s":"بعد أن دخلت الجزائر في النفوذ العثماني بجهاد البحَّارينِ عروج وأخيه خير الدين بربروسا، فقد استطاعا أن يوقِفا المدَّ الإسباني على المغرب، كما استطاعا أن يُلحِقا القسم الأكبر منه بالدولة العثمانية التي كانت بدورها تُعِين عروج بالسلاحِ والرجال, فاستطاع أن يستعيدَ جزيرة جربة سنة 916 وشرشل سنة 920 ومدينة الجزائر سنة 922, وإن احتفظ الإسبان بقلعة الجزائر، واستعاد كذلك تنسي وتلمسان، واستشهد عروج أثناء جها"},{"id":3629,"era":"c10","t":"انتصار العثمانيين على البرتغاليين وطردهم من اليمن .","s":"بعد قيام العثمانيين بالقضاء على الدولة المملوكية في مصر بدؤوا بالاستعداد لمنازلة البرتغاليين في البحار الشرقية بوجه عام، والبحر الأحمر بوجه خاص؛ ليتصدوا بذلك للمشاكل الاقتصادية والسياسية التي واجهوها بعد قيام البرتغاليين بتحويل طريقِ التجارة البحرية عبر البحرِ الأحمر والخليج العربي إلى رأس الرجاء الصالح من ناحية، ولمواجهة تحالف البرتغاليين مع الدولة الصفوية في إيران- التي كانت علاقتها عدائيَّة بال"},{"id":3630,"era":"c10","t":"وفاة السلطان العثماني سليم الأول ياوز وتولي ابنه سليمان الخلافة .","s":"هو السلطان سليم الأول بن بايزيد الثاني بن محمد الفاتح الغازي الملقب بياوز، أي: القاطع, وهو تاسع سلاطين الدولة العثمانية، وأول من تلقَّب بأمير المؤمنين من سلاطين بني عثمان. تولى سلطنة الدولة العثمانية سنة 918 بعد نزاع مع والده بايزيد، انتهى النزاع بتنازل والده له بالحكم بدعم من الانكشارية, وقد أظهر سليم منذ بداية حكمه ميلًا إلى تصفية خصومه ولو كانوا من إخوته أو أبنائهم, فبعد توليه السلطة عيَّنَ ابن"},{"id":3631,"era":"c10","t":"جان بردي الغزالي والي الشام يعلن تمرده على الدولة العثمانية .","s":"ما إن علم الوالي جان بردي الغزالي والي الشام للعثمانيين بموت الخليفة سليم الأول أعلن عصيانه وتمرده، واتصل بخيري بك والي مصر ليكون نصيره، فراوغه خيري ووعده، وفي الوقت نفسه أطلع الخليفة سليمان القانوني على هذه المراسلات، وأعلن جان بردي نفسه سلطانًا على الشام وأمر بالدعاء له في خطب الجمعة، ونقش اسمه على النقود وتلقب بالملك الأشرف، وقضى على حامية دمشق العثمانية، وطرد العثمانيين من بيروت وطرابلس وحماة "},{"id":3632,"era":"c10","t":"اضطهاد الأسبان للموريسكيين المسلمين وترحيلهم إلى مراكش .","s":"لم تنجح محاكم التفتيش التي أقامها الصليبيون الإسبان ولا الأساليب التي اتبعوها في إجبار المسلمين على ترك دينهم كما تريد الكنيسة التي أدركت مدى عمق الإيمان بالعقيدة الإسلامية في نفوس الموريسكيين، فقررت إخراجهم من إسبانيا، فأصدر مجلس الدولة بالإجماع في (30/1/1608م) قرارًا بطرد جميع الموريسكيين من إسبانيا، ولم يحُلَّ شهر أكتوبر عام (1609م) حتى عمَّت موانئَ المملكة وبلنسية من لقنت جنوبًا إلى بني عروس ش"},{"id":3633,"era":"c10","t":"حدوث غلاء وجوع كبير ببلاد المغرب .","s":"وقع الغلاء والجوع الكبير الذي صار تاريخًا في الناس مدة، وحدث هذا بعد عام من انحباس المطر واضطرار الناس إلى استخراج السواقي من الأودية والأنهار لسقي زرعهم وثمارهم."},{"id":3634,"era":"c10","t":"استيلاء العثمانيين على بلغراد .","s":"بعد أن اعتلى السلطان سليمان القانوني عرش الخلافة العثمانية أرسل رسولا إلى ملك المجر يُعلِمه بأنه أصبح الخليفة ويطالبه بدفع الجزية، فقام ملك المجر بقتل الرسول، فجهَّز سليمان جيشًا وسار على رأسه لقتال المجر، ودخل مدينة بلغراد بعد أن حاصرها قليلًا وغادرها الجنود المجريون، ثم صلى السلطان سليمان الجمعة في أحد كنائسها بعد أن حولها إلى مسجد جامع."},{"id":3635,"era":"c10","t":"انتشار وباء بالمغرب .","s":"انتشار وباء بالمغرب، وكان وقوعه بعد ما حدث من غلاء وجوع في العام الذي قبله."},{"id":3636,"era":"c10","t":"سيطرة البرتغاليين والإسبان على جزر إندونيسيا .","s":"استطاع البرتغاليون احتلال مالاقا سنة 917, واتخذوها قاعدةً لشن حملاتهم على الجزر الإندونيسية، وخاصة جزر الملوك، وهي الجزر التي يعرفونها بجرز التوابل، وتمكنوا من السيطرة على شمالي سومطرة هذه السنة, ووصلوا إلى جزيرة سيلبيس سنة 947، وقد قامت الثورات ضدَّهم لتعصبهم الصليبي الذي كان واضحًا لا خفاء فيه، وقد زادت هذه الحركات بعد أن قُتل غدرًا سلطان جزيرة ترنات ويدعى هارون، أما الإسبان فقد وصلوا إلى جزيرة "},{"id":3637,"era":"c10","t":"استرداد هرمز بعد طرد البرتغاليين منها .","s":"بعد أن توفِّي السفاح البرتغالي بوكيرك شرع سكان الخليج العربي لتحريك ثورة تحت قيادة هرمز على الحكم البرتغالي، بحيث امتدت الثورة إلى جميع القواعد والحصون البرتغالية في منطقة الخليج العربي، فقام في تشرين الثاني من عام 1521م رئيس التجَّار بمهاجمة السفينتين الموجودتين في ميناء هرمز، وأشعل النار فيهما وهاجم السكانَ البرتغاليين وحاصروهم في القلعة، ونجحت الثورة نجاحًا جيدًا، ثم قام البرتغاليون بنقل التعزي"},{"id":3638,"era":"c10","t":"فتح العثمانيين رودس وانتزاعها من فرسان القديس يوحنا .","s":"كانت جزيرة رودس جزيرة مشاكِسة؛ إذ كانت حصنًا حصينًا لفرسان القديس يوحنا الذين كانوا يقطعون طريق الحجَّاج المسلمين الأتراك إلى الحجاز، فضلًا عن أعمالهم العدوانية الموجهة لخطوط المواصلات البحرية العثمانية، فاهتمَّ السلطان سليمان القانوني بفتحها، وأعدَّ حملة عظيمة ساعده على تحقيقِها عدةُ أمور: انشغال أوروبا بالحرب الكبرى بين شارل الخامس (كنت) إمبراطور الدولة الرومانية المقدسة وفرانسوا ملك فرنسا، وعقْ"},{"id":3639,"era":"c10","t":"زحف إسباني صليبي على الفلبين للقضاء على الإسلام فيها .","s":"الفلبين هي عبارة عن مجموعة كبيرة من الجزر تمتدُّ في المحيط الهادي ما بين الأرخبيل الإندونيسي وأرخبيل اليابان، وقد دخلها الإسلام قديمًا، ولكن في ربيع ثاني من هذه السنة فوجئ السكان بسفن إسبانية عسكرية بقيادة ماجلان احتلُّوا الجزر وأخذوا في القتل والنهب، ثم أراد ماجلان أن ينصِّرَ السكان المسلمين قسرًا، فكان هذا سببًا في مصرعه؛ حيث ثار عليه مجموعة من السكان الذين استاؤوا من طريقة تنصيره وإجباره الناسَ"},{"id":3640,"era":"c10","t":"وفاة إسماعيل شاه مؤسس الدولة الصفوية وتولي ابنه طهماسب .","s":"هو أبو المظفر إسماعيل شاه بن حيدر بن جنيد بن إبراهيم بن خواجة علي بن صدر الدين موسى بن الشيخ صفي الدين إسحاق بن جبريل الأردبيلي، المشهور بإسماعيل شاه الصفوي، وجدُّه إبراهيم هو شيخ الطريقة الصفوية التي أسَّسها أصلًا صفي الدين إسحاق, وقيل: إن أول من تشيَّع فيهم صفيُّ الدين أو ابنه موسى صدر الدين. ولد إسماعيل بأردبيل سنة 892هـ وأمه بنت الحسن الطويل، وكانت أمها كاترينا ابنة كارلو يوحنا ملك مملكة طرابز"},{"id":3641,"era":"c10","t":"أبو العباس أحمد السعدي يمتلك مدينة مراكش .","s":"لما توفِّيَ أبو عبد الله محمد السعدي حاكِمُ المغرب اجتمع الناسُ على بيعة ابنه ووليِّ عهده السلطان أبي العباس الأعرج من سائر الآفاق، وآتوه طاعتهم عن رضًا منهم، فاستقام أمره وصرف عزمه إلى تمهيد البلاد واقتناء الأجناد، وتعبئة الجيوش إلى الثغور وشن الغارات على العدو في الآصال والبكور، في أحواز تيلمست وآسفي وغيرهما. وكان النصارى قد خيَّموا بشاطئ البحر وعاثُوا في تلك السواحل فأجلاهم عنها وطهَّر تلك البق"},{"id":3642,"era":"c10","t":"أحمد باشا والي مصر يعلن استقلاله عن الخلافة العثمانية .","s":"طمع أحمد باشا في منصب الصدر الأعظم ولم يفلحْ في تحقيق هدفه، وطلب من السلطانِ أن يعيِّنَه واليًا على مصر فعَيَّنه، وما إن وصل إلى مصر حتى حاول استمالةَ الناس وأعلن نفسه سلطانًا مستقلًّا؛ حيث جمع حولَه بعض مماليك الشراكسة وشيوخ العربان، وأعاد تنصيبَ المتوكل على الله الخليفة العباسي المتنازل عن الخلافة للعثمانيين، وسرَّح الجيش الانكشاري عنده، ونظَّم جيشًا جديدًا من المماليك وحاول كذلك أن يوطِّدَ علاق"},{"id":3643,"era":"c10","t":"وفاة المؤرخ ابن إياس زين الدين المصري .","s":"هو زين الدين أبو البركات محمد بن أحمد بن إياس المصري الحنفي، شركسي الأصل، وُلِد في القاهرة سنة 852 وكان جده ووالده من أمراء المماليك، ومع ذلك لم يتصِلْ بالبلاط المملوكي، بل انصرف للتأليف، وهو من تلاميذِ جلال الدين السيوطي، كتب تاريخًا لمصر وصل فيه إلى سنة 928، اشتهر بحياده في التأليف، وبتحرِّيه الدقةَ فيما يكتب، وفيما يصدر من أحكامٍ على معاصريه من السلاطين والأمراء, وكان يقِفُ عند كل حادثة بالشرح "},{"id":3644,"era":"c10","t":"وفاة شيخ الإسلام القاضي شهاب الدين أحمد المزجد .","s":"هو شيخ الإسلام العلامة ذو التصانيف المفيدة والفتاوى السديدة، قاضي قضاة المسلمين شهاب الدين أبو السرور أحمد بن عمر بن محمد بن عبد الرحمن بن القاضي يوسف بن محمد بن علي بن محمد بن حسان بن الملك سيف بن ذي يزن المذحجي السيفي المرادي الشهير بالمُزَجد الشافعي الزبيدي، وكان من العلماء المشهورين وبقية الفقهاء، واحد المحقِّقين المعتمدين المرجوع إليهم في النوازل المعضلة والحوادث المشكلة، وكان على الغاية من ا"},{"id":3645,"era":"c10","t":"وفاة السلطان محمد الوطاسي وتولي أخيه ثم خلعه .","s":"هو السلطان أبو عبد الله محمد بن محمد شيخ الوطاسي المعروف بالبرتغالي، صاحب المغرب، وقع في الأسر عند البرتغاليين مدةً من الزمن وهو صغير السن؛ ولذلك لقِّب بالبرتغالي, تولى السلطنة بعد والده محمد شيخ، وقد انشغل بجهاد البرتغاليين, وبعد وفاته تولى أخوه أبو الحسن علي بن محمد الثاني الملقب أبو حسون، فقام أبو العباس أحمد بن أبي عبد الله محمد بخلع عمه أبي حسون."},{"id":3646,"era":"c10","t":"إجراء عين حنين إلى مكة وعين نعمان إلى عرفات .","s":"كانت الأوامر السلطانية السليمانية قد صدرت بإصلاح عين حنين وعين نعمان- التي أجرتهما زبيدة بنت جعفر بن المنصور زوجة الرشيد، وعَمَرها بعدها الملوك والسلاطين- وعُين لذلك ناظرٌ اسمه مصلح الدين مصطفى من المجاورين بمكة، فبذل جهدَه في عمارتهما، فجَرَت عين حنين إلى مكة، وعين نعمان إلى عرفات."},{"id":3647,"era":"c10","t":"تنصير الموريسكيين المسلمين الإسبان .","s":"أمر الإمبراطور شارل الخامس بتنصير الموريسكيين المسلمين الأسبان، وعهد لمحاكم التفتيش بتنفيذ ذلك الأمر."},{"id":3648,"era":"c10","t":"وفاة الأمير أبي عبد الله محمد الحفصي وقيام ابنه الأصغر وقتاله .","s":"هو الأمير المتوكل أبو عبد الله محمد الخامس بن الحسن الحفصي صاحب تونس، ومن الأعمال التي تنسب إليه المكتبة العبدلية التي أسسها بجامع الزيتونة, وبعد وفاته قام بالأمر بعده ابنه الحسن بن محمد خلفًا له مع وجود الابن الأكبر رشيد، فلجأ رشيد إلى خير الدين بربروسا حاكم الجزائر وطلب مساعدته لاسترداد تونس من أخيه المتغلب عليها، فاستأذن خير الدين السلطان العثماني سليمان، فأذن له وأمده بقوة من الجند، فاستعدَّ ل"},{"id":3649,"era":"c10","t":"تمرد شيعي رافضي على الدولة العثمانية .","s":"بدعم من الدولة الصفوية قاد تمرد شيعي رافضي رجلٌ يقال له بابا ذو النون في منطقة يوزغاد؛ حيث جمع هذا البابا ما بين ثلاثة آلاف وأربعة آلاف ثائر من مريديه، وفرض الخراجَ على المنطقة، وقَوِيت حركته حتى إنه استطاع هزيمة بعض القُواد العثمانيين الذين توجَّهوا لقمع حركته، ثم أرسل له السلطان سليمان القانوني حملةً عسكرية قضت عليه وقتلته، وأُرسِلَ رأسُه إلى إستانبول، ثم ظهر رجلٌ آخر يقال له قلندر جلبي في منطقت"},{"id":3650,"era":"c10","t":"وفاة السلطان الأعظم مظفر شاه صاحب كجرات .","s":"هو السلطان الأعظم مظفر شاه بن محمود شاه، صاحب كجرات، كان عادلًا فاضلًا محبًّا لأهل العلم معروفًا بعنايته بالعلم وتورُّعِه عن غزو ممالك المسلمين، وكان حسنَ الخط، وكتب بيده جملةً من المصاحف، أرسل منها مصحفًا إلى المدينة. وقد خرجت روحُه وهو ساجد."},{"id":3651,"era":"c10","t":"هزيمة إبراهيم اللودي على يد ظهير الدين المغولي بالهند .","s":"غزا ظهير الدين محمد بن عمر الشيخ ميرزا بابر البنجاب، واستولى على لاهور بعد هزيمة إبراهيم اللودي, فكان لهذا النصر أثر في سيطرة بابر على دلهي وآكره، وشمال الهندوستان من نهر السند إلى سواحل بنطالة، وإقامة الدولة المغولية."},{"id":3652,"era":"c10","t":"انتصار العثمانيين في موهاكس على ملك المجر .","s":"كان ملك المجر فيلاد يسلاف الثاني جاجليو قد عزم على فكِّ أي تعهدات كانت قد أُعطيت من قِبَل أسلافه لسلاطين الدولة العثمانية، وذهب إلى حدِّ قَتْل مبعوث السلطان سليمان إليه، وكان المبعوثُ يطالب بالجزية السنوية المفروضة على المجر، فسيَّرَ السلطان سليمان القانوني جيشًا من القسطنطينية لمحاربة المجر، مؤلفًا من مائة ألف جندي و300 مدفع و800 سفينة في نهر الطونة- الدانوب- لنقل الجيوش من برٍّ إلى آخر، فسار الج"},{"id":3653,"era":"c10","t":"إقامة محكمة التفتيش الإسبانية في غرناطة .","s":"أقام شارل الخامس (شارلكان) ملك إسبانيا محكمةَ تفتيش بغرناطة مهمتُها القبض على المسلمين في حال قيامِهم بأحد الأنشطة التالية: الاتجاه للقبلة (وهذا يعني مجرد الصلاة), أو ذبح الماشية على الطريقة الإسلامية, أو التكلم باللغة العربية, أو ارتداء الملابس العربية، وغيرها من الأشياء الأخرى، وكلها قاضية بقمع الهُوية الإسلامية نهائيًّا في إسبانيا ظاهرًا وباطنًا!"},{"id":3654,"era":"c10","t":"هطول مطر غزير بمراكش .","s":"نزل مطر غزير بمراكش حتى امتلأت منه الآبار وتهدَّمت الدُّور، وصار الناس يؤرِّخون بعام الآبار."},{"id":3655,"era":"c10","t":"انتصار السلطان ظهير الدين بابر شاه على جيش هندي .","s":"انتصر السلطانُ ظهير الدين محمد بن عمر الشيخ ميرزا بابر شاه على جيش هندي ضخم يضم 100 ألف جندي، وألف فيل، في معركة بانيبات التي استمرت 7 ساعات فقط، وينتمي بابر شاه إلى سلالة تيمورلنك التي أقامت حكمًا إسلاميًّا للدولة المغولية في الهند استمر 3 قرون."},{"id":3656,"era":"c10","t":"استيلاء خير الدين بربروسا والي الجزائر على البينون من الإسبانيين .","s":"تمكَّن خير الدين بربروسا من طرد الإسبان من الجيوبِ التي أقاموها في الجزائر، فضمَّ إليه عنابة وقالة في شرقي الجزائر، ثم حقق انتصارًا باهرًا على الإسبانيين حين استولى في هذا العام على حصن بينون الإسباني على الجزيرة المواجهة لبلدة الجزائر، وقد كان قد استمر يقصِفُ الحصنَ بقذائف مدافعه طوال عشرين يومًا حتى تداعت جوانبه، ثم اقتحم الحصنَ مع قوات كثيفة العدد كانت تحملُها خمس وأربعون سفينة جاءت من الساحل، "},{"id":3657,"era":"c10","t":"وفاة الشيخ أبي محمد الغزواني .","s":"هو الشيخ أبو محمد عبد الله بن عجال الغزواني أصلُه من مراكش من غزوان، قبيلة من عرب تامسنا، ولِدَ بمدينة القصر الكبير وبها تعلم مبادئ علوم الدين والأدب, وكان في ابتداء أمره يقرأ العلمَ بمدرسة الوادي من عدوة الأندلس بفاس، فحصلت له إرادة فسافر إلى مراكش ولازم الشيخ التباع وتخرج به، ثم انتقل إلى بلاد الهبط فنزل بها على قبيلة، يقال لهم: بنو فزنكار، واجتمع عليه كثيرٌ من مريديه واشتهر أمرُه وعظُمَ صيتُه و"},{"id":3658,"era":"c10","t":"تقوية الجبهة الداخلية في الجزائر بإدخالها تحت الحكم العثماني .","s":"في الوقت الذي كان خير الدين بربروسا يواجه خطر الإسبان في الجزائر، كان يعمل في ذات الوقت على تقوية الجبهة الداخلية بتوحيد المغرب الأوسط, والذي لم يخلو من مؤامرات بني زيان والحفصيين ومن بعض القبائل الصغيرة، ولكنه استطاع مدَّ منطقة نفوذه باسم الدولة العثمانية، ودخلت الإمارات الصغيرة تحت السيادة العثمانية؛ لكي تحتمي بهذه القوة من الأطماع الصليبية الإسبانية ومِن قهرِها على اعتناق النصرانية، وما لبث أن "},{"id":3659,"era":"c10","t":"أول معاهدة امتيازات أجنبية في الدولة العثمانية مع فرنسا .","s":"كانت أوروبا تعيش انقساماتٍ سياسيةً ودينية خطيرة، أدى ذلك إلى أن تنوعت مواقفُ الدول الأوروبية من الدَّولة العثمانية حسَبَ ظروف كلِّ دولة، فكان تشارلز الخامس ملك الإمبراطورية الرومانية المقدَّسة ينافسُ فرانسوا الأول ملِكَ فرنسا على كرسيِّ الحكم للإمبراطورية الرومانية، فرأى فرانسوا الأولُ أن يكسِبَ الدولة العثمانية صديقاً له، فوقف منها موقِفَ التودد والرغبة في الوِفاق ، فبدأت مفاوضات فرنسا مع الدولة "},{"id":3660,"era":"c10","t":"حدوث وقعة آنماي بين الوطاسيين والسعديين بالمغرب .","s":"لم يعُدْ لبني وطاس وصولٌ إلى مراكش ولا إلى أحوازها، فكان أبو العباس أحمد الأعرج السعدي يتلاقى مع أبي العباس أحمد الوطاسي بتادلا وأحوازها، ووقعت بينهما معركة بموضع يقال له: آنماي، وهو قرب مراكش، وبه زاوية الشيخ أبي العزم رحال الكوش، وكانا قد افترقا على اصطلاح."},{"id":3661,"era":"c10","t":"السلطان العثماني سليمان القانوني يحاصر فيينا عاصمة النمسا .","s":"بعد أن استطاع العثمانيون فتحَ بودابست عاصمة المجر, وتعيين الخليفة سليمانِ القانوني أميرَ ترانسلفانيا جان زابولي عليها, ادَّعى الأمير فرديناند أخو ملك النمسا شارلكان أحقيَّةَ ملك المجر بدلَ جان الذي وضعه سليمان القانوني، فهجم عليه وهزم الملِكَ جان الذي استنجد بسليمان، فسار إليه الخليفة فهرب فرديناند متجهًا إلى فيينا، فتبعه الخليفة سليمان وتابع في ضغطِه حتى بلغت جيوشه أسوار فيينا عاصمة الإمبراطورية "},{"id":3662,"era":"c10","t":"خير الدين بربروسا والي الجزائر يهاجم السواحل الإسبانية .","s":"قام خير الدين بربروسا والي الجزائر في هذا العام بتوجيه ست وثلاثين سفينة خلال سبع رحلات إلى السواحل الإسبانية في الحوض الغربي للبحر المتوسط، وبفضل الله ثمَّ مساعدات الدولة العثمانية وموارد خزينة الجزائر المتنوِّعة من ضرائبَ وسبيٍ ومغانمَ وزكاة والعُشر والجِزية والفيء والخراج، وما يقوم به الحكَّام ورؤساء القبائل والعشائر من دفْعِ العوائد وغيرها- أصبحت دولة الجزائر لها قاعدةٌ اقتصادية قوية، لقد تضرَّ"},{"id":3663,"era":"c10","t":"سلطان حضرموت يعلن ولاءه للدولة العثمانية .","s":"أخذت علاقة السلطان بدر أبو طويرق بالدولة العثمانية تزداد يومًا بعد يوم؛ ففي أواخر سنة 936 توقَّفت حملة القائد العثماني مصطفى بيرم المتَّجهة إلى الهند للتصدِّي للبرتغاليين في ميناء الشحر؛ بسبب رداءة الأجواء الملاحية، وعَقِبَ توقفها خرج الضابِطُ صفر سلمان إلى المدينة بعد أن استأذن من السلطان بدر أبو طويرق حاملًا معه خِلعةً وكساء قدَّمها هدية للسلطان بدر أبو طويرق نيابةً عن قائد الحملة مصطفى بيرم، وق"},{"id":3664,"era":"c10","t":"خوض الأسطول العثماني معركة بحرية مع الأسطول البرتغالي .","s":"خاض الأسطول العثماني معركةً بحرية مع الأسطول البرتغالي المكوَّن من 190 سفينة حربية و210 سفن نقل محمَّلة بستة وعشرين ألف جندي، وذلك قربَ جزيرة ديو الواقعة في المحيط الهندي، والتي تبعد عن شمال جزيرة بومباي بمسافة 250 كم. وقد حقَّق العثمانيون انتصارًا كبيرًا في هذه المعركة."},{"id":3665,"era":"c10","t":"معاهدة الصلح بين العثمانيين والنمسا .","s":"بعد أن طرد العثمانيون ملكَ النمسا فرديناند من المجَر؛ لتدخله في أمورِها وحصارِهم لفيينا سنة936. عاد ملك النمسا بجيشه هذا العام ودخل بودابست، لكنه لم يستطع أن يستوليَ عليها؛ بسبب مقاومة الحامية العثمانية فيها، فلما سار الخليفةُ سليمان بجيشه نحو المجر ليُخرج منها ملك النمسا طلب الملك فرديناند من الخليفة الصلحَ فوافق عليه وعلى الرجوع بجيشه, وذلك لِما بلغه من قوة استعدادات شارلكان الدفاعية، وأنَّ سفنً"},{"id":3666,"era":"c10","t":"معاهدة إستانبول بين العثمانيين وألمانيا .","s":"قامت الدولة العثمانية بإبرام معاهدة إستانبول مع ألمانيا، والتي تم بمقتضاها تثبيت الحدود بين الجانبين، واعترف الألمان بموجِبها بالفتوحات التركية في أوروبا، وقرَّرت المعاهدة أن يدفع الألمانُ ضريبة سنوية للعثمانيين، وألا تُستعمَلَ صفة \"إمبراطور\" في المكاتبات الرسمية مع الدولة العثمانية."},{"id":3667,"era":"c10","t":"وقعة الحمر وهزيمة المسلمين في المغرب .","s":"وقعت غزوة الحمر بين النصارى والقائد عبد الواحد بن طلحة العروسي على مقربةٍ من آصيلا، وانتصر فيها النصارى على المسلمين, واستُشهد فيها الشيخ أبو الحسن علي بن عثمان الشاوي. كان رحمه الله لما انهزم الناسُ استقبل النصارى وسيفُه في يدِه، فكان ذلك آخِرَ العهد به، ولما رجع الناسُ من الغد ليحملوا قتلاهم لم يوقَفْ لأبي الحسن على عينٍ ولا أثر، وإنما وُجد غنباز من لباسِه عند النصارى وفيه أثَرُ طعنة في صدره- ال"},{"id":3668,"era":"c10","t":"السلطان العثماني سليمان القانوني ينشئ أول أسطول بحري .","s":"عزم السلطانُ سليمان القانوني- بعد أن استولى على بلغراد، السَّفَرَ بسائر جنوده إلى إسبانيا للاستيلاء عليها، وبدا للسلطان سليمان القانوني أنَّه لا بد له من رجلٍ يعتمد عليه في دخول تلك البلاد على أن يكون عالِمًا بأحوالها، فوقع اختياره على خير الدين بربروسا؛ لما يعرفه عنه من شجاعة وإقدام، وكثرة هجومِه على تلك النواحي، وما استردَّه من بلاد المسلمين في شمال إفريقيا، وكيف أقَرَّ الحكم العثماني فيها، فوجه"},{"id":3669,"era":"c10","t":"استيلاء خير الدين باشا التركي على تونس ثم طرده منها .","s":"كان أمر بني أبي حفص أصحاب تونس قد مرج في هذه المدَّة وتداعى إلى الاختلال، فقام القائد خير الدين باشا التركي- وهو من القادة الأتراك العظماء- بالاستيلاء على تونس، ففرَّ صاحبها الحسن بن محمد الحفصي إلى طاغية الإسبان صاحب قشتالة، فأعطاه العساكِرَ وجاء بها إلى تونس، فنزل عسكر النصارى ببرج العيون قرب حلق الوادي، وتقدَّموا إلى تونس فملكوها، وانهزم خير الدين إلى الجزائر، وشارك النصارى الحسن بن محمد في إمر"},{"id":3670,"era":"c10","t":"غارات خير الدين بربروسا على السواحل الأوربية .","s":"بعد أن تمَّ إعدادُ الأسطول العثماني الجديد بقيادة خير الدين بربروسا خرج بأسطوله القوي من الدردنيل متجهًا نحو سواحل إيطاليا الجنوبية، فاستطاع أن يأسِرَ الكثير منها، وأغار على مدنِها وسواحلِها، ثم اتجه نحوَ جزيرة صقلية، فاسترجع كورون وليبانتو وكريت."},{"id":3671,"era":"c10","t":"عقد صلح بين بني وطاس والسعديين لإنهاء حالة الحرب بينهما\n  .","s":"لما رأى أهل المغرب ما وقع بين السلطان أبي العباس أحمد الوطاسي صاحب فاس وأبي العباس أحمد السعدي المعروف بالأعرج صاحب مراكش من الاقتتال على الملك، والتهالك عليه، وفناء الخلق بينهم- دخلوا في الصلح بينهم والتراضي على قسمة البلاد، وحضر لذلك جماعةٌ من العلماء والصلحاء، منهم أبو حفص عمر الخطاب، وأبو الرواين المحجوب، وكان صاحب حالٍ وجذبٍ، فجعل الناس يوصونه بالسكوت مخافةَ أن يُفسِدَ عليهم أمرَهم، فلما دخلو"},{"id":3672,"era":"c10","t":"وفاة السلطان أبو عبد الله الصغير آخر حكام بني الأحمر في غرناطة .","s":"هو السلطان أبو عبد الله الصغير محمد الثاني عشر بن الحسن بن سعد بن علي بن يوسف بن محمد: آخر حكام بني نصر ابن الأحمر، المنحدرة من قبيلة الخزرج القحطانية في غرناطة، وكان قد تولى الرياسةَ بعد منازعاته مع عمه أبي عبد الله الزغل محمد بن سعد، وكانت دولة بني الأحمر في هذه المدة متماسكةً، والفتنة بين أفرادها متشابكة، والعدو فيما بين ذلك يخادعُهم عمَّا بأيديهم، جاهد أبو عبد الله الصغير النصارى كثيرًا ووصل ا"},{"id":3673,"era":"c10","t":"خير الدين بربروسا يفتح تونس .","s":"كانت المرحلة الثانية بالنسبة لخير الدين بربروسا بعد هجومه على السواحل الجنوبية لإيطاليا وجزيرة صقلية هي تونس؛ وذلك لتنفيذ خطة الدولة العثمانية، والتي تقتضي تطهير شمال إفريقيا من الإسبان كمقدمة لاستعادة الأندلس، وصل الأسطول العثماني تحت قيادة خير الدين إلى السواحل التونسية، فعرج على مدينة عنابة، وتزوَّد ببعض الإمدادات، ثم تقدَّم نحو بنزرت، ثم اتجه إلى حلق الواد؛ إذ تمكَّن منها بدون صعوبة، واستُقبِل"},{"id":3674,"era":"c10","t":"العثمانيون يعاودون السيطرة على العراق .","s":"بعد أن ظلَّت العراق تحت الحكم الصفوي من أيام مؤسِّسها الأول إسماعيل شاه، قام الخليفة سليمان القانوني بإعلان الحرب في هذه السنة على الصفويين، فسار بجيشِه من أجل إبطال محاولات شاه طهماسب بن إسماعيل الصفوي لنشر المذهب الشيعي في العراق بدلًا من المذهب السنِّي. فتحرك موكب الجيشِ العثماني تحت قيادة سليمان القانوني، وكبار قادته والأعيان، وكتائب الخيالة؛ حيث خرج الجميعُ من إسكدار عبر آسيا الصغرى، مرورًا ب"},{"id":3675,"era":"c10","t":"استعادة الإسبان احتلال تونس بعد انتزاعها من العثمانيين  .","s":"لم تلبث تونس كثيرًا تحت يد العثمانيين حتى اتفق شارل الخامس (شارلكان) ملك إسبانيا وأسبان برشلونة ورهبان مالطة على الحرب واستعادة تونس التي كانت تحت يد الإسبان قبل أن يستعيدها خير الدين بربروسا العام الماضي، مستغلين انشغال العثمانيين بحربهم ضد الصفويين الرافضة، فتوجَّه الجيش بقيادة شارلكان نفسه ملك إسبانيا بحملة بحرية كبيرة، تكوَّنت من ثلاثين ألف مقاتل إسباني وهولندي وألماني ونابولي وصقلي، على ظهر خ"},{"id":3676,"era":"c10","t":"توقيع الوزير العثماني داماد إبراهيم باشا معاهدة امتيازات مع فرنسا .","s":"حصلت فرنسا بموجِب معاهدة أبرمتها مع الدولة العثمانية على امتيازاتٍ عسكرية واقتصادية؛ لتنميتِها والحيلولة دون وقوع فرنسا تحت نفوذ ملك إسبانيا وألمانيا، وهو ما مهَّد السبيل لكي يرسوَ الأسطول العثماني في ميناء طولون الفرنسي في البحر المتوسط."},{"id":3677,"era":"c10","t":"خير الدين بربروسا يلاحق الأسطول الإسباني في عدة معارك .","s":"قام خير الدين بربروسا بالهجومِ على جزر البليار الإسبانية وعلى سواحلها الجنوبية، فاجتاز مَضِيقَ جبل طارق، وأطلق العِنانَ لنفسِه بالانقضاض على السفُن الإسبانية والبرتغالية العائدة من الأراضي الأمريكية، والمحمَّلة بالذهب والفضة، فاهتَزَّت لتلك الأحداث جميعُ الأوساط النصرانية، وأقلقت شارل الخامس ملك إسبانيا الذي اعتقد أنَّ خير الدين لن يقوى شأنُه بعد حادثة تونس السابقة، ويُعتبَر ذلك هو ردَّ الفعل على "},{"id":3678,"era":"c10","t":"معاهدة بين البرتغال والوطاسيين  .","s":"إثر الهزيمة التي تلقَّتها أسرة الوطاسيين أمام السعديين في وقعة بير عقبة تقرَّب أحمد الوطاسي من البرتغال؛ وذلك نتيجة شعوره بانشغال العثمانيين في حروبِهم ضِدَّ الإسبان، ووقَّع معهم معاهدة لمدة أحد عشر عامًا تقضي بوضع المغاربة المقيمين في ضواحي آصيلا وطنجة والقصر الصغير تحت السلطة القضائية لملك فاس، كما يجوز لرعايا الملك الوطاسي المتاجرة بحُرية داخلَ تلك المناطق باستثناء تجارة الأسلحة والبضائع المحظو"},{"id":3679,"era":"c10","t":"وقعة بير عقبة بوادي العبيد بين الوطاسيين والسعديين .","s":"كانت الأسرة الوطاسية هي الحاكمةَ على فاس بزعامة أبي العباس أحمد بن أبي عبد الله محمد، وكانت الأسرةُ السعدية أخذت في التوسُّع بزعامة أبي العباس أحمد الأعرج وانتقلت من مراكش، وهدَّدت سلطنة الوطاسيين، فقامت بين الأسرتين حروبٌ دامت أيامًا، تعتبر وقعةُ بير عقبة من أعظم الوقعاتِ التي كانت بين الوطاسيين والسعديين، وتحدَّث بها العامة في أنديتهم كثيرًا وبالغوا في وصفِها والإخبار عنها، وقد ذكرها شعراؤهم في "},{"id":3680,"era":"c10","t":"هزيمة البنادقة على يد السلطان العثماني سليمان القانوني .","s":"نشبت معركةٌ كبيرة بحرية بين الأسطول العثماني بقيادة خير الدين بربروسا وبين الأسطولين الإسباني والبندقي على شواطئ اليونان الغربية، استطاع فيها الأسطولُ العثمانيُّ تحطيمَ الأسطولين المشتركين، فأدى ذلك لبسط السيادة العثمانية على البحر المتوسطِ الجزءِ الغربيِّ منه بعد أن كان للإسبان."},{"id":3681,"era":"c10","t":"دخول اليمن تحت الحكم العثماني .","s":"كان الأسطولُ العثماني المتجه لقتال البرتغاليين على شواطئ الهند من مهمَّاته المرورُ على اليمن وإخضاعُها للحكم العثماني، فعند وصول الأسطول العثماني بقيادة سليمان باشا الخادم، والمؤلَّف من سبعين سفينة، اتجه على رأس عشرين ألف جندي وفتح عدن ومسقط، وحاصر جزيرة هرمز حتى فتحَها."},{"id":3682,"era":"c10","t":"وفاة العلامة وجيه الدين عبد الرحمن بن الدَّيبع .","s":"العلَّامةُ الحافِظُ وجيهُ الدِّين أبو محمد عبد الرحمن بن علي الدَّيبع الشيباني العبدري الزَّبيدي الشافعي. قال في آخِرِ كتابه «بغية المستفيد بأخبار زبيد»: \"كان مولدي بمدينة زَبيد المحروسةِ في يوم الخميس الرابِعَ مِن المحَرَّم الحرام سنةَ سِتٍّ وستين وثمانمائة في منزل والدي منها، وغاب والدي عن مدينةِ زبيدٍ في آخرِ السنة التي وُلِدتُ فيها ولم تَرَه عيني قطُّ، ونشأتُ في حجر جدِّي لأمِّي العلَّامة الصّ"},{"id":3683,"era":"c10","t":"البرتغال يوقِّعون معاهدة مع السعديين للحد من نفوذ العثمانيين .","s":"حاول البرتغاليون عقدَ هُدنة مع السعديين كما فعلوا مع خصومِهم الوطاسيين، فبعثوا وفدًا إلى مراكش للتفاوض مع السلطان أبي العباس أحمد الأعرج الذي استجاب لذلك؛ لأنه كان في حاجة إلى تنظيم أمور دولته الناشئة لا سيما بعد الانتصارات التي حقَّقها ضد خصومه الوطاسيين في موقعة بير عقبة، واتفق البرتغاليون مع السعديين على عقدِ هدنة بينهما في 25 ذي القعدة من هذه السنة, لمدة ثلاث سنوات، مع إقامة تبادُل تجاري بين ر"},{"id":3684,"era":"c10","t":"تحالف عثماني فرنسي لغزو إيطاليا .","s":"كان العثمانيون قد تحالفوا مع الفرنسيين على غزو إيطاليا: العثمانيون بحرًا من الجنوب، والفرنسيون برًّا من الشمال، لكنَّ العثمانيين ترددوا في الاستمرار؛ خشية من التمرد الأوربي عمومًا، وكانت فرنسا تشجِّعُها على الاستمرار لإنقاذ جزيرة كورفو من البنادقة، فتابعت فرنسا سيرَها من الشمال حتى احتلَّت ميلانو وجنوة، ثم قام البابا بالتوسُّط بين فرانسوا ملك فرنسا، وبين النمسا في سبيل الوحدة الأوربية عمومًا، ووعد"},{"id":3685,"era":"c10","t":"حملة عثمانية لطرد البرتغاليين من سواحل البحر الأحمر .","s":"أرسل السلطانُ العثماني سليمان القانوني حملةً عسكرية بهدف ضرب البرتغاليين في ميناء ديو بالهند، الذين كانوا يعيثون فسادًا في موانئ البحر الأحمر والبحر العربي، بينما كان الغرض الحقيقي من ورائها هو السيطرةَ على بلاد اليمن، وكانت الحملة تتكَّون من عشرين ألف جندي، تحملهم ثمانون سفينة بقيادة سليمان باشا الخادم أحد المماليك المقرَّبين من السلطان العثماني سليمان القانوني، وكان قد سبق وصولَ هذه الحملة إلى س"},{"id":3686,"era":"c10","t":"استنجاد الهند بالعثمانيين ووقعة ديو الثانية .","s":"وصل السفيرُ الهندي من كوجرات يستنجد الخليفة العثماني ضِدَّ البرتغاليين الذين وصلوا إلى سواحل الهند، وآخَرُ مِن دلهي يستنجد ضِدَّ همايون بن ظاهر الدين محمد المشهور ببابر، وهو من المغول الذين دخلوا الهندَ وحكموها، فانطلق سليمان باشا الخادم إلى كوجرات ودخل بعض القلاع التي أقامها البرتغاليون على سواحل الهند، فالتقى الأسطولُ العثماني بالأسطول البرتغالي أمام مدينة ديو على ساحل الملبار، ولكِنَّ الأسطول ا"},{"id":3687,"era":"c10","t":"استيلاء العثمانيين على ميناء عدن .","s":"استولى العثمانيون على ميناء عدن، وبعدها شنَقوا أمير عدن \"عامر الثالث\" بتهمة تقديم التسهيلات للبرتغاليين، وعدم طاعته للخليفةِ العثماني."},{"id":3688,"era":"c10","t":"معركة بروزة وهزيمة أندرى حليف ملك إسبانيا  .","s":"دارت معارك عديدة بين أندرى دوريا القائدِ البحري الجنوي- حليف ملك إسبانيا شارلكان ضد العثمانيين- وبين الأسطول العثماني، كان أشهرُها معركة بروزة والتي مُنِيَ فيها أندرى بهزيمةٍ ساحقة أمام الأسطول العثماني بقيادة خير الدين برباروسا."},{"id":3689,"era":"c10","t":"فتح السلطان محمد الشيخ السعدي حصن النصارى فونتي بسوس .","s":"لما استقلَّ السلطان أبو عبد الله محمد الشيخ السعدي بأمر السوس، واجتمعت الكلمةُ عليه؛ صرفَ عَزمَه إلى جهاد العدوِّ الذي بثغوره وحصونه، وأرهف حدَّه لتطهيرها من بقايا شغبه، فانتصر عليهم واستأصل شأفتَهم وقطع من تلك النواحي دابِرَهم، وحسم آفتَهم، ففتح حصن فونتي الذي بناه البرتغاليون بالسوس بعد أن أقاموا فيه اثنتين وسبعين سنة، وكان السلطان السعدي منصورًا بالرعب!"},{"id":3690,"era":"c10","t":"بناء حصن أغادير .","s":"بنى الأميرُ السلطان أبو عبد الله محمد الشيخ السعدي حصنَ أغادير بالسوس الأقصى، وذلك بعدما أجلى النصارى البرتغال من الموضع المعروف بفونتي، وكان له في اختطاطه رأيٌ مصيب وفِراسة تامة."},{"id":3691,"era":"c10","t":"معاهدة إستانبول بين الدولة العثمانية والبندقية .","s":"عقدت الدولةُ العثمانية معاهدةً مع البندقية عُرِفت بمعاهدة إستانبول دفَعَت البندقية بمقتضاها حوالي 300 ألف ليرة ذهبية للعثمانيين، كغرامة حرب، وقد حالت هذه المعاهدةُ دون انضمام البندقية إلى الإمبراطور الألماني شارل كوينت، الذي كان في حربٍ مع العثمانيين أثناءَ تلك الفترة."},{"id":3692,"era":"c10","t":"السعديون يفتحون سانتاكروز والبرتغال يتخلون عن آسفي وأزمور .","s":"حقَّق السعديون على صعيدٍ آخر نصرًا كبيرًا على البرتغاليين، وفتحوا حصن سانتاكروز في السوس، وما أن علِمَ ملك البرتغال جان الثالث بهذا الخبر حتى أمر حامياتِ آسفي وأزمور بالجلاء فورًا عنها، وقد وجَّه الملك جان الثالث في هذا الشأن إلى سفيره بمدريد رسالةً يُطلِع فيها الإمبراطور الإسباني شارل الخامس، حيث جاء فيها ذِكرُ الأسباب التي أجبرت البرتغال على اتخاذ قرار الجلاء عن قاعدتي آسفي وأزمور، ومنها تزايُدُ"},{"id":3693,"era":"c10","t":"هزيمة ملك إسبانيا شارلكان في معركة باب الواد في الجزائر .","s":"عزم شارل الخامس (شارلكان) ملكُ إسبانيا على القيام بحملة عسكرية تستهدفُ القضاء على حركةِ الجهاد الإسلامي في الحوضِ الغربيِّ للبحر المتوسط، وقبل أن يشرَعَ في تنفيذها حدث هدوءٌ نسبيٌّ ساد القارةَ الأوربية إثرَ عقدِ هُدنة نيس في محرم 945 (يونيو 1538م) مع فرنسا، والتي كانت مدتها عشر سنوات. ومما شجع شارلكان على هذه الحملة علمُه بأن القائد التركي خير الدين بربروسا قد ذهب إلى إستانبول للَّقاء بالسلطان الع"},{"id":3694,"era":"c10","t":"انتزاع الأسطول العثماني مدينة نيس من الإسبان وتسليمها لفرنسا  .","s":"قام شارلكان ملكُ إسبانيا بإعلان الحرب ضِدَّ فرنسا التي تعتبَرُ عدوًّا له باعتبارها من حلفاء الدولة العثمانية, فقام الفرنسيون بالاستنجاد بالعثمانيين وتوقيع معاهدةٍ جديدة ضِدَّ شارلكان الذي كان يحكُمُ نيس، فانضمَّ الأسطول الفرنسي إلى الأسطول العثماني بأمرٍ من ملك فرنسا، ووضَعَ قائدُ الأسطول الفرنسي الأمير فرانسوا دبو بوربون قواتِه تحت قيادة القائد التركي خير الدين بربروسا، باعتباره القائِدَ العامَّ "},{"id":3695,"era":"c10","t":"بسط العثمانيين نفوذهم على المغرب الأوسط .","s":"استطاع العثمانيون أن يسيطروا على الجزائرِ بمساعدة أمير البحرِ عروج باشا، ومن بعدِه أخوه خير الدين بربروسا، وكذلك استطاعوا أن يسيطروا على تونس شيئًا فشيئًا، وكذلك على ليبيا بعد ذلك حتى صارت أقاليمها الثلاثة- طرابلس وبرقة وفزان- تحت الولاية العثمانية."},{"id":3696,"era":"c10","t":"انقراض أمر أمراء بني عبد الحميد العروسيين .","s":"كان لأمراء بني عبد الحميد العروسيين- أصحاب قصر كتامة- رياسةٌ وسياسةٌ وجهادٌ في العدوِّ إلى أن انقرض أمرُهم, وأخبر غيرُ واحد من فقهاء قصر كتامة أنَّ الشيخ أبا الرواين المحجوب جاء إلى القصر وصاحَبَه يومئذ القائدُ عبد الواحد العروسي في عصبةٍ من أقاربه أولاد عبد الحميد، فصعد أبو الرواين صومعةَ المسجد ثم نادى بأعلى صوتِه: يا بني عبد الحميد، اشتروا مني القصرَ وإلَّا خرجتُم منه في هذه السنة، فسمع القائدُ"},{"id":3697,"era":"c10","t":"اتخاذ خير الدين بربروسا مدينة طولون الفرنسية قاعدة للعثمانيين .","s":"بعد طردِ خيرِ الدين بربروسا الإسبانَ من مدينة نيس وتسليمِها للفرنسيين استقَرَّ بأسطوله في مدينة طولون الفرنسية، وجعلَها قاعدةً للجيشِ الإسلاميِّ وأسطولِه، بعد أن غادرَها معظَمُ سكانِها بأمرِ ملك فرنسا وتركوها في أيدي المسلمين."},{"id":3698,"era":"c10","t":"استيلاء الأسطول العثماني على صقلية وبعض السواحل الإيطالية .","s":"استولى الأسطول العثماني بقيادة خير الدين بربروسا على صقلية وبعضِ السواحل الإيطالية، ودمَّرَ استحكاماتِها، ثم استولى على ميناء أوستيا الواقع على نهر تيبر، الذي يبعد 15 كم عن مدينة روما مقرِّ البابويَّة الكاثوليكية في العالم."},{"id":3699,"era":"c10","t":"سقوط نيس وطولون ثانية في يد النصارى  .","s":"كان تحرير نيس من أيدي الإسبان- بعد اتفاق الفرنسيين مع العثمانيين ضد الإسبان- قد أثار ثائرة النصارى جميعًا في أوروبا ضد هذا التصرُّف الفرنسي، وأخذت الدعايةُ المضادة للمسلمين تجتاحُ أرجاء أوروبا، يحمِلُها الإسبان وغُلاة الصليبية، ويستثمرونها إلى أقصى الحدود، ومن ذلك قولهم: إنَّ خير الدين بربروسا القائدَ العثماني قد اقتلع أجراسَ الكنائس، فلم تعُدْ تَسمع في طولون إلا أذان المؤذنيين, وبقي خير الدين وال"},{"id":3700,"era":"c10","t":"استيلاء السلطان محمد الشيخ السعدي على مراكش وتجديد البيعة له .","s":"كان السلطان أبو عبد الله محمد الشيخ السعدي بعد القبض على أخيه واستقلاله بالأمر، قد أقام بالبلاد السوسية مثابرًا على جهاد العدوِّ إلى أن قلع عروقَ مفسدتِه منها، وكانت مراكش في هذه المدَّة قد توقَّفت عن بيعته، وتربصت عن الدخول في دعوته اتقاءً للوطاسيين وارتيابًا في أمره إلى ماذا يؤول، واستمَرَّ الحال إلى هذه السنة فانقادت له حينئذ، وبايعه أهلُها فقَدِمَها واستولى عليها وخَلُصَ له جميعُ ما كان بيد أخ"},{"id":3701,"era":"c10","t":"خير الدين بربروسا يواصل جهاده على سواحل أوروبا .","s":"لم تتوقف الحرب بين إسبانيا والمسلمين؛ فقد استمرَّ خير الدين بربروسا في ممارسة الأعمال القتالية أثناء طريق عودته، فتوقَّف أمام مدينة جنوة، فارتاع مجلسُ شيوخها فأرسل له مجموعةً من الهدايا الثمينة مقابِلَ عدم التعرض للمدينة بأذًى، فتابع خير الدين طريقَه حتى وصل جزيرة (البا) التي كانت تحت حكم إسبانيا فاحتلَّها وغَنِمَ ما بها، كما احتَلَّ عددًا من المدن الساحلية، من بينها مدينة (لبياري) ورجع إلى إستانب"},{"id":3702,"era":"c10","t":"معاهدة بين الصفويين بإيران والبرتغال .","s":"تم توقيع معاهدة بين إيران الصفوية والبرتغال، سلَّمت بموجِبها إيرانُ بسيطرةِ البرتغال على ميناء هرمز، في مقابل أن تتعهد البرتغال بالوقوفِ مع إيران ضِدَّ العثمانيين، وظلَّ حكم البرتغاليين لهرمز حتى عام 1031."},{"id":3703,"era":"c10","t":"وقعة وادي درنة بتادلا وأسر الأمير أبي زكريا الوطاسي ومهلكه .","s":"حدثت وقعة وادي درنة بتادلا بين الأشراف السعديين والوطاسيين، وقد أُسِرَ فيها الأمير أبو زكريا الوطاسي، ومات في تلك الليالي القريبة غمًّا وأسفًا، وكان سلطانُ السعديين يومئذ أبا عبد الله محمد الشيخ الملقَّب بالمهدي؛ فإنَّه تغلَّب على أخيه أبي العباس أحمد الملقب بالأعرج وانتزَع منه المُلكَ وسجَنَه."},{"id":3704,"era":"c10","t":"استيلاء العثمانيين على تلمسان .","s":"استولى العثمانيون على تلمسان بقيادة حسن بن خير الدين بربروسا، وذلك في أواسط شعبان، وأخرج منها الأمير أحمد ابن الأمير عبد الله ووزيره منصور بن أبي غانم ولَحِقا بدبدو، واستمرَّت تلمسان في يد العثمانيين إلى أواسط صدر المائة الثالثة عشرة."},{"id":3705,"era":"c10","t":"وفاة القائد المجاهد خير الدين بربروسا  .","s":"هو القائد العثماني خيرُ الدين خضر بن يعقوب بن يوسف أحدُ أكبرِ قادة الأساطيل العثمانية، وأحد رموزِ الجهاد البحري، لقَّبه السلطان سليم الأول بخير الدين باشا، وعُرِف لدى الأوروبيين ببربروسا، أي: ذي اللحية الحمراء، ولِدَ سنة 871 ويذكَرُ أن والده يعقوب أصلُه من بقايا الفاتحين المسلمين الأتراك الذين استقرُّوا في جزيرة مدللي إحدى جزر الأرخبيل، وأمه سيدة مسلمة أندلسية كان لها الأثرُ على أولادها في تحويل ن"},{"id":3706,"era":"c10","t":"العثمانيون يصلون إلى الخليج العربي .","s":"وجَّه الخليفة العثماني سليمان القانوني حملةً بحرية بقيادة محيي الدين بيري، مهمتُها طرد البرتغاليين من الخليج العربي، فحاصر هرمزَ التي كانت بيدِ البرتغاليين، لكنَّه فَشِلَ في الاستيلاء عليها بعد أن تكبَّد خسائر فادحة، فتوجَّه إلى البصرة ومعه ثلاث سفُنٍ فقط، وبقيَ فيها بعضَ الوقتِ، ثمَّ ذهب إلى مصر، ولَمَّا علم الخليفةُ سليمان به أمرَ بالقبض عليه وقُتل بعد ذلك في عام 961هـ."},{"id":3707,"era":"c10","t":"معاهدة إستانبول بين الدولة العثمانية وألمانيا .","s":"عقدت الدولة العثمانية معاهدةَ إستانبول مع ألمانيا، اعترف الألمان بموجِبها بالفتوحات التركية في أوروبا، وقرَّرت المعاهدة أن يدفعَ الألمان ضريبةً سنوية للعثمانيين، وألَّا تُستعمل صفة إمبراطور في المكاتبات الرسمية مع الدولة العثمانية."},{"id":3708,"era":"c10","t":"الدولة العثمانية تعقد صلحًا مع النمسا .","s":"وقَّعت الدولة العثمانية معاهدةَ صلحٍ في عهد السلطان سليمان القانوني مع النمسا، بقيادة ملكها فردينالد، واتَّفق الطرفان على هدنة خمس سنوات، شريطة أن يدفع ملك النمسا جزيةً سنوية مقدارها ثلاثون ألف دوكا."},{"id":3709,"era":"c10","t":"العثمانيون يضمون أراضي للصفويين ويدخلون تبريز للمرة الثالثة .","s":"جاء إلى إستانبول أخو الشاه الصفوي يشكو ظلمَ أخيه له ويستنجِدُ بالخليفة سليمان القانوني، فسار الخليفةُ بجيش إلى تبريز عاصمةِ الصفويين منتزعًا كلَّ الأراضي الواقعة شمال شرقي نهر دجلة حتى بحيرة وان، ويدخل تبريز للمرة الثالثة ويفتح قلعة وان."},{"id":3710,"era":"c10","t":"استيلاء السلطان محمد الشيخ السعدي على مكناسة  .","s":"لما استولى السلطان أبو عبد الله محمد الشيخ على مراكش وصَفَت له أعمالها، طَمِحت نفسُه للاستيلاء على بقيةِ بلاد المغرب وأمصاره، وقَطْعِ الوطاسيين من سائر أقطاره، فجمع الجموعَ وتقدَّم بها إلى أعمال فاس، وكان أوَّلُ ما ملك منها مكناسة الزيتون؛ فإنه افتتحها بعد حصارٍ وقتال كبير."},{"id":3711,"era":"c10","t":"استيلاء السلطان محمد الشيخ السعدي على مدينة فاس .","s":"لما غلب السلطانُ محمد الشيخ السعدي على أخيه أبي العباس أحمد الأعرج، واستولى على مراكش، طَمِحَت نفسه للتوغل في بلاد المغرب وقراه، فتفرغ لحرب بني وطاس ونكَثَ ما كان بينه وبينهم من الصلح، وردَّد إليهم البعوث والسرايا وأكثَرَ فيهم من شَنِّ الغارات، وصار يستلبُهم البلادَ شيئًا فشيئًا إلى أن استولى عليها، وكان أولُ ما ملك من أمصار المغرب مكناسة الزيتون افتتحها العام الماضي, ثم تقدَّم إلى فاس فألح عليها "},{"id":3712,"era":"c10","t":"استعادة العثمانيين ترانسلفانيا .","s":"تنازلت إيزابيلا أرملة زابولي عن ترانسلفانيا إلى فرديناند الأمير النمساوي مخالِفةً بذلك شروطَ الهدنة الموقَّعة مع العثمانيين والنمساويين، فأرسل الخليفةُ العثماني سليمانُ القانوني جيوشَه التي استطاعت أن تُعيدَ ترانسلفانيا بعد مقاومةٍ مِن قِبَل النمساويين."},{"id":3713,"era":"c10","t":"هدم دار الندوة بمكة .","s":"لما تسلَّم الأمير كلدي أمير إمارة مكَّة، هدم دارَ الندوة في هذا العام, وبني مقامًا مُربَّعًا داخِلَ الحرم ذا طبقتين: الأولى للإمام والمُصلِّين، والثانية للمؤذِّنين والمبلِّغين."},{"id":3714,"era":"c10","t":"الغزو الإسباني على تونس .","s":"قام الأسطول الإسباني بغزو المهدية وطَوَّق أسوارَها من البحر، وأنزل الإسبان قواتِهم إلى البر، فسارع الوالي العثماني طورغوت حاكِمُ جزيرة جربة بإرسال أسطولٍ لنجدة الحامية العثمانية بالمهدية، فقامت معركةٌ بين الأسطولين أسفرت عن هزيمةِ طوغورت وتراجُعِه، فاستولى الإسبان على المهدية، وقتلوا عددًا كبيرًا من المدافعين عنها وأسَرُوا الرجال النساء."},{"id":3715,"era":"c10","t":"استيلاء السلطان محمد الشيخ السعدي على تلمسان .","s":"لما فتح أبو عبد الله محمد الشيخ السعدي حضرة فاس، تاقت نفسُه إلى الاستيلاء على المغرب الأوسط، وكان يعزُّ عليه استيلاء الترك العثمانيين عليه، مع أنهم أجانبُ عن هذا الإقليم ودُخَلاء فيه، فيَقبُحُ بأهلِه وملوكه أن يتركوهم يغلبون على بلادِهم، لا سيما وقد فرَّ إليهم عدوٌّ من أعدائه، وهو أبو حسون الوطاسي، فرأى محمد الشيخ من الرأي وإظهار القوة في الحربِ أن يبدأَهم قبل أن يبدؤوه، فنهض من فاس قاصدًا تلمسان "},{"id":3716,"era":"c10","t":"العثمانيون يضمون ليبيا لحكمهم ويطردون فرسان القديس يوحنا .","s":"كان العثمانيون وقائِدُهم خير الدين بربروسا وحسن الطوشي قد انشغلوا بمحاربة الأسبان في الجزائر والمغرب فترةً طويلةً من الوقت، جَعَلت فرسان القديس يوحنا (وهم بقايا الإسبتارية الصليبيين المطرودين من فلسطين ثم من قبرص ورودس سنة 928) يسيطرون على طرابلس سنة 942 بعد خروجهم من رودس بأمر البابا, واستمرَّ الحالُ حتى وفاة خير الدين بربروسا، وتمَّ تعيينُ طرغود أو «طرغوت، أو طرغول» باشا في منصب قبطان الأساطيل ا"},{"id":3717,"era":"c10","t":"استيلاء العثمانيين على جزيرة مالطة  .","s":"استولى الأسطول العثماني على جزيرة مالطة، وقام بتخريبها، وكانت مالطة من القواعدِ العسكريةِ البحريةِ المزعجة للمسلمين في البحر المتوسط؛ حيث ضمَّت عددًا من الفرسان الصليبيين المتعصِّبين ضِدَّ الإسلام."},{"id":3718,"era":"c10","t":"تجديد المعاهدة بين العثمانيين والفرنسيين والإغارة على صقيلية .","s":"لما هلك ملك فرنسا فرانسوا الأول خلفَه ابنه هنري الثاني الذي جدَّد المعاهدة مع العثمانيين في هذا العام, ثم أغار الطرفان على صقلية وجنوبي إيطاليا، وفتحت أساطيلُهما جزيرة كورسيكا، ثم اختلف قائدا الأسطولين فتركا الجزيرة وعاد كلٌّ منهما إلى بلده."},{"id":3719,"era":"c10","t":"محاولات العثمانيين استرجاع هرمز من البرتغاليين .","s":"بعد أن فشِلت محاولة محيي الدين بيري استرجاعَ هرمز من البرتغاليين، أعاد السلطان سليمان القانوني إرسالَ حملة بحرية أخرى بقيادة مراد رئيسي، وهو من مشاهير أمراءِ البحريَّة العثمانية، ولما وصل إلى هرمز وجد أسطولًا هائلًا من البرتغاليين، فدارت بينهما معركة عنيفةٌ تكبد فيها العثمانيون خسائرَ فادحةً جدًّا، فعاد إلى البصرة، ثم جهَّز السلطان حملةً أخرى بقيادة علي جلبي الذي قاتل البرتغاليين في معركة بالقربِ "},{"id":3720,"era":"c10","t":"وفاة عالم الجغرافيا والبحار أحمد محيي الدين الريس العثماني .","s":"هو عالمُ الجغرافيا والبِحار العثماني أحمد محيي الدين الريس (بيري ريس بالتركية) ولِدَ سنة 871, في مدينة غاليبولي غرب إسطنبول، على الجانب الأوروبي من بحر مرمرة، وكانت هذه المدينة بمثابة المركز الرئيسي للقوات البحرية العثمانية, وهو أبرز القادةِ البحريين في الأسطول العثماني وراسِمُ الخرائط. في الوقت الذي استطاع البحَّارة العثمانيون آنذاك أن يصلوا إلى المحيط الأطلسي ويبلغوا بحر الهند، ورسموا خرائِطَ ال"},{"id":3721,"era":"c10","t":"توقيع الدولة العثمانية معاهدة إستانبول مع فرنسا .","s":"اعترف ملك فرنسا هنري الثاني في معاهدة إستانبول بالسلطان العثماني كإمبراطور أوروبا الأوحد، ووضع الأسطولَ الفرنسيَّ رهْنَ الدولة العثمانية في مقابِلِ تقديم تركيا مساعداتٍ بحريةً لفرنسا، وأن تترك فرنسا أسطولها لتركيا في حالة عدمِ تسديدها مصاريفَ الحملة البحرية العثمانية."},{"id":3722,"era":"c10","t":"استيلاء العثمانيين على جزيرة كوريكا ومدينة كاتانيا في صقلية .","s":"استولى القائدُ البحري العثماني طرغد بك على جزيرة كوريكا ومدينة كاتانيا في صقلية بعد إبادتِه لحاميتها، وتخليصِه لسبعة آلاف أسيرٍ مسلم، ثم قام بتسليم كوريكا للفرنسيين الذين لم يستطيعوا الاحتفاظَ بها طويلًا أمام الإسبان الذين سيطروا عليها في نفس العامِ!"},{"id":3723,"era":"c10","t":"قيام دولة السعديين بالمغرب الأقصى .","s":"بعد أن استولى السعديون على فاس سنة 956هـ ثم قام العثمانيون بطردهم وإعادة الوطاسيين، ثم ترك العثمانيون فاس وعادوا إلى الجزائر؛ واجه أبو حسون منافسةَ محمد الشيخ السعدي الذي جمع قواتٍ من السوس والحوز وأتى بجنوده إلى أن وصل رأس الماء من أحواز فاس، وكان أبو حسون بعد انسحاب العثمانيين قد أخذ في إعداد الجيوشِ وآلات الحرب إلى أن قضت ثمانية شهور، فأمر بالخروج لمواجهة محمد الشيخ السعدي والوصول إلى مراكش، ول"},{"id":3724,"era":"c10","t":"وفاة الأمير الشريف أحمد بن أبي نمي  .","s":"هو الأميرُ الشريف أحمد بن أبي نمي محمد الثاني بن بركات الثاني شريف حسني جدِّ آل منديل وآل حراز، وهو صاحِبُ مكة، وكان هو الذي دعس بساطَ السلطان سليمان القانوني ولم يدعَسْه غيره من أمراء مكَّة، أرسله أبوه إليه سنة 945 واجتمع به، ولما عاد إلى مكة توفِّيَ بها في حياة أبيه، ولم يلِ الإمارةَ استقلالًا, وكانت شوكتُه قد استقرَّت في حياة أبيه."},{"id":3725,"era":"c10","t":"قيام الدولة الثانية للسلطان أبي حسون الوطاسي .","s":"لما دخل السلطان أبو عبد الله محمد الشيخ السعدي إلى فاس سنة 956 وقبض على بني وطاس بها، فرَّ أبو حسون- أخو السلطان أبي العباس أحمد الوطاسي- إلى ثغر الجزائر حقنًا لدمه ومستعينًا بالعثمانيين على السعدي، وكان العثمانيون قد استولوا على المغرب الأوسط وانتزعوه من يد بني زيان، فلم يزل أبو حسون عندهم يفتلُ لهم في الغارات والسنام ويحسِّنُ لهم بلاد المغرب الأقصى ويعظِّمُها في أعينهم ويقول: \"إن المتغلِّبَ عليه"},{"id":3726,"era":"c10","t":"نشوب حرب بحرية بين الأسطولين العثماني والبرتغالي .","s":"نشبت حربٌ بحرية طاحنة بين الأسطولين العثماني والبرتغالي في مضيق هرمز بالخليج العربي, واستمرت الحرب 18 ساعة بدون توقُّف، ولم تؤدِّ إلى نصرٍ حاسمٍ لأحد الفريقين."},{"id":3727,"era":"c10","t":"استيلاء السلطان محمد الشيخ السعدي على مدينة فاس .","s":"لما فرَّ السلطان محمد الشيخ السعدي من وقعة الأتراك بفاس وصل إلى مراكش، فاستقَرَّ بها وصرف عزمَه لقتال أبي حسون، فأخذ في استنفار القبائل وانتخاب الأبطال وتعبئة العساكر والأجناد، فاجتمع له من ذلك ما اشتدَّ به أزْرُه وقويَ به عَضدُه، ثم نهض بهم إلى فاس، فخرج إليه السلطان أبو حسون في رُماة فاس وما انضاف إليهم من جيش العرب، فكانت الهزيمة على أبي حسون فرجع إلى فاس وتحصَّن بها، فتقدم الشيخ السعدي وحاصره "},{"id":3728,"era":"c10","t":"معاهدة بين السعديين بالمغرب الأقصى والبرتغاليين .","s":"بعد عودة فاس للسعديين ظهر السلطان محمد الشيخ السعدي كخصم عنيد للعثمانيين، ومن المعارضين لسياستهم التوسعيَّةِ في بلاد المغرب، بل والأكثر من ذلك أنه أعلن إثرَ دخوله فاس بأنه عازمٌ على الذهاب إلى الجزائر لمنازلة العثمانيين هناك، فهذا التنافسُ السعديُّ العثماني على شمال إفريقيا، بل وعلى الخلافةِ الإسلامية كان في صالحِ الإسبان والبرتغال، ولا عجب إذا رأينا بعد ذلك تقاربًا بين هؤلاء جميعًا ضد العثمانيين "},{"id":3729,"era":"c10","t":"معاهدة أماسيا بين العثمانيين والصفويين .","s":"عُقِدت معاهدة أماسيا بين الخليفة سليمان القانوني والدولة الصفوية بإيران؛ لتثبيت الحدود بين الدولتين، بموجِبِها ضُمَّت كل الأراضي الواقعة شمالَ شرق نهر دجلة حتى بحيرة وان إلى الدولة العثمانية كما استقرت عام 955، وبموجِب هذه المعاهدة تخلى الصفويون عن حقوقِهم بالعراق، واعتَرَفوا بها على أنَّها جزءٌ من الدولة العثمانية."},{"id":3730,"era":"c10","t":"العثمانيون يسيطرون على المغرب الأقصى .","s":"نتيجةً لتحالف السعديين مع الإسبان والبرتغال ضِدَّ العثمانيين تحَّركت القوات العثمانية تحت قيادةِ صالح رايس والي الجزائر من قِبَل العثمانيين للوقوف مع أبي حسون الوطاسي وحصلت اصطدامات عسكرية بين قوات محمد الشيخ السعدي والقوات العثمانية قرب بادس التي رسا بها الأسطول العثماني، فلحقت الهزيمة بالقوات السعدية؛ مما أفسح المجالَ أمام العثمانيين لكي يواصلوا زحفهم نحو الداخل، وفي هذا العام سقطت مدينة تازة في"},{"id":3731,"era":"c10","t":"انتزاع بجاية من يد الإسبان .","s":"لم يكن صالح رايس والي الجزائر يهتمُّ قبل كلِّ شيء إلا بمحاربة الإسبان، ولا يهدفُ من وراء أي عملٍ إلَّا جمعَ القوى الإسلامية من أجلِ تطهير البلاد من الوجودِ الأوروبي الصليبي، فكان يرى قبل كل شيءٍ وجوبَ طردِ الإسبانِ مِن وهران، لكن كيف يتسنَّى له ذلك وسلطانُ السعديين بالمغرب يترقَّبُ به الفُرَص، وسلطانُ قلعة بني عباس ببلاد مجانة يُعلنُ انفصاله واستقلاله، ترامت لصالح رايس يومئذٍ الأنباءُ عن ضعفِ القو"},{"id":3732,"era":"c10","t":"محاولة العثمانيين انتزاع وهران من سيطرة الإسبان .","s":"أُطلِعَ صالح رايس- والي الجزائر من قِبَل العثمانيين- على تلك المؤامرةِ التي كانت تُحاك ضِدَّ الدولة العثمانية بين ملكِ المغرب السلطانِ الشيخ المهدي أبي عبد الله محمد السعدي والإسبان، والتي كان هدفُها طردَ العثمانيين من الجزائر؛ لأنَّه طالما أن الدولة في الجزائر معناه خطرٌ على إسبانيا، فبعث صالح رايس للباب العالي يخبرُه بشأن تلك المحادثات، فكان جوابُ السلطان سليمان سريعًا وحاسمًا بوجوبِ مهاجمة وهرا"},{"id":3733,"era":"c10","t":"وفاة القائد أمير البحر صالح رايس .","s":"هو القائدُ أمير البحر صالح رايس، ويقال (ريس)، قائدُ البحرية العثمانية في البحر المتوسط, وهو عربيٌّ من الإسكندرية، ولد فيها سنة 893 تعرَّف على الأتراك حين قدِموا إلى مصر، ورافق أميرَ البحار خير الدين بربروسا في رَحَلاته البحرية, ومن أهمِّ أعمال رايس أنَّه ساهم في إنقاذ بقايا المسلمين في الأندلس، وقد تولى منصِبَ حاكم الجزائر عام 1552م. كان صالح رايس يهتم كثيرًا بمحاربة الإسبان، ويهدف من ورائه جمعَ ق"},{"id":3734,"era":"c10","t":"وفاة السلطان الشيخ المهدي محمد بن محمد السعدي .","s":"هو محمد بن محمد بن محمد بن عبد الرحمن بن زيدان الحسني، أبو عبد الله، المعروف بالشيخ، والملقب بالسلطان المهدي: ثالثُ سلاطين الدولة السعدية بالسوس ومراكش. ولِدَ سنة 896. كان مع أبيه القائمِ بأمر الله في بدء ظهورِه، ثم كان مع أخيه أحمد الأعرج، وكانت كلمتُهما واحدة مدة 23 عامًا، ثم افترقت كلمتُهما، فقام محمد بخلع أخيه أحمد والقبض عليه وعلى أولاده سنة 946، واجتمعت الكلمة عليه، فباشر الجهادَ في الثغور، "},{"id":3735,"era":"c10","t":"وقوع وباء عظيم بالمغرب .","s":"كسا هذا الوباءُ سهلَ المغرب وجبالَه، وأفنى كُماتَه وأبطالَه، واستمَرَّ وجوده إلى سنة ست وستين بعدها."},{"id":3736,"era":"c10","t":"مبايعة أهل فاس ومراكش للسلطان عبد الله السعدي .","s":"تولَّى السلطانُ الغالب بالله الحُكمَ، وذلك بعد مقتل أبيه ومبايعةِ أهل فاس له وأهلِ مراكش، فاستوثق له الأمرُ وتمهَّد له ملك أبيه. وكان قد نشأ في عفافٍ وصيانة، وحَفِظَ القرآن وأخذ بطرفٍ صالحٍ من العلم، وكان وليَّ عهد أبيه، وكان يلقَّب من الألقاب السلطانية بالغالب بالله، لقَّبَه به غيرُ واحد من الأئمةِ."},{"id":3737,"era":"c10","t":"هزيمة حسن بن خير الدين التركي من السلطان الغالب بالله .","s":"لَمَّا ولِيَ السلطان أبو محمد عبد الله الغالب بالله الخلافةَ، اشتغل بتأسيس ما بيده وتحصينِه بالعَدَد والعُدَّة، ولم تطمح نفسه إلى الزيادة على ما ملك أبوه من قَبلِه. وغزاه حسن بن خير الدين باشا التركي صاحبُ تلمسان في جيشٍ كثيفٍ من الأتراك، فخرج إليه السلطان الغالب بالله فالتقيا بمقربةٍ من وادي اللبن من عمالة فاس، فكانت الدائرة على حَسنٍ، فرجع منهزمًا يطلب صياصيَ الجبال إلى أن بلغ إلى باديس، وكانت ي"},{"id":3738,"era":"c10","t":"معركة مستغانم بين العثمانيين والإسبان  .","s":"حقَّق القائد العثماني الشهير حسن باشا بن بربروسا انتصارًا كبيرًا على النصارى الإسبان في معركة \"مستغانم\" بالجزائر؛ حيث قُتل في هذه المعركة 12 ألفًا من الإسبان، وتشتهرُ هذه المعركة في التاريخ بأنَّه لم يبقَ فيها جندي إسباني على قيدِ الحياة، حيث تمَّ إفناءُ الجيش الإسباني عن بَكرة أبيه. وكان سببُها أن حاكم وهران دو الكوديت كان يدركُ أنَّ استرجاع العثمانيين لتلمسان يهدِّدُ الوجود الإسباني تهديدًا خطير"},{"id":3739,"era":"c10","t":"نشوب حرب قونية الميدانية .","s":"نشبت حرب قونيَّة الميدانية بين السلطان سليمان القانوني وأخيه بايزيد حولَ أمور متعلِّقة بولاية العهدِ في الدولة العثمانية، وقد هُزِمَ بايزيد وهَرَب إلى الدولة الصفويَّة المعادية للعثمانيين، إلَّا أن الصفويين ما لبثوا أن قتلوه بناءً على طلبٍ مِن سليمان القانوني."},{"id":3740,"era":"c10","t":"استيلاء الإسبان على جزيرة جربة .","s":"استولى الأسطول الإسباني الضخم المكوَّن من 200 سفينة و30 ألف جندي، على جزيرة جربة التونسية وقلعتِها، بعد انسحاب الحاميةِ العثمانية منها، والتي تقدَّر بألف رجل."},{"id":3741,"era":"c10","t":"انتصار الأسطول العثماني على الأسطول الإسباني في معركة جربا .","s":"انتصر الأسطولُ العثماني بقيادة طرغد باشا على الأسطول الإسباني الصليبي في معركة \"جربا\" قرب تونس، في واحدة من كبرى المعارك البحرية في التاريخ العالمي في تلك الفترة، وقُتِلَ أكثرُ من ثلثي بحَّارة الأسطول الإسباني، في حين لم يسقُط من العثمانيين سوى ألف."},{"id":3742,"era":"c10","t":"حرب بحرية بين أسطول العثمانيين وأساطيل أوروبية .","s":"أمير البحر العثماني طورغوت يستولي على جزيرة جربة بعد معركةٍ جرت قبلها في شهر رمضان من هذا العام، هزمت فيها أساطيل جنوة وفلورنسا وصقلية ومالطة وإسبانيا، وتوغَّل طوغورت بعد ذلك في الداخل، فاستولى على مدُنِ قفصة وصفاقس والموناستير والقيروان وسوسة، وكان الأعرابُ الشابية قد استولوا عليها فحرَّرها منهم وانتقلت إلى الدولة العثمانية."},{"id":3743,"era":"c10","t":"استيلاء القائد العثماني طرغد باشا على قلعة جربا في تونس .","s":"كانت هذه القلعة سابقًا خاضعة للإسبان، واستولى العثمانيون عليها بعد حصار دام 63 يومًا، وقد أطلقوا فيها نحو 12 ألف طلقة مدفعٍ على القلعة، وقُتل من الإسبان 8800 جندي، ومن العثمانيين ألف."},{"id":3744,"era":"c10","t":"وفاة طاش كبري زاده .","s":"أحمد بن مصطفى بن خليل المعروف بطاش كبري زاده، من مشاهير الموسوعيين الأتراك وكُتَّاب السِّيَر، ولد في بروصا  عام 901هـ ثم انتقل إلى أنقرة ثم إستانبول، قرأ الفقه والنحو والصرف، وتولى قضاءَ حلب، ويعتبَرُ من المصنِّفين في الموسوعات، فكتابه: مفتاح السعادة ومصباح السيادة، يعتبر ذخيرةً للتعريف بكثيرٍ من العلوم، وله كتابٌ في السير هو: الشقائق النعمانية فيه سيرة شيوخ الطرق، وله العقدُ المنظوم في ذكر أفاضل "},{"id":3745,"era":"c10","t":"وفاة القائد البحري الإسباني دوريا .","s":"توفِّيَ القائد البحري الإسباني الشهير \"أندريا دوريا\"، كان قد خاض العديدَ من المعارك ضِدَّ المسلمين العثمانيين، وكان النصرُ فيها سِجالًا، وتوفِّيَ بعد انتصار العثمانيين في معركة \"جربا\" البحرية."},{"id":3746,"era":"c10","t":"وفاة الأمير بايزيد ابن السلطان سليمان القانوني  .","s":"هو الأمير بايزيد (بالتركية شاهزاده بايزيد) بن سليمان بن سليم الأول بن بايزيد الثاني بن محمد الفاتح, هو الابنُ الرابع من أبناء سليمان القانوني، والابن الثالث من زوجته الثانية روكسلان. قاد جيشًا متمردًا على الدولة اعتراضًا على ولاية العهد لأخيه سليم الثاني الذي يصغُرُه بسنة ونصف، فهُزم في معركة قونية الميدان سنة 966, فاضطرَّ بايزيد أن يلجأ لإيران عند شاه, ولكن بموجب المعاهدة بين الطرفين قام الشاه طه"},{"id":3747,"era":"c10","t":"السلطان العثماني سليمان القانوني وولاية العهد .","s":"كان القانوني قد قتل سابقًا ابنه مصطفى بدسيسة من زوجته روكسلانا الروسية؛ ليتولى ابنُها سليم الخلافة، بل سعت أيضًا لقتل ابن مصطفى الذي لا يزال رضيعًا، وعَهِدَ بالخلافةِ لابنه سليم دون الأكبر بايزيد الذي ثار على أبيه، فأرسل إليه جيشًا فهزمه، فاضطر بايزيد للُّجوء إلى بلاد فارس عند الصفويين، فلما استردَّه سليمان القانوني ثم قتله، صفت ولاية العهد لسليم بن سليمان."},{"id":3748,"era":"c10","t":"فتح السعديين مدينة شفشاون بالمغرب وانقراض أمر بني راشد منها .","s":"لما توفِّيَ الأمير أبو الحسن علي بن موسى بن راشد مختطُّ مدينة شفشاون في شمال المغرب، وبقِيَت بيد أولاده يتولَّون رياستها ولم يزالوا فيها بين سِلمٍ وحرب إلى أن حاصرهم بها الوزير أبو عبد الله محمد بن عبد القادر ابن السلطان محمد الشيخ السعدي بجيوشِ عَمِّه السلطان أبي محمد عبد الله الغالب بالله، وصاحب شفشاون يومئذ الأمير الفاضل أبو عبد الله محمد ابن الأمير أبي الحسن علي بن موسى بن راشد، فلمَّا اشتَدَّ"},{"id":3749,"era":"c10","t":"حدوث سيل عظيم هائل بحضرموت (سيل الإكليل)  .","s":"حدث سيلٌ عظيم هائل بحضرموت لم يُسمَع بمثله، أتلف كثيرًا من النخيل, وأهلُ تلك الجهة يذكرونه، ويؤرِّخون به، وهو المسمى عندهم (سيل الإكليل) ويقال إنه وقع في قديم الزمان سيلٌ مثلُه أو قريبٌ منه."},{"id":3750,"era":"c10","t":"محاولة الإسبان احتلال جزيرة باديس .","s":"بدأ فيليب الثاني يستعدُّ لاحتلال جزيرة باديس، وشجَّعه على ذلك النصرُ الذي حقَّقه في وهران، فوجَّه لذلك أسطولًا في هذه السَّنة, فقاومه المجاهدون مقاومةً عنيفةً، واضطرَّ الأسطول إلى التراجع, والجديرُ بالذكر أنَّ جزيرة باديس كانت أقربَ نقطة مغربية إلى جبل طارق، وأنَّها كانت بالنسبة للمجاهدين ميناءً هامًّا؛ إذ يمكِنُهم من خلالها العبور للأندلس، كما يمكِنُهم التسلل لداخل الأراضي الإسبانية؛ لتقديم المسا"},{"id":3751,"era":"c10","t":"محاولة استرجاع وهران من الإسبان .","s":"خرج حسن بن خير الدين بربروسا في هذه السنة من مدينة الجزائر نحو الغرب، يقودُ جيشًا كبيرًا مؤلفًا من خمسة عشر ألف رجل من رماة البندقية، وألف فارس من الصباحية، تحت إمرة أحمد مقرن الزواوي، واثني عشر ألف رجل من زواوة وبني عباس، أما مؤَنُ وذخيرة الجيش فقد حملها الأسطولُ العثماني إلى مدينة مستغانم التي اتخذَها قاعدة للعمليات، وفي 13 أبريل وصل حسن خير الدين بكامل قوَّته أمام مدينة وهران، وضرب حصارًا حولها"},{"id":3752,"era":"c10","t":"وفاة أمير البحر طرغد باشا العثماني  .","s":"هو القائد أمير البحر طرغد باشا العثماني، يسمى عند النصارى درغوث، وعند العرب طرغول. من أشهر قادة البحر العثمانيين، خلَفَ خيرَ الدين في قيادة الأسطول العثماني في شمال إفريقيا، ولِدَ طرغد عام 1485م، في قرية تابعة للواء منتشة موغلة. التحق بالبحرية العثمانية كجنديٍّ بحري عاديٍّ في سن مبكرة جدًّا، ثم اندفع في شبابه إلى حياة البحر بدافع حب المغامرات، فاشتغل كملَّاح بسيط ثم مِدفَعي، ثم ذاع صيتُه، وأظهر تف"},{"id":3753,"era":"c10","t":"وفاة شيخ الإسلام شهاب الدين ابن حجر الهيتمي .","s":"هو شيخ الإسلام شهاب الدين أبو العباس أحمد بن محمد بن علي بن حجر الهيتمي السعدي الأنصاري، ولد سنة 909 في محلة أبي الهيتم في إقليم الغربية بمصر، وإليه نسبته, ويقال هي محلة ابن الهيثم بالمثلثة فغيَّرتها العامة، تلقى علومَه بالأزهر فبلغ فيها مرتبة شيخ الإسلام عندهم، كان فقيهًا على الشافعي مذهبًا، الأشعريِّ عقيدةً، والمتصوف مسلكًا, وتعتبر ترجيحاته في المذهب معتبرة، وأقواله في المذهب معتبرة، بل يعتبرونه"},{"id":3754,"era":"c10","t":"وفاة الصوفي عبد الوهاب بن ذوقا الشعراني صاحب الطبقات .","s":"هو أبو المواهب عبد الوهاب بن أحمد بن علي الحنفي، نسبة إلى محمد بن الحنفية، ولِدَ في قلقشندة بمصر، ونشأ في ساقية أبي شعرة، وينسب الشعراني إلى قرية أبي شعرة المصري الشافعي الصوفي، والشعراني صوفي شاذلي أسَّس الطريقة الشعراوية، وكان معظمُ نشاطه في التصوف، اشتهر بتفاخره؛ حيث كان يدَّعي الاتصالَ بالله والملائكة والرسل، وأنه قادر على الإتيان بالمعجزات والتعرف على أسرار العالم!! له تصانيف أشهرُها طبقاته ا"},{"id":3755,"era":"c10","t":"محاولة العثمانيين فتح جزيرة مالطة .","s":"كان السلطان العثماني سليمان القانوني عازمًا على فتح جزيرة مالطة التي كانت أكبر مَعقِل للنصارى الأوروبيين في وسط البحر المتوسط، والتي سبق أن استقَرَّ فيها فرسان القديس يوحنا، فأرسل السلطانُ العثماني أسطولًا آخر بقيادة بيالي باشا نفسه، كما طلب من درغوث رايس حاكمِ طرابلس وجربة، وحسن خير الدين أن يتوجَّها على رأس أسطوليهما الإسلاميين للمشاركة في عملية مالطة وإخضاعها؛ استعدادًا لمنازلة بقية المعاقل الإ"},{"id":3756,"era":"c10","t":"وفاة السلطان سليمان القانوني وتولي ابنه سليم الثاني الخلافة .","s":"هو السلطان سليمان بن سليم الأول بن بايزيد الثاني بن محمد الفاتح بن مراد الثاني، عاشر سلاطين بني عثمان، وثاني من حمل لقب أمير المؤمنين، ولد في غرة شعبان سنة 900هـ في طرابزون, وهو من أشهر سلاطين آل عثمان؛ حيث تميَّز عصره بالقوة والنفوذ، كان الغرب يلقِّبه بسليمان العظيم، وفي الشرق يلقب بسليمان القانوني, وبلغت الدولة العثمانية في مدته أعلى درجات الكمال. وكانت باكورةُ أعماله بعد توزيع النقود على الانكش"},{"id":3757,"era":"c10","t":"صلح العثمانيين مع النمسا .","s":"بعد أن تسَلَّم سليم الثاني زمامَ الخلافة العثمانية بدأ الضعفُ يدبُّ فيها، إلا أنه لم يظهر الضعف عليه بسبب قوة وزيره محمد الصقلي، وفي هذه السنة عقدت الدولة العثمانية معاهدةَ صلح مع النمسا، اعترفت فيه بأملاك النمسا في المجر على أن تدفع النمسا مقابل ذلك الجزية السنوية المقرَّرة للدولة العثمانية، واعتراف النمسا أيضًا بتبعية أمراء ترانسلفانيا والأفلاق والبغدان للدولة العثمانية."},{"id":3758,"era":"c10","t":"ثورة مسلمي غرناطة الموريسكيون .","s":"ثار المسلمون في ليلة عيد ميلاد النصارى على الإسبان، واعتصموا في جبال البشرات لصدور أوامر ملكية تحرم عليهم التحدث بالعربية، وتمنعهم من ممارسة عبادتهم وتقاليدهم، وكانت هذه الثورة بقيادة محمد بن أمية، يُذكَر أن السلطان السعدي الغالب بالله بذل الوعود المعسولة لرسل الثوَّار البورشارات، ووعدهم بالنصر وتقديم كل ما يحتاجونه من عتاد وسلاح ورجال، لكن استمرَّ الغالب بالله محافظًا على روابطه الوديَّة مع فيليب"},{"id":3759,"era":"c10","t":"مزيد من اضطهاد الموريسكيين في غرناطة .","s":"بعد أن قُمِعت ثورة الموريسكيين في غرناطة وانتهت، أصدر الملك الإسباني فيليب الثاني مرسومًا بطرد الأندلسيين الموريسكيين من مملكة غرناطة، وتوزيعهم في الأقاليم الأندلسية بعد مصادرة أملاكهم، وإجبارهم على التنصر، وإحالة من يأبى على محاكم التفتيش."},{"id":3760,"era":"c10","t":"إخضاع ثورة الزيدية والإسماعيلية ضد العثمانيين في اليمن .","s":"انتفض زعماءُ اليمن من الزيدية والإسماعيلية على الحُكم العثماني، وطردوا الحامية العثمانية عام 975، فقاد سنان باشا جيشًا استولى على عدن، ثم في هذه السنة عُقِدت اتفاقية بين الدولة العثمانية وبين الأئمة الزيدية، اعترف الزيديةُ بموجِبها بالسيادة العثمانية، ومرابطة القوات العثمانية في جميع القطاعات والمدن التي كانت ترابِطُ فيها قبل اندلاع الانتفاضة، واعترفت الدولة العثمانية بالإمام المطهَّر بن شرف الدين"},{"id":3761,"era":"c10","t":"استيلاء علي باشا صاحب الجزائر على تونس .","s":"عندما غزا علي باشا- صاحِبُ الجزائر- تونسَ في هذه السنة، واستولى عليها وطرد منها حاكمها أحمد بن الحسن بن محمد الحفصي- ذهب أحمد إلى طاغية قشتالة مستغيثًا به، شأنُه شأن أبيه من قَبلِه، فأمَدَّه الطاغية بأسطول عظيم واشترط عليه أداء مال فالتزمه، ولما وصل الأسطول إلى ظاهر تونس اطَّلع قائده السلطان أحمد الحفصي على كتاب من الطاغية مضمونُه المشاركة في الحُكم، فأنكر أحمد ذلك وأنِفَ منه وذهب إلى صقلية فبقي ب"},{"id":3762,"era":"c10","t":"وفاة السلطان بدر أبي طويرق الكثيري سلطان حضرموت .","s":"هو السلطان بدر بن عبد الله بن جعفر، أبو طويرق الكثيري سلطان حضرموت. ولد سنة 902 في مدينة سيؤون وتولى سلطنتها وتوفي فيها، تولاها صغيرًا بعد وفاة أبيه. نشأ موفَّقًا في سياسته، طيب السيرة، وافر العقل، جوادًا، يعتبر أوَّلَ من عمل لتوحيد مناطق حضرموت؛ حيث شملت أراضي سلطنته حضرموتَ من أبْينَ ومأرب غربًا إلى ظفار شرقًا, ثم استعان بالترك، وكاتَبَ السلطان سليمان القانوني، فجاءته سنة 926 قوةٌ منهم، أضاف إلي"},{"id":3763,"era":"c10","t":"صدور المرسوم الثاني بترحيل جميع سكان غرناطة المسلمين .","s":"أعلن الكاردينال \"خيمينيث\" أن المعاهدة التي تم توقيعُها مع حكام غرناطة قبل مائة سنة والتي عقدت عام 879 لم تعُدْ صالحة أو موجودة، وأعطى أوامرَه بتنصير جميع المسلمين في غرناطة دون الأخذ برأيهم، أو حتى تتاح لهم فرصةُ التعرف إلى الدين الجديد الذي يساقون إليه، ومن يرفُض منهم عليه أن يختار أحد أمرين: 1- إما أن يغادر غرناطة إلى إفريقيا دون أن يحمل معه أي شيء من أمواله، ودون راحلةٍ يركبها هو أو أحد أفراد أ"},{"id":3764,"era":"c10","t":"فتح العثمانيين جزيرة قبرص للمرة الثالثة .","s":"كانت إيطاليا وإسبانيا تقدران أهمية جزيرة قبرص، وشاع في أوروبا تكوُّنُ حِلف ضِدَّ السلطان، ولكن لم يُعمَلْ شَيءٌ في حينه لإنقاذ قبرص من العثمانيين الذين نزلوها بقوة كاسحة، نفذت إلى الجزيرة بدون صعوبة، ووقفت مدينة فامرجستا الحصينة أمام العثمانيين بقيادة باحليون وبراجادنيو الذين واجهوا القوة العثمانية التي بلغ عددُ مقاتليها مائة ألف, واستعمل خلالها العثمانيون جميعَ وسائل الحصار المعروفة، مِن فَرٍّ وك"},{"id":3765,"era":"c10","t":"الأساطيل الأوروبية تهزم الأسطول العثماني في موقعة ليبانتو .","s":"ارتعدت فرائِصُ الأمم الأوروبية النصرانيةِ من الخطر الإسلاميِّ العظيم الذي هدَّد القارة الأوروبية؛ من جرَّاءِ تدفُّق الجيوش العثمانية برًّا وبحرًا, وعندما احتلَّ الأسطول العثماني بقيادة علي باشا قبرص بقرارٍ من السلطان سليم الثاني, أخذ البابا بيوس الخامس يسعى من جديدٍ لجمع شمل البلاد الأوروبية المختلفة، وتوحيد قواها برًّا وبحرًا في تحالف صليبي تحت راية البابوية، اختير لقيادة قوة هذا التحالف (دون خوا"},{"id":3766,"era":"c10","t":"وفاة القائد البحري العثماني حسن باشا بن خير الدين بربروسا .","s":"هو القائد البحري العثماني حسن باشا ابن القائد البحري الشهير خير الدين بربروسا، وُلد سنة 925, ويعدُّ من القادة المعدودين في الدولة العثمانية الذين حقَّقوا انتصارات باهرة على الإسبان في شمال إفريقيا، وقد حكم الجزائرَ حوالي 15 عامًا، تخللتها حروبٌ طاحنة. أراد حسن باشا أن يطهِّرَ وهران من الوجود الإسباني، فأخذ يستعدُّ في مدينة الجزائر لجمع قوى جديدةٍ منظَّمة منقادة إلى جانب الجيشِ العثماني، فجنَّد عشر"},{"id":3767,"era":"c10","t":"عقد الدولة العثمانية معاهدة إستانبول مع البندقية .","s":"عقدت الدولةُ العثمانية معاهدةَ إستانبول مع البندقية, فالدولة العثمانية لم يُقعِدْها هزيمة معركة ليبانتو القاسية سنة 979هـ ولم تضعُفْ هِمَّةُ الصدر الأعظم محمد باشا صقللي، فانتهز فرصة الشتاء وعدم إمكانية استمرار الحرب لتجهيز أسطول جديد، وبذَلَ النَّفس والنفيس في تجهيزِه وتسليحه، حتى إذا أقبل صيف سنة 1572م كان قد تمَّ بناء 250 سفينة، وأعلم الصدرُ الأعظم البنادقةَ باستعداده للجولة الثانية، ففضَّلت ال"},{"id":3768,"era":"c10","t":"وقوع فتنة عظيمة بمراكش .","s":"كان الفقيهُ أبو عبد الله محمد الأندلسي نزيلُ مراكش قد استهوى بما يظهر عليه من زهدٍ وصلاحٍ كثيرًا من العامة، فتبعوه، وكانت تصدرُ عنه مقالات قبيحةٌ من الطعن على أئمة المذاهب رحمهم الله تعالى، ويتفوه بمقالات شنيعة في الدين، فأمر السلطانُ الغالب بالله بقتلِه، فاستغاث بالعامَّةِ مِن أتباعه، واعصوصبوا عليه ووقعت فتنةٌ عظيمة بمراكش بسَبَبِه إلى أن قُتِلَ وصُلِب على باب داره برياض الزيتون بمراكش، وكان ذلك"},{"id":3769,"era":"c10","t":"قيام النصارى بمكيدة البارود بجامع المنصور في مراكش .","s":"كان بقصبة مراكش جماعةٌ من أسارى النصارى من لدُن أيامِ أبي العباس الأعرج وأخيه أبي عبد الله الشيخ، فرأوا الجمعَ الغفير من أعيان المسلمين وأهلِ الدولة يحضرون كلَّ جمعة للصلاة مع السلطان بجامعِ المنصور من القصبة، فحدَّثَتهم أنفسُهم الشيطانية بأن يصنعوا مكيدةً يُهلكون بها السلطانَ ومن معه، فحفروا في خُفيةٍ تحت الجامع حفرةً مَلؤُوها من البارود ووضعوا فيها فتيلًا تسري فيه النارُ على مهلٍ كي ينقلبَ الجام"},{"id":3770,"era":"c10","t":"السلطان العثماني ينصب هنري شقيق ملك فرنسا ملكا على بولونيا .","s":"نصبَ السلطانُ العثمانيُّ هنري شقيقَ ملك فرنسا شارل التاسع ملكًا على بولونيا التي كانت قد دخلت في تبعية الدولة العثمانية من سنة 1573م حتى 1592م, وكانت من الدول الملكيَّة الكبرى في أوروبا."},{"id":3771,"era":"c10","t":"استيلاء الإسبان على تونس .","s":"كان فيليب الثاني قد تشجَّع لاحتلال تونس؛ بسبب لجوء السلطان الحفصي أبي العباس الثاني- الذي حكم تونس سنة 942- إليه، وطلب منه المساعدة في إخماد الثوراتِ فاشترط فيليب إعطاءَهم امتيازاتٍ كبيرة تتيح لهم سكنَ جميع أنحاء تونس، ويتنازلُ لهم عن عناية وبنزرت وحلق الواد, فرفض أبو العباس الشروطَ، ولكنَّ أخاه محمد بن الحسين قَبِلَها بعد ذلك, فخرج (دون خوان) أخو الملك من جزيرة صقلية في رجب 981, على رأس أسطول مكو"},{"id":3772,"era":"c10","t":"وفاة السلطان أبي محمد السعدي أمير السعديين وتولي ابنه .","s":"هو السلطان أبو محمد عبد الله الغالب بالله، ابن السلطان محمد الشيخ السعدي أمير السعديين في المغرب، ولِدَ بتارودانت سنة 933، وانتقل إلى فاس، فبويع له فيها يومَ ورد النبأ من تارودانت بأنَّ الترك اغتالوا أباه آخر سنة 964, وأتته بيعةُ مراكش في أول سنة 965 واستوثق له الأمر, وبعد أربعة أشهر من ولايته أقبل من تلمسان جيشٌ من الترك بقيادة حسن بن خير الدين بربروسا، فقاتله الغالب باللَّه بالقربِ من فاس وهزمه,"},{"id":3773,"era":"c10","t":"خلع ملك السعديين محمد الثاني وتولي عمه عبد الملك .","s":"لَمَّا هرب عبد الملك بن محمد المهدي أبو مروان وأحمد المنصور عمَّا المتوكل على الله محمد الثاني زعيم السعديين، بعد توليه الحكم في المغرب بسبب عدائه لهما- استنجدا بالدولة العثمانية في الجزائر، فوجدت الدولةُ العثمانية في انشغال مَلِك إسبانيا فيليب الثاني بأحداث أوروبا الغربية- حيث ثورة الأراضي المنخفضة- فرصةً مناسِبةً للتدخل في المغرب، فأمدُّوا عبد الملك بجيشٍ قوامه خمسة آلاف مقاتل مسلَّحين بأحسن الأ"},{"id":3774,"era":"c10","t":"استعادة تونس وتحويلها لولاية عثمانية .","s":"لما دخل الإسبان إلى تونس قاموا بإرجاع أحمد الحفصي، لكنهم اشترطوا عليه مقابِلَ ذلك أن يمنحَهم أراضيَ من تونس، فرفض ذلك فخلعوه وولَّوا أخاه محمدًا مكانه، وكان قد وافق على طلب الإسبان، فلجأ أحمد إلى صقلية ومات في باليرمو، أمَّا أخوه محمد فأدخل الإسبان إلى البلاد فشاركوه السلطةَ وكثُرَ الفساد وهرب أكثرُ الناس إلى الجبال، ولكنْ لم يلبث الأمرُ فيها أكثر من ثمانية أشهر، حتى أبحر الأسطولُ العثماني بقيادة "},{"id":3775,"era":"c10","t":"وفاة السلطان سليم الثاني بن سليمان القانوني .","s":"هو السلطان سليم الثاني بن سليمان القانوني بن سليم الأول بن بايزيد الثاني بن محمد الفاتح. ولِدَ سليم الثاني في 6 رجب سنة 930 وهو ابن روكسلان الروسية. تولَّى المُلك بعد موت أبيه سليمان القانوني, ولم يكن السلطان سليم متصفًا بما يؤهِّله للقيام بحفظ فتوحات أبيه، فضلًا عن إضافة شيء إليها! وكان لوجود الوزير الطويل محمد باشا صقللي المدرَّب على الأعمال الحربية والسياسية دور كبير في حفظ الدولة، فحُسنُ سياست"},{"id":3776,"era":"c10","t":"خضوع بولونيا تحت الولاية العثمانية .","s":"ترك هنري ملك بولونيا منصِبَه وعاد إلى فرنسا، فأوصى الخليفةُ مراد الثالث أعيانَ بولونيا بانتخاب أمير ترانسلفانيا ملكًا عليهم، ففعلوا ذلك وأصبحت بولونيا بذلك تحت حماية العثمانيين، واعترفت النمسا بذلك في معاهدة الصلحِ التي أبرمتها مع الدولة العثمانية في العام التالي، وذلك حين هجم التتارُ على الحدود البولونية، فاستنجدت بالدولة العثمانية فأعلن حمايتَها بموجبِ معاهدةٍ رسميةٍ."},{"id":3777,"era":"c10","t":"الدولة العثمانية تجدد امتيازات الدول الأجنبية .","s":"جدَّد الخليفةُ مراد الثالث للدُّول الأوربية امتيازاتِها، وهي فرنسا والبندقية، وزاد عليها أن أصبح السفيرُ الفرنسي يأتي في مقدِّمة سفراء الدول الأجنبية الذين كثُروا في إستانبول، وكانت سفُنُ الدول الأوربية تدخل الموانئ العثمانية تحت ظِلِّ العلم الفرنسي باستثناء البندقية، ثم جاءت بعدئذ إنكلترا التي حصلت على امتيازات لتجَّارها أيضًا، وطِبقًا للمعاهدات السابقة فقد قامت فرنسا بإرسال البَعثات الدينية النص"},{"id":3778,"era":"c10","t":"وفاة الشاه طهماسب الصفوي وقيام ابنه إسماعيل الثاني .","s":"هو الشاه طهماسب بن إسماعيل الصفوي. تولَّى السلطة على الصفويين بعد أبيه، وهو الابن الأكبر لإسماعيل شاه، ثم ثار عليه أخوه إخلاص ميرزا مدَّعيًا حقه في العرش، فتمكن من أسْرِه وقتْلِه، ثم توفِّيَ طهماسب في هذه السنة مسمومًا بعد أن دام في الملك أربعة وخمسين عامًا، فخلفه ابنُه إسماعيل الثاني الذي كان محبوسًا منذ عام 965 بسبب استقلاله العسكري؛ مما أثار شكوك أبيه وخوفه من الثوران عليه وإطاحته من المُلك، فل"},{"id":3779,"era":"c10","t":"استيلاء أبي مروان عبد الملك ابن الشيخ السعدي على مراكش .","s":"بعد انتهاءِ أبي مروان عبد الملك ابن الشيخ السعدي من ضَمِّ فاس, تقدَّم إلى البلاد المراكشية قاصدًا حرب ابن أخيه محمد المتوكل على الله وتشريده عنها، ولما سَمعَ ابنُ أخيه بخروجه إليه وقصْده إياه، تهيأ لملاقاته وسار إلى منازلته، فالتقى الجمعان بموضعٍ يسمى خندق الريحان، على مقربة من وادي شراط من أحواز سلا، فكانت الهزيمة أيضًا على المتوكل على الله، وتبعه عمُّه أبو العباس أحمد المنصور خليفةُ أخيه أبي مرو"},{"id":3780,"era":"c10","t":"وفاة الشاه إسماعيل الثاني بن طهماسب وقيام أخيه محمد خدابنده .","s":"هو الشاه إسماعيل الثاني بن طهماسب بن إسماعيل بن حيدر الصفوي، ثالث حكام الدولة الصفوية، ملك بعد أبيه سنة 984 وكان محبوسًا بقلعة ألموت منذ عشرين سنة؛ بسب استقلاله العسكري، فلما بويع بالحُكمِ قام بقتلِ جميع أخوته ما عدا محمد خدابنده، كما قتل جميع أولاده ما عدا الأكبر حسينًا، وأخاه عباسًا الذي نجا بأعجوبة, وكان إسماعيل الثاني شيعيًّا ثم صار سنيًّا، وقتل غالبَ الروافض وكان متجبرًا متعظِّمًا، فاحتجب عن "},{"id":3781,"era":"c10","t":"غزو الأشراف لنجد .","s":"غزا الأشراف نجدًا بقيادة الشريف حسن بن أبي نمي، وهاجموا بلدة معكال التي أصبحت جزءًا من مدينة الرياض الحالية, وبقي مدة فيها ثم عاد بعد ثلاث سنوات، وغزا الخرج والعارض، واعترضه أثناء عودته جماعةٌ من بني خالد فهزمهم."},{"id":3782,"era":"c10","t":"معركة وادي المخازن بين السعديين والعثمانيون والبرتغاليين .","s":"كان محمد المتوكل على الله بعد هزيمته من عمِّه عبد الملك قد اتصل بمَلِك البرتغال سبستيان، واتَّفق معه على أن يُعينَه على طرد عمِّه من حكم المغرب، وأن يتنازلَ له مقابل ذلك عن جميع شواطئ المغرب، فقَبِلَ سبستيان ذلك العرض المغربي، انتقل المتوكِّل إلى سبتة، وأقام بها أربعة شهور، ومنها اتَّجه إلى طنجة في انتظار سبستيان على رأس القوات العسكرية، وفي أثناء استعدادات الدول الأوروبية- وخاصة البرتغال- للوثوب "},{"id":3783,"era":"c10","t":"وفاة ملك السعديين عبد الملك بن السلطان محمد الشيخ السعدي .","s":"هو السلطان أبو مروان عبد الملك ابن السلطان محمد الشيخ السعدي ملك السعديين، تولى حكم المغرب بعد أن انتزعَه من ابن أخيه محمد الثاني، الذي أعلن من بداية حكمِه العداءَ لأعمامه أبي مروان وأبي العباس، فاستعانا بالعثمانيين، فقَدَّموا لهما الدعم حيث تمكن عبد الملك من حكم المغربِ وأخوه أبو العباس ساعِدُه الأيمن. كان أبو مروان خلافَ أخيه الغالب بالله وابنه محمد الثاني في التعاون مع الإسبان والبرتغال ضِدَّ ا"},{"id":3784,"era":"c10","t":"مبايعة السلطان المنصور أحمد بن محمد السعدي بحكم المغرب .","s":"بعد انتصار المسلمين على النصارى في معركةِ وادي المخازن التي توفِّيَ أثناءها أبو مروان عبد الملك السعدي, تمَّت بيعةُ المنصور أحمد بن محمد الشيخ السعدي المعروف بالذهبي، بعد أن اجتمع عليه مَن حضر هناك من أهل الحَلِّ والعقدِ، ثم لَمَّا قفل المنصور من غزوته تلك، ودخل حضرةَ فاس يوم الخميس عاشر جمادى الآخرة من هذه السنة جُدِّدت له البيعةُ بها ووافق عليه من لم يحضُر يوم وادي المخازن، ثم بعث إلى مراكش وغير"},{"id":3785,"era":"c10","t":"معركة قويون كجيدي وانتصار العثمانيين فيها على الصفويين  .","s":"انتصر العثمانيون على الصفويين في معركة قويون كجيدي، والتي قُتِلَ فيها من الصفويين خمسة آلاف جندي، وهذا ما مهَّد السبيل لسيطرة العثمانيين على شيروان (أذربيجان حاليًّا)."},{"id":3786,"era":"c10","t":"معركة شماهي وانتصار العثمانيين فيها على الصفويين .","s":"انتصارُ العثمانيين على الصفويين في معركة شماهي، وقع ذلك في القفقاس، وقد خسر الصفويون في هذه المعركة 15 ألف قتيل، وجاءت هذه المعركة في إطار حروبٍ طاحنة بين الجانبين؛ للسيطرة على زعامة العالمِ الإسلاميِّ."},{"id":3787,"era":"c10","t":"غلاء عظيم بالمغرب .","s":"وقع غلاءٌ عظيم بالمغرب، حتى عُرِف ذلك العام بعام البقول، وقيل إنه لما انتهب الناسُ غنيمة وادي المخازن، كان الناس يتوقَّعون مغبَّتها لاختلاط الأموال بالحرامِ، فظهر أثر ذلك من غلاءٍ وغيره، وكان يقال بأن البركةَ رُفِعت من الأموال من يومئذ."},{"id":3788,"era":"c10","t":"مرضُ المنصور أبي العباس أحمد السعدي  .","s":"مَرِضَ المنصور أبو العباس أحمد السعدي مرضًا مَخوفًا وطال به حتى كادت الأمور تختلُّ، ثم تداركه اللهُ على يد الحكيم الماهر أبي عبد الله محمد الطبيب، وكان يوم خروجه يومًا مشهودًا."},{"id":3789,"era":"c10","t":"رفع الصفويين حصارهم عن العثمانيين في تفليس .","s":"حاصر 15 ألف جندي صفوي ما يقرُبُ من 1800 جندي عثماني في تفليس، وقد استمرَّ هذا الحصار 124 يومًا، ولم يرفع الصفويون الحصار إلَّا بعد سماعهم أصوات الموسيقى العسكرية العثمانية التي جاءت لنجدة تفليس."},{"id":3790,"era":"c10","t":"الدولة العثمانية تؤسس أميرالية الخزر .","s":"أسَّست الدولة العثمانية أميرالية الخزر، وهي قيادة بحرية في داغستان, وكان أسطولها الرئيسي في ميناء باكو في أذربيجان حاليًّا، وكان أول أمير لها هو محمد بك، وقد انتهت هذه الأميرالية بسبب انتقال داغستان وشيروان أذربيجان إلى حوزة الصفويين."},{"id":3791,"era":"c10","t":"وفاة الصدر الأعظم صوقوللو محمد باشا رئيس وزراء الدولة العثمانية .","s":"هو صوقوللو محمد باشا: سياسي عثماني، أشهَرُ من تولى منصِبَ الصدر الأعظم في الدولة العثمانية، أصلُه من البوسنة، كانت عائلته صربيةً نصرانية، ولد سنة 912 في سراييفو، دخل في خدمة الدولة العثمانية عن طريق نظامِ الدوشيرمة، والذي من خلاله يُؤخَذُ أولاد السكَّان النصارى من أُسَرِهم في سن مبكِّر من الطفولة ويُربَّون في معسكرات خاصة بهم، ويتعلمون هناك اللغة والعادات والتقاليد التركية، وحب الشهادة والدين الإس"},{"id":3792,"era":"c10","t":"مبايعة المأمون ابن المنصور أبي العباس أحمد السعدي بولاية العهد .","s":"لما شفيَ المنصور أحمد السعدي من مرضه الذي ألمَّ به, وعاد إلى حاله من الصحة؛ أجمع رأي أعيان الدولة السعدية واتَّفقت كلمة كبرائها على أن يطلبوا منه تعيينَ من يلي الأمرَ بعده، ويكون وليَّ عهده، وكان المنصور مهيبًا لا يقدِرُ أحد على مواجهته بمثل هذا، فاتفقوا على أن يكون البادئ لذلك القائِدَ المؤمن بن الغازي العمري؛ لِما له من الإدلال على المنصور بطول الخدمة وسالف التربية، فقال له ابن الغازي: يا مولانا"},{"id":3793,"era":"c10","t":"ثورة داود بن عبد المؤمن بن محمد الشيخ السعدي على عمه المنصور .","s":"لما وقعت البيعةُ للمأمون عبد الله بن المنصور أحمد السعدي العام الماضي وتكاملَ أمرُها، ثار الرئيس أبو سليمان داود بن عبد المؤمن ابن السلطان محمد الشيخ، وهو ابن أخي المنصور، وفرَّ إلى جبل سكسيوة وشقَّ عصا الطاعة ودعا إلى نفسه، فانثالت عليه أوشابٌ من البربر وغيرهم، ونجَمَ أمرُه وأثَّرت في أذن الرعية جعجعتُه، فبعث إليه المنصور قائدَه الزعيم أبا عبد الله محمد بن إبراهيم بن بجة، فناوشه القتال بجبل سكسيو"},{"id":3794,"era":"c10","t":"والي مصر حسن باشا يأمر بتغيير لباس اليهود والنصارى .","s":"أمر والي مصر حسن باشا الخادم بتغيير لباسِ اليهود والنصارى، فبدل العمائِمَ الصُّفرَ للنصارى، أصبحت البرانيطَ السود، وبدَّل العمائم الزُّرق لليهود، أصبحت الطراطيرَ السود."},{"id":3795,"era":"c10","t":"العثمانيون يستولون على شروان من بلاد الصفويين والكرج سكان جورجيا وغيرها .","s":"بعد أن تولى الشاه محمد خدابنده واختلف عليه الناسُ وحدثت عدَّةُ ثورات وتزعزعت الأوضاع الداخلية، انتهز العثمانيون هذه الفرصة فأرسلوا جيشًا احتلَّ الكرج ودخل عاصمتَها تفليس، ثم دخلوا بعد انقضاء الشتاء إلى شوران أذربيجان الشمالية، ثم تابعوا مسيرَهم بقيادة عثمان باشا على بلاد داغستان، ثمَّ سار إلى بلاد القرم عبر جبال القوقاز لتأديبِ خان القرم، الذي رفض إرسال مَدَد للعثمانيين لمحاربة الصفويين، وقد أنهكه"},{"id":3796,"era":"c10","t":"محاولة العثمانيين أخذ المغرب وجعلها ولاية عثمانية .","s":"بدأت القوات الإسبانية في اكتساح الأراضي البرتغالية، ولم يستطِع الأمير البرتغالي دون أنطونيو مقاومةَ تلك القوات الإسبانية، التي ضمَّت أراضيه لسنة 988 (1580م)، عند ذلك اقترح السلطان العثماني مراد الثالث على السلطان أحمد المنصور السعدي عقْدَ تحالف عسكري ضِدَّ الإسبان، على أساس إمداده بأسطول حربي وقوات عسكرية، فبعث برسالتين في رجب 988 (سبتمبر 1580م) يعرِضُ عليه فيهما إرسال إمدادات عسكرية لفاس يستفتحُ "},{"id":3797,"era":"c10","t":"فتح العثمانيين مدينة إيريفان الإيرانية  .","s":"احتلَّ العثمانيون مدينة إيريفان الإيرانية بقيادة السردار فرحات باشا، وبنى بها حصن إيريفان مكان حصن أرمني قديم على ضفاف نهر هردزان، وبقي العثمانيون في المدينة حتى عام 1603م حين استعادها الصفويون مرةً أخرى إثر الحروبِ العثمانية الصفوية الأولى."},{"id":3798,"era":"c10","t":"استيلاء المنصور أحمد السعدي على بلاد الصحراء تيكورارين وتوات .","s":"لما استقرَّ المنصور أحمد السعدي بمراكش، وأمن من هجوم العثمانيين على المغرب، طَمِحت نفسُه إلى التغلب على بلاد تيكورارين وتوات من أرض الصحراء وما انضاف إلى ذلك من القرى والمداشر- المزارع- إذ كان أهل تلك البلاد قد انكفَّت عنهم أيدي الملوك ولم تَسُسْهم الدول منذ أزمان، ولا قادهم سلطانٌ قاهر إلى ما يراد منهم، فسنح للمنصور أن يجمع بهم الكلمةَ ويرُدَّهم إلى أمر الله، فبعث إليهم القائِدَ أبا عبد الله محمد"},{"id":3799,"era":"c10","t":"العثمانيون يهاجمون شواطئ إسبانيا .","s":"جهَّز الوالي العثماني في الجزائر أسطولَه في هذه السنة لمحاربة إسبانيا فوق أرضِها، فنزل المجاهدون المسلمون في برشلونة، فأعملوا فيها تدميرًا ثم عبَروا مضيقَ جبل طارق وهاجموا جزر الكناري التي تحتلُّها إسبانيا، فدمَّروا المراكز العسكرية وغَنِموا ما فيها ولم يكن الأسطول العثماني يذهب للأندلس لمجرد التنكيل بالإسبانيين ولتدمير منشآتهم، بل كان بالدرجة الأولى لإنقاذ المسلمين من نكبتهم، وتعرَّض المجاهدون أث"},{"id":3800,"era":"c10","t":"معركة \"مشعلة لر\" وانتصار العثمانيين على الصفويين فيها .","s":"انتصر العثمانيون على الصفويين في معركة \"مشعلة لر\" الطاحنة, وقد جاء هذا الانتصارُ بعد ثلاثة أيام من القتال، أثناء نزاع الفريقين للسيطرة على شيروان (أذربيجان حاليًّا)، وقد خَسِر الصفويون في هذه المعركة حوالي 11 ألف قتيل."},{"id":3801,"era":"c10","t":"معركة \"ديزفول\" وانتصار العثمانيين على الصفويين فيها .","s":"انتصر العثمانيون على الصفويين في معركة ديزفول, وقد جاءت هذه الحربُ بعد سيطرة العثمانيين على سواحِلِ خليج البصرة الشمالية."},{"id":3802,"era":"c10","t":"تنازل الصفويين عن بعض بلادهم لصالح العثمانيين .","s":"بعد أن دخل العثمانيون بعض بلاد الصفويين سنة 991, ورجع عثمان باشا إلى إستانبول، عاد في هذه السنة إلى غزو الصفويين وانتصر على قائدِهم حمزة ميرزا، ودخل تبريز عاصمَتَهم ثم جرى الصلح بين الطرفين، وتنازل الصفويون للعثمانيين عن بلاد الكرج وشروان ولورستان الواقعة جنوب أذربيجان."},{"id":3803,"era":"c10","t":"ثورة الحاج قرقوش ببلاد غمارة ومقتله .","s":"ثار رجل يقال له الحاج قرقوش بجبال غمارة وبلاد الهبط، وتسمَّى بأمير المؤمنين، وكان في ابتداء أمره حائكًا، وظهر عليه الزهد والصلاح، واعتقدته العامةُ، ثم استحال أمرُه فأُخِذَ وقُتل وحُمِل رأسه إلى مراكش، وانقطعت مادةُ فساده."},{"id":3804,"era":"c10","t":"فتح العثمانيين مدينة تبريز الإيرانية .","s":"فتح العثمانيون مدينة تبريز الإيرانية، وقد كانت هذه المدينة عاصمةَ الدولة الصفوية، وأسَّس العثمانيون إيالة تبريز التي استمرَّت حوالي 18 عامًا."},{"id":3805,"era":"c10","t":"العثمانيون يسيطرون على مقديشيو ويبعدون الخطر البرتغالي .","s":"استطاع الأسطولُ العثماني أن يجتاز القرنَ الإفريقيَّ ويستولي على مقديشيو وغيرها من المحطات الواقعة على شواطئ الصومال؛ بحيث لم يبقَ في أيدي البرتغال سوى ملندى وموضعين آخرين، وبذلك سيطر العثمانيون على الساحل الإفريقي الشرقي، وقطعوا خطَّ المواصلات حول إفريقيَّةَ عن المستعمرات البرتغالية في الهند."},{"id":3806,"era":"c10","t":"خلع الشاه محمد خدابنده وتولي عباس الأول مكانه .","s":"بعد أن تولى محمد خدابنده مُلكَ الصفويين وبقي إلى هذا العام؛ حيث خلعه عباسُ بن طهماسب المعروف بعباس الكبير، وعمره كان سبعة عشر عامًا، فسعى عباس إلى إقامة صلح مع العثمانيين، تنازل بمقتضاه عن تلك الأماكن التي أصبحت بيَدِ العثمانيين عام 993 كما تعهَّد بعدم سبِّ الخلفاء الراشدين أبي بكر وعمر وعثمان رضي الله عنهم، في أرض مملكته، وبعث بابن عمٍّ له يدعى حيدر ميزرا رهينةً إلى إستانبول؛ لضمان تنفيذ ما اتفقا"},{"id":3807,"era":"c10","t":"معركة كارفو وانتصار الجيش البولوني على الجيش الألماني  .","s":"هزم الجيش البولوني المعزَّز بوحدات الصاعقة التركية نظيرَه الجيش الألماني في معركة كارفو، وأُسِرَ الأرشيدق الألماني سيجموند، ويرجع سبب هذه المعركة إلى رغبة الألمان في السيطرة على العرش البولوني الذي كان تابعًا للدولة العثمانية حتى عام 1592م."},{"id":3808,"era":"c10","t":"العثمانيون ينتصرون على الصفويين .","s":"انتصر العثمانيون بقيادة جعفر باشا حاكم شيروان (أذربيجان حاليًّا) على الصفويين بقيادة زياد أوغلو محمد خان، وقتلوا نصفَ الجيش الصفوي، وقد مهَّد هذا الانتصار الطريقَ لعقد معاهدة إستانبول عام 998 بين الجانبين."},{"id":3809,"era":"c10","t":"معاهدة إستانبول بين الدولة العثمانية والدولة الصفوية في إيران .","s":"عَقَدت الدولة العثمانية معاهدةَ إستانبول مع الدولة الصفوية في إيران، وكانت هذه المعاهدة قد أنهت الحربَ الشرسة بين الدولتين التي استمرت 12 عامًا، واعترفت إيران في هذه المعاهدة باحترام حرية المذهبِ السنيِّ، ووافقت على عَدَمِ سَبِّ الصحابة، وعلى مبادلة الأسرى بين الجانبين."},{"id":3810,"era":"c10","t":"إحباط العثمانيين أول مساعي اليهود للاستيطان في فلسطين .","s":"ظنَّ اليهودُ أنَّ الفرصةَ سانحة لهم لتحقيقِ حُلمٍ راودهم طويلًا، فنزحوا في هجراتٍ متقطعة ومتقاربة إلى سيناء لاستيطانِها، وكانت خطَّتُهم تقوم في المراحل الأولى على تركيز إقامتِهم في مدينة الطور، وكان اختيارُهم لهذه المدينة اختيارًا هادفًا؛ فهذه المدينة- وهي تقع على الشاطئ الشرقي لخليج السويس- لها ميناء يصلح لرسو السفن التجارية، وكانت تأتيها سفن من جدَّة، وينبع، وسواكن، والعقبة، والقلزم، كما كانت ال"},{"id":3811,"era":"c10","t":"الدولة السعدية تجتاح السودان الغربي .","s":"قام الملك أبو العباس أحمد المنصور بن محمد المهدي- سلطانُ دولة السعديين بالمغرب- باجتياح السودان الغربي، الذي أخضع فيه سلطانَ سنغاي وأدخله في طاعته، فكانت هذه العملية في السودان الغربي أول الحقوق التي انتدبت إليها الحكومة المغربية للتحدُّث عن سيادتها على موريتانيا والسنغال والنيجر."},{"id":3812,"era":"c10","t":"غزو السعديين السودان وفتحها .","s":"عزم السلطانُ أحمد المنصور السعدي على غزو السودان، فاشتغل بتجهيز آلة الحرب وما يحتاج إليه الجيشُ من آلة السفر ومهمَّاته، وأمر القوَّادَ أن يقوِّموا حِصَصَ القبائل وما يحتاجون إليه من إبلٍ وخيل وبغال، وأنَّ من أتى بجملٍ ضعيف يعاقَبُ، واشتغل هو بتقويم آلةِ الحرب من المدافِعِ والعجلات التي تحمِلُها، والبارود والرصاص والكور، وتقويم الخشب واللوح والحديد للغلائط، والسفن والفلك والمجاذيف والقلوع والبراميل"},{"id":3813,"era":"c10","t":"زوال الدولة المهدوية .","s":"زالت الدولةُ المهدوية بأحمد نكر من بلاد الدكن، وقُتل الوزير جمال خان وجيء برأسِه إلى أحمد نكر، وطِيفَ به فيها، ثم علِّق أيامًا وتسلطن رهان شاه."},{"id":3814,"era":"c10","t":"معاهدة بين الدولة العثمانية وبولونيا .","s":"عقدت الدولةُ العثمانية معاهدةً مع بولونيا، ونصَّت هذه المعاهدة على تبعيَّةِ بولونيا (لتوانيا) للدولةِ العثمانية، وأن تُسدِّدَ بولونيا ربع مليون ليرة ذهبية سنويًّا إلى إستانبول، وأن تتبع بولونيا سياسةً خارجية متوافقةً مع السياسة الخارجيَّة العثمانية."},{"id":3815,"era":"c10","t":"انتشر الإسلام في وسط إفريقيا عبر مدينة تمبكتو في مالي .","s":"كانت الصحراء الكبرى من إفريقيا تحت نفوذ إمبراطورية سنغاي أو صنغاي الإسلامية التي تقع في الساحل الغربي من إفريقيا, وكان ملوكُها من الأسقيين وكبيرُهم الأول هو محمد الكبير الذي يعتبر هو أوَّلَ من نظَّم أمور المملكة، فنظَّم البلادَ والوظائِفَ، وأشرف على الشؤون القَبَلية، وفتح البلادَ ووسَّعها، وكان للدولةِ تنظيمُها الإداري وجيشُها النظامي وقضاتُها أصحابُ السُّلطات الشرعية, وفي عهدِهم تعتبرُ مدينة تمبك"},{"id":3816,"era":"c11","t":"هزيمة العثمانيين أمام المجريين والنمساويين .","s":"بعد أن قُتِل الوزير محمد الصقلي وكثُرت التوليةُ والعزلُ بعده, وقد كان هو عمادَ الدولة وركنَها، ومع توقُّف الحروب التي كانت تباشِرُها الإنكشارية الذين أخذوا في الثورة والاعتداء والنَّهبِ والسرقة، فثاروا في إستانبول والقاهرة وغيرها، ثمَّ لما أعيد سنان باشا لولاية الصدر الأعظم، أشار بأن تسيَّرَ العساكر الإنكشارية إلى المجر، وهذا ما تمَّ، ولكِنَّ الجيش الذي كان قد تعوَّد الفوضى اختَلَّ نظامُه, فانهزم "},{"id":3817,"era":"c11","t":"هجوم الألمان على العثمانيين  .","s":"قام الجيش الألماني البالغ 40 ألف مقاتل بهجومٍ مباغت على الجيشِ العثماني المكوَّن مِن 10 آلاف مقاتلٍ في الجنوب الشرقي من زغرب الواقعة حاليًّا في كرواتيا، وقَتل 7 آلاف عثماني، بمن فيهم القائِدُ حسن باشا حاكِمُ البوسنة. وكانت هذه الغارة سببًا في إعلان تركيا الحربَ على ألمانيا."},{"id":3818,"era":"c11","t":"إعلان الدولة العثمانية الحرب على ألمانيا .","s":"أعلنت الدولةُ العثمانية الحربَ على ألمانيا بعد الغارةِ التي شنَّها الجيشُ الألماني على الجيش العثمانيِّ على ضفافِ نهر كولبا قُربَ حدود البوسنة، وكان هذا في عهد مراد الثالث من 982- 1003، وقد راح ضحيَّةَ هذه الغارة 7 آلاف عثماني, وأنهت هذه الحربُ حالةَ الصلح التي استمرت 25 عامًا بين الدولتين."},{"id":3819,"era":"c11","t":"قيام حكومة آفراسياب في البصرة تابعة للعثمانيين\n  .","s":"كانت البصرةُ واحدةً مِن المدُنِ التي شَهِدت الكثيرَ مِن الحركاتِ الثورية ضِدَّ الولاة العثمانيين؛ إذ تمكَّن الثوارُ من عزل ولاية البصرةِ عن باقي ولايات العراق، فبرزت أُسرة في جنوب العراق، وهي أُسرة أحد كبار ملَّاكي الأراضي من العرب، ويُدعى آفراسياب، وكان مؤسِّس هذه الأُسرة يشغلُ منصِبَ قائد القوَّات غير النظامية لحاكم البصرة أيوب باشا، فاستغل آفراسياب حالةَ الضعف التي شهدتها البصرةُ، ولم يتمكن الو"},{"id":3820,"era":"c11","t":"غزو العثمانيين ألمانيا .","s":"اجتاز القائِدُ العثماني قوجاسنان باشا الحدودَ الألمانية، وسيطر على مدينة \"يانق قلعة\" التي تقع على بعد 100 كم من الجنوب الشرقي لفيينا، وهي تعدُّ المنفذَ الرئيسيَّ لفيينا، وقد تمت السيطرةُ على هذه المدينة بعد حصار استمرَّ 51 يومًا."},{"id":3821,"era":"c11","t":"وفاة السلطان العثماني مراد الثالث بن سليم الثاني .","s":"هو السُّلطانُ العثماني مرادُ الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول بن بايزيد الثاني بن محمد الفاتح بن مراد الثاني. ولِدَ سنة 951. قال عبد الملك العصامي المكي: \"نشأ مرادٌ في ظِلِّ والده وجَدِّه على مهاد العِزِّ والسلطان في حجرِ الخلافةِ، راضعًا ثديَ العلم والعرفان، ولم تُعلَم له صبوةٌ مع توفُّرِ دواعيها، ولم يتناول شيئًا من المحرَّمات، بل ولا مِن المكروهات؛ فهو منذ ترعرع في شبابه ص"},{"id":3822,"era":"c11","t":"قتل السلطان العثماني محمد الثالث إخوانه التسعة عشر  .","s":"ذُكِرَ أنَّ السلطان محمد الثالث بدأ حكمَه بقتل تسعة عشر أخًا من إخوته الذكور، وأمر أن يُدفَنوا مع أبيه حتى لا ينافِسوه في الحُكم، كما أمر بقتلِ عشر نساءٍ من نساء أبيه كلُّهن حبالى، وهذا بعيد لا يقبلُه لا عقلٌ ولا شرعٌ، وترفضه الفِطَر السوية، وهو من الاتهامات التي حَرَص أعداءُ وخصوم الدولة على تشويه سير سلاطينها بمثل هذا الاتهام, وصرْف الأنظار عن بطولاتهم وإنجازاتهم التي حقَّقوها خلال حكمهم للمسلمي"},{"id":3823,"era":"c11","t":"استيلاء الألمان على قلعة إستركون من العثمانيين .","s":"استولى الألمان على قلعة إستركون الواقعة على الطريق بين بودابست وفيينا من العثمانيين. وكان السلطانُ العثماني سليمان القانوني قد فتح هذه القلعةَ قبل 52 عامًا. واستمرَّ الاحتلال الألماني للقلعة 10 سنوات نهبوا خلالها آثارَها التاريخية."},{"id":3824,"era":"c11","t":"قوات المغرب الأقصى تعبر الصحراء الكبرى لتنهي إمبراطورية سنغاي .","s":"بلغت إمبراطورية سنغاي أوْجَ قوَّتها في عهد الأسقيين، وأبرزهم محمد الكبير وابنه داود، وقد كانت إمبراطوريتهم انتشرت وتوسَّعت حتى وصلت إلى مالي ومشارفِ المجيد، ولامست الصحراءَ الكبرى، وانتصروا على الموسي ومالي والطوارق وبني حسان، حتى جاء أحمد الذهبي زعيمُ السعديين في المغرب الأقصى وجهز جيشًا ليس بالكبير، وكان مؤلَّفًا من ثلاثة آلاف جندي، مات أكثَرُ من نصفهم في طريقهم إلى السنغاي؛ بسبب سوء الأحوال وما"},{"id":3825,"era":"c11","t":"انتصار العثمانيين على النمسا والمجر في معركة كرزت .","s":"لما هُزِمَ الجيش العثماني الإنكشاري أمام النمسا والمجر عام 1001 أعلن أمراءُ الأفلاق والبغدان وترانسلفانيا التمَرُّدَ على الدولة العثمانية، وانضمُّوا إلى النمسا في حربها ضِدَّ العثمانيين، فسار السلطانُ محمد الثالث ومعه سنان باشا إلى بلغراد، ومنها إلى ميادين الوغى والجهاد، وبمجرَّد خروجه دبَّت في جيش السلطان الحميَّة الدينية والغَيرة العسكريَّة، ففتحوا قلعةَ أرلو الحصينة التي عجز السلطانُ سليمان عن "},{"id":3826,"era":"c11","t":"مقتل 4 آلاف تركي في مدينة بوخارست .","s":"قُتِل 4 آلاف تركي في مدينة بوخارست ذبحًا بالسيف، أثناء عصيانِ عددٍ من الإمارات العثمانية في المجر ورومانيا للدولة العثمانيةِ."},{"id":3827,"era":"c11","t":"وفاة شمس الدين الرملي الشافعي .","s":"هو شمسُ الدين محمد بن أحمد بن حمزة الرملي الشافعي، نسبةً إلى الرملة من قرى المنوفية بمصر، ولِدَ بالقاهرة سنة 919, وهو فقيهُ الديار المصرية في عصره، برع في الفقهِ الشافعيِّ حتى قيل عنه الشافعيُّ الصغير. قال عنه الشوكاني: \"لم أقفْ له على ترجمةٍ مبسوطة، لكن قال العصامي في وصفه: إمامُ الحرمين وشيخُ المصريين، من كانت العلماء تكتبُ عنه ما يُملي؛ مولانا شمس الدين محمد بن أحمد بن حمزة الرملي، فاتح أقفال م"},{"id":3828,"era":"c11","t":"ثورة الناصر ابن السلطان الغالب بالله ببلاد الريف ومقتله. .","s":"لما توفِّيَ الغالب بالله، قام بالأمر بعده ابنه المتوكِّلُ، فقبض على أخيه الناصر فاعتقله، فلم يزل معتقلًا عنده سائِرَ أيامه، إلى أن قَدِمَ عبد الملك المعتصم بجيشِ الترك وانتزع المُلكَ من يد ابن أخيه المتوكِّل، فسرَّح الناصر من اعتقالِه وأحسن إليه، فلم يزل عنده في أرغَدِ عيش إلى أن توفِّيَ المعتصم يوم وادي المخازن، وأفضى الأمر إلى أحمد المنصور، ففرَّ الناصر إلى آصيلا، وكانت للنصارى يومئذٍ، ثم عبر ال"},{"id":3829,"era":"c11","t":"الاستعمار الهولندي لجزر أندونيسيا .","s":"وصل الهولنديون إلى سومطرة وجاوه، وحدث بينهم وبين السكَّان معاركُ، وحاول البرتغاليون الوقوفَ في وجه الهولنديين، فتحرَّكوا بسفُنِهم ضِدَّهم، وكان الأندونيسيون قد تحالفوا ضِمنًا مع الهولنديين ضد البرتغاليين؛ ظنًّا منهم أنهم سيتخلَّصون من الحقد البرتغالي الصليبي، فتزحزح البرتغالُ عن أندونيسيا، ولكنَّ هولندا لم تكن أحسنُ حالًا من سلَفِها؛ فالصليبيون هم الصليبيون، فانقضُّوا على الجزر الأندونيسية سلبًا و"},{"id":3830,"era":"c11","t":"فتح العثمانيين قلعة أكرى شمال المجر .","s":"فتَحَ السلطانُ العثمانيُّ محمد الثالث قلعةَ أكرى في شمال المجر، تمَّ ذلك بعد 18 يومًا من الحصار، وقد قُتِل في هذه المعركة 11 ألف جندي ألماني، وكان العثمانيون قد حاصروا هذه القلعة 39 مرة، لكِنَّهم لم يتمكَّنوا من فتحها سابقًا؛ نظرًا لقوَّةِ تحصينِها."},{"id":3831,"era":"c11","t":"استيلاء الجيش الألماني على مدينة \"يانق قلعة\" .","s":"تقع مدينة \"يانق قلعة\" على بُعد 100 كم في الجنوب الشرقي لفيينا التي فتحها الجيش العثماني سنة 1002، وقد استولى عليها الألمانُ في هذه السنة بطريقة ذكية؛ حيث قامت وحدة تتكلَّمُ التركية بالدخولِ إلى القلعة ومهَّدت الطريقَ لدخولِ الجنود الألمان إلى القلعةِ والسيطرة عليها."},{"id":3832,"era":"c11","t":"ثورة قره يازجي ومعه المرتزقة ضد العثمانيين .","s":"بعد أن فرَّ كثيرٌ من الجند من معركة كرزت، قام السلطان العثماني محمد الثالث بنفيهم إلى الأناضول، فقام أحدُهم واسمه قره يازجي وادَّعى أنَّه رأى الرسول صلى الله عليه وسلم في المنام، وأنه وعده بالنصرِ على آل عثمان، فأعلن التمرُّد بعد أن تبِعَه كثيرٌ من المرتزقة من الجنود المنفيِّين، فدخل عينتاب فحاصرته الجيوشُ العثمانية، فأعلن الاستسلامَ على أن يُعطَى ولايةَ أماسيا، فوافق العثمانيون على ذلك، فلما ابتع"},{"id":3833,"era":"c11","t":"انتصار الجيش العثماني على الجيش الألماني .","s":"انتصر الجيشُ العثماني بقيادة حسن باشا على جيش ألماني ضخم مكوَّن من مائة ألف جندي، وقد حاز على غالبية مهمَّات الجيش الألماني الذي كان يحاصر العثمانيين لمدة 69 يومًا في \"قانيجة\" القريبة من يوغسلافيا حاليًّا، ويعدُّ هذا الانتصار من الانتصارات الكبرى التي حقَّقها العثمانيون رغم قلَّة عدد جيشهم!"},{"id":3834,"era":"c11","t":"ثورة الخيالة السباه في إستانبول .","s":"قامت ثورة الخيَّالة العثمانيين الذين يسَمَّون بالسباه في إستانبول مطالبين بالتعويضات عما لحِقَ بإقطاعاتهم من أضرارٍ بسبب فتنة الفراريين، ولم يكن بإمكانِ الدولة أن تعطيَهم عِوَضَها لعجزها، فاستعانت عليهم بالانكشارية فقضت على ثورتهم بعد أن أفسَدوا ونهبوا حتى المساجِدَ وغيرها ممَّا وصلت أيديهم إليه!"},{"id":3835,"era":"c11","t":"احتلال الصفويين جزيرة أوال (البحرين) .","s":"بدأ النفوذ الإنكليزي يظهر في منطقة الخليج العربي؛ حيث استمالت إنكلترا إليها الشاهَ عباس الصفوي شاه إيران ليقف معها ضد العثمانيين والبرتغاليين، وقد منح الشاه إنكلترا امتيازاتٍ واسعة في التجارة وساعدته هي على مدِّ نفوذه في الخليج، حتى استطاعت قواتُه من احتلال جزيرة أوال (البحرين) في هذا العام، بعد أن كانت تحت السيطرة العثمانية من عام 957 الذين طَرَدوا البرتغاليين منها."},{"id":3836,"era":"c11","t":"نهوض السلطان زيدان السعدي لحرب أخيه أبي فارس في مراكش .","s":"لما بايع أهلُ مراكش أبا فارس بن أحمد المنصور الذهبي السعدي، عزم أخوه زيدان على النهوض إليه، فخرج من فاس يؤمُّ بلاد الحوز، واتصل الخبَرُ بأبي فارس فجهَّز لقتال أخيه زيدان جيشًا كثيفًا وأمَّر عليهم ولده عبد الملك، فقيل له: إن زيدان رجلٌ شجاع عارفٌ بمكايد الحرب وخُدَعه، وولدك عبد الملك لا يقدِرُ على مقاومته، فلو سرَّحت أخاك محمد الشيخ المأمون لقتالِه كان أقرب للرأي؛ لأن أهل الغرب لا يقاتلونَه؛ لأنه ك"},{"id":3837,"era":"c11","t":"وفاة السلطان المنصور أحمد الذهبي زعيم دولة الأشراف السعديين .","s":"هو السلطان أبو العباس المنصور أحمد، المعروف بالذهبي ابن أبي عبد الله محمد الشيخ المهدي بن محمد القائم بأمر الله الزيداني الحسني السعدي، واسطةُ عِقد الملوك الأشراف السعديين، وأحدُ ملوك المغرب الأقصى العِظام. كانت ولادته بفاس سنة 956, وأمُّه الحُرَّة مسعودة بنت الشيخ الأجلِّ أبي العباس أحمد بن عبد الله الوزكيتي، وكانت من الصالحات الخيرات, وكان أبوه المهدي ينبِّه على أن ابنَه أحمد واسطةُ عِقد أولاده."},{"id":3838,"era":"c11","t":"مبايعة زيدان بن أحمد المنصور السعدي بالحكم في مدينة فاس .","s":"لَمَّا توفِّيَ المنصور أحمد الذهبي السعدي وفرَغَ الناس من دفنِه، اجتمع أهلُ الحَلِّ والعقد من أعيان فاس وكبرائها والجمهورِ من جيش المنصور على بيعةِ ولده زيدان، وقالوا إن المنصور استخلفه في حياتِه ومات في حجرِه، وكان ممن تصدى لذلك القاضيان قاضي الجماعة بفاس أبو القاسم بن أبي النعيم، والقاضي أبو الحسن علي بن عمران السلاسي, وكان زيدان لما توفِّي والده كتم موتَه وبعث جماعةً للقبض على أخيه محمد الشيخ ا"},{"id":3839,"era":"c11","t":"انحراف أهل مراكش عن طاعة زيدان بن المنصور أحمد السعيدي .","s":"كان المنصور أحمد السعيدي قد فرَّق عمالات المغرب على أولادِه، فاستعمل محمد الشيخ المأمون على فاس والغرب وولَّاه ولاية العهد من بعده، واستعمل زيدان على تادلا وأعمالها، واستخلفه عند نهوضه إلى فاس؛ للقضاء على ثورة ابنه الشيخ المأمون، وعيَّن ابنه أبي فارس على مراكش وأعمالها, فلما بلغ أهل مراكش وفاةُ المنصور وكتب إليهم أهلُ فاس بمبايعتهم لزيدان، امتنعوا وبايعوا أبا فارس لكونه خليفةَ أبيه بدارِ مُلكه الت"},{"id":3840,"era":"c11","t":"بدء الحرب العثمانية والإيرانية .","s":"بدأت الحربُ العثمانية الإيرانية بعد فترة من الصلح دامت 13 عامًا، وكان هدفُ الصفويين هو استردادَ المدن والأماكن التي استولى عليها العثمانيون، مثل تبريز وأذربيجان."},{"id":3841,"era":"c11","t":"وفاة السلطان العثماني محمد الثالث بن مراد الثالث .","s":"هو السلطان محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول بن يزيد الثاني بن محمد الفاتح بن مراد الثاني بن محمد جلبي بن بايزيد الأول بن مراد الأول بن أورخان بن الغازي عثمان، السلطانُ العثماني الثالثَ عشر من سلاطين العثمانيين، ولِدَ في ذي القعدة سنة 974, وكانت والدتُه جاريةً بندقيةَ الأصلِ أحبَّها والده فاصطفاها زوجةً له. أمَّره أبوه على مغنيسا في أواخر سنة 991 ودام واليً"},{"id":3842,"era":"c11","t":"انتصار العثمانيين على النمساويين .","s":"عيَّن السلطانُ أحمد لالا محمد باشا صدرًا أعظم خليفةً للصدر الأعظم يمشجي حسن باشا، حيث كان سردارًا عامًّا للجيوش التي جاهدت في النمسا، وهو من خيرة قوَّاد الجيوش، فاهتمَّ بتقوية الجيوش العثمانية وحاصر قلعةَ استراغون وفتحها، كما حارب إماراتِ الأفلاق والبغدان والأردل، وعقد صلحًا معهم، ولما مات لالا باشا خلَفَه قبوجي مراد باشا صدرًا أعظم، وكان قائدًا لإحدى فرق الجيش، وقد نجحت الجيوشُ العثمانية في هزيمة"},{"id":3843,"era":"c11","t":"الدولة العثمانية تجدد الامتيازات للدول الأوربية .","s":"جدَّدت الدولةُ العثمانية امتيازاتِ فرنسا وإنجلترا، على مثلها، كما جَدَّدت الاتفاقيةَ مع بولونيا- بولندا- بحيث تمنعُ الدولة تتارَ القرم من التعدي على بولونيا، وتمنع بولونيا القوزاق من التعدِّي على الدولة العثمانية، وتحصَّلت هولندا على امتيازات واستغلت ذلك في نشرِ الدُّخَان داخِلَ ديار الإسلام، وبدأ تعاطيه من قِبَل الجنود، فأصدر المفتي فتوى بمَنعِه فهاج الجندُ وأيَّدَهم الموظَّفون، فاضطر العلماءُ إل"},{"id":3844,"era":"c11","t":"وفاة السلطان جلال الدين محمد أكبر بن همايون التيموري في الهند .","s":"هو السلطانُ المؤيَّد المظفَّر أبو الفتح جلال الدين محمد أكبر بن همايون بن بابر التيموري الكوركاني، أكبرُ ملوك الهند وأشهرُهم في الذِّكر، ولِدَ في قلعة أمركوث من أرض السِّند في ثاني ربيع الأول سنة 949هـ من \"حميده بانو\". حين انهزم والده همايون من شير شاه، ثم رجع بعد بضعة سنين فافتتح قندهار وكابل وأكثر بلاد الهند، فلما مات همايون جلس ولدُه جلال الدين على سريره تحت وصاية الوزير بيرم خان؛ لأن سنَّه حين"},{"id":3845,"era":"c11","t":"تولي السلطان جهانكير خان بن أكبر الحكم في الهند .","s":"تولى السلطانُ أبو الفتح نور الدين محمد جهانكير خان بن جلال الدين أكبر المغوليُّ- من سلالة تيمورلنك- الحُكمَ في الهند، بعد وفاة والده، وفي عهده بدأت القوى الاستعمارية تتطلَّعُ إلى السيطرة على الهند تحت اسم التجارة، وقد دام حكمُه ثلاثًا وعشرين سنة."},{"id":3846,"era":"c11","t":"وفاة الشيخ ملا علي القاري الحنفي .","s":"هو الشيخ نور الدين أبو الحسن علي بن سلطان بن محمد القاري، الهَرَوي المكي، المعروف بملَّا علي القاري، من فقهاء الحنفية، وُلِد في هراة وسكن مكةَ وتوفي بها. كان زاهدًا في الدنيا، بعيدًا عن الحكَّام ومجالِسِهم، مُعرِضًا عن الوظائف والأعمال، وكان شديدًا عليهم، حاملًا على أهلِ البدع والضلالات في مكَّة محلِّ إقامته، قانعًا بما يحصِّل من بيعِ كُتُبِه، ويغلِبُ على حاله الزهد والعفاف والرضا بالكفاف، وكان قل"},{"id":3847,"era":"c11","t":"معاهدة ستفاتوروك بين الدولتين العثمانية والنمساوية .","s":"تم توقيعُ معاهدة بين الدولتين العثمانية والنمساوية، عُرفت باسم معاهدة ستفاتوروك، وانتهت بها تلك الحربُ التي استمرت نحو ثلاث عشرة سنة ونصف السنة. وبمقتضى هذه المعاهدة دفعت النمسا إلى الدولة العثمانية غرامةَ حرب قدرها 67000 سكة ذهبية، وأُلغيت الجزيةُ التي كان يدفعُها إمبراطور النمسا إلى الدولة العثمانية كلَّ سنة، وثبتت الحدودُ على أساس أن لكلٍّ الأراضيَ الموجودةَ تحت سيطرته، وأنْ تخاطِبَ الدولةُ الع"},{"id":3848,"era":"c11","t":"نهوض عبد الله بن الشيخ المأمون لحرب عمه أبي فارس .","s":"دعا الشيخ المأمون ابن السلطان أحمد المنصور السعدي تجارَ فاس فاستسلف منهم مالًا كثيرًا وأظهر من الظلمِ وسوءِ السيرة وخُبث السريرة ما هو شهيرٌ به، ثم تتبَّع قوَّاد أبيه فنهب ذخائِرَهم واستصفى أموالَهم وعذَّب من أخفى من ذلك شيئًا منهم، ثم جهز جيشًا لقتال أخيه أبي فارس بمراكش، وكان عدد الجيش نحو الثمانية آلاف، وأمَّرَ عليه ولده عبد الله فسار بجيوشه فوجد أبا فارس بمحلتِه في موضع يقال له إكلميم، ويقال ف"},{"id":3849,"era":"c11","t":"طرد المسلمين من أسبانيا (الأندلس). .","s":"أصدرت الحكومةُ الأسبانية مرسومًا يقضي بترحيل المسلمين من إسبانيا ترحيلًا نهائيًّا."},{"id":3850,"era":"c11","t":"ثورة محمد بن عبد المؤمن المهدي ثم هزيمته من السلطان زيدان .","s":"لما دخل عبدُ الله بن الشيخ المأمون السعدي مراكشَ واستولى عليها فعَلَ فيها أعظَمَ من فعلته الأولى بفاس، فهربت شرذمة من أهل مراكش إلى جبل جيليز واجتمع هنالك منهم عصابةٌ من أهل النجدة والحمية، واتفق رأيُهم على أن يُقَدِّموا للخلافة محمدَ بن عبد المؤمن ابن السلطان محمد الشيخ، وكان رجلًا خيِّرًا ديِّنًا صيِّنًا وقورًا, ومن أحفاد السلطان محمد الشيخ المهدي السعدي، فبايعه أهل مراكش هنالك والتفوا عليه، فخر"},{"id":3851,"era":"c11","t":"استيلاء السلطان زيدان على فاس وفرار أخوه محمد الشيخ .","s":"كان محمد الشيخ المأمون بن أحمد المنصور الذهبي السعدي ما يزال على قُبحِ السيرة والإساءة إلى الخاصة والعامة، حتى ملَّتْه النفوسُ ورفضته القلوبُ وضاق أهلُ فاس بشؤمِه ذرعًا، وكان قد بعث ابنَه عبد الله مرةً ثالثة إلى حرب أخيه السلطان زيدان بمراكش وأعمالها، فخرج عبد الله من فاس آخِرَ ذي الحجة سنة 1016 فالتقى الجمعان بوادي بوركراك، فكانت الهزيمة على عبد الله وفرَّ في رهطٍ من أصحابه وترك محلَّتَه بما فيها"},{"id":3852,"era":"c11","t":"الأمير فخر الدين المعني يستولي على بعلبك ويهدد باحتلال دمشق .","s":"فخرُ الدين المعني الثاني هو حفيد فخر الدين المعني الأول، الدرزي الأصل الذي قاتل مع السلطان سليم، فتولى بذلك لبنان والجبال المحيطة به، ولما تولى هذا الحفيدُ السلطة في لبنان عام 999هـ وكان درزيًّا وصوليًّا كبيرًا واستطاع أن يجمع المُعادين للإسلام من نصارى ونُصيرية ودروز، وأمثالهم، حتى تمكَّن من جبال لبنان، والسواحل وفلسطين، وأجزاء من سورية، ولما قوِيَ أمره فاوض الطليان فدعموه بالمال وبنى القلاع والح"},{"id":3853,"era":"c11","t":"وفاة السلطان أبي فارس بن أحمد المنصور الذهبي السعدي .","s":"هو السلطان أبو فارس عبد الله بن المنصور أحمد السعدي، بويع بمراكش بعد وفاة والده، ثم بعث أخاه محمد الشيخ المأمون لقتال أخيهما السلطان زيدان، فلما انتصر عليه نكث محمد الشيخ عهده مع أخيه أبي فارس واستبدَّ عليه، ثم بعثَ إليه ابنَه عبد الله فهزَمَ عمَّه أبا فارس إلى مسفيوة ثم منها إلى السوس، فأقام عند حاجب أبيه عبد العزيز بن سعيد الوزكيتي، ثم لما بالغ زيدان في طلبه فرَّ إلى أخيه الشيخ المأمون فلم يزل م"},{"id":3854,"era":"c11","t":"استيلاء النصارى الأسبان على العرائش بخيانة الشيخ ابن السعدي .","s":"استولى النصارى الأسبان على العرائش، وذلك بعد إخراجهم للمسلمين منها باتفاق مع حاكمها الشيخ المأمون ابن المنصور السعدي، الذي استعان بهم على أخيه السلطان زيدان، فاشترطوا عليه وقتها إعطاءهم العرائش وإخلاءها من سكَّانها، ففعل- خذَلَه اللهُ- ولما خرج منها المسلمون أقام بها القائد الكرني إلى أن دخلها النصارى واستولوا عليها في رابع رمضان من هذه السنة، ووقع في قلوب المسلمين من الامتعاض لأخذ العرائش أمرٌ عظ"},{"id":3855,"era":"c11","t":"وفاة الفقيه أحمد بن يحيى بن سالم الذويد اليمني .","s":"هو الشيخُ الفقيه المحقِّق أحمد بن يحيى بن سالم الذويد بن على بن محمد بن موسى الصعدي اليمني، أخذ عن السيد محمد بن عز الدين المفتي، وعبد العزيز بن محمد بن بهران، وسمع الأمهَّات الستَّ، واستجاز فيها من الحافظ محمد بن محمد المصري, وأجلُّ تلامذة الفقيه أحمد الذويد: الإمامُ القاسم بن محمد، والفقيه مهدي الشعيبي، وغيرهما, وكان فقيهًا محدِّثًا قليل النظير في المعقولات والصفات، إمامًا في الشرعيات على الإطلا"},{"id":3856,"era":"c11","t":"هزيمة العثمانيين أمام الصفويين وابتلاء أهل السنة في العراق .","s":"استغَلَّ الشاه عباس الصفوي انشغالَ الدولة العثمانية بالثورات الداخلية والحروب مع أوربا، بالإضافة للضعف الذي دبَّ فيها، فباشر في تخليصِ عراق العجم, واسترجع شمالَ العراق وتبريز ووان، واستطاع أن يحتلَّ بغداد والأماكن المقدَّسة الشيعية في النجف وكربلاء والكوفة، وكانت الجيوشُ العثمانية أضعفَ من أن تقاوم الجيوشَ الصفوية، فاضطر السلطان العثماني أحمد الأول أن يعقِدَ صلحًا مع الصفويين في عام 1013هـ استرجع "},{"id":3857,"era":"c11","t":"وفاة ابن محلي المدعي أنه المهدي المنتظر بفاس .","s":"أحمد بن عبد الله السجلماسي أبو العباس المعروف بابن محلي، متصَوِّف ادعى أنه المهدي الفاطمي المنتظَر، ولِدَ بمدينة سجلماسة، وطلب العلم بفاس، تصوَّف وكثُرَ أتباعه، وذهب إلى جنوب المغرب فكاتب رؤساء القبائل وعظماء البلدان أنَّه المهدي الفاطمي المنتظَر، مدَّعيًا أنه من سلالة العباس بن عبد المطلب، وزحف على سجلماسة واستولى عليها بعد قتال، وأرسل السلطانُ زيدان بن أحمد السعدي صاحب المغرب جيشًا لقتاله، فانهز"},{"id":3858,"era":"c11","t":"وفاة السلطان محمد الشيخ المأمون ابن المنصور أحمد السعدي .","s":"هو السلطان أبو عبد الله محمد الشيخ المأمون بن أحمد المنصور الذهبي، ملك السعديين في المغرب الأقصى. كان المأمونُ وَلِيَّ عهد أبيه المنصور وخليفتَه على فاس وأعمالها سائرَ مدة أبيه، وكان للمنصور اعتناءٌ تام به واهتمامٌ بشأنه حتى قيل إن المنصور كان لا يختِمُ على صندوق من صناديق المال إلا قال: \"جعل الله فتحَه على يد ابنِه الشيخ رجاءَ أن يقوم بالأمر بعدَه، فلم يُقدَّرْ له، وخرج الأمرُ عن مرادِه؛ فقد أساء"},{"id":3859,"era":"c11","t":"وقوع غلاء وموت بمدينة فاس .","s":"وقع غلاءٌ بفاس حتى بيع القمحُ بأوقيتين وربع للمُدِّ، وكثر الموتى حتى إن صاحب المارستان أحصى من الموتى أربعة آلاف وستمائة إنسان من عيد الأضحى إلى ربيع الأول من السنة التي بعدها، وخربت أطرافُ فاس وخلت المداشر- القرى أو المزارع- ولم يبقَ بلَمْطَةَ سوى الوحوشِ."},{"id":3860,"era":"c11","t":"معاهدة ستراتورك بين الدولة العثمانية والنمسا والمجر من جهة أخرى .","s":"عقدت الدولةُ العثمانيةُ صلحًا مع النمسا في هذا العام تخلصت فيه النمسا ممَّا كانت تدفعُه من جزيةٍ سنوية للعثمانيين، على أن تدفَعَ مائتي ألف دوكا دفعة واحدة، علمًا أن الجزية السنوية كانت تبلغ ثلاثين ألف دوكا! وذلك بعد الخلافِ على بلاد المجر ومحاولة النمسا إبعادَ أمير المجر عن العثمانيين وإغرائه ليكون ملكًا بمساعدة النمسا، وبقيت المجرُ بعد هذا الصلح تتبع الدولةَ العثمانية."},{"id":3861,"era":"c11","t":"استيلاء النصارى الأسبان على المعمورة المهدية .","s":"لما استولى النصارى الأسبان على العرائش، طمحت نفوسُهم إلى الاستيلاء على غيرها وتعزيزِها بأختها، فرأوا أنَّ المهديةَ أقربُ إليها، فبعث إليها الطاغية فيليبس الثالث من جزيرة قادس تسعين مركبًا حربية، فانتهوا إليها واستولوا عليها من غير قتال؛ لفرار المسلمين الذين كانوا بها عنها، وبعدها كتب أهل سلا إلى السلطان زيدان، فبعث إليهم أبا عبد الله العياشي الذي كان مقدمًا بوكالته على الجهاد بدكالة، وأمر أبو عبد "},{"id":3862,"era":"c11","t":"وفاة شيخ الإسلام عمر العرضي الحلبي .","s":"هو محدِّث حلب شيخ الإسلام عمر بن عبد الوهاب العرضي، أوحدُ وقته في فنون الحديث والفقه والأدب، أخذ عن محمود البيلوني، ورضي الدين الحنبلي، وبه تخرج، ومن أفخر أسانيدِه روايتُه عن والده عبد الوهاب عن زكرياء عن ابن حجر، ومن أعظم مؤلفاته \"شرح الشفاء\" في أربعة أسفار ضخامٍ، سماه \"فتح الغفار بما أكرم الله به نبيه المختار\" اشتغل به نحو اثنتي عشرة سنة، وله \"مناهج الوفا فيما تضمنه من الفوائد اسم المصطفى\"، وله "},{"id":3863,"era":"c11","t":"وفاة الإمام الحسن بن علي بن داود المؤيدي .","s":"هو الناصر لدين الله الإمام الحسن بن علي بن داود المؤيدي إمام الدولة الزيدية في اليمن. له تبحُّرٌ في علوم عديدة، كالنحو والصرف، والمنطق والمعاني والبيان، والأصول والتفسير، والفقه والحديث، وله رسائل تدلُّ على بلاغته وقوة تصرُّفه، دعا إلى نفسه سنة 984 في نصف شهر رمضان منها، فاجتمعت إليه الزيدية وأجابوا دعوتَه، وبايعوه في بلاد صعدة، وخرج منها بجيش إلى الأهنوم واشتعلت الأرض نارًا بقيامه على الأتراك، ود"},{"id":3864,"era":"c11","t":"وفاة السلطان العثماني أحمد الأول وتولي أخيه مصطفى الأول .","s":"هو السلطان أحمد الأول بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول. ولد في 12 جمادى الثانية سنة 998 (18 ابريل سنة 1590م) تولى السلطنة بعد أبيه ولم يتجاوز سنه الرابعة عشرة إلَّا بقليل, وقام بحجز أخيه مصطفى بين الخدم والجواري. كانت أركانُ الدولة في بداية حكمه غيرَ ثابتة، فنارُ الحرب مستعرة مع النمسا غربًا, ومع الصفويين شرقًا؛ حيث كانت الحرب معهم شديدة الوطأة؛ لتولي الشاه عباس الصفو"},{"id":3865,"era":"c11","t":"خلع السلطان العثماني مصطفى الأول وتولية ابن أخيه عثمان .","s":"لم تدُمْ أيام السلطان مصطفى الأول بن مراد الثالث كثيرًا؛ فقد خُلِع من السلطة بعد ثلاثة أشهر وثمانية أيام فقط؛ بدعوى أنَّه لا يعرف بأمورِ الحكم شيئًا، بحُكمِ أنَّه كان طول حياة أخيه أحمد محجوزًا عليه عند الجواري والخَدَم، وقيل: كان ذلك بتدبير فرنسا، ثمَّ تم تولية ابن أخيه عثمان بن أحمد الأول الذي كان ما يزال في الثالثة عشرة من عمره، فكان أول ما عمله أن أطلق سراحَ القنصل الفرنسي ومترجِمه، اللذين كان"},{"id":3866,"era":"c11","t":"انتصار الصفويين على العثمانيين في معركة بول شكسته .","s":"انتصر الصفويون على العثمانيين في معركة \"بول شكسته\"، وخسر العثمانيون في هذه المعركة 15 ألف قتيل."},{"id":3867,"era":"c11","t":"توقيع الدولة العثمانية معاهدة \"أردبيل\" مع إيران .","s":"وقَّعت الدولة العثمانية معاهدةَ أردبيل مع إيران، وقد خفضت هذه المعاهدة كمية الحرير التي كانت تقَدِّمُها إيران سنويًّا، كخراج للدولة العثمانية إلى نصف ما قررته معاهدة إستانبول الموقَّعة بين الدولتين!"},{"id":3868,"era":"c11","t":"ثورة محمد بن الشيخ المأمون السعدي المعروف بزغودة على أخيه .","s":"لما رأى أهل بلاد الهبط ما وقع من افتراق الكلمة وتوقُّد الفتن، بايعوا محمد بن الشيخ المعروف بزغودة، وكان الذي قام بدعوته الشريفَ أبا الحسن علي بن محمد بن علي بن عيسى بن عبد الرحمن الإدريسي المحمدي اليونسي المعروف بابن ريسون، وهي أم جدة علي نزيل تاصروت، وبايعوه على الكتاب والسنة، وعلى إحياء الحق وإماتة الباطل، فلما بلغ خبَرُه أخاه عبد الله، خرج لقتاله فالتقى الجمعان بوادي الطين واقتتلوا، فانهزم عبد "},{"id":3869,"era":"c11","t":"انتصار الجيش العثماني على جيش بولونيا .","s":"انتصر الجيشُ العثماني أيام عثمان الثاني الذي أعلن الجهادَ ضِدَّ بولونيا-بولندا- فأرسل جيشًا من الانكشارية بقيادة الوزير غازي إسكندر باشا، وتمكَّن العثمانيون من إبادة الجيش البولوني الذي كان يبلغ قوامُه ستين ألف جندي، ولم ينجُ من المعركة إلا أربعُمائة جندي بولوني فقط! وكان سبب المعركة هو تدخُّل بولونيا في شؤون إمارة البغدان من المجر. لكنْ حدَثَ الصُّلحُ بعد ذلك بناءً على رغبة بولونيا، وطلب الانكشار"},{"id":3870,"era":"c11","t":"الدولة العثمانية تعقد معاهدة \"خوتين\" مع بولونيا .","s":"وقَّعت الدولة العثمانية معاهدة \"خوتين\" مع بولونيا، واتَّفق الطرفان على الصلح بعد اشتعال الحرب بينهما، واتَّفقا على أن تقوم بولونيا بهدم جميعِ القلاع التي شيَّدتْها على حدود الدولة العثمانية، وأن تدفعَ ضريبةً سنويةً إلى القرم التي كانت تخضَعُ للدولة العثمانية, وأن تترك بولونيا قلعة \"خوتين\" الهامة للدولة العثمانية."},{"id":3871,"era":"c11","t":"وفاة الإمام العلامة زين الدين المناوي الشافعي .","s":"هو الإمامُ العلَّامة زين الدين محمد عبد الرؤوف بن تاج العارفين بن علي بن زين العابدين الحدادي المناوي القاهري، ولد سنة 952 بمنى، وهي قرية من قرى مصر. كان أعلَمَ معاصريه بالحديث وأكثَرَهم فيه تصنيفًا وإجادةً وتحريرًا، أخذ التفسير والحديث عن النور علي بن غانم المقدسي، والنجم الغيطي، والشمس الرملي، وأخذ التصوُّفَ عن جماعة، منهم الشيخ منصور الغيطي، والشعراني، وغيرهما. قال عبد الحي الكتاني: \"لم يخلُ من"},{"id":3872,"era":"c11","t":"خلع السلطان عثمان الثاني وقتله وإعادة عمه مصطفى الأول .","s":"هو الخليفةُ عثمان الثاني بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول بن بايزيد الثاني بن محمد الفاتح بن مراد الثاني بن محمد الأول جلبي بن بايزيد الأول بن مراد الأول بن أورخان غازي بن عثمان بن أرطغرل. وُلِد بإستانبول سنة 1013 ولَمَّا توفي والده أحمد الأول سنة 1026لم يرشِّحْه للخلافة لصِغرِ سِنِّه، ورشح أخاه مصطفى الأول، لكنه لم يلبث على سرير الملك إلا"},{"id":3873,"era":"c11","t":"خلع السلطان العثماني مصطفى الأول للمرة الثانية وتولية ابن أخيه .","s":"تولى السلطانُ مصطفى الحكمَ للمرة الثانية إثرَ فتنة الانكشارية، وصارت الحكومةُ ألعوبةً بأيديهم، ينصبون الوزراء ويعزلونهم بحسَبِ أهوائهم، وأصبحت المناصب تُباعُ جِهارًا، وارتكبوا أنواعَ المظالم، وتغير الوزراء الصدورُ في مدَّتِه هذه سبعَ مرَّات خلال عام واحد وأربعة شهور، وكان الخلافُ قد دبَّ بين أمراء الأناضول وفرقة السباهية- الخيالة- على استمرار الوزراء الصدور، حتى إن بعضهم لم يُكمِل شهرًا واحدًا، ون"},{"id":3874,"era":"c11","t":"ثورة أباظة باشا على الدولة العثمانية .","s":"أعلن والي أرضروم أباظة باشا العصيانَ مدَّعيًا أنه يريد الانتقام للمرحوم السلطان عثمان شهيد الانكشارية، فدخل سيواس وأنقرة، فسار إليه الصدرُ الأعظم حافظ باشا، وبعد معركة قيصرية قضى على هذه الثورة، ثم سار القائدُ حافظ باشا إلى بغداد غير أنَّ الانكشارية لم يستمروا معه في القتال، فعزل بسبب ذلك القائد حافظ باشا، فعاد أباظة باشا للثورة وأحرز نصرًا على الدولة العثمانية، فسار إليه خسرو باشا الصدر الأعظم ال"},{"id":3875,"era":"c11","t":"وفاة الفقيه مرعي الكرمي الحنبلي .","s":"هو الفقيه زين الدين مرعي بن يوسف بن أبي بكر بن أحمد الكرمي المقدسي الحنبلي، وهو كذلك مؤرِّخ وأديب، من أهل طولكرم قرب نابلس، درَّس في القدس والقاهرة، وعمل مدرسًا في الجامع الأزهر والمسجد الطولوني، كان من كبارِ فُقهاء الحنابلة، له سبعون مصنَّفًا، منها: أقاويل الثقات في تأويل الأسماء والصفات، والآيات والفوائد الموضوعة في الأحاديث الموضوعة، وتحقيق الخلاف في أصحاب الأعراف، وتوضيح البرهان في الفرق بين ا"},{"id":3876,"era":"c11","t":"الصفويون يحتلون بغداد .","s":"قام قائدُ الشرطة في بغداد بكير آغا بقتلِ الوالي وتسلَّم الأمرَ مكانه، فأرسلت له الدولةُ العثمانية قوةً بقيادة حافظ باشا، فحاصره في بغداد، فقام بالاتصال بالشاه عباس الصفوي، وعرض عليه تسليمَ المدينة فسار إليه, وفي الوقت نفسِه اتصل آغا بالقائد العثماني المحاصِر له وعرض عليه تسليمَ المدينة على أن يتسلَّم هو ولايتَها، فوافق القائد ودخلت جنودُه المدينة قبل وصول الشاه، ولَمَّا وصل الشاه وألقى الحصارَ علي"},{"id":3877,"era":"c11","t":"وفاة السلطان جهانكير بن أكبر شاه الكوركاني .","s":"هو السلطان نور الدين محمد جهانكير بن أكبر بن همايون بن بابر الكوركاني المغولي، من سلالة تيمورلنك سلطان الهند، ولِدَ في ربيع الأول سنة 977 بأكبر آباد، وتولى المملكة بعد والده يوم الخميس لأربع عشرة خلت من جمادى الآخرة سنة 1014، وكان اسمُه سليمًا، سماه به والده على اسم الشيخ سليم بن بهاء الدين السيكروي؛ لأن الشيخ بشَّر به والده قبل ولادته ودعا له، فلما استقلَّ بالملك لقَّب نفسَه نور الدين محمد جهانكي"},{"id":3878,"era":"c11","t":"وفاة الشاه عباس الأول الصفوي وتولي صفي بن صفي .","s":"هو الشاه الصفوي عباس الكبير الأول بن محمد خدابنده بن طهماسب بن إسماعيل الأول. ولد عباس في مدينة حيرات الواقعة في أفغانستان في 27/1/1571م. تولى حكم الدولة الصفوية سنة 996 بعد أن تمرد على والده ثم نحاه عن الحكم؛ لأنه لم يستطع ضبط الاضطرابات التي عمت البلاد بسبب ضعف شخصيته, ويعتبر عباس هو رابع حكام الدولة الصفوية ومن أقوى وأشرس حكامها, وقد أعاد لها قوتها كما كانت عليه في عهد إسماعيل الأول, فتمكن من س"},{"id":3879,"era":"c11","t":"وفاة السلطان زيدان بن أحمد السعدي وقيام ابنه عبد الملك .","s":"هو السلطان أبو المعالي زيدان بن أحمد المنصور الذهبي السعدي، زعيم الأشراف في المغرب الأقصى. كان في أيام أبيه مقيمًا بتادلا أميرًا عليها، تولى بعد وفاة والده المنصور سنة 1012حيث اجتمع أهل الحَل والعقد من أعيان فاس وكبرائها والجمهور من جيش المنصور على بيعة ولده زيدان، وقالوا إن المنصور استخلفه في حياته ومات في حجره، وكان المنصور قد عزل ابنه الكبير الشيخ المأمون وسجنه في مراكش لفساده وتمرده، فلما تمت "},{"id":3880,"era":"c11","t":"استيلاء الجيش العثماني على مدينة همدان .","s":"استولى الجيش العثماني بقيادة خسرو باشا على مدينة همدان، الواقعة على بعد 250 كم جنوب غرب طهران."},{"id":3881,"era":"c11","t":"بناء قصر تاج محل ليكون أشهر الرموز الإسلامية بالهند .","s":"تاج محل بالهند هو مَعلَم معماري هندي يقع في آكرا، يعتبر من أكبر الشواهد على الفنون والعمارة في العهد المغولي. شُيِّد الضريح تخليدًا لذكرى أرجونمد بانو باكام، والتي اشتهرت بلقب ممتاز محل، وكانت هي الزوجة المحظية لدى السلطان شاه جهانكير, والتي توفيت سنة 1631م أثناء إحدى الحملات العسكرية ويقع ضريحها بالقرب من ضريح زوجها الذي توفي سنة 1666م، وتطلَّب تشييد هذا المعلم عشرين عامًا وتجنيد أكثر من عشرين أل"},{"id":3882,"era":"c11","t":"السلطان العثماني مراد الرابع يقضي على ثورة الانكشارية .","s":"سيطر الجيشُ الانكشاري على السلطان مراد الرابع في أول أمره لصغره، ثم إنَّه لم يلبث أن عرف أمور الحكم حتى بدأ بالقضاء على طغاة العسكر الذين قتلوا أخاه السلطان عثمان الثاني، وأَعدم جميع المتأسِّدين في إستانبول وفي جميع أنحاء الدولة، وأسَّس تشيكلات قوية للمخابرات وثبَّت من خلالها أسماء جميع المستبدين في الدولة، وكان إذا صادف بلدًا في أسفاره يدعو مستبديها بأسمائهم ويعدمهم، ومنع في عهده الخمر والتدخين و"},{"id":3883,"era":"c11","t":"نشوب حريق هائل في إستانبول .","s":"نشب حريق هائل في إستانبول أدى إلى احتراق 20 ألف منزل، وقد نجم الحريق عن تدخين التبغ (السجائر)؛ مما دفع الدولة العثمانية إلى إصدار قرار بمنع التدخين حتى في المنزل، وقد رُفع الحظر عن التدخين عام 1640م."},{"id":3884,"era":"c11","t":"مقتل شيخ الإسلام زادة حسين أفندي .","s":"هو شيخ الإسلام أخي زادة حسين أفندي تولى منصب المشيخة الإسلامية على أيام السلطان مراد الرابع، ولد في إستانبول عام 980هـ، وبعد أن حصَّل العلم تولى قضاء إستانبول في عام 1014هـ، ثم أصبح قاضي عسكر الأناضول عام 1020هـ، ثم قاضي عسكر الروملي في سنة 1032ه، ثم تولى المشيخة الإسلامية في سنة 1041ه، وكان عالمًا له بعض تعليقات على كتب التدريس، ونظَم الشعر بمخلص هدايي، وأقام مدرسة في مواجهة داره، كما قام بتحويل "},{"id":3885,"era":"c11","t":"وفاة عبد الملك الثاني سلطان السعديين وقيام أخيه الوليد .","s":"هو السلطان أبو مروان عبد الملك الثاني بن زيدان بن أحمد المنصور الذهبي سلطان السعديين بالمغرب الأقصى، تولى الحكم بعد وفاة والده السلطان زيدان, ولما تمت له البيعة ثار عليه أخواه الوليد وأحمد، فوقعت بينه وبينهما معارك وحروب إلى أن هزمهما واستولى على ما كان بيدهما من العُدة والذخيرة وفَرَّ أحمد إلى بلاد الغرب، فدخل عبد الملك فاس يوم الجمعة الخامس والعشرين من صفر بعد وفاة أبيه بستة وأربعين يومًا، فاتَّ"},{"id":3886,"era":"c11","t":"منع الدولة العثمانية تناول المشروبات الكحولية .","s":"أصدر السلطان العثماني مراد الرابع أمرًا بمنع تناول المشروبات الكحولية في أرجاء الدولة العثمانية، وحظَر تناولها على المسلمين حتى في بيوتهم، وأُغلقت الحانات، وهَدَّدت الدولة العثمانية بإعدامِ كلِّ من يشرب الخمر في محلِّ ارتكاب الجريمة."},{"id":3887,"era":"c11","t":"معارك بين العثمانيين والزيدية في اليمن .","s":"بدأت المعارك بين العثمانيين والإمام المنصور القاسم بن محمد باليمن عام 1022هـ وانتصرت قوات الإمام وانسحب العثمانيون إلى صنعاء، ثم اضطر القائد جعفر باشا لعقد الصلح مع الإمام، واستمر عامًا واحدًا، ثم تجدد القتال حتى استطاع الإمام السيطرة على شمال اليمن عام 1029هـ ثم توفي من العام نفسه، وتولى ابنه المؤيد الذي استطاع أن يصل إلى أبواب صنعاء حيث جرت في هذا العام بينه وبين العثمانيين معركة اضطرت القائد ال"},{"id":3888,"era":"c11","t":"استقلال اليمن عن الخلافة العثمانية بعد جلاء قواتها عنها .","s":"بعد وفاة المطهر بن شرف الدين زعيم الجبهة الزيدية وقائد المقاومة عام 980هـ, انتهى دور آل شرف الدين لتعقبهم فترة تدهور للمقاومة ضد الأتراك، واستمر الوضع ربع قرن حتى ظهر الإمام القاسم بن محمد، قائدًا لثورة عارمة ضد العثمانيين، وأسس جيلًا جديدًا من الأئمة الزيدية واستمروا في حكم اليمن بين مد وجزر حتى زمن الثورة الجمهورية عام 1962م، وقد تميَّز تاريخ الفترة اللاحقة بالنضال الدؤوب من قبل اليمنيين جميعًا "},{"id":3889,"era":"c11","t":"العثمانيون يخمدون ثورة الأمير فخر الدين الثاني الدرزي في لبنان .","s":"كان السلطان عثمان الثاني قد عفا عن فخر الدين المعني الثاني وسمح له بالعودة إلى جبل لبنان، فبدأ من جديد بالتحرُّك للثورة والعصيان على الدولة العثمانية، فثار مرة أخرى في لبنان فنهض إليه والي دمشق وانتصر عليه وأسره وولديه وأرسلهم إلى إستانبول غير أن الخليفة مراد الرابع عاملهم بغاية الكرم رغم أنهم أكثر الناس خيانة باتصالهم الدائم بالصليبيين والطليان خاصة، وهذا ما شجَّع قرقماز حفيد فخر الدين بالتحرك وا"},{"id":3890,"era":"c11","t":"العثمانيون يفتحون مدينة تبريز .","s":"سار الخليفة مراد الرابع بنفسه إلى الصفويين وفتح بعض القلاع ثم انطلق إلى مدينة تبريز فدخلها عَنوة في هذا العام."},{"id":3891,"era":"c11","t":"وفاة السلطان الوليد بن زيدان ملك السعديين وتولي أخيه محمد .","s":"هو السلطان الوليد بن زيدان بن أحمد المنصور الذهبي ملك السعديين في المغرب الأقصى لما قُتل أخوه السلطان عبد الملك بن زيدان سنة 1044 بويع أخوه الوليد بن زيدان فلم يزل مقتصرًا على ما كان لأخيه وأبيه من قبله لم يجاوز سلطانه مراكش وأعمالها، وعظمت الفتن بفاس حتى عُطِّلت الجمعة والتراويح من جامع القرويين مدة ولم يصَلِّ به ليلةَ القدر إلا رجل واحد من شدة الهول والحروب التي كانت بين أهل المدينة؛ فقد اقتسم ا"},{"id":3892,"era":"c11","t":"استيلاء السلطان العثماني مراد الرابع على مدينة \"روان\" الإيرانية .","s":"عمل السلطان مراد الرابع على إعادة قوة الدولة العثمانية وعودة عمليات الفتح والتوسع كما كانت عليه في عهد سليمان القانوني، فقاد السلطان العثماني مراد الرابع حملة عسكرية بنفسه لغزو إيران حتى تمكن من الاستيلاء على مدينة \"روان\" الإيرانية، التي استسلمت بعد 11 يومًا من الحصار. وكان العثمانيون يسيطرون على المدينة منذ سنة 1583م حتى 1604م، ثم فقدوا السيطرة عليها 31 عامًا كانت فيها خاضعة لحكم الصفويين."},{"id":3893,"era":"c11","t":"قيام حرب بين أهل الأندلس واللمطيين .","s":"قامت حرب بين أهل الأندلس واللمطيين، وانتُهبت فيها السلع التي بسوق القيسارية- السوق الكبير- وسوق العطارين، وبنى اللمطيون الدرب الذي بباب العطارين، واستمرت الحرب نحو ثمانية أيام ثم اصطلحوا، وكان سببها مقتل أحمد ولد ابن الأشهب على يد علي بن سعد في جامع القرويين وهو في صلاة العصر، وذلك في رابع جمادى الأولى من هذه السنة."},{"id":3894,"era":"c11","t":"انتصار الإيرانيين على العثمانيين في معركة مهران .","s":"انتصر الإيرانيون على العثمانيين في معركة مهران، وقد قُتل في هذه المعركة الوزير العثماني كوجوك أحمد باشا، وقد أعاد الإيرانيون جسده إلى العثمانيين نظرًا لشجاعته في القتال."},{"id":3895,"era":"c11","t":"حرب العثمانيين مع الصفويين ودخول العثمانيين بغداد .","s":"اندلعت الحرب مع الشيعة الصفوية في العراق عام 1044هـ/1634م، فقاد السلطان مراد الرابع الجيوش بنفسه واتجه إلى بغداد، وكان عباس شاه فارس قد استولى عليها وقتل واليها العثماني وأذل أهل السنَّة بها وعمل بهم الأفاعيل، فحاصر السلطان مراد بغداد وهدم جزءًا كبيرًا من أسوارها بالمدفعية ودخلها, وقتل من جنود الشيعة عشرين ألفًا، ثم أقام بها مدة جدَّد عمارتها، وأصلح ما تهدم من أسوارها، وعين لها وزيرًا، وكان هذا ال"},{"id":3896,"era":"c11","t":"مقتل الصدر الأعظم طيار محمد باشا رئيس الوزراء بالدولة العثمانية .","s":"هو الصدر الأعظم طيار محمد باشا بن أوجار مصطفى باشا رئيس وزراء الدولة العثمانية. ولد في لاديك قرب البحر الأسود، وتولى الصدارةَ العظمى لفترة وجيزة في عهد السلطان مراد الرابع, لقِّب بالطيار لسرعته في العمليات الحربية. قُتل طيار محمد باشا أثناء حصار العثمانيين لبغداد التي استولى عليها الإيرانيون منذ عام 1624م. وكان طيار هو رابع رئيس وزراء عثماني يُقتَل في ساحة الحرب، وكان والده أوجار مصطفى باشا قد قُت"},{"id":3897,"era":"c11","t":"توقيع معاهدة صلح بين الدولة العثمانية والدولة الصفوية .","s":"تم توقيع معاهدة صلح بين الدولة العثمانية في عهد مراد الرابع والدولة الصفوية، وانقطعت بهذه المعاهدةِ كلُّ أسباب العداوة بين البلدين."},{"id":3898,"era":"c11","t":"وفاة السلطان العثماني مراد الرابع وتولي أخيه إبراهيم الأول .","s":"هو السلطان مراد الرابع بن أحمد بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول، هو السلطان العثماني السابع عشر، ولد بإستانبول سنة 1021 جلس للحكم بعد عمه باتفاق من الأركان على عزل عمه مصطفى الأول، يوم الأحد الرابع عشر ذي القعدة سنة 1032 وله من العمر أحد عشر عامًا، فبايعه الأعيان، ثم فرق إنعامات الجلوس عليهم, وقد عمل السلطان مراد على استعادة هيبة الدولة وقوتها، فتولى هو"},{"id":3899,"era":"c11","t":"السلطان العثماني إبراهيم الأول يسترد مدينة أزوف في بلاد القرم .","s":"افتتح السلطان إبراهيم الأول حروبه الخارجية بإرسال جيش جرار إلى بلاد القرم لمحاربة القوزاق الذين احتلوا مدينة آزوف (شمال البحر الأسود على بحر آزوف) فحاربهم العثمانيون وأبلَوا فيهم بلاء حسنًا واستردوا المدينةَ منهم بعد أن أحرقوها، وذلك سنة 1642."},{"id":3900,"era":"c11","t":"وفاة شيخ الإسلام يحيى بن بيرام مفتي الديار العثمانية .","s":"هو شيخ الإسلام يحيى بن زكريا بن بيرام مفتي الديار العثمانية في عصره. تركي الأصل، مستعرب. ولد سنة999 في إستانبول ونشأ بها. تولى قضاء الشام ثم نقل إلى قضاء مصر وعُزل، فولي قضاء بورصة، ثم قضاء أدرنة، ثم قضاء إستانبول, عُزل وولي مرارًا، وما زال يتنقل إلى أن توفي في الروم إيلي. وكان له في عصره شأن رفيع عند السلطان، جُمعت فتاواه في كتاب سُمِّي فتاوى يحيى، له نظم منه تخميس البردة."},{"id":3901,"era":"c11","t":"استعادة جزيرة كريت .","s":"كانت جمهورية البنادقة تهيمن على جزيرة كريت وعلى الحركة التجارية في بحر إيجة، مستغلين الصلح مع الدولة العثمانية، فعزم العثمانيون على تدمير نفوذ البنادقة في الشرق، فجُهِّزت الجيوش والأسطول وأُعلنت الحرب على البنادقة، واعتقل جميع البنادقة في طول البلاد وعرضها، وأُمر بمصادرة أموالهم وممتلكاتهم، ثم أمر السلطان إبراهيم بتجهيز عمارة بحرية قوية لفتح جزيرة كريت لأهمية موقعها الجغرافي الحربي عند مدخل بحر أر"},{"id":3902,"era":"c11","t":"غزو الشريف زيد بن محسن أمير مكة بلاد نجد .","s":"غزا الشريف زيد بن محسن أمير مكة بلاد نجد، ونزل روضة سدير، وقتل رئيسها: محمد بن ماضي، وولى عليها: رميزان بن غشام، من آل بوسعيد"},{"id":3903,"era":"c11","t":"انتصار الأسطول العثماني على البنادقة في معركة أيبسارا البحرية .","s":"انتصر الأسطول العثماني بقيادة المشير عمار زاده محمد باشا على البنادقة في معركة أيبسارا البحرية أثناء فتح العثمانيين لجزيرة كريت الواقعة في البحر المتوسط."},{"id":3904,"era":"c11","t":"خلع السلطان العثماني إبراهيم الأول وتولية ابنه محمد الرابع .","s":"أراد السلطان إبراهيم الأول أن يفتِكَ برؤوس الانكشارية المعارضين له، فعلموا بذلك فتآمروا على عزله وتولية ابنه الصغير محمد الذي لم يزِدْ عمره عن السابعة، فقاموا بخلعه بعد أن امتدَّ حكمه 8 سنوات و9 أشهر، ثم تمَّت تولية ابنه محمد الرابع، فلما أراد الخيَّالة السباهي أن يعيدوا السلطان المخلوع إبراهيم وعلمت الانكشارية بذلك، قتلوه, وقيل إن الذي عزله والدتُه السلطانة كوسم مهبيكر ثم تآمرت على قتله."},{"id":3905,"era":"c11","t":"انهيار النفوذ البرتغالي في مسقط على أيدي اليعاربة .","s":"انهار النفوذ البرتغالي في مسقط على أيدي اليعاربة؛ مما شجع العرب على العودة إلى سواحل الخليج العربي بعد أن انحسرت موجات هجرتهم خلال فترة الوجود العسكري البرتغالي، والتي استمرت نحو 190 عامًا، فكان انهيار النفوذ البرتغالي في الخليج دافعًا لاستئناف الهجرات القبلية نشاطها، والتي أسهمت بدورها في تأسيس الكيانات السياسية في الخليج العربي."},{"id":3906,"era":"c11","t":"مقتل السلطانة كوسم مهبيكر أشهر نساء الدولة العثمانية .","s":"السلطانة \"كوسم مهبيكر\" واسمها الحقيقي \"أناستاسيا\" وُلدت في اليونان، وقيل إنَّها ولدت في البوسنة عام 999هـ, وهي من أشهر النساء في التاريخ العثماني, قيل إنها أُرسلت من اليونان إلى إستانبول من قبل والي البوسنة، ولما دخلت أناستاسيا الإسلام غيَّرت اسمها لاسم \"كوسِم\". وسُميت باسم \"ماه بيكر\" بفضل حُب السلطان العثماني أحمد الأول لها، الذي تزوجها بعد أن أسلمت, وقد تولى اثنين من أبنائها السلطنة: مراد الرابع"},{"id":3907,"era":"c11","t":"تولي خديجة تارخان نيابة السلطنة في الدولة العثمانية .","s":"تولَّت خديجة تارخان نيابة السلطنة في الدولة العثمانية نيابةً عن ابنها الصغير محمد الرابع، وهي من أصل أوكراني، وكان عمرها آنذاك 24 عامًا، واستمرت نيابتها حتى سنة 1066، عندما صعد كوبريلي محمد باشا إلى رئاسة الوزارة. وقد توفيت خديجة عن عمر يناهز الـ 56 عامًا سنة 1683م."},{"id":3908,"era":"c11","t":"وفاة محمد الأصغر ملك السعديين وتولي أحمد الثاني .","s":"هو السلطان محمد الأصغر بن زيدان ابن المنصور أحمد الذهبي ملك السعديين في المغرب الأقصى, ويلقَّب بالشيخ. لما قتل السلطان الوليد سنة 1045 اختلف الناس فيمن يقدمونه للولاية عليهم، ثم أجمع رأيُهم على مبايعة أخيه محمد الشيخ وإلقاء القيادة إليه، فأخرجوه من السجن، وكان أخوه الوليد قد سجنه إذ كان يتخوَّف منه الخروج عليه، فبويع بمراكش يوم الجمعة الخامس عشر من رمضان سنة 1045 ولما بويع سار في الناس سيرةً حميدة"},{"id":3909,"era":"c11","t":"ثورة قاطرجي أوغلي في الأناضول ضد العثمانيين .","s":"قامت ثورة في الأناضول بزعامة قاطرجي أوغلي، ودعمه كورجي يني؛ اللذان انتصرا على والي الأناضول أحمد باشا، ثم توجَّها نحو إستانبول، ولكنهما اختلفا فسلمت العاصمة منهما؛ لاختلافهما، وانتصر عليهما السلطان محمد الرابع لذلك الخلاف، فقتل كورجي يني، وطلب قاطرجي أوغلي العفو، وتسلَّم ولاية القرمان، ورغم انتهاء الثورة لم تتحسن أوضاع الدولة الداخلية ولا الخارجية."},{"id":3910,"era":"c11","t":"تولي كوبريلي محمد باشا رئاسة الوزراء في الدولة العثمانية .","s":"تولى كوبريلي محمد باشا رئاسة الوزراء في الدولة العثمانية، الذي حاول انتشال الدولة من حالة التدهور، فتسلم مقاليد أمور الدولة من نائبة السلطنة خديجة تارخان، واستمر دور عائلة \"كوبريلي\" في الدولة مدة 27 عامًا حتى عام 1683م. واستطاعت هذه الأسرة أن تُنقذ الدولة العثمانية بفضل الله تعالى من أزمات كبيرة كادت تعصف بها. واستمرت رئاسة \"كوبريلي\" للوزراء حتى أكتوبر 1661م."},{"id":3911,"era":"c11","t":"وفاة المؤرخ التركي حاجي خليفة .","s":"هو المؤرِّخ التركي مصطفى بن عبد الله الحلبي المعروف بحاجي خليفة، ولد سنة 1017هـ / 1608م، وحفظ القرآن، ودَرس العربية والفقه والحساب، واهتم بالتاريخ والجغرافيا. وأبوه من رجال الجند، استُخدم كاتبًا في نظارة الجيش بالأناضول حتى أصبح رئيس الكُتاب، ثم عاد إلى الآستانة وتفرغ للعلم ولقب خليفة منذ كان بالآستانة، اشتهر بمؤلَّفه النافع: كشف الظنون عن أسامي الكتب والفنون، الذي يحوي على 14500 اسم كتاب، ويعتبر "},{"id":3912,"era":"c11","t":"ثورة المسلمين الأندلسيين الثانية في أسبانيا .","s":"بدأت اضطرابات محدودة من قِبَل المسلمين في جبل البشرات تمكَّن جنود مركيز مندخار (الحاكم العسكري) من إنهائها بسرعة, ومكَّن الهدوء النسبي الذي لحق ذلك بدء انتقال أعداد من شبان مدينة غرناطة إلى الجبال سرًّا للتدرُّب على استخدام السلاح. وفي الثالث والعشرين من ديسمبر اعتقد الثوارُ أن عددهم كان كافيًا للقيام بالخطوة التالية فشنُّوا هجومًا مباغتًا على مدينة غرناطة فيما كانت حاميتها تستعد للاحتفال بعيد الم"},{"id":3913,"era":"c11","t":"طرد البرتغاليين من مسقط وعُمان .","s":"بدأت الثورةُ في الخليج العربي عمومًا وفي هرمز خصوصًا ضد البرتغاليين من بداية القرن العاشر الهجري، واستمرت بين مد وجزر حتى كانت النهاية في طرد البرتغاليين من مسقط وعمان، وكان الأثر الأكبر في ذلك هو تنامي قوة العرب العمانيين من أسرة اليعاربة التي قُدِّر لها أن تحسم الصراع لصالح العرب وتقضي على الإمبراطورية البرتغالية، وبرزت وحدة الشعب العماني في عهد هذه الأسرة التي نمت وترعرعت بسبب وجود المستعمر الب"},{"id":3914,"era":"c11","t":"وفاة السلطان أحمد بن عبد الملك ملك السعديين بالمغرب .","s":"هو السلطان أحمد العباس بن أبي مروان عبد الملك، ملك السعديين في المغرب الأقصى، قتله أخوه، ويعتبر هو آخر الملوك السعديين فرع الحسنيين، وكان من أسباب نهاية هذا الفرع من السعديين الأشراف تنافس الأمراء على الحكم والاستعانة بخصوم الدولة سواء الأسبان والبرتغال أو الأتراك. وبدأت بعد عهد الأشراف دولة العلويين في مراكش بزعامة الرشيد بن محمد."},{"id":3915,"era":"c11","t":"تعيين العثمانيين مدينة بوخارست عاصمة لرومانيا .","s":"عين السلطان العثماني محمد الرابع مدينة بوخارست كعاصمة لرومانيا، وأصبحت بوخارست منذ ذلك التاريخ هي العاصمةَ الرومانية."},{"id":3916,"era":"c11","t":"استيلاء القائد العثماني كوسه على قلعة فيرتا الألمانية .","s":"تمكَّن القائد العثماني البحري كوسه علي باشا من الاستيلاء على قلعة فيرتا الألمانية بعد حصار دام 45 يومًا، وغنم العثمانيون 700 مدفع من القلعة."},{"id":3917,"era":"c11","t":"البرتغال تتخلى عن طنجة للإنجليز  .","s":"كان البرتغاليون يحتلون طنجة قرنين من الزمان، ثم إن الأميرة كاترينا البرتغالية قدَّمت طنجة صداقًا لزوجها تشارلز الثاني ملك إنكلترا، فأصبحت طنجة تحت النفوذ الإنكليزي."},{"id":3918,"era":"c11","t":"وفاة الصدر الأعظم كوبريلي محمد علي باشا .","s":"هو الصدر الأعظم محمد علي باشا كوبريلي، وهو أشهر رئيس وزراء للدولة العثمانية في أدرنة, وعلى الرغم من كبر سنه كان قوي الشخصية والإرادة، عظيم الهمة، يميل إلى الشدة والترهيب فيما يتصل بأمن الدولة وسلطانها، فانتظمت أمور الدولة الداخلية، وضرب على أيدي الانكشارية وأعادهم إلى احترام النظام والانشغال بعملهم، ومنعهم من التدخل فيما لا يعنيهم من شؤون السياسة. وفي الوقت نفسه حقق للدولة بعض الانتصارات الخارجية،"},{"id":3919,"era":"c11","t":"تراجع قوة الدولة العثمانية أمام دول الغرب .","s":"بوفاة الصدر الأعظم \"أحمد كوبريلي\" العام الماضي ضعف النظام العثماني، وتمكنت دول أوربا خلال السنوات القادمة من تحقيق انتصارات على الدولة العثمانية, فهاجمت النمسا بلاد المجر، واغتصبت قلعة نوهزل ومدينة بست ومدينة بودا، وأغار ملك بولونيا على ولاية البغدان، وأغارت سفن البندقية على سواحل المورة واليونان، واحتلت أثينا وكورنثة عام 1097هـ وغيرها من المدن. وتذكر كتب التاريخ أن العلماء ورجال الدولة بسبب هذا ا"},{"id":3920,"era":"c11","t":"إعلان الدولة العثمانية الحرب على ألمانيا .","s":"أعلنت الدولة العثمانية الحرب على ألمانيا بعد 56 عامًا من معاهدة سيتفاتوروك التي أوقفت الحرب السابقة بين الجانبين، وكان سبب الحرب هذه المرة هو بناء الألمان قلعة حصينة على الحدود مع الدولة العثمانية."},{"id":3921,"era":"c11","t":"العثمانيون يحصارون قلعة نوهزل النمساوية والاستيلاء عليها .","s":"كان الصدر الأعظم محمد كوبريلي الذي توفي عام 1072هـ أعاد للدولة العثمانية هيبتها، ولما خلفه ابنه أحمد سار سيرةَ أبيه، فرفض الصلحَ مع النمسا والبندقية وسار على رأس جيش لقتال النمسا، وتمكن من أن يفتح أعظم قلعة في النمسا وهي قلعة نوهزل شرقي فيينا، ومع أن هذه القلعة كانت مشهورة في جميع أوروبا بالمناعة وعدم إمكان أي أحد التغلب عليها وفتحها، فقد اضطر كوبريلي أحمد باشا حاميتَها إلى التسليم بشرط خروج من به"},{"id":3922,"era":"c11","t":"استيلاء العثمانيين على قلعة \"أويفار\" الخاضعة للألمان .","s":"تمكن العثمانيون من الاستيلاء على قلعة \"أويفار\" الواقعة شمال غرب بودابست بعد 37 يومًا من الحصار. وقد كانت القلعة خاضعة للألمان، وتعدُّ أقوى وأحصن قلاع أوربا، وكان الاستيلاء عليها فاتحةً لاستسلام 30 قلعة ألمانية للدولة العثمانية!"},{"id":3923,"era":"c11","t":"استيلاء العثمانيين على قلعة \"يني قلعة\" .","s":"تمكن العثمانيون من الاستيلاء على قلعة \"يني قلعة\" الحصينة داخل الحدود الألمانية، والتي تسبب تشييدها في نشوب الحرب بين الجانبين في إبريل 1663م."},{"id":3924,"era":"c11","t":"استمرار حكم العلويين الأشراف في المغرب بعد السعديين .","s":"كان وجود الأشراف في المغرب قديمًا, لكن لم يتسنَّ لهم تسلم القيادة إلا في هذه الفترة التي مثَّل الشرفاء فيها سلالة السعديين، والتي جاءت من الجزيرة العربية أواخر القرن الثامن الهجري، وأول من وصل العرش منهم هو محمد المهدي القائم بأمر الله بن عبد الرحمن بن علي، وهو الذي أخرج الوطاسيين نهائيًّا من فاس، ومن جهة أخرى لم تنقطع الهجمات الصليبية من البرتغال والأسبان على السواحل، ومع ذلك استطاع السعديون الحس"},{"id":3925,"era":"c11","t":"واقعة سان جوتار وعقد صلح مع النمسا .","s":"بعد استيلاء العثمانيين على قلعة نوهزل النمساوية، وسَّطَ ليوبولد إمبراطورُ النمسا البابا إسكندرَ السابِعَ في طلبه المساعدة له من ملك فرنسا- الذي كان قد عرض على ليوبولد قبل حصار العثمانيين لقلعة نوهزل إمدادَه بأربعين ألفًا من الألمان المحالفين له، فأبى خوفًا من إظهار الضعف- فسعى البابا جهدَه لدى ملك فرنسا حتى قَبِلَ بإرساله ستة آلاف جندي فرنساوي وأربعة وعشرين ألفًا من محالفيه الألمان، وانضم هذا الجي"},{"id":3926,"era":"c11","t":"وقوع اشتباك بين الجيش الألماني ومقدمة الجيش العثماني .","s":"اشتبك الجيش الألماني المكون من 60 ألف جندي مع مقدمة الجيش العثماني المكونة من 10 آلاف جندي، وتمكن من إفنائها في حربٍ غير متكافئة بعد سبع ساعات من القتال قُتِلَ خلالها 10 آلاف ألماني!"},{"id":3927,"era":"c11","t":"عودة الجيش العثماني إلى أدرنة لقتال الألمان .","s":"عاد الجيش العثماني بقيادة رئيس الوزراء فاضل أحمد باشا إلى أدرنة بعد مغادرتها لمدة سنة و3 أشهر لقتال ألمانيا؛ حيث انتهت الحرب بين الجانبين بتوقيع معاهدة \"فاشفار\" على بعد 3 كم عن النمسا."},{"id":3928,"era":"c11","t":"تولي \"كوبريلي فاضل باشا\" قيادة الحملة العثمانية لفتح جزيرة كريت .","s":"تولى رئيس الوزراء \" كوبريلي فاضل أحمد باشا\" قيادة الحملة العثمانية لفتح جزيرة كريت، وقد استمر \"فاضل\" في الجزيرة طيلة 3 سنوات ونصف سنة حتى تم فتح كريت."},{"id":3929,"era":"c11","t":"رفع رئيس الوزراء فاضل أحمد باشا الحصار عن \"قلعة كاندية\" .","s":"يعتبر حصار قلعة كاندية المنيعة في جزيرة كريت أطول حصار في التاريخ، كان العثمانيون قد قضوا سنة 1055 ثلاثة أشهر لفرض الحصار على مدينة كاندية، بقطع إمدادات المياه، وتعطيل الممرات البحرية البندقية إلى المدينة، وقاموا بقصف المدينة دون تأثير يذكر. البنادقة بدورهم حاصروا الدردنيل لمنع وصول الإمدادات العثمانية لجزيرة تكريت, وتلقَّت جمهورية البندقية المزيدَ من المساعدات من الدول الأوروبية الغربية الأخرى خل"},{"id":3930,"era":"c11","t":"وفاة الشيخ سليمان التميمي جد الشيخ محمد بن عبد الوهاب .","s":"هو العلَّامةُ الفقيهُ الشيخ أبو محمد سليمان بن علي بن محمد بن أحمد بن راشد بن بريد بن مشرف الوهيبي الحنظلي التميمي، جَدُّ الإمام المجدِّد محمد بن عبد الوهاب, وعالمُ الدِّيار النجدية في عصره ومُفتيها. قيل إنه وُلد في بلدة أشيقر ونشأ فيها وقرأ على علمائها, واشتهر بالورع والتواضع وغمط النفس, والعدل في أقضيته، وكان قويًّا في الحق، لا تأخذه في الله لومة لائم، وبعد أن برز وبرع في العلم واشتهر، طَلَبَه أ"},{"id":3931,"era":"c11","t":"عقد الدولة العثمانية معاهدة مع البندقية .","s":"وقعت الدولة العثمانية معاهدة من 18 مادة تم بمقتضاها انتقال قلعة \"كاندية\" الحصينة في جزيرة كريت إلى الدولة العثمانية، إضافة إلى 1100 مدفع كانوا في القلعة، وأن تحصل تركيا على كامل جزيرة كريت، وبذلك تنتهي الحرب العثمانية مع البندقية التي استمرت 24 عامًا."},{"id":3932,"era":"c11","t":"قيام حكم البايات في الجزائر كما حصل من قبل في تونس .","s":"كان النظامُ في الدولة العثمانية في هذه الولايات التابعة لها أن يكون هناك والٍ عثماني هو الباشا، يحكم تلك الولايةَ ويكون تحته أعوانٌ ويكون التصرفُ للباشا، ثم تغيَّرَ الوضع فأصبح نظامُ الباي، وذلك أن الرجل الذي يكون واليًا ممثلًا للخليفة في هذه الولاية هو الباي (بيلرباي) وليس شرطًا أن يكون عثمانيًّا، ويساعده ديوانٌ استشاريٌّ مؤلَّفٌ من  عسكريين يمثِّلون الفِرَق العسكرية في الولاية، ويلقَّبُ كل منهم "},{"id":3933,"era":"c11","t":"غزو براك بن غرير زعيم بني خالد بلاد نجد .","s":"غزا براك بن غرير زعيم بني خالد بلاد نجد من مركزه في الأحساء، واستمرت حملاته عليها لفترة؛ مما أدى إلى تزايد نفوذه والتضييق على العثمانيين ونفوذهم بالمنطقة."},{"id":3934,"era":"c11","t":"وفاة الملك أبو العز الرشيد ملك العلويين بالمغرب وتولي أخيه إسماعيل .","s":"هو الملك أبو العز الرشيد بن محمد بن علي الحسني أول ملوك شرفاء مراكش من العلويين، وكان قد قاتل أخاه محمدًا الذي كان قد تسلم بعد وفاة أبيهما عام 1069هـ وكانت قاعدتهم سجلماسة، فلما أصبح الأمر للرشيد نقل العاصمة إلى مراكش؛ ولهذا عُدَّ هو أولَ ملوك العلويين في مراكش وتولى أخوه إسماعيل الملك خلفًا له."},{"id":3935,"era":"c11","t":"محاولة فرنسا تجديد الامتيازات في الدولة العثمانية .","s":"حاولت فرنسا التقرب من الدولة العثمانية، وتجديد الامتيازات، غيرَ أن الصدر الأعظم رفض ذلك، ثم حاولت فرنسا التهديدَ؛ حيث أرسل \"لويس الرابع عشر\" ملك فرنسا السفيرَ الفرنسي مع أسطول حربي، وهذا ما زاد الصدر الأعظم إلا ثباتًا، وقال: إن الامتيازات كانت منحة، وليست معاهدة واجبة التنفيذ, فتراجعت فرنسا أمام تلك الإرادة الحديدية واستعملت سياسة اللين والخضوع للدولة العثمانية، حتى جددت لها المعاهدات القديمة وأعا"},{"id":3936,"era":"c11","t":"قيام الحرب بين الدولة العثمانية وبولندا وتوقيع معاهدة بين الطرفين .","s":"رغب القوزاق في التبعية إلى الدولة العثمانية فأعلنوا ذلك، وكانوا يقيمون في أوكرانيا والمناطق التي تقع إلى الشرق منها، وهذا ما أغضب بولونيا فأغارت على أوكرانيا التي طلبت النجدة من العثمانيين، وسار الخليفة محمد الرابع بنفسه على رأس جيش انتصر على البولونيين الذين طلبوا الصلح، فعقد ولم يمضِ على الحرب أكثر من شهر واحد، وقد اعترفت بولونيا فيه بأن أوكرانيا للقوزاق وأن إقليم بووليا في غرب أوكرانيا للدولة ا"},{"id":3937,"era":"c11","t":"السلطان محمد الرابع يبدأ حملته السلطانية الأولى على بولونيا .","s":"بدأ السلطان محمد الرابع حملته الهمايونية السلطانية الأولى على بولونيا- بولندا-والتي استمرت 6 أشهر، تم خلالها افتتاح عدد من القلاع، وانتهت الحملة بتوقيع معاهدة بين الطرفين دفعت خلالها بولونيا ضريبة سنوية للعثمانيين."},{"id":3938,"era":"c11","t":"استيلاء الجيش العثماني على قلعة كاماينجو البولونية .","s":"استطاع الجيش العثماني الاستيلاء على قلعة كاماينجو البولونية الحصينة الواقعة على نهر تورلا، بعد 9 أيام من الحصار."},{"id":3939,"era":"c11","t":"فتح القائد العثماني قبلان مصطفى باشا منطقة بودوليا .","s":"استطاع القائد العثماني قبلان مصطفى باشا أن يفتح منطقة بودوليا، ويؤسِّس فيها إيالة \"كامانيجة\"، وكانت هذه المنطقة تابعة لبولونيا، لكنها تقع الآن في جمهورية أوكرانيا. وقد استمرت السيطرة العثمانية عليها حتى نوفمبر 1180م."},{"id":3940,"era":"c11","t":"إعلان الدول الأوربية الحرب على الدولة العثمانية .","s":"أعلنت الدول الأوربية الحربَ على الدولة العثمانية، واستمرَّت هذه الحرب حتى عام 1686م، وعُرفت هذه السنوات في التاريخ العثماني بسنوات المصيبة, وكان هدف هذه الحملات هو إخراج المسلمين الأتراك من أوربا إلى آسيا, وأطلق البابا على هذه الحرب \"الحملة الصليبية الـ14 ضد الأتراك\"."},{"id":3941,"era":"c11","t":"تغلب الجيشِ البولوني على الجيش العثماني واستيلاؤه على خوتين .","s":"تمكن الجيش البولوني بقيادة \"سوبياسكي\" والمكون من 80 ألف جندي من الاستيلاء على خوتين الواقعة على نهر تورلا من العثمانيين بعد هزيمة الجيش العثماني المكون من 30 ألف جندي في معركة استمرت 3 ساعات."},{"id":3942,"era":"c11","t":"المعاهدة النهائية للامتيازات بين الدولة العثمانية وإنجلترا  .","s":"عقد السلطان محمد الرابع معاهدة جدَّد فيها الامتيازات التجارية الممنوحة لدولة إنكلترا وأضيف إليها بنود أخرى، وأطلق عليها اسم المعاهدة النهائية للامتيازات بين الإمبراطورية العثمانية وإنكلترا، وتُمثل هذه المعاهدة المرحلة الثانية في تاريخ الامتيازات في نَيل التاجر البريطاني حريةَ التجارة داخل البلاد العثمانية والتمتع بما يكفي حماية نفسه وماله."},{"id":3943,"era":"c11","t":"وفاة الصدر الأعظم العثماني زاده فاضل أحمد باشا كوبريلي  .","s":"هو الصدر الأعظم زاده فاضل أحمد باشا ابن الصدر الأعظم محمد علي باشا كوبريلي رئيس الوزراء، وأحد رجالات الدولة العثمانية الكبار في القرن الحادي عشر الهجري، وأصغر من تولى رئاسة الوزراء في تاريخ الدولة العثمانية. توفي عن إحدى وأربعين سنة قضى منها خمس عشرة سنة في منصب الصدارة العظمى بكل أمانة وصدق سائرًا في ذلك على خطة والده محمد علي باشا, وتقلد منصب الصدارة بعده زوج أخته قرة مصطفى باشا، ولم يكن كفؤًا ل"},{"id":3944,"era":"c11","t":"وفاة الشيخ المحدث علاء الدين الحصكفي مفتي الحنفية في دمشق .","s":"هو الشيخ المحدث محمد بن علي بن محمد الحصني، المعروف بعلاء الدين الحصكفي، الكثير الحفظ والمرويات، مفتي الحنفية في دمشق. مولدُه في دمشق سنة 1025. كان فاضلًا عالي الهمة، عاكفًا على التدريس والإفادة. من كتبه الدر المختار في شرح تنوير الأبصار في فقه الحنفية، وإفاضة الأنوار على أصول المنار في الفقه، والدر المنتقى شرح ملتقى الأبحر في الفقه، وشرح قطر الندى في النحو، وله تعليق على صحيح البخاري في مجلد. توف"},{"id":3945,"era":"c11","t":"رفع القائد العثماني شيطان إبراهيم باشا الحصار عن قلعة جهرين .","s":"رفع القائد العثماني شيطان إبراهيم باشا الحصار عن قلعة جهرين في أوكرانيا، وذلك بسبب المقاومة الكبيرة التي أبداها 60 ألف جندي روسي وأوكراني."},{"id":3946,"era":"c11","t":"وفاة ابن العماد الحنبلي .","s":"هو الشيخ أبو الفلاح عبد الحي بن أحمد بن العماد العكبري، مؤرخ وفقيه حنبلي وعالم بالأدب، ولد في دمشق سنة 1032 ونشأ بها، وقرأ القرآن الكريم على بعض الشيوخ، وطلب العلم مشمِّرًا عن ساعد الجد والاجتهاد، فأخذ عن أعلام الأشياخ، وأجلُّهم الشيخ أيوب الخلْوَتي الصوفي. وتلقى الفقهَ قراءة وأخذًا عن ابن فقيه فُصَّة مفتي الحنابلة بالشام في عصره، ثم رحل إلى القاهرة وأقام بها مدة طويلة، فأخذ العلم عن أشياخها. ثم ع"},{"id":3947,"era":"c11","t":"بدءُ السلطان العثماني محمد الرابع حملته السلطانية الأولى على روسيا .","s":"بدأ السلطان العثماني محمد الرابع حملته السلطانية الأولى على روسيا، وكانت تلك الحملة الأولى لسلطان عثماني على روسيا، حيث كان يقوم بهذه المهمة في السابق خان القرم."},{"id":3948,"era":"c11","t":"استيلاء الجيش العثماني على قلعة \"جهرين\" .","s":"تمكَّن الجيش العثماني من الاستيلاء على قلعة جهرين في أوكرانيا بعد حصار دام 32 يومًا، قتل خلاله 20 ألف جندي روسي وأوكراني."},{"id":3949,"era":"c11","t":"بدء السلطان العثماني محمد الرابع حملته السلطانية الثانية على روسيا .","s":"بدأ السلطان العثماني محمد الرابع حملته السلطانية الثانية على روسيا، وقد انتهت هذه الحملة بعقد صلح بين العثمانيين والروس."},{"id":3950,"era":"c11","t":"قتال بين الروس والعثمانيين انتهى بمعاهدة رادزين .","s":"بعد أن توفي الصدر الأعظم أحمد كوبريلي عام 1087هـ خلفه في الصدارة صهره قرة مصطفى، ولم يكن بكفاءة أحمد كوبريلي ووالده محمد باشا, فأثار القوزاق الذين استنجدوا بروسيا فوقعت الحرب بين الطرفين عام 1088هـ واستمرت حتى عام 1092هـ حتى عقدت معاهدة أنهت الحرب وبقيت الأمور كما كانت قبل الحرب، ولكن أصبح القوزاق أميلَ إلى أعدائهم الروس منهم إلى العثمانيين إخوانهم في السابق، وتمت المعاهدة المعروفة باسم معاهدة راد"},{"id":3951,"era":"c11","t":"وفاة السلطانة خديجة تارخان .","s":"هي السلطانة خديجة تارخان نائبة السلطنة في الدولة العثمانية، والتي تولت النيابة سنة 1651م؛ لصغر عمر ولدها السلطان محمد الرابع واستمرت في النيابة حتى عام 1656م. وخديجة من أصل أوكراني، وتوفيت عن 56 عامًا، وقد حازت أطول مدة لامرأة تحصل على صفة \"السلطانة - الوالدة\"، في التاريخ العثماني، حيث استمرت هذه الصفة لصيقة بها لمدة 34 عامًا."},{"id":3952,"era":"c11","t":"إعلان الدولة العثمانية الحرب على ألمانيا .","s":"قامت الدولة العثمانية بإعلان الحرب على ألمانيا بعد 18 عامًا على صلح \"فاشفار\" الذي وقعه الجانبان."},{"id":3953,"era":"c11","t":"استيلاء القائد العثماني أوزون إبراهيم باشا على \"قلعة فولك\" .","s":"تمكن القائد العثماني أوزون إبراهيم باشا من الاستيلاء على \"قلعة فولك\" الحصينة في سلوفاكيا إضافة إلى 28 قلعة أخرى بالمنطقة، وقد استطاع هذا القائد تحقيق السيطرة الكاملة على سلوفاكيا."},{"id":3954,"era":"c11","t":"حصار الدولة العثمانية لفيينا عاصمة النمسا .","s":"كان الصدر الأعظم قرة مصطفى قد سار عام 1092هـ لمحاربة النمسا بطلب من سكان الأقسام المجرية التي تخضع للنمسا بسبب استبداد النمسا المذهبي، وانتصر الصدر الأعظم في عدة معارك، ثم سار نحو فيينا وألقى عليها الحصار مدة شهرين من هذا العام, كان فتح فيينا يمثِّل حلمًا طالما راود سلاطينَ العثمانيين؛ لِما تمثِّلُه فيينا من أهمية استراتيجية للسيطرة على خطوط التجارة والمواصلات في القلب الأوروبي. فالسلطان سليمان ال"},{"id":3955,"era":"c11","t":"طرد الفرنسيين من الجزائر .","s":"عندما شنَّ الفرنسيون حملة صليبية كبيرة هدفها احتلال الجزائر في هذه السنة اضطر الداي بابا حسن إلى التفاوض معهم على أن يدفع لهم جزية كبيرة ويطلق جميع الأسرى الفرنسيين في الجزائر، لكن هذا الرضوخ من الداي لم يعجب طائفة رياس البحر وزعيمهم حسين ميزو مورتو الذين عبروا عن سخطهم بقتل الداي بابا حسن وتعيين حسين ميزو مورتو دايا مكانه، وبعد توليه الحكم أرسل خطابًا شديد اللهجة إلى قائد الحملة الفرنسية دوكين ين"},{"id":3956,"era":"c11","t":"وقعت الدولة العثمانية معاهدة إستانبول مع البندقية .","s":"وقعت الدولة العثمانية معاهدة إستانبول مع البندقية. وبمقتضى هذه المعاهدة فُرض على البندقية تسديد غرامة قدرها ربع مليون قطعة ذهبية للدولة العثمانية."},{"id":3957,"era":"c11","t":"فتح القائد العثماني حسين باشا براتسلافا الألمانية .","s":"استطاع القائد العثماني حسين باشا أن يفتح براتسلافا الألمانية، وأن يغنم منها تاج إمبراطور ألمانيا، والذي كان موجودًا فيها."},{"id":3958,"era":"c11","t":"هزيمة الجيش العثماني في معركة \"ألمان داغي\" .","s":"تعرض الجيش العثماني لهزيمة قاسية في معركة \"ألمان داغي\" أثناء حصاره لفيينا للمرة الثالثة، فعندما تداعت الدول الأوروبية بأقصى سرعة لنجدة فيينا من السقوط، وأعلن بابا روما الحرب الصليبية على العثمانيين، وأمر ملك بولندا سوبيسكي بنقض عهده مع العثمانيين، وأمر أيضًا أمراء ساكسونيا وبافاريا الألمان، وهم أقرب أمراء أوربا بالتوجه إلى فيينا بأقصى سرعة ممكنة، وكان قرة مصطفى قد وضع قوة عثمانية كبيرة يقودها أمير"},{"id":3959,"era":"c11","t":"انتصار الجيش العثماني على الجيش البولوني في معركة \"جكردلن\" .","s":"انتصر الجيش العثماني بقيادة محمد باشا على خصمه الجيش البولوني بقيادة الملك سوبياسكي في معركة \"جكردلن\"، وقتل من البولونيين في هذه المعركة 10 آلاف جندي."},{"id":3960,"era":"c11","t":"استيلاء الجيش البولوني والقوات الأوربية على قلعة \"إستركون\" .","s":"تمكن الجيش البولوني وعدد من القوات من أوربا من الاستيلاء على قلعة \"إستركون\" التابعة للدولة العثمانية بعد 22 يومًا من الحصار. وكانت هذه القلعة من أهم القلاع العثمانية في أوربا، والتي استمرت سيطرة العثمانيين عليها 128 عامًا."},{"id":3961,"era":"c11","t":"العثمانيون يفتحون (بودوليا) في بولندا و(فيينا) في النمسا .","s":"عندما حاول أمير ترانسلفانيا جورج راغوجي عدم الوفاء بالتزاماته المالية عزله العثمانيون وولوا مكانه ميخائيل أبافي، فكان هذا سببًا في قيام حرب تزعَّمها المجريون، ثم انضم لهم جماعة من الأوربيين في حرب صليبية كان العثمانيون لها بالمرصاد حتى وصلوا إلى حدود النمسا، ثم أحرز العثمانيون النصر عليهم، ثم حصلت حرب بين السويد وبولونيا (بولندا) فاستنجد ملك السويد بالعثمانيين على أن تصبح بولونيا تحت نفوذهم، فاتجه"},{"id":3962,"era":"c11","t":"بريطانيا تتخلى عن طنجة لسلطان مراكش .","s":"كانت طنجة مُستعمَرة من قبل البرتغاليين وبقيت تحتهم قرنين من الزمن ثم تنازلت الأميرة البرتغالية عنه لملك إنكلترا، فأصبحت تحت السيطرة البريطانية إلى أن قام إسماعيل السعدي ملك العلويين في مراكش بمحاصرة ثغر طنجة، واستمر الأمر ست سنوات إلى أن انتزعه في هذا العام من البريطانيين، وكان من أهم الثغور التجارية والمواقع الاستراتيجية على البحر الأبيض المتوسط."},{"id":3963,"era":"c11","t":"انتصار القائد العثماني سليم كيراي على ملك بولونيا .","s":"استطاع القائد العثماني القرمي سليم كيراي أن يهزم سوبياسكي ملك بولونيا في معركة كامانيجة."},{"id":3964,"era":"c11","t":"التحالف المقدس بين الصليبيين ضد العثمانيين .","s":"إن الانتصار الذي أحرزه الصليبيون في فك حصار فيينا زاد من أواصر الصليبية وشجعها على المضي، فكونت أوربا حلفًا ضم: النمسا، وبولونيا، والبندقية، ورهبان مالطة، والبابا، وروسيا، وسموه (الحِلف المقدس)؛ وذلك للوقوف في وجه المد الإسلامي الذي أصبح قريبًا من كل بيت في أوربا الشرقية؛ بسبب جهاد العثمانيين الأبطال، وبدأ الهجوم الصليبي على ديار الدولة العثمانية، وبدأ هذا التحالف بالعمل؛ فالنمسا بدأت تهاجم بلاد ا"},{"id":3965,"era":"c11","t":"هزيمة جيش البندقية في معركة شين .","s":"تمكن القائد العثماني فندق مصطفى باشا- حاكم البوسنة- من هزيمة جيش البندقية في معركة شين."},{"id":3966,"era":"c11","t":"استسلام قلعة \"أويفار\" الخاضعة للدولة العثمانية .","s":"كانت أويفار خاضعة للدولة العثمانية منذ 21 عامًا. ثم استسلمت قلعتها أويفار إلى دوق لورين بعد حصار دام 50 يومًا، وكان الاستيلاء على هذه القلعة سببًا في إقامة الأفراح في العالم النصراني. وقد كانت هذه القلعة خاضعة للألمان، فاستولى عليها العثمانيون سنة 1074، وهي من أمنع وأقوى قلاع أوربا."},{"id":3967,"era":"c11","t":"انتصار القائد العثماني سليم كيراي على ملك بولونيا في معركة بويان .","s":"تمكن القائد العثماني القرمي سليم كيراي من هزيمة ملك بولونيا سوبياسكي في معركة بويان، وخسر البولونيون في هذه المعركة 6 آلاف قتيل و5 آلاف أسير."},{"id":3968,"era":"c11","t":"وفاة القائد العثماني داماد ملك إبراهيم باشا .","s":"هو القائد العثماني الكهل الفذ داماد ملك إبراهيم باشا، كان اسمه شيطان إبراهيم باشا، استبدل به السلطان محمد الرابع ملك إبراهيم باشا بعد انتصار القوات العثمانية في معركة كرز إلياس على الألمان، وعينه قائدًا بدل بكري مصطفى باشا, وبعد سقوط أويفار بيد الألمان أصدر رئيس الوزراء العثماني قرة إبراهيم باشا أمرًا بقتل داماد ملك إبراهيم باشا متَّهِمًا إياه بالمسؤولية عن سقوطها, وقيل إن السبب الحقيقي في قتله أن"},{"id":3969,"era":"c11","t":"استيلاء القائد البندقي موروسيني على قلعة نافارين من العثمانيين .","s":"تمكن القائد البندقي موروسيني من الاستيلاء على قلعة نافارين في جزيرة المورة باليونان من العثمانيين بعد حصار استمر 13 يومًا تقريبًا."},{"id":3970,"era":"c11","t":"سيطرة الجيش الألماني وحلفائه على قلعة \"بودين\" في بودابست .","s":"تمكن الجيش الألماني الضخم وحلفاؤه من الأوربيين من السيطرة على قلعة ومدينة \"بودين\" في بودابست، بعد دفاع عثماني مجيد، سقط خلاله آلاف القتلى من العثمانيين، وكان العثمانيون قد فتحوها قبل 160 عامًا إبَّان حكم سليمان القانوني، وكان سقوطها من أكبر المصائب العثمانية."},{"id":3971,"era":"c11","t":"سقوط مدينة بودابست المجرية في يد الألمان وطرد الأتراك منها .","s":"كان العثمانيون قد حاصروا فيينا وكادوا يفتحونها لولا أن الصليبيين تحالفوا بفعل نداءات البابا لهم، فقاموا بالتكالب على الدولة العثمانية كلٌّ من طرف، فوصلت القوات من كل مكان من بولونيا وبافاريا الألمان إلى فيينا لفك الحصار، ثم بعد فك الحصار عقد البابا حلفًا مع الروس والألمان والبولنديين والبنادقة على طرد العثمانيين من المجر، فقامت كل دولة بالهجوم على الدولة العثمانية من طرق؛ لتشتيت قواها، فاستطاع الأ"},{"id":3972,"era":"c11","t":"انتصار الجيش العثماني على \"جيش الاتفاق\" في معركة أوساك .","s":"انتصر الجيش العثماني على ما يسمى بـ \"جيش الاتفاق\" الذي كوَّنته أوربا النصرانية لحرب الدولة العثمانية في معركة \"أوساك\" قرب المجر."},{"id":3973,"era":"c11","t":"استيلاء البنادقة على قلعة كورون من العثمانيين .","s":"تمكن القائد البندقي موروسيني من الاستيلاء على قلعة كورون في اليونان من العثمانيين بعد حصارهم لها لمدة شهر كامل."},{"id":3974,"era":"c11","t":"هزيمة الجيش العثماني من قِبَل جيش الاتفاق الأوربي .","s":"تعرض الجيش العثماني لهزيمة قاسية في صحراء موهاج المجرية أمام جيش الاتفاق الذي كونته أوربا النصرانية لحرب العثمانيين، وقد قتل خلالها 20 ألف عثماني، مرة واحدة."},{"id":3975,"era":"c11","t":"انتصار العثمانيين على ملك بولونيا .","s":"قام العثمانيون بهزيمة ملك بولونيا سوبياسكي هزيمة كبيرة، وذلك قرب قلعة كامانيجة."},{"id":3976,"era":"c11","t":"استيلاء الجيش البندقي على مدينة أثينا من العثمانيين .","s":"تمكن الجيش البندقي الذي تسانده إسبانيا وألمانيا ومالطة والسويد من الاستيلاء على مدينة أثينا من العثمانيين، وقام بتخريبها بشكل فظيع، وقام الأرثوذكس بذبح الكاثوليك في المدينة بلا رحمة."},{"id":3977,"era":"c11","t":"خلع السلطان العثماني محمد الرابع وتولية أخيه سليمان الثاني .","s":"لما تتالت الهزائم على العثمانيين وحدثت الفوضى بسبب ذلك، اتفق العلماء والوزير على عزل السلطان محمد الرابع بن إبراهيم الأول، فتم ذلك في هذا العام بعد أن أمضى في الحكم أربعين سنة وخمسة أشهر، أعاد خلال مدة حكمه هيبة الدولة وقوتها، كما أعاد عمليات الفتح في أوربا، وتولى قيادة جيوش الدولة, ويعتبر هو آخر القادة الفاتحين في التاريخ الإسلامي، وتمت تولية أخيه سليمان الثاني في الثاني من محرم الذي كان يزيد عمر"},{"id":3978,"era":"c11","t":"استيلاء الجنرال المجري كارفا على مركز إيالة أكري من العثمانيين .","s":"تمكن الجنرال المجري كارفا من الاستيلاء على مركز إيالة أكري من العثمانيين، وبذلك خرج شمال المجر من الحكم العثماني. وقد كان بالمدينة التي فتحها العثمانيون قبل 91 عامًا من تاريخ سقوطها حوالي 41 مسجدًا هُدِّمت جميعًا إلا مأذنة واحدة ما زالت باقية حتى الآن، وتحول جامعها الكبير إلى كنيسة القديس ليوبولد!!"},{"id":3979,"era":"c11","t":"سقوط قلعة بلغراد في أيدي الألمان وتحويل مائة مسجد إلى كنائس .","s":"سقطت قلعة بلغراد في أيدي الألمان، بعد تسع وعشرين يومًا من حصار الجيش العثماني بداخلها، وتم تحويل مائة مسجد في المدينة إلى كنائس، بعد ذبح المسلمين الموجودين فيها. وكانت بلجراد مدينة إسلاميَّة لعدة قرون من حيث العمران وحركة العلم ورفع راية الجهاد, ثم تحوَّلت بعد سقوطها بسنوات إلى محاربة المسلمين، الذين حوَّلوها إلى إحدى أعظم مدن أوربا حضارة. وقت أنْ كانت أوربا تعيش في ظلمات الجهل والتخلُّف، وقد صارت"},{"id":3980,"era":"c11","t":"هزيمة الدولة العثمانية أمام النمسا .","s":"انتهز الأعداء الفوضى التي جرت بعد تولي السلطان الجديد سليمان الثاني حيث تمرد الجند وقتلوا الصدر الأعظم سياوس باشا وسَبَوا نساءه، فتقدم الأعداء في أملاك الدولة العثمانية, فأخذت النمسا كثيرًا من المواقع والمدن، ومنها بلغراد، كما أخذت البندقية سواحل دالماسيا (السواحل الشرقية لبحر الأدرياتيك) وبعض المواطن في بلاد اليونان وتوالت الهزائم."},{"id":3981,"era":"c11","t":"انتصار القائد القرمي سليم كيراي على الجيش الروسي .","s":"تمكن القائد القرمي التابع للدولة العثمانية سليم كيراي من هزيمة الجيش الروسي، المكون من 300 ألف جندي، والذي اقترب من حدود القرم."},{"id":3982,"era":"c12","t":"استعادة العثمانيين لبعض المواقع التي خسروها مثل بلغراد وغيرها .","s":"بعد أن تتالت الهزائم على الدولة العثمانية بفترة الصدر الأعظم مصطفى باشا، تم عزله وتولية مصطفى بن محمد كوبريلي مكانه، فكان كأبيه وأخيه من قبل، فسمح للنصارى في إستانبول ببناء ما تهدم من كنائسهم، وأحسن إليهم وعاقب بأشد العقاب كل من عرض لهم في إقامة شعائر دينهم، حتى استمال جميع نصارى الدولة، وكانت نتيجة معاملة النصارى الأرثوذكس بالعدل أن ثار أهالي مورة الأورام على البنادقة الكاثوليك، وطردوا جيشها من ب"},{"id":3983,"era":"c12","t":"رفع القائد البندقي موروسيني حصاره عن جزيرة \"آغري بوز\" .","s":"رفع القائد البندقي الشهير موروسيني حصاره عن جزيرة \"آغري بوز\" الخاضعة للحكم العثماني بعد 106 يومًا من الحصار والقتال الشرس، وقُتل خلال ذلك 23 ألفًا من البنادقة، وقد أطلق البنادقة على القلعة 182 ألف طلقة مدفعية، لكن القلعة ظلت صامدة"},{"id":3984,"era":"c12","t":"سقوط قلعة كانيجة في أيدي الألمان ثم استعادت العثمانيين لها .","s":"تمكن الألمان من إسقاط قلعة كانيجة في أيديهم، وذلك بعد 158 سنة من سيطرة الدولة العثمانية عليها، لكن العثمانيين تمكنوا من استردادها بعد ذلك بوقت قليل."},{"id":3985,"era":"c12","t":"استسلام قلعة بنفشه للبندقية .","s":"استسلمت قلعة بنفشه للبندقية بعد مقاومة استمرت 14 شهرًا، وتعد قلعة بنفشه هذه آخر قلاع الدولة العثمانية في جزيرة المورة (اليونان)."},{"id":3986,"era":"c12","t":"انتصار العثمانيين على الجيش الألماني في معركة زرنيت .","s":"انتصر العثمانيون بقيادة جركس أحمد باشا على الجيش الألماني في معركة زرنيت، ولم ينجُ من الجيش الألماني المكون من 26 ألف جندي سوى 200 جندي فقط!!"},{"id":3987,"era":"c12","t":"استيلاء العثمانيين على قلعة نيش من الألمان .","s":"تمكن العثمانيون من الاستيلاء على قلعة نيش الواقعة جنوبي صربيا، انتزعوها من الألمان، وذلك بعد حصار استمر 23 يومًا."},{"id":3988,"era":"c12","t":"استعادة العثمانيين السيطرة على قلعة بلجراد .","s":"تمكن العثمانيون من نزع السيطرة على قلعة بلجراد عاصمة صربيا الآن من يد الألمان، وتعدُّ قلعة بلجراد من أحصن القلاع، وتتكون من 9 طوابق، و116 برجًا، وقد قُتل من العثمانيين في سبيل ذلك 5 آلاف جندي."},{"id":3989,"era":"c12","t":"استيلاء الجيش الألماني على الأراضي المجرية التابعة للعثمانيين .","s":"تمكن الجيش الألماني بقيادة ماركراف من الاستيلاء على أغلب الأراضي المجرية التابعة للدولة العثمانية، مُنهيًا بذلك الحكم العثماني للمجر، والذي استمر لمدة 165 عامًا."},{"id":3990,"era":"c12","t":"وفاة السلطان العثماني سليمان الثاني وتولي أخيه أحمد الثاني .","s":"هو السلطان سليمان الثاني بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني, السلطان الثاني والعشرون من سلاطين بني عثمان، ولد عام 1052هـ وتولى الحكم بعد أخيه محمد الرابع عام 1099هـ واستمر التدهور في الدولة العثمانية في عهده، وازدادت شراسة الأعداء على عهده، فاغتصبت النمسا كثيرًا من المواقع والمدن، ومنها بلجراد عام 1099هـ، كما احتلت البندقية سواحل دالماسيا"},{"id":3991,"era":"c12","t":"وفاة فاضل مصطفى باشا كوبريلي رئيس وزراء الدولة العثمانية .","s":"هو الصدر الأعظم فاضل مصطفى باشا ابن الصدر الأعظم محمد علي باشا كوبريلي، رئيس وزراء الدولة العثمانية، وسليل عائلة كوبريلي الشهيرة وأخو الصدر الأعظم أحمد كوبريلي، كان عظيم النفع للدولة العثمانية. لما رأى السلطان إبراهيم الأول توالي المصائب على الدولة عزل الصدر الأعظم مصطفى باشا, وعيَّن مكانه مصطفى باشا بن محمد باشا كوبريلي الكبير, ولم يكن مصطفى أضعفَ همة من والده، بل كان يشبهه في علو المكانة ومَضاء "},{"id":3992,"era":"c12","t":"وفاة السلطان العثماني محمد الرابع بن إبراهيم الأول .","s":"هو السلطان العثماني محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول بن يزيد الثاني بن محمد الفاتح. ولد السلطان محمد عام 1051هـ، وتولى السلطنة وهو ابن سبع سنوات، فتولت جدته كوسيم مهبيكر نيابة السلطنة وأصبحت مقاليد الأمور في يديها، وساءت أحوال الدولة وتدخل الانكشارية (وهم قوات مشاة وفرسان بالجيش العثماني) في شؤونها فازدادت سوءً"},{"id":3993,"era":"c12","t":"نجاح العثمانيين في الدفاع عن قلعة خانيا .","s":"نجح العثمانيون في جزيرة كريت شمال إيطاليا في الدفاع عن قلعة خانيا لمدة 41 يومًا؛ مما أجبر أساطيل البندقية ومالطة وفلورانسا على الانسحاب بعد خسارتهم 4 آلاف جندي."},{"id":3994,"era":"c12","t":"رفع الجيش الألماني حصاره عن مدينة بلجراد .","s":"رفع الجيش الألماني حصاره عن مدينة بلجراد التي كانت خاضعة للدولة العثمانية، بعد خسارته 10 آلاف قتيل في هذا الحصار."},{"id":3995,"era":"c12","t":"وفاة السلطان العثماني أحمد الثاني وتولي ابن أخيه مصطفى الثاني .","s":"هو السلطان العثماني أحمد الثاني بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني. ولد في 6 ذي الحجة سنة 1052 تولى السلطنة بعد أخيه سليمان الثاني، وأبقى الصدر الأعظم مصطفى باشا كوبريلي اعتمادًا عليه في الحرب والسلم، لكن المنية لم تمهل هذا الوزير الشهير، فاستُشهد وهو في عنفوان شبابه في 24 ذي القعدة سنة 1102هـ في حروب الدولة العثمانية مع النمسا، فكان موت "},{"id":3996,"era":"c12","t":"وفاة أمير الدرعية محمد بن مقرن بن مرخان، جد آل سعود .","s":"هو الأمير محمد بن مقرن بن مرخان بن إبراهيم بن موسى بن ربيعة بن مانع المريدي بن ربيعة، وينتهي نسبه إلى بكر بن وائل من بني أسد بن ربيعة أمير الدرعية وجد آل سعود."},{"id":3997,"era":"c12","t":"اشتباك الأسطول العثماني مع الأسطول البندقي قرب جزر قويون .","s":"اشتبك الأسطول العثماني مع الأسطول البندقي في معركة بحرية قرب جزر قويون، وقد غرقت خلال هذه المعركة 9 سفن للبندقية دون أن تغرق أي سفينة من السفن العثمانية."},{"id":3998,"era":"c12","t":"نجاح العثمانيين في استعادة قلعة ساقيز من البنادقة والمالطيين .","s":"نجح العثمانيون في استعادة قلعة ساقيز- الواقعة في اليونان حاليًا- من البنادقة والمالطيين الذين احتلُّوها في محرَّم من هذا العام."},{"id":3999,"era":"c12","t":"بدء السلطان مصطفى الثاني حملة عسكرية على ألمانيا .","s":"ابتدأ السلطان العثماني مصطفى الثاني حملة عسكرية مكونة من 153 ألف جندي على ألمانيا، وقد استمرَّت هذه الحملة لمدة 4 أشهر."},{"id":4000,"era":"c12","t":"انتصار العثمانيين على البنادقة والمجريين بقيادة مصطفى الثاني .","s":"انطلق السلطان مصطفى الثاني بجيشه إلى بولونيا فانتصر عليهم في عدة معارك بمساعدة القوزاق، ثم انطلق إلى بلاد المجر بعد أن فك الحصار الروسي عن مدينة آزوف، فهزم جيوش المجر، ثم في عهد ولاية الصدر الأعظم حسين كوبريلي سارت الجيوش بالأساطيل على البندقية واستردَّ بعض الجزر في بحر إيجه."},{"id":4001,"era":"c12","t":"غزو شريف مكة سعد بن زيد بلاد نجد .","s":"غزا شريف مكة سعد بن زيد بلاد نجد، ونزل في بلدة أُشيقر، وحاصر أهلها، وكان قد سار إليها من قبل حتى وصل إلى منطقة الحمادة ثم رجع عنها."},{"id":4002,"era":"c12","t":"قيام حملة السلطان العثماني السلطانية الثانية على أوربا .","s":"قام السلطان العثماني مصطفى الثاني بحملته السلطانية الثانية على أوربا، والتي خاض فيها العثمانيون حربًا شرسة مع الجيش الألماني، وقد أسفرت عن انتصار العثمانيين. واستمرت هذه الحملة 6 أشهر."},{"id":4003,"era":"c12","t":"في العنوان مكتوب (وحصار الجيش الروسي لقلعة أزاك) لكن في تفاصيل الحدث لا يوجد ذكر للحصار الروسي ! ويوجد عنوان آخر مستقل بعنوان (الروس يستولون على قلعة أزاك العثم","s":"بعد الانتصارات البحرية التي حققها العثمانيون خرج السلطان مصطفى الثاني بنفسه في هذا العام, لمحاربة النمساويين، فاستولى على قلعة ليبا وانتصر في وقعة لوغوس وقُتل الجنرال فيتراني قائد جيوش النمسا في هذه الموقعة، ثم عاد السلطان إلى الآستانة (إسطنبول حاليا). ولكن النمساويين أعادوا الكرة في السنة التالية فحاصروا قلعة طمشوار، فتقدم إليهم السلطان العثماني بجنوده وردهم عن القلعة بعد أن دحرهم دحورًا فاحشًا، "},{"id":4004,"era":"c12","t":"(بطرس) قيصر روسيا يقاتل العثمانيين ويفتح أزوف (أزاق) .","s":"حاصر بطرس الأكبر القيصر الروسي مدينة آزوف التي كانت أصلًا قد استردها العثمانيون وأخضعوها للدولة العثمانية أيام ثورة القوزاق عليهم، ثم أُجبر القيصر الروسي على فك الحصار عام 1107هـ بعد أن قاومهم خان القرم والعثمانيون الذين هناك، فردوهم بعد أن قتلوا منهم نحوًا من ثلاثين ألف جندي، فلما انشغل العثمانيون بالحرب مع المجر استغل الروس هذا الانشغال، فعادوا إلى آزوف ودخلوها هذا العام."},{"id":4005,"era":"c12","t":"الروس يستولون على قلعة أزاك العثمانية .","s":"حاصر الجيش الروسي المكون من مائة ألف جندي قلعة أزاك العثمانية القريبة من البحر الأسود لمدة ثلاثة وستين يومًا حتى استسلمت القلعة, ولم يتمكن العثمانيون من استرجاعها إلا بعد خمسة عشرة عامًا، ثم استرجعها الروس فجأة عام 1148هـ مما تسبب في إعلان الحرب على روسيا."},{"id":4006,"era":"c12","t":"خوض الجيش العثماني معركة \"أولاز\" ضد الجيش الألماني .","s":"خاض الجيش العثماني معركة \"أولاز\" الشرسة ضد الجيش الألماني، والتي أسفرت عن مقتل 16 ألف ألماني، و1500 عثماني."},{"id":4007,"era":"c12","t":"خوض الأسطول العثماني معركة بحرية ضد الأسطول البندقي .","s":"خاض الأسطول العثماني بقيادة القبطان ميزو مورتا حسين باشا معركة بحرية ضد الأسطول البندقي (نسبة إلى مدينة البندقية) قرب جزر أندروز، أسفرت عن غرق 13 سفينة بندقية، ومقتل 5 آلاف بحار."},{"id":4008,"era":"c12","t":"النمساويون يهزمون العثمانيين ومقتل الصدر الأعظم محمد باشا .","s":"بعد أن استطاعت الجيوش العثمانية أن تفكَّ الحصار الروسي عن آزوف سارت إلى المجر، ولكن لم تستطع هزيمة الجيش النمساوي بقيادة أوجين دي سافوا على نهر تيس، فقُتل يومها الصدر الأعظم محمد باشا وغرق أعدادٌ من العثمانيين في النهر، ولاحقهم القائد النمساوي حتى دخل بلاد البوسنة، ثم تولى الصدارة العظمى حسين كوبريلي، فسار نحو النمسا فتقهقرت أمامه جيوشُها ودفعهم إلى ما بعد نهر السافا."},{"id":4009,"era":"c12","t":"تعرض الجيش العثماني لهزيمة في معركة \"زينتا\" أمام الجيش الألماني .","s":"تعرض الجيش العثماني لهزيمة قاسية في معركة زينتا، وهي قرية تقع جنوب المجر، أمام الجيش الألماني، وقد قُتل من العثمانيين 20 ألفًا، إضافة إلى غرق 10 آلاف آخرين، وترجع هذه الهزيمة إلى خيانة بعض القادة العثمانيين."},{"id":4010,"era":"c12","t":"معاهدة كارلوفتس بين العثمانيين وبعض دول أوربا .","s":"تعتبر معاهدة كارلوفتس (كارلوفجة) إحدى أقسى المعاهدات في تاريخ الدولة العثمانية، واعتبرت بداية انحسار المد الإسلامي في أوربا، وبداية مرحلة التفكك في الدولة العثمانية، وكان من الأسباب التي أدت إلى كارلوفتس ضعف الوازع الديني عند المسلمين وبرود همَّتهم الجهادية، واستمرار ثورات الانكشارية وتقاعسهم عن أداء واجبهم، وتعاقب الحملات الصليبية واشتدادها، واتحاد القوى الأوروبية على دولة الخلافة الوحيدة، فكانت "},{"id":4011,"era":"c12","t":"انتصار العثمانيين على البندقيين جنوب جزيرة ميديلي .","s":"انتصر الأسطول العثماني على الأسطول البندقي في معركة بحرية جنوب جزيرة ميديلي في البحر المتوسط، وأسفرت هذه المعركة عن مقتل 2500 بندقي."},{"id":4012,"era":"c12","t":"انتصار العمانيين على البرتغاليين في موقعة ممبسة البحرية .","s":"انتصر العمانيون على البرتغاليين في موقعة ممبسة البحرية، والتي استمرت ثلاثة أيام، هبت خلالها ريح شديدة كانت سببًا في جعل الأسطول البرتغالي ينسحب من المعركة."},{"id":4013,"era":"c12","t":"انتصار العثمانيين على سلطان فاس .","s":"انتصر العثمانيون بقيادة مصطفى دايي على السلطان \"إسماعيل الكبير\" سلطان فاس في معركة \"جدوية\" وقُتِل فيها من الفاسيين 30 ألفًا."},{"id":4014,"era":"c12","t":"شيخ الإسلام فيض الله أفندي يتدخل في تصريف الدولة العثمانية .","s":"كان فيض الله أفندي معلم السلطان قبل جلوسه على كرسي السلطنة، وكان السلطان ولَّاه مسند المشيخة الإسلامية وصار يستشيره في كل الأمور، فأغاظ ذلك الصدر الأعظم حسين باشا كوبريلي لتدخُّل شيخ الإسلام في الأحوال السياسية التي ليست من متعلقات وظيفته أصلًا، وكان القبودان ميزه مورتو حسين باشا مدة حياته يجتهد في التأليف بينه وبين الصدر ويزيل النفور من قلوبهما، إلا أنه بعد وفاة القبودان استبدَّ الشيخ فيض الله أف"},{"id":4015,"era":"c12","t":"عقد الدولة العثمانية معاهدة إستانبول مع روسيا .","s":"عقدت الدولة العثمانية معاهدة إستانبول مع روسيا بعد مفاوضات استمرت 5 أشهر، وتضمنت المعاهدة (14) بندًا، منها: أن يكون ذهاب وإياب السفير الروسي إلى إستانبول عن طريق البر، وليس عن طريق البحر؛ لأن البحر الأسود بحر عثماني مغلق."},{"id":4016,"era":"c12","t":"وفاة القائد البحري العثماني الشهير ميزو مورتا حسين باشا غرقا  .","s":"هو القائد البحري العثماني الشهير ميزو مورتا حسين باشا حاكم جزائري عثماني، كان أحد قادة رياس البحر الكبار عندما تفاوض الداي بابا حسن- حاكم جزائري- مع الفرنسيين على أن يدفع لهم جزية كبيرة وإطلاق جميع الأسرى الفرنسيين في الجزائر لم يُعجِب طائفة رياس البحر، فقتلوا الداي بابا حسن, وعينوا حسين ميزو مورتو دايا مكانه، وبعد توليه الحكم أرسل خطابًا شديد اللهجة إلى قائد الحملة الفرنسية دوكين ينذره إلا أن دوك"},{"id":4017,"era":"c12","t":"أول مطبعة بالأحرف العربية .","s":"تم في هذه السنة إنشاء أول مطبعة بالحروف العربية؛ فقد أنشأ عبد الله الصائغ في حلب أول مطبعة تطبع بالحروف العربية، وأنشأ أيضًا مطبعة أخرى مثلها في لبنان، أما في إستانبول فكانت أول مطبعة أنشئت فيها عام 1139هـ بعد موافقة المفتي بذلك."},{"id":4018,"era":"c12","t":"بناء مدينة سانت بطرسبرغ  .","s":"سانت بطرسبرغ مدينة روسية تقع في شمال غرب روسيا في دلتا نهر نيفا، وتعتبر أحد أكبر مراكز أوربا الثقافية. عندما احتلت روسيا مصبَّ نهر نيفا وضع القيصر بطرس الأول أساسَ مدينة سانت بطرسبرج كنافذة مطلة على أوربا، ببناء قلعة ضخمة على نهر نيفا، ثم اتسعت رغم وعورة المنطقة وكثرة المستنقعات، وسرعان ما تحولت إلى ميناء عسكري تجاري كبير، وفتحت آفاق اتصال واسع مع الحضارة الأوروبية, كانت عاصمة الإمبراطورية الروسية"},{"id":4019,"era":"c12","t":"قتال بين الباي أحمد بن سليمان وإبراهيم الشريف آغة الصبايحية .","s":"ظهر أحمد بن سليمان باي بن رمضان باي بن مراد الأول قائمًا في البلاد فجمع أهل الفساد، فجهَّز له إبراهيم الشريف آغة الصبايحية، وخرج له في الرابع من محرم هذه السنة وقصده نحو السوس، فالتقى عسكر من عساكر إبراهيم الشريف بأحمد بن سليمان، فوقعت الهزيمة على جيش إبراهيم الشريف، فرحل أحمد بن سليمان نحو إفريقية بقرب جندوبة، وتبعه إبراهيم الشريف، والتقيا في الحادي عشر من محرم، فانهزم أحمد بن سليمان وتشتت جمعه، "},{"id":4020,"era":"c12","t":"خلع السلطان العثماني مصطفى الثاني وتولية أخيه أحمد الثالث .","s":"بعد أن استقال الصدر الأعظم حسين كوبريلي عام 1114هـ ثار الانكشارية على خلفه فاستُبدل برامي محمد باشا الذي سار على خطى كوبريلي في الإصلاح وإبطال المنكر ومحاربة الرشوة والتضييق على المفسدين، فثاروا عليه أيضًا وطلبوا من الخليفة أن يعزله فرفض. وكان الغضب واسعًا من السلطان وشيخ الإسلام فيض الله أفندي الذي كان يستأثر أقاربه بالمناصب العلمية والقضائية, فثاروا عليه أيضًا وطلبوا بخلع شيخ الإسلام، لكن الخليف"},{"id":4021,"era":"c12","t":"وفاة السلطان العثماني مصطفى الثاني بن محمد الرابع .","s":"هو السلطان العثماني مصطفى الثاني ابن السلطان محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول بن بايزيد الثاني بن محمد الفاتح بن مراد الثاني بن محمد الأول جلبي بن بايزيد الأول بن مراد الأول بن أورخان. وُلِدَ عام 1074هـ وتولى الخلافة عام 1106هـ/1694م وفي عهده بدأ تراجع المد الإسلامي عن ديار أوروبا الشرقية؛ بسبب ضعف روحِ الجهاد،"},{"id":4022,"era":"c12","t":"قتال بين باي الجزائر وباي تونس .","s":"جهز إبراهيم الشريف باي تونس مراكب صغارًا للغزو في سبيل الله، فغَنِمت إحداها غنيمةً بها ثلاثون نصرانيًّا وعدة صناديق بها أموال جزيلة، فدخلوا طرابلس فأحضرها خليل باي الجزائر بين يديه واغتصب منها أحد عشر نصرانيًّا واحتاط على الأموال بأسرها، فلم يُبقِ منها ولم يذرْ، واغتصب عدة صناديق بها آلات حرب وطردهم، فلما علم بذلك إبراهيم الشريف ورأى تجرؤَ خليل جمع جموعه ونصب ديوانًا في شأن تعدي خليل، فكان اتفاق ا"},{"id":4023,"era":"c12","t":"وفاة إبراهيم الشريف باي تونس .","s":"هو إبراهيم الشريف أحد بايات وولاة تونس من الأسرة المرادية، تولى الحكم من عام 1702 حتى 1705 وهي الفترة المتأزمة التي تلت نهاية حكم المراديين وبداية حكم الحسينيين على يد حسين بن علي. كان أمير جند البايات المراديين بتونس وآغا الصبايحية. قتل مراد باي الثالث عام 1702م بأمر من العثمانيين كما قضى على كافة أبناء وأحفاد حمودة باشا، منهيًا بذلك فترة حكم المراديين بتونس. عيَّنه جند الصبايحية بايا، ثم عُيِّن "},{"id":4024,"era":"c12","t":"مبايعة حسين بن علي وقيام الدولة الحسينية .","s":"بعد عزل باي تونس إبراهيم الشريف اجتمع أهل الحل والعقد من العلماء وأكابر العسكر بتونس، فنصبوا ديوانًا لتولية من يصلح للقيام بأمر الخلق، فلم يجدوا أصلح من حسين باي بن علي الحسيني، فجددوا بيعته وأبقوه على ما هو عليه من ولايته؛ لِما يعلمون من شفقته وعطفه وحسن عهده وسلامة صدره من المكر والحقد والغدر، ولِما جبله الله عليه من اللين والرفق وحسن التدبير والسياسة، ففرح الخلقُ عامة من أهل تونس وأوطانها وعجمه"},{"id":4025,"era":"c12","t":"وفاة العلامة النوري الصفاقسي .","s":"هو المقرئ الفقيه المالكي الأشعري الصوفي: أبو الحسن علي بن محمد النوري الصفاقسي، صاحب كتاب \"غيث النفع في القراءات السبع\" ولد بصفاقس سنة 1053 ونشأ بها، ورحل إلى تونس فأخذ عن أهلها، ثم رحل إلى مصر فكمل بها علومه، ثم عاد إلى مسقط رأسه وانقطع لبثِّ العلم والإرشاد. كان يأكل من كسبه فيتَّجِر ويشتغل بالقماش يتعيش منه طلبًا للحلال وتوكُّلًا على الله، ولا يأخذ عن تعليمه شيئًا. كان الشيخ النوري يدعو إلى جهاد"},{"id":4026,"era":"c12","t":"وفاة العلامة القاضي التاجموعتي .","s":"هو العلامة الأديب المحدِّث الخطيب النوازلي المسنِد أبو الوليد عبد الملك بن محمد التاجموعتي، قاضي سجلماسة، كان خطيباً حاد اللسان عالِمًا بالحديث عارفًا بالمخاطبات السلطانية، ينظِم الشعر، له فهرسة نسبها له تلميذه الشيخ المسناوي في إجازته لابن عاشر الحافي السلوي، وحج وجاور هناك سنوات، ودرَّس وألف بالحرمين الشريفين، وأجازه الحافظ البابلي والزرقاتي والخرشي وعمر الفكروني السوسي. كان إمامًا محدِّثًا، وكا"},{"id":4027,"era":"c12","t":"قتال عتوب الزبارة مع عتوب الكويت ضد عرب بني كعب .","s":"اشترك عتوب الزبارة (آل خليفة) في قطر مع عتوب الكويت (أُسرة الصباح) في الحرب ضد عرب بني كعب، وهي من القبائل العربية القاطنة في الشاطئ الفارسي للخليج العربي. وكانت العلاقة بين آل خليفة وأسرة الصباح تقوم على أساس الصداقة والتعاون، وبخاصة في المجالات العسكرية والتجارية."},{"id":4028,"era":"c12","t":"استعادة الأتراك مدينة وهران من أيدي النصارى الأسبان .","s":"نجح الأتراك في استعادة مدينة وهران من أيدي النصارى الأسبان الذين أخذوها سنة 1114هـ  فنكبوا أهلها، فكانوا ما بين أسير وقتيل إلى أن أعادها الله عز وجل للإسلام والمسلمين على يد الأتراك هذه السنة."},{"id":4029,"era":"c12","t":"سعود الأول بن محمد بن مقرن يتولى إمارة الدرعية .","s":"كان موسى بن ربيعة بن وطبان بن ربيعة بن مرخان بن إبراهيم أميرًا للدرعية إلى أن خلعه أهلُ الدرعية، فتوجَّه إلى العيينة وتولى الإمارة مكانَه ابنُ عمه سعود الأول بن محمد بن مقرن بن مرخان بن إبراهيم الذي يلتقي مع موسى في جدهما مرخان بن إبراهيم."},{"id":4030,"era":"c12","t":"وفاة الزرقاني محدث الديار المصرية .","s":"هو الفقيه العلامة الإمام محدث الديار المصرية أبو عبد الله محمد بن عبد الباقي بن يوسف الأزهري، المالكي الناسك النحرير الشهير بالزرقاني نسبة إلى زرقان من قرى المنوفية، المصري الأزهري خاتِمة الحفاظ والمحدِّثين. ولد سنة 1055. كان شغوفًا بالعلم والعلماء منذ صِغَر سنه. أخذ عن والده وعن النور علي الشبراملسي. له مصنفات منها: شرح الزرقاني على موطأ الإمام مالك، ومختصر المقاصد الحسنة في بيان الأحاديث المشتهر"},{"id":4031,"era":"c12","t":"أحمد قره مانلي يؤسس حكمًا مستقلًّا في ليبيا تابعا للعثمانيين .","s":"لَمَّا دخلت الدَّولةُ العُثمانيةُ في عِدَّةِ حُروبٍ في آنٍ واحدٍ مع الروسِ واليونانيِّين والبلغار والرومان والأرمن واليوغسلاف، أصبحت عاجزةً عن حمايةِ ولاياتِها وفَرْضِ النظامِ والتحَكُّمِ في الولاةِ الذين صاروا يَنصِبون ويَعزِلون حسَبَ نزواتِ الجُندِ في جوٍّ مشحون بالمؤامراتِ والعُنفِ. وفي كثيرٍ مِن الأحيان لم يبقَ الوالي في منصِبِه أكثَرَ مِن عام واحد، حتى إنه في الفترة ما بين سنة (1672 م-1711 م)"},{"id":4032,"era":"c12","t":"العثمانيون يحاصرون قيصر الروس ثم يوقعون معاهدة فلكزن .","s":"بعد أن تولى بلطجي محمد باشا الصدارة العظمى أعلن الحرب ضد روسيا وقاد الجيوش، فتمكن من حصار القيصر ومعه خليلته كاترينا الأولى، ومعه قرابة 200 ألف جندي، ولكن كاترينا التي قامت بإغراء الصدر الأعظم بالمال استطاعت أن تفكَّ الحصار، فنجا القيصرُ ومن معه من الإبادة أو الأسر، ووقعت معاهدة (فلكزن) في جمادى الآخرة من هذا العام بين الطرفين, تعهد فيها القيصر بعدم التدخل في شؤون القوزاق والتخلي عن ميناء آزوف."},{"id":4033,"era":"c12","t":"معاهدة أدرنة بين العثمانيين والروس .","s":"بعد توقيع المعاهدة فلكزن سنة 1123هـ بين الروس والعثمانيين والتي كانت السبب في عزل الصدر الأعظم بلطجي محمد باشا بجهود خان القرم ودعم ملك السويد، ونفيه إلى جزيرة لمنوس في بحر إيجة، وتولي يوسف باشا المنصب؛ قام بعقد معاهدةٍ جديدة مع روسيا تنصُّ على هدنة بين الطرفين مدتها خمس وعشرون سنة، غير أن الحرب كادت تتجدَّد لإخلال القيصر بالشروط، فرأت هولندا وإنجلترا أن مصلحتها إيقاف الحرب؛ ولذلك تدخلتا، ووُقِّعت"},{"id":4034,"era":"c12","t":"الأسرة القرمانية في ليبيا تستقل ذاتيًّا عن الدولة العثمانية .","s":"أصبح أحمد القرة مانلي الداي والباشا معًا في ليبيا لصالح العثمانيين، وأسس الأسرة القرة مانلي التي حكمت طرابلس وفزان أكثر من مائة سنة، فقضى أحمد القرة مانلي مدعومًا من الانكشارية والسكان المحليين على مقاومة كبار الضباط والموظفين الأتراك؛ إذ دعاهم إلى الاجتماع وذبح ثلاثمائة شخص منهم، وفشلت الحملة العسكرية التي وُجِّهت ضده من قِبَل الدولة العثمانية."},{"id":4035,"era":"c12","t":"العثمانيون يهزمون البنادقة ويستردون الجزر في بحر إيجة .","s":"انتصر العثمانيون على البنادقة وأخذوا منهم ما بقي بأيديهم من جزيرة كريت وبعض الجزر الأخرى، فاستنجد البنادقة بالنمسا التي ارتاحت من الحروب بينها وبين فرنسا، فطلب إمبراطور النمسا من الدولة العثمانية إرجاعَ ما أُخذ من البنادقة إليهم، فرفضت الدولة العثمانية وقامت الحرب من جديد بين الطرفين وانتصرت النمسا وقُتِل الصدر الأعظم علي باشا."},{"id":4036,"era":"c12","t":"تغلب الألمان على الجيش العثماني في معركة بترفارادين .","s":"تمكَّن القائد الألماني الشهير \" أوجين\" من هزيمة الجيش العثماني في معركة بترفارادين، وكان سبب هزيمة العثمانيين هو تشتُّت الجيش العثماني بعد مقتل قائده الوزير تورك أحمد بك حاكم الأناضول."},{"id":4037,"era":"c12","t":"استيلاء الأمير الألماني أوجين على قلعة \"تامشوار\" الخاضعة للعثمانيين .","s":"تمكَّن الأمير الألماني أوجين من الاستيلاء على قلعة \"تامشوار\" التي كانت خاضعة للعثمانيين، وهي مدينة مجرية، وتسببت سيطرة الألمان على هذه القلعة في انقطاع صلة العثمانيين بالمجر."},{"id":4038,"era":"c12","t":"سيطرة الألمان على مدينة بلغراد من الدولة العثمانية .","s":"سيطر الأمير الألماني أوجين على مدينة بلغراد من الدولة العثمانية بعد 42 يومًا من الحصار، وقد سقط من العثمانيين 20 ألفًا قُتِلوا أثناء محاولة فك الحصار عن المدينة، ودام الاحتلالُ الألماني لبلغراد 22 عامًا."},{"id":4039,"era":"c12","t":"معاهدة (بساروفتس) وتخلي الدولة العثمانية عن الصرب وبلغراد .","s":"بعد أن انتصرت النمسا على العثمانيين وجاء الصدر الأعظم الجديد خليل باشا الذي جاء مددًا للعثمانيين، فهُزم أيضًا أمام النمسا وسقطت بلغراد عام 1129هـ ثم جرى الصلح، ووقعت معاهدة بساروفتس بجهود إنكلترا، فأخذت بموجبها النمسا مدينة بلغراد وأكثر بلاد الصرب وجزءًا من الأفلاق، ولكن تبقى سواحل دالماسيا للبندقية، وترجع بلاد المورة للعثمانيين."},{"id":4040,"era":"c12","t":"توقيع الدولة العثمانية معاهدة \"بساروفيتش\" مع النمسا والبندقية .","s":"بدأت مساعي الصلح بين الدولة العثمانية وكل من النمسا والبندقية بعد (12) يومًا من صدارة إبراهيم باشا- أي من بدء توليه رئاسة الوزراء- وانتهت هذه المساعي بتوقيع معاهدة وصلح \"بساروفيتش\" في 22 شعبان من هذه السنة، وقد تكونت هذه المعاهدة من (20) مادة خاصة بالنمسا، و(26) مادة خاصة بالبندقية، وقد أنهت حالة الحرب مع البندقية، والتي استمرت ثلاث سنوات وسبعة أشهر، ومع النمسا التي استمرت سنتين وشهرين، وتقضي هذه "},{"id":4041,"era":"c12","t":"تعديل معاهدة بساروفيتش .","s":"طلبت روسيا من الدولة العثمانية تعديل معاهدة بساروفيتش، وذلك بما يتيح لتجَّارها المرور من أراضي الدولة العثمانية وبيع سِلَعِهم فيها، وأن يتوجَّه الحجاج الروس إلى بيت المقدس وغيره من الأماكن والأديرة المقدسة بدون دفعِ خراج أو رسوم أثناء إقامتهم أو على جوازات سفرهم. وأضيف إلى هذه المعاهدة شرط آخر ذو أهمية سياسية كبيرة؛ حيث تعهدت الدولة العثمانية وروسيا بموجِبه بمنع زيادة نفوذ الملك المنتخب ببولونيا ع"},{"id":4042,"era":"c12","t":"ارتكاب الثوار اليونانيين مذبحة كبيرة ضد الأتراك .","s":"ارتكب الثوار اليونانيون مذبحة كبيرة ضد الأتراك في مدينة تريبوليجة، وذلك في الرابع والعشرين من شهر ذي الحجة من هذه السنة، وقد راح ضحية تلك المذبحة 8 آلاف مدني (غير عسكري)، وقد حدث ذلك في أثناء الثورة اليونانية ضد الدولة العثمانية."},{"id":4043,"era":"c12","t":"هجوم القاجاريين في إيران على الأناضول الشرقية وحصارهم لبغداد .","s":"استغل القاجاريون في إيران انشغال الدولة العثمانية بإخماد ثورة اليونان، وقاموا بمهاجمة الأناضول الشرقية وحاصروا بغداد، وقد عُقد بعد سنتين صلحٌ بين الجانبين لإنهاء الحرب بينهما، وكانت تلك آخِرَ حرب بين إيران وتركيا."},{"id":4044,"era":"c12","t":"إعلان الثوار اليونانيين تأسيس اليونان .","s":"أعلن الثوار اليونانيون ضِدَّ الدولة العثمانية تأسيسَ دولة اليونان التي تضم المورة وجزر كيكلاد، وجزيرة أغرى بوز."},{"id":4045,"era":"c12","t":"سيطرة العثمانيين على ميناء وقلعة ساقيز في اليونان .","s":"تمكن العثمانيون بقيادة القائد البحري العثماني نصوح زاده علي باشا من السيطرة على ميناء وقلعة ساقيز في اليونان إبَّان الثورة اليونانية ضد الدولة العثمانية، وذلك بعد 19 يومًا من بدء العصيان ضد العثمانيين."},{"id":4046,"era":"c12","t":"الاتفاق بين روسيا وتركيا على اقتسام بلاد فارس .","s":"ضعُفت الدولة الصفوية وتنازل الشاه حسين عن السلطة لمير محمد أمير بلاد أفغانستان، فأسرع الصدر الأعظم إبراهيم باشا واحتل بلاد أرمينيا وبلاد الكرج وأسرع قيصر روسيا بطرس الأكبر واحتلَّ بلاد داغستان وساحل بحر الخزر الغربية، واصطدمت الجيوشُ العثمانية والروسية، وكادت الحرب أن تقع بين الطرفين لولا وساطةُ فرنسا بناءً على طلب من روسيا التي وجَدت نفسها عاجزة عن القتال، فبقي كل فريق في المناطق التي دخلها دون م"},{"id":4047,"era":"c12","t":"وفاة الأمير سعود بن محمد الأول أمير الدرعية .","s":"هو الأميرُ سعود بن محمد بن مقرن بن مرخان، أمير الدرعية جدُّ آل سعود حكَّام المملكة العربية السعودية، كان مسكنُه الدرعية بنجد، وهي كانت أساس المُلك."},{"id":4048,"era":"c12","t":"الأفغان يستولون على بلاد فارس .","s":"كان كركين خان قد تقدم بجيشه إلى أفغانستان وأخضعهم تحت نفوذه، ثم إنَّهم استغاثوا من ظُلمِه بملك الصفويين، ولكن كركين كان قد سبقهم وأعلمه أنهم عبارة عن عصاة، ثم برز أويس الذي كان يحكم قندهار فأرسله كركين إلى الشاه الصفوي على أنه زعيم العصاة، لكنه حظِيَ بالقرب من الشاه وفكَّر في الاستقلال، لكنه رأى أن يتريَّث وخاصة أن الدولة الصفوية أخذت في الهَرَم والضعف، ثم رجع إلى بلاده ليكون رقيبًا على كركين، وأر"},{"id":4049,"era":"c12","t":"ظهور وباء في العيينة ووفاة أميرها عبد الله بن معمر .","s":"وقع وباء كبير في مدينة العيينة أقوى إمارات نجد، وأودى بحياةِ عدد كبير من رجالها، ومن بينهم أميرُها عبد الله بن معمر الذي حكمها لمدة 41 عامًا من (1096هـ ـ 1138هـ) ولم يكن في زمانه في نجد من يضاهيه في الرئاسة وقوة الملك والعدة."},{"id":4050,"era":"c12","t":"روسيا القيصرية تسيطر على بحر قزوين التابع لبلاد فارس الإسلامية .","s":"لَمَّا رأى بطرس الأكبر قيصر روسيا أن الدولة الصفوية بدأت تضعُف، قام باحتلال بلاد داغستان وسواحل بحر الخزر (قزوين) الغربية، وقام الصفويون بالرد وكادت الحرب أن تستمر لولا تواسط فرنسا بناء على طلب روسيا، فتم الصلح بين الدولتين، ولكِنْ على أن يبقى مع كل طرف ما أخذه."},{"id":4051,"era":"c12","t":"وفاة الإمام العلامة نور الدين السندي .","s":"هو الشيخُ الإمام العلَّامة المحقِّق المدقِّق نور الدين أبو الحسن بن عبد الهادي السندي، من فقهاء الأحناف المشهورين. ولِدَ ببته قرية من بلاد السند ونشأ بها ثم ارتحل إلى تستر، وأخذ بها عن جملة من الشيوخ، كالسيد محمد البرزنجي، والملا إبراهيم الكوراني، وغيرهما، ودرَّس بالحرم الشريف النبوي، واشتهر بالفضل والذكاء والصلاح. استوطن المدينةَ المنورة، برع في علم الحديث، وألَّف مؤلفات نافعة من الحواشي، منها: ح"},{"id":4052,"era":"c12","t":"وفاة الملك إسماعيل بن محمد ملك العلويين في مراكش وتولي ابنه أحمد .","s":"هو الملك أبو النصر إسماعيل بن محمد بن علي المراكشي، الملك الثاني لدولة العلويين في مراكش. ولد سنة 1057 بتافيلات التي تقع جنوب شرقي المغرب. كانت الدولة العلوية في عهده أزهى أيامها، وقد نقل عاصمته من مراكش إلى مكناسة، توفِّي بعد أن أمضى في الحكم سبعة وخمسين عامًا، وخلفه ابنُه أحمد."},{"id":4053,"era":"c12","t":"تولي الأمير محمد بن سعود بن محمد بن مقرن إمارة الدرعية .","s":"توالى أبناء مانع المريدي وأحفادُه على حُكم إمارة الدرعية والقرى التي حولها، ولم يتجاوزوها إلى أن آلت الإمارة إلى الأمير محمد بن سعود بن محمد بن مقرن بن مرخان هذه السنة, والذي تمَّت في عهده سنة 1157هـ المعاهدة التاريخية بينه وبين الإمام المجدد محمد بن عبد الوهاب. ومنها بدأت دولةُ الدرعية بالتوسُّعِ والحركة، حيث آزروا الشيخ محمد بن عبدالوهاب على تبليغ الدعوة، وانتشرت حتى ضَمَّت كل بلاد العارض عدا ال"},{"id":4054,"era":"c12","t":"توقيع الدولة العثمانية معاهدة \"آينا قاياق\" مع روسيا .","s":"وقَّعت الدولة العثمانية معاهدة \"آينا قاياق\" مع روسيا، حول جزيرة القرم، وكانت هذه المعاهدة ضدَّ مصالحِ الدَّولةِ العُثمانيَّةِ."},{"id":4055,"era":"c12","t":"استيلاء  العثمانيين على بعض أراضي الصفويين .","s":"لما ضعُف الصفويون استولى العثمانيون على كثيرٍ مِن مناطقهم، ثم ما لبث الصفويون أن هبُّوا وقاتلوا العثمانيين، ولكنهم هُزموا وفقدوا تبريز وهمدان وعددًا من القلاع، ثم جرى الصلح, ومات الشاه، وبقي الشاه طهماسب فطلب من العثمانيين أن يتخلَّوا عما أخذوه فلم يقبلوا فغزاهم، ولم تكن عند الخليفة حرارة القتال، فثار الانكشارية عليه وقتلوا الصدر الأعظم وأمير البحر، ثم امتد أذاهم وعصيانهم إلى الخليفة."},{"id":4056,"era":"c12","t":"توقيع الدولة العثمانية معاهدة مع إيران حول الحدود بين الجانبين .","s":"بعد فتح العثمانيين عدة مدن وقلاع إيرانية، أهمها مدائن همدان وأريوان وتبريز؛ وذلك نتيجة لتسلط الفوضى داخل إيران، وتنازع كل من الشاه أشرف الذي قتل مير محمد أمير أفغانستان، والشاه طهماسب ملك ساسان. انتهت هذه الحرب بالصلح مع الشاه أشرف في 25 صفر سنة 1140هـ"},{"id":4057,"era":"c12","t":"وفاة الملك أحمد الذهبي ملك العلويين في المغرب وقيام أخيه عبدالله .","s":"هو الملك أحمد الذهبي بن إسماعيل بن محمد بن علي: ملك العَلويين الحسنيين في المغرب الأقصى، وعُرف بالذهبي لبسط يده بالعطاء، وبعد توليته قتَل كثيرًا من عمال أبيه وأركان دولته, وكان ضعيف الإرادة، يستشير عبيدَه في أغلب شؤونه، فتسلَّطوا على الناس حتى ضجَّ أهل فاس وثاروا على السلطان سنة 1140 فنقَضوا بيعته، وتبِعَهم أهل مكناسة فقبضوا عليه، وبايعوا أخاه عبد الملك بن إسماعيل. قام عبد الملك بنفي أخيه أحمد إلى"},{"id":4058,"era":"c12","t":"الدولة العثمانية والتأثر بالحضارة الغربية .","s":"كان عددٌ قليل من العثمانيين قد نادى بالإصلاح للوصول إلى الوسائل التي حققت بها أوروبا قوَّتها خاصة في التنظيم العسكري والأسلحة الحديثة, وكان الداماد إبراهيم باشا الذي تولى الصدارة العظمى في عهد السلطان أحمد الثالث هو أول مسؤول عثماني يعترف بأهمية التعرف على الإصلاحات الأوربية؛ لذا فإنه أقام اتصالاتٍ منتظمةً بالسفراء الأوربيين المقيمين بالآستانة، وأرسل السفراءَ العثمانيين إلى العواصم الأوروبية، وبخا"},{"id":4059,"era":"c12","t":"خلع السلطان العثماني أحمد الثالث وتولية ابن أخيه محمود الأول .","s":"ثار الانكشارية على السلطان أحمد الثالث لعدم ميله إلى الحربِ مع الدولة الصفوية ورغبته في الصلح معهم، فقتلوا الصدرَ الأعظم والمفتي وأمير البحر، حتى امتد أذاهم وعصيانهم وعزلوا الخليفة أحمد الثالث بن مصطفى الثاني بعد أن دام في الخلافة سبعة وعشرين سنة وأحد عشر شهرًا، وبقي معزولًا حتى توفي عام 1149هـ، وقام الانكشارية بتولية ابن أخيه محمود الأول بن مصطفى الثاني."},{"id":4060,"era":"c12","t":"معركة كوريجان بين الدولة العثمانية والإيرانيين .","s":"وهي المعركة التي استرجعت فيها الدولة العثمانية مدينة همدان بعد انتصارها على الإيرانيين في معركة \"كوريجان\"، التي قُتل فيها ثلاثة أرباع الجيش الصفوي المكوَّن من 40 ألف جندي."},{"id":4061,"era":"c12","t":"وفاة الشاعر عبد الغني النابلسي .","s":"هو الشاعر عبد الغني بن إسماعيل النابلسي الشاعر المتصوف، وهو عالم بالأدب والتاريخ، ولد سنة 1050 بدمشق ونشأ بها، ثم رحل إلى بغداد، ثم تنقل بين سوريا وفلسطين ومصر ولبنان، ثم عاد واستقر في دمشق وبها توفي، له مصنفات عديدة، أشهرها: (تعطير الأنام في تعبير المنام)، وله (الحقيقة والمجاز في الرحلة إلى بلاد الشام ومصر والحجاز)، وله (التحفة النابلسية في الرحلة الطرابلسية)، وله (كنز الحقائق المبين في أحاديث سي"},{"id":4062,"era":"c12","t":"قتال العثمانيين مع الصفويين واسترجاع الصفويين ممتلكاتهم .","s":"اتجهت الدولة العثمانية إلى قتال الشيعة الصفوية، فتغلبت على طهماسب الذي طلب الصلح في هذا العام, وتخلى العثمانيون عن تبريز، وهمدان، ولورستان، غير أنَّ والي الشاه على خراسان وهو نادر شاه لم يقبل بهذه المعاهدة. فسار إلى أصفهان، وعزل الشاه طهماسب، وولى مكانه ابنه عباسًا، وعيَّنَ عليه مجلس وصاية، ثم سار نادر شاه لحرب العثمانيين فانتصر عليهم، وحاصر بغداد، فطلبت الدولة العثمانية الصلحَ، وجرى الاتفاق عام 1"},{"id":4063,"era":"c12","t":"استعادة الأسبان السيطرة على ميناء ومدينة \"وهران\" من العثمانيين .","s":"تمكَّنَ الأسبان من استعادة السيطرة على ميناء ومدينة \"وهران\" الجزائرية من العثمانيين. وكان العثمانيون قد فتحوا وهران قبل 24 عامًا، وخلصوها من الاحتلال الأسباني."},{"id":4064,"era":"c12","t":"حصار الشاه الإيراني لبغداد .","s":"حاصر الشاه الإيراني نادر شاه- بعد هزيمته العسكرية الكبيرة أمام العثمانيين- مدينة بغداد التي كانت خاضعة للدولة العثمانية، واستمرَّ هذا الحصار 7 أشهر و8 أيام."},{"id":4065,"era":"c12","t":"الفرس بقيادة نادر شاه يطردون الأفغان من بلادهم .","s":"كان نادر شاه في أول أمره من قطَّاع الطرق، ثم برز اسمه أيام الفوضى فجمع حوله الرجال ورأى من المصلحة العمل باسم الشاه الصفوي، فانتصر على الأفغان عام 1141هـ ولاحقهم، فاعتصم سلطانهم في مدينة أصفهان، فحاصره نادر شاه واستطاع أشرف سلطان الأفغان أن ينسحب نحو شيراز، وتابع نادر شاه الأفغانَ حتى أخرجهم من منطقة فارس عام 1142هـ، ولما أصبح الأمر لنادر شاه بعد موت الشاه عباس الثالث حارب الأفغان واستولى على قنده"},{"id":4066,"era":"c12","t":"هزيمة الشاه الإيراني على يد الدولة العثمانية .","s":"تلقى الشاه الإيراني نادر شاه هزيمةً قاسية من الدولة العثمانية أمام مدينة بغداد، في حرب استمَرَّت 9 ساعات، خَسِر خلالها نادر شاه 30 ألف جندي تقريبًا."},{"id":4067,"era":"c12","t":"افتتاح مدرسة الهندسة الإمبراطورية في الدولة العثمانية .","s":"تم افتتاح مدرسة الهندسة الإمبراطورية في الدولة العثمانية، وكان الهدف الأول من إنشائها هو تخريج ضباط الاستحكامات والمهندسين العسكريين للجيش العثماني."},{"id":4068,"era":"c12","t":"قيام دولة الأفشار بقيادة نادر شاه خلفا لدولة الصفويين .","s":"استطاع محمود بن أويس الأفغاني أن ينهي دولة الصفويين في إيران، ثم عقبه أشرف بن عبد العزيز  ابن عمه، وكان طهماسب بن حسين الصفوي الذي فرَّ من أصفهان يريد استرجاعَ الملك، وكان قد تعاقد مع الروس على أن يُعينوه ضدَّ الأفغان على أن يتخلى لهم عن البلاد الشمالية من إيران، وكان نادر شاه قائد جيوشه فزحفوا إلى أصفهان لطرد أشرف الأفغاني الذي تولى بعد محمود الأفغاني، وكان السكان الإيرانيون الذين بقوا في إيران ق"},{"id":4069,"era":"c12","t":"استيلاء الروس على قلعة \"أزاك\" من الدولة العثمانية .","s":"استطاع الروسُ الاستيلاءَ بشكلٍ مفاجئ على قلعة \"أزاك\" من الدولة العثمانية؛ مما تسبب في إعلان استانبول الحربَ على روسيا في 7 صفر 1149هـ."},{"id":4070,"era":"c12","t":"الحرب بين العثمانيين وبين الروس ومعهم النمسا .","s":"اتحدت النمسا مع روسيا لمحاربة تركيا، وكانت الدولة خارجة من حرب إيران فساقت روسيا جيوشها تحت قيادة الفلد مارشال مونيخ، حاصرت فرقةٌ منه قلعةَ أزوف (آزاق). ودخلت فرقةٌ أخرى من برزخ أورقبو، وهددت بلاد القرم، وهاجمت فرقةٌ ثالثة قلعةَ كيلبرون فاضطرت تركيا لإعلان الحرب عليها، وسار الصدر الأعظم على رأس الجيوش، وساقت النمسا جيوشها على قلعة شهر كوي، ودخلت عساكرُها بلاد البوسنة، ثمَّ تقدَّمت الجيوش التركية و"},{"id":4071,"era":"c12","t":"وفاة السلطان العثماني أحمد الثالث\n  .","s":"هو السلطانُ أحمد الثالث بن السلطان محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول، المولود في 3 رمضان سنة 1083/ 23 ديسمبر سنة 1673 وعند تعيينه سلطانًا للدولة وزع أموالًا طائلة على الانكشارية، وسلم لهم في قتل المفتي فيض الله أفندي لمقاومته لهم في أعمالهم, فلما استقرَّت الأحوال وعادت السكينة اقتصَّ السلطان أحمد من رؤوس الانكشا"},{"id":4072,"era":"c12","t":"الدولة العثمانية توقف تقدم روسيا في إقليم البغدان .","s":"أعلنت روسيا والنمسا الحرب على بولندا، واحتلَّتها روسيا، ورغبت فرنسا في التحالف مع الدولة العثمانية لإنقاذ بولندا من كلٍّ مِن النمسا وروسيا, فأرضت النمسا فرنسا بمعاهدة فيينا, واتفقت من جهة ثانية لقتال الدولة العثمانية، وبدأت روسيا القتالَ ضد الدولة العثمانية، فتمكَّن العثمانيون من وقفِ تقدُّم الروس في إقليم البغدان."},{"id":4073,"era":"c12","t":"توقيع الدولة العثمانية معاهدة استانبول مع إيران  .","s":"بعد حرب دامت ست سنوات بين الإيرانيين والدولة العثمانية، طلبت الدولة العثمانية توقيع معاهدة استانبول مع إيران بقيادة نادر شاه، وكانت المعاهدة في مدينة تفليس حيث نودي في حينه بنادر شاه ملكًا على إيران، على أن تردَّ الدولة العثمانية إلى إيران كلَّ ما أخذته منها، وأن تكون حدود الدولتين كما تقرر بمعاهدة سنة 1639م المبرمة في زمن السلطان الغازي مراد الرابع."},{"id":4074,"era":"c12","t":"إعلان ألمانيا الحرب على الدولة العثمانية .","s":"أعلنت ألمانيا الحربَ على الدولة العثمانية بعد هزيمة حليفتها روسيا أمام العثمانيين في شبه جزيرة القرم، ووقوع مائة ألف روسي في الأسر."},{"id":4075,"era":"c12","t":"نادر شاه حاكم إيران يفتح (كابل) و(غزنة) ويهزم قوات المغول .","s":"بعد أن استطاع نادر شاه السُّني اعتلاء عرش إيران بعد أن أنهى حُكمَ الصفويين فيها، أراد أول شيء أن يُخضِع الأفغان؛ لعلمه أنَّهم ربما يثورون عليه كما ثاروا على الصفويين قبله، بل هو الذي استطاع أن يستردَّ إيران من أيديهم، فاستعان بقطاع الطرق البختياريين الذين استطاع أن يلاحِقَهم حتى ألحقهم بجيشِه، واستطاع أن يفتحَ قندهار الحصينة، وكابل وغزنة, وكان رضا قلي ميرزا ابن نادر شاه على رأس جيشٍ أخذ يتقدَّم نح"},{"id":4076,"era":"c12","t":"توقيع الدولة العثمانية معاهدة \"بلغراد\" مع ألمانيا وروسيا .","s":"أوقفت الدولةُ العثمانيةُ تقدُّمَ الروس في بلاد البغدان والألمان في البوسنة والصرب والأفلاق، فانسحب الألمانُ من الحرب، وطلبوا الصلحَ عن طريق فرنسا، وتم توقيع معاهدة بلغراد بين الدولة العثمانية مع كلٍّ من ألمانيا من جهة، وروسيا من جهة أخرى، تعهَّد فيها الألمان بتسليم بلغراد للدولة العثمانية بعد احتلالٍ دام 22 سنة، وتعهدت روسيا بهدم قلاعِ ميناء آزوف وتسليم أرضِها للعثمانيين، وألَّا تُبحِرَ أيةُ سفينة"},{"id":4077,"era":"c12","t":"وفاة الشيخ عبد الوهاب بن سليمان التميمي والد الإمام المجدد  .","s":"هو عبد الوهاب بن سليمان بن علي بن مشرف التميمي النجدي، فقيه حنبلي، والد الشيخ المجدد محمَّد بن عبد الوهَّاب. من أهل العُيينة بنجدٍ، من علماء نجد وفقهائها، تولى القضاء في العُيينة, ثم انتقل منها ليتولى قضاء حريملاء. له كتابات في بعض المسائل الفقهية."},{"id":4078,"era":"c12","t":"طرد الشيخ محمد بن عبد الوهاب من حريملاء وانتقاله إلى العيينة .","s":"كان الشيخ عبد الوهاب بن سليمان والد الشيخ محمد بن عبد الوهاب قد انتقل إلى حريملاء وتولى القضاء فيها, فلما قَدِم الشيخ من رحلاته العلمية على والدِه في حريملاء أخذ يقرأُ عليه, ويُنكِرُ ما يفعلُه الجهَّال من البدع والشرك في الأقوال والأفعال، وكثُرَ منه الإنكار لذلك ولجميع المحظورات، حتى وقع بينه وبين أبيه كلام، وكذلك وقع بينه وبين الناس في البلد, فأقام على ذلك مدة سنين، حتى توفي والده في هذه السنة، ف"},{"id":4079,"era":"c12","t":"حدوث شغب العبيد على السلطان مولاي عبد الله بالمغرب .","s":"لما كان شهر ربيع الأول من هذه السنة، شغَّب العبيد على السلطان مولاي عبد الله بن إسماعيل بن مولاي علي الشريف العلوي, وهمُّوا بخلعه والإيقاع به، فنذرت بذلك أمه الحرة خناثى بنت بكار، ففرت من مكناسة إلى فاس الجديد، ومن الغد تبِعَها ابنها السلطان المولى عبد الله، ونزل برأس الماء فخرج إليه الودايا وأهل فاس وأجَلُّوا مَقدَمَه واهتزُّوا له، فاستعطفهم السلطان وقال لهم: أنتم جيشي وعدتي، ويميني وشمالي، وأريد"},{"id":4080,"era":"c12","t":"مبايعة مولاي زين العابدين بن إسماعيل سلطانًا على المغرب .","s":"كان ابتداءُ أمر السلطان مولاي زين العابدين بن إسماعيل العلوي أنَّه قَدِم مكناسة في أيام أخيه مولاي المستضيء، فلما سمع به أمَرَ بسجنه وضربه، فضُرب وهو في قيده ضربًا وجيعًا أشرف منه على الموت، ثم أمر ببعثه مقيَّدًا إلى سجلماسة؛ كي يُسجَن بها مع بعض الأشراف المسجونين هنالك، فلما سمع بذلك قوَّاد رؤوسهم من العبيد، بعثوا مَن رَدَّه من صفرو إلى فاس، ثم بعثوا به إلى القائد أبي العباس أحمد الكعيدي ببني ياز"},{"id":4081,"era":"c12","t":"طرد الشيخ محمد بن عبد الوهاب من العيينة  .","s":"بعد أن طلب أميرُ الأحساءِ وزعيمُ بني خالد: سليمان بن محمد بن غرير آل حميد الخالدي من حاكِمِ العُيينة التخلُّصَ مِن الشيخ محمد بن عبد الوهاب, فكتب إلى عثمان يتوعَّدُه ويأمُرُه أن يقتُلَ هذا المطَوَّع الذي عنده في العُيينة, وقال: إن المطوع الذي عندكم بلغنا عنه كذا وكذا، فإما أن تقتُلَه، وإما أن نقطَعَ عنك خراجَك الذي عندنا!! وكان عنده للأمير عثمان خراجٌ من الذهب، فعظم على عثمانَ أمرُ هذا الأمير، وخا"},{"id":4082,"era":"c12","t":"تحالف الأمير محمد بن سعود مع الشيخ محمد بن عبد الوهاب .","s":"خرج الإمامُ محمد بن عبد الوهاب من العُيينة بنجدٍ يدعو إلى دينِ الله القويم، وقد كانت منطقةُ نجد في هذه الفترة انتشر فيها الشِّركُ والبِدَع، فلقي الشيخُ صعوبات كثيرة إلى أن يسَّرَ الله له الأميرَ محمد بن سعود أمير الدرعية، فتم بينهما اتفاقٌ تاريخي في هذا العام عُرِف \"باتفاق الدرعية\" لَمَّا وصل الشيخ محمد بن عبد الوهاب إلى الدرعية دخل على شخصٍ مِن خيارها في أعلى البلد يقال له: محمد بن سويلم العريني،"},{"id":4083,"era":"c12","t":"وفاة الشيخ محمد بن علي التهانوي .","s":"هو الشيخ الفاضل محمد بن علي بن حامد بن صابر بن الفاروقي التهانوي الهندي الحَنَفي: أحدُ رجال العلم، اشتُهر بكتابه الشهير: كشاف اصطلاحات الفنون. عاش التهانوي في عصر سلاطين الدولة المغولية في الهند، فأدرك طَرَفًا من عهد الإمبراطور أورنغ زيب عالمكير الذي عرفت الهندُ في عصره حركةً علمية ثقافية نَشِطةً بتشجيعه لها. وقد قيل: إن التهانوي كان قاضيًا في قريته تهانة في عصر هذا الإمبراطور. نشأ التهانوي في بيئ"},{"id":4084,"era":"c12","t":"ابتدأ الصراع العسكري بين الدرعية والرياض .","s":"ظلَّت دعوة الشيخ محمد بن عبد الوهاب في نجد سلميةً دون الدخولِ مع خصوم الدعوة في أي صدامٍ عسكري منذ الاتفاق التاريخي بين أمير الدرعية والشيخ محمد بن عبد الوهاب عام 1157 إلى هذا العام، حين ابتدأ الصراع العسكري بين الدرعية والرياض، بعد انضمام منفوحة إلى دعوة الشيخ محمد بن عبد الوهاب في هذه السنة، حيث قام دهام بن دواس أميرُ الرياض بالهجوم على المنفوحة الذين لبَّوا دعوة الشيخ محمد بن عبد الوهاب ودخلوا "},{"id":4085,"era":"c12","t":"وقعة العمارية بين جيش الرياض وجيش الدرعية .","s":"هاجم أميرُ الرياض دهام العماريةَ المواليةَ للدرعية وقتل أميرَها عبد الله بن علي وعقر إبِلَه، فلما بلغ ذلك الإمام محمد بن سعود جمع أهل الدرعية وعرقة، وأراد أن يرصد عودة جيش دهام من العمارية ويكمن له، وكان دهام بن دواس قد كمن في الموضعِ نفسه فالتقى الفريقان واقتتلوا قتالًا شديدًا انهزم فيه دهام، وجَدَّ أهل الدرعية في إثرِه ولكنهم فُوجئوا بخروج فرقة لابن دواس من جهة العمارية، فوقع القتل وانكسر جيشُ ا"},{"id":4086,"era":"c12","t":"وقعة الشياب بين جيش الرياض وجيش الدرعية .","s":"أخذت الدرعية بثأرِها من دهام بن دواس بعد وقعةِ العمارية حينما قام الأميرُ محمد بن سعود بحملةٍ على دهام وجَرَت موقعةٌ في مكان يقال له الوشام، انهزمت فيها قوات الرياض، ودُعِيت بوقعة \"الشياب\" لأنه قتل فيها شايبان (أي شيخان مُسِنَّان) من آل شمس من أهل الرياض."},{"id":4087,"era":"c12","t":"وقعة العبيد بين جيش الرياض وجيش الدرعية .","s":"أراد الأميرُ محمد بن سعود أن يلاحِقَ دهامًا ويُلحِقَ به هزيمة منكرة، فقام بحملة أخرى على الرياض كانت نتيجتها هزيمة دهام مرة أخرى، وسميت هذه الوقعة \"وقعة العبيد\"؛ لأنَّ معظم من قُتِلَ من رجال دهام كانوا من العبيدِ."},{"id":4088,"era":"c12","t":"انتقام دهام بن دواس من الدرعية .","s":"جهَّز دهام بن دواس أميرُ الرياض جيشًا وهاجم الدرعية، ولما اندفعت نحوه قواتُها تظاهر بالتقهقر فظَنَّ جيش الدرعية أنَّ جيش دهام قد انهزم، إلا أن جيش الرياض كان قد نصب كمينًا لجيش الدرعية، فكانت الهزيمة لجيش الدرعية، وقُتِلَ فيها الأميران فيصل وسعود ابنا الإمام محمد بن سعود، وكل هذه الحروب كانت في هذه السَّنةِ، وذكر ابن بشر أنَّها كانت سنة 1160."},{"id":4089,"era":"c12","t":"أول غارة من الدرعية على قصر أمير الرياض .","s":"بعد أن جهر أميرُ الرياض دهام بن دواس بعداوتِه وانكشف غدرُه في هجومِه على المنفوحة، انتدب  الأمير محمد بن سعود جماعةً توجَّهت ليلًا إلى الرياض فدخلوها وأتوا باب القلعة التي فيها دهام، فشذبوا البابَ بالمنشار ودخلوا بيت ناصر بن معمر وتركي بن دواس، فعقروا فيهما إبلًا كثيرةً، ورموا بالرصاص دهام بن دواس وهو في عليَّة قصره ثم عادوا إلى الدرعية سالمين."},{"id":4090,"era":"c12","t":"غدر عثمان بن معمر أمير العيينة بأمير الدرعية وتراجعه عن نصرة الدعوة  .","s":"كانت وقعةُ دلقة من غير رضاء أمير العُيينة ابن معمر ولم يشاوَرْ فيها؛ لذلك لم يحضُرْها. يقول ابن غنام: \"لما رأى ابنُ معمر عودةَ الجماعة من الحرب خَشِيَ أن ينكشف نفاقُه وأن تظهر خيانته, فأرسل إلى الشيخ وإلى محمد بن سعود يستشفع إليهما, ويطلب منهما الصفحَ عن تخلُّفِه، فقبلا عذره رجاءً منهما ألا يعودَ إلى مكره, ثم قَدِمَ عليهما ومعه وجوهُ أهل حريملاء والعُيينة، وعاهدهما على الجهاد والقيام بنصرة الدين، "},{"id":4091,"era":"c12","t":"نشوب موقعة الدلقة بين جيش الدرعية وجيش الرياض .","s":"قامت الدرعية بقيادة أميرِها محمد بن سعود بتجهيز جيشٍ قوي للهجوم على الرياض، ردًّا على هزيمة الدرعية في \"وقعة العبيد\"، إلَّا أن أحد أهالي بلدة حريملاء يقالُ له أبو شيبة من آل داود، ويدعى أبو شيبة كان قد أفشى للرياض سرَّ المعلومات التي هيأتها الدرعية لمهاجمة الرياض, فصَبَّحهم الأمير محمد بن سعود وجماعته فإذا هم مستعِدُّون والتقوا في جوف البلد فاقتتلوا قتالًا شديدًا، وحمي القتال عند باب القصر، وأصيب "},{"id":4092,"era":"c12","t":"وفاة الملك نادر شاه مؤسسة أسرة الأفشار في إيران .","s":"هو الملك نادر شاه الأفشار التركماني، ويعرف كذلك باسم \"نادر قـُلي بگ\" ولد نادر شاه في محرم 1100هـ/ 22 نوفمبر 1688م وجلس على العرش في شوال 1148هـ وهو مؤسِّس الأسرة الأفشارية التي حكمت إيران. كانت قبيلةُ أفشار هي إحدى القبائل التركمانية التي فرَّت من وجه المغول تاركةً تركستان، واستقرت في أذربيجان، فأرسل الشاه إسماعيل الصفوي قِسمًا من هذه القبيلة إلى الجزء الشمالي من خراسان وأسكنهم فيها بالقرب من منبع"},{"id":4093,"era":"c12","t":"حصول وقعة البنية ووقعة الخريزة بين جيش الدرعية وجيش الرياض .","s":"قام عثمانُ بن معمر أمير العيينة بمعاهدة الأمير محمد بن سعود على الحربِ معه، فقاد جيشُ الدرعية ضِدَّ جيش الرياض، وانهزم بعد قتالٍ شديد قُتِل فيه أناس كثيرون، ثم حدثت وقعة أخرى سار فيها عبد العزيز بن محمد بن سعود بأهل الدرعية وضرما، وتولى عثمان بن معمر قيادةَ قوات العُيينة وحريملاء، كما أنه كان الأمير عليهم جميعًا واشتبك مع جيش الرياض في مكان يدعى \"الخريزة\" قرب الرياض، وكانت النتيجة متكافئة، وتلت ذل"},{"id":4094,"era":"c12","t":"قيام دولة أمراء أفغانستان .","s":"برز أحمد خان الدوراني الذي كان يقود الأفغان والأوزبك في جيش نادر شاه، وعندما قُتل نادر شاه عام 1160هـ في شروان أسرعت الفرقة الأفغانية التي كانت معه عائدةً إلى بلادها واستقَرَّت في قندهار، ونادت بقائدها أحمد خان الذي كان قد تقاتل مع بقية القادة وهُزِمَ فانسحب إلى قندهار أيضًا، وأسس فيها مملكة الأفغان وعاصمتها قندهار، وبدأ أحمد خان شاه يوسِّع دولته؛ فقد ضم إليها كشمير ولاهور والملتان، وقاتل السيخ وا"},{"id":4095,"era":"c12","t":"وفاة العلامة إسماعيل العجلوني .","s":"هو الشيخ العلامةُ الإمام العالمُ الهُمام الحجَّة الرُّحلة العمدة: أبو الفداء إسماعيل بن محمد بن عبد الهادي بن عبد الغني، الشهير بالجراحي- نسبة إلى أبي عبيدة بن الجراح- العجلوني الدمشقي، محدِّث الشام في أيامه. وُلِد بعجلون (بالأردن) سنة 1087 نشأ بدمشق وفيها توفي. كان عالِمًا بارعًا صالحًا مفيدًا محدِّثًا مبجَّلًا قدوة سندًا خاشعًا. له يدٌ في العلوم لا سيما الحديث والعربية، وكان شافعيًّا صوفيًّا، له"},{"id":4096,"era":"c12","t":"وقعة البطحاء بين جيش الدرعية وجيش الرياض .","s":"جرت وقعة البطحاء في الرياض، وذلك أن محمد بن سعود سار بجنودِه إلى الرياض ليلًا ووصل المكان المعروف بباب المروة ومعه رجال مشهورون بالشجاعة، منهم علي بن عيسى الدروع، وسليمان بن موسى الباهلي، ومحمد بن حسن الهلالي، وعلي بن عثمان بن ريس، وعبد الله بن سليمان الهلالي، وإبراهيم الحر، فخرج إليهم أهلُ الرياض ووقع قتال شديد، قُتل فيه من أهل الرياض سبعةُ رجال, واثنان من أهل الدرعية."},{"id":4097,"era":"c12","t":"أهل الدرعية بقيادة عبد العزيز بن محمد يغزون ثرمداء .","s":"سارت قوةٌ من أهل الدرعية وأميرُهم عبد العزيز بن محمد إلى ثرمداء، وكان النذيرُ قد جاء أهل ثرمداء بذلك، فاستعانوا بأهل وثيثيا ومرات، فالتقى بهم جيش الدرعية وهم مستعدون للقتال في موضع قريب من ثرمداء يسمى الوطية، وكان جيش الدرعية قد أعدوا كمينًا، فلما نشب القتال خرج عليهم الكمين فولَّوا مدبرين وقتل منهم خمسة وعشرون، منهم علي بن زامل أمير وثيثيا"},{"id":4098,"era":"c12","t":"وفاة عثمان بن معمر أمير العيينة .","s":"هو عثمانُ بن حمد بن عبد الله بن محمد بن حمد بن عبد الله بن محمد بن حمد بن حسن بن طوق بن سيف آل معمر، من العناقر، من بني سعد من بني تميم: أمير العيينة. تولى إمارتها خلفًا لأخيه محمد, وهو جدُّ سعود الكبير بن عبد العزيز بن محمد ثالث حكام الدولة السعودية الأولى. كان ابن معمر آوى الشيخ محمد بن عبد الوهاب في العيينة ووعد بنصره بعد خروجه من حريملاء، لكنه طرد  الشيخَ من العيينة بعد أن تلقَّى ابن معمر  تهد"},{"id":4099,"era":"c12","t":"غزو منطقة سدير لضمها تحت لواء دولة الدرعية الناشئة .","s":"قامت دولةُ الدرعية الناشئة بعدة غزوات ضد بلدان منطقة سدير التي رفضت الدعوة، ورفضت الانضواءَ تحت لواء الدولة الناشئة. والتي بدأت غزواتُها للمنطقة في هذه السنة، واستمرت حتى عام 1177هـ. وفي هذه الفترة استطاعت نشرَ مبادئ الدعوة في كلٍّ من الزلفي وجلاجل والحوطة والجنوبية والروضة والتويم والغاط والداخلة والعودة وحرمة، وغيرها من المدن والبلدان، في هذه المنطقة."},{"id":4100,"era":"c12","t":"نقض أهل حريملاء عهدهم مع دولة الدرعية .","s":"بعد أن أعلنت حريملاء خضوعَها لدولة الدرعية في أوَّلِ الأمر، ثم قام بعض أهلها في هذه السنة بتحريضٍ من قاضيها سليمان بن عبد الوهاب شقيق الشيخ محمد بن عبد الوهاب الذي كان معارضًا لآراء أخيه، قاموا بنقضِ عَهدِهم مع الدعوة والدولة، وأخرجوا من البلدة من لم يستجِبْ دعواهم، ومن بينهم الأمير محمد بن عبد الله بن مبارك، وأخوه عثمان، فقصد هؤلاء المطرودون بلدة الدرعية ونزلوا ضيوفًا على أميرها، ولما خَشِي المتم"},{"id":4101,"era":"c12","t":"عدوان أهل سدير والوشم على أتباع دعوة التوحيد .","s":"اجتمع أهلُ سدير والوشم ومعهم آل ظفير، واتجهوا إلى رغبة، وكان أهلها قد اهتَدَوا إلى التوحيد, فحصرتهم تلك الجموعُ في البلد أيامًا، فجنح بعض أهلها إلى الضَّلالِ فأدخلوا تلك الأجناد فنَهَبوا  جميع الأموال، ولكِنَّ الله حقن دماء المسلمين, ثم اتجهت تلك الجموع ومعهم جلوية ضرمى إلى ضرمى- الذين دخل أهلها في طاعة الدرعية- فحصَروا أهلها أيامًا ونصبوا السلالم على أسوارها، وصعد منهم السور نحو ثلاثين رجلًا قُتل"},{"id":4102,"era":"c12","t":"رجوع أهل منفوحة عن تأييد دعوة التوحيد متابعتها .","s":"رجع أهلُ المنفوحة عن تأييد دعوة التوحيد، ونبذوا عهدَهم مع الدرعية وطردوا إمامَهم محمد بن صالح, وخرج معه سبعون رجلًا من المؤيدين لها, ثم تلاحق الناسُ بعد ذلك فارِّين بدينهم."},{"id":4103,"era":"c12","t":"وفاة أسعد أفندي  شيخ الإسلام في الدولة العثمانية .","s":"هو شيخُ الإسلام أسعد أفندي بن أبي إسحاق إسماعيل أفندي، رئيسُ المشيخة في الدولة العثمانية. وكان قد تولَّى المشيخة في رجب 1161هـ، ولكنَّه لم يستمر في منصبه طويلًا. وللشيخ مؤلَّفات وبحوث في اللغة التركية، من أشهرها: معجم تركي بعنوان: \"لهجة اللغات\"."},{"id":4104,"era":"c12","t":"موقف الشيخ محمد بن عبد الوهاب وكبار أنصاره من خصوم الدعوة .","s":"اجتمع في الدرعية الشيخ محمد بن عبد الوهاب والإمام محمد بن سعود، بالإضافة إلى كبار أنصار الدعوة الذين قدموا من مختلف البلدان للتباحث في شؤون الدعوة والمواقف اللازم اتخاذها ضد أعدائها، وكان دهام بن دواس قد تضجَّر من الحرب مع آل سعود، فلما سمع بهذا التجمع مال إلى المهادنة، وطلب من الشيخ محمد بن عبد الوهاب والإمام محمد بن سعود عقدَ صُلحٍ بينه وبين الدرعية، وتعهد باعتناق مبادئ الدعوة السلفية، إلَّا أنه"},{"id":4105,"era":"c12","t":"وفاة السلطان العثماني محمود الأول وقيام أخيه عثمان الثالث خلفًا له .","s":"هو الخليفةُ العثماني محمود الأول ابن السلطان مصطفى الثاني ابن السلطان محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول. وُلِدَ في 4 محرم سنة 1108هـ 3 أغسطس سنة 1696 تولى السلطان محمود السلطنة بعد ثورة على السلطان أحمد الثالث الذي كان يميل إلى مصالحة الدولة الصفوية, فثار عليه الانكشارية في  15 ربيع الأول 1143 فقتلوا الصدرَ الأع"},{"id":4106,"era":"c12","t":"السلطان العثماني عثمان الثالث يضيق الخناق على الذميين .","s":"كان من أوائل ما قام به السلطان عثمان الثالث بعد توليه السلطنةَ مَنْعُ كلِّ ما يخالف الشرعَ، سواء كان ما يفعله النصارى واليهود أو غيرُهم، فشَدَّد بذلك الخناقَ على أهل الذمَّةِ الذين كانوا قد توسَّعوا أكثر من حقوقِهم، وخاصة تحت اسم الحماية التي كانت عليهم من قِبَل دولهم النصرانية الأوربية تحت ظلِّ البابوية. كما اهتم بالإصلاحاتِ الداخلية، وأُسِّسَت في عهده مطبعة, وقمَعَ كثيرًا من الثورات الداخلية."},{"id":4107,"era":"c12","t":"انضمام بلدة حريملاء إلى دعوة الشيخ محمد بن عبد الوهاب .","s":"سار الأميرُ عبد العزيز بن محمد في نحو 800 رجل ومعهم من الخيل 20 فرسًا، فأناخ شرقيَّ البلد ليلًا، وكمن في موضعين، فصار عبد العزيز ومعه عِدَّةٌ من الشجعان في شعيب عوجا، وكمن مبارك بن عدوان مع 200 رجل في الجزيع، فلما أصبحوا شنُّوا الغارةَ، فخرج أهل حريملاء واشتد القتالُ حتى فرَّ أهل حريملاء في الشعاب والجبال بعد أن قُتِلَ منهم 100 رجل، وغنم جيش الدرعية منهم كثيرًا من الذخائر والأموال، وقُتل من جيش ال"},{"id":4108,"era":"c12","t":"نقض دهام بن دواس أمير الرياض العهد مع الدرعية .","s":"نقض دهام بن دواس عهدَه مع الأمير محمد بن سعود أمير الدرعية، فعدا على أهل أبي الكباش، ثم رجع فلمَّا تبيَّنَ منه أهلُ الدِّينِ في الرياض المكرَ والغدرَ تركوا أموالَهم وبلدهم وهاجروا إلى منفوحة، ثم هاجروا إلى الدرعية، لما تبين لهم أن رئيس المنفوحة محمد بن فارس قد انضمَّ مع دهام بن دواس في نقضِ العَهدِ."},{"id":4109,"era":"c12","t":"حدوث موقعة الدار بين دهام بن دواس وحلفائه وجيش الدرعية .","s":"تجهَّز دهام بن دواس لمحاربة الدرعية الحربَ الثانية، فاجتمع معه محمد بن فارس رئيس المنفوحة وإبراهيم بن سليمان رئيس ثرمداء، ومعهم أناسٌ مِن أهل سدير وأهل ثادق وجلوية حريملاء، واتجهوا إلى بلدة حريملاء فوصلوها ليلًا، ودخلوا محلة بأعلى البلد تسمَّى الحسيان، وكان الناس وأغلب الحرسِ نائمين، فلم يشعر بهم أحدٌ حتى ملكوا المحلَّةَ وبساتينها, فلما علم أميرُ البلدة مبارك بن عدوان  نهض مع جماعتِه في الليل وقات"},{"id":4110,"era":"c12","t":"استقرار أسرة الصباح في حكم الكويت وتولي الشيخ صباح الأول حكم البلاد .","s":"سعى المستوطِنون الأولون آلُ الصباح من العتوب في الكويت، إلى تأمين مركزِهم في إمارتهم الناشئة، وذلك بالاعترافِ بشيء من الولاء للدولة العثمانية. فأوفدوا زعيمَهم الأول، صباح بن جابر، إلى الوالي العثماني في بغداد؛ ليطلب منه تأييدَ الدولة العثمانية لهم، وإقرارها لاستقرارهم وأمنهم، فضلًا عن إظهارِ رغبتِهم في العيش في سلامٍ، وتعهُّدهم بحفظ الأمن والاستقرار في المنطقة، وقد نجح زعيمُ أُسرة الصباح في مسعاه "},{"id":4111,"era":"c12","t":"انضمام بلدة القويعية إلى دعوة الشيخ محمد بن عبد الوهاب .","s":"انضمَّت بلدة القويعية في منطقة الوشم إلى دعوة الشيخ محمد بن عبد الوهاب، وأعلن أهلُها الطاعةَ وبايعوا الشيخَ محمد بن عبد الوهاب والإمامَ محمد بن سعود, والتزموا بالسَّمع والطاعة، وصَدَقوا ووفَوا فلم ينخلعوا منها ولم يَنقُضوا عهدهم, وكان أول مَن وفد منهم على الشيخ والأميرِ: ناصِرُ بن جماز العريفي وسعود بن حمد."},{"id":4112,"era":"c12","t":"السلطان عثمان الثالث يقتل الصدر الأعظم بعد أن تبين له ظلمه للرعية .","s":"كان السلطان عثمان الثالث بعد توليه الخلافة قد عيَّن في منصب الصدارة العظمى نشانجي علي باشا بدلًا من محمد سعيد باشا, فاعتمد علي باشا هذا على ميلِ السلطان إليه, فسار في طريقٍ غيرِ حميدٍ، حتى أهاج ضِدَّه الأهالي أجمعين، ولكون السلطان كان من عادته المرور ليلًا في الشوارع والأزقة متنكرًا لتفَقُّدِ أحوال الرعية والوقوف على حقيقة أحوالِهم، سمع أثناء تَجوالِه بما يرتكبه وزيرُه من أنواع المظالم والمغارم، و"},{"id":4113,"era":"c12","t":"هجوم أهل الوشم وسدير على شقراء  .","s":"تجمَّع أهلُ الوشم وسدير في بلدة القرين في ناحية الوشم يريدون غزوَ أهل شقراء بعد أن انضمَّ أهلها للدعوة, فبَقُوا في القرائن ثلاثة أيام وهم يناوشون أهل شقراء الحربَ، فلما علم بذلك الأمير محمد بن سعود- وكان أهل شقراء من السابقين في متابعةِ دعوة الشيخ محمد بن عبد الوهاب- طلب منهم أن يخرُجوا إليهم ويشاغلوهم حتى يأتيَهم المددُ، ثم أرسل ابنَه الأمير عبد العزيز مع جنوده، الذي تمكن من هزيمة أهل الوشم وسدير"},{"id":4114,"era":"c12","t":"انضمام بلدة ثادق إلى دعوة الشيخ محمد بن عبد الوهاب .","s":"غزا الأمير عبد العزيز بن محمد بقوَّاته أهل ثادق فنازلوهم وقطعوا شيئًا من نخلهم وتراموا بالرصاص من بعيدٍ، حتى قتلوا منهم 8 رجال وحاصروهم زمنًا، فطلب أهل ثادق المصالحةَ وأقبلوا على دعوة الشيخ محمد بن عبد الوهاب، ووفدوا عليه في الدرعية وأمَّرَ عليهم دخيلَ بن سويلم، وأرسل معهم أحمد بن سويلم يعلِّمُهم التوحيدَ والأحكام."},{"id":4115,"era":"c12","t":"عزل مبارك بن عدوان عن إمارة حريملاء ثم تمرده عن الطاعة .","s":"عزل الشيخُ محمد بن عبد الوهاب والأميرُ ابنُ سعود مباركَ بنَ عدوان عن إمارةِ حريملاء؛ وذلك لأنهما تخوَّفا على أهل حريملاء منه لأمورٍ صدرت ونُسِبت إليه وأمَّرا مكانه أحمد بن ناصر, فاستأذن ابن عدوان من الشيخ ومن الأمير أن يذهَبَ إلى عُيينة ثم يعود اليهما في الدرعية، فأذنا له فلما خرج متظاهِرًا بالذهاب إلى العيينة التقى في الطريق بأناسٍ من أهل حريملاء فأغراهم بالرجوعِ عن طاعة الشيخ والأمير، فأطاعه فري"},{"id":4116,"era":"c12","t":"وفاة السلطان العثماني عثمان الثالث وتولية مصطفى الثالث خلفًا له .","s":"هو السلطانُ العثماني عثمانُ الثالث ابن السلطان مصطفى الثاني بن محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول. وُلِدَ السلطان عثمان سنة 1110هـ سنة 1696م وبعد أن تقلَّدَ السيف في جامعِ أبي أيوب الأنصاري على حَسَبِ العادة القديمة وأبقى كبار الموظفين في وظائفهم عيَّن في منصب الصدارة العظمى نشانجي علي باشا بدلَ محمد سعيد باشا ثم"},{"id":4117,"era":"c12","t":"تولي محمد الأول بن عبد الله ملك العلويين في المغرب خلفا لأبيه  .","s":"تولى محمَّدٌ الأول بن عبد الله بن إسماعيل ملك العلويين في المغربِ الأقصى الفرعَ الحسني خلفًا لأبيه عبد الله, في 20 صفر, فجدَّد للدولة قوَّتَها بعد تلاشيها، وأحياها بعد خمود جمرتها وتمزيقِ حواشيها، بحُسن سيرتِه ويُمن نقيبتِه."},{"id":4118,"era":"c12","t":"هجوم زعيم بني خالد مع حلفائه على حريملاء والجبيلة .","s":"عزم الحاكِمُ الخالدي عريعر بن دجين وحلفاؤه الهجومَ على الدرعية والقضاء على دعوة الشيخ محمد بن عبد الوهاب التي كانت تحت حمايةِ محمد بن سعود أميرِ الدرعية. فأمر الشيخُ والأمير جميعَ أتباعِهم في بلدان نجدٍ بالاستعداد والتحصُّن، وبنى عبد العزيز بن محمد على الدرعية سورينِ عليهما البروج, فلمَّا بدأ عريعر بالخروجِ ومعه أهل الأحساءِ وبنو خالد وأهل سدير والوشم والرياض والخرج، ويعاوِنُهم في ذلك كلُّ من ناصب"},{"id":4119,"era":"c12","t":"انضمام ثرمداء إلى دعوة الشيخ محمد بن عبد الوهاب .","s":"انضمَّت ثرمداء في منطقة الوشم إلى دعوة الشيخ محمد بن عبد الوهاب، وأصبحت خاضعةً للدرعية، وذلك بعد أن قاد الأمير عبد العزيز بن محمد عِدَّةَ حملات عسكرية ضِدَّها بداية من عام 1161هـ."},{"id":4120,"era":"c12","t":"عزل أمير العيينة مشاري بن معمر .","s":"عزل الشيخُ محمد بن عبد الوهاب والأميرُ ابن سعود مشاري بنَ معمر عن إمارة العُيينة؛ لأمور كثيرة ثبتت عليه، وأمَّر عليها سلطان بن محيسن المعمري، وأمَرَ الشيخ بهدم قصر آلِ معمر."},{"id":4121,"era":"c12","t":"انضمام بلدتي الفرعة وأشيقر إلى دعوة الشيخ محمد بن عبد الوهاب .","s":"سار الأميرُ عبد العزيز ومَن معه إلى بلدة الفرعة في منطقة الوشم، فخرج أهلُها لقتال عبد العزيز، فلما ظهر عليهم كمينٌ أعده عبد العزيز انهزموا وقُتِلَ منهم سبعة رجال، وبعد أيام وفد أهل الفرعةِ على الشيخ محمد وبايعوه على السمعِ والطاعة، ورئيسُهم منصور بن حمد بن إبراهيم بن حسين، واستقاموا على البيعة، ثم حارب أهل الفرعة مع قواتِ الدرعية أهلَ أشيقر سبعَ سنوات حتى استولوا على أبراجِها, فدخل أهل أشيقر بسبب "},{"id":4122,"era":"c12","t":"وفاة الشيخ صباح الأول الصباح أمير الكويت, وتولى ابنه عبد الله .","s":"هو الشيخُ صباحُ الأول بن جابر الصباح في الكويت، وهو من عشيرة الشملان من بني عتبة من جُميلة من عنزة من ربيعة: جد أمراء آل الصباح؛ حُكَّام الكويت، وأولُ من حكم الكويت بعد تأسيسها. يُرَجَّح أنَّ أصله من الهدار من منطقة الأفلاج في نجدٍ، وقد بُنِيت الكويت في عهده، وفي مذكرات خالد الفرج: أنَّ الكويت حديثةُ البناء، كان موضِعُها يسمى \"القرين\"، وكانت السلطة في القرين لبني خالد، ورئيسُهم في أواخر القرن الحا"},{"id":4123,"era":"c12","t":"تولي الشيخ عبد الله الأول بن صباح الأول الحكم في الكويت .","s":"تولَّى حكمَ الكويت الشيخُ عبد الله الأول بن صباح الأول بن جابر، وكان ذلك بعد وفاة أبيه، وقد حَسُنت سيرته، وكان عاقلًا يوصَفُ بالشجاعة والكرم، وانتعشت الكويتُ في عهده، واستمَرَّ في الحكم إلى أن توفي، وفي أيامه هاجَرَ آل خليفة (حكام البحرين) إلى الكويت."},{"id":4124,"era":"c12","t":"وفاة العلامة شاه وَليُّ الله الدهلوي .","s":"هو العلامةُ كوكب الديار الهندية شاه وَليُّ الله أبو عبد العزيز قطبُ الدين أحمد بن عبد الرحيم الفاروقي الدهلوي، من علماءِ الهند البارزين, وهو فقيهٌ حنفي من المحدِّثين من أهلِ دهلي بالهند، ولِدَ سنة 1110هـ  زار الحجاز سنة 1143 - 1145هـ. قال صاحب فهرس الفهارس: \"أحيا الله به وبأولاده وأولاد بنتِه وتلاميذِهم الحديثَ والسنَّةَ بالهند بعد مواتهما، وعلى كتبه وأسانيده المدارُ في تلك الديار\" كان فصيحًا بالل"},{"id":4125,"era":"c12","t":"غزو الأمير عبد العزيز بن محمد الأحساء ديار بني خالد .","s":"غزا الأميرُ عبد العزيز بن محمد الأحساءَ ديارَ بني خالد خصومِ الدَّعوةِ، وكانت خيلُهم نحو 30 فرسًا، فأناخ عبد العزيز في مكانٍ يسمى المطيرفي، وهجم على من كان فيه من أهلِها، فقتل منهم سبعين رجلًا، وأخذوا منهم كثيرًا من الأسلحة والأمتعة والدواب. فلما أرادو الرجوعَ إلى نجد أغاروا على المبرز، ونالوا من أهلها."},{"id":4126,"era":"c12","t":"أمير الرياض دهام بن دواس يطلب الصلح من أهل الدرعية .","s":"طلب أميرُ الرياض دهـام بن دواس الصلحَ من الشيخ محمد بن عبد الوهاب والإمـام محمد بن سعود، ومع علمِهما بأنَّه لا يفي بوعده إلَّا أنهما وافقا بشروط، منها: أن يقبَلَ دهام بعودة أنصار الدعوة إلى الرياضِ بعد أن كان قد اضطرَّهم إلى الهجرةِ منها, وأن يردَّ دهام إلى المهاجرين الأموالَ التي صادرها منهم في الرياض حين هجرتِهم منها, وأن يسوقَ إلى الدرعية ألفَي (ريال) أحمر معجَّلة, فالتزم دهام بهذا الصلحِ إلى و"},{"id":4127,"era":"c12","t":"شركة الهند الشرقية الهولندية تسيطر على البصرة .","s":"استطاع الهولنديون أصحابُ شركة الهند الشرقية الهولندية أن يدخُلوا الخليج العربي عن طريقِ تحالُفِهم مع الإنكليز، ثم إن الهولنديين أرادوا التوغُّلَ بتجارتهم وأطماعِهم أكثَرَ من ذلك، فاستطاعوا الظهورَ في البصرة بعد أن عرفوا أنَّ التجارةَ فيها رابحةٌ، فمدُّوا نشاطَهم إلى العراق، وأرسلوا سفُنَهم إلى البصرة، واستطاعوا أن يأخذوا السوقَ من الإنكليز وخاصة بوجود الامتيازات الممنوحة لهم من قِبَل علي باشا من أ"},{"id":4128,"era":"c12","t":"غزو عريعر بن دجين الدرعية بمساندة خصوم الدرعية في نجد .","s":"بعد هزيمةِ جيش الدرعية في وقعةِ الحاير أرسل عريعر بن دجين حاكمُ بني خالد في الأحساءِ إلى الحسن هبة الله المكرمي يدعوه إلى البقاءِ في نجد حتى يقدَمَ عليه بجيوشِه ليشتركوا في قتال الدرعية, لكِنَّ المكرمي كان قد كاتب حُكَّام الدرعية بعد واقعة الحاير على تبادُلِ الأسرى، فلما أطلق الأسرى من الجانبين عاد إلى بلادِه، بعد أن مكث في نجد 15 يومًا. خرج عريعر مع بني خالدٍ كافةً وأهل الأحساء، فلم يصل الدهناء ح"},{"id":4129,"era":"c12","t":"دمج \"مجلس أحكام العدلية\" أعلى مؤسسة في الدولة العثمانية .","s":"تم دمج \"مجلس عالي تنظيمان\"- الذي كان يعدُّ أعلى مؤسسة في الدولة العثمانية، والذي تم إنشاؤه في عام 1854م- في مجلس \"والا\" أو \"مجلس أحكام العدلية العالي\" الذي أنشأه السلطان محمود الثاني في إبريل 1838م."},{"id":4130,"era":"c12","t":"هزيمة جيش الدرعية في وقعة الحاير على يد رئيس نجران .","s":"جرت الوقعةُ المشهورة بوقعة الحاير- وهو مكان يُعرَف بحاير سبيع، بين الرياض والخرج- وكانت هذه الوقعة ابتلاءً لأهل التوحيد أتباع الدرعية, وكان سببُ هذه الوقعة أن العجمان بعد أن هزمهم عبد العزيز بن محمد في قذلة عام 1177هـ وقتل منهم فريقًا وأسر فريقًا آخر، استنجدوا برئيس نجران وقبائل يام، فاستجاب صاحبُ نجران الحسنُ بن هبة الله المكرمي لشكواهم، وأعدَّ العدة لذلك، وأبلغ صاحِبَ الأحساء عريعر بن دجين عدو ا"},{"id":4131,"era":"c12","t":"برد شديد في نجد قضى على الزرع والثمار .","s":"أتى على نجدٍ في هذا العام بردٌ شديدٌ لم يُعهدْ مِثلُه أذهب الزرعَ والثمار"},{"id":4132,"era":"c12","t":"وفاة الأمير محمد بن سعود آل مقرن وتولي ابنه عبد العزيز من بعده .","s":"هو الأميرُ الإمامُ محمَّدُ بنُ سعود بن محمد بن مقرن بن مرخان بن إبراهيم بن موسى بن ربيعة بن مانع بن ربيعة المريدي الدرعي العدناني، مؤسِّسُ الدولة السعودية الأولى، وكان الإمامُ محمد بن سعود آل مقرن قد انطلق من مدينة الدرعية (المنطقة الوسطى بجانب مدينة الرياض، العاصمة الحالية). وكان شجاعًا حازمًا، وقد التقى بالإمام محمد بن عبد الوهاب الذي كان يطلب حمايةَ الدعوة من الإمام محمد بن سعود. وتوافق الاثنان"},{"id":4133,"era":"c12","t":"نقض أمير الرياض دهام بن دواس عهده مع الدرعية .","s":"نقض أميرُ الرياض دهام بن دواس وأبدى الخيانة، فسار هو وزيد بن زامل رئيسُ الدلم وعدا على الصبيحات في المنفوحة، وأخذا منها سائمةً كثيرة، فخرج أهل منفوحة فقاتلوهما، فقتل من الطرفين عدةُ رجال، فثارت الحرب بين الطرفين، وكان دهام هو الذي فتح باب القتال بنقضِه العهد، وكانت هذه الحرب سببًا لهلاكه وخروجِه من الرياض."},{"id":4134,"era":"c12","t":"انضمام بلدة العودة في سدير لحكم الدرعية .","s":"غزا جيشٌ من الدرعية العودة في سدير, وأميرهم هذلول بن فيصل، ومعه سعود بن عبد العزيز- وهذه أول غزوة غزاها سعود بن عبد العزيز- فدخلوا البلدة ليلًا وأعدوا كمينًا لم يشعُرْ به أحدٌ، فلما أصبحوا غار جيش الدرعية على أطراف البلد، فخرج أهلها إليهم ليقاتلوهم، فدخل الكمين البلدة، فلما علم الذين خرجوا من أهل البلدة بذلك عادوا إليها، وأرادوا دخول القلعة, فوجدوا جيشَ الدرعية قد استولَوا عليها، فجرى بينهم قتال ح"},{"id":4135,"era":"c12","t":"ارتفاع الأسعار في نجد في سنة سوقة .","s":"ارتفعت الأسعارُ في نجد ونَفِدَ الزاد، وقاسى الناس ألوانَ الضيق, واستمَرَّ غلاء الأثمان إلى السنة التالية، وزاد ما كان يلقاه الناسُ مِن مشقة وضيق، حتى سميت هذه السنة سنة سوقة أو قحط سوقة"},{"id":4136,"era":"c12","t":"وفاة العلامة الشيخ عمر بن علي الطحلاوي المالكي الأزهري .","s":"هو الشيخُ الإمام الثبت العلامة الفقيهُ المحدِّث الشيخ عمر بن علي بن يحيى بن مصطفى الطحلاوي المالكي الأزهري، تفقه على الشيخ سالم النفراوي وحضر دروس الشيخ منصور المنوفي، والشهاب ابن الفقيه، والشيخ محمد الصغير الورزازي، وغيرهم، وسمع الحديثَ عن الشهابين أحمد البابلي والشيخ أحمد العماوي، وأبي الحسن علي بن أحمد الحريشي الفاسي، وتمهَّر في الفنون ودرَّس بالجامع الأزهر وبالمشهد الحُسيني، واشتهر أمرُه وطار "},{"id":4137,"era":"c12","t":"وفاة الشيخ محمد الحفناوي الشافعي شيخ الطريقة الخلوتية الصوفية .","s":"هو الشيخُ محمد بن سالم الحفناوي الشافعي الخلوتي الصوفي, شيخُ الأزهر, وهو شَريفٌ حُسيني من جهة أم أبيه، وهي السيدة ترك ابنة السيد سالم بن محمد بن علي بن عبد الكريم بن السيد برطع, وينتهي نسَبُه إلى الإمام الحسين رضي الله عنه، وكان والده مستوفيًا عند بعض الأمراء بمصر، وكان غايةً من العفاف، ولِدَ على رأس المائة بعد الألف ببلده حفنا بالقصر, وهي قريةٌ من أعمال بلبيس، وبها نشأ، والنسبةُ إليها حفناوي، وغل"},{"id":4138,"era":"c12","t":"ثورة علي بك الكبير والي مصر  .","s":"كان الخليفةُ العثماني مصطفى الثالث قد طلب من والي مصر حمزة باشا اثني عشر ألف مقاتل لمحاربة الروس، فأوقعت المماليكُ والباشا الفِتَنَ بحَقِّ علي بك متولي المشيخة، وقد ورد فرمانٌ في قتله وإرسال رأسِه إلى السلطان غيرَ أنَّ علي بك عَلِمَ بذلك وتربَّص بالرسل وقتلهم، وأعلن استقلاله بمصر بدَعمٍ مِن الروس؛ من أجل إضعاف الدولة العثمانية. كتب علي بك إلى الشيخ (ظاهر) ظاهر العمر أمير عكا يُعلِمُه بذلك، فعلم ال"},{"id":4139,"era":"c12","t":"غزو الأمير سعود بن عبد العزيز عنيزة .","s":"قاد الأميرُ سعود بن عبد العزيز حملةً عسكرية ركابُها نحو مائة من الإبل ضد عنيزة، فأغار عليها فخرج عليهم أهلها، وكان عِدَّتُهم مئات، ونشب بينهم القتال إلى أن انهزم أهلُ عُنيزة وقُتِلَ منهم نحو عشرةٍ مِن الرجال."},{"id":4140,"era":"c12","t":"إعلان بريدة ولائها لدولة الدرعية، وتبني دعوة الشيخ محمد بن عبد الوهاب .","s":"أعلنت بُريدة بقيادة أميرِها حمود الدريبي آل عليان ولاءَها لدولة الدرعية وتبنِّي دعوة الشيخ محمد بن عبد الوهاب، وذلك حين دَعَمت حكومةُ الدرعيةِ أميرَها حمود الدريبي ضدَّ أمير عنيزة عبد الله بن أحمد بن زامل، بقوَّاتٍ قادها الأميرُ سعود بن عبد العزيز, لكنَّ بريدة لم يستقِرَّ ولاؤها للدرعية إلَّا سنة 1189."},{"id":4141,"era":"c12","t":"إعلان الدولة العثمانية الحرب على روسيا .","s":"نشبت الحربُ بين الدولة العليَّة وروسيا؛ وذلك أنه لما توفِّيَ أوغست الثالث ملك بولونيا سعت كاترين الثانية إمبراطورة روسيا في تعيين أحد أتباعها مَلِكًا على بولونيا خلافًا لِما تعهَّدت به روسيا للدولة العلية؛ ولذلك تنبهت الدولة العلية إلى نتيجةِ هذه السياسة وعَلِمَت أنها إن لم تضَعْ حدًّا لتقدم نفوذ روسيا في بولونيا، فلا تلبث بولونيا أن تُمحى من العالم السياسي بانضمامها لروسيا أو بتجزئتِها بينها وبين"},{"id":4142,"era":"c12","t":"وفاة العلامة الأمير محمد الصنعاني .","s":"هو العلامةُ المجتهد السيد الحسني صاحب التصانيف: الأمير محمد بن إسماعيل الكحلاني، ثم الصنعاني. ولِدَ ليلة الجمعة نصف جمادى الآخرة سنة 1099هـ بكحلان ثم انتقل مع أسرته إلى صنعاء سنة 1107هـ وأخذ عن علمائها، ووالده كان من الفضلاء الزاهدين في الدنيا الراغبين في العمل، وله شعر جيد، مات في ثالث شهر ذي الحجة سنة 1142هـ. رحل الصنعاني إلى مكة وقرأ الحديث على أكابر علمائها وعلماء المدينة، وبرع في جميع العلوم،"},{"id":4143,"era":"c12","t":"هجوم خان القرم التابع للدولة العثمانية على أوكرانيا .","s":"استطاع خان القرم التابعُ للدولة العثمانية أن يقوم بهجوم شتوي مفاجئ على أوكرانيا أثناء الحرب الروسية - العثمانية، فنجح ملِكُ القرم في غارتِه، وهدم عددًا من الضِّياعِ وحمل الآلافَ من الأسرى."},{"id":4144,"era":"c12","t":"محاصرة الجيش الروسي قلعة خوتين التابعة للحكم العثماني .","s":"حاصر الجيشُ الروسيُّ قلعة خوتين الواقعةَ على نهر دنيسنز، والتي تعدُّ المدخَلَ الرئيسيَّ لبولونيا التي كانت تابعةً للدولة العثمانية، بَيْدَ أنَّ الجيشَ العثماني استطاع تشتيتَ الجيشِ الروسي بعد يومٍ مِن الحصار."},{"id":4145,"era":"c12","t":"انضمام أهل القصيم لدعوة الشيخ محمد بن عبد الوهاب .","s":"غزا الإمامُ عبد العزيز بن محمد بأهل الدرعية وقراها بلدةَ الهلالية وهي مِن قرى القصيم، فوصلها ليلًا وأعدَّ لها كمينًا، فلما أصبحوا حاربَ أهلَها حتى هزموهم, وقُتِل منهم رجالٌ، ثم دخل عبد العزيز الهلاليةَ وأقام فيها أيامًا، فوفد إليه أهلُ القصيم يعلنون له السمع والطاعة، فأخذ عليهم العهدَ ووضع عندهم معلِّمين يعلمونهم التوحيدَ والشَّرائعَ والأحكامَ."},{"id":4146,"era":"c12","t":"حج طائفة من أهل الدرعية وأتباع الدعوة .","s":"في هذه السَّنةِ غَزَت جماعةٌ من الدرعية، فصادفت الشريف منصورًا فأسَرَتْه مع ركبٍ كان معه، فمَنَّ الإمامُ عبد العزيز وأطلقه دون فداءٍ, فلما عاد الشريف منصور إلى مكةَ استأذن من شريفِ مكَّةَ ليَسمحَ لأتباع الدرعية بالحَجِّ، فحجَّت طائفةٌ منهم آمنة وقضت فرضها بعد أن كان الحجُّ متعسرًا على أتباع الدعوة بسبَبِ الشائعات التي لدى أشرافِ مكَّةَ ضِدَّ أتباع دعوة الشيخ محمد بن عبد الوهاب."},{"id":4147,"era":"c12","t":"تجدد قتال العثمانيين مع الروس .","s":"كان السلطانُ مصطفى الثالث يرى أنَّ الخطرَ الدَّاهِمَ على الدولة العثمانية يتمثَّلُ في ظهورِ القوة الروسية الجديدة، ويبدو أنَّه اطَّلع على المخطط الأسود الروسي لتفتيت الدولة العثمانية الذي وضعه بطرس الأكبر في وصيَّتِه؛ ولذلك أعدَّ السلطان مصطفى الثالث لحرب روسيا، فخاضت الدولةُ العثمانية حربًا مع روسيا بسبب اعتداءات القوزاق التابعين لروسيا على مناطق الحدود، فنجح ملِكُ القرم في غارته وهدم عددًا من ال"},{"id":4148,"era":"c12","t":"قتال بين الأسطول الروسي والأسطول العثماني في أكثر من موقع .","s":"لَمَّا كانت روسيا ليس لها عمارةٌ بالبحر الأسود استقدمت أساطيلَها من بحر البلطيك واستعانت بسفن من إنكلترا والفلمنك والبنادقة، واستأجرت ضباطًا ورجالًا لها، فأقبل هذا الأسطول إلى البحر الأبيض ومَرَّ بسواحل مورة، وأمَدَّ رجال الثورة هناك بالمال والسلاح. فلما رأت فرنسا تغلغل روسيا في البحر الأبيض كرهت ذلك جدًّا، وعرضت على الدولة العثمانية النجدةَ فقَبِلتْها، فحضر أحد مهندسيها واسمه البارون (توت) ليساعد"},{"id":4149,"era":"c12","t":"سقوط البصرة في أيدي الإنجليز واستخدامها لأغراض تجارية .","s":"كانت التجارة في البصرة قد تدهورت وخاصةً بعد ظهور مرضِ الطاعون في المدينة فتوقَّفَت الحركة التجارية وسُحِب المركز الإنكليزي المقيم فيها مؤقتًا، ثم لم تلبَثْ أن مرت سنتان حتى أتى الحصارُ والاحتلال الفارسي للعراق، فأصيبت البصرة بالشَّلَلِ التِّجاري، لكن الأمرَ لم يدُمْ طويلًا؛ حيث تخلَّت إيران عن البصرة، فأعاد الإنكليز فورًا فتح مركزهم بدرجة مقيمٍ، وقطع ارتباطه بمقيمه بوشهر في إيران، وأصبحوا تحت إمرة"},{"id":4150,"era":"c12","t":"الروس يستولون على نهر الدانوب ويشعلون الأسطول العثماني .","s":"كانت الدولةُ الروسيةُ طامحةً إلى بولونيا، وكان ذلك ضِدَّ مصلحة فرنسا, فحرَّضت فرنسا تركيا على محاربة روسيا، وكان الصدر إذ ذاك محسن زاده محمد باشا فعارض هذا الأمرَ أشَدَّ المعارضة؛ لعلمه بضعف تركيا إذ ذاك وعدَمِ استعدادها لإعلانِ حربٍ كبيرة كهذه على روسيا، فعزله السلطان وعيَّنَ بدله سلحدار ماهر حمزة باشا فأعلن الحربَ على روسيا، وقاد باغلقجي محمد أمين باشا جيشًا تركيًّا وتصدى به لعبورِ نهر الدانوب و"},{"id":4151,"era":"c12","t":"محاولات روسيا السيطرة على بلاد القرم .","s":"هاجم الروسُ مدينةَ طرابزون وفشلوا في احتلالِها، ولكِنَّهم نجحوا في اقتحامِ بلاد القرم والسيطرة عليها, ثم جَرَت مفاوضات الصلحِ، ولكنَّها فَشِلت بسبب مطالبِ روسيا التعسُّفية، وعادت الحربُ وانتصر العثمانيون, وأثناء  الحرب القائمة بين الروس والعثمانيين بعثت روسيا البرنس دلفوروكي بجيشٍ لفتح بلادِ القرم، فقابله السلحدار (رتبة عسكرية) إبراهيم باشا وهزمه، فعمد الروسُ إلى إثارة أهل القرم بأنَّها إنما تريد "},{"id":4152,"era":"c12","t":"رسول من الدرعية يلتقي بشريف مكة  .","s":"أرسل الشيخُ محمد بن عبد الوهاب والإمام عبد العزيز إلى والي مكة الشريفِ أحمد بن سعيد رسولًا بهدايا, وكان الشريفُ قد كاتبهما وطلب منهما أن يرسِلَا إليه فقيهًا وعالِمًا من جماعتهما يُبَيِّن حقيقة ما يدعونَ إليه من الدِّينِ، ويناظر علماءَ مكةَ، فأرسلا إليه الشيخ عبد العزيز بن عبد الله الحصين، ومعه رسالة منهما, يقول ابن غنام: \"لما وصل الشيخُ عبد العزيز الحصين على الشريفِ الملقب بالفعر، واجتمع هو وبعض ع"},{"id":4153,"era":"c12","t":"تجدد القتال مع الروس .","s":"حاولت روسيا أن تعقد مع تركيا عهدًا مقتضاه استقلالُ القرم وأن تستولي روسيا على قلعة كرتس وبناء قلعة في مدخل بحر أزوف، وأن تكون الملاحةُ حرَّةً لروسيا في جميع موانئ الدولة التركية في البحر الأسود، وأن يكون لتلك الدولةِ حَقُّ حماية المسيحيين الأرثوذكس في تركيا، فرفضت تركيا هذا الشرطَ الأخير، فعاد الجفاء بين الدولتين على ما كان عليه، فتقدَّم الصدر الأعظم محسن زاده باشا وانتصر على الروسِ بجوار بزارجق و"},{"id":4154,"era":"c12","t":"تمرد محمد بيك أبو الذهب على أستاذه علي بيك بعد دخوله الشام  .","s":"جهَّز حاكِمُ مِصرَ علي بك تجريدةً عظيمة لضَمِّ الشام لحُكمِه، وجعل أميرَها محمد بك أبو الذهب زوج بنته, وأرباب المناصب ومماليكهم وطوائفهم وأتباعهم وعساكر كثيرة من المغاربة والترك والهنود واليمانية والمتاولة، وخرجوا في استعدادٍ عظيم ومعهم الطبول والزمور والذخائر. فلما وصلوا إلى الديار الشامية حاصروا يافا حتى ملكوها، ثم حاربوا نواب وولاة الدولة العثمانية، فهزموهم وقتلوهم وفرُّوا من وجوههم، واستولوا ع"},{"id":4155,"era":"c12","t":"وقوع خسائر فادحة في الجيش الروسي .","s":"تعرَّض الجيش الروسي المكون من 200 ألف جندي لخسائِرَ فادحة أثناء عبوره نهر الطونة للسيطرة على مولدافيا ورومانيا."},{"id":4156,"era":"c12","t":"علي بك الكبير يعود ويأخذ مناطق من بلاد الشام بدعم من الروس .","s":"بعد هزيمةِ علي بك أمام أبي الذهب محمد بك اتَّجه علي بك إلى الشامِ، فاتفق مع (ظاهر) ظاهر العمر فاستطاعا أن يسيطرا على صفد، ثم ينطلق منها إلى الجهات الثانية فدخل عكا وتسلَّم ولايتها، واضطر السلطان أن يعترف بذلك لانشغاله بالحربِ مع الروس التي دعمت علي بك وظاهر العمر لمحاربة العثمانيين، فسارا إلى صيدا لاحتلالها والتقيا بالعثمانيين خارجها وانتصرا على جيوش الدولة العثمانية بدعمٍ مِن  الأسطول الروسي في ا"},{"id":4157,"era":"c12","t":"استيلاء روسيا على بلاد القرم\n  .","s":"أخذت روسيا تبث رجالها في بلاد القرم لإثارة المشاغب الداخلية بها، وبالتالي لابتلاعِها وضَمِّها إلى أملاكها؛ حيث لم يكن قَصدُها من استقلالها السياسي وقطعِ روابط تبعيتها للدولة العثمانية إلا الوصولَ لهذه الغاية، وما زالت مستمرةً في إلقاء الدسائس ونشر الفتن بين الأهالي، حتى عزلوا أمير بلاد دولت كراي الذي انتخبه الأهالي بمقتضى نصوصِ معاهدة كاينارجي، وأقاموا جاهين كراي مكانه، فلم يقبل تعيينَه فريقٌ عظيم"},{"id":4158,"era":"c12","t":"نهاية حركة علي بك الكبير في الخروج على دولة الخلافة العثمانية .","s":"بعد أن تمكَّن محمد بك أبو الذهب من مصرَ على إثرِ هزيمة قوات أستاذه علي بك، اشتدَّ الأمر بعلي بك ولاحت على دولتِه لوائح الزوالِ، وكاد يموتُ من الغيظ والقهر, ثم شرع في تجهيزِ تجريدةٍ أخرى وأميرُها علي بك الطنطاوي, ووقعت بينهم معركةٌ قوية هُزِمَت فيها عسكر علي بك, فرَكِبَ إلى داره وحمل حمولَه وأمواله وخرج من مصر وذهب إلى جهة الشامِ، وذلك ليلة الخامس والعشرين من شهر المحرم، وبصحبته علي بك الطنطاوي وبا"},{"id":4159,"era":"c12","t":"استيلاء الجيش الروسي على قلعة \"بندر\" العثمانية .","s":"كانت قلعة بندر قلعةً عثمانية مهمةً على الساحل الجنوبي من تورلا قربَ مدينة كيشنيف، انهزم الصدر الأعظم والسردار الأكرم عوض خليل باشا أمام رومانزوف في موقع كارتال قرب أيساكجي. فتمكَّن الجيش الروسي من الاستيلاء على القلعة، وقد ذبح الروس ُكافة المسلمين الموجودين في القلعة بالسيف، بلغ عددهم 50 ألف جندي عثماني، تمت مطاردتُهم بعد تركهم القتالَ والهروب من القلعة، فذبحهم الروس- الذين تكبدوا خسائر كبيرة على "},{"id":4160,"era":"c12","t":"تحالف روسي نمساوي لطرد الدولة العثمانية من أوروبا .","s":"أبرمت روسيا مع النمسا اتفاقًا سِريًّا تمَّ بين كاترين الثانية وبين الإمبراطور جوزيف الثاني عند مقابلتهما بمدينة كرزن، قاضيًا بمحاربة الدولة العثمانية لإنشاءِ حكومةٍ مُستقلةٍ تكون حاجِزًا بينهما وبين الدولة العثمانية، مكوَّنة من الفلاخ والبغدان وإقليم بساربيا يكون اسمُها مملكة داسي، ويعَّين لها ملكٌ من المذهب الأرثوذكسي، وتأخذ روسيا ميناء أوتشاكوف (مدينة أوزي) وبعض جزائر الروم، وتأخذ النمسا بلادَ ا"},{"id":4161,"era":"c12","t":"طاعون في بغداد والبصرة .","s":"وقع طاعونٌ عظيم في بغداد والبصرة ونواحيهما، ولم يبق من أهل البصرةِ ونواحيها إلَّا القليل, وقيل: مات منهم 350 ألفًا، ومن أهل الزبير ستة آلاف."},{"id":4162,"era":"c12","t":"زيد بن زامل رئيس بلد الدلم يؤلب على الدرعية .","s":"بعد دخولِ الإمام عبد العزيز بن محمد الرياضَ، أرسل إلى زيد بن زامل رئيس الدلم يذكِّره الالتزامَ بالعهد الذي بينهم, فلم يلتفِتْ زيد لهذا العهدِ، وأخذ يؤلِّبُ على الدرعية، فأرسل إلى المكرمي رئيسِ نجران يستحِثُّه على حرب الدرعية ويبذلُ له المالَ، ولم يستجب له، حتى طلب منه مزيدًا من المالِ، فبذل له زيدٌ كُلَّ ما طلب مقابِلَ أن يرسِلَ له رهائِنَ مِن قومِه إلى أن يتِمَّ مقصودُه، فأرسل النجراني رؤساءَ قَو"},{"id":4163,"era":"c12","t":"وفاة علي بك الكبير حاكم مصر .","s":"هو علي بك الكبير مملوكي حكم القاهرة كشيخ البلد أيام الدولة العثمانية, وكغيره من المماليك، لا تُعرف أصولُهم وإنما يُشتَرَون صغارًا، ثم يُجلبون لتركيا فيعتنقون الإسلام ثم يتربَّون تربية عسكرية صارمة، ويبدؤون في الصعود إلى مناصِبَ عليا والسيطرة على مقاليد الأمور، ويقال إن علي بك ابن قسيس رومي أرثوذكسي من قرية أماسيا في الأناضول. ولد سنة1140 ثم خُطِفَ وهو في الثالثة عشرة من عمره وبيع في القاهرة، فاشتر"},{"id":4164,"era":"c12","t":"وفاة السلطان العثماني مصطفى الثالث وتولي أخيه عبد الحميد .","s":"هو الخليفة العثماني مصطفى الثالث بن أحمد الثالث بن محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول، ولِدَ عام 1129. ولِيَ الحُكمَ بعد ابنِ عَمِّه عثمان الثالث، وكان عمُرُه حينذاك 42 عامًا. كان ميالًا للإصلاح محبًّا لتقديم بلاده، خصوصًا وزيره الأول الصدر الأعظم راغب باشا الذي أخذ في إصلاحِ بعضِ الشؤون بمساعدة السلطان وتعضيدِه "},{"id":4165,"era":"c12","t":"استسلام الرياض ودخولها تحت حكم الدرعية وهروب أميرها دهام .","s":"غزا الإمامُ عبد العزيز بن محمد بن سعود الرياضَ في صفَر, فنازل أهلَها أيامًا عديدة وضيَّق عليهم واستولى على بعضِ برودِها وهدم أكثَرَها وهدم المرقابَ، وحصل بينهم قتالٌ قُتِل فيه عددٌ من أهل الرياض، وكانت هذه الغزوةُ. يقول ابن بشر: \"بعد هذه الوقعة دخل قلبَ دهام الرعبُ والخجَلُ، ودخله الخوفُ والوجَلُ، فلم تستقرَّ له عينٌ, وقام يحاول الانهزامَ، وجمع رؤساءَ بلَدِه وأخبَرَهم بحقيقة مقصِدِه وأنه ملئَ خوفً"},{"id":4166,"era":"c12","t":"الدولة العثمانية وتوقيع معاهدة كوجك قاينارجة مع روسيا .","s":"كانت الدولة العثمانية قد دخلت في حرب طاحنة دامت ست سنوات مع روسيا من 1181 إلى 1187هـ/ 1768 – 1774م، مُنِيَت فيها الدولة العثمانية بهزائِمَ أليمة، أجبرتها على عَقدِ معاهدة مخزية في 13 من جمادى الأولى من هذه السنة, وهي المعروفة باسم معاهدة كيتشوك كاينارجي، أو \"كوجك قينارجه\" في مدينة قينارجة في بلغاريا على البحر الأسود، استطاعت روسيا من خلالِ هذه المعاهدةِ أن تحقِّق نصرًا عظيمًا على العثمانيين؛ حيث ح"},{"id":4167,"era":"c12","t":"القضاء على ثورة ظاهر العمر الذي استولى على فلسطين .","s":"بعد أن استطاع أبو الذهب محمد بك أن يقضيَ على فتنة علي بك ومَن معه من الروس، وكان ظاهر العمر من شركاء علي بك، لكنه كان في عكا متملكًا لها، فأمر السلطانُ عبد الحميد واليَه أبا الذهب محمد بك بملاحقة ظاهر العمر والقضاء عليه فهرب ظاهر إلى صفد فارًّا من محمد بك الذي بقي محاصِرًا له في جبال صفد إلى أن استطاع أن يقتُلَه في هذا العام."},{"id":4168,"era":"c12","t":"هجوم خالد بن عريعر على منطقة القصيم .","s":"شَنَّ خالدُ بن عريعر هجومًا عاصفًا على منطقة القصيم، وركز هجومَه على بلدة بُريدة، ونجح في إقصاء أميرِها عبد الله بن حسن وأسرته الموالين للدرعية، وعيَّن عليها راشِدًا الدريبي المناهض لإمارة الدرعية ودعوة الشيخ، وتشجَّع عريعر على مهاجمة الدرعية نفسِها، إلا أنَّه توفي في الخابية قرب النبقية بعد شهرين من انسحابِه مِن بُريدة."},{"id":4169,"era":"c12","t":"محاصرة الفرس للبصرة واحتلالهم إياها .","s":"حاصر الفُرسُ البصرة واحتلوها لمدة أربع سنوات، وأسهم هذا الاحتلال في إضعافِ السُّلطات العثمانية في العراق، وتحوُّل حركة التجارةِ مِن البصرة إلى الكويت."},{"id":4170,"era":"c12","t":"تحالف بقيادة المكرمي رئيس نجران يغزو نجد  .","s":"أقبل أهلُ نجران وجميعُ قبائل يام ومعهم أهلُ الوادي وغيرُهم بقيادة رئيس نجران المكرمي, وكان حويل الودعاني مع زيد بن زامل قد بذلوا له الأموال سنة 1187 ليغزو نجدًا؛ وذلك لما عهدوا منه قُوَّته حين هزم جيش الدرعية في الحاير سنة 1178 فسار معه أهل الخرج ومن حولهم، واجتمع مع المكرمي جموعٌ تضيقُ بها القِفارُ ولا تسقيهم الآبارُ والأنهار, وأرسل إليه بطين بن عريعر من النقدِ ما يزيد على ستة آلاف مشخصٍ، وأحمالً"},{"id":4171,"era":"c12","t":"غزو مدينة بريدة وتعيين عبد الله بن حسن أميرا على بلدان القصيم .","s":"سار سعودُ بن عبد العزيز وقَصْدُه بريدة، ومعه آل عليان الذين خرجوا منها سنة 1188 عندما أخذها عريعر بن دجين عنوةً, وفرض عليها حصارًا وبنى تجاهها حِصنًا جعل فيه عدَّةَ رجال عبد الله بن حسن أميرًا عليهم يواصِلُ منه الحصارَ على بريدة، فلما اشتد الأمر بأهل بريدة أرسل أمير البلد راشد الدريبي إلى عبد الله بن حسن الأمانَ لنفسه وأن يخرجَ لوحده فأعطاه الأمان وخرج إليه راشد، ثم دخل عبد الله ومن معه البلد وملك"},{"id":4172,"era":"c12","t":"دخول زيد بن زامل رئيس الدلم في طاعة الدرعية  .","s":"قَدِمَ رئيس الدلم زيدُ بن زامل ومعه أناسٌ من أعيان قومِه على الإمام عبد العزيز في الدرعية فجأةً، فبايعوا على الإسلامِ والسمع والطاعة، والالتزام بإقامة الشريعة في بلادِهم، فطلب منه عبد العزيز أنواعًا من السلاح والخيل, فلما أرسله أخذ عبد العزيز البعضَ منه وردَّ له البعض الآخرَ ترغيبًا له وتأليفًا. لكنَّه نقض العهدَ في السنة التالية."},{"id":4173,"era":"c12","t":"وفاة الشيخ صباح بن جابر حاكم الكويت .","s":"هو الشَّيخُ صُباح الأولُ بن جابر بن سَلمان بن أحمد العتبي. في سنة 1129هـ اتفق ثلاثةٌ من رؤساء القبائل التي سكَنَت الكويت وهم: صُباح بن جابر بن سلمان بن أحمد، وخليفةُ بن محمَّد، وجابر بن رحمة العتبي رئيس الجلاهمة، على أن يتولَّى صُباح الرئاسةَ وشؤونَ الحُكمِ، وأن يتشاورَ معهم، ويتولَّى خليفة شؤونَ المال والتجارة، ويتولى جابر بن رحمة شؤونَ العمل في البحرِ، وتقسَّم جميعُ الأرباح بينهم بالتساوي, ثم حا"},{"id":4174,"era":"c12","t":"حاكم الدرعية يسند إمارة بريدة إلى حجيلان العليان .","s":"أسندت الدرعيةُ إمارةَ بُريدة وما يتبعها إلى حجيلان بن حمد العليان بعدَ مقتَلِ أميرها عبد الله بن حسن في وقعةِ مخيريق, فنجح حجيلان في توطيدِ حُكم الدرعية هناك، وقام بكثيرٍ مِن الغزوات لمصلحةِ ذلك الحُكمِ، ومَدَّ رقعتَه، وظلَّ أميرًا نَشِطًا في غزواته حتى قضى إبراهيم باشا على الدولة السعودية الأولى، فأُخِذَ حجيلان إلى المدينة النبوية عام 1234هـ، وتوفِّيَ فيها بعد وصولِه إليها بقليل."},{"id":4175,"era":"c12","t":"هزيمة جيش الدرعية في وقعة مخيريق  .","s":"سار الإمام عبد العزيز بجنودِه، وقصد عربان آل مرة في أرض الخرجِ, وكانوا قد اجتمعوا فيها وتأهَّبوا للحرب والقتالِ، فشَنَّ عليهم عبد العزيز غارةً في الصباح الباكر، فتفازع العربان وحصل قتالٌ شديد، وكانت الغارة على العربان في شعبٍ ضَيِّق، فأمسك العربان مدخَلَ الشِّعبِ ولم يكن لعبد العزيز مصدرٌ غيرُه، فوقعت الهزيمةُ على عبد العزيز وألجأهم العُربان إلى عقبة وعرة تسمى مخيريق الصفا، فوقع فيها كثيرٌ مِن الر"},{"id":4176,"era":"c12","t":"فشل الحملة الأسبانية للسيطرة على الجزائر .","s":"فشلت الحملة الأسبانية، التي انعقد لواؤها للسيطرة على الجزائر، وكانت الحملةُ تتكوَّن من 22 ألف جندي، وخَسِرَ الأسبان في هذه الحملة 7 آلاف قتيل، وهو ما أثار استياءَ الملك كارلوس الثالث في مدريد، في حين أقام العثمانيون الأفراحَ في إستانبول بهذا النصر."},{"id":4177,"era":"c12","t":"غزو سعود بن عبد العزيز حرمة  .","s":"أجمع أهلُ حرمة- وهي بلدة في المجمعة- الغدرَ بأميرهم عثمان بن عبد الله، وكان رئيسُهم في الغدر جويسرَ الحسيني الذي اتَّفَق مع سويد بن محمد صاحب جلاجل وأحمد بن عثمان أمير المجمعة على الغدر بأتباع الدعوة في بلدانِهم, فلمَّا أجمعوا على إنجازِ ما اتَّفَقوا عليه، أرسلوا إلى كبار أتباع الدعوةِ في المجمعة ليأتوا إلى حرمة؛ ليُعَلِّموا أهلَها، فلما جاء بعضُهم حرمة، كان أمير حرمة عثمان في نخلٍ له خارِجَ البلد"},{"id":4178,"era":"c12","t":"وفاة الشيخ أحمد الدمنهوري شيخ الأزهر .","s":"هو الشيخُ الإمام أبو العباس أحمد بن عبد المنعم بن يوسف بن صيام الدمنهوري، شيخ جامع الأزهر، وأحد عُلماء مصر المُكثرين من التصنيف، ولِدَ بدمنهور سنة 1101هـ - 1589م. تعلَّم في الأزهر حتى تولى مشيخَتَه. فقد اشتغل بالعلمِ، وجدَّ في تحصيلِه، واجتهد في تكميلِه، وأجازَه علماء المذاهب الأربعة، وسمحوا له بتدريسِ الفِقهِ على المذاهب الأربعة, حتى سُمِّي بالمَذهبي. كانت له حافظةٌ وذاكرةٌ عجيبة, قيل عنه إنه: \"أ"},{"id":4179,"era":"c12","t":"أغا محمد يؤسس الدولة القاجارية  .","s":"كان أغا محمد خان- أغا أي: مَخْصِي- وهو من قبيلة قاجار المشهورة التي سكنت استراباد شمالي إيران، وهم من الشيعة الاثني عشرية، كان مستشارَ كريم خان الزندي، وقيل: إنه لَمَّا توفي كريم خان فرَّ أغا محمد خان من شيراز إلى طهران، وأعلن استقلالَه، ثم لَمَّا وصل إلى بلاده الأصلية جمع حولَه القاجارية وضمَّ إليه أيضًا بعض القبائل المجاورة وتصالحَ مع الأفشار، فأصبح هو صاحِبَ الأمر والنهي في شماليَّ إيران، وكان "},{"id":4180,"era":"c12","t":"أهل حرمة ينقضون العهد ويغزون المجمعة .","s":"نقض أهلُ حرمة عهدَهم مع الأمير سعود بن عبد العزيز وتواعَدوا مع أهل الزلفي وأرسلوا إلى سعدون بن عريعر حاكِمِ الأحساء وأتباعِه مِن العربان أنَّهم يريدون أن يَسطُوا على بلدة المجمعة، وكان فيها مرابط وضباط من جهة الإمام عبد العزيز بن محمد، وقد تحقَّق عند أهل حرمة أنَّهم إن لم يأخُذوا المجمعة ويضبطوها لم يكن لهم في بلدهم قرار, فسار رجالٌ مِن أهل حرمة في زيِّ النساءِ وأمسكوا بروجَ النخيل، ثمَّ قَدِم علي"},{"id":4181,"era":"c12","t":"الأمير سعود يغزو بلدة حرمة والإمام عبد العزيز يأمر بتدميرها .","s":"غزا سعودُ بن عبد العزيز حرمة واستنفر معه أهلَ البلدان مشاةً وركبانًا، ونزل على بلدة حرمة وحصرها حصارًا شديدًا، وقطع نخلَ قاضيها عبد الله بن المويس- ابن عم الشيخ المجدِّد، لكنه من ألدِّ أعداء الدعوة (ت1175)- ومَلَك الأمير سعود أكثَرَ نخلها وأقام عليها أيامًا يباكرهم القتالَ، فلما اشتد عليهم الحصارُ ألقى الله الرعب في قلوبهم، فأرسلوا إلى سعود وطلبوا الصلحَ فأبى إلا أن تكون بلدتُهم فيئًا، أو يزيل ما "},{"id":4182,"era":"c12","t":"اتفاق بين الدولة العثمانية ومدينة تفليس الفارسية في رسم الحدود .","s":"توصَّلت الدولةُ العثمانية في تلك الفترة إلى توقيعِ اتِّفاقٍ مع نادر شاه، أكبر ولاة فارس في مدينة تفليس، وكان الغرضُ منه هو تحديدَ الحدودِ بينهما."},{"id":4183,"era":"c12","t":"حرب مقاطعة ميسور بين مسلمي الهند والإنجليز .","s":"تعتبرُ حربُ مقاطعة ميسور من أشهر الحروبِ بين الإنكليز والمسلمين في الهند، وهذه المقاطعةُ كانت فيها المرازبة الهندوك تحت سيطرةِ المسلمين، فلما ضَعُفت الدولةُ المغوليةُ المُسلِمةُ المركزية في الهند استبَدَّ المرازبةُ بما تحت أيديهم، وكان حيدر علي خان بن فتح علي خان أحدَ قادتِهم، فخافه وزراؤهم وأرادوا البطشَ به، فلما أحسَّ بما يدبَّرُ له تسلَّمَ السلطةَ بالقوة ووسَّع مُلكَه؛ إذ استولى على أكثَرِ بلاد"},{"id":4184,"era":"c12","t":"إجماع أكثر بلدان القصيم على نقض عهدهم مع الدرعية .","s":"أجمع أهلُ القصيمِ عدا بريدة والرس والتنومة على نقضِ عَهدِهم مع الدرعية، وأعلنوا الحربَ ضِدَّها، وتزعمت مدينةُ عنيزة هذا العصيانَ، وتعاهدوا أنَّ كلَّ أهلِ بلدٍ يقتلون في يومٍ محدَّدٍ مَن عندهم مِن الدعاةِ والمعلِّمين الذين أوفدَتْهم الدرعية للإرشادِ, وأرسلوا إلى صاحِبِ الأحساءِ سعدون بن عريعر يخبرونَه بأمرهم ويستحِثُّونه للقدومِ عليهم, فاستنفر في الحالِ العربان، فلما قرُبَ من القصيم قام كلُّ أهلِ ب"},{"id":4185,"era":"c12","t":"وفاة ضاهر العمر حاكم عكا  .","s":"هو ضاهر (ظاهر) بن عمر بن أبى زيدان. وُلِد في صفد سنة 1106هـ كان داهيةً شجاعًا. يقال: إنَّ أصله من المدينة، هاجر أحدُ أجداده إلى فلسطين،  وكان والدُه وجدُّه وأعمامُه حكامًا في صفد وعكا. تولى إدارة عكَّا وصفد، فأقام إمارةً قوية تمثِّل مصدرَ قلقٍ للدولة العثمانية في شماليَّ فلسطين، ضمَّت صفد وطبرية والجليل الأعلى والناصرة ونابلس وعكا، فقاتله سليمان باشا والي دمشق العثماني سنة 1150هـ، فتحصَّن في طبرية"},{"id":4186,"era":"c12","t":"سعدون بن عريعر يغزو بريدة بتحريض من أهل القصيم .","s":"قدم أميرُ الأحساء سعدون بن عريعر القصيمَ لِمساندة أهلِها في الغدر بأتباعِ دعوة الشيخ محمد بن عبد الوهاب وأنصار الدرعية، وكان معه بنو خالد، وقد استنفر الظفير وعربان شمر ومن حضَر من عربان عنزة، فنزلوا بريدةَ وأحاطوا بها، فبادر رجالٌ منهم للقتال، فظهر أهلُ البلد فقتلوهم وأرسلوا برؤوسِهم لسعدون فامتلأ غيظًا وغضبًا، فهدد باستئصالهم إن ظفر بهم، فزحف على البلدة فوقع قتالٌ شديدٌ ولم ينَلْ منهم بشيءٍ، فحمل"},{"id":4187,"era":"c12","t":"قحط دالوب في نجد   .","s":"هذه السَّنةُ هي أوَّلُ القحط المسمَّى دالوب، قلَّ فيه المطرُ وغلت الأسعارُ واشتَدَّ الغلاء والقحطُ والجوعُ، ومات أناسٌ جوعًا من النساء والرجال والأطفال والبهائم، فأمر الإمامُ عبد العزيز بصَدَقاتٍ للضعفاء من أهل البلدانِ، وفرَّق عليهم شيئًا كثيرًا."},{"id":4188,"era":"c12","t":"وفاة الأمير زيد بن زامل أمير الخرج  .","s":"هو الأميرُ زيد بن زامل بن عثمان الديلمي من عائذ من الصقر من عبيدة من قحطان، أمير الخرج، أعلن عداءَه لدعوة الشيخ ودولة الدرعية من بداية الدعوةِ، وخاض معها عدةَ معاركَ، وشارك في عدةِ أحلافٍ تشكَّلت ضِدَّ الدرعية, وقد دخل في صلحٍ مع أميرِ الدرعية وبايع الشيخَ والأميرَ عِدَّةَ مراتٍ، لكنه سرعان ما ينقُضُ العهدَ ويرجِعُ عن بيعتِه لهم. إلى أن كانت نهايتُه  كقاطع طريقٍ، عندما أغار على عربان سبيع وأخذ من "},{"id":4189,"era":"c12","t":"انتزاع آل خليفة حكم البحرين من آل مذكور التابعين لحكام فارس .","s":"تعرَّض وفدٌ من آل خليفة (عتوب الزبارة) في البحرين إلى اعتداءٍ أدى إلى وقوعِ قتال بين أتباعِ آل خليفة والبحارنة, فقُتِل أحد أتباع الخليفة، فغَضِب أهلُ الزبارة نتيجةً لذلك فأرسلوا سفينةً صغيرة للبحرين؛ للأخذ بثأر القتيل، فتمكنوا من قتلِ غريمِهم وقتلوا معه خمسةَ أشخاص, فجهَّز ناصِرُ آل مذكور- التابع لحكم الزنديين في بوشهر- سفُنًا حربية تحتوي على خمسة آلاف مقاتلٍ، وتولى ابنُ أخيه محمد بن سعدون آل مذكو"},{"id":4190,"era":"c12","t":"إحباط البحرية العثمانية محاولة الأسبان لاحتلال الجزائر .","s":"تمكَّنت البحريةُ العثمانية في موانئ الجزائرِ بنجاحٍ مِن مهاجمةِ وتشتيت 75 سفينةً حربيةً إسبانيةً كانت تحاوِلُ إنزالَ قواتها في موانئ الجزائر؛ وذلك تمهيدًا منها للقيام باحتلالِها."},{"id":4191,"era":"c12","t":"ضياع القرم من المسلمين واستيلاء الروس عليها  .","s":"أرسلت روسيا قوةً كبيرةً إلى فارنا من بلغاريا على البحر الأسود ولم تستَطِع القواتُ العثمانية صَدَّها، فاضطرت لعقدِ الصلحِ مع روسيا، فتَمَّ الصُّلحُ في مدينة قينارجة في بلغاريا، اعترفت فيه الدولةُ العثمانيةُ باستقلالِ تتار القرم ومنطقة بسارابيا في رومانيا وقوبان في القفقاس، على أن تكونَ للدولة العثمانيةِ المرجعيةُ الدينيةُ، وتدفَعَ لروسيا مبلغًا ماديًّا كغرامةٍ حربيةٍ، وتكون لها حريةُ الملاحة في الب"},{"id":4192,"era":"c12","t":"عمليات الأمير سعود بن عبد العزيز العسكرية ضد الأحساء .","s":"بدأت العملياتُ العسكريةُ لدَولةِ الدرعية ضِدَّ الأحساء على يدِ الأمير سعود بن عبد العزيز، وذلك ردًّا على العداءِ السَّافِرِ من بني خالد لدولةِ الدرعية، فسار الأميرُ سعود بقواتِه حتى وصل قرية العيون في الأحساءِ، فغَنِمَ جَيشُه غنائمَ كثيرةً، ثم قفل راجعًا إلى بلادِه."},{"id":4193,"era":"c12","t":"قدوم وفد من وادي الدواسر عليهم ربيع بن زيد .","s":"في هذه السنة قَدِمَ ربيع وبدن ابنا زيد الدوسري رئيس المخاريم من وادي الدواسِرِ، ومعهما رجالٌ من رؤساء قومِهما على الشيخ محمد والإمام عبد العزيز، وبايعوا على دين اللهِ ورَسولِه والسَّمعِ والطاعة, ثم أقاموا في الوادي أتمَّ القيامِ بأمرِ الدعوةِ، وهدى الله بهم أناسًا كثيرًا."},{"id":4194,"era":"c12","t":"انضمام الأفلاج لدولة الدرعية  .","s":"وفد إلى الدرعية أهلُ الأفلاج وبايعوا الشيخَ والإمامَ عبد العزيز على دينِ اللهِ والسَّمعِ والطاعةِ."},{"id":4195,"era":"c12","t":"الأمير سعود يخضِع منطقة الخرج لسلطان الدرعية .","s":"شنَّ الأميرُ سعود هجومًا على الدلم من منطقةِ الخرج، فحاصرها وقطع نخلَها حتى أخذَها عَنوةً وقَتَل أميرها تركي بن زيد بن زامل، واستعمل عليها سليمانَ بن عفيصان، ثم أذعن له جميعُ أهل بلدان الخرج وحوطة بني تميم والحريق واليمامة والسلمية وغيرها، وطلب سعود منهم نكالًا مِن النقد وغيرِه، فصَبَروا له بذلك وبايعوه كلُّهم على دينِ الله ورسولِه والسَّمعِ والطاعة."},{"id":4196,"era":"c12","t":"احتلال الروس بلاد القرم  .","s":"سمَحت معاهدةُ كيتشوك كاينارجي للروسِ بالحصول على الامتيازات ضِمنَ البلاد العثمانية، تشمل الأرثوذكس في الأفلاق والبغدان وجزر بحر إيجة، وبالتالي تحوَّلت روسيا إلى حماية الأرثوذكس في أي مكان في الدولةِ العثمانية, ولم يكتَفِ الروس الصليبيون بذلك، بل واصلوا تآمُرَهم، وفاجؤوا الدولة العثمانية بدخولِ قواتهم بلادَ القرم- وهي جزءٌ من ولايات الدولة العثمانية- بسبعين ألف جندي، غيرَ مبالين بمعاهدة كاينارجي, و"},{"id":4197,"era":"c12","t":"إعلان الدولة العثمانية الحرب على روسيا .","s":"عَلِمت الدولةُ العثمانية أنَّ روسيا تريدُ الحربَ؛ لذا أرادت أن تبدأ هي بالحربِ قبل أن يستعِدَّ خصومُها؛ ولإيجاد سبب لذلك فقد طلبَت من السفير الروسي إبلاغَ حكومته عدَّة طلبات، وهي: تسليم حاكم الأفلاق الذي أعلن العصيان على الدولة العثمانية والتجأ إلى روسيا، التنازل عن حماية بلاد الكرج؛ لأنها تحت سيادة الدولةِ العثمانية، عزلُ القناصل الذين يثيرون السكانَ، وقَبولُ قناصِلَ عثمانيين في موانئ البحرِ الأس"},{"id":4198,"era":"c12","t":"وقعة جضعة ولجوء سعدون بن عريعر للدرعية .","s":"اتَّفق رؤساء المهاشير من بني خالد وآل صبيح مع عبد المحسن بن سرداح آل عبيد الله ودويحس بن عريعر على عداوةِ سعدون بن عريعر رئيس بني خالد، وحَربِه، واستنجدوا بثويني بن عبد الله شيخ المنتفق، فتنازلوا مع سعدون في قتالٍ، وقُتِل بينهم كثيرٌ من القتلى، وصارت الكرَّةُ على سعدون ومن معه، فانهزموا وفرَّ سعدون إلى الدرعية وطلَبَ الأمانَ من عبد العزيز لكنَّه لم يجِبْه إلى طلَبِه؛ بسبب هُدنةٍ بينه وبين ثويني شي"},{"id":4199,"era":"c13","t":"ثويني بن عبد الله شيخ المنتفق يستولي على البصرة .","s":"سار ثويني بن عبد الله شيخ المنتفق من نجدٍ إلى البصرة فدخَلَها وحبس متسَلِّمَها من قِبَل الدولة العثمانية, فلما استقَرَّ فيها طلب من رؤساء البصرة وأعيانِهم أن يكتبوا للسلطان العثماني أن يجعَلَه أميرًا عليهم ويرسلوا كتابًا بطلبهم مع مفتي البصرة، فلما عرض المفتي على السلطانِ ما جاء به أطلع السلطانُ وزراءَه على الطلب فقالوا له: هذا أعرابيٌّ متغَلِّبٌ، فغَضِبَ السلطانُ وكاد يفتِكُ بالمفتي."},{"id":4200,"era":"c13","t":"الاحتلال الإنجليزي للملايو .","s":"بدأت المصالحُ الإنجليزية في الملايو من الناحية التجارية، وكان سلطان صولو قد أعطى الإنجليزَ منطقةً في شمالي جزيرة بورنيو (أندونيسيا) لتقيمَ عليها تجارتَها، فعملت الشركة البريطانية المعروفة بشركة الهند الشرقية البريطانية لإقامةِ قاعدةٍ لها في الملايو، وتمكَّنت من ذلك بسهولة, واشترت ميناء سنغافورة أيضًا، ثم أخذ الاستعمارُ البريطاني بالتوسُّعِ منذ عام 1291هـ في الملايو، وتكرَّس على شكلِ معاهداتٍ مع سل"},{"id":4201,"era":"c13","t":"شيخ قبيلة قحطان يبايع الشيخ محمد بن عبد الوهاب على نصرة الدعوة .","s":"وفد هادي بن قرملة شيخُ عموم قبيلة قحطان في نجدٍ على الشيخِ والإمام عبد العزيزِ في الدرعية، وبايع على دين الله ورسولِه والسمع والطاعة, وصدق معهم وجاهدَ بعُربانه وبذلَ نفسَه في نصرةِ الدعوةِ وأهلِها."},{"id":4202,"era":"c13","t":"ثويني بن عبد الله شيخ المنتفق يغزو القصيم .","s":"بعد قَبولِ الإمام عبد العزيز سعدونَ بنَ عريعر في الدرعية، سار ثويني بن عبد الله شيخ المنتفق ومعه العساكرُ العظيمة من المنتفق وأهل الهجر وجميع أهل الزبير وعربان شمر وطي ومعه من العَدَد والعُدَّة ما يفوق الحصرَ، يريد غزوَ القصيم، فوصل التنومة وهي من قرى القصيم ونازلها بجموعِه وحاصَرَها وضربها بالمدافِعِ، لكِنَّه لم يتمكن من دخولهِا إلا بمكيدةٍ عن طريق عثمان آل حمد من أهل الزلفي، فدخلها عليهم خديعةً،"},{"id":4203,"era":"c13","t":"طرد ثويني شيخ المنتفق من البصرة بعد هزيمته من قبل صاحب بغداد .","s":"لما تحقَّق سليمان باشا صاحب بغداد ما أحدثَه ثويني شيخ المنتفق في البصرة مِن تولِّي حكمِها بعد  طَردِ متسَلِّمها، سار بعساكره إلى البصرة، فالتقى مع ثويني الذي جمع عُربانَ المنتفق وأهل الزبير بالقرب من سوق الشيوخ خارجَ البصرة، فاقتتلوا قتالًا شديدًا انهزم فيه ثويني هزيمةً شنيعةً فَرَّ على إثرها بمن بقي معه من جنوده إلى الجهراء، ثم رحل إلى الصمان ديار بني خالد، وتولى حمود بن ثامر رئاسةَ المنتفق، وعَي"},{"id":4204,"era":"c13","t":"أخذُ البيعة بولاية العهد للأمير سعود بن عبد العزيز .","s":"أمر الشيخُ محمد بن عبد الوهاب جميعَ أهل نجدٍ أن يبايعوا الأميرَ سعود بن عبد العزيز بعد أبيه، وذلك بإذن الإمام عبد العزيز، فبايعه أهلُ نجد جميعًا."},{"id":4205,"era":"c13","t":"قدوم وفد من وادي الدواسر للدرعية بعد انتشار الدعوة فيهم .","s":"بعد أن بايع ربيع بن زيد وأخوه بدن الشيخَ محمدًا والإمام عبد العزيز عام 1199, وعادا إلى الوادي بدأا بالدعوة للتوحيد ونبْذِ مظاهر الشرك والبدع، فنفر منهما أهلُ الوادي ودخلا معهم في حربٍ طويلة استعان فيها أهل الوادي بصاحبِ نجران المكرمي ليقضوا على ربيع بن زيد وأتباعه ودعوته، لكِنْ دون جدوى, وقد حصل ربيعٌ على مالٍ وسلاح من الإمام عبد العزيز في حربِه لِقَومِه حتى تمكَّن من أهل الوادي، فأرسلوا إلى ربيع "},{"id":4206,"era":"c13","t":"غزو ابن عفيصان قطر والأحساء .","s":"غزا سُليمان بن عفيصان إلى جهة الشرق، فأغار على أهل قطر فأصاب كثيرًا مِن آل أبي رميح وأخذ منهم كثيرًا من الخيل والغنم والسلاح, ثم سار إلى الأحساءِ, فأغار على الجشة إحدى قرى الأحساء، فأصاب منهم رجالًا."},{"id":4207,"era":"c13","t":"وفاة الشريف سرور بن مساعد أمير مكة .","s":"هو الشَّريفُ سرورُ بنُ مساعد بن سعيد بن سعد بن زيد بن محسن بن حسين بن حسن بن أبي نُمي، الذي طار صيتُه في الآفاقِ وبلغ من المجدِ والسعيِ في أعمال الخيرِ وتأمين السُّبُل ما لم يبلُغْ إليه أحدٌ من آبائه، ولقد كانت أحاديثُ الوافدين للحجِّ إلى بيت الله الحرام تخبِرُ عنه بأخبار تسُرُّ القلوبَ وتشَنِّف الأسماعَ وترَوِّح الطباعَ، وكان عظيمَ السَّطوة شديدَ الصَّولة قامعًا للفساد راعيًا لمصالح العباد، كثيرَ"},{"id":4208,"era":"c13","t":"إعلان الإمبراطور النمساوي جوزيف الثاني الحرب على الدولة العثمانية .","s":"أعلن الإمبراطورُ النمساوي جوزيف الثاني الحربَ على الدولة العثمانية؛ وذلك تأييدًا منه لحليفتِه روسيا التي كانت تحارب العثمانيين منذ 5 أشهر حول جزيرة القرم."},{"id":4209,"era":"c13","t":"انتصار الجيش العثماني على الجيش النمساوي في معركة \"شبش\" .","s":"انتصر الجيشُ العثماني بقيادة السلطانِ عبد الحميد الأول على الجيشِ النمساوي الذي يقودُه الإمبراطور جوزيف الثاني، وذلك في معركة \"شبش\" داخِلَ حدود النمسا. قامت مجموعةٌ مِن كشَّافة الجيش النمساوي بالتقَدُّم؛ لاستطلاعِ موقِفِ الجيش العثماني. وفي طريقِهم وجدوا تجمُّعًا للغجرِ حيث يباعُ الخمرُ، فجَلَسوا وسَكِروا حتي الثمالة. بعد قليلٍ جاءت مجموعةٌ مِن المشاة النمساويين للانضمامِ للمجموعةِ الأولى فرفَضوا "},{"id":4210,"era":"c13","t":"فشل تحالف روسي نمساوي لطرد الأتراك من أوروبا .","s":"على الرغمِ من اعتراف الدولة العثمانية بضم القرم لروسيا سنة 1186 إلَّا أنَّ قصْدَ روسيا ومساعديها انتشابُ القِتالِ؛ ليحظى كل منهم بأمنيتِه؛ لذلك عَمِلوا على إثارة خاطر الدولة العثمانية وإيقاعِها في الحربِ، فأخذوا في تحصين ميناء سباستوبول وأقاموا ترسانةً عظيمةً في ميناء كرزن، وأنشؤوا عمارةً بحرية من الطراز الأول في البحرِ الأسود وأرسلوا جواسيسَهم إلى بلاد اليونان وولايتي الفلاخ من البغدان؛ لتهييجِ ا"},{"id":4211,"era":"c13","t":"احتلال الجيش الروسي قلعة \"أوزي\" إحدى القلاع العثمانية .","s":"احتلَّ الجيشُ الروسي قلعة \"أوزي\" في أوكرانيا، أهَمَّ القلاعِ العثمانية على البحر الأسود، وارتكب الروسُ فيها مجزرةً رهيبةً راح ضحيَّتَها 25 ألف تركي مِن الرجال والنساء والأطفال، بعد أن قاموا بتعذيبِهم بشِدَّةٍ, وكان لخبرِ سقوطِ أوزي بيَدِ الروس وذبحِ أهلِها المدنيين بالسيفِ أكبَرُ الأثَرِ على السلطان عبد الحميد الأول؛ حيث أُصيب على إثر الخبَرِ بنزيفٍ في المخِّ توفِّيَ بعده."},{"id":4212,"era":"c13","t":"وفاة السلطان العثماني عبد الحميد الأول وقيام السلطان سليم الثالث بعده .","s":"هو السلطانُ العثماني عبد الحميد الأول بن أحمد الثالث بن محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث، ولِدَ سنة 1137هـ تولى الحكمَ عام 1187هـ/1773م بعد وفاة أخيه مصطفى الثالث، وكان محجوزًا في قصرِه مدَّةَ حكم أخيه مصطفى الثالث، استطاعت روسيا في عهدِه أن تحقِّقَ نصرًا على العثمانيين في معاهدة كيتشوك كاينارجي، وطلب الصدرُ الأعظمُ الصلحَ والمفاوضة، وتمَّ ذلك في مدينة قاينارجة في بلغاريا "},{"id":4213,"era":"c13","t":"منح الدولة العثمانية مبلغ مليار آقجه، للسويد طبقا لمعاهدة \"بيقوز\" .","s":"منحت الدولة العثمانية مبلغ مليار آقجه (العملة العثمانية) للسويد طبقًا لمعاهدة \"بيقوز\"؛ وذلك نظيرًا للدور الذي لعبته السويد في تثبيتِ قسمٍ مِن الجيش الروسي على الحدودِ مع السويد إبَّان الحرب العثمانية - الروسية."},{"id":4214,"era":"c13","t":"معركة \"فوشكاني\" وانتصار الجيش العثماني على الجيش الروسي والألماني .","s":"انتصر الوزيرُ والقائد العثماني \"كمانكش مصطفى باشا\" بقوَّاته البالغة 30000 جندي على جيش الاتحاد الروسي الألماني في معركة \"فوشكاني\" الواقعة قربَ فرع للطونة بين الأفلاقِ والبغدان"},{"id":4215,"era":"c13","t":"استيلاء الروس والنمساويين على بعض المناطق التابعة للعثمانيين .","s":"تولَّى السلطانُ سليم الثالث وما زالت الحربُ دائرةً بين الدولة العثمانية والروس، فأعطى السلطانُ وقتَه وجهده لقتالهم، غيرَ أنَّ جنده قد ضَعُفَت همَّتهم، في المقابِلِ اتحدت الجيوش الروسية والنمساوية ضِدَّ الدولة العثمانية، فتمكَّنت روسيا من الاستيلاء على الأفلاق والبغدان وبساربيا، كما استطاعت النمسا احتلالَ بلاد الصرب ودخلت بلغراد أيضًا، غيرَ أن هذا الاتفاق الروسي النمساوي لم يدُمْ طويلًا؛ إذ انصرف إ"},{"id":4216,"era":"c13","t":"سقوط بَرد على حريملاء .","s":"نزل على حريملاء بَردٌ في الشتاء على غير العادة، فقتَلَ ما وقع عليه من البهائمِ والطيور، وخسف السطوحَ والأواني حتى النحاسَ، وأهلك الأشجارَ وكسَّرها، وأهلك جميعَ زروعِهم، فجأروا إلى الله سبحانه، فرَحِمَهم ودفع عنهم."},{"id":4217,"era":"c13","t":"رسالة الشيخ محمد بن عبد الوهاب لعلماء بلد الله الحرام  .","s":"أرسل الشريفُ غالِبُ بن مساعد شريفُ مكةَ إلى الإمام عبد العزيز بن محمد  كتابًا يطلُبُ فيه أن يرسِلَ إنسانًا عارِفًا حتى يعرِّفَه بحقيقة ما يدعو إليه وما هم عليه, فأرسل إليه القاضي عبد العزيز بن عبد الله الحصين، وكتب معه الشيخ محمد بن عبد الوهاب كتابًا ورد فيه: \"بسم الله الرحمن الرحيم، من محمد بن عبد الوهاب إلى العلماء الأعلام في بلد الله الحرام، نصر الله بهم دينَ سيِّد الأنام، وعليه أفضل الصلاة وال"},{"id":4218,"era":"c13","t":"موقعة غريميل بين جيش الأمير سعود بن عبد العزيز وقوات بني خالد .","s":"جرت موقعةُ غريميل (وهو جبل صغير تحته ماء، قربَ الأحساء) حيث التقت قواتُ الدرعية بقيادةِ الأمير سعود بن عبد العزيز، مع قواتِ بني خالد بقيادةِ عبد المحسن بن سرداح وابن أخته دويحس بن عريعر، وبعد نزال استمَرَّ ثلاثة أيام، انهزم جيش بني خالد وهرب عبد المحسن إلى المنتفق، وغَنِمَ جيشُ سعود غنائِمَ كثيرة، واستعمل الأمير سعود زيدَ بن عريعر أميرًا على بني خالد."},{"id":4219,"era":"c13","t":"وفاة الملك محمد الثالث ملك العلويين بالمغرب وقيام ابنه يزيد الأول .","s":"هو الملك محمد الثالث بن عبد الله بن إسماعيل ملك العلويين في المغرب الأقصى، وكانت عاصمتُه مراكش، ولد بمكناس سنة 1134. تولى الحكم سنة1171 في ظروف صعبة بعد اضطراباتٍ، وقد تميَّزَ بالعقل والرزانة وبُعدِ النظر، اجتهَدَ في المحافظة على بلادِه ووَحدتِها وتأمينِ الشواطئ المغربية من العدوان الأوروبي، وحرَّر مازاغان من يد البرتغاليين، وانتصر على الجيش الفرنسي في معركة العرائش سنة1179, وكان أول حاكمٍ يعترف ب"},{"id":4220,"era":"c13","t":"الشريف غالب يغزو أعالي نجد .","s":"سيَّرَ شريف مكة الشريف غالبُ عساكِرَه بقيادة أخيه عبد العزيز إلى أعالي نجد لمحاربة أهلِها في قوة هائلة في العددِ والعُدَّة، نحو عشرة آلاف، ومعهم 20 مدفعًا وأمَرَهم أن يقصدوا الدرعية ومنازلَتَها فضلًا عن غيرِها من بلدانِ نجدٍ التابعة للدرعية, فلمَّا رأى أعداءُ الدعوة في نجدٍ هذه القوة أيقَنوا بنهاية دولة الدرعية ودعوة الشيخِ، خاصَّةً أنها جاءت من شريفِ مكَّةَ؛ ولذلك نقض عددٌ من العربان وأهالي بعض ب"},{"id":4221,"era":"c13","t":"وفاة الإمام العلامة مرتضى الزبيدي صاحب تاج العروس .","s":"هو الإمامُ الفاضلُ العلَّامة، الفقيهُ المحَدِّث اللُّغوي النحوي الأصولي: محمد بن محمد بن عبد الرزاق الحسيني، الملقب بمرتضى الزبيدي، أصلُه من واسط العراقِ، ولد بالهند سنة 1145, ونشأ في زَبيد، وتوفِّي في مصر، كان عالِمًا بالأدب والأنساب والحديثِ، قرأ على الشيخ عبد الرحمن العيدروس مختصر السعد بمكة، ولازمه ملازمةً كليةً وألبسه الخرقةَ وأجازه بمروياته ومسموعاته، وهو الذي شوَّقه إلى دخولِ مِصرَ بما وصفه"},{"id":4222,"era":"c13","t":"الشريف غالب يحاصر قرية قصر الشعراء .","s":"لَمَّا أخفقت حملة الشريف عبد العزيز في تحقيقِ أيِّ نصر على دولة الدرعية، جهَّز الشريف غالب بن مساعد شريف مكة جنودًا عظيمةً من مكة وغيرها ومعه سبعة مدافِعَ، فقصد هو بنفسِه أخاه عبد العزيز، ثم رحل الشريف غالب وأخوه عبد العزيز بجنودِهما الهائلة، ونزلوا قصر الشعراء، وهي قرية معروفة بأعالي نجدٍ، وحاصروها وضربوها بالمدافِعِ، وكادوا لها بأنواعِ القتالِ، وساقوا عليها الأبطالَ، وأقام الشريفُ غالب يحاصِرُها"},{"id":4223,"era":"c13","t":"الدولة العثمانية توقع معاهدة زيشتوفي مع ألمانيا .","s":"وقَّعت الدولة العثمانية معاهدة \"زيشتوفي\" مع ألمانيا؛ لإنهاء الحرب بينهما، وتكوَّنت هذه المعاهدة من أربع عشرة مادة، وكانت مدتُها ثلاث سنوات، وانسحب الألمانُ من بلغراد ورومانيا بناءً على هذه المعاهدة بعد احتلالٍ دام سنة وعشرة أشهر، وكانت تلك آخِرَ حرب بين الجيوش الألمانية والجيوش العثمانية في التاريخِ."},{"id":4224,"era":"c13","t":"وقعة العدوة بين الشريف غالب والأمير سعود بن عبد العزيز .","s":"لَمَّا رجع الشريف بعد حملتِه غيرِ الموفَّقة على قصر الشعراء في أعالي نجد، انفرد عن كثير من البوادي وأكثرهم من مطير وقبائل شمر ورئيسهم مسعود الملقَّب حصان إبليس، وانحازوا إلى ماء معروف بالعدوة لشمر قُربَ حائل، فنهض لهم الأمير سعود بن عبد العزيز واستنفر أهلَ نجد البادي والحاضر، فسار بجنوده حتى نازلهم في تلك الناحية ووقع بينهم قتالٌ شديد، فانهزمت تلك البوادي وقُتِل منهم قتلى كثير من بينهم قائدُهم حصا"},{"id":4225,"era":"c13","t":"وفاة الملك يزيد الأول بن محمد الثالث ملك العلويين بالمغرب .","s":"هو يزيدُ الأول بن محمد الثالث ملك العلويين في المغرب الأقصى، الفرع الحسني الذي كان يقاتِلُ أخاه هشامًا الذي بايعه قبائِلُ الحوز في سبتة, فلما توفي يزيد الأول تولَّى أخوه هشام الملك خَلَفًا له."},{"id":4226,"era":"c13","t":"وفاة الأمير عبد المحسن بن سرداح رئيس بني خالد .","s":"هو الأميرُ عبد المحسن بن سرداح، رئيس بني خالد، توفِّيَ بعد وقعة غريميل سنة 1204 هرب عبد المحسن إلى المنتفق وتولى بني خالد زيدُ بن عريعر، ثمَّ إن زيدًا وإخوته أرسلوا إلى عبد المحسن ووعدوه بالأمان ومَنَّوه حتى جاء إلى الأحساءِ فقَتَلوه في مجلِسِهم."},{"id":4227,"era":"c13","t":"إصلاحات السلطان سليم الثالث الداخلية .","s":"كان السلطانُ سليم الثالث منذ أن تولَّى السلطنةَ سنة 1203هـ يدرِكُ أنَّ البلادَ بحاجة إلى إصلاحاتٍ داخليةٍ في كافةِ المجالات لا سيَّما الحربية؛ حيث إنَّ ضَعفَ سلطات استانبول سبَّب استئثار بعض الولاة بولاياتِهم وامتناعِهم عن دفعِ الأموال المتَّفَق عليها للخزينةِ السلطانية، وبعد هدوء القتالِ على الجبهات الخارجية انصرف السلطانُ سليم للإصلاحات الداخلية، فبدأ بتعيين أحدِ الشبَّان، وهو كوشك حسين باشا قبو"},{"id":4228,"era":"c13","t":"إجراء أول تجربة ناجحة على استخدام الغواصة في الدولة العثمانية .","s":"أُجريت أول تجربة ناجحة على استخدامِ الغواصة في الدولة العثمانية، وذلك في عهد السلطان أحمد الثالث، تُطلِقُ طوربيدًا من تحت الماء، وأطلِقَ على هذه الغواصة اسمَ \"تحت الماء\" وقد أشرف على صناعتها كبيرُ مهندسي السفن إبراهيم أفندي رئيس مهندسي مصنع السفن الإمبراطوري آنذاك, ثم أُدخلت هذه الغواصة ضِمنَ الأسطول الحربي العثماني."},{"id":4229,"era":"c13","t":"استعادة العثمانيين السيطرة على ميناء ومدينة وهران الجزائرية من الأسبان .","s":"استعاد العثمانيون السيطرةَ على ميناء ومدينة وهران الجزائرية من الأسبان، وذلك بعد ما سيطر الأسبان عليها 59 عامًا، وكانوا قد نجحوا في انتزاعها من العثمانيين سنة 1144هـ تقريبًا."},{"id":4230,"era":"c13","t":"روسيا تتوسع عسكريًّا على حساب الأتراك العثمانيين ومعاهدة ياش .","s":"رجعت النمسا عن تحالُفِها مع الروس ضِدَّ العثمانيين وعقدت صلحًا معهم وأعادت ما كانت أخذَته من العثمانيين، أما روسيا فقد استمَرَّت بالحرب واستولت على بعض المدنِ، فارتكبت من الجرائِمِ ما لا يوصف، ثم توسَّطت إنكلترا وهولندا للصلحِ بين الطرفين خوفًا على مصالحِهم، فكانت معاهدةُ ياش, أخذت بموجِبِها روسيا بلادَ القرم نهائيًّا، وبسارابيا وجزءًا من بلاد الشراكسة، والمنطقة الواقعة بين نهري بوغ ودنيسر، وأصبح "},{"id":4231,"era":"c13","t":"غزو الأمير سعود القطيف ومحاصرته لسيهات .","s":"تحرَّك الأميرُ سعود بقواتِه غازيًا القطيفَ، وقام بمحاصرة سيهات وأخذها عَنوةً، ثم احتَلَّ بلدة عنك، ثم سار إلى القديح وأخذها عَنوةً، ثم أخذ العوامية وحاصَرَ الفرضة؛ لأن أهلَ القطيف هربوا إليها فصالَحَهم بثلاثة آلاف زر، وأزال جميعَ ما في القطيف من الأوثان والمتعبدات والكنائس، وأمر سعودٌ بحرق كُتُبِهم القبيحة بعد ما جمعوا منها حملًا."},{"id":4232,"era":"c13","t":"وفاة الإمام المجدد محمد بن عبد الوهاب .","s":"هو شيخُ الإسلامِ الإمامُ المجَدِّد محمد بن عبد الوهاب ابنُ الفقيه العالم سليمان بن علي بن محمد بن أحمد بن راشد التميمي النجدي، ولِدَ في العُيينة بنجد سنة 1115ونشأ فيها، تربَّى في حجر أبيه الفقيه الحنبلي، ثم انتقل للحَجِّ والدراسة في الحجازِ، ثمَّ درس في البصرة وبغداد والأحساء، تأثَّرَ بكتب شيخ الإسلام ابن تيمية ودعوتِه، وخاصَّةً فكرة محاربة البدع والمعتقدات الشركية التي كانت منتشرةً بكثرةٍ في نجد "},{"id":4233,"era":"c13","t":"وفاة الأمير أحمد بن محمد آل خليفة مؤسس البحرين .","s":"هو الأميرُ أحمد بن محمد آل خليفة، الملقَّب بالفاتِحِ؛ لأنَّه يعتبَرُ المؤسِّسَ لإمارة البحرين والمثَبِّت الحقيقيَّ لحكم آل خليفة في الجزيرة البحرينية وشبه الجزيرة القطرية، وهو عتبي عنزي أسدي، من آلِ خليفةٍ، ولِدَ بالكويت في النصف الأول من القرن الثامن عشر، انتقل مع والده على رأس الأسرة إلى قطر عام (1175هـ/1762م) حيث أسَّسوا الزبارة كانت إقامته بالزبارة (على الساحل المقابل للبحرين) مع أخيه شيخ الزب"},{"id":4234,"era":"c13","t":"وفاة الملك هشام بن محمد الثالث ملك العلويين بالمغرب .","s":"هو المَلِكُ  هشام بن محمد الثالث ملك العلويين في المغرب الأقصى الفرع الحسني، بعد أن تولى بعد مَقتَلِ أخيه يزيد، لكِنَّه لم يلبث طويلًا حتى توفي في هذا العام متأثرًا بوباء أصابه، فخلَفَه أخوه سليمان."},{"id":4235,"era":"c13","t":"خضوع منطقة جبل شمر لدولة الدرعية .","s":"أدرك الإمامُ عبد العزيز بن محمد بن سعود، الذي نجحت جيوشُه في القضاءِ على ثوراتِ الخرج والقصيم أهميةَ منطقة جبل شمر لتأمين حدود دولتِه من الشمال، وأدرك أيضًا أهميتَها الاقتصادية؛ حيث تزدهِرُ فيها الزراعة، بالإضافة إلى علاقتِها التجارية بالعراقِ والبلاد المجاورة؛ لذا عزم على إخضاعِ أُمرائها آل علي لنفوذِ دولةِ الدرعية، فأرسل إليها الحَمَلاتِ تِباعًا، حملةً تلو حملة، واستمَرَّت تلك العملياتُ العسكرية"},{"id":4236,"era":"c13","t":"وقعة الشيط بين بني خالد والأمير سعود .","s":"لَمَّا تولى براك بن عبد المحسن أمرَ بني خالد نهض بجميعِ بني خالد للغزوِ، فورد اللصافة الماء المعروف، فأغار على عُربان سبيع وغيرهم, وأخذ منهم إبلًا كثيرة، فلما بلغ الأمير سعود خبَرُ بني خالد استشار من معه في النفير أو الحضير، فأشار عليه العُربان بالنفير طمعًا في الغنيمة، فتكلم حجيلان بن حمد فقال: هؤلاء مقصِدُهم الغنيمة ونحن مقصِدُنا عزُّ الإسلام والمسلمين، فانهض بالمسلمين في ساقةِ هذه الشَّوكةِ، فإ"},{"id":4237,"era":"c13","t":"أهل الأحساء يبايعون الأمير سعود ثم ينقضون العهد .","s":"لَمَّا بلغ أهلَ الأحساء هزيمةُ بني خالد في الشيط، وقع الرعب في قلوبهم وخافوا خوفًا عظيمًا، ثم سار الأمير سعود بجنوده ناحيةَ الأحساء فنزل الردينية الماء المعروف في الطف فأقام أيامًا وأتته المكاتبات مع رسل أهل الأحساء يدعونه إليهم ليبايعوه، فارتحل منها وسار إلى الأحساء ونزل عينَ النجم خارج البلدِ، فخرج إليه أهلُها وبايعوه على دين الله ورسولِه والسمع والطاعة, ثم دخل جيشُ سعود الأحساءَ فهَدَموا جميع م"},{"id":4238,"era":"c13","t":"وفاة الأمير سليمان بن عفيصان أمير الخرج .","s":"هو الأميرُ سليمان بن عفيصان أميرُ الخرج، وهو من أبرز قادةِ دولة الدرعية. كان ذا جرأةٍ وشجاعة, وكان كثيرًا ما يستعمله الإمامُ عبد العزيز في قيادة السرايا, وهو والد القائد إبراهيم بن عفيصان الذي تولى إمارة الخرج بعد والِدِه سليمان وخلَفَه في قيادة الجيوشِ."},{"id":4239,"era":"c13","t":"غزو إبراهيم ابن عفيصان قطر .","s":"غزا إبراهيمُ بنُ سُليمان بن عفيصان قطر، وهو أوَّلُ قائدٍ تابِعٍ لدولة الدرعية يقومُ بغزوها، واستطاع إخضاعَ مُعظَم قراها: فريحة والحويلة واليوسفية والرويضة وغيرها، وكتب إلى الدرعية يطلب السماحَ له بمهاجمة الزبارة، فجاءته الموافقةُ مِن الإمام عبد العزيز بن محمد، وحاصر إبراهيمُ فيها العتوب (آل خليفة وجماعتهم) وشدَّد هجماتِه عليها حتى استولى على قلعتِها، فاضطر العتوب إلى الرحيلِ وساروا إلى البحرين بوس"},{"id":4240,"era":"c13","t":"قيادة إبراهيم بن عفيصان أول حملة من الدرعية على الكويت .","s":"أدركت دولةُ الدرعية أهميَّةَ الكويت التي تعَدُّ ميناءً لتموين نجدٍ، فقام القائدُ إبراهيم بن عفيصان بحملةٍ عسكرية، ويبدو أنَّ من أسباب الحملةِ أيضًا إيواءَ الكويت لزعماء بني خالد الفارِّين من دولة الدرعية، وقد غنم إبراهيمُ في هذه الحملة غنائِمَ كثيرةً، لكنه لم يتمكَّنْ من إخضاع الكويت لسيادةِ دولةِ الدرعية."},{"id":4241,"era":"c13","t":"غزو سعود الأحساء ونهاية حكم آل حميد فيها .","s":"سار الأميرُ سعود بن عبد العزيز بجيوشِه من جميع نواحي نجدٍ وعُربانها، وقصَدَ الأحساءَ، وكان أهلُ الأحساءِ بعد نقضِهم العهدَ أتى إليهم زيدُ بن عريعر واستولى عليهم واستوطنَ البلَدَ هو وإخوانُه وذووه، فأقبل إليهم سعود  بجنوده وفرسانه، ومعهم براك بن عبد المحسن بن سرداح آل حميد مهاجر، ونزل سعودٌ بجنوده على قرية الشقيق المعروفة في الأحساء، فحاصرها يومين وأخذها عَنوةً، واستولى عليها وهرب أهلُها، تم اجتمع "},{"id":4242,"era":"c13","t":"قيام دولة القاجار في طهران بقيادة محمد حسن خان .","s":"وبعد وفاة كريم خان الكردي حاكم دولة الزنديين في إيران، انتفضَ على الحُكم زكي خان فقام في وجهه القاجار بقيادة آغا محمد، فبعث إليهم جيشًا إلى أصفهان بقيادةِ علي مراد خان الذي لم يلبثْ أن انقلب ضِدَّه واغتِيلَ زكي خان، وانطلق القاجار بقيادةِ زعيمِهم آغا محمد، ودخَلوا أصفهان غيرَ أنهم في البداية هُزموا أمام البختيار، ثمَّ إنَّ لطف الله خان الكردي استسلم للقاجار فقتلوه, وأبادوا أسرةَ الزندي، وهكذا انته"},{"id":4243,"era":"c13","t":"غزو الأمير سعود بن عبد العزيز تربة بالحجاز .","s":"سار الأمير سعود بن عبد العزيز بجنوده قاصدًا الحجاز ونازل أهلَ تربة بلد البقوم المعروفة، فحاصر أهلَها حصارًا شديدًا وقطع كثيرًا من نخيلها ووقع بينهما قتلى، ثم صالحه أهلُ البلد."},{"id":4244,"era":"c13","t":"الأزهر يثور ضد المماليك الترك في مصر .","s":"قام أهل بلبيس بالحضور إلى الشيخ وشكَوا إليه محمد بيك الألفي وظُلم أتباعه، فذهب الشيخ الشرقاوي للأزهر وجمع المشايخ وقفَّلوا أبواب الجامع، وذلك بعدما خطب مراد بيك وإبراهيم بيك، وفعلوا مثل ذلك اليوم الثاني، وأمروا الناسَ بغلق الأسواق والحوانيت، ثمَّ ركبوا مع جمعٍ كبير من العامَّةِ إلى بيت الشيخ السادات، وازدحم الناسُ فحضر الدفتردار أيوب بيك، فقالوا له إنَّ مرادهم هو رفعُ الظلم والجَور، وتطبيقُ العدل "},{"id":4245,"era":"c13","t":"عساكر الشريف غالب يغزون نجد .","s":"جمعَ الشريفُ غالب بن مساعد عساكِرَ كثيرةً، واستعمل عليها الشريفَ فهيد، فقصدوا قحطان وهم على ماسل الماء المعروف في عالية نجد، فتقاتلوا أشدَّ القتال، وانهزم ابن قرملة ومن معه من بني قحطان، فقُتل منهم 30 رجلًا، وأُخِذ منهم نحو 3000 من الإبل، ولَمَّا انهزموا ذهبوا مُشاةً في الصحراء ومعهم الأطفال والنساء وكادوا أن يهلِكوا من العطَشِ."},{"id":4246,"era":"c13","t":"غزو إبراهيم بن عفيصان عمان .","s":"لَمَّا وصل نفوذُ دولة الدرعية إلى منطقةِ الأحساء بدأ قادةُ الدولة يتطلَّعون إلى نشرِ مبادئ الدعوة في عمان، فأمر الإمامُ عبد العزيز بن محمد قائدَه مطلق المطيري بغزو عمان الصير؛ حيث تقطُنُ قبيلة بني ياس، إلا أنَّه لم يوفَّقْ في الاستيلاء على المنطقة، فعندها رأى الإمامُ عبد العزيز أن يكِلَ الأمر إلى قائده إبراهيم بن عفيصان الذي قاد معظَمَ الحملات السابقة في شرق الجزيرة، فقاد جيشًا كبيرًا إلى منطقة عم"},{"id":4247,"era":"c13","t":"هزيمة عساكر الشريف غالب في معركة الجمانية .","s":"جمع الشريفُ غالب صاحِبُ مكَّةَ جموعًا كثيرةً مِن باديتِه وحاضرته، واستعمل عليهم أميرًا الشريفَ ناصر بن يحيى، وسار من مكة، فلما بلغ خبرُهم الإمامَ عبد العزيز بن محمد بن سعود، أمر محمد بن حمود بن ربيعان ومن تبعه من عُربان عتيبة, وفيصل الدويش ومن تبعه من مطير, وربيع بن زيد أميرَ جميع الدواسر الحاضرة والبادية، وأمر أيضًا عربان السهول وعربان سبيع وعربان العجان وغيرهم من بوادي نجد؛ أمرهم جميعًا أن ينزلو"},{"id":4248,"era":"c13","t":"الولايات المتحدة توقع معاهدة مع العثمانيين تدفع على إثرها الجزية .","s":"في أواخرِ القرن الثامن عشر الميلادي بدأت السفنُ الأمريكية بعد أن استقلَّت أمريكا عن إنجلترا سنة 1190هـ ترفعُ أعلامَها لأولِ مرَّةٍ سنة 1197هـ وتجوب البحارَ والمحيطات. وقد تعرَّض البحَّارة الجزائريون لسفن الولايات المتحدة، فاستولوا على إحدى سفنِها في مياه قادش، وذلك في رمضان 1199هـ ثم ما لَبِثوا أن استولوا على إحدى عشرة سفينةً أخرى تخصُّ الولايات المتحدة الأمريكية وساقوها إلى السواحِلِ الجزائرية. و"},{"id":4249,"era":"c13","t":"وقوع غزوة الرقيقة وخضوع الأحساء لنفوذ دولة الدرعية .","s":"بعد طلَبِ برَّاك بن عبد المحسن الأمانَ لأهل الأحساء من الإمام عبد العزيز بن محمد، أُجيب إلى طلبِه، وانسحب جيشُ الأمير سعود من الأحساءِ بعد مبايعة أهلِها على السمع والطاعة، وبعد ذلك بسنواتٍ ثار أهل الأحساء بتحريضٍ مِن براك بن عبد المحسن نفسِه، ولكنْ قضى على ثورتهم إبراهيمُ بن عفيصان، ثمَّ وصول قوات كبيرة بقيادة الأميرِ سعود بن عبد العزيز الذي أخضع الأحساءَ لحكم دولة الدرعيةِ، وضرب عليهم ألوفًا من ا"},{"id":4250,"era":"c13","t":"وفاة آغا محمد خان قاجار حاكم إيران وتولي فتح علي شاه زعامة القاجاريين .","s":"هو آغا محمد خان بن محمد حسن خان القاجاري بن فتح علي خان بن شاه قلي خان، حاكم إيران. من مواليد 27 محرم 1155 في استر آباد وهو مؤسِّس الدولة القاجارية الشيعية في إيران- ومعنى آغا أي مَخصِي- وقيل: إنَّ محمد خان زند، هو الذي أخصى آغا محمد خان؛ لأنَّه تزوَّج من بنت أخيه علي خان زند بدون عقدٍ، وقيل إنَّ خِصاءَ آغا محمد خان كان على يد عادل شاه خليفة نادر شاه. أطاح آغا محمد خان بحُكم خلفاء كريم خان زند، ثم"},{"id":4251,"era":"c13","t":"ولاية ثويني بن عبد الله للمنتفق .","s":"في هذه السنة عزل سليمان باشا صاحَبَ العراقِ حمودَ بن ثامر عن ولاية المنتفق، وولَّى عليهم ثويني بن عبد الله، وكان ثويني قد قصد البصرةَ ونزل سفوان الماء المعروف قربَ البصرة، فاجتمع إليه قبائِلُ من عُربان المنتفق, فسار إليه حمود بن ثامر بمن تَبِعه من المنتفق وأهل الزبير وغيرهم, فنازله وحصل بينهما قتالٌ شديد انهزم ثويني فأخذ حمود ومن تبعه محلَّه ومتاعه وخيامه، وقُتِل من رجالِه عِدَّةُ قتلى, فهرب ثويني"},{"id":4252,"era":"c13","t":"سيل موصة في نجد .","s":"نزل سيلٌ عظيم أشفق منه كثيرٌ من أهل البلدان، وغرق منه حلةُ بلد الدلم ومحاها، ولم يبقَ مِن بيوتها  إلا القليل. وذهب لهم أموالٌ كثيرة من الطعام والأمتعة وغيرها, ونزل على بلدِ حريملاء بردٌ لم يُعرَف له نظير وخسَف السطوحَ وقتَلَ بهائمَ، وكسَّر عُسبان النخل والأشجار، وهَدَّم الجدران، حتى أشرفوا على الهلاك، ثم جاء في الصيف سيلٌ عظيم أشفق منه أهل البلدان، وهدم بعضَ حوطة بني تميم، وذهب بزروعٍ كثيرة محصورة"},{"id":4253,"era":"c13","t":"الدولة العثمانية تعقد معاهدة استانبول مع روسيا .","s":"عقدت الدولةُ العثمانيةُ مُعاهدة استانبول مع روسيا بعد مفاوضات استمرَّت خمسة أشهر، وتضَمَّنت المعاهدة أربعةَ عشر بندًا، منها أن يكونَ ذَهابُ وإياب السفير الروسي إلى استانبول عن طريقِ البر، وليس عن طريقِ البحرِ؛ لأنَّ البحر الأسود بحرٌ عُثماني مُغلَق."},{"id":4254,"era":"c13","t":"علماء نجد يناظرون علماء الحرم .","s":"طلب الشريفُ غالب بن مساعد شريفُ مكة من الإمام عبد العزيز بن محمد أن يبعثَ إليه عالِمًا ليناظِرَ علماء الحرم الشريف في شيءٍ من أمور الدين، فبعثَ إليه الإمامُ عبد العزيز الشيخَ حمد بن ناصر بن معمر على رأسِ ركبٍ من العلماء، فلمَّا وصلوا إلى الحرم الشريف أناخوا رواحِلَهم أمام قصرِ الشريف غالب فاستقبلَهم بالحفاوة والإكرام، وأنزلهم منزلًا محترمًا يليقُ بهم، فلما طافوا وسعَوا للعمرة ونحروا الجَزورَ التي "},{"id":4255,"era":"c13","t":"عتيبة وعربان الحجاز يبايعون الإمام عبد العزيز .","s":"أرسل حمود بن ربيعان ومَن تَبِعَه من عتيبة وعُربان الحجاز إلى الإمام عبد العزيز وطلبوا منه البيعةَ على دينِ الله ورسولِه والسَّمعِ والطاعة، وأداءِ الزكاة وألَّا يعترِضوا سُبُلَ المسلمين، وبَذَلوا دراهِمَ معلومةً نكالًا، فأجابَهم عبد العزيز إلى ذلك، وأخذ على كل بيتٍ عِدَّةَ دراهِمَ معلومة، فلمَّا بلغ الشريف غالب ذلك الخبَرُ، أفزعه وأهمَّه، فجهَّز العساكِرَ مِن مكَّةَ وما حولها، فخرج بنفسِه وقصد هادي"},{"id":4256,"era":"c13","t":"الحملة الفرنسية بقيادة نابليون بونابرت على مصر .","s":"أمرت الجمهوريةُ الفرنسيَّةُ بونابرت بالمسيرِ إلى مصر لفتحِها بغير إعلانِ حربٍ على الدولة العليَّة، وأوصَتْه بكتمانِ الأمر حتى لا تعلَمَ به إنكلترا فتسعى في إحباطِه، وكان القصدُ من الحملة منعَ مرور تجارة الإنجليز من مصرَ إلى الهند, كانت تلك الحملةُ صدًى للثورة الفرنسية المتأثِّرة بأفكارِها الثوريَّة الماسونية اليهودية، ورَفْع شعاراتها (الحرية, العدل, المساواة). فجهَّز جيشًا من 36 ألف مقاتل وعشرة آل"},{"id":4257,"era":"c13","t":"أمير القصيم يغير على عربان الشرارات بالشام .","s":"غزا حجيلان بن حمد أميرُ ناحية القصيم وغيرِهم، وقصَدوا أرضَ الشام وأغاروا على عُربان الشَّرارات فانهزموا فقُتِل منهم نحوُ مائة وعشرين رجلًا, وأخذوا جميعَ محلَّتِهم وأمتاعِهم وأزوادِهم, وأخذوا من الإبلِ خَمسةَ آلاف بعير وأغنامًا كثيرة, وعُزِلت الأخماسُ فأخذها عمَّالُ عبد العزيز, وقسَّم حجيلان باقيَها في ذلك الجيشِ، غنيمةُ الراجِلِ سَهمٌ والفارِسِ سهمانِ."},{"id":4258,"era":"c13","t":"رؤساء البقوم وأهل تربة يبايعون الإمام عبد العزيز .","s":"وفد رؤساءُ البقوم وأهل تربة على الإمامِ عبد العزيز وبايعوه على دينِ لله ورسولِه، وعلى السَّمعِ والطَّاعةِ."},{"id":4259,"era":"c13","t":"هزيمة الشريف غالب عند بلد الخرمة .","s":"لمَّا بلغ الإمامَ عبد العزيز غزوُ الشريف غالب رنية وبيشة، وعدوانُه على قحطان ونزولُه بلد الخرمة (من محافظات منطقة مكة المكرمة) القريبة من تربة. أرسل إلى هادي بن قرملة ومَن لديه من قبائل قحطان، وربيع بن زيد أميرِ الوادي ومن معه من الدواسرِ، وإلى قبائل من أخلاطِ القبائل البوادي، وجيشٍ مِن الحضَرِ، وأمرهم أن يجتمعوا ويكونوا في وجهِ الشريف غالب، فدهموه في منزلِه على الخرمة فانهزم عسكرُه لا يلوي أحدٌ ع"},{"id":4260,"era":"c13","t":"هزيمة أهل العراق في وقعة سحبة ومقتل ثويني بن عبد الله رئيس المنتفق .","s":"لَمَّا عيَّن سليمان باشا صاحب العراق ثويني بن عبد الله رئيسًا للمنتفق وقَدِمَ ثويني البصرةَ، فرح به أهلُ البصرة وما حولها من الأوطان فرحًا شديدًا, وقالوا: هذا الذي سيأخذُ الثأر ويخربُ تلك الديار- التابعة لدولة الدرعيَّة- وأتته منهم القصائِدُ يحضُّونه ويحَرِّضونه ويعجِّلونه بالمسير, وعَمِلَ محمد بن فيروز قصيدةً في التحريض على أتباعِ الدرعية. استنفر ثويني رعاياه وحشد عُربان المنتفق وأهل الزبير والبص"},{"id":4261,"era":"c13","t":"وفاة ثويني بن عبد الله رئيس المنتفق  .","s":"هو الأميرُ ثويني بن عبد الله بن محمد بن مانع آل شبيب السعدون، من فرع آل شبيب رئيس المنتفق، خَلَف والدَه في رئاسة المنتفق في العراق سنة 1175هـ وهو صغير السن، واستفرد بزعامة المنتفق بعد مقتلِ ابنِ عمِّه ثامر بن سعدون بن محمد بن مانع سنة 1193هـ / 1779م. احتلَّ البصرة سنة 1202ه فحكمها مستقلًّا ثلاث سنوات، التجأ ثويني إلى الدرعية مستنصرًا بحاكِمِها الإمامِ عبد العزيز ليستعيدَ رئاسته للمنتفق، فقدَّم له "},{"id":4262,"era":"c13","t":"الأمير سعود بن عبد العزيز يسير إلى سوق الشيوخ بالبصرة .","s":"سار الأميرُ سعودُ بن عبد العزيز من جميعِ نواحي نجدٍ وعُربانها وقَصَد الشمال، وأغار على سوقِ الشيوخ المعروفِ عند البصرة، وقُتِل منهم قتلى كثيرة وهرب أناسٌ وغَرِقوا بالشطِّ، ثم قصد جهةَ السماوة فأتاه عيونُه وأخبروه بعُربان كثير مجتمعينَ في الأبيض الماء المعروف قرب السَّماوة, فنازلهم على مائِهم ذلك, وكانت تلك العُربان كثيرةٌ مِن عُربان شمر ورئيسُهم مطلق بـن محمد الجربا الفارس المشهور، ومعه عِدَّةٌ من"},{"id":4263,"era":"c13","t":"الشريف غالب بن مساعد يغزو رنية وبيشة ويغير على قحطان .","s":"سار الشَّريفُ غالب بن مساعد شريفُ مكَّةَ بالعساكِرِ العظيمة من الباديةِ والحاضرة وأهلِ مِصرَ والمغاربة؛ سار في عددٍ عظيمٍ وعُدَّة وكمية هائلة من المدافِعِ والآلاتِ وتوجَّه إلى بلد رنية ونازل أهلَها وحاصَرَها، ودمَّرَ فيها نخيلًا وزروعًا ووقع بينه وبين أهلِها قِتالٌ شديدٌ قُتِل فيه من عسكرِ الشريف غالبٍ عدَّةُ قتلى، وأقام محاصِرَها عشرين يومًا، ثم ارتحل منها إلى بيشة، ونازل أهلَها وحصل بينهم قتالٌ،"},{"id":4264,"era":"c13","t":"قيادة مناع أبي رجلين الحملة الثانية على الكويت .","s":"قاد مناع أبو رجلين الحملةَ الثانيةَ على الكويت بعد حملةِ إبراهيمَ بنِ عفيصان، وكان النصرُ حليفَ قوات دولة الدرعيَّة، واضطُرَّ آل صباح إثرَ هذه الحملة إلى أن يُحيطوا الكويت بسورٍ منيع حتى تستطيعَ صَدَّ العمليات العسكرية الموجَّهة ضِدَّها."},{"id":4265,"era":"c13","t":"الشريف غالب يصالح الإمام عبد العزيز ويبايعه ويأذن له بالحج .","s":"لم يلبَث الشريفُ غالب شريفُ مكَّةَ بعد هزيمتِه في الخرمة (من محافظات منطقة مكة المكرمة) أنْ صالحَ الإمامَ عبد العزيز وبايعه وأذِنَ له ولأتباعِه بالحَجِّ."},{"id":4266,"era":"c13","t":"كتاب بونابرت للشعب المصري .","s":"يقول الجبرتي: \"كانت الفرنسيسُ حين دخولهم بالإسكندرية كتبوا مرسومًا وطبَعوه وأرسلوا منه نُسخًا إلى البلاد التي يَقدَمون عليها؛ تطمينًا لهم، ووصل هذا المكتوبُ مع جملةٍ مِن الأُسارى الذين وجدوهم بمالطة وحضروا صُحبتَهم، وحضرَ منهم جملةٌ إلى بولاق، وذلك قبل وُصولِ الفرنسيس بيومٍ أو بيومين، ومعهم منه عِدَّةُ نُسَخ، ومنهم مغاربة وفيهم جواسيس وهم على شَكلِهم من كفَّار مالطة ويعرفون باللغات, وصورةُ ذلك الم"},{"id":4267,"era":"c13","t":"فشل الحملة الفرنسية في إخضاع الشام وفلسطين .","s":"لَمَّا اجتمعت الدولُ الثلاثُ العثمانيون والإنجليز والروس على حرب نابليون بونابرت في مصرَ، تأكَّد لديه أهميةُ مفاجأتهم باحتلالِ بلاد الشام، وأنَّ من يحتل مصر لا يكون آمنًا فيها إلَّا إذا احتَلَّ بلاد الشام, فعزم على احتلالها قبل وصولِ القوات العثمانية والإنجليزية إليها, فخرج من مصرَ ومعه ثلاثة عشر ألف مقاتل، قاصدًا بلاد الشام من طريقِ العريشِ، فاحتَلَّها ثم أخذ غزة والرملة ويافا, ثمَّ رحل من يافا ل"},{"id":4268,"era":"c13","t":"نابليون يجلب معه أول مطبعة لمصر أنشأها في بولاق بالقاهرة .","s":"ظلَّت الكتابةُ في مصرَ تعتَمِدُ على النَّسخِ اليدوي حتى نهايةِ القرن الثامن عشر، فلم يعرِفْ وادي النيل المطابعَ إلَّا مع قدوم نابليون بونابرت لمصر، الذي جلب معه من الفاتيكان أوَّلَ مطبعة أنشأها في بولاق بالقاهرة، وكان قد حَمَل معه ثلاث مطابع مجَهَّزة بحروف عربية ويونانية وفرنسية، وكان الهدفُ الأساسي لهذه المطابع هو طباعةَ المنشورات والأوامر، وكانت تقومُ بعملها في عُرض البحر، حتى دخلت الحملةُ القاه"},{"id":4269,"era":"c13","t":"ثورة القاهرة الأولى ضد الفرنسيين وقيادة الأزهر لها .","s":"كان بونابرت وقت اندلاع المعركة خارجَ القاهرة، فعاد إليها مسرعًا ونصب المدافِعَ على تلال المقطَّم لتعاون مدافع القلعة في إطلاق القنابل على حي الأزهر، مركز حركة الجهاد وشُعلته المتأجِّجة. ففي اليوم الثاني للثورة (22 أكتوبر) حين شرع الثوارُ في مهاجمة مقر القيادة الفرنسية العامة بحي الأزبكية، كان الجنود الفرنسيون يهاجِمون الجامع الأزهر، ثم دخلوه وهم راكبون الخيول وسَلَبوا ما كان فيه من الودائِعِ وألقَ"},{"id":4270,"era":"c13","t":"السلطان سليم الثالث يعلن الجهاد ضد الفرنسيين الذين احتلوا مصر .","s":"كان الهجومُ الفرنسي على مصر يُعتبَرُ أوَّلَ هجوم صليبي على ولايةٍ عربية من ولايات الدولة العثمانية في التاريخِ الحديث، وعلى الفورِ أعلن السلطانُ سليم الثالث الجهادَ على الفرنسيين الصليبيين واستجاب لدعوته المسلمون في الحجاز والشام وشمال أفريقيا, فمن الحجاز خرجت جموعٌ من المسلمين بقيادة محمد الكيلاني، وتكوَّنت من مسلمي الوجه القبلي في مصر وخاصة عرب الهوَّارة، وأهالي النوبة، وقوَّات مراد بك جبهةٌ حرب"},{"id":4271,"era":"c13","t":"حصار الفرنسيين لعكا .","s":"بعد أن احتلَّ الفرنسيون يافا اتَّجَهوا إلى عكَّا بلد أحمد الجزَّار، فحاصروها وهاجموها مرارًا على مدى ستين يومًا، لكنهم لم يتمكَّنوا من فتحِها بسبَبِ مناعة حُصونِها, ووصولِ المدد إليها تباعًا من طريق البحر, واستيلاءِ الأميرال الإنجليزي سدني سميث على مدافِعِ الحصار التي أرسلها بونابرت من مصر لإطلاقها على أسوار عكَّا، ولتيَقُّظِ أحمد باشا الجزَّار قائدِ حاميتها، وإفسادِه الألغام التي زرعها الفرنسيون,"},{"id":4272,"era":"c13","t":"الإنجليز يهزمون الفرنسيين في أبي قير .","s":"كانت بريطانيا تتابِعُ الأطماعَ الفرنسية في مصر وغيرها بدقَّةٍ متناهية، وعندما تحرَّكت الحملةُ الفرنسيةُ ووصلت إلى مصر، أرسلت أسطولًا بقيادة الأميرال نلسون لتعقُّبِ الحملة الفرنسية، وفاجأ نلسون الأسطولَ الفرنسيَّ وهو رابضٌ في خليجِ أبي قير بعد أن أنزل قواتِ الحملةِ في الإسكندرية، واشتبك معه في معركة أدَّت إلى إغراقِ المراكب الفرنسية في أوَّلِ أغسطس 1718م، وقد كانت إنكلترا عَرَضت المساعدة على العثما"},{"id":4273,"era":"c13","t":"دخول الفرنسيين الإسكندرية .","s":"كان أوَّل ما حضر إلى الإسكندرية في أوَّلِ هذه السنة مراكِب للإنجليز زعموا أنَّهم جاؤوا ليحمُوا الثغر من الفرنسيين، فإنَّهم في طريقهم لاحتلال مصر, ولكنَّ أهل الإسكندرية ظنُّوا أن هذه مخادعة وقالوا: هذه بلاد السلطان، لا سبيل للإنجليز ولا للفرنسيين عليها، فرحل الإنجليزُ، ومع ذلك لم يفعل أمراءُ البلد شيئًا، أما أهل الإسكندرية فجمعوا العُربان وتهيَّأ الناسُ لِمثل هذا الحدَثِ، ثم وصلت مراكبُ الفرنسيين و"},{"id":4274,"era":"c13","t":"دخول الجنود الفرنسيين مدينة القاهرة واقتحام الجامع الأزهر .","s":"فتح الجنودُ الفرنسيون في مصرَ بعضَ البيوت المغلَقة لأمراء المماليك واستولوا على ما فيها، ثم تركوها لطائفةِ الجعيدية يستأصلونَ ما فيها، وقد توافد الفرنسيون بعدها على القاهرةِ وسَكَنوا بيوتها. فتجمَّع أهل مصر (القاهرة) وجمعوا السلاحَ والفرسان وتجمَّعوا في الأزهر وعملوا المتاريسَ ثم وصلت طائفةٌ من الفرنسيين من ناحية المناخلية، فاستطاعوا إجلاءَها من المقاتلين المصريين، فخاف الناس وأرجفوا حتى بلغ إلى ن"},{"id":4275,"era":"c13","t":"قتل محمد كريم حاكم الإسكندرية لمقاومته الفرنسيين .","s":"لَمَّا نزل الفرنسيون بالإسكندرية أخذوا محمد كريم الذي كان بيده أمرُ الديوان والجمارك ومصادرات التجار خصوصًا من الإفرنج في الإسكندرية، فحبسوه وطالبوه بالمال وضيَّقوا عليه في المركب، ولَما حضروا إلى مصر وطلعوا إلى قصر مراد بيك، وفيها اطَّلعوا على أخبار محمد كريم وتعَرَّفوا على اجتهاده في حربِهم وتهوين أمرِهم وتنقيصِهم، فاشتد غيظُهم عليه فأرسلوا وأحضروه إلى مصر وحبَسوه، ولم تنفع الشفاعات فيه أبدًا، ث"},{"id":4276,"era":"c13","t":"حملة علي كيخيا على الأحساء .","s":"سيَّر سلمان باشا والي العراق العساكِرَ الكثيرة من العراق والأكراد والمحمرة، ومعهم من البوادي عُربان المنتفق مع رئيسِهم حمود بن ثامر، وعُربان آل بعيج، والزقاريط وآل قشعم، وجميع بوادي العراق، وعربان شمر والظفير، وسار معه أهل الزبير وما يليهم، وجعل على قيادةِ الحملة وزيره علي كيخيا، واتفق له قوةٌ هائلة من المدافع والقنابر وآلات الحروب، واجتمع معه جموع كثيرة، حتى قيل إنَّ الخيل الذي يعلَّقُ عليها ثمان"},{"id":4277,"era":"c13","t":"ركب من أهل نجد يحجون ويعودون سالمين .","s":"حجَّ ركبٌ من أهل نجدٍ في هذا العام، فيهم عليٌّ ابنُ الشيخ محمد بن عبد الوهاب وأخوه إبراهيم، وإبراهيمُ بن سدحان رئيس بلد شقراء، ورفقة معهم من أهل الوشم وأهل القصيم، وقَضَوا حجَّهم ورجعوا سالمين، وذلك أنَّ الشريف بعد وقعة الخرمة (من محافظات منطقة مكة المكرمة) سنة 1212 أرسل إلى الإمام عبد العزيز وطلب الصلحَ والمهادنة، فأجابه إلى ذلك وأذِنَ لأهل نجد بالحَجِّ بعد أن كانوا ممنوعين منه منذ عقودٍ."},{"id":4278,"era":"c13","t":"انتصار نابليون على الأتراك في أبي قير .","s":"بعد عودةِ القوات الفرنسية من الشامِ إلى مصر انتصَرَ بونابرت في معركة أبو قير البريَّة على قوَّة عثمانية اتخَذَت طريقَها في رودس إلى مصر، وكان من أهمِّ نتائج هذه الموقعة حصولُ بونابرت من القائِدِ العثماني مصطفى باشا الذي وقع في الأسرِ على معلوماتٍ تفيد بأن حربًا عامَّةً في أوروبا قد اندلعت ضِدَّ فرنسا."},{"id":4279,"era":"c13","t":"اتفاق العريش لإجلاء الفرنسيين عن مصر .","s":"بعد رحيلِ نابليون بونابرت إلى فرنسا أقبلَ كليبر على تصريفِ الأمورِ بكُلِّ همَّةٍ، فأعَدَّ تنظيمَ الحكومةِ وقَسَّم القُطرَ المصريَّ إلى ثمانية أقاليم إدارية، وبادر بالكتابةِ إلى الصدر الأعظم ينفي رغبةَ فرنسا في انتزاعِ مِصرَ مِن تركيا، ويذكُرُ الأسبابَ التي جعلت فرنسا تُرسِلُ حَملتَها إلى مصرَ، وهي محاولةُ إلقاء الرُّعبِ في قلوبِ الإنجليز، وتهديدُ ممتلكاتهم في الهندِ، وإرغامُهم على قَبولِ الصلح مع "},{"id":4280,"era":"c13","t":"بريطانيا توقع اتفاقية تعاون مع إمام مسقط .","s":"لما قام نابليون بونابرت بغزو مصر استغَلَّت بريطانيا الظروفَ لوضع العراقيل أمامَ الفرنسيين للحِفاظِ على مركزها في الهندِ، وقد تولى ولزلي الحاكمُ البريطاني في الهند هذه المهمَّةَ؛ إذ بعث ميرزا مهدي علي خان المقيم البريطاني في بوشهر إلى مسقط لعقدِ معاهدة مع سلطان بن أحمد تهدف إلى إبعادِ مسقط عن الفرنسيين؛ حيث تعتبر مسقط مفتاحَ باب الخليج العربي، ولِمَنع بقاء العلاقات العمانية الفرنسية، ووُقِّعَت المع"},{"id":4281,"era":"c13","t":"نابليون يدعو يهود العالم لأجل القتال معه لإعادة القدس القديمة .","s":"رأى القائِدُ الفرنسي نابليون بونابرت أنَّ السيطرةَ على فلسطين ضرورةٌ حيوية لحمايةِ وتأمين مصالحِ الإمبراطورية الفرنسية، فهي من جِهةٍ تأخُذُ لفرنسا نصيبَها من تركة الخلافةِ العثمانية التي كانت تُحتَضَر آنذاك، ومن جهةٍ أخرى تمكِّنُه من الفوز في السباقِ مع منافِستِه بريطانيا، كما تحَقِّقُ له حلمَه الكبيرَ في السيطرة على مصرَ التي كان يعتبِرُها أهمَّ بلد في العالم. وكان نابليون أولَ زعيم أوروبي يعرِضُ"},{"id":4282,"era":"c13","t":"اشتعال ثورة القاهرة الثانية ضد الحملة الفرنسية .","s":"اشتعلت ثورةُ القاهرة الثانية ضِدَّ الحملة الفرنسية، وامتَدَّت إلى سائر أحياء العاصمة على مدى ثلاثة وثلاثين يومًا، واشترك في هذه الثورة كلٌّ من العثمانيين والأمراء المماليك مع أفراد الشعب المصري، وانتهت باتفاق كليبر قائد الحملة الفرنسية في ذاك الوقتِ ومراد بك أحد زعماء المماليك على الصلحِ فيما بينهما، على أن يكونا حُلفاءً لبعضهما ضِدَّ أي قوى أخرى، وهنا أمدَّ مراد بك الفرنسيين بالحطَبِ والسلاح وساع"},{"id":4283,"era":"c13","t":"الأمير سعود بن عبد العزيز يحج حجته الأولى .","s":"حجَّ الأميرُ سعود بن عبد العزيز حجَّتَه الأولى، وكان معه غالِبُ أهل نجد والجنوب والأحساء والبوادي وغيرهم، وكانت حَجَّةً حافلةً بالشوكة وجميعِ الخيلِ والجَيشِ والأثقالِ، واعتمروا وقَضَوا حجَّهم على أحسَنِ الأحوالِ، ولم ينَلْهم مكروهٌ ورجَعوا سالِمين."},{"id":4284,"era":"c13","t":"هزيمة العثمانيين في معركة عين شمس (هليوبوليس) أمام الفرنسيين .","s":"أمام هذا التحول المفاجئ من تدخُّل الإنجليز في وجهِ اتفاق العريش لجلاء الفرنسيين من مصر، لم يجد كليبر مفرًّا من وقف عملية الجلاء التي كان قد بدأها تنفيذًا لاتفاقية العريش، ثم أسرع في صبيحةِ اليوم بالزَّحفِ على رأس جيشِه لوقفِ تقدُّم العثمانيين الذين وصلت طلائعُهم إلى المطرية على مسافةِ ساعتين من القاهرة، فوقعت معركةُ عين شمس (هليوبوليس) التي امتدَّ ميدانُها من المطرية حتى جهات الصالحية، وهزم الفرنس"},{"id":4285,"era":"c13","t":"ثورة القاهرة الثالثة ضد الفرنسيين .","s":"أثناء معركة هليوبوليس كان فريقٌ مِن جيش الصدر الأعظم وبعضِ عناصر المماليك قد تسلَّلوا إلى داخِلِ القاهرة وأثاروا أهلَها على الفرنسيين، فكانت ثورةُ القاهرة الثالثة التي استمَرَّت مدة شهر تقريبًا، ولم يستطع كليبر إخماد الثورة إلَّا بعد التجائه إلى العنف، فدَكَّ القاهرة بالمدافع من كلِّ جانب، وشدَّد الضربَ على حي بولاق، حيث تركَّزت الثورة، فاندلعت ألسنة النيران في كل مكانٍ منه، والتهمت الحرائقُ عددًا"},{"id":4286,"era":"c13","t":"بدء محاكمة سليمان الحلبي لقتله قائد الحملة الفرنسية في مصر .","s":"بعد قتل سليمانَ الحلبي للقائِدِ الفرنسي كليبر قائِدِ الحملة الفرنسية على مصرَ، تم القبض عليه وبدأت محاكمتُه، التي استمرت لمدة 3 أيام، نُفِّذ بعدها حكمُ القَتلِ في الحلبي بعد حَرقِ يده، ثم وضعه على الخازوق الذي اخترق مؤخِّرتَه، وبَقِيَ على هذه الحالة البشعة حتى توفِّي، ثم قُطِعت رأسه، وما زالت موجودةً في متحف الإنسان في باريس، مع الخنجرِ الذي قَتَل به كليبر!!!"},{"id":4287,"era":"c13","t":"إغلاق الفرنسيين الجامع الأزهر عقب اغتيال كليبر .","s":"تمَّ إغلاق الجامِعِ الأزهر أيَّامَ الحملة الفرنسية على مصر، وذلك عَقِب اغتيالِ القائد الفرنسي كليبر قائِدِ الحملة على مصرَ على يد الطالب الأزهري سليمان الحلبي، وظلَّ المسجد مغلقًا لأول مرة منذ إنشائه حتى خرجت الحملةُ من مصر."},{"id":4288,"era":"c13","t":"الإمام عبد العزيز يوجه الدعوة إلى الإمام المنصور صاحب اليمن .","s":"قال الإمام الشوكاني: \"وفي سنة 1215 وصل من صاحِبِ نجدٍ الإمامِ عبد العزيز مجلَّدان لطيفان، أرسل بهما إلى حضرة مولانا الإمام حَفِظه الله، أحدُهما يشتَمِلُ على رسائل لمحمد بن عبد الوهاب كلُّها في الإرشاد إلى إخلاص التوحيد والتنفير من الشرك الذي يفعله المعتَقِدون في القبور، وهي رسائلُ جيدة مشحونة بأدلَّة الكتاب والسنة، والمجلَّد الآخر يتضمَّنُ الردَّ على جماعةٍ مِن المقصِّرين من فقهاءِ صَنعاءَ وصَعدة "},{"id":4289,"era":"c13","t":"الإمام عبد العزيز بن محمد يعزم على الحج .","s":"عزم الإمامُ عبد العزيز بن محمد بن سعود الحجَّ بالنَّاسِ الحَجَّةَ الثانية, وقد احتفلوا احتفالًا عظيما بالحَجَّة الأولى في السنة الماضية, وأجمل معه في الحجِّ غالب أهل نجد ومن تَبِعَهم من البوادي وغيرهم من النساء والأطفال، وخرج معه للحَجِّ ابنه الأمير سعود, ثمَّ إن الإمام عبد العزيز لما سار سبعة ووصل قرب الدوادمي المعروف في عالية نجد أيام، آنسَ من نفسه الملل والثِّقلَ فرجع للدرعية، وحَجَّ بالناس الأ"},{"id":4290,"era":"c13","t":"خروج الفرنسيين والإنجليز من مصر .","s":"بعد مقتَلِ كليبر آلت القيادةُ العامَّةُ للحملةِ إلى الجنرال مينو باعتبارِه أكبَرَ ضباط الحملة سنًّا، وكان هذا القائِدُ مِن أنصار البقاء في مصر وخُطَّة سياسته استهدفت توطينَ الفرنسيين فيها، إلا أنَّ الضغوطات الداخلية والخارجية اضطرَتْه إلى مغادرة مصرَ بعد الهجوم المشترك الذي قام به الإنجليز والعثمانيون على الفرنسيين في مصر. فتظافرت عدَّةُ عوامل أرغمت المحتَلِّين الفرنسيين على الخروجِ مِن مصر في الن"},{"id":4291,"era":"c13","t":"والي مسقط يستولي على البحرين وآل خليفة يستنصر بالإمام عبد العزيز .","s":"سار سلطانُ بن أحمد صاحب مسقط البلد المعروف في عمان، في كثيرٍ من المراكب والسفن، ونازل أهل البحرين وأخذَه من يد آل خليفة, ثم آل خليفة ساروا إلى الإمام عبد العزيز في الدرعيَّة واستنصروه، فأمَدَّهم بجيش كثيفٍ تمكَّن من هزيمة سلطان أحمد وانتزاع البحرين منه وتسليمها لآل خليفة."},{"id":4292,"era":"c13","t":"إعادة افتتاح الأزهر بعد إغلاق أبوابه عقب مقتل كليبر .","s":"تمَّت إعادةُ افتتاح الجامع الأزهر بعد أن أُغلِقت أبوابُه عَقِبَ مَقتَلِ كليبر قائد الحملة الفرنسية في مصر، وقد ظل مُغلقًا زُهاءَ عام، حتى افتُتِح عند شروع الفرنسيين في الجلاء عن مصر."},{"id":4293,"era":"c13","t":"هجوم قوات الدرعية على كربلاء وهدمها القباب والأضرحة والمزارات الشيعية .","s":"بعد تصدِّي قبيلة الخزاعل الشيعية لبعضِ أتباع دولة الدرعية وقتلِها منهم حوالي 300 رجلٍ عام 1214هـ قُرْبَ النجف، احتَجَّ حكام الدرعية وطالبوا بديةِ القتلى، ولكِنْ لم يوافق الشيعة على ذلك، فتوجَّه الأمير سعود بجموعٍ كثيرة وقوَّة عظيمة إلى العراق، والتقى في كربلاء بجموعٍ كثيفة من الأعاجِمِ ورجال الشيعة الذين استماتوا في الدفاعِ عن معاقلهم الدينية، فانتصروا عليهم وأمَرَ الأمير سعود بهدمِ القباب والأضرح"},{"id":4294,"era":"c13","t":"نابليون يفاوض الدولة العثمانية لتحسين العلاقات .","s":"بعد أن هرب نابليون إلى فرنسا عندما عَلِمَ بأنَّ هناك مشروعًا مُشتركًا بين العثمانيين وإنكلترا وروسيا، أخذ يراسِلُ الدولة العثمانية من فرنسا لتحسين العلاقات بينهما وإعادة التفاهمِ، وتم ذلك في عام 1216هـ على أساس إخلاء فرنسا لمصر وتأييد امتيازات فرنسا السابقة في الدولة العثمانية، كما اتَّفَقت فرنسا وإنكلترا بمصالحة أميان, خرجت إنكلترا بموجِبِها من مصر وأصبح لفرنسا حقُّ الملاحة في البحر الأسود أسوةً "},{"id":4295,"era":"c13","t":"الشريف غالب  شريف مكة ينقض عهده مع الإمام عبد العزيز .","s":"في هذه السنةِ نقَضَ الشريفُ غالب شريفُ مكَّةَ الصلحَ مع الإمام عبد العزيز بن محمد بن سعود، ففارقه وزيرُه وزوج أخته عثمانُ بن عبد الرحمن المضايفي الذي خرجَ مِن مكة وترك الشريفَ غالبًا ونابَذَه، ووَفد المضايفي على الإمامِ عبد العزيز وبايعه على دينِ اللهِ ورَسولِه والسَّمعِ والطاعةِ، فعَيَّنه أميرًا على الطائف والحجازِ، وزَوَّده برسائِلَ إلى مشائخ القبائل يُعلِمُهم بهذا التعيين، ويطلُبُ منهم طاعتَه و"},{"id":4296,"era":"c13","t":"انضمام القواسم في رأس الخيمة لدعوة الشيخ محمد بن عبد الوهاب .","s":"وصلت دعوةُ الشيخ محمد بن عبد الوهاب سواحِلَ الخليج العربي بين عامي  1798-1805م؛ فقد انطلق مؤيِّدو دعوة الشيخ من البريمي نحو الخليج وعمان للداخل، وعبروا الجبالَ العمانية ووصلوا إلى مسقط، وانضَمَّت قبائل كثيرة لدعوتهم، ومنها القواسم وبنو علي، ولم ينقِذ الإمامَ العماني سلطانَ بن الإمام أحمد بن سعيد منهم سوى وفاةِ الإمام عبد العزيز في الدرعيَّة عام 1803 واضطرارهم للعودة إلى البريمي، وقد عقد القواسِمُ "},{"id":4297,"era":"c13","t":"وصول دعوة الإمام المجدد محمد بن عبد الوهاب اليمن .","s":"وصلت دعوةُ الإمام محمد بن عبد الوهاب اليمَنَ، ودخلَت بلادُ أبى عريش وأشرافُها في طاعةِ دولةِ الدرعية"},{"id":4298,"era":"c13","t":"عثمان المضايفي أميرا على الطائف من قبل الإمام عبد العزيز .","s":"لَمَّا فَشِل الشريف غالب في النَّيل من عثمان المضايفي في العبيلا، جمع المضايفي من يليه من الحاضرة والبادية، فسار إليه سالمُ بن شكبان بأهل بيشة وقراها, ومصلط بن قطنان بأهل رنية وقراها، ومن كان عنده من سبيع, وسار أيضًا حمد بن يحيى بأهل تربة ومعه البقوم, وسار هادي بين قرملة, ومعه جيش من قَحطان. وسار إليه غيرُ ذلك من عتيبة فاجتمعت تلك الجموعُ عند عثمان، فساروا إلى الطائِفِ وفيها الشريف غالب، وقد تحصَّ"},{"id":4299,"era":"c13","t":"وفاة سليمان باشا الكبير والي بغداد وخلفه علي باشا زوج ابنته في ولاية بغداد  .","s":"هو سليمان باشا أحد ولاة العراق, وكان من المماليك، وكان من عُتقاء محمد بك الدفتري الربيعي، واسمه سليمان آغا. ولِدَ في عام 1137هـ، وصار واليًا للبصرة، ثم نُقل واليًا على بغداد عام 1194هـ/1780م، وعُرِف بعد توليه ولاية بغداد باسم سليمان الكبير, وقد عُرِف عصرُه باسم العصر الذهبي لفترة حكم المماليك في العراق, في أواخر سنوات حكم سليمان باشا الكبير بدأت هجَمات أتباع دولة الدرعية، وكانوا يُغيرون على تخوم ا"},{"id":4300,"era":"c13","t":"تأسيس الدولة الكثيرية الثانية بحضرموت .","s":"جاءت مَرحلةُ الدولةِ الكَثيريةِ الثانيةِ، على يدِ السُّلطانِ جَعفرِ بنِ علِيِّ بنِ عُمَرَ بنِ جَعفرٍ الكَثيريِّ، الذي جاء مِن هِجرتِه الطويلةِ بجاوةَ والهِندِ سنةَ 1218م، ثم أقام أوَّلًا بهنن، وشَرَع يُكاتِبُ الشنافِرَ وفَهدًا وأعيانَ السادةِ العَلويةِ، ويَبثُّ الدُّعاةَ لِإحياءِ دولةِ آلِ كَثيرٍ، وقامَ بشراءِ عَبيدٍ وجَنَّدَهم لِلقتالِ، ثم قَويَ أمرُه واستَولى على مَناطقَ مِن حَضرَمَوتَ، وأرسَلَ "},{"id":4301,"era":"c13","t":"محمد علي يتولى حكم مصر .","s":"جاء محمدُ علي باشا إلى مصرَ مع الجنود الذين جاؤوا لإخراجِ الفرنسيين منها واستطاع بعد مناورات مع المماليك والولاة والعثمانيين والأهالي أن يتوصَّلَ إلى ولايةِ مصر في العاشرِ من شهر ربيع الثاني من عام 1220هـ حتى عندما حاول الإنجليز لدى الدولة العثمانية عزلَه أو نقلَه، تمسَّك به العلماء والقادة، فصدر أمرٌ بتثبيته عام 1221هـ، ثم استطاع أن يتفَرَّد بالحُكمِ بتخَلُّصِه من المماليك في حادثة القلعة عام 122"},{"id":4302,"era":"c13","t":"استعادة الشريف غالب حكم مكة .","s":"رحل الشريف غالب بعسكَرِه مِن جُدة إلى مكة، ونازل أهل القصور الذين رتَّبَهم الإمام سعود بعد عودتِه من حصار جدة, فتمكَّنَ الشريف غالب من إخراجِهم بالأمان، واستولى على مكة."},{"id":4303,"era":"c13","t":"قوات الدرعية تدخل البحرين .","s":"بدأ الصدام بين آل خليفة ودولة الدرعية عام 1210هـ وعندما اشتَدَّ حصار قوات الدرعية على الزبارة ارتحل عنها أهلها جميعًا وانتقلوا إلى جزيرة أورال، حيث أقاموا في قرية الجو الواقعة على أحد المرتفعات جنوبي الجزيرة التي بدأت تُعرَف بالبحرين، ثم تعرَّضوا لهجوم سلطان مسقط الذي استطاع أخذ رهائن من البحرين، فاستعان آل خليفة بالإمام عبد العزيز عام 1218هـ حيث تمكَّنوا بمساعدتهم من استرجاع الرهائنِ واستعادة الج"},{"id":4304,"era":"c13","t":"احتلال الإنجليز كابل .","s":"استطاع شُجاع الملك في هذا العام أن يستوليَ على كابل ويخلعَ أخاه محمودًا ويسجنَه وأن يُعلِنَ عن نفسِه مَلِكًا في بيشاور، ولكِنْ لم يلبَثْ أن استطاع أخوه فتح خان أن يهزِمَه ففَرَّ شجاع إلى بلادِ الهند عام 1224هـ أمَّا أخوهم دوست محمد فبدأ يقوَى نفوذُه حتى استولى على كابل، ولَقَّبَ نفسَه أميرَ كابل، فاستنجد شجاعٌ بالإنكليز الذين وطَّدوا نفوذَهم بالهند فأرسلوا جيشًا دخل كابل ونصَبوا شجاعَ الملك حاكِمً"},{"id":4305,"era":"c13","t":"غزو الإمام سعود البصرة .","s":"سار الإمامُ سعود من الدرعية بعد أن استلحق جميعَ رعاياه من البادي والحاضر، فنهض بجيوشه وقصدَ ناحية الشمال حتى نزل على قريةِ التنومة القريبة من القصيم فعيَّد فيها ونحَرَ ضحاياه بها، ثم أرخص عُربان الشمال من الظفيري وأذِنَ لهم بالعودة إلى أوطانِهم؛ لأنَّه يريد القفول إلى وطنه، وكان قصده أن يُبغِت أهل البصرة إذا بلَغَهم رجوعُه، ثم رحل من التنومة إلى جهة الدرعية، ثم رجع عاديًا إلى البصرة فوافق كتيبةَ خ"},{"id":4306,"era":"c13","t":"دخول الأمير سعود مكة بدون قتال .","s":"في الوقتِ الذي كانت الحربُ دائرةً بين الشريف غالب وعثمان المضايفي في الطائفِ، كان الأميرُ سعود بن عبد العزيز يجمَعُ البواديَ والحاضرة في السبلة الموقع القريب من بلدة الزلفي، فلما اجتمعوا إليه رحَلَ بهم إلى الحجاز ونزل العقيقَ المعروف عند المعان، وكان ذلك وقتَ الحَجِّ, وكانت الحُجَّاج الشاميَّة والمصريَّة والمغربية وغيرُهم في مكة، وهم في قوَّةٍ هائلةٍ وعُدَّة عظيمة، فهَمُّوا بالخروج إلى سعود والمسي"},{"id":4307,"era":"c13","t":"محاولة الأمير سعود فتح جدة .","s":"بعد أن استقَرَّت الأوضاع في مكَّةَ، ارتحل الأمير سعود إلى جُدَّة لفتحِها، فعسكر بجيشِه في الرغامة بالقربِ من سور جدة، فكتب إلى أهلها يدعوهم إلى التَّسليم, وكان الشريف غالب قد تحصَّن وراء سور جدة واستعد للقتالِ، فدامت المناوشات بينهما أسبوعًا، فلما رأى سعود حصانةَ جُدَّة رحل منها ورتب جندًا في قصرٍ مِن قصور مكَّةَ، ثمَّ رجع إلى الدرعية."},{"id":4308,"era":"c13","t":"هجوم سفينتي حرب أمريكيتين على السفن في ميناء طرابلس في ليبيا .","s":"على الرغم من معاهدة 1210ه بين الجزائر والولايات المتحدة، فإن السفنَ العثمانية التابعة لإيالة (ولاية) طرابلس بدأت في التعَرُّضِ للسفن الأمريكية التي تدخُلُ البحر المتوسط، وترتَّب على ذلك أن أرسَلَت الولايات المتحدة أسطولًا حربيًّا إلى ميناء طرابلس، هاجمت سفينتا حرب أمريكيتان تملك 35 مدفعًا السفُنَ الموجودةَ في ميناء طرابلس في ليبيا، إلَّا أن إحدى السفينتين (فلادليفيا) التي كانت تعدُّ أكبر سفينة في "},{"id":4309,"era":"c13","t":"وفاة الإمام عبد العزيز بن محمد بن سعود حاكم دولة الدرعية .","s":"هو الإمامُ عبد العزيز بن محمد بن سعود بن محمد بن مقرن، ولِدَ 1132هـ/1720م ونشأ في الدرعيَّة، ونهل من علومِها الشرعية، ودرس على عُلَماء عصره، وأبرزهم الشيخُ محمد بن عبد الوهاب في العُيَينة، وبعد قدومه الدرعية عام 1157هـ شارك في كثير من المعارك والحروبِ في حياة أبيه, وبعد وفاةِ والده تولَّى الحكمَ سنة 1179هـ, وأكمل بناءَ الدولة ونشر الدعوةَ الإصلاحية التي بدأ بها والده الإمام محمد بمؤازرة الإمامِ مح"},{"id":4310,"era":"c13","t":"عزل ابن ماجد عن حكم الأحساء وتعيين ابن عفيصان .","s":"عزل الإمامُ سعودٌ سُليمانَ بن محمد بن ماجد عن إمارةِ الأحساء واستعمل إبراهيم بن سليمان بن عفيصان أميرًا عليها."},{"id":4311,"era":"c13","t":"وفاة سلطان بن أحمد بن سعيد إمام مسقط .","s":"هو سلطان بن أحمد بن سعيد البوسعيد إمامُ مسقط وهو مؤسِّسُ دولة البوسعيدية في عمان، ولد في عمان, وكان قد عَمِل على توحيد البلاد وتقويتها، ثم الاهتمام بالخارج لتوسيعِ نفوذ دولته، وقد اصطدم بقوات دولة الدرعية في البحرين عندما غزاها وانتزعها من آلِ خليفة. قتله رجلٌ من القواسم أهل رأس الخيمة أتباع دعوةِ الشيخ محمد بن عبد الوهاب. كان سلطان أحمد ركب البحرَ وصادفه القواسم في عُرض البحر وقد نزل من مركبه الم"},{"id":4312,"era":"c13","t":"عبد الوهاب أبو نقطة يسير لقتال الشريف غالب شريف في جدة .","s":"سار عبد الوهاب بن عامر المعروف بكُنيتِه أبو نقطة أمير ألمع وعسير وتهامة قاصدًا جُدَّةَ محاربًا لها بأمر الإمام سعود الذي أمر على من في جهة عبد الوهاب من أهل الخبت والحجاز أن ينفروا معه إلى جدة, فسار عبد الوهاب بهم وهم ستة آلاف مقاتل, ونزل السعديةَ الماء المعروف قرب سيف البحر، فلما تحقق الشريف حالَهم أراد أن يباغِتَهم في مكانهم قبل أن يأتيَ إليه أبو نقطة بجيشِه، فجهَّز العساكر الكثيرة قيل إنها عشرة"},{"id":4313,"era":"c13","t":"الإمام سعود يسير لتأديب الظفيري لإخلالهم بفرائض الدين .","s":"سار الإمامُ سعود بجيوشه الكثيرة من جميع نواحي نجد والجنوب وعمان والأحساء وغير ذلك من البادي والحاضر، قاصدًا الشمال, وكان قد حدَث من عربان الظفير حوادِثُ من تضييع بعض فرائض الدين وإيواء المُحدَثين وإضافتهم، وأتاهم غزوٌ من بوادي الشمال، فأغاروا على بوادي المسلمين واجتازوا بالظفير فأضافوهم، وذكروا للإمام سعود أن أناسًا منهم يغزون مع أعداء المسلمين على بواديهم، وكان قبل ذلك قد حدَث بين الظفير ومطير بع"},{"id":4314,"era":"c13","t":"محاولة استيلاء الإنكليز على الدردنيل ووقوف العثمانيين ضدهم .","s":"تحسَّنت العلاقة الفرنسية العثمانية، فعزل السلطان أميري الأفلاق والبغدان من منصبيهما وكانا مؤيَّدَين من قبل روسيا، فثارت ثائرة روسيا وأرسلت جيوشَها لاحتلال الإقليمين دون إعلانِ حرب، وتضامنت إنكلترا مع روسيا وأرسلت قطعات بحرية إلى مضيق الدردنيل، وطلبت من الخليفة أن يقومَ حلف بين إنكلترا والدولة العثمانية، وأن تسلِّم الدولةُ الأسطول وقلاع مضيق الدردنيل إلى إنكلترا، وأن تتنازل عن إقليمي الأفلاق والبغد"},{"id":4315,"era":"c13","t":"أهل المدينة يبايعون الإمام سعود بن عبد العزيز .","s":"قبل مبايعة الشريف غالب بايع أهلُ المدينة الإمام سعود على دين الله ورسوله والسمع والطاعة، وهُدِّمت جميعُ القباب التي على القبور والمشاهد, وذلك أنَّ آل مضيان ورؤساء حرب ومن تبِعَهم من عُربانهم كانوا قد أحبُّوا الدعوة وأتباعها، فوفدوا على الإمام عبد العزيز في عهدِه وبايعوه, وأرسل معهم عثمان بن عبد المحسن أبا حسين يعلِّمُهم فرائض الدين ويقرِّرُ لهم التوحيد، فاجتمعوا على حرب المدينة ونزلوا عواليَها ثم "},{"id":4316,"era":"c13","t":"رئيس الحديدة وبيت الفقيه باليمن يبايع الإمام سعود ويغزو زبيد .","s":"بايع صالح بن يحيى العلقي رئيسُ الحُدَيدة وبيتُ الفقيه الإمامَ سعودًا على دين الله والسمع والطاعة، وحَسُنت عقيدته, فسيَّرَ إمامُ صنعاء عسكرًا حاصروا بندر الحديدة وأخذوه وأسروا ابن صالح، وكان والده استعمله أميرًا على الحُدَيدة, فجمع صالح جنوده وقومه وقبائل عديدة حاضرة وبادية نحو 3000 مقاتل، فنازل أهل زبيد وأخذوه عنوة، وغنموا منه من الأموال والمتاع الشيءَ الكثير، ولم يمتنع عليه إلا القلعةُ الأمامية و"},{"id":4317,"era":"c13","t":"عبد الوهاب أبو نقطة يغزو نجران بأمر من الإمام سعود .","s":"أمر الإمامُ سعود عبد الوهاب أبا نقطة ورعاياه من عسير وألمع وفهاد بن شكبان ورعاياه من بيشة وعبيدة وأهل سنحان ووادعة وقراها وأهل وادي الدواسر ومن تبعهم أن يقصِدوا نجران لقتالِ أهله, فسار هؤلاء في جمع بلغت عدته حوالي 30 ألفًا، ونازلوا أهلَ بدر مدَّةً وجرى بينهم وقائع وقتلى بين الفريقين، أكثَرُ القتلى من قوم عبد الوهاب, وأمر عبد الوهاب من معه أن يبنوا قصرًا مقابِلَ قصر بدر يصير ثغرًا لهم، ويضَيِّق على"},{"id":4318,"era":"c13","t":"الشريف غالب يطلب الصلح والمبايعة مع الإمام سعود .","s":"أمر الإمام سعود عبدَ الوهاب أبا نقطة وجميعَ رعاياه من تهامة وسالم بن شكبان ورعاياه من أهل بيشة ونواحيها وعثمان المضايفي بجميع أهل الحجاز بالمسير إلى مكة، فينزلون ويضيقون على أهلِها، وأمرهم بانتظار الحاج الشاميِّ وأن يمنعوه إذا كان محاربًا، فسارت تلك الجموع إلى مكة فاشتدَّ الأمر على الشريف غالب، وبلغ منه الجَهدُ، وطلب منهم الصلحَ ومواجهة الإمام سعود ومبايعته على دين الله ورسوله والسَّمعِ والطاعة فص"},{"id":4319,"era":"c13","t":"غلاء وقحط في بلدان الجزيرة العربية .","s":"اشتدَّ الغلاء والقحط على الناس في نجد وما يليها، وسقط كثير من أهل اليمن ومات أكثر إبلِهم وأغنامهم، وفي آخر هذا العام بلغ البُرُّ ثلاثة أصوع بريال, وبلغ التمر سبع وزنات بريال، وبِيعَ في ناحية الوشم والقصيم خمس وزنات بريال, وأمَّا في مكة فالأمر فيها أعظَمُ بسبب الحرب والحصار بعد نقض الشريف غالب الصلحَ مع الإمام سعود، فسُدَّت كُلُّ الطرق عن مكة من جهة اليمن والحجاز وتهامة ونجد؛ لأن أهل هذه البلدان كل"},{"id":4320,"era":"c13","t":"ثورة الزعيم الوطني عمر مكرم الشعبية ضد الوالي العثماني خورشيد باشا .","s":"قاد الزعيمُ الوطني عُمر مكرم ثورةً شعبية مسلَّحةً في مصر ضِدَّ الوالي العثماني خورشيد باشا؛ مِمَّا كان لها أكبر الأثر في تغيير حكمِ مصر حيث تمكَّنَت من إقصاء خورشيد عن الحكم، واختيار محمد علي واليًا على مصر."},{"id":4321,"era":"c13","t":"محمد علي مؤسس الأسرة العلوية بمصر، واعتراف الباب العالي به .","s":"ولد محمد علي في مدينة قَوَلة الساحلية في جنوب مقدونيا عام 1769م، وهو تركي عثماني لا يمتُّ للألبانيين ولا لصقالبة مقدونية ولا يونانها بسببٍ ولا نسب، لكنَّه حين قدم مصر جاء مع الفرقة الألبانية التي أرسلها السلطانُ العثماني إلى مصر؛ ممَّا أشكَلَ أمره على البعض، فحسِبَ أنَّ له أصلًا ألبانيًّا! وكان محمد علي قد اختاره المصريون ليكون واليًا على مصر، فبعد جلاء الفرنسيين عن مصرَ استطاع محمد علي أن يسيطرَ "},{"id":4322,"era":"c13","t":"الشريف غالب يخل في الالتزام بالصلح الإمام سعود .","s":"بعد أن حَقَّق الإمامُ سعود طلَبَ الشريف غالب في الصلحِ والمبايعة، وقع من الشريفِ ما يَريبُ منها: أنَّه أبقى في مكة عسكرًا من الترك والمغاربة وغيرهم من الحاجِّ، وذلك أنَّ باشا الحاج عبد الله العظم هو الذي رتَّبَهم بأمر من الدولة العثمانية, ومنها أنَّه حصن جُدَّة وأحاطها بالخندق ومنعَ الغرباء والسفار من جهةِ دولة الإمام سعود عن دخول جدَّة، واستوطنها الشريف أغلبَ أيامِه، وبقيت تلك العساكر عنده إلى وق"},{"id":4323,"era":"c13","t":"صدور فرمان من الدولة العثمانية بتثبيت محمد علي في ولايته على مصر .","s":"صدر فرمان من الدولة العثمانية بتثبيت محمَّد علي باشا حاكِمِ مِصرَ في ولايته على البلادِ، وذلك بعد أن أصرَّت الزعامةُ الشعبيةُ ومعها جموعُ المصريين على ذلك"},{"id":4324,"era":"c13","t":"احتلال الزعيم الصربي قرة يوركي مدينة بلجراد .","s":"قام الزعيمُ الصربي قرة يوركي باحتلالِ مدينة بلجراد، وقام فيها بذبحِ جميع المسلمين الموجودين في المدينة أثناء الثورةِ الصربية على الدولةِ العثمانية."},{"id":4325,"era":"c13","t":"الإمام سعود يحج الحجة الثالثة ومواجهته مع عبد الله باشا العظم .","s":"خرج الإمامُ سعود للحَجَّة الثالثة في ذي القعدةِ، وكان قد سيَّرَ قبل خروجِه للحج في نهاية رمضان عبد الوهاب أبا نقطة برعاياه من عسير وألمع وفهاد بن سالم بن شكبان بأهل بيشة ونواحيها، وعثمان المضايفي بأهل الطائف, وأهل اليمن وأهل تهامة والحجاز وحجيلان بن حمد بشوكة أهل القصيم, ومحمد بن عبد المحسن بأهل الجبل ومن تبعه من أهل شمر وشوكة أهل الوشم, وواعدهم الإمامُ سعود المدينةَ النبوية واجتمع معهم مسعود بن م"},{"id":4326,"era":"c13","t":"محمد علي باشا يضع نفسه تحت الحماية البريطانية  .","s":"في بداية حكم محمد علي لمصر دخل في مفاوضاتٍ مع الإنجليز استمرَّت أربعة أشهر أكَّدَ فيها جديَّتَه ورغبته المخلصة في الارتباطِ بهم، بل وطلب وضع نفسِه تحت حمايتهم، وهذا ما يؤكِّدُه تقرير القائد الإنجليزي فريزر قائد الحملة البريطانية على الإسكندرية، والذي تولى التفاوضَ مع محمد علي، الأمر الذي أدى- بعد اقتناعهم به- إلى تخلِّيهم عن أصدقائهم من المماليك. وقد تضمَّن التقرير الذي أعده فريزر ثم أرسلَه الى ال"},{"id":4327,"era":"c13","t":"وفاة السلطان العثماني سليم الثالث وتولية مصطفى الرابع .","s":"هو السلطانُ العثماني سليم الثالث بن مصطفى الثالث بن أحمد الثالث بن محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول بن بايزيد الثاني بن محمد الفاتح بن مراد الثاني بن محمد الأول بن بايزيد الأول بن مراد الأول بن أورخان بن عثمان بن أرطغرل، أحدُ خلفاء الدولة العثمانية. تولى السلطةَ بعد وفاة عمه عبد الحميد الأول سنة 1203هـ وكانت ال"},{"id":4328,"era":"c13","t":"البحرية البريطانية تدمر رأس الخيمة بالجزيرة العربية .","s":"شَهِدت سواحِلُ الخليج العربي عملياتِ مسحٍ بريطانيةً لِموانئ اللؤلؤ في جزر البحرين والتعرف على المنطقة، وازداد في الوقت نفسِه نشاطُ القواسم البحري- أتباع دعوة الشيخ المجدد محمد بن عبد الوهاب- في تتَبُّع السفن البريطانية في المحيط الهندي، حتى وصلوا  لمسافة لا تبعُدُ عن بومباي نفسها سوى ستين ميلًا، وكان من جراء  ذلك المخطط إرسالُ الحملة البريطانية التي أبحَرت من بومباي بقيادة الجنرال كير نحو رأس الخي"},{"id":4329,"era":"c13","t":"وفاة علي كيخيا باشا بغداد .","s":"هو علي كيخيا باشا بغداد كان وزيرًا لسليمان باشا الكبير والي بغداد سيره سنة 1213 على رأس حملة لغزو الأحساء والقطيف، لكِنَّ حملته على الرغم من قوته الهائلة إلَّا أنها باءت بالفشلِ، ولَمَّا قُتل سليمان باشا الكبير تولى بعده علي كيخيا ولاية بغداد، ولَمَّا استقر في الملك ودان له غالبُ رعايا العراق من الحضر والبادي، وثب عليه خمسة من غلمانِه وهو في الصلاة فقتلوه, فقام كيخيا سليمان فقتَلَهم, ولم يتِمَّ له"},{"id":4330,"era":"c13","t":"صدور أول تكليف لمحمد علي باشا من قبل السلطان العثماني .","s":"تمَّ تكليف محمد علي باشا من قِبَل السلطان العثماني مصطفى الرابع بمهمة القضاء على الدولة السعودية، وأرسل محمد علي باشا إلى السلطان يعتذِرُ عن هذه المهمة الصَّعبةِ بسَبَبِ الظروف الاقتصادية السيئة في مصر والناتجة عن انخفاض فيضان النيل واستيلاء المماليك على صعيدِ مِصرَ، والخشيةِ مِن أطماع الدول الأوروبية في مصرَ."},{"id":4331,"era":"c13","t":"غلاء وقحط في نجد .","s":"اشتَدَّ الغلاء والقحط في نجد وبلغ البُرُّ أربعةُ أصوع بريال والتمرُ إحدى عشرة وزنة بريال، وأمحلت الأرض وهلكت غالبُ مواشي الحضر، فلمَّا كان وقتُ انسلاخ رمضان في وسط الشتاء أنزل الله علي نجدٍ الغيث وأحيا البلادَ وكَثُرَ العشب وعَمَّ في الحضر والبادي إلَّا أن الغلاء على حاله واشتدادِه حتى حُصِد الزرعُ."},{"id":4332,"era":"c13","t":"الإنجليز يحاولون الاستيلاء على الإسكندرية بإرسال حملة القائد فريزر .","s":"كان لفشل الإنجليز في السيطرة على مضيق الدردنيل سنة 1220 أثرُه في جعل القائد الإنجليزي يعمل لمحوِ ما فشِلَ فيه، فأرسل حملةً بقيادة فريزر إلى الإسكندرية واحتلَّها في مطلع هذا العام، وأرسل فرقة إلى ثغر رشيد لكنها هُزِمَت وأعاد الكَرَّة بعد أشهر فكان مصيرُه كالمرة السابقة، وجاء محمد علي للدفاع عنها واضطرَّ الإنجليز للرحيل عن مصرَ بعد دخولهم بستة أشهر."},{"id":4333,"era":"c13","t":"ثورة قباقجي ضد إصلاحات سليم الثالث الداخلية .","s":"أقدم السلطان سليم الثالث على عَمَلِ إصلاحات داخلية من عام 1206, وأنشأ فرقةَ النظام الجديد الذي يُلغي دور الانكشارية الذين زاد شرُّهم في الفترة الأخيرة وتدَخُّلهم في كل شيء؛ مِمَّا أثار الجنود الانكشارية فقاموا بثورةٍ عُرِفت بثورة قباقجي وساندهم بعض الأعيان ضِدَّ النظام الجديد، وادَّعَوا أن الجيش  الجديد كافرٌ؛ لأنه يرتدي البنطلون لبس الأوربيين بدلًا من الشالوار اللباس التقليدي؛ مما اضطر السلطان إل"},{"id":4334,"era":"c13","t":"توقيع هدنة بين الروس والدولة العثمانية .","s":"وقَّعت روسيا هدنةً مع الدولة العثمانية بسَبَبِ حُروبها مع نابليون بونابرت، إلَّا أن الحرب بين روسيا والدولة العثمانية ما لَبِثَت أن تجدَّدت عام 1809م بعد عامين من توقيع الهدنة."},{"id":4335,"era":"c13","t":"توقيع معاهدة دمنهور بين محمد علي والي مصر والإنجليز .","s":"تم توقيع معاهدة دمنهور بين محمد علي والي مصر والإنجليز، وقد تمَّ بمقتضاها جلاءُ حملة فريزر عن مصر بعد فشلِها الذريع في تحقيقِ أغراضها وإصابتِها بهزيمةٍ فادحةٍ على يد المصريين."},{"id":4336,"era":"c13","t":"الإمام سعود يحج الحجة الرابعة .","s":"حجَّ الإمام سعود الحجَّةَ الرابعة بجميعِ نواحي رعاياه، حَجَّ معه أكثر من 100 ألف, ودخل مكَّةَ بجميع تلك الجموع واعتَمَروا وحَجُّوا بأحسن حال, وزار الشريفُ غالب الإمامَ سعودًا مرارا وصار معه كالشقيقِ فيزورُه أحيانًا وحده ومعه رجل أو رجلين، وأحيانًا بخيله ورجالِه, وكثيرًا ما يدخل سعود الحرم ويطوف بالبيتِ ويجلس فوقَ زمزم ومعه خواصُّه، وبَثَّ في مكة الصدقات والعطاء لأهلها وضعفائها شيئًا كثيرًا، وكسا ا"},{"id":4337,"era":"c13","t":"خلع السلطان العثماني مصطفى الرابع وتولية أخيه محمود الثاني .","s":"اختلف زعماء الحركة التي أطاحت بالخليفة سليم الثالث وطُولِبَ بإعادته إلَّا أنه كان قد قُتِل، ثم نودِيَ بعزل الخليفة مصطفى الرابع بن عبد الحميد فتمَّ ذلك وحُجز في المكان الذي كان قد حُجز فيه سليم الثالث، بعد أن أمضى أربعة عشر شهرًا في الحكم، ثم أُعدِم في هذا العامِ وأقيم بعده أخوه محمود الثاني."},{"id":4338,"era":"c13","t":"غلاء وقحط في نجد وغيرها .","s":"في هذه السَّنةِ كان الغلاءُ والقحطُ في نجدٍ على حالِه في الشدَّةِ، وانتهى سعرُ البُرِّ أربعة أصوع بريال، والتمر عشر وزنات بريال، وعَمَّ الغلاء جميعَ نواحي نجد واليمن والتهايم والحجاز والأحساء, ووقع مع ذلك مرضٌ ووباءٌ مات فيه خلقٌ كثير من نواحي نجد، ودخلت السنةُ التالية والأمرُ على حالِه من الغلاءِ والمرضِ، ومات فيها والسَّنةِ التي قبلها مئاتٌ من سوادِ النَّاسِ."},{"id":4339,"era":"c13","t":"قتال بين أنصار الدرعية في عمُان وابن الإمام رئيس سحار .","s":"بعث الإمامُ سعود سَريَّةً قليلة إلى عمان لتعَلِّمَ أهلها فرائض الدين والاطلاع على أحوالهم, فلما وصلوا هناك فغذا قيسُ بن أحمد المسمى ابن الإمام رئيس سحار وجميع باطنة عمان وابن أخيه سعيد بن سلطان رئيس مسقط ومعهم من الجنود نحو عشرة آلاف رجل سائرين على النواحي التي تليهم من رعية الإمام سعود، الذين كان يرأسُهم من جهة سعود سلطانُ بن صقر بن راشد صاحِبُ رأس الخيمة، فأرسل إلى من يليه من أهل عُمان، فاجتمع ع"},{"id":4340,"era":"c13","t":"الإمام سعود يرفض مهادنة الدولة العثمانية .","s":"عندما وصل سعودٌ بجيوشِه إلى مشارف الشام وقراها واكتسح ما أمامه من القرى والعربان، وقبل ذلك غزا كربلاء وهدد العراق وهزم جميعَ الجيوش التي أرسلها ولاةُ الشام والعراق لمحاربته، حتى اضطرت الدولةُ العثمانية أن تطلُبَ من سعود المهادنةَ والمسابلة وتَبذُل له مقابِلَ ذلك كلَّ سنة ثلاثين ألف مثقال ذهبي، وأوفدت الدولة لهذ الغرض رجلًا يسمَّى عبد العزيز القديمي وأوفدت بعده رجلًا آخر يسمى عبد العزيز بيك، فرجع ك"},{"id":4341,"era":"c13","t":"الإمام سعود يتجه إلى العراق وينازل أهل كربلاء .","s":"سار الإمام سعود بجيوشه من جميع نواحي نجد والأحساء والجنوب وأهل وادي الدواسر وأهل بيشة ورنية والطائف والحجاز والتهايم. خرج من الدرعية وتوجَّه ناحية العراق ونازل أهلَ كربلاء فوجدهم محصِّنين بلدَهم بسور عظيم وجنودٍ جمعوها بعد غزوتِه السابقة لهم سنة 1216، فأمر سعود بوضع السلالمِ على السور ووقع رميٌ وقتال شديدٌ، فلما علم سعود بحصانة البلد وعِظَمِ سورِها رحل عنهم."},{"id":4342,"era":"c13","t":"ثورة فرق الإنكشارية العثمانية على السلطان محمود الثاني .","s":"بعد تولِّي السلطان محمود الثاني مقاليدَ الحكم في البلاد رأى أن يبدأ بالإصلاحِ الحربي، فكلَّف الصدر الأعظم مصطفى البيرقدار بتنظيم الإنكشارية وإصلاحِ أحوالهم، وإجبارِهم على اتِّباع التنظيمات القديمة الموضوعة منذ عَهدِ السلطان سليمان القانوني، والتي كانت قد أُهمِلَت شيئًا فشيئًا، فقامت فِرَق الإنكشارية العثمانية بثورةٍ عنيفة ضدَّ السلطان."},{"id":4343,"era":"c13","t":"الإمام سعود بن عبد العزيز يحج الحجة الخامسة .","s":"حج الإمامُ سعود بن عبد العزيز الحَجَّة الخامِسةَ برعاياه من جميعِ النواحي ودخل مكَّةَ واعتمر وحَجَّ ونصل قصر الشمالي المعروف في البياضة وأقام فيه, والشريف غالب يزورُه كُلَّ وقتٍ وهو لسعود بمنزلةِ أحدِ نوَّابه وأمرائه الذين في نجدٍ بالسَّمعِ والطاعة, وفشا الأمرُ بالمعروف والنهيُ عن المنكر في مكةَ، فلا يُشرَبُ التنباك في الأسواق، وأمر سعود أن يُجعَلَ في أسواقها مَن يأمرُ بالصلاةِ إذا دخل وقتُها, وبذ"},{"id":4344,"era":"c13","t":"وباء ومرض شديد في الدرعية .","s":"اشتدَّ الوباءُ والمرض خصوصًا في الدرعية، فمكث ذلك إلى شهر جمادى ومات في الدرعية خلقٌ كثير من الغرباء والسكَّان حتى أتي عليهم أيامٌ يموت في اليوم الواحد ثلاثون وأربعون نفسًا، وكتب سعود نصيحةً بليغة لأهلِ الدرعية وأرسَلَها إلى جميع النواحي حَذَّرهم فيها من المحظورات وحثَّهم على التوبة، ودعا الله في آخِرِها دعاءً عظيمًا أن يرفَعَ الضرَّ والوباءَ عن الناسِ، وقرئ على الناسِ في مساجِدِ الدرعيةِ."},{"id":4345,"era":"c13","t":"الإمام سعود يبين لوالي الشام سبب منع حجاج الشام عن مكة .","s":"عندما منع الإمام سعود حاجَّ الشام من دخول مكَّةَ لأداء الحجِّ، أرسل والي الشام إلى الإمام سعود يستنكِرُ منع حجاج الشام من دخول مكة، فأرسل له الإمام سعود رسالةً مطولة بيَّن فيها سبَبَ مَنعِهم من دخول مكةَ، وممَّا ورد في هذه الرسالة: \"السلام التام والتحية والإكرام يُهدى إلى سيِّد الأنام محمد عليه أفضل الصلاة والسلام, ثم ينتهي إلى جناب الأحشم المكرَّم سلمه الله من الآفات واستعمله بالباقيات الصالحات، "},{"id":4346,"era":"c13","t":"الإمامُ سعود بن عبد العزيز يرسل عبدَ الله بن مزروع يغزو عمان .","s":"أرسل الإمامُ سعود بن عبد العزيز إلى عمان عبدَ الله بن مزروع صاحِبَمنفوحة وعِدَّةَ رجال من أهل نجد، وأمرهم بنزولِ قصر البريمي المعروف في عمان وإحصانه، ثمَّ إن سعودًا بعث بعده إلى عُمان مطلق المطيري بجيش من أهل نجد، وأمرَ أهل عمان بالاجتماع عليه والقتال معه، فاجتمع عليه مقاتِلةُ أهل عمان مع ما معه من أهل نجد، فقاتل أهل الباطنة سحار ونواحيها ومن تبعهم، ورئيسُهم يومئذ عزان بن قيس، وقاتلوا سعيدَ بن سلط"},{"id":4347,"era":"c13","t":"مراكب الإنجليز تستبيح رأس الخيمة وتحرقها .","s":"أقبَلَت مراكِبُ الإنجليز الذين استنجد بهم سعيدُ بن سلطان صاحِبُ مسقط في عمان بعد أن نقَضَ عهده مع الدرعية، وقصَدَت مراكبهم أهلَ بلد رأس الخيمة في عمان ورئيسُها يومئذ سلطانُ بن صقر بن راشد بن مطر أميرُ القواسم، وحاربوهم فلم يحصُلوا على طائل, فرفعوا على البلد بلورًا وجعلوه في عين الشمس وقابلوا به البلدَ، فاشتعلت النار فيها وكان أكثر بيوتهم عسبان النخل فدخلوا البلدَ واستباحوها ونهبوا ما فيها وأشعلوا "},{"id":4348,"era":"c13","t":"الإمام سعود يرسل جيشًا إلى آل خليفة أهل البحرين .","s":"عندما تحقَّق للإمام سعود أنَّ آل خليفة أهل البحرين والزبارة يقع منهم بعض المخالفات, فخاف أن يقع أكبَرُ من ذلك, فأرسل إليهم جيشًا واستعمل عليه الأميرَ محمد بن معيقل, ثم أتبعه بعبد الله بن عفيصان واجتمعوا ونزلوا عند الزبارة المعروفة عند البحرين، فأقاموا فيها قريبَ أربعة أشهر حتى رجع الإمام سعود من الحجِّ، فأرسل أمراءَ جيشه إلى آل خليفة يأمرونهم أن يَفِدوا على سعود فساقوهم كرهًا، فقَدِموا عليه في الد"},{"id":4349,"era":"c13","t":"وفاة الشيخ حسين ابن شيخ الإسلام محمد بن عبد الوهاب .","s":"هو العلَّامةُ الشيخ القاضي حسين ابن شيخ الإسلام محمد بن عبد الوهاب، ولد بمدينة الدرعية ونشأ بها وقرأ العلمَ على والده الشيخ محمد بن عبد الوهاب. وكان كفيفَ البصر نيِّرَ البصيرة جَهْوريَّ الصوت بحيث يسمَعُ تكبيرَه في الصلاة أدنى المسجد وأقصاه مع كثرةِ الخلائق، وكان له معرفةٌ في الأصل (التوحيد) والفروع والتفسير, وله مجالسُ عديدة في تدريس الفقه والتفسير وغيرهما, وقد تولَّى إمامة مسجد البجيري في منازل "},{"id":4350,"era":"c13","t":"وفاة الأمير عبد الوهاب أبو نقطة أمير عسير ورجال ألمع .","s":"هو الأمير عبد الوهاب بن عامر المتحمي المشهور بـ (أبو نقطة) من بلدة طبب بعسير السراة، وعبد الوهاب من قبيلة ربيعة رفيدة، قَدِم عبد الوهاب مع أخيه محمد بن عامر على إمام الدرعية عبد العزيز بن محمد بن سعود في سنة 1215هـ فعاهداه على دينِ الله ومناصرة الدعوة السلفيَّة والجهاد في سبيل نشرِها، فقبل منهما وأرسل معهما سرية لإخضاع القبائل بقيادة ربيع بن زيد المخارم أمير ناحية الدواسر، فسارا من الدرعية برفقة ه"},{"id":4351,"era":"c13","t":"نفي محمد علي باشا نقيبَ الأشراف إلى دمياط .","s":"نفى محمد علي باشا حاكِمُ مِصرَ عُمَر مكرم نقيب الأشراف إلى دمياط على الرغم أنَّ مَكرم كان له دورٌ في تولية محمد علي شؤون البلاد، عندما قاد هو وعددٌ من مشائخ الأزهر ثورةً لخلع خورشيد بيك باشا سنة 1805م تولى بعدها محمد علي حكم مصر، وحينما استقَرَّت الأمور لمحمد علي خاف من نفوذ المشائخ،  فنفى عمر مكرم إلى دمياط سنة 1809م, وأقام بها أربعةَ أعوام، ثم نقله إلى طنطا توفي فيها 1822م، وبذلك يكون محمد علي ب"},{"id":4352,"era":"c13","t":"سيول تعم أرجاء الوديان والشعاب في نجد ونواحيها .","s":"نزل مطرٌ شديدٌ مصحوب برعد وبرق سال به شعاب بلدان كثيرة من نجد، وامتلأت الوديانُ حتى خشيَ الناس على محالِّهم ومنازلهم منه, وكان هذا السيل وقع مستهلَّ جمادى الآخرة في جمرة القيظ وقتَ حلول الشمس برج السرطان، وهذا لم يُعهَدْ بنزوله في مثل هذا الناحية منذ أزمانٍ."},{"id":4353,"era":"c13","t":"الإمام سعود يسير جيوشه إلى بندر عريش باليمن .","s":"كان حمُّود بن محمد أبو مسمار صاحب أبو عريش  قد بايع الإمامَ سعودًا على دين الله ورسوله والسمع والطاعة، ثم ظهر منه ما يريبُ من مخالفة المسلمين ومعاداتِهم، وحدثت عداوةٌ بينه وبين عبد الوهاب أبو نقطة ومنابذة, فكتب الإمامُ سعود إلى حمود بن محمد أبو مسمار يأمرُه أن يحارب أهلَ صنعاء ويسَيِّرَ إليهم جنوده، فلم يفعَلْ، فأمر سعود أهلَ النواحي الحجازية واليمنية ومن يليهم بالمسيرِ لقتاله, وبعث من الدرعيةِ فر"},{"id":4354,"era":"c13","t":"انتصار الدولة العثمانية على روسيا في معركة تاتاريجه .","s":"حقَّقت الدولة العثمانية انتصارًا في معركة \"تاتاريجه\"، على الجيش الروسي البالغ 60 ألف شخص، قُتل فيها من الروس 10 آلاف جندي."},{"id":4355,"era":"c13","t":"الإمام سعود يحج الحجة السادسة .","s":"الإمامُ سعود يحُجَّ الحَجَّةَ السادسة وحَجَّ معه جمعٌ ممن شملتهم دولتُه مِن أهل العارض والجنوب ووادي الدواسر والأحساء ونواحيه وعمان وأهل نجد وأهل التهايم والحجاز واليمن والمدينة النبوية، ومعهم النساء والأطفال والثقيل والخفيف، وبنات الإمام سعود، وكثير من نساء آل مقرن، ودخلوا مكة واعتمروا وحَجُّوا بأمانٍ عظيم لا يُحمَل فيه سلاحٌ، ونزل سعود القصر الشمالي من البياضية، وأهدى عليه الشريفُ غالب هدايا سَن"},{"id":4356,"era":"c13","t":"مساعدات الدولة الفارسية للبحرين ومسقط لمواجهة آل سعود .","s":"لَمَّا تمكَّنَت قوات الدولة السعودية من دخولِ البحرين والزبارة قصدَ أبناء آل خليفة صاحِبَ مسقط سعيد بن سلطان فاستنصروه وأرسلوا إلى العجم الفُرس واستصرخوهم, وكانت مراكِبُ الإنجليز عند سعيد في مسقط، فاستعانوا بهم فأقبلوا بجموعٍ عظيمة في مراكِبَ كثيرة، وبندروا عند الزبارة بالليل، فأظهر آلُ خليفة منها بقيَّة رجالهم وما فيها من المتاع والمال ودمَّروها جملة, ثم ساروا إلى البحرين ونازلوا فهد بن عفيصان وا"},{"id":4357,"era":"c13","t":"الإمام سعود يغزو المزيريب .","s":"غزا الإمام سعود غزوة المزيريب وآل خليفة في الاعتقال، فلما رجع طلب منه آلُ خليفة أن يفكَّ أسرَهم ووعدوه السَّمعَ والطاعة ويَنزلوا الزبارة، وأن يجتمعوا فيها ببنيهم وأقربائهم، فإن أراد بنوهم الامتناعَ فإنهم يرجعون إلى الدرعية، وبايعوا سعودًا على ذلك, وأعطوه عهدًا وميثاقًا، فارتحلوا من الدرعية وبعث معهم سعودٌ شوكة من الجيش، فلما وصلوا إلى ناحيتهم طلبوا منهم الموافقةَ على ما بايعوا عليه سعود، فأبوا علي"},{"id":4358,"era":"c13","t":"رخص الأسعار في نجد والحرمين .","s":"رخصت الأسعار وبلغ البُرُّ ثلاثة عشر صاعًا بريال، والتمر سبع وثلاثون وزنة بريال، ورخصت أسعار الحرمين، وبِيعَ الأردب بأربعة ريالات."},{"id":4359,"era":"c13","t":"عزل يوسف باشا والي الشام .","s":"بعد أن قفل الإمامُ سعود من الشام, جاء العزل ليوسف باشا والي الشام, وسار إليه سلمانُ صاحب عكا، فأجلاه واحتوى على جميعِ أمواله، وتولى إمارةَ الشام."},{"id":4360,"era":"c13","t":"وفاة سليمان باشا والي بغداد .","s":"هو سليمان باشا والي بغداد، وهو غير سليمان باشا الكبير. سار عبد الرحمن باشا الكردي إلى بغداد، فنازل أهلها ودخلها وقتل سليمان باشا، وسَبَبُ ذلك أن السلطان محمود بن عبد الحميد بعث رجلًا يقال له آغا بكر إلى سليمان يطلب منه خراجَ العراق من مدة سنين لم يأتِه منه شيء، فقام الأغا بكر عنده في بغداد، فلم يحصُلْ له شيء، ثم إن سليمان أعطاه رشوةً وأذن له في الخروجِ من بغداد، فخرج فاستصرخ الأكراد وبادية العراق "},{"id":4361,"era":"c13","t":"غزو الإمام سعود الشام .","s":"سار الإمامُ سعود بجيوشِه التي استنفرها من جميعِ النواحي الحاضر والبادي من وادي الدواسر إلى مكة والمدينة، إلى جبلِ طيٍّ والجوف وما بين ذلك الدرعية، وقصد نقرة الشام المعروفة؛ لأنه بلغه الخبَرُ أنَّ بوادي الشام وعربانه من عنزة وبني صخر وغيرهم فيها, فلما وصل تلك الناحية لم يجِدْ فيها أحدًا منهم؛ إذ سبقه النذيرُ إليهم فاجتمعوا على دوخي بن سمير رئيس ولد علي من عنزة، وهو من وراء الجبَلِ المعروف بطويل الث"},{"id":4362,"era":"c13","t":"الإمام سعود يحج الحجة السابعة .","s":"حجَّ الإمامُ سعود الحَجَّةَ السابعة واحتفل معه بالحَجِّ جميعُ رعيته من الجبل والجوف إلى الأحساء ووادي الدواسر ونواحيه وعمان وجميع أهل الحجاز وعسير وألمع وجميع طور تهامة ومن يليهم, فدخلوا مكةَ واعتمروا وحجُّوا بأمان عظيم، ونزل سعود القصر الشمالي من البياضية وبذل في مكة من الصدقات والعطاء شيئًا كثيرًا, وخطب سعود يوم عرفة. قال ابن بشر: \"حججت تلك السنة وشهِدتُ سعودًا وهو راكب مطيَّتَه مُحرِمًا بالحج و"},{"id":4363,"era":"c13","t":"خروج أبناء الإمام سعود لعمان دون موافقة والدهم .","s":"بينما كان الإمامُ سعود في الحَجِّ خرج من الدرعية أبناؤه تركي وأخواه ناصر وسعد وقصدوا ناحية عمان ومعهم عدة رجال من أتباعهم وخَدَمِهم، وذلك أنه وقع بينهم وبين أبيهم مغاضبة عندما طلبوا منه زيادةً في عطائهم وخَراجِهم، فأبى عليهم ذلك وطلبوا الخروجَ إلى عمان للقتالِ فمنعهم منه، فلما وصلوا عمان عَلِم بهم أناس من أهل باطنة عمان وغيرهم فنفروا عليهم وهجدوهم بالليلِ بياتًا فحصل بينهم قتالٌ شديدٌ قُتِلَ من ال"},{"id":4364,"era":"c13","t":"وفاة الشيخ العلامة حمد بن ناصر بن معمر .","s":"هو العلَّامةُ المحَقِّقُ الشيخ حمد بن ناصر بن عثمان بن معمر النجدي التميمي من آل معمر أهل العُيَينة، نزح منها واستوطن مدينة الدرعية، وقرأ فيها على الشيخ محمد بن عبد الوهاب وأخيه الشيخ سليمان بن عبد الوهاب، وأخذ العربية عن الشيخ حسين بن غنام، وبعد ذلك جلس للتدريس بمدينة الدرعية، فأخذ عنه العلمَ خَلقٌ كثير من أهل الدرعية وغيرهم، منهم العلامة سليمان ابن الشيخ عبد الله بن محمد بن عبد الوهاب, وعبد الرح"},{"id":4365,"era":"c13","t":"وفاة الشيخ العلامة حسين بن غنام صاحب تاريخ ابن غنام .","s":"هو الشيخ العلامة أبو بكر حسين بن أبي بكر بن غنام الأحسائي المالكي مذهبًا التميمي نسبًا، ولد ببلدة المبرز بالأحساء ونشأ بها وقرأ على علمائها، ثم نزح منها إلى الدرعية، فقدمها على الإمام عبد العزيز بن محمد والشيخ محمد بن عبد الوهاب فأكرماه وأنزلاه المنزلة الرفيعة، فاستقرَّ في الدرعية وجلس فيها لطلاب العلم يقرؤون عليه علم النحو والعروض فقط، منهم الشيخ العلامة سليمان بن عبد الله ابن الشيخ المجدد محمد ب"},{"id":4366,"era":"c13","t":"تكليف محمد علي بقتال الدولة السعودية من قبل الدولة العثمانية .","s":"لما بدأ الإصلاح ودعوة التوحيد الصحيح ينتشران في أرض نجد والحجاز حتى دخل الحرمان تحت حكم الدولة السعودية- كان بدهيًّا أن يوجد معارِضون لهذه الدعوة والدولة على اختلاف مشاربِهم وأهدافهم، وكان من بين هؤلاء الدولةُ العثمانية الني انزعَجَت مِن امتداد سلطان دولة آل سعود إلى الحجاز وأطراف العراق والشام، وكذلك واليها في مصر محمد علي باشا الذي له أطماع وطموحات شخصية، وبعض الدول الأوربية التي أزعجها وصولُ هذ"},{"id":4367,"era":"c13","t":"عقد معاهدة تحالف بين مسقط وفارس .","s":"لوحظ أن الخلافَ القائِمَ بين السعوديين ودولة العجم استغَلَّه حُكَّام مسقط وغيرهم في مناطق الخليج العربي، في إقامة نوعٍ مِن الوفاق بينهم وبين دولة الفرس، وقد عبَّرَت البعثة الدبلوماسية التي أرسلها سعيد بن سلطان برئاسة سالم إلى بلاط الشاه في هذه السنة عن هذا الوِفاق؛ إذ كان هدفُها إقامةَ معاهدة تحالف بين مسقط وبين فارس, وقد نجحت هذه البَعثةُ في تحقيق هدفِها, وكان من ثمارِ ذلك أن ساعَدَت فارسُ حكومةَ"},{"id":4368,"era":"c13","t":"قتال بين مطلق المطيري أمير جيوش الدولة السعودية في عمان وصاحب مسقط .","s":"جمع صاحبُ مسقط سعيد بن سلطان جموعًا وعسكرh كثيرا, واستنصر بالعجم فأتاه منهم نحو 3000 مقاتل، وساروا إلى عمان, وعاثوا فيما يليهم من رعايا وأتباع الدرعية، واستولوا على بلاد الجبري سمايل، وهرب الجبري منها, فسار مطلق المطيري بشوكةِ المجاهدين الذين معه في عمان من أهل عمان ونجد وغيرهم، فجمع اللهُ بينهم وبين عساكر صاحب مسقط وتنازلوا واقتتلوا قتالًا شديدًا، فانهزمت جنود صاحب مسقط, وركب المجاهدون أكتافَهم و"},{"id":4369,"era":"c13","t":"موقعة خكيكرة بين الكويت والبحرين من جانب وحاكم الدمام من جانب آخر .","s":"خاضت الكويت معركةَ خكيكرة مع البحرين بقيادة عبد الله بن أحمد آل خليفة وجابر بن عبد الله الصباح ضِدَّ حاكم ساحل الدمام رحمة بن جابر الجلهمي، الذي دعمه الإمامُ سعود بن عبد العزيز بن محمد حاكمُ نجد، وانتهت المعركة بانتصار البحرين والكويت, وكان من أسباب المعركة أنَّ الإمامَ سعودًا كتب إلى رحمة بن جابر الجلهمي في قطر يأمرُه فيها بالاستعداد لغزو البحرين، وكان محاربًا لآل خليفة حكام البحرين، فأرسل إليه ا"},{"id":4370,"era":"c13","t":"مذبحة المماليك في مصر (مذبحة القلعة) .","s":"عندما وصل محمد علي باشا لسُدَّة الحكم في مصر، أخذ في التخلُّص من كل القوى المنافِسة له، حتى تلك التي وقَفَت بجانبه وساعدته في الحصول على هذا المنصِبِ الخطير، مثل العلماء ومشايخ الأزهر، والحامية الألبانية الذي هو واحِدٌ من أفرادها، ولكِنْ كان أقوى خصومِ محمد علي وأشدهم تهديدًا له هم المماليك، ولقد حاول محمد علي التخلصَ منهم عدة مرات، ولكنه فَشِل لكثرتِهم وتخوُّفِهم منه واتِّباعهم لأسلوب الكرِّ والف"},{"id":4371,"era":"c13","t":"معركة بحرية بين السعوديين وأهل البحرين .","s":"لما رجع سعود من الحج أطلق آلَ خليفة أهل البحرين والزبارة، وأذِنَ لهم بالرجوع إلى بلدهم، ووعدوه بالسمع والطاعة وعدم المخالفة، ووافق وقتُ وصولهم البحرين وقوعَ مقاتلة عظيمة في البحر بين عشايرهم وأبنائهم وبين أتباع الدولة السعوديةِ الذين في ناحيتِهم، وهم رحمة بن جابر بن عذبي أمير خوير حسان المعروف، وأبا حسين أمير الحويلة البلد المعروفة في قطر، وإبراهيم بن عفيصان أمير شوكة المرابِطة من أهل نجد وغيرهم، "},{"id":4372,"era":"c13","t":"اضطراب الأوضاع في عُمان ونقضهم العهد .","s":"لَمَّا خرج أبناء سعود ومُطلق المطيري ومعه رؤساء المسلمين وأتباعهم من عمان وقع بعضُ الخلل, ونقَضَ العهد أكثر بنو إياس، فكتب سعود لعبد العزيز بن غردقة صاحب الأحساء أن يسيرَ بجيشٍ يكون هو أميرَه، فلما وصل ابن غردقة عمان وقع بينه وبين بني إياس وغيرهم من عمان وقعة هُزم فيها الغردقة و200 من أهل الأحساء وعمان وغيرهم."},{"id":4373,"era":"c13","t":"الحملة المصرية الأولى على الحجاز بقيادة أحمد طوسون باشا .","s":"انطلقت حملةُ أحمد طوسون بن محمد علي من مصرَ، ونزل طوسون على الساحِلِ الغربيِّ بجيشٍ قِوامه عشرة آلاف جندي, حرص طوسون أن يُغدِقَ الأموال والهدايا والخِلَع على شيوخ القبائل ورؤساء الجماعات التي تقطُن الموانئ الحجازية ولها نفوذ فيها؛ لتكون سندًا لقواتِه، ولتقبَلَ تأجير إبلها إلى قواته من أجل حَمل المُؤَن والعتاد من المناطق الساحلية إلى داخل البلاد، واستولى على ينبُع بدون مقاومة تذكر, ثم استدرج عبد ال"},{"id":4374,"era":"c13","t":"دخول الإسلام أستراليا .","s":"بدايةُ دخول الإسلام في أستراليا تعود إلى بدايات القرن الماضي عندما قام الإنجليز أثناءَ احتلالهم لأفغانستان بجلب الذَّهَبِ إلى أستراليا؛ نظرًا للارتباط الإنجليزي بهذه القارة الحديثة. ولكِنَّهم فكَّروا في أن أستراليا نفسها يمكن أن تكونَ موطنًا للذهب، فاستقدموا عمالًا مسلمين من أفغانستان للعمل في المناجم الأسترالية، وأخذ هؤلاء الأفغان ينشرون الدين الإسلامي، وقاموا ببناء أول مسجد في غرب بيرث، وكان ذلك"},{"id":4375,"era":"c13","t":"استقلال صربيا عن الدولة العثمانية بموجب معاهدة بوخارست .","s":"حاول العثمانيون عقدَ اتفاقٍ مع روسيا مماثلٍ لِما جرى بين إنكلترا وروسيا، ولكنَّه فَشِل واشتعلت نارُ الحرب بينهما، وهُزم العثمانيون واستولى الروسُ على بعض المواقع، وعُزِل الصدر الأعظم ضياء يوسف باشا وتولى مكانه أحمد باشا الذي انتصر على الروس، وأجلاهم عن المواقِعِ التي دخلوها، وساءت العلاقة بين فرنسا وروسيا، وكادت تقعُ الحرب بينهما، فطلبت روسيا الصلحَ مع الدولة العثمانية، وعقدت بين الطرفين مُعاهدة ب"},{"id":4376,"era":"c13","t":"وفاة الشيخ عبد الله الشرقاوي شيخ الأزهر .","s":"هو الشيخُ عبد الله بن حجازي بن إبراهيم الشرقاوي أحدُ مشائخ الأزهر. ولِدَ بقرية الطويلة من قرى الشرقية بمصر سنة 1150هـ, وتعلَّم في الأزهر وتولى مشيختَه سنة 1208هـ, وفي عهده قام الأزهرُ بقيادة الحركة الوطنية ضِدَّ الحملة الفرنسية، وكانت له مواقِفُ شجاعة أثناء المعارك مع الفرنسيين، وتزَعَّم الشرقاويُّ قيادة ثورة القاهرة الأولى, ومن مؤلَّفاتِه التحفة البهية في طبقات الشافعية, وتحفة الناظرين في من ولِي"},{"id":4377,"era":"c13","t":"الحملة المصرية الثانية بقيادة محمد علي باشا .","s":"بعد أن هُزم طوسون في وقعة وادي الصفراء بين المدينة والقصيم سنة1227 طلب المساعدةَ من والده، فجهَّز جيشَه وأخذ معه الأموال للمساعدة. قرر محمد علي باشا أن يسير بنفسِه إلى الحجاز لمتابعة القتال وبسْطِ نفوذه في شبه الجزيرة العربية، فغادر مصر على رأس جيش آخَرَ، ونزل في جدة، ثم غادرها إلى مكة وهاجم معاقِلَ السعوديين إلَّا أنه فَشِلَ في توسيع رقعة انتشاره، فأخلى القنفذةَ بعد أن كان قد دخَلَها، وانهزم ابنه"},{"id":4378,"era":"c13","t":"وفاة الأمير عثمان بن عبد الرحمن المضايفي .","s":"هو الأمير عثمان بن عبد الرحمن العدواني من قبيلة عدوان، كان من أمراء الشريف غالب أمير مكة ووزيره في الشؤون الخاصة، وكان على درجة عالية من الكفاءة أقنعت الشريفَ غالبًا أن يتَّخِذَه وزيرًا له وأن يكونَ صفيَّه وحميمَه، وقد تزوج المضايفي بأختِ الشريف غالب بن مساعد ثم تحوَّل إلى تأييد دعوة التوحيد بعد أن رأس وفدًا من قبل الشَّريفِ غالب للتفاوضِ مع حكَّام الدرعية، فلما عاد من الدرعية أخذ يدعو بالإمارة لن"},{"id":4379,"era":"c13","t":"دخول قوات أحمد طوسون إلى مرفأ جدة .","s":"وجد أحمد طوسون باشا الطريقَ مفتوحًا أمامه للتوغُّلِ في الحجاز، وظهرت حاجةُ قواته إلى مرفأ جدة؛ ليكون مركزا لتموين الجيشِ في زحفِه نحو مكة، فأرسل طوسون باشا إلى شَريفِ مكَّةَ الشَّريفِ غالب؛ ليسمح له بالدخولِ إلى مرفأ جدة، فسَمَح له وأَخَذت قوات طوسون طريقَها في الزَّحفِ نحو مكة."},{"id":4380,"era":"c13","t":"وقوع وباء وحمى في بلدان سدير ومنيخ .","s":"وقع في بلدان سدير ومنيخ وباء وحمى مات فيه خلق كثير، وأكثر من مات من بلد جلاجل؛ حيث مات منهم أكثر من 600 نفس بين كبير وصغير، ولم يزل الوباءُ من مبتدأ هذه السنة إلى آخِرِها."},{"id":4381,"era":"c13","t":"عبد الله بن سعود يوجه أخاه فيصل لقيادة عساكر الدولة في الحجاز .","s":"كان عبدُ الله بنُ سعود بعد عودتِه من غزوِ الحجاز أقام في القصيمِ خمسة أشهر، وأرسل أثناءَ إقامتِه هناك أخاه فيصلًا إلى تربة؛ ليتولى قيادةَ جموعِ المسلمين التي من تهامة والحجاز وغيرهم ومَن معه من أهلِ نجدٍ."},{"id":4382,"era":"c13","t":"وفاة الأمير إبراهيم بن سليمان بن عفيصان أمير الأحساء .","s":"هو الأميرُ إبراهيم بن سليمان بن عفيصان أميرُ الأحساء، ومِن أبرزِ قادةِ وأمراء الدولة السعودية الأولى حقَّق عددًا من الانتصاراتِ في معاركَ مع خصومِ الدَّولةِ خاصَّةً في مناطِقِ شرقيَّ الجزيرة العربية, وقد تولَّى ابن عفيصان إمرةَ عددٍ مِن البلدان التي خضعت لحُكمِ الدولة السعودية؛ فقد تولى إمارةَ الأحساء في عهد الإمامِ عبد العزيز بن محمد بعد أن تمكَّن من فتحِها سنة  1210هـ/ 1795م، ثم أصبح إبراهيم أمي"},{"id":4383,"era":"c13","t":"وفاة الشيخ عبد الله الأول بن  صباح أمير الكويت .","s":"هو الشيخُ عبد الله الأول بن صباح  بن جابر بن سليمان بن أحمد تولى حكم الكويت بعد أن توفِّي والده سنة 1190هـ وقد بقي في حكم الكويت 39 سنة, وبعد وفاته تولى حكمَ الكويت ابنُه جابر الأول، الذي كان في البحرين وقتَ وفاة والده، فتسلم الحكم في الكويت الشيخُ محمد السلمان جد المالك الصباح بعد مبايعةِ الكويتيين له إلى حينِ عَودةِ الشيخِ جابرٍ مِن البحرين."},{"id":4384,"era":"c13","t":"محمد علي يوجه عساكره لليمن فتهزمهم القوات السعودية في القنفذة .","s":"بعث محمد على صاحب مصر عسكرًا كثيفًا ووجَّهه إلى ناحية اليمن، لَمَّا استقر بمكة وجدة، فأرسل تلك العساكر برًّا وبحرًا، فسَيَّرَ في البحر أكثَرَ من أربعين سفينة وبندروا عند القنفذة, وكان في القنفذة عسكر من عسير نحو 500 مقاتل، فحصرهم الروم (جيش محمد علي) ورموهم بالمدافِعِ والقنابر، فلم يزالوا محاصرين لهم حتى أخرجوهم بالأمان واستولوا على القنفذة، وكان أميرُ عسير وتهامة طامي بن شعيب قد سار بجميع الشوكة "},{"id":4385,"era":"c13","t":"وفاة الإمام سعود الكبير بن عبد العزيز بن محمد وتولي ابنه عبد الله .","s":"هو الإمامُ قائِدُ الجنودِ سعود الكبير بن عبد العزيز بن محمد بن سعود ثالثُ حُكَّام الدولة السعودية الأولى، ولد بالدرعية سنة 1165هـ وتولى الحكمَ بعد وفاة والده سنة 1218هـ يعتبر عصر سعودٍ قِمَّةَ ازدهار الحكم السعودي في الدولة السعودية الأولى؛ فقد استطاع إخضاعَ الحجاز وعمان، وبلغ حوران من الشام. يصِفُ ابن بشر الإمامَ سعودًا وعهده بقوله: \"أَمِنَت البلاد وطابت قلوب العباد, وانتظمت مصالحُ المسلمين بحُسن"},{"id":4386,"era":"c13","t":"كسوف الشمس  .","s":"كسفت الشمسُ وقتَ الضحى كسوفًا لم يُعهَدْ مِثلُه، وانطمست بالكليةِ وأظلمت الأرضُ وطَلَعت النجومُ."},{"id":4387,"era":"c13","t":"الجيوش الحجازية والتهامية السعودية تهزم قوات محمد علي بوادي زهران .","s":"سار طامي بن شعيب برعاياه من عسير وألمع وغيرهم في نحو 20 ألف مقاتل، وكان الروم (قوات محمد علي) قد ساروا من مكَّةَ والطائف بعساكِرَ كثيرة نحو 20 ألفًا من الأتراك والمغاربة، فحاصروا بخروش وغلاس في أودية وادي زهران, وحصلت موقعةٌ بين الروم وقوات طامي بن شعيب قربَ حِصنِ بخروش، فاقتتلوا قتالًا شديدًا حتى انهزم الرومُ هزيمةً شنيعة، فغنم طامي خيامَهم ومحطتَهم وزهبتَهم وأزوادهم وبغالهم، وقُتِل من الرومِ مقت"},{"id":4388,"era":"c13","t":"حجُّ حاجِّ الشام ومصر .","s":"حجَّ هذا العامَ حاجُّ الشام ومصر، ولَمَّا انصرفوا من الحَجِّ أبقوا مع محمد علي في مكَّةَ رحايل وذخائر وأموالًا أتوا بها إليه من جهةِ الروم (الترك)"},{"id":4389,"era":"c13","t":"عودة محمد علي إلى مصر .","s":"بعد أن حقَّق محمد علي باشا عدةَ انتصارات في الحملةِ التي قادها بنفسِه لدعم جهودِ ابنِه طوسون في العمَلِ على إسقاط الدولة السعودية، اضطر أن يغادِرَ إلى مصر للقضاء على حركة تمرد استهدفت حكمه، فعيَّن حسين باشا الأرنؤطي واليًا على مكة، وأقام ابنَه أحمد طوسون قائدًا على القوات العسكرية في الحجاز, وبعد قضاء محمد علي على حركةِ التمَرُّدِ في مصر استأنف حربَه ضِدَّ السعوديين، فأرسل إليهم حملةً عسكرية أخرى "},{"id":4390,"era":"c13","t":"وفاة الأمير طامي بن شعيب المتحمي أمير عسير وألمع .","s":"هو الأميرُ طامي بن شعيب المتحمي، أحدُ أشهر أمراء عسير في الدولة السعودية الأولى، تولَّى إمارة الإقليم بعد وفاة ابنِ عمه عبد الوهاب بن عامر «أبو نقطة» المتحمي سنة 1224هـ. كان طامي ذا بِنيةٍ صحيحة وقوية، قصيرًا في بنائه ذا لحية طويلة بيضاء مهيبة، عيناه تقذفان شررًا، يمتاز بروحٍ سَمحة، ومهذَّب تجاه رئيس الأتراك؛ ولذا كان محمد علي بعد اعتقالِه غالبًا ما يتحدَّثُ معه معجبًا به. أبدى طامي نشاطًا كبيرًا "},{"id":4391,"era":"c13","t":"معركة بسل بين قوات محمد علي باشا والقوات السعودية  .","s":"جرت معركةٌ حاميةُ الوطيس في بلدةِ بسل الواقعة بين الطائفِ وتربة بين قواتِ محمد علي باشا والقوات السعودية بقيادة فيصل بن سعود, وذلك أنَّ فيصلَ بن سعود لَمَّا قدم إلى الحجاز ليتولى قيادةَ جموع المسلمين نزل تربة واستنفر رعايا دولتِهم في الحجازِ، فقَدِمَ طامي بن شعيب في أهل عسير وألمع وزهران وغامد في عشرين ألفًا، فلما أقبلوا على تربة وأرسلوا إلى فيصل يخبرونه بقدومِهم خرج فيصل من تربة ومعه عشرةُ آلاف م"},{"id":4392,"era":"c13","t":"محمد علي يسير بعساكره إلى عسير وألمع ورفيدة .","s":"سار محمد علي بعساكِرِه إلى بلد طامي عسير وألمع ورفيدة وغيرهم فأطاعت لهم رفيدة، وثبت طامي بن شعيب ومن معه من عسير وألمع وبني أحمر والأسمر، واستعَدُّوا لقتال محمد علي ومحاربته, ورتَّب طامي جموعَه ورعاياه، فجعل مع حوان عسكرًا عند الطلحة- وهي عدَّةُ قرى في بلاد ربيعة رفيدة- فزحف محمد علي على الطلحة فقاتله حوان وهزمه ثم تراجع الروم وثبتوا، ووقع في قوم حوان خيانةٌ وخِذلان فانهزموا واستولى الروم على عددٍ"},{"id":4393,"era":"c13","t":"قتال بين طوسون وعبد الله بن سعود في القصيم .","s":"بينما كان طوسون باشا قائد الروم (قوات جيش محمد علي) في الحجاز يجهِّزُ للهجوم على نجد؛ إذ وصله كتابٌ من أهل الرس والخبراء يعرضان عليه الطاعةَ, فأرسل إلى عسكَرِه في الحناكية بالسيرِ إلى القصيم ودخول الرس والخبراء، فدخلوهما واستوطنوهما واستولوا على ما فيهما من القصيرات والمزارع,, وثبت بقيةُ بلدان القصيم وحاربوا الروم, فلما علم بذلك عبد الله بن سعود استنفر أهلَ الجبل والقصيم ووادي الدواسر والأحساء وعم"},{"id":4394,"era":"c13","t":"عقد صلح بين الإمام عبد الله بن سعود وطوسون باشا .","s":"بعد مناوشاتٍ وقتال بين قوات طوسون باشا وقواتِ عبد الله بن سعود عُقِدَت معاهدة صلح بينهما أن تضع الحرب بين الفئتين وتُتركَ بموجِبِها نجدٌ وأعماله بقبضة عبد الله, وتدخُلُ الحجازُ تحت الإدارة المصرية، وتعهَّدَ عبدُ الله بأن يعتبر نفسَه تابعًا للسلطان التركي، ووعد بالخضوعِ للوالي المصري في المدينة، وتعهَّد بتأمين سلامة الحج، والذَّهابِ إلى استانبول والمثول أمام السُّلطانِ في حال تم استدعاؤه، وإعادة كن"},{"id":4395,"era":"c13","t":"عبد الله بن سعود يؤدب أهل الخبراء والبكيرية .","s":"سار عبدُ الله بن سعود بجموعِه قاصِدًا القصيمَ ونزل على الخبراء وهَدَّم سورَها وسورَ بلد البكيرية عقوبةً لهم عمَّا تقدَّمَ منهم من استدعائِهم الروم (جيش طوسون) وإدخالهم, وخوفًا أن يُحدِثوا مثلها فيما بعد, وأخذ معه ثلاثةً من رؤساء الرس."},{"id":4396,"era":"c13","t":"الحملة المصرية الثالثة بقيادة إبراهيم باشا على نجد .","s":"جهَّز محمد علي باشا صاحِبُ مِصرَ العساكِرَ الكثيفةَ مِن مصر والروم والشام والعراق إلى نجدٍ مع ابنه إبراهيم باشا، فسار إلى المدينة وضبط نواحيَها، ثم سار إلى الحناكية وأقام فيها، وأكثَرَ الغاراتِ على ما حولها من العُربان، وأخذ أموالًا وقتل رجالًا، فاجتمع عليه كثير من تلك النواحي من حرب ومطير وغيرهم وعتيبة ومن عنزة الدهامشة"},{"id":4397,"era":"c13","t":"وفاة الشريف غالب بن مساعد أمير مكة .","s":"هو الشريفُ غالبُ بن مساعد بن سعيد بن سعد بن زيد بن محسن بن حسين بن حسن بن أبي نُمي، شريفُ مكَّةَ، تولَّى الإمارةَ في مكة بعد أخيه الشريف سرور بن مساعد منذ سنة 1202هـ حتى نَفْيه سنة 1228هـ.  نشأ الشريفُ غالب في كنف والده ملازمًا له مشاركًا معه في حروب, وبعد موت الشريفِ سرور بن مساعد في رجب سنة 1202 قام مقامَه أخوه عبد المعين، ثمَّ رغب عن الأمرِ لأخيه غالب بعد أيام يسيرة من ولايتِه، وكان غالبٌ في سِ"},{"id":4398,"era":"c13","t":"وفاة أحمد طوسون بن محمد علي باشا .","s":"هو أحمد طوسون بن محمد علي باشا المعروف بـ\"طوسون باشا\" الابن الأكبر لمحمد علي باشا والي مصر، وُلِدَ سنة 1208هـ، قاد الحملة الأولى جهةَ نجدٍ ضِدَّ الدولة السعودية الأولى، وخاض فيها عدة معارك انتصر في بعضِها وهُزِم في البعض الآخرِ منها. أصيبَ بجراحٍ في معركة تربة التي هُزم فيها, فنُقِل إلى جُدَّة للعلاج, ثم نُقِل إلى مصر, ومات فيها متأثرًا بجراحِه عن عمر 33 سنة."},{"id":4399,"era":"c13","t":"وفاة الشيخ عثمان دان فوديو زعيم حركة الإصلاح الديني الأفريقي .","s":"هو الشيخُ أبو محمد عثمان بن محمد الملقب بـ (فودي) بن عثمان بن صالح بن هارون بن محمد أحدُ علماء نيجيريا، كان مالكيَّ المذهب. ولِدَ في قرية طقِل في شمال نيجيريا، سنة 1169هـ يعتبرُ عثمان دان فوديو مؤسِّسَ دولة تكرور في سوكوتو في غربِ أفريقيا قريبًا من نهر الكونغو، وكان قد عاد من الحجِّ وهو ممتلئٌ حماسةً للإصلاح الديني، فكَثُر أتباعُه والمتحمِّسون لأفكارِه، فلما زاد عددُ أتباعه ومريديه، وفكَّرَ في الا"},{"id":4400,"era":"c13","t":"تولي داود باشا ولاية بغداد وإسقاطه منها بعد ذلك .","s":"تولَّى داود باشا العثماني الولايةَ على بغداد، وكان معروفًا بقوته، فرفض ما وصل إليه المقيمُ البريطاني جيمس من المكانة؛ حيث كان الرجُلَ الثاني في صلاحياتِه بعد الوالي فأعلن: \"أنَّ حكومة بغداد لا تعترف بأيةِ حقوق أوربية\"، ومِمَّا قام به بناءُ جامع الحيدر خانة، وجامِعِ الأزبك، والمدرسة الداودية, فلم يَرُق للبريطانيين ولا للصفويين هذه القوَّة التي يتمتَّع بها داود باشا، فبدؤوا بالضغط على السلطةِ المركز"},{"id":4401,"era":"c13","t":"استسلام عنيزة لإبراهيم باشا .","s":"لَمَّا استقر صُلحُ أهلِ الرسِّ مع إبراهيم باشا، رحل منها بعساكره إلى الخبراء، فلما نزلها دبَّ الرعب في قلوبِ جيش عبد الله وتفرَّقت البوادي، فرتَّب عبد الله المرابِطةَ في عنيزة، واستعمل محمد بن حسن بن مشاري بن سعود أميرًا عليها، ثم رحل هو إلى بريدة, ثم رحل إبراهيم باشا وعسكره من الخبراء إلى عنيزة ونازل أهلها، فسلَّمَت له وأطاعوا له، وامتنع أهل قصر الصفا فجر عليهم الباشا القبوسَ والقنابر ورماهم بها "},{"id":4402,"era":"c13","t":"عبد الله بن سعود يجمع جيوشه لمواجهة الحملة المصرية بقيادة إبراهيم باشا .","s":"أمر عبد الله بن سعود بعضَ النواحي من أهل الوشم وسدير أن يتجهَّزوا بشوكتهم إلى القصيم، ثم أمر شوكةَ أهل القصيم أن تجتَمِعَ تحت رئاسة أمير القصيم حجيلان بن حمد, ثم تجهَّز عبد الله غازيًا من الدرعية واستنفر جميعَ القوات التابعة لها من الحاضرة والبادية، وخرج من الدرعية لعشرٍ بقين من جمادى الأولى، وقصد ناحيةَ الحجاز ونزل قربَ الرس واستلحق الشوكةَ التي مع حجيلان، وسار حتى نزل العلم- الماء المعروف- وهو ي"},{"id":4403,"era":"c13","t":"هزيمة الإمام عبد الله بن سعود أمام قوات إبراهيم باشا .","s":"في منتصف جمادى الآخرة حمل عبدُ الله بن سعود وقواته على قواتِ إبراهيم باشا حتى قربوا من محطة العسكر, فثوَّرَ الروم مدافعَهم فخَفَّ بعض البوادي مع عبد الله ومَن نزلوا قرب جبل ماوية قبالةَ الروم، فثبت الرومُ بواديهم لَمَّا رأوه نزل فوجه مدافِعَهم إلى المسلمين ورموهم فأثَّرت فيهم، فأمر عبد الله على بعض المسلمين أن يرحَلوا وينزلوا الماء، فلما هموا بالرحيل خفَّت البوادي فتتابعت فيهم الهزيمةُ ووقع الرعبُ"},{"id":4404,"era":"c13","t":"حصار إبراهيم باشا لمدينة الرس ومصالحة أهلها له .","s":"لَمَّا صارت الهزيمةُ على عبد الله بن سعود في جمادى الآخرة رحل بالقُربِ من جَبَل ماوية ونزل إبراهيمُ باشا وقواته الرسَّ، فثبت له أهلُ الرس وحاربوه، وأرسل عبد الله للرس مرابِطةً مع حسن بن مزروع، والهزاني صاحب حريق نعام، فحاصرهم الرومُ أشَدَّ الحصار وتابعوا الحربَ عليهم في الليل والنهار، وكُلَّ يوم يسوقُ الباشا على سورِها صناديدَ الروم بعدما يجعل السورَ بالقبوس فوق الأرضِ مهدومًا، ومع ذلك ثبت أهلُ ال"},{"id":4405,"era":"c13","t":"أهل شقراء يحفرون خندقا لحماية بلدهم من إبراهيم باشا .","s":"أمر حمد بن يحيى أمير شقراء  وناحية الوشم على أهل بلد شقرا أن يحفِروا خندقَ بلَدِهم، وكانوا قد بدؤوا في حَفرِه وقتَ حملة طوسون، فلمَّا صارت المصالحةُ تركوه فقاموا في حَفرِه أشَدَّ القيام واستعانوا فيه بالنِّساءِ والولدان لحَملِ الماء والطعامِ، حتى جعلوه خندقًا عميقًا واسعًا وبَنَوا على شفيرِه جدارًا من جهة السورِ، ثم ألزمَهم كل رجل غني يشتري من الحنطةِ بعَدَدٍ معلومٍ من الريالات خوفًا أن يطول عليهم"},{"id":4406,"era":"c13","t":"السنغال تصبح مستعمرة فرنسية خالصة .","s":"بدأ الفرنسيون يتردَّدون على شواطئ السنغال قديمًا ويُنشِئون مراكِزَ إقامة لهم، وأسَّسوا مستعمرة لهم عند مصَبِّ نهر صنهاجة (نهر السنغال حاليًّا) وأقاموا حِصنَ سان لويس، ثم طردوا البرتغاليين من ممتلكاتِهم جنوبَ الرأس الأخضر ونازع الإنجليزُ الفرنسيين على المنطقةِ، فقد احتلُّوا المستعمرة الفرنسية سان لويس عام 1172هـ، ثم عادت السنغال إلى فرنسا بموجِبِ معاهدة 1198هـ، ولكِنَّ الإنجليز أعادوا الكَرَّةَ واح"},{"id":4407,"era":"c13","t":"انتصار الشريف حمود أبي مسمار على قوات محمد علي باشا .","s":"لما وصلت جيوشُ الروم بقيادة سنان أغا ومعه عددٌ مِن أهل الحجاز وتهامة عسير، استنجد محمد بن أحمد وقومُه من عسير بحمود أبي مسمار أميرِ العريش، فتولى أبو مسمار قيادةَ جموع قوات عسير ووقَعَت الملاقاة بينهم وبين الروم في حجيلا من نواحي عسير، وكثُرَ القتلى بين الفريقين فانهزم الرومُ وفَرَّ سنان إلى القنفذة."},{"id":4408,"era":"c13","t":"إلغاء الدولة العثمانية الإنكشارية في الجزائر .","s":"أقدمت الدولةُ العثمانيةُ على إلغاء حامية الانكشارية في الجزائر، وكان في هذه الحامية حوالي 34 ألفَ انكشاريٍّ. وكانت فِرَق الانكشاريَّة من أكثَرِ الفِرَقِ انضباطًا وقتالًا في الجَيشِ العثماني، لكِنْ تورُّط قادتِها في السياسةِ بعد ذلك أثَّرَ على مستواهم العسكريِّ؛ ممَّا أدى إلى إلغائِها."},{"id":4409,"era":"c13","t":"وفاة الشريف حمود أبو مسمار أمير العريش\n  .","s":"هو الأميرُ الشريف حمود بن محمد بن أحمد الحسني التهامي، ويُعرَفُ بأبي مسمار أمير من أشراف تهامة اليمن، كانت ولادته عام 1170هـ في قرية الملاحة من بلاد بني مالك بالسراة، كانت له ولأسلافه ولايةُ المخلاف السليماني من تهامة ودعوتهم لأئمة صنعاء. في سنة 1210 ثار حمود على ابن عمه علي بن حيدر، فنزل له عن إمارة عريش واستقلَّ بولاية أبي عريش وصبيا وضمد والمخلاف السليماني. واختطَّ مدينة (الزهراء) وبنى قلاعًا و"},{"id":4410,"era":"c13","t":"حصار إبراهيم باشا شقراء واستبسال أهلها في الدفاع عن بلدهم .","s":"ركب إبراهيم باشا من أشيقر بخيلِه وقصد بلد شقراء، فأتاها واستدار فيها، وقاسَها وعَرَف موضِعَ منزلِه ومنزل عسكرِه وقبوسيه؛ لأنه يعلم أنَّ أهلها محاربون أشداءُ وأهلُ صدق في الحرب مجرِّبون، وكان قد أتى إليه أمدادٌ من العساكر والقبوس، وصار في قوَّةٍ عظيمة، فنزل أسفلَ البلد وشمالَه، فخرج إليه أهلُها فساق الباشا عليهم الرومَ، فوقع بينهم قتال شديد في وسطِ النخيل وخارجه، فقُتِل من الروم قتلى كثيرٌ وجُرح كث"},{"id":4411,"era":"c13","t":"دخول إبراهيم باشا ضرما عنوة بعد أن ثبات أهلها في القتال .","s":"كان عبدُ الله بن سعود لما صالح أهل شقراء وأطاع الرومَ جميعُ أهل الوشم وسدير والمحمل وغيرهم، أمر سعود بن عبد الله بن محمد بن سعود في عِدَّةِ رجال من أهل الدرعية ومتعب بن إبراهيم بن عيصان صاحب الخرج وعدة رجال معه ومحمد العميري في عدة رجال من أهل ثادق والمحمل- أمَرَ الجميعَ أن يسيروا إلى بلد ضرما ويدخلوها ليصيروا عونًا لأهلها ورِدءًا لهم، فساروا إليها ودخلوها، ثم إنَّ الباشا وعساكر الروم لَمَّا وصلوا"},{"id":4412,"era":"c13","t":"حصار إبراهيم باشا للدرعية واستبسال أهلها في الدفاع عنها .","s":"عندما نزل إبراهيم باشا على الدرعية رتَّبَ قبوسَه ومدافِعَه وقنابره على جهاتِ الدرعية الأربعة، وكان عبد الله بن سعود قد رتَّب جموع أهل الدرعية ومن كان عنده من أهل الآفاقِ مقابِلَ قوات الباشا، ومن أبرز القادة الذين كانوا مع عبد الله إخوانُه فيصل وإبراهيم وفهد، وتركي الهزاني صاحب حريق نعام، وعبد الله ابن القاضي أحمد العريني رئيس سدير، ومحمد العميري رئيس المحمل، تولى هؤلاء قيادةَ الجبهات، ومعهم المداف"},{"id":4413,"era":"c13","t":"سقوط الدرعية عاصمة الدولة السعودية الأولى .","s":"لَمَّا قبل إبراهيم باشا الصلحَ خرج له من أعيان الدرعية عبد الله بن عبد العزيز بن محمد، والشيخ العالم علي ابن الشيخ محمد بن عبد الوهاب، ومحمد بن مشاري بن معمر، فأرادوا منه أن يصالِحَهم على البلدِ كُلِّه فأبى أن يصالِحَهم إلا على السهلِ، أو يحضُرَ الإمام عبد الله بن سعود فرفضوا، فدخل الرومُ الدرعية ووقعت الحربُ عند مسجد الطريف أيامًا ثم انفَضَّ عن عبد الله بن سعود كثيرٌ ممن كان عنده،  فلما رأى عبد ا"},{"id":4414,"era":"c13","t":"أحوال نجد بعد سقوط الدرعية ونهاية الدولة السعودية الأولى .","s":"لما انهار حكمُ الدولة السعودية على يدِ إبراهيم باشا ودُمِّرَت الدرعية، كَثُر في نجد الاختلافُ والاضطراب ونَهْب الأموال وقَتْل الرجال، وتقدم أناسٌ وتأخَّر آخرون، يقول ابن بشر: \"قلتُ: وانحل فيها نظامُ الجماعة والسَّمع والطاعة، وعُدم الأمرُ بالمعروف والنهيُ عن المنكر، حتى لا يستطيعَ أحد أن ينهى عن منكرٍ أو يأمُرَ بطاعةٍ، وعُملَ بالمحرَّمات والمكروهات جهرًا، وليس للطاعاتِ ومَن عَمِلَ بها قَدْرٌ، وجُرّ"},{"id":4415,"era":"c13","t":"نقض إبراهيم باشا شروط الصلح  واستباحته الدرعية وأهلها .","s":"بعد سفر الإمام عبد الله بن سعود إلى مصر ارتحل إبراهيم باشا بنفسِه وحاشيتِه وقبوسه وقنبره ومدافِعِه من سمحان، ولم يلتزم الباشا بشروطِ الصُّلحِ التي نصَّت على عدمِ المساس بالبَلدةِ وأهلِها بسوءٍ, فنزل إبراهيم باشا في نخل تركي بن سعود المعروفِ بالعويسية أسفلَ الدرعية، وباقي عساكِرِه فَرَّقَها في نخيلِها وأطرافِها ودروبِها، وكان إبراهيم باشا بعث عساكِرَ مِن حاشيته وخَدَمِه وفَرَّقَهم في نواحي نجدٍ وأم"},{"id":4416,"era":"c13","t":"عساكر إبراهيم باشا تسير للأحساء لنهب ما كان فيها لآل سعود .","s":"بعث الباشا إبراهيمُ عَسكرًا إلى الأحساءِ نحو مائتين وأربعين، مقَدَّمُهم محمد كاشف، فساروا إليه مع عبد الله بن عيسى بن مطلق صاحب الأحساء، وأمرهم الباشا بجَمعِ بيت المال وجميعِ ما كان لآل سعود في الأحساءِ، فقَدِموا وأخذوا أموالًا، وقتلوا رجالًا، وصادروا ما كان لآل سعود فيه وطوارفهم، وقُتِلَ رجالٌ مِن أئمة مساجد الأحساء مِن أهل نجد، وأمسكوا عبد الرحمن بن نامي وحبسوه وأخذوا أمواله وقتلوه، وهرب سيفُ بن"},{"id":4417,"era":"c13","t":"التطور العمراني في الدرعية .","s":"يقول ابن بشر: \"كانت هذه البلدةُ -الدِّرعية- أقوى البلادِ، وقوَّةُ أهلها وكثرةُ رجالهم وأموالهم لا يحصيه التَّعداد، فلو ذهبت أعددُ أحوالهم وإقبالَهم فيها وإدبارَهم في كتايب الخيل والنجايب العمانيات، وما يدخلُ على أهلها من أحمالِ الأموالِ مِن سائر الأجناس التي لهم مع المسافرينَ منهم، ومن أهل الأقطار- لم يسَعْه كتاب، ولرأيت العجَبَ العجاب، وكان الداخِلُ في موسمها لا يفقد أحدًا من أهل الآفاقِ مِن اليم"},{"id":4418,"era":"c13","t":"مقتل الإمام عبد الله بن سعود آخر حكام الدولة السعودية الأولى .","s":"هو الإمامُ عبد الله بن سعود بن عبد العزيز بن محمد بن سعود، آخِرُ أئمَّةِ الدولة السعودية الأولى، وآخِرُ حاكمٍ اتَّخَذ من الدرعية عاصمةً للدولة السعودية، وكان عبدُ الله بن سعود ذا سيرةٍ حسنةٍ مقيمًا للشرائع آمرًا بالمعروف ناهيًا عن المنكرِ كثيرَ الصَّمتِ حَسَن السَّمتِ، باذِلَ العطاء موقِّرًا للعلماء، وكان صالحَ التدبير في مغازيه، ثبت في مواطِنِ اللقاء وهو أثبَتُ مِن أبيه في مصابرةِ الأعداء، وكانت "},{"id":4419,"era":"c13","t":"تولي تركي بن عبد الله الحكم في نجد .","s":"جاء تركي بن عبد الله بن محمد بن سعود، فدخل الدرعيَّةَ وتخلَّصَ من ابن مَعمَر، وانتقل إلى الرياض وجعلها مقرًّا لحُكمِه، فقَدِمَت حملاتٌ عثمانية أجبرته على الخروجِ مِن الرياض، واتجه إلى الجنوب وظَلَّ في بلدة الحلوة ثلاثَ سَنَواتٍ يجمَعُ الأنصار."},{"id":4420,"era":"c13","t":"اندلاع الثورة اليونانية طلبًا للاستقلال وانتصار محمد علي باشا .","s":"فُتِن أهالي بعضِ البلاد التي دخلها العثمانيون بالتقَدُّم الذي تمَّ في أوربا فأرادوا السيرَ على منهجِهم، فبَدؤوا يُرسِلون أولادَهم إلى أوربا للتعَلُّمِ فيها، فأسَّس اليونانيون جمعياتٍ سريَّةً لهم في النمسا وروسيا وبدؤوا يعملون للانفصالِ عن العثمانيين؛ لاختِلافِ الروابط العَقَديَّة، وكانت مراكِزُ جمعية الأخوة أهمَّ هذه الجمعيات في فيينا عاصمة النمسا وفي أوديسا في روسيا على البحر الأسود، ثم انتقل إلى"},{"id":4421,"era":"c13","t":"خروج حملة بحرية كبرى من بومباي إلى رأس الخيمة .","s":"كانت ظروفُ السُّلطاتِ البريطانية في الهند مهيَّأةً أكثَرَ مِن أيِّ وقت سابقٍ للقيام بتدخُّلٍ عسكري واسعِ النطاقِ في الخليج العربيِّ وتأكيد سيطرتِها البحرية المؤدِّيةِ إلى المحيطِ الهنديِّ، وكان إيفان تبيان حاكِمُ بومباي في ذلك الوقتِ مِن أنصار التدخُّلِ العسكريِّ في الخليج العربي، فعُرِضت عليه مشروعات عِدَّة للتدخُّل، فاختار منها المشروعَ الذي يَعرِض إنشاءَ قاعدة بريطانية في رأسِ الخيمة والتدخُّل "},{"id":4422,"era":"c13","t":"حملة محمد علي في السودان .","s":"بعد الانتصاراتِ التي حَقَّقَها محمد علي في الجزيرةِ العربيةِ، والتي تمثَّلَت في إسقاطِ الدولة السعودية، قَوِيَ عَزمُه على الإغارة على نواحي السودان، فجهَّز ولدَه إسماعيلَ باشا على رأس حملة لغزو السودان عُرِفَت باسم الغزو التركي للسودان، فغالِبُ جنود الجيش من الأتراك والألبان والمغاربة ولم يشارِكْ في الحملةِ أحَدٌ من المصريين؛ لأنَّ محمد علي لم يبدأ بعدُ بتجنيد المصريين. جمع محمد علي لجيشِ هذه الحم"},{"id":4423,"era":"c13","t":"إنشاء محمد علي باشا أول مدرسة حربية في مصر .","s":"لما جاء الكولونيل سيف -سليمان الفرنساوي- إلى مصرَ، كضابط مع الحملة الفرنسيةِ ولَمَّا آنس منه محمد علي باشا الكفاءةَ لتحقيق مشروعه؛ أنفذه إلى أسوان ليؤسِّسَ مدرسة حربية تخرِّجُ ضباطًا على النمط الأوربي؛ ليكونوا النواةَ الأولى من جيشِ مِصرَ الحديث، وبدأ العمَلَ في هذه المدرسة بأن قَدَّم إليه خمسمائة من خاصَّةِ مماليكه ليدَرِّبَهم على أن يكونوا ضبَّاطًا في النظامِ الحديث، وطلب إلى بعضِ رجاله أن يحذُو"},{"id":4424,"era":"c13","t":"افتتاح \"غرفة ترجمة الباب العالي\" في الدولة العثمانية .","s":"افتُتحت في الدولة العثمانية \"غرفة ترجمة الباب العالي\" وكان خريجو هذه المدرسة هم عمادَ السلك الدبلوماسي العثماني، وهم من أسَّسوا الدبلوماسيَّةَ التركيةَ الحديثة، وكانت اللغةُ الرئيسية فيها هي اللغةَ الفرنسيةَ."},{"id":4425,"era":"c13","t":"معاهدة أرضروم بين الفرس والعثمانيين .","s":"في أوائل القرن التاسع عشر ظهر إلى الوجودِ في هذه المنطقة نفوذُ روسيا القيصرية المتمَثِّل في شمال إيران وبريطانية التي يتمَثَّل وجودُها في الخليج العربي وجنوب إيران، وقد أخذت إيران في هذه الفترة في إثارة المشاكِلِ في العراق ضِدَّ الدولة العثمانية عن طريق إثارة المتمَرِّدين وتحريضِهم للثورة؛ ونظرًا لرغبةِ الأطراف المعنيَّة في وضع حدٍّ لهذه المشاكل الحدودية بين الدولتين العثمانية والإيرانية، فقد توسّ"},{"id":4426,"era":"c13","t":"إحراق البحارة اليونانيين للدونانمة .","s":"تمكَّن البحَّارة اليونانيون من إحراق الدونانمة، أي: الأسطول البحري التركي، في إطار ثورةِ اليونانيين التي اندلعت شرارتُها في المورة ضِدَّ الحكمِ العثمانيِّ، وقُتِلَ في هذه المعركة نحوُ ثلاثة آلاف مقاتل من البحرية التركية."},{"id":4427,"era":"c13","t":"استيلاء تركي بن عبد الله على ضرماء .","s":"دخلت هذه السنةُ وتركي بن عبد الله في بلد عرقة محاربًا لأهلِ الرياض ومنفوحة، وأهلِ الخَرج وصاحب ضرما وثرمداء وحريملاء. وباقي بلدان نجدٍ يكاتبونه بلا متابعةٍ، ثمَّ إن تركي عزم أن يسطوَ على ناصر السياري في بلد ضرما، فقصده من بلد عرقة، واستخلف فيها عمرَ بن محمد بن عفيصان، وليس مع تركي إلا شرذمةٌ قليلة، فدخل عليه المسجد فوجده في سطحه، وتمكَّنَ من قتله، واستولى تركي على بلد ضرما وملكَها وأقام فيها."},{"id":4428,"era":"c13","t":"هلاك معظم العساكر المصرية في عسير .","s":"سار أحمد باشا رئيسُ مكَّةَ بعسكرٍ كثيرٍ مِن مِصرَ والحجاز وغيرِهم، ومعه عددٌ من أشراف مكة وأتباعهم، فقَصَدوا عسير في اليمن، ورئيسهم سعيد بن مسلط، فوقع بينهم وقعاتٌ، فوقع على عساكر الباشا بَردٌ وبَرقٌ لا يُعرَفُ له نظير، فهلك غالِبُ العسكر ولم ينجُ منهم إلا القليلُ."},{"id":4429,"era":"c13","t":"بداية قيام الدولة السعودية الثانية .","s":"في رمضان عام 1238هـ بدأ تركي بن عبد الله تحَرُّكَه من مخبَئِه في بلدة الحلوة جنوبي نجد؛ لإخراجِ بقية القوَّات الغازية وحامياتها الموجودة بالرياض ومنفوحة، فانطلق منها وجمَعَ أتباعه عند بلدة عرقة قُربَ الرياض، وتوافَدَت إليه جموعُ المؤيِّدين من سدير والوشم، وبعد قتالٍ استمَرَّ لمدة عام ضد الحاميتين أجبر من كان فيهما من الجنودِ على المغادرة إلى الحجاز في أواخر عام 1239هـ وأمر مشاري بن ناصر آل سعود بد"},{"id":4430,"era":"c13","t":"وفاة المؤرخ عبد الرحمن الجبرتي .","s":"هو عبدُ الرحمن بن حسن بن إبراهيم الجبرتي، وُلِدَ في القاهرة عام 1753م والجبرتي نسبةً إلى بلدة جبرت، وهي بلاد زَيلَع في الحبشة، كان والِدُه من كبارِ العُلَماء الفَلَكيين، وحصل على ثروةٍ كبيرةٍ مِن عمله في التجارة، وقد رُزِق بنيِّف وأربعين ولدًا ذكَرًا، فعاش الجبرتي وسطَ أسرة ثرية، وكان تلميذًا لوالِدِه في مختلف المعارفِ، كما درس الجبرتي في الأزهر وبرَعَ في العلومِ العصريَّة وفي التاريخ، عُيِّنَ الج"},{"id":4431,"era":"c13","t":"بلدان نجد تدين بالولاء لتركي بن عبد الله .","s":"دانت جميعُ بلدان نجدٍ كلِّها بالسَّمعِ والطاعة للإمام تركي بن عبد الله سوى الأحساءِ وما يليه، فاطمأنَّت الرعيَّةُ، وأَمِنت البلدان والقرى، وخافت سطوتَه أشرارُ البلدان، ولانت لهيبتِه رؤوس العُربان، وزالت عنهم الفِتَن والحُروبِ."},{"id":4432,"era":"c13","t":"السلطان العثماني محمود الثاني يقضي على الجيش الانكشاري .","s":"فسدت طبيعةُ الانكشاريين وتغَيَّرت أخلاقهم، وتبدلَّت مهمَّتُهم، وأصبحوا مصدرًا للبلاءِ للدولة والشعوب التابعة لها، وصاروا يتدخَّلون في شؤونِ الدولة وتعَلَّقت أفئدتُهم بشهوةِ السلطة وانغمَسوا في الملذات والمحرمات، وشق عليهم أن ينفِروا في برودة الشتاءِ، وفرضوا العطايا السلطانية، ومالوا إلى النَّهبِ والسلب حين غَزوا البلاد، وتركوا الغاية التي من أجلِها وُجِدوا، وغَرَقوا في شرب الخمور، وأصبحت الهزائِمُ"},{"id":4433,"era":"c13","t":"عودة الشيخ عبدالرحمن بن حسن ابن الشيخ محمد بن عبد الوهاب من مصر  .","s":"قَدِم الإمامُ الحافظ المتقِن قاضي قضاة الإسلام الشيخ عبد الرحمن بن حسن ابن الشيخ محمد بن عبد الوهاب مِن مِصرَ على الإمام  تركي بن عبد الله بعد أن بَقِيَ في مصر 9 سنوات منذ أن نفاه إليها إبراهيم باشا عام 1233، وكان معه ابنه عبد اللطيف صغيرًا, ففرح الإمامُ تركي به وأكرمه، واغتبط به المسلمون الخاصُّ والعامُّ، وبذل الشيخُ مِن نفسه للطالبين، فانتفع بعِلمِه كثيرٌ مِن المستفيدين."},{"id":4434,"era":"c13","t":"صدور أول جريدة عربية بمصر .","s":"أصدَرَ محمد علي باشا والي مصر جريدةَ (الوقائع المصرية) باللغتين العربية والتركية، وقد ظهرت فكرةُ الجريدة في الصحافة المصرية بجُهدٍ مِن الحملة الفرنسية؛ حيث أُنشِئت أوَّلُ جرَيدةٍ عَرَفَها الشعب المصري، وهي جريدة بريد مصر، التي صدرت باللغة الفرنسية في 29 أغسطس سنة 1798م، ومع جَلاء الحملة الفرنسية ومع استقرارِ الأوضاع في مصرَ بدأت فكرةُ وجود صحافة محلية والاستفادة من مطبعة بولاق. لم تكُنْ لمحمد علي "},{"id":4435,"era":"c13","t":"وفاة الأمير رَحمَة بن جابِر حاكم ساحل الدمام .","s":"هو الأميرُ رحمةُ بن جابر بن عذبي شيخُ الجلاهمة ورئيسُهم، جعله الإمامُ سعود بن عبد العزيز حاكِمَ ساحل الدمام، وهو قُرصانٌ كويتي، من الشجعان. اشتهر بمساعدته لأهل البحرين على الخلاصِ من الاحتلال الفارسي عام 1782م، فجعلوا له حصةً مما يحصُلون عليه من اللؤلؤ. ثم توقَّفوا. هاجر إلى دارين واحترف القرصنة 1802 م فكان له أسطولٌ قوامه خمسُ سفن. يزيدُ بحَّارتُها على الألف بحَّار. أخذ يعترض سفُنَ الغوَّاصين ولا"},{"id":4436,"era":"c13","t":"وفاة الشيخ عثمان بن عبد الجبار  .","s":"هو العالم الفقيهُ الشيخ عثمان بن عبد الجبَّار بن حمد بن شبانة الوهبي التميمي، بقيَّةُ العُلماء الزُّهَّاد، ورِثَ العلمَ كابرًا عن كابر مِن آبائه وأجداده وأعمامه وإخوانه، وممَّن تعلم منهم ابنُ عمه الشيخ حمد بن عثمان بن عبد الله، والشيخ حمد التويجري، والشيخ عبد المحسن بن نشوان بن شارخ، القاضي في الكويت والزبير، والشيخ عبد العزيز بن عيد الإحسائي نزيل الدرعية، وكان الشيخ عثمان فقيهًا له قُدرةٌ على است"},{"id":4437,"era":"c13","t":"اندلاع الحرب بين روسيا والدولة العثمانية ومعاهدة أدرنة .","s":"بعد أن أعلنت روسيا الحربَ على الدَّولةِ العُثمانية في شوال مِن هذا العام، اجتازت نهرَ بروت الفاصل بين الدولتين والذي يرفدُ نهر الدانوب قُربَ مَصَبِّه، واحتلت عاصمةَ إقليم البغدان ياش الواقعةَ على النهر، ثم دخلت بخارست عاصِمةَ الأفلاقِ، وجعلت على الإقليمينِ حُكَّامًا من قِبَلِها، ثم اجتازت نهرَ الدانوب واتَّجَهت جيوشُها لحصار مدينةِ فارنا الواقعةِ في بلغاريا على ساحلِ البحر الأسود، وحاصرَتْها برًّا"},{"id":4438,"era":"c13","t":"أهل جبل شمر يبايعون الإمام تركي بن عبد الله على السمع والطاعة .","s":"وفد عيسى بن علي رئيس جبل شمر على الإمامِ تركي بن عبد الله ومعه رؤساءُ قَومِه، فبايعوه على دين الله ورسولِه والسَّمعِ والطاعة، وجعل في بيتِ مال الجبل حمدَ الشويعر الذي كان على بيتِ مالِ الجبل منذ أيام الإمامَينِ سعود وعبد الله."},{"id":4439,"era":"c13","t":"وفاة الشيخ عبد الله ابن الشيخ محمد بن عبد الوهاب .","s":"هو الإمامُ العلَّامةُ الأوحد الشيخ عبد الله ابن شيخ الإسلام محمد بن عبد الوهاب، الثِّقةُ الثَّبتُ, التقي الوَرِعُ المجاهد المحتَسِب, ذو الهمة العالية والشجاعة المتناهية, الذي خَلَف والِدَه شيخ الإسلام محمد بن عبد الوهاب في مؤازرة الإمامِ عبد العزيز بن محمد بن سعود، وخَلَفه في بثِّ العلم والقيام بدعوة التوحيد ونَشْرها، والدفاع عنها بالقلَمِ واللسان، والحُجَّة والبيان، وهو عالمُ نجد بعد أبيه ومُفتيه"},{"id":4440,"era":"c13","t":"رخص الأسعار وكثرة الأمطار في نجد .","s":"وفيها أرخص اللهُ الأسعارَ وكَثُرت الأمطارُ وفاضت الآبارُ، فأول ما نزل الغيثُ في الموسم زرع عليه النَّاسُ، فلمَّا حُصِد الزَّرعُ ونُقِلَ في بيادره تتابَعَ الغيثُ فأعطنت الزروع، فلم يكن للناسِ شُغلٌ إلَّا نشرُها وجمعُها، واسوَدَّ التبن وتغَيَّر الحَبُّ، وأقام الناس على ذلك نحوًا من عشرين يومًا، كل يوم ينزل الحَيَا والسيلُ في آخِرِ النَّهارِ، وأوَّلُه صَحوٌ لم يُرَ عليها قزعة، فلما كبر البُسر وصار كا"},{"id":4441,"era":"c13","t":"هزيمة إبراهيم باشا في معركة نافارين  .","s":"طلبت إنكلترا من الدولة العثمانية في الثامن من رجب عام 1242هـ أن تتوسَّطَ الدول الأوربية النصرانية بين الدولةِ العثمانية وبين ما يتبَعُها، فرفضت الدولةُ العثمانية ذلك؛ لأنَّ هذا تدخلٌ صريح في شؤونها الداخلية، فكان هذا الرَّفضُ حُجَّةً تذرعت به لإعلان الحربِ مَرَّةً أخرى بعد أن ضَعُفت الدولة سياسيًّا، فاتفقت روسيا وفرنسا وإنكلترا في الحادي عشر من ذي الحجة على إجبارِ الدولة العثمانية لإعطاء اليونان ا"},{"id":4442,"era":"c13","t":"أهل القصيم يبايعون الإمام تركي بن عبد الله على السمع والطاعة .","s":"أرسل الإمامُ تركي إلى رؤساء القصيم وأمراء بلدانه، وأمرهم بالقدومِ إليه فأقبل جميعُ أمراء القصيم ورؤسائه، فقَدِموا عليه في الرياضِ وبايعوه كلُّهم على السَّمعِ والطاعة، وعزَل محمَّدَ بن علي الشاعر عن إمارة بُرَيدة وجعَلَ مكانَه عبد العزيز بن محمد بن عبد الله، ثمَّ لما بلغ الإمامَ تركيًا ما يريبُه من محمد بن علي أرسل إليه وجعله عنده في الرياضِ ولم يأذن له بالعودةِ للقصيم حتى قَوِيَ عبد العزيز بن محمد"},{"id":4443,"era":"c13","t":"خروج فيصل بن تركي من مصر .","s":"أقبل فيصل بن تركي هاربًا مِن مصر وقَدِمَ على أبيه في الرياض فاستبشر به والِدُه، وصار فيصل الساعِدَ الايمان لوالده في إدارة الدولة، وقد كان فيصل من ضمن المنقولين إلى مصر سنة 1234 ومعه أسرته، وهم إخوانُه وعددهم أربعةٌ، وأخواتُه اثنتان، ووالدته، وثمانٍ مِن جواريه، وسبعةٌ من عبيدِه وخَدَمِه، وكان مجموعُ من نفى إبراهيم باشا إلى مصرَ مِن آل سعود وآل الشيخ 351 بموجِبِ البيان الذي أرسله إبراهيمُ لوالده في"},{"id":4444,"era":"c13","t":"رؤساء العربان يبايعون الإمام تركي بن عبد الله  .","s":"وَفد رؤساءُ العُربان من سبيع ومطير والعجمان وقحطان وغيرهم على الإمامِ تركي يبايعونه على السَّمعِ والطاعةِ، فأرسل معهم عمالًا يَقبَضون الزكاةَ."},{"id":4445,"era":"c13","t":"فتنة بين الصميط من أهل حرمة وآل راشد رؤساء أهل حرمة في  الزبير  .","s":"وقع سِبابٌ بين سليمان بن عبد الله الصميط من سبيعٍ، ومِن أهلِ حرمة وبين عبد الرحمن بن مبارك بن راشد، رئيس أهل حرمة، فوثب رجلٌ من آل راشد فقتَلَ سليمانَ، فكمن رجلٌ من الصميط لناصر بن راشد أمير الزبير فقتَلَه، وحصل مجاولات بين الفريقين، انضَمَّ إلى آل راشد آلُ زهير، ثم وقع الصلح بينهم واجتمعوا له وحضره العُلَماء والرؤساء والمشايخ، وكتبوا بينهم سِجِلًّا أودعوا فيه شيئًا عظيمًا من المواثيق، وشَهِدَ علي"},{"id":4446,"era":"c13","t":"تحطيم الأسطول المصري في معركة نفارين .","s":"قام الأسطولان البريطاني والروسي بتحطيمِ الأسطول المصري في معركةِ نفارين؛ وذلك لخشيةِ كلا الأُسطولين من ازديادِ نُفوذِ محمد علي باشا بعد استدعاءِ السلطان العثماني للجيشِ المصري؛ لإخماد الثورةِ التي اشتعلت في بلادِ المورة ضدَّ الدولةِ العثمانيةِ."},{"id":4447,"era":"c13","t":"الدولة العثمانية توقع معاهدة أكرمان مع روسيا .","s":"وقَّعت الدولةُ العثمانية معاهدةَ أكرمان مع روسيا، وتمَّ بموجِبِ هذه المعاهَدةِ توسيعُ الاستقلال الداخلي لرومانيا وصربيا، كما تقَرَّر بموجِبِها عدمُ وجودِ أيِّ مُسلمٍ محليٍّ في قِلاعِ صربيا عدا الجنودِ الأتراك."},{"id":4448,"era":"c13","t":"إعلان روسيا الحرب على الدولة العثمانية واحتلالِ رومانيا .","s":"أعلنت روسيا الحربَ على الدولة العثمانية، وتمكَّنَت من إخراجِ العثمانيين من السواحِلِ الشرقية للبَحرِ الأسود، وقامت باحتلالِ رومانيا التي كانت تابعةً للدولة العثمانية في تلك الفترة."},{"id":4449,"era":"c13","t":"تجديد أهل رأس الخيمة ولاءهم للإمام تركي بن عبد الله .","s":"كانت رأسُ الخيمة قد أعلنت ولاءَها للدولة السعودية الأولى، ولجأ إليها عددٌ من الذين فرُّوا من الدرعية بعد استسلامِ الإمام عبد الله بن سعود، وجَدَّد أهلُ رأس الخيمة ولاءَهم لتركي بن عبد الله، حيث قَدِمَ إليه وفد منهم يطالبون بقاضٍ ومعلم وسَرِيَّةً، فأرسل معهم سَرِيةً بقيادة عمر بن عفيصان لحمايتِهم من خصومِهم، ومعه قاضٍ هو الشيخ محمد بن عبد العزيز العوسجي قاضي بلدان المحمل زمنَ الإمام سعود، وأصبحت وا"},{"id":4450,"era":"c13","t":"وفاة الشيخ عبد العزيز بن حمد بن معمر .","s":"هو الإمامُ العلَّامة الشيخُ عبد العزيز بن الشيخ الإمام حمد بن ناصر بن عثمان بن معمر من آل معمر أهل العُيَينة، وهم من بين سعد بن زيد مناة بن تميم، وُلِدَ في الدرعية مركزِ الحركة العلمية في ذلك الحين سنة 1203هـ ونشأ في وسط العلماء العاملين الذين كانت تزخَرُ بهم الدرعيةُ ونجد في ذلك الزمنِ، فكان من شيوخِه والِدُه الشيخ حمد بن ناصر بن معمر، والشيخ الإمام عبد الله ابن شيخ الإسلام محمد بن عبد الوهاب، وا"},{"id":4451,"era":"c13","t":"توقيع معاهدة أدرنة بين روسيا والدولة العثمانية .","s":"تَمَّ توقيعُ معاهدة أدرنة بين روسيا والدولة العثمانية في عهد السلطان محمود الثاني في منتصَفِ هذا الشهر، فبعد أن احتلت روسيا مدينةَ أدرنة خَشِيَت فرنسا وإنكلترا أن تحتَلَّ روسيا استانبول فإنَّ ذلك يهَدِّدُ مصالحهما الخاصة، فسارعتا للوقوف في وجهِ روسيا وبجهودِ مملكة بروسيا تم عقد معاهدة أدرنة والتي بمقتضاها دعمت روسيا مركزَها في البحر الأسود، بينما تقَلَّصت السيادةُ العثمانية، فانحسرت عن جميعِ مَصاب"},{"id":4452,"era":"c13","t":"بدء احتلال فرنسا للجزائر واستمرار عملية المقاومة (18) عامًا .","s":"كان السببُ الظاهِرُ الذي دعا إلى احتلالِ الفرنسيين للجزائر هو ما قام به حاكمُ الجزائر الباي حسين التابِعُ للدولة العثمانية، وهو يستقبل المهنِّئين بعيد الفطر، وكان من بينهم السفيرُ الفرنسي الذي جرى حديثٌ بينه وبين الباي حسين بشأن الدُّيون التي على فرنسا للجزائر، فوجَّه السفير كلامًا يمَسُّ كرامة الباي الذي غَضِبَ، وكان بيده مروحة أشار بها في وجهِ السفير الذي أصاب وجهَه طرفُ المروحة، فكان هذا الحادث"},{"id":4453,"era":"c13","t":"ضم الأحساء للدولة السعودية الثانية .","s":"تطَلَّع الإمامُ تركي بن عبد الله بن محمد بن سعود إلى ضَمِّ الأحساء التي استعادها بنو خالد بعد سقوطِ الدرعية، وأراد التخلص من تهديدهم لدولته، فأمر عمر بن محمد بن عفيصان فغزاها فرَدَّ عليه أحدُ زعماء بني خالد بغزوِ بلدة حرمة بنجد. ولكنَّ الدائرةَ دارت على بني خالد ودخل الإمامُ تركي الأحساء دون قتالٍ، بعد هروب بني خالد منها، وقد وفد زعماءُ القطيف على الإمام وبايعوه على السَّمعِ والطاعة، وبهذا رجَعَت "},{"id":4454,"era":"c13","t":"العثمانيون يقضون على المماليك في العراق .","s":"حَكَم المماليكُ في العراق 1189 - 1247هـ، 1775 - 1831م. وأدَّى ضَعفُ السُّلطة المركزية والانحسارُ الفِعليُّ للوجودِ العثماني المباشِر عن أقاليمَ عديدة، إلى قيامِ سُلُطاتٍ محليَّةٍ قوية تمكَّنت مِن ملءِ الفراغ الناجم عن ذلك الانحسارِ، فظهرت سُلطةُ المماليك في العراق. وتميَّزت فَترةُ حكم المماليك بتعاقُبِ وُلاةٍ مماليكَ على السُّلطةِ في بغداد، وظهور دورٍ ملحوظٍ للقُوى الأوروبية في إسنادِ ترشيحِ أحَدِ"},{"id":4455,"era":"c13","t":"جهاد الإمام شامل للروس في بلاد القوقاز .","s":"نفَّذ شامِلٌ انسحابًا تكتيكيًّا إلى داخل الجبال، مغريًا الروس بالتوغُّل خلفه عبر الغابات الكثيفة، فانقضَّ عليهم المريدون من جهاتٍ مختلفة. وقتلوا أكثَرَ مِن نصف ضبَّاط الروس، وتوالت الهجماتُ على الروس حتى غنِمَ المريدون منهم أربعةَ مدافعَ روسية استُخدِمَت في حرب الروس الذين قُتِلَ منهم خلال أربع سنوات أكثر من 10.000 قتيلٍ"},{"id":4456,"era":"c13","t":"حملة محمد علي باشا على الشام بحجة توحيد الشام مع مصر .","s":"كان محمد علي باشا والي مصر يطمَعُ أن يوسِّعَ أملاكَه ويرغَبُ في ضَمِّ الشام إليه، ولَمَّا فَرَّ عددٌ من الهاربين من التجنيد إلى الشام والتجؤوا إلى عبد الله باشا والي عكَّا، ومنهم من هرب من الضرائب الفادحة، فتذرَّع محمد علي بهذه الذريعة للدُّخول إلى الشام، وكان قد راسل الخليفةَ بنيَّتِه، ولكِنَّ الخليفةَ لم يوافِقْه على ذلك، ولكِن محمد علي لم يصغِ إليه، بل أرسل جيشًا بريًّا بقيادة ابنه إبراهيم، وسي"},{"id":4457,"era":"c13","t":"خروج مشاري بن عبد الرحمن على خاله تركي بن عبد الله .","s":"بينما كان الإمامُ تركي غازيًا في الشمال خرج مشاري بن عبد الرحمن من الرياض مغاضِبًا لخاله الإمام تركي بن عبد الله، فبحث عمَّن يَنصُرُه عند مطيرٍ ورؤساء أهل القصيم وعنزة، وأخيرًا شريف مكة محمد بن عون، فلم يجِدْ منهم من ناصره، فعاد إلى الرياض نادمًا سنة 1248هـ وطلب من خالِه العفو فعفا عن وأكرمه، وأسكنه في بيتٍ عنده، وحجز النَّاسَ عن زيارته."},{"id":4458,"era":"c13","t":"احتلال فرنسا للجزائر .","s":"قامت فرنسا باحتلالِ الجزائر، وكان سببُ ذلك رفْضَ \"الباشا حسين\" تقديمَ اعتذارٍ إلى قنصل فرنسا، وكان القنصلُ الفرنسي قد أساء معاملةَ الباشا، فأشار الباشا بمروحةٍ في يده على وجهِ القنصل, فاعتبرها الفرنسيون إهانةً لفرنسا، فأمر مَلِكُ فرنسا بضرورةِ احتلال إقليمِ الجزائر، فأرسلت الحكومةُ الفرنسية جيشًا من 28 ألف مقاتل وأسطولًا يضم مائة سفينةٍ، وثلاثة سفن تحمل 27 ألف جندي بحري، ونزلت بالقرب من مدينة الجز"},{"id":4459,"era":"c13","t":"استيلاء الاستعمار الفرنسي على الأوقاف الإسلامية بالجزائر .","s":"بدأ الاستعمارُ الفرنسيُّ في وَضعِ يَدِه على الأوقافِ الإسلامية بالجزائر، وانتهى الأمرُ بتصفية تلك الأوقاف لصالحِ الاستيطانِ الفرنسيِّ."},{"id":4460,"era":"c13","t":"خروج الإمام تركي بن عبد الله لمناطق الشمال .","s":"سار الإمامُ تركي بن عبد الله بجميعِ رعاياه من أهلِ وادي الدواسر والأحساء والوشم وسدير والقصيم وجبل شمر وعربانهم، فقصد الشمالَ، ووافق فهيدًا الصييفيَّ رئيسَ سبيع -الذي كان يُعلِنُ عداوته للسعوديين منذ أيام سعود بن عبد العزيز- وأتباعَه، فصبَّحَهم وأخذهم، فلما حاز أموالهم ذكروا أنَّ لهم عنده ذمَّةً وعهدًا، فردَّ عليهم جميع ما أُخِذَ منهم، ثم سار ونزل على ماء الصبيحة قربَ الكويت، فأرسل إليهم رئيس الكو"},{"id":4461,"era":"c13","t":"وباءٌ في مكة يسمى أبو زويعة .","s":"وقع وباءٌ وموتٌ عظيم في مكة، وهو الوباء المعروف بـ أبو زويعة (العقاص) وأوَّل ما وقع فيها قبل قدومِ الحاجِّ، ومات منه فئامٌ مِن الناس ثم ارتفع عنها مع دخول ذي الحجة، فلما كان يومُ النحر حلَّ الوباء والموت العظيم ثانيًا في الحاجِّ وغيرِهم، وقيل: لم يبقَ من حاج الشامِ إلا قدرُ ثلُثِه، ومن حاجِّ أهل نجد من كلِّ بلد هلك بعضُهم نصفُه، وبعضهم أقل أو أكثر، وأُحصي من مات من أهل مكة فكانوا 16 ألف نفسٍ، ولَم"},{"id":4462,"era":"c13","t":"الحملة المصرية تدخل الأناضول ومعاهدة كوتاهية مع محمد علي  .","s":"استطاع إبراهيم باشا أن يستوليَ على بلاد الشام جميعِها ويهزِمَ جيشَ حسين باشا من قِبَلِ الخليفة العثماني، فتابع إبراهيمُ سيرَه باتجاه الأناضول فجهَّز الخليفةُ أيضًا جيشًا آخر بقيادة رشيد باشا الذي التقى مع إبراهيم قرب قونية بعد أن اجتاز إبراهيم جبالَ طوروس، واحتَلَّ أضنة، وانتصر إبراهيم باشا وأخذ القائِدَ رشيد باشا أسيرًا، وأصبحت أبوابُ استانبول مفتوحةً أمامه، فخَشِيَت الدول الأوربية أن يتوغَّلَ أك"},{"id":4463,"era":"c13","t":"طاعون عظيم يعم العراق وما حوله .","s":"وقع الطاعونُ العظيم الذي عَمَّ العراق والسواد والمجرة وسوق الشيوخ والبصرة والزبير والكويت وما حولها، وليس هذا مِثلَ الوباء الذي قبله المسمى العقاص (أبو زويعة)، بل هذا هو الطاعونُ المعتاد -نعوذ بالله من غضبه وعقابه- وحَلَّ بهم الفَناءُ العظيم الذي انقطع منه قبائل وحمائل، وخلت من أهلها منازلُ، وإذا دخل في بيتٍ لم يخرج منه وفيه عينٌ تطرفُ، وجثا الناسُ في بيوتهم لا يجِدون من يدفنهم، وأموالهم عندهم ليس"},{"id":4464,"era":"c13","t":"وفاة ابن لعبون أمير شعراء النبط .","s":"هو الشاعرُ المشهور محمد بن جمد بن محمد ابن لعبون بن  مدلج الوايلي البكري العنزي، أمير شعراء النبط، ولِدَ في بلدة حرمة بنجد سنة 1205هـ وحَفِظَ بها القرآن وتعَلَّم الكتابة، وكان خطُّه فائقًا. ونَظَم الشعرَ في صغرِه. ومال إلى اللهوِ والبطالة. ورحل إلى الزبير في العراق، ساعده ذكاؤه  الشِّعري وشخصيتُه المَرِحة الطَّرِبة في توطيدِ علاقاته مع كثيرٍ مِن وجهاءِ وأعيان نجد والزبير والكويت والأحساء والبحرين "},{"id":4465,"era":"c13","t":"تعيين علي باشا واليا على بغداد .","s":"قَدِمَ علي باشا واليًا على بغداد مِن جهةِ السلطان محمود العثماني، وعَزَلَ داود أفندي، وأشخصه إلى استانبول، واستولى على خزائنِه، وكان داود شغوفًا بجمع الأموال ومصادرةِ الرجال وأخذ أموالهم."},{"id":4466,"era":"c13","t":"عمال الإمام تركي بن عبد الله يجبون الزكاة من نواحي نجد .","s":"سار الإمامُ تركي بن عبد الله غازيًا من الرياض بجميعِ غَزوِه من نواحي رعاياه، ونزل الرمحية -الماء المعروف في العرمة- وأقام فيها نحو 40 يومًا ووفد عليه كثيرٌ من رؤساء العُربان من أهل الشمال، وأتاه كثيرٌ مِن الهدايا من رؤساءِ الظفير والمنتفق وغيرهم، وأتى إليه مكاتباتٌ من علي باشا والي بغداد، ثم بعث الإمام عمالَه لعُربان نجد يقبِضون منهم الزكاةَ، فكُلُّهم سَمِعوا وأطاعوا وأدَّوا الزكاة سوى العجمان، ثم"},{"id":4467,"era":"c13","t":"إصدار السلطان العثماني أمرًا بإلغاء حامية الإنكشارية في تونس .","s":"أصدر السلطانُ العثماني محمود الثاني أمرًا إلى والي تونس حسين باشا بأن يُلغي حامية الانكشارية الموجودة في إيالته، وأن يطبق القوانين التي شرَعَها السلطان لتحديثِ الدولة العثمانية."},{"id":4468,"era":"c13","t":"ظواهر غريبة في الأفق بنجد .","s":"حصل في السماء تغييرٌ عند طلوع الشمس وعند غروبها؛ ففي آخر صفر ليلة خمس وعشرين وست وعشرين منه، صار في السماء والأرض نورٌ قريبٌ من نور القمر، واستمَرَّ إلى آخر الشهر، فلما كان سابع ربيع الأول صار قَترٌ في السماء وتغيرت الشمسُ، وفي أول العشر الأواخر من هذا الشهر ظهرت الشمسُ مِن المشرق خضراءَ كأنَّها قطعةُ زجاج وصارت تلك الخُضرةُ في الجدران والأرض، وحسبها الناس كسوفًا! وفي هذا الشهر صار في الأُفقِ حُمر"},{"id":4469,"era":"c13","t":"عودة القائد العثماني البحري \"كوجاك مراد رئيس\" إلى الجزائر .","s":"عاد القائدُ العثماني البحري \"كوجاك مراد رئيس\" إلى الجزائر مع 12 سفينة عثمانية، وذلك بعد قيامه بغارة بحرية على موانئ إيرلندا، وأسَرَ خلالها 400 شخص، وقد استغرقت هذه الحملةُ إلى حين عودتها 3 أشهر."},{"id":4470,"era":"c13","t":"حصول جزيرة سيسام على استقلالها الذاتي عن الدولة العثمانية .","s":"حصلت جزيرةُ سيسام القريبةُ من سواحل الأناضول على استقلالِها الذاتيِّ عن الدولةِ العثمانيةِ، وذلك مقابِلَ مبلغٍ مِن المال تدفعُه سنويًّا للعثمانيين، وتبلُغُ مساحةُ هذه الجزيرة 550 كم2، وقد ضمَّتْها اليونان إليها عام 1913م."},{"id":4471,"era":"c13","t":"فتح إبراهيم باشا بن محمد علي عكا .","s":"نجح إبراهيم باشا بن محمد علي باشا في فتح عكا بعد حصار دام ستة أشهر، وكان لسقوطِها دويٌّ هائِلٌ على الدول الأوروبية، ولفتت الأنظارَ إلى عبقرية إبراهيم باشا وأركان حَربِه سليمان باشا الفرنساوي. وتجدُرُ الإشارةُ هنا إلى أن نابليون بونابرت القائِدَ الفرنسي كان قد عجز عن اقتحامِها قبل ذلك أثناء حملتِه على مصر والعالمِ الإسلاميِّ."},{"id":4472,"era":"c13","t":"عمر بن عفيصان أميرًا على الأحساء وعمان .","s":"كتب الإمام تركي بن عبد الله إلى عُمَرَ بنِ محمد بن عفيصان أمير الأحساء يتجهَّزُ برجالٍ معه إلى عمان؛ ليصير أميرًا للجميع، فسار إلى عمان وفتح بلدانًا وأخذ عربانًا."},{"id":4473,"era":"c13","t":"برد عظيم أضر بالنخيل في نجد .","s":"وقَعَ بردٌ شديدٌ في نجدٍ أضَرَّ بالنخلِ وقطرت العسبان دبسًا مِن شدة البرد، فلما جاء الصيفُ بان الخَلَلُ في النخيل ويَبِس أكثر عسبانها، وأما الزرع والقتُّ والنبات فضرَرُه قليل، ثم حصل في السنة التالية بردٌ أعظم من الأول حتى تجمَّد الماء في السواقي والزروع وبين الميزاب والأرض، وأضَرَّ بالنخل، وفي هاتين السنتين ما اختَلَّ حمل النخل، بل كان على معتاده، فلما كانت سنة الخمسين لم يحمِل النخلُ إلا بنصفِ ح"},{"id":4474,"era":"c13","t":"وفاة فيصل بن وطبان الدويش رئيس مطير .","s":"هو فَيصلُ بن وطبان بن محمد الدويش الملقَّب بالأكوخ، شيخ قبيلة مطير. تولى المشيخة من عام 1205هـ. انضَمَّ مع القوات العثمانية بقيادةِ إبراهيم باشا في الاستيلاءِ على مدن القصيم والعارض وحصار الدرعية، وكان سببُ انضمامه قتل 12 رجلًا من شيوخ مطير وأقربائه من قِبَلِ عبد الله بن سعود، وكان له مراسلات عديدةٌ مع إبراهيم باشا"},{"id":4475,"era":"c13","t":"ظواهر غريبة في أفق نجد .","s":"قال ابن بشر: \"في ليلة الثلاثاء 19 جمادى الآخرة بعدما مضى نصفُ الليل تطايرت النجومُ في السماء كأنها الجرادُ، وكأنها شُعَل النار وقدح الزند من جميع جهاتِ السماء كلها شرقًا وغربًا، وشمالًا وجنوبًا، وصار فيها شهبٌ عظيمة تنقض وتضيء بالأرضِ، ويبقى موضع الشهاب ساعةً لا يزول، وانزعج الناس لذلك، واستمر إلى بعد اسفرارِ الصبحِ حتى ستره النهارُ، وأخبرني من أثِقُ به أنه رأى شهبًا تنقض بعدما طلعت الشمسُ يراها ك"},{"id":4476,"era":"c13","t":"مبايعة عبد القادر الجزائري بإمارة الجهاد .","s":"بويع القائِدُ الجزائري عبد القادر بإمارةِ الجهاد في بلاده، والتَفَّ حولَه كُلُّ المجاهدين، وقد دخل بعد ذلك مدينةَ تلمسان."},{"id":4477,"era":"c13","t":"الإمام تركي بن عبد الله يعتقل فلاح بن حثلين ويسجنه في الرياض .","s":"سار الإمامُ تركي بن عبد الله بجنودِه من جميع الرعايا من أهلِ نجدٍ باديها وحاضرها، وعدا على فلاح بن حثلين وعُربانه من العجمان وأخلاطِ مَن معهم من العربان، فسبق إليهم النذيرُ، فانهزم ابن حثلين ومن معه من منزلهم قربَ أم الربيعة، فنزل الإمام تركي في نفس المكان فرجع إليه المرضف شيخُ آل مرة وأتباعه، وصالحه على نفسه ومن تَبِعَه من العُربان، فلما عَلِمَ ابن حثلين بذلك داخَلَه الرُّعبُ، فركب قاصدًا تركيًا،"},{"id":4478,"era":"c13","t":"الإمام تركي بن عبد الله يحذر الأمراء والرؤساء من ظلم الرعية .","s":"لما رجع الإمامُ تركي من بعض غزواته وخرج من الدهناء ونزل غدير وثيلان، أمَرَ على رؤساء النواحي وأمرائهم أن يجتمعوا عنده، فلما حضروا قام فيهم مذكِّرًا بنعمة الاجتماع بعد الفُرقةِ، ثم أغلظ الكلام على الأمراء وتهدَّدهم وتوعَّدَهم عن ظلم الرعايا وقال: \" اسمَعوا يا أمراء البلدان، اسمعوا يا أمراء المسلمين، إياكم وظلمَ الرعايا والأخذ منهم غير الحقِّ، فإذا ورد عليكم أمري بالمغزى حملتموهم زيادةً لكم إياكم، و"},{"id":4479,"era":"c13","t":"توقيع اتفاقية \"كوتاهية\" بين محمد علي باشا والدولة العثمانية .","s":"تمَّ توقيعُ اتفاقية \"كوتاهية\" بين محمد علي باشا والدولة العثمانية بعد حروبٍ دامية بينهما، بتدخُّلٍ من روسيا وبريطانيا وفرنسا؛ للحِفاظِ على مصالحِهم، واتفق الطرفان على أن تتخلى الدولةُ العثمانيةُ لمحمد علي عن سوريا وإقليم أضنة، ونَصَّت المعاهدة على أن تتراجَعَ جيوش محمد علي عن إقليمِ الأناضول إلى ما بعد جبالِ طوروس، مع تثبيت محمَّد علي في ولاية مصر مدَّةَ حياته له ولنَسلِه، ويُعطى معها الشام وكريت "},{"id":4480,"era":"c13","t":"محمد علي ينشئ الدولة المصرية الحديثة .","s":"تمكَّن محمد علي أن يبنيَ في مصر دولةً عصرية على النَّسَق الأوروبي، واستعان في مشروعاتِه الاقتصادية والعِلميَّةِ بخبراء أوروبيين، ومنهم بصفة خاصة السان سيمونيون (أتباع سان سيمون الفيلسوف والاقتصادي الفرنسي) الفرنسيون، الذين أمضَوا في مصر بضعَ سنوات في الثلاثينيات من القرن التاسع عشر، وكانوا يَدعُون إلى إقامة مجتمع نموذجيٍّ على أساسِ الصناعة المعتَمِدة على العلم الحديث. وكانت أهمُّ دعائِمِ دولة محمد"},{"id":4481,"era":"c13","t":"أهل عسير يستولون على بلدة المخا في اليمن ويُخرجون الترك منها .","s":"سار أهلُ عسير وألمع وجنودُهم من أهلِ اليمن على بلدة المخا في اليمن، وقد أخذها التركُ ومَلَكوها، فلَبِسَ من عسير وأتباعهم قدرُ ألفي رجلٍ أكفانَهم وقصدوا أسوارَها وتسوَّروا جدرانها، وقُتِلَ كثيرٌ فوق السور، فلم يَثنِ عَزمَ الباقين، فأخذوا البلدَ عَنوةً من أيدي الترك وغنموا أموالًا لا تحصى."},{"id":4482,"era":"c13","t":"توقيع معاهدة \"خونكار أسكله سي\" بين الدولة العثمانية وروسيا. .","s":"عُقِدَت اتفاقيَّةٌ جانبية بين الدولة العثمانية وروسيا باسم (خونكار أسكله سي) تعهَّدت فيها روسيا بالدفاع عن الدولة ضِدَّ جيوش محمد علي أو أي معتدٍ آخر، وبذلك أصبح بإمكانِها التدخل في شؤون الدولة الخاصة وقتما تريد. وتُعتَبَرُ هذه المعاهدة قمةَ النفوذ الروسي في الدَّولةِ العثمانية والتي نَصَّت على: عقدِ تحالفٍ بين الدولة العثمانية وروسيا. عقدِ اتفاقية دفاعٍ مُشترك بين الدولة العثمانية وروسيا. مَنحِ ر"},{"id":4483,"era":"c13","t":"فشل القوات الفرنسية في اقتحام بلدة بليدة الجزائرية. .","s":"حاولت القواتُ الفرنسيّةُ في بداية الاحتلال الفرنسي للجزائر اقتحامَ بلدة بليدة الجزائرية، فقاوم سكانُها ذلك مقاومةً باسلة، بفَضلِ الله تعالى، وفَشِلَت القواتُ الفرنسية في مسعاها."},{"id":4484,"era":"c13","t":"انسحاب الجيش الروسي من رومانيا بعد احتلالها .","s":"انسحَبَ الجيش الروسي من رومانيا بعد خمسِ سَنواتٍ ونصف من احتلالها، وكانت رومانيا تَتْبَع في تلك الفترة الدولةَ العثمانية، لكِنَّ الروس احتلوها أثناءَ حَربِهم مع العثمانيين عام 1828م."},{"id":4485,"era":"c13","t":"معاهدة بين عبد القادر الجزائري والقائد الفرنسي دي ميشيل .","s":"وقَّع الأمير عبد القادر الجزائري مُعاهدةً مع القائد الفرنسي دي ميشيل، بوهران بعد اضطرار الفرنسيين للتحاوُرِ مع الأمير الذي أمر بمنعِ أي معاملةٍ تجارية مع الغزاة, وبحَسَبِ المعاهدة فإن فرنسا قد اعترفت بإمارةِ عبد القادر على الغَربِ الجزائري عدا وهران وأرزيو ومستغانم. لكِنَّ تطبيق المعاهدة واجهَ صعوباتٍ عدة، وكان من نتائِجِها وقفُ القتال بين الطرفين، والقيامُ بتبادُلِ الأسرى بينهما."},{"id":4486,"era":"c13","t":"وفاة الإمام تركي بن عبد الله بن سعود وتولي ابنه فيصل الحكم من بعده .","s":"هو الإمامُ تركي بن عبد الله بن محمد بن سعود بن محمد بن مقرن، من أمراءِ نجد، وَلِيَها بعد مقتل ابنِ عَمِّه مشاري بن سعود. كان تركي بن عبد الله فارًّا من وجه التُّرك وعُمَّال والي مصر محمد علي، في الخَرجِ بنجد، وعلم بأنَّ مشاري بن معمر قبض على ابنِ عَمِّه مشاري وسَلَّمه إلى الترك فقَتَلوه، فخرج من مخبئه ودخل العارضَ فنازع ابن معمر برهةً مِن الزمن، ثم قتَلَه بابن عمه، وتولى الحكمَ مكانه. وبولايةِ ترك"},{"id":4487,"era":"c13","t":"العساكر المصرية مع شريف مكة تغزو عسير  .","s":"سارت العساكِرُ المصرية وملأت السَّهلَ والجبل لمحاربةِ عسير في بلدان اليمن، ومعهم أحمد باشا وشريف مكة محمد بن عون، فلمَّا وصلوا بلادهم أرسلوا إليهم أنَّهم ما يريدون منهم إلَّا رسمَ الطاعة، وأنهم ما أتوا إلا للصلاحِ، فأطاع لهم عسير، وجعلوا في ثغورِ بلادهم عسكرًا، فلما تمكَّنوا من بلادهم طلبوا منهم أموالًا ونِساءً، فأجمع رأيُ رؤساء عسير أن يجمَعوا شوكَتَهم وعَدَدَهم وعُدَّتَهم، وينفرون عليهم ويسيرون "},{"id":4488,"era":"c13","t":"فيصل بن تركي يقتل مشاري بن عبد الرحمن ويسترد الحكم منه .","s":"لما بلغ فيصلًا خَبَرُ مقتل والده، جمع الأمراء والرؤساء الذين معه في الغزو، وهم رئيس جبل شمر: عبد الله بن علي بن رشيد، ورئيس بريدة: عبد العزيز بن محمد، ورئيس الحريق: تركي الهزاني، وحمد بن يحي أمير بلدان سدير، وغيرهم من الرؤساء والرجال، ورؤساء العربان، أخبَرَهم بمقتل والده فوعَظَهم وذكَّرَهم، فبايعوه جميعًا على السمعِ والطاعةِ، ثم رحل مِن الأحساء بجنوده وأمرائِه إلى الرياض فدخلها وحاصَرَ مشاري في قص"},{"id":4489,"era":"c13","t":"وفاة الشاه فتح الله شاه زعيم القاجاريين في إيران .","s":"هو الشاه فتح علي شاه قاجار زعيم القاجاريين الشيعة في إيران. ولِدَ سنة 1772 وكان فتح علي ثاني شاه قاجاري على فارس. وقد حكم من 17 يونيو 1797 حتى وفاته. وقد شَهِدَ عهده فقدانَ إيران بالقوة -وبغير رجعة- أراضيَها الشمالية؛ الأراضي القوقازية التي تضمُّ جورجيا، داغستان، أذربيجان، أرمنيا، لصالح روسيا القيصرية إثرَ الحرب الروسية الفارسية (1804-1813)، الحرب الروسية الفارسية (1826-1828) والمعاهدتين اللتين أُ"},{"id":4490,"era":"c13","t":"وفاة الشيخ حسن بن محمد العطار شيخ الجامع الأزهر .","s":"هو الشَّيخُ علَّامةُ مِصرَ: أبو عليٍّ حسن بن علي محمد بن محمود العطار، شيخ الجامع الأزهر، وهو الشيخ السادس عشر في سلسلة شيوخ الأزهر، أصله من المغرب. ولد بالقاهرة سنة 1180 هـ، كان أبوه الشيخ علي محمد العطار فقيرًا يعمل عطَّارًا، من أصل مغربي، وكان له إلمامٌ بالعلم، وكان حسن يساعِدُه في دكانه، ولَمَّا رأى منه حبًّا للعلم وإقبالًا على التعَلُّم، شجعه على طلب العلم،، كان طويلًا بعيدَ ما بين المنكِبَين"},{"id":4491,"era":"c13","t":"وصول الحملة التي أعدها محمد علي باشا إلى ينبع .","s":"كان محمد علي باشا والي مصر يعمَلُ على تكوين دولة كبرى على حسابِ الدولة العثمانية، فضَمَّ السودان والشام وأجزاءً من بلاد اليونان والأناضول إلى سيطرته. وكان يَعُدُّ شبهَ جزيرة العرب من المناطق التابعة لدولته؛ ولهذا لم يكن غافلًا عما يجري في نجد من حركة لإعادة الدولة السعودية. ووجد أنَّ مِمَّا يسهل عَمَلَ الحملات العسكرية أن يترأَّسَها أحدُ أفراد الأسرة السعودية. وأراد محمد علي باشا التخاطبَ مع الإما"},{"id":4492,"era":"c13","t":"الشيخ عبد الله أبا بطين ينتقل قاضيًا لأهل القصيم بطلب أهلها .","s":"طلب رؤساءُ القَصيمِ مِن الإمام فيصل أن يبعَثَ إليهم الشيخَ عبد الله بن عبد الرحمن أبا بطين قاضيًا في بلدانهم، كمدرِّس لطلبة العلم في أوطانِهم، فأمر عليه الإمام فيصل وهو في بلد شقراء قاضيًا لأهل الوشم أن ينتَقِلَ إلى القصيم، فقَدِمَ عُنَيزة وأقام فيها، ثم طلبوا نزولَه عندهم وانتقاله إليهم بأهله، فانتقل بعياله عندهم واستوطن عُنيزة، فأكرموه غاية الإكرام وعظَّموه بما يستحِقُّه من الإعظام، فاجتمع عنده "},{"id":4493,"era":"c13","t":"عبد القادر الجزائري ينتصر على الفرنسيين  في معركة المقطع  .","s":"أعلن عبد القادر الجزائري الجهادَ ونظَّم حُكمَه، فكان بمثابةِ رئيس للوزراء وله نائب ووزراء، واتخذ من مدينةِ المعسكر قاعدةً له، واتَّصل بمن بقي من العثمانيين، فأعلنوا السَّمعَ والطاعة، ثم بويع أميرًا للجهاد في جمادى الآخرة 1248هـ / تشرين الثاني 1832م، ثم قَوِيَ أمره حتى جرت بينه وبين الجنرال دي ميشيل معاهدة بتاريخ 17 شوال 1249هـ / 26 شباط 1834م لوقف القتالِ، وإطلاق سراح الأسرى، وحرية التجارة، واحترا"},{"id":4494,"era":"c13","t":"قحط وغلاء الأسعار في نجد .","s":"قَلَّ المطَرُ وغَلَت الأسعار، فصار البُرُّ سِتةُ أصواعٍ وخمسة بريال فرنسي، والتمر خمسة عشر وزنة، وأصاب الناسَ مجاعةٌ، وجلا كثيرٌ من أهل سدير للزبير والبصرة، ولم يأتِ من السيل إلا قليلٌ في الصيف، وكان هذا الغلاء والقحط وقع بعد قتلِ الإمام تركي، وعلى وجه إقبال خالد بن سعود مع العسكرِ المصري."},{"id":4495,"era":"c13","t":"فيصل بن تركي يغزو القبائل التي تمتنع عن دفع الزكاة .","s":"سار الإمامُ فيصل بن تركي بجنودٍ مِن العارض والخرج والفرع والأفلاج ووادي الدواسر والقصيم والجبل والوشم وسدير وغيرهم وجميع غزوان العربان، فنزل روضة التنهات المعروفة عند الدهناء، وأقام فيها أكثَرَ من شهرين؛ وذلك لأنه بلَغَه أنَّ بعض العربان فيهم امتنعوا عن الزكاة، فإذا سمعوا بخروجه سَمِعوا وأطاعوا، فوفد عليه رؤساءُ العربان، وأرسل إليهم عمالًا، لكلِّ فريقٍ عامِلُه، فقبضوا منهم الزكاة، وألفى عليه أخوه "},{"id":4496,"era":"c13","t":"عقد أول هدنة بحرية بين رؤساء المشيخات والإمارات العربية في الخليج العربي .","s":"كانت الملاحة في الخليج العربي قد اضطربت لمدة سنتين بدءًا من عام 1249هـ؛ وذلك بسبَبِ الصراع بين مشيختي الشارقة وأبو ظبي، ثم بسبب الاضطرابات الداخلية في مشيخةِ أبو ظبي، وكان لتلك الاضطرابات أكبَرُ الأثر في حياة القواسم وبني ياسر، وهما أكبَرُ قبيلتين بحريتين في ساحل الصلحِ البحري، فتوقفت أعمالُ الغوص لصيد اللؤلؤ، وساءت أحوالُهم المعيشية إلى حدٍّ كبير، فكان هذا هو العامِلَ الرئيسي الذي مهَّد لعقد أول "},{"id":4497,"era":"c13","t":"أمير القطيف وسيهات يبايعان الإمام فيصلًا .","s":"بعث الإمام فيصل زويد العبد ومعه 100 مطية من الركاب ناحيةَ القطيف، فأمر فيه ونهى، وعزل رجالًا وثَبَّت رجالًا، ووفد ولدُ أمير القطيف ابن غانم وابن عبد الرحيم أمير سيهات على الإمام فيصل، وبايعاه على السَّمعِ والطاعة."},{"id":4498,"era":"c13","t":"ظهور الحركة الأندلسية في أسبانيا .","s":"رفضت المدُنُ الأندلسيَّةُ أن ترضخَ لمطالبِ السياسيِّ الليبرالي منديزابال: \"بأن تقومَ الدولةُ ببيعِ ممتلكاتِ الكنيسةِ ومُصادرتِها، كحَلٍّ لمشاكِلِها الماليةِ في أسبانيا\"، وتوحَّدت مناطِقُ الأندلس عبر \"مجلس أعلى للثورة\" مقرُّه بلدةُ أندوجر (مقاطعة جيان) يمثِّل جميعَ الأندلس عبر ممثِّلينَ من جميعِ مقاطعاتِها. وانتخَبَ المجلسُ الكوندي دي دوناديو -مثِّل مدينة جيان- رئيسًا له، وأرسل إنذارًا للحكومةِ في "},{"id":4499,"era":"c13","t":"سيادة ليبيا على البحر المتوسط في عهد أسرة قره مانلي .","s":"كانت ليبيا في عهد أسرة القره مانلي تمتلك أسطولًا بحريًّا قويًّا مكَّنَها من أن تتمَتَّعَ بمكانة دولية مَهيبة، وأصبحت تنعَمُ بنوعٍ مِن الاستقلال. فأسَّس أحمد القره مانلي أسرةً حاكمة استمرَّت في حكم ليبيا حتى هذا العام، ويعتبر يوسف باشا القره مانلي أبرزَ ولاة هذه الأسرةِ."},{"id":4500,"era":"c13","t":"ظهور الدعوة السنوسية في شمال أفريقيا .","s":"كان مؤسِّسُ الدعوة السنوسية محمد بن علي المعروف باسم السنوسي الكبير في الجزائر حين دراستِه في فاس تأثَّر كثيرًا بالحركة الصوفية هناك، وخاصة أولئك الذين ينتَمون إلى الطريقة التيجانية، والتحَقَ فيما بعد بجماعاتٍ متعددة من المتصوَفِّة حين كان يدرُسُ في الحجاز على الشيخِ الإدريسي، وكان يحمِلُ أفكارًا إصلاحيَّةً وتجديدية، فقام بإيجاد طريقة صوفية خاصةٍ به حين كان في مكَّةَ، أطلق عليها اسمَ السنوسية، وكا"},{"id":4501,"era":"c13","t":"مقتل محمد ابن وطبان رئيس الزبير .","s":"هو الأميرُ محمد بن إبراهيم بن ثاقب بن وطبان أمير الزبير، كان من أعظَمِ أهلِ ناحيته عقلًا ومعرفةً ودهاءً، وكان متحفِّظًا على نفسه، يعرِفُ الحِيَل ويخافُ منها، وكانوا يسمونه \"البلم يغرق غيره ويَسلَم\" كان أبوه إبراهيمُ أمير الزبير، فلما مات صار مكانَه، فحصل بينه وبين آل زهير وأهلِ حرمة الجالين في الزبير ضغائِنُ عظيمة، فأخرجوه بسببها من الزبير، فانتقل مع أهله وعياله ونزل بلد الكويت، ثم عاد لحُكمِ الزب"},{"id":4502,"era":"c13","t":"تحرك الإمام فيصل بن تركي من الرياض لملاقاة القوات المصرية .","s":"حاول الإمام فيصل أن يتفادى الصدامَ مع القوة المصرية الموجَّهة إليه؛ إذ لا قِبَلَ له بها. فأرسل الهدايا مع مبعوثٍ منه إلى قائدَيها خالد بن سعود وإسماعيل بك، إظهارًا لحُسن نيته. ولما عاد المبعوث أطلع الإمامَ على نيات محمد علي باشا في مهاجمةِ البلاد. وواصلت الحملةُ تقَدُّمَها من المدينة النبوية إلى الحناكية، وكان الإمامُ فيصل لما بلغه مسيرُ العساكر المصرية بقيادة إسماعيل بك وخالد بن سعود، استشار رؤسا"},{"id":4503,"era":"c13","t":"إنشاء أول وزارة للمعارف في مصر والعالم العربي باسم ديوان المدارس .","s":"تم إنشاءُ أوَّلِ وَزارة للمعارفِ في مصرَ والعالم العربيِّ، باسم ديوان المدارس، وقد تولى رئاستَها مصطفى مختار باشا، الذي كان أحد أعضاءِ البعثة العلمية الأولى التي أرسلها محمد علي باشا إلى فرنسا."},{"id":4504,"era":"c13","t":"مواجهة الإمام فيصل العساكر المصرية في القصيم .","s":"نزل الإمامُ فيصل بجنودِه على ماء الصريف من أرضِ القصيمِ، فأقام عليها أكثَرَ مِن شهر حتى بلغه أنَّ خالد بن سعود وإسماعيل بك وعساكِرَهم نزلوا الرسَّ، فرحل الإمام ونزل عُنَيزة، واستنفر أهلَها، فركب معه أميرُها يحيى بن سليمان، ورئيسُ بريدة عبد العزيز بن محمد، ونزل في رياض بلد الخبرا بين الرس والخبرا، فأقام فيها عشرين يومًا، وهو ملازم  عسكر الترك في الرس ومحاربٌ لهم، ولكن لم يحصُلْ بينه وبينهم قِتالٌ، "},{"id":4505,"era":"c13","t":"خروج الإمام فيصل من الرياض وانتقاله للأحساء .","s":"لما دخل الإمامُ فيصل الرياضَ بعد عودتِه من القصيم، رأى من بعض أهلِها ريبةً، وجاهر بعضُهم بالعداوةِ، فعمل فيصل على جمعِ أمواله وأهله وخيله والنجايب، وخرج بهم من الرياض إلى الخَرج، فأقام بها عشرة أيام حتى استلحق باقي أهله وشيء من متاعه وعَدَد من رجاله وعبيده، ثم قصد الأحساءَ، فلما وصلها استقبلها أميرُها مِن قِبَلِه عمر بن عفيصان ورؤساؤها وبايعوه على النصرةِ والقيام معه، ونزل قصر الكوت بعياله وأثقالِ"},{"id":4506,"era":"c13","t":"خورشيد باشا يستدرج الإمام فيصل .","s":"أرسل محمد علي باشا حملةً عسكريةً بقيادة واحد من أمهرِ قادته العسكريين، وهو خورشيد باشا. وكان أوَّل ما فعله خورشيد وهو في طريقه إلى نجد أن أرسل رسالةً وهدايا إلى الإمام فيصل بن تركي مع الشريف عبد الله، صاحب ينبع، وأذِنَ للإمام أن يأخُذَ ما أراد أخْذَه من ممتلكاته الموجودة في الرياض، ووعده بالتقريرِ في مُلكِه، ولا عليه مُنازِع، وربما كان قصد خورشيد باشا من هذا الوعد هو أن يبقي الإمام فيصلًا حاكِمًا "},{"id":4507,"era":"c13","t":"عبد الله بن علي بن رشيد يستعيد حكمه لجبل شمر .","s":"أقبل عبدُ الله بن علي بن رشيد رئيس جبل شمر ومعه من أعوانه وعشيرته رجالٌ؛ لمحاربة عيسى بن علي، ونزل عند بني تميم في بلد قفار المعروفة في حائل، وأقام عندهم، ثم سطا على عيسى بن علي وأخرجَه مِن قَصرِه ومن البلد، وقتل رجالًا ونهب أموالًا."},{"id":4508,"era":"c13","t":"خالد بن سعود يدخل الرياض يطلب البيعةَ له .","s":"رحل خالد بن سعود وإسماعيل بك وعساكِرُ الترك من القصيمِ إلى الرياض ودخلوها يوم السبت 7 صفر، ودخل خالد وإسماعيل القصرَ واستوطنوه ونزل العسكرُ خارج الرياض، وقَدِمَ عليهم رؤساء البلدان وتابعوهم، وأرسلوا إلى الهزاني ورؤساء أهل الحوطة يطلبون منهم المتابعةَ والقدومَ إليهم، فأبوا عليهم، وكتبوا لخالد إن كان الأمرُ لك ولا يأتينا في ناحيتِنا عسكرٌ مِن الترك فنحن رعيَّةٌ لكم، وإن كان الأمر للتركِ فنحن لهم محا"},{"id":4509,"era":"c13","t":"توقيع الأمير عبد القادر الجزائري معاهدة تافنة مع الفرنسيين .","s":"نجح الأميرُ عبد القادر الجزائري في إحراز نصرٍ على القائد الفرنسي الجنرال \"بيجو\" في منطقة \"وادي تفنة (أو تافنة) \"، الأمرُ الذي أجبر القائدَ الفرنسي على عقدِ معاهدة هدنة جديدةٍ عُرفت باسم \"معاهدة تافنة\"، وعاد الأميرُ عبد القادر بعدها لإصلاحِ حالِ بلادِه وترميمِ ما أحدَثَتْه المعارك بالحصون والقلاع، وتنظيم شؤونِ البلاد، لكِنَّ الفرنسيين نقَضوها عام 1839م."},{"id":4510,"era":"c13","t":"إصدار فرنسا قانونا يخضع القبائل الجزائرية للإجراءاتِ الفرنسية .","s":"أصدرت فرنسا قانونًا أخضَعَت به أراضيَ القبائل الجزائرية لإجراءاتِ القوانينِ الفرنسية، وهو ما سهَّل للفرنسيين الاستيلاءَ على تلك الأراضي."},{"id":4511,"era":"c13","t":"هزيمة جيش خالد بن سعود قرب بلدة الحلوة .","s":"بعد سَيرِ القوات المصرية نحوَ الرياض وجدت التشجيعَ مِن سكَّانها الذين قَدِمَ منهم وفد؛ ليعلن ولاءَهم للجيش المصري، وفر منها المعارِضون من آلِ الشيخ إلى جهات الحلوة والحريق وحوطة بني تميم في جنوبي نجد. فأراد خالد بن سعود أن يُخضِعَ المناطِقَ الجنوبية من نجدٍ بالقوة، بعد أن رفضت طاعتَه، فكتب خالد إلى أمراء سدير والمحمل والوشم وبلدان العارض بالنفير معه لقتالِ مناطق الجنوب، فخرجوا جميعًا إلَّا أمير سد"},{"id":4512,"era":"c13","t":"محاصرة الإمام فيصل بن تركي مدينة الرياض .","s":"لما هُزِمَ خالد بن سعود في بلدة الحلوة، سارع الإمام فيصل بن تركي من الأحساء إلى الخَرج، وانضم إليه أهلُ الخرج والحوطة والحريق والفرع الذين هزموا خالدًا. وانطلق بهم نحوَ الرياض، وحاصرها. ولكنه اضطرَّ إلى فَكِّ الحصار والتراجع نحو منفوحة في شعبان من هذه السنة أيضًا، وذلك بعد أن زحفت حشودٌ من قبيلة سبيع بقيادة فهيد الصييفي، ومن قبيلة قحطان بقيادة قاسي بن عضيب؛ لنجدة خالد بن سعود. فشنُّوا الغارة على ا"},{"id":4513,"era":"c13","t":"علي باشا والي العراق يستولي على بلد المحمرة .","s":"سار علي باشا والي العراق من بغداد بعساكِرَ عظيمة، قيل إنهم 70 ألفًا من عقيل وغيرهم، وقصد بلد المحمرة المعروفة عند البصرة، واستلحق  أهل الزبير وساروا معه، فنزل المحمرة وحاصرها وأخذها عَنوةً، ونهَبَها وأخذوا منها من الأموالِ ما لا يُعَدُّ ولا يحصى."},{"id":4514,"era":"c13","t":"الحرب الأفغانية البريطانية الأولى  .","s":"حربٌ دارت بين الراج البريطاني (الحكم البريطاني في الهند) والشعب الأفغاني المسلِم من سنة 1838م إلى سنة 1842م حين غزت بريطانيا أفغانستانَ لاحتلالها بهدف إنشاء دولة عازلة بين إمبراطوريتهم وروسيا القيصرية، لكِنَّ الحرب انتهت بانتصار حاسم للأفغان؛ حيث سُحِق فيها مُعظَمُ الجيش البريطاني."},{"id":4515,"era":"c13","t":"توقيع معاهدة بلطة ليمان بين الدولة العثمانية، والمملكة المتحدة .","s":"كانت معاهدة بلطة ليمان معاهدةً تجارية وُقِّعَت بين الدولة العثمانية والمملكة المتحدة لبريطانيا العظمى وأيرلندا؛ لتنظيم التجارة الدولية. وتمَّ تحديد الرسوم لتكون 5 % على الواردات، و12 % على الصادرات، و3 % على البضائع المارة (ترانزيت). كما وافق العثمانيون على إلغاء جميع الاحتكارات. ففي عام 1831 قاد إبراهيم باشا بن محمد علي باشا حملةً عسكريةً ناجحةً في بلاد الشام، منَصِّبًا نفسَه حاكمًا، وبدأ في عَصْ"},{"id":4516,"era":"c13","t":"استسلام الإمام فيصل بن تركي لقوات خورشيد باشا .","s":"وصلت حملةُ خورشيد باشا إلى الرياض في رجب من هذه السنة، وطُلِب من الإمام فيصل بن تركي -الموجود في الدلم- الاستسلام، وإلا فإنه سيواجِهُ الحرب، ولما رفض الإمام فيصل الإنذار، وقع القتالُ بين الطرفَين في معركة الخراب، في جهة الدلم، وتغلبت فيه قواتُ خورشيد باشا على الإمام فيصل وأتباعه. وانتهى الأمرُ باستسلام فيصل بن تركي في رمضان من هذا العام، بعد أن حصل على الأمان للبلدة. وفي اليوم الثاني من شوال أُخِذ"},{"id":4517,"era":"c13","t":"احتلال بريطانيا مدينة عدن .","s":"لقد كانت عدن محطَّ أنظار كثيرٍ مِن الدول الطامعة في إرساء قواعدَ لها على البحر الأحمر والخليج العربي، ومن ثَمَّ السيطرة على المحيط الهندي، والحصول على السيطرة الاقتصادية والسياسية في تلك المنطقة، فتوالت على عدن الكثيرُ مِن القوات والدول المستعمرة، وكان من أهمِّ تلك الدول بريطانيا؛ حيث قامت ببعض المقَدِّمات لاحتلالِ عدن، فأرسلت في بداية الأمر الكابتن هينز أحدَ ضباط البحرية إلى منطقةِ خليج عدن في عا"},{"id":4518,"era":"c13","t":"مصر ترفض معاهدة لندن فيفصل الأوروبيون بينها وبين الشام .","s":"كانت معاهدةُ خونكار أسكله سي بين روسيا والدولةِ العثمانيةِ بمثابةِ تحالُفٍ دفاعيٍّ بين روسيا والعثمانيين؛ مما أدى إلى مسارعة كلٍّ مِن بريطانيا وفرنسا بالتصدِّي لمحمد علي خشيةَ المزيد من التدخُّلِ الروسي، وفرضت عليه اتفاقيَّةَ لندن سنة 1255هـ / 1840م. وقد ترتَّب على هذه الأحداث إجهاضُ محاولة الإصلاح التي حاول السلطانُ محمود الثاني أن يقومَ بها في الدولة العثمانية، واضطرت الدولةُ العثمانيةُ لقبولِ و"},{"id":4519,"era":"c13","t":"خلع الأمير فيصل بن تركي وتولية خالد بن سعود في نجد .","s":"كان الإمام فيصل بن تركي تولَّى حكم نجدٍ بعد مقتل أبيه، وتمكَّنَ من إخضاعِ أكثَرِ الإمارات ما عدا الحجاز، وعَيَّن عبد الله بن رشيد أميرًا على حائل، فلمَّا انزعج محمد علي حاكِمُ مصر أرسل حملةً احتَلَّت نجدًا وقبضت على الإمام فيصل بن تركي، ثم أُرسِلَ إلى مصر خلال هذه السنة، وأقامت الحملةُ خالدَ بنَ سعود بن عبد العزيز بن محمد -الذي تربَّى في مصر- حاكِمًا لنجد، وكانت غايةُ محمد علي باشا تفريقَ الأسرة ا"},{"id":4520,"era":"c13","t":"موافقة الدولة العثمانية على منح اليونان حكمًا ذاتيًّا  .","s":"وافقت الدولةُ العثمانيَّةُ على قَبولِ معاهدةِ لندن والتي أقرَّتْها الدولُ الأوربية الكبرى، وقد نصَّت هذه المعاهدةُ على تأسيسِ إمارة يونانية تكونُ مستقلَّةً ذاتيًّا ومرتبطة بالعثمانيين، وتقوم بدفعِ الضرائب للسلطان العثماني."},{"id":4521,"era":"c13","t":"انسحاب الإنجليز من كابل والاعتراف بمحمد دوست حاكمًا لبلاد الأفغان .","s":"كان الراج بريطاني -راج، يعني: الحكم- دخل كابل عام 1218 ويمثِّلُ هذا الدخولُ الحربَ الأفغانية الإنجليزية الأولى، التي انتصر فيها الأفغان. كان هدف بريطانيا هو إنشاءَ دولة في أفغانستان عازلة بينها وبين روسيا عندما ساعدت شجاع الملك في استعادة حُكمِ كابل مِن أخيه فتح خان، وفي هذا العام فرَّ أخوه محمد دوست إلى بخارى، فحاول أن يهاجِمَ بلاد الأفغان من جهةِ الشمال غير أن هجماتِه فَشِلت، فجاء إلى الأفغان وس"},{"id":4522,"era":"c13","t":"ظهور دعوة أغاخان (الإسماعيلي) بالهند .","s":"ظهر في إيران رجلٌ شيعي إسماعيلي اسمُه حسن علي شاه، وجمع حولَه عددًا كبيرًا من الإسماعيليَّةِ وغيرهم، فأرهبوا القوافل، وهاجموا القرى حتى ذاع صيتُه، وقَوِيت شوكته، وخَشِيَته الأسرة القاجارية الشيعية الحاكمةُ في إيران، فأُعجِبَ الناس بقوته، وانضموا تحت لوائِه؛ طمعًا في المكاسب المادية التي وعدهم بها، وكان الإنجليزُ في ذلك الوقت يعملون على بَسطِ الثورة ضِدَّ شاه إيران. وقام الإسماعيلي حسن علي بالثورة "},{"id":4523,"era":"c13","t":"تجدد القتال بين قوات محمد علي باشا وبين العثمانيين .","s":"حدَثَت ثوراتٌ في بلاد الشام ضِدَّ حُكمِ إبراهيم باشا فأخضَعَها بكُلِّ شِدَّةٍ، فهدأت، وفاتَحَ محمد علي وكلاءَ الدول الأوربية في مصرَ بأنه يريد ولايةَ مصر والشام وجزيرة العرب له ولأولاده من بعدِه، ونُقِلَت هذه الرغبات إلى الدولة العثمانية التي أرسلت له مندوبًا اتَّفَق معه على أن تكون مصرُ وجزيرة العرب مِلكًا متوارثًا لأسرة محمد علي باشا وبلاد الشام لمحمد علي مدَّةَ حياتِه، وأما جبال طوروس فتكون كُل"},{"id":4524,"era":"c13","t":"وفاة السلطان العثماني محمود الثاني وتولي ابنه عبد المجيد الأول .","s":"هو الخليفةُ العثماني السلطان محمود خان الثاني بن عبد الحميد الأول بن أحمد الثالث بن محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول بن بايزيد الثاني. تولى السلطنةَ في 20 يوليو 1785م، وكان السلطان الثلاثين للدولة العثمانية، شَهِدَ عَصرُه خطواتِ إصلاحٍ واسِعةً، وقد اتَّسم عهدُه بالتوجه للغرب العلماني، وهو الذي أمَرَ محمد علي با"},{"id":4525,"era":"c13","t":"السلطان العثماني عبد المجيد الأول يصدر أول دستور للبلاد .","s":"لما تسلَّم السلطان عبد المجيد الأول بن محمود الثاني الحُكمَ، وهو ما يزال دون الثامنةَ عشرة من عمرِه، كان صِغَرُ سِنِّه هذا فرصةً لبعض الوزراء التغريبيين لإكمال ما بدأه والِدُه الراحل من إصلاحاتٍ على الطريقة الأوروبية، والتمادي في استحداثِ الوسائل الغربية، ومن هؤلاء الوزراءِ الذين ظهروا في ثيابِ المصلحين ومُسوحِ الصادقين (مصطفى رشيد باشا) الذي كان سفيرًا للدولة في (لندن) و (باريس)، ووصل إلى منصِبِ "},{"id":4526,"era":"c13","t":"وفاة الإمام العلامة بدر الدين الشوكاني .","s":"هو الإمامُ العلَّامةُ بدرُ الدين محمد بن علي بن محمد بن عبد الله بن الحسن بن محمد بن صلاح بن إبراهيم بن محمد العفيف بن محمد بن رزق، ينتهى نسَبُه إلى خيشنة الشوكاني نِسبةً إلى شوكان من بلاد خولان باليمن، وهو أحدُ أبرز عُلَماءِ أهل السنة والجماعة وفقهائِها، ومِن كبار علماء اليمن، ولِدَ في هجرة شوكان يوم الاثنين 28 من ذي الحجة سنة 1173 هـ بصنعاء، وتولى قضاءها، برعَ في الفقه والحديث والأصول والتفسير، "},{"id":4527,"era":"c13","t":"اتفاق إنجلترا وبعض دول أوربا بشأن محمد علي باشا وإجلائه من الشام .","s":"كانت فرنسا توَدُّ أن تدعَمَ محمد علي باشا وأن يحتفِظَ بما أخضعه من مناطِقَ، ولكِنَّ إنجلترا لا تريد ذلك؛ لمنافسة فرنسا على مركزها في مصر، وخوفًا من منافَستِها على طريق الهند، وأما النمسا وبروسيا فتريان في قوة محمد علي خطرًا على أوربا خشيةَ أن يسيطرَ على الدولة العثمانية فيفَكِّرَ في إعادة ما كانت عليه، ولقد تمَّ عقد اتفاقية عام 1256هـ بين إنكلترا وروسيا والنمسا وبروسيا بعد انسحاب فرنسا ومحاولة اتف"},{"id":4528,"era":"c13","t":"تحرر فلسطين من الاحتلال الفرنسي الذي فرض عليها من نابليون  .","s":"وقعت فلسطينُ تحت الاحتلال الفرنسي في عام 1799م/1214هـ حين توجَّه نابليون بونابرت على رأس جيشٍ فرنسي قوامه 13000 جندي بحملةٍ عسكرية نحو فلسطين, هدفُها احتلال فلسطين والشام وإخضاعها للسيطرة الفرنسية، ومِن ثمَّ القضاء على السلطنة والإمبراطورية العثمانية في اسطنبول, فاحتلَّ العديد من المدن الفلسطينية وارتكب نابليون مجزرةً؛ حيث قتل فيها أكثر من 12000 أسيرٍ عربيٍّ، ثم أصيب جيش نابليون بداءِ الطاعون، ورغ"},{"id":4529,"era":"c13","t":"تأسيس حاكم تونس أحمد باي مدرسة باردو العربية .","s":"أسَّس أحمد باي حاكِمُ تونس مدرسةَ باردو العربية التي تعتبَرُ أول مدرسة عصرية لتخريج الضباطِ والفنيين لجيشه النظامي، وجعل الباي مقرَّ المدرسة في سرايته، وانتقل هو إلى قصرٍ آخر، وجلب لها أساتذةً وضباطًا أوربيين، واستمرت في العمل لمدة 24 عامًا."},{"id":4530,"era":"c13","t":"دخول الجيش العثماني مدينة حلب .","s":"استطاع الجيش العثماني الدخولَ إلى مدينة حلب في سوريا، وذلك بعد طردِ الجيش المصري بقيادة إبراهيم باشا من بلاد الشام، وذلك بعد معاهدة لندن في يوليه 1840م، والتي نصَّت على إخلاء والي مصر محمد علي باشا لبلاد الشام، وعودة الدولة العثمانية للسيطرةِ عليها."},{"id":4531,"era":"c13","t":"بداية الحروب الطائفية في لبنان  .","s":"شرعت فرنسا وإنجلترا تُثير الفِتَن الطائفية من عام 1256هـ/ 1841م بين الأقليات غير المسلِمة في لبنان، والهَدفُ هو إنهاك قوة الدولةِ العثمانية التي أرسلت قواتٍ لإنهاء الفتنة، وكذلك إيجادُ المبرر للتدخُّل الفرنسي والبريطاني في لبنان؛ تمهيدًا لتمزيقِه واحتلالِه."},{"id":4532,"era":"c13","t":"حكم آل ثنيان لنجد وانسحاب القوات المصرية منها .","s":"ظهر عبدُ الله بن ثنيان بن إبراهيم بن ثنيان بن سعود بن محمد بن مقرن بن مرخان بن إبراهيم بن موسى بن ربيعة بن مانع بن ربيعة المريدي، على مسرحِ الأحداث التاريخية في نجدٍ بعد غزوة البياض التي رافق فيها خالدُ بن سعود ضِدَّ آل شامر من هذه السنة. وكان خالد بن سعود حريصًا على مراقبةِ تحرُّكات عبد الله بن ثنيان؛ لأنه ظَلَّ يشُكُّ في نواياه تجاهه. وعندما قرر خالد بن سعود التوجُّهَ إلى بلدة الشنانة ليودِّعَ خ"},{"id":4533,"era":"c13","t":"انسحاب القوات المصرية من القدس وعودتها للسيادة العثمانية .","s":"انسحبت القواتُ المصرية من القُدسِ، وذلك بناءً على معاهدة لندن في العام الماضي 1256هـ، والتي قلَّصَت الدور المصري في الشام؛ مما أدى بالقوات المصرية إلى الانسحابِ منها، ورجوعها للسيادة العثمانية مرةً أخرى."},{"id":4534,"era":"c13","t":"إصدار السلطان العثماني \"فرمان مصر\" .","s":"أصدَرَ السلطان العثماني \"فرمان مصر\" الذي نصَّ على إعطاء محمد علي باشا ولاية مصر والسودان وراثيًّا، وقد بَقِيَ هذا الفرمان مرعيًّا في مصر كدستور حتى نهاية عام 1914م حين أُعلِنَت الحمايةُ البريطانية على مصر."},{"id":4535,"era":"c13","t":"معاهدة المضائق وإلغاء معاهدة خونكار اسكله سي  .","s":"بدأت إنكلترا وفرنسا تعملان لإلغاء المعاهدة الدفاعية بين روسيا والدولة العثمانية خونكار اسكله سي، التي تقضي بمرورِ السفن الروسية من المضائقِ العثمانية في الوقتِ الذي تشاء ودون تفتيشِ سُفُنِها، وقد استطاعت الدولتان فرنسا وإنكلترا الاتفاقَ مع الدول الأخرى -بما فيها روسيا- على أن تبقى المضائِقُ مُقفَلةً أمام جميع الدول بلا استثناء، ووُقِّعت المعاهدة التي عُرِفت بمعاهدة المضائق في 23 من جمادى الأولى من"},{"id":4536,"era":"c13","t":"وقوع معركة بقعاء بين زعماء القصيم وعبد الله بن رشيد وأتباعه .","s":"حدثت معركةُ بقعاء بين زعماء القصيم وجبل شمر، وملخَّصُها أن غازي ضبيان رئيسُ الدهامشة من عنزة أغار على ابن طوالة من شمر، فأخذ منهم إبلًا وأغنامًا لأهل حائل، فأغار عبد الله بن علي بن رشيد رئيس الجبل على غازي فأخذ منهم إبلًا كثيرةً، فغضب لهم أميرُ بريدة؛ لأن غازيًا من أهل القصيم، فنادى أمير بريدة في حرب ابن رشيد، وكان أهل القصيم قد اتَّفَقوا فيما بينهم لمحاربة كلِّ من يقصدهم بعداوة مهما كانوا، وأجمعو"},{"id":4537,"era":"c13","t":"محاصرة دير القمر والإيذان ببدء الحرب الأهلية الأولى في لبنان .","s":"بادرت القواتُ الدرزية بزعامة أولاد بشير جنبلاط إلى محاصرة \"دير القمر\"؛ إيذانًا ببدء الحرب الأهلية الأولى. وعلى الرغم من استعداداتِ الموارنة وادِّعاءاتهم بما سيفعلونه بالدروز عندما تقع الحرب، تحوَّل القتال إلى كارثة مروِّعة نزلت بالموارنة في دير القمر؛ إذ دبَّت فيهم الفوضى، فأصبحوا أهدافًا سهلة للقوات الدرزية. وما إن سمع البطريرك بما حدث لدير القمر، حتى أغلق الكنائس، وطلب من كلِّ نصراني أن يحمِلَ ا"},{"id":4538,"era":"c13","t":"ثورة الدروز في لبنان وتقسيم البلاد إلى شطرين بين الدروز والموارنة  .","s":"دعمت فرنسا الموارنةَ في لبنان على حين دعَمَت إنكلترا الدروز، فاعتدى الدروزُ على الموارنة في عام 1257هـ ودخلوا ديرَ القمر وارتكبوا أبشَعَ الأعمال، وكرَّروا الاعتداء عام 1261هـ، فعزل الخليفةُ العثماني الأميرَ بشير الشهابي ووضع واليًا عثمانيًّا مكانه، وحَرَم الجبل مما كان له من امتيازات، ولم تقبل الدولُ الأوربية بذلك فاضطرَّ أن يعيد للجبل امتيازاتِه، وأن يعيِّنَ قائمينِ درزي وآخر ماروني، وذلك في عام "},{"id":4539,"era":"c13","t":"تقديم مشروع لتقسيم لبنان وموافقة الدول الكبرى عليه .","s":"كان الأميرُ ميترينخ وزيرُ خارجية ومستشار النمسا، صاحِبَ مشروعٍ مبنيٍّ على الواقِعِ الموجود في لبنان، وقِوامُه الاعترافُ بالحقيقة الطائفية في هذا البلد، إذا أريد التوصُّلُ إلى نظامِ حُكمٍ يكون مقبولًا من الطرفين المتنازعَين: الموارنة والدروز، على أن يكون ذلك في إطارٍ مِن الاعتراف بالسيادة العثمانية. فدعا المستشارُ النمساوي إلى تقسيم الجبل، بإنشاء وحدتَين إداريتَين؛ إحداهما درزية في نصفه الجنوبي، وي"},{"id":4540,"era":"c13","t":"استيلاء عبد الله بن ثنيان على الأحساء .","s":"بعث عبد الله بن ثنيان قوةً بقيادة عبد الله بن بتال المطيري لاحتلال الأحساء، فاستولى عليها، ثم عيَّن عمر بن عفيصان أميرًا على الأحساء وكلَّفه بالسير إلى القطيف فأخضعها، وهدَمَ سور سيهات، وقبض على أميرها ابن عبد الرحيم، كما أشخص أميرَ القطيف علي بن غانم إلى نجد لمقابلة ابن ثنيان، فوجَّه إليه تهمة الخيانة العظمى بالتواطؤِ مع آل خليفة، فسجنه وصادر أموالَه وأملاكه، ثم عيَّنَ أحمد السديري أميرًا على الق"},{"id":4541,"era":"c13","t":"نزول الغيث على نجد بعد سنوات عجاف .","s":"في ليلةِ عشرين من رمضان أنزل اللهُ من الغيث العظيم على نجدٍ، فسالت منه الوديان، وضاقت من جَورِ سَيلِه الشعبان، وعمَّ جميع الأوطان والبلدان حتى أشفقوا من الغرق، فتضَرَّعوا إلى الله خوفًا من الغرق، فكان هذا السيلُ رحمة من الله للعباد والبلدان، وإنقاذًا من بعد السنين الشداد، فجرى به كلُّ وادٍ، وكان قد مضى على وادي سدير نحو أربع عشرة سنة ما عَمَّ بلدانَه سَيلُه، وغارت آبارُه وهلك كثيرٌ من نخله، فأخذ و"},{"id":4542,"era":"c13","t":"ظهور الطريقة السنوسية في الجبل الأخضر بليبيا .","s":"بدأت الدَّعوة السنوسية في الجزائر على يدِ مؤسِّسِها محمد بن علي المعروف بالسنوسي الكبير، وبدأت هذه الدعوةُ تنتشِرُ داخِلَ أفريقيا من الصومال إلى السنغال وعلى طول الطريق إلى تشاد، وفي المغرب، وكانت أكثر المناطق التي انتشرت فيها بقوة هي ليبيا، وخاصةً منطقة الجبل الأخضر؛ حيث كان فيها أكثر من 300 زاوية سنوسية تعيشُ على الزراعة، وهم أوَّلُ من قاوم المحتلين الإيطاليين في ليبيا، وكان من أبرَزِ رجال هذه ا"},{"id":4543,"era":"c13","t":"موت الزرع قبل أن يشتد سنبله .","s":"حصل في هذا العامِ بَردٌ في آخر الحميم على أوَّلِ دخول الذراع مع طلوع المؤخر، فمات كل زرع لم يشتَدَّ سنبله، وما اشتد في سنبله سَلِمَ من الموت، وهذا لم يُعهَدْ في هذا الوقتِ."},{"id":4544,"era":"c13","t":"استعمار فرنسا لجزر القمر .","s":"استعمرت فرنسا جُزُرَ القمر الكبرى وأنجوان ومايوت وموهيلي، ما بين عامي 1843 و1920م، وقد وضعَتْها فرنسا تحت إدارةِ الحاكم العام في مدغشقر. وفي سنوات لاحقةٍ أقام فيها المقيمون الفرنسيون والشركاتُ الفرنسية وبعضُ التجار العرب الأغنياء اقتصادًا زراعيًّا يعتَمِدُ على المزارع التي كانت تصدِّرُ ثلث الإنتاج. وفي سنة 1947م أصبحت جزرُ القمر واحدةً من الأقاليم الفرنسية فيما وراء البحار، وأعطيت تمثيلًا في البرل"},{"id":4545,"era":"c13","t":"استعادة الإمام فيصل بن تركي قصر الدمام .","s":"بعد أن استقَرَّ الإمام فيصل بن تركي في الرياض وبايعه رؤساءُ القبائل وأمراء بلدان نجد، تطلع إلى الخليج، وبدأ باستعادة قَصرِ الدمام من آل خليفة حُكَّام البحرين، وجعل فيه قوةً سعودية، وحاول أكثَرَ مِن مرة ضَمَّ البحرين ولكِنَّه لم يتمكَّنْ من ذلك؛ بسبب التدخُّلات البريطانية التي كانت تخشى على مصالحِها ونفوذها، فعَمَدت إلى ضرب ساحل الأحساء، وانتهى الأمرُ بأن توسط سعيد بن سحنون حاكِمُ أبو ظبي بين الطرف"},{"id":4546,"era":"c13","t":"وفاة عيسى بن محمد السعدون رئيس المنتفق محترقًا .","s":"هو عيسى بن محمد السعدون رئيس المنتفق، احترق في منزلِه، وسببُ ذلك  أنَّ بيوتَهم التي يأوون إليها من قَصَبٍ يتَّخِذونها في وقت القيظ على شاطئ الفرات، فاتَّفق في ليلة نام مع أهله، ونسيت الخادِمُ الفنر أن تطفِئَه وتركته معلقًا على القصب المحكَم شَدُّه كالجدار، فعَلقَت النارُ فيه فاضطرمت في البيتِ وهو في نومِه مع أهله على سريره، فما استيقظ إلا وقد شملت النار جميعَ البيت وليس له مَهربٌ، وعليه بابٌ مُحكَ"},{"id":4547,"era":"c13","t":"تأليف البرلمان الإنجليزي \"لجنة إعادة أمة اليهود إلى فلسطين\"  .","s":"ألَّف البرلمان الإنجليزي لجنة \"إعادة أمة اليهود إلى فلسطين\", وفي العام نفسه تألَّفت في لندن \"الجمعية البريطانية والأجنبية للعمل في سبيل إرجاع الأمة اليهودية إلى فلسطين\". وألحَّ رئيسها القس كريباس على الحكومة البريطانية كي تبادِرَ للحصول على فلسطين كلِّها من الفرات إلى النيل ومن المتوسِّط إلى الصَّحراء."},{"id":4548,"era":"c13","t":"مغادرة الإمام فيصل بن تركي لمصر .","s":"تمكَّن الإمام فيصل بن تركي من الهروبِ مِن سِجنِه في مصر متدلِّيًا بحبل، ونزل معه ابنه عبد الله، وأخوه جلوي بن تركي، وابن أخته عبد الله بن إبراهيم، وكان ذلك ليلًا، ثم غادروا مصر حتى وصلوا جبل شمر، فاستقبلهم عبدُ الله بن علي بن رشيد -والي جبل شمر مِن قِبَل فيصل- فأكرمهم ووعدهم بالمساعدةِ بالمال والرِّجالِ، والقتال معهم."},{"id":4549,"era":"c13","t":"ظاهرة كونية غريبة في السماء .","s":"في أوَّلِ يومٍ مِن صفر بعد صلاة المغرب في وسَطِ القبلة ظهر عمودٌ أبيض مستطيل من الأفق إلى وسط السماء، مثل المنارة في رأي العين، وانزعج الناسُ لذلك، وكثر التنافس في طلوع هذه الآية، وما زال يضمحلُّ شيئًا فشيئًا إلى طلوع شهر صفر."},{"id":4550,"era":"c13","t":"استعادة الإمام فيصل بن تركي حكمه في نجد .","s":"لما بلغ ابنَ ثنيان في الرياض خبَرُ وصول فيصل بن تركي جبل شمر، عزم على قتالِ فيصل ومَنْعِه من دخول الرياض, ودارت مفاوضاتٌ ومراسلات رفض فيها ابن ثنيان الخروجَ مِن الرياض وتسليمَها لفيصل، واستعَدَّ الطرفان للحربِ، لكن فيصل تمكَّن من دخول الرياض بدون قتالٍ، وقبض على ابن ثنيان وحَبَسَه في أحد بيوت القصر إلى أن مات فيه. وتمكَّن الإمام فيصل من استعادة أكثر الأملاك التي خضعت له في فترةٍ وجيزة."},{"id":4551,"era":"c13","t":"وفاة الأمير عبد الله بن ثنيان .","s":"هو عبد الله بن ثنيان بن إبراهيم بن سعود بن محمد بن مقرن، من أمراء نجد، وكان في الرياض يُظهِرُ الطاعة لخالد بن سعود القادم من مصر الذي أخرج فيصل بن تركي وحلَّ محلَّه، فعمل ابن ثنيان على إخراج خالد والقوات المصرية، وكان شجاعًا مَهيبًا أطاعته نجد، فصَفَت له الإمارةُ إلى أن عاد فيصل بن تركي من أَسْرِه في مصر، فامتنع عليه عبدُ الله، وظَفِرَ به فيصل فحبسه في الرياض، فمات في السجن، فخرج فيصل في جنازته وص"},{"id":4552,"era":"c13","t":"قتل أمير القطيف السابق علي بن عبد الله بن غانم .","s":"لما استعمل الإمامُ فيصل عبدَ اللهِ بنَ سعد المداوي أميرًا على القطيف استلحق علي بن عبد الله بن غانم الرافضي رئيس القطيف السابق، فناوبه بأشياءَ ذُكِرَت له فضَرَبَه بالخَشَبِ حتى مات، فغضب الإمامُ فيصل وأرسل إليه غلامَه بلال بن سالم الحرق، فأشخصه إلى الإمام وجلس مكانَه في القطيف، فلما أتى المداوي إلى الإمام ذكَرَ له عُذْرَه في ضربه لابن غانم، فقبل منه ورَدَّه إلى القطيف أميرًا."},{"id":4553,"era":"c13","t":"معارك عنيفة بين الجزائريين والفرنسيين في منطقة جبال الأوراس .","s":"اندلعت معاركُ عنيفةٌ بين الجزائريين والفرنسيين، وذلك في أثناء الاحتلال الفرنسي لمنطقة جبال الأوراس بقيادة أحمد باي، وقد استمَرَّت عشرين يومًا."},{"id":4554,"era":"c13","t":"الاعتداء الثاني للدروز على الموارنة في جبل لبنان .","s":"لم يُعجِبِ الدروزَ أن يكون الموارنة في الجبل تحت سلطةِ غيرهم -وهو الرأي الذي أخذ به الخليفةُ العثماني في حلِّ المشكلة بين الدروز والموارنة في الجبل- فقام الدروز باعتداءاتِهم الثانية في هذا العامِ بعد الاعتداء الأول عام 1258هـ، فأرسلت الدولةُ العثمانية بعد ذلك جيوشَها واحتَلَّت المنطقةَ كُلَّها، وأعلنت فيها الأحكامَ العُرفيَّةَ، ثم اتفقت الدولُ الأوربية مع الخليفة على تشكيلِ مجلسٍ يَضُمُّ أعضاءً مِ"},{"id":4555,"era":"c13","t":"إبادة القوات الفرنسية لقبيلة أولاد رباح الجزائرية .","s":"أقدمت القواتُ الاستعمارية بقيادة الجنرال بليسي السفَّاح على جريمة خطيرة ظلَّت طيَّ الكتمان، وهي محارِقُ في كلٍّ مِن النقمارية وأولاد رباح، وحسَبما تداول عن هذه المعارك أن القواتِ الاستعمارية كانت وراءَ كُلِّ أنواع التعذيب التي حدثت في المنطقة، ومنها ثلاثُ محارق في النقمارية وأولاد رباح، حيث تم حشدُ مئات المواطنين في شهر أوت من سنة 1845م داخِلَ مغارات وكهوف تحت الأرض وبعد الغَلقِ عليهم بالإسمنت الم"},{"id":4556,"era":"c13","t":"وقعة بين ابن رشيد رئيس جبل شمر وأهل عنيزة .","s":"في رمضانَ من هذه السنة كانت وقعةُ ابن رشيد رئيس الجبل على أهل عُنيزة، وذلك أنَّ عبد الله بن سليم بن زامل أميرَ عنيزة أخذ إبلًا لابن رشيد، فطلب منه الأداء، فأبى عليه وحَذَّره وأنذَرَه، فجهَّز ابنُ رشيد إليهم أخاه عبيد في 250 مطية وخمسين من الخيل، فأغار على غَنَم عنيزة قريبًا من البلد، ففزع أهلُ عنيزة، وكان ابن رشيد قد جعل لهم كمينًا، فلما نشب القتالُ خرج عليهم الكمين فولَّوا منهزمين، واستولى عبيد و"},{"id":4557,"era":"c13","t":"عدوان العجمان على حاج الأحساء والقطيف والبحرين .","s":"في آخِرِ هذه السنة أقبل حاجُّ الأحساء والقطيف والبحرين وسيف البحر ومعه عجمٌ كثيرٌ، فرصد لهم في الطريق فلاح بن حثلين رئيسُ العجمان ومعه أناسٌ مِن أعراب سبيع، فشَنُّوا عليهم الغارةَ، فتفرق من الحاج نحوًا من نصفه، وانهزم أكثرُ الحاج، فمنهم السالم والمأخوذ، فلما بلغ الإمام فيصل خبَرُهم استنفر المسلمين فرَكِبَ من الرياض آخِرَ ذي القعدة ومعه الشيخ العالم القاضي عبد الرحمن بن حسن ابن الشيخ محمد بن عبد ال"},{"id":4558,"era":"c13","t":"محاسبة الإمام فيصل بن تركي قطَّاع الطريق وتصفيتهم .","s":"تمكَّن الإمام فيصل خلال هذا العامِ مِن القبض على فلاح بن حثلين وقطع رأسَه في الأحساء  على إثرِ قَطعِه الطريقَ على حاجِّ الأحساء والقطيف والبحرين، وكذلك تمكَّنَ من مشعان بن هذال لَمَّا أخذ الحدرة ولم يمتَنِعْ بعدها إلا خمسين يومًا حتى اقتصَّ منه، وكذلك هادي بن مذود لما أخذها لم يحُلْ عليه الحول، وقطع الله أصله ونسْلَه على يد الإمام، وكذلك ما جرى على الدبادية -وهم فرع من مطير- قتَلَهم مرةً واحدةً لَ"},{"id":4559,"era":"c13","t":"الإنجليز يبيعون كشمير لأسرة الدوغرا الهندوسية لمدة مائة عام .","s":"كانت كشمير تحت حكم المغول المسلمين، ثم سيطر الأفغانُ عليها بعد المغول، ثم بعد التدخُّل الإنجليزي استطاع السيخُ أن يتحكَّموا بالإقليم الكشميري، وكانت أيامُهم فيها من أسوأ الأيام على المسلمين من إراقة الدماء وهدمِ المساجِدِ، ثم أخذها الإنجليزُ مِن السيخ عام 1262هـ / 1846م ثم قاموا ببيعِها بموجِبِ اتفاقية أمريتسار (وهي المدينة التي تعد قاعدة السيخ) بمبلغ سبعة ملايين ونصف مليون روبية إلى أسرة الدوغرا "},{"id":4560,"era":"c13","t":"وفاة فلاح ابن حثلين أمير العجمان  .","s":"هو فلاح بن مانع بن حثلين العجمي أميرُ قبيلة العجمان، قام في السنة الماضية ومعه بعض العُجمان وعربان من سبيع بالغارة على حاجِّ الأحساء والقطيف والبحرين وسيف البحر، فطلبه الإمام فيصل بن تركي ففَرَّ إلى  ديرة بن خالد، فأجلى الإمام فيصل العجمانَ من ديرة بني خالد، ففَرَّ ابن حثلين إلى محمد بن هاد بن قرملة بعد أن انسلخ منه العجمان وتبرؤوا منه، ثم إنَّ فلاح بن حثلين قام يدير الرأيَ في الحيلة للرجوعِ إلى د"},{"id":4561,"era":"c13","t":"زيارة محمد علي باشا والي مصر لاستانبول .","s":"زار محمد علي باشا والي مصرَ استانبول عاصمة الدولة العثمانية؛ لتقديم فروضِ الولاءِ والطاعة، وذلك بعد سنوات من الحروبِ بين الجانبين، وكان عمرُه آنذاك 77 عامًا، وتعَدُّ هذه الزيارةُ هي الأولى والأخيرة له للعاصمة العثمانية، وقد استمَرَّت لمدة 29 يومًا."},{"id":4562,"era":"c13","t":"وفاة العلامة أشرف علي التهانوي .","s":"هو الشيخُ المحَدِّث الكبير، أشرف علي التهانوي بن عبد الحق بن الحافظ فيض علي، صاحِبُ التصانيف النافعة المفيدة، وُلِدَ صباح الخامس من شهر ربيع الثاني سنة 1280هـ / 10 سبتمبر 1863م، في إحدى قرى الهند وهي قرية (تهانه بهون)، وترعرع في بيئة علمية، وكان منذ نعومة أظفاره مكبًّا على العلم والعلماء، بعيدًا عن اللهو. ويعتبر أشرفُ علي التهانوي أحد كبار مشيخة ديوبند، تخرَّج عليه خلقٌ كثيرون، وعلماء أمثال: الشيخ"},{"id":4563,"era":"c13","t":"قيام السلطنة القعيطية وصراعها مع الدولة الكثيرية .","s":"أُسِّستِ المَملَكاتُ القُعَيْطيَّةُ في حَضرَموتَ على يَدِ عُمَرَ بنِ عَوَضِ بنِ عبدِ اللهِ القُعَيْطيِّ، والأسرةُ القُعَيْطيَّةُ تَرجعُ جُذورُها إلى قَبيلةِ يافِعٍ، فبَعدَ مَوتِ السُّلطانِ بَدرٍ أبي طُوَيرِقٍ الكَثيريِّ، دخَلَ حُلَفاؤُه مِنَ السَّلاطينِ في تَطاحُنٍ على السُّلطةِ، حتى إنَّ بَعضَ السَّلاطينِ الكَثيريِّينَ استَنجَدَ بالجيشِ الإماميِّ في صَنعاءَ، فكانَ أنْ تلاشَت تَدريجيًّا السُّلطةُ "},{"id":4564,"era":"c13","t":"غزو الروس لتركستان .","s":"بعد أن سيطر الروسُ تمامًا على سيبيريا (تشمل منطقة آسيا الشمالية) عام 1078هـ أصبحت تركستان تحدُّهم من جهة الجنوب حيث تمتدُّ سهول القازاق الواسعة والتي تعد قليلةَ السكان؛ الأمر الذي أغراهم بها، ولكِنْ كان قبل ذلك انصبَّ همهم على القفقاس فما أن انتهوا من أمر القفقاس وأصبحت تحت قبضتِهم حتى توجهوا إلى تركستان فسيطروا على سواحل بحر الخزر الشمالية والشرقية عام 1249هـ، ثم تابعوا تقَدُّمَهم نحو نهر سيحون، "},{"id":4565,"era":"c13","t":"تمرد قبائل شمال عُمان ضد القائد السعودي سعد المطيري .","s":"تمرَّدَت قبائل شمال عمان ضِدَّ القائد السعودي سعد بن مطلق المطيري، وشكَوا إلى الإمام فيصل أنه يتشَدَّد في معاملته معهم، واستدعى الإمام فيصل قائدَه سعد بن مطلق المطيري إلى الرياض للتفاهُمِ معه بشأن الموقف المتدهوِرِ في البريمي. وفي غياب سعد بن مطلق حلَّ محلَّه محمد بن يوسف العجاجي بالوكالةِ، واستطاع توثيقَ عُرى الصداقة بين القبائل هناك، وظَلَّ يحكُمُ عدة شهور حتى وصل حاكِمٌ جديدٌ للبريمي من قِبَل ا"},{"id":4566,"era":"c13","t":"شريف مكة يقصد نجدًا بتحريض من رؤساء القصيم .","s":"قصد في هذه السنة شريفُ مكَّةَ محمد بن عون بتحريضٍ من رؤساء أهل القصيم الذين زيَّنوا له أنَّه إن سار إلى نجدٍ فلا يقاومُه أحدٌ ولا يثبُتُ فيصلُ بن تركي في مكانِه، فجهَّز نفسَه وعساكره واستلحق عساكِرَ الترك من المدينة والحناكية، وظهر معه خالدُ بن سعود واجتمع عليه عساكِرُ كثيرةٌ، وقَدِمَ القصيم في ربيع الآخر وأطاعه أهلُ القصيم كلُّهم، ووفد عليه كثيرٌ من رؤساء العُربان وأمراء البلدان، فلما علم فيصل به"},{"id":4567,"era":"c13","t":"وفاة عبد الله بن رشيد أمير جبل شمر وخلفه ابنه طلال .","s":"هو الأمير عبد الله بن علي بن رشيد، من الجعافرة (آل جعفر) من الربيعية، من عبدة، من شمر: أول حكام آل رشيدٍ في جبل شمر، ومؤسِّسُ حُكمِهم فيها. ولِدَ بحائل سنة 1202ه. كان جدُّه رشيد من سكان حائل ومات في أواخر القرن الثاني عشر للهجرة, وعُرِفَ أبناءُ رشيد وأحفاده بآل رشيد. وكانت لهم في شماليَّ جزيرة العرب إمارةٌ واسعة ظهر فيها أمراءُ وفرسان عُرِفوا في تاريخ نجد الحديث. خلَّف رشيد عليًّا. وعلي خلَّفَ عبد"},{"id":4568,"era":"c13","t":"عزل الإمام فيصل بن تركي لأمير عنيزة .","s":"بادر الإمامُ فيصل بن تركي إلى عَزْلِ أمير عنيزة في هذه السنة؛ وذلك لاعتقاده بأنه أغرى شريفَ مكة محمد بن عون بغزوِ نجد، وفتح له أبوابَ بلدتِه. وأمَّر الإمامُ فيصل على عنيزة ناصرَ بن عبد الرحمن السحيمي. فناصَبَ آلُ سليم أسرةُ الأمير المعزول أسرةَ السحيمي الأميرِ الجديد العداءَ، وحاولوا بزعامةِ عبد الله بن يحيى بن سليم اغتيالَ السحيمي، والاستيلاءَ على قصرِ الإمارة، ولكِنَّ محاولتهم باءت بالفشلِ، فهرب"},{"id":4569,"era":"c13","t":"عودة الشيخ عبد اللطيف بن عبد الرحمن بن حسن من مصر .","s":"قَدِمَ الشيخ عبد اللطيف بن عبد الرحمن بن حسن من مصر إلى نجد واستعمله الإمامُ فيصل قاضيًا في الأحساء، ثم عاد إلى الرياض ليكونَ قاضيًا فيها مع أبيه. وكان قد جلب معه كتُبًا كثيرة انتفع بها وبعِلْمِه كثيرٌ من أهل العلمِ، والقُضاة."},{"id":4570,"era":"c13","t":"وفاة الأمير خالد بن سعود قائد الحملة المصرية .","s":"الأميرُ خالد بن سعود بن عبد العزيز بن محمد بن سعود أميرٌ مِن آل سعود، وهو مِن أمٍّ حبشية. نشأ بمصرَ بعد حرب إبراهيم باشا للدرعية,  ولما قَوِيَ أمر الإمام فيصل بن تركي في الديار النجدية أرسل محمد علي باشا خالدًا مع قوة عسكرية يقودُها إسماعيل بك سنة 1252 هـ لقتال فيصل بن تركي، فنشبت بينهما معاركُ انتهت باستسلام فيصل لخورشيد باشا في رمضان 1255 1838 م ووجَّهه خورشيد إلى مصر، ومعه ولداه عبد الله ومحمد "},{"id":4571,"era":"c13","t":"أسر عبد القادر الجزائري بعد أن هزم الآليات الفرنسية .","s":"بدأ الأميرُ عبد القادر الجزائري سياسةً جديدةً في حركته، واستطاع أن يحقِّقَ بعض الانتصارات، وبعد أن كبَّد عبد القادر الجزائري الآلياتِ الفرنسيةَ هزائِمَ متلاحِقةً، دعمت فرنسا قواتِها بسرعة، فلجأ الجزائريُّ مرة ثانية إلى بلاد المغرب، وعلى الرغمِ من انتصار الأمير عبد القادر على جيش الاستطلاع الفرنسي فإن المشكلة الرئيسية أمامَ الأمير كانت هي الحصول على سلاح لجيشِه، ومن ثمَّ أرسل لكُلٍّ من بريطانيا وأم"},{"id":4572,"era":"c13","t":"قحط في نجد ثم غيث  .","s":"وفي هذه السنة منع اللهُ الغيثَ بحكمته، فلم يقَعْ في الأرض حَيَا في بلدان نجدٍ ولا غيمٌ ولا مطرٌ كثيرٌ ولا قليلٌ، من أولها إلى آخر الشتاء، وقتَ حلول الشمس برج الحوت، فقَنِط الناس قنوطًا عظيمًا؛ لأن الناس يقولون: ما نعلم أن السماء عَدِمَ فيها الغيم مثل هذه السنة، فلما كان رابعَ عشر صفر أنشأ الله الغيمَ في السماء فصَبَّ الغيث فامتلأ كلُّ وادي بما فيه، وضاقت مجاريه وخرَّب السيل في البلدان كثيرًا، فلم "},{"id":4573,"era":"c13","t":"دخول الجيش التركي رومانيا .","s":"استطاع الجيش التركي أن يدخُلَ رومانيا، وقد ردَّت روسيا على هذه الخطوة من تركيا باحتلالِ مولدافيا، وذلك في إطار التنافُسِ بين الدولتين في منطقة البلقان في أوروبا."},{"id":4574,"era":"c13","t":"وفاة الشاه محمد القاجاري شاه إيران وتولي ناصر الدين شاه الزعامة .","s":"هو الشاه محمد بن عباس القاجاري الشيعي، شاه إيران في الفترة من 23 أكتوبر 1834 إلى وفاته سنة 1848، ينتمي إلى سلالة القاجاريين التي حكمت بلاد فارس بين عامي 1779 و1925. وهو ابنُ عباس ميرزا، ابن فتح علي شاه وولي عهده. خلَفَ محمد شاه جَدَّه في الحكم. ثم ثار عليه عمُّه علي ميرزا. توفِّيَ محمد شاه يوم الثلاثاء 6 شوال من هذا العام  ودام ملكُه أربع عشرة سنة وثلاثة أشهر، وكان ابنه ناصر الدين ميرزا ولي العهد "},{"id":4575,"era":"c13","t":"دخول مسقط في نزاع مع الرياض .","s":"دخلت مسقط مع الرياض في نزاعٍ عندما رأت ضعفَ القوَّة السعودية إثرَ اعتداءِ حاكم أبو ظبي سعيد بن طحنون عليها، فرفض الثويني ابنُ حاكم مسقط أن يدفَعَ ما تعهد به من الزكاة عام 1261هـ وتحالف معه ابنُ طحنون في السنة نفسِها واتَّفَقا على مساعدة بعضهما البعض ضِدَّ السعوديين."},{"id":4576,"era":"c13","t":"وقعة اليتيمة بقيادة عبد الله بن فيصل .","s":"لَمَّا قفل عبد الله بن فيصل راجعًا بعد غارته على عنزة، نزل النفوذَ المسماةَ اليتيمةَ، ووجد آثارَ جيش عبد العزيز المحمد أبو عليان معه أهل عنيزة واستنفر معه أيضًا من وافقه من أهل بُريدة على قتال عبد الله ومن معه، فأشار على عبد الله بن فيصل من معه أن يسيرَ في طريقه ويتركَهم ما دام أنَّهم لم يعترضوه، فقال: لا والله لا أرجِعُ عنهم حتى يطأَهم جيشي، فقصدَهم في موضعهم فثار القتالُ وصمدوا للقتال وحَمِيَ وط"},{"id":4577,"era":"c13","t":"اتفاق بلطة ليمان بين العثمانيين والروس .","s":"ثار أهلُ الأفلاق والبغدان رغبةً في تكوين دولةٍ واحدةٍ تشمَلُ الإقليمين مع ترانسلفانيا، ففَرَّ أمير الإقليمين وتشكَّلَت حكومةٌ مؤقَّتةٌ، فأرسلت الدولةُ العثمانية جيشًا بقيادة عمر باشا لإعادةِ الوَضعِ إلى ما كان عليه، وسارعت روسيا واحتَلَّت البغدان والأفلاق، وطردت الحكومةَ المؤقَّتةَ فاحتجت الدولةُ العثمانيةُ على هذا الفِعلِ، وكادت تقَعُ الحربُ بين الطرفين، ثم جرى اتفاق بلطة ليمان قرب استانبول عام 1"},{"id":4578,"era":"c13","t":"أهل القصيم يخرجون عن طاعة الإمام فيصل بن تركي .","s":"لَمَّا رحل الشريف محمد بن عون العامَ الماضي من القصيم عائدًا إلى مكة بعد الفشل في تحقيق مرادِه، أوفد أهل القصيم إلى الإمام فيصل منهم رجالًا يعتذرون عمَّا بدر منهم، فقَبِلَ عُذرَهم وغفر لهم خطأَهم، ثم إن الإمام فيصل عزل عن إمارة عُنيزة إبراهيمَ بن سليمان بن زامل؛ لأن الشريف لم ينزِلْ عُنَيزةَ إلا بإذنه، وجعل مكانَه ناصِرَ بن عبد الرحمن السحيمي من أهل العقيلية، الذي قدِمَ إلى عنيزة بكتابٍ فيه توليته"},{"id":4579,"era":"c13","t":"وفاة محمد علي باشا بمصر  .","s":"هو محمد علي باشا المسعود بن إبراهيم آغا القوللي الملقَّب بعزيز مصر، مؤسِّسُ الأسرة العَلَوية وحاكم مصر، من مواليد قوالة على الساحل المقدوني 1769م، كان عمه يشغل منصب (متسلم - أو نائب والي) وفي ديوان عمِّه هذا تمرَّس محمد علي بالأعمال والمعاملات من غيرِ أن يحظى بتربيةٍ مدرسية صحيحة. حتى إذا بلغ العشرين كان قد نجح في تجارةِ التبغ وعقد الصفقاتِ فيها، والتبغ مادةُ التجارة الرئيسية في بلده الأم. وظهرت ع"},{"id":4580,"era":"c13","t":"وفاة علي محمد الشيرازي الملقب بالباب مؤسس فرقة البابية المنحرفة .","s":"هو علي محمد ابن المرزا رضى البزَّاز الشيرازي الملقَّب بالباب مؤسِّس فرقة \"البابية\" وهي إحدى الفِرَق التي حرَّفت العقيدة الإسلامية، وهي أصلُ فرقة البهائية, وهو إيرانيُّ الأصل، ولِدَ بشيراز سنة 1235هـ، ومات أبوه وهو رضيعٌ، فرَبَّاه خاله المرزا سيد علي التاجر، ونشأ في أبي شهر فتعَلَّم مبادئَ القراءة بالعربية والفارسية، وتلقى شيئًا من علوم الدين، وتقشَّف، فكان يمكث في الشَّمسِ ساعات عديدة. وأثَّر ذلك "},{"id":4581,"era":"c13","t":"أهل قطر يبايعون الإمام فيصل بن تركي على السمع والطاعة .","s":"جهَّز الإمامُ فيصل بن تركي لغزوِ قطر، فلما عَلِمَ أهلُ قطر بذلك طلبوا الأمانَ من فيصل وبايعوه على دينِ الله والسمع والطاعة، فأمر الإمامُ فيصل على السُّفن التي لأهل قطر، وهي نحو 300 سفينة أن يُهَيِّئوها وجعل فيها رجالًا مِن جُندِه، ثمَّ أمرَ على أولاد عبد الله آل خليفة الجالين من البحرين أن يركبوها ويتولَّوا قيادتَها."},{"id":4582,"era":"c13","t":"وفاة الشيخ القاضي محمد بن مقرن بن سند .","s":"هو الشيخُ القاضي محمد بن مقرن بن سند بن علي بن عبد الله بن فطاي بن سابق بن حسن الودعاني الدوسري، وهو من أعلامِ الحنابلة في القرن الثالث عشر الهجري، قال عنه ابن بشر: \"كان -رحمه الله- فطِنًا متيقظًا له عقلٌ راجِحٌ ورأيٌ صائبٌ ووجهٌ سامحٌ صابحٌ، إذا قال رأيتَ قولَه مُسكتًا عن الجواب، وإذا أشار بالرأي يلوحُ من رأيه الصواب\" استعمله الإمام سعود بن عبد العزيز قاضيًا في بلدان المحمل، وأرسله قاضيًا في عُما"},{"id":4583,"era":"c13","t":"أهل البحرين يطلبون العفو والصلح مع الإمام فيصل  .","s":"وكان أهلُ البحرين حين نزل الإمامُ فيصل بن تركي في ناحيتِهم أرسلوا إلى سعيدِ بن طحنون رئيسِ بلدان أبو ظبي في ناحية عُمان يستنجدون به أن يفزعَ لهم، وكان ذو قوةٍ مِن الأموال والرجال والسفن، ففزع لهم وأقبل في عددٍ مِن السفن المملوءة من الرجال، فلما أقبل على الجهةِ التي نزل فيها الإمامُ فيصل ناحيةَ قطر، داخل ابن طحنون الفشَلَ والوجَلَ، وأرسل إلى الإمامِ يطلب منه أن يتصالحَ مع أهل البحرين، فأجابه الإمام"},{"id":4584,"era":"c13","t":"آل سديري في طاعة الإمام فيصل .","s":"كان أحمدُ السديري وبنوه من أحسَنِ الناس سيرةً وأصفاهم سريرةً وألينِهم طبيعةً، ولهم في الولاياتِ فنونٌ رفيعة وسيعة؛ فلذلك استعمل الإمامُ أحمدَ أميرًا في عمان، وابنَه تركيًا أميرًا في الأحساء ونواحيه، وابنَه محمدًا أميرًا في سدير وبلدانه، وعبدَ المحسن ابنه أيضًا أميرًا في بلدهم الغاط، فلو نظرتَ إلى أصغرِهم لقلتَ هذا بالأدبِ قد أحاط، وإن نظرتَ إلى الأكبر لرأيتَ فوق ما يُذكَر، لم يكُنْ في عصرِهم مثلُه"},{"id":4585,"era":"c13","t":"وفاة رؤوف باشا رئيس وزراء الدولة العثمانية .","s":"هو الصَّدرُ الأعظم محمد أمين رؤوف باشا رئيس الوزراء بالدولةِ العُثمانية، وهو عثماني تركي، توفِّيَ عن عمر يناهز الثمانين عامًا، وقد تولى الوزارة 5 مرات، بلغ مجموعُ سِنِيها 14 عامًا."},{"id":4586,"era":"c13","t":"تركيا وحرب القوى العظمى في القرم ضد روسيا .","s":"حاولت روسيا إعادةَ اتفاقية خونكار أسكله سي، ولكِنَّ الدولة العثمانية رفضت ذلك، كما رفضت حقَّ حماية روسيا للنصارى المقيمين في الدولةِ العثمانية، وأُعيدَ رشيد باشا للصدارة العظمى بعدما عُزِلَ سابقًا؛ إرضاءً لروسيا، فهددت روسيا باحتلالِ الأفلاق والبغدان، فأبلغ الخليفةُ ذلك التهديدَ لسفراء الدول، فأعطت إنكلترا الأوامِرَ لقطعاتِها البحرية المنتَظِرة في مالطة بالتحَرُّك إلى مياه اليونان، والاشتراك مع ال"},{"id":4587,"era":"c13","t":"توقيع الفرنسيين معاهدة المقطع مع الأمير عبد القادر الجزائري .","s":"وقَّع الفرنسيون معاهدةَ المقطع مع الأمير عبد القادر الجزائري، وجاءت هذه المعاهدةُ بعد هزيمتهم أمامَه تحت قيادةِ الحاكمِ الفرنسي \"تيرزيل\"."},{"id":4588,"era":"c13","t":"أهل عنيزة يخرجون أميرهم جلوي بن تركي .","s":"حصل خِلافٌ بين أهل عُنيزة وأميرهم جلوي بن تركي، فأخرجوه منها ونزل بُرَيدة وكاتَبَ أخاه الإمام فيصلًا، وأخبره بالأمر، وكتب أهلُ عنيزة إلى الإمام فيصل ينتَقِدون شِدَّةَ وطأة الأمير جَلَوي عليهم، وعدم مراعاته لذوي المقامات منهم، وتكليفهم بأمورٍ ليست من مقامهم، وأنه يتعمَّدُ اضطهاد الأعيان وإذلالَهم مِمَّا لم يسَعْهم الصبر عليه، وإنهم اختاروا له العزلةَ إلى أن يأتي أمرُه بإرسال من يَخلفُه، ولكنه فارق "},{"id":4589,"era":"c13","t":"ولاية محمد سعيد باشا بن محمد علي باشا لحكم مصر .","s":"تولَّى محمد سعيد باشا بن محمَّد علي باشا حُكمَ مِصرَ خلفًا لابن أخيه عباس الأول، وهو الرابِعُ من أسرة محمد علي باشا الذين تولَّوا الحكم. وتميَّز عَهدُه بعدد من الإجراءات الإصلاحية التي وقفت إلى جانبِ الفلاحِ المصري، وأبرَزُ أعمالِه حفرُ قناةِ السويس."},{"id":4590,"era":"c13","t":"نزاع على رئاسة المنتفق بين أبناء السعدون .","s":"بعد وفاة عيسى بن محمد السعدون سنة 1259هـ تولَّى بعده أخوه بندر فأخذ نحوًا من ثلاث سنين من ولايتِه وحكَمَهم في ابتداءٍ مِن الخلل، ثم مات ووَلِيَ بعده أخوه فهد، فلم تطُلْ مُدَّتُه، فقد مات قبل أن يتِمَّ سنة في رئاستِه, ثم مرج حكمُ المنتفق بعده، فتارةً في أولاد راشد السعدون، وتارةً في أولاد عقيل السعدون، وتارة في ولد عيسى السعدون، يتحاربون ويتقاتلون بينهم، حتى هلك منهم أممٌ؛ يأخذ الواحِدُ منهم مدة قل"},{"id":4591,"era":"c13","t":"انتقال الأمير عبد القادر الجزائري إلى دمشق .","s":"ظلَّ الأمير عبد القادر الجزائري في سجون فرنسا يعاني من الإهانة والتضييق حتى عام 1852م، ثم استدعاه نابليون الثالث بعد تولِّيه الحكم، حيث وافق له أن يرحل إلى الشرق براتبٍ من الحكومة الفرنسية. توقَّف الجزائري في استانبول حيث السلطانُ عبد المجيد الأول، والتقى فيها بسفراءِ الدول الأجنبية، ثم استقَرَّ به المقام في دمشق منذ عام 1856م وفيها أخذَ مكانه بين الوُجَهاء والعلماء، وقام بالتدريسِ في المسجد الأمو"},{"id":4592,"era":"c13","t":"وقوع معركة \"سينوب\" البحرية بين روسيا والدولة العثمانية .","s":"أعلنت الدَّولةُ العثمانيةُ الحَربَ على روسيا في 1 محرَّم من هذه السنة، وأرسلت قِسمًا من أسطولها البحري إلى ميناء \"سينوب\" على البحر الأسود، وكان يتألَّفُ من ثلاث عشرة قطعة بحَرية بقيادة \"عثمان باشا\"، ثم وصلت إلى الميناء بعضُ القطع البحرية الروسية في 18 محرم من هذه السنة بقيادة \"ناخيموف\" قائد الأسطولِ الروسي؛ لتكشِفَ مواقع الأسطول العثماني، وتَعرِف مدى قوَّتِه، وظلَّت رابضةً خارج الميناء، محاصرةً لل"},{"id":4593,"era":"c13","t":"انتصار الجيش العثماني في معركة جاتانا على الجيش الروسي .","s":"تعرَّض الجيشُ الروسي لهزيمةٍ قاسية في معركة جاتانا في رومانيا من الجيشِ العثماني، وبذلك فَشِلَ الروس في طردِ العثمانيين من رومانيا، والذي كان هدفًا رئيسيًّا من أهداف تلك المعركةِ."},{"id":4594,"era":"c13","t":"عقد الدولة العثمانية \"معاهدة استانبول\" ضد روسيا. .","s":"عقدت كلٌّ من الدولة العثمانية وإنجلترا وفرنسا \"معاهدة استانبول\"، والتي نصَّت على ألَّا تَعقِدَ أيُّ دولة منهم أي صلح منفرد مع روسيا، وأن تكوِّنَ الدولُ الثلاث جيشًا واحدًا في حرب أيٍّ منهم ضِدَّ روسيا."},{"id":4595,"era":"c13","t":"إعلان فرنسا وإنجلترا الحرب على روسيا .","s":"أعلنت كلٌّ من فرنسا وإنجلترا بصفةٍ رسمية الحربَ على روسيا؛ وذلك تنفيذًا لمعاهدة استانبول التي وقَّعَتْها الدولتان مع الدولة العثمانية، والتي تقضي بتكوينِ جيشٍ واحد من كلٍّ مِن تركيا وفرنسا وإنجلترا بهدفِ حربِ روسيا."},{"id":4596,"era":"c13","t":"انتصار العثمانيين على الروس في معركة \"قالافات\" .","s":"انتصر الجيشُ العثماني بقيادة عمر باشا على الجيشِ الروسي في معركة \"قالافات\" في رومانيا، وطارد الجيشُ العثماني الروسَ مسافة 80 كم."},{"id":4597,"era":"c13","t":"صدور امتياز قناة السويس  .","s":"بعد أن تولى محمد سعيد باشا حُكمَ مِصرَ في 14 يوليو 1854م تمكن فرديناند دي لسبس المهندس الفرنسي -الذي كان مقرَّبًا من سعيد باشا- من الحصول على فرمان عقدِ امتياز قناة السويس الأوَّل، وكان مكوَّنًا من 12 بندًا، كان من أهمها حفر قناة تصِلُ بين البحرين، ومدة الامتياز 99 عامًا من تاريخ فَتحِ القناة، واعترضت إنجلترا بشدَّةٍ على هذا المشروع خوفًا على مصالحِها في الهند. قام دي لسبس برفقة لينان دي بلفون بك "},{"id":4598,"era":"c13","t":"انهزام الجيش الروسي في معركة \"يركوي\" .","s":"تعرَّض الجيشُ الروسي لهزيمةٍ قوية من الجيش العثماني بقيادة القائد العثماني عمر باشا، وذلك في معركة \"يركوي\" قربَ رومانيا، وخَسِرَ الروس في هذه المعركةِ 6 آلاف جندي."},{"id":4599,"era":"c13","t":"إنزال فرنسا وإنجلترا قواتهما في شبه جزيرة القرم .","s":"أنزلت كلٌّ من فرنسا وإنجلترا عددًا كبيرًا من قواتهما العسكرية في شبه جزيرة القرم الواقعة حاليًّا في أوكرانيا؛ وذلك لمساندة الدولة العثمانية في حربها ضد روسيا، تنفيذًا لمعاهدة استانبول الموقَّعة في جمادى الآخرة من هذه السنة."},{"id":4600,"era":"c13","t":"وفاة الشيخ المفسر شهاب الدين محمود الألوسي .","s":"هو الشيخُ المفسِّر أبو الثناء شهاب الدين محمود بن عبد الله الألوسي الحسيني البغدادي صاحِبُ التفسير المعجب المسمى (روح المعاني)، أحد علماء القرن 13 الهجري، وهو مفتي بغداد، وخاتِمةُ المحقِّقين من أعلام المشرق، ولِدَ ببغداد سنة 1217 وتعلم بها وتوفِّيَ فيها، جلس للتدريس وأقبل عليه الطلاب من كلِّ مكان، وترك مؤلفات كثيرة أهمها: التفسير المعروف بروح المعاني في تفسير القرآن العظيم والسبع المثاني. قال عنه "},{"id":4601,"era":"c13","t":"انهزام الجيش الروسي في معركة \"ألما\" .","s":"تعرَّض الجيش الروسي لهزيمةٍ كبيرة في معركة \"ألما\" من قواتِ فرنسا وإنجلترا والدولة العثمانية، وخَسِرَ الروس في هذه المعركة 7 آلاف قتيل."},{"id":4602,"era":"c13","t":"صمود العثمانيين وعجز الروس في اقتحام قلعة سلسترا ببلغاريا .","s":"كان الفرنسيون أصحابَ الحَقِّ في حماية النصارى في بيتِ المقدِسِ، ثمَّ استطاع الروسُ الحصولَ على هذا الحَقِّ أيام نابليون بونابرت، فلمَّا رجعت الدولةُ الفرنسية وأرادت إعادةَ حَقِّها اصطدمت مع روسيا، فكانت الدَّولة العثمانية قد ألَّفت لجنةً مِن رجال الكنائِسِ على اختلافِ مذاهِبِهم فأيَّدوا فرنسا فهدَّد الروسُ بالحربِ وأرادوا إعادةَ معاهدة خونكار أسكله سي، وحاولت الاستعانةَ بإنكلترا وفرنسا اللتين رفضت"},{"id":4603,"era":"c13","t":"خسارة الروس 20 ألف قتيل في هجوم جيش الاتفاق .","s":"خَسِرَ الروس 20 ألف قتيل في هجومِ جَيشِ الاتفاق الفرنسي الإنجليزي العثماني على قلعة \"سيفاستوبول\"- الواقعة حاليًّا في أوكرانيا- وذلك في أثناء \"حرب القرم\" بين الدولة العثمانية وحلفائِها من جهة، وبين روسيا من جهةٍ أخرى."},{"id":4604,"era":"c13","t":"استدانة الدولة العثمانية لأول مرة في تاريخها من الخارج .","s":"قامت الدولةُ العثمانية لأوَّلِ مرة في تاريخها بالاستدانة من الخارج؛ حيث حصَلَت على قرض مقداره 5 ملايين قطعة ذهبية بفائدة 5% من إنجلترا؛ وذلك لتغطية نفقات حَربِها ضِدَّ روسيا."},{"id":4605,"era":"c13","t":"الإمام شامل يقود الثورة في داغستان ضد الروس .","s":"انتقلت قيادةُ الثورة في داغستان ضِدَّ الروس إلى الشيخ الإمام شامل بن دنكاو الداغستاني، وكان قد صَحِبَ منذ صغره الشيخَ المجاهد محمد الكمراوي قائدَ الثورة الأول في رحلته العلمية، وعكف معه على العلم والعبادة، والأمر بالمعروف والنهى عن المنكر، حتى قامت الثورةُ المباركة وكان الإمامُ شامل الذراعَ الأيمن لمحمد الكمراوي، وقائد جيوشه وشريكه في الأمور حتى ليلة استشهاده، ثم اشترك مع القائد الثاني حمزة بك علي"},{"id":4606,"era":"c13","t":"انتصار الجيش العثماني في معركة \"أنجير\" على الجيش الروسي .","s":"انتصر القائدُ العثماني عمر باشا على الجيشِ الروسي في معركة \"أنجير\"، أثناءَ الحرب الروسية العثمانية المسمَّاة \"حرب القرم\"."},{"id":4607,"era":"c13","t":"صدور فرمان لتنظيم أوضاع النصارى في الدولة العثمانية .","s":"أصدر السُّلطانُ العثماني عبد المجيد الأول فرمانًا (قانونًا) عُرِفَ باسم \"إصلاحات خط همايوني\" حول أوضاع النصارى في الدولةِ العثمانية، وقد تعرَّض هذا الفرمان لانتقاداتٍ كبيرة داخل الدولة. وقد تضَمَّن البنودَ التالية: المساواة بين كل مواطِني الدولة العثمانية في الحقوقِ والواجبات مهما كانت أديانُهم ومذاهبُهم. عدم إجبار أي شخص على تركِ دينه. إلغاء نظام الالتزام (جباية الأموال والضرائب من عامة الشعب لإر"},{"id":4608,"era":"c13","t":"توقيع \"معاهدة باريس\" لإنهاء \"حرب القرم\" .","s":"وقَّعت كلٌّ من الدولة العثمانية وإنجلترا وفرنسا والنمسا وروسيا وبروسيا وساردونيا \"معاهدة باريس\"؛ وذلك لإنهاء حرب القرمِ التي شاركت فيها الدُّوَل السابقة، وتعَدُّ من كبرى الحروب التي شهدها العالَمُ في تلك الفترة، وتعدُّ هذه المعاهدة من المعاهدات التي صاغت الوجهَ السياسي لأوروبا في القرنِ التاسع عشر."},{"id":4609,"era":"c13","t":"إنشاء مجلس تجار مختلط من المصريين والأجانب .","s":"قرر سعيد باشا حاكِمُ مِصرَ إنشاء مجلس تجَّار مختلط من المصريين والأجانب، وقد أدى إنشاء مثل هذا المجلس إلى تسرُّبِ القانون الأجنبي ليحُلَّ محَلَّ الشريعة الإسلامية في المعامَلاتِ."},{"id":4610,"era":"c13","t":"الإنجليز يعلنون أن الهند من أملاك التاج البريطاني .","s":"سيطر الإنجليز على الهند جزءًا بعد آخر بكُلِّ الوسائل، واستولوا على أوقاف المسلمين التي كانت المصدرَ الوحيد لكتاتيب التعليمِ، فزاد الجهل، وبالوقتِ نَفسِه قاموا بتقوية مركز الهندوس وتعليمِهم؛ ليكُونوا أعوانَهم ضِدَّ المسلمين، ودخل نتيجةَ الفقر كثيرٌ مِن المسلمين في الجيش الإنجليزي ولكِنَّهم كانوا يعامَلون بالاستهزاء مِمَّا وَلَّد لديهم الكراهة الزائدة، فحدثت ثوراتٌ ضِدَّ الجيش شَمِلَت معظم أجزاء الب"},{"id":4611,"era":"c13","t":"صدور عهد الأمان بتونس .","s":"صدر إعلانُ عهد الأمان في 20 محرم من هذه السنة، في عهد محمَّد باي، ويتكوَّنُ هذا العهد من مقدِّمة وإحدى عشرة مادة، وتشير المقدمة إلى وجوب الاهتداء بأحكام الشريعة الإسلامية الغرَّاء باعتبار أنَّ الإسلامَ هو الدينَ الرسمي للدولة التونسية، وأن الباي والسكَّان مسلمون، وأن الدولة العثمانية تؤكِّدُ الأمان لرعاياها وتراه من الحقوقِ المَرعيَّة. وتضَمَّنت موادُّ هذا العهد الأمانَ التامَّ لجميع سكَّان تونس د"},{"id":4612,"era":"c13","t":"وفاة مصطفى رشيد باشا رئيس وزراء الدولة العثمانية .","s":"هو مصطفى رشيد باشا الكبير، الصَّدرُ الأعظم ورئيس الوزراء في الدولة العثمانية. ولِدَ باستانبول سنة 1800 م ويعدُّ رشيد باشا أحدَ كبار رؤساء الوزارة في التاريخ التركي، وأحدَ عمالقة الدبلوماسية العثمانية خاصةً في عهد التنظيمات، وكان من دعاة التغريبِ؛ ولذلك كثيرٌ من تنظيماته كانت مقتَبَسةً من النظم الغربية التي تتعارض مع الشريعةِ الإسلامية؛ ولذلك لما أصدر أوَّلَ دستور للبلاد سمَّاه (خطا شريفا) جمع بين "},{"id":4613,"era":"c13","t":"وفاة الشريف محمد بن عون شريف مكة .","s":"هو الشريف محمد بن عبد المعين بن عون بن محسن بن عبد الله بن حسين بن عبد الله بن حسن ابن أبي نمي، ولِدَ بمكة سنة 1204ه،ـ ونشأ بها، ولما استولى محمد علي باشا على مكَّةَ ذهب به إلى مصر وجلس بها عنده مدَّةَ سنواتٍ، ولَمَّا قُتِل الشريف يحيى بن سرور الشريف شمبر بمكة في شعبان سنة 1243هـ تولى عبد المطلب بن غالب إمارةَ مكة وهي إمارته الأولى وبقي أميرًا حتى قَدِمَ محمد بن عبد المعين بن عون من مصر في جمادي ا"},{"id":4614,"era":"c13","t":"عزل السلطان بهادر شاه آخر سلاطين الدولة المغولية الإسلامية بالهند .","s":"عزَلَ الإنجليزُ السلطانَ بهادر شاه الثاني عن الحُكمِ في الهند، ونَفَوه خارج البلاد, وهو آخِرُ سلاطين الدولة الإسلامية التي حكَمَت بلاد الهند، وبعَزلِه انتهى الحكمُ الإسلامي في الهند بعد أن استمَرَّ فيها ثمانية قرون ونصف قرن. كما يعتبر بهادرُ شاه الثاني آخِرَ حكام بني تيمور في الهند، وقد استمر حُكمُ بني تيمور في الهند قرابةَ ثلاثة قرون، وباستعمار الإنجليز بلادَ الهند عانت الهند من تعسُّفِ الإنجليز "},{"id":4615,"era":"c13","t":"تولي الشيخ صباح الثاني بن جابر الحكم في الكويت .","s":"تولى الشيخُ صباح الثاني الحُكمَ بعد وفاة والِدِه الشيخ جابر بن عبد الله الصباح، وكانت فترةُ حُكمِه قصيرةً، وفي فترة حكمه احتفظ بالسلطةِ السياسيةِ وتركَ السلطةَ القضائيَّةَ إلى القاضي؛ حيث كان يتولاها وحدَه وبدون تدخُّلٍ منه، وقد اتَّسَعت التجارةُ في عهدِه وكثُرَت أموال الكويت، وأراد أن يضع رسومًا جمركيَّةً على البضائِعِ الخارجةِ من الكويت لكِنَّ التجَّارَ قالوا له: \" لا تجعَلْ على أموالنا ما لم يج"},{"id":4616,"era":"c13","t":"استقلال رومانيا .","s":"في عام 1821م أُلقِيَ القبض على فلاديميرسكو زعيمِ مولدافيا ونُفِّذَ به حكم القتل بتهمةِ الخيانة؛ لأنه كانت له محاولات للخروجِ عن السلطنة العثمانية. ومع ذلك استمرت الثورات في رومانيا، التي أدَّت إلى معاهدة 1829م التي سُمِح لروسيا بموجِبِها باحتلالِ الإمارات الرومانية. وأصبح أميرُها يُعيَّنُ لمدى الحياة بالتوافُقِ ما بين القيصر الروسي والسلطان العثماني. وبعد عِدَّةِ ثورات قامت في تلك الإمارات قرَّر ا"},{"id":4617,"era":"c13","t":"عزل الأمير عبد العزيز المحمد أبو عليان عن إمارة بريدة  .","s":"عاد الأميرُ عبد العزيز المحمد أبو عليان إلى إمارته في بُريدةَ بعد أن استرضى الإمامَ فيصل بن تركي، ولكنْ لم تكن الثقةُ بينهما تامةً، فالوحشةُ لم تفارِقْ عبد العزيز بل ازدادت؛ ذلك لأن الإمام لا ينظرُ إليه بالعين التي كان ينظرُه فيها، وما زال متَّهمًا عنده لكثرةِ نزعاته وعدم استقامته، ويزيد الإمامَ ما يتواترُ عليه من مهنَّا الصالح من أخبارٍ عن عبد العزيز لم تكُن في مصلحته، ومهنا كان طامِعًا بمركز عبد"},{"id":4618,"era":"c13","t":"بدء أعمال الحفر في قناة السويس .","s":"بدأت في مصرَ أعمالُ حَفرِ قناة السويس، وهي القناة التي تربطُ بين البحرين الأبيض والأحمر، واستمَرَّ الحفر في القناة لمدة 10 سنوات ونصف، وقد شارك فيه 60 ألف فلاحٍ مصري، وبلغ طولُها آنذاك 162,5 كم، وافتُتِحَت للملاحةِ في 19 من نوفمبر 1869م."},{"id":4619,"era":"c13","t":"الفتنة الطائفية في الشام بين الدروز والموارنة .","s":"تجدَّدت الفِتنةُ الطائفية في بلاد الشامِ؛ إذ اعتدى الموارنة على الدروز عام 1276هـ، فقام الدروز يأخُذونَ بالثأرِ، وامتَدَّ اللهيبُ مِن جبل لبنان إلى طرابلس وصيدا وزحلة ودير القمر واللاذقية ودمشق، وأسرعت الدولةُ فأرسلت فؤاد باشا وقضى على الفتنةِ، وعاقب المسؤولين عنها كلًّا بما يستحِقُّ، واحتَجَّت الدُّولُ الأوربية وهدَّدت بالتدخُّلِ، وكانت متفرقةَ الرأي ثم اجتمعت أو اتَّفَقت على أن ترسِلَ فرنسا ستة "},{"id":4620,"era":"c13","t":"الروس يأسرون الشيخ الإمام محمد شامل بعد جهاد طويل للروس .","s":"كان الشيخُ الإمام محمد شامل الداغستاني في عام 1834م قد دعا جميعَ رؤساء القبائل وكبار القضاة إلى اجتماعٍ في منطقةٍ وسطَ جبال القوقاز وتباحَثوا في أمرِ جهادِ الرُّوسِ، فبادر الإمامُ شامل بوضع القواعدِ اللازمة للارتقاءِ بالمقاومة الإسلاميَّةِ ضِدَّ الروس، وحوَّل القبائل إلى شَعبٍ واحدٍ، وقسَّم المناطِقَ إلى أقسامٍ عِدَّةٍ ووضع لكلِّ قسمٍ نائبًا يأخذُ على عاتقه الأمورَ الشرعيَّةَ والعُرفيَّةَ والعسكري"},{"id":4621,"era":"c13","t":"وفاة محمد بن علي السنوسي الكبير صاحب الدعوة السنوسية .","s":"هو محمد بن علي السنوسي الكبير صاحِبُ الدعوة السنوسية، وواحِدٌ من كبار المُصلِحين في العالم الإسلامي في العصر الحديث. ولِدَ بمقاطعة وهران بالجزائر سنة 1202 هـ / 1798م، ورحل إلى فاس سنة 1812م، والتحق بجامِعِ القرويين وبعد تخرُّجِه فيها عُيِّن مدرسًا بالجامعِ الكبير بفاس. عاصرَ دخولَ الدولةِ السعودية الأولى للحجازِ واختلط بعُلَمائِها وأخذ عنهم، ثم عاد إلى ليبيا وقام بدعوته الإصلاحية التي اتخذت الإسلا"},{"id":4622,"era":"c13","t":"عبد الله بن فيصل يؤدب العجمان وآل مرة لفسادهم في الأحساء .","s":"أغار عبد الله بن فيصل على العجمان وآل شامر وبني حسين وآل عذبة من المرة، وانتصر عليهم في وقعةِ الصبيحة بالدوادمي، وملأ يدَه من أموالهم، وقتل منهم خلقًا كثيًرا، وقد كانوا يَعيثون في أطرافِ الأحساء فسادًا، وكان الشيخُ أحمد بن مشرف أرسل قصيدةً لعبد الله بن فيصل يحرِّضُه عليهم ويبَيِّن له خطَرَهم على البلادِ."},{"id":4623,"era":"c13","t":"وفاة الأمير جابر الأول بن عبد الله بن صباح حاكم الكويت .","s":"هو الأميرُ جابر الأول بن عبد الله بن صباح، ثالثُ أمراء الكويت من آل الصباح. ولِدَ في الكويت وأقام في البحرين إلى أن توفِّيَ والده سنة 1229هـ فعاد إلى الكويت وولِيَ إمارتها. وفي أيَّامِه استولت إحدى قبائل العراق على البصرة وطردت حاكِمَها، فلجأ إلى جابر الأول فأنجَدَه بعدة سفُنٍ مزوَّدة بالرجال والمدافع، فاستخلصها فكافأته الحكومةُ العثمانية بمقدارٍ كبيرٍ من التمر كان يُرسَلُ إليه كلَّ عامٍ، وحاولت ح"},{"id":4624,"era":"c13","t":"عودة الأمير عبد العزيز المحمد أبو العليان لإمارة بريدة .","s":"قام بنو عَمِّ عبد العزيز المحمد أبو العليان، وهم: حسن العبد المحسن، وأخوه عبد الله، ومحمد الغانم، وأخوه عبد الله، وقتلوا عبدَ الله بن عبد العزيز بن عدوان، أميرَ بُريدة من قِبَل الإمام فيصل، فلما بلغَ الإمامَ الخبَرُ جعل محمد الغانم أبو العليان أميرًا على بريدة، وبعد مدَّةٍ قليلة أطلق الإمامُ سراحَ عبد العزيز المحمد وأمره أن يرجِعَ أميرًا على بَلَدِه، وأبقى ابنَه عبد الله في الرياض كرهينةٍ؛ لأنَّ ه"},{"id":4625,"era":"c13","t":"غزو عبد الله بن فيصل بن تركي جموع قبيلة العجمان وحلفائها .","s":"تولَّى راكان بن فلاح بن حثلين زعامةَ العجمان بعد تنازُلِ عَمِّه حزام بن حثلين له عن رئاسةِ العجمان, وكان راكان شاعرًا وفارسًا مشهورًا تُروى حوله قِصَصٌ بطولية، واستمر سنواتٍ لا يصدُرُ منه ما يعكِّرُ صفو الأمن أو يثير مشكلاتٍ لحكومةِ الإمام فيصل، لكِنَّه في هذا العام أغار على إبِلٍ للإمام فيصل بن تركي نفسِه وأخذَها، ثم ارتحل إلى الصبيحية القريبة من الكويت، وقام بغاراتٍ على أطرافِ العراق، فجهز الإما"},{"id":4626,"era":"c13","t":"وفاة سليمان باشا الفرنساوي الكولونيل سيف القائد بالجيش المصري .","s":"هو سليمان باشا الفرنساوي، أو الكولونيل سيف، اسمه \"الكولونيل أوكتاف جوزيف انتلم سيف\" ولِدَ عام 1788م في مدينة ليون بفرنسا وهو ضابطٌ فرنسي جاء إلى مصر مع الحملةِ الفرنسية، وبقي بها واعتنق الإسلامَ، وهو من بقايا حروب نابليون. عندما فكر محمد علي في بناء جيشٍ مصريٍّ حديث يحافِظُ على إنجازاته عَهِدَ إليه بتكوينِ النواة الأولى من الضباط، واختار له أسوانَ حتى يبتَعِدَ الطلاب عن القاهرة ومؤثِّراتها والمؤام"},{"id":4627,"era":"c13","t":"لالا فاطمة نسومر تقود القبائل في الجزائر في حرب ضد الفرنسيين .","s":"انضَمَّت لالا فاطمة إلى المقاومة، وشاركت بجانب الشريفِ بوبغلة في المقاومة والدفاع عن منطقةِ جرجرة، فقاومت لالا فاطمة نسومر الاستعمارَ الفرنسي مقاومةً عنيفةً أبدت خلالَها شجاعةً وبطولة متفرِّدتين حتى توفِّيَت في سبتمبر 1863م؛ فقد شاركت في صَدِّ هجمات الفرنسيين عن ولاية \"أربعاء ناث إيراثن\" التابعة لولاية تيزي وزو شرقي الجزائر، فقطعت عليهم طريقَ المواصلات؛ ولهذا انضَمَّ إليها عددٌ من قادة الأعراش وشي"},{"id":4628,"era":"c13","t":"تشكيل لجنة أوروبية وعثمانية للتحقيق في حوادث الستين في لبنان .","s":"شُكِّلت لجنةٌ دوليةٌ تمثِّلُ الدول الأوروبية الكبرى: فرنسا وإنجلترا وروسيا والنمسا وبروسيا، برئاسة فؤاد باشا مندوبِ السلطانِ العثماني ووزيرِ خارجيته، مهمَّتُها التحقيقُ في حوادثِ الستين في لبنانِ، والحيلولةُ دون تجدُّدِها، ورأْبُ الصَّدعِ بين طوائفِ جبل لبنان، ووضع نظام جديد لحُكمه. وبعد أن عَقَدت اللجنةُ عِدَّةَ اجتماعات في بيروت والقسطنطينية ودرست خلالَها مختَلِفَ الشؤون، انتهت إلى عدة قرارات، ك"},{"id":4629,"era":"c13","t":"وقعة الطبعة -سنة الطبعة- على العجمان .","s":"جرت الوقعةُ الكبرى على العجمان، وذلك أنَّ العجمان بعد وقعةِ الصبيحة انتَزَحوا إلى الشمال ونزلوا إلى الجهراءِ في الكويت؛ وذلك ليبتعدوا عن عبدِ الله الفيصل الذي ما زال يطارِدُهم لإزالة شَرِّهم. وفي شهر شعبان خرج عبد الله من الرياض وانضَمَّ إليه سبيع ومطير وبنو هاجر، فحاصروهم في موقعٍ خطيرٍ قريبٍ مِن البحر في منطقة الجهراء فتراجعت قواتُهم تجاهَ البحرِ، فنشبت أرجُلُ جيادهم في الرَّملِ والطين وغرق بعضُ"},{"id":4630,"era":"c13","t":"وفاة الأمير عبد العزيز المحمد أبو العليان أمير بريدة  .","s":"هو الأمير عبد العزيز بن محمد بن عبد الله بن حسن آل أبو عليان، وينتمي إلى العناقر من بني سعدِ بنِ زيد مناة بن بني تميم، أميرُ برُيدة وكانت مدة إمارته 34 سنة من عام 1243هـ إلى 1277هـ، وقد اشتهر بالشجاعةِ والطموحِ الكبير، جَدُّه هو عبد الله بن حسن كان أميرًا على القصيم. عندما عَزَل الإمام تركي بن عبد الله الأميرَ محمد بن علي الشاعر عن إمارة بُرَيدة جعل مكانَه عبد العزيز المحمد أبو عليان، ثمَّ لَمَّا "},{"id":4631,"era":"c13","t":"تشكيل الدولة العثمانية لواء ذي استقلال ذاتي في جبال لبنان .","s":"شكَّلت الدولةُ العثمانية لواءً له استقلالٌ ذاتيٌّ في جبال لبنان، وكان مركزُه \"دير القمر\"، وبلغت مساحته 3100 كم2، وكان يقطنُه النصارى، وظَلَّ الاستقلال الذاتي لهذا اللواء لمدة 53 عامًا حتى سنة 1914م."},{"id":4632,"era":"c13","t":"وفاة السلطان العثماني عبد المجيد الأول وتولي أخيه عبد العزيز .","s":"هو الخليفةُ العثماني عبد المجيد الأول بن محمود الثاني بن عبد الحميد الأول بن أحمد الثالث بن محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول بن بايزيد الثاني. كان السلطانُ عبد المجيد الأول ضعيفَ البنية شديدَ الذكاء، واقعيًّا ورحيمًا، وهو من أجلِّ سلاطين آل عثمان قدْرًا، تولَّى الحُكمَ بعد وفاة والِدِه السلطان محمود الثاني سنة "},{"id":4633,"era":"c13","t":"وفاة أحمد الباي سلطان تونس .","s":"هو أحمدُ الباي سلطان تونس، وكان قد حاول أن يقيمَ بتونس نهضةً إصلاحية محاولًا الاستفادةَ من تجربة محمد علي باشا بمصرَ."},{"id":4634,"era":"c13","t":"تأسيس أول بلدية عربية للقدس .","s":"تمَّ تأسيسُ أوَّلِ بلدية في القُدسِ بشَكلٍ شِبهِ منظَّم، وكانت عبارةً عن مجلسٍ محليٍّ ذي سلطة محدودة وميزانية لا تتعدى (500) جنيه ذهبي في السنة، ثم صدر قانون الأقاليم (1864) الذي يتضَمَّنُ أحكامًا محدودة عن تشكيلِ البلديات. وقد بَقِيَ الوضع على ما هو عليه حتى عام (1918) حين دخل الإنجليز المدينة، وأصبحت البلديةُ تدارُ من قِبَلِ أربعةِ أشخاص من العرب، واثنين من اليهود، وفي عام 1948م وبعد الاستيلاء ا"},{"id":4635,"era":"c13","t":"وفاة الإمام محمد شامل الداغستاني  .","s":"هو الإمامُ محمد شامل الداغستاني قائدٌ سياسي في شمال القوقاز وأحدُ أشهر المقاومين للوجودِ الروسي في بلاد القوقاز، ولِدَ عام 1797م في قرية غيمري، الداغستانية, وهو ثالِثُ أئمة الشيشان وداغستان من 1834 – 1859 م لقِّبَ بأسد القفقاس، وصقر الجبال. قاد المقاومةَ ضِدَّ الروس خلالَ حروب القوقاز حين اختاره المريدون بعد وفاةِ حمزة بيه في عام 1834م، فأعاد شامِلٌ تنظيمَ جيش ِالمريدين على نمطِ أعدائه الكوزاك بشك"},{"id":4636,"era":"c13","t":"محاولة الصلح بين أهل عنيزة وعبد الله بن فيصل .","s":"طالت الحربُ مع أهل عنيزة بعد قَتْلِ أميرهم عبد العزيز المحمد أبو العليان وأثناء حصارِ عُنيزة حاول الأميرُ طلال بن رشيد أن يعقِدَ صلحًا بين عبد الله وأهل عنيزة، فأرسل سرًّا إلى الأمير عبد الله اليحيى السليم وزامل العبد الله أنَّ الإمام لا يكره الصلحَ ووَقْفَ القتالِ إذا كان طلبُ الصلح منكم، فأنابوه عنهم وقالو له إنَّك مفوَّضٌ مِن قِبَلِنا، فعرض على عبد الله رغبةَ أهل عنيزة في الصلحِ، فقال: عبد الله"},{"id":4637,"era":"c13","t":"وفاة السلطان محمد بهادر آخر سلاطين الدولة الإسلامية بالهند .","s":"هو السُّلطان أبو الظفر سِراجُ الدين محمد بهادر شاه الثاني، آخِرُ سلاطين الدولة الإسلامية في الهند، وقد أصبح إمبراطورًا عند وفاة والده سنة 1838هـ وشهِدَت فترةُ حكمه الثورةَ الهندية التي كادت تقضي على الإنجليز وتُخرِجُهم من الهند، وكان الهنودُ قد اختاروه قائدًا لهم على الرغم من كبر سنِّه، لكِنَّ الثورة لم تنجَحْ؛ حيث قبض الإنجليزُ على بهادر شاه، ونفوه خارج الهند. وبنفيه انتهى الحكمُ الإسلامي في الهن"},{"id":4638,"era":"c13","t":"زيارة السلطان العثماني عبد العزيز لمصر .","s":"قام السلطان العثماني عبد العزيز بزيارة لمصر، وتعَدُّ زيارته هذه هي الزيارةَ الثانيةَ لسلاطين الدولة العثمانية لمصر؛ حيث كانت الأولى في عهد السلطان سليم الأول عند فتح مِصرَ، أي: قبل 345 عامًا."},{"id":4639,"era":"c13","t":"إعلان الميرزا حسين علي دعوته البهائية .","s":"أعلن الميرزا حسين علي دعوتَه البهائية، وأنَّه الوريثُ الحقيقي للباب علي بن محمد الشيرازي مؤسِّس فرقة البابية الضالة. وفي عكَّا بذل البهاءُ جُهدًا كبيرًا في نشر دعوتِه وكسْبِ الأنصار والأتباع، فأعلن حقيقةَ شَخصِه، وأبطل ما كان يدَّعيه \"الباب\" حتى انسلخ هو وأتباعُه من شريعة الباب، ولم يبقَ مِن كلامه إلا ما كان فيه إشارةٌ أو إيماءة تبشِّرُ بمَقدَم البهاء، ولم يكتفِ بادعاء النبوة، بل تجاوزها إلى ادِّع"},{"id":4640,"era":"c13","t":"حصول الخديوي إسماعيل على فرمان (قانون) مصر من الدولة العثمانية .","s":"نجح الخديوي إسماعيل في الحُصولِ على فرمان (قانون) من الدولةِ العثمانية عُرِفَ بـ\"فرمان مصر\" يقضي بانتقال ولاية مصرَ مِن الأبِ إلى الابنِ الأكبر، وهو ما مهَّد الطريق لمحمد توفيق باشا ابن إسماعيل لتولِّي الحُكم في مِصرَ."},{"id":4641,"era":"c13","t":"وفاة لالا فاطمة نسومر .","s":"هي لالا فاطمة نسومر، وتسمى أيضًا لالة فاطمة، واسمُها الحقيقي هو (فاطمة سيد أحمد محمد بن عيسى)، و\"لالة أو لالا\" هي لفظةُ توقير أمازيغية تعني \"السيدة\" وهي من أبرز وجوه المقاومة الشعبية الجزائرية في بدايات الغزو الفرنسي للجزائر. وُلِدَت لالا فاطمة نسومر بقريةِ ورجة قرب عين الحمام سنة 1246هـ /1830م في أسرةٍ تنتمي إلى الطريقة الرحمانية، وأبوها محمد بن عيسى مقدَّم زاوية الشيخ سيدي أحمد أومزيان شيخ الطري"},{"id":4642,"era":"c13","t":"ظهور التلمود مطبوعًا في وارسو ببولندا  .","s":"ينقَسِمُ التلمود إلى جزئين هامَّين: 1- المشناه Mishnah، وهو الأصل (المتن) 2- جمارا Gamara، وهو شرح المشناه. ومشناه أولُ لائحة قانونية وضعها اليهودُ لأنفسهم بعد التوراة، جمعها يهوذا هاناسي Judah Hanasi فيما بين 190 و200 م، أي: بعد قرن تقريبًا من تدميرِ تيطس الروماني الهيكل. أمَّا جمارا فاثنان: جمارا أورشليم (فلسطين). وجمارا بابل. جمارا أورشليم (أو فلسطين) هو سجِلٌّ للمناقشات التي أجراها حاخامات فلس"},{"id":4643,"era":"c13","t":"صدور قانون التصفية بمصر .","s":"هو قانونٌ أصدرَتْه وزارة رياض باشا، في عهدِ الخديوي توفيق، ونصَّ على تخصيص أكثَرَ مِن نصف إيرادات مصر السنوية لتسديدِ الديون لصالح الدائنين الأجانب. وكانت نتائجُ قانون التصفية: (أ) زيادةُ التدخُّل الأجنبي (ب) سوءُ الأحوال الاقتصاديةِ في البلاد."},{"id":4644,"era":"c13","t":"تنازل الدولة العثمانية عن بناء القلاع والحصون بأراضي إمارة الجبل الأسود .","s":"تنازلت الدولةُ العثمانية عن بناء القلاع بأراضي إمارة الجبَلِ الأسود الواقعة على شاطئ الأدرياتيكي إلى الشمالِ من ألبانيا، وكانت إمارةُ الجبل الأسود خاضعةً لحكم الدولة العثمانية، وأراد أميرُها الاستقلالَ بحُكمِها كما قام بمساعدة ثوَّار إقليم (الهرسك) ضِدَّ الدولة العثمانية التي ما لبث أن تمكَّنَت من القضاء تمامًا على جميع حركات التمَرُّد، وشرعت في بناء عِدَّةِ قلاع وحصون داخِلَ بلاد الجبل الأسود، فت"},{"id":4645,"era":"c13","t":"بداية الفتنة بين ابناء الإمام فيصل بن تركي .","s":"لم تكن الفتنةُ بين عبد الله وسعود أبناء فيصل بن تركي وليدةَ الساعة بعد وفاة والدهما، بل كانت روحُ التنافس موجودة بينهما من أيام والدهما؛ ولذلك جعل فيصل سعودًا أميرًا على الخَرجِ والأفلاج ومناطق جنوب بلاد العارض، وما أن توفي فيصل حتى ثار سعودٌ على أخيه عبد الله ينازعه في الحكمِ، واتجه إلى عسير ونزل على حكامِها آل عايض يطلب العونَ والمساعدة في حربِه على أخيه بحجَّةِ أنه كان يهينُه ولم يَرْعَ حَقَّه،"},{"id":4646,"era":"c13","t":"وفاة الإمام فيصل بن تركي بن عبد الله  .","s":"هو الإمامُ فيصل بن تركي بن عبد الله بن محمد بن سعود بن محمد بن مقرن، أحَدُ حكَّامِ الدولة السعودية الثانيةِ، وكان إمامًا شجاعًا حازمًا، عُرِف بحسن التدبير والعَدلِ في الرعيَّة، كان مِن ضمنِ مَن نفاهم إبراهيم باشا لمصر بعد تدميرِ الدرعية، وتمكَّن فيصل من مغادرة مصر والعودة إلى نجد عام 1242هـ وأصبح ساعِدَ والده الأيمنَ في توطيد دعائم الدولة وتوسيع رقعتها. ثم وليَ الحكم بعد مقتَلِ أبيه سنة 1249هـ، إل"},{"id":4647,"era":"c13","t":"بريطانيا تسيطر على إمارات الخليج العربي .","s":"استطاعت بريطانيا أن تثبِّت قَدَمَها في الخليج العربي عمومًا، بل أصبحت تَعُدُّ نفسَها وصيةً على الخليج، فأصبحت تتدخَّلُ أيضًا في حل النزاعات القائمة بين الولايات في الخليج العربي، فلمَّا حصلت مشاكِلُ بين أتباع الشيخ محمد بن عبد الوهاب وبين ثُويني حاكم مسقط، وهاجم أتباعُ الشيخ محمد بن عبد الوهاب مسقَطَ طلَبَ ثويني المدافِعَ والمعونات المالية من الإنجليز، خرجت السفن الإنجليزية من الهند إلى مسقط، وكان"},{"id":4648,"era":"c13","t":"وفاة الأمير طلال ابن رشيد .","s":"هو الأميرُ طلال بن عبد الله العلي الرشيدي الشمري، ثاني حُكَّام إمارة حائِل، فقد خَلَف أباه بشكلٍ سلِسٍ وبموافقة عمِّه عبيد بن عبد الله الذي كان المرشَّحَ لخلافة أخيه عبد الله؛ إذ كان يُتوقَّعُ أن يتولى عبيد بن عبد الله أخو عبد الله وعمُّ طلال: حُكمَ حائل بعد وفاة الأمير عبد الله. فقد كان عُبيد المؤسِّسَ الثاني للدولة، ولكِنَّ عبيدًا رشَّح طلالًا للحكم بعد وفاة عبد الله، ووافق جماعةَ حائل مواطِنوها"},{"id":4649,"era":"c13","t":"وفاة الشيخ عبد الله بن عبد الرحمن أبا بُطَيْن .","s":"هو الإمامُ العلَّامة الفقيه الشيخ عبد الله بن عبد الرحمن بن عبد العزيز بن عبد الرحمن بن عبد الله بن سلطان بن خميس، الملقَّب كأسلافه أبا بُطَيْن -بضم الباء وفتح الطاء وسكون الياء- من عوائل قحطان، العائذي نسبًا، الحنبلي مذهبًا، النجدي بلدًا، فقيه الديار النجديَّة في عصرِه، وإمامٌ من أئمة العلم في زمنه, ولِدَ الشيخ في بلدة الروضة من بلدان سدير، لعشر بقين من ذي القعدة سنة 1194هـ, ونشأ بها وقرأ على عال"},{"id":4650,"era":"c13","t":"معركة المعتلا بين أبناء الإمام فيصل .","s":"لَمَّا حشد سعودٌ حشوده في الجنوب خرج إلى الرياض، فالتقى مع قوات أخيه عبد الله التي كان يقودها أخوه محمد بن فيصل في معركة المعتلا، وهي أول معركة بين أبناء الإمام فيصل عبد الله وسعود، وقد قُتِلَ فيها عددٌ كبير من الطرفين، وخاصة أتباع سعود، وجُرِحَ فيها سعود جروحًا بليغة، وأصيب في إحدى يديه، فلجأ إلى آلِ مرة في شرق البلاد، وبقي عندها للتداوي حتى بَرِئت جراحُه."},{"id":4651,"era":"c13","t":"تولي الشيخ عبد الله الثاني بن صباح الثاني الحكم في الكويت .","s":"تولى الشيخُ عبد الله الثاني بن صباح الثاني بن جابر الأول -من آل صباح، خامس أمراء الكويت- إمارةَ الكويت بعد وفاة أبيه الشيخ صباح الثاني عام 1866، وقد استماله الترك العثمانيون فسَمَّوه قائم مقام في الكويت، وكان للكويت في عهده أسطولٌ من السفن الشراعية الكبيرة، وكانت أهمُّ الأحداث في عهده: (1) هو أول حاكم للكويت يسكُّ عملة كويتية عليها اسم الكويت عام 1866م. (2) في عام الهيلق 1867م تعرضت الكويت إلى مجا"},{"id":4652,"era":"c13","t":"صدور لائحة مجلس شورى النواب في عهد الخديوي إسماعيل .","s":"صدرت لائحةُ مجلس شورى النوَّاب في عهد الخديوي إسماعيل، وكان رئيسُ المجلس ووكيلُه هما اللذان يعيِّنُهما الخديوي دونَ أن يكونَ للمجلس رأيٌ في هذا، وكان عددُ أعضاء المجلس لا يزيدُ على خمسة وسبعين عضوًا, وجديرٌ بالذكر أنَّ هذا المجلس كان من بدايات الأخذِ بالنظام النيابي في مصرَ والعالم الإسلامي."},{"id":4653,"era":"c13","t":"سنة الهيلق (الهلاك) .","s":"سنة الهيلق، وهي مجاعةٌ حلَّت في الكويت في عهد الشيخ عبد الله الثاني بن صباح الثاني الصباح, والهيلق كَلِمةٌ تعني الهلاك أو الهلك. حيث تعرَّضت الأقاليم المجاورة لإمارة الكويت لجفافٍ هائلٍ لم يكن بالحسبان حتى اضطروا إلى أكلِ ذمامِ البهائم التي تُذبَح, وكانت الكويتُ محصَّنة ولديها إمكانيةٌ لمواجهة مثل هذا الجفاف. فأصبحت الكويتُ الوجهة الرئيسيَّةَ للمنكوبين. وكانت يدُ الخير تنتظِرُهم حيث أمدُّوهم بالما"},{"id":4654,"era":"c13","t":"افتتاح قناة السويس رسميًّا في حفلة حضرها ملوك ورؤساء .","s":"افتُتِحت \"قناة السويس\" -التي تربط بين البحر الأبيض المتوسط والبحر الأحمر- أمامَ الملاحة الدولية، وقد بدأت أعمالُ الحفر في هذه القناة في 24 من إبريل 1859م، وشارك فيها 60 ألف فلاحٍ مصري، وبلغ طول القناة 162.5 كم, وقد دعا الخديوي إسماعيل حاكِمُ مصر أباطرةَ وملوك العالم وقريناتِهم لحضور حفلِ افتتاح قناة السويس، والذى تم في 16 نوفمبر 1869، وقد كان حفلًا أسطوريًّا، روعِيَ فيه الاهتمام بنظافة المدينة، وت"},{"id":4655,"era":"c13","t":"صدور مرسوم \"كريميو\" الذي يمنح الجنسية الفرنسية لليهود في الجزائر .","s":"صدر مرسومُ كريميو الفرنسي الذي يمنح اليهودَ في الجزائر الجنسيَّةَ الفرنسيَّةَ، ويتضمَّنُ في داخله هدفَ توطين العنصر الأوروبي في الجزائر، مع ما ترتَّـب على ذلك من امتيازات وظيفية واجتماعية لم يكن يتمتّـَعُ بها مواطِنوهم المسلمون في ظِلِّ الاحتلالِ الفرنسي."},{"id":4656,"era":"c13","t":"معركة بئر جودة .","s":"بعد معركة المعتلا سنة 1283 عزل عبد الله بن فيصل أميرَ الأحساء محمد السديري بعد أن اتَّهَمه بالضعف في موقِفِه من بعض قبائل العجمان وبني مرة التي أيَّدت سعودًا وعيَّنَ خلفًا له ناصر بن جبر الخالدي، كما أرسل قواتٍ بقيادة أخيه الصغير عبد الرحمن لشرق البلاد لمراقبة تحُّركات سعود ومؤيديه، فانتقل سعود من البريمي إلى البحرين التي ساعده شيخُها بقوات ناوشت الحامية النجديَّةَ في قطر، ثم عزز سعودٌ قواتِه بمسا"},{"id":4657,"era":"c13","t":"حركة محمد المقراني الجهادية في الجزائر .","s":"في الجزائر انطلق محمد المقراني مجاهدًا في سبيل الله ثائرًا على المغتصبين الفرنسيين الصليبيين، مدافعًا عن حقوق العباد، فزحف على بلدة البرج في تاريخ 28 ذي الحجة 1287هـ / 16 آذار 1871م وفي الوقت نفسِه أمر أخاه بو مرزاق بالتحرُّك في منطقة سور الغزلان، وابنَ عمِّه وصهرَه السعيد بن داود بالتحرُّك في منطقة الحضنة وبلاد أولاد نائل، وابنَ عمه الثاني بوزيد بن عبد الرحمن بالزحف إلى البرج مع خمسة عشر ألف مقات"},{"id":4658,"era":"c13","t":"إنشاء كلية دار العلوم لإحياء اللغة العربية .","s":"أمر الخديوي إسماعيلُ باشا وزيرَ معارفه علي باشا مبارك بإنشاء دار العلوم عام 1872م لتصبحَ مؤسَّسةً تنويريَّةً حضارية، وقد أضيفت إلى جامعة القاهرة 1946م. وكانت كلية (دار العلوم) من قَبلُ تسمى (مدرسةَ دار العلوم)، وقد تطوَّرت (دار العلوم) إلى أن أصبحت إحدى المدارس العالية، وظلَّت كذلك إلى أن ضُمَّت لجامعة القاهرة، وأصبحت تسمى (كلية دار العلوم) محتفظةً باسمها التاريخي العزيز، وكلمة (علوم) التي يضمها ا"},{"id":4659,"era":"c13","t":"أحوال الأحساء تحت الحكم العثماني .","s":"بدت علاماتُ تذمُّر الأهالي من الحُكم التركي؛ لكثرة الضرائب الباهظة التي فُرِضَت عليهم ممَّا جعلهم يفكرون كثيرًا في الثورة على العثمانيين بالإضافة إلى اضطراب الأمن وتدهور التجارة؛ بسبب كثرة الثورات القبلية في المنطقة الممتدَّة في شرق البلاد من الكويت إلى قطر، واعتدائهم على القوافل التجارية بالنَّهبِ والسلب كلما سنحت لهم الفرصُ، وعودة القرصنة في السواحل الشرقية؛ بسبب ضعف سيادة الدولة العثمانية في ال"},{"id":4660,"era":"c13","t":"حملة عثمانية لضم قطر لحكمها .","s":"بعد دُخول العثمانيين الأحساءَ أشار قاسم بن ثاني على نافذ باشا أن يتقدَّم بقواته لاحتلال قطر؛ لأنه كان يخشى امتدادَ سلطة آل خليفة أعوان الإنجليز، فكان لا بدَّ أن يضع بلاده تحت حماية الترك بدلًا من ابتلاعها مِن آل خليفة، أو اللجوء إلى حماية الإنجليز. ومن الأحساء خرجت قوةٌ عسكرية احتلت قطر واتخذت الدوحة مركزًا لها."},{"id":4661,"era":"c13","t":"وفاة الشيخ محمد المقراني .","s":"الشيخُ محمد المقراني هو أحدُ قادة الثوراتِ الشعبيَّة الجزائرية بعد الغزو الفرنسيِّ للجزائر عام 1830م. ومحمد المقراني هو ابن أحمد المقراني أحد قواد منطقة مجانة الهضاب العليا، وبعد وفاة الأب عُيِّن مكانَه ابنه محمد المقراني، لكن بلقب منحَتْه إياه السلطات الفرنسية، والذي كان \"باشا آغا\" وامتيازاته أقَلُّ من امتيازات أبيه, تحدر من زعماء سلطنة بني عباس في القرن السادس عشر الميلاد من آخر سلطان حفصي في بج"},{"id":4662,"era":"c13","t":"معركة \"البرة\" بين الأخوين سعود وعبد الله ابني فيصل بن تركي .","s":"في محرَّم من هذه السنة بدأ سعود بن فيصل بالزَّحفِ من الأحساء نحو الرياض. وحينما عَلِمَ أخوه عبد الله بن فيصل باقترابه، غادر العاصمةَ متوجهًا إلى قحطان بوادي أعوانه؛ طلبًا للحماية. ودخل سعود بن فيصل الرياضَ بدون قتال، وحكَمَها للمرَّةِ الأولى، ونكل أتباعُه بسكَّانِها جزاءً لموقف أهلها العدائيِّ منه، وكثر الهرج والمرج في منطقة العارض. كتب سعودٌ إلى رؤساء البلدان، فقَدِمَت عليه وفود من مناطق نجد تعلِ"},{"id":4663,"era":"c13","t":"وفاة محمد أمين عالي باشا رئيس الوزراء في الدولة العثمانية .","s":"هو محمد أمين عالي باشا، سياسي عثماني، وأحدُ السياسيين البارزين في الإصلاحات السياسية المعروفة باسم التنظيمات التي شهدتها الدولة العثمانية في منتصف القرن التاسع عشر، ولِدَ عالي باشا باسطنبول سنة 1815م، وتمكَّن بفضل إجادته للغة الفرنسية من الالتحاق بالسلك الدبلوماسي العثماني في صَدرِ شبابِه، فعُيِّنَ بدائرة الترجمة، ثم سكرتير السفارة العثمانية في فيينا، ثم منصب وزير الخارجية، ثمَّ عيِّنَ سفيرًا للدو"},{"id":4664,"era":"c13","t":"حملة عثمانية لضم الأحساء لحكمها  .","s":"بعد خروج عبد الله بن فيصل من الرياض وسيطرة أخيه سعود على الحكم فيها، توجه عبد الله لعدد من الجهات طلبًا للمساعدة ضِدَّ أخيه سعود، فاتصل بآل سليم في القصيم، وابن رشيد في حائل، ولَمَّا لم يجد منهم العون أرسل إلى العراق عبد العزيز أبا بُطين ومعه ثلاث رسائل، الأولى لمدحت باشا والي بغداد، والثانية إلى خليل بك والي البصرة، والثالثة إلى السيد محمد الرفاعي نقيب الأشراف، يطلب من الحكومة العثمانية المساعدةَ"},{"id":4665,"era":"c13","t":"ثورة أهل الرياض على سعود بن فيصل وعودة أخيه عبد الله لحكم الرياض  .","s":"بعد استقرارِ سعود في الرياض تعرَّضت نجد لمجاعة شديدة، واحتل الأتراك الأحساء ولم يفُوا بوعدهم لعبد الله بن فيصل بتسليمه حكمَ الأحساء، فشجَّعَ هذا والمجاعة أهلَ الرياض في الثورة على سعود بن فيصل، فخرج من الرياض إلى الخرج والدلم، حيث يوجد عددٌ من القبائل المؤيِّدة له، وعيَّنَ أهلُ الرياض عمَّ سعود عبد الله بن تركي، ولَمَّا علم عبد الله بن فيصل بثورة الرياض على أخيه سعود ونما إلى علمه أيضًا أن الأتراك"},{"id":4666,"era":"c13","t":"عودة سعود بن فيصل لحكم الرياض للمرة الثانية .","s":"لَمَّا استقرَّ عبد الله بن فيصل في الحكم في الرياض بعد ثورة أهل الرياض على أخيه سعود، بدأ سعود يحشد أعوانه من مناطق الجنوب الخرج والدلم والأفلاج ووادي الدواسر، وقرَّرَ محاربة أخيه عبد الله الذي أرسل جيشًا بقيادة أخيه محمد للاستيلاء على الخرج مركزِ تحرُّك سعود، لكنَّ قوات سعود تمكَّنَت من هزيمة قوات محمد، وأسرت عمَّ سعود عبد الله بن تركي الذي كان يرافِقُ الحملة، وسجنه حتى توفِّيَ في سجنه، ثم لاحقت "},{"id":4667,"era":"c13","t":"محاولات سعود بن فيصل استعادة الأحساء من العثمانيين .","s":"كان سعود بن فيصل منذ اللحظة الأولى التي تسلَّم فيها حكم الرياض في المرة الأولى سنة 1288هـ قرَّر أن يعمل على استعادة إقليم الأحساء للدولة من العثمانيين، إما عن طريق القوة أو عن طريق السِّلم، فأرسل إلى بلي المقيم البريطاني في الخليج العربي رسالةً يذكُرُ فيها أنه الآن حاكم نجد ومسيطرٌ على الوضع تمامًا، وغرضه أن يحُلَّ السلام بين السكان بعد أن سيطر على ما بحوزة أخيه عبد الله الموالي للترك، وأنَّ علاقت"},{"id":4668,"era":"c13","t":"وفاة رفاعة رافع الطهطاوي .","s":"هو رفاعةُ رافع بن بدوي بن علي الطهطاوي، ولِدَ سنة 1216هـ - 1801م، بطهطا إحدى مدن محافظة سوهاج بصعيد مصر, وقصد القاهرةَ سنة 1223هـ - 1817م، فتعلم في الأزهر, وبعد تخرُّجه منه عام 1824م خدم كإمام في الجيشِ النظامي الجديد, ثم أرسلَته الحكومة المصرية سنة 1826م إمامًا للصلاة والوعظ مع بعثةٍ مِن الشبان أوفدتهم إلى فرنسا لتلقِّي العلوم الحديثة، فدرس الفرنسيَّةَ والجغرافية والتاريخ، وفُتِنَ بالحضارةِ الغرب"},{"id":4669,"era":"c13","t":"وفاة الشيخ عثمان بن عبد الله بن بشر .","s":"هو الشيخُ عثمان بن عبد الله بن عثمان بن أحمد بن بشر, من الحراقيص من قبيلة بني زيد، النجدي مسكنًا، الحنبلي مذهبًا، السلفي اعتقادًا، من رؤساء بني زيد القبيلة المعروفة المشهورة أهل شقراء وغيرها، والمعروف باسم ابن بِشر، وهو مؤرخ وأديب عاصرَ الدولة السعودية الأولى والثانية، ودوَّن أحداثهما في كتابه: (عنوان المجد في تاريخ نجد). ولِدَ ابن بشر في جلاجل سنة 1194هـ ونشأ فيها يتيمًا، وتعلم القراءة والكتابة، "},{"id":4670,"era":"c13","t":"توقيع المعاهدة الخاصة بتأسيس الاتحاد الدولي للبريد، في سويسرا .","s":"تمَّ توقيع المعاهدة الخاصة بتأسيس الاتحاد الدولي للبريد، وذلك بعد اجتماعٍ عقدته 22 دولة في مدينة بيرن السويسرية، من بينها 20 دولة أوروبية، بالإضافة إلى الولايات المتحدة ومصر، وكان يسمَّى آنذاك \"الاتحاد العام للبريد\"."},{"id":4671,"era":"c13","t":"وفاة الأمير سعود بن فيصل بن تركي .","s":"هو الأمير سعود بن فيصل بن تركي بن عبد الله آل سعود، ثاني أبناء الإمام فيصل، لقِّبَ بـ (أبو هلا) لكرمِه وكثرة ترحيبِه بالضيف. وقد حكم في الدولة السعودية الثانية من 1288 إلى1291هـ (1871- 1875م) كان أبوه قد ولَّاه أميرًا على الخرج عام 1263هـ/ 1846م واستمرَّ في هذه الإمارة مدةً طويلة، وقد أكسبه ذلك قاعدةً شعبية في تلك المنطقة. أما أخوه عبد الله، الذي يكبرُه في السن، فقد كان أبوه قد عيَّنه وليًّا للعهد"},{"id":4672,"era":"c13","t":"افتتاح المحاكم المختلطة في مصر -أي التي تشمل المصريين وغيرهم_ .","s":"تمَّ إنشاء المحاكِم المختَلطة في مصر بناءً على اتفاق بين مصر والدول التي كانت لرعاياها امتيازاتٌ تفوق امتيازاتِ المواطن المصري. وذلك للفصلِ في المنازعاتِ التي تنشأ بين المصريين والأجانب. أو بين الأجانبِ مختلفي الجنسية؛ حيث أرادت الدولة المصرية أن تخفِّفَ مِن استبداد نظام الامتيازات الذي كان يتمتَّعُ به الأجنبي."},{"id":4673,"era":"c13","t":"آل مهنا يثورون على آل عليان يستولون على حكم بريدة  .","s":"كان الإمام فيصل عيَّنَ مهنا الصالح أميرًا على بريدةَ ثمَّ عزَلَه عن الإمارة، وفي هذه السنة ثار مهنا الصالح على آل عليان أمراء بريدة، واغتصب منهم الإمارة وأجلاهم إلى عُنيزة، ولكِنَّ مهنا لم يلبث أن قتله آل عليان، ولكن أنصارَ مهنا وابنه حسن قتلوا القَتَلةَ من آل عليان وتولى حسن إمارةَ بُرَيدة بعد والدِه."},{"id":4674,"era":"c13","t":"حكم أولاد سعود بن فيصل للرياض ثم عودة عمهم عبد الله للحكم .","s":"لم تنته الفتنة بين أبناء فيصل بموت سعود، بل استمَرَّت إلى أبعَدَ من ذلك؛ ففي عام 1291 هـ تولى عبد الرحمن بن فيصل إمامةَ نجدٍ بعد وفاة أخيه سعود، ومضى في حكمِه على أتمِّ وجه حوالي السنة، وبعدها اضطربت الأوضاعُ بالنسبة لعبد الرحمن؛ إذ جاء أخوه عبد الله الإمامُ الشرعي ومعه أخوه محمد من بادية العجمان -حيث كانا لاجئينِ سياسيينِ هناك- إلى الرياض ومعهما قوات من بدوِ عتيبة ومِن حَضَرِ الوشم، والتقيا بقوات"},{"id":4675,"era":"c13","t":"ظهور الحركة المهدية ودروها في هزائم المستعمرين الإنجليز .","s":"تولى الخديوي إسماعيل الحُكمَ، وكانت الحركةُ الاستعماريةُ في عنفوانِها، فخاف أن يقَعَ السودان فريسةَ احتلال أوروبي، فوضع خطةً واسعةَ المدى لاستكشاف منابعِ النيل وحمايةِ الوطن السوداني، ولكِنَّه ارتكب خطأً فادحًا؛ إذ عَيَّنَ رجلًا إنجليزيًّا هو السير «صمويل بيكر» حاكمًا عامًّا على السودان؛ ذلك لأن صمويل بيكر هذا كان شخصيةً استعمارية صليبيةً شديدةَ الحقد على المسلمين، اتَّبَع سياسةً خبيثة ترمي لهدفين"},{"id":4676,"era":"c13","t":"موقف آل رشيد من نزاع أبناء فيصل بن تركي .","s":"يرجِعُ تأسيسُ إمارة آل رشيد في جبل شمر إلى عبد الله بن علي بن رشيد، الذي كان صديقًا حميمًا لفيصل بن تركي؛ حيث قام بدورٍ كبير في استعادة فيصل للحُكمِ بعد مقتَلِ والده تركي، فكافأه بأن عيَّنَه عام 1251 ه أميرًا على حائل وجبل شمر، على أن يكون الحُكمُ فيها وراثيًّا في أسرته من بَعدِه، مستقلًّا إداريًّا تحت حكم آل سعود. حكم عبد الله بن رشيد 12 سنة، واستمر حكمُ أسرته لجبل شمر 90 سنة، وقد قام آل رشيد بدو"},{"id":4677,"era":"c13","t":"ثورة البلغار على الدولة العثمانية .","s":"قامت ثورةُ البلغار في نفس الوقت الذي قام فيه نصارى البوسنة والهرسك بثورتِهم بدعمٍ مِن النمسا والدول الأوروبية وخاصةً روسيا، فقد تأسَّسَت جمعياتٌ في بلاد البلغار؛ لنَشرِ النفوذ الروسي بين النصارى الأرثوذكس والصقالبة، وكانت تدعَمُها روسيا وتمدُّها بالسِّلاحِ، وتبذُلُ هذه الجمعياتُ بدورها جهدَها لإثارة سكَّان الصرب والبوسنة والهرسك، وتحَرِّضُهم على الثورة ضِدَّ العثمانيين. وعندما أنزلت الدولةُ العثما"},{"id":4678,"era":"c13","t":"خلع السلطان العثماني عبد العزيز وتولية ابن أخيه مراد الخامس .","s":"ظنَّ السلطان عبد العزيز بن محمود الثاني أنَّه إذا تقرَّب إلى الروس فإن ذلك سيؤثِّرُ على الدول الأوربية الغربية لتقديمِ تساهلاتٍ أكثَرَ للدولة العثمانية، فخافت الدولُ الأوربية فأشاعت عنه التبذيرَ والإسرافَ، وتولى رئيسُ مجلس الشورى أحمد مدحت باشا فكرةَ عَزلِه، كما تواطأ معه شيخُ الإسلام حسن خير الله أفندي -المنتمي لحركة تركيا الفتاة- فأصدر فتوى شرعية تفيدُ بعَزلِه, فعُزِلَ السلطان عبد العزيز في هذا "},{"id":4679,"era":"c13","t":"خلع السلطان العثماني مراد الخامس وتولية عبد الحميد الثاني .","s":"لم يلبَث السلطانُ مراد الخامس بن عبد المجيد إلَّا ثلاثة وتسعين يومًا في الخلافةِ حتى قيل إنَّ جنونَ السلطانِ ظهر للناس بشكلٍ واضحٍ، فكان لا بدَّ من خلعِه، وأعلن ذلك من قِبَل شيخِ الإسلامِ عام 1876م وكان نص الفتوى: \"إذا جُنَّ إمامُ المسلمين جنونًا مُطبِقًا ففات المقصودُ من الإمامةِ، فهل يصِحُّ حلُّ الإمامة من عهدته؟ الجواب: يصِحُّ، والله أعلم. كتبه الفقير حسن خير الله أفندي، فتم عزلُه في العاشر من "},{"id":4680,"era":"c13","t":"ولايتا الصرب والجبل الأسود تشهران الحرب على العثمانيين .","s":"اشتعلت الثَّوراتُ في الهرسك بتحريضٍ من الجبل الأسود ومِن الصرب، ولكنْ سرعانَ ما استطاعت الدولةُ العثمانيةُ إخمادَ الثورة، ولَمَّا رَغِبَ السلطانُ عبد الحميد الثاني في مَنْعِ الدول الأوربية من التدخُّلِ، أصدر مرسومًا بفصل القضاءِ عن السلطة التنفيذية، ويتم انتخابُ القُضاةِ عن طريق الأهالي، والمساواة في الضرائبِ بين المسلمين والنصارى، وكانت النمسا التي تريد ضَمَّ البوسنة والهرسك إليها عادت لتحَرِّضَ "},{"id":4681,"era":"c13","t":"إعلان رئيس الوزراء العثماني الدستور المسمى \"المشروطية الأولى\" .","s":"كان رئيسُ الوزراء العثماني الشهير مدحت باشا قد أعلنَ المشروطيَّةَ الأولى في أيلول عام 1876م بعد تسلُّم السلطان عبد الحميد الثاني الحكمَ مباشرة، ويعتبر مدحت باشا من أشهَرِ الإصلاحيِّين العثمانيين الذين ارتبطوا بالحركةِ الماسونيةِ، والذين تبنَّوا فكرة الإصلاح على الطريقة الأوروبيةِ، ولُقِّبَ مدحت باشا بـ \"أبي الدستور\" و\"أبي الأحرار\" وتعني المشروطية الأولى: القانونَ الأساسيَّ للدولة العثمانية، أي -ال"},{"id":4682,"era":"c13","t":"السلطان عبد الحميد الثاني يعزل أحمد باشا عن رئاسة الوزراء .","s":"عزل السلطانُ عبد الحميد الثاني رئيسَ الوزراءِ مدحت باشا أبو المشروطيَّة من منصبِه، وذلك بعد خمسة أشهر من إعلان المشروطيةِ التي لم يتِمَّ تنفيذها. فقد أقاله السلطان عبد الحميد الثاني من منصِبِ الصدرِ الأعظم لتوجُّهاته الغربيَّةِ والماسونيَّةِ, ثمَّ حاكمه السلطان بتهمة ضلوعِه في اغتيالِ عَمِّه السلطانِ عبد العزيز."},{"id":4683,"era":"c13","t":"بروتوكول لندن .","s":"وقَّعت الدولُ الأوربيَّةُ الكبرى \"بروتوكول لندن\" وهو الذي يَعرِضُ على الدولةِ العثمانيةِ تأمينَ حُدودِها مقابِلَ إجرائها إصلاحاتٍ في الإيالات (الولايات) البلقانية لصالح الرعايا النصارى، لكِنَّ الدولة العثمانية رفضت شروطَ هذا البروتوكول، وقامت بعقدِ صُلحٍ منفردٍ مع الصِّربِ، سحبت على إثرِه جيوشَها من بلاد الصرب، واشترطت أن يُرفَعَ العَلَمُ العثماني بجوار العلم الصربي، كدليل على استمرارِ السيادة الع"},{"id":4684,"era":"c13","t":"انتصار العثمانيين على الروس في معركة زفيان .","s":"انتصر الجيش العثماني بقيادة قائده أحمد مختار باشا على الجيشِ الروسي في معركة \"زفيان\" Zvin في الأناضول."},{"id":4685,"era":"c13","t":"انتصار الجيش العثماني على الجيش الروسي في معركة \"بلونة الثانية\" .","s":"انتصر الجيش العثماني على الجيش الروسي في معركة \"بلونة الثانية\" في منطقة البلقان، وخَسِرَ الروس في هذه المعركة أكثر من 7300 قتيلٍ. وهذه المعركةُ إحدى معارك \"حرب 93\" بين روسيا والدولة العثمانية، والتي انتَهَت بانتصارِ الروس."},{"id":4686,"era":"c13","t":"انتصار الجيش العثماني على الجيش الروسي في معركة \"كدكلر\" .","s":"لقي الجيشُ الروسي هزيمةً جديدة على أيدي الجيشِ العثماني، وذلك بقيادةِ القائد العثماني أحمد مختار باشا في معركة \"كدكلر\"، وحصل من السلطانِ العثماني \"عبد الحميد الثاني\" على لقب \"غازي\"؛ لانتصاراتِه المتعَدِّدة على الجيوشِ الروسية."},{"id":4687,"era":"c13","t":"انتصار الجيش العثماني على الجيش الروسي في معركة \"يخنيلر\" .","s":"انتصر الجيشُ العثماني بقيادة القائدِ أحمد مختار باشا على الجيشِ الروسي في معركة \"يخنيلر\"، واستطاع إحرازَ هذا الانتصار بجيش قوامه 34 ألف جندي على الجيش الروسي المكوَّن من 740 ألف جندي، وخَسِرَ الروس في هذه المعركة 10 آلاف قتيل."},{"id":4688,"era":"c13","t":"انهزام الجيش العثماني على يد الجيش الروسي في معركة \"آلاجاداغ\" .","s":"تغَلَّب الجيشُ الروسي على الجيشِ العثماني الذي يقودُه أحمد مختار باشا في معركة \"آلاجاداغ\"، بعد عدة انتصاراتٍ لمختار باشا على الروسِ في جبهةِ الأناضول."},{"id":4689,"era":"c13","t":"تعطيل مجلس النواب ونهاية المشروطية الأولى في الدولة العثمانية .","s":"دامت المشروطيَّةُ الأولى -التي أصدرها مدحت باشا في نهاية عام 1293هـ- مدَّةَ سنة وشهر و21 يومًا، وقد ظلَّ المجلِسُ مفتوحًا خلال الأشهر 12 و25 يومًا الأخيرة. وإن كان الدستور لم يُعمَلْ به أصلًا؛ لأن مدحت باشا الذي أصدر الدستور عُزِلَ عن منصب الصدر الأعظم بعد إصداره للدستور بخمسة أشهر, وكان على رأسِ أحكامِ الدستور المجلِسُ الشعبي، فعُطِّلَ المجلسُ بقرار الحكومة الموشَّح بالإدارة السَّنية لأمدٍ غيرِ م"},{"id":4690,"era":"c13","t":"بدء انتشار الدعوة القومية والعلمانية وأبرزها جمعية تركيا الفتاة .","s":"بدأ التعصُّبُ القومي أو بالأحرى: الدعوة إلى العصبية، تظهَرُ بوضوحٍ في أيامِ عبد الحميد الثاني، وإن كانت قد برزت قبله، ولكن بدأ تأسيسُ الجمعيات ذات الأهدافِ السياسية المشبوهةِ، والمرتبطة بالدولِ الاستعمارية، وإن كانت تحمِلُ صِفاتٍ أدبيةً وعلميةً، وكانت مراكِزُها المهمَّةُ هي استانبول وبيروت، ولعب النصارى دورًا كبيرًا جدًّا في نشر هذه الجمعيات في بيروت، فظهرت جمعيةُ العلوم والفنون تحت رعاية الإرسالي"},{"id":4691,"era":"c13","t":"الحرب الأفغانية البريطانية الثانية .","s":"هي حربٌ وقعت بين إمارة أفغانستان وبريطانيا بين عامي 1878م و1880م وهي فترة حكم شير علي خان الذي ينتمي لعائلة البركزاية الحرب التي شنَّها الراج البريطاني لغزو أفغانستان، وقد انتهت الحرب بانتصار بريطاني ثم انسحابها من أفغانستان بعد معاهدة جاندماك؛ حيث احتفظ الأفغان بالسيادة في المناطق الداخلية لبلادهم في حين تخلَّوا للإنجليز عن المناطق الحدودية وإدارة العلاقات الخارجية للبلاد."},{"id":4692,"era":"c13","t":"انهزام العثمانيين أمام روسيا .","s":"وقَّعت روسيا اتفاقًا سريًّا مع الأفلاق والبغدان (رومانيا) وضَعَت رومانيا بموجِبِه جميع إمكانياتها تحت تصرُّف روسيا، ثم قطعت روسيا العلاقاتِ السياسية مع الدولةِ العثمانية، وأعلنت الحربَ عليها بناءً على رفضِ البابِ العالي للائحةِ لندن-البابُ العالي هو قصرٌ في استانبول يقيمُ فيه السلاطين العثمانيون- وأخبر الباب العالي دولَ أوربا ثانيةً عمَّا تصرَّفت به روسيا فلم يَلقَ أيَّ موقف إيجابي، وذلك عام 1294ه"},{"id":4693,"era":"c13","t":"ملحمة بلافنا مع الروس  .","s":"عبَرَت جحافِلُ القوات الروسية ﺍلأﺭاضي العثمانية باتِّفاقٍ ومباركةٍ مِن فرنسا وبريطانيا، انضَمَّ إلى الروس قواتٌ رومانية وصربية وبلغارية، وعَبَروا نهر الدانوب، واستولوا علي بعض المدُنِ التابعة للعثمانيين، والمعابر المؤدية إلى البلقان، فقام السلطان عبد الحميد الثاني بتعيين عثمان باشا قائدًا للجيشِ العثماني لصَدِّ الغزو الروسي الذي حاول الاستيلاءَ على مدينة بلافنا، التي تقع في بلغاريا، وهي من أهم الم"},{"id":4694,"era":"c13","t":"احتلال بريطانيا جزيرة قبرص وبقاءها في حكم العثمانيين اسمًا فقط .","s":"فتح العثمانيون جزيرةَ قُبرص سنة 979هـ وعَمِلوا على توطيدِ دَعائِمِ الإسلامِ بها وأسكَنوا فيها كثيرًا من المسلِمين حتى صار عددُ المسلمين فيها ثلاثةَ أضعاف النصارى، وهكذا غدت الجزيرة بلدًا إسلاميًّا خالصًا وجزءًا من أمَّةِ الإسلام.وعندما ضَعُفَت الدولةُ العثمانية وقَوِيَت أوروبا التي أخذت في التهامِ جَسَدِ الدولة قطعةً قِطعةً، وكان الإنجليزُ أعدى أعداء المسلمين ينظُرون لقبرص نظرةً خاصةً باعتبارِها ق"},{"id":4695,"era":"c13","t":"مؤتمر برلين واحتلال النمسا للبوسنة والهرسك .","s":"رأى بسمارك مستشار ألمانيا عقدَ المؤتمر المزمَعِ عقدُه في برلين، وعُرِف بـ(مؤتمر برلين) وقَبِلت روسيا أن تعرِضَ شروط المعاهدة على المؤتمر؛ لأنها شعرت حينذاك بعُزلتها. وعُقِدَ المؤتمرُ في 13 يونيو 1878م في برلين، واستمر 31 يومًا، إذ انتهت أعماله في 13 يوليو. وقد حضره مندوبون عن بريطانيا وألمانيا والنمسا والمجر وفرنسا وإيطاليا وبوهيميا وروسيا، والدولة العثمانية. وفي هذا المؤتمر اتَّفَقت سياسة ألمانيا"},{"id":4696,"era":"c13","t":"معاهدة سان ستفانو وانسحاب تركيا من أوروبا  .","s":"بعد الحرب مع روسيا التقى مندوبو الدولةِ العُثمانيَّة ومندوبو روسيا في بلدة قرب استانبول على بحر مرمرة تُسمَّى سان ستفانو، وذلك بعد محادثات تقَدَّمَ فيها الروس قليلًا عن خطِّ وقف إطلاق النار الذي اتُّفِق عليه، ونُقِلَ أيضًا مركزُ المحادثات من أدرنة إلى هذه القريةِ، وقدَّمَ المندوبُ الروسي شروطًا مسبقةً وطلب التوقيعَ عليها مباشرةً، وإلا تتقَدَّم الجيوش الروسية وتحتل استانبول، ولم يكن للعثمانيين من خ"},{"id":4697,"era":"c13","t":"تولي السياسي الأرمني \"نوبار باشا\" رئاسة الوزراء في مصر .","s":"تولَّى السياسيُّ النصرانيُّ الأرمني \" بوغوص نوبار باشا\" رئاسةَ الوزراء في مصر، وهو أول رئيس وزراء بمصرَ، وذلك في ظِلِّ تزايد النفوذ الأجنبي في مصرَ في عهد الخديوي إسماعيل، وعُرِفَت هذه الوزارة بالوزارة الأوروبيَّة، واستمَرَّت حتى 23 فبراير 1879م. شغل نوبار منصب رئيس الوزراء 3 مراتٍ، كان يُتقِنُ اللغات: الفرنسية، والإنجليزية، واليونانية، والتركية، ولم يُتقِنِ اللغةَ العربيَّةَ!"},{"id":4698,"era":"c13","t":"هجرة الشراكسة المسلمين من روسيا بسبب الاضطهاد الديني .","s":"الشَّراكسة أو الشركس (أو الجركس) واليونان هم أوَّلُ مَن أطلق عليهم هذا الاسمَ. وهذا الاسمُ لم يطلِقْه أيُّ شَعبٍ على نفسِه، ويُطلق حاليًّا على أعراقِ شمال القوقاز، مثل الأديغا، ويقطنون حاليًّا في شركيسيا والقبردي والأديغي والسواحل الشمالية الغربية للقوقاز على البحر الأسود، والأبخاز في جمهورية أبخازيا حاليًّا، والشيشان في جمهوريتي الشيشان وأنغوشيا والمناطق المجاورة، وبعض القبائل القليلة من الداغستا"},{"id":4699,"era":"c13","t":"تولية خير الدين التونسي رئاسة الوزراء في الدولة العثمانية .","s":"تولى خير الدين التونسي منصِبَ رئاسة الوزراء في الدولةِ العثمانيةِ. ولد خير الدين في القفقاس لعائلةِ تليش الأباظية الشركسية، حوالي عام 1820م. تعهَّده والي تونس الداي أحمد، وهيأ له فُرَصَ الاستزادة من العلوم، فأكَبَّ على دراسة الفنون العسكرية والسياسية، والتاريخ والعلوم الشرعية، وأتقن اللغاتِ العربيةَ والتركية والفرنسية. أصبح رئيسًا لمكتب العلوم الحربية بباردو عام 1840م، ثم أصبح رئيسًا لفرقة الفرسان"},{"id":4700,"era":"c13","t":"عزل الخديوي إسماعيل ونفيه إلى إيطاليا واستخلاف ابنه توفيق .","s":"كان للخديوي إسماعيل خصومٌ في مصر وفي الأستانة، مع تزايُدِ التدخل الأوربي السافِرِ في شؤون مصر، فكانت القناصِلُ الأوربية يضغطون عليه ليُقيل نفسَه، وفي استانبول كان بعضُ السفراء يحثُّون السلطان على إصدار قرار العزلِ، ومن الأسباب التي اتخذتها الحكوماتُ الأوربية للمطالبة بعزلِه الانقلاب السياسي الذي قام به إسماعيل سنة 1879م (سنة عزله) وأنهى به عهدَ حُكمِ حملة السندات، باستقالة النظارة المصرية الإنجليز"},{"id":4701,"era":"c13","t":"احتلال فرنسا تونس وتوقيع معاهدة \"باردو\"  .","s":"بعد أن احتَلَّت فرنسا الجزائِرَ سنة 1246هـ عَزَمت على احتلالِ تونس وقامت مقابِلَ ذلك بالتنازُلِ لإنكلترا عن مصرَ، فبدأت بالتدخُّل أولًا في أمورِ الدولة بحجَّة الديون، ثمَّ قامت باستغلالِ خلافٍ افتعلَتْه على الحدودِ مع الجزائِرِ، واتَّهَمت تونس بإيواء المجاهدين الجزائريين في أراضيها، وأنَّها لا بدَّ لها من التدخُّل لقمع هؤلاء المجاهدين وجيوبهم، فقامت بحملةٍ عسكرية، ودخلت الأراضيَ التونسية، ثمَّ لم "},{"id":4702,"era":"c13","t":"خيانة اليهود للمسلمين في مدينة صفاقس التونسية .","s":"خان اليهودُ في مدينة صفاقس الشعبَ التونسيَّ المسلِمَ، وذلك حين أخبروا البارجةَ الفرنسية \"ألكرسيكي\" باستعدادِ الأهالي من المسلمين لمقاومتهم، فأحجمت البارجةُ عن مهاجمة المدينة لحين التزوُّد، ثم هاجمتها بمعاونة 6 بوارج إضافيةٍ أخرى."},{"id":4703,"era":"c13","t":"جهاد التونسيين للمحتل الفرنسي  .","s":"لم يرضَخِ الشعبُ التونسي لاحتلالِ فرنسا لبلادِه تحت عنوانٍ برَّاقٍ، وهو إعلانُ الحماية، والذي استهدفت فرنسا من اختيارِه عدمَ إثارة الدول الأوروبية، والتمويه على أبناء تونس بأنَّها لم تحتَلَّ بلدهم، وتُنزِلها منزلةَ المستعمرات، وحتى تُحمِّلَ الجانبَ الوطني نفقاتِ الاحتلال. واشتعلت الثورةُ في معظم أنحاءِ تونس، وعجزت فرنسا عن وقفِ العملياتِ الحربيَّة في تونس، واتَّضح أن القبائلَ التي تسكن شرقيَّ تونس"},{"id":4704,"era":"c13","t":"مقاومة أحمد عرابي استبداد الخديوي .","s":"في أوائل سنة 1298هـ استفحل أمرُ الشراكسة بمصر، وهمَّ ناظر الجهادية عثمان رفقي باشا الشركسي بتنحية فريقٍ مِن الوطنيين عن مراكزهم، فاجتمع عددٌ من هؤلاء وانتدبوا أحمد عرابي للمطالبة بموادَّ اتفقوا عليها، منها عزل رِفقي من نظارة الجهاديَّة، وتأليف مجلس نوَّاب. فرفع أحمد عرابي الأمرَ إلى رئيس النظار (رياض باشا) فأهمله إلى أن انعقد مجلسٌ برئاسة الخديوي، فقَرَّر محاكمة عرابي واثنين من أصحابه، فقُبِض عليه"},{"id":4705,"era":"c13","t":"ضم ابن رشيد المجمعة لحكمه .","s":"وقَّع محمد بن رشيد مع أهلِ المجمعة حِلفًا دفاعيًّا سريًّا ضد الإمام عبد الله بن فيصل الذي وقع في خلافٍ مع أهالي الوشم والمجمعة الذين ثاروا لتحقيق استقلالِهم عن الرياضِ، ولَمَّا تقدمت جيوشُ عبد الله المؤلَّفة من البوادي والحضر في وادي حنيفة، بادر محمَّد بن رشيد إلى نجدة المجمعة بجيشٍ مؤلَّف من بوادي شمر وقبائل حرب، ولَمَّا وصلت قواتُ ابن رشيد بُرَيدة انضَمَّ إليها أميرُ البلدة حسن آل مهنا أبو الخيل"},{"id":4706,"era":"c13","t":"ثورة المهدي في السودان  .","s":"كانت السودانُ خاضعةً لحكم محمد علي باشا من عام 1237هـ /1821 م. فقامت الحركةُ المهدية في الفترة من 1299 - 1317هـ /1881 - 1899 م؛ لتخليص السودانِ مِن ظلم الحكومة المصرية الواقِعِ على السودانيين؛ حيث أعلن محمد أحمد بن عبد الله أنَّه المهدي المنتَظَر لبعث الأمَّة، فتبعه كثيرون وسيطَرَ على أغلب البلاد، وكان محمد المهدي في سنة 1298 هـ (1881 م) تلقَّب بالمهديِّ المنتظَر، وكتب إلى فقهاء السودان يدعوهم لنص"},{"id":4707,"era":"c13","t":"الفرنسيون يرتكبون حرب إبادة للجزائريين .","s":"اعتمد الجيشُ الفرنسي وقادتُه استراتيجيةَ الحَربِ الشاملة في تعامُلِهم مع الشعب الجزائري، وكان الهَدَفُ المنشود من وراء هذه الاستراتيجية الإسراعَ في القضاء على تلك المقاوَمةِ المُستَميتة التي أظهرَتْها مختلفُ فئات الشعب وعلى جميعِ الأصعدة للهيمنة الأجنبية، وكانت البدايةُ بمذبحةِ البليدة على عهدِ الجنرال كلوزيل، ثمَّ مذبحة العوفية إلى عهدِ الدوق دي ريفيقو، التي كشفت طبيعةَ الإبادة الجماعية، كأسلوبِ "},{"id":4708,"era":"c13","t":"تأسيس مؤسسة الديون العمومية في الدولة العثمانية .","s":"أمرَ السلطان عبد الحميد الثاني بتأسيسِ مؤسسة الديون العمومية في الدولة العثمانية؛ لمعالجة مشكلة ديونِ الدولة، فوُضِعَت إيراداتُ الدولة الرئيسية تحت تصرُّفِ هذه المؤسسة لتسديدِ ديون الدولة التي بلغت 252 مليون قطعة ذهبية، فأسقطت المؤسَّسةُ من ديون الدولة 146 مليونًا. وقد لَعِبَت هذه المؤسسة دورًا في تسديد كثيرٍ مِن ديون الدولة أثناء عهدِ السلطان عبد الحميد الثاني."},{"id":4709,"era":"c13","t":"ضرب الإنجليز لمدينة الإسكندرية إبان الثورة العرابية .","s":"قام الإنجليزُ بضرب مدينة الإسكندرية، وذلك إبَّان الثورة العُرابية حيث حاصر الأسطولُ الإنجليزي مدينةَ الإسكندرية واختلق ذرائِعَ لِضَربِها واحتلالها مساندةً للخديوي توفيق!"},{"id":4710,"era":"c13","t":"مؤتمر الأستانة والتمهيد لاحتلال بريطانيا لمصر .","s":"دعا دي فريسينيه رئيس وزراء فرنسا الدولَ الأوربيةَ الكبرى إلى عقدِ مؤتمر للنظَرِ في المسألة المصرية، فلبَّى الدعوةَ كُلٌّ من إنجلترا وألمانيا وروسيا وإيطاليا والنمسا، وأمَّا تركيا فإنها رفَضَت الحضورَ واحتَجَّت على فكرةِ المؤتمر؛ لأنَّ فيه خَرقًا لسيادتها. عُقِدَ المؤتمر يوم 23 يونيو 1882م، وقرر المؤتمر في جِلسته الأولى إرسالَ مذكِّرة إلى الباب العالي يبلغُه نبأ اجتماعه، ويأسَفُ لعدم انعقاده برئاسة"},{"id":4711,"era":"c13","t":"ثورة أحمد عرابي واحتلال الإنجليز لمصر .","s":"كان ضُبَّاط الجيشِ قد نَظَّموا مظاهرة أيَّدها الشعب طالبوا الخديوي توفيق بتشكيلِ وَزارةٍ جديدة وتسَلُّم أحمد عُرابي في الوزارة الجديدة وزارةَ الحربية، واقترحت هذه الوَزارةُ مناقشةَ المجلس للميزانية باستثناءِ القِسمِ المخَصَّص لتسديد الديون للحيلولةِ دون التدخُّلِ الأجنبي، فوافق المجلِسُ واعتمد الخديوي الدستور عام 1299هـ فعارضت إنكلترا وفرنسا ذلك وعَمِلَتا على إثارة الفِتَنِ لإمكانية التدخُّلِ، وكا"},{"id":4712,"era":"c13","t":"دخول القوات البريطانية القاهرة بعد فشل الثورة العرابية .","s":"دخلت القواتُ البريطانيةُ القاهرةَ بعد فَشَلِ الثورة العرابية، وانتصار الإنجليز على القوَّات المصرية بقيادة عُرابي في معركة التل الكبير، وبعدها أقامت القواتُ البريطانية عرضًا عسكريًّا في ميدانِ عابدين، وكان ذلك إيذانًا ببَدءِ الاحتلال البريطاني الذي جَثَم على مصر أكثَرَ مِن سبعين عامًا."},{"id":4713,"era":"c13","t":"تولية الشيخ محمد المهدي العباسي مشيخة الأزهر .","s":"تولَّى الشيخُ محمد المهدي العباسي مشيخةَ الأزهر، وهو الشيخُ الحادي والعشرون في سلسلة مشايخ الأزهر، جمع بين منصبي الإفتاء ومشيخة الأزهر لأوَّلِ مَرَّة، وقد عُرِفَ بالشجاعة والجرأة في الحَقِّ. وهو أوَّلُ من تقلَّدَها من الحنفية، وهو الذي سَنَّ امتحانَ التدريس للعلماء، وجعَلَ لهم قانونًا في ذلك، واجتمع رأيُهم أن يكون المُمتَحِنون ستةً مِن أكابر العلماء، من أهل كلِّ مَذهَبٍ اثنان سوى مذهَبِ الإمام أحم"},{"id":4714,"era":"c13","t":"الأسطول البريطاني يقصف الإسكندرية .","s":"لما كانت إنجلترا قد بيَّتَت أمرًا فقد أعلنت تشكُّكَها في قدرة الحكومة المصرية الجديدة على حِفظِ الأمن، وبدأت في اختلاقِ الأسباب للتحَرُّش بالحكومة الجديدة، ولم تعجِزْ في البحث عن وسيلةٍ لهدفها، فانتهزت فرصةَ تجديدِ قلاعِ الإسكندرية وتقويةِ استحكاماتها، وإمدادِها بالرِّجال والسلاح، وأرسلت إلى قائدِ حامية الإسكندرية إنذارًا في 24 شعبان 1299 هـ / 10 يوليو 1882 م بوَقفِ عملياتِ التحصين والتجديدِ، وإنز"},{"id":4715,"era":"c13","t":"محاكمة زعماء الثورة العرابية في مصر .","s":"تشكَّلت المحاكمُ العسكرية لمحاكَمةِ وزير الدفاعِ في الحكومة المصرية الجديدة أحمد عرابي وأنصارِه. وفي يوم 3 ديسمبر 1882م صدرَ الحُكمُ بإعدام عرابي، ومحمود سامي البارودي، وعلي فهمي، وعبد العال حلمي، وغيرهم. واستُبدِلَ بالحُكمِ النفيُ المؤبَّدُ إلى جزيرة سيلان (سيريلانكا حاليًّا) مع تجريدِهم مِن الرُّتَب العسكرية ومصادَرةِ أملاكهم. كما حُكِمَ على محمد عبده وغيرِه بالنَّفيِ خارج مصر، وسُجِنَ الكثير من"},{"id":4716,"era":"c13","t":"وفاة الأمير عبدالقادر الجزائري قائد حركة المقاومة ضد الفرنسيين .","s":"هو الأميرُ عبدُ القادر ناصِرُ الدين بن محيي الدين الحسني المعروف بعبد القادر الجزائري, اشتهرَ بمناهضته للاحتلالِ الفرنسيِّ للجزائر. وُلِدَ في 23 رجب 1222هـ / مايو 1807م، بقرية \"القيطنة\" بوادي الحمام من منطقة معسكر \"المغرب الأوسط\" بالجزائر، ثم انتقل والِدُه إلى مدينة وهران. كان لوالِدِه محيي الدين صِدامٌ مع الحاكِمِ العثماني لمدينة \"وهران\"، وأدَّى هذا إلى تحديدِ إقامة الوالد في بيته، فاختار أن يخرُ"},{"id":4717,"era":"c14","t":"ابن رشيد يبسط نفوذه على بلاد الوشم وسدير  .","s":"حاول عبدُ الله بن فيصل إخضاعَ أهل المجمعة واستردادَ سلطتِه عليهم، لكنَّه فَشِلَ أمام تحالُف أهل المنطقة مع ابن رشيد وآل مهنا، فمُنِيَت قواتُه بخسائِرَ فادحةٍ في الأرواحِ، فبَسَط ابن رشيد نفوذَه على الوشم وسدير، وعيَّنَ لها حاكِمًا من قِبَلِه، وكاتبَ البلدانَ المجاورةَ لتدخُلَ في طاعته، ولَمَّا أرسل عبدُ الله أخاه محمدًا لابن رشيد للتفاهمِ معه والتفاوض، جلَا ابنُ رشيد عن الوشمِ إكرامًا له، ودليلًا "},{"id":4718,"era":"c14","t":"انتصار الثورة المهدية في السودان .","s":"طلب اللورد كرومر المندوب السامي البريطاني بمصرَ مِن الضابط تشارلز جورج غوردون الإشرافَ على إخلاء السودان من القواتِ المصرية تمهيدًا لاحتلالها، ولكن غوردون رفض ذلك الطلبَ وأعلن أنَّ القواتِ الإنجليزيةَ والمصريةَ المشتركة بالخرطوم سوف تتحَرَّكُ للقضاء على الثورة المهدية، وكان ذلك منه غطرسةً وتكبُّرًا دفع ثمنَهما حياتَه؛ تحرَّكت قواتُ المهدي باتجاه الخرطوم أواخِرَ سنة 1301هـ 1884م، وأرسل المهديُّ مند"},{"id":4719,"era":"c14","t":"فرنسا تستقل باستعمار غينيا .","s":"بدا نفوذُ فرنسا في غينيا منذ عام 1254هـ / 1838م؛ حيثُ تدخَّلت بسبب الاختلاف مع أحد أمراء القبائل حولَ تجارةِ الرقيقِ، وفي عام 1270هـ / 1854م أرادت أن تَحولَ بين بريطانيا وبين رَبطِ منطقة غامبيا بمنطقة سيراليون باحتلالِ جهات غينيا؛ لذا أسرعت فرنسا واحتلَّت مدينة دوبريكا وما حولها لتقطَعَ على بريطانيا الطريقَ، وفي هذا العام عُقِدَ مؤتمر برلين، ونتيجتُه استقَلَّت فرنسا بأنحاء غينيا وأخذت تتوسَّعُ بجه"},{"id":4720,"era":"c14","t":"التنافس على فارس والخليج بين الإنجليز والروس .","s":"كانت مَطامِعُ روسيا ومنذ عهد بطرس الأكبر الوصولَ إلى مياه الخليج العربي، والسيطرةَ على بلاد فارس المجاوِرة، والحُصولَ على قاعدة بحرية في الخليج العربي، وكانت بريطانيا هي المنافِسَ لروسيا؛ حيث استطاعت الملاحةُ في نهر الكارون، وعَقَدت الاتفاقيات مع الشاه، ومن جانبٍ آخر قام الروس بتسخير جيشٍ لحماية الشاه من الانقلابات والتمرُّدات العسكرية، فأصبح الروسُ لهم نفوذٌ في الشمال من إيران، ومن البريطانيين في"},{"id":4721,"era":"c14","t":"وفاة القائد الإنجليزي غوردون  .","s":"هو اللواءُ تشارلز جورج غوردون المعروف بلقب (غوردون الصين) و(غوردون باشا) و(غوردون الخرطوم). ولِدَ بلندن عام 1833م.كان غوردون ضابطًا وإداريًّا في الجيش البريطاني، وتنقَّلَ في عدد من المهام القيادية العسكرية البريطانية، فعُيِّن في سلاحِ الهندسة الملكية، واشترك في حربِ القرم وعمُرُه واحد وعشرون عامًا، ثم اشترك في حربِ الصين؛ حيث أسهم في الاستيلاء على بكِّين، ثم تولى قيادة الجيش الصينيالذي قمع ثورة تي"},{"id":4722,"era":"c14","t":"صدور قرار بريطاني بإخلاء الحاميات المصرية من ميناء زيلع الصومالي .","s":"قرَّرت بريطانيا إخلاءَ الحاميات المصرية مِن ميناء زيلع الصومالي، وقرَّرت أن تكونَ إدارةُ ساحل الصومال الممتد من \"زيلع\" حتى \"رأس حافون\" تابعةً مباشرة لحكومة الهند الخاضعة لبريطانيا."},{"id":4723,"era":"c14","t":"وفاة محمد أحمد المهدي السوداني .","s":"هو محمد أحمد بن عبد الله، المهدي السوداني الثَّائر، وقائدُ الحركة المهدية ومؤسِّسُها. كان لحركته أثرٌ كبير في حياة السودانِ السياسية. ولِدَ في جزيرةٍ تابعة لدنقلة سنة 1259هـ، من أسرةٍ اشتهر أنها حُسينية النَّسَبِ. وكان أبوه فقيهًا، فتعلَّم منه القراءةَ والكتابة، وحفِظَ القرآنَ وهو في الثانية عشرة من عمره. ومات أبوه وهو صغير، فعَمِلَ مع عمه في نجارةِ السُّفن مدةً قصيرةً، وذهب إلى الخرطوم، فقرأ الفِ"},{"id":4724,"era":"c14","t":"محمد بن سعود ينتصر على عمه الإمام عبد الله بن فيصل .","s":"في الوقتِ الذي نجح فيه ابنُ رشيد في بسطِ نفوذِه ليشمَلَ بلادَ الوشم وسدير كان محمدُ بن سعود ينازِعُ عَمَّه الإمامَ عبد الله على الحُكمِ، بحُجَّةِ أنَّه الوريثُ الشرعيُّ لوالِدِه، فدارت بينهما عدةُ معارك انتهت في هذه السنة بتغَلُّبِ أبناء سعود على عَمِّهم عبد الله، ودخلوا الرياض واعتقلوا عمَّهم عبد الله وسَجَنوه."},{"id":4725,"era":"c14","t":"ابن رشيد يبسط نفوذه على الرياض  .","s":"كان الإمامُ عبد الله والمعركةُ دائرة بينه وبين ابنِ أخيه محمد بن سعود أرسل إلى محمَّدِ ابن رشيد يستنجِدُ به ويطلب منه القدومَ لنُصرتِه فلبَّى طلَبَه فزحف إلى الرياضِ على رأسِ قوةٍ كبيرةٍ، ففرَّ أبناء سعود إلى الخَرج كعادتِهم عندما يهدِّدُهم الخطر، فدخل ابنُ رشيد الرياض وأخرج عبدَ الله من السجن بعد أن أصيبَ بمرضٍ في سجنِه، ثم عاد إلى حائل ومعه الإمامُ عبد الله، وعيَّنَ على الرياض قائِدَه سالم بن سب"},{"id":4726,"era":"c14","t":"إيطاليا تستولي على إرتريا .","s":"لما كانت إيطاليا الفاشية مُصَمِّمةً على إقامةِ إمبراطورية استعمارية، فقد قامت بغزو إثيوبيا في 3 تشرين الأول 1935 وأرغمت هيلاسيلاسي على اللجوءِ إلى المنفى في أيار 1936. وضَمَّت إيطاليا إثيوبيا إلى إرتريا التي كانت آنذاك مستعمرةً إيطاليةً، وضمَّت إلى الاثنين الصومال الإيطالي، وكونت من الثلاثة أفريقيا الشرقيةَ الإيطاليةَ."},{"id":4727,"era":"c14","t":"عزل سالم بن سبهان عن حكم الرياض .","s":"ضجَّ الناسُ في الرياض من سياسةِ ابنِ سبهان، ومما زاد غضَبَهم عليه قتلُه لأبناءِ سعودٍ الثلاثة: محمد، وعبد الله، وسعد، الأمر الذي أغضب أيضًا آل سعود وابن رشيد، فقام بعزلِه، وعيَّنَ بدلًا عنه فهَّاد بن عبادة بن رخيص."},{"id":4728,"era":"c14","t":"احتلال الصومال وتقسيمه بين ثلاث دول استعمارية .","s":"بعد أن احتَلَّت بريطانيا مصرَ أرادت أن تحُلَّ محلَّ القواتِ المصرية في شرقيَّ أفريقيا وانتهزت الحركةَ المهديةَ في السودان ففَصَلت سواحِلَ البحر الأحمر وبلادَ الصومال عن مصرَ، وحَلَّت القواتُ البريطانيةُ محلَّ القوات المصرية في زيلع عام 1302هـ وأمَّا جنوبيُّ الصومالِ فكان مع القواتِ الإيطالية، ولم تكُنْ بريطانيا تريدُ أن تدخُلَ في خلافات مع فرنسا وإيطاليا فاتَّفَقت مع فرنسا عام 1306هـ / 1888م على إ"},{"id":4729,"era":"c14","t":"إنزال الغواصة عبد الحميد إلى البحر .","s":"أنزلت الدولةُ العثمانية الغوَّاصةَ \"عبد الحميد \" إلى البحرِ، وكان اسمُها \"تحت البحر\" وهي أوَّلُ غوَّاصةٍ تُصنَعُ في المملكة المتَّحِدة، بُدئَ بتصنيعِها في عام 1886م، وتعمَلُ بالطاقة البخارية، وتعتبَرُ من جيل الغوَّاصات التي بُنِيَت في وقتٍ مبكر في إنجلترا، وأدخلتها الدولةُ العثمانية للخِدمةِ ضمن أسطولِها الحربيِّ بعد إجراء تجارِبِ الغَوصِ والارتفاعِ والسير، ثم أُدخِلَت هذه الغواصة \"الطوربيدات\"، وك"},{"id":4730,"era":"c14","t":"معاهدة القسطنطينية .","s":"أفلحت الضغوطُ الفرنسيَّةُ في حملِ كلٍّ من ألمانيا والنمسا والمجر وأسبانيا وإيطاليا وهولندا وروسيا والإمبراطورية العثمانية وبريطانيا على توقيعِ معاهدةِ القُسطنطينية في 29 أكتوبر 1888م، والتي تقضي مادتُها الأولى بضمان حريةِ الملاحةِ في قناة السويس واستمرارِها في أوقات الحربِ والسِّلمِ، وكفالتِها لكلِّ سفينةٍ حربية أو تجارية أيًّا كان العَلَمُ الذي ترفعُه، واتِّفاق الأطراف السامية المتعاقِدَة بعدمِ ا"},{"id":4731,"era":"c14","t":"عبد الرحمن بن فيصل يتولى الحكم في الرياض اسميا .","s":"تولى عبدُ الرحمنِ بنُ فيصل حُكمَ الرياض بعد وفاةِ أخيه عبد الله؛ لأنَّ أخاه محمدًا وهو أكبر منه لم يكن له مطمَعٌ في الحُكمِ، وطلب عبد الرحمن من ابنِ رشيد أن يعزِلَ فهَّاد ابن رخيص عن إمارة الرياضِ فقابل ابن رشيد هذا الطَّلَبَ بتحَدٍّ، فعزل ابن رخيص وعيَّنَ ابنَ سبهان العدوَّ اللدودَ لابن سعود."},{"id":4732,"era":"c14","t":"وفاة الإمام عبد الله بن فيصل بن تركي .","s":"هو الإمامُ عبد الله بن فيصل بن تركي بن عبد الله بن محمد بن سعود بن محمد بن مقرن، ثالث حكَّام الدولة السعودية الثانية، بويع بالرِّياضِ بعد وفاةِ والده سنة 1282هـ وخالفه أخوه سعود، فنشبت بينهما معارِكُ استولى سعودٌ في آخرها سنة 1287هـ على الرياض. وخُلِعَ عبد الله، فلجأ إلى التركِ في الأحساءِ فلم يطمئنُّوا إليه، فابتعد عنهم، وجمع بعضَ القبائِلِ وأعاد الكَرَّة على أخيه سعود. فاقتتلا في وقعةِ الجزعة من"},{"id":4733,"era":"c14","t":"وفاة الوزير خير الدين باشا التونسي  .","s":"هو الوزيرُ المؤرِّخُ خير الدين باشا التونسي، مِن رجال الإصلاحِ السياسيِّ الإسلامي، وهو شركسيُّ الأصل من القوقازي، ولِدَ سنة 1225هـ، قَدِمَ إلى تونس صغيرًا، وقضى بها مُعظَمَ حَياتِه، اتَّصَل بصاحبِها (الباي أحمد) وأثرى وتعلَّم بعض اللغات وتقلَّد مناصِبَ عديدةً عالية آخِرُها منصب رئيسِ الوزراء، وبسَعيِه أُعلِنَ دستور المملكة التونسية سنة 1284 هـ - 1867م، ولكنَّه ظَلَّ حِبرًا على ورق. وفي سنة1294 هـ "},{"id":4734,"era":"c14","t":"وفاة الأمير العلامة صديق حسن خان القنوجي  .","s":"هو الإمامُ العلَّامةُ الأميرُ السيد الشريف المحقِّقُ محيي السنة وقامِعُ البدعة: أبو الطيب محمد صديق بن حسن بن علي بن لطف الله القنوجي البخاري، نزيل بهوبال، ويرجع نَسَبُه إلى زين العابدين بن علي بن الحسين السبط بن علي بن أبي طالب. ولِدَ في بلدة \"بريلي\" موطِنِ جَدِّه من جهةِ الأمِّ، عام 1248هـ ولما بلغ السادسةَ مِن عمره توفِّيَ والدُه، فرحل مع أمِّه إلى قِنَّوج موطِنِ آبائهِ بالهندِ، فنشأ فيها في حج"},{"id":4735,"era":"c14","t":"وفاة القائد الأمير رابح الزبير .","s":"هو الأميرُ رابح بنُ فضل الله أو رابِحُ الزبير، كان زعيمًا سودانيًّا، وُلِدَ في عائلةٍ عربية في حلفاية الملوك، أحدِ ضواحي الخرطوم، كان والدهُ زعيمًا أو مَلِكًا على إحدى القبائل التي استوطَنَت مِنطقةَ بحر الغزال، التحق رابح بجيش \"الزبير\" إلَّا أنه عند بلوغه سن العشرين سافَر رابِحٌ إلى القاهرة، والتحق بجيش الخديوي إسماعيل في مصر، وعَمِلَ في سلاح الفرسان غيرِ النظاميِّين المصري أثناء حملةِ الحبشة، وقد"},{"id":4736,"era":"c14","t":"محاولة ابن سبهان التخلص من عبد الرحمن بن فيصل  .","s":"أراد الأميرُ سالمُ بنُ سبهان حاكِمُ الرياض مِن قِبَل ابنِ رشيد التخلُّصِ من عبد الرحمن بن فيصل، فدبَّرَ مؤامرةً لتنفيذها يومَ عيد الأضحى، إلَّا أن عبد الرحمن اكتشَفَها، فلما دخل ابن سبهان القصرَ على عبد الرحمنِ اعتَقَله هو ومن معه، وظل ابن سبهان في السِّجنِ إلى أن أُطلِقَ سَراحُه فيما بعدُ بطَلَبٍ مِن ابن رشيد."},{"id":4737,"era":"c14","t":"حصار ابن رشيد للرياض  .","s":"حاول عبدُ الرحمن بنُ فيصل أن يستعيدَ سُلطتَه على مناطِقِ القصيم، فاستنجد بأهالي القصيمِ ضِدَّ محمد ابن رشيد الذي لم يمهِلْ هذا الحِلفَ حتى ينضجَ، فجَرَّد حملةً عسكرية قويةً مِن البدو والحضر، واتجه لمحاصرة الرياضِ لإنهاء حُكمِ آل سعود، وانتهى الحصارُ بعد 40 يومًا بصُلحٍ حَضَره من قِبَلِ عبد الرحمن أخوه محمد، والشيخ عبد الله بن عبد اللطيف آل الشيخ قاضي الرياض، وحضر المفاوضاتِ الأميرُ عبد العزيز بن ع"},{"id":4738,"era":"c14","t":"معركة المليداء بين ابن رشيد وأهل القصيم .","s":"قرَّر محمَّدُ ابن رشيد أن يصفِّيَ حساباتِه مع أهل بُرَيدة بعد فَشَل فتح الرياض، فأعَدَّ حملةً مِن عُربان شمر وحرب، والتقى بقواتِ القصيم في مكانٍ يدعى القرعا، وانتصر عليه أهلُ القصيم فاحتال عليهم وانسحب إلى سهلية، فلما لحق به أهلُ القصيمِ انقَضَّ عليهم وهزمهم وقَتَل منهم 1000 رجلٍ، وكان عبد الرحمن بن فيصل قد جهَّز جيشًا لمساعدة مؤيِّديه من أهل القصيم إلَّا أنه وصله خبَرُ هزيمتهم قبل أن يصِلَ إليهم،"},{"id":4739,"era":"c14","t":"سقوط مسقط وعُمان في يد الإنجليز .","s":"استمَرَّت السيطرةُ البرتغاليَّةُ في عمان منذ بدايةِ القرنِ السادسَ عشَرَ وحتى عام 1060هـ /1650م حين استطاعت أسرةُ اليعاربةِ تحريرَ أرضِ عمان بطردِ البرتغاليِّين مِن معاقِلِهم في مسقط ومطرح، وكان ذلك التحريرُ ثمرةَ الكفاحِ والإرادةِ العُمانية التي استثمرت تنافُسَ وصراعَ الإنجليز والهولنديِّين مع البرتغاليين؛ لتخرُجَ منه في المنتَصَف الأوَّلِ من القرن السابع عشر أقوى قوَّةٍ بحرية محليَّةٍ في غَربِ ا"},{"id":4740,"era":"c14","t":"معركة حريملاء ونهاية الدولة السعودية الثانية .","s":"بعد معركة المليداء سنة 1308 أخذ الإمامُ عبد الرحمن ما أمكَنَه أخذُه من ممتلكاتِه في الرياض، وخرج بأسرتِه منها، واتَّجَه إلى المناطق الواقعة بين واحة يبرين والأحساء، لبُعدِها عن متناولِ ابن رشيد، ولوجودِ قبائل متعاطِفة معه، ومناوِئة لخَصمِه ابن رشيد، مِثلُ العجمان وآل مرة، ولكِنَّ صعوبة حياة الصحراء على نِساءِ أُسرتِه وأطفاله أجبَرَت الإمامَ عبد الرحمن على إرسالِ ابنه عبد العزيز إلى الشيخ عيسى بن خ"},{"id":4741,"era":"c14","t":"انتقال عبد الرحمن بن فيصل إلى الكويت .","s":"بعد مَعركةِ حُريملاء انتقل عبد الرحمن بن فيصل مع أسرتِه إلى يبرين في الأحساء ومنها إلى البحرين، حتى وصلوا إلى الكويت واستقروا بها حيث خصص لهم راتباً شهرياً قدره ستون ليرة عثمانية وظَلَّ فيها عشر سنوات حتى استطاع ابنُه عبد العزيز أن يستعيدَ الرِّياضَ مِن آلِ رشيد سنة 1319هـ / 1902م."},{"id":4742,"era":"c14","t":"وفاة الخديوي توفيق بن إسماعيل والي مصر .","s":"هو الخديوي محمد توفيق بن إسماعيل بن إبراهيم بن محمد علي باشا، حاكِمُ مصرَ والسودان، وحفيدُ محمد علي باشا، وكان قد تسلَّم الحُكمَ سنة 1296هـ - 1879م، بعد أن أجبَرَ الإنجليز والفرنسيون أباه الخديوي إسماعيل على تَركِ مَنصِبِه، وذلك عندما حاول استدراكَ ما فاته، وبعد أن أغرق البلادَ في ديونٍ أجنبيةٍ ضَخمةٍ مَهَّدت السبيلَ للأوروبيِّين التدخُّلَ في شئون البلاد، حاول إسماعيلُ التصَدِّيَ للنفوذ الأجنبي، ف"},{"id":4743,"era":"c14","t":"قيام أول مجمع لغوي في العالم العربي .","s":"قام أوَّلُ مَجمَعٍ لُغويٍّ في العالَم العربي، واتَّخَذَ من قصر \"محمد توفيق البكري\" بمصرَ مقرًّا له، وقد ضَمَّ هذا المجمَعَ أعيانَ اللغة، وغيرَهم، مثلُ: محمد توفيق البكري، ومحمد عبده، والشنقيطي، وحفني ناصف، وحمزة فتح الله، والمويلحي. ولم يستمِرَّ هذا المجمع لمدةٍ طويلة؛ فقد أُسدلَ الستار عليه بعد شهورٍ قليلة."},{"id":4744,"era":"c14","t":"الملك عبد العزيز بن عبد الرحمن في الكويت .","s":"بعد سُقوطِ الدَّولةِ السعودية الثانية في نجدٍ، تنقَّل عبد العزيز وهو في العاشرةِ مِن عُمُرِه مع أسرة أبيه من الرياضِ إلى شمالِ الربع الخالي حول يبرين، ثم البحرين، ومنها إلى الكويت، فقد وصلها مع نساءِ أُسرتِهم قبلَ وصول والِدِه، ونزلوا في دارٍ مؤلَّفٍ مِن ثلاث غرف أعدَّها لهم مبارك الصباح، وشهد عبد العزيز مع حداثةِ سِنِّه حادثةَ اغتيال مبارك الصباح -بمشاركة أحد أبنائه له- شيخ الكويت وأميرها أخوه ال"},{"id":4745,"era":"c14","t":"تولي مبارك الصباح إمارة الكويت .","s":"عندما ثار الأخُ الأوسَطُ مبارك بن صباح الصباح على أخيه الأكبر الشيخِ محمد أمير الكويتِ وقَتَله وقَتَل معه الأخَ الأصغَرَ جراحًا في ليلة واحدةٍ، تولى بعدها الشيخُ مبارك الصباح سُدَّة الإمارة في الكويتِ، وقيل: إنَّ الشيخ خزعل حاكِمَ المحمرة عاصِمةِ الأحواز كان له دورٌ في تشجيعِ مبارك على تصفية أخويه ليتفَرَّدَ بإمارةِ الكويتِ!"},{"id":4746,"era":"c14","t":"وفاةُ ناصر الدين شاه ملك فارس وتولي مظفر الدين شاه  .","s":"هو مَلِكُ فارس ناصر الدين شاه بن محمد ميرزا القاجار، الحاكِمُ الرابع في أسرة القاجار الشيعية في فارس. وُلِدَ في 6 صفر 1247 هـ/ 17 يوليو 1831 في قرية كُهنَمار بالقرب من تبريز، وكان أبوه محمد ميرزا وأمُّه ملك جهان خانم المعروفة بمهد العليا. حكَمَ فارس من 1848م، ولم يكُنْ وصولُ ناصر الدين للعرش إلَّا بمساعدة القنصل البريطاني في تبريز، وفي عهدِه تمَّ قَمعُ الحركة البابية وقتل الباب. بحَثَ ناصر الدين ع"},{"id":4747,"era":"c14","t":"معركة فركة في السودان بين المهديين والجيش المصري .","s":"قامت الحركةُ المهديَّةُ بالسودان وسيطَرَت على جميع أجزائِها ما عدا دارفور، واضطرَّ الإنجليز للانسحابِ من البلاد ومعهم انسحب الجيشُ المصري تحت ضغطٍ شديدٍ من إنجلترا، وذلك سنة 1302هـ، وبعد ذلك بعامٍ واحد توفِّيَ زعيم الحركة « محمد المهدي» وجاءت على البلادِ سنواتٌ عجافٌ، وأخذت إنجلترا تخطِّطُ للعودة إلى السودان، وأخذت في تشكيل جيشٍ مصري تحت قياداتٍ إنجليزيةٍ؛ من أجل تنفيذِ هذا الغرض، وتقدم هذا الجيشُ"},{"id":4748,"era":"c14","t":"ظهور كتاب الدولة اليهودية لهيرتزل .","s":"المؤسِّسُ الحقيقي للصهيونية اليهوديَّة السياسية هو (تيودور هرتزل) 1860-1904م، الذي كان منهجُه يكمُنُ في توظيف اليهودِ لحلِّ مشاكل الغرب والنَّظَر إلى المسألة اليهودية كمُشكلةٍ سياسيةٍ دوليةٍ غربيةٍ تجتَمِعُ كُلُّ الأمم المتحضِّرة (أي الغربية) لمناقشتِها وإيجاد حلٍّ لها، لكن ذلك سيتمُّ بمراقبة الرأي العام الغربي، وبمعاونة صادقةٍ مِن الحكومات المعنيَّة. دعا هرتزل إلى هجرةٍ يهودية عَلَنية بمساعدة دول"},{"id":4749,"era":"c14","t":"إنشاء مكتبة الجامع الأزهر الشريف  .","s":"كان لكلِّ رواقٍ في الأزهر مكتبةٌ خاصةٌ به، وكان بعضُ أهل الخير يَقِفون الكتُبَ فيها، ولكنها لم تكُنْ خاضِعةً لأيِّ نظامٍ، وكانت معظمُ الكتب في النحو، فاقترح الشيخُ محمد عبده عضوُ مجلس إدارة الأزهر في حينِها من ضِمنِ إصلاحاتِه أن يكون للأزهرِ مَكتبةٌ خاصَّةٌ متكامِلةٌ منظَّمةٌ، تجمَعُ شَتاتَ الكُتُبِ المتفَرِّقة في الأروقة التي ذهب كثيرٌ منها إلى أوربا عن طريقِ سماسرة الكتُبِ ومَن لا أمانة له من ال"},{"id":4750,"era":"c14","t":"وفاة جمال الدين الأفغاني .","s":"هو محمد جمال الدين بن صفدر -وتكتب صفتر- الحسيني الأفغاني الأسد آبادي، كان فيلسوفًا سياسيًّا، وكاتبًا وخطيبًا وصحفيًّا، ولد في شعبان 1254هـ / أكتوبر 1838م بأسد آباد بالقربِ من همذان من أعمال فارس، وقيل إنه ولد بأسد آباد الأفغانية؛ ولذا اختُلِفَ في أصل نسب أسرتِه، هل هو فارسي إيراني أم أفغاني, وقيل إنه من أسرة أفغانية عريقة ينتهي نسَبُها إلى الحسين بن علي رضي الله عنه, نشأ الأفغاني في كابول عاصمة ال"},{"id":4751,"era":"c14","t":"إعلان الدولة العثمانية الحرب على اليونان .","s":"أعلنت الدَّولةُ العثمانية الحربَ على اليونان بعد حروبِ العِصاباتِ التي شنَّها اليونانيون في عددٍ مِن الإيالات (الولايات) العُثمانية، وقد استمَرَّت هذه الحرب شهرًا، وانتصرت فيها الدولةُ العثمانية التي أفنت الجيشَ اليونانيَّ في معركة \"برنار\" ووصلت إلى أبواب العاصمةِ أثينا."},{"id":4752,"era":"c14","t":"انتصار الجيش العثماني على الجيش اليوناني في معركة \"جتالجه\" .","s":"انتصر الجيشُ العثماني على الجَيشِ اليوناني الذي يقودُه الأمير \"قسطنطين\" وليُّ عهد اليونان في معركةِ \"جتالجه\". ومكَّنَت انتصارات العثمانيين على اليونان من اقترابِ الجَيشِ العثماني إلى مسافة 150 كم من العاصمةِ أثينا."},{"id":4753,"era":"c14","t":"حادثة فاشودة في جنوب السودان .","s":"حادثُ فاشودة كان من أسبابِ الخلافِ بين انجلترا وفرنسا في السيطرةِ على أعالي النيلِ، هو تصميمُ الخديوي إسماعيل على الوصولِ إلى أعماقِ الجنوب السوداني عند تأسيسِه مديرية خَطِّ الاستواء على حدودِ أوغندا ليسيطِرَ على كلِّ مجرى نهرِ النيل والامتداد في أعماقِ القارَّة. وقد أصبحت تلك المناطِقُ ضِمنَ الوجود المصري في السودانِ، وكانت الإمبراطوريةُ الفرنسيةُ بدَورِها تتحَرَّك باتجاهِ مَنطِقةِ جنوب السودان ه"},{"id":4754,"era":"c14","t":"وفاة الأمير محمد ابن رشيد حاكم نجد وجبل شمر .","s":"هو الأميرُ محمدُ بنُ عبد الله بن علي بن رشيد، من شمر، أكبَرُ أمراءِ آل رشيد أيامَ حُكمِهم في حائل وما حولها. كان أبوه عبدُ الله قد لجأ إلى آل سعودٍ وأقامه الأميرُ فيصل بن تركي بن عبد الله أميرًا على حائل، وتوفِّيَ بها سنة 1263هـ، وخلفه ابنُه طلال فتوفي سنة 1283 وخَلَفه أخوه متعب فقتله ولَدَا أخيه بندر وبدر ابنا طلال سنة 1285، وقام محمد سنة 1288 فقتل خمسةً من أبناء أخيه طلال بينهم بندر وبدر، وترك س"},{"id":4755,"era":"c14","t":"محاولة اليهود إغراء السلطان عبد الحميد الثاني بهجرتهم إلى فلسطين .","s":"في هذا العام زار الإمبراطورُ الألمانيُّ ويلهلم استانبولَ فلَحِقَه هرتزل وتمكَّن من مقابلتِه في القدس وطلَبَ مساعدتَه بشأن الهجرة إلى فلسطين، وبعد توسُّط السفارة الألمانية في استانبول تقَدَّم هرتزل وبصُحبتِه الحاخام اليهوديُّ موشيه ليفي مِن السلطان عبد الحميد الثاني قائلًا: مولانا صاحِبَ الشوكة جلالةَ السلطانِ، لقد وكَّلَنا عبيدُكم اليهودُ بتقديم أسمى آيات التبجيل والرجاءِ، عبيدُكم المخلِصون اليهود"},{"id":4756,"era":"c14","t":"انعقاد المؤتمر الصهيوني الأول في بازل بسويسرا .","s":"بدأت الجمعيَّاتُ السرِّيَّةُ وغيرُ السريَّةِ تنتَشِرُ في البلادِ، والأفكارُ الغربية المواليةُ للغربِ والمعاديةُ لفِكرةِ الخلافة تنتَشِرُ، وبدأت التنظيماتُ العسكريَّةُ تنمو وتتَّسِعُ دائرتُها بسرعةٍ، وبدأ الخطَرُ اليهودي يَبرُز بشكلٍ واضحٍ سواء عن طريقِ يهود الدونمة، أو عن طريقِ الماسونيَّة، أو عن طريق اليهودِ من الخارج؛ إذ ساعدوا الجمعيَّاتِ السريَّةَ، وكان اليهودُ قد دَعَوا إلى اجتماعٍ لبَحثِ قضي"},{"id":4757,"era":"c14","t":"توقيع الدولة العثمانية معاهدة استانبول مع اليونان .","s":"وقَّعت الدولةُ العثمانيةُ مُعاهدةَ استانبول مع اليونان، بعد الحَربِ التي نَشَبت بين الجانبين وكَسَبتْها الدولةُ العُثمانية، ونصَّت المعاهدةُ على أنْ تدفَعَ اليونان لاستانبول غراماتٍ حربيَّةً ضَخمةً."},{"id":4758,"era":"c14","t":"بريطانيا تفرض حمايتها على الكويت .","s":"بعد أن استطاع الشيخُ مبارك آل الصباح الاستيلاءَ على حُكمِ الكويت أبقى العلمَ العُثمانيَّ مرفوعًا في الكويت ليخَفِّفَ نقمةَ النَّاسِ عليه من قَتلِه لأخويه محمد وجراح ليستفردَ بالحكم، ومن جانبِ الدولة العثمانية فإنها لم تكنْ واثقةً به، ومنعًا لاعتراف أيِّ دولة باستقلاله عيَّنَتْه قائمقام في الكويت، أمَّا البريطانيون فكانوا يتخوَّفون من أمرين: من الحكومة العثمانية التي بدأت تعَزِّزُ قواتها في البصرة،"},{"id":4759,"era":"c14","t":"الدعاية للقومية التركية بغرض إلغاء الخلافة الإسلامية .","s":"كان السُّلطانُ عبد الحميد الثاني قد أعلن الدستورَ سنة 1876م لكنه بعد سنتين عَلَّق الدستور وعطَّل البرلمانَ العثماني لَمَّا رأى أنَّ أكثَرَ الموالين للدستور من المفتونيين بأوربا وسياستِها وعلى صلةٍ بالساسة الأوربيين، ويعادون القانونَ الإسلاميَّ، ويطلقون على أنفُسِهم اسمَ الدستوريين، فانطلقوا يعملون على نشرِ أفكارِهم وبدؤوا بتأسيسِ الجَمعيَّاتِ السرِّية التي كان من أشهَرِها وأولها جمعية الاتحاد والت"},{"id":4760,"era":"c14","t":"استعادة الجيش المصري الإنجليزي السودان .","s":"بعد أن سيطر المهديُّون على السودان كلِّها وجاءت الأوامِرُ الإنجليزية للمصريين بالانسحابِ مِن السودان، ثمَّ أخذت إنجلترا بالعمل لاستعادة السودانِ، ووافق ذلك هزيمةَ إيطاليا أمام الحبشة، فاستنجدت إيطاليا بإنجلترا فتشَكَّل الجيشُ المصري الإنجليزيُّ، وتجمَّعَ في حلفا في ذي القعدة 1313هـ / أيار 1896م ليستعيدَ السودان، وقاد الجيشَ كتشنر الضابِطَ الإنجليزيَّ، ثم أُعطِيَت الأوامِرُ للتقَدُّمِ إلى السودان، "},{"id":4761,"era":"c14","t":"الاتفاقية المصرية السودانية .","s":"بعد أن استعاد الجيشُ المصري الإنجليزي السودانَ، تم التوقيعُ على الحُكم الثنائي للسودان، وذلك بين كرومر المندوب السامي الإنجليزيِّ في مصر ووزيرِ خارجية مصر بطرس غالي، وقد كانت الاتفاقيَّةُ بشأنِ إدارة السودان في المستقبَلِ، وأُطلِقَ لفظُ السودان في هذه الاتفاقية على جميع الأراضي الواقعة جنوبَ خَطِّ العرض 22 شمالًا، وأن يُرفَعَ العلمان البريطاني والمصري في البَرِّ والبحر في جميع أنحاء السودان عدا سو"},{"id":4762,"era":"c14","t":"ظهور حركة محمد الصومالي ودورها في مواجهة الإنجليز .","s":"واجه الاستعماران البريطانيُّ والإيطاليُّ ثورةَ الزعيم محمَّد عبد الله حسن الذي تلقَّب بمهدي الصومال. الذي استطاع أن يقاوِمَ المستعمرين لمدةِ عشرين عامًا كبَّدَهم أثناءَها الخسائِرَ الفادحة. وكانت بدايةُ هذه المقاومة هذا العام. وقد استطاع محمدُ عبد الله «الملا المجنون» (لقب أطلقه عليه الإنجليز) انتزاع حَقِّ السيادة على مناطقَ عديدةٍ. وفي عام 1913م. ألحقت قواتُه هزيمةً نكراء بالقوات الإنجليزية التي "},{"id":4763,"era":"c14","t":"وقوع السودان تحت السيطرة المصرية البريطانية .","s":"منذ أن دخلت بريطانيا إلى مصرَ وهي تعمَلُ على فصل السودان عن مصرَ، ولم تستطع إنجلترا أن تقمَعَ الثورات باسمِ المصريين، فقامت بإجلاء العساكِرِ المصرية من السودان بحُجَّةِ ولائِهم لأحمد عرابي لا للخديوي توفيق، وبصعوبةِ المواصلات للسودان، وأصَرَّ كرومر المندوبُ الإنجليزيُّ على إجبارِ الحكومة المصرية على قَبولِ الجلاء، ولكنَّه صار جلاءً مؤقَّتًا؛ ففي سنة 1896م جاءت حملةُ كتشنر التي انتهت بعد معركةِ أم "},{"id":4764,"era":"c14","t":"استيلاء الإنجليز على السودان بعد القضاء على حركة المهدي .","s":"أجبرت إنجلترا حكومةَ مِصرَ على سَحبِ جَيشِها من السودانِ بعد انتصارِ ثورة المهدي، وقاد كيتشنر مع عددٍ مِن الضباط الإنجليز حملةَ الجيش المصري لإعادةِ احتلال السودان من عام 1896م حتى عام 1898م؛ حيث انهزم المهديُّون في معركةِ أم درمان الفاصلة، فأجبر الإنجليز مصرَ على توقيع اتفاقية هذا العام (بحجَّة أن السودان قد أُعيدَ فتحه بدعمٍ مِن البلدين) فنصَّت الاتفاقيَّةُ على رفع العَلَمين المصري والإنجليزي. و"},{"id":4765,"era":"c14","t":"قيام حملة ضخمة تمنع بيع الأراضي للمهاجرين اليهود في فلسطين .","s":"شَهِدَ هذا العامُ حملةً ضَخمةً لجَمعِ التوقيعات على عرائِضَ تَمنَعُ بَيعَ الأراضي للمهاجرين اليهود في فلسطين. وكانت لكتاباتِ الشيخ رشيد رضا على صفحاتِ جريدة المنار، وغيره، أثرٌ كبير في زيادةِ وعي الجماهير بما يدورُ في فلسطين."},{"id":4766,"era":"c14","t":"صدور أمر بإنشاء سكة حديد الحجاز لخدمة الحجاج .","s":"أصدر السُّلطانُ العثماني عبد الحميد الثاني أمرًا سلطانيًّا بإنشاء سكة حديد الحجاز؛ لخدمة حجاج بيت الله الحرام، واستمَرَّ الخَطُّ في العمل تسعَ سنوات، وتعرَّض بعدها للتخريبِ أثناء الثورة العربية، ولم تُفلِح محاولات إعادته للحياةِ مرةً أخرى، وكانت تنحَصِرُ أهداف السلطان عبد الحميد في إنشاءِ الخط الحجازي في هدَفَين أساسيَّين مترابطين: أولهما: خدمةُ الحجاج بإيجادِ وسيلةِ سفَرٍ عصرية يتوفَّرُ فيها الأم"},{"id":4767,"era":"c14","t":"معركة الصريف ومحاولة الملك عبد العزيز الأولى لاستعادة الرياض  .","s":"انتهت الدولة السعوديُة الثانية عام 1308هـ واستطاع محمدُ ابنُ رشيد السيطرةَ على كل المناطق التي كانت تحت حُكمِ آل سعود في نجدٍ وما حولها، وبقِيَ الأمرُ على ذلك إلى عام 1319هـ، وكان كُلَّ هذه الفترة عبدُالرحمن بن فيصل مع أسرتِه في الكويت، ثمَّ إن أمير حائل عبد العزيز بن متعب استعَدَّ لقتال الشيخ مبارك أميرِ الكويت، فاقترح عبد العزيز بن عبد الرحمن بن فيصل على الشيخِ مبارك أن يسيرَ بقوَّةٍ إلى الرياضِ"},{"id":4768,"era":"c14","t":"ظهور بروتوكولات حكماء صهيون وخطرها على العالم الإسلامي .","s":"تعتبَرُ بروتوكولات حُكَماءِ صهيون من أخطَرِ الكتُبِ المنتَشِرة حولَ العالم، ذلك أنَّها تتحَدَّثُ عن خطةٍ مَرسومةٍ وجاهزةٍ وُضِعَت للسيطرةِ على العالم. يقالُ إنَّ مَن وضع هذه البروتوكلات هم رجالُ المال والاقتصاد اليهود؛ لتخريب المسيحيةِ والبابوية، ثم الإسلام؛ للسيطرةِ على العالم أكمَلَ، وذلك خلال مئة سنةٍ مِن تاريخ وَضعِها، يُقالُ: إنَّها كُتِبَت عام 1897 في بازل بسويسرا، أي: في العام نفسه الذي عُق"},{"id":4769,"era":"c14","t":"دخول الملك عبد العزيز الرياض واستعادة حكم نجد .","s":"بعد إخفاقِ الملك عبد العزيز في المحاولةِ الأولى لاستعادةِ الرِّياضِ، ازداد إصرارًا على انتزاع الرياضِ مِن ابن رشيد واستعادةِ حُكمِ آل سعود، فأعاد الكرَّةَ مرةً أخرى في هذا العام. فاستطاع دخولَ الرياض، وقَتَل عجلانَ بن محمد العجلان أميرَ الرياضِ مِن قِبَلِ ابنِ رشيد، بعد خوضِ مغامرةٍ جَريئةٍ قام بها مع أربعينَ رجلًا من أقربائِه وأتباعِه في الليلة الخامسة من شوال. أعلن عبد العزيز بعدها حُكمَه للرياض"},{"id":4770,"era":"c14","t":"قيام جمعية الاتحاد والترقي بعقد مؤتمر بعنوان \"مؤتمر أحرار العثمانية \" .","s":"عقَدَت جمعية الاتحاد والترقي مؤتمرًا لها في باريس بعنوان \"مؤتمر أحرار العثمانية\" استمَرَّ خمسة أيام، جمع فيه المعارضون لنظامِ السلطان عبد الحميد الثاني، واتخذ المؤتمَرُ عِدَّةَ قرارات؛ منها: أن تؤسَّسَ في الإمبراطورية العثمانية إداراتٌ محليةٌ مستقِلَّة على أساس القوميات. وجمعيةُ الاتحاد والترقي نشأت كجمعيَّةٍ سرية باسم (اتحاد عثماني جمعيت) في عام 1889 لمجموعةٍ من طلاب كلية الطب، وهم إبراهيم طمو، ع"},{"id":4771,"era":"c14","t":"فرنسا تحتل موريتانيا .","s":"كانت موريتانيا تتبَعُ دولة السنغال وتتبَعُ المغربَ، فبعض مناطق موريتانيا تتبع السنغال، وبعضها يتبع المغرب، وكانت عبارةً عن إماراتٍ صغيرة وغيرِ موحَّدة فيما بينها؛ لذا كانت تخضَعُ للدول الكبيرة التي تقوم في المنطقة، وهذا ما شجَّع الصليبيين المستعمرين للتقَدُّم من السواحل إلى الداخلِ، ولم يجد الاستعمارُ الفرنسيُّ الذي سيطر على المغرب إلَّا إمارات مفكَّكة، وخاصةً بعد أن أُعطِيَت منطقة السنغال إلى فرن"},{"id":4772,"era":"c14","t":"رفض السلطان عبد الحميد الثاني اقتراحًا بإنشاء جامعة يهودية في القدس .","s":"رفضَ السلطانُ عبد الحميد الثاني اقتراحًا من \"تيودور هرتزل\" مؤسِّس الحركة الصهيونية بإنشاء جامعة يهودية في القدس. وهرتزل يهوديٌّ نمساوي رأَسَ أوَّلَ مؤتمر صهيوني في بازل بسويسرا عام 1879م. يقول السلطان عبد الحميد: \"لليهودِ قُوَّةٌ في أوروبا أكثَر مِن قوَّتِهم في الشرق؛ لهذا فان أكثَرَ الدول الأوربية تحبِّذُ هجرة اليهود إلى فلسطين؛ لتتخَلَّصَ من العِرق السامي الذي زاد كثيرًا، ولكنْ لدينا عددٌ كاف من"},{"id":4773,"era":"c14","t":"وفاة عبد الرحمن الكواكبي .","s":"هو عبد الرحمن بن أحمد بن مسعود الكواكبي، ويلقَّب بالسيد الفراتي، مِن رجالِ الأدب والاجتماع والسياسة، وهو من رواد الحركةِ القومية العربيَّة، ولد في 23 شوال سنة 1271هـ في مدينة حلب، وتعَلَّم بها، وكانت له مكانةٌ مرموقة في بلَدِه، يقصدُه أصحابُ الحاجات لقضائِها، ويلجأُ إليه أرباب المشاكلِ لحلِّها، بل كان رجالُ الحكم يستشيرونه أحيانًا فيُبدي رأيَه في جرأة وشجاعة. أنشأ في حلب جريدة (الشهباء) فأغلقَتْها"},{"id":4774,"era":"c14","t":"ضم الملك عبد العزيز الخرج والدلم .","s":"بعد أن سيطرَ الملك عبد العزيز على الرياض في شوال عام 1319هـ، رَمَّم أسوارَها وحَصَّنها؛ لاحتمال مهاجمة ابن رشيد لها، ثم اتجه إلى الخرج والدلم وجمع حولَه مؤيديه من أهل الخرج والحوطة والفرعة؛ رغبة في استدراج ابن رشيد إلى جنوب الرياض، ولَمَّا اتجه ابن رشيد إلى الرياض وعَلِمَ بتحصينها وأنَّ الملك عبدالعزيز في الخرج، توجه إلى الخرج واشتبك معه في عدَّةِ وقائِعَ دون أن يتحَقَّقَ له أيُّ نصر عليه، إلى أن "},{"id":4775,"era":"c14","t":"إخماد الجيش العثماني لثورة البلغار في مقدونيا .","s":"أخمد الجيشُ العثماني الثورةَ التي قام بها البلغار في مقدونيا، والتي كانت تابعةً للدولة العثمانية، وتبلغ مساحتُها 96 ألف كم مربع، ويبلُغُ عدد سكانها 4 ملايين نسمةٍ، وكانت تحتوي على أعراقٍ وأديانٍ متعَدِّدة."},{"id":4776,"era":"c14","t":"استيلاء البريطانيين على مدينة \"كانو\" في شمال نيجيريا .","s":"استولى البريطانيون على مدينة \"كانو\" في شمالِ نيجيريا، وكان مُعظَمُ جنوب نيجيريا قد خضَعَ للحماية البريطانية منذ عام 1900م. كانت مدينة \"كانو\" تحتَ حُكم أميرٍ مُسلمٍ، وكانت مركزًا تجاريًّا وعسكريًّا مهمًّا في شمالِ نيجيريا. وهاجر عددٌ غير قليل من مواطنيها نتيجةً لهذا الغزو الاستعماري، من دارِ الكُفرِ إلى دار الإسلامِ (الحجاز والسودان) وتحمِلُ الولايةُ التي توجَدُ فيها هذه المدينةُ (وهي عاصمتها) هذا "},{"id":4777,"era":"c14","t":"تولي الشيخ علي بن محمد بن أحمد الببلاوي مشيخة الجامع الأزهر .","s":"تولَّى الشيخُ علي بن محمد بن أحمد الببلاوي مشيخةَ الجامع الأزهر. والببلاوي تعلَّم في الأزهرِ ودرس فيه، وتولى نِظارةَ دار الكتب. وعُيِّن نقيبًا للأشرافِ خَلَفًا لمحمد توفيق البكري، ولم يمكُثْ في مشيخة الأزهر طويلًا؛ بسبب معارضةِ الخديوي عباس حلمي لجهودِ الببلاوي في إدخال تغييراتٍ على الأزهَرِ."},{"id":4778,"era":"c14","t":"ظهور الفرقة القاديانية في الهند .","s":"إنَّ مما قام به الإنجليز في الهند لتوطيدِ بقائهم وسيطرتهم فيها أنْ عَمِلوا على إنشاءِ الفِرَق الضالَّة، أو على الأقلِّ دعمها أو السكوت عنها وتَرْكها تنشُرُ ضلالها، فكان مما عَمِلَته أن شجَّعَت مرزا غلام أحمد القادياني على إحياءِ ما دعا إليه المَلِك المغولي في الهند جلال الدين أكبر شاه المتوفَّى عام 1014ه. فأنشأ مرزا غلام القاديانية، وكتب البراهينَ الأحمدية، ثم تطوَّر أمره فادَّعى عام 1322هـ أنَّه "},{"id":4779,"era":"c14","t":"ضم الملك عبد العزيز بلدان الوشم وسدير  .","s":"بعد أن استقرَّ حُكمُ الملك عبد العزيز في الرياض والخرج والدلم وما حولها، اتجه نحو شمال الرياض وقصَدَ بلاد الوشم وسدير والمجمعة التي كانت خاضعةً لحكم ابن رشيد، فدارت اشتباكات بين حاميات ابن رشيد وسرايا الملك عبد العزيز، نتج عنهما ضمُّ الإقليمين إلى حكم الملك عبدالعزيز ما عدا بلدة المجمعة التي ظلت محافِظةً على ولائها لابن رشيد، ولم تخضع إلا بعد مقتَلِه في روضةِ مهنا سنة 1324هـ ودخول القصيم تحت حكمِ "},{"id":4780,"era":"c14","t":"مهاجمة القوات البريطانية لقوات الدراويش أتباع مهدي الصومال .","s":"هاجمت القواتُ البريطانية قواتِ الدراويش التابعةَ لمهدي الصومال سيد محمد بن عبد الله، الذي كان يلقِّبُه الاستعمار بـالملَّا المجنون. واستمر المهديُّ في مقاومة الاستعمار البريطاني في الصومال حتى عام 1920 عندما لجأت بريطانيا إلى الطيرانِ لقَصفِ مواقِعِ الثوار أتباع مهدي الصومال، ثمَّ جاءت وفاةُ المهدي سيد محمد التي انتهت بها ثورتُه الإسلاميَّةُ."},{"id":4781,"era":"c14","t":"الدولة العثمانية تفاوض الملك عبد العزيز بن سعود في القصيم .","s":"أثناء معارك القصيم مع ابن رشيد أصبح وضع الملك عبد العزيز بن سعود قويًّا خاصةً بعد معركة الشنانة. واتضح للعثمانيين فشَلُ تجربتهم العسكرية في تلك المنطقة، وأدركوا أنَّ الأمر ليس بالسهولة التي صوَّرها لهم ابنُ رشيد، وأنَّ عليهم مراجعةَ حساباتهم تجاه الملك عبدالعزيز الذي اتضح أنه يتمتَّعُ بشعبية واسعة في القصيم وفي نجد كلها، فأرادت الدولة أن يكون لها يدٌ داخِلَ الجزيرة بالتدخُّل في حلِّ مشكلة القصيم س"},{"id":4782,"era":"c14","t":"وفاة الصحفي اليهودي تيودور هرتزل زعيم المنظمة الصهيونية العالمية .","s":"هو تيودور هرتزل (بنيامين زئيف هرتزل) صحفيٌّ يهوديٌّ نمساويٌّ مَجَري، مؤسِّسُ الصهيونية السياسية المعاصِرة. ولِدَ في بودابست 1860م، وتلقَّى تعليمًا يطابقُ روحَ التنوير الألماني اليهودي السائدِ في تلك الفترة، الذي يغلِبُ عليه في صُلبِه الطابَعُ الغربي النصراني حتى سنة 1878م. اشتغل هرتزل بالصحافةِ في باريس كمراسِلٍ للصحيفة الفيينية المهمَّة آنذاك من عام 1891 إلى 1896م وحينها تشكَّلَت أفكارُه الصهيوني"},{"id":4783,"era":"c14","t":"معركة البكيرية .","s":"وقعت هذه المعركة بين قوات عبد العزيز بن متعب بن رشيد وقوات الملك عبد العزيز بن سعود، كان ابن رشيد قد قام بمصادرةِ ما وَجَد من إبل العقيلات من أهل القصيم الذين كانوا يجوبون البلاد للتجارة بين العراق والشام ومصر وشبه الجزيرة العربية، وحمَّل عليها قسمًا كبيرًا مما حصل عليه من أطعمةٍ ومُؤَن وأسلحة نقلها من العراق إلى نجد، وأسرع إلى القصيمِ بمن اجتمع لديه من البدو خاصَّةً من قبيلة شمر، وفئات من الحضر و"},{"id":4784,"era":"c14","t":"معركة الشنانة  .","s":"وقعت هذه المعركة بين قوات الملك عبد العزيز وحاكم حائل عبد العزيز بن متعب بن رشيد، بمحافظة الشنانة بالقصيم، وبدعمٍ مِن أهل الشنانة انتصرت فيها قوات الملك عبد العزيز، وكانت هذه المعركة قاصمةَ الظهر لابن رشيد الذي تحوَّل بعدها من الهجوم إلى الدفاع. وقد قام ابن رشيد وقواته بتخريبِ الشنانة وقطْع نخيلها وتعذيب أهلها نظيرَ وقوفِهم في وجهِه ودعْمِهم للملك عبد العزيز."},{"id":4785,"era":"c14","t":"وفاة الشاعر محمود سامي البارودي .","s":"هو الشاعِرُ محمود سامي باشا بن حسن حسني بن عبد الله البارودي المصري, جركسي الأصلِ من سلالةِ المقام السيفي نوروز الأتابكي. ولِدَ بالقاهرة سنة 1255ه، وهو من أوائِلِ من نهض بالشعرِ العربيِّ في عصرنا الحاضر، كان البارودي إلى جانبِ موهبتِه الشعريَّةِ رجلًا عَسكريًّا وسياسيًّا، وهو من تلاميذِ جمال الدين الأفغاني وممَّن تأثَّر بفِكرِه وطرحِه السياسيِّ، رحل الباروديُّ إلى الأستانة فأتقَنَ الفارسيَّةَ والت"},{"id":4786,"era":"c14","t":"إخضاع الإنجليز مسلمي البنغال لسيطرة الهندوس .","s":"قام الإنجليزُ بتقسيمِ البنغال إلى قِسمَين غربي وشرقي، وذلك على أساسٍ دينيٍّ بين المسلمين والهندوس، وعارض الهندوس هذا التقسيمَ؛ إذ فقدوا حسَبَ رأيهم السيطرةَ على ولاية مهمةٍ، وعَمَّهم الحزن وأضربوا واجتَمَعوا عند صَنمِهم كالي، إله التدمير -حسب عقليَّتِهم- وتعاهدوا على مقاطعةِ البضائعِ الإنجليزية، وطالب المسلِمون في العام التالي بإجراءِ انتخاباتٍ منفصلة، وتَرْك الانتخابات المشتركة، وذهب وفدٌ منهم لم"},{"id":4787,"era":"c14","t":"مؤتمر الجزيرة الخاصة بالمغرب .","s":"كان من محاولات فرنسا للتدخُّلِ في المغرب دون أن تواجِهَ الخصومَ الأوربيين أنْ عَقَدت الاتفاقياتِ معهم، فعقدت مع إيطاليا اتفاقًا بأن تترك لها طرابلس، ثم عقدت مع بريطانيا اتفاقًا على أن تتركَ لها حرية التصرُّفِ في مصر مع بقاء معاهدة إنجلترا القديمة مع مراكش ساريةَ المفعول، ولاقت هذه الاتفاقيةُ قَبولًا أسبانيًّا لكنَّها لاقت رفضًا ألمانيًّا؛ حيث جاء الإمبراطور غليوم إلى طنجة في هذا العام وألقى خطابًا"},{"id":4788,"era":"c14","t":"تعرض السلطان العثماني عبد الحميد الثاني لمحاولة اغتيال فاشلة .","s":"تعرَّض السلطانُ العثماني عبد الحميد الثاني لمحاولةِ اغتيالٍ فاشلةٍ دَبَّرها الأرمن بإيعازٍ وتشجيعٍ مِن الحركة الصهيونية اليهودية العالَمية، وعُرِفَ هذا الحادِثُ في التاريخ العثماني باسم \"حادث القنبلة\". كلَّف يهود سويسرا إدوارد جورج اليهوديَّ الفرنسيَّ الجنسية بالتعاونِ مع أعضاء جمعية الطاشناق الماسونية الأرمنية لإدخالِ عَرَبة إلى استانبول، فوصلت إلى استانبول قِطعةً قطعةً، وتمَّ تركيبُها لتكون قنبل"},{"id":4789,"era":"c14","t":"وفاة الشيخ محمد عبده .","s":"هو الشيخُ محمد عبده بن حسن خير الله مِن آلِ التركماني، مفتي الدِّيارِ المصريَّةِ، وأحَدُ دُعاةِ ما يسمى بالنهضة والإصلاح في العالمِ العربي والإسلاميِّ، وأحدُ رموزِ دعاةِ التجديدِ في الفِقهِ الإسلاميِّ، ساهمَ بعد التقائه بأستاذِه جمال الدين الأفغاني في إنشاءِ حركة فكريةٍ تجديديةٍ في أواخر القرن التاسع عشر وبدايات القرن العشرين، تهدفُ إلى القضاء على الجُمودِ الفِكريِّ والحضاريِّ، وإعادةِ إحياء الأمّ"},{"id":4790,"era":"c14","t":"حادثة قرية دنشواي في مصر .","s":"في يومِ الأربعاء الثالث عشر من يونيو 1906م كانت قرية دنشواي تعيشُ في هدوء حتى دخَلَها على غير موعدٍ عددٌ من أفرادِ كتيبةٍ إنجليزيَّةٍ كانت تتحَرَّك من القاهرة إلى الإسكندرية، وبدؤوا في اصطياد الحمام الذي يربِّيه الأهالي، وبجوارِ أجران القمح -موضع يُداس فيه القَمحُ- التي لا تخلو من وجودِ أصحابها بجوارِها، وبينما هم كذلك أصابت رصاصةٌ زوجةَ مؤذِّن القرية (صاحب أحدِ الأجران) وأشعلت رصاصةٌ ثانيةٌ النَّ"},{"id":4791,"era":"c14","t":"معركة روضة مهنا .","s":"حدثت بين قوات إمارة جبل شمر بقيادة عبد العزيز بن متعب آل رشيد يسانده 200 جندي عثماني، وبين قوات الملك عبد العزيز في روضة مهنا بمنطقة القصيم، حيث دارت اشتباكاتٌ ليلية خفيفة وعنيفة قُتِلَ فيها ابن رشيد على يدِ أهل القصيم عندما دخل وسطَ قواتِ الملك عبد العزيز ظنًّا منه أنهم قواتُه، فانهالوا عليه ببنادقهم فخَرَّ صريعا وقطَعوا رأسَه ووصلوا به إلى بريدة ثم عنيزة، وانتهت المعركة بانتصار الملك عبد العزيز "},{"id":4792,"era":"c14","t":"وفاة الأمير عبد العزيز بن متعب ابن رشيد أمير جبل شمر .","s":"هو الأمير عبد العزيز بن متعب بن عبد الله العلي الرشيد مِن الجعفر من قبيلة شمر من أمراء آل رشيد أصحاب حائل وما حولها بنجد. وَلِيَها بعد وفاة عمه محمد بن عبد الله الرشيد سنة 1315هـ، كان من أشجع العرب في عصره، وأصلَبِهم عودًا. بدأ حكمه في ظل قبولٍ تامٍّ له من قِبَل الأهالي وأفراد أسرته، وكان ذا ميول عسكرية وتوسُّعية، فاهتمَّ كثيرًا بالشأنِ العسكريِّ وكوَّن جيشًا عَزَّز به جميعَ مناطق نفوذه. له وقائِع"},{"id":4793,"era":"c14","t":"تعديل الحدود بين الدولة العثمانية ومصر .","s":"تمَّ تعديلُ الحدود بين الدولة العثمانية ومصرَ على أساسِ حدود مصرَ الحاليَّةِ في سيناء، وتمَّ اعتبار \"طابا\" ضِمنَ الأراضي المصرية، و\"العَقَبة\" ضمن الأراضي العُثمانية."},{"id":4794,"era":"c14","t":"ثورة المغرب يقودها عبد الكريم الخطابي ضد الأسبان والفرنسيين .","s":"ظهر الأميرُ محمد عبد الكريم الخطَّابي عام 1921 م في منطقة الريف، واستطاع أن يفجِّرَ الثورة فيها ضدَّ الأسبان وأن يحقِّقَ العديد من الانتصارات على الأسبان، وأصبح وجودُ الأسبان قاصرًا على مدينة تطوان وبعض الموانئ والحصون في الجبال، وأسَّسَ الأميرُ إدارةً منظمة للمناطِقِ المحرَّرة وحكَمَها حكمًا شبيهًا بالحُكمِ الجُمهوري الرئاسي، وألَّف مجلِسًا لرؤساء القبائل، وجعل الوزراءَ مسؤولين أمام هذا المجلس، و"},{"id":4795,"era":"c14","t":"إنشاء خط لسكة الحديد بين المدينة المنورة ودمشق .","s":"عَمِلَ السلطانُ عبد الحميد على كَسبِ الشعوب الإسلامية عن طريقِ الاهتمامِ بكلِّ مؤسَّساتها الشرعيَّة والعِلميَّة، والتبَرُّع لها بالأموالِ والمِنَح، ورَصد المبالغ الطائلة لإصلاحِ الحَرَمين، وترميمِ المساجِدِ وزَخرفتها، وأخذ السلطانُ يستميل إليه مسلمي العربِ بكلِّ الوسائِلِ، فكوَّن له من العَرَبِ حرسًا خاصًّا، وعيَّنَ بعضَ الموالين له منهم في وظائِفَ كبرى، وأبدى السلطان عبد الحميد اهتمامًا بالغًا بإ"},{"id":4796,"era":"c14","t":"تمرد قبيلة مطير بزعامة فيصل الدويش وتحالفها مع ابن رشيد .","s":"تمرَّد بعضُ رؤساء عشائر قبيلة مطير على الملك عبدالعزيز، وتحالفوا مع أمير بريدة محمد بن عبد الله أبا الخيل، على أن يكونوا من أنصار ابن رشيد ضِدَّ الملك عبدالعزيز الذي تحالف مع قبيلة عتيبة خصوم مطير وشمر، فنشبت قربَ مدينة المجمعة في سدير معركةٌ بين قبيلة مطير بقيادة فيصل الدويش وقوات الملك عبدالعزيز المكَوَّنة بالأساس من قبيلة عتيبة. وهُزمت مطيرٌ، وأصيب فيصل الدويش بجراحٍ في هذه المعركة، فطلب الصلح "},{"id":4797,"era":"c14","t":"إنشاء مدرسة القضاء الشرعي بمصر .","s":"ساءت أحوالُ المحاكم الشرعيةِ في مصر، بعد أن بدأ محمد علي باشا وخلفاؤه في تغييرِ الوضع القضائي المستقِرِّ في البلاد منذ مئات السنين، بإيجاد كيانٍ جديدٍ لا يعتَمِدُ على القضاء الشرعيِّ، بل يتَّجِهُ إلى التَّقنين الأوربيِّ الحديث، وانحصر دورُ المحاكم الشرعية في نظَرِ قضايا الأحوال الشخصيَّة والمواريث والوقفِ، وتسلَّل إليها الفسادُ بعد أن أدارت لها الدولةُ ظَهرَها ولم تقَدِّمْ إليها يدَ العون. وظل الأ"},{"id":4798,"era":"c14","t":"معركة الطرفية .","s":"نكث أميرُ بُريدة محمد بن عبد الله أبا الخيل عَهدَه مع الملك عبد العزيز بن سعود، واتَّفق مع أمير حائل سلطان الحمود بن رشيد على أن يكونا يدًا واحدةً عليه. كذلك ازداد أبا الخيل قوةً بقدوم فيصل الدويش زعيم قبيلة مطير إليه، الذي عاهده على الوقوفِ معه. وسارع الملك عبد العزيز في التحرُّك إلى القصيم، ووصل عُنيزةَ التي هَبَّ أهلُها إليه، وخرج لمهاجمة سلطان ابن رشيد في بُريدة، وحصلت مناوشات لم تسفِرْ عن دخو"},{"id":4799,"era":"c14","t":"نشوء الأحزاب السياسية العربية بمصر .","s":"كان الناسُ في مِصرَ على تيارات ثلاثة، تيار \"الحركة الوطنية\"، وكانت ضِدَّ الاحتلالِ الإنجليزيِّ وتيار \"جماعةِ الاحتلال\" التي تتلقَّى الدعم الإنجليزيَّ وتعيش عليه، وتيار \"جماعة قصر عابدين\" التي تؤيِّد الخديوي الذي يكرَهُ الاحتلالَ لكِنَّه راضِخٌ له، وبدأت وسائِلُ إعلام كلُّ تيارٍ بالصِّراعِ، وبناءً على هذه التيارات نشأت الأحزابُ السياسية، فأُعلِنَ في 16 رمضان عن تأسيس \"الحزب الوطني\"، رغم قيامِه فعلي"},{"id":4800,"era":"c14","t":"وفاة المشير محمد رؤوف باشا قائد الجيش العثماني .","s":"هو المشيرُ محمد رؤوف باشا بن عبدي باشا الجركسي، قائِدُ الجيش العثماني. ولِدَ في استانبول عام 1832م، وتلقَّى علومَه العسكريَّةَ في الأكاديميَّةِ الحربية في استانبول. شارك في المعارِكِ التي جرت في كُلٍّ مِن البوسنة والقَرم تحت قيادة عمر باشا. التحق بمدرسةِ سانت سير الفرنسية العسكرية، ثم التحَقَ بأركان حربِ الجيش العثماني، وحصل على رُتبة الباشوية. تمَّت ترقيته في عام 1869م إلى رتبة مُشير. تولَّى منصب"},{"id":4801,"era":"c14","t":"احتلال النمسا البوسنة والهرسك .","s":"رفضت البوسنة والهرسك دعوةَ مندوبيها لحضور المجلس النيابي المنعقد في استانبول، مع أنَّها لا تزال تابعةً اسميًّا للدولة العثمانية، واتجهت نحو الصرب، وكانت النمسا تطمَعُ أن تضمَّهما لها، فاتفقت مع روسيا سرًّا على أن تضمَّهما إليها مقابِلَ أن تكون الملاحة لروسيا حُرَّةً في البوسفور والدردنيل، وفعلًا قامت النمسا بضَمِّ البوسنة والهرسك إليها، ولم تستطع روسيا فِعلَ شَيءٍ لمعارضة الدول الأوربية لأطماع روس"},{"id":4802,"era":"c14","t":"وفاة الزعيم الوطني مصطفى كامل .","s":"هو مصطفى كامل بن علي محمد، زعيمٌ سياسيٌّ وكاتبٌ مصريٌّ وأحد روَّاد التحرير في مِصرَ، وُلِدَ سنة 1291ه في قرية كتامة التابعة لمركز بسيون بمحافظة الغربية، وكان أبوه علي محمد مِن ضبَّاطِ الجيش المصري، وقد رُزِقَ بابنه مصطفى وهو في الستينَ مِن عمره، ويعتبر مصطفى مؤسِّسَ الحزب الوطني المصري الذي تألَّف برنامجُه السياسي من عِدَّة موادَّ؛ أهمها: المطالبةُ باستقلال مصر ضِمنَ دولة الخلافةِ العثمانية، وإيجا"},{"id":4803,"era":"c14","t":"رضوخ السلطان العثماني عبد الحميد الثاني لجمعية الاتحاد والترقي .","s":"لم يعُدْ تنظيمُ الاتحاد والترقي خافيًا على الدولة ولا على الناسِ، بل قَوِيَت شوكتُهم العسكرية وألَّفوا عصاباتٍ في وجهِ الحكومة؛ إذ كان من ضِمن أعضائِه ضباطٌ كبار من الجيش الحكومي، وكان هذا التنظيمُ يسيطِرُ على الفيلق الأوَّلِ مِن الجيش الحكومي، وكذلك الفيلق الثاني والثالث، أما الرابع فكان فيه أنصارٌ لهم، فأرسل رجالُ الاتحاد والترقي البرقياتِ مِن كبريات المدن في الجهة الأوربية (سلانيك ومناستر وسكوب"},{"id":4804,"era":"c14","t":"ضم البوسنة والهرسك إلى النمسا .","s":"أعلن القيصرُ النمساوي فرانتس جوزيف الأول ضَمَّ بلاد البوسنة والهرسك ذات الأغلبية المسلِمة إلى بلاده بعد 30 عامًا من احتلالِها واغتصابِها مِن الدولة العثمانية، وذلك في إطارِ خِطَّةِ تقسيم أملاكِ الدولة العثمانية."},{"id":4805,"era":"c14","t":"إعلان بلغاريا انفصالها عن الدولة العثمانية .","s":"أعلنت بلغاريا انفصالَها عن الدولة العثمانية، كما أعلنت قيامَ نظام الحكم المَلَكي فيها من جانبٍ واحد. وقد وافقت الدولةُ العثمانية على هذا الاستقلال في ربيع الأول 1327هـ مقابِلَ حصولها على 5 ملايين ليرة ذهبية. كانت مساحةُ بلغاريا آنذاك أكثَرَ من 96 ألف كم2، ويزيد عددُ سكانها على 4 ملايين نسمة."},{"id":4806,"era":"c14","t":"افتتاح السلطان عبد الحميد الثاني مجلس المبعوثان (النواب) .","s":"افتتح السلطانُ عبد الحميد الثاني مجلِسَ المبعوثان (النواب) الذي كان النائبُ فيه يسمى (مبعوثًا) والذي ضمَّ 275 نائبًا، منهم 140 نائبًا تركيًّا، و60 عربيًّا، وعدد من النواب اليهود والنصارى والأرمن والصرب والبلغار والألبان."},{"id":4807,"era":"c14","t":"افتتاح الجامعة المصرية الأهلية رسميًّا .","s":"افتُتِحَت الجامعةُ المصريَّةُ الأهلية رسميًّا برئاسةِ الأمير أحمد فؤاد، وكانت البداياتُ الأولى لها متواضِعةً، ثم أخذت تتوسَّعُ نتيجة دعمِ كثيرٍ مِن المؤسَّسات والأفراد لها، ثم تحوَّلت الجامعة إلى جامعةٍ حكومية سنة 1344هـ/ 1925م باسم الجامعة المصرية، وهي التي تُعرَفُ الآن بجامعة القاهرة."},{"id":4808,"era":"c14","t":"خلع السلطان عبد الحميد الثاني آخر الخلفاء العثمانيين فعليًّا .","s":"بعد فوزِ الاتحاديِّين بأغلبيةٍ كبيرةٍ وإعلان الدستور أرادوا أن يُتِمُّوا خطَطَهم الراميةَ إلى خلع الخليفة، فبدؤوا يثيرونَ الفوضى والقلاقِلَ في الدولة بطُرُق غير مباشرة، وادَّعى رجال الاتحاد أنَّ الدستورَ معرَّضٌ للإلغاء والحريةَ مهدَّدةٌ؛ لذا فقد تقَدَّم الجيشُ المرابط في سلانيك بإمرةِ محمود شوكت لحماية الدستورِ والمجلس النيابي، عِلماً أنه كان فيه عناصِرُ أجنبية ترتدي الزيَّ العسكري، ووصل الجيشُ إ"},{"id":4809,"era":"c14","t":"عهد الاتحاديين في تركيا .","s":"بعد خَلعِ السلطانِ عبد الحميد الثاني أصبح كُلُّ شيء في الخلافةِ بيَدِ الاتحاديِّين، أمَّا الخليفةُ محمد رشاد فكان صورةً، غيرَ أن الأمر لم يطُلْ؛ إذ لم يتعاقَبْ على الخلافة سوى ثلاثة خلفاء، وكانت الدولةُ قد اشتركت في الحربِ العالمية الأولى بجانب ألمانيا، فهُزِمَت وتجزَّأت، وغادر البلادَ رِجالُ الاتحاد البارزين، أو الذين بيَدِهم الأمرُ والنهي، وجاء إلى الحُكمِ مصطفى كمال، وفي أيامِ الخليفة محمد رشاد"},{"id":4810,"era":"c14","t":"مظاهرة في عاصمة الخلافة العثمانية تطالب بالعودة إلى الشريعة .","s":"اشتعلت المظاهراتُ في عاصمةِ دولةِ الخلافةِ العُثمانية تطالِبُ بإلغاءِ الدستور، والعودةِ إلى الشريعةِ الإسلاميةِ، وإسقاطِ حُكومةِ الاتحادِ والترقي، التي تسلَّطَت على السلطانِ عبد الحميد الثاني وخلَعَتْه."},{"id":4811,"era":"c14","t":"وفاة بطرس باشا غالي رئيس وزراء مصر .","s":"هو بطرس باشا نيروز غالي، ولِدَ في عام 1262هـ/ 1847م قبطيٌّ من نصارى مصر. كان والده نيروز غالي ناظرًا للدائرة السَّنِيَّة لشقيق الخديوي إسماعيل في الصعيد. تلقَّى تعليمه في كلية البابا كيرلس الرابع. نشأ محبًّا للإنجليز؛ مِمَّا مهَّد لعمله في وزارة مصطفى فهمي، ثمَّ تولى منصب رئيس وزراء مصر من 12 نوفمبر 1908 إلى 1910م. اتُّهِم بمحاباته للإنجليز على حساب مصلحة مصر؛ فقد لعِبَ بطرس غالي دورًا مشبوهًا في "},{"id":4812,"era":"c14","t":"نشر الدولة العثمانية \"قانون الكنائس\" .","s":"قامت الدولة العثمانية بنشر \"قانون الكنائس\" الذي صار حُكمًا بين الأقليَّات البلغارية والصربية واليونانية الموجودة في مقدونيا في منطقة البلقان."},{"id":4813,"era":"c14","t":"وفاة المهدي قائد المقاومة الصومالية .","s":"هو محمد عبد الله حسن نور صومالي، قاد الجهاد ضِدَّ الاحتلال الإنجليزي والإيطالي والأثيوبي في مطلع القرنِ العشرينَ، وُلِدَ سنة 1856م، سماه الإنجليز «الملا المجنون» عندما واجه الاستعمارين البريطاني والإيطالي، واستطاع أن يقاوم المستعمرين لمدة عشرين عامًا، كبَّدهم أثناءها الخسائِرَ الفادحة، وانتزع حقَّ السيادة على مناطِقَ عديدة، خاض محمد بن عبد الله 270 موقعة في الجهاد ضدَّ البريطانيين انتصر في معظمها."},{"id":4814,"era":"c14","t":"صلح دعان بين الزيديين في اليمن والعثمانيين .","s":"تزعَّم المتوكِّلُ يحيى بن المنصور محمد بن حميد الدين اليمنيين؛ لمقارعة الأتراك، وتمكَّن من حصار صنعاء وأجبر الأتراك أخيرًا على الصلح المشهور بصلح دعان ضمن بنود كثيرة على الاعتراف به حاكمًا وحيدًا للطائفة الزيدية في اليمن مقابِلَ اعترافه بالسيادة العثمانية على اليمن، وهو ما جعل حربَه للأتراك تبدو وكأنها فقط لنيل الاعتراف بسلطته الدينية والسياسية على المناطق التي ينتشِرُ فيها المذهب الزيدي، وقد نفرت"},{"id":4815,"era":"c14","t":"عقد المؤتمر المصري بالقاهرة تحت رعاية الإنجليز .","s":"قُبَيل انتهاء المؤتمر القبطي بمصر نشرت بعضُ الصحفِ أنباءً عن تكوينِ لجنةٍ بالإسكندرية تضُمُّ بعضَ الأعيان في الأقاليم، مكلَّفةً بعقد مؤتمر ديني يضمُّ مندوبين عن المسلمين واليهود المصريين والنصارى؛ للنظر في المسألة القبطية. وفي ذات الوقت دارت اجتماعاتٌ في القاهرة بين عددٍ كبيرٍ مِن المشتغلين بالمسائل العامة، ومنهم فريق من حزب الأمة؛ لمناقشة المسألة القبطية ونتائج انعقاد المؤتمر القبطي في أسيوط، ودع"},{"id":4816,"era":"c14","t":"إرسال الإمبراطور الألماني طرادًا بحريًّا إلى ميناء أغادير المغربية .","s":"أرسل الإمبراطور الألماني جليوم طرادًا بحريًّا إلى ميناء أغادير المغربية؛ وذلك احتجاجًا على سياسة فرنسا في المغرب، فما كان من فرنسا إلا أن تنازلت لألمانيا عن الكاميرون، فأقرَّ لها الإمبراطور باحتلال مراكش."},{"id":4817,"era":"c14","t":"وفاة الزعيم أحمد عرابي قائد الثورة العرابية .","s":"هو الزعيم المصري أحمد عرابي بن محمد عرابي بن محمد وافي بن محمد غنيم من قبيلة المحامدة، انتقل جَدُّهم من بطائح العراق إلى مصر في أواسط القرن السابع للهجرة. ولِدَ في قرية (هرية رزنة) من قرى الزقازيق بمصر، وجاور في الأزهر سنتين، ثم انتظم جنديًّا في الجيش سنة 1271هـ وبلغ رتبة (أميرالاي) في أيام الخديوي توفيق. وهو قائد الثورة العرابية ومفجِّرُها ضِدَّ الخديوي توفيق. وقد فشلت هذه الثورة؛ وذلك نتيجة لخيا"},{"id":4818,"era":"c14","t":"إبلاغ إيطاليا الدولةَ العثمانية بضرورة تسهيل احتلالها لليبيا .","s":"أبلغت إيطاليا الحكومةَ العثمانية عن نيَّتِها باحتلال ليبيا، وطلبت منها تسهيلَ الاحتلال بحجَّة حماية رعاياها من الاضطهاد العثماني، والمحافظة على المصالح الاقتصادية للإيطاليين. وكان الموقِفُ العثماني في ظل عهد جماعة الاتحاد والترقي ضعيفًا جدًّا أمام التهديد الإيطالي، فاكتفت بدعوة إيطاليا للجلوس إلى طاولة المفاوضات تجنبًا لاستخدام القوة. ولكن الحكومة الإيطالية رفضت ذلك؛ لعدة أسباب، من أهمها: أ- ضعف ا"},{"id":4819,"era":"c14","t":"الإيطاليون يستعمرون ليبيا .","s":"كانت إيطاليا تطمَحُ بالسيطرة على طرابلس، وخاصةً بعد أن احتلَّت فرنسا تونس عام 1299هـ وبدأت إيطاليا تعقِدُ الاتفاقات السياسية مع الدول الأوربية الأخرى، مثل إسبانيا وفرنسا وإنجلترا والنمسا، ثم انصرفت إلى تهيئة الوضعِ داخِلَ ليبيا، فعَمِلَت على شراء الأراضي وإنشاء المشروعات الزراعية، وإرسال البعثات النصرانية الكاثوليكية، وفتح المدارس الإيطالية، وتأسيس شركات النقل بين البلدين، ومسْح السواحل بحجَّة الب"},{"id":4820,"era":"c14","t":"جرائم الاحتلال الإيطالي بحق الليبيين .","s":"عندما اجتاحت القوات الإيطالية طرابلس قبضت على ألوف من أهلها في بيوتهم ونفتهم بدون أدنى مسوِّغ إلى جزر إيطاليا؛ حيث مات أكثرهم من سوء المعاملة. وأباد الإيطاليون في غير ميدان الحرب كل ليبي يزيد عمره على (14) سنة، وأحرقوا يوم 26 تشرين الأول أكتوبر أحياءً خلف بنك روما، وبعد أن ذبحوا كثيرًا من السكان بينهم النساء والشيوخ والأطفال، في اليوم التالي وصف أحد المراسلين ما وقع عليه بصرُه بقوله: (صادفت 50 جند"},{"id":4821,"era":"c14","t":"انتفاضة مسلمي تونس ضد الاحتلال الفرنسي .","s":"انتفض المُسلمون في تونس ضِدَّ الاحتلال الفرنسي؛ وذلك بسبب إصرار الفرنسيين على نبشِ قبور موتى المسلمين بهدفِ مَدِّ خط حديدي عبر مقبرة \"الزلاج\"."},{"id":4822,"era":"c14","t":"حرب البلقان الأولى مع العثمانيين واستقلال بلاد البلقان .","s":"رفضت البوسنة والهرسك دعوةَ مندوبيها لحضور المجلس النيابي في استانبول عام 1327هـ مع أنها لا تزال تتبع الدولة العثمانية اسمًا، واتجهت نحو الصرب، وهذا ما أثار النمسا التي اتفقت مع روسيا سرًّا على أن تضم البوسنة والهرسك إليها مقابِلَ إبقاء مضائق البوسفور والدردنيل مفتوحةً دائمًا لروسيا، وبالفعل قامت النمسا باحتلالهما، وزاد العداء بين النمسا والصرب، وأما إيطاليا فكان لها مطامِعُ فيهما، فعقدت أيضًا اتفا"},{"id":4823,"era":"c14","t":"ملك أفغانستان يدعو لحملة تبرع لدعم الشعب الليبي ضد إيطاليا .","s":"دعا جلالةُ ملك أفغانستان حبيب الله خان جميعَ وجوه مملكته ورجال حكومته وأعيانها وتجارها، دعاهم لاجتماع عظيم، وعَرَض عليهم القضيةَ الطرابلسية وما يعانيه المسلمون في طرابلس الغرب من الظلم والعدوان، ودعاهم إلى الإنفاق وجمْع الأموال وفتْح كتاب أسماه كتاب (إغاثة يتامى وشهداء ومجروحي مجاهدي طرابلس الغرب) وقال لهم: افتحوا كيس همَّتكم وبلُّوا قلوبكم بماء الشفقة الأخوية، أعينوا يتامى وأيامى أولئك المجاهدين "},{"id":4824,"era":"c14","t":"دعم العالم الإسلامي للشعب الليبي في جهاده ضد الاحتلال الإيطالي .","s":"أبلى الشعب الليبي بلاءً حسنًا في جهاده ضد المحتل الإيطالي الصليبي، فلما طارت أخبارُ معارك بنغازي وطرابلس ودرنة إلى العالم أجمع، ورأت حكومة الأتراك أنَّ الشعب الليبي جديرٌ بالمساعدة وجادٌّ في جهاده وكفاحه ضِدَّ العدو، أرسلوا الإمدادات، فقام أنور باشا وزير الحربية التركية باختيار مجموعاتٍ من الشباب الليبي، واستقبلهم في استانبول لتعليمهم النظم السياسية والعسكرية الجديدة؛ ليُشرِفوا على قيادة الجيش الو"},{"id":4825,"era":"c14","t":"الاستعمار الفرنسي والإسباني على المغرب .","s":"عندما ساعد الملِكُ عبد الرحمن بن هشام العلوي الأميرَ عبد القادر الجزائريَّ في مقاومته الاحتلالَ الفرنسي للجزائر، احتجَّت فرنسا على هذه المساعدة، واحتَلَّت مدينة وجدة مقابل ذلك، ثم احتلَّ الإسبان مدينة تطوان لكنَّهم خرجوا منها بعد دفع أموال باهظة لهم، وفي أيام الحسن الأول عُقِدَت معاهدةُ مدريد عام 1298هـ وأصبح لمدينة طنجة مجلس صحي يتناوب رئاستَه قنصلا فرنسا وإسبانيا وأعلنت فرنسا عام 1300هـ الحمايةَ"},{"id":4826,"era":"c14","t":"النمسا أول الدول الأوروبية اعترافًا بالدين الإسلامي في البلاد. .","s":"اعترفت النمسا بالإسلامِ كدين رسمي في البلاد في عهد القيصر فرانس جوزيف، وهو ما منحهم ميزاتٍ كبيرة استنادًا إلى نصوص الدستور الذي يساوي بين الجالية المسلِمة وغيرها من معتنقي الديانات الأخرى. وضَمِنَ الاعتراف الرسمي بالدين الإسلامي حقوقَ الجالية المسلمة في مواضِعَ مختلفة، مثل حرية ممارسة الشعائر الدينية، وحرية المسلمين في تنظيم الرعاية الدينية الخاصة بهم، وحصول مؤسَّساتهم على حق حماية جميع أنشطتها ال"},{"id":4827,"era":"c14","t":"مواجهة البحرينيين للبعثة الأمريكية التنصيرية .","s":"كانت حملات التنصير قد وصلت إلى البحرين عام 1893م وتأسَّست أولُ مدرسة للتعليم بالأسلوب الغربي الحديث في البحرين على يدِ البعثة، وفي عام 1894 افتتحت الإرساليةُ الأمريكية مكتبةً عامةً لها بالمنامة وبدأت عمَلَها في تقديم بعضِ الصُّحُفِ والكتُبِ لروَّادِها، ثم أنشأت الإرساليةُ الأمريكيةُ مستشفى ماسون التذكارية، ودكانًا لبيع الإنجيل، وحينها كان مجلِسُ الشيخ إبراهيم بن محمد آل خليفة ابن حاكم البحرين يُعَ"},{"id":4828,"era":"c14","t":"معاهدة طهران بين الدولة العثمانية وإيران بشأن الحدود .","s":"جرت عِدَّةُ معاهدات بشأن الحدود بين الدولتين العثمانية والإيرانية، ومنها: معاهدة أرضروم الثانية 1263هـ غير أنَّها فشلت واستمَرَّت الاشتباكات على الحدود، وفشلت لجنة التخطيط بناءً على المعاهدة المذكورة في إنهاء المشكلة، كما بدأ الخلاف في تفسير نصوص المعاهدة، وكانت كلٌّ من إنجلترا وروسيا ترغبان في إنهاء هذا الموضوع؛ حيث أصبحت المنطقة ساحةَ نفوذ لكلٍّ مِن الدولتين، فدعا ذلك لإجراء مفاوضات مباشِرة بتوس"},{"id":4829,"era":"c14","t":"ثورة أحمد وهبة ضد فرنسا في المغرب .","s":"فرض الفرنسيون الحمايةَ على المغرب، وبعد أيامٍ مِن فرض الحماية قام المغاربة بثورةٍ عارمة في فاس ثار فيها الجيشُ والشعب، تزعَّمها المجاهِدُ أحمد هبة الله ابن الشيخ ماء العينين، وكانت الانتصارات فيها سِجالًا بين الفريقين، وانتهى الأمرُ بوفاة الرجل، وتمكن الفرنسيون من بسطِ نفوذهم على المغرب أثناء الحربِ العالمية الأولى."},{"id":4830,"era":"c14","t":"انسحاب الدولة العثمانية من الحرب الليبية وتوقيع معاهدة مع إيطاليا .","s":"بعد أن أعلنت إيطاليا الحرب على الدولة العثمانية، وهي الحرب التي عُرِفت بالحرب الإيطالية - الطرابلسية. حاصر الأسطول الإيطالي مدينةَ طرابلس الغرب مدةَ ثلاثة أيام، بعدها سقطت المدينةُ بيد المستعمرين الإيطاليين. ولم تتوفر للمقاومة الشعبية القوة اللازمة لقهر الإيطاليين ورَدِّهم على أعقابهم. كما لم تكن قدرةُ الدولة العثمانية القتالية بالمستوى المطلوب، ولم تكن القوة بين الطرفين متكافئة، ورغم المقاومة الع"},{"id":4831,"era":"c14","t":"اقتسام فرنسا وإسبانيا شمال أفريقيا (مراكش) .","s":"في أعقاب الوحدة الألمانية عام 1286هـ/ 1870م. وذلك عندما بدأت ألمانيا تعاني من مشكلة عدم تملُّكها للمستعمرات أسوةً ببريطانيا وفرنسا حتى تستطيع تصريفَ منتجاتها، والحصول على المواد الخام اللازمة لصناعتها وإنشاء أسواق لها فيها، ومن هنا بدأت ألمانيا تتطلَّعُ للبحث عن مستعمرات لها في خارج أوروبا؛ ونتيجة لذلك بدأ التنافس بينها وبين فرنسا من أجل مراكش فتصَدَّت فرنسا لهذه المحاولة، وذلك بربط نفسها بعدة اتف"},{"id":4832,"era":"c14","t":"نشأةُ الأرطاوية أول هجر الإخوان في جزيرة العرب .","s":"الأرطاوية موقع على طريق القوافل من الكويت إلى القصيم بالقرب من الزلفي، فيه مجموعة من الآبار، وأول من سكنها كان عددٌ من أهالي مدينة حرمة يقَدَّر عددهم بثلاثين رجلًا، وكانوا قد ارتحلوا في هذا العام من حرمة إلى الأرطاوية؛ بسبب نزاع دبَّ بينهم وبين أهلها حول تشدُّدهم الديني. فلما لم يطِبْ لهم المقام في حرمة اختاروا موضِعَ الأرطاوية حيث الآبار والموارد وجودة المرعى، ثم نزلها إحدى عشائر العريمات وشيخها "},{"id":4833,"era":"c14","t":"هجر الإخوان في عهدُ الملك عبد العزيز .","s":"كانت الأرطاوية أول هجرة نشأت في نجد سنة 1329هـ حيث تولى رئاستها زعيم مطير فيصل الدويش , والتي تقع في الطريق بين الكويت والقصيم بقرب الزلفي ثم بعده نشأت هجرة الغطغط والتي تقع جنوب غربي الرياض حيث سكنها جزء من عتيبة تحت قيادة سلطان بن بجاد , ثم تتابع نشوء الهجر التي استوطنتها قبائل الجزيرة العربية بتشجيع ودعم الملك عبدالعزيز لها حيث وفر لهم المياه بحفر الآبار وبناء المساجد وتوفير المؤن الغذائية لهم "},{"id":4834,"era":"c14","t":"ضم الملك عبدالعزيز الأحساء .","s":"بدأ الملك عبدالعزيز بالاستعداد في القيام بدخول الأحساء فاتفق مع بعض كبار رجالات أسر الأحساء في تنفيذ عملية الفتح. غادر الملك عبدالعزيز الرياض بقواته إلى الأحساء ووصل الرقيقة ومعه 600 جندي ثم وصل الكوت من الناحية الغربية ثم اجتاز أسوار المدينة بعد أن فاجأ الحامية التركية التي سرعان ما أذعنت له بالاستسلام ثم أجلاها إلى البحرين، ولقي عبدالعزيز ترحيب السكان به، ورغم معرفة الملك عبدالعزيز موقف بريطانيا"},{"id":4835,"era":"c14","t":"اغتيال رئيس الوزراء العثماني محمود شوكت .","s":"هو محمود شوكت باشا بن سليمان طالب العمري الفاروقي بالولاء، وهو قائِدٌ عراقي، ولي رئاسةَ الوزراء في الدولة العثمانية، وعَلَت شهرتُه في حركة الدستور العثماني. ولِدَ ببغداد سنة 1275ه وكان أبوه متصرفًا في المنتفق، فتعلَّم بها ثم بالمدرسة الحربية في الأستانة، وتقدَّم في المناصب العسكرية إلى أن أعطِيَ لقب فريق، وعيِّن واليًا لقوصوه، فقائدًا للفيلق الثالث بسلانيك. وكان من أعضاء جمعية (تركيا الفتاة) السِّ"},{"id":4836,"era":"c14","t":"حرب البلقان الثانية .","s":"نشبت حرب البلقان الثانية، وكان سببها هو رغبة بلغاريا في انتزاع إقليم مقدونيا الشمالية من صربيا، وقد انتهت هذه الحرب بعد 42 يومًا من اشتعالها، بمعاهدة \"بوخارست\" في أغسطس 1913م.كان الصرب والبلغار يأملون أن تساعدهم روسيا في المستقبل؛ لذلك تنصَّلوا من وعودهم للنمسا في عدم القيام بدعاية للجامعة الصربية والدولة السلافية الكبرى في داخل النمسا والمجر، وانتهى الأمر بتكوين العصبة البلقانية التي تضمُّ بلغاري"},{"id":4837,"era":"c14","t":"توقيع معاهدة بين الدولة العثمانية وبريطانيا .","s":"وقَّعت بريطانيا والدولةُ العثمانية معاهدةً تتضَمَّنُ اعتراف الدولة العثمانية باستقلال الكويت وترسيم خرائط حدودية بين البلدين واعتراف الدولة العثمانية بملكية الكويت على جُزُر مثل وربة وبوبيان ومسكان وفيلكا وعوهة وكبر، واعترفت بحقِّ شيخ الكويت في الحصول على الزكاة من القبائل المحيطة بالكويت بمسافة 362 كيلومترًا. ولكِنْ بعد نشوب الحرب العالمية الأولى التي أصبحت فيها بريطانيا والدولة العثمانية أعداء ت"},{"id":4838,"era":"c14","t":"مصر تحت الحماية البريطانية .","s":"تعرَّضت مصر للاحتلال الإنجليزي ثلاثَ مرات؛ الأولى بحجة إخراج الفرنسيين من مصر؛ لعجز الدولة العثمانية وحدها عن إخراجهم، والثانية سنة 1807م وكانت من أخلاط من الجنود، والثالثة كانت سنة 1882م وبقيت أكثر من ثلاث وسبعين سنة، فعاصر الاحتلال البريطاني حكم خمسة من حكام أسرة محمد علي هم: توفيق، وإسماعيل، وحلمي الثاني، وحسين كامل، وفؤاد، وفاروق، واستطال إلى الأيام الأولى من الحُكم الجمهوري في مصر، وإذا كانت "},{"id":4839,"era":"c14","t":"عزل بريطانيا للخديوي عباس حلمي عن عرش مصر .","s":"قامت بريطانيا بعزل الخديوي عباس حلمي عن عرش مصر، وتعيين عمه \"حسين كامل\" وأطلقت عليه لقب سلطان؛ نكاية بالسلطان العثماني، وذلك بعد قرارها بإعلان الحماية على مصر. وكان ذلك الإجراءُ في إطار سياسة بريطانيا الرامية إلى عزل مصر عن الدولة العثمانية التي كانت قد دخلت الحربَ العالمية الأولى ضدَّ إنجلترا ودول الحلفاء."},{"id":4840,"era":"c14","t":"مراسلات حسين مكماهون بين بريطانيا والشريف حسين .","s":"استغَلَّت بريطانيا المشكلةَ التي بدأت تحدُثُ بين الأتراك والعرب، فعملت بريطانيا لإغراء الشريف حسين وإعداده نفسيًّا للثورة على الدولة العثمانية، وأبدَوا استعدادهم لمساعدته في قضيته، فبدأ الشريف حسين بإرسال رسالته الأولى إلى السير هنري مكماهون نائب ملك بريطانيا في مصر في 14 تموز 1915م ثم تبِعَتْها رسائل أخرى، وكلها خمس رسائل، كان آخرها رد مكماهون في آذار 1916م، وكان الإنجليز يزيدون في تبجيل الشريف و"},{"id":4841,"era":"c14","t":"اندلاع الحرب العالمية الأولى (العظمى) وانضمام تركيا إلى جانب ألمانيا .","s":"انقسم المعسكر الأوربي إلى قسمين؛ الأول: ضَمَّ دولَ المحور: ألمانيا، والنمسا، وبلغاريا، وانضمت لهم الدولةُ العثمانية بسبب تعاملها مع ألمانيا في المجال العسكري؛ حيث كانوا هم مدرِّبي الجيوش العثمانية، والقسم الثاني: دول الحلفاء، ضم: إنجلترا، وفرنسا، وروسيا، وإيطاليا، ورومانيا، واليونان، واليابان، و كانت تسمَّى بالحرب العظمى، وبعد قيام الحرب العالمية الثانية عُرِفَت بالحرب العالمية الأولى، بينما الأمر"},{"id":4842,"era":"c14","t":"انضمام الدولة العثمانية إلى جانب دول المحور في الحرب العالمية الأولى .","s":"حاول الحلفاءُ إبقاءَ الدولة العثمانية على الحياد بإغرائِها بالقروض المالية، وإلغاء الامتيازات الأجنبية التي كانت قائمةً والتي كانت سببًا في كثير من المشكلات الداخلية، والسماح للبحَّارة الألمان بالعودة إلى ألمانيا، غيرَ أنَّ حكومة الاتحاد والترقي رفضت هذا كلَّه، وألغت الامتيازاتِ الأجنبيةَ بنفسها، وقدَّمت مذكِّرةً للحلفاء تطلب منهم إلغاء الامتيازات الأجنبية، وخروج إنجلترا من مصر، وإعادة الجُزُر في "},{"id":4843,"era":"c14","t":"وفاة الشيخ شبلي النعماني أحد علماء الهند .","s":"هو الشيخ شبلي حبيب الله بن سراج الدولة النعماني، أحد علماء الهند. اعتنى به والدُه الشيخ \"حبيب الله\"؛ حيث كان من العلماء، فنشأ محبًّا للعلم. رحل شبلي في طلب العلم، وتنقل بين لكنو ودلهي ولاهور ورامبور وسهارنبور وغيرها من المدن الهندية، فدرس الأدب والفقه، والحديث وعلوم الفارسية والأدبية والعربية، كما درس الهندسة والمنطق والفلسفة، وتلقَّى العلم على عدد من شيوخ الهند، منهم الشيخ \"محمد فاروق الجرياكوتي\""},{"id":4844,"era":"c14","t":"موقف الملك عبد العزيز من أطراف الصراع في الحرب العالمية الأولى  .","s":"عندما اندلعت الحربُ العالمية الأولى بعث الملك عبدالعزيز برسائل إلى كل من الشريف حسين في مكَّةَ، وسعود بن صالح في حائل، والشيخ مبارك الصباح في الكويت، يقترح عليهم عقدَ لقاء بين حكَّام العرب للحيلولة دون جَرِّهم إلى العمليات الحربية، وتوقيع معاهدة مع الدول الكبرى لضمان تقريرِ مصير البلاد العربية، ولم تكن مصالحُهم متوافقةً آنذاك؛ لذلك تعذَّر وضعُ موقفٍ مشترك؛ فأمير حائل ردَّ بأنه سيقاتل مع الدولة الع"},{"id":4845,"era":"c14","t":"إعلان إنجلترا فصل مصر عن الدولة العثمانية .","s":"كانت إنجلترا قد احتلَّت مصر، ولكِنْ مع ذلك بقي الولاةُ عليها من قِبَل الدولة العثمانية، وبقيت تابعةً اسمًا ورسميًّا للدولة العثمانية، ثم بعد أن اندلعت الحرب العالمية الأولى قامت إنجلترا بسبب ظروفِ الحرب بفَرضِ الحماية على مصر لتبعيَّتِها الرسمية للعثمانيين، ولأن العثمانيين وقفوا بجانب ألمانيا ضِدَّ الحلفاء الذين من بينهم إنجلترا، وأعلنت كذلك فَصْلَ مصر عن الدولة العثمانية رسميًّا، وخلعت الخديوي عب"},{"id":4846,"era":"c14","t":"إنشاء معاهدة حدودية بين الدولة العثمانية وبريطانيا .","s":"تمَّ إنشاءُ معاهدة حدودية بين الدولةِ العثمانيةِ وبريطانيا؛ لتعيينِ الحدودِ بين شمال اليمن العثماني، وجنوب اليمن البريطاني، وكانت هذه المعاهَدةُ بالنسبة لبريطانيا أهمَّ حَدَثٍ بعد احتلال عدَن عام (1255هـ- 1839م)، وتم التصديقُ عليها عام (1333هـ- 1914م) وبهذه المعاهدة تعرَّضت اليمَنُ لأوَّلِ انشطار إلى جنوبٍ وشمال في التاريخ."},{"id":4847,"era":"c14","t":"فرنسا تصدر مرسومًا في المغرب خاصا بالبربر عرف بالظهير البربري .","s":"وضعت فرنسا نُصبَ عينيها لَمَّا دخلت المغرب أن تفَرِّقَ بين العرب وبين البربر؛ لتضرب جماعةً بأخرى، وذلك من باب فَرِّق تسُدْ، وخاصة أن البربر يشكِّلون أكثَرَ من أربعين بالمئة، وفكَّرت بتنصيرهم، ثم استصدرت السلطاتُ الفرنسية مرسومًا (ظهيرًا) عرف بالظهير البربري أعفت فيه البربرَ من تطبيق الشريعة الإسلامية، ومن دراسة اللغة العربية، وسمحت لهم بالتقاضي حسب الأعراف والتقاليد البربرية، وبدراسة اللغة البربري"},{"id":4848,"era":"c14","t":"احتلال مدينة البصرة بقوة بريطانية .","s":"قامت قوةٌ بريطانية قادمة من الهند باحتلالِ مدينة البصرة أثناء اشتعال الحربِ العالمية الأولى، وكان الهدفُ من ذلك حماية أنابيب البترول وتأمين وصولِ الإمدادات."},{"id":4849,"era":"c14","t":"الاحتلال الإنجليزي للعراق وقتالهم مع الجيوش العثمانية .","s":"وصلت الحملةُ الإنجليزية من الهند إلى شطِّ العرب في آخر سنة 1332هـ ثم في اليوم التالي احتَلَّت الفاو، جنوب البصرة ثم البصرة في الخامس من محرم، واستمرت النجداتُ تصل إلى الحملة الإنجليزية حتى احتلت العمارة في 21 رجب، كما سيطرت على القرنة والشعبية وبَقِيَت حكومةُ الهند والحكومة الإنجليزية لا يتقدَّمان إلى بغداد حتى شجَّعهم فشل القوات العثمانية في السويس ونجاح مراسلات حسين ومكماهون فتقَدَّموا واحتلوا ا"},{"id":4850,"era":"c14","t":"معركة جراب بين الملك عبدالعزيز وقوات ابن رشيد .","s":"اشتبكت قوات الملك عبدالعزيز مع قوات ابن رشيد قرب بئر جراب شمالي الزلفي وكانت قوات الملك عبدالعزيز تتكون في معظمها من أهل العارض وثلاثمائة خيال من العجمان ومدفع واحد فقط وبعض البادية المتأثرين بفكر الإخوان (إخوان من أطاع الله) الحركة الناشئة داخل الجزيرة العربية  واستمرت المعركة عدة إيام وقتل أثناءها شكسبير مبعوث كوكس إلى الملك عبدالعزيز وقيل انه حضر المعركة كمراقب على الرغم أن الملك عبدالعزيز كان "},{"id":4851,"era":"c14","t":"مطالبة روسيا بالقسطنطينية في حالة فوز الحلفاء بالحرب .","s":"قام سازونوف وزير الخارجية الروسي بتسليم مذكرة إلى ممثلي إنجلترا وفرنسا، يطالب فيها لروسيا بالقسطنطينية، وبشريط على طول الساحل الشمالي للبسفور وبحر مرمرة والدردنيل، وكذلك تراقيا، وبالجانب الأسيوي للبسفور، وذلك في حالة فوز الحلفاءِ بالحرب."},{"id":4852,"era":"c14","t":"مذابح الأرمن ضد المسلمين في مدينة \"وان\" .","s":"قامت العصاباتُ الأرمينية بارتكابِ مذابِحَ وحشية ضِدَّ المسلمين في مدينة \"وان\" الواقعة في الأناضول الشرقية؛ حيث قامت بقتل جميعِ من فيها من المسلمين بعد تعذيبٍ وحشيٍّ."},{"id":4853,"era":"c14","t":"معركة القرضابية  .","s":"معركةُ القرضابية من المعارك الفاصلة في جهاد الليبيين ضِدَّ إيطاليا؛ إذ شارك فيها جميعُ الليبيين، كما أنها شكَّلت البداية لاندحار الإيطاليين، وبعد المعركةِ لم يبقَ بيد الإيطاليين إلا مدينتا طرابلس والخمس."},{"id":4854,"era":"c14","t":"معركة كنزان بين الملك عبد العزيز وبني هاجر والعجمان .","s":"حدثت هذه المعركة بين الملك عبد العزيز وبني هاجر والقبائل التابعة له وبين قبيلة العجمان بالقرب من جبل كنزان في الأحساء عندما اعتدى العجمان  على عشائر مبارك بن الصباح فنهبوا مواشيه فكتب ابن الصباح إلى عبدالعزيز يطلب منه تأديبهم ورد المنهوبات فأجابه عبدالعزيز أن العجمان لا يرجعون ما ينهبون إلا بحرب، وإذا عزمت عليّ حربهم تعطيني عهد الله وميثاقه ان تعيني بالمال والرجال وأن لا تسلك معهم مسلكا غير مسلكي "},{"id":4855,"era":"c14","t":"انقلاب مبارك بن الصباح على الملك عبدالعزيز .","s":"قدم سالم بن مبارك ابن الصباح مع قوة صغيرة لنجدة الملك عبدالعزيز بعد هزيمته من العجمان إلا أنه انقلب على الملك عبدالعزيز واتفق مع العجمان وصالحهم وأعلن حمايتهم وهجر حليفه الملك عبدالعزيز، فكتب محمد بن عبدالرحمن إلى أخيه عبدالعزيز يستأذنه في الهجوم على العجمان وابن الصباح فأجابه: \" لا تفعل كيف نكون حلفاء أول النهار وأعداء في آخره والناس لا يعرفون حقيقة الحال\" ثم كتب إلى مبارك يشكو إليه خيانة ابنه سا"},{"id":4856,"era":"c14","t":"محاولة السنوسيين بليبيا غزو غرب مصر .","s":"رأى السنوسيون في برقةَ مؤازرةَ الدولة العثمانية استجابةً لدواعي الجهاد الديني والتضامن الإسلامي، وذلك بالهجوم على القوات البريطانية في مصر، وكان كلٌّ من العثمانيين والإنجليز يحاولون كسبَ السيد أحمد الشريف السنوسي لصَفِّه، ولكن رغم ما قدَّمه هنري مكماهون للسنوسي من أجل كسبِه إلى طرفه إلَّا أنه آثر البقاءَ مع العثمانيين، فقام بمهاجمة الحدود المصرية الغربية، وتوغَّل داخِلَ الأراضي المصرية، ونازل القو"},{"id":4857,"era":"c14","t":"أوروبا تُرغم ملك الحبشة على التنازل عن عرشه بعد إعلان إسلامه .","s":"بعد أن هلك منليك الثاني ملك الحبشة عام 1331هـ/ 1913م خلَفَه حفيده ليج أياسو الذي كان بالأصل مسلما؛ وإن تسمَّى ليج باسم نصراني ونشأ في رعايةِ جَدِّه النصراني منليك الثاني والد أمه أرجاس، إلا أنه كان يتردَّد على مساجد هرر، وشيَّد المساجد فيها، واتخذ عَلَمًا جديدا للدولة، فوضع الهلال بدل الصليب، وأرسل هذا العلم إلى القنصل العثماني في أديس أبابا واتَّصل مع محمد عبد الله حسن مهدي الصومال، وحاول ليج توح"},{"id":4858,"era":"c14","t":"إنهاء حركة علي دينار وضم دارفور للسودان .","s":"كانت أسرة سولونغ تحكم منطقة دارفور غرب السودان حتى عام 1293هـ، ثمَّ بعد أن أعيد الحُكمُ الإنجليزي على السودان وبعد معركةِ كرري 1316هـ غادر أم درمان علي دينار بن زكريا السولونغي ومعه عشرة أفراد، وانضم لهم في طريقِهم قرابةُ الألفي رجلٍ، واتجه نحو دارفور، ولما وصل الفاشر سلمت له وبدأت المنافسة بينه وبين إبراهيم علي الذي وضعته القواتُ الإنجليزية في دارفور، فتنازل إبراهيم لعلي دينار الذي استطاع أن يضبِ"},{"id":4859,"era":"c14","t":"اتفاقية (سايكس بيكو) وفرض الاحتلال الأوروبي على الشرق الأوسط .","s":"في الوقت الذي كان الشريف حسين بن علي أميرُ مكة ما زال يتفاوضُ مع السير هنري مكماهون لإعلان الثورة العربية، كانت إنجلترا تعقِدُ صفقةً جديدة مع فرنسا لتحديدِ مناطق النفوذ بينهما في البلاد العربية، منعًا لأي خلاف قد يحدثُ في المستقبل، وهذه الاتفاقية -التي عُرِفَت باسم واضعيها السير مارك سايكس الإنجليزي، والدبلوماسي جورج بيكو الفرنسي- هي جزء من اتفاقية واسعة عقدتها دول روسيا وبريطانيا وفرنسا بين بعضها"},{"id":4860,"era":"c14","t":"وفاة الشيخ مبارك بن صباح أمير الكويت .","s":"هو مبارك بن صباح بن جابر بن عبد الله بن صباح، من عنزة، أمير الكويت، مِن الشُّجعان الدُّهاة، ولِدَ سنة 1252هـ في الكويت ونشأ فيها. كان نفوذ الكلمة فيها لأخويه (محمد، وجراح) فقتلهما سنة 1313هـ واستقام له أمر الكويت، وصار حاكِمَها المُطلَق. وهو سابع من وَلِيَها من آل الصباح. وكان للعثمانيين (الترك) شيءٌ من السلطان في الكويت، فحرَّضوا ابن الرشيد على مبارك، فظَفِرَ مبارك. فحاولوا نفيَه سنة 1315هـ بحيلة"},{"id":4861,"era":"c14","t":"معاهدة دارين (القطيف) .","s":"وقّعت هذه المعاهدة عند بلدة دارين في جزيرة تاروت المقابلة لميناء القطيف، ونصت المعاهدة على اعتراف بريطانيا بأن عبدالعزيز حاكما مستقلا في نجد والأحساء والقطيف والجبيل ولأبنائه من بعده."},{"id":4862,"era":"c14","t":"فشل بريطانيا وحلفائها في الاستيلاء على مضيق البوسفور والدردنيل .","s":"مارست الدولةُ العثمانية سيادتَها على مضيقي البوسفور والدردنيل، وبحر مرمرة، وكانت هذه المضايقُ تصِلُ بين البحر الأسود وبحر إيجة الذي هو جزءٌ من البحر المتوسط، ولم يكن للبحر الأسود مخرجٌ يتَّصِلُ عن طريقه بالبحار العامة إلا عبر هذه المضايق. وقد نجحت الدولةُ العثمانية في فرض سيادتها على هذه المضايق. وبلغ من هيبة الدولةِ العثمانية في فترة قوَّتِها أنَّ الرعايا الروس إذا أرادوا ممارسةَ التجارة بين موان"},{"id":4863,"era":"c14","t":"انتصار العثمانيين على الإنجليز في معركة \"كوت العمارة\" في العراق .","s":"كان للإنجليزِ في العراق نفوذٌ واسعٌ لا سيما في مناطق حقول النفط هناك، وفي المناطق الجنوبية الشرقية من إيران؛ لذا فقد أنزلوا سنة 1914 قوةً من الجيش البريطاني الذي رابط في الهند، فاحتلت البصرة وتوجَّهت صوب بغداد لاحتلالها، ولكنها اصطدمت بالجيش التركي بقيادة الجنرال الألماني فون دير غلوتز، فأوقع بالجيشِ البريطاني خسائِرَ فادحة وكارثة عظيمة؛ إذ استسلم له عند \"كوت العمارة\" جيشٌ قوامه 13 ألف جندي وضابط "},{"id":4864,"era":"c14","t":"ثورة ضد الأتراك وإعلان الشريف حسين نفسه ملكا على الحجاز .","s":"كانت مُراسلاتُ \"حسين - مكماهون\" التي دارت بين شَريف مكةَ الشَّريفِ حسين، ونائبِ الملِكِ البريطاني في القاهرة هنري مكماهون، تمثِّلُ مقدِّماتِ الثورةِ العربية، ومن أبرزِ أسبابِها، والتي وعدت فيها بريطانيا الشريفَ حسينًا بالمساعدة وتنصيبِه ملكًا على العربِ، وإقامةِ خلافةٍ عربيةٍ إسلاميةٍ، كما أنَّ هناك أسبابًا أخرى، منها: الضَّعفُ الذي دَبَّ في أطرافِ الدولةِ العثمانية التي كانت تحكمُ المناطِقَ العرب"},{"id":4865,"era":"c14","t":"حصار المدينة أثناء الحرب العالمية الأولى (سِفِر بِرلِك) (النفير العام) .","s":"وقفت الدولةُ العثمانية في الحرب إلى جانب دول المحور، بينما أعلن الشريف حسين الثورةَ على الدولة العثمانية ووقف إلى جانب دول الحلفاء، وتمكنت قواتُ الشريف حسين مدعومةً من قوات الحلفاء -وخاصة بريطانيا- من السيطرة على معظم بلاد الحجاز عدا المدينة، فحوصرت حصارًا يعدُّ واحدًا من أطول الحصارات في التاريخ؛ حيث استمَرَّ الحصار لمدة سنتين وسبعة أشهر حتى بعد انتهاء الحرب العالمية الأولى، وكان والي المدينة هو "},{"id":4866,"era":"c14","t":"الخلاف بين الملك عبدالعزيز وآل الصباح .","s":"أثار نموُّ عبد العزيز بن سعود في نجدٍ قلقَ آل صباح؛ لذلك ساعد آل الصباح العجمانَ عندما تمرَّدوا على الملك عبدالعزيز واستقبلوهم لَمَّا هربوا منه، كما ظهرت أزمةٌ بين الملك عبدالعزيز والعوازم، وهم من أتباع آل الصباح في الكويت، لَمَّا فرض عليهم الملك عبدالعزيز الزكاةَ، وحرَّضَهم على هجر الكويت والاستقرار في نجدٍ؛ لذلك زار الكولونيل هاملتون الرياضَ لينقل إلى الملك عبدالعزيز احتجاجَ سالم الصباح على تجاو"},{"id":4867,"era":"c14","t":"مؤتمر الكويت برئاسة برسي كوكس المعتمد البريطاني لدعم الثورة العربية .","s":"دعا برسي كوكس المعتمد البريطاني إلى مؤتمرٍ عربيٍّ إعلامي لشَدِّ أزْر الشريف حسين، وإثبات تأييد العربِ له، فعقد اجتماعًا موسَّعًا في الكويت دعا إليه الشيخ جابر بن مبارك، والملك عبدالعزيز، وخزعل الكعبي أمير عربسات، ومئة شيخ من شيوخ عشائر قبيلة مطير، والظفير، والعجمان، وغيرهم من شيوخ القبائل، وأعلن في المؤتمَرِ عن نية بريطانيا الحَسَنة تجاه العرب!، وأنها ترغَبُ في استعادة مجدِهم، وتوحيدِهم وجمعِ كَلِ"},{"id":4868,"era":"c14","t":"وفاة علي دينار سلطان دارفور .","s":"هو السلطانُ علي دينار ابن السلطان زكريا بن محمد فضل الكيراوي. ولِدَ في قرية \"شوية\" بدارفور سنة 1856م، وهو آخر سلاطين الفور من السلالة الكيراوية في سلطنة دارفور بالسودان. أعلن توحيدَ جهود المسلمين ضِدَّ الغزو الصليبي الأوروبي في أفريقيا، ويعَدُّ السلطان علي دينار من أشهرِ السلاطين الذين حكَموا إقليم دارفور ووقفوا مع الثورة المهدية في دحر المستعمِر، كما قام السلطانُ بنشر الدعوة المهديَّة في عهد الخل"},{"id":4869,"era":"c14","t":"زيارة الملك عبد العزيز للبصرة .","s":"بعد اختتام مؤتمر الكويت أعمالَه زار الملك عبد العزيز البصرةَ بدعوة من برسي كوكس، وقد حَظِيَ الملك باستقبالٍ حافل من جانب سلطاتِ الاحتلال البريطاني في البصرةِ؛ إذ أقيم أمامَه استعراضٌ عسكري اشتركت فيه صنوفُ الأسلحة العسكرية، ثم قام بجولةٍ على متن القطارات والعربات، ثم اطَّلَع على المستشفيات الحديثة والقطاعات العسكرية، وسعى كوكس لعقد اجتماعٍ بين الملك عبد العزيز وفهد الهذال شيخ عنزة؛ بغرضِ منع الأخي"},{"id":4870,"era":"c14","t":"استيلاء الجيش الإنجليزي على مدينة غزة .","s":"استولى الجيشُ الإنجليزي على مدينة غزَّة الفلسطينية وانتزعها من العثمانيين، بعدما قاموا بمدِّ خَطِّ سكة حديد وخَطِّ أنابيب مياه في سيناء؛ للتغلب على صعوبة الطقس ووعورة التضاريس، وذلك بعد أن خَسِروا معركتين في غزةَ أمام العثمانيين."},{"id":4871,"era":"c14","t":"بعثة وفد إنكليزي للرياض برئاسة الكولونيل هاملتون  .","s":"أوفد برسي كوكس المعتمد البريطاني وفدا مكونا من الكولونيل هاملتون رئيسا للوفد وبرفقته جون فيلبي سكرتير كوكس والكولونيل أوين الوكيل السياسي في الكويت بغرض استنهاض الملك عبدالعزيز لحرب ابن رشيد في حائل والتوفيق بينه وبين الشريف حسين، وقد قضى هاملتون 21 يوما ثم غادر الرياض وترك فلبي يحل محله لإكمال التفاوض مع الملك عبدالعزيز، رفض الملك عبدالعزيز إعلان الحرب صراحة على تركيا لكنه طمأن الوفد عن استعداده "},{"id":4872,"era":"c14","t":"القوات البريطانية تحتل بغداد .","s":"ما كادت الحربُ العالمية تُعلَن حتى أنزلت الجيوش البريطانية قواتِها في المحمرة -مدينة عربية في خوزستان جنوب غرب إيران- بحجة حماية امتيازات البترول في إيران، ثم نزلت في البصرة ومشت بسرعة إلى القرنة، ثم العمارة، وحسبت أن الطريق إلى بغداد بات مفتوحًا، ولكِنَّ الهجوم المعاكس الألماني التركي هزم الإنجليزَ في البداية في الكوت بعد حصار ستة أشهر، فاستنجدوا بنجداتٍ أتت من الهند ليواصِلوا الزحف إلى بغداد ودخ"},{"id":4873,"era":"c14","t":"نشوء جمهورية شمال القوقاز الجبلية الفيدرالية .","s":"نشأت جمهوريةُ شمال القوقاز الجبلية الفيدرالية، وتتكوَّنُ مِن داغستان، والشيشان، وأنغوشيا، وأوسيتيا، وألانيا، وقبردينو، وأبخازيا، وبلقاريا، وأديغيا، وكانت عاصمتُها باطوم (جورجيا) واختير عبد المجيد تشيرموف أولَ رئيس لها، واعترف بهذه الدولة عددٌ من الدول الأوربية، والدولةُ العثمانية أيضًا."},{"id":4874,"era":"c14","t":"مؤتمر موسكو للتوفيق بين الإسلام والاشتراكية .","s":"اتحد الزُّعماءُ المسلمون الذين يؤيدون الاشتراكيين الثوريين والديمقراطيين الدستوريين، وشكَّلوا لجنة إسلامية نشأت عنها الجبهةُ الوطنية التتارية، ونظمت لجان العمال التي انضمَّ بعضُها إلى بعض تحت اسمِ اللجان الاشتراكية الإسلامية، فلم تلبث أن أصبحت تسيرُ في خطِّ البلاشفة، وأصدرت صحيفة \"قيزل بيرق\" (العلم الأحمر)، ورغم بُعدِها عن الشيوعية وكرههم للاشتراكيين ومبادئهم الإلحادية، إلا أنهم اتفقوا معهم على إن"},{"id":4875,"era":"c14","t":"استقلال ألبانيا ودخولها تحت الحماية الإيطالية .","s":"استقلت دولة ألبانيا وأصبحت تحت الحماية الإيطالية، وذلك إبَّان الحرب العالمية الأولى. وألبانيا هي إحدى دول البلقان التي كانت خاضعةً للحكم العثماني، وتحوَّلت من النظام الرئاسي بعد استقلالها إلى النظام الملكي عام 1928م تحت حكم \"أحمد زوغو\"، ثم حكَمَها الشيوعيون بقيادة \"أنور خوجا\" أربعين عامًا من الحكم المطلق حتى وفاته عام 1985م."},{"id":4876,"era":"c14","t":"وفاة السلطان حسين كامل سلطان مصر .","s":"هو السلطانُ حسين كامل سلطان ابن الخديوي إسماعيل، حَكَمَ مصر تحت الاحتلال البريطاني، ولِدَ في القاهرة، ولما بلغ الثامنة التحق بمدرسة قصر النيل التي أنشأها والده ليتعلَّم فيها، بخاصة أولاده وأولاد الأعيان. ولي حسين كامل سلسلةً من المناصب الإدارية. وأقام في طنطا فترةً بوصفه مفتشًا للدلتا، وأشرف على النهوض بقنوات الري في هذه المنطقة. وكذلك خدم مراتٍ عدةً في وزارات المعارف والأوقاف والأشغال العمومية، و"},{"id":4877,"era":"c14","t":"قيام الاتحاد السوفيتي .","s":"نشأ الاتحادُ السوفيتي بعد ثورة أكتوبر في العام 1917م بقيادة لينين الذي أزاح منافِسيه ووصل إلى الحُكمِ على يد البلاشفة اليساريين الاشتراكيين الذين تسَمَّوا باسم الحزب الشيوعي فيما بعد. ومن الأسباب الرئيسة في قيامِ الاتحاد السوفيتي: ضَعفُ النظام القيصري في روسيا، وتردِّي الأوضاع الاقتصادية، وبسبب دخول روسيا في الحرب العالمية الأولى ضد ألمانيا، وكانت قد نشطت في روسيا العديدُ من الأحزاب اليسارية المبش"},{"id":4878,"era":"c14","t":"أوضاع المسلمين في روسيا بعد الثورة البلشفية .","s":"قامت الثورة البلشفية في روسيا عام 1335هـ / 1917م، حيث تظاهر العمَّالُ نتيجة المفاسد وانهيار الأوضاع الاقتصادية وكثرة البطالة، فتشكَّلت حكومةٌ مؤقتة اشترك فيها الاشتراكيون والحزب الديمقراطي الدستوري، كان من نتيجتها تنازُلُ القيصر نقولا الثاني عن العرش لأخيه الأكبر ميخائيل، الذي سرعان ما تنازل هو أيضًا، وخوَّل الحكومةَ المؤقَّتة تسييرَ شؤون البلاد، ولم يجِدِ المسلمون لهم ناصرًا بين الروس، وقد حضروا "},{"id":4879,"era":"c14","t":"قيام المملكة اليوغسلافية  .","s":"بعد انتهاء الحرب العالمية الأولى وتقسيم الإمبراطورية، اتحدت عام 1918م كلٌّ مِن صربيا، كرواتيا، وسلوفينيا، تحت قيادة ملك الصرب بطرس الأول، وباسم مملكة صربيا وكرواتيا وسلوفينيا، وهي مملكة أوروبية امتدَّت من غرب البلقان حتى وسط أوروبا. اتبع خليفة بطرس الأول الملك الكسندر الأول حكمًا عسكريًّا منذ عام 1929م إلى حين اغتياله عام 1934م. أُعيد تسمية البلاد إلى مملكة يوغوسلافيا. ثم ناصَرَ الملكُ بطرس الثاني"},{"id":4880,"era":"c14","t":"وعد بلفور وخيانة بريطانيا للعرب .","s":"وعدُ بلفور أو تصريحُ بلفور، هو وعدٌ لليهود يمنَحُهم حقَّ إقامة وطني قومي في فلسطين، وهو وعدٌ مشؤوم بالنسبة للمسلمين يناقِضُ ما أبرمه الإنجليزُ مع الشريف حسين في مراسلات \"حسين، مكماهون\" والوعودَ بإقامة خلافةٍ عربية إسلامية في البلاد العربية مقابِلَ إعلان العرب الثورةَ على الدولة العثمانية!! ولقد أثار اشتراكُ الإمبراطورية العثمانية في الحربِ ضِدَّ الحلفاء الأطماعَ الصهيونية، وكان على رأس زعمائهم في "},{"id":4881,"era":"c14","t":"موقف الإنجليز من حركة إخوان نجد  (إخوان من أطاع الله) .","s":"تأسَّست حركة الإخوان -وكان مقرها الرئيسي الأرطاوية- على يد الملك عبدالعزيز لخوض المعارك ضد خصومه، وكانوا تستعِرُ داخِلَهم جذوةُ الدين وأصبحوا لا يُقهَرون، وكان شعارهم في الحرب: (هَبَّت هبوبُ الجنة، أين أنت يا باغيها؟ وكلٌّ يبغيها)؛ لذلك فكانوا يحاربون، وقلَّما ينهزمون، يرون أنَّ الجنَّةَ أمامهم والنارَ خلفهم، فلا يتقهقرون ولا يولون الدبر، فانتشر خبرهم وذاع صيتهم حتى بلغ الدوائر الإنجليزية والشريف "},{"id":4882,"era":"c14","t":"وفاة السلطان عبد الحميد الثاني آخر سلاطين الدولة العثمانية .","s":"هو السلطانُ عبد الحميد الثاني بن عبد المجيد الثاني، السلطان الرابع والثلاثون من سلاطين الدولة العثمانية، وآخِرُ من امتلك سلطةً فعليةً منهم. ولد في 16 شعبان 1258هـ الموافق 21 سبتمبر 1842م، وتولَّى الحكم عام 1293هـ 1876م. أبعِدَ عن العرش عام 1327هـ / 1909م بتهمة الرجعية، وأقام تحت الإقامة الجبرية حتى وفاته في 15 جمادى الأولى 1337هـ الموافق 10 فبراير 1918م. تلقى السلطان عبد الحميد بن عبد المجيد تعليم"},{"id":4883,"era":"c14","t":"مؤتمر سان ريمو أو سان جان دي موريين في إيطاليا  .","s":"عقد المجلسُ الأعلى للحلفاء اجتماعًا في سان ريمو في إيطاليا في نيسان 1920م وغايتُه وضع اتفاقية خاصة بتركيا غايتُها تصفية الخلافات الفرنسية الإيطالية؛ لهذا قرَّرت منح فرنسا منطقةَ أضنة على أن تضعَ إيطاليا يدَها على ما تبقَّى من أراضي جنوبي الأناضول، بما في ذلك أزمير، وولاية قونيا، ومتصرفيات أضاليا، وبقية أراضي الأناضول غربًا."},{"id":4884,"era":"c14","t":"وفاة السلطان العثماني محمد رشاد وتولي محمد السادس وحيد الدين .","s":"هو السلطانُ محمد الخامس رشاد بن عبد المجيد الأول بن محمود الثاني عبد الحميد الأول بن أحمد الثالث بن محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني. ولِدَ سنة 1844 باستانبول، وهو السلطان الخامس والثلاثون للدولة العثمانية، تولى الحكمَ بعد خلع أخيه عبد الحميد الثاني 1909م، وكان عمره 65 عامًا. أعيد تفعيلُ الدستور بعد تنصيبِه، وسيطر الاتحاديون"},{"id":4885,"era":"c14","t":"احتلال الجيش العثماني التاسع مدينة باكو في أذربيجان .","s":"احتلَّ الجيش العثماني التاسع، الذي يقوده نوري باشا، مدينةَ باكو في أذربيجان أثناء الحربِ العالمية الأولى، وأعلن نوري باشا أن تَدخُّل قواتِه حدث بطلبٍ مِن الحكومة الأذربيجانية، وتمكَّن الجيشُ من الوصول إلى حدودِ بحر الخزر -بحر قزوين-، لكِنَّ هذا الوضع لم يستمرَّ طويلًا؛ فقد اضطرت القواتُ العثمانية إلى الانسحاب بموجِبِ معاهدةِ موندروس."},{"id":4886,"era":"c14","t":"سيطرة القوات الفرنسية والإنجليزية على الشام .","s":"استطاعت كلٌّ من القوات الفرنسية والإنجليزية التمكُّنَ مِن السيطرة على بلاد الشام مِن الدولة العثمانية بما يتَّفِقُ مع اتفاقية سايكس بيكو، وقامتا بتحريضِ الأمير فيصل بن الحسين على ارتكابِ مذبحةٍ ضِدَّ الجنود العثمانيين المنسحِبين نحو الشمال."},{"id":4887,"era":"c14","t":"مؤتمر الرياض الأول .","s":"مع ما تمتَّع به الإخوانُ (إخوان من أطاع الله) من بسالةٍ وبطشٍ بالأعداء ورغبةٍ في الجهادِ، لكن بدا منهم جفاءٌ وغلظة مع من يخالِفُهم في طريقتِهم من الحضَرِ عُمومًا، والبدو خصوصًا، ممَّن لم يلحَقْ بهم في الهِجَر، وصاروا يتهمونَهم بالضلالِ، وربما رموهم بالكُفرِ، فانتشر من جرَّاءِ هذا الأمر الفوضى في البلادِ، وكاد ينقَطِعُ حبل الأمن والسلام، فعقد السلطان عبد العزيز ابن سعود مؤتمرًا في الرياض في هذا الع"},{"id":4888,"era":"c14","t":"استقلال اليمن عن الدولة العثمانية .","s":"أخذت اليمنُ استقلالها عن الدولة العثمانية مبكرًا، وذلك منذ قيام الإمام محمد بن يحيى سنة 1307هـ ثم ابنِه يحيى؛ حيث حاربوا الجيوشَ العثمانية وأخرجوها من اليمن بعد حروبٍ مريرة حتى سمِّيَت البلاد مقبرة الأناضول، ولَمَّا ضاق العثمانيون ذَرعًا من الحرب في اليمن عَقَدوا صُلحًا مع الإمام يحيى سنة 1329هـ نال فيه اليمنُ الاستقلال الذاتي، ثم لما خسر العثمانيون في الحرب العالمية الأولى سنة 1336هـ جلت بقايا ال"},{"id":4889,"era":"c14","t":"هدنة مدروز واستسلام الدولة العثمانية في الحرب العالمية الأولى .","s":"تدهورت الأوضاعُ العسكرية للدولة العثمانية أثناءَ الحرب العالمية الأولى، وسيطر البريطانيون على العراقِ والشام، واحتلَّ الفرنسيون شماليَّ بلاد الشام، وسيطر الحلفاءُ على استانبول والمضايق التركية، ولَمَّا رأى قادة الاتحاد والترقي هذه الهزائم قدَّم طلعت باشا رئيس الوزراء استقالةَ وزارته، فتألفت وزارة جديدة برئاسة أحمد عزت باشا، وهرب كلٌّ من طلعت باشا وأنور باشا وغيرهما إلى ألمانيا. وأرسلت الحكومة الجد"},{"id":4890,"era":"c14","t":"انتصار مصطفى كمال أتاتورك وإلغاء الخلافة الإسلامية وعلمنة تركيا .","s":"بعد هزيمة الدولة العثمانية في الحربِ العالمية الأولى، وإعلان هُدنةِ مودروس؛ وصل الجنرال اللنبي قائِدُ الإنجليز استانبولَ وطلب من الحكومةِ التركية تعيينَ مصطفى كمال قائدًا للجيش السادس بالقُربِ مِن الموصل حيث تهمُّ هذه المنطقة إنجلترا، وأثناء انسحاب مصطفى كمال من حلبٍ اقترح تشكيلَ وزارة جديدة برئاسةِ عزة باشا الأرناؤوط؛ لتخلُف وزارة الاتحاديين برئاسة طلعت باشا، وعلى أن يتولى هو في هذه الوَزارةِ الج"},{"id":4891,"era":"c14","t":"تأسيس حزب الوفد المصري المطالب بالاستقلال .","s":"انتهت الحربُ العالمية الأولى وخرجت إنجلترا ومن معها منتَشِين بالنصر، وكانت تُمنِّي المصريين بمنحِهم الاستقلالَ فورَ انتصارهم في الحرب، ولما كان الاحتلالُ مكَلِّفًا أكثر من إبقاء الدولة تابعةً لها بوضع أناسٍ يُخضِعون إدارتها، فتحصُلُ على ما تريد دون خسائرَ بشرية ولا خسائِرَ اقتصادية، فأظهرت اللِّينَ وأبدت الاستعدادَ لفكرة الاستقلالِ، وهيَّأت أشخاصًا مناسبين لها لهذا العمل الجديد، فأوحت لسعد زغلول ب"},{"id":4892,"era":"c14","t":"المظاهرة النسائية وخلع الحجاب في مصر .","s":"قامت مجموعةٌ من النساء المصريات بمظاهرةٍ نسائية في ميدان الإسماعيلية منَدِّدةً بالاحتلال الإنجليزي، كان على رأسهن صفية زغلول، وهدى شعراوي؛ حيث إن زوجيهما كانا أبرزَ قادة الوفد المقتَرَح لمفاوضة الحلفاء لتقريرِ مصير مصر بعد الحرب العالمية الأولى، وتجمَّع النسوة أمام ثكنات الجيش الإنجليزي، وهتَفْنَ ضِدَّ الاحتلال. ثم بتدبيرٍ سابقٍ ودون مقدماتٍ ظاهرةٍ خَلَعْنَ الحجابَ، وألقين به في الأرضِ، وسكَبْنَ ع"},{"id":4893,"era":"c14","t":"اغتيال أمير الأفغان حبيب الله خان وتولي ابنه أمان الله خان .","s":"هو حبيب الله خان عبد الرحمن خان بن محمد أفضل خان بن دوست محمد خان، ولِدَ سنة 1872م، تولى إمارة أفغانستان عام 1901م، وفي عهدِه اعترفت كلٌّ من إنجلترا وروسيا باستقلال بلاد الأفغان، عندما احتلت إيطاليا ليبيا دعا حبيب الله شعبَه لدعم جهاد الليبيين ضِدَّ الاحتلال الإيطالي، وافتتح التبرعاتِ بعشرين ألف روبية، ولَمَّا اندلعت الحرب العالمية الأولى التزم الحيادَ في أفغانستان في الحرب العالمية الأولى، على ال"},{"id":4894,"era":"c14","t":"ثورة المصريين ضد الاحتلال البريطاني .","s":"بعد انتهاء الحرب العالمية الأولى توقَّعت إنجلترا بدءَ مستعمراتها في طلب الاستقلال، فأخذت تظهِرُ اللينَ، وأبدت استعدادَها للموافقة، وأوحت إلى سعد زغلول ورفاقه بالتحرك، فبدأ في عقد اجتماعات ولقاءات أسفرت عن طلب الاستقلالِ، وتم تشكيلُ وفد للسفر إلى الخارج لعرض القضية على العالم، وتشكَّل هذا الوفد من سعد زغلول، وعلي شعراوي، وعبد العزيز فهمي، وطلبوا مقابلةَ المندوب السامي البريطاني «وينجت» وطلبوا منه ا"},{"id":4895,"era":"c14","t":"اندلاع الحرب الأفغانية البريطانية الثالثة واستقلال أفغانستان .","s":"اندلعت الحربُ الثالثة بين بريطانيا وأفغانستان في هذا العام، بينما كانت الحربُ الأولى عام 1254ه حيث هُزمت فيها بريطانيا هزيمةً نكراء، والحرب الثانية في عام 1295ه التي انتصرت فيها بريطانيا ورضيت من نتائج نصرِها بالسيطرة على المناطق الحدودية لبلاد الأفغان، وبقية السيادة كاملة للأفغان داخِلَ بلادهم. أما الحربُ الثالثة هذه، فكان سببُها هو عدم اعتراف الحكومة الهندية البريطانية (الراج البريطاني) باستقلال"},{"id":4896,"era":"c14","t":"معركة تربة وهزيمة الإخوان (إخوان من أطاع الله) لجيش الشريف حسين .","s":"عندما استردَّ الأمير عبد الله بن الشريف حسين واحةَ تربة (جنوب غربي نجد) التي خضعت مؤخرًا لسلطان الملك عبدالعزيز، فهجم جيشُ الإخوان بقيادة سلطان بن بجاد ومعه قبائل سبيع وعتيبة وخالد بن لؤي أمير الخرمة (من محافظات منطقة مكة المكرمة) على جيش الأمير عبد الله بن الحسين، بعد منتصف الليل من مختلف الجهات، الأمرُ الذي أصاب الأمير عبد الله بالارتباك، فلم يستطع أن يفعل شيئًا، فمزَّق الإخوان جيشَه على الرغم م"},{"id":4897,"era":"c14","t":"تأسيس الحزب الحر الدستوري في تونس .","s":"أسَّس الحزبَ الحُرَّ الدستوريَّ في تونس أنصارُ عبد العزيز الثعالبي أثناء اعتقال الفرنسيين له، وقد ساهم في نشأةِ الحزب جملةٌ من العوامل الداخلية والخارجية أدت إلى ظهوره، كان من بينها على مستوى عالميٍّ الإعلانُ عن مبادئ الرئيس الأمريكي وِلْسن، الداعية إلى تحرير الشعوب، وحَقِّها في تحرير مصيرها، بالإضافة إلى تنامي حركات التحرُّر في العالم، فلما أُطلِقَ سراح الثعالبي تولى رئاسةَ الحزب، وقد آزر الحزبَ "},{"id":4898,"era":"c14","t":"إعلان مصطفى كمال أتاتورك استقلاله عن الخليفة العثماني .","s":"أبلغت لجنةُ الحلفاء العليا المقيمة في باريس الحكومةَ العثمانيةَ قرارًا يقضي بنزول الجيوشِ اليونانية في أزمير ويحذِّرونها من المقاومة، فأبلغت الحكومةُ التركية والي أزمير الالتزامَ بالهدوء وعدمِ المقاومة؛ لأن الحلفاءَ سيحتلون أزمير، ثم ظهر الأسطولُ الإنجليزي في مياه المدينة في 14 أيار، وأبلغ القائدُ الإنجليزي كالثورب واليَ أزمير بأنَّ الاحتلال سيكون من قِبَل اليونان وليس من قِبَل الحُلَفاء، فصُعِقَ "},{"id":4899,"era":"c14","t":"حركة محمود المعروف الكردي ضد الاحتلال الإنجليزي .","s":"كان محمود المعروف أحدَ زعماء الأكراد الذين برَزوا في السليمانية، وكانت له شعبيةٌ واسعة، وعندما انسحب العثمانيون من العراق لصالح الإنجليز أراد القائدُ العثماني أن يستفيدَ من محمود ونفوذه، فأمَدَّه بالمال وترك له فوجًا يتصرَّفُ بإمرته، والإنجليز لم يكونوا وصلوا للسليمانية، ولما رأى محمود أن القوةَ أصبحت للإنجليز لا للعثمانيين أراد الاتصالَ بهم، فكتب إلى وِلْسن القائد الإنجليزي في كركوك، وطلب منه أن "},{"id":4900,"era":"c14","t":"إقالة الحكومة العثمانية مصطفى كمال كمفتش عام الجيوش .","s":"كان السلطانُ وحيد الدين يدرِكُ أنَّ ما فقدته الدولة العثمانية لا يمكِنُ أن يعود إلا بالقتال، فكلَّف سرًّا مصطفى كمال بمهمة إثارة القلاقل في الأناضول، وعيَّنه مفتشًا عامًّا لجيوش الأناضول ليعمِّيَ على الحلفاء -وخاصة الإنجليز- الدور الذي سيلعبه مصطفى كمال في إثارة الفوضى فيها، لكِنَّ مصطفى كمال لم يذهب للأناضول، وإنما اتَّجه إلى أزمير بتدبير مع الإنجليز ودخَلَها مع دخول القوات اليونانية، واستغل الفو"},{"id":4901,"era":"c14","t":"اتفاقية المساعدة البريطانية من أجل تقدم فارس ورفاهيتها .","s":"كانت فارس مقسَّمةً إلى ثلاثة أقسام: قسم تحت النفوذ الروسي، وقسم تحت النفوذ البريطاني، وقسم محايد، ولما انتهى النفوذ الروسي في فارس بعد قيام الثورة الشيوعية، وتسلمها مقاليد الحكم في محرم 1336هـ / تشرين الأول 1917م وتنازلوا عن ديونهم على فارس، وأرادت إنجلترا أن تحُلَّ محلَّ روسيا فلم تتمكَّنْ، ولكنها رأت أن تجعل على الأقل سدًّا في وجه التوسع الشيوعي، فأسرعت في توقيع اتفاقية مع فارس بعد مباحثات لمدة "},{"id":4902,"era":"c14","t":"مؤتمر الشرق الأوسط لمناقشة توسع الملك عبدالعزيز في الحجاز .","s":"أثار انتصار قوات الإخوان (إخوان من أطاع الله) في تربة وتفوقهم العسكري مخاوف الإنجليز من توسع الملك عبدالعزيز تجاه الحجاز على حساب حليفهم الشريف حسين لذلك حاولت بريطانيا تخفيف حدة الصراع والتوتر بين الحجاز ونجد والحيلولة دون تقدم آل سعود إلى الحجاز بأن طلبت منه أن يسحب قواته من الحجاز، ثم دعا اللورد كيرزون وزير الخارجية البريطانية لعقد مؤتمر في مبنى وزارة الخارجية في لندن دعا إليه مسؤولون بريطانيون"},{"id":4903,"era":"c14","t":"عقد اتفاق بين فرنسا وإيطاليا حول بعض الواحات التونسية .","s":"تمَّ عقدُ اتفاق بين فرنسا وإيطاليا، تمَّ بمقتضاه النزولُ لإيطاليا عن عددٍ من الواحات الهامة في الجنوب الشرقي لتونس، وأصبح وضعُ الإيطاليين معادِلًا لوضع الفرنسيين في تونس."},{"id":4904,"era":"c14","t":"قيام مصطفى كمال بعقد مؤتمر سيواس .","s":"عقد مصطفى كمال مؤتمر سيواس، وقد تشكَّلت فيه هيئةٌ تمثيلية، وطالب الدوائرَ العسكرية والمدنية بالارتباط بها، وقَطْعِ علاقتهم باستانبول، ثم انتقل مقرُّ هذه الهيئة إلى أنقرة."},{"id":4905,"era":"c14","t":"تشكيل حكومة الاحتلال البريطاني لجنة ملنر .","s":"قامت حكومةُ الاحتلال البريطاني بتشكيل لجنة عُرِفَت باسم \"لجنة ملنر\"؛ وذلك من أجل التحقيق في أسباب اشتعال الثورة المصرية المعروفة بثورة 1919م، على الرغم من أن الإنجليز هم من خطَّط لقيام ثورة احتجاجٍ على اعتقال أعضاء الوفد المزمَع سفرُهم للتفاوض في باريس؛ وذلك لمزيد من صناعة أعضاء الوفدِ سعد زغلول ورفاقه كزعماء وطنيين بدلًا من الزعامة الوطنية الموجودة في البلاد، كمصطفى كامل، فقدَّمت لجنة ملنر مقترحا"},{"id":4906,"era":"c14","t":"زيارة الأمير فيصل بن عبدالعزيز الأولى لأوروبا .","s":"دفعت أحداث تربة والخرمة (من محافظات منطقة مكة المكرمة) والصراع الحجازي النجدي الحكومة البريطانية إلى الطلب من الملك عبدالعزيز إرسال وفد إلى لندن فكلف ابنه فيصل البالغ من العمر 14 سنة للقيام بهذه الزيارة نيابة عنه وأرسل معه وفدا ضم مستشاره للشؤون الخارجية أحمد بن ثنيان ولحق بهم فيلبي سكرتير برسي كوكس المعتمد البريطاني في الخليج ليكون وسيطا بين حكومته والوفد، وقد حضر فيصل والوفد المرافق له احتفالات "},{"id":4907,"era":"c14","t":"معاهدة سيفر  .","s":"بعد أن سيطر الحلفاء على استانبول وألقِيَ القبضُ على رئيس الوزراء، وحُلَّت جمعيةُ الاتحاد والترقي، واغتيلَ أكثَرُ أعضائها، وأُقيل مصطفى كمال من منصبِه، وأعلنت الحكومة تمرُّدَ مصطفى كمال الذي ظهر بمظهرِ البطل الثائر حتى لقَّب نفسه بالغازي، فتقدَّم إلى الغرب من الأناضول، وحاصر أسكي شهر فانسحب الإنجليزُ منها دون مقاومة، فدخلها بصورة الفاتح ودخل قونية، وأعلن إجراءَ انتخابات جديدة بحيث تكون أنقرة مقرًّا"},{"id":4908,"era":"c14","t":"مؤتمر مدينة غريان لتوحيد الجهاد الليبي ضد الطليان .","s":"عندما بدأ الاحتلالُ الإيطالي لليبيا وتخلَّت عنهم الدولة العثمانية، بقي المجاهدون وحدهم في ميدان القتال، فالتقَوا في عدة معارك مع الطليان، وكان الليبيون قد دحروا القواتِ الإيطاليةَ حتى حاولوا الهجومَ على الإنجليز بمصرَ، لكنهم فشلوا، وتنازل أحمد شريف عن زعامة الحركة السنوسية لابن عمه محمد إدريس، الذي هزم الطليان في عدة معارك، واضطروا إلى إبرام اتفاقيةٍ معه اعترفوا له فيها بنفوذه على المناطق، وتعهَّد"},{"id":4909,"era":"c14","t":"ضم الملك عبدالعزيز مدينة عسير لحكمه .","s":"عندما اندلعت الحرب العظمى انسحب الأتراك من عسيرٍ، أصبح الأمير حسن آل عائض حاكمًا لعسير، لكِنَّ قبائل قحطان وزهران نفرت منه بسبب استبداده، فأرسلوا إلى الملك عبدالعزيز يستعينون به عليه، فأرسل لهم علماء يعلِّمون الناس العلم وينشرون التوحيد، لكنَّ ابن عائض لم يحسِنْ استقبالهم واستمَرَّ في سياسته، فأرسل الملك عبدالعزيز حملةً بقيادة ابن عمه عبد العزيز بن مساعد بن جلوي أمير حائل ومعه قحطان وزهران، فهزموا"},{"id":4910,"era":"c14","t":"دخول فرنسا موريتانيا .","s":"كانت موريتانيا محلَّ أطماع الأوروبيين منذ القرن الخامس عشر الميلادي؛ حيث وصلها البرتغال والهولنديون، وأقاموا مراكز تجارية علي سواحلها بغيةَ الحصول علي الصمغ العربي الذي اشتهرت موريتانيا بإنتاجه، وفي القرن (17م) دخل الفرنسيون والإسبان والإنجليز هذا الصراع، فكانت معاركُ وصدامات بين الأوروبيين من أجل السيطرة علي تجارة الصمغ العربي، وقد أطلق على تلك الحروب اسم حروب الصمغ العربي، التي انتهت بسيطرة الفر"},{"id":4911,"era":"c14","t":"ثورة إبراهيم هنانو ضد الاحتلال الفرنسي في سوريا .","s":"في عام 1919م اتَّفق عددٌ من الوطنيين السوريين على اختيار إبراهيم هنانو لتأليف قواتٍ من المجاهدين، تمكَّنَت من احتلال مدينة أنطاكية، وكان أولُ صدام مسلح بين قوات هنانو والفرنسيين في أكتوبر، ثم قامت بعضُ القوات التابعة لهنانو بالهجومِ على الفرنسين والانتصار عليه، فذاع صيتُه وكثُر مؤيدوه، وبعد توقيع الأمير فيصل بن الحسين على معاهدة الانتداب عام 1920م أصبح وضعُ هنانو صعبًا؛ لحاجته للسلاح، فحصل عليه من"},{"id":4912,"era":"c14","t":"اعتراف بلجيكا بالإسلام كدين رسمي .","s":"اعترفت دولة بلجيكا بالإسلام كدينٍ رسمي، وفي عام 1998م بعد ربع قرن على هذا الاعتراف حقَّق المسلمون نجاحًا آخر عندما خاضوا انتخاباتٍ على مستوى الأقلية لاختيار هيئة موحَّدة تمثِّلُهم لدى الحكومة، وتكون بمثابة المُحاوِرِ الرسمي للسلطات البلجيكية في شؤون المسلمين."},{"id":4913,"era":"c14","t":"قيام منظمة عصبة الأمم رسميًّا .","s":"عُصبةُ الأمم منظَّمةٌ دولية تمَّ تأسيسُها بعد الحرب العظمى (العالمية الأولى) والهدف من إنشائها -كما يزعمون- هو التقليل من عملية التسلح العالميَّة، وفكُّ النزاعات قبل أن تتطور لتصبِحَ نزاعًا مسلَّحًا، كما حدث في الحرب العالمية الأولى. وأثبتت المؤسَّسةُ فشلها في مواجهة القوى الفاشية في العالم، وفشَلَها في منع وقوع الحرب العالمية الثانية؛ مما تطلَّب أن يُستبدَلَ بها هيئةُ الأمم المتحدة بعد الحرب العا"},{"id":4914,"era":"c14","t":"وفاة الأمير سعود بن عبد العزيز بن متعب الرشيد أمير حائل .","s":"هو الأمير سعود بن عبد العزيز بن متعب بن عبد الله بن علي بن رشيد من فخذ آل جعفر من عبده من قبيلة شمر، عاشر حكام إمارة جبل شمر في حائل، خلال الفترة من 1908 إلى 1920م. ولِدَ بحائل عام 1898م تولى سعود حكم حائل وعمُرُه 11 سنة تحت وصاية خاله الأمير حمود بن سبهان السبهان الذي مارس دور الحاكم الفعلي للإمارة إلى أن تولَّى الأمير سعود آل عبد العزيز الحكم رسميًّا في حائل 1914م وفي عام 1915 خاض معركة جراب ضِد"},{"id":4915,"era":"c14","t":"دخول قوات التحالف عاصمة الخلافة العثمانية بعد الحرب العالمية الأولى .","s":"احتَلَّ الحلفاءُ استانبول بالكامل، وكانت القواتُ الإنجليزية فقط هي التي احتلَّتْها، وأظهر الإنجليزُ عداءً ظاهريًّا لمصطفى كمال حتى يصنعوا منه بطلًا؛ فبعد سقوط الحكومة التي شُكِّلَت في ظل الاحتلال جرت انتخاباتٌ ونجح مصطفى (أتاتورك) عن أنقرة، فجمع النواب فيها، وشكَّل حكومةً برئاسته، وأظهر التدينَ والتمسُّكَ بالإسلام!!"},{"id":4916,"era":"c14","t":"قيام ثورة العشرين في فلسطين .","s":"اندلعت ثورة 1920 في فلسطين احتجاجًا على وعد بلفور، وبدأت أحداثها في القدس، ثم امتدت إلى مختلف المدن الفلسطينية؛ فقد سارت جموعٌ حاشدة في مظاهرات صاخبة طافت شوارعَ القدس، وهي رافعة صورة فيصل بن الحسين بصفته ملكًا لسوريا وفلسطين. وحينما وصلت المظاهرة باب يافا في القدس وقع انفجارٌ قوي تبعه قذفُ الحوانيت اليهودية بالحجارة، واشتبك المتظاهرون مع اليهود، ثم مع الإنجليز الذين هُرعوا لحمايتهم. وكانت تلك الأ"},{"id":4917,"era":"c14","t":"ضعف دعم الإنجليز للشريف حسين وأثره على استقرار الأوضاع في الحجاز .","s":"تغيَّرت سياسةُ الحكومة البريطانية في حَجمِ دَعمِها للشريف حسين بعد نهاية الحرب العظمى، فأصبح الدعمُ مرهونًا بالمحافظة على ميزان القوى داخل الجزيرة العربية، والتي يمثِّلُ الشريف حسين أحد أطرافها في الحجاز، مع أطراف أخرى منهم الملك عبدالعزيز في نجد، وابن رشيد في حائل، وغيرهم. ففي هذا العام حدثت أزمةٌ مالية للشريف حسين عندما قلَّصت بريطانيا دعْمَها الماديَّ الذي كان قد بلغ وقت الحرب ما يزيد على 200 أ"},{"id":4918,"era":"c14","t":"انعقاد المؤتمر السوري .","s":"انعقد المؤتمر السوري واتخذ عدةَ قراراتٍ تاريخية تنصُّ على إعلان استقلال سوريا بحدودها الطبيعية استقلالًا تامًّا بما فيها فلسطين، ورفْض ادِّعاء الصهاينة في إنشاء وطن قومي لليهود في فلسطين، وإنشاء حكومةٍ مسؤولة أمام المؤتمر السوري الذي هو مجلس نيابي، وكان يضم ممثِّلين انتخبهم الشعب في سوريا ولبنان وفلسطين. وتنصيب الأمير فيصل حسين ملكًا على سوريا الكبرى، فاستقبلت الجماهيرُ المحتشدة في ساحة الشهداء هذ"},{"id":4919,"era":"c14","t":"إعلان بريطانيا الانتداب على العراق وتهنيد العراق .","s":"بعد اندلاع الحرب العالمية الأولى عام 1914 ودخول الدولة العثمانية في تحالفٍ إلى جانب ألمانيا ضِدَّ دول الحلفاء بزعامة بريطانيا وفرنسا وروسيا القيصرية، أدى ذلك إلى قطع خطوط المواصلات الاستراتيجية لبريطانيا مع مستعمراتها؛ مما أدى بالتالي إلى انقطاع شريانِ الإمدادات الحيوي للحرب والحياة العامة البريطانية. فقامت بريطانيا باعتمادِ خطةٍ سريعة، كان من بين أهدافها احتلالُ العراق، في الوقت الذي كان الجهدُ ا"},{"id":4920,"era":"c14","t":"انعقاد مؤتمر سان ريمو بعد انتهاء الحرب العالمية الأولى .","s":"نتيجةً لموقف إنجلترا وفرنسا من مقرَّرات المؤتمر السوري الذي انعقد في مارس تمَّ عقدُ مؤتمر سان ريمو الذي حُدِّدت فيه مناطق النفوذ البريطانية والفرنسية في المشرق العربي، فانعقد المجلس الأعلى للحلفاء، الذي يعتبَرُ امتدادًا لمؤتمر لندن المنعقد في (فبراير) 1920 في مدينة سان ريمو الإيطالية، في المدة ما بين التاسع عشر والخامس والعشرين من نيسان (أبريل) 1920؛ للبحث في شروط الحلفاء للصلحِ مع تركيا طبقًا لمع"},{"id":4921,"era":"c14","t":"صدور قرار بإنشاء المجمع العلمي العربي بدمشق .","s":"صدر قرارٌ بإنشاء المجمَع العِلميِّ العربي بدمشق، والذي عُرِفَ فيما بعد بـ \"مجمع اللغة العربية\". وقد نهض المجمَعُ بأمور اللغة في سوريا، وأحياها في دواوين الحكومة، وقام بجَمعِ الكتب والمخطوطات، وقد ضَمَّ المجمَعُ بين صفوفه عددًا من أعيان اللغة في العالم العربي. كانت الدولُ الاستعمارية منذ الوهلة التي يضعُ المستعمِرُ قدمَه في أي بلدٍ يستعمِرُه يبدأ بالتنقيب عن آثار البلد لربطِ سكانه بتاريخهم القومي ب"},{"id":4922,"era":"c14","t":"ثورة العشرين في العراق ضد الاحتلال البريطاني .","s":"انتهت الحربُ العالمية الأولى ووُضِعَت العراق تحت الانتداب البريطاني، فأظهر الإنجليزُ الفساد من مجاهرة لشرب الخمور، وممارسة الزنا والاختلاط والسير في الطرقات بدون حشمة، بالإضافة لنظرة الاستعلاء بزعمهم أنَّهم جاؤوا ليرفعوا مستوى السكَّان والأخذ بأيديهم نحو الاستقلالِ، ولكن العراقيين (غير اليهود والنصارى الذين صاروا يصِرُّون على أن يبقوا تحت رعاية بريطانيا) كانوا ينظرون إلى الإنجليز نظرةَ ازدراء وكرا"},{"id":4923,"era":"c14","t":"توقيع الدولة العثمانية معاهدة سيفر مع الحلفاء .","s":"وقَّعت الدولةُ العثمانية معاهدةَ سيفر مع الحلفاء بعد هزيمتها في الحربِ العالمية الأولى واحتلالِ معظَمِ أراضيها، في مدينة سيفر الفرنسية، وكانت هذه المعاهدةُ بمثابة المسمار الأخير في نعش الدولة العثمانية وتفكُّكِها ثم انهيارها؛ بسبب شروطها القاسية والمُجحِفة، والتي كانت بدافع النِّقمةِ مِن هزيمة الحُلَفاء في معركة غاليبولي، وضخامة الخسائر التي تكبَّدها الحلفاء على يد القوات العثمانية؛ فقد نصَّت المع"},{"id":4924,"era":"c14","t":"مفاوضات بين ملنر والوفد المصري بزعامة سعد زغلول .","s":"تقدَّم اللورد ملنر وزير المستعمرات الألماني إلى الوفدِ المصري بنصِّ مشروع معاهدة تتكوَّن من عدة مواد، ومنها: (المادة الأولى) تتعهد بريطانيا بضمان سلامة أرضِ مِصرَ واستقلالها كمملكةٍ ذات أنظمة دستورية. (المادة الثانية) تتعهَّدُ مصر من جانبها ألَّا تَعقِدَ أيَّ معاهدة سياسية مع أي دولة أخرى بدون رضا بريطانيا. (المادة الثالثة) نظرًا للمسؤولية الملقاة على عاتق بريطانيا بمقتضى الفقرة المتقدمة، ونظرًا ل"},{"id":4925,"era":"c14","t":"تعيين الحكومة البريطانية هربرت صموئيل الصهيوني مندوبًا ساميًا في فلسطين .","s":"قامت الحكومةُ البريطانية بتعيين هربرت صموئيل الصهيوني مندوبًا ساميًا لحكومة الانتداب البريطاني في فلسطين، وقد وضع الانتداب موضِعَ التنفيذ رسميًّا في 29 سبتمبر 1923م بعد أن وقَّعت تركيا على معاهدة لوزان."},{"id":4926,"era":"c14","t":"إعلان المؤتمر الوطني في تركيا \"الميثاق الوطني\" .","s":"أعلن المؤتمرُ الوطني في تركيا بعد الهزيمة في الحرب العالمية الأولى\"الميثاق الوطني\" الذي تضمَّن عِدَّةَ مبادئ تشمل: حقَّ تقرير المصير. تأمينَ القسطنطينية، فتحَ المضايق، حقوقَ الأقليَّات. إلغاءَ الامتيازات الأجنبية. وقد يلاحَظُ أنَّه يحتوي على الحد الأدنى من شروط السلام التي وافقت عليها تركيا في معاهدة السلام التي ستنتهي بها الحربُ العالمية الأولى. ومن بين القراراتِ التي خرجت من الاجتماع وخاصة اعتما"},{"id":4927,"era":"c14","t":"معاهدة الصداقة \"الأفغانية- السوفيتية الأولى\" .","s":"تم توقيعُ معاهدة الصداقة \"الأفغانية - السوفيتية الأولى\" وهي أول معاهدة تعقِدُها أفغانستان بعد إعلان استقلالها في عام 1919؛ حيث نصَّت المعاهدة على إعادة منطقة \"بنجده\" -وهي التي كان الروس قد استولوا عليها في عام 1885م- والاعتراف باستقلال الولايات الإسلامية (بخارى وكييف) وعدم الاعتداء بين الطرفين 25 سنة، الأمر الذي لم يفعَلْه الاتحاد السوفيتي حتى سقوطِه في عام 1991. وقد عقَدَ هذه المعاهدةَ الملكُ أما"},{"id":4928,"era":"c14","t":"نشأة المجلس الإسلامي الأعلى الفلسطيني  .","s":"تأسَّس مجلس إسلامي فلسطيني عام 1922 لإدارة المحاكم الشرعية والأوقاف والشؤون الإسلامية، وقد تألَّف المجلس من مجموعة العلماء الذين رشَّحوا الحاج أمين الحسيني مفتي القدس رئيسًا لهذا المجلس الذي سُمِّي (المجلس الإسلامي الأعلى) الذي أصبح على مرِّ الأيام أقوى قوة وطنية فلسطينية إسلامية في البلاد، وقام بعددٍ من الأعمال والإنجازات الهامة؛ منها: إنشاء دار الأيتام الإسلامية الصناعية في القدس، وفَتْح عشرات ا"},{"id":4929,"era":"c14","t":"تأسيس الجيش العراقي أثناء الانتداب البريطاني على العراق .","s":"تمَّ تأسيسُ الجيش العراقي تحت الانتدابِ البريطاني في العراق، وتكوَّن هذا الجيشُ من 1500 جندي، وكان الفريقُ جعفر العسكري أوَّلَ مَن تولى وزارة الدفاع العراقية، واستمرَّ هذا الجيشُ قائمًا حتى ألغاه الاحتلالُ الأمريكي في مايو 2003م."},{"id":4930,"era":"c14","t":"اتفاق الرجمة واعتراف الإيطاليين بحكم السنوسي في ليبيا .","s":"استمرَّت حركة المقاومة في ليبيا حتى نشوب الحرب العالمية الأولى سنة (1332هـ / 1914م)، ودخلت إيطاليا الحربَ إلى جانب الحلفاء، بينما كانت تركيا حليفًا لألمانيا، ومن ثمَّ فقد جاهرت تركيا بمساندتها وتأييدها للِّيبيين بقيادة أحمد السنوسي، ومناصرتهم في حربهم ضِدَّ عدوهم المشترك. ولكنْ ما لبثت العلاقاتُ أن تعقَّدت بين السنوسي والأتراك الذين نجحوا في الوقيعة بينه وبين الإنجليز فأغلقوا بدورهم طريق مصر في وج"},{"id":4931,"era":"c14","t":"معركة الجهراء بين نجد والكويت  .","s":"حدثت أزمة حدودية بين نجد والكويت حول واحة البلبول جنوب الكويت والتي تبعد عن ميناء الجبيل عشرين ميلا عند ما بنى فيها سالم الصباح حاكم الكويت حصنا فاحتج الملك عبدالعزيز وكتب لابن الصباح يؤكد فيها أن البلبول ضمن أراضيه ويطلب منه وقف التوسع في بناء الحصون لكن ابن صباح رفض هذا التحذير فبنى الملك عبدالعزيز قرية بالقرب من البلبول وعلى الرغم من حدوث سلسلة من المراسلات والاتصالات التي توسطت بها بريطانيا بي"},{"id":4932,"era":"c14","t":"المعارك بين الأتراك واليونان .","s":"كانت لجنةُ الحلفاء العليا المجتَمِعة في باريس والمؤلَّفة من رؤساء وزارات كلٍّ من إنجلترا وفرنسا وإيطاليا واليونان والحكومة التركية أصدرت قرارًا يقضي بنزول الجيوشِ اليونانية في أزمير، وحذَّر القرارُ الدولةَ العثمانية من المقاومة، وأن أيَّ مقاومة تعني نقضَ الهدنة وعودة الحرب، وقد نزل اليونانيون فعلًا في اليوم الثاني من مطلع صيف 1338هـ، ثم دفعت إنجلترا باليونانيين فتقدَّموا من ناحية الغرب، وجرى القتا"},{"id":4933,"era":"c14","t":"محاولة الملك عبدالعزيز ضم حائل .","s":"بعد مقتَلِ سعود بن عبد العزيز أمير حائل غزا الملك عبدالعزيز حائل، واستطاع أن يهزم شمر، ووصل إلى أسوارها، وقرر أميرُها الجديد عبد الله بن متعب أن يحتميَ بأسوار حائل المنيعة، ولما بدأت المؤَنُ تنفَدُ أرسل إلى الملك عبدالعزيز يعرِضُ عليه التفاوضَ، على أن تبقى إمارة جبل شمر على حائل، ولكنَّ الملك عبدالعزيز طلب منه الاستسلامَ بالكامِلِ، واستمرت المعركة عدة أشهر دون أن يتمكَّنَ من فتحِ حائل على الرغم من"},{"id":4934,"era":"c14","t":"إفراج السلطات الفرنسية عن الزعيم التونسي عبد العزيز الثعالبي .","s":"أفرجت السلطاتُ الفرنسيةُ عن الزعيم التونسي عبد العزيز الثعالبي بعد سجن استمرَّ 9 أشهر. وعبد العزيز الثعالبي زعيمٌ تونسي حاول التخلُّصَ من الاستعمار وظُلمِه، والرفعة بالمجتمع في الوقت ذاته. وقد تعرَّض الثعالبي للنفي والتَّرحال في سبيل دعوته ومبادئه. وقد تولى الثعالبي رئاسةَ الحزب الحر الدستوري التونسي الذي كان من أهدافِه: الفصلُ بين السلطات الثلاث. ضمانُ الحريات والمساواة. إجباريَّةُ التعليم."},{"id":4935,"era":"c14","t":"وضع فلسطين تحت الانتداب البريطاني بعد نهاية الحرب العالمية الأولى .","s":"وُضِعَت فلسطين تحت الانتداب البريطاني بعد نهاية الحرب العالمية الأولى، وكلَّفَت بريطانيا الصهيونيَّ هربرت صموئيل كمندوب سامي لها في فلسطين، وقد مكَّن هذا الوضعُ من ازدياد الهجرة اليهودية إلى فلسطين في موجاتٍ متتابعة، والتمكين لهم، ثم انتهى الأمرُ بقرار الأمم المتحدة بتقسيم فلسطين سنة 1947م."},{"id":4936,"era":"c14","t":"معركة أنوال الشهيرة وانتصار الأمير المغربي محمد بن عبد الكريم الخطابي على الإسبان .","s":"كان الجنرالُ الإسباني سلفستر قائِدُ قطاع مليلة يزحَفُ نحو بلاد الريف؛ لِيُحكِمَ السيطرة عليها، ونجح في بادئ الأمر في الاستيلاء على بعض المناطق، وحاول الأميرُ محمد بن عبد الكريم الخطابي أن يُحَذِّرَ الجنرال سلفستر من مغبَّةِ الاستمرار في التقدُّمِ والدخول في مناطق لا تعترف بالحماية الإسبانية الأجنبية، لكنَّ الجنرال المغرور لم يأبهْ لكلام الأمير، واستمرَّ في التقدُّمِ ممنِّيًا نفسه باحتلال بلاد الري"},{"id":4937,"era":"c14","t":"معركة ميسلون واحتلال دمشق .","s":"كان غورو قد أرسل إلى المَلِك فيصل كتابًا يشيرُ فيه إلى استغرابه من بدءِ الفساد والتمرُّد منذ دخول جيوش فرنسا للمنطقة بعد رحيل إنجلترا، وذلك في تموز 1920م، ثم أرسل إليه إنذارًا أو بلاغًا يدور حولَ خمسِ نقاطٍ، أهمُّها: قَبولُ الانتداب الفرنسي، وإلغاءُ التجنيد الإجباري. رفَضَ وزيرُ الحربية يوسف العظمة قرارَ التسريحِ للجيشِ ولكنَّه اضطرَّ للتوقيع على القرار مُكرهًا بحضور الملك فيصل، وكتب الملك فيصل بر"},{"id":4938,"era":"c14","t":"تتويج فيصل بن الحسين ملكًا على العراق مع توقيع صك الانتداب .","s":"كان فيصل بن الحسين ثالثُ الأبناء قد نُصبَ ملكًا على سوريا الجزءِ الأكبر من بلاد الشام، لكِنَّه لم يلبث أن طُرِدَ في العاشر من ذي القعدة 1338هـ / 25 تموز 1920م عندما دخل الفرنسيون إلى سوريا، وكانت إنجلترا بعد أن نكَثَت كلَّ العهود التي أعطتها للشريف حسين ظنَّت أنَّ فيصلًا أنسب أبنائه لحُكمِ العراق التي كانت تحت سيطرتها، فكتب وزيرُ الخارجية الإنجليزي كرزون إلى نائب الحاكِمِ الملكي في العراق يسألُه ع"},{"id":4939,"era":"c14","t":"مؤتمر الرياض الأول واتخاذ ابن سعود لقب سلطان نجد وملحقاتها  .","s":"عندما أنشأت بريطانيا عرشينِ ملكيَّينِ للهاشميين خصومِ الملك عبد العزيز، في العراق وشرق الأردن عام 1921م، غَضِبَ الملك من سياسة بريطانيا تجاهَه بعد أن أحاطوه بالأعداءِ، وأقاموا دويلاتٍ من حولِه ونَصَبوا من أعدائِه ملوكًا وقدَّموا لهم المساعداتِ المالية والسياسية، فدعا إلى عقد مؤتمر في الرياض حضره القادةُ العسكريون والشيوخُ والعلماء من نجدٍ وما حولها، وأُعلِنَ في هذا المؤتمر عن مبايعة الملك عبد العز"},{"id":4940,"era":"c14","t":"تتويج عبد الله بن الحسين ملكًا على شرق الأردن .","s":"ارتبط تأسيسُ إمارة شرقي الأردن بوصول الأمير عبد الله بن الحسين (الذي كان يشغَلُ منصب وزير خارجية الدولة العربية في الحجاز) إليها بناءً على الدعواتِ التي وُجِّهَت للشريف علي بن الحسين من قِبَل أعيان ووُجهاءِ مناطِقِ شرقي الأردن، وكذلك أعضاء حزب الاستقلال الذين جاؤوا للأردن من سوريا بعد معركة ميسلون 1920، وبعد طَردِ الملك فيصل من سوريا على يد الفرنسيين جاء أخوه عبد الله طالبًا للثأر، فلما وصل إلى مد"},{"id":4941,"era":"c14","t":"فرنسا تقسم سوريا الكبرى إلى عدة دويلات بعد أن فرضت عليها الانتداب  .","s":"استطاعت فرنسا أن تدخُلَ دِمشقَ بعد معركةٍ ميسلون، فقامت بتمزيق سوريا الكبرى واصطنعت بينها الحواجِزَ الجمركية والحدودَ المصطنعةَ، فأول ما قاموا به هو فصلُ لبنان عن سوريا باسم لبنان الكبير، وضمُّوا فيه جبل لبنان ومدن طرابلس وصيدا وصور بأقاليمها وأغلبيتها المسلمة، إضافة إلى بيروت وسهل البقاع وأغلَبُه أيضًا من المسلمين، وهذه أوَّلُ خطوة في محاباة فرنسا؛ حيث إن غورو كاثوليكي متعصِّبٌ، ثم قُسِّمت سوريا "},{"id":4942,"era":"c14","t":"خلع السلطان محمد السادس نفسه وتنازله عن الخلافة وتولي عبد المجيد الثاني .","s":"بعد أن تسلم محمد السادس الخلافةَ بأشهر استسلمت الدولةُ في الحرب العالمية الأولى واحتَلَّ الحلفاء أكثَرَ أجزاء الدولة وسيطروا على استانبول والمضائق، واحتلت اليونانُ الأقسامَ الغربية وضاعت البلدانُ العربية، فوضع السلطانُ ثِقتَه بمصطفى كمال فخاب ظنُّه؛ لأنه أصبح يعمل لنفسِه، فلما وجد السلطانُ محمد ذلك اعتزل السلطةَ وتنازل عن الخلافة في هذا العامِ، وبعد أقل من أربع سنوات من توليه للحكمِ؛ حيث رفض أن يك"},{"id":4943,"era":"c14","t":"مؤتمر لوزان يطالب بإلغاء الخلافة الإسلامية مقابل منح تركيا الاستقلال .","s":"بعد ثلاثةِ أيام من تسلُّم عبد المجيد الثاني الخلافةَ افتُتِحَ مؤتمر لوزان الذي حضره وفدُ أنقرة فقط، ووضَعَ رئيسُ الوفد الإنجليزي كرزون أربعةَ شُروطٍ للاعتراف باستقلال تركيا، وهي إلغاء الخلافة الإسلامية، وطردُ الخليفة من بني عثمان خارِجَ حدود تركيا، وإعلانُ علمانيةِ الدولة، ومصادرةُ أملاك وأموال بني عثمان، وربطُ نجاحِ المؤتمر على ذلك، فأخفق المؤتمَرُ، ورجع إلى البلاد الوفدُ التركي برئاسة عصمت إينون"},{"id":4944,"era":"c14","t":"تأسيس جمهورية الريف وتدخل فرنسا وإسبانيا لحلها .","s":"تأسَّست في 18 سبتمبر 1921 عندما ثار سكان منطقة الريف (شمال المغرب) على إسبانيا، وأعلنوا استقلالَهم عن الحماية الإسبانية للمغرب. عاصمة الجمهورية كانت أجدير، وعملتها كانت الريفان، وقدر عدد سكانها بـ 18، 350 نسمة. وقد أُعلِنَ محمد بن عبد الكريم الخطابي أميرًا للريف. وتم تشكيلُ الجمهورية رسميًّا في 1 فبراير 1923. وكان الخطابي رئيسَ الدولة ورئيس الوزراء في البداية، ثم تمَّ تعيينُ الحاج الحاتمي كرئيس لل"},{"id":4945,"era":"c14","t":"قواعد فرنسية جديدة للجنسية التونسية .","s":"قامت فرنسا بتطبيقِ قواعِدَ جديدة للجنسية بتونس تجيزُ فيها سحْبَ الجنسية التونسية من بعضِ المواطنينَ."},{"id":4946,"era":"c14","t":"ضم الملك عبدالعزيز حائل إلى حكمه .","s":"بعد أن أعلنت بريطانيا تنصيبَ فيصل بن الحسين في العراقِ، وعبد الله بن الحسين في شرق الأردن، زادت مخاوفُ الملك عبدالعزيز من تحالفهما مع ابن رشيد؛ فقرَّر المسارعةَ لضَمِّ حائل، فعاد لغزوها بقواتٍ كبيرة من ضِمنِها قواتُ الإخوان  (إخوان من أطاع الله) بزعامة فيصل الدويش، وبعد شهرين من الحصار استسلمت المدينةُ للملك عبدالعزيز، وأسَرَ معه محمد بن طلال إلى الرياض، وتزوج الملك عبدالعزيز من ابنةِ محمد بن طلال"},{"id":4947,"era":"c14","t":"أزمة الحج بين الملك عبدالعزيز والشريف حسين .","s":"على الرغمِ من انتهاء الأزمة بين الملك عبدالعزيز والشريف حسين، وتبادل الطرفين المبعوثين، والتأكيد على إحلال السلامِ بينهما، إلا أن الشريف حسين في هذا العام حدَّد عددَ حُجَّاج نجد، فاعترض الملك عبدالعزيز على هذا التحديدِ، ووجَّه خِطابًا إلى المعتَمد البريطاني في بغداد، فوجَّه الإنجليز خطابًا للشريف للدخولِ مع الملك عبدالعزيز في مباحثاتٍ لحَلِّ هذه المشكلة، فرفض الشريف وكتب للإنجليزِ بعدم استقباله لح"},{"id":4948,"era":"c14","t":"إلغاء الحماية البريطانية على مصر مع بقاء قوات الاحتلال  .","s":"دخلت مصر إلى القرن العشرين وهى مُثقلَةٌ بأعباء الاستعمار البريطاني بضغوطِه لنَهبِ ثرواتها، وتصاعدت المقاومةُ الشعبية والحركةُ الوطنية ضِدَّ الاحتلال بقيادة مصطفى كامل، ومحمد فريد، وظهر الشعورُ الوطني بقوة مع ثورة 1919 للمطالبة بالاستقلال، وكان لسعد زغلول ورفاقِه دورٌ بارز فيها بدعمٍ مِن الإنجليز للعمل من أجلِ إلغاء الحماية البريطانية على مصر في عام 1922 والاعتراف باستقلالِها على أيدي وطنيِّين تمَّ"},{"id":4949,"era":"c14","t":"إعادة النظر في بعض مواد معاهدة سيفر الظالمة .","s":"وافق الحُلفاءُ على إعادةِ النظر في بعضِ موادِّ معاهدةِ سيفر الظالِمة التي أُجبِرَت الدولةُ العثمانيةُ على قبولِها بعد هزيمتِها في الحرب العالمية الأولى، وحاول الحُلفاءُ الوصولَ إلى تسويةٍ للنزاع بين الأتراك واليونانيين، وقد رفض الأتراكُ الهدنةَ حتى يجلوَ اليونانيون عن الأناضول."},{"id":4950,"era":"c14","t":"غزو الإخوان  (إخوان من أطاع الله) حدود العراق .","s":"بعد أن استولى الملك عبدالعزيز على حائل واجه ثلاثَ قوًى محيطةٍ به ومعاديةٍ له في الشمال والغرب، ولم يتِمَّ ترسيمُ الحدود بين العراق وشرق الأردن وحائل ونجد، ولم تُحَلَّ الخلافات القبلية بين العراق ونجد، وفي عام 1921م تم تعيينُ يوسف بن سعدون قائدًا لقوات عراقية من الفرسان، وكان على عَداءٍ مع شيخ الظفير حمود بن سويط الذي هرب إلى الرياض، وطلب نجدةَ الملك عبدالعزيز، والتحقت بحمود مجموعةٌ من الإخوان من م"},{"id":4951,"era":"c14","t":"اتفاقية استقلال مصر المقيد بتحفظات بريطانية .","s":"بعد أن تألَّف الوفد المصري وسافر إلى باريس ولندن، ولم يُجدِ ذلك شيئًا حتى جرى اتِّفاقٌ بين المعتمد البريطاني في القاهرة وبين عبد الخالق ثروت، وعدلي يكن، وإسماعيل صدقي، في الرابع عشر من جمادى الأولى 1340هـ / 13 كانون الثاني 1922م، ونص الاتفاق على نقاطٍ، منها: أن تصبِحَ مِصرُ دولةً مستقلة لها سيادتها، ووافقت الحكومةُ البريطانية على اعتمادِ هذا الاتفاق، ولكن أدخَلت عليه بعضَ التعديلاتِ، ومنها: جَعلُ "},{"id":4952,"era":"c14","t":"معاهدة المحمرة لرسم حدود بين العراق ونجد .","s":"التقى الإنجليزي برسي كوكس مع الملك عبدالعزيز في المحمرة، وأكَّد الإنجليزُ على ضرورة إقامةِ حدودٍ بين نجد والعراق، وطالب الوفدُ النجديُّ رسمَ الحدود اعتمادًا على التقسيم القَبَلي المعروف للبدوِ، وتمَّ توقيعُ المعاهدة التي جَعَلت قبائِلَ المنتفق والظفير والعمادات من عنيزة تبعَ العراق، وجعلت شمر تابعةً لنجد، إلا أنَّ الملك عبدالعزيز رفض إبرامَ الوثيقة لأنَّ الظفير بزعامة حمود بن سويط قد احتَمَوا به و"},{"id":4953,"era":"c14","t":"غزو الإخوان (إخوان من أطاع الله) شرق الأردن وترسيم الحدود .","s":"شرع الإخوانُ يتحرَّكون شمالًا نحو شرق الأردن واحتلُّوا واحةَ الجوف بعد أشهرٍ واشتبكوا مع رجال شرقِ الأردن، واستولَوا على تيماء وتبوك وأخذوا الزكاة منهما إلى الرياضِ، ووصلوا إلى وادي السرحان وواحة بن شاكر، كما وصلوا إلى قلب شرق الأردن، وحدود سوريا وحدود العراق المباشر بين الممتلكات البريطانية؛ لذلك رأى كوكس المعتمد البريطاني في الخليج ضرورةَ تثبيت الحدود مع الملك عبدالعزيز؛ حيث تم اعتمادُ الحدود وا"},{"id":4954,"era":"c14","t":"إخضاع آل عائض في عسير وتأديب إمام اليمن .","s":"في هذا العام تمرَّد الأميرُ حسن آل عائض على ابنِ سعودٍ ونقَضَ العهدَ بتحريضٍ مِن إمام اليمن يحيى حميد الدين، فأرسل الملك عبدالعزيز قواتٍ نجديةً بقيادةِ ابنه فيصل، وجعل القيادةَ العسكريةَ إلى خالد بن لؤي أميرِ الخرمة (من محافظات منطقة مكة المكرمة) وأحدِ قادة الإخوان، والتحق بهم أثناء الطريق بدوٌ مِن قحطان وزهران وشهران، فاستولى فيصل على واحة بيشة ووصل إلى مشارفِ أبها، فهرب منها ابنُ عائضٍ ولم يستَط"},{"id":4955,"era":"c14","t":"صدور قانون الظهير البربري .","s":"صدر قانون الظهير البربري -والظهيرُ يعني المرسوم- أصدره المستعمِرُ الفرنسي، ونصَّ هذا الظهيرُ على جعْلِ إدارة المنطقة البربرية تحت سلطةِ الإدارة الاستعمارية، فيما تبقى المناطِقُ العربية تحت سلطة \"حكومة المخزن\" والسلطان المغربي، وتمَّ إنشاءُ محاكم على أساسِ العُرفِ والعادة المحلية للبربر، وإحلالُ قانون العقوبات الفرنسي محلَّ قانون العقوبات \"الشريفي\" المستَنِد إلى الشريعة الإسلامية؛ ومِن ثمَّ قام هذا"},{"id":4956,"era":"c14","t":"ثورة محمد بن عبد الكريم الخطابي على الإسبان والفرنسيين معًا في المغرب .","s":"كان الشعبُ المغربي قد ثار على السلطان عبد العزيز بن الحسن العلوي وخلَعَه عام 1908م بعد أن أطلق يدَ فرنسا وإسبانيا في المغرب، وبايع الشعبُ أخاه عبد الحفيظ بشَرطِ العمل على استرداد الجهاتِ المقتطعة على الحدودِ، ولكِنَّ عبد الحفيظ صانَعَ فرنسا التي اتَّفَقت سنة 1911 مع إسبانيا على إعطائِها الريفَ مقابِلَ السكوت على الاحتلال الفرنسي، وثار الشعبُ مرة أخرى، ففُرِضَت الحماية الفرنسية، وعَمَّت الثورةُ أرج"},{"id":4957,"era":"c14","t":"معاهدة 1922م وتوقيع صك الانتداب بين ملك العراق وبريطانيا .","s":"كان وزيرُ المستعمرات البريطانية ونستون تشرشل قد اتَّفق مع الملك فيصل ابن الشريف حسين قبل تسَلُّمِه المُلْك أن تكون معاهدةٌ بين الطرفين تحُلُّ مكانَ الانتداب، غيرَ أن الإنجليز قد فهموا من هذه العبارة أنَّ الاستقلالَ صورةٌ، والواقِعَ انتدابٌ؛ فالمَلِك ليس أكثَرَ مِن اسمٍ؛ فالمتصَرِّفُ الفعلي والحقيقي هو المعتمد السامي البريطاني، والوزراء ليس لهم سوى التوقيع على قراراته، وصاحِبُ الكلمة هو المستشار ال"},{"id":4958,"era":"c14","t":"وصول موسوليني للسلطة في إيطاليا .","s":"في هذا العام تولَّى الدوتشي بينيتو أندريا موسوليني رئاسةَ إيطاليا وشغَلَ منصِبَ رئيس الوزراء وأحيانًا وزارة الخارجية والداخلية، ويعتبَرُ موسوليني من الشخصيات الرئيسة والمهِمَّة بين المؤسِّسين الحقيقيِّين للفاشية، وفي عهده مارست إيطاليا أبشَعَ صُوَر الوحشية من أجل إخضاعِ الشعب الليبي للاستعمار الإيطالي، وأدخل إيطاليا الحربَ العالميَّةَ الثانية إلى جانبِ دُوَل المحور ضِدَّ دول الحلفاء."},{"id":4959,"era":"c14","t":"علماء العراق يقاطعون الانتخابات  .","s":"بعد إعلان الحكومة العراقية معاهدة 1922م التي تُرسِّخ الانتداب البريطاني في العراق، قاطع العلماءُ المشاركةَ في الانتخابات مالم يتِمَّ: 1/ إلغاء سياسة الضغط التي يمارسها المعتمد البريطاني. 2/ إطلاقُ حرية الاجتماعات والمطبوعات. 3/ سحبُ المستشارين الإنجليز من الألوية إلى بغداد. 4/ السماح بتأليف الجمعيات. 5/ السماح بإعادة المنفيِّين السياسيين إلى وطنهم."},{"id":4960,"era":"c14","t":"إلغاء مصطفى كمال أتاتورك السلطنة العثمانية .","s":"قام مصطفى كمال أتاتورك -الذي كانت بيده مقاليدُ الأمور في تركيا- بإلغاء السَّلْطَنة العثمانية، ونفيِ السلطان عبد المجيد الثاني، وكان ذلك تمهيدًا لإلغاءِ الخلافة الإسلامية التي أصدر قرارًا بإلغائها سنة 1924م!! ونفى جميعَ أسرة آل عثمان التي حكمت العالم الإسلاميَّ خمسة قرون. وبذلك نجحت الجهودُ الغربية الاستعمارية في تدمير الرباطِ الرُّوحيِّ بين المسلمين بعد عشراتِ السنواتِ مِن التآمُرِ والمكائد لإسقاط"},{"id":4961,"era":"c14","t":"معاهدة العقير وترسيم الحدود بين نجد والعراق والكويت .","s":"معاهدةٌ حدوديةٌ وُقِّعَت في العقير (ميناء قرب الأحساء)، كان الهدفُ منها إيجادَ حَلٍّ للخلاف بين الملك عبد العزيز والشريف حسين وأولاده في شرق الأردن والعراق، وأطماع الأتراك في الموصل، وقد مثَّلَ نجْدًا سلطانُ نجد عبد العزيز بن عبد الرحمن آل سعود، وكان صبيح بك نشأت وزيرَ المواصلات والأشغال عن الملك فيصل ملك العراق، أمَّا الكويت فقد مثَّلَها الميجور مور الوكيل السياسي البريطاني في الكويت طبقًا لاتفاق"},{"id":4962,"era":"c14","t":"إصدار فرنسا قانونًا جديدًا يتعلق بالجنسية الفرنسية في تونس .","s":"أصدرت فرنسا قانونًا جديدًا في تونس يمنَحُ الجنسية الفرنسية لكُلِّ من يطلُبُها، أو يُظهِرُ عواطِفَ نحو فرنسا، وبالتالي يصبحُ حامِلُها من رعايا فرنسا، ويستحق حمايتَها ودَعْمَها، فردَّ المسلمون على هذا القانون اجتماعيًّا وعَقَديًّا، فقاطعوا كلَّ مُسلِمٍ طلَبَ الجنسية الفرنسية، وعدُّوه خارجًا عن الإسلامِ، لا يصِحُّ دَفنُه في مقابر المسلمين! وهذه القوَّةُ في مواجهة القانون جعلت كثيرًا ممن أقدم على التج"},{"id":4963,"era":"c14","t":"صدور أول دستور مصري في ظل الاستقلال المقيد .","s":"عَقِبَ انتهاء الحرب العالمية الأولى قامت الثورةُ المصرية في عام 1919 مطالِبةً بالحرية والاستقلال لمصر، وإقامة حياة نيابية وديمقراطية كاملة. وأدَّت هذه الثورة إلى صدور تصريح في 28 فبراير 1922، والذي اعترف بمصرَ دولةً مستقلةً ذات سيادة (مع وجود تحفُّظات أربعة)، كما تضمَّن إنهاءَ الحماية البريطانية على مصر. واستنادًا إلى هذا الواقِعِ الجديد تمَّ وَضعُ دستور جديد للبلاد صدر في إبريل عام 1923، ووضعَته "},{"id":4964,"era":"c14","t":"إقامة حفلة بمناسبة اعتراف إنجلترا باستقلال شرق الأردن  .","s":"اعترفت إنجلترا باستقلال شرق الأردن، واحتفظت لنفسِها بالإشراف العسكريِّ، وبعضِ الإشرافِ الماليِّ عليه، والمعروف أنَّ هذا القسم كان تحت حكم ِالأمير عبد الله بن حسين بن شريف مكةَ، وفي 15 أيار أقيمَ حَفلٌ رَسميٌّ بمناسبة اعتراف بريطانيا باستقلالِ شرق الأردن، شارك فيه رجالاتُ الأردن وفلسطين، وأيضًا المندوب السامي البريطاني في فلسطين الصهيوني هربرت صموئيل، ومعه الجنرال كلايتون الذي يعمل في المكتب العربي"},{"id":4965,"era":"c14","t":"اعتراف بريطانيا بحكومة شرق الأردن تحت الإشراف البريطاني .","s":"قرَّرت بريطانيا أن يكونَ شرق الأردن دولةً مُتمتِّعةً بالحكم الذاتي، يحكُمُها الأمير عبد الله بن حسين بن شريف مكةَ، بعد مقابلته لوزير المستعمرات البريطاني وينستون تشرشل، تمَّ الاتفاق بأن تقومَ في شرقي الأردن إمارةٌ ذاتُ حكومة تتمتَّعُ بالاستقلال الإداري وتسترشِدُ برأي المفوض السامي الإنجليزي في القدس، وتتقاضى من إنجلترا معونةً سنوية، فوقَّع الأميرُ عبد الله بن الحسين على صكِّ الانتداب البريطاني على"},{"id":4966,"era":"c14","t":"بداية القضية الكردية في العراق  .","s":"بعد زيارة رئيس مجلس الوزراء العراقي عبد المحسن السعدون منطقةَ السليمانية قرَّر مجلِسُ الوزراء في جلسة المجلس يوم 28 ذي القعدة 1431ه الموافق 11يوليو 1923م: 1/ أنَّ الحكومة لا تنوي تعيينَ أيِّ موظَّف في الأقضية الكردية عدا الموظَّفين الفنيين. 2/ أن الحكومةَ لا تجبِرُ سكان المناطق الكردية على استعمال اللغة العربية في مراجعاتهم. فكان هذا القرارُ خاطئًا؛ فإن المناطق الكردية جزء من أرض العراق يعيَّنُ في"},{"id":4967,"era":"c14","t":"أعمال مصطفى كمال أتاتورك بعد أن تسلم الرئاسة .","s":"مصطفى كمال من سلانيك أو سالونيك مدينة يونانية، وهي مهبِطُ اليهود ومقَرُّهم، ومنها خرج وفيها نشأ، لذلك عدَّه كثيرٌ من الكُتَّاب من يهود الدونمة؛  ثمَّ إن أدواره التي لَعِبَها توحي بالعمالة الغربية؛ فقد صنعه الغَربُ ليظهَرَ في صورة البطل؛ وليكونَ مقبولًا عند الأتراك، ويكفي أنَّ أعمالَه تدُلُّ على باطنه؛ فقد منع الخليفةَ مِن الخروج للصلاة، ثم خفض مخصَّصاته للنصف، وحكم مصطفى كمال البلادَ بالحديدِ والن"},{"id":4968,"era":"c14","t":"احتلال الإيطاليين مدينة طرابلس وقضاؤهم على جمهورية ليبيا الأولى .","s":"في أعقاب الحرب العالمية الأولى التي انتهت سنة 1337هـ/ 1918م والتي خرجت إيطاليا منها مُنهَكةً، رأت إيطاليا مهادنةَ الليبيين، وتمَّ عقد اتفاق \"سوني\" بين الطرفين، اعترفت إيطاليا بموجِبِه بقيام الجمهورية، ونصَّ على إنهاء حالة القتال بينهما، مع الاعترافِ بالاستقلال الداخلي لطرابلس تحت سيادةِ ملك إيطاليا، وإنشاء مجلسِ نوابٍ محليٍّ، ومجلس آخر حكومي يشتركان في حكمِ البلاد. إلا أنَّه لم يقَدَّر لتلك الجمهو"},{"id":4969,"era":"c14","t":"مؤتمر الكويت لحل النزاعات الحدودية بين نجد والعراق والحجاز و الأردن .","s":"دعت الحكومةُ البريطانية كُلًّا من نجد والعراق وشرق الأردن والحجاز إلى تسويةِ القضايا الحدوديَّةِ في مؤتمر عُقدَ في الكويت برئاسة الكولونيل نوكس وزير البحرية الأميركية، اشترط الملك عبدالعزيز على نوكس أن يتِمَّ تعيينُ الحدود بين نجدٍ والحجاز وشرق الأردن من جهة، وعدم اشتراك مندوبِ العراق مع حكومتي الحجاز وشرق الأردن في المباحثات المشتركة، وأن يتِمَّ تناول المشكلات بين نجدٍ وتلك الحكومات بصورة منفردة،"},{"id":4970,"era":"c14","t":"سعد زغلول يشكل أول وزارة وفديَّة .","s":"قام سعد زغلول بتشكيل أول وزارة وفدية، وذلك عَقِبَ الفوز الذي حقَّقه حزبُ الوفد في الانتخابات التي أُجرِيَت في 27 من سبتمبر 1923، وفاز بأغلبية مقاعد البرلمان المصري."},{"id":4971,"era":"c14","t":"إلغاء الخلافة العثمانية الإسلامية والإعلان عن قيام جمهورية تركيا .","s":"بعد أن أخفق مؤتمر لوزان، وعاد رئيسُ الوفد التركي عصمت إينونو واختلف هو ومصطفى كمال مع رئيسِ الوزارة وبجانبه الجمعية الوطنية، فاستقال رئيس الوزارة، وبدأت الدسائِسُ، فحَلَّ مصطفى كمال الجمعيةَ الوطنية، وكثرت الفوضى وقرَّر مصطفى كمال إعلان الجمهورية، واجتمعت الجمعيةُ الوطنية، ودُعِيَ مصطفى كمال لتشكيل الوزارة فوافق، على ألا يُناقَشَ في تصرُّفاته، وشكَّل الوزارة، وأعلن الجمهورية بعد اجتماع المجلس الني"},{"id":4972,"era":"c14","t":"تغير ميزان القوى في الحجاز لصالح الملك عبدالعزيز ضد الشريف حسين .","s":"دخلت العلاقاتُ الحِجازية النجدية في مراحِلَ حاسمة في أواخر هذا العام، وزادت طموحات الملك عبدالعزيز في ضم الأراضي الحجازية مع تغيُّر الأوضاع في ظِلِّ تفوُّقِه بعد ضم الأحساء ثم حائل، ثم عسير، وضَعْف الدعم البريطاني للشريف حسين، وفشل مؤتمر الكويت، وتحميل الإنجليز الشريف المسؤوليةَ في ذلك، وإعلان الشريف حسين الخلافةَ على المسلمين بعد إعلانِ سُقوطِ الخلافة العثمانية، ورَفْض الدول الإسلامية وعموم المسل"},{"id":4973,"era":"c14","t":"مؤتمر الرياض لإقرار غزو الحجاز .","s":"دعا الملك عبدالعزيز إلى عقد مؤتمر في الرياض للأعيان والعلماء والشيوخ وزعماء القبائل؛ للتداول في شُؤونِ الحُجَّاج، وتمَّ اتخاذُ القرارات الخاصة بعدم صلاحية الشريف حسين في الإشراف على الأماكن المقدَّسة في الحجاز، بعد أن منع الحُجَّاج من نجد بأداء مناسِكِ الحج، وأيَّدَ المجتَمِعون استخدام القوة ضِدَّ الشريف في الحجاز."},{"id":4974,"era":"c14","t":"المصادقة على المعاهدة العراقية البريطانية 1922م .","s":"أحالت الحكومةُ العراقيَّةُ برئاسة جعفر العسكر المعاهدةَ العراقية البريطانية إلى لجنةِ للتدقيق فيها، وكانت بنودُ هذه المعاهدة قد وُضِعَت عام 1922م وهي تتضمَّنُ ترسيخ الانتداب البريطاني وانضمام العراق إلى عُصبة الأمم، وعندما أحيلت المعاهدةُ إلى لجنة مكونة من 15 عضوًا جرت مناقشاتٌ كثيرة حولها؛ فالمعارِضون يريدون تعديلَها والمؤيِّدون للحكومة يرون أنَّهم مضطرون للتصديقِ عليها خوفًا من التهديدات البريطا"},{"id":4975,"era":"c14","t":"وفاة الأديب مصطفى لطفي المنفلوطي .","s":"هو الأديبُ مصطفى لطفي بن محمد لطفي المنفلوطي، ولِدَ سنة 1292هـ بمنفلوط من مدن الوجه القبلي بمصر، من أبٍ مصري وأم تركية، من أسرة حُسينية النَّسَب، في بيت علمٍ وقضاء، حيث كان والده قاضيًا مشهورًا ونقيبًا للأشراف، وهو نابغةٌ في الإنشاء والأدب، انفرد بأسلوب نقيٍّ في مقالاته وكتبه. له شعرٌ جيد فيه رقَّة وعذوبة. تعلَّم في الأزهر، واتَّصَل بالشيخ محمد عبده اتصالًا وثيقًا، حتى إنه سُجِنَ بسببِه ستة أشهر، "},{"id":4976,"era":"c14","t":"قوات الملك عبدالعزيز على حدود العراق وشرق الأردن .","s":"عندما قرَّر الملك عبدالعزيز التقدُّمَ نحو الحجاز أرسل قوةً عسكرية إلى حدودِ نجد مع العراق، وأخرى على حدود نجد مع شرق الأردن؛ خوفًا من تدخُّل فيصل وعبد الله -نجلَي الشريف حسين- في حَسمِ الصراعِ على الحجاز."},{"id":4977,"era":"c14","t":"احتلال إيران لعربستان (الأحواز) .","s":"كانت منطقةُ الأحواز تسمَّى عربستان، وهي إمارةٌ عربيةٌ تقعُ في محيطٍ فارسي، وكانت مشمولةً برعايةٍ بريطانيةٍ يحكُمُها أميرُ الشيخ حسين خزعل، وهي إمارة مستقلَّة، إلى أن جاء الجنرال رضا بهلوي، ونظرًا لتأثير الحرب العالمية الثانية على بريطانيا وسَعْيِها لكسبِ إيران وضمانِ مساندتها لبريطانيا قامت بريطانيا بإعطاءِ إمارة عربستان لإيران في هذا العام، وَعَمِلَ الجنرالُ بهلوي على إنهاءِ حُكمِ آخِرِ حکَّامِ ا"},{"id":4978,"era":"c14","t":"تدويل طنجة لمصلحة المستعمر .","s":"كان لمدينة طنجة وضعٌ خاصٌّ بسبب موقعها المهم؛ لذا حرصت الدول المستعمِرة للمغرب أن يكونَ لها وضعٌ خاصٌّ، وقد شُغِلت الدول بأحداث الحرب العالمية الأولى؛ لذا لم تستطع وضعَ نظام لها، فلما وضَعَت الحربُ أوزارَها وضعت الدولُ الكبرى لطنجة نظامًا دوليًّا محايِدًا يقضي بأن يكون للميناء حاكِمٌ فرنسي إداري وله مساعدان إنجليزي وإسباني، والسلطة التنفيذية بيد هيئة المراقبة المؤلَّفة من فرنسا وإسبانيا وإنجلترا، "},{"id":4979,"era":"c14","t":"عصبة الأمم تقرِّر ضم الموصل للعراق  .","s":"كانت الموصِل جزءًا من الدولة العثمانية حتى نهاية الحرب العالمية الأولى، عندما احتلَّتْها بريطانيا، وبعد حرب الاستقلال التركية، اعتبرت تركيا الموصل من القضايا الحاسمة المحدَّدة في الميثاق الوطني التركي. وعلى الرغم من المقاومة المستمرة تمكَّنت بريطانيا من طرح هذه القضية في الساحة الدولية، كمشكلة حدود بين تركيا والعراق. فقرَّر مجلسُ عصبة الأمم في جلسته المنعقدة في الثالث من ربيع الأول عام 1343هـ / ال"},{"id":4980,"era":"c14","t":"دخول قوات الإخوان  (إخوان من أطاع الله) الطائف .","s":"بلَغَت قراراتُ مؤتمر الرياض قواتِ الإخوان المتمركِزة في تربة والخرمة (من محافظات منطقة مكة المكرمة)، ووصلهم الأمرُ بالاستعداد لفتح الطائف، فتقدموا إلى الحوية قرب الطائف، وهزموا القواتِ الحجازية ودخلوا الطائفَ بعد انهيار قوات الشريف حسين في معركة الهدا، فأرسل الشريف إلى بريطانيا يطالبها بالتدخُّل وعدمِ السماح للملك عبدالعزيز بتكرارِ ما فعله الإخوان في الطائف في أماكن أخرى، ولكِنَّ بريطانيا أجابت بأ"},{"id":4981,"era":"c14","t":"تنازل الشريف حسين عن الحكم لابنه علي .","s":"بعد دخول قوات الملك عبدالعزيز الطائفَ كتب أعضاءُ الحزب الوطني الحجازي من أشراف مكَّة وجُدَّة إلى الحسين يطلبون منه التنازُلَ عن الحُكمِ لولده علي، وبالفعل قرَّر الحسين التنازل ومغادرة الحجاز إلى العقبة مع أفراد أسرته، وأصبح علي بن الحسين ملكًا على الحجاز، وبويعَ بذلك، وهذا ما يشيرُ إلى انهيار الحكم الهاشمي في الحجاز عندما فقد الحسين حُلفاءَ الخارج (بريطانيا) وحُلَفاء الداخل (الأعيان والجيش)"},{"id":4982,"era":"c14","t":"دخول الإخوان (إخوان من أطاع الله) مكة بدون قتال ووصول الملك عبدالعزيز إليها .","s":"على الرغم من تنازُلِ الحسين لابنه علي فإنَّ الوضع في مكة لم يكن يسير لصالحِ الأشراف؛ لذلك غادر علي بن الحسين وحكومته مكةَ عندما تيقَّنوا عدم مقدرتهم منعَ قوات الإخوان عن دخول مكة بعد انهيار قوات الشريف في معركة الهدا. فتمكَّن الإخوان من دخول مكة بأسلحتِهم مُلَبِّين مُحرِمين بعُمرة بدون أي مقاومة تُذكَرُ، وأرسل قائدَا الإخوان سلطانُ بن بجاد وخالد بن لؤي رسائِلَ إلى معتمدِيِ الدول وقناصِلِها في جدة "},{"id":4983,"era":"c14","t":"تشكيل المجلس الأهلي بمكة .","s":"وجَّه الملك عبد العزيز بعد دخولِه مكَّةَ دعوةً لمجموعة من العلماء والأعيان فاجتمعوا، فقال يخاطبهم:\"إنَّ ديارًا كديارِكم تحتاجُ إلى اهتمامٍ زائدٍ في إدارة شؤونها، وعندنا مَثَلٌ يعرِفُه الناسُ جميعًا: أهلُ مكَّةَ أدرَى بشِعابِها. فأنتم أعلم ببلدِكم من البعيدين عنكم، وما أرى لكم أحسَنَ مِن أن تُلقى مسؤوليات الأعمال على عواتِقِكم، وأريد منكم أن تعَيِّنوا وقتًا تجتَمِعُ فيه نخبةٌ من العلماء والأعيان وا"},{"id":4984,"era":"c14","t":"وفاة سيرلي ستاك سردار الجيش المصري وحاكم السودان العام .","s":"هو سيرلي ستاك، سردار الجيش المصري وحاكم السودان العام، أحد موظَّفي الدفاع البريطانيين الكِبار، انتقل إلى قيادة الجيش المصري عام 1899، ثم عُيِّن قائدًا لقوة السودان عام 1902، ثم أصبح وكيلَ السودان ومديرَ المخابرات العسكرية. تقاعد عام 1910 وأصبح سكرتيرًا مدنيًّا لحكومة السودان، ثم عيِّنَ حاكِمًا عامًّا للسودان، وسردارًا للجيش المصري إلى أن قُتِلَ هذا العام، وكان قد قام باغتياله أحدُ الوطنيين المصريي"},{"id":4985,"era":"c14","t":"عقد الملك عبدالعزيز البحث عن النفط شرق البلاد مع الشركة البريطانية .","s":"مع اتساعِ رقعةِ ممتلكاتِ الملك عبدالعزيز وزيادةِ المصاريفِ على شؤون الدولة وقلَّةِ المواردِ، أخذ يبحَثُ عن مواردَ جديدةٍ؛ لتموين احتياجاتِ دولته الناشئة، فجاءت فكرةُ التنقيب عن النفط، فجَرَت مباحثاتٌ مع فرنك هولمز المغامر النيوزلندي الأصل، والضابط في الجيش البريطاني أثناء الحرب العالمية الأولى- مؤسِّس شركة الشرقية العامة في لندن، وقد حصل على عقد حَقِّ امتياز التنقيب عن النفطِ في الأحساءِ؛ لحساب شر"},{"id":4986,"era":"c14","t":"رضا خان البهلوي ينصب نفسه شاهًا لإيران .","s":"كان رضا خان بهلوي من ضباط الجيش القاجاري، وسرعان ما أبدى كفاءةً عالية فأصبح قائدًا لفرقة القوزاق، وكان طموحًا جدًّا وفي غاية الذكاء. وكانت البلاد تترنَّح، فصمَّم على إنقاذها، فقام بانقلاب عسكري، وأسقط الوزارة سنة 1340 هـ/1921م وأسندها لسياسيٍّ إيراني شهير هو ضياء الدين طباطبائي، وذلك ليحكُمَ مِن ورائه، وتتوارى أهدافُه الديكتاتورية. فتولى وزارة الحربية ثمَّ رئاسة الوزراء، ثم خطا رضا خان خطوتَه الكب"},{"id":4987,"era":"c14","t":"نفي الشريف حسين إلى قبرص .","s":"بعد انتقالِ الشريف حسين إلى العَقَبة -جنوب الأردن- عَمِلَ على دعمِ ابنه علي في مواجهتِه للملك عبدالعزيز بإرسال الأموالِ والرجالِ، فغَضِبَ الملك عبدالعزيز وطلب من الإنجليز إخراجَ الحسين من العقبة، وإلا سيهاجمه هناك، فقررت بريطانيا نقْلَه إلى قبرص، فلما رفض الانتقالَ أقنعه ابنُه عبد الله بمغادرة العَقَبة وعدم إثارة المشكلاتِ مع بريطانيا، ومكث في قبرص 7 سنوات، ثم عاد منها بعد مرضه إلى عَمَّان سنة 193"},{"id":4988,"era":"c14","t":"الثورة السورية الكبرى (ثورة 1925م) ضد الاحتلال الفرنسي .","s":"في عام 1924 ألَّف الدكتور عبد الرحمن الشهبندر بدمشق حزبًا سياسيًّا سمَّاه حزب الشعب، وتولى رئاسته، وأطلق على نفسِه لقب الزعيم، وأخذ يعمَلُ في تنظيم العمل السياسي ويدعو إلى الوَحدة العربية، ويطالِبُ بإلغاء الانتداب، وإقامة جمهورية سورية في نطاق الاتحاد مع جميع البلدان العربية المستقِلَّة؛ ولتحقيق ذلك بدأ الدكتور عبد الرحمن الشهبندر الاتصالَ بزعماء ووجهاء المدن السورية يحثُّهم على الثورة ضِدَّ الاست"},{"id":4989,"era":"c14","t":"الاتحاد السوفيتي يعلن قيام جمهورية تركمانستان ويضمها إلى إمبراطوريته .","s":"كان الروسُ قد احتلُّوا جمهورية تركمانستان -من الشعوب التركية- في عام 1881م، ودخل الشيوعيون عاصمتَها عشق أباد في 1918م بعد مقاومة ضارية من السكان المسلمين، وفي عام 1918-1921م حارب التركمانُ البولشيفيين أثناء الثورة الروسية. وفي عام 1921م ضَمَّ البلاد إلى جمهورية تركستان الاشتراكية السوفيتية. وفي عام 1924م أصبحت تركمانستان جمهوريةً اشتراكية سوفيتية تابعةً إلى الاتحاد السوفيتي. وفي عام 1990م أصبحت ال"},{"id":4990,"era":"c14","t":"أوضاع الحجاز بعد دخولها تحت حكم الملك عبدالعزيز .","s":"بعد أن ضَمَّ الملك عبدالعزيز الحجازَ حاول الإبقاء على النظام الإداري الذي وضعه المَلِكُ حسين في الحجاز، والتوفيق بين عُلماء الدين في نجد والحجاز، واستمَرَّت أعمال الشركات الأجنبية في الحجاز، وكان الوضعُ في الحجاز أكثَرَ تطورًا من نجد؛ حيث وجودُ الإدارة وَفقَ المعايير العثمانية والميزانية المالية، والجيش النظامي والمدارس على النظام الحديث حتى المرحلة الثانوية، كما كان يوجدُ في الحجاز صحيفة \"القبلة\""},{"id":4991,"era":"c14","t":"ثورات الأكراد ضد سياسة التتريك في تركيا .","s":"في عام 1919م ساهم المثقَّفون والفئات الواعية من الأكراد في حركةِ التحرُّر الوطني التركية التي تزعَّمها مصطفى كمال (أتاتورك) ولا سيما من خلال جمعية الدفاع عن حقوقِ الأناضول الشرقي أي (كردستان تركيا)؛ اعتقادًا منهم بأن مساهمتَهم مع إخوانهم الأتراك في الكفاحِ ضِدَّ الاستعمار ستؤدِّي إلى نيل حقوقهم القومية، وحضر اجتماعَ المجلسِ الوطني التركيِّ الكبير في أنقرة عام 1920م اثنان وسبعون نائبًا كرديًّا تعاو"},{"id":4992,"era":"c14","t":"تطور التعليم في عهد الملك عبد العزيز  .","s":"في بدايةِ عَهدِ الملك عبد العزيز كان التعليمُ في معظم أنحاء الجزيرة العربية -عدا منطقتي الحجاز والأحساء اللَّتينِ كانتا تخضعان للحكم العثماني- يعتَمِدُ على النظام التقليدي (الكتاتيب)، ولم يكن في نجدٍ وما حولها أيُّ مدرسة نظامية، وإنما حلقات لدراسة العلوم الشرعية، والتاريخ واللغة في المساجد والجوامع والكتاتيب التي يُعلَّم فيها الأطفال في المنازل القراءة والكتابة وحفظ القرآن، وتمَّ فتحُ أول مدرسة في"},{"id":4993,"era":"c14","t":"التعليم في عهد الملك عبد العزيز .","s":"لَمَّا رأى المَلِكُ نمطَ التعليم المنتَشِر في الحجاز أُعجِبَ به، فأُنشِئَت في مكة إدارةُ المعارف العامة، وربَطَها بالنائب العام، ويديرُ أعمالَها مديرٌ عام، وكان من أبرز المشاكِلِ التي واجهت إدارةَ المعارف خلوُّ المدارس الابتدائية من المعلِّمين (المتعلِّمين) فأنشأت الإدارةُ في مكَّةَ المعهدَ العلميَّ السعوديَّ لإعداد معلِّمي المرحلة الابتدائية، بالإضافةِ إلى إرسال أوَّلِ بَعثةٍ مِن الطلاب إلى الخار"},{"id":4994,"era":"c14","t":"تشكيل الوزارات والإدارات الحكومية الحديثة في نجد والحجاز .","s":"بعد أن استقَرَّ الوضعُ في الحجاز للملك عبد العزيز بدأ بإدخال التنظيمات الحديثة في إدارة مملكة الحجاز ونجد وملحقاتها، مستفيدًا من بعض الشخصيات العربية الموجودة في الحجاز، كما استقطب شخصياتٍ أخرى من عدد من الدول العربية ذات خبرة إدارية وسياسية وإعلامية؛ فتأسَّست عام 1343هـ إدارة الأمن العام، ثم أصبحت مديرية الشرطة العامة لحماية الأخلاق والتفتيش والمحاسبة ومراقبة الأجانب، ولها إداراتٌ في كل مدينة ونا"},{"id":4995,"era":"c14","t":"تطور القطاع العسكري بعد ضم الملك عبدالعزيز الحجاز إليه .","s":"كانت قواتُ الملك عبد العزيز في نجد تتشكَّلُ مِن كلِّ فردٍ محاربٍ يحمِلُ السِّلاحَ من سنِّ 13 إلى سن 70، وتنقسِمُ إلى عدة أقسام: أهل العارض، والحضر، والإخوان (إخوان من أطاع الله)، والبدو، وكان الحرسُ الملكي (جيش الجهاد) من أهل العارض يتولى حمايةَ الملك والأمراء والأسرة المالكة، وكان مع جيشِ الجهاد جيشُ الإخوان من قبائل البادية الرحُّل، والتي تحولت الهجر فيه إلى ثكناتٍ عسكرية، وظلَّ هذا النظام قائمً"},{"id":4996,"era":"c14","t":"نهاية دولة القاجاريين وبدء الأسرة البهلوية وأولهم رضا بهلوي ملكًا لإيران .","s":"كان أحمد شاه من الأسرة القاجارية ملك بلاد فارس (إيران) عندما أُلغيت الخلافة الإسلامية سنة 1342ه. وكان أحمد شاه منصرفًا إلى اللهو، وأما المتصَرِّف الفعلي في البلاد فهو رئيس الوزراء رضا بهلوي، وهو يتلاعَبُ بالكُتَل النيابية كيف يشاء، والمهيمِن على الوضع، واستمر الأمرُ على ذلك حتى قدَّم في 12 ربيع الأول نائبُ رئيس المجلس النيابي محمد تدين زعيمُ حزب التجديد نداء موقعًا من ستة وسبعين نائبًا جاء فيه: نظ"},{"id":4997,"era":"c14","t":"تنازل مصر لليبيا عن واحة جغبوب .","s":"تنازلت مصر لليبيا عن واحة جغبوب التي كانت من معاقِلِ الدعوة السنوسية، وذلك بإيعازٍ مِن بريطانيا، وتمَّ بعدها بأيامٍ عَقدُ اتفاق بين كلٍّ من إنجلترا وإيطاليا في 20 جمادى الأولى 1344هـ والذي تمَّ بمقتضاه النزولُ عن واحة جغبوب وضَمُّها مع أجزاء أخرى من غربِ مِصرَ إلى ليبيا التي كانت تحت الاحتلالِ الإيطالي."},{"id":4998,"era":"c14","t":"مبايعة الملك عبدالعزيز ملكًا على الحجاز وسلطان نجد وملحقاتهما .","s":"عُقِدَ اجتماعٌ بين أعيان الحجاز وخاصةً جدة، وتقرر فيه مبايعة الحجازيين عبدَ العزيز بن سعود الذي أعلن نفسه ملكًا على الحجاز وسلطان نجد وملحقاتهما، وكان قد انتزع مكَّةَ من الشريف حسين بن علي."},{"id":4999,"era":"c14","t":"استسلام جدة للملك عبدالعزيز بن سعود سلطان نجد وملحقاتها .","s":"انتقل المَلِكُ علي بن الحسين إلى جُدَّة قبل دخول قوات الإخوان  (إخوان من أطاع الله) مكة، واتخذها عاصمة لمملكته، ولَمَّا استقر الملك عبدالعزيز في مكة حاول أن ينهيَ قضية جُدَّة مع علي بن الحسين بالسِّلمِ، لكِنَّه رفض، ففرض السلطانُ الحصارَ عليه في الوقت الذي كان قادة الإخوان (إخوان من أطاع الله) يطالبون وبشدةٍ اقتحام جدة مع تقديم الضمانات بالمحافظة على سلامة الرعايا الأجانب وقناصِلِهم، لكِنَّه رُفِض"},{"id":5000,"era":"c14","t":"إصدار الحكومة التركية قرارًا بقراءة القرآن الكريم باللغة التركية .","s":"قرَّرت الحكومة التركية بقيادة مصطفى كمال أتاتورك قراءةَ القرآن الكريم باللغة التركية بدلًا من العربية!! وكان حجَّتُها في ذلك أنَّ الأتراك لا يستطيعون تلفُّظَ وكتابة بعضِ الحروف العربية!!"},{"id":5001,"era":"c14","t":"الاتحاد السوفيتي أول بلد يعترف بمملكة الحجاز الجديدة .","s":"كان الاتحادُ السوفيتي أوَّلَ بلدٍ اعترف بالمملكة الجديدة، وسُلِّمَت مذكِّرةٌ إلى الملك عبدالعزيز بهذا الخصوص"},{"id":5002,"era":"c14","t":"عقد المؤتمر الإسلامي بمكة  .","s":"دعا المَلِك عبد العزيز بن سعود مَلِكُ الحجاز وسلطان نجد وملحقاتهما إلى عقدِ مؤتمر إسلامي عالميٍّ في مكة بعد أداء فريضة الحج؛ للبحث في شؤون المسلمين، واقتراح سُبُل توحيد كلمتهم، والنَّظَر في مختلف المشكلات والقضايا الإسلامية، ولم تكُن الخلافةُ مدرجةً في جدول أعمالِه، ولَبَّت الدعوةَ أقطارٌ إسلامية كثيرة، وبدأ المؤتمَرُ جلساته، وألقى الملك كَلِمتَه التي تعهَّد فيها بأنه سيرعى الأماكِنَ المقدَّسة، وس"},{"id":5003,"era":"c14","t":"المحمل المصري وموقف  إخوان من أطاع الله  منه .","s":"في موسِمِ حَجِّ تلك السَّنةِ، في اليومِ الأوَّلِ مِن عيدِ الأضحى،رأى الإخوان  (إخوان من أطاع الله) المحمَلَ القادِمَ مع الحجِّ المصري على جملٍ يتهادى بين الجموع، تحيطُ به موسيقاه وعساكِرُه، فقاموا يرشقونَه بالحجارة وهم بملابسِ الإحرام، ولم يكنْ مِن أمير الحج المصريِّ إلَّا أنْ أمَرَ بنَصبِ المدافع والرشَّاشات وإطلاق نيرانها على جموعِ الإخوانِ (إخوان من أطاع الله)، فقتل منهم خمسةً، وجرح آخَرون، ولَ"},{"id":5004,"era":"c14","t":"عقد مؤتمرات إسلامية لإحياء مؤسسة الخلافة الإسلامية .","s":"أدَّى سقوط الخلافة الإسلامية عام 1342هـ/ 1924م لانعقاد عدَّة مؤتمرات، وهي على وجه التحديد: مؤتمر مكة المكرمة عام 1342هـ/ 1924م، ومؤتمر الخلافة بمصر عام 1344هـ / 1926م، ثم مؤتمَر العالم الإسلامي بمكة المكرمة عام 1926م، ومؤتمر القدس عام 1349هـ / 1931م. وكان الهدفُ من هذه المؤتمرات إحياءَ مؤسسة الخلافة، ثم تعدَّدت أهدافها إلى إيجادِ شَكلٍ من أشكال الانعقاد المنتَظِم، وصولًا إلى منظمة إسلامية دائمة، إ"},{"id":5005,"era":"c14","t":"معاهدة مكة بين الإدريسي والملك عبدالعزيز لحماية جازان .","s":"كان السيد محمد بن علي بن أحمد الإدريسي قد أوصى المَلِكَ عبد العزيز بأولاده من بعده، فلما دَبَّ الخلاف بينهم بعد وفاته أرسل الملك عبد العزيز الأميرَ عبد العزيز بن مساعد بن جلوي فأنهى الصراع الذي نشب بينهم، وعَيَّن حسن الإدريسي بدلًا من أخيه علي، وعندما غزت قواتُ إمام اليمن يحيى حميد الدين تهامةَ عسير بقيادة عبد الله الوزير واحتَلَّ موانئ تهامة ومدنها، عين الإمامُ ولاتَه عليها، ثم واصل جيشُ الإمام ي"},{"id":5006,"era":"c14","t":"إنشاء أول مجلس شورى في الحجاز .","s":"لَمَّا صَدَرت التعليماتُ الأساسيَّةُ للمملكة الحجازية تألَّفَ بمقتضاه أوَّلُ مجلِسٍ للشورى مؤلَّف من النائب العام ومستشاريه، ومن ستة ذوات يعيَّنون من قِبَل صاحب الجلالة المَلِك ممَّن فيهم اللياقة والاقتدار، ويرأسُه النائب العام الأمير فيصل، أو معاوِنُه، أو أحد مستشاريه، وبيَّن الأميرُ فيصل في كلمته الافتتاحية للمجلس مهامَّ واختصاصات هذا المجلسِ."},{"id":5007,"era":"c14","t":"قطع العلاقة بين مصر ومملكة الحجاز  .","s":"بعد حادثةِ المحمَلِ في حَجِّ العام الماضي بمَنْعِ دخولِه مكَّةَ، أمر المَلِكُ فؤاد بقطع إرسالِ كِسوةِ الكعبة وريعِ أوقافِ الحرمين في الديار المصرية، وقَطْع العلاقة مع مملكةِ ابن سعود، وعلى الرَّغمِ أنَّ المَلِكَ عبد العزيز أرسل ابنَه سعودًا لمعالجة المشكلة وتصفية الجوِّ مع القصر الملكي إلَّا أنَّ الجفوةَ استمَرَّت بين مصر والسعودية، فدعا الملك عبد العزيز عام 1354 في حديثٍ له مع صحفيٍّ مصريٍّ إلى ت"},{"id":5008,"era":"c14","t":"قيام مصطفى كمال أتاتورك بإلغاء الطرق الصوفية في تركيا .","s":"قام مصطفى كمال أتاتورك بإلغاء الطرُقِ الصوفية في تركيا، وذلك في محاولاته التي بدأها بإبعادِ تركيا عن الإسلامِ، وأيِّ مظهر من مظاهر التدين، وقَطْع كل السبل التي تربط تركيا بالإسلامِ أو بالمسلمين، وحتى الفِرَق المنحرفة، كالطُّرُقيَّة الصوفية لم تسلَمْ من بطشِ أتاتورك."},{"id":5009,"era":"c14","t":"صدور وثيقة التعليمات الأساسية للمملكة الحجازية  .","s":"أقام المَلِكُ عبد العزيز نظامًا للسُّلطةِ الإدارية، وأصدر وثيقةً باسم التعليمات الأساسية للمملكة الحجازية، وتُسَمَّى الدستور، ونصَّت على الارتباط الوثيق بين أجزاء المملكة الحجازية ومناطِقِها، وأنَّها دولةٌ مَلَكيةٌ شُوريةٌ إسلاميَّةٌ مُستَقِلةٌ، عاصِمتُها مكَّةُ، وإدارتها بيَدِ الملِكِ، وهو مقَيَّدٌ بأحكام الشَّرعِ، ونَصَّت الوثيقةُ على تعيين نائبٍ للملك في الحجاز، ورؤساء الشُّعَب التابعين له، وسِ"},{"id":5010,"era":"c14","t":"زيارة الأمير فيصل بن عبد العزيز الثانية لأوروبا .","s":"ما إن تم الاعتراف بالملك عبد العزيز مَلِكًا للحجاز وسلطانًا على نجد وملحقاتها حتى دعت بريطانيا نظيرتَها السعودية لإجراء مباحثات في لندن، كخطوة لتعزيز العلاقة بين البلدين، فأرسل الملك عبد العزيز ابنه فيصلًا ونائبه في الحجاز مرة أخرى إلى بريطانيا نيابةً عنه وكان عمره 22 سنة، وكان معه في الزيارة عبد الله الدملوجي مدير الشؤون الخارجية في مملكة الحجاز. وقد حَظِيَ الأمير فيصل باستقبال ضَخمٍ من قِبَل كبا"},{"id":5011,"era":"c14","t":"الامتيازات الأجنبية في الحجاز بعد دخولها تحت حكم الملك عبدالعزيز .","s":"بعد أن ضمَّ  الملك عبدالعزيز الحجازَ عام 1344هـ رأى أنَّ من أولى الواجبات أن يعمَلَ على تأمين سلامة الحجاج، ويعيدَ ريعَ أوقاف الحرمين الموجودة في العالم الإسلامي، ويعمَلَ على تشغيل سكَّة حديد الحجاز، لكنه اصطدم بالامتيازاتِ التي يتمتَّعُ بها رعايا الدول الأوروبية، والتي حصلت عليه تلك الدولُ مِن خلال المعاهدات التي تمَّت بينها وبين الدولة العثمانية في جميعِ أراضي الدول العثمانية الواسعة، بحيث تُطَب"},{"id":5012,"era":"c14","t":"وفاة الشيخ محمد الخضري صاحب الدراسات التاريخية الإسلامية .","s":"هو الشيخُ محمد بن عفيفي الباجوري، المعروف بالشيخ الخضري. باحث وخطيب من علماء الشريعة والأدب وتاريخ الإسلام، وهو صاحب الدراسات التاريخية الإسلامية. ولد بمصرَ سنة1289ه، وكانت إقامتُه في (الزيتون) من ضواحي القاهرة، تخرج بمدرسة دار العلوم، وعُيِّن قاضيًا شرعيًّا في الخرطوم، ثمَّ مدرسًا في مدرسة القضاء الشرعي بالقاهرة، مدة 12 سنة، وأستاذًا للتاريخ الإسلامي في الجامعة المصرية، فوكيلًا لمدرسة القضاء الشر"},{"id":5013,"era":"c14","t":"معاهدةُ جُدة بين حكومة بريطانيا وحكومة ملك الحجاز وملحقاتِها .","s":"تمَّت معاهدةُ جُدة بين حكومة بريطانيا وحكومة ملك الحجاز وملحقاتِها؛ لتوطيد العلاقة بينهما، وتأمين مصالحهما، وقد مثَّل بريطانيا جلبرت فلكنجهام كلايتن، بينما مثَّل حكومة ملك الحجاز وملحقاتها الأميرُ فيصل بن عبد العزيز نائب الملك في الحجاز، وأهم ما جاء في هذه المعاهدة: اعترافُ الحكومة البريطانية بالاستقلال التام لعبد العزيز آل سعود ملكًا على الحجاز ونجد، وتعهَّد الجانبان بالحفاظ على السلام والصداقة ب"},{"id":5014,"era":"c14","t":"وفاة سعد زغلول الملقب بزعيم نهضة مصر السياسية .","s":"هو سعدُ بنُ إبراهيم زغلول، لُقب بزعيم نهضة مصر السياسية، وكان من أبرز خطبائِها في عصره. ولِدَ في إبيانة من قرى الغربية في يوليو عام 1858م وتوفِّيَ والده وهو في الخامسة، التحق سعد زغلول في السابعة من عمره بكُتَّاب القرية، حيث مكث فيه خمس سنوات، تعلَّم فيه القراءة والكتابة، وحَفِظ القرآن الكريم في سنة 1873م. ثم انتقل سعد زغلول إلى القاهرة للالتحاق بالأزهر، وتتلمذ على يد الشيخ محمد عبده، ولازم جمالَ "},{"id":5015,"era":"c14","t":"هجوم الإخوان  (إخوان من أطاع الله) على مخفر بُصية في الحدود العراقية .","s":"أقامت حكومةُ العراق بدعمٍ من الإنجليز مخفرًا على ماء بُصية في الحدود النجدية العراقية، وأعلنت رسميًّا عَزْمَها بناء حصون أخرى، ورأى الملك عبد العزيز في ذلك مخالفةً للمادة الثالثة من معاهدة العقير عام 1915م التي تنصُّ على عدم استخدام أيٍّ من الطرفين الآبار الموجودة على أطراف الحدود لأيِّ غرض حربي، كوضع قلاع عليها، أو تعبئتها بالجند، فاحتجَّ الملك عبد العزيز على هذا الخَرقِ الصريح للاتفاقيات المبرمة"},{"id":5016,"era":"c14","t":"اكتشاف النفط في العراق  .","s":"تم اكتشافُ النفط العراقي في عهد وزارة جعفر العسكري في كركوك يوم 18 ربيع الثاني من هذا العام، وبينما كان المهندسون والعمال يمارسون أعمالهم تدفَّق النفط وأدى إلى مقتَلِ عددٍ منهم."},{"id":5017,"era":"c14","t":"توقيع العراق مع إنجلترا معاهدة 1927م .","s":"كانت معاهدة 1922م والتي تمت المصادقة عليها في 12 يونيو 1924م قد لَقِيت معارضةً شديدة من العراقيين، وما زالت المعارضة لأنَّها تتضمن تكريسَ الانتداب والاحتلال البريطاني للعراق؛ فبدأ الجانبان مفاوضاتِهما لتعديل هذه المعاهدة في بغداد، ثم انتقلت المفاوضاتُ إلى لندن بإشراف الملك فيصل وإدارة جعفر العسكر، وتعَذَّرت المفاوضات بسبب عدم جِدِّية البريطانيين في تطوير الجيش العراقي، وأن المعاهدة دون معاهدة 1922"},{"id":5018,"era":"c14","t":"المعاهدة الأردنية البريطانية بدل صك الانتداب .","s":"كانت حكومة بريطانيا قد وعدت بالاعترافِ باستقلال الأردن ومضت خمسُ سنوات قبل أن تنَفِّذَ بريطانيا هذا الوعدَ استجابة لمساعي الأمير عبد الله وضغوط لجنة الانتداب التابعة لعُصبة الأمم، وفي 20 شباط 1928م تمَّ في القدس التوقيعُ على المعاهدة ومن بنودها وضع قانون أساسي للبلاد (الدستور) وتنازُل حكومة الانتداب للأمير عبد الله عن السُّلطتين التشريعية والتنفيذية، ويبقى لحكومة بريطانيا حقُّ الاحتفاظ بقوات مسلَّ"},{"id":5019,"era":"c14","t":"وفاة الإمام عبد الرحمن بن فيصل والد الملك عبد العزيز  .","s":"هو الإمامُ عبد الرحمن بن فيصل بن تركي بن عبد الله، من آل سعود كان رابع أبناءِ فيصل بن تركي، حصل بينه وبين ابن رشيد قتال على الرياض وتمكَّن ابن رشيد من هزيمة رجال عبد الرحمن في (المليدة) سنة 1308هـ فرحل عبد الرحمن إلى الجنوب، ونزل في قبائل (مرة) فأقام سبعةَ أشهر، وأرسل أهلَه إلى الأحساء -وكانت لا تزال في يد الترك- وجمَعَ من توسَّم فيهم النَّجدةَ وأعاد الكَرَّةَ على الرياض، فأخرج منها رجالَ ابنِ رشي"},{"id":5020,"era":"c14","t":"معركـة قــارة عافية في ليبيا .","s":"معركـةٌ شهيـرة وقَعَت بين الليبيِّين والإيطاليِّين بليبيا في الجفرة وتحديدًا قرب هون، وكان قائدُ المجاهدين في تلك المعركة المجاهِدَ قضوار السهولي الورفلي من قبيلة السهول الليبية، وانتصر فيها انتصارًا باهرًا على قوات الاحتلال الإيطالي، وقَتَل فيها معظم الضباط الإيطاليين، وقَتَل فيها القائِدَ قضوار السهولي وعددًا من قادةِ الجهاد الليبي، وكانتقام من المجاهدين تمَّ التنكيلُ بأهالي هون وشَنْقُ مَن قُبِ"},{"id":5021,"era":"c14","t":"اجتماع الجمعية العمومية في الرياض  .","s":"عُقِدَ اجتماع الجمعية العمومية في أحد أروقة القصر، وحضره نحو 800 من علماء ورؤساء حضر وبدو، بينما قاطَعَ زُعماءُ الإخوان  (إخوان من أطاع الله) اجتماعَ الجمعية العمومية استنادًا إلى أن مؤتمر الرياض فيه الكفاية، بعد أن ثبت لهم رفضُ الإنجليز هدمَ المخافر، وبالتالي أصبح على الإمام أن يشُنَّ الجهاد أو ينتدب المسلمون أنفسهم للجهاد. فلم يحضُرْ فيصل الدويش ولا سلطان بن بجاد، وأناب فيصل الدويش ابنه عزيز. اف"},{"id":5022,"era":"c14","t":"معركة السبلة .","s":"لَمَّا بلغ عبد العزيز أنَّ ابن بجاد زعيم عتيبة وأمير الغطغط -أول هجرة لقبيلة عتيبة- التقى بجماعةٍ مِن تجار القصيم فقتَلَهم واستباح أموالَهم، أذن بالزَّحفِ على الإخوان العصاةِ، فاجتمع مع عبد العزيز على حَربِ المتمرِّدين من الإخوان (إخوان من أطاع الله) حَضَرُ نجدٍ وبوادي حرب وقحطان وسبيع من الإخوان، وقِسْم من عتيبة المعارضين للدويش وابن بجاد، وخرج بهم عبد العزيز في 22 رمضان من هذا العام، وقد تجمَّعت"},{"id":5023,"era":"c14","t":"وفاة ضيدان بن حثلين شيخ العجمان .","s":"هو ضيدان بن خالد بن فيصل بن حزام بن مانع آل حثلين، شيخ قبيلة العجمان، ومن قادة الإخوان (إخوان من طاع الله) الذين شاركوا مع الملك عبد العزيز في نشرِ الدعوة وتوحيد البلاد. إلا أنه اختلف معه حولَ استخدام المخترعات الحديثة، كالهاتف والبرقيات، ومرونتِه في التعامُل مع دول وفئات يرى ابن حثلين أنَّه من الخطأ التعامُلُ معهم؛ لانحرافهم عن الدينِ الصَّحيحِ، وقد انضَمَّ ابن حثلين مع زعماء الإخوان فيصل الدويش،"},{"id":5024,"era":"c14","t":"الاتحاد السوفيتي يعلن عن قيام جمهورية طاجيكستان ويضمها إلى إمبراطوريته  .","s":"لَمَّا ضَعُفَت دولةُ المغول في طاجيكستان سيطر الروسُ عليها وكانت أكثَرُ المحاولات الروسية للسيطرةِ عليها في سنة1869م، تمكَّن البلاشفة الشيوعيون من الاستيلاء على طاجيكستان في سنة 1917م وأصبحت جمهورية اتحادية في سنة 1922م. وفي أوائل 1990م شهدت جمهورية طاجيكستان انتفاضةً ضِدَّ السلطة السوفيتية؛ مما أدى إلى العديد من المظاهرات والعصيان المدني، وقد استخدمت السلطاتُ القواتِ المسلحةَ ضِدَّ العصيان. وقبل "},{"id":5025,"era":"c14","t":"انقلاب ابن السقا في أفغانستان ثم سيطرة محمد نادر على الحكم .","s":"ساءت سيرةُ المَلِكِ أمان الله خان كثيرًا، وسار سيرةَ الأوربيين في زِيِّه وغَيِّه، وترفَّع على شعبِه، بل بدأ يُلزِمُه بما هوَتْه نفسُه من الملابس الأوروبية وسفورِ النساء واختلاطهم، وزاد على ذلك أن أثقَلَهم بالضرائبِ التي هدَّت من كواهِلِهم، حتى نَقموا عليه، فاندلعت الفوضى ضِدَّه، فقام أحدُ قُطَّاع الطرق الطامعين، وهو باجي السقا (ابن السقا) باستغلالِ الأحداث، فاستولى على كابل وفَّرَ المَلِكُ إلى قند"},{"id":5026,"era":"c14","t":"تحول مديرية الشؤون الخارجية إلى وزارة خارجية .","s":"توسَّعت اتصالاتُ المَلِك عبد العزيز الخارجية بعد ضَمِّه للحجازِ؛ فقد كان في جُدَّة عددٌ من القناصل الأجنبيَّةِ، فأنشأ مديريةَ الشؤون الخارجية 1344هـ وأسهم فيها الدكتور عبد الله الدملوجي (عراقي) ويوسف ياسين (سوري) وحافظ وهبة (مصري)، ثم في هذا العام تحوَّلت إلى وزارةٍ للخارجية، وأُسنِدَت إلى الأمير فيصل بن عبد العزيز، فصار نائبًا للملك في الحجاز ووزيرًا للخارجية، وفي تلك الفترة أقامت الدولةُ علاقاتٍ"},{"id":5027,"era":"c14","t":"مفاوضات عمر المختار مع الإيطاليين .","s":"أرغَمَ عُمَرُ المختار -الذي لمعَ نجمُه في جهاد الإيطاليين في برقة- الإيطاليِّينَ على الدخولِ معه في مُفاوضاتٍ، فكان في جملةِ شروطه: عدمُ تدخُّلِ الحكومة الإيطالية في أمورِ الدين الإسلامي، والاعترافُ باللغة العربية لغةً رسمية في دوائِرِ ودواوين الإدارة الإيطالية، والسماحُ بفتح المدارسِ الدينية التي تُدرَّس فيها علومُ القرآن، والتفسير والحديث والفقه وسائر العلوم. وكذلك إلغاءُ القانون الذي وضعته إيطا"},{"id":5028,"era":"c14","t":"جرائم الاحتلال الإيطالي بالليبيين .","s":"أرادت إيطاليا إقامةَ مملكةٍ لاتينية في ليبيا؛ لإعادتها كما كانت في عهدِ الرومان، ولتأمينِ استيطانِ ثلاثة ملايين إيطالي فيها؛ ومن أجل ذلك: (أقدَمَ الإيطاليون على ارتكابِ آلافِ المجازر الوحشيَّة بدون مُوجِبٍ سوى الانتقامِ مِن المسلمين واستئصالِ شأفتِهم من طرابلس وبرقة، ولَمَّا كانت أراضي الجبل الأخضر من برقة هي أجودَ قطعةٍ مِن برِّ طرابلس، وفيها المياه الجاريةُ، والعيونُ الصافية، والغاباتُ الملتَفَّ"},{"id":5029,"era":"c14","t":"تمرد الإخوان  (إخوان من أطاع الله) مرة أخرى بعد السبلة .","s":"ما إن اندملت جراحُ الدويش بعد موقعة السبلة وهو في الأرطاوية، وجاءته أخبار الإخوان في تجمُّعِهم بالوفرة جنوب الكويت، فتناسى عهده للملك عبد العزيز فخرج بمطير إلى الوفرة واشتَدَّ ساعده بنايف بن حثلين (الملقَّب بأبي الكلاب) فولوا فيصلَا رئاستهم، ولما تسامعت مطير وغيرها بانتفاضة الدويش وتزعُّمه الحركة أقبلوا إليه، فأخذ الدويشُ يشنُّ الغارات على نجد، ويقطع السبل، واستنفر القبائِلَ لنُصرتِه، وكانت لفيصل "},{"id":5030,"era":"c14","t":"تأسيس الوكالة اليهودية العالمية .","s":"في عام 1907 أنشأ الحزبُ اليهوديُّ مُنظَّمةً عَسكريَّةً من اليهود الأوروبيين تسمَّى (بارجيورا) ثم تأسَّست الوكالة اليهودية عام 1923 بقرارٍ من المؤتمر الصهيوني الثالث عشر، وهي الوكالةُ التي أخذت على عاتِقِها تنشيطَ هِجرةِ اليهود من جميع أنحاء العالم إلى فلسطين بشتى الوسائل. وهي منظَّمةٌ يهودية صهيونية أقيمَت بمبادرةٍ مِن بنيامين زئيف هرتزل في المؤتمر الصهيوني الأول، الذي انعقد في بازل عام 1897م بصفت"},{"id":5031,"era":"c14","t":"ثورة حائط البراق (حائط المبكى) في فلسطين .","s":"اندلعت في فلسطينَ ثورةٌ مَعروفةٌ باسم حائط البراق في 15 أغسطس من هذا العامِ، لكِنَّ إرهاصاتها تعودُ إلى نحو 12 شهرًا سابقة على هذا التاريخ مع وقوعِ عَدَدٍ من المواجهات بين الفلسطينيين واليهود في القدس؛ بسبب حائط البُراق -الحائط الغربي للمسجد الأقصى- الذي أطلق عليه اليهودُ اسمَ حائط المَبكى، وذلك بعد أن انعقد المؤتمرُ الصهيوني العالمي في السادس عشر في مدينة زيورخ السويسرية في صيف 1928م، وخرج \"الحزب"},{"id":5032,"era":"c14","t":"اجتماع قرية الشعراء مع الملك عبد العزيز .","s":"دعا الملِكُ عبد العزيز ذوي الرأيِ من شيوخ وقادة القبائل إلى اجتماعٍ في قرية الشعراء، وطلب منهم أن يأتوه بآرائِهم وآراءِ قبائلهم في شأنِ المتمَرِّدين من الإخوان (إخوان من طاع الله)، وفي اليوم التالي انعقد الاجتماعُ واتفقوا على عددٍ مِن المقررات، منها: 1/ كل من شارك في الفتنة وبقي حيًّا يؤخذ مالُه ورِكابُه وسلاحُه وتحكَّمُ الشريعة في رقبته. 2/ كل من كان متهمًا بممالأة أهل الفساد ولم يجاهِدْ مع المسل"},{"id":5033,"era":"c14","t":"تسليم الإنجليز زعماء الإخوان (إخوان من أطاع الله) للملك عبد العزيز .","s":"تمكن الملك عبد العزيز بعد اجتماع الشعراء أن يُلحِقَ بالإخوان هزائِمَ مُتلاحِقةً حتى فرَّ الدويش ونايف بن حثلين إلى الكويت، كما هرب أعدادٌ من الإخوان إلى داخل الحدود العراقية خوفًا وهربًا من ابن سعود الذي أرسل إلى ديكسون الوكيل السياسي في الكويت يحتَجُّ على السماح للإخوان باللجوء إلى العراق والكويت وشرق الأردن، فأجابه بأنَّه سيعيدهم إلى نجدٍ، وفي 9 شعبان نُقِلَ زعماء الإخوان الثلاثة: فيصل الدويش، و"},{"id":5034,"era":"c14","t":"معاهدة صداقة وحسن جوار بين ملكي الحجاز والعراق .","s":"بعد أن قضى الملك عبد العزيز على حركة الإخوان (إخوان من أطاع الله) وتسَلَّم زعماءَهم عَقَد معاهدةَ صداقة وحُسْن جوار مع الملك فيصل بن الحسين ملك العراق؛ حيث التقى الاثنان مع المندوب السامي البريطاني في العراق همفرز، ودام اللقاءُ ثلاثة أيام، واتفقا على معاهدة صداقة وحُسْن جوار، ووُقِّعَت بعد أسابيع، وتبادَلَ المَلِكان الاعترافَ بدولتيهما ونسيان ماضي الصراع الهاشمي السعودي في الحجاز، وتم تبادل المندو"},{"id":5035,"era":"c14","t":"عودة البحث عن النفط بين السعودية والشركات الأمريكية .","s":"كان البريطانيون قد سبقوا الأمريكانَ إلى التنقيبِ عن النفطِ في غرب الخليج العربي. ولم تُسفِرْ بحوثُهم عن نتيجةٍ، فكتبوا إلى السلطان عبد العزيز يأسَفون على ما أضاعوا من جهدٍ ومالٍ، وانصرفوا عن البحثِ، ولَمَّا كان وزير الخارجية الأمير فيصل يزور لندن على رأس بَعثةٍ سياسية تحدَّثَ مع الجهاتِ البريطانية في احتمالِ وجودِ النِّفطِ على الشاطئ الغربي للخليج العربي، فلم يجِدْ في الشركات البريطانية استعدادًا "},{"id":5036,"era":"c14","t":"تعيين إسماعيل صدقي باشا رئيسًا للوزراء في مصر .","s":"أصدر الملك فؤاد الأول قرارًا بتعيين إسماعيل صدقي باشا رئيسًا للوزراء خلفًا لمصطفى النحاس باشا، وكان الملك فؤاد يرى في صدقي رجلَ إدارة وحسم، قادرًا على حلِّ المشكلات التي تعصِفُ بالبلاد، فأُلغي دستور 1923 وأصدر دستور 1930."},{"id":5037,"era":"c14","t":"معاهدة التحالف الوثيق بين العراق وبريطانيا .","s":"كانت المعاهدةُ قد طُرِحَت سابقًا لكِنْ لم يتمَّ التوقيعُ عليها بسبب بُعدِ الشروط فيها، فكانت كلُّ وزارة تتغيَّرُ ولا يحدث أي توقيع للمعاهدة، حتى شُكِّلت لجنةٌ لمفاوضة الجهة البريطانية التي يمثِّلُها المعتمد السامي البريطاني، وقد وجدت ثلاث نقاط يجب بحثُها، وهي: تعديل الاتفاقية المالية والعسكرية؛ حيث كان هناك اعتراض على قوة الطيران البريطانية الموجودة بالعراق، وقضيةُ التجنيد الإلزامي، وامتلاك ميناء "},{"id":5038,"era":"c14","t":"صدور دستور جديد للبلاد في مصر .","s":"شهد عام 1930 إلغاءَ دستور 1923م ثم إصدارَ دستور جديد للبلاد في وزارة إسماعيل صدقي باشا رئيس الوزراء، واستمَرَّ العمل به لمدة خمس سنوات، ثم عادت البلادُ مرة أخرى إلى دستور عام 1923، وذلك في عام 1935."},{"id":5039,"era":"c14","t":"معارك واحة الكفرة الليبية آخر معاقل السنوسيين واحتلال القوات الإيطالية لها. .","s":"وقعت هذه المعركة في يناير 1931م بعد ما أمضى الإيطاليون ستة أشهر وهم يعدُّون جيشًا قويًّا من أجل الزحف على مناطق الكفرة جنوب شرق ليبيا. وبعد إتمام تجهيز هذه القوة عَمَد قائدها إلى إطلاقها من عدةِ أماكن؛ فقد انطلقت القوة الرئيسية من أجدابيا شرق ليبيا في 20 ديسمبر 1930م عبر أوجلة جنوب بنغازي، والقوة الثانية انطلقت من زلة عبر تازربو، وانطلقت قوة ثالثة مسانِدة من الوادي الكبير، بلغ إجمالي هذه القوات ال"},{"id":5040,"era":"c14","t":"تأسيس جمعية العلماء المسلمين في الجزائر .","s":"بقي الاستعمارُ الفرنسي في الجزائر قائمًا، وأخذ أشكالًا جديدة، فبدأ ينشر الجهلَ، ويحارب اللغة العربية، وينشر الرذيلة والفواحش بين المسلمين، ولكِنْ أبقى الله في الأمة بقيةً تأمر بالمعروف وتنهى عن المنكر، فكان من المصلحين الشيخ عبد الحميد بن باديس الذي كان يُلقي دروسًا في التفسير في مسجد سيدي الأخضر بقسنطينة، والتفَّ حوله الكثير واشتد ساعده، وقام بدعوة العلماء لتوحيد الكلمة، فحضر 190 من علماء الجزائر"},{"id":5041,"era":"c14","t":"وفاة فيصل الدويش زعيم قبيلة مطير .","s":"هو فيصلُ بنُ سلطان بن فيصل بن نايف الدويش من أواخِر شيوخِ مطير، ومِن كبارِ أصحابِ الثورات في نجدٍ ضِدَّ الملك عبد العزيز. وهو من بني الدويش، ويقالُ لهم: الدُّوشان من بني علوة أصحابِ الرياسة في مطير، تمتَدُّ منازِلُ مطير من الصمَّان غربيَّ الأحساءِ إلى سهولِ الدبدبة فالقصيم فأطراف الحجاز، وكان فيصل بدويًّا قُحًّا، فيه شراسةٌ ودهاءٌ واعتزازٌ بعددِه الضخم. قام بزعامة مطير بعد أبيه. وكان لطبيعتِه البد"},{"id":5042,"era":"c14","t":"قتل عمر المختار قائد الكفاح الليبي ضد الاحتلال الإيطالي .","s":"هو الشيخُ المجاهِدُ عُمَرُ بنُ مختار بن عمر المنفي، نسبةً إلى قبيلة منفة في بادية برقة بليبيا، تعلم في الزوايا السنوسية، وجعله محمد المهدي السنوسي شيخًا على زاوية القصور بالجبل الأخضر، خرج لجهادِ الطليان بعد أن احتلُّوا مدينة بنغازي عام 1329هـ وصَمَد للعدو صمودًا منقَطِعَ النظير جعَلَه في أوائل الأبطال في الجهاد الليبي ضِدَّ الطليان، كانت منطقة المختار برقة ثابتةً منيعةً. وتهادن الإيطاليون والطراب"},{"id":5043,"era":"c14","t":"انعقاد المؤتمر الإسلامي الأول .","s":"لما رأى الحاج أمين الحسيني انحياز الإنجليز مع اليهود، لجأَ إلى قوة العالم الإسلامي؛ حيث دعا إلى عقد مؤتمر إسلامي رسمي في القُدس؛ ليُشعِرَ سلطات الانتداب بأنَّ عَرَبَ فلسطين ليسوا وحدهم، فهناك الملايين من العرب والمسلمين يساندونَهم. وافتتح المؤتمر الإسلامي الأول رسميًّا يوم الإسراء 7/12/1931، حضره حشدٌ كبير من العلماء والشخصيات السياسية، من أمثال الشيخ رشيد رضا، وعبد العزيز الثعالبي، وضياء الدين ال"},{"id":5044,"era":"c14","t":"استقلال العراق بموجب معاهدة مع بريطانيا 1927م .","s":"في الثالث من أكتوبر تمَّ إعلانُ استقلال العراق ودخولُه عصبة الأمم بموجِبِ المعاهدة البريطانية العراقية 1922م، التي تم تصديقها 1924م، ثم تعديلها عام 1927م، وتصديقُها من قِبَل مجلس الوزراء سنة 1930م إلا أنَّ الاستقلال لم يكن مكتَمِلًا؛ لأنَّ المعاهدة التي وُضِعَت له كان الغرضُ منها وضْعَ صيغة بديلة عن صَكِّ الانتداب، وقد واجهت معارضةً من الشعب العراقي ومقاومةً مسلحة. بموجِبِ هذه المعاهدة يعتبر العرا"},{"id":5045,"era":"c14","t":"ثورة ابن رفادة في شمال الحجاز .","s":"آلُ رِفادةَ هم شُيوخُ قَبيلةِ بَلِيٍّ من قُضاعةَ اليَمانِيَةِ مِن سُكَّانِ شَمالِ الحِجازِ، كان حامِدُ بنُ سالِمِ بنِ رِفادةَ البَلَويُّ أحَدَ شُيوخِ قَبيلةِ بَلِيٍّ ومِن فُرْسَانِها المشهورينَ، ومَعروفٌ بحامِدٍ العورِ، وكانت له صَولاتٌ وجَولاتٌ في المنطقةِ، وله كَلِمةٌ مَسموعةٌ وثِقلٌ كَبيرٌ وإن لم تكُنْ له رِئاسةُ قَبيلةِ بَلِيٍّ، كانت علاقَتُه بالأشرافِ قَوِيَّةً ومِن الموالِينَ لهم، وبعد دُخول"},{"id":5046,"era":"c14","t":"إعلان توحيد المملكة العربية السعودية .","s":"استعاد المَلِكُ عبد العزيز الرياضَ من آل رشيد سنة 1319هـ، ثمَّ ضم إليها الخرجَ والأفلاج وبلاد نجد وما حولها، ثم ضم عنيزة وبريدة في معركة روضة مهنا، والأحساء وبقية المنطقة الشرقية، وانتزع حائل من آل رشيد، وضم عسير وقضى على آل عايض، وضم الحجاز وقضى على حُكم الأشراف نهائيًّا، وضم تهامة عسير المقاطعة الإدريسية، ثم في 21 جمادى الأولى من هذا العام 1351هـ الموافق 22 أيلول / سبتمبر 1932م صدر مرسومٌ مَلكيّ"},{"id":5047,"era":"c14","t":"وفاة أمير الشعراء أحمد شوقي .","s":"هو أحمد شوقي بن علي بن أحمد شوقي، أميرُ الشعراء، ولد بالقاهرة سنة 1285 ونشأ بها، أمَّا أصلُه فأبوه تركي، وأمُّه يونانية. يقول شوقي عن نفسه: إني عربي، تركي، يوناني، جركسي، أصولٌ أربعة في فروع مجتمعة، تكفلها له مصر، وقد سمع أباه يردُّه إلى الأكراد فالعرب، ويقول: إنَّ والده قَدِمَ هذه الديار يافعًا يحمِلُ وصاةً من أحمد باشا الجزار إلى والي مصر محمد على باشا، فأدخَلَه في معيَّتِه، وظَلَّ يتقَلَّبُ في "},{"id":5048,"era":"c14","t":"تأسيس مجمع اللغة العربية بمصر .","s":"تأسَّس مجمع اللغة العربية بالقاهرة عام 1351هـ، وبدأ العمل فيه سنة 1353هـ. وقد رأَسَه محمد توفيق رفعت، ثم أحمد لطفي السيد، ثم الدكتور طه حسين، ثم الدكتور إبراهيم مدكور، ثم الدكتور شوقي ضيف. وقد نَصَّ مرسومُ إنشاء مجمع اللغة العربية الذي أصدره الملك فؤاد الأول عام 1932م على أن يتكوَّنَ المَجمَع من 20 عضوًا من العلماء المعروفين بتبحُّرِهم في اللغة العربية، نصفُهم من المصريين، ونصفُهم الآخر من العرب و"},{"id":5049,"era":"c14","t":"وفاة الملك محمد نادر شاه الأفغان وتولي ابنه محمد ظاهر .","s":"هو الملِكُ محمد نادر شاه بن محمد يوسف خان بن محمد يحيى خان؛ شاه أفغانستان. وكان جده الأكبر سلطان محمد خان شقيق الأمير دوست محمد خان؛ المؤسس الأوَّل لأسرة البركزاية في أفغانستان، وهو الذي باع بيشاور إلى السيخ. ولِدَ محمد نادر في ديرادون شمال الهند سنة 1883م. دخل نادر أفغانستان في سن 18 عندما سُمِحَ لجده يحيى خان بالعودة من المنفى، وفي عهد أمان الله خان دخل نادر شاه العسكريةَ سنة 1919م، وشارك في حرب"},{"id":5050,"era":"c14","t":"وفاة الشيخ إبراهيم بن محمد آل خليفة شيخ الأدباء في البحرين .","s":"هو الشيخ إبراهيم بن محمد بن خليفة بن سليمان آل خليفة: شيخ الأدباء في البحرين. وُلِدَ الشيخ إبراهيم بالبحرين عام 1267هـ / 1850م، وتربَّى في بيت ميسور الحال؛ فقد كان والده الشيخ محمد بن خليفة الحاكِمَ الرابع للبحرين؛ حيث عَهِدَ بتربيته إلى بعض عُلَماء نجد، فبرع باللغة العربية وآدابها، فكان من أوائل روَّاد النهضة في البحرين، وراعيَ حركتِها الأدبية والثقافية، وأحدَ رجال الإصلاح والتجديد الذين كانت لهم"},{"id":5051,"era":"c14","t":"اكتشاف النفط في المملكة العربية السعودية .","s":"في عهد الملك عبد العزيز وقَّعت الحكومةُ السعودية اتفاقيةً مع شركة سوكال التي عُرِفَت فيما بعد باسم شركة الزيت العربية الأمريكية، أو أرامكو، للتنقيبِ عن الزيتِ، وبدأ البحثُ في إقليم الأحساء في النطاق الممتَدِّ من صحراء الدهناء إلى ساحل الخليج العربي، وظهر أولُ بئر في الدمام عام 1354هـ / 1935م، ولكن كميةَ الإنتاج كانت قليلةً، واستمَرَّ الحفر والتنقيب إلى أن عُثِرَ على آبار أخرى غنية استُخرِجَ منها ا"},{"id":5052,"era":"c14","t":"صدور قرار ولاية العهد بعد الملك عبد العزيز .","s":"أمَرَ الملِكُ عبد العزيز بوضعِ نظامٍ لتولية العرش مِن بعدِه، فانعقد مجلِسَا الوكلاء والشورى، وأبرمَا قرارًا في 16 محرم 1352هـ الموافق 11/ 5 / 1933م بمبايعةِ كبير أبنائه الأمير سعود وليًّا للعهد،ثم أبرق الملِكُ على الأثرِ إلى سعود برقيةً جاء فيه: \" تفهَمُ أنَّنا نحن والناس جميعًا ما نُعِز أحدًا ولا نذِلُّ أحدًا، وإنما المعِزُّ والمذِلُّ اللهُ هو سبحانه وتعالى، ومن التجأ إليه نجا، ومن اغتَرَّ بغيره "},{"id":5053,"era":"c14","t":"عقد تنقيب النفط في السعودية مع شركة سوكال .","s":"على الرغمِ من الجُهودِ المُضنية والإغراءاتِ المتعَدِّدة التي بذلَتْها الحكومةُ البريطانية؛ من أجل حصولِ الشركات البريطانية على حقِّ امتياز التنقيبِ عن النفط إلَّا أن الملك عبد العزيز كان يدفَعُ المفاوضات باتجاه الشركات الأمريكية؛ وذلك للتخَلُّصِ من سيطرة وتحكُّم الحكومة البريطانية في الجانبِ الاقتصادي في بلادِه؛ ولذلك مَنَح إحدى الشركاتِ الأمريكية، وهي شركة سوكال \"ستاندر أويل أوف كاليفورنيا\" حقًّا"},{"id":5054,"era":"c14","t":"حل فرنسا الحزب الحر الدستوري التونسي .","s":"أعلن المقيمُ العامُّ الفرنسيُّ في تونس حَلَّ الحزبِ الحُرِّ الدستوري التونسي الذي استقى مبادِئَه من كتاب \"تونس الشهيدة\" لعبد العزيز الثعالبي. وكان من مطالِبِ الحزب: إرساءُ نظامٍ دستوريٍّ بتونس، والفَصلُ بين السلطات الثلاث, وضمانُ الحريات والمساواة, وإجبارية التعليم."},{"id":5055,"era":"c14","t":"الحركة الآشورية في العراق .","s":"كان الآشوريون -وهم نصارى نساطرة- يقيمون في ولاية \"وان\" شرقيَّ الأناضول، وعاشوا تحت ظِلِّ الدولة الإسلامية آمنينَ على دمائِهم وأعراضِهم وأموالِهم، فلما اندلعت الحربُ العالمية الأولى، واستولى الروسُ على \"وان\" أغرَوا الآشوريِّينَ بالتمَرُّد على العثمانيين، وأمدُّوهم بالمالِ والسلاح، ولَمَّا انسحبت روسيا من \"وان\" بعد قيام الشيوعيَّةِ وجدت الدولةُ العثمانيةُ نفسَها مضطرةً للفَتكِ بهم؛ لِمَا أظهَروه من "},{"id":5056,"era":"c14","t":"وفاة الملك فيصل بن الحسين ملك العراق وتنصيب ابنه غازي .","s":"هو المَلِكُ فيصل الأوَّلُ بن الحسين بن علي الحسني الهاشمي، أبو غازي ملك العراق. ولِدَ بالطائف سنة 1300هـ، وترعرع في خيام بنى عتيبة في بادية الحجاز. ورحل مع أبيه حين أُبعِدَ إلى الأستانة سنة 1308هـ، وعاد معه سنة 1327هـ، واختير نائبًا عن مدينة جدة في مجلس النواب العثماني سنة 1913م، فأخذ ينتقِلُ بين الحجاز والأستانة. زار دمشق سنة 1916م، وأقسم يمين الإخلاص لجمعية \"العربية الفتاة\" السرية. ولَمَّا ثار و"},{"id":5057,"era":"c14","t":"قيام جمهورية إسلامية في تركستان الشرقية .","s":"قامت ثورةٌ عارمة في تركستان الشرقية ضِدَّ الصين سنة 1350هـ / 1931م كان سببُها تقسيمَ الحاكم الصيني المنطقةَ التي يحكمها \"شاكر بك\" إلى وحداتٍ إدارية، فبدأ التذمُّر، ثم وقع اعتداءٌ على امرأةٍ مسلمة من قِبَل رئيس الشرطة، فامتلأ الناسُ غيظًا وحِقدًا على الصينيين، وتظاهروا بإقامة حفلٍ على شَرفِ رئيس الشرطة وقَتَلوه أثناء الحَفلِ مع حرَّاسه البالغ عددُهم اثنين وثلاثين جنديًّا. وقد كانت ثورةً عنيفة، اعتص"},{"id":5058,"era":"c14","t":"افتتاح الخط الحديدي بين مراكش وتونس .","s":"افتُتِحَ الخَطُّ الحديدي بين مراكش وتونس، وهو الخط الذي يربط بين الممتلكات الفرنسية، ويمكِّنُها من إرسال قوات من تونس إلى موانئ مراكش الواقعة على المحيط الأطلسي، وبذلك تتفادى طريق البحر المتوسط المحفوف بالأخطار."},{"id":5059,"era":"c14","t":"الحرب اليمنية السعودية  .","s":"قامت في اليمن حركةٌ بقيادة الإمام يحيى حميد الدين واجه فيها الدولةَ العثمانية التي انسحبت من اليمن في أعقاب الحرب العالمية الأولى فصفا له الجوُّ فيها. ويفصل بينه وبين مُلك الملك عبدالعزيز إمارة آل عائض في أبها، وإمارة آل إدريس في جازان، وقد قامت فيهما فِتَنٌ وأحداث انتهت بانضمامِهما إلى حكم الملك عبدالعزيز، وقد لجأ الحسَنُ الإدريسي وجمَعَ من أقاربه وخاصته إلى اليمن في ضيافة الإمام يحيى، وكان الملك"},{"id":5060,"era":"c14","t":"موازنة الدولة في عهد الملك عبد العزيز ونموها .","s":"كان خُمسُ الغنائم التي تحصُلُ عليها الدولة من الحروب التي حدثت في أيام تأسيس الدولة وتوحيد الجزيرة تشَكِّلُ جزءًا من إيرادات الدولة، وفي عام 1344ه أصدر الملك عبد العزيز مرسومًا يحدِّدُ مقادير الزكاة الشرعية، وطرق جبايتها، وكلَّف أمراءَ المقاطعات بالإشراف على استيفائها، وبعد ضَمِّ السواحل الشرقية للجزيرة العربية فَرَض رسومًا جمركية، ومع ذلك ظلت موارد الدولة فقيرةً مقابِلَ احتياجات الدولة لتمويل الع"},{"id":5061,"era":"c14","t":"هجرة اليهود إلى فلسطين ووصول اثنين وأربعين ألف يهودي .","s":"منذ أواسط القرن التاسع عشر الميلادي كان لليهود محاولات للتسلُّل إلى فلسطين، وعندما عَلِمَ سلاطين الدولة العثمانية وضعوا قوانين صارمة لمنع مثل هذه التسلُّلات، وعاش من كان في فلسطين كأقليةٍ تعتمد على المعونات الخارجية، ثم بعد اضطهاد قيصر روسيا لليهود بسبب محاولتِهم اغتيالَه بدأ قسم كبيرٌ منهم بالهجرة إلى فلسطين، فقَدِمَ الفوجُ الأول إلى فلسطين سنة 1823م وأنشؤوا بعض المستوطنات بين يافا والقدس، لكِنَّ"},{"id":5062,"era":"c14","t":"وفاة ليج أياسو إمبراطور الحبشة المسلم .","s":"هو ليج أياسو بن محمد علي إمبراطور الحبشة المسلم. في أواخِرِ القرن التاسع عشر الميلادي قام إمبراطورُ الحبشة منليك الثاني النصراني بدعمٍ وتحريضٍ من أوروبا الاستعمارية بشَنِّ حملة كبيرة على الإمارات الإسلامية التي كانت تقوم على معظم أراضي الحبشة، فنجح في احتلالِ مدينة هرر عاصمة إمارة هرر المسلمة، وتساقطت بعدها بقيةُ الإمارات المسلمة التي كانت متفرقةً وضعيفة، ثم زوَّج إمبراطور الحبشة منليك ابنته إلى م"},{"id":5063,"era":"c14","t":"سفر الأمير فاروق ابن الملك فؤاد للدراسة في بريطانيا .","s":"لَمَّا بلغ الأمير فاروق سن الرابعة عشرة طلب السير مايلز لامبسون من الملك فؤاد ضرورةَ سفر ابنه الأمير فاروق إلى بريطانيا لمواصلةِ الدراسة وأصَرَّ على ذلك بشدة رافضًا أيَّ محاولة من الملك فؤاد لتأجيل سفره حتى يبلغ سن السادسة عشرة، فتقرَّر سفرُ فاروق إلى بريطانيا ولكن دون أن يلتحِقَ بكلية إيتون، بل تم َّإلحاقه بكلية وولتش للعلوم العسكرية؛ ونظرًا لكونه لم يبلغ الثامنة عشرة -وهو أحد شروط الالتحاق بكلية"},{"id":5064,"era":"c14","t":"معاهدة الطائف بين اليمن والسعودية .","s":"بعد أن توقَّف زحفُ الجيش السعودي على اليمن بقيادة الأمير سعود والأمير فيصل، استدعى الملكُ عبد العزيز عبدَ اللهِ ابنَ الوزير إلى الطائِفِ، وأطلَعَه على برقية الإمام يحيى -التي أرسلها بعد انهيار قوات جيشه- ثمَّ أملى الملك عبد العزيز على ابن الوزير ومن حضر من المستشارين السعوديين فقراتٍ أشبَهَ بالمواد التي تُبنى عليها معاهدةٌ للصلح، فتولى المستشارون وابن الوزير صياغتَها، فكانت معاهدة الطائف، ثم جرى ت"},{"id":5065,"era":"c14","t":"أمر أتاتورك بإيقاف الصلاة في جامع آيا صوفيا .","s":"أصدرت الحكومةُ التركيةُ برئاسة مصطفى كمال أتاتورك قراراً حكوميًّا بتوقف الصلاة في جامع آيا صوفيا، ونَزعِ سجاجيده، ومنبره، ولوحاته المكتوبة باللغة العربية، وتحويلِه إلى متحف سياحي!!"},{"id":5066,"era":"c14","t":"محاولة الاعتداء على الملك عبد العزيز في الحرم (حادث المطاف) .","s":"في صباح يوم النحر بينما كان الملك عبد العزيز يطوف طوافَ الإفاضةِ كعادته كلَّ سنةٍ في هذا الوقتِ مع قِلَّةٍ مِن الحُجَّاج، وخلفه ابنه الأمير سعود وبعض رجاله، وبعد استلامِه الحجرَ الأسود في بداية الشوط الخامس هجم عليه رجلٌ من فجوةٍ في الحِجْر عليه بَزَّة يمانية، وقد سَلَّ خِنجَرَه وهو يصيح صيحاتٍ مُنكرةً وانقض على المَلِك من ورائِه لِيطعَنَه بالخنجر فألقى سعود نفسَه على أبيه ودفع الرجلَ بيده الذي أط"},{"id":5067,"era":"c14","t":"وفاة الشيخ محمد رشيد رضا .","s":"هو الشيخُ محمد رشيد بن علي رضا بن محمد شمس الدين بن محمد بَهاء الدين بن منلا علي خليفة القلموني؛ البغدادي الأصل، الحسيني النَّسَب (على خلاف في صحة نسبه لآل البيت)، وهو أحَدُ رجال الإصلاح الديني في العصر الحديث. كان متعَدِّدَ الجوانب والمواهب، فكان مفكِّرًا إسلاميًّا غيورًا على دينه، وصحفيًّا نابهًا، وكاتبًا بليغًا في كثير من الصحف، ومفسرًا نابغًا، ومحدثًا مُتقِنًا في طليعة محدثي العصر، وأديبًا لغو"},{"id":5068,"era":"c14","t":"وفاة القائد السوري \"إبراهيم هنانو\" .","s":"القائدُ السوري \"إبراهيم بن سليمان بن أغا هنانو\" المعروف بـ\"إبراهيم هنانو\". قاد حركةَ الجهاد ضِدَّ المحتَلِّ الفرنسي بعد معركة \"ميسلون\". ولِدَ في حلب 1286هـ / 1869م، وتلقَّى تعليمَه في تركيا، وعَمِلَ في الوظائف الإدارية بسوريا. لَمَّا احتَلَّ الفرنسيون مدينةَ أنطاكية انتُدِبَ لتأليف عصابات عربية تُشاغِلُ الفرنسيين، وجعل مقَرَّه في حلب، وفوجِئَت سورية بنكبة ميسلون سنة 1338هـ، واحتلال الفرنسيين دمشق "},{"id":5069,"era":"c14","t":"فوز حزب الوفد بأغلبية مقاعد مجلس النواب في مصر .","s":"فاز حزبُ الوفدِ بأغلبية مقاعِدِ مجلس النواب في الانتخابات التي أُجريت في البلاد، وقام مصطفى النحاس باشا رئيسُ حزب الوفد بتشكيلِ وزارة وفدية تمكَّنَت من عقد مفاوضات بين مصر وبريطانيا، فنتج عن تلك المفاوضات معاهدة 1936م."},{"id":5070,"era":"c14","t":"الاتحاد السوفيتي يعلن عن قيام جمهورية قيرغيزيا ويضمها إلى امبراطوريته .","s":"بدأ الاستعمارُ الروسيُّ في فيرغيزيا عام 1866م، وقد أدَّى الاحتلالُ الروسي لقيرغيزيا إلى تناقُصِ عَدَدِ القيرغيز؛ بسبب الثوراتِ، والهروب من البلاد، والموت جوعًا، وحرب الإبادة التي مارسها الروسُ ضِدَّ القيرغيز؛ ففي سنة 1916م قامت ثورة قُتِلَ فيها 150 ألف قيرغيزي، ومات جوعًا من القيرغيز أثناء هربهم إلى الصين -إبَّان طغيان الحكم الشيوعي والسيطرة الروسية من قَبلُ- عشرات الآلاف، وأثناء الحكم الشيوعي منذ"},{"id":5071,"era":"c14","t":"معاهدة 1936 المصرية البريطانية (معاهدة الشرف والاستقلال) .","s":"وقَّع مصطفى النحاس -وهو رئيس الوزراء- ووزير الداخلية، ووزير الصحة: المعاهدةَ مع إنجلترا والتي عُرِفَت بمعاهدة 1936 وتنُصُّ على إنهاء الاحتلال العسكري والوصاية البريطانية، مع استثناء بعض القواعد العسكرية للدفاع عن وادي النيل وقناة السويس ضِدَّ أي عدوان خارجي، ووضْع الأراضي المصرية وطرق مواصلاتها ومطاراتها وموانيها تحت تصرُّف الجيش البريطاني في حالةِ قيام حرب، وتخلِّي إنجلترا عن المصالح الأجنبية، وت"},{"id":5072,"era":"c14","t":"معاهدة 1936 السورية - الفرنسية  .","s":"بعد أن رأى الكثيرُ من السوريين أنَّ الكفاحَ المسلَّحَ لا يتكافأُ مع القوات الفرنسية لجؤوا إلى الكفاح الدبلوماسيِّ، فبدأت تظهَرُ الكتلة الوطنية والجمعية التأسيسية التي دعت لوضع دستورٍ للبلاد، وعمَلِ انتخابات نيابية حُرَّة، وإلغاءِ الأحكام العرفية، ثم حصلت تطوراتٌ في إصدار دساتير عديدة، أحدها لدولة سوريا، وآخر لدولة العلويين في اللاذقية، وثالث للدروز، ثمَّ حُلَّت الحكومة المؤقتة، وعملت انتخابات جديد"},{"id":5073,"era":"c14","t":"الثورة الفلسطينية الكبرى 1936م .","s":"تعتَبرُ الثورة الفلسطينية الكبرى في عام 1936م من أشَدِّ الثورات على اليهود وأعوانهم الإنجليز، وكانت ذاتَ طابَعٍ إسلامي واضِحٍ، وتركَّزت العمليات في شمالي فلسطين ولواء نابلس؛ حيث إن جماعة عز الدين القسَّام كان وجودها مكثفًا هناك، فقاموا باغتيال الحاكم البريطاني لمنطقة الجليل \"أندروز\"، وكان فوزي القاوقجي هو قائد عام الثورة، وتولَّى منطقة القدس عبد القادر الحسيني الذي قُتِلَ في معركة القسطل، واشتعلت "},{"id":5074,"era":"c14","t":"إصدار الحكومة الفرنسية قرارًا باعتبار اللغة العربية لغة أجنبية في الجزائر .","s":"أصدرت الحكومةُ الفرنسيةُ قرارًا باعتبارِ اللغة العربية لغةً أجنبية في الجزائر! ويأتي هذا القانونُ في سلسلة قوانينَ سَنَّها الاحتلال الفرنسي لمحاربةِ اللغة العربية، وفَرْنَسة الشعب الجزائري، وتسَبَّبت هذه القوانين في زحزحة اللغة العربية واحتلال اللغة الفرنسية لمكانةٍ متميزة في الإدارةِ والحُكمِ في الجزائر!"},{"id":5075,"era":"c14","t":"وفاة أحمد فؤاد ملك مصر وتولي الملك فاروق .","s":"هو المَلِكُ أحمد فؤاد الأوَّل بن الخديوي إسماعيل بن إبراهيم بن محمد علي ملك مصر. مولده ووفاته بالقاهرة. تعلَّمَ بها، ثم في جنيف، ثم في المدرسة الحربية بتورينو إيطاليا، وتخرَّج ضابطًا في الجيش الإيطالي، وأُلحِقَ بالبلاط الملكي برومة، ورحل إلى الأستانة فعُيِّنَ ياورا فخريًّا للسلطان عبد الحميد، فمُلحَقًا حربيًّا للسفارة العثمانية بعاصمة النمسا، وعاد إلى مصر سنة 1892 فعُيِّن (ياورا) للخديوي عباس الثا"},{"id":5076,"era":"c14","t":"قتل بلاس إنفانتي الأندلسي لدفاعه عن المسلمين بأسبانيا .","s":"هو بلاس إنفانتي بيريث دي بارغاس رجلُ سياسة ومفكِّر وكاتب أندلسي، ويُعَدُّ أبا القومية الأندلسية الحديثة. ولِدَ سنة 1885م في بلدة قشريش بمقاطعة مالقة، ظهرت في أوائل القرن العشرين شخصيةُ بلاس إنفانتي الفَذَّة، الذي اعتنق الإسلام وعَمِلَ حَسَب طاقته في ذلك الحين على توعية المجتمع الأندلسي، وإزاحة الغشاء المظلِم الذي أنزله أعداؤه على تاريخِه وماضيه الإسلامي. تعرَّف بلاس إنفانتي إبَّان مُقامِه في غرناط"},{"id":5077,"era":"c14","t":"المعاهدة 1936 اللبنانية الفرنسية .","s":"خطَّطت فرنسا -بعد أن انتهت الثورةُ العربية الكبرى ضِدَّ العثمانيين- لما ستفعله في سوريا، فأول ما قامت به هو فَصلُ لبنان عن سوريا، وخاصة أن فيه كثيرًا من الموارنة النصارى، وقد سنَّت دستورًا خاصًّا للبنان الكبير، ومع أنَّ الدستور لم ينُصَّ على ديانة الرئيس إلَّا أن فرنسا كانت مصممة على ألَّا يليَ الرئاسة إلا نصراني، فعُيِّنَ أولًا شارل دباس، وحاول حبيب باشا السعد أن يجعل اللهجةَ العامية هي اللغة الر"},{"id":5078,"era":"c14","t":"قرارات لجنة بيل الملكية البريطانية ومشروع تقسيم فلسطين\n  .","s":"بعد أن قامت الثورةُ الفلسطينية الكبرى عام 1936م وعَمَّت كلَّ أرجاء فلسطين وتكَبَّد البريطانيون من ورائِها خسائرَ فادحةً: أرادوا أن يستغلُّوا هذه النقطةَ لصالِحِهم، فقاموا بتشكيلِ لجنةٍ برئاسة بيل، وهي ما تسمى باللجنة الملكية البريطانية؛ لدراسة أسباب الثورة، وكأن أسبابَها غامضةٌ تحتاج إلى دراسة، وكان الغرضُ الرئيس من هذه اللجنة وغيرها من اللجان امتصاصَ الثورة بظهور بريطانيا أمام العالم أنها مهتمَّة"},{"id":5079,"era":"c14","t":"ميثاق سعد آباد الذي ضم تركيا والعراق وإيران .","s":"في عام 1937م بدأت الظروفُ العالمية تُنذِرُ بنشوب الحرب العالمية الثانية فاتَّخَذت الدولُ الغربية بعضَ الاحتياطات ضِدَّ ألمانيا وإيطاليا واليابان والاتحاد السوفييتي، وكان من جملةِ التدابير المتَّخَذة عقد (ميثاق سعد آباد) في الثامن من يوليو عام 1937م في إيران، وساهم عقدُ هذا الميثاق في التقارب العراقي الإيراني، حيث عُقِدَت المعاهدة عام 1937بين العراق، تركيا، أفغانستان، وإيران تحت إشراف بريطانيا، ثم "},{"id":5080,"era":"c14","t":"معاهدة الصداقة بين العراق وإيران .","s":"بعد أن وُقِّع ميثاقُ سعد آباد بين كل من تركيا وأفغانستان والعراق وإيران في ربيع الثاني 1356هـ في هذا العام على ألَّا تتدخل أي دولة بشؤون الدول الأخرى الداخلية، وألَّا تتعدى عليها، ولا تعاوِن من يتعدى عليها، وما إلى ذلك، ثم وقِّعَت في 10 جمادى الأولى في العام نفسِه معاهدةُ صداقة دائمة لإقامة سِلمٍ دائم وصداقة لا تتغيَّرُ بين العراق وإيران، ووقِّعَت في طهران، ويتعهَّدُ الطرفان بأن يُعقَدَ بأسرعِ وقت"},{"id":5081,"era":"c14","t":"استيلاء الصينيين على تركستان الشرقية بمساعدة الروس. .","s":"تعرَّضت تركستان الشرقية لأربعِ غَزَوات صينية منذ عام 1277هـ / 1860م مرَّتين في عهد أسرة المانشو، ومرةً في عهد الصين الوطنية، ومرةً في عهد الصين الشيوعية. وقد أدت هذه الغزوات وما رافقها من مذابحَ صينيةٍ إلى إبادة كثير من المسلمين، وحدوثِ عِدَّةِ هِجرات من هذا الإقليم إلى المناطق المجاورة. وقد قامت ثورةٌ عارمة في تركستان الشرقية ضِدَّ الصين سنة 1350هـ / 1931م كان سببُها تقسيمَ الحاكم الصيني المنطقةَ"},{"id":5082,"era":"c14","t":"قيام الملك فاروق ملك مصر بحل مجلس النواب .","s":"بعد تولِّي الملِكِ فاروق عرشَ مصرَ قام بحل مجلسِ النواب الذي كان يتمتَّعُ فيه حِزبُ الوفد بأغلبية كبيرة، وكان الوفديُّون قد أحرزوا هذه الأغلبيةَ في الانتخابات التي أُجرِيَت في مايو 1936م، وكانت الحياةُ السياسية في مصر في تلك الفترة تعتَمِدُ على ثلاث قوى رئيسية فاعلة، هم: الإنجليز، والقصر، وحزب الوفد. قبل أن يدخُلَ الجيش إلى المعادَلةِ ويقلِبَ توازنات القوى فيها، جلس فاروق على العرش مع اهتزازِ وترا"},{"id":5083,"era":"c14","t":"وفاة الشاعر محمد إقبال .","s":"هو محمد إقبال ابنُ الشيخ نور محمد؛ الشاعر المعروف، ولِدَ في سيالكوت إحدى مدن البنجاب الغربية في الثالث من ذي القعدة 1294هـ الموافق 9 من نوفمبر 1877م. ينتمي محمد إقبال إلى أسرة هندوكية من البراهمة، وهي جماعةٌ لها شأنٌ كبير في الهند رغم أنَّها تعبُدُ الأصنامَ وتقَدِّسُ التماثيل، لكِنَّ أسرة محمد إقبال تنازلت عن كلِّ هذه العظمة؛ لتدخُلَ في دين الإسلام في عهدِ السلطان زين العابدين بادشاه 1421 - 1473م،"},{"id":5084,"era":"c14","t":"وفاة مصطفى كمال أتاتورك رئيس الجمهورية التركية .","s":"هو مصطفى كمال أتاتورك الملقَّب بالغازي؛ رئيس الجهورية التركية، وكلمة أتاتورك، تعني: أبو الأتراك، وهو الذى أسقط الخلافةَ الإسلاميةَ سنة 1343ه / 1924م. ولِدَ مصطفى كمال عام 1296هـ في مدينة سالونيك اليونانية وكانت تابعة للدولة العثمانية، من أمٍّ تدعى زبيدة، ونُسِبَ في بداية الأمر إلى زوج أمه علي رضا الذي لم يلبث أن توفِّي، ولم يتجاوز ربيبُه مصطفى الثامنةَ من العمر، وكانت زبيدة مُستهترة، وتمكَّنَت من "},{"id":5085,"era":"c14","t":"فرنسا تعطي لواء إسكندرون السوري لتركيا .","s":"كان لواء إسكندرون ضِمنَ المناطق الزرقاء التي تشمل سواحل بلاد الشام الشمالية، والتي أعطتها معاهدةُ سايكس بيكو إلى فرنسا، وكانت كذلك كيليكيا بيد فرنسا، فرغبت أن يكون لها قناة تواصُل مع الأتراك، كما للإنجليز فأعطت فرنسا -بعد مفاوضات- كيليكيا لتركيا، ورسمت الحدودَ بين سوريا وتركيا؛ حيث كان لواء إسكندرون في الأرض الشامية، ورَغِبَ مصطفى كمال في إظهار الإخلاص لأمَّتِه، فرفع طلبًا للأمم المتحدة لحَلِّ الن"},{"id":5086,"era":"c14","t":"إعلان إيطاليا ضم طرابلس وبرقة إلى ليبيا ومنحها الجنسية الإيطالية للسكان .","s":"قبل اندلاع الحرب العالمية الثانية بتسعة أشهر أعلنت إيطاليا ضمَّ طرابلس وبرقة إلى ليبيا سابقًا (ليبيا بالأصل تُطلَق على الصحراء التي تقع غربَ نهر النيل وجنوب برقة وطرابلس) ومنحت للسكَّان الجنسية الإيطالية، وألزمَتْهم تعلُّمَ اللغة الإيطالية، ومن عارضها هتكت عِرْضَه، وألقت كثيرًا من الناسِ مِن الطائرة وهم أحياء، إلى غير ذلك من الأعمال الوحشية."},{"id":5087,"era":"c14","t":"مقتل الملك غازي بن فيصل الأول ملك العراق وتولي ابنه فيصل الثاني  .","s":"هو الملِكُ غازي بن فيصل بن الشريف حسين الهاشمي ثاني ملوكِ العراق. ولِدَ سنة 1333هـ / 1912م في مكة التي كانت واقعةً ضِمنَ ممالك وولايات الدولة العثمانية، وهو الابنُ الوحيد للملك فيصل الأول الذي كان له 3 بنات. عاش في كنَفِ جَدِّه حسين بن علي شريف مكة قائد الثورة العربية المنادي لاستقلال العرب من الأتراك العثمانيين، مناديًا بعودة الخلافة للعرب. أرسله والِدُه الملك فيصل الأول إلى كلية هارو في إنجلترا "},{"id":5088,"era":"c14","t":"بداية تصدير النفط السعودي .","s":"في الثامن من ربيع الأول 18 إبريل وصل الملك عبد العزيز إلى الظهران، وأمضى يومين في استعراضِ مُنشآت النفط، بين الظهران وميناء رأس تنورة؛ ملازمًا في سيره خط الأنابيب، مُتَّبعًا مسيل الزيت من مكانِ خروجه إلى مكان انصبابه في الباخرة، وفي 11ربيع الأول صَعِدَ الباخرة في رأس تنورة، وافتتح مجرى انتقال الزيت إليها، فاندفع ما زِنَتُه عشرة آلاف طن، هي الحمولة التجارية الأولى، في أول باخرة شَحَنت شحنةً كاملة ك"},{"id":5089,"era":"c14","t":"الحرب العالمية الثانية .","s":"حربٌ كونيَّةٌ مُدَمِّرة شاركت فيها معظَمُ دول العالم، استمَرَّت ست سنوات من 1 سبتمبر 1939م إلى 2 سبتمبر 1945م انطلقت شرارةُ هذه الحرب مع هجومِ ألمانيا على بولونيا في 17 رجب 1358هـ/ 1 سبتمبر 1939م؛ ليتسع ذلك الخلاف بإعلانِ كُلٍّ مِن فرنسا وإنجلترا الحربَ على ألمانيا، ثم تشكَّلَ طرفا النزاع من حِلْفَين: الأول دُولُ الحُلَفاء على رأسِها كُلٌّ من بريطانيا وفرنسا وروسيا الشيوعية، ثم انضمَّت إليهم أمريك"},{"id":5090,"era":"c14","t":"فرنسا تصدر قرارا بحل حزب الشعب الجزائري ذي الميول الشيوعية. .","s":"بعد الأحداثِ التي عرفَتْها الساحةُ السياسية في الجزائر خلال الثلاثينيات، مثل انعقاد المؤتمر الإسلامي 1936، ووصول الجبهة الشعبية إلى الحكم في فرنسا، ثم خيبة أمل الحركة الوطنية الجزائرية في وعود الإصلاحِ مِن طَرَف الجبهة الشعبية ونتيجةً لحلِّ حزب نجم شمال إفريقيا سنة 1937؛ تم إعادة تشكيل حزب وطني جديد من قِبَلِ بعض أعضاء نجم شمال أفريقيا، فكان حزبُ الشعب الجزائري الذي تأسس في مارس 1937 في فرنسا، ويع"},{"id":5091,"era":"c14","t":"قيام الأمير إدريس السنوسي بعقد اجتماع هام في الإسكندرية .","s":"بعد أن استقَرَّ الأميرُ إدريس السنوسي في القاهرة أصبحت حركتُه محدودةً بعد أن فَرَض عليه الاحتلالُ البريطاني في مصر عدَمَ الاشتغال بالسياسة، وكان من حينٍ إلى آخر يكتُبُ في الصحف المصرية حولَ قضية بلاده. وعندما اشتعلت الحربُ العالمية الثانية نَشِطَ إدريس السنوسي وعقد اجتماعًا في داره بالإسكندرية حضره ما يقرب من 40 شيخًا من المهاجرين الليبيين، وذلك في 6 رمضان 1359هـ/ 20 أكتوبر 1939م، وانتهى الحاضِرون"},{"id":5092,"era":"c14","t":"ثورة الشيخ حيدر بالأحواز على الإيرانيين .","s":"كانت إيران قد احتلَّت الأحواز (عربستان) في عهد رضا بهلوي عام 1925 بعد أن منحته بريطانيا هذا الإقليمَ العربيَّ مكافأة له على مساندتِه لها في الحرب العالمية الأولى، وقد بلغ غضبُ الأحوازيين بعد الأوضاع الشاذة التي تعرَّض لها على أيدي السلطات الإيرانية المحتلَّة ذِروتَه هذا العامَ، فأخذ أحرارُ الأحواز يحَرِّضون العشائِرَ على الثورة ورَفْع الذلِّ الذي نكَّس رؤوسَهم طوال هذه السنوات, وغسل عار استعبادهم."},{"id":5093,"era":"c14","t":"قرار لاهور (قرار باكستان) بشأن تقسيم الهند .","s":"كان المسلِمون في الهند قد قدَّموا مشروعاتٍ مِن أجل التقسيم؛ فمنهم من يرى الانقسامَ عن الهندوس، ومنهم من يرى البقاءَ وعدم التقسيم؛ لمصلحة الدعوة والأقليات، وكان محمد إقبال قد دعا إلى تشكيلِ دولة باكستان والانفصال عن الهندوس في 1356هـ، ولكنه توفِّيَ في العام التالي، ثم عُقِد مؤتمر السند الإقليمي للرابطة الإسلامية في كراتشي برئاسة محمد علي جناح، وقرر في شعبان 1357هـ / 10 أكتوبر 1938م أنَّه من الضروري"},{"id":5094,"era":"c14","t":"وفاة الشيخ عبد الحميد بن باديس مؤسس جمعية العلماء المسلمين بالجزائر .","s":"هو الشيخُ عبد الحميد بن محمد المصطفى بن مكي بن باديس مؤسِّسُ جمعية العلماء المسلمين بالجزائر. ولِدَ في 11 من ربيع الآخر 1307هـ بمدينة قسنطينة، ونشأ في أسرةٍ كريمة ذات عراقة وثراء، ومشهورة بالعلم والأدب، سافر إلى تونس في سنة 1326هـ وانتسب إلى جامع الزيتونة، وتلقى العلومَ الإسلاميةَ على جماعةٍ مِن أكابر علمائه، أمثال الشيخ محمد الطاهر بن عاشور، ولقد آمن ابنُ باديس بأنَّ الطريق الأوَّلَ لمقاومة الاحت"},{"id":5095,"era":"c14","t":"دول المحور تنقل ميدان الحرب إلى البحر المتوسط وبلدان شمال أفريقيا  .","s":"اندلعت نارُ الحرب العالمية الثانية في 17 رجب 1358هـ، ودخلت إيطاليا إلى جانب ألمانيا واليابان مقابِلَ إنجلترا وفرنسا والولايات المتحدة الأمريكية وروسيا، ومعنى ذلك أن أرضَ ليبيا ستكون ساحةَ صراع بين الأطراف المتخاصِمة؛ فأرضُها مُحتلَّة من قِبَل إيطاليا، بينما إنجلترا محتَّلةٌ الأراضي التي تحدُّها من الشَّرقِ، وهي مصر. وفرنسا تحتَلُّ الأراضي التي تحدُّها من الغرب والجنوب، وهي: تونس والجزائر وتشاد وال"},{"id":5096,"era":"c14","t":"ثورة رشيد عالي الكيلاني ضد الاحتلال البريطاني في العراق .","s":"ثورةُ رشيد عالي الكيلاني هي سلسلةُ الأحداث الدستورية التي تصاعدت بسببِ تضارُبِ مدارس الحُكم الملكي في العراق وتياراتِه ما بين التيارِ الوطني الثوري التحرري، والتيار الليبرالي الميَّال لممالأة الإنجليز، في وقت كان العراقُ يمثِّل زعامةً ومدرسةً سياسيةً يُعتَدُّ بها في المنطقة العربية، فلما تفاقمت الأمورُ في الحكومة العراقية وتأزَّمت بسبب موقِفِ العراق من الحرب العالمية الثانية وموقِفِها من الدول الم"},{"id":5097,"era":"c14","t":"دور الإمبراطور هيروهيتو في دخول اليابان الحرب العالمية الثانية  .","s":"خرجت اليابانُ مِن هذه الحرب بملايين القتلى والجرحى من شَعبِها، واقتصاد مدمَّر كلِّيًّا، وسيطرة كاملة على أراضيها مِن قِبَل القوات الأمريكية؛ فمن هو المسؤول عن إشراك اليابان في هذه الحرب المدمِّرة، وتعرُّض الشعب إلى الكوارث بسببها؟ يرى البعضُ أن الإمبراطور هيروهيتو غيرُ مسؤول؛ لأن الحكومة والجيش الياباني ذا التوجُّهات القومية المتطرِّفة والنزعة التوسعية يعملون خلال السنوات الأخيرة منذ عهد الإمبراطو"},{"id":5098,"era":"c14","t":"تنازل رضا شاه ملك إيران لولده محمد .","s":"كانت إيران قد وقفت في الحرب العالمية الثانية مع ألمانيا ضِدَّ الحلفاء الذين طالبوا إيران بتسليمِ الألمان الموجودين في إيران، وفي 15 شعبان 1360هـ / 6 أيلول 1941م عاد الحلفاءُ فطلبوا من إيران طرْدَ البَعثات السياسية لدول المحور، وفي 23 شعبان / 14 أيلول طلبت بريطانيا وروسيا من الشاه رضا بهلوي التنازُلَ عن العرش لولي عهده محمد رضا، وإعلان الحرب على ألمانيا وبقية دول المحور، فرفض فأجبره الحلفاءُ على ال"},{"id":5099,"era":"c14","t":"اليابان تحتل جنوب شرقي آسيا .","s":"دخلت اليابان الحرب العالمية الثانية إلى جانب دول المحور تتزعَّمُهم ألمانيا النازية واستطاعت اليابان القيامَ بحروب خاطفة باحتلالِ جنوب شرقي آسيا، وكان من بين ما احتلَّتْه: جزيرة بورنيو (أندونيسيا)، وشبه جزيرة الملايو (ماليزيا) بعد حملة دامت أكثر من شهرين، وذلك في 20 ذي القعدة 1360هـ / 8 ديسمبر 1941م، كما استولت على سنغافورة مَعقِل القوات البريطانية في المنطقة، ووضعت البلادَ تحت الإدارة العسكرية الي"},{"id":5100,"era":"c14","t":"مذبحة المسلمين في مقاطعة القراقي بالحبشة .","s":"بعد أن عاد هيلا سيلاسي إلى الحكم في عام 1361 / 1942م وبعد أن أتمَّ استئناف برامجه لتنصير المسلمين، جاءت الهيئاتُ التنصيرية السويدية بإيعازٍ منه إلى منطقة القراقي الإسلامية، والتي لا يوجَدُ فيها نصراني واحد، أو يهودي أو وثني، فهَبَّ شيخ المقاطعة عبد السلام يطالبُ عن طريق القانون منعَ دخول المنصِّرين إلى هذه المقاطعة الإسلامية؛ تجنُّبًا لِما يحدث من أضرار للمنَصِّرين، فاتهمته السلطاتُ بأنه يبَيِّت ا"},{"id":5101,"era":"c14","t":"تحرر الحبشة من الاحتلال الإيطالي. .","s":"احتلَّت إيطاليا الحبشة عام 1354هـ / 1935م رغم مُعارضة الأمم المتحدة وفَرْض العقوبات الاقتصادية، ثم لَمَّا قامت الحرب العالمية الثانية قامت الثورات في الحبشة ضِدَّ الطليان بتحريضٍ مِن البريطانيين وباقي الحلفاء، وزحفت القوات البريطانية من السودان إلى الحبشة، وخرج الطليان من البلاد ودخل الإنجليز أديس أبابا عام 1360هـ / 1941م، وأعيد الإمبراطور هيلا سيلاسي من منفاه في العام نفسِه، وبعد أن استسلمت آخِرُ"},{"id":5102,"era":"c14","t":"إنشاء الحاج أمين الحسيني معاهد لتخريج الأئمة في دول المحور  .","s":"أثناء إقامة المفتي الحاج أمين الحسيني في ألمانيا بعد فراره من الإنجليز أيامَ الحرب العالمية الثانية سَمِعَ بالمآسي التي حلَّت بالشعب البوسني المسلم عندما تصارعت عليه القوميتان الكرواتية والصربية؛ حيث اجتمع بزعماء بوسنة وهرسك، وبعد البحثِ معهم ومع قيادة القوات الألمانية في كيفية المحافظةِ على حياة البشناق (البسنويين) ومَنْع وقوع المذابح فيهم، وافقت الحكومة الألمانية على تجنيد الشبَّان منهم وتسليحهم"},{"id":5103,"era":"c14","t":"الإنذار البريطاني لفاروق ملك مصر وأحداث 18 محرم 1361هـ .","s":"في منتصف محرم - 1 فبراير قامت مظاهراتٌ تطالب بإسقاط الحكومة بعد أن ظهر أنَّها توالي الإنجليز، وصادف ذلك هوًى في نفس فاروق الملك، فأقال الحكومةَ، وكلَّف علي ماهر بتشكيل وزارة جديدة، واستمَرَّت المظاهرات، وفي 17 محرم اتصل السفيرُ الإنجليزي مايلز لامبسون بالملك فاروق، وأخبره أنَّ الحكومة البريطانية تصِرُّ على تغيير الوزارة القديمة، وتشكيل حكومة وفدية برئاسة مصطفى النحاس، واجتمع المَلِكُ بالشخصيات الس"},{"id":5104,"era":"c14","t":"المعاهدة الثلاثية الإيرانية الروسية البريطانية .","s":"بعد أن أجبَرَ الإنجليز رضا شاه بهلوي بالتنازل عن الحكم لابنه محمد بسبب ميوله للألمان عُقِدَت معاهدة ثلاثية بين إيران وبريطانيا وروسيا في 12 محرم / 29 يناير اعترفت بريطانيا وروسيا فيها بوَحدة الأراضي الإيرانية واستقلالها وسيادتها، وتعهدت الدولتان بالدِّفاعِ عن إيران ضِدَّ أي اعتداء، كما احتفظتا بما تراه ضروريًّا من قوات برية وبحرية وجوية على أرض إيران، وتعهَّدتا بسحب قواتهما خلال ستة أشهر بعد انتها"},{"id":5105,"era":"c14","t":"سقوط مدينة طبرق الليبية في يد الجيش الألماني .","s":"شنَّت القواتُ الألمانية بقيادة المارشال إيروين روميل (رومل ثعلب الصحراء) هجومًا كاسِحًا على مدينة طبرق الليبية -مدينة ساحلية شرق طرابلس- التي كانت قد سقطت في أيدي القوات البريطانية في وقت سابق. لم يكن البريطانيون يتصوَّرون أن يفكِّرَ الألمان في مهاجمة مدينة طبرق التي تتميَّزُ بموقع استراتيجي؛ حيث يَسهُلُ الدفاعُ عنها بسبب وقوعِها على قمة هضبة مرتفعة تجعَلُ من الهجوم عليها مهمةً صعبة. وقد لعبت خطةُ"},{"id":5106,"era":"c14","t":"هروب رشيد عالي الكيلاني من العراق .","s":"بعد فَشَلِ حركة رشيد عالي الكيلاني في العراق بمناهضة الاحتلالِ الإنجليزي هرب إلى إيران، فلما دخلَتْها الجيوش البريطانية والروسية فرَّ إلى تركيا، والتقى هناك بعددٍ من الزعماء العرب الذين طالبوه بالعمَلِ السريع من أجل العرب، وحرَّر المجتَمِعون وثيقةً تتضَمَّنُ اعتراف الحكومة الألمانية بأنَّه رئيس وزراء العراق لتكونَ لمحادثاتِه صِفةٌ رسمية، وأن يحصُلَ على تصريح رسمي من الحكومتين الإيطالية والألمانية "},{"id":5107,"era":"c14","t":"معركة العلمين غرب الإسكندرية بين الحلفاء والألمان  .","s":"معركةُ العَلَمين الثانية هي المعركة التي وقعت في العلمين التي تبعد 90 كيلومترًا عن الإسكندرية، وكانت بين القوات الألمانية والإيطالية بقياده إرفين رومل، وبين القوات البريطانية بقيادة برنارد مونتغمري، وتُعَدُّ هذه المعركة من أهم معارك التحَوُّل في الحرب العالمية الثانية، كما أنها كانت من أهم معارك الدبَّابات على مدار التاريخ، وبعد انتصار القوات الألمانية في معارك الصحراء، وكان الفرقُ بين قوات الجانب"},{"id":5108,"era":"c14","t":"تأسيس الأحزاب السياسية في ليبيا. .","s":"اتجه النضال في طرابلس نحو العمل السياسي والمطالبة بوحدة أراضيه والاستقلال، فأنشئ النادي السياسي الأول عام 1362هـ / 1943م في مدينة طرابلس، وافتتح فروعًا له في النواحي. وازداد نفوذ النادي حتى تمكَّن بعد عامين من تنظيم مظاهرة كبرى أزالت اللافتاتِ الفاشية من الشوارع. وتقَدَّم بعضُ الذين سبق لهم التعاونُ مع الإيطاليين بعرائض طالبوا فيها بوصاية بريطانية. ونشأ كرَدِّ فعل لهذه الحركة الحزبُ الوطني عام 136"},{"id":5109,"era":"c14","t":"مؤتمر الدار البيضاء (أنفا) .","s":"عُقِد مؤتمر الحلفاء بعد انتصارِهم على دول المحور في الحرب العالمية الثانية بحضور الرئيس الأمريكي فرانكلن وروزفلت ورئيس الوزراء البريطاني تشرشل، ومَثَّل فرنسا الحرة الجنرال شارل ديغول، واعتذر عن الحضور رئيس الوزراء الروسي جوزيف ستالين؛ لانشغاله بمتابعة القتال الدائر في ستالينغراد. انعقد المؤتمر في فندق أنفا بمدينة الدار البيضاء بالمغرب؛ بهدف رسم الاستراتيجية الأوروبية للحلفاء بعد الحرب، وقد أسفرت ا"},{"id":5110,"era":"c14","t":"ليبيا تحت نفوذ الحلفاء .","s":"كانت ليبيا تحت الاحتلال الإيطالي، وبعد سنة من بدء الحرب العالمية الثانية بدأت الحربُ بين إيطاليا وإنجلترا في ليبيا ومصر؛ حيث كانت مصر تحت احتلال إنجلترا، وكانت الحرب سِجالًا، حتى استطاعت إنجلترا ومعها حلفاؤها من القوات أن تدخُلَ طرابلس الغرب في تاريخ 17 محرم 1362هـ / 23 يناير وانسحب الإيطاليون بعد أسبوعين، واستمَرَّ تراجع دول المحور المقابلين لدول الحلفاء، فأصبحت ليبيا تحت النفوذ الإنجليزي التابع "},{"id":5111,"era":"c14","t":"استيلاء الحلفاء على مدينة قفصة التونسية .","s":"استطاع الحلفاءُ أن يستولوا على مدينة قفصة التونسية، وذلك بعد طرد القوات الألمانية منها أثناء الحرب العالمية الثانية."},{"id":5112,"era":"c14","t":"قوات الحلفاء تستعيد احتلال المغرب من الألمان .","s":"لَمَّا اندلعت الحرب العالمية الثانية لم تلبث فرنسا كثيرًا حتى انهارت أمامَ ألمانيا وقامت حكومةُ فيشي برئاسة الجنرال بيتان الذي وقَّع الهدنة مع الألمان، وكان مواليًا لهم، وتَبِعَت المغرب حكومةَ فيشي، إلَّا أن السلطان كان بجانب ألمانيا كُرهًا لدول الحلفاء، ثم استطاعت قوات الحلفاء أن تنزل بالمغرب في 11 ذي القعدة 1362هـ / 8 نوفمبر وخرج منها أتباع حكومة فيشي، علمًا أن أسبانيا خلال هذه الفترة احتلت طنجة"},{"id":5113,"era":"c14","t":"تأسيس حزب الاستقلال في المغرب  .","s":"نشأ حزبُ الاستقلالِ مع انطلاق الحركة الوطنية التي سعت للتحرُّر من الهيمنة الأجنبية، واستعادة السيادة المغربية. فقام الحزبُ بتقديم عريضة المطالبة بالاستقلال والديمقراطية يوم 11 يناير 1944، ومن هذا التاريخ أصبح الحزبُ الوطني يحمِلُ اسم حزب الاستقلال. وفي 28 يناير تمت حملةُ اعتقالات في صفوف مسيِّري الحزب وقادته وفي مقدِّمتِهم الأمين العام أحمد بلفريج؛ حيث نُفِيَ إلى جزيرة كورسيكا، فعمت البلاد موجةٌ م"},{"id":5114,"era":"c14","t":"الشعب المغربي يعلن وثيقة تطالب بالاستقلال .","s":"بعد أن خرجت الحكومة الفرنسيى من المغرب أخذت الحركة الوطنية بنشاطها من جديد؛ حيث نشأ حزب الاستقلال في 1363هـ / 27 ديسمبر 1943م وحلَّ محَلَّ الحزب الوطني ونال تأييدًا شعبيًّا واسعًا، ثم التقت الأحزابُ المغربية واتخذت ميثاقًا تضمَّن أهدافَ الشعب المغربي، وفوَّضوا حزب الاستقلال بتقديم المطالب للملك، وإلى المقيم الفرنسي العام ومتابعة مراحل المطالبة بالاستقلال، وكانت أهم بنود الميثاق: المطالبة بالاستقلا"},{"id":5115,"era":"c14","t":"وفاة الشيخ عبد العزيز الثعالبي  .","s":"هو عبد العزيز بن إبراهيم بن عبد الرحمن الثعالبي: زعيمٌ تونسيٌّ، وهو عالم، أديب، كاتب، خطيب، سياسي، صحافي, جزائري الأصلِ، ولِدَ بتونس في 15 شعبان 1293هـ. حَفِظَ القرآن الكريم وأتمَّ الدراسة الأولية في البيت على يد مدرس خاص، ثم دخل مدرسة \"باب سويقة الابتدائية\" في تونس، ثم التحق بجامع الزيتونة وتخرج سنة 1896م، وأخذ يتردَّدُ على المدرسة الخلدونية حتى حصل على الدراسات العليا. وبظهور أولِ حزب لتحرير تون"},{"id":5116,"era":"c14","t":"جهاد الجزائريين للفرنسيين في الجزائر .","s":"لم يتجاوب الشعب الجزائري مع السياسة الفرنسية في جميع الجهاتِ بدون استثناء؛ فلم يكن هناك أثَرٌ في فَرْنَسة الشعب الجزائري المسلِم، وهو ما دفع مخطِّطي السياسة الفرنسية إلى اتهام الجزائريين بأنَّهم شَعبٌ يعيش على هامش التاريخ. حارب الجزائريون سياسةَ التفرقة الطائفية، وقد رأى المصلِحون من أبناء الجزائر في ظِلِّ فَشلِ حركات المقاومة يتقَدَّمُهم الشيخ العالِم عبد الحميد بن باديس أنَّ العمل يجب أن يقومَ "},{"id":5117,"era":"c14","t":"إنشاء جامعة الدول العربية .","s":"بدأت سلسلة من المشاورات الثنائية بين مصر من جانب، وممثِّلي كلٍّ من العراق وسوريا ولبنان والمملكة العربية السعودية والأردن واليمن من جانب آخرَ، وهي المشاورات التي أسفرت عن تبلور اتجاهين رئيسين بخصوص موضوع الوحدة العربية: الاتجاه الأول يدعو إلى ما يمكِنُ وصفه بالوَحدة الإقليمية الفرعية وقوامها سوريا الكبرى أو الهلال الخصيب. والاتجاه الثاني يدعو إلى نوعٍ أعَمَّ وأشمل من الوحدة يظلِّلُ عموم الدول العر"},{"id":5118,"era":"c14","t":"تأسيس الهيئة العربية العليا لفلسطين في مصر .","s":"عندما انتقل الحاج أمين الحسيني مفتي القدس من باريس إلى مصر شكَّل الهيئةَ العربية العليا لفلسطين برئاسته؛ حيث نظَّم الحركةَ الوطنية الفلسطينية تنظيمًا حديثًا، وقرَّر إعداد الشعب لخَوضِ الكفاح المسلَّح ضِدَّ الصهاينة والإنجليز، وألَّف لجنة من قادة المجاهدين الفلسطينيين وبعض الضبَّاط السوريين والعراقيين والمصريين لوضع الخطط وتحديد المطلوب من الأسلحة والمعَدَّات للجهاد الذي كان أوانه قد اقترب بعد بروز"},{"id":5119,"era":"c14","t":"إلقاء أمريكا القنبلتين الذريتين على هيروشيما وناغازاكي .","s":"حصلت الكارثة الذَّرِّية بتاريخ 6 آب/ أغسطس عام 1945م عندما أمرت حكومة الرئيس الأمريكي هاري ترومان بإلقاء القنبلة الذرية على اليابان. عندما رفضت اليابان الإنذارَ الأمريكي بالاستسلام غير المشروط، فأغار الطيرانُ الأمريكي على وسط مدينة هيروشيما، وألقى القنبلةَ الذرية المعبَّأة باليورانيوم والتي كانت تزِنُ أكثَرَ 4.5 أطنان من على ارتفاع 1980 قدمًا عند الساعة الثامنة والربع من صباح ذلك اليوم، عندما كان "},{"id":5120,"era":"c14","t":"قيام حكومة إسلامية في أندونيسيا، ومؤتمر جاكرتا الإسلامي .","s":"ما إن انتهت الحربُ العالمية الثانية، وكانت اليابان قد هُزِمَت، بعد أن أُلقِيَت عليها القنبلةُ الذَّرية الأمريكية، وكانت اليابان قد احتَلَّت فيما احتلَّتْه جزرَ أندونيسيا، وبعد يومين من الهزيمة اليابانية أُعلِنَ عن قيام حكومة أندونيسية برئاسة أحمد سوكارنو، ونائبه محمد حتا، وأخذت الحكومةُ تعمَلُ على الحيلولة دون عودة المحتلين الهولنديين، فتحركوا لنزعِ السلاح من اليابانيين، وأُسِّسَت حكومة وسط جزيرة "},{"id":5121,"era":"c14","t":"إصدار الوثيقة الأولى لإنشاء جامعة الدول العربية .","s":"في أعقابِ الحرب العالمية الثانية اتَّفَق قادة خمس دول عربية في مدينة الإسكندرية بمصر على إنشاء منظمةٍ تربطُ العربَ بعضهم ببعض، فتمَّ إنشاء جامعة الدول العربية في العام التالي. وكلُّهم توافقوا على ما يسمى اليوم ببروتوكول الإسكندرية. وكان الهدفُ الرئيسي لهذه المنظمة هو تعزيزَ العلاقات بين الدول العربية والمشاركة بفعاليةٍ في تنسيق الخطَطِ السياسية، والسياسة الخارجية من دونِ التدخُّلِ في استقلاليتها، "},{"id":5122,"era":"c14","t":"استقلال سوريا ولبنان .","s":"بعد أن انتهت الحرب العالمية وانتصر الحلفاء أرسل ممثِّل فرنسا مذكرةً إلى حكومتي سوريا ولبنان؛ مذكرةً تضَمَّنت طلباتٍ متعسفة تتعارضُ مع السيادة الوطنية، وكان فيها إصرارٌ شديد لعقد اتفاقيات تجعل لفرنسا مكانًا متميزًا وأوضاعًا استراتيجيةً، فلم ترضَخِ الحكومتان لهذه الضغوط، وبدأ الهياجُ الشعبي، ثم قام الفرنسيون بواسطةِ جنود سنغاليين بقتل رجال الشرطة المكلَّفين بحراسة مبنى مجلس النواب، ثم وُجِّهَت المدف"},{"id":5123,"era":"c14","t":"مقاطعة ساراواك (ماليزيا) تصبح مستعمرة بريطانية .","s":"أصبحت مقاطعةُ ساراواك (التابعة لماليزيا) عام 1365هـ مُستعمرةً تابعة للتاج البريطاني؛ حيث تنازل حاكِمُ الولاية عن سلطته على الولاية إلى التاجِ البريطاني."},{"id":5124,"era":"c14","t":"إعلان ألبانيا جمهورية شعبية بعد إلغاء الملكية .","s":"بعد استقرارِ الأحوال في ألبانيا، أُجريت انتخابات عامة وعلى إثر فوز أنور خوجا بها أُعلنت ألبانيا جمهوريةً شعبية، وأُلغيت الملكية رسميًّا، وأصبح أنور خوجا رئيسًا للبلاد، وما إن أمسك بمقاليد الأمور حتى بادر إلى قطعِ العلاقات مع كلٍّ مِن بريطانيا والولايات المتحدة الأمريكية. وكان أنور خوجا من المعجَبين بستالين: دكتاتور الاتحاد السوفيتي الشيوعي، فوقف إلى جانِبِه حين نشب خلافٌ سنة 1367هـ / 1948م بينه وب"},{"id":5125,"era":"c14","t":"سيطرة الشيوعيين على ألبانيا .","s":"بَقِيَت ألبانيا تحت الاحتلالِ الإيطالي نحو أربع سنوات، ثم وقَعَت تحت الاحتلال الألماني، لكِنَّها ما لبثت أن انسحبت منها بعد عام واحد، وكانت الهزائِمُ قد توالت عليها، ولم تجد مفرًّا من تَرْك ألبانيا؛ فتسَلَّم الحكمَ فيها جبهةُ التحرير القومية بقيادة الشيوعيين، وكانت هذه الجبهةُ قد تأسَّست في سنة 1360هـ / 1941م، وقادت حركةَ المقاومة ضِدَّ الغزو الإيطالي والألماني. ولما وضعت الحربُ أوزارَها، وعاد اله"},{"id":5126,"era":"c14","t":"مبادرة الملك الأردني عبد الله الأول للدعوة إلى إحياء مشروع \"سوريا الكبرى\" .","s":"بعد أن منحت بريطانيا شرقَ الأردن حَقَّ الاستقلال -بموجِبِ صَكِّ الانتداب- دعا ملِكُ الأردني عبد الله الأول إلى إحياءِ مشروع \"سوريا الكبرى\" الذي يضمُّ الأردن وسوريا ولبنان، إلَّا أن المجلس النيابيَّ السوري رفض هذا المشروع في سبتمبر 1947م."},{"id":5127,"era":"c14","t":"معاهدة بريطانيا الأردن الثانية واستقلال الأردن  .","s":"بعد أن قضى الانتدابُ البريطاني في شرق الأردن 25 سنة من 1921م مَنَحت بريطانيا شرقَ الأردن حقَّ الاستقلال بموجِبِ صَكِّ الانتداب -الذي يقضي ببقاء شرق الأردن تحت الحكم البريطاني 25 سنة- تمَّ إبرامُ المعاهدة البريطانية الأردنية الثانية في 22 مارس التي تعترف باستقلالِ شرقِ الأردن. وتم إعلانُ استقلال إمارة شرق الأردن، وإعلانُ قيام المملكة الأردنية الهاشمية، ويكون المَلِكُ عبد الله الأول بن الحسين ملكًا "},{"id":5128,"era":"c14","t":"إعلان قيام حزب الأمة السوداني .","s":"أسَّس عبد الرحمن المهدي زعيمُ جماعة الأنصار المهدية حزبَ الأمة السوداني كامتدادٍ سياسي للحركة المهدية في السودان، وكان شعارُه \"السودان للسودانيين\" وتحقيق المطامح الوطنية في الاستقلال عن مصر، والتخلُّص مما يُعرَف بدولتي الحُكمِ الثنائي (مصر وبريطانيا)، وبناء الدولة السودانية المستقلَّة على أُسُس المساواة والحرية والعدل، وكان حزبُ الأمة السوداني يطالِبُ باستقلال السودان عن بريطانيا ومصر رافعًا راية "},{"id":5129,"era":"c14","t":"إطلاق اسم الأردن رسميًّا على إمارة شرق الأردن .","s":"تمَّ إطلاق اسم الأردن رسميًّا على إمارة شرق الأردن، وقد تأسَّست هذه الإمارة سنة 1920 تحت الانتدابِ البريطاني بموجِبِ صَكِّ الانتداب الذي وقَّعَه عبد الله بن الحسين أمامَ وزير المستعمرات البريطاني تشرشل مقابِلَ تنصيبِه مَلِكًا على شرق الأردن، وقد حَصَلت الإمارة على استقلالِها في 25 مايو 1946م، واعتُبِرَ ذلك اليوم عيدًا للاستقلال، وتألَّفت في هذه الإمارة 18 وزارة قبل إعلانها مملكةً تحت اسم المملكة ا"},{"id":5130,"era":"c14","t":"مؤتمر القمة العربي غير العادي (قمة أنشاص) .","s":"يعتبَرُ أول مؤتمر قمة عربي عُقِدَ هو مؤتمر قمة أنشاص هذا العام من 29 إلى 30 يوليو، (وهو مؤتمر قمة غير عادي) عُقِدَت هذه القمَّةُ بدعوة من الملك فاروق في قصرِ أنشاص بالشرقية في مِصرَ، وضَمَّت الدولَ السبع المؤسِّسة للجامعة العربية (22 آذار 1945م)، وهي: مصر، وشرق الأردن، والسعودية، واليمن، والعراق، ولبنان، وسوريا، وطالب المجتَمِعون بالحفاظ على عروبة فلسطين، ووقْف الهجرة اليهودية إليها، ولم يَصدُرْ ع"},{"id":5131,"era":"c14","t":"إصدار مجلس السوفييت الأعلى قرارا بإلغاء \"جمهورية القرم\" .","s":"أصدر مجلِسُ السوفييت الأعلى قرارًا بإلغاء \"جمهورية القرم\" ذات الاستقلال الذاتي؛ بذريعة خيانة شعب القرم للسوفييت أثناء الحرب العالمية الثانية، وتعاونهم مع الألمان. وشِبهُ جزيرة القرم جمهوريةٌ ذاتُ حكم ذاتي تقع حاليًّا في أوكرانيا، ويحيط بها البحرُ الأسود من الجنوب والغرب، وبحر أزوف من الشرق، وتبلغ مساحتها 27 ألف كم، وعدد سكانها 2.5 مليون نسمة. وقد تمكَّن الروسُ من غزوها في سنة 1198ه - 1783م في عهد "},{"id":5132,"era":"c14","t":"تأسيس حزب الاتحاد الديمقراطي في الجزائر .","s":"أسَّس الجزائريُّ فرحات عباس حزبَ الاتحاد الديمقراطي للبيان الجزائري، بعد أن قَمَعت السلطاتُ الفرنسية بالجزائر كلَّ الأحزاب والمنظمات السياسية. وكانت للحزب صحيفةٌ اسمُها التفاهم تصدُرُ باللغة الفرنسية وتنطِقُ باسم الحزب. كان الحزبُ يَعرِض مساوئَ الحكم الفرنسي في الجزائر، ويطالبُ بالمساواة في الحقوق والمعاملة بين الفرنسيين والجزائريين. ولم يكن يؤيِّدُ الكفاحَ المسلَّح أو الانفصال عن فرنسا. توقَّف نش"},{"id":5133,"era":"c14","t":"اندلاع أعمال عنف بين الهندوس والمسلمين في مدينة كالكوتا الهندية .","s":"اندلعت أعمالُ عُنفٍ بين الهندوس والمسلمين في مدينة كالكوتا الهندية، وامتدَّت أعمال العنف إلى عددٍ من المدن الأخرى، واستمرَّت الاشتباكات لمدة 3 أيام متواصلة أسفرت عن سقوط 7 آلاف قتيل!"},{"id":5134,"era":"c14","t":"معاهدة صدقي بيفن بين مصر وإنجلترا ومظاهرات تطالب بالجلاء .","s":"قام إسماعيل صدقي بتشكيل حكومة وزارية في مصرَ، هو رئيسها، وقرَّرت في 16 ربيع الثاني 1356هـ / 19 آذار 1946م تأليفَ لجنة للمفاوضات وعرضت على حزب الوفد الاشتراكَ، لكِنَّه لم يشترِكْ لعدم الاتفاق على عدد النواب، وكان رأسُ الوفد البريطاني أرنست بيفن وزير الخارجية، وأخفق الوفدُ في المفاوضات، ثم سافر إسماعيل صدقي مع إبراهيم عبد الهادي وزير الخارجية إلى لندن، ووضع مشروع معاهدة، وأخذت إنجلترا تماطِلُ بالتوق"},{"id":5135,"era":"c14","t":"نشأة حزبي الشعب وبرشام الشيوعيين في أفغانستان .","s":"بدأ تجمُّع أصحاب الفكر الشيوعي والاشتراكي في أفغانستان منذ عام 1361هـ تحت اسم (ويش ذلميان) أي: حركة يقظة الشباب، وكان من أعضائها نور محمد تراقي، وبابرك كارمل، وكانت جريدة (أنجاد البرلمان) تنشر آراءهم، وتهاجم الإسلام، ثم أُلغيت هذه الجريدة عام 1393هـ، ثم نما هذا التجمُّع في عهد وزارة محمد داود، وأصدر محمد تراقي جريدةَ خلق، وفي 28 شعبان 1384هـ الأول من كانون الثاني عام 1965 نشرت جريدة خلق خبرَ ميلاد"},{"id":5136,"era":"c14","t":"قرار 1947م تقسيم فلسطين لدولتين .","s":"كانت اللجنةُ المَلَكية البريطانية (لجنة بيل الملكية) سنة 1356هـ / 1937م قد أصدرت بعد دراسةٍ عدَّةَ توصياتٍ؛ منها: تقسيم فلسطين حيث أوصت اللجنة بقيام كيانٍ صهيوني في فلسطين بناءً على أحلام اليهود، وإعطائهم نصف فلسطين؛ لتكون دولتهم مستقلة تمامًا، مع وضع القدس وما حولها تحتَ الانتدابِ البريطاني؛ لأنها مدينة مقدسة لدى كافة الأديان، ورفضَ العرَبُ هذا القرار، واليهود كذلك رفضوه لأنهم لا يريدون نصفَ فلسط"},{"id":5137,"era":"c14","t":"نشأة حزب البعث العربي الاشتراكي .","s":"تأسَّس في أربعينات القرن الماضي بدمشق على يَدِ كُلٍّ من ميشيل عفلق (نصراني) وصلاح الدين البيطار (مسلم سني) وزكي الأرسوزي (علوي سوري الأصل فرنسي الهوية ولم يتحدَّث بالعربية إلا في آخر أيامه), اندمج حزبُ البعث العربي الذي أسَّسه الأرسوزي مع حركة البعث العربي الذي أسَّسه عفلق، وتولى عفلق قيادته، وفي عام 1952م اندمج حزبُ البعث مع حزب أكرم الحوراني (الحزب الاشتراكي العربي)، فصار اسمُ الحزب حزبَ البعث ا"},{"id":5138,"era":"c14","t":"إصدار البرلمان البريطاني قانون استقلال الهند وتقسيمها .","s":"أصدر البرلمانُ البريطاني قانونَ استقلال الهند وتقسيمها إلى دولتي الهند وباكستان، وقام بمنحِ الإمارات والولايات الحَقَّ الكامِلَ في الانضمام إما إلى الهند أو باكستان."},{"id":5139,"era":"c14","t":"انفصال باكستان عن الهند وتعيين محمد علي جناح حاكمًا عليها .","s":"كانت قضيةُ تقسيم الهند بين المسلمين والهندوس قضيةً شائِكةً جِدًّا، وبقيت سنواتٍ عِدَّةً بين أخذ ورد ومقترحات ومشروعات ومفاوضات وتدخلات بريطانية، وما إلى ذلك، وكان من آخِرِها اللجنةُ الوزارية المؤلَّفة من ثلاثة بريطانيين مهمَّتُهم المباحثة مع زعماء الهند، وأجرت المحادثات وادَّعت أن الشعب باستثناء الرابطة الإسلامية يرغَبُ في وحدة الهند، وأنهم سيرون موضوعَ استقلال باكستان، وزعموا أنَّ إقامةَ دولة باك"},{"id":5140,"era":"c14","t":"المعاهدة العراقية الأردنية .","s":"عُقِدَت معاهدةٌ أردنية عراقية في 20 رمضان 1366هـ / 7 آب كان القَصدُ منها الدفاعَ المشترك، وكان القصدُ الإنجليزي منها إثارةَ الحُكمِ السعودي والضَّغط عليه؛ للحصول على بعض المنافِعِ، أو تمرير بعض المخطَّطات، ورأى العراقيون في المعاهدةِ مَصلحةً للأردن والعراق كدَعمٍ لقضية فلسطين التي كانت تشغَلُ المسلمين عامةً، والأمصارَ المجاورةَ خاصَّةً، وقد وقف الشيوعيون في العراق موقِفًا مؤيِّدًا لليهود بكلِّ صرا"},{"id":5141,"era":"c14","t":"الإعلان عن تشكيل حكومة كشمير الحرة (آزار كشمير) .","s":"أعلن الشيخ محمد إبراهيم في 19 ذي القعدة تشكيلَ حُكومةِ كشمير الحرَّة (آزاد كشمير)، وتأليف الجيش الكشميري الذي استطاع أن يسيطرَ على كثير من المناطق ويقيمَ حكومة، وذلك بعد انعقادِ مؤتمر الفلَّاحين الكشميريين، والمطالبة بانضمام الولاية إلى باكستان، لكِنَّ المهراجا الهندوسي \"هري سنغ\" حاكِمَ كشمير المسلِمةِ رفض هذا الطلب، وقام بتوزيعِ الأسلحة على الهنادكة؛ فسارع رجالُ القبائل من باكستان لنجدة إخوانهم ا"},{"id":5142,"era":"c14","t":"إعلان الهند موافقتها الرسمية على انضمام ولاية جامو وكشمير .","s":"أعلنت الهندُ موافقَتَها الرسميَّةَ على انضمام ولاية جامو وكشمير بعد طلب حاكِمِها الهندوسي المهراجا سينج الانضمامَ للهند، وأمرَت الهندُ قواتِها النظامية بالتدخُّل في الولاية جامو وكشمير، وهي ولاية إسلامية؛ فالمسلمون بها أغلبية لا أقلية، فنسبة المسلمين فيها تصِلُ إلى أكثر من 75% وبسبب استيلاء الهند على النصيب الأكبر من أرض الولاية أصبح المسلمون أقليَّةً وسط هذا المحيطِ البشريِّ!"},{"id":5143,"era":"c14","t":"إبادة جيش الهند الهندوسي مسلمي كشمير .","s":"بعد إعلان انفصال باكستان عن الهند لم تكن كشمير قد حُسِم وضعُها في التقسيم بين البلدين، على الرغم من أن طبيعتها وسكَّانها وموقعها الجغرافي هي أقرب إلى باكستان من الهند، ولكن الهند بمكرٍ وخداع عرضت على باكستان أنَّ حَلَّ قضية كشمير مرهون باستفتاء السكان، ووافقت باكستان على هذا العرض، وقد أكَّد على هذا رئيس وزراء الهند جواهر لال نهرو، لكن الهند أرادت أن تجعل من كشمير منطقةَ نزاع مع باكستان تتحرَّش به"},{"id":5144,"era":"c14","t":"إعلان قيام المملكة الأردنية الهاشمية .","s":"كان الأميرُ عبد الله بن الحسين قد تعاون بقواتِه مع الحلفاء في شمال شرق سوريا ضِدَّ دول المحور، فقامت بريطانيا - كنوع من المكافأة- بوعده بمنحِه الاستقلالَ، وفعلًا وقَّعت بريطانيا والأردن معاهدةً في لندن في 22 آذار 1946م اعترفت بموجِبِها بريطانيا بشرقي الأردن دولةً مستقلة، على أن تحتَفِظَ دولة الانتداب بحقِّ إبقاء قواتٍ لها في الأردن، مع استخدام التسهيلات في النقل والمواصلات، وتدريبِ قواتِه المسلَّح"},{"id":5145,"era":"c14","t":"استباحة نصارى الحبشة مدينة هرر المسلمة .","s":"هَبَّت مدينة هرر المسلمة في الحبشة في عهد هيلا سيلاسي تطالبُ بحقوقها العادلة، فجَهَّزت لها الحكومةُ الغاشمةُ ثلاثةَ ألويةٍ مِن الجيشِ اقتحمت المدينةَ وعَمَلَت فيها السَّلبَ والنهب، فصودرت المتاجِرُ والمزارع والمدارس، واعتُقِلَ الآلافُ فامتلأت السجونُ، وأقيمت محاكمُ التطهير، وأُخِذَت أوقاف المساجد وأُبعِدَ الزعماء، وتعرَّض الناسُ لأشد أنواع العذاب. وكان التعذيبُ وحشيًّا لم يقتَصِرْ على إطفاء السجائ"},{"id":5146,"era":"c14","t":"إصدار مجلس الأمن قرارًا بتقسيم فلسطين .","s":"وردت فِكرةُ تقسيم فلسطين إلى دولتين إسلامية ويهودية مع تحديدِ منطقة دولية حول القدس في تقريرِ لجنة پيل الملكية البريطانية عام 1937م، وتقرير لجنة وود هيد من 1938، وصدر هذان التقريران عن لجنتين تم تعيينُهما على يد الحكومة البريطانية لبحثِ قضية فلسطين إثرَ الثورة الفلسطينية الكبرى التي دارت بين السنوات 1933 و1939م. بعد الحربِ العالمية الثانية وإقامة هيئة الأمم المتحدة بديلًا لعصبة الأمم، طالبت الأممُ"},{"id":5147,"era":"c14","t":"الحرب الباكستانية الهندية الأولى  .","s":"ما إن بدأ العمل على انفصال باكستان عن الهند حتى نظم المسلمون في كشمير المناطق التي تمكَّنوا من بسط نفوذهم عليها، وألَّف محمد إبراهيم حكومةَ كشمير الحرة (أزاد كشمير) في ذي 19 القعدة 1366 هـ / تشرين الأول، وتألف الجيشُ الكشميري، فلما وصلت القوات الهندية انضمَّت إلى قوات الحاكم الهندوسي في كشمير وبدؤوا بعمليات التطهير والقتل الجماعي لمسلمي كشمير، فنشب القتال بين الجيش الهندوسي ومجاهدي كشمير، ومع أنَّ"},{"id":5148,"era":"c14","t":"وفاة هدى شعراوي زوجة علي شعراوي  .","s":"هي هدى محمد سلطان المعروفة بهدى شعراوي؛ نِسبةً إلى لَقَبِ زَوجِها علي شعراوي على الطريقة الغربية؛ ولدت في المنيا من مصر الوسطى ونشأت في القاهرة، وكان أبوها رئيس أول مجلس نيابي في مصر، وهي التي خَرَجت بالمظاهرة النسائية سافرةً وحَرَقت حجابَها فتَبِعَها بعضُ النساء على ذلك! فكانت أولَ امرأةٍ مُسلِمةٍ في مصرَ تخلَعُ الحجابَ! مات زوجُها تاركًا لها ثروةً هائلةً كانت سبب بطرها، ألَّفَت جمعيةَ الاتحاد ال"},{"id":5149,"era":"c14","t":"اتفاق رانفيل ثم مؤتمر لاهاي لنقل السلطة للحكومة الأندونيسية .","s":"بعد أن قامت هولندا بإعطاء اعتراف للحكومة الأندونيسية بسيطرتِها على بعضِ الجُزُرِ عادت للتدخُّل العسكري وأعمال عسكرية ضِدَّ الحكومة، ثم تدخَّلت الأمم المتحدة وألزمت هولندا بإيقافِ إطلاق النار، ثمَّ وقِّع اتفاق رانفيل (اسم الباخرة الأمريكية التي عُقِدَت على متنها المفاوضات) واقتصرت على قسمٍ مِن جزيرة جاوه وقطعةٍ مِن سومطرة، وكانت العاصمة جوكجاكرتا (عاصمة أندونيسيا القديمة) ولم ينتهِ العامُ حتى عاد ا"},{"id":5150,"era":"c14","t":"ارتكاب عصابات الهاجاناه مجزرة في بلدة الشيخ بفلسطين .","s":"قامت عصابات الهاجاناه بارتكابِ مجزرةٍ جديدة في حقِّ سكان بلدة الشيخ (يطلق عليها الآن اسم تل غنان) بفلسطين، وقامت بقتل نحو 600 قتيل فيها، وقد وُجِدَت جثث غالبيتهم داخِلَ منازل القرية. والهاجاناه منظمة صهيونية يقصد بها (الدّفاع) تأسست في العام 1921م في مدينة القدس وهي تكتّل عسكري في الانتداب البريطاني على فلسطين في الفترة السّابقة لإعلان دولة إسرائيل."},{"id":5151,"era":"c14","t":"تدمير قرية يجو بالحبشة .","s":"في شهر ديسمبر رفض المسلِمون في قرية يجو الحبشية أعمالَ السخرة في مزارع الإقطاعيين الأحباش، كما رفضوا دفعَ ضريبة الكنيسة المتزايدةِ مِن أجلِ بناء الكنائس ومراكزِ التنصير لمحاربة الإسلام، فأمر هيلا سيلاسي بإبادةِ القريةِ أسوأَ إبادة؛ فقُتِلَ المسلمون وأُحرقت مساجِدُهم وهُدِّمَت، وزُجَّ بعُلمائِها في سجن \"ألم بقا\" وهو يعني نهايةَ الحياة."},{"id":5152,"era":"c14","t":"ارتكاب عصابات \"الأرغون\" الصهيونية مجزرة يافا بفلسطين .","s":"ارتكبت عصابات \"الأرغون\" الصهيونية مجزرةَ يافا بفلسطين؛ حيث قَتَلت 30، وجرحت 98 آخرين."},{"id":5153,"era":"c14","t":"تأسيس المؤتمر الوطني الليبي .","s":"قام السنوسي بإيقاف نشاط نادي عمر المختار، ومَنَع جميعَ الأحزاب السياسية عن العمل في ديسمبر 1947م، وألَّفَ المؤتمرَ الوطنيَّ بحجة التحدُّث باسم أهالي برقة جميعًا. إلَّا أن المؤتمر كان يتكوَّنُ مِن الجيل القديم من قادة القبائل الموالين له، وكان المؤتمرُ برئاسة أخيه محمد رضا السنوسي، وفي طرابلس كانت الأحزابُ السياسية في اضطراب وبلبلة. ووُجِدَ في المنطقة أكثر من عشرة أحزاب وجماعات ونوادي ذات أهدافٍ مخ"},{"id":5154,"era":"c14","t":"رفع قضية كشمير إلى هيئة الأمم المتحدة للفصل فيها .","s":"رُفِعَت قضيةُ كشمير -موضع النزاع بين الهند وباكستان- إلى هيئة الأمم المتحدة للفصل فيها، وقد أصدرت الأممُ المتحدة قرارها في 12 صفر 1368 هـ/ 13 ديسمبر 1948 بوَقفِ القتال بين البلدين، وإجراء استفتاءٍ تحت إشرافِ الأمم المتحدة؛ لتقريرِ مسألةِ انضمامِ كشمير إلى الهند أو باكستان."},{"id":5155,"era":"c14","t":"ارتكاب العصابات الصهيونية مجزرة فندق سميراميس بفلسطين .","s":"قامت العصابات الصهيونية بارتكابِ مجزرة فندق سميراميس بفلسطين؛ حيث فجَّرَ صهاينةٌ قنبلةً في شارع صلاح الدين في حيفا، فقتلوا 31 من الرجال والنساء والأطفال، وأصابوا 31 آخرين."},{"id":5156,"era":"c14","t":"وفاة الإمام يحيى حميد الدين حاكم اليمن .","s":"هو الإمام يحيى بن محمد بن يحيى حميد الدين الحسني العلويُّ الطالبي: ملك اليمن، الإمام المتوكل على الله ابن المنصور بالله، من أئمة الزيدية. وُلِدَ بصنعاء، وتفقَّه وتأدب بها، وخرج منها مع أبيه إلى صعدة سنة 1307 هـ وولي الإمامةَ بعد وفاة أبيه سنة 1322هـ في \"قفلة عذر\" شماليَّ صنعاء. وكانت صنعاءُ في أيدي العثمانيين فحاصرها، حتى استسلمت له حاميتها ودخلها، فأعادوا الكرَّةَ عليها، فانسحب منها، وواصل القتال"},{"id":5157,"era":"c14","t":"عبد الله بن أحمد بن الوزير، وزير الإمام يحيى حميد الدين .","s":"هو عبد الله بن أحمد بن الوزير، وزير الإمام يحيى حميد الدين، وهو ثائِرٌ من دهاة اليمن وأعيانها وشجعانها، من أسرة علوية النسب هاشمية, ومن عُلَماء الزيدية من أهل صنعاء. ولد سنة 1302هـ بقرية بيت السيد، ودرس بهجرة بيت الوزير. كان من مستشاري الإمام يحيى حميد الدين وثقاته، أرسله سنة 1343هـ على رأس جيش لإخضاعِ جموعٍ مِن العصاة في الجوف شمال صنعاء، ووجَّهه إلى التهائم، فاستسلمت له باجل والحُدَيدة، وضبط موا"},{"id":5158,"era":"c14","t":"مجزرة دير ياسين ضد المدنيين الفلسطينيين  .","s":"منذ إعلانِ قيام الكيان الصهيوني سنة 1948م مارست الحكومةُ الصهيونيةُ الضغطَ على العرب الذين بَقُوا في فلسطين واستخدمت معهم أبشَعَ الأساليب من استيلاء للأراضي والمصادرات، وإقامة المستعمرات والتهجير الإجباري للفلسطينيين، وإضافةً لهذا كله مارسوا اعتداءاتِهم على الفلسطينيين من قتل واغتيالات، وكان من أبشع تلك العمليات مجزرةُ دير ياسين التي ارتكبها اليهودُ في شهر نيسان 1948م؛ قتلوا فيها الأبرياء من السكا"},{"id":5159,"era":"c14","t":"ارتكاب عصابات الهاجاناه الصهيونية مجزرة قرية ناصر الدين قضاء طبريا بفلسطين .","s":"قامت عصابات الهاجاناه الصهيونية بارتكاب مجزرةٍ جديدةٍ في حقِّ الشعب الفلسطيني، وذلك في قرية ناصر الدين قضاء طبريا بفلسطين؛ حيث قتلت 50 فلسطينيًّا من سكان القرية البالغ عددهم 90."},{"id":5160,"era":"c14","t":"بريطانيا تلغي انتدابها على فلسطين  .","s":"كانت الأممُ المتحدة أوصت بتقسيم فلسطين إلى دولتين عربية ويهودية عام 1366هـ، ورفضت الدولُ العربيةُ والإسلاميةُ هذا القرارَ، ثمَّ عَمَّت البلادَ الفلسطينيةَ ثورةٌ ضِدَّ المستعمِرِ البريطاني وضِدَّ الصهيونية، واحتدم النزاعُ بين العرب واليهود الصهاينة، وشهدت فلسطين ستة أشهر من المعارك والقتال العنيف، ثم على إثرِ ذلك انسحبت القواتُ البريطانية من فلسطين في 14 مايو 1948م، وكانت مدينة القدس هي أولَ مدينة "},{"id":5161,"era":"c14","t":"ارتكاب العصابات الصهيونية مجزرة قرية أبو شوشة قضاء القدس بفلسطين .","s":"ارتكبت العصاباتُ الصهيونيةُ مجزرة قرية أبو شوشة قضاء القدس بفلسطين، وراح ضحيَّتَها 50 قتيلًا من النساء والرجال والشيوخ والأطفال، وقد ضُرِبت رؤوس العديد منهم بالهراوات، وأطلق جنود \"لواء جفعاتي\" الصهيوني -الذي نفذ المذبحة- النارَ على كلِّ شَيءٍ متحَرِّك دون تمييز، وحتى الحيوانات لم تسلَمْ من المجزرة."},{"id":5162,"era":"c14","t":"إعلان قيام دولة الكيان الصهيوني يوم إنهاء الانتداب البريطاني على فلسطين .","s":"تم الإعلانُ عن قيام دولة الكيان الصهيوني يوم 14 مايو 1948م، وفيما يلي نصُّ إعلان الكيان نفسِه، ونحن نذكُرُه هنا لأغراضِ المعرفةِ بالعَقلِ الصهيوني ومبادئِه في تأسيس دولته.. بصَرفِ النظر عما يعتريه من تشويهٍ متعَسِّف للتاريخ والجغرافيا. \"أرضُ إسرائيل هي مهْدُ الشعب اليهودي، هنا تكوَّنت شخصيتُه الروحية والدينية والسياسية، وهنا أقام دولةً للمرة الأولى، وخَلَق قيمًا حضارية ذات مغزًى قومي وإنساني جامع،"},{"id":5163,"era":"c14","t":"إنشاء جيش الدفاع الإسرائيلي  .","s":"بعد إعلانِ قيامِ ما يُعرَفُ بدولة الكيان الصهيوني في 15 مايو 1948م، قَرَّرت أولُ حكومة صهيونية بزعامة رئيس الوزراء الصهيوني ديفيد بن جوريون تشكيلَ \"جيش الدفاع الإسرائيلي\" من عناصر عصابة \"الهاجاناه\" وهي عصابة صهيونية تأسَّست في مدينة القدس كرَدِّ فعل للثورة التي اندلعت في فلسطين من العام 1920م إلى العام 1921م، وكان الهدفُ من إنشائها العمَلَ على حماية المغتصِبين اليهود المهاجرين إلى فلسطين، وطرد الس"},{"id":5164,"era":"c14","t":"نكبة 48 الحرب العربية الإسرائيلية الأولى وخسائر العرب .","s":"بعد إعلان قرارِ التقسيم تزايدَ الصِّراعُ مع اليهود أكثَرَ، ثم بلغ أوْجَهُ عند انتهاء الانتداب البريطاني على فلسطين، وكانت الأوضاعُ العربيةُ وشعوبُها المستقِلَّة استقلالًا صوريًّا غير قادرة على أعمالٍ موازية لِما يقوم به اليهود وبجانبهم بريطانيا، وخاصة من ناحية التسليح؛ حيث وصل عدد اليهود الذين يستطيعون القتال أكثر من سبعين ألفًا مقابل عشرين ألفًا من الجيوش العربية، بالإضافة للفلسطينيين والمتطوِّعي"},{"id":5165,"era":"c14","t":"بدء الهدنة الأولى في فلسطين بين الجيوش العربية والعصابات اليهودية أثناء حرب 1948م .","s":"بعد أن زحفت الجيوشُ العربية على فلسطين في حرب 48 من الشمال والشرق والجنوب، وأعلنت حالة الحصار البحري، لم يمضِ أسبوعان على الزحفِ العربي حتى كانت الجيوشُ العربية تسيطِرُ على المناطق المخصَّصة للعرب طبقًا لمشروع التقسيم، باستثناء يافا وقِسمٍ من الجليل الأعلى، وبات متوقعًا أن تتمكن القوات العربية من إنهاء عملياتها الحربية في فترة قصيرة، فاستنجدت السلطاتُ الصهيونية والولايات المتحدة الأمريكية بهيئة ال"},{"id":5166,"era":"c14","t":"قيام وحدة كوماندوز صهيونية بارتكاب مجزرة بمدينة اللّد بفلسطين .","s":"ارتكَبَت وَحدة كوماندوز صهيونية بقيادة \"موشيه ديان\" مجزرةً في مدينة اللُّد بفلسطين؛ حيث اقتحمت المدينة وقت المساء تحت وابل من القذائف المدفعية. واحتمى المواطِنون من الهجوم في مسجد دهمش، وقُتِلَ في الهجوم 426 فلسطينيًّا. ولم يتمَّ الاكتفاء بذلك بل بعد توقُّف عمليات القتل اقتِيدَ المدنيون إلى ملعب المدينة؛ حيث تم اعتقال الشباب، وأعطيَ الأهالي مهلة نصف ساعة فقط لمغادرة المدينة سيرًا على الأقدام دون م"},{"id":5167,"era":"c14","t":"قيام ثورة في أندونيسيا وإعلانها قيام حكومة تابعة للشيوعيين .","s":"كان عامر شرف الدين الشيوعي رئيسًا للحكومة ووزيرًا للدفاع في أندونيسيا، ولكنه أُقيل من منصبه بعد الضَّغطِ الشعبي على الرئيس أحمد سوكارنو الذي عيَّنه بنفسه، فثار الشيوعيون، وألف الحزبُ الشيوعي الأندونيسي مجلسًا للثورة وقيادة عليا وقَدَّم أحدهم هو عيديد مذكرةً للحكومة للمطالبة بالتبادل السياسي مع الدول الشيوعية، وبالتأميم، ومصادرة الأملاك، وإقالة الحكومة، والسير مع الدول الماركسية، والانضمام إلى المع"},{"id":5168,"era":"c14","t":"وفاة محمد علي جناح مؤسس دولة باكستان وتولي نظام الدين .","s":"هو محمد علي جناح أول حكام باكستان المستقِلَّة في 8 ذي القعدة (11 أيلول 1948م)، لقَّبه مواطنوه بلقب \"قائد أعظم\" وهو مؤسس دولة باكستان. ولد في 27 ديسمبر سنة 1876، وكان أبوه تاجرًا متوسط الثراء، وعضوًا في أسرة من الخوجات تعيش في كراتشي. وتلقى محمد تعليمَه الأول في بومباي، ثم في مدرسة الإسلام السندية، وفي المدرسة العليا لجماعة المبعوثين المبشرين في كراتشي. ولَمَّا حصل على إجازة القبول في الجامعة بُعِث"},{"id":5169,"era":"c14","t":"مجزرة البعنة ودير الأسد على يد العصابات الصهيونية .","s":"في الساعة العاشرة صباحًا في 27 ذي الحجة / 31 أكتوبر دخلت وَحدةٌ من جيش العدو الإسرائيلي إلى قريتي (الدير والبعنة) وقامت بتجميعِ السكان في حقل بين القريتين، وبحلولِ وقت العصر أصيب الأطفالُ والشيوخ بالإنهاك الشديد، وكانوا في أشد الحاجة إلى الماء، وطلب بعض الشباب الإذن من جنود الوحدة المعادية لإحضار بعض الماء من بئر قريبة، ليسدُّوا رمق الشيوخ والأطفال والنساء، واستعد لهذه المهمة شابان من قرية (دير ال"},{"id":5170,"era":"c14","t":"مجزرة الدوايمة على يد العصابات الصهيونية. .","s":"بعد أداء صلاة الجمعة والناس غافلون مُنهَمِكون في أسواقهم وأشغالهم وحقولهم، إذ بالجنودِ الصهاينة يقتَحِمون قريةَ الدوايمة التي تبعُدُ عن الخليل نحو 24 كيلو متر ويحاصِرونَها، فقتلوا المئات من الشيوخ والشباب، وحطَّموا رؤوس الأطفال بالهراوات أمام أمهاتهم، ثم قتلوا الأمهات. واعتدَوا على النساء أمام ذويهن دون أن يعبؤوا بصياحهنَّ واستنجادهن، يقول أحد قادة حزب المابام الصهيوني (إسرائيل جاليلي) إنه شاهَدَ "},{"id":5171,"era":"c14","t":"الأمم المتحدة تقرر تدويل مدينة القدس .","s":"منذ صدورِ قرار التقسيم رقم 181 عن الأمم المتحدة الصادر في 29 نوفمبر 1947م (وهو أول قرار دولي يصدُرُ عن الأمم المتحدة يتناول القضية الفلسطينية) بدأت القدسُ تأخذ خصوصيةً معينة في الصراع العربي الإسرائيلي؛ حيث عالج القرار في جزئه الثالث قضية القدس، وجعل منها كيانًا منفَصِلًا خاضعًا لنظام دولي خاص يتبَعُ إدارة الأمم المتحدة، وعين مجلس وصاية دولي ليقوم بأعمال السلطة الإدارية نيابةً عن الأمم المتحدة، وق"},{"id":5172,"era":"c14","t":"اكتشاف نفط السفانية تحت الماء بين السعودية والكويت .","s":"في هذا العام تقدَّمت إحدى شركات التنقيب عن النفط لحكومة الملك عبد العزيز بمشروع البحثِ عن النفط تحت الماء في الخليج العربي، فأذِنَ عبد العزيز بمنحها الامتيازَ بالتنقيب فيما سمِّيَ بالمنطقة المحايدة بين السعودية والكويت، وبُشِّرَ عبد العزيز في أواخر عام 1370هـ / 1951م باكتشاف الآبار النفطية في حقل السفانية، على منتصف الطريق بحرًا، بين شواطئ المملكة وشاطئ الكويت، وتم الاتفاق بين الحكومتين على اقتسام"},{"id":5173,"era":"c14","t":"مقتل حسن البنا .","s":"هو حسن بن أحمد بن عبد الرحمن البنا، ولِدَ سنة 1324هـ / 1906م في المحمودية بالقُربِ من الإسكندرية، ووالده هو الشيخ المعروف بالساعاتي، صاحب كتاب الفتح الرباني. نشأ حسن البنا في ظِلِّ عائلة متدينة، تخرَّج من مدرسة المعلِّمين الأولية في (دمنهور)، والتحق بدار العلوم وأنهى دراسته فيها عام 1927. عُيِّنَ بعد ذلك معلِّمًا للغة العربية في المدرسة الابتدائية الأميرية في الإسماعيلية، وبَقِيَ في هذه الوظيفة إل"},{"id":5174,"era":"c14","t":"إعلان استقلال برقة في ليبيا .","s":"بعد أن تأسَّس المؤتمر الوطني البرقاوي، وكانت دعوتُه أصلًا إلى استقلال إقليم برقة شرق ليبيا، وقيام حكومة دستورية فيها برئاسة محمد إدريس السنوسي، وكان هذا المؤتمَرُ هو الهيئة السياسية الوحيدة المعتَرَف بها، وقد عُقِدَ هذا المؤتمر في بنغازي في 5 شعبان 1368هـ / 1 حزيران 1949م، وأعلِنَ فيه عن مَولِد دولة برقة وأيد المؤتمر بالإجماع واعترفت إنجلترا بالدولة الجديدة مباشرة، أما الشعبُ فقد أبدى استياءً عامّ"},{"id":5175,"era":"c14","t":"قيام العقيد حسني الزعيم بالانقلاب العسكري الأول في سوريا  .","s":"قام العقيد حسني الزعيم بأول انقلاب عسكري في سوريا، ويعَدُّ الانقلاب الذي قاده العقيد \"حسني الزعيم\" في سوريا في 29 شعبان سنة 1368هـ/ 30 مارس هو الانقلابَ الأوَّلَ في تاريخ الدول العربية الحديثة. فبعد رحيلِ الفرنسيين عن سوريا كان الأمريكيون يخشون من تنامي التيارات العقائدية داخِلَ البلاد، خاصة الشيوعية واليسارية، ورأى الأمريكيون أنَّ تَرْكَ المسرح السوري للقوى السياسية للتفاعل فيه سيقود حتمًا إلى أن"},{"id":5176,"era":"c14","t":"الانقلاب العسكري الثاني في سوريا بقيادة العقيد سامي الحناوي  .","s":"بدأ الأمريكان بالتخلِّي عن مساندة حسني الزعيم، وسعيهم للتخلص منه، بعدما أبدى قدرًا من الرغبة والمساعي للخروج عن الوصاية الأمريكية، فرأى الأمريكان أنه ما دام الجيشُ هو المؤسَّسةَ التي تملِكُ القوَّةَ، وتحتكر أدواتَها، فعليهم أن يتحَرَّكوا من داخِلِه للتخلُّصِ من الزعيم وبسرعة، وتحقَّق للأمريكيين ما أرادوا؛ حيث لم يمضِ إلا وقت قليل حتى وقع انقلابٌ مضادٌّ بقيادة العقيد سامي الحناوي في 20 من شوال 14 أ"},{"id":5177,"era":"c14","t":"وفاة حسني الزعيم حاكم سوريا .","s":"هو حسني ابن الشيخ رضا بن محمد بن يوسف الزعيم؛ ثائر سوري من أهل دمشق، من القواد العسكريين. ولد حسني الزعيم في حلب سنة 1315هـ/ 1897م، وهو كردي الأصل، وكان والِدُه مفتيًا في الجيش العثماني. حكم الزعيم سوريا حكمًا مُطلقًا مدة 136 يومًا. تعلَّم الزعيم في المدرسة الحربية بالأستانة، وأصبح ضابطًا في الجيش العثماني، واعتقله الحلفاءُ أثناء الحرب العالمية الأولى، ثم التحقَ بجيش الثورة العربية بقيادة فيصل بن "},{"id":5178,"era":"c14","t":"العمل على توحيد مملكتي العراق والأردن .","s":"كان الملك عبد الله بن الحسين مَلِكُ الأردن قد وضع أُسُسَ الاتحاد بين المملكتين الهاشميتين، وبعث بهذه الأسس إلى الوصيِّ على ملك العراق عبد الإله، والملك فيصل الثاني، وأرسل الأسُسَ مع وزير بلاطه سمير الرفاعي في 6 شعبان عام 1369هـ / 2 حزيران ليرى الوصيُّ فيها رأيَه، وكان فيها التعاون العسكري وإزالة الموانع الجمركية والمرور، وتنسيق المعارف، وتوحيد السياسة الخارجية، وغيرها من الشروط، ودرست الحكومةُ الع"},{"id":5179,"era":"c14","t":"قيام دولة جمهورية أندونيسيا .","s":"كانت أندونيسيا اتحادية من الدويلات التي صنعَتْها هولندا، فكادت الحربُ أن تقومَ بينها فتقَدَّم محمد ناصر أحدُ زعماء حزب ماشومي في المجلس النيابي باقتراحٍ عُرِفَ باقتراح محمد ناصر الوحدوي، ويقضي بأن تقومَ كُلُّ دولة من دول الاتحاد بما في ذلك جمهورية أندونيسيا (جمهورية جوكاجكرتا) بحلِّ نفسِها، ثم تقومُ على أنقاض الجميعِ دولة جمهورية أندونيسيا، وقد حصلت الموافقةُ على هذا الاقتراح بالإجماعِ، وتم ذلك وا"},{"id":5180,"era":"c14","t":"تأسيس كلية الشريعة بمكه المكرمة .","s":"كُلِّيَّةُ الشَّريعةِ بمكَّةَ المكَرَّمةِ أوَّلُ كُلِّيَّةٍ شَرعيَّةٍ تُؤَسَّسُ في المملَكةِ العَربيَّةِ السُّعوديَّةِ، وكان ذلك في عَهدِ المَلِكِ عبدِ العزيزِ رحمه الله، تغَيَّرَ اسمُها إلى كُلِّيَّةِ الشَّريعةِ والتَّربيةِ عام 1373هـ تحتَ إشرافِ وَزارةِ المعارِفِ، ثمَّ انفَصَلت عنها كُلِّيَّةُ التَّربيةِ عام 1382هـ، وأصبح اسمُها كُلِّيَّةَ الشَّريعةِ والدِّراساتِ الإسلاميَّةِ، وتحتَها ثلاثةُ أقس"},{"id":5181,"era":"c14","t":"اعتراف بريطانيا بضم الأردن للضفة الغربية .","s":"اعترفت بريطانيا بضَمِّ الأردن للضفة الغربية. وتبلغُ مساحتها 5.878 كم أي 21,7% من مساحة فلسطين، لكنَّ إسرائيل استولت عليها بعد نكسة 1967م."},{"id":5182,"era":"c14","t":"مشكلة منطقة البريمي مع الإنجليز في عهد الملك عبد العزيز .","s":"البريمي واحةٌ في جنوب شرقي المملكة العربية السعودية على الحدودِ مع عمان والإمارات، وهي تابعة للأحساءِ، وعندما طلب الملكُ عبد العزيز من مهندسي شركة الزيت العربية الأمريكية (أرامكو) التنقيبَ فيها عن النفط منَعَت بريطانيا المنقِّبين عن مواصلة العمل باسمِ بَعضِ محميَّاتِها في الخليج؛ بدعوى أنَّها من الأراضي غير المتَّفَقِ على تبعيتها، ووافق الملك عبد العزيز حسمًا للنزاع مع الإنجليز على سحب المنقبِّين "},{"id":5183,"era":"c14","t":"محمود جلال بايار يصبح رئيسًا لتركيا بعد فوزه بالانتخابات .","s":"بقي عِصمت إينونو على نَهجِ سَلَفِه مصطفى كمال؛ إذ إنَّ حِزبَه الذي أسَّسه مصطفى -حزب الشعب الجمهوري- حكم البلادَ وتعَسَّف وأساء حتى كَرِهَه الناس، وكرهوا بقاءَ التمجيد للهالِكِ أتاتورك، ولَمَّا انتهت الحرب العالمية الثانية وأعطِيَ النَّاسُ بعض الحرية حصل خلافٌ بين رئيس الجمهورية عصمت إينونو وبين محمود جلال بايار أدَّى إلى الانشقاقِ في داخِلِ الحزب الذي ينتميان إليه، وهو الحِزبُ الحاكمُ حِزبُ الشعب"},{"id":5184,"era":"c14","t":"معاهدة الدفاع والتعاون المشترك لدول الجامعة العربية .","s":"وقَّعَت أعضاءُ دُول الجامعة العربية معاهدةَ دفاع وتعاون مشترك بينها، نصَّت على الآتي: إنَّ حكومات حضرة صاحب الجلالة مَلِك المملكة الأردنية الهاشمية، وحضرة صاحب الفخامة رئيس الجمهورية السورية، وحضرة صاحب الجلالة ملك المملكة العراقية، وحضرة صاحب الجلالة ملك المملكة العربية السعودية، وحضرة صاحب الفخامة رئيس الجمهورية اللبنانية، وحضرة صاحب الجلالة ملك المملكة المصرية، وحضرة صاحب الجلالة ملك المملكة ال"},{"id":5185,"era":"c14","t":"تحرير أرتيريا من الاستعمار الإيطالي ودخولها في اتحاد مع الحبشة .","s":"كانت أرتيريا تحت الاستعمار الإيطالي، وعندما تحرَّرت الحبشة من الاستعمار بَقِيَت باقي المستعمرات الإيطالية لم تتحَرَّر، وكانت الحبشة تطالِبُ بضَمِّ هذه المستعمرات لها، وطال بحثُ قضية أرتيريا في أروِقةِ الأمم المتحدة وأخيرًا صدر قرارها في 22 صفر / 2 ديسمبر بإقامةِ اتحاد سياسي بين أرتيريا والحبشة كحَلٍّ يرضي بريطانيا؛ حيث لم تتخَلَّ عن الحبشة كليًّا فتعطي أرتيريا استقلالَها الذاتي وترتَبِطُ مع الحبشة"},{"id":5186,"era":"c14","t":"الحكومة الباكستانية تطالب الجماعة الإسلامية بوضع دستور إسلامي .","s":"أدَّت مطالبة الجماعة الإسلامية بقيادة أبي الأعلى المودودي تطبيقَ الشريعة الإسلامية إلى اعتقالِ المودودي وعددٍ من رموز الجماعة، ثم عَمِلت الحكومة الباكستانية على وضع أهدافٍ تحدِّد الوجهةَ الإسلامية لباكستان وذلك في 13 جمادى الأولى 1368 هـ / 12 مارس 1949م. وبعد عام في 11 شعبان 1369 هـ / 28 مايو 1950م اضطرت الحكومةُ إلى إطلاق سراح المودودي وزملائه، وبدأت الجماعةُ الإسلامية دراسةَ قرار الأهداف الموضوع"},{"id":5187,"era":"c14","t":"تشكيل أول حكومة اتحادية مؤقتة في ليبيا برئاسة محمود المنتصر. .","s":"أعلنت الجمعيةُ التأسيسيَّةُ في ليبيا عن تشكيلِ أوَّلِ حكومة اتحادية لليبيا مؤقَّتة في طرابلس برئاسة محمود المنتصر، وفي يوم 12/10/1951م نُقِلَت إلى الحكومة الاتحادية والحكومات الإقليمية السلطة كاملة ما عدا ما يتعلَّقُ بأمور الدفاع والشؤون الخارجية والمالية، فالسُّلُطاتُ المالية نُقِلت إلى حكومة ليبيا الاتحادية في 15/12/1951م، وأعقَبَ ذلك في 24 ديسمبر 1951م إعلان الدستور واختيار إدريس السنوسي ملِكًا"},{"id":5188,"era":"c14","t":"رفض مصر قرار إلغاء مجلس الأمن الدولي على السفن الإسرائيلية .","s":"أصدر مجلِسُ الأمن الدولي قرارًا بإلغاء القيود التي تفرِضُها دولةُ مِصرَ على ملاحةِ السفن الإسرائيلية في قناة السويس، لكِنَّ مصر رفضت هذا القرارَ."},{"id":5189,"era":"c14","t":"استقالة بشارة خليل الخوري من رئاسة لبنان .","s":"استقال الرئيسُ اللبناني بشارة خليل الخوري من رئاسة لبنان، وذلك بعد 9 سنوات قضاها في الحكم، وكان قد انتُخِبَ رئيسًا للجمهورية سنة 1943م، بعد أن أسهم في التوفيق بين الطوائف اللبنانية، وفي المقاومة التي أدَّت إلى الاستقلال وجلاء الفرنسيين. وأُجبِرَ على الاستقالة بعد مظاهرات ضخمة على خلفية اتهامه بالفساد؛ وخوفًا منه على تفاقم الأمور استدعى قائِدَ الجيش فؤاد شهاب، وقَدَّم إليه استقالتَه بعد أن كلَّفه ب"},{"id":5190,"era":"c14","t":"حركة الضباط الأحرار الأردنيين  .","s":"تنظيمٌ سِلمي تأسس في خمسينيات القرن العشرين من قِبَلِ مجموعة من الضباط الأردنيين الوطنيين بمباركة الملك حسين، وأهداف الحركة تتمثَّلُ في إلغاء المعاهدة الأردنية البريطانية، وتعريب قيادة الجيش العربي بطرد الجنرال الإنجليزي غلوب باشا، وقد تمَّ للحركة ما خطَّطت له، وقد تعرضت الحركة إلى وشاية بريطانية أمريكية أنَّ مِن أهداف الحركة قلبَ نظام الحكم كحركة الضباط في مصر، فاعتقل الملك حسين بعض الضباط، وفَرّ"},{"id":5191,"era":"c14","t":"تنحية الحاكم الباكستاني نظام الدين وتولية غلام محمد .","s":"اغتيل رئيسُ وزراء باكستان لياقت علي خان في 16 محرم 1371هـ / 16 أكتوبر، فتَمَّ تعيين غلام محمد حاكِمًا على باكستان، وكان قبل ذلك وزيرًا للمالية، وكلف الحاكم السابق خواجا نظام الدين برئاسة الوزراء."},{"id":5192,"era":"c14","t":"قيام أديب الشيشكلي بالانقلاب العسكري الثالث في سوريا .","s":"قام العقيد أديب الشيشكلي بانقلاب عسكري ثالث في سوريا، واستولى على السلطة، وقام بحَلِّ الأحزاب السياسية، وتشكيل \"حزب حركة التحرير العربي\". وقد قام الشيشكلي بانقلابِه العسكري الأول هذا في 19 ديسمبر، لكِنْ وقع انقلابٌ عسكري ضِدَّ الشيشكلي في 25/2/1954م، فاضطر إلى مغادرة سوريا متَّجِهًا إلى لبنان."},{"id":5193,"era":"c14","t":"استقلال ليبيا .","s":"اتَّفَقت بريطانيا وإيطاليا في 10 مارس 1949م على مشروع (بيفن سيفورزا) الخاص بليبيا الذي يقضي بفرضِ الوصاية الإيطالية على طرابلس، والوصاية البريطانية على برقة، والوصاية الفرنسية على فزان، على أن تُمنَح ليبيا الاستقلالَ بعد عشر سنوات من تاريخ الموافقةِ على مشروع الوصاية، وقد وافقت عليه اللجنةُ المختصة في الأمم المتحدة في يوم 13 مايو 1949م وقُدِّمَ إلى الجمعية العامة للأمم المتحدة للاقتراع عليه، ولكِن"},{"id":5194,"era":"c14","t":"حريق القاهرة بتدبير من الاحتلال البريطاني في مصر .","s":"حريقُ القاهرة هو حريق هائل اندلع في عدةِ منشآت في مدينة القاهرة عاصمة مصر. وفي خلال ساعات قلائل التهمت النار نحو 700 محل وسط المدينة؛ بينها أكبر وأشهر المحلات التجارية في مصر، ومكاتب لشركات كبرى، وشققًا سكنية، وفنادق مشهورة، منها: فندق متروبوليتان، وفيكتوريا، ودورسينما، ومعارض كبرى للسيارات، وأندية ومقاهي ومطاعم. وقد أسفر هذا الحادث عن قتلى وجرحى  وتشريدِ عِدَّة آلاف من العاملين في المنشآت التي اح"},{"id":5195,"era":"c14","t":"الحكومة التركية تسمح بدخول السلالة العثمانية عدا أبناء السلاطين .","s":"سمحت الحكومة التركية بدخول جميع أعضاء السلالة العثمانية -عدا الأمراء أبناء السلاطين- إلى تركيا بعد إلغاء الخلافة العثمانية في مارس 1923م، وطَرْد سلالة بني عثمان إلى خارج تركيا، بعد ما حكموا البلاد مدة 963 عامًا، منها 407 أعوام هي مدة الخلافة."},{"id":5196,"era":"c14","t":"ثورة الضباط الأحرار، وتنازل الملك فاروق عن الملك ومغادرته لمصر .","s":"تنظيم الضباط الأحرار في الجيش المصري هو تنظيم  بقيادة اللواء محمد نجيب ومعه جمال عبد الناصر الذين كانوا على صلة وقتها بجماعة الإخوان المسلمين،  قام التنظيم بانقلاب مسلح لم ترق به دماء، وسيطر على المرافق الحيوية في البلاد وأذاع البيان الأول\" للثورة \" بصوت أنور السادات وأجبر التنظيم الملك فاروق على التنازل عن العرش لولي عهده الأمير أحمد فؤاد ومغادرة البلاد، وكانت إدارة البلاد بيد مجلس قيادة الثورة ا"},{"id":5197,"era":"c14","t":"الحبشة تحتل أرتيريا .","s":"بعد أزمة أرتيريا مع الحبشة وقرارِ هيئة الأمم عام 1370هـ بقيامِها باتحادٍ لامركزيٍّ مع الحبشةِ، وهذا يعني أن تتمتَّعَ أرتيريا بسلطات تشريعية وتنفيذية وقضائية في الشؤون الداخلية، وأما خارجيًّا فمرتبطة بالحبشة، وكذلك ماليًّا ودفاعيًّا، ولم ترضَ الحبشةُ كليًّا بدمج أرتيريا بها، بل تريد ابتلاعَها كأرض لها، فأمر الإمبراطور الحبشي هيلا سيلاسي جيشَه عام 1952م باحتلال أرتيريا وتواطأت بريطانيا معها علنًا، ف"},{"id":5198,"era":"c14","t":"ثورة الشعب المغربي ضد الفرنسيين .","s":"قدَّمت الدولُ العربية احتجاجًا إلى هيئة الأمم المتحدة، وإلى فرنسا؛ على الأعمال التي تقومُ بها فرنسا في المغرب، ورفعت مذكرات الاحتجاج من السعودية ومصر وسوريا والأردن، غير أنَّ فرنسا رفضت كلَّ ذلك، وأما مَلِكُ المغرب الملك محمد الخامس فقد قام بتقديمِ مذكِّرة إلى رئيس فرنسا أيَّدَ فيه مطالِبَ شَعبِه بالاستقلال، وإلغاء الحماية الفرنسية، ورفضت فرنسا كلَّ ذلك أيضًا، وقدَّمت العراق مذكِّرةً إلى هيئة الأم"},{"id":5199,"era":"c14","t":"إلغاء السلطنة في المالديف وإعلان الجمهورية .","s":"أُعلنت الجمهوريةُ في المالديف في يناير 1953م بعد أن أُلغِيَت السَّلطنة في العام نفسه، وانتُخِبَ محمد أمين ديدي أولَ رئيسٍ للجمهورية."},{"id":5200,"era":"c14","t":"تشكيل لجنة السودنة .","s":"لجنةٌ شُكِّلت من عضوٍ مصري وآخر بريطاني وثلاث أعضاء سودانيين؛ لوضع إجراءاتِ إنهاء الحكم الثنائي (المصري البريطاني للسودان) بإشرافٍ دوليٍّ، وقد ورد لفظُ لجنة السَّوْدَنة في الاتفاقية التي وُقِّعَت بين مصر وبريطانيا بشأن الحكم الذاتي، وتقرير حق المصير للسودان."},{"id":5201,"era":"c14","t":"الموافقة على إعطاء السودان حق تقرير المصير .","s":"وقَّعت الحكومتان المصرية والبريطانية اتفاقيةً يتِمُّ بمقتضاها منح السودان حقَّ تقرير المصير في خلال ثلاث سنوات كفترةٍ انتقالية تطبيقًا لبنود الاتفاق. وقد تمَّت أول انتخابات نيابية في السودان في أواخر عام 1953م، وتم تعيين أول حكومة سودانية وذلك في 9 يناير 1954م. بالإضافة إلى تركِ المناطق التي استحوذ عليها البارونات في أيديهم؛ وفي 19 أغسطس قامت وحدات من الجيش السوداني الجنوبي بالتمَرُّد، وتم القضاء "},{"id":5202,"era":"c14","t":"تتويج حسين بن طلال ملكًا للأردن .","s":"بعد مَقتلِ الملك عبد الله تُوِّجَ ابنُه الأكبر طلال بن عبد الله خلفًا لوالِدِه، ولكن خلال عام أجبره البرلمان الأردني على التنحِّي عن المُلكِ بدعوى أنَّه مصاب بمرض عقليٍّ أو نفسي، فأُعلن ابنُه الأمير حسين ملكًا على الأردن، وذلك في 11 أغسطس 1952 وكان عمره آنذاك 17 سنة، ولم يكنْ يبلغ السن القانونية، فشُكِّلَ مجلِسٌ للوصاية على العرشِ، وتم تتويجُه ملِكًا في 2 مايو عام 1953."},{"id":5203,"era":"c14","t":"وفاة الشريف عبد الله بن الحسين ملك الأردن  .","s":"الشريف عبد الله بن الحسين بن علي بن محمد الحسني الهاشمي، من آل عون أمير شرقيَّ الأردن، ثم ملك المملكة الأردنية الهاشمية. ولد بمكة سنة 1299هـ، وتلقى مبادئ العلوم في الأستانة أيام إقامة أبيه فيها، وعاد مع أبيه إلى الحجاز سنة 1326ه، وسمي نائبًا عن مكة في مجلس النواب العثماني سنة 1327، فكان يقيم بعض شهور السنة في العاصمة العثمانية، وبقيَّتَها في الحجاز. وقام مع والده في الثورة على الترك سنة 1334ه / 19"},{"id":5204,"era":"c14","t":"إعلان النظام الجمهوري في مصر برئاسة محمد نجيب .","s":"بعد أن تنازل المَلِكُ فاروق مجبَرًا عن الملك لابنِه ولي العهد أحمد فؤاد الثاني، لم يكن للملك الجديد أيُّ عمل؛ إذ كان ما يزال طفلًا تحت الوصاية، وكان الأمر والنهي كله بيد قادةِ ثورة يوليو الضبَّاط الأحرار الذين أجبروا أباه على التنازُلِ، وفي 6 شوال / 18 حزيران أصدر مجلِسُ قيادة الثورة قرارًا بإلغاء النظام الملكي وإعلان النظامِ الجمهوري بمصر، وبعد أن عدَّد القرارُ سلبياتِ الأسرةِ الحاكمة من خيانةٍ و"},{"id":5205,"era":"c14","t":"فرنسا تنفي السلطان المغربي محمد الخامس إلى جزيرة كورسيكا .","s":"لم تتوقَّف المطالِبُ المغربيَّةُ بالاستقلالِ طوالَ السنواتِ الماضيةِ، والمَلِكُ يؤيِّدُها، فكاد الفرنسيون للمَلِك فألزموا الكثيرَ من الوجهاء والقادة على التوقيعِ على عريضة تطالِبُ بخَلعِ الملك؛ لمعارضته الإصلاحاتِ وعدمِ أهليتِه، وكانت فرنسا قد قرَّرت التخَلُّصَ من الملك بأيِّ صورة، فأَرسَلَت له في 9 ذي الحجة - أي يوم عرفة- وثيقةً عن طريق الحاكم العام الفرنسي تتضَمَّنُ تخييره بين التنازل عن الملك أ"},{"id":5206,"era":"c14","t":"وفاة الملك عبد العزيز آل سعود ملك المملكة العربية السعودية .","s":"هو المَلِكُ عبد العزيز بن عبد الرحمن بن فيصل بن تركي بن عبد الله بن محمد بن سعود آل مقرن: مَلِكُ المملكة العربية السعودية، ومؤسِّسُ الدولة السعودية الثالثة، وأحدُ رجالاتِ العَصرِ. وُلِدَ في الرياض عام 1293هـ / 1876م، ودَولةُ آبائِه في ضَعفٍ وانحلال، وصَحِبَ أباه في رحلته إلى البادية، يطارده محمد بن عبد الله ابن رشيد، واستقَرَّ مع أبيه في \"الكويت\" سنة 1309ه (1891 م) وشبَّ فيها. وشنَّ الغارات على آل"},{"id":5207,"era":"c14","t":"إعادة نظام السلطنة للمالديف وتنصيب محمد فريد ديدي سلطانا .","s":"لم يدُمِ النظام الجمهوري في المالديف كثيرًا؛ حيث طُرِح موضوعُ رئاسة الجمهورية على الجمعية الوطنية التي صوَّتَت بإعادة السلطنة، فتمَّ ذلك ونُصب محمد فريد ديدي سلطانًا على المالديف في شباط 1954م خلَفًا لابن عمِّه الرئيس السابق."},{"id":5208,"era":"c14","t":"تنحي رئيس مصر محمد نجيب وتولي جمال عبد الناصر .","s":"زادت مُضايقاتُ بعضِ رجالِ الثَّورةِ -وخاصةً جمال عبد الناصر، وجمال سالم، وصلاح سالم- لرئيس الجمهورية محمد نجيب، فكانت تُختصَرُ كلماتُه في وسائل الإعلام، بل وتُهمَلُ أحيانًا، ويُطلَبُ منه إبعادُ بعض أعوانه دون سبب، بل ويُشتَمُ أمام أنصاره ويُطلَبُ منهم إبلاغه بذلك! وأمام هذه المضايقات قَدَّم الرئيس محمد نجيب استقالتَه إلى مجلس الثورة، وبعد ثلاثة أيام صدر قرارُ مجلس قيادة الثورة بقَبولِ الاستقالة عل"},{"id":5209,"era":"c14","t":"تولي الأمير فيصل بن عبد العزيز رئاسة مجلس الوزراء .","s":"بعد وفاة الملك عبد العزيز رحمه الله عام 1373هـ/ 1953م بويع الأميرُ سعود بن عبد العزيز مَلِكًا على البلادِ خَلَفًا لوالده، كما بويع الأمير فيصل بولاية العهد، وتبعًا لذلك ولتمرُّسه على شؤون الحكم والإدارة وأمور السياسة عُيِّن نائبًا لرئيس مجلس الوزراء، كما احتفظ بمركزِه السابق كوزير للخارجية، ثم عَهِدَ إليه الملك سعود في 16 ذي الحجة من هذا العام برئاسةِ مجلس الوزراء."},{"id":5210,"era":"c14","t":"الاستقلال الداخلي لدولة تونس .","s":"أعلنَ رئيس الوزراء الفرنسي \"بيير منديس فرانس\" في تونس أنَّ الحكومة الفرنسية تعترف بالاستقلالِ الداخلي للدولة التونسية."},{"id":5211,"era":"c14","t":"الاتفاقية المصرية البريطانية لجلاء القوات البريطانية من قناة السويس .","s":"جاء في المعاهدةِ التي وقَّعَها رئيس وزراء مصر وزملاؤه ووزير الدولة بوزارة الخارجية البريطانية، والسفير البريطاني بشأن قاعدة السويس، والغرض منه إقامةُ علاقات مصرية إنجليزية على أساسٍ جديدٍ مِن التعاون، وإنهاء معاهدة 1936، وجلاء القوات البريطانية جلاءً تامًّا عن الأراضي المصرية في مدة أقصاها عشرون شهرًا من تاريخ الاتفاقية، على أنه يحِقُّ للقوات البريطانية العودةُ في حالة الاعتداء على مصر، ويبقى بالت"},{"id":5212,"era":"c14","t":"محاولة اغتيال جمال عبد الناصر في حادثة المنشية .","s":"أقيمَ حَفلُ تكريم لجمال عبد الناصر ورفاقه في حديقة المنشية بمدينة الإسكندرية في 29 صفر / 26 أكتوبر، واتُّخِذَت التدابير الأمنية المعروفة، وفي أثناء الحفل تقَدَّم أحد الرجال وأطلق ثمانيةَ أعيرة نارية باتجاه جمال عبد الناصر الذي لم يُصَبْ هو ولا الوفد بأيِّ أذًى، وبدأت الصحف تتكَلَّمُ عن الحادثة وعن القبض على المجرم، وشُكِّلَت محكمةُ الشعب برئاسة جمال سالم وعضوية أنور السادات، وحسين الشافعي، فصدرت ض"},{"id":5213,"era":"c14","t":"الثورة الجزائرية الكبرى (المليون شهيد) ضد قوات الاستعمار الفرنسي .","s":"قام فرحات عباس زعيم حزب اتحاد الشعب الجزائري بتقديم بيانٍ إلى السلطات الفرنسية يطالبون فيه بحث تقرير المصير, إلَّا أن فرنسا رفضت واعتقلت فرحات عباس، ولم يمضِ وقتٌ طويل حتى استغلت فرنسا قيامَ بعض المظاهرات في عددٍ من المدن الجزائرية وإحراقها للعَلَم الفرنسي حتى ارتكبت مذبحةً رهيبة سقط فيها 45 ألف قتيل جزائري، وكان ذلك تحولًا في كفاح الجزائريين من أجلِ الحرية والاستقلال؛ فتشَكَّلت لجنة سرية من اثنين"},{"id":5214,"era":"c14","t":"تأسيس حلف بغداد .","s":"اقترحت أمريكا على إنجلترا أن تشكِّلَ أحلافًا عسكرية من الدوَلِ المحيطة بروسيا على أن تكونَ إنجلترا وأمريكا أعضاءً فيها؛ ليتمَكَّنوا من التدخُّلِ وقتما شاؤوا، واقترحت إنجلترا أن يكون المكانُ بغدادَ، فبدأت ولادة حلف بغداد، ودُعِيت له عدةُ دول غيرَ أنَّ بَعضَها رفض الحلف، وأخذ السياسيون ورجال التخطيط والمخابرات يتردَّدون على بغداد؛ من أجل الحلف وترتيباته اللازمة، وأخذوا يتَّصِلون بمن يقَعُ عليهم الاخ"},{"id":5215,"era":"c14","t":"قيام منظمة دول عدم الانحياز .","s":"بعد أن وضعت الحربُ العالميةُ الثانية أوزارَها، وظهَرَ في العالَمِ قُطبَان ثنائيَّان يتمثَّلُ في الولايات المتحدة التي تمثِّلُ المعسكر الرأسمالي والاتحاد السوفيتي الذي يقود المعسكر الشيوعي، وبدأ العالم يدخل فيما يُعرَفُ بالحرب الباردة بين القطبين، كما بدأت تتشَكَّلُ تكتُّلات أو أحلاف عسكرية تدورُ في فَلَك أحد القطبين، وفي ظِلِّ هذا الاستقطاب انبعثت حركةُ عدم الانحياز من قِبَلِ عددٍ مِن الدول التي ت"},{"id":5216,"era":"c14","t":"مؤتمر (باندونغ) والقضية الجزائرية .","s":"عُقِدَ المؤتمر في أندونيسيا وأصدر قرارًا ينُصُّ على حق الشعب الجزائري والمغربي والتونسي في تقرير المصير والاستقلال. وقد تزامن ذلك مع انتصاراتِ جيش التحرير الوطني في الشمال بقسطنطينة، وفي المنطقة الغربية من الجزائر."},{"id":5217,"era":"c14","t":"مذابح الإسرائيليين في خان يونس بفلسطين .","s":"قام الإسرائيليون بقيادة إريل شارون في هذه السنة بمذبحة مروعة في خان يونس بفلسطين، أسفَرَت عن استشهاد 36 شخصًا، وإصابة 31 من المواطنين العزَّل."},{"id":5218,"era":"c14","t":"عودة السلطان محمد الخامس إلى عرش بلاده وإعلان استقلال المغرب .","s":"لَمَّا رأت فرنسا أنَّ السيل صار كالتيار الجارف وزاد التأييدُ الدولي واستنكار أعمال فرنسا في المغرب وجرائمها فيه، اتصلت بالملك محمد الخامس في منفاه ووقَّعت اتفاقية مغربية فرنسية في \"إكس لي بان\" في شهر ذي الحجة 1374هـ / آب 1955م حدَّدت فيها كيفية عودته إلى بلاده، ثم في غُرة ربيع الثاني 1375هـ / نوفمبر 1955م أعيد إلى عرشه، ووقَّعَت فرنسا معاهدةَ الانسحاب من المغرب، وفي شعبان 1375هـ  وقَّعت إسبانيا ات"},{"id":5219,"era":"c14","t":"استقلال السودان .","s":"كانت السودانُ مرتبطةً بمصر وتعَدُّ جزءًا منها؛ فحاكمُهما واحد، وسلطانهما واحد، فهي تابعة إداريًّا لمصر، ولكِنَّ هذا الارتباط كان يشكِّلُ أحيانًا عقبة أمام المصريين في مباحثاتهم مع الإنجليز بشأنِ الجلاء عن مصر، لذلك رأى الضباطُ الأحرار قادةُ انقلاب 23 يوليو 1952م / 1371هـ في مصر أنَّ علاج مشكلة السودان كفيلٌ بحَلِّ مشكلة الجلاء عن مصر، فقامت الحكومةُ المصرية بتقديم مذكِّرة للحكومة البريطانية بشأن ا"},{"id":5220,"era":"c14","t":"مشروع إصلاح التعليم بتونس .","s":"أعدَّ الفرنسيُّ جان دوبياس مديرُ التعليم الثانوي في تونس خطةً مِن ستين صفحة سُمِّيَت مشروع إصلاح التعليم بتونس، دعا فيها إلى إلغاءِ التعليم الأصلي الديني على اعتبار أنَّه مكَلِّف ماديًّا. وقوبل هذا المشروع بالرفضِ مِن الأمين الشابي وزير التربية القومية آنذاك، واستقال من منصبه لنفس السبب؛ لأنه كان من المتحمسِّين لعملية التعريب رافضًا بذلك \"مشروع إصلاح التعليم بتونس\" بروحه الفرنسية. وبالمقابل كان دو"},{"id":5221,"era":"c14","t":"منح فرنسا تونس الاستقلال .","s":"تم التوقيع على وثيقة الاستقلال التي أنهت الحمايةَ الفرنسية على تونس، والتي وقعها الحبيب بورقيبة مع فرنسا بعد أن ربط نفسَه وبلاده باتفاقيات ثقافية واقتصادية معها، وتم تكليفه بتشكيل حكومةٍ تبدأ بالبناء على أساس أنَّ البلاد قد حَصَلت على الاستقلال."},{"id":5222,"era":"c14","t":"قيام نظام جمهوري في باكستان .","s":"كان حاكِمُ باكستان غلام محمد يعاني شللًا أفقده القدرةَ على العمل، فترك منصبه في 17 ذي الحجة 1374هـ / 1955م فقبض على السلطة الجنرال إسكندر مرزا، وفي 11 شعبان 1375هـ أُجريت الانتخابات العامة وتألفت جمعيةٌ تأسيسية لوضع الدستور، وكان أهم أعمالها أن وحَّدَت باكستان الغربية بعد أن كانت عددًا من المقاطعات، ثم جرت الانتخاباتُ الرئاسية وانتُخِب في 23 رجب 1375هـ إسكندر مرزا رئيسًا لباكستان، وفي 11 شعبان من "},{"id":5223,"era":"c14","t":"مقاطعة ليبيا دولة الاحتلال الإسرائلي في فلسطين .","s":"طبَّقَت المملكة الليبية قانونَ مقاطعة دولة الاحتلال إسرائيل، وذلك بعد الضغوط الشعبية الكبيرة التي طالبَتْها بذلك، وقامت من أجلِ ذلك بإنشاء مكتب للمقاطعة في طرابلس."},{"id":5224,"era":"c14","t":"انتخاب جمال عبد الناصر لمنصب رئاسة الجمهورية المصرية  .","s":"في جمادى الآخرة 1375هـ / 16 يناير 1956م صدر الدستورُ المؤقَّتُ بمصر بعد نهاية المرحلة الانتقالية التي تولى فيها جمال عبد الناصر السلطة على إثرِ تنازُلِ محمد نجيب عام 1954م عن السلطة. أعلن جمال عبد الناصر عن نفسِه للترشُّح لرئاسة الجمهورية، ولم يرشِّحْ أحدٌ نفسَه، أو لم يجرؤْ أن يرشِّحَ أحدٌ نفسَه، وجرى الاستفتاء الشعبي لكسبِ الصفة الشرعية بناءً على الدستور فحصل على نسبة 99.999 % من الأصوات، وبذا أ"},{"id":5225,"era":"c14","t":"جمال عبد الناصر يؤمم قناة السويس .","s":"كان أوَّلُ عمل رسميٍّ قام به جمال عبد الناصر بعد فوزِه برئاسة الجمهورية المصرية هو تأميم قناة السويس (أي نقل ملكيتها للحكومة من القطاع الخاص للعام)؛ ففي يوم 18 ذي الحجة /26 تموز 1956م وكان هذا الفعل منه ردًّا على وزير خارجية أمريكا جون فوستر دلاس في قولِه: إنَّ الاقتصاد المصري منهارٌ، ثم وضعت مصرُ يَدَها على أموال الشركة في البنك العثماني وقيمتها خمسة ملايين جنيه، وجمَّدت إنجلترا الحسابَ الجاري لم"},{"id":5226,"era":"c14","t":"نشأة حركة الضباط الأحرار في العراق .","s":"بدأ العمل داخِلَ الجيش العراقي منذ عودته من فلسطين، فتشكَّلَت عدةُ مجموعات سرية أولُها نَظَّمَها الرائد \"رفعت الحاج سري\" عام 1952م، وقد انضَمَّ معه في التنظيم عددٌ من الضباط، على الرغم من تبايُنِ توجُّهاتِهم الفكرية، ثم تشكَّلت مجموعات أخرى من التنظيمات السرية، ثم اندمجت مجموعتا بغداد والمنصور في مجموعة واحدة وتولَّى قيادتها العميد عبد الكريم قاسم، وكان لقيادات هذه المجموعات صِلاتٌ مع قيادات بعض ا"},{"id":5227,"era":"c14","t":"تشكيل \"هيئة المنتفعين\" لمعالجة مشكلة تأميم قناة السويس .","s":"قرَّرت أمريكا وفرنسا وإنجلترا عقدَ مؤتمر في لندن للدُّوَل البحرية المنتَفِعة من قناة السويس وعددُها ثمانٍ، موقعة على معاهدة استانبول إضافة إلى 16 دولة أخرى تنتفع من قناة السويس، وقرَّروا إنشاء هيئة دولية لإدارة القناة مع مصرَ تُعرَفُ بهيئة المنتفعين، مع الاعتراف بحق مصر في السيادة على القناة، وضمان دخل عادل لها، وتم إرسال لجنة برئاسة رئيس وزراء استراليا لإبلاغ عبد الناصر بالقرار غيرَ أنَّه رفض، فع"},{"id":5228,"era":"c14","t":"اتفاقية التضامن بين مصر وسوريا والأردن والسعودية .","s":"عقد عبد الناصر اتفاقياتِ دفاع مشترك مع بعض الدولِ العربية، مثل سوريا والأردن والسعودية واليمن وذلك بعد أن رفَضَت كلٌّ من أمريكا وبريطانيا وفرنسا تمويلَ بناء السد العالي مما كان سببا في تأميمَ قناة السويس في 16 أغسطس 1956م من أجل الاستفادة من عائداتها لبناءِ السد العالي."},{"id":5229,"era":"c14","t":"العدوان الثلاثي (بريطانيا وفرنسا وإسرائيل) على مصر عام 1956م .","s":"بعد أن قام جمال عبد الناصر بتأميم قناة السويس، ورفضت فرنسا وإنجلترا دفعَ الرسوم على سُفُنِها، وتم الاتفاق مع ثمانية دول أخرى كلُّها من المنتفعين بالقناة؛ تم الاتفاق بينهم على إنشاء هيئةٍ عُرِفَت بهيئة المنتفعين؛ بهدف تولي إدارة القناة مع اعترافهم بسيادة مصر عليها، وأصدر مجلِسُ الأمن قراراتٍ أخرى قبلتها مصر إلَّا أن فرنسا وإنجلترا أصرَّتا على قرار هيئة المنتفعين، وبدأ الاستعدادُ بين هذه الدول بالإض"},{"id":5230,"era":"c14","t":"وفاة الشيخ العلامة عبد الرحمن بن سعدي .","s":"هو الشيخُ العلامة أبو عبد الله عبد الرحمن بن ناصر بن عبد الله بن ناصر بن حمد آل سعدي، من بني تميم. وُلِدَ في عُنيزة في القصيم في 12 محرم سنة 1307هـ. نشأ الشيخُ يتيمًا؛ فقد توفِّيَت أمُّه وله من العمر أربع سنوات، ثم توفِّيَ والِدُه وهو في السابعة، لكنه نشأ نشأةً صالحة، وقد أثار إعجابَ مَن حوله فاشتهر منذ حداثته بفطنته، وذكائه، ورغبته الشديدةِ في طلب العلم وتحصيله، فحَفِظَ القرآن عن ظهر قلبٍ وعمُرُه"},{"id":5231,"era":"c14","t":"إعلان إسرائيل سحب قواتها من قطاع غزة ومنطقة خليج العقبة .","s":"أعلنت إسرائيلُ سَحْبَ قوَّاتِها من قطاع غزة ومنطقة خليج العقبة، على افتراض أنَّ حرية المرور ستستمرُّ في خليج العقبة، وأنَّ قوات الطوارئ التابعة للأمم المتحدة ستُديرُ قِطاعَ غزة حتى يتِمَّ الاتفاق على تسوية سِلمية."},{"id":5232,"era":"c14","t":"الاتحاد القومي المصري الناصري .","s":"أسَّس جمال عبد الناصر الاتحادَ القوميَّ كتجَمُّع سياسي يحكُمُ عن طريقه البلد، وقد بَعَث علي صبري إلى البرتغالِ لدراسة الاتحاد القومي هناك الذي نظَّمَه \"سالازار\" طاغية البرتغال. وقد نصَّ دستور عام 1956م على هذا التنظيم، وذكر أن هذا التجمُّع سياسيٌّ يعمَلُ على تحقيق الأهداف التي قامت من أجلها ثورة يوليو عام 1952م، ولم يكُنْ هذا التنظيم حزبًا سياسيًّا كما جرت العادة، وإنما كان تنظيميًّا حكوميًّا؛ حيث"},{"id":5233,"era":"c14","t":"تشكيل أول حكومة ذات استقلال ذاتي صوري في موريتانيا .","s":"استمَرَّت المقاومة في موريتانيا ولم تهدأ رغمَ سُقوطِ الدولة العثمانية، ورغْم استطاعة الفرنسيين بَسْطَ سيطرتهم ونفوذِهم على البلاد بسبَبِ تفوُّقِهم العسكري في الرجال والسلاح. وفي أثناء أحداثِ الحرب العالمية الثانية بدأت بوادِرُ الدعوة للاستقلال بالظهور؛ إذ برز حزبان هما: حزب الاتحاد الوطني، وحزب منظمات الشباب. بعد ذلك انحصرت مطالِبُ الحزبين بالمطالبة بالاستقلال المباشر، فتوحَّدا في حزب واحد عام 136"},{"id":5234,"era":"c14","t":"إلغاء نظام الباي في تونس وإعلان الجمهورية .","s":"حصلت تونس على الاستقلالِ في عام 1375هـ ثم شكَّلَ الحبيب بورقيبة الوزارةَ، وكان همُّه الأول ترسيخَ قواعده والعمَلَ على التخلص من مُناوئيه؛ لذا فقد عَمِلَ قَبلَ كُلِّ شَيءٍ على تصفية خصومه السياسيين، وفي 28 ذي الحجة 25 تموز ألغى منصِبَ الباي (النظام الملكي) وأعلن الجمهوريةَ وتسَلَّمَ مَنصِبَ الرئاسة."},{"id":5235,"era":"c14","t":"منح الأمير فيصل بن عبدالعزيز صلاحيات إدارة شؤون الدولة .","s":"وَلِيَ الأمير فيصل بن عبدالعزيز ولايةَ العهد ورئاسةَ مجلس الوزراء في عام 1373هـ، وفي هذا العام أُعطيت له صلاحيات مطلقة في الأمور الإدارية والمالية والخارجية، وصدر بذلك مرسوم ملكي."},{"id":5236,"era":"c14","t":"مذابح المسلمين في الصين بكاشغر \"تركستان الشرقية\" .","s":"بدأت مأساةُ المسلمين في الصين الشيوعية منذ عام 1954م حين حاربت الصينُ الشيوعية الإسلامَ، وذلك بتعطيل المساجد، وسَجْنِ العلماء أو قتلِهم، كما قامت الصينُ الشيوعية بتقسيم تركستان الشرقية، وتهجير المسلمين منها، وقتلت منهم 360 ألف مسلمٍ في مدينة كاشغر في معركةٍ مع الشيوعيِّين."},{"id":5237,"era":"c14","t":"الوحدة العربية بين مصر وسوريا .","s":"قام وفدٌ نيابيٌّ من سوريا بزيارة مصر ودعا إلى الوَحدةِ بين الدولتين العربيتين وبادلهم وفدٌ مصري الزيارةَ، وكان جمال عبد الناصر يريد الاتحادَ ولا يرى الدَّمجَ، يعني الوحدة، غير أنَّ الوضع في سوريا كان قلقًا جِدًّا، وكان الشعب يريدُ الوَحدةَ؛ لعله يتخَلَّصُ مِمَّا هو فيه من التسلُّطِ العسكري وتحكُّم البعثيِّينَ والشيوعيِّين، وكان رئيسُ الأركان السوري عفيف البزري ذو الميول الشيوعية يعرِفُ رغبة جمال ف"},{"id":5238,"era":"c14","t":"الاتحاد العربي بين العراق والأردن .","s":"بعد أن قامت الوحدة بين سوريا ومصر في رجب من عام 1377هـ / 1 شباط 1958م،كان لهذه الوحدةِ أثَرٌ على العراق والأردن، فاقترح وزيرُ الخارجية البريطانية سلوين لويد إقامةَ اتحاد بين العراق والأردن، واجتمع فعلًا الوفدان العراقي والأردني في عمان، وكان الأردن قد اشترط لتحقيقِ الاتحاد أن تنسَحِبَ العراق من حلف بغداد، لكِنَّ العراق رفض ذلك، فبَقِيَ العراق في حلفه وبقيت الأردن في هدنتها مع إسرائيل، وتم الاتفاقُ"},{"id":5239,"era":"c14","t":"وفاة الشيخ أبي الكلام آزاد الهندي .","s":"هو الشيخُ أبو المكارم محيي الدين أحمد بن خير الدين الهندي المشهور بلقب \"أبو الكلام آزاد\", من أسرة أفغانية هاجرت إلى الهند زمنَ الإمبراطور بابر مؤسِّس الدولة المغولية، ولِدَ بكلكتا عام 1306هـ / 1888م وبها استتَمَّ دراستَه الأولية. وقصد الأزهرَ في الرابعة عشرة من عمره، فدرس على علمائِه ودرَّس في خارجه، ثم عاد إلى وطن أبيه (الهند) فسكن كلكتا، وقد أخذ كنيةَ أبي الكلام لكونِه خطيبًا بارعًا، أما كلمة آز"},{"id":5240,"era":"c14","t":"وفاة الشيخ المحقق أحمد شاكر .","s":"هو الشَّيخُ الأستاذ العلَّامة المحَدِّث أبو الأشبال أحمد بن محمد شاكر بن أحمد بن عبد القادر من آل أبي علياء. وُلِدَ بعد فجر يوم الجمعة في 29 جمادي الآخرة سنة 1309هـ / 1892م بالقاهرة، ووالده هو العلَّامة الشيخ محمد شاكر، لَمَّا عُيِّن والده الشيخ محمد شاكر قاضيًا بقضاءِ السودان سنة 1900م أخذه معه وأدخله كلية غوردون، فبقي بها حتى عودة والده إلى الإسكندرية سنة 1904م، فالتحق بمعهد الإسكندرية. وفي سنة "},{"id":5241,"era":"c14","t":"ثورة عبد الكريم قاسم وانتهاء الحكم الملكي في العراق .","s":"نشأت \"حركة الضباط الأحرار\" عام 1376هـ تحت قيادة عبد الكريم قاسم ذو الميول الشيوعية، وعبد السلام عارف ذو الميول الإسلامية، وقد قامت الحركةُ بعدة محاولاتٍ لقَلبِ نظام الحُكمِ لكِنَّها فَشِلت، إلى أن تمكنت من توجيه ضربة قاضية ضِدَّ الحكم الملكي، فقتلت كلًّا من الملك فيصل الثاني بن غازي ملك العراق، والوصي عليه خاله عبد الإله بن علي، ونوري السعيد رئيس الحكومة، وسيطرت على الوَضعِ ورحَّبت بعض الدولُ العر"},{"id":5242,"era":"c14","t":"وفاة نوري السعيد رئيس حكومة العراق .","s":"هو نوري بن سعيد بن صالح ابن الملا طه، من عشيرة القره غولي البغدادية رئيس حكومة العراق. سياسيٌّ عَسكريُّ المنشأ، فيه دهاء وعنف. ولدَ ببغداد سنة 1306هـ / 1888م، وتعلَّم في مدارسها العسكرية. وتخرَّج بالمدرسة الحربية في الأستانة (1906) ودخل مدرسة أركان الحرب فيها عام 1911م، وحضر حرب البلقان 1912 – 1913م، وشارك في اعتناق \"الفكرة العربية\" أيام ظهورها في العاصمة العثمانية. فكان من أعضاء جمعية العهد السري"},{"id":5243,"era":"c14","t":"وفاة الشيخ حافظ الحكمي .","s":"هو الشيخُ العلَّامة حافظ بن أحمد بن علي الحكمي، ولد في 24 رمضان سنة 1342هـ في قرية السلام في جازان، نشأ بدويًّا يرعى الغَنَم. بدأ تعلُّمَه في سن مبكرةٍ، وكان آيةً في الحِفظِ؛ فحفظ القرآن وبعض المتون وهو يرعى الغنم صغيرًا، ثم قيَّض الله له الداعية الشيخ عبد الله القرعاوي الذي اهتَمَّ به فأفاده من علومِه وفقهِه، ثم اشتهر بالعلمِ ولمع نجمُه، حتى أصبح معلِّمًا، ثم تولى النيابةَ في إدارة مدارس التعليم "},{"id":5244,"era":"c14","t":"الخلاف بين قيادات ثورة تموز عبد الكريم قاسم وعبد السلام عارف .","s":"كان الخلافُ بين عبد الكريم قاسم ذو الميول الشيوعية وعبد السلام عارف أبرَزَ مشاهد الصراع على السلطة بين قادة (الضباط الأحرار)؛ فقد بدأ الخلافُ بينهما من اليوم الأول؛ إذ يعدُّ كل واحدٍ منهما نفسَه أنه هو الذي أنشأ الحركةَ وقادها، فعبد الكريم قاسم رأسُ المنظَّمة ومنه تَصدُرُ الأوامر، وهو الذي يرى نفسَه أنَّه هو المُخطِّط لهذه الثورة، ولا يتِمُّ عمَلٌ دونه، ويرى عبد السلام عارف أنه هو الذي قاد الحركة "},{"id":5245,"era":"c14","t":"استقلال غينيا  .","s":"جرت الانتخاباتُ المحلية في غينيا عام 1377هـ / 1957م إثرَ مؤتمر باماكو الذي ضَمَّ ممثِّلي أفريقيا الغربية، وكان من مقرراته اعترافُ فرنسا بحَقِّ تقرير المصير لشعوب المنطقة، وفاز في غينيا حزبُ غينيا الديمقراطي، واحتفلت غينيا باستقلالها في 19 ربيع الأول / 2 أكتوبر بعد استعمارٍ دام قرنًا من الزمن، وكان أوَّلُ رئيس لغينيا الرئيس أحمد سيكوتورى، وغينيا من دول أفريقيا ذات الأغلبية المسلمة."},{"id":5246,"era":"c14","t":"حركة رشيد عالي الكيلاني ضد عبد الكريم قاسم  .","s":"نتيجةً لاستبداد عبد الكريم قاسم بالسلطة وإقصاء غيرِ الشيوعيين من زملاء الثورة جرت في البلادِ عِدَّةُ محاولات للانقلاب على عبد الكريم قاسم؛ منها محاولة رشيد عالي الكيلاني الذي عاد للبلاد بعد نجاحِ الثورة وإنهاء الحُكم المَلَكي، وأخذ عددٌ من الضباط الناقمين على قاسم بالتردُّد على الكيلاني في بيته، ويتحدثون في السياسة بكل صراحة، فترامى إلى قاسم أنَّ رشيد الكيلاني يُعِدُّ لانقلاب ضده، فدبر عبد الكريم "},{"id":5247,"era":"c14","t":"أيوب خان رئيسًا لباكستان بعد إسكندر مرزا .","s":"كان الرئيس إسكندر مرزا قد ألغى الدستورَ وحَلَّ المجلسَ النيابي وفرض الأحكامَ العُرفيَّة، وحَلَّ الحكومة المركزية والأحزاب كافة، ثم استولى أيوب خان القائدُ العام للجيش والقوات المسلحة في 4 ربيع الثاني / 17 أكتوبر على مقاليدِ الأمور في البلادِ إثرَ انقلابٍ أطاح بحكومةِ إسكندر ميرزا الذي غادر البلادَ بعد عشرة أيام، وتسلَّم أيوب خان السلطةَ مكانَه ليحلَّ الحكم العسكري في البلاد، وبعد ثلاثة أيام فقط من"},{"id":5248,"era":"c14","t":"وفاة الشيخ محمد حامد الفقي مؤسس جماعة \"أنصار السنة المحمدية\" .","s":"هو الشيخُ المحقِّق محمد حامد بن أحمد عبده الفقي مؤسِّسُ جماعة أنصار السنة المحمدية. ولِدَ الفقي بقرية نكلا العنب في سنة 1310ه الموافق 1892م بمركز شبراخيت مديرية البحيرة بمصر، أمضى ست سنوات من دراسته بالأزهر. وتخرُّجِ عام 1917م بعد أن نال الشهادة العالمية من الأزهر، وكان عمرُه حينذاك 25 سنة. ثم انقطع منذ تخرجه إلى خدمة كتاب الله وسنة رسولِه صلى الله عليه وسلم. وأثمرت تلك الجهود في إنشاء جماعة أنصار"},{"id":5249,"era":"c14","t":"محاولة اغتيال الرئيس العراقي عبد الكريم قاسم .","s":"رأى حِزبُ البعثِ العراقي أنَّه لا بدَّ من التخلص من رئيس العراق باغتيالِه، فاختاروا عشرة من المغامِرين ودرَّبوهم، وأعدَّ الحزبُ العُدَّةَ لتسلُّم السلطة بعد تنفيذ العملية، وقَطْع الطريق على الشيوعية، واتصل الزعماءُ البعثيون برئيس مجلس القيادة الفريق محمد نجيب الربيعي، ووافقهم على تسلُّم الرئاسة وتشكيل مجلس ثورة جديد بعد نجاح العملية، ثمَّ تقَرَّر التنفيذ في 5 ربيع الثاني 1379هـ / 7 أكتوبر، فقام ال"},{"id":5250,"era":"c14","t":"قتل عدنان مندريس رئيس وزراء تركيا .","s":"هو علي عدنان إرتكين مندريس المعروف بعدنان مندريس رئيس وزراء تركيا، ولِدَ في مدينة أيدين سنة 1317هـ، وهو سياسيٌّ حقوقي، ورجل دولة تركي ومن دهاة الأتراك, شارك في تأسيسِ رابع حزب معارِض معتَرَف به في تركيا، كما أنه يعتبَرُ أوَّلَ رئيس وزراء منتَخَب ديمقراطيًّا في تركيا عام 1385هـ, دخل الانتخاباتِ مُرشَّحًا للحزب الديموقراطي سنة 1950م ببرنامج توقَّعَت له كلُّ الدراسات الفشَلَ المطلق، فمع أنَّه خرج من "},{"id":5251,"era":"c14","t":"جمال غورسيل يترأس تركيا بانقلاب عسكري ضد محمود بايار .","s":"قام رئيسُ الأركان جمال غورسيل بانقلاب عسكري على الحزبُ الحاكم الديمقراطي برئاسة محمود جلال بايار فقُبِضَ على عدنان مندريس رئيس الوزراء، وأعدِمَ مع اثنين من وزرائه، وأمَّا رئيس الجمهورية محمود جلال بايار فخُفِّفَ عنه حكم القتل لكِبَر سنه، فسُجِنَ سَجنًا مؤبَّدًا حتى قضى نحبه فيه عام 1391هـ، وأصبح جمال غورسيل رئيسًا للجمهورية في عام 1381هـ بعد إجراء انخابات صورية."},{"id":5252,"era":"c14","t":"استقلال الغابون (الجابون) .","s":"في نهايةِ القرن الثالث عشر الهجري وصل الفرنسيُّون إلى الغابون، فاشتَرَوا قطعة من الأرض، وأقاموا عليها مستعمرةً صغيرة وبعد مضي عشر سنوات أقاموا مركزًا لتجارة الرقيق قُربَ الساحل، ثم امتَدَّ نفوذهم إلى داخل الغابون، وضَمُّوها إلى الكنغو الفرنسي، ثم فُصِلَت الجابون لتصبِحَ مُستعمَرةً قائمة بذاتها، وفي هذا العام نالت الغابون استقلالَها، وفي ظِلِّ الاستقلال هاجر العديدُ من المسلمين من مالي، وبنين، والس"},{"id":5253,"era":"c14","t":"استقلال الصومال .","s":"تنازلت بريطانيا إثرَ إلغاء الخلافة سنة 1342هـ عن منطقة جوبا السفلي أقصى جنوبي الصومال، لإيطاليا، وكانت مِن قَبلُ تتبع كينيا، وأعطت كينيا مقابِلَ ذلك الأراضي الصومالية الواقعة شرق بحيرة رودولف، ثم بعد الحرب العالمية الثانية كَثُرَ الجدل في الأمم المتحدة حولَ الوصاية على الصومال، ثم فازت إيطاليا بالوصاية على القسم الجنوبي من الصومال، وحُدِّدت بعشر سنوات تنتهي في جمادى الآخرة 1379هـ / ديسمبر 1959م، و"},{"id":5254,"era":"c14","t":"استقلال ساحل العاج  .","s":"بعد الحَربِ العالمية الثانية أصبحت دولةُ ساحل العاج ضِمنَ الاتحاد الفرنسي، وانتُخِبَت أول جمعية وطنية عام 1366هـ / 1947م وبعد عشر سنوات تشكَّلَت فيها أوَّلُ حكومة تتمَتَّعُ بالاستقلال الذاتي، ثم وافقت على دستور ديغول المعروف، فحصلت على الاستقلال الداخلي في 1378هـ / 1958م فأُعلِنَت الجمهوريةُ ضِمنَ مجموعة الشعوب الفرنسية، ثم مع الحزب الديمقراطي لساحل العاج حصلَ على الاستقلال التام في 14 صفر 1380هت "},{"id":5255,"era":"c14","t":"فرض جامعة الدول العربية مقاطعة اقتصادية على إيران .","s":"قامت جامعةُ الدول العربية بفَرضِ مقاطعة اقتصادية على دولةِ إيران؛ وذلك بسبب إقدامها على الاعتراف بدولة إسرائيلَ، وعزمها على تبادُلِ التمثيل الدبلوماسي بينهما."},{"id":5256,"era":"c14","t":"استقلال تشاد  .","s":"كانت تشاد تحت الاستعمار الفرنسي الذي كان قد قضى على إمارة رابح الإسلامية، حتى عُدَّت تشاد عام 1363هـ / 1944م جزءًا من الجمهورية الفرنسية فيما وراء البحار؛ بسبب وقوف حكَّامِها آنذاك مع حكومة ديغول الحرة التي قامت بعد هزيمة فرنسا أمام ألمانيا أثناء الحرب العالمية الثانية، وبالتالي شارك سكان تشاد في الحرب بجانب الفرنسيين، ووافقت فرنسا على تأسيس الأحزاب السياسية فيها بما أنَّها من الدولة الفرنسية، وأص"},{"id":5257,"era":"c14","t":"استقلال فولتا العليا (بوركينافاسو) .","s":"كان المُستعمِرون قد قَسَّموا البلاد في غرب أفريقيا إلى أقسام، وأزالوا من الخارطة اسم فولتا العليا (بوركينافاسو حاليًّا)، ثم بعد الحرب العالمية الثانية وفي عام1366هـ / 1947م أعيدت الدولةُ بنفس الحدود السابقة، وجرت انتخابات واختار السكان جمعيةً وطنية بقيت تحت إشراف فرنسا بشكلٍ تام قرابةَ العشر سنوات، ثم أقيمت أوَّلُ حكومة للحكم الذاتي في 19 شوال 1376هـ / 18 أيار 1957م، وجاء بعدها ديغول وطرح دستوره ا"},{"id":5258,"era":"c14","t":"استقلال داهومي (بنين) .","s":"كانت داهومي (بنين حاليًّا) تحت الاستعمار الفرنسي، ورُسِمَت الحدود بين نيجيريا وداهومي بشكلٍ دقيق بعد اتفاقية بين بريطانيا وفرنسا وُقِّعَت عام 1316هـ / 1898م، ثم رُسِمَت الحدود مع التوغو بعد اتفاقية مع ألمانيا عام 1330هـ / 1912م وأخذت داهومي شكلها الحاليَّ تقريبًا، ثم ركَّزت جهودَها التنصيرية أكثَرَ مِن أي منطقة أخرى، ثم تشَكَّلت حكومةٌ شبه مستقلة في الداهومي بعد الحرب عام 1366هـ / 1947م، وبعد عشر "},{"id":5259,"era":"c14","t":"استقلال النيجر  .","s":"اتفقت إنجلترا وفرنسا عام 1308هـ / 1890م على تعيين الحدود واقتسام مناطق النفوذ بينهما في منطقة وسط أفريقيا، وكانت منطقة النيجر من نصيبِ فرنسا، وتمكَّنَت من السيطرة التامة على النيجر كاملةً عام 1341هـ / 1923م وأخذت تطَبِّقُ سياسَتَها الاستعمارية، ثم بعد الحرب العالمية الثانية قَبِلَت النيجر بدستور ديغول وحصَلَت على الاستقلال الداخلي، وأعلنت الجمهورية ضِمنَ المجموعة الفرنسية، ثم أخذت بالمطالبة بالخرو"},{"id":5260,"era":"c14","t":"استقلال السنغال .","s":"انضَمَّت السنغال إلى السودان الفرنسي ليؤلِّفَا معًا اتحادَ مالي في شوال 1378هـ / نيسان 1959م، وبعد أقل من عام أصبح اتحادُ مالي مستقلًّا وانحلَّ الاتحاد وأصبحت السنغال جمهوريةً مستقلة في 27 صفر 1380هـ / 20 آب 1960م، ثم استقلت رسميًّا عن فرنسا في 14 ربيع الأول 1380هـ / 5 أيلول، وكانت تحت حُكمِ حزب الاتحاد التقدمي السنغالي، ورئيسه هو رئيس الجمهورية ليوبولد سنجور."},{"id":5261,"era":"c14","t":"تأسيس منظمة أوبك ودور السعودية في نشأتها\n  .","s":"درست الحكومةُ السعودية دراسةً دقيقة سوقَ النفط في العالم, وبدأت تدرِكُ مدى الأرباح الطائلة التي تحصل عليها شركات النفط خارجَ السعودية, مع وجود مبدأ \"المناصفة\"، وفي نيسان (أبريل) 1959 عُقِد أول مؤتمر نِفطي عربي حضره ممثِّلون عن السعودية، وبدأت البلدان المصدِّرة للنفط تُدرِكُ ضرورةَ القيام بنشاطات جماعية. وقد أثار بالغ القلق لدى هذه البلدان انخفاض الأسعار القياسية. ففي الفترة من سنة 1957 حتى سنة 196"},{"id":5262,"era":"c14","t":"استقلال مالي .","s":"كانت مالي تقع ضمن بلاد السودان الفرنسي تحت سيطرة الاحتلال الفرنسي، وعندما طُرِحَ دستور ديغول قَبِلَته مالي، فتكوَّنَت جمهورية مالي ذاتُ الاستقلال الذاتي ضِمنَ مجموعة الشعوب الفرنسية، وأُلغِيَت وظيفةُ الحاكم الفرنسي العام، ثم في شهر شوال 1378هـ / نيسان 1959م تمَّ اتحاد بين السودان الفرنسي والسنغال حَمَل اسم مالي رمزًا لمملكة مالي القديمة، وحصل الاتحاد على الاستقلال ضِمنَ المجموعة الفرنسية عام 1379ه"},{"id":5263,"era":"c14","t":"استقلال موريتانيا  .","s":"بعد انتهاءِ الحرب العالمية الثانية بدأت الأحزابُ تدعو إلى الاستقلال، وفي عام 1378هـ / 1958م أصبحت موريتانيا ضِمنَ الشعوب الفرنسية التي تتمتَّعُ بالاستقلال الداخلي مع بقاء السلطاتِ بيَدِ الحاكم العام الفرنسي، وبقيت الأحزابُ تُطالِبُ بالاستقلال، ثم جرت الانتخاباتُ وتشَكَّلت الجمعية التأسيسية، وقُدِّم الدستور إلى الجمعية الوطنية فوافقت عليه في رمضان 1378هـ / آذار 1959م، وجاء فيه أنَّ اسم البلاد هو ال"},{"id":5264,"era":"c14","t":"مؤتمر (برازفيل) لضم دول غرب ووسط أفريقيا للاتحاد الفرنسي .","s":"مؤتمر برازافيل (مؤتمر اتحاد الدول الأفريقية والملاجاشية) عُقد في الفترة من 15 إلى 19 ديسمبر 1960م. وكان الهَدفُ منه تحقيقَ تعاون بين بعض الدول الأفريقية الواقعة تحت الاستعمار الفرنسي وترغب في الاستقلال، وترفُضُ الانضمامَ إلى المجموعة الفرنسية. وقد بذلت هذه الدولُ جهودًا كبيرةً في إنشاء تجمُّع أفريقي غيرِ مرتبط بأيِّ دولة أوروبية. عُقِدَ أوَّلُ مؤتمر في مدينة أبيدجان، عاصمة ساحل العاج من 3 إلى 7 أك"},{"id":5265,"era":"c14","t":"مؤتمر الدار البيضاء لدول أفريقية بالمغرب .","s":"عُقِدَ مؤتمر الدار البيضاء الدولي بالمغربِ بدعوة من الملك محمد الخامس؛ ملك المغرب بعد عدة لقاءات واجتماعات بين ممثِّلي الدول الأفريقية التي وقَّعت فيما بعد ميثاقَ المنظمة. اشترك في هذا المؤتمر سِتُّ دول، هي: الجمهورية العربية المتحدة، والمغرب، وحكومة الجزائر المؤقتة، وغانا، وغينيا، ومالي. كما حضر المؤتمر مراقبان من ليبيا وسيلان، على الرغمِ من أن سيلان ليست دولةً أفريقية. وكان الهدف من المؤتمر تباد"},{"id":5266,"era":"c14","t":"نشأة وزارة المعارف في السعودية .","s":"اتَّسَعت أعمالُ إدارة المعارف بعد وفاة الملك عبد العزيز فجُعِلت وزارةً كسائر وزارات الدولة، وتولاها الأميرُ فهد بن عبد العزيز، وفي عهده أُنشِئَت جامعة الرياض، ثم تولى الوَزارةَ الشيخ عبد العزيز بن عبد الله آل الشيخ، ثم تولاها أخوه حسن بن عبد الله آل الشيخ الذي توسَّع نطاقُ جامِعة الرياض في عَهدِه، فشَمِلَت كليَّات العلوم والصيدلة والآداب والتجارة والزراعة، ثم الهندسة، وأُنشِئَت جامعة الملك عبد الع"},{"id":5267,"era":"c14","t":"وضعُ حجر الأساس لبناء السد العالي في أسوان .","s":"وُضِعَ حَجَرُ الأساس لبناء السد العالي في أسوان، بحضور الرئيس المصري جمال عبد الناصر، وكان الغرَضُ من بناء السد تخزينَ المياه، وموازنة الفيضانات المرتفعة والمنخفضة، وتوليد الكهرباء، وتحسين الملاحة بالنيل، وقد أُنجِزَت المرحلة الأولى في بناء السد سنة 1964م."},{"id":5268,"era":"c14","t":"وفاة محمد الخامس ملك المغرب وتولي ابنه الحسن الثاني .","s":"هو محمَّدُ الخامس بن يوسف بن الحسن بن محمد بن عبد الرحمن الحسني العلويّ، أبو الحسن المنصور باللَّه: ملك المغرب، ورمزُ نهضته الحديثة. وُلِدَ بفاس سنة 1329هـ وتعَلَّم بها وبالرباط، وكان بفاس يوم بُويِعَ له بعد وفاة والده سنة 1346ه 1927م، فانتقل إلى الرباط عاصمة المغرب في عهد أبيه. وكان الاحتلالُ الفرنسي المعبَّرُ عنه بالحماية هو المرجِعَ الأعلى في سياسة البلاد وإدارتها، وليس للملك الذي كان يُدعى بال"},{"id":5269,"era":"c14","t":"استقلال سيراليون  .","s":"كثُرت الأحزاب السيرالونية حتى بلغت تسعةَ أحزاب أجمعت كلُّها على المطالبة بالاستقلال من الحماية البريطانية، وشَكَّلت وفدًا سافر إلى لندن عام 1380هـ / 1960م، وقد شكل أعضاؤه بعد عودتهم حكومةً ائتلافية استطاعت أن تظفَرَ بالاستقلال في 12 ذي القعدة 1380هـ / 27 نيسان ضِمنَ رابطة الشعوب البريطانية، وسيراليون من دول غرب أفريقيا ذات الأغلبية المسلمة."},{"id":5270,"era":"c14","t":"استقلال الكويت .","s":"تعودُ النشأةُ الحديثةُ لدولة الكويت إلى الشَّيخِ مبارك الصباح الذي حكَمَ الفترة ما بين 1896م إلى 1915م، واستند نظامُ الحكم فيها إلى أساس السلطة المُطلَقة للحُكَّام، ولم تحصل تطوراتٌ جوهرية على النظامِ حتى حصول الكويت على الاستقلال، وذلك بعد إلغاء اتفاقيَّة الحماية التي عُقِدَت في 1899م بينها وبين بريطانيا، وقد قُبِلَت الكويت في الجامعة العربية في 20 تموز 1961م، وفي الأمم المتحدة في 14 آذار 1963م. "},{"id":5271,"era":"c14","t":"انفصال الوحدة بين مصر وسوريا .","s":"بدأت العلاقةُ بين الطرفين المصري والسوري تسوء عندما عُيِّنَ المشير عبد الحكيم عامر حاكِمًا على سوريا في عام 1379هـ / 1959م فاستقال وزراءُ حزبِ البعث ونائِبُ رئيس الجمهورية البعثي أكرم الحوراني؛ وحدث استياءٌ عام في سوريا في الوسط المثقَّف والتعليمي وفي الجيش وحتى بين الشيوعيين الذين غادر أكثَرُهم البلاد، وعلى رأسهم زعيمهم خالد بكداش، فبدأ بعض الضباط السوريين العمل سرًّا لانفصال الوحدة، ومن بينهم عب"},{"id":5272,"era":"c14","t":"ثورة 26 سبتمبر في اليمن ونهاية حكم الأئمة وإعلان الجمهورية .","s":"بعد أن انفصلت اليمنُ عن الدولة العثمانية أثناء الحرب العالمية الأولى استقلَّ بحكمِها الإمام يحيى حميد الدين حتى سنة 1948م حكمًا يجمع بين الإمامة الدينية والسلطة السياسية، وعاونه في الإدارة أولادُه، ولما قتل الإمام يحيى في شباط 1948م في مؤامرة بسبب صراع أسري، تولى الحكم ابنُه أحمد الذي انفتح على العالم بانضمامه إلى الجامعة العربية، ثم لهيئة الأمم المتحدة، بل وفتح باب العلاقة مع دول المعسكر الشيوعي "},{"id":5273,"era":"c14","t":"حرب اليمن الأهلية (دعم مصر للجمهوريين ودعم السعودية للملكيين) .","s":"لما توفي الإمام أحمد خلفه في الإمامة ابنه البدر، ولم تلبث أن قامت الثورة عليه بإمرة العقيد الناصري عبد الله السلال، وذلك في 27 ربيع الثاني / 26 سبتمبر، وهرب البدر من البلاد، وأخذ يستعد للعودة. أيدت السعودية الملكية اليمنية وأيَّدت مصر الثورة ووصلت طلائع القوات المصرية إلى اليمن في 7 جمادى الأولى 1383هـ، وفي اليوم التالي من وصولها قطعت مصر علاقتَها بالسعودية، ثم وصل أنور السادات حيث عَقَد مع اليمن "},{"id":5274,"era":"c14","t":"استقلال تانجانيقا (تنزانيا) .","s":"كانت تنزانيا الحالية تتكون من منطقتين؛ المنطقة الأولى هي تانجانيقا، والأخرى زنجبار، فأما تانجانيقا وهو الساحل الجنوبي الشرقي فقد كان تحت الاحتلال الألماني، وعرفت باسم أفريقيا الشرقية الألمانية، وقد تمكنت إنجلترا بعد الحرب العالمية الأولى من انتزاع تانجانيقا من ألمانيا، ووُضعت تحت وصاية عصبة الأمم، ثم أصبحت بريطانيا هي الوصية عليها بتصديق من عصبة الأمم عام 1341هـ / 1922م، فاتبع فيها نظام الانتداب، "},{"id":5275,"era":"c14","t":"اتفاقية إيفيان الأولى ووقف إطلاق النار بين جبهة التحرير الجزائرية وفرنسا .","s":"بدأت المفاوضاتُ بين الجزائريين والفرنسيين في إيفيان من 20 مايو، واستمرت لمدة عام، تمَّ في بدايتها الاتفاقُ على إعلان وقف إطلاق النار بين جبهة التحرير الجزائرية وفرنسا. وبناءً على اتفاقية إيفيان تمَّ إقرار مرحلة انتقالية وإجراء استفتاء تقرير المصير. والاتفاق على أن تتولى شؤون الجزائر حكومةٌ مؤقتة تتكون من 12 عضوًا. كما تضمَّنت هذه الاتفاقيات جملةً من اتفاقيات التعاون في المجالات الاقتصادية والثقافي"},{"id":5276,"era":"c14","t":"انقلابات عسكرية في سوريا ضد الوحدة مع مصر .","s":"قام عبد الكريم النحلاوي بانقلاب عسكري في سوريا ضدَّ الجمهورية العربية المتحدة برئاسة جمال عبد الناصر، ويعد النحلاوي المسؤولَ الرئيسي عن انفصال سوريا عن مصر في الوحدة التي نشأت بين القطرين تحت اسم \"الجمهورية العربية المتحدة\"، ثم قام النحلاوي في 28 مارس 1962م بانقلابٍ آخر فحَلَّ البرلمان وأقال حكومة معروف الدواليبي. ثم وقع انقلاب عسكري بعد يومين ضد \"النحلاوي\"."},{"id":5277,"era":"c14","t":"رؤية ولي العهد فيصل بن عبد العزيز في الإصلاح السياسي والإداري .","s":"شكَّل الأميرُ فيصل بن عبد العزيز الحكومةَ الجديدة، ثم طرح مجموعةً من الرُّؤى الإصلاحية؛ كالنِّظام الأساسي للحُكم، ونظامِ القضاء، ومجلسٍ للإفتاء، وهيئةٍ للأمر بالمعروف والنهي عن المنكر، واعتماد مجانيَّة الطبِّ والتعليم، ودعم الموادِّ الاستهلاكية الضرورية، والضَّمان الاجتماعي، وتنظيم وتطوير الوضع الاقتصاديِّ والتجاريِّ والاجتماعيِّ، وإلغاء الرِّقِّ بشكلٍ مُطلَق، وحَظْرِه وعتق العبيد جميعًا. وقد تحقق"},{"id":5278,"era":"c14","t":"استقلال الجزائر .","s":"توقَّفت الثَّورةُ الجزائريةُ الكبرى -التي اندلعت في جميعِ أرجاء الجزائر ثم انتقلت لأرض فرنسا نفسِها- بعد اتِّفاق الجزائريِّين والفرنسيِّين في مفاوضاتٍ سابقة على وقفِ إطلاق النار، وتشكيل حكومةٍ جزائرية مؤقَّتة؛ فأعلنت فرنسا عن قَبولها للمفاوضات، وعيَّنَ المجلسُ الوطني الجزائري العقيدَ هواري بومدين قائدًا عامًّا لجيش التحرير، ثم أعلنت الحكومةُ الجزائريةُ والفرنسيةُ في 25 ذي القعدة 1380هـ / 10 أيار 1"},{"id":5279,"era":"c14","t":"اتفاقية ميثاق الطائف بين السعودية والأردن .","s":"اجتمع الملكُ سعود -مَلِكُ السعودية-، والملكُ حسين -ملك الأردن- في الطائف، ووقَّعا اتفاقيةً على رسم الحدود بين البلدين، وعُرِفَت هذه الاتِّفاقيةُ بميثاق الطَّائف."},{"id":5280,"era":"c14","t":"إصدار الحكومة الإثيوبية قرارًا باحتلال إريتريا عسكريًّا .","s":"أصدرت الحكومةُ الإثيوبية قرارًا باحتلال إريتريا عسكريًّا وضَمِّها إلى أملاكها الرسمية، ويتعارض هذا القرارُ مع قرار الأمم المتحدة الصادر في 2 يناير 1950م بشأن إقامة اتحادٍ لامركزيٍّ بين الحبشة وإريتريا."},{"id":5281,"era":"c14","t":"إقامة صلاة الجمعة في جامع كتشاوة بالجزائر .","s":"تمَّت إقامةُ صلاة الجمعة في جامع كتشاوة بالجزائر، وكان خطيبُها الشيخَ الجزائري \"البشير الإبراهيمي\"، وكانت هذه هي الجُمعةَ الأولى التي تقامُ في ذلك المسجد بعد مائة عام مِن تحويلِ الاحتلال الفرنسي هذا المسجِدَ إلى كنيسةٍ!"},{"id":5282,"era":"c14","t":"مبادرة الرئيس الأمريكي جون كندي لحل نزاع اليمن .","s":"وجَّه الرَّئيسُ الأمريكي جون كندي رسائلَ إلى رئيس الوزراء السعودي الأمير فيصل، وملك الأردن حسين، ورئيس مصر عبد الناصر، والرئيس اليمني عبد الله السلال, ضمَّنَها تصوراتِه حول سُبُل حلِّ نزاع اليمن. وقد تجاهل الرئيسُ الأمريكي الإمامَ محمد البدر وحاشيته. واقترح كندي على مصر سَحْبَ قواتها المسلَّحة من اليمن, وفي المقابل اقترح على السعودية والأردن ومشايخ وسلاطين اتحاد جنوب الجزيرة وقْفَ المساعدات للمَلَ"},{"id":5283,"era":"c14","t":"إصدار مرسوم بإلغاء الرق في المملكة العربية السعودية  .","s":"صدر مرسومٌ بإلغاء الرِّقِّ، والتزمت حكومةُ المملكة العربية السعودية بموجِبه دفع 700 دولار عن كل عبدٍ لسيِّدِه، و1000 دولار عن الأَمَةِ، وحُدِّد آخِرُ موعد لتقديم طلبات التعويض في 14 صفر 1383هـ / 7 يوليو 1963م، وبلغ العدد الإجمالي للرقيق الذين طالب أسيادُهم بدفع تعويضٍ عنهم 1682 شخصًا، ودفعت الحكومةُ التعويضات وأعتقَتْهم، واعتُبر سائرُ الرقيق معتوقين بعد التاريخ المذكور الذي حُدِّد كأجَلٍ نهائي لدَ"},{"id":5284,"era":"c14","t":"وفاة محمد بن عبد الكريم الخطابي قائد الثورة المغربية .","s":"هو محمد بن عبد الكريم الخطابي (بالأمازيغية موحند نعبد لكريم لخطابي) الذي اشتُهِر بين الريفيين بـ (عبد الكريم الخطابي)، وهو قائدُ الثورة المغربية في منطقة الريف شماليَّ المغرب. وُلِدَ سنة 1299هـ / 1882م في أجدير قرب الحسيمة، من ريف المغرب. وُلِدَ في بيت علمٍ وجهادٍ، من قبيلة \"ورياغل\" إحدى كبريات القبائل البربرية في جبال الريف. حَفِظ القرآن وبَعَثه والِدُه إلى القرويين بفاس، فتعَلَّم وعاد إلى الريفِ"},{"id":5285,"era":"c14","t":"انقلاب البعثيين على الرئيس العراقي عبد الكريم قاسم ومقتله .","s":"لم تنجح المحاولاتُ التي بذلتها المجموعاتُ والأحزابُ المعارِضة لعبد الكريم قاسم في إنهاء حُكمه؛ لقدرة قاسم على كشف كلِّ المحاولات ثم إحباطِها؛ فبدأ كلُّ حزب يعمل على حِدةٍ وبسِرِّية حتى تمكَّن حِزبُ البعثِ من تصفيته وتقويضِ حُكمه؛ ففي الأول من شعبان عام 1382هـ / 27 ديسمبر 1962م قامت مظاهرات طلابية بسبب تدخل المهداوي رئيس المحكمة العسكرية في شؤون إحدى المدارس، فاستغلَّ الحزبيون الموقفَ فورًا، ولما ت"},{"id":5286,"era":"c14","t":"انقلاب حزب البعث السوري  ووصوله إلى السلطة في سوريا .","s":"كانت سوريا قد دخلت في الوَحدة مع مصر من تاريخ 1958م وتأسَّست الجمهورية العربية المتحدة، ثم تمَّ إلغاءُ الوحدة بعد أن رأى السوريون أنهم لم يتسَلَّموا أي سلطات تُذكَر تحت السيادة المصرية، وبعد أن تمَّ الانفصال في 28 أيلول 1961م وصل حزبُ البعث السوري إلى السلطة في سوريا في ثورة الثامن آذار (مارس) 1963م، وكان مشيل عفلق (نصراني) هو رئيس الحزب ومُنَظِّره، وبعد نجاح الانقلاب كُلِّف صلاح الدين البيطار (سُ"},{"id":5287,"era":"c14","t":"ضم القسم الغربي من جزيرة غينيا الجديدة (إيريان الغربية) إلى أندونيسيا .","s":"جزيرة غينيا الجديدة أكبر جزر أندونيسيا وثاني أكبر جُزُر العالم، وتنقَسِمُ إلى قسمين: القسم الغربي، ويُعرَف باسم إيريان الغربية، ولم تستطع أندونيسيا وهولندا الاتفاقَ عليها في معاهدة 1369هـ / 1949م في لاهاي؛ فبقيت تحت السيطرة الهولندية، وبعد الضغط العسكري على هولندا جرى استفتاءٌ عامٌّ بين السكان عام 1380هـ / 1960م فتحوَّل الإقليم إلى إشراف الأمم المتحدة في 1382هـ / 1962م، ثم انتهى الأمرُ إلى أن ضُمّ"},{"id":5288,"era":"c14","t":"الفاتيكان يصدر وثيقة تبرئة لليهود ليضفي على الدولة الإسرائيلية الشرعية .","s":"كانت المنظماتُ الصهيونيةُ تُصعِّد ضغوطَها منذ عام 1960م لاستصدار وثيقةٍ من الفاتيكان بتبرئة اليهود من دمِ المسيح، وقد صَدَرت بالفعل وثيقة فاتيكانية بعنوان (نوسترا ايتاتي) تعلن أن موت السيد المسيح  -على زعمهم- لا يمكن أن يُعزَى عشوائيًّا إلى جميع الذين عاشوا في عهده أو إلى يهود اليوم. وكان البابا يوحنا الثالث والعشرون قد ألغى من الصلاة الكاثوليكية مقطعًا يتحدَّث عن اليهود الملعونين، كما ألغى من الن"},{"id":5289,"era":"c14","t":"جلاء فرنسا عن ميناء بنزرت بعد معارك مع التونسيين .","s":"كانت وثيقةُ الاستقلال وما جرى من مفاوضاتٍ قبلَها بين تونس وفرنسا قد تركت \"بنزرت\" قاعدةً لفرنسا، وبدأت تونس المطالبةَ بها والعمل على استرجاعها؛ من أجل مصلحة البلاد وما تقتضيه الظروفُ السياسية من تحجيم النُّفوذ الفرنسي والإنجليزي، ولكِنَّ الحكومةَ كانت تحتاج إلى إعادة تقوية لمركزها؛ فبدأت المطالبة بـ\"بنزرت\" من فرنسا وأن تنسحبَ منها، ولكِنَّ فرنسا رفضت ذلك وأصرَّت على البقاء، فأخذت المقاومة تُغِيرُ ع"},{"id":5290,"era":"c14","t":"التحضير لنشأة منظمة التحرير الفلسطينية وانعقاد جلسته الأولى  .","s":"بعد وفاة أحمد حلمي -رئيس حكومة عمومِ فلسطين، وممثل فلسطين لدى الجامعة العربية- صدر قرارٌ باختيار أحمد الشقيري لهذا المنصب، وأكَّد القرار أنَّ الشعب الفلسطيني هو صاحب الحقِّ الشرعي في فلسطين، وأن من حقِّه أن يستردَّ وطنَه، ويقرِّرَ مصيره، ويمارسَ حقوقه الوطنية الكاملة، وأنَّ الوقتَ قد حان ليتولى أهلُ فلسطين أمرَ قضيتهم، وأنَّ مِن واجب الدول العربية أن تتيحَ لهم الفرصةَ لممارسة هذا الحق. وبادر الشقي"},{"id":5291,"era":"c14","t":"اتفاقية الجزائر بين العراق وإيران .","s":"أثناء انعقاد مؤتمر القمة للدول الأعضاء في منظمة الأوبك، وبمبادرة من الرئيس الجزائري هواري بومدين تقابل مرَّتين شاه إيران وصدام حسين نائب رئيس مجلس قيادة الثورة، وأجرَيا محادثاتٍ مُطَوَّلة حول العلاقات بين الدولتين، وقرَّر الطرفان إجراءَ تخطيط نهائي لحدودهما البرية، بناء على اتفاق القسطنطينية سنة 1913م، وتحديد الحدود النهرية حسب خط تالوك (أعمق النقاط في وسط النهر)، وإعادة الثقة المتبادلة، ووضع حدٍّ"},{"id":5292,"era":"c14","t":"تولي اللواء أمين الحافظ الرئاسة في سوريا .","s":"تولَّى اللواء أمين الحافظ الرئاسة في سوريا، وذلك بعد استقالة اللواء لؤي الأتاسي. وشهد حكمُ أمين الحافظ انقلابًا عسكريًّا دمويًّا انتهى بإقصائه عن السلطة واعتقالِه، وأصبح نورُ الدين مصطفى الأتاسي رئيسًا للجمهورية، وحافظ الأسد وزيرًا للدفاع."},{"id":5293,"era":"c14","t":"استقلال ماليزيا (اتحاد ماليزيا) .","s":"اقترح رئيس وزراء الملايو تانكو عبد الرحمن في 10 شوال 1380هـ / 27 آذار 1961م العملَ مع بريطانيا وشعوب بلاد سنغافورة وبورنيو الشمالية وبروناي وسارواك؛ للوصول إلى اتفاقٍ لوضع مخطَّط يهدف إلى إيجاد تعاون سياسي واقتصادي بين هذه البلدان يؤدِّي إلى وَحدتِها، ما دامت كُلُّها تعود إلى أصلٍ واحد، فتجاوب الزعماء لهذا الاقتراح، ثم جرت محادثاتٌ، وأعلن الاتحادُ بموجِبِ استفتاء جرى في ربيع الثاني 1382هـ / أيلول "},{"id":5294,"era":"c14","t":"ثورة 14 أكتوبر في اليمن .","s":"انطلقت الشَّرارةُ الأولى لثورة 14 أكتوبر في الجزء الجنوبي من اليمن ضِدَّ الاستعمار البريطاني، من جبال ردفان، بقيادة راجح بن غالب لبوزة الذي قُتِلَ في اليوم الأول للثورة، وقد شَنَّت السلطاتُ الاستعماريةُ حملاتٍ عسكريةً غاشمةً استمرَّت ستةَ أشهر، ضربت خلالها القرى والسَّكَّان الآمنين بمختلِف أنواعِ الأسلحة؛ فتشَرَّد على إثْرِها آلاف المدنيين العُزل، واتَّبعت القوات البريطانية في هجماتها وغاراتها على"},{"id":5295,"era":"c14","t":"استقلال نيجيريا باسم اتحاد نيجيريا .","s":"أعلنت بريطانيا عام 1318هـ / 1900م قيام محمية نيجيريا الشمالية، وعَيَّنت مندوبًا ساميًّا مِن قِبَلها، وفي عام 1333هـ / 1914م جاء الحاكم الإنجليزي لوغارد، فحكم البلاد حكمًا ثنائيًّا بين نيجيريا الشمالية ونيجيريا الجنوبية، وجعل من الجنوبيةِ مُستعمَرةً، ومن الشمالية محميَّةً، وكانت تحاوِلُ أن تنصِّرَ عددًا من الناس يتسَلَّمون الحكم من بعدها، وقد برز قُبَيل الحرب العالمية الثانية ناندي أزيكوي الذي قدَّ"},{"id":5296,"era":"c14","t":"استقلال كينيا .","s":"في القرن الثامن الميلادي استوطن التجَّارُ العَرَبُ الساحِلَ الشرقي لأفريقيا، وفي القرن السادس عشر سيطر البرتغاليون على البلاد. وفي عام 1887م قامت شركة أفريقيا الشرقية باستئجار جزءٍ من أرض الساحل. وفي عام 1895م ادَّعت بريطانيا أحقيَّتَها في منطقة داخلية كبيرة أسمَتْها محميَّةَ شرق أفريقيا. في عام 1920م أصبحت محميَّةُ شرق أفريقيا تعرف باسم كينيا. وفي عام 1923م رفضت بريطانيا مطالَبةَ المستوطِنين البي"},{"id":5297,"era":"c14","t":"وفاة الشيخ محمود شلتوت شيخ الجامع الأزهر .","s":"هو الشيخ محمود شلتوت شيخ الجامع الأزهر بين سنة 1958 و1963م. ولِدَ في منية بني منصور، مركز إيتاي البارود بمحافظة البحيرة في مصر سنة 1893م. وحفظ القرآن الكريم وهو صغير، ونال إجازةَ العالمية سنة 1918م، وكان خطيبًا موهوبًا جهير الصوتِ. عُيِّن مدرسًا بالمعاهد، ثم بالقسمِ العالي، ثمَّ مدرِّسًا بأقسام التخصص، ثم وكيلًا لكلية الشريعة، ثم عضوًا في جماعة كبار العلماء، ثم شيخًا للأزهر، وكان أولَ حامل لِلَقَب"},{"id":5298,"era":"c14","t":"مؤتمر القمة العربية الأول (قمة القاهرة) .","s":"انعقد مؤتمرُ القمة العربية الأوَّل لأعضاء دول الجامعة العربية في القاهرة ما بين 13 إلى 16 من الشهر الأول لعام 1964م، وترأَّسه الرئيسُ جمال عبد الناصر، وحضره الرئيس أحمد الشقيري مندوبًا عن فلسطين، وقد نتج عن هذا المؤتمر عدةُ قرارات، كان من أبرزها: إنشاءُ قيادة عسكرية عربية واحدة لحماية تنفيذ المشروعات العربية بشأن استغلال مياه نهر الأردن وروافده، وإنشاءُ كِيانٍ فلسطيني يجمع إرادةَ شعب فلسطين، ويقيم"},{"id":5299,"era":"c14","t":"وفاة الكاتب الشهير عباس محمود العقاد .","s":"هو عباس بن محمود بن إبراهيم بن مصطفى العقَّاد، الكاتب المشهور، إمامٌ في الأدب، من المكثرين كتابةً وتصنيفًا مع الإبداع. أصلُه من دمياط، انتقل أسلافُه إلى المحلة الكبرى، وكان أحدُهم يعمل في عقادة الحرير. فعُرِف بالعقَّاد. وعمل أبوه صرَّافًا في إسنا، فتزوج بكُردية من أسوان، ووُلِدَ عباسٌ في أسوان وتعلَّم في مدرستها الابتدائية. وشُغِف بالمطالعة. وسعى للرِّزق فكان موظفًا بالسكة الحديدية، ثم بوزارة الأو"},{"id":5300,"era":"c14","t":"تخلي الملك سعود بن عبد العزيز عن إدارة الحكم لأخيه الأمير فيصل .","s":"أصدر العُلماء فتوى أيَّدها معظمُ أفراد الأسرة المالكة حول تسليمِ السلطة بأكملها للأمير فيصل، على أن يبقى الملكُ سعودٌ ملكًا للبلاد، وعلى إثْرِ هذه الفتوى أصدر مجلسُ الوزراء سلسلةً من القرارات تمَّ من خلالها تشكيلُ وزارة الدفاع، ووزارة الداخلية."},{"id":5301,"era":"c14","t":"استقلال زنجبار (تنزانيا) .","s":"في عام 1381هـ استقلَّت المنطقة الأولى من تنزانيا، وهي تانجانيقا، أمَّا المنطقة الثانية، وهي زنجبار، فقد كانت محميَّةً بريطانية منذ عام 1308هـ / 1890م وسلطانها عبد الله خليفة، ومعه مقيمٌ بريطاني يُعَدُّ هو المسيطرَ الفعليَّ والحاكمَ الرسمي، ثم أصبحت سلطنةً مستقلة عن الأسرة الحاكمة في عمان عام 1383هـ / 1963م، ثم لم يلبَثْ أن وَقَع انقلاب في زنجبار بتاريخ 27 شعبان 1383هـ / 12 كانون الثاني 1963م وأُزي"},{"id":5302,"era":"c14","t":"نشأة منظمة التحرير الفلسطينية  .","s":"مُنظَمَّةٌ سياسية شِبهُ عسكرية معترَفٌ بها في الأمم المتحدة والجامعة العربية كمُمَثِّل شرعي وحيد للشعب الفلسطيني داخل وخارج فلسطين، ولتمثيل الفلسطينيين في المحافِلِ الدولية، وهي تضُمُّ معظمَ الفصائل والأحزاب الفلسطينية تحت لوائِها. ويُعدُّ رئيسُ اللجنة التنفيذية فيها رئيسًا لفلسطين والشعب الفلسطيني في الأراضي التي تسيطِرُ عليها السلطةُ الفلسطينية في الضفة الغربية وقطاع غزة، بالإضافة إلى فلسطينيِّي"},{"id":5303,"era":"c14","t":"عقد المؤتمر الفلسطيني الأول .","s":"قام أحمد الشقيري مندوب فلسطين في الجامعة العربية بناءً على تكليفٍ من مؤتمر القمة العربية الأول في القاهرة بإجراء اتصالات مع الدول العربية والفعاليات والجمعيات والهيئات الفلسطينية، وقد أسفرت هذه الاتصالاتُ عن عقد المؤتمر الفلسطيني الأول في القدس بتاريخ 28 مايو، وصدرت عنه قرارات، أهمها:1- قيامُ إسرائيل خَطَرٌ أساسي يجب دَفْعُه سياسيًّا واقتصاديًّا وإعلاميًّا.2- إنشاءُ قيادة عربية موحَّدة لجيوش الدول"},{"id":5304,"era":"c14","t":"مؤتمر القمة العربية الثاني (قمة الإسكندرية) .","s":"عُقِدَ مؤتمر القمَّة العربية الثاني لأعضاء جامعة الدول العربية \"قمة الإسكندرية\" في 11 مايو / أيلول 1964م بقصر المنتزَهْ بالإسكندرية، بحضورِ أربعة عشر قائدًا عربيًّا، وصدرَ عن المؤتمر بيانٌ ختامي تضمَّن مجموعةً من القراراتِ."},{"id":5305,"era":"c14","t":"تنحية الملك سعود عن الحكم ومبايعة أخيه ولي العهد الأمير فيصل بالملك .","s":"اجتمع العلماءُ في منزل مفتي الديار السعودية محمد بن إبراهيم آل الشيخ, ثمَّ عَقَدوا اجتماعًا مع الأمراءِ في فندق الصحراء بالرياض, ثم صادق مجلِسُ الوزراء على قرارين: فتوى العُلَماء بمبايعة ولي العهد الأمير فيصل مَلِكًا للبلاد, ورسالة وقَّعها جميعُ أفراد الأسرة المالكة تبايع الأميرَ فيصلًا ملكًا للبلاد. كما بايع الملِكَ الجديد أعضاءُ مجلس الشورى، وممثِّلو أهمِّ مناطق المملكة، ثمَّ توجَّه أعضاءُ الحكو"},{"id":5306,"era":"c14","t":"مؤتمر القمة الثاني لحركة عدم الانحياز .","s":"عُقِد مؤتمرُ القمة الثاني لحركة عدم الانحياز في القاهرة بين 5- 10 أكتوبر نوقِشَت فيه قضية فلسطين ضمن البند الخاص \"بتحرير البلاد المستَعمَرة واستئصال الاستعمار بشكليه القديم والجديد، وكذلك الإمبريالية\". وتقرَّر في النهاية إدانةُ السياسة الاستعمارية المتَّبَعة في الشرق الأوسط، و\"تأييد استعادة حقوق الشعب الفلسطيني كاملةً في بلده، وحقُّه الثابت في تقرير المصير\"، كما أعلن القادةُ المشاركون في هذه القمة"},{"id":5307,"era":"c14","t":"استقلال غامبيا .","s":"كانت غامبيا قطعةً صغيرة من السنغال لكِنَّها بَقِيَت تحت الحماية الإنجليزية، بينما باقي السنغال تحت الحماية الفرنسية، حصلت غامبيا على الاستقلال الذاتي وأصبحت دولةً مستقلَّةً ضِمنَ رابطة الشعوب البريطانية (الكومنولث) في 17 شوال 1384هـ / 18 شباط، وأصبح الحكمُ جمهوريًّا فيها في محرم 1390هـ/ نيسان 1970م، وغالبية سكَّان غامبيا من المسلمين."},{"id":5308,"era":"c14","t":"حل الجماعة الإسلامية في باكستان ومصادرة أموالها .","s":"صدرت أوامِرُ مِن حكومة أيوب خان (سُنِّي) رئيس باكستان بحلِّ الجماعة الإسلامية، ومُصادرة أموالها، وكانت الحكومةُ مِن قبل شهرٍ قد صادرت مجلة ترجمان القرآن، التي كان يُصدِرُها أبو الأعلى المودودي، وزجَّت به مع أعضاءِ جماعته البارزين في السُّجون، وكان هذا قبل وقوعِ  الحرب الثانية بين الهند وباكستان على كشمير."},{"id":5309,"era":"c14","t":"وفاة الزعيم الأمريكي المسلم مالكوم إكس .","s":"هو مالكوم إكس بن أورلي ليتل، أو الحاج مالك شباز؛ من الشخصيات الأمريكية المسلِمة البارزة في منتصف القرن الماضي، كانت حياتُه سلسلةً من التحولات؛ حيث انتقل من قاع الجريمة والانحدار إلى تطرُّف الأفكار العنصرية، ثم إلى الإسلام. وُلِد مالكوم في 6 ذي القعدة 1343هـ/ 19 مايو 1925م، وكان أبوه \"أورلي ليتل\" قسيسًا أسود من أتباع \"ماركوس كافي\" الذي أنشأ جمعيةً بنيويورك ونادى بصفاء الجنس الأسود وعودته إلى أرض أج"},{"id":5310,"era":"c14","t":"وفاة ملك مصر السابق فاروق بن فؤاد .","s":"هو الملك فاروق بن الملك فؤاد الأول بن الخديوي إسماعيل بن إبراهيم باشا بن محمد علي باشا. آخِرُ ملوك مملكة مصر والسودان. ولِدَ في 11 فبراير 1920م في القاهرة، ونشأ بها كابن وحيدٍ بين خمسِ شقيقات أنجبهم الملك فؤاد الأول، ثم أكمل تعليمَه بفرنسا وإنجلترا، أصبح وليًّا للعهد وهو صغيرُ السن، واختار الملك الوالِدُ فؤادُ الأولُ لولي عهده لقَبَ أمير الصعيد. وتحمَّل فاروقٌ المسؤولية وهو صغير السن؛ حيث إنه تولّ"},{"id":5311,"era":"c14","t":"وفاة عبدالله بن سليمان وزير الملك عبد العزيز .","s":"هو معالي الوزير عبد الله بن سليمان الحمدان وزير الملك عبد العزيز، وُلِدَ سنة 1305هـ 1887م بمدينة عنيزة في القصيم. قصد الهند بعد أن تجاوز الطفولةَ، ثم تنقَّل بينها وبين البحرين وبعض بلاد الخليج في طلب الرزق، ثم استقرَّ في الرياض؛ حيث كان له أخٌ اسمُه محمد يعمل في ديوان الملك عبدالعزيز قبل أن يتمَّ تنظيم الديوان، ولما مَرِضَ محمد ناب عنه عبد الله سنة 1338هـ 1919م، ولما رأى الملك عبد العزيز حُسنَ خَط"},{"id":5312,"era":"c14","t":"نشأة منظمة مجاهدي خلق المعارضة في إيران  .","s":"منظمة مجاهِدي خلق المعارضة الإيرانية أكبر وأنشط حركة معارضة إيرانية. تأسَّسَت المنظَّمة على أيدي مثقَّفين إيرانيين؛ بهدف إسقاط نظامِ الشاه، وقد أعدَمَ نظامُ الشاه مؤسِّسيها وعددًا كبيرًا من أعضاء قيادتِها، وبعد سقوطِ نظام الشاه إثرَ قيام \"ثورة الخميني الإيرانية\" أدَّت منظمة مجاهدي خلق دورًا كبيرًا في انتصار الثورة، وقد اعتمد على قوَّتها أبو الحسن بني صدر أوَّلُ رئيس للجمهورية الإيرانية، لكِنْ ظهرت"},{"id":5313,"era":"c14","t":"عزل الرئيس الجزائري أحمد بن بلة وتولي هواري بومدين .","s":"بعد أن انتُخب أحمد بن بلة رئيسًا للجزائر لم تَرُقْ للناسِ طريقتُه في الحكم؛ حيث أعلن القوانينَ الاشتراكيَّةَ ولم يُطَبِّقْها، وأبقى القانونَ الفرنسي ولم يُقِمِ المحاكِمَ الشرعية، وبقيت السياسةُ الخارجية بيد فرنسا، فتمَّ تشكيلُ مجلس عسكري برئاسة العقيد هواري بومدين في 20 صفر 1385هـ / 19 حزيران, فقَرَّر هذا المجلس عزلَ الرئيس أحمد بن بلة والقَبضَ عليه بتهمة استخدام أموال الدولة في غير وجهِها الشرعي،"},{"id":5314,"era":"c14","t":"ثورة ظفار التحررية في عمان .","s":"تعد ثورةُ ظفار في الجزء الجنوبي من سلطنة عمان على حُكمِ السلطان سعيد بن تيمور واحدةً من أطولِ الثورات العربية؛ حيث امتدَّت زهاءَ عشرة أعوام، وقد واكبت حقبةَ الثورات التحرُّرية من الاستعمار العالمي، والتي شَهِدتْها المنطقة العربية في الخمسينيات والستينيات من القرن العشرين، ومن أسبابِ الثورة وقيامها: حالةُ التخَلُّف التي سادت سلطنةَ مسقط وعمان بشكلٍ عامٍّ، وإقليم ظفار بشكل خاص، وكثرة الممنوعات والمع"},{"id":5315,"era":"c14","t":"استقلال جزر المالديف  .","s":"جُزُر المالديف مجموعةُ جُزُر صغيرة تقع في قارة آسيا في المحيط الهندي، جميعُ سُكَّانها مسلمون، وأوَّلُ من استعمرها هم البرتغاليون، ثم خلَفَهم الهولنديون، ثم الإنجليز عام 1211هـ، لكِنْ بَقِيَ الهولنديون أصحابَ النفوذ إلى عام 1305هـ؛ حيث أصبحت الجُزُر كُلُّها تحت الحماية الإنجليزية، ولكِنَّ قبضة الإنجليز بدأت بالتراخي عام 1350هـ؛ فأعلن السلطان شمس الدين إسكندر الدستورَ، وتغيَّرَ أسلوبُ الإنجليز الذين"},{"id":5316,"era":"c14","t":"الحرب الثانية بين باكستان والهند بشأن كشمير .","s":"اخترق الجيشُ الهندي خطَّ وَقْفِ النار في كشمير، واحتَلَّ أربعة مراكز في دولة كشمير الحرة، فقامت باكستان مباشَرةً برَدِّ فعلٍ مفاجئ بجنوبي كشمير التي تحتلُّها الهند، فقامت الهندُ بشنِّ هجوم على الحدود الباكستانية في منطقة لاهور بالإضافة إلى قصفِ المُدُن الباكستانية بالقنابل، فانتقلت الحربُ من أرض كشمير إلى أرض باكستان، ثم فتحت الهند جبهةً أخرى في جنوبي باكستان على محور كراتشي، فردَّ الباكستانيون ال"},{"id":5317,"era":"c14","t":"محاولة انقلاب فاشلة على الرئيس العراقي عبد السلام عارف  .","s":"كان عبد السلام عارف من المعارِضين للوَحدة مع مصر، وكان عارف عبد الرزاق رئيسُ الحكومة يطمَحُ برئاسة الجمهورية، فما إنْ سافر الرئيس إلى الدار البيضاء لحضور مؤتمر القمة حتى بدأ نشاطُه، وأخذ الضبَّاطُ الناصريون بالاتِّصالِ بالضبَّاط أصحاب المراكز الحساسة، ويشجِّعونهم على العمل ضِدَّ الرئيس عارف، ووضعوا خطةً للانقلاب؛ فقاموا بعمل مظاهراتٍ من الطلَّاب والعمَّال بتوجيه من الضباط الناصرِّيين، وفي الوقتِ ن"},{"id":5318,"era":"c14","t":"فشل الثورة الشيوعية الثانية في أندونيسيا .","s":"أعاد الحزبُ الشيوعي في أندونيسيا تنظيمَ نفسه مجدَّدًا بعد أن فَشِلَت ثورته الأولى عام 1367هـ، وبدأ بتقويةِ وَضْعِه وخاصةً مع مساعدة الرئيس أحمد سوكارنو لهم بالإضافة للأموال الضخمةِ من المعسكر الشيوعي، ثم أعلن الحزبُ الشيوعي أنَّه سيكون الحزبَ الوحيدَ، وأنَّه سيحوِّل البلادَ إلى دولة تسير حَسَب المنهج الشيوعي، وبدأت أعمالُ الشيوعيين الإرهابية، وأخافوا الناس؛ فهجموا على المدارس الإسلامية والشخصيات ا"},{"id":5319,"era":"c14","t":"وفاة الشيخ محمد بن عبد العزيز ابن مانع .","s":"هو الشيخُ الفقيه محمد بن عبد العزيز بن محمد بن مانع الوهيبي التميمي النجدي. ولِدَ في مدينة عنيزة إحدى مدن القصيم سنة 1300 هـ، ولما بلغ السابعةَ أدخله والده الكتاتيبَ؛ ليتعلم بها القرآنَ، ولم يلبث والدُه أن توفِّي، فشرع في القراءةِ على عُلماء بلده، فقرأ على عمِّه الشيخ عبد الله، وعلى الشيخ صالح العثمان القاضي، ولما بلغ الثامنةَ عَشْرة من عمره سافر إلى بغداد، واتصل بالعلامة السيد محمود شكري الألوسي،"},{"id":5320,"era":"c14","t":"انعقاد مؤتمر طشقند لحل النزاع الهندي الباكستاني .","s":"بعد أن أُوقِفَ إطلاقُ النارِ بين الهند وباكستان بقرارٍ من مجلس الأمن تمَّ اقتراحُ تدخُّل الاتحاد السوفيتي كوسيط؛ لفضِّ النزاعِ بين باكستان والهند حول قضية كشمير، وذلك في أعقاب حرب 1965م، فطَرَحت روسيا أن يجتَمِعَ الطرفان في \"طشقند\" قاعدةِ جمهورية أوزبكستان الإسلامية، فعُقِدَ مؤتمرٌ حَضَره رئيس وزراء الهند والرئيس الباكستاني، وكان الرئيس الروسي طوال المؤتمر في طشقند، وقد تمَّ التوصُّلُ إلى اتفاقٍ م"},{"id":5321,"era":"c14","t":"وفاة الحاج سير أحمدو بلو زعيم إقليم شمال نيجيريا .","s":"هو الحاج سير أحمدو بلو بن الأمير إبراهيم بن فودي: زعيمٌ سياسيٌّ نيجيري شمالي. مفكرٌ إسلاميٌّ سياسي كان من أبرز قادةِ مقاومة الاستعمار الإنجليزي. وُلِدَ سنة 1909م بقرية رابا، وتعلَّم في كُتَّابها سنتين، ثم أخذه أخوه إلى مدينة صكتو؛ لِيُلحِقَه بمدرسةٍ ابتدائية هناك، فدرس فيها القرآنَ الكريم، والحساب، واللغة الإنجليزية، والتاريخ، لكنَّه أبدى أسَفَه حين رأى أنَّ التاريخَ الذي يَدرسُه تاريخ إنجلترا بدل"},{"id":5322,"era":"c14","t":"انقلاب عسكري بعثي في سوريا على أمين الحافظ رئيس الجمهورية .","s":"بعد انقلابِ حزبِ البَعثِ السوري على الحكومة العربية السورية في الثامن آذار عام 1963م في سوريا قامت حكومةٌ ضعيفة توالى عليها ثلاثةُ رؤساء، وبدأت الحكوماتُ البعثيةُ بسلسلة من الإجراءات الاشتراكية، إلا أنَّ الفترة الأولى من الحكم البعثي الاشتراكي في سوريا كانت مضطربةً؛ فوقع انقلابٌ عسكريٌّ بعثيٌّ في 23شباط / فبراير 1966م بقياده صلاح جديد (نصيري بعثي) بهدف الإطاحة بحكومة الجمهورية العربية السورية التي"},{"id":5323,"era":"c14","t":"وفاة عبد السلام عارف رئيس جمهورية العراق .","s":"هو عبد السلام محمد عارف الجميلي: ثاني رؤساء العراق بعد سقوطِ المَلَكيَّة وقيام الجمهورية العراقية، وقد وُلِدَ في مدينة \"حديثة\" على نهر الفرات في أسرة فقيرة، ثم انتقل مع أسرته إلى بغداد والتحق بالمدارس الحكومية، ثم دخل الكليةَ الحربيَّةَ وتخرَّج منها برتبة ملازم، ثم اشترك في حربِ فلسطين، وقابل هناك عبدَ الكريم قاسم، وانضمَّ عن طريقه إلى اللجنة المركزية للثورة العراقية، وقام بدورٍ كبير في الثورة على"},{"id":5324,"era":"c14","t":"عودة العلاقة شكليًّا بين السعودية ومصر .","s":"استأنفت السعوديةُ عَلاقتَها الوُدِّيَّةَ شَكليًّا مع مصر بعد تقديمِ تنازلاتٍ من عبدالناصر. وأضحت السعوديةُ قادرةً على  تقديمِ المساعدة الماليَّة لدُولِ المجابهة العربية مع إسرائيل, وكانت مصرُ قد استنزفتها حربُ اليمن وهزمَتها إسرائيلُ في حزيران 67, ففقدت شبه جزيرة سيناء، وعوائدَ قناة السويس, فتركَّزت كُلُّ جهودها على استعادة قدرتها الدفاعيَّة، واتِّباع سياسةٍ خارجيةٍ أكثرَ مرونةً؛ فقَدَّمت تنازلاتٍ"},{"id":5325,"era":"c14","t":"تنازل الرئيس التركي جمال غورسيل وفوز جودت صوناي بالرئاسة .","s":"سار الرَّئيسُ التركي جمال غورسيل على نهجِ مصطفى كمال، خاصةً وأنَّ حُكمَه كان حُكمًا عسكريًّا، ثم إنَّ أوضاعَ الرئيس جمال الصحيَّة ساءت؛ ممَّا دعاه إلى الاعتزالِ قبل انتهاء فترةِ الرئاسة بما يقرُبُ من السنتين، وأُجريت انتخاباتٌ لاختيار رئيسٍ مكانه، فنجح جودت صوناي."},{"id":5326,"era":"c14","t":"تحويل اتحاد نيجيريا إلى جمهورية نيجيريا الاتحادية .","s":"قام قائدُ الجيش جونسون أغوي إيرونسي وهو من قبائل الإيبو (الوثنية) بإقالةِ الحكومة الاتحادية والحكومات الإقليمية، وعيَّن حاكِمًا عسكريًّا لكل إقليم، وبذلك صارت البلاد كلُّها تحت قبضته، وشكَّل مجلسًا عسكريًّا أعلى، وأعلنت السلطةُ العسكريةُ مقترحاتٍ في شوال 1385هـ / شباط 1966م لإلغاء الدولة الاتحادية وإقامة دولة وَحدَوية، ثم غيَّرَت السلطة العسكرية اسمَ البلاد؛ فأصبحت جمهورية نيجيريا الاتحادية بعد أن"},{"id":5327,"era":"c14","t":"وفاة الشيخ عبد الرحمن المعلمي .","s":"هو الشيخُ العلامة أبو عبد الله عبد الرحمن بن يحيى بن علي بن أبي بكر المعَلِّمي العتمي اليمني، وُلِدَ في أولِ سنة 1313هـ بقرية المحاقرة  التابعة لمحافظة صنعاء، قرأ القرآنَ على والدِه، ثم درس في المدرسةِ الحكومية، وتعلَّم القرآنَ والتجويدَ والحسابَ، ثم قرأ النحو، ثم ارتحل إلى جازان سنة 1336هـ، فترأَّس فيها القضاءَ، ثم ارتحل إلى عَدَن ثمَّ الهند مصحِّحًا لكتب الحديث وعلومه، ثمَّ إلى مكة سنة 1371هـ وك"},{"id":5328,"era":"c14","t":"محاولات انقلاب فاشلة على الرئيس العراقي عبد الرحمن عارف .","s":"كان عارف عبد الرزاق (ناصريُّ التوجُّه) قد حاول الانقلابَ على رئيس العراقِ عبد الرحمن عارف الجميلي في جمادى الأولى 1385هـ / 16 أيلول بالاشتراكِ مع عددٍ من كِبار الضبَّاط العراقيِّين، وبدعمٍ مِن المخابراتِ السُّوريَّةِ؛ لِقَلبِ نظامِ الحُكمِ في العراق, ففَشِلَ وهرب إلى مصرَ، ثم تسَلَّل من مصرَ إلى بغدادَ مع بعض الأشخاص، وفي 11 ربيع الأول من هذا العامِ استولى على المطارِ العسكريِّ بالموصل، وهاجمت الط"},{"id":5329,"era":"c14","t":"قتل سيد قطب .","s":"هو سيد قطب بن إبراهيم؛ ولد في قرية موشا في أسيوط سنة 1324هـ / 1906م. نشأ سيد في مجتمعٍ قُروي صعيدي. حفظ القرآنَ الكريمَ كاملًا من نفسِه وهو في سن العاشرة؛ ذهب إلى القاهرة في سن الرابعة عشرة وعاش عند خاله، والْتَحَق أوَّلًا بإحدى مدارس المعلِّمين الأوَّليَّة وعمل مدرسًا ابتدائيًّا. بدت في القاهرة في هذه المدَّة سوءاتُ الاحتلالِ الأجنبي ومفاسدُه؛ حيث سادت عوامِلُ التمزُّق الطَّبَقي والصِّراع الحزبي،"},{"id":5330,"era":"c14","t":"تنحية الرئيس الأندونيسي أحمد سوكارنو وتولية سوهارتو  .","s":"بعد أن فَشِلَت الثَّورةُ الشُّيوعيَّةُ الثانية، وكان الرئيسُ الأندونيسي أحمد سوكارنو يؤيِّدُها ويريدُ أن يعيدَ وَضعَ الشيوعيَّةِ على ما كانت عليه، ومع أنَّ الشَّعبَ كان قد انتخبه رئيسًا مدى الحياة، إلَّا أنَّه قد ثار عليه النَّاسَ؛ فقامت المظاهراتُ ضِدَّه وضِدَّ الشيوعيَّة، وأعلنت الأحزابُ السياسيَّة في \"جاوه الغربية\" مطالبتَها المجلسَ الاستشاريَّ بالنَّظرِ في أمر تنحيتِه، وأعلنت رابطةُ القضاة وال"},{"id":5331,"era":"c14","t":"دعم اليمن الجنوبي لثوار ظفار التحررية .","s":"يعدُّ الانتماءُ المشترك للجبهة القومية في اليمن الجنوبي والجبهة الشعبية لتحرير ظفار إلى الجناحِ اليساري في حركة القوميين العرب عامِلًا مهمًّا في دَعمِ ثوار ظفار التحررية، حيث أعلن اليمنُ الجنوبي استعدادَه لتقديم كلِّ الدعم للمُعارضة العمانية باعتبار أنَّ ذلك جزء من أهدافه الوطنية. وعسكريًّا وفَّر اليمنُ الجنوبي قواعِدَ للجبهة في كلٍّ من حوف والغيظة والمكلا وعدن، إضافةً إلى وسائل التدريب العسكري، ب"},{"id":5332,"era":"c14","t":"الحرب العربية الإسرائيلية الثالثة نكسة 5 حزيران (حرب الأيام الستة) .","s":"قامت إسرائيل بشنِّ غارةٍ على سوريا انتقامًا من الفدائيِّين الذين دخلوا فلسطينَ من الجبهة السورية، وأسقطت بعضَ الطائرات السورية فوق ضواحي دمشق، فأمر جمال عبد الناصر القواتِ المصريَّة أن تزحَفَ إلى سيناء، وطلب إنهاءَ عمل قوات الطوارئ الدوليَّة فيها، وأعلنت مصرُ إغلاقَ خليج العقبة أمامَ السُّفُن الإسرائيلية والسُّفُن التي تحمِلُ البضائع لها، ونصحت روسيا مصر ألَّا تبدأ هي بالهجومِ حتى يكونَ الإسرائيلي"},{"id":5333,"era":"c14","t":"عبد الرشيد علي رئيسًا للصومال بعد آدم عبد الله .","s":"انتَخَب المجلسُ الوطني في الصومال رئيس الوزراء عبد الرشيد علي شيرمارك رئيسًا لجمهورية الصومال مكانَ آدَم عبد الله."},{"id":5334,"era":"c14","t":"وفاة رجل الأعمال السعودي محمد بن عوض بن لادن .","s":"وُلِدَ المعَلِّمُ محمَّدُ بنُ لادِن عام 1326ه الموافِق 1908م في وادي دوعن بحَضرَمَوتَ، ثمَّ هاجَرَ إلى السُّعوديَّةِ للعَمَلِ، وكان أمِّيًا لا يُجيدُ ‏القِراءةَ والكِتابةَ، لكِنَّه ذو فِطنةٍ وذَكاءٍ، وعَزيمةٍ ومُثابَرةٍ، وقُدرةٍ على تحَمُّلِ المَسؤوليَّةِ؛ فانخَرَط في أعمالِ المُقاوَلاتِ والبِناءِ، واكتَسَب خِبراتٍ كَبيرةً، ثمَّ أنشَأَ شَرِكةً صَغيرةً في مجالِ المقاوَلاتِ، وقام ببناءِ مُنشَآتٍ حُك"},{"id":5335,"era":"c14","t":"اللاءات الثلاث المعبرة عن الموقف العربي المشترك من إسرائيل .","s":"تمَّ خِلالُ مؤتمر الخرطوم وضعُ وإقرارُ مبادئ تنسيق الدول العربية, وخاصةً فيما يخصُّ التسوية في الشرق الأوسط. وُضِعَت في الخرطومِ صيغةُ اللاءات الثلاث المعروفة، والمعبِّرة عن الموقف العربي المشتركِ حيال إسرائيل \"لا صُلحَ, لا مفاوضاتِ, لا اعتِرافَ\", والتي تمسَّكت بها طوالَ السنوات اللاحقة جميعُ الدول العربية إلى أن خَرَقَت مصرُ في عهدِ السادات هذا الإجماعَ بعقدِ صُلحٍ منفردٍ ومباشِرٍ مع إسرائيل"},{"id":5336,"era":"c14","t":"وفاة المشير عبد الحكيم عامر .","s":"هو المشيرُ محمد عبد الحكيم بن علي عامر، وُلِدَ في 11 ديسمبر 1919م في قرية أسطال مركز سمالوط بمحافظة المنيا في أسرةٍ ثرية، وكان والِدُه عمدةَ القرية، ويُعدُّ المشير أحد رجال ثورة يوليو عام 1952م في مصر. وكان صديقًا مقربًا للرئيس جمال عبد الناصر، ورئيسِ المخابرات صلاح نصر، ووزيرِ الحربية شمس بدران حتى حرب 1967. وقائدًا عامًّا للقوات المسلحة المصرية، ونائِبَ رئيس الجمهورية. تخرَّج عامر من الكلية الحر"},{"id":5337,"era":"c14","t":"إعلان جمهورية اليمن الجنوبية الشعبية استقلالها عن بريطانيا .","s":"كان اليمنُ الجنوبي يمثِّل مجموعةً من المحميات الخاضعة للاحتلال البريطاني، وتنقَسِمُ إلى محميَّات غربية عاصمتها عدن، ومحميَّات شرقية عاصمتها المكلا، وفي حوالي سنة 1960م بدأ يظهرُ حزبُ البعث العربي الاشتراكي باليَمَن الجنوبي متأثرًا بالمدِّ الاشتراكي القومي العربي: مذهبِ جمال عبد الناصر! وتوسَّع في صفوفِ العُمَّال العَدَنيين، وكان يطالِبُ بالاستقلال التام، وبدأ يَقوَى حتى اجتاح البلادَ بالمظاهراتِ و"},{"id":5338,"era":"c14","t":"قرار مجلس الأمن 242 (الأرض مقابل السلام)  .","s":"أصدر مجلسُ الأمن الدولي في 22 نوفمبر قرارًا برقم 242 وذلك في أعقاب نكسة حزيران 67 التي أسفرت عن هزيمة الجيوشِ العربيَّة، واحتلال إسرائيل لمناطِقَ عربية جديدة، وقد جاء هذا القرار كحَلٍّ وسطٍ بين عدة مشاريع طُرِحَت للنقاش بعد الحرب. تضمَّن القرار في مادته الأولى في (الفقرة أ) انسحابَ القوات الإسرائيلية من الأراضي التي احتُلَّت في النزاع الأخير، وإنهاء حالة الحرب والاعتراف ضمنًا بإسرائيلَ دون ربط ذلك"},{"id":5339,"era":"c14","t":"معركة الكرامة  .","s":"كان الفلسطينيون يشكِّلون نسبةً عاليةً من تَعداد سكان الأردن في تلك الفترة، يتمركزون في بلدة الكرامة على الجانب الأردني، وكانوا قد استهدفوا إسرائيلَ مرارًا عبر هَجَمات خلال الحدودِ مِن قِبَل الفدائيين الفلسطينيين. وكرَدِّ فعلٍ على مجموعةٍ من الهجمات التي صدرت من جانب حدود الأردن قام جيشُ الدفاع الإسرائيلي باجتياح بلدة الكرامة في 21 مارس، وقد أعلن رئيسُ الوزراء الإسرائيلي ليفي إشكول في حينها أنَّ ال"},{"id":5340,"era":"c14","t":"مؤتمر الأديان في جاكرتا أندونيسيا .","s":"دعت الحُكومةُ الأندونيسيَّةُ إلى عقدِ مؤتمر للأديان في جاكرتا عام 1387هـ / 1967م فلبَّى الدعوةَ مَن وُجِّهت إليهم، وعُقِدَ المؤتمر في دار المجلس الاستشاري الأعلى ووجَّه فيه الرئيسُ سوهارتو نداءً إلى أتباع الأديان؛ كي يركِّزَ كُلٌّ منهم اهتمامَه التامَّ على مهمة تصعيد مستوى الوعيِ الدينيِّ في أبناء طائفته، وأن يحرصوا على الحيلولة دونَ أن تُحِسَّ طائفة من الطوائف أنَّها مُعَرَّضة لدعايات طائفة أخرى "},{"id":5341,"era":"c14","t":"صدور الميثاق الوطني الفلسطيني .","s":"في عام 1964م أصدر المجلسُ الوطني الفلسطيني -(وكان اسمه المؤتمر العربي الفلسطيني) في دورته الأولى التي عُقِدَت في القدس- الميثاقَ القوميَّ الفلسطينيَّ المبنيَّ على قرارات المؤتمرات السابقة, وأعلن قيامَ منظمة التحرير الفلسطينية. وفي الدورة الرابعة للمجلس الوطني الفلسطيني المنعقد في القاهرة في 10/7/1968م أقرَّت تسميتَه الميثاق الوطني الفلسطيني, وصار الميثاقُ هو البرنامجَ الاستراتيجيَّ لتحرير فلسطين. "},{"id":5342,"era":"c14","t":"انقلاب بعثي يطيح بالرئيس العراقي عبد الرحمن عارف .","s":"لما انتُخِبَ عبد الرحمن عارف رئيسًا للجمهورية كان لمدةٍ سنة واحدة فقط مع إمكان تجديدِها، وكان من المفترض تعديلُ الدستور، ولكِنَّ العدوانَ اليهوديَّ على مصر والأردن وسوريا ومساهمة العراق بالمساعدة أخَّر ذلك، ومع ذلك وقبل انتهاء فترة حُكمِ الرئيس حدث انقلابٌ أطاح بعبد الرحمن عارف؛ فقد قام تنظيمٌ سري باسم (الثوريون العرب) حرَّكه مديرُ الاستخبارات العسكرية وتمكَّن من التواصُلِ مع رئيس الحرس الجمهوري، "},{"id":5343,"era":"c14","t":"قيام النظام الجمهوري في المالديف كبديل لنظام السلطنة .","s":"بعد أن استقلَّت جُزُرُ المالديف سنة 1385هـ وبعد ثلاث سنوات جرى استفتاءٌ شعبي، فوافق الشعبُ على إقامة النظام الجمهوري في الحُكمِ كبديلٍ لنظام السَّلْطنة الذي كان قائمًا، وأُعلِنَ النظام الجمهوري في 20 شعبان 1388هـ / 11 تشرين الثاني، وتسلَّم إبراهيم ناصر رئاسةَ الجمهورية، وكان قبل ذلك يَشغَلُ مَنصِبَ رئاسة الوزراء، وكانت البلاد تُعرَف باسم جُزُر المالديف، ثم أُطلِقَ عليها عام 1389هـ / 1969م اسمَ جمه"},{"id":5344,"era":"c14","t":"انقلاب عسكري يطيح برئيس مالي موديبو كيتا .","s":"قاد الملازمُ أول موسى تراوري انقلابًا عسكريًّا في مالي ضِدَّ نظام الرئيس موديبو كيتا الذي كان يومَها يتنزَّهُ بقاربه الشِّراعي في نهر النيجر، وعند عودتِه إلى الشاطئ ألقِيَ القَبضُ عليه من قِبَل الانقلابيين، وتولَّى الحكمَ لجنةٌ عسكريةٌ تضُمُّ أربعة عشر ضابطًا، ثم نَصَب موسى تراوري نفسه رئيسًا للجمهورية."},{"id":5345,"era":"c14","t":"وفاة الشيخ محمد فؤاد عبد الباقي .","s":"هو الشيخُ محمد فؤاد بن عبد الباقي، باحثٌ ومؤلِّفٌ متخَصِّصٌ في الحديث النبوي، وعالمٌ بتنسيق الأحاديث النبوية ووَضْع الفهارس لها ولآيات القرآن الكريم، وهو مترجِمٌ باللغتين الفرنسية والإنجليزية لكتُبِ المستشرقين في معاجمِ الحديث والقرآن. ولِدَ في إحدى قرى القليوبية في جمادى الأولى 1299هـ / مارس 1882م، ونشأ في القاهرة، وفي سنة 1317 هـ / 1899م عَمِل بمركز تلا التابع لمحافظة المنوفية مدرسًا للُّغة العر"},{"id":5346,"era":"c14","t":"حرب الاستنزاف .","s":"حربُ الاستنزاف تعبيرٌ أطلقه الرئيس جمال عبد الناصر على العمليَّات العسكرية التي كانت تدور بين القوَّات المصرية شَرقَ قناة السويس والقوات الإسرائيلية المحتلَّة لمنطقة سيناء عَقِبَ حربِ الأيام الستة (نكسة حزيران 67) والتي احتلَّت فيها إسرائيلُ الأرضَ العربيةَ في كلٍّ مِن الضَّفَّة الغربية، وقطاع غزة، وهضبة الجولان، وسيناء. وانتهت حربُ الاستنزاف بموافقة عبد الناصر على مبادرة وزير الخارجية الأمريكي رو"},{"id":5347,"era":"c14","t":"وفاة الملك سعود بن عبد العزيز .","s":"هو سعودُ بن عبد العزيز بن عبد الرحمن الفيصل آل سعود: مَلِكُ المملكة العربية السعوديَّة، وهو أوَّلُ ملك للبلادِ بعد أبيه المؤسِّسِ الملك عبد العزيز رحمهما الله. وُلِدَ سعود في الكويت سنة 1319هـ العام الذي استعاد فيه الملك عبد العزيز الرياض، ونشأ سعود في الرياض. وقرأ على بعض مشايخها. وقام برحلاتٍ إلى الخارج. وقاد المعاركَ في حروب أبيه. وتولى العرشَ السعودي عام (1373هـ / 1953) فور وفاة أبيه، وبعهدٍ م"},{"id":5348,"era":"c14","t":"اعتزال الرئيس الباكستاني أيوب خان السلطة وتولية محمد يحيى خان .","s":"تأزَّم الأمرُ في باكستان كثيرًا -وخاصةً بعد الحربِ مع الهند- وزادت المعارَضةُ، وبدأت المطالَبةُ بتقسيم باكستان إلى إقليمين، وفُصِلَ الإقليمُ الشرقي، وزادت الاضطراباتُ، وكانت مكانةُ أيوب خان (سُنِّي) في باكستان بدأت تَضعُفُ؛ بسَبَبِ ازدياد المعارِضين لسياسته، وزاد من قوَّتِها انتقادُ وزير الخارجية ذي الفقار علي بوتو (شيعي) للمعاهدة، وفي هذه الأوضاع تأسَّس حزبُ الشعب الاشتراكي بهدف إقصاءِ أيوب خان ع"},{"id":5349,"era":"c14","t":"انقلاب عسكري بقيادة جعفر النميري في السودان .","s":"كان جعفر محمد النميري قد أُرسِلَ إلى أمريكا للحصول على رتبةِ أركان حرب، ورجع بعد أقل من سنتين ورُفِع إلى رتبة عقيد، وكان قد عُيِّن كقائدٍ ثان في مدرسة المشاة في جبيت، وفي 9 ربيع الأول 1389هـ / 25 أيار قام بانقلابٍ عسكريٍّ واستولى على الحُكم، وأزاح وزارةَ محمد أحمد محجوب، وشكَّل مجلِسًا للثَّورة والحكومة، وأعاد عددًا من الضبَّاط الذين كانوا قد أُقيلوا سابقًا، وكان الانقلابُ العسكريُّ قد استهدف الجب"},{"id":5350,"era":"c14","t":"استعادة المغرب لمنطقة سيدي إفني المحتلة من قبل إسبانيا .","s":"كانت منطقة \"سيدي إفني\" التي تقع جنوبَ مدينة أغادير بالمغرب على المحيطِ الأطلسي بحُكمِ مَوقِعِها الاستراتيجي: محطَّ أطماعٍ استعماريَّةٍ، وهدفًا سَعَت قواتُ الاحتلال الإسباني إلى تحقيقِه باعتبارها بوابةً بحريةً مؤهِّلةً للإنزال العسكري والعمليَّات الحربية؛ ولطبيعةِ سيدي إفني وأرضيتها الصالحة لهُبوط الطائرات وتضاريسها التي تجعل منها حِصنًا يُطِلُّ على امتداداتٍ شاسعةٍ مِن عُمقِ تراب آيت باعمران (وهو "},{"id":5351,"era":"c14","t":"وفاة القارئ الشيخ محمد صديق المنشاوي .","s":"هو المقرئُ الشيخ محمد صديق المنشاوي، أحدُ رُوَّادِ التلاوة بمصر، تميَّز بأسلوبٍ مُمَيَّز وحزين في تلاواتِه. وُلِدَ بقرية البوري بمحافظة سوهاج بمصر، وأتمَّ حِفظَ القرآن وهو في الثامنة؛ حيث نشأ في أسرةٍ تهتَمُّ بالقرآن حفظًا وتلاوةً؛ فأبوه الشيخ صديق هو الذي علَّمه فنَّ قراءة القرآن الكريم، ذاع صِيتُ محمد ولَقِيَ قَبولًا حسنًا لعُذوبةِ صَوتِه وجماله وانفرادِه بذلك، كان متقِنًا لمقاماتِ القراءة والان"},{"id":5352,"era":"c14","t":"ثورة الفاتح بقيادة معمر القذافي وإنهاء الحكم الملكي في ليبيا .","s":"زادت نِقمةُ النَّاسِ على النِّظامِ الحاكم في ليبيا، وكانت تزدادُ كُلَّما ازداد التودُّدُ للإيطاليين الذين كانوا بالأمسِ محتلِّين وأذاقوا الناسَ الويل، وأيضًا لعدَمِ مقاطعتهم لإسرائيل رغمَ صدور قرار المقاطعة من الجامعة العربية، ثمَّ ازدياد النفوذ الأمريكي في المنطقة، وغيرها من الأمور التي ولَّدت الحِقدَ الشعبيَّ، وظهرت المعارضةُ. وفي 19 جمادى الآخرة 1389هـ / 2 أيلول (سبتمبر) تحرَّك الجيشُ بقيادةِ ا"},{"id":5353,"era":"c14","t":"اليهود يحرقون المسجد الأقصى .","s":"إنَّ مِن أهدافِ اليهود إزالةَ المسجد الأقصى ومسجد الصَّخرة؛ لإقامةِ هيكلِ سليمانَ المزعومِ الذي يدَّعون زُورًا وبهتانًا أنَّه كان مُقامًا في نفسِ مكان المسجد، وأنَّ بناءه هو السَّبيلُ لظهور مسيحِهم المنتظَرِ الذي يدَّعون أنَّهم سيقتلون العالَم أجمعَ معه، فكان من تخطيطِهم إحراقُ المسجدِ مِن أجْلِ هَدمِه؛ فقامت السُّلطاتُ اليهودية ُبهدمِ العقاراتِ الملاصقة للمسجد الأقصى، ثم قامت بنَسفِ جميع المباني "},{"id":5354,"era":"c14","t":"عقد أول مؤتمر قمة إسلامي في الرباط .","s":"بعد أن أقدم اليهودُ على إحراقِ المسجِدِ الأقصى، واستاء العالمُ الإسلامي جميعًا من هذا الفعلِ المُجرِم، بادر الملِكُ الحسن الثاني مَلِكُ المغرب بتوجيهِ دعوةٍ إلى رؤساء العالم الإسلامي للاجتماعِ في الرِّباطِ عاصمةِ المغرب؛ للاتفاقِ على خِطَّةِ عَمَلٍ إسلامية موحَّدة تهدف إلى الدِّفاعِ عن القدس الشريف، وحمايةِ البِقاع المقَدَّسة ومعالمه الحضارية؛ فعُقِدَ بالفعلِ أوَّلُ مؤتمر قمة إسلامي في الرباط في ا"},{"id":5355,"era":"c14","t":"اغتيال الرئيس الصومالي عبد الرشيد وتولي محمد سياد بري .","s":"اغتال أحدُ أفراد شرطة الصومال رئيسَ الجُمهورية عبد الرشيد علي شيرمارك في 4 شعبان 1389هـ / 15 تشرين الأول، وبعد ستةِ أيام سيطر الجيشُ بانقلابٍ عسكريٍّ على الحُكمِ عَشيَّةَ اليوم الذي كان مقررًا فيه إجراءُ انتخاب رئاسي، واستولى على السلطةِ قائِدُ الجيش والقوَّات المسلحة محمد سياد بري الذي حلَّ المجلِسَ الوطني، وألغى الأحزابَ السياسيَّةَ، وشكَّل حُكومةً جديدة من قِبَل المجلِسِ الثوري الأعلى الذي يرأس"},{"id":5356,"era":"c14","t":"وفاة الشيخ محمد بن إبراهيم آل الشيخ مفتي الديار السعودية .","s":"هو الشَّيخُ العلَّامة محمد بن إبراهيم بن عبد اللطيف بن عبد الرحمن بن حسن بن محمد بن عبد الوهاب التميمي مفتي الديار السعودية. وُلِدَ يوم عاشوراء من عام 1311هـ، ونشأ نشأةً عِلميَّةً في بيتِ عِلمٍ ودين، فحَفِظَ القرآنَ مبكرًا، ثم بدأ الطلَبَ على العلماء قبل أن يبلُغَ السادسة عشرة، ثم أصيب بمرَضٍ في عينيه وهو في هذه السن ولازمه حتى فَقَد بصَرَه وهو في سن السابعة عشرة، وكان يَعرِفُ القراءة والكتابة قبل"},{"id":5357,"era":"c14","t":"اقتسام المنطقة المحايدة بين السعودية والكويت .","s":"اقتَسَمت السعوديةُ والكويت إدارةَ المنطقة المحايِدة الواقعة في الحدودِ بين الكويت والسعودية، وبدأت مفاوضاتُ التقسيم بعد وقتٍ قصير من لقاءِ حُكَّام الكويت والسعودية في تشرين الأول عام 1960م، وتم الاتفاقُ على وجوب تقسيمِ المنطقة المحايِدة (المجاورة) أراضي كلٍّ منها، مع المحافظة على اتفاقية سابقةٍ تقضي بتقاسُمِ الموارد النِّفطية بينهما مناصَفةً، وتمَّ التوقيعُ على اتفاق ترسيم تقسيم المنطقة المحايدة ف"},{"id":5358,"era":"c14","t":"مذابح المسلمين الكبرى في الفلبين .","s":"نُفِّذت مَذابحُ مُروِّعةٌ ضِدَّ مُسلِمي الفلبينِ على يَدِ حُكومة الدِّكتاتور فرديناند ماركوس، الذي حكَم الفلبينَ من 1965 إلى 1986م بالحديدِ والنارِ؛ حيث ارتكَبَت قُوَّاته أفظَعَ الجرائمِ في حقِّ المسلمين؛ مِن قتْلٍ جَماعيٍّ، وإحراقِ الأحياءِ، وانتهاكِ الأعراضِ والحُرماتِ، وَفَقْءِ أعيُنِ الرجالِ، وبقْر بُطون الأطفالِ، وذبْحٍ بالخناجرِ، وفصْلٍ للرُّؤوس عن الأجسادِ! وما بين عامي 1392- 1404هـ قُتِل أ"},{"id":5359,"era":"c14","t":"النزاع السعودي الإيراني في الخليج العربي .","s":"ظلَّت السُّعودية تَنظُر بكثيرٍ من الحذَرِ لخُطَط ونشاطاتِ طهرانَ في المنطقةِ، ولكنها لم تَصِلْ إلى حدِّ النِّزاع أو الاشتباكِ. وفي كانون الثاني (يناير) 1968 قرَّرت حُكومةُ حِزب العُمال البريطانيةُ إبطالَ مَفعولِ المعاهداتِ المعقودةِ حولَ مَحْميات البحرينِ، وقَطَر، وإماراتِ ساحلِ الصلحِ السَّبعة (أبو ظَبي، وعجْمان، ودُبي، والفُجيرة، ورأْس الخيمة، والشارِقة، وأم القيوين)، وسحْبَ جُزءٍ كبير مِن قُوات"},{"id":5360,"era":"c14","t":"معركة جزيرة أبا في السودان بين جماعة الأنصار وحكومة النميري .","s":"بدَأَت الصِّداماتُ في السُّودان بين حُكومة النميريِّ الاشتراكيةِ وأنصارها مِن جِهةٍ، وبين حَرَكة المقاوَمة الشَّعبيةِ مِن جِهةٍ أخرى، وكان أوَّل الصِّداماتِ دُخول قُوَّات الأمْن إلى مَسجدِ عبدِ الرحمن المهدي الذي يَتجمَّع فيه الأنصارُ عادةً، فقُتِل ثلاثونَ رجلًا مِن الأمن في حِين قُتِل ألْفُ رجلٍ مِن الأنصارِ جَماعةِ المهديِّ، ثم رفَض الهادي زِيارةَ النميريِّ لجِزيرة \"أبا\" الواقعةِ في النِّيل الأب"},{"id":5361,"era":"c14","t":"مبادرة روجرز أول مبادرة سلام في الصراع العربي الإسرائيلي .","s":"عرَض وزيرُ الخارجية الأمريكيةِ وليام رُوجرز مشروعَه في 9 ديسمبر، وتألَّفَ مشروعُ رُوجرز في دِيباجة مُوجَزة تدْعو إلى عقْدٍ اتفاقٍ نهائيٍّ ملزِمٍ بصورةٍ مُتبادلة بين مصرَ وإسرائيلَ، يَجري التفاوضُ بشَأْنه تحت رِعاية السَّفير السويديِّ \"غونار يارنغ\" الممثِّل الشَّخصي للأمين العامِّ للأُمَم المتحِدة، ويَستنِد هذا الاتِّفاق إلى نِّقاط عشْر، أهمها أن تقومُ مصرُ وإسرائيلُ بتَحديد الجدْول الزَّمني والإجر"},{"id":5362,"era":"c14","t":"استقلال عُمان وانقلاب السلطان قابوس على أبيه .","s":"كانت سَلْطنة عُمانَ من بيْن أوائل الدُّول التي نالَت استقلالَها في المنطقةِ. بعدَ أنْ أنهى السُّلطان قابوس دِراساتِه العسكريةَ في لَنْدن وقِيامِه بجولةٍ حولَ العالم، تمَّ استدعاؤه إلى الوطَنِ، ووُضِعَ قابوس في عُزْلة في قصْر صلالةَ؛ بسَبب تَعارُض أفكارِه التقدُّميةِ العالمية مع مُيول والِدِه في الإبقاءِ على محافظةِ وانعزاليةِ عُمان. وبدَعْمٍ مِن البريطانيين والصَّفوة السياسية في عُمان استولَى السّ"},{"id":5363,"era":"c14","t":"توقف العمليات العسكرية في اليمن الشمالي .","s":"توقَّفت العملياتُ الحربيةُ في شَمال اليمنِ ونصَّت اتِّفاقيةٌ وقَّعتها السُّعوديةُ والجُمهورية العربيَّة اليمنيةُ في هذا الشَّهر على تخلِّي الحكومةِ اليمنيةِ عن العديدِ مِن مُنجَزات الثَّورة. وبدَأ تَطهيرُ الجيش وهَيئات أمْن الدولة في اليمنِ مِن العناصر اليَساريةِ، وعاد مِن السُّعودية الكثيرُ من الملكِيينَ الذين تَبوَّأَ عددٌ منهم مناصبَ في هَيئات السُّلطة العليا، ثم اعترَفَت السُّعودية رسميًّا بال"},{"id":5364,"era":"c14","t":"إعلان الملك حسين الأحكام العرفية في الأردن .","s":"أعلَن الملِكُ حُسين بن طلالٍ الأحكامَ العُرْفية في الأردنِّ، وتَنصيبَ حُكومة عسكريةٍ بَدلًا مِن مَدَنية في عَمان، فعيَّن مُستشارَه العسكريَّ حابس المجالي حاكمًا عسكريًّا عامًّا للأردنِّ، وشكَّل وزارةً جديدة برئاسةِ الزعيمِ داود خلَفًا لوزارةِ عبد المنعم الرفاعي المستقيلةِ، وعيَّن حُكامًا عسْكريين في كلِّ مُحافظات الأردنِّ، وكان هذا قبل هُجوم الجيش الأردني على المنظَّمات الفِلَسطينية في الأردن في 1"},{"id":5365,"era":"c14","t":"أيلول الأسود (الصدام الفلسطيني الأردني) .","s":"\"أيلول الأسودُ\" هو الاسمُ الذي يُشار به إلى شَهر أيلولَ من هذا العامِ؛ ففي هذا الشَّهر تحرَّك حُسين بن طلال ملِكُ الأردنِّ لإجهاضِ مُحاولةٍ لمنظَّمات فِلَسطينية لإسقاطِ نِظامِ حُكمِه الملكيِّ؛ حيث استمرَّ القتالُ المسلَّح حتى يُوليو عام 1971م؛ حيث كان الفِلَسطينيون يُشكِّلون نِسبةً عالية من تَعدادِ سُكان الأردنِّ في تلك الفترة، وكانوا مَدْعومين من قِبَل أنظمةٍ عربية مُختلِفة، خاصَّةً من الرئيس الم"},{"id":5366,"era":"c14","t":"مؤتمر القمة العربية غير العادي الأول بسبب أحداث أيلول الأسود .","s":"عُقِدت هذه القِمة (غير العادية وغير الرَّسمية) في القاهرة على إثرِ الاشتباكاتِ العنيفةِ في الأردنِّ بين الأرُدنيين والفِلَسطينيين، ولم تَعقِدْ هذه القِمةُ جلساتٍ عامةً، وتحوَّلت إلى مُشاوَرات بين رُؤساء الدُّول؛ ولهذا فإنَّ الجامعة العربيَّة لم تُدرِجْها في سِجِلاتها الرسمية للقِمَمِ العربيَّة، وانتهَت هذه القِمة -التي قاطعَتْها كلٌّ من سُوريا والعراقِ، والجزائر والمغربِ- بمُصالحةٍ بين منظَّمة الت"},{"id":5367,"era":"c14","t":"وفاة جمال عبد الناصر حاكم مصر ونهاية الحكم الناصري  .","s":"هو جَمال عبد الناصرِ بن حُسين بن خَليل بن سُلْطان عبْد الناصر، رئيسُ الجُمهورية العربيَّة المتحِدة، وقائدُ ثَورة يُوليو 52 العسكرية (ثَورة الضُّباط الأحرار). وُلِدَ في قَرية بني مُر بمحافظةِ أسيوطَ سنة 1336هـ / 1918م، وانتقَلَ إلى القاهرةِ وعُمره ثمانِ سنواتٍ، فعاش مع عمٍّ له اسمه خَليل. وتعلَّم بها ثم بالإسكندريةِ، وحصَل على البكالوريوسِ سنةَ 1936، وشارَك في المظاهَرات المعاديةِ للإنجليزِ، وجُرِح"},{"id":5368,"era":"c14","t":"الحرب الهندية الباكستانية الثالثة .","s":"أعدَّت الهِند عُدَّتها لفصْل شَطْري باكستانَ عن بعضِهما، وعقَدَت حِلفًا عسكريًّا مع رُوسيا لردْعِ أيِّ مُحاولةِ تهديدٍ تأتي من الصِّين، وقد كانت القواتُ الهِندية تَفوق القواتِ الباكستانيةَ في الجبهةِ الشرقيةِ بما يُعادِل ستة أضعافها، ومُجهَّزة بكلِّ الوسائل الحديثةِ في القتالِ، تَدعُمها رُوسيا، بينما إمكانياتُ الباكستانيينَ في الشرْق ضَعيفةٌ، واندلَع القِتالُ على كافَّة الجبهاتِ الشرقيةِ والغربيةِ"},{"id":5369,"era":"c14","t":"افتتاح السد العالي بمصر أكبر مشروع كهرومائي في الشرق الأوسط .","s":"بدَأ العملُ في بِناء السَّدِّ العالي في 10 / 7 / 1379هـ / 9 يناير1960م، وتَمَّ الانتهاءُ مِن تنفيذ المرحلةِ الأولى في 16 مايو 1964م، وانتهى تَنفيذ المرحلةِ الثانية في 15 يناير 1971م، والسَّدُّ العالي: هو سَدٌّ مائيٌّ على نَهر النِّيل في جَنوب مصرَ، أُنشِئَ في عهد جمالِ عبد الناصرِ، وشارك السُّوفيتُ في بِنائه. وقد ساعَد كثيرًا في التحكُّم في تدفُّقِ المياهِ، والتخفيفِ مِن آثار فَيضانِ النِّيل. ويُس"},{"id":5370,"era":"c14","t":"الانقلاب العسكري الثاني في تركيا ضد سليمان ديميريل (انقلاب المذكرة) .","s":"أثار الرُّكود الاقتصاديُّ موجةً من الاضطراباتِ الاجتماعية التي تمثَّلت في المظاهراتِ التي تجوبُ الشوارعَ، وإضراباتِ العُمَّال، والاغتيالاتِ السِّياسية، كما تمَّ تَشكيلُ حركاتٍ عُمَّالية وطُلابية يساريةٍ تُعارِضُها الجماعاتُ اليَمِينية القوميةُ المسلَّحة والإسلاميَّة، وبحُلولِ يناير 1971 عَمَّت الفوضى أرجاءَ تركيا، وتوقَّفت الجامعاتُ عن العملِ، وأضربت المصانع، وقام الطُّلاب بسَرِقة البنوكِ، وخطْف ا"},{"id":5371,"era":"c14","t":"عودة العلاقة الدبلوماسية بين السعودية والجمهورية اليمنية .","s":"عادَت العَلاقات الدُّبلوماسيةُ بين السُّعودية والجُمهورية اليمنيةِ، وقام رَئيس وُزراء الجُمهورية العربيَّة اليَمَنيةِ عبد الله الحجريُّ بزِيارة الرياضِ. ونصَّ بلاغٌ سُعودي يَمَنيٌّ مشترَك على أنَّ الحُدودَ بين البلدينِ ثابتةٌ ونهائيةٌ، كما نصَّت عليها معاهدةُ الطائفِ عام 1353هـ / 1934م. وأدَّى تقارُب صَنعاءَ مع الرِّياضِ إلى تَحسين عَلاقات اليمنِ الشماليِّ بالولايات المتحِدةِ وبريطانيا وألمانيا ال"},{"id":5372,"era":"c14","t":"قيام الجمهورية العربية المتحدة بين (مصر وسوريا وليبيا) .","s":"عمِلَت الثورة اللِّيبيةُ على إقامة اتِّحاد الجُمهوريات العربيَّة المتحِدة الذي تألَّف مِن مصرَ وسُوريا ولِيبيا، وكانت طرابلسُ مَقرَّ المباحثاتِ التي دارت لإقامةِ هذا الاتِّحاد، ووُقِّع الميثاقُ في بَنغازي ووُقِّع بعدها الاتِّفاقُ على الوَحدةِ الاندماجيةِ مع مصرَ، وتمَّ حلُّ هذا الاتِّحادِ في آذار 1977 مع بِداية المفاوَضات بين الساداتِ وإسرائيلَ، وقد عانى الاتِّحاد مُنذ خُطواته الأولى من الكثيرِ من"},{"id":5373,"era":"c14","t":"محاولة الشيوعيين الانقلاب على حكومة النميري .","s":"انقسَمَ الشُّيوعيون في السودانِ إلى قِسمينِ: قسمٌ يَرى تطبيقَ الشُّيوعيةِ وإعلانَ الحُكْمِ الشُّيوعي، وقسمٌ يَرى الإفادة مِن الحُكْم القائمِ إلى أنْ يَتهيَّأ الجوُّ المناسِبُ؛ إذ لا يمكِنُ حمْل الناس على الشُّيوعية وغالبُهم يَرفُضها، واستطاع أصحابُ هذا الرأيِ إبعادَ الرأي الآخَرِ عن مجلس قِيادةِ الثَّورة، وابتدَأ جَعفرٌ النميري يُهاجِم الحزْب الشُّيوعي الجِناح المعارِضَ الذي أبعَدَ بعضَ أعضائه، وك"},{"id":5374,"era":"c14","t":"استقلال البحرين  .","s":"فرضت بريطانيا حمايتها على البحرين منذ سنةَ 1820م، فكانت البحرين تقَعُ تحتَ الاستعمارِ البريطانيِّ، وكانت قِيادة الشؤون الخارجيةِ بيَدِ البريطانيينَ، حتى أضْحَت البحرينُ القاعدةَ البريطانية الأساسيةَ في الخليجِ العربي، وانتقَلَ المقرُّ السِّياسي البريطاني مِن \"بوشهر\" إليها، ثم إنَّ الشَّعب البحرينيَّ بدَأ يتحرَّك لِنَيل بعضِ الحقوقِ، ومنها إصدارُ العُمْلة الخاصَّة به، وكانت لإيرانَ أطماعٌ في البحري"},{"id":5375,"era":"c14","t":"استقلال قطر .","s":"كانت قَطَر قد تخلَّى عنها العُثمانيون بعدَ أن وقَّع الشيخ جاسمٌ اتفاقيةً معهم، ثم في سنةِ 1916م عقَد البِريطانيون معاهدةَ حِمايةٍ، فأضْحَت تابعةً للضابط البِريطاني في البحرينِ، وبقِيَت كذلك إلى أنِ استقلَّت 12 رجَب 1391هـ / 3 أيلول (سبتمبر)، ونشَرَت دُستورًا لها فورَ استقلالِها، ودخَلت الجامعة العربيَّة، والأُمَم المتحِدةَ، ومنظَّمةَ \"الأوبك\"."},{"id":5376,"era":"c14","t":"انقسام باكستان الشرقية وقيام دولة بنغلادش فيها .","s":"بدَأت المطالَبةُ في باكستانَ بتَقسيم باكستانَ الشرقيةِ (بنغلادش حاليًّا) عن باكستانَ الغربيةِ (باكستان الحالية)، وكان شَيخ مُجيب الرحمن (مُيوله اشتراكيةٌ) في باكستانَ الشرقيةِ هو الداعيَ إلى هذا الانفصالِ، وكان مِن المؤيِّدين أيضًا لهذا الانفصالِ ذو الفقار علي بوتو الشِّيعي، وأيَّد الأمريكانُ هذا التَّيار بمِثل ما أيَّدوا به مُجيب الرحمن، إضافةً إلى أنَّ الرئيسَ يحيى خان الشِّيعي أوعَز للشِّيعة بت"},{"id":5377,"era":"c14","t":"استقلال إمارات مشيخة الخليج العربية (دولة الإمارات العربية المتحدة)  .","s":"كان البريطانيُّون يُعانون مِن \"القواسمِ\" في إمارة الشارقةِ، الذين تأثَّروا بدَعوة الشيخ محمَّد بن عبد الوهَّابِ، وأخَذوا يعمَلون على نشْرِها في سواحل الإماراتِ، وفرْضِ سِيادتِهم على تلك السواحلِ، ولكن الإنجليزَ -وبمُساعدةٍ مِن سُلْطان مسْقطَ- استطاعوا القضاءَ على حَركة القواسمِ وتَدمير أساطيلِهم، وإخضاعِ السواحلِ التابعة لتلك المناطقِ لِلْحمايةِ البريطانية، حتى أقامت قاعدةً عَسكريةً واسعةً في مَشي"},{"id":5378,"era":"c14","t":"احتلال إيران الجزر الإماراتية (أبو موسى وطمب الصغرى والكبرى) .","s":"في تِشرين الثاني (نوفمبر) 1971 عُقِدت اتِّفاقيةٌ بين إيرانَ وإمارةِ الشارقة، ملَكَت إيرانُ بمُوجِبها عمليًّا جزيرةَ \"أبو موسى\" التي ظلَّت من الناحية الشَّكلية جُزءًا من إمارة الشارقةِ، وحصَلت إيرانُ على حقِّ إقامة قاعدةٍ عسكرية في الجزيرةِ، على أنْ تَدفَع مُقابِلَ ذلك لشيخ الشارقةِ 1.5 مليون جنيه إسترليني سَنويًّا، ويَستمرُّ الدفْع لحين بُلوغ دخْلِ الشيخ من النِّفط 3 ملايين جنيه إسترليني سنويًّا، "},{"id":5379,"era":"c14","t":"انقلاب عيدي أمين على رئيس أوغندا ميلتون أوبوتي .","s":"ظهَرت شخصيةُ عيدي أمين كقائدٍ للجيش سنة 1384هـ، وهو ضابطٌ مسلِم تدرَّب في إسرائيلَ، وهو ذو طبيعةٍ استبدادية، تأثَّر بشَخصيَّة عبد الناصر، فقام بانقلابٍ ضدَّ ميلتون أوبوتي، وتسلَّم على إثْره الحكْمَ، وفَرَّ أبوتي إلى تَنزانيا التي رفضَت الاعترافَ بحُكْم عيدي أمين، قام عيدي أمين بعدَّةِ إجراءاتٍ، كان من شأْنِها إثارةُ القوى الصَّليبية والصُّهيونية ضِدَّه؛ فقد قام بطَرْد البَعثة الإسرائيلية مِن أوغند"},{"id":5380,"era":"c14","t":"تنحي يحيى خان عن رئاسة باكستان وتولي ذي الفقار علي بوتو .","s":"بعدَ أنِ انتهَت الحربُ الباكستانية الهِنْدية الثالثة التي لم تَستمِرَّ إلا أسبوعينِ، وانتهَت بهزيمة الجيشِ الباكستاني هَزيمة مُنكَرةً، أُسِر فيها 93 ألفَ جُنديٍّ باكستاني. كما أدَّت إلى انفصال القِسم الشرقيِّ من باكستانَ وقِيام دولة بنغلاديش، فخرَجَت مُظاهراتٌ في باكستانَ تطالِبُ باستمرار الحرْب، وتقديمِ الرئيسِ يحيى خان للمُحاكَمة بسبب تَقصيرِه، فاسْتَدعى الرئيسُ يحيى خان من نيويورك ذا الفقار علي"},{"id":5381,"era":"c14","t":"منح الدول المصدرة للنفط حق تحديد أسعار النفط  .","s":"وُقِّعت في 14 شباط (فبراير) في طَهرانَ اتِّفاقيةٌ بين البلدان الخليجيةِ الأعضاءِ في \"أوبك\" وشَركات النِّفط، منَحَت عَمَليًّا البلدانَ المصَدِّرة للنِّفط حقَّ الإشراف على الأسعار القياسيةِ، وبهذا يكون أعضاءُ \"أوبك\" قد حقَّقوا الأهدافَ المطروحةَ عام 1960. ولكن ظلَّت مُعلَّقةً مسألةُ مساهمةِ حُكومات البلدان المصدِّرة للنِّفط في ممْتلكات ونشاط الشَّركات، وفي 21 كانون الثاني (يناير) 1972 بدَأت مُفاوضات"},{"id":5382,"era":"c14","t":"وفاة أديب الحجاز محمد بن سرور الصبان .","s":"وُلِد محمَّدُ بنُ سُرورٍ الصَّبَّانُ عامَ 1316هـ الموافِق 1898م في مدينةِ القُنْفُذةِ بالمَمْلَكةِ العَرَبيَّةِ السُّعوديَّةِ أيَّامَ حُكمِ الأشرافِ، ثمَّ انتَقَل والِدُه بأُسْرَتِه إلى جُدَّةَ عامَ 1320هـ، ثمَّ اتَّجَهوا إلى مَكَّةَ المُكَرَّمةِ واستقَرُّوا بها. وكان زَعيمَ الحرَكةِ الأدَبيَّةِ في الجَزيرةِ العَرَبيَّةِ، ورائِدَ الأُدَباءِ والمثَقَّفينَ في مكَّةَ المُكَرَّمةِ، أَسَّس أوَّلَ مَكتب"},{"id":5383,"era":"c14","t":"اتفاقية سيملا بين باكستان والهند .","s":"بعدَ أنْ وضَعَت الحربُ الثالثةُ أوزارها بين الدولتينِ: الهند وباكِستان، وفي 17 جُمادى الأولى / 28 حُزيران، بدَأت محادثاتُ القِمة بين الرئيسِ الباكستاني ذي الفقار علي بوتو، ورئيسةِ وُزراء الهندِ أنديرا غاندي في مدينة سيملا الهِنديةِ، وذلك في مُحاولةٍ للتوصُّل إلى تَسوية المشكِلات المعلَّقة والناجمةِ عن حَرْب شوَّال 1391هـ / ديسمبر 1971م، وعن تَقسيمِ باكستانَ، وانفصال الجَناح الشَّرقي، وقِيام دَولة "},{"id":5384,"era":"c14","t":"محاولة اغتيال الملك الحسن الثاني ملك المغرب .","s":"في سنةِ 1391هـ وقعَت مُحاولةٌ لاغتيالِ الملِك الحسن الثاني في القصْر، وهو في حَفلة عِيد ميلادِه الـ(42)، ولكنها فشَلت، وفي 7 رجب / 16 آب من هذا العامِ عندما كان الملك عائدًا من فرنسا على متْن طائرةٍ، وقعَت مُحاولةٌ ثانية لاغتيالِه بتَدْبيرٍ من اللِّواء محمَّد أوفقير؛ حيث انطلَقَت 6 طائراتٍ هُجومية مِن قاعدة القُنَيطرة المغربيةِ، وبدَأت بضَرْبِ طائرة الملِك، ونَفِدت ذَخائرُ طائرتينِ، وأما طائرةُ قا"},{"id":5385,"era":"c14","t":"الرئيس الصومالي محمد سياد بري يعلن تطبيق الاشتراكية في الصومال .","s":"لمَّا تولَّى محمَّد سياد بري رئاسةَ الصُّومال عام 1390هـ بعد انقلابٍ عَسْكري، أعلَن أنَّ الصُّومال دَولةَ اشتراكيةٌ، وفي هذا العامِ قام بري بتَنْفيذ حملةِ قتل، فتوجَّه نحوَ العُلَماء والتنظيماتِ الإسلاميَّة، وقد أذاع الرئيسُ محمَّد سياد بري بَدْء تَطبيق الاشتراكيةِ في الصُّومال، والتي أسَّسها كارل ماركِس، وطبَّقها لينين، وفي رَمضان / تشرين الأول، وفي يومِ الذِّكرى الثالثة للثَّورة؛ أعلَن بري إلغاء"},{"id":5386,"era":"c14","t":"محاولة انقلاب ضد السلطان قابوس .","s":"بعدَ الهزائم التي مُنِيت بها \"الجبْهة الشَّعبية\" في ثَورة ظَفار، توجَّهت إلى التخطيطِ للقيامِ بانقلابٍ ضدَّ السُّلطان قابوس ونِظام حُكْمِه في السَّلْطنة، وقد تمَّ التخطيطُ للانقلابِ في العراقِ في أكتوبر 1972م عن طَريق بعض العناصرِ التي أوفَدَتْها الجبهةُ إلى هناك، بالإضافة إلى بَعض أعضاءِ المكتبِ السِّياسي في اليَمَنِ الجنوبيِّ، وقد تمَّ تحديدُ موعدِ الانقلابِ في 31 ديسمبر 1972م. غيرَ أنَّ هذه الم"},{"id":5387,"era":"c14","t":"ليبيا تحتل شريط أوزو في تشاد .","s":"قامت لِيبيا باحتلالِ شَريط أوزو في شمالي تشادَ، وادَّعت لِيبيا أنها لم تَقُمْ بذلك إلا بناءً على الاتفاقية التي جَرَت بين فرنسا وإيطاليا عام 1362هـ / 1943م، واستقرَّت قوةٌ لِيبية في تشادَ، قوامُها خمسةَ عشَرَ ألفَ جُنديٍّ، ثم قدَّمت اقتراحاتٍ لقيامِ وَحدةٍ بين لِيبيا وتشادَ، لكنها لم تَنجَح؛  فسحَبَت ليبيا قُواتها في مَطلع عام 1402هـ، ووُضِعَت محلَّها قواتُ حِفظ السلامِ الدوليةِ."},{"id":5388,"era":"c14","t":"فخري ثابت كورتورك رئيسًا لتركيا بعد جودت صوناي .","s":"انتهَت مُدَّة الرئيسِ جودت صوناي في الحكْم، وحدَثَت أزمةٌ في انتخابِ رئيس جديدٍ؛ إذ رشَّح الجيشُ فخري ثابت تورتورك رئيس الأركانِ التُّركي، فاستقال مِن منْصبِه ليَدخُل في مجلِس الشيوخ؛ لأنَّ الرئيسَ يجِب أنْ يكون عضوًا في هذا المجلسِ، ورشَّح حِزْب العدالةِ (المؤسَّس أصْلًا على أنقاض الحِزْب الديمقراطي) تاكين أريبون، وخُشِي مِن وُقوع صِدامٍ مع العسكريين؛ لذا بحَثَ الساسةُ إمكانيةَ تَمديد فترة الرئاس"},{"id":5389,"era":"c14","t":"محمد داود يترأس أفغانستان بعد انقلاب عسكري ضد الشاه محمد .","s":"كان محمَّد داود (وهو ابنُ عمِّ الشاه محمَّد ظاهر، وزَوج شقيقتِه) قد أصبَح رئيسًا للوزراءِ في أفغانستانَ، إضافةً إلى احتفاظِه بوزارتيِ الدَّاخلية والدِّفاع، وكان يَمِيل إلى الرُّوس؛ حيث تعامَل معهم وعقَد معهم معاهداتٍ مِن تسليحٍ وغيرِه، ولمَّا عرَف الشاهُ مُيولَه وأطماعَه نحَّاه عن منْصبِه، وهذا ما ولَّد النِّقمةَ عنده، ثم إنَّ الرُّوس وأعوانَهم لمَّا رأَوُا ازديادَ النَّشاط الإسلاميِّ ونُموَّه بشك"},{"id":5390,"era":"c14","t":"وفاة الطاهر بن عاشور .","s":"هو الشيخُ محمَّد الطاهر بنُ محمَّد بنِ محمَّد الطاهر بن عاشورٍ، الشَّهير بالطاهرِ بنِ عاشورٍ، أحدُ الأعلامِ المشهورين والمفسِّرين المعروفين، وكان أديبًا خطيبًا، ومِن طلائع النَّهضة الحديثةِ النابهينَ في تُونس. كانت حياتُه -التي زادت على 90 عامًا- جهادًا في طلَبِ العِلم، أحدَثَت آراؤه نَهضةً في عُلوم الشريعة والتفسيرِ، والتربيةِ والتعليمِ، والإصلاح. وُلِدَ بتُونسَ سنةَ 1296هـ في أُسرةٍ عِلْمية عريق"},{"id":5391,"era":"c14","t":"الحرب العربية الإسرائيلية الرابعة (أكتوبر 1973م) .","s":"بعْدَ نَكبة 1948م، والعُدوان الثُّلاثي في 1956م، ونَكسة حُزَيران في 1967م؛ وفي 6 أكتوبر من عام من عام 1973، 10 رمضان 1393هـ اجتازتِ القواتُ المصريةُ قَناة السويسِ، وانتقَلت إلى الضفةِ الشرقيةِ واقتَحَمت خطَّ بارليف الذي أقامه اليهودُ على حُدود شِبه جزيرة سَيناء الغربية، والذي حصَّنوه جيدًا، ووَضَعوا أمامه تلًّا تُرابيًّا؛ لِيَحميَ تَحرُّكَهم عن أعيُنِ المصريين، ولكن لم يُتابِع الجيشُ المصري تقدُّم"},{"id":5392,"era":"c14","t":"سلاح النفط والضغط على الولايات المتحدة في حرب 6 أكتوبر .","s":"دعَت السُّعودية واشنطن إلى الضَّغط على إسرائيلَ وحمْلِها على تنْفيذ قرارِ مجلِس الأمْن رقم (242) الصادرِ في 22 تشرين الثاني (نوفمبر) عام 1967، الذي يَقضي بالانسحابِ من جميع الأراضي العربيَّة المحتلَّة في حُزيران (يونيو) 1967، وإلَّا فإنَّ الولاياتِ المتحِدةَ سوف تُواجِه عقَبات تَقليص تَصديرِ النِّفط. لم تأخُذْ الولاياتُ المتحِدةُ وأوربَّا الغربية هذه التَّحذيراتِ على مَحملِ الجِدِّ، فألْمحتِ السُّ"},{"id":5393,"era":"c14","t":"وفاة الدكتور طه حسين .","s":"هو الدُّكتور طه بن حسين بنِ عليِّ بن سلامةَ. وُلِد سنةَ 1889م في قرية (الكيلو) بمَغاغةَ مِن مُحافَظة المِنْيا (بالصعيد المصْري)، وأُصِيب بالجُدريِّ في الثالثة مِن عُمرِه، فكُفَّ بصَرُه. وكان السابعَ من إخوته وأخواتِه الذين بلَغَ عَددُهم (13)، وكان والدُه ذا مركزٍ مَرموقٍ في الضاحيةِ، حرَصَ على تَعليمِ أولادِه؛ وحرَص أنْ يُعلِّم ابنَه طه، فأدْخَله الكُتَّاب، وحفِظ فيه القرآنَ الكريمَ، وحفِظَ الكثير"},{"id":5394,"era":"c14","t":"دعم إيران لسلطان عُمان لمواجهة حركة التحرير في ظفار .","s":"قام السُّلطان قابوس في شَهر أكتوبر عامَ 1971م بزيارةٍ رسميةٍ إلى إيرانَ؛ للمُشارَكة في الاحتفالات التي أقامها الشاهُ محمَّد رضا بَهلوي بمُناسبة عرْشِ الطاوسِ في بلادِ فارسَ، فطلَب السُّلطان قابوس مِن شاه إيرانَ مُساعدتَه في مُواجهة ثوارِ ظَفار، فأبدى الشاهُ استِعدادَه والوقوفِ إلى جانبِ قوَّات السُّلطان في حَرْبها ضِدَّ الثُّوار، وكان مِن أهمِّ الدوافعِ التي دفَعَت الشاهَ الإيرانيَّ للدعْمِ هو طُم"},{"id":5395,"era":"c14","t":"وفاة ديفيد بن غوريون أول رئيس وزراء للاحتلال الصهيوني .","s":"وُلِد في مَدينة \"بلونسك\" البُولنديَّة، ولِتَحمُّسِه للصُّهيونيةِ هاجَر إلى فِلَسطين في 1906. امتهَنَ ابن غُوريون الصحافةَ في بِداية حياته العَمَلية، وبدَأ باستعمالِ الاسمِ اليهودي \"ابن غُوريون\" عندما مارَس حياتَه السِّياسيةَ. وهو أوَّلُ مَن تقلَّد مَنصِب رئيس وُزراءٍ لإسرائيلَ مِن سنةِ 1948م حتى سنة 1953م، وتقلَّد المنصبَ مدَّةً أُخرى بدَأت في 1955م، وانتهَت في 1963م، وعندما تولَّى منْصبَ رئيسَ ال"},{"id":5396,"era":"c14","t":"مؤتمر القمة العربية السادس (قمة الجزائر) .","s":"ما إنْ أُعلِنَ وقفُ إطلاق النارِ في حرْب 6 أكتوبر / تشْرين الأول بقَرارِ رقم 338 مِن الأُمَم المتحِدة في 22 أكتوبر، حتى تمَّ عقْدُ قِمَّة عربيةٍ في الجزائرِ من 26 - 28 تشْرين الثاني، وحضَرَتْه 16 دولةً عربية بمُبادرةٍ من سُوريا ومصرَ، وقاطعَتْه العراقُ ولِيبيا، وكانت القضيةُ الرئيسةُ التي تمَّ طرْحُها في القمةِ هي: \"الصُّلح مع إسرائيلَ\" بشروط؛ حيث صَدَر عن المؤتمر بَيانٌ خِتاميٌّ ومجموعةٌ من القرا"},{"id":5397,"era":"c14","t":"شيخ مجيب الرحمن يتولى رئاسة بنغلاديش .","s":"كان شيخُ مُجيب الرحمن قد قام مع حِزْبه بالتأليبِ للانفصالِ عن باكستانَ وقِيام دولةٍ مُستقِلة، وهذا ما تمَّ بالفِعل عامَ 1391هـ، وكان قد اعتُقِل مُجيب ثم أُطلِقَ سراحُه، وعاد إلى دكا عاصمةِ بنغَلاديشَ، ثم في 22 ذي الحجةِ 1393هـ / 15 كانون الثاني 1974م انتُخِب مُجيب الرحمنِ رئيسًا لِلجُمهورية، أو نصَّب نفْسَه، ويُعَدُّ الثالثَ مِن رُؤساء دَولةِ بنْغلاديش بعد نصْرِ الإسلامِ وأبي سَعيد شودري اللذينِ ك"},{"id":5398,"era":"c14","t":"وفاة الشيخ العلامة محمد الأمين الشنقيطي صاحب تفسير (أضواء البيان) .","s":"هو الشَّيخ العلَّامةُ محمَّدُ الأمين بنُ محمَّد المختارِ بنِ عبد القادر الشِّنقيطي الجَكَني الحِمْيري، وُلِدَ سنةَ 1325هـ في شِنْقيط في كيفا شرق موريتانيا، ونشَأَ يتيمًا في بيوت أخوالِه، وحفِظ القرآنَ وهو ابنُ عشْرِ سِنينَ، وتعلَّم رسْمَ المصحفِ على يَدِ ابن خالِه، وأخَذ الأدَب وعُلوم اللُّغة على يَدِ زوجةِ خالِه، فكانت مَدرستُه الأولى بَيتَ خالتِه، تعلَّم الفِقْه المالكيَّ، وهو السائدُ في بِلاده،"},{"id":5399,"era":"c14","t":"الوحدة بين ليبيا وتونس .","s":"جرَت اتِّصالاتٌ سَريعةٌ بين الحكومتينِ اللِّيبيةِ والتُّونسية في 18 ذي الحجةِ / 12 يناير؛ حيث وقَّع الزعيمُ التُّونسي الحبيب بُوْرقيبة والعقيدُ اللِّيبي معمَّر القذَّافي على \"بيان جربة\"؛ لتَوحيدِ البلدينِ تحت رايةِ جُمْهورية واحدةٍ تُسمَّى بـ\"الجُمهورية العربيَّة الإسلاميَّة\" تكونُ وَفْقَ سُلْطةٍ تَنفيذيَّة وتشْريعية وقَضائيةٍ ودُسْتورية واحدةٍ، على أنْ يكون بُورقيبة رئيسًا لها، والقذَّافي نائبًا "},{"id":5400,"era":"c14","t":"حركة التمرد البولشستانية في باكستان للانفصال بدولة مستقلة .","s":"قامت في باكستانَ حركةُ تمرُّد في ولاية بالوشستان بزعامة حزب عوامي الوطنيِّ، وتهدُف هذه الحركةُ إلى انفصالِ بالوشستان عن باكستانَ، وتأسيس دولة خاصَّةٍ على أساس القوميَّة البالوشستية، وضمِّ المناطق الأفغانية التي يقيم فيها البالوش إليها، وكان وراء هذه الحركةِ الشيوعيون الذين عملوا في الخفاء لتجزئة الأمصارِ الإسلامية؛ لإضعافِها، وخاصَّة المجاورة لروسيا، ولكن قُضي على هذا التمرُّد ولم يحصل المتمرِّدون"},{"id":5401,"era":"c14","t":"إلغاء حظر النفط عن الولايات المتحدة وتطور العلاقة مع السعودية .","s":"أُلغي حظرُ تصدير النفطِ إلى الولايات المتحدة في 18 آذار (مارس). وقد ساعد إلغاءُ الحظرِ على حدوث بعض الانفراجِ في العلاقات السعودية الأمريكية؛ مما أتاح الفرصةَ للتوصلِ إلى اتفاقية ثُنائيةٍ حولَ التعاون الاقتصاديِّ والفني عقَدها البلَدانِ في 8 حزيران (يونيو) 1974. وبعد مرور فترة قصيرةٍ وُقِّعَت اتفاقيةٌ حول تصديرِ معدَّاتٍ عسكرية أمريكية إلى السعودية، وتدريب الحرس الوطني السعوديِّ على يد مُدرِّبين أ"},{"id":5402,"era":"c14","t":"وفاة الشيخ محمد أحمد أبو زُهرة .","s":"هو الشيخُ العلَّامة محمد بنُ أحمد بنِ مصطفى بنِ أحمد المعروف بأبي زُهرةَ. وُلِدَ بالمحلَّة الكبرى التابعة لمحافظة الغربية بمصر في 6 ذي القعدة 1315هـ/ 29 مارس 1898م، ونشأ في أسرة كريمةٍ عُنِيت بولدها، فدفعت به إلى أحد الكتاتيب التي كانت مُنتشرة في أنحاء مصر تُعلِّم الأطفال وتحفِّظهم القرآن الكريم؛ فحفظ القرآنَ الكريم، وأجاد تعلُّم مبادئ القراءة والكتابةِ، ثم انتقل للتعلُّم بالجامع الأحمديِّ بمدينة "},{"id":5403,"era":"c14","t":"انضمام جمهورية الصومال إلى جامعة الدول العربية .","s":"انضمَّت جمهوريةُ الصومال إلى جامعة الدول العربيةِ، وقد استقلَّت أرض الصومالِ عن الإدارة الإيطاليةِ في 1 يوليو 1960م، وحصلت على عضويَّةِ الأمم المتحدة في 20/ 9 / 1960م."},{"id":5404,"era":"c14","t":"وفاة المصلح المغربي علال الفاسي .","s":"هو محمد علال ابنُ العلَّامة الخطيب عبد الواحد بنِ عبد السلام بنِ علال بنِ عبد الله بنِ المجذوب الفاسي الفِهريُّ نسبًا، ثم الفاسيُّ مولدًا ودارًا ومنشأ. أحد روَّاد الفكر الإسلامي الحديث، ومن كبار الخطباء في المغرب، ينحدِرُ من عائلة عربية عريقة نزحت من موطنها بديار الأندلس إلى المغرب الأقصى فرارًا بدينها وعقيدتها من محاكمِ التفتيشِ الإسبانية، واستوطنت بمدينة فاس تحت اسمِ بني الجدِّ واشتهرت بآل الفاس"},{"id":5405,"era":"c14","t":"وفاة الحاج أمين الحسيني مفتي القدس .","s":"هو الحاجُّ محمد أمين بنُ محمد طاهر بن مصطفى الحُسيني مفتي القدس. وُلد في القدسِ سنة 1897م، تربَّى في بيت والدِه الشيخِ طاهر الحسينيِّ مفتي القدس، عُرِف بالحاج أمين الحسينيِّ بعد أن حجَّ برفقة والدتِه. تلقَّى علومه الابتدائيَّة والثانوية في مدارسِ القدسِ، ثم التحق بكلية الفرير بالقدس لتعلُّم اللغةِ الفرنسية، بعدها التحق بجامعة الأزهر، وكان يتردَّد على (دار الدعوة والإرشاد) التي أنشأها الشيخُ محمد ر"},{"id":5406,"era":"c14","t":"إصدار الحكومة التركية أوامر إلى قواتها العسكرية بالنزول في جزيرة قبرص .","s":"أصدرتِ الحكومةُ التركيةُ أوامرها إلى قوَّاتها العسكريةِ بالنزول في جزيرة قُبرص المتنازَع عليها مع اليونانِ، وقد تمكَّنت القواتُ التركية منَ السيطرة على 35% من مساحة الجزيرةِ، حتى وقف إطلاق النار في 16 أغسطس بعدَ إرسال قواتٍ دوليةٍ إلى الجزيرة."},{"id":5407,"era":"c14","t":"استقلال غينيا بيساو .","s":"غينيا بيساو دولة أفريقية صغيرة ذات أغلبية مسلمة كانت تحتَ الاحتلالِ البرتغالي الذي أذاقها الوَيلاتِ حتى اعترفت عام 1392هـ / 1972م لجنة تصفية الاستعمار التابعة للأمم المتحدة بالحزب الإفريقي المطالب باستقلال غينيا بيساو وجزر الجبل الأخضرِ عنِ السيطرة البرتغالية، وفي 1393هـ / 1973م جرت الانتخاباتُ لتشكيلِ مجلس الشعب الوطني وحصلت غينيا بيساو على الاستقلال الذاتي، وتسلَّم لويس كابرال رئاسةَ مجلس الدولة"},{"id":5408,"era":"c14","t":"حل مشكلة البريمي واعتراف السعودية بدولة الإمارات العربية المتحدة .","s":"في عام 1971م حلَّت السعودية خلافها مع سلطنة عُمان حول واحة البريمي؛ حيثُ قام السلطان قابوس بن سعيد سلطان عمان بزيارة إلى الرياض والتقى مع الملك فيصل في الرياض في تشرين الأول عام 1971م وصدر عن هذه الزيارة بيان مشترك تضمَّن اعتراف السعودية بضم القرى التي سبق أن حصلت عليها سلطنة عمان وفقًا للاتفاق الذي تم بينهما وبين إمارة أبو ظبي برعاية الحكومة البريطانية في ديسمبر 1955م، وهي البريمي وحماسا وصعراء، "},{"id":5409,"era":"c14","t":"المعاهدة العراقية الإيرانية .","s":"كان من مقرَّراتِ اتفاقيةِ الجزائر بين العراقِ وإيران التي كانت عام 1383هـ / 1963م أن يجتمعَ الطرفانِ في طهرانَ في 15 آذار 1975م / 1395هـ وبناءً على ما جاء من إعادة الثقةِ والعمل على حلِّ مسألة الحدودِ فقد قرَّر الطرفانِ عقدَ المعاهدة وعيَّنا مندوبيهما المفوَّضينِ: رئيسَ الوزراء سعدون حمادي، ووزيرَ خارجية العراق، وشاهِنشاه إيران عباس علي خلعتبري، ووزيرَ خارجية إيران، وبعدَ تبادل وثائق التفويض اتفقا"},{"id":5410,"era":"c14","t":"إعلان القبارصة الأتراك إنشاء \"دولة قبرص التركية الفيدرالية\" .","s":"ما إن تمكَّنتِ القواتُ العسكريةُ التركية من احتلال حوالي 35 % من مساحة الجزيرة حتى أعلن القبارصةُ الأتراكُ إنشاءَ \"دولة قبرص التركية الفيدرالية\" كإدارة قبرصية تركية مستقلَّة، وذلك بعد فشل المحادثاتِ بين تركيا واليونان حولَ الجزيرةِ."},{"id":5411,"era":"c14","t":"مقتل الملك فيصل بن عبد العزيز آل سعود وتولي أخيه خالد المُلك .","s":"هو المَلِك فيصل بنُ عبدِ العزيز بنِ عبد الرحمن الفيصل آل سعودٍ، الابنُ الثالث لوالده الملك المؤسِّس عبد العزيز رحمهما الله. وُلِد في مدينة الرياض في 14 صفر سنة 1324هـ / 1906م في عام انتصار والده على ابن رشيد في القصيم. شارك في سنٍّ مبكِّرة في المعارك والأحداث التي واكبت نُشوء المملكة؛ ففي عام 1345هـ- 1927م ندبه والده لينوبَ عنه في المباحثاتِ مع بريطانيا التي انتهت بالتوقيع على معاهدة جدَّة في 18 ش"},{"id":5412,"era":"c14","t":"الحرب الأهلية اللبنانية .","s":"الحرب الأهليَّة اللبنانيَّة هي حرب دمويَّة وصراعٌ معقَّد استمرَّ في لبنان 15 سنة و6 أشهر ما بين 1975- 1990م، وتعود جذوره للصراعاتِ والتنازلاتِ السياسيَّة في فترة الاستعمار الفرنسيِّ لسوريا ولبنان، وعاد ليثورَ بسبب التغيُّر السكانيِّ (الديمغرافي) في لبنان والنزاع الدينيِّ: الإسلامي النصراني من جهةٍ، والسني الشيعي من جهة أخرى، ومما زاد من حدَّة النزاع تقاربُ هذه العناصر من سوريا أو إسرائيل. وقد ساهَ"},{"id":5413,"era":"c14","t":"استقلال جزر القمر .","s":"تقع جزرُ القمر (القمر الكبرى وأنجوان وموحلي ومايوت) في المحيط الهنديِّ على مقرُبةٍ من الساحلِ الشرقيِّ لإفريقيا، وأقربُ الدول إليها موزمبيق وتنزانيا ومدغشْقَر وسيشل. أصبحتْ جزرُ القمرِ تحت الحماية الفرنسيةِ بسبب استعانةِ بعض السلاطينِ على بعضِهم بالفرنسيِّين، فأصبحوا يتعاهدون مع الفرنسيِّين ضدَّ بعضهم، واستطاعت فرنسا أن تجعلَ الجزر تحت حمايتِها، ثم ألحقَت جزر القمر بجزيرة مدغشقر المحتلَّة من قِبَل"},{"id":5414,"era":"c14","t":"مشتاق أحمد يترأس بنغلادش بعد انقلاب عسكري على مجيب الرحمن .","s":"استبدَّ شيخ مجيب الرحمن بالحكمِ وحلَّ التنظيماتِ السياسيةَ كلَّها سوى حزبه الحاكمِ حزب رابطة عوامي، وبدأ الفسادُ الإداريُّ والفقر ينتشران، وبقِيَت بنغلادش تحت الوصاية الهنديةِ، فخاف الرئيسُ من العسكريِّين فنظم جيشًا سريًّا هو واكي باهيتي لحمايتِه الشخصيَّة. لكن العسكر قاموا بانقلابٍ ضد مجيبِ الرحمن في 28 رجب / 15 أغسطس، فأطاحوا به وبنائبِه ورئيس وزرائه والنظام القائمِ كله، وقُتِل مجيب الرحمنِ، ثم "},{"id":5415,"era":"c14","t":"وفاة شيخ مجيب الرحمن مؤسس دولة بنغلاديش ورئيسها .","s":"وُلِد شيخ مجيب الرحمن عام 1920م في قرية تونجيبار تبعد 97 كم جنوب غربي دكا، درس مجيب الرحمن في مدارس الإرسالياتِ التنصيريةِ وتربَّى فيها وحصل على درجة البكالوريوس في الآداب من جامعة كالكوتا، كما حصل على شهادة في القانون من جامعة دكا. كان أحد مؤسِّسي رابطة \"عوامي\" العام 1949م، وكان مؤيدًا انفصال باكستان عن الهند. استطاع شيخ مجيب بعد نُشوب حربٍ أهلية شرسةٍ بين شطري باكستان الغربيِّ والشرقيِّ أن ينفصل"},{"id":5416,"era":"c14","t":"انقلاب عسكري يطيح برئيس بنغلاديش ثم انقلاب آخر .","s":"بعدَ الانقلابِ على شيخ مجيب الرحمن واغتيالِه في أغسطس تولَّى رئاسة بنغلاديش مشتاق أحمد، وفي 29 شوال / 3 تشرين الثاني قام انقلابٌ ضدَّه بعد أن بقي في الرئاسة فقط ثلاثةَ أشهرٍ، وقاد الانقلابَ العميدُ خالد مشرف الذي أُحضر منَ الهندِ، وكان قائدًا سابقًا لحاميةِ دكا ويوالي الهند، وكان قد عُيِّن رئيسًا لهيئة الأركان، ولكنَّه لم يتولَّ السلطة سوى أربعةِ أيامٍ حتى حدث انقلابٌ آخر أقصاه عن الرئاسةِ، واستول"},{"id":5417,"era":"c14","t":"إعلان قيام الجمهورية العربية الصحراوية في الصحراء الغربية .","s":"أُعلنت الجمهوريةُ العربيةُ الصحراويةُ الديمقراطيَّة يوم 27 فبراير- شباط من قبل جبهة البوليساريو. وفي السادس من مارس- آذار 1976م تم تشكيلُ أولِ حكومةٍ صحراوية برئاسة محمد الأمين أحمد، ضمَّت عددًا من الوزاراتِ الميدانيةِ التي سارعت إلى تنظيمِ واستكمالِ الهياكل التنظيميَّةِ والإدارية \"للدولة الصحراوية\". لا تعترفُ حاليًّا أيُّ دولة كبرى أو دولةٌ عربية - باستثناءِ الجزائر - بهذه الجمهوريةِ المعلنة من ط"},{"id":5418,"era":"c14","t":"محاولة العقيد محمد نور سعيد الانقلاب على النميري .","s":"وقع في السودان انقلابٌ بقيادةِ العقيد محمد نور سعيد بتاريخ 5 رجب / 2 تموز، وهرب الرئيسُ جعفر النميريُّ واحتلَّ الانقلابيون المعسكراتِ ومطارَ الخرطومِ ودار الهاتف، استطاع النميريُّ أن يعودَ بعد يومين إلى مقرِّه وانضمَّت إليه بعض القطاعاتِ، فقادها وقام بعملية مضادَّةٍ، ولم يستطعْ دخولَ دار الهاتف إلا بصعوبةٍ؛ ورفضت جماعة الأنصار التي ساهمت في هذه الحركةِ إطلاقَ سراح المعتقلين السياسيِّين الذين في سج"},{"id":5419,"era":"c14","t":"وفاة عبد العزيز الميمني الراجكوتي .","s":"هو الأديبُ عبدُ العزيز الميمني الراجكوتي: باحث، ومحقِّق، ولغويٌّ، وخبير بالمخطوطات ونوادر الكتبِ، وأحد المهتمِّين بالثقافةِ العربيةِ. وُلد عبد العزيز الميمني سنة 1306هـ / 1888م ببلدة راجكوت، ومنها جاءت نسبتُه الراجكوتي، وهي تقعُ في إقليم كاتهيا دار بولاية گوجرات التي تُعرَف الآن باسمِ سوراشترا على الساحلِ الغربي للهندِ. التحقَ عبد العزيز الميمني بالكتَّاب، وتعلَّم مبادئ القراءةِ والكتابةِ، وحفِظ ا"},{"id":5420,"era":"c14","t":"وفاة خير الدين الزركلي صاحب كتاب الأعلام .","s":"هو خيرُ الدين بنُ محمود بنِ محمد بنِ علي فارس الزِّرِكلي وُلِد في بيروت في ليلة 9 من ذي الحجَّة 1310هـ، ونشَأَ في دِمَشقَ حيث موطنُ أبيه وأمِّه، وتعلَّم في إحدى مدارسها الأهليَّة، وأخذ عن عُلَمائها على الطريقة القديمة التي كانت سائدةً آنذاك في التعليم، وأقبَلَ على قراءة كُتُب الأدب، وجرى لسانُهُ بنَظْم الشِّعر، وصحب مخطوطات المكتبة الظاهريَّة، فكان لا يُفارقها إلا لساعاتٍ قليلة. أصدر مجلةً أُسبوعي"},{"id":5421,"era":"c14","t":"ضياء الرحمن يتولى رئاسة بنغلادش بعد تنحية عبد الستار صايم .","s":"في بنغلادش أخذ الفريق أول ضياء الرحمن يستولي على سُلُطات الرئيس الإدارية من الرئيس عبد الستار محمد صايم تبعًا للأحكام العسكرية، حتى تسلَّم أخيرًا كامل السُّلطة، وأعلن نفسه رئيسًا للبلاد وقام بجعل الإسلام نظامَ الدَّولة الأساسي بدلًا من العلمانية؛ إرضاءً للشعب؛ حيث كانوا يعرفون ماضيَه السيِّئ."},{"id":5422,"era":"c14","t":"انقلاب عسكري ضد الرئيس الباكستاني ذي الفقار علي بوتو .","s":"وقعت مظاهرات عنيفة في باكستان ضد الرئيس بوتو سقط خلالها حوالي 350 قتيلًا، مع آلاف الجَرْحى من جرَّاء العُنف السياسي؛ فدعا الرئيس بوتو الجيش إلى التدخُّل لمواجهة أعمال العنف، وقَمْع المظاهرات، وتأييد نظامه، إلَّا أن بعض ضُبَّاط الجيش -خاصة القادمين من إقليم البنجاب- رفضوا قمع المظاهرات والاصطدام بالشَّعْب وإطلاق النار على المتظاهرين، وكانت تلك النواة التي هيَّأت لضياء الحق -الذي كان قائدًا عامًّا ل"},{"id":5423,"era":"c14","t":"استقلال جيبوتي .","s":"كانت جيبوتي (الصُّومال الفرنسي) تحت الاحتلال الفَرَنْسي الذي سامها سوءَ العذاب، ثم بعد الحرب العالمية الثانية جرى التَّصويت على دستور ديغول الخاصِّ بالمستعمرات الفرنسية، وتدخلت فرنسا بالاستفتاء لصالح قَبول الدُّستور، فأصبحت جيبوتي ضمن المجموعة الفرنسيَّة، وفي منتصف عام 1378هـ قامت مظاهراتٌ تطالب بالاستقلال الكُلِّي وتندِّد بالاستفتاء الذي لم يكن حرًّا، وجرى إضراب عامٌّ للعمال، ولكنْ قُمِع بالبطش و"},{"id":5424,"era":"c14","t":"زيارة السادات لإسرائيل المحتلة وعرض  السلام عليها .","s":"أعلن الرئيس المِصْري محمد أنور السادات في 28 ذي القعدة 1397هـ / 9 نوفمبر 1977م أمام مجلس الأُمَّة أنه على استعداد للذَّهاب إلى جنيف؛ للمُفاوضة مع إسرائيل، بل يُمكِن أن يذهب إلى الكنيست ومُناقشة اليهود، وكان هذا نوعًا من جسِّ نَبْض الشعب ورؤية ردِّ الفعل الذي نتج عنه فعلًا استقالة عددٍ من الوزراء، منهم وزير الخارجية، ورئيس مجلس الوزراء نفسه، وتمَّ تعيين بطرس غالي بدلًا عنه، وقام الرئيس السادات بزيا"},{"id":5425,"era":"c14","t":"تأسيس الجبهة القومية للصمود والتصدي .","s":"تأسَّست الجبهة القوميَّةُ للصمود والتصدِّي ردًّا على زيارة الرئيس المصري أنور السادات للقدس، وبدء المفاوضات المصريةِ؛ لعقدِ صُلح مُنفردٍ مع إسرائيل. وقد ضمَّت الجبهةُ ليبيا وسوريا والجزائر ومُنظمةَ التحرير الفلسطينية واليمنَ الجنوبي."},{"id":5426,"era":"c14","t":"اعتراف بلجيكيا بالدين الإسلامي كدين رسمي في الدولة  .","s":"اعترفتِ الحكومةُ البلجيكية بالدين الإسلاميِّ كأحد الأديان الرئيسيةِ في البلاد. وكان هذا الاعترافُ هو الأولَ من نوعه في أوروبا، وفي عام 1998م وبعدَ حوالي ربعِ قرنٍ على هذا الاعترافِ حقَّق المسلمون نجاحًا آخر عندما خاضوا انتخاباتٍ على مُستوى الأقلِّية لاختيار هيئةٍ موحَّدةٍ تمثِّلهم لدى الحكومةِ، وتكون بمثابة المحاور الرسميِّ للسلطات البلجيكية في شؤون المسلمين."},{"id":5427,"era":"c14","t":"الشيوعيون ينقلبون على الرئيس الأفغاني محمد داود .","s":"ترأَّس محمد داود أفغانستان بانقلابٍ في 1393 هـ/ 1973م ضدَّ الشاه محمد ظاهر (وهو ابنُ عمِّ الشاه) وكانت ميولُ محمد داود للروس الذين أرادوا منه أن يخنقَ الدعوات الإسلامية في البلاد، ومن ثَم تستطيع الشيوعيةُ أن تنتشرَ فيها، وهذا ما حصل فعلًا في البدايةِ، ولكن لما رأى أن كفَّةَ الشيوعيِّين بدأت ترجحُ وأحسَّ من نفسه بالتبعية لها أرادَ أن يرجعَ عمَّا هو عليه، فبدأ بالتودُّد للدول الإسلامية، كالسعوديةِ و"},{"id":5428,"era":"c14","t":"وفاة محمد داود رئيس أفغانستان .","s":"هو السردارُ محمد داود ابن عمِّ الملك محمد ظاهر شاه، وزوج شقيقتِه، ضابط في الجيش الأفغانيِّ، درس في مدينة كابول، وأتمَّ دراستَه العسكريةَ في فرنسا، عُيِّن عام 1350هـ أيام محمد نادر خان حاكمًا على مقاطعة قندهار، وبعدَ خمس سنواتٍ عُيِّن قائدًا لقوات المنطقة الوسطى، ومديرًا للكلية الحربيةِ، وعُهد إليه برئاسة الوزارة عام 1373هـ فاحتفظ لنفسِه بحقيبتي وزارتي الداخلية والدفاع إضافة إلى رئاسة الحكومة، فحكم"},{"id":5429,"era":"c14","t":"انقلاب عسكري يطيح بالرئيس الموريتاني مختار ولد داده .","s":"كان أولُ رئيس موريتانيٍّ بعد الاستقلالِ هو مختار ولد داده الذي لم يُبقِ على أي حزبٍ إلا الحزب الحاكم، وبقِيَ رجالُ حزبه يتحكَّمون في البلاد، وازداد الجفافُ والخلافُ على الصحراء المغربيةِ، والحالة الاقتصاديةُ تتأخَّر وتتدهور، وتضايق الناس، وأربكت قضيَّة الصحراء وضعَ البلاد، وانتقل التذمُّر إلى العسكريِّين، فقامت حركةٌ هدفُها تحقيقُ السلام بإخراج البلادِ من حرب الصحراءِ، وتقويم الوضع الاقتصاديِّ، وق"},{"id":5430,"era":"c14","t":"مؤتمر كامب ديفيد (مخيم داود) للسلام بين مصر وإسرائيل .","s":"بعد أن تولَّى محمد أنور السادات رئاسةَ مصرَ خلفًا لجمال عبد الناصر أعلن سيرَه على نفس الخُطى، إلا أنه بدأ بالميل إلى أمريكا؛ ففتح البابَ كاملًا للأمريكانِ. فاجأ الساداتُ العالمَ أجمعَ العربي والإسلاميَّ بزيارته للقدس، نجم عنها توقيع معاهدةَ السلام المصرية الإسرائيلية (كامب ديفيد) في الولايات المتحدةِ؛ وقَّع المعاهدةَ من الجانب الإسرائيليِّ رئيسُ الوزراء الإسرائيلي مناحيم بيغن، ومن الجانب المصريِّ "},{"id":5431,"era":"c14","t":"رفض جبهة الصمود والتصدي لاتفاقات كامب ديفيد بين مصر وإسرائيل .","s":"أعلنت جبهةُ الصمود والتصدِّي التي تتكوَّن من سوريا والعراق وليبيا واليمنِ الجنوبيِّ والجزائر ومُنظمةِ التحرير الفلسطينية في قمَّتِها الثالثة في دمشقَ رفضَها لاتفاقية كامب ديفيد؛ معاهدة السلام المنفردةِ من قِبَل مصر مع إسرائيلَ التي وقَّعها الساداتُ مع إسرائيل في 17/ 9/ 1978م. دون مراعاةِ مصر للإجماع العربي والمتبِّني في حينِه اللاءات الثلاثة: (لا صُلح، لا اعتراف، لا تفاوض) مع العدو الصهيونيِّ قبل "},{"id":5432,"era":"c14","t":"مأمون عبد القيوم رئيسًا للمالديف خلفا لإبراهيم ناصر .","s":"انتهت ولايةُ الرئيسِ المالديفي إبراهيم ناصر وجرتِ الانتخابات، ولكن دون أن يرشِّح الرئيسُ إبراهيم ناصر نفسَه، واختار المجلس وزيرَ المواصلاتِ مأمون عبد القيوم لمنصب الرئاسةِ، فتسلَّم مهمَّته."},{"id":5433,"era":"c14","t":"مؤتمر القمة العربية التاسع (قمة بغداد) .","s":"عُقد مؤتمر القمَّةِ العربية التاسعُ (قمة بغداد) بناءً على طلبِ العراق على إثرِ توقيع مصر اتفاقية كامب ديفيد للسلام مع إسرائيلَ؛ حيثُ وقَّع أنور السادات معاهدةَ السلام من جانب واحدٍ مع إسرائيلَ، فقرَّر المؤتمر أنَّ الاتفاقاتِ التي وقَّعتْها الحكومةُ المصرية في كامب ديفيد أضرَّت بحقوق الشعبِ الفلسطيني، وتم حثُّ الحكومة المصريةِ على عدم التصديقِ على الاتفاقياتِ، والأهمُّ من ذلك أن الجامعةَ جمَّدت علا"},{"id":5434,"era":"c14","t":"تنحية الرئيس الموريتاني ولد مصطفى وتولي محمد خونا ولد هيداله .","s":"كانت رئاسةُ الرئيس الموريتانيِّ ولد مصطفى بن ولد محمد السالك صوريةً، ولا تصرُّفَ له، بينما المتصرِّف الفعليُّ هو المقدم أحمد بوسيف الذي تُوفِّي في رجب عام 1399هـ فحلَّ محله المقدم محمد خونا ولد هيداله، والذي أصبح بدورِه هو المتصرِّفُ الفعليُّ والرئيس ما يزال بلا سلطةٍ إلى أن قام المقدم محمد خونا بعزلِ ولد مصطفى عن رئاسةِ الجمهوريةِ، وتسلَّم مكانه ورفع رتبتَه إلى لِواء."},{"id":5435,"era":"c14","t":"وفاة الرئيس الجزائري هواري بومدين .","s":"هو محمد إبراهيم بوخروبة، المعروفُ باسم هواري بومدين زعيم أمازيغي رئيسُ الجزائر. وهو ابنُ فلاحٍ بسيطٍ من عائلة كبيرةِ العددِ ومتواضعة الحال تَنتمي إلى عرش بني فوغال التي نزحت من ولاية جيجل عندَ بداية الاحتلال الفرنسيِّ، وُلد سنة 1932في دوَّار بني عدي (العرعرة) على بُعد بضعةِ كيلومترات غرب قرية \"قالمة\" من قرى الشرقِ الجزائريِّ، وتعلَّم بها وبقسنطينةَ، والتحقَ في تلك الحِقبة بجامع الزيتونةِ الذي كان "},{"id":5436,"era":"c14","t":"معاهدة الصداقة الأفغانية- السوفيتية الثنائية .","s":"بعد اغتيالِ رئيسِ أفغانستان مُحمد داود وعائلتِه ومعظم مساعديه في مذبحةٍ جماعيَّةٍ بشعةٍ في انقلاب شيوعيٍّ حكم البلادَ أولُ شيوعيٍّ هو نور محمد تراقي مؤسِّس حزب الشعب الشيوعيِّ، وحرص الاتحادُ السوفيتيُّ فورًا على دعم تراقي؛ من أجل إقامة نظامٍ ماركسيٍّ؛ ولذلك أبرمت موسكو بعد قرابة ثمانيةِ أشهرٍ من الانقلاب الشيوعيِّ الدمويِّ معاهدةَ صداقة ثنائية بين البلدينِ في 4 محرم / 5 ديسمبر تمتدُّ لعشرين عامًا،"},{"id":5437,"era":"c14","t":"وفاة المقرئ الشيخ مصطفى إسماعيل .","s":"هو القارئُ المشهورُ مصطفى محمد المرسى إسماعيل. من روَّاد التلاوة والترتيل للقرآن الكريمِ وكان يطلق عليه (كروان المقرئين)، ولد عام 1905 في محافظة الغربية بمصرَ في قرية ميت غزال، وقرَّر جدُّه إلحاقه بكُتَّاب القرية بمجرَّد أن بلغ الخامسة من عمرِه، واستطاع أن يتمَّ حفظ القرآن الكريم كاملًا وهو في سنِّ الثانية عشرة، درس بعدها القراءاتِ القرآنيةَ حتى أجادها وهو في السابعة عشرة من عمره، وسافر بعدها إلى "},{"id":5438,"era":"c14","t":"ثورة الخميني في إيران ونهاية حكم الشاه محمد رضا بهلوي .","s":"عمِلَ الشاهُ ما سماه الثورة البيضاء والتي هدفُها إخضاعُ رجال الدينِ وأخْذ جزءٍ من ممتلكاتهم أيضًا، وكان الخمينيُّ قد سُجِن بسبب ردِّه على الشاه يوم رفَضَ تعدُّد الزوجات، ثم نُفيَ إلى تركيا، ثم إلى العراق، وعاش في النجف، ثم أُجبر على السفر من العراقِ، ورفضت الكويتُ استقباله فسافر إلى فرنسا، ومع ذلك كانت خُطبه وكلماتُه وحماسه يُنقَل إلى إيران فتحدُث بسببها أعمالُ شغب ومظاهرات، وحدثت عدَّة أعمال عنفٍ"},{"id":5439,"era":"c14","t":"تولي الشاذلي بن جديد رئاسة الجزائر بعد وفاة هواري بومدين .","s":"لما تُوفِّي هواري بو مدين في أواخر عام 1398هـ في مدينةِ الجزائرِ اجتمع المجلسُ العسكريُّ وكتم الوفاةَ حتى اتفق أعضاؤه على تسليمِ أحدِهم الرئاسةَ، ووقع الاختيارُ على الشاذلي بن جديد."},{"id":5440,"era":"c14","t":"تَوقيعُ مُعاهدةِ السلام بين مِصرَ وإسرائيلَ .","s":"تُعدُّ مُعاهدةُ السلامِ بين مصرَ وإسرائيلَ عام 1979 أوَّلَ خَرْقٍ عربيٍّ للموقف العربيِّ مِن إسرائيل؛ حيث تعهَّدت الدَّولتانِ بمُوجِب هذه المعاهدةِ على إنهاءِ حالة الحرْبِ وإقامة عَلاقاتٍ وُديَّةٍ بينهما؛ تَمْهيدًا للتسويةِ التي تقومُ على مَبدأ (الأرض مُقابِل السلام)؛ فتَنسحِبُ إسرائيلُ مِن سيناء التي احتلَّتْها عام 1967، مُقابلَ اعترافِ مِصرَ بإسرائيلَ، وتنصُّ المعاهدةُ على: (أنَّ حُكومتي جُمهوري"},{"id":5441,"era":"c14","t":"وفاة الرئيس علي ذي الفقار بوتو  .","s":"هو الرئيس ذو الفقَّار علي بوتو بن شاهنواز سياسيٌّ باكستانيٌّ شِيعيٌّ، تقلَّب في مناصبَ عديدةٍ حتى أصبح رئيسًا لباكستان. وُلِد بوتو في 5 كانون الثاني في بَلْدة لاركانا في مقاطعة السِّنْد، والده شاهنواز من مُلَّاك الأراضي في المنطقة ومن أعْيانها، عُرِف والدُهُ بمقارعته للاستِعْمار البريطاني وبمُطالبتِهِ بإنشاء دَوْلة باكستان. وأُمُّه خورشيد هُندوسيَّة الأصل، تشيَّعت قبل الزَّواج بها. درس تعليمَه الأ"},{"id":5442,"era":"c14","t":"صدام حسين يزيح الرئيس العراقي أحمد البكر ويتولى الرئاسة .","s":"تسلَّم حِزبُ البَعْث السلطةَ في العراق منذ عام 1388هـ / 1968م، وكان صدَّام حسين التكريتيُّ من المُقرَّبين لأمين الحِزْب أحمد حسن البكر حتى وصَلَ صدَّام إلى مَنصِب الأمين القُطْري لحِزْب البَعْث العربي الاشتراكي، واستطاع أن يُزيحَ من أمامه كلَّ مَن يرى أنهم سيعيقون طُموحَه فأزاح حردان عبد الغفار التكريتيَّ، ثم صالح مهدي، ثم عدنان الحَمْداني، وغيرَهم من القيادة القُطْرية، ومن مَجلِس قيادة الثَّوْرة،"},{"id":5443,"era":"c14","t":"اشتداد المقاومة الإسلامية بأفغانستان ودخول الوحدات الروسية .","s":"قامت حركاتُ مُقاومةٍ في شرقي البلاد في نورستان حتى اضطرَّ الرئيسُ كارمل للسَّفَر لروسيا لطلَبِ المُساعدةِ المادِّيَّة، ثم اشتدَّت المقاومة، وظهر في الساحة الحزبُ الإسلاميُّ بقيادة قَلْب الدين حكمتيار وأحزابٌ أخرى، وفي ربيع الثاني 1399هـ / آذار 1979م وقَعَت انتفاضةٌ في مُعَسكرات هراة وحَدَثَ تمرُّد عسكريٌّ في الجيش، فأرسل الرُّوس في شعبان أوَّلَ وَحْدة هُجوميةٍ إلى أفغانستان، وهي عبارةٌ عن كتيبةٍ م"},{"id":5444,"era":"c14","t":"مذابح المسلمين في الحبشة .","s":"وَضَعَ هيلاسيلاسي خُطَّة لإنهاء المسلمين خلال 15 عامًا، وتباهى بخُطَّتِهِ أمام الكونجرس الأمريكي, وقام بإحْراقِ الشُّيوخ والنِّساءِ والأطفالِ بالنَّار والبنزين في قَريةِ جرسم, وأمَرَ بالتَّعْقيم الإجباريِّ للمسلمين رجالًا ونساءً. وقام بعدَه السَّفَّاح منجستو بمذبحةٍ كبيرةٍ؛ حيث أمر بإطلاق النَّار على المَسجِدِ الكبيرِ بمدينةِ ريرادار بإقليم أوجاوين؛ فقُتِل أكثَرُ من ألْفِ مُسلمٍ كانوا يُؤدُّون الص"},{"id":5445,"era":"c14","t":"تولي حفيظ الله أمين رئاسة أفغانستان بعد اعتقال نور محمد تراقي .","s":"تولَّى نور مُحمَّد تراقي الشُّيوعيُّ رئاسةَ الدَّوْلة بعد انقلابِهِ على مُحمَّد داود؛ من أجْلِ أن يُطبِّقَ النِّظام الماركسيَّ في البلاد، فعقدتْ روسيا معه مُعاهدةَ صداقةٍ ثُنائيَّة في 5 ديسمبر؛ لدَعمِهِ اقتصاديًّا وعسكريًّا، ولكن سادتِ البلادَ مَوْجةُ غضبٍ من الأوضاعِ السياسيَّةِ الجديدةِ والغريبةِ على الشعب, فقد سعى تراقي إلى تطبيقِ الماركسيَّةِ على كُلِّ الأصعدة دون اعتبار للتقاليد والأعْراف الت"},{"id":5446,"era":"c14","t":"وفاة نور محمد تراقي رئيس أفغانستان .","s":"هو نور مُحمَّد تراقي أوَّلُ رئيسٍ لأفغانستانَ بعدَ الانقِلابِ الشُّيوعيِّ على مُحمَّد داود. وُلِدَ تراقي عامَ 1335هـ 1917م في قريةِ (ميدو) في ولاية غَزْنة، وسافَرَ في 1353هـ / 1934م إلى الهِنْد، وبَقِيَ في بومباي 4 سنواتٍ، وهناك اعتنَقَ الفِكْر الشيوعيَّ، وعندما رجَعَ إلى بلادِهِ عَمِلَ في مُؤسَّسة السُّكَّر التِّجاريَّةِ بوزارةِ الماليَّة، والتَحَقَ أيضًا بجامعةِ كابلَ، ثم ابتُعِثَ إلى أمريكا كمُ"},{"id":5447,"era":"c14","t":"وفاة أبي الأعلى المودودي أمير الجماعة الإسلامية بالهند .","s":"هو أبو الأعْلى المَوْدوديُّ بنُ أحمَدَ حسن مودودي أميرُ الجماعة الإسلامية، وُلِدَ في 3 رجب سنة 1321هـ بمدينة أورَنْج آباد الدكن في حَيْدر آباد، وتلقَّى تعليمَهُ على يد والدِهِ، فتعلَّم المودوديُّ القُرآنَ والعربيةَ والحديثَ والفِقْه حتى حَفِظَ المُوطَّأَ، ثم دخل الثانويَّةَ وهو ابن 11 سنةً لنُبوغِهِ، ثم بعد ذلك بدأ العملَ في الصَّحافةِ التي وجَدَ فيها مجالًا للدَّعْوة والتَّعْليم، وكان يُصدِرُ مجل"},{"id":5448,"era":"c14","t":"حادثةُ دُخولِ جُهيمان العتيبي ورفاقه الحرمَ المكيَّ الشريف .","s":"عَمِلَ جُهيمان بن محمد بن سيف العتيبيُّ في الحرس الوطني السُّعوديُّ لمدة 18 عامًا، ثم انتقل إلى جامعةِ أمِّ القُرى للدراسة فيها، ثم انتقَلَ إلى الجامعة الإسلامية في المدينة المنوَّرةِ، وهناك الْتقى بمحمد بن عبد الله القَحطانيِّ. تزوَّج جُهيمان العتيبي بأختِ محمد القحطانيِّ، وفي غرَّة محرَّم من العام 1400 من الهجرة / 20 تشرين، نوفمبر بعْد صَلاة الفجر دخَل جُهيمان وجماعتُه المسجد الحرامَ في مكة المك"},{"id":5449,"era":"c14","t":"مظاهرات الشِّيعة في القَطيفِ .","s":"أثناء انْشِغالِ القوَّات الحُكوميَّة في إنهاء حادثة الحرَمِ المكِّيِّ، وخِلافًا لِأوامِرِ الحكومة بمنْعِ المظاهراتِ؛ خرَجَ الشِّيعةُ في القَطيف أثناءَ احتِفالِهم بيومِ عاشوراءَ في مُظاهراتٍ عامَّةٍ، فحاولت قُوَّاتُ الحرَس منْعَ مَواكبِهم الدِّينية من التجمْهُرِ في الشوارع العامَّةِ، إلَّا أنَّ جُموعهم تدفَّقَت ترفَعُ شِعاراتٍ مُعاديةً، ويُردِّدون شعاراتٍ مُؤيِّدةً لِنِظام الخُمينيِّ في إيران، كما "},{"id":5450,"era":"c14","t":"انقلابٌ عسكريٌّ يُطيح بالرئيس الأفغاني حَفيظ الله أمين .","s":"لم تَرْضَ روسيا عن حَفيظ الله أمين رغم شُيوعيته؛ فهم لا يَرغبون بشُيوعيةٍ تخرُج عن دائرتِهم، وكان حِزْبُ برشام (الراية) الحزبَ الشيوعيَّ الأقربَ لِمُوسكو؛ فهو يرى الارتباطَ بها، وكان زَعيم الحزب هو بابرك كارمل، وكان لا يَزال في (براغ) عاصمة تشيكسلوفاكيا كلاجئٍ سياسيٍّ، ثم في يوم 6 صفر 1400هـ / 27 ديسمبر حدَث هجومٌ على القصر الجُمهوري برئاسة وزير الدِّفاع محمد أسد وطنجار، واعتُقِلَ رئيسُ الجمهوريةِ"},{"id":5451,"era":"c14","t":"دَعمُ الاتِّحاد السُّوفيتيِّ نِظامَ بابرك كارمل الشيوعي في كابُلَ  .","s":"أرسَلَ الاتِّحادُ السُّوفيتي الجيشَ الأربعينَ لِدَعْمِ نِظام بابرك كارمل الشيوعي في كابُل، والذي قام بانقلابٍ اغتِيلَ فيه الرئيسُ الشيوعي حفيظ الله أمين الذي اتُّهِم بأنه \"عميل لِلأمريكانِ\". جاء كارمل إلى السُّلطة بعد عِدَّة انقلاباتٍ شَهِدتها أفغانستانُ على إثر سُقوط الملَكِيَّة في يوليو 1973م، بعد انقلاب عسكريٍّ قام به محمدُ داود ابن عم الشاه محمد ظاهر وزَوْج شَقيقته، الذي أعلَنَ جُمهورية أفغانس"},{"id":5452,"era":"c14","t":"التدخُّل (الاحتلال) الرُّوسي في أفغانستانَ .","s":"الحربُ السُّوفيتية في أفغانستانَ، أو الغزوُ السُّوفيتيُّ لأفغانستانَ؛ هو اسمٌ يُطلَق على حرْبٍ دامتْ عشْرَ سنواتٍ، كان هَدَف السُّوفيت المعلَنُ دعْمَ الحكومة الأفغانيةِ الصَّديقة للاتِّحاد السُّوفيتيِّ، والتي كانت تُعاني مِن هَجَمات الثوَّار المعارضِينَ للسُّوفيت، والذين حَصَلوا على دَعْمٍ مِن مجموعةٍ من الدول المناوئةِ للاتحادِ السُّوفيتي، مِن ضِمْنها الولاياتُ المتحدة الأمريكيةُ، والسُّعودية، وب"},{"id":5453,"era":"c14","t":"وُقوع أحداث عُنْف داميةٍ في مَدينة قفصةَ التَّونسيةِ. .","s":"وقَعَت أحداثُ عُنْفٍ داميةٍ في مدينةِ قفصةَ جنوب غرب تونس من 26 يناير حتى 3 فبراير 1980م، قام بها كُوماندوس من المعارضينَ التُّونسيين ذي توجُّهٍ عُروبيٍّ تسرَّبوا إلى مدينةِ قفصةَ، وقد تمكَّن المهاجِمون مِن السيطرةِ على أغلَبِ مَراكزِ المدينةِ، إلا أنَّ دَعواتهم للسُّكَّان إلى التمرُّدِ باءتْ بالفشَلِ. وتمكَّن الجيشُ في نِهايةِ الأمْر مِن إعادة السَّيطرةِ على المدينةِ وأسْرِ قائدِ المجموعةِ. وأدَّ"},{"id":5454,"era":"c14","t":"أبو الحسنِ بني صدر أوَّلُ رئيسٍ للجُمهورية الإيرانية .","s":"اختار الخُميني أبا الحسنِ بني صدر (وهو الذي كان يُرافِق الخُميني عندما رجَعَ إلى إيرانَ مِن فرنسا، وهو طَبيبٌ إيرانيٌّ متجنِّس بالجِنسيةِ الأمريكية) رئيسًا لِجُمهوريةِ إيرانَ الإسلامية، فرَشَّح نفْسَه يوم 8 ربيعٍ الأول 1400هـ، فحصَلَ على نِسبةٍ عاليةٍ من الأصواتِ، فأصبَحَ أوَّلَ رئيسِ جُمهوريةٍ في إيرانَ، وبقِي هو المشرِفَ على شُؤون الدولة والموجِّهَ لِإدارتها وللرَّعية، وكَلِمتُه هي المسموعةَ، وب"},{"id":5455,"era":"c14","t":"وَفاة المحامي أحمدَ أسعد الشقيريِّ؛ أوَّلُ رئيسٍ لمنظَّمة التحريرِ الفلسطينية .","s":"هو المحامي أحمدُ أسعد الشقيريُّ، وهو كاتبٌ ومُحامٍ، وسياسيٌّ ودُبلوماسي، وأوَّلُ رئيسٍ لمنظَّمة التحرير الفلسطينيةِ. وُلِدَ في قَلعةِ تبنين جنوبَ لُبنان عام 1908م، وانتقَلَ إلى عكَّا لِيَعيش في كَنَفِ والدِه بعد وفاةِ والدتِه. أسَّسَ مع رِفاقه «جمعية الوَحدةِ العربية»، وطُرِد مِن بيروتَ، فانتقَلَ إلى القُدس، ودخَل معهد الحُقوق الفِلَسطيني هناك، ثم دخَلَ سِلكَ المحاماةِ، وكتَب في الصُّحف الفلسطينية"},{"id":5456,"era":"c14","t":"اغتيالُ عالِم الذَّرة المصري الدكتور يَحيى المشد في باريسَ .","s":"هو الدكتور يَحيى أمين المشد؛ عالِمُ ذَرَّةٍ مصريٌّ وأستاذٌ جامعيٌّ، وُلِد يحيى المشد في مصرَ في مدينةِ بَنْها سنة 1932، وتعلَّم في مدارسِ طنْطا، وتخرَّج من قِسم الكهرباء في كُلِّية الهندسة جامعة الإسكندريةِ سَنة 1952، اختِيرَ لِبَعثة الدكتوراه إلى لَندنَ سنة 1956، لكنَّ العُدوانَ الثُّلاثي على مصرَ حوَّلها إلى مُوسكو، ثم عاد بعدها سَنة 1963 متخصِّصًا في هَندسة المفاعِلات النَّووية. وعندَ عَودتِه ا"},{"id":5457,"era":"c14","t":"الحربُ العِراقيةُ الإيرانيةُ .","s":"بدَأَت الحربُ بين العراقِ وإيرانَ في 13 ذي القعدة عام 1400هـ / 22 أيلول، باندفاعِ القواتِ العراقيةِ داخلَ إيرانَ؛ اعتمادًا على اتِّفاقية الجزائر التي تُطالِبُ الطرفينِ بالانسحابِ مِن المناطق المحتلَّةِ من أرْض الطرَفِ الآخَرِ، غيرَ أن إيرانَ لم تَنسحِبْ من مَنطقة زين القوسِ، وتجاهَلَت مُطالبةَ العراقِ لها بالانسحابِ، ثم قامتْ إيرانُ بهُجومٍ مُعاكس في جُمادى الأولى عام 1402هـ / آذار 1982م، وتمكَّنت"},{"id":5458,"era":"c14","t":"الانقلابُ العسكريُّ الثالث في تُركيا على الرئيسِ فخري كوروتورك .","s":"زاد النشاطُ الإسلاميُّ في تُركيا أيامَ حُكومة فخري ثابت كوروتورك، والذي أظهَرَه حِزب السلامة الوطني برئاسة نَجم الدِّين أرْبكان، وهذا ما أخاف الدوائرَ الاستعماريةَ، فكان لا بُد مِن إجراء عمل يحدُّ من نَشاط الإسلاميين، مع الخوف أيضًا من انتشارِ الشُّيوعية وسَيطرتها على الحُكْم، فتَحرَّك الجيش بقيادةِ رئيس الأركان كنعان إيفرين في 3 ذي القعدة 1400هـ / 12 أيلول بانقلابٍ عَسكري ضدَّ الحكومة المدنية الم"},{"id":5459,"era":"c14","t":"تَوقيعُ مُعاهَدة التعاون والدِّفاع المشترك بين سُوريَة والاتِّحاد السُّوفيتي .","s":"وَرِثت روسيا تَركةَ الاتِّحاد السُّوفيتي القديمِ وعَلاقتَه بالجُمهورية العربية السُّورية، وقد مرَّت عَلاقاتُهما بكثيرٍ من المواقف المختلِفة، ويُلاحَظ أنَّ السُّوفيت لم يَرْكَنوا إلى الحكومات السُّورية المتعاقِبة؛ لِعَدائها جميعًا للحزبِ الشُّيوعي السوري، إلَّا أنهم ارْتاحوا لِرَغبتِها في الحِفاظ على استقلال سُوريَة، وتجنُّب الشِّباك الأمريكية، وقد وقَّعت سُوريَة معاهدةَ صداقةٍ وتعاوُن مع الاتِّحاد"},{"id":5460,"era":"c14","t":"زِلزالانِ يَضربانِ مدينة الأصنام (الشلف حاليًّا) بالجزائرِ .","s":"ضرَبَ زِلزالانِ عَنيفانِ متتاليانِ مدينة الأصنام (الشلف حاليًّا) في غرب الجزائرِ، الأول في يوم الجمعة 30 ذي القعدة / 10 أكتوبر، بقوَّة سبْعِ درجاتٍ وثلاثة أعشارِ الدرجةِ، وقد كان زلزالًا عَنيفًا جِدًّا لدرجةِ تَدميره 80 بالمائةِ من المدينةِ، واستمرَّت الهزات الارتداديةُ لهذا الزلزالِ عدَّة أشهرٍ بعد الهزةِ الأولى، فوقَع زلزالٌ ثانٍ بقوَّة ست درجاتٍ وثلاثة أعشار الدرجةِ حسَب مِقياس رِيخترَ، وأدَّيا"},{"id":5461,"era":"c15","t":"استقالةُ رئيس السِّنغال ليوبولد سنجور مِن مَنصبه .","s":"في مَطلع عام 1401هـ / ديسمبر 1980م استقالَ رئيسُ جُمهورية السِّنغال ليوبولد سنجور مِن مَنصبه، مُتنازلًا لِنائبِه ورَئيس وُزرائه عبده ضيوف الذي شغَلَ مَنصِبَ رئاسة الوزراءِ أكثَرَ مِن عشْر سِنين."},{"id":5462,"era":"c15","t":"مُؤتمر القِمة العربي الحادي عشر (قمة عَمَّان) .","s":"عُقِدَت قِمةُ عَمَّان في 25 – 27 تشرين الثاني 1980م، وأكَّدت هذه القِمةُ التي شاركتْ فيها 15 دولةً دَعْمَها لِوَحدة وسلامة أراضي لُبنان، ووافقَتْ على استمرارِ مُقاطَعة مصرَ، ودعمَت العراقَ في حَرْبه ضدَّ إيرانَ.وصدَر عن المؤتمر بيانٌ خِتامي تضمَّن مجموعةً من القراراتِ؛ أهمُّها:- عَزْم القادةِ العربِ على إسقاط اتِّفاقيتي كامب دِيفيد للسلامِ مع إسرائيلَ.- التأكيدُ على أنَّ قرارَ مجلس الأمْن رقم (242"},{"id":5463,"era":"c15","t":"مُؤتمر القِمة الإسلامي الثالث (قِمة مكَّة المكرَّمة) .","s":"عُقِدَ هذا المؤتمرُ في مكَّة المكرَّمة في المملكةِ العربية السُّعوديةِ من 19-22 ربيع الأول 1401 هـ، الموافِق 25-28 يناير 1981م، وقد تغيَّب عن المؤتمر كلٌّ مِن جُمهورية إيرانَ الإسلامية، والجَماهيرية العربية اللِّيبية الشَّعبية الاشتراكية، وقد صدَرَ عنه بلاغُ مكَّةَ المشهورُ الذي أصْدَره المشارِكون، وصدَر أيضًا عنه قراراتٌ كثيرةٌ جدًّا؛ سياسيةٌ، وثقافيةٌ، واقتصاديةٌ، تمَسُّ العالَمَ الإسلاميَّ، كما"},{"id":5464,"era":"c15","t":"قَطعُ العَلاقات الدُّبلوماسية بين موريتانيا والمغربِ .","s":"انقطَعَت العَلاقات الدُّبلوماسية بين دولتيْ موريتانيا والمغربِ؛ وذلك في أعقابِ اتِّهامات نفَتْها الدَّولتانِ، بتورُّطِ كلٍّ منهما في محاولاتٍ لِزَعزعة استقرارِ الأُخرى."},{"id":5465,"era":"c15","t":"عَودة عبد الستار صايم لِرئاسة بنغلادش بعْدَ اغتيالِ الرئيس ضياء الرَّحمن .","s":"اغتِيلَ الرئيسُ ضياء الرحمن في مُحاولة انقلابٍ عَسكري، يُعتقَدُ أنَّ قائده الفريق محمد عبد المنصور، وهو قائدُ إحدى الوحداتِ العسكريةِ، وذلك في 27 رجب 1401هـ / 30 أيار 1981م، وتولى الرِّئاسةَ القاضي عبدُ الستار محمد صايم؛ الرئيسُ السابق الذي خُلِعَ عام 1397هـ، وقد كان نائبًا للرئيسِ ضِياء الرحمن."},{"id":5466,"era":"c15","t":"عَزْلُ الرئيس الإيرانيِّ (أبو الحسن بني صدر)، وتولِّي محمد علي رجائي .","s":"أُقْصِي الرئيس أبو الحسن بني صدر مِن قيادة القواتِ المسلَّحة، وأُغلِقَت جَريدتُه، وقامت المظاهراتُ عليه، فاختَفى عن الأنظارِ، فدَعاه الخُميني للظُّهور وإعلانِ تَوبته، ولكنه لم يَستجِبْ، فصدَرَ أمْرٌ بمنْعِه من السفرِ خارجَ البلاد، وفي 19 شعبان 1401هـ / 21 حزيران 1981م قرَّر المجلِسُ النِّيابي عدَمَ صلاحيتِه لرئاسة الدَّولةِ، وتَشكَّلَ مجلسٌ رئاسيٌّ من ثلاثةِ أعضاء، لكن حدَث انفجارٌ في مقرِّ حِزب ا"},{"id":5467,"era":"c15","t":"إسرائيلُ تدمِّرُ المفاعلَ النَّووي العِراقي .","s":"ضرَبَت إسرائيلُ المفاعِلَ النَّووي الذي أقامته فَرنسا على بُعْد عشرةِ أميالٍ ونصف الميل جنوب شَرق بغدادَ، واشتَرَكت في العمليةِ 8 طائرات (فالكون - ف16) مُقاتِلة وقاذِفة، في بطْنِ كلٍّ منها 900 كيلو جرام قنابل ثَقيلة، مُوجَّهة بأشعَّة اللِّيزر، تُغطِّيها 8 طائراتٍ أُخرى (إيجل - ف15) مُزَّودة بصواريخ جو - جو، مِن طُراز «سبارو» و«سسايدوندر»، وبها خزاناتُ وَقودٍ إضافية، وأجهزةُ تَشويشٍ إلكتُرونية.. وق"},{"id":5468,"era":"c15","t":"قَتلُ الرئيسِ الإيراني محمد علي رجائي، وتولِّي علي خامنئي .","s":"قُتِلَ رئيسُ جمهورية إيرانَ الإسلامية محمد علي رجائي بعد شهرينِ مِن تَسلُّمه المنصبَ، وقُتِلَ معه في حادثِ انفجارِ قُنبلة رئيسُ الحكومة، ثم جَرَت الانتخاباتُ في ذي الحجة / تشرين الأول، وفاز بها علي خامنئي (أحد المقرَّبين من الخُميني ومِن مؤسِّسي حزب الجمهورية)، وأقسَمَ اليمينَ الدُّستورية بعد عُطلةِ عيدِ الأضحى مباشرةً."},{"id":5469,"era":"c15","t":"تُركيا تخفِّض حَجْم تَمثيلها الدُّبلوماسي مع إسرائيلَ .","s":"خفَّضت تُركيا حَجمَ تَمثيلِها الدُّبلوماسي مع إسرائيلَ؛ وذلك احتجاجًا منها على قرارِ الكِنيست القاضي بضَمِّ القُدس الشرقيةِ، واعتبار القُدس عاصمةً لإسرائيلَ. وطالَبَت الحكومةُ الإسرائيليةُ باتِّخاذ إجراءٍ مُماثل في سِفارتها بأنقرةَ."},{"id":5470,"era":"c15","t":"وَفاةُ الشيخ راشدِ بن حميد النعيميِّ، حاكم إمارةِ عَجمان .","s":"وُلِدَ عام 1902 بإمارةِ عَجمان، وتولَّى الحُكمَ في سنةِ 1928م، وهو الحاكمُ التاسعُ للإمارةِ، ويُعتبَر مؤسِّسَ إمارةِ عَجمانَ الحديثةِ، وقد قام بإنشاءِ شُرطة عَجمانَ عام 1967م، وشارَكَ في اجتماعاتِ تكوينِ الاتِّحاد، وقد وقَّع على الدُّستور المؤقَّت يوم 2 ديسمبر 1971م، وأصبحت عَجمانُ جُزءًا مِن دولة الإماراتِ العربية المتحِدة، وأصبَح عضوًا إلى المجلسِ الأعلى للاتِّحاد. تُوفِّي رحمه الله صباحَ يوم ال"},{"id":5471,"era":"c15","t":"اغتيالُ الرئيسِ المصري محمد أنور السادات، وتولِّي محمد حُسني مبارك الحكْمَ .","s":"في يومِ الاحتفال بذِكرى حرْب رمضانِ، وفي يوم 8 ذي الحجة 1401هـ / 6 تشرين الأول 1981م، وبيْنما كان الرئيسُ أنور السادات على مَنصَّة الشرَفِ يَرتدي البِزَّة العسكريةَ، وحولَه أعوانُه، وتمرُّ أمامَه أرتالُ الجُند في العرْض العسكريِّ؛ تقدَّم مِن بيْنِهم الضابطُ خالد الإسلامبولي وأطلَقَ عليه النارَ فأرداه قَتيلًا، فكانت مدَّةُ رئاستِه تَزيدُ على أحد عشَرَ عامًا. وتولَّى رئاسةَ الجمهورية مؤقَّتًا رئيسُ "},{"id":5472,"era":"c15","t":"اعتداءُ إيرانَ على المنْشآت الكويتيةِ .","s":"كان الدِّفاعُ عن العراق -والتي كانت في حالةِ حربٍ مع إيرانَ- موضعَ اتِّفاق أعضاءِ مجلس التعاوُن الخليجيِّ. وكانت سياسةُ الكويت التي استنَدَت لاتِّفاقيات مُبرَمةٍ في 1972، 1978، والتي نظَّمت تِجارة الترانزيت، والإمدادَ العسكريَّ مِن موانئِ \"الشعيبة\" و\"الشويخ\" الكويتيينِ إلى البصرةِ؛ تَعكِسُ دعمًا للعراقِ، وقد أدَّى هذ إلى ردِّ فِعلٍ عسكري إيرانيٍّ؛ ففي 10/ 8/ 1981 اعترَضَت البحريةُ الإيرانية عند مد"},{"id":5473,"era":"c15","t":"إسرائيلُ تَعتدي على لُبنانَ وتحاصِرُ العاصمةَ بَيروت  .","s":"خرَقَت إسرائيلُ وقفَ إطلاقِ النار مع لُبنانَ الذي أبرَمَتْه في يوليو/ تموز بضغْطٍ أمريكيٍّ، وقامت القواتُ الإسرائيليةُ بغَزْوِ لُبنان في عمليةٍ أُطلِقَ عليها اسمُ (سلام الجَليلِ)، قالت إسرائيلُ: إنها تَهدِفُ لِقَطْعِ الطريقِ أمام صواريخ المقاومةِ الفلسطينية بجَنوب لُبنان. وفي 10/6/1982م وصَل الإسرائيليونُ إلى ضواحي بَيروت، واحتلُّوا ضواحي قصْرِ بعبدا يوم 12/6، وفي يوليو / تموز 1982م أحكمَتْ إسرائي"},{"id":5474,"era":"c15","t":"مَشروعُ برجينيف لِتَسوية النِّزاع بين الفِلَسطينين واليهودِ .","s":"هو مَشروعٌ يمثِّل التصوُّرَ السُّوفيتي لِتَسوية النِّزاع بين الفِلَسطينين واليهودِ، طرَحَه الرئيس يليونيد بريجينيف في 25 سبتمبر 1982، ولا يَختلِف عن مَشروع السلام العربيِّ كثيرًا، مع التركيزِ على حقِّ الشَّعب الفِلَسطيني في تَقرير مَصيره، وإقامةِ دولةٍ مُستقِلة في الضفةِ الغربيةِ وقِطاع غَزة، بما فيها القدسُ، وعلى إنهاء الحربِ وإحلالِ السلام بين الدُّول العربيةِ وإسرائيلَ، وعلى إيجادِ ضَماناتٍ دول"},{"id":5475,"era":"c15","t":"مُؤتمر القِمة العربي الثاني عشر (قِمة فاس) .","s":"شاركَتْ فيه جميعُ الدول العربيةِ باستثناء مِصرَ، وكانت أقصَر قِمةٍ عربية؛ فلم تَستغرِقْ أكثرَ مِن خمْسِ ساعاتٍ، رفَضَت خلالها سُوريَةُ ودُولُ جَبْهة المواجهةِ ما طُرح مِن أجْلِ حلِّ أزمة الشرق الأوسط، وأعلنت القِمةُ تَعليقَ أعمالِها على أن تُستأنَفَ في وقتٍ لاحقٍ."},{"id":5476,"era":"c15","t":"إقرارُ الكِنيست تطبيقَ القانونِ الإسرائيلي على هَضبة الجولان .","s":"أقرَّ الكنيستُ الإسرائيلي قانونَ تطبيقِ القانونِ الإسرائيلي على الجولانِ المحتلِّ، واعتبارِ سُكَّانه مواطنينَ إسرائيليِّينَ، وسُمِّي القانونُ آنذاكَ بـ(قانون الجولان)، الذي رفضَتْه الأُمَم المتحِدة، واعتبرتْه قانونًا غيرَ شرعيٍّ، وأصدَرَت قرارًا برقم (497) وتاريخ 17/12/1981، والذي يُدِين تطبيقَ القوانينِ الإسرائيلية على الجولانِ المحتلِّ، وعليه يُعتبَر القرارُ الإسرائيلي لاغيًا كأنْ لم يكُنْ."},{"id":5477,"era":"c15","t":"الاتِّحاد بين السِّنغال وغامبيا .","s":"أُعلِنَ في شوال 1401هـ / آب 1982م عن خُطة لاتِّحادٍ بين السِّنغال وغامبيا، وإقامةِ دَولة منهما أُطلِقَ عليها سنغامبيا، وظهَر الاتِّحادُ فِعليًّا في 7 ربيع الثاني 1402هـ / شباط 1982م، وعُقِدَ أولُ مجلسٍ لِمُناقشة سُبل التعاوُن بين البلدينِ مِن الناحيةِ السياسية والاقتصاديةِ ووَحدةِ النقْدِ، لكن كانت غامبيا ما تَزال مُتردِّدةً مِن تَحقيق الوَحدة فِعليًّا، وفي مُحرم 1410هـ / آب 1989م أعلَنَ رئيسُ الس"},{"id":5478,"era":"c15","t":"حسين محمد إرشاد يتولَّى رئاسةَ بنغلادش بانقلابٍ ضِد عبد الستار صايم .","s":"في بنغلادش قام رئيسُ هيئةِ أركان الجيشِ الفريق حسين محمد إرشاد في 29 جمادى الأولى 1402هـ / 24 آذار 1982م، بانقلابٍ (أبيض)، مُدَّعيًا أنَّ الفسادَ السياسيَّ وسُوء الإدارة الاقتصاديةِ أصبَحَ غيرَ مُحتمَلٍ، فأطاح بالرئيسِ عبد الستار محمد صايم، وتولَّى هو حُكْمَ الدولةِ، ولقَّب نفْسَه الرئيسَ الإداريَّ لقانون الأحكامِ العُرْفية، وفي 7 ربيع الأول 1404هـ / 11 ديسمبر 1083م أعلَنَ تنصيبَ نفْسِه رئيسًا."},{"id":5479,"era":"c15","t":"تولِّي الشيخِ جاد الحق علي جاد الحق مشيخةَ الجامع الأزهر .","s":"وُلِدَ في بطرة؛ قَريةٍ مِن قُرى مُحافظة الدَّقَهلية الخميس الموافِق (13 جمادى الآخرة سنة 1335 هـ = 5 إبريل 1917م)، وتُوفِّي عام 1996م، تلقَّى تعليمَه الأوليَّ في قَريتِه، فحفِظَ القرآنَ الكريم، وتعلَّم مبادئَ القِراءة والكتابةِ، ثم الْتحقَ بالمعهدِ الأحمديِّ بطنطا، وأنهى المرحلةَ الابتدائيةَ به، وانتقَل إلى المرحلة الثانويةِ، واستكْمَلها في القاهرةِ في مَعهدها الدِّيني بالدَّرَّاسة، وبعدَ اجتيازِه"},{"id":5480,"era":"c15","t":"المسجدُ الأقصى يتعرَّض لاعتداءاتٍ إسرائيلية .","s":"تعرَّض المسجدُ الأقصى المبارك لاعتداءٍ آثمٍ؛ حيث قام أحدُ الجنودِ الإسرائيليينَ -واسمه هاري غولدمان- باقتحامِ المسجد الأقصى وإطلاقِ النار بشكْلٍ عَشوائي على مَن في الحرمِ، ممَّا أدَّى إلى مَقتلِ مواطنين وجرْحِ أكثرَ مِن سِتِّين آخرينَ. وأثار هذا الحادثُ سخطَ المواطنين، وأدَّى إلى اضطراباتٍ عنيفةٍ في الضفة الغربية وغَزة، وردودَ فِعلٍ عالمية غاضبة ضِدَّ الاحتلال."},{"id":5481,"era":"c15","t":"تأْسيس الاتِّحاد الإسلاميِّ لِمُجاهدي أفغانستان .","s":"تمَّ تأسيسُ الاتِّحاد الإسلامي لِمُجاهدي أفغانستان مِن الفصائل المختلِفة التي تَعمل في مَيدانِ الجِهاد ضِدَّ الاتِّحاد السُّوفيتي، وتمَّ اختيارُ عبد رب الرسول سياف رئيسًا له."},{"id":5482,"era":"c15","t":"السُّعودية وقَطَر ولِيبيا والإماراتُ تَقطَع عَلاقاتِها الدُّبلوماسية مع زائير .","s":"قطعَت السُّعودية وقطَر ولِيبيا والإماراتُ عَلاقاتِها الدُّبلوماسيةَ مع دولةِ زائير (الكونغو الديمقراطية)؛ وذلك بعد أنْ أعادت زائير عَلاقاتِها مع إسرائيلَ في أيار 1982، وكانت إسرائيلُ -فضْلًا عن ذلك- قد نجحَتْ في ربط زائير بمعاهدةٍ عسكريةٍ تنصُّ على قيام إسرائيلَ بإعادة بِناء الجيش الزائيري، وإيفادِ مُستشارين عسْكريِّين إلى زائير؛ لِتَدريب سِلاح البحريةِ."},{"id":5483,"era":"c15","t":"وَفاة الملِكِ خالد بن عبد العزيز وتولِّي أخيه الملِكِ فَهدٍ .","s":"الملِكُ خالد بن عبد العزيز -رحمه الله- هو رابعُ مَن تولَّى ملِكَ المملكة العربية السُّعودية، بعْدَ أبيه الملِك عبد العزيز وأخوَيه سُعود وفَيصل، وقد تولَّى حُكمَ السُّعودية عقِب اغتيالِ أخيه فَيصل سنة 1395هـ - 1975م، وشهِدَ عهدُه ازدهارًا اقتصاديًّا كبيرًا للسُّعودية؛ بسَببِ ارتفاعِ أسعار النِّفط، وما صاحَب ذلك مِن انفتاحٍ على العالَم الخارجي بصورةٍ أكبرَ بكثيرٍ مِن السابق، وقد حاوَل الملِك خالدٌ ا"},{"id":5484,"era":"c15","t":"تعرُّضُ سفيرِ إسرائيل في لَندن لِمُحاولة اغتيالٍ .","s":"في عام 1982م وبعَد ظُهْر 4 حزيران، علا أزيزُ الطائرات الإسرائيليةِ، وارتفَعَ دُخَان الحرائقِ والدمارِ إثْرَ غاراتٍ عنيفةٍ مُتواصلةٍ على بيروتَ، بدأَت بتدميرِ \"المدينة الرياضية\"، وامتدَّت لِتَشملَ مناطقَ الفاكهاني، والجامعة العربية، ومُحيطَهما، غارات مُتتاليةٌ لم يَسبِقْ أن شهِدَ مِثلَها اللُّبنانيون، وساد الذُّعر العاصمةَ، ونزَح أهالي تلك المناطق، والمناطق القريبةِ والمحيطة بها باتِّجاه مناطقَ ظنّ"},{"id":5485,"era":"c15","t":"مؤتمرٍ وزراء دول عَدَمِ الانحيازِ لِبَحث عدوان إسرائيل على لُبنانَ .","s":"عُقِدَ في نيقوسيا مؤتمرٌ لِوُزراء خارجية دُول عَدَمِ الانحيازِ؛ وذلك لِبَحْث العُدوان الإسرائيليِّ على لُبنان، وطالَب المؤتمرُ بفرْضِ عُقوبات شاملةٍ وإلزاميةٍ ضِدَّ إسرائيل؛ لِعَدَمِ امتثالِها لقراراتِ الأمم المتحِدة بشأْن فِلَسطين، وطالَب أيضًا إسرائيلَ برفْعِ الحصارِ عن بَيروت الغربيةِ، مع تَشكيل مَجلِس الأمن قُوة مُؤقَّتة؛ لِحِفْظ السلامِ في لُبنان دونَ تأخيرٍ."},{"id":5486,"era":"c15","t":"تدخُّلٌ عسكريٌّ فرنسي في تشاد .","s":"تدخَّلت فرنسا عسكريًّا في تشاد؛ لِدَعمِ الرئيس حسين حبري -الذي استَولى على السُّلطة في 1982م- بطلَبٍ منه؛ وذلك في مُواجهة غوكوني عويدي، الذي تَدعُمه القوات اللِّيبية. وقد سبَقَ أن أرسلَتْ فَرنسا قواتٍ إلى تشاد للمرَّة الأولى في 1968م، بعدَ أنْ أثارت جَبهة التَّحرير الوطني (فرولينا) المعارِضة للرئيس تومبالباي، اضطراباتٍ في مَنطقة تيبستي."},{"id":5487,"era":"c15","t":"مَذبحة مُخيَّم صَبرا وشاتيلا .","s":"حصَلَت مذبحةٌ في مُخيَّم صبرا وشاتيلا للَّاجئين الفِلَسطينيِّين في لُبنان في شَهر سبتمبر 1982م، على يَدِ الميليشياتِ المارونيةِ أثناءَ الاحتلال الإسرائيلي لِبَيروت لبنان في خِضَمِّ الحرْب الأهلية اللُّبنانية، تحت قِيادة أيلي حبيقة، الذي أصبَح فيما بعْدُ عُضوًا في البرلمان اللُّبناني لمدَّةٍ طويلة، ووزيرًا عام 1990م، وأدَّت هذه المذبحةُ إلى قتْل ما يقرُبُ من 3500 من الرِّجال، والأطفالِ، والنساء، وا"},{"id":5488,"era":"c15","t":"مُؤتمر غيرُ العاديِّ (قمة فاس)، وإقرار مَشروع السلامِ مع إسرائيلَ .","s":"تغيَّب عن هذه القِمة (غير العادية) كلٌّ من مصرَ ولِيبيا، وشاركت فيها 19 دولةً عربيةً، اعترَفَت ضِمنيًّا -ولأوَّلِ مرَّةٍ- بحقِّ إسرائيلَ في الوُجود. وصدَر عنه بيانٌ خِتامي تضمَّن مجموعةً مِن القرارات؛ أهمُّها:- إقرارُ مَشروع السلامِ العربيِّ مع إسرائيلَ، وأهمُّ ما تضمَّنه: انسحابُ إسرائيلَ من جميع الأراضي العربيةِ التي احتلَّتها عام 1967م، وإزالةُ المستعمراتِ الإسرائيليةِ في الأراضي التي احتُلَّت "},{"id":5489,"era":"c15","t":"اغتيالُ الرئيس بشير الجميل في انفجارٍ دمَّر مقرَّ حِزب الكتائب اللُّبناني .","s":"وُلِدَ بَشير الجميل في بَيروت عام 1947م لِأُسرةٍ مِن ستةِ أبناء، كان هو أصغَرَهم. ووالده بيير الجميل هو مُؤسِّس ورئيسُ حِزب الكتائب اللُّبناني آنذاك. التحقَ عام 1962م بحِزْب الكتائبِ، وأصبح عضوًا في قسْم الطَّلَبة، ثم شارَكَ عام 1968م في مُؤتمرٍ طُلَّابي نظَّمَته جَريدةُ الشَّرقِ عقِبَ الأحداثِ التي جرَت في الجامعاتِ بين الطَّلبة اليساريينَ المؤيدينَ للفِلَسطينيين في لُبنان، والطَّلَبة اللُّبنانيي"},{"id":5490,"era":"c15","t":"اغتيالُ سعد صايل رئيس العملياتِ العسكرية لمنظَّمة التحريرِ .","s":"أبو الوليد سعد صايل هو عسكريٌّ فِلَسطيني، وُلِدَ في قرية كفر قليل (محافظة نابلس)، وتلقَّى دِراسته الابتدائيةَ والثانوية في مَدينة نابلس، والتحقَ بالكُلِّية العسكرية الأُرْدنية سَنة 1951م، وتخصَّص في الهندسة العسكريةِ، ثم أُرسِلَ في دوراتٍ عسكريةٍ إلى بريطانيا سنة 1954م (هندسة تَصميم الجُسور وتصنيفها)، وبريطانيا سنة 1958م، والولايات المتحِدة سنة 1960م (هندسة عَسْكرية متقدِّمة)، وعاد إلى الولايات ال"},{"id":5491,"era":"c15","t":"وفاةُ أحمد حسن البكر رئيس جُمهورية العراقِ .","s":"انضمَّ البكر إلى الأكاديميةِ العسكريةِ العراقية عامَ 1938م، بعدَ أن عمِلَ مُعلِّمًا لمدةِ 6 سنواتٍ، واشترَكَ البكر في بداياتِ حياتِه العسكريةِ في حركةِ رَشيد عالي الكيلاني ضِدَّ النُّفوذ البريطانيِّ في العراق عامَ 1941م، التي باءت بالفشَلِ، فدخَل على إثرِ ذلك السجنَ، وأُجبِرَ على التقاعدِ، ثم أُعيدَ إلى الوظيفةِ عامَ 1957م. وانضمَّ إلى تَنظيمِ الضُّباط الوطنيينَ الذي أطاح بالملَكِية في العراق عامَ"},{"id":5492,"era":"c15","t":"السُّعودية تَعتقِلُ حجَّاجًا إيرانيين تَظاهروا وأثاروا الشَّغَب في البلادِ .","s":"اعتقَلَت السُّلطات السُّعوديةُ 69 حاجًّا إيرانيًّا تَظاهروا ضِدَّ السُّلطات السُّعودية، وقاموا بالتَّنديدِ بالشَّيطانِ الأكبرِ: أمريكا وإسرائيل، كما يَزعُمون، وأثاروا الخوفَ والرُّعب والشَّغَبَ بين الحُجاجِ الآمنينَ."},{"id":5493,"era":"c15","t":"وَفاةُ العالِمِ الأزهري الشَّهيرِ في عِلْم القراءاتِ: عبد الفتاحِ القاضي .","s":"تُوفِّيَ الشيخُ عبدُ الفتاح بنُ عبدِ الغني بن محمد القاضي، المولودُ في دمنهور البحيرة بمصرَ في 14/10/1907م. وهو عالِمٌ مُبرَّزٌ في القِراءات وعُلومها، التحقَ بالمعهدِ الأزهريِّ بالإسكندرية بعدَ أن حفِظَ القرآنَ الكريم، وتدرَّجَ في التعليمِ حتى حصَل على شَهادة التخصُّص القديمِ (الدكتوراه حاليًّا) عامَ 34/1935م. تَتلمذَ على كِبار عُلماء عصْره بالإسكندرية والقاهرةِ؛ منهم الشيخُ محمد تاج الدينِ في الت"},{"id":5494,"era":"c15","t":"تَفجير السِّفارة الأمريكية في بَيروت .","s":"في 18 إبريل 1983 اقتَرَبت سيارةٌ مُفخَّخة مِن سِفارة الولايات المتحِدةِ في بَيروت، وحدَث انفجارٌ هائلٌ أدَّى إلى تدميرٍ كاملٍ للقِسم المركزي للبِناية، وتسبَّبَ الانفجارُ في سُقوط 60 قتيلًا؛ بينهم 17 أمريكيًّا، و100 جريح. وكانت السَّيارة المفخَّخةُ التي دمَّرت السفارة مجهَّزةً بحَوالي 180 كغم مِن المتفجِّرات، وكانت السيارةُ -حسَبَ تقاريرِ وكالةِ المخابرات الأمريكيةِ- قد تمَّت سَرِقتُها قبلَ عامٍ وا"},{"id":5495,"era":"c15","t":"تَفجُّر عَملية التمرُّدِ التي يَقودها أبو موسى داخَل حرَكةِ (فتح) .","s":"تفجَّرت عمليةُ التمرُّدِ التي يَقودها أبو موسى داخلَ حرَكة (فتح)، في شكْل صِدامٍ مسلَّح مع أنصار ياسر عرفات في مَدينة بعْلَبك بوادي البِقاع بلُبنانَ، وأدَّت حركةُ التمرُّد والانشقاقِ هذه إلى إحداثِ انهيارٍ للتَّيار التقدُّمي في داخل حرَكة (فتْح)."},{"id":5496,"era":"c15","t":"اندلاعُ الاشتباكات الطائفيةِ في جَبَل الشوف بعد انسحابِ الإسرائيليينَ .","s":"في أغسطس 1983م انسحَبَت إسرائيلُ مِن جَبَل الشوف بلبنان، مُزِيلةً الفاصلَ ما بين الدُّروز والنَّصارى، لِتَندلِعَ معاركُ عنيفةٌ ودامية بين الحِزب التقدُّمي الاشتراكيِّ، مَدْعومًا مِن بعضِ القُوى الفِلَسطينية في مُواجَهة القواتِ اللُّبنانية والجيش اللُّبناني، وارتفَعَت بسُرعةٍ وَتيرةُ المعاركِ على مختلَف الجَبَهات، لِتَرتفِعَ معها أعدادُ القتْلى بسُرعةٍ هائلةٍ؛ إذ كان يَسقط مئاتُ المقاتلينَ مِن الطر"},{"id":5497,"era":"c15","t":"تَطبيقُ الشريعةِ الإسلامية في السُّودان .","s":"بدَأ المسلمونَ في السُّودان يطالِبون بتَعديل الدُّستور، وتَقييد صلاحياتِ السُّلطات المطلَقة للرئيسِ، ثم بدَأَت المظاهراتُ سخطًا على غزْو الرُّوس لأفغانستانَ، وأخذَت المظاهراتُ تُنادي بتَطبيقِ الشريعة؛ إذ أيَّد ذلك قِيامُ الثَّورة الخُمينية في إيرانَ التي كانت تُعلِن تطبيقَ الشريعةِ في ظاهرِ الأمر، ثم زاد السَّخطُ بزِيارة الساداتِ للقُدس لِمُفاوضة اليهودِ، وازداد الإلحاحُ على تَطبيق الشريعةِ؛ لإنقا"},{"id":5498,"era":"c15","t":"تفجيرٍ في بيروت في مقرِّ قُوات المارينز الأمريكية ومَقرِّ سَرِية فرنسية .","s":"قامت مُنظَّمةُ الجِهاد الإسلاميِّ بتَفجير مَقرِّ قِيادة مُشاة البحريةِ الأمريكية، ومَقرِّ سِرَية فرنسية مِن المظلِّيين في بَيروت؛ وذلك إبَّانَ الحرْب الأهليةِ في لُبنان، وأسفَر التفجيرانِ عن مَقتلِ 239 أمريكيًّا و58 فرنسيًّا، وكان الفارقُ بين التفجيرينِ بِضعَ لَحظاتٍ، وأدَّى هذانِ التفجيرانِ إلى إصدار الرئيسِ الأمريكي رونالد ريغان قرارًا بسحْب المارينزِ مِن الأراضي اللُّبنانية إلى السُّفن الأمريكي"},{"id":5499,"era":"c15","t":"تأسيسُ جَمعية المُعجميةِ العربيةِ بتُونس .","s":"جَمعيةُ المُعجمية العربية: هي هيئةٌ عِلْميةٌ تأسَّست بتُونس عام 1983م، وتَهتمُّ بالبحثِ المُعجميِّ لِما يهمُّ العربيةَ، وقد اعتنَتْ خاصَّةً بالمُعجمِ التاريخيِّ، ونظَّمت لذلك نَدوةً عِلْمية دَعَت لها اللُّغويينَ العربَ. صدَرَت عن هذه الجَمعية مَجلَّة عِلميةٌ مُتخصِّصة تُسمى مَجلة \"المعجمية\". ترأَّسَ هذه الجمعيةَ الأستاذُ محمد رشاد الحمزاويُّ، ويَترأَّسُها منذ عامِ 1994م الأستاذُ إبراهيم بن مراد. و"},{"id":5500,"era":"c15","t":"استقلالُ بروناي .","s":"مَنحت بريطانيا الحُكم الذاتيَّ لسَلطنة بروناي في رمضان 1391هـ / تشرين الثاني 1971م، وفي ذي الحجَّة 1395هـ / ديسمبر 1975هـ أصدر مجلسُ الأُمَم المتَّحدة قرارًا دعا فيه بريطانيا للانسحاب من بروناي، وعودة المنفيِّينَ السياسيِّينَ، وإجراءِ انتخاباتٍ عامَّةٍ، وتمَّتِ المُفاوضةُ بين سَلطنة بروناي وبين بريطانيا عام 1398هـ / 1978م، وأعقبتْها تأكيداتٌ من إندونيسيا وماليزيا على احتِرام استِقلال سَلطنة بروناي"},{"id":5501,"era":"c15","t":"وفاةُ الزعيم الغِيني أحمد سيكوتوري .","s":"أحمد سيكوتوري هو أحدُ أبرز القادةِ الأفارقةِ المُناضِلينَ، ممَّن أظهر مُعاداتَهُ للاستعمار، وُلِدَ أحمد سيكوتوري في مِنطَقةِ فاراناه، فيما كان يُعرف بمِنطَقة النيجر الأعلى عام 1922م، لعائلةٍ تشتغلُ بالزراعة، وهو ينحدِرُ من قبيلةِ المالنكي التي ظلَّت تُقاوم الاستعمار الفرنسي بشراسةٍ لمدة ستَّةَ عشَرَ عامًا قبل نهايةِ القرن التاسعَ عشَرَ، وكان جدُّهُ أحدَ أشهَرِ زُعَماء هذه القبيلةِ ورجالاتِها الأقو"},{"id":5502,"era":"c15","t":"قيام جَبْهة الإنقاذ الوطني الليبي المُعارضةِ بعملية باب العزيزية .","s":"اقتحمتْ مجموعةٌ من مُقاتلي الإنقاذِ (الجَناح العَسْكري للجَبْهة الوطنيَّة لإنقاذِ ليبيا) مُعَسكَرَ باب العزيزيةِ في طرابلس، وقد اشتبكتْ هذه المجموعةُ مع قُوَّات ليبيَّةٍ وأجنبيةٍ تحرُسُ المُعَسكَرَ لفترةٍ تراوحتْ بين خَمسِ وسَبعِ ساعاتٍ استُخدمت فيها كافَّةُ الأسلحة، وقد قُتل جميعُ الذين اشتركوا في العملية من المُقاتِلينَ وعددُهم ثمانية، ولم يتمكَّنْ بعض الموجودين في المُعَسكَرِ من الفَرار عبر أحد"},{"id":5503,"era":"c15","t":"وفاةُ المُفكِّر والكاتب محمد عِزَّة دَروزة .","s":"مُحمَّد عِزَّة دَروزة مُفكِّر وكاتب مُسلِم، وُلِد في نابلس في 21 حُزَيران 1887م وتُوُفِّيَ في دِمَشقَ في 26 تموز 1984م. كان أديبًا، وصحفيًّا، ومترجمًا، ومُؤرخًا، ومُفسرًا للقُرآن. نشأ في أُسرة من عشيرةِ \"الفريحات\" التي كانت تسكُنُ شَرْق الأُردُنِّ، وانحدرت إلى فِلَسطينَ، واستوطنتْ نابلس. كان والِدُهُ يملِكُ محلًّا لتِجارة الأقمشةِ في سُوق خان التُّجَّار القديمِ الشهيرِ في المدينةِ القديمةِ في نابل"},{"id":5504,"era":"c15","t":"حِزبُ العُمَّالِ الكردستاني يبدأ حركة تمرد مسلحة لإنشاء دولة كردية .","s":"حِزْبُ العُمَّال الكُردستانيُّ هو حِزبٌ سياسيٌّ كُرديٌّ يساريٌّ مُسلَّحٌ، ذو توجُّهاتٍ قوميَّةٍ كُرديَّةٍ وماركسيَّةٍ - لِينينيَّةٍ، هدفُهُ إنشاءُ ما يُطلق عليه الحِزبُ دولةَ كُردستانَ المستقِلَّةِ. ويُعتبر الحِزبُ في قائمة المُنظَّماتِ الإرهابيَّةِ على لوائح الولايات المُتَّحدةِ، والمملكة المُتَّحِدة، والاتِّحادِ الأوروبيِّ، وتُركيا، وإيرانَ، وسُوريَة، وأُستراليا. تأسَّس في عام 1978م، وبدأ حركةَ "},{"id":5505,"era":"c15","t":"بدءُ انسحاب القُوَّات الليبية والفرنسية من تشاد .","s":"بدأ النظام السياسيُّ في ليبيا التدخُّلَ في تشاد في 1977م، حيث قام بتمويلِ حَرَكة فلورينا بقيادة كوكني وداي ومساعدةِ حسين حبري ضدَّ الحكومة التشادية في ذلك الوقت، وبعد وُصول جبهة فلورينا للحُكم في تشاد حدث انفصالٌ بين كوكني وداي وحسين حبري، وانحاز النظام السياسيُّ في ليبيا إلى كوكني وداي ضدَّ حسين حبري، وكانت هذه المجموعةُ تُطالب بشريط أوزو الذي كان محلَّ خلافٍ بين ليبيا وتشاد في السابق، وقد فُصل ف"},{"id":5506,"era":"c15","t":"وفاةُ الرئيس مُحمَّد نجيب أول رئيس للجُمهورية المصرية .","s":"مُحمَّد نجيب يوسف نجيب قُطب القشلانُ سياسيٌّ وعَسكريٌّ مِصريٌّ، وُلد بالخُرطوم، والتحَقَ بالكُليَّة الحربيَّةِ في مِصرَ في إبريل عام 1917م وتخرَّج فيها في 23 يناير 1918م، ثم سافَرَ إلى السُّودان في 19 فبراير 1918م، والتحَقَ بذات الكَتيبةِ المِصريَّةِ التي كان يعملُ بها والدُهُ؛ ليبدأ حياتَهُ كضابطٍ في الجيش المِصريِّ، حصل على شَهادةِ الكفاءةِ، ودخَلَ مدرسةَ البوليسِ لمُدَّةِ شهرَينِ، واحتكَّ بمُخت"},{"id":5507,"era":"c15","t":"انسحابُ القُوَّات الإسرائيليَّة من المناطق اللبنانية .","s":"في السَّادِس من حُزَيران سنة 1982م اجتاحت إسرائيلُ صَيْدا بقُوَّاتها البَريَّةِ والجَويَّةِ والبَحْريَّةِ بوحشيَّةٍ وحِقدٍ، فدمَّرت بُيوتًا، وقتلت الأبرياءَ، وروَّعت السُّكَّان، وعطَّلتِ الكثيرَ من مَرافِق الحياةِ. وبعد أن سيطرت على أحياءِ صَيْدا والمِنطَقةِ الشرقيَّةِ أخذت تُمارِس الإرهابَ بقَصدِ إذْلالِ الشَّعبِ وتَطبيعِهِ. وكانت تدعو السُّكَّان بواسطة مُكبِّرات الصَّوتِ إلى التجمُّع في الساحاتِ"},{"id":5508,"era":"c15","t":"انقلاب عسكريٍّ على الرئيس الموريتاني محمد خونا .","s":"لمَّا ترأَّسَ مُحمَّد خُونا ولد هيداله موريتانيا حاوَلَ تصحيحَ أوضاع البِلادِ الاقتصاديَّةِ التي كانت مُتردِّيةً، وكان مركزيًّا في حُكمِهِ، فعمَّ التذمُّرُ بين الناس؛ مدنيِّينَ وعَسكريِّينَ، فقام العقيدُ مُعاوية ولد سيدي طايع رئيسُ الوُزراءِ الأسبَقِ بانقلابٍ عسكريٍّ في 19 ربيع الأول 1405هـ / 12 ديسمبر 1984م فأزاح رئيسَ الجُمهوريَّةِ اللواءَ مُحمَّد خونا ولد هيداله عن مناصِبِهِ كلِّها، وتسلَّمَ مك"},{"id":5509,"era":"c15","t":"انقلابٌ عسكريٌّ في السُّودان، واختيارُ حُكومةِ الصادق المهدي .","s":"في 16 رجب 1405هـ / 6 نيسان 1985م قام وزيرُ الدِّفاع السُّوداني عبد الرحمن سِوارُ الذَّهَب مع عددٍ من كِبار ضُبَّاطِ الجَيشِ بانقلابٍ على الحكومةِ، وشكَّلوا المجلسَ العسكريَّ الأعلى الذي تحمَّلَ مسؤوليَّةَ تسييرِ الحُكمِ مُعلِنًا من البدايةِ أنه لا يُريدُ الاستِئثارَ بالسُّلطةِ، وإنَّما هو مرحلةٌ انتقاليَّةٌ مُدَّتها لا تزيدُ على سنةٍ إلى حين تسليمِها إلى حكومةٍ مَدَنيَّةٍ، وجرتِ الانتخاباتُ بعد سن"},{"id":5510,"era":"c15","t":"وفاةُ \"أنور خوجا\" رئيسُ دولة ألبانيا .","s":"وُلِد أنور خوجا في بلدةِ \"أرجيرو كاسترو\" سنة (1326هـ = 1908م)، ونشأ في وسطِ عائلةٍ مُسلمةٍ، اشتغلت بالتِّجارةِ، وعُرفت بالثَّراءِ، وتلقَّى دراستَهُ الأولى في مدرسةٍ فَرَنسيَّةٍ في \"كوريتسا\"، وهناك انخرط في صُفوفِ الحِزبِ الشُّيوعي الفَرَنسيِّ، وبعد أن أنْهى دراستَهُ سافَرَ إلى \"بلجيكا\"؛ حيث عَمِلَ سكرتيرًا للسفارة الألبانية، ثم عاد إلى بلادِهِ سنة (1355هـ = 1936م)، واشتغَلَ بالتَّدريس. ولمَّا تعرّ"},{"id":5511,"era":"c15","t":"مُحاولة اغتيال أميرِ الكُويت جابر الصَّباح .","s":"في صَباح 25 مايو 1985، كان أميرُ الكُويتِ الشيخُ جابر الصَّباح في طريقِهِ إلى الدِّيوانِ الأميريِّ في قَصرِ السَّيفِ، فقد كان مُعتادًا أن يصلَ إلى مَكتبِهِ في الثامنةِ صباحًا. وقبلَ هذا الوقتِ بلحظاتٍ دوَّى انفجارٌ هائلٌ نجَمَ عن تفجيرِ سيَّارةٍ مُفخَّخةٍ، فأُصيبَ الشَّيخ جابرٌ بجُروحٍ ونُقِلَ إلى المُستشفى الأميريِّ."},{"id":5512,"era":"c15","t":"مُؤتَمَرُ القِمَّة العربيُّ غيرُ العادي الثاني (مُؤتَمَرُ الدار البَيْضاء) .","s":"انعقدَتْ قمَّةُ الدار البَيْضاءِ بناءً على دَعْوةٍ من الحَسَنِ الثاني مَلِك المملكةِ المغربيَّةِ. وصدَرَ عن المُؤتَمَرِ بيانٌ ختاميٌّ تضمَّنَ مجموعةً من القراراتِ أهمُّها:- تأليفُ لَجنَتَينِ لتنقيةِ الأجواءِ العربيَّةِ، وحلِّ الخلافاتِ بين الأشِقَّاءِ العرب.- الاستنكارُ والأسَفُ الشديدُ لإصرار إيرانَ على مُواصلةِ الحربِ، وإعلانُ المؤتمر تعبئةَ جميع الجُهودِ لِوَضعِ حدٍّ سريعٍ للقتالِ. - التَّنديد "},{"id":5513,"era":"c15","t":"حِصارُ القُوَّات السُّورية مدينةَ طرابلس في لبنان .","s":"بالتَّعاوُنِ مع مليشياتِ الحيِّ النُّصَيريِّ في بعل محسن في طرابلس، أقدمتِ القُوَّاتُ السُّوريَّةُ على حِصارِ ودكِّ مدينةِ طرابلس عاصمةِ أهل السُّنَّة في شمال لبنان. وكانت قد ارتكبتْ مَجزرةً في مُخيَّماتِ بيروت قبل ذلك بأُسبوعٍ، وعلى مَدارِ 20 يومًا ذكرتْ وِكالاتُ الأنباءِ: أنَّ أكثَرَ من مِليونِ صاروخٍ وقذيفةٍ دمَّرت أكثَرَ من نِصف مباني المدينةِ وجعلتْها معزولةً عن العالَمِ، وساهمتِ القُوَّاتُ ا"},{"id":5514,"era":"c15","t":"هُجومٌ أمريكيٌّ على القواعد الليبيَّةِ  .","s":"قامتِ الولايات المُتَّحِدة بتاريخ 24 و25 / 3 / 1986م بشنِّ عُدوان بَحْري وجَويٍّ شاركت فيه ثلاثُ حاملاتٍ للطائرات على أهدافٍ مَدَنيَّةٍ وعسكريَّةٍ بخليجِ سِرتٍ، وأغرقت عددًا من الزَّوارقِ الليبيَّةِ، ولم تقُمِ البحرية الأمريكية بإنقاذ طاقَمِ إحدى السُّفُن الليبية من الغرق. فشنَّتِ الولايات المتحدة الأمريكية بتاريخ 15 / 4 / 1986م هجومًا جويًّا واسع النطاق على مدينتَيْ طرابلس وبنغازي راح ضحيَّتَه ال"},{"id":5515,"era":"c15","t":"مُؤتَمَر ليبيا لِمُناهَضةِ الإمبرياليَّةِ والصُّهيونيَّة والفاشيَّة .","s":"عُقِد في طرابلس المؤتمرُ الثاني لِمُناهضةِ الإمبرياليَّة والصُّهيونيَّة والعُنصرية والفاشية في الفترة من 15 وحتى 29 مارس، وضمَّ المؤتمرُ وفودًا تُمثِّل هُنود أمريكا الشماليَّة، والأقليَّة الزنجيَّة المسلمة في الولايات المُتَّحِدة، والمليشياتِ المعارضةَ للتنظيم والحُكم في أمريكا اللاتينيَّةِ، ومُمثِّلينَ للحَرَكاتِ الكُردية الانفصاليَّةِ، ومُسلمي الفلبين، وحركاتِ الاستقلال في المُستَعمَراتِ الفرنسي"},{"id":5516,"era":"c15","t":"نجيبُ الله مُحمَّد يترأَّسُ أفغانستانَ بعد هَرَب الرئيس بابرك كارمل .","s":"كان نجيبُ الله مُحمَّد رئيسُ المخابرات الأفغانية (خاد) في عهد الرئيس بابرك كارمل صاحبَ أطماعٍ، ويُجيد المناورة والظُّهور بمظهر المسالمة، ومحبَّة الوصول إلى نتيجةٍ مع المحاور كلها، وفي 25 شعبان نصَّب نفسه رئيسًا للدولة الأفغانية بمُساعدة سلطان علي كشتمند على حين فرَّ سَلَفُهُ بابرك كارمل إلى السفارة الصينية، ومنها إلى الروسية ثم خرج بتدبيرٍ منهم إلى طشقند، ثم إلى موسكو، حيث عاش هناك."},{"id":5517,"era":"c15","t":"الجماعاتُ الإسلاميَّة في إسبانيا تُؤسِّس حِزبَ تحريرِ الأندلُس .","s":"أسَّست الجماعات الإسلاميَّة في إسبانيا حزبًا سياسيًّا أطلقت عليه اسمَ (تحرير الأندلس)؛ وذلك للمُطالبة باستقلال إقليم الأندلس، وإنهاءِ التواجُد الأجنبي، وخاصَّة الأمريكي من الإقليم، وتوطيدِ الروابط مع العالمَينِ العربي والإسلامي."},{"id":5518,"era":"c15","t":"المَلِك فهدِ يستبدل لَقَب صاحب الجلالة بلقب خادِمِ الحرمَينِ الشَّريفَينِ .","s":"أعلَنَ الملك فهد بن عبد العزيز رحمه الله استبدالَ لَقَب صاحب الجلالة ليكونَ اللَّقَب الرسميُّ لملك المملكة العربية السعودية هو: خادِمُ الحرمَينِ الشَّريفَينِ."},{"id":5519,"era":"c15","t":"كشفُ فضيحةِ \"إيران غيت\" بيع الأسلحة سراً إلى إيران .","s":"في مُخالفةٍ للقانون باعتِ الولايات المتحدة سرًّا أسلحةً إلى إيران. وفي إطار هذه الفضيحةِ، حُكم على اللفتنانت كولونيل أوليفر نورث في 6 تموز / يوليه 1989م بالسجن ثلاثة أعوام مع وقف التنفيذ، وغرامة قدرُها ألفُ دولارٍ، وعلى الأدميرال جون بوينديكستر بالسجن ستة أعوام في 5 مارس 1990م، وبُرِّئ وزير الدفاع كاسبار واينبرغر وكل الـ 150 المتهمين الآخرين."},{"id":5520,"era":"c15","t":"مُؤتمرُ القِمَّة الإسلاميُّ الخامسُ (قمة الكويت) .","s":"عقدُ مؤتمر القمة الإسلامي الخامس في (دولة الكويت) في الفترة من 26- 29 جُمادى الأولى 1407هـ، (الموافق 26- 29 ينايــر 1987م)، وقد صدر عنه عدَّة قرارات بشأن سَير عمل اللَّجنة الدائمة للتَّعاوُن الاقتصادي والتجاري، وبشأنِ اللَّجْنة الدائمة للتَّعاوُن العِلمي والتكنولوجي، وبشأن تنفيذ خُطَّة العمل لِتَعزيز التعاوُن الاقتصادي بين الدُّوَل الأعضاء في منظمة المؤتمر الإسلامي، وبشأن إقامةِ نظام أطول من أجل ت"},{"id":5521,"era":"c15","t":"استعادة الجيش التشادي مِنطَقة \"وادي دوم\" وانتصاره على الجيش الليبي .","s":"أعاد الجيشُ التشاديُّ سيطرتَه على مِنطَقة \"وادي دوم\" شمال تشاد بمحاداة الحدود الليبية وذلك بعد انتصاره على الجيش الليبي أثناء الحَرب التشادية - الليبية التي نشبت عام 1973م حول إقليم \"أوزو\" المُتنازَع عليه بين البلدينِ. وتبلغ مِساحة هذا الإقليم 14 ألف كيلو متر، وقد انسحبت ليبيا من \"أوزو\" في فبراير 1994م بعد حُكم محكمة العدل الدولية بأحقيَّة تشاد في الإقليم."},{"id":5522,"era":"c15","t":"اغتيالُ الشَّيخ إحسان إلهي ظهير .","s":"الشَّيخ إحسان إلهي ظهير عالِمٌ باكستانيٌّ، حمل لواءَ الحَرْب على أصحابِ الفِرَق الضالَّة، وبيَّنَ مَدى ما هُم فيه من انحرافٍ عن سبيلِ الله تعالى، وحيادٍ عن سُنَّة نبيه صلى الله عليه وسلم.وُلد في \"سيالكوت\"  شمال شرق البنجاب بباكستان عام 1363هـ من أُسرةٍ تُعرف بالانتماء إلى أهل الحديث، ولمَّا بلغ التاسعة كان قد حفظ القُرآن كاملًا. وقد أكمل دراستَه الابتدائية في المدارس العادية، وفي الوقت نفسه كان يخ"},{"id":5523,"era":"c15","t":"اغتيالُ رشيد كرامي رئيسِ وُزراء لبنان .","s":"رشيد عبد الحميد كرامي سياسيٌّ لبنانيٌّ، شغل مَنصِب رئيسِ الوزراء ثمانِ مرَّات، أوَّلُها بين سبتمبر 1955 ومارس 1956 وآخرُها بين إبريل 1984 إلى وفاته في يونيو 1987م. ينتمي رشيد كرامي إلى عائلة سياسيَّة عريقةٍ؛ إذ شغل والدُه وأخوه عمر مَنصِب رئيس الوزراء. وُلد رشيد كرامي في بلدة بالقُرب من طرابلس في لبنان، في عائلة من أهمِّ العائلات السياسية اللبنانيَّة. كان والدُه عبد الحميد كرامي رئيسًا للوزراء لأش"},{"id":5524,"era":"c15","t":"محاولة انقلاب في إمارة الشارقة للاطاحة بالشيخ سُلطان القاسمي .","s":"استولى الشَّيخ عبد العزيز بن محمد القاسمي على السُّلطة في إمارة الشارقة في انقلابٍ سِلميٍّ أطاح خلاله بشقيقه الشَّيخ سُلطان القاسمي."},{"id":5525,"era":"c15","t":"تظاهُرُ الحُجَّاج الإيرانيين، وإثارةُ الشَّغَب في مكة المُكرَّمة في مَوسِم الحج .","s":"في صَباح يوم الجُمُعة في اليوم السادس من شهر ذي الحجَّة عام 1407هـ، والحجيجُ على وَشكِ التأهُّب للرحيل إلى المشاعر المُقدَّسة، واستكمال مَناسِك الحج، وفي شمال مكَّة في مِنطَقة الحجون والمعلَّاة، على مَقرُبة من شِعب بني عامر الشَّهير، قام الحُجَّاج الإيرانيون بإثارة الشَّغَب، وترديد شِعاراتٍ مُستَنكرةٍ لا تليقُ بمَوسِم الحج مِثلَ: (لبَّيك يا خُميني، والموتُ لأمريكا)، وقد حصلت مُواجَهاتٌ بين المُتظا"},{"id":5526,"era":"c15","t":"إعلانُ أثيوبيا تأسيس جُمهوريتها .","s":"بعد أن أُعلنت إثيوبيا دولةً اشتراكَّية. ومات هيلاسيلاسي في آب 1975م. وتعهَّدت الطُّغمة العسكريَّة الحاكمة بإقامة دولة الحزب الواحد، ونفَّذت برنامجًا ناجحًا للإصلاح الزراعي، وتمَّ قمع المعارضة بعُنف، والحدُّ من نُفوذ الكنيسة القبطية الملكية في 1975م. وفي 1977م قُتل تفري بنتي الحاكم السابق، وحلَّ محلَّه العقيد منجستو هيلا مريام، وكانتِ المُدَّة من 1977م إلى 1979م هي فترة الإرهاب الأحمر، حيث قتَلَ نظ"},{"id":5527,"era":"c15","t":"انقطاعُ العَلاقات السُّعودية الإيرانية .","s":"ساءتِ العَلاقات السُّعودية الإيرانية منذُ قيام الثورة الخمينية، وإعلانِ الجُمهورية الإسلامية المزعومة في إيران تصديرَ الثورة، والتدخُّلَ في الشؤون الداخليَّة لبعض الدُّوَل، ودعمَ الطوائف الشيعية فيها، كما قامت إيران بإثارة القلاقل والفوضى في مواسم الحج، والتي منها أحداثُ مكَّة عام 1407هـ التي خرج الحُجَّاج الإيرانيون فيها بمُظاهراتٍ مُؤيِّدة للثورة الإسلامية؛ مُستغِلَّة المواسم الدينية لمصالحها ال"},{"id":5528,"era":"c15","t":"مُؤتمرُ القمةِ العربيُّ غير العادي الثالث (مُؤتمَرُ عمان) .","s":"قِمَّة عمان في 8 نوفمبر/ تشرين الثاني 1987، شاركت فيها عِشرون دولةً عربيَّةً، ومُنظَّمة التحرير الفلسطينية، صدر عنه بيانٌ خِتاميٌّ، ومجموعة من القرارات أهمُّها:- إدانةُ إيران لاحتلالها جُزءًا من الأراضي العراقية، والتضامُن مع العراق.- تضامُن المؤتمر مع السُّعودية والكويت، والتنديدُ بالأحداث التي اقترفها الإيرانيُّون في المسجد الحرام بمكَّة المُكرَّمة.- التمسُّك باستِرجاع كافَّة الأراضي العربية الم"},{"id":5529,"era":"c15","t":"الرئيس التُّونسيُّ الحبيبُ بورقيبة يُعيِّن زين العابدين بن علي رئيسًا للوزراء .","s":"في سنة 1985م جرى تعيينُ زين العابدين وزيرَ دولةٍ للأمن في مكتب رئيس الوزراء محمد مزالي، وفي سنة 1986م عُيِّن وزيًرا للداخلية، وظلَّ في منصبه هذا حتى تولَّى رئاسة الوزارة، فجمع بين منصب الوزير الأول، ووزير الحكومة، فضلًا عن تولِّيه الأمانة العامة للحزب الاشتراكي الدُّستوري، الحِزب الحاكم. وزينُ العابدين بن علي رجُلٌ عسكريٌّ اصطفاه بورقيبة منذُ سنواتٍ؛ ليكون قبضتَه الحديديَّة في مُواجهة خُصومه والأز"},{"id":5530,"era":"c15","t":"اندلاعُ الانتفاضةِ الفِلَسطينيَّة الأُولى .","s":"يُعتبر عامُ 1987م هو عامُ بَدءِ الانتفاضة الفِلَسطينيَّةِ الأُولى، حيث بدأت في الضفَّة الغربية، وقِطاع غزَّة. وأعلَنَ يومَها عرفاتٌ ارتباطَه بالانتفاضة."},{"id":5531,"era":"c15","t":"زينُ العابدين بن علي يُنحِّي الرئيسَ التونسي بورقيبة، ويتولَّى الرئاسة .","s":"أخذت أوضاعُ الرئيس التُّونسيُّ الحبيب بورقيبة تزداد سُوءًا جِسميًّا ونفسيًّا، حتى أثَّر ذلك على قراراته الرئاسية، وتقدَّمت به السِّنُّ حتى فقد الرصانة في تسيير الحُكم كما فقَدَ المنطقَ، وأخذ تأثيرُ الحاشية يَظهر على القرارات السياسيَّة، فقام في 16 ربيع الأول 1408هـ / 7 تشرين الثاني 1987م الوزيرُ الأوَّل زين العابدين بن علي بتنحيةِ الرئيس الحبيب بورقيبة وتسلَّم السُّلطة، وأخذ بإزالة العَهدِ الماضي،"},{"id":5532,"era":"c15","t":"وفاةُ اللُّغويِّ العراقيِّ أحمد عبد الستار الجواري .","s":"تُوُفِّيَ اللُّغوي العراقيُّ أحمد عبد الستار الجواري. وقد وُلِد في الكَرْخ ببغداد، وحصل من جامعةِ القاهرة على الدُّكتوراه سنة 1953م، ثم عاد إلى بغدادَ للتَّدريس في دار المُعلِّمينَ العالية. وانتُخب نقيبًا للمُعلِّميَن ثم رئيسًا لاتحاد المُعلِّمينَ العرب سنة 1969م، ثم تولَّى وزارة التربية سنة 1963م، ووزارة شُؤون رئاسة الجمهورية سنة 1970م، وحضر كثيرًا من المؤتمراتِ، وكان عضوًا عاملًا في المجامع اللغ"},{"id":5533,"era":"c15","t":"خروجُ الاتحاد السُّوفييتي مُنهزِمًا من أفغانستان .","s":"ارتكب الرُّوسُ فظائعَ وجرائمَ في حقِّ الشعب الأفغاني المسلم، أدَّت إلى مقتل أكثَرَ من مِليون مُسلِمٍ، وتشريدِ حوالي خمسة ملايين آخرين، واستخدم الرُّوسُ أحدث ما في ترسانتِهم العسكريَّةِ من أسلحةٍ فتَّاكة ومُحرَّمة دوليًّا، غير أنها لم توفِّر لهم البقاء الآمن في أفغانستان، حيث شنَّ المجاهدون الأفغانُ حربًا شرسةً ضد الروس، أدَّت إلى استنزافٍ دائمٍ لقُوَّاتهم، وخسر الروس حوالي أكثر من (13) ألفَ قتيلٍ "},{"id":5534,"era":"c15","t":"عبده ضُيوف رئيسًا للسنغال مرَّة أخرى .","s":"في جُمادى الآخرة بدأتِ الانتخابات الرئاسية في السنغال، وأخذت الصراعات تظهر في بعض المناطق بين رجال الأمن ورجال الأحزاب المُعارِضة، ثم أُعلنت النتائج في رجب من العام نفسه، فظهر أن رئيس الجُمهوريَّة عبده ضيوف قد حصل على 73.2% من الأصوات، وحصل حزبه الحاكم حزبُ التجمُّع الديمقراطي السنغالي على أكثر المقاعد."},{"id":5535,"era":"c15","t":"قتالُ القُوَّات العراقية للأكراد أثناءَ الحَربِ الإيرانية (حادثة حَلبَجة) .","s":"دخلتِ العراق في حربٍ مع إيران، ولكن لم تكن هي الجبهة الوحيدة التي يُقاتل عليها العراقيُّون في ذلك الوقت، فقد كانت مُشكلة الأكراد ما تزال قائمةً، ولما كانت العراق لا تستطيع أن تُقاتل على جبهتينِ معًا، لجأت إلى المباحثات مع جلال الطالباني رئيس حزب الاتحاد الوطني الكردي، ووقفِ القتال، فتمَّ التفاهم معه في ربيع الأول 1404هـ / ديسمبر 1983م على إطلاقِ تسعة وأربعين سجينًا سياسيًّا، وعودةِ ثمانية آلافِ عا"},{"id":5536,"era":"c15","t":"اتفاقيَّةُ جنيف بين باكستان وأفغانستان .","s":"كانت باكستانُ مأوى للَّاجئينَ الأفغانِ، وكذلك كانت محضنًا للمجاهدين، وكانت روسيا تتَّهِم باكستان بإثارة الأفغانِ على نِظام كابل، وبدأتِ المحادثات تجري في جنيف بين باكستان وبين نظام أفغانستان الخاضِع للرُّوس في 28 رمضان 1402هـ / 19 تموز 1982م، واستمرَّت حتى تمَّ التوقيع على الاتفاقية بين الطرفينِ في 27 شعبان 1408هـ / 14 نيسان 1988م، وكانت حول مبادئ العلاقات، واحترام السيادة والسلامة الإقليميَّة، وع"},{"id":5537,"era":"c15","t":"وفاةُ عبد السلام هارون شيخُ المُحقِّقينَ .","s":"عبد السلام مُحمَّد هارون بن عبد الرزاق، وُلِد في مدينة الإسكندرية في 25 من ذي الحجَّة 1326هـ ونشأ في بيتٍ كريمٍ من بُيوت العِلم، فجدُّه عضوُ جماعة كبار العُلَماء، وأبوه كان يتولَّى عند وفاته مَنصِب رئيس التفتيش الشَّرعي في وزارة الحقَّانيَّة (العدل)، أما جدُّه لأُمِّهِ فهو الشيخ محمود بن رضوان الجزيري عضوُ المحكمة العُليا. حَفِظ عبد السلام القُرآنَ الكريمَ، وتعلَّم مبادئ القراءة والكتابة، والتحق ب"},{"id":5538,"era":"c15","t":"اغتيالُ خليل الوزير (أبو جهاد) نائبِ القائد العامِّ لقُوَّات الثَّورة الفِلَسطينيَّةِ .","s":"خليل إبراهيم محمود الوزير (1935 - 16 إبريل 1988م) والمعروفُ بأبي جهاد. وُلِد في بلدة الرَّمْلة بفلسطين، وغادرها إلى غزَّة إثْر حرب 1948م مع أفرادِ عائلته. درس في جامعة الإسكندرية، ثم انتقل إلى السُّعودية، فأقام فيها أقلَّ من عامٍ، وبعدها توجَّه إلى الكويت، وظلَّ بها حتى عام 1963م. وهناك تعرَّف على ياسر عرفاتٍ، وشارك معه في تأسيس حركة فتح. في عام 1963م غادر الكويت إلى الجزائر حيث سمحتِ السُّلطات ال"},{"id":5539,"era":"c15","t":"القُوَّات العراقيَّة تُحرر شِبه جزيرة الفاو من القُوَّات الإيرانيَّة .","s":"معركةُ تحرير الفاو هي عمليَّة عسكريَّة نفَّذها الجيشُ العراقي في 17 إبريل / نيسان 1988 خلال حرب الخليج الأولى؛ لإخراج الجيشِ الإيرانيِّ من شِبه جزيرة الفاو بعد احتلالٍ دام عامينِ. شملت العمليَّةُ العسكريَّةُ التي نفَّذها الجيش العراقي قبل شُروق شمسِ يوم 17 إبريل 3 مراحلَ، استطاعتِ القُوَّات العِراقيَّةُ من خلالها تحريرَ كاملِ شِبه جزيرة الفاو في 35 ساعةً، وتكبيدَ القُوَّة الإيرانية خسائرَ كبيرةً م"},{"id":5540,"era":"c15","t":"مُؤتمرُ القِمَّة العربيُّ غيرُ العادي الرابعُ (قِمَّة الجزائر) .","s":"قِمَّة الجزائر من 7 - 9 حُزيران 1988م مُبادرة من الرئيس الجزائري الشاذلي بن جديد طالبت هذه القِمَّة (غيرُ العادية) بعقدِ مُؤتمرٍ دوليٍّ حولَ الشَّرق الأوسط بمُشاركة مُنظَّمة التَّحْرير الفِلَسطينيَّةِ، وكرَّرت دَعْمها لحقِّ الشعب الفلسطيني في تقريرِ مصيرِهِ. وصدَرَ عن المؤتمر بيانٌ ختاميٌّ، ومن قراراتِهِ:- دعمُ الانتفاضة الشَّعبيَّة الفِلَسطينيَّةِ، وتعزيزُ فعاليَّتِها وضمانُ استمراريَّتِها.- المُ"},{"id":5541,"era":"c15","t":"اضطراباتٌ في (كوسوفو-كوسوفا) إثرَ ضمِّ هذا الإقليم إلى الصِّرب .","s":"بدأت مُشكلة إقليم (كوسوفو-كوسوفا) في 1989م بإلغاء الحُكم الذاتي الذي كان يَحظى به الإقليمُ في الوقتِ الذي كانت فيه الغالبية الألبانية الشابَّة تُطالب بتوسيع الحُكم الذاتي حتى تتحوَّل كوسوفو إلى جمهوريةٍ مُتساويةٍ مع بقيَّة الجُمهوريات. فقد كانت كوسوفو ولايةً عُثمانيَّةً لها كِيان إداريٌّ وسياسيٌّ؛ مما مهَّد إلى دخول الألبان في صِراع مُسلَّح مع الحُكم العثماني. ونتيجةً لإعلان الدُّوَل البَلقانيَّة "},{"id":5542,"era":"c15","t":"هِجرةُ اليهود السُّوفيت إلى إسرائيل .","s":"مع انهيار الاتِّحادِ السُّوفييتي السابق بدايةَ عام 1990م انتهزتِ المُنظَّمة الصُّهيونيَّة العالميَّة، والوكالة اليهودية الفُرصةَ لتحشيدِ قوافِلِ الهجرة الاستيطانيَّة التوسُّعيَّة اليهوديَّة الصُّهيونية إلى فلسطين. وبدأت أرقام هِجرة اليهود السُّوفييت تتراكَمُ باتجاه فلسطين المُحتلَّة، وقد وصَلَ خلال الفترة (1990-2000م) نحو مليون يهوديٍّ، وساهمت الهجرةُ بأكثر من (67%) من إجمالي الزيادة السُّكانيَّة "},{"id":5543,"era":"c15","t":"الإعلانُ عن بنجلاديش جُمهوريَّةً إسلاميَّةً .","s":"كانت بنغلاديش جُزءًا من الهند في ظِلِّ الإسلامِ الذي وصَلَ إلى تلك المِنطَقةِ في القرن العاشر الميلادي. وفي النصف الثاني من القرن الثامنَ عشَرَ، احتلَّ المستعمِرُ البريطانيُّ القارة الهنديَّةَ، ومن ضِمنها بنغلاديشُ وباكستانُ وجامو وكشمير تحت نير الإمبراطوريَّة الاستعماريَّة البريطانيَّة في جنوب آسيا. ناضلتِ (الرابطة الإسلاميَّة) التي ضمَّتِ المسلمينَ في القارة الهنديَّةِ تحت راية الكِفاح ضدَّ الاس"},{"id":5544,"era":"c15","t":"اغتيالُ الرئيس الباكستانيِّ ضياء الحق، وترأس غلام إسحاق خان .","s":"في باكستان، سار ضياءُ الحق في سياستِهِ الأوَّليَّةِ باتجاهينِ يكادانِ يكونانِ متناقضينِ: اتجاه بالتقرُّب إلى أمريكا، واتجاه إسلاميٌّ، فدعَّم المجاهدين الأفغانَ، وهذا ما كانت أمريكا راضيةً عنه ثأرًا لها من روسيا التي دعَّمت الفيتناميين ضِدَّها، ثم إنَّ ضياء الحق في أواخر أيَّامه بدَت رغبتُه في تطبيق الشريعة، حيث أخذ يُصرِّح مُتسائِلًا: بماذا يُجيب اللهَ يوم القيامة، إذا سأله عن عدم تطبيقه للشريعة، "},{"id":5545,"era":"c15","t":"مظاهراتٌ كُبْرى ضمَّت الملايين في الجزائر ضدَّ النظام الحاكم .","s":"كانت الجزائر ولا زالت متأثِّرةً بالاستعمار، ولم تكُنْ فيها الحرية الكافية؛ ليظهَر الشعب رجالًا ونساءً بالمظاهر الإسلامية، فانطلقت مظاهراتٌ كُبْرى مطالِبةً بالحريَّات، وفي 24 صفر 1409هـ - 5تشرين الأول 1988م سمحت الحكومةُ الجزائريةُ بشيء من الحرية، فأخذَت المظاهرُ الإسلامية تظهَر، وخاصةً لدَى النِّساء، فوصَمَها الغرب، وخاصةً فرنسا بالرجعيَّة والتخلُّف، فقامت ثُلَّة من النساء يُظهِرْنَ معارضتَهنَّ لل"},{"id":5546,"era":"c15","t":"توسعة الملك فهد للمسجد الحرام .","s":"أمَرَ المَلِكُ فَهدُ بنُ عبدِ العَزيز -رَحِمَه اللهُ- بوَضعِ حَجَرِ الأساسِ لأكبَرِ تَوسِعةٍ للمَسجِدِ الحرامِ في هذا العامِ، وتَقَعُ في الجانِبِ الغَربيِّ مِن المسجِد الحرامِ بين بابَيِ العُمرةِ والمَلِكِ عبدِ العزيزِ.يتكَوَّنُ مبنى التَّوسِعةِ مِن ثلاثةِ أدوارٍ بمساحةِ 76 ألف مترٍ مُرَبَّعٍ، إضافةً إلى السَّاحاتِ الخارجيَّةِ بمساحةِ 85,800 مترٍ مُرَبَّعٍ.وصَلَ إجماليُّ القُدرةِ الاستيعابيَّةِ لل"},{"id":5547,"era":"c15","t":"إعلان المجلس الوطني الفلسطيني عن قيام دولة فلسطينية عاصمتها القدس .","s":"في 15 نوفمبر 1988م، في اجتماع المجلس الوطني الفِلَسطيني في الجزائر، أُعلن قيامُ دولة فِلَسطين وَفْق قرار التقسيم الصادر من الأمم المتَّحِدة رقم 181، الإعلان يحدِّد قيام الدولة على قطاع غزَّة والضِّفة الغربية التي تخضع للاحتلال الإسرائيلي منذ 1967م، ثم أكَّدت اللجنة التنفيذية لمنظمة التحرير، وممثِّلو القوى الوطنية الفِلَسطينية برئاسة ياسر عرفات في عام 1993م على حقِّ القيادة الفِلَسطينيَّة في الإعلا"},{"id":5548,"era":"c15","t":"وفاة الشيخ القارئ عبد الباسط عبد الصمد .","s":"وُلد الشيخُ عبد الباسط بن محمد بن عبد الصمد بن سليم القارئُ المشهورُ سنةَ 1927م، بقرية المراعزة من عائلة كُرديَّة، بأرمنت-قنا بجنوبي صعيد مصر، حفِظ القرآنَ الكريم على يد الشيخ محمد الأمير شيخ كُتَّاب قريته، وأخذ القراءات على يد الشيخ المتقِن محمد سليم حمادة، دخل الإذاعة المصرية سنةَ 1951م، وكانت أول تلاواته من سورة فاطر، عُيِّن قارئًا لمسجد الإمام الشافعي سنةَ 1952م، ثم لمسجد الإمام الحُسين سنةَ 1"},{"id":5549,"era":"c15","t":"انسحاب القوات السوفيتية من أفغانستان .","s":"دخلت روسيا إلى أفغانستان بصورة عسكريَّةٍ احتلاليَّة في صفر 1400هـ / ديسمبر 1979م، وبدأ التعسُّف، والتدميرُ، والتشريدُ، وبرَزت منظَّمة تحرير شعب أفغانستانَ (ساما) بقيادة ماجد كلاكاني، وظهرت جبهة التحرير الوطنية برئاسة أحمد الجيلاني، ثم تشكَّلت جَبهة المقاوَمة الجديدة من ستِّ مجموعاتٍ، معَ وجود بعض الخلافات التي كانت بين مدٍّ وجزرٍ؛ وذلك لأنَّ المنظِّمات الشِّيعية متعدِّدةٌ، وتتركَّز في طِهْرانَ، وت"},{"id":5550,"era":"c15","t":"مصر تستعيد منطقة طابا الحدودية من إسرائيل .","s":"طابا هي آخِرُ النقاط العُمرانيَّة المصريَّة على خليج العَقَبة، وهي ذاتُ أهميَّة إستراتيجيَّة وسياحيَّة كبيرة. وتبعُدُ عن مدينة شرمِ الشيخِ حوالَيْ 240 كم باتجاه الشمالِ، وتُجاوِرُها مدينة إيلات الإسرائيليَّة، وتمثِّل المِنطقة الواقعة بين طابا شمالًا وشرم الشيخ جنوبًا أهمَّ مناطق الجَذْب والتنمية السياحية بجنوب شبهِ جزيرة سيناءَ، ولطابا أهميَّةٌ أُخْرى في التاريخ المصري أشهَرُها حادثةُ طابا عام 190"},{"id":5551,"era":"c15","t":"الأزمة بين موريتانيا والسنغال .","s":"وقعَتْ أزمةٌ بين موريتانيا والسنغال، بسبب الزُّنوجِ في الصحْراءِ المتاخِمة للبلَدَينِ، فقد قُتِلَ اثنانِ من السنغاليِّينَ في قريةٍ على الحدود في الجنوب الشرقي من موريتانيا على يدِ رُعاةٍ موريتانيِّينَ من الزُّنوج، وقام وزيرُ الداخليَّةِ السنغاليِّ بزيارة موريتانيا، وقابَلَ الرئيس، وأعلَنَ الوزيرُ أنَّ الأمر مُبَيَّتٌ، ولن تَسكُتِ السنغالُ، فقام في اليوم التالي السنغاليُّونَ بمظاهَراتٍ في البلدة ال"},{"id":5552,"era":"c15","t":"وفاة الخميني قائد الثورة الإيرانية .","s":"الخُميني قائدُ الثورة الإيرانيَّة، ومُنشئُ الحُكومة الإسلاميَّة الشيعيَّة التي أسْقَطَت حُكمَ الشاهِ، وصاحبُ نظريَّة (وِلايةُ الفَقيهِ)، واسمُه بالكامل رُوحُ اللهِ بنُ مصطفى موسَوي، وُلد في 29 جمادى الأولى سنةَ 1318هـ 24 سبتمبر 1900م، بقرية «خُمين» بإيرانَ، وكان أبوه من عُلماء الشيعةِ، وقد قُتل على يد أحد الإقطاعيِّينَ، والخُميني كان عمرُه سنةً واحدةً، فتكفَّلت أُمُّه برِعايته ورِعايةِ أخيه الأصغر"},{"id":5553,"era":"c15","t":"انقلاب عسكري بقيادة العقيد البشير في السودان .","s":"في صباح يوم الجمُعة 27 ذي القَعدة 1409هـ / 30 حزيران 1989م وقَع انقلابٌ عسكري بقيادة العقيد الركن عمر حسن أحمد البشير، الذي أَعلن نفسَه رئيسًا لمجلس قيادة الثورة الجديد في السودان، وأَعْلن قادةُ الانقلاب بياناتِهم باسم \"الحركة القومية لتصحيح الأوضاع\"، ثم أطلَقوا على أنفسهم ثورةَ حزيران، ثم ثورة الإنقاذ الوطني، وأُعلنت الإطاحةُ بحكومة الصادق المهدي، وكان ميل هذا الاتجاه الجديد إسلاميًّا، فأَعلنت أم"},{"id":5554,"era":"c15","t":"علي أكبر رفسنجاني رئيسًا لإيران بعد انتهاء مدة علي خامنئي .","s":"بعد أن انتهَت مدة الرئاسة المقَرَّرة بالدستور الإيراني للرئيس علي خامنئي، وكانت قد مُدِّدت ولايتُه شهرًا آخَرَ، وانتُخِب علي خامنئي مدةَ شَهرين ريثَما تنتهي مآتمُ عاشوراءَ، وتتم بعض التعديلات على الدستور، جرَت الانتخاباتُ النيابيةُ، وفاز بها علي أكبر رفسنجاني الذي أقسَمَ اليمينَ الدستورية في 15 محرم 1409هـ / 17 آب 1989م."},{"id":5555,"era":"c15","t":"مشروع الوحدة بين اليمن الشمالي والجنوبي (حضرموت) .","s":"بدأ في اليمَن تنفيذ مشروع الوَحْدة الاندماجيَّة الفَوْريَّة، عندما وصل وفدٌ من صنعاءَ برئاسة الرئيس علي عبد الله صالح للمُشارَكة في احتفالات ذِكرى جَلاء الاستعمار البريطاني عن الجنوب اليَمَني (1967م)، لكنَّ الزيارةَ لم تنتهِ إلَّا وقد تمَّ التوقيع على اتفاق يَقْضي بإحالة مشروع دستور يَمَن الوَحْدة الجديد على برلمان كل شطر، تمهيدًا لإجراء استفتاءٍ شَعبي عليه، وهو ما كان يَعْني قيامَ وَحْدة اندماجيّ"},{"id":5556,"era":"c15","t":"مقتل عبد الله يوسف عزام أمير المجاهدين العرب في أفغانستان. .","s":"وُلد عبد الله عزَّام في قرية سيلة الحارثيَّة في لواء جنينَ الواقعة شمالَ وسطِ فِلَسطينَ، وكانت لا تزال تحت الانتداب البريطاني، واسم والده الحاج يوسف مصطفى عزَّام، تلقَّى عبد الله عزَّام علوم الابتدائيَّة والإعداديَّة في مدرسة القرية، ثم واصَل تعليمَه العاليَ بكلية خضورية الزراعية، ونال منها الدبلوم، ثم انتسب إلى كلية الشريعة في جامعة دِمَشقَ، ونال منها شَهادة الليسانس في الشريعة عام 1966م، وفي عام"},{"id":5557,"era":"c15","t":"وفاة الشيخ حسنين محمد حسنين مخلوف، مفتي الديار المصرية .","s":"وُلِدَ الشيخ حسنين في حي باب الفتوح بالقاهرة في (16 من رمضان 1307هـ / 6 من مايو 1890م)، وتَعهَّدَه أبوه بالتربية والتعليم، فما إن بلغ السادسةَ حتى دفَعَ به إلى مَن يُحَفِّظه القرآنَ الكريم، وأتمَّه وهو في العاشرة على يد الشيخ محمد علي خلف الحسيني شيخ المقارئ المصرية، وهيَّأه أبوه للالتحاق بالأزهر، فحفَّظه متونَ التجويد، والقراءات، والنحو، ثم التحق بالأزهر، وهو في الحاديةَ عَشْرةَ من عمره، وتلقَّى "},{"id":5558,"era":"c15","t":"اقتحام الجيش العراقي للكويت وقيام حرب الخليج الثانية .","s":"ما أن استقَلَّت الكويت عام 1381هـ / حزيران 1961م حتى أخذت العراق تُطالِب بالكويت، وتَعُدُّها جزءًا منها، ولكنْ بعد أيام من الاستقلال نزلَت قوات بريطانية في الكويت، وأصبحت العراق تُطالب بضرورة انسحاب القوات الأجنبية من أرض الوطن، ثم تقدَّمت الكويت إلى الجامعة العربية لتكون عضوًا فانسحبت القوات البريطانية، وحلَّت محلَّها قوات عربية من سوريا والأردُنِّ، ومصرَ والسعوديةِ، التي بَقيَت فيها سنةً، ثم رجع"},{"id":5559,"era":"c15","t":"وفاة الشيخ راشد بن سعيد آل مكتوم حاكم إمارة دبي .","s":"الشيخ راشد بن سعيد آل مكتوم الفلاسي، وُلد في عام 1912م، ونشأ في كنَف أبيه الشيخ سعيد بن مكتوم آل مكتوم، وهما من قبيلة آل بو فلاسة، وترعرع في كنَف والدته الشيخة حصَّة بنت المر بن حريز الفلاسي. تلقَّى دراسته الأولى في الكتاتيب، مع بداية الدراسة النظاميَّة بمدرسة الأحمديَّة التي أُسِّست في أوائل هذا القرن، عُيِّن حاكمًا لإمارة دبي منذ 1958م، وحتى وفاتِه في 7 أكتوبر 1990، ونائبَ رئيس الدولة من 1971م و"},{"id":5560,"era":"c15","t":"اغتيال صلاح خلف المعروف بأبي إياد، عضو حركة فتح .","s":"صلاح خلف، اسمه الحَرَكي أبو إياد، وهو سياسي فِلَسْطيني، من مؤسِّسي حركة تحرير فِلَسطين (فتح)، وهو قائد الأجهزة الأمنيَّة الخاصَّة لمنظمة التحرير، وحركة فتح لمدَّة طويلة.قدِمَ والدُه من مدينة غزَّة إلى يافا، وهناك وُلد صلاح خلف عام 1933م، وعاش أول سِني حياتِه حتى قبلَ قيام الكِيان الصِّهْيَوني بيوم واحد، حيث اضطرَّ وعائلتُه إلى الذَّهابِ إلى غزَّةَ عن طريق البحر، فأكمل في غزَّةَ دراستَه الثانوية، و"},{"id":5561,"era":"c15","t":"قوات المعارضة الصومالية تتولى السلطة بعد هرب الرئيس محمد زياد بري .","s":"كان رئيس الصومال محمد زياد بري قد أسَّس في مقديشو مكتبًا للمنظمة الديمقراطية الشعبية الأورومية المعارِضة في الحَبَشة لنظام منغستو ماريام رئيس الحبشة، فقامت الحَبَشة بمضاعَفة دَعْمها للمعارَضة الصومالية، ممَّا أدَّى إلى اشتداد القتال بين قوات الحكومة وفصائل المعارَضة التي زادت قوتها، وبان تفوقها، حتى اضطرَّ الرئيس محمد زياد بري إلى الهرب خارج الصومال في رجب 1411هـ / كانون الثاني 1991م، وتمكَّنت الق"},{"id":5562,"era":"c15","t":"إلغاء مجلس قيادة الثورة العراقية قرار ضم الكويت .","s":"قرَّر مجلسُ قيادة الثورة العراقية إلغاءَ قرار ضمِّ الكويت، واعتبار جميع القوانين والأحكام القضائية والقواعد التي تمَّ تطبيقُها على الكويت منذ الغزو العراقي في أغسطس الماضي لاغيةً، وأن الرئيس صدَّام حُسين وقَّع على القرار، وذلك في إطار قَبول العراق لقرارات مجلس الأمن، بما فيها القرار 687."},{"id":5563,"era":"c15","t":"تدمير المساجد واضطهاد المسلمين في ليبيريا الأفريقية .","s":"إنَّ مؤسِّسي دولة ليبيريا الإفريقية كانوا من السُّود المحرَّرين الذين كانوا عبيدًا في الولايات المتحدة، ثم أعادتهم واشنطنُ إلى مواطِنِهم الأصليَّة من أجْل خِدمة أطماعها الاستعمارية، فضلًا عن أطْماع الكنيسة في واشنطنَ التي عمِلت على تنصير هؤلاء أوَّلًا، ثم إرسالهم إلى بلادهم من أجْل نشر النصرانيَّة، وبالرغم من أنَّ هؤلاء لم يُشكِّلوا سوى 1% فقطْ من سكان البلاد، إلَّا أنَّ الدعم الأمريكي الكبيرَ لهم"},{"id":5564,"era":"c15","t":"مؤتمر مدريد بين العرب وإسرائيل .","s":"انعقَدَ مؤتمَرُ مدريدَ في 30 أكتوبر برعايةٍ أمريكيةٍ سُوفيتيةٍ، وبحضورٍ أوربيٍّ شَكليٍّ، وشارَكت أكثرُ البلاد العربية، وتمكَّن الكِيان الصِّهْيَوني من فَرض شروطه على التمثيل الفِلَسْطيني، فتمَّ استبعاد المشارَكة الرسمية لمنظمة التحرير الفِلَسْطينية، وسار المؤتمر في مسارَيْنِ: - ثنائيٍّ، يضم الأطراف العربية التي لها نزاعٌ مباشرٌ معَ إسرائيلَ، وهي: سوريا، والأردُنُّ، ولُبنانُ، وفِلَسطينُ. - ومتعددِ "},{"id":5565,"era":"c15","t":"اغتيال رئيس الوزراء الإيراني الأسبق شابور بختيار .","s":"شابور بختيار كان من أعضاء الجبهة الوطنية، وكان رئيسَ الوزراء في حكومة الشاه محمد رضا بهلوي في إيرانَ، وُلِدَ بختيار في شهركرد، كان وزيرًا في حكومة محمد مصدق، وقد طلَب بختيار من الشاه محمد رضا بهلوي أن يوافِقَ على تشكيل مجلس وصاية ينوبُ عنه، وأن يقومَ الشاه بمغادَرة البلاد في عطلة، فقَبِل بختيار رئاسة الوزراء، ثم حدث انشقاقٌ في الجبهة الوطنية، أَعلن الخُميني طردَه من النهضة الإسلامية بعد الثورة الإ"},{"id":5566,"era":"c15","t":"بداية أزمة لوكيربي بين ليبيا والولايات المتحدة وبريطانيا .","s":"بدأت هذه الأزمةُ في 21 ديسمبر 1988م، عندما انفجرت الطائرة البوينج 747، والتابعة لشركة (PANAM) الأمريكية، الرحلة 103 المتَّجِهة من فرانكفورتَ إلى نيويوركَ عبرَ لندنَ، وكان الانفجار فوقَ مُقاطعة إسكتلندا ببلدة لوكيربي، وبلغ مجموعُ ضحايا الانفجار 270 فردًا من 21 دولةً.كان ردُّ الفعل على الانفجار عنيفًا، حيث صدرت عدَّةُ بياناتٍ، من مختلِف الدول تُدين العملية، وانضمَّت بريطانيا إلى أمريكا في هذا الحادث"},{"id":5567,"era":"c15","t":"فوز الجبهة الإسلامية للإنقاذ في انتخابات الدورة الأولى بالجزائر .","s":"فازت الجَبْهة الإسلامية للإنقاذ والتي يتزعَّمُها عباسي مدني في الدورة الأولى في الانتخابات التشريعيَّة التي أُجريت على أساس التعدُّديَّة الحزبيَّة في الجزائر في عهد الرئيس الجزائري الشاذلي بن جديد، غيرَ أنَّ هذا الفوز أقلق قادة الجيش، فأُلغيت الدورة الثانية، وتجمَّدت الانتخابات."},{"id":5568,"era":"c15","t":"البوسنة والهرسك ثالث جمهورية يوغسلافية تعلن الاستقلال. .","s":"البوسنة والهرسك هي إحْدى جُمهوريات يوغوسلافيا السابقة ذات الأغلبيَّة المسلِمة، وتقَع في جنوب أوروبا، وقد قامت بإعلان استقلالَها، ممَّا أدخلها في حرب أهليَّة معَ الصِّرْب، واعترفت المجموعة الأوروبيةُ والولاياتُ المتحدةُ باستقلال البوسنة والهرسك في العامِ نفْسِه."},{"id":5569,"era":"c15","t":"اختيار الشيخ محمد صفوت رئيسًا لجماعة أنصار السُّنة المحمدية بمصر .","s":"تولَّى الشيخ محمد صفوت نور الدِّين رئاسةَ جماعة أنصار السُّنة المحمديَّة بعد وفاة الشيخ محمد علي عبد الرحيم -خامس رؤساء الجماعة- عام 1412هـ - 1991م؛ فصار بذلك أوَّلَ رئيسٍ من الجيل الثاني، وسادس رؤساء الجماعة، وقد تمَّ انتخابُه بالإجماع في يوم الخميس 22 شعبان 1412هـ."},{"id":5570,"era":"c15","t":"اغتيال الرئيس الجزائري محمد بوضياف في مدينة عنابة الجزائرية .","s":"في يوم الاثنينِ 29 يونيو 1992 في الساعة التاسعة صباحًا وصَلَ الرئيس إلى عنابة -مدينة ساحلية تقع شمال شرق الجزائر-، وفي أثناء إلقاء خطابِه انفجرت قُنبلةٌ يدويةٌ، ثم تمَّ إطلاق النار مباشرةً على الرئيس من خلفِ ظَهرِه، وفي نفس الوقتِ انفجرت قُنبلةٌ أُخرى كانت تحت مَقعَد الرئيس مُصيبةً بشظاياها كلَّ مَن كان جالسًا على المِنصَّة، لم تدُم الطلقات سوى ثوانٍ معدودةٍ، ورمى كل مَن كان واقفًا نفسَه على الأرض"},{"id":5571,"era":"c15","t":"مذابح المسلمين في البوسنة والهرسك .","s":"بدأت القواتُ الصِّرْبيةُ تَعيثُ فَسادًا في البلاد طولًا وعَرضًا، وقالوا للعالم: إنَّ بلادَ البوسنةِ لن تصمُدَ سِوى أربع أو خمس ساعاتٍ، وتكون كلُّها بقبضةِ الصِّربِ، {وَيَمْكُرُونَ وَيَمْكُرُ اللَّهُ وَاللَّهُ خَيْرُ الْمَاكِرِينَ} [الأنفال: 30]، فزحفَت القوات الصربيَّة على سراييفو التي ظلَّت تقاوِمُ، وسقَطَت مدنُ بريدور، وبانيالوكا، وبالي، ومدن كثيرة بقبضة الصِّربِ، والمدنُ الأُخرى محاصَرة، وقطعوا"},{"id":5572,"era":"c15","t":"الحرب الأهلية في جمهورية طاجكستان الإسلامية .","s":"نشِبَت الحربُ الأهليَّة في طاجكستانَ بعد نيل استقلالها بقليلٍ، حيث اندلَعت الحربُ بين الميليشيات، ونتَجَ عنها مَقتلُ (50) ألفَ شخصٍ، وهجرة (1.2) مليون مُشرَّد ولاجئ خارجَ وداخلَ البلاد."},{"id":5573,"era":"c15","t":"اضطهاد المسلمين في بورما .","s":"إنَّ عددَ مُسلِمي بورما يصِلُ إلى 11 مليونَ نسمةٍ من إجماليِّ سكان بورما البالغِ تَعدادُهم 50 مليونَ نسمةٍ، منهم أكثرُ من 5.7 مليون مسلمٍ، يقطُنون منطقةَ أراكان، يُشكِّلون أكثرَ من 75 % من سكان المنطقة، وقد بدأت مأساة مُسلِمي بورما في عام 1948م، وهو نفسُ العام الذي احتلَّ فيه الصهاينة فِلَسْطينَ، حيث دخلت القوات البورميَّة أراكان وتمكَّنت من احتلالها بالقوة عبرَ سلسلة من المذابح الإجراميَّة، ومارس"},{"id":5574,"era":"c15","t":"معاهدة أوسلو بين إسرائيل ومنظمة التحرير الفلسطينية .","s":"وقَّعت إسرائيلُ ومنظَّمةُ التحرير الفِلَسْطينيةُ معاهدةَ أوسلو في واشنطنَ في 13 سبتمبر، ونسبت إلى مدينة أوسلو بالنرويجِ، والتي تمَّت فيها المحادَثاتُ السريةُ التي سبَقَت المعاهدةَ، وهي أول اتفاقيةٍ رسميةٍ مباشرةٍ بين إسرائيلَ والمنظمةِ، وتنصُّ على:1.     إقامة سُلطة حكومةٍ ذاتيةٍ انتقاليةٍ فِلَسطينيةٍ. 2.     ومجلس تشريعي منتخَب للشعب الفِلَسْطيني في الضفة الغربية وقطاع غزَّةَ، لفترة انتقالية لا ت"},{"id":5575,"era":"c15","t":"اتفاق لإنهاء الحرب الأهلية في أفغانستان .","s":"في 24 نيسان إبريل 1992، تم توقيعُ اتفاق عُرف باسم اتفاق بيشاورَ من قِبَل أحزاب الاتحاد الإسلامي لمجاهِدي أفغانستانَ السبعة، وحزب الوَحْدة الشيعي، والحركة الإسلامية محسني، فتمَّ الاتفاق على تشكيل حكومة مؤقَّتة لمدة شَهرينِ، وعلى رأسها صبغة الله مجددي، ثم يتبَعُه ولمدة أربعة أشهرٍ بُرهان الدين ربَّاني، ولكنَّ الحزب الإسلامي بقيادة حكمتيار رفَضَ الاتفاقيةَ بالرغم من أنَّه من الموقِّعين عليها، فهاجَم "},{"id":5576,"era":"c15","t":"وفاة أبي القاسم الخوئي المرجع الأعلى للشيعة في العالم  .","s":"وُلد أبو القاسم الخوئي في ليلة النصف من شهر رجبٍ سنةَ 1317هـ الموافق 19/11/1899م، في مدينة خوي من إقليم أذربيجانَ في إيرانَ، ويُنسَب إلى عائلةٍ ذات أُصول عَلَويَّة (موسوية)، نسبة إلى (موسى الكاظم)، قام الخوئي وهو ابن الثالثةَ عَشْرةَ بالهجرة إلى العراق للالتحاق بوالده علي أكبر الموسوي الخوئي الذي كان قد هاجَر قبلَه إلى النجَف، وبدأ الخوئي بدراسة علوم العربية، والمنطق، والأصول، والفقه، والتفسير، وا"},{"id":5577,"era":"c15","t":"الهندوس المتعصبون يدمرون المسجد البابري بالهند .","s":"إنَّ المسجد البابري الواقعَ بمدينة \"إيودهيا \" في شمال الهندِ، يعودُ تاريخُه إلى القرن السادسَ عَشَرَ الميلاديِّ، عندما بناه \"بابرُ\" أولُ إمبراطورٍ مغوليٌّ حكَمَ الهندَ، وفي أوائل الثمانينيات من القرن العشرين زعَم المتطرِّفون الهندوسُ أنه بُنيَ على أنقاض معبدٍ بمكان مَولِد \"راما\" الأسطوري المقدَّس لدى الهندوس، ولذا وجب نسفُه، والتخلصُ منه .. وجعلوها قضيةً شَعبيَّةً، وقضيَّةً عامَّةً للهندوس، وبدؤوا"},{"id":5578,"era":"c15","t":"الأمم المتحدة ترسل قوات دولية إلى الصومال .","s":"قامت الأممُ المتَّحدةُ بإرسال قوَّات شارَكت فيها عشرون دولةً، وذلك في إطار عملية \"إعادة الأمل\" إلى الصومال التي كانت تشهَد حربًا أهليَّةً منذ عام 1990م. وقد عزَّزت هذه القواتِ بعد عامٍ واحدٍ بوَحَدات معظمُها أمريكيةٌ وفرنسيةٌ؛ لإنهاء الفوضى والقِتالِ في الصومال، لكنَّها اضطرَّت في النهاية إلى الانسحاب بعد أن تكبَّدت خسائرَ كبيرةً، وفَشِلت في حلِّ المشكلة."},{"id":5579,"era":"c15","t":"وفاة الرئيس التركي تورجوت أوزال .","s":"وُلِدَ تورجوت أوزال عام 1346هـ، وهو الذي أسَّس حزبَ الوطن الأم في تركيا، وذلك عندما بدأت الحياة السِّياسية تعود للبلاد تدريجيًّا، وكان أوزال يتمتَّع بخبرةٍ عاليةٍ في الشؤون الاقتصادية والسياسية، وكان مرشحًا لحزب السلامة الوطني عن ولاية \"أزمير\"، وكان يُقال عنه: إنه سفيرُ الغرب في بلاده، ورغم ذلك فإنَّ الحركة الإسلامية في عهده -سواءٌ كان في رئاسة الوزراء، أو في رئاسة الجمهورية- كانت تتمتَّع بحرية أك"},{"id":5580,"era":"c15","t":"استقلال إريتريا .","s":"استطاعت إريتريا أنْ تنفَصِل عن إثيوبيا، وتستقِلَّ سياسيًّا بعدَ ثلاثين عامًا من الكفاح السياسي والعسكري، حَظِيَت خلالَه بدعمٍ عربيٍّ وإسلاميٍّ كبيرٍ، ورغم أنَّ نسبة المسلمين في إريتريا تُقارب 78% إلَّا أنَّ الرئيس أسياس أفورقي قاد البلاد بتوجُّهاته الماركسية التي تعزَّزت بفَرضِه اللغةَ التيجرينيةَ لغةً رسميةً للبلاد بدلًا من اللغة العربية، وتجاهُلِه لقوانين الأحوال الشخصية للمسلِمينَ، وعلاقاتِه ال"},{"id":5581,"era":"c15","t":"نشوب حرب بين اليمن الشمالي والجنوبي (حضرموت) وانتصار الشمالي .","s":"بعد مشروعِ الوَحْدة جَرى انتخاب علي عبد الله صالح رئيسًا لمجلس رئاسة الجمهورية اليَمَنية، وعلي سالم البيض نائبًا له، ثم بدأت بوادرُ الاختلال السياسي في اتفاق الوَحْدة، بين نظامَينِ مختلِفَينِ: النظام الجنوبي الاشتراكي، والشمالي القَبَلي، حيثُ يَعُدُّ شيوخُ القبائلِ الاشتراكيِّين كفرةً وماركسيِّين، ويَعُدُّهم الاشتراكيُّونَ أُصوليِّين ومُتخلِّفينَ، وسُرعانَ ما انهار السِّلم واندلعت حربٌ أهليةٌ قصير"},{"id":5582,"era":"c15","t":"اتفاق القاهرة بين الفلسطينيين والإسرائيليين .","s":"يُعَدُّ هذا الاتفاق إجراءً تنفيذيًّا لاتفاقية أوسلو، فقد فشِلَ الطرَفانِ الفِلَسْطينيُّ والإسرائيليُّ في الاتفاق على تَفْصيلات المرحلةِ الأولى (غزَّة - أريحا)، وانقضَت المدة المحدَّدة لانسحاب القوات الإسرائيليَّة قبل أنْ تنسَحِب بالفعل، وبعد مَزيد من التعنُّت الإسرائيلي، والتنازُلِ الفِلَسْطيني، توصَّلَ الجانبانِ إلى توقيعِ اتفاقِ القاهرة؛ ليفصِلَ المرحلةَ الأُولى من الاتفاق والجدولة الزمنية للانس"},{"id":5583,"era":"c15","t":"هجوم مشترك للصرب والكروات على مسلمي البوسنة .","s":"قامت القوَّاتُ الصربيةُ والقوات الكرواتيةُ بهجوم مشتركٍ على مُسلمي البوسنةِ، وقاما بقَصفِهم بالقنابلِ الحارقة."},{"id":5584,"era":"c15","t":"زعماء الفصائل الصومالية المتنازعة يوقعون اتفاقًا لإنهاء القتال .","s":"وقَّع زعماءُ الفصائل الصومالية المتنازِعة في العاصمة الصومالية مقديشيو اتفاقًا، يهدُفُ إلى إنهاء القتال في مقديشيو، ونصَّ الاتفاق على إعادة الممتلَكاتِ التي نُهبَت عقِبَ الفوضى التي أطاحت بالرئيس الصومالي السابق محمد سياد بري."},{"id":5585,"era":"c15","t":"تعيين الأمين زروال رئيسًا للجزائر .","s":"تولَّى الأمين زروال رئاسة الجزائر، وقد وُلد بمدينة باتنة عاصمة الأوراس التي شهِدَت اندلاعَ ثورة التحرير، التحَق بجيش التحرير الوطني، وعمرُه لا يتجاوزُ 16سنةً، حيثُ شارَكَ في حرب التحرير بين 1957م – 1962م، وبعد الاستقلالِ تلقَّى تكوينًا عسكريًّا في الاتحاد السوفييتي، ثم في المدرسة الحربية الفرنسية سنةَ 1974م، ممَّا أتاح له تَقَلُّد عدَّة مسؤولياتٍ على مستوى الجيش الوطني الشعبي؛ إذ إنه اختير قائدًا "},{"id":5586,"era":"c15","t":"مذبحة المسجد الإبراهيمي بفلسطين .","s":"حدثت مَذْبَحة المسجد الإبراهيمي في الخليل عندَما أقدَم مستوطِنٌ يَهوديٌّ (باروخ غولد شتاين) تحتَ تَغْطية من الجيش الإسرائيلي على فتحِ النيران على الساجِدينَ الصائمينَ، فقَتَل 29 مسلمًا أثناءَ أدائهم الصلاةَ فجرَ يومِ جُمعة الخامسَ عَشَرَ من شهر رمضانَ، كما جرَحَ 150 آخرينَ قبلَ أنْ يَنقَضَّ عليه مُصَلُّونَ آخَرونَ ويَقْتلوه، وشارَكَ في الهجوم الخسيس الجيشُ الإسرائيلي، وجموعُ مُستَوطِني (كريات أريع"},{"id":5587,"era":"c15","t":"لبنان تقطع العلاقات الدبلوماسية مع العراق .","s":"قرَّرَت دولة لُبنانَ قطعَ العَلاقات الدبلوماسية مع دولةِ العراق، وذلك بسبب رفضِ بَغدادَ رفعَ الحصانة عن اثنين من الدبلوماسيِّينَ العراقيِّينَ المعتقَلينَ في لُبنان؛ لمحاكمتهم بتُهمة التورُّط في مَقتَل مُعارِض عراقي في بيروت."},{"id":5588,"era":"c15","t":"إنهاء الحرب الأهلية في اليمن بدخول قوات اليمن الشمالية مدينة عدن .","s":"اندلَعَت الحرب الأهليةُ في اليَمَن صيف 1994م بين الحكومة اليَمَنية في صنعاءَ، والحزب الاشتراكي اليَمَني في عدنَ؛ من أجل مطالبة الانحلال، أو الانفصالِ لـ اليَمَن الجنوبي عن اليَمَن الشمالي من دولة الوَحْدة اليَمَنية التي قامت في عام 1990، بين اليَمَن الجنوبي -بما كان يُعرف بجمهورية اليَمَن الديمقراطية الشعبية ممثَّلةً بالحزب الاشتراكي اليَمَني- واليَمَن الشمالي -بما كان يُعرف بالجمهورية العربية الي"},{"id":5589,"era":"c15","t":"الأردنيون يوقعون معاهدة للسلام مع إسرائيل (معاهدة وادي عربة) .","s":"يُطلَق اسمُ معاهدة وادي عربة على معاهدة السلام الأُردُنِّيَّة الإسرائيلية نسبةً إلى المنطقة الأُردُنِّيَّة التي تمَّ توقيعُ المعاهَدة عليها.- وقَّع عن الجانب الأُردُنِّيِّ: عبد السلام المجالي رئيس الوزراء الأُردُنِّيُّ، وعن الجانب الإسرائيلي: إسحاق رابين رئيسُ الوزراء الإسرائيلي.- الشاهدُ على التوقيعِ: بيل كلينتون رئيس الولايات المتحدة الأميركية. - تاريخُ التوقيعِ: 26 أكتوبر/ تشرين الأول 1994م. - "},{"id":5590,"era":"c15","t":"إيران تعلن أن جزر الإمارات ملك لها إلى الأبد .","s":"بعدَ أنْ أَعلنت إيرانُ رسميًّا سيادتَها على جُزُر الإمارات في 16 يونيو 1993م، قامت مرةً أُخرى بإعلانها أنَّ جزرَ الإمارات ملكٌ لها إلى الأبدِ، ورفضت قرارَ المجلس الوزاري لجامعة الدول العربية بإنهاء الوجودِ الإيراني في هذه الجزرِ، وهذه الجزر محلُّ النزاعِ هي: أبو موسى، وطنب الكبرى، وطنب الصغرى."},{"id":5591,"era":"c15","t":"المغرب وإسرائيل تقرران فتح مكاتب ارتباط في كلتا الدولتين .","s":"بعدَ اتفاقِ الحُكم الذاتي بينَ إسرائيلَ ومنظمة التحريرِ الفِلَسْطينية عامَ 1993م، فتَحَت الدولةُ العِبْريَّة مكتبَ ارتباطٍ لها في الرباطِ عامَ 1994م، في حينِ فتَحَت المغربُ مكتبًا مماثِلًا في تل أبيب عامَ 1995م."},{"id":5592,"era":"c15","t":"عرفات ورابين وبيريز يفوزون بجائزة نوبل للسلام .","s":"مُنِحَت جائزةُ نوبلَ للسلامِ لعام 1994م مُناصَفةً بينَ كلٍّ من الزعيم الفِلَسْطيني ياسر عرفات رئيس فِلَسطينَ المحتلَّة، وشيمون بيريز الرئيس الإسرائيلي، وإسحق رابين رئيس الوزراء الإسرائيلي."},{"id":5593,"era":"c15","t":"افتتاح السفارة الإسرائيلية في عمَّان .","s":"بعد توقيعِ الأُردُنِّ اتفاقيةَ السلام (اتفاقية وادي عربة) مع إسرائيلَ في أكتوبر / تشرين الأول 1994م، قامت إسرائيلُ بافتتاحِ سِفارتها في العاصمة الأُردُنِّيَّة عمَّانَ."},{"id":5594,"era":"c15","t":"جيبوتي وإسرائيل تقرران تطبيع العلاقات بينهما .","s":"تَقرَّرَ تطبيعُ العَلاقات بين جيبوتي وإسرائيلَ، ونتيجةً لهذا التطبيع سُمِحَ لأوَّل طائرةٍ إسرائيليةٍ بالهبوط في مطارِ جيبوتي."},{"id":5595,"era":"c15","t":"انسحاب القوات الدولية من الصومال .","s":"دخلَت القواتُ الدوليةُ بقيادةِ الولاياتِ المتحدةِ الصومالَ في ديسمبر عامَ 1992م، والتي حمَلَت اسمَ \"إحياء الأمل\"، وقد انتشرت في معظمِ المناطقِ الجنوبية، ودخَلَت القواتُ الدوليةُ في حربٍ معَ مليشيات الجنرال عيديد، وطالبت بإلقاءِ القبضِ عليه، وهو ما لم تنجحْ فيه. وأعقَبَ ذلك انسحابٌ سريعٌ للولايات المتَّحِدة من الصومالِ بعد مَقتَلِ 18 من جنودِها في شوارع مقديشيو في أكتوبر عام 1993م، تَلاه انسحابٌ لل"},{"id":5596,"era":"c15","t":"تظاهرات في الضفة الغربية في ذكرى مذبحة الحرم الإبراهيمي .","s":"وقَعَت تَظاهُراتٌ في الضفةِ الغربيةِ، وذلك في ذِكْرى مذبحةِ الحرم الإبراهيمي، وهي المذبحةُ التي ارتكبها باروخ جولدشتاين، أو باروخ جولدستين، وهو طبيبٌ يهوديٌّ والمنفِّذُ لمذبحةِ الحرم الإبراهيمي في مدينة الخليلِ الفِلَسْطينية في 1414 هـ / 25 فبراير 1994م، التي قام بها معَ عدد من المستوطِنينَ والجيشِ في حقِّ المصلِّينَ، حيث أطلق النارَ على المصلِّينَ المسلمينَ في المسجد الإبراهيمي أثناءَ أدائِهم صلا"},{"id":5597,"era":"c15","t":"محاولة اغتيال الرئيس مبارك رئيس مصر في أديس أبابا .","s":"أطلَق مُسلَّحونَ النارَ على الرئيس مبارك في أديس أبابا عندما كان حاضرًا لقمةِ مُنظَّمة المؤتمرِ الإسلاميِّ، فأُصيبت سيارتُه من جرَّاء الاعتداء، واضطر موكبُه إلى التراجُعِ من حيث أتى، ومن جرَّاء الهجوم توتَّرت العَلاقات المصرية السودانية، إلى درجة أنَّ هناك مصريِّينَ طالبوا مبارك بضرب السودان، حيث أشارت بعضُ المصادر إلى تورُّط عددٍ من العناصر المرتبطة بالجبهة الإسلامية في السودان في هذه المحاوَلة."},{"id":5598,"era":"c15","t":"تصاعد النزاع المصري السوداني حول منطقة حلايب وشلاتين الحدودية .","s":"تقَعُ مِنطقةُ حَلايبَ وشَلاتينَ على الحدود الرسميَّةِ بينَ مصرَ والسودانِ، وتبلُغُ مساحتُها 20 ألفَ كيلومترٍ مربعٍ على ساحل البحر الأحمر، وحلايبُ تَقطُنُها قبائلُ تمتدُّ بجذورها التاريخية بينَ الجانِبَينِ، كما تتنقَّلُ هذه القبائلُ بسهولةٍ عبرَ الحدود؛ لأنَّ وُجودَها كان سابقًا على رسمِ الحدودِ، وبها نقطةٌ وطريقٌ يربِطُ بينَها وبينَ السويسِ عَبرَ بئرِ شَلاتينَ وأبو رمادٍ، وتُعَدُّ مدينةُ حلايبَ ال"},{"id":5599,"era":"c15","t":"القوات الفرنسية تقتحم عاصمة جمهورية جزر القمر .","s":"اقتحَمَت القواتُ الفرنسيةُ عاصمةَ جمهورية جُزُر القُمُر؛ وذلك لإنهاء انقلابٍ حدَثَ بها، والسيطرةِ على المنشآتِ الحيوية، والإفراجِ عن الرئيس سعيد جوهر المحتَجَز."},{"id":5600,"era":"c15","t":"قطر تفتتح مكتب تمثيل لها في غزة .","s":"افتتَحَت دولةُ قَطر مكتبَ تمثيلٍ لها في غزَّةَ، وبعدها قام الزعيم ياسر عرفات بزيارتها والاجتماعِ معَ أمير قطر، في أثناءِ جولةٍ زارَ خلالَها الإمارات في أواخِرِ ديسمبر 1995م، وشدَّدَ على ضرورة طيِّ صَفحةِ حَربِ الخليج، وتجاوُز ما يُعكِّر صفوَ العلاقات الخليجية الفِلَسْطينية."},{"id":5601,"era":"c15","t":"انسحاب إسرائيل مدينة \"جنين\" في الضفة الغربية .","s":"بعدَ احتلالٍ دامَ 28 عامًا انسحبت إسرائيلُ بقوَّاتها من مدينة \"جنين\"، وهي أولُ مَدينة في الضفة الغربية يَنسَحِب منها الاحتلالُ الإسرائلي، وإثْرَ هذا الانسحابِ تسلَّمت السُّلُطات الفِلَسْطينية المدينةَ وَسْطَ احتفالاتٍ فِلَسْطينية صاخبةٍ."},{"id":5602,"era":"c15","t":"تفجير مقر البعثة العسكرية الأمريكية في الرياض .","s":"تمَّ تفجيرُ مَقرِّ البَعثةِ العَسْكرية الأمريكية في الرياض، عن طريق سيارةٍ مُفخَّخةٍ، ممَّا أدَّى إلى مَصرَعِ وإصابةِ 66 شخصًا، من بينِهم 40 أمريكيًّا، واحتراق 40 سيارةً."},{"id":5603,"era":"c15","t":"مؤتمر في الجامعة العربية لبحث قضية سرقة إسرائيل للمياه الفلسطينية .","s":"تمَّ عقدُ مؤتمرٍ في الجامعة العربية، وكان الهدفُ منه بحثَ قَضيةِ سَرِقةِ إسرائيلَ للمياهِ الفِلَسْطينية.وأطماعُ إسرائيلَ في المياه الفِلَسْطينية ترجِعُ منذُ احتلالها للضفة الغربيةِ وقطاعِ غزَّةَ عامَ 1967م، حيث عمِلَت على استنزاف المياه الفِلَسْطينية فيها، وخاصَّةً بعد أنْ تمكَّنت من الوصول إلى أحواضِ المياه فيها، والسيطرةِ عليها عبرَ العَديدِ من الأوامرِ العسكريةِ، والتي هدَفَت إلى ترسيخِ احتلاله"},{"id":5604,"era":"c15","t":"مؤتمر للمعارضة السودانية في أسمرة لبحث إسقاط نظام البشير .","s":"تمَّ عقدُ مؤتمَرٍ للمُعارَضةِ السودانية في أسمرةَ، وكان الهدفُ منه بحثَ إسقاط نظام البشيرِ، وفي ختام اجتماعات قادة المعارَضةِ السودانية، قرَّروا العملَ على إسقاطِ نظامِ البشيرِ، والإجماعَ على وَحْدة السودان، ومقاطعةِ الانتخابات السودانية."},{"id":5605,"era":"c15","t":"انتخاب ياسر عرفات رئيسًا للسلطة الوطنية الفلسطينية .","s":"بعد فوزِ عرفات وإسحق رابين وشمعون بيريز بجائزة نوبلَ للسلامِ، لم يلبَثْ عرفات أنِ انتُخِب رئيسًا فلسطينيًّا للسلطة الفِلَسْطينية، ومع أنَّه اتخذ لنفسه لقبَ الرئيس الفلسطيني، إلَّا أنه بَقيَ يُشار إليه من قِبَل المحافِل الغربية بلقَب تشيرمان عرفات (كلمة ليست بدرجة رئيس)."},{"id":5606,"era":"c15","t":"عودة سراييفو مدينة موحدة بعد أربع سنوات من التقسيم .","s":"عادت مدينة سراييفو عاصمةُ البوسنة والهرسك مدينةً مُوَحَّدةً من جديد، بعد أنِ استعادها المسلمونَ الكرواتُ، وذلك بعد أربع سنواتٍ من سيطرةِ القوات الصربيةِ عليها."},{"id":5607,"era":"c15","t":"مجزرة قانا الأولى .","s":"شنَّت القواتُ الإسرائيليةُ بأوامرَ من رئيس وزرائها الأسبق شيمون بيريز هجومَ قانا الأولَ، وتمَّت هذه المجزَرة في مركز قيادة فيجي التابع ليونيفل في قرية قانا جنوبَ لُبنانَ، حيث قامت قواتُ الاحتلالِ الإسرائيليِّ بقصفِ المقَرِّ بعد لجوء المدنيِّينَ إليه هرَبًا من عمليةِ عناقيدِ الغضبِ التي شنَّتها إسرائيلُ على لُبنانَ، وأدَّى قصفُ المقَرِّ إلى مَقتَلِ 106 من المدنيِّينَ، وإصابة الكثيرِ بجروحٍ، وقد اجت"},{"id":5608,"era":"c15","t":"منظمة التحرير الفلسطينية تلغي كل البنود التي لا تعترف بإسرائيل .","s":"قامَت منظمةُ التحريرِ الفِلَسْطينية بتعديل الميثاق الوطنيِّ الفِلَسْطينيِّ، وألغَت منه كلَّ البنودِ التي لا تَعتَرِف بإسرائيلَ."},{"id":5609,"era":"c15","t":"اتفاق الخليل بين الفلسطينيين واليهود .","s":"قدَّمَت السُّلْطة الفِلَسْطينية تنازلاتٍ جديدةً بعد عودة حزب الليكود إلى الحكم برئاسة بنيامين نتنياهو المعارِض لاتفاقِ أوسلو، فتمَّ تَوقيعُ اتفاقٍ في 15 يناير يَقْضي بتقسيمِ مدينةِ الخليل إلى قِسمَينِ: قسمٍ يَهوديٍّ في قلبِ المدينة، بما فيها الحرم الإبراهيمي، وقِسمٍ عربيٍّ يشمَلُ الدائرةَ الأوسعَ للمدينةِ، وتمَّ وَضعُ تَرتيباتٍ أمنيةً قاسيةً ومُعقَّدةً؛ لضمانِ أمنِ 400 يهوديٍّ مُقيمينَ في وَسَطِ ا"},{"id":5610,"era":"c15","t":"بغداد توقع رسميًّا مع الأمم المتحدة اتفاق \"النفط مقابل الغذاء\" .","s":"بلَغَت مأساةُ الشعبِ العِراقي بسبب الحصار الاقتصادي المفروضِ تحتَ عُنوان قراراتِ مجلسِ الأمنِ الدوليِّ ذُروةً خطيرةً، أثارت احتجاجاتِ المنظمات الإنسانية عالميًّا، فانعقدَت اتفاقيةُ \"النفط مقابلَ الغذاء\"، ليُسمَحَ للعراقِ بتصديرِ جُزءٍ محدَّدٍ من نِفطِه؛ ليستفيدَ من عائداته في شراءِ الاحتياجات الإنسانية لشعبِه، تحت إشراف الأممِ المتَّحدة!!"},{"id":5611,"era":"c15","t":"رباني وحكمتيار يوقعان اتفاق سلام في أفغانستان .","s":"وقَّعَ كلٌّ من القائدَينِ بُرهان الدين ربَّاني وقلب الدين حكمتيار اتفاقَ سلامٍ في أفغانستانَ، يَقْضي بالعملِ المشترَكِ، واقتسامِ السُّلْطة فيما بينَهما."},{"id":5612,"era":"c15","t":"حدوث انفجار في مدينة الخبر بالمملكة السعودية .","s":"حدَثَ إنفجارُ ضخم في مجمَّعِ الإسْكانِ بمدينة الخبر بالمملكة العربية السعودية الذي يَأْوي القواتِ العسكريةَ الأمريكيةَ العاملةَ في قاعدة الظهرانِ العسكريةِ الجويةِ، وقد نفَّذ الانفجارُ مجموعة من الشيعة الموالين لإيران بواسطة شاحنةٍ لنقلِ النفطِ مُفَخَّخة، ذهبَ ضحيته عَشَراتُ الأمريكيِّينَ."},{"id":5613,"era":"c15","t":"مسلمو وكروات البوسنة يتفقون على تشكيل حكومة محلية في موستار .","s":"كتطبيعٍ للعَلاقاتِ بين دُوَيْلات البوسنة وافقت كرواتيا تحتَ ضغوطٍ أمريكيةٍ على تصفيةِ دُوَيْلة كرواتِ البوسنةِ، ودمجِها في دولة الاتحاد الفيدرالي، كما أَعلن كُرواتُ البوسنةِ موافقتَهم على تسويةٍ معَ المسلمينَ والاتحادِ الأوروبي، كذلك تمَّ الاتفاقُ على تشكيلِ حكومةٍ محليةٍ في موستار."},{"id":5614,"era":"c15","t":"وقف الحرب بين روسيا والشيشان .","s":"عندما أعْيَت المقاومةُ الشيشانيةُ القواتِ الروسيةَ، لجأ الرئيس الروسي بوريس يلتسين إلى جنراله ألكسندر ليبيد من أجْلِ التوصُّلِ لتسويةٍ سياسيةٍ، تُنْهي عَجَلة الحرب هناك بأقلِّ خسائرَ ممكنةٍ، ففي يوم 31 أغسطس 1996م، وبعد مفاوضاتٍ معَ ألكسندر ليبيد، سكرتير مجلس الأمن الروسي السابق، وقَّع أصلان مسخادوف ما يُعرف باتفاقياتِ \"خسف يورت\"، التي كان يُفترَض أنْ توقِفَ القتالَ ضدَّ القوات الروسية، وتَبِعَت ذ"},{"id":5615,"era":"c15","t":"فوز \"علي عزت بيجوفيتش\" في انتخابات البوسنة والهرسك .","s":"انتُخِب علي عزت بيجوفيتش أوَّلَ رئيسِ جمهوريةٍ للبوسنةِ والهرسكِ، بعد انتهاء الحرب الرهيبة في البوسنة، وُلد في مدينة بوسانا كروبا البوسنيةِ، لأسرةٍ بُسنويةٍ عريقةٍ في الإسلامِ بمدينةِ \"بوسانسكي شاماتس\"، واسمُ عائلته يمتدُّ إلى أيام الوجود التركي بالبوسنةِ، فالمقطع (بيج) في اسم عائلته هو النطق المحلي للقب (بك) العثماني، ولقبُه (عزت بيجوفيتش) يعني ابن عزت بك. تعلَّم في مدارس مدينة سراييفو، وتخرَّج ف"},{"id":5616,"era":"c15","t":"سيطرة حركة طالبان على العاصمة الأفغانية كابول .","s":"سَيْطَرت حركةُ طالبان على العاصمة الأفغانية كابولَ، بعدَ مواجهاتٍ عنيفةٍ، وقتلت الحركةُ الرئيسَ نجيب الله في مَقَرِّ الأممِ المتحدةِ، وفرَضَت تطبيقَ الشريعة الإسلامية على البلاد."},{"id":5617,"era":"c15","t":"عزل بنظير بوتو رئيسة الوزراء الباكستانية .","s":"قام الرئيسُ الباكستانيُّ فاروق ليغاري بعزلِ بناظير بوتو رئيسةِ الوزراء الباكستانية، وذلك بسبب اتِّهامها بالفساد وعدم الأهليَّة، وقام أيضًا بحلِّ الجمعية الوطنية، وعَيَّن مالك مراج خالد رئيس المجلس الوطني الأسبق على رأس حكومةٍ انتقاليَّةٍ، حتى يحينَ مَوعدُ الانتخابات الجديدة."},{"id":5618,"era":"c15","t":"أصلان مسخادوف يفوز في أول انتخابات رئاسية في الشيشان .","s":"كان أصْلان مسخادوف عضوًا بارزًا في المفاوضات التي دارت بينَ القادةِ الشيشانِ والمسؤولينَ الروسِ تمهيدًا لاستقلال الشيشانِ عن جمهوريةِ روسيا الاتحاديةِ، وذلك في مدينة جروزني خلالَ صيفِ عامِ 1995م، حينَ وُقَّعَ عن الجانبِ الشيشاني اتِّفاقًا معَ الروس حولَ المسائلِ العسكريةِ.وانتهى النزاعُ الأولُ في العام 1996م، حيث شاركَ مسخادوف في المفاوضات التي دارت معَ ممثِّلي الحكومة الفيدرالية الروسية في مدينة "},{"id":5619,"era":"c15","t":"السوريون يعلنون الإضراب الشامل في قرى ومدن الجولان .","s":"أَعْلن السوريون الإضرابَ الشامل في قرى ومدن الجولانِ؛ وذلك احتجاجًا منهم على فرض القانون الإسرائيليِّ على الجولانِ السورية المحتلَّةِ.ويرجِعُ هذا القانون إلى تاريخ 14/12/1981م، حيث أقرَّت الكنيست الإسرائيلية تطبيقَ القانون الإسرائيلي على الجولانِ المحتلِّ، واعتبار سكانه مواطنينَ إسرائيليِّينَ، وسُمِّيَ القانون آنذاك بـ\"قانون الجولان\"، وقد قوبلَ هذا القانونُ بالرفض من قِبَل الأمم المتحدة، واعتبرَتْ"},{"id":5620,"era":"c15","t":"تولي محمد خاتمي رئاسة إيران خلفًا لهاشمي رفسنجاني .","s":"وُلد محمد خاتمي في مدينة أردكان في إيرانَ، نشأ خاتمي في كنَف أسرةٍ تُركمانيةٍ مُتديِّنةٍ، ودخلَ مدرسةَ قُمَّ الدينيةَ عامَ 1961م، بعد إنهائه دراستَه الابتدائية، ودرس الفلسفةَ، وحصلَ على إجازة البكالوريوس في الفلسفة من جامعة أصفهانَ، واستكملَ دراستَه الدينيةَ بعد ذلك في معهد قُمَّ، وفي العام 1970م عاد ليدرسَ العلوم التربوية في جامعة طهرانَ، وعاد بعدَها إلى قُمَّ لدراسة علم الاجتهاد.في عهد الشاه كان"},{"id":5621,"era":"c15","t":"أمريكا تتقدم بمشروع لنقل سفارتها في إسرائيل إلى القدس .","s":"تقدَّمت وزارة الخارجية الأمريكية بمشروعٍ لتخصيص 100 مليون دولار، وذلك لنقلِ السفارة الأمريكية في إسرائيلَ إلى القُدسِ، وذلك بعد موافَقةِ مجلسِ النوَّابِ الأمريكي على الاعترافِ بالقُدسِ عاصمةً موَحَّدةً لإسرائيلَ، بأغلبية عُظْمى."},{"id":5622,"era":"c15","t":"وفاة المحقق محمود محمد شاكر .","s":"نشأ محمود شاكر في بيتِ عِلمٍ؛ فأبوه كان شيخًا لعُلماء الإسكندرية، وتولَّى منصبَ وكيلِ الأزهر لمدة خمس سنواتٍ (1909م-1913م)، واشتغل بالعملِ الوطني، وكان من خُطباءِ ثورةِ 1919م، وأخوه العلَّامةُ أحمد شاكر واحدٌ من كِبار مُحَدِّثي العصر، وله مؤلَّفاتٌ وتحقيقاتٌ مشهورةٌ ومُتداوَلة.انصرف محمود شاكر -وهو أصغرُ إخوتِه- إلى التعليم المدَني، فالتحق بالمدارس الابتدائية والثانوية، وكان شغوفًا بتعلُّمِ الإنجل"},{"id":5623,"era":"c15","t":"التحالف المعارض لحركة طالبان يُعيِّن برهان الدين رئيسا لأفغانستان .","s":"قام التحالفُ الشماليُّ المعارضُ لحركة طالبان بتعيينِ بُرهان الدين ربَّاني رئيسًا لأفغانستانَ، وهو ثاني رئيس في كابولَ بعد سقوطِ الحكم الشيوعي فيها في إبريل 1992م، وكان قد خرج من كابول في 26 سبتمبر 1996م، على يد حركة طالبان، وظلَّ ينتقلُ في ولايات الشمال التابعةِ له. ويُعَدُّ ربَّاني أحدَ أبرز زعماء تحالُف المعارَضة الشمالي السياسيِّين، والمعارِض لطالبان.ربَّاني من مواليد 1940م في مدينة فيض آباد مر"},{"id":5624,"era":"c15","t":"وفاة أبي الحسن الندوي .","s":"وُلد أبو الحسن النِّدْوي بقرية تكية، مديرية رائي بريلي، بالهندِ عام 1332هـ/ 1913م، وتعلَّم في دار العلومِ بالهندِ (ندوة العلماء)، والتحق بمدرسة الشيخ أحمد علي في لاهور، حيث تخصَّص في علم التفسير، كان الشيخ ماتُريديًّا نشيطًا للعمل الإسلامي، سواءٌ في الهند، أو خارجَها، وقد شارَكَ -رحمه الله- في عدد من المؤسَّسات والجمعيات الإسلامية، ومنها تأسيسُ المجمَع العِلمي بالهندِ، وتأسيس رابطة الأدب الإسلامي،"},{"id":5625,"era":"c15","t":"اتفاق واي ريفر بلانتيشن بين عرفات ونتنياهو .","s":"وقَّعه عرفات ونتنياهو في 23 أكتوبر، وتضمَّن الانسحابَ الإسرائيليَّ من 13% من أراضي الضفة، وإطلاق سَراح بِضعِ مئات من أصل 3000 مُعتَقَل سياسي فِلَسْطيني، والسماح بتشغيل مطار غزَّةَ، والسماح بطريق آمِنٍ بين الضفة والقطاع، واتخذ هذا الاتفاق شكلًا أمنيًّا أكثرَ تشددًا؛ إذ كان شرط تنفيذه أن يُصَعِّد الطرفُ الفِلَسْطيني جهودَه ضدَّ المعارَضة الفِلَسْطينية، ويُصادرَ الأسلحة بناءً على خُطة أمنية مجدوَلة، "},{"id":5626,"era":"c15","t":"حرب كوسوفا من قبل الصرب للتطهير العرقي .","s":"قامت القواتُ والميليشيات الصربيةُ والكُرواتيةُ بعمليات وَحشيةٍ ضدَّ مُسلِمي البوسنة والهرسك وكوسوفو، باسم التطهير العِرقي، حيث اجتاحَ الصربُ أراضيَ البوسنة ومدنَها؛ لتنفيذ خُطتهم، للاستيلاء على أراضي هذه الجمهورية، وطرد المسلِمينَ منها، حتى تكون خالصةً فقطْ للصربِ، ومن أجْل ذلك ارتكَبَ الصربيونَ صُنوفًا من أبشعِ الجرائمِ التي لم يشهَدْ لها تاريخُ أوروبا مثيلًا منَ القتلِ والظلم، والدمار، والاغتصاب"},{"id":5627,"era":"c15","t":"وفاة الشيخ محمد متولي الشعراوي .","s":"وُلد الشيخ محمد متولي الشعراوي في 15 إبريل عامَ 1911م بقرية دقادوسَ مركز ميت غمر بمحافظة الدقهلية، وحفِظَ القرآنَ الكريمَ في الحاديةَ عَشْرةَ من عُمرِه. وفي عام 1916م التحَقَ بمعهدِ الزقازيق الابتدائي الأزهري، وأظهَرَ نبوغًا منذُ الصغَرِ في حِفظِه للشعرِ والمأثورِ من القول والحِكَم، ثم حصَلَ على الشهادة الابتدائية الأزهرية سنةَ 1923م، ودخَلَ المعهدَ الثانوي، وزاد اهتمامُه بالشعرِ والأدَبِ، وحَظِيَ"},{"id":5628,"era":"c15","t":"انفجاران هائلان يدمران سفارتي أمريكا في كينيا وتنزانيا .","s":"في أعنفِ هُجومٍ ضدَّ أهدافٍ أمريكيةٍ في مِنطقةِ شَرق إفريقيا‏،‏ لَقيَ حوالَيْ 80‏ شخصًا مَصرَعَهم‏،‏ من بينهم ‏8‏ أمريكيِّينَ‏،‏ وأُصيبَ أكثرُ من ألفٍ آخَرينَ‏،‏ في انفجارَيْنِ كبيرَيْنِ استهدَفا في وقت واحدٍ سِفارتَيِ الولايات المتحدة في كينيا وتنزانيا‏.‏"},{"id":5629,"era":"c15","t":"هيئة التحكيم الدولية تؤكد سيادة اليمن على جزر حنيش .","s":"تقَعُ جزيرةُ حنيش في الجزء الجنوبي من البحر الأحمر بالقُرب من باب المندَب، ومنذُ الانتداب البريطاني على جنوب اليَمَن، واليمنُ تُعِدُّ الأرخبيلَ جُزءًا منها، وكذلك أريتريا، حيث عدَّها الجانبان جزءًا منهما، فوقع نزاعٌ بين البلدَيْنِ أدَّى إلى الاقتتال بينَهما، فلجأت اليَمَنُ إلى لجنة التحكيم الدولية التي حكَمَت لصالح اليَمَن، وخلُصَت إلى الإقرار بتَبَعيَّة أرخبيل حنيش للجمهورية اليَمَنية، وذلك بحضور"},{"id":5630,"era":"c15","t":"اتفاق الأرض مقابل الأمن بين ياسر عرفات ورئيس الوزراء الإسرائيلي .","s":"توصَّلَ الرئيسُ الفِلَسْطيني ياسر عرفات، ورئيس الوزراء الإسرائيلي إلى اتفاقِ الأرضِ مُقابلَ الأمنِ، حيث ستُنَفِّذ إسرائيلُ مرحلةً جديدةً من إعادة الانتشار في 13% من الضفة الغربية مُقابلَ قيام السُّلْطة الفِلَسْطينية بتكثيف حملتها ضدَّ العنف."},{"id":5631,"era":"c15","t":"وفاة عائشة عبد الرحمن الشهيرة ببنت الشاطئ .","s":"عائشةُ عبد الرحمن (بنتُ الشاطئ) أستاذةٌ جامعيةٌ، وباحثةٌ وكاتبةٌ، وُلدت في مدينة دمياطَ بشمالِ دلتا مصرَ في منتصفِ نوفمبر عامَ 1913م، وهي ابنةٌ لعالمٍ أزهريٍّ، وتعلَّمت وقتَذاكَ في المنزل، وفي مدارس القرآن (الكُتَّابِ)، ومن المنزل حصَلَت على شهادة الكفاءةِ للمُعلِّمات عامَ 1929م، ثم الشهادةِ الثانوية عامَ 1931م، والتحَقَت بجامعة القاهرة لتتخرَّجَ من كلية الآداب قسم اللغة العربية عامَ 1939م، ثم نال"},{"id":5632,"era":"c15","t":"بدء عملية ثعلب الصحراء ضد العراق .","s":"وهي ضربةٌ عسكريةٌ جويةٌ قامت بها الولايات المتحدة الأمريكية، وبريطانيا على العراق، واستمرت لمدة أربعة أيامٍ، وقد جَرَت العملية عقِبَ ادعاءِ عدم تعاوُنِ العراق مع مُفَتِّشي الوَكالة الدولية بحثًا عن أسلحة الدمار الشامل العراقية المزعومة، وقد تركَّز القَصفُ على أهدافٍ في بغدادَ، كما تمَّ إلحاق ضررٍ كبيرٍ بالبِنَى التحتية العراقية، وذهب ضحايا من الأبرياء العراقيين خلالَ هذه العملية."},{"id":5633,"era":"c15","t":"وفاة الملك حسين بن طلال ملك المملكة الأردنية الهاشمية .","s":"هو حُسين بن طلال بن عبد الله بن الحسين، ثالثُ ملوك الأُردُنِّ، ينتهي نسبُه لآل البيت من الفرع الحَسَني، وُلد بعَمَّان سنةَ 1935م، وتلقَّى علومَه الأُولى بها، ثم انتقل للدراسة بكلية فكتوريا بالإسكندرية، ثم انتقلَ لإنجلترا، والتحق بكلية سانت هيرست العسكرية سنةَ 1950، وكان بصُحبة جَدِّه الملك عبد الله لحظةَ اغتياله سنةَ 1951م، وأُصيب في الحادث إصابةً طفيفةً، وبعد تنصيب أبيه طلال على عرش الأُردُنِّ بأ"},{"id":5634,"era":"c15","t":"اختطاف القائد الكردي \"عبد الله أوجلان\" .","s":"قامت مجموعةٌ من قواتِ الكوماندوس التركيةِ بخطفِ القائد الكردي \"عبد الله أوجلان\"، وهو في دولة كينيا، وذلك في 15 فبراير 1999م، وأعادته إلى تركيا، في عملية مشتركة بين قوات وَكالة الاستخبارات المركزية الأمريكية (CIA)، ووَكالة الاستخبارات الوطنية التركية (MIT)، وتمَّ نقلُه بعدَها جوًّا إلى تركيا.وُلد \"أوجلان\" عام 1949م، وأسَّس حزب العمَّال الكردستاني ذا الميول الشيوعية، ونفَّذ عددًا من العمليات الإرهاب"},{"id":5635,"era":"c15","t":"إجراء استفتاء حول مشروع حكم ذاتي في مقاطعة تيمور الشرقية .","s":"اتَّفَقت إندونيسيا والبرتغال على تنظيم استفتاءٍ حولَ مشروعِ حُكمٍ ذاتيٍّ في مُقاطعةِ تيمور الشرقية المستعمرةِ البُرتغاليةِ السابقة التي ضمَّتها إندونيسيا عام 1976م. وقد عبَّرَ 78،5% من الناخبين في الاستفتاء الذي أُجريَ في 30 أغسطس برعاية الأمم المتحدة عن تأييدهم لاستقلالِ تيمور الشرقيةِ، ممَّا أثار غضبَ الموالين لحكومة إندونيسيا. واجتاحت الإقليمَ موجةٌ من أعمال العُنف الخطيرة بهدف تهجير سكانِه، أد"},{"id":5636,"era":"c15","t":"اتفاقية شرم الشيخ بين عرفات وإيهود باراك .","s":"وُقِّعت اتفاقيةٌ في شرم الشيخ بمصرَ بين كلٍّ من ياسر عرفات، وإيهود باراك رئيس الوزراء الإسرائيلي، وهي نُسخةٌ مُعدَّلةٌ من اتفاقية واي ريفر -اتفاقية بين إسرائيل والسلطة الفلسطينية-، حضر التوقيعَ الرئيس المصري، وملكُ الأُردُنِّ، وتتعلَّقُ بموضوع تعجيل إعادة الانتشار، وتمديد فترة الحُكم الذاتي إلى سبتمبر 2000م."},{"id":5637,"era":"c15","t":"وفاة إمام العصر عبد العزيز بن عبد الله بن باز .","s":"وُلِدَ الشيخ عبد العزيز في الرياض في الثانيَ عَشَرَ من ذي الحِجة سنةَ 1330ه،ـ ونشأ في بيئة علمٍ وصلاحٍ، حفِظ القرآنَ قبل أنْ يبلُغَ سنَّ البلوغ، وكان قد بدأ يضعُفُ بصرُه إثْرَ مرضٍ أصابَه في عينَيْه حتى فقَدَ بصرَه نهائيًّا سنةَ 1350هـ، وعمرُه 20 عامًا، فزاد ذلك من هِمَّته لطلب العلمِ مُلازمًا العلماءَ بذكاءٍ مُفرطٍ، وذاكرةٍ حادَّةٍ، وسرعةِ بَديهةٍ، واستحضارٍ لمسائل العلمِ، معَ ما أُوتيَ من فِراسة"},{"id":5638,"era":"c15","t":"إسرائيل تتوسع في ضم المستوطنات في الضفة الغربية وغزة .","s":"تَولَّى حزبُ العملِ الحُكمَ في إسرائيلَ برئاسة إيهود باراك، وواصَلَت إسرائيلُ عمليةَ توَسُّعِها الاستيطانيِّ، حيث صدرت الأوامرُ بإنشاء 2600 وحدةٍ سكنيةٍ في المُستَوطَنات القائمة في الضفة الغربية وقطاع غزَّةَ، بالإضافة إلى طرح عطاءات ببناءِ 3370 وَحْدةً سكنيةً جديدةً مُوزَّعةً على العديد من المستوطناتِ بالضفة الغربية وقطاع غزَّةَ، وقد رافقت هذا المخططَ حملةٌ إعلاميةٌ ضخمةٌ؛ لتضليلِ الرأي العام العا"},{"id":5639,"era":"c15","t":"محكمة أمن الدولة التركية تحكم على أوجلان زعيم الأكراد بالقتل .","s":"حَكَمَت محكمةُ أمن الدولة في تركيا على عبد الله أوجلان بالقتل، وصادقت محكمةُ التمييز على الحُكم، ولكنَّ محكمة أمن الدولة التركية حوَّلت قرار القتل إلى الأشغال الشاقَّة المؤَبَّدة مدى الحياةِ عقِبَ إلغاءِ البرلمان التركي عقوبةَ القتل في البلادِ من عام 2002م."},{"id":5640,"era":"c15","t":"تولِّي محمد بن الحسن عرش المغرب .","s":"محمد السادس، هو محمدُ بنُ الحسنِ بنِ محمدِ بنِ يوسفَ ملكُ المغربِ، وهو الملك الثالث والعشرون للدولة العَلويَّة. تمَّت البَيْعة الشرعيَّة له ملكًا يومَ 23 يوليو 1999م، بقاعةِ العرشِ بالقَصرِ الملَكي بالرباطِ بعد وفاة والدِه الحسَن الثاني، عندما كان وليًّا للعهد كلَّفه والدُه الملكُ الحسنُ الثاني بالعديد من المهامِّ، وأوْفَدَه مبعوثًا لعدد من الدول، كما شارَكَ في العديدِ من الملتقياتِ، على المستوى ا"},{"id":5641,"era":"c15","t":"إعلان بعض مناطق جمهورية داغستان دولة إسلامية .","s":"قَدِم بعضُ المجاهِدين بقيادةِ القائدِ الشيشاني شامل باساييف وغيره من الشيشانِ، ودخَلوا إلى أراضي جمهورية داغستانَ، وقاموا بإعلان دولةٍ إسلاميةٍ في بعض مناطقِها."},{"id":5642,"era":"c15","t":"وفاة محدث العصر الشيخ محمد ناصر الدين الألباني .","s":"أبو عبدِ الرحمنِ محمدٌ ناصرُ الدِّينِ بنُ نوح نجاتي بن آدم الألبانيُّ علَّامةُ الشامِ، وُلد عامَ 1332هـ / 1914م في أشقودرة عاصمة ألبانيا آنذاكَ، نشأ في أسرة فقيرة، وكان والده مُتخرِّجًا من المعهد الشرعي في الآستانة، ثم هاجر والدُه مع أسرته إلى دِمَشقَ عندما بدأ الحاكم أحمد زوغو يَزيغُ عن الحق، ويأمُرُ بنزع الحجاب، ويَسيرُ على خُطى الطاغية أتاتورك، فدرس الشيخ محمد ناصر في دِمَشقَ المرحلة الابتدائية"},{"id":5643,"era":"c15","t":"وفاة الشيخ سيد سابق .","s":"السيد سابق صاحبُ كتابِ \"فقه السُّنة\"، تخرَّج في كليَّة الشريعة، من مواليد محافظة المنوفية مركز الباجور قرية إسطنها، بدأ يكتُب في فقه الطهارة، معتمِدًا على كتب فقه الحديث، التي تُعنى بالأحكام، مثل: (سُبل السلام) للصنْعانيِّ، شرح (بلوغ المرام) لابن حَجَر، و(نيل الأوطار) للشوْكاني، وشرح (مُنْتَقى الأخيار من أحاديث سيد الأخيار) لابن تَيْميةَ الجدِّ، وغير ذلك من المصادر المختلِفة، مثل (المُغْني) لابن ق"},{"id":5644,"era":"c15","t":"مشروع كلينتون للسلام .","s":"سعى الرئيسُ الأمريكيُّ بيل كلينتون في الأيام الأخيرة من ولايتِه إلى تقديم مشروعِ سلامٍ، فدعا الطرفَينِ الفِلَسْطيني والإسرائيلي لإجراءِ مُباحثاتٍ في واشنطنَ، وتضمَّنَ مشروعُه ما يلي:- دولةٌ فِلَسْطينيَّةٌ على 94- 96% من الضفة، و100% من القطاع، وأنْ تُعطيَ إسرائيلُ من 1-3% من أراضيها المحتلَّة عامَ 48 إلى الطرف الفِلَسْطيني.- 80% من المستوطِنينَ اليهود يُقيمونَ في مجمَّعاتٍ استيطانيةٍ.- المناطقُ ال"},{"id":5645,"era":"c15","t":"اندلاع الانتفاضة الفلسطينية الثانية .","s":"اندلَعَت الانتفاضةُ الثانيةُ في فِلَسْطينَ، وسُمِّيت بانتفاضة الأقْصى، بدأت في أعقاب زيارة زعيم المعارَضة في ذلك الوقت أرئيل شارون للمسجِدِ الأقْصى في 28 سبتمبر 2000م."},{"id":5646,"era":"c15","t":"انسحاب إسرائيل من جنوب لبنان .","s":"انسحَبَت القواتُ الإسرائيليةُ المحتلَّةُ من جنوب لُبنانَ، وذلك بعد 18 سنةً من احتلالها للأراضي اللُّبنانيةِ؛ لاكتشافها عدمَ جدوى الاحتلال من صدِّ الهجمات ضدَّ قواتها.ويبلُغُ عدد القرى المحَرَّرة التي كانت واقعةً تحت الاحتلال الإسرائيلي المباشِر 125 قريةً، بالإضافة إلى 33 قريةً أخرى كانت تحتلُّها المليشيات العميلة لإسرائيلَ، أو ما كان يُسَمَّى بجيش لُبنان الجنوبي.تتبَعُ القُرى المحرَّرةُ إداريًّا س"},{"id":5647,"era":"c15","t":"وفاة الرئيس السوري حافظ الأسد، وابنه بشار يخلفه في السلطة .","s":"وُلد حافظ سليمان الأسد في 6 أكتوبر 1930م، في مدينةِ القِرداحةِ بمحافظة اللاذقيَّةِ، لأسرةٍ كانت تعمَلُ في فلاحة الأرض، أتمَّ تعليمَه الأساسي في مدرسة قريته التي أنشأها الفرنسيون، عندما أدخلوا التعليم إلى القرى النائية، وكان أولَ مَن نال تعليمًا رسميًّا في عائلته، ثم انتقلَ إلى مدينة اللاذقيَّةِ، حيث أتمَّ تعليمَه الثانوي في مدرسة جول جمال، ونال شهادة الفرع العلمي، لكنَّه لم يتمكَّنْ من دخول كلية ا"},{"id":5648,"era":"c15","t":"إقرار معاهدة الحدود بين السعودية واليمن .","s":"تحُدُّ الجمهوريةُ اليَمَنيةُ المملكةَ العربيةَ السعوديةَ من الجنوب والجنوب الغربي، وقد وقَّعَ البَلدانِ مُعاهدةَ الحدود الدولية بمدينة جُدَّةَ في 12 يونيو 2000م، ويبلُغُ طولُ خطِّ الحدود البريَّة حوالَيْ 1314 كم. وترتبط المملكةُ معَ اليَمَن بأربعةِ منافذَ بريَّةٍ هي: الطوال في الغرب، وعلب ومنفذ الخضراء في الوسط، والوديعة في الشرق."},{"id":5649,"era":"c15","t":"مشكلة كشمير المسلمة .","s":"أعلنت الهندُ أنَّ \"جامو وكشمير\" إقليمًا هنديًّا، وأنه لن يكونَ هناك أيُّ تفاوُضٍ معَ باكستانَ بشأنها، وحذَّرت باكستانَ من اللجوء إلى القوة لحلِّ مُشكلة كشميرَ، وذكرَتْ أنَّه لا يُسمحُ باستخدام القوة حلًّا للنزاعاتِ وضرورة التواصل من خلال الحوارِ، وأنَّ الحكومةَ الباكستانيةَ لا يمكنُ أنْ تكونَ طرفًا في المفاوضاتِ بشأنِ ولاية كشميرَ التي يَسْعى سكانُها المسلمون إلى إقامة دولة مستقلَّةٍ عن الهندِ."},{"id":5650,"era":"c15","t":"الرباط تغلق مكتب إسرائيل في المغرب والمكتب المغربي في تل أبيب .","s":"أغلقَت الرباطُ مكتبَ الارتباطِ الإسرائيليِّ في المغرِبِ، والمكتبَ المغربيَّ في تلِّ أبيبَ، وذلك بعد قيام انتفاضة الأقْصى، واشترطَ المغربُ لإعادةِ فتحِ مكتبِه التمثيليِّ \"حصولَ تطورٍ في عملية السلامِ\"."},{"id":5651,"era":"c15","t":"وفاة فقيه العصر الشيخ محمد بن صالح بن عثيمين .","s":"أبو عبدِ اللهِ محمدُ بنُ صالحِ بنِ سليمانَ بنِ عبدِ الرحمنِ بنِ عُثمانَ (الذي كان مَعروفًا بعُثيمينٍ تَصغيرًا) التميميُّ، نزَحَ أجدادُه من الوشمِ إلى عُنيزةَ، التي وُلد فيها الشيخ محمد سنةَ 1347هـ في السابع والعشرين من شهر رمضانَ، في بيت علمٍ واستقامةٍ، وكان الشيخ قد رُزق ذكاءً وهمَّةً عاليةً، مع إعراضٍ عن الدنيا، يأمُرُ بالمعروف، ويَنْهى عن المنكرِ، صَبورًا حازمًا حريصًا على وقته، معَ زُهدٍ وورَع"},{"id":5652,"era":"c15","t":"تحطيم تماثيل بوذا في أفغانستان على يد حكومة طالبان .","s":"قامت حكومة طالبان بتدمير التماثيل الموجودة في أفغانستانَ، بموجِب فتاوى شرعيةٍ، وبناءً على قرارٍ من المحكمة العُليا، وقد كانت أفغانستانُ مركزًا كبيرًا للبوذيَّةِ قبل الفتح الإسلامي، في القرن الحاديَ عَشَرَ، وتحتفظُ بعددٍ كبيرٍ من التماثيل والتحف البوذيَّةِ، خصوصًا تماثيلَ عملاقةً، هي الأكبرُ في العالم لبوذا، محفورة منذ ألفَيْ عام في صخور \"باميان\"، في وَسَط البلاد، وقامت طالبان بتحطيم ثُلُثي هذه الت"},{"id":5653,"era":"c15","t":"وفاة الشيخ مقبل بن هادي الوادعي .","s":"أبو عبدِ الرحمنِ مُقبلُ بنُ هادي بنِ مُقبلِ بنِ قايدةَ الوادعيُّ الهَمْدانيُّ، نشأ يتيمًا، ونشأ في بيئة مليئةٍ بالجهل والشركِ، وقد منَّ الله عليه بالهداية، فكان يأمُرُ بالمعروفِ ويَنْهى عن المنكرِ، فأُوذيَ بسبب ذلك كثيرًا، ثم عُنيَ بطلب العلم، وخاصَّةً الحديثَ، حتى برعَ فيه، وأجاد، وكان مشهورًا بحرصه على اتِّباع السُّنة، والرد على أصحاب الأهواء والبِدعِ، مع زهدٍ، وعزوفٍ عن الدنيا، وتواضعٍ، وكرمٍ، "},{"id":5654,"era":"c15","t":"وقوع هجمات أحداث 11 سبتمر في الولايات المتحدة الأمريكية .","s":"تعرَّضت الولايات الأمريكية لسلسلة من الهجمات في 11 سبتمبر عامَ 2001م، وتركَّزت في كلٍّ من واشنطنَ، ونيويوركَ وبنسلفانيا، وبدأت هذه الهجماتُ باصطدام طائرتَينِ من طراز بوينج، بمركز التجارة العالمي -أعْلى مَبْنى في العالم- بحي مانهاتن بولاية نيويورك الأمريكية، حيث اصطدمت كلُّ طائرةٍ ببرجٍ، ممَّا أدَّى إلى سقوط البُرجين، حتى سُوِّيَا بالأرض، بعد أن اشتَعَلا بالنار لفترة قليلةٍ، كما تعرَّض مَقَرُّ وزار"},{"id":5655,"era":"c15","t":"حصار عسكري إسرائيلي على مقر الرئيس ياسر عرفات بمدينة رام الله .","s":"أعلنت إسرائيلُ أنَّ قرارَ مُغادرة الرئيس عرفات لمدينة رام الله خاضعٌ لها وَحْدَها، لتبدأَ مرحلةُ محاصرةِ الزعيم الفلسطيني في رام الله، وبعد خمسة أيام في 13/12/2001م تحركت آلياتٌ عسكريةٌ إسرائيليةٌ بينها دباباتٌ حولَ مقرِّ الرئيس عرفات، وقرَّرَ شارون رئيس الوزراء الإسرائيلي منعَه من الخروج إلى أية مدينة أخرى، وفي ذات الوقت قصفَت الطائراتُ الإسرائيليةُ مَقرَّ الرئاسة في \"المنتدى\" بغزَّةَ، ولأول مرةٍ"},{"id":5656,"era":"c15","t":"توقيع الحكومة السودانية والحركة الشعبية لتحرير السودان اتفاقًا أمنيًّا .","s":"وقَّعَت الحكومةُ السودانيةُ والحركة الشعبية لتحرير السودان اتفاقًا أمنيًّا يَسمَحُ بدمجِ القوات في مناطقَ مُعيَّنة متنازَعٍ عليها، على أن يحتفظ الطرَفانِ بقوات مسلَّحة مُنفَصِلة في المناطق الأخرى، وأن تستمر المفاوَضات حولَ القضايا السياسية والاقتصادية فيما بينَهما."},{"id":5657,"era":"c15","t":"مقتل القائد خطَّاب (ثامر السويلم) في الشيشان .","s":"ثامر بن صالح بن عبد الله السويلم المعروف بخطاب، وُلد عامَ 1389هـ في مدينة عرعر شمالَ المملكة العربية السعودية، كان جَدُّه عبد الله عُرِف في منطقة الأحساء بـالنشمي، نزحَت هذه العائلة من بلاد نجدٍ إلى الأحساء عامَ 1240هـ، وهناك وُلد أجدادُه، ووُلد فيها والد خطاب صالح السويلم الذي انتقل إلى عرعر، وهناك وُلد خطاب، ومكَث فيها حتى انتهى من الصف الرابع الابتدائي، وعُمرُه عَشْرُ سنوات، ثم انتقل والدُه بأب"},{"id":5658,"era":"c15","t":"وفاة محمد إبراهيم عقال رئيس جمهورية أرض الصومال .","s":"تُوفِّيَ محمد إبراهيم عقال رئيس وزراء الصومال الأسبقُ ورئيسُ ما يُعرَفُ بـ«جمهورية أرض الصومال» الانفصاليةِ الواقعةِ في شمالِ شرقِ البلادِ عن عُمرٍ يُناهزُ الرابعةَ والسبعينَ، إثْرَ إصابته بأزمةٍ دماغيةٍ مفاجئةٍ خلالَ عمليةٍ جراحيةٍ في مدينة جوهانسبرغ بجنوب أفريقيا، وكان عقال قد بدأ زيارةً إلى جنوب إفريقيا؛ لإجراء فُحوصاتٍ طبيةٍ عاجلةٍ، بعدما رفضت عدةُ دولٍ عربيةٍ استقبالَه رسميًّا على أراضيها، لع"},{"id":5659,"era":"c15","t":"وفاة الشيخ محمد صفوت نور الدين .","s":"محمد صفوت نور الدين أحمد مرسي وُلد في عام 1363هـ، بقرية \"الملايقة\" إحدى قرى مركز \"بلبيس\"، محافظة الشرقية في مصر، عمِلَ بالتربية والتعليم حتى صار مديرًا عامًّا، وشغَلَ منذ الثمانينيَّات وظيفةَ \"أمين عام الدعوة\"، زمنَ رئاسة الشيخ \"محمد علي عبد الرحيم\"، وتولَّى رئاسةَ جماعة أنصار السُّنة المحمدية بعدَ وفاة الشيخ محمد علي عبد الرحيم في 22 شعبان 1412هـ؛ ليكونَ سادسَ رؤساء الجماعة، كانت له مساهماتٌ كبير"},{"id":5660,"era":"c15","t":"إعلان خطة بديلة للسلام وهي ما سمي بـ \"وثيقة جنيف\" .","s":"جاء التوقيعُ على وثيقةِ جنيفَ من أجْلِ السلام في الشرق الأوسط في أول ديسمبر 2003م، ليواكبَ خريطةَ الطريق الأمريكية، وهي الوثيقةُ التي ظلَّ وزيرُ الإعلام الفِلَسْطيني ياسر عبد ربه، ووزير العدل الإسرائيلي يوسي بيلين يتفاوَضان حولهَا على مدى ثلاث سنوات، حتى تمَّ التوقيعُ عليها بحضور مئات الشخصيات الدولية، وتَدْعو هذه الوثيقة إلى إنهاء النزاع الإسرائيلي - الفِلَسْطيني، وإحلال السلام بين الطرفَينِ، وقي"},{"id":5661,"era":"c15","t":"منع ارتداء الحجاب الإسلامي داخل المدارس بفرنسا .","s":"أعلَنَ الرئيسُ الفرنسي جاك شيراك رفضَه ارتداءَ تِلميذاتِ المدارسِ المسلماتِ للحجابِ، واعتبرَه أمرًا \"عُدوانيًّا\"؛ لينضمَّ بذلك التصريح إلى زُمرةِ السياسيِّينَ الفرنسيِّينَ الرافِضينَ للحجاب في فرنسا، وليُعبِّرَ عن دعمِه لسَنِّ قانونٍ يحظُرُ الحجابَ بالمؤسَّساتِ التعليمية الفرنسية. وأعربَ شيراك عن قلقه إزاءَ ما سمَّاه بـ\"الأُصولية الإسلامية\"، مع تزايُدِ الميْلِ في فرنسا لحظرِ كلِّ الرموزِ الدينية ب"},{"id":5662,"era":"c15","t":"سقوط بغداد على يد القوات الأمريكية .","s":"سقطت العاصمةُ العراقيةُ بغدادُ على يد القوات الأمريكية التي قادت تحالفًا دوليًا بحُجةِ امتلاك النظام العراقي أسلحةً محظورةً، ورغم استيلاءِ الولايات المتحدة على مؤسَّساتِ ومرافقِ العراقِ لم تستطعْ إثباتَ صحةِ الذرائع التي اجتاحَت على أساسها العراقَ، وتسبَّبتْ في إثارةِ فَوْضى عارمةٍ، ومقتلِ آلافِ العراقيِّينَ خلالَ الحروب، وأعمال العنف الطائفي الذي شَهِدَته البلاد منذُ الغزو الأمريكي للعراقِ."},{"id":5663,"era":"c15","t":"وفاة عبدالله الطيب المجذوب المعروف بعميد الأدب السوداني .","s":"وُلدَ عبدُ اللهِ الطيبُ المجذوبُ بقرية التميراب غربَ الدامر في 25 رمضانَ 1339هـ / الموافق 2 يونيو 1921م، تعلَّم بمدارس كسلا والدامر وبربر، وكلية غردون التذكارية بالخرطوم، والمدارس العُليا، ومعهدِ التربيةِ ببخت الرضا، وجامعة لندنَ بكلية التربية، ومعهدِ الدراساتِ الشرقيةِ والإفريقيةِ، نال الدكتوراه من جامعة لندنَ (SOAS) سنةَ 1950م.وعمِلَ بالتدريس بأم درمان الأهليةِ، وكليةِ الخرطومِ الجامعيةِ، وجامعة"},{"id":5664,"era":"c15","t":"ليبيا تقر بامتلاكها أسلحة دمار شامل .","s":"أقرَّت ليبيا بامتلاكها أسلحةَ دمارٍ شاملٍ، وأعلَنت أنَّها ستتخلَّص منها جميعًا \"بإرادتها الحُرَّة\"، وهو ما لاقى ارتياحًا أمريكيًّا وبريطانيًّا، كما أعلَنَت أنَّها تتحمَّل مسؤولية تحطُّم طائرة لوكيربي عام 1988م؛ الأمر الذي دفعَ مجلسَ الأمن الدولي لأنْ يُقرِّرَ رفعَ العقوبات الدولية عن طرابلسَ، فضلًا عن قيام واشنطنَ في فبراير 2004م برفع قيودِ السفرِ المفروضةِ على السفر إليها."},{"id":5665,"era":"c15","t":"اعتقال القوات الأمريكية الرئيس العراقي صدام حسين .","s":"اعتقلت القواتُ الأمريكية الرئيسَ العراقيَّ صدَّام حُسين الذي كان مختبئًا قُربَ مَسقَطِ رأسه بتكريتَ، وشاهَدَ العالمُ صورَ صدَّام حُسين يومَ القَبضِ عليه، بلِحيته الكثَّة الطويلة، وقد خرجَ من حُفرة في مَزْرعةٍ في تكريتَ، وكان العقلُ المدبِّرُ للعملية الرقيبَ الاستخباراتي الأمريكي إريك مادوكس، وصَلَ إريك إلى العراق كمُحقِّق، وتمَّ تحويلُه إلى وَحْدة النُّخبة، وتمكَّن لاحقًا من نَيْل إعجاب فريق عملِه"},{"id":5666,"era":"c15","t":"اغتيال الرئيس الشيشاني السابق سليم خان ياندرباييف .","s":"وُلد سليم خان ياندرباييف في كازخستانَ عام 1952م، ثم عاد إلى الشيشانِ معَ عائلتِه عام 1958م، ويُعَدُّ سليم خان ياندرباييف الرجلَ الثانيَ في القيادة الشيشانية، ووصديقَ الرئيس جوهو دوداييف، شغلَ سليم خان ياندرباييف منصبَ رئيس الجمهورية المستقِلَّة لفترة قصيرةٍ عامَ 1996م، عندما بدأت الحرب الأولى التي شنَّتْها روسيا في الشيشان تُشارفُ على نهايتها. تعلَّم اللغةَ العربيةَ على يد أحدِ الطلابِ العربِ، كما"},{"id":5667,"era":"c15","t":"توقيع اتفاق مصالحة بين الحكومة السودانية والحركة الشعبية لتحرير السودان .","s":"إعلانُ اختتام مفاوضات الهيئة الحكومية الدولية المعنيَّة بالتنمية (IGAD) بشأن السلام في السودان من قِبَل حكومة السودان والجيش الشعبي/الحركة الشعبية لتحرير السودان، جيجيري، نيروبي، 19 نوفمبر 2004م، وينصُّ اتفاقُ نيفاشا بكينيا الذي وقَّعَتْه حكومةُ الخرطوم مع قرنق في 9 يناير/ كانون الثاني 2003م على وضع حدٍّ للحرب الأهلية التي دارت في جنوب السودانِ أكثرَ من 20 عامًا، وعلى أنْ تُشكَّل حكومةٌ انتقاليةٌ "},{"id":5668,"era":"c15","t":"مقتل الشيخ أحمد ياسين مؤسس حركة حماس بفلسطين .","s":"وُلد أحمد ياسين في يونيو/حزيران عام 1936م، في قرية جورة عسقلان - شماليَّ قطاع غزَّةَ - نزحَ مع عائلته إلى قطاع غزَّةَ بعد حرب عام 1948م، أصابه الشللُ في جميع أطرافه أثناءَ ممارسته للرياضة في عامه السادسَ عَشَرَ. استطاع أنْ يُنهيَ دراستَه الثانوية في العام الدراسي 1958م، ثم الحصول على فرصة عمل رغمَ الاعتراض عليه في البداية بسبب حالته الصحية، وحينَ بلوغِه العشرين بدأ أحمد ياسين نشاطَه السياسيَّ بالم"},{"id":5669,"era":"c15","t":"مقتل عبد العزيز الرنتيسي أحد مؤسسي حركة حماس بفلسطين .","s":"وُلِد عبد العزيز علي عبد الحفيظ الرنتيسي عام 1947م في قرية يبنا (بين عسقلان ويافا)، لجأت أسرتُه بعد حرب 1948م إلى قطاع غزَّةَ، واستقرَّت في مخيم خان يونس للاجئين، وكان عمرُه وقتَها ستةَ شهورٍ، التحَقَ وهو في السادسة من عُمره بمدرسةٍ تابعةٍ لوَكالة غوث وتشغيل اللاجئين الفِلَسْطينيين، واضطر للعمل أيضًا، وهو في هذا العمر ليُسهِم في إعالة أسرته الكبيرة التي كانت تمرُّ بظروف صعبةٍ، أنهى دراسته الثانوية"},{"id":5670,"era":"c15","t":"\"العزيمة القذرة\" والهجوم الأمريكي على الفلوجة .","s":"شنَّت قوات الاحتلال الأمريكي هجومًا شاملًا على الفلوجة في عملية سمَّتها بعملية \"العزيمة القذرة\" أدَّت إلى مَقتَل 700 عراقي."},{"id":5671,"era":"c15","t":"مقتل الرئيس الشيشاني الموالي لروسيا أحمد قاديروف .","s":"قُتل الرئيس الشيشاني الموالي لروسيا أحمد قديروف في انفجارٍ وقَعَ بأحد الملاعب الكُبرى بالعاصمة الشيشانية جروزني، وكان الملعب الرياضي دينامو أحدَ أكبرِ الاستادات بالعاصمة الشيشانية قد شهِد احتفالاتِ روسيا بذِكْرى الانتصارِ على القوات النازية في الحرب العالمية الثانية، غيرَ أنَّ الانفجارَ الناجمَ عن لَغَمٍ أرضيٍّ، تمَّ زَرْعُه في وقت سابق أسفرَ عن سقوط 32 قتيلًا، منهم الرئيس، بالإضافة إلى ما يزيدُ ع"},{"id":5672,"era":"c15","t":"تعذيب العراقيين بسجن أبو غريب على يد قوات الأمريكية .","s":"سجنُ أبو غريب هو في منطقة أبو غريب على بعد 32 كم من العاصمة بغدادَ، الذي أصبحَ معروفًا بعد دخول قوات التحالفِ العراقَ بإساءة معاملة السجناء، تمَّ بناءُ السجن من قِبَل مُتعهِّدين بريطانيِّين على مساحة 1.15 كم2، مع 24 برجًا أمنيًّا، وقد تمَّ اعتقال كثيرٍ من العراقيِّين في هذا السجن من قِبَل القوات الأمريكية، وظهرت صور تُبيِّن طرقَ تَعذيب المساجين العراقيِّين وإذلالهم، وتصويرهم، وتكديسهم عُراةً من قِ"},{"id":5673,"era":"c15","t":"القوات الإسرائيلية تجتاح مخيم رفح جنوب قطاع غزة .","s":"اجتاحت قواتُ الاحتلال الإسرائيلي مخيمَ رفَحَ جنوبَ قطاع غزَّةَ، ممَّا أدَّى إلى مَقتَلِ العَشَرات، وإصابةِ المئاتِ من الفِلَسْطينيِّين، وتدمير عَشَرات المنازل، ومن المناطق التي تضرَّرت في مدينة رفَحَ نتيجةَ الاجتياح: تل السلطان، ورفح الغربية، وحي السلام، وجزء من منطقتي الجنين وقشطة."},{"id":5674,"era":"c15","t":"وفاة الشيخ رزق خليل حبة شيخ المقارئ المصرية السابق .","s":"تُوفي الشيخ رزق خليل حبَّة شيخُ عمومِ المقارئِ المصريةِ سابقًا، وقد وُلد بقرية كفر سليمان البحري بمحافظة دمياط شماليَّ مصرَ سنةَ 1918ماستمع إلى الشيخ أبي العينين شعيشع، وكان لا يزال فتًى صغيرًا، فأثَّرَ فيه تأثيرًا كبيرًا، فعزم على حفظ القرآنِ، وحفِظَه على الشيخ حسن سعيدة شيخ قريته، انتسب الشيخ رزق إلى الأزهر، ودرس فيه، ونال شهادةَ تخصُّص القراءات من كلية اللغة العربية، وعمِل مدرسًا بمعهد القراءات"},{"id":5675,"era":"c15","t":"اعتراف حكومة جمهورية صرب البوسنة رسميًّا بمسؤوليتها عن مجزرة سربرينتشا .","s":"اعترَفَت حكومةُ جمهورية صرب البوسنة رسميًّا بأنَّ القوات الصربية تتحمَّل مسؤولية قتل آلاف المسلمين في مجزرة سربرينتشا، التي وقعت خلالَ الحربِ الأهلية في البوسنة عام 1995م، وقد جاء هذا الاعترافُ ضِمنَ تحقيقٍ رسميٍّ أجْرَته سُلْطات صرب البوسنة في المجزرة التي تعتبرُها المحكمة الدولية لجرائم الحرب في لاهاي نوعًا من الإبادة الجماعية، وأقرَّت اللجنةُ التي أجْرَت التحقيقَ بوقوع انتهاكاتٍ \"جسيمةٍ\" لحقوق "},{"id":5676,"era":"c15","t":"القوات الأمريكية في العراق تسلم السلطة إلى الحكومة العراقية المؤقتة .","s":"سلَّمت القواتُ الأمريكية في العراق السُّلْطةَ رسميًّا إلى الحكومة العراقية المؤقَّتة، وذلك عن طريق تبادُل وثائق بين الحاكم الأمريكي للعراق بول بريمر، ورئيس الوزراء العراقي الشيعي إياد علاوي، الذي كانت تربِطُه علاقاتٌ بوَكالة المخابرات المركزية الأمريكية، بينما تولَّى غازي الياور الزعيم العشائري السُّني رئاسةَ العراق؛ ليُصبح أولَ رئيسٍ بعد الإطاحة بالرئيس العراقي صدَّام حُسين."},{"id":5677,"era":"c15","t":"الحكومة المصرية تطلق سراح الجاسوس الإسرائيلي عزام عزام .","s":"أطلَقَت الحكومةُ المصريةُ سَراحَ الجاسوسِ الإسرائيلي عزَّام عزَّام المسجون في مصرَ منذُ عام 1997م، وكان ذلك مقابلَ إطلاقِ إسرائيلَ لسَراح 6 طلبة مصريين مُعتَقَلينَ لدَيْها، وهو ما كان له ردودُ فِعلٍ غاضبةٌ لدى المصريين، بينما فرِحَ الإسرائيليون بالإفراج عن عزَّام.وعزَّام عزَّام من مواليد عام 1963م، دُرْزي إسرائيلي، أُدينَ في مصر بتُهمة التجسس لصالح العدو الإسرائيلي، وسُجن لثماني سَنَوات قبلَ إطلاق"},{"id":5678,"era":"c15","t":"حظر الحجاب في فرنسا .","s":"بدأ سَرَيان العمل بقانون حَظرِ الحِجابِ، أو أي رموز دينيةٍ أُخرى في المدارس والمؤسسات الحكومية في فرنسا."},{"id":5679,"era":"c15","t":"وفاة الرئيس الفلسطيني ياسر عرفات .","s":"اسمُه الحقيقيُّ عبدُ الرؤوف عرفات عبد الرحمن القدوة، واسمُه الحركيُّ: ياسر عرفات أبو عمَّار، وُلد في القاهرة بحي السكاكين في حارة اليهود، بتاريخ 24/08/1929م. جَدُّه عبد الرحمن القدوة قدِمَ من المغرب إلى القُدسِ في أواخر القرن التاسعَ عَشَرَ، لازم الشيخَ عصام السعيد في المسجد الأقْصى يُعينه في كلِّ ما يطلب منه، ثم تزوَّج ابنتَه -وكانت عانسًا ومُقْعَدةً- فأنجبا ولدًا واحدا سمَّياه عرفات، تزوَّج ياسر"},{"id":5680,"era":"c15","t":"عملية \"أيام الندم\" واجتياح إسرائيل لقطاع غزة .","s":"قامت إسرائيلُ باجتياح شمال قطاع غزَّةَ في عملية سمَّتها \"أيام الندم\" قُتل فيها حوالَيْ 130 فِلَسْطينيًّا، بينهم 30 طفلًا، وأُصيب ما يزيدُ عن 400 فِلَسْطينيٍّ، واستمرت هذه العملية 17 يومًا، هُدمت فيها عَشَراتُ المنازلِ، وجُرِّفت مساحاتٌ زراعيةٌ واسعةٌ."},{"id":5681,"era":"c15","t":"وفاة الشيخ زايد بن سلطان رئيس دولة الإمارات .","s":"الشيخُ زايدُ بنُ سلطانٍ آلَ نهيانَ، هو أولُ رئيسٍ لدولة الإمارات العربية المتحدة، وحاكمُ إمارة أبو ظبي، وُلد عامَ 1918م، في مدينة أبو ظبي بقصر الحصن، وتولَّى الشيخُ زايدٌ حُكم العين عام 1946م، وافتُتِحَت في عام 1959م أولُ مدرسةٍ بالعين حملَت اسمَ المدرسةِ النهيانية، كما تمَّ إنشاءُ أولِ سوق تجاريةٍ وشبكة طرق، ومَشفًى طبي، وقام بإعادة النظر في ملكية المياه، وجعَلَها على نُدرتها متوفرةً للجميع، بالإ"},{"id":5682,"era":"c15","t":"وفاة الشيخ عبد القادر الأرناؤوط .","s":"هو قَدْري بن صَوْقَل بن عَبْدُول بن سِنَان المشهور بعبد القادر الأرناؤوط، وُلد سنةَ 1347هـ بقرية «فريلا» في «إقليم كوسوفا» من بلاد الأرنؤوط في ما كان يُعرف بيوغوسلافيا، والألبانيون يُسمُّون هذا الإقليم: كوسوفا، والصرب يقولون: كوسوفو، والأرنؤوط جِنسٌ يندَرِجُ تحته شعوبٌ كثيرةٌ من الألبان واليوغسلاف وغيرهم هاجَرَ سنةَ 1353هـ من جرَّاء اضطهاد المحتلِّين الصرب إلى دِمَشقَ بصحبةِ والدِه وبقيَّةِ عائلته"},{"id":5683,"era":"c15","t":"كارثة تسونامي بأندونيسيا وشرق آسيا .","s":"تجاوَزَت حصيلةُ المدِّ البحْري الذي ضرب سواحلَ المحيطِ الهندي ال 280000 ألفِ قتيلٍ ومفقودٍ، في كلٍّ من أندونيسيا (أكثر من 228000)، وسريلانكا (30957)، وتايلاند (3134)، والهند (10744). وكان سببُ ذلك زلزالًا عنيفًا وقع في جزيرة سومطرة الإندونيسية، وتسبَّب في ظاهرة تسونامي، وموجات مدٍّ بحْريٍّ عاتيةٍ، اندفعت بسرعة تَزيدُ عن 600 كم، وبعُلوٍّ وصلَ إلى قُرابةِ 20م في بعض الأحيان."},{"id":5684,"era":"c15","t":"إشهار إسلام ستة من زعماء قبائل الكونغو في مؤتمر ليبيا .","s":"أشهرَ 6 من زعماء القبائل في جمهورية الكونغو الديمقراطية إسلامَهم بالعاصمة الليبية \"طرابُلُسَ\"، وذلك بحضور عددٍ من الشخصيات الإسلامية المشاركةِ في المؤتمرِ العامِّ السابعِ للدعوة الإسلامية، والذي كان مُنعقِدًا بليبيا."},{"id":5685,"era":"c15","t":"انتخاب حامد كرزاي رئيسًا لجمهورية أفغانستان .","s":"وُلد حامد كرزاي بقرية بولاية قندهار، وكان والده من وجهاء طائفة بوبلزي، ومساعدًا لمجلس الوزراء في ستينيات القرن العشرين، تخرَّج في مدرسة محمود هوتكي الابتدائية بكابولَ، ثم التحَقَ بكلية العلوم السياسية والعلاقات الدولية في الهند، حيث أنهى دراستَه هناك، واشتغَلَ بأمور تربويةٍ في مدارسِ باكستانَ إبَّانَ الغزو السوفيتي لأفغانستانَ، وبعد مجيء حكومة الأفغان عام 1996م أصبحَ مساعدًا لوزير الخارجية.انتُخِب"},{"id":5686,"era":"c15","t":"عملية الحديد البرتقالي واجتياح الاحتلال الإسرائيلي مُخيَّم خان يونس .","s":"شنَّت قواتُ الاحتلال الإسرائيلي عمليةَ اجتياح لمُخيَّم خان يونس جنوبَ قطاع غزَّةَ سمَّتها \"الحديد البرتقالي\"، دمَّرت خلالَها نحوَ أربعين منزلًا تدميرًا كليًّا، وشرَّدت نحوَ خمسينَ عائلةً يَزيدُ عدد أفرادها عن أربع مئة فردٍ. وسيطَرَت على مقبرة الشهداء في المدينة، وكانت هذه العملية على حدِّ زعمهم تهدُف إلى منع إطلاق قذائف هاون من هذا المُخَيَّم على المستوطَنات اليهودية القريبة."},{"id":5687,"era":"c15","t":"انتخاب محمود عباس رئيسًا للسلطة الفلسطينية .","s":"تمَّ ترشيحُ محمود عباس كمرشحٍ رئاسيٍّ للسُّلْطة الفِلَسْطينية من قِبَل حركة فتح، ليُصبحَ رئيسًا للسُّلْطة الفِلَسْطينية خلَفًا لياسر عرفات."},{"id":5688,"era":"c15","t":"توقيع مصر وإسرائيل وأمريكا على اتفاقية إنشاء المناطق الصناعية المؤهلة .","s":"وقَّعت مصرُ وإسرائيلُ وأمريكا اتفاقيةً بإنشاء المناطق الصناعية المؤهلة المعروفة اختصارًا باسم كويز، في القاهرة، وتنصُّ الاتفاقيةُ على إقامة 3 مناطق حرة هي (القاهرة الكبرى، والإسكندرية، وبورسعيد) للسوق الأمريكية دون رسوم جمركية شريطةَ أنْ تكون 11،7% من مكوناتها إسرائيليةً، وهو ما أثار احتجاجًا شعبيًّا كبيرًا."},{"id":5689,"era":"c15","t":"الأردن يوقع اتفاقية مع إسرائيل بإنشاء المناطق الصناعية المؤهلة .","s":"وقَّع الأُردُنُّ اتفاقيةً مع إسرائيلَ بإنشاء المناطق الصناعية المؤهلة المعروفة اختصارًا باسم كويز، وهو ما اعتبَرَه البعض خطوةً جديدةً لربط الاقتصاد الوطني الأُردُنِّيِّ بالاقتصاد الصِّهْيَوْني."},{"id":5690,"era":"c15","t":"حركة المقاومة الإسلامية \"حماس\" تفوز في انتخابات بلديات غزة .","s":"حقَّقَت حركة المقاومة الإسلامية \"حماس\" فوزًا في انتخابات بلديات غزَّةَ، حيث حصلت على نسبة 65،25 %، مقابلَ حصول حركة فتح على 22%، وحصل المرشحون المستقلُّونَ على 4،23%، والجبهة الشعبية على نسبة 0،84%، بينما فازت عائلة المصدر على 7،62%."},{"id":5691,"era":"c15","t":"أول قمة بين الرئيس الفلسطيني عباس ورئيس وزراء إسرائيل شارون .","s":"عُقدت أولُ قمةٍ بين الرئيس الفِلَسْطيني محمود عباس ورئيس الوزراء الإسرائيلي أرييل شارون بحضور الرئيس المصري، والعاهل الأردني في شرم الشيخ المصرية، حيث أعلن عباس وشارون وقفَ \"أعمال العُنف\"، وتعهَّدت دولتا مصر والأردن بإعادة سفيريهما إلى إسرائيلَ."},{"id":5692,"era":"c15","t":"مقتل الرئيس الشيشاني آصلان مسخادوف .","s":"نفَّذَت قواتٌ روسيةٌ خاصةٌ تُساندُها القواتُ الشيشانيةُ -المواليةُ لموسكو- عمليةَ اغتيال، قُتل على إثْرها الزعيمُ والرئيسُ (الشرعي) لجمهورية الشيشان أصلان مسخادوف، داخلَ الأراضي الشيشانية، وُلد أصلان مسخادوف في 21 / 9 /1951م بجمهورية كازاخستانَ في الفترة التي كان الشعب الشيشاني قد نُفي خلالها إلى آسيا الوسطى وسيبيريا (تشمل منطقة آسيا الشمالية)، وفي عام 1957م عاد أصلان مسخادوف مع والدَيْه من كازاخس"},{"id":5693,"era":"c15","t":"وفاة أمير الكويت جابر الصباح .","s":"تُوفي الشيخُ جابر الأحمد الصباح أمير الكويت عن 77 عامًا، وخلالَ فترة حُكمه التي بدأت عام 1977م واستمرَّت نحوَ ثلاثة عقودٍ، مرَّت منطقة الخليج بأحداث بالغةِ الأهميَّة، من أبرزها قيامُ الثورة الإسلامية في إيرانَ عامَ 1979م، وإعلان قائدها الخُميني اعتزامَه تصدير الثورة لدول المنطقة، ثم قامت حربُ العراقِ وإيرانَ في عام 1980م، واستمرَّت نحوَ ثماني سنواتٍ، وفي عام 1990م قام صدَّام حُسين بغزو الكويت، واض"},{"id":5694,"era":"c15","t":"اغتيال رئيس الوزراء اللبناني السابق رفيق الحريري .","s":"يُعَدُّ رفيقٌ الحريريُّ الذى اغتيلَ في قلب العاصمة اللُّبنانية بيروتَ واحدًا من أبرز الساسة اللُّبنانيِّين الذين لعِبوا دَورًا هامًّا في الحياه السياسية بلُبنان، وقد وُلد رفيق بهاء الحريري في صيدا عام 1944م، وأنهى دراسته الثانوية في لُبنان، وحصل على إجازة في العلوم التجارية من جامعة بيروت العربية، وسافَرَ بعد تخرُّجه في الجامعة للعمَل في المملكة العربية السعودية، وحصل علي الجنسية السعودية، وفي عام"},{"id":5695,"era":"c15","t":"جلال الطلباني رئيسًا للعراق .","s":"انتخَبَ البرلمانُ العراقيُّ يومَ الأربعاء في 27/2/1426هـ، (الزعيمَ الكُرديَّ) جلال الدين طالباني رئيسًا جديدًا مؤقتًا للعراق، بعد أسابيع من المفاوَضات بين القائمتَينِ الشيعية والكُردية، وقد جرَت هذه الانتخابات تحت رعاية القوات الأمريكية، ومقاطعة السُّنة لها، ويُعَدُّ طالباني أولَ زعيم كُردي يتولَّى منصبًا على هذه الأهمية في الدولة العراقية، التي يُشكِّلُ فيها الأكرادُ نسبةَ 20% تقريبًا."},{"id":5696,"era":"c15","t":"قيام أمينة ودود بإمامة المصلين في صلاة الجمعة بإحدى كنائس نيويورك .","s":"قامت أمينة ودود أستاذة الدراسات الإسلامية بجامعة فيرجينيا كومونولث الأمريكية بإمامةِ مجموعةٍ من النساء والرجال سويًّا في صلاة الجمُعة، بعدَ أنْ ألقَت خُطبةَ الجمُعة عليهم، وقد اتخذت أمينة ودود هذه الخطوةَ غيرَ المسبوقة ضمنَ الاحتفال بيوم المسلم بالولايات المتحدة، وقد أُقيمت هذه الصلاةُ في إحْدى الكنائس الأنجليكانية بنيويوركَ بعد أنْ رفضت المساجدُ استضافتَها، حيث رفضَت ثلاثةُ مساجدَ بنيويوركَ أداءَ"},{"id":5697,"era":"c15","t":"انسحاب سوريا من لبنان .","s":"بإعلانٍ من الرئيس السوري بشار حافظ الأسد سُحِبَت قواتُ سوريا من لُبنان على مرحلَتَينِ: إلى البقاع أولا، ثم الحدود الدولية مع لُبنان، وكانت القواتُ السورية أصلًا قد دخلَت إلى لُبنان بعد اتفاق الطائف الذي أنهى الحربَ الأهلية في لُبنان عامَ 1989م، وكان من مُقرَّرات هذا الاتفاق أنْ تكونَ القواتُ السوريةُ هي عنصر الأمان في لُبنان، والفاصل بين هذه القوى الأهلية المتحارِبة، وبَقِيَت في لُبنان كلَّ هذه ال"},{"id":5698,"era":"c15","t":"توقيع اتفاق سلام بين الحكومة الإندونيسية ومتمردي آتشيه .","s":"قامت الحكومةُ الإندونيسية بتوقيعِ اتفاقِ سلامٍ بينَها وبين مُتمرِّدي آتشيه، وذلك بالعاصمة الفِنلندية هِلسنكي، وكان الاتفاقُ يهدُف إلى إنهاء واحدٍ من أطولِ الصراعاتِ في آسيا، والذي راح ضحيتَه أكثرَ من 12 ألفًا على مدى ثلاثة عقودٍ."},{"id":5699,"era":"c15","t":"مصر وإسرائيل توقعان اتفاقًا لبيع الغاز الطبيعي المصري لإسرائيل .","s":"وقَّعت مصرُ وإسرائيلُ اتفاقًا لبيع الغاز الطبيعي المصري لإسرائيلَ بعد أن تأجَّلَ التوقيعُ أكثرَ من مرةٍ بسبب خلافاتٍ حولَ الترتيبات النهائية للاتفاقِ، وذلك من خلال خط أنبوب يبدأ من منطقة الشيخ زُوَيِّد بشرق العريش بشبهِ جزيرة سيناءَ، وهي نفس نقطة انطلاقِ خطِّ الغاز العربي الواصل إلى كلٍّ من الأُردُنِّ وسوريا ولُبنان، ويمتدُّ الخطُّ إلى منطقة عَسْقلان بفِلَسْطينَ."},{"id":5700,"era":"c15","t":"وفاة الملك فهد بن عبد العزيز ملك المملكة العربية السعودية .","s":"الملكُ فهدُ بنُ عبدِ العزيزِ هو الابنُ التاسعُ من أبناء الملك عبدِ العزيزِ آلَ سعودٍ الذكور -رحمهما اللهُ- وهو خامسُ ملوك المملكة العربية السعودية، وأولُ مَن تلقَّب بخادم الحرمَينِ الشريفَينِ رسميًّا بإعلانه ذلك في المدينة المنورة، تولَّى مقاليدَ الحُكم في 21 شعبان 1402هـ الموافق13 يونيو 1982م، وذلك بعد وفاة أخيه غير الشقيق الملك خالد بن عبد العزيز، تعرَّض الملك فهد إلى جَلْطة في عام 1995م، وتولَّ"},{"id":5701,"era":"c15","t":"انتخاب مسعود البارزاني رئيسًا لإقليم كردستان العراق .","s":"انتُخِبَ مسعود البارزاني من قِبَل المجلس الوطني لكُردستان العراق بالإجماع كأول رئيس مُنتَخَب لإقليم كردستانَ في تاريخ الشعب الكردي، وقام مسعود البارزاني بأداء اليَمَينِ الدستورية كرئيسٍ لإقليمِ كُردستان العراق لمدة 4 سنواتٍ."},{"id":5702,"era":"c15","t":"مقتل المخرج الهولندي لفيلم \"الاستسلام\" والذي أساء فيه للإسلام .","s":"قُتِل المخرجُ الهولندي ثيو فان جوخ مخرج فيلم \"الاستسلام\"، والذي أساء فيه للإسلام، حيث قتَلَه المسلم الهولندي المغربي الأصل محمد بويري، وقد تمَّت إدانتُه، وصدر فيه حكمٌ بالسجن مدى الحياة، وهي أقْصى عقوبة في القضاء الهولندي."},{"id":5703,"era":"c15","t":"مصرع جون جارانج (قرنق) زعيم الجيش الشعبي لتحرير السودان .","s":"وُلد جون جارانج في عام 1945م في قبائل دينكا جنوبَ السودان، لعائله نصرانية من قبائل الدينكا الجنوبية المعروفة بعبادة السماء، وقد أرسلته عائلتُه إلى الولاياتِ المتحدة لتلقِّي تعليمِه، فدرسَ في كلية جرنيل، بولاية أيووا، ثم عاد إلى السودان عام 1982م، معَ بداية الحرب الأهلية معَ حركة أنانيا الجنوبية، ثم عاد إلى الولايات المتحدة مرةً ثانيةً لتلقِّي تدريب عسكري في فورت بينينج، جورجيا، وكان أولَ اختبار لج"},{"id":5704,"era":"c15","t":"وفاة الداعية الإسلامي أحمد ديدات .","s":"تُوفيَ الداعيةُ الإسلاميُّ الشهيرُ أحمد ديدات، بعد أنْ قَضى سنواتٍ عديدةً على فراش المرضِ، في مدينة (ديربان)، وكان قد قدَّم خِدْماتٍ جليلةً للإسلام في مجال الدعوة إلى الله، واشتَهَر بمناظراتِه للنصارى، ومحاضراتِه حولَ تناقُض الإنجيل (الموجود حاليًّا بين أيدي النصارى)، ممَّا أدَّى إلى إسلام عدد كبيرٍ على يدَيْه، وأُصيب الشيخ ديدات بمرض عُضالٍ منذُ عام 1996م، أجبره على لزوم الفراش، وقد أحدث دويًّا ه"},{"id":5705,"era":"c15","t":"تنصيب \"سلفا كير\" لمنصب ‏النائب الأول للرئيس السوداني .","s":"بدأ سلفا كير حياتَه العسكريةَ جُنديًّا في الجيش السوداني قبلَ أنْ يَلتحِقَ بقوات جارانج، وفي عام 1986م أصبحَ نائبًا لقائد الأركان، ومكلَّفًا بالعمليات في الجيش الشعبي لتحرير السودان، وفي عام 1997م أصبحَ نائبًا لجارانج في قيادة الحركة، وفي الوقت نفسِه قائدًا عسكريًّا لقواتها المسلَّحة في بحر الغزال.ثارت الإشاعاتُ منذُ عامِ 1998م حولَ خلافه مع جون جارانج، وبأنَّه كان يُخطِّط لانقلابٍ داخلَ الحركة ال"},{"id":5706,"era":"c15","t":"انقلاب عسكري بموريتانيا على الرئيس معاوية ولد الطايع .","s":"تمَّت الإطاحةُ بنظام الرئيس معاوية ولد الطايع، وإنشاء مجلس عسكري يتولَّى الحُكمَ في البلاد، وكان الرئيس الموريتاني معاوية ولد الطايع، الذي يحكُم البلادَ منذ 20 عامًا، قد غادَر إلى السعودية لتقديم العزاء بوفاة الملك فهد بن عبد العزيز -رحمه اللهُ- ولكنَّ الجيش منعَ الطائرة الرئاسية من الهبوط في مطار نواكشوط، فاضطرَّ الرئيسُ للتوجُّهِ إلى نيامي عاصمة النيجر."},{"id":5707,"era":"c15","t":"إجراء أول انتخابات برلمانية في منطقة \"دولة أرض الصومال\" ‏الانفصالية .","s":"أجرَت منطقةُ دولة أرض الصومال الانفصالية انتخاباتٍ برلمانيةً لاختيارِ أعضاءِ البرلمانِ البالغِ عددُهم 28 عضوًا، وهي أولُ انتخابات برلمانية على أساسٍ حزبيٍّ تشهَدُها المستعمرةُ البريطانيةُ السابقةُ منذُ إعلان دولة أرض الصومال من جانبٍ واحدٍ، وانفصَلَت أرضُ الصومال عن مقديشو بعد أنْ أطاح زعماءُ الميليشيات بمحمد سياد بري."},{"id":5708,"era":"c15","t":"وفاة مكتوم بن راشد نائب رئيس دولة الإمارات .","s":"تُوفيَ مكتوم بن راشد بن سعيد آل مكتوم الفلاسي حاكم إمارة دبي منذُ عام 1990م حتى 2006م، أكبر أبناء الشيخ راشد بن سعيد آل مكتوم، والأخ الأكبر للشيخ محمد بن راشد آل مكتوم، وحاكم دبي شقيق الشيخ حمدان بن راشد آل مكتوم. وُلد الشيخُ مكتوم في منطقة الشندغة في دبي سنةَ 1943م، وقد أكمَلَ تعليمَه في أوائل الستينيات في دبي وأرسلَه والدُه لمواصلة تعليمه في إحْدى الجامعات البريطانية، وحينَ أَعلَنَت بريطانيا سنة"},{"id":5709,"era":"c15","t":"كارثة غرق عبارة السلام المصرية في البحر الأحمر .","s":"غرِقَت العبَّارة المصريةُ \"السلام 98\" في مياه البحر الأحمر وعمرُها 25 عامًا، وتبلُغُ حمولتُها 6650 طنِّا، وكانت تُقِلُّ أيضًا 22 سيارةً، و16 شاحنةً، وخمس سيارات بضائعَ، فقد تهاوَت إلى أعماق مياه البحر الأحمر، وعلى مَتنِها نحوُ (1400 شخصٍ)، وعُدَّ حوالَيْ 1000 شخصٍ منهم ما بين قتيلٍ ومفقودٍ."},{"id":5710,"era":"c15","t":"صحيفة فرنسية تعيد نشر الرسومات المسيئة للنبي صلى الله عليه وسلم .","s":"في إساءةٍ مقصودةٍ ثانيةٍ كرَّرت صَحيفةٌ فرنسيةٌ نشرَ الصورِ الكاريكاتوريةِ المُسيئةِ لنبيِّ الأمةِ محمدٍ صلَّى اللهُ عليه وسلَّمَ على صفحاتِ جرائدِها، رغمَ ما ظهَر من غضبٍ عارمٍ اجتاحَ الأمةَ الإسلاميةَ بعد نشرِ ذاتِ الرسوماتِ في صحيفةٍ دنماركيةٍ سابقًا، وزادت الصحيفةُ الفرنسيةُ من إثارةِ نفوس المسلمين في إيرادها تعليقاتٍ على بعض الرسومات بأنَّها \"رسوماتٌ طريفةٌ\"، زاعمةً أنَّ نشرَ هذه الرسومات الك"},{"id":5711,"era":"c15","t":"إنشاء المعارضة السورية جبهة موحدة للإطاحة بالرئيس بشار الأسد .","s":"اتَّفَق معارِضون سوريون يُقيمون في الخارج خلالَ اجتماعٍ في بروكسلَ على إنشاء جبهة موحَّدة للإطاحة بالرئيس بشار الأسد بالوسائل الديمقراطية، على رأسهم عبد الحليم خدام النائب السابق للرئيس، والذي انشقَّ على الأسد، وقد ضمَّت مفاوَضات بروكسلَ 17 سياسيًّا من الحركات المعارِضة من قوميِّين، ولِيبراليِّين، وإسلاميِّين، وأكراد وشيوعيِّين، وكان من ضِمنِهم المراقبُ العامُّ للإخوانِ المسلمينَ في سوريا علي صدر "},{"id":5712,"era":"c15","t":"تطبيع العلاقات الليبية الأميركية بعد ثلاثين سنة من التوترات بينهما .","s":"قرَّرت واشنطنُ في بيانٍ لوزارة خارجيتِها إعادةَ عَلاقتِها الدبلوماسية معَ ليبيا، وإعادةَ فتحِ سفارتها في طرابلُسَ. وقالت وزيرة الخارجية كوندوليزا رايس، في بيانٍ صحفيٍّ: \"يُسعِدُني أنْ أُعلنَ أنَّ الولايات المتحدة استأنَفَت العلاقاتِ الدبلوماسيةَ الكاملةَ معَ ليبيا\"، وتأتي هذه الخطوة بعد قطيعةٍ دبلوماسيةٍ بين طرابلُسَ وواشنطنَ دامت منذ عام 1980م، بالإضافة إلى ذلك قرَّرت واشنطنُ شطبَ ليبيا من لائحة "},{"id":5713,"era":"c15","t":"مقتل أبي مصعب الزرقاوي زعيم تنظيم القاعدة في بلاد الرافدين .","s":"أحمد فاضل نزال الخلايلة، المشهور بأبي مصعب الزرقاوي، سافَرَ إلى أفغانستانَ في ثمانينيَّات القرن العشرين لمحارَبة القوات السوفييتة، ومكَثَ الزرقاوي سبعَ سنواتٍ في السجون الأردنية، وذلك بعد القبض عليه في الأُردُنِّ بتُهمة التخطيط لمهاجمة إسرائيلَ، وبعد مغادرة الزرقاوي السجنَ، غادرَ مرةً أُخرى إلى أفغانستانَ، ومكَثَ فيها حتى أوائل عام 2000م، وكان أمير تنظيم \"قاعدة الجهاد في بلاد الرافدين\"، الذي هو فر"},{"id":5714,"era":"c15","t":"المحاكم الإسلامية بالصومال تعين الشيخ عويس رئيسًا للبرلمان .","s":"حسن ظاهر عويس، شيخٌ وناشطٌ سياسيٌّ صوماليٌّ، انتُخِب رئيسًا لبرلمان اتحاد المحاكم الإسلامية بعد سيطرتِها على مقديشو، ومعظم مناطقِ جنوبِ الصومال. وُلد الشيخُ عامَ 1935م، وهو من أكثر قادة المحاكم الإسلامية في الصومال نفوذًا، يَنْتَمي لجيل المؤسِّسين لمنظمة الحركة الجهادية الصومالية التي بدأت نشاطَها في مقاوَمة حُكم الرئيس الصومالي الأسبق محمد سياد بري، وكانت تَسْعى لإقامة دولةٍ على أساس القِيَم الإس"},{"id":5715,"era":"c15","t":"القوات الصهيونية تبدأ حربًا على غزة أُطلق عليها \"أمطار الصيف\" .","s":"توغَّلت القوات الإسرائيلية في غزَّةَ بشكل واسعٍ منذُ انسحابِها من القطاع في عملية أُطلق عليها \"أمطار الصيف\"، وقامت فيها بقصف محطَّات توليد الكهرباء والجسور، واضطرَّ آلاف الفِلَسْطينيِّين أنْ يَفِرُّوا من بُيوتهم نتيجةً للاجتياحات العسكرية المستمرة، والقصف الشديد، ودخلت كمية محدودةٌ من المساعدات الإنسانية قطاع غزَّةَ بعد إغلاق مَعبَر المنطار (كارني) بشكلٍ كاملٍ، أطلق الجيش الإسرائيلي عمليتَه العسكر"},{"id":5716,"era":"c15","t":"وفاة القائد الشيشاني شامل باسييف .","s":"وُلد باسييف أو عبد الله شامل كما كان يُسمِّي نفسَه، أو \"أبو إدريس\" في الشيشان في عام 1965م في قرية ديشني فيدينو الواقعة جنوبَ الشيشانِ، وفي عام 1987م انتسَبَ لمعهد الهندسة في موسكو، وبعد أنْ أتمَّ دراستَه في المعهد التحقَ بالجيش السوفييتي آنذاكَ لأداء الخدمةِ العسكرية، وعاد باسييف إلى الشيشان عقِبَ تفكُّكِ الاتحاد السوفيتي، وحينَ أعْلنَ الرئيس الشيشاني الراحل جوهر دوداييف استقلالَ بلاده عن موسكو ف"},{"id":5717,"era":"c15","t":"الصهاينة يشنون حربًا واسعة على لبنان لمدة 33 يومًا .","s":"بدأت حربُ الـ 33 يومًا بين العدو الصِّهْيَوْني وحزبِ اللهِ، وذلك بعد ما قام الحزب بأسر جنديَّيْنِ وقَتل 8 عندَ موقع تلة الراهب في مشارفِ بلدةِ عيتا الشعب في جنوبِ لُبنانَ، وتمَّ بهذه الحرب قتلُ أكثرَ من 1200 لُبنانيٍّ، وجُرحَ أكثرُ من 4000 مواطنٍ من الجنوب وكافَّة الأراضي اللُّبنانية، كما قام الصهاينةُ بقصف جميع الجسور في لُبنانَ من الجنوب إلى الشمال إلى البقاع، والوسط، والجبل، وقامت أيضًا بأكثرَ "},{"id":5718,"era":"c15","t":"القوة الأمنية الدولية \"إيساف\" تتولى السيطرة على جميع أنحاء أفغانستان .","s":"أصبحت القوةُ العسكريةُ الأمريكيةُ-الأوروبيةُ هي التي تُباشرُ مهامَّ العملِ العسكري لأفغانستانَ، وأطلقوا عليها اسمَ \"قوة المساعدة الأمنية الدولية (ISAF)\"، وتتكوَّنُ قوة الإيساف من 32 ألفَ جنديٍّ، ينتمون إلى 37 بلدًا، ثم تسلَّمَ حلف الناتو قيادة قوة المساعدة، وأصبحت هذه القوةُ مسؤولةً بالكامل عن الأمن في جنوب أفغانستانَ، ثم أُضيفت منطقة شرق أفغانستانَ إلى مسؤوليات قواتِ الناتو.وأصدرَ مجلسُ الأمن الد"},{"id":5719,"era":"c15","t":"المحاكم الإسلامية في الصومال تعلن الجهاد ضد القوات الإثيوبية .","s":"انسحَبَت قواتُ الحكومة الصومالية من مدينة بورهكبا 190 كم غربَ العاصمة مقديشو، بعدَ استيلائها عليها بمسانَدة قواتٍ إثيوبيةٍ، فيما أعلنت المحاكمُ الإسلاميةُ الجهادَ داعيةً الشعب الصومالي إلى تلبية نداء الجهادِ ضدَّ القوات الإثيوبية الغازية، والتي اعتدت على ترابِ الصومال، واتهمت إثيوبيا بشنِّ هجومٍ على الصومال، مؤكدةً أنَّ أكثرَ من 30 ألفَ جنديٍّ قد توَغَّلوا داخلَ الصومال خلالَ الفترة الأخيرة، واستَ"},{"id":5720,"era":"c15","t":"اتحاد المحاكم الإسلامية في الصومال يحكم سيطرته على مدينة كيسمايو .","s":"أحكمَت قواتُ اتحاد المحاكم الإسلامية في الصومال سيطرتَها الكاملةَ على مدينة كيسمايو الإستراتيجية الواقعة جنوبيَّ البلاد دونَ قتالٍ، بعدَ فرارِ زعماءِ تحالُفِ المليشيا التي كانت تُسيطرُ على المدينة، والمنطقة الجنوبية، وقد أكَّدَ رئيس مجلس اتحاد المحاكم الإسلامية في الصومال شريف شيخ أحمد أنَّ كيسمايو انضمَّت إلى المحاكم طوعًا، وأنَّ قوات المحاكم توجَّهت إلى المدينة بطلب من الأهالي."},{"id":5721,"era":"c15","t":"وفاة الشيخ صفي الرحمن المباركفوري .","s":"صفي الرحمن بن عبد الله بن محمد أكبر المباركفوري الأعظمي، وُلد في 6 يونيو 1943م بقرية من ضواحي مباركفور، وهي معروفة الآنَ بشرية حسين آباد، تعلَّم في صباه القرآنَ الكريمَ، كما حصَلَ على الشهادة المعروفة بشهادة «مولوي» في فبراير سنة 1959م، ثم حصَلَ على شهادة «عالم» في فبراير سنة 1960م من هيئة الاختبارات للعلوم الشرقية في مدينة الله أباد بالهند، ثم حصَلَ على شَهادةِ الفَضيلة في الأدبِ العربيِّ في فبرا"},{"id":5722,"era":"c15","t":"قتل الرئيس العراقي صدام حسين .","s":"بعد أنْ تمَّ القبضُ على الرئيس العراقي صدَّام حُسين من قِبَل القوات الأمريكية، وبَقيَ في السجن وعُقدت له عدةُ جلَسات محاكمةٍ، دامت قُرابةَ الثلاث سنواتٍ، كان نهايتُها هو الحكم عليه بالإعدام شنقًا، وقد اختارت القيادةُ العراقية الجديدة التي يتزعمُها الشيعة يومَ عيد الأضْحى لتنفيذ حُكم الإعدامِ، فكان يومُ السبت في العاشر من ذي الحِجة 1427هـ هو يومُ تنفيذ الحُكم الموافق 30 ديسمبر، وتمَّ تنفيذ حكم الإع"},{"id":5723,"era":"c15","t":"اتفاق مكة المكرمة بين حماس وفتح لحقن الدماء .","s":"تعهَّد قادةُ حركَتَيْ حماس وفتح الفِلَسْطينيَّتينِ في مكَّة المكرَّمة بحقن الدماء الفِلَسْطينية، وتشكيل حكومة وَحْدة وطنيَّة، وَسْطَ تأكيدات بضرورة الوصول إلى اتفاقٍ، وقال الرئيس الفِلَسْطيني محمود عباس مُفتَتِحًا الجلسةَ: \"لن نخرُجَ من هذا المكان المقدَّس إلَّا ونحن مُتَّفِقون\"، ومن جانبِه قال رئيسُ المكتَب السياسي لحماس خالد مشعل في كلمة ألقاها بعد الرئيس الفلسطيني: \"جئنا لنتَّفِق، ولن نغادرَ هذ"},{"id":5724,"era":"c15","t":"إسرائيل تبدأ بهدم باب المغاربة وتغلق جميع منافذ القدس .","s":"قامت الجرَّافاتُ الإسرائيليةُ بمباشَرة عمليةِ هدمٍ في الطريق التاريخيةِ المؤديةِ إلى باب المغاربة، وذلك بهدف إجراءِ تَغْييراتٍ جِذْريةٍ في محيطِ المسجدِ الأقْصى المبارَكِ؛ لإعداد المنطقة لبناء الهيكل المزعومِ، وقامَت الجرَّافات بهدم غُرفتَينِ محاذِيَتَينِ لحائط البُراقِ، الأمر الذي يمكِّنُ من اقتحامِ مسجدِ البُراقِ، وتَحويلِه إلى كنيسةٍ، وحينَها قامت قواتٌ كبيرةٌ من الشرطة، والجيش، والقوات الخاصة "},{"id":5725,"era":"c15","t":"انفجار المواجهات بين القوات الحكومية اليمنية والمتمردين .","s":"بدأت المرحلةُ الرابعة للصراعِ اليَمَني الحوثي بقيادة \"عبد الملك\"، أحد أبناء \"الحوثي\"، والذي كان يتمركَزُ معَ أنصارِه في محافظة صعدة ذات الأغلبية الشيعية، وهي منطقةٌ جبليةٌ مناسبةٌ للاحتماء بها، وتعوقُ القواتِ الحكوميةَ من استهدافِهم، كما أنَّهم يحمِلونَ السلاحَ بشكلٍ كبيرٍ جدًّا من خلال انتشاره في القبائل اليَمَنية، وما تمُدُّهم به إيرانُ الموالونَ لها."},{"id":5726,"era":"c15","t":"تعيين 30 سيدة مصرية في منصب قاض لأول مرة في تاريخ مصر .","s":"أدَّت ‏30‏ قاضيةً مصريةً اليَمينَ القانونية‏،‏ إيذانًا بدخولِ المرأة المصرية محرابَ القضاءِ لأولِ مرةٍ‏ في تاريخ مصرَ."},{"id":5727,"era":"c15","t":"اتفاق المصالحة بين الرئيس السوداني عمر البشير والتشادي إدريس ديبي .","s":"برعايةٍ سُعوديةٍ وقَّع الرئيسان السوداني عمر حسن البشير، والتشادي إدريس ديبي اتفاقًا للمُصالَحة بين البلدَينِ، وذلك في ختام قمةٍ حضَرَها الملك عبد الله بن عبد العزيز في قصره بالجنادرية على بعد 40 كم شمال شرقيَّ الرياض."},{"id":5728,"era":"c15","t":"وفاة أمير منطقة مكة المكرمة الأمير عبد المجيد بن عبد العزيز .","s":"وُلد الأمير عبد المجيد بن عبد العزيز سنةَ 1362هـ، 1943م في الرياض، ونشأ في رعايةِ والدِه، وتلقَّى تعليمَه الأوليَّ على يد الشيخ عبد الله بن عبد الغني خياط، وتعلَّم منه القرآنَ الكريمَ، ومبادئَ العلوم الدينية، ثم انتقَلَ إلى مدرسة الأنجال في الرياض، فدرسَ المرحلة المتوسطة، ثم التحَقَ بالقوات البحْرية السعودية عامَ 1374هـ، وسافَرَ إلى بريطانيا للدراسة.تولَّى إمارة تبوكَ سنةَ 1400هـ، وعندما تُوفيَ أم"},{"id":5729,"era":"c15","t":"اندلاع معارك عنيفة بين الجيش اللبناني وجماعة \"فتح الإسلام\" .","s":"قامت معاركُ في \"مخيَّم نهر البارد\" بين الجيش اللُّبناني وقوى الأمن الداخلي من جهة، ومجموعات \"فتح الإسلام\" من جهة ثانيةٍ، ويتزعَّمُ حركة \"فتح الإسلام\" شاكر العَبْسي، وهو مسلَّح فِلَسْطيني معروفٌ، وقد حُكم على العَبْسي في الأردُنِّ بالقتل غيابيًّا بسبب قتله الدبلوماسي الأمريكي لورانس فولي، في العاصمة عمانَ عامَ 2002م، وشهِدَت الأحداث تصعيدًا عاليًا للمواجَهة المسلَّحة عندَما بدأ الجيشُ اللُّبنانيُّ "},{"id":5730,"era":"c15","t":"عقد اتفاق بين الحكومة اليمنية والحوثيين .","s":"تلقَّت الحكومةُ اليَمَنية بيانًا موَقَّعًا من عبد الملك الحوثي القائد الميداني لجماعة الحوثي، يؤكِّدُ فيه قَبولَه دعوة الرئيس علي عبد الله صالح إلى وقف العنف، والاقتتال حقنًا للدماء، وكذلك إعلانُه الالتزامَ بالنظام الجمهوري، ودستور البلاد، وبذلك توقَّف صراعٌ استمر لمدة ثلاث سنواتٍ، وسقط فيه المئاتُ من الجانبَينِ."},{"id":5731,"era":"c15","t":"إعصار 'جونو' العنيف يضرب دول الخليج .","s":"ضربَ إعصارُ \"جونو\" المداري العنيفُ سواحلَ سَلْطنة عُمانَ المطلةَ على بحر العرب، وبلغَت شدةُ رياحه 200 كيلومترٍ فى الساعة، ووصل ارتفاعُ الأمواج إلى 12 مترًا، وبدأت الأمطار بالهطول على جزيرة \"مصيرة\"، ومنطقة \"رأس الحد\" بشرق البلاد قبلَ وصولِ الإعصار."},{"id":5732,"era":"c15","t":"مظاهرات في باكستان ضد تكريم صاحب كتاب \"آيات شيطانية\" .","s":"نظَّمت الجماعاتُ الإسلامية في باكستانَ احتجاجاتٍ ضدَّ قرارِ بريطانيا مَنْحَ لقبِ فارسٍ إلى الكاتب سلمان رشدي، وكانت هذه المظاهرات في العاصمة إسلام أباد، وميناء كراتشي، ومدينة لاهور، كما قامت مظاهراتٌ في القطاع الذي تُديرُه الهند من كشمير، وردَّد المتظاهرون هُتافاتٍ مثلَ: \"ملعون رشدي\"، و\"تسقط بريطانيا\". وكانت رواية سلمان رشدي \"آيات شيطانية\" التي صدرت عام 1988م، قد تعرَّضت للاستنكار والإدانة من بعض "},{"id":5733,"era":"c15","t":"وفاة الفقيه الحنبلي الشيخ صالح الأطرم .","s":"تُوفيَ الشيخُ صالحُ بنُ عبدِ الرحمنِ الأطرمُ عضوُ هيئة كبار العلماء، وأستاذُ الدراسات العُليا في قسمِ الفقهِ بكلية الشريعة بجامعة الإمام محمد بن سعود الإسلامية بالرياضِ، إثْرَ مرضٍ مُزمنٍ لازَمَه سنواتٍ عدةً، والشيخُ حصَلَ على الدكتوراه من المعهد العالي للقضاء، وكان يتولَّى تدريسَ مادة الفقه المقارَن بجامعة الإمام محمد بن سعود الإسلامية بالرياضِ، بالإضافةِ إلى تدريسه لطلبة مرحلتَيِ الماجستير والدك"},{"id":5734,"era":"c15","t":"اغتيال رئيسة وزراء باكستان السابقة وزعيمة المعارضة \"بينظير بوتو\" .","s":"بينظير بوتو سياسيةٌ باكستانيةٌ، وابنةُ السياسي ورئيس باكستان السابق ذو الفقار علي بوتو، وهي من مواليد مدينة كراتشي، بعد إكمالها لدراستها في جامعة هارفارد بالولايات المتحدة، وجامعة أكسفورد في بريطانيا، عادت إلى باكستانَ بمُدَّة قليلة قبلَ الانقلاب على أبيها الذي قاده ضياء الحق، نشأت \"بنظير بوتو\" في أسرةٍ سياسيةٍ عريقةٍ، فكان جَدُّها \"السير شاهنواز بوتو\" الذي يُعَدُّ أحدَ الشخصيات السياسية المشهورة "},{"id":5735,"era":"c15","t":"إسرائيل تغلق جميع المعابر عن غزة وتمنع الغذاء والدواء عن القطاع .","s":"أصدرَ وزيرُ الدفاعِ الإسرائيلي إيهود باراك تعليماتٍ للجيشِ الإسرائيلي بإغلاق جميعِ المعابِرِ الحدوديةِ المؤدِّيةِ لقطاعِ غزَّةَ، ومنعِ حركةِ تنقُّلِ البضائعِ من وإلى القطاع بشكلٍ نهائيٍّ، وبفرضِ حظرٍ على دخول الأطعمةِ وجميعِ المستلزَماتِ الأساسية حتى الأدوية الطبية، ما عدا الضروريةَ منها، ثم قُطعَ بعد ذلك الوقودُ بشكلٍ كاملٍ عن القطاعِ، وقُطعت إمداداتُ الكهرباء، ممَّا أدَّى إلى تدهورِ الأوضاع الإن"},{"id":5736,"era":"c15","t":"وفاة الرئيس الأندونيسي الأسبق سوهارتو .","s":"تُوفيَ الرئيس الأندونيسي الأسبق سوهارتو في أحد مستشفيات جاكارتا عن 86 عامًا، وكان سوهارتو قد حكمَ أندونيسيا المكونةَ من 6 آلاف جزيرةٍ مأهولةٍ بالسكان، تمتدُّ على مسافة 3 آلاف ميلٍ، بقبضةٍ من حديدٍ لمدة 32 عامًا، إلى أنْ أسقطَتْه احتجاجات شعبيةٌ عامَ 1998م، اتُّهِم سوهارتو بالقمع وانتهاكات حقوقِ الإنسانِ، حيث إنَّه تسبَّب في مقتلِ ما يقرُبُ من مليون شخصٍ من المعارِضينَ، وسَحقَ الحركةَ الشيوعية بعد "},{"id":5737,"era":"c15","t":"اشتباكات بين الحكومة اليمنية والحوثيين وتوقيع وثيقة بينهم .","s":"تجدَّدت أعمالُ التمرُّدِ والتخريب في بعض مناطق محافظةِ صعدة بقيادة عبد الملك الحوثي، وعدد من أتباعه، وذلك بعد نحوِ 7 أشهرٍ من وقف إطلاق النار، ورغمَ توقيع الحكومة اليَمَنية والحوثيين اتفاقًا بشأن البرنامج التنفيذي لوقفِ العملياتِ العسكريةِ، إلَّا أنَّ الحوثيين رَفَضوا تنفيذ ما يُلزِمُهم به الاتفاقُ، وواصلوا اعتداءاتِهم، ورَفَضوا الاستجابةَ لعدةِ مبادَراتٍ، ومساعٍ حكوميةٍ وأهليةٍ، هدفت إلى إنهاء ال"},{"id":5738,"era":"c15","t":"وفاة جورج حبش مؤسس وأمين عام الجبهة الشعبية لتحرير فلسطين .","s":"تُوفيَ جورج حبش في العاصمة الأردنية عمَّانَ، والذي كان أحدَ أبرزِ قادة الثورة الفِلَسْطينية المعاصرة، وأحدَ مؤسِّسي حركة القوميِّين العرب، وُلد في مدينة \"اللد\" عامَ 1926م، لعائلةٍ من الروم الأرثوذوكس، وهاجَرَ في حرب 1948م من فِلَسْطينَ، درس في كلية الطب في الجامعة الأمريكية في بيروت، وتخرَّج فيها عامَ 1951 مُتخصِّصًا في طب الأطفال، فعمِل في العاصمة الأردنية عمَّانَ، والمخيَّماتِ الفِلَسْطينية، وفي"},{"id":5739,"era":"c15","t":"مؤتمر للمصالحة بين السُّنة والشيعة في العراق .","s":"شارك مئاتٌ من زعماءِ العشائر السُّنية، والشيعية، وقادة مجالس الصحوة في مؤتمر للمصالحة، عُقدَ المؤتمرُ في الثالث من يناير في جنوب بغدادَ بدعوة من التيار الصدري الذي يتزعمُه مُقْتدى الصدر، المؤتمر عُقد في خيمة نُصبت في منطقة أبو دشير (جنوب)، بحضور عدد كبيرٍ من قادةِ الأجهزة الأمنيةِ، والشرطةِ، والجيشِ، والمجالسِ المحليةِ لبلدة هور رجب، وعرب جبور السُّنِّيَّتينِ، ووسطَ إجراءات أمنيةٍ مشدَّدةٍ، وأقام "},{"id":5740,"era":"c15","t":"تفجير الحدود بين غزة ورفح وعبور ثلث سكان غزة إلى العريش .","s":"بعدما طلبَ الرئيسُ المصريُّ حسني مبارك من قوات الأمن المصرية السماحَ لفِلَسْطيني قطاع غزَّةَ بالدخول إلى مصرَ للتزوُّدِ باحتياجاتهم من الغذاء وغيره، تزايدت أعداد الفِلَسْطينيِّين التي اجتازت الحدود من غزَّةَ إلى الأراضي المصرية، وفجَّر ناشطون فِلَسْطينيونَ السور الحدودي، ووصلَت أعداد الفِلَسْطينيِّين الذين اجتازوا الحدودَ إلى نصفِ مليونِ نسمةٍ حسَبَ تقديراتٍ فِلَسْطينيةٍ، أي حوالَيْ ثلثِ سكان غزَّ"},{"id":5741,"era":"c15","t":"اغتيال عماد مغنية في دمشق .","s":"لَقيَ عماد مغنية أحد المسؤولين العسكريين في حزب الله حتفَه في انفجارٍ وقَع في منطقة كفر سوسة في قلب دِمَشق، وقد قضى أكثرَ من عقدَينِ من حياته مُتخفِّيًا. وُلد عماد مغنية في يوليو عام 1962م في مدينة صور بالجنوب اللُّبناني لأسرةٍ شيعيةٍ، وقد بدأ نشاطَه في صفوف قوات تابعةٍ لحركة فتح الفِلَسْطينية، ومكلفة بحماية الرئيس الفِلَسْطيني الراحل ياسر عرفات في أواخر السبعينيات، رغمَ أنه لُبناني شيعي من الجنوب"},{"id":5742,"era":"c15","t":"المحتل الصهيوني يقرر هدم المسجد العمري التاريخي في القدس .","s":"قرَّرَ المحتلُّ الصِّهْيَوْنيُّ هدمَ المسجدِ العُمَريَّ الواقعَ في قرية أم طوبا جنوبَ مدينة القُدسِ، وذلك بدعوى البناء غير المرخَّص دونَ سابقِ إنذارٍ، والمسجد قديمٌ جدًّا وتاريخيٌّ، فقد تمَّ تَشييدُه قبلَ نحو 700 عامٍ، وتمَّ ترميمُه عامَ 1963م، ولكنَّه بَقيَ ضيقًا لا يتسعُ لأعداد المصلِّينَ المتزايدةِ، فتمَّت توسعتُه لاستيعاب هذه الأعداد، وأثار الأمرُ حفيظةَ أبناء القرية، وقرَّروا المرابطةَ في الم"},{"id":5743,"era":"c15","t":"وفاة الشيخ بكر بن عبد الله أبو زيد .","s":"وُلد الشيخُ العلَّامةُ بكر بن عبد الله أبو زيد رئيس مجمَع الفقه الإسلامي الدولي، وعضوُ هيئة كبار العلماء، وعضوُ اللجنة الدائمة للإفتاء السابقُ، في عالية نجدٍ، عامَ 1365 هـ. درس الشيخُ في المعهد العلمي، ثم في كلية الشريعة، حتى تخرَّج فيها عامَ 1388هـ، وفي عام 1384هـ انتقَلَ إلى المدينة النبوية، فعمِلَ أمينًا للمكتبة العامة بالجامعة الإسلامية، وكان بجانب دراسته النظامية يُلازمُ حِلَقَ عددٍ من المشاي"},{"id":5744,"era":"c15","t":"عملية عسكرية في شمال قطاع غزة سميت بالشتاء الساخن .","s":"شنَّت القواتُ الإسرائيلية المحتلَّةُ عمليةً حربيةً على قطاع غزَّةَ عُرفت بـ\"الشتاء الساخن\"، واشتهَرَت إعلاميًّا باسم \"محرقة غزَّةَ\"، وهي عمليةٌ إسرائيليةٌ موسَّعةٌ، جرَت في قطاع غزَّةَ على مدار خمسةِ أيامٍ بدعوى القضاء على عناصر حركة حماس المطلِقة للصواريخِ على الأراضي الإسرائيليةِ. وقد راح ضحيتها 116 شخصًا من بينهم 26 طفلًا."},{"id":5745,"era":"c15","t":"صحيفة صهيونية تعيد نشر الرسوم المسيئة للرسول صلى الله عليه وسلم .","s":"قامت العديدُ من الصحفِ العِبريةِ ومن بينها (يديعوت أحرونوت)، و(معاريف) بنشر رسومٍ مُسيئةٍ للرسولِ محمدٍ صلَّى اللهُ عليه وسلَّمَ، وبادَرَ الفِلَسْطينيونَ بوقفِ اشتراكاتهم في الصحف احتجاجًا على إعادة نشر الرسوم، وأبدَوْا غضبَهم الشديدَ لقيام الصحيفة بنشر تلك الرسومِ، وطالبوها بالاعتذارِ وعدم إعادة نشرِها."},{"id":5746,"era":"c15","t":"مقتل المسؤول العسكري لحركة طالبان منصور داد الله .","s":"شنَّ الجيشُ الباكستانيُّ حملةً ضدَّ مقاتلي حركة طالبان الأفغانية في إقليم بلوشستان القريبِ من الحدودِ الأفغانيةِ، ممَّا أدَّى إلى اعتقال الملا منصور داد الله في منطقة قلعةِ سيف الله معَ ستةٍ من رفاقِه الذين أُصيبوا بجروحٍ، وذلك بعد أنْ أبدَوْا مقاومةً خلالَ المواجَهاتِ، وقد تولَّى منصور القيادة العسكرية لحركة طالبان خلفًا لشقيقه الأكبر الملا داد الله أحدِ أهمِّ القادةِ العسكريينَ لحركة طالبان، بعد"},{"id":5747,"era":"c15","t":"أعلن ألبان كوسوفو استقلال بلادهم عن صربيا .","s":"أعلنَ هاشم ثاتشي رئيس وزراء إقليم كوسوفو استقلالَ الإقليم رسميًّا عن صربيا، وأعلنَ قيام دولة كوسوفو المستقلَّةِ، وذلك خلالَ جلسةٍ للبرلمان عُقدت في العاصمة برشيتينا، وقد أدانت جمهوريةُ صربيا إعلانَ الاستقلالِ، وأكَّدت روسيا كذلك معارضتَها لاستقلال كوسوفو."},{"id":5748,"era":"c15","t":"وقع الرئيسان التشادي والسوداني اتفاقًا لحل الخلافات .","s":"وقَّع الرئيسان التشادي إدريس ديبي، والسوداني عمر البشير في دكار اتفاقَ عدمِ اعتداءٍ، بهدف إنهاءِ خمسِ سنواتٍ من النزاعِ بينَهما، ووضع حدٍّ نهائيٍّ للاختلافات بينَهم."},{"id":5749,"era":"c15","t":"توقيع اتفاق مصالحة بين حماس وفتح في العاصمة اليمنية .","s":"وقَّعَت حركتا فتح وحماس اتفاقَ مُصالحةٍ برعاية يمنيَّةٍ، وتعهَّدَتا بإحياء المحادثاتِ المباشِرةِ بعد شهور من الأعمالِ العدائية، ووقَّع كلٌّ من عزَّام الأحمد رئيس كتلة فتح في المجلس التشريعي الفِلَسْطيني، ونائب رئيس المكتب السياسي لحركة حماس موسى أبو مرزوق الاتفاقَ الذي أُطلق عليه اسمُ \"إعلان صنعاء\"، بحضور الرئيس اليَمَني علي عبد الله صالح، والتوقيع شكَّلَ إطارًا لاستئناف الحوار من أجْل العودة بالأ"},{"id":5750,"era":"c15","t":"سيطرة جيش اتحاد جُزر القُمُر على جزيرة أنجوان .","s":"تمكَّنَ الجيشُ في اتحاد جُزر القُمُر مدعومًا بقوات من الاتحاد الأفريقي، من بَسطِ سيطرته على جزيرة أنجوان بعدَ عامٍ كاملٍ من قيام الكولونيل محمد بكر الذي كان يشغَلُ منصبَ رئيس الجزيرة، بالاستيلاءِ على الجزيرةِ وفَصلِها عن بقيةِ أجزاءِ الأرخبيلِ الواقعِ في المحيط الهندي، ويُعاني اتحاد جُزرِ القُمُر من نزاعاتٍ بين العاصمةِ موروني، والجُزُرِ الثلاثِ، وهي: القُمُر الكُبْرى، وأنجوان، وموهيلي، حيثُ تتمتّ"},{"id":5751,"era":"c15","t":"سيطرة المحاكم الإسلامية الصومالية على بلدة بلعد ومدينة كيسمايو .","s":"استولَت قواتُ المحاكمِ الإسلاميَّة الصوماليَّة المعارِضة للحكومة على مدينةِ بلعد الواقعة على بُعدِ 30 كيلومترًا إلى الشمال من العاصمة الصومالية مقديشو، ويَأْتي ذلك بعد استيلائِها على ستِّ مدن صوماليَّة بوسَطِ وجنوبِ الصومال، من بينها مدينةُ جوهر عاصمة إقليم شبه الوسط المتاخِم للعاصمة."},{"id":5752,"era":"c15","t":"انتخاب ميشيل سليمان رئيسًا للبنان .","s":"انتُخِب قائدُ الجيشِ ميشيل سليمان رئيسًا للُبنان بأغلبيةٍ 118 صوتًا من أصل 127، وامتناع ستة نواب عن التصويت، وبذلك يكونُ سليمانُ الرئيسَ الثانيَ عَشَرَ للجمهورية اللُّبنانية، وثالثَ قائدِ جيشٍ يصبحُ رئيسًا للبلاد بعد انتهاءِ ولاية الرئيسِ السابقِ إميل لحود."},{"id":5753,"era":"c15","t":"وفاة سعد العبد الله السالم الصباح أمير الكويت الرابع عشر .","s":"سعد العبد الله السالم الصباح أميرُ دولةِ الكويت الرابعَ عَشَرَ، أصبح أميرًا على الكويت في عام 2006م، وذلك بعد وفاةِ الأمير جابر الأحمد الجابر الصباح، ولكنَّ ظروفَه الصحيَّةَ لم تمكِّنْه من تحمُّلِ تَبِعاتِ الحُكم والإمارة، وبعد اجتماعاتٍ بين أبناء الأسرةِ الحاكمةِ، تمَّ عزلُه بعد تولِّيه بأيامٍ، وتمَّ إسنادُ الإمارة إلى الشيخ صباح الأحمد الصباح."},{"id":5754,"era":"c15","t":"اتِّفاقُ الدَّوحَة بين الفُرَقاء اللُّبنانيين .","s":"وقَّعت الفصائل اللُّبنانية اتِّفاقًا توصَّلَت إليه في الدَّوحة بقطر. والاتِّفاق يمثِّل نهايةً لـ(18) شهرًا من الأزمةِ السِّياسيَّة في لُبنانَ؛ شَهِدت بعضُ الفتراتِ منها أحداثًا داميةً. وكان الاتِّفاقُ بين طرفَيِ النزاعِ اللُّبناني المعارَضة والموالَاة. وكان من أبرزِ بُنود هذا الاتِّفاق: انتخابُ قائدِ الجيش ميشال سُليمان رئيسًا للجُمهوريَّة، وتأليفُ حكومةِ وَحدةٍ وطنيَّة."},{"id":5755,"era":"c15","t":"إعلانُ السُّودان قطْع العَلاقات الدبلوماسية مع تشاد .","s":"استمرَّت خلالَ عام (2008م) الأزمةُ الحادِثةُ في العَلاقات السُّودانية التشادية على خلفيَّة الاتِّهامات المتبادَلَة بين البلدَين بدعمِ كلِّ طرَفٍ لمتمرِّدي الطرَفِ الثاني. ورغْمَ أنَّ الرئيسَين السُّودانيَّ عمرَ البشيرَ والتشاديَّ إدريس دبي وقَّعَا في داكار اتِّفاقًا لوضعِ حدٍّ نهائيٍّ للخلافات بين البلدَين، إلا أنَّ السودانَ عاد وأعلن قَطْعَ العَلاقات الدبلوماسية مع تشاد؛ وذلك بعد هُجومٍ شنَّه متم"},{"id":5756,"era":"c15","t":"اشتباكاتٌ بين عناصِرِ حزبِ الله ومسلَّحِين موالِين للحُكومةِ في بيروت .","s":"وَقَعت اشتباكاتٌ بين عناصرِ حزبِ الله اللُّبناني ومسلَّحِين موالِين للحكومة في بيروت؛ أدَّت إلى سقوط (81) قتيلًا و(250) جريحًا، وسعى وُسطاءُ إلى إنهاء تلك الاشتباكاتِ التي تُعدُّ أعنفَ قتالٍ داخلي منذ الحرب الأهليَّة (1975-1990)."},{"id":5757,"era":"c15","t":"استِقالةُ رئيسِ الوُزَراء الموريتاني زَين ولد زيدان .","s":"قدَّم رئيسُ الوُزَراء الموريتاني زَين ولد زيدان استقالتَه من منصِبِه، بعد عامٍ من تولِّيه، وقَبِل الرئيسُ سيدي ولد الشيخ عبد الله استقالةَ ولد زيدان أثناءَ استقبالِه له دون توضيحِ أسبابِ الاستقالةِ، ثم عيَّن مكانَه يحيى ولد أحمد الواقِفَ الأمينَ العامَّ لرئاسةِ الجمهورية."},{"id":5758,"era":"c15","t":"وَفاة المفكِّر المِصريِّ عبدِ الوهَّاب المسيري .","s":"تُوفِّي المفكِّرُ المصريُّ عبدُ الوهاب المسيري في القاهرة، عن عُمُر يناهِز (70) عامًا بعد مُعاناةٍ مع مرضِ السرطان، وُلد المسيري في دمنهور سنة (1938م) بمصرَ، والْتحق عامَ (1955م) بقسم اللُّغة الإنجليزية بكُلِّيَّة الآداب جامعة الإسكندريَّة، وعُيِّن معيدًا فيها عند تخرُّجِه وحصَل على درجة الدكتوراه عامَ (1969م)، وكان المسيري أستاذًا متخصِّصًا في الأدب الإنجليزي؛ قام بالتدريسِ في عدَّةِ جامعات مِصري"},{"id":5759,"era":"c15","t":"إلغاءُ قرارِ حظرِ الحجابِ في تركيا .","s":"قَضَت المحكمة الدُّستورية في تركيا ببُطلانِ قرارِ حظرِ الحجاب للنِّساء داخِلَ الجامعاتِ التركية، والذي فُرِض للمرَّةِ الأولى في أعقابِ الانقلابِ العسكريِّ في عام (1980م)."},{"id":5760,"era":"c15","t":"صُدورُ مشروعٍ إلكتروني صِهيَونِيٍّ لتفسير القُرآن الكريم باللغة العِبرية .","s":"صَدَر مشروعٌ إلكتروني حمَل اسم \"قرآنت\" أطلقتْه وِزارة الخارجيةِ الإسرائيليةِ لتفسير القرآن الكريم باللُّغة العِبرية. والمشروع من إعدادِ (15) أكاديميًّا من عربِ إسرائيلَ في إطار دِراسَتِهم لنَيلِ درجةِ الماجستير في مجالِ الاستِشاراتِ التَّربويَّةِ تحتَ إشرافِ الأستاذ الجامعيِّ اليهوديِّ عوفر جروزيرد. وهذا المشروعُ خَديعةٌ إسرائيليةٌ؛ حيث يفسِّر القرآنَ الكريمَ حسبَ ما يتناسبُ مع أفكارِهم ومُعتقداتِ"},{"id":5761,"era":"c15","t":"إقالَةُ شيخ شريف من رئاسةِ اللَّجنة التنفيذيَّة في الصومال .","s":"أقالَ أعضاءُ (التحالُف من أجل إعادة تحرير الصومال) المعارِضِ للحُكومةِ الانتقاليَّة شيخ شريف شيخ أحمد من رئاسةِ اللجنةِ التنفيذيَّة للتحالُف، وعيَّن مكانَه الشيخ حسن ضاهر أويس؛ وذلك بَعدَ توقيعِ التحالُفِ بجيبوتي لهُدنةٍ مع الحكومة الموالِيَة للاحتلالِ الإثيوبيِّ وإقرارِه من قِبَل اللجنةِ المركزيَّة للتحالُف. وكانت قياداتٌ في المحاكمِ الإسلاميةِ قد وجَّهَت انتقاداتٍ لشيخ شريف شيخ أحمد لتوقيعِهِ عل"},{"id":5762,"era":"c15","t":"وفاةُ الشَّيخِ حسن أيوب .","s":"تُوفِّي الداعيةُ الإسلاميُّ الشيخُ حسن أيوب عن عُمُرٍ يناهِزُ الـ(90) عامًا. والشيخُ حسن أيوب من مواليد محافظة المُنوفية بجمهورية مصرَ العربية ومن عُلماءِ الأزهرِ؛ حيث عَمِل بعدَ تخرُّجِه في كليَّة أُصولِ الدِّين بجامعة الأزهر عامَ (1949م) مدرِّسًا بوِزارة التربية والتعليم المِصريَّة، ثم موجِّهًا بوِزارة الأوقافِ، فمُديرًا لمكتبها الفنيِّ، كما عَمِل الشيخُ أيوب بالكُويت واعظًا وخَبيرًا ومؤلِّفًا ف"},{"id":5763,"era":"c15","t":"انتِخابُ موسى تويبو رئيسًا لجَزيرة أنجوان .","s":"فاز موسى تويبو في الانتِخابات الرئاسيَّةِ في جزيرة أنجوان التي تتمتَّع بحُكم ذاتيٍّ ليخلُف بذلك الكولونيل محمد بكار، الذي أطاحَت به قوَّاتُ اتحادِ جزر القمر بدعمٍ من الاتِّحاد الإفريقيِّ. وموسى تويبو مهندسُ أشغالٍ عامةٍ تلقَّى دُروسَه بالجزائرِ، وقد كان وزيرًا في حُكومةِ الرئيسِ السابقِ سعيد محمد جوهر."},{"id":5764,"era":"c15","t":"انعِقادُ المؤتمَر الدَّوليِّ للحِوارِ بين الأديان .","s":"انعَقَد في العاصمة الأسبانية مدريد المؤتمرُ الدَّوليُّ للحوار بين الأديان تحتَ رعايةِ الملك عبد الله بن عبد العزيز آل سعود ملكِ المملكةِ العربيَّة السُّعودية، وبحُضور الملكِ خوان كارلوس ملك مملكة إسبانيا، وقد نظَّم الحوارَ رابطةُ العالم الإسلاميِّ، وشارَك فيه (200) شخصيةٍ من مُختلَف أتْباعِ الأديانِ والحضاراتِ والثَّقافاتِ المختَلِفَة."},{"id":5765,"era":"c15","t":"اعتِقالُ الزَّعيم السياسيَّ لصِرب البوسنة رادوفان كرادجيتش ومُحاكمَتُه .","s":"طارَدَ المجتمعُ الدَّولي رادوفان كرادجيتش الزَّعيمَ السياسيَّ السابقَ لصِرب البوسنة على مدى (13) عامًا ظلَّ فيها متخفيًا قبل أن تعتقِلَه أجهزةُ الأمن الصِّربية، ويعدُّ كرادجيتش من منفذِّي \"التطهير العِرقي\" الدَّموي في يوغوسلافيا السابقةِ. ولقد اتهمَتْه محكمةُ الجزاءِ الدَّولية في لاهاي بارتكابِ جرائمِ حربٍ وإبادَةٍ في حق الإنسانيَّة، وأنه مسؤولٌ مع الزعيمِ العسكريِّ السابقِ لصِرب البوسنة راتكو ملا"},{"id":5766,"era":"c15","t":"هَلاكُ الشاعِرِ الفِلَسطينيِّ محمود درويش .","s":"محمود درويش هو أحدُ الشُّعراءِ الفِلَسطينين الحداثيين الذين ارتَبَط اسمُهُم بشِعرِ الثورَةِ والوطن وكان مليئًا بالسُّخْرية والاستهزاء بالله وبالدين والمقدسات الإسلامية. وُلد درويش عام (1941) في قريةِ البَروةِ وهي قريةٌ فِلسطينيةٌ تقع في الجليلِ قُربَ ساحِلِ عَكَّا، وخَرَجت الأسرةُ برُفقة اللَّاجئين الفِلَسطينيين عامَ (1947) إلى لُبنان، ثم عادت متسلِّلةً عامَ (1949) بُعَيدَ توقيعِ اتِّفاقياتِ السلا"},{"id":5767,"era":"c15","t":"وفاةُ الشَّيخِ المُقرِئِ محمد سكر (شيخ القراء في دمشق) .","s":"الشَّيخُ المقرِئُ أبو هشام محمد بن طه سكر الدِّمَشقي، من كبارِ علماءِ القراءاتِ ومَشايِخ القُرَّاء بدِمَشق. وُلد الشيخُ في دمشق في حيِّ العفيف، بمِنطَقَة الصَّالِحِيَّة سنةَ (1340هـ-1922م) ونشأ يتيمًا في حِضن والِدَتِه الكريمةِ؛ فعَكَف الشيخُ رحمه الله منذ صِغَرِه على حَلَقات العلمِ؛ فقرأ على الشَّيخِ محمود فايز الدير عطاني (ت: 1385) ختمةً كاملةً برِواية حفصٍ عن عاصمٍ، وكان خِلالَ هذه الختمةِ يحفَ"},{"id":5768,"era":"c15","t":"استِقالةُ رئيس باكستان برويز مشرف .","s":"استَقال الرَّئيس برويز مشرف مُنهِيًا تِسعَ سنواتٍ كرئيسٍ لباكستان، وكان قد تسلَّم برويز مشرف قائدُ الجيشِ السابقُ مقاليدَ حُكمِ باكستان التي عَرَفت ماضِيًا طويلًا من الأنظمةِ الديكتاتورية العسكريةِ عَقِب انقلابٍ عسكريٍّ دمويٍّ في العام (1999) أطاح فيه برئيسِ الوُزراء آنذاك نواز شريف."},{"id":5769,"era":"c15","t":"سيطرةُ حركةِ الشَّباب المُجاهدين في الصومال على مدينة كيسمايو .","s":"سيطَرَت حركةُ الشباب المجاهدين على مدينة كيسمايو، أكبرَ مدنِ جنوب الصومال بعد معاركَ ضاريةٍ أوقَعَت أكثرَ من 40 قتيلًا. وقامت بطَردِ الميليشيَات المحليَّة التي كانت تسيطِرُ على المدينةِ، وتمكَّنَت أيضًا من الاستيلاء على المَرفأِ الرئيسيِّ في جنوب البلاد الواقِعِ على بُعد حوالَي (500) كلم جنوب مقديشو. وكانت حركةُ الشباب المجاهدين قد انفصَلَت عمَّا كان يُعرَف بـ(اتحاد المحاكم الإسلامية)، رافضةً اتفا"},{"id":5770,"era":"c15","t":"انقِلابٌ عسكريٌّ يُطيح بالرئيس الموريتاني سيدي ولد الشيخ .","s":"اعتُقِل الرئيسُ الموريتانيُّ سيدي ولد الشيخ عبد الله أولُ رئيسٍ منتخَب ديمقراطيًّا في نواكشوط إثرَ انقلابٍ قادَه قائدُ الحرسِ الرِّئاسي، كما اعتُقِل عددٌ من الوُزَراء المقرَّبين. ويأتي الانقلابُ بعدَ سنة ونصف من الانتخاباتِ الرئاسية مطلعَ (2007) وبعد ثلاثِ سنواتٍ من انقلابٍ عسكريٍّ في أغسطس (2005) أطاح بالرَّئيس معاوية ولد الطايع. وشكَّل الانقلابِيُّون مجلِسًا للحُكمِ برئاسةِ رئيسِ الأركانِ وقائدِ"},{"id":5771,"era":"c15","t":"توقيعُ حزبِ الله والتيارِ السلفيِّ وثيقةً لمَنعِ الفتنةِ .","s":"وقَّع حزبُ الله والتيارُ الإسلاميُّ السلفيُّ في لُبنان وثيقةَ تفاهُمٍ مشترَكةٍ في خطوةٍ هي الأولى بين الجانِبَين. ووقَّع الوثيقةَ عن التيار السلفيِّ ممثِّلُ التيار السلفيِّ في لبنان الدكتور حسن الشهال رئيس \"جمعية العدل والإحسان\"، وعن حزبِ الله رئيسُ المجلسِ السياسيِّ إبراهيم أمين السيد. ولكنْ بعد يومٍ واحدٍ من توقيعِ وثيقةِ التفاهُمِ بين هذه الفَصائلِ، تم الإعلانُ عن تَجميدِ الوثيقةِ."},{"id":5772,"era":"c15","t":"تعيِينُ ولد مهان رئيسًا لموريتانيا .","s":"عيَّنَت محكمةُ العدلِ العُليا الموريتانيَّةُ التي شكَّلتْها الهيئةُ العسكريةُ الحاكمةُ المحامي محمد ولد مهان رئيسًا لها في (29 سبتمبر)، وانتُخِب العقيدُ المتقاعدُ ديوب عبد الله ديمباواس نائبًا للرئيس."},{"id":5773,"era":"c15","t":"توسِعَةُ المَسعَى بالمسجدِ الحرامِ .","s":"بدَأَت المملكةُ العربية السعوديةُ في تشغيلِ الدَّورِ الأرضيِّ من المَسعَى الجديدِ في المسجد الحرامِ بمكَّةَ المكرمة؛ وذلك ضِمنَ المرحلةِ الأولى لمشروعِ تطويرِ وتوسِعَةِ المَسعَى. وتَمَّت تلك التوسعةُ بِناءً على مُوافقةِ خادمِ الحرمَين الشريفَين الملِك عبد الله بن عبد العزيز رحمه الله، ولقد زاد المَسعَى -بعد هذه التوسعة- من (29) ألف متر مربع قبْل التوسعةِ لتُصبِحَ مساحتُه (87) ألف متر مربع، تتَّسع "},{"id":5774,"era":"c15","t":"ظُهورُ الأزمةِ الاقتصاديَّةِ العالميَّةِ .","s":"في (سبتمبر 2008) بدَأَت أزمةٌ ماليةٌ عالَميةٌ هي الأسوأُ من نوعِها منذ زمنِ الكساد الكبير سنةَ (1929م)، ابتدَأَت الأزمةُ أولًا بالولايات المتحدة الأمريكية أقوى الاقتصادياتِ في العالَمِ؛ إذ يمثِّلُ اقتصادُها أكثرَ من (30%) من اقتصاد العالم، ثم امتَدَّت إلى دُول العالَم لتشملَ الدولَ الأوربِّية والدُّولَ الآسيوية والدُّولَ الخليجية والدُّولَ النامية التي يرتبِطُ اقتِصادُها مباشرةً بالاقتصاد الأمريكي"},{"id":5775,"era":"c15","t":"انتِخابُ آصف علي زرداري رئيسًا لباكستان .","s":"أعلن رئيسُ اللجنةِ الانتخابية الباكستانية انتِخابَ زعيم حزبِ الشعب بالوَكالة آصف علي زرداري (53 عامًا) زوجِ بنازير بوتو- زعيمةِ المعارضةِ سابقًا- رئيسًا لباكستان من قِبَلِ البرلمان والمَجالسِ الإقليمية. وكان أعضاءُ البَرلمانِ الباكستانيِّ وأربعةُ مجالِسَ إقليميَّةٍ قد اجتَمَعوا للتَّصويتِ لاختيارِ رئيسٍ جديدٍ للبلادِ خَلَفًا للرئيسِ المُستَقيل برويز مشرف، وَسَطَ إجراءاتٍ أمنيَّةٍ مشدَّدةٍ حولَ مبن"},{"id":5776,"era":"c15","t":"هلاك داعية الضَّلال عبدِ الله الحبَشيِّ .","s":"عبدُ الله الحبشيُّ الضالُّ زعيم فِرقةِ الأحباش، اسمُه عبدُ الله بن محمد من هرر بالحبشةِ، نَزَح من الحبشةِ إلى الشام بضَلالَتِه، وتنقَّل فيها حتى استقرَّ به المُقامُ في لُبنانَ، وأخَذ يدعو النَّاسَ إلى طريقَتِه، ويتعصَّب لها ويُناظِر من أجلِها، ويطبَعُ الكتبَ والصُّحُفَ الداعيةَ إليها؛ فانتشَرَ أَتباعُه وراجَت أفكارُه وهي أخلاطٌ من اعتقاداتِ الجهميةِ والمعتزِلَةِ والصوفيَّةِ القُبوريَّةِ، مع الوُقو"},{"id":5777,"era":"c15","t":"اتِّفاقٌ في جيبوتي لاقتِسام السُّلطة في الصومال .","s":"في جيبوتي وقَّعَت الحكومةُ الصُّوماليةُ الانتقاليةُ وتحالُفُ إعادةِ تحريرِ الصومال اتفاقيَّةَ وَقفِ إطلاقِ النار وانسحابِ القوَّاتِ الإثيوبية من الصومال، وذلك بعد الجولة الثالثةِ من المُفاوَضاتِ غيرِ المباشِرَةِ بين الجانِبَين."},{"id":5778,"era":"c15","t":"وفاة العلَّامة القاضي إسماعيل الأكوع اليمنيِّ .","s":"هو المؤرِّخُ اليمنيُّ القاضي إسماعيلُ بن عليٍّ الأكوَعُ، تُوفِّي في مدينةِ صنعاءَ عن (87) عامًا، ودُفن في مقبرة \"حدة\" وشارك في تشييعِ الجنازة رئيسُ الجمهورية ورئيسُ مجلسِ القضاء الأعلى ورئيسُ مجلسِ الشورى وعددٌ كبيرٌ من العُلَماء والمسؤولين والمثقَّفين. والقاضي إسماعيلُ مؤرِّخٌ ولغويٌّ وفقيهٌ وأديبٌ، كان عضوًا في المَجمَع العلميِّ العراقي، والمَجمعِ العلميِّ الهنديِّ، وعضوًا في المَجمَعِ اللُّغوي "},{"id":5779,"era":"c15","t":"وقوعُ فيضانات كبيرة في اليمن الجنوبي (حضرموت) .","s":"تُوفِّي (180) شخصًا جرَّاءَ فيضاناتٍ في جنوب اليمن بمحافظتَي حضرَموتَ والمهرةِ، وأُجبِرَ أكثرُ من عشرةِ آلافٍ آخَرين على مُغادرةِ منازِلِهم، كما تضرَّر قُرابةُ (2000) منزلٍ."},{"id":5780,"era":"c15","t":"ترسيم الحدود بين السعودية وقطَر .","s":"أنهَت السعوديةُ وقطرُ الخِلافَ الحدوديَّ بينهما؛ بالتوقيع على اتفاقيةِ تعيينِ الحدودِ البريةِ والبحريةِ، ووقَّع البَلَدان على كافَّةِ الخرائطِ الحدوديةِ بعد الانتهاءِ من ترسيم الحدودِ بشكلٍ نهائيٍّ ووَضعِ العلاماتِ الحدوديةِ سواءٌ البريَّة أو البحريَّة."},{"id":5781,"era":"c15","t":"وَقفُ إطلاقِ النارِ بين الجيشِ السودانيِّ والحَرَكات المُسلَّحة في دارفور .","s":"أعلَنَت السودانُ وقفًا فوريًّا لإطلاق النار في دارفور ونَزعَ أسلحةِ الميليشيَاتِ في هذه المِنطَقة الواقعةِ في غرب البلاد والتي تشهَدُ حربًا أهليةً، وتوفيرَ آليةِ مراقبةٍ فاعلةٍ مشترَكةٍ من كافة الأطراف والقوَّات المشترَكَة للاتِّحادِ الإفريقيِّ والأُمم المتحدةِ. مع وَقفِ الحَمَلات الإعلاميَّة حتى نهايةِ العامِ؛ إلا أنَّ حركةَ «العدل والمساواة» -وهي إحدى فصائلِ المُتمرِّدِين الرئيسيةِ في دارفور- رَ"},{"id":5782,"era":"c15","t":"وفاةُ الرئيسِ السودانيِّ السابقِ أحمد الميرغني .","s":"تُوفِّي الرئيسُ السابقُ للسودانِ أحمد بن علي الميرغني بمدينةِ الإسكندريةِ بمصرَ عن عمر يناهِزُ (67) عامًا. والميرغني هو سليلُ عائلةِ علي الميرغني، زعيمُ طائفةِ الطريقةِ الخَتميةِ القويَّةِ النُّفوذِ بالسُّودان. وُلد الميرغني في الخُرطوم في أغسطس عامَ (1941م)، وقد حَصَل على شَهادةِ الاقتصادِ من جامعةِ كامبردج بلندن بدرجةِ امتيازٍ مع مرتبةِ الشرفِ. عَمِل سفيرًا للسُّودان في القاهرة بمصرَ، ووزيرًا لل"},{"id":5783,"era":"c15","t":"انعقاد مؤتمر حوار بين الأديانِ والحضارات في مقرِّ الأمم المتَّحدة .","s":"عُقِد في مقرِّ الأممِ المتحدةِ في نيويورك مؤتمرُ الحوارِ بين الأديانِ والتعاوُنِ من أجلِ السلامِ؛ وذلك استجابةً لدعوةِ خادِمِ الحرمَين الشريفَين الملك عبد الله بن عبد العزيز الجمعيةَ العامَّةَ للأُممِ المتَّحدة إلى عقدِ اجتماعٍ عالي المستوى للحِوارِ بين أتباعِ الأديانِ والثَّقافاتِ والحضاراتِ. ويأتي هذا المؤتمرُ وَفقًا لإعلانِ مدريدَ الذي صَدَر في ختامِ المؤتَمرِ العالميِّ للحوارِ الذي نظَّمَتْه ر"},{"id":5784,"era":"c15","t":"إعلانُ حماسٍ انتهاءَ الهدنةِ مع إسرائيل .","s":"أعلَنَت \"كتائبُ عزِّ الدين القسَّام\" الجناحُ العسكريُّ لحركةِ \"حماسٍ\" انتهاءَ التهدِئَةِ مع إسرائيلَ، وتحميلَ الدولةِ المحتلَّةِ المسؤوليَّةَ الكامِلَةَ عن ذلك. وقد أطلَقَ فِلَسطينيون ثلاثةَ صواريخَ من شمالِ قطاعِ غزَّةَ على إسرائيلَ في أوَّلِ يومٍ من إعلانِهِم انتهاءَ التَّهدِئَةِ. وأوضَحَت حركةُ حماسٍ أن السببَ وراءَ قرارِها: هو أنَّ العدوَّ الصِّهيَونِيَّ لم يلتزمْ بشروطِ التهدِئَةِ، المتمثِّلَ"},{"id":5785,"era":"c15","t":"الاتِّفاقيَّةُ الأمنيَّةُ الأمريكيةُ العراقيةُ .","s":"أقرَّت الحكومةُ العراقية الاتفاقيةَ التي تمت تسميَتُها (اتفاقيةَ انسحابِ القواتِ الأمريكية من العراق) وهَدَفت الاتِّفاقيَّةُ إلى تحديدِ الأحكام والمُتطلَّباتِ الرئيسةِ التي تنظِّمُ الوُجودَ المؤقَّتَ للقُوَّات الأمريكية في العراق وأَنشطِتَها فيه وجدوَلَةَ عمليةِ انسحابِ القُوَّات المسلحة منها. ولقد ثار جدلٌ واسِعٌ بين التكتُّلاتِ السياسيةِ والعِرقيَّةِ في العراقِ حولَ هذه الاتِّفاقية قَبْلَ توقيعِ"},{"id":5786,"era":"c15","t":"الرئيسُ الصومالي يُقيل رئيسَ وُزرائه وحكومَتَه .","s":"أقال الرئيسُ الصومالي عبد الله يوسف رئيسَ وُزرائِه نور حسين عدي وحكومته، وقد رَفَض رئيسُ الوُزَراء قرارَ إقالتِه واعتبَرَ أنَّ الرئيسَ يوسف لا يحقُّ له مثلُ هذا القرارِ، وأنَّ الرئيسَ خالَفَ اللَّوائِحَ والأحكامَ السارِيَةَ في البلادِ.‏‏ وكان عدي شَغَل منصِبَ رئيسِ الوُزراء لمدةِ عامٍ، إلا أنَّه كان على خلافٍ مع الرئيسِ يوسف بسببِ رَفضِ الأخيرِ لبَعضِ وُزَرائِه.‏‏ وكانت قد تفاقَمَت الخِلافاتُ بينه"},{"id":5787,"era":"c15","t":"العُدوانُ الصِّهيَونِيُّ يُدمِّرُ مَسجِدًا ويَقصِفُ مقرَّ الجامعةِ الإسلاميةِ في غزةَ .","s":"دكَّت طائراتُ الاحتلالِ الصِّهيَونِيِّ في اعتدائِها على غزةَ مسجِدَ الشفاءِ، وهو المسجدُ الثاني الذي تمَّ قصفُه بعد مسجدِ مخيَّم جباليا، ومن بين المُنشآت التي تم قصفُها مبنى المختبَراتِ العلميةِ في قسم الطالباتِ، وهو مُكوَّن من خمسةِ طوابِقَ. والجامعةُ الإسلاميةُ هي كُبرَى الجامعاتِ الفِلَسطينية؛ حيث يدرُس فيها قُرابةُ خمسةٍ وعشرين ألفَ طالبٍ وطالبةٍ."},{"id":5788,"era":"c15","t":"السُّلطاتُ السودانية تطرُدُ منظَّمةً أمريكيةً تنصيريَّةً. .","s":"طرَدَت السُّلطات السودانيةُ جماعةً إغاثيةً في مِنطقةِ دارفور التي يَدينُ كلُّ سكانِها بالإسلامِ، بعدَمَا وجد بعضُ المسؤولين آلافَ النسخِ من الإنجيل باللُّغة العربيةِ مُخزَّنةً في مكتبٍ تُديرُه منظمةُ (ثرست نو مور) أي (لا مزيد من العطش) في شمالِ دارفور. وتتَّخذ هذه الجماعةُ من ولايةِ تكساس الأمريكيةِ مقرًّا لها."},{"id":5789,"era":"c15","t":"اعترافٌ دَوليٌّ رسميٌّ باستقلالِ جمهورية كوسوفا. .","s":"أعلَنَ عددٌ من الدُّول اعترافَها باستقلالِ كوسوفا، وقد بلَغ عددُها (56) دولةً من دول العالَمِ الأعضاءِ في منظَّمة الأُمم المتحدة الـ(192)، من بينِها المملكةُ العربيةُ السعودية والإمارات العربيةُ المتَّحدة والولاياتُ المتَّحدة الأمريكيَّةُ، واليابانُ، ومُعظَمُ دولِ الاتحادِ الأوربِّيِّ، فيما رَفَضت صربيا هذه الخطوةَ بشدةٍ وساندَتْها الصينُ والهندُ وروسيا."},{"id":5790,"era":"c15","t":"منعُ الحجابِ في المدارس البلغارية .","s":"وافَقَت الحكومةُ البلغارية على مشروعِ قانونٍ يقضي بمَنعِ الحجابِ الإسلامي والرُّموز الدينيَّةِ الواضحةِ في المدارس، ويمثِّلُ المسلمون نحوَ (12%) من عدد سكان بلغاريا البالغِ (7.6) ملايين نسمة، وينحدر أغلبُ المسلمين في بلغاريا من أصولٍ تركيةٍ."},{"id":5791,"era":"c15","t":"اعتقالُ عدد من المتشيِّعين المِصريِّين .","s":"اعتقَلَت السُّلطاتُ الأمنيةُ المِصريةُ المتشيِّعَ حسن شحاتة، الخطيبَ الأسبقَ لمسجد كوبري جامعة بالقاهرة، ومعه (306) من المتشيِّعين من أتْباعِه، وقد وُجِّهَت إليهم تهمةُ زعزعةِ الأمنِ القوميِّ المِصرِيِّ وازدراءِ الأديان، وحسن شحاتة هو أحدُ غُلاةِ المتشيِّعين المعروفين في مصر، والمعروفُ بخُطَبه التي يسبُّ فيها صحابَةَ النبي صلَّى الله عليه وسلَّم وأُمَّ المؤمنين عائشةَ رضي الله عنها بألفاظٍ بذيئةٍ،"},{"id":5792,"era":"c15","t":"وفاةُ الرئيسِ الجابوني عمر بونجو. .","s":"تُوفِّي رئيس الجابون عمر بونجو بسبب أزمةٍ قلبية في مستشفى إسبانيٍّ، وذلك بعد أكثر من أربعين عامًا تولَّى خلالَها رئاسةَ الدولةِ المُنتِجة للنِّفطِ في وسط إفريقيا. وقد أصبَحَ رئيسًا للبلادِ عَقِبَ وفاةِ سلفِه ليون مبا عام (1967م)، وبعد ستِّ سنواتٍ اعتَنَقَ الإسلامَ."},{"id":5793,"era":"c15","t":"وُقوعُ مذبحةٍ ضدَّ مسلِمي الإيجور .","s":"قام مئاتٌ من العُمَّال الصينيين بأحدِ المصانعِ الواقِعَةِ بجنوب الصِّين في منتصف الليل باقتحامِ مساكنِ العُمَّال المسلمين التُّركستانيين هناك، وانهالوا عليهم ضَربًا بالعِصِيِّ والسَّكاكين، ممَّا أدَّى إلى مَقتلِ ثلاثمئةٍ، وجَرحِ المئاتِ. وقد تظاهَرَ عَشَراتُ الآلافِ من التركستانيين في شوارعِ \"أورومتشي\" مُطالِبين ببَيانِ أسبابِ الحادثِ، ومُعاقبةِ المُجرمين، ووَقفِ التميِيزِ العُنصريِّ ضدَّهم. وقامَ"},{"id":5794,"era":"c15","t":"وفاةُ الشيخِ العلَّامة عبدِ الله بنِ عبد الرحمن بن جِبرين. .","s":"وُلد الشيخُ سنةَ (1352هـ) في إحدى قرَى القويعيةِ، ونشأَ في بلدة الرين، وابتَدَأ بالتعلُّمِ في عام (1359هـ). وأتقن القرآنَ وسِنُّه اثنا عشر عامًا، وتعلَّم الكتابةَ وقواعِدَ الإملاء، ثم ابتَدَأ في الحفظِ وأكمَلَه في عام (1367هـ). وكان قد قرأ قبلَ ذلك في مبادئِ العلومِ؛ ففي النحو قرأ على أبيه أوَّلَ \"الآجرومية\"، وكذا متنَ \"الرَّحبيَّة في الفرائض\"، وفي الحديثِ \"الأربعين النووِيَّة\" حفظًا، و\"عُمدة الأح"},{"id":5795,"era":"c15","t":"فَوزُ مسعود برزاني برئاسةِ إقليمِ كردستان .","s":"أعلَنَت رئاسةُ إقليم كردستان فوزَ مسعود برزاني برئاسةِ الإقليمِ بنسبةِ (70%)."},{"id":5796,"era":"c15","t":"مُواجهاتٌ بين القُوَّات الحكوميةِ النيجيريَّةِ وأعضاءِ الجَماعةِ الإسلاميَّةِ .","s":"حدَثَت مُواجَهاتٌ بين قواتِ الحكومةِ النيجيرِيَّةِ وأعضاءِ الجَماعةِ الإسلاميةِ في شمال البلادِ \"بوكو حرام\"، استمَرَّت خمسةَ أيَّامٍ، وقُتِل فيها أكثرُ من (780) شخصًا. وكانت مدينةُ مايدوجوري عاصمةَ ولاية بورنو معقِلُ زعيمِ الجماعة محمد يوسف قد شَهِدت أعنفَ العملياتِ القتاليَّةِ."},{"id":5797,"era":"c15","t":"مَقتلُ زعيمِ جماعةِ (أنصار جند الله) في قطاع غزة .","s":"اقتَحَمت أجهزةُ الأمنِ التابعةِ لشرطةِ الحكومةِ في غزةَ آخِرَ منزلٍ فرَّ إليه مُسَلَّحون من جماعةِ أنصار جند الله، الذين سَبَق أن أعلنوا قِيامَ إمارةٍ إسلاميَّةٍ بغزةَ تنطلِقُ من مدينةِ رَفَحَ. ونجَحَت قواتُ الأمنِ في اقتحامِ منزلِ عبد اللطيف موسى الذي فرَّ إليه كَثيرٌ من المُسَلَّحين، بعد أن حاصرَتْهم الشرطةُ لساعاتٍ في مسجدِ ابن تيمية، وقد أُعلِن بعد ذلك عن مقتَلِه و(20) من أتباعِه. وعبد اللطيف "},{"id":5798,"era":"c15","t":"اقتِحامُ جماعاتٍ يهوديَّةٍ متطرِّفةٍ للمسجدِ الأقصى. .","s":"اقتحَمَت جماعاتٌ يهوديَّةٌ متطرِّفةٌ يومَ (25 شعبان) ساحةَ المسجدِ الأقصى المبارَك، من جهةِ بوابةِ المغارِبة بالقدسِ الشرقية المحتلَّة، وتحت حراسةِ شرطةِ الاحتلالِ الإسرائيليِّ بزَعمِ أنَّ المكانَ الذي يتجوَّلون فيه هو \"جبل الهيكل المزعوم\". وشَمِلت جولَتُهم المسجِدَ القِبليَّ المسقوفَ، والأقصى القديمَ، والمصلَّى المَرْوانيَّ، والساحاتِ القريبةَ منه، بالإضافةِ إلى مِنطقةِ مسجد الصخرة، ولكنَّها لم ت"},{"id":5799,"era":"c15","t":"تأسيسُ جمعيةٍ أمازيجية في المغربِ تدعو للتطبيعِ مع إسرائيل. .","s":"أُعلِن في المغرِب عن تأسيسِ جمعية أمازيجية تدعو للتطبيعِ مع الكِيان الصِّهيَونيِّ، وتسعى لإقامةِ عَلاقاتٍ ثقافيَّةٍ واجتماعيَّةٍ واقتصاديَّةٍ وسياسية مع الكِيانِ الصِّهيَونِيِّ. وزَعَمت الجمعيةُ أنَّ هدَفَها توثيقُ الصِّلاتِ التاريخيةِ بين الأمازيج واليهود الإسرائيلِيِّين الذين استوطَنوا المناطِقَ الأمازيجية بالمغربِ وهاجَروا إلى إسرائيل. وطالَبَت بالسماحِ لهَؤلاءِ اليهودِ الإسرائيلِيِّين بالعودة "},{"id":5800,"era":"c15","t":"وفاةُ عبد العزيز الحكيم رئيسُ المَجلس الأعلى الشيعي في العراق .","s":"هو عبدُ العزيز محسن الحكيم، الزعيمُ الشيعيُّ، وعضوُ البرلمان العراقيِّ، ورئيسُ \"المجلس الإسلامي الأعلى الشيعي\"، وُلد الحكيمُ سنةَ (1953م) بمدينة النجف العراقيَّةِ، وهو ابن المَرجِع الشيعي محسن الطَّبطَبائي الحكيم، وشقيقُ المعارِض محمد باقر الحكيم، الذي اغتِيلَ بانفِجارِ سيارةٍ مفخَّخة عامَ (2003م). وكان عبدُ العزيز الحكيمُ أحدَ الأعضاءِ المؤسِّسين لـ\"المجلس الأعلى للثورة الإسلامية\" المعارِض لحُكمِ"},{"id":5801,"era":"c15","t":"وُقوعُ أكبرِ هُجومٍ ضدَّ الحرسِ الثوريِّ الإيراني. .","s":"وقع هُجومٌ تفجيريٌّ في جنوبِ شرق إيران أدَّى إلى مقتلِ ستِّين شخصًا على الأقلِّ، وكان من بين القَتلى الجنرال نور علي شوشتاري نائبُ قائدِ القُوَّات البرِّيَّة، كما أنَّ عشراتٍ آخَرين من قادةِ الحرس الثوريِّ الإيراني قد قُتِلوا وجُرِحوا في الهُجومِ الذي وَقَع بمحافظة سيستان بلوشستان. وبين القتلى أيضًا الجنرال محمد زاده، قائدُ الحرس الثوريِّ في محافظة سيستان بلوشستان، وقائدُ الحرسِ الثوري في مدينةِ إ"},{"id":5802,"era":"c15","t":"إنشاءُ قاعدةٍ عسكريةٍ فرنسيةٍ دائمةٍ في الإمارات العربية المتحدة .","s":"دشَّن الرئيسُ الفَرَنسي نيكولا ساركوزي قاعدةً عسكريةً فَرَنسيةً دائمةً في الإمارات العربية المتحدة، وجدَّد في الوقت نفسِه اتفاقًا دفاعيًّا موقَّعًا مع الإمارات في (1995م). وفي المقابِلِ انتقَدَت إيرانُ -التي ترفُضُ الانسحابَ من الجزرِ الإماراتية الثَّلاث التي تحتلُّها- كُلًّا من فرنسا والإمارات على خلفيَّةِ تدشين القاعدةِ العسكريَّةِ، وقامت بنشرِ ثلاثِ غوَّاصاتٍ حديثةٍ، و(18) زَورقًا سريعًا وعددًا"},{"id":5803,"era":"c15","t":"وفاة الدكتور مصطفى محمود .","s":"الدكتور مصطفى كمال محمود حُسين آل محفوظ، وُلِد عامَ (1921م)، وكان توأمًا لأخٍ توفِّي في العامِ نفسِه، وهو طبيبٌ وكاتبٌ من مواليدِ شبين الكوم بمحافظة المنوفية، درس الطبَّ وتخرَّج عامَ (1953م)، ولكنه تفرَّغ للكتابةِ والبحثِ عامَ (1960م)، تزوَّج مرَّتَين، وانتهى كلا الزواجَين بالطلاق. ألَّف (89) كتابًا، منها الكتبُ العلميةُ والدينيَّةُ والفلسفية والاجتماعيةُ والسياسيَّةُ والحِكاياتُ والمَسرَحياتُ وقَ"},{"id":5804,"era":"c15","t":"إعادةُ انتخابِ الشيخ خليفة رئيسًا لدولة الإمارات العربية المتحدة .","s":"قرَّر أعضاءُ المجلس الأعلى لاتِّحاد حُكَّام الإمارات، إعادةَ انتخابِ الشيخِ خليفةَ بنِ زايد آل نهيان، رئيسًا للدولة للسنواتِ الخمسِ القادمةِ؛ وَفقًا لأحكام دستور دولةِ الإمارات العربية المتحدة. وكان حُكَّامُ الإماراتِ قد اختاروا خليفةَ رئيسًا للدولةِ للمرَّة الأولى في الثَّالثِ من نوفمبر عامَ (2004م) خَلَفًا لوالِدِه الشَّيخِ زايد بن سلطان آل نهيان، وبعد أن أصبحَ حاكِمًا لإمارَةِ أبوظبي في الثَّان"},{"id":5805,"era":"c15","t":"وفاةُ الشيخِ الأُصوليِّ محمد سليمان الأشقر .","s":"وُلِد الشيخُ محمد سليمان الأشقر في قريةِ بَرقَة التَّابعةِ لمُحافظة نابُلُس في الثلاثينات من القرن الماضي، وهو من بيتِ علمٍ، وكان رحمه الله المدرِّسَ الأولَ لأخيه الدكتور المعروف الشَّيخِ عمر سليمان الأشقر... وخَرَج الشيخُ الأشقر من فِلَسطين إلى المملكة العربية السعودية، وعَمِل مدرِّسًا في جامعةِ الإمام محمد بن سعود في الرِّياض مع سماحة الشيخ عبد العزيز بن باز رحمه الله تعالى، ثم انتَقَل إلى المدي"},{"id":5806,"era":"c15","t":"حَظرُ المآذنِ في سويسرا. .","s":"يعيش في سويسرا (400) ألفِ مسلمٍ يصلُّون في مساجدَ ذاتِ مظهرٍ متواضِعٍ وتُوجَد فيها أربعُ مآذِنَ فقط، ومع ذلك فقد حَظَرت الحكومةُ بناءَ مآذنَ جديدةٍ فيها بعد استفتاءٍ كانت نتيجتُه (57%) يؤيِّدون الحظْرَ؛ وذلك خوفًا من المَدِّ الإسلاميِّ في أوربا."},{"id":5807,"era":"c15","t":"سبعةُ آلاف شخصٍ وثمانِي قرًى بالكاميرون تعتنق الإسلام .","s":"دخل سكانُ ثماني قرًى في بلاد الكاميرون في الدينِ الإسلاميِّ بتوفيقِ الله وكرمِه، وقد كانت تلك القرى تدينُ بالوثنيةِ ثمَّ تنصَّر أهلُها بسبب أنشطةِ الكنيسةِ في البلادِ، ثم وفَّق الله تعالى بعضَ الدعاة في إقناع أهلِها بالإسلامِ حتى أسلموا، ثم بدَأَت جهودُ تثبيتِهم على الدين. وهذه القُرى هي: كوادي، وتولوم، وبيزيل، أسلَمَت واحدةً تِلْوَ الأخرى، واعتنق الإسلامَ ثلاثةُ آلافِ شخصٍ فيها، كما قام مجموعةٌ م"},{"id":5808,"era":"c15","t":"وفاةُ محمد سيد طنطاوي شيخِ الأزهرِ .","s":"وُلِد محمد سيد طنطاوي في (28 أكتوبر 1928م) بقريةِ سليم الشرقية في محافظة سوهاج. تعلَّم وحَفِظ القرآنَ في مدينةِ الإسكندرية. حصل على الدكتوراه في الحديثِ والتفسيرِ عامَ (1966) بتقدير ممتاز، ثم عَمِل مدرِّسًا في كليَّةِ أُصولِ الدين، ثم انتُدِب للتدريسِ في ليبيا لمدةِ (4) سنواتٍ. عَمِل في المدينة المنوَّرة عميدًا لكليَّةِ الدِّراسات العليا بالجامعةِ الإسلاميَّةِ، وعُيِّن مُفتيًا للديار المِصرِيَّة ف"},{"id":5809,"era":"c15","t":"قيامُ إسرائيلَ بفتحِ \"كنيس الخراب\" قُربَ الأقصى .","s":"افتَتَحت دولةُ الاحتلال \"كنيس الخراب\" قُربَ المسجدِ الأقصى، وفَرَضت شرطةُ الاحتلالِ منذ الإعلانِ عن افتتاحِه قيودًا مشدَّدةً على المسجدِ الأقصى؛ حيث مَنَعت دخولَ المَقدِسِيِّين وفِلَسطينيِّي (48) إلى البلدةِ القديمةِ والمسجدِ الأقصى المبارك، ومَنَعت مَن تَقِلُّ أعمارُهم عن (50) عامًا من الدخولِ لأداء الصلواتِ، وقامت باحتِجازِ بطاقاتِ هُوِيَّةِ مَن سُمِح لهم بالدُّخول، كما نَشَرت قُرابةَ (2500) جند"},{"id":5810,"era":"c15","t":"تعيينُ أحمد محمد الطيب شيخًا للأزهر .","s":"الدُّكتور أحمد محمد الطيب حاصلٌ على درجةِ الدكتوراه من فرنسا في الفلسفةِ الإسلاميَّة، وهو شيخُ الطريقةِ الأحمديَّةِ الخَلوتِيَّةِ الصُّوفيةِ بصعيد مصر. عُيِّن شيخًا للأزهر بعد وفاةِ سابقِه محمد سيد طنطاوي. وكان من قَبلُ مُفتيًا لمصر ثم رئيسًا لجامعةِ الأزهرِ، وعُضوًا في لجنة السِّياسات بالحزب الحاكم، إلى أنْ صَدَر قرارُ تعيينِه شيخًا للأزهر."},{"id":5811,"era":"c15","t":"وفاةُ الرئيس النيجيريِّ عومارو يار أدوا. .","s":"الرئيسُ عومارو يار أدوا (58 عامًا) انتُخب رئيسًا عامَ (2007)، خلفًا لأولوسيغون أوباسانجو الذي كان سمَّاه كخَلَفٍ له داخلَ حزب الشعبِ الديموقراطيِّ. أُصيب بمرضٍ في غشاءِ القلبِ، نُقل على أثرِه إلى مستشفى في المملكة العربية السعودية لتلقِّي العلاجِ، ثم عاد إلى نيجيريا، وتسلَّم القائمُ بأعماله جودلاك جوناثان السُّلطاتِ الانتقاليةَ بقرارٍ من البرلمان وأصبح منذ ذلك الوقتِ الحاكِمَ الفعليَّ في البلاد. و"},{"id":5812,"era":"c15","t":"إعلانُ تغيِيرِ المناهِجِ الدينية بمِصرَ .","s":"أعلن أحمد زكي بدر وزيرُ التربية والتعليم المصري، والدكتور علي جمعة مفتى الجمهورية اتِّفاقَهُما على بدءِ تعديلِ مناهِجِ التربيةِ الدِّينية الإسلاميةِ المقرَّرة على الصفوف من الأوَّلِ الابتدائيِّ وحتى الثالثِ الثانويِّ عَبْرَ لجنةٍ يُشَكِّلُها الطرفانِ تبدَأُ عملَها بناءً على معايِيرَ يَضَعُها المُفتِي. وأوضَحَا أنَّ عمليةَ تغيِيرِ كتبِ الدينِ الإسلاميِّ تستهدِفُ تنقيتَها ممَّا سمَّيَاه الأفكارَ الت"},{"id":5813,"era":"c15","t":"وفاةُ محمد عابد الجابري .","s":"محمد عابد الجابري مفكِّرٌ مغربيٌّ وُلِد غُرَّةَ شوالٍ (1354هـ)، وكان أستاذَ الفلسفة والفكرِ العربيِّ الإسلامي في كليَّة الآداب بالرباط. حَصَل على دُبلوم الدِّراسات العليا في الفلسفة في عامَ (1967) ثم دكتوراه الدَّولة في الفلسفة عامَ (1970) من كليَّة الآداب بالرباط. عَمِل كمعلِّمٍ بالابتدائيِّ (صف أول) ثم أستاذِ فلسفةٍ عضوِ مجلسِ أُمناءِ المؤسَّسة العربية للديمقراطية. استطاع محمد عابد الجابري عَبْر"},{"id":5814,"era":"c15","t":"أُسطولُ الحُرِّية .","s":"أُسطولُ الحُرِّية؛ هو مجموعةٌ من ستِّ سفنٍ، تضمُّ ثلاثَ سفنٍ تتبَعُ مؤسَّسَةَ الإغاثةِ الإنسانيَّةِ التُّركية، واحدةٌ من هذه السفن الثلاثِ هي سفينةٌ كُويتية، وواحدةٌ تركيةٌ، وواحِدَة جزائريةٌ، وثلاثُ سفنٍ من منظمةِ غزَّةَ الحرةِ، تحمِل على مَتنِها موادَّ إغاثةٍ ومُساعداتٍ إنسانيَّةٍ. جُهِّزت القافلةُ وتمَّ تسيِيرُها من قِبَلِ جمعياتٍ وأشخاصٍ مُعارِضين للحِصارِ الإسرائيليِّ المَفروضِ على قطاع غزَّة"},{"id":5815,"era":"c15","t":"وفاة الشيخ عبدِ الله الغُدَيَّان عضو هيئة كِبار العلماء في السعودية .","s":"الشَّيخُ عبدُ الله بنُ عبد الرحمنِ بنِ عبد الرزَّاق بن قاسِمٍ آل غُدَيَّان من بني تميم، وُلِد عامَ (1345هـ) في مدينة الزلفي، وتلقَّى مبادِئَ القراءة والكتابة في صِغَرِه على عبدِ الله بنِ عبد العزيز السحيمي وعبدِ الله بن عبد الرحمنِ الغيثِ وفالحٍ الروميِّ وتلقَّى مبادِئَ الفقهِ والتوحيدِ والنحوِ والفرائضِ على حمدان بنِ أحمد الباتلِ، ثم سافَرَ إلى الرياض عامَ (1363هـ) فدَخَل المدرسَةَ السعودية الابت"},{"id":5816,"era":"c15","t":"قتل زعيمِ حركةِ جُندِ الله السُّنية في إيران .","s":"شَنَقت السلطاتُ الإيرانيةُ عبدَ الملك ريغي رحمه الله زعيمَ حركة جُندِ الله السنيةِ، بتُهمة الإرهابِ، وكانت السلطاتُ الإيرانيةُ أعدَمَت أيضًا شقيقَ ريغي شنقًا في جنوب شرق إيران قبل ذلك بشهرٍ بالتُّهمةِ نَفسِها."},{"id":5817,"era":"c15","t":"سورية تمنع دخولَ الطالبات المنتَقبات إلى الجامعات .","s":"أعطى وزيرُ التعليم العالي السوري غياث بركات توجيهاتٍ تقضي بمَنعِ دُخولِ الطالبات المنتقبات إلى الجامعات السُّورية. وأعلن الوزيرُ السوريُّ رفْضَه لِمَا وصَفَه بالظَّاهرة التي تتعارضُ مع القِيَم والتَّقاليد الأكاديميَّة ومع أخلاقيَّاتِ الحرمِ الجامعيِّ."},{"id":5818,"era":"c15","t":"قَسٌّ أمريكيٌّ يدعو ليومٍ عالميٍّ لحَرقِ القرآنِ .","s":"أعلَنت وسائلَ إعلامٍ أمريكية متعددةً خُطَط كنيسةٍ أمريكية للإعلان عن يوم عالميٍّ يُسمَّى اليومَ العالميَّ لحَرقِ القرآنِ؛ بحيث يصادِفُ اليومُ المذكورُ الذكرى التاسعةَ لهجمات (11 سبتمبر 2001). وقد نَصَبت الكنيسةُ أمامَ مدخلِها الرئيسِ لوحةً مكتوبًا عليها: الإسلامُ من الشيطانِ، وقد وُجِّهَت إلى الكنيسةِ انتقاداتٌ شديدةٌ وردودُ أفعالٍ غاضبةٍ ومن جهاتٍ مختلفة. وادَّعى القَسُّ تيري جونز من فلوريدا الذي"},{"id":5819,"era":"c15","t":"حربُ أوربا على النِّقاب .","s":"تعرَّض النِّقاب لحملةٍ أوربِّية مكثَّفةٍ لحظْرِه في الأماكنِ العامة، وذلك في فرنسا وإسبانيا وإيطاليا وبلجيكا."},{"id":5820,"era":"c15","t":"قيامُ الثَّورة التُّونُسية .","s":"الثَّورةُ التُّونُسية، هي ثورةٌ شعبيَّةٌ، انطَلَقت بوفاةِ الشابِّ محمد البوعزيزي الذي أضرَمَ النَّارَ في جسدِه تعبيرًا عن غضبِه على بَطالَتِه؛ ومُصادرَةِ الشرطةِ للعربةِ التي يبيع عليها. فخرج آلافُ التُّونُسيين الرافضين للأوضاع المتردِّيَة؛ بسبب البَطالَةِ؛ وعدمِ وُجودِ عدالةٍ اجتماعية؛ وتفاقُمِ الفَسادِ داخِلَ النظام الحاكِمِ. ونَتَج عن هذه التَّظاهُرات سقوطُ قتلَى وجرحَى؛ كما أجبَرَت الرَّئيسَ ز"},{"id":5821,"era":"c15","t":"قيامُ الثورةِ المصريةِ .","s":"بدَأَت أحداثُ الثورةِ المصريَّة بتظاهُراتٍ سِلمية شارك فيها آلافُ المُحتَجِّين في القاهرة وغيرها، واختار الدَّاعُون إلى هذه التظاهُرات يومَ (25) يناير؛ لمُصادَفَته عيدَ الشرطة؛ وذلك تضامُنًا مع خالد سعيد، الشابِّ المصريِّ من الإسكندريَّة، الذي قيل: إنَّه اعتُقِل وعُذِّب حتى الموتِ في أحدِ أقسام الشُّرطة في (6 يونيو 2010). وأدَّى استمرارُ التظاهُرات إلى سقوطِ عَشَرات القتلى، ومئاتِ الجرحى، واعتقالِ"},{"id":5822,"era":"c15","t":"وفاة ملا \"محمد عزيزي\" أحدِ عُلماءِ أهلِ السُّنة في إيران .","s":"تُوفِّي الشيخُ ملا محمد عزيزي -رحمه الله- عن عمرٍ ناهَزَ الثَّمانين، بعد معاناةٍ طويلةٍ مع المرضِ، وتمَّ تشيِيعُ جُثمانه في جموعٍ حاشدةٍ من الطَّلَبة والعلماءِ وغيرِهم، وذلك في مسقط رأسِه، قرية \"برده رش\" من توابِعِ مدينة \"بانه\" في مديرية \"نمشير\". وكان من المُجتَهدين في الدعوة، في محافظةِ كُردستان الإيرانية. وقد وُلد في سنةِ (1349هـ) من أسرةٍ عُرِفت بالتديُّن والالتزام. وكان والدُه الشيخ عبد القادر"},{"id":5823,"era":"c15","t":"وفاةُ إمامِ الشِّيعةِ في المدينة المنوَّرة محمد علي العمري .","s":"تُوفِّي محمد علي العمري، المرجِعُ الأعلى لأتباعِ المذهبِ الشيعيِّ بالمدينة النبوية، عن عمرٍ يناهِزُ المئةَ عام، في مستشفى المدينة الوطني، وذَكَر ابنُه كاظم العمري أنَّ والِده تُوفِّي بعد صراعٍ مع المرض، وهو من مواليد عام (1327هـ)، ودرس في الحَوزَات العلمية في النجف عامَ (1349هـ) ثم عاد إلى المدينة بعد عامٍ بسببِ وفاةِ والدِه، ورَجَع بعد ذلك إلى العراق ومَكَث فيها (20) عامًا، ثمَّ عاد بعد ذلك إلى ا"},{"id":5824,"era":"c15","t":"قِيامُ الثورة اليمنيَّة .","s":"الثَّورةُ اليمنِيَّةُ هي ثورةٌ شعبيَّة اشتعَلَت يومَ الجُمعة الذي أُطلِقَ عليه اسم \"جمعة الغضب\"، وقاد هذه الثَّورَةَ الشُّبَّانُ اليمنيُّون بالإضافةِ إلى أحزابِ المُعارضَةِ؛ للمُطالبةِ بتغيِيرِ نظامِ الرئيسِ علي عبد الله صالح الذي حَكَم البلادَ أكثرَ من (30) عامًا، ومطالبَتِه بالقيامِ بإصلاحاتٍ سياسيةٍ واقتصادِيَّة واجتماعِيَّة. وكان لمواقِعِ التواصُلِ الاجتماعيِّ على الإنترنت مثلِ الفيسبوك إسهاما"},{"id":5825,"era":"c15","t":"وفاة الشيخِ صالح بن عبد العزيز الراجحي .","s":"تُوفِّي الشيخُ صالح بن عبد العزيز بن صالحٍ الراجحي، بسكتةٍ قلبيَّةٍ، في مستشفى الحبيبِ بمدينة الرِّياض عن عمرٍ ناهَزَ (88) عامًا، وصُلِّي عليه في جامِعِ الراجحي، وُلِد الشيخُ صالحٌ عامَ (1344هـ) في محافظة البكيرية بالقَصيم، وانتَقَل مع والِدِه إلى الرِّياض لطلبِ العلمِ والرِّزق، وكانت الرياضُ آنَذاك عامرةً بالحركةِ العِلميَّة والتُّجارية. وفي الرِّياض دَرَس على يدِ سَماحةِ الشيخِ محمد بن إبراهيم آ"},{"id":5826,"era":"c15","t":"قِيامُ الثَّورةِ اللِّيبيَّة .","s":"انطَلَقت الثورةُ اللِّيبيةُ بعد اعتقالِ محامي ضحايا سجن بوسليم \"فتحي تربل\" في مدينة بنغازي؛ فخَرَج أهالي الضَّحايا ومُناصِروهم لتَخليصِه؛ وتَلَتْها مُظاهَراتٌ للمُطالبةِ بإسقاطِ النِّظام بمدينةِ البيضاء، فأطلَق رجالُ الأمنِ الرَّصاصَ، وقَتَلوا بعضَ المتظاهِرين، كما خرَجَت مدينةُ الزنتان والرجبان في اليوم نفسِه، وقام المُتظاهِرون في الزنتان بحرقِ مقرِّ اللِّجان الثَّورِيَّة، ومركز الشُّرطة المحليِّ"},{"id":5827,"era":"c15","t":"وفاة نجم الدين أربكان .","s":"تُوفِّي رئيسُ وُزراء تركيا الأسبق نجمُ الدين أربكان عن عمرٍ يناهِزُ (84) عامًا، وكان يخضَعُ للعلاج في المستشفى. وقد وُلِدَ أربكان في (29 أكتوبر 1926م)، وهو مهندسٌ وسياسيٌّ تركيٌّ، تولَّى رئاسةَ حزبِ الرفاة ورئاسة وزراء تركيا من الفترة بين (1996 و1997) وقد عُرِف بتوجُّهاتِه الإسلاميةِ. وهو حاصِلٌ على الدكتوراه من جامعة أخن الألمانية في هندسة المُحرِّكات عامَ (1956) وعَمِل أثناءَ دِراستِه في ألمانيا"},{"id":5828,"era":"c15","t":"دخولُ قواتِ درع الجزيرة إلى مملكة البحرَين .","s":"شهدت مملكة البحرين احتِجاجاتٍ وتظاهُراتٍ من الطائفة الشيعية، فطلَبَت المساعدة من \"درع الجزيرة\" وهي قواتٌ خليجيةٌ مشترَكةٌ أسَّسها مجلسُ التعاوُنِ الخليجيِّ في عامِ (1984)، فجاءت القُوَّاتُ لتأمينِ المُنشآت الإستراتيجيَّةِ بمملكة البحرَين."},{"id":5829,"era":"c15","t":"قيامُ الثورةِ السُّورية .","s":"الثَّورةُ السُّورية هي انتفاضةٌ شعبيَّةٌ بدَأَت سِلميَّةً ونُشِرَت على موقع الفيسبوك. وقد انطَلَقت الاحتجاجاتُ ضدَّ الرئيسِ بشار الأسد وحزبِ البعث السوريِّ، قاد هذه الاحتجاجاتِ الشُّبَّانُ السُّوريُّون الذين طالبوا بإصلاحاتٍ سياسيةٍ واقتصاديةٍ واجتماعيَّةٍ ورَفَعوا شعارَ: \"حرية... حرية\"، لكنَّ قوَّاتِ الأمن والمُخابَراتِ السُّوريةَ ومليشياتٍ مواليةً للنظام تُسمَّى بالشبِّيحة، واجهَتْهم بالرَّصاص، "},{"id":5830,"era":"c15","t":"مَقتَل قائدِ تنظيمِ القاعدةِ أسامةَ بنِ لادن .","s":"أعلَنَت الولاياتُ المتحدةُ الأمريكيةُ عن قَتلِ أسامةَ بنِ لادن زعيمِ تنظيمِ القاعدةِ في أبوت آباد الواقعةِ على بُعد (120كم) عن إسلام أباد، عَبْرَ عمليةِ اقتحامٍ استغرَقَت (40) دقيقةً. بعد أن داهَمَت مجمعًا سكنيًّا كان يُقيمُ به ابنُ لادن مع بعضِ زَوجاتِه وأبنائِه."},{"id":5831,"era":"c15","t":"توقيعُ اتِّفاقِ المُصالَحةِ بين فتحٍ وحماسٍ بالقاهرة .","s":"وقَّعت حرَكَتَا فتحٍ وحماسٍ الفِلسطِينِيَّتان اتفاقًا للمُصالَحة بينهما في القاهرة، شارك في الاجتِماعِ الذي تمَّ فيه التوقيعُ ثلاثةَ عشرَ فَصيلًا فِلَسطينيًّا، إضافةً إلى شخصياتٍ أخرى مستقلَّةٍ، ووكيلُ جهازِ المُخابَرات المِصرِيَّة، وقد رَأَس اجتماعَ التوقيعِ خالد مشعل عن حركة حماسٍ، وعزام الأحمد عن حركة فتحٍ، ولم يشهَدْ مناقشةَ أيِّ تفاصيلَ. وذكر طاهر النونو المتحدِّثُ باسمِ حركةِ حماسٍ أنَّ الات"},{"id":5832,"era":"c15","t":"وفاةُ الأديبِ الحَدَاثيِّ السعوديِّ عبد الله عبد الجبار .","s":"تُوفِّي الأديبُ السُّعودي الحَدَاثي عبد الله عبد الجبار عن عمرٍ ناهَزَ الـ(93) عامًا. وقد وُلد في مكة عامَ (1919)، ويلقَّب بـ\"الأستاذ\"؛ كونُه أشرَف على طُلَّابِ البَعَثات التعليميَّةِ من الحجازِ في مصر في الأربعيناتِ. وأصبح كِتابَاه: ((التيارات الأدبيَّة في قلب الجزيرة العربية)) و((قصَّة الأدب في الحجاز)) اللَّذانِ اشترك في تأليفِهِما مع الدكتور عبد المُنعِم خفاجي من المراجِعِ التاريخيَّةِ في الأد"},{"id":5833,"era":"c15","t":"وفاةُ الشيخِ عبدِ الرحمن البانِي .","s":"تُوفِّي الشَّيخُ عبدُ الرحمن البانِي رحمه الله عن عُمُر يناهِزُ المائةَ عامٍ. وهو من مواليد دمشق عامَ (1329هـ) الموافِقَ (1911م)، وهو من أسرةٍ دِمَشقية اشتُهِرت بالعلم، ومن عُلماءِ العربيَّة المعدودين، وصاحِبُ آراءٍ إصلاحيَّةٍ في قضايا التربيةِ الإسلاميَّة، قضى أكثرَ من سبعين سنةً في ميادين التَّربيَةِ طالبًا ومتعلِّمًا، ومدرِّسًا ومعلِّمًا، وموجِّهًا ومفتِّشًا، ومُشرِفًا ومُنظِّرًا، وخَبيرًا ومُس"},{"id":5834,"era":"c15","t":"اختيارُ المصريِّ نبيل العربي أمينًا عامًّا لجامعة الدول العربية .","s":"اختار وُزراءُ الخارجيَّةِ العربُ وزيرَ الخارجيَّةِ المصريَّ «نبيل العربي» كأمينٍ عامٍّ لجامعة الدُّوَل العربية، خلفًا لعمرو موسى الذي انتَهَت وِلايَتُه الثانيةُ، وبهذا يكون العربي سابِعَ أمينٍ عامٍّ للجامعة منذ تأسيسِها في العامِ (1945). عَمِل العربيُّ قاضيًا في محكمةِ العدل الدولية في لاهاي بين العامَين (2001 و2006). كما شَغَل منصِبَ رئيسِ لجنة الشُّؤون العربية بمجلِس الشورى، وقد جَرَت العادةُ عل"},{"id":5835,"era":"c15","t":"وفاةُ الشاعرِ السعوديِّ عبدُ الله بن خميس .","s":"تُوفِّي الشَّاعرُ السُّعوديُّ عبدُ الله بنُ محمد بنِ خميسٍ -رحمه الله- في العاصمةِ السُّعودية الرياض، وذلك بعد معاناةٍ مع المرض، وقد وُلِد عامَ (1339هـ) بقرية الملقى وهي إحدى قُرى الدِّرعية في مِنطَقة الرياض. وقد ألَّف -رحِمه الله- عشراتِ الكتبِ في الأدبِ والشِّعر والنَّقد والتُّراث والرِّحْلات، وصالَ وجالَ في الصَّحافَةِ والمُنتَديات والمُؤتَمرات داخِلَ المملكةِ وخارِجَها. ومن تلكَ الكتب: ((تاريخ"},{"id":5836,"era":"c15","t":"مُحاولةُ اغتيالِ الرئيسِ اليمني .","s":"بعد حشدِ أنصارِ الرئيسِ علي عبد الله صالح في جمعةٍ أسمَوها «جمعةَ الأمن والأمان»، تعرَّض الرئيسُ اليمنيُّ علي عبد الله صالح لمُحاولةِ اغتيالٍ، أُصيب من جرَّائها بحروقٍ بليغةٍ، وقد تمَّت مُحاولةُ اغتيالِه في مسجد دار الرِّئاسة. واتَّهم الإعلامُ اليمنيُّ أنصارَ الشيخِ صادقٍ الأحمر شيخ قبيلة حاشد بارتكابِ هذا التفجيرِ، بينما نفى مديرُ مكتبهِ أيَّ صلةٍ لهم بالهجومِ، وفي فجرِ يوم الأحد (5) يوليو أعلن ا"},{"id":5837,"era":"c15","t":"انفصالُ جنوبِ السُّودان عن شَمالِه .","s":"بعد نتيجةِ استفتاءٍ أجرَتْها الأممُ المتحدة انفصلَ جنوبُ السودان عن شَمالِه، بعد أن صوَّت (99%) من الجنوبيِّين لصالِحِ الانفصالِ عن الشمال، وأعلن رئيسُ البرلمان السودانيُّ الجنوبيُّ انفصالَ جنوبِ السودان رسميًّا؛ لتكونَ بذلك أحدثَ دولةٍ في العالم، وذلك بعد أكثرَ من خمسين عامًا من الحرب -تخلَّلَتْها فترةُ هدوءٍ لبضعةِ أعوامٍ- بين المتمرِّدين الجنوبيِّين وحُكوماتِ الخُرطومِ المتعاقبةِ. وأُقيم حفلٌ ر"},{"id":5838,"era":"c15","t":"بدءُ مُحاكمةِ محمد حسني مبارك الرَّئيسِ المصريِّ السابقِ .","s":"قُدِّم محمد حسني مبارك للمحاكمةِ العَلَنية بتهمةِ قَتلِ المُتظاهِرين في ثورة (25 يناير). وقد مَثَل أمامَ محكمةٍ مَدَنيةٍ في رمضانَ من هذا العامِ، في أكاديميَّةِ الشُّرطة التي تحوَّلَت إلى ساحةِ قضاءٍ برئاسة المستشار أحمد رفعت، وظهر مباركٌ راقدًا على سريرٍ متحرِّكٍ داخِلَ قفص الاتِّهام ومعه نجلاه علاء وجمال ووزيرُ الداخليَّة السابِقِ حبيب العادلي ومعاوِنوه، وبلغ عددُ الموجودين في القاعة أكثرَ من (3"},{"id":5839,"era":"c15","t":"إنشاءُ أولِ حزبٍ شيعيٍّ في مصرَ باسم \"الوَحدة والحرية\" .","s":"أعَلن المتشيِّعُ المصريُّ أحمد راسم النفيس عن تأسيسِ حزبِ \"الوحدة والحرية\"؛ ليكون بذلك أوَّلَ حزبٍ سياسيٍّ شيعيٍّ يتمُّ تأسيسُه في مصر. وللحزبِ مقرَّاتٌ في القاهِرَة والمنصورة والزقازيق. و\"أحمد راسم النفيس\" هو طبيبٌ وأستاذٌ جامعيٌّ شيعيٌّ اثنا عشريٍّ، وُلد عامَ (1952م) في المنصورة بمصر، واشتُهِر بسبب تحوُّلِه من المذهب السُنِّيِّ إلى المذهبِ الشِّيعيِّ في ثمانينيات القرن الماضي، وقد كَتَب حوالَي ("},{"id":5840,"era":"c15","t":"وُقوعُ أسوأِ مَوجةِ جفافٍ في الصُّومال منذ عقودٍ .","s":"أُصيب الصومال بمَوجةِ جفافٍ غيرِ مسبوقةٍ، أدَّت إلى أزمةِ مجاعةٍ ضَرَبت ستَّ مناطِقَ هي: ولايةُ شابيل السفلى، وجنوبُ باكول القَريبتانِ من منِطقَة باي، ومُخيَّماتُ أفقوي للَّاجئين شمالَ مقديشو التي ضمَّت (400) ألفِ لاجئٍ، ومُخيَّماتُ اللَّاجئين في العاصمةِ، ومِنطَقتَا بلادِ وادالي في شابيل الوسطى، ومِنطَقةٌ سادسةٌ هي منطقة \"باي\" الواقعةُ في الجنوبِ. وقد تضرَّر من هذا الجفافِ أكثرُ من أربعةِ مليون أ"},{"id":5841,"era":"c15","t":"وفاةُ شيخِ الحنابلةِ عبدِ الله بن عَقيلٍ .","s":"تُوفِّي شيخُ الحنابلةِ عبدُ الله بنُ عبد العزيز العَقيلُ الرَّئيس السابقُ للهيئةِ الدَّائمة بمجلسِ القضاءِ الأعلى في السُّعودية، عن عمرٍ يناهز (97) سنةً. وقد نشأ الشيخُ ابنُ عقيلٍ في كَنَفِ والدِه عبدِ العزيز العَقيلِ، الذي يُعَدُّ من أُدباء وشُعراء عُنَيزةَ المشهورين، فكان والِدُه هو معلِّمَه الأولَ. ودَرَس العلومَ الأوليَّةَ في مدرسةِ ابنِ صالحٍ، ثم في مدرسةِ الشيخِ عبدِ الله القَرعاوِيِّ. وحَفِ"},{"id":5842,"era":"c15","t":"اغتِيالُ بُرهانِ الدين رباني .","s":"اغتِيلَ في كابُل برهانُ الدين ربَّاني بن محمد يوسف -رحمه الله- والذي يُعَدُّ ثانِيَ رئيسٍ في كابُل بعد سُقوطِ الحكم الشيوعيِّ فيها في إبريل (1992)، وقد أُخرِج من كابُل في (26 سبتمبر 1996) على يدِ حركةِ طالِبان. وظلَّ ينتقِل في ولاياتِ الشَّمال التابعةِ له. وهو يُعتبَر أحدَ أبرزِ زُعماءِ تحالُفِ المعارَضةِ الشمالي، المعارِضِ لطالِبان، ووُلد في مدينة فيض آباد مركز ولاية بدخشان، وينتمي إلى قبيلَةِ ال"},{"id":5843,"era":"c15","t":"اعترافُ الاتِّحادِ الإفريقيِّ بالمَجلسِ الوطنيِّ الانتقاليِّ الليبِيِّ .","s":"رَفَعت مُفوضِيَّةُ الاتِّحادِ الإفريقيِّ عَلَمَ المَجلسِ الانتقاليِّ الليبِيِّ بدلًا من علمِ نظامِ العقيد مُعَمَّر القذافي. وكان الاتِّحادُ الإفريقيُّ قد أعلَن اعتِرافَه رسميًّا بالمَجلس الوطنيِّ الانتقاليِّ كقيادةٍ شرعيةٍ في ليبيا وممثِّلٍ شرعيٍّ للشعبِ الليبِيِّ، بعد اجتماعاتِ الجمعيَّةِ العامَّة للأُمم المتحدة في نيويورك، وسبق أنْ قدَّم المجلسُ الوطنيُّ الانتقاليُّ تعهُّداتٍ للاتِّحاد الإفريقيّ"},{"id":5844,"era":"c15","t":"إعلانُ تأسيسِ أوَّلِ حزبٍ سياسيٍّ في ليبيا .","s":"أُعلِن في بنغازي عن تأسيسِ \"حزبِ التجمع الوطني من أجل العدالة والديمقراطية\"، وذَكَر مؤسِّسوه أنهم يسعَون لتعبئةِ اللِّيبيِّين في سبيلِ إقامةِ مؤسَّساتِ دولةٍ مَدَنيَّة، تقوم على سيادةِ القانونِ والمُساواة. وأشارت مبادئُ وأهدافُ الحزبِ إلى أنَّه تجمُّعٌ لتحقيقِ العدالةِ والسَّعيِ إليها بين كلِّ الناس وكلِّ المدنِ والمناطِق."},{"id":5845,"era":"c15","t":"المُعارَضةُ السُّوريةُ تؤسِّس مَجلسًا وطنيًّا .","s":"أعلَن مُعارِضون سورِيُّون في مدينة إسطنبول التُّركيةِ تشكيلَ مجلسٍ وطنيٍّ للمُعارضةِ وأمانةٍ عامَّةٍ له، وذلك بهدفِ إسقاطِ نظامِ الرَّئيس بشار الأسد وإقامةِ نظامٍ ديمقراطيٍّ، وهذا المَجلسُ يضمُّ كافَّةَ الأطيافِ السِّياسية من اللِّيبراليِّين وبعضِ الإسلامِيِّين، وممثِّلين عن الأقلِّيَّتين الكُردية والآشورِيَّة."},{"id":5846,"era":"c15","t":"فتنةُ حادِثَةِ ماسبيرو بالقاهرة .","s":"اندَلَعت فتنةُ ماسبيرو والتي كانت بين النَّصارى الأقباط في مصر وبعضِ أهالي مصرَ من جانبٍ والجيشِ العسكريِّ المصريِّ من جانبٍ آخرَ، وانطَلَقت المُظاهرةُ من شُبْرَا أحدِ أحياءِ القاهرة ذي الكثافةِ القِبطيَّة وتوجَّهَت نحوَ مقرِّ الإذاعة والتلفزيون المصريِّ الواقِعِ في مِنطَقة ماسبيرو بالقُرب من مَيدان التحرير، أمَّا السببُ المباشِر لهذه المظاهَرة فهو المُطالَبة بإقالةِ مُحافظِ أُسوان لهَدمِه كنيسةً "},{"id":5847,"era":"c15","t":"تسليم الإسرائيلي شاليط مقابِل أكثرَ من ألف أسيرٍ فلسطيني .","s":"أفرَجَت حركةُ المقاوَمة الإسلامية \"حماس\" عن الجنديِّ الإسرائيليِّ \"جلعاد شاليط\"، بعد أن بَقِي في الأَسْرِ أكثرَ من خمسِ سنواتٍ، وسلَّمَتْه إلى مسؤولين مصرِيِّين، قاموا بتسليمِه إلى \"إسرائيل\"، عَبْرَ صفقةِ تبادُلِ الأسرَى بشرطِ إطلاقِ (1027) أسيرًا فلسطينيًّا بسُجونِ الاحتلالِ. ونَقَلت حماسٌ شاليطَ عبْرَ معبرِ رفحٍ إلى الجانب المصريِّ، وفَورَ تأكُّد وُصولِه إلى الأراضي المِصرِيَّة توجَّهت عائِلَتُه"},{"id":5848,"era":"c15","t":"الحصار على دار الحديث بدَماَّج في اليمن .","s":"فَرَض حُوثِيُّون حِصارًا على دار الحديث بدَماَّجٍ بصَعدَةَ، وقاموا بمَنعِ دُخولِ الموادِّ الغذائيَّةِ والأدوِيَةِ، ودُخولِ الطَّلَبة المستجَدِّين، وخُروجِ الحُجَّاج لأداء الحجِّ، وقاموا بقَتلِ بعضِ طَلَبةِ العلمِ عن طريقِ القنصِ من الجبال، ثم شنُّوا هُجومًا بالقذائفِ المِدفَعية والهاون قُتِل من جرَّائِه عَشَراتٌ من أهل السُّنة، وأكثَرُهم نَزَفوا حتى الموتِ؛ إذ لا تتوفَّرُ إمكانياتٌ طِبِّيةٌ بسبب ا"},{"id":5849,"era":"c15","t":"مقتلُ مُعَمَّر القذافي رئيسِ ليبيا .","s":"أانطلقت الثَّورة الليبية ُفي ربيعٍ الأول من هذا العام وتحوَّلت إلى ثورة مُسلَّحة انتهت بأسر  مُعَمَّر القذافي حيًّا في سرت مسقَطِ رأسِه لكِنَّه قُتِلَ بعد ذلك."},{"id":5850,"era":"c15","t":"وفاةُ الأميرِ سلطان بن عبد العزيز وليِّ العهد السعودي .","s":"تُوفِّي وليُّ العهدِ السُّعودي الأميرُ سلطان بن عبد العزيز آل سعود رحمه الله في نيويورك. وكان الأميرُ سلطان قد غادر المملكةَ إلى الولايات المتحدة للعلاجِ، وصُلِّي عليه بعد صلاةِ العصرِ يومَ الثلاثاء الموافقَ (27 من ذي القَعدة)، في مسجد الإمامِ تركي بن عبد الله بمدينة الرياض. وكان قد بدأ حياتَه السياسيَّةَ بتولِّي إمارةِ مِنطَقة الرياض عامَ (1947)، وعُيِّن وزيرًا للزراعةِ والمياهِ عامَ (1953) ثم ال"},{"id":5851,"era":"c15","t":"تعيينُ الأميرِ نايف وليًّا للعهد السعودي .","s":"أعلَن الدِّيوانُ الملكيُّ السعوديُّ اختيارَ الأمير نايف بن عبد العزيز وليًّا للعهد خَلَفًا للأميرِ سلطان بن عبد العزيز، الذي وافَتْه المنيَّةُ، وقال الدِّيوانُ الملكيُّ: إنَّ الملكَ عبدَ الله بن عبد العزيز قرَّر وأبلَغَ هيئةَ البَيعةِ بتعيِينِ الأمير نايف وليًّا للعهدِ ونائبًا لرئيسِ مجلسِ الوُزراء مع احتفاظِه بمَنصبِه وزيرًا للدَّاخلية، والأميرُ نايف كان يَشغَلُ قبلَ وفاةِ الأمير سلطان بن عبد الع"},{"id":5852,"era":"c15","t":"فوزُ حزبِ النَّهضةِ في الانتِخاباتِ التُّونُسية .","s":"أعلَنَت لجنةُ الانتِخاباتِ التُّونُسية أنَّ حزبَ النَّهضة الإسلاميَّ بزعامةِ راشد الغنوشي فاز بـ(90) مِقعَدًا من مقاعِدِ الجَمعيَّة التأسيسية الـ(217)، وبذلك يكون حزبُ النهضة قد حَصَل على أكثرَ من (41 %) من مَقاعدِ الجمعيَّة التأسيسِيَّة. وحركةُ النهضة (حركة الاتجاه الإسلامي سابقًا) تأسَّسَت (1972) وأعلَنَت عن نفسِها رسميًّا في (1981) ولم يتمَّ الاعترافُ بها كحزبٍ سياسيٍّ في تونس إلا في هذا العامِ"},{"id":5853,"era":"c15","t":"تعليقُ عُضوِيَّة سورية في الجامعة العربية .","s":"قرَّرت جامعةُ الدُّول العربية خلالَ اجتماعٍ طارئٍ لوُزراءِ الخارجيَّةِ العربِ بأغلبيَّةٍ ساحقةٍ تعليقَ عُضوِيَّة سورية؛ لعَدَمِ التزامِها بالمُبادرَة العربيَّة التي تنصُّ على التوقُّفِ عن قمعِ المُحتَجِّين. وهدَّدت الجامعةُ بمزيدٍ من الإجراءات ضدَّ نظامِ الأسد وبالتدخُّل لحمايةِ المَدنيِّين. وقد رحَّبت غالبيةُ جهاتِ المعارَضة السورية بالقَرار، ومنها المجلسُ الوطنيُّ السوريُّ، وهيئةُ التَّنسيقِ الو"},{"id":5854,"era":"c15","t":"اعتِقالُ سيفِ الإسلام القذافي .","s":"اعتُقِلَ سيفُ الإسلام بن مُعَمَّر القذافي والذي كان مطلوبًا لدى المَحكمةِ الجنائية الدوليةِ بتُهمة ارتكابِ جرائمَ ضدَّ الإنسانية. وأعلَن وزيرُ العدلِ وحُقوقِ الإنسان الليبيُّ محمد العلاقي: أنَّ سيفَ الإسلام الذي كان يُعتَبَرُ الوريثَ لوالِدِه اعتُقِل في جنوب ليبيا. وأكَّد قائدُ عمليَّاتِ الثُّوَّار في الزنتان بشير الطيب أن رِجالَه قَبَضوا على سيفِ الإسلامِ مع ثلاثةٍ من مُساعِديه في منطقة أوباري، و"},{"id":5855,"era":"c15","t":"توقيعُ الرئيسِ اليمني على المبادرة الخليجيَّة .","s":"وقَّع الرئيسُ اليمنيُّ علي عبد الله صالح على المُبادرةِ الخليجيَّةِ في الرياض؛ والمُبادرَة الخليجيَّة: هي مشروعُ اتفاقيَّةٍ سياسيَّةٍ أعلَنَتْها دولُ الخليجُ لإخراجِ اليمن من مَغبَّةِ الوُصولِ إلى انفجارِ الوضعِ، وحُصولِ حربٍ أهليَّةٍ داخِلَ البلدِ نتيجةَ تمسُّكِ الرئيسِ اليمنيِّ علي عبد الله صالح بالسُّلطة ورَفضِه التنحِّيَ عن الحكمِ بعد خُروجِ ملايِين اليمنِيِّين من الشَّبابِ وطلبةِ الجامعات ومُ"},{"id":5856,"era":"c15","t":"إقامةُ احتفالاتِ عاشوراءَ الشيعيةِ في مِصرَ لأوَّلِ مرةٍ .","s":"ظَهَرت في مِصرَ السُّنية لأولِ مرةٍ ما يسمَّى باحتفالاتِ عاشوراءَ الشيعية؛ حيث تجمَّع نحوُ (1000) شيعيٍّ من مُختلَف المُحافظاتِ، ووفدٌ من الشيعةِ العراقيِّين؛ لإحياءِ ذكرى مَقتلِ الحسين رضي الله عنه في كَربِلاء. وألقت الشُّرطة المصريةُ القبضَ على محمد الدريني القيادي الشيعيِّ ورئيسِ مؤسسةِ آل البيت بمصرَ وعَشَرةٍ من قيادات الشيعةِ قُبَيل بدءِ احتفالاتِ الشيعةِ بليلةِ عاشوراءَ بمسجِدِ الحُسين بالقا"},{"id":5857,"era":"c15","t":"انتخابُ المَجلسِ التأسيسيِّ «منصف المرزوقي» رئيسًا لتونس .","s":"انتَخَب المَجلسُ الوطنيُّ التأسيسيُّ التونُسيُّ «منصف المرزوقي»، أمينَ عامِّ حزبِ (المؤتمر من أجل الجمهورية)، رئيسًا لتونُس خلالَ المرحلةِ الانتقالِيَّة. وحَصَل المرزوقي على (153) صوتًا من أصل (217)، ويُعتبَر منصف المرزوقي أوَّلَ رئيسٍ لتونس يخلُف فؤاد المبزع الذي تولَّى رِئاسةَ البلاد مؤقَّتًا بعد سقوطِ نظامِ ابن علي. وقد وُلد منصف المرزوقي في عام (1945م) في جنوب تونُس، وسافر إلى فرنسا عامَ (1964"},{"id":5858,"era":"c15","t":"أيسلندا تعترِف بفِلَسطين دولةً مستقلةً .","s":"أعلَنَت أيسلندا اعتِرافَها رسميًّا بدولةِ فِلَسطين، وذلك في حفلٍ جَرَى في العاصمة ريكيافيك؛ لتُصبِحَ بذلك واحِدَةً من أوائلِ الدُّول الأوربِّية والغربية التي تقوم بهذه الخُطوةِ. وكان البرلمانُ الأيسلنديُّ قد صوَّت سابقًا لصالِحِ الاعتراف بدولةٍ فِلَسطينية على حدودِ ما قبل حرب عام (1967م)، وأتى هذا الاعترافُ بعد يومَين من رَفعِ العَلَم الفِلَسطيني للمرة الأولى فوقَ مقرِّ منظَّمةِ الأُمم المتحدة للت"},{"id":5859,"era":"c15","t":"إسرائيلُ تُفرِج عن (550) أسيرًا .","s":"أفرَجَت الحُكومةُ الصِّهيَونِيَّةُ عن (550) أسيرًا وأسيرةً من فِلَسطين، وذلك في المرحلةِ الثَّانِية من اتفاق تبادُلِ الأسرَى مقابِلَ إطلاقِ سراح الجنديِّ الإسرائيلي جلعاد شاليط الذي وقَّعَتْه الحُكومَةُ الصِّهيوَنِيَّة مع حركةِ المُقاوَمةِ الإسلاميَّةِ حماسٍ. وكان جميعُ الأسرى ممَّن حوكِموا على خلفيَّاتٍ أمنيةٍ ونشاطٍ مُقاوِمٍ للاحتلال. وكانت مصرُ قد رَعَت لسنواتٍ عديدةٍ إنجازَ صفقةِ تبادُلِ الأسر"},{"id":5860,"era":"c15","t":"مَقتلُ خليل إبراهيم زعيمِ متمرِّدي دارفور .","s":"قُتل خليل إبراهيم زعيمُ حركةِ العدلِ والمساواة إحدى جماعاتِ التمرُّدِ في إقليم دارفور بغرب السُّودان؛ وإبراهيمُ هو مؤسِّس حركة العدل والمساواة عامَ (2003م) مُطالِبًا بالمزيدِ من المُشارَكة في السلطةِ والثَّروة مِثلِ بقيَّةِ الحَرَكات الدارفورية الأخرى."},{"id":5861,"era":"c15","t":"تأسيسُ أوَّلِ حزبٍ إسلاميٍّ في ليبيا .","s":"أعلَن عُلماءُ دينٍ ليبيُّون عن تأسيسَ حزبِ (الإصلاح والتنمية) بعد أقلَّ من أُسبوعٍ على إعلانِ المَجلسِ الوطني الانتقاليِّ الليبيِّ إلغاءَ قوانينِ تَجريمِ الحزبِيَّة في عهدِ العقيدِ المخلوعِ مُعَمَّر القذافي. وأكَّدت اللَّجنةُ التأسيسيةُ في الحزبِ: أنَّه حزبٌ سياسيٌّ تنموِيٌّ مستقلٌّ يسعى للنُّهوضِ بالدَّولةِ في مُختلَف المَجالاتِ السياسِيَّة والاقتصادِيَّة والاجتماعية وَفْقَ معاييرِ وثوابِتِ الشَّ"},{"id":5862,"era":"c15","t":"المُعارَضة الموريتانية تُطلِق مجلسًا انتقاليًّا لإنقاذِ البلاد .","s":"أعلَنَت المُعارضةُ في موريتانيا عن تشكيلِ مجلسٍ انتقاليٍّ لإنقاذِ البلادِ. ودُعِيت جميعُ الأَطرافِ للالْتِحاق الفوريِّ بهذا المَجلسِ للمُشاركةِ في وَضعِ التَّصوُّرات العَمَلية لإطلاقه. كما قامت الأطرافُ المشكِّلة للمجلسِ بإمهالِ النظامِ الحاكمِ ثلاثةَ أشهُرٍ للاستِجابةِ لجُملةِ مطالِبَ، من بينِها رَفعُ الحظرِ عن المُنَظَّمات غيرِ المُرَخَّص لها، ورفعُ اليدِ عن القضاءِ ووسائل الإعلامِ العُمومية، وو"},{"id":5863,"era":"c15","t":"التَّيَّارُ السلفيُّ في اليمن يُطلِق أولَ حزب سياسيٍّ .","s":"أعلن مُمَثِّلون عن التيار السلفيِّ في اليمن عن إنشاءِ حزبٍ سياسيٍّ جديد باسم اتِّحاد الرشاد اليمني بهدفِ توحيدِ جُهودِ السلفيِّين في بلورةِ رُؤيةٍ منهجِيَّةٍ وسياسِيَّةٍ شامِلَةٍ. وقرَّر المُجتَمِعون تشكيلَ لجنةٍ تتولَّى التحضيرَ لمؤتَمر تأسيسيٍّ للحزبِ، وأعلَنوا عن نِيَّتِهم المشارُكةَ في الانتخاباتِ مُستقبَلًا، ودَعَوا إلى حوارٍ مع التمرُّدِ الشيعيِّ في الشمالِ ومع المُطالِبين بالانفصالِ في الجن"},{"id":5864,"era":"c15","t":"البَرلمانُ الكُويتي يُقِرُّ حُكْمَ القتل على المُسيئين لله ورسولِه .","s":"صادَقَ البرلمانُ الكُويتي في جولةٍ أُولَى من التصويتِ على تعديلاتٍ قانونيَّةٍ تنصُّ على تطبيقِ عُقوبةِ الإعدامِ على كلِّ مَن يُدان بسبِّ الذاتِ الإلهيَّةِ أو النبيِّ محمدٍ صلى الله عليه وسلم وزوجاتِه الكَريماتِ. وجاء تحرُّكُ البرلمانِ لتشديدِ العُقوباتِ على التَّجاوُزات الدينية بعد أنْ أوقَفَت السُّلطاتُ الشَّهرَ الماضيَ شَخصًا بتُهمةِ سبِّ الرَّسولِ صلى الله عليه وسلم وزَوجاتِه الكريمات وبعضِ الص"},{"id":5865,"era":"c15","t":"وفاةُ الشيخِ حامدٍ البيتاوي رئيسِ رابِطَةِ عُلَماء فلسطين .","s":"تُوفِّي الشَّيخُ حامِدٌ البَيتاويُّ رئيسُ رابطةِ عُلَماءِ فِلَسطين والنَّائِبُ في المَجلسِ التَّشريعيِّ عن كُتلةِ التَّغييرِ والإصلاحِ التَّابعةِ لحماسٍ، في مشفَى المقاصِدِ بالقُدس المُحتلَّة. وقد منع الاحتلالُ الصِّهيونِيُّ النائبَ البيتاويَّ من السفرِ لتلقِّي العلاج بالأردنِّ، ما اضطَرَّه لإجرائِها في القدس. والشيخُ البيتاويُّ رحمه الله شَغَل منصِبَ خطيبِ المسجدِ الأقصى سابقًا، وكان قد نَجَح في "},{"id":5866,"era":"c15","t":"وفاةُ الرَّئيس الجزائريِّ السابق أحمد بن بلَّة .","s":"تُوفِّي في الجزائرِ أوَّلُ رئيسٍ عرفَتْه البلادُ بعد مرحلةِ الاستقلالِ أحمدُ بن بلَّة، وذلك عن عمر ناهز (96) سنة. وُلد ابن بلَّة لأُسرةٍ من الفلَّاحين في الخامسِ والعشرينِ من ديسمبر (1916)، ونشأ في غربيِّ البلادِ قُربَ الحدودِ مع المغرِبِ، ويُعَدُّ من أبرزِ الشَّخصيات في حربِ الاستقلال ضدَّ الاستعمار الفرنسيِّ بعدَ الحرب العالميَّة الثانية، وقَضَى عدةَ سنواتٍ في السُّجون الفرنسية. وفي (27 سبتمبر 1"},{"id":5867,"era":"c15","t":"الإعلانُ عن تأسيسِ المَجلس الوطنيِّ الأعلى للثُّوار في ليبيا .","s":"أُعلِن ميثاقُ تأسيسِ المَجلسِ الوطني الأعلى لثُوارِ ليبيا. ويَنُصُّ ميثاقُ المَجلسِ على أن يكونَ الاسمُ المقترَحُ (المجلس الوطني الأعلى لثُوار ليبيا)، ومقرُّه مدينة طرابُلس، ويجوزُ له إنشاءُ فُروعٍ للمجلس في الدَّاخلِ والخارج. وينصُّ الاتِّفاق على أن يكونَ المَجلسُ مؤسَّسةً غيرَ حكوميةٍ مستقِلَّةً استِقلالًا تامًّا عن أيَّةِ مَرجعِيَّةٍ سياسيَّةٍ أو حزبيَّة أو دينية، ولا يعدُّ حَليفًا أو مُناصِرًا"},{"id":5868,"era":"c15","t":"افتِتاحُ أوَّلِ حُسَينية للشِّيعة في مصر .","s":"أقام عددٌ من الشِّيعةِ أوَّلَ حُسَينية لهم في مصرَ، ودَعَوا «علي الكوراني» أحدَ المَراجع الشِّيعية اللُّبنانية لإلقاءِ دُروسٍ فيها. وأثار افتِتاحُ أوَّلِ حُسَينية للشيعة في مصرَ غَضَبَ الأزهرِ، واستَنكرَ أعضاءُ مَجمعِ البُحوثِ الإسلامية ووِزارةُ الأوقاف‏ ونِقابةُ الأشرافِ زيارَةَ علي الكوراني لمصرَ،‏ وقيامَه بعقدِ نَدَواتٍ دينيةٍ خاصةٍ داخِلَ بُيوتِ عددٍ من الشِّيعة بالقاهرة والمُحافظات، وإلقاءَ م"},{"id":5869,"era":"c15","t":"إنشاءُ حزبِ جبهة الإصلاحِ الإسلامي في تونس .","s":"تمَّ إنشاءُ حزبِ (جبهةِ الإصلاحِ الإسلاميِّ) وذلك بعد أن مَنَحت السُّلطاتُ التُّونُسية ترخيصًا قانونيًّا بتأسيسِه؛ وذَكَر أحدُ قيادِيِّي ومؤسِّسي الحزبِ أن من مبادئِ الحزب أنَّه قائِمٌ على منهَجِ أهلِ السنَّة والجَماعَة بفَهمِ سلف الأمَّة؛ وذلك على المُستوَى العَقَدي. وأما سياسيًّا: فهو حزبٌ يؤمِنُ بآليَّاتِ العملِ الديمقراطيِّ والدَّولةِ المَدَنِيَّة وخِياراتِ الشَّعب الانتخابية."},{"id":5870,"era":"c15","t":"مَقتلُ وزيرِ الدفاعِ السُّوري ونائبِه ورئيسِ مكتبِ الأمنِ القوميِّ .","s":"قُتِل وزيرُ الدِّفاع السوري داود عبد الله راجحة، ونائِبُه آصف شوكت، صِهرُ بشار الأسد، ورئيسُ خليَّة الأزمة حسن تركماني، كما أُصيب وزيرُ الداخلِيَّة محمد الشعار، وذلك في التَّفجيرِ الذي استَهدَفَ مبنَى الأمنِ القوميِّ بالعاصمة دِمَشق. وتمَّ تعيِينُ العِماد فهد جاسم الفريج نائبًا للقائِدِ العامِّ للجيش والقُوَّات المُسلَّحة ووزيرًا للدفاع. وقد أعلَن الجيشُ السُّوريُّ الحرُّ مسؤولِيَّتَه عن الانفجار."},{"id":5871,"era":"c15","t":"الحُكمُ على الرئيسِ المِصريِّ السَّابق حسني مبارك بالسَّجنِ المؤبَّد .","s":"قَضَت المَحكمةُ التي تنظُر قضيةَ الرئيسِ المصريِّ حسني مبارك بالسَّجن المؤبَّد عليه وعلى وزير داخلِيَّتِه حبيب العادلي في قضيَّةِ قَتلِ المُتظاهِرين في ثورة (25 يناير). بينما قَضَت ببراءةِ مباركٍ ونجلَيه ورجلِ الأعمال حُسين سالم في قضيَّة التَّربُّحِ، كما حَكَمت ببراءةِ جميعِ مُساعِدي وزير الداخلية الأسبقِ في قضيَّةِ قَتلِ المُتظاهِرين."},{"id":5872,"era":"c15","t":"بدايةُ العُنفِ ضدَّ المسلمين في بورما .","s":"قام البوذِيُّون المُتطرِّفون بدعمٍ من السُّلطات البورمية بارتكابِ تجاوُزاتٍ ضدَّ مسلِمي الروهينجا في إقليمِ أراكان غربيِّ بورما، ونَتَج عن ذلك آلافُ القَتلَى والجَرحَى من المسلمين، بالإضافَةِ إلى إحراقِ آلافِ المنازل ومِئاتِ المساجدِ. ويقع إقليمُ أراكان ذو الأغلبيَّة المسلِمة في الجنوبِ الغربيِّ لبورما على ساحِلِ خليج البنغال والشَّريطِ الحدوديِّ مع بنغلاديش."},{"id":5873,"era":"c15","t":"وفاةُ وليِّ العهد السُّعودي الأميرُ نايف بن عبد العزيز .","s":"تُوفِّي الأميرُ نايفُ بنُ عبد العزيز رحمه الله وليُّ العهدِ السعودي ونائبُ رئيسِ مجلسِ الوُزراء ووزيرُ الداخلية، عن عمرٍ يناهز (83) عامًا، وذلك بعد أنْ غادر جُدَّةَ إلى جنيف بسويسرا لإجراءِ بعضِ الفُحوصات الطِّبِّية، وتَمَّت الصَّلاةُ عليه بالمسجدِ الحَرامِ بمكَّة المكرمة."},{"id":5874,"era":"c15","t":"فَوزُ الدُّكتور محمد مرسي برِئاسةِ جمهورية مصر العربية .","s":"فاز الدُّكتور محمد مرسي مرشَّحُ (حزب الحرية والعدالة) برئاسة جمهورية مصر العربية. وقد وُلد الدكتور محمد مرسي في قريةِ العدوة بمحافظة الشرقية، وحَصَل على بكالوريوس الهندسة من جامِعَة القاهرة عامَ (1975م) ثم حَصَل على الماجستير في هندسة الفِلِزَّات عامَ (1978م)، وحَصَل على الدكتوراه من جامعةِ جنوب كاليفورنيا عامَ (1982م) في حمايةِ محرِّكاتِ مَركباتِ الفضاءِ، وعُيِّن مُعيدًا ومدرِّسًا مساعدًا بكُلِّي"},{"id":5875,"era":"c15","t":"وفاةُ رئيسِ وُزراء القذافي .","s":"تُوفِّي رئيسُ الحُكومةِ اللِّيبيةِ السابقُ البغداديُّ المحموديُّ آخِرُ رئيسِ وُزراءَ في عهدِ مُعَمَّر القذافي، والذي تسلَّمَتْه السُّلطاتُ اللِّيبيَّة من تونُسَ، التي فرَّ إليها إبَّانَ الثَّورةِ اللِّيبيَّةِ."},{"id":5876,"era":"c15","t":"وفاة عمر سليمان نائبِ الرئيسِ المصريِّ ورئيسِ المخابرات .","s":"تُوفِّي اللواءُ عمر سليمان نائبُ الرئيس المصريِّ مبارك، ورئيسُ الاستِخباراتِ المصريَّةِ السابقِ الذي تم نقلُه إلى الولايات المتحدة الأمريكية في محاولةٍ لإنقاذِ حياتِه. وأُعلِن عن وفاةِ اللواء عمر سليمان عن عمر (76) عامًا في مستشفى بمدينة كليفلاند بولاية أوهايو الأمريكية، وشُيِّعت الجنازَةُ من مسجدِ آل رشدان بشرقِ القاهرة."},{"id":5877,"era":"c15","t":"تأسيسُ أوَّلِ مدرسةٍ شيعية في مصر .","s":"أنشأ الشيعةُ أولَ مدرسةٍ لهم في مِصرَ تضمُّ طُلَّابًا وطالباتٍ من عدة دولٍ عربيَّة وأجنبيَّة، منها الجزائرُ وإيران والولايات المتحدة وغيرُها من الدُّول."},{"id":5878,"era":"c15","t":"وفاةُ الشيخِ الدُّكتور عمر بن سليمان الأشقر .","s":"تُوفِّيَ الشيخُ الدكتور عمر بن سليمان الأشقر بالعاصمةِ الأردنِّية عَمَّانَ بعد معاناة مع المرض عن عمر يناهز (72) عامًا. وقد نعاهُ عددٌ كبير من المشايخِ والدُّعاة وطُلَّاب العلم. والشيخُ رحمه الله وُلد عامَ (1940م) بقرية بَرقة التَّابعة لمُحافظة نابُلُس بفِلَسطين، ثم خَرَج من فِلَسطين وهو ابنُ ستَّ عشرةَ سنةً إلى المدينة النبويَّة بالمملكة العربية السعودية، وأكمَلَ دِراستَه الثانويةَ العامَّةَ هناك"},{"id":5879,"era":"c15","t":"مَقتلُ رئيسِ هيئِة إفتاء أهلِ السُّنة بالعراق .","s":"قُتِل رئيسُ هيئةِ إفتاءِ أهلِ السُّنة مهدي الصميدعي رحمه الله وثلاثةٌ من عناصِرِ حِمايَتِه بسبب تفجيرِ سيارةٍ مفخَّخة استهدَفَت موكِبَه غرْبَ بغدادَ. ووقع الانفجارُ لدى خروجِ الصميدعي من مسجد عمر المختار في مِنطَقة حي اليرموك، غربَ بغدادَ، بعد أدائِه صلاةَ العيدِ."},{"id":5880,"era":"c15","t":"وُقوعُ مُواجهاتٍ دامِيَة بين السُّنة والنُّصَيرِيِّين بلُبنان .","s":"أدَّت الأزمةُ بين المسلمين السُّنة وبين النظامِ السُّوري في سوريَة إلى أعنفِ اشتباكاتٍ في لُبنان منذ الحربِ الأهليَّة اللُّبنانية التي دارت رَحاها بين (1975م و1990م)، واتَّهَمت المُعارَضةُ اللُّبنانية النظامَ السوريَّ برئاسة بشار الأسد بمُحاولاتِ إشعالِ الفتنة في شمالِ لُبنان، داعيةً أبناءَ مِنطَقة جبل محسن النُّصيرية إلى عدمِ الانجِرارِ إلى مُخطَّطِ النِّظام السوريِّ. ومِنطَقة طرابُلس من أكثرِ خُ"},{"id":5881,"era":"c15","t":"تشكيلُ الجيشِ العراقيِّ الحُرِّ لقتالِ حكومةِ المالكي .","s":"شُكِّل الجيشُ العراقيُّ الحُرُّ بهدف مُقاتلةِ حكومة المالكي لمَواقِفها المؤيِّدةِ لنظام بشار الأسد، كمُحاولَةٍ للتصدِّي للمُناصَرةِ الطَّائفيةِ من قِبَلِ الحُكومَة العراقيَّة للنِّظام السوريِّ، وتأمينِ الحُدود المشترَكة العراقيَّة السورية ومَنعِ وصولِ أيِّ دعمٍ عسكريٍّ لنظام الأسد عَبْرَ العراق، وقد انضمَّ بعضُ الضُّبَّاط الكبارِ المتقاعدين في الجيش العراقيِّ السابقِ إلى الجيشِ العراقيِّ الحرِّ."},{"id":5882,"era":"c15","t":"نصارى (أقباط) المَهجَر المِصريُّون يُنتِجون فيلمًا مسيئًا للرَّسول صلى الله عليه وسلم .","s":"قام نصارَى المهجر بإنتاج فيلمٍ يسيءُ إلى الرسولِ الكريم صلى الله عليه وسلم، ويصوِّر المُسلِمين على أنَّهُم إرهابِيُّون، ويَقتُلون النصارى في مصرَ، وقد أعلن عددٌ من أقباطِ المهجرِ -على رأسِهم عصمت زقلمة الدَّاعي إلى تقسيمِ مِصرَ ورئيسُ الدولةِ القبطيةِ المزعومةِ، وموريس صادق المعارِضُ المصريُّ، ومعهما القَسُّ المتشدِّدُ تيري جونز الذي حَرَق المُصحفَ الشَّريفَ أكثرَ من مرَّةٍ- أعلنوا عن إنتاجِ فيلمٍ"},{"id":5883,"era":"c15","t":"انتخابُ حسن شيخ محمود رئيسًا للصومال .","s":"فاز مرشَّح حزب (السلام والتنمية) البروفيسور حسن شيخ محمود برئاسةِ الصومال في تصويتِ البرلَمان. وكان أكثرُ من (24) مرشَّحًا قد تنافَسوا على هذا المنصِبِ، وانتقَدَت حركةُ الشَّباب الصوماليةُ اختيارَ حسن شيخ محمود رئيسًا جديدًا للبلاد، ووصفَتْه بالخائنِ وأنَّ الانتخاباتِ جَرَت بما لا يتماشَى مع مصلحةِ الشَّعب الصومالي، وأنَّها تمثِّلُ المصالِحَ الغربيَّةَ ومصالِحَ عُملائِها في المِنطَقة."},{"id":5884,"era":"c15","t":"تأسيسُ رابطةِ عُلَماء الشام لمُناصرةِ الثَّورة السورية .","s":"تمَّ تأسيسُ رابِطَةِ عُلماءِ الشامِ كمرجعيَّةٍ دينيَّةٍ لمُساندةِ الثَّورةِ السُّورية. وتلا الشيخُ كريم راجح رئيسُ الرابِطَةِ البيانَ التأسيسيَّ؛ الذي جاء فيه: أنَّ أحدَ أهدافِها هو دعمُ الثَّورة السورية والقيامُ بواجبِ جهادِ الكَلِمَة. وإنشاءُ رابطةِ عُلماء الشامِ هو في الواقِعِ إعادةُ تأسيسٍ لها من جديدٍ؛ حيث تمَّ إنشاؤها في سنة (1947م) لتنتهيَ في بداية السبعينِيَّاتِ مع ظهورِ نظامِ الرئيس السور"},{"id":5885,"era":"c15","t":"تدشينُ أضخَمِ مسجدٍ بجنوب إفريقيا .","s":"تمَّ تدشينُ أضخَمِ مسجدٍ بجنوب إفريقيا، بتمويلِ رجلِ أعمالٍ تركيٍّ، وذلك في بلدة ميدراند التي تقع بين العاصمِة الاقتصادِيَّة لجنوب إفريقيا جوهانسبورغ والعاصمةِ السياسيَّة بريتوريا. ودشَّن رئيسُ جنوب إفريقيا جاكوب زوما المسجِدَ بحُضورِ وفدٍ وَزاريٍّ تركيٍّ، والمسجدُ واقِعٌ في مَجمَعٍ إسلاميٍّ يضمُّ أيضًا مدرسةً وملاعبَ رياضيةً ومستشفًى. وقد بُنِي على نُموذجِ المسجدِ السُّليماني النظامي الذي شُيِّد "},{"id":5886,"era":"c15","t":"اتفاقُ سلامٍ يمنحُ المسلمين حُكمًا ذاتيًّا في جنوب الفلبين .","s":"أعلن الرَّئيسُ الفلبينىُّ بنينو أكينو أنَّ الحكومة الفلبينيَّةَ وجبهَةَ مورو الإسلاميةَ للتحريرِ توصَّلوا لاتفاقِ سلامٍ في جنوب البلاد. وأكَّد الرئيسُ نهايةَ صراعٍ استمرَّ (40) عامًا وأدَّى إلى سقوطِ أكثرَ من (100) ألف قتيلٍ وإصابةِ اقتصادِ المِنطَقة بالشَّلل. وتُحدِّد الاتفاقيةُ خارِطَةَ طريقٍ لإنشاءِ مِنطَقةٍ جديدةٍ تتمتَّع بحكم ذاتيٍّ في المناطِقِ التي تقطُنها أغلبيَّةٌ مسلمةٌ في جنوب الفلبين، "},{"id":5887,"era":"c15","t":"تحديدُ يومٍ عالميٍّ للُّغة العربيةِ .","s":"حدَّدت منظمةُ الأُمم المتحدة للتربيةِ والعلوم والثَّقافة المشهورةُ باليونسكو اليوم الـ(18) من ديسمبر في كلِّ عامٍ يومًا عالميًّا للُّغة العربية، وذلك ضِمنَ الأيَّام الدولية التي تحتفِلُ بها المنظَّمة. وجاء قرارُ المَجلسِ التنفيذيِّ للمنظَّمة بناءً على طلبِ المملكة العربية السعودية والمغرب. وسبق أنْ بدَأَت المجموعةُ العربية لدى اليونسكو في ترتيب الاحتفالِيَّة الأولى لهذه المناسَبة وقامت بتدشينِ شعا"},{"id":5888,"era":"c15","t":"مقتلُ خميس القذافي .","s":"قُتل خميس القذافي نجلُ العقيد الليبي الهالِكِ مُعَمَّر القذافي في مدينة بني وليد، أحدِ معاقِلِ أنصارِ القذافي، على يدِ مجموعةٍ من كتيبةِ حِطِّين التابعةِ لثُوار مصراتة، وتم نقلُه إلى مدينةِ مصراتة، متأثِّرًا بجِراحِه التي أُصيب بها خلالَ معارِكَ دارَت للقبضِ عليه مع مُوالين للقذَّافي."},{"id":5889,"era":"c15","t":"إسرائيلُ تقصِف مَصنعًا للذَّخيرة بالسُّودان .","s":"قام اليهودُ الصَّهايِنة بتفجيرِ مصنعِ اليرموك للذَّخيرة جنوبيِّ العاصمة السودانية الخُرطوم، وتسبَّب هذا الانفجارُ في اندلاعِ حريقٍ بالمصنع. وسَبَق أنْ قامت بضربِ مصنعِ الشِّفاء للأدوية في السودان عامَ (1998م)."},{"id":5890,"era":"c15","t":"اغتيالُ القائدِ العامِّ لكتائبِ القسَّام .","s":"اغتِيلَ القائِدُ الفعليُّ لكتائبِ الشَّيخِ عزِّ الدين القسام -الجناحِ العسكريِّ لحركةِ حماسٍ- أحمد الجُعبُري، في غارةٍ جويَّةٍ صِهيَونِيَّةٍ استهدَفَت سيارَتَه، في مدينة غزَّةَ. وقد أعلن الكِيانُ الصِّهيَونِيُّ مسؤولِيَّتَه عن عمليةِ اغتيالِ القائدِ الجعبري في غارة دقيقةٍ. وأنَّ رئيسَ هيئة الأركانِ الصِّهيَونِيَّة، قد أشرف بنفسِه على عمليَّةِ الاغتِيال."},{"id":5891,"era":"c15","t":"اعترافُ تركيا بالائتِلافِ الوطنيِّ السُّوري المعارِض .","s":"اعتَرَفت تركيا بالائتلافِ الوطنيِّ لقُوَى الثَّورةِ والمعارضةِ السُّورية كممثلٍ شرعيٍّ وحيدٍ للشَّعب السوريِّ. وقام بإعلانِ هذا الاعترافِ وزيرُ الخارجيَّةِ التُّركيُّ أحمد داود أوغلو في كلمتِه بالاجتماع الـ(39) لمَجلسِ وُزراء دُوَلِ منظَّمة التعاوُنِ الإسلاميِّ بجيبوتي."},{"id":5892,"era":"c15","t":"انضمامُ الكُويت إلى الاتفاقيَّة الأمنية الخليجيَّة .","s":"انضَمَّت الكُويت إلى السُّعودية، والإمارات، والبحرين، وقطر، وعُمَان، في الاتِّفاقيَّة الأمنيَّة الخليجيَّة، وكانت الكُويت هي الدولةَ الخليجيةَ الوحيدةَ التي رفضَتْها لمدةٍ طويلةٍ. ومن أهدافِ هذه الاتِّفاقيَّةِ توسيعُ التَّعاوُنِ والتَّرابُطِ بين هذه الدُّول في المجالات الأمنيَّة."},{"id":5893,"era":"c15","t":"انسِحابُ الجيشِ الفرنسي من كابيسا في أفغانستان .","s":"انسَحَب الجيشُ الفَرَنسي من آخِرِ ولايةٍ في أفغانستان كان يُقاتِل فيها وفَقَد فيها أكبرَ عددٍ من جُنودِه، وهي ولاية كابيسا في شمالِ شرق العاصمة الأفغانية كابُل. وغادر الجنودُ الفَرَنسيُّون هذه الولايةَ آخرَ قاعدةٍ لهم في كابيسا."},{"id":5894,"era":"c15","t":"اعترافُ (120) دولةٍ بالائتِلافِ الوطنيِّ ممثِّلًا للشعب السوريِّ .","s":"اعتَرَفت (120) دولةً مشارِكةً في مؤتَمَرِ أصدقاءِ سوريةَ في مدينة مراكُش المغربيَّة بالائتِلاف الوطنيِّ لقُوَى الثورةِ والمُعارَضة السوريَّة ممثِّلًا وحيدًا للشعب السُّوريِّ. وكان هدفُ المؤتمرِ الرئيسيُّ إيجادَ حلٍّ للأزمة السُّوريةِ بعيدًا عن مجلسِ الأمنِ الذي استخدَمَت روسيا والصينُ فيه حقَّ النقضِ ضدَّ مشروع القرارِ الخاصِّ بسورية، وكانت من ضمنِ الدُّول المشارِكَة وُزراءُ خارجيَّة أمريكا ودولُ "},{"id":5895,"era":"c15","t":"وفاةُ الشيخِ عبد السلام ياسين مؤسِّسِ جماعةِ العدلِ المغربية .","s":"تُوفِّي الشيخُ عبدُ السلام ياسين رحمه الله الزَّعيمُ الرُّوحيُّ لجماعة العدلِ والإحسان، بعد إصابتِه بوعكةٍ صحِّيَّة حادَّةٍ. وقد وُلد الشيخ عامَ (1928)، وعَمِل في سِلكِ التَّعليم لمدَّةِ (20) عامًا تدرَّج خلالَها في مجموعةٍ من المناصب التربويَّةِ والإدارية العالية. وفي سنةِ (1974) بَعث ياسين بنصيحةٍ إلى الملكِ الراحل الحسن الثاني، وهي عبارةٌ عن رسالةٍ حَوَت أكثرَ من (100) صفحةٍ سمَّاها: «الإسلامُ "},{"id":5896,"era":"c15","t":"وفاةُ الشيخِ محمدٍ السُّبَيِّلِ أحدِ أشهَرِ أئمَّةِ الحرمِ المكِّيِّ .","s":"تُوفِّيَ الشَّيخُ محمدُ بنُ عبد الله السُّبَيِّلُ رحمه الله أحدُ أشهرِ أئمَّةِ الحرمِ المكِّيِّ والرئيسُ الأسبَقُ للرِّئاسة العامَّةِ لشُؤون المسجدِ الحرامِ والمَسجدِ النبويِّ، والعُضوُ السابِقُ في هيئة كبارِ العُلَماء، والعضوُ في المَجمَع الفقهيِّ. وهو من مواليدِ مِنطَقة القصيم عامَ (1924م). وكان الشيخُ قد أُدخِلَ إلى مستشفى الحرس الوطنيِّ في جُدَّةَ بعد وعكةٍ صحيَّةٍ، وتُوفِّي عن عمر تجاوز الـ(8"},{"id":5897,"era":"c15","t":"وفاةُ الرئيسِ الموريتاني الأسبقِ المصطفى ولد محمد السالك .","s":"تُوفِّي في باريس الرئيسُ الموريتانيُّ الأسبَقُ المصطفى ولد محمد السالك، الذي حَكَم البلاد ما بين عامَي (1978م و1980م). وينحدِرُ المصطفى من ولايةٍ لعصابة جنوبَ شرق موريتانيا، وبدأ رِحلتَه الدراسيَّةَ من مدينة داكار ليُصبِحَ في النهايَةِ معلِّمًا، وبعد الاستقلال سنةَ (1960م) كان من أوائلِ الضُّباطِ الذين شكَّلوا نواةَ الجيشِ الموريتاني، وتلقَّى تكوينَه العسكريَّ في فرنسا، ثم تولَّى قيادةَ الجيشِ ما "},{"id":5898,"era":"c15","t":"اغتيالُ نائبِ مفتي أوسيتيا الشمالية .","s":"اغتِيلَ نائِبُ مفتي جمهورية أوسيتيا الشمالية بالقوقاز، إبراهيم دوداروف (34 عامًا) رحمه الله بخمسِ رَصاصاتٍ على الطريقِ المؤدِّيَة إلى العاصمة الإقليمية فلاديقوقاز. وتمَّ العثورُ على جُثَّتِه في سيارةٍ على طريقٍ يربِطُ مدينةَ فلاديقوقاز ببلدةِ تشمي."},{"id":5899,"era":"c15","t":"إصدارُ أولِ صحيفةٍ أُسبوعية للشِّيعةِ في تونس .","s":"صَدَر العددُ الأولُ من جريدة \"الصحوة التونسية\" وهي أوَّلُ جريدةٍ يُصدِرُها الشيعةُ في تونس، وتُعرِّف الجريدة نفسَها بأنَّها صحيفةٌ أُسبوعية عربية مستقِلَّة جامعةٌ تقوم على شعار: «الحقُّ أحقُّ أن يُتَّبَعَ!» وتسعى إلى تحريرِ العُقولِ وإيقاظ الهِمَم من أجلِ نهضةٍ عربية إسلاميَّةٍ إنسانية شاملة! -كما يزعُم القائمون عليها-، وتدَّعي الصحيفةُ أنَّ مشروعَها مَعنِيٌّ مباشرةً بتعزيزِ قِيَم الحرِّية والعدل "},{"id":5900,"era":"c15","t":"غرقُ مِنَصَّةِ إنتاجِ غازٍ إيرانية في الخليج .","s":"فقَدَت إيرانُ مِنَصَّةَ أوف شور التي استغرَق بناؤُها (30) شهرًا، وقيمَتُها (40) مليون دولار، ووزنُها (1850) طنًّا؛ حيث غَرِقَت عند تشغيلِها في حقل الغازِ العملاق ساوث بارس بالخليج والتي تتقاسَمُه إيرانُ مع قطرَ، تحت (80) مترًا في قعر البحر. وكان قد أُوكِل تنفيذُ المشروعِ بقيمةِ خمسةِ مليارِ دولارٍ إلى مجموعةِ خاتَمِ الأنبياءِ الصِّناعية لحرسِ الثورةِ الإيرانية بعد أن انسحَبَت في (2010م) شركِتَا شل"},{"id":5901,"era":"c15","t":"افتتاحُ إمامِ الحرمِ المكِّيِّ لأعلى مسجدٍ في العالَمِ .","s":"افتَتَح الشيخُ الدكتور خالد الغامدي إمامُ المسجِدُ الحرام بمكَّةَ المكرمةَ أعلى مسجِدٍ في العالم في قمَّةِ بُرجِ خليفة بمدينة دبي بدولة الإمارات العربية المتحدة،، وأَمَّ المُصَلِّين فيه، وذلك بدعوةٍ من إدارة البُرجِ الذي يُعدُّ حتى هذا التاريخِ أطوَلَ بُرجٍ في العالم بارتفاع (828) مترًا."},{"id":5902,"era":"c15","t":"اختيارُ شوقي إبراهيم عبد الكريم مفتيًا للدِّيارِ المِصرِيَّة .","s":"أعلَن أحمد الطيب شيخُ الأزهرِ أنَّ شوقي إبراهيم عبد الكريم -أستاذَ الفقهِ الإسلامي والشَّريعة بجامعة الأزهر \"فرع طنطا\"- حَصَل على أعلى نسبةِ تصويتٍ من أعضاءِ هيئةِ كبارِ العُلَماء بالأزهر لاختيارِ مُفتِي الجمهوريَّةِ خَلَفًا لعلي جمعة، عَقِبَ إجراءِ اقتراعٍ سريٍّ خلالَ اجتماعِ الهيئةِ برئاسة الدكتور أحمد الطيب شيخِ الأزهر."},{"id":5903,"era":"c15","t":"وفاةُ الأميرِ سطام بن عبد العزيز أميرِ منطقة الرياض .","s":"تُوفِّي الأميرُ سطام بن عبد العزيز رحمه الله أميرُ مِنطَقة الرياض في مدينة الرِّياض بعد معاناةٍ طويلةٍ من مرض السرطان، وأعلَن وفاتَه الديوانُ الملكي السعودي وهو الابنُ الثلاثون من أبناء الملكِ عبد العزيز الذُّكورِ. وقد صُلِّي عليه في جامع الإمام تركي بن عبد الله بالرياض، ثم نُقِلَ إلى مكَّةَ المُكرَّمَة ليُدفَن في مقبرة العدل تنفيذًا لوصِيَّتِه."},{"id":5904,"era":"c15","t":"هيئةُ عُلَماء المسلمين تستنكِرُ إنتاجَ فيلم إيراني يجسِّد النبي صلى الله عليه وسلم .","s":"استنَكَرت الهيئةُ العالميَّةُ للعُلَماء المسلِمين في رابطةِ العالمِ الإسلاميِّ بشدةٍ عَزْمَ شركةٍ سينمائية إيرانيةٍ إنتاجَ فيلمٍ يجسِّد شخصيَّةَ الرَّسولِ محمد صلى الله عليه وسلم. ودَعَت الهيئةُ في بيانٍ لها الحكومةَ الإيرانيةَ إلى إيقافِ تصويرِ هذا الفيلم ومنعِ عرضِ أيِّ جُزءٍ منه؛ فهي مسؤولة عمَّا يتمُّ في أراضيها، وعليها أن تمنعَ تجسيدَ شُخوصِ الأنبياءِ والرُّسل عليهم السلام، وخاتَمِهم محمدٍ صل"},{"id":5905,"era":"c15","t":"انتِفاضةُ مسلِمي إثيوبيا ضدَّ الحكومة .","s":"خرج مئاتُ الآلافِ من مسلِمي إثيوبيا في مظاهراتٍ كبيرةٍ بالعاصمة الإثيوبيَّة أديس أبابا وعدةِ مدنٍ أُخرى؛ استجابةً لدعوةِ ناشِطين في حركة \"ليُسمع صوتُنا\" الإثيوبية، وطالَبوا بحقِّهم في ممارسةِ شعائِرِهم الدينية دونَ تدخُّلِ الحكومة. ومنذ عامٍ أطلَق المسلِمون كلَّ أسبوعٍ دعوةً للحكومةِ إلى الالتزامِ بالدُّستور الإثيوبي الذي يحرِّم عليها التدخُّلَ في شؤونِ الأديان. وازداد غضبُ المسلمين بعد اعتقالِ ال"},{"id":5906,"era":"c15","t":"المُوافقةُ على تأسيسِ أكبرِ مسجدٍ في أيرلندا .","s":"وافَق مجلسُ بلدية \"دبلن\" الأيرلندية على إنشاءِ أكبرِ مسجدٍ في \"أيرلندا\"، قامت منظمة \"دبلن ويلفار\" الإسلاميةُ بتقديمِه إلى مجلسِ البلدية، وتبلُغ تكلفةُ المشروعِ حوالَي (40) مليون يورو، ممنوحةٍ من دولة الإمارات العربية المتحدة. وتبلُغ مساحةُ هذا المشروع (157) ألفَ متر مربع، تشمَلُ: مطعَمًا، وصالةَ مؤتَمراتٍ، ومدرسةً ابتدائيةً، وكلِّيَّةً، ويستوعِب المسجدُ حوالَي (500) مصلٍّ كلَّ جمعة و(3) آلافٍ في ا"},{"id":5907,"era":"c15","t":"اعترافُ هولندا بقسم الدِّراسات الإسلامية بجامِعَة روتردام الإسلامية .","s":"حَصَل قسمُ الدِّراسات الإسلامية لمرحلة البكالوريوس بجامعةِ روتردام الإسلامية بهولندا على الاعتمادِ الأكاديميِّ الرسميِّ، وهذا يمكِّن للجامعةِ تقديمَ طلبٍ للحُصولِ على الدَّعم الماديِّ من الحُكومة الهولنديَّة، وفَتْحَ فُروعٍ في كافَّة دول أوربا. وبهذا القرارِ الذي منحتْه منظَّمةُ الاعتماد الهولندية الفلمنكية (NVAO) يُعتَرف لأول مرةٍ لجامعةٍ إسلامية مستقلَّةٍ بتدريس البكالوريوس في قسمِ الدراسات الإس"},{"id":5908,"era":"c15","t":"وفاةُ الأمير بدرِ بن عبد العزيز آل سعود .","s":"تُوفِّي الأميرُ بدرُ بن عبد العزيز آل سعود رحمه الله نائبُ رئيسِ الحرسِ الوطنيِّ السعودي السابقُ. وقد شارَك في عددٍ من الوُفود واللِّجان بالمملكة، ورافقَ الملكَ فيصلَ بنَ عبد العزيز في زياراتِه الرسميَّةِ لبعضِ الدُّول العربية والإسلامية. وعُيِّن وَزيرًا للمُواصَلات عامَ (1381هـ-1961م)، وأصدر الملكُ فيصلٌ أمْرَه بتعيينِه نائبًا لرئيس الحرس الوطنيِّ في (3/11/1387هـ) الموافِقِ (1967م). وشارَك في وَض"},{"id":5909,"era":"c15","t":"وفاةُ الرئيسِ الجزائريِّ الأسبقِ علي كافي .","s":"تُوفِّي في العاصمةِ الجزائر الرئيسُ الجزائريُّ الأسبَقُ علي كافي عن عمرٍ تجاوز الـ(85) عامًا، بعد وَعكةٍ صحيَّةٍ أدخلَتْه المستشفى العسكري \"عين النعجة\"، بعد عمرٍ طويلٍ قضى بعضَه في جبال الأوراس حيثُ معاقِلُ الثَّورةِ الجزائرِيَّة زمنَ الاستِعمارِ الفَرَنسي كعقيدٍ في صفوفِ جيشِ جبهةِ التحريرِ الوطنيِّ. ويُعَدُّ علي كافي سادِسَ رئيسِ دولةٍ للجزائر المستقلَّةِ؛ حيث ترأَّس المَجلِسَ الأعلى للدولة مباش"},{"id":5910,"era":"c15","t":"رَفْعُ الحظرِ المَفروضِ على الحجابِ في بلجيكا .","s":"أُسقِطَ قرارُ حظرِ ارتِداءِ الحجابِ بعد قيامِ أكثرَ من عشرةِ آلافِ مُواطِنٍ بالتَّوقيعِ على إجراءِ تصويتٍ على طلبِ رَفعِ الحَظرِ عن الحجابِ، فتمَّ النِّقاشُ في مَجلسِ المدينةِ لأربَعِ ساعاتٍ انتَهَت بتصويتِ (29) من بين (51) عضوًا لصالِحِ إلغاءِ قرارِ الحظرِ على ارتداء الرُّموز الدينيَّة أو السياسيَّة. فأَسقَط تصويتُ الأغلبيَّة هذا القرارَ."},{"id":5911,"era":"c15","t":"وفاةُ العلَّامةِ زُهير الشاويش .","s":"تُوفِّي الشيخُ محمد زهير الشاويش في مدينة بيروت وصُلِّي عليه ودُفن في مقابِرِ الأوقافِ الجديدة. وعُرِفَ باسمِ زهير الشاويش وهو محقِّقٌ ومؤلِّفٌ سورِيُّ الجنسيَّة. وُلد في حيِّ المَيدان بمدينة دمشق وكان صاحِبَ ومؤسِّسَ المكتَب الإسلاميِّ للطِّباعة والنشر والتوزيع بدمشق، ويُعَدُّ أحدَ أعلامِ الدَّعوَة السلفيَّة في العصرِ الحديثِ، كان له قَصبُ السَّبقِ والرِّيادة في نشرِ التُّراث العلميِّ وتحقيقِه، و"},{"id":5912,"era":"c15","t":"فَوزُ نواز شريف في رِئاسةِ الحكومة الباكستانية .","s":"انتخَبَت الجمعيَّةُ الوطنيَّةُ الباكستانيةُ نواز شريف رئيسًا لحكومةِ بلادِه، وذلك بعد فوزِ حزبِه (الرابطة الإسلامية) بالأغلبيَّةِ في الانتخاباتِ التشريعيَّةِ، وقد شَغَل منصِبَ رئيسَ وُزراءِ باكستان لولايَتَين غيرِ مُتتالِيَتين ثمَّ أُطيح به في انقلابٍ عسكريٍّ قاده برويز مشرف، وتمَّ نفيُه بعد أن حُكِم عليه بالسَّجن مدى الحياةِ، ثم عاد إلى باكستان مُنهِيًا مَنفاه في السعودية بعد أن أصدرَت المحكمةُ ا"},{"id":5913,"era":"c15","t":"انتِخابُ حسن روحاني رئيسًا لإيران .","s":"فاز حسن روحاني برئاسةِ إيران وأصبَح الرئيسَ السابِعَ للجمهورية. وقد وُلد روحاني في (12 نوفمبر سنة 1948م) في مدينة سرخه، بالقُرب من محافظةِ سمنان شمالي إيران، من عائلةٍ متديِّنة قاتَلَت ضدَّ شاه إيران السابق. وقد انخَرَط في سلكِ الدِّراسات الدينية في الحَوزة العلميَّة في مدينتِه عامَ (1960م)، ثم انتَقَل إلى مدرسة قُم في عام (1961م)، وقد حضر دُروسَ العُلَماء البارزين في ذلك الوقتِ، مثلِ مرتضى الحائر"},{"id":5914,"era":"c15","t":"مَقتلُ رأسِ الشِّيعةِ في مصرَ حسن شحاتة .","s":"قُتِلَ رأسُ الشيعةِ في مصرَ حسن شحاتة وثلاثةٌ من أتباعِه من الشيعةِ المصريِّين، وحسن شحاتة أزهري تشيَّع منذ سِنين، وانتشَرَت عدةُ مقاطِعَ مصورةٍ له وهو يستهزِئُ ويتطاوَل على الصحابةِ الكِرامِ وأُمَّهات المؤمنين رضي الله عن الجميع. وقد هَجَم المِئاتُ من أهالي زاويةِ أبي مسلم على حسن شحاتة وأتباعِه الشيعةِ، أثناءَ اجتماعِهِم داخِلَ منزل حسن العريان الذي استضافَهم بداخِلِه بإحدى القرى وأوسَعُوهم ضربً"},{"id":5915,"era":"c15","t":"الإطاحةُ بالرئيسِ المصريِّ محمد مرسي .","s":"قام الجَيشُ المصريُّ بقيادة وزيرِ الدفاع الفريقِ أول عبد الفتاح السيسي بالإطاحة بالرئيس محمد مرسي وعزلِه عن رئاسةِ البلاد، وأعلَن عن خارِطَةِ طريقٍ مُستقبَليَّةٍ لمصر، وتعيينِ المستشار عدلي منصور رئيسِ المحكمة الدستورية رئيسًا مؤقَّتًا للبلاد، وأيَّد هذا الإجراءَ القضاءُ المصريُّ وشيخُ الأزهرِ وبابا الأقباط والحزبُ الوطنيُّ وحزب النور. وعارضته بعض الأحزاب السياسيَّة والإسلاميَّة، ودَعَت المؤسسةُ ا"},{"id":5916,"era":"c15","t":"وُقوعُ حادِثَتَي رابعة العدوية والنهضة في مصر .","s":"قام الحَرَسُ الجُمهورِيُّ والشُّرطة المصريَّةُ بفض الاعتصام بميدان رابعة العدوية والنهضة المؤيِّدين للرئيس محمد مرسي بالقوة، قُتِل وأُصيب فيها المئاتُ."},{"id":5917,"era":"c15","t":"وُقوعُ مَجزرةٍ مروِّعة بالكيماوي بالغُوطة الشرقية بسوريَة .","s":"قامت حُكومةُ بشار الأسد بمَجزرةٍ مروِّعةٍ في الغوطة الشرقيَّةِ بريفِ دِمَشقَ، استُخدِم فيها السلاحُ الكيماوِيُّ المُحرَّمُ دوليًّا والغازاتُ السامَّةُ في قَتلِ الأبرياءِ والأطفالِ والنِّساءِ والرِّجال؛ وكانت ضحيةُ هذه المجزرةِ المُروِّعة (2300) قتيلًا وأكثرَ من (5000) آلاف جريحٍ. كانت أعراضُ الإصابةِ بالكيماويِّ واضحةً على الضحايا، وعددُ القتلى في ازديادٍ بسبب قلَّةِ الأدوِيَة الطبية لعلاج المُصاب"},{"id":5918,"era":"c15","t":"وَضْعُ حسني مبارك تحتَ قيدِ الإقامةِ الجَبريَّةِ .","s":"صَدَر قرارٌ من رئيس الوُزَراء المصريِّ نائبِ الحاكِمِ العسكريِّ بوَضعِ الرَّئيسِ محمد حسني مبارك تحتَ الإقامَةِ الجَبريَّةِ، بعدَ ساعاتٍ من قرارِ المَحكمةِ بإخلاءِ سبيلِه في قضيَّةِ الفسادِ الماليِّ المعروفةِ باسم \"قضية هدايا الأهرام\"، وهي آخِرُ القضايا التي حُبِس على ذِمَّتها احتياطيًّا."},{"id":5919,"era":"c15","t":"وفاةُ أسامة الباز .","s":"تُوفِّي الدبلوماسيُّ المصرِيُّ الدُّكتور أسامة الباز المستشارُ السياسِيُّ للرئيسِ الأسبقِ محمد حسني مبارك رئيسِ مصرَ عن عمر تجاوز (82) عامًا. وأُطلق على \"الباز\" لقبُ \"خِزانة أسرار السُّلطة\" و\"عميد الدبلوماسية المصرية\"، بسببِ قُربِه من صُناَّع القرارِ في مصرَ لمدَّةٍ طويلة. وقد وُلِد أسامة بإحدى قرى محافظة الدَّقهلِيَّة، وحَصَل على ليسانس الحُقوق عامَ (1954م)، ودكتوراه في القانون العامِّ من الولايا"},{"id":5920,"era":"c15","t":"رَفضُ السُّعودية قَبولِ مقعدٍ غيرِ دائمٍ في مجلسِ الأمنِ الدَّولي .","s":"اعتذَرَت المملكة العربية السعودية عن عدمِ قَبولِ مقعدٍ غيرِ دائمٍ في مجلس الأمن الدولي؛ لأنَّ أُسلوبَ العملِ وازدواجيَّةَ المعايِيرِ الحاليَّةِ تمنعُ المَجلِسَ من أداءِ واجباتِه وتحمُّل مسؤولياتِه لإنهاءِ الحروبِ وغيرِها من المشاكِل في أنحاء العالَم. وذَكَرت أنَّها لا تستطيع قَبولَ المِقعَد إلى أنْ تُطبَّقَ إصلاحاتٌ على المَجلسِ."},{"id":5921,"era":"c15","t":"أنغولا تبدأ بهَدمِ المساجِدِ ومَنْع مُمارسةِ الشعائِرِ الإسلاميَّة .","s":"أعلَنَت وزيرةُ الثقافة في أنغولا روزا كروز دسيلفا مَنْعَ المُسلمين من مُمارسةِ شعائر الإسلام على أرض أنغولا، وشرَعَتْ في هدمِ المساجد، وقد كان هناك أكثرُ من (80) مسجِدًا لحوالَي نصفِ مليون مسلِم."},{"id":5922,"era":"c15","t":"قَتلُ الشَّيخ عبد القادر ملا مساعِدِ أمين الجماعة الإسلاميَّة ببنغلاديش .","s":"قَتلَت حكومةُ بنغلاديش مساعدَ الأمينِ العامِّ لحزب الجماعة الإسلامية ببنغلادش الشَّيخَ عبد القادر ملا رحمه الله. بتُهمةِ ارتكابِ جرائِمَ خلالِ الحربِ من أجلِ الاستقلالِ عن باكستان عامَ (1971م). وقد استنكَرَتْ عددٌ من الجهاتِ الإسلاميَّةِ الحدثَ وعدَّتْه من كُبرَى جرائِمِ حكومةِ بنغلاديش."},{"id":5923,"era":"c15","t":"سَيطرَةُ الحوثيِّين على مدينةِ \"دمَّاج\" وإخراجُ أهلِ السُّنَّة منها .","s":"اشتدَّ اعتِداءُ الحوثيِّين وحِصارُهم لمِنطَقَة دمَّاج؛ ممَّا أدَّى إلى خروجِ شيخِ دار الحديثِ بها، وكَثيرٍ من أهل السُّنَّة منها بعدَ مُفاوضاتٍ من قِبَلِ لجنةِ وَساطةٍ بينهم وبين جماعةِ الحُوثِيِّ، مقابلَ وَقفِ إطلاقِ النَّارِ، وفَكِّ الحِصارِ عن دمَّاجٍ."},{"id":5924,"era":"c15","t":"وفاةُ السَّفَّاح شارون .","s":"أُعلِنَت وفاةُ رئيسِ الوُزراء الصِّهيَونِيِّ الأسبق السَّفَّاحُ أرئيل شارون رسميًّا عن عمر ناهز (86) عامًا. وكان السفاحُ شارون من أكثرِ قادةِ الاحتلالِ إجرامًا بحقِّ الشعب الفِلَسطيني؛ لدورِه في الاجتياح الصِّهيَونِيِّ لجنوب لُبنان عامَ (1982م)، وارتكابِه مذبحةَ صَبْرَا وشاتِيلَا التي راح ضحيَّتَها آلافُ الشُّهداءِ من اللَّاجئين الفِلَسطينيين في لبنان. كما قام مع وَحدَتِه العسكريَّةِ بارتكابِ مذبح"},{"id":5925,"era":"c15","t":"وفاةُ الداعيَةِ العِراقي عبد الكريم زيدان .","s":"تُوفِّي الداعيةُ والمفكِّر الإسلاميُّ العراقيُّ الدكتور عبد الكريم زيدان عن عُمر يناهز (97) عامًا، بعدَ حياةٍ حافِلَةٍ بالعطاءِ الفِكريِّ والتَّربويِّ، والتأليفِ والتَّدريس. وزيدان عِراقيُّ الجنسيَّة مقيمٌ في اليَمَن منذُ سنواتٍ، يدرِّس في جامعةِ الإيمانِ التي يَرأَسُها الشَّيخُ عبد المجيد الزنداني. ويعدُّ زيدان أحدَ أبرزِ وُجوهِ الفِكرِ الإسلامي ومنظِّري الدَّعوةِ، تقلَّد العديدَ من المناصِبِ، ول"},{"id":5926,"era":"c15","t":"اغتيالُ الداعيةِ السلفيِّ محمد أوَّل آدم ألباني شمالي نيجيريا .","s":"اغتِيلَ الداعيةُ السَّلفيُّ البارز محمد أول آدم ألباني هو وزوجتُه بمدينة \"زاريا\"، في ولايَةِ كادونا شماليَّ نيجيريا، عندما كان عائدًا من إحدى دُروسِه. وآدم ألباني رحمه الله هو مؤسِّسُ أكاديميَّة علوم الألبانيِّ ودار الحديثِ، وكلاهُما يَقَعُ في مدينة \"زاريا\"، وكان واعِظًا مُعارِضًا للحكومة، زُجَّ به في السِّجن عِدَّةَ مراٍت؛ بسببِ آرائِه المُعارِضة. واعتُقِلَ عامَ (2011م) في أعقابِ العُنفِ الذي اتّ"},{"id":5927,"era":"c15","t":"السعوديَّة والإمارات والبحرَين يسحبون سُفراءَهم من قطر .","s":"نَشِب خلافٌ بين الدُّول الثَّلاث (السعودية والإمارات والبحرين) من جِهةٍ وبين دولة (قطر) من جهةٍ أُخرى، وقد أدَّى هذا الخِلافُ إلى سَحْبِ الدُّول الثلاث سُفراءَها من قطرَ وانضمت معها بعض الدول: كـمصر وجزر المالديف وموريتانيا واليمن."},{"id":5928,"era":"c15","t":"الاتِّحادُ الإفريقيُّ يوافِقُ على انضمامِ قطرَ كعضوٍ مراقِبٍ .","s":"تمَّ انضِمامُ قطرَ رسميًّا كعُضوٍ مراقِبٍ في الاتِّحادِ الإفريقيِّ، وكانت الكُويت والإمارات والسعوديَّة واليمنُ قد انضمُّوا كأعضاءَ مراقبين من قبلُ. ويُسمَحُ للأعضاءِ المُراقبين بالمشاركةِ في كافَّة أنشِطَةِ الاتِّحادِ الإفريقي، لكن لا يُسمَحُ لهم بالتَّصويتِ على القَراراتِ التي يُصدِرُها."},{"id":5929,"era":"c15","t":"اعتمادُ \"العربيَّةِ\" لُغةً رسميَّةً لجامبيا؛ تمهيدًا لإعلانِها جمهورية إسلاميَّة .","s":"أعلن الرَّئيسُ الجامبي \"يحيى جامي بات\" اعتمادَه اللُّغةَ العربيَّةَ لُغةً رسميَّةً في البلاد، وخروجَ جامبيا من مجموعة الكومنولث، وأنَّ جامبيا ستتوقَّف عن استخدامِ اللُّغة الإنجليزية بصِفتِها لُغةً رسميَّةً؛ لأنها \"إرثٌ استعماريٌّ\". وتأتي هذه الخُطوةُ في إطارِ التوجُّه الجديدِ للرَّئيس جامي؛ حيث أصبَحَ يتقرَّب من الدُّول العربيَّة والإسلاميَّة. وجمهورية جامبيا إحدى دُول غربِ إفريقيا، وعاصمَتُها بان"},{"id":5930,"era":"c15","t":"وفاةُ محمد قطب .","s":"وُلد محمد قطب في (26 إبريل 1919م) في بلدة موشا -من محافظة أسيوط بصعيد مصر- وكان والِدُه قُطب إبراهيم من المُزارِعين في تِلكَ النَّاحيةِ. أمَّا والِدَتُه فاطمة عثمان فقد كانت تَنتمي إلى أُسرةٍ مُحِبَّةٍ للعلم، بدأ دِراسَتَه في القاهرة ثم الْتحَقَ بجامعةِ القاهرة؛ حيث درَس اللُّغةَ الإنجليزية وآدابَها، وكان تخرُّجُه فيها عامَ (1940م)، ومن ثَمَّ تابَعَ في معهدِ التَّربية العالي للمُعلِّمين فحَصَل على"},{"id":5931,"era":"c15","t":"عشائِرُ العراق يتَّحدون ضدَّ الحكومة العراقيَّة .","s":"قامَت احتجاجاتُ سُنَّةِ العراق في بغداد وخَمْسِ محافظاتٍ أُخرى ضدَّ حكومة نوري المالكي؛ وذلك لدعم تنظيم «ثُوَّار العشائر» الذي يخوضُ معارِكَ شرسةً على جبهتين: الأُولى لمُقاتلةِ تنظيمِ (الدولة الإسلاميَّة في العراق والشام) «داعش»، والأُخرى لمنْعِ قُوَّات الجيش العراقيِّ من دُخولِ المُدُن."},{"id":5932,"era":"c15","t":"انتخابُ بوتفليقة رئيسًا للجزائر لولايةٍ رابعة .","s":"فوزُ عبد العزيز بوتفليقة بعُهدةٍ رئاسيَّة للمرَّة الرابعة وقد تمَّ تعيينُه رئيسًا للبلادِ عامَ (1424هـ-2003م)."},{"id":5933,"era":"c15","t":"تعيينُ أوَّل وزيرٍ مسلمٍ للثقافة في بريطانيا .","s":"تكليفُ عضوِ البرلمان المسلِم عن حزبِ المحافِظين (ساجد جافيد) بمنصِبِ وزيرِ الثقافة عَقِبَ استقالة ماريا ميلر من المنصِبِ بعدَ انتقادات برلمانيَّة لنفقاتِها، وهي المرةُ الأُولى التي يتولَّى فيها مسلمٌ منصِبًا مِثلَ هذا في بريطانيا."},{"id":5934,"era":"c15","t":"وفاةُ الشَّيخ محمد روَّاس قلعجي .","s":"تُوفِّي بالسُّعودية الشَّيخُ الدكتور محمد روَّاس قلعجي السُّوريُّ الأصلُ، عن عُمر يناهز الـ(80) عامًا، قضى الكثيرَ منها في التأليفِ والفقهِ والتعليمِ، وفي البُحوث العلميَّة الإسلاميَّة. والدُّكتور محمد رواس قلعجي -رحمه الله- من مواليدِ مدينةِ حَلَب عامَ (1934م)، وحَصَل على الدكتوراه من جامعةِ الأزهرِ بمصرَ في عامَ (1975). وقد تأثَّر كثيرًا بمحدِّث حلبَ الشَّيخِ محمد راغب الطباخ -رحمه الله- كما تأث"},{"id":5935,"era":"c15","t":"سلطنة بروناي تُعلِن تطبيقَ الشَّريعة الإسلاميَّة تدريجيًّا .","s":"أَعلن السلطانُ حسن بلقية سلطان بروناي عن بَدْءِ تطبيقِ أحكامِ الشريعة الإسلاميَّة في بلادِه، وأعلن عن المُصادَقةِ على قانونٍ جِنائيٍّ إسلاميٍّ جديدٍ يُطبَّق على المسلمين فقط. وتبلُغ نِسبةُ مسلمي بروناي (70%) من عددِ السكَّان، والبقيَّة من البوذيِّين والنَّصارى."},{"id":5936,"era":"c15","t":"وفاة عبدِ العزيز الخويطر وزيرِ الدَّولة لشؤون مجلسِ الوُزراء السعوديِّ .","s":"وفاة وزير الدولة لشؤون مجلس الوزراء السُّعودي الدكتور عبدُ العزيز الخويطر رحمه الله، الذي يُصنَّف من أقدمِ الوُزراء في المملكة. وُلد الخويطر في عُنيزة عامَ (1347هـ) الموافقَ (1925م)، ودرس فيها مرحلتَي الابتدائيَّة والمتوسِّطة، ثم انتقَل إلى المعهدِ العلميِّ السعودي بمكَّة المكرَّمة؛ لإكمال دِراستِه الثانوية، ثم ذهب إلى القاهرة ولندن لمواصلةِ دِراساتِه العليا في التاريخِ والفلسفة. ويُعدُّ الخويطر أ"},{"id":5937,"era":"c15","t":"إعادةُ انتخاب بشار الأسد رئيسًا لسوريةَ .","s":"فوزُ بشار الأسد في الانتخاباتِ الرِّئاسية بولاية ثالثةٍ مدتُها (7 سنوات). وجاءت هذه الانتخاباتُ بعد اندلاعِ الاحتجاجات في سوريةَ التي بَدَأت في (15 مارس 2011م)، والتي تطوَّرت فيما بعدُ إلى ما يُسمَّى الأزمَةَ السورية، وتمَّ بعدَها إقرارُ دستورٍ جديدٍ للبلاد اعتبارًا من تاريخ (27 فبراير 2012)، ومن أهمِّ التغيُّرات على مستوى رئاسةِ الجمهوريَّة إلغاءُ المادَّة الثَّامنة التي كانت تنصُّ على أنَّ حِزبَ"},{"id":5938,"era":"c15","t":"وفاة أدو بن عبد الله بايرو أميرِ ولاية كانو في شمال نيجيريا .","s":"وفاةُ أمير ولاية كانو في شمالِ نيجيريا (أدو بن عبد الله بايرو) رحمه الله عن عُمر يناهزُ (83) عامًا، وبايرو هو شخصيَّةٌ إسلاميَّةٌ مُبَجَّلة في شمالِ نيجيريا."},{"id":5939,"era":"c15","t":"تعيينُ عبدِ الفتاح السيسي رئيسًا لمصر .","s":"تم تعيينُ عبدِ الفتاح سعيد حُسين خليل السيسي رئيسًا لمصر، بعد الإطاحَةِ بالرَّئيس محمد مرسي. والسِّيسي هو الرَّئيسُ السَّادسُ لجمهورية مصر العربية، شغَل سابقًا منصِبَ القائِدِ العامِّ للقُوَّات المسلحة المصريَّةِ، ووزيرَ الدِّفاع الرابعِ والأربعين. وكان تخرَّج من الكُلِّية الحربية عامَ (1977م)، وعَمِل في سلاح المُشاةِ، وعُيِّن قائدًا للمِنطَقة الشماليَّة العسكرية، وتولَّى منصبَ مديرِ إدارةِ المخاب"},{"id":5940,"era":"c15","t":"الشَّيخُ تميمُ بن حمد آل ثاني يَتسلَّم مقاليدَ الحُكمِ لدولة قطر .","s":"تَسلَّم وليُّ العهد القطريُّ الشَّيخُ تميم بن حمد آل ثاني مقاليدَ السُّلطة، خَلَفًا لوالدِه الشَّيخِ حمد بن خليفة آل ثاني بعد مرورِ (18) عامًا على تولِّيه الحُكمَ. وقد وُلد الشَّيخ تميم في (3 يونيو 1980م) بالدَّوحة، وهو النَّجلُ الرَّابع للأمير حمد، وعُيِّن وليًّا للعهدِ في الخامِسِ من أغسطس (2003)، خَلَفًا لشقيقِه الأكبرِ الشَّيخِ جاسم، الذي تخلَّى عن المنصبِ."},{"id":5941,"era":"c15","t":"تنظيمُ الدولةِ الإسلاميَّة يُعلِنُ الخلافةَ الإسلاميَّة .","s":"أعلن تنظيمُ الدولة الإسلاميَّةِ في العراقِ والشامِ، أو ما يُعرف بـ\"داعش\" عن تأسيسِ ما أسماها \"دولةَ الخلافة الإسلاميَّة\"، وتسميتِها بـ\"الدولة الإسلاميَّة\" دُون إضافةِ العراقِ والشام، مؤكِّدًا وجوبَ مُبايَعةِ الخليفةِ. ونُصِبَ أبو بكر البغدادي خَليفةً للمسلمين ومبايعتُه، وبذلك -حسب زعمِهم- يُصبِح إمامًا وخليفةً للمسلمين في كلِّ مكانٍ تجب بيعتُه."},{"id":5942,"era":"c15","t":"الصِّين تحظُر الصومَ على موظَّفي ومعلِّمي \"شنغيانغ\" المسلمين .","s":"حَظَرت السلطاتُ الصينيَّةُ في إقليم \"شنغيانغ\" ذي الأغلبيَّةِ المسلِمة ممارسةَ شعيرةِ الصَّوم على الموظَّفين الحكوميِّين والمعلِّمين وطُلَّاب المدارس."},{"id":5943,"era":"c15","t":"حُكومة ميانمار تَمنَع مُسلِمي الروهينجا من صلاةِ التَّراويح في المساجِدِ .","s":"أغلَقَتْ حكومةُ ميانمار المساجدَ أمامَ مُسلِمي الروهينجا، ومنعَتْهم من أداءِ صلاةِ التَّراويحِ بالمساجدِ في كثيرٍ من مدنِ وقرى أراكان للعامِ الثاني على التَّوالي؛ ولم تسمحْ بفَتحِها للمصلِّين طيلةَ شهرِ رمضانَ."},{"id":5944,"era":"c15","t":"نُشوبُ حربٍ بين الكِيان الصِّهيَونِيِّ المحتلِّ وحكومَةِ حماسٍ بغَزَّةَ .","s":"شنَّ الجيشُ الإسرائيليُّ الغاصِبُ حربًا على غزَّةَ بعمليةٍ سُمِّيت بــ(الجرف الصامد) بعد موجةٍ عُنفٍ تفجَّرَت مع خطفِ وتعذيبِ وحرقِ الطِّفلِ محمد أبو خضير من شعفاط على أيدي مجموعةٍ مستوطِنين في (2 يوليو 2014)، وإعادةِ اعتقال العَشَرات من محرَّري صفقة شاليط، ودَهْسِ إسرائيليٍّ لاثنَين من العُمَّال العربِ قُربَ حَيفا، وقد ردَّت كتائبُ عزِّ الدِّين القسَّام بمعركةِ (العصف المأكول) وردَّت حركةُ الجهاد"},{"id":5945,"era":"c15","t":"انتخابُ فؤاد معصوم رئيسًا للعراق خَلَفًا للرئيس جلال طالباني .","s":"فؤاد معصوم سياسيٌّ كُرديٌّ من مواليد (1938م)، وقد شغَل مناصِبَ عديدةً، منها: رئاسةُ المجلسِ الوطنيِّ المؤقَّت في (2003م)، وكان أوَّلَ رئيسٍ لوُزراء حُكومةِ إقليم كردستان عامَ (1992م)."},{"id":5946,"era":"c15","t":"اغتيالُ إمامِ أكبرِ مساجِدِ شينجيانغ في الصِّين .","s":"اغتِيلَ جمعة طاهر إمامُ مسجد (إد كاه) في مدينةِ كشغر، أكبرِ مساجِدِ الصين في شينجيانغ، بعد صلاةِ الفجرِ. وجاء اغتيالُ الإمامِ رحمه الله بعد مواجهاتٍ عنيفةٍ وقعتْ في مِنطَقة يرقند على بُعد (200) كلم جنوب شرق كشغر. ويُقيم في شينجيانغ أكثرُ من تسعة ملايين أويغوري، وهم مسلِمون ناطِقون باللُّغة التُّركية يَرفُضون الوِصايةَ الصينيَّةَ."},{"id":5947,"era":"c15","t":"فوز الرَّئيس محمَّد ولد عبد العزيز برئاسة موريتانيا .","s":"فاز ولد عبد العزيز بولايَةٍ رئاسيَّةٍ ثانية من خمسِ سنواتٍ لموريتانيا، ولم يعترفْ منافِسُوه بالفوز، وصرَّحوا بتزويرِ الانتخاباتِ والتلاعُبِ في عددٍ الأصواتِ."},{"id":5948,"era":"c15","t":"أردوغان رئيسًا لتركيا بعد فوزِه في أوَّلِ انتخاباتٍ مباشرةٍ .","s":"فوزُ رجب طيب أردوغان في الانتخاباتِ الرئاسيَّةِ بغالبيَّةِ الأصواتِ، وكان أردوغان يَشغَلُ منصِبَ رئيسِ الوُزراء منذُ عام (2003)."},{"id":5949,"era":"c15","t":"اختيارُ \"محمد كامون\" أولَ رئيسِ وُزراءَ مُسلِمٍ لإفريقيا الوسطى .","s":"اختِيرَ محمد كامون مستشارُ رئيسِ جمهورية إفريقيا الوُسطى رئيسًا للوُزراء؛ ليُصبِحَ أوَّل رَئيسِ وُزراَء مسلمٍ للبلادِ."},{"id":5950,"era":"c15","t":"انتصارُ حكومَةِ غزَّةَ على الكِيانِ الصِّهيَونِيِّ .","s":"احتفَل آلافُ الفِلَسطينيين في قطاعِ غزَّةَ باتِّفاقِ وَقفِ إطلاقِ النَّار مع إسرائيلَ، وخَرَج آلافُ الفِلَسطينِيِّين في شوارعِ القِطاعِ احتفالًا بالاتِّفاق. واعتَبَرَت حركةُ حماسٍ التي تُسيطِرُ على قطاعِ غزَّةَ أنَّ الاتِّفاقَ يُعَدُّ انتصارًا للمُقاومةِ."},{"id":5951,"era":"c15","t":"اغتيالُ زعيمِ حركة \"جيش النصر\" البلوشية السُّنية غرب باكستان .","s":"اغتِيلَ عبدُ الرؤوف ريغي زعيمُ حركةِ \"جيش النصر\" البلوشيَّة السُّنيَّة في مدينة كويتا غربَ باكستان. وكان عبدُ الرؤوف ريغي رحمه الله قد تعلَّم العُلومَ الشَّرعيَّة والدِّينيَّةَ في مدارِسِ زاهدان، ثم انتقَل إلى كراتشي في باكستان، وتخرَّج من جامعةِ دار العُلوم بكراتشي في الدِّراساتِ الإسلاميَّة. وبعدَما أنهى ريغي الدراساتِ الإسلاميَّةَ عاد إلى بلوشستان إيران، وبدأ من هناك بتشكيلِ الفَصائلِ المسلَّحة"},{"id":5952,"era":"c15","t":"الخُرطومُ تَطرُد الملحقَ الثقافيَّ الإيرانيَّ .","s":"أصدَرَت الحكومةُ السودانيَّةُ قرارًا بغَلقِ جميعِ المراكزِ الثقافيَّة الإيرانية بها، وطرْدِ الملحَقِ الثَّقافي الإيراني ودبلوماسيِّين آخَرين بعد أن تأكَّد لها أنَّ المركزَ وفُروعَه قد تجاوزوا التَّفويضَ الممنوحَ لهم والاختصاصاتِ التي تُحدِّد الأنشِطَةَ التي يُخوِّلُهم القيامُ بها، وبذلك أصبحَ يُشكِّل تهديدًا للأمنِ الفِكريِّ والأمنِ الاجتماعيِّ بالسودان."},{"id":5953,"era":"c15","t":"بوكو حرام تُسيطِرُ على معظَمِ ولاية بورنو بنيجيريا .","s":"سيطَرَ مقاتِلو بوكو حرام على مُعظَمِ مناطِقِ ولاية بورنو شماليَّ البلاد. وقَبْلَ ذلك كانتْ جماعةُ بوكو حرام تُسيطِرُ على عددٍ من المُدُن شمالَ شرقيِّ البلاد من \"غمبورو نغالا\"، و\"غووزا\" في ولاية بورنو، إلى \"يوني يادا\" في ولاية يوبي، وحتى \"مادغالي\" و\"غولاك\" في ولاية أداماوا."},{"id":5954,"era":"c15","t":"اغتيالُ قادةِ أحرارِ الشامِ .","s":"قُتِل عددٌ مِن قادةِ حركةِ أحرار الشَّام في تفجيرٍ ضخْمٍ في بلدةِ رام حمدان بريف إدلب الشَّمالي؛ حيث كانوا في اجتماعٍ يَضمُّ من (40) إلى (50) من قادةِ الصفِّ الأوَّل والثاني بالحركةِ بينهم القائُد العامُّ أبو عبد الله الحموي (حسان عبود) رحمه الله. وأحرارُ الشامِ جماعةٌ إسلاميَّة تنضوِي تحتَ لواء تحالُف الجبهةِ الإسلاميَّة الذي يخوضُ صِراعًا مع نظامِ بشار الأسد."},{"id":5955,"era":"c15","t":"إنشاءُ تحالُفٍ دوليٍّ ضدَّ تنظيمِ الدولةِ الإسلاميَّة (داعش) .","s":"أعلَنتِ الولاياتُ المتحدة الأمريكيَّةُ عن تحالُفٍ دوليٍّ كبيرٍ لعَشَراتِ الدُّول الغربيَّة والعربية ضدَّ تنظيمِ \"الدولة الإسلاميَّة\" (داعش)."},{"id":5956,"era":"c15","t":"تركيا تُلغي قرارَ حَظرِ الحجابِ في المدارس .","s":"قرَّرت الحكومةُ التركيَّة رفْعَ حظرِ ارتِداءِ الفَتَيات للحجابِ في المدارسِ الإعداديَّة التركيَّة. وأعلن \"بولند أرنج\"، نائبُ رئيسِ الوُزراء والناطِقُ الرَّسميُّ باسم الحُكومةِ: أنَّ الحكومةَ التركيَّةَ عدَّلت لوائِحَ اللِّباس المدرسيِّ؛ حيث عدَّلت المادةَ الثالثةَ والرَّابعةَ من تلك اللوائحِ، وألْغَت بندَ (حاسِري الرأس) منها، بحيث سيُصبِحُ بإمكانِ الفَتَياتِ المُحجَّباتِ الذَّهابُ إلى المدرسة بحجا"},{"id":5957,"era":"c15","t":"من هو أشرف غني أحمد زاي؟ يحتاج لإضافة نبذة مختصرة عنه .","s":"يتسلم \"أشرف غني أحمد زاي\" رسميًّا منصِبَه كرئيسٍ لأفغانستان من خَلفِه الرئيسِ السابق \"حامد كرزاي\". وأُقيم حفلُ أداءِ اليمينِ في القصرِ الرِّئاسي بالعاصمة كابُل، وحضَرَه مسؤولون من عِدَّةِ دولٍ بينهم الرئيسُ الباكستاني \"ممنون حسين\"، ونائبُ رئيسِ الوُزراءِ التركيِّ \"بولند أرنج\"، ونائبُ الرئيسِ الإيراني، ونائبُ الرَّئيسِ الهنديِّ."},{"id":5958,"era":"c15","t":"ميانمار تمنَعُ مسلمي الروهينجا من الحجِّ للمرة الثانية .","s":"مَنعتْ حكومةُ ميانمار المسلمين من أقليَّةِ الروهينجا بإقليمِ أركان في ميانمار (بورما سابقًا)، من أداءِ فريضةِ الحجِّ للعامِ الثَّاني على التوالي، ولم يستطعْ أحدٌ من الروهينجيين الذَّهابَ لأداء فريضةِ الحجِّ؛ وذلك بسببِ الاضطهادِ الذي يتعرَّضون له."},{"id":5959,"era":"c15","t":"موريتانيا تُلغي إجازَةَ الجمعةِ .","s":"قامتِ الحكومة الموريتانية بتغيِيرِ عُطلة نهاية الأسبوع من يومَي الجُمعةِ والسَّبت إلى السَّبت والأَحَد، وندَّد كثيرٌ من الأئمَّةِ والفُقهاء بهذا الأمرِ، وعدُّوه معارِضًا للدُّستور الموريتاني، الذي ينصُّ على أنَّ الإسلام دِينُ الدولةِ والشَّعبِ، وطالَبوا السُّلطاتِ الموريتانيةَ بالتَّراجُعِ الفوريِّ عن هذا القرار المستفِزِّ لمشاعِرِ المسلمين."},{"id":5960,"era":"c15","t":"الائتلافُ السُّوريُّ يَنتخب أحمد طعمة .","s":"انتخَب الائتلافُ السُّوريُّ المعارِضُ الدكتورَ أحمد طعمة رئيسًا للحُكومةِ السُّوريَّة المؤقَّتة."},{"id":5961,"era":"c15","t":"اقتحامُ الصَّهايِنَةِ للمسجدِ الأقصى .","s":"اقتحَمَتْ مجموعاتٌ يهوديَّةٌ متطرِّفةٌ باحاتِ المسجِدِ الأقصى تحتَ حمايةِ قوَّاتِ الاحتلالِ الإسرائيليِّ، وقد سهَّلت قوَّاتُ الاحتلالِ عمليةَ الاقتحامِ هذه بعدَما فرَضَتْ إجراءاتِ أمنٍ مشدَّدةً في محيطِ المسجِد الأقصى وسمَحَت بدخول (900) يهوديٍّ وسائحٍ أجنبيٍّ إلى باحاتِ المسجِد الأقصى."},{"id":5962,"era":"c15","t":"المَحكمةُ الجزائيَّة السعوديَّة تحكُم بالقَتلِ تعزيرًا على الشِّيعيِّ نمر النمر .","s":"أَصدرت المحكمةُ الجزائيَّة المتخصِّصة في الرياضِ حُكمًا بالقَتْل تعزيرًا على نمر النمر؛ أحدِ مُثيري الفِتنة بالقَطيفِ، الذي كان يُطالِبُ بولايَةِ الفقيهِ في البَحرَين والسعوديَّة."},{"id":5963,"era":"c15","t":"نيجيريا.. حَظرُ ارتداءِ الحجابِ في المدارِس الحكومِيَّة بـ«لاغوس» .","s":"وافقَتِ المَحكمةُ العليا بمدينَةِ لاغوس النيجيريَّةِ على حظْرِ ارتِداءِ الحجابِ في مدارسِ الدَّولة بالعاصمةِ السَّابِقَةِ."},{"id":5964,"era":"c15","t":"وفاةُ المؤرِّخ محمود شاكر .","s":"تُوفِّي صباح الأحد المؤرِّخُ السُّوريُّ محمود شاكر في منزلِه بالعاصِمَة السُّعودية الرِّياض، وقد أَثرى رحمه الله المكتبةَ الإسلاميَّةَ بعشراتِ الكتبِ، كان أَبرزُها موسوعةَ \"التَّاريخ الإسلامي\"، كما عُرِف باهتِمامه البالِغِ بأحوالِ الأقلِّيَّات المسلِمةِ حولَ العالَمِ. وُلِد أبو أسامةَ محمودُ بنُ شاكرٍ في حَرَسْتا شمالَ شرقيِّ دِمَشق في شهر رمضان عامَ (1351هـ-1932م)، دَرَس الابتدائيةَ والإعداديةَ و"},{"id":5965,"era":"c15","t":"هجومٌ مُسلَّحٌ على صحيفةِ شارلي إبدو .","s":"وَقَع هجومٌ على مَقرِّ الصَّحيفَةِ السَّاخِرَة \"شارلي إبدو\" في باريس، وأدَّى إلى مقتلِ (12) شخصًا وإصابةِ (11) آخَرين، وكانت الصحيفةُ المَعنيَّةُ سبَق أنْ نشرَتْ رُسومًا مُسيئةً للرَّسولِ صلَّى الله عليه وسلَّم."},{"id":5966,"era":"c15","t":"مقتلُ الشَّيخِ محمد قمر الزمان ببنغلادش .","s":"نفَّذت السُّلطاتُ البِنغاليَّةُ حُكمَ القتلِ بحَقِّ مساعِدِ الأمينِ العامِّ لحِزبِ الجَماعةِ الإسلاميَّةِ محمد قمر الزمان رحمه الله، والذي أَصدَرتْه محكمةُ جرائِمِ الحَربِ الدوليَّةِ، التي تأسَّسَت في بنغلاديش عامَ (2010م) للتَّحقيق بجرائمِ الحربِ إبَّانَ حربِ الاستقلالِ عامَ (1971م). وقد قُتِل قمرُ الزمان في السِّجن الذي كان مُعتَقلًا فيه."},{"id":5967,"era":"c15","t":"وفاةُ الملك عبد الله بن عبد العزيز ملكِ المملكة العربية السعودية .","s":"المَلِك عبد الله بن عبد العزيز آلُ سعود هو الابنُ الثاني عشر من أبناءِ المَلِك عبد العزيز الذُّكور، وهو سادِسُ ملوكِ المملكة العربيَّة السعودية، وأُمُّه هي فَهدَة بنتُ العاصي بن شريم الشمري. وُلِد في عام (1924م) بمدينة الرِّياض، وقد نَشَأ في كَنَفِ والِدِه المَلِك عبد العزيز، واستفاد من مدرسَتِه وتَجارِبه في مجالاتِ الحُكْم والسِّياسةِ والإدارةِ والقيادةِ، عُيِّن قائدًا للحرسِ الوطنيِّ عامَ (1962م"},{"id":5968,"era":"c15","t":"مُبايَعةُ الأمير سلمانَ بنِ عبد العزيز ملكًا للمملكة العربية السعودية .","s":"بُويِعَ خادمُ الحرَمَين الشريفَين المَلِكُ سَلمان بنُ عبد العزيز آل سعود مَلِكًا للمملكة العربيَّة السعوديَّة، وكان قد قضى أكثرَ من عامَين ونصفٍ وليًّا للعهد ونائبًا لرئيسِ مجلسِ الوُزراء، كما بَقِيَ حِينَها في منصبِهِ وزيرًا للدِّفاع. وُلِد سلمانُ بن عبدِ العزيز في الخامسِ من شوَّال سنةَ (1354هـ) المُوافِق (31 ديسمبر 1935م) في الرِّياض، وهو الابنُ الخامِسُ والعشرون لمؤسِّس المملكة العربيَّة السعو"},{"id":5969,"era":"c15","t":"استيلاءُ الحوثِيِّين على السلطةِ في اليمن .","s":"استَولَى الحوثيُّون على السُّلطةِ واحتَلُّوا صنعاءَ، وسَيطروا على مقرِّ التلفزيون والمطار واقتَحَموا مَقرَّ الفِرْقة التي يقودُها علي محسن الأحمر، وجامعةَ الإيمان الإصلاحيَّةَ وسيطروا على مؤسَّساتٍ أمنيَّةٍ ومُعسكراتٍ ووِزاراتٍ حكوميَّة، فهَرَب الأحمرُ إلى السُّعودية، واستقال الرئيسُ عبدُ ربِّه منصور هادي ونائِبُه خالد بحاح في (22 يناير 2015م)، ووقعتْ معاركُ في إب والحديدةِ والبيضاءِ مع المقاومةِ "},{"id":5970,"era":"c15","t":"وفاةُ الشَّيخِ حارثٍ الضاري أمينِ هيئةِ عُلَماءِ المُسلِمين في العراق .","s":"توفِّي الشيخُ حارثٌ الضَّاري أمينُ عامِّ هيئةِ عُلَماء المسلمين في العراق، عن عمر يُناهِز (74) عامًا في مدينة إسطنبول التركيَّة، وُلِد الضاري عامَ (1941م). والشيخُ حارث الضاري رحمه الله هو أحدُ عُلَماء السُّنَّة في العراقِ، وكان يُقيم في العاصمةِ الأُرْدُنِّيَّة عَمَّانَ منذ دُخولِ القُوَّات الأمريكية للعِراق عامَ (2003م)، الْتَحَق الضاريُّ بجامعة الأزهرِ عامَ (1963م)، وحَصَل على شهادةِ اللِّيسانس"},{"id":5971,"era":"c15","t":"إطلاقُ عملية عاصِفة الحزمِ ضدَّ الانقلابيِّين الحوثيِّين في اليمن .","s":"تَمَّ إطلاقُ عمليَّة عاصفةِ الحَزْم ضدَّ الانقلابيِّين الحوثيِّين في اليمنِ، بقيادةِ المملكةِ العربية السعودية، ومشاركةِ تِسْعِ دُول، أبرزُها: الإماراتُ والكُويت والبحرَين وقطرُ والأردنُّ. وتُعْتبَرُ عاصِفةُ الحزمِ إعلانَ بدايةِ العمليَّاتِ العسكريَّةِ بقيادةِ السُّعودية في اليمن. وقد تَمَّ فيها السَّيطرةُ على أجواءِ اليمنِ وتدميرِ الدِّفاعاتِ الجويَّة ونُظُم الاتِّصالات العسكريَّة للحوثيِّين والر"},{"id":5972,"era":"c15","t":"تعيِينُ محمَّد بن نايف وليًّا للعهد .","s":"أَصدَر المَلِكُ سلمانُ بنُ عبد العزيز حُزْمةَ أوامِرَ مَلكيَّةٍ بتعيِينِ وإعفاءِ بعضِ الأُمراءِ من مناصِبِهم. وجاء في الأوامرِ إعفاءُ الأميرِ مقرن بن عبد العزيز من ولايَةِ العهدِ، وتعيِينُ الأمير محمد بن نايف بن عبد العزيز وليًّا للعهد مع احتفاظِه بوِزارة الدَّاخليَّة، وهو أوَّلُ حفيدٍ للمَلِك عبد العزيز آل سعود يُعيَّن وليًّا للعهد. وُلِد الأمير محمَّد بمدينةِ جُدَّة بتاريخ (25 صفر لعام 1379هـ) ا"},{"id":5973,"era":"c15","t":"تعيِينُ محمدِ بن سلمان وليًّا لوليِّ العهد .","s":"محمدُ بنُ سلمان بنِ عبد العزيز آل سعود، هو الابنُ السادسُ للمَلك سلمان بن عبد العزيز آل سعود. وُلِد محمدُ بنُ سلمان في (15 من ذي الحجَّة 1405هـ-31 أغسطس 1985م). حصَل على درجةِ البكالوريوس في القانون من جامعةِ المَلِك سعود. وفي عامِ (1434هـ) تَمَّ تعيينُه رئيسًا لديوانِ سُموِّ وليِّ العهد ومُستشارًا خاصًّا له برُتبةِ وزيرٍ. كمَّا تَمَّ تعيينُه مُستشارًا خاصًّا ومُشرِفًا على المكتبِ والشُّؤون الخاصّ"},{"id":5974,"era":"c15","t":"غاراتُ التحالُف تُدمِّر ضريحَ حسينٍ الحوثيٍّ مؤسِّسِ الحركة .","s":"شنَّ طيرانُ التَّحالُف العربيِّ -الذي تقودُه المملكةُ العربيَّةُ السُّعودية ضدَّ الانقلابيِّين الحوثيِّين- غاراتٍ جويَّةً انتَهَت بالتَّدميرِ الكُلِّيِّ لضريحِ حُسينٍ الحوثِيِّ، مؤسِّسِ الحركةِ والأبِ الرُّوحي للحوثيِّين في مِنطَقة مران بصَعْدةَ."},{"id":5975,"era":"c15","t":"وفاة الأمير سعود الفيصل وزير الخارجية السعودي .","s":"تُوفِّي وزيرُ الخارجيَّة السعوديُّ الأمير سعودٌ الفيصل -رحمه الله- عن عمرٍ نَاهَز الـ 75 عامًا، وذلك بعد 4 عُقُودٍ قضاها على رأسِ الدبلوماسيَّة السعودية؛ إذ شَغَل مَنصِبَ وزيرِ الخارجيةِ في المملكةِ العربية السعودية من 1975م إلى 2015م. وُلِد الأميرُ سعود الفيصل في مدينةِ الطَّائفِ في الثاني من يناير عامَ 1940م، وهو ابنُ المَلِك فيصلِ بنِ عبدِ العزيزِ آل سعود، وحصَلَ على شهادة البكالوريوس في الاقتص"},{"id":5976,"era":"c15","t":"وفاة الدكتور وهبة الزحيلي .","s":"تُوفِّي الدكتورُ وَهْبة مصطفى الزُّحيليُّ المفسِّرُ، الفقيهُ الأصوليُّ في دِمَشق بسوريَّةَ عن عمرٍ نَاهَز الـ 83 عامًا، قضاها -رحمه الله- في العِلْم والتعليم والبحث والتأليف، والتدريس في عددٍ من الجامعاتِ العربية، واشتُهِر بكتُبِه العلميَّةِ في مجالِ الفقهِ الإسلاميِّ وأصوله. وُلِد الدكتور الزُّحيلي في مدينة \"دير عطية\" من مُدن ريف دِمَشق عام 1932م، درَس الابتدائيَّةَ في بلدِ \"الميلاد\" في سوريَّةَ،"},{"id":5977,"era":"c15","t":"إعلان وفاة (الملا عمر) زعيم حركة طالبان الأفغانية .","s":"وُلِد المُلَّا عمر عامَ 1959م في قريةٍ من قرى قندهارَ، وهو من قبيلةِ \"بشتونية\"، عندما دخَلَتِ القوَّات السوفيتيَّة إلى أفغانستان كان عُمُره 19 عامًا، وكان يَدرُس في ولايةِ \"قندهارَ\"، تَرَك الدِّراسةَ والتَحَق بالمجاهدين في أفغانستان. شارَك في عدَّة معاركَ ضدَّ قوَّاتِ الاتحادِ السوفيتيِّ السابقِ في ولايتَي قندهار وأرزجانَ، اللَّتينِ شهِدتَا معاركَ ضاريةً، وكان يتنقَّلُ من مُنظَّمةٍ إلى أخرى، انضمّ"},{"id":5978,"era":"c15","t":"تحرير محافظة عدن من قبضة الحوثيين .","s":"أعلنتِ الحكومةُ اليمنيَّة المُعترَفُ بها دوليًّا \"تحريرَ محافظة عَدَن\". ويأتي الإعلانُ بعد أربعةِ أشهُرٍ من المعاركِ مع المقاتلين الحوثيِّين وأنصارِ الرئيسِ المخلوعِ علي عبد الله صالح. وكانتْ عَدَن مَعقِلَ حكومةِ الرئيس اليمنيِّ عبد ربه منصور هادي قَبْل سيطرةِ الحوثيِّين عليها. وكانت استعادتُها نقطةَ تحوُّلٍ في مَجرى الأحداثِ في اليمنِ."},{"id":5979,"era":"c15","t":"سقوط آلة رافعة في الحرم المكي .","s":"سقَطتْ آلةٌ رافعةٌ في الحَرَمِ المكِّيِّ تَابِعةٌ لمشروعِ تَوسِعة المسجِدِ الحرام في مكَّة المكرمة. وقد خلَّفْت هذه الحادثةُ أكثرَ من 108 قتلى، وحوالي 238 جريحًا، حسَبَ ما أَعلَن عنه الدِّفاعُ المدنيُّ السعوديُّ. وكان سببُها تَعرُّضَ مكة المكرمة لعواصفَ رمليَّةٍ ورياحٍ عاتية وأمطارٍ شديدةٍ. تَزامنتْ هذه الحادثةُ مع بداية موسِمِ الحجِّ في مكَّةَ المكرَّمةِ."},{"id":5980,"era":"c15","t":"حادثة التدافع في منى .","s":"حصَل تَدافُعٌ كبيرٌ في مَشْعَرِ مِنى يومَ العيد العاشر من ذي الحجةِ، أدَّى إلى وفاةِ عددٍ كبير من الحُجَّاج، بلغ 717 -حسَبَ إعلان الدِّفاع المَدَنيِّ السعوديِّ- وأُصيب 863 حاجًّا، وهو أعنفُ حادثٍ يَحدُث في الحَجِّ منذ التَّدافُعِ الأخيرِ الذي حدَثَ عامَ 1990م، وأدَّى إلى مَقتَل 1426 شخصًا."},{"id":5981,"era":"c15","t":"محاولة اغتيال رئيس المالديف في طريق عودته من الحج .","s":"نجا رئيسُ جمهوريةِ المالديف عبدُ الله يمين عبد القيوم من محاولةِ اغتيالٍ تَعرَّض لها في طريقِ عَودتِه من المملكةِ، بعد إتمامِه مَناسِكَ الحَجِّ. ولم يُصَبْ في الانفجار الذي وقَع بزَورقِه لدى اقترابِه من مالي عاصمةِ جُزُرِ المالديف الواقعةِ في المحيط الهنديِّ، وأُصيبت زوجتُه في الانفجارِ. وكان رئيسُ المالديف قد غادَر مطارَ الملكِ عبدِ العزيز بجُدَّةَ، ووصلتْ طائرتُه إلى المطار الدَّوليِّ الرئيسِ، و"},{"id":5982,"era":"c15","t":"روسيا تشرع في تنفيذ ضربات جوية في سوريَة .","s":"شنَّتْ روسيا ضَرَباتٍ جويَّةً على الأراضي السوريَّة، في أكبَرِ تَدخُّلٍ لها في الشَّرقِ الأوسطِ منذُ عشَراتِ السنين، وذلك بعد أنْ طلب الرئيسُ السوريُّ بشار الأسد دعمًا عسكريًّا من موسكو، ووافَق مجلسُ الاتحادِ الرُّوسيِّ على تفويضِ الرئيس فلاديمير بوتين استخدامَ القوَّاتِ المسلَّحةِ الروسيَّةِ خارجَ البلاد. جاءت هذه الضرَباتُ بعد الإعلانِ عن الدَّعمِ العَسكريِّ لنِظامِ الأسدِ من موسكو."},{"id":5983,"era":"c15","t":"تشييد قاعدة بحرية دائمة للقوات البحرية الملكية البريطانية في البحرين .","s":"وضَع وزيرُ الخارجيَّة البريطانيُّ: فيليب هاموند، ونظيرُه البحرينيُّ: خالدُ بن أحمد آل خليفة، حجَرَ الأساسِ لبناءِ قاعدةٍ بحريَّةٍ بريطانيَّةٍ في البحرين في اليومِ الثامنَ عشَرَ من هذا الشهرِ، وتُعدُّ هي الأولى لبريطانيا في منطقةِ الشَّرق الأوسطِ بشكلٍ دائمٍ منذُ انسحابِ بريطانيا من المنطقةِ عامَ 1971. وجاء بناءُ قاعدةِ \"إتش إم إس الجُفير\" في ميناءِ سلمان من أجلِ دَعمِ انتشارِ قوَّاتِ البَحريَّة ال"},{"id":5984,"era":"c15","t":"إعلان إنشاء تحالف إسلامي عسكري بقيادة السعودية .","s":"التحالفُ الإسلاميُّ العسكريُّ لمحاربة الإرهابِ هو حِلفٌ عسكريٌّ مكوَّنٌ من 40 دولةً إسلاميَّةً تقودُه المملكةُ العربيَّةُ السعوديَّة، من أصلِ سبعٍ وخمسين دولةً مِن الدُّولِ الأعضاءِ في «منظمة التعاونِ الإسلاميِّ»، يسعَى هذا التحالُفُ إلى مُحارَبةِ الإرهابِ بجميعِ أشكالِه ومظاهرِه، كما جاء في بيانِ إعلانِ التحالُفِ. ومن الدُّوَل العربيَّة التي انضمَّت إلى هذا التحالُفِ: الأردُنُّ، والإماراتُ، والبح"},{"id":5985,"era":"c15","t":"اغتيال زهران علوش قائد جيش الإسلام المعارض للنظام السوري .","s":"وُلِدَ محمد زهران علوش في مدينةِ دوما التابعةِ للغُوطةِ الشَّرقية في ريفِ دِمَشقَ عامَ 1971. وسلَكَ دَرْبَ العلمِ منذ الصِّغرِ اقتداءً بوالِدِه، فقرَأَ القرآنَ الكريمَ على والِدِه وعلى بعضِ شُيوخ بلَدِه، وتلقَّى التعليمَ الشَّرعيَّ عليهم، ثم التحَقَ بكليَّة الشَّريعة في جامعة دمشق وتخرَّج فيها. ثمَّ سافَرَ إلى المملكةِ العربيَّةِ السعوديَّة، وأكمل الدِّراسةَ في الجامعةِ الإسلاميَّة بالمدينة المنوّ"},{"id":5986,"era":"c15","t":"قتل نمر النمر عالم دين شيعي سعودي .","s":"وُلِدَ نمر باقر النمر في عامِ 1379هـ في مدينةِ العواميَّةِ في محافظةِ القطيفِ بشرقِ السُّعوديةِ، ودرَسَ في مَسقَطِ رأسِه العواميةِ، ثم هاجَرَ بعد ذلك إلى إيرانَ عامَ 1980م؛ إذ التحقَ بالحَوْزةِ العِلميَّة، وبقيَ هناك ما يقارِبُ عشرَ سنَواتٍ قَبْلَ أن يتَّجِهَ إلى سوريَّةَ. وهو عالِمُ دِينٍ شِيعيٍّ سُعوديٍّ أثارت خِطاباتُه التحريضية جدَلًا واسعًا، واعتُقِل عدَّةَ مَرَّاتٍ، ثم حَكَمَت عليه المحكمةُ "},{"id":5987,"era":"c15","t":"وفاة بطرس غالي .","s":"وُلِدَ بُطرس بطرس غالي لعائلةٍ مسيحيَّة قِبطيَّة ذاتِ شأنٍ في السياسةِ والمُجتمَعِ المِصريِّ، في 14 نوفمبر 1922، وهو حفيدُ بطرس نيروز غالي رئيسِ وُزَراءِ مصرَ في أوائلِ القرنِ العشرين، وهو أيضًا عَمُّ يوسف بطرس غالي الذي كان وزيرًا للماليَّةِ. بعد حُصولِه على إجازةِ الحقوقِ من جامعةِ القاهرةِ في عامِ 1946 حصَلَ على الدكتوراه من فرنسا في عامِ 1949، وعَمِل أستاذًا للقانونِ الدَّوليِّ والعَلاقاتِ الد"},{"id":5988,"era":"c15","t":"وفاة محمد حسنين هيكل .","s":"وُلِدَ الكاتبُ المصريُّ والصَّحفيُّ الشَّهير: محمد حسنين هيكل في 23 سبتمبر 1923، وتلقَّى تعليمَه بمراحِلِه المتَّصِلةِ في مصرَ، وكان اتِّجاهُه مبكِّرًا إلى دراسةِ ومُمارسةِ الصحافةِ، وفي عامِ 1943م التَحَق بجريدة «الإيجبشيان جازيت» مُحرِّرًا، ثمَّ عُيِّنَ عام 1945م مُحَرِّرًا بمجلةِ آخرِ ساعةٍ، وانتقلَ معها عندما انتقلت مِلْكيَّتُها إلى جريدةِ أخبار اليوم، أصبَحَ “حسنين هيكل” بعد ذلك مُراسِلًا متج"},{"id":5989,"era":"c15","t":"وفاة حسن الترابي زعيم حزب المؤتمر الشعبي السوداني .","s":"وُلِدَ حسن عبدالله دفع الله التُّرابي عامَ 1932 في مدينةِ كسلا شرقَ السُّودان، ودرَس الحقوقَ في جامعةِ الخُرطومِ منذُ عامِ 1951 حتى 1955، وحصَلَ على الماجستير مِن جامعةِ أكسفورد البريطانيَّةِ عامَ 1957، وحصَلَ على الدكتوراه من جامعةِ السُّوربون بباريسَ عامَ 1964. وهو يُتقِنُ أربعَ لُغاتٍ: العربية، والإنجليزية، والفرنسية، والألمانية، وتقلَّد الترابي بعد عَودتِه من فرنسا أمانةَ \"جَبهةِ الميثاقِ الإس"},{"id":5990,"era":"c15","t":"اغتيال الشيخ عبد العزيز يعقوب الكردي أحد مشايخ السُّنة ببلوشستان .","s":"قام جِهازُ المُخابراتِ الإيرانيُّ باغتيالِ الشيخِ عبدِ العزيزِ يعقوب الكُردي، أحَدِ رجالِ الدِّينِ السُّنَّة في إقليمِ بلوشستان الواقِعِ جنوبَ شَرقِ البلادِ على المُثَلَّثِ الحُدوديِّ مع أفغانستانَ وباكستانَ؛ إذ دخَل مُسلَّحان أحدَ جوامِعِ مدينةِ خاش، وأطلَقا نيرانَ أسلحَتِهما على الشَّيخِ في باحةِ الجامِعِ، وأردَيَاه قتيلًا بعد أدائِه صلاةَ الجُمُعةِ. وشَهِدَت مدينةُ خاش خروجَ تَظاهُرةٍ كبيرةٍ ضِ"},{"id":5991,"era":"c15","t":"صدور إعلان مصري رسمي عن تبعية جزيرتي \"تيران وصنافير\" للسعودية .","s":"أعلَنَت جمهوريَّةُ مصرَ العربيَّة أنَّ جَزيرتَي (تيران وصنافير) الواقعتَينِ في البحرِ الأحمَرِ؛ تابِعتانِ للأراضي السُّعوديةِ، فقد وقَّعَ الجانبانِ المِصريُّ والسُّعوديُّ اتفاقيَّةَ تعيينِ الحُدودِ البَحريةِ بين البلَدَينِ؛ من أجلِ الاستفادةِ مِن المنطقةِ الاقتصاديَّة الخالصةِ لكلٍّ منهما، بما توفِّرُه من ثَرَواتٍ وموارِدَ تعودُ بالمنفعةِ الاقتصاديَّةِ عليهما. ووقَّع الاتِّفاقيَّةَ عن الجانبِ السّ"},{"id":5992,"era":"c15","t":"وفاة إمام المسجد النبوي الشيخ محمد أيوب .","s":"وُلِدَ الشيخ محمَّد أيوب بن محمد يوسف بن سليمانَ عمر في مَكَّةَ المكرمةِ عامَ 1372ه، وهو من أصلٍ بورميٍّ، حفِظَ القرآنَ عام 1386 هـ في جامعِ بن لادن في حيِّ الحفاير بمكةَ، والتحقَ بالجامعةِ الإسلاميَّة، وتخرَّج  في كليَّةِ الشريعةِ عامَ 1396هـ، ثمَّ تَخَصَّصَ في التفسيرِ وعلومِ القرآن، فحصَلَ على درجةِ الماجستير من كليَّةِ القرآنِ، وحصَلَ على درجةِ الدكتوراه من الكليَّةِ نَفسِها عامَ 1408هـ، وإضاف"},{"id":5993,"era":"c15","t":"توقيع أول اتفاقية عسكرية لتمركز القوات التركية بين تركيا وقطر .","s":"وقَّعَت تركيا وقطر في العاصمةِ القَطَريَّة: الدَّوحةِ، أوَّلَ اتِّفاقيةٍ عَسكريَّةٍ بين البَلَدينِ، خلالَ زيارةِ رئيسِ الوزراءِ التُّركيِّ أحمد داود أوغلو لقطَرَ، وهي اتفاقيَّةٌ خاصَّةٌ بتمركُزِ قواتٍ تُركيَّة في قَطرَ، ويأتي إنشاءُ القاعدةِ التُّركيَّة في قطَرَ عبْرَ الاتفاقيَّة التي وُقِّعَت بين البلدَينِ عامَ 2014، وصادقَ عليها البرلمانُ التركيُّ، بخصوصِ التَّعاونِ الأمنيِّ بينهما. وتمنَحُ هذه "},{"id":5994,"era":"c15","t":"وفاة أختر محمد منصور زعيم حركة طالبان .","s":"وُلِد المُلا أختر محمد منصور شاه محمد في قريةِ بندي تيمور (مُقاطعةِ ميواند) بولايةِ قندهارَ جنوبَ أفغانستانَ لعائلةٍ مِن البشتون. كان عُضوًا بارزًا في قيادةِ حركةِ طالبان، وعُيِّنَ عامَ 2001م وزيرًا للطيرانِ المَدَني والنقلِ في حركةِ \"طالبان\". وأُعيدَ إلى أفغانستان في عامِ 2006م بعدَ اعتقالِه في باكستانَ. وكان حاكمَ طالبان في قندهار حتى مايو 2007م، وشَغِلَ رئاسةَ الشُّؤونِ العسكريَّةِ في طالبان حت"},{"id":5995,"era":"c15","t":"وفاة بطل الملاكمة العالمي محمد علي كلاي .","s":"وُلِدَ محمد علي كِلاي في 17 يناير 1942م في مدينةِ لويفيل بولايةِ كنتاكي، مِن عائلةٍ أمريكيَّةٍ سوداءَ مِن الطبَقةِ المتوسِّطةِ، واعتنَقَ الإسلامَ في عامِ 1964م، وكان اسمُه قبلَ إسلامِه (كاسيوس مارسيلوس كلاي جونيور) فغيَّرَه إلى مُحمَّد علي، واختار الانتماءَ في بادئِ أمرِه إلى جماعةِ أمَّةِ الإسلامِ، ولم يستمرَّ انضمامُه إليهم طويلًا؛ إذ كان يختلِفُ مع الكثيرِ مِن أفكارِهم، فاعتنَقَ الإسلامَ السُّن"},{"id":5996,"era":"c15","t":"قيام محاولة انقلابية في تركيا .","s":"قامتْ مجموعةٌ مِن ضُبَّاطِ القوَّاتِ المُسلَّحةِ التُّركيَّةِ بمحاولةٍ للانقلابِ على حكومةِ الرَّئيسِ رجب طيب أردوغان، وأعلن مدبِّرو الانقلابِ انقلابَهم، وإنشاءَ مجلسٍ يشكِّلُ الهيئةَ الحاكمةَ في البلدِ مِن خلالِ بيانٍ بثُّوه على القناةِ الرَّسميَّةِ التُّركيةِ بعد سيطرتِهم عليها. ولاقَت محاولةُ الانقلابِ رفضًا شَعبيًّا وسِياسيًّا مِن قياداتٍ حزبيَّةٍ وعسكريَّةٍ وبرلمانيَّة تركيَّةٍ، وممَّن رفضَ ا"},{"id":5997,"era":"c15","t":"انعقاد مؤتمر جروزني بالشيشان عن مصطلح أهل السنة والجماعة .","s":"في مدينةِ جروزني (عاصمةِ الشيشان) دشَّن الرئيسُ الشيشانيُّ: رمضان قاديروف مُؤتمَرًا عالميًّا تحتَ عُنوانِ \"من هم أهلُ السنَّةِ والجماعةِ؟\" في اليومِ الثاني والعشرين من هذا الشهرِ حضَرَه قُرابةُ 200 مشاركٍ من المَنسوبين إلى العِلمِ الشرعيِّ والدَّعوةِ الإسلاميَّةِ من مُختلِفِ الدُّوَلِ العربيةِ والإسلاميَّةِ، ومِن بينهم وفدٌ مصريٌّ مِن مشايخِ الأزهرِ برئاسةِ شيخِ الأزهرِ: الدكتور أحمد الطيب، وضمَّ "},{"id":5998,"era":"c15","t":"وفاة إسلام كريموف رئيس أوزبكستان سابقًا .","s":"وُلِدَ إسلام كريموف في مدينةِ سَمَرقند في أوزبكستانَ عامَ 1938، ودرَسَ الهندسةَ والاقتصادَ، وعَمِلَ مهندسًا في الطيرانِ مِن 1961 إلى 1966، ثمَّ تولَّى بعدها مناصِبَ حكوميَّةً، وفي عامِ 1989 تولَّى الحُكمَ في أوزباكستانَ، ومُدِّدَت ولايتُه إلى عامِ 2000 بموجِب استفتاءٍ، وفاز في انتخاباتٍ أُجرِيَت في تلك السَّنة دون مُنافِسٍ، وفي استفتاءِ عامِ 2002م مُدِّدَت فترةُ ولايتُه من 5 إلى 7 سنَواتٍ، وفاز بف"},{"id":5999,"era":"c15","t":"وفاة السفاح شمعون بيريز .","s":"وُلِد شمعون بيريز في بولندا، وهاجَرَت عائلتُه إلى فِلَسطينَ في عامِ 1934م (أيامَ الانتدابِ البريطانيِّ)، واستقَرَّت في مدينةِ تل أبيب التي أصبَحَت في تلك الأيامِ مَركزًا للمجتمَعِ اليهوديِّ. تعلَّمَ في مدرسةِ \"غيئولا\" في تلِّ أبيب، ثم واصلَ دراستَه في المدرسةِ الزراعيَّة \"بن شيمن\" قُربَ مدينةِ اللدِّ. وفي 1947م انضمَّ إلى قيادةِ الهجاناه، وكان مَسؤولًا عن شراءِ العَتادِ والموارِدِ البشريَّة. وفي ذ"},{"id":6000,"era":"c15","t":"وفاة الشيخ خليفة بن حمد آل ثاني أمير قطر سابقًا .","s":"هو الشيخُ خليفةُ بنُ حمد بن عبد الله بن قاسم بن محمد آل ثاني سادسُ أُمراءِ قطَرَ. وُلِدَ في 17 سبتمبر سنةَ 1932م، وكان قد تولَّى حُكمَ قطرَ بعدَ قِيامِه بانقلابٍ أبيضَ في عامِ 1971م استطاَع فيه أنْ يخلَعَ ابنَ عَمِّه أحمدَ بنَ عليِّ بنِ عبدِ اللهِ بنِ قاسمٍ، ويستوليَ على السُّلْطةِ، وتولَّى مقاليدَ الحكمِ. وفي بدايةِ عَهدِه أُقيمَت عَلاقات دُبلوماسية مع عددٍ من الدولِ على مُستوى السفراءِ لأولِ مرّ"},{"id":6001,"era":"c15","t":"وفاة الشيخ المحدث العلامة شعيب الأرناؤوط .","s":"هو الشيخُ شُعيبُ بنُ مُحرَّمٍ الألبانيُّ الأرناؤوطُ، وُلِدَ عامَ 1928 في العاصمةِ السوريةِ دمشقَ، وهو يَنحدِرُ من أسرةٍ ألبانيَّةِ الأصلِ، هاجرَتْ إلى دِمَشقَ سنةَ 1926، وكان والدُه من أهلِ العِلمِ. درَسَ اللغةَ العربيةَ في سِنٍّ مُبكِّرةٍ، وتعلَّم مبادئَ الإسلامِ، وحفِظَ أجزاءً كثيرةً من القرآنِ الكريمِ. تتلمَذَ في علومِ العربيةِ على كِبارِ أساتِذَتِها وعُلمائِها في دمشقَ آنَذاكَ، منهم الشيخُ صال"},{"id":6002,"era":"c15","t":"إقرار قانون يمنع بناء المساجد وإفشاء الإسلام في سلوفاكيا .","s":"وافَقَ البرلمانُ السلوفاكيُّ على مشروعِ قانونٍ يجعَلُ من الصعْبِ إعلانَ الإسلامِ دينًا رسميًّا في البلادِ، كما يُصعِّبُ من بناءِ المساجدِ، وأعدَّ مشروعَ القانونِ الحِزبُ القوميُّ السلوفاكيُّ الشريكُ في الحكومةِ الائتلافيةِ، ودعَمَتْه أحزابُ المعارضةِ؛ ما أدَّى إلى تمريرِه بأغلبيةِ الأصواتِ. ووَفقًا للقانونِ الجديدِ لا بدَّ أنْ يكونَ عَددُ أتباعِ دينٍ ما في سلوفاكيا 50 ألفًا على الأقلِّ؛ لتعترِفَ ا"},{"id":6003,"era":"c15","t":"وفاة الرئيس علي أكبر هاشمي رفسنجاني رئيس إيران الأسبق  .","s":"هو علي أكبر هاشمي رفسنجاني بهرماني، ولِدَ في 25 أغسطس 1934 بقَريةِ بهرمانَ في ضاحيةِ مدينةِ رفسنجان بمحافظةِ كرمانَ جنوبِ إيرانَ في عائلةٍ ثَريَّةٍ. وبعد أنْ تتلمَذَ في مدرسةٍ دينيةٍ مَحلِّيَّةٍ انتقل إلى الحَوْزةِ الدينيةِ بمدينةِ قُمَّ، وهو في سِنِّ المراهقةِ، فأكمَلَ دُروسَه الدينيةَ. وكان رفسنجاني من أبرَزِ المعارضينَ للشاهِ الموالين للخميني، كما لعِبَ دورًا ملموسًا ومُميَّزًا في ترسيخِ نظامِ "},{"id":6004,"era":"c15","t":"وفاة الشيخ حمزة بودشيشي شيخ الطريقة القادرية بالمغرب .","s":"هو الشيخُ حمزةُ القادِريُّ بنُ العبَّاسِ البُودْشِيشيِّ، شيخُ الطريقةِ القادِريَّةِ البُودْشِيشيَّةِ: أَكبَرِ جماعةٍ صوفيَّةٍ بالمَغرِبِ. ولِدَ حمزةُ القادِريُّ عامَ 1922 بقريةِ مَداغَ بإقليمِ بَرْكانَ على الحدودِ المَغربيَّةِ الجزائريَّةِ. حفِظ القرآنَ الكريمَ، وأنهى دِراستَه في السَّلكِ الأوَّلِ من التكوينِ العِلميِّ، ثم تلقَّى علومَ الشريعةِ في مَقَرِّ الزاويةِ بمَدَاغَ، ودرَسَ عُلومَ الفِقهِ و"},{"id":6005,"era":"c15","t":"وفاة الأمير محمد الفيصل بن عبد العزيز آل سعود .","s":"هو الأميرُ محمدُ ابنُ المَلِكِ فَيصلِ ابنِ الملِكِ عبدِ العزيزِ بنِ عبدِ الرحمنِ بنِ فَيصَلٍ آل سعودٍ، ولِدَ عامَ 1356هـ في مدينةِ الطائفِ، وهو الابنُ الثاني بعدَ الأميرِ الشاعرِ عَبد اللهِ الفَيصَلِ لنائبِ المَلِكِ على الحجازِ، الأميرِ فَيصَلِ بنِ عبدِ العزيزِ -آنَذاكَ-، والابنُ البِكرُ للأميرةِ عِفَّت الثَّنيان آل سعودٍ، التي قادت مشروعَ تعليمِ الفتاةِ السُّعوديةِ، وأنشأَتْ أولَ مَدارسَ للبناتِ،"},{"id":6006,"era":"c15","t":"عودة المملكة المغربية للاتحاد الإفريقي .","s":"وافَقَ قادةُ الاتحادِ الإفريقيِّ على عودةِ المَغرِبِ إلى المنظمةِ؛ ليصبِحَ العُضوَ الخامسَ والخمسين بعدَ 32 سنةً من انسحابِه من الاتحادِ، وكان المَغرِبُ غادَرَ الاتحادَ عامَ 1984 بعدما قَبِلَت أغلبيةُ الدولِ الأعضاءِ بمنظمةِ الوَحدةِ الإفريقيَّةِ عُضويَّةَ جَبهةِ البوليساريو التي تُنازعُ المَغرِبَ السيادةَ على إقليمِ الصَّحراءِ الغربيةِ، والتي ترى فيها الرِّباطُ جَبهةً انفصاليَّةً."},{"id":6007,"era":"c15","t":"وفاة الشيخ عمر عبد الرحمن .","s":"هو الشيخُ عُمَرُ عبد الرحمن: عالمٌ أزهريٌّ، وهو الزعيمُ الرُّوحيُّ للجماعةِ الإسلاميةِ في مصرَ. ولِدَ بمدينةِ الجمالية بالدقهليةِ عامَ 1938، فَقَدَ بَصَرَه بعدَ عشَرةِ أشهُرٍ من ولادتِه، حصَلَ على الثانويةِ الأزهريةِ عامَ 1960، ثم التحَقَ بكليَّةِ أصولِ الدينِ بالقاهرةِ، ودَرَسَ فيها حتى تخرَّجَ فيها سنةَ 1965 بتقديرِ امتيازٍ مع مرتَبةِ الشرَفِ، ثم حصَلَ على شهادةِ الماجستير، وعَمِلَ مُعيدًا بالكل"},{"id":6008,"era":"c15","t":"دولة الاحتلال الإسرائيلي تقر قانون منع أذان الفجر .","s":"أقرَّ كنيست دولةِ الاحتلالِ الإسرائيليِّ قانونَ مَنعِ الأذانِ بمُكَبِّراتِ الصوتِ في فِلَسطينَ من الساعةِ 11 ليلًا إلى الساعةِ 7 صباحًا!! وهذا يعني مَنعَ أذانِ الفَجرِ بمكبِّراتِ الصوتِ، وعَدَّ الفلسطينيُّون مَنْعَ الأذانِ في مُكبِّراتِ الصوتِ بمنزلةِ إعلانِ حربٍ على الإسلامِ والمسلمين وعلى الفلسطينيين أهلِ البِلادِ الأصليِّين، وتَصدَّوا لهذا القرارِ ولم يَلتَزِموا به."},{"id":6009,"era":"c15","t":"تركيا تنتقل في نظام حكمها من النظام البرلماني إلى النظام الرئاسي .","s":"أجرَتِ الجمهوريةُ التُّركيَّةُ تعديلاتٍ على الدستورِ التركيِّ للمرةِ السابعةِ منذُ تأسيسِ الجمهوريةِ. وتُمَهِّدُ تلك التعديلاتُ الدستوريةُ إلى تحويلِ النظامِ الحُكوميِّ من برلمانيٍّ إلى رئاسيٍّ تَنفيذيٍّ، ومن ثَمَّ إلغاءُ منصِبِ رئيسِ الحكومةِ، والسماحُ لرئيسِ الدولةِ بتَعيينِ الوُزراءِ، وجَعلُ الإجراءاتِ الحُكوميةِ تحتَ سُلطَتِه، وإعلانُ حالةِ الطوارئِ. وأنْ يُنتخَب الرئيسُ لولايتَينِ رئاسيَّتَين"},{"id":6010,"era":"c15","t":"منظمة \"اليونسكو\" تتبنى قرارًا يعد القدس مدينة محتلة .","s":"تبنَّتْ مُنظَّمةُ الأمَمِ المتحدةِ للتربيةِ والعلمِ والثقافةِ \"اليونسكو\" قرارًا يَعُدُّ القُدسَ مَدينةً مُحتلَّةً، ويؤكِّدُ فِلَسطينيةَ البَلدةِ القديمةِ في المدينةِ المُقدَّسةِ. ويُؤكِّدُ مشروعُ القرارِ أنَّ \"إسرائيلَ\" تحتلُّ القدسَ، وليس لها في البَلدةِ القديمةِ أيُّ حقٍّ، ويشمَلُ أيضًا الاعترافَ بأنَّ المقابرَ في مدينةِ الخليلِ وقَبرِ راحيلَ في بيتِ لَحمٍ مقابرُ إسلاميةٌ."},{"id":6011,"era":"c15","t":"وفاة الشيخ محمد محمد الراوي .","s":"هو الشيخُ محمد محمد الراوي عضوُ مَجمَعِ البحوثِ الإسلاميةِ، وعضوُ هيئةِ كِبارِ العلماءِ بالأزهرِ. وُلِدَ في قريةِ \"ريفا\" محافظةَ أسيوطَ غُرَّةَ فبرايرَ 1928م. حَفِظَ القرآنَ الكريمَ في سنٍّ مُبكِّرةٍ في القريةِ، حيثُ كانت المعاهدُ الأزهريةُ لا تَقبَلُ الطالبَ في السنةِ الأولى إلا بحِفظِ القرآنِ الكريمِ كُلِّه. وبعد الانتهاءِ من الدراسةِ في معهدِ أسيوطَ تقدَّم إلى كُليَّةِ أصولِ الدينِ بالقاهرةِ، و"},{"id":6012,"era":"c15","t":"تعيين سمو الأمير محمد بن سلمان وليًّا للعهد .","s":"أصدرَ الملكُ سلمانُ بنُ عبدِ العزيزِ أمرًا ملكيًّا بتعيينِ نَجلِه محمدِ بنِ سَلمانَ وليًّا للعهدِ، ليحُلَّ بذلك مَحَلَّ ابنِ عمِّه الأميرِ محمد بن نايف، الذي أُعفِيَ أيضًا من وزارةِ الداخليَّةِ. وبويِعَ وليُّ العهدِ الأميرُ محمد بن سلمانَ بقصرِ الصفا في مكةَ المكرمةِ."},{"id":6013,"era":"c15","t":"اتفاقية نقل سيادة تيران وصنافير من مصر إلى المملكة العربية السعودية .","s":"صدَّقَ الرئيسُ المصريُّ عبدُ الفتاحِ السيسي على اتفاقيةِ تيرانَ وصنافيرَ التي أقرَّها مجلِسُ النُّوَّابِ، والتي تنُصُّ على نقلِ السيادةِ على الجزيرتَينِ الواقعتَينِ في البحرِ الأحمرِ إلى المملكةِ العربيةِ السعوديةِ. وتتحكَّمُ جزيرتا تيرانَ وصنافيرَ غيرِ المَأهولتَينِ في مَدخَلِ خليجِ تيرانَ، وهو المَمَرُّ المِلاحيُّ الرئيسُ المُؤدِّي إلى ميناءِ إيلاتَ الإسرائيليِّ على خليجِ العقَبةِ. وتتمركَزُ الق"},{"id":6014,"era":"c15","t":"وفاة الشيخ الدكتور محمد أديب صالح .","s":"ولِدَ الشيخُ الدكتورُ محمد أديب الصالح في مدينةِ قطنا -جنوبَ غَربِ دِمَشقَ- في العامِ 1926 م، وعاش يتيمًا، ولكنَّ والدتَه عوَّضَتْه عن عنايةِ الوالدِ بانقطاعِها لرِعايتِه، والاهتمامِ بشَأنِه، وقد بدأ تعليمَه في إحدى مدارسِ قطنا الابتدائيةِ، ومنها انتقل إلى دِمَشقَ، حيثُ أحرَزَ شهادةَ الكفاءةِ العامَّةِ ثم شَهادةَ الكليةِ الشرعيةِ، التي كانتْ تُعَدُّ مَعهدًا عِلميًّا رفيعَ المستوى، ثم حصَلَ على الث"},{"id":6015,"era":"c15","t":"وفاة شيخ الحديث محمد يونس الجونفوري السهارنفوري .","s":"هو الشيخُ الإمامُ المحقِّقُ محمد يونس بنُ شَبير أحمد بن شير علي الجونفوري السَّهارنفوريُّ، شيخُ الحديثِ، وُلد في قريةِ كُورَيْني قُربَ جونفور بالهندِ، 15 رجب سنةَ 1355، وتوفِّيت أمُّه وهو ابنُ خَمْسٍ، فربَّتْه جَدَّتُه لأمِّه، وكانت من الصالحاتِ، فتربَّى في بيئةٍ مُتديِّنةٍ، ثم التحَقَ بالكتاتيبِ وأخَذَ فيها القراءةَ والكتابةَ والمبادئَ، وبعدها انتقَلَ إلى مدرسةِ ضياءِ العلومِ بماني كلان قُربَ قري"},{"id":6016,"era":"c15","t":"دولة الاحتلال الإسرائيلي تمنع أداء صلاة الجمعة بالمسجد الأقصى .","s":"منَعَ جيشُ الاحتلالِ الإسرائيليِّ المُصلِّين من الدُّخولِ إلى باحات المَسجِدِ الأقصى لتأديةِ صَلاةِ الجمُعةِ، وتُعدُّ هذه هي المرةَ الأولى التي منَعَ فيها المُحتلُّ اليَهوديُّ المُصلِّين المسلمين من تَأديةِ صَلاةِ الجُمُعةِ في المسجدِ الأقصى منذ الاحتلالِ الإسرائيليِّ للقُدسِ عامَ 1967. وأعلَنَ جيشُ المحتلِّ الإسرائيليِّ أنَّ المسجدَ الأقصى والبلدةَ القديمةَ منطقةٌ عَسكريَّةٌ، واعتَدَوا على حُرَّا"},{"id":6017,"era":"c15","t":"حسن روحاني يتولى رئاسة إيران للمرة الثانية. .","s":"تولَّى حسن روحاني -وهو رجلُ دينٍ شِيعيٍّ برُتبةِ حُجَّةِ الإسلامِ- رئاسةَ جمهوريةِ إيرانَ للمرةِ الثانيةِ وكانتِ المرةُ الأولى في أغسطس 2013، وُلِدَ روحاني في 12 نوفمبر 1948 في منطقةِ سرخه بمحافظةِ سمنانَ \"شرقِ طهرانَ\"، وكان والدُه تاجرًا. وهو حائزٌ على شهادةِ الدكتوراه من جامعةِ غلاسكو في اسكتلندا. وكان روحاني إلى جانبِ الخميني عندما نُفِيَ إلى فرنسا قبلَ 1979، وكان روحاني نائبًا بين عامَي 1980 و"},{"id":6018,"era":"c15","t":"وفاة العالم الهندي الشيخ المحدث ظهير الدين الرحماني المباركفوري .","s":"هو الشيخُ المُحدِّثُ المعمَّر ظَهيرُ الدِّينِ بنُ عبدِ السبحان محمد بَهادُر الأثَريُّ الرَّحماني المُبارَكْفوريُّ، وُلد سنةَ 1920م الموافق لسنةِ 1338 تقريبًا، في حُسين آباد قُربَ مُبارَكْفُورَ بالهندِ. وبدأ دِراستَه الأولى في بَلدتِه، ثم انتقَلَ إلى جامعةِ \"فَيض عام\" في مدينةِ \"مَو\" القريبةِ، وانتقَلَ بعدها إلى دارِ العلومِ في ديوبند، ثم انتقَلَ إلى دارِ الحديثِ الرحمانيَّةِ الشهيرةِ في دِهْلي -دل"},{"id":6019,"era":"c15","t":"وفاة الدكتور بيرم رجب رئيس وزراء كوسوفو  .","s":"هو الدكتور الطبيبُ بيرم رجب رئيسُ وزراءِ كوسوفو. وُلِد في 3 يونيو 1954 في كوسوفسكا ميتروفيتشا، كوسوفو يوغوسلافيا، وأصبحَ أوَّلَ رئيسٍ للوزراءِ في كوسوفو بعد الحربِ. وهو عضوٌ في حزبِ كوسوفو الديمقراطيِّ ثاني أكبرِ حزبٍ سياسيٍّ في كوسوفو. تخرَّج في جامعةِ بريشتينا، وأتمَّ دِراساتِه العليا في جامعةِ زغرب سنةَ 1985. قضى مُعظمَ حَياتِه المِهنيَّةِ كجرَّاحٍ ناجحٍ. وخلالَ حربِ كوسوفو عامَ 1999 انضمَّ إلى"},{"id":6020,"era":"c15","t":"وفاة السلطان عبد الحليم معظم ملك ماليزيا  .","s":"هو السلطانُ عبدُ الحليمِ معظم، ملكُ ماليزيا. وُلد في 28 نوفمبر 1927 وهو سلطانُ وِلايةِ قدح شمالَ البلادِ، أدَّى اليمينَ الدُّستوريَّةَ لتولِّي منصِبِ ملكِ ماليزيا الرابعَ عشرَ لمدةِ خمسِ سنَواتٍ، في مراسمَ تقليديَّةٍ أقيمت بالقصرِ الوطنيِّ في العاصمةِ كوالالمبور في 13 ديسمبر 2011. وهذه هي المرةُ الثانيةُ التي يتولَّى فيها عبدُ الحَليمِ هذا المنصِبَ؛ فقد كانت المرةُ الأولى عامَ 1970 واستمرَّت حتى 1"},{"id":6021,"era":"c15","t":"حليمة يعقوب أول امرأة مسلمة تتولى رئاسة دولة سنغافورة .","s":"وُلِدَت حليمةُ يعقوب يومَ 23 أغسطس 1954 في سنغافورةَ، والدُها كان حارسًا، وهو مُسلِمٌ من أصلٍ هنديٍّ، وعانَت حليمةُ الفَقرَ في طُفولتِها؛ إذ تُوفِّيَ والدُها وهي في سنِّ الثامنةِ، واضطُرَّتْ في سنِّ العاشرةِ من عُمرِها إلى أنْ تُساعِدَ والدتَها العاملةَ في دُكَّانٍ لبيعِ الأطعمةِ، وفي عملياتِ التنظيفِ والغسيلِ، وفي توزيعِ الأكلِ على الزبائنِ! وبرَغمِ ظُروفِها الصعبةِ واصلَت دِراستَها حتى تخرَّجَت "},{"id":6022,"era":"c15","t":"حركة حماس تحل حكومتها في غزة. .","s":"أعلنت حَركةُ حماسَ أنها حلَّت حُكومَتَها في قطاعِ غَزَّةَ التي كان اسمُها اللجنةَ الإداريَّةَ، ودعَتِ الحركةُ حُكومةَ الوِفاقِ إلى القُدومِ إلى قطاعِ غَزَّةَ لممارسةِ مُهمَّاتِها والقيامِ بواجباتِها فورًا، والموافقةِ على إجراءِ الانتخاباتِ العامَّةِ، وينُصُّ اتفاقُ القاهرةِ الذي توصَّلَت إليه «حماس» و«فتح» وبقيةُ الفصائلِ الفِلَسطينيَّةِ برعايةٍ مِصريةٍ، على تشكيلِ حكومةِ وَحدةٍ وطنيَّةٍ، وإجراءِ "},{"id":6023,"era":"c15","t":"قرار ملكي بالسماح للمرأة السعودية بقيادة السيارة. .","s":"أصدَرَ خادمُ الحرَمَينِ الشريفَينِ الملكُ سلمانُ بنُ عبدِ العزيزِ قرارًا بالسماحِ للمرأةِ السعوديةِ بقيادةِ السيارةِ، على أنْ يكونَ التنفيذُ ابتداءً من يومِ 10 شوال 1439ه."},{"id":6024,"era":"c15","t":"المصالحة بين حماس والسلطة الفلسطينية .","s":"وقَّعَ وَفدا حركتَي (فتح) و(حماس) اتفاقَ مُصالَحةٍ في القاهرةِ برعايةٍ مصريةٍ، وينُصُّ اتِّفاقُ المصالحةِ على تمكينِ حكومةِ الوفاقِ؛ لتقومَ بكافَّةِ مَهامِّها في غزَّةَ، كما اتَّفقَ الطرفانِ على تَسلُّمِ الحكومةِ الفلسطينيةِ كافةَ معابرِ غَزَّةَ، على أنْ تُنقَلَ إدارةُ معبرِ رَفَح إلى حرسِ الرئاسةِ الفلسطينيةِ. وقد رحَّبَ الرئيسُ الفلسطينيُّ محمود عباس بإنجازِ اتِّفاقِ المصالحةِ الفلسطينيةِ، وأكَّ"},{"id":6025,"era":"c15","t":"مقتل الرئيس اليمني السابق علي عبد الله صالح .","s":"علي عبد الله صالح عفاش من مواليدِ 29 ربيع الآخِر 1366هـ/ 21 مارس 1947، كان الرئيسَ السادسَ للجمهوريةِ العربيةِ اليمنيَّةِ، وتُعَدُّ مُدَّةُ حُكمِه أطولَ مُدَّةِ حُكمٍ لرئيسٍ في اليمنِ منذُ العامِ 1978م حتى تنازلَ عن الحُكمِ في 27 فبراير 2012م، وكان يحمِلُ رتبةَ المشيرِ العسكريَّةَ. وصَلَ علي عبد الله صالح إلى رأسِ السُّلطةِ في البلادِ عَقِبَ مقتلِ الرئيسِ أحمد الغشمي بفترةٍ قصيرةٍ، بعد أنْ تنحَّى "},{"id":6026,"era":"c15","t":"اعتراف الولايات المتحدة الأمريكية بالقدس عاصمةً لدولة إسرائيل المحتلة .","s":"اعترفَت إدارةُ الرئيسِ دونالد ترامب رسميًّا بالقدسِ عاصمةً لإسرائيلَ، وأضافَ ترامب أنَّ وزارةَ الخارجيةِ الأمريكيةَ ستبدأ عمليةَ بناءِ سفارةٍ أمريكيةٍ جديدةٍ في القدسِ.رفَضَ البيانُ الخِتاميُّ للقمَّةِ العربيَّةِ التاسعُ والعِشرون قرارَ الإدارةِ الأمريكيةِ بالاعترافِ بالقدسِ عاصمةً للاحتلالِ الإسرائيليِّ ونَقْلِ السفارةِ إليها، عادًّا ذلك خَرقًا وتدميرًا لعمليةِ السلامِ وللاتفاقياتِ جَميعِها؛ سواء"},{"id":6027,"era":"c15","t":"وفاة الشيخ المُحقق مُحمَّد مُصطفى الأعظمي .","s":"الشيخُ المُحقِّق مُحمَّد مُصطفى الأعظمي عالمٌ مُسلمٌ هنديٌّ، تخصَّصَ في دراسةِ الحديثِ النَّبويِّ. اشتُهِرَ بتدقيقِه وتمحيصِه لبعضِ مؤلَّفاتِ المستشرقين عن الإسلامِ والحضارةِ الإسلاميةِ. وُلِد محمد مصطفى الأعظمي في مدينةِ منو بالهندِ سنةَ 1350هـ الموافقةَ لسنةِ 1932م. أخرجَه والدُه من المدرسةِ الثانويةِ الإنجليزيَّةِ، وألحَقَه بالمدرسةِ العربيةِ؛ إذ كان والدُه معاديًا للاحتلالِ البريطانيِّ للهندِ،"},{"id":6028,"era":"c15","t":"فوز مهاتير محمد في الانتخابات الرئاسية في ماليزيا .","s":"مهاتير بن محمد من مواليد 10 يوليو 1925م. سبَقَ أنْ تولَّى رئاسةَ الوزراءِ فكان رابعَ رئيسِ وُزراءَ لماليزيا في المدَّةِ من 1981 إلى 2003، وتُعَدُّ أطولَ فترةٍ لرئيسِ وزراءَ في ماليزيا، وكذلك من أطولِ فتَراتِ الحكمِ في آسيا، امتدَّ نشاطُ مهاتير السياسيُّ لِما يقرُبُ من 40 عامًا، منذُ انتخابِه عضوًا في البرلمانِ الاتحاديِّ الماليزيِّ عامَ 1964، حتى استقالتِه من منصبِ رئيسِ الوزراءِ في عامِ 2003. كان"},{"id":6029,"era":"c15","t":"وفاة الشيخ أبوبكر الجزائري .","s":"أبو بَكرٍ جابرُ بنُ موسى بنِ عبدِ القادرِ بنِ جابرٍ المعروفُ بـ (أبو بكرٍ الجَزائريُّ). ولِدَ في قريةِ ليوة القريبةِ من طولقةَ، التي تقعُ اليومَ في ولايةِ بسكرةَ جنوب بلادِ الجزائرِ عامَ 1921م، وفي بلدتِه نشأَ وتلقَّى علومَه الأوليَّةَ، وبدأ بحِفظِ القرآنِ الكريمِ وبعضِ المتونِ في اللغةِ والفقهِ المالكيِّ، ثم انتقَلَ إلى مدينةِ بسكرةَ، ودرَس على مشايخِها جملةً من العلومِ النقليَّةِ والعقليَّةِ الت"},{"id":6030,"era":"c15","t":"وفاة جلال الدين حقاني المولوي .","s":"المَوْلويُّ جلالُ الدينِ حقَّاني ولدَ عامَ 1939م، وهو قائدٌ سياسيٌّ وجِهاديٌّ سُنِّيٌّ، معروفٌ بقيادةِ قتالٍ واسعٍ ضدَّ العدوانِ السوفييتيِّ على أفغانستانَ في ثمانينيَّاتِ القرنِ العشرين الميلاديِّ، وقد كان قبلَ موتِه من قادةِ حركةِ طالبان الأفغانيةِ، وسبَقَ أنْ عيَّنَته الحركةُ وزيرًا للشؤونِ القَبَليَّةِ في حكومةِ إمارةِ أفغانستانَ الإسلاميةِ. ولقد دُعِي من طرَفِ حامد كرزاي لتولِّي منصبِ رئيسِ و"},{"id":6031,"era":"c15","t":"الأردن تنهي اتِّفاقيةِ تأْجيرِ أراضي الباقورةِ والغمرِ لإسرائيل .","s":"أنْهى العاهِلُ الأُردنِّيُّ الملِكُ عبدُ اللهِ الثَّاني، أحدَ بُنودِ اتِّفاقيةِ السلامِ \"وادي عربةَ\"، وذلِك بعدَمِ تجديدِ اتِّفاقيةِ تأجيرِ أراضي الباقورةِ والغمّرِ لإِسرائيلَ بعدَ احتِجاجاتٍ ومَسيراتٍ تطالِبُ بعدَمِ تجديدِ الاتِّفاقيةِ، والباقورةُ والغمرُ مِنطقَتيْنِ أُردُنيَّتيْنِ حُدوديَّتيْنِ مع دولةِ الاحتلالِ.وبحسَبِ المعاهدةِ الموقَّعةِ عامَ 1994م، وضعَ الأُردنُّ مِنطقتَيِ الباقورةِ والغمرِ"},{"id":6032,"era":"c15","t":"وفاةُ الأميرِ طلالِ بنِ عبدِ العزيزِ آلِ سعودٍ الأخِ الشَّقيقِ للملِكِ سلْمانَ .","s":"وُلِدَ الأميرُ طلالُ بنُ عبدِ العزيزِ آلُ سعودٍ عامَ 1350هـ /1931م وهو الابنُ الثامنُ من أبناءِ الملكِ عبدِ العزيزِ بنِ عبدِ الرحمنِ آلِ سعودٍ. عُيِّن وزيرًا للمواصلاتِ من 1372 هـ - 1374 هـ ثم وزيرًا للماليَّةِ من 1380هـ - 1381هـ ثم سفيرًا في فرنسا. وهو والدُ رجلِ الأعمالِ الشَّهيرِ المليارديرِ الوليدِ بنِ طلالٍ، وكان للأميرِ طلالٍ مواقفُ وآراءٌ جريئةٌ تسبَّبت في تركِه للْحياةِ السياسيَّةِ وانتقال"},{"id":6033,"era":"c15","t":"وفاةُ صبغةِ اللهِ مُجدِّدي أولِ رئيسٍ لأفغانِسْتانَ بعدَ الانسِحابِ السوفييتيِّ .","s":"صِبغةُ اللهِ مُجدِّدي من مواليدِ 1926م، كان من أبرَزِ قادةِ المجاهِدينَ الأفغانِ ضدَّ الاحتِلالِ السوفيتيِّ، وكان يرأَسُ جَبهةَ التَّحريرِ الوَطنيِّ الأفغانيَّةَ، وهو أوَّلُ رئيسٍ للبلادِ بعدَ انسِحابِ الجيشِ السُّوفيتيِّ بعدَ سقوطِ حُكومةِ محمد نجيب الله في أبريلَ 1992م، وشغَلَ منصِبَ رئيسٍ لمجلِسِ اللويا جيرغا (الجمعية الكبرى) سنة 2003م الذي وافقَ على دُستورٍ جديدٍ في أفغانِستانَ. ولم يدُمْ طويل"},{"id":6034,"era":"c15","t":"اعتِرافُ الولاياتِ المتَّحِدةِ بسِيادةِ إسرائيلَ على الجولانِ .","s":"أعلنَ الرئيسُ الأمريكيُّ دونالد ترامب عنِ اعتِرافِ الولاياتِ المتَّحدةِ بسِيادةِ إسرائيلَ على الجولانِ، وأنَّ هضْبةَ الجولانِ السُّوريةَ المحتلَّةَ جزءٌ من دولةِ إسرائيلَ، وذلك بعدَ زيارةِ رئيسِ الوزراءِ الإسرائيليِّ بِنْيامين نتنياهو إلى واشنطن.ولا تزالُ إسرائيلُ تبسُطُ سيطرَتَها على ثُلَثيْ هضْبةِ الجولانِ السوريَّةِ الواقعةِ جنوبَ غَربِ البلادِ ضِمنَ محافظةِ القُنيْطرةِ، وتَعتبِرُ الأممُ المتَّ"},{"id":6035,"era":"c15","t":"فَوزُ الرئيسِ النَّيْجيريِّ مُحمَّدِ بُخاري بِولايةٍ رئاسيَّةٍ ثانيةٍ .","s":"فازَ الرئيسُ محمد بخاري بولايةِ رئاسيَّةٍ ثانيةٍ وتستمِرُّ ولايتُه حتى عام 2023م بعدَما فازَ على مُنافسِه نائبِ الرئيسِ السَّابقِ عتيق أبو بكرٍ.وُلِدَ محمد بخاري عام 1942 في قريةٍ صغيرةٍ تُدعى \"دورا\" لأُسرةٍ مُسلمةٍ، تقعُ في ولايةِ كاتسينا شمالَ نيجيريا قُربَ الحدودِ مع تشادَ والتَحقَ بالجيشِ وعمرُه لم يتجاوزْ 19 سنةً، ثم درسَ الفنونَ العسكريَّةَ في بريطانيا قبلَ أن يعودَ إلى بلادِه ليتقلَّدَ مناص"},{"id":6036,"era":"c15","t":"هُجُومٌ إرهابيٌّ بِسلاحٍ ناريٍّ على مسجدِ النورِ بنيوزيلندا .","s":"تعرَّض مسجدُ النورِ بنيوزيلندا لإطلاقِ نارٍ من رجُلٍ أُستراليِّ يبلُغُ (28 عامًا) باستِخدامِ سلاحٍ آليٍّ، ضدَّ المصلِّين أثْناءَ إقامةِ صلاةِ الجمعةِ، وقد وثَّقَ القاتلُ الحادثَ بالفيديو ونشرَه على حِساباتِه بمواقعِ التواصُلِ الاجتماعيِّ مُباشرةً.كما وقعَ حادثٌ آخَرُ في مسجدٍ آخرَ في نفسِ المِنطقةِ، وكانت حصيلةُ الاعتداءَينِ المُسلَّحيْنِ على المسجِدَينِ 49 قتيلًا على الأقلِّ، و48 جريحًا، حسْبَ ما"},{"id":6037,"era":"c15","t":"حريقُ مسجدِ كاليفورنيا .","s":"اندلعَ حريقٌ في مسجِدِ المركزِ الإسلاميِّ بكاليفورنيا في مقاطعةِ إسكونديدو شمالَيْ سان دييغو، عثَرتْ الشُّرطةُ عندَ مدخلِ المسجدِ على رسوماتٍ غرافيتي مُعاديةٍ للمسلمينَ تُشيرُ إلى حادثةِ إطلاقِ النارِ الذي حصلَ داخِلَ مَسجدَيِ النورِ ومركزِ لينود الإسلاميِّ في مدينةِ كرايستشرش في نيوزلندا، التي نتجَ عنهما العديدُ منَ الإصاباتِ والوَفَياتِ، وهذا ما قادَ الشُّرطةَ إلى اعتِبارِ الحريقِ بمثابةِ هُجومٍ"},{"id":6038,"era":"c15","t":"استقالةُ الرئيسِ الجزائريِّ عبدِ العزيزِ بوتفليقةَ .","s":"قدَّم الرئيس الجزائري عبد العزيز بوتفليقة استقالته إلى رئيس المجلس الدستوري وتم إعلان إجراءات شغور منصب الرئيس ومن ثم التحضير لفترة انتقالية تنتهي بانتخاب رئيس جديديُعدُّ بوتفليقةُ الرئيسَ العاشرَ للجزائرِ منذُ التكوينِ، والرئيسَ الثامِنَ منذُ الاستقلالِ. وُلِدَ بمدينةِ وَجْدةَ المغربيَّةِ وهو مِن أصولٍ أمازيغيَّةٍ. التحَقَ بعدَ نهايةِ دراستِه الثانويَّةِ بصفوفِ جيشِ التَّحريرِ الوطنيِّ الجزائريِّ"},{"id":6039,"era":"c15","t":"تولِّي عبدِ القادرِ بنِ صالحٍ منصِبَ رئاسةِ الجزائرِ مؤقتًا .","s":"فِي 9 أبريل 2019م أعلنَ البرلمانُ الجزائريُّ عبدَ القادرِ بنَ صالحٍ رئيسًا للدولةِ لمدَّةِ 90 يومًا، بعدَ أن أعلنَ رسميًّا الشُّغورَ النهائيَّ لمنصِبِ رئيسِ الجمهوريَّةِ إثْرَ استِقالةِ عبدِ العزيزِ بوتفليقة.وُلِدَ عبدُ القادرِ بنُ صالحٍ يومَ 24 نوفمبر 1941م بفلاوسن بولاية تِلِمْسانَ.عمِلَ دبلوماسيًّا في السِّفارةِ الجزائريَّةِ بمصرَ. وبينَ سنواتِ 1970م - 1974م عُيِّنَ مديرًا للمركزِ الجزائريِّ لل"},{"id":6040,"era":"c15","t":"عَزلُ الرَّئيسِ السُّودانيِّ عُمَرَ البَشيرِ عن الحُكمِ .","s":"أعلنَ الجيشُ السودانيُّ عَزلَ الرئيسِ عُمرَ البشيرِ واعتِقالَه في مكانٍ آمِنٍ، بعدَ احتِجاجاتٍ واسِعةٍ في الشارعِ السودانيِّ، وتمَّ تولِّي المجلِسِ العَسكريِّ برئاسةِ وزيرِ الدِّفاعِ أحمدَ عوض بنِ عوفٍ مقاليدَ السُّلطةِ في 11 أبريلَ 2019م، مُزيحًا البشيرَ عن رأسِ السلْطةِ.ويُعدُّ عُمر حسن أحمد البشيرِ من مواليدِ 1 يناير 1944م وهوَ رئيسُ جُمهوريَّةِ السودانِ منذُ (1989م – 2019م)، ورئيسُ حِزبِ المؤت"},{"id":6041,"era":"c15","t":"وَفاةُ عباسي مدني مؤسِّسِ \"الجَبهةِ الإسلاميَّةِ للإنقاذِ\" الجزائريَّةِ .","s":"تُوفِّي عباسي مدني في مُستشفى بالدَّوحةِ عن عمرٍ ناهزَ 88 سنةً. نُقِلَ جُثمانُ مدني إلى الجزائرِ العاصِمةِ ليُدفنَ في مقبرةِ سيدي أمحمد بوقبرين ببلكور.وهو من مواليدِ 28 فبرايرَ 1931م ومؤسِّس الجبهةِ الإسلاميَّةِ للإنقاذِ، بدأَ عباسي مدني ممارسةَ العملِ السياسيِّ منذُ عامِ 1948م في الحركةِ الوطنيَّةِ الجزائريَّةِ في عهدِ الاستِعمارِ حيثُ انخرَطَ في خلايا حزبِ الشَّعبِ الجزائريِّ ثم حركةِ انتصارِ ال"},{"id":6042,"era":"c15","t":"وفاةُ الرئيسِ المصريِّ السابقِ محمد مرسي\n  .","s":"تُوفي الرئيسُ السابقُ محمد مرسي خِلالَ جلْسةِ محاكمتِه وهو من مواليدِ أغسطس عامَ 1951م، واسمُه الكاملُ محمد محمد مرسي عيسى العيَّاط، تولَّى رئاسةَ مصرَ في أوَّلِ انتِخاباتٍ رئاسيَّةٍ عقِبَ ثورةِ يناير منَ العامِ 2011م، ليكونَ الرئيسَ الخامِسَ لمصرَ، كان يعمَلُ أستاذًا بكليةِ الهندسةِ جامعةِ الزقازيقِ، وبدأتْ فَترتُه الرئاسيَّةُ مع إعلانِ فوزِه في الانتِخاباتِ الرئاسيَّةِ التي أُجرِيَت في 24 يونيو "},{"id":6043,"era":"c15","t":"وفاةُ الرئيسِ التونِسيِّ الباجيِّ قايد السبسي .","s":"من مواليدِ 29 نوفمبر 1926م؛ سياسيٌّ ومحامٍ تونِسيٌّ، وكان الرئيسَ الخامسَ في تاريخِ الجمهوريَّةِ التونِسيَّةِ للفَترةِ من 31 ديسمبرَ 2014م إلى 25 يوليو 2019. ترأَّسَ حزبَ نداء تونِسَ. تقلَّد العديدَ من المناصِبِ الوزاريَّةِ في عهدِ الحبيبِ بورقيبةَ، ثم عادَ للساحةِ السياسيَّةِ بعدَ الثورةِ التونِسيَّةِ. ترشَّحَ للانتِخاباتِ الرئاسيَّةِ في 2014م أمامَ الرئيسِ المنتهيةِ ولايتُه المنصف المرزوقي، وتسل"},{"id":6044,"era":"c15","t":"وفاةُ الأميرِ بندرَ بنِ عبدِ العزيزِ آلِ سعود .","s":"هو من مواليدِ (1341 هـ / 1923)، ويُعدُّ الأميرُ بَندرُ الابنَ العاشرَ من أبناءِ الملكِ عبدِ العزيزِ آلِ سعودٍ الذكورِ، وترتيبُه بين إخوتِه العاشرُ بعدَ الملكِ فهدٍ مُباشرةً.لم يتقلَّدْ أيَّ منصِبٍ رسميٍّ في الدولةِ منذُ تأسيسِها، ويُمثِّلُه في هيئةِ البَيعةِ ابنُه الأميرُ فيصل أميرُ مِنطقةِ الرياضِ. كما يشغَلُ أبناءُ الأميرِ بَندرَ مناصِبَ هامَّةً في الدولةِ، من بينِهمُ الأميرُ خالدُ بنُ بَندرَ مُ"},{"id":6045,"era":"c15","t":"إلغاءُ الهندِ الحكمَ الذاتيَّ الدُّستوريَّ لجامو وكَشْميرَ .","s":"أعلَنتِ الحكومةُ الهنديَّةُ إلغاءَ وضعِ الحُكمِ الذاتيِّ الدُّستوريِّ لكَشميرَ بمرسومٍ رئاسيٍّ، ووضعَتِ الزُّعماءَ السياسيِّينَ تحتَ الإقامةِ الجبريَّةِ.واعتَبرتْ باكِستانَ ذلك خُطوةً \"غيرَ شرعيَّةٍ\"، وأعلنَت رفضَها لهذا القرارِ مما أدَّى إلى توتُّرِ العلاقاتِ بين البلَدينِ، وتتَّهِمُ الهندَ جارتَها بدَعمِ الجماعاتِ المسلَّحةِ في وادي سريناغار الشماليِّ، وهو ما تنفيهِ باكستانُ."},{"id":6046,"era":"c15","t":"المجلِسُ الانتقاليُّ الجنوبيُّ يُسيطِرُ على مدينةِ عدَن .","s":"سيطرَ المجلسُ الانتقاليُّ الجنوبيُّ على عدنَ بقوَّةِ السلاحِ، وسقطَ عددٌ منَ القتْلى في مواجهةٍ بينَه وبينَ الحكومةِ المُعترَفِ بها دوليًّا والمدعومةِ من تحالُفِ دعمِ الشرعيَّةِ في اليمنِ، ودعَتِ السعوديَّةُ لاجتِماعٍ طارئٍ بمدينةِ الرياضِ لإنهاءِ هذه الأزمةِ.صدرَ منه بيانٌ جاء فيه: رفضُ التطوُّراتِ في عدن، ودعوةُ كافَّةِ الأطرافِ والمكوِّناتِ لتحكيمِ العقلِ وتغليبِ المصلحةِ الوطنيَّةِ والعملِ مع "},{"id":6047,"era":"c15","t":"وفاة الشيخ محمد المختار الشِّنْقيطي بالمدينة المنورة .","s":"وُلِد في بلادِ شِنْقِيطَ بمُوريتانيا عام 1361 هـ، ونشَأ في بيتِ عِلمٍ، حيث كان والدُه عالمًا أُصوليًّا وعضوًا في هَيئة كبارِ العلماءِ بالسُّعوديةِ، وهو الشَّيخُ محمَّد الأمينُ الشِّنْقيطيُّ صاحب كتاب (أضْواء البَيان). وكانت وفاتُه رحمه الله في المدينة المنوَّرة عن عُمرٍ يُناهِزُ 77 عامًا، وصُلِّي عليه العصر في المسجد النَّبويِّ، وتمَّ دفْنُه في مقبرةِ البَقيع."},{"id":6048,"era":"c15","t":"وفاةُ الرئيسِ التونِسيِّ الأسبقِ زَينِ العابدينَ بنِ عليٍّ .","s":"يُعدُّ زَينُ العابِدينَ بنُ عليٍّ الرئيسَ الثانيَ لتونِسَ منذُ استِقلالِها عن فرنسا عامَ 1956م بعدَ الحبيبِ بورقيبةَ، وقد عُيِّن رئيسًا للوُزراءِ في أكتوبرَ 1987م ثم تولَّى الرئاسةَ بعدَها بشهرٍ في نوفَمبرَ 1987م في انقلابٍ؛ حيثُ أعلنَ أنَ الرئيسَ بورقيبةَ عاجزٌ عن تولِّي الرئاسةِ. وقد أُعيدَ انتِخابُه في كلِّ الانتِخاباتِ الرئاسيَّةِ التي جرتْ، وآخِرُها كان في 25 أكتوبرَ 2009م. وُلِدَ بنُ عليٍّ ف"},{"id":6049,"era":"c15","t":"استهداف مَعمَلي شَركة أرامكو في بقيق وخريص بطائرات مسيَّرة (دراون) .","s":"استُهدِف مَعملانِ مِن مَعاملِ النِّفط في السُّعوديةِ لشركةِ أرامكو السُّعودية بطائراتٍ بدون طيَّارٍ، أحدُهما في مُحافظةِ بقيق، والآخَرُ في هجرة خريص، مما أدَّى إلى اشتعالِ حَرائقَ في المَعمَلينِ وخسائرَ كبيرةٍ جدًّا، وكان وراءَ هذه العمليةِ جُمهوريَّةُ إيرانَ وأتباعُها مِن الميشيلياتِ الحُوثيَّةِ."},{"id":6050,"era":"c15","t":"مَقْتَل (أبو بكر البَغدادي) زعيم تنظيم الدَّولة الإسلامية (داعش).\n  .","s":"إإبراهيم عوَّاد إبراهيم علِي البَدْري السَّامرائي، وشُهرتُه أبو بكرٍ البغدادي، وُلِد عام 1391هـ/1971م، كان قائدَ تنظيمِ القاعدةِ في العراقِ، والتي كانت تُسمَّى بـ\"دَولة العراقِ الإسلاميَّة\"، ثم قام بإعلان الوَحْدةِ بين الجماعاتِ في العراق والشامِ تحْت اسمِ \"تَنظيم الدَّولة الإسلامية في العِراق والشامِ\" الذي اشتهَرَ بـاسم (داعش)، ثم أعلَنَ التَّنظيمُ قيامَ \"الدَّولة الإسلامية\"، ونُصِّب أبو بكرٍ الب"},{"id":6051,"era":"c15","t":"فَوز قَيْس سِعَيِّد في الانتخابات الرِّئاسية التُّونسية .","s":"وُلِدَ قَيسُ بنُ المنصِف بنِ محمد سِعَيِّد عام 1377هـ / 1958م، وأصبَح في هذا العامِ رئيسَ الجُمهورية التُّونسيةِ السابعَ. وهو سِياسيٌّ وأستاذٌ جامعيٌّ، مُختصٌّ في القانونِ الدُّستوري."},{"id":6052,"era":"c15","t":"عقْد اتِّفاق بين الحكومة اليمنية والمجلِس الانتقالي الجَنوبي .","s":"عُقِد اتفاقٌ بيْن الحكومةِ اليَمنية -ويَرأَسُها الرَّئيسُ عبْدُ ربِّه مَنصور هادي- والمجلسِ الانتقاليِّ الجنوبيِّ -ويَرأسُه عَيْدروس الزَّبيدي-، وذلك في العاصمةِ السُّعودية الرِّياضِ، برِعاية الممْلَكة العربيةِ السُّعوديةِ والإماراتِ العربية المتَّحِدة. مثَّل الحكومةَ اليمنية في تَوقيع الاتفاقِ سالمٌ الخَنْبَشيُّ، ومثَّل المجلسَ الانتقاليَّ ناصرٌ الخُبَّجيُّ."},{"id":6053,"era":"c15","t":"جائحة فيروس كورونا (كوفيد19) .","s":"جائحةُ فَيروس كُورونا، أو جائحةُ (كوفيد-19)؛ هي جائحةٌ عالَميةٌ سبَّبها فَيروس (كورونا 2) المرتبِطُ بالمُتلازمة التَّنفُّسيةِ الحادَّة الشَّديدةِ (سارس-كوف-2). تفشَّى المرضُ للمرةِ الأُولى في مَدينة وُوهان الصِّينيةِ في أوائل شَهْر دِيسمبر عامَ 2019م/ رَبيعٍ الآخَرِ 1441هـ، وانتشَرَ في نهايةِ المطافِ إلى بَقيَّة الصِّينِ، وفي 30 يناير 2020م / 5 جُمادى الأولى 1441 أعلَنَت منظَّمةُ الصِّحةِ العالميّ"},{"id":6054,"era":"c15","t":"وفاة الأمير مِتْعِب بن عبدالعزيز آل سعود .","s":"وُلِد الأميرُ مِتْعِب بنِ عبد العزيز آل سُعودٍ في مدينة الرِّياض عامَ 1350 هـ، وهو الابنُ السابعَ عشَرَ مِن أبناء الملك عبْد العزيز الذُّكور. والدتُه الأميرةُ شهيدة، وهي والدةُ الأميرَينِ: منصور، ومِشْعل، درَس في «معهد الأنجال»، ثم درَس البكالوريوس في جامعةِ كاليفورنيا بأمريكا في العُلوم السِّياسية، وتخرَّج فيها عامَ 1372هـ، وكان وزيرًا سابقًا للشُّؤون البَلَدية والقرويَّةِ.تُوفِّي رحمه الله بعْد "},{"id":6055,"era":"c15","t":"تبادُل السُّفراء بين أمريكا والسودان بعد انقطاع عِقْدَينِ من الزمن .","s":"أعلَنَت الولاياتُ المتَّحِدةُ الأمريكيةُ وجُمهوريةُ السودانِ تَبادُلَ السُّفراء بيْنهما بعد انقطاعٍ استمرَّ لأكثرَ مِن عِقدَينِ من الزمَنِ. وكان ذلك دعْمًا أمريكيًّا للحُكومة الانتقاليةِ في السُّودان، حيث وعَدَت بإزالةِ اسم السُّودانِ مِن الدُّول الراعية للإرهابِ ورفْعِ العُقوباتِ الاقتصادية كافَّةً عنها."},{"id":6056,"era":"c15","t":"وَفاة سلطان عُمان قابوس بن سعيد  .","s":"قابوسُ بنُ سَعيد بن تَيمور بن فَيصل بن تُرْكي بن سَعيد بن سُلطان بن أحمد بن سَعيد آل بُو سَعيدي، وُلِد عام 1359هـ / 1940م، السُّلطانُ التاسعُ لسَلْطنة عُمَان، ورئيسُ مَجلس الوُزراء، ووَزير الدِّفاع، والخارجية، والماليَّة، وحاكمُ البَنك المركزيِّ، والقائدُ الأعلى للقوَّات المسلَّحة، والحاكمُ الثاني عشَرَ لأسرةِ آل بو سَعيد. يُعَدُّ حكْمُه أطولَ مدَّةٍ بيْن الحكَّام العرَبِ والثالثَ في العالَمِ حتَّ"},{"id":6057,"era":"c15","t":"تولية هيثم بن طارق آل سعيد سلطانًا لعمان خلفًا لقابوس .","s":"وُلِد هَيثم بن طارق بن تَيمور آل سَعيدٍ عام 1375هـ / 1955 م، وهو السُّلطانُ العاشرُ لسَلْطنة عُمَان خلَفًا لابن عمِّه قابوس بنِ سعيدٍ وطبْقًا لوصيَّتِه. وكان قبْلها وزيرًا للتُّراث والثَّقافةِ ورئيسَ اللَّجنة الرَّئيسية للرُّؤية المستقبَلية \"عُمَان 2040\"، كما شغَل العديدَ مِن المناصب في وزارةِ الخارجية، منها الأمينُ العامُّ، ووَكيلُ الوزارة للشُّؤون السِّياسية، ووَزير مُفوَّض. وعمِلَ في بعْض الأحي"},{"id":6058,"era":"c15","t":"وَفاة الشيخ محمد بن الأمين بُوخُبْزة .","s":"هو محمَّد بنُ الأمين بنِ عبد الله بن أحمدَ الحَسَني الإدريسيِّ العَمْراني، كُنْيتُه (بُوخُبْزة)، وُلِد بتِطْوانَ في المغربِ عام1351هـ / 1932م، وكانت تحْت الاحتلالِ الأسبانيِّ.أتمَّ حِفظَ القرآنِ، ثم أتمَّ حِفظَ بعضِ المتون العِلمية، كالآجُروميةِ، والمرشِد المُعِين على الضَّروري من عُلوم الدِّين، ومُختصَر خَليلٍ في الفِقه المالكي، ثم الْتحَقَ بالمعهد الدِّيني بالجامع الكبيرِ، ومكَث فيه نحْوَ عامينِ"},{"id":6059,"era":"c15","t":"وفاة الرئيس المصري الأسبق محمد حسني مبارك  .","s":"وُلِد محمد حسني مُبارَك عامَ 1347هـ/ 1928م، بمُحافظةِ المُنوفية، أصبَح الرئيسَ الرابع لجُمهورية مِصر العربيةِ خلَفًا لمحمَّد أنور السَّادات عامَ 1401هـ / 1981م. تنحَّى عن الحكْم عامَ 1432هـ / 2011م تحْت ضُغوطٍ شَعبية وسلَّم السُّلطة للمجلِس الأعلى للقوَّات المسلَّحة. حصَل على التعليمِ العسْكريِّ في مِصرَ، وتخرَّج من الكُلِّية الجويَّة عامَ 1370هـ/1950م، وترقَّى في المناصبِ العسكريةِ حتى وصَل إلى م"},{"id":6060,"era":"c15","t":"وفاة المفكِّر محمد عمارة .","s":"محمَّد عمارةَ مُصطفى عمارة، وُلِد عام 1350هـ / 1931م، وكان عضوًا في مَجمَعِ البحوثِ الإسلامية بالأزهَر، وعضْوَ هَيئةِ كِبار عُلماء الأزهر، وعضْوَ المجلِسِ الأعلى للشُّؤون الإسلاميةِ بمِصر، ورَئيسَ تَحرير مجلَّة الأزهرِ.كان ماركسيًّا، ثم هَداهُ الله فأصبَح مِن الكُتَّاب الإسلاميِّينَ، ولكنَّه كان يَخلِطُ في كِتاباتِه بين الفِكر الاعتزاليِّ العَقْلاني والمنهجِ السَّلَفي، وله انتقاداتٌ جيِّدة على الع"},{"id":6061,"era":"c15","t":"مَقْتَل قاسم سُليماني قائد فَيلق القُدس الإيراني .","s":"اللِّواء قاسم سُليماني مِن مَواليدِ عامِ 1377هـ / 1957م، كان قائدًا لفَيلَق القُدسِ التابعِ للحرَسِ الثَّوري الإيراني، والمسؤولَ عن العمَليات العسْكريةِ السِّرِّية خارجَ الحدود الإقليميَّةِ لإيرانَ. وهو مِن قُدامى المحاربينَ في الحربِ العراقيةِ الإيرانيةِ في الثَّمانينيَّات، رُقِّيت الرُّتبةُ العسكرية لقاسم سُليماني مِن عقيدٍ إلى لِواء بواسطةِ قائدِ الثَّورة الإيرانية علِي خامنئي. كان سُليماني نشِ"},{"id":6062,"era":"c15","t":"تعليق أداء الصلاة في المسجد الحرام والمسجد النَّبوي بسَبب فيروس كورونا .","s":"علَّقت الحُكومةُ السُّعودية الصَّلواتِ في المسجد الحرام والمسجدِ النَّبوي؛ وذلك ضِمنَ الإجراءات الاحترازيةِ والتَّدابير الوِقائية لمنْعِ انتشار فَيروس كورونا المستجِدِّ."},{"id":6063,"era":"c15","t":"وفاة القارئ الشيخ محمد محمود الطبلاوي .","s":"وُلِد القارئ الشيخُ محمد محمود الطَّبْلاوي عامَ 1353هـ / 1934م، في محافظةِ الجيزةِ، وأصْلُه مِن المنوفيةِ، أصبَحَ من مَشاهيرِ القُراءِ الإذاعيينَ قبْل أن يَبلُغ الخامسةَ عشْرةَ مِن عُمرِه، واحتلَّ بيْنهم مكانةً مَرموقةً.تُوفِّي عن عُمرٍ ناهَزَ 86 عامًا بعْد معاناةٍ مع المرضِ."},{"id":6064,"era":"c15","t":"إقامة صلاة الجمعة في آيا صوفيا بتُركيا لأول مرة منذ أكثر من 80 عامًا .","s":"آيا صُوفيَا،  أو جامع آيا صُوفيا؛ هو مَبنًى تاريخيٌّ للعبادة، يقَعُ على الضفَّة الأوروبيَّة في مَدينة إسطنبولَ، أُنشِئ ليكون كاتدرائيةً للبَطريركية المسيحية الأرْثوذكسيَّةِ، ثمَّ تحوَّل إلى كاتدرائيةٍ رُومانية كاثُوليكيةٍ، وبعْد فتْحِ القُسطنطينيةِ تحوَّل إلى مَسجدٍ، وبعْد قِيام الجُمهوريةِ التُّركية تحوَّل إلى مُتْحفٍ عَلْماني، وأخيرًا أُعلِن عن إعادته مَسجدًا بعْد إصدار حُكم المحْكَمة الإدارية ا"},{"id":6065,"era":"c15","t":"تنظيم شعيرة الحج وفق احترازات صحية صارمة .","s":"بسَببِ انتشار وَباء كورونا قرَّرت الحكومةُ السُّعودية اقتصارَ الحجِّ على عددٍ محدود جدًّا من السُّعوديين والمقيمينَ داخلَ السُّعودية، على أن تكونَ نِسبةُ غيرِ السُّعوديين من المقيمينَ داخلَ المملكة هي 70% مِن إجمالي الحُجاجِ، وتكون نِسبةُ السُّعوديين 30 % فقطْ، على أنْ يَقتصِر حَجُّ المواطنينَ السُّعوديين على الممارِسين الصحِّيِّين ورِجال الأمن. مع أخْذ كافَّة الاحترازات والمعاييرِ الصِّحِّية، وتم"},{"id":6066,"era":"c15","t":"انهيار سدِّ بوط على النيل الأزرق في السودان. .","s":"سَدُّ \"بوط\" يقَعُ على مَجرى النِّيل الأزرق، قَريب مِن مَدينة بوط في وِلاية النِّيل الأزرق جَنوبَ شَرقَي السُّودان.انهار السَّدُّ ودمَّر مئاتِ المنازل، وشرَّد آلافَ النَّاس، وكان السدُّ يُخزِّن 5 ملايين مِترِ مكعَّب من المياه القادمةِ مِن وُدْيان جِبال «الإنقسنا». وتَسبَّبت الأمطار الغزيرةُ التي شهِدتها المنطقةُ بانهيارِه."},{"id":6067,"era":"c15","t":"انفجار هائل في بيروت يُسقِط عشَرات القتلى ومئات الجرحى .","s":"وقَع انفجارٌ هائل في مَرفَأ بَيروت؛ ممَّا جعَل وَسائلَ الإعلام تُطلِق عليه مُصطلَح \"بيروتشيما\" تَشبيهًا له بما جَرى لمدينة هِيروشيما جرَّاء الانفجارِ النَّووي عامَ 1945 م، وقد وقَع الانفجارُ الضَّخم على مَرحلَتَين نتجَت عنه سحابةٌ دُخانيةٌ ضخْمةٌ على شاكلةِ سَحابة الفِطْر، ترافَقت مع مَوجةٍ صادمة هزَّت العاصمةَ بَيروت، مما أدَّى إلى أضرارٍ كبيرة في المَرْفَأ وتَهشيم الواجهاتِ الزُّجاجية للمباني وا"},{"id":6068,"era":"c15","t":"تطْبيع العَلاقات بين الاحتلال الإسرائيلي والإمارات العربية المتَّحِدة .","s":"أعلَنَت الإمارات العربية المتَّحِدة وإسرائيلُ المحتلة الاتفاقَ على التَّطبيعِ الكاملِ بيْنهما برعايةٍ أمريكيَّة، وبتَوقيعِ هذا الاتفاق أصبَحَت الإماراتُ العربية المتَّحِدة ثالثَ دولةٍ عربية -بعْد مِصرَ عامَ 1399هـ/ 1979م، والأردن عام 1415هـ/ 1994م- تُوقِّعُ اتفاقيةَ سلامٍ وتَطبيعٍ مع إسرائيل، والدَّولةَ الخليجيةَ الأُولى التي تقومُ بذلك."},{"id":6069,"era":"c15","t":"الإمارات والبحرين توقعا معاهدة سلام وتطبيع مع دولة الاحتلال إسرائيل .","s":"وقَّعَت الإماراتُ العربيَّةُ المتحدةُ ومملكة البحرين اتفاقيَّةَ سلامٍ وتطبيعٍ مع دولة الاحتلالِ إسرائيلَ، وكان ذلك في احتفالٍ في البيتِ الأبيضِ. وبتوقيعه أصبحت الإماراتُ أوَّلَ دولةٍ خليجيَّةٍ، وثالثَ دولةٍ عربيَّةٍ بعد مِصرَ والأردن، توقِّعُ اتفاقيَّةَ سلامٍ وتطبيعٍ مع إسرائيلَ. والبحرين ثاني دولةٍ خليجيَّةٍ ورابعُ دولةٍ عربيَّةٍ."},{"id":6070,"era":"c15","t":"وفاة الشَّيخ أحمد شفيع ببنجلاديش .","s":"وُلِدَ رحمه اللهُ عام 1334هـ الموافق 1916م في رانجونية بشيتاغونغ، وتلقَّى تعليمَه الابتدائيَّ والمتوسِّطَ في نفسِ المدرسةِ، ثم سافر إلى دارِ العلومِ ديوبند لتحصيل العلومِ العُليا، وصاحَبَ هناك كثيرًا من كِبارِ عُلَماءِ الهندِ، كان من كبارِ عُلَماءِ بنغلاديش وأقدَمِهم، وآخِرَ من توفِّيَ من تلاميذِ الشَّيخ حسين أحمد المدني، وكان مُسنِدَ الحديثِ النبويِّ في الدِّيارِ البنغاليَّةِ، كان رئيسَ جماعة حفظ"},{"id":6071,"era":"c15","t":"وفاة الدكتور نور الدّين عتر .","s":"وُلِدَ الدكتور نور الدين عتر في حلب عام 1356هـ الموافق 1937م، درس في الثانوية الشرعيَّة (الخسروية)، وحصل على الشَّهادة الثَّانوية الشَّرعيَّة عام ١٣٧٣هـ الموافق 1954م، ثم التحق بجامعةِ الأزهرِ في مِصرَ وتخرَّج فيها.في عام ١٣٨٤هـ الموافق 1964م حاز على الشَّهادة العالِمية الدُّكتوراه، من شُعبة التَّفسيرِ والحديثِ، وكانت أطروحته: «طريقة الترمذيِّ في جامِعِه، والموازنة بينه وبين الصَّحيحينِ»، استفاد م"},{"id":6072,"era":"c15","t":"الشَّيخ نواف الأحمد الجابر الصباح أميرا لدولة الكويت .","s":"وُلِدَ الشَّيخ نوَّاف الأحمد في وسط مدينة الكويت، في 15 ربيع الآخر 1356هـ الموافق 25 يونيو 1937م، ونشأ في قصر دسمان، وهو بيتُ الحُكمِ في الكويت إبَّان إمارةِ والده أحمد الجابر الصباح ما بين عامي ١٣٣٩هـ - ١٣٦٩هـ الموافق 1921م-1950م، وتلقَّى تعليمَه في مدارس الكويت المختلفة، حيث درس في مدارسِ حمادة وشرق والنقرة، ثم في المدرسةِ الشَّرقيَّةِ، إضافةً إلى تحصيله في المدرسة المباركية، وهي أوَّلُ مدرسةٍ ف"},{"id":6073,"era":"c15","t":"وفاة الشَّيخ عبد الرحمن عبد الخالق  .","s":"وُلد الشَّيخُ عبدُ الرحمنِ بنُ عبدِ الخالِقِ في محافظةِ المنوفيَّةِ بمصرَ بتاريخ 23 رمضان 1358هـ الموافق 5 نوفمبر 1939م. درس الشَّيخُ المرحلةَ الجامعيَّةَ في كليَّةِ الشريعةِ بالجامعةِ الإسلاميَّةِ في المدينةِ المنوَّرةِ، وتتلمذ على يدِ الشَّيخِ عبدِ العزيزِ بنِ باز، والشَّيخِ محمَّد ناصر الدين الألباني والشَّيخِ عبد الرَّزَّاق عفيفي، وغيرهم من العلماء، انتقل إلى الكويت عام ١٣٨٥هـ الموافق 1965م، ح"},{"id":6074,"era":"c15","t":"وفاة أمير الكويت الشَّيخ صباح الأحمد الجابر الصباح  .","s":"وُلِد الشَّيخُ صباح الأحمد الجابر الصباح عام ١٣٤٨هـ الموافق 1929م، وهو أمير دولة الكويت الخامس عشر، في عام ١٤٢٤هـ الموافق 2003م، صدر تعيينه رئيسًا لمجلس الوزراء في البلادِ. وكان قد شَغِل قبل ذلك عِدَّة مناصِبَ؛ منها: وزارة الخارجية، ووَزارةُ الإعلامِ بالوكالة، ورئاسةُ دائرةِ الشؤونِ الاجتماعيَّةِ والعمل ودائرة المطبوعات والنَّشــر، وعُضوًا في الهيئة التنظيميَّةِ للمجلِسِ الأعلى، وعضوًا في مجلِسِ ا"},{"id":6075,"era":"c15","t":"تعيين الشَّيخ مشعل الأحمد الصباح وليا للعهد في الكويت. .","s":"وُلِدَ الشَّيخُ مِشعَل الأحمد الجابر المبارك الصباح عام ١٣٥٩هـ الموافق 1940م في الكويت، وهو الابنُ السَّابعُ للشَّيخِ أحمد الجابر الصباح.درس في كلية لندن للشُّرطةِ في بريطانيا وتخرج فيها عام ١٣٨٠هـ الموافق 1960م، ويُعَدُّ من أهمِّ رجالِ الأمنِ بالكويت.بعد وفاةِ الأميرِ الشَّيخ صباح الأحمد الجابر الصباح وتولِّي الشَّيخ نوَّاف الأحمد الجابر الصباح مُسند الإمارة بصِفَتِه وليًّا للعهد أصدر أمرًا أميري"},{"id":6076,"era":"c15","t":"وفاة الدكتور عبد الستار أبو غدة .","s":"وُلِدَ الدكتورُ عبد السَّتَّار أبو غُدَّة عام ١٣٥٩هـ الموافق 1940م بحَلَب. حصل على ليسانس في الشريعة عام ١٣٨٤هـ الموافق 1964م من جامعة دمشق، كما حصل على ليسانس في الحقوقِ عام ١٣٨٥هـ الموافق 1965م من نفس الجامعةِ، وحصل على ماجستير في الشريعةِ عام ١٣٨٦هـ الموافق 1966م، ثمَّ ماجستير في علومِ الحديثِ عام ١٣٨٧هـ الموافق 1967م، ثمَّ على الدكتوراه في الشَّريعةِ في مجالِ (الفقهِ المقارِن) عام ١٣٩٥هـ الموا"},{"id":6077,"era":"c15","t":"مقتل الوزير الحوثي حسن زيد في صنعاء .","s":"وُلِدَ حسن محمد زيد عام ١٣٧٣هـ الموافق 1954م في مدينة صنعاء القديمة.حصل على الماجستير في علومِ التربيةِ كما حصل على دراساتٍ عليا في بريطانيا بليفربول.عُيِّن \"وزير دولة\" في حكومةِ خالد بحاح بتاريخ 14 محرم ١٤٣٦هـ الموافق 7 نوفمبر 2014م، وهو من مؤسِّسِي حزب الحق [الشِّيعي]، وكان أمينَه العامَّ، ومن مؤسِّسي تكتُّل أحزاب اللِّقاء المشترك، وتولى رئاسته طَوالَ فترة الحربِ السَّادسةِ على الحوثيِّينَ في صَ"},{"id":6078,"era":"c15","t":"وفاة صائب عريقات .","s":"وُلد عام ١٣٧٥هـ الموافق 1955م في بلدة أبو ديس بمحافظة القُدسِ عندما كانت تحتَ الإدارة الأردنيَّةِ.تلقَّى تعليمَه المدرسيَّ في مدارس مدينة أريحا، وحصل على شهادةِ الدِّراسةِ الثانويَّةِ العامَّة عام ١٣٩٢هـ الموافق 1972م، وحصل على درجة البكالوريوس في عام ١٣٩٧هـ الموافق 1977م، وعلى درجة الماجستير في عام ١٣٩٨هـ الموافق 1978م من جامعة سان فرانسيسكو الحكومية بالولاياتِ المتَّحدةِ في تخصُّصِ العُلومِ السي"},{"id":6079,"era":"c15","t":"وفاة رئيس الوزراء البحريني خليفة بن سلمان آل خليفة .","s":"وُلِدَ الأميرُ خليفة بن سلمان آل خليفة عام ١٣٥٤هـ الموافق 1935م. وابتُعِثَ للدراسةِ في بريطانيا على فتراتٍ مُتقَطِّعةٍ حتى عام 1959. تدرَّج في المناصِبِ وُصولًا إلى رئيس الوزراء في عَهدِ أخيه الأكبر الشَّيخ عيسى بن سلمان آل خليفة (عاهل البحرين ١٣٨١هـ - ١٤٢٠هـ - الموافق 1961م- 1999م)، وهو المنصِبُ الذي ظلَّ يحتَفِظُ به في عهد الملك حمد بن عيسى آل خليفة، حتى وافَتْه المنيَّةُ. وكان عَمَّ مَلِكِ البح"},{"id":6080,"era":"c15","t":"وفاة الشَّيخ علي الحلبي  .","s":"وُلِدَ الشَّيخُ علي الحلبي في مدينةِ الزرقاء في المملكةِ الأردنيَّة الهاشميَّة يوم الأحد بتاريخ 29 جمادى الثانية من عام 1380هـ الموافق 18 ديسمبر 1960م، وكان والِدُه قد هاجر مع جَدِّه إلى الأردن من يافا في فلسطين سنة 1368هـ الموافق عام 1948م من آثارِ حربِ اليهودِ.التقى بالشَّيخِ محمَّد ناصر الدين الألباني في أواخِرِ عام 1977م في عمان. ولازمه ودرَسَ على يَدَيه حتى توفَّاه اللهُ.أسَّس مجلَّةَ الأصالة"},{"id":6081,"era":"c15","t":"وفاة الرئيس الموريتاني الأسبق سيدي محمد ولد الشَّيخ عبد الله .","s":"وُلِد سيِّدي محمد ولد الشَّيخ عبد الله سنة ١٣٥٧هـ الموافق 1938م في ألاك (عاصمة ولاية لبراكنة)، ودرس الابتدائيَّةَ والإعداديَّةَ فيها، وحصل على الثانويَّةِ من العاصِمةِ السنغالية دكار، وحصل على دبلوم الدِّراساتِ المعمَّقة في الاقتصادِ مِن فرنسا سنة ١٣٨٨هـ الموافق 1968م.تولَّى بعض المناصِبِ؛ أبرزها: مديرُ التخطيطِ، ثمَّ وزيرُ الدَّولةِ المكَلَّف بالاقتصادِ في حكومةِ الرئيسِ المختارِ ولد داداه، ثم عَ"},{"id":6082,"era":"c15","t":"وفاة الصادق المهدي زعيم حزب الأمة السوداني  .","s":"وُلِدَ الصَّادِقُ المهدي عام ١٣٥٤هـ الموافق 1935 في أم درمان، وتولى بعد وفاة والده الصديق المهدي عام ١٣٨١هـ الموافق 1961م إمامةَ حركة الأنصارِ وقيادةَ الجَبهةِ القوميَّةِ المتَّحِدة التي كانت بقيادةِ حِزبِ الأمَّةِ. ثم أصبح رئيسًا لحزبِ الأمَّة.جَدُّه الأكبرُ هو محمَّد أحمد المهدي الذي أسَّس الحركةَ المهديَّة في السودان. نال شهادةَ الماجستير في الاقتصادِ مِن جامعةِ أوكسفورد البريطانيَّة عام ١٣٧٧هـ"},{"id":6083,"era":"c15","t":"اعتراف أمريكا بالصحراء الغربية للمغرب. .","s":"أعلن الرئيسُ الأمريكيُّ دونالد ترامب اعترافَ الولاياتِ المتَّحِدة بالسِّيادةِ المغربيَّة على الصَّحراءِ المغربيَّة، وقد انفردت أمريكا بهذا القرارِ ولم توافِقِ الأمَمُ المتَّحِدةُ على هذا القرارِ، وظَلَّت على موقِفِها، كما أنَّ الجزائِرَ وجَبهةَ البوليساريو التي تسعى لاستقلالِ الصَّحراء الغربيَّة رفضتا القرارَ، وكان ثمن اعتراف أمريكا بسيادةِ المغربِ على الصَّحراءِ الغربيَّة هو إعلانَ المغربِ التطبي"},{"id":6084,"era":"c15","t":"المملكة المغربية توقع معاهدة سلام وتطبيع مع دولة الاحتلال إسرائيل .","s":"وقَّعَت المملكةُ المغربيَّةُ اتفاقيَّةَ سلامٍ وتطبيعٍ مع دولةِ الاحتلالِ إسرائيلَ بوساطةٍ أمريكيَّةٍ؛ لتُصبِحَ المغرِبُ سادِسَ دولةٍ عربيَّةٍ تُطَبِّعُ مع إسرائيل بعد مصرَ والأردن والإماراتِ والبحرينِ والسُّودان، وتشمل الاتفاقيَّةُ إقامةَ علاقاتٍ دبلوماسيَّةٍ كاملةٍ بين الدَّولَتينِ."},{"id":6085,"era":"c15","t":"عودة العلاقات بين قطر والدول الأربع (السعودية، والإمارات، والبحرين، ومصر) .","s":"عُقِدَت قِمَّةُ مجلِسِ التعاوُنِ لدُوَلِ الخليجِ العَرَبيَّةِ الواحد والأربعين في محافظةِ العلا في المملكةِ العربيَّةِ السُّعوديَّةِ. وقد سُمِّيَت «قِمَّة السُّلطان قابوس والشَّيخ صباح»؛ لأنَّها أوَّلُ قِمَّة خليجية بعد موتهما.وسمِّيَت أيضًا بقمَّة المُصالحِة الخليجيَّةِ، وفيها تمت المصالحةُ بين المَملكةِ العربيَّة السعوديَّة والإماراتِ العربيَّةِ المتَّحِدة ومملكة البحرينِ مع دولةِ قَطَر بعد خلاف"},{"id":6086,"era":"c15","t":"وفاة الشَّيخ ثناء الله المدني مفتي عموم أهل الحديث في باكستان .","s":"وُلِدَ ثناءُ الله المَدَني في قريةِ (كلس) في إقليم (البنجاب) في (باكستان) سنة 1360هـ، الموافق 1940م.بدأ دراستَه الابتدائيَّةَ في قريتِه، وحَفِظَ القُرآنَ الكريمَ ثمَّ سافر إلى (لاهور) لإتمام دراستِه الجامعيَّة في جامعة أهلِ الحديثِ، وتخرَّج فيها سنة 1381هـ.التحق بالجامعةِ الإسلاميَّة في المدينةِ المنوَّرة، في كليَّة الشَّريعةِ سنة 1383هـ، وتخرَّج فيها سنة 1388هـ، وهو من أوائِلِ المتخرِّجين في الجا"},{"id":6087,"era":"c15","t":"وفاة الدكتور أحمد زكي يماني وزير البترول الأسبق في السعودية .","s":"وُلِدَ الدكتور أحمد زكي يماني في مكَّة المكرَّمة عام 1349هـ الموافق1930م، وحصل على بكالوريوس الحقوق من جامعة القاهرة في عام 1371هـ الموافق 1952م، وأكمل الدِّراساتِ العُليا في جامعتي نيويورك وهارفارد بالولاياتِ المتَّحِدة الأمريكيَّةِ.وفي عام 1382هـ الموافق 1962م، عُيِّن وزيرًا للبترول في المملكة العربية السُّعوديةِ، واستمرَّ في منصبه قرابة 24 عامًا، وكان ممثِّلَ المملكةِ في منظَّمة الدُّوَلِ المصَ"},{"id":6088,"era":"c15","t":"وفاة رئيس الصومال علي مهدي محمد .","s":"علي مهدي محمد الرَّئيسُ الرابعُ للصُّومال ورئيس حزب الصومالي القومي المتَّحِد. انتخبه البرلمانُ الصوماليُّ في جلسته التي انعقدت في جِيبوتي في عام ١٤١١هـ الموافِق 1991م كرئيس للجمهوريةٍ، وذلك في الانتخاباِت التي أُجرِيَت بعد الإطاحةِ بالرَّئيسِ الأسبَقِ محمَّد سياد بري أواخِرَ عام ١٤١٠هـ الموافق 1990م.  وُلِدَ علي مهدي محمد عام ١٣٥٧هـ الموافق 1938م من أسرة صوفيَّة، فوالِدُه أحَدُ متَّبِعي الطريقةِ "},{"id":6089,"era":"c15","t":"وفاة الشَّيخ محمد الصابوني .","s":"وُلِد الشَّيخُ محمَّد علي الصابوني عام 1930 بمدينة حلب، وتعلَّم على يد والِدِه الشَّيخ جميل الصَّابوني أحَدِ عُلَماءِ حَلَب، ودرَس علومَ اللُّغةِ والدِّينِ على يَدِ شُيوخِ المدينةِ؛ مِثلُ محمد سعيد الإدلبي، ومحمد راغب الطبَّاخ. التحق بثانويَّةِ حَلَب الشرعيَّة (الخسروية)؛ حيث درَسَ علومَ التفسير والحديثِ والِفقهِ، والعلومَ الطبيعيَّةَ، وتخرج منها عام ١٣٦٨هـ الموافق 1949م، ثمَّ أكمل دراستَه في الأز"},{"id":6090,"era":"c15","t":"تنصيب محمد بازوم رئيسًا للنيجر .","s":"وُلِد محمد بازوم الذي ينحَدِرُ من قبيلة \"أولاد سليمان\" العربية – وهو من المسلِمين السنة – عام ١٣٨٠هـ الموافق 1960م في منطقة \"ديفا\"، بجنوبِ شَرقِ النيجر.تُمثِّلُ القوميَّةُ التي ينتمي إليها بازوم أقلِّيَّةً في البلاد؛ حيث لا تتعدَّى الواحِدَ في المائة من سُكَّان النيجر، غيرَ أنَّ لها حضورًا قَوِيًّا في ليبيا وتشاد ومالي.حصل على شهادة البكالوريا عام 1979، ثم على درجة الماجستير في الفلسفة السياسيَّة "},{"id":6091,"era":"c15","t":"مقتل إدريس ديبي رئيس تشاد  .","s":"ينتمي إدريس ديبي لقبيلةِ الزغاوة التشادية-السُّودانيَّة. تدرَّب في فرنسا، ورجع إلى تشاد عام ١٣٩٦هـ الموافق 1976م، وعَمِلَ في الجيش، ثم حصل خلافٌ بينه وبين الرَّئيسِ حسين حبري، فترك تشاد واتَّجَه إلى ليبيا ثم السودان، وشَكَّل جبهةَ الإنقاذِ الوَطَنيَّة \"المدعومة من ليبيا والسودان\" وبدأ الهجومَ ضِدَّ حُسَين حبري سنة ١٤٠٩هـ الموافِق 1989م، واستولى على أنجامينا سنة ١٤١٠هـ الموافق 1990م، وأصبح رئيسًا ل"},{"id":6092,"era":"c15","t":"وفاة محمد حسن الأمين (الشيعي)  .","s":"عالمٌ ومُفكِّرٌ شِيعيٌّ لبنانيٌّ، وُلِدَ في بلدة شقرا قضاء بنت جبيل سنة 1316هـ الموافق 1946م، درس الابتدائيَّةَ والمتوسِّطةَ في بلدتِه، ودرس على والِدِه في علومِ اللُّغةِ والنَّحوِ والصَّرفِ والمنطِقِ.هاجر إلى النجف عام ١٣٨٠هـ الموافق 1960م، فدخل كليَّةَ الفِقهِ وتخرَّج منها في العام ١٣٨٧هـ الموافق 1967م، ثم تابع دراساتِه العُليا حتى العام ١٣٩٢هـ الموافق 1972م؛ حيث عاد إلى جبل عامل، وسكن بلدتَه شق"},{"id":6093,"era":"c15","t":"إنشاء مجمع الملك سلمان العالمي للغة العربية .","s":"أُعلِنَ عن إنشاءِ مجمَعِ المَلِكِ سَلْمانَ العالَميِّ للُّغةِ العربيَّةِ، وهو أحدُ المبادراتِ الاستراتيجيَّةِ لوزارةِ الثقافةِ السُّعوديَّةِ، ويَهدِفُ المجمَعُ إلى:1- نشرُ اللُّغةِ العربيَّةِ وحمايتُها.2- تصحيحُ الأخطاءِ الشَّائِعةِ في الألفاظِ والتراكيبِ.3- ترجمةُ الإنتاجاتِ المعرفيَّةِ والعالميَّةِ.4- تعريبُ الألفاظِ والمُصطَلحاتِ الجديدةِ التي لم يَسبِقْ وَضعُ ألفاظٍ ومُصطَلَحاتٍ لها.5- دراسةُ "},{"id":6094,"era":"c15","t":"وفاة الشَّيخ مصطفى مسلم  .","s":"وُلِدَ رحمه الله سنة 1940 ميلاديًّا في عين العرب التابعةِ لمحافظةِ حَلَب في شمالِ سوريا، حصل على بكالوريوس في الشَّريعةِ الإسلاميَّةِ من جامعةِ \"دمشق\" عام ١٣٨٥هـ الموافق 1965م. وماجستير في التفسيرِ وعُلومِ القرآنِ مِن كُلِّيَّة أُصولِ الدِّينِ في جامعة \"الأزهر\" عام ١٣٨٩هـ الموافق 1969م. ثم على الدكتوراه عام ١٣٩٤هـ الموافق 1974م. عَمِلَ أستاذًا في جامعةِ الإمامِ محمَّدِ بنِ سعودٍ الإسلاميَّةِ بالرّ"},{"id":6095,"era":"c15","t":"وفاة وحيد الدين خان .","s":"وُلِدَ رحمه الله سنة ١٣٤٣هـ الموافق 1925م في مدينةِ أعظم كره بالهند وتعلَّم في جامعةِ الإصلاحِ العربيَّةِ الإسلاميَّةِ، ثمَّ انضمَّ إلى لجنةِ التآلُفِ التابعةِ للجماعةِ الإسلاميَّةِ بالهندِ، وعَمِلَ فيها سنواتٍ، ثم شَغِلَ منصبَ رئيسِ تحرير مجلَّة الجمعيَّة الأسبوعيَّة في دلهي عام ١٣٨٧هـ الموافق 1967م لمدة سبع سنوات، وفي سنة ١٣٩٦هـ الموافق 1976م أصدر بمفرَدِه مجلة (الرسالة).له عدَّةُ مُؤَلَّفاتٍ؛ م"},{"id":6096,"era":"c15","t":"اشتباكات بين الفلسطينين والعدو الإسرائلي في القدس واندلاع المواجهة مع حماس .","s":"قام العَدُوُّ الصِّهيونيُّ الغاشِمُ بطَردِ عائلاتٍ فلسطينيَّةٍ مِن حَيِّ الشَّيخ جراح ليستوطِنَه اليهودُ، فاشتبك الفلسطينيونَ مع الشُّرطةِ الإسرائيليَّةِ في مجمعِ المسجِدِ الأقصى في القُدسِ الشَّرقيَّةِ، وطالبت حماس إسرائيلَ بإبعادِ الشُّرطةِ من هناك ومن حي الشَّيخ جراح ولم تستجِبْ؛ فاندلعت الحربُ بينهما وزاد من تأجيجِها التهديدُ بإجلاءِ العائلاتِ الفلسطينيةِ مِن منازلها في القُدسِ الشَّرقيَّةِ مِ"},{"id":6097,"era":"c15","t":"انقلاب عسكري في مالي .","s":"أسَرَ الجيشُ المالي الرَّئيسَ باه نداو، ورئيسَ الوُزَراءِ مختار أواني، ووزيرَ الدِّفاعِ سليمان دوكوري، وأعلن عاصمي غوتا رئيسُ المجلِسِ العسكريِّ الذي قاد الانقلابَ أنَّه تم تجريد نداو وأوان من سلطاتِهما، وأنَّ انتخاباتٍ جديدةً ستُجرَى في عام ١٤٤٣هـ الموافق 2022. وهذا ثالِثُ انقلابٍ في البلاد في عشرِ سنواتٍ، بعد الانقلابِ العَسكريِّ في عامي ١٤٣٣هـ و ١٤٤١هـ الموافق 2012 و2020."},{"id":6098,"era":"c15","t":"قصر حج هذا العام على ستين ألف حاج .","s":"قرَّرَت المملكةُ العَرَبيَّةُ السُّعوديَّةُ قَصْرَ أداءِ مَناسِكِ الحَجِّ لهذا العامِ على المواطنينَ والمقيمينَ داخِلَ المملكةِ بما لا يزيدُ عن 60 ألْفَ حاجٍّ، وذلك في ظِلِّ ما يشهَدُه العالَمُ أجمَعُ -ومنه السُّعوديَّةُ- من جائحةِ فيروس كورونا المستجَدِّ (كوفيد - 19)."},{"id":6099,"era":"c15","t":"إبراهيم رئيسي يفوز بالانتخابات الرئاسية الإيرانية .","s":"وُلِدَ إبراهيم رئيسي في حي نوغان بمدينة مشهد عام ١٣٨٠هـ الموافق 1960 في أسرةٍ شِيعيَّةٍ مُتدَيِّنةٍ.وهو رَجُلُ دِينٍ مُتشَدِّدٌ، وكان قاضيًا مُتَّهَمًا بالتوَرُّطِ في إعداماتٍ ليساريِّينَ. يرفَعُ شِعاراتِ مُكافَحةِ الفَسادِ والفَقرِ، والدِّفاعِ عن الطَّبَقاتِ المُهمَّشةِ، وهو مُقرَّبٌ جِدًّا من القائِدِ الأعلى للثَّورةِ الإيرانيَّةِ علي خامِنئي، وكان أحدَ طُلَّابِه في إحدى المدارِسِ الدينيَّةِ بمد"},{"id":6100,"era":"c15","t":"وفاة العلامة محمد بن إسماعيل العمراني .","s":"وُلِدَ رحمه اللهُ في صنعاءَ القديمةِ سنة 1340هـ ـ الموافق 1921م، توفِّيَ والِدُه وهو في الرابعةِ مِن عُمُرِه، وكفَلَتْه والدتُه، درس على يدِ عَدَدٍ كبيرٍ مِن عُلَماءِ الزَّيديَّةِ وغيرِهم، وكان من أشهَرِ عُلَماءِ اليَمَنِ المعاصِرين، وكان قاضِيَ اليمن ومُفتِيَها لعدَّةِ عُقودٍ، درَّس وهو في سِنٍّ مُبكِّرةٍ لم يتجاوَزِ الخامسةَ والعشرينَ مِن عُمُرِه بعد أن أجازه عددٌ مِن مشايخِه، تأثَّر كثيرًا بالع"},{"id":6101,"era":"c15","t":"وفاة رئيس تشاد الأسبق حسين حبري  .","s":"وُلِد حُسَين حبري عام 1942 في فايا شمالَ تشاد،وكان رئيسًا لتشاد من 1982 إلى 1990. وقبلها كان رئيسًا للوُزراءِ، وهو من قبيلةِ الأنكزةِ؛ إحدى فروعِ قبائِلِ التبو. درس في فرنسا العُلومَ السِّياسيَّةَ، وعاد إلى تشاد سنة 1971. بدأ في الظُّهورِ على السَّاحةِ الدَّوليَّةِ بعدما هاجمت مجموعةٌ تحت قيادتِه بلدةَ بارداي في تبيستي، وأخذت ثلاثةَ أوروبيِّينَ رهائنَ. حكَمَت عليه المحكمةُ الأفريقيَّةُ الخاصَّةُ ف"},{"id":6102,"era":"c15","t":"الجزائر تعلن قطع علاقاتها مع المغرب .","s":"أعلنت الجزائرُ قَطعَ علاقاتِها الدُّبلوماسيَّةِ مع المغربِ، بعد اتهامِها بدَعمِ جماعاتٍ قامت بإشعالِ حرائِقَ في الغاباتِ الضَّخمةِ في الجزائِرِ."},{"id":6103,"era":"c15","t":"وفاة الرئيس الجزائري الأسبق عبد العزيز بوتفليقة  .","s":"وُلِد عبدُ العزيزِ بوتَفْليقة بمدينةَ وَجدةَ المغربيَّةِ عام 1937م، وهو الرَّئيسُ السَّابعُ منذُ الاستقلالِ. عُيِّن عام 2005 رئيسًا لحزبِ جبهةِ التحريرِ الوطنيِّ. التحق عام 1956بعد نهايةِ دراستِه الثَّانويَّةِ بصفوفِ جَيشِ التحريرِ الوطنيِّ الجزائريِّ، وكان عُمُره 19 سنة. وكان أطولَ رُؤساءِ الجزائرِ حُكمًا. أعلن اسقالته عام 2019 بسبب رَفضِ الشَّعبِ الجزائريِّ ترَشُّحَه للرِّئاسةِ لتدَهورِ صِحَّتِه"},{"id":6104,"era":"c15","t":"وفاة وزير الدفاع المصري الأسبق محمد حسين طنطاوي .","s":"وُلِد المشيرُ محمَّد حُسَين طنطاوي، القائِدُ العامُّ السَّابقُ للقوَّاتِ المُسلَّحةِ المِصريَّةِ عام 1935. عَمِل وزيرًا للدِّفاعِ والإنتاجِ الحربيِّ. وكان من أُسرةٍ نوبيَّةٍ. تخرَّج في الكُلِّيَّةِ الحربيَّةِ المصريَّةِ سنة 1956م، ثمَّ كليةِ القادةِ والأركانِ. شارك في حرِب 1967م، وحربِ الاستنزافِ، وحربِ أكتوبر 1973م؛ حيث كان قائِدَ وحدةِ مُقاتلةٍ بسلاحِ المُشاةِ. وبعد الحربِ حصل على نُوطِ الشَّجاع"},{"id":6105,"era":"c15","t":"وفاة الرئيس الجزائري السابق عبد القادر بن صالح .","s":"وُلِد عبدُ القادِرِ بنُ صالح عام 1941 بفلاوسِن بولايةِ تِلْمِسان. في سنة 1959،التحق بصُفوفِ جَيشِ التَّحريرِ الوطنيِّ انطلاقًا من المغربِ، ولم يبلُغْ بَعْدُ سِنَّ الثامنةَ عَشرةَ.شَغلَ منصِبَ الرَّئيسِ المؤقَّتِ للجمهوريَّةِ الجزائريَّةِ عام 2019 لبضعةِ أشهُرٍ بعد أن أُعلِنَ رسميًّا شُغورُ منصِبِ رئيسِ الجُمهوريَّةِ إثرَ استقالةِ عبدِ العزيزِ بوتَفليقة. توُفِّيَ عبدُ القادِرِ بنُ صالحٍ عن عمرٍ ناه"},{"id":6106,"era":"c15","t":"وفاة كرم زهدي، عضو مجلس شورى الجماعة الإسلامية في مصر. .","s":"وُلِد كرم محمَّد زُهدي في المنيا عام 1952م، وكان عضوًا سابقًا في مجلِسِ شُورى الجماعةِ الإسلاميَّةِ في مصرَ، سُجِنَ منذُ اغتيالِ الرَّئيسِ المصريِّالأسبَقِ أنور السَّادات عام 1981، وقضى في السِّجنِ 22 عامًا. تَرَك رئاسةَ مجلس شورى الجماعةِ الإسلاميَّةِ بعدَ ثورةِ 25 يناير، وأصبح من أعضائِه فقط. قاد كرم زُهدي عمليَّةَ مُراجعاتِ السُّجونِ للتخَلِّي عن حملِ السِّلاحِ والصِّراعِ مع الدَّولةِ. وقدَّم ا"},{"id":6107,"era":"c15","t":"وفاة الأديب السعودي عبد الله بن إدريس .","s":"وُلِد عبدُ اللهِ بنُ إدريسَ عام 1348هـ (1929 - 6 أكتوبر 2021)، في بلدة (حرْمَة) شمالَ مدينةِ الرِّياضِ، وهو أديبٌ وشاعرٌ سعوديٌّ، وكان رئيسًا لنادي الرِّياضِ الأدبيِّ، وعُضوًا في عدَدٍ من المؤسَّساتِ والهيئاتِ الثَّقافيَّةِ؛ كدارةِ المَلِكِ عبدِ العزيزِ،ورابطةِ الأدَبِ الحديثِ في مصرَ، وعُضوَ شَرَفٍ في رابطةِ الأدَبِ الإسلاميِّ العالَميَّةِ، إلى جانِبِ المناصِبِ التي شغلها في جامعةِ الإمامِ محمَّد"},{"id":6108,"era":"c15","t":"نجلاء بودن رمضان أول رئيسة حكومة في تونس  .","s":"وُلِدَت عامَ 1958 في القيروانَ، بتونُسَ، وهي مهندسةٌ ودكتورةٌ متخَصِّصةٌ في علومِ الجُيُولوجيا، وسياسيَّةٌ تونُسيَّةٌ. عَمِلت في وَزارةِ التربيةِ عام 2011.وأصبحت مديرةً عامَّةً للجودةِ في وزارةِ التعليمِ العالي والبَحثِ العِلميِّ، ثمَّ في عام 2015 شَغلَت منصِبَ مُديرِ المشروعِ في مكتَبِ الوزيرِ سليم شورى. ثمَّ شَغلَت منصِبَ رئيسِ وَحدةِ الإدارةِ حَسَبَ الأهدافِ لتنفيذِ مشروعِ إصلاحِ التَّعليمِ الع"},{"id":6109,"era":"c15","t":"وقوع انقلاب عسكري في السودان  .","s":"قام الجيشُ السُّودانيُّ بانقلابٍ ضِدَّ الحكومةِ المَدَنيَّةِ. وأعلن عبدُ الفتَّاحِ البرهانُ حَلَّ مجلِسِ السِّيادةِ، وفَرْضَ حالةِ الطوارئِ، وإعفاءَ مُعظَمِ وُزراءِ حُكومةِ حمدوك، وكذلك إعفاءُ حُكَّامِ الولاياتِ، وجرى اعتقالُ عدَدٍ كبيرٍ من المؤيِّدينَ للحُكومةِ. دعا تجمُّعُ المهنيِّينَ السُّودانيِّينَ وقوى الحُريَّةِ والتغييرِ إلى العِصيانِ المَدَنيِّ، ورَفضِ التعاوُنِ مع مُنَظِّمي الانقلابِ. أعل"},{"id":6110,"era":"c15","t":"وفاة الشيخ صالح اللحيدان .","s":"وُلِد الشَّيخُ صالح بمدينةِ البَكيريَّةِ بمِنطَقةِ القصيمِ عام 1350 هـ، تخرَّج في كليَّةِ الشَّريعةِ بالرِّياضِ عام 1379هـ، وعَمِل بعدَ تخرُّجِه سكرتيرًا وملازِمًا قضائيًّا لمفتي الدِّيارِ السُّعوديَّةِ السَّابقِ الشَّيخِ محمَّدِ بنِ إبراهيمَ آل الشَّيخِ، ثمَّ مُساعًدا لرئيسِ المحكمةِ الكُبرى في الرِّياضِ، ثمَّ صار رئيسًا للمَحكَمةِ عام 1384هـ، حصل على رسالةِ الماجستيرِ مِن المعهدِ العالي للقَضاءِ"},{"id":6111,"era":"c15","t":"وفاة المؤرخ العراقي عبد الرحمن علي الحجي .","s":"وُلِدَ الحجِّي في المقداديَّةِ إحدى مُدُنِ محافظةِ ديالى عام 1935م،وهو مؤرِّخٌ عراقيٌّ وأستاذُ التاريخِ الإسلاميِّ والأندلُسيِّ وحضارتِه في العديدِ من الجامعاتِ، وأحَدَ مُؤَسِّسي جامعةِ الإماراتِ العربيَّةِ المتَّحِدةِ، وعميدٌ أسبقُ لكليَّةِ العلومِ الإنسانيَّةِ بها.حصَل على دكتوراه في العَلاقاتِ الدُّبلوماسيَّةِ الأندَلُسيَّةِ مع أوروبَّا الغربيَّةِ من جامعةِ كامْبِريدج في بريطانيا عام 1966. نال "},{"id":6112,"era":"c15","t":"وقوع انقلاب عسكري في بوركينا فاسو .","s":"اعتُقِل الرَّئيسُ رُوش مارْك كريستيان كابوري من قِبَلِ جُنودٍ مُتمرِّدينَ في المُعسكَرِ العَسكريِّ بالعاصمةِ، وأعلن الجيشُ على شاشةِ التلفزيونِ أنَّ كابوري قد عُزِل من الرِّئاسةِ. وبعد الإعلانِ أعلن الجيشُ حَلَّ البرلمانِ والحكومةِ، ووَقْفَ الدُّستورِ، ثمَّ أعيدَ الدُّستورُ، وعُيِّنَ قائِدُ الانقلابِ المُقَدَّمُ بول هنري سانوغو داميبا رئيسًا مؤقَّتًا"},{"id":6113,"era":"c15","t":"محاولة انقلابية فاشلة في غينيا بيساو. .","s":"قام مجموعةٌ من العَسكريِّينَ في الجيشِ بمحاولةِ انقلابٍ من خلالِ محاصرةِ مَقَرِّ الحكومةِ في العاصمةِ بيساو لاعتقالِ الرَّئيسِ عُمَر سيسوكو إمبالو، ولكن فَشِلَت المحاولةُ، ونجا الرَّئيسُ ومَن معه"},{"id":6114,"era":"c15","t":"وفاة الشيخ يعقوب الباحسين .","s":"وُلِد الشَّيخُ يعقوبُ الباحسين التميميُّ سنةَ 1347هـ، في الزبيرِ، وتلقَّى تعليمَه في مدينةِ البصرةِ، ثمَّ أنهى الدكتوراه في الفقهِ من جامعةِ الأزهَرِ، وزاول التدريسَ في جامعةِ البصرةِ، ثمَّ انتقل إلى السُّعوديَّةِ ودرَّس في جامعةِ الإمامِ محمَّدِ بنِ سُعودٍ الإسلاميَّةِ، وكان عُضوَ هيئةِ كِبارِ العُلَماءِ في المملكةِ العربيَّةِ السُّعوديَّةِ، وأستاذًا بالمعهدِ العالي للقضاءِ.لديه العديدُ من المؤلّ"},{"id":6115,"era":"c15","t":"صدور أمر ملكي سعودي لذكرى يوم التأسيس للدولة السعودية .","s":"أصدَر َالملِكُ سَلْمانُ بنُ عبدِ العزيزِ أمرًا مَلَكيًّا بتحديدِ يومِ 22 فبراير من كُلِّ عامٍ يومًا لذكرى تأسيسِ الدَّولةِ السُّعوديَّةِ، باسمِ \"يوم التَّأسيس\"، ويصبِحُ إجازةً رسميَّةً في البلادِ.والمقصودُ بالتأسيسِ بدايةُ تأسيسِ الإمامِ محمَّدِ بنِ سُعودٍ قَبلَ ثلاثةِ قُرونٍ -مُنتصَفَ عام 1139هـ، الموافِق شَهْرَ فبراير من عامِ 1727م- للدَّولةِ السُّعوديَّةِ الأُولى."},{"id":6116,"era":"c15","t":"مقتل أبي إبراهيم محمد المولى، الخليفة الثاني لتنظيم (داعش) .","s":"وُلِد أبو إبراهيمَ محمَّد سعيد عبد الرحمن المولى الصلبي عام 1396هـ،وهو الخليفةُ الثَّاني لتنظيمِ الدَّولةِ الإسلاميَّةِ (داعش)، بويعَ بَعدَ مَقتَلِ أبي بكرٍ البغداديِّ عام 1440هـ.كان مَقتَلُه على يدِ جُنودٍ أمريكانَ قاموا بإنزالٍ جوِّيٍّ من مَروحيَّاتٍ أمريكيَّةٍ في إدلِب بسُوريا، حاصرت المنزِلَ الذي فيه أبو إبراهيمَ ومَن معه، واشتبكت معهم، ثم غادرت قواتُ الإنزالِ بعد إتمامِ المُهِمَّةِ، ثمَّ جاءت"},{"id":6117,"era":"c15","t":"نقل صلاحيات الرئيس اليمني هادي إلى مجلس القيادة الرئاسي .","s":"أعلَنَ الرَّئيسُ اليَمَنيُّ عبد ربه منصور هاديقرارًا بتشكيلِ مجلِسِ قيادةٍ رئاسيٍّ، ونَقلِ جميعِ صلاحيَّاتِه إليه لاستكمالِ تنفيذِ مهامِّ المرحلةِ الانتقاليَّةِ، وأعفى نائبَه علي محسن الأحمر من منصِبِه.وعُيِّن رشاد محمَّد العليمي رئيسًا للمجلِسِ مع سبعةِ أعضاءٍ، ووَفْقَ القرارِ سيُديرُ مجلِسُ القيادةِ الرِّئاسيُّ الدَّولةَ سياسيًّا وعسكريًّا وأمنيًّا طَوالَ المرحلةِ الانتقاليَّةِ.ويشمَلُ القرارُ ت"},{"id":6118,"era":"c15","t":"سحب الثقة من رئيس وزراء باكستان عمران خان .","s":"أطاح البرلمانُ الباكستانيُّ برئيسِ الوُزراءِ عمران خان من السُّلطةِ من خلالِ التصويتِ على حَجبِ الثِّقةِ عن حكومتِه، وأيَّدَت المحكمةُ العُليا حَجْبَ الثِّقةِ عنه، وأصبح خان أوَّلَ رئيسِ وُزراءَ باكستانيٍّ يُطاحُ به من خلالِ تصويتٍ لحَجبِ الثِّقةِ عنه في البرلمانِ."},{"id":6119,"era":"c15","t":"انتخاب شهباز شريف رئيسًا للوزراء خلَفًا لعمران خان  .","s":"انتَخَب النُّوَّابُ الباكستانيُّونَ ميان محمد شهباز شريف رئيسًا جديدًا للوزراءِ بعدما أُطيحَ بسَلَفِه عمران خان وحُجِبَت عنه الثِّقةُ.ثمَّ شَكَّل شريف حكومةً من حِزبِه \"الرَّابطة الإسلاميَّة الباكستانيَّة\" و\"حزبِ الشَّعْبِ الباكستانيِّ\" و\"جمعيَّةِ عُلَماءِ الإسلامِ\"."},{"id":6120,"era":"c15","t":"قوات الاحتلال الإسرائيلية تقتحم المسجد الأقصى  .","s":"اقتَحَمت قوَّاتُ الاحتلالِ الإسرائيليِّ المسجِدَ الأقصى، وتسلَّقَ عددٌ من جنودِ الاحتلالِ أسطُحَ المباني المحيطةِ بالمسجِدِ الأقصى، وأخلَوْا ساحةَ المسجِدِ، وأغلقوا مُعظَمَ الأبوابِ المؤدِّيةِ إليه.وكان وراءَ هذا الاقتحامِ عدَّةُ مُنظَّماتٍ دينيَّةٍ يهوديَّةٍ متطرِّفةٍ أعلنت أنَّها ستقيمُ شعائِرَ دينيَّةً في باحةِ المسجِدِ الأقصى بمناسَبةِ عيدِ الفصحِ اليهوديِّ. ولكِنْ تصدَّى لهم الفِلَسطينيُّونَ،"},{"id":6121,"era":"c15","t":"وفاة رئيس دولة الإمارات العربية المتحدة الشيخ خليفة بن زايد آل نهيان  .","s":"وُلِد الشَّيخُ خليفة عام 1948م في مدينةِ العَينِ،وهو ثاني رئيسٍ لدولةِ الإماراتِ العربيَّةِ المتَّحِدةِ، والحاكِمُ السَّادِسَ عَشَرَ لإمارةِ أبوظبي، أصبح رئيسًا للإماراتِ عام 2004 خلَفًا لوالِدِه الشَّيخِ زايدِ بنِ سُلطانَ مُؤَسِّسِ دولةِ الإماراتِ العربيَّةِ المتَّحِدة، وتولَّى رئاسةَ الدَّولةِ حتَّى وفاتِه.وُلِد الشَّيخُ خليفة بقلعة (قصر) المويجعي في مدينةِ العَينِ، وكان أكبَرَ الأبناءِ الذُّكور"},{"id":6122,"era":"c15","t":"انتخاب الشيخ محمد بن زايد آل نهيان رئيسًا لدولة الإمارات العربية المتحدة  .","s":"انتَخَب المجلِسُ الأعلى لاتحادِ الإماراتِ بالإجماعِ الشَّيخَ محمَّدَ بنَ زايدٍ رئيسًا لدَّولةِ الإماراتِ العربيَّةِ المتَّحدةِ بعد وفاةِ أخيه خليفةَ بنِ زايدٍ؛ ليُصبِحَ الرَّئيسَ الثَّالِثَ لدولةِ الإماراتِ العربيَّةِ المتَّحِدةِ منذُ قيامِ الاتحادِ سنة 1971م، وبصِفتِه وَليَّ عهدِ إمارةِ أبوظبي فقد تولَّى أيضًا حُكمَ الإمارةِ؛ ليُصبحَ بذلك الحاكِمَ السَّابِعَ عَشَرَ لإمارةِ أبوظبي من أُسرةِ آل نَه"},{"id":6123,"era":"c15","t":"انتخاب حسن شيخ محمود رئيسًا للصومال  .","s":"وُلِد حَسَن شيخ محمود عام 1955م،وهو من قبيلة هوية. انتخبه البرلمانُ الصُّوماليُّ رئيسًا جديدًا للصُّومالِ خَلَفًا للرَّئيسِ محمَّد عبد الله محمَّد،وبهذا يكونُ رئيسَ الصُّومالِ العاشِرَ، وكان رئيسَ حِزبِ السَّلامِ والتنميةِ."},{"id":6124,"era":"c15","t":"وفاة الداعية الكويتي أحمد القطان .","s":"هو أحمدُ بنُ عبدِ العزيزِ بنِ أحمدَ القَطَّانِ التميميُّ، وُلِدَعام 1365هـ في مدينةِ الكويت، ودرس فيها وتخرَّج من معهَدِ المعَلِّمينَ عامَ1389هـ.كان من أبرَزِ وأشهَرِ خُطَباءِ المنابِرِ في الثَّمانينيَّاتِ وبدايةِ التِّسعينيَّاتِ الميلاديَّةِ.تعرَّضَ لوَعْكةْ صِحِّيةٍ مُفاجِئةٍ أُدخِلَ على إثْرِها العنايةَ المركَّزةَ في مستشفى جابر الأحمد، وتوفِّيَ رحمه الله خلالَ ساعاتٍ، عن عمرٍ ناهز 76 عامًا."},{"id":6125,"era":"c15","t":"وفاة الأديب الرحالة محمد ناصر العبودي .","s":"وُلِد الشَّيخُ محمَّدُ بنُ ناصرٍ العبوديُّ عام 1345هـ في مدينةِ بُرَيدة بمِنطقةِ القَصيمِ بالمملكةِ العربيَّةِ السُّعوديَّةِ، وتلقَّى تعليمَه الأوَّليَّ فيها على يَدِ عَدَدٍ من العُلَماءِ، ثمَّ عَمِل مُدَرِّسًا ثمَّ مديرًا للمعهدِ العِلميِّ في بُرَيدةَ، ثمَّ أصبح الأمينَ العامَّ للجامعةِ الإسلاميَّةِ بالمدينةِ المنوَّرةِ لثلاثةَ عَشَرَ عامًا، ثمَّ أصبح وكيلًا للجامعةِ ثمَّ مديرًا لها، ثمَّ شَغِل م"},{"id":6126,"era":"c15","t":"وفاة أبي الحسن بني صدر أول رئيس للجمهورية الإسلامية الإيرانية  .","s":"وُلِد أبو الحسَنِ بني صدْر في مقاطعةِ همدانَ في إيرانَ، وكان والِدُه نصر الله شيعيًّا اثنَيْ عَشريًّا من الملالي النافذينَ في همدانَ، والذي كانت تربطُه صداقةٌ مع الخُميني. تولَّى أبو الحسَنِ بني صدر مؤقَّتًا منصِبَ وزيرِ الشُّؤونِ الخارجيَّةِ في إيران عام 1979م،وكان أوَّلَ رئيسٍ لإيرانَ بعدَ الثَّورةِ الإيرانيَّةِ سنة 1979، التي انتصَرَت وأنهت الحُكمَ الملكيَّ.تولَّى رئاسةَ الجُمهوريَّةِ الإيرانيّ"},{"id":6127,"era":"c15","t":"حركة طالبان تستعيد السيطرة على أفغانستان .","s":"أدَّى انسحابُ القُوَّاتِ الأمريكيَّةِ من أفغانستانَ بعد ما يقرُبُ من عشرينَ عامًا على الإطاحةِ بحَرَكةِ طالبانَ،إلى سيطرةِ الحَركةِ من جديدٍ على أفغانستانَ، وعَيَّنت الحَركةُ محمَّد حسن أخوند زاده رئيسًا لحكومةِ أفغانستانَ، وألقى أوَّلَ خطابٍ له عَبْرَ التِّلفزيون الأفغانيِّ الرَّسميِّ."},{"id":6128,"era":"c15","t":"وفاة أبي بكر المشهور العدني .","s":"وُلِد أبو بكرٍ عام 1366هـ بمدينةِ أحور بمحافظةِ أَبْيَن في اليَمَنِ الجَنوبيِّ، ونشأ في كَنَفِ والِدِه علي بنِ أبي بكر، تلقَّى دراستَه الابتدائيَّةَ في مدينَتَي أحور والمحفد، وتلقَّى دراستَه الثَّانويَّةَ في مدينةِ عَدَن. وتخرَّج في جامعةِ عَدَنٍ من كليَّةِ التربيةِ قِسمِ اللُّغةِ العربيَّةِ، والتَحَق بسِلكِ التَّربيةِ والتَّعليمِ، ودرَّس في مدارِسِ أحور وعَدَن بَعدَ تخرُّجِه من الجامعةِ.كان العَد"}]
